sh_int get_txtclr( CHAR_DATA* ch )
{
    if ( !ch )
        return 0;

    return ch->disguise ? ch->disguise->txtclr : ch->txtclr;
}

void set_txtclr( CHAR_DATA* ch, sh_int txtclr )
{
    if ( !ch )
        return;

    if ( ch->disguise )
        ch->disguise->txtclr = txtclr;
    else
        ch->txtclr = txtclr;

    save_char_obj( ch, TRUE );    
    return;
}

