void sound_to_char( CHAR_DATA* vic, char* argument )
{
    if ( vic == NULL || NULLSTR( argument ) )
        return;

    if ( IS_NPC( vic ) || !has_pcflag( vic, PCFLAG_SOUND ) )
        return;

    DESCRIPTOR_DATA* apDescriptor = vic->desc;

    if ( !apDescriptor )
        return;

    protocol_t* pProtocol = apDescriptor ? apDescriptor->pProtocol : NULL;

    if ( pProtocol == NULL )
        return;

    // If they've enabled MSP (or MDSP sound? Not entirely sure what that means) send special IAC codes for it.
    // Otherwise, send plaintext !!SOUND(filename) so a client can set up triggers for it.
    if ( pProtocol->bMSP || pProtocol->pVariables[eMSDP_SOUND]->ValueInt )
        ch_printf( vic, "%c%c%c!!SOUND(%s)%c%c", IAC, SB, TELOPT_MSP, argument, IAC, SE );
    else
        ch_println( vic, "!!SOUND(%s)", argument );
}

/**
    Sends a message to all player characters in a room that have CONF +SOUND.
    @param room Room to send message to
    @param argument Message to send
*/
void sound_to_room( ROOM_INDEX_DATA* room, char* argument )
{
    CHAR_DATA* vic;

    if ( room == NULL )
        return;

    for ( vic = room->first_person; vic; vic = vic->next_in_room )
        sound_to_char( vic, argument );
}

/**
    Check whether the player is OOC-limited and, if not, subtract the given amount of limit from them.
    Any appropriate messages when limited will be sent by this rather than the caller.
    @return true if they are limited, false if the OOC message can continue
*/
bool ooc_break_check( CHAR_DATA* ch, int limit_used )
{
    if ( !IS_NPC( ch ) && !IS_RPC( ch ) )
    {
        if ( ch->pcdata->oocbreak )
        {
            ch_println( ch, "&RYour OOC channels are still on cooldown." );
            return true;
        }

        if ( ch->pcdata->ooclimit <= 0 )
        {
            ch->pcdata->oocbreak = TRUE;
            ch_println( ch, "&ROOC limit reached - OOC disabled for a short time." );
            return true;
        }

        ch->pcdata->ooclimit -= limit_used;
    }

    return false;
}

/**
    BEEP Command
    Allows a player to 'beep' another player with a sound and message.
    - Cannot be used in silent rooms
    - Cannot use with 'silenced' or 'no tell' flags
    @param ch Character using the command
    @param argument Arguments being passed
    @author Ghost
*/
CMDF do_beep( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    char arg[MSL];
    char buf[MSL];

    if ( IS_NPC( ch ) )
    {
        send_to_char( "What sense would that make?", ch );
        return;
    }

    argument = one_argument( argument, arg );
    strlcpy( buf, argument, MSL );
    xREMOVE_BIT( ch->deaf, CHANNEL_TELLS );

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch ) )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( is_silenced( ch ) || has_pcflag( ch, PCFLAG_NO_TELL ) )
    {
        ch_println( ch, "You can't do that." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Beep who?" );
        return;
    }

    if ( ooc_break_check( ch, 2 ) )
        return;

    if ( strlen( argument ) > 254 && get_trust( ch ) < sysdata.log_level )
    {
        argument[254] = '\0';
        ch_println( ch, "&WLine too long. Please cut down the spam." );
    }

    if ( arg[0] == '@' )
    {
        ACCOUNT_DATA* acc = NULL;
        DESCRIPTOR_DATA* d = NULL;

        if ( ( acc = get_account( arg + 1 ) ) == NULL )
        {
            ch_println( ch, "There is no account by that name." );
            return;
        }

        for ( d = first_descriptor; d; d = d->next )
        {
            if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                continue;

            if ( !d->account || d->account != acc )
                continue;

            victim = d->character;
        }
    }

    if ( !victim )
        victim = get_char_world_full( ch, arg );

    if ( victim == NULL )
    {
        arg[0] = toupper( arg[0] );
        ch_printf( ch, "&R(%s) You beep %s: %s\n\a", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg, argument );
        return;
    }

    if ( !IS_NPC( victim ) && ( victim->switched )
            && ( get_trust( ch ) > LEVEL_AVATAR ) )
    {
        ch_println( ch, "That player is switched." );
        return;
    }
    else if ( !IS_NPC( victim ) && ( !victim->desc ) )
    {
        ch_println( ch, "That player is link-dead." );
        return;
    }

    if ( xIS_SET( victim->deaf, CHANNEL_TELLS )
            && ( !IS_RPC( ch ) || ( get_trust( ch ) < get_trust( victim ) ) ) )
    {
        act( AT_PLAIN, "$E has $S tells turned off.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( is_silenced( victim ) )
    {
        ch_println( ch, "That player is silenced.  They will receive your message but can not respond." );
    }

    if ( ( !IS_RPC( ch ) && !IS_AWAKE( victim ) )
            || is_silenced( victim ) )
    {
        act( AT_PLAIN, "$E can't hear you.", ch, 0, victim, TO_CHAR );
        return;
    }

    if ( victim->desc       /* make sure desc exists first  -Thoric */
            &&   victim->desc->connected == CON_EDITING
            &&   get_trust( ch ) < LEVEL_GOD )
    {
        act( AT_PLAIN, "$E is currently in a writing buffer.  Please try again in a few minutes.", ch, 0, victim, TO_CHAR );
        return;
    }

    arg[0] = toupper( arg[0] );
    ch_printf( ch, "&R(%s) You beep %s: %s\n\a", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg, argument );
    send_to_char( "\a", victim );
    snprintf( buf, MSL, "&R(%s) %s beeps: '%s'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name, argument );
    act( AT_RED, buf, ch, argument, victim, TO_VICT );
    return;
}

/**
    Text scrambler
    @param argument String to scramble
    @param modifier How scrambled the string should be
    @param langs What language the text is being scrambled into
    @return Scrambled string
    @author Altrag
*/
char* scramble_text( const char* argument, EXT_BV langs )
{
    static char arg[MIL];
    strlcpy( arg, "", MIL );
    sh_int position = 0;
    sh_int conversion = 0;

    if ( xIS_SET( langs, LANG_YUBYUB ) )
    {
        position = number_range( 1, 4 );

        for ( int i = 0; i < position; i++ )
        {
            if ( number_range( 0, 1 ) == 1 )
                strlcat( arg, "yub ", MIL );
            else
                strlcat( arg, "nub ", MIL );
        }

        arg[strlen( arg ) - 1] = 0; // this is the null character, this is why this works
        return arg;
    }

    int modifier = number_range( 1000, 32000 );
    modifier %= number_range( 80, 300 ); /* Bitvectors get way too large #s */

    for ( position = 0; position < MIL; position++ )
    {
        if ( argument[position] == '\0' )
        {
            arg[position] = '\0';
            return arg;
        }
        else if ( argument[position] == '&' )
        {
            // Skip formatting tokens
            arg[position] = argument[position];
            position++;
            arg[position] = argument[position];
            continue;
        }
        else if ( argument[position] >= 'A' && argument[position] <= 'Z' )
        {
            if ( xIS_SET( langs, LANG_BINARY ) )
            {
                if ( number_range( 0, 1 ) == 0 )
                    arg[position] = '0';
                else
                    arg[position] = '1';
            }
            else
            {
                conversion = -conversion + position - modifier + argument[position] - 'A';
                conversion = number_range( conversion - 5, conversion + 5 );

                while ( conversion > 25 )
                    conversion -= 26;

                while ( conversion < 0 )
                    conversion += 26;

                arg[position] = conversion + 'A';
            }
        }
        else if ( argument[position] >= 'a' && argument[position] <= 'z' )
        {
            if ( xIS_SET( langs, LANG_BINARY ) )
            {
                if ( number_range( 0, 1 ) == 0 )
                    arg[position] = '0';
                else
                    arg[position] = '1';
            }
            else
            {
                conversion = -conversion + position - modifier + argument[position] - 'a';
                conversion = number_range( conversion - 5, conversion + 5 );

                while ( conversion > 25 )
                    conversion -= 26;

                while ( conversion < 0 )
                    conversion += 26;

                arg[position] = conversion + 'a';
            }
        }
        else if ( argument[position] >= '0' && argument[position] <= '9' )
        {
            if ( xIS_SET( langs, LANG_BINARY ) )
            {
                if ( number_range( 0, 1 ) == 0 )
                    arg[position] = '0';
                else
                    arg[position] = '1';
            }
            else
            {
                conversion = -conversion + position - modifier + argument[position] - '0';
                conversion = number_range( conversion - 2, conversion + 2 );

                while ( conversion > 9 )
                    conversion -= 10;

                while ( conversion < 0 )
                    conversion += 10;

                arg[position] = conversion + '0';
            }
        }
        else
            arg[position] = argument[position];
    }

    arg[position] = '\0';
    return arg;
}

/**
    Drunk speech processor
    @param argument Speech to scramble
    @param ch Character speaking
    @return Scrambled speech
*/
char* drunk_speech( const char* argument, CHAR_DATA* ch )
{
    const char* arg = argument;
    static char buf[MIL * 2];
    char buf1[MIL * 2];
    sh_int drunk;
    char* txt;
    char* txt1;

    if ( IS_NPC( ch ) || !ch->pcdata )
        return ( char* ) argument;

    drunk = ch->pcdata->condition[COND_DRUNK];

    if ( drunk <= 0 )
        return ( char* ) argument;

    buf[0] = '\0';
    buf1[0] = '\0';

    if ( !argument )
    {
        bug( "Drunk_speech: NULL argument", 0 );
        return "";
    }

    txt = buf;
    txt1 = buf1;

    while ( *arg != '\0' )
    {
        if ( *arg == '&' )
        {
            // Preserve the letter after a format token
            *txt++ = *arg;
            arg++;

            if ( *arg != '\0' )
            {
                *txt++ = *arg;
                arg++;
            }

            continue;
        }
        else if ( toupper( *arg ) == 'T' )
        {
            if ( number_percent() < ( drunk * 2 ) )     /* add 'h' after a 'T' */
            {
                *txt++ = *arg;
                *txt++ = 'h';
            }
            else
                *txt++ = *arg;
        }
        else if ( toupper( *arg ) == 'X' )
        {
            if ( number_percent() < ( drunk * 2 / 2 ) )
            {
                *txt++ = 'c', *txt++ = 's', *txt++ = 'h';
            }
            else
                *txt++ = *arg;
        }
        else if ( number_percent() < ( drunk * 2 / 4 ) )  /* slurred letters */
        {
            sh_int slurn = number_range( 1, 2 );
            sh_int currslur = 0;

            while ( currslur < slurn )
                *txt++ = *arg, currslur++;
        }
        else
            *txt++ = *arg;

        arg++;
    };

    *txt = '\0';

    txt = buf;

    while ( *txt != '\0' )   /* Let's mess with the string's caps */
    {
        if ( *txt == '&' )
        {
            // Preserve the letter after a format token
            *txt1 = *txt;
            txt1++, txt++;

            if ( *txt != '\0' )
            {
                *txt1 = *txt;
                txt1++, txt++;
            }

            continue;
        }
        else if ( number_percent() < ( 2 * drunk / 2.5 ) )
        {
            if ( isupper( *txt ) )
                *txt1 = tolower( *txt );
            else if ( islower( *txt ) )
                *txt1 = toupper( *txt );
            else
                *txt1 = *txt;
        }
        else
            *txt1 = *txt;

        txt1++, txt++;
    };

    *txt1 = '\0';

    txt1 = buf1;

    txt = buf;

    while ( *txt1 != '\0' )   /* Let's make them stutter */
    {
        if ( *txt1 == ' ' )  /* If there's a space, then there's gotta be a */
        {
            /* along there somewhere soon */
            while ( *txt1 == ' ' )  /* Don't stutter on spaces */
                *txt++ = *txt1++;

            if ( ( number_percent() < ( 2 * drunk / 4 ) ) && *txt1 != '\0' )
            {
                sh_int offset = number_range( 0, 2 );
                sh_int pos = 0;

                // Go past the initial copy of the offset
                while ( *txt1 != '\0' && pos < offset )
                {
                    // Go past any formatting codes and don't count them in the offset
                    if ( *txt1 == '&' )
                    {
                        *txt++ = *txt1++;

                        if ( *txt1 != '\0' )
                            *txt++ = *txt1++;
                    }
                    else
                    {
                        *txt++ = *txt1++, pos++;
                    }
                }

                if ( *txt1 == ' ' )  /* Make sure not to stutter a space after */
                {
                    /* the initial offset into the word */
                    *txt++ = *txt1++;
                    continue;
                }

                pos = 0;
                offset = number_range( 2, 4 );

                while ( *txt1 != '\0' && pos < offset )
                {
                    // Go past any formatting codes and don't count them in the offset
                    if ( *txt1 == '&' )
                    {
                        *txt++ = *txt1++;

                        if ( *txt1 != '\0' )
                            *txt++ = *txt1++;
                    }

                    *txt++ = *txt1;
                    pos++;

                    if ( *txt1 == ' ' || pos == offset )  /* Make sure we don't stick */
                    {
                        /* A hyphen right before a space    */
                        txt1--;
                        break;
                    }

                    *txt++ = '-';
                }

                if ( *txt1 != '\0' )
                    txt1++;
            }
        }
        else
            *txt++ = *txt1++;
    }

    *txt = '\0';
    return buf;
}


/**
    Profanity Filter  -Ghost [with help from LoKust]
    @param txt String to filter
    @author Ghost
*/
void profanity_filter(char* txt)
{
    char *nbuf, *tbuf, *p;
    bool change = TRUE;
    unsigned int x, v;
    size_t txt_len = strlen(txt);

    nbuf = malloc( txt_len + 1 );
    tbuf = malloc( txt_len + 1) ;

    if ( !nbuf || !tbuf ) // Check for allocation failure
    {
        bug( "%s: allocation failure", FUNC );
        if ( nbuf ) free( nbuf );
        if ( tbuf ) free( tbuf );
        return;
    }

    strlcpy( nbuf, strlower(txt), txt_len + 1 );
    strlcpy( tbuf, txt, txt_len + 1 );

    while ( change )
    {
        change = FALSE;

        for ( x = 0; strcmp( ignore_table[x], "$" ) != 0; x++ )
        {
            if ( ( p = strstr(nbuf, ignore_table[x] ) ) != NULL )
            {
                change = TRUE;

                for ( v = 0; v < strlen( ignore_table[x] ); v++ )
                    *(p + v) = '.';
            }
        }
    }

    change = TRUE;

    while ( change )
    {
        change = FALSE;

        for ( x = 0; strcmp(curse_table[x], "$") != 0; x++ )
        {
            if ( ( p = strstr( nbuf, curse_table[x] ) ) != NULL )
            {
                change = TRUE;

                for ( v = 0; v < strlen(curse_table[x]); v++ )
                    *(p + v) = '*';
            }
        }
    }

    /*
        Clone *'s over to the real string
    */
    for ( x = 0; x < txt_len; x++ )
        if ( nbuf[x] == '*' )
            tbuf[x] = '*';

    strlcpy( txt, tbuf, txt_len + 1 );
    free( nbuf );
    free( tbuf );
    return;
}

/**
    Profanity check
    @param arg String to check for profanity
    @return TRUE if arg has profanity, FALSE if it does not
*/
bool profanity_check( char* arg )
{
    char* nbuf, *p;
    bool change = TRUE;
    unsigned int x, v;
    nbuf = ( char* )malloc( strlen( arg ) + 1 );
    strlcpy( nbuf, strlower( arg ), strlen( arg ) + 1 );

    while ( change )
    {
        change = FALSE;

        for ( x = 0; strcmp( ignore_table[x], "$" ); x++ )
        {
            if ( ( p = strstr( nbuf, ignore_table[x] ) ) )
            {
                change = TRUE;

                for ( v = 0; v < strlen( ignore_table[x] ); v++ )
                    *( p + v ) = '.';
            }
        }
    }

    for ( x = 0; strcmp( curse_table[x], "$" ); x++ )
    {
        if ( ( p = strstr( nbuf, curse_table[x] ) ) )
        {
            free( nbuf );
            return TRUE;
        }
    }

    free( nbuf );
    return FALSE;
}

/**
    Censor check
    @param ch Character to check for censoring
    @return TRUE if player has CONF +CENSOR
*/
bool block_profane( CHAR_DATA* ch )
{
    if ( ch == NULL )
        return FALSE;

    if ( !ch->desc )
        return FALSE;

    if ( !ch->pcdata )
        return FALSE;

    if ( ch->desc->connected != CON_PLAYING )
        return FALSE;

    if ( has_pcflag( ch, PCFLAG_CENSOR ) )
        return TRUE;

    return FALSE;
}

/**
    Get the character's active comlink
    @param ch Character to get comlink for
    @return active comlink for ch - currentcom if it is set, otherwise first comlink found
*/
OBJ_DATA* get_comlink( CHAR_DATA* ch )
{
    OBJ_DATA* obj;

    if ( ch->curr_comlink )
        return ch->curr_comlink;
    else
        for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
            if ( obj->item_type == ITEM_COMLINK )
                return obj;

    return NULL;
}

void format_string( char* str )
{
    int len = strlen(str);
    int i, j;

    for ( i = 0, j = 0; i < len; i++ )
    {
        if ( str[i] == '\n' )
        {
            str[j] = ' ';
            j++;

            while ( i + 1 < len && str[i + 1] == '\n' )
                i++;
        }
        else if ( str[i] != '\r' )
        {
            str[j] = str[i];
            j++;
        }
    }

    str[j] = '\0';
    return;
}

void send_broadcast( char* message, char* from_name )
{
    bool custom_event = false;
    char buf[MSL];

    if ( !str_cmp( from_name, "CUSTOM EVENT" ) )
        custom_event = true;

    strlcpy( buf, "&YB&Oro&zad&Wc&wa&zst&Oin&Yg &YN&Oe&zt&ww&zo&Or&Yk", MSL );

    if ( !NULLSTR( from_name ) )
    {
        strlcat( buf, " &Y[&w", MSL );
        if (custom_event)
            strlcat( buf, "GNI Report", MSL );
        else
            strlcat( buf, from_name, MSL );
        strlcat( buf, "&Y]", MSL );
    }

    strlcat( buf, "&z: &W", MSL );
    strlcat( buf, message, MSL );
    if (custom_event)
        format_string( buf );
    strlcat( buf, "\n", MSL );

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
    {
        CHAR_DATA* och;
        CHAR_DATA* vch;
        och = d->character;
        vch = d->character;



        if ( och && ( d->connected == CON_PLAYING || ( IS_IMMORTAL( och ) && d->connected == CON_EDITING ) ) &&
                !( och->in_room && xIS_SET( och->in_room->flags, ROOM_COMMSHIELD ) )
           )
        {
            // Mute anything under the header "GNI Report" (which custom events translate into) if they've muted the GNI channel
            if ( ( !str_cmp( from_name, "GNI Report" ) || !str_cmp( from_name, "CUSTOM EVENT" ) ) && xIS_SET( och->deaf, CHANNEL_GNI ) )
                continue;

            // Mute everything else if they've muted the CHAT channel 
            if ( str_cmp( from_name, "GNI Report" ) && str_cmp( from_name, "CUSTOM EVENT" ) && xIS_SET( och->deaf, CHANNEL_CHAT ) )
                continue;
            ch_printf( vch, buf );
        }
    }
    write_to_log( FUNC, buf, sysdata.log_level, 1, true );
}

/**
    Generic channel function.
    @param ch Character talking
    @param argument Text being said
    @param channel Channel being spoken onto
    @param verb Verb the player is doing ('talk', 'yell', 'ooc', etc.)
*/
void talk_channel( CHAR_DATA* ch, char* argument, int channel, const char* verb )
{
    /* GRAL Check listeners state ie no messages when sleeping */
    char buf[MSL];
    char buf2[MSL];
    char buf3[MSL];
    DESCRIPTOR_DATA* d = NULL;
    int position;
    CLAN_DATA* clan = NULL;
    SHIP_DATA* ship = NULL;
    OBJ_DATA* pcomm = NULL, * ptmp = NULL;
    bool  ch_comlink = FALSE;
    bool newbie = false;

    if(channel == CHANNEL_OOC || channel == CHANNEL_NEWBIE) {
        WOF(to_ooc_talk_channel(ch, NULL, NULL, channel, argument, NO_FLAG));
        return;
    }

    if ( ch->in_room && ch->in_room->area && xIS_SET( ch->in_room->area->flags, AFLAG_NEWBIE ) )
        newbie = true;

    //   if ( channel == CHANNEL_INTERPORT )
    //     mud_message(ch, channel, argument);

    if ( channel == CHANNEL_CLAN )
        clan = ch->pcdata->clan;

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch )  )
    {
        ch_println( ch, "&wYou can't do that here." );
        return;
    }

    // OOC and newbie is okay to use in commshield - everything else is banned - veska
    if ( channel != CHANNEL_OOC && channel != CHANNEL_NEWBIE && xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        if ( ch->master )
            ch_println( ch->master, "&wI don't think so..." );

        return;
    }

    if ( NULLSTR( argument ) )
    {
        snprintf( buf, MSL, "&w%s what?\n", verb );
        buf[0] = UPPER( buf[0] );
        send_to_char( buf, ch );    /* where'd this line go? */
        return;
    }

    if ( has_pcflag( ch, PCFLAG_AUTOFORMAT ) )
        argument = autoformat_string( argument );

    /*    if ( !IS_NPC(ch) && has_pcflag( ch, PCFLAG_SILENCE ) )
        {
        ch_println( ch, "You can't %s.", verb );
        return;
        }*/
    xREMOVE_BIT( ch->deaf, channel );

    if ( !( pcomm = ch->curr_comlink ) )
    {
        for ( ptmp = ch->last_carrying; ptmp; ptmp = ptmp->prev_content )
        {
            if ( ptmp->item_type == ITEM_COMLINK )
                pcomm = ptmp;
        }
    }

    if ( !IS_NPC( ch ) && !pcomm )
    {
        /* Comlink Safety Switch */
        if ( !IS_RPC( ch ) && ( channel == CHANNEL_CHAT
                || channel == CHANNEL_CLAN
                || channel == CHANNEL_CLANTALK ) )
        {
            ch_println( ch, "&wYou need a comlink to use that channel!" );
            return;
        }
    }

    /* Talking comlinks */
    if ( channel == CHANNEL_CHAT
            || channel == CHANNEL_CLAN
            || channel == CHANNEL_CLANTALK )
    {
        if ( ch->in_room && ch->in_room->area )
        {
            CHAR_DATA* rch = NULL;

            for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
            {
                if ( rch == ch )
                    continue;

                if ( rch->position < POS_RESTING )
                    continue;

                if ( ch->in_room->area->ambience == 1 )
                {
                    if ( !knows_language( rch, ch->speaking, ch ) && ( !IS_NPC( ch ) || !xIS_EMPTY( ch->speaking ) ) )
                    {
                        ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), scramble_text( argument, ch->speaking ) );
                    }
                    else
                        ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), argument );
                }
                else
                {
                    ch_println( rch, "&z%s %swhispers into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ) );
                }
            }
        }
    }

    switch ( channel )
    {
        case CHANNEL_INTERPORT:
            if ( sysdata.interport )
                mud_message( ch, channel, argument );

            return;

        case CHANNEL_CLAN:
        case CHANNEL_CLANTALK:
        {
            AI_DATA* curr_ai = NULL;

            if ( is_disrupted( ch, TAP_COMM, false ) )
            {
                return;
            }

            for ( curr_ai = first_ai; curr_ai; curr_ai = curr_ai->next )
                if ( curr_ai->clan == ch->pcdata->clan )
                    ai_react( curr_ai->character, ch, "clan", argument );
        }

        set_char_color( AT_CLAN, ch );
        clan = IS_NPC( ch ) ? get_clan( ch->mob_clan ) : ch->pcdata->clan;

        if ( !clan )
            return;

        ch_println( ch, "&W%s&z{%s&z}<%s&z>&W[&C%s&W]&W%s%s&W: %s%s&W", clan->adjective, get_division( ch ), get_rank( ch ), g_name( ch, ch ), tone_convert_format( ch, NULL ), lang_convert_format( ch, ch->speaking, ch ), txtclr( ch ), argument );
        break;

        case CHANNEL_SHIP:
            set_char_color( AT_WHITE, ch );
            ch_println( ch, "[INTERCOM: %s]%s%s: '%s%s&W'", ch->name, tone_convert_format( ch, NULL ), lang_convert_format( ch, ch->speaking, ch ), txtclr( ch ), argument );
            snprintf( buf, MSL, "&W[INTERCOM: $n]%s%s: '%s$t&W'", tone_convert_format( ch, NULL ), lang_convert_format( ch, ch->speaking, ch ), txtclr( ch ) );
            break;

        case CHANNEL_YELL:
            set_char_color( AT_GOSSIP, ch );
            ch_println( ch, "You %s%s, '%s%s&C'", tone_convert( ch, NULL ), verb, txtclr( ch ), argument );
            snprintf( buf, MSL, "Someone %s%ss, '%s$t'", tone_convert( ch, NULL ), verb, txtclr( ch ) );
            break;

        case CHANNEL_NEWBIE:
            set_char_color( AT_OOC, ch );
            ch_println( ch, "&Y(&RN&OE&YW&GB&BI&pE&Y) %s%s&Y: %s", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", ch->desc->account && xIS_SET(  ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name, argument );

            if ( strstr( ch->name, "Gni" ) || strstr( stripclr( argument ), "mucky" ) || strstr( stripclr( argument ), "chaw" ) )
                return;

            snprintf( buf, MSL, "&Y(&RN&OE&YW&GB&BI&pE&Y) %s%s&Y: $t", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name );
            snprintf( buf2, MSL, "&Y(&RN&OE&YW&GB&BI&pE&Y) %s%s&Y(%s): $t", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name, ch->name );

            discord_sendchan(DBC_SETTING_DISCORD_CHANNEL_OOC_DEFAULT, "(NEWBIE) %s%s: %s", 
                ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", 
                ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name, 
                argument);
            break;

        case CHANNEL_OOC:
            set_char_color( AT_OOC, ch );
            snprintf( buf, MSL, "(%s) %s%s: $t &D", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name );
            snprintf( buf2, MSL, "(%s) %s%s(%s): $t &D", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "",
                     ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : "", ch->name );

            if ( is_douche( ch ) )
                snprintf( buf3, MSL, "(GAG) %s%s(%s): $t &D", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "", ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : "", ch->name );
            else {
                discord_sendchan( DBC_SETTING_DISCORD_CHANNEL_OOC_DEFAULT, "(%s) %s%s: %s", 
                    IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC",
                    ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "*" : "",
                    ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name,
                    argument );
            }
            position        = ch->position;
            ch->position    = POS_STANDING;
            act( AT_OOC, buf, ch, argument, NULL, TO_CHAR );
            ch->position    = position;
            break;

        case CHANNEL_IMMTALK:
            snprintf( buf, MSL, "$n> $t" );
            position    = ch->position;
            ch->position    = POS_STANDING;
            act( AT_IMMORT, buf, ch, argument, NULL, TO_CHAR );
            ch->position    = position;
            break;

        case CHANNEL_CHAT:
            if ( is_disrupted( ch, TAP_COMM, false ) )
            {
                return;
            }

            ch_println( ch, "&YB&Oro&zad&Wc&wa&zst&Oin&Yg &YN&Oe&zt&ww&zo&Or&Yk &Y[&w%s&w%s&Y]&z: &W%s%s", ch->in_room->area->planet->name, is_leader( ch, ch->in_room->area->planet ) || IS_NPC( ch ) ? "" : " &R(&zPrivate Signal&R)", txtclr( ch ), argument );
            snprintf( buf, MSL, "&YB&Oro&zad&Wc&wa&zst&Oin&Yg &YN&Oe&zt&ww&zo&Or&Yk &Y[&w%s&w%s&Y]&z: &W%s$t", ch->in_room->area->planet->name, is_leader( ch, ch->in_room->area->planet ) || IS_NPC( ch ) ? "" : " &R(&zPrivate Signal&R)", txtclr( ch ) );
            snprintf( buf3, MSL, "&YB&Oro&zad&Wc&wa&zst&Oin&Yg &YN&Oe&zt&ww&zo&Or&Yk &Y[&w%s&w%s&Y]&z: (&C%s&z) &W%s$t", ch->in_room->area->planet->name, is_leader( ch, ch->in_room->area->planet ) || IS_NPC( ch ) ? "" : " &R(&zPrivate Signal&R)", ch->name, txtclr( ch ) );
            break;

        default:
            if ( is_disrupted( ch, TAP_COMM, false ) )
            {
                return;
            }

            set_char_color( AT_GOSSIP, ch );
            ch_println( ch, "You %s over the public network, '%s'", verb, argument );
            snprintf( buf, MSL, "$n %ss over the public network, '$t'",     verb );
            break;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_LOGSPEECH ) )
    {
        snprintf( buf2, MSL, "[%d] %s: %s (%s)", ch->in_room->vnum, IS_NPC( ch ) ? ch->short_descr : ch->name, argument, verb );
        append_to_file( LOG_FILE, buf2 );
    }

    char log_name[128];
    snprintf( log_name, 128, "chan_%s", stripclr(flag_value_name(chan_names, channel)) );
    int log_level = (channel == CHANNEL_CLAN ? 104 : sysdata.log_level);
    char log_buf[MSL];
    snprintf( log_buf, MSL, "%s: %s", ch->name, argument );
    write_to_log( log_name, log_buf, log_level, 4, false );

    for ( d = first_descriptor; d; d = d->next )
    {
        CHAR_DATA* och;
        CHAR_DATA* vch;
        och = d->character;
        vch = d->character;

        if ( ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                && vch != ch
                && !xIS_SET( och->deaf, channel ) )
        {
            if ( vch->position < POS_RESTING )
                continue;

            char* sbuf = argument;
            bool encrypt = FALSE;
            ch_comlink = FALSE;

            if ( channel == CHANNEL_CHAT )
                encrypt = FALSE;

            if ( xIS_SET( vch->in_room->flags, ROOM_COMMSHIELD ) && !IS_RPC( och ) )
            {
                /*  GRAL maybe check for level and commshield
                    Do we want real newbs to ask on OOC or RPC/IMMCHAT?
                    && get_trust( ch ) < LEVEL_HERO * 0.2
                */
                if ( channel == CHANNEL_CLAN )
                    continue;

                if ( channel == CHANNEL_CHAT )
                    continue;
            }

            if ( is_disrupted( vch, TAP_COMM, true ) && ( channel == CHANNEL_CLAN || channel == CHANNEL_CHAT ) )
                continue;

            if ( channel == CHANNEL_IMMTALK && !IS_IMMORTAL( och ) )
                continue;

            if ( xIS_SET( vch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( vch ) && channel != CHANNEL_OOC && channel != CHANNEL_NEWBIE )
                continue;

            if ( channel == CHANNEL_YELL )
            {
                if ( ch->in_room->area != och->in_room->area )
                    continue;

                /* Fix for yelling on ships. Not good */
                if ( get_ship_from_room( ch->in_room ) != NULL
                        || get_ship_from_room( och->in_room ) != NULL )
                    if ( get_ship_from_room( och->in_room ) != get_ship_from_room( ch->in_room ) )
                        continue;
            }

            if ( channel == CHANNEL_CLAN )
            {
                if ( IS_NPC( vch ) )
                    continue;

                if ( xIS_SET( vch->in_room->flags, ROOM_DISTORTION ) && !IS_IMMORTAL( vch ) )
                {
                    ch_println( vch, "&RAll you hear is static." );
                    continue;
                }

                if ( !vch->pcdata->clan && get_trust( vch ) < sysdata.log_level )
                    continue;

                if ( vch->pcdata->clan && vch->pcdata->clan != clan
                        && get_trust( vch ) < sysdata.log_level )
                    continue;

                if ( IS_IMMORTAL( vch ) && get_trust( vch ) < 104 ) // Ok now we totally block <105s. Orion 2008 - Modified by Rojan to be <104s, by Anna's request
                    continue;
            }

            if ( channel == CHANNEL_SHIP )
            {
                ship = get_ship_from_room( ch->in_room );

                if ( !ship )
                    continue;

                if ( !vch->in_room )
                    continue;

                if ( vch->in_room->vnum > ship->lastroom
                        || vch->in_room->vnum < ship->firstroom )
                    continue;
            }

            position        = vch->position;

            if ( channel != CHANNEL_YELL )
                vch->position   = POS_STANDING;

            if ( ( ( !knows_language( vch, ch->speaking, ch )
                     && ( !IS_NPC( ch )
                          || !xIS_EMPTY( ch->speaking ) ) )
                    || encrypt )
                    && ( channel != CHANNEL_NEWBIE
                         &&  channel != CHANNEL_OOC
                         && channel != CHANNEL_TEAM
                         && channel != CHANNEL_CHAT )  )
                sbuf = scramble_text( argument, ch->speaking );

            MOBtrigger = FALSE;

            if ( channel == CHANNEL_IMMTALK )
                act( AT_IMMORT, buf, ch, sbuf, vch, TO_VICT );
            else if ( channel == CHANNEL_OOC || channel == CHANNEL_NEWBIE )
            {
                // Filter out newbie stuff!
                if ( newbie && !getRPC( vch->name ) && !IS_RPC( vch ) && !IS_IMMORTAL( vch ) )
                    continue;
                else if ( newbie )
                    send_to_char( "&C(Newbie Area)", vch );

                if ( ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) && get_trust( vch ) >= 105 && !has_pcflag( vch, PCFLAG_ACCNAME ) )
                {
                    if ( is_douche( ch ) )
                    {
                        if ( get_trust( vch ) >= 103 )
                            act( AT_OOC, buf3, ch, sbuf, vch, TO_VICT );
                    }
                    else
                        act( AT_OOC, buf2, ch, sbuf, vch, TO_VICT );
                }
                else
                {
                    if ( is_douche( ch ) )
                    {
                        if ( get_trust( vch ) >= 103 )
                            act( AT_OOC, buf3, ch, sbuf, vch, TO_VICT );
                    }
                    else
                        act( AT_OOC, buf, ch, sbuf, vch, TO_VICT );
                }
            }
            else if ( channel == CHANNEL_SHIP )
            {
                snprintf( buf, MSL, "&W[INTERCOM: $n]%s%s: '%s$t&W'", tone_convert_format( ch, NULL ), lang_convert_format( vch, ch->speaking, ch ), txtclr( ch ) );
                act( AT_YELLOW, buf, ch, sbuf, vch, TO_VICT );
            }
            else if ( channel == CHANNEL_CLAN )
            {
                //                char *sbuf;
                OBJ_DATA* obj = NULL;
                ch_comlink = FALSE;

                for ( obj = och->first_carrying ; obj ; obj = obj->next_content )
                    if ( obj->item_type == ITEM_COMLINK )
                        ch_comlink = TRUE;

                /* no comlink no service */
                if ( ( !ch_comlink ) && get_trust( vch ) < sysdata.log_level )
                    continue;

                if ( !knows_language( vch, ch->speaking, ch ) )
                {
                    snprintf( buf, MSL,  "%s&z{%s&z}<%s&z>&W[&C%s&W]&W%s&W: <&zTranslation from %s&W %s$t\n", clan->adjective, get_division( ch ), get_rank( ch ), g_name( ch, vch ), tone_convert_format( ch, vch ), lang_convert_format( ch, ch->speaking, ch ), txtclr( ch ) ); // GRAL lang_convert_format(ch, ch->speaking, ch) chosen so the language spoke is never hidden
                    act( AT_ACTION, buf, ch, argument, vch, TO_VICT );
                }
                else
                {
                    snprintf( buf, MSL,   "%s&z{%s&z}<%s&z>&W[&C%s&W]&W%s%s&W: %s$t\n",                        clan->adjective, get_division( ch ), get_rank( ch ),  g_name( ch, vch ), tone_convert_format( ch, vch ), lang_convert_format( vch, ch->speaking, ch ), txtclr( ch ) );
                    act( AT_ACTION,  buf, ch, argument, vch, TO_VICT );
                }
            }
            else if ( channel == CHANNEL_CHAT )
            {
                OBJ_DATA* obj = NULL;
                ch_comlink = FALSE;

                for ( obj = och->first_carrying ; obj ; obj = obj->next_content )
                    if ( obj->item_type == ITEM_COMLINK )
                        ch_comlink = TRUE;

                /* no comlink no service */
                if ( ( !ch_comlink ) && get_trust( vch ) < sysdata.log_level )
                    continue;

                if (IS_IMMORTAL(vch))
                    act( AT_GOSSIP, buf3, ch, sbuf, vch, TO_VICT );
                else
                    act( AT_GOSSIP, buf, ch, sbuf, vch, TO_VICT );
            }
            else
                act( AT_GOSSIP, buf, ch, sbuf, vch, TO_VICT );

            vch->position   = position;
        }
    }

    snprintf(buf, MSL, "%s,%s", ch->name, argument);
    snprintf(buf2, MSL, "out/channel/%s", flag_value_name(chan_names, channel));
    mqtt_publish(buf2, escape_percent( buf ) );

    if ( !IS_IMMORTAL( ch ) && channel != CHANNEL_CLAN )
        WAIT_STATE( ch, 3 );

    return;
}
// used to send messages to ooc talk channels, which don't typically use
// talk_channel. This is used for things like immnet, councilnet, and ooc
int to_ooc_talk_channel( CHAR_DATA* ch, ACCOUNT_DATA *account, CHAR_DATA* hide, int channel, char* argument, int flags )
{
    char outbuf[MSL];
    if( NULLSTR(argument)) return E_LOTJ_MISSING_ARGUMENTS;
    if (!account && ch && ch->pcdata && ch->pcdata->account) //TODO temp fix to stop the mud from crashing until Miros fixes it for real
        account = ch->pcdata->account;
    argument = escape_percent( argument );


    if(flags & RAW_OUTPUT) {
        strncpy(outbuf, argument, MSL);
    } else { // do the formatting
        char acc_or_username[24];
        char *txt_clr = "&049";
        if(ch) txt_clr = txtclr(ch);
        if(!ch && !account) return E_LOTJ_MISSING_ARGUMENTS;
        snprintf(acc_or_username, 24, "%s%s", ch ? "" : "#", ch ? ch->name : account->name);
        switch(channel) {
            case CHANNEL_IMMTALK:
                snprintf(outbuf, MSL, "&W&BImmNet&W[&C%s&W]: %s%s\r\n", acc_or_username, txt_clr, argument);
                break;
            case CHANNEL_COUNCIL:
                snprintf(outbuf, MSL, "&W&zCouncilNet&W[&C%s&W]: %s\r\n", acc_or_username, argument);
                break;
            case CHANNEL_RPC:
                snprintf( outbuf, MSL, "&z(&YR&z|&YP&z|&YC&z) &z[&w%s&z]: &O%s\r\n", acc_or_username, argument );
                break;
            case CHANNEL_NEWBIE:
            case CHANNEL_OOC:
                argument = stripclr( argument );
                char tag_part[2] = "";
                char name_part[64];
                char ooc_imm_newbie_part[24];
                if(channel == CHANNEL_NEWBIE) {
                    snprintf(ooc_imm_newbie_part, 24, "(&RN&OE&YW&GB&BI&pE&Y)");
                } else if ( ( ch && IS_IMMORTAL(ch) ) || (!ch && account && account->level >= LEVEL_IMMORTAL) ){
                    snprintf(ooc_imm_newbie_part, 24, "(IMM)");
                } else {
                    snprintf(ooc_imm_newbie_part, 24, "(OOC)");
                }
                if(account && (!ch || xIS_SET(account->flags, ACC_CHAT))) {
                    snprintf(tag_part, 2, "*");
                    snprintf(name_part, 64, "%s", account->name);
                } else {
                    snprintf(name_part, 64, "%s", ch->name);
                }
                snprintf(outbuf, MSL, "&Y%s %s%s&Y: %s\r\n", ooc_imm_newbie_part, tag_part, name_part, argument);
                break;
            case CHANNEL_IMMCHAT:
                snprintf( outbuf, MSL, "&B( &WIMM &B| &WCHAT &B)&w&W[&C%s&W]&w: &B'&w%s%s&B'&w\r\n", acc_or_username, txt_clr, argument );
                break;
            default:
                return E_LOTJ_INVALID_CHANNEL;
        }
    }

    char log_name[128];
    int log_level = sysdata.log_level;
    snprintf(log_name, 128, "chan_%s", flag_value_name(chan_names, channel));    
    write_to_log(log_name, outbuf, log_level, 4, false);

    for(DESCRIPTOR_DATA *desc = first_descriptor; desc; desc = desc->next) {
        if(desc->connected != CON_PLAYING) continue;
        if(!desc->character) continue;
        if (desc->character == ch && ( channel == CHANNEL_RPC || channel == CHANNEL_IMMCHAT ) && flags & RAW_OUTPUT) continue;
        if (hide && desc->character == hide) continue;
        if(xIS_SET(desc->character->deaf, channel)) continue;

        switch(channel) {
            case CHANNEL_IMMCHAT:
            case CHANNEL_IMMTALK:
                if ( get_trust( desc->character ) < sysdata.log_level && !is_name( "newimm", desc->character->pcdata->bestowments ) ) continue;
                break;
            case CHANNEL_COUNCIL:
            case CHANNEL_RPC:
                if ( !has_pcflag( desc->character, PCFLAG_NCOUNCIL ) && get_trust( desc->character ) < sysdata.log_level && get_trust( desc->character ) < 101 ) continue;
                break;
            case CHANNEL_NEWBIE:
            case CHANNEL_OOC:
                if(!IS_IMMORTAL(desc->character) && desc->character->position <= POS_SLEEPING) continue;
                break;
        }

        send_to_char_color( outbuf, desc->character );
    }

    if( !(flags & NO_DISCORD_OUT ) ) {
        int rval;
        char discord_chan_name[1024];
        if ( ( rval = discord_internal_chan_to_discord_chan( channel, discord_chan_name, 1024 ) ) == E_LOTJ_SUCCESS ) {
            discord_sendchan(discord_chan_name, outbuf);
        }
    }

    // if the NO_MQTT_OUT flag is not set
    if( !(flags & NO_MQTT_OUT ) ) {
        int rval;
        char output_topic[1024];
        if ( ( rval = internal_chan_to_output_topic( channel, output_topic, 1024 ) ) == E_LOTJ_SUCCESS ) {

            mqtt_publish(output_topic, stripclr(outbuf) );
        }
    }

    if(flags & DISCORD_ECHOBACK && account) {
        account_broadcast(account, outbuf);
    }

    return E_LOTJ_SUCCESS;
}

/**
    Send a message to a channel
    Used for logging/imm channels
    Level restricted, unlike talk_channel
    @param argument Text being transmitted
    @param channel Channel being transmitted to
    @param verb Verb for what is being done ('yell', 'say', etc.)
    @param level Minimum level to see message
*/
void to_channel( const char* argument, int channel, const char* verb, sh_int level )
{
    char buf[MSL];
    DESCRIPTOR_DATA* d = NULL, *d_next = NULL;
    CHAR_DATA* vch = NULL;
    sh_int trust = 0;
    char chan_name[MSL];
    snprintf( chan_name, MSL, "chan_%s", verb ? ( !dump_mem_on_shutdown ? stripclr( strlower( verb ) ) : strlower( verb ) ) : "NULL" );

    if ( !first_descriptor || NULLSTR( argument ) )
        return;

    snprintf( buf, MSL, "&p%s: %s&w\n", verb ? verb : "NULL", argument );

    for ( d = first_descriptor; d; d = d_next )
    {
        d_next = d->next;
        vch = d->character;

        if ( !vch )
            continue;

        trust = get_trust( vch );

        if ( trust < LEVEL_IMMORTAL ||
            ( channel == CHANNEL_BUILD && trust < sysdata.build_level ) ||
            ( ( channel == CHANNEL_LOG || channel == CHANNEL_COMM ) && trust < sysdata.log_level ) )
            continue;

        if ( d->connected == CON_PLAYING && !xIS_SET( vch->deaf, channel ) &&
        ( trust >= level || ( is_empowered( vch, chan_name ) && trust >= CHANNEL_LOG ) ) )
        {
            if ( channel == CHANNEL_TUNE && vch->pcdata && vch->pcdata->tune_filter && fnmatch( vch->pcdata->tune_filter, buf, FNM_EXTMATCH ) )
                continue;

            if ( channel == CHANNEL_DEBUG && vch->pcdata && vch->pcdata->debug_filter && fnmatch( vch->pcdata->debug_filter, buf, FNM_EXTMATCH ) )
                continue;

            send_to_char( buf, vch );
        }
    }

    if(channel != CHANNEL_DEBUG && channel != CHANNEL_TUNE && !dump_mem_on_shutdown )
    {
        char buf2[1024];
        snprintf(buf2, 1024, "out/channel/%s", flag_value_name(chan_names, channel));
        mqtt_publish( buf2, escape_percent( argument ) );
        write_to_log( chan_name, buf, level, 4, false ); // write to the channel logs for 4 hours
    }

    return;
}

/**
    Command to use the broadcast network
    BROADCAST/NETWORKHACK
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_chat( CHAR_DATA* ch, char* argument )
{
    PLANET_DATA* planet = NULL;

    if ( xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You're not even on a planet." );
        return;
    }

    if ( !xIS_SET( planet->flags, PLANET_COMM ) || !xIS_SET( planet->flags, PLANET_TRANSMIT ) )
    {
        ch_println( ch, "You can't send a signal right now." );
        return;
    }

    // GRAL Stopped calls to this (broadcast) while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't speak while gagged." );
        return;
    }

    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "The language of the Lorrdians is physical." );
        return;
    }

    if ( is_disrupted( ch, TAP_COMM, false ) )
        return;

    if ( !IS_NPC( ch ) && count_args( argument ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than three words in length!" );
        return;
    }
    else if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( argument ) > ( get_curr_int( ch ) / 3 ) + 2 )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
        return;
    }

    shift_points( ch, 1 );
    talk_channel( ch, drunk_speech( argument, ch ), CHANNEL_CHAT, "chat" );
    return;
}

