/**
    Broadcast message from ship to starsystem
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_systemtalk( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&wRadio what?" );
        return;
    }

    if ( ch->position < POS_RESTING )
    {
        ch_println( ch, "You might want to stand up first!" );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak through the ship's communication but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't use ship communications while gagged." );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "The language of the Lorrdians is physical." );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RGet out of hyperspace first." );
        return;        
    }

    if ( ship->shipstate == SHIP_DOCKED || !ship->starsystem )
    {
        ch_println( ch, "&RWon't do much good unless you're launched!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RAll you hear is static." );
        return;
    }

    radio( ship, drunk_speech( argument, ch ), ch );

    if ( !IS_IMMORTAL( ch ) )
        WAIT_STATE( ch, 3 );

    return;
}

/**
    Broadcast a message from ship to starsystem
    @param ship The ship being radioed from.
    @param argument Text spoken
    @param ch Character speaking. Can be null.
*/
void radio( SHIP_DATA* ship, char* argument, CHAR_DATA* ch )
{
    char buf[MSL];
    ROOM_INDEX_DATA* room;
    CHAR_DATA* vch, *next_vch;
    bool valid_ch = false;

    if ( !ship || !ship->starsystem )
        return;

    if ( ch && !char_extracted( ch ) )
        valid_ch = true;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( room->vnum == ship->cockpit || room->vnum == ship->navseat
                || room->vnum == ship->pilotseat || room->vnum == ship->coseat || room->vnum == ship->gunseat || room->vnum == ship->engineroom )
        {
            for ( vch = room->first_person; vch; vch = next_vch )
            {
                next_vch = vch->next_in_room;

                if ( !IS_AWAKE( vch ) )
                    continue;

                if ( valid_ch && vch == ch )
                {
                    snprintf( buf, MSL, "&CYou %sradio, '%s%s&C'\n", tone_convert( ch, vch ), txtclr( ch ), argument );
                    send_to_char( buf, vch );
                }
                else if ( valid_ch )
                {
                    snprintf( buf, MSL, "&C%s %sradios, '%s%s&C'\n", g_name( ch, vch ), tone_convert( ch, vch ), txtclr( ch ), translate_for_target( ch, vch, argument ) );
                    send_to_char( buf, vch );
                }
                else
                {
                    snprintf( buf, MSL, "&CThe ship's computer radios, '%s'\n", argument );
                    send_to_char( buf, vch );
                }
            }
        }
    }

    for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
    {
        if ( turret->room )
        {
            for ( vch = turret->room->first_person; vch; vch = next_vch )
            {
                next_vch = vch->next_in_room;

                if ( !IS_AWAKE( vch ) )
                    continue;

                if ( valid_ch && vch == ch )
                {
                    snprintf( buf, MSL, "&CYou %sradio, '%s%s&C'\n", tone_convert( ch, vch ), txtclr( ch ), argument );
                    send_to_char( buf, vch );
                }
                else if ( valid_ch )
                {
                    snprintf( buf, MSL, "&C%s %sradios, '%s%s&C'\n", g_name( ch, vch ), tone_convert( ch, vch ), txtclr( ch ), translate_for_target( ch, vch, argument ) );
                    send_to_char( buf, vch );
                }
                else
                {
                    snprintf( buf, MSL, "&CThe ship's computer radios, '%s'\n", argument );
                    send_to_char( buf, vch );
                }
            }
        }
    }

    SHIP_DATA* target_next;

    for ( SHIP_DATA* target = ship->starsystem->first_ship; target; target = target_next )
    {
        target_next = target->next_in_starsystem;

        if ( target == ship )
            continue;

        for ( room = target->first_room; room; room = room->next_in_range )
        {
            if ( room->vnum == target->cockpit || room->vnum == target->navseat
                    || room->vnum == target->pilotseat || room->vnum == target->coseat || room->vnum == target->gunseat || room->vnum == target->engineroom )
            {
                for ( vch = room->first_person; vch; vch = next_vch )
                {   
                    next_vch = vch->next_in_room;

                    if ( !IS_AWAKE( vch ) )
                        continue;

                    snprintf( buf, MSL, "&C%s %sradios, '%s%s&C'\n", ship->name, valid_ch ? tone_convert( ch, vch ) : "", valid_ch ? txtclr( ch ) : "", valid_ch ? translate_for_target( ch, vch, argument ) : argument );
                    send_to_char( buf, vch );
                }
            }
        }

        for ( TURRET_DATA* turret = target->first_turret; turret; turret = turret->next )
        {
            if ( !turret || turret == NULL )
                break;

            if ( turret->room )
            {
                for ( vch = turret->room->first_person; vch; vch = next_vch )
                {
                    next_vch = vch->next_in_room;

                    if ( !IS_AWAKE( vch ) )
                        continue;

                    snprintf( buf, MSL, "&C%s %sradios, '%s%s&C'", ship->name, valid_ch ? tone_convert( ch, vch ) : "", valid_ch ? txtclr( ch ) : "", valid_ch ? translate_for_target( ch, vch, argument ) : argument );
                    send_to_char( buf, vch );
                }
            }
        }
    }

    return;
}

/**
    Out of character chat channel
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_ooc( CHAR_DATA* ch, char* argument )
{
    if ( IS_NPC ( ch ) )
        return; // Ralen NPC's doing OOC crashes us.

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &COOC <&wmessage&C>" );
        ch_println( ch, "&wOOC is LOTJ's global Out Of Character chat." );
        ch_println( ch, "&wWhat would you like to say?" );
        return;
    }

    if ( is_silenced( ch ) )
    {
        ch_println( ch, "You can't do that!" );
        return;
    }

    if ( is_noooc( ch ) )
    {
        ch_println( ch, "You can't do that! If you have questions, please use IMMCHAT to ask for assistance." );
        return;
    }

    if ( !IS_IMMORTAL( ch ) && str_cmp( stripclr( argument ), argument ) )
    {
        ch_println( ch, "You cannot use colour on OOC." );
        return;
    }

    //strlcpy( argument, stripclr( argument ), MIL );

    /* GRAL Changed 100 to LEVEL_HERO */
    if ( ch->top_level < LEVEL_HERO )
    {
        do_newbiechat( ch, argument );
        return;
    }

    if ( strlen( argument ) > 254  && get_trust( ch ) < sysdata.log_level  )
    {
        argument[253] = '\n';
        argument[254] = '\0';
        ch_println( ch, "&WLine too long. Please cut down the spam." );
    }

    if ( !sysdata.ALLOW_OOC
            && !IS_RPC( ch ) )
    {
        ch_println( ch, "&RThe OOC Channel is closed at this time. Sorry." );
        // if ( IS_RPC( ch ) ) ch_println( ch, "&R[Immortal - Use SETOOC to toggle OOC]" );
        return;
    }
    else if ( !sysdata.ALLOW_OOC )
        ch_println( ch, "&RThe OOC channel is off, mortals won't be able to respond." );

    if ( !IS_NPC( ch ) && xIS_SET( ch->deaf, CHANNEL_OOC ) )
    {
        ch_println( ch, "&RYou must engage your OOC channel to use it. CHANNEL +OOC." );
        return;
    }

    if ( ooc_break_check( ch, 1 ) )
        return;

    if ( getRPC( ch->name ) )
        add_ooc( getRPC( ch->name ) );

    shift_points( ch, -2 );
    talk_channel( ch, argument, CHANNEL_OOC, "ooc" );
    return;
}

bool check_ooc_in_ic_message( CHAR_DATA* ch, const char* argument, const char* func_name )
{
    if ( get_trust( ch ) >= LEVEL_RPC )
        return false;

    char* lower_arg = strlower( argument );
    char* ooc_start = strstr( lower_arg, "ooc" );

    if ( ooc_start )
    {
        if ( ooc_start != argument && !isalpha( *( ooc_start - 1 ) ) && !isalpha( *( ooc_start + 3 ) ) )
        {
            lognormal( "%s used 'ooc' in %s: %s", ch->name, func_name, argument );
            char buf[MIL];
            snprintf( buf, MIL, "osay %s", argument );
            interpret( ch, buf, FALSE );
            return true;
        }
    }

    char* osay_start = strstr( lower_arg, "osay" );

    if ( osay_start )
    {
        if ( osay_start != argument && !isalpha( *( osay_start - 1 ) ) && !isalpha( *( osay_start + 4 ) ) )
        {
            lognormal( "%s used 'osay' in %s: %s", ch->name, func_name, argument );
            char buf[MIL];
            snprintf( buf, MIL, "osay %s", argument );
            interpret( ch, buf, FALSE );
            return true;
        }
    }

    return false;
}

