    if ( has_pcflag( ch, PCFLAG_AUTOFORMAT ) )
        argument = autoformat_string( argument );

    ch_println( ch, "&CYou %syell%s, '%s%s&C'", tone_convert( ch, NULL ), lang_convert( ch, ch->speaking, ch ), txtclr( ch ), argument );
    yell_radius( ch, drunk_speech( argument, ch ), true );
    return;
}

/**
    Handler for transmitted yelled messages based on area ambience
    @see do_yell
    @see yell_radius_1
    @param ch Character yelling
    @param buf Text being yelled
*/
void yell_radius( CHAR_DATA* ch, char* buf, bool speech )
{
    int range = 0, ambience = 0;

    if ( !ch->in_room )
        return;

    ambience = ch->in_room->area ? ch->in_room->area->ambience : 0;

    /*
        Ambience Factors:
        Low:    Range = 6 rooms
        Medium: Range = 4 rooms
        High:   Range = 2 rooms
    */


    switch ( ambience )
    {
        case 0:
            range = 4;
            break;

        case 1:
            range = 6;
            break;

        case 2:
            range = 4;
            break;

        case 3:
            range = 2;
            break;
    }

    int cnt = 0;
    int vnums[500] = { 0 };

    yell_radius_1( ch, ch->in_room, &cnt, vnums, buf, range, -1, NULL, speech );
    return;
}

/**
    Transmit yelled message to surrounding rooms
    @see do_yell
    @see yell_radius
    @param ch Character yelling
    @param room Room ch is yelling from
    @param buf Text being yelled
    @param range Range to transmit message
    @param dir Direction being yelled towards
*/
void yell_radius_1( CHAR_DATA* ch, ROOM_INDEX_DATA* room, int* cnt, int* vnums, char* buf, int range, int dir, char* default_string, bool speech )
{
    CHAR_DATA* rch = NULL, *rnext = NULL;
    SHIP_DATA* ship = NULL;
    ROOM_INDEX_DATA* entrance_ramp = NULL;
    EXIT_DATA* pexit = NULL;
    char* dtxt = NULL;
    bool same = FALSE;
    char fulltext[MSL];

    if ( !ch || !room )
        return;

    for ( int i = 0; i < (*cnt); i++ )
        if ( vnums[i] == room->vnum )
            return;

    if ( ch->in_room == room )
        same = TRUE;
    else
    {
        switch ( dir )
        {
            default:
                dtxt = !NULLSTR( default_string ) ? default_string : "somewhere";
                break;

            case 0:
                dtxt = "the south";
                break;

            case 1:
                dtxt = "the west";
                break;

            case 2:
                dtxt = "the north";
                break;

            case 3:
                dtxt = "the east";
                break;

            case 4:
                dtxt = "below";
                break;

            case 5:
                dtxt = "above";
                break;

            case 6:
                dtxt = "the southwest";
                break;

            case 7:
                dtxt = "the southeast";
                break;

            case 8:
                dtxt = "the northwest";
                break;

            case 9:
                dtxt = "the northeast";
                break;
        }
    }

    for ( rch = room->first_person; rch; rch = rnext )
    {
        rnext = rch->next_in_room;

        if ( IS_NPC( rch ) || rch == ch )
            continue;

        if ( rch->hit <= 0 )
            continue;

        if ( !IS_AWAKE( rch ) )
            continue;

        // snprintf( buf, MSL, "'%s$t&C' $n %s%s you%s.", txtclr(ch), tone_convert(get_tone( ch )), says_to_verb, lang_convert(vch, ch->speaking, ch) );
        if ( speech )
        {
            if ( same )
                ch_println( rch, "&C%s %syells%s, '%s%s&C'",
                           PERS( ch, rch ), tone_convert( ch, rch ), lang_convert( rch, ch->speaking, ch ),
                           txtclr( ch ), translate_for_target( ch, rch, buf ) );
            else
                ch_println( rch, "&CSomeone %syells from %s%s, '%s%s&C'",
                           tone_convert( ch, rch ), dtxt, lang_convert( rch, ch->speaking, ch ),
                           txtclr( ch ), translate_for_target( ch, rch, buf ) );
        }
        else if ( !same )
            ch_println( rch, "&CYou hear %s from %s.&C", buf, dtxt );
    }
    if ( *cnt >= 500 )
    {
        bug("%s: exceeded array size of 500.", FUNC );
        return;
    }

    vnums[(*cnt)] = room->vnum;
    (*cnt)++;

    /* Branch out */
    for ( pexit = room->first_exit; pexit; pexit = pexit->next )
    {
        if ( pexit->to_room && pexit->to_room != room )
        {
            if ( range > 0 )
                yell_radius_1( ch, pexit->to_room, cnt, vnums, buf, range - 1, pexit->vdir, NULL, speech );
            else
            {
                if ( speech )
                    echo_to_room( AT_CYAN, pexit->to_room, "You hear someone yelling nearby." );
                else
                {
                    snprintf( fulltext, MSL, "You hear %s nearby.", buf );
                    echo_to_room( AT_CYAN, pexit->to_room, fulltext );
                }
            }
        }
    }

    for ( ship = room->first_ship; ship; ship = ship->next_in_room )
    {
        entrance_ramp = get_ship_entrance( ship );

        if ( ship->hatchopen || xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            if ( entrance_ramp && entrance_ramp != room )
            {
                if ( range > 0 )
                    yell_radius_1( ch, entrance_ramp, cnt, vnums, buf, range - 1, -1, "through the hatch", speech );
                else
                {
                    if ( speech )
                        echo_to_room( AT_CYAN, entrance_ramp, "You hear someone yelling through the hatch." );
                    else
                    {
                        snprintf( fulltext, MSL, "You hear %s through the hatch.", buf );
                        echo_to_room( AT_CYAN, entrance_ramp, fulltext );
                    }
                    if ( *cnt >= 500 )
                    {
                        bug("%s: exceeded array size of 500.", FUNC );
                        return;
                    }
                    vnums[(*cnt)] = entrance_ramp->vnum;
                    (*cnt)++;
                }

            }
        }
    }

    // and from inside the ship
    if ( ( ship = ship_from_entrance( room ) ) != NULL )
    {
        if ( ship->in_room && ( ship->hatchopen || xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) ) )
        {
            if ( entrance_ramp != room )
            {
                char buf2[MSL];

                if ( range > 0 )
                {
                    snprintf( buf2, MSL, "the hatch of %s", ship->name );
                    yell_radius_1( ch, ship->in_room, cnt, vnums, buf, range - 1, -1, buf2, speech );
                }
                else
                {
                    if ( speech )
                        snprintf( buf2, MSL, "You hear someone yelling through the hatch of %s.", ship->name );
                    else
                        snprintf( buf2, MSL, "You hear %s through the hatch of %s.", buf, ship->name );

                    echo_to_room( AT_CYAN, ship->in_room, buf2 );
                    if ( *cnt >= 500 )
                    {
                        bug("%s: exceeded array size of 500.", FUNC );
                        return;
                    }
                    vnums[(*cnt)] = ship->in_room->vnum;
                    (*cnt)++;                 
                }
            }
        }
    }
    return;
}

