const char* fmt_talk_output( CHAR_DATA* ch, CHAR_DATA* rch, int channel, int code, bool encrypt, bool hapanlink, const char* argument )
{
    char colA[4], colB[4];
    static char buf[MSL];

    if ( code != 0 )
    {
        strlcpy( colA, "&B", 4 );

        if ( hapanlink )
            strlcpy( colB, "&r", 4 );
        else
            strlcpy( colB, "&R", 4 );
    }
    else
    {
        strlcpy( colA, "&B", 4 );

        if ( hapanlink )
            strlcpy( colB, "&z", 4 );
        else
            strlcpy( colB, "&G", 4 );
    }

    bool rch_knows_language = knows_language( rch, ch->speaking, ch ) || ( IS_NPC( ch ) && xIS_EMPTY( ch->speaking ) );
    snprintf( buf, MSL, "&w%sCommNet %d %s[&W%s%s]&W%s%s: %s%s&D\n",
        colA, channel, colB,
        g_name( ch, rch ),
        colB,
        tone_convert_format( ch, rch ), // Still show tone when encrypted
        encrypt ? "" : lang_convert_format( rch, ch->speaking, ch ), // Can't understand language when encrypted
        txtclr( ch ),
        encrypt ? "&z(&wunintelligible audio&z)" : rch_knows_language ? argument : scramble_text( argument, ch->speaking )
    );

    return buf;
}

/**
    IC Comlink chat channel
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_talk( CHAR_DATA* ch, char* argument )
{
    /*  17May09 FIXED GRAL when sleeping or stunned block clan
        GRAL Stop -# commlink talks. Bug on load maybe ?
        17May09 FIXED GRAL 17:25 ( IMM | CHAT )[Alarid]: 'Hmm...anyone see anything wrong with this...? CommNet 0 [Michaels]<An unfamiliar dialect>: Arakyd Industries is now hiring for all positions including fo
        29May09 Blocked clan language. The clan channel will auto translate instead.
        17May09 FIXED GRAL Most lag on translation here.
        18May09 Fried translation droids no a comm channel.
        Todo - lost the d->descriptors block the imms from seeing while morting.
         How about we force a chan -channel when morting instead.
        GRAL Before this line: CommNet 0 [Gral]: test Log: [*****] LAG: Gral: talk test (R:44 S:10.306807)
    */
    OBJ_DATA*  obj = NULL;
    SHIP_DATA* ship = NULL;
    bool ch_comlink = FALSE, hapanlink = FALSE, has_comlink = FALSE, encrypt = FALSE;
    int channel = 0, code = 0;
    char buf[MSL];

    if ( NOT_AUTHED( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    // GRAL I will do away with this language soon.
    if ( xIS_SET( ch->speaking, LANG_CLAN ) )
    {
        ch_println( ch, "&wThe language of a clan is for the clan channel." );
        return;
    }

    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "&wThe language of the Lorrdians is physical." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( !IS_NPC( ch ) && xIS_SET( ch->deaf, CHANNEL_TALK ) )
    {
        ch_println( ch, "&RYou must engage your talk channel to use it. Channel +talk." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch )  )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( is_disrupted( ch, TAP_COMM, false ) )
        return;

    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "&cGagged, $n tries to speak through their comlink but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "&cYou try to speak into your comlink, but due to the gag your words are undecipherable." );
        return;
    }

    if ( ( obj = ch->curr_comlink ) != NULL )
    {
        channel = obj->value[5];
        code = obj->value[4];

        if ( obj->value[2] == 1 )
            hapanlink = TRUE;

        ch_comlink = TRUE;
    }
    else
    {
        ch_println( ch, "&wYou need to select a comlink with &kcurrentcom&k first." );
        return;
    }

    if ( ( !ch_comlink ) && has_cyber_flag( ch, CYBER_COMLINK ) )
        // Gral this stops the whining on the perms in pubbies
    {
        if ( ( ship = get_ship_from_room( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "&wYou need a comlink or a ship's systems to boost the cybernetic comlink's signal!" );
            return;
        }

        ch_comlink = TRUE;
    }

    if ( !ch_comlink )
    {
        ch_println( ch, "&wYou're going to need a comlink to do that!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&wWhy don't you say something!" );
        return;
    }

    if ( !IS_NPC( ch ) && count_args( argument ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
    {
        ch_println( ch, "&wYou aren't intelligent enough to form sentences greater than three words in length!" );
        return;
    }

    if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( argument ) > ( get_curr_int( ch ) / 3 ) + 2 )
    {
        ch_println( ch, "&wYou aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
        return;
    }

    if ( code > 0 )
        encrypt = TRUE;

    if ( has_pcflag( ch, PCFLAG_AUTOFORMAT ) )
        argument = autoformat_string( argument );

    argument = drunk_speech( argument, ch );

    if ( ch->in_room && ch->in_room->area )
    {
        CHAR_DATA* rch = NULL;

        for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        {
            if ( rch == ch )
                continue;

            if ( rch->position < POS_RESTING )
                continue;

            if ( ch->in_room->area->ambience == 1 )
            {
                if ( !knows_language( rch, ch->speaking, ch ) && ( !IS_NPC( ch ) || !xIS_EMPTY( ch->speaking ) ) )
                {
                    ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), scramble_text( argument, ch->speaking ) );
                }
                else
                    ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), argument );
            }
            else
            {
                ch_println( rch, "&z%s %swhispers into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ) );
            }
        }
    }

    shift_points( ch, 2 );
    if ( is_disrupted( ch, TAP_COMM, false ) && !IS_IMMORTAL( ch ) )
        return;

    for ( CHAR_DATA* rch = first_char; rch; rch = rch->next )
    {
        // Safety fix for preloaded characters
        if ( !rch->in_room )
            continue;

        if ( xIS_SET( rch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( rch ) )
            continue;

        encrypt = code != 0;
        if ( !IS_NPC( rch ) )
        {
            has_comlink = FALSE;
            if ( !IS_IMMORTAL( rch ) )
            {
                if ( !IS_AWAKE( rch ) )
                    continue;
                if ( is_cg( ch ) != is_cg( rch ) )
                    continue;
            }
            if ( xIS_SET( rch->in_room->flags, ROOM_COMMSHIELD ) )
                continue;

            for ( obj = rch->last_carrying; obj; obj = obj->prev_content )
                if ( ( obj->item_type == ITEM_COMLINK || obj->item_type == ITEM_MONITOR ) && obj->value[5] == channel )
                {
                    if ( obj->value[4] == code )
                        encrypt = FALSE;
                    has_comlink = TRUE;
                }

            if ( get_trust( rch ) >= 105 || ( IS_IMMORTAL( rch ) && !check_multi( rch->desc ) ) )
                encrypt = FALSE;

            // When they have a comlink tuned to the channel, prefer that and skip tap output.
            // Comlink output is at least as good (since it might be decrypted)
            if ( !has_comlink )
            {
                TIMER* timer = get_timerptr( rch, TIMER_DO_FUN );
                if ( timer && !str_cmp( timer->buffer->func, "do_datatap" ) )
                {
                    TAP_DATA* tap = ( TAP_DATA* )timer->buffer->buf1;
                    if ( tap && tap->type == TAP_COMM && get_on_planet( ch ) == get_on_planet( rch ) )
                    {
                        act_tap( fmt_talk_output(ch, rch, channel, code, encrypt, hapanlink, argument), rch );
                    }
                }
            }

            if ( xIS_SET( rch->deaf, CHANNEL_TALK ) )
                continue;

            // Imms see all talk output as long as they're >= 105 or not morting
            if ( !IS_IMMORTAL( rch ) || ( check_multi( rch->desc ) && get_trust( rch ) < 105 ) )
                if ( !has_comlink )
                    continue;

            // This check is after tapdata output - when tapping, you can still see what
            // people are trying to say even though nobody else can.
            if ( is_disrupted( rch, TAP_COMM, true ) )
                continue;

            send_to_char( fmt_talk_output(ch, rch, channel, code, encrypt, hapanlink, argument), rch );
        }
        else if ( rch->droid_data )
        {
            DROID_DATA* dd = rch->droid_data;
            if ( dd->mode != DROID_MODE_TRANSLATION || dd->active != DROID_STATE_ASSIST )
                continue;

            obj = rch->curr_comlink;
            if ( obj && obj->value[5] == channel  )
            {
                if ( obj->value[4] == code || code == 0 )
                    encrypt = FALSE;

                // Droids do not translate the same language they're speaking
                if ( xIS_EMPTY( rch->speaking ) )
                    xSET_BIT( rch->speaking, LANG_BASIC );
                if ( code == 0 && xHAS_BITS( rch->speaking, ch->speaking ) )
                    continue;

                snprintf( buf, MSL, "say &z(&WTranslating channel &C%d&z) %s%s", obj->value[5], txtclr( rch ), encrypt ? "Unable to decipher encryption" : argument );
                interpret( rch, buf, FALSE );
                addDroidExperience_b( dd, strlen( argument ) * ( getDroidLevel( dd->exp ) + 1 ) );
            }
        }
    }

    return;
}
