/**
    Goes through any microphones in the room, or in the inventory or containers of
    characters in the room, and triggers relay on each.
    @param ch Character talking into the microphone
    @param say_text Message to relay
*/
void relay_microphones( CHAR_DATA* ch, const char* say_text )
{
    CHAR_DATA* vch;
    OBJ_DATA* obj, *content;

    /* Gral: Ignore Immortal Staff talking. Especially at 100 chatter */
    if ( IS_IMMORTAL( ch ) )
        return;

    /*Microphones should not work if the planet is disrupted. - Gathorn 4May19 */
    if ( is_disrupted( ch, TAP_COMM, TRUE ) )
        return;

    if ( speaking_silent_language( ch ) )
        return;

    /* If an imm is in the room and not invis, the room is "OOC" and whatever's discussed shouldn't be relayed */
    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
        if ( IS_IMMORTAL( vch ) && !has_pcflag( vch, PCFLAG_WIZINVIS ) )
            return;

    // Look for and trigger microphones on players in the room
    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
    {    
        // If they're AFK, they're not transmitting.
        if ( has_pcflag( vch, PCFLAG_AFK ) )
            continue;

        for ( obj = vch->last_carrying; obj; obj = obj->prev_content )
            if ( obj->item_type == ITEM_MICROPHONE )
                relay_microphone( ch, obj->value[0], say_text );
            else if ( obj->item_type == ITEM_CONTAINER )
                for ( content = obj->first_content; content; content = content->next_content )
                    if ( content->item_type == ITEM_MICROPHONE )
                        relay_microphone( ch, content->value[0], say_text );
    }

    // Look for and trigger microphones in the same room.
    for ( obj = ch->in_room->first_content; obj; obj = obj->next_content )
        if ( obj->item_type == ITEM_MICROPHONE && obj->value[0] > 0 )
            relay_microphone( ch, obj->value[0], say_text );
}

/**
    Relays a msg to all ppl with comlinks tuned to the same channel.
    @author Ghost
    @param ch Character talking into the microphone
    @param channel Channel to relay message to
    @param say_text Message to relay
*/
void relay_microphone( CHAR_DATA* ch, int channel, const char* say_text )
{
    DESCRIPTOR_DATA* d;
    OBJ_DATA* obj;
    char* vch_heard_text;
    SPACE_DATA* dsys = NULL;
    SPACE_DATA* chsys = NULL;

    /* Ignore Microphones on Channel 0 */
    if ( channel == 0 )
        return;

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING )
            continue;

        if ( !d->character )
            continue;

        if ( d->character->position <= POS_SLEEPING )
            continue;

        if ( !d->character->in_room->area )
            continue;

        if ( !ch->in_room->area )
            continue;

        dsys = starsystem_from_vnum( d->character->in_room->vnum );
        chsys = starsystem_from_vnum( ch->in_room->vnum );

        if ( dsys != chsys )
            continue;

        vch_heard_text = translate_for_target( ch, d->character, say_text );

        /* Look for receiving devices... Mainly Comlinks... */
        // Gral Do we want to enable/disable Immortals seeing the buzzing?
        if ( ( get_trust ( d->character ) >= LEVEL_PR_ADMIN ) && !xIS_SET( d->character->deaf, CHANNEL_MICROPHONE ) )
            ch_println( d->character, "&zMicrophone on channel %d buzzes '%s&z'", channel, stripclr( vch_heard_text ) );

        for ( obj = d->character->last_carrying; obj; obj = obj->prev_content )
        {
            if ( !obj || obj == NULL )
                continue;

            // Ralen let's actually show which comlink is buzzing.
            if ( obj->item_type == ITEM_COMLINK && obj->value[5] == channel )
                ch_println( d->character, "&z%s&z buzzes '%s&z'", obj->short_descr, stripclr( vch_heard_text ) );
            else if ( obj->item_type == ITEM_MONITOR && obj->value[0] == channel )
                ch_println( d->character, "&z%s&z buzzes '%s&z'", obj->short_descr, stripclr( vch_heard_text ) );
        }
    }

    return;
}

/**
    Finds any translator droids in the room and triggers them to translate the given text.
    @param speaker the character who spoke
    @param say_text the message (in their spoken language) to translate
*/
void activate_translator_droids( CHAR_DATA* speaker, const char* say_text )
{
    char droid_cmd[MIL];
    CHAR_DATA* vch = NULL;
    DROID_DATA* db = NULL;
    bool found_droid = FALSE;
    int text_len;
    char buf[MSL];

    if ( !speaker || char_extracted( speaker ) || IS_IMMORTAL( speaker ) )
        return;

    if ( IS_NPC( speaker ) && xIS_SET( speaker->act, ACT_DROID ) && ( db = droid_from_mob( speaker ) ) != NULL && db->mode == DROID_MODE_TRANSLATION )
        return;

    if ( speaking_silent_language( speaker ) )
        return;

    if ( !str_prefix( TRANSLATED_PREFIX, say_text ) )
        return; // Avoid infinite translation loop with multiple droids

    strlcpy( buf, say_text, MSL );
    text_len = strlen( stripclr( buf ) );

    for ( vch = speaker->in_room->first_person; vch; vch = vch->next_in_room )
    {
        if ( vch == speaker )
            continue; // Droids shouldn't translate themselves.

        if ( ( db = droid_from_mob( vch ) ) != NULL )
        {
            if ( db->mode == 2 && db->active == 2 )
            {
                // Droids do not translate the same language they're speaking
                if ( xIS_EMPTY( vch->speaking ) )
                    xSET_BIT( vch->speaking, LANG_BASIC );

                if ( xHAS_BITS( vch->speaking, speaker->speaking ) )
                    continue;

                bool can_translate = true;

                if ( xIS_SET( speaker->speaking, LANG_CLAN ) || xIS_SET( speaker->speaking, LANG_YUUZHAN_VONG ) )
                    can_translate = false;

                snprintf( droid_cmd, MIL, "say %s %s%s", TRANSLATED_PREFIX, txtclr( vch ), can_translate ? say_text : "Unable to translate..." );
                interpret( vch, droid_cmd, FALSE );
                addDroidExperience_b( db, URANGE( 10, number_range( 10, 25 )*text_len, 2500 ) );
                found_droid = TRUE;
            }
        }
    }

    if ( db && found_droid )
        save_droid( db, TRUE );
}

/**
    In-room OOC chat
    @see do_ooc
    @author Orion
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_osay( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    CHAR_DATA* rch = NULL;
    //int cnt=0;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cosay <&wmessage&C>&w" );
        ch_println( ch, "&wosay sends an out-of-character message to the other people in the room." );
        return;
    }

    if ( is_silenced( ch ) )
    {
        ch_println( ch, "You can't do that!" );
        return;
    }

    if ( xIS_SET( ch->deaf, CHANNEL_OSAY ) )
    {
        ch_println( ch, "Try turning on osay first (CHANNELS +OSAY)" );
        return;
    }

    if ( !has_pcflag( ch, PCFLAG_NCOUNCIL ) && ooc_break_check( ch, 2 ) )
        return;

    snprintf( buf, MSL, "%s%s", txtclr( ch ), argument );
    ch_println( ch, "&Y(&zOSAY&Y) &WYou say &Y'%s&Y'", buf );

    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( ch == rch )
            continue;

        if ( xIS_SET( rch->deaf, CHANNEL_OSAY ) )
            continue;

        ch_println( rch, "&Y(&zOSAY&Y) &W%s says &Y'%s&Y'", g_name( ch, rch ), buf );
    }

    return;
}

/**
    In-room IC chat channel
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_say( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Say what?" );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && !IS_RPC( ch ) && has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "You cannot do that while AFK." );
        return;
    }

    process_say( ch, NULL, argument );
}

/**
    Directed say message (IC)
    @see do_say
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_sayto( CHAR_DATA* ch, char* argument )
{
    char victim_name[MIL];
    char* say_text;
    CHAR_DATA* victim;
    say_text = one_argument( argument, victim_name );

    if ( NULLSTR( say_text ) )
    {
        ch_println( ch, "Say what, and to whom?" );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && !IS_RPC( ch ) && has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "You cannot do that while AFK." );
        return;
    }

    if ( ( victim = get_char_room( ch, victim_name ) ) == NULL )
    {
        ch_println( ch, "You don't see anyone like that nearby." );
        return;
    }

    process_say( ch, victim, say_text );
}

bool speaking_silent_language( CHAR_DATA* speaker )
{
    if ( xIS_SET( speaker->speaking, LANG_LORRDIAN ) )
        return TRUE;

    return FALSE;
}

/**
    Translate the given text as target would see it, returning an empty string if it's inaudible
*/
char* translate_for_target( CHAR_DATA* ch, CHAR_DATA* target, const char* say_text )
{
    static char result[MIL];
    strlcpy( result, say_text, MIL );

    if ( !ch || !target || char_extracted( ch ) || char_extracted( target ) )
        return result;

    if ( target != ch && !knows_language( target, ch->speaking, ch ) )
    {
        //if ( speaking_silent_language( ch ) )
        // Player doesn't understand this silent language, so the result is empty.
        //    result[0] = '\0';
        if ( !IS_NPC( ch ) || !xIS_EMPTY( ch->speaking ) )
            strlcpy( result, scramble_text( say_text, ch->speaking ), MIL );
    }

    return result;
}

void process_say( CHAR_DATA* ch, CHAR_DATA* victim, char* say_text )
{
    char orig_say_text[MIL];
    char last_char;
    char* vch_heard_text;
    char buf[MSL];
    CHAR_DATA* vch;
    EXT_BV actflags;
    OBJ_DATA* tobj;
    ROOM_INDEX_DATA* troom = NULL;
    bool can_see_lorrdian;

    if ( check_ooc_in_ic_message( ch, say_text, __FUNCTION__ ) )
        return;

    if ( has_pcflag( ch, PCFLAG_AUTOFORMAT ) )
        say_text = autoformat_string( say_text );

    if ( !IS_NPC( ch ) && count_args( say_text ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than three words in length!" );
        return;
    }
    else if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( say_text ) > ( get_curr_int( ch ) / 3 ) + 2 )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch )  )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n makes a feeble attempt to make some noises.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't say anything to people while gagged." );
        return;
    }

    last_char = say_text[strlen( say_text ) - 1];
    char* say_verb = last_char == '!' ? ( speaking_silent_language( ch ) ? "exclaim in sign" : "exclaim" ) : last_char == '?' ? ( speaking_silent_language( ch ) ? "ask in sign" : "ask" ) : ( speaking_silent_language( ch ) ? "sign" : "say" );
    char* says_verb = last_char == '!' ? ( speaking_silent_language( ch ) ? "exclaims in sign" : "exclaims" ) : last_char == '?' ? ( speaking_silent_language( ch ) ? "asks in sign" : "asks" ) : ( speaking_silent_language( ch ) ? "signs" : "says" );
    char* say_to_verb = last_char == '!' ? ( speaking_silent_language( ch ) ? "exclaim in sign at" : "exclaim at" ) : last_char == '?' ? ( speaking_silent_language( ch ) ? "ask a question in sign to" : "ask" ) : ( speaking_silent_language( ch ) ? "sign to" : "say to" );
    char* says_to_verb = last_char == '!' ? ( speaking_silent_language( ch ) ? "exclaims in sign at" : "exclaims at" ) : last_char == '?' ? ( speaking_silent_language( ch ) ? "asks a question in sign to" : "asks" ) : ( speaking_silent_language( ch ) ? "signs to" : "says to" );
    strlcpy( orig_say_text, say_text, MIL ); // Preserve original text for progs and lifts, which can hear through drunkenness
    say_text = drunk_speech( orig_say_text, ch );
    // Temporarily lift the SECRETIVE flag for speaking mobs, then restore it after
    actflags = ch->act;

    if ( IS_NPC( ch ) )
        xREMOVE_BIT( ch->act, ACT_SECRETIVE );

    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
    {
        if ( vch != ch && !IS_NPC( ch ) && !IS_NPC( vch ) )
        {
            shift_points( ch, 1 );
            shift_points( vch, 1 );
        }

        MOBtrigger = FALSE; // Don't trigger off the act() we're about to do

        if ( vch == ch )
        {
            if ( victim == NULL )
            {
                snprintf( buf, MSL, "You %s%s%s '%s$T&C^d'", tone_convert( ch, NULL ), say_verb, lang_convert( ch, ch->speaking, ch ), txtclr( ch ) );

                if ( number_range( 1, 3 ) == 3 && strlen( stripclr( say_text ) ) <= 10 )
                    snprintf( buf, MSL, "&C^d'%s$T&C^d' you %s%s%s.", txtclr( ch ), tone_convert( ch, NULL ), say_verb, lang_convert( ch, ch->speaking, ch ) );
            }
            else
            {
                snprintf( buf, MSL, "&C^dYou %s%s %s%s '%s$T&C^d'", tone_convert( ch, NULL ), say_to_verb, g_name( victim, ch ), lang_convert( ch, ch->speaking, ch ), txtclr( ch ) );

                if ( number_range( 1, 3 ) == 3 && strlen( stripclr( say_text ) ) <= 10 )
                    snprintf( buf, MSL, "&C^d'%s$T&C^d' you %s%s %s%s.", txtclr( ch ), tone_convert( ch, NULL ), say_to_verb, g_name( victim, ch ), lang_convert( ch, ch->speaking, ch ) );
            }

            act( AT_SAY, buf, ch, NULL, say_text, TO_CHAR );
        }
        else
        {
            if ( speaking_silent_language( ch ) )
            {
                can_see_lorrdian = FALSE;

                if ( IS_IMMORTAL( vch ) )
                    can_see_lorrdian = TRUE;
                else if ( knows_language( vch, ch->speaking, ch ) )
                    can_see_lorrdian = TRUE;
                else if ( vch->skill_level[FORCE_ABILITY] > 10 )
                    can_see_lorrdian = TRUE;
                else if ( !IS_AFFECTED( vch, AFF_BLIND ) && vch->skill_level[FORCE_ABILITY] <= 10 && number_range( 1, 6 - ( int )( vch->perm_wis / 5 ) ) == 1 )
                    can_see_lorrdian = TRUE;

                if ( can_see_lorrdian == FALSE )
                    continue;
            }

            vch_heard_text = translate_for_target( ch, vch, say_text );

            // if ( NULLSTR( vch_heard_text ) )
            // Player doesn't understand this silent language, so we skip them.
            //     continue;

            if ( victim == NULL )
            {
                snprintf( buf, MSL, "$n %s%s%s '%s$t&C^d'", tone_convert( ch, vch ), says_verb, lang_convert( vch, ch->speaking, ch ), txtclr( ch ) );

                if ( number_range( 1, 3 ) == 3 && strlen( stripclr( vch_heard_text ) ) <= 10 )
                    snprintf( buf, MSL, "&C^d'%s$t&C^d' $n %s%s%s.", txtclr( ch ), tone_convert( ch, vch ), says_verb, lang_convert( vch, ch->speaking, ch ) );
            }
            else if ( vch == victim )
            {
                snprintf( buf, MSL, "$n %s%s you%s '%s$t&C^d'", tone_convert( ch, vch ), says_to_verb, lang_convert( vch, ch->speaking, ch ), txtclr( ch ) );

                if ( number_range( 1, 3 ) == 1 && strlen( stripclr( vch_heard_text ) ) <= 10 )
                    snprintf( buf, MSL, "'%s$t&C^d' $n %s%s you%s.", txtclr( ch ), tone_convert( ch, vch ), says_to_verb, lang_convert( vch, ch->speaking, ch ) );
            }
            else
            {
                snprintf( buf, MSL, "$n %s%s %s%s '%s$t&C^d'", tone_convert( ch, vch ), says_to_verb, g_name( victim, vch ), lang_convert( vch, ch->speaking, ch ), txtclr( ch ) );

                if ( number_range( 1, 3 ) == 1 && strlen( stripclr( vch_heard_text ) ) <= 10 )
                    snprintf( buf, MSL, "'%s$t&C^d' $n %s%s %s%s.", txtclr( ch ), tone_convert( ch, vch ), says_to_verb, g_name( victim, vch ), lang_convert( vch, ch->speaking, ch ) );
            }

            act( AT_SAY, buf, ch, vch_heard_text, vch, TO_VICT );
        }
    }

    for ( TRANSMIT_DATA* transmit = first_transmit; transmit; transmit = transmit->next )
    {
        if ( !transmitter_sending_from_room( transmit, ch->in_room ) )
            continue;

        snprintf( buf, MSL, "&cBinary data detected on holotransmitter channel %d.\n", transmit->channel );
        push_to_taps( ch->in_room, TAP_COMM, buf );

        for ( TRANSMIT_RECEIVER* rcv = transmit->first_connected; rcv; rcv = rcv->next )
        {
            tobj = rcv->transmitter;

            if ( tobj->value[IVAL_TRANSMITTER_MODE] == IVAL_TRANSMITTER_MODE_SEND )
                continue;

            troom = tobj->in_room ? tobj->in_room : tobj->carried_by ? tobj->carried_by->in_room : NULL;

            if ( !troom || troom == ch->in_room )
                continue;

            for ( vch = troom->first_person; vch; vch = vch->next_in_room )
            {
                vch_heard_text = translate_for_target( ch, vch, say_text );

                if ( NULLSTR( vch_heard_text ) )
                    // Player doesn't understand this silent language, so we skip them.
                    continue;

                if ( victim == NULL )
                {
                    snprintf( buf, MSL, "&z<&WHolo&z> &033$n %s%s%s '%s$t&033'", tone_convert( ch, vch ), says_verb, lang_convert( vch, ch->speaking, ch ), txtclr( ch ) );

                    if ( number_range( 1, 3 ) == 3 && strlen( stripclr( vch_heard_text ) ) <= 10 )
                        snprintf( buf, MSL, "&z<&WHolo&z> &033'%s$t&033' $n %s%s%s.", txtclr( ch ), tone_convert( ch, vch ), says_verb, lang_convert( vch, ch->speaking, ch ) );
                }
                else
                {
                    snprintf( buf, MSL, "&z<&WHolo&z> &033$n %s%s %s%s '%s$t&033'", tone_convert( ch, vch ), says_to_verb, g_name( victim, vch ), lang_convert( vch, ch->speaking, ch ), txtclr( ch ) );

                    if ( number_range( 1, 3 ) == 1 && strlen( stripclr( vch_heard_text ) ) <= 10 )
                        snprintf( buf, MSL, "&z<&WHolo&z> &033'%s$t&033' $n %s%s %s%s.", txtclr( ch ), tone_convert( ch, vch ), says_to_verb, g_name( victim, vch ), lang_convert( vch, ch->speaking, ch ) );
                }

                act( AT_SAY, buf, ch, vch_heard_text, vch, TO_VICT );
            }
        }
    }

    relay_microphones( ch, say_text );
    activate_translator_droids( ch, say_text );

    if ( victim != NULL && victim->ai_data )
        ai_react( victim, ch, "say", orig_say_text );

    ch->act = actflags; // In case we modified their SECRETIVE flag

    if ( xIS_SET( ch->in_room->flags, ROOM_LOGSPEECH ) )
    {
        snprintf( buf, MSL, "[%d] %s: %s", ch->in_room->vnum, IS_NPC( ch ) ? ch->short_descr : ch->name, orig_say_text );
        append_to_file( LOG_FILE, buf );
    }

    if ( victim == NULL )
    {
        //TURBOLIFT CALLING by Rojan
        //KEYCARDS ADDED by Nield (if they break, blame him)
        TURBOLIFT_DATA* lift = NULL;
        TURBOFLOOR_DATA* floor = NULL;
        OBJ_INDEX_DATA* lkeycard = NULL, *fkeycard = NULL;
        OBJ_DATA* lkc = NULL, *fkc = NULL;
        bool has_clan = false, clan_match = true, rank_match = true;

        if ( ( lift = get_lift( ch->in_room->vnum ) ) != NULL )
        {
            if ( !NULLSTR( lift->clanlist ) )
                has_clan = true;

            if ( has_clan && ( IS_NPC( ch ) || !ch->pcdata->clan || !hasname( lift->clanlist, ch->pcdata->clan->shortname ) ) )
                clan_match = false;

            if ( lift->keycard > 0 )
                lkeycard = get_obj_index( lift->keycard );

            if ( lkeycard )
                for ( lkc = ch->first_carrying; lkc; lkc = lkc->next_content )
                    if ( lkc->pIndexData && lkc->pIndexData == lkeycard )
                        break;

            if ( ( floor = get_floor_from_arg( lift, orig_say_text ) ) != NULL )
            {
                if ( floor->keycard > 0 )
                    fkeycard = get_obj_index( floor->keycard );

                if ( fkeycard )
                    for ( fkc = ch->first_carrying; fkc; fkc = fkc->next_content )
                        if ( fkc->pIndexData && fkc->pIndexData == fkeycard )
                            break;

                if ( has_clan && ( !clan_match || ch->pcdata->clan_rank < floor->rank ) )
                    rank_match = false;

                if ( !floor->enabled )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->disabled ) ? "&RThe turbolift beeps angrily.\n" : floor->disabled ); //"The turbolift beeps angrily or something (lift/floor disabled)."
                else if ( !lift->enabled )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->disabled ) ? "&RThe turbolift beeps angrily.\n" : lift->disabled ); //"The turbolift beeps angrily or something (lift/floor disabled)."
                else if ( floor->current )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->alreadyonfloor_in ) ? "&RThe turbolift beeps angrily.\n" : lift->alreadyonfloor_in ); //"The turbolift beeps angrily or something (already on that level)."
                // If a clan list is set and the character isn't in the clan and either there isn't a lift/floor keycard or they don't have that keycard, fail out.
                else if ( !IS_IMMORTAL( ch ) && has_clan && !clan_match && ( !lkeycard || !lkc ) && ( !fkeycard || !fkc ) )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->wrongclan ) ? "&RThe turbolift beeps angrily.\n" : lift->wrongclan ); //"The turbolift beeps angrily or something (not in the right clan)."
                // If a floor's rank is set and the character doesn't have high enough rank and either there isn't a floor-specific keycard or they don't have it, fail out. 
                else if ( !IS_IMMORTAL( ch ) && has_clan && floor->rank > 0 && !rank_match && ( !fkeycard || !fkc ) )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->ranktoolow ) ? "&RThe turbolift beeps angrily.\n" : floor->ranktoolow ); //"The turbolift beeps angrily or something (not high enough rank)."
                // If there isn't a clan, start looking more closely for keycards. If the lift has a keycard set and they don't have it, fail out.
                else if ( !IS_IMMORTAL( ch ) && !has_clan && lkeycard && !lkc )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->nokeycard ) ? "&RThe turbolift beeps angrily.\n" : lift->nokeycard );
                // If the floor has a specific keycard set and they don't have it, fail out.
                else if ( !IS_IMMORTAL( ch ) && ( !has_clan || floor->rank == 0 ) && fkeycard && !fkc )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->nokeycard ) ? "&RThe turbolift beeps angrily.\n" : floor->nokeycard );
                else if ( lift->timer > 0 )
                    echo_to_room( AT_PLAIN, ch->in_room, "&RA loud beep resounds signaling the turbolift is already in use.\n" );
                else
                    move_lift( lift, floor );
            }
        }
        else if ( ( floor = get_floor( NULL, ch->in_room->vnum ) ) != NULL )
        {
            if ( is_name( rempunc( strlower( orig_say_text ) ), "lift" ) || is_name( rempunc( strlower( orig_say_text ) ), "turbolift" ) || is_name( rempunc( strlower( orig_say_text ) ), "call" ) )
            {
                lift = get_lift_from_floor( floor );

                if ( !NULLSTR( lift->clanlist ) )
                    has_clan = true;

                if ( has_clan && ( IS_NPC( ch ) || !ch->pcdata->clan || !hasname( lift->clanlist, ch->pcdata->clan->shortname ) ) )
                    clan_match = false;

                if ( lift->keycard > 0 )
                    lkeycard = get_obj_index( lift->keycard );

                if ( lkeycard )
                    for ( lkc = ch->first_carrying; lkc; lkc = lkc->next_content )
                        if ( lkc->pIndexData && lkc->pIndexData == lkeycard )
                            break;

                if ( floor->keycard > 0 )
                    fkeycard = get_obj_index( floor->keycard );

                if ( fkeycard )
                    for ( fkc = ch->first_carrying; fkc; fkc = fkc->next_content )
                        if ( fkc->pIndexData && fkc->pIndexData == fkeycard )
                            break;

                if ( has_clan && ( !clan_match || ch->pcdata->clan_rank < floor->rank ) )
                    rank_match = false;

                if ( !floor->enabled )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->disabled ) ? "&RThe turbolift beeps angrily.\n" : floor->disabled ); //"The turbolift beeps angrily or something (lift/floor disabled)."
                else if ( !lift->enabled )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->disabled ) ? "&RThe turbolift beeps angrily.\n" : lift->disabled ); //"The turbolift beeps angrily or something (lift/floor disabled)."
                else if ( floor->current )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->alreadyonfloor_out ) ? "&RThe turbolift beeps angrily.\n" : lift->alreadyonfloor_out ); //"The turbolift beeps angrily or something (already on that level)."
                else if ( !IS_IMMORTAL( ch ) && has_clan && !clan_match && ( !lkeycard || !lkc ) && ( !fkeycard || !fkc ) )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->wrongclan ) ? "&RThe turbolift beeps angrily.\n" : lift->wrongclan ); //"The turbolift beeps angrily or something (not in the right clan)."
                else if ( !IS_IMMORTAL( ch ) && has_clan && floor->rank > 0 && !rank_match && ( !fkeycard || !fkc ) )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->ranktoolow ) ? "&RThe turbolift beeps angrily.\n" : floor->ranktoolow ); //"The turbolift beeps angrily or something (not high enough rank)."
                else if ( !IS_IMMORTAL( ch ) && !has_clan && lkeycard && !lkc )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( lift->nokeycard ) ? "&RThe turbolift beeps angrily.\n" : lift->nokeycard );
                // If the floor has a specific keycard set and they don't have it, fail out.
                else if ( !IS_IMMORTAL( ch ) && ( !has_clan || floor->rank == 0 ) && fkeycard && !fkc )
                    echo_to_room( AT_PLAIN, ch->in_room, NULLSTR( floor->nokeycard ) ? "&RThe turbolift beeps angrily.\n" : floor->nokeycard );
                else if ( lift->timer > 0 )
                    echo_to_room( AT_PLAIN, ch->in_room, "&RA loud beep resounds signaling the turbolift is already in use.\n" );
                else
                    move_lift( lift, floor );
            }
        }
    }

    if ( !str_prefix( TRANSLATED_PREFIX, orig_say_text ) )
        return;

    // Capture now in case progs move them
    ROOM_INDEX_DATA* room = ch->in_room;
    lua_trigger_on_ch_speech( ch, orig_say_text );

    if( victim != NULL ) {
        lua_trigger_on_ch_sayto( ch, victim, orig_say_text );
    }

    if ( char_extracted( ch ) )
        return;

    mprog_speech_trigger( orig_say_text, ch );

    if ( char_extracted( ch ) )
        return;

    lua_trigger_on_obj_speech( ch, orig_say_text );

    if ( char_extracted( ch ) )
        return;

    oprog_speech_trigger( orig_say_text, ch );

    if ( char_extracted( ch ) )
        return;

    lua_trigger_on_room_speech( room, ch, orig_say_text );

    if ( char_extracted( ch ) )
        return;

    rprog_speech_trigger( orig_say_text, ch );
    return;
}

/**
    IC in-room private communication
    Allows you to whisper to a player/NPC you are approached to
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_whisper( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL];
    CHAR_DATA* victim;
    int position;
    xREMOVE_BIT( ch->deaf, CHANNEL_WHISPER );
    argument = one_argument( argument, arg );

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "Whisper to whom what?" );
        return;
    }

    // GRAL Stopped whisper while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n makes a feeble attempt to make some noises.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't whisper while gagged." );
        return;
    }

    if ( check_ooc_in_ic_message( ch, argument, __FUNCTION__ ) )
        return;

    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "The language of the Lorrdians is physical." );
        return;
    }

    if ( !IS_NPC( ch ) && count_args( argument ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than three words in length!" );
        return;
    }
    else if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( argument ) > ( get_curr_int( ch ) / 3 ) + 2 )
    {
        ch_println( ch, "You aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "You have a nice little chat with yourself." );
        return;
    }

    if ( !IS_NPC( victim ) && ( victim->switched )
            && !IS_AFFECTED( victim->switched, AFF_POSSESS ) )
    {
        ch_println( ch, "That player is switched." );
        return;
    }
    else if ( !IS_NPC( victim ) && ( !victim->desc ) )
    {
        ch_println( ch, "That player is link-dead." );
        return;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        return;
    }

    if ( xIS_SET( victim->deaf, CHANNEL_WHISPER )
            && ( !IS_IMMORTAL( ch ) || ( get_trust( ch ) < get_trust( victim ) ) ) )
    {
        act( AT_PLAIN, "$E has $S whispers turned off.", ch, NULL, victim,
             TO_CHAR );
        return;
    }

    /*    if ( !IS_NPC(victim) && has_pcflag( victim, PCFLAG_SILENCE ) )
        ch_println( ch, "That player is silenced.  They will receive your message but can not respond." );
    */
    if ( victim->desc       /* make sure desc exists first  -Thoric */
            &&   victim->desc->connected == CON_EDITING
            &&   get_trust( ch ) < LEVEL_GOD )
    {
        act( AT_PLAIN, "$E is currently in a writing buffer.  Please try again in a few minutes.", ch, 0, victim, TO_CHAR );
        return;
    }

    snprintf( buf, MSL, "&CYou %swhisper to $N '%s$t&C'", tone_convert( ch, NULL ), txtclr( ch ) );
    act( AT_WHISPER, buf, ch, drunk_speech( argument, ch ), victim, TO_CHAR );
    position        = victim->position;
    victim->position    = POS_STANDING;
    snprintf( buf, MSL, "&C$n %swhispers to you '%s$t&C'", tone_convert( ch, victim ), txtclr( ch ) );
    // GRAL Missing language check
    act( AT_WHISPER, buf, ch, !knows_language( victim, ch->speaking, ch ) && ( !IS_NPC( ch ) || !xIS_EMPTY( ch->speaking ) )
         ? drunk_speech( scramble_text( argument, ch->speaking ), ch ) : drunk_speech( argument, ch ), victim, TO_VICT );

    if ( !xIS_SET( ch->in_room->flags, ROOM_SILENCE ) )
    {
        snprintf( buf, MSL, "&C$n %swhispers something to $N.", tone_convert( ch, victim ) );
        act( AT_WHISPER, buf, ch, argument, victim, TO_NOTVICT );
    }

    victim->position    = position;

    if ( xIS_SET( ch->in_room->flags, ROOM_LOGSPEECH ) )
    {
        snprintf( buf, MSL, "[%d] %s: %s (whisper to) %s.", ch->in_room->vnum, IS_NPC( ch ) ? ch->short_descr : ch->name, drunk_speech( argument, ch ), IS_NPC( victim ) ? victim->short_descr : victim->name );
        append_to_file( LOG_FILE, buf );
    }

    lua_trigger_on_ch_speech( ch, argument );

    if ( char_extracted( ch ) )
        return;

    mprog_speech_trigger( argument, ch );
    return;
}

