/**
    OOC private chat channel from 1 player to another
    @see do_reply
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_tell( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[SUPER_MIL];
    CHAR_DATA* victim = NULL;
    int position;
    CHAR_DATA* switched_victim = NULL;
    bool toaccount = FALSE;
    xREMOVE_BIT( ch->deaf, CHANNEL_TELLS );

    if ( xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch )  )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( is_silenced( ch ) || has_pcflag( ch, PCFLAG_NO_TELL ) )
    {
        ch_println( ch, "You can't do that." );
        return;
    }

    argument = one_argument( argument, arg );

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "Tell whom what?" );
        return;
    }

    if ( strlen( argument ) > 254  && get_trust( ch ) < sysdata.log_level )
    {
        argument[254] = '\0';
        ch_println( ch, "&WLine too long. Please cut down the spam." );
    }

    if ( arg[0] == '@' )
    {
        ACCOUNT_DATA* acc = NULL;
        DESCRIPTOR_DATA* d = NULL;

        if ( ( acc = get_account( arg + 1 ) ) == NULL )
        {
            ch_println( ch, "There is no account by that name." );
            return;
        }

        for ( d = first_descriptor; d; d = d->next )
        {
            if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                continue;

            if ( !d->account || d->account != acc )
                continue;

            victim = d->character;
            toaccount = TRUE;
        }
    }

    if ( !has_pcflag( ch, PCFLAG_NCOUNCIL ) && ooc_break_check( ch, 1 ) )
        return;

    if ( !victim )
        victim = get_char_world_full( ch, arg );

    if ( victim == NULL )
    {
        arg[0] = toupper( arg[0] );
        snprintf( buf, SUPER_MIL, "(%s) You tell %s '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg );
        act( AT_TELL, buf, ch, argument, NULL, TO_CHAR );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "You have a nice little chat with yourself." );
        return;
    }

    if ( IS_IMMORTAL( victim ) )
    {
        ch_println( ch, "Please use IMMCHAT to communicate with staff." );
        return;
    }
    else if ( IS_RPC( victim ) )
    {
        ch_println( ch, "Please use RPC to communicate with the Roleplay Council." );
        return;
    }

    if ( NOT_AUTHED( ch ) && !NOT_AUTHED( victim ) && !IS_IMMORTAL( victim ) )
    {
        ch_println( ch, "They can't hear you because you are not authorized." );
        return;
    }

    if ( xIS_SET( victim->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( victim ) )
    {
        arg[0] = toupper( arg[0] );
        snprintf( buf, SUPER_MIL, "(%s) You tell %s '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg );
        act( AT_TELL, buf, ch, argument, NULL, TO_CHAR );
        // ch_println( ch, "&RPublic communication channels are not available to them." );
        return;
    }

    if ( IS_SWITCHED_PC( victim ) )
        switched_victim = victim->switched;
    else if (
        ( !IS_NPC( victim ) && ( !victim->desc ) ) ||
        ( xIS_SET( victim->deaf, CHANNEL_TELLS ) && ( !IS_IMMORTAL( ch ) || ( get_trust( ch ) < get_trust( victim ) ) ) ) ||
        ( is_silenced( victim ) ) ||
        ( !IS_NPC( victim ) && xIS_SET( victim->in_room->flags, ROOM_SILENCE ) ) ||
        ( victim->desc && victim->desc->connected == CON_EDITING && get_trust( ch ) < LEVEL_GOD )
    )
    {
        arg[0] = toupper( arg[0] );
        snprintf( buf, SUPER_MIL, "(%s) You tell %s '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg );
        act( AT_TELL, buf, ch, argument, NULL, TO_CHAR );
        return;
    }

    if ( switched_victim )
        victim = switched_victim;

    arg[0] = toupper( arg[0] );

    if ( toaccount )            // Stop Account Fishing
        snprintf( buf, SUPER_MIL, "(%s) You tell %s%s&B '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ( ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ) ? "&B" : "", arg );
    else
        snprintf( buf, SUPER_MIL, "(%s) You tell %s&B '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", arg );

    act( AT_TELL, buf, ch, argument, NULL, TO_CHAR );
    position        = victim->position;
    victim->position    = POS_STANDING;
    snprintf( buf, SUPER_MIL, "(%s) %s%s&B tells you (%s) '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ( ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ) ? "&W@" : "", ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name, arg );
    act( AT_TELL, buf, ch, argument, victim, TO_VICT );
    victim->position    = position;
    victim->reply   = ch;

    if ( xIS_SET( ch->in_room->flags, ROOM_LOGSPEECH ) )
    {
        snprintf( buf, SUPER_MIL, "[%d] %s: %s (tell to) %s.", ch->in_room->vnum,
                 IS_NPC( ch ) ? ch->short_descr : ch->name,
                 argument, IS_NPC( victim ) ? victim->short_descr : victim->name );
        append_to_file( LOG_FILE, buf );
    }

    return;
}

/**
    OOC private chat channel (Reply to tells)
    @see do_tell
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_reply( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    CHAR_DATA* victim;
    int position;
    xREMOVE_BIT( ch->deaf, CHANNEL_TELLS );

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch )  )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( is_silenced( ch ) )
    {
        ch_println( ch, "Your message didn't get through." );
        return;
    }

    if ( ( victim = ch->reply ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( !IS_NPC( victim ) && ( victim->switched )
            && can_see( ch, victim ) && ( get_trust( ch ) > LEVEL_AVATAR ) )
    {
        ch_println( ch, "That player is switched." );
        return;
    }
    else if ( !IS_NPC( victim ) && ( !victim->desc ) )
    {
        ch_println( ch, "That player is link-dead." );
        return;
    }

    if ( xIS_SET( victim->deaf, CHANNEL_TELLS )
            && ( !IS_IMMORTAL( ch ) || ( get_trust( ch ) < get_trust( victim ) ) ) )
    {
        act( AT_PLAIN, "That player has tells turned off.", ch, NULL, victim,
             TO_CHAR );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && !IS_IMMORTAL( ch ) ) // You couldn't tell but you could reply?
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( !IS_NPC( victim ) && xIS_SET( victim->in_room->flags, ROOM_SILENCE ) )
    {
        act( AT_PLAIN, "$E can't hear you.", ch, 0, victim, TO_CHAR );
        return;
    }

    if ( !has_pcflag( ch, PCFLAG_NCOUNCIL ) && ooc_break_check( ch, 1 ) )
        return;

    snprintf( buf, MSL, "(%s) You tell %s '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", victim->desc && victim->desc->account && xIS_SET( victim->desc->account->flags, ACC_CHAT ) ? victim->desc->account->name : victim->name );
    act( AT_TELL, buf, ch, argument, victim, TO_CHAR );
    position        = victim->position;
    victim->position    = POS_STANDING;
    snprintf( buf, MSL, "(%s) %s%s&B tells you '$t'", IS_IMMORTAL( ch ) ? "IMM" : IS_RPC( ch ) ? "RPC" : "OOC", ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? "&W@" : "", ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_CHAT ) ? ch->desc->account->name : ch->name );
    act( AT_TELL, buf, ch, argument, victim, TO_VICT );
    victim->position    = position;
    victim->reply   = ch;

    if ( xIS_SET( ch->in_room->flags, ROOM_LOGSPEECH ) )
    {
        snprintf( buf, MSL, "[%d] %s: %s (reply to) %s.", ch->in_room->vnum,
                 IS_NPC( ch ) ? ch->short_descr : ch->name,
                 argument,
                 IS_NPC( victim ) ? victim->short_descr : victim->name );
        append_to_file( LOG_FILE, buf );
    }

    return;
}

// Safely gets the (n)th character in the given string, or returns \0 if out of range.
// If n is negative, counts back that many from the end of the string (-1 would be the last character, etc)
char char_idx( const char* fulltext, int n )
{
    if ( fulltext == NULL )
        return '\0';

    int len = strlen( fulltext );

    if ( n >= len )
        return '\0';

    if ( n < 0 )
    {
        n = n * -1;

        if ( n > len )
            return '\0';

        return fulltext[ len - n ];
    }

    return fulltext[n];
}

const char* read_emote_target( const char* cptr, char* sub_buf )
{
    strlcpy( sub_buf, "", MSL );

    if ( *cptr == '\"' || *cptr == '\'' )
    {
        // Quote mode. Read until we get a closing quote.
        char close_quote = *cptr;
        cptr++;

        while ( *cptr != close_quote )
        {
            strncat( sub_buf, cptr, 1 );
            cptr++;

            if ( !*cptr ) // Got to the end of the whole string without finding a closing quote.
                return NULL;
        }

        cptr++; // Read past the closing quote
    }
    else
    {
        // Non-quote mode. Read until we get something that doesn't fit a keyword.
        while ( isdigit( *cptr ) )
        {
            strncat( sub_buf, cptr, 1 );
            cptr++;
        }

        if ( strlen( sub_buf ) > 0 && *cptr == '.' )
        {
            strncat( sub_buf, cptr, 1 );
            cptr++;
        }

        while ( isdigit( *cptr ) || isalpha( *cptr ) || *cptr == '-' )
        {
            strncat( sub_buf, cptr, 1 );
            cptr++;
        }
    }

    return cptr;
}

#define EMOTE_MODE_NORMAL     1   // Normal, includes both action and speech
#define EMOTE_MODE_VIS_ONLY   2   // Replaces speech with ------
#define EMOTE_MODE_AUDIO_ONLY 3   // Will include only text chunks
#define EMOTE_MODE_AUDIO_RAW  4   // Will include only text chunks and will not drunkify text

// Translate an emote string to the final form as seen by viewer.
// Returns false if some error was presented to the emoter and we should bail out.
bool process_emote_for_target( CHAR_DATA* ch, const char* argument, int mode, const char* base_color_code, char* result, CHAR_DATA* viewer )
{
    char sub_buf[MSL];
    strlcpy( result, base_color_code, MSL );
    const char* cptr = argument;

    while ( *cptr )
    {
        if ( *cptr == '"' )
        {
            strlcpy( sub_buf, "", MSL );
            cptr++;

            while ( *cptr != '"' )
            {
                strncat( sub_buf, cptr, 1 );

                if ( !*cptr ) // Got to the end of the whole string without finding a closing quote.
                {
                    ch_println( ch, "No closing quote found for speech portion of emote." );
                    return false;
                }

                cptr++;
            }

            cptr++; // Read past the closing quote

            if ( strlen( sub_buf ) == 0 )
            {
                ch_println( ch, "There must be something between each pair of quotes." );
                return false;
            }

            // Validate that the player can say that text in their current setting.
            if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) && !IS_RPC( ch ) )
            {
                ch_println( ch, "You can't do that here." );
                return false;
            }

            if ( has_pcflag( ch, PCFLAG_GAGGED ) )
            {
                act( AT_ACTION, "$n attempts to speak but is muffled through their gag.", ch, NULL, NULL, TO_ROOM );
                ch_println( ch, "You try to speak, but all you can manage are a few muffled grunts." );
                return false;
            }

            if ( !IS_NPC( ch ) && count_args( sub_buf ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
            {
                ch_println( ch, "You aren't intelligent enough to form sentences greater than three words in length!" );
                return false;
            }
            else if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( sub_buf ) > ( get_curr_int( ch ) / 3 ) + 2 )
            {
                ch_println( ch, "You aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
                return false;
            }

            // If applicable, transform speech with drunkenness, language scrambling, etc.
            char* final_speech = sub_buf;

            if ( mode != EMOTE_MODE_AUDIO_RAW )
            {
                final_speech = drunk_speech( sub_buf, ch );

                if ( viewer )
                    final_speech = translate_for_target( ch, viewer, final_speech );
            }

            // If doing audio-only, ensure there's a space between successive blocks of speech.
            if ( ( mode == EMOTE_MODE_AUDIO_ONLY || mode == EMOTE_MODE_AUDIO_RAW ) &&
                    strlen( result ) > strlen( base_color_code ) )
                strlcat( result, " ", MSL );

            if ( mode == EMOTE_MODE_AUDIO_RAW )
            {
                strlcat( result, stripclr( final_speech ), MSL );
            }
            else if ( mode == EMOTE_MODE_AUDIO_ONLY )
            {
                strlcat( result, "\"", MSL );
                strlcat( result, final_speech, MSL );
                strlcat( result, base_color_code, MSL );
                strlcat( result, "\"", MSL );
            }
            else
            {
                strlcat( result, "&w\"", MSL );

                if ( mode == EMOTE_MODE_VIS_ONLY )
                {
                    strlcat( result, "&z------", MSL );
                }
                else
                {
                    strlcat( result, txtclr( ch ), MSL );
                    strlcat( result, final_speech, MSL );
                }

                strlcat( result, "&w\"", MSL );
                strlcat( result, base_color_code, MSL );
            }

            continue;
        }

        // We handle speech blocks first, so audio-only mode need not continue.
        if ( mode == EMOTE_MODE_AUDIO_ONLY || mode == EMOTE_MODE_AUDIO_RAW )
        {
            cptr++;
            continue;
        }

        if ( !strncmp( "$n", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, PERS( ch, viewer ), MSL );
            strlcat( result, base_color_code, MSL );
        }
        else if ( !strncmp( "$e", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, is_droid( get_visible_race( ch ) ) ? "it" : he_she [URANGE( 0,  ch->sex, 2 )], MSL );
        }
        else if ( !strncmp( "$m", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, is_droid( get_visible_race( ch ) ) ? "it" :  him_her[URANGE( 0,  ch->sex, 2 )], MSL );
        }
        else if ( !strncmp( "$s", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, is_droid( get_visible_race( ch ) ) ? "its" : his_her[URANGE( 0,  ch->sex, 2 )], MSL );
        }
        else if ( !strncmp( "@@", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, "@", MSL );
        }
        else if ( !strncmp( "**", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, "*", MSL );
        }
        else if ( !strncmp( "##", cptr, 2 ) )
        {
            cptr += 2;
            strlcat( result, "#", MSL );
        }
        else if ( *cptr == '@' )
        {
            cptr++;
            cptr = read_emote_target( cptr, sub_buf );

            if ( !cptr )
            {
                ch_println( ch, "No closing quote found for @ token." );
                return false;
            }

            if ( strlen( sub_buf ) == 0 )
            {
                ch_println( ch, "Empty @ token. Reference which character?" );
                return false;
            }

            CHAR_DATA* target_ch = get_char_room( ch, sub_buf );

            if ( !target_ch )
            {
                ch_println( ch, "I don't see %s here!", sub_buf );
                return false;
            }
            else if ( target_ch == ch )
            {
                ch_println( ch, "Use $n to refer to yourself." );
                return false;
            }

            bool poss = !strncmp( "'s", cptr, 2 );

            if ( target_ch == viewer && poss )
            {
                strlcat( result, "your", MSL );
                cptr += 2;
            }
            else
            {
                if ( target_ch == viewer )
                    strlcat( result, "you", MSL );
                else
                {
                    strlcat( result, PERS( target_ch, viewer ), MSL );
                    strlcat( result, base_color_code, MSL );
                }
            }
        }
        else if ( *cptr == '#' )
        {
            cptr++;
            cptr = read_emote_target( cptr, sub_buf );

            if ( !cptr )
            {
                ch_println( ch, "No closing quote found for # token." );
                return false;
            }

            if ( strlen( sub_buf ) == 0 )
            {
                ch_println( ch, "Empty # token. Reference which object?" );
                return false;
            }

            OBJ_DATA* target_obj = get_obj_here( ch, sub_buf );

            if ( !target_obj )
            {
                ch_println( ch, "I don't see %s here!", sub_buf );
                return false;
            }

            if ( !can_see_obj( viewer, target_obj ) )
            {
                strlcat( result, "something", MSL );
            }
            else
            {
                strlcat( result, target_obj->short_descr, MSL );
                strlcat( result, base_color_code, MSL );
            }
        }
        else if ( *cptr == '*' )
        {
            cptr++;
            cptr = read_emote_target( cptr, sub_buf );

            if ( !cptr )
            {
                ch_println( ch, "No closing quote found for * token." );
                return false;
            }

            if ( strlen( sub_buf ) == 0 )
            {
                ch_println( ch, "Empty * token. Reference which ship/vehicle/structure?" );
                return false;
            }

            SHIP_DATA* ship = ship_in_room( ch->in_room, sub_buf );

            if ( ship )
            {
                strlcat( result, ship->name, MSL );
                strlcat( result, base_color_code, MSL );
                continue;
            }

            VEHICLE_DATA* vehicle = vehicle_in_room( ch->in_room, sub_buf );

            if ( vehicle )
            {
                strlcat( result, vehicle->name, MSL );
                strlcat( result, base_color_code, MSL );
                continue;
            }

            STRUCTURE_DATA* structure = find_struct_in_room( ch->in_room, sub_buf );

            if ( structure )
            {
                strlcat( result, structure->name, MSL );
                strlcat( result, base_color_code, MSL );
                continue;
            }

            ch_println( ch, "I don't see %s here!", sub_buf );
            return false;
        }
        else
        {
            strncat( result, cptr, 1 );
            cptr++;
        }
    }

    // Loop over the result to capitalize the first letter after every sentence.
    bool sentence_ended = false;
    bool capitalize_next = true;

    for ( int i = 0; result[i]; i++ )
    {
        if ( capitalize_next && result[i] != ' ' )
        {
            result[i] = toupper( result[i] );
            capitalize_next = false;
            continue;
        }

        // Skip past any color codes or punctuation before the next sentence.
        if ( sentence_ended )
        {
            while ( result[i] && result[i] != ' ' )
                i++;

            if ( !result[i] )
                break;

            sentence_ended = false;
            capitalize_next = true;
            continue;
        }

        // Look for a sentence ending either outside a quote or before a closing quote.
        if ( !strncmp( ". ", result + i, 2 ) )
            sentence_ended = true;
    }

    // If this is audio-only and there was only one chunk of text, remove the quotes around it.
    if ( mode == EMOTE_MODE_AUDIO_ONLY )
    {
        char* nocolor = stripclr( result );

        if ( count_args( nocolor ) == 1 )
        {
            one_argument( nocolor, sub_buf );
            strlcpy( result, txtclr( ch ), MSL );
            strlcpy( result, sub_buf, MSL );
        }
    }

    return true;
}

/**
    Allows characters to "do actions" IC
    -Beefed up to allow people to throw says into emotes and compensate for language barriers, and microphones.  Orion
    -Ravaus added ability to target players/objects
    @see do_rmote
    @author Orion,Ravaus
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_emote( CHAR_DATA* ch, char* argument )
{
    EXT_BV actflags = ch->act;
    char buf[MSL];
    char final_arg[MSL];
    char viewer_buf[MSL];
    TAP_DATA* tap = NULL;

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_NO_EMOTE ) )
    {
        ch_println( ch, "You can't show your emotions." );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && !IS_RPC( ch ) && has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "You cannot do that while AFK." );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_HIDE ) || IS_AFFECTED( ch, AFF_INVISIBLE ) || leader_is_affected( ch, AFF_HIDE, SMUGGLING_ABILITY ) )
    {
        ch_println( ch, "You're out of sight, that's kind of the point." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Emote what?" );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && !IS_RPC( ch ) && has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "You cannot do that while AFK." );
        return;
    }

    if ( check_ooc_in_ic_message( ch, argument, __FUNCTION__ ) )
        return;

    if ( IS_NPC( ch ) )
        xREMOVE_BIT( ch->act, ACT_SECRETIVE );

    // If no $n token was included, put it at the front.
    if ( !strstr( argument, "$n" ) )
    {
        // If they did "emote s ...", we should present their name in a possessive form.
        if ( char_idx( argument, 0 ) == 's' && char_idx( argument, 1 ) == ' ' )
            snprintf( final_arg, MSL, "$n's %s", argument + 2 );
        else
            snprintf( final_arg, MSL, "$n %s", argument );
    }
    else
    {
        strlcpy( final_arg, argument, MSL );
    }

    if ( isdigit( char_idx( final_arg, -1 ) ) || isalpha( char_idx( final_arg, -1 ) ) )
        strlcat( final_arg, ".", MSL );

    for ( CHAR_DATA* rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( !process_emote_for_target( ch, final_arg, EMOTE_MODE_NORMAL, "&c", viewer_buf, rch ) )
            return;

        if ( rch->position <= POS_SLEEPING )
            continue;

        ch_println( rch, "%s", viewer_buf );
    }

    if ( !is_disrupted( ch, TAP_COMM, true ) )
    {
        for ( TRANSMIT_DATA* transmit = first_transmit; transmit; transmit = transmit->next )
        {
            if ( !transmitter_sending_from_room( transmit, ch->in_room ) )
                continue;

            snprintf( buf, MSL, "&cBinary data detected on holotransmitter channel %d.\n", transmit->channel );
            push_to_taps( ch->in_room, TAP_COMM, buf );

            for ( TRANSMIT_RECEIVER* rcv = transmit->first_connected; rcv; rcv = rcv->next )
            {
                OBJ_DATA* tobj = rcv->transmitter;

                if ( tobj->value[IVAL_TRANSMITTER_MODE] == IVAL_TRANSMITTER_MODE_SEND )
                    continue;

                ROOM_INDEX_DATA* troom = tobj->in_room ? tobj->in_room : tobj->carried_by ? tobj->carried_by->in_room : NULL;

                if ( !troom || troom == ch->in_room )
                    continue;

                for ( CHAR_DATA* rch = troom->first_person; rch; rch = rch->next_in_room )
                {
                    if ( !process_emote_for_target( ch, final_arg, EMOTE_MODE_NORMAL, "&033", viewer_buf, rch ) )
                        return;

                    if ( rch->position <= POS_SLEEPING )
                        continue;

                    ch_println( rch, "&z<&WHolo&z> %s", viewer_buf );
                }
            }
        }

        if ( !has_feat( ch, cache_skill( "camera avoidance", &skill_camera_avoidance ) ) )
        {
            for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
            {
                if ( !d->character || d->connected != CON_PLAYING )
                    continue;

                TIMER* timer = get_timerptr( d->character, TIMER_DO_FUN );

                if ( !timer )
                    continue;

                tap = NULL;
                if ( !str_cmp( timer->buffer->func, "do_monitor_camera" ) )
                {
                    tap = ( TAP_DATA* )timer->buffer->buf1;
                    if ( !tap || tap->tap_target != ch->in_room )
                        continue;

                    if ( !process_emote_for_target( ch, final_arg, EMOTE_MODE_VIS_ONLY, "&c", viewer_buf, d->character ) )
                        return;

                    if ( d->character->position <= POS_SLEEPING )
                        continue;

                    ch_println( d->character, "&w<&WCamera&w> %s", viewer_buf );
                }
            }
        }
    }

    ch->act = actflags; // In case we modified their SECRETIVE flag
    char audio_only_orig[MSL];

    if ( !process_emote_for_target( ch, final_arg, EMOTE_MODE_AUDIO_RAW, "", audio_only_orig, NULL ) )
        return;

    char audio_only[MSL];

    if ( !process_emote_for_target( ch, final_arg, EMOTE_MODE_AUDIO_ONLY, "", audio_only, NULL ) )
        return;

    if ( !NULLSTR( audio_only_orig ) )
    {
        // Capture now in case progs move them
        ROOM_INDEX_DATA* room = ch->in_room;
        relay_microphones( ch, audio_only );
        activate_translator_droids( ch, audio_only );
        lua_trigger_on_ch_speech( ch, audio_only_orig );

        if ( char_extracted( ch ) )
            return;

        mprog_speech_trigger( audio_only_orig, ch );

        if ( char_extracted( ch ) )
            return;

        lua_trigger_on_obj_speech( ch, audio_only_orig );

        if ( char_extracted( ch ) )
            return;

        oprog_speech_trigger( audio_only_orig, ch );

        if ( char_extracted( ch ) )
            return;

        lua_trigger_on_room_speech( room, ch, audio_only_orig );

        if ( char_extracted( ch ) )
            return;

        rprog_speech_trigger( audio_only_orig, ch );
    }
}

