/**
    Quit out of the game
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_quit( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    SHIP_DATA* ship = NULL;
    struct timeval last_time;
    time_t ltime;
    int level;

    if ( IS_SWITCHED( ch ) )
    {
        ch_println( ch, "&wYou can't quit while switched. Use &Creturn&w first." );
        return;
    }

    if ( IS_NPC( ch ) )
        return;

    if ( ch->position == POS_FIGHTING )
    {
        set_char_color( AT_RED, ch );
        ch_println( ch, "No way! You are fighting." );
        return;
    }

    if ( isFighting( ch ) )
    {
        int mm, ms;
        ms = ch->fight_timer % 60;
        mm = ch->fight_timer / 60;
        set_char_color( AT_RED, ch );
        ch_println( ch, "You can't sleep for another %d minute%s and %d second%s.", mm, mm == 1 ? "" : "s", ms, ms == 1 ? "" : "s" );
        return;
    }

    if ( ch->position < POS_STUNNED  )
    {
        set_char_color( AT_BLOOD, ch );
        ch_println( ch, "You're not DEAD yet." );
        return;
    }

    if ( !IS_RPC( ch ) && ch->in_room && !xIS_SET( ch->in_room->flags, ROOM_HOTEL ) && !NOT_AUTHED( ch ) && ch->desc )
    {
        ch_println( ch, "You may not quit here." );
        ch_println( ch, "You will have to find a safer resting place such as a hotel..." );
        ch_println( ch, "Maybe you could HAIL a speeder." );
        return;
    }

    if ( !IS_IMMORTAL( ch ) && ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
    {
        char buf[MSL];
        if ( !check_pilot( ch, ship ) && !nifty_is_name( ch->name, ship->crew ) && ship->classtype < BATTLESTATION_SHIP )
        {
            if ( ch->desc )
            {
                ch_println( ch, "You can't quit here. See HELP QUIT." );
                return;
            }
            else
            {
                snprintf( buf, MSL, "%s (%s) is linkdead, quitting on ship they don't own (%s).",
                ch->name, ( ch->pcdata && ch->pcdata->account ) ? ch->pcdata->account->name : "null", ship->name  );
                bug( buf );
                write_to_log( FUNC, buf, sysdata.log_level, 720, true );
            }
        }

        if ( ch->desc && ship->shipstate != SHIP_DOCKED && ship->classtype < FRIGATE_SHIP )
        {
            if ( ship->in_room && ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) ) {}
            else
            {
                ch_println( ch, "&RThis spacecraft will have to be landed or docked first. Sorry." );
                return;
            }
        }

        if ( ship_is_fighting( ship ) )
        {
            ch_println( ch, "&RThis spacecraft was in combat too recently. Try again in %d seconds.", getFightTimer( ship ) );
            return;
        }

        if ( is_public( ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        {
            if ( ch->desc )
            {
                ch_println( ch, "&RYou cannot log out inside taxis." );
                return;
            }
            else
            {
                snprintf( buf, MSL, "%s (%s) is linkdead, quitting on public taxi (%s).",
                ch->name, ( ch->desc && ch->desc->account ) ? ch->desc->account->name : "null", ship->name  );
                bug( buf );
                write_to_log( FUNC, buf, sysdata.log_level, 720, true );
            }
        }

        if ( ship->selfd_armed == TRUE && ship->selfd_time > 0 )
        {
            ch_println( ch, "&RThis ship is going to explode! Get out of here first!" );
            return;
        }
    }

    // Force em to sleep first! Makes it more realistic and everyone knows when you log in.   Orion 2008
    if ( ch->position != POS_SLEEPING && get_trust( ch ) <= LEVEL_HERO )
    {
        ch_println( ch, "You need to be asleep to quit. Attempting to sleep!" );
        interpret( ch, "rest", FALSE );
        interpret( ch, "sleep", FALSE );

        if ( ch->position != POS_SLEEPING && ch->desc )
        {
            ch_println( ch, "You can't log out unless you are asleep!" );
            return;
        }

        // GRAL Force them awake maybe afterwards ? Its frickken annoying.
    }

    account_update( ch );

    lua_trigger_on_ch_logout( ch, ch->in_room );

    if ( ch->position == POS_MOUNTED )
    {
        CHAR_DATA* rch = NULL, *rnext = NULL;

        for ( rch = first_char; rch; rch = rnext )
        {
            rnext = rch->next;

            if ( !IS_NPC( rch ) )
                continue;

            if ( ch == rch )
                continue;

            if ( ch->mount && ch->mount == rch )
            {
                stop_follower( rch, false );
                xREMOVE_BIT( rch->act, ACT_MOUNTED );
                if ( xIS_SET( rch->act, ACT_SENTINEL ) && rch->pIndexData && !xIS_SET( rch->pIndexData->act, ACT_SENTINEL ) )
                    xREMOVE_BIT( rch->act, ACT_SENTINEL );
                ch->mount = NULL;
                ch->position = POS_STANDING;
            }
        }
    }

    /* Check if we should save the RP Points */
    gettimeofday( &last_time, NULL );
    ltime = ( time_t ) last_time.tv_sec;

    if ( ( ltime - ch->logon ) > ( 30 * 60 ) )
    {
        if ( get_trust( ch ) >= 105 )
            ch_println( ch, "&G***SAVING ROLEPLAY POINTS***" );

        ch->pcdata->new_rp = URANGE( -250, ch->pcdata->new_rp, 250 );
        ch->pcdata->curr_rp = URANGE( -1000, ch->pcdata->curr_rp + ch->pcdata->new_rp, 1000 );
        ch->pcdata->new_rp = 0;
    }
    else
    {
        if ( get_trust( ch ) >= 105 )
            ch_println( ch, "You were only on for %d seconds. Points will not save.", ( ltime - ch->logon ) );
    }
    set_char_color( AT_WHITE, ch );
    ch_println( ch, "Your surroundings begin to fade as a mystical swirling vortex of colors\nenvelops your body... When you come to, things are not as they were.\n" );
    random_quote( ch );
    act( AT_SAY, "\nA strange voice says, 'We await your return, $n...'", ch, NULL, NULL, TO_CHAR );

    if ( !IS_IMMORTAL( ch ) )
        act( AT_BYE, "$n has left the game.", ch, NULL, NULL, TO_ROOM );

    set_char_color( AT_GREY, ch );
    snprintf( log_buf, MSL, "%s has quit at %d.", ch->name, ch->in_room->vnum );

    if ( ch->desc )
        sql_connect_log( ch->name, ch->desc->user, ch->desc->account ? ch->desc->account->name : "", ch->desc->host, get_trust( ch ), FALSE, (ch && ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "" );
    else
        sql_connect_log( ch->name, "", "", "", get_trust( ch ), FALSE, (ch && ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "" );

    save_char_obj( ch, false );
    save_player_backup( ch );
    if ( ch->furniture )
        ch->furniture->occupants--;

    if ( ch->pcdata->clan )
        save_clan( ch->pcdata->clan, true );

    level = get_trust( ch );

    /*
        After extract_char the ch is no longer valid!
    */
    extract_char( ch );

    /* don't show who's logging off to leaving player */
    /*
        to_channel( log_buf, CHANNEL_MONITOR, "Monitor", level );
    */
    log_string_plus( log_buf, LOG_COMM, level );
    return;
}
