/**
    Something from original DikuMUD that Merc yanked out.
    Used to prevent following loops, which can cause problems if people
    follow in a loop through an exit leading back into the same room
    (Which exists in many maze areas)            -Thoric
    @param ch Character 1
    @param victim Character 2
    @return TRUE or FALSE based on whether it is a follow loop
*/
bool circle_follow( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( ch->master == victim && victim->master == ch )
        return TRUE;

    return FALSE;
}
/**
    Dismiss a follower
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_dismiss( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[MIL];
    CHAR_DATA* victim = NULL;
    DROID_DATA* tDB = NULL;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Dismiss whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    bool isDroid = false;
    tDB = droid_from_controller( ch->id );

    if ( tDB && victim == mob_from_droid( tDB ) )
        isDroid = true;

    if ( ( IS_AFFECTED( victim, AFF_CHARM ) || !str_cmp( victim->name, "message drone droid" ) )
            && ( IS_NPC( victim ) )
            && ( victim->master == ch ) && !isDroid )
    {
        if ( !str_cmp( victim->name, "message drone droid" ) )
        {
            act( AT_ACTION, "$n dismisses $N, causing $M to bobble off towards $S next delivery.", ch, NULL, victim, TO_NOTVICT );
            act( AT_ACTION, "You dismiss $N, causing $M to bobble off towards $S next delivery.", ch, NULL, victim, TO_CHAR );
        }
        else
        {
            act( AT_ACTION, "$n dismisses $N, causing $M to leave the room to go about $S business.", ch, NULL, victim, TO_NOTVICT );
            act( AT_ACTION, "You dismiss $N, causing $M to leave the room to go about $S business.", ch, NULL, victim, TO_CHAR );
        }
        interpret( victim, "drop all", FALSE );
        snprintf( buf, MIL, "drop %ld credits", victim->gold );
        interpret( victim, buf, FALSE );
        if ( ch->mount == victim )
            do_dismount( ch, "" );
        stop_follower( victim, false );
        stop_hating( victim );
        stop_hunting( victim );
        stop_fearing( victim );
        extract_char( victim );
    }
    else
        ch_println( ch, "You cannot dismiss them." );

    return;
}
/**
    Follow someone
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_follow( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Follow whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master )
    {
        act( AT_PLAIN, "But you'd rather follow $N!", ch, NULL, ch->master, TO_CHAR );
        return;
    }

    if ( victim == ch )
    {
        if ( !ch->master )
            ch_println( ch, "You already follow yourself." );

        stop_follower( ch, false );
        return;
    }

    add_follower( ch, victim, false );
    return;
}

bool is_following( CHAR_DATA* follower, CHAR_DATA* leader )
{
    if ( !follower || !leader || char_extracted( follower ) || char_extracted( leader ) )
        return false;

    if ( follower->master == leader )
        return true;

    for ( CHAR_DATA* tch = leader->first_follower; tch; tch = tch->next_follower )
        if ( tch == follower )
            return true;

    return false;
}

/**
    Add a follower to a master
    @param ch Character following
    @param master Character being followed
    @param silent Whether to suppress echos
*/
void add_follower( CHAR_DATA* ch, CHAR_DATA* master, bool silent )
{
    if ( !ch || char_extracted( ch ) )
    {
        bug( "%s: null or extracted ch", FUNC );
        return;
    }

    if ( !master || char_extracted( master ) )
    {
        bug( "%s: null or extracted master", FUNC );
        return;
    }

    stop_follower( ch, false );

    ch->master        = master;
    ch->leader        = NULL;

    if ( IS_NPC( ch ) && !droid_from_mob( ch ) )
        LINK( ch, master->first_follower, master->last_follower, next_follower, prev_follower );

    if ( !silent )
    {
        if ( can_see( master, ch ) )
            act( AT_ACTION, "$n now follows you.", ch, NULL, master, TO_VICT );

        act( AT_ACTION, "You now follow $N.",  ch, NULL, master, TO_CHAR );
    }
    return;
}

/**
    Stop following
    @param ch Character following
    @param silent Suppress echos
*/
void stop_follower( CHAR_DATA* ch, bool silent )
{
    bool has_node = FALSE;

    if ( !ch )
    {
        bug( "%s: null ch.", FUNC );
        return;
    }

    if ( ch->master )
    {
        if ( !silent )
        {
            if ( can_see( ch->master, ch ) )
                act( AT_ACTION, "$n stops following you.",     ch, NULL, ch->master, TO_VICT    );

            act( AT_ACTION, "You stop following $N.",      ch, NULL, ch->master, TO_CHAR    );
        }

        LINK_HASNODE( ch->master->first_follower, CHAR_DATA, next_follower, ch, has_node );
        if ( has_node ) UNLINK( ch, ch->master->first_follower, ch->master->last_follower, next_follower, prev_follower );
    }

    ch->master = NULL;
    ch->leader = NULL;

    if ( IS_AFFECTED( ch, AFF_CHARM ) )
        xREMOVE_BIT( ch->affected_by, AFF_CHARM );

    return;
}

/**
    Stop following and remove all followers (upon death?)
    @param ch Character dying/being cleared
*/
void die_follower( CHAR_DATA* ch )
{
    CHAR_DATA* fch = NULL;

    if ( !ch )
    {
        bug( "%s: null ch", FUNC );
        return;
    }

    stop_follower( ch, false );

    for ( fch = first_char; fch; fch = fch->next )
    {
        if ( fch == ch )
            continue;

        if ( fch->master == ch || fch->leader == ch )
            stop_follower( fch, false );
    }

    return;
}

/**
    Order an NPC to execute a command
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_order( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], argbuf[MIL];
    CHAR_DATA* victim = NULL;
    CHAR_DATA* och = NULL;
    CHAR_DATA* och_next = NULL;
    bool found = FALSE;
    bool fAll = FALSE;
    strlcpy( argbuf, argument, MIL );
    argument = one_argument( argument, arg );

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "Order whom to do what?" );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You feel like taking orders, not giving them." );
        return;
    }

    if ( !str_cmp( arg, "all" ) )
    {
        fAll   = TRUE;
    }
    else
    {
        if ( ( victim = get_char_room( ch, arg ) ) == NULL )
        {
            ch_println( ch, "They aren't here." );
            return;
        }

        if ( victim == ch )
        {
            ch_println( ch, "Aye aye, right away!" );
            return;
        }

        if ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_DROID ) )
        {
            ch_println( ch, "If you want to control your droid use the DUTY command." );
            return;
        }

        if ( !IS_AFFECTED( victim, AFF_CHARM ) || victim->master != ch )
        {
            ch_println( ch, "Do it yourself!" );
            return;
        }
    }

    if ( nifty_is_name_prefix( "mp", argument ) )
    {
        ch_println( ch, "I don't think so, you cheating twit." );
        return;
    }

    found = FALSE;

    for ( och = ch->in_room->first_person; och; och = och_next )
    {
        och_next = och->next_in_room;

        if ( IS_AFFECTED( och, AFF_CHARM )
                &&   och->master == ch
                && ( fAll || och == victim ) )
        {
            found = TRUE;
            act( AT_ACTION, "$n orders you to '$t'.", ch, argument, och, TO_VICT );
            interpret( och, argument, TRUE );
        }
    }

    if ( found )
    {
        snprintf( log_buf, MSL, "%s: order %s.", ch->name, argbuf );
        log_string_plus( log_buf, LOG_NORMAL, ch->top_level );
        ch_println( ch, "Ok." );
        WAIT_STATE( ch, 12 );
    }
    else
        ch_println( ch, "You have no followers here." );

    return;
}
/**
    Add someone to your group
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_group( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim = NULL;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        CHAR_DATA* gch;
        CHAR_DATA* leader;
        leader = ch->leader ? ch->leader : ch;
        set_char_color( AT_GREEN, ch );
        ch_println( ch, "%s's group:", PERS( leader, ch ) );

        /* Changed so that no info revealed on possess */
        for ( gch = first_char; gch; gch = gch->next )
        {
            if ( is_same_group( gch, ch ) )
            {
                set_char_color( AT_DGREEN, ch );

                if ( IS_AFFECTED( gch, AFF_POSSESS ) )
                    ch_println( ch,
                               "%-16s %4s/%4s hp %4s/%4s mv %5s xp",
                               PERS( gch, ch ),
                               "????",
                               "????",
                               "????",
                               "????",
                               "?????"    );
                else
                {
                    int hp_perc = ( int )( ( ( double )( gch->hit ) / ( double )( gch->max_hit ) ) * 100 );
                    int mv_perc  = ( int )( ( ( double )( gch->move ) / ( double )( gch->max_move ) ) * 100 );
                    ch_println( ch,
                               "%-16s %4d%% hp %4d%% mv",
                               PERS( gch, ch ),
                               hp_perc, mv_perc   );
                }
            }
        }

        return;
    }

    if ( !strcmp( arg, "disband" ) )
    {
        CHAR_DATA* gch;
        int count = 0;

        if ( ch->leader || ch->master )
        {
            ch_println( ch, "You cannot disband a group if you're following someone." );
            return;
        }

        for ( gch = first_char; gch; gch = gch->next )
        {
            if ( is_same_group( ch, gch )
                    && ( ch != gch ) )
            {
                stop_follower( gch, false );
                count++;
                ch_println( gch, "Your group is disbanded." );
            }
        }

        if ( count == 0 )
            ch_println( ch, "You have no group members to disband." );
        else
            ch_println( ch, "You disband your group." );

        return;
    }

    if ( !strcmp( arg, "all" ) )
    {
        CHAR_DATA* rch;
        int count = 0;

        for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        {
            if ( ch != rch
                    &&   rch->master == ch
                    &&   !ch->master
                    &&   !ch->leader
                    &&   !is_same_group( rch, ch )
               )
            {
                rch->leader = ch;
                count++;
            }
        }

        if ( count == 0 )
            ch_println( ch, "You have no eligible group members." );
        else
        {
            act( AT_ACTION, "$n groups $s followers.", ch, NULL, victim, TO_ROOM );
            ch_println( ch, "You group your followers." );
        }

        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim->held )
    {
        act( AT_RED, "But $N is restrained!", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( ch->master || ( ch->leader && ch->leader != ch ) )
    {
        ch_println( ch, "But you are following someone else!" );
        return;
    }

    if ( ( victim->master != ch && ch != victim ) || victim == ch )
    {
        act( AT_PLAIN, "$N isn't following you.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( is_same_group( victim, ch ) && ch != victim )
    {
        stop_follower( victim, false );
        act( AT_ACTION, "$n removes $N from $s group.",   ch, NULL, victim, TO_NOTVICT );
        act( AT_ACTION, "$n removes you from $s group. You are no longer following $n.",  ch, NULL, victim, TO_VICT    );
        act( AT_ACTION, "You remove $N from your group. They are no longer following you.", ch, NULL, victim, TO_CHAR    );
        return;
    }

    victim->leader = ch;
    act( AT_ACTION, "$N joins $n's group.", ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "You join $n's group.", ch, NULL, victim, TO_VICT    );
    act( AT_ACTION, "$N joins your group.", ch, NULL, victim, TO_CHAR    );
    return;
}

/**
    'Split' originally by Gnort, God of Chaos.
    Split some amount of credits amongst your group
    @author Gnort
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_split( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg[MIL];
    CHAR_DATA* gch;
    int members;
    int amount;
    int share;
    int extra;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Split how much?" );
        return;
    }

    amount = atoi( arg );

    if ( amount < 0 )
    {
        ch_println( ch, "Your group wouldn't like that." );
        return;
    }

    if ( amount == 0 )
    {
        ch_println( ch, "You hand out zero credits, but no one notices." );
        return;
    }

    if ( ch->gold < amount )
    {
        ch_println( ch, "You don't have that many credits." );
        return;
    }

    members = 1;

    for ( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
    {
        if ( gch != ch && !IS_NPC( gch ) && is_same_group( gch, ch ) )
            members++;
    }

    if ( ( has_pcflag( ch, PCFLAG_AUTOGOLD ) ) && ( members < 2 ) )
        return;

    if ( members < 2 )
    {
        ch_println( ch, "Just keep it all." );
        return;
    }

    share = amount / members;
    extra = amount % members;

    if ( share == 0 )
    {
        ch_println( ch, "Don't even bother, cheapskate." );
        return;
    }

    long int origgold = ch->gold;
    ch->gold -= amount;
    ch->gold += share + extra;
    origgold = ch->gold - origgold;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "do_split", origgold, FALSE );

    set_char_color( AT_GOLD, ch );
    ch_println( ch,
               "You split %d credits.  Your share is %d credits.",
               amount, share + extra );
    snprintf( buf, MSL, "$n splits %d credits.  Your share is %d credits.",
             amount, share );

    for ( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
    {
        if ( gch != ch && !IS_NPC( gch ) && is_same_group( gch, ch ) )
        {
            act( AT_GOLD, buf, ch, NULL, gch, TO_VICT );
            gch->gold += share;

            if ( !IS_NPC( gch ) )
                sql_credits_log( gch->name, "do_split", share, FALSE );
        }
    }

    return;
}

