/*
    Types:
    0 = All
    1 = Mobs only
    2 = Players only
*/
/**
    Count how many followers someone has
    @return Number of followers of the provided type
    @param ch Master character
    @param inroom Only count followers in the same room as the master?
    @param type Type of follower
    - 0 = All
    - 1 = Mobs only
    - 2 = Players only
*/
int count_followers( CHAR_DATA* ch, int type, bool inroom )
{
    CHAR_DATA* rch;
    int count = 0;

    if ( inroom && !ch->in_room )
        return 0;

    for ( rch = first_char; rch; rch = rch->next )
    {
        if ( ch == rch )
            continue;

        if ( inroom && ch->in_room != rch->in_room )
            continue;

        // CH could potentially be following someone else - who cares, we only allow X followers
        if ( rch->master == ch )
        {
            if ( IS_NPC( rch ) && type != 2 )
                count++;

            if ( !IS_NPC( rch ) && type != 1 )
                count++;
        }
    }

    return count;
}

/**
    Check if two characters are in the same group
    It is very important that this be an equivalence relation:
    (1) A ~ A
    (2) if A ~ B then B ~ A
    (3) if A ~ B  and B ~ C, then A ~ C
    @return TRUE if they are in the same group
    @param ach Character 2
    @param bch Character 2
*/
bool is_same_group( CHAR_DATA* ach, CHAR_DATA* bch )
{
    if ( ach->leader )
        ach = ach->leader;

    if ( bch->leader )
        bch = bch->leader;

    return ach == bch;
}


/**
    Language support functions. -- Altrag
    07/01/96
    @return TRUE if ch knows language
    @param ch Character to check for language
    @param language Language to check knowledge of
    @param cch Speaker (used if speaking clan language)
    @author Altrag
*/
bool knows_language( CHAR_DATA* ch, EXT_BV language, CHAR_DATA* cch )
{
    SKILL_DATA* skill = NULL;

    if ( !IS_NPC( ch ) && IS_IMMORTAL( ch ) )
        return TRUE;

    if ( IS_NPC( ch ) && xIS_EMPTY( ch->speaks ) ) /* No langs = knows all for npcs */
        return TRUE;

    if ( IS_NPC( ch ) && xIS_SET( language, LANG_CLAN ) )
        return TRUE;

    if ( IS_NPC( ch ) )
    {
        for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
            if ( xIS_SET( language, languages[i].flag ) && xIS_SET( ch->speaks, languages[i].flag ) )
                return TRUE;
    }

    if ( xIS_SET( language, LANG_CLAN ) )
    {
        /* Clan = Basic for mobs.. snicker.. -- Altrag */
        if ( IS_NPC( ch ) || IS_NPC( cch ) )
            return TRUE;

        if ( ch->pcdata->clan == cch->pcdata->clan && ch->pcdata->clan != NULL )
            return TRUE;
    }

    if ( !IS_NPC( ch ) )
    {
        /* Racial languages for PCs */
        if ( xIS_SET( language, ch->race->language ) )
            return TRUE;

        for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
        {
            skill = language_table[i];

            if ( !skill )
                continue;

            /* Safety patch - Make sure the flag has been set */
            if ( get_learned_pct( ch, skill ) > 0 && !xIS_SET( ch->speaks, languages[i].flag ) )
            {
                /* bug("Repaired missing language flag on %s. Bug Fixed.", ch->name); */
                xSET_BIT( ch->speaks, languages[i].flag );
            }

            if ( xIS_SET( language, languages[i].flag ) && xIS_SET( ch->speaks, languages[i].flag ) )
            {
                if ( get_learned_pct( ch, skill ) >= 60 )
                    return TRUE;
            }
        }
    }

    return FALSE;
}
/**
    Check if a player can learn a language
    @return TRUE if ch can learn language
    @param ch Character to check for language
    @param language Language to check for possibility to learn
*/
bool can_learn_lang( CHAR_DATA* ch, int language )
{
    SKILL_DATA* skill = NULL;

    if ( language == LANG_CLAN )
        return FALSE;

    if ( IS_NPC( ch ) || IS_IMMORTAL( ch ) )
        return FALSE;

    if ( ch->race->language == language )
        return FALSE;

    if ( xIS_SET( ch->speaks, language ) )
    {
        for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
            if ( language == languages[i].flag )
            {
                if ( ( skill = language_table[i] ) == NULL )
                {
                    bug( "%s: valid language without skill: %s", languages[i].name );
                    continue;
                }

                if ( get_learned_pct( ch, skill ) >= 99 )
                    return FALSE;
            }
    }

    /* if ( VALID_LANGS & language ) */
    return TRUE;
    return FALSE;
}

/**
    Change the language you are speaking
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_speak( CHAR_DATA* ch, char* argument )
{
    EXT_BV xchk;
    char arg[MIL];
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &CSPEAK <&wlanguage&C>" );
        ch_println( ch, "&zSpeaking: &C%s", flag_string( &ch->speaking, languages ) );

        if ( IS_IMMORTAL( ch ) || IS_NPC( ch ) )
        {
            ch_println( ch, "&zYou can speak all languages." );
        }
        else
        {
            ch_println( ch, "&zYou can speak: &B%s&z.", flag_string( &ch->speaks, languages ) );
        }

        return;
    }

    if ( !str_cmp( arg, "all" ) && IS_IMMORTAL( ch ) )
    {
        set_char_color( AT_SAY, ch );
        xCLEAR_BITS( ch->speaking );
        for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
            xSET_BIT( ch->speaking, languages[i].flag );

        ch_println( ch, "&wNow speaking all languages." );
        return;
    }

    if ( !str_prefix( arg, "Jawa" ) && str_cmp( ch->race->race_name, "Jawa" ) && !IS_IMMORTAL( ch ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "Only Jawas can speak Jawa." );
        return;
    }

    /* if ( str_prefix( arg, "Wookiee" ) && ch->race == RACE_WOOKIEE )
    {
    set_char_color( AT_SAY, ch );
                ch_println( ch, "Wookiees cannot speak any language except their own." );
    return;
    }*/

    if ( !str_prefix( arg, "Clan" ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wThat is not a valid option." );
        return;
    }

    if ( !str_prefix( arg, "Defel" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_DEFEL ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wOnly Defels can speak Defel." );
        return;
    }

    if ( !str_prefix( arg, "Shyriiwook" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_WOOKIEE ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wYour vocal cords aren't made to talk that way!" );
        return;
    }

    if ( !str_prefix( arg, "Yuuzhan Vong" ) && !xIS_SET( ch->race->flags, RFLAG_VONG ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wYour vocal cords aren't made to talk that way!" );
        return;
    }

    if ( xIS_SET( ch->race->flags, RFLAG_VONG ) && ch->main_ability != ESPIONAGE_ABILITY && str_prefix( arg, "Yuuzhan Vong" ) )
    {
        ch_println( ch, "&wOnly the Praetorite Vong have been trained to speak in alien tongues." );
        return;
    }

    if ( !str_prefix( arg, "Felucian" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_FELUCIAN ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wYour vocal cords aren't made to talk that way!" );
        return;
    }

    /*    if ( str_prefix( arg, "gamorrean" ) && ch->race == RACE_GAMORREAN )
        {
        set_char_color( AT_SAY, ch );
                ch_println( ch, "Gamorreans cannot speak other languages, even though some can understand them." );
        return;
        }*/
    if ( !str_prefix( arg, "twileki" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_TWILEK ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wTo speak the Twi'lek language requires body parts that you don't have." );
        return;
    }

    if ( !str_prefix( arg, "lorrdian" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_LORRDIAN ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wTo speak the Lorrdian language requires more control than you have." );
        return;
    }

    if ( !str_prefix( arg, "Binary" ) && !xIS_SET( ch->race->flags, RFLAG_DROID ) )
    {
        set_char_color( AT_SAY, ch );
        ch_println( ch, "&wOnly droids can speak binary." );
        return;
    }

    if ( !str_prefix( arg, "Ithorian" ) && !xIS_SET( ch->race->specflags, RSPECFLAG_ITHORIAN ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
    {
        ch_println( ch, "&zYour vocal cords aren't made to talk that way!" );
        return;
    }

    for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
    {
        xCLEAR_BITS( xchk );
        xSET_BIT( xchk, languages[i].flag );

        if ( !str_prefix( arg, languages[i].name ) )
        {
            if ( xIS_SET( ch->race->flags, RFLAG_OWNLANG ) && languages[i].flag != ch->race->language )
            {
                ch_println( ch, "&wYou can only speak your own language." );
                return;
            }
            else if ( knows_language( ch, xchk, ch ) )
            {
                xCLEAR_BITS( ch->speaking );
                xSET_BIT( ch->speaking, languages[i].flag );
                set_char_color( AT_SAY, ch );
                ch_println( ch, "&wYou will now speak %s.", languages[i].name );
            }
            else
            {
                ch_println( ch, "&wYou don't know how to speak %s.", languages[i].name );
                return;
            }

            return;
        }
    }

    set_char_color( AT_SAY, ch );
    ch_println( ch, "&wYou do not know that language." );
    return;
}
/**
    Get a list of languages or learn a language from a teacher
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_languages( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[MIL];
    EXT_BV chk;
    int lang;
    SKILL_DATA* skill = NULL;
    int cnt = 0;
    argument = one_argument( argument, arg );

    if ( IS_NPC( ch ) )
        return;

    if ( arg[0] != '\0' && !str_prefix( arg, "learn" ) && !IS_NPC( ch ) )
    {
        CHAR_DATA* sch = NULL;
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zLearn which language?" );
            return;
        }

        for ( lang = 0; languages[lang].flag != LAST_FLAG_VALUE; lang++ )
        {
            if ( languages[lang].flag == LANG_SITH )
                continue;
            if ( !str_prefix( arg2, languages[lang].name ) )
                break;
        }

        if ( languages[lang].flag == LAST_FLAG_VALUE )
        {
            ch_println( ch, "&zThat is not a language." );
            return;
        }

        if ( languages[lang].flag == LANG_LORRDIAN && !xIS_SET( ch->race->specflags, RSPECFLAG_LORRDIAN ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
        {
            ch_println( ch, "&zThat language is only available to the Lorrdians!" );
            return;
        }

        if ( languages[lang].flag == LANG_YUUZHAN_VONG && !xIS_SET( ch->race->flags, RFLAG_VONG ) )
        {
            ch_println( ch, "&zYou'll have to find someone with special knowledge of that language!" );
            return;
        }

        if ( languages[lang].flag == LANG_DATHOMIRI && !xIS_SET( ch->race->specflags, RSPECFLAG_DATHOMIRI ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
        {
            ch_println( ch, "&zThat language is only able to be spoken by Dathomiri!" );
            return;
        }

        if ( languages[lang].flag == LANG_YEVETHAN && !xIS_SET( ch->race->specflags, RSPECFLAG_YEVETHAN ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) )
        {
            ch_println( ch, "&zThat language is too complex for you to learn." );
            return;
        }

        if ( ( skill = language_table[lang] ) == NULL )
        {
            ch_println( ch, "&zThat is not a language." );
            return;
        }

        if ( get_learned_pct( ch, skill ) >= 100 )
        {
            ch_println( ch, "&zYou are already fluent in &C%s&z.", languages[lang].name );
            return;
        }

        if ( !IS_IMMORTAL( ch ) && !xIS_SET( ch->race->flags, RFLAG_TRANSLATOR ) && count_langs( ch ) >= lang_limit( ch ) && get_learned_pct( ch, skill ) == 0 )
        {
            ch_println( ch, "&wLearning another language is beyond you at this point." );
            return;
        }

        xSET_BIT( chk, languages[lang].flag );

        /*
            if ( knows_language( sch, ch->speaking, ch ) && knows_language( sch, chk, sch ) )
            if ( xIS_EMPTY(sch->speaking) || knows_language( ch, sch->speaking, sch ) )
        */

        for ( sch = ch->in_room->first_person; sch != NULL; sch = sch->next_in_room )
            if ( IS_NPC( sch ) && xIS_SET( sch->act, ACT_SCHOLAR ) )
                break;

        if ( sch == NULL || !IS_NPC( sch ) )
        {
            ch_println( ch, "&zThere is no one who can teach that language here." );
            return;
        }

        if ( !knows_language( sch, ch->speaking, ch ) )
        {
            do_say( sch, "&wSorry, I don't understand what you're saying!" );
            return;
        }

        if ( !knows_language( sch, chk, sch ) )
        {
            do_say( sch, "&wSorry, I can't teach you that language. I don't know it." );
            return;
        }

        if ( ch->gold < 5 )
        {
            ch_println( ch, "&zLanguage lessons cost &C5 &zcredits...you don't have enough.&w" );
            return;
        }

        ch->gold -= 5;

        if ( !IS_NPC( ch ) )
            sql_credits_log( ch->name, "do_languages", -5, TRUE );

        //Spamming to learn a language is kind of a needless thing. Just go straight to 100, there is no value or point in not having 100. Gathorn 16Jun19
        set_learned_pct( ch, skill,  100 );
        xSET_BIT( ch->speaks, languages[lang].flag );
        ch_println( ch, "&zYou now speak perfect &C%s&z.", languages[lang].name );
        return;
    }

    for ( int i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
    {
        if ( languages[i].flag == LANG_CLAN || languages[i].flag == LANG_SITH )
            continue;

        skill = language_table[i];

        if ( skill == NULL )
            continue;

        bool speaking = xIS_SET( ch->speaking, languages[i].flag ) || ( IS_NPC( ch ) && xIS_EMPTY( ch->speaking ) );

        if ( languages[i].flag == LANG_YUUZHAN_VONG && get_learned_pct( ch, skill ) == 0 && !speaking )
            continue;

        cnt++;
        snprintf( buf, MIL, "%s%s%s", speaking ? "&C" : "&B", languages[i].name, speaking ? " &z(&CSpeaking&z)" : "" );
        pager_printf( ch, "&z(&C%1s&z) %-*s", get_learned_pct( ch, skill ) > 0 ? "X" : " ", 20 + ( strlen( buf ) - strlen( stripclr( buf ) ) ), buf );
        if ( cnt % 3 == 0 )
            pager_println( ch, "" );
    }

    pager_println( ch, "\n&CX&w learned language" );

    if ( !IS_NPC( ch ) && lang_limit( ch ) > count_langs( ch ) )
    {
        pager_printf( ch, "&wYou can learn %d more language%s.\n", ( lang_limit( ch ) - count_langs( ch ) ),
                      ( lang_limit( ch ) - count_langs( ch ) ) > 1 ? "s" : "" );
    }

    return;
}

// Compare tones by category, then by name.
int compare_tones( DB_DATA** t1p, DB_DATA** t2p )
{
    DB_DATA* t1 = ( *t1p );
    DB_DATA* t2 = ( *t2p );

    if ( !t1 && !t2 )
        return 0;

    if ( !t1 && t2 )
        return 1;

    if ( !t2 && t1 )
        return -1;

    // Special-sort uncategorized ones last.
    if ( t1->str1[0] == '\0' && t2->str1[0] != '\0' )
        return 1;

    if ( t1->str1[0] != '\0' && t2->str1[0] == '\0' )
        return -1;

    int category_cmp = strcasecmp( t1->str1, t2->str1 );

    if ( category_cmp != 0 )
        return category_cmp;

    return strcasecmp( t1->name, t2->name );
}

/**
    Change your tone of voice
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_tone( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    argument = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Ctone list                &z- List all available tones" );
        ch_println( ch, "&zSyntax: &Ctone list <&wfilter&C>       &z- List all tones matching a filter" );
        ch_println( ch, "&zSyntax: &Ctone <&wname, or none&C>     &z- Set your current speech tone" );

        if ( IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "" );
            ch_println( ch, "&zSyntax: &Ctone create <&wname&C>" );
            ch_println( ch, "&zSyntax: &Ctone set <&wname&C> category <&wcategory, or none&C>" );
            ch_println( ch, "&zSyntax: &Ctone set <&wname&C> adverb <&wadverb, or none&C> &z- Force an adverb if necessary" );
            ch_println( ch, "&zSyntax: &Ctone set <&wname&C> disabled &z- Hide this tone from the list going forward" );
            ch_println( ch, "&zSyntax: &Ctone set <&wname&C> enabled  &z- Add the tone back to the list." );
        }

        DB_DATA* current_tone = find_tone( get_tone( ch ) );
        ch_println( ch, "\n&zYour current tone is: &C%s", current_tone ? current_tone->name : "(unknown)" );
        return;
    }

    if ( !str_cmp( arg1, "list" ) )
    {
        char* arg_lower = strlower( argument );
        // Count tones we'll display so we can allocate the array
        int tone_ct = 0;

        for ( DB_DATA* db = first_tone; db; db = db->next )
        {
            // No need to show "none", it's implied. Also, hide disabled tones from players.
            if ( !str_cmp( db->name, "none" ) || ( db->num1 && !IS_IMMORTAL( ch ) ) )
                continue;

            // Filter by name and category
            if ( arg_lower[0] == '\0' || strstr( db->name, arg_lower ) || strstr( db->str1, arg_lower ) )
                tone_ct++;
        }

        if ( tone_ct == 0 )
        {
            ch_println( ch, "&RNo matching tones found." );
            return;
        }

        // Copy tone pointers to display into an array for sorting
        DB_DATA* tone_arr[tone_ct];
        tone_ct = 0;

        for ( DB_DATA* db = first_tone; db; db = db->next )
        {
            // No need to show "none", it's implied. Also, hide disabled tones from players.
            if ( !str_cmp( db->name, "none" ) || ( db->num1 && !IS_IMMORTAL( ch ) ) )
                continue;

            // Filter by name and category
            if ( arg_lower[0] == '\0' || strstr( db->name, arg_lower ) || strstr( db->str1, arg_lower ) )
                tone_arr[tone_ct++] = db;
        }

        qsort( &tone_arr[0], tone_ct, sizeof( DB_DATA* ), ( int( * )( const void*, const void* ) ) compare_tones );
        int category_count = 0;
        char* current_category = NULL;

        for ( int i = 0 ; i < tone_ct; i++ )
        {
            if ( !current_category || str_cmp( current_category, tone_arr[i]->str1 ) )
            {
                if ( i > 0 )
                    ch_println( ch, "" );

                if ( category_count % 5 > 0 )
                    ch_println( ch, "" );

                category_count = 0;
                current_category = tone_arr[i]->str1;

                if ( !NULLSTR( current_category ) )
                    ch_println( ch, "&C%s tones:", capitalize( current_category ) );
                else
                    ch_println( ch, "&CUncategorized tones:" );
            }

            ch_printf( ch, "%s%-15s ", tone_arr[i]->num1 ? "&R" : "&z", tone_arr[i]->name );

            if ( ++category_count % 5 == 0 )
                ch_println( ch, "" );
        }

        if ( category_count % 5 > 0 )
            ch_println( ch, "" );

        if ( IS_IMMORTAL( ch ) )
            ch_println( ch, "&z\nTones listed in &Rred&z are disabled and not available to players." );

        return;
    }
    else if ( IS_IMMORTAL( ch ) && !str_cmp( arg1, "create" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Ctone create <&wname&C>" );
            return;
        }

        DB_DATA* tone = find_tone_by_name( argument, true );

        if ( tone != NULL )
        {
            ch_println( ch, "&RTone already exists." );
            return;
        }

        char* arg_lower = strlower( argument );
        CREATE( tone, DB_DATA, 1 );
        tone->id = 0;
        SET_STRING( tone->name, arg_lower );
        SET_STRING( tone->str1, "" ); // Category, set it as blank to start with
        SET_STRING( tone->str2, "" );
        tone->num1 = 0; // No-op for clarity: num1 is the "disabled" field. 0=enabled, 1=disabled
        LINK( tone, first_tone, last_tone, next, prev );
        save_dbase_sql(DB_TABLE_TONES,tone);
        ch_println( ch, "&zTone created: &B%s", tone->name );
        return;
    }
    else if ( IS_IMMORTAL( ch ) && !str_cmp( arg1, "set" ) )
    {
        argument = one_argument( argument, arg2 );

        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&RSet which tone?" );
            return;
        }

        DB_DATA* tone = find_tone_by_name( arg2, true );

        if ( tone == NULL )
        {
            ch_println( ch, "&RUnrecognized tone." );
            return;
        }

        argument = one_argument( argument, arg3 );

        if ( NULLSTR( arg3 ) )
        {
            ch_println( ch, "&RSet which property of that tone?" );
            return;
        }
        else if ( !str_cmp( arg3, "category" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "&RSet that tone's category to what?" );
                return;
            }


            char* arg_lower = strlower( argument );
            SET_STRING( tone->str1, !str_cmp( arg_lower, "none" ) ? "" : arg_lower );
            save_dbase_sql(DB_TABLE_TONES,tone);
            ch_println( ch, "&zTone category set to: &B%s", tone->str1[0] != '\0' ? tone->str1 : "none" );
            return;
        }
        else if ( !str_cmp( arg3, "adverb" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "&RSet that tone's adverb override to what?" );
                return;
            }

            char* arg_lower = strlower( argument );
            SET_STRING( tone->str2, !str_cmp( arg_lower, "none" ) ? "" : arg_lower );
            save_dbase_sql(DB_TABLE_TONES,tone);
            ch_println( ch, "&zTone adverb override set to: &B%s", tone->str2[0] != '\0' ? tone->str2 : "none" );
            return;
        }
        else if ( !str_cmp( arg3, "enabled" ) )
        {
            if ( tone->num1 == 0 )
            {
                ch_println( ch, "&RTone already enabled." );
                return;
            }

            tone->num1 = 0;
            save_dbase_sql( DB_TABLE_TONES,tone );
            ch_println( ch, "&zTone &B%s&z enabled.", tone->name );
            return;
        }
        else if ( !str_cmp( arg3, "disabled" ) )
        {
            if ( tone->num1 == 1 )
            {
                ch_println( ch, "&RTone already disabled." );
                return;
            }

            tone->num1 = 1;
            save_dbase_sql( DB_TABLE_TONES,tone );
            ch_println( ch, "&zTone &B%s&z disabled.", tone->name );
            return;
        }
        else
        {
            ch_println( ch, "&RUnsupported tone property name." );
            return;
        }
    }

    DB_DATA* db = find_tone_by_name( arg1, false );

    if ( db != NULL )
    {
        set_tone( ch, db->id );
        ch_println( ch, "&zSpeaking tone set to &B%s&z.", db->name );
        return;
    }

    ch_println( ch, "&RUnrecognized tone. Try a different one." );
    return;
}

int dispatch_rpcto_or_mortchat(CHAR_DATA *from, CHAR_DATA *to, ACCOUNT_DATA *from_account, ACCOUNT_DATA *to_account, const char *message, bool is_rpcto, int flags) {  
    const char *from_name;
    const char *to_name;
    if(((!from && !from_account) || (!to && !to_account)) || !message) {
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    if(is_rpcto && !to) {
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    from_name = from ? from->name : from_account->name;
    to_name = to ? to->name : to_account->name;

    if(!to_account && to && to->pcdata->account) {
        to_account = to->pcdata->account;
    }

    // always upgrade to an account level message when we can.
    if(to_account && !is_rpcto) {
        int rval;
        char buf[MSL];
        snprintf( buf, MSL, "&B( &WIMM &B| &WCHAT &B)&w %s mortchats to you &B'&w%s&B'&W\n\r", from_name, message );
        if ( (rval = account_broadcast(to_account, buf) != E_LOTJ_SUCCESS ) ) {
            // they are not online, and we can't send them a message via discord.
            return rval;
        }
    } else if(to) {
        if( is_rpcto ) {
            ch_printf(to, "&z(&YR&z|&YP&z|&YC&z)&w %s says to you &Y'&O%s&Y'\n\r", from_name, message);
        } else {   
            ch_printf(to, "&B( &WIMM &B| &WCHAT &B)&w&w %s mortchats to you &B'&w%s&B'&W\n\r", from_name, message);
        }
    } else {
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    if(from) {
        if( is_rpcto ) {
            ch_printf(from, "&z(&YR&z|&YP&z|&YC&z)&w You say to %s &Y'&O%s&Y'\n\r", to_name, message);
        } else {
            ch_printf(from, "&B( &WIMM &B| &WCHAT &B)&w You mortchat to %s &B'&w%s&B'&W\n\r", to_name, message);
        }
    }

    if (is_rpcto) {
        char buf[MSL];
        snprintf( buf, MSL, "&z(&YR&z|&YP&z|&YC&z) &w%s says to %s &Y'&O%s&Y'\n\r", from_name, to_name, message );
        to_ooc_talk_channel(from, from_account, to, CHANNEL_RPC, buf, flags | RAW_OUTPUT);
    } else {
        char buf[MSL];
        snprintf( buf, MSL, "&B( &WIMM &B| &WCHAT &B)&w %s mortchats to %s &B'&w%s&B'&W\n\r", from_name, to_name, message );
        to_ooc_talk_channel(from, from_account, to, CHANNEL_IMMCHAT, buf, flags | RAW_OUTPUT);
    }

    return E_LOTJ_SUCCESS;

}
/**
    Send a message to a player (from an imm)
    @see do_immchat
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_mortchat( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    DESCRIPTOR_DATA* d;
    ACCOUNT_DATA* acc = NULL;
    argument = one_argument( argument, arg );

    if ( !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax:&C mortchat <&wmortal&C> <&wmessage&C>&w" );
        return;
    }

    victim = get_player_world( arg );

    if ( victim == NULL || IS_NPC( victim ) || get_trust( victim ) > get_trust( ch ) || !victim->desc )
    {
        if ( arg[0] == '@' )
        {
            if ( ( acc = get_account( arg + 1 ) ) )
            {
                for ( d = first_descriptor; d; d = d->next )
                    if ( d->account && d->account == acc )
                        break;

                if ( d && d->character && ( d->connected == CON_PLAYING || d->connected == CON_EDITING ) )
                    victim = d->character;
            }
        }
        else
        {
            acc = account_get_from_char( arg );

            if(acc && acc->level > get_trust(ch)) {
                acc = NULL;
            }

            if ( !acc )
            {
                ch_println( ch, "They are not online." );
                return;
            }
        }
    }

    if ( victim && victim == ch )
    {
        ch_println( ch, "Why would you want to mortchat to yourself?" );
        return;
    }

    if ( victim && victim->top_level > ch->top_level )
    {
        ch_println( ch, "Why don't you just use IMMTALK?" );
        return;
    }

    int rval;
    if ( ( rval = dispatch_rpcto_or_mortchat(ch, victim, NULL, acc, argument, FALSE, 0) ) != E_LOTJ_SUCCESS ) {
        ch_printf( ch, "Unable to send mortchat, are you sure they are online and/or have discord confirmed? (%s)\n\r", lotj_strerror(rval) );
        return;
    }

    return;
}
/**
    Channel for players to ask privately for imm help (only visible by imms, but usable by any player)
    @see do_mortchat
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_immchat( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    if ( NOT_AUTHED( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cimmchat <&wmessage&C>" );
        ch_println( ch, "&wThis channel lets you speak privately with LOTJ's immortal staff." );
        ch_println( ch, "&wWhat would you like to say?" );
        return;
    }

    snprintf( buf, MSL, "&B( &WIMM &B| &WCHAT &B)&w&W[&C%s&W]&w: &B'&w%s&B'&w\r\n", ch->name, argument );
    send_to_char( buf, ch );

    int rval;
    if ( ( rval = to_ooc_talk_channel( ch, NULL, NULL, CHANNEL_IMMCHAT, argument, 0 ) ) != E_LOTJ_SUCCESS ) {
        lognormal( "do_immchat: to_ooc_talk_channel failed with rval %d (%s)", rval, lotj_strerror(rval) );
        return;
    }
    return;
}

/**
    Channel for RPC members to send messages to players on
    @see do_rpc
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_rpcto( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim = NULL;
    DESCRIPTOR_DATA* d = NULL;
    ACCOUNT_DATA* acc = NULL;
    argument = one_argument( argument, arg );

    if ( !IS_RPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax:&C rpcto <&wmortal&C> <&wmessage&C>&w" );
        return;
    }

    victim = get_player_world( arg );

    if ( victim == NULL || IS_NPC( victim ) || get_trust( victim ) > get_trust( ch ) )
    {
        if ( arg[0] == '@' && get_trust( ch ) >= sysdata.log_level )
        {
            if ( ( acc = get_account( arg + 1 ) ) )
            {
                for ( d = first_descriptor; d; d = d->next )
                    if ( d->account && d->account == acc )
                        break;

                if ( d && d->character && ( d->connected == CON_PLAYING || d->connected == CON_EDITING ) )
                    victim = d->character;
            }
        }
        else
        {
            acc = account_get_from_char( arg );

            if(acc && acc->level > get_trust(ch)) {
                acc = NULL;
            }

            if ( !acc )
            {
                ch_println( ch, "They are not online." );
                return;
            }
        }
    }

    int rval;
    if ( ( rval = dispatch_rpcto_or_mortchat(ch, victim, NULL, acc, argument, TRUE, 0) ) != E_LOTJ_SUCCESS ) {
        ch_printf( ch, "Unable to send rpcto, are you sure they are online and/or have discord confirmed? (%s)\n\r", lotj_strerror(rval) );
        return;
    }

    if ( getRPC( ch->name ) )
        add_rpcto( getRPC( ch->name ) );

    return;
}
/**
