DB_DATA* find_tone_by_name( char* name, bool include_disabled )
{
    char* name_lower = strlower( name );

    // First look for exact matches (and filter out disabled tones, where num1 == 1)
    for ( DB_DATA* db = first_tone; db; db = db->next )
        if ( ( !db->num1 || include_disabled ) && !strcmp( name_lower, db->name ) )
            return db;

    // Next look for prefix matches
    for ( DB_DATA* db = first_tone; db; db = db->next )
        if ( ( !db->num1 || include_disabled ) && !str_prefix( name_lower, db->name ) )
            return db;

    return NULL;
}

DB_DATA* find_tone( int id )
{
    for ( DB_DATA* db = first_tone; db; db = db->next )
        if ( db->id == id )
            return db;

    return NULL;
}

/**
    Convert from tone name to grammatically correct tone descriptor
    @see tone_convert_format
    @return Converted tone message
*/
char* tone_convert( CHAR_DATA* ch, CHAR_DATA* listener )
{
    static char buf[MSL];
    strlcpy( buf, "", MSL );

    if ( !ch || char_extracted( ch ) )
        return buf;

    int tone = get_tone( ch );
    DB_DATA* db = find_tone( tone );
    // For screenreaders, determine whether we should print the text color.
    // We generally don't want to do it for characters they know, since that's unnecessary to identify them
    bool print_color = FALSE;

    if ( listener && !char_extracted( listener ) )
    {
        bool known = FALSE;

        if ( listener == ch
                || IS_IMMORTAL( ch )
                || IS_NPC( ch )
                || ( knows_player( listener, ch, GREET_ANY, true ) && !obj_mask( ch ) ) )
            known = TRUE;

        print_color = listener && !known && has_pcflag( listener, PCFLAG_SCREENREADER );
    }

    if ( db != NULL && str_cmp( db->name, "none" ) )
    {
        // If the tone's override adverb is set, just return that directly.
        if ( db->str2 && db->str2[0] != '\0' && str_cmp( db->str2, "(null)" ) )
        {
            if ( print_color )
                snprintf( buf, MSL, "%s in %s ", db->str2, txtclr_names[get_txtclr( ch )] );
            else
                snprintf( buf, MSL, "%s ", db->str2 );

            return buf;
        }

        strlcpy( buf, db->name, MSL );
        int pnt = strlen( db->name ) - 1;

        if ( pnt > 0 )
        {
            if ( buf[pnt] == 'y' )
                buf[pnt] = 'i';

            if ( buf[pnt] == 'l' && buf[pnt - 1] == 'l' )
                strlcat( buf, "y ", MSL );
            else
            {
                // Gralhack for except of word ending in e thats drops to y ie miserable miserably indecipherabely indecipherably
                // Gralhack is this a rule or exception?  ie check for l by pnt = strlen( db->name ) - 2; if ends in e
                if ( ( buf[pnt - 1] == 'l' ) && ( buf[pnt] == 'e' ) )
                {
                    buf[pnt] = 'y';
                    strlcat( buf, " ", MSL );
                }
                else
                    strlcat( buf, "ly ", MSL );
            }
        }

        if ( print_color )
        {
            strlcat( buf, "in ", MSL );
            strlcat( buf, txtclr_names[get_txtclr( ch )], MSL );
            strlcat( buf, " ", MSL );
        }
    }
    else if ( print_color )
    {
        snprintf( buf, MSL, "in %s ", txtclr_names[get_txtclr( ch )] );
    }

    return buf;
}
/**
    Convert from tone # to grammatically correct tone descriptor
    WITH formatting/color
    @see tone_convert
    @return Converted tone message
    @param tone Tone to convert
*/
char* tone_convert_format( CHAR_DATA* ch, CHAR_DATA* listener )
{
    static char buf[MSL];
    strlcpy( buf, "", MSL );
    char* tone_msg = tone_convert( ch, listener );

    if ( !NULLSTR( tone_msg ) )
        snprintf( buf, MSL, "&W( &z%s&W)", tone_msg );

    return buf;
}
/**
    Updated to allow 102s to use, and 101s to not see/use
    Private builder (102) chat channel
    must be bestowed with 'builder' to use if level < 102
    @see do_i103
    @see do_i104
    @see do_i105
    @see do_i200
    @see do_council
    @see do_immtalk
    @see do_buildernet
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_buildernet( CHAR_DATA* ch, char* argument )
{
    DESCRIPTOR_DATA* d = NULL;
    char buf[MSL];
    char buf2[MSL];

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "What would you like to say on BuilderNet?" );
        return;
    }

    if ( !is_name( "builder", ch->pcdata->bestowments ) && get_trust( ch ) < 102 )
    {
        ch_println( ch, "You aren't a builder!" );
        return;
    }

    snprintf( buf, MSL, "&WB&wu&wi&zl&zd&we&wr&WN&we&zt&Y[&W%s&Y]&z: &w%s\n", ch->name, argument );
    snprintf( buf2, MSL, "&WB&wu&wi&zl&zd&we&wr&WN&we&zt&Y[&WSomeone&Y]&z: &w%s\n", argument );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( get_trust( d->character ) < 102 )
            continue;

        if ( can_see( d->character, ch ) || ch == d->character )
            send_to_char( buf, d->character );
        else
            send_to_char( buf2, d->character );
    }

    return;
}

