/**
    IC clan-to-clan communication channel
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_clan_message( CHAR_DATA* ch, char* argument )
{
    CLAN_DATA* clanA = NULL, *clanB = NULL;
    DESCRIPTOR_DATA* d = NULL;
    char arg[MIL];
    char buf[MSL];
    argument = one_argument( argument, arg );

    if ( NULLSTR( argument ) )
    {
        send_to_char( "clanmessage <clan> <message>\n"
                      "This will send a message with your name from your clan "
                      "to the clan you specify.\n", ch );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "&wYou cannot communicate while sleeping!" );
        return;
    }

    // GRAL Stopped clanmessage while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak through the communication system but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't use communications while gagged." );
        // GRAL Do we want a noise perhaps? Check if they at least have hands to push a button?
        return;
    }

    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "The language of the Lorrdians is physical." );
        return;
    }

    if ( !IS_NPC( ch ) && count_args( argument ) > 3 && xIS_SET( ch->race->flags, RFLAG_STUPID ) )
    {
        ch_println( ch, "&wYou aren't intelligent enough to form sentences greater than three words in length!" );
        return;
    }
    else if ( !IS_NPC( ch ) && get_curr_int( ch ) < 12 && count_args( argument ) > ( get_curr_int( ch ) / 3 ) + 2 )
    {
        ch_println( ch, "&wYou aren't intelligent enough to form sentences greater than %d words in length!", ( get_curr_int( ch ) / 3 ) + 2 );
        return;
    }

    // GRAL Block silent room mpclanmessage as the channels are blocked here.
    if ( ( xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) || xIS_SET( ch->in_room->flags, ROOM_SILENCE ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RPublic communication channels are not available here." );
        return;
    }

    if ( is_disrupted( ch, TAP_COMM, false ) )
        return;

    argument = drunk_speech( argument, ch );

    if ( !IS_NPC( ch ) )
    {
        if ( !ch->pcdata->clan )
        {
            ch_println( ch, "You're not even in a clan." );
            return;
        }

        clanA = ch->pcdata->clan;

        if ( clanA == NULL )
            return;

        if ( !is_empowered( ch, "clan_message" ) && str_cmp( ch->name, clanA->leader ) )
        {
            ch_println( ch, "You're not authorized to send clan transmissions." );
            return;
        }

        if ( xIS_SET( ch->deaf, CHANNEL_CLAN ) )
        {
            ch_println( ch, "You are not listening to clan communications." );
            return;
        }
    }

    if ( get_comlink( ch ) == NULL )
    {
        ch_println( ch, "You have no comlink. Why don't you get one first?" );
        return;
    }

    clanB = get_clan( arg );

    if ( ( clanB == NULL  || ( clanB != NULL && xIS_SET( clanB->flags, CLAN_HIDDEN )  && !is_allied( clanA, clanB ) && !is_allied( clanB, clanA ) ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You don't know of a clan by that name." );
        return;
    }

    if ( clanA == clanB )
    {
        ch_println( ch, "Why send a transmission to your own organization?" );
        return;
    }

    if ( xIS_SET( clanB->flags, CLAN_VONG ) )
    {
        ch_println( ch, "They don't operate on any known interorganizational frequency." );
        return;
    }

    if ( ch->in_room && ch->in_room->area )
    {
        CHAR_DATA* rch = NULL;

        for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        {
            if ( rch == ch )
                continue;

            if ( rch->position < POS_RESTING )
                continue;

            if ( ch->in_room->area->ambience == 1 )
            {
                if ( !knows_language( rch, ch->speaking, ch ) && ( !IS_NPC( ch ) || !xIS_EMPTY( ch->speaking ) ) )
                    ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), scramble_text( argument, ch->speaking ) );
                else
                    ch_println( rch, "&z%s %swhispers '%s' into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ), argument );
            }
            else
                ch_println( rch, "&z%s %swhispers into a comlink.", PERS( ch, rch ), tone_convert( ch, NULL ) );
        }
    }

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( ( !d->character->pcdata->clan || d->character->pcdata->clan != clanB ) || get_comlink( d->character ) == NULL )
            continue;

        if ( xIS_SET( d->character->deaf, CHANNEL_CLAN ) )
            continue;

        if ( d->character->in_room && ( xIS_SET( d->character->in_room->flags, ROOM_COMMSHIELD ) ||  xIS_SET( d->character->in_room->flags, ROOM_SILENCE ) ) )
            continue;

        if ( is_disrupted( d->character, TAP_COMM, true ) )
            continue;

        if ( d->character->position < POS_RESTING )
            continue;

        if ( !knows_language( d->character, ch->speaking, ch ) )
        {
            snprintf( buf, MSL, "&z&W&Y[&zIncoming Transmission from %s&Y]&w\n&z{%s&z}<%s&z>&W[&C%s&W]&W%s&W: <&zTranslation from %s&W %s%s",
                     ch->pcdata->clan->name, get_division( ch ), get_rank( ch ),
                     g_name( ch, d->character ),
                     tone_convert_format( ch, d->character ),
                     lang_convert_format( ch, ch->speaking, ch ),
                     txtclr( ch ),
                     argument
                   ); // GRAL lang_convert_format(ch, ch->speaking, ch) chosen so the language spoke is never hidden
        }
        else
        {
            snprintf( buf, MSL, "&z&W&Y[&zIncoming Transmission from %s&Y]&w\n&z{%s&z}<%s&z>&W[&C%s&W]&W%s%s&W: %s%s",
                     ch->pcdata->clan->name,
                     get_division( ch ), get_rank( ch ),
                     g_name( ch, d->character ),
                     tone_convert_format( ch, d->character ),
                     lang_convert_format( ch, ch->speaking, d->character ),
                     txtclr( ch ),
                     argument
                   );
        }

        send_to_char( buf, d->character );
        ch_println( d->character, "" );
    }

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( ( !d->character->pcdata->clan || d->character->pcdata->clan != clanA ) || get_comlink( d->character ) == NULL )
            continue;

        if ( xIS_SET( d->character->deaf, CHANNEL_CLAN ) )
            continue;

        if ( d->character->in_room && xIS_SET( d->character->in_room->flags, ROOM_COMMSHIELD ) )
            continue;

        if ( is_disrupted( d->character, TAP_COMM, true ) )
            continue;

        if ( d->character->position < POS_RESTING )
            continue;

        if ( !knows_language( d->character, ch->speaking, ch ) )
        {
            snprintf( buf, MSL, "&z&W&Y[&zOutgoing Transmission to %s&Y]&w\n&z{%s&z}<%s&z>&W[&C%s&W]&w%s&w: <&zTranslation from %s&W %s%s",
                     clanB->name,
                     get_division( ch ), get_rank( ch ),
                     g_name( ch, d->character ),
                     tone_convert_format( ch, d->character ),
                     lang_convert_format( ch, ch->speaking, ch ),
                     txtclr( ch ),
                     argument
                   ); // GRAL lang_convert_format(ch, ch->speaking, ch) chosen so the language spoke is never hidden
        }
        else
        {
            snprintf( buf, MSL, "&z&W&Y[&zOutgoing Transmission to %s&Y]&w\n&z{%s&z}<%s&z>&W[&C%s&W]&W%s%s&W: %s%s",
                     clanB->name,
                     get_division( ch ), get_rank( ch ),
                     g_name( ch, d->character ),
                     tone_convert_format( ch, d->character ),
                     lang_convert_format( ch, ch->speaking, d->character ),
                     txtclr( ch ),
                     argument
                   );
        }

        send_to_char( buf, d->character );
        ch_println( d->character, "" );
    }

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( get_trust( d->character ) < 104 )
            continue;

        if ( xIS_SET( d->character->deaf, CHANNEL_CLAN ) )
            continue;

        snprintf( buf, MSL, "&z&W&Y[&zTransmission from %s to %s&Y]&w\n&z{%s&z}<%s&z>&w[&C%s&w]%s%s&w: &w%s%s\n",
                 clanA->name,
                 clanB->name,
                 get_division( ch ), get_rank( ch ),
                 g_name( ch, d->character ),
                 tone_convert_format( ch, d->character ),
                 lang_convert_format( ch, ch->speaking, d->character ),
                 txtclr( ch ),
                 argument
               );
        send_to_char( buf, d->character );
    }
}
/**
    Capital game chat channel
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_cgtalk( CHAR_DATA* ch, char* argument )
{
    DESCRIPTOR_DATA* d;
    char buf[MSL];

    if ( IS_NPC( ch ) )
        return;

    if ( !has_pcflag( ch, PCFLAG_CG ) && get_trust( ch ) < 103 )
    {
        ch_println( ch, "&WHuh?" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "What would you like to say on CGtalk?" );
        return;
    }

    snprintf( buf, MSL, "&C[&wCG Arena&C]&231(&wChat&231) &231%s: &107%s", ch->name, argument );
    ch_println( ch, buf );

    for ( d = first_descriptor; d ; d = d->next )
    {
        if ( d->connected != CON_PLAYING )
            continue;

        if ( !d->character )
            continue;

        if ( d->character == ch )
            continue;

        if ( !has_pcflag( d->character, PCFLAG_CG )
                && get_trust( d->character ) < sysdata.log_level )
            continue;

        ch_println( d->character, buf );
    }

    return;
}
/**
    Set up a player as a CG character
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_cg( CHAR_DATA* ch, char* argument )
{
    if ( !str_cmp( "time", argument ) )
    {
        long tmp = 0, sec = 0;

        if ( sysdata.cgtime <= 0 )
        {
            ch_println( ch, "There is no CG open currently." );
            return;
        }

        tmp = current_time - sysdata.cgtime;
        sec = tmp;
        tmp /= 60;
        tmp = labs( tmp );
        sec %= 60;
        ch_println( ch, "The CG has been running for %ld minute%s, %ld second%s.", tmp, tmp != 1 ? "s" : "", sec, sec != 1 ? "s" : "" );
        return;
    }

    if ( !str_cmp( "open", argument ) )
    {
        if ( sysdata.cgtime > 0 )
        {
            ch_println( ch, "There is already a CG game open. Please use CG CLOSE to close it first." );
            return;
        }
        sysdata.cgtime = current_time;
        save_sysdata( &sysdata );
        ch_println( ch, "CG is now open." );
        return;
    }

    if ( !str_cmp( "close", argument ) )
    {
        if ( sysdata.cgtime == 0 )
        {
            ch_println( ch, "There is no CG in session." );
            return;
        }
        sysdata.cgtime = 0;
        save_sysdata( &sysdata );
        ch_println( ch, "CG is now closed." );

        for ( CHAR_DATA* victim = first_char; victim; victim = victim->next )
        {
            if ( is_cg( victim ) && victim->in_room->vnum != ROOM_CG && get_trust( victim ) < sysdata.log_level )
            {
                char_from_room( victim );
                char_to_room( victim, get_room_index( ROOM_CG ) );
            }

            if ( is_cg( victim ) )
            {
                victim->team = 0;
                ch_println( victim, "The CG is now over." );
            }
        }
        return;
    }

    ch_println( ch, "&zSyntax: &Ccg open  &z- Allow CG char creation/login" );
    ch_println( ch, "        &Ccg close &z- Move all CG chars to start room and block CG logins" );
    ch_println( ch, "        &Ccg time  &z- Show how long CG has been open" );
}

/**
    Who list for the capital game
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_cgwho( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    if ( sysdata.cgtime == 0 )
    {
        ch_println( ch, "A capital game is not currently running." );
        return;
    }

    ch_println( ch, "&C[&wCG Arena&C] &WActive Players:\n" );

    int count = 0;
    for ( int team = 0; team <= 4; team++ )
    {
        bool printed_any = false;
        for ( DESCRIPTOR_DATA* d = first_descriptor ; d ; d = d->next )
        {
            if ( !(d->connected == CON_PLAYING || d->connected != CON_EDITING)
                || !d->character
                || !has_pcflag( d->character, PCFLAG_CG )
            )
                continue;

            if ( d->character->team != team )
                continue;

            if ( !printed_any )
            {
                if ( team == 0 )
                    ch_println( ch, "&WUnassigned Players" );
                else if ( team == 1 )
                    ch_println( ch, "&RRed Team Roster" );
                else if ( team == 2 )
                    ch_println( ch, "&BBlue Team Roster" );
                else if ( team == 3 )
                    ch_println( ch, "&YYellow Team Roster" );
                else if ( team == 4 )
                    ch_println( ch, "&GGreen Team Roster" );
            }

            ch_println( ch, "&w  %s", d->character->name );
            printed_any = true;
            count++;
        }
        if ( printed_any )
            ch_println( ch, "" );
    }

    if ( count == 0 )
        ch_println( ch, "&wNo characters found." );
    else
        ch_println( ch, "&wTotal of %d players found.", count );
    return;
}
/**
    Change your text color
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_text_color( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "You may choose a number from the list of colors below." );
        ch_println( ch, "" );

        for ( int i = 0; i < txtclr_count; i++ )
        {
            ch_printf( ch, "&c%2d&z - %s%-14s", i, txtclr_codes[i], capitalize( txtclr_names[i] ) );

            if ( i % 2 == 1 )
                ch_println( ch, "" );
        }

        ch_println( ch, "\n&zSyntax: &Ctextcolor <&w# of desired color&C>" );

        if ( ( !ch->disguise && ch->txtclr >= 0 && ch->txtclr < txtclr_count ) || ( ch->disguise && ch->disguise->txtclr >= 0 && ch->disguise->txtclr < txtclr_count ) )
            ch_println( ch, "&wYour current text color is %s%s &w(#%d)",
                       txtclr_codes[get_txtclr( ch )],
                       txtclr_names[get_txtclr( ch )],
                       get_txtclr( ch ) );

        return;
    }

    if ( atoi( argument ) > -1 && atoi( argument ) < txtclr_count )
    {
        set_txtclr( ch, atoi( argument ) );
        ch_println( ch, "Text color set to %s%s.", txtclr_codes[get_txtclr( ch )], txtclr_names[get_txtclr( ch )] );
        save_char_obj( ch, TRUE );
        return;
    }
    else
    {
        ch_println( ch, "Color value out of range." );
        return;
    }
}
/**
    Get current text color code for a character
    @param ch Character to get text color for
    @return Color code for their current text color
*/
char* txtclr( CHAR_DATA* ch )
{
    static char tmp[MSL];
    // GRAL Nice. We jack 16 characters for each person in a room during talks as we text CLEAR it.
    // strlcpy(tmp, "&z&Y&W&g&G&W&O&g",MSL);
    strlcpy( tmp, "", MSL );

    if ( !ch || char_extracted( ch ) )
        return tmp;

    if ( ( !ch->disguise && ( ch->txtclr < 0 || ch->txtclr >= txtclr_count ) ) || ( ch->disguise && ( ch->disguise->txtclr < 0 || ch->disguise->txtclr >= txtclr_count ) ) )
    {
        bug( "txtclr - %s out of range (%d)", ch->name, get_txtclr( ch ) );
        strlcpy( tmp, "", MSL );
    }
    else
    {
        strlcat( tmp, txtclr_codes[get_txtclr( ch )], MSL );
    }

    return tmp;
}

