/**
    Change your active comlink
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_current_comlink( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj = NULL;
    char cbuf[MSL];

    if ( NULLSTR( argument ) )
    {
        // GRAL Doesn't take into account MONITORs
        if ( ch->curr_comlink != NULL )
            snprintf( cbuf, MSL, "&zFrequency: &C%d &zEncryption: &C%d", ch->curr_comlink->value[5], ch->curr_comlink->value[4] );

        ch_println( ch, "&zCurrent comlink: &C%s &z%s", ch->curr_comlink != NULL ? ch->curr_comlink->short_descr : "(none)", ch->curr_comlink != NULL ? cbuf : "" );
        ch_println( ch, "&zTo change your current comlink, try specifying a comlink you have." );
        return;
    }

    if ( !str_cmp( argument, "none" ) )
    {
        ch->curr_comlink = NULL;
        ch_println( ch, "Current comlink cleared." );
        return;
    }

    if ( ( obj = get_obj_wear( ch, argument ) ) == NULL )
    {
        if ( ( obj = get_obj_carry( ch, argument ) ) == NULL )
        {
            ch_println( ch, "&zYou don't have that item!" );
            return;
        }
    }

    if ( obj->item_type != ITEM_COMLINK )
    {
        ch_println( ch, "Try that on a comlink." );
        return;
    }

    if ( ch->curr_comlink == obj )
    {
        ch_println( ch, "That comlink is already your current one." );
        return;
    }

    if ( ch->curr_comlink )
    {
        ch_println( ch, "Changing current comlink from %s to %s.", ch->curr_comlink->short_descr, obj->short_descr );
        snprintf( cbuf, MSL, "&zFrequency: &C%d &zEncryption: &C%d", obj->value[5], obj->value[4] );
        ch_println( ch, "&zCurrent comlink now: &C%s &z%s", obj->short_descr, cbuf );
    }
    else
    {
        ch_println( ch, "Current comlink set to %s.", obj->short_descr );
        snprintf( cbuf, MSL, "&zFrequency: &C%d &zEncryption: &C%d", obj->value[5], obj->value[4] );
        ch_println( ch, "&zCurrent comlink now: &C%s &z%s", obj->short_descr, cbuf );
    }

    ch->curr_comlink = obj;
}
/**
    Get the clan division someone is in
