/**
    Send a clan message from IMM to a clan
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_immclan( CHAR_DATA* ch, char* argument )
{
    CLAN_DATA* clanA = NULL, *clanB = NULL;
    char arg[MIL];
    char buf[MSL];
    int tmpnum = 0;
    argument = one_argument( argument, arg );

    if ( NULLSTR( argument ) )
    {
        send_to_char( "immclan <clan> <message>\n"
                      "This will send a message with your name from the IMMs"
                      "to the clan you specify.\n", ch );
        return;
    }

    if ( ( get_trust( ch ) < sysdata.log_level && get_trust( ch ) < 102 ) || IS_NPC( ch ) )
    {
        ch_println( ch, "&W&wHuh?" );
        return;
    }

    if ( ( clanB = get_clan( arg ) ) == NULL )
    {
        ch_println( ch, "You don't know of a clan by that name." );
        return;
    }

    clanA = ch->pcdata->clan;
    snprintf( buf, MSL, "&z&W&Y&W[&COutgoing message to %s&W]: %s%s", clanB->name, txtclr( ch ), argument );
    do_immtalk( ch, buf );
    tmpnum = clanB->members;
    ch->pcdata->clan = clanB;
    snprintf( buf, MSL, "&z&W&Y&W[&CIncoming message from the &z(&WIMMS&z)&W]: %s%s", txtclr( ch ), argument );
    do_clantalk( ch, buf );
    ch->pcdata->clan = clanA;

    if ( clanB->members != tmpnum )
        clanB->members = tmpnum;

    save_clan( clanB, true );
    return;
}
