/**
    Planet-wide, clan-specific IC chat network
    @param ch Character using the command
    @param argument Arguments being passed
*/
CMDF do_planet_talk( CHAR_DATA* ch, char* argument )
{
    PLANET_DATA* planet = NULL;
    DESCRIPTOR_DATA* d = NULL;

    if ( !ch->in_room || !ch->in_room->area->planet )
    {
        ch_println( ch, "You're not even on a planet!" );
        return;
    }

    planet = ch->in_room->area->planet;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Usage: ptalk <message>\nThis will send a message to all your fellow clanmates on the planet, so long as your clan owns it." );
        return;
    }

    if ( IS_NPC( ch ) )
    {
        if ( !is_troop( ch ) && !is_pol( ch ) )
            return;
    }
    else if ( !ch->pcdata->clan || ( ch->pcdata->clan != planet->governed_by && planet->governed_by ) )
    {
        ch_println( ch, "You cannot access the planetary network." );
        return;
    }

    if ( !get_comlink( ch ) )
    {
        ch_println( ch, "You need a comlink to do that!" );
        return;
    }

    for ( d = first_descriptor ; d ; d = d->next )
    {
        if ( !d->character )
            continue;

        /* Get only those in the system - we want navy and army to talk */
        if ( in_starsystem( ch ) != in_starsystem( d->character ) )
            continue;

        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( get_trust( d->character ) < sysdata.log_level && ( !d->character->pcdata->clan || d->character->pcdata->clan != ch->pcdata->clan ) )
            continue;/* GRAL Walldo crash - this should be a break */

        /* GRAL TEMP Fixed extra color code (  )[Walldo](Comm Officer){Imperial Engineering Corps}&w: seductively blah */
        ch_println( d->character, "%s&z{%s&z}<%s&z>&W[&C%s&W]&W%s%s&W: %s%s", planet->gov_name, get_division( ch ), get_rank( ch ), ch->name, tone_convert_format( ch, d->character ), lang_convert_format( ch, ch->speaking, ch ), txtclr( ch ), argument );
    }
}
/**
    Count how many languages ch knows (>0%)
    @param ch Character to tally languages for
    @return Number of languages known
*/
int count_langs( CHAR_DATA* ch )
{
    int cnt = 0;
    SKILL_DATA* skill = NULL;

    if ( IS_NPC( ch ) )
        return count_bits( ch->speaks );

    for ( skill = last_skill; skill; skill = skill->prev )
        if ( skill->type == SKILL_TONGUE && get_learned_pct( ch, skill ) > 0 )
            cnt++;

    return cnt;
}

/*  int lang_limit( CHAR_DATA *ch )
    {
    return ( get_curr_int( ch ) / 5 );
    }*/
int lang_limit( CHAR_DATA* ch )
{
    int cnt = 0;

    if ( has_feat( ch, cache_skill( "communicator", &skill_communicator ) ) )
        cnt += 2;

    if ( has_feat( ch, cache_skill( "master communicator", &skill_master_communicator ) ) )
        cnt += 3;

    int int_for_languages = get_curr_int( ch );
    return ( int_for_languages / 5 ) + cnt;
}

DB_DATA* get_mindtalk( CHAR_DATA* ch, bool accepted )
{
    for ( DB_DATA* mtalk = first_mtalk; mtalk; mtalk = mtalk->next )
    {
        if ( !str_cmp( mtalk->name, ch->name ) || !str_cmp( mtalk->str1, ch->name ) )
        {
            if ( accepted && mtalk->num1 == 1 )
                return mtalk;

            if ( !accepted && mtalk->num1 == 0 )
                return mtalk;
        }
    }

    return NULL;
}

CMDF do_mindtalk( CHAR_DATA* ch, char* argument )
{
    DB_DATA* mtalk = NULL;
    CHAR_DATA* victim = NULL;

    if ( NULLSTR( argument ) )
    {
        send_to_char( "&zSyntax: &Cmindtalk <&wmessage&C>\n"
                      "        mindtalk accept\n"
                      "        mindtalk deny\n"
                      "        mindtalk end\n", ch );
    }
    else if ( !str_cmp( "end", argument ) )
    {
        mtalk = get_mindtalk( ch, true );

        if ( !mtalk )
        {
            ch_println( ch, "You are not mindtalking with anyone. Try using the MINDTALK spell!" );
            return;
        }

        ch_println( ch, "You focus, and close the connection." );

        if ( !str_cmp( mtalk->name, ch->name ) )
            victim = get_char_world_full( ch, mtalk->str1 );
        else
            victim = get_char_world_full( ch, mtalk->name );

        if ( victim )
            ch_println( victim, "You feel your connection to %s is lost.", g_name( ch, victim ) );

        delete_sql_row_by_id(DB_TABLE_MTALK, mtalk->id);
        UNLINK( mtalk, first_mtalk, last_mtalk, next, prev );

    }
    else if ( !str_cmp( "accept", argument ) )
    {
        mtalk = get_mindtalk( ch, true );

        if ( mtalk )
        {
            ch_println( ch, "You are already mindtalking with someone." );
            return;
        }

        for ( mtalk = first_mtalk; mtalk; mtalk = mtalk->next )
            if ( !str_cmp( mtalk->str1, ch->name ) && mtalk->num1 == 0 )
                break;

        CHAR_DATA* mindtalker = NULL;

        if ( mtalk )
            mindtalker = get_char_world_full( ch, mtalk->name );

        if ( !mtalk || !mindtalker )
        {
            ch_println( ch, "Nobody has attempted to establish a connection with you." );
            return;
        }

        ch_println( ch, "&BYou feel a mental connection established with %s.", g_name( mindtalker, ch ) );
        ch_println( mindtalker, "&BYou feel a mental connection established with %s.", g_name( ch, mindtalker ) );
        mtalk->num1 = 1;
        save_dbase_sql( DB_TABLE_MTALK, mtalk );
    }
    else if ( !str_cmp( "deny", argument ) )
    {
        for ( mtalk = first_mtalk; mtalk; mtalk = mtalk->next )
            if ( !str_cmp( mtalk->str1, ch->name ) && mtalk->num1 == 0 )
                break;

        if ( !mtalk )
        {
            ch_println( ch, "Nobody has attempted to establish a connection with you." );
            return;
        }

        ch_println( ch, "&BYou ignore the attempt to make mental contact." );
        UNLINK( mtalk, first_mtalk, last_mtalk, next, prev );
        // Don't need to save here since it wouldn't have been persisted anyway
    }
    else
    {
        mtalk = get_mindtalk( ch, true );

        if ( !mtalk )
        {
            ch_println( ch, "You are not mindtalking with anyone. Try using the MINDTALK spell!" );
            return;
        }

        if ( !str_cmp( mtalk->name, ch->name ) )
            victim = get_char_world_full( ch, mtalk->str1 );
        else
            victim = get_char_world_full( ch, mtalk->name );

        if ( !victim
                || xIS_SET( ch->in_room->flags, ROOM_NO_MAGIC )
                || xIS_SET( victim->in_room->flags, ROOM_NO_MAGIC )
                || has_pcflag( ch, PCFLAG_NO_SENSE )
                || has_pcflag( victim, PCFLAG_NO_SENSE )
           )
        {
            ch_println( ch, "&BYou feel the connection is lost." );
            delete_sql_row_by_id(DB_TABLE_MTALK, mtalk->id);
            UNLINK( mtalk, first_mtalk, last_mtalk, next, prev );
            return;
        }

        ch_println( ch, "&BYou %sspeak through your mind '%s%s&W&B'", tone_convert( ch, NULL ), txtclr( ch ), argument );
        ch_println( victim, "&B%s %sspeaks in your mind '%s%s&W&B'", g_name( ch, victim ), tone_convert( ch, victim ), txtclr( ch ), argument );
    }
}

void load_thoughts( char* charname, DB_DATA** first, DB_DATA** last )
{
    debug ("loading thoughts for %s from PGsql",charname);
    load_dbdata_table_for_owner( "thoughtdb", charname, first, last );
    return;
}

void extract_loaded_thoughts( DB_DATA* first_thought, DB_DATA* last_thought )
{
    if ( !first_thought || !last_thought )
        return;

    DB_DATA* db = NULL, *next_db = NULL;
    for ( db = first_thought; db; db = next_db )
    {
        next_db = db->next;
        UNLINK( db, first_thought, last_thought, next, prev );
        extract_db( db );
    }

    return;
}

/* Refactored 05/19/2023 to allow deletions by imms and pseudo-deletions by players - Nield */
void do_think( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL], arg3[MIL];
    char name[MSL];
    CHAR_DATA* victim = NULL;

    if ( IS_NPC( ch ) )
        return;

    set_char_color( AT_PLAIN, ch );

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: '&Cthink <&wthoughts&C>&w' OR '&Cthink list&w'" );
        ch_println( ch, "&w        '&Cthink search <&wnumber, date, or keyword&C>&w'" );
        ch_println( ch, "&w        '&Cthink open&w' OR '&Cthink close&w'" );

        if ( get_trust( ch ) >= 101 )
        {
            ch_println( ch, "&w        '&Cthink <&wplayer&C> list&w'" );
            ch_println( ch, "&w        '&Cthink <&wplayer&C> search <&wnumber, date, or keyword&C>&w'" );
        }

        return;
    }

    char* orig_argument = argument;
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( !str_cmp( arg2, "list" ) && NULLSTR( argument ) && get_trust( ch ) >= 101 )
    {
        victim = get_char_world_full( ch, arg );

        if ( get_trust( ch ) < 103 && !strstr( ch->pcdata->bestowments, "thinkbypass" ) )
        {
            if ( !victim )
            {
                send_to_pager( "&zThey're not logged on!\n", ch );
                return;
            }

            if ( victim->thinkrpc == 0 && get_trust( ch ) < 103 )
            {
                send_to_pager( "&zThey aren't allowing RPC to view their thoughts!\n", ch );
                return;
            }
        }

        if ( victim != NULL && get_trust( ch ) < 103 )
        {
            char temp[MSL];
            snprintf( temp, MSL,  "\n&z(&YR&z|&YP&z|&YC&z) &z%s is viewing your thoughts. Remember to turn them off using '&Wthink close&z' when they are no longer needed.\n", ch->name );
            send_to_pager( temp, victim );
        }

        snprintf( name, MSL, "\n&W%s's Thoughts:\n", arg );
        send_to_pager( name, ch );
        send_to_pager( "&z[&c#&z] &w{&cDATE&w} &wThought\n", ch );
        DB_DATA* db;
        time_t tm;

        DB_DATA* first_thought = NULL;
        DB_DATA* last_thought = NULL;

        if ( victim )
        {
            first_thought = victim->first_thought;
            last_thought = victim->last_thought;
        }
        else
            load_thoughts( arg, &first_thought, &last_thought );

        for ( db = first_thought; db; db = db->next )
        {
            tm = ( time_t )db->num1;

            pager_printf( ch, "&z[&c%d&z] &w{&c%28s&w} &w%s\n",
                          db->id, stripclr( ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ),
                          db->str1 );
        }

        if ( !victim )
            extract_loaded_thoughts( first_thought, last_thought );

        return;
    }
    else if ( !strcmp( arg2, "search" ) && get_trust( ch ) >= 101 )
    {
        DB_DATA* db;
        victim = get_player_world( arg );

        if ( get_trust( ch ) < 103 && !strstr( ch->pcdata->bestowments, "thinkbypass" ) )
        {
            if ( !victim )
            {
                send_to_pager( "&zThey're not logged on!\n", ch );
                return;
            }

            if ( victim->thinkrpc == 0 )
            {
                send_to_pager( "&zThey aren't allowing RPC to view their thoughts!\n", ch );
                return;
            }
        }

        if ( victim != NULL && get_trust( ch ) < 103 )
        {
            char temp[MSL];
            snprintf( temp, MSL, "\n&z(&YR&z|&YP&z|&YC&z) &z%s is viewing your thoughts. Remember to turn them off using '&Wthink close&z' when they are no longer needed.\n", ch->name );
            send_to_pager( temp, victim );
        }

        // Gotta join them back together for searching
        if ( !NULLSTR( argument ) )
        {
            strlcat( arg3, " ", MIL );
            strlcat( arg3, argument, MIL );
        }

        snprintf( name, MSL, "\n&W%s's Thoughts:\n", arg );
        send_to_pager( name, ch );
        send_to_pager( "&z[&c#&z] &w{&cDATE &w} &wThought\n", ch );
        int cnt = 0;
        time_t tm;

        DB_DATA* first_thought = NULL;
        DB_DATA* last_thought = NULL;
        if ( victim )
        {
            first_thought = victim->first_thought;
            last_thought = victim->last_thought;
        }
        else
            load_thoughts( arg, &first_thought, &last_thought );

        for ( db = first_thought; db; db = db->next )
        {
            tm = ( time_t )db->num1;

            if ( nifty_is_name_prefix( arg3, db->str1 ) || nifty_is_name_prefix( arg3, ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ) ||
                    ( atoi( arg3 ) != 0 && atoi( arg3 ) == db->id ) )
            {
                cnt++;
                pager_printf( ch, "&z[&c%d&z] &w{&c%28s&w} &w%s\n",
                              db->id, stripclr( ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ),
                              db->str1 );
            }
        }

        if ( !victim )
            extract_loaded_thoughts( first_thought, last_thought );

        if ( cnt == 0 )
            ch_println( ch, "Sorry, could not find any thoughts that match that criteria." );
        else
            pager_printf( ch, "Found a total of %d match%s.\n", cnt, cnt == 1 ? "" : "es" );

        return;
    }
    else if ( !str_cmp( arg, "open" ) && NULLSTR( arg2 ) )
    {
        send_to_pager( "&z(&YR&z|&YP&z|&YC&z) &zMembers can now view your thoughts!\n", ch );
        ch->thinkrpc = 1;
        do_save( ch, "-noalert" );
        return;
    }
    else if ( !str_cmp( arg, "close" ) && NULLSTR( arg2 ) )
    {
        send_to_pager( "&z(&YR&z|&YP&z|&YC&z) &zMembers can no longer view your thoughts!\n", ch );
        ch->thinkrpc = 0;
        do_save( ch, "-noalert" );
        return;
    }
    else if ( !str_cmp( arg, "search" ) )
    {
        DB_DATA* db;
        int cnt = 0;
        time_t tm;
        send_to_pager( "\n&WYour Thoughts:\n", ch );
        send_to_pager( "&z[&c#&z] &w{&cDATE &w} &wThought&w\n", ch );
        argument = one_argument( orig_argument, arg );

        for ( db = ch->first_thought; db; db = db->next )
        {
            tm = ( time_t )db->num1;

            if ( nifty_is_name_prefix( argument, db->str1 ) || nifty_is_name_prefix( argument, db->name ) || nifty_is_name_prefix( argument, db->str2 ) ||
                    nifty_is_name_prefix( argument, ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ) || ( atoi( argument ) != 0 && atoi( argument ) == db->id ) )
            {
                cnt++;
                pager_printf( ch, "&z[&c%d&z] &w{&c%28s&w} &w%s\n", db->id, stripclr( ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ), db->str1 );
            }
        }

        if ( cnt == 0 )
            ch_println( ch, "Sorry, could not find any thoughts that match that criteria." );
        else
            pager_printf( ch, "Found a total of %d match%s.\n", cnt, cnt == 1 ? "" : "es" );

        return;
    }
    else if ( !str_cmp( arg, "list" ) && NULLSTR( arg2 ) )
    {
        send_to_pager( "\n&WYour Thoughts:\n", ch );
        send_to_pager( "&z[&c#&z] &w{&cDATE &w} &wThought&w\n", ch );
        DB_DATA* db;
        time_t tm;

        for ( db = ch->first_thought; db; db = db->next )
        {
            tm = ( time_t )db->num1;
            pager_printf( ch, "&z[&c%d&z] &w{&c%28s&w} &w%s\n", db->id, stripclr( ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ), db->str1 );
        }

        return;
    }
    else
    {
        ch->thoughts++;
        DB_DATA* db = NULL;
        CREATE( db, DB_DATA, 1 );
        SET_STRING( db->name, "" );
        SET_STRING( db->str1, orig_argument );
        SET_STRING( db->str2, "" );
        db->num1 = time( 0 );
        db->num2 = 0;
        db->num3 = ch->thoughts;
        db->id = 0;
        LINK( db, ch->first_thought, ch->last_thought, next, prev );
        save_dbase_sql_owner( "thoughtdb", db, ch->name );
        send_to_pager( "You think, therefore you are.\n", ch );
        do_save( ch, "-noalert" );
        return;
    }
}

