void get_chatgptreply( char* chname, int mobvnum, char* reply )
{
    CHAR_DATA* ch;
    CHAR_DATA* mob;
    char buf[MSL];
    ch = get_player_world( chname );

    if ( !ch )
    {
        bug( "Can't find player %s", chname );
        return;
    }

    snprintf( buf, MSL, "%d", mobvnum );
    mob = get_char_room_exact( ch, buf );

    if ( !mob )
    {
        bug( "Can't find mob %d", mobvnum );
        return;
    }

    if ( !xIS_SET( mob->act, ACT_CHATGPT ) )
