void alert_rpc( char* source, char* argument )
{
    char buf[SUPER_MSL];

    if ( NULLSTR( source ) || NULLSTR( argument ) )
        return;

    snprintf( buf, SUPER_MSL, "&z(&YR&z|&YP&z|&YC&z) &z[&w%s&z]: &O%s\n", source, argument );

