// Don't free the value of this field after passing it into storage. (For things like cJSON instances if we want to reuse it after)
#define FLAG_DONT_AUTOFREE BV00
// Write the value to storage from this field, but do not read it back into anything.
#define FLAG_WRITE_ONLY BV01
// Read the value from storage for this field, but do not write it back.
#define FLAG_READ_ONLY BV02
// Store an empty string instead of null, for non-nullable string columns
#define FLAG_NULL_AS_EMPTY_STRING BV03
// Skip writing this field if the value is null
#define FLAG_DONT_WRITE_NULL  BV04
// This DB column is unique and must be treated as so in our upsert queries
#define FLAG_UNIQUE_COLUMN BV05
// This field is stored as an inline struct, not a pointer. (Like how we store Vector3 on PLANET_DATA)
// Supported only for FIELD_TYPE_NESTED_OBJ
#define FLAG_NOT_POINTER BV06
// This field is dynamically allocated
#define FLAG_DYNAMIC_ALLOC BV07
// If this is null, abort any write op
#define FLAG_ABORT_ON_NULL BV08
// Don't save/load from Postgres or JSON, but free when appropriate
#define FLAG_FREE_ONLY BV09
// Write the value to storage from this field, but do not read it back into anything or attempt to free it.
#define FLAG_WRITE_NO_FREE BV10

#define BASIC_UNLOAD null_unloader

