struct field_map {
    const char *name;
    int type;
    int sub_type;
    size_t offset;
    size_t offset_2;
    size_t size_offset;
    int arr_max_size;
    const char *db_column;
    int flags;
    const FLAG_INFO *flag_info;

    // When this field is another object we want to look up at runtime, we store functions to retrieve
    // the value based on either string or int reference.
    STRING_REF_LOOKUP *string_ref_lookup;
    INT_REF_LOOKUP *int_ref_lookup;

    // When this field is itself another object with its own field map, we store its size and field
    // map pointer.
    size_t value_size;
    const FIELD_MAP* value_fields;

    // Pointer to a specially designated unloader function for that fieldmap type, or to null_unloader otherwise
    UNLOADER_FUN* unloader;
};

