// A generic field, typically used for primitives.
// struct_type: The type containing this field
// field: The name of the field on that struct
// type_enum: The FIELD_TYPE enum value above to determine which (de)serialization logic we'll use
// column_name: The DB column or JSON field name to store the value in
// fm_flags: Any special behavior for handling this field, see flags near top of file
#define FIELD_INFO(struct_type, field, type_enum, column_name, fm_flags) { \
    .name = #field, \
    .type = type_enum, \
    .offset = offsetof(struct_type, field), \
    .db_column = column_name, \
    .flags = fm_flags \
}


// Binary field with length stored in another field (variable-sized)
#define FIELD_INFO_BINARY(struct_type, field, len_field, type_enum, column_name, fm_flags) \
{ \
    .name        = #field, \
    .type        = (type_enum), \
    .offset      = offsetof(struct_type, field), \
    .size_offset = offsetof(struct_type, len_field), \
    .db_column   = (column_name), \
    .flags       = (fm_flags) \
}

#define FIELD_INFO_ARRAY(struct_type, field, arr_size_field, type_enum, column_name, fm_flags) { \
    .name = #field, \
    .type = FIELD_TYPE_ARRAY, \
    .sub_type = type_enum, \
    .offset = offsetof(struct_type, field), \
    .db_column = column_name, \
    .flags = fm_flags | FLAG_DYNAMIC_ALLOC, \
    .size_offset = offsetof(struct_type, arr_size_field) \
}

#define FIELD_INFO_FIXED_ARRAY(struct_type, field, array_max_size, type_enum, column_name, fm_flags) { \
    .name = #field, \
    .type = FIELD_TYPE_ARRAY, \
    .sub_type = type_enum, \
    .offset = offsetof(struct_type, field), \
    .db_column = column_name, \
    .flags = fm_flags, \
    .arr_max_size = array_max_size \
}

// A list of flags set on an EXT_BV struct field, stored as an array of the flag names which are set
// struct_type: The type containing this field
// field: The name of the EXT_BV field on that struct
// column_name: The DB column or JSON field name to store the value in
// fm_flags: Any special behavior for handling this field, see flags near top of file
// flag_list: A pointer to the FLAG_INFO array storing info about these flags
#define FIELD_INFO_FLAGLIST(struct_type, field, column_name, fm_flags, flag_list) { \
    .name = #field, \
    .type = FIELD_TYPE_FLAGLIST, \
    .offset = offsetof(struct_type, field), \
    .db_column = column_name, \
    .flags = fm_flags, \
    .flag_info = flag_list \
}

// A collection (as linked list) of some nested struct
// struct_type: The type containing this field
// first_field: The name of the field on the struct storing the first element of the list
// last_field: The name of the field on the struct storing the last element of the list
// type_enum: The FIELD_TYPE enum value above to determine which (de)serialization logic we'll use
// column_name: The DB column or JSON field name to store the value in
// fm_flags: Any special behavior for handling this field, see flags near top of file
#define FIELD_INFO_LINKEDLIST(struct_type, first_field, last_field, type_enum, column_name, fm_flags) { \
    .name = #first_field, \
    .type = type_enum, \
    .offset = offsetof(struct_type, first_field), \
    .offset_2 = offsetof(struct_type, last_field), \
    .db_column = column_name, \
    .flags = fm_flags \
}

// A reference to another object based on a string value (for example, the starsystem field of PLANET_DATA)
// struct_type: The type containing this field
// ref_field_on_struct: The name of the field on the struct storing the reference
// ref_type: The type of the value referred to (SPACE_DATA in our example)
// str_field_on_ref: The name of the field on the referred type which we use to get the value to store as the reference (name in our example, for the starsystem->name)
// lookup_func: A function with a single char* argument to get the value, or null if not found. (starsystem_from_name, in our example)
// column_name: The DB column or JSON field name to store the value in
// fm_flags: Any special behavior for handling this field, see flags near top of file
#define FIELD_INFO_STRING_REF(struct_type, ref_field_on_struct, ref_type, str_field_on_ref, lookup_func, column_name, fm_flags) { \
    .name = #ref_field_on_struct, \
    .type = FIELD_TYPE_STRING_REF, \
    .offset = offsetof(struct_type, ref_field_on_struct), \
    .offset_2 = offsetof(ref_type, str_field_on_ref), \
    .db_column = column_name, \
    .string_ref_lookup = (STRING_REF_LOOKUP*)lookup_func, \
    .flags = fm_flags \
}

// A reference to another object based on an integer value (for example, the in_room field of CHAR_DATA)
// struct_type: The type containing this field
// ref_field_on_struct: The name of the field on the struct storing the reference
// ref_type: The type of the value referred to (ROOM_INDEX_DATA in our example)
// int_field_on_ref: The name of the field on the referred type which we use to get the value to store as the reference (vnum in our example, for the room->vnum)
// lookup_func: A function with a single int argument to get the value, or null if not found. (get_room_index, in our example)
// column_name: The DB column or JSON field name to store the value in
// fm_flags: Any special behavior for handling this field, see flags near top of file
#define FIELD_INFO_INT_REF(struct_type, ref_field_on_struct, ref_type, int_field_on_ref, lookup_func, column_name, fm_flags) { \
    .name = #ref_field_on_struct, \
    .type = FIELD_TYPE_INT_REF, \
    .offset = offsetof(struct_type, ref_field_on_struct), \
    .offset_2 = offsetof(ref_type, int_field_on_ref), \
    .db_column = column_name, \
    .int_ref_lookup = (INT_REF_LOOKUP*)lookup_func, \
    .flags = fm_flags \
}

#define FIELD_INFO_NESTED_OBJ(struct_type, field, field_type, field_map, column_name, fm_flags, unload_fun) { \
    .name = #field, \
    .type = FIELD_TYPE_NESTED_OBJ, \
    .offset = offsetof(struct_type, field), \
    .db_column = column_name, \
    .value_size = sizeof(field_type), \
    .value_fields = field_map, \
    .flags = fm_flags, \
    .unloader = (UNLOADER_FUN*)unload_fun \
}

/*  Frees the struct and its contents. Throws a bug message and returns an integer error
    code if the operation fails. Useful in custom free_ and extract_ functions that
    return integer values aligned with the standard lotj_errno codes. */
#define FREE_STRUCT(elem, field_type) { \
    if ( ( fieldmap_struct_to_free( elem, field_type, TRUE ) ) != E_LOTJ_SUCCESS ) \
    { \
        bug( "%s: failed to free struct.", FUNC ); \
        return E_LOTJ_FREE_FAILED; \
    } \
    elem = NULL; \
} \

/* 
    Frees the struct and its contents, but doesn't automatically return an error value
    if the operation fails. It'll still throw the bug message though. Useful for
    embedding in functions that don't themselves return int values or that otherwise
    need to continue running after.
*/
#define FREE_STRUCT_NORET(elem, field_type) { \
    if ( ( fieldmap_struct_to_free( elem, field_type, TRUE ) ) != E_LOTJ_SUCCESS ) \
        bug( "%s: failed to free struct.", FUNC ); \
    elem = NULL; \
} \

/*  Frees the contents of a struct but not the struct itself. Useful for structs that
    aren't dynamically allocated (i.e., not pointers), like metrics, Vector3s, etc.
*/
#define FREE_STRUCT_CONTENTS(elem, field_type) { \
    if ( ( fieldmap_struct_to_free( elem, field_type, FALSE ) ) != E_LOTJ_SUCCESS ) \
        bug( "%s: failed to free struct.", FUNC ); \
} \

