/*
    Creates the blast-radius for a landed/docked ship after Selfdestruct.
    -Ghost
*/
void ship_explode( SHIP_DATA* ship )
{
    int blast = 0;
    int range = 0;
    ROOM_INDEX_DATA* room;
    room = get_room_index( ship->location );

    if ( room == NULL )
        return;

    if ( xIS_SET( ship->flags, SHIP_DRYDOCK ) )
    {
        bug( "Ship %s trying to explode while drydocked!\n", ship->name );
        return;
    }

    blast = 5000;
    range = get_ship_size( ship ) * 2;
    blast = get_ship_size( ship ) * 250;
    /*
        bug("Blast damage: %d", blast);
        bug("Range: %d", range);
    */
    /* Begin the detonation sequence */
    ship_explode_2( room, blast, range );
    ship_explode_1( room, blast, range );
    ship_explode_2( room, blast, range );

    OBJ_INDEX_DATA* blank = get_obj_index( OBJ_VNUM_BLANK );
    if ( !blank )
        return;

    OBJ_DATA* wreck = create_object( blank, 1 );
    xCLEAR_BITS( wreck->wear_flags );
    xSET_BIT( wreck->extra_flags, ITEM_PERSISTENT );
    xSET_BIT( wreck->extra_flags, ITEM_INDESTRUCTIBLE );
    xSET_BIT( wreck->extra_flags, ITEM_NOGET );
    wreck->weight = 10000;
    if ( !NULLSTR( ship->template->base_name ) )
    {
        SET_STRING( wreck->name, strfmt("a wrecked %s", stripclr(ship->template->base_name) ) );
        SET_STRING( wreck->short_descr, strfmt("a wrecked %s", ship->template->base_name ) );
        SET_STRING( wreck->description, strfmt("&zA wrecked %s is smoldering here.", ship->template->base_name ) );
    }
    else
    {
        SET_STRING( wreck->name, strfmt("a wrecked %s", flag_value_name( ship_classes, ship->classtype ) ) );
        SET_STRING( wreck->short_descr, strfmt("a wrecked %s", flag_value_name( ship_classes, ship->classtype ) ) );
        SET_STRING( wreck->description, strfmt("&zA wrecked %s is smoldering here.", flag_value_name( ship_classes, ship->classtype ) ) );
    }
    wreck->timer = (24*60*60*PULSE_PER_SECOND)/PULSE_TICK;
    wreck->item_type = ITEM_TRASH;
    obj_to_room( wreck, room );
    save_persistent_object(wreck, true);

    return;
}

void ship_explode_1( ROOM_INDEX_DATA* room, int blast, int range )
{
    CHAR_DATA* rch;
    CHAR_DATA* rnext;
    OBJ_DATA*  robj;
    OBJ_DATA*  robj_next;
    int dam;

    /*
        Is this room 'clean' of the explosion?
    */
    if ( xIS_SET( room->flags, BFS_MARK ) )
        return;

    /* Mark the room as being hit by the explosion */
    xSET_BIT( room->flags, BFS_MARK );

    /* Anybody in the room with the explosion? */
    for ( rch = room->first_person ; rch ;  rch = rnext )
    {
        rnext = rch->next_in_room;

        if ( is_safe( rch, rch ) )
            continue;

        if ( !IS_NPC( rch ) )
        {
            ch_println( rch, "&YThe shockwave from a massive explosion rips through your body!" );
        }

        dam = number_range( ( int )( blast * 0.9 ), ( int )( blast * 1.1 ) );

        if ( dam > 0 )
            damage( rch, rch, dam, TYPE_UNDEFINED );
    }

    /* Any objects to destroy? */
    for ( robj = room->first_content; robj; robj = robj_next )
    {
        robj_next = robj->next_content;
        set_cur_obj( robj );
        damage_obj( robj );
    }

    /* Spread the explosion to nearby rooms */
    {
        EXIT_DATA* pexit;

        for ( pexit = room->first_exit; pexit; pexit = pexit->next )
        {
            if ( pexit->to_room && pexit->to_room != room )
            {
                if ( range > 0 && blast > 1 )
                {
                    int roomblast;
                    roomblast = ( int )( blast * 0.20 ); /* 1|5 of the remaining blast */
                    ship_explode_1( pexit->to_room, roomblast, range - 1 );
                }
                else
                    echo_to_room( AT_YELLOW, pexit->to_room, "You hear a massive explosion not too far from here!\n" );
            }
        }
    }
}

void chomp_ending_nlcrs(char *str) {
    size_t len = strlen(str);
    while (len > 0 && (str[len - 1] == '\n' || str[len - 1] == '\r')) {
        str[--len] = '\0';
    }
}

void ship_explode_2( ROOM_INDEX_DATA* room, int blast, int range )
{
    if ( !xIS_SET( room->flags, BFS_MARK ) )
        return;

    xREMOVE_BIT( room->flags, BFS_MARK );

    if ( blast > 0 && range > 0 )
    {
        int roomblast;
        EXIT_DATA* pexit;

        for ( pexit = room->first_exit; pexit; pexit = pexit->next )
        {
            if ( pexit->to_room && pexit->to_room != room )
            {
                roomblast = ( int )( blast * 0.20 ); /* 1|5 of remaining blast */
                ship_explode_2( pexit->to_room, roomblast, range - 1 );
            }
        }
    }
}

/*
    Creates the blast-radius for a vehicle upon explosion.
    -Ghost
*/
void vehicle_explode( VEHICLE_DATA* vec )
{
    int blast = 0;
    int range = 0;
    ROOM_INDEX_DATA* room;
    room = get_room_index( vec->location );

    if ( room == NULL )
        return;

    blast = vec->size * 200;
    range = URANGE( 1, vec->size - 1, 2 );
    vec_explode_2( room, blast, range );
    vec_explode_1( room, blast, range );
    vec_explode_2( room, blast, range );
    return;
}

