/*
    Detonates a object. Modified to support package bombs too.
    --- Coded by Ghost
*/
void  explode_obj( OBJ_DATA* obj )
{
    char buf[MSL];
    OBJ_DATA* scraps = NULL;
    /*
        Armed by a character?
    */
    // Still possible to prevent the bomb from exploding
    // in lua by disarming it in a event trigger callback
    // here.  ~Miros
    lua_trigger_on_obj( obj, LUA_TRIGGER_OBJ_BEFORE_EXPLODE );

    if ( !NULLSTR( obj->armed_by ) )
    {
        ROOM_INDEX_DATA* room = NULL;
        CHAR_DATA* xch = NULL;
        OBJ_DATA* cont = NULL;
        bool held = FALSE;

        for ( xch = first_char; xch; xch = xch->next )
        {
            /* Did this character arm it? */
            if ( ( !IS_NPC( xch ) || IS_PUFF( xch ) ) && nifty_is_name( obj->armed_by, xch->name ) )
            {
                /* Is this character holding it? */
                if ( obj->carried_by )
                {
                    act( AT_WHITE, "$p EXPLODES in $n's hands!", obj->carried_by, obj, NULL, TO_ROOM );
                    act( AT_WHITE, "$p EXPLODES in your hands!", obj->carried_by, obj, NULL, TO_CHAR );
                    room = obj->carried_by->in_room;
                    held = TRUE;
                }
                else if ( obj->in_room )
                    room = obj->in_room;
                else if ( obj->in_obj )
                {
                    for ( cont = obj->in_obj; cont; cont = cont->in_obj )
                    {
                        if ( !cont || cont == NULL )
                            break;

                        if ( cont->in_room )
                        {
                            room = cont->in_room;
                            break;
                        }
                        else if ( cont->carried_by )
                        {
                            room = cont->carried_by->in_room;
                            break;
                        }
                    }
                }
                else
                    room = NULL;

                /* Do we have a room to explode in? */
                if ( room )
                {
                    /*  Make sure nobody is holding it, and that someone is in the room */
                    if ( !held && room->first_person )
                    {
                        act( AT_WHITE, "$p EXPLODES!", room->first_person, obj, NULL, TO_ROOM );
                    }

                    strlcpy( buf, xch->name, MSL );
                    room_explode( obj, xch, room );
                }
            }
        }

        lua_trigger_on_obj( obj, LUA_TRIGGER_OBJ_AFTER_EXPLODE );
        /* Destroy the explosive */
        scraps = make_scraps( obj );
        /* Record the user */
        SET_STRING( scraps->killed_by, buf );
    }
}

void room_explode( OBJ_DATA* obj, CHAR_DATA* xch, ROOM_INDEX_DATA* room )
{
    int blast = 0, range = 0, type = 0;
    /* Calculate the blast value */
    blast = number_range( obj->value[0], obj->value[1] );

    if ( obj->item_type == ITEM_GRENADE ) //Specialized grenades will end up having a V2 of 0, and why default to 2 rooms if the grenade is that crappy? - 10Nov20 Gathorn
        range = obj->value[2];
    else
        range = UMAX( 2, obj->value[2] );

    type = obj->value[3];

    //if ( obj->item_type == ITEM_LANDMINE ) blast *= 2; // why not like grenades? ~Miros
    if ( obj->item_type == ITEM_GRENADE )
        blast *= 2;

    if ( obj->item_type == ITEM_BOMB )
        blast *= 4;

    /* bug("Blast damage: %d", blast); */
    /* bug("Range: %d", range); */
    /* Begin the detonation sequence */
    int vnum = room->vnum;
    room_explode_1( obj, xch, room, blast, range, type );
    room_explode_2( vnum, blast, range );
    return;
}

void room_explode_1( OBJ_DATA* obj, CHAR_DATA* xch, ROOM_INDEX_DATA* room, int blast, int range, int type )
{
    STRUCTURE_DATA* structure = NULL;
    AFFECT_DATA raf, af;
    SHIP_DATA* rship = NULL;
    CHAR_DATA* rch = NULL;
    CHAR_DATA* rnext = NULL;
    OBJ_DATA*  robj = NULL;
    OBJ_DATA*  robj_next = NULL;
    int dam = 0, dam2 = 0, duration = 0;

    /*
        Is this room 'clean' of the explosion?
    */
    if ( xIS_SET( room->flags, BFS_MARK ) )
        return;

    /* Mark the room as being hit by the explosion */
    xSET_BIT( room->flags, BFS_MARK );

    // We now apply room-level effects, which we do regardless of whether
    // anyone is in the room to witness them
    if ( type == GRENADE_SMOKE )
    {
        // Don't let a weaker grenade negate a previously detonated stronger one
        if ( xIS_SET( room->affected_by, AFF_SMOKE ) )
            for ( AFFECT_DATA* aff = room->first_affect; aff; aff = aff->next )
                if ( xIS_SET( aff->bitvector, AFF_SMOKE ) )
                    duration = UMAX( duration, aff->duration );

        raf.type      = -1;
        raf.location  = APPLY_AFFECT;
        raf.duration  = UMAX( duration, blast );
        xCLEAR_BITS( raf.bitvector );
        xSET_BIT( raf.bitvector, AFF_SMOKE );
        affect_replace( room, ROOM_AFFECT, &raf );
    }
    else if ( type == GRENADE_NAPALM && obj != NULL )
    {
        if ( xIS_SET( room->affected_by, AFF_NAPALM ) )
        {
            // Don't let a weaker grenade negate a previously detonated stronger one
            for ( AFFECT_DATA* aff = room->first_affect; aff; aff = aff->next )
            {
                if ( xIS_SET( aff->bitvector, AFF_NAPALM ) )
                {
                    duration = UMAX( duration, aff->duration );
                    dam2 = UMAX( dam2, aff->modifier );
                }
            }
        }        

        // New feature: map the object values to the affects, accounting for smaller sh_int limits
        for ( size_t i = 0; i < MAX_VALS; i++ )
            raf.value[i] = URANGE( SHRT_MIN, obj->value[i], SHRT_MAX );

        raf.type = -1;
        raf.location  = APPLY_DAMAGE;
        raf.duration = UMAX( duration, raf.value[0] ); // Top up the duration
        raf.modifier = UMAX( dam2, raf.value[1] ); // Top up the damage value

        xCLEAR_BITS( raf.bitvector );
        xSET_BIT( raf.bitvector, AFF_NAPALM );
        affect_replace( room, ROOM_AFFECT, &raf );
    }

    /* Anybody in the room with the explosion? */
    for ( rch = room->first_person ; rch ;  rch = rnext )
    {
        rnext = rch->next_in_room;

        if ( is_safe( rch, rch ) )
            continue;

        if ( !IS_NPC( rch ) && IS_IMMORTAL( rch ) && has_pcflag( rch, PCFLAG_WIZINVIS ) )
            continue;

        if ( !IS_NPC( rch ) && has_pcflag( rch, PCFLAG_AFK ) )
            continue;

        // When hit by other people's grenades, apply diminishing returns:
        // Ignore the grenade if you were hit by one within the last 5 seconds.
        if ( !IS_NPC( rch ) && str_cmp( obj->armed_by, rch->name ) && obj->item_type == ITEM_GRENADE )
        {
            if ( get_timerptr( rch, TIMER_GRENADED ) )
                continue;
            else
                add_timer( rch, TIMER_GRENADED, 5, NULL, NULL, FUNC );
        }

        if ( !IS_NPC( rch ) )
        {
            switch ( type )
            {
                default:
                case GRENADE_BOMB:
                case GRENADE_NORMAL:
                    ch_println( rch, "&YThe shockwave from a massive explosion rips through your body!" );
                    break;

                /* Taken out due to #1 player abuse and #2 needed to force people to RP or fight normally */
                /*case GRENADE_CONCUSSION:*/
                case GRENADE_SMOKE:
                    ch_println( rch, "&238A thick &239c&241l&243o&241u&239d&238 of black gas &239b&241i&243l&245l&243o&241w&239s&238 through the room!" );
                    break;

                case GRENADE_NERVE:
                    ch_println( rch, "&112You falter as a strange greenish gas seeps into the room!" );
                    break;

                case GRENADE_NAPALM:
                    ch_println( rch, "&208A blazing wall of fire slams into you, bursting into a fierce cloud of flames!" );
                    break;

                case GRENADE_ION:
                    if ( is_droid( rch->race ) )
                    {
                        ch_println( rch, "&CA burst of ionized particles flows through you, frying your circuitry!" );
                        act( AT_LBLUE, "$n's circuitry hisses and arcs with ion energy as the burst wreaks havoc on $s systems.",
                             rch, NULL, NULL, TO_ROOM );
                    }
                    else
                    {
                        ch_println( rch, "&CA burst of ionized particles flows through you, singeing you slightly!" );
                    }

                    break;
            }
        }

        if ( type == GRENADE_SMOKE )
        {
            act( AT_SKILL, "Your vision clouds as the room fills with smoke!", rch, NULL, NULL, TO_CHAR );
        }
        else if ( type == GRENADE_NERVE )
        {
            if ( !is_droid( rch->race ) )
            {
                SKILL_DATA* afskill = cache_skill( "poison", &skill_poison );
                af.type      = afskill ? afskill->id : -1;
                af.location  = APPLY_STR;
                af.modifier  = -2;
                af.duration  = ( blast * 5 );
                xCLEAR_BITS( af.bitvector );
                xSET_BIT( af.bitvector, AFF_POISON );
                affect_replace( rch, CHAR_AFFECT, &af );
                act( AT_SKILL, "You feel dizzy and groggy as the nerve agent sets in...", rch, NULL, NULL, TO_CHAR );
                // Special case: The first time someone is poisoned, they get a sudden bump in mental state.
                rch->mental_state = URANGE( 25, rch->mental_state, 100 );
            }
        }
        else if ( type == GRENADE_NAPALM && obj != NULL )
        {
            dam2 = 0;
            duration = 0;
            if ( xIS_SET( rch->affected_by, AFF_NAPALM ) )
            {
                // Don't let a weaker grenade negate a previously detonated stronger one
                for ( AFFECT_DATA* aff = rch->first_affect; aff; aff = aff->next )
                {
                    if ( xIS_SET( aff->bitvector, AFF_NAPALM ) )
                    {
                        duration = UMAX( duration, aff->duration );
                        dam2 = UMAX( dam2, aff->modifier );
                    }
                }
            }

            // New feature: map the object values to the affects, accounting for smaller sh_int limits
            for ( size_t i = 0; i < MAX_VALS; i++ )
                af.value[i] = URANGE( SHRT_MIN, obj->value[i], SHRT_MAX );

            af.type      = -1;
            af.location  = APPLY_DAMAGE;
            af.modifier  = UMAX( dam2, af.value[1] );
            af.duration  = UMAX( duration, obj->value[5] );
            xCLEAR_BITS( af.bitvector );
            xSET_BIT( af.bitvector, AFF_NAPALM );
            affect_replace( rch, CHAR_AFFECT, &af );
            act( AT_RED, "You scream as your body is engulfed in flames!", rch, NULL, NULL, TO_CHAR );
        }
        else if ( type == GRENADE_ION )
        {
            if ( is_droid( rch->race ) )
            {
                SKILL_DATA* afskill = cache_skill( "grenades", &skill_grenades );
                af.type      = afskill ? afskill->id : -1;
                af.location  = APPLY_DEX;
                af.modifier  = -5;
                af.duration  = 3;
                xCLEAR_BITS( af.bitvector );
                xSET_BIT( af.bitvector, AFF_LETHARGY );
                affect_replace( rch, CHAR_AFFECT, &af );
                dam = blast;
            }
            else
                dam = blast * 0.25; // Quarter damage to non-droid targets
        }
        else if ( type == GRENADE_BOMB || type == GRENADE_NORMAL )
        {
            dam = blast;
        }
        else
            dam = 0;

        if ( dam > 0 )
        {
            char log_buf[MSL];

            if ( !IS_NPC( rch ) )
            {
                if ( obj->item_type == ITEM_LANDMINE )
                {
                    snprintf( log_buf, MSL, "%s stepped on a landmine at %d.", rch->name, rch->in_room->vnum );
                    log_string_plus( log_buf, LOG_NORMAL, get_trust( rch ) );
                }
                else
                {
                    snprintf( log_buf, MSL, "%s hit by %s's grenade at %d.", rch->name, ( IS_NPC( xch ) ? xch->short_descr : xch->name ), rch->in_room->vnum );
                    log_string_plus( log_buf, LOG_NORMAL, get_trust( rch ) );
                }
            }

            damage( xch, rch, dam, TYPE_UNDEFINED );

            // High chance of wounds from a landmine exploding in your room.
            if ( obj->item_type == ITEM_LANDMINE && !char_extracted( rch ) && rch->in_room == obj->in_room )
            {
                if ( number_range( 1, 6 ) == 1 && !xIS_SET( rch->w_wound, MED_L_LEG ) )
                {
                    ch_println( rch, "&RYour left leg is severely wounded by the blast!" );
                    xSET_BIT( rch->w_wound, MED_L_LEG );
                }
                if ( number_range( 1, 6 ) == 1 && !xIS_SET( rch->w_wound, MED_R_LEG ) )
                {
                    ch_println( rch, "&RYour right leg is severely wounded by the blast!" );
                    xSET_BIT( rch->w_wound, MED_R_LEG );
                }
                if ( number_range( 1, 6 ) == 1 && !xIS_SET( rch->w_wound, MED_L_FOOT ) )
                {
                    ch_println( rch, "&RYour left foot is severely wounded by the blast!" );
                    xSET_BIT( rch->w_wound, MED_L_FOOT );
                }
                if ( number_range( 1, 6 ) == 1 && !xIS_SET( rch->w_wound, MED_R_FOOT ) )
                {
                    ch_println( rch, "&RYour right foot is severely wounded by the blast!" );
                    xSET_BIT( rch->w_wound, MED_R_FOOT );
                }
            }
        }
    }

    // Ion grenades can damage ship systems
    if ( type == GRENADE_ION )
    {
        SHIP_DATA* ship = get_ship_from_room( room );

        if ( ship )
        {
            if ( room->vnum == ship->engineroom && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
            {
                if ( ship->shipstate == SHIP_HYPERSPACE )
                    exit_hyperspace( ship );

                ship->shipstate = SHIP_DISABLED;
                echo_to_room( AT_YELLOW, room, "The ship's drive sparks and clanks as the ion blast disables it." );
            }

            if ( room->vnum == ship->cockpit || room->vnum == ship->gunseat || room->vnum == ship->coseat )
            {
                ship->missilestate = MISSILE_DAMAGED;
                ship->spent_tubes = ship->missiletubes;
                ship->tractorstate = TRACTOR_DAMAGED;
                ship->autoblaster_charge = LASER_DAMAGED;
                ship->laser_charge = LASER_DAMAGED;
                ship->turbolaser_charge = LASER_DAMAGED;
                ship->ion_charge = ION_DAMAGED;
                echo_to_room( AT_YELLOW, room, "The targeting console arcs with electricity and goes dark." );
            }

            for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
            {
                if ( turret->room == room )
                {
                    turret->laserstate = LASER_DAMAGED;
                    echo_to_room( AT_YELLOW, room, "The targeting console arcs with electricity and goes dark." );
                }
            }
        }
    }

    /* Inside an structure? Inside a ship? */
    if ( type != GRENADE_NERVE && type != GRENADE_SMOKE && type != GRENADE_ION )
    {
        if ( obj->item_type == ITEM_LANDMINE )
        {
            // Decent landmines might do 1.5-2k raw damage. We want them to destroy anything smaller than a corvette.
            // Corvettes tend to have 1000+ hull, so drop damage to 1/3 here.
            if ( blast_damage_ship( room, xch, blast / 3 ) )
                return;
        }
        else
        {
            // Grenades do pretty minimal damage to ships. Decent grenades might do 1.5k raw damage to a player.
            // We drop that to 5% so it lands at 75 for ships - not enough to worry about in anything bigger
            // than a transport
            if ( blast_damage_ship( room, xch, blast / 20 ) )
                return;
        }

        for ( structure = first_structure; structure; structure = structure->next )
        {
            if ( structure->firstroom > room->vnum || room->vnum > structure->lastroom )
                continue;

            if ( structure->hull <= 0 )
                continue;

            dam =  blast / 10;
            structure->hull = UMAX( 0, ( structure->hull - dam ) );

            if ( structure->hull <= 0 )
            {
                CHAR_DATA* victim;

                for ( victim = first_char; victim; victim = victim->next )
                {
                    if ( victim == NULL )
                        continue;

                    if ( victim->in_room == NULL )
                        continue;

                    if ( victim->in_room->vnum >= structure->firstroom && victim->in_room->vnum <= structure->lastroom )
                    {
                        ch_println( victim, "The structure collapses around you! You're a goner for sure!" );

                        if ( !IS_IMMORTAL( victim ) )
                            raw_kill( victim, victim );
                    }
                }
            }
        }
    }

    robj = NULL;
    /* Any objects to destroy? */

    for ( robj = room->first_content; robj; robj = robj_next )
    {
        robj_next = robj->next_content;

        if ( robj == obj )
            continue;

        if ( robj->item_type == ITEM_BLUEPRINT && xIS_EMPTY( robj->extra_flags ) )
            continue;

        // Armed landmines can't be blown up by grenades.
        // This prevents people from getting rid of landmines by damaging them.
        if ( obj->item_type == ITEM_GRENADE && robj->item_type == ITEM_LANDMINE && xIS_SET( robj->extra_flags, ITEM_BURIED ) )
            continue;

        set_cur_obj( robj );

        if ( type != GRENADE_NERVE && type != GRENADE_SMOKE && type != GRENADE_ION )
            damage_obj( robj );
    }

    SHIP_DATA* tarnext;

    /* Any ships to thrash? */
    for ( rship = room->first_ship; rship; rship = tarnext )
    {
        tarnext = rship->next_in_room;

        if ( type == GRENADE_CONCUSSION )
            continue;

        /* Toast the ship. Ship takes 1 point for every 8-10 real damage */
        if ( type != GRENADE_SMOKE && type != GRENADE_NERVE && type != GRENADE_ION )
        {
            rship->shield -= number_range( ( blast / 8 ), ( blast / 10 ) );

            if ( rship->shield < 0 )
                rship->hull -= number_range( 1, 3 );

            rship->shield = UMAX( 0, rship->shield );
            rship->hull = UMAX( 0, rship->hull );
        }
    }

    /* Spread the explosion to nearby rooms */
    {
        EXIT_DATA* pexit;

        for ( pexit = room->first_exit; pexit; pexit = pexit->next )
        {
            if ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) )
                continue;

            if ( pexit->to_room && pexit->to_room != room )
            {
                if ( range > 0 && blast > 1 )
                {
                    int roomblast;
                    roomblast = ( int )( blast * 0.25 ); /* 1|4 of the remaining blast */
                    room_explode_1( obj, xch, pexit->to_room, roomblast, range - 1, type );
                }
                else
                    echo_to_room( AT_WHITE, pexit->to_room, "You hear a massive explosion not too far from here!" );
            }
        }
    }
}

// Cleans up fanout state for room explosions.
void room_explode_2( int vnum, int blast, int range )
{
    // Look up by vnum in case the vnum got deleted as part of the explosion
    ROOM_INDEX_DATA* room = get_room_index( vnum );
    if ( !room )
        return;

    if ( !xIS_SET( room->flags, BFS_MARK ) )
        return;

    xREMOVE_BIT( room->flags, BFS_MARK );

    if ( blast > 0 && range > 0 )
    {
        int roomblast;
        EXIT_DATA* pexit;

        for ( pexit = room->first_exit; pexit; pexit = pexit->next )
        {
            if ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) )
                continue;

            if ( pexit->to_room && pexit->to_room != room )
            {
                roomblast = ( int )( blast * 0.25 ); /* 1|4 of remaining blast */
                room_explode_2( pexit->to_room->vnum, roomblast, range - 1 );
            }
        }
    }
}

// Return true if ship was destroyed
bool blast_damage_ship( ROOM_INDEX_DATA* room, CHAR_DATA* ch, int blast )
{
    char buf[MSL];
    static SHIP_DATA* last_ship = NULL;
    SHIP_DATA* ship = NULL;
    int dam;

    if ( room == NULL )
        return FALSE;

    if ( !xIS_SET( room->flags, ROOM_SPACECRAFT ) )
        return FALSE;

    if ( last_ship )
        if ( last_ship->firstroom >= room->vnum && last_ship->lastroom <= room->vnum )
            ship = last_ship;

    if ( !ship )
        ship = get_ship_from_room( room );

    if ( !ship )
        return FALSE;

    if ( xIS_SET( ship->flags, SHIP_INVINCIBLE ) && !xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
        return FALSE;

    if ( blast <= 0 )
        return FALSE; // no need to bother

    /* Special Effects :-D */
    // GRAL Weird desynch in hatchopen and breached hatch
    if ( ship->entrance == room->vnum && ( ship->hatchopen || xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) ) && ship->shipstate == SHIP_DOCKED )
    {
        snprintf( buf, MSL, "A wall of fire erupts from %s!", ship->name );
        ship_action( ship, buf );
    }

    if ( ship->engineroom == room->vnum && blast >= 10 )
    {
        tune( "blast_damage_ship: doing *10 blast damage to ship %s due to engine room at %d", ship->name, room->vnum );
        blast *= 10;

        if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) { }
        else if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "[ALERT]: Drive systems disabled - Exiting hyperspace!" );
            exit_hyperspace( ship );
            ship->shipstate = SHIP_DISABLED;
        }
        else
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "Ship Drive DAMAGED!" );
            ship->shipstate = SHIP_DISABLED;
        }
    }

    dam = ( int )( blast / 2 );
    tune( "blast_damage_ship: doing %d hull damage to %s at %d", dam, ship->name, room->vnum );
    ship->hull = UMAX( 0, ship->hull - dam );

    // GRAL It would be nice to have the thrower's name
    if ( ship->hull <= 0 && ship->maxhull > 0 )
    {
        if ( last_ship == ship )
            last_ship = NULL;

        if ( !xIS_SET( ship->flags, SHIP_SIMULATOR ) )
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "The cockpit is engulfed in flames as the ship is *OBLITERATED*" );
            echo_to_ship_main( AT_BLOOD, ship, "You scream in agony as your body is engulfed in flames!" );
            echo_to_ship_main( AT_BLOOD, ship, "The ship erupts into a blazing inferno, and explodes before you!" );
        }

        //Changed to more accurately reflect whether a ship was in space or not. Gathorn 9May16
        if ( ship->location == 0 )
        {
            snprintf( buf, MSL, "%s is engulfed in explosions!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            bool validchar = (ch != NULL);
            snprintf( buf, MSL, "internal grenade%s%s", validchar ? " by " : "", validchar ? ( !IS_NPC( ch ) ? ch->name : ch->short_descr ) : "" );
            destroy_ship( ship, NULL, ch, buf );
            return TRUE;
        }
        else
        {
            snprintf( buf, MSL, "%s erupts into a ball of fire on the pad!", ship->name );
            ship_action( ship, buf );
            echo_to_room( AT_ORANGE, get_room_index( ship->location ), "Flaming shrapnel is thrown from the exploding ship!" );
            ship_explode( ship );
            snprintf( buf, MSL, "%s has been destroyed!", ship->name );
            echo_to_room( AT_RED, get_room_index( ship->location ), buf );
            bool validchar = (ch != NULL);
            snprintf( buf, MSL, "internal grenade%s%s", validchar ? " by " : "", validchar ? ( !IS_NPC( ch ) ? ch->name : ch->short_descr ) : "" );
            destroy_ship( ship, NULL, ch, buf );
            return TRUE;
        }
    }
    else
    {
        last_ship = ship;
    }

    return FALSE;
}

bool contains_explosive( OBJ_DATA* obj, int antiloop )
{
    OBJ_DATA* pObj;

    if ( antiloop > 99999 )
    {
        bug( "contains_explosive: Reached nesting level of 99999. Aborting." );
        return FALSE;
    }

    if ( !obj->first_content )
        return FALSE;

    for ( pObj = obj->first_content; pObj; pObj = pObj->next_content )
    {
        if ( pObj->item_type == ITEM_CONTAINER )
        {
            if ( contains_explosive( pObj, ( antiloop + 1 ) ) )
                return TRUE;
        }
        else if ( pObj->item_type == ITEM_GRENADE || pObj->item_type == ITEM_BOMB )
        {
            if ( pObj->value[4] > 0 )
                return TRUE;
        }
    }

    return FALSE;
}

// Determines total value of a container
int contents_value( OBJ_DATA* obj, int antiloop )
{
    OBJ_DATA* pObj;
    int worth = 0;

    if ( antiloop > 99999 )
    {
        bug( "contents_value: Reached nesting level of 99999. Aborting." );
        return worth;
    }

    if ( !obj->first_content )
        return obj->cost;

    for ( pObj = obj->first_content; pObj; pObj = pObj->next_content )
    {
        worth += contents_value( pObj, ( antiloop + 1 ) );
    }

    return worth;
}

bool is_wizvis( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !IS_NPC( victim )
            &&   has_pcflag( victim, PCFLAG_WIZINVIS )
            &&   get_trust( ch ) < victim->pcdata->wizinvis )
        return FALSE;

    return TRUE;
}

int umin( int check, int ncheck )
{
    if ( check < ncheck )
        return check;

    return ncheck;
}

int umax( int check, int ncheck )
{
    if ( check > ncheck )
        return check;

    return ncheck;
}

int urange( int mincheck, int check, int maxcheck )
{
    if ( check < mincheck )
        return mincheck;

    if ( check > maxcheck )
        return maxcheck;

    return check;
}

/*
    Return how much exp a char has
*/
int get_exp( CHAR_DATA* ch, int ability )
{
    if ( ability >= MAX_ABILITY || ability < 0 )
        return 0;

    return ch->experience[ability];
}

/*
    New combat routine -- Calculates the characters max AP
*/
int get_max_ap( CHAR_DATA* ch )
{
    int ap = 0;
    ap = 3 + ( ( get_curr_dex( ch ) - 2 ) / 2 );
    ap = URANGE( 4, ap, 12 );
    return ap;
}

/*
    New armor class routine --- Functions like the the old one,
    but with maximum ranges and a built-in scaling function.
*/
int get_new_ac( CHAR_DATA* ch )
{
    int ac = 0;
    /* Base AC Bonus */
    ac = ch->armor;
    /* Apply DEXTERITY Modifier while awake */
    /* ac += ( IS_AWAKE(ch) ? dex_app[get_curr_dex(ch)].defensive : 0 ); */
    /* Apply Combat Level Modifier */
    ac -= ( ch->skill_level[COMBAT_ABILITY] / 2 );
    /* Apply racial modifiers */
    ac += ch->race->acmod;
    /*  if ( ch->race == RACE_BARABEL ) ac -= 100;
        else if ( ch->race == RACE_HUTT ) ac -= 250;
        else if ( ch->race == RACE_GEONOSIAN ) ac -= 100;
        else if ( ch->race == RACE_GAND ) ac -= 100;
        else if ( ch->race == RACE_IKTOTCHI ) ac -= 100;
         else if ( ch->race == RACE_TSURR ) ac -= 100;
        else if ( ch->race == RACE_TRANDOSHAN ) ac -= 100;
         else if ( ch->race == RACE_BARABEL ) ac -= 100;
    */
    ac = URANGE( -1000, ac, 600 );
    return ac;
}

/*                              -Thoric
    Return how much experience is required for ch to get to a certain level
*/
int exp_level( sh_int level )
{
    int lvl;
    lvl = ( int ) UMAX( 0, level - 1 );
    return ( lvl * lvl * 500 );
}

/*
    Get what level ch is based on exp
*/
sh_int level_exp( CHAR_DATA* ch, int exp )
{
    int x, lastx, y, tmp;

    if ( !ch )
        return 0;

    x = LEVEL_SUPREME;
    lastx = x;
    y = 0;

    while ( !y )
    {
        tmp = exp_level( x );
        lastx = x;

        if ( tmp > exp )
            x /= 2;
        else if ( lastx != x )
            x += ( x / 2 );
        else
            y = x;
    }

    if ( y < 1 )
        y = 1;

    if ( y > LEVEL_SUPREME )
        y = LEVEL_SUPREME;

    return y;
}

/*
    Retrieve a character's trusted level for permission checking.
*/
sh_int get_trust( CHAR_DATA* ch )
{
    if ( !ch )
        return 0;

    if ( ch && ch->desc && ch->desc->original && ch->desc->original != ch )
        ch = ch->desc->original;

    if ( IS_NPC( ch ) && ch->top_level >= LEVEL_GREATER && xIS_SET(ch->act, ACT_ESCALATED) )
        return LEVEL_GREATER;

    if ( IS_NPC( ch ) && ch->top_level >= LEVEL_AVATAR )
        return LEVEL_AVATAR;

    if ( ch->trust != 0 )
        return ch->trust;

    if ( ch->top_level >= LEVEL_NEOPHYTE && IS_RETIRED( ch ) )
        return LEVEL_NEOPHYTE;

    return ch->top_level;
}

