void fix_affect( AFFECT_DATA* paf )
{
    char bvstring[XBI * 12];
    // Port old affects represented with location+modifier to the bitvector
    if ( paf->location == APPLY_AFFECT && paf->modifier > 0 && xIS_EMPTY( paf->bitvector ) )
    {
        snprintf( bvstring, (XBI * 12), "%d", paf->modifier );
        paf->bitvector = parse_bitvector( bvstring );
        paf->modifier = 0;
    }

    return;
}

bool gives_affected_by( AFFECT_DATA* paf, int affect_id )
{
    if ( xIS_SET( paf->bitvector, affect_id ) )
        return true;

    return false;
}

// Returns true if the character is wearing an item which grants the same affect.
bool wearing_other_granting_affect( CHAR_DATA* ch, int affect_id )
{
    AFFECT_DATA* other_aff;

    for ( OBJ_DATA* other = ch->first_carrying; other; other = other->next_content )
    {
        if ( other->wear_loc == WEAR_NONE )
            continue;

        for ( other_aff = other->pIndexData->first_affect; other_aff; other_aff = other_aff->next )
            if ( gives_affected_by( other_aff, affect_id ) )
                return true;

        for ( other_aff = other->first_affect; other_aff; other_aff = other_aff->next )
            if ( gives_affected_by( other_aff, affect_id ) )
                return true;
    }

    return false;
}

/*
    Apply or remove an affect to a character.
*/
void affect_modify( void* target, sh_int aff_type, AFFECT_DATA* paf, bool fAdd )
{
    if ( !target || !paf || aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
        return;

    OBJ_DATA* wield;
    int mod, i;
    SKILL_DATA* skill;
    ch_ret retcode;
    mod = paf->modifier;
    CHAR_DATA* ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    ROOM_INDEX_DATA* room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;
    debug( "%s: %s affect (type:%d, loc:%d) from %s", fAdd ? "adding" : "removing", FUNC, paf->type, paf->location, ch ? ch->name : itoa( room->vnum ) );

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room.", FUNC );
        return;
    }

    if ( fAdd )
    {
        for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
        {
            if ( gives_affected_by( paf, affect_flags[i].flag ) )
            {
                if ( ch )
                    xSET_BIT( ch->affected_by, affect_flags[i].flag );
                else
                    xSET_BIT( room->affected_by, affect_flags[i].flag );
            }
        }

        // If adding affects, the above logic is all we needed so we can return now.
        if ( paf->location == APPLY_AFFECT )
            return;
    }
    else
    {
        AFFECT_DATA* other = NULL;

        for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
        {
            if ( gives_affected_by( paf, affect_flags[i].flag ) )
            {
                bool other_aff_provides = false;

                for ( other = (ch ? ch->first_affect : room->first_affect); other; other = other->next )
                    if ( other != paf && xIS_SET( other->bitvector, affect_flags[i].flag ) )
                        other_aff_provides = TRUE;

                // We check for all worn EQ because when removing gear with an affect, its wearloc is cleared
                // before we call this function.
                bool other_eq_provides = ch ? wearing_other_granting_affect( ch, affect_flags[i].flag ) : FALSE;
                debug( "%s: removing affect %s, other_aff_provides: %s, other_eq_provides: %s", FUNC, affect_flags[i].name, other_aff_provides ? "y" : "n", other_eq_provides ? "y" : "n" );

                if ( !other_aff_provides && !other_eq_provides )
                {
                    if ( ch )
                        xREMOVE_BIT( ch->affected_by, affect_flags[i].flag );
                    else
                        xREMOVE_BIT( room->affected_by, affect_flags[i].flag );
                }

                if ( affect_flags[i].flag == AFF_SMOKE )
                    for ( CHAR_DATA* rch = room->first_person; rch; rch = rch->next_in_room )
                        ch_println( rch, "&zYour vision clears as the smoke dissipates from the room." );
            }
        }

        // We've reached the end of what's useful for rooms -- for now.
        if ( !ch )
            return;

        /*
            might be an idea to have a duration removespell which returns
            the spell after the duration... but would have to store
            the removed spell's information somewhere...     -Thoric
            (Though we could keep the affect, but disable it for a duration)
        */
        if ( ( paf->location ) == APPLY_REMOVESPELL )
            return;

        switch ( paf->location )
        {
            case APPLY_AFFECT:
                // Affect removal already handled above, so just return now to skip all the below logic.
                return;

            case APPLY_RESISTANT:
                xREMOVE_BIT( ch->resistant, mod );
                return;

            case APPLY_IMMUNE:
                xREMOVE_BIT( ch->immune, mod );
                return;

            case APPLY_SUSCEPTIBLE:
                xREMOVE_BIT( ch->susceptible, mod );
                return;

            case APPLY_WEARSPELL:       /* affect only on wear */
                return;

            case APPLY_REMOVE:
                SET_BIT( ch->affected_by.bits[0], mod );
                return;
        }

        mod = 0 - mod;
    }

    // Nothing else to do for non-character affects -- for now.
    if ( !ch )
        return;

    switch ( paf->location )
    {
        case APPLY_NONE:
            break;

        case APPLY_STR:
            ch->mod_str     += mod;
            break;

        case APPLY_DEX:
            ch->mod_dex     += mod;
            break;

        case APPLY_INT:
            ch->mod_int     += mod;
            break;

        case APPLY_WIS:
            ch->mod_wis     += mod;
            break;

        case APPLY_CON:
            ch->mod_con     += mod;
            break;

        case APPLY_CHA:
            ch->mod_cha     += mod;
            break;

        case APPLY_LCK:
            ch->mod_lck     += mod;
            break;

        case APPLY_SEX:
            ch->sex = ( ch->sex + mod ) % 3;

            if ( ch->sex < 0 )
                ch->sex += 2;

            ch->sex = URANGE( 0, ch->sex, 2 );
            break;

        /*
            These are unused due to possible problems.  Enable at your own risk.
        */
        case APPLY_LEVEL:
            break;

        case APPLY_AGE:
            break;

        case APPLY_GOLD:
            break;

        case APPLY_EXP:
            break;

        case APPLY_KICK:
            break;

        case APPLY_PARRY:
            break;
        /*
            Regular apply types
        */
        case APPLY_HEIGHT:
            ch->height      += mod;
            break;

        case APPLY_WEIGHT:
            ch->weight      += mod;
            break;

        case APPLY_MANA:
            ch->max_mana        += mod;
            break;

        case APPLY_HIT:
            ch->max_hit     += mod;
            break;

        case APPLY_MOVE:
            ch->max_move        += mod;
            break;

        case APPLY_AC:
            ch->armor           += mod;
            break;

        case APPLY_HITROLL:
            ch->hitroll     += mod;
            break;

        case APPLY_DAMROLL:
            ch->damroll     += mod;
            break;

        case APPLY_SAVING_POISON:
            ch->saving_poison_death += mod;
            break;

        case APPLY_SAVING_ROD:
            ch->saving_wand     += mod;
            break;

        case APPLY_SAVING_PARA:
            ch->saving_para_petri   += mod;
            break;

        case APPLY_SAVING_BREATH:
            ch->saving_breath       += mod;
            break;

        case APPLY_SAVING_SPELL:
            ch->saving_spell_staff  += mod;
            break;

        case APPLY_RESISTANT:
            xSET_BIT( ch->resistant, mod );
            break;

        case APPLY_IMMUNE:
            xSET_BIT( ch->immune, mod );
            break;

        case APPLY_SUSCEPTIBLE:
            xSET_BIT( ch->susceptible, mod );
            break;

        case APPLY_WEAPONSPELL: /* see fight.c */
            break;

        case APPLY_REMOVE:
            REMOVE_BIT( ch->affected_by.bits[0], mod );
            break;

        /*
            Player condition modifiers
        */
        case APPLY_FULL:
            if ( !IS_NPC( ch ) )
                ch->pcdata->condition[COND_FULL] =
                    URANGE( 0, ch->pcdata->condition[COND_FULL] + mod, 48 );

            break;

        case APPLY_THIRST:
            if ( !IS_NPC( ch ) )
                ch->pcdata->condition[COND_THIRST] =
                    URANGE( 0, ch->pcdata->condition[COND_THIRST] + mod, 48 );

            break;

        case APPLY_DRUNK:
            if ( !IS_NPC( ch ) )
                ch->pcdata->condition[COND_DRUNK] =
                    URANGE( 0, ch->pcdata->condition[COND_DRUNK] + mod, 48 );

            break;

        case APPLY_BLOOD:
            if ( !IS_NPC( ch ) )
                ch->pcdata->condition[COND_BLOODTHIRST] =
                    URANGE( 0, ch->pcdata->condition[COND_BLOODTHIRST] + mod, ch->top_level + 10 );

            break;

        case APPLY_MENTALSTATE:
            ch->mental_state    = URANGE( -100, ch->mental_state + mod, 100 );
            break;

        case APPLY_EMOTION:
            ch->emotional_state = URANGE( -100, ch->emotional_state + mod, 100 );
            break;

        /*
            Specialty modfiers
        */
        case APPLY_STRIPSN:
            if ( IS_VALID_SN( mod ) )
                affect_strip( ch, CHAR_AFFECT, skill_from_id( mod ) );
            else
                bug( "%s: APPLY_STRIPSN invalid sn %d", FUNC, mod );

            break;

        /* spell cast upon wear/removal of an object    -Thoric */
        case APPLY_WEARSPELL:
        case APPLY_REMOVESPELL:
            if ( xIS_SET( ch->in_room->flags, ROOM_NO_MAGIC )
                    ||   xIS_SET( ch->immune, RIS_MAGIC ) )
                return;

            mod = abs( mod );

            if ( IS_VALID_SN( mod )
                    &&  ( skill = skill_from_id( mod ) ) != NULL
                    &&   skill->type == SKILL_SPELL )
            {
                if ( skill->target == TAR_IGNORE || skill->target == TAR_OBJ_INV )
                {
                    bug( "APPLY_WEARSPELL trying to apply bad target spell.  SN is %d.", mod );
                    return;
                }

                if ( ( retcode = ( *skill->spell_fun ) ( skill, ch->top_level, ch ) ) == rCHAR_DIED || char_extracted( ch ) )
                    return;
            }

            break;

        // NIXING THIS ALERT because Lua programs can now leverage affects even if they don't do anything on the C side. - Nield 04/08/2024
        default:
            return;
    }

    /*
        Check for weapon wielding.
        Guard against recursion (for weapons with affects).
    */
    if ( !IS_NPC( ch )
            &&  ( wield = get_eq_char( ch, WEAR_WIELD ) ) != NULL
            &&   get_obj_weight( wield ) > str_app[get_curr_str( ch )].wield )
    {
        static int depth;

        if ( depth == 0 )
        {
            depth++;
            act( AT_ACTION, "You are too weak to wield $p any longer.",
                 ch, wield, NULL, TO_CHAR );
            act( AT_ACTION, "$n stops wielding $p.", ch, wield, NULL, TO_ROOM );
            unequip_char( ch, wield );
            depth--;
        }
    }

    return;
}

/*
    Give an affect to a char.
*/
void affect_to_target( void* target, sh_int aff_type, AFFECT_DATA* paf )
{
    AFFECT_DATA* paf_new = NULL;
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;

    if ( !paf )
    {
        bug( "%s: missing affect", FUNC );
        return;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return;
    }

    CREATE( paf_new, AFFECT_DATA, 1 );
    if ( ch )
        LINK( paf_new, ch->first_affect, ch->last_affect, next, prev );
    else
        LINK( paf_new, room->first_affect, room->last_affect, next, prev );
    paf_new->type   = paf->type;
    paf_new->duration   = paf->duration;
    paf_new->location   = paf->location;
    paf_new->modifier   = paf->modifier;
    paf_new->bitvector  = paf->bitvector;
    for ( size_t i = 0; i < MAX_VALS; i++ )
        paf_new->value[i] = paf->value[i];
    affect_modify( target, aff_type, paf_new, TRUE );
    if ( room ) save_room( room, TRUE );
    return;
}

/*
    Remove an affect from a char.
*/
void affect_remove( void* target, sh_int aff_type, AFFECT_DATA* paf )
{
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;
    bool in_list = FALSE;

    if ( !paf )
    {
        bug( "%s: missing affect", FUNC );
        return;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return;
    }

    affect_modify( target, aff_type, paf, FALSE );
    if ( ch )
    {
        LINK_HASNODE( ch->first_affect, AFFECT_DATA, next, paf, in_list );
    }
    else
    {
        LINK_HASNODE( room->first_affect, AFFECT_DATA, next, paf, in_list );
    }

    if ( in_list )
    {
        if ( ch )
            UNLINK( paf, ch->first_affect, ch->last_affect, next, prev );
        else
            UNLINK( paf, room->first_affect, room->last_affect, next, prev );
    }
    FREE_STRUCT_NORET( paf, affect_fields );
    if ( room ) save_room( room, TRUE );
    return;
}

/*
    Strip all affects of a given sn.
*/
void affect_strip( void* target, sh_int aff_type, SKILL_DATA* skill )
{
    AFFECT_DATA* paf = NULL, *paf_next = NULL;
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;

    if ( !skill )
    {
        bug( "%s: missing skill", FUNC );
        return;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return;
    }

    for ( paf = (ch ? ch->first_affect : room->first_affect); paf; paf = paf_next )
    {
        paf_next = paf->next;

        if ( paf->type == skill->id )
            affect_remove( target, aff_type, paf );
    }

    if ( room ) save_room( room, TRUE );
    return;
}

/*
    Return true if a char is affected by a spell.
*/
bool is_affected( void* target, sh_int aff_type, SKILL_DATA* skill )
{
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;

    if ( !skill )
    {
        bug( "%s: missing skill", FUNC );
        return FALSE;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return FALSE;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return FALSE;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return FALSE;
    }

    bool retval = FALSE;
    if ( ch && skill )
        retval = xIS_SET( ch->affected_by, skill->id );
    else if ( room && skill )
        retval = xIS_SET( room->affected_by, skill->id );

    return retval;
}

