/*
    Add or enhance an affect.
    Limitations put in place by Thoric, they may be high... but at least
    they're there :)

    Limitations modified by Orion. Lowered to something REALISTIC FFS.
*/
void affect_join( void* target, sh_int aff_type, AFFECT_DATA* paf )
{
    AFFECT_DATA* paf_old;
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;
    int cap = 1000;

    if ( !paf )
    {
        bug( "%s: missing affect", FUNC );
        return;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return;
    }

    for ( paf_old = (ch ? ch->first_affect : room->first_affect); paf_old; paf_old = paf_old->next )
    {
        if ( paf_old->type == paf->type )
        {
            if ( xIS_SET( paf->bitvector, AFF_OBSCURE ) )
                cap = 3500;

            paf->duration = UMIN( cap, paf->duration + paf_old->duration );

            if ( paf->modifier )
                paf->modifier = UMIN( cap, paf->modifier + paf_old->modifier );
            else
                paf->modifier = paf_old->modifier;

            affect_remove( target, aff_type, paf_old );
            break;
        }
    }

    affect_to_target( target, aff_type, paf );
    if ( room ) save_room( room, TRUE );
    return;
}

/*
    Adds an affect to a character, first removing any of the same type.
*/
void affect_replace( void* target, sh_int aff_type, AFFECT_DATA* paf )
{
    AFFECT_DATA* paf_old;
    CHAR_DATA* ch = NULL;
    ROOM_INDEX_DATA* room = NULL;

    if ( !paf )
    {
        bug( "%s: missing affect", FUNC );
        return;
    }

    if ( !target )
    {
        bug( "%s: missing target", FUNC );
        return;
    }

    if ( aff_type < CHAR_AFFECT || aff_type > MAX_AFFECT )
    {
        bug( "%s: invalid aff type %d", FUNC, aff_type );
        return;
    }

    ch = aff_type == CHAR_AFFECT ? (CHAR_DATA*)target : NULL;
    room = aff_type == ROOM_AFFECT ? (ROOM_INDEX_DATA*)target : NULL;

    if ( !ch && !room )
    {
        bug( "%s: missing both ch and room", FUNC );
        return;
    }

    for ( paf_old = (ch ? ch->first_affect : room->first_affect); paf_old; paf_old = paf_old->next )
    {
        if ( ( paf->type != -1 && paf_old->type == paf->type ) || ( paf->type == -1 && ext_has_bits( &paf->bitvector, &paf_old->bitvector ) ) )
        {
            affect_remove( target, aff_type, paf_old );
            break;
        }
    }

    affect_to_target( target, aff_type, paf );
    if ( room ) save_room( room, TRUE );
    return;
}

// apply_type: one of apply_types (APPLY_INT, etc)
int affect_modifier_from_cybers( CHAR_DATA* ch, int apply_type )
{
    int result = 0;
    for ( CYBER_DATA* cyber = ch->first_cyber; cyber; cyber = cyber->next_on_char )
        for ( AFFECT_DATA* aff = cyber->cyber_index->first_affect; aff; aff = aff->next )
            if ( aff->location == apply_type )
                result += aff->modifier;
    return result;
}

int affect_modifier_from_equipment( CHAR_DATA* ch, int apply_type )
{
    int result = 0;
    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
    {
        if ( obj->wear_loc == WEAR_NONE )
            continue;

        for ( AFFECT_DATA* aff = obj->first_affect; aff; aff = aff->next )
            if ( aff->location == apply_type )
                result += aff->modifier;

        for ( AFFECT_DATA* aff = obj->pIndexData->first_affect; aff; aff = aff->next )
            if ( aff->location == apply_type )
                result += aff->modifier;

        // Special logic for built-in about/head armor bonuses        
        if ( apply_type == APPLY_DEX )
            result -= dex_mod( obj );
        if ( apply_type == APPLY_AC )
            result -= apply_ac( obj );
        if ( apply_type == APPLY_HIT )
            result += hp_mod( obj );
    }
    return result;
}

int affect_modifier_from_temporary( CHAR_DATA* ch, int apply_type )
{
    int result = 0;
    for ( AFFECT_DATA* aff = ch->first_affect; aff; aff = aff->next )
        if ( aff->location == apply_type )
            result += aff->modifier;
    return result;
}

/*
    Move a char out of a room.
*/
void char_from_room( CHAR_DATA* ch )
{
    OBJ_DATA* obj = NULL;
    CHAR_DATA* rch = NULL;
    SHIP_DATA* ship = NULL;

    if ( !ch )
    {
        bug( "Char_from_room: NULL char.", 0 );
        return;
    }

    if ( !ch->in_room )
    {
        bug( "Char_from_room: NULL room: %s", ch->name );
        return;
    }

    if ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
        ship->occupants--;


    // Clear any action text targeting the character leaving the room
    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( rch == ch )
            continue;

        if ( rch->aim == ch )
        {
            ch_println( rch, "You stop aiming." );
            action_clear( rch );
            rch->aim = NULL;
            rch->aim_part = 0;
        }

        if ( rch->action_to == ch )
            action_clear( rch );
    }

    action_clear( ch );

    if ( !IS_NPC( ch ) )
        --ch->in_room->area->nplayer;

    if ( ( obj = get_eq_char( ch, WEAR_LIGHT ) ) != NULL
            &&   obj->item_type == ITEM_LIGHT
            &&   obj->value[2] != 0
            &&   IS_SET( obj->value[3], 1 << 0 )
            &&   ch->in_room->light > 0 )
        --ch->in_room->light;

    bool found = false;
    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        if ( rch == ch )
            found = true;

    if ( found )
        UNLINK( ch, ch->in_room->first_person, ch->in_room->last_person, next_in_room, prev_in_room );
    ch->in_room      = NULL;
    ch->next_in_room = NULL;
    ch->prev_in_room = NULL;

    if ( ch->block )
    {
        ch->block = NULL;
        action_clear_ex( ch, AS_UNLOCK );
        debug( "clearing block on %s during from room", ch->name );
    }

    if ( !IS_NPC( ch )
            &&   get_timer( ch, TIMER_SHOVEDRAG ) > 0 )
        remove_timer( ch, TIMER_SHOVEDRAG );

    return;
}

/* Used when very temporarily moving a character out of the room (i.e., for "look") so as to avoid
   clearing their actiondescs */
void char_from_room_temporary( CHAR_DATA* ch )
{
    OBJ_DATA* obj;

    if ( !ch )
    {
        bug( "char_from_room_temporary: NULL char.", 0 );
        return;
    }

    if ( !ch->in_room )
    {
        bug( "char_from_room_temporary: NULL room: %s", ch->name );
        return;
    }

    if ( !IS_NPC( ch ) )
        --ch->in_room->area->nplayer;

    if ( ( obj = get_eq_char( ch, WEAR_LIGHT ) ) != NULL
            &&   obj->item_type == ITEM_LIGHT
            &&   obj->value[2] != 0
            &&   IS_SET( obj->value[3], 1 << 0 )
            &&   ch->in_room->light > 0 )
        --ch->in_room->light;

    bool found = false;
    CHAR_DATA* rch = NULL;
    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        if ( rch == ch )
            found = true;

    if ( found )
        UNLINK( ch, ch->in_room->first_person, ch->in_room->last_person, next_in_room, prev_in_room );

    ch->in_room      = NULL;
    ch->next_in_room = NULL;
    ch->prev_in_room = NULL;

    return;
}


/*
    Move a char into a room.
*/
void char_to_room( CHAR_DATA* ch, ROOM_INDEX_DATA* pRoomIndex )
{
    OBJ_DATA* obj = NULL;
    SHIP_DATA* ship = NULL;

    if ( !ch )
    {
        bug( "Char_to_room: NULL ch!", 0 );
        return;
    }

    if ( ch->in_room )
        char_from_room( ch );

    if ( !pRoomIndex || room_extracted( pRoomIndex ) )
    {
        bug( "%s: %s -> NULL room!  Putting char in limbo (%d)", __FUNCTION__, ch->name, ROOM_VNUM_LIMBO );
        /*
            This used to just return, but there was a problem with crashing
            and I saw no reason not to just put the char in limbo.  -Narn
        */
        pRoomIndex = get_room_index( ROOM_VNUM_LIMBO );
    }

    if ( !pRoomIndex )
    {
        bug("char_to_room: could not establish pRoomIndex for %s.", !IS_NPC( ch ) ? ch->name : ch->short_descr );
        return;
    }

    ch->in_room = pRoomIndex;

    LINK( ch, pRoomIndex->first_person, pRoomIndex->last_person,
          next_in_room, prev_in_room );

    if ( !IS_NPC( ch ) )
        if ( ++ch->in_room->area->nplayer > ch->in_room->area->max_players )
            ch->in_room->area->max_players = ch->in_room->area->nplayer;

    if ( ( obj = get_eq_char( ch, WEAR_LIGHT ) ) != NULL
            &&   obj->item_type == ITEM_LIGHT
            &&   IS_SET( obj->value[3], 1 << 0 )
            &&   obj->value[2] != 0 )
        ++ch->in_room->light;

    if ( !IS_NPC( ch )
            &&    get_timer( ch, TIMER_SHOVEDRAG ) <= 0 )
        add_timer( ch, TIMER_SHOVEDRAG, 30, NULL, NULL, FUNC );

    /*
        Delayed Teleport rooms                   -Thoric
        Should be the last thing checked in this function
    */
    if ( xIS_SET( ch->in_room->flags, ROOM_TELEPORT )
            &&   ch->in_room->tele_delay > 0 )
    {
        TELEPORT_DATA* tele;

        for ( tele = first_teleport; tele; tele = tele->next )
            if ( tele->room == pRoomIndex )
                return;

        CREATE( tele, TELEPORT_DATA, 1 );
        LINK( tele, first_teleport, last_teleport, next, prev );
        tele->room      = pRoomIndex;
        tele->timer     = pRoomIndex->tele_delay;
    }

    if ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
        ship->occupants++;

    save_char_obj( ch, true );
    return;
}

/*
    Give an obj to a char.
*/
OBJ_DATA* obj_to_char( OBJ_DATA* obj, CHAR_DATA* ch )
{
    if ( !obj || !ch )
        return NULL;

    if ( obj->in_room )
        obj_from_room( obj );

    if ( obj->in_obj )
        obj_from_obj( obj );

    if ( obj->carried_by )
        obj_from_char( obj );

    if ( obj->in_locker )
        obj_from_locker( obj );

    OBJ_DATA* otmp;
    OBJ_DATA* oret = obj;
    bool grouped = FALSE;
    int oweight = get_obj_weight( obj );
    int onum = get_obj_number( obj );
    int wear_loc = obj->wear_loc;
    EXT_BV extra_flags = obj->extra_flags;

    if ( IS_OBJ_STAT( obj, ITEM_PROTOTYPE ) )
        if ( !IS_IMMORTAL( ch ) && ( !IS_NPC( ch ) || !xIS_SET( ch->act, ACT_PROTOTYPE ) ) )
            return obj_to_room( obj, ch->in_room );

    for ( otmp = ch->first_carrying; otmp; otmp = otmp->next_content )
        if ( ( oret = group_object( otmp, obj ) ) == otmp )
        {
            grouped = TRUE;
            break;
        }

    if ( !grouped )
    {
        LINK( obj, ch->first_carrying, ch->last_carrying, next_content, prev_content );
        obj->carried_by         = ch;
        obj->in_room            = NULL;
        obj->in_obj         = NULL;
    }

    if ( wear_loc == WEAR_NONE )
    {
        ch->carry_number    += onum;
        ch->carry_weight    += oweight;
    }
    else if ( !xIS_SET( extra_flags, ITEM_MAGIC ) )
        ch->carry_weight    += oweight;

    save_char_obj( ch, true );
    return ( oret ? oret : obj );
}



/*
    Take an obj from its character.
*/
void obj_from_char( OBJ_DATA* obj )
{
    CHAR_DATA* ch;

    if ( !obj )
        return;

    if ( ( ch = obj->carried_by ) == NULL )
    {
        bug( "Obj_from_char: null ch.", 0 ); /* GRAL Bug happens here so did it extract the wrong object */
        return;
    }

    OBJ_DATA* rObj = NULL;
    bool found = false;
    for ( rObj = ch->first_carrying; rObj; rObj = rObj->next_content )
        if ( rObj == obj )
            found = true;

    if ( obj->wear_loc != WEAR_NONE )
        unequip_char( ch, obj );

    /* obj may drop during unequip... */
    if ( !found && !obj->carried_by )
        return;

    /* make sure we clear curr_comlink */
    if ( obj == ch->curr_comlink )
        ch->curr_comlink = NULL;

    if ( found )
        UNLINK( obj, ch->first_carrying, ch->last_carrying, next_content, prev_content );

    if ( IS_OBJ_STAT( obj, ITEM_COVERING ) && obj->first_content )
        empty_obj( obj, NULL, NULL, NULL );

    obj->in_room     = NULL;
    obj->carried_by  = NULL;
    obj->fresh_reset = false;

    if ( found )
    {
        ch->carry_number    -= get_obj_number( obj );
        ch->carry_weight    -= get_obj_weight( obj );
    }

    save_char_obj( ch, true );
    return;
}

int apply_ac( OBJ_DATA* obj )
{
    if ( obj->item_type != ITEM_ARMOR || obj->value[4] > 0 )
        return 0;

    if ( obj->value[2] == 0 || obj->value[2] > 12 || obj->value[0] > 13 )
        return 0;

    int base_ac = 0;

    switch ( get_armor_type( obj ) )
    {
        case 1:
            base_ac = 60;
            break;

        case 2:
            base_ac = 480;
            break;

        case 3:
            base_ac = 700;
            break;
    }

    if ( xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) )
        return base_ac;
    else if ( xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) )
        return base_ac / 4;

    return 0;
}

/*
    Find a piece of eq on a character.
    Will pick the top layer if clothing is layered.      -Thoric
*/
OBJ_DATA* get_eq_char( CHAR_DATA* ch, int iWear )
{
    OBJ_DATA* obj, *maxobj = NULL;

    if ( ch->first_carrying == NULL )
        return NULL;

    for ( obj = ch->first_carrying; obj; obj = obj->next_content )
        if ( obj->wear_loc == iWear )
        {
            if ( !obj->pIndexData->layers )
                return obj;
            else if ( !maxobj
                      ||    obj->pIndexData->layers > maxobj->pIndexData->layers )
                maxobj = obj;
        }

    return maxobj;
}

/*
    Equip a char with an obj.
*/
void equip_char( CHAR_DATA* ch, OBJ_DATA* obj, int iWear )
{
    OBJ_DATA*    otmp;
    CLAN_DATA* clan = NULL;

    if ( obj->carried_by != ch )
    {
        // bug( "equip_char: obj not being carried by ch!" );
        // 15Apr09 Spammed silly with this with not enough info. Changed for more info:
        bug( "Equip_char: obj(%d) not being carried by ch(%s)! already equipped in room %d.", obj->pIndexData->vnum, ch->name, ch->in_room->vnum );
        return;
    }

    if ( ( otmp = get_eq_char( ch, iWear ) ) != NULL
            &&   ( !otmp->pIndexData->layers || !obj->pIndexData->layers || iWear == WEAR_HEAD || iWear == WEAR_ABOUT ) )
    {
        bug( "Equip_char: already equipped ((%d)%s in room %d, location %d).", obj->pIndexData->vnum, ch->name, ch->in_room->vnum, iWear );
        return;
    }

    separate_obj( obj ); /* just in case */

    if ( ( IS_OBJ_STAT( obj, ITEM_ANTI_EVIL )    && IS_EVIL( ch )    )
            ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_GOOD )    && IS_GOOD( ch )    )
            ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_NEUTRAL ) && IS_NEUTRAL( ch ) )
            ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_JEDI ) && IS_JEDI( ch ) )
            ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_SITH ) && IS_SITH( ch ) ) )
    {
        act( AT_MAGIC, "You are zapped by $p and drop it.", ch, obj, NULL, TO_CHAR );
        act( AT_MAGIC, "$n is zapped by $p and drops it.",  ch, obj, NULL, TO_ROOM );

        if ( obj->carried_by )
            obj_from_char( obj );

        obj_to_room( obj, ch->in_room );
        oprog_zap_trigger( ch, obj );

        if ( IS_SET( sysdata.save_flags, SV_ZAPDROP ) && ch != NULL )
            save_char_obj( ch, true );

        return;
    }

    if ( obj->item_type == ITEM_ARMOR && obj->value[4] > 0 )
    {
        if ( NULLSTR( obj->short_descr ) )
        {
            SET_STRING( obj->short_descr, "broken item" );
            SET_STRING( obj->name, obj->short_descr );
        }

        if ( !obj->blueprint )
            SET_STRING( obj->blueprint, obj->short_descr );
    }

    if ( ( clan = get_clan( obj->obj_clan ) ) != NULL )
    {
        if ( !ch->pcdata || !ch->pcdata->clan )
            return;

        if ( ch->pcdata->clan != clan )
            return;
    }

    xREMOVE_BIT( obj->extra_flags, ITEM_HIDDEN );
    obj->wear_loc    = iWear;
    ch->carry_number    -= get_obj_number( obj );

    if ( xIS_SET( obj->extra_flags, ITEM_MAGIC ) )
        ch->carry_weight  -= get_obj_weight( obj );

    if ( obj->item_type == ITEM_BINDING && xIS_SET( obj->wear_flags, ITEM_WEAR_BINDING ) )
        ch->held = TRUE;

    apply_equip_stats( ch, obj );

    if ( obj->item_type == ITEM_LIGHT
            &&   IS_SET( obj->value[3], 1 << 0 )
            &&   obj->value[2] != 0
            &&   ch->in_room )
        ++ch->in_room->light;

    return;
}

/*
    Unequip a char with an obj.
*/
void unequip_char( CHAR_DATA* ch, OBJ_DATA* obj )
{
    if ( obj->wear_loc == WEAR_NONE )
    {
        bug( "Unequip_char: already unequipped.", 0 );
        return;
    }

    ch->carry_number    += get_obj_number( obj );

    if ( xIS_SET( obj->extra_flags, ITEM_MAGIC ) )
        ch->carry_weight  += get_obj_weight( obj );

    obj->wear_loc    = WEAR_NONE;

    unapply_equip_stats( ch, obj );
}

void apply_equip_stats( CHAR_DATA* ch, OBJ_DATA* obj )
{
    AFFECT_DATA* paf;

    bool full_hp = ch->hit == ch->max_hit;

    ch->armor -= apply_ac( obj );

    for ( paf = obj->pIndexData->first_affect; paf; paf = paf->next )
        affect_modify( ch, CHAR_AFFECT, paf, TRUE );

    for ( paf = obj->first_affect; paf; paf = paf->next )
        affect_modify( ch, CHAR_AFFECT, paf, TRUE );

    if ( obj->item_type == ITEM_ARMOR && obj->value[2] > 0 && obj->value[0] <= 13
            && ( xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) || xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) ) )
    {
        ch->mod_dex -= dex_mod( obj );
        ch->max_hit += hp_mod( obj );
    }

    // If they were at full hp before equipping this and weren't recently fighting,
    // restore them after wearing it.
    if ( full_hp && !get_timer( ch, TIMER_RECENTFIGHT ) )
        ch->hit = ch->max_hit;
}

void unapply_equip_stats( CHAR_DATA* ch, OBJ_DATA* obj )
{
    AFFECT_DATA* paf;

    ch->armor += apply_ac( obj );

    for ( paf = obj->pIndexData->first_affect; paf; paf = paf->next )
        affect_modify( ch, CHAR_AFFECT, paf, FALSE );

    for ( paf = obj->first_affect; paf; paf = paf->next )
        affect_modify( ch, CHAR_AFFECT, paf, FALSE );

    if ( obj->item_type == ITEM_ARMOR && obj->value[2] > 0 && obj->value[0] <= 13
            && ( xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) || xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) ) )
    {
        ch->mod_dex += dex_mod( obj );
        ch->max_hit -= hp_mod( obj );
    }
}

/*
    Count occurrences of an obj in a list.
*/
int count_obj_list( OBJ_INDEX_DATA* pObjIndex, OBJ_DATA* list )
{
    OBJ_DATA* obj;
    int nMatch;
    nMatch = 0;

    for ( obj = list; obj; obj = obj->next_content )
        if ( obj->pIndexData == pObjIndex )
            nMatch++;

    return nMatch;
}



/*
    Move an obj out of a room.
*/

int falling;

void obj_from_room( OBJ_DATA* obj )
{
    ROOM_INDEX_DATA* in_room;

    if ( ( in_room = obj->in_room ) == NULL )
    {
        bug( "obj_from_room: NULL.", 0 );
        return;
    }
    OBJ_DATA* rObj = NULL;
    bool found = false;
    for ( rObj = in_room->first_content; rObj; rObj = rObj->next_content )
        if ( rObj == obj )
            found = true;

    if ( found )
        UNLINK( obj, in_room->first_content, in_room->last_content, next_content, prev_content );

    if ( IS_OBJ_STAT( obj, ITEM_COVERING ) && obj->first_content )
        empty_obj( obj, NULL, obj->in_room, NULL );

    if ( obj->item_type == ITEM_FIRE )
        obj->in_room->light -= obj->count;

    obj->carried_by   = NULL;
    obj->in_obj       = NULL;
    obj->in_room      = NULL;

    // Objects not in a room are no longer stored with the persistent objects --
    // they're stored with whowever/whatever is holding or containing them. - Nield 06/21/2024
    if ( !dump_mem_on_shutdown && falling == 0 && obj->id > 0 )
    {
        delete_sql_row_by_id( "persistent_objects", obj->id );
        obj->id = 0;
    }

    obj->fresh_reset = false;

    return;
}

/*
    Move an obj into a room.
*/
OBJ_DATA* obj_to_room( OBJ_DATA* obj, ROOM_INDEX_DATA* pRoomIndex )
{
    if ( !obj || !pRoomIndex )
        return NULL;

    if ( obj->in_room )
        obj_from_room( obj );

    if ( obj->in_obj )
        obj_from_obj( obj );

    if ( obj->carried_by )
        obj_from_char( obj );

    if ( obj->in_locker )
        obj_from_locker( obj );

    OBJ_DATA* otmp, *oret;
    sh_int count = obj->count;
    sh_int item_type = obj->item_type;

    if ( pRoomIndex->first_content )
    {
        for ( otmp = pRoomIndex->first_content; otmp; otmp = otmp->next_content )
        {
            if ( otmp == NULL )
                continue;

            if ( ( oret = group_object( otmp, obj ) ) == otmp )
            {
                if ( item_type == ITEM_FIRE )
                    pRoomIndex->light += count;

                save_persistent_object( oret, true );
                return oret;
            }
        }
    }

    LINK( obj, pRoomIndex->first_content, pRoomIndex->last_content,
          next_content, prev_content );
    obj->in_room                = pRoomIndex;
    obj->carried_by             = NULL;
    obj->in_obj                 = NULL;

    if ( item_type == ITEM_FIRE )
        pRoomIndex->light += count;

    falling++;
    obj_fall( obj, FALSE );
    falling--;
    save_persistent_object( obj, true );
    return obj;
}

/*
    Move an object into an object.
*/
OBJ_DATA* obj_to_obj( OBJ_DATA* obj, OBJ_DATA* obj_to )
{
    if ( !obj || !obj_to )
        return NULL;

    OBJ_DATA* otmp, *oret;

    if ( obj == obj_to )
    {
        bug( "Obj_to_obj: trying to put object inside itself: vnum %d", obj->pIndexData->vnum );
        return obj;
    }

    if ( obj->in_room )
        obj_from_room( obj );

    if ( obj->in_obj )
        obj_from_obj( obj );

    if ( obj->carried_by )
        obj_from_char( obj );

    if ( obj->in_locker )
        obj_from_locker( obj );

    if ( obj_to->carried_by )
    {
        obj_to->carried_by->carry_weight += get_obj_weight( obj );
        obj_to->carried_by->carry_number += get_obj_number( obj );
    }

    for ( otmp = obj_to->first_content; otmp; otmp = otmp->next_content )
        if ( ( oret = group_object( otmp, obj ) ) == otmp )
            return oret;


    LINK( obj, obj_to->first_content, obj_to->last_content, next_content, prev_content );
    obj->in_obj              = obj_to;
    obj->in_room             = NULL;
    obj->carried_by          = NULL;

    if ( obj_to->in_room )
        save_persistent_object( obj_to, true );
    return obj;
}

/*
    Move an object into a locker.
*/
OBJ_DATA* obj_to_locker( OBJ_DATA* obj, LOCKER_DATA* locker )
{
    if ( !obj || !locker )
        return NULL;

    OBJ_DATA* otmp, *oret;

    if ( obj->in_room )
        obj_from_room( obj );

    if ( obj->in_obj )
        obj_from_obj( obj );

    if ( obj->carried_by )
        obj_from_char( obj );

    if ( obj->in_locker )
        obj_from_locker( obj );

    for ( otmp = locker->first_content; otmp; otmp = otmp->next_content )
        if ( ( oret = group_object( otmp, obj ) ) == otmp )
            return oret;

    LINK( obj, locker->first_content, locker->last_content,
          next_content, prev_content );
    obj->in_obj              = NULL;
    obj->in_room             = NULL;
    obj->carried_by          = NULL;
    obj->in_locker           = locker;
    save_locker( locker, true );
    return obj;
}


/*
    Move an object out of an object.
*/
void obj_from_obj( OBJ_DATA* obj )
{
    if ( !obj )
        return;

    OBJ_DATA* obj_from = NULL, *rObj = NULL;

    if ( ( obj_from = obj->in_obj ) == NULL )
    {
        bug( "Obj_from_obj: null obj_from.", 0 );
        return;
    }

    bool found = false;
    for ( rObj = obj_from->first_content; rObj; rObj = rObj->next_content )
        if ( rObj == obj )
            found = true;

    if ( found )
    {
        rObj = obj->in_obj;
        UNLINK( obj, obj_from->first_content, obj_from->last_content, next_content, prev_content );
        for ( rObj = obj->in_obj; rObj; rObj = rObj->in_obj )
        {
            if ( rObj->carried_by )
            {
                rObj->carried_by->carry_weight -= get_obj_weight( obj );
                rObj->carried_by->carry_number -= get_obj_number( obj );
            }
        }      
    }

    rObj = obj->in_obj;

    if ( IS_OBJ_STAT( obj, ITEM_COVERING ) && obj->first_content )
        empty_obj( obj, obj->in_obj, NULL, NULL );

    obj->in_obj       = NULL;
    obj->in_room      = NULL;
    obj->carried_by   = NULL;
    obj->fresh_reset = false;

    while ( rObj->in_obj != NULL )
        rObj = rObj->in_obj;

    if ( rObj && rObj->in_room )
        save_persistent_object( rObj, true );

    return;
}

/*
    Move an object out of a locker.
*/
void obj_from_locker( OBJ_DATA* obj )
{
    if ( !obj )
        return;

    LOCKER_DATA* obj_from;

    if ( ( obj_from = obj->in_locker ) == NULL )
    {
        bug( "Obj_from_locker: null obj_from.", 0 );
        return;
    }

    OBJ_DATA* rObj = NULL;
    bool found = false;
    for ( rObj = obj_from->first_content; rObj; rObj = rObj->next_content )
        if ( rObj == obj )
            found = true;

    if ( found )
        UNLINK( obj, obj_from->first_content, obj_from->last_content, next_content, prev_content );

    if ( IS_OBJ_STAT( obj, ITEM_COVERING ) && obj->first_content )
        empty_obj( obj, NULL, NULL, obj_from );

    obj->in_obj       = NULL;
    obj->in_room      = NULL;
    obj->carried_by   = NULL;
    obj->in_locker = NULL;
    save_locker( obj_from, true );
    return;
}

/*
    Extract an obj from the world.
*/
int extract_obj( OBJ_DATA* obj )
{
    OBJ_DATA* obj_content = NULL;
    BUFFER_DATA* buffer = NULL;

    if ( !obj )
    {
        bug( "extract_obj: !obj" );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    if ( obj->reset_ptr )
        *obj->reset_ptr = NULL;

    if ( obj->fp_internal_memory != NULL )
        fclose( obj->fp_internal_memory );

    SET_STRING( obj->internal_memory, NULL );
    lua_triggers_extract_subject( &obj->first_trigger, 0 );
    lua_extract_delayed_triggers( obj, LUA_PARAM_OBJ );
    if ( obj_extracted( obj ) )
    {
        if ( lotj_ready && obj->pIndexData )
            bug( "%s: obj %d already extracted!", FUNC, obj->pIndexData->vnum );

        return E_LOTJ_NOTHING_TO_DO;
    }

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
    {
        if ( d->character && ( buffer = get_buffer( d->character, "do_oset" ) ) != NULL && buffer->obj == obj )
        {
            ch_println( d->character, "Your oset target has been extracted." );
            d->character->substate = SUB_NONE;
            dispose_buffer( buffer );

            if ( d->character->pcdata && d->character->pcdata->subprompt )
                SET_STRING( d->character->pcdata->subprompt, NULL );
        }
    }

    if ( obj->item_type == ITEM_TRANSMITTER && obj->value[IVAL_TRANSMITTER_STATE] == 1 )
        transmit_leave_channel( obj );

    if ( obj->carried_by )
        obj_from_char( obj );

    if ( obj->in_room )
        obj_from_room( obj );

    if ( obj->in_obj )
        obj_from_obj( obj );

    if ( obj->in_locker )
        obj_from_locker( obj );

    while ( ( obj_content = obj->last_content ) != NULL )
        extract_obj( obj_content );

    if ( obj == gobj_prev )
        gobj_prev       = obj->prev;

    if ( obj->tlprog )
    {
        UNLINK( obj->tlprog, first_timeprog, last_timeprog, next, prev );
        DISPOSE( obj->tlprog );
    }

    UNLINK( obj, first_object, last_object, next, prev );
    /* shove onto extraction queue */
    queue_extracted_obj( obj );
    if ( obj->pIndexData )
        obj->pIndexData->count -= obj->count;

    numobjsloaded -= obj->count;
    --physicalobjects;

    if ( obj->serial == cur_obj )
    {
        cur_obj_extracted = TRUE;

        if ( global_objcode == rNONE )
            global_objcode = rOBJ_EXTRACTED;
    }

    hashset_remove( valid_objs, obj );
    return E_LOTJ_SUCCESS;
}

/*
    Extract a char from the world.
*/
int extract_char( CHAR_DATA* ch )
{
    CHAR_DATA* wch = NULL, *droid_mob = NULL;
    OBJ_DATA* obj = NULL, *next_obj = NULL;
    GREET_DATA* greet = NULL, *ngreet = NULL;
    BUFFER_DATA* buffer = NULL;
    DROID_DATA* droid = NULL;
    LOCKER_DATA* locker = NULL, *next_locker = NULL;
    TEACH_DATA* teach = NULL, *next_teach = NULL;
    bool hasnode = FALSE;

    if ( !ch )
    {
        bug( "%s: NULL ch", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    //do it quietly
    if ( IS_PUFF( ch ) )
        return E_LOTJ_NOTHING_TO_DO;

    if ( ch == supermob )
        return E_LOTJ_NOTHING_TO_DO;

    if ( ch->reset_ptr )
        *ch->reset_ptr = NULL;

    if ( char_extracted( ch ) )
    {
        bug( "%s: %s already extracted!", FUNC, ch->name );
        return E_LOTJ_NOTHING_TO_DO;
    }

    stop_hunting( ch );
    stop_hating( ch );
    stop_fearing( ch );
    free_fight( ch );

    for ( wch = first_char; wch; wch = wch->next )
    {
        LINK_HASNODE( wch->first_follower, CHAR_DATA, next_follower, ch, hasnode );
        if ( hasnode )
            UNLINK( ch, wch->first_follower, wch->last_follower, next_follower, prev_follower );

        if ( wch->leader == ch )
            wch->leader = NULL;

        if ( wch->master == ch )
            wch->master = NULL;

        if ( wch->hunting && wch->hunting->who == ch )
            stop_hunting( wch );

        if ( wch->hating && wch->hating->who == ch )
            stop_hating( wch );

        if ( wch->fearing && wch->fearing->who == ch )
            stop_fearing( wch );

        if ( wch->fighting && wch->fighting->who == ch )
            stop_fighting( wch, FALSE );

        if ( wch->approach == ch )
            wch->approach = NULL;

        if ( wch->action_to == ch )
            action_clear_ex( wch, AS_UNLOCK );

        if ( wch->aim == ch )
            clear_aim( wch );

        if ( wch->carried == ch )
            wch->carried = NULL;

        if ( wch->carrying == ch )
            wch->carrying = NULL;

        if ( wch->heldby == ch )
        {
            wch->heldby = NULL;
            wch->held = FALSE;
        }

        if ( wch->holding == ch )
            wch->holding = NULL;

        if ( wch->mount == ch )
        {
            wch->mount = NULL;
            if ( wch->position == POS_MOUNTED )
                wch->position = wch->hit > 0 ? POS_STANDING : POS_STUNNED;
        }

        if ( wch->reply == ch )
            wch->reply = NULL;

        if ( wch->switched == ch )
        {
            do_return( ch, "" );
            wch->switched = NULL;
        }

        if ( wch->watching == ch )
            wch->watching = NULL;       
    }

    for ( VEHICLE_DATA* vec = first_vehicle; vec; vec = vec->next )
        if ( vec->target_c == ch )
            vec->target_c = NULL;

    for ( MISSILE_DATA* missile = first_missile; missile; missile = missile->next )
        if ( missile->fired_by == ch )
            missile->fired_by = NULL;

    for ( FCARGO_DATA* fcargo = first_fcargo; fcargo; fcargo = fcargo->next )
        if ( fcargo->fired_by == ch )
            fcargo->fired_by = NULL;

    if ( ch->carrying )
        ch->carrying = NULL;

    AFFECT_DATA* paf = NULL;
    while ( ( paf = ch->last_affect ) != NULL )
        affect_remove( ch, CHAR_AFFECT, paf );

    TIMER* timer = NULL;
    while ( ( timer = ch->first_timer ) != NULL )
        extract_timer( ch, timer );

    if ( ch->editor )
        stop_editing( ch, false );

    if ( !IS_NPC( ch ) )
    {
        droid = droid_from_owner( ch->id, FALSE );
        droid_mob = mob_from_droid( droid );

        if ( droid )
        {
            // Unload it if the mob is still alive. Delete it outright if it's not.
            if ( droid_mob )
                unload_droid( droid );
            else
                delete_droid( droid );
        }

        // Free up clan mobs to be controlled by someone else
        droid = droid_from_controller( ch->id );
        droid_mob = mob_from_droid( droid );

        if ( droid && droid->clan_owned )
        {
            if ( !droid_mob )
                delete_droid( droid );
            else
            {
                droid->controller = 0;
                droid->active = 3;
                do_block( droid_mob, "" );
                do_follow( droid_mob, "self" );
                save_droid( droid, true );
            }
        }
    }

    if ( !IS_NPC( ch ) )
    {
        for ( locker = first_locker; locker; locker = next_locker )
        {
            next_locker = locker->next;
            if ( locker->player_id == ch->id && locker->clan_id == 0 && locker->open == FALSE && !str_cmp( locker->owner_name, ch->name ) )
            {
                UNLINK( locker, first_locker, last_locker, next, prev );
                FREE_STRUCT_NORET( locker, locker_fields );
            }
        }

        for ( teach = first_teach; teach; teach = next_teach )
        {
            next_teach = teach->next;

            if ( teach->student == ch || teach->teacher == ch )
            {
                UNLINK( teach, first_teach, last_teach, next, prev );
                DISPOSE( teach );
            }
        }
    }

    mob_act_remove( ch );

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
    {
        if ( d->character && ( buffer = get_buffer( d->character, "do_mset" ) ) != NULL && buffer->target == ch )
        {
            ch_println( d->character, "Your mset target has been extracted." );
            d->character->substate = SUB_NONE;
            dispose_buffer( buffer );

            if ( d->character->pcdata && d->character->pcdata->subprompt )
                SET_STRING( d->character->pcdata->subprompt, NULL );
        }
    }

    clear_buffers( ch );

    if ( ch->ai_data )
    {
        extract_ai( ch->ai_data );
        ch->ai_data = NULL;
    }

    if ( ch->vendor_data )
    {
        UNLINK( ch->vendor_data, first_vendor, last_vendor, next, prev );
        ch->vendor_data->mob = NULL;
        ch->vendor_data = NULL;
    }

    if ( ch->droid_data )
    {
        ch->droid_data->mob = NULL;
        ch->droid_data = NULL;
    }

    DB_DATA* mtalk = get_mindtalk( ch, true );

    if ( mtalk )
        do_mindtalk( ch, "end" );

    if ( ch->mount )
    {
        xREMOVE_BIT( ch->mount->act, ACT_MOUNTED );
        ch->mount = NULL;
        ch->position = POS_STANDING;
    }

    if ( IS_NPC( ch ) && xIS_SET( ch->act, ACT_MOUNTED ) )
        xREMOVE_BIT( ch->act, ACT_MOUNTED );

    for ( obj = ch->first_carrying; obj; obj = next_obj )
    {
        next_obj = obj->next_content;
        extract_obj( obj );
    }

    clear_piloting( ch );

    if ( gch_prev == ch )
        gch_prev = ch->prev;

    if ( ch == cur_char )
        cur_char_extracted = TRUE;

    /* shove onto extraction queue */
    queue_extracted_char( ch );

    if ( ch->in_room )
        char_from_room( ch );

    if ( IS_SWITCHED( ch ) )
        do_return( ch, "" );

    if ( IS_NPC( ch ) )
    {
        --ch->pIndexData->count;
        --nummobsloaded;
    }

    /* Start removing GREET Structures */
    if ( ch->pcdata )
    {
        if ( ch->pcdata->first_greet )
        {
            for ( greet = ch->pcdata->first_greet; greet; greet = ngreet )
            {
                ngreet = greet->next;
                extract_greet( ch, greet );
            }
        }
    }

    if ( ch->save_queued )
        ch->save_queued = FALSE;

    lua_triggers_extract_subject( &ch->first_trigger, 0 );
    lua_extract_delayed_triggers( ch, LUA_PARAM_CHAR );

    if ( ch->tmprog )
    {
        UNLINK( ch->tmprog, first_timeprog, last_timeprog, next, prev );
        DISPOSE( ch->tmprog );
    }

    if ( ch->tlprog )
    {
        UNLINK( ch->tlprog, first_timeprog, last_timeprog, next, prev );
        DISPOSE( ch->tlprog );
    }

    UNLINK( ch, first_char, last_char, next, prev );
    hashset_remove( valid_chars, ch );

    if ( !dump_mem_on_shutdown && IS_NPC( ch ) && ch->id > 0 )
    {
        delete_sql_row_by_id( "persistent_mobs", ch->id );
        ch->id = 0;
    }

    if ( ch->desc )
    {
        if ( ch->desc->character != ch )
            bug( "%s: char %s's descriptor points to another char", FUNC, IS_NPC( ch ) ? ch->short_descr : ch->name );
        else
        {
            ch->desc->character = NULL;

            // Handle fake descriptors with specialized cleanup
            if ( ch->desc->is_fake_desc )
            {
                destroy_fake_descriptor( ch->desc );
            }
            else
            {
                close_socket( ch->desc, FALSE );
            }

            ch->desc = NULL;
        }
    }

    return E_LOTJ_SUCCESS;
}


/*
    Find a char in the room.
*/
CHAR_DATA* get_char_room( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    int number = number_argument( argument, arg );

    // When dealing with a first-index argument ("personname" as opposed to "3.personname") we want
    // to prefer exact matches if any are available. Only if we find no exact match do we fall back to
    // prefix matching.
    if ( number == 1 )
    {
        if ( IS_NPC( ch ) )
        {
            // NPCs should always be able to safely refer to any character by name.
            CHAR_DATA* exact_match = get_char_room_exact( ch, argument );

            if ( exact_match )
                return exact_match;
        }
        else
        {
            for ( CHAR_DATA* rch = ch->in_room->last_person; rch; rch = rch->prev_in_room )
                if ( _char_matches_name( ch, rch, arg, nifty_is_name, false ) )
                    return rch;
        }
    }

    for ( CHAR_DATA* rch = ch->in_room->last_person; rch; rch = rch->prev_in_room )
    {
        if ( _char_matches_name( ch, rch, arg, nifty_is_name_prefix, false ) )
        {
            number--;

            if ( number == 0 )
                return rch;
        }
    }

    return NULL;
}

/*
    Find a char in the room by exact match only, ignoring the greet/dub system.
    Should be used by mobs or other special logic needing a match exclusively on target name
*/
CHAR_DATA* get_char_room_exact( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* rch;
    int number, count, vnum;
    number = number_argument( argument, arg );

    if ( !str_cmp( arg, "self" ) )
        return ch;

    if ( get_trust( ch ) >= LEVEL_SAVIOR && is_number( arg ) )
        vnum = atoi( arg );
    else
        vnum = -1;

    count  = 0;

    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        if ( can_see( ch, rch ) && ( ( ( IS_IMMORTAL( ch ) || !rch->disguise ) && nifty_is_name( arg, rch->name ) ) || ( rch->disguise && nifty_is_name( arg, rch->disguise->disgname ) ) || ( IS_NPC( rch ) && vnum == rch->pIndexData->vnum ) ) )
        {
            if ( number == 0 && !IS_NPC( rch ) )
                return rch;
            else if ( ++count == number )
                return rch;
        }

    return NULL;
}

// Returns true if the target is viewable to ch as the given name
// The name_match function parameter should be either nifty_is_name, for exact matching,
// or nifty_is_name_prefix, for partial match support.
bool _char_matches_name( CHAR_DATA* ch, CHAR_DATA* target, char* name, bool ( *name_match )( char*, char* ), bool see_through_restring )
{
    // Always match on self if target is the character
    if (
        ch == target &&
        ( !str_cmp( name, "self" ) || !str_cmp( name, ch->name ) )
    )
        return true;

    // Staff can match by vnum
    if (
        IS_IMMORTAL( ch ) &&
        IS_NPC( target ) &&
        atoi( name ) == target->pIndexData->vnum
    )
        return true;

    // RPC can match by names regardless of greet
    if ( IS_RPC( ch ) && ( name_match( name, target->name ) || ( target->disguise && name_match( name, target->disguise->disgname ) ) ) )
        return true;

    if ( !can_see( ch, target ) )
        return false;

    // Check for targets wearing covering restrung armor first.
    // This obscures all other match types if ch is not in target's clan
    if (
        !IS_NPC( target ) &&
        obj_mask( target )
    )
    {
        if ( name_match( name, get_mask( target ) ) )
            return true;

        // Players who aren't in the same clan can't use anything but the masked appearance to match.
        if ( ( !IS_NPC( ch ) || IS_CONTROLLED( ch ) ) && !same_clan( ch, target ) && !see_through_restring )
            return false;
    }

    GREET_DATA* greet = fetch_greet( ch, target );

    // ch knows target by a nickname or fake greet, and the argument matches that.
    if ( greet && !knows_player( ch, target, GREET_KNOWN, false ) && ( knows_player( ch, target, GREET_NICKNAME, false ) || knows_player( ch, target, GREET_FAKE, false ) )
    && ( name_match( name, greet->nickname ) ) )
        return true;

    if ( greet && knows_player( ch, target, GREET_KNOWN, false ) )
    {
        if ( name_match( name, greet->nickname ) )
            return true;

        if ( !target->disguise && name_match( name, greet->real_name ) )
            return true;

        if ( target->disguise && name_match( name, greet->real_disguise_name ) )
            return true;
    }

    // Match on either their name or race on its own
    if (
        !IS_NPC( target ) &&
        ch != target &&
        greet == NULL &&
        ( name_match( name, get_apparent_race( target ) ) || name_match( name, get_sex( target ) ) )
    )
        return true;

    // Standard keyword match on a known player or an NPC
    if ( ( IS_NPC( target ) || knows_player( ch, target, GREET_KNOWN, false ) ) && ( ( ( IS_IMMORTAL( ch ) || !target->disguise ) && name_match( name, target->name ) ) || ( target->disguise && name_match( name, target->disguise->disgname ) ) ) )
        return true;

    return false;
}

/*
    Find a char in the world.
*/
CHAR_DATA* get_char_world( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    int number = number_argument( argument, arg );

    if ( !str_cmp( arg, "self" ) )
        return ch;

    // Look in their own room first
    if ( ch->in_room )
    {
        for ( CHAR_DATA* rch = ch->in_room->last_person; rch; rch = rch->prev_in_room )
        {
            if ( _char_matches_name( ch, rch, arg, nifty_is_name, true ) )
            {
                number--;

                if ( number == 0 )
                    return rch;
            }
        }
    }

    for ( CHAR_DATA* wch = first_char; wch; wch = wch->next )
    {
        if ( wch->in_room == ch->in_room )
            continue;

        if ( _char_matches_name( ch, wch, arg, nifty_is_name, true ) )
        {
            number--;

            if ( number == 0 )
                return wch;
        }
    }

    return NULL;
}

CHAR_DATA* get_char_starsystem( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    int number = number_argument( argument, arg );

    if ( !str_cmp( arg, "self" ) )
        return ch;

    // Look in their own room first
    if ( ch->in_room )
    {
        for ( CHAR_DATA* rch = ch->in_room->last_person; rch; rch = rch->prev_in_room )
        {
            if ( _char_matches_name( ch, rch, arg, nifty_is_name, true ) )
            {
                number--;

                if ( number == 0 )
                    return rch;
            }
        }
    }

    SPACE_DATA* ch_starsystem = in_starsystem( ch );

    if ( ch_starsystem )
    {
        for ( CHAR_DATA* wch = first_char; wch; wch = wch->next )
        {
            if ( wch->in_room == ch->in_room )
                continue;

            if ( _char_matches_name( ch, wch, arg, nifty_is_name, true ) )
            {
                if ( in_starsystem( wch ) == ch_starsystem )
                {
                    number--;

                    if ( number == 0 )
                        return wch;
                }
            }
        }
    }

    return NULL;
}

/*
    Find a char in the world.
*/
CHAR_DATA* get_char_world_full( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    int number = number_argument( argument, arg );
    CHAR_DATA* wch;

    if ( !str_cmp( arg, "self" ) )
        return ch;

    /* check the room for an exact match */
    if ( ch->in_room )
    {
        for ( wch = ch->in_room->first_person; wch; wch = wch->next_in_room )
        {
            if ( _char_matches_name( ch, wch, arg, nifty_is_name, true ) || nifty_is_name( arg, wch->name ) )
            {
                number--;

                if ( number == 0 )
                    return wch;
            }
        }
    }

    /* check the world for an exact match */
    for ( wch = first_char; wch; wch = wch->next )
    {
        if ( _char_matches_name( ch, wch, arg, nifty_is_name, true ) || nifty_is_name( arg, wch->name ) )
        {
            number--;

            if ( number == 0 )
                return wch;
        }
    }

    return NULL;
}

CHAR_DATA* get_player_world( char* argument )
{
    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
        if ( d->connected == CON_PLAYING && d->character && !str_cmp( d->character->name, argument ) )
            return d->character;

    return NULL;
}

CHAR_DATA* get_player_room( ROOM_INDEX_DATA* room, const char* argument )
{
    if ( !room )
        return NULL;

    for ( CHAR_DATA* ch = room->first_person; ch; ch = ch->next_in_room )
        if ( ch->pcdata != NULL && !str_cmp( ch->name, argument ) )
            return ch;

    return NULL;
}

CHAR_DATA* player_from_id( int id )
{
    CHAR_DATA* result = NULL;

    if ( id <= 0 )
        return NULL;

    for ( result = first_char; result; result = result->next )
    {
        if ( IS_NPC( result ) )
            continue;

        if ( result->id == id )
            break;
    }

    return result;
}

/*
    Find some object with a given index data.
    Used by area-reset 'P', 'T' and 'H' commands.
*/
OBJ_DATA* get_obj_type( OBJ_INDEX_DATA* pObjIndex )
{
    OBJ_DATA* obj;

    for ( obj = last_object; obj; obj = obj->prev )
        if ( obj->pIndexData == pObjIndex )
            return obj;

    return NULL;
}


/*
    Find an obj in a list.
*/
OBJ_DATA* get_obj_list( CHAR_DATA* ch, char* argument, OBJ_DATA* list )
{
    char arg[MIL];
    OBJ_DATA* obj;
    int number;
    int count;
    number = number_argument( argument, arg );
    count  = 0;

    for ( obj = list; obj; obj = obj->next_content )
        if ( can_see_obj( ch, obj ) && nifty_is_name( arg, obj->name ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    /*  If we didn't find an exact match, run through the list of objects
        again looking for prefix matching, ie swo == sword.
        Added by Narn, Sept/96
    */
    count = 0;

    for ( obj = list; obj; obj = obj->next_content )
        if ( can_see_obj( ch, obj ) && nifty_is_name_prefix( arg, obj->name ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    return NULL;
}

/*
    Find an obj in a list...going the other way          -Thoric
*/
OBJ_DATA* get_obj_list_rev( CHAR_DATA* ch, char* argument, OBJ_DATA* list )
{
    char arg[MIL];
    OBJ_DATA* obj;
    int number;
    int count;
    number = number_argument( argument, arg );
    count  = 0;

    int vnum = -1;
    if ( get_trust( ch ) >= LEVEL_SAVIOR && is_number( arg ) )
        vnum = atoi( arg );

    for ( obj = list; obj; obj = obj->prev_content )
        if ( can_see_obj( ch, obj ) && ( nifty_is_name( arg, obj->name ) || obj->pIndexData->vnum == vnum ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    /*  If we didn't find an exact match, run through the list of objects
        again looking for prefix matching, ie swo == sword.
        Added by Narn, Sept/96
    */
    count = 0;

    for ( obj = list; obj; obj = obj->prev_content )
        if ( can_see_obj( ch, obj ) && ( nifty_is_name_prefix( arg, obj->name ) || obj->pIndexData->vnum == vnum ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    return NULL;
}



/*
    Find an obj in player's inventory.
*/
OBJ_DATA* get_obj_carry( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj;
    int number, count, vnum;

    if ( !argument )
        return NULL;

    number = number_argument( argument, arg );

    if ( get_trust( ch ) >= LEVEL_SAVIOR && is_number( arg ) )
        vnum = atoi( arg );
    else
        vnum = -1;

    count  = 0;

    for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->wear_loc == WEAR_NONE
                &&   can_see_obj( ch, obj )
                &&  ( nifty_is_name( arg, obj->name ) || obj->pIndexData->vnum == vnum ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    if ( vnum != -1 )
        return NULL;

    /*  If we didn't find an exact match, run through the list of objects
        again looking for prefix matching, ie swo == sword.
        Added by Narn, Sept/96
    */
    count = 0;

    for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->wear_loc == WEAR_NONE
                &&   can_see_obj( ch, obj )
                &&   nifty_is_name_prefix( arg, obj->name ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    return NULL;
}

// Returns the first object in the character's inventory of the given type.
OBJ_DATA* get_obj_in_inv_of_type( CHAR_DATA* ch, int type )
{
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->wear_loc == WEAR_NONE && obj->item_type == type )
