}

// Returns the first item on the character of the given type (inv or equip)
OBJ_DATA* get_obj_carried_of_type( CHAR_DATA* ch, int type )
{
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->item_type == type )
            return obj;
    return NULL;
}

/*
    Find an obj in player's equipment.
*/
OBJ_DATA* get_obj_wear( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj;
    int number, count, vnum;

    if ( !ch )
    {
        bug( "get_obj_wear: null ch" );
    }

    number = number_argument( argument, arg );

    if ( get_trust( ch ) >= LEVEL_SAVIOR && is_number( arg ) )
        vnum = atoi( arg );
    else
        vnum = -1;

    count  = 0;

    for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->wear_loc != WEAR_NONE
                /*  &&   can_see_obj( ch, obj )*/
                &&  ( nifty_is_name( arg, obj->name ) || obj->pIndexData->vnum == vnum ) )
            if ( ++count == number )
                return obj;

    if ( vnum != -1 )
        return NULL;

    /*  If we didn't find an exact match, run through the list of objects
        again looking for prefix matching, ie swo == sword.
        Added by Narn, Sept/96
    */
    count = 0;

    for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->wear_loc != WEAR_NONE
                &&   nifty_is_name_prefix( arg, obj->name ) )
            if ( ++count == number )
                return obj;

    return NULL;
}



/*
    Find an obj in the room or in inventory.
*/
OBJ_DATA* get_obj_here( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj;

    if ( !ch || !ch->in_room )
        return NULL;

    obj = get_obj_list_rev( ch, argument, ch->in_room->last_content );

    if ( obj )
        return obj;

    if ( ( obj = get_obj_carry( ch, argument ) ) != NULL )
        return obj;

    if ( ( obj = get_obj_wear( ch, argument ) ) != NULL )
        return obj;

    return NULL;
}



/*
    Find an obj in the world.
*/
OBJ_DATA* get_obj_world( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj;
    int number, count, vnum;

    if ( !ch )
        return NULL;

    if ( ( obj = get_obj_here( ch, argument ) ) != NULL )
        return obj;

    number = number_argument( argument, arg );

    /*
        Allow reference by vnum for saints+          -Thoric
    */
    if ( get_trust( ch ) >= LEVEL_SAVIOR && is_number( arg ) )
        vnum = atoi( arg );
    else
        vnum = -1;

    count  = 0;

    for ( obj = first_object; obj; obj = obj->next )
        if ( can_see_obj( ch, obj ) && ( nifty_is_name( arg, obj->name )
                                         ||   vnum == obj->pIndexData->vnum ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    /* bail out if looking for a vnum */
    if ( vnum != -1 )
        return NULL;

    /*  If we didn't find an exact match, run through the list of objects
        again looking for prefix matching, ie swo == sword.
        Added by Narn, Sept/96
    */
    count  = 0;

    for ( obj = first_object; obj; obj = obj->next )
        if ( can_see_obj( ch, obj ) && nifty_is_name_prefix( arg, obj->name ) )
            if ( ( count += obj->count ) >= number )
                return obj;

    return NULL;
}


/*
    How mental state could affect finding an object      -Thoric
    Used by get/drop/put/quaff/recite/etc
    Increasingly freaky based on mental state and drunkeness
*/
bool ms_find_obj( CHAR_DATA* ch )
{
    int ms = ch->mental_state;
    int drunk = IS_NPC( ch ) ? 0 : ch->pcdata->condition[COND_DRUNK];
    char* t;

    if ( ch->pcdata && has_pcflag( ch, PCFLAG_MPFORCED ) )
        return FALSE;

    /*
        we're going to be nice and let nothing weird happen unless
        you're a tad messed up
    */
    drunk = UMAX( 1, drunk );

    if ( abs( ms ) + ( drunk / 3 ) < 30 )
        return FALSE;

    if ( ( number_percent() + ( ms < 0 ? 15 : 5 ) ) > abs( ms ) / 2 + drunk / 4 )
        return FALSE;

    if ( ms > 15 )  /* range 1 to 20 */
        switch ( number_range( UMAX( 1, ( ms / 5 - 15 ) ), ( ms + 4 ) / 5 ) )
        {
            default:
            case  1:
                t = "As you reach for it, you forgot what it was...\n";
                break;

            case  2:
                t = "As you reach for it, something inside stops you...\n";
                break;

            case  3:
                t = "As you reach for it, it seems to move out of the way...\n";
                break;

            case  4:
                t = "You grab frantically for it, but can't seem to get a hold of it...\n";
                break;

            case  5:
                t = "It disappears as soon as you touch it!\n";
                break;

            case  6:
                t = "You would if it would stay still!\n";
                break;

            case  7:
                t = "Whoa!  It's covered in blood!  Ack!  Ick!\n";
                break;

            case  8:
                t = "Wow... trails!\n";
                break;

            case  9:
                t = "You reach for it, then notice the back of your hand is growing something!\n";
                break;

            case 10:
                t = "As you grasp it, it shatters into tiny shards which bite into your flesh!\n";
                break;

            case 11:
                t = "What about that huge dragon flying over your head?!?!?\n";
                break;

            case 12:
                t = "You scratch yourself instead...\n";
                break;

            case 13:
                t = "You hold the universe in the palm of your hand!\n";
                break;

            case 14:
                t = "You're too scared.\n";
                break;

            case 15:
                t = "Your mother smacks your hand... 'NO!'\n";
                break;

            case 16:
                t = "Your hand grasps the worse pile of revoltingness than you could ever imagine!\n";
                break;

            case 17:
                t = "You stop reaching for it as it screams out at you in pain!\n";
                break;

            case 18:
                t = "What about the millions of burrow-maggots feasting on your arm?!?!\n";
                break;

            case 19:
                t = "That doesn't matter any more... you've found the true answer to everything!\n";
                break;

            case 20:
                t = "A supreme entity has no need for that.\n";
                break;
        }
    else
    {
        int sub = URANGE( 1, abs( ms ) / 2 + drunk, 60 );

        switch ( number_range( 1, sub / 10 ) )
        {
            default:
            case  1:
                t = "In just a second...\n";
                break;

            case  2:
                t = "You can't find that...\n";
                break;

            case  3:
                t = "It's just beyond your grasp...\n";
                break;

            case  4:
                t = "...but it's under a pile of other stuff...\n";
                break;

            case  5:
                t = "You go to reach for it, but pick your nose instead.\n";
                break;

            case  6:
                t = "Which one?!?  I see two... no three...\n";
                break;
        }
    }

    send_to_char( t, ch );
    return TRUE;
}


/*
    Generic get obj function that supports optional containers.  -Thoric
    currently only used for "eat" and "quaff".
*/
OBJ_DATA* find_obj( CHAR_DATA* ch, char* argument, bool carryonly )
{
    char arg1[MIL];
    char arg2[MIL];
    OBJ_DATA* obj;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !str_cmp( arg2, "from" )
            &&   argument[0] != '\0' )
        argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg2 ) )
    {
        if ( carryonly && ( obj = get_obj_carry( ch, arg1 ) ) == NULL )
        {
            ch_println( ch, "You do not have that item." );
            return NULL;
        }
        else if ( !carryonly && ( obj = get_obj_here( ch, arg1 ) ) == NULL )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, arg1, TO_CHAR );
            return NULL;
        }

        return obj;
    }
    else
    {
        OBJ_DATA* container;

        if ( carryonly
                && ( container = get_obj_carry( ch, arg2 ) ) == NULL
                && ( container = get_obj_wear( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "You do not have that item." );
            return NULL;
        }

        if ( !carryonly && ( container = get_obj_here( ch, arg2 ) ) == NULL )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, arg2, TO_CHAR );
            return NULL;
        }

        if ( !IS_OBJ_STAT( container, ITEM_COVERING )
                &&    IS_SET( container->value[1], CONT_CLOSED ) )
        {
            act( AT_PLAIN, "The $d is closed.", ch, NULL, container->name, TO_CHAR );
            return NULL;
        }

        obj = get_obj_list( ch, arg1, container->first_content );

        if ( !obj )
            act( AT_PLAIN, IS_OBJ_STAT( container, ITEM_COVERING ) ?
                 "I see nothing like that beneath $p." :
                 "I see nothing like that in $p.",
                 ch, container, NULL, TO_CHAR );

        return obj;
    }

    return NULL;
}

int get_obj_number( OBJ_DATA* obj )
{
    if ( !obj )
        return 0;

    return count_obj_contents( obj );
}

/*
    Return weight of an object, including weight of contents.
*/
int get_obj_weight( OBJ_DATA* obj )
{
    OBJ_DATA* tObj = NULL;
    int weight = 0;

    if ( !obj )
        return 0;

    for ( tObj = obj->first_content; tObj; tObj = tObj->next_content )
        weight += get_obj_weight( tObj );

    weight += obj->weight * obj->count;

    return weight;
}

/*
    True if room is dark.
*/
bool room_is_dark(ROOM_INDEX_DATA* pRoomIndex) {
    if (!pRoomIndex) {
        bug("room_is_dark: NULL pRoomIndex", 0);
        return TRUE;
    }

    // Check conditions that could potentially make the room dark
    bool potentially_dark = xIS_SET(pRoomIndex->flags, ROOM_DARK) ||
                            (!xIS_SET(pRoomIndex->flags, ROOM_INDOORS) &&
                             !xIS_SET(pRoomIndex->flags, ROOM_SPACECRAFT) &&
                             !xIS_SET(pRoomIndex->flags, ROOM_UNDERGROUND) &&
                             !xIS_SET(pRoomIndex->flags, ROOM_LIT) &&
                             (time_info.hour < 6 || time_info.hour > 19));

    if (!potentially_dark) {
        // If none of the potentially dark conditions are met, the room is not dark
        return FALSE;
    }

    // If we are here, at least one potentially dark condition is true, so we need to check further

    if (pRoomIndex->light > 0) {
        return FALSE;
    }

    for (VEHICLE_DATA* vec = pRoomIndex->first_vehicle; vec; vec = vec->next_in_room) {
        if (xIS_SET(vec->flags, VEHICLE_LIGHTS_ON)) {
            return FALSE;
        }
    }

    for (SHIP_DATA* ship = pRoomIndex->first_ship; ship; ship = ship->next_in_room) {
        if (ship->shipstate == SHIP_HOVER || ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH) {
            return FALSE;
        }
    }

    for (CHAR_DATA* rch = pRoomIndex->first_person; rch; rch = rch->next_in_room) {
        OBJ_DATA* obj = get_eq_char(rch, WEAR_WIELD);
        if (obj && obj->value[3] == WEAPON_LIGHTSABER && obj->value[4] > 1) {
            return FALSE;
        }
    }

    if ( xIS_SET( pRoomIndex->flags, ROOM_DARK ) )
        return TRUE;

    if (xIS_SET(pRoomIndex->flags, ROOM_LIT) || xIS_SET(pRoomIndex->flags, ROOM_INDOORS) || xIS_SET(pRoomIndex->flags, ROOM_SPACECRAFT))
        return FALSE;

    if (pRoomIndex->sector_type == SECT_INSIDE || pRoomIndex->sector_type == SECT_CITY)
        return FALSE;

    // If none of the conditions that make the room not dark are met, the room is dark
    return TRUE;
}

/*
    If room is "do not disturb" return the pointer to the imm with dnd flag
