/*
    Returns TRUE if this room saves equipment  (Coded by Ghost)
*/
bool if_equip_room( ROOM_INDEX_DATA* room )
{
    if ( !room )
        return FALSE;

    if ( xIS_SET( room->flags, ROOM_SAVEEQ ) )
        return TRUE;

    return FALSE;
}

bool is_phome_resident( CHAR_DATA* ch, PHOME_DATA* phome )
{
    if ( !phome || !ch )
        return FALSE;

    for ( RESIDENT_DATA* resident = phome->first_resident; resident; resident = resident->next )
    {
        if ( resident->plr_id != ch->id )
            continue;

        return TRUE;
    }

    return FALSE;
}
/*
    True if room is private.
*/
bool room_is_private( CHAR_DATA* ch, ROOM_INDEX_DATA* pRoomIndex )
{
    CHAR_DATA* rch = NULL;
    int count;

    if ( !pRoomIndex )
    {
        bug( "%s: NULL pRoomIndex", FUNC );
        return FALSE;
    }

    if ( !ch )
        return TRUE;

    if ( pRoomIndex->phome && xIS_SET( pRoomIndex->flags, ROOM_PLR_HOME ) )
    {
        if ( pRoomIndex->phome->owner_id == ch->id )
            return FALSE;

        if ( is_phome_resident( ch, pRoomIndex->phome ) )
            return FALSE;

        if ( ch == warrant_char )
            return FALSE;

        return TRUE;
    }

    count = 0;

    for ( rch = pRoomIndex->first_person; rch; rch = rch->next_in_room )
        count++;

    if ( xIS_SET( pRoomIndex->flags, ROOM_PRIVATE ) && count >= 2 )
        return TRUE;

    return FALSE;
}

/*
    True if char can see victim.
*/
bool can_see( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !victim )
    {
        debug( "%s: null victim", FUNC );
        return FALSE;
    }

    if ( char_extracted( victim ) )
    {
        debug( "%s: victim died", FUNC );
        return FALSE;
    }

    if ( !ch || char_extracted( ch ) )
    {
        debug( "%s: %s ch, processing...", FUNC, ch ? "dead" : "null" );

        if ( IS_AFFECTED( victim, AFF_INVISIBLE )
                ||   IS_AFFECTED( victim, AFF_HIDE ) || leader_is_affected( victim, AFF_HIDE, SMUGGLING_ABILITY )
                ||   has_pcflag( victim, PCFLAG_WIZINVIS ) )
            return FALSE;
        else
            return TRUE;
    }

    bool ch_is_npc = IS_NPC( ch );
    bool victim_is_npc = IS_NPC( victim );
    sh_int trust = get_trust( ch );

    /* Always true for the supermob and for puff */
    if ( ch_is_npc && ch->pIndexData && ( ch->pIndexData->vnum == MOB_VNUM_SUPERMOB || ch->pIndexData->vnum == MOB_VNUM_PUFF ) )
        return TRUE;

    /* puff is invisible, period */
    if ( victim_is_npc && victim->pIndexData && ( victim->pIndexData->vnum == MOB_VNUM_PUFF ) )
        return FALSE;

    if ( !check_blind( ch, TRUE ) )
        return FALSE;

    if ( !check_smoke( ch, TRUE ) )
        return FALSE;

    if ( !victim_is_npc && has_pcflag( victim, PCFLAG_WIZINVIS ) && trust < victim->pcdata->wizinvis )
        return FALSE;

    if ( victim->spirit && !ch->spirit && !victim->manifest && trust < sysdata.log_level )
        return FALSE;

    if ( hidden_defel( victim ) )
    {
        if ( ch_is_npc )
            return FALSE;

        if ( !ch_is_npc && ch->skill_level[FORCE_ABILITY] > 10 ) /* Jedi see Defel */
            return TRUE;

        if ( xIS_SET( ch->race->flags, RFLAG_CANCAMO ) )
            return TRUE;

        if ( get_eq_char( ch, WEAR_EYES ) != NULL )
            return TRUE;

        return FALSE;
    }

    if ( trust <= LEVEL_HERO )
        if ( victim->position == POS_FIGHTING || victim->position < POS_SLEEPING )
            return TRUE;

    if ( victim->position == POS_FIGHTING || victim->position < POS_SLEEPING )
        return TRUE;

    if ( victim->position == POS_FIGHTING || victim->position < POS_SLEEPING )
        return TRUE;

    /* SB */
    if ( victim_is_npc
            &&   xIS_SET( victim->act, ACT_MOBINVIS )
            &&   trust < victim->mobinvis )
        return FALSE;

    if ( trust < LEVEL_IMMORTAL && !victim_is_npc && !victim->desc
            &&    get_timer( victim, TIMER_RECENTPVP ) > 0
            &&  ( !victim->switched || !IS_AFFECTED( victim->switched, AFF_POSSESS ) ) )
        return FALSE;

    if ( !ch_is_npc && has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
        return TRUE;

    /* The miracle cure for blindness? -- Altrag */
    if ( !IS_AFFECTED( ch, AFF_TRUESIGHT ) )
    {
        int spot = 0;

        if ( room_is_dark( ch->in_room ) )
            if ( !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) && ( ch != victim || !IS_AFFECTED( ch, AFF_INFRARED ) ) )
                return FALSE;

        if ( ch == victim )
            return TRUE;

        int perception = 0;

        if ( IS_AFFECTED( victim, AFF_INVISIBLE ) )
        {
            spot = victim->top_level;
            perception = ( int ) ch->perm_int;
            spot = URANGE( 0, spot - perception, 100 );
            tune ( "can_see: Spot %d - %s looking at %s, %d for %s's int.", spot, ch->name, victim->name, ( get_curr_int( ch ) * 2 ), ch->name );

            if ( IS_AFFECTED( ch, AFF_DETECT_INVIS ) )
                spot = URANGE( 20, spot - perception * 2, 100 );

            if ( number_percent() < spot )
                return FALSE;
        }

        if ( IS_AFFECTED( victim, AFF_HIDE ) || leader_is_affected( victim, AFF_HIDE, SMUGGLING_ABILITY ) )
        {
            spot = victim_is_npc ? victim->top_level : ( int ) get_learned_pct( victim, cache_skill( "hide", &skill_hide ) );

            if ( IS_AFFECTED( ch, AFF_DETECT_HIDDEN ) )
                spot = URANGE( 20, spot - ( ( int )( spot * 0.45 ) ), 100 );

            if ( number_percent() < spot )
                return FALSE;
        }
    }

    return TRUE;
}

// True if char can see what's around them (room exits, etc)
bool can_see_surroundings( CHAR_DATA* ch )
{
    if ( !ch || !ch->in_room )
        return TRUE;

    if ( get_trust( ch ) >= LEVEL_PR )
        return TRUE;

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
        return TRUE;

    if ( !check_blind( ch, TRUE ) )
        return FALSE;

    if ( !check_smoke( ch, TRUE ) )
        return FALSE;

    if ( IS_AFFECTED( ch, AFF_TRUESIGHT ) )
        return TRUE;

    if ( room_is_dark( ch->in_room ) && !IS_AFFECTED( ch, AFF_INFRARED ) && !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) )
        return FALSE;

    return TRUE;
}

/*
    True if char can see obj.
*/
bool can_see_obj( CHAR_DATA* ch, OBJ_DATA* obj )
{
    if ( obj == NULL )
        return FALSE;

    // If doing this anonymously, we can see all objects
    if ( ch == NULL )
        return TRUE;

    if ( get_trust( ch ) >= LEVEL_PR )
        return TRUE;

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
        return TRUE;

    if ( IS_OBJ_STAT( obj, ITEM_CONCEAL ) )
        return FALSE;

    if ( IS_OBJ_STAT( obj, ITEM_BURIED ) )
        // Minesweepers can see active mines.
        if ( !( obj->item_type == ITEM_LANDMINE && has_feat( ch, cache_skill( "minesweeper", &skill_minesweeper ) ) ) )
            return FALSE;

    if ( !check_blind( ch, TRUE ) )
        return FALSE;

    if ( !check_smoke( ch, TRUE ) )
        return FALSE;

    if ( IS_AFFECTED( ch, AFF_TRUESIGHT ) )
        return TRUE;

    if ( IS_OBJ_STAT( obj, ITEM_HIDDEN ) )
    {
        int chance = 0;
        chance = URANGE( 0, IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "sharp eye", &skill_sharp_eye ) ), 100 );

        if ( chance < 100 )
            chance = URANGE( 1, chance - 40, 100 );

        if ( number_percent() < chance )
        {
            learn_from_success( ch, cache_skill( "sharp eye", &skill_sharp_eye ) );
            return TRUE;
        }

        return FALSE;
    }

    if ( obj->item_type == ITEM_LIGHT && obj->value[2] != 0 && IS_SET( obj->value[3], 1 << 0 ) )
        return TRUE;

    if ( ch->in_room )
        if ( room_is_dark( ch->in_room ) && !IS_AFFECTED( ch, AFF_INFRARED ) && !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) && !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) )
            return FALSE;

    if ( IS_OBJ_STAT( obj, ITEM_INVIS ) && !IS_AFFECTED( ch, AFF_DETECT_INVIS ) )
        return FALSE;

    return TRUE;
}

/*
    True if char can drop obj.
*/
bool can_drop_obj( CHAR_DATA* ch, OBJ_DATA* obj )
{
    if ( xIS_SET( ch->act, ACT_FORCED ) )
        return TRUE;

    /* Seems logical */
    if ( !can_see_obj( ch, obj ) )
        return FALSE;

    if ( !IS_OBJ_STAT( obj, ITEM_NODROP ) )
        return TRUE;

    if ( !IS_NPC( ch ) && get_trust( ch ) >= LEVEL_IMMORTAL )
        return TRUE;

    if ( IS_NPC( ch ) && ch->pIndexData->vnum == 3 )
        return TRUE;

    return FALSE;
}

/*
    Return ascii name of an item type.
*/
const char* item_type_name( OBJ_DATA* obj )
{
    const FLAG_INFO* flag = NULL;

    if ( !valid_obj( obj ) )
        return "(unknown)";

    if ( obj->item_type <= 0 )
    {
        bug( "Item_type_name: unknown type %d.", obj->item_type );
        return "(unknown)";
    }

    flag = flag_from_num( obj_types, obj->item_type );

    if ( xIS_SET( obj->extra_flags, ITEM_CLOTHING ) )
        return "clothing";
    else if ( !flag )
        return "(unknown)";
    else
        return flag->name;
}

/*
    Return ascii name of an affect location.
*/
char* affect_loc_name( int location )
{
    if ( location >= 0 && location < MAX_APPLY_TYPE )
        return a_types[location];

    bug( "Affect_location_name: unknown location %d.", location );
    return "(unknown)";
}

/*
    Set off a trap (obj) upon character (ch)         -Thoric
*/
ch_ret spring_trap( CHAR_DATA* ch, OBJ_DATA* obj )
{
    int dam;
    int typ;
    int lev;
    char* txt;
    char buf[MSL];
    ch_ret retcode;
    typ = obj->value[1];
    lev = obj->value[2];
    retcode = rNONE;

    switch ( typ )
    {
        default:
            txt = "hit by a trap";
            break;

        case TRAP_TYPE_POISON_GAS:
            txt = "surrounded by a green cloud of gas";
            break;

        case TRAP_TYPE_POISON_DART:
            txt = "hit by a dart";
            break;

        case TRAP_TYPE_POISON_NEEDLE:
            txt = "pricked by a needle";
            break;

        case TRAP_TYPE_POISON_DAGGER:
            txt = "stabbed by a dagger";
            break;

        case TRAP_TYPE_POISON_ARROW:
            txt = "struck with an arrow";
            break;

        case TRAP_TYPE_BLINDNESS_GAS:
            txt = "surrounded by a red cloud of gas";
            break;

        case TRAP_TYPE_SLEEPING_GAS:
            txt = "surrounded by a yellow cloud of gas";
            break;

        case TRAP_TYPE_FLAME:
            txt = "struck by a burst of flame";
            break;

        case TRAP_TYPE_EXPLOSION:
            txt = "hit by an explosion";
            break;

        case TRAP_TYPE_ACID_SPRAY:
            txt = "covered by a spray of acid";
            break;

        case TRAP_TYPE_ELECTRIC_SHOCK:
            txt = "suddenly shocked";
            break;

        case TRAP_TYPE_BLADE:
            txt = "sliced by a razor sharp blade";
            break;

        case TRAP_TYPE_SEX_CHANGE:
            txt = "surrounded by a mysterious aura";
            break;
    }

    dam = number_range( obj->value[2], obj->value[2] * 2 );
    snprintf( buf, MSL, "You are %s!", txt );
    act( AT_HITME, buf, ch, NULL, NULL, TO_CHAR );
    snprintf( buf, MSL, "$n is %s.", txt );
    act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
    --obj->value[0];

    if ( obj->value[0] <= 0 )
        extract_obj( obj );

    switch ( typ )
    {
        default:
        case TRAP_TYPE_POISON_DART:
        case TRAP_TYPE_POISON_NEEDLE:
        case TRAP_TYPE_POISON_DAGGER:
        case TRAP_TYPE_POISON_ARROW:
            /* hmm... why not use spell_poison() here? */
            retcode = obj_cast_spell( cache_skill( "poison", &skill_poison ), lev, ch, ch->name, NULL );

            if ( retcode == rNONE )
                retcode = damage( ch, ch, dam, TYPE_UNDEFINED );

            break;

        case TRAP_TYPE_POISON_GAS:
            retcode = obj_cast_spell( cache_skill( "poison", &skill_poison ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_BLINDNESS_GAS:
            retcode = obj_cast_spell( cache_skill( "blindness", &skill_blindness ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_SLEEPING_GAS:
            retcode = obj_cast_spell( cache_skill( "sleep", &skill_sleep ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_ACID_SPRAY:
            retcode = obj_cast_spell( cache_skill( "acid blast", &skill_acid_blast ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_SEX_CHANGE:
            retcode = obj_cast_spell( cache_skill( "change sex", &skill_change_sex ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_FLAME:
        case TRAP_TYPE_EXPLOSION:
            retcode = obj_cast_spell( cache_skill( "fireball", &skill_fireball ), lev, ch, ch->name, NULL );
            break;

        case TRAP_TYPE_ELECTRIC_SHOCK:
        case TRAP_TYPE_BLADE:
            retcode = damage( ch, ch, dam, TYPE_UNDEFINED );
    }

    return retcode;
}

/*
    Check an object for a trap                   -Thoric
*/
ch_ret check_for_trap( CHAR_DATA* ch, OBJ_DATA* obj, int flag )
{
    OBJ_DATA* check;
    ch_ret    retcode;

    if ( !obj->first_content )
        return rNONE;

    retcode = rNONE;

    for ( check = obj->first_content; check; check = check->next_content )
        if ( check->item_type == ITEM_TRAP
                &&   IS_SET( check->value[3], flag ) )
        {
            retcode = spring_trap( ch, check );

            if ( retcode != rNONE )
                return retcode;
        }

    return retcode;
}

/*
    Check the room for a trap                    -Thoric
*/
ch_ret check_room_for_traps( CHAR_DATA* ch, int flag )
{
    OBJ_DATA* check;
    ch_ret    retcode;
    retcode = rNONE;

    if ( !ch )
        return rERROR;

    if ( !ch->in_room || !ch->in_room->first_content )
        return rNONE;

    for ( check = ch->in_room->first_content; check; check = check->next_content )
    {
        //Ralen - do not explode landmine if you're nowhere near the ground.
        if ( check->item_type == ITEM_LANDMINE && IS_OBJ_STAT( check, ITEM_BURIED ) )
        {
            if ( flag == TRAP_ENTER_ROOM )
            {
                // Don't trigger mines while force-jumping, jetpacking, etc.
                // If you walked in normally, then triggered it, then did force jump to try to avoid
                // it, it'll still go off - no flying check in the on-leave block.
                if ( IS_AFFECTED( ch, AFF_FLYING ) )
                    continue;

                if ( has_feat ( ch, cache_skill( "minesweeper", &skill_minesweeper ) ) )
                {
                    ch_println( ch, "&RWhoa! You notice a live landmine on the ground, and carefully step around it." );
                    continue;
                }

                lognormal( "%s triggered a landmine in room %d", ch->name, ch->in_room->vnum );
                echo_to_room( AT_YELLOW, ch->in_room, "You hear a soft *click* followed by an unsettling whirring noise." );

                // 20 minutes until it goes off on its own
                check->value[4] = (20*60*PULSE_PER_SECOND)/PULSE_DOUBLE;
            }
            else if ( flag == TRAP_LEAVE_ROOM && !ch->carried ) // If someone is carried, the carrier is who we check.
            {
                // Mine has been armed.
                if ( check->value[4] > 0 )
                {
                    if ( has_feat ( ch, cache_skill( "minesweeper", &skill_minesweeper ) ) )
                    {
                        ch_println( ch, "&RWhoa! You notice a live landmine on the ground, and carefully step around it." );
                        continue;
                    }

                    ch_println( ch, "&RYou set off a landmine!" );
                    explode_obj( check );
                    // Only one mine can go off at once.
                    return rNONE;
                }
            }
        }
        else if ( check->item_type == ITEM_TRAP && IS_SET( check->value[3], flag ) )
        {
            retcode = spring_trap( ch, check );

            if ( retcode != rNONE )
                return retcode;
        }
    }

    return retcode;
}

/*
    return TRUE if an object contains a trap         -Thoric
*/
bool is_trapped( OBJ_DATA* obj )
{
    OBJ_DATA* check;

    if ( !obj->first_content )
        return FALSE;

    for ( check = obj->first_content; check; check = check->next_content )
        if ( check->item_type == ITEM_TRAP )
            return TRUE;

    return FALSE;
}

/*
    If an object contains a trap, return the pointer to the trap -Thoric
*/
OBJ_DATA* get_trap( OBJ_DATA* obj )
{
    OBJ_DATA* check;

    if ( !obj->first_content )
        return NULL;

    for ( check = obj->first_content; check; check = check->next_content )
        if ( check->item_type == ITEM_TRAP )
            return check;

    return NULL;
}

/*
    Remove an exit from a room                   -Thoric
*/
int extract_exit( ROOM_INDEX_DATA* room, EXIT_DATA* pexit )
{
    if ( !room || !pexit )
        return E_LOTJ_MISSING_ARGUMENTS;

    for ( CHAR_DATA* ch = room->first_person; ch != NULL; ch = ch->next_in_room )
    {
        if ( ch->block == pexit )
        {
            ch_println( ch, "The exit you are blocking suddenly vanishes!" );
            ch->block = NULL;
            action_clear_ex( ch, AS_UNLOCK );
        }
    }

    for ( RESET_DATA* reset = room->first_reset; reset; reset = reset->next )
        if ( reset->exit == pexit )
            reset->exit = NULL;

    UNLINK( pexit, room->first_exit, room->last_exit, next, prev );

    if ( pexit->rexit )
        pexit->rexit->rexit = NULL;

    FREE_STRUCT( pexit, exit_fields );
    save_room( room, true );
    top_exit--;
    return E_LOTJ_SUCCESS;
}

/*
    "Fix" a character's stats                    -Thoric
*/
void fix_char( CHAR_DATA* ch )
{
    if (!ch->race) {
        ch->race = get_race_by_id(1); //reset to human if race is null
    }
    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
        if ( obj->wear_loc != WEAR_NONE )
            unapply_equip_stats( ch, obj );

    de_cyber_char( ch );

    for ( AFFECT_DATA* aff = ch->first_affect; aff; aff = aff->next )
        affect_modify( ch, CHAR_AFFECT, aff, FALSE );

    ch->affected_by = ch->race->affected;
    ch->mental_state    = 0;
    ch->hit             = UMAX( 1, ch->hit   );
    ch->max_mana    = get_max_mana( ch );
    ch->mana            = UMAX( 1, ch->mana  );
    ch->move            = UMAX( 1, ch->move  );
    ch->armor       = 100;
    ch->mod_str     = 0;
    ch->mod_dex     = 0;
    ch->mod_wis     = 0;
    ch->mod_int     = 0;
    ch->mod_con     = 0;
    ch->mod_cha     = 0;
    ch->mod_lck     = 0;
    ch->damroll     = 0;
    ch->hitroll     = 0;
    ch->alignment   = URANGE( -1000, ch->alignment, 1000 );
    ch->saving_breath   = 0;
    ch->saving_wand = 0;
    ch->saving_para_petri = 0;
    ch->saving_spell_staff = 0;
    ch->saving_poison_death = 0;
    ch->carry_weight    = 0;
    ch->carry_number    = 0;

    for ( AFFECT_DATA* aff = ch->first_affect; aff; aff = aff->next )
        affect_modify( ch, CHAR_AFFECT, aff, TRUE );

    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
    {
        ch->carry_weight += get_obj_weight( obj );
        if ( obj->wear_loc != WEAR_NONE )
            apply_equip_stats( ch, obj );
        else
            ch->carry_number += get_obj_number( obj );
    }

    re_cyber_char( ch );

    ch->max_mana = get_max_mana( ch );
    if ( ch->mana > ch->max_mana )
        ch->mana = ch->max_mana;
}


/*
    Show an affect verbosely to a character          -Thoric
*/
void showaffect( CHAR_DATA* ch, AFFECT_DATA* paf )
{
    char buf[MSL];
    strlcpy( buf, "", MSL );
    int x;

    if ( !paf )
    {
        bug( "showaffect: NULL paf", 0 );
        return;
    }

    if ( paf->location != APPLY_NONE )
    {
        switch ( paf->location )
        {
            default:
                snprintf( buf, MSL, "&zAffects &C%s&z by &C%d.\n", affect_loc_name( paf->location ), paf->modifier );
                break;

            case APPLY_AFFECT:
                snprintf( buf, MSL, "&zAffects &C%s&z by",
                         affect_loc_name( paf->location ) );

                for ( x = 0; affect_flags[x].flag != LAST_FLAG_VALUE; x++ )
                    if ( xIS_SET( paf->bitvector, affect_flags[x].flag ) )
                    {
                        strlcat( buf, "&C ", MSL );
                        strlcat( buf, affect_flags[x].name, MSL );
                    }

                strlcat( buf, "\n", MSL );
                break;

            case APPLY_WEAPONSPELL:
            case APPLY_WEARSPELL:
            case APPLY_REMOVESPELL:
                SKILL_DATA* skill = skill_from_id( paf->modifier );
                snprintf( buf, MSL, "Casts spell '%s'\n", skill ? skill->name : "unknown" );
                break;

            case APPLY_RESISTANT:
            case APPLY_IMMUNE:
            case APPLY_SUSCEPTIBLE:
                snprintf( buf, MSL, "&zAffects &C%s&z by &C%s\n",
                    affect_loc_name( paf->location ),
                    flag_value_name( resistant_types, paf->modifier )
                );
                break;
        }

        send_to_char( buf, ch );
    }
}

bool ch_affected_by( CHAR_DATA* ch, AFFECT_DATA* aff )
{
    if ( !ch || !aff )
        return false;

    AFFECT_DATA* aff2 = NULL;
    for ( aff2 = ch->first_affect; aff2; aff2 = aff2->next )
        if ( aff2 == aff )
            return true;

    return false;
}

