        return NULL;

    return ref.ch;
}

CHAR_REF char_to_ref( CHAR_DATA* ch )
{
    CHAR_REF ref;

    ref.ch = NULL;
    ref.sid = 0;

    if ( valid_char( ch ) )
    {
        ref.ch = ch;
        ref.sid = ch->sid;
    }

    return ref;
}

/*
    Memory appearing in structures sucks. To counter that, for characters, this function
    checks the linked list made when all _valid_ characters are created. Return false
    if no match can be made.
*/
bool valid_obj( OBJ_DATA* obj )
{
    if ( !obj )
        return FALSE;

    return hashset_contains( valid_objs, obj );
}

OBJ_DATA* obj_from_ref( OBJ_REF ref )
