int interrupt_ch( CHAR_DATA* victim )
{
    if ( !victim || char_extracted( victim ) )
    {
        debug( "%s: null victim", FUNC );
        return rNONE;
    }
    TIMER* timer = get_timerptr( victim, TIMER_DO_FUN );
    if ( !timer || timer->uninterruptible )
        return rNONE;

    if ( timer->on_abort )
        (timer->on_abort)( victim, timer->buffer );

    int retcode = rNONE;
    if ( char_extracted( victim ) )
    {
        victim = NULL; // So extract_timer doesn't fuss with invalid ch
        retcode = rVICT_DIED;
    }
    else
    {
        action_clear_ex( victim, AS_UNLOCK );
        extract_timer( victim, timer );
        // Regroup objects which were separated for use in the timer.
        group_ch_objects( victim );
    }

    return retcode;
}

/*
    Add a timer to ch                        -Thoric
    Support for "call back" time delayed commands

    This has been rewritten to work with BUFFER_DATA as a way to pass state to callbacks.
    There's no need to manage timer state in your callbacks. Simply run the logic you want
    based on the buffer contents.

    Some buffer contents are pre-validated so you don't have to check them yourself.
    For example, your on_complete code will not run if any objects in the buffer are no longer where they started.
    If on_complete returns any code other than E_LOTJ_SUCCESS, consumable objects in the buffer are not extracted.

    To extend a timer in its on_complete code, you can call add_timer again with the same on_complete function.
    This will reuse all other existing buffer data.
*/
TIMER* add_timer( CHAR_DATA* ch, sh_int type, sh_int seconds, ASYNC_FUN* on_complete, ASYNC_FUN* on_abort, const char* func_name )
{
    if ( get_trust( ch ) >= LEVEL_IMMORTAL && type == TIMER_DO_FUN )
        seconds = 1;

    TIMER* timer;
    for ( timer = ch->first_timer; timer; timer = timer->next )
        if ( timer->type == type && timer->on_complete == on_complete )
        {
            debug( "Updating existing timer on %s", ch->name );
            timer->seconds = seconds;
            timer->on_complete = on_complete;
            timer->on_abort = on_abort;
            timer->on_damage_interrupt = true;
            timer->comms_interrupt = true;
            break;
        }

    if ( !timer )
    {
        CREATE( timer, TIMER, 1 );
        timer->type = type;
        timer->seconds = seconds;
        timer->on_complete = on_complete;
        timer->on_abort = on_abort;
        timer->on_damage_interrupt = true;
        timer->comms_interrupt = true;
        timer->uninterruptible = false;
        timer->buffer = create_buffer( ch, func_name );
        LINK( timer, ch->first_timer, ch->last_timer, next, prev );
    }

    return timer;
}

TIMER* get_timerptr( CHAR_DATA* ch, sh_int type )
{
    TIMER* timer;

    for ( timer = ch->first_timer; timer; timer = timer->next )
        if ( timer->type == type )
            return timer;

    return NULL;
}

sh_int get_timer( CHAR_DATA* ch, sh_int type )
{
    TIMER* timer;

    if ( ( timer = get_timerptr( ch, type ) ) != NULL )
        return timer->seconds;
    else
        return 0;
}

void extract_timer( CHAR_DATA* ch, TIMER* timer )
{
    if ( !timer )
    {
        bug( "extract_timer: NULL timer", 0 );
        return;
    }

    if ( ch )
        UNLINK( timer, ch->first_timer, ch->last_timer, next, prev );

    if ( timer->buffer )
    {
        dispose_buffer( timer->buffer );
        timer->buffer = NULL;
    }
    DISPOSE( timer );
    return;
}

void remove_timer( CHAR_DATA* ch, sh_int type )
{
    TIMER* timer;

    for ( timer = ch->first_timer; timer; timer = timer->next )
        if ( timer->type == type )
            break;

    if ( timer )
        extract_timer( ch, timer );
}

void timers_update( void )
{
    TIMER* timer, *timer_next;
    CHAR_DATA* ch_prev;
    for ( CHAR_DATA* ch = last_char; ch; ch = ch_prev )
    {
        ch_prev = ch->prev;
        set_cur_char( ch );
        for ( timer = ch->first_timer; timer; timer = timer_next )
        {
            // This block is necessary because there are cases where both the current and next timer might be
            // extracted during this iteration of the loop. (Suppose some code in processing the timer causes
            // another timer to be removed)
            bool valid = false;
            for ( TIMER* timer_check = ch->first_timer; timer_check; timer_check = timer_check->next )
                if ( timer_check == timer )
                    valid = true;
            if ( !valid )
                break;

            timer_next = timer->next;
            if ( --timer->seconds <= 0 )
            {
                if ( timer->type == TIMER_DO_FUN )
                {
                    bool orig_uninterruptible = timer->uninterruptible;
                    timer->uninterruptible = true; // Ensure actions taken while resolving this timer don't interrupt itself.
                    if ( validate_buffer_targets( timer->buffer, ch ) )
                    {
                        if ( (timer->on_complete)( ch, timer->buffer ) == E_LOTJ_SUCCESS )
                            extract_buffer_consumables( timer->buffer );

                        if ( char_extracted( ch ) )
                            ch = NULL;

                        timer->uninterruptible = orig_uninterruptible;
                    }
                }

                // If the timer was re-upped in the process of completing the function, don't extract it.
                if ( !ch || char_extracted( ch ) )
                {
                    break;
                }
                else if ( timer->seconds <= 0 )
                {
                    action_clear_ex( ch, AS_UNLOCK );
                    extract_timer( ch, timer );

                    // Regroup objects which were separated for use in the timer.
                    group_ch_objects( ch );
                }
            }
        }
    }
}

bool is_busy( CHAR_DATA* ch )
{
    return get_timerptr( ch, TIMER_DO_FUN ) != NULL || ch->is_lua_busy;
}

/*
    Scryn, standard luck check 2/2/96
*/
bool chance( CHAR_DATA* ch, sh_int percent )
{
    /*  sh_int clan_factor, ms;*/
    sh_int deity_factor, ms;

    if ( !ch )
    {
        bug( "Chance: null ch!", 0 );
        return FALSE;
    }

    /*  Code for clan stuff put in by Narn, Feb/96.  The idea is to punish clan
        members who don't keep their alignment in tune with that of their clan by
        making it harder for them to succeed at pretty much everything.  Clan_factor
        will vary from 1 to 3, with 1 meaning there is no effect on the player's
        change of success, and with 3 meaning they have half the chance of doing
        whatever they're trying to do.

        Note that since the neutral clannies can only be off by 1000 points, their
        maximum penalty will only be half that of the other clan types.

        if ( IS_CLANNED( ch ) )
        clan_factor = 1 + abs( ch->alignment - ch->pcdata->clan->alignment ) / 1000;
        else
        clan_factor = 1;
    */
    /*  Mental state bonus/penalty:  Your mental state is a ranged value with
        zero (0) being at a perfect mental state (bonus of 10).
        negative values would reflect how sedated one is, and
        positive values would reflect how stimulated one is.
        In most circumstances you'd do best at a perfectly balanced state.
    */
    deity_factor = 0;
    ms = 10 - abs( ch->mental_state );

    if ( ( number_percent() - get_curr_lck( ch ) + 13 - ms ) + deity_factor <=
            percent )
        return TRUE;
    else
        return FALSE;
}

bool chance_attrib( CHAR_DATA* ch, sh_int percent, sh_int attrib )
{
    /* Scryn, standard luck check + consideration of 1 attrib 2/2/96*/
    sh_int  deity_factor;

    if ( !ch )
    {
        bug( "Chance: null ch!", 0 );
        return FALSE;
    }

    deity_factor = 0;

    if ( number_percent() - get_curr_lck( ch ) + 13 - attrib + 13 + deity_factor <= percent )
        return TRUE;
    else
        return FALSE;
}

/*
    Make a simple clone of an object (no extras...yet)       -Thoric
*/
OBJ_DATA* clone_object( OBJ_DATA* obj )
{
    OBJ_DATA* clone;
    EXTRA_DESCR_DATA* desc_clone;
    AFFECT_DATA* aff_clone;
    CREATE( clone, OBJ_DATA, 1 );
    clone->pIndexData   = obj->pIndexData;
    SET_STRING( clone->name, obj->name );
    SET_STRING( clone->short_descr, obj->short_descr );
    SET_STRING( clone->description, obj->description );
    SET_STRING( clone->action_desc, obj->action_desc );
    SET_STRING( clone->obj_clan, obj->obj_clan );
    SET_STRING( clone->blueprint, obj->blueprint );
    SET_STRING( clone->cybertype, obj->cybertype );
    clone->item_type    = obj->item_type;
    clone->extra_flags  = obj->extra_flags;
    clone->magic_flags  = obj->magic_flags;
    clone->wear_flags   = obj->wear_flags;
    clone->wear_loc = obj->wear_loc;
    clone->weight   = obj->weight;
    clone->cost     = obj->cost;
    clone->level        = obj->level;
    clone->timer    = obj->timer;
    clone->value[0] = obj->value[0];
    clone->value[1] = obj->value[1];
    clone->value[2] = obj->value[2];
    clone->value[3] = obj->value[3];
    clone->value[4] = obj->value[4];
    clone->value[5] = obj->value[5];
    clone->blaster_setting = obj->blaster_setting;
    CREATE( clone->variable, VARIABLE_DATA, 1 );
    SET_STRING( clone->variable->v1, obj->variable->v1 ? obj->variable->v1 : "Unset" );
    SET_STRING( clone->variable->v2, obj->variable->v2 ? obj->variable->v2 : "Unset" );
    SET_STRING( clone->variable->v3, obj->variable->v3 ? obj->variable->v3 : "Unset" );
    SET_STRING( clone->variable->v4, obj->variable->v4 ? obj->variable->v4 : "Unset" );
    SET_STRING( clone->variable->v5, obj->variable->v5 ? obj->variable->v5 : "Unset" );
    CREATE( clone->vars, DVAR_LIST, 1 );
    copy_dvars( clone->vars, obj->vars );

    for ( EXTRA_DESCR_DATA* desc = obj->first_extradesc; desc; desc = desc->next )
    {
        CREATE( desc_clone, EXTRA_DESCR_DATA, 1 );

        if ( !NULLSTR( desc->keyword ) )
            SET_STRING( desc_clone->keyword, desc->keyword );

        if ( !NULLSTR( desc->description ) )
            SET_STRING( desc_clone->description, desc->description );

        if ( !NULLSTR( desc->spec_funname ) )
            SET_STRING( desc_clone->spec_funname, desc->spec_funname );

        LINK( desc_clone, clone->first_extradesc, clone->last_extradesc, next, prev );
    }

    for ( AFFECT_DATA* aff = obj->first_affect; aff; aff = aff->next )
    {
        CREATE( aff_clone, AFFECT_DATA, 1 );
        aff_clone->type = aff->type;
        aff_clone->duration = aff->duration;
        aff_clone->location = aff->location;
        aff_clone->modifier = aff->modifier;
        xSET_BITS( aff_clone->bitvector, aff->bitvector );
        LINK( aff_clone, clone->first_affect, clone->last_affect, next, prev );
    }

    if ( clone->item_type == ITEM_TRANSMITTER && clone->value[IVAL_TRANSMITTER_STATE] == 1 )
        transmit_join_channel( obj );

    clone->count    = 1;
    ++obj->pIndexData->count;
    ++numobjsloaded;
    ++physicalobjects;
    cur_obj_serial = UMAX( ( cur_obj_serial + 1 ) & ( BV30 - 1 ), 1 );
    clone->serial = clone->pIndexData->serial = cur_obj_serial;
    LINK( clone, first_object, last_object, next, prev );
    hashset_add( valid_objs, clone );
    return clone;
}

bool extra_descs_equal( OBJ_DATA* obj1, OBJ_DATA* obj2 )
{
    EXTRA_DESCR_DATA* obj1desc = NULL;
    EXTRA_DESCR_DATA* obj2desc = NULL;

    if ( obj1 )
        obj1desc = obj1->first_extradesc;

    if ( obj2 )
        obj2desc = obj2->first_extradesc;

    while ( obj1desc || obj2desc )
    {
        if ( obj1desc && !obj2desc )
            return false;

        if ( !obj1desc && obj2desc )
            return false;

        if ( !NULLSTR( obj1desc->keyword ) && !NULLSTR( obj2desc->keyword ) &&
                strcmp( obj1desc->keyword, obj2desc->keyword ) )
            return false;

        if ( !NULLSTR( obj1desc->description ) && !NULLSTR( obj2desc->description ) &&
                strcmp( obj1desc->description, obj2desc->description ) )
            return false;

        if ( !NULLSTR( obj1desc->spec_funname ) && !NULLSTR( obj2desc->spec_funname ) &&
                strcmp( obj1desc->spec_funname, obj2desc->spec_funname ) )
            return false;

        obj1desc = obj1desc->next;
        obj2desc = obj2desc->next;
    }

    return true;
}

bool affects_equal( OBJ_DATA* obj1, OBJ_DATA* obj2 )
{
    AFFECT_DATA* obj1aff = obj1->first_affect;
    AFFECT_DATA* obj2aff = obj2->first_affect;

    while ( obj1aff || obj2aff )
    {
        if ( obj1aff && !obj2aff )
            return false;

        if ( !obj1aff && obj2aff )
            return false;

        if ( obj1aff->type != obj2aff->type )
            return false;

        if ( obj1aff->duration != obj2aff->duration )
            return false;

        if ( obj1aff->location != obj2aff->location )
            return false;

        if ( obj1aff->modifier != obj2aff->modifier )
            return false;

        if ( !xSAME_BITS( obj1aff->bitvector, obj2aff->bitvector ) )
            return false;

        obj1aff = obj1aff->next;
        obj2aff = obj2aff->next;
    }

    return true;
}

void add_affect_to_obj( OBJ_DATA* obj, int atype, int mod )
{
    AFFECT_DATA* affect;
    CREATE( affect, AFFECT_DATA, 1 );
    affect->type = -1;
    affect->duration = -1;
    affect->location = atype;
    affect->modifier = mod;
    xCLEAR_BITS( affect->bitvector );
    LINK( affect, obj->first_affect, obj->last_affect, next, prev );
    top_affect++;
}

void group_ch_objects( CHAR_DATA* ch )
{
    OBJ_DATA *other, *other_next; 
    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
    {
        for ( other = obj->next_content; other; other = other_next )
        {
            other_next = other->next_content;
            group_object( obj, other );
        }
    }
}

/*
    If possible group obj2 into obj1             -Thoric
    This code, along with clone_object, obj->count, and special support
    for it implemented throughout handler.c and save.c should show improved
    performance on MUDs with players that hoard tons of potions and scrolls
    as this will allow them to be grouped together both in memory, and in
    the player files.
*/
OBJ_DATA* group_object( OBJ_DATA* obj1, OBJ_DATA* obj2 )
{
    if ( !obj1 || !obj2 )
        return NULL;

    if ( obj1 == obj2 )
        return obj1;

    /* don't group armed explosives */
    if ( !NULLSTR( obj1->armed_by ) || !NULLSTR( obj2->armed_by ) )
        return obj2;

    if ( obj1->pIndexData == obj2->pIndexData
            &&   ( obj1->count + obj2->count + 1 ) <= 10001
            &&   QUICKMATCH( obj1->name,    obj2->name )
            &&   QUICKMATCH( obj1->short_descr, obj2->short_descr )
            &&   QUICKMATCH( obj1->description, obj2->description )
            &&   QUICKMATCH( obj1->action_desc, obj2->action_desc )
            &&   QUICKMATCH( obj1->obj_clan, obj2->obj_clan )
            &&   QUICKMATCH( obj1->blueprint, obj2->blueprint )
            &&   QUICKMATCH( obj1->cybertype, obj2->cybertype )
            &&   obj1->item_type    == obj2->item_type
            &&   obj1->item_type    != ITEM_DISK // Never stack notes, it breaks copying disks in datapads
            &&   obj1->item_type    != ITEM_TRANSMITTER // Never stack transmitters, they have state tracked elsewhere
            &&   obj1->item_type    != ITEM_BLUEPRINT // Never stack blueprints, makes unstacking them during buildship mess with the order
            &&   xSAME_BITS( obj1->extra_flags, obj2->extra_flags )
            &&   xSAME_BITS( obj1->magic_flags, obj2->magic_flags )
            &&   xSAME_BITS( obj1->wear_flags, obj2->wear_flags )
            &&   obj1->wear_loc     == WEAR_NONE
            &&   obj2->wear_loc     == WEAR_NONE
            &&   obj1->weight       == obj2->weight
            &&   obj1->level        == obj2->level
            &&   obj1->timer        == obj2->timer
            &&   obj1->value[0]     == obj2->value[0]
            &&   obj1->value[1]     == obj2->value[1]
            &&   obj1->value[2]     == obj2->value[2]
            &&   obj1->value[3]     == obj2->value[3]
            &&   obj1->value[4]     == obj2->value[4]
            &&   obj1->value[5]     == obj2->value[5]
            &&  extra_descs_equal( obj1, obj2 )
            &&  affects_equal( obj1, obj2 )
            &&  count_dvars( obj1->vars ) == 0
            &&  count_dvars( obj2->vars ) == 0
            &&  !obj1->first_content    && !obj2->first_content
            &&  !obj1->fresh_reset      && !obj2->fresh_reset
            &&  obj1->in_use_count == 0 && obj2->in_use_count == 0
    )
    {
        obj1->count += obj2->count;
        obj2->count = 0;

        if ( current_mprog_obj.obj == obj2 )
            current_mprog_obj.obj = obj1;

        extract_obj( obj2 );
        save_persistent_object( obj1, TRUE );
        return obj1;
    }

    return obj2;
}

/*
    Split off a grouped object                   -Thoric
    decreased obj's count to num, and creates a new object containing the rest
*/
OBJ_DATA* split_obj( OBJ_DATA* obj, int num )
{
    int count;
    OBJ_DATA* rest;

    if ( !obj )
        return NULL;

    count = obj->count;

    if ( count <= num || num == 0 )
        return NULL;

    rest = clone_object( obj );
    --obj->pIndexData->count;   /* since clone_object() ups this value */
    --numobjsloaded;
    rest->count = obj->count - num;
    obj->count = num;

    if ( obj->carried_by )
    {
        INSERT( rest, obj, obj->carried_by->first_carrying, next_content, prev_content );
        rest->carried_by        = obj->carried_by;
        rest->in_room           = NULL;
        rest->in_obj            = NULL;
        rest->in_locker         = NULL;
    }
    else if ( obj->in_room )
    {
        INSERT( rest, obj, obj->in_room->first_content, next_content, prev_content );
        rest->carried_by        = NULL;
        rest->in_room           = obj->in_room;
        rest->in_obj            = NULL;
        rest->in_locker         = NULL;

    }
    else if ( obj->in_obj )
    {
        INSERT( rest, obj, obj->in_obj->first_content, next_content, prev_content );
        rest->in_obj             = obj->in_obj;
        rest->in_room            = NULL;
        rest->carried_by         = NULL;
        rest->in_locker         = NULL;

    }
    else if ( obj->in_locker )
    {
        INSERT( rest, obj, obj->in_locker->first_content, next_content, prev_content );
        rest->in_obj             = NULL;
        rest->in_room            = NULL;
        rest->carried_by         = NULL;
        rest->in_locker          = obj->in_locker;
    }

    save_persistent_object( obj, TRUE );
    save_persistent_object( rest, TRUE );
    return rest;
}

OBJ_DATA* stack_obj( OBJ_DATA* obj )
{
    OBJ_DATA* otmp = NULL;

    if ( !obj || obj_extracted( obj ) )
        return NULL;

    if ( obj->in_room )
    {
        for ( otmp = obj->in_room->first_content; otmp; otmp = otmp->next_content )
            if ( group_object( otmp, obj ) == otmp )
                return otmp;    
    }
    else if ( obj->carried_by )
    {
        for ( otmp = obj->carried_by->first_carrying; otmp; otmp = otmp->next_content )
            if ( group_object( otmp, obj ) == otmp )
                return otmp;
    }
    else if ( obj->in_obj )
    {
        for ( otmp = obj->in_obj->first_content; otmp; otmp = otmp->next_content )
            if ( group_object( otmp, obj ) == otmp )
                return otmp;
    }
    else if ( obj->in_locker )
    {
        for ( otmp = obj->in_locker->first_content; otmp; otmp = otmp->next_content )
            if ( group_object( otmp, obj ) == otmp )
                return otmp;
    }

    return obj;
}

OBJ_DATA* separate_obj( OBJ_DATA* obj )
{
    return split_obj( obj, 1 );
}

/*
    Empty an obj's contents... optionally into another obj, or a room
*/
bool empty_obj( OBJ_DATA* obj, OBJ_DATA* destobj, ROOM_INDEX_DATA* destroom, LOCKER_DATA* destlocker )
{
    OBJ_DATA* otmp, *otmp_next;
    CHAR_DATA* ch = obj->carried_by;
    bool movedsome = FALSE;

    if ( !obj )
    {
        bug( "empty_obj: NULL obj", 0 );
        return FALSE;
    }

    if ( destobj || ( !destroom && !ch && ( destobj = obj->in_obj ) != NULL ) )
    {
        for ( otmp = obj->first_content; otmp; otmp = otmp_next )
        {
            otmp_next = otmp->next_content;

            if ( destobj->item_type == ITEM_CONTAINER
                    &&   get_obj_weight( otmp ) + get_obj_weight( destobj )
                    > destobj->value[0] )
                continue;

            obj_from_obj( otmp );
            obj_to_obj( otmp, destobj );
            movedsome = TRUE;
        }

        return movedsome;
    }

    if ( destroom || ( !ch && ( destroom = obj->in_room ) != NULL ) )
    {
        for ( otmp = obj->first_content; otmp; otmp = otmp_next )
        {
            otmp_next = otmp->next_content;

            if ( ch && ( otmp->pIndexData->progtypes & DROP_PROG ) && otmp->count > 1 )
            {
                separate_obj( otmp );
                obj_from_obj( otmp );

                if ( !otmp_next )
                    otmp_next = obj->first_content;
            }
            else
                obj_from_obj( otmp );

            otmp = obj_to_room( otmp, destroom );

            if ( ch )
            {
                lua_trigger_on_obj_drop( otmp, ch );
                oprog_drop_trigger( ch, otmp );     /* mudprogs */
                lua_trigger_on_room_drop( ch, otmp );

                if ( char_extracted( ch ) )
                    ch = NULL;
            }

            movedsome = TRUE;
        }

        return movedsome;
    }

    if ( destlocker || ( !destroom && !ch && ( destlocker = obj->in_locker ) != NULL ) )
    {
        for ( otmp = obj->first_content; otmp; otmp = otmp_next )
        {
            otmp_next = otmp->next_content;
            obj_from_obj( otmp );
            obj_to_locker( otmp, destlocker );
            movedsome = TRUE;
        }

        if ( movedsome ) save_locker( destlocker, true );
        return movedsome;
    }

    if ( ch )
    {
        for ( otmp = obj->first_content; otmp; otmp = otmp_next )
        {
            otmp_next = otmp->next_content;
            obj_from_obj( otmp );
            obj_to_char( otmp, ch );
            movedsome = TRUE;
        }

        return movedsome;
    }

    bug( "empty_obj: could not determine a destination for vnum %d",
         obj->pIndexData->vnum );
    return FALSE;
}

/*
    Improve mental state                     -Thoric
*/
void better_mental_state( CHAR_DATA* ch, int mod )
{
    int c = URANGE( 0, abs( mod ), 20 );
    int con = get_curr_con( ch );
    c += number_percent() < con ? 1 : 0;
    ch->mental_state = URANGE( 0, ch->mental_state - c, 100 );
}


/*
    Deteriorate mental state                 -Thoric
*/
void worsen_mental_state( CHAR_DATA* ch, int mod )
{
    int c   = URANGE( 0, abs( mod ), 20 );
    int con = get_curr_con( ch );
    c -= number_percent() < con ? 1 : 0;

    if ( c < 1 )
        return;

    ch->mental_state = URANGE( 0, ch->mental_state + c, 100 );
}


/*
    Add gold to an area's economy                -Thoric
*/
void boost_economy( AREA_DATA* tarea, int gold )
{
    while ( gold >= 1000000000 )
    {
        ++tarea->high_economy;
        gold -= 1000000000;
    }

    tarea->low_economy += gold;

    while ( tarea->low_economy >= 1000000000 )
    {
        ++tarea->high_economy;
        tarea->low_economy -= 1000000000;
    }
}

/*
    Take gold from an area's economy             -Thoric
*/
void lower_economy( AREA_DATA* tarea, int gold )
{
    while ( gold >= 1000000000 )
    {
        tarea->high_economy -= 1;
        gold -= 1000000000;
    }

    tarea->low_economy -= gold;

    while ( tarea->low_economy < 0 )
    {
        tarea->high_economy -= 1;
        tarea->low_economy += 1000000000;
    }
}

/*
    Check to see if economy has at least this much gold         -Thoric
*/
bool economy_has( AREA_DATA* tarea, int gold )
{
    int hasgold = ( ( tarea->high_economy > 0 ) ? 1 : 0 ) * 1000000000
                  + tarea->low_economy;

    if ( hasgold >= gold )
        return TRUE;

    return FALSE;
}

/*
    Used in db.c when resetting a mob into an area           -Thoric
    Makes sure mob doesn't get more than 10% of that area's gold,
    and reduces area economy by the amount of gold given to the mob
*/
void economize_mobgold( CHAR_DATA* mob )
{
    int gold;
    AREA_DATA* tarea;
    /* make sure it isn't way too much */
    mob->gold = UMIN( mob->gold, mob->top_level * mob->top_level * 400 );

    if ( !mob->in_room )
        return;

    tarea = mob->in_room->area;
    gold = ( ( tarea->high_economy > 0 ) ? 1 : 0 ) * 1000000000 + tarea->low_economy;
    mob->gold = URANGE( 0, mob->gold, gold / 10 );

    if ( mob->gold )
        lower_economy( tarea, mob->gold );
}

KILLED_DATA* get_killed_data( CHAR_DATA* ch, int vnum )
{
    KILLED_DATA* result = NULL;

    if ( !ch || IS_NPC( ch ) )
        return NULL;

    for ( result = ch->pcdata->first_killed; result; result = result->next )
        if ( result->vnum == vnum )
            break;

    return result;
}

/*
    Add another notch on that there belt... ;)
    Keep track of the last so many kills by vnum         -Thoric
*/
void add_kill( CHAR_DATA* ch, CHAR_DATA* mob )
{
    KILLED_DATA* killed = NULL;

    if ( IS_NPC( ch ) )
        return;

    if ( !IS_NPC( mob ) )
        return;

    killed = get_killed_data( ch, mob->pIndexData->vnum );

    if ( killed )
        killed->count += 1;
    else
    {
        CREATE( killed, KILLED_DATA, 1 );
        killed->vnum = mob->pIndexData->vnum;
        killed->count = 1;
        LINK( killed, ch->pcdata->first_killed, ch->pcdata->last_killed, next, prev );
    }

    return;
}

/*
