/*
    stripnlcr - removes the newline and/or carriage return characters from a string

*/
const char* stripnlcr( const char* text )
{
    static char* done = NULL;

    if ( !text )
        return NULL;

    if ( dump_mem_on_shutdown && text == memdebug_signal )
    {
        DISPOSE( done );
        return NULL;
    }

    int dix = 0;
    int i = 0;

    if ( done )
        DISPOSE( done );

    int buflen = strlen( text ) + 1;
    done = malloc( buflen );
    memset( done, '\0', buflen );

    while ( text[i] != '\0' )
    {
        if ( text[i] != '\n' && text[i] != '\r' )
            done[dix++] = text[i];

        i++;
    }

    done[dix] = '\0';
    return done;
}

char* escape_percent( const char* input )
{
    static char* buffers[MAX_POOL]; // an array of pointers
    static int count = -1;

     if ( !input )
        return NULL;

    if ( dump_mem_on_shutdown && input == memdebug_signal )
    {
        cleanup_static_pool( buffers );
        return NULL;
    }

    int len = strlen(input);
    int new_len = len;
    int i, j;

    // First, count how many % characters there are in the input
    for (i = 0; i < len; i++) {
        if (input[i] == '%') {
            new_len++; // We will need an extra space for each %
        }
    }

    // Rotate buffers and free the old one if necessary
    count++;
    count %= MAX_POOL;
    char** buf = &(buffers[count]);

    if (*buf)
    {
        free(*buf);
        *buf = NULL;
    }

    // Allocate memory for the new string in the buffer
    *buf = (char*)malloc(new_len + 1);
    memset( *buf, '\0', new_len + 1 );
    if (!*buf) {
        // Handle memory allocation failure
        return NULL;
    }

    // Copy and escape % characters
    for (i = 0, j = 0; i < len; i++) {
        if (input[i] == '%') {
            (*buf)[j++] = '%';
        }
        (*buf)[j++] = input[i];
    }

    // Null-terminate the new string
    (*buf)[j] = '\0';

    return *buf;
}


/*
    stripclr - Removes the color codes from a string.

    This function should properly remove the color codes from a string.
*/
char* stripclr( const char* text )
{
    int i = 0, j = 0, len = 0, buflen = 0;
    int r = 0, g = 0, b = 0, length = 0;
    static char* buffers[MAX_POOL];
    static int count = -1;
    const char* ptr;

    if ( !text )
        return NULL;

    if ( dump_mem_on_shutdown && text == memdebug_signal )
    {
        cleanup_static_pool( buffers );
        return NULL;
    }

    len = strlen( text );

    if ( !str_cmp( text, "&" ) || len == 0 )
        return (char*)text; //Rojan - bug fix so that doing & doesn't crash the mud when its stripped

    count++;
    count %= MAX_POOL;
    char** buf = &( buffers[count] );

    if ( *buf )
    {
        free( *buf );
        ( *buf ) = NULL;
    }

    buflen = sizeof( char ) * ( len + 2 );
    ( *buf ) = ( char* )malloc( buflen );
    memset( *buf, '\0', buflen );

    /* Loop through until you've hit your terminating 0 */
    while ( text[i] != '\0' )
    {
        if ( text[i] == '&' || text[i] == '^' )
        {
            ptr = text + i + 1;
            if (
            text[i + 1] == 'x' || text[i + 1] == 'O' || text[i + 1] == 'c' ||
            text[i + 1] == 'z' || text[i + 1] == 'g' || text[i + 1] == 'G' ||
            text[i + 1] == 'P' || text[i + 1] == 'r' || text[i + 1] == 'b' ||
            text[i + 1] == 'w' || text[i + 1] == 'Y' || text[i + 1] == 'C' ||
            text[i + 1] == 'p' || text[i + 1] == 'R' || text[i + 1] == 'B' ||
            text[i + 1] == 'W' || text[i + 1] == '?' )
            {
                i += 2;
                continue;
            }
            else if ( parse_rgb( ptr, &r, &g, &b, &length ) )
            {
                i += length;
                continue;
            }
            else if ( isdigit( text[i + 1] ) && isdigit( text[i + 2] ) && isdigit( text[i + 3] ) )
            {
                i += 4;
                continue;
            }
        }

        if ( text[i] == '}' && (
                    text[i + 1] == 'x' || text[i + 1] == 'O' || text[i + 1] == 'c' ||
                    text[i + 1] == 'z' || text[i + 1] == 'g' || text[i + 1] == 'G' ||
                    text[i + 1] == 'P' || text[i + 1] == 'r' || text[i + 1] == 'b' ||
                    text[i + 1] == 'w' || text[i + 1] == 'Y' || text[i + 1] == 'C' ||
                    text[i + 1] == 'p' || text[i + 1] == 'R' || text[i + 1] == 'B' ||
                    text[i + 1] == 'W' )
            )
        {
            i += 2;
            continue;
        }

        if ( text[i] != '\0' )
        {
            if ( isspace( text[i] ) && !iscntrl( text[i] ) )
            {
                (*buf)[j] = ' ';
                i++;
                j++;
            }
            else
            {
                (*buf)[j] = text[i];
                i++;
                j++;
            }
        }
        else
            (*buf)[j] = '\0';
    }

    (*buf)[j] = '\0';
    return *buf;
}

/*
    substr_clr - Returns a substring of a certain length, exclusive of color codes
*/
char* substr_clr( int length, char* text )
{
    int i = 0, j = 0, cnt = 0;
    static char *buf = NULL;

    if ( NULLSTR( text ) )
        return NULL;
    else
    {
        if ( !str_cmp( text, "&" ) )
            return text; //Rojan - bug fix so that doing & doesn't crash the mud when its stripped

        if( buf != NULL )
            free(buf);

        buf = calloc( 1, strlen( text ) + 1 );

        /* Loop through until you've hit your terminating 0 */
        while ( text[i] != '\0' && cnt < length )
        {
            if ( text[i] == '&' )
            {
                if ( isdigit( text[i + 1] ) && isdigit( text[i + 2] ) && isdigit( text[i + 3] ) )
                {
                    cnt -= 4;
                }
                else
                {
                    cnt -= 2;
                }
            }

            if ( text[i] == '^' && (
                        text[i + 1] == 'x' || text[i + 1] == 'r' || text[i + 1] == 'g' ||
                        text[i + 1] == 'O' || text[i + 1] == 'b' || text[i + 1] == 'p' ||
                        text[i + 1] == 'c' || text[i + 1] == 'w' )
               )
            {
                cnt -= 2;
            }

            if ( text[i] == '}' && (
                        text[i + 1] == 'x' || text[i + 1] == 'O' || text[i + 1] == 'c' ||
                        text[i + 1] == 'z' || text[i + 1] == 'g' || text[i + 1] == 'G' ||
                        text[i + 1] == 'P' || text[i + 1] == 'r' || text[i + 1] == 'b' ||
                        text[i + 1] == 'w' || text[i + 1] == 'Y' || text[i + 1] == 'C' ||
                        text[i + 1] == 'p' || text[i + 1] == 'R' || text[i + 1] == 'B' ||
                        text[i + 1] == 'W' )
               )
            {
                cnt -= 2;
            }

            if ( text[i] != '\0' )
            {
                if ( isspace( text[i] ) && !iscntrl( text[i] ) )
                {
                    buf[j] = ' ';
                    i++;
                    j++;
                    cnt++;
                }
                else
                {
                    buf[j] = text[i];
                    i++;
                    j++;
                    cnt++;
                }
            }
            else
                buf[j] = '\0';
        }

        buf[j] = '\0';
        return buf;
    }
}

