int get_armor_type( OBJ_DATA* obj )
{
    if ( obj->item_type != ITEM_ARMOR )
        return 0;

    if ( !xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) && !xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) )
        return 0;

    if ( obj->value[2] == 1 || obj->value[2] == 4 || obj->value[2] == 5 || obj->value[2] == 6 )
        return 1;

    if ( obj->value[2] == 2 || obj->value[2] == 7 || obj->value[2] == 8 || obj->value[2] == 9 )
        return 2;

    if ( obj->value[2] == 3 || obj->value[2] == 10 || obj->value[2] == 11 || obj->value[2] == 12 )
        return 3;

    return 0;
}

