bool same_clan( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( IS_IMMORTAL( ch ) || IS_IMMORTAL( victim ) )
        return TRUE;

    if ( IS_NPC( ch ) || IS_NPC( victim ) )
        return FALSE;

    if ( !ch->pcdata->clan || !victim->pcdata->clan || ch->pcdata->clan != victim->pcdata->clan )
        return FALSE;

    return TRUE;
}

