    return E_LOTJ_SUCCESS;
}

void check_switches( bool possess )
{
    CHAR_DATA* ch;

    for ( ch = first_char; ch; ch = ch->next )
        check_switch( ch, possess );
}
DECLARE_DO_FUN( do_switch );

void check_switch( CHAR_DATA* ch, bool possess )
{
    AFFECT_DATA* paf;
    CMDTYPE* cmd;
    int hash, trust = get_trust( ch );

    if ( !ch->switched )
        return;

    if ( !possess )
    {
        for ( paf = ch->switched->first_affect; paf; paf = paf->next )
        {
            if ( paf->duration == -1 )
                continue;
        }
    }

    for ( hash = 0; hash < 126; hash++ )
    {
        for ( cmd = command_hash[hash]; cmd; cmd = cmd->next )
        {
            if ( cmd->do_fun != do_switch )
                continue;

            if ( cmd->level <= trust )
                return;

            if ( !IS_NPC( ch ) && ch->pcdata->bestowments && is_name( cmd->name, ch->pcdata->bestowments )
                    && cmd->level <= trust )
                return;
        }
    }

    if ( !possess )
    {
        set_char_color( AT_BLUE, ch->switched );
        ch_println( ch->switched, "You suddenly forfeit the power to switch!" );
    }

    do_return( ch->switched, "" );
}

bool is_your_vendor( CHAR_DATA* ch, CHAR_DATA* vendor )
{
    VENDOR_DATA* vdata = NULL;
    CLAN_DATA* clan = NULL;

    if ( !ch || !vendor )
        return false;    

    if ( IS_NPC( ch ) || !IS_NPC( vendor ) )
        return FALSE;

    if ( ( vdata = vendor->vendor_data ) == NULL )
        return FALSE;

    if ( !str_cmp( ch->name, vdata->owner ) )
        return TRUE;

    clan = ch->pcdata->clan;

    if ( clan != NULL && !str_cmp( vdata->owner, clan->name ) )
    {
        // does not need to be two lines but it's a lot easier to read
        if ( is_empowered( ch, "clanvendor") ||
                !str_cmp( ch->name, ch->pcdata->clan->leader ) ||
                !str_cmp( ch->name, ch->pcdata->clan->number1 ) ||
                !str_cmp( ch->name, ch->pcdata->clan->number2 ) )
        {
            return TRUE;
        }
    }

    return FALSE;
}

