char* remove_substr_from_str( const char* str, const char* substr )
{
    if ( !str || !substr )
        return NULL;

    char arg[MIL];
    static char result[MSL];
    strlcpy( result, "", MSL );

    while ( !NULLSTR( str ) )
    {
        str = one_argument( str, arg );
        if ( str_cmp( arg, substr ) )
            snprintf( result + strlen( result ), MSL - strlen( result ), "%s ", arg );
    }
    if ( strlen( result ) > 0 )
        result[ (int) strlen(result) - 1 ] = '\0'; // Remove the last space in the string

    return result;
}

char* replace_substr_in_str( const char* str, const char* substr, const char* newsubstr )
{
    int cnt = 0, lendiff = 0, substrlen = 0, pos = 0, pos2 = 0;
    char* ptr = NULL;
    static char* result = NULL;

    if ( dump_mem_on_shutdown && str == memdebug_signal )
    {
        DISPOSE( result );
        return NULL;
    }

    if ( NULLSTR( str ) || NULLSTR( substr ) || NULLSTR( newsubstr ) )
        return NULL;

    substrlen = strlen( substr );
    lendiff = UMAX( (int)( strlen( newsubstr ) - substrlen ), 0 );

    do {
        ptr = strstr( str + pos, substr );
        if ( ptr != NULL )
        {
            cnt++;
            pos = ptr - str + substrlen;
        }
    } while ( ptr != NULL );


    if ( result )
        DISPOSE( result );

    size_t len = strlen( str ) + 1 + ( lendiff * cnt );
    result = malloc( len );
    memset( result, '\0', len );

    if ( cnt == 0 )
    {
        snprintf( result, len, "%s", str );
        return result;
    }


    pos = 0;
    do {
        ptr = strstr( str + pos, substr );
        pos2 = ptr != NULL ? (int) ( ptr - str ) : (int) strlen( str );
        snprintf( result + strlen( result ), len - strlen( result ), "%.*s%s", pos2 - pos, str + pos, ptr ? newsubstr : "" );
        pos = pos2 + substrlen;
    } while ( ptr != NULL );

    return result;
}

/* Function to find every instance of typos in a string and return the number of characters to add/remove */
int char_differences( const char* str )
{
    char substr[MIL];
    int counter = 0;

    while (*str)
    {
        str = one_argument_qt( str, substr );
        for ( AUTOCORRECT_DATA* autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
            if ( strcmp( substr, autocorrect->typo ) == 0 )
                counter += ( strlen( autocorrect->correction ) - strlen( autocorrect->typo ) );
    }

    return counter;
}

/* Function to replace commonly misspelled words in any string passed to it */
char* autoformat_replace_words( const char* str )
{
    static char* buf = NULL;
    char arg[MIL];
    int counter = 0;

    if ( !str )
        return NULL;

    if ( dump_mem_on_shutdown && str == memdebug_signal )
    {
        DISPOSE( buf );
        return NULL;
    }

    counter = char_differences(str);

    if ( buf )
        DISPOSE( buf );

    int len = strlen( str ) + counter;
    int buflen = 2 * len + 2; 
    buf = malloc( buflen );
    if ( !buf )
    {
        bug( "%s: memory allocation failure" );
        return NULL;
    }

    memset( buf, '\0', buflen );

    bool corrected = false;
    while ( *str )
    {
        corrected = false;
        str = one_argument_qt( str, arg );

        for ( AUTOCORRECT_DATA* autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
        {
            if ( strcmp(arg, autocorrect->typo) == 0 )
            {
                strlcat( buf, autocorrect->correction, buflen );
                corrected = true;
                break;
            }
        }

        if ( !corrected )
            strlcat( buf, arg, buflen );

        if ( !NULLSTR( str ) && ( ( strcmp(arg, "\"" ) != 0 && strcmp( arg, "\'" ) != 0 ) || str[0] == ' ' ) && ( str[0] != '\"' && str[0] != '\'' ) )
            strlcat( buf, " ", buflen );
    }

    return buf;
}


char* autoformat_string( const char* str )
{
    if ( !str )
        return NULL;

    char* buf = autoformat_replace_words( str );
    bool new_sentence = true;
    int len = strlen( buf );

    for ( int i = 0; buf[i]; i++ )
    {
        if ( new_sentence && isalpha( buf[i] ) )
        {
            buf[i] = toupper(buf[i]);
            new_sentence = false;
        }

        if ( buf[i] == '.' || buf[i] == '?' || buf[i] == '!' )
            new_sentence = true;
    }

    if ( buf[len - 1] != '.' && buf[len - 1] != '?' && buf[len - 1] != '!' )
    {
        buf[len] = '.';
        buf[len + 1] = '\0';
    }

    return buf;
}

/*
 * Checks if the provided name is valid for use with objects. Looks for
 * impermissible special characters and sequences at the beginning.
 * Returns true if the object name is valid for use, and false if not.
 */
bool valid_obj_name( char* name )
{
    if ( NULLSTR( name ) )
        return false;

    bool result = true;

    if ( name[0] == '*' || name[0] == '-' || name[0] == '#' || name[0] == '!' || name[0] == '$' || name[0] == '@' || name[0] == '%' )
        result = false;

    if ( isdigit( name[0] ) )
    {
        for ( int i = 0; i < (int) strlen( name ); i++ )
        {
            if ( isdigit( name[i] ) )
                continue;

            if ( name[i] == '.' )
                result = false;

            break;
        }
    }

    return result;
}

BUFFER_DATA* create_buffer( CHAR_DATA* ch, const char* func )
{
    BUFFER_DATA* buffer = NULL;

    if ( NULLSTR( func ) )
        return NULL;

    if ( ( buffer = get_buffer( ch, func ) ) != NULL )
    {
        bug("create_buffer: %s attempting to create buffer for %s that already exists.", func, ch ? ( IS_NPC( ch ) ? ch->short_descr : ch->name ) : "(null)" );
        return buffer;
    }

    CREATE( buffer, BUFFER_DATA, 1 );
    buffer->created = time( 0 );
    buffer->ch = ch;
    SET_STRING( buffer->func, func );
    if ( buffer->ch )
        LINK( buffer, ch->first_buffer, ch->last_buffer, next, prev );
    else
        LINK( buffer, first_buffer, last_buffer, next, prev );
    return buffer;
}

BUFFER_DATA* get_buffer( CHAR_DATA* ch, const char* func )
{
    BUFFER_DATA* buffer = NULL;

    if ( NULLSTR( func ) )
        return NULL;

    for ( buffer = ch ? ch->first_buffer : first_buffer; buffer; buffer = buffer->next )
        if ( !str_cmp( buffer->func, func ) )
            break;

    return buffer;
}

// Add an object to the buffer with a key to pick it back out later.
// If consume is set to true, this object will be deleted after any non-error completion of the callback.
// Object ungrouping is handled automatically: Once put in a buffer, an object is ungrouped and prevented
// from re-grouping until no buffers are using it anymore.
void add_obj_to_buffer_ex( BUFFER_DATA* buffer, const char* key, OBJ_DATA* obj, bool consume, const char* label )
{
    if ( !valid_obj( obj ) || !buffer || NULLSTR( key ) )
        return;

    separate_obj( obj );
    obj->in_use_count++;

    for ( BUFFER_OBJ_REF* ref = buffer->_first_obj_ref; ref; ref = ref->next )
    {
        if ( !str_cmp( ref->key, key ) )
        {
            OBJ_DATA* existing = obj_from_ref( ref->ref );
            if ( existing )
                existing->in_use_count--;
            ref->ref = obj_to_ref( obj );
            ref->consume = consume;
            return;
        }
    }

    BUFFER_OBJ_REF* ref;
    CREATE( ref, BUFFER_OBJ_REF, 1 );
    SET_STRING( ref->key, key );
    SET_STRING( ref->obj_name, obj->short_descr );
    SET_STRING( ref->label, label );
    ref->ref = obj_to_ref( obj );
    ref->consume = consume;
    ref->orig_carried_by = obj->carried_by;
    ref->orig_in_room = obj->in_room;
    LINK( ref, buffer->_first_obj_ref, buffer->_last_obj_ref, next, prev );
    return;
}

void add_obj_to_buffer( BUFFER_DATA* buffer, const char* key, OBJ_DATA* obj )
{
    add_obj_to_buffer_ex( buffer, key, obj, false, NULL );
    return;
}

void add_consumable_to_buffer( BUFFER_DATA* buffer, const char* key, OBJ_DATA* obj, const char* label )
{
    add_obj_to_buffer_ex( buffer, key, obj, true, label );
    return;
}

// Get a named object from a buffer.
// In an on_complete callback, this is guaranteed to return a non-null object for a valid key, since on_complete
// won't be called if any of the objects go missing.
OBJ_DATA* get_obj_from_buffer( BUFFER_DATA* buffer, const char* key )
{
    if ( !buffer || NULLSTR( key ) )
        return NULL;

    for ( BUFFER_OBJ_REF* ref = buffer->_first_obj_ref; ref; ref = ref->next )
    {
        if ( !str_cmp( ref->key, key ) )
        {
            OBJ_DATA* obj = obj_from_ref( ref->ref );
            if ( !obj || obj->carried_by != ref->orig_carried_by || obj->in_room != ref->orig_in_room )
                return NULL;
            return obj;
        }
    }
    return NULL;
}

// If this function returns true, all buffer objects are where they started and you can
// use get_obj_from_buffer and safely assume the return value will be non-null.
bool validate_buffer_targets( BUFFER_DATA* buffer, CHAR_DATA* ch )
{
    if ( !buffer || !ch )
        return false;

    for ( BUFFER_OBJ_REF* ref = buffer->_first_obj_ref; ref; ref = ref->next )
        if ( !get_obj_from_buffer( buffer, ref->key ) )
        {
            if ( ref->orig_carried_by == ch )
                ch_println( ch, "&RYou no longer seem to have %s&R!", ref->obj_name );
            else
                ch_println( ch, "&R%s&R isn't here anymore!", ref->obj_name );
            return false;
        }

    return true;
}

int dispose_buffer_obj_ref( BUFFER_OBJ_REF* ref )
{
    if ( !ref )
        return E_LOTJ_MISSING_ARGUMENTS;

    SET_STRING( ref->key, NULL );
    SET_STRING( ref->obj_name, NULL );
    SET_STRING( ref->label, NULL );
    DISPOSE( ref );
    return E_LOTJ_SUCCESS;
}

void extract_buffer_consumables( BUFFER_DATA* buffer )
{
    if ( !buffer )
        return;

    BUFFER_OBJ_REF* next_ref;
    for ( BUFFER_OBJ_REF* ref = buffer->_first_obj_ref; ref; ref = next_ref )
    {
        next_ref = ref->next;
        if ( !ref->consume )
            continue;

        OBJ_DATA* obj = obj_from_ref( ref->ref );
        if ( !obj )
            continue;

        extract_obj( obj );
        UNLINK( ref, buffer->_first_obj_ref, buffer->_last_obj_ref, next, prev );
        dispose_buffer_obj_ref( ref );
    }
}

void print_buffer_objects( BUFFER_DATA* buffer, CHAR_DATA* ch )
{
    if ( !buffer || !ch )
        return;

    ch_println( ch, "\n&wYou are using:" );
    // Do some primitive deduping here: If we have N objects in a row with the same name, show them on one line.
    int name_dup_count = 0;
    for ( BUFFER_OBJ_REF* ref = buffer->_first_obj_ref; ref; ref = ref->next )
    {
        if ( ref->label )
        {
            name_dup_count++;
            // Next object has the same name, so skip this after increment our counter.
            if ( ref->next && !str_cmp( ref->obj_name, ref->next->obj_name ) )
                continue;

            if ( name_dup_count > 1 )
                ch_println( ch, "&w  %s: %s &z(&C%d&z)", ref->label, ref->obj_name, name_dup_count );
            else
                ch_println( ch, "&w  %s: %s", ref->label, ref->obj_name );
            name_dup_count = 0;
        }
    }
}

int dispose_buffer( BUFFER_DATA* buffer )
{
    bool hasnode = FALSE;
    TIMER* timer, *next_timer;

    if ( !buffer )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( buffer->ch )
    {
        LINK_HASNODE( buffer->ch->first_buffer, BUFFER_DATA, next, buffer, hasnode );
        if ( hasnode )
            UNLINK( buffer, buffer->ch->first_buffer, buffer->ch->last_buffer, next, prev );

        for ( timer = buffer->ch->first_timer; timer; timer = next_timer)
        {
            next_timer = timer->next;
            if ( timer->buffer == buffer )
            {
                timer->buffer = NULL;
                extract_timer( buffer->ch, timer );
            }
        }
    }

    LINK_HASNODE( first_buffer, BUFFER_DATA, next, buffer, hasnode );

    if ( hasnode )
        UNLINK( buffer, first_buffer, last_buffer, next, prev );

    BUFFER_OBJ_REF* ref = NULL, *next_ref = NULL;

    for ( ref = buffer->_first_obj_ref; ref; ref = next_ref )
    {
        next_ref = ref->next;
        OBJ_DATA* obj = obj_from_ref( ref->ref );

        if ( obj )
            obj->in_use_count--;

        UNLINK( ref, buffer->_first_obj_ref, buffer->_last_obj_ref, next, prev );
        dispose_buffer_obj_ref( ref );
    }

    SET_STRING( buffer->func, NULL );
    SET_STRING( buffer->str1, NULL );
    SET_STRING( buffer->str2, NULL );
    DISPOSE( buffer );
    return E_LOTJ_SUCCESS;
}

void clear_buffers( CHAR_DATA* ch )
{
    if ( !ch )
        return;

    BUFFER_DATA* buffer = NULL, *next_buffer = NULL;
    for ( buffer = ch->first_buffer; buffer; buffer = next_buffer )
    {
        next_buffer = buffer->next;
        buffer->ch = ch;

        // Some timers may reference these buffers; make sure we clear them out too.
        TIMER* buffer_timer = NULL;
        for ( TIMER* timer = ch->first_timer; timer; timer = timer->next )
            if ( timer->buffer == buffer )
                buffer_timer = timer;

        // Extracting the timer will also extract the buffer, so don't do it here too.
        if ( buffer_timer )
            extract_timer( ch, buffer_timer );
        else
            dispose_buffer( buffer );
    }

    return;
}

