CMDF do_debugmud( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    IMM_CHECK( ch );

    for ( CHAR_DATA* tch = first_char; tch; tch = tch->next )
    {
        if ( !IS_NPC( tch ) )
        {
            if ( tch->id <= 0 )
                bug( "%s: player %s has no ID", FUNC, ch->name );

            if ( tch->save_queued )
                bug( "%s: player %s is queued for saving", FUNC, ch->name );
        }
        else if ( xIS_SET( tch->act, ACT_PERSISTENT ) )
        {
            if ( tch->id <= 0 )
                bug( "%s: persistent mob %s (%d) has no ID", FUNC, ch->short_descr, ch->pIndexData ? ch->pIndexData->vnum : -1 );

            if ( tch->save_queued )
                bug( "%s: persistent mob %s (%d) is queued for saving", FUNC, ch->short_descr, ch->pIndexData ? ch->pIndexData->vnum : -1 );
        }
    }

    for ( ACCOUNT_DATA* acc = first_account; acc; acc = acc->next )
    {
        if ( acc->id <= 0 )
            bug( "%s: account %s has no ID", FUNC, acc->name );

        if ( acc->save_queued )
            bug( "%s: account %s is queued for saving", FUNC, acc->name );
    }

    for ( CLAN_DATA* clan = first_clan; clan; clan = clan->next )
    {
        if ( clan->id <= 0 )
            bug( "%s: clan %s has no ID", FUNC, clan->name );

        if ( clan->save_queued )
            bug( "%s: clan %s is queued for saving", FUNC, clan->name );
    }

    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( ship->id <= 0 )
            bug( "%s: ship %s has no ID", FUNC, ship->name );

        if ( ship->save_queued )
            bug( "%s: ship %s is queued for saving", FUNC, ship->name );
    }

    for ( STRUCTURE_DATA* structure = first_structure; structure; structure = structure->next )
    {
        if ( structure->id <= 0 )
            bug( "%s: structure %s has no ID", FUNC, structure->name );

        if ( structure->save_queued )
            bug( "%s: structure %s is queued for saving", FUNC, structure->name );
    }

    for ( VEHICLE_DATA* vehicle = first_vehicle; vehicle; vehicle = vehicle->next )
    {
        if ( vehicle->id <= 0 )
            bug( "%s: vehicle %s has no ID", FUNC, vehicle->name );

        if ( vehicle->save_queued )
            bug( "%s: vehicle %s is queued for saving", FUNC, vehicle->name );
    }

    for ( OBJ_DATA* obj = first_object; obj; obj = obj->next )
    {
        if ( xIS_SET( obj->extra_flags, ITEM_PERSISTENT ) )
        {
            if ( obj->id <= 0 )
                bug( "%s: persistent object %s (%d) has no ID", FUNC, obj->short_descr, obj->pIndexData ? obj->pIndexData->vnum : -1 );

            if ( obj->save_queued )
                bug( "%s: persistent object %s (%d) is queued for saving%s", FUNC, obj->short_descr, obj->pIndexData ? obj->pIndexData->vnum : -1, obj->id > 0 ? "" : " WITH NO ID" );
        }
    }

    for ( AREA_DATA* area = first_area; area; area = area->next )
    {        
        if ( area->save_queued )
            bug( "%s: area %s is queued for saving", FUNC, area->shortname );

        if ( area->full_save )
            bug( "%s: area %s is set to full save", FUNC, area->shortname );
    }

    for ( MOB_INDEX_DATA* mobIndex = first_mob_index; mobIndex; mobIndex = mobIndex->next )
        if ( mobIndex->save_queued )
            bug( "%s: mob index %s (%d) is queued for saving", FUNC, mobIndex->short_descr, mobIndex->vnum );

    for ( OBJ_INDEX_DATA* objIndex = first_obj_index; objIndex; objIndex = objIndex->next )            
        if ( objIndex->save_queued )
            bug( "%s: obj index %s (%d) is queued for saving", FUNC, objIndex->short_descr, objIndex->vnum );

    for ( ROOM_INDEX_DATA* room = first_room; room; room = room->next )       
        if ( room->save_queued )
            bug( "%s: room index %s (%d) is queued for saving", FUNC, room->name, room->vnum );

    return;
}

bool has_label( LABEL_DATA** first, const char* name )
{
    LABEL_DATA* label = NULL;

    if ( (*first) == NULL )
        return FALSE;

    if ( NULLSTR( name ) )
        return FALSE;

    for ( label = *first; label; label = label->next )
        if ( !str_cmp( label->label, name ) )
            return TRUE;

    return FALSE;
}

LABEL_DATA* get_label( LABEL_DATA** first, const char* name )
{
    LABEL_DATA* label = NULL;

    if ( (*first) == NULL )
        return NULL;

    if ( NULLSTR( name ) )
        return NULL;

    for ( label = *first; label; label = label->next )
        if ( !str_cmp( label->label, name ) )
            break;

    return label;
}

int remove_label( LABEL_DATA** first, LABEL_DATA** last, const char* name )
{
    LABEL_DATA* label = get_label( first, name );

    if ( !label )
        return E_LOTJ_MISSING_ARGUMENTS;

    UNLINK( label, *first, *last, next, prev );
    FREE_STRUCT( label, label_fields );
    return E_LOTJ_SUCCESS;
}

int add_label( LABEL_DATA** first, LABEL_DATA** last, const char* name )
{
    LABEL_DATA* label = NULL;

    if ( NULLSTR( name ) )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( has_label( first, name ) )
        return E_LOTJ_NOTHING_TO_DO;

    CREATE( label, LABEL_DATA, 1 );
    SET_STRING( label->label, name );
    LINK( label, *first, *last, next, prev );
    return E_LOTJ_SUCCESS;
}

int64_t strntoll( const char* str, size_t len )
{
    int64_t val = 0;
    bool negative = false;
    size_t i = 0;

    if ( !str || len <= 0 )
        return val;

    if ( str[0] == '-')
    {
        negative = true;
        i = 1;
    }

    while ( i < len && str[i] >= '0' && str[i] <= '9' )
    {
        val = val * 10 + ( str[i] - '0' );
        i++;
    }

    if ( negative )
        val *= -1;

    return val;
}

