bool update_pstats()
{
    time_t tm = time( 0 );
    DESCRIPTOR_DATA* d;
    CHAR_DATA* victim;
    int ptotal = 0;
    int pcount = 0;
    int icount = 0;
    int botcount = 0;
    int afkpcount = 0;
    int afkicount = 0;
    int idlepcount = 0;
    int idleicount = 0;

    for ( d = first_descriptor; d; d = d->next )
        if ( ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                && ( victim = d->character ) != NULL
                &&   !IS_NPC( victim )
                &&   victim->in_room )
        {
            if ( IS_IMMORTAL( victim ) )
            {
                icount++;

                if ( has_pcflag( victim, PCFLAG_AFK ) )
                    afkicount++;
                else if ( d->idle > 1200 )
                    idleicount++;
            }
            else
            {
                pcount++;

                if ( has_pcflag( victim, PCFLAG_AFK ) )
                    afkpcount++;
                else if ( victim->pcdata->botting )
                    botcount++;
                else if ( d->idle > 1200 )
                    idlepcount++;
            }

            ptotal++;
        }
   // int id = -1;
    return upsert_sql_row_with_flags(
        "pcountlog",
        FLAG_NO_UPSERT, 
        sql_unique_id( NULL ),
        sql_int( "time", ( int )tm ),
        sql_int( "total", ptotal ),
        sql_int( "mortcount", pcount ),
        sql_int( "afkmortcount", afkpcount ),
        sql_int( "botmortcount", botcount ),
        sql_int( "immcount", icount ),
        sql_int( "afkimmcount", afkicount ),
        sql_int( "idlemorts", idlepcount ),
        sql_int( "idleimms", idleicount ),
        LAST_DB_VALUE
    );
}

