int max_level( CHAR_DATA* ch, int ability )
{
    return max_level_flag( ch, ability, FALSE );
}

/*
    This is a simple fucking formula. - Rojan

    level = race[main][abil] + (current stat - racial max) + (current stat - racial max)
*/
int max_level_flag( CHAR_DATA* ch, int ability, bool nolevels )
{
    int level = 0;
    int base = 18;
    int orig_str, orig_dex, orig_con, orig_int, orig_wis, orig_cha, orig_lck;
    CYBER_DATA* ch_cyber = NULL;
    AFFECT_DATA* chpaf = NULL;

    if ( IS_NPC( ch ) ) // GRAL why 100 and not 150?
        return 100;

    if ( IS_IMMORTAL( ch ) )
        return 200;

    //    if (ch->legacymax[ability] != 0)
    //        level = UMAX(1,ch->legacymax[ability]);
    //    else
    level = ch->race->main_table[ch->main_ability][ability];

    if ( ch->custommax[ability] != 0 )
        return UMAX( 1, ch->custommax[ability] );

    // GRAL This means custommax is hidden from mstat you cheats
    // Means if you get awoken you will also not have your levels change - needs a fix
    orig_str = ch->perm_str;
    orig_con = ch->perm_con;
    orig_dex = ch->perm_dex;
    orig_int = ch->perm_int;
    orig_wis = ch->perm_wis;
    orig_cha = ch->perm_cha;
    orig_lck = ch->perm_lck;

    for ( ch_cyber = ch->first_cyber; ch_cyber; ch_cyber = ch_cyber->next_on_char )
    {
        for ( chpaf = ch_cyber->cyber_index->first_affect; chpaf; chpaf = chpaf->next )
        {
            switch ( chpaf->location )
            {
                case APPLY_STR:
                    orig_str += chpaf->modifier;
                    break;

                case APPLY_DEX:
                    orig_dex += chpaf->modifier;
                    break;

                case APPLY_CON:
                    orig_con += chpaf->modifier;
                    break;

                case APPLY_INT:
                    orig_int += chpaf->modifier;
                    break;

                case APPLY_WIS:
                    orig_wis += chpaf->modifier;
                    break;

                case APPLY_CHA:
                    orig_cha += chpaf->modifier;
                    break;

                case APPLY_LCK:
                    orig_lck += chpaf->modifier;
                    break;

                default:
                    break;
            }
        }
    }

    // Cap bonuses to 25 of a given attribute
    orig_str = UMIN( orig_str, 25 );
    orig_con = UMIN( orig_con, 25 );
    orig_dex = UMIN( orig_dex, 25 );
    orig_int = UMIN( orig_int, 25 );
    orig_wis = UMIN( orig_wis, 25 );
    orig_cha = UMIN( orig_cha, 25 );
    orig_lck = UMIN( orig_lck, 25 );

    switch ( ability )
    {
        default:
            break;

        case  COMBAT_ABILITY:
            level += orig_str - ( base + ch->race->str_plus );
            level += orig_con - ( base + ch->race->con_plus );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 )
            {
                switch ( ch->pcdata->fclass ) //Subclass combat levels updated due to Jan 2017 subclass upgrade. -Gathorn 14Jan2017
                {
                    default:
                        break;

                    case JEDI_GUARDIAN:
                    case SITH_JUGGERNAUT:
                        level += 70;
                        break;

                    case JEDI_SENTINEL:
                    case JEDI_CONSULAR:
                    case SITH_ASSASSIN:
                    case SITH_SORCERER:
                        level += 40;
                        break;

                    case SITH_DARKLORD:
                        level += 40;
                        break;
                }
            }

            break;

        case PILOTING_ABILITY:
            level += 2 * ( orig_dex - ( base + ch->race->dex_plus ) );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 && ( IS_GUARDIAN( ch ) || IS_JUGGERNAUT( ch ) ) )
                level += 20;

            break;

        case ENGINEERING_ABILITY:
            level += 2 * ( orig_int - ( base + ch->race->int_plus ) );

            if ( xIS_SET( ch->race->specflags, RSPECFLAG_NUBIAN ) )
                level += 5;

            if ( ch->skill_level[FORCE_ABILITY] >= 2 && ( IS_CONSULAR( ch ) || IS_SORCERER( ch ) ) )
                level += 30;

            break;

        case HUNTING_ABILITY:
            level += 2 * ( orig_con - ( base + ch->race->con_plus ) );
            break;

        case SMUGGLING_ABILITY:
            level += 2 * ( orig_lck - ( 10 + ch->race->lck_plus ) );
            level += orig_cha - ( base + ch->race->cha_plus );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 )
            {
                switch ( ch->pcdata->fclass )
                {
                    default:
                        break;

                    //               Guardian no longer receives smuggling bonus due to Jan 2017 subclass upgrade. -Gathorn 14Jan2017
                    /*               case JEDI_GUARDIAN:
                                       level += 30;
                                       break;*/
                    case JEDI_SENTINEL:
                    case SITH_ASSASSIN:
                        level += 50;
                        break;

                    case SITH_DARKLORD:
                        level += 40;
                        break;
                }
            }

            break;

        case LEADERSHIP_ABILITY:
            level += orig_cha - ( base + ch->race->cha_plus );
            level += orig_wis - ( base + ch->race->wis_plus );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 )
            {
                switch ( ch->pcdata->fclass )
                {
                    default:
                        break;

                    case JEDI_CONSULAR:
                    case SITH_SORCERER:
                        level += 50;
                        break;
                }
            }

            break;

        case DIPLOMACY_ABILITY:
            level += orig_cha - ( base + ch->race->cha_plus );
            level += orig_wis - ( base + ch->race->wis_plus );
            /*           if ( ch->skill_level[FORCE_ABILITY] >= 2 )
                       {
                           switch ( ch->pcdata->fclass )
                           {
                           default:
                               break;
                           Sentinel no longer receives diplomacy bonus due to Jan 2017 subclass upgrade. -Gathorn 14Jan2017
                           case JEDI_SENTINEL:
                               level += 60;
                               break;
                           case JEDI_CONSULAR:
                           case SITH_SORCERER:
                               level += 50;
                               break;
                           case JEDI_SAGE:
                               level += 20;
                               break;
                           case SITH_DARKLORD:
                               level += 40;
                               break;
                           }
                       } */
            break;

        case ESPIONAGE_ABILITY:
            level += orig_lck - ( 10 + ch->race->lck_plus );
            level += orig_dex - ( base + ch->race->dex_plus );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 && ( IS_GUARDIAN( ch ) || IS_JUGGERNAUT( ch ) ) )
                level += 30;

            break;

        case SLICER_ABILITY:
            level += orig_lck - ( 10 + ch->race->lck_plus );
            level += orig_wis - ( base + ch->race->wis_plus );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 && ( IS_SENTINEL( ch ) || IS_ASSASSIN( ch ) ) )
                level += 30;

            break;

        case MEDIC_ABILITY:
            level += orig_wis - ( base + ch->race->wis_plus );
            level += orig_int - ( base + ch->race->int_plus );
            break;

        case SCIENCE_ABILITY:
            level += 2 * ( orig_int - ( base + ch->race->int_plus ) );

            if ( ch->skill_level[FORCE_ABILITY] >= 2 )
            {
                switch ( ch->pcdata->fclass )
                {
                    default:
                        break;

                    case JEDI_SAGE:
                        level += 50;
                        break;
                }
            }

            break;

        case FORCE_ABILITY:
            level = ch->perm_frc * 5;

            // GRAL Why do we min set nats to 25?
            //Rojan - no clue, this is dumb..removing
            //if ( level < 25 && xIS_SET(ch->race->flags,RFLAG_NATURALFORCE) )
            //  level = 25;
            // GRAL Dark lord always has the advantage or what?
            if ( ch->skill_level[FORCE_ABILITY] >= 2 && ch->pcdata->fclass == SITH_DARKLORD )
            {
                level += 15;
            }

            break;
    }

    if ( is_focus( ch, ability ) )
        level += 30;

    /* Should make sure that your max cant be below your current level */
    if ( ch->skill_level[ability] > level && nolevels == FALSE )
        level = ch->skill_level[ability];

    // bug("CH: %s | Ability: %s | Level: %d", ch->name, flag_value_name( ability_name, ability ), level);
    level = URANGE( 1, level, 150 );

    if ( has_pcflag( ch, PCFLAG_CHILD ) && level > 1 )
        return URANGE( 1, level / 2, 30 );

    return level;
}

