    if ( ability == COMBAT_ABILITY )
    {
        level = 20;

        if ( ch->main_ability == COMBAT_ABILITY )
            level = 100;

        if ( ch->main_ability == HUNTING_ABILITY )
            level = 55;

        if ( ch->main_ability == ESPIONAGE_ABILITY )
            level = 5;

        level += ch->perm_con + ch->perm_str;
        rac_mod = ch->race->ability[0]; //combat

