            if ( ch->main_ability == PILOTING_ABILITY ) level = 10;
            if ( ch->main_ability == LEADERSHIP_ABILITY ) level = 50;
            level += ch->perm_int + ch->perm_cha*2;
            if ( ch->skill_level[FORCE_ABILITY] >= 2 )
            {
                switch ( ch->pcdata->fclass )
                {
                default:
                    break;
                case JEDI_SENTINEL:
                    level += 60;
                    break;
                case JEDI_CONSULAR:
                    level += 90;
                    break;
                case JEDI_SAGE:
                    level += 20;
                    break;
                case SITH_DARKLORD:
                    level += 40;
                    break;
                }
            }
            rac_mod = ch->race->ability[5]; //diplomacy
            level = ( rac_mod == -99 ? 0 : level + rac_mod );
            if ( ch->main_ability == ESPIONAGE_ABILITY ) level = URANGE(0, level - 55, level);
        } */

    if ( ability == ESPIONAGE_ABILITY )
    {
        level = 10;

        if ( ch->main_ability == ability )
            level = 100;

        if ( ch->main_ability == COMBAT_ABILITY )
            level = 25;

        if ( ch->main_ability == SLICER_ABILITY )
            level = 40;

        if ( ch->main_ability == ENGINEERING_ABILITY )
            level = 10;

        level += ch->perm_lck + ch->perm_dex + ch->perm_con;
        rac_mod = ch->race->ability[8]; //espionage
        level = ( rac_mod == -99 ? 0 : level + rac_mod );
    }

    if ( ability == SLICER_ABILITY )
    {
        level = 5;

        if ( ch->main_ability == ability )
            level = 100;

        if ( ch->main_ability == ESPIONAGE_ABILITY )
            level = 65;

        if ( ch->main_ability == PILOTING_ABILITY )
            level = 30;

        if ( ch->main_ability == ENGINEERING_ABILITY )
            level = 25;

        level += ch->perm_lck + ch->perm_int + ch->perm_wis;
        rac_mod = ch->race->ability[9]; //slicer
        level = ( rac_mod == -99 ? 0 : level + rac_mod );
    }

    if ( ability == MEDIC_ABILITY )
    {
        level = 5;

        if ( ch->main_ability == ability )
            level = 100;

        if ( ch->main_ability == ESPIONAGE_ABILITY )
            level = 5;

        if ( ch->main_ability == PILOTING_ABILITY )
            level = 20;

        if ( ch->main_ability == ENGINEERING_ABILITY )
            level = 30;

        level += ch->perm_wis + ch->perm_int * 2;
        rac_mod = ch->race->ability[10]; //medic
        level = ( rac_mod == -99 ? 0 : level + rac_mod );
    }

    if ( ability == SCIENCE_ABILITY )
    {
        level = 5;

        if ( ch->main_ability == ability )
            level = 100;

        if ( ch->main_ability == ENGINEERING_ABILITY )
            level = 30;

        level += ( int )( ch->perm_int * 2.3 + ch->perm_wis * 2.3 );

        if ( ch->skill_level[FORCE_ABILITY] >= 2 )
        {
            switch ( ch->pcdata->fclass )
            {
                default:
                    break;

                case JEDI_SAGE:
                    level += 50;
                    break;
            }
        }

        rac_mod = ch->race->ability[11]; //science
        level = ( rac_mod == -99 ? 0 : level + rac_mod );
    }

    if ( is_focus( ch, ability ) )
        level += 30;

    /* Should make sure that your max cant be below your current level */
    if ( ch->skill_level[ability] > level )
        level = ch->skill_level[ability];

    level = URANGE( 1, level, 150 );

    if ( ability == FORCE_ABILITY )
    {
        if ( ch->main_ability == ability )
            level = 20;
        else
            level = 0;

        level += ch->perm_frc * 5;

        // GRAL Why do we min set nats to 25?
        //  if ( level < 25 && xIS_SET(ch->race->flags,RFLAG_NATURALFORCE) )
        //    level = 25;
        // GRAL Dark lord always has the advantage or what?
        if ( ch->skill_level[FORCE_ABILITY] >= 2 && ch->pcdata->fclass == SITH_DARKLORD )
        {
            level += 15;
        }
    }

    if ( has_pcflag( ch, PCFLAG_CHILD ) && level > 1 )
        return URANGE( 1, level / 2, 30 );

    return level;
}
void advance_level( CHAR_DATA* ch, int ability, bool silent )
{
    char buf[MSL];
    int add_move = 0;
    int add_gold = 0;
    int add_frc = 0;
    bool topmove = FALSE;

    if ( ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_PURCHASE ) )
        silent = TRUE;

    /* Gral http://www.smaugmuds.org/index.php?a=topic&t=1951 100 or MAX_LEVEL */
    if ( ch->top_level < ch->skill_level[ability] && ch->top_level < 100 )
    {
        /* Gral http://www.smaugmuds.org/index.php?a=topic&t=1951 100 or MAX_LEVEL */
        ch->top_level = URANGE( 1, ch->skill_level[ability], 100 );
        topmove = TRUE;
    }

    /* No gold from force */
    if ( ability != FORCE_ABILITY )
    {
        add_gold = 10 * ch->skill_level[ability];
        ch->gold += add_gold;

        if ( !silent && !IS_NPC( ch ) )
            sql_credits_log( ch->name, "advance_level", add_gold, TRUE );
    }

    if ( ability == FORCE_ABILITY )
    {
        /*    add_frc   = ((get_curr_frc(ch) + get_curr_lck(ch))/2);
              add_frc   = UMAX( 10, add_frc );*/
        switch ( ch->pcdata->fclass )
        {
            case JEDI_GUARDIAN:
            case SITH_JUGGERNAUT:
                add_frc = 20; //Updated JEDI_GUARDIAN mana bonus due to Jan 2017 subclass upgrade -Gathorn 15Jan2017
                break;

            case JEDI_SENTINEL:
            case SITH_ASSASSIN:
                add_frc = 25;
                break;

            case JEDI_CONSULAR:
            case SITH_SORCERER:
                add_frc = 35;
                break;

            case JEDI_SAGE:
                add_frc = 30;
                break;

            case SITH_DARKLORD:
                add_frc = 30;
                break;

            default:
                add_frc = 5;
                break;
        }

        if ( ch->pcdata->fclass == JEDI_NONE )
            ch_println( ch, "You have not yet selected your force class.\nUntil you select one you will get 5 force points per level." );

        int tmpmana = ch->max_mana;
        ch->max_mana = get_max_mana( ch );
        ch->mana     += ch->max_mana - tmpmana;
    }

    if ( topmove )
    {
        add_move = number_range( 5, ( get_curr_con( ch ) + get_curr_dex( ch ) ) / 4 );
        add_move    = UMAX( 10, add_move );
        ch->max_move    += add_move;

        if ( ch->top_level == 5 )
        {
            if ( !silent )
                ch_println( ch, "&YOOC: &wDid you know? You can change your main class before level 30 using the &Gmainchange &wcommand." );
        }
        else if ( ch->top_level == 27 )
        {
            if ( ch->skill_level[FORCE_ABILITY] > 1 && ch->main_ability == HUNTING_ABILITY )
            {
                if ( !silent )
                    ch_println( ch, "&RWarning: &wOn reaching level 30 as a Bounty Hunter, any chance for force sensitivity will be &RREMOVED&w. If you wish to have a chance at this character being force-sensitive, please use the &Gmainchange &wcommand before you hit level 30." );
            }
        }
        else if ( ch->top_level == 29 )
        {
            if ( !silent )
                ch_println( ch, "&YOOC: &wIf you want to change your main class, now is your last chance! You can only use the &Gmainchange &wcommand until you hit level 30." );
        }
        else if ( ch->top_level == 30 && ch->main_ability == HUNTING_ABILITY )
        {
            if ( !IS_IMMORTAL( ch ) )
            {
                if ( ch->pcdata )
                {
                    lognormal( "Removing force (frc %d, level %d, mana %d, rank %d, class %d) from bounty hunter %s upon hitting level 30.", ch->perm_frc, ch->skill_level[FORCE_ABILITY], ch->max_mana, ch->pcdata->frank, ch->pcdata->fclass, ch->name );
                    ch->pcdata->frank = FRANK_NONE;
                    ch->pcdata->fclass = JEDI_NONE;
                }

                if ( ch->skill_level[FORCE_ABILITY] >= 2 || ch->perm_frc > 0 )
                {
                    FORCER_DATA* forcer = forcer_create( ch );
                    if ( forcer ) forcer_delete( forcer );
                }

                ch->skill_level[FORCE_ABILITY] = 0;
                ch->perm_frc = 0;
                ability = ABILITY_NONE;
                ch->max_mana = 0;
                ch->set_max_mana = 0;
                add_frc = 0;
                ch->mana = 0;

                for ( SKILL_DATA* skill = first_skill; skill; skill = skill->next )
                {
                    // when someone's level max lowers, reset skills they have above that level
                    if ( skill->guild == FORCE_ABILITY )
                        set_learned_pct( ch, skill, 0 );
                }

                if ( !silent )
                    ch_println( ch, "&RYou have chosen the life of a Bounty Hunter.\n\r&RThis character cannot be force-sensitive.&w" );
            }
        }
    }

    level_bonus( ch, ability );

    if ( ch->top_level < LEVEL_IMMORTAL && ability == FORCE_ABILITY )
    {
        snprintf( buf, MSL, "Your gain is: %d mana, raising you to %d.\n", add_frc, ch->max_mana );
        set_char_color( AT_WHITE, ch );

        if ( !silent )
            send_to_char( buf, ch );
    }
    else if ( ch->top_level < LEVEL_IMMORTAL && topmove )
    {
        snprintf( buf, MSL, "Your gain is: %d/%d mv and %d credits.\n", add_move, ch->max_move, add_gold );
        set_char_color( AT_WHITE, ch );

        if ( !silent )
            send_to_char( buf, ch );
    }
    else if ( ch->top_level < LEVEL_IMMORTAL )
    {
        snprintf( buf, MSL, "Your gain is: %d credits.\n", add_gold );
        set_char_color( AT_WHITE, ch );

        if ( !silent )
            send_to_char( buf, ch );
    }

    if ( !silent )
        do_save( ch, "-noalert" );

    account_update( ch );
    return;
}

void level_bonus( CHAR_DATA* ch, int ability )
{
    // Warriors are WYSIWYG. Keeps people from rolling for luck because they could otherwise
    // instantly see what their gains are.
    if ( xIS_SET( ch->race->flags, RFLAG_WARRIOR ) || has_pcflag( ch, PCFLAG_CG ) )
        return;

    // Gral changed from 1/30 to 1/60.
    // Right now it gives about 5 boosts per 150 level. Reduced to 2.5
    if ( number_range( 1, 60 ) != 1 )   /* No bonus this level */
        return;

    /* act( AT_YELLOW, "$n has recived a *LEVEL BONUS!*", ch, NULL, NULL, TO_ROOM ); */
    /* ch_println( ch, "&YYou have earned a &G-&R=&YLEVEL BONUS!&R=&G-&Y" ); */

    switch ( ability )
    {
        default:   /* GENERAL has no bonus */
            break;

        case COMBAT_ABILITY:
            /*
                Combat bonus, Damage muliplies in the next few fights.
                Doesn't last very long.
                Buffed up by Orion.
            */
            ch_println( ch, "&GAdrenaline surges through your body!&w" );
            ch->fbonus += 120;
            ch->hitroll++;

            if ( number_range( 1, 2 ) == 1 && ch->gain_str < 2 && ch->perm_str < 25 )
            {
                ch_println( ch, "&GYou feel stronger!&w" );
                ch->perm_str = UMIN( ch->perm_str+1, 25 );
                ch->gain_str++;
            }
            else if ( ch->gain_con < 2 && ch->perm_con < 25 )
            {
                ch_println( ch, "&GYour endurance grows ever stronger!&w" );
                ch->perm_con = UMIN( ch->perm_con+1, 25 );
                ch->gain_con++;
            }

            break;

        case PILOTING_ABILITY:
        case ENGINEERING_ABILITY:
            if ( ch->gain_dex < 2 && ch->perm_dex < 25 )
            {
                ch_println( ch, "&GYour coordination grows stronger and quicker!&w" );
                ch->perm_dex = UMIN( ch->perm_dex+1, 25 );
                ch->gain_dex++;
            }

            break;

        case HUNTING_ABILITY:
            if ( ch->gain_con < 2 && ch->perm_con < 25 )
            {
                ch_println( ch, "&GYour endurance grows ever stronger!&w" );
                ch->perm_con = UMIN( ch->perm_con+1, 25 );
                ch->gain_con++;
            }

            break;

        case SMUGGLING_ABILITY:
            if ( ch->main_ability == SMUGGLING_ABILITY )
            {
                if ( ch->perm_lck + 1 <= UMIN( 25, 22 + ch->race->lck_plus ) )
                {
                    ch_println( ch, "&GYou feel luckier!&w" );
                    ch->perm_lck++;
                }
            }
            else
            {
                if ( ch->perm_lck + 1 <= UMIN( 25, 20 + ch->race->lck_plus ) )
                {
                    ch_println( ch, "&GYou feel luckier!&w" );
                    ch->perm_lck++;
                }
            }

            break;

        case MEDIC_ABILITY:
        case SLICER_ABILITY:
            if ( ch->gain_wis < 2 && ch->perm_wis < 25 )
            {
                ch_println( ch, "&GYou grow in wisdom!&w" );
                ch->perm_wis = UMIN( ch->perm_wis+1, 25 );
                ch->gain_wis++;
            }

            break;

        case LEADERSHIP_ABILITY:
            if ( ch->gain_cha < 2 && ch->perm_cha < 25 )
            {
                ch_println( ch, "&GYour social skills and personality improve.&w" );
                ch->perm_cha = UMIN( ch->perm_cha+1, 25 );
                ch->gain_cha++;
            }

            break;

        case FORCE_ABILITY:

            /*  Force Bonus, Max mana increases  */
            /*  The original plan was mana, but thats weak. Why not let them
                get better at the force, just make that chance low? - Orion
            */

            // Gral As skills are restricted from learning with out a master that knows them
            //   why not let someone hit 25 frc
            // Ralen - line as it is currently blocks all our forcers from ever progressing past 100 or adepting skills at lvl 100.
            // New imm-manufactured blockage: lvl 110
            // if (number_percent() < chance && ch->perm_frc +1 <= UMIN(25,20+ch->race->frc_plus) )
            if ( ch->perm_frc <= 21 ) //Why did we make it rarer for people with less forcer to get a gain? C'mon.
            {
                ch->perm_frc++;
                ch_println( ch, "&GYour grasp on the force tightens!" );
            }

            break;

        case ESPIONAGE_ABILITY:
            if ( ch->gain_int < 2 && ch->perm_int < 25 )
            {
                ch_println( ch, "&GYour mind becomes sharper!&w" );
                ch->perm_int = UMIN( ch->perm_int+1, 25 );
                ch->gain_int++;
            }

            break;

        case SCIENCE_ABILITY:

            /*
                Science bonus, +1 int or +1 wis
            */
            if ( number_range( 1, 2 ) == 1 && ch->gain_int < 2 && ch->perm_int < 25 )
            {
                ch->perm_int = UMIN( ch->perm_int+1, 25 );
                ch->gain_int++;
                ch_println( ch, "&GYour mind becomes sharper!&w" );
            }
            else if ( ch->gain_wis < 2 && ch->perm_wis < 25 )
            {
                ch->perm_wis = UMIN( ch->perm_wis+1, 25 );
                ch->gain_wis++;
                ch_println( ch, "&GYou grow in wisdom!&w" );
            }

            break;
    }

    return;
}

void gain_exp( CHAR_DATA* ch, int gain, int ability, bool groupgain )
{
    CHAR_DATA* victim;

    if ( IS_NPC( ch ) )
        return;

    if ( has_feat( ch, cache_skill( "scientific mind", &skill_scientific_mind ) ) )
    {
        gain += gain / 10 * 2;
        ch_println( ch, "&GYou gain extra experience due to your scientific mind." );
    }

    if ( ability == FORCE_ABILITY && get_trust( ch ) < sysdata.log_level )
    {
        if ( ch->pcdata->fclass == JEDI_NONE && ch->skill_level[ability] > 1 ) // > Awaken_force needs to get you past level 1 before this should kick in. Otherwise, this breaks awaken_force. - Gathorn 25Jun17
        {
            ch_println( ch, "&wYou cannot gain any more experience until you pick a force sub-class.\nSee &CHELP SUB-CLASS.&w" );
            return;
        }

        if ( ch->pcdata->frank < FRANK_KNIGHT && ch->skill_level[ability] >= 60 )
        {
            ch_println( ch, "You cannot gain any more experience until you enter knighthood." );
            return;
        }

        if ( sysdata.force_levelsperday > 0 )
        {
            FORCER_DATA* forcer = forcer_create( ch );
            // Limit how many levels can be gained per day they've awakened. This just looks
            // at the diff between now and then so if they skip a day, they can make up for it.
            int days_since_created = (int)(current_time - ch->created_at) / 86400;
            int days_since_awakened = (int)(current_time - ch->pcdata->awakened_at) / 86400;
            int max_force_level = ( days_since_awakened + 1 ) * sysdata.force_levelsperday;

            // If we're dealing with imm-set characters who are way off, recompute their awakened_at date
            if ( ch->skill_level[FORCE_ABILITY] > max_force_level && forcer && forcer->source == FROLL_MSET )
            {
                int new_max_force_level = ch->skill_level[FORCE_ABILITY] + ( days_since_created * sysdata.force_levelsperday );
                if ( ( new_max_force_level % 3 ) > 0 ) new_max_force_level += ( 3 - ( new_max_force_level % 3 ) );
                int diff = ( new_max_force_level - max_force_level );
                ch->pcdata->awakened_at -= ( ( (int)( (double)diff / sysdata.force_levelsperday )) * 86400 );
                days_since_awakened = (int)(current_time - ch->pcdata->awakened_at) / 86400;
                max_force_level = ( days_since_awakened + 1 ) * sysdata.force_levelsperday;
                save_char_obj( ch, TRUE );
            }

            if ( ch->skill_level[FORCE_ABILITY] >= max_force_level )
            {
                ch_println( ch, "You have learned as much as you can about the Force today. It will take time for your mind to expand." );
                return;
            }
        }
    }

    if ( ability < 0 || ability > MAX_ABILITY )
        return;

    /* Students can share their masters XP */
    victim = fetch_apprentice( ch, TRUE );

    if ( ability == FORCE_ABILITY && victim )
    {
        int xp = gain;
        xp = apply_xp_sink( victim, xp, ability );
        gain_exp( victim, xp, ability, FALSE );
        ch_println( victim, "You gain %d force experience from your masters teachings.", xp );
        ch_println( ch, "Your apprentice gains %d force experience from your teachings.", xp );
    }

    /* Rojan leadership module 2008 */
    if ( groupgain )
        group_gain( ch, ability );

    if ( is_focus( ch, ability ) )
        gain *= 2;

    ch->experience[ability] = UMAX( 0, ch->experience[ability] + gain );

    if ( NOT_AUTHED( ch ) && ch->experience[ability] >= exp_level( ch->skill_level[ability] + 1 ) )
    {
        ch_println( ch, "You can not ascend to a higher level until you are authorized." );
        ch->experience[ability] = ( exp_level( ch->skill_level[ability] + 1 ) - 1 );
        return;
    }

    debug( "gain_exp %s is gaining %d %s xp", ch->name, gain, flag_value_name( ability_name, ability ) );

    while ( ch->experience[ability] >= exp_level( ch->skill_level[ability] + 1 ) )
    {
        if ( ch->skill_level[ability] >= max_level( ch, ability ) )
        {
            ch->experience[ability] = ( exp_level( ch->skill_level[ability] + 1 ) - 1 );
            return;
        }

        set_char_color( AT_WHITE + AT_BLINK, ch );
        //GRAL Attempt to fix the color bug of black when logging in
        ch_println( ch, "&WYou have now obtained %s level %d!", flag_value_name( ability_name, ability ), ++ch->skill_level[ability] );
        advance_level( ch, ability, FALSE );
        // if ( get_trust( ch ) > lvl && lvl == LEVEL_HERO-1 && (!ch->desc || !ch->desc->account ) )
        //{
        //    ch_println( ch, "When you hit level 100 you will have to associate this character with an account to continue playing." );
        //}
        //else if ( get_trust( ch ) > lvl && lvl > LEVEL_HERO - 10 && (!ch->desc || !ch->desc->account) )
        // {
        //     ch_println( ch, "You have %d more levels to raise before you need an account.", LEVEL_HERO - get_trust( ch ) );
        // }
    }

    return;
}

int apply_xp_sink( CHAR_DATA* ch, int gain, int ability )
{
    int xp = 0, abil = 0;

    if ( !ch )
        return gain;

    if ( !ch->pcdata )
        return gain;

    xp = gain;

    for ( abil = 0; abil < MAX_ABILITY; abil++ )
    {
        ch->exp_sink[abil] = UMAX( 0, ch->exp_sink[abil] );

        if ( abil == ability )
        {
            xp = gain - ( int )( ( double )( gain / 100 ) * ( double )( ch->exp_sink[abil] * 10 ) );
            ch->exp_sink[abil] = URANGE( 0, ( ch->exp_sink[abil] + 1 ), 10 );
        }

        if ( abil == LEADERSHIP_ABILITY )
        {
            ch->exp_sink[abil] = UMAX( 0, ( ch->exp_sink[abil] - 1 ) );
        }

        if ( ch->main_ability == LEADERSHIP_ABILITY )
        {
            ch->exp_sink[abil] = UMAX( 0, ( ch->exp_sink[abil] - 1 ) );
        }

        if ( abil == COMBAT_ABILITY )
        {
            ch->exp_sink[abil] = UMAX( 0, ( ch->exp_sink[abil] - 1 ) );
        }

        // The check here was removed - it allowed you to spam other skills every other time to reset the exp 1 - very exploitable and rather useless
        // New check to unrape leadership mains.
        // Another new check to unrape combat leveling. Sinks too fast otherwise, too many factors at play
    }

    return xp;
}
/*
    Regeneration stuff.
*/
int get_hit_gain( CHAR_DATA* ch )
{
    int gain, x = 0, z = 0;

    for ( x = 0; x <= MAX_MED; x++ )
        if ( xIS_SET( ch->w_wound, x ) )
            z++;

    while ( z > 0 )
    {
        ch->hit = URANGE( -499, ch->hit - number_range( 10, 30 ), ch->max_hit );
        ch_println( ch, "&RYour wounds are bleeding! Seek medical attention!" );

        if ( IS_NPC( ch ) && ch->hit <= 0 )
            raw_kill( ch, ch );
        else if ( ch->hit <= -499 && !isFighting( ch ) ) // Don't kill them as long as they have a PVP timer
            raw_kill( ch, ch );

        if ( char_extracted( ch ) )
            return 0;

        z--;

        if ( z == 0 )
        {
            make_bloodstain( ch );
            return 0;
        }
    }

    if ( IS_NPC( ch ) )
    {
        gain = ch->top_level;

        if ( xIS_SET( ch->act, ACT_DROID ) || droid_from_mob( ch ) != NULL )
            gain = 0; // No self-healing droids!
    }
    else
    {
        gain = UMIN( 5, ch->top_level );

        if ( xIS_SET( ch->in_room->flags, ROOM_NODEATH ) )
        {
            if ( ch->position == POS_DEAD )
                return UMIN( ( get_curr_con( ch ) + 1 ) * 2, ch->max_hit - ch->hit );

            if ( ch->position == POS_MORTAL )
                return UMIN( ( get_curr_con( ch ) + 1 ) * 3, ch->max_hit - ch->hit );

            if ( ch->position == POS_INCAP )
                return UMIN( ( get_curr_con( ch ) + 1 ) * 2, ch->max_hit - ch->hit );
        }

        switch ( ch->position )
        {
            case POS_DEAD:
                if ( has_feat( ch, cache_skill( "quick healer", &skill_quick_healer ) ) )
                    gain = 0;

                break;

            case POS_MORTAL:
                if ( has_feat( ch, cache_skill( "quick healer", &skill_quick_healer ) ) )
                {
                    gain = 10;
                    tune( "quick_healer: %s is gaining %d extra hp while mortally wounded due to quick_healer feat", ch->name, gain );
                }
                else
                {
                    gain = 0;
                }

                return gain;

            case POS_INCAP:
                if ( has_feat( ch, cache_skill( "quick healer", &skill_quick_healer ) ) )
                {
                    gain = 15;
                    tune( "quick_healer: %s is gaining %d extra hp while incapacitated due to quick_healer feat", ch->name, gain );
                }
                else
                {
                    gain = 0;
                }

                return gain;

            case POS_STUNNED:
                gain = URANGE( 1, get_curr_con( ch ) / 5, 5 );

                if ( has_feat( ch, cache_skill( "quick healer", &skill_quick_healer ) ) )
                {
                    int modifier;
                    modifier = gain * 4;
                    gain += modifier;
                    tune( "quick_healer: %s is gaining %d extra hp while stunned due to quick_healer feat", ch->name, modifier );
                }

                return gain;

            case POS_SLEEPING:
                gain = get_curr_con( ch ) * 4;

                if ( has_cyber_flag( ch, CYBER_RECOVER ) )
                    gain *= 2;

                break;

            case POS_RESTING:
                gain = get_curr_con( ch ) * 3;

                if ( has_cyber_flag( ch, CYBER_RECOVER ) )
                {
                    gain *= 2;
                }

                break;

            default:
                gain = get_curr_con( ch ) * 2;
                break;
        }

        if ( gain <= 0 )
            return gain;
    }

    if ( IS_AFFECTED( ch, AFF_POISON ) )
    {
        if ( gain > 0 )
            gain /= 4; // Reduce gains when poisoned
        else
            gain *= 2; // Multiply losses when poisoned
    }

    if ( has_feat( ch, cache_skill( "quick healer", &skill_quick_healer ) ) )
    {
        int modifier = gain * 2;
        gain += modifier;
        tune( "quick_healer: %s is gaining %d extra hp due to quick_healer feat", ch->name, modifier );
    }

    return UMIN( gain, ch->max_hit - ch->hit );
}

int hit_gain( CHAR_DATA* ch )
{
    if ( !ch )
    {
        bug( "hit_gain: null ch!" );
        return 0;
    }

    int gain = get_hit_gain( ch );
    tune( "hit_gain: %s gaining %d hp", ch->name, gain );
    return gain;
}

int mana_gain( CHAR_DATA* ch )
{
    int gain;

    if ( IS_NPC( ch ) )
    {
        gain = ch->top_level;
    }
    else
    {
        if ( ch->skill_level[FORCE_ABILITY] <= 1 )
            return ( 0 - ch->mana );

        if ( has_pcflag( ch, PCFLAG_NO_SENSE ) )
            return 0;

        gain = UMIN( 2, ch->skill_level[FORCE_ABILITY] / 2 );

        if ( ch->position < POS_SLEEPING )
            return 0;

        switch ( ch->position )
        {
            case POS_SLEEPING:
                gain += get_curr_int( ch ) * 4;
                break;

            case POS_RESTING:
                gain += get_curr_int( ch ) * 2;
                break;
        }

        if ( ch->pcdata->condition[COND_FULL]   == 0 )
            gain /= 2;

        if ( ch->pcdata->condition[COND_THIRST] == 0 )
            gain /= 2;
    }

    if ( IS_AFFECTED( ch, AFF_POISON ) )
        gain /= 4;

    if ( has_cyber_flag( ch, CYBER_RECOVER ) )
        gain *= 3;

    if ( IS_AFFECTED( ch, AFF_CLARITY ) )
        gain *= 4;

    return UMIN( gain, ch->max_mana - ch->mana );
}

int move_gain( CHAR_DATA* ch )
{
    int gain = 0;

    if ( get_trust( ch ) > 100 ) /* Immortals */
        return ch->max_move;

    if ( IS_NPC( ch ) )
    {
        gain = ch->top_level;
    }
    else
    {
        gain = UMAX( 15, 2 * ch->top_level );

        switch ( ch->position )
        {
            default:
                return get_curr_dex( ch ) * 15;

            case POS_DEAD:
                return 0;

            case POS_MORTAL:
                return -1;

            case POS_INCAP:
                return -1;

            case POS_STUNNED:
                return 1;

            case POS_SLEEPING:
                return get_curr_dex( ch ) * 35;
                break;

            case POS_RESTING:
                return get_curr_dex( ch ) * 25;
                break;
        }

        if ( ch->pcdata->condition[COND_FULL]   == 0 )
            gain /= 2;

        if ( ch->pcdata->condition[COND_THIRST] == 0 )
            gain /= 2;
    }

    if ( IS_AFFECTED( ch, AFF_POISON ) )
        gain /= 4;

    return UMIN( gain, ch->max_move - ch->move );
}

void update_blood_toxicity( CHAR_DATA* ch )
{
    if ( !ch->pcdata )
        return;

    if ( ch->pcdata->blood_toxicity == 0 )
        return;

    for ( AFFECT_DATA* af = ch->first_affect; af; af = af->next )
        if ( af->type >= TYPE_HERB && af->type < TYPE_PERSONAL )
            return;

    bool has_withdrawal = IS_AFFECTED( ch, AFF_WITHDRAWAL );
    AFFECT_DATA af;
    af.type      = -1;
    af.duration  = 10;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_WITHDRAWAL );

    switch ( ( ( int ) ch->pcdata->blood_toxicity ) / 25 )
    {
        case 1: // 25-49

            // Take slight mental state penalty
            if ( ch->mental_state < 30 )
                worsen_mental_state( ch, 1 );

            if ( has_withdrawal )
                break;

            switch ( number_range( 1, 5 ) )
            {
                case 1:
                    act( AT_YELLOW, "You feel slightly weaker.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_STR;
                    af.modifier  = -2;
                    break;

                case 2:
                    act( AT_YELLOW, "You feel slightly nauseous.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_CON;
                    af.modifier  = -2;
                    break;

                case 3:
                    act( AT_YELLOW, "Your movements seem to require more effort.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_DEX;
                    af.modifier  = -2;
                    break;

                case 4:
                    act( AT_YELLOW, "Coordination becomes more difficult, and you feel less accurate.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_HITROLL;
                    af.modifier  = -5;
                    break;

                case 5:
                    act( AT_YELLOW, "Your hands feel weaker.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_DAMROLL;
                    af.modifier  = -5;
                    break;
            }

            affect_to_target( ch, CHAR_AFFECT, &af );
            break;

        case 2: // 50-74

            // Take moderate mental state and hp penalties
            if ( ch->mental_state < 60 )
                worsen_mental_state( ch, 1 );

            if ( ch->hit > 100 )
                ch->hit = URANGE( 1, ch->hit - 50, ch->max_hit );

            if ( ch->move > 100 )
                ch->move = URANGE( 1, ch->move - 25, ch->max_move );

            if ( has_withdrawal )
                break;

            switch ( number_range( 1, 5 ) )
            {
                case 1:
                    act( AT_YELLOW, "You suddenly feel weaker.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_STR;
                    af.modifier  = -5;
                    break;

                case 2:
                    act( AT_YELLOW, "You begin to feel ill.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_CON;
                    af.modifier  = -5;
                    break;

                case 3:
                    act( AT_YELLOW, "Your movements slow.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_DEX;
                    af.modifier  = -5;
                    break;

                case 4:
                    act( AT_YELLOW, "It suddenly seems harder to coordinate.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_HITROLL;
                    af.modifier  = -20;
                    break;

                case 5:
                    act( AT_YELLOW, "Your hands are shaking, and your strength is fading away.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_DAMROLL;
                    af.modifier  = -20;
                    break;
            }

            xSET_BIT( af.bitvector, AFF_POISON );
            affect_to_target( ch, CHAR_AFFECT, &af );
            break;

        case 3: // 75-99

            // Take significant mental state and hp penalties
            if ( ch->mental_state < 90 )
                worsen_mental_state( ch, 1 );

            if ( ch->hit > 100 )
                ch->hit = URANGE( 1, ch->hit - 100, ch->max_hit );

            if ( ch->move > 100 )
                ch->move = URANGE( 1, ch->move - 50, ch->max_move );

            if ( has_withdrawal )
                break;

            switch ( number_range( 1, 5 ) )
            {
                case 1:
                    act( AT_YELLOW, "Your limbs feel weak and wobbly.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_STR;
                    af.modifier  = -12;
                    break;

                case 2:
                    act( AT_YELLOW, "A feeling of intense nausea and weakness washes over your body.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_CON;
                    af.modifier  = -12;
                    break;

                case 3:
                    act( AT_YELLOW, "Your movements feel awkward and clumsy.", ch, NULL, NULL, TO_CHAR );
                    af.location  = APPLY_DEX;
                    af.modifier  = -12;
                    break;

                case 4:
                    act( AT_YELLOW, "Your surroundings blur. All you see is colorful shapes... then, darkness.", ch, NULL, NULL, TO_CHAR );
                    xSET_BIT( af.bitvector, AFF_BLIND );
                    af.location  = APPLY_NONE;
                    af.modifier  = 0;
                    break;

                case 5:
                    act( AT_YELLOW, "Your pulse slows and you feel extremely drowsy.", ch, NULL, NULL, TO_CHAR );
                    xSET_BIT( af.bitvector, AFF_SLEEP );
                    af.location  = APPLY_NONE;
                    af.modifier  = 0;

                    if ( ch->position == POS_STANDING || ch->position == POS_RESTING || ch->position == POS_SITTING )
                    {
                        ch->position = POS_SLEEPING;
                        act( AT_ACTION, "You feel lightheaded... and then fall to the ground, passed out.", ch, NULL, NULL, TO_CHAR );
                        act( AT_YELLOW, "$n wobbles momentarily, then faints.", ch, NULL, NULL, TO_ROOM );
                    }

                    break;
            }

            xSET_BIT( af.bitvector, AFF_POISON );
            affect_to_target( ch, CHAR_AFFECT, &af );
            break;

        case 4: // Perfect 100
            act( AT_BLOOD, "Your surroundings blur suddenly as severe withdrawal kicks in.", ch, NULL, NULL, TO_CHAR );
            act( AT_ACTION, "The last thing you remember is falling... colors... pain...", ch, NULL, NULL, TO_CHAR );
            act( AT_RED, "$n suddenly collapses, immediately passing out while shaking and breathing heavily.", ch, NULL, NULL, TO_ROOM );
            ch->mental_state = URANGE( 30, ch->mental_state + 25, 100 );
            ch->hit = -1;
            ch->position = POS_STUNNED;
            ch->pcdata->blood_toxicity = 90;
            af.location  = APPLY_NONE;
            af.modifier  = 0;
            af.duration  = 30;
            xSET_BIT( af.bitvector, AFF_PARALYSIS );
            xSET_BIT( af.bitvector, AFF_BLIND );
            xSET_BIT( af.bitvector, AFF_SLEEP );
            affect_to_target( ch, CHAR_AFFECT, &af );
            break;
    }

    // By default, this wears off slightly slower than affects with the same duration.
    double reduction = 0.75;

    if ( has_cyber_flag( ch,  CYBER_IMMUNE ) )
        reduction = 1.;

    ch->pcdata->blood_toxicity = UMAX( 0, ch->pcdata->blood_toxicity - reduction );
}

void gain_condition( CHAR_DATA* ch, int iCond, int value )
{
    int condition;
    ch_ret retcode = 0;

    if ( value == 0 || IS_NPC( ch ) || get_trust( ch ) >= LEVEL_IMMORTAL || NOT_AUTHED( ch ) )
        return;

    condition                   = ch->pcdata->condition[iCond];
    ch->pcdata->condition[iCond]    = URANGE( 0, condition + value, 48 );

    if ( !sysdata.hunger )
    {
        if ( iCond == COND_FULL || iCond == COND_THIRST )
            ch->pcdata->condition[iCond] = UMAX( 4, ch->pcdata->condition[iCond] );
    }

    if ( ch->pcdata->condition[iCond] == 0 )
    {
        switch ( iCond )
        {
            case COND_FULL:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_HUNGRY, ch );
                    ch_println( ch, "You are STARVING!" );
                    act( AT_HUNGRY, "$n is starved half to death!", ch, NULL, NULL, TO_ROOM );
                    worsen_mental_state( ch, 1 );
                    retcode = damage( ch, ch, 5, TYPE_UNDEFINED );
                }

                break;

            case COND_THIRST:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_THIRSTY, ch );
                    ch_println( ch, "You are DYING of THIRST!" );
                    act( AT_THIRSTY, "$n is dying of thirst!", ch, NULL, NULL, TO_ROOM );
                    worsen_mental_state( ch, 2 );
                    retcode = damage( ch, ch, 5, TYPE_UNDEFINED );
                }

                break;

            case COND_DRUNK:
                if ( condition != 0 )
                {
                    set_char_color( AT_SOBER, ch );
                    ch_println( ch, "You are sober." );
                }

                retcode = rNONE;
                break;

            default:
                bug( "Gain_condition: invalid condition type %d", iCond );
                retcode = rNONE;
                break;
        }
    }

    if ( retcode != rNONE )
        return;

    if ( ch->pcdata->condition[iCond] == 1 )
    {
        switch ( iCond )
        {
            case COND_FULL:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_HUNGRY, ch );
                    ch_println( ch, "You are really hungry." );
                    act( AT_HUNGRY, "You can hear $n's stomach growling.", ch, NULL, NULL, TO_ROOM );

                    if ( number_bits( 1 ) == 0 )
                        worsen_mental_state( ch, 1 );
                }

                break;

            case COND_THIRST:
                if ( ch->top_level <= LEVEL_AVATAR  )
                {
                    set_char_color( AT_THIRSTY, ch );
                    ch_println( ch, "You are really thirsty." );
                    worsen_mental_state( ch, 1 );
                    act( AT_THIRSTY, "$n looks a little parched.", ch, NULL, NULL, TO_ROOM );
                }

                break;

            case COND_DRUNK:
                if ( condition != 0 )
                {
                    set_char_color( AT_SOBER, ch );
                    ch_println( ch, "You are feeling a little less light headed." );
                }

                break;
        }
    }

    if ( ch->pcdata->condition[iCond] == 2 )
    {
        switch ( iCond )
        {
            case COND_FULL:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_HUNGRY, ch );
                    ch_println( ch, "You are hungry." );
                }

                break;

            case COND_THIRST:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_THIRSTY, ch );
                    ch_println( ch, "You are thirsty." );
                }

                break;
        }
    }

    if ( ch->pcdata->condition[iCond] == 3 )
    {
        switch ( iCond )
        {
            case COND_FULL:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_HUNGRY, ch );
                    ch_println( ch, "You are a mite peckish." );
                }

                break;

            case COND_THIRST:
                if ( ch->top_level <= LEVEL_AVATAR )
                {
                    set_char_color( AT_THIRSTY, ch );
                    ch_println( ch, "You could use a sip of something refreshing." );
                }

                break;
        }
    }

    return;
}

/*
    Mob autonomous action.
    This function takes 25% to 35% of ALL Mud cpu time.
*/
void mobile_update( void )
{
    char buf[MSL];
    CHAR_DATA* ch, *tch, *next_tch, *xch;
    EXIT_DATA* pexit;
    int door;
    ch_ret     retcode;
    retcode = rNONE;
    sysdata.noidle = 0;

    /* Examine all mobs. */
    for ( ch = last_char; ch; ch = gch_prev )
    {
        set_cur_char( ch );

        if ( ch == first_char && ch->prev )
        {
            bug( "mobile_update: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;

        if ( gch_prev && gch_prev->next != ch )
        {
            snprintf( buf, MSL, "FATAL: Mobile_update: %s->prev->next doesn't point to ch.",
                     ch->name );
            bug( buf, 0 );
            bug( "Short-cutting here", 0 );
            gch_prev = NULL;
            ch->prev = NULL;
            do_yell( ch, "Thoric says, 'Prepare for the worst!'" );
        }

        if ( !IS_NPC( ch ) )
        {
            drunk_randoms( ch );
            halucinations( ch );

            if ( ch->spirit && !ch->manifest && ch->first_carrying )
            {
                de_equip_char( ch );
                de_cyber_char( ch );
                do_drop( ch, "all" );
                ch_println( ch, "Curses, you are intangible." );
            }

            /* Fix here to prevent ghosts created from this method from continually being spammed */
            if ( !IS_NPC( ch ) && ch->pcdata->clone > 2 && get_trust( ch ) <= LEVEL_HERO && !ch->spirit )
            {
                ch_println( ch, "&zThe DNA inside your cells has been weakened by the cloning of a clone..." );
                ch_println( ch, "Your clone dies, unable to continue to live!" );
                bug( "%s hit max of 2 clones. Destroying pfile.", ch->name );
                /*whistle*/
                ch->gold = 0;
                bh_char = ch;
                raw_kill( ch, ch );
                bh_char = NULL;
            }

            continue;
        }
        else
        {
            switch ( ch->position )
            {
                case POS_SLEEPING:
                    better_mental_state( ch, 9 );
                    break;

                case POS_RESTING:
                    better_mental_state( ch, 6 );
                    break;

                case POS_SITTING:
                case POS_MOUNTED:
                    better_mental_state( ch, 4 );
                    break;

                case POS_STANDING:
                    better_mental_state( ch, 2 );
                    break;

                case POS_FIGHTING:
                    if ( number_bits( 2 ) == 0 )
                        better_mental_state( ch, 2 );

                    break;
            }

            if ( !droid_from_mob( ch ) )
            {                
                if ( ch->master )
                {    
                    if ( ch->in_room && ch->master->in_room && ch->in_room != ch->master->in_room )
                    {
                        if ( ch->separated == 0 )
                            ch->separated = time( 0 );
                        else if ( ch->separated < ( current_time - 600 ) )
                        {
                            extract_char( ch );
                            continue;
                        }
                    }
                    else if ( ch->separated != 0 )
                        ch->separated = 0;
                }
            }
        }

        if ( !ch->in_room
                ||   IS_AFFECTED( ch, AFF_PARALYSIS ) )
            continue;
        else if ( IS_AFFECTED( ch, AFF_CHARM ) )
        {
            if ( !ch->master )
            {
                stop_follower( ch, true );
                continue;
            }
        }

        /* Clean up 'animated corpses' that are not charmed' - Scryn */

        if ( ch->pIndexData->vnum == 5 && !IS_AFFECTED( ch, AFF_CHARM ) )
        {
            if ( ch->in_room->first_person )
                act( AT_MAGIC, "$n returns to the dust from whence $e came.", ch, NULL, NULL, TO_ROOM );

            if ( IS_NPC( ch ) ) /* Guard against purging switched? */
                extract_char( ch );

            continue;
        }

        if ( ch->held == TRUE )
        {
            do_struggle( ch, "" );
            continue;
        }

        if ( !xIS_SET( ch->act, ACT_RUNNING )
                &&   !xIS_SET( ch->act, ACT_SENTINEL )
                &&   !ch->fighting && ch->hunting )
        {
            /* Gral http://www.smaugmuds.org/index.php?a=topic&t=1951 100 or MAX_LEVEL */
            if (  ch->top_level < 20 )
                WAIT_STATE( ch, 6 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 40 )
                WAIT_STATE( ch, 5 * PULSE_PER_SECOND );
            else if (  ch->top_level < 60 )
                WAIT_STATE( ch, 4 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 80 )
                WAIT_STATE( ch, 3 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 100 )
                WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
            else
                WAIT_STATE( ch, 1 * PULSE_PER_SECOND );

            hunt_victim( ch );
            continue;
        }
        else if ( !xIS_SET( ch->act, ACT_RUNNING )
                  &&   !xIS_SET( ch->act, ACT_SENTINEL )
                  &&   !ch->fighting && ch->tracking )
        {
            /* Gral http://www.smaugmuds.org/index.php?a=topic&t=1951 100 or MAX_LEVEL */
            if (  ch->top_level < 20 )
                WAIT_STATE( ch, 6 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 40 )
                WAIT_STATE( ch, 5 * PULSE_PER_SECOND );
            else if (  ch->top_level < 60 )
                WAIT_STATE( ch, 4 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 80 )
                WAIT_STATE( ch, 3 * PULSE_PER_SECOND );
            else    if (  ch->top_level < 100 )
                WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
            else
                WAIT_STATE( ch, 1 * PULSE_PER_SECOND );

            track_victim( ch );
            continue;
        }
        else if ( !ch->fighting && !ch->hunting && !ch->tracking
                  && !xIS_SET( ch->act, ACT_RUNNING )
                  && ch->was_sentinel && ch->position >= POS_STANDING && !xIS_SET( ch->act, ACT_MOUNTED ) )
        {
            act( AT_ACTION, "$n leaves.", ch, NULL, NULL, TO_ROOM );
            char_from_room( ch );
            char_to_room( ch, ch->was_sentinel );
            act( AT_ACTION, "$n arrives.", ch, NULL, NULL, TO_ROOM );
            xSET_BIT( ch->act, ACT_SENTINEL );
            ch->was_sentinel = NULL;
        }

        /* Reworked for new spec system :( - Orion */
        if ( !xIS_SET( ch->act, ACT_RUNNING ) && ch->spec_fun )
        {
            if ( ( *ch->spec_fun ) ( ch ) )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        if ( !xIS_SET( ch->act, ACT_RUNNING ) && ch->spec_2 )
        {
            if ( ( *ch->spec_2 ) ( ch ) )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        if ( !xIS_SET( ch->act, ACT_RUNNING ) && ch->spec_3 )
        {
            if ( ( *ch->spec_3 ) ( ch ) )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        if ( !xIS_SET( ch->act, ACT_RUNNING ) && ch->spec_4 )
        {
            if ( ( *ch->spec_4 ) ( ch ) )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        /* Check for mudprogram script on mob */
        if ( ch->pIndexData->progtypes & SCRIPT_PROG )
        {
            mprog_script_trigger( ch );
            continue;
        }

        if ( ch != cur_char )
        {
            bug( "%s: ch != cur_char after spec_fun", FUNC );
            continue;
        }

        /* That's all for sleeping / busy monster */
        if ( ch->position != POS_STANDING )
            continue;

        if ( xIS_SET( ch->act, ACT_MOUNTED ) )
        {
            if ( xIS_SET( ch->act, ACT_AGGRESSIVE ) )
                do_emote( ch, "snarls and growls." );

            continue;
        }

        /* MOBprogram random trigger */
        if ( ch->in_room->area->nplayer > 0 )
        {
            mprog_random_trigger( ch );

            if ( ch->position < POS_STANDING )
                continue;

            if ( char_extracted( ch ) )
                continue;

            lua_trigger_on_ch_random( ch );

            if ( ch->position < POS_STANDING )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        /* MOBprogram hour trigger: do something for an hour */
        mprog_hour_trigger( ch );

        if ( char_extracted( ch ) )
            continue;

        rprog_hour_trigger( ch );

        if ( char_extracted( ch ) )
            continue;

        if ( ch->position < POS_STANDING )
            continue;

        /* Scavenge */
        if ( xIS_SET( ch->act, ACT_SCAVENGER )
                &&   ch->in_room->first_content
                &&   number_bits( 2 ) == 0 )
        {
            OBJ_DATA* obj;
            OBJ_DATA* obj_best;
            int max;
            max         = 1;
            obj_best    = NULL;

            for ( obj = ch->in_room->first_content; obj; obj = obj->next_content )
            {
                if ( IS_OBJ_STAT( obj, ITEM_PROTOTYPE ) && !xIS_SET( ch->act, ACT_PROTOTYPE ) )
                    continue;

                if ( CAN_WEAR( obj, ITEM_TAKE ) && obj->cost > max && !IS_OBJ_STAT( obj, ITEM_BURIED ) )
                {
                    obj_best = obj;
                    max = obj->cost;
                }
            }

            if ( obj_best )
            {
                obj_from_room( obj_best );
                obj_to_char( obj_best, ch );
                act( AT_ACTION, "$n gets $p.", ch, obj_best, NULL, TO_ROOM );
                lua_trigger_on_obj( obj_best, LUA_TRIGGER_OBJ_ON_GET );
            }
        }

        /* Wander */
        if ( !xIS_SET( ch->act, ACT_RUNNING )
                &&   !xIS_SET( ch->act, ACT_SENTINEL )
                &&   !xIS_SET( ch->act, ACT_PROTOTYPE )
                &&   !ch->master && !ch->leader
                && ( door = number_bits( 5 ) ) <= 9
                && ( pexit = get_exit( ch->in_room, door ) ) != NULL
                &&   pexit->to_room
                &&   !is_ai( ch, AI_SOLDIER_LIGHT )
                &&   !xIS_SET( pexit->flags, EX_WINDOW )
                &&   !xIS_SET( pexit->flags, EX_CLOSED )
                &&   MOB_CAN_ENTER( pexit->to_room )
                && !xIS_SET( ch->act, ACT_MOUNTED )
                && ( !xIS_SET( ch->act, ACT_STAY_AREA ) || pexit->to_room->area == ch->in_room->area ) )
        {
            retcode = move_char( ch, pexit, 0, FALSE );

            /*  If ch changes position due
                to it's or someother mob's
                movement via MOBProgs,
                continue - Kahn */
            if ( retcode != rNONE || xIS_SET( ch->act, ACT_SENTINEL ) || ch->position < POS_STANDING )
                continue;

            if ( char_extracted( ch ) )
                continue;
        }

        /* Flee */
        if ( ch->hit < ch->max_hit / 2
                && ( door = number_bits( 4 ) ) <= 9
                && ( pexit = get_exit( ch->in_room, door ) ) != NULL
                &&   pexit->to_room
                &&   !xIS_SET( pexit->flags, EX_CLOSED )
                &&   MOB_CAN_ENTER( pexit->to_room ) )
        {
            CHAR_DATA* rch;
            bool found;
            found = FALSE;

            for ( rch  = ch->in_room->first_person;
                    rch;
                    rch  = rch->next_in_room )
            {
                if ( is_fearing( ch, rch ) )
                {
                    switch ( number_bits( 2 ) )
                    {
                        case 0:
                            snprintf( buf, MSL, "Get away from me!" );
                            break;

                        case 1:
                            snprintf( buf, MSL, "Leave me be!" );
                            break;

                        case 2:
                            snprintf( buf, MSL, "Someone is trying to kill me!  Help!" );
                            break;

                        case 3:
                            snprintf( buf, MSL, "Someone save me!" );
                            break;
                    }

                    do_yell( ch, buf );
                    found = TRUE;
                    break;
                }
            }

            if ( found )
                retcode = move_char( ch, pexit, 0, FALSE );
        }

        // Start hospitalizing injured folk
        if ( char_extracted( ch ) || !ch->in_room )
            continue;

        if ( ch->position < POS_STANDING )
            continue;

        // If the triggering character is an NPC and is not a called mob, let's start
        // hospitalizing injured players.
        if ( IS_NPC( ch ) && ch->pIndexData != NULL && ch->pIndexData->vnum != 97 )
        {
            for ( tch = ch->in_room->first_person; tch; tch = next_tch )
            {
                next_tch = tch->next_in_room;

                // Skip themselves
                if ( tch == ch )
                    continue;

                // If they've actively fighting, skip them
                if ( tch->position == POS_FIGHTING )
                    continue;

                if ( tch->fighting && tch->fighting->who )
                    continue;

                // If the triggering NPC is still aggro against the target, skip them
                if ( is_hating( ch, tch ) || is_hunting( ch, tch ) || is_fearing( ch, tch ) )
                    continue;

                // If they're at or above 0 HP (even though 0 is technically stunned), skip them
                if ( tch->hit >= 0 )
                    continue;

                // Only do this for downed players
                if ( IS_NPC( tch ) )
                    continue;

                // If they're not in a room... IDK, this is just random crash prevention.
                if ( !tch->in_room )
                    continue;

                // If they're held or carried by another player, skip them
                if ( tch->held || tch->heldby || tch->carried )
                    continue;

                // If they've been in PvP recently, skip them
                if ( isFighting( tch ) || get_timer( tch, TIMER_RECENTPVP ) > 0 )
                    continue;

                // If they can't be hospitalized (because they're on an enemy planet or don't have 5k), skip them
                if ( !hospitalZone( tch ) )
                    continue;

                // If there are any other conscious players in the room, find them
                for ( xch = tch->in_room->first_person; xch; xch = xch->next_in_room )
                {
                    if ( xch == tch || xch == ch )
                        continue;

                    if ( IS_NPC( xch ) )
                        continue;

                    if ( xch->hit < 0 )
                        continue;

                    break;
                }

                // If there's another conscious player in the room, the NPC doesn't hospitalize the downed player -- or any downed players.
                if ( xch )
                    break;

                // If we've made it this far, hospitalize 'em
                sendToHospital( ch, tch );
            }
        }

    }

    return;
}

void update_taxes( void )
{
    PLANET_DATA* planet = NULL;
    CLAN_DATA* clan = NULL;
    DESCRIPTOR_DATA* d = NULL;
    CHAR_DATA* ch = NULL, *och = NULL;
    int pay = 0;

    for ( planet = first_planet; planet; planet = planet->next )
    {
        if ( xIS_SET( planet->flags, PLANET_STAR ) || xIS_SET( planet->flags, PLANET_MOON ) )
            continue;

        clan = planet->governed_by;

        if ( clan )
        {
            if ( get_planet_pop_opinion( planet, clan ) > 40 )
                planet->population += number_range( 10, 30 );

            // 4x the population increase if affected by immigration
            if ( get_planet_event( planet, PLANET_EVENT_IMMIGRATION ) )
                planet->population += number_range( 30, 90 );
        }
    }

    for ( CLAN_DATA* clan = first_clan; clan; clan = clan->next )
    {
        char reportbuf[MSL], linebuf[MIL];
        strlcpy( reportbuf, "", MSL );
        strlcpy( linebuf, "", MIL );
        int clan_income = get_clan_income( clan ); // Now includes pending taxes and subtracts tax leech deductions
        mod_clan_funds( clan, NULL, clan_income, "hourly planet finances", NULL );
        debug( "update_taxes: background income for %s: %d", clan->name, clan_income );
        int planet_leech_value = 0, total_leech_value = 0;
        int planet_sales_and_cargo = 0, total_sales_and_cargo = 0;

        for ( planet = first_planet; planet; planet = planet->next )
        {
            planet_sales_and_cargo = 0;
            planet_leech_value = 0;

            if ( planet->governed_by && planet->governed_by == clan )
            {
                /* Note: these funds are already tallied and included in get_clan_income/get_planet_income,
                so we only adjust clan funds once at the top there. */
                planet_sales_and_cargo = ( get_planet_sales_and_cargo( planet ) - (int) ( get_planet_sales_and_cargo( planet ) * get_planet_tax_leech_rate( planet ) ) );
                debug( "update_taxes: %s earned %d cargo/sales tax from %s", clan->name, planet_sales_and_cargo, planet->name );
                snprintf( reportbuf + strlen( reportbuf ), MSL - strlen( reportbuf ), "&w    %-19s&w: &G%+8d\n", planet->name, planet_sales_and_cargo );
                planet->pending_taxes = 0;
                save_planet( planet, true );
                total_sales_and_cargo += planet_sales_and_cargo;
            }

            planet_leech_value = tax_leech_value( planet, clan );

            if ( planet_leech_value > 0 )
            {
                snprintf( linebuf, MIL, "tax leech for planet %s", planet->name );
                mod_clan_funds( clan, NULL, planet_leech_value, linebuf, NULL );
                debug( "update_taxes: tax leech income for %s: %d", clan->name, planet_leech_value );
                total_leech_value += planet_leech_value;
            }
        }

        int total_income = clan_income + total_leech_value;
        int subtotal_income = clan_income - total_sales_and_cargo;
        debug( "update_taxes: total income for %s: %d", clan->name, total_income );

        for ( d = last_descriptor; d; d = d->prev )
        {
            if ( ( d->connected != CON_PLAYING && d->connected != CON_EDITING ) || d->original )
                continue;

            ch    = d->character;
            och   = d->original ? d->original : d->character;

            if ( !och->pcdata || !och->pcdata->clan || och->pcdata->clan != clan )
                continue;

            if ( has_pcflag( och, PCFLAG_SHORTINCOME ) )
            {
                if ( total_income > 0 )
                    ch_println( ch, "&YYour clan has gained %'d credits from controlled planets.", total_income );
                else if ( total_income < 0 )
                    ch_println( ch, "&YYour clan has lost %'d credits in maintaining controlled planets.", -1 * total_income );
            }
            else
            {
                ch_println( ch, "&z----- &CHourly Planetary Income Report: &z--------------------------------" );
                ch_println( ch, "" );
                ch_println( ch, "&w  %-21s&w: %s%+8d   &z(&wSee &CPLANETS INCOME&w for breakdown&z)",
                           "&zPopulation and Upkeep",
                           subtotal_income < 0 ? "&R" : subtotal_income > 0 ? "&G" : "&w",
                           subtotal_income
                         );
                ch_println( ch, "&w  %-21s&w: %s%+8d",
                           "&zSales and Cargo Taxes",
                           total_sales_and_cargo < 0 ? "&R" : total_sales_and_cargo > 0 ? "&G" : "&w",
                           total_sales_and_cargo
                         );
                ch_printf( ch, reportbuf );
                ch_println( ch, "&w  %-21s&w: %s%+8d",
                           "&zTax Leech Revenue    ",
                           total_leech_value < 0 ? "&R" : total_leech_value > 0 ? "&G" : "&w",
                           total_leech_value
                         );
                ch_println( ch, "" );
                ch_println( ch, "&W%-23s&w: %s%+8d",
                           "Total",
                           total_income < 0 ? "&R" : total_income > 0 ? "&G" : "&w",
                           total_income
                         );
                ch_println( ch, "" );
                ch_println( ch, "&z----------------------------------------------------------------------" );
            }

            if ( has_pcflag( och, PCFLAG_AFK ) )
                continue;

            pay = UMIN(  clan->salary, clan->funds );
            pay = UMAX(  pay, 0 );
            pay *= ch->pcdata->clan_rank == 0 ? 1 : ( int ) ch-> pcdata->clan_rank;

            if ( pay == 0 || IS_IMMORTAL( ch ) )
            {
                continue;
            }

            if ( clan->funds <= 0 || clan->funds - pay < 0 )
            {
                if ( clan->funds < 0 )
                    clan->funds = 0;

                ch_println( ch, "&wYour organization is unable to pay you, insufficient clan funds." );
                continue;
            }

            /* dish out the funds, after checking to make sure it's legit */
            och->gold += pay;
            clan->funds -= pay;

            if ( !IS_NPC( och ) )
                sql_credits_log( och->name, "update_taxes wages", pay, FALSE );

            sql_credits_log( clan->name, "update_taxes wages", pay * -1, FALSE );
            ch_println( ch, "&YYou are paid %d credits, courtesy of %s.", pay, clan->name );
        }

        save_clan( clan, true );
    }
}

// Removes expired tax leeches
void update_tax_leeches( void )
{
    TAX_LEECH_DATA* leech = NULL, *next_leech = NULL;
    PLANET_DATA* planet = NULL;
    for ( planet = first_planet; planet; planet = planet->next )
    {
        for ( leech = planet->first_tax_leech; leech; leech = next_leech )
        {
            next_leech = leech->next;
            if ( leech->expiration > 0 && leech->expiration < current_time )
                remove_tax_leech( leech );
        }
    }

    return;
}

/*
    update the time
*/
void time_update( void )
{
    ++time_info.hour;
    // Lets take a moment for time checks    Orion 2008
    check_timeprogs();

    if ( time_info.hour == HOUR_MIDNIGHT )
    {
        time_info.hour = 0;
        time_info.day++;
        update_economy  ( );
    }

    if ( time_info.day >= DAYS_PER_MONTH )
    {
        time_info.day = 0;
        time_info.month++;
        //      update_month_trigger = TRUE;
    }

    if ( time_info.month >= MONTHS_PER_YEAR )
    {
        time_info.month = 0;
        time_info.year++;
    }

    return;
}

/* Anything that should be updating based on time should go here - like hunger/thirst for one */
void char_calendar_update( void )
{
    CHAR_DATA* ch;

    for ( ch = last_char; ch; ch = gch_prev )
    {
        if ( ch == first_char && ch->prev )
        {
            bug( "%s", "char_calendar_update: first_char->prev != NULL... fixed" );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "%s", "char_calendar_update: ch->prev->next != ch" );
            return;
        }

        if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) )
        {
            gain_condition( ch, COND_DRUNK, -1 );

            /*
                Newbies won't starve now - Samson 10-2-98
            */
            if ( ch->in_room && ch->top_level > 3 )
                gain_condition( ch, COND_FULL, -1 + ch->race->hunger_mod );

            /*
                Newbies won't dehydrate now - Samson 10-2-98
            */
            if ( ch->in_room && ch->top_level > 3 )
            {
                int sector;
                sector = ch->in_room->sector_type;

                switch ( sector )
                {
                    default:
                        gain_condition( ch, COND_THIRST, -1 + ch->race->thirst_mod );
                        break;

                    case SECT_DESERT:
                        gain_condition( ch, COND_THIRST, -3 + ch->race->thirst_mod );
                        break;

                    case SECT_UNDERWATER:
                    case SECT_OCEANFLOOR:
                        if ( number_bits( 1 ) == 0 )
                            gain_condition( ch, COND_THIRST, -1 + ch->race->thirst_mod );

                        break;
                }
            }
        }
    }
}

/*
    Update all chars, including mobs.
    This function is performance sensitive.
*/
void char_update( void )
{
    CHAR_DATA* ch;
    OBJ_DATA* binding = NULL;
    int cnt = 0, oldval = 0;
    bool changed = FALSE;
    OBJ_DATA* obj = NULL;
    debug( "char_update" );

    for ( ch = last_char; ch; ch = gch_prev )
    {
        changed = FALSE;

        if ( ch == first_char && ch->prev )
        {
            bug( "char_update: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;
        set_cur_char( ch );

        if ( !IS_NPC( ch ) )
        {
            if ( ch->desc && !ch->desc->account )
                ch->desc->account = account_from_name( ch->name );

            if ( ch->pcdata && ( ch->pcdata->last_backup < ( current_time - ( 60 * 60 ) ) ) )
                save_player_backup( ch );
        }

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "char_update: ch->prev->next != ch", 0 );
            return;
        }

        /*
            Do a room_prog rand check right off the bat
            if ch disappears (rprog might wax npc's), continue
        */
        if ( !IS_NPC( ch ) )
            rprog_random_trigger( ch );

        if ( char_extracted( ch ) )
            continue;

        if ( ch->position == POS_MOUNTED && !ch->mount )
        {
            ch->position = POS_STANDING;
            changed = TRUE;
        }

        if ( !ch->race )
        {
            bug("%s: %s (%d) has no race! Setting to human.", FUNC, IS_NPC( ch ) ? ch->short_descr : ch->name, ch->pIndexData ? ch->pIndexData->vnum : 0 );
            ch->race = get_race_by_id( 1 );
            save_char_obj( ch, TRUE );
            continue;
        }

        /* Mando adrenaline surge */
        if ( xIS_SET( ch->race->flags, RFLAG_DEATHCOMA ) && ch->hit <= 0 )
        {
            oldval = ch->hit;
            if ( ch->hit > -150 )
                ch->hit = URANGE( -500, ch->hit + number_range( ( int )( ch->max_hit * 0.2 ), ( int )( ch->max_hit * 0.7 ) ), ch->max_hit );
            else
                ch->hit = URANGE( -500, ch->hit + number_range( 45, 65 ), ch->max_hit );

            if ( ch->hit != oldval ) changed = TRUE;
            ch_println( ch, "&YYour body enters a death-like healing trance, allowing you to recuperate faster.&w" );
        }

        if ( xIS_SET( ch->race->flags, RFLAG_REGEN ) && ch->hit < ch->max_hit && ch->hit >= -150 )
        {
            oldval = ch->hit;
            ch->hit = URANGE( -500, ch->hit + number_range( ( int )( ch->max_hit * 0.2 ), ( int )( ch->max_hit * 0.7 ) ), ch->max_hit );
            if ( ch->hit != oldval ) changed = TRUE;
            ch_println( ch, "&GYour heart beats, adrenaline filling your veins!&w" );
        }

        if ( ( xIS_SET( ch->race->flags, RFLAG_FULLREGEN ) || has_cyber_flag( ch,  CYBER_REGENERATION ) )
                && ch->hit < ch->max_hit )
        {
            oldval = ch->hit;
            if ( ch->hit > -150 )
                ch->hit = URANGE( -500, ch->hit + number_range( ( int )( ch->max_hit * 0.2 ), ( int )( ch->max_hit * 0.7 ) ), ch->max_hit );
            else
                ch->hit = URANGE( -500, ch->hit + number_range( 45, 65 ), ch->max_hit );

            if ( ch->hit != oldval ) changed = TRUE;
            ch_println( ch, "&BYour wounds close as healing reagents course through your body.&w" );
        }

        if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && IS_AFFECTED( ch, AFF_FLYING ) )
        {
            oldval = ch->move;
            ch->move = URANGE( 0, ch->move - number_range( 1, 5 ), ch->max_move );
            if ( ch->move != oldval ) changed = TRUE;
            if ( number_range( 1, 20 ) == 20 )
                ch_println( ch, "The strain from controlling yourself in the air is wearing on you.&w" );
        }

        if ( !IS_AWAKE( ch ) && IS_AFFECTED( ch, AFF_FLYING ) )
        {
            xREMOVE_BIT( ch->affected_by, AFF_FLYING );
            changed = TRUE;
        }

        for ( obj = ch->first_carrying; obj; obj = obj->next_content )
            if ( obj->item_type == ITEM_MONEY )
                cnt += obj->value[0];

        if ( !IS_NPC( ch ) && get_trust( ch ) < sysdata.log_level && ch->gold + cnt > sysdata.maxgold )
        {
            char lbuf[MSL];
            snprintf( lbuf, MSL, "%ld credits", ch->gold + cnt - sysdata.maxgold );
            ch_println( ch, "You have more credits than you can carry!" );
            do_drop( ch, lbuf );
            changed = TRUE;
        }

        if ( ch->alert > 0 )
            ch->alert--;

        if ( get_eq_char( ch, WEAR_SHIELD ) != NULL )
        {
            OBJ_DATA* tobj = get_eq_char( ch, WEAR_SHIELD );

            if ( tobj->item_type == ITEM_SHIELD && tobj->value[2] > 0 )
            {
                tobj->value[2]--;

                if ( tobj->value[2] == 0 )
                    ch_println( ch, "Your energy shield's display turns solid green as it comes online." );

                changed = TRUE;
            }

            if ( tobj->value[3] != 0 )
            {
                oldval = tobj->value[4];
                tobj->value[4] -= number_range( 10, 40 );
                if ( tobj->value[4] != oldval ) changed = TRUE;

                if ( tobj->value[4] <= 0 )
                {
                    //Ralen - currently players don't know when their shield runs out unless in combat. Alerting here.
                    act( AT_PLAIN, "$p fizzles and dies.", ch, tobj, NULL, TO_CHAR );
                    act( AT_PLAIN, "$n's energy shield fizzles and dies.", ch, NULL, NULL, TO_ROOM );
                    tobj->value[4] = tobj->value[3] = 0;
                    changed = TRUE;
                }
            }
        }

        /*
            Check to ensure you don't magically free yourself from bindings. -Ulthrax
        */
        if ( ( binding = get_eq_char( ch, WEAR_BINDING ) ) != NULL
                &&     !ch->held )
        {
            ch->held = TRUE;
            changed = TRUE;
            bug( "%s is bound, but not held. Re-applying held state.\n", ch->name );
        }

        if ( ch->move < 0 )
        {
            ch->move = 0;
            changed = TRUE;
        }

        if ( ch->hit  < ch->max_hit )
        {
            oldval = ch->hit;
            int newhp = ch->hit + hit_gain( ch );
            ch->hit  = URANGE( -500, newhp, ch->max_hit );
            if ( ch->hit != oldval ) changed = TRUE;
        }

        if ( char_extracted( ch ) )
            continue;

        oldval = ch->mana;

        if ( ch->mana < ch->max_mana || ch->skill_level[FORCE_ABILITY] == 1 )
            ch->mana = UMIN( ch->max_mana, ch->mana + mana_gain( ch ) );

        if ( ch->mana > ch->max_mana )
            ch->mana = ch->max_mana;

        if ( ch->mana != oldval ) changed = TRUE;
        oldval = ch->move;

        if ( ch->move < ch->max_move )
            ch->move = UMIN( ch->max_move, ch->move + move_gain( ch ) );

        // if you remove something that gives you an MV bonus, you also remove
        // the bonus.  ~Miros
        if ( ch->move > ch->max_move )
            ch->move = ch->max_move;

        if ( ch->move != oldval ) changed = TRUE;

        oldval = ch->mental_state;

        if ( !IS_NPC( ch ) && ch->top_level < LEVEL_IMMORTAL )
        {
            OBJ_DATA* obj;

            if ( ( obj = get_eq_char( ch, WEAR_LIGHT ) ) != NULL && obj->item_type == ITEM_LIGHT )
            {
                if ( IS_SET( obj->value[3], BV00 ) && obj->value[2] > 0 )
                {
                    if ( --obj->value[2] == 0 && ch->in_room )
                    {
                        ch->in_room->light -= obj->count;
                        act( AT_ACTION, "$p goes out.", ch, obj, NULL, TO_ROOM );
                        act( AT_ACTION, "$p goes out.", ch, obj, NULL, TO_CHAR );
                    }

                    changed = TRUE;
                }
            }

            if ( ch->pcdata->condition[COND_DRUNK] > 8 )
                worsen_mental_state( ch, ch->pcdata->condition[COND_DRUNK] / 8 );

            if ( ch->pcdata->condition[COND_FULL] > 1 )
            {
                switch ( ch->position )
                {
                    case POS_SLEEPING:
                        better_mental_state( ch, 4 );
                        break;

                    case POS_RESTING:
                        better_mental_state( ch, 3 );
                        break;

                    case POS_SITTING:
                    case POS_MOUNTED:
                        better_mental_state( ch, 2 );
                        break;

                    case POS_STANDING:
                        better_mental_state( ch, 1 );
                        break;

                    case POS_FIGHTING:
                        if ( number_bits( 2 ) == 0 )
                            better_mental_state( ch, 1 );

                        break;
                }
            }

            if ( ch->pcdata->condition[COND_THIRST] > 1 )
            {
                switch ( ch->position )
                {
                    case POS_SLEEPING:
                        better_mental_state( ch, 5 );
                        break;

                    case POS_RESTING:
                        better_mental_state( ch, 3 );
                        break;

                    case POS_SITTING:
                    case POS_MOUNTED:
                        better_mental_state( ch, 2 );
                        break;

                    case POS_STANDING:
                        better_mental_state( ch, 1 );
                        break;

                    case POS_FIGHTING:
                        if ( number_bits( 2 ) == 0 )
                            better_mental_state( ch, 1 );

                        break;
                }
            }

            gain_condition( ch, COND_DRUNK,  -1 );
            gain_condition( ch, COND_FULL,   -1 );
        }

        // If they've been logged in for 30 minutes and haven't already had interest enabled this login
        if ( ch->pcdata && !ch->pcdata->ready_for_interest && ( current_time - ch->logon ) >= ( 30 * 60 ) )
            apply_interest_time( ch );

        if ( !char_extracted( ch ) )
        {
            /*
                Careful with the damages here,
                 MUST NOT refer to ch after damage taken,
                 as it may be lethal damage (on NPC).
            */
            if ( IS_AFFECTED( ch, AFF_POISON ) )
            {
                AFFECT_DATA* paf;
                int dam = 0;

                for ( paf = ch->first_affect; paf; paf = paf->next )
                {
                    if ( xIS_SET( paf->bitvector, AFF_POISON ) )
                    {
                        paf->duration = URANGE( 0, paf->duration, 32000 );
                        act( AT_POISON, "$n shivers and suffers.", ch, NULL, NULL, TO_ROOM );
                        act( AT_POISON, "You shiver and suffer.", ch, NULL, NULL, TO_CHAR );
                        worsen_mental_state( ch, number_range( 2, 5 ) );
                        dam = number_range( 10, 25 );

                        if ( !IS_NPC( ch ) )
                            damage( ch, ch, dam, cache_skill( "poison", &skill_poison )->id );

                        if ( IS_NPC( ch ) )
                            damage( ch, ch, dam * 5, cache_skill( "poison", &skill_poison )->id );
                    }

                    if ( char_extracted( ch ) )
                        break;
                }
            }

            if ( char_extracted( ch ) )
                continue;

            if ( ch->mental_state >= 30 && ch->position > POS_SLEEPING )
                switch ( ( ch->mental_state + 5 ) / 10 )
                {
                    case  3:
                        ch_println( ch, "You feel feverish." );
                        act( AT_ACTION, "$n looks kind of out of it.", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  4:
                        ch_println( ch, "You do not feel well at all." );
                        act( AT_ACTION, "$n doesn't look too good.", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  5:
                        ch_println( ch, "You need help!" );
                        act( AT_ACTION, "$n looks like $e could use your help.", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  6:
                        ch_println( ch, "Seekest thou a cleric." );
                        act( AT_ACTION, "Someone should fetch a healer for $n.", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  7:
                        ch_println( ch, "You feel reality slipping away..." );
                        act( AT_ACTION, "$n doesn't appear to be aware of what's going on.", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  8:
                        ch_println( ch, "You begin to understand... everything." );
                        act( AT_ACTION, "$n starts ranting like a madman!", ch, NULL, NULL, TO_ROOM );
                        break;

                    case  9:
                        ch_println( ch, "You are ONE with the universe." );
                        act( AT_ACTION, "$n is ranting on about 'the answer', 'ONE' and other mumbo-jumbo...", ch, NULL, NULL, TO_ROOM );
                        break;

                    case 10:
                        ch_println( ch, "You feel the end is near." );
                        act( AT_ACTION, "$n is muttering and ranting in tongues...", ch, NULL, NULL, TO_ROOM );
                        break;
                }

            if ( ch->mental_state <= -30 )
                switch ( ( abs( ch->mental_state ) + 5 ) / 10 )
                {
                    case  10:
                        if ( ch->position > POS_SLEEPING )
                        {
                            if ( ( ch->position == POS_STANDING
                                    ||    ch->position < POS_FIGHTING )
                                    &&    number_percent() + 10 < abs( ch->mental_state ) )
                                do_sleep( ch, "" );
                            else
                                ch_println( ch, "You're barely conscious." );
                        }

                        break;

                    case   9:
                        if ( ch->position > POS_SLEEPING )
                        {
                            if ( ( ch->position == POS_STANDING
                                    ||    ch->position < POS_FIGHTING )
                                    &&   ( number_percent() + 20 ) < abs( ch->mental_state ) )
                                do_sleep( ch, "" );
                            else
                                ch_println( ch, "You can barely keep your eyes open." );
                        }

                        break;

                    case   8:
                        if ( ch->position > POS_SLEEPING )
                        {
                            if ( ch->position < POS_SITTING
                                    &&  ( number_percent() + 30 ) < abs( ch->mental_state ) )
                                do_sleep( ch, "" );
                            else
                                ch_println( ch, "You're extremely drowsy." );
                        }

                        break;

                    case   7:
                        if ( ch->position > POS_RESTING )
                            ch_println( ch, "You feel very unmotivated." );

                        break;

                    case   6:
                        if ( ch->position > POS_RESTING )
                            ch_println( ch, "You feel sedated." );

                        break;

                    case   5:
                        if ( ch->position > POS_RESTING )
                            ch_println( ch, "You feel sleepy." );

                        break;

                    case   4:
                        if ( ch->position > POS_RESTING )
                            ch_println( ch, "You feel tired." );

                        break;

                    case   3:
                        if ( ch->position > POS_RESTING )
                            ch_println( ch, "You could use a rest." );

                        break;
                }

            if ( ch->mental_state != oldval ) changed = TRUE;

            if ( !IS_NPC ( ch ) )
            {
                // This is a bit over 20 minutes.
                // That's meant to be in sync with our rescue-or-die mechanics (EV suits, landmines) which give you
                // 20 minutes to be rescued. We don't want characters to be removed from the world before those
                // things go off.
                if ( ++ch->timer >= 20 && !ch->desc )
                {
                    if ( ( ch->switched || ch->pcdata ) && xIS_SET( ch->act, ACT_IS_NPC ) )
                    {
                        // If something happens and an NPC is stuck in a switched state after a disconnect, fix it.
                        ch->switched = NULL;
                        free_pcdata( ch->pcdata );
                        ch->pcdata = NULL;
                    }
                    else
                    {
                        ch->position = POS_RESTING;
                        ch->hit = UMAX ( 1, ch->hit );
                        save_char_obj( ch, true );
                        do_quit( ch, "" );
                    }
                }
            }

            if ( changed && IS_SET( sysdata.save_flags, SV_AUTO ) && ch->save_time < ( current_time - (sysdata.save_frequency * 60) ) && ( !IS_NPC( ch ) || xIS_SET( ch->act, ACT_PERSISTENT ) ) )
            {
                debug( "%s: saving %s", FUNC, IS_NPC( ch ) ? ch->short_descr : ch->name );
                save_char_obj( ch, TRUE );
            }
        }
    }

    return;
}

/*
    Update all objs.
    This function is performance sensitive.
*/
void obj_update( void )
{
    OBJ_DATA* obj = NULL;
    sh_int AT_TEMP = 0;

    for ( obj = last_object; obj; obj = gobj_prev )
    {
        CHAR_DATA* rch;
        char* message;

        if ( obj == first_object && obj->prev )
        {
            bug( "obj_update: first_object->prev != NULL... fixed", 0 );
            obj->prev = NULL;
        }

        gobj_prev = obj->prev;

        if ( gobj_prev && gobj_prev->next != obj )
        {
            bug( "obj_update: obj->prev->next != obj", 0 );
            return;
        }

        set_cur_obj( obj );

        if ( obj->carried_by || obj->in_room )
            oprog_random_trigger( obj );

        lua_trigger_on_obj_random( obj );

        if ( obj_extracted( obj ) )
            continue;

        if ( obj->item_type == ITEM_WEAPON && obj->carried_by && !IS_NPC( obj->carried_by ) &&
                ( obj->wear_loc == WEAR_WIELD || obj->wear_loc == WEAR_DUAL_WIELD ) &&
                obj->value[3] != WEAPON_BLASTER && obj->value[4] > 0 &&
                obj->value[3] != WEAPON_BOWCASTER && obj->value[3] != WEAPON_FORCE_PIKE
                && obj->value[3] != WEAPON_DISRUPTOR && obj->value[3] != WEAPON_FLAMETHROWER )
        {
            obj->value[4]--;

            if ( obj->value[4] <= 0 )
            {
                if ( obj->value[3] == WEAPON_LIGHTSABER )
                {
                    act( AT_PLAIN, "$p fizzles and dies.", obj->carried_by, obj, NULL, TO_CHAR );
                    act( AT_PLAIN, "$n's lightsaber fizzles and dies.", obj->carried_by, NULL, NULL, TO_ROOM );
                }
                else if ( obj->value[3] == WEAPON_VIBRO_BLADE || obj->value[3] == WEAPON_VIBRO_AXE )
                {
                    act( AT_PLAIN, "$p stops vibrating.", obj->carried_by, obj, NULL, TO_CHAR );
                }
            }
        }

        if ( obj->item_type == ITEM_MEDPAC && obj->value[0] == 0 )
        {
            if ( obj->in_room )
            {
                // Empty medpacs in rooms should expire eventually.
                if ( !obj->timer )
                    obj->timer = number_range( 10, 15 );
            }
            else
            {
                // If it has been picked up by someone, cancel the decay timer.
                if ( obj->timer && ( !obj->pIndexData || !obj->pIndexData->timer ) )
                    obj->timer = 0;
            }
        }

        /* Corpse decay (npc corpses decay at 8 times the rate of pc corpses) - Narn */

        if ( obj->item_type == ITEM_CORPSE_PC || obj->item_type == ITEM_CORPSE_NPC
                || obj->item_type == ITEM_DROID_CORPSE || obj->item_type == ITEM_ASHES )
        {
            sh_int timerfrac = UMAX( 1, obj->timer - 1 );

            if ( obj->item_type == ITEM_CORPSE_PC || obj->item_type == ITEM_ASHES )
                timerfrac = ( int )( obj->timer / 8 + 1 );

            if ( obj->timer > 0 && obj->value[2] > timerfrac )
            {
                char buf[MSL];
                char name[MSL];
                char* bufptr;
                bufptr = one_argument( obj->short_descr, name );
                bufptr = one_argument( bufptr, name );
                bufptr = one_argument( bufptr, name );
                //   OBJ_DATA *tobj;
                /*  for (tobj = obj->first_content; tobj; tobj = tobj->next_content)
                     if (IS_OBJ_STAT(tobj,ITEM_DRESET))
                     {
                         obj_from_obj(tobj);
                         obj_to_room(tobj,obj->in_room);
                     }*/
                separate_obj( obj );
                obj->value[2] = timerfrac;

                // PC corpses last long enough that this doesn't matter, and we don't want to rename deletion boxes.
                if ( obj->item_type != ITEM_CORPSE_PC )
                {
                    if ( obj->item_type == ITEM_DROID_CORPSE )
                        snprintf( buf, MSL, d_corpse_descs[ UMIN( timerfrac - 1, 4 ) ], bufptr );
                    else if ( obj->item_type == ITEM_ASHES )
                        snprintf( buf, MSL, ashes_descs[ UMIN( timerfrac - 1, 4 ) ], capitalize( bufptr ) );
                    else
                        snprintf( buf, MSL, corpse_descs[ UMIN( timerfrac - 1, 4 ) ], capitalize( bufptr ) );

                    SET_STRING( obj->description, buf );
                }
            }
        }

        /* don't let inventory or dynamic resets decay */
        if ( IS_OBJ_STAT( obj, ITEM_INVENTORY ) ) //|| IS_OBJ_STAT(obj, ITEM_DRESET) )
            continue;

        if ( obj->timer > 0 && obj->timer < 5 && obj->item_type == ITEM_ARMOR )
        {
            if ( obj->carried_by )
            {
                act( AT_TEMP, "$p is almost dead.", obj->carried_by, obj, NULL, TO_CHAR );
            }
        }

        if ( ( obj->timer <= 0 || --obj->timer > 0 ) )
            continue;

        /* if we get this far, object's timer has expired. */
        if ( obj->item_type == ITEM_BLOODSTAIN )
            separate_obj( obj );

        AT_TEMP = AT_PLAIN;

        switch ( obj->item_type )
        {
            default:
                message = "$p has depleted itself.";
                AT_TEMP = AT_PLAIN;
                break;

            case ITEM_FOUNTAIN:
                message = "$p dries up.";
                AT_TEMP = AT_BLUE;
                break;

            case ITEM_ASHES:
                message = "$p is blown away by the wind, leaving a small smudge.";
                AT_TEMP = AT_OBJECT;
                break;

            case ITEM_CORPSE_NPC:
                message = "$p decays into dust and blows away.";
                AT_TEMP = AT_OBJECT;
                break;

            case ITEM_DROID_CORPSE:
                message = "$p rusts away into oblivion.";
                AT_TEMP = AT_OBJECT;
                break;

            case ITEM_CORPSE_PC:
                message = "$p decays into dust and is blown away...";
                AT_TEMP = AT_MAGIC;
                break;

            case ITEM_FOOD:
                message = "$p is devoured by a swarm of maggots.";
                AT_TEMP = AT_HUNGRY;
                break;

            case ITEM_BLOODSTAIN:
                message = "$p dries up into flakes and blows away.";
                AT_TEMP = AT_BLOOD;
                break;

            case ITEM_SCRAPS:
                message = "$p crumbles and decays into nothing.";
                AT_TEMP = AT_OBJECT;
                break;

            case ITEM_CONTAINER:
                message = "$p breaks apart and spills its contents onto the ground.";
                AT_TEMP = AT_OBJECT;
                break;

            case ITEM_FIRE:
                if ( obj->in_room )
                    --obj->in_room->light;

                message = "$p burns out.";
                AT_TEMP = AT_FIRE;
        }

        if ( obj->carried_by )
        {
            act( AT_TEMP, message, obj->carried_by, obj, NULL, TO_CHAR );
        }
        else if ( obj->in_room
                  &&      ( rch = obj->in_room->first_person ) != NULL
                  &&    !IS_OBJ_STAT( obj, ITEM_BURIED ) )
        {
            act( AT_TEMP, message, rch, obj, NULL, TO_ROOM );
            act( AT_TEMP, message, rch, obj, NULL, TO_CHAR );
        }

        if ( obj->serial == cur_obj )
            global_objcode = rOBJ_EXPIRED;

        // When containers expire, they dump their things on the ground.
        if ( obj->item_type == ITEM_CONTAINER || obj->item_type == ITEM_CORPSE_PC )
        {
            if ( obj->in_room )
                empty_obj( obj, NULL, obj->in_room, NULL );
            else if ( obj->carried_by )
                empty_obj( obj, NULL, obj->carried_by->in_room, NULL );
            else if ( obj->in_locker )
                empty_obj( obj, NULL, NULL, obj->in_locker );
        }
        extract_obj( obj );
    }

    return;
}

void rand_update_rooms( void )
{
    for ( ROOM_INDEX_DATA* room = first_room; room; room = room->next )
        lua_trigger_on_room_random( room );
}

void room_affects_update( void )
{
    ROOM_INDEX_DATA* room = NULL;
    CHAR_DATA* ch = NULL;
    AFFECT_DATA* paf = NULL, *paf_next = NULL;
    AFFECT_DATA af;

    // Tee up the napalm affect
    af.type = -1;
    af.location  = APPLY_DAMAGE;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_NAPALM );

    for ( room = first_room; room; room = room->next )
    {
        for ( paf = room->first_affect; paf; paf = paf_next )
        {
            paf_next = paf->next;

            if ( --paf->duration < 0 )
            {
                affect_remove( room, ROOM_AFFECT, paf );
                continue;
            }

            if ( xIS_SET( paf->bitvector, AFF_NAPALM ) )
            {
                af.duration = paf->value[5];
                af.modifier = paf->value[1];

                for ( size_t i = 0; i < MAX_VALS; i++ )
                    af.value[i] = paf->value[i];

                for ( ch = room->first_person; ch; ch = ch->next_in_room )
                {
                    affect_replace( ch, CHAR_AFFECT, &af );
                    act( AT_YELLOW, "You scream as the flames from the room continue to consume you!", ch, NULL, NULL, TO_CHAR );
                    interrupt_ch( ch );
                    damage( ch, ch, paf->modifier, TYPE_UNDEFINED );
                }
            }
        }
    }
}

/*
    Function to update SELF_DESTRUCT Modules =)
*/
void selfd_check( void )
{
    SHIP_DATA* ship = NULL;
    ROOM_INDEX_DATA* room = NULL;
    char buf[MSL];

    // Declare the array of pointers to copy the linked list into
    SHIP_DATA** all_ships = NULL;

    // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
    LINK_TO_ARRAY( first_ship, SHIP_DATA, next, all_ships );

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        /*
            Hull Damage Check
            -Written for Grenading Ships
        */
        if ( ship->hull <= 0 && ship->maxhull > 0 )
        {
            if ( !xIS_SET( ship->flags, SHIP_SIMULATOR ) )
            {
                echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "The cockpit is engulfed in flames as the ship is *OBLITERATED*" );
                echo_to_ship_main( AT_BLOOD, ship, "You scream in agony as your body is engulfed in flames!" );
                echo_to_ship_main( AT_BLOOD, ship, "The ship erupts into a blazing inferno, and explodes before you!" );
            }

            if ( ship->shipstate != SHIP_DOCKED )
            {
                snprintf( buf, MSL, "%s is engulfed in explosions!", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                destroy_ship( ship, NULL, NULL, "hull rupture" );
            }
            else
            {
                room = ship->in_room ? ship->in_room : get_room_index( ship->location );
                snprintf( buf, MSL, "%s erupts into a ball of fire on the pad!", ship->name );
                echo_to_room( AT_YELLOW, room, buf );
                echo_to_room( AT_ORANGE, room, "Flaming shrapnel is thrown from the exploding ship!" );
                ship_explode( ship );
                snprintf( buf, MSL, "%s has been destroyed!", ship->name );
                echo_to_room( AT_RED, room, buf );
                destroy_ship( ship, NULL, NULL, "hull rupture" );
            }

            continue;
        }

        if ( xIS_SET( ship->flags, SHIP_JAMMED ) )
        {
            if ( --ship->jam_timer <= 0 )
            {
                echo_to_ship_windows( AT_WHITE, ship, "*ALERT* Radar and communications systems restored.\n" );
                xREMOVE_BIT( ship->flags, SHIP_JAMMED );
                ship->jam_timer = 0;
            }
        }

        if ( ship->undock_time > 0 )
        {
            // This can happen if the ship has been undocked by other means (being captured, destroyed, etc)
            if ( ship->dockship == NULL )
            {
                ship->undock_time = 0;
            }
            else if ( --ship->undock_time <= 0 )
            {
                char dockbuf[MSL];
                echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: Breaking off Dock... Docking Ring Sealed!" );
                echo_to_ship_main( AT_YELLOW, ship->dockship, "[ALERT]: Breaking off Dock... Docking Ring Sealed!" );

                if ( ship->entrance || ship->dockroom )
                    echo_to_room( AT_YELLOW, get_ship_dockroom( ship ), "The hatch hisses closed as the docking connection is broken." );

                if ( ship->dockship->entrance || ship->dockship->dockroom )
                    echo_to_room( AT_YELLOW, get_ship_dockroom( ship->dockship ), "The hatch hisses closed as the docking connection is broken." );

                snprintf( dockbuf, MSL, "%s undocks from %s.", ship->name, ship->dockship->name );
                echo_to_system_noqueue( AT_YELLOW, ship, dockbuf, NULL );
                lua_trigger_ship_undocked( ship, ship->dockship, ship->starsystem );
                ship->dockship->dockship   = NULL;
                ship->dockship->dock_state = DOCK_READY;
                ship->dockship->dock_lead  = FALSE;
                save_ship( ship->dockship, TRUE );
                ship->dockship   = NULL;
                ship->dock_state = DOCK_READY;
                ship->dock_lead  = FALSE;
                save_ship( ship, TRUE );
            }
            else
            {
                if ( ship->undock_time <= 5 || ( ship->undock_time % 5 == 0 ) )
                {
                    snprintf( buf, MSL, "[ALERT]: Breaking off dock in %d second(s).", ship->undock_time );
                    echo_to_ship_main( AT_YELLOW, ship, buf );
                }
            }
        }

        if ( ship->selfd_armed )           /* Self Destruct Armed */
        {
            if ( ship->selfd_time >= 1 )    /*    Countdown =)     */
            {
                char selfd_timemsg[100];
                selfd_timemsg[0] = '\0';
                int color = ship->selfd_time <= 30 ? AT_RED : AT_YELLOW;

                switch ( ship->selfd_time )
                {
                    case 1800:
                    case 1500:
                    case 1200:
                    case 900:
                    case 700:
                    case 600:
                    case 540:
                    case 480:
                    case 420:
                    case 360:
                    case 300:
                    case 240:
                    case 180:
                    case 120:
                        snprintf( selfd_timemsg, 100, "%d Minutes", ship->selfd_time / 60 );
                        break;

                    case 60:
                        snprintf( selfd_timemsg, 100, "1 Minute" );
                        break;

                    case 50:
                    case 40:
                    case 30:
                    case 20:
                    case 10:
                    case 9:
                    case 8:
                    case 7:
                    case 6:
                    case 5:
                    case 4:
                    case 3:
                    case 2:
                        snprintf( selfd_timemsg, 100, "%d Seconds", ship->selfd_time );
                        break;

                    case 1:
                        snprintf( selfd_timemsg, 100, "1 Second" );
                        break;
                }

                if ( !NULLSTR( selfd_timemsg ) )
                {
                    char selfd_buf[MIL];

                    if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
                    {
                        switch ( ship->selfd_time )
                        {
                            case 5:
                                snprintf( selfd_buf, MIL, "&WYou feel your skin ice up as the air leaves your lungs.\n" );
                                break;

                            case 4:
                                snprintf( selfd_buf, MIL, "&WThe coldness of space continues to take hold.\n" );
                                break;

                            case 3:
                                snprintf( selfd_buf, MIL, "&WYou see your old ship in the distance...\n" );
                                break;

                            case 2:
                                snprintf( selfd_buf, MIL, "&WIf only you could get back to it somehow...\n" );
                                break;

                            case 1:
                            case 0:
                            default:
                                snprintf( selfd_buf, MIL, "&WIf only...\n" );
                                break;
                        }
                    }
                    else if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
                        snprintf( selfd_buf, MIL, "*ALERT*: Life Support Expires in %s.\n", selfd_timemsg );
                    else
                        snprintf( selfd_buf, MIL, "*ALERT*: Self Destruct in %s.\n", selfd_timemsg );

                    echo_to_ship_windows( color, ship, selfd_buf );
                }

                if ( ship->selfd_time % 15 == 0 )
                {
                    awaken_ship( ship, TRUE );

                    if ( !xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
                        echo_to_shipNC( AT_RED, ship, "Warning lights flash throughout the ship..." );
                }

                if ( ship->shipstate == SHIP_DOCKED )
                {
                    room = ship->in_room ? ship->in_room : get_room_index( ship->location );
                    if ( ship->selfd_time >= 90 )
                    {
                        if ( ship->selfd_time % 30 == 0 )
                        {
                            snprintf( buf, MSL, "The exterior lights on %s flash brilliant red.", ship->name );
                            echo_to_room( AT_RED, room, buf );
                        }
                    }
                    else
                    {
                        if ( ship->selfd_time % 15 == 0 )
                        {
                            snprintf( buf, MSL, "The exterior lights on %s flash brilliant red.", ship->name );
                            echo_to_room( AT_RED, room, buf );
                        }
                    }
                }

                ship->selfd_time--;
            }
            else                            /*    Detenation       */
            {
                if ( !xIS_SET( ship->flags, SHIP_ENVIROSUIT ) && !xIS_SET( ship->flags, SHIP_SIMULATOR ) )
                {
                    echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "The cockpit is engulfed in flames as the ship is *OBLITERATED*" );
                    echo_to_ship_main( AT_BLOOD, ship, "You scream in agony as your body is engulfed in flames!" );
                    echo_to_ship_main( AT_BLOOD, ship, "The ship erupts into a blazing inferno, and explodes before you!" );
                }

                //Changed to more accurately reflect whether the ship is in space or docked somewhere. Gathorn 9May16
                /* Are we on a ship, or in a dock, or in space? */
                if ( ship->location == 0 )
                {
                    /* Not Docked, Yaaaah! */
                    if ( !xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
                    {
                        snprintf( buf, MSL, "%s is engulfed in explosions!", ship->name );
                        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                    }
                    snprintf( buf, MSL, "selfdestruct%s%s", !NULLSTR( ship->selfd_by ) ? " by " : "", !NULLSTR( ship->selfd_by ) ? ship->selfd_by : "" );
                    CHAR_DATA* xch = NULL;
                    if ( !NULLSTR( ship->selfd_by ) )
                        xch = get_player_world( ship->selfd_by );
                    destroy_ship( ship, NULL, xch, buf );
                    continue;
                }
                else
                {
                    /* Failsafe to keep LOTJ from crashing  */
                    snprintf( buf, MSL, "%s erupts into a ball of fire on the pad!", ship->name );
                    room = ship->in_room ? ship->in_room : get_room_index( ship->location );
                    echo_to_room( AT_YELLOW, room, buf );
                    echo_to_room( AT_ORANGE, room, "Flaming shrapnel is thrown from the exploding ship!" );
                    ship_explode( ship );
                    snprintf( buf, MSL, "%s has been destroyed!", ship->name );
                    echo_to_room( AT_RED, room, buf );
                    snprintf( buf, MSL, "selfdestruct%s%s", !NULLSTR( ship->selfd_by ) ? " by " : "", !NULLSTR( ship->selfd_by ) ? ship->selfd_by : "" );
                    CHAR_DATA* xch = NULL;
                    if ( !NULLSTR( ship->selfd_by ) )
                        xch = get_player_world( ship->selfd_by );
                    destroy_ship( ship, NULL, xch, buf );
                    continue;
                }
            }
        }

        if ( ship->chaff_time > 0 )
        {
            ship->chaff_time--;

            if ( ship->chaff_time == 0 )
            {
                echo_to_ship_windows( AT_YELLOW, ship, "The chaff has cleared, leaving the ship vulnerable again." );

                if ( in_squadron( ship ) && should_follow_squadleader( ship->squadleader, ship ) )
                    message_to_squadleader( ship, "My chaff has cleared." );
            }
        }
    }

    DISPOSE( all_ships );
    return;
}

/*
    Function to update AUTOLAUNCH Modules =)
    Also controls the Autoclose feature for hatchways.
*/
void autolaunch_check( void )
{
    SHIP_DATA* ship = NULL, *onship = NULL;
    HANGAR_DATA* hangar = NULL;
    CLAN_DATA* clan = NULL;
    ROOM_INDEX_DATA* room = NULL;
    char buf[MSL];

    for ( ship = first_ship; ship; ship = ship->next )
    {
        if ( ship->calctimer > 0 )
        {
            if ( --ship->calctimer <= 0 )
            {
                ship->hyperlock = TRUE;
                echo_to_ship_windows( AT_GREEN, ship, "[Status]: Hyperspace calculations have been completed." );
            }
        }

        if ( ship->hatchtimer > 0 && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            if ( --ship->hatchtimer <= 0 )
            {
                if ( ship->hatchopen )
                {
                    ship->hatchopen = FALSE;
                    ship->hatchtimer = 0;

                    room = ship->in_room ? ship->in_room : get_room_index( ship->location );
                    if ( xIS_SET( ship->flags, SHIP_VONG ) )
                    {
                        snprintf( buf, MSL, "The hatch membrane on %s snaps shut.", ship->name );
                        echo_to_room( AT_YELLOW, room, buf );
                        echo_to_room( AT_YELLOW, get_ship_entrance( ship ), "The hatch membrane snaps shut." );
                    }
                    else
                    {
                        snprintf( buf, MSL, "The hatch on %s closes.", ship->name );
                        echo_to_room( AT_YELLOW, room, buf );
                        echo_to_room( AT_YELLOW, get_ship_entrance( ship ), "The hatch slides shut." );
                    }
                }
            }
        }

        if ( ship->autolaunch_armed && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )          /* Autolaunch is Armed */
        {
            if ( --ship->autolaunch_time <= 0 )
            {
                bool shields = FALSE;

                if ( ship->in_room )
                    if ( ship->in_room->area )
                        if ( ship->in_room->area->planet )
                            if ( ship->in_room->area->planet->shields >= 25 )
                                shields = TRUE;

                echo_to_ship_windows( AT_YELLOW, ship, "The console flickers an alert: 'Engine Startup Engaged'" );
                echo_to_ship_main( AT_CYAN, ship, "The ship hums as concealed systems whine to full power..." );

                /* Safety Checks */
                if ( ship->shipstate != SHIP_DOCKED || ship->energy < 25 || shields )
                {
                    echo_to_ship_windows( AT_YELLOW, ship, "The console flickers an alert: 'Engine Startup failed'" );
                    echo_to_ship_main( AT_CYAN, ship, "The ship hums as concealed systems whine down to standby..." );
                    ship->autolaunch_time = 0;
                    ship->autolaunch_armed = FALSE;
                    ship->autolaunch_used = FALSE;
                    continue;
                }

                if ( ship->shipowner && ship->squadleader && ( clan = ship->clan ) != NULL && squads_launched( clan ) >= clan->squadrons )
                {
                    echo_to_ship_windows( AT_YELLOW, ship, "The console flickers an alert: 'Engine Startup failed'" );
                    echo_to_ship_main( AT_CYAN, ship, "The ship hums as concealed systems whine down to standby..." );
                    bug( "%s: %s trying to autolaunch %s with too many squads already.", FUNC, clan->name, ship->name );
                    ship->autolaunch_time = 0;
                    ship->autolaunch_armed = FALSE;
                    ship->autolaunch_used = FALSE;
                    continue;
                }

                if ( ( onship = ship_from_hangar( ship->in_room ) ) != NULL )
                {
                    hangar = get_hangar_room( onship, ship->in_room );

                    if ( hangar == NULL )
                        continue;

                    if ( !hangar->bayopen )
                        continue;
                }

                /*
                    Launch the ship!
                */
                if ( ship->shipstate == SHIP_DOCKED )
                {
                    ship->autolaunch_time = 0;
                    ship->autolaunch_armed = FALSE;

                    // For ships smaller than frigates (the first size impacted by clanlimits)
                    if ( ship->classtype < FRIGATE_SHIP )
                    {
                        ship->autolaunch_used = TRUE;

                        // Store the previous autopilot configurations for later use and load in a bare-bones config
                        xCLEAR_BITS( ship->prev_aflags );
                        xSET_BITS( ship->prev_aflags, ship->aflags );
                        xCLEAR_BITS( ship->aflags );
                        xSET_BIT( ship->aflags, AFLAG_SENTINEL );
                        xSET_BIT( ship->aflags, AFLAG_AUTOSHIELD );
                        xSET_BIT( ship->aflags, AFLAG_NOINTERCEPT );
                    }

                    ship->shipstate = SHIP_LAUNCH;
                    ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );

                    if ( xIS_SET( ship->aflags, AFLAG_SENTINEL ) )
                        ship->currspeed = 0;
                    else
                        ship->currspeed = ship->realspeed;

                    ship->autopilot = TRUE;

                    room = ship->in_room ? ship->in_room : get_room_index( ship->location );
                    if ( ship->hatchopen )
                    {
                        ship->hatchopen = FALSE;
                        if ( xIS_SET( ship->flags, SHIP_VONG ) )
                        {
                            snprintf( buf, MSL, "The hatch membrane on %s snaps shut.", ship->name );
                            echo_to_room( AT_YELLOW, room, buf );
                            echo_to_room( AT_YELLOW, get_ship_entrance( ship ), "The hatch membrane snaps shut." );
                        }
                        else
                        {
                            snprintf( buf, MSL, "The hatch on %s closes.", ship->name );
                            echo_to_room( AT_YELLOW, room, buf );
                            echo_to_room( AT_YELLOW, get_ship_entrance( ship ), "The hatch slides shut." );
                        }
                    }

                    echo_to_ship_main( AT_YELLOW, ship, "The ship hums as it lifts off the ground." );
                    snprintf( buf, MSL, "%s begins to launch.", ship->name );
                    echo_to_room( AT_YELLOW, room, buf );
                    save_ship( ship, true );
                }
            }
        }
    }

    return;
}

/*
    Function to check important stuff happening to a player
    This function should take about 5% of mud cpu time
*/
void char_check( void )
{
    CHAR_DATA* ch, *ch_next;
    EXIT_DATA* pexit;
    static int cnt = 0;
    int door, retcode;
    cnt = ( cnt + 1 ) % 2;

    for ( ch = first_char; ch; ch = ch_next )
    {
        set_cur_char( ch );
        ch_next = ch->next;
        will_fall( ch, 0 );

        if ( IS_NPC( ch ) && ch->hit <= 0 )
            ch->hit = 1;

        if ( ch->hit > ch->max_hit )
            ch->hit = ch->max_hit;

        if ( ch->mana > ch->max_mana )
            ch->mana = ch->max_mana;

        if ( isFighting( ch ) )
            ch->fight_timer--;

        if ( !IS_NPC( ch ) && ch->pcdata->botting && ch->pcdata->cooldown != -1 )
        {
            ch->pcdata->botting++;

            if ( ch->pcdata->botting >= ( 60 * 60 * 2 ) )
            {
                send_to_char( "**BOT WARNING**\nBotting time limit reached.\nYou must wait 30 mins before botting again.\nFor info check BOT STATUS.\n\a", ch );
                ch->pcdata->botting = 0;
                ch->pcdata->cooldown = ( 30 * 60 );
                do_visible( ch, "-noalert" );

                if ( ch->block )
                    do_block( ch, "" );

                set_pcflag( ch, PCFLAG_AFK );
                ch_println( ch, "You are now afk." );
                act( AT_GREY, "$n is now afk.", ch, NULL, NULL, TO_ROOM );
                //    interpret( ch, "afk", FALSE );
            }
        }

        if ( !IS_NPC( ch ) && ch->pcdata->cooldown > 0 )
        {
            ch->pcdata->cooldown--;

            if ( ch->pcdata->cooldown <= 0 )
            {
                ch_println( ch, "You may now bot again." );
                ch->pcdata->cooldown = 0;
            }
        }

        if ( ch->action_timer > 0 )
            if ( --ch->action_timer  == 0 )
                action_clear( ch );

        //   if ( !IS_NPC( ch ) && xIS_SET(ch->race->specflags,RSPECFLAG_DEVARONIAN) ) ch->skincolor = 9;

        /* Clan check for hunters, STAY OUT OF EM BRATS! */
        if ( !IS_NPC( ch ) && ch->main_ability == HUNTING_ABILITY ) //&& !xIS_SET(ch->race->specflags,RSPECFLAG_YEVETHAN))
        {
            if ( ch->pcdata->clan && !xIS_SET( ch->pcdata->clan->flags, CLAN_BHCLAN ) ) // !strstr( ch->pcdata->clan->name, "hunter" ) )
            {
                ch_println( ch, "Hunters cannot be part of a clan, sorry." );
                ch->pcdata->clan = NULL;
                SET_STRING( ch->pcdata->clan_name, "" );
            }
        }

        if ( ch->fbonus > 0 )    /* Leveling bonus for combat */
            ch->fbonus--;

        update_pos( ch );

        if ( IS_NPC( ch ) )
        {
            if ( cnt != 0 )
                continue;

            /* running mobs -Thoric */
            if ( xIS_SET( ch->act, ACT_RUNNING ) )
            {
                if ( !xIS_SET( ch->act, ACT_SENTINEL )
                        &&   !ch->fighting && ch->hunting )
                {
                    WAIT_STATE( ch, 2 * PULSE_VIOLENCE );
                    hunt_victim( ch );
                    continue;
                }
                else if ( !xIS_SET( ch->act, ACT_SENTINEL )
                          &&   !ch->fighting && ch->tracking )
                {
                    WAIT_STATE( ch, 2 * PULSE_VIOLENCE );
                    track_victim( ch );
                    continue;
                }

                if ( ch->spec_fun )
                {
                    if ( ( *ch->spec_fun ) ( ch ) )
                        continue;

                    if ( char_extracted( ch ) )
                        continue;
                }

                if ( ch->spec_2 )
                {
                    if ( ( *ch->spec_2 ) ( ch ) )
                        continue;

                    if ( char_extracted( ch ) )
                        continue;
                }

                if ( !ch->master
                        &&   !xIS_SET( ch->act, ACT_SENTINEL )
                        &&   !xIS_SET( ch->act, ACT_PROTOTYPE )
                        && ( door = number_bits( 4 ) ) <= 9
                        && ( pexit = get_exit( ch->in_room, door ) ) != NULL
                        &&   pexit->to_room
                        &&   !xIS_SET( pexit->flags, EX_CLOSED )
                        &&   MOB_CAN_ENTER( pexit->to_room )
                        && ( !xIS_SET( ch->act, ACT_STAY_AREA ) || pexit->to_room->area == ch->in_room->area ) )
                {
                    retcode = move_char( ch, pexit, 0, FALSE );

                    if ( char_extracted( ch ) )
                        continue;

                    if ( retcode != rNONE || xIS_SET( ch->act, ACT_SENTINEL )
                            ||    ch->position < POS_STANDING )
                        continue;
                }
            }

            continue;
        }
        else
        {
            if ( ch->mount
                    &&   ch->in_room != ch->mount->in_room )
            {
                xREMOVE_BIT( ch->mount->act, ACT_MOUNTED );
                ch->mount = NULL;
                ch->position = POS_STANDING;
                ch_println( ch, "No longer upon your mount, you fall to the ground...\nOUCH!" );
            }

            /*
                Cybernetic Updater. Pass only ppl with Cyber Enhancments
            */
            if ( ch->pcdata && ch->first_cyber != NULL )
                c_update( ch );

            if ( ( ch->in_room && ch->in_room->sector_type == SECT_UNDERWATER )
                    || ( ch->in_room && ch->in_room->sector_type == SECT_OCEANFLOOR ) )
            {
                if ( !IS_AFFECTED( ch, AFF_AQUA_BREATH ) && !xIS_SET( ch->race->flags, RFLAG_AQUABREATH ) && ( !ch->spirit ) )
                {
                    if ( get_trust( ch ) < LEVEL_IMMORTAL )
                    {
                        int dam;
                        dam = number_range( ch->max_hit / 50, ch->max_hit / 30 );
                        dam = UMAX( 1, dam );

                        if (  ch->hit <= 0 )
                            dam = UMIN( 10, dam );

                        if ( number_bits( 3 ) == 0 || ch->top_level < 30 )
                            ch_println( ch, "You cough and choke as you try to breathe water!" );

                        damage( ch, ch, dam, TYPE_UNDEFINED );

                        // Check to see if we send to the hospital
                        if ( hospitalZone( ch ) && ch->hit <= -200 )
                        {
                            ch_println( ch, "Water fills your lungs as you make your last attempt to breathe." );
                            act( AT_DEAD, "$n ceases $s struggling and begins to sink deeper into the watery depths.", ch, NULL, NULL, TO_ROOM );
                            sendToHospital( NULL, ch );
                        }
                        // TODO: Don't think we need this else-if because of the below death check
                        else if ( ch->hit <= -490 && !xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) && !IS_IMMORTAL( ch ) )
                        {
                            ch_println( ch, "Water fills your lungs as you make your last attempt to breathe." );
                            raw_kill( ch, ch );
                        }
                    }
                }
            }

            if ( char_extracted( ch ) )
                continue;

            if ( ch->in_room
                    && ( ( ch->in_room->sector_type == SECT_WATER_NOSWIM )
                         ||  ( ch->in_room->sector_type == SECT_WATER_SWIM ) ) )
            {
                if ( !IS_AFFECTED( ch, AFF_FLYING )
                        && !IS_AFFECTED( ch, AFF_FLOATING )
                        && !IS_AFFECTED( ch, AFF_AQUA_BREATH )
                        && !xIS_SET( ch->race->flags, RFLAG_AQUABREATH )
                        && !ch->mount )
                {
                    if ( get_trust( ch ) < LEVEL_IMMORTAL )
                    {
                        int dam;

                        if ( ch->move > 0 )
                            ch->move--;
                        else
                        {
                            dam = number_range( ch->max_hit / 50, ch->max_hit / 30 );
                            dam = UMAX( 1, dam );

                            if (  ch->hit <= 0 )
                                dam = UMIN( 10, dam );

                            if ( number_bits( 3 ) == 0 )
                                ch_println( ch, "Struggling with exhaustion, you choke on a mouthful of water." );

                            damage( ch, ch, dam, TYPE_UNDEFINED );
                        }
                    }
                }
            }
        }
    }
}


/*
    Aggress.

    for each descriptor
       for each mob in room
           aggress on some random PC

    This function should take 5% to 10% of ALL mud cpu time.
    Unfortunately, checking on each PC move is too tricky,
     because we don't the mob to just attack the first PC
     who leads the party into the room.

*/
void aggr_update( void )
{
    DESCRIPTOR_DATA* d = NULL, *d_next = NULL;
    CHAR_DATA* wch = NULL;
    CHAR_DATA* ch = NULL;
    CHAR_DATA* ch_next = NULL;
    CHAR_DATA* victim = NULL;
    char buf[MSL];
    bool still_exists = FALSE;

    ACT_PROG_DATA* runner = NULL, *next_runner = NULL;
    MPROG_ACT_LIST* mpact = NULL, *next_mpact = NULL;

    /* check mobprog act queue */
    for ( runner = first_mob_act; runner; runner = next_runner )
    {
        next_runner = runner->next;
        still_exists = FALSE;

        wch = ( CHAR_DATA* )runner->vo;

        if ( valid_char( wch ) && wch->mpactnum > 0 )
        {
            for ( mpact = wch->first_mpact; mpact; mpact = next_mpact )
            {
                next_mpact = mpact->next;

                if ( mpact->obj && obj_extracted( mpact->obj ) )
                    mpact->obj = NULL;

                if ( valid_char( mpact->ch ) )
                    mprog_wordlist_check( mpact->buf, wch, mpact->ch,
                                          mpact->obj, mpact->vo, ACT_PROG );

                UNLINK( mpact, wch->first_mpact, wch->last_mpact, next, prev );
                FREE_STRUCT_NORET( mpact, mpact_fields );
            }

            wch->mpactnum = 0;
        }

        LINK_HASNODE( first_mob_act, ACT_PROG_DATA, next, runner, still_exists );
        if ( still_exists )
        {
            UNLINK( runner, first_mob_act, last_mob_act, next, prev );
            DISPOSE( runner );
        }
    }

    /*
        Just check descriptors here for victims to aggressive mobs
        We can check for linkdead victims to mobile_update   -Thoric
    */
    for ( d = first_descriptor; d ; d = d_next )
    {
        d_next = d->next;

        if ( ( d->connected != CON_PLAYING && d->connected != CON_EDITING ) || ( wch = d->character ) == NULL )
            continue;

        if ( IS_NPC( wch ) || wch->top_level >= LEVEL_IMMORTAL || !wch->in_room )
            continue;

        for ( ch = wch->in_room->first_person; ch; ch = ch_next )
        {
            int count = 0;
            ch_next = ch->next_in_room;

            if ( !IS_NPC( ch )
                    ||   ch->fighting
                    ||   IS_AFFECTED( ch, AFF_CHARM )
                    ||   !IS_AWAKE( ch )
                    ||   ( xIS_SET( ch->act, ACT_WIMPY ) )
                    ||   !can_see( ch, wch )
                    ||   is_safe( ch, wch ) )
                continue;

            if ( is_hating( ch, wch ) )
            {
                found_prey( ch, wch );
                continue;
            }

            if ( !xIS_SET( ch->act, ACT_AGGRESSIVE )
                    ||    xIS_SET( ch->act, ACT_MOUNTED )
                    ||    is_safe( ch, wch ) )
                continue;

            victim = wch;

            if ( !victim )
            {
                bug( "Aggr_update: null victim.", count );
                continue;
            }

            // When a mob sees a group, it should always prefer the leader of the group.
            if ( victim->leader
                    && victim->leader->in_room == victim->in_room
                    && !is_safe( ch, victim ) )
                victim = victim->leader;

            if ( IS_NPC( ch ) && xIS_SET( ch->attacks, ATCK_BACKSTAB ) )
            {
                SKILL_DATA* skill = cache_skill( "backstab", &skill_backstab );
                OBJ_DATA* obj;

                if ( skill && !ch->mount
                        && ( obj = get_eq_char( ch, WEAR_WIELD ) ) != NULL
                        && obj->value[3] == 11
                        && !victim->fighting
                        && victim->hit >= victim->max_hit )
                {
                    WAIT_STATE( ch, skill->beats );

                    if ( !IS_AWAKE( victim )
                            ||   number_percent( ) + 5 < ch->top_level )
                    {
                        global_retcode = multi_hit( ch, victim, skill->id );
                        continue;
                    }
                    else
                    {
                        global_retcode = damage( ch, victim, 0, skill->id );
                        continue;
                    }
                }
            }

            if ( !IS_NPC( victim ) && victim->hit <= 0 ) //When a mob aggros you and you're stunned, just go ahead and finish you off. Gathorn 16Jun19
            {
                snprintf( buf, MSL, "&c%s sees %s in a vulnerable state and finishes them off.", ch->name, victim->name );
                act( AT_PLAIN, buf, ch, NULL, victim, TO_ROOM );
                damage( ch, victim, 500, TYPE_UNDEFINED );
            }
            else
                global_retcode = multi_hit( ch, victim, TYPE_UNDEFINED );
        }
    }

    return;
}

