void tele_update( void )
{
    TELEPORT_DATA* tele, *tele_next;

    if ( !first_teleport )
        return;

    for ( tele = first_teleport; tele; tele = tele_next )
    {
        tele_next = tele->next;

        if ( --tele->timer <= 0 )
        {
            if ( tele->room->first_person )
            {
                teleport( tele->room->first_person, tele->room->tele_vnum,
                          TELE_TRANSALL );
            }

            UNLINK( tele, first_teleport, last_teleport, next, prev );
            DISPOSE( tele );
        }
    }
}

void auth_update( void )
{
    if ( !sysdata.WAIT_FOR_AUTH )
        return;

    CHAR_DATA* victim;
    DESCRIPTOR_DATA* d;
    char buf [MIL], log_buf [MIL];
    bool found_hit = FALSE;         /* was at least one found? */
    strlcpy( log_buf, "Pending authorizations:\n", MIL );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( ( victim = d->character ) && IS_WAITING_FOR_AUTH( victim ) )
        {
            found_hit = TRUE;
            snprintf( buf, MIL, " %s@%s new %s\n", victim->name,
                     victim->desc->host, victim->race->race_name );
            strlcat( log_buf, buf, MIL );
        }
    }

    if ( found_hit )
    {
        log_string( log_buf );
        to_channel( log_buf, CHANNEL_MONITOR, "Monitor", 1 );
    }
}

void update_publish_stats() {
    // get the player counts
    char buf[MSL];

    DESCRIPTOR_DATA* d;
    CHAR_DATA* victim;

    int pcount = 0;


    for ( d = first_descriptor; d; d = d->next )
        if ( ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                && ( victim = d->character ) != NULL
                &&   !IS_NPC( victim )
                &&   victim->in_room )
        {
            if ( !IS_IMMORTAL( victim ) )
            {

                pcount++;

            }

        }
    mqtt_publish("out/stats/playerCount", "%d", pcount);
    snprintf( buf, MSL, "%d - Online", pcount );
    discord_set_presence_activity(buf, NULL);
}

void update_publish_status(int status) {    
    char buf[MSL];
    char *msg = NULL;
    if (status == STATUS_AUTO) {
        if(sysdata.cpy != 0) {
            status = STATUS_COPYOVER_SCHEDULED;
        } else {
            status = STATUS_ONLINE;
        }
    }
    switch(status) {
        case STATUS_COPYOVER_CANCELED:
            msg = "Copyover Canceled!";
            mqtt_publish("out/stats/status", "copyover_canceled");

            // Fallthrough
        case STATUS_COPYOVER_RECOVERED:
            if(status == STATUS_COPYOVER_RECOVERED) {
                msg = "Recovered from copyover!";
                mqtt_publish("out/stats/status", "copyover_recovered");
            }
            // Fallthrough
        case STATUS_COLD_BOOT:
            if(status == STATUS_COLD_BOOT) {
                msg = "The mud has booted up!";
                mqtt_publish("out/stats/status", "coldboot");
            }
            // Fallthrough
        case STATUS_ONLINE:
            mqtt_publish("out/stats/status", "online");
            update_publish_stats();
            break;
        case STATUS_COPYOVER_NOW:
            msg = "Engaging Copyover NOW!";
            mqtt_publish("out/stats/status", "copyover_now");
            discord_set_presence_activity(" - Copyover NOW", NULL);
            break;
        case STATUS_COPYOVER_WARN:
            int cpyminutes = sysdata.cpy / 60;
            snprintf(buf, MSL, "Copyover in %d minute%c.", cpyminutes, cpyminutes  != 1 ? 's' : ' ');
            msg = buf;
            // Fallthrough
        case STATUS_COPYOVER_SCHEDULED:
            mqtt_publish("out/stats/status", "copyover_scheduled");
            discord_set_presence_activity(" - Copyover Soon", NULL);
            break;
        case STATUS_SHUTDOWN:
            msg = "Shutting down...";
            mqtt_publish("out/stats/status", "shutdown");
            discord_set_presence_activity(" - Game offline.", NULL);
            break;
    }
    if(msg) {
        discord_sendchan(dbc_yolo_get_string(DBC_SETTING_DISCORD_GENERAL_CHANNEL, 
                                                        DBC_SETTING_DISCORD_GENERAL_CHANNEL_DEFAULT), msg);
        discord_sendchan(dbc_yolo_get_string(DBC_SETTING_DISCORD_SERVERSTATUS_CHANNEL, 
                                                DBC_SETTING_DISCORD_SERVERSTATUS_CHANNEL_DEFAULT), msg);
    }

}

