void check_memory() {
    static int high_water_mark = 0;
    struct mallinfo2 mi;
    mi = mallinfo2();

    // Correct definition with proper type and parentheses
    int max_memory = dbc_yolo_get_int(DBC_SETTING_MAX_MEMORY, DBC_SETTING_MAX_MEMORY_DEFAULT);
    int warn_percentage = dbc_yolo_get_int(DBC_SETTING_MEMORY_WARN_PERCENTAGE, DBC_SETTING_MEMORY_WARN_PERCENTAGE_DEFAULT);

    int used_memory = (int)((mi.arena + mi.hblkhd) / 1024 / 1024);

    if (used_memory > high_water_mark && sysdata.autocopy == AUTOCOPY_NONE) {
        int warn_memory = (int)(max_memory * warn_percentage / 100);
        // did we just cross the threshold?
        if (used_memory > warn_memory && warn_memory < high_water_mark) {
            char msg_buf[MSL];
            snprintf(msg_buf, MSL, "Memory usage is over %d megabytes (%d percent of soft limit). Current usage: %d (%d percent of soft limit).",
            warn_memory, warn_percentage, used_memory, (int)(used_memory * 100 / max_memory));
            lognormal(msg_buf);
            discord_sendchan(DISCORD_CODING_EMERG, msg_buf);
        }
        high_water_mark = UMIN(used_memory + 25, max_memory - 5);
    }

    // Check if the program is using more than 2GB of RAM
    if (used_memory > max_memory && sysdata.autocopy == AUTOCOPY_NONE) {
        char msg_buf[MSL];
        snprintf(msg_buf, MSL, "Memory usage is over %d megabytes. Scheduling copyover...", max_memory);
        lognormal(msg_buf);
        discord_sendchan(DISCORD_CODING_EMERG, msg_buf);
        // schedule copyover
        sysdata.autocopy = AUTOCOPY_NORMAL;
        sysdata.cpy = 60;
        autosave();
        echo_to_all(AT_RED, "COPYOVER IN ONE MINUTE, YOUR CHARACTER HAS BEEN SAVED\\n", ECHOTAR_ALL);
    }
}

int update_deaths(UPDATE_INTERVAL_DATA *task, int budget, UNUSED(int delta_time) )
{
    static char flipflop = 1;
    char dead_char_name[MIL];
    for (DEATH_DATA *death = first_death; death; death = death->next)
    {
        if (budget <= 0) {
            task->pulses_left = 1; // continue next pulse
            return 0;
        }
        if (death->flipflop == flipflop)
            continue;

        debug("%s: Checking death ownership for: %s", FUNC, death->victim);

        clock_t start_time = clock();  // Start time for this iteration

        if (death->expiration > 0 && death->expiration <= current_time)
        {
            lognormal("Death ownership timer expired. Clearing ownership for: %s", death->victim);
            one_argument(death->victim, dead_char_name);
            slay_vendors(dead_char_name);
            close_accounts(dead_char_name);
            clean_player_ships(dead_char_name);
            clean_player_structures(dead_char_name);
            clean_player_home(dead_char_name);
            death->expiration = 0;
            death_save(death);
        }

        // Decrement budget based on time spent in this iteration
        budget -= (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
    }
    flipflop = (flipflop == 1 ? 2 : 1);
    return E_LOTJ_SUCCESS;
}

/*
    Handle all kinds of updates.
    Called once per pulse from game loop.
    Random times to defeat tick-timing clients and players.
*/

/*
typedef struct {
    const char *name;
    // function pointer
    void (*func)(void);
    int interval;
    int pulses_left;
    int max_ms;
    int min_ms;
    int history_ms[UPDATE_INTERVAL_HISTORY_LENGTH]; // An array of the last N durations
    int times_deferred;
} UPDATE_INTERVAL_DATA;
*/
UPDATE_INTERVAL_DATA make_update_task_ex( const char* name, void (*func)(void), int (*func_ext)(UPDATE_INTERVAL_DATA *interval, int budget, int delta_time), int interval, int initial_pulses_left )
{
    UPDATE_INTERVAL_DATA result;
    result.name = name;
    result.func = func;
    result.func_ext = func_ext;
    result.interval = interval;
    result.pulses_left = initial_pulses_left;
    result.max_ms = -1;
    result.last_ms = -1;
    result.last_run_time_ms = 0;
    for ( int i = 0; i < UPDATE_INTERVAL_HISTORY_LENGTH; i++ )
        result.history_ms[i] = -1;
    result.times_deferred = 0;
    return result;
}

UPDATE_INTERVAL_DATA make_update_task( const char* name, void (*func)(void), int interval )
{
    return make_update_task_ex( name, func, NULL, interval, interval );
}

