#define MAX_BUDGET 185

int task_runtime_avg( UPDATE_INTERVAL_DATA* task )
{
    int history_count = 0;
    int history_ms_sum = 0;
    for ( int i = 0; i < UPDATE_INTERVAL_HISTORY_LENGTH; i++ )
    {
        if ( task->history_ms[i] != -1 )
        {
            history_count++;
            history_ms_sum += task->history_ms[i];
        }
    }
    if ( history_count == 0 )
        return -1;
    return history_ms_sum / history_count;
}

void record_task_runtime( UPDATE_INTERVAL_DATA* task, int duration )
{
    // Slide all values back one
    for ( int i = 1; i < UPDATE_INTERVAL_HISTORY_LENGTH; i++ )
        task->history_ms[i-1] = task->history_ms[i];
    // Put new value at the end of the array
    task->history_ms[UPDATE_INTERVAL_HISTORY_LENGTH-1] = duration;
}

void do_updateinfo(CHAR_DATA *ch, const char *args)
{
    char colstr[8], task_name[19];
    int cnt = 0;

    if(!NULLSTR(args)) {
        // get the first argumetn
        char arg1[MIL];
        args = one_argument(args, arg1);
        if(!str_cmp(arg1, "run")) {
            // next arg should be the name of the task
            for (int i = 0; i < INTERVAL_DATA_MAX; i++) {
                if(update_tasks[i].name && !str_prefix(args, update_tasks[i].name)) {
                    // update its pulses left to INT_MIN, so it runs immediately
                    update_tasks[i].pulses_left = INT_MIN + 1;
                    ch_printf(ch, "Task %s will run immediately.\n", update_tasks[i].name);
                    return;
                }
            }
            ch_printf(ch, "Task %s not found.\n", args);
            return;
        }

        ch_printf(ch, "Unknown argument: %s\n", arg1);
        return;
    } else {



        // sort the list
        for (int i = 0; i < INTERVAL_DATA_MAX; i++) {
            for (int j = i + 1; j < INTERVAL_DATA_MAX; j++) {
                if (update_tasks[i].name != NULL && update_tasks[j].name != NULL && 
                    update_tasks[i].pulses_left > update_tasks[j].pulses_left) {
                    // Swap tasks if they are out of order
                    UPDATE_INTERVAL_DATA temp = update_tasks[i];
                    update_tasks[i] = update_tasks[j];
                    update_tasks[j] = temp;
                }
            }
        }

        ch_println( ch, "Update Tasks:" );

        for (int i = INTERVAL_DATA_MAX - 1; i >= 0; i--)
        {
            cnt++;
            snprintf( colstr, 8, "%s", cnt % 2 == 0 ? "&037" : "&116" );
            if(i % 20 == 0)
                ch_println( ch, "\n&z%-18s %-8s %-5s %-12s %-6s %-7s %-7s",
                "Task Name", "Interval", "Left", "Recent Avg", "Last", "Max", "Def" );

            UPDATE_INTERVAL_DATA *task = &update_tasks[i];
            if (task->name)
            {
                int recent_avg = task_runtime_avg( task );
                // Truncate task name if necessary
                snprintf(task_name, 19, "%.18s", task->name);
                ch_println( ch, 
                    "%s%-18s %s%-8d %s%-5d %s%-12d %s%-7d %s%-7d %s%-7d", 
                    colstr, task_name, colstr, task->interval, 
                    (task->pulses_left < 0 ? "&Y" : colstr), task->pulses_left, 
                    (recent_avg >= MAX_BUDGET ? "&Y" : colstr), recent_avg, 
                    (task->last_ms > MAX_BUDGET ? "&Y" : colstr), task->last_ms, 
                    (task->max_ms > MAX_BUDGET ? "&Y" : colstr), task->max_ms, 
                    (task->times_deferred > 0 ? "&Y" : colstr), task->times_deferred );
            }
        }
    }

    ch_printf(ch, "\n&zUse updateinfo run <task> to schedule a task to run immediately.\n");

    return;
}

void update_budgeted_updates(int milliseconds) {
    // First loop: decrement pulses_left
    for (int i = 0; i < INTERVAL_DATA_MAX; i++) {
        UPDATE_INTERVAL_DATA *task = &update_tasks[i];
        if (task->name == NULL) {
            continue;
        }
        task->pulses_left--;  // Decrement pulses left
    }

    // Second loop: execute tasks
    // Sort tasks based on pulses_left in ascending order
    for (int i = 0; i < INTERVAL_DATA_MAX; i++) {
        for (int j = i + 1; j < INTERVAL_DATA_MAX; j++) {
            if (update_tasks[i].name != NULL && update_tasks[j].name != NULL && 
                update_tasks[i].pulses_left > update_tasks[j].pulses_left) {
                // Swap tasks if they are out of order
                UPDATE_INTERVAL_DATA temp = update_tasks[i];
                update_tasks[i] = update_tasks[j];
                update_tasks[j] = temp;
            }
        }
    }

    for (int i = 0; i < INTERVAL_DATA_MAX; i++) {
        UPDATE_INTERVAL_DATA *task = &update_tasks[i]; // Get a pointer to the actual array element
        if ( task->name == NULL )
            continue;

        int budget = task_runtime_avg( task );
        if (budget > MAX_BUDGET) {
            debug("update_budgeted_updates: %s has recent avg of %d ms, which is over the max budget of %d ms", task->name, budget, MAX_BUDGET);
            budget = MAX_BUDGET;
        }

        // Delay a task by no more than 50% of its scheduled interval
        int max_defers = task->interval * 0.5;

        // Run this update if:
        // - We have nonzero time left allotted to this update cycle
        // - The task is due to be run
        // - We have enough time left in the update cycle to fit the task based on its recent average runtimes
        //   OR it has been deferred too much already
        //   OR it's an extended func signature, which we expect will stick to its budget whatever we give it
        if (milliseconds > 5 && task->pulses_left <= 0 && (task->func_ext || budget <= milliseconds || task->pulses_left < -1 * max_defers))
        {
            clock_t start_time = clock();
            if(task->func_ext) {
                int delta_time = task->interval * PULSE_PER_SECOND * 1000;
                budget = UMAX(UMIN(budget * 2, milliseconds * 80 / 100 ), 5); // let the budget grow exponentially if it needs to, up to 80% of the max
                if(task->last_run_time_ms > 0 ) {
                    delta_time = get_current_time_ms() - task->last_run_time_ms;
                }
                WOF(task->func_ext(task, budget, delta_time));
            } else {
                task->func();
            }
            task->last_run_time_ms = get_current_time_ms();
            clock_t end_time = clock();
            int elapsed_time = (end_time - start_time) * 1000 / CLOCKS_PER_SEC;
            record_task_runtime( task, elapsed_time );
            milliseconds -= elapsed_time;

            //lognormal("update_budgeted_updates: %s took %d ms to run", task->name, elapsed_time);
            if (elapsed_time > UMAX(budget, 50) * 110 / 100) { // 10% grace
                debug("update_budgeted_updates/over_budget: %s took %d ms to run, over budget of %d ms", task->name, elapsed_time, budget);
            }
            debug("update_budgeted_updates/runtime: %s budget: %d ms, elapsed: %d ms", task->name, budget, elapsed_time);
            if (task->max_ms == -1 || elapsed_time > task->max_ms) {
                task->max_ms = elapsed_time;
            }
            task->last_ms = elapsed_time;

            if(task->pulses_left <= 0) {
                task->pulses_left = task->interval;
            }

        } else {
            // we want to run but couldn't for some reason, probably budget.
            if(task->pulses_left < 0) {
                task->times_deferred++;
                increment_counter(&sysdata.metrics, "deferred_updates", NO_FLAG );
                debug("update_budgeted_updates: %s deferred %d times, needed %d but only had %d", task->name, task->times_deferred, budget, milliseconds);
            }
        }
    }
}

void update_handler( int milliseconds )
{
    static  int     pulse_emergency;
    static  int     flag_dissolves;
    struct timeval stime;  
    struct timeval etime;

    clock_t start_time = clock();

    if(milliseconds <= 0)
        debug("%s: Warning, entering update_handler with %d ms of budget!", FUNC, milliseconds);

    if ( timechar )
    {
        set_char_color( AT_PLAIN, timechar );
        ch_println( timechar, "Starting update timer." );
        gettimeofday( &stime, NULL );
    }

    if ( pulse_emergency == 0 )
    {
        pulse_emergency    = PULSE_EMERGENCY;
    }
    else if ( --pulse_emergency <= 0 )
    {
        debug( "update_handler: pulse emergency" );
        pulse_emergency = PULSE_EMERGENCY;
        /* Arm Emergency Copyover mode */
        emergency_arm( );
        sysdata.waited = TRUE;
    }

    if ( ( current_time % 86400 ) == 0 )
    {
        if ( flag_dissolves == 0 )
        {
            flag_dissolves = 1;
            check_dissolves();
        }
    }

    debug( "update_handler: pulse remainder" );
    mpsleep_update();  /* MPSLEEP Driver */
    tele_update( );
    aggr_update( );
    obj_act_update ( );
    room_act_update( );
    clean_extract_queue();
    update_lua_timers();
    mqtt_update( 100 );    // limit to 100ms for now
    rpc_handle_timeouts();

    if ( timechar )
    {
        gettimeofday( &etime, NULL );
        set_char_color( AT_PLAIN, timechar );
        ch_println( timechar, "Update timing complete." );
        subtract_times( &etime, &stime );
        ch_println( timechar, "Timing took %d.%06d seconds.",
                   etime.tv_sec, etime.tv_usec );
        timechar = NULL;
    }

    tail_chain( );

    int elapsed_ms = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;

    milliseconds -= elapsed_ms;

    update_budgeted_updates(milliseconds);

    debug( "update_handler: end" );
    return;
}


void remove_portal( OBJ_DATA* portal )
{
    ROOM_INDEX_DATA* fromRoom, *toRoom;
    CHAR_DATA* ch;
    EXIT_DATA* pexit;
    bool found;

    if ( !portal )
    {
        bug( "remove_portal: portal is NULL", 0 );
        return;
    }

    fromRoom = portal->in_room;
    found = FALSE;

    if ( !fromRoom )
    {
        bug( "remove_portal: portal->in_room is NULL", 0 );
        return;
    }

    for ( pexit = fromRoom->first_exit; pexit; pexit = pexit->next )
        if ( xIS_SET( pexit->flags, EX_PORTAL ) )
        {
            found = TRUE;
            break;
        }

    if ( !found )
    {
        bug( "remove_portal: portal not found in room %d!", fromRoom->vnum );
        return;
