    return;
}

void update_grenade ( void )
/* GRAL Need to hack timer landmines here */
{
    OBJ_DATA* obj, *oprev;

    for ( obj = last_object; obj; obj = oprev )
    {
        if ( obj == first_object && obj->prev )
        {
            bug( "update_grenade: first_obj->prev != NULL... fixed", 0 );
            obj->prev = NULL;
        }

        oprev = obj->prev;

        if ( oprev && oprev->next != obj )
        {
            // this can happen if one grenade scraps another, it's not really a bug
            bug( "update_grenade: obj->prev->next != obj", 0 );
            return;
        }

        if ( obj->item_type != ITEM_GRENADE && obj->item_type != ITEM_BOMB && obj->item_type != ITEM_LANDMINE )
            continue;

        if ( obj->value[4] <= 0 )
            continue;

        // When there are about 2 minutes left, do an ominous warning.
        if ( obj->in_room && obj->item_type == ITEM_LANDMINE && obj->value[4] == 30 )
            echo_to_room( AT_YELLOW, obj->in_room, "The whirring noise gets louder..." );

        // dont tick if not armed ~Miros
        if ( obj->armed_by && str_cmp( obj->armed_by, "" ) &&  --obj->value[4] <= 0 )
        {
            /* BaaaaBOOOOOOOOM -Ghost */
            explode_obj( obj );
        }
    }

    return;
}

void update_backup ( void )
{
    CHAR_DATA* ch;

    for ( ch = last_char; ch; ch = gch_prev )
    {
        if ( ch == first_char && ch->prev )
        {
            bug( "char_update: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;
        set_cur_char( ch );

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "update_backup: ch->prev->next != ch", 0 );
            return;
        }

        /*
            Update Carrying
        */
        if ( ch->carrying != NULL )
        {
            if ( ch->carrying->in_room != ch->in_room )
            {
                char_from_room( ch->carrying );
                char_to_room( ch->carrying, ch->in_room );
            }

            if ( IS_AWAKE( ch->carrying ) || ch->carrying->fighting )
            {
                act( AT_LBLUE, "$N releases you, dropping you on the ground.", ch->carrying, NULL, ch, TO_CHAR );
                act( AT_LBLUE, "You release $N, dropping $M on the ground.", ch, NULL, ch->carrying, TO_CHAR );
                act( AT_LBLUE, "$n releases $N, dropping $M on the ground..", ch, NULL, ch->carrying, TO_NOTVICT );
                ch->carrying->carried = NULL;
                ch->carrying = NULL;
            }
        }

        if ( ch->carried != NULL )
        {
            if ( ch->carried->carrying == NULL )
            {
                bug( "[ERROR]: Fault in carrying module. Dropping player." );
                ch->carried = NULL;
            }
        }

        /*
            Update Backup
        */
        if ( ch->called )
        {
            ch->called->wait_time--;

            if ( ch->called->wait_time <= 0 )
                add_reinforcements( ch );
        }
    }

    return;
}

/* Major overhaul, basically modified so it doesn't eat CPU like popcorn   Orion */
void update_planetary ( void )
{
    char buf[MSL];
    TURRET_DATA* pturret = NULL;
    //  AREA_DATA* area;
    ROOM_INDEX_DATA* room = NULL;
    PLANET_DATA* planet = NULL;
    SPACE_DATA* space = NULL;
    CLAN_DATA* clan = NULL, *tclan = NULL;
    SHIP_DATA* target = NULL;
    double chance = 0;

    /*
        AUTOFIRE Mode for Planetary Weapons. Tracks and attacks enemy vessels.
    */
    for ( pturret = first_pturret; pturret; pturret = pturret->next )
    {
        room = pturret->room;

        if ( !room || room_extracted( room ) )
            continue;

        if ( pturret->laserstate > 0 )
        {
            pturret->laserstate--;

            if ( pturret->laserstate == 0 )
                echo_to_room ( AT_RED, room, "[ALERT]: Charging complete ... Ready to fire.\n" );
        }

        planet = get_planet_from_room( room );

        if ( !planet )
            continue;

        if ( !xIS_SET( planet->flags, PLANET_AUTOFIRE ) )
            continue;

        if ( ( space = planet->starsystem ) == NULL )
            continue;

        if ( !xIS_SET( room->flags, ROOM_WEAP_ION ) && !xIS_SET( room->flags, ROOM_WEAP_TURBOLASER ) )
            continue;

        if ( pturret->laserstate > 0 )
            continue;

        if ( pturret->target != NULL )
        {
            int allow = 0;

            if ( ship_extracted( pturret->target ) || pturret->target->cloakstatus == CLOAK_ON )
            {
                pturret->target = NULL;
                continue;
            }

            if ( pturret->target->starsystem != space )
            {
                pturret->target = NULL;
                continue;
            }

            if ( vector_distance( &pturret->target->vpos, &planet->pos ) > 5000 )
            {
                pturret->target = NULL;
                continue;
            }

            chance += pturret->target->classtype * 25;
            chance -= pturret->target->maneuver / 10;
            chance -= pturret->target->currspeed / 20;
            chance -= ( fabs( planet->pos.x - ( int )pturret->target->vpos.x ) / 70 );
            chance -= ( fabs( planet->pos.y - ( int )pturret->target->vpos.y ) / 70 );
            chance -= ( fabs( planet->pos.z - ( int )pturret->target->vpos.z ) / 70 );
            chance = URANGE( 30, chance, 90 );

            if ( number_range( 1, 100 ) > chance )
            {
                pturret->laserstate += 2;
                snprintf( buf, MSL, "Something opens fire from the surface of %s, barely missing %s!", planet->name, pturret->target->name );
                echo_to_system_noqueue_noship( AT_ORANGE, pturret->target->starsystem, buf );
                snprintf( buf, MSL, "You are almost hit by fire from the surface of %s!", planet->name );
                echo_to_ship_windows( AT_BLOOD, pturret->target, buf );
            }

            if ( xIS_SET( room->flags, ROOM_WEAP_ION ) )
                allow += 1;

            if ( xIS_SET( room->flags, ROOM_WEAP_TURBOLASER ) )
                allow += 2;

            if ( allow == 3 )
                allow = number_range( 1, 2 );

            if ( allow == 1 )
            {
                snprintf( buf, MSL, "Ion blasts erupt from the surface of %s, hitting %s!", planet->name, pturret->target->name );
                echo_to_system_noqueue_noship( AT_ORANGE, pturret->target->starsystem, buf );
                snprintf( buf, MSL, "You are hit by ion blasts from the surface of %s!\n", planet->name );
                echo_to_ship_windows( AT_BLOOD, pturret->target, buf );

                if ( number_range( 1, 10 ) >= 5 )
                    echo_to_ship_main( AT_RED, pturret->target, "A small explosion vibrates through the ship." );

                if ( !xIS_SET( planet->flags, PLANET_FULLTURRETS ) )
                {
                    damage_ship_ion( pturret->target, 26, 30, NULL );
                }
                else
                {
                    int mindam = pturret->target->maxshield * .1;
                    damage_ship_ion( pturret->target, mindam, mindam * 2, NULL );
                }

                pturret->laserstate += 1;
            }

            if ( allow == 2 )
            {
                snprintf( buf, MSL, "Turbolasers erupt from the surface of %s, hitting %s!", planet->name, pturret->target->name );
                echo_to_system_noqueue_noship( AT_ORANGE, pturret->target->starsystem, buf );
                snprintf( buf, MSL, "You are hit by turbolasers from the surface of %s!\n", planet->name );
                echo_to_ship_windows( AT_BLOOD, pturret->target, buf );

                if ( number_range( 1, 10 ) >= 5 )
                    echo_to_ship_main( AT_RED, pturret->target, "A massive explosion rips through the ship!" );

                if ( !xIS_SET( planet->flags, PLANET_FULLTURRETS ) )
                {
                    damage_ship( pturret->target, 26, 30, NULL, NULL );
                }
                else
                {
                    int mindam = pturret->target->maxhull * .1;
                    damage_ship( pturret->target, mindam, mindam * 2, NULL, NULL );
                }

                pturret->laserstate += 2;
            }
        }
        else
        {
            /* Locate a fresh target =) */
            clan = planet->governed_by;

            if ( clan != NULL && planet->starsystem )
            {
                for ( target = planet->starsystem->first_ship; target; target = target->next_in_starsystem )
                {
                    if ( vector_distance( &target->vpos, &planet->pos ) > 5000 )
                        continue;

                    if ( ( tclan = target->clan ) != NULL )
                    {
                        if ( enemy_clan( clan, tclan ) )
                        {
                            pturret->target = target;
                        }
                    }
                    else if ( is_pirate( target ) )
                    {
                        if ( !pturret->target || vector_distance( &planet->pos, &target->vpos ) < vector_distance( &planet->pos, &pturret->target->vpos ) )
                            pturret->target = target;
                    }
                }
            }
        }
    }

    return;
}

void reboot_check( time_t reset )
{
    static char* tmsg[] =
    {
        "SYSTEM: Reboot in 1 seconds.",
        "SYSTEM: Reboot in 2 seconds.",
        "SYSTEM: Reboot in 3 seconds.",
        "SYSTEM: Reboot in 4 seconds.",
        "SYSTEM: Reboot in 5 seconds.",
        "SYSTEM: Reboot in 10 seconds.",
        "SYSTEM: Reboot in 30 seconds.",
        "SYSTEM: Reboot in 1 minute.",
        "SYSTEM: Reboot in 2 minutes.",
        "SYSTEM: Reboot in 3 minutes.",
        "SYSTEM: Reboot in 4 minutes.",
        "SYSTEM: Reboot in 5 minutes.",
        "SYSTEM: Reboot in 10 minutes.",
    };
    static const int times[] = { 1, 2, 3, 4, 5, 10, 30, 60,
                                 120, 180, 240, 300, 600
                               };
    static const int timesize =
        UMIN( sizeof( times ) / sizeof( *times ), sizeof( tmsg ) / sizeof( *tmsg ) );
    static int trun;
    static bool init;

    if ( !init || reset >= current_time )
    {
        for ( trun = timesize - 1; trun >= 0; trun-- )
            if ( reset >= current_time + times[trun] )
                break;

        init = TRUE;
        return;
    }

  /*  if ( ( current_time % 1800 ) == 0 )
    {
        snprintf( buf, MSL, "%.24s: %d players", ctime( &current_time ), num_descriptors );
        append_to_file( USAGE_FILE, buf );
    }*/

    if ( new_boot_time_t - true_boot_time < 60 * 60 * 18 &&
            ( !set_boot_time || !set_boot_time->manual ) )
        return;

    if ( new_boot_time_t <= current_time )
    {
        CHAR_DATA* vch;
        extern bool mud_down;

        for ( vch = first_char; vch; vch = vch->next )
            if ( !IS_NPC( vch ) )
                save_char_obj( vch, true );

        mud_down = TRUE;
        return;
    }

    if ( trun != -1 && new_boot_time_t - current_time <= times[trun] )
    {
        echo_to_all( AT_YELLOW, tmsg[trun], ECHOTAR_ALL );

        if ( trun <= 5 )
            sysdata.DENY_NEW_PLAYERS = TRUE;

        --trun;
        return;
    }

    return;
}

void subtract_times( struct timeval* etime, struct timeval* stime )
{
    etime->tv_sec -= stime->tv_sec;
    etime->tv_usec -= stime->tv_usec;

    while ( etime->tv_usec < 0 )
    {
        etime->tv_usec += 1000000;
        etime->tv_sec--;
    }

    return;
}

/*
    Detects if certain 'problem' files are exceeding a set limit.
    Sends a warning to all immortals when this occurs.

    If files exceed their 'failsafe' limit they are either
    taken offline or wiped clean.
*/
void update_logalerts( void )
{
    char buf[MSL];
    int size = 0;

    /*
        Update for log.txt
         Limit: 2.5 megabytes (25000000 bytes)
         Failsafe: 5 megabytes (Clears log file)
    */
    snprintf( buf, MSL, "%s%s", SYSTEM_DIR, LOG_FILE );

    if ( ( size = file_size( buf ) ) > 5000000 )
    {
        /* Execute failsafe */
        snprintf( buf, MSL, "[ALERT]: Log.txt exceeds 5 megabyte failsafe! File will be deleted. (%d bytes)", size );
        log_string( buf );

        if ( !remove( LOG_FILE ) )
            log_string( "[ALERT]: Log.txt successful cleared. File is now empty." );
        else if ( errno != ENOENT )
            log_string( "[ALERT]: Log.txt could not be cleared. Contact Ghost or Raven." );
    }
    else if ( size > 2500000 )
    {
        snprintf( buf, MSL, "[WARNING]: Log.txt exceeds maximum file limit. (%d bytes)", size );
        log_string( buf );
    }

    return;
}

