void update_economy( void )
{
    PLANET_DATA* planet;
    SPACE_DATA* system = NULL;

    for ( planet = first_planet; planet; planet = planet->next )
    {
        if ( ( system = planet->starsystem ) == NULL )
            continue; /* No updating unattached planets */

        if ( xIS_SET( planet->flags, PLANET_PIRATED ) )
