        // Update all resource prices
        for ( CARGO_PRICE_DATA* cp = planet->first_cargo_price; cp; cp = cp->next )
            update_cargo_price( cp );

        /* Save the changes */
        save_planet( planet, true );
    }

    return;
}

int process_char_saves( int milliseconds )
{
    if ( milliseconds <= 0 )
        return 0;

    clock_t start_time = clock();

    for ( CHAR_DATA* ch = first_char; ch; ch = ch->next )
    {
        if ( ch->save_queued )
        {
            save_char_obj( ch, false );
            milliseconds -= (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
            if ( milliseconds <= 0 ) return 0;
            start_time = clock();
        }
