int clean_extract_queue( void )
{
    QUEUE_DATA* queue = NULL, *next_queue = NULL;

    for ( int type = 0; type < MAX_EXTRACT_TYPE; type++ )
    {
        for ( queue = first_queued_extract[type]; queue; queue = next_queue )
        {
            next_queue = queue->next;
            switch ( queue->type )
            {
                case EXTRACT_CHAR:
                    free_char( queue->ptr );
                    cur_qchars--;
                    break;

                case EXTRACT_OBJ:
                    free_obj( queue->ptr );
                    cur_qobjs--;
                    break;

                case EXTRACT_SHIP:
                    FREE_STRUCT_NORET( queue->ptr, ship_fields );
                    cur_qships--;
                    break;

                case EXTRACT_ROOM:
                    FREE_STRUCT_NORET( queue->ptr, room_index_fields );
                    cur_qrooms--;
                    break;

                default:
                    bug( "%s: invalid extract type %d", FUNC, queue->type );
                    break;
            }

            UNLINK( queue, first_queued_extract[type], last_queued_extract[type], next, prev );
            DISPOSE( queue );
        }
    }

    return E_LOTJ_SUCCESS;
}

/*
    Event Updating Routines  [Coded by Nield]
*/
void update_events( void )
{
    CUSTOM_EVENT_DATA* event;

    for ( event = first_event; event; event = event->next )
    {        
        if ( event->status == EVENT_ACTIVE )
        {
            if ( event->end_date < current_time )
            {
                stop_event( NULL, event, FALSE );
                event->status = EVENT_EXPIRED;
            }
        }
        else if ( event->status == EVENT_PENDING && event->start_date < current_time )
            startevent( event, event->started_by );
        else
        {
            for ( CUSTOM_EFFECT_DATA* effect = event->first_effect; effect; effect = effect->next )
            {
                for ( EVENT_PLANET* ePlanet = effect->first_planet; ePlanet; ePlanet = ePlanet->next )
                {
                    if ( ePlanet && ePlanet->support_effect && ePlanet->support_effect->popular_opinion_mod == 0 )
                    {
                        PLANET_SUPPORT_DATA* pSupport = get_planet_support_data( ePlanet->planet, effect->clan );
                        for ( PLANET_SUPPORT_EFFECT_DATA* pEffect = pSupport->first_effect; pEffect; pEffect = pEffect->next )
                        {
                            if ( pEffect == ePlanet->support_effect )
                            {
                                UNLINK( pEffect, pSupport->first_effect, pSupport->last_effect, next, prev );
                                FREE_STRUCT_NORET( pEffect, planet_support_effect_fields );
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    return;
}

/*
    Planetary Shield Updates
*/
void update_shields( void )
{
    PLANET_DATA* planet;

    for ( planet = first_planet; planet; planet = planet->next )
    {
        if ( planet == NULL || !planet )
            continue;

        /* Tally Generators */
        // planet->generators = get_generators( planet );
        planet->generators = 0;
        planet->max_shields = ( planet->generators * 10000 );

        if ( !xIS_SET( planet->flags, PLANET_SHIELD ) )
        {
            if ( planet->shields > 0 )
                planet->shields -= URANGE( 10, planet->shields / 2, 1000 );

            planet->shield_cap = URANGE( 0, planet->shield_cap + planet->generators, ( planet->generators * 1000 ) );
        }
        else
        {
            if ( planet->shield_cap > 0 )
            {
                planet->shields = URANGE( 0, planet->shields + ( planet->shield_cap * 5 ), planet->max_shields );
                planet->shield_cap /= 2;
            }
            else
            {
                planet->shields += ( planet->generators * 3 );
            }
        }

        planet->shields = URANGE( 0, planet->shields, planet->max_shields );
    }

    return;
}

/*
    Bacta Tank Updates (Coded by Ghost)
    Now also repairs POISON, BLINDING, and PARALYSIS.
*/
void bacta_update()
{
    CHAR_DATA* ch;
    AFFECT_DATA* paf;
    char buf[MSL];

    for ( ch = last_char; ch; ch = gch_prev )
    {
        if ( ch == first_char && ch->prev )
        {
            bug( "bacta_update: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;
        set_cur_char( ch );

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "bacta_update: ch->prev->next != ch", 0 );
            return;
        }

        if ( !IS_NPC( ch ) )
        {
            if ( xIS_SET( ch->in_room->flags, ROOM_BACTA ) )
            {
                int x = 0;

                if ( ch->hit < ch->max_hit )
                {
                    ch->hit = URANGE( 0, ch->hit + 100, ch->max_hit );
                    ch->move = URANGE( 0, ch->move + 50, ch->max_move );
                    snprintf( buf, MSL, "&GYour wounds heal slightly as the bacta flows over you.\n" );
                    send_to_char( buf, ch );
                }

                for ( paf = ch->first_affect; paf; paf = paf->next )
                    if ( xIS_SET( paf->bitvector, AFF_POISON ) || xIS_SET( paf->bitvector, AFF_BLIND ) || xIS_SET( paf->bitvector, AFF_PARALYSIS ) )
                        paf->duration = URANGE( 1, paf->duration - 100, 10000 );

                for ( x = 0; x <= MAX_MED; x++ )
                {
                    if ( xIS_SET( ch->w_wound, x ) )
                    {
                        if ( number_range( 1, 90 ) < get_curr_lck( ch ) )
                        {
                            ch_println( ch, "The bacta heals your %s wound.", part_name( x ) );
                            xREMOVE_BIT( ch->w_wound, x );
                        }
                    }
                }
            }
        }
    }
}

/*
    OOC Limit-Break Check
*/
void update_ooc()
{
    CHAR_DATA* ch;
    char buf[MSL];

    for ( ch = last_char; ch; ch = gch_prev )
    {
        if ( ch == first_char && ch->prev )
        {
            bug( "update_ooc: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;
        set_cur_char( ch );

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "update_ooc: ch->prev->next != ch", 0 );
            return;
        }

        if ( !IS_NPC( ch ) )
        {
            int ability;

            for ( ability = 0; ability < MAX_ABILITY; ability++ )
                ch->exp_sink[ability] = UMAX( 0, ( ch->exp_sink[ability] - 2 ) );

            if ( ch->pcdata->ooclimit < MUDH_OOC_LIMIT )
            {
                ++ch->pcdata->ooclimit;

                if ( ch->pcdata->ooclimit == MUDH_OOC_LIMIT && ch->pcdata->oocbreak )
                {
                    ch->pcdata->oocbreak = FALSE;
                    snprintf( buf, MSL, "&GOOC Limit-Break reset. You may resume using OOC.\n" );
                    send_to_char( buf, ch );
                }
            }
        }
    }
}

