        */
        if ( !IS_NPC( ch ) && ch->pcdata )
        {
            PACKAGE_DATA* tmp;
            int i;

            /* bug( "[update.c]: Checking %s's packages.", ch->name ); */

            for ( i = 0; i <= 5; i++ )
