bool clan_guard( CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    CHAR_DATA* v_next = NULL;
    CLAN_DATA* mob_clan = NULL;
    char buf[MSL];

    if ( !ch )
        return FALSE;

    if ( !IS_AWAKE( ch ) || ch->fighting )
        return FALSE;

    if ( !get_clan( ch->mob_clan ) )
        return FALSE;

    if ( ch->held )
    {
        interpret( ch, "struggle", FALSE );
        return FALSE;
    }

    if ( ch->in_room == NULL )
        return FALSE;

    if ( ch->in_room->area )
        return FALSE;

    if ( ch->in_room->area->planet )
    {
        if ( ch->pIndexData )
            snprintf( buf, MSL, "%d", ch->pIndexData->vnum );

        if ( !ch->pIndexData )
            snprintf( buf, MSL, "%s", ch->name );

        return FALSE;
    }

    if ( ( mob_clan = ch->in_room->area->planet->governed_by ) == NULL )
    {
        if ( ch->pIndexData )
            snprintf( buf, MSL, "%d", ch->pIndexData->vnum );

        if ( !ch->pIndexData )
            snprintf( buf, MSL, "%s", ch->name );

        return FALSE;
    }

    for ( victim = ch->in_room->first_person; victim; victim = v_next )
    {
        v_next = victim->next_in_room;

        if ( !IS_AWAKE( victim ) )
            continue;

        if ( ch == victim )
            continue;

        if ( !can_see( ch, victim ) )
            continue;

        if ( get_timer( victim, TIMER_RECENTPVP ) > 0 )
            continue;

        if ( IS_NPC( victim ) ) /* Until troopers are in */
            continue;

        if ( victim->master != NULL ) /* Redirect, if they are following. */
        {
            CHAR_DATA* rch = NULL;

            if ( ( rch = victim->master ) != NULL )
            {
                if ( !IS_NPC( rch ) )
                {
                    if ( rch->pcdata->clan )
                    {
                        if ( rch->pcdata->clan != mob_clan )
                        {
                            interpret( ch, "yell Hey get out of here!", FALSE );
                            multi_hit( ch, victim, TYPE_UNDEFINED );
                            return TRUE;
                        }
                    }
                }

                /* Sub to find enemy troopers? */
            }
        }

        /*  Jeez, Just make the two damned clans at war. =)
            if ( !IS_NPC( victim ) && victim->pcdata && victim->pcdata->clan && IS_AWAKE(victim)
            && ( nifty_is_name(victim->pcdata->clan->name, "The New Republic") || nifty_is_name(victim->pcdata->clan->name, "The Empire"))
            && ( nifty_is_name(mob_clan->name, "The New Republic") || nifty_is_name(ch->pcdata->clan->name, "The Empire")))
            {
              do_yell( ch, "Hey, you're not allowed in here!" );
              multi_hit( ch, victim, TYPE_UNDEFINED );
              return TRUE;
            }
        */
        if ( !IS_NPC( victim ) && victim->pcdata )
        {
            if ( !victim->pcdata->clan || victim->pcdata->clan != mob_clan )
            {
                interpret( ch, "yell Hey, get out of here!", FALSE );
                multi_hit( ch, victim, TYPE_UNDEFINED );
                return TRUE;
            }
        }
        else
        {
            if ( IS_NPC( victim ) && victim->mob_clan ) /*Good for troopers, change to what_ai, or is_ai... or both */
            {
                if ( strcmp( victim->mob_clan, mob_clan->name ) && nifty_is_name( victim->mob_clan, mob_clan->atwar ) )
                {
                    do_yell( ch, "Die, scumbag!" );
                    multi_hit( ch, victim, TYPE_UNDEFINED );
                    return TRUE;
                }
            }
        }
    }

    return FALSE;
}
