/* showing pirates/war notifications */
/*  Redoing news priortizing and removing some of the news messages.

    PRIORITY:
          CUSTOM GALACTIC EVENTS
          HARD-CODED PLANETARY EVENTS
          BOMBARD
          BLOCKADE
          PIRATE
          CRIME
          EMBARGO
          HOLIDAY
          MILITARY
          WAR
*/
void update_news()
{
    bool has_run = false;
    int i = 0, j = 0;

    if ( last_event_broadcast <= current_time - 5 * 60 )
    {
        // Iterate through the events and figure out how many events have eligible broadcasts to run.
        for ( CUSTOM_EVENT_DATA* event = first_event; event; event = event->next )
        {
            if ( event->status == EVENT_ACTIVE && event->broadcasted_at <= current_time - event->broadcast_frequency * 60 )
            {
                for ( CUSTOM_BROADCAST_DATA* broadcast = event->first_broadcast; broadcast; broadcast = broadcast->next )
                {
                    if ( broadcast->broadcasted_at <= ( current_time - broadcast->frequency * 60 ) )
                    {
                        i++;
                        break;
                    }
                }
            }
        }

        // If we've identified at least one event with an eligible broadcast, select the one to run at random.
        if ( i >= 1 )
            j = number_range( 1, i );

        i = 0; // Reset the counter for the next iteration through the events
        for ( CUSTOM_EVENT_DATA* event = first_event; event; event = event->next )
        {
            // Skip events that aren't presently running
            if ( event->status != EVENT_ACTIVE )
                continue;

            // Just skip ahead if we already ran a broadcast this cycle.
            if (has_run)
                break;

            // If we've already determined that there are no eligible event broadcasts this cycle, skip ahead.
            if (j == 0)
                break;

            // If the event has broadcasted within the event broadcast frequency window (default 20 minutes), skip it.
            if ( event->broadcasted_at > current_time - event->broadcast_frequency * 60 )
                continue;

            for ( CUSTOM_BROADCAST_DATA* broadcast = event->first_broadcast; broadcast; broadcast = broadcast->next )
            {
                // Skip broadcasts we've already made within their specific frequency window (default 60 minutes)
                if ( broadcast->broadcasted_at > ( current_time - ( broadcast->frequency + broadcast->decay_now ) * 60 ) )
                    continue;

                // If we've made it this far, increment the counter and, if we're not on the right event, move on to the next one.
                i++;
                if ( i < j )
                    break;

                // Make sure this broadcast is next up to run -- if it's run more recently than any of the others in the event, 
                // and the other broadcasts are also within their broadcast window, skip this one.
                bool next_in_line = true;
                for ( CUSTOM_BROADCAST_DATA* test_broadcast = event->first_broadcast; test_broadcast; test_broadcast = test_broadcast->next )
                {
                    if ( broadcast != test_broadcast && broadcast->broadcasted_at > test_broadcast->broadcasted_at
                    && test_broadcast->broadcasted_at <= current_time - ( test_broadcast->frequency + test_broadcast->decay_now ) * 60 )
                    {
                        next_in_line = false;
                        break;
                    }
                }
                if (!next_in_line)
                    continue;

                if ( !NULLSTR( broadcast->message ) )
                {
                    event->broadcasted_at = current_time;
                    broadcast->broadcasted_at = current_time;
                    broadcast->decay_now += broadcast->decay;
                    // Using this global variable to keep track of when broadcasts run to avoid concurrent broadcasts (aka spamming the players)
                    last_event_broadcast = current_time;
                    has_run = true;
                    send_broadcast( broadcast->message, "CUSTOM EVENT" );
                    save_events( );
                    return;
                }
            }
        }
    }

    // If we're already run a broadcast this cycle for a galactic event, or if we've run any broadcast in the last 5 minutes, don't try to run
    // another for planetary events in the same news cycle.
    if ( !has_run && last_event_broadcast <= current_time - 5 * 60 )
    {
        for ( PLANET_DATA* planet = first_planet; planet; planet = planet->next )
        {
            if ( xIS_SET( planet->flags, PLANET_STAR ) || xIS_SET( planet->flags, PLANET_MOON ) )
                continue;

            if ( xIS_SET( planet->flags, PLANET_NOSHOW ) )
                continue;

            for ( PLANET_EVENT_DATA* event = planet->first_event; event; event = event->next )
            {
                // Skip events we've already broadcasted and events which started too recently.
                if ( event->broadcasted_at > 0 || event->started_at > current_time - 15 * 60 )
                    continue;

                char* broadcast_text = planet_event_start_news( planet, event );

                if ( !NULLSTR( broadcast_text ) )
                {
                    event->broadcasted_at = current_time;
                    last_event_broadcast = current_time;
                    has_run = true;
                    send_broadcast( broadcast_text, "GNI Report" );
                    save_planet( planet, true );
                }
            }
        }
    }

    /* Finally, if no other broadcasts have run in this cycle and no general broadcasts have run in the last five minutes,
       run one of the general broadcasts if called for. */
    if ( !has_run && last_general_broadcast <= current_time - 5 * 60 )
    {
        PLANET_DATA* cplanet = NULL, *pplanet = NULL, *eplanet = NULL, *cri = NULL, *bplanet = NULL, *wplanet = NULL, *xplanet = NULL;
        char buf[SUPER_MSL];
        int tminus12h = current_time - 12 * 3600;
        int tminus10m = current_time - 10 * 60;

        /* Run through the planets, find the ones which have anything important, then execute in priority. */
        for ( PLANET_DATA* planet = first_planet ; planet ; planet = planet->next )
        {
            if ( xIS_SET( planet->flags, PLANET_STAR ) || xIS_SET( planet->flags, PLANET_MOON ) )
                continue;

            if ( xIS_SET( planet->flags, PLANET_NOSHOW ) )
                continue;

            if ( xIS_SET( planet->flags, PLANET_PIRATED ) )
            {
                if ( pplanet == NULL || number_range( 1, 2 ) == 2  )
                {
                    pplanet = planet;
                }
            }

            if ( xIS_SET( planet->flags, PLANET_EMBARGO ) )
                if ( eplanet == NULL || number_range( 1, 2 ) == 2 )
                    eplanet = planet;

            if ( planet->crime > 75 && planet->last_broadcast_crime < tminus12h )
            {
                if ( cplanet == NULL || number_range( 1, 2 ) == 2  )
                {
                    cplanet = planet;
                }
            }

            if ( !cri || planet->crime > cri->crime )
            {
                if ( !xIS_SET( planet->flags, PLANET_WARTORN ) )
                {
                    cri = planet;
                }
                else if ( xIS_SET( planet->flags, PLANET_WARTORN ) && number_range( 1, 10 ) == 1 )
                {
                    cri = planet;
                }
            }

            if ( planet->blockaded_by &&
                    planet->blockade_start_time < tminus10m &&
                    ( xIS_SET( planet->flags, PLANET_BLOCKADE ) || xIS_SET( planet->flags, PLANET_UNBLOCKADED ) ) &&
                    ( !bplanet || number_range( 1, 2 ) == 1 ) )
                bplanet = planet;

            if ( xIS_SET( planet->flags, PLANET_STAR ) || xIS_SET( planet->flags, PLANET_NOSHOW ) )
                continue;

            if ( planet->governed_by && planet->governed_by->atwar && planet->governed_by->atwar[0] != '\0' && ( !wplanet || number_range( 1, 3 ) == 2 ) )
                wplanet = planet;

            if ( xIS_SET( planet->flags, PLANET_BOMBARDED ) &&
                    planet->bombard_start_time < tminus10m )
                if ( xplanet == NULL || number_range( 1, 2 ) == 2 )
                    xplanet = planet;
        }

        if ( xplanet )
        {
            bool war = FALSE;
            bool sameclan = FALSE;

            if ( xplanet->bombarded_by != NULL ) // Is there a clan responsible for the bombardment?
            {
                if ( ( xplanet->governed_by && nifty_is_name( xplanet->bombarded_by->name, xplanet->governed_by->atwar ) ) || ( xplanet->governed_by && nifty_is_name( xplanet->governed_by->name, xplanet->bombarded_by->atwar ) ) )
                    war = TRUE;

                if ( xplanet->governed_by && nifty_is_name( xplanet->bombarded_by->name, xplanet->governed_by->name ) )
                    sameclan = TRUE;

                if ( sameclan )
                    snprintf( buf, SUPER_MSL, "&R[&O*&R] Casualty Report! &R[&O*&R] &WDramatic footage from the surface of %s in the %s shows massive explosions rippling across the surface of the planet. Warships from %s are positioned in orbit around the planet, seemingly unleashing a devastating attack on their own territory. Civilians are advised to steer clear of this sector until further notice!", xplanet->name, xplanet->starsystem->name, xplanet->bombarded_by->name );
                else
                    snprintf( buf, SUPER_MSL, "&R[&O*&R] Casualty Report! &R[&O*&R] &WDramatic footage from the surface of %s in the %s shows massive explosions rippling across the surface of the planet. Warships from %s are in orbit around the planet, and are unleashing a deadly assault on the world below. Civilians are advised to steer clear of this sector until further notice! %s", xplanet->name, xplanet->starsystem->name, xplanet->bombarded_by->name, war ? "The two groups continue to fight their war, this being just the latest in the ongoing conflict." : "The attacks have caught some people off-guard, as there have been no official hostilities announced between the two groups. GNI will continue to bring you the latest on this attack as the situation develops." );
            }
            else
                snprintf( buf, SUPER_MSL, "&R[&O*&R] Casualty Report! &R[&O*&R] &WDramatic footage from the surface of %s in the %s shows massive explosions rippling across the surface of the planet. Unknown vessels are positioned in orbit around the planet, seemingly unleashing a devastating attack on the planet. Civilians are advised to steer clear of this sector until further notice!", xplanet->name, xplanet->starsystem->name );

            xREMOVE_BIT( xplanet->flags, PLANET_BOMBARDED );
            xplanet->bombarded_by = NULL;
            xplanet->bombard_start_time = 0;
            save_planet( xplanet, true );
        }
        else if ( bplanet && bplanet->governed_by ) //Added null crash prevention if somehow the mud gets stuck with an ungoverned planet as blockaded, whereas there is no governing clan to check details about further on.
        {
            bool war = FALSE;
            bool sameclan = FALSE;
            char wtxt[MSL];

            if ( ( bplanet->governed_by && nifty_is_name( bplanet->blockaded_by->name, bplanet->governed_by->atwar ) ) || ( bplanet->governed_by && nifty_is_name( bplanet->governed_by->name, bplanet->blockaded_by->atwar ) ) )
                war = TRUE;

            if ( bplanet->governed_by && nifty_is_name( bplanet->blockaded_by->name, bplanet->governed_by->name ) )
                sameclan = TRUE;

            if ( bplanet->governed_by )
                snprintf( wtxt, MSL, ", held by %s,", bplanet->governed_by->name );

            if ( xIS_SET( bplanet->flags, PLANET_UNBLOCKADED ) )
            {
                xREMOVE_BIT( bplanet->flags, PLANET_UNBLOCKADED );
                bplanet->blockade_start_time = 0;
                SET_STRING( bplanet->blockade_news_clan_name, NULL );

                if ( sameclan )
                    snprintf( buf, SUPER_MSL, "&R[&O*&R] Blockade Report &R[&O*&R] &W%s and the sector of %s are no longer under blockade by %s. One can only imagine the relief of the citizens there that the whole thing is over.", bplanet->name, bplanet->starsystem->name, bplanet->blockaded_by->name );
                else
                    snprintf( buf, SUPER_MSL, "&R[&O*&R] Blockade Report &R[&O*&R] &W%s and the sector of %s%s are no longer under blockade by %s. One can only imagine the relief of the citizens there that the whole thing is over. %s", bplanet->name, bplanet->starsystem->name, bplanet->governed_by ? wtxt : "", bplanet->blockaded_by->name, war ? "Despite the lift of the blockade, the war has not been ended." : "No further hostilities seem apparent for the two groups, perhaps this is a change for the better." );

                bplanet->blockaded_by = NULL;
                save_planet( bplanet, true );
            }
            else if ( !sameclan )
            {
                snprintf( buf, SUPER_MSL, "&R[&O*&R] Blockade Report &R[&O*&R] &W%s and the sector of %s%s are under blockade by %s. All ships seem to be getting stopped, and by the look of things it's either by choice or by force. %s. Listeners are advised to steer clear of this sector until further notice!", bplanet->name, bplanet->starsystem->name, bplanet->governed_by ? wtxt : "",  bplanet->blockaded_by->name, war ? "The two groups continue to fight their war, this being only a short segment in the story of the conflict" : "Though the two groups are not at war, GNI will be attempting to bring you the story on the reasons for the blockade" );
                SET_STRING( bplanet->blockade_news_clan_name, bplanet->blockaded_by->name );
            }
            else
            {
                snprintf( buf, SUPER_MSL, "&R[&O*&R] Blockade Report &R[&O*&R] &W%s and the sector of %s%s are under blockade by %s. All ships seem to be getting stopped, and by the look of things it's either by choice or by force. Though we don't yet know why %s is blockading a world they control, GNI will be attempting to bring you the story on the reasons for the blockade. Listeners are advised to steer clear of this sector until further notice!", bplanet->name, bplanet->starsystem->name, bplanet->governed_by ? wtxt : "", bplanet->blockaded_by->name, bplanet->blockaded_by->name );
                SET_STRING( bplanet->blockade_news_clan_name, bplanet->blockaded_by->name );
            }
        }
        else if ( pplanet && number_range( 1, 10 ) > 8 )
        {
            snprintf( buf, SUPER_MSL, "&W[&O*&W] &rPirate Report &W[&O*&W] %s is under rule by orbital pirates. They are sending down raids, pillaging and inciting crime as they go. The %d citizens left are not going to survive this sort of treatment for very long. Will %s step in to help? This remains to be seen.", pplanet->name, pplanet->population, !pplanet->governed_by ? "no one" : ( pplanet->leader[0] == '\0' ? pplanet->leader : pplanet->governed_by->name ) );
        }
        else if ( cplanet && cplanet->governed_by && ( ( !wplanet && number_range( 1, 2 ) == 1 ) || number_range( 1, 4 ) == 1 ) )
        {
            snprintf( buf, SUPER_MSL, "&W[&O*&W] &RCrime Report &W[&O*&W] &wCrime is at a rising rate, as citizens of %s are learning of in the recent days. Criminals, outlaws and thieves are threatening the safety of the citizens there. %s %s %s%s. We hope %s, appointed leader of its citizenry, will step in soon to bring an end to this. I wonder what %s think of all this, and the impact on their %d citizens on this planet.", cplanet->name, cplanet->name, cplanet != cri ? "has less crime than" : "is the worst", cplanet != cri ? cri->name :  "", cplanet != cri ? " though, which is the highest rated in the galaxy for it's crime presence" : "place for crime in the galaxy", cplanet->leader[0] != '\0' ? cplanet->leader : cplanet->governed_by->name, cplanet->governed_by->name, cplanet->population );
            cplanet->last_broadcast_crime = current_time;
        }
        else if ( eplanet && eplanet->governed_by && number_range( 1, 10 ) == 1 ) //More null protection if planet isn't owned.
        {
            snprintf( buf, SUPER_MSL, "&W[&O*&W] &GTrade News &W[&O*&W] &wA recent embargo levied by %s leaves %s's %d citizens blocked from trading with anyone. Both the buying, and the selling of the cargo coming to, or leaving from %s will be out of luck. We can only speculate as to the reason %s decided to make this move.", eplanet->leader[0] != '\0' ? eplanet->leader : eplanet->governed_by->name, eplanet->name, eplanet->population, eplanet->name, eplanet->leader[0] != '\0' ? eplanet->leader : eplanet->governed_by->name );
        }
        else if ( wplanet && number_range( 1, 7 ) == 7 && last_general_broadcast <= current_time - 15 * 60 )
        {
            CLAN_DATA* clan = NULL;

            for ( clan = first_clan; clan; clan = clan->next )
                if ( nifty_is_name( clan->name, wplanet->governed_by->atwar ) )
                    break;

            if ( !clan )
            {
                bug( "Update_news - Clan %s has unmatched atwar. No clans listed fit the string.", wplanet->governed_by ? wplanet->governed_by->name : "Null governed_by" );
                return;
            }

            snprintf( buf, SUPER_MSL, "&W[&O*&W] &cPolitical Update&W [&O*&W] &w%s and %s are at war. ", wplanet->governed_by->name, clan->name );
            int broadcast_selector = number_range( 1, 7 );
            if ( broadcast_selector == 1 )
            {
                int wpcount = 0, cpcount = 0;
                for ( PLANET_DATA* planet = first_planet ; planet ; planet = planet->next )
                {
                    if ( planet->governed_by == clan )
                        cpcount++;

                    if ( planet->governed_by == wplanet->governed_by )
                        wpcount++;
                }
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Times of war can be hard on everyone. Despite that, we are bringing you the news on how the conflict is shaping up. %s's %d sectors versus %s's %d sectors puts %s in the more powerful position. GNI will continue to bring further developments in the fight as they happen.", wplanet->governed_by->name, wpcount, clan->name, cpcount, cpcount > wpcount ? clan->name : wpcount > cpcount ? wplanet->governed_by->name : "neither side" );
            }
            else if ( broadcast_selector == 2 )
            {
                double wpsupport, cpsupport;
                i = 0;
                for ( PLANET_DATA* planet = first_planet ; planet ; planet = planet->next )
                {
                    i++;
                    cpsupport += get_planet_pop_opinion( planet, clan );
                    wpsupport += get_planet_pop_opinion( planet, wplanet->governed_by );
                }
                cpsupport /= i;
                wpsupport /= i;
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Our wartime correspondents are working hard to bring you the facts on the ground. Between %s and %s, public opinion throughout the galaxy %sfavors %s. GNI will continue to bring further developments in the fight as they happen. Stay safe and stay tuned.", wplanet->governed_by->name, clan->name, fabs( cpsupport - wpsupport ) > 30 ? "strongly " : fabs( cpsupport - wpsupport ) > 15 ? "somewhat " : fabs( cpsupport - wpsupport ) > 1 ? "slightly " : "", cpsupport - wpsupport > 1 ? clan->name : wpsupport - cpsupport > 1 ? wplanet->governed_by->name : "neither side" );
            }
            else if ( broadcast_selector == 3 )
            {
                double wmrating = 0, cmrating = 0;
                i = 0;
                for ( PLANET_DATA* planet = first_planet ; planet ; planet = planet->next )
                {
                    i++;
                    PLANET_SUPPORT_DATA* csupport = get_planet_support_data( planet, clan );
                    if (csupport)
                        cmrating += csupport->military_presence;
                    PLANET_SUPPORT_DATA* wsupport = get_planet_support_data( planet, wplanet->governed_by );
                    if (wsupport)
                        wmrating += wsupport->military_presence;
                }
                cmrating /= i;
                wmrating /= i;
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Our wartime analysts are on the ground, in the action, to bring you the latest. Between %s and %s, %s has %s military presence throughout the galaxy. GNI will keep in the thick of it to bring you the latest news. Stay tuned.", wplanet->governed_by->name, clan->name, cmrating - wmrating > 1 ? clan->name : wmrating - cmrating > 1 ? wplanet->governed_by->name : "neither side", fabs( cmrating - wmrating ) > 50 ? "a much larger" : fabs ( cmrating - wmrating ) > 30 ? "a substantially larger" : fabs ( cmrating - wmrating ) > 15 ? "a larger" : fabs ( cmrating - wmrating ) > 1 ? "a slightly larger" : "a larger" );
            }
            else if ( broadcast_selector == 4 )
            {
                // Don't spill the beans on credit counts if one of the clans is hidden/secret/whathaveyou
                if ( xIS_SET( clan->flags, CLAN_HIDESTATS ) || xIS_SET( wplanet->governed_by->flags, CLAN_HIDESTATS ) )
                    return;

                int cfunds = clan->funds / 1000000;
                int wfunds = wplanet->governed_by->funds / 1000000;
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Our wartime pundits are crunching the numbers to help you make sense of it all. Between the two factions, %s has a %seconomic advantage, with %d million credits in reserve for %s versus %d million for %s. GNI will continue to monitor the situation as it develops. Until then, stay safe and stay tuned.", 
                cfunds - wfunds > 1 ? clan->name : wfunds - cfunds > 1 ? wplanet->governed_by->name : "neither side", abs( cfunds - wfunds ) > 100 ? "strong " : abs( cfunds - wfunds ) > 50 ? "modest " : abs( cfunds - wfunds ) > 1 ? "slight " : "real ", cfunds > wfunds ? cfunds : wfunds, cfunds > wfunds ? clan->name : wplanet->governed_by->name, cfunds > wfunds ? wfunds : cfunds, cfunds > wfunds ? wplanet->governed_by->name : clan->name );
            }
            else if ( broadcast_selector == 5 )
            {
                int cmembers = clan_count_active_members( clan );
                int wmembers = clan_count_active_members( wplanet->governed_by );
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "We're cutting through the wartime propaganda to bring you the facts. Between the two factions, %s has %spersonnel advantage that could give them an edge. GNI will continue to keep tabs on the war and bring you the latest updates as they arrive. Stay tuned.", cmembers > wmembers ? clan->name : wmembers > cmembers ? wplanet->governed_by->name : "neither side", abs( wmembers - cmembers ) > 30 ? "an extraordinary " : abs( wmembers - cmembers ) > 20 ? "a significant " : abs( wmembers - cmembers ) > 10 ? "a substantial " : abs( wmembers - cmembers ) > 1 ? "a slight " : "a " );
            }
            else if ( broadcast_selector == 6 )
            {
                double ccrating = 0, wcrating = 0;
                i = 0;
                j = 0;
                for ( PLANET_DATA* planet = first_planet; planet; planet = planet->next )
                {
                    if ( planet->governed_by == clan )
                    {
                        ccrating += planet->crime;
                        i++;
                    }   
                    else if ( planet->governed_by == wplanet->governed_by )
                    {
                        wcrating += planet->crime;
                        j++;
                    }
                }
                // This broadcast is meaningless if either clan doesn't control any planets, so skip it.
                if ( i == 0 || j == 0 || wcrating < 0 || ccrating < 0 )
                {
                    return;
                }

                ccrating /= i;
                wcrating /= j;
                snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Times of war can be hard on everyone, but especially the citizens of worlds in the crossfire. " );
                if ( wcrating > 50 && ccrating > 50 )                
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Because of the conflict -- or perhaps despite it -- both %s and %s face serious unrest on their worlds, with crime rates at all-time highs. GNI will continue to bring further developments in the fight as they happen.", wplanet->governed_by->name, clan->name );
                else if ( wcrating > 50 )
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Because of the conflict -- or perhaps despite it -- %s faces serious unrest on their worlds, with crime rates at all-time highs. GNI will continue to bring further developments in the fight as they happen.", wplanet->governed_by->name );
                else if ( ccrating > 50 )
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Because of the conflict -- or perhaps despite it -- %s faces serious unrest on their worlds, with crime rates at all-time highs. GNI will continue to bring further developments in the fight as they happen.", clan->name );
                else
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Because of the conflict -- or perhaps despite it -- %s is left to deal with %s crime rate on their worlds as compared to the worlds %s governs. GNI will continue to bring further developments in the fight as they happen.", wcrating > ccrating ? wplanet->governed_by->name : clan->name, fabs( wcrating - ccrating ) > 40 ? "a dramatically higher" : fabs( wcrating - ccrating ) > 20 ? "a substantially higher" : fabs( wcrating - ccrating ) > 10 ? "a somewhat higher" : fabs( wcrating - ccrating ) > 5 ? "a slightly higher" : "a remarkably similar", wcrating > ccrating ? clan->name : wplanet->governed_by->name );
            }
            else if ( broadcast_selector == 7 )
            {
                if ( ( wplanet->governed_by->clan_type == CLAN_GOVERNMENT || clan->clan_type == CLAN_GOVERNMENT ) &&
                ( wplanet->governed_by->clan_type == CLAN_CRIME || clan->clan_type == CLAN_CRIME ) )
                {
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Fighting crime is never easy, but %s is giving it their best shot as they make war on %s, a crime syndicate known to operate both in the shadows and in open daylight. Will law and order prevail? GNI will continue to bring you the latest developments. Stay tuned.", wplanet->governed_by->clan_type == CLAN_GOVERNMENT ? wplanet->governed_by->name : clan->name, wplanet->governed_by->clan_type == CLAN_CRIME ? wplanet->governed_by->name : clan->name );
                }
                else if ( ( wplanet->governed_by->clan_type == CLAN_GOVERNMENT || clan->clan_type == CLAN_GOVERNMENT ) &&
                ( wplanet->governed_by->clan_type == CLAN_ENGINEERING || clan->clan_type == CLAN_ENGINEERING ) )
                {
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "Though we don't yet know the cause of the conflict, it's rare to see a government and an engineering firm at war with one another. Will %s survive to do business another day? How will this impact the galactic economy? Stay tuned for updates.", wplanet->governed_by->clan_type == CLAN_ENGINEERING ? wplanet->governed_by->name : clan->name );
                }
                else if ( ( wplanet->governed_by->clan_type == CLAN_GOVERNMENT || clan->clan_type == CLAN_GOVERNMENT ) &&
                ( wplanet->governed_by->clan_type == CLAN_RELIGION || clan->clan_type == CLAN_RELIGION ) )
                {
                    snprintf( buf + strlen(buf), SUPER_MSL - strlen(buf), "While we don't know much about the tenets of %s and its devotees, it's odd to see a government and a religion take up arms against one another. Will %s endure? How will this affect religious observance across the galaxy? We'll bring you updates as they emerge. Stay tuned.", wplanet->governed_by->clan_type == CLAN_RELIGION ? wplanet->governed_by->name : clan->name, wplanet->governed_by->clan_type == CLAN_RELIGION ? wplanet->governed_by->name : clan->name );
                }
                else
                {
                    return;
                }
            }
        }
        else
        {
            return;
        }

        send_broadcast( buf, "GNI Report" );
        last_general_broadcast = current_time;
        has_run = true;
        return;
    }

    return;
}

void update_planets( void )
{
    lua_trigger_on_generic( LUA_TRIGGER_BEFORE_UPDATE_PLANETS );
    for ( PLANET_DATA* planet = first_planet; planet; planet = planet->next )
    {
        update_planet_support( planet );
        firehose_write_planet( planet );
    }
    lua_trigger_on_generic( LUA_TRIGGER_AFTER_UPDATE_PLANETS );
}

void save_all_planets( void )
{
    PLANET_DATA* planet = NULL;

    for ( planet = first_planet; planet; planet = planet->next )
    {
        save_planet( planet, true );
    }
    return;
}

void update_cpy( void )
{
    if ( sysdata.cpy == 0 )
        return;

    if ( !sysdata.cpy_char && !sysdata.autocopy )
        return;

    if ( --sysdata.cpy == 0 )
    {
        if ( sysdata.cpy_char )
        {
            do_copyover( sysdata.cpy_char, "bypass" );
        }
        else if ( sysdata.autocopy == AUTOCOPY_NORMAL )
        {
            char buf[1024];
            snprintf( buf, 1024, "\n *** [ALERT] COPYOVER NOW, PLEASE STAND BY...\n" );
            copyover( buf, false, false, true );
        }
        else if ( sysdata.autocopy == AUTOCOPY_EMERGENCY )
        {
            char buf[1024];
            snprintf( buf, 1024, "\n *** [ALERT] COPYOVER NOW, PLEASE STAND BY...\n" );
            copyover( buf, true, false, true );
        }
    }
}

bool msdp_update_one_player( DESCRIPTOR_DATA* d )
{
    if ( !validate_desc( d ) )
        return false;

    CHAR_DATA* ch = d->character;

    if ( !ch || d->connected != CON_PLAYING || IS_NPC( ch ) )
        return false;

    char buf[MSL];
    CHAR_DATA* pOpponent = ch->fighting ? ( ch->fighting->who ? ch->fighting->who : NULL ) : NULL;
    ROOM_INDEX_DATA* pRoom = ch->in_room ? ch->in_room : NULL;
    AFFECT_DATA* paf = NULL;
    SKILL_DATA* skill = NULL;
    SHIP_DATA* ship = NULL;
    MSDPSetString( d, eMSDP_CHARACTER_NAME, ch->name );
    MSDPSetNumber( d, eMSDP_ALIGNMENT, ch->alignment );
    MSDPSetNumber( d, eMSDP_HEALTH, ch->hit );
    MSDPSetNumber( d, eMSDP_HEALTH_MAX, ch->max_hit );
    MSDPSetNumber( d, eMSDP_TOPLEVEL, ch->top_level );
    MSDPSetNumber( d, eMSDP_LEVEL_COMBAT, ch->skill_level[COMBAT_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_PILOTING, ch->skill_level[PILOTING_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_ENGINEERING, ch->skill_level[ENGINEERING_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_HUNTING, ch->skill_level[HUNTING_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_SMUGGLING, ch->skill_level[SMUGGLING_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_LEADERSHIP, ch->skill_level[LEADERSHIP_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_ESPIONAGE, ch->skill_level[ESPIONAGE_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_SLICER, ch->skill_level[SLICER_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_MEDIC, ch->skill_level[MEDIC_ABILITY] );
    MSDPSetNumber( d, eMSDP_LEVEL_SCIENCE, ch->skill_level[SCIENCE_ABILITY] );
    MSDPSetString( d, eMSDP_RACE, capitalize( get_race( ch ) ) );
    MSDPSetString( d, eMSDP_CLASS, capitalize( flag_value_name( ability_name, ch->main_ability ) ) );
    MSDPSetNumber( d, eMSDP_WIMPY, ch->wimpy );
    MSDPSetNumber( d, eMSDP_MOVEMENT, ch->move );
    MSDPSetNumber( d, eMSDP_MOVEMENT_MAX, ch->max_move );
    MSDPSetNumber( d, eMSDP_HITROLL, GET_HITROLL( ch ) );
    MSDPSetNumber( d, eMSDP_DAMROLL, GET_DAMROLL( ch ) );
    MSDPSetNumber( d, eMSDP_AC, GET_AC( ch ) );
    MSDPSetNumber( d, eMSDP_STR, get_curr_str( ch ) );
    MSDPSetNumber( d, eMSDP_INT, get_curr_int( ch ) );
    MSDPSetNumber( d, eMSDP_WIS, get_curr_wis( ch ) );
    MSDPSetNumber( d, eMSDP_DEX, get_curr_dex( ch ) );
    MSDPSetNumber( d, eMSDP_CON, get_curr_con( ch ) );
    MSDPSetNumber( d, eMSDP_CHA, get_curr_cha( ch ) );
    MSDPSetNumber( d, eMSDP_STR_PERM, ch->perm_str );
    MSDPSetNumber( d, eMSDP_INT_PERM, ch->perm_int );
    MSDPSetNumber( d, eMSDP_WIS_PERM, ch->perm_wis );
    MSDPSetNumber( d, eMSDP_DEX_PERM, ch->perm_dex );
    MSDPSetNumber( d, eMSDP_CON_PERM, ch->perm_con );
    MSDPSetNumber( d, eMSDP_CHA_PERM, ch->perm_cha );
    MSDPSetNumber( d, eMSDP_BOTTING_COOLDOWN, ch->pcdata->cooldown );
    MSDPSetNumber( d, eMSDP_BOTTING_TIME, ch->pcdata->botting );

    if ( ch->desc )
    {
        char newstr[MSL];
        int i, j;
        int itag = 0;

        for ( i = j = 0; ch->desc->inbuf[i] != '\0'; i++ )
        {
            if ( ch->desc->inbuf[i] == '\n' )
            {
                newstr[j++] = ',';
            }
            else if ( ch->desc->inbuf[i] == ',' )
            {
                itag++;
                newstr[j++] = ch->desc->inbuf[i];
            }
            else if ( ch->desc->inbuf[i] != '\r' )
            {
                newstr[j++] = ch->desc->inbuf[i];
            }
        }

        newstr[j] = '\0';
        char goodstr[MSL];
        strlcpy( goodstr, newstr, MSL );
        MSDPSetString( d, eMSDP_COMMAND_STACK, goodstr );
    }

    if ( ch->pcdata->clan )
        MSDPSetString( d, eMSDP_CLAN, ch->pcdata->clan->name );

    UpdateGMCPString( d, GMCP_NAME, ch->name );
    UpdateGMCPString( d, GMCP_RACE, capitalize( get_race( ch ) ) );
    UpdateGMCPString( d, GMCP_MAIN_CLASS, capitalize( flag_value_name( ability_name, ch->main_ability ) ) );
    UpdateGMCPNumber( d, GMCP_ALIGNMENT, ch->alignment );
    UpdateGMCPNumber( d, GMCP_TOPLEVEL, ch->top_level );
    UpdateGMCPNumber( d, GMCP_LEVEL_COMBAT, ch->skill_level[COMBAT_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_PILOTING, ch->skill_level[PILOTING_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_ENGINEERING, ch->skill_level[ENGINEERING_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_HUNTING, ch->skill_level[HUNTING_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_SMUGGLING, ch->skill_level[SMUGGLING_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_LEADERSHIP, ch->skill_level[LEADERSHIP_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_ESPIONAGE, ch->skill_level[ESPIONAGE_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_SLICER, ch->skill_level[SLICER_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_MEDIC, ch->skill_level[MEDIC_ABILITY] );
    UpdateGMCPNumber( d, GMCP_LEVEL_SCIENCE, ch->skill_level[SCIENCE_ABILITY] );
    UpdateGMCPString( d, GMCP_CLAN, ch->pcdata->clan ? ch->pcdata->clan->name : NULL );
    UpdateGMCPNumber( d, GMCP_HP, ch->hit );
    UpdateGMCPNumber( d, GMCP_MOVE, ch->move );
    UpdateGMCPNumber( d, GMCP_MAX_HP, ch->max_hit );
    UpdateGMCPNumber( d, GMCP_MAX_MOVE, ch->max_move );
    UpdateGMCPNumber( d, GMCP_STR, get_curr_str( ch ) );
    UpdateGMCPNumber( d, GMCP_INT, get_curr_int( ch ) );
    UpdateGMCPNumber( d, GMCP_WIS, get_curr_wis( ch ) );
    UpdateGMCPNumber( d, GMCP_DEX, get_curr_dex( ch ) );
    UpdateGMCPNumber( d, GMCP_CON, get_curr_con( ch ) );
    UpdateGMCPNumber( d, GMCP_CHA, get_curr_cha( ch ) );
    UpdateGMCPNumber( d, GMCP_HITROLL, GET_HITROLL( ch ) );
    UpdateGMCPNumber( d, GMCP_DAMROLL, GET_DAMROLL( ch ) );
    UpdateGMCPNumber( d, GMCP_ARMOR, GET_AC( ch ) );
    UpdateGMCPNumber( d, GMCP_STR_PERM, ch->perm_str );
    UpdateGMCPNumber( d, GMCP_INT_PERM, ch->perm_int );
    UpdateGMCPNumber( d, GMCP_WIS_PERM, ch->perm_wis );
    UpdateGMCPNumber( d, GMCP_DEX_PERM, ch->perm_dex );
    UpdateGMCPNumber( d, GMCP_CON_PERM, ch->perm_con );
    UpdateGMCPNumber( d, GMCP_CHA_PERM, ch->perm_cha );
    UpdateGMCPNumber( d, GMCP_WIMPY, ch->wimpy );
    UpdateGMCPBoolean( d, GMCP_BOTTING, ch->pcdata->botting > 0 && ch->pcdata->cooldown != -1 );
    UpdateGMCPNumber( d, GMCP_BOTTING_TIME, ch->pcdata->botting );
    UpdateGMCPNumber( d, GMCP_BOTTING_COOLDOWN, ch->pcdata->cooldown );

    if ( get_trust( ch ) >= LEVEL_IMMORTAL )
        UpdateGMCPNumber( d, GMCP_IMM_LEVEL, get_trust( ch ) );
    else
        UpdateGMCPNull( d, GMCP_IMM_LEVEL );

    if ( ch->skill_level[FORCE_ABILITY] > 1 || IS_IMMORTAL( ch ) )
    {
        MSDPSetNumber( d, eMSDP_LEVEL_FORCE, ch->skill_level[FORCE_ABILITY] );
        MSDPSetNumber( d, eMSDP_MANA, ch->mana );
        MSDPSetNumber( d, eMSDP_MANA_MAX, ch->max_mana );
        UpdateGMCPNumber( d, GMCP_LEVEL_FORCE, ch->skill_level[FORCE_ABILITY] );
        UpdateGMCPNumber( d, GMCP_MANA, ch->mana );
        UpdateGMCPNumber( d, GMCP_MAX_MANA, ch->max_mana );
    }
    else
    {
        MSDPSetNumber( d, eMSDP_LEVEL_FORCE, 0 );
        MSDPSetNumber( d, eMSDP_MANA, 0 );
        MSDPSetNumber( d, eMSDP_MANA_MAX, 0 );
        UpdateGMCPNumber( d, GMCP_LEVEL_FORCE, 0 );
        UpdateGMCPNumber( d, GMCP_MANA, 0 );
        UpdateGMCPNumber( d, GMCP_MAX_MANA, 0 );
    }

    if ( ch->curr_comlink != NULL )
    {
        MSDPSetNumber( d, eMSDP_COMM_CHANNEL, ch->curr_comlink->value[5] );
        MSDPSetNumber( d, eMSDP_COMM_ENCRYPT, ch->curr_comlink->value[4]  );
        UpdateGMCPNumber( d, GMCP_COMM_CHANNEL, ch->curr_comlink->value[5] );

        if ( ch->curr_comlink->value[4] == 0 )
            UpdateGMCPNull( d, GMCP_COMM_ENCRYPT );
        else
            UpdateGMCPNumber( d, GMCP_COMM_ENCRYPT, ch->curr_comlink->value[4] );
    }
    else
    {
        UpdateGMCPNull( d, GMCP_COMM_CHANNEL );
        UpdateGMCPNull( d, GMCP_COMM_ENCRYPT );
    }

    MSDPSetNumber( d, eMSDP_OOC_LIMIT, ch->pcdata->ooclimit );
    MSDPSetNumber( d, eMSDP_OOC_BREAK, ch->pcdata->oocbreak );
    UpdateGMCPNumber( d, GMCP_OOC_LIMIT, ch->pcdata->ooclimit );
    UpdateGMCPBoolean( d, GMCP_OOC_BREAK, ch->pcdata->oocbreak );

    // See if they're aware enough to get any IC info about their surroundings
    if ( ch->position > POS_SLEEPING && check_blind( ch, TRUE ) && !has_pcflag( ch, PCFLAG_AFK ) )
    {
        ship = get_ship_from_cockpit( ch->in_room );

        if ( !ship )
            ship = get_ship_from_engine( ch->in_room );

        if ( ship != NULL )
        {
            MSDPSetNumber( d, eMSDP_IS_PILOTING, ship->piloting == ch ? 1 : 0 );
            MSDPSetNumber( d, eMSDP_SHIP_MAXSPEED, ship->realspeed );
            MSDPSetNumber( d, eMSDP_SHIP_HULL, ship->hull );
            MSDPSetNumber( d, eMSDP_SHIP_MAXHULL, ship->maxhull );
            MSDPSetNumber( d, eMSDP_SHIP_ENERGY, ship->energy );
            MSDPSetNumber( d, eMSDP_SHIP_MAXENERGY, ship->maxenergy );
            MSDPSetNumber( d, eMSDP_SHIP_SHIELD, ship->shield );
            MSDPSetNumber( d, eMSDP_SHIP_MAXSHIELD, ship->maxshield );
            UpdateGMCPBoolean( d, GMCP_IS_PILOTING, ship->piloting == ch );
            UpdateGMCPNumber( d, GMCP_SHIP_MAXSPEED, ship->realspeed );
            UpdateGMCPNumber( d, GMCP_SHIP_HULL, ship->hull );
            UpdateGMCPNumber( d, GMCP_SHIP_MAXHULL, ship->maxhull );
            UpdateGMCPNumber( d, GMCP_SHIP_ENERGY, ship->energy );
            UpdateGMCPNumber( d, GMCP_SHIP_MAXENERGY, ship->maxenergy );
            UpdateGMCPNumber( d, GMCP_SHIP_SHIELD, ship->shield );
            UpdateGMCPNumber( d, GMCP_SHIP_MAXSHIELD, ship->maxshield );
        }
        else
        {
            MSDPSetNumber( d, eMSDP_IS_PILOTING, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_MAXSPEED, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_HULL, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_MAXHULL, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_ENERGY, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_MAXENERGY, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_SHIELD, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_MAXSHIELD, 0 );
            UpdateGMCPNull( d, GMCP_IS_PILOTING );
            UpdateGMCPNull( d, GMCP_SHIP_MAXSPEED );
            UpdateGMCPNull( d, GMCP_SHIP_HULL );
            UpdateGMCPNull( d, GMCP_SHIP_MAXHULL );
            UpdateGMCPNull( d, GMCP_SHIP_ENERGY );
            UpdateGMCPNull( d, GMCP_SHIP_MAXENERGY );
            UpdateGMCPNull( d, GMCP_SHIP_SHIELD );
            UpdateGMCPNull( d, GMCP_SHIP_MAXSHIELD );
        }

        if ( ship && ship->starsystem )
        {
            MSDPSetNumber( d, eMSDP_SHIP_SPEED, ship->currspeed );
            MSDPSetNumber( d, eMSDP_SHIP_SYSX, ship->vpos.x );
            MSDPSetNumber( d, eMSDP_SHIP_SYSY, ship->vpos.y );
            MSDPSetNumber( d, eMSDP_SHIP_SYSZ, ship->vpos.z );
            MSDPSetNumber( d, eMSDP_SHIP_HEADX, ship->head.x );
            MSDPSetNumber( d, eMSDP_SHIP_HEADY, ship->head.y );
            MSDPSetNumber( d, eMSDP_SHIP_HEADZ, ship->head.z );
            MSDPSetNumber( d, eMSDP_SHIP_GALX, ship->starsystem->xpos );
            MSDPSetNumber( d, eMSDP_SHIP_GALY, ship->starsystem->ypos );
            MSDPSetString( d, eMSDP_SHIP_SYSNAME, ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
            UpdateGMCPNumber( d, GMCP_SHIP_SPEED, ship->currspeed );
            UpdateGMCPNumber( d, GMCP_SHIP_POS_X, ship->vpos.x );
            UpdateGMCPNumber( d, GMCP_SHIP_POS_Y, ship->vpos.y );
            UpdateGMCPNumber( d, GMCP_SHIP_POS_Z, ship->vpos.z );
            UpdateGMCPNumber( d, GMCP_SHIP_HEAD_X, ship->head.x );
            UpdateGMCPNumber( d, GMCP_SHIP_HEAD_Y, ship->head.y );
            UpdateGMCPNumber( d, GMCP_SHIP_HEAD_Z, ship->head.z );
            UpdateGMCPNumber( d, GMCP_SYS_X, ship->starsystem->xpos );
            UpdateGMCPNumber( d, GMCP_SYS_Y, ship->starsystem->ypos );
            UpdateGMCPString( d, GMCP_SYS_NAME, ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
        }
        else
        {
            MSDPSetNumber( d, eMSDP_SHIP_SPEED, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_SYSX, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_SYSY, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_SYSZ, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_HEADX, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_HEADY, 0 );
            MSDPSetNumber( d, eMSDP_SHIP_HEADZ, 0 );
            if ( ship && ship->shipstate == SHIP_HYPERSPACE )
            {
                MSDPSetNumber( d, eMSDP_SHIP_GALX, sys_coord_from_galactic_coords(ship->hyper_currentpos.x) );
                MSDPSetNumber( d, eMSDP_SHIP_GALY, sys_coord_from_galactic_coords(ship->hyper_currentpos.y) );
            }
            else
            {
                MSDPFlush( d, eMSDP_SHIP_GALX );
                MSDPFlush( d, eMSDP_SHIP_GALY );
            }
            MSDPSetString( d, eMSDP_SHIP_SYSNAME, "" );
            UpdateGMCPNull( d, GMCP_SHIP_SPEED );
            UpdateGMCPNull( d, GMCP_SHIP_POS_X );
            UpdateGMCPNull( d, GMCP_SHIP_POS_Y );
            UpdateGMCPNull( d, GMCP_SHIP_POS_Z );
            UpdateGMCPNull( d, GMCP_SHIP_HEAD_X );
            UpdateGMCPNull( d, GMCP_SHIP_HEAD_Y );
            UpdateGMCPNull( d, GMCP_SHIP_HEAD_Z );
            if ( ship && ship->shipstate == SHIP_HYPERSPACE )
            {
                UpdateGMCPNumber( d, GMCP_SYS_X, sys_coord_from_galactic_coords(ship->hyper_currentpos.x) );
                UpdateGMCPNumber( d, GMCP_SYS_Y, sys_coord_from_galactic_coords(ship->hyper_currentpos.y) );
            }
            else
            {
                UpdateGMCPNull( d, GMCP_SYS_X );
                UpdateGMCPNull( d, GMCP_SYS_Y );
            }
            UpdateGMCPNull( d, GMCP_SYS_NAME );
        }

        if ( has_pcflag( ch, PCFLAG_HOLYLIGHT ) || IS_AFFECTED( ch, AFF_TRUESIGHT ) || !room_is_dark( ch->in_room ) )
        {
            /* This would be better moved elsewhere */
            if ( pOpponent != NULL )
            {
                int hit_points = ( pOpponent->hit * 100 ) / pOpponent->max_hit;
                MSDPSetNumber( d, eMSDP_OPPONENT_HEALTH, hit_points );
                MSDPSetNumber( d, eMSDP_OPPONENT_HEALTH_MAX, 100 );
                MSDPSetString( d, eMSDP_OPPONENT_NAME, g_name( pOpponent, ch ) ); //Was giving keyword name of mobs and names of people. this should just give the name of what people know the opponent as. Also, can I say fuck MSDP
                UpdateGMCPString( d, GMCP_OPPONENT_NAME, g_name( pOpponent, ch ) );
                UpdateGMCPNumber( d, GMCP_OPPONENT_PERCENT, ( pOpponent->hit * 100 ) / pOpponent->max_hit );
            }
            else /* Clear the values */
            {
                MSDPSetNumber( d, eMSDP_OPPONENT_HEALTH, 0 );
                MSDPSetString( d, eMSDP_OPPONENT_NAME, "" );
                UpdateGMCPNull( d, GMCP_OPPONENT_NAME );
                UpdateGMCPNull( d, GMCP_OPPONENT_PERCENT );
            }

            /* Only update room stuff if they've changed room */
            if ( pRoom && pRoom->vnum != d->pProtocol->pVariables[eMSDP_ROOM_VNUM]->ValueInt )
            {
                EXIT_DATA* pexit = NULL;
                buf[0] = '\0';
                char exitsJson[MSL];
                exitsJson[0] = '\0';
                strlcat( exitsJson, "{", MSL );
                bool first = true;

                for ( pexit = ch->in_room->first_exit; pexit; pexit = pexit->next )
                {
                    if ( pexit->to_room
                            && ( !xIS_SET( pexit->flags, EX_WINDOW ) || xIS_SET( pexit->flags, EX_ISDOOR ) )
                            &&  !xIS_SET( pexit->flags, EX_SECRET )
                            &&  !xIS_SET( pexit->flags, EX_HIDDEN )
                            &&  !xIS_SET( pexit->flags, EX_DIG ) )
                    {
                        const char MsdpVar[] = { ( char )MSDP_VAR, '\0' };
                        const char MsdpVal[] = { ( char )MSDP_VAL, '\0' };

                        if ( xIS_SET( pexit->flags, EX_CLOSED ) )
                        {
                            if ( pexit->keyword
                                    && ( !str_cmp( "door", pexit->keyword )
                                         ||   !str_cmp( "gate", pexit->keyword )
                                         ||    pexit->keyword[0] == '\0' ) )
                            {
                                strlcat( buf, MsdpVar, MSL );
                                strlcat( buf, dir_name[pexit->vdir], MSL );
                                strlcat( buf, MsdpVal, MSL );
                                strlcat( buf, "C", MSL );

                                if ( !first )
                                    strlcat( exitsJson, ",", MSL );

                                strlcat( exitsJson, "\"", MSL );
                                strlcat( exitsJson, dir_name[pexit->vdir], MSL );
                                strlcat( exitsJson, "\": \"C\"", MSL );
                                first = false;
                            }
                        }
                        else
                        {
                            strlcat( buf, MsdpVar, MSL );
                            strlcat( buf, dir_name[pexit->vdir], MSL );
                            strlcat( buf, MsdpVal, MSL );
                            strlcat( buf, "O", MSL );

                            if ( !first )
                                strlcat( exitsJson, ",", MSL );

                            strlcat( exitsJson, "\"", MSL );
                            strlcat( exitsJson, dir_name[pexit->vdir], MSL );
                            strlcat( exitsJson, "\": \"O\"", MSL );
                            first = false;
                        }
                    }
                }

                strlcat( exitsJson, "}", MSL );
                MSDPSetString( d, eMSDP_ROOM_NAME, stripclr( pRoom->name ) );
                MSDPSetTable( d, eMSDP_ROOM_EXITS, buf );
                MSDPSetNumber( d, eMSDP_ROOM_VNUM, pRoom->vnum );
                MSDPSetString( d, eMSDP_PLANET, pRoom->area->planet ? pRoom->area->planet->name : NULL );
                UpdateGMCPString( d, GMCP_ROOM_NAME, stripclr( pRoom->name ) );
                UpdateGMCPNumber( d, GMCP_ROOM_VNUM, pRoom->vnum );
                UpdateGMCPObject( d, GMCP_ROOM_EXITS, exitsJson );
                UpdateGMCPString( d, GMCP_PLANET, pRoom->area->planet ? stripclr( pRoom->area->planet->name ) : NULL );

                if ( pRoom->mapper_coords_set )
                {
                    UpdateGMCPNumber( d, GMCP_ROOM_X, pRoom->mapper_x );
                    UpdateGMCPNumber( d, GMCP_ROOM_Y, pRoom->mapper_y );
                    UpdateGMCPNumber( d, GMCP_ROOM_Z, pRoom->mapper_z );
                }
                else
                {
                    UpdateGMCPNull( d, GMCP_ROOM_X );
                    UpdateGMCPNull( d, GMCP_ROOM_Y );
                    UpdateGMCPNull( d, GMCP_ROOM_Z );
                }
            }
        }
    }

    /*
                MSDPSetNumber( d, eMSDP_WORLD_TIME,  );
    */
    strlcat( buf, "", MSL );

    for ( paf = ch->first_affect; paf; paf = paf->next )
    {
        if ( ( skill = skill_from_id( paf->type ) ) != NULL )
        {
            char skill_buf[MSL];
            snprintf( skill_buf, MSL, "%c%s%c%d",
                     ( char )MSDP_VAR, skill->name,
                     ( char )MSDP_VAL, paf->duration );
            strlcat( buf, skill_buf, MSL );
        }
    }

    MSDPSetTable( d, eMSDP_AFFECTS, buf );
    MSDPUpdate( d );
    SendUpdatedGMCP( d );
    return true;
}

void msdp_update( void )
{
    int PlayerCount = 0;
    // GMCP/MSDP update can cause descriptors to be closed, so iterate safely.
    DESCRIPTOR_DATA* d_next = NULL;

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d_next )
    {
        d_next = d->next;

        if ( msdp_update_one_player( d ) )
            PlayerCount++;
    }

    /*  Ideally this should be called once at startup, and again whenever
        someone leaves or joins the mud.  But this works, and it keeps the
        snippet simple.  Optimise as you see fit.
    */
    MSSPSetPlayers( PlayerCount );
}

//  Room Hazards Support (cold/hot) By Rojan & Anna
void update_roomhazards()
{
    CHAR_DATA* ch;

    for ( ch = last_char; ch; ch = gch_prev )
    {
        if ( ch == first_char && ch->prev )
        {
            bug( "update_roomhazards: first_char->prev != NULL... fixed", 0 );
            ch->prev = NULL;
        }

        gch_prev = ch->prev;
        set_cur_char( ch );

        if ( gch_prev && gch_prev->next != ch )
        {
            bug( "update_roomhazards: ch->prev->next != ch", 0 );
            return;
        }

        if ( !IS_NPC( ch ) && ( !ch->spirit ) )
        {
            if ( xIS_SET( ch->in_room->flags, ROOM_COLD ) || xIS_SET( ch->in_room->flags, ROOM_HOT ) || xIS_SET( ch->in_room->flags, ROOM_GAS ) )
            {
                int env_dmg = 0;

                if ( xIS_SET( ch->in_room->flags, ROOM_COLD ) )
                {
                    if ( xIS_SET( ch->immune, RIS_COLD ) || ( xIS_SET( ch->race->flags, RFLAG_COLDIMMUNE ) ) )
                    {
                        ch_println( ch, "&OThe icy winds blow past you but you are protected.&w" );
                    }
                    else if ( xIS_SET( ch->resistant, RIS_COLD ) || ( xIS_SET( ch->race->flags, RFLAG_COLDRESISTANCE ) ) )
                    {
                        env_dmg = 10;
                        ch->move = UMAX( ch->move - 25, 0 );
                        ch_println( ch, "&CYou shiver from the cold but you are protected from the brunt of the icy winds!&w" );
                    }
                    else
                    {
                        env_dmg = 25;
                        ch->move = UMAX( ch->move - 50, 0 );
                        ch_println( ch, "&CYou shiver from the bitter cold!&w" );
                    }
                }

                if ( xIS_SET( ch->in_room->flags, ROOM_HOT ) )
                {
                    if ( xIS_SET( ch->immune, RIS_FIRE ) || ( xIS_SET( ch->race->flags, RFLAG_HEATIMMUNE ) ) )
                    {
                        ch_println( ch, "&RYou are protected from the blazing heat.&w" );
                    }
                    else if ( xIS_SET( ch->resistant, RIS_FIRE ) || ( xIS_SET( ch->race->flags, RFLAG_HEATRESISTANCE ) ) )
                    {
                        env_dmg = 10;
                        ch->move = UMAX( ch->move - 25, 0 );
                        ch->pcdata->condition[COND_THIRST] -= 2;
                        ch_println( ch, "&RYour body recoils slightly as the blazing heat takes its toll.&w" );
                    }
                    else
                    {
                        env_dmg = 25;
                        ch->move = UMAX( ch->move - 50, 0 );
                        ch->pcdata->condition[COND_THIRST] -= 5;
                        ch_println( ch, "&RYour body wilts as the blazing heat takes its toll.&w" );
                    }
                }

                if ( xIS_SET( ch->in_room->flags, ROOM_GAS ) )
                {
                    if ( xIS_SET( ch->immune, RIS_GAS ) || xIS_SET( ch->race->flags, RFLAG_GASIMMUNE ) ||
                    xIS_SET( ch->race->flags, RFLAG_HASREBREATHER ) || xIS_SET( ch->race->flags, RFLAG_DROID ) )
                    {
                        ch_println( ch, "&RYou are protected from the noxious fumes.&w" );
                    }
                    else if ( xIS_SET( ch->resistant, RIS_GAS ) || xIS_SET( ch->race->flags, RFLAG_GASRESISTANCE ) )
                    {
                        env_dmg = 10;
                        ch->move = UMAX( ch->move - 25, 0 );
                        ch_println( ch, "&OYour body recoils as the noxious fumes take their toll.&w" );
                    }
                    else
                    {
                        env_dmg = 25;
                        ch->move = UMAX( ch->move - 50, 0 );
                        ch_println( ch, "&OYou inhale noxious fumes, causing your lungs to burn in agony.&w" );
                    }
                }

                if ( env_dmg > 0 )
                {
                    damage( ch, ch, env_dmg, TYPE_UNDEFINED );

                    if ( ch->hit <= -490 && !IS_IMMORTAL( ch ) && !isFighting( ch ) )
                    {
                        if ( xIS_SET( ch->in_room->flags, ROOM_COLD ) )
                        {
                            ch_println( ch, "&CYour vision blackens as the numbness takes over.&w" );
                            act( AT_DEAD, "$n ceases moving as the frost takes over their body", ch, NULL, NULL, TO_ROOM );
                        }
                        else if ( xIS_SET( ch->in_room->flags, ROOM_HOT ) )
                        {
                            ch_println( ch, "&RYour body fails as you are consumed by the heat.&w" );
                            act( AT_DEAD, "$n collapses to the ground as a withered husk.", ch, NULL, NULL, TO_ROOM );
                        }
                        else if ( xIS_SET( ch->in_room->flags, ROOM_GAS ) )
                        {
                            ch_println( ch, "&OYour vision blackens as the lack of clean air suffocates you.&w" );
                            act( AT_DEAD, "$n collapses to the ground gasping for air before ceasing to move.", ch, NULL, NULL, TO_ROOM );
                        }

                        raw_kill( ch, ch );
                    }
                }
            }
        }
    }
}

void desc_history_pester( void )
{
    DESCRIPTOR_DATA* d = NULL;
    CHAR_DATA* vch = NULL;
    char buf[1024], buf2[1024], buf3[1024];
    snprintf( buf, 1024, "&zYou still haven't set your history or description.\nPlease use the &Chistory&z and &Cdescription&z commands." );
    snprintf( buf2, 1024, "&zYou still haven't set your history. Please use the &Chistory&z command." );
    snprintf( buf3, 1024, "&zYou still haven't set your description. Please use the &Cdescription&z command." );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING )
            continue;

        if ( ( vch = d->character ) == NULL )
            continue;

        if ( IS_NPC( vch ) )
            continue;

        if ( vch->top_level < 30 || IS_RPC( vch ) || IS_IMMORTAL( vch ) )
            continue;

        if ( !NULLSTR( vch->description ) && !NULLSTR( vch->pcdata->bio ) )
            continue;

        if ( NULLSTR( vch->description ) && NULLSTR( vch->pcdata->bio ) )
            ch_println( vch, buf );
        else if ( NULLSTR( vch->pcdata->bio ) )
            ch_println( vch, buf2 );
        else if ( NULLSTR( vch->description ) )
            ch_println( vch, buf3 );
    }

    return;
}

