/*
    Adds a help page to the list if it is not a duplicate of an existing page.
    Page is insert-sorted by keyword.            -Thoric
    (The reason for sorting is to keep do_hlist looking nice)
*/
void add_help( HELP_DATA* pHelp, bool savefile )
{
    if ( !pHelp )
        return;

    HELP_DATA* tHelp;

    for ( tHelp = first_help; tHelp; tHelp = tHelp->next )
    {
        if ( pHelp->level == tHelp->level && !str_cmp( pHelp->keyword, tHelp->keyword ) )
        {
            bug( "%s: duplicate: %s. Deleting.", FUNC, pHelp->keyword );
            FREE_STRUCT_NORET( pHelp, help_fields );
            return;
        }
    }

    LINK_SORT_NAME( pHelp, HELP_DATA, first_help, last_help, next, prev, keyword );

    if ( savefile == TRUE )
        save_help( pHelp );

    top_help++;
    return;
}

int save_help( HELP_DATA* pHelp )
{
    if ( !pHelp )
        return E_LOTJ_MISSING_ARGUMENTS;

    return upsert_sql_fieldmap_row( DB_TABLE_HELPS, pHelp, help_fields, NO_FLAG );
}

int delete_help( HELP_DATA* pHelp )
{
    if ( !pHelp )
        return E_LOTJ_MISSING_ARGUMENTS;

    return delete_sql_row_by_id( DB_TABLE_HELPS, pHelp->id );
}

int save_helps_sql( void )
{
    HELP_DATA* pHelp;
    int rval;

    for ( pHelp = first_help; pHelp; pHelp = pHelp->next )
        if ( ( rval = save_help(pHelp) ) != E_LOTJ_SUCCESS )
            bug( "%s: failed to save helpfile %s", FUNC, pHelp->keyword ? pHelp->keyword : itoa( pHelp->id ) );

    return E_LOTJ_SUCCESS;
}

