    int rval;
    CREATE( pHelp, HELP_DATA, 1 );
    if ( ( rval = fieldmap_postgres_row(res, row, pHelp, help_fields)) != E_LOTJ_SUCCESS)
    {
        FREE_STRUCT( pHelp, help_fields );
        return rval;
    }

    if ( !str_cmp( pHelp->keyword, "greeting" ) )
        SET_STRING( help_greeting, pHelp->text );

    if ( !str_cmp( pHelp->keyword, "wizlist" ) )
        SET_STRING( help_wizlist, pHelp->text );

    add_help( pHelp, FALSE );
    return E_LOTJ_SUCCESS;
}

/*
    Add a character to the list of all characters        -Thoric
*/
void add_char( CHAR_DATA* ch )
{
    LINK( ch, first_char, last_char, next, prev );
    hashset_add( valid_chars, ch );

    if ( ch->pIndexData )
    {
        for ( MPROG_DATA* mprog = ch->pIndexData->first_mprog; mprog; mprog = mprog->next )
        {
            if ( ( mprog->type & TIME_PROG ) || ( mprog->type & HOUR_PROG ) )
            {
                TIMEPROG_DATA* tp = NULL;
                CREATE( tp, TIMEPROG_DATA, 1 );
                tp->tch = ch;
                ch->tmprog = tp;
                LINK( tp, first_timeprog, last_timeprog, next, prev );
                break;
            }
        }
    }

    if ( lua_trigger_exists( &ch->first_trigger, LUA_TRIGGER_CHPR_ON_TIME ) || ( ch->pIndexData && lua_trigger_exists( &ch->pIndexData->first_trigger, LUA_TRIGGER_CHPR_ON_TIME ) ))
    {
        TIMEPROG_DATA* tp = NULL;
        CREATE( tp, TIMEPROG_DATA, 1 );
        tp->tch = ch;
        ch->tlprog = tp;
        LINK( tp, first_timeprog, last_timeprog, next, prev );
    }
}

/*
    Go through all areas, and set up initial economy based on mob
    levels and gold
*/
void initialize_economy( void )
{
    AREA_DATA* tarea;
    MOB_INDEX_DATA* mob;
    int idx, gold, rng;

    for ( tarea = first_area; tarea; tarea = tarea->next )
    {
        /*
            skip area if they already got some gold
        */
        if ( tarea->high_economy > 0 || tarea->low_economy > 10000 )
            continue;

        rng = 25;
        gold = rng * rng * 10000;
        boost_economy( tarea, gold );

        for ( idx = tarea->min_vnum; idx < tarea->max_vnum; idx++ )
            if ( ( mob = get_mob_index( idx ) ) != NULL )
                boost_economy( tarea, mob->gold * 10 );
    }
}

/*
    Translate all room exits from virtual to real.
    Has to be done after all rooms are read in.
    Check for bad reverse exits.
*/
void fix_exits( void )
{
    ROOM_INDEX_DATA* pRoomIndex;
    AREA_DATA* area = NULL;
    EXIT_DATA* pexit, *pexit_next, *rev_exit;
    bool fexit;

    top_exit = 0;

    for ( pRoomIndex = first_room; pRoomIndex; pRoomIndex = pRoomIndex->next )
    {
        fexit = FALSE;

        for ( pexit = pRoomIndex->first_exit; pexit; pexit = pexit_next )
        {
            pexit_next = pexit->next;
            top_exit++;
            pexit->rvnum = pRoomIndex->vnum;

            if ( pexit->vnum <= 0 || ( pexit->to_room = get_room_index( pexit->vnum ) ) == NULL )
            {
                if ( fBootDb )
                    boot_log( "Fix_exits: room %d, exit %s leads to bad vnum (%d)",
                            pRoomIndex->vnum, dir_name[pexit->vdir], pexit->vnum );

                for ( area = first_area_archive; area; area = area->next )
                    if ( pexit->vnum >= area->min_vnum && pexit->vnum <= area->max_vnum )
                        break;

                if ( !area )
                {
                    bug( "Deleting %s exit in room %d", dir_name[pexit->vdir], pRoomIndex->vnum );
                    extract_exit( pRoomIndex, pexit );
                    fexit = TRUE;                    
                }
            }
        }

        /* If an invalid exit was extracted and there are no other exits left,
        set the nomob flag to prevent mobs from pooling in detached rooms */

        if ( fexit && !pRoomIndex->first_exit )
            xSET_BIT( pRoomIndex->flags, ROOM_NO_MOB );
    }

    /*
        Set all the rexit pointers   -Thoric
    */
    for ( pRoomIndex = first_room; pRoomIndex; pRoomIndex = pRoomIndex->next )
    {
        for ( pexit = pRoomIndex->first_exit; pexit; pexit = pexit->next )
        {
            if ( pexit->to_room && !pexit->rexit )
            {
                rev_exit = get_exit_to( pexit->to_room, rev_dir[pexit->vdir], pRoomIndex->vnum );

                if ( rev_exit )
                {
                    pexit->rexit = rev_exit;
                    rev_exit->rexit = pexit;
                }
            }
        }
    }

    return;
}

/*
    Repopulate areas periodically.
*/
void area_update( bool force_reset )
{
    AREA_DATA* pArea = NULL;
    ROOM_INDEX_DATA* room = NULL, *school = get_room_index( ROOM_VNUM_SCHOOL );
    CHAR_DATA* ch = NULL;

    for ( pArea = first_area; pArea; pArea = pArea->next )
    {
        int reset_age = pArea->reset_frequency ? pArea->reset_frequency : 15;

        if ( !force_reset && ( ( reset_age == -1 && pArea->age == -1 ) || ++pArea->age < ( reset_age - 1 ) ) )
            continue;

        /*
            Check age and reset.
            Note: Mud Academy resets every 3 minutes (not 15).
        */
        if ( pArea->nplayer == 0 || pArea->age >= reset_age || force_reset )
        {
            pArea->reset_queued = TRUE;

            if ( reset_age == -1 )
                pArea->age = -1;
            else
                pArea->age = number_range( 0, reset_age / 5 );

            if ( school != NULL && pArea == school->area && pArea->reset_frequency == 0 )
                pArea->age = 15 - 3;
        }
    }

    for ( room = first_room; room; room = room->next )
    {
        if ( room->area && room->area->reset_queued )
        {
            reset_room( room );
            for ( ch = room->first_person; ch; ch = ch->next_in_room )
                if ( !IS_NPC( ch ) && IS_AWAKE( ch ) )
                    ch_println( ch, "%s", !NULLSTR( room->area->resetmsg ) ? room->area->resetmsg : "&gTime passes as eternity continues to unfold...&w" );
        }
    }

    for ( pArea = first_area; pArea; pArea = pArea->next )
        pArea->reset_queued = FALSE;

    return;
}

