        case ITEM_BOLT:
            if ( obj->value[0] <= 0 )
                obj->value[0] = number_fuzzy( 95 );

            break;

        case ITEM_AMMO:
            if ( obj->value[0] <= 0 )
                obj->value[0] = number_fuzzy( 495 );

            break;

        case ITEM_WEAPON:
            if ( obj->value[1] && obj->value[2] )
            {
                /*
                    Okay, What purpose does this load of bullshit here
                    serve? It changes my preset values! Damnit!

                    obj->value[2] *= obj->value[1];
                */
            }
            else
            {
                /*
                    obj->value[1] = number_fuzzy( number_fuzzy( 1 + level/20 ) );
                    obj->value[2] = number_fuzzy( number_fuzzy( 10 + level/10 ) );
                */
            }

            if ( obj->value[1] > obj->value[2] )
                obj->value[1] = obj->value[2] / 3;

            if ( obj->value[0] == 0 )
                obj->value[0] = INIT_WEAPON_CONDITION;

            switch ( obj->value[3] )
            {
                case WEAPON_BLASTER:
                case WEAPON_LIGHTSABER:
                case WEAPON_VIBRO_BLADE:
                case WEAPON_VIBRO_AXE:
                case WEAPON_FORCE_PIKE:
                case WEAPON_BOWCASTER:
                    if ( obj->value[5] <= 0 )
                        obj->value[5] = number_fuzzy( 1000 );
            }

            obj->value[4] = obj->value[5];

            if ( obj->value[3] == WEAPON_BLASTER )
                obj->blaster_setting = BLASTER_FULL;

            break;

        case ITEM_ARMOR:
        case ITEM_SHIELD:
            if ( obj->value[0] == 0 )
                obj->value[0] = obj->value[1];

            break;

        case ITEM_PILL:
            obj->value[0] = number_fuzzy( number_fuzzy( obj->value[0] ) );
            break;

        case ITEM_MONEY:
            obj->value[0] = obj->cost;
            break;
    }

    add_obj( obj );
    ++pObjIndex->count;
    ++numobjsloaded;
    ++physicalobjects;

    return obj;
}

VSNOOP_DATA *vsnoop_start(CHAR_DATA *ch) {
    VSNOOP_DATA *vsnoop;

    if(ch == NULL) {
        bug("start_memstream: NULL ch", 0);
        return NULL;
    }

    CREATE(vsnoop, VSNOOP_DATA, 1);
    vsnoop->ch = ch;
    vsnoop->fp_memstream = open_memstream(&vsnoop->memstream_buf, &vsnoop->memstream_size);
    LINK(vsnoop, first_vsnoop, last_vsnoop, next, prev);
    LINK(vsnoop, ch->first_vsnoop, ch->last_vsnoop, next_in_ch, prev_in_ch);

    return vsnoop;
}

char* vsnoop_close( VSNOOP_DATA *vsnoop )
{
    char* retval;
    if( vsnoop == NULL )
    {
        bug( "%s: NULL vsnoop", FUNC );
        return NULL;
    }

    fclose( vsnoop->fp_memstream );
    retval = STRALLOC( vsnoop->memstream_buf );
    STRFREE( vsnoop->memstream_buf );
    UNLINK( vsnoop, first_vsnoop, last_vsnoop, next, prev );
    UNLINK( vsnoop, vsnoop->ch->first_vsnoop, vsnoop->ch->last_vsnoop, next_in_ch, prev_in_ch );
    DISPOSE( vsnoop );
    return retval;
}

