ROOM_INDEX_DATA* get_room_template( ROOM_INDEX_DATA* room )
{
    if ( !room )
        return NULL;

    SHIP_DATA* ship = get_ship_from_room( room );
    if ( ship && ship->template )
    {
        int offset = room->vnum - room->on_ship->firstroom;
        for ( ROOM_INDEX_DATA* template = room->on_ship->template->first_room; template; template = template->next_in_range )
            if ( template->vnum == offset )
                return template;
        return NULL;
    }

    STRUCTURE_DATA* structure = structure_from_room( room->vnum );
    if ( structure && structure->template )
    {
        int offset = room->vnum - structure->firstroom;
        for ( ROOM_INDEX_DATA* template = structure->template->first_room; template; template = template->next_in_range )
            if ( template->vnum == offset )
                return template;
        return NULL;
    }
    return NULL;
}

