char* b64encode( const char* input )
{
    static char output[MSL];
    char* c = output;
    int cnt;
    base64_encodestate s;

    if ( strlen( input ) > MAX_B64_STRING_LENGTH - 1 )
    {
        bug( "&RCan't encode string, it is too long. Begins with %.15s. Note, whatever you saved, it probably is missing an lprog.", input);
        return NULL;
    }

    base64_init_encodestate( &s );
    cnt = base64_encode_block( input, strlen( input ), c, &s );
    c += cnt;
    cnt = base64_encode_blockend( c, &s );
    c += cnt;
    *c = 0;
    return output;
}

char* b64decode( const char* input )
{
    static char output[MSL];
    strlcpy( output, "", MSL );
    char* c = output;
    base64_decodestate s;
    int cnt;
    base64_init_decodestate( &s );
    cnt = base64_decode_block( input, strlen( input ), c, &s );
    c += cnt;
    *c = 0;

    for ( cnt = 0; output[cnt] != '\0'; cnt++ )
    {
        if ( !isascii( output[cnt] )
                && !isprint( output[cnt] )
                && output[cnt] != '\n'
                && output[cnt] != '\r'
                && output[cnt] != '\0' )
        {
            bug( "Invalid character found in base64 decode, string discarded." );
            output[0] = '\0';
            break;
        }
    }

    return output;
}

