/*
    Compare strings, case insensitive.
    Return TRUE if different
     (compatibility with historical functions).
*/
bool str_cmp( const char* astr, const char* bstr )
{
    if ( !astr || !bstr )
        return TRUE;

    for ( ; *astr || *bstr; astr++, bstr++ )
    {
        if ( LOWER( *astr ) != LOWER( *bstr ) )
            return TRUE;
    }

    return FALSE;
}

/*
    Compare strings, case insensitive, for prefix matching.
    Return TRUE if astr not a prefix of bstr
     (compatibility with historical functions).
*/
bool str_prefix( const char* astr, const char* bstr )
{
    if ( !astr || !bstr )
        return TRUE;

    for ( ; *astr; astr++, bstr++ )
    {
        if ( LOWER( *astr ) != LOWER( *bstr ) )
            return TRUE;
    }

    return FALSE;
}



/*
    Compare strings, case insensitive, for match anywhere.
    Returns TRUE is astr not part of bstr.
     (compatibility with historical functions).
*/
bool str_infix( const char* astr, const char* bstr )
{
    int sstr1;
    int sstr2;
    int ichar;
    char c0;

    if ( ( c0 = LOWER( astr[0] ) ) == '\0' )
        return FALSE;

    sstr1 = strlen( astr );
    sstr2 = strlen( bstr );

    for ( ichar = 0; ichar <= sstr2 - sstr1; ichar++ )
        if ( c0 == LOWER( bstr[ichar] ) && !str_prefix( astr, bstr + ichar ) )
            return FALSE;

    return TRUE;
}



/*
    Compare strings, case insensitive, for suffix matching.
    Return TRUE if astr not a suffix of bstr
     (compatibility with historical functions).
*/
bool str_suffix( const char* astr, const char* bstr )
{
    int sstr1;
    int sstr2;
    sstr1 = strlen( astr );
    sstr2 = strlen( bstr );

    if ( sstr1 <= sstr2 && !str_cmp( astr, bstr + sstr2 - sstr1 ) )
        return FALSE;
    else
        return TRUE;
}



/*
    Returns an initial-capped string.
*/
char* capitalize( const char* str )
{
    static char buf[MSL];
    char* dest = buf;
    enum { Normal, Color } state = Normal;
    bool bFirst = TRUE;
    char c;

    while ( ( c = *str++ ) )
    {
        if ( state == Normal )
        {
            if ( c == '&' || c == '^' || c == '}' )
            {
                state = Color;
            }
            else if ( isalpha( c ) )
            {
                c = bFirst ? toupper( c ) : tolower( c );
                bFirst = FALSE;
            }
        }
        else
        {
            state = Normal;
        }

        *dest++ = c;
    }

    *dest = c;
    return buf;
}

// A variant of capitalize() which uppercases the first letter of the string and leaves the rest unchanged.
char* capitalize_first( const char* str )
{
    static char buf[MSL];
    char* dest = buf;
    enum { Normal, Color } state = Normal;
    bool bFirst = TRUE;
    char c;

    while ( ( c = *str++ ) )
    {
        if ( state == Normal )
        {
            if ( c == '&' || c == '^' || c == '}' )
            {
                state = Color;
            }
            else if ( isalpha( c ) )
            {
                c = bFirst ? toupper( c ) : c;
                bFirst = FALSE;
            }
        }
        else
        {
            state = Normal;
        }

        *dest++ = c;
    }

    *dest = c;
    return buf;
}

/*
    Returns a lowercase string.
*/
char* strlower( const char* str )
{
    static char* strlow = NULL;

    if ( !str )
        return NULL;

    if ( strlow )
        DISPOSE( strlow );

    if ( dump_mem_on_shutdown && str == memdebug_signal )
        return NULL;

    size_t buflen = strlen( str ) + 1;
    strlow = malloc( buflen * sizeof( char ) );
    memset( strlow, '\0', buflen );
    int i;

    for ( i = 0; str[i] != '\0'; i++ )
        strlow[i] = LOWER( str[i] );

    strlow[i] = '\0';
    return strlow;
}

/*
    Returns a lowercase string without modifying the source string
*/
const char* strlower_safe( const char* str )
{
    static char strlow[MSL], orgstring[MSL];
    strlcpy( strlow, "", MSL );
    strlcpy( orgstring, str, MSL );
    int i;

    for ( i = 0; orgstring[i] != '\0'; i++ )
        strlow[i] = LOWER( orgstring[i] );

    strlow[i] = '\0';
    return strlow;
}

/*
    Returns a lowercase string with first letter capitalized, without modifying the source string
*/
const char* sentence_case( const char* str )
{
    static char result[MSL], orgstring[MSL];
    strlcpy( result, "", MSL );
    strlcpy( orgstring, str, MSL );
    char upper;
    int i;

    for ( i = 0; orgstring[i] != '\0'; i++ )
        result[i] = LOWER( orgstring[i] );

    result[i] = '\0';
    upper = toupper( result[0] );
    result[0] = upper;
    return result;
}

const char* rempunc(const char* str)
{
    static char result[MSL];  // A statically allocated buffer
    size_t j = 0;

    for (size_t i = 0; str[i] != '\0'; ++i)
        if ( !ispunct( (unsigned char)str[i] ) || (unsigned char)str[i] == '\'' || (unsigned char)str[i] == '-' )
            result[j++] = str[i];

    result[j] = '\0';  // Terminate the result string
    return result;
}

/*
    Returns an uppercase string.
*/
char* strupper( const char* str )
{
    static char strup[MSL];
    int i;

    for ( i = 0; str[i] != '\0'; i++ )
        strup[i] = UPPER( str[i] );

    strup[i] = '\0';
    return strup;
}

const char* strspacetounderscore( const char* str )
{
