/*
    Add a string to the boot-up log              -Thoric
*/
void boot_log( const char* str, ... )
{
    char buf[MSL];
    FILE* fp;
    va_list param;
    strlcpy( buf, "[*****] BOOT: ", MSL );
    va_start( param, str );
