/*
    Writes a string to the log, extended version         -Thoric
*/
void log_string_plus( const char* str, sh_int log_type, sh_int level )
{
    char* strtime;
    int offset;
    time_t now = time( 0 );
    strtime = ctime( &now );
    strtime[strlen( strtime ) - 1] = '\0';
    fprintf( stderr, "%s :: %s\n", strtime, str );

    if ( strncmp( str, "Log ", 4 ) == 0 )
        offset = 4;
    else
        offset = 0;

    switch ( log_type )
    {
        default:
            to_channel( str + offset, CHANNEL_LOG, "Log", level );
            break;

        case LOG_BUILD:
            to_channel( str + offset, CHANNEL_BUILD, "Build", level );
            break;

        case LOG_COMM:
            to_channel( str + offset, CHANNEL_COMM, "Comm", level );
            break;

        case LOG_MPROG:
            to_channel( str + offset, CHANNEL_MPROG, "MProg", level );
            break;

        case LOG_LPROG:
            to_channel( str + offset, CHANNEL_LPROG, "LProg", level );
            break;

        case LOG_ALL:
            break;
    }

    return;
}

