// Function to delete a room from the SQL database. - Nield 10/26/2024
int delete_room( ROOM_INDEX_DATA* room )
{
    char buf[MSL];

    if ( !room )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( room->delete_queued )
        return E_LOTJ_NOTHING_TO_DO;

    room->delete_queued = TRUE;

    snprintf( buf, MSL, "vnum = %d AND area = %s", room->vnum, sql_escape_string( room->area->shortname) );
    int result = delete_sql_by_where( DB_TABLE_ROOMS, buf );
    unload_room( room );
    return result;
}

int free_phome( PHOME_DATA* phome )
{
    if ( !phome )
