    FREE_STRUCT( phome, phome_fields );
    return E_LOTJ_SUCCESS;
}

bool room_extracted( ROOM_INDEX_DATA* room )
{
    if ( !room )
        return TRUE;

    return room->extracted;
}

int queue_extracted_room( ROOM_INDEX_DATA* room )
{
    if ( !room )
        return E_LOTJ_MISSING_ARGUMENTS;

    add_extract_queue( room, EXTRACT_ROOM );
    room->extracted = TRUE;
    cur_qrooms++;
    return E_LOTJ_SUCCESS;
}

int unload_room( ROOM_INDEX_DATA* room )
{
    ROOM_INDEX_DATA* limbo = get_room_index( ROOM_VNUM_LIMBO ), *troom = NULL;
    CHAR_DATA* ch = NULL, *next_ch = NULL;
    EXIT_DATA* ex = NULL, *next_ex = NULL;
    EXTRA_DESCR_DATA* ed = NULL, *ted = NULL;
    BUFFER_DATA* buffer = NULL;
    SHIP_DATA* ship = NULL, *next_ship = NULL;
    VEHICLE_DATA* vehicle = NULL, *next_vehicle = NULL;
    FURN_DATA* furn = NULL, *next_furn = NULL;
    TURRET_DATA* pTurret = NULL, *next_pTurret = NULL;

    if ( !room )
        return E_LOTJ_MISSING_ARGUMENTS;

    // Extract the Lua triggers specifically targeting this room
    lua_triggers_extract_subject( &room->first_trigger, 0 );
    lua_extract_delayed_triggers( room, LUA_PARAM_ROOM );

    if ( room->tmprog )
    {
        UNLINK( room->tmprog, first_timeprog, last_timeprog, next, prev );
        DISPOSE( room->tmprog );
    }

    if ( room->tlprog )
    {
        UNLINK( room->tlprog, first_timeprog, last_timeprog, next, prev );
        DISPOSE( room->tlprog );
    }

    // Remove all the occupants of the room, transferring players and extracting mobs
    for ( ch = room->first_person; ch; ch = next_ch )
    {
        next_ch = ch->next_in_room;

        if ( !IS_NPC( ch ) )
            char_to_room( ch, limbo );
        else
            extract_char( ch );
    }

    if ( room->on_ship )
        UNLINK( room, room->on_ship->first_room, room->on_ship->last_room, next_in_range, prev_in_range );

    // Clear up any backlinks to this room for players not currently in it
    for ( ch = first_char; ch; ch = next_ch )
    {
        next_ch = ch->next;

        if ( ch->substate != SUB_ROOM_DESC && ch->substate != SUB_ROOM_EXTRA )
            continue;

        if ( ch->was_in_room == room )
            ch->was_in_room = ch->in_room;

        buffer = ch->first_buffer;

        if ( !buffer )
            continue;

        troom = ( ROOM_INDEX_DATA* )buffer->buf1;
        ted = buffer->ed;

        if ( ch->substate == SUB_ROOM_DESC && troom && troom == room )
        {
            ch_println( ch, "The room is no more." );
            stop_editing( ch, false );
            ch->substate = SUB_NONE;
            dispose_buffer( buffer );
        }
        else if ( ch->substate == SUB_ROOM_EXTRA && ted )
        {
            for ( ed = room->first_extradesc; ed; ed = ed->next )
            {
                if ( ed == ted )
                {
                    ch_println( ch, "The room is no more." );
                    stop_editing( ch, false );
                    ch->substate = SUB_NONE;
                    dispose_buffer( buffer );
                    break;
                }
            }
        }
    }

    for ( ship = first_ship; ship; ship = next_ship )
    {
        if ( ship_extracted( ship ) )
        {
            next_ship = first_ship;
            continue;
        }

        next_ship = ship->next;
        if ( room->vnum >= ship->firstroom && room->vnum <= ship->lastroom )
        {
            bug( "%s: ship %s contains room %d, which is being %s. %s ship.", FUNC, ship->name, room->vnum, room->delete_queued ? "deleted" : "unloaded", room->delete_queued ? "deleting" : "unloading" );
            if ( room->delete_queued )
                delete_ship( ship );
            else
                extract_ship( ship );
        }
    }

    for ( ship = first_drydock; ship; ship = next_ship )
    {
        if ( ship_extracted( ship ) )
        {
            next_ship = first_drydock;
            continue;
        }

        next_ship = ship->next;
        if ( room->vnum >= ship->firstroom && room->vnum <= ship->lastroom )
        {
            bug( "%s: drydocked ship %s contains room %d, which is being %s. %s ship.", FUNC, ship->name, room->vnum, room->delete_queued ? "deleted" : "unloaded", room->delete_queued ? "deleting" : "unloading" );
            if ( room->delete_queued )
                delete_ship( ship );
            else
                extract_ship( ship );
        }
    }

    // Move all the ships out of this room
    for ( ship = room->first_ship; ship; ship = next_ship )
    {
        next_ship = ship->next_in_room;
        ship_to_room( ship, ROOM_LIMBO_SHIPYARD );
    }

    // Move all the vehicles out of this room
    for ( vehicle = room->first_vehicle; vehicle; vehicle = next_vehicle )
    {
        next_vehicle = vehicle->next;
        vehicle_to_room( vehicle, ROOM_LIMBO_SHIPYARD );
    }

    // Remove all instances of furniture in the room
    for ( furn = room->first_furniture; furn; furn = next_furn )
    {
        next_furn = furn->next_in_room;
        remove_furniture_instance( furn );
    }

    // Axe the exits
    for ( ex = room->first_exit; ex; ex = next_ex )
    {
        next_ex = ex->next;
        extract_exit( room, ex );
    }

    // Nix the lprog
    if ( !NULLSTR( room->lprog_code ) )
    {
        LUA_PROGRAM* pLprog = get_room_lprog( room );
        if ( pLprog )
            lua_program_dispose( pLprog );
    }

    // Eliminate any global mprog runners tied to the room
    room_act_remove( room );

    MPSLEEP_DATA* mpsleep = NULL, *next_sleep = NULL;
    for ( mpsleep = first_mpsleep; mpsleep; mpsleep = next_sleep )
    {
        next_sleep = mpsleep->next;
        if ( mpsleep->type == MP_ROOM && mpsleep->room == room )
        {
            UNLINK( mpsleep, first_mpsleep, last_mpsleep, next, prev );
            SET_STRING( mpsleep->com_list, NULL );
            DISPOSE( mpsleep );            
        }
    }

    for ( pTurret = first_pturret; pTurret; pTurret = next_pTurret )
    {
        next_pTurret = pTurret->next;

        if ( pTurret->room == room )
        {
            UNLINK( pTurret, first_pturret, last_pturret, next, prev );
            FREE_STRUCT_NORET( pTurret, turret_fields );
        }
    }

    // If the room belongs to an enabled area, remove/unlink it from the linked list.
    // Note that ship/structure template rooms are deliberately left alone here.
    if ( room->area && room->area->enabled )
        UNLINK( room, first_room, last_room, next, prev );

    if ( room_map[room->vnum] && room_map[room->vnum] == room )
        room_map[room->vnum] = NULL;

    queue_extracted_room( room );
    --top_room;
    return E_LOTJ_SUCCESS;
}

int unload_rooms( AREA_DATA* area )
{
    ROOM_INDEX_DATA* room = NULL;
    int cnt = 0;

    if ( !area )
        return E_LOTJ_MISSING_ARGUMENTS;

    for ( int i = area->min_vnum; i <= area->max_vnum; i++ )
    {
        if ( ( room = room_map[i] ) != NULL && room->area == area )
        {
            unload_room( room );
            cnt++;
        }
    }

    return cnt;
}

// Function to delete an object index from the SQL database. - Nield 10/26/2024
int delete_obj( OBJ_INDEX_DATA* obj, bool clear_resets )
{
    char buf[MSL];

    if ( !obj )
        return E_LOTJ_MISSING_ARGUMENTS;

    snprintf( buf, MSL, "vnum = %d AND area = %s", obj->vnum, sql_escape_string( obj->area->shortname) );
    int result = delete_sql_by_where(DB_TABLE_OBJECTS, buf );
    unload_obj( obj, clear_resets );
    return result;
}

int unload_obj( OBJ_INDEX_DATA* obj, bool clear_resets )
{
    OBJ_DATA* tobj = NULL, *tobj_prev = NULL, *nobj = NULL, *nobj_prev = NULL, *xobj = NULL, *xobj_prev = NULL;
    EXTRA_DESCR_DATA* ed = NULL, *ted = NULL;
    MPROG_DATA* mp = NULL, *tmprog = NULL;
    CHAR_DATA* ch;
    BUFFER_DATA* buffer = NULL;

    if ( !obj )
        return E_LOTJ_MISSING_ARGUMENTS;

    /*
        Remove references to object index
    */
    for ( tobj = last_object; tobj; tobj = tobj_prev )
    {
        tobj_prev = tobj->prev;
        for ( nobj = tobj->last_content; nobj; nobj = nobj_prev )
        {
            nobj_prev = nobj->prev_content;

            for ( xobj = nobj->last_content; xobj; xobj = xobj_prev )
            {
                xobj_prev = xobj->prev_content;
                if ( xobj->pIndexData == obj )
                {
                    extract_obj( xobj );
                    xobj->pIndexData = NULL;
                }
            }

            if ( nobj->pIndexData == obj )
            {
                extract_obj( nobj );
                nobj->pIndexData = NULL;
            }
        }

        if ( tobj->pIndexData == obj )
        {
            extract_obj( tobj );
            tobj->pIndexData = NULL;
        }
    }

    lua_triggers_extract_subject( &obj->first_trigger, 0 );

    for ( ch = first_char; ch; ch = ch->next )
    {
        if ( ch->substate != SUB_OBJ_EXTRA && ch->substate != SUB_MPROG_EDIT )
            continue;

        buffer = ch->first_buffer;

        if ( !buffer )
            continue;

        tmprog = ( MPROG_DATA* )buffer->buf1;
        ted = buffer->ed;

        if ( ch->substate == SUB_OBJ_EXTRA && ted )
        {
            for ( ed = obj->first_extradesc; ed; ed = ed->next )
            {
                if ( ed == ted )
                {
                    ch_println( ch, "You suddenly forget which object you were editing!" );
                    stop_editing( ch, false );
                    ch->substate = SUB_NONE;
                    dispose_buffer( buffer );
                    break;
                }
            }
        }
        else if ( ch->substate == SUB_MPROG_EDIT && tmprog )
        {
            for ( mp = obj->first_mprog; mp; mp = mp->next )
            {
                if ( mp == tmprog )
                {
                    ch_println( ch, "You suddenly forget which object you were working on." );
                    stop_editing( ch, false );
                    ch->substate = SUB_NONE;
                    dispose_buffer( buffer );
                    break;
                }
            }
        }
    }

    if ( !NULLSTR( obj->lprog_code ) )
    {
        LUA_PROGRAM* pLprog = get_obj_proto_lprog( obj );

        if ( pLprog )
            lua_program_dispose( pLprog );
    }

    // If the object index belongs to an enabled area, remove/unlink it from the linked list.
    if ( obj->area && obj->area->enabled )
        UNLINK( obj, first_obj_index, last_obj_index, next, prev );

    if ( obj_map[obj->vnum] && obj_map[obj->vnum] == obj )
        obj_map[obj->vnum] = NULL;

    if ( clear_resets )
        delete_resets_for_obj( obj->vnum );
    else
        detach_resets_for_obj( obj->vnum );

    FREE_STRUCT( obj, obj_index_fields );
    --top_obj_index;
    return E_LOTJ_SUCCESS;
}

int unload_objects( AREA_DATA* area, bool clear_resets )
{
    OBJ_INDEX_DATA* obj = NULL;
    int cnt = 0;

    if ( !area )
