/*
    Create a new room (for online building)          -Thoric
*/
ROOM_INDEX_DATA* make_room( int vnum, bool save )
{
    ROOM_INDEX_DATA* pRoomIndex;
    CREATE( pRoomIndex, ROOM_INDEX_DATA, 1 );
    pRoomIndex->vnum = vnum;
    SET_STRING( pRoomIndex->name, "Floating in a void" );
    SET_STRING( pRoomIndex->description, "" );
    SET_STRING( pRoomIndex->nightdesc, "" );
    xSET_BIT( pRoomIndex->flags, ROOM_PROTOTYPE );
    pRoomIndex->sector_type = 1;
    CREATE( pRoomIndex->variable, VARIABLE_DATA, 1 );
    reset_variables( pRoomIndex, 0 );
    CREATE( pRoomIndex->vars, DVAR_LIST, 1 );
    LINK( pRoomIndex, first_room, last_room, next, prev );
    room_map[pRoomIndex->vnum] = pRoomIndex;
    pRoomIndex->minshipclass = FIGHTER_SHIP;
    pRoomIndex->maxshipclass = SATELLITE_SHIP;
    top_room++;
    pRoomIndex->area = area_from_vnum( pRoomIndex->vnum );
    pRoomIndex->on_ship = get_ship_from_vnum(pRoomIndex->vnum);
    if ( save ) save_room( pRoomIndex, true );
