        snprintf( buf, MSL, "A %s is here.", name );
        SET_STRING( pObjIndex->description, buf );
        SET_STRING( pObjIndex->action_desc, "" );
        pObjIndex->short_descr[0] = LOWER( pObjIndex->short_descr[0] );
        pObjIndex->description[0] = UPPER( pObjIndex->description[0] );
        SET_STRING( pObjIndex->obj_clan, "" );
        SET_STRING( pObjIndex->blueprint, "" );
        SET_STRING( pObjIndex->cybertype, "" );
        pObjIndex->item_type = ITEM_TRASH;
        xSET_BIT( pObjIndex->extra_flags, ITEM_PROTOTYPE );
        xCLEAR_BITS( pObjIndex->wear_flags );
        pObjIndex->value[0] = 0;
        pObjIndex->value[1] = 0;
        pObjIndex->value[2] = 0;
        pObjIndex->value[3] = 0;
        pObjIndex->value[4] = 0;
        pObjIndex->value[5] = 0;
        pObjIndex->weight = 1;
        pObjIndex->cost = 0;
    }
    else
    {
        EXTRA_DESCR_DATA* ed, *ced;
        AFFECT_DATA* paf, *cpaf;
        SET_STRING( pObjIndex->short_descr, cObjIndex->short_descr );
        SET_STRING( pObjIndex->description, cObjIndex->description );
        SET_STRING( pObjIndex->action_desc, cObjIndex->action_desc );
        SET_STRING( pObjIndex->obj_clan, cObjIndex->obj_clan );
        SET_STRING( pObjIndex->blueprint, cObjIndex->blueprint );
        SET_STRING( pObjIndex->cybertype, cObjIndex->cybertype );
        pObjIndex->item_type = cObjIndex->item_type;
        pObjIndex->extra_flags = cObjIndex->extra_flags;
        xSET_BIT( pObjIndex->extra_flags, ITEM_PROTOTYPE );
        pObjIndex->wear_flags = cObjIndex->wear_flags;
        pObjIndex->value[0] = cObjIndex->value[0];
        pObjIndex->value[1] = cObjIndex->value[1];
        pObjIndex->value[2] = cObjIndex->value[2];
        pObjIndex->value[3] = cObjIndex->value[3];
        pObjIndex->value[4] = cObjIndex->value[4];
        pObjIndex->value[5] = cObjIndex->value[5];
        pObjIndex->weight = cObjIndex->weight;
        pObjIndex->cost = cObjIndex->cost;

        for ( ced = cObjIndex->first_extradesc; ced; ced = ced->next )
        {
            CREATE( ed, EXTRA_DESCR_DATA, 1 );
            SET_STRING( ed->keyword, ced->keyword );
            SET_STRING( ed->description,ced->description );
            LINK( ed, pObjIndex->first_extradesc, pObjIndex->last_extradesc, next, prev );
            top_ed++;
        }

        for ( cpaf = cObjIndex->first_affect; cpaf; cpaf = cpaf->next )
        {
            CREATE( paf, AFFECT_DATA, 1 );
            paf->type = cpaf->type;
            paf->duration = cpaf->duration;
            paf->location = cpaf->location;
            paf->modifier = cpaf->modifier;
            paf->bitvector = cpaf->bitvector;
            LINK( paf, pObjIndex->first_affect, pObjIndex->last_affect, next, prev );
            top_affect++;
        }
    }

    pObjIndex->area = area_from_vnum( pObjIndex->vnum );
    pObjIndex->count = 0;
    LINK( pObjIndex, first_obj_index, last_obj_index, next, prev );
    obj_map[pObjIndex->vnum] = pObjIndex;
    top_obj_index++;
    if ( save ) save_object( pObjIndex, true );
    return pObjIndex;
}

