/*
    Creates a simple exit with no fields filled but rvnum and optionally
    to_room and vnum.                        -Thoric
    Exits are inserted into the linked list based on vdir.
*/
EXIT_DATA* make_exit( ROOM_INDEX_DATA* pRoomIndex, ROOM_INDEX_DATA* to_room, sh_int door )
{
    EXIT_DATA* pexit, *texit;
    bool broke;
    CREATE( pexit, EXIT_DATA, 1 );
    pexit->vdir = door;
    pexit->rvnum = pRoomIndex->vnum;
    pexit->to_room = to_room;
    pexit->distance = 1;

    if ( to_room )
    {
        pexit->vnum = to_room->vnum;
        texit = get_exit_to( to_room, rev_dir[door], pRoomIndex->vnum );

        if ( texit ) /* assign reverse exit pointers */
        {
            texit->rexit = pexit;
            pexit->rexit = texit;
        }
    }

    broke = FALSE;

    for ( texit = pRoomIndex->first_exit; texit; texit = texit->next )
        if ( door < texit->vdir )
        {
            broke = TRUE;
            break;
        }

    if ( !pRoomIndex->first_exit )
        pRoomIndex->first_exit = pexit;
    else
    {
        /*
            keep exits in incremental order - insert exit into list
        */
        if ( broke && texit )
        {
            if ( !texit->prev )
                pRoomIndex->first_exit = pexit;
            else
                texit->prev->next = pexit;

            pexit->prev = texit->prev;
            pexit->next = texit;
            texit->prev = pexit;
            top_exit++;
            return pexit;
        }

        pRoomIndex->last_exit->next = pexit;
    }

    pexit->next = NULL;
    pexit->prev = pRoomIndex->last_exit;
    pRoomIndex->last_exit = pexit;
    top_exit++;
    save_room( pRoomIndex, true );
    save_room( to_room, true );
    return pexit;
}

void fix_area_exits( AREA_DATA* tarea )
{
    ROOM_INDEX_DATA* pRoomIndex;
    EXIT_DATA* pexit, *rev_exit;
    int rnum;
    bool fexit;

    for ( rnum = tarea->min_vnum; rnum <= tarea->max_vnum; rnum++ )
    {
        if ( ( pRoomIndex = get_room_index( rnum ) ) == NULL )
            continue;

        fexit = FALSE;

        for ( pexit = pRoomIndex->first_exit; pexit; pexit = pexit->next )
        {
            fexit = TRUE;
            pexit->rvnum = pRoomIndex->vnum;

            if ( pexit->vnum <= 0 )
                pexit->to_room = NULL;
            else
                pexit->to_room = get_room_index( pexit->vnum );
        }

        if ( !fexit )
            xSET_BIT( pRoomIndex->flags, ROOM_NO_MOB );
    }

    for ( rnum = tarea->min_vnum; rnum <= tarea->max_vnum; rnum++ )
    {
        if ( ( pRoomIndex = get_room_index( rnum ) ) == NULL )
            continue;

        for ( pexit = pRoomIndex->first_exit; pexit; pexit = pexit->next )
        {
            if ( pexit->to_room && !pexit->rexit )
            {
                rev_exit = get_exit_to( pexit->to_room, rev_dir[pexit->vdir], pRoomIndex->vnum );

                if ( rev_exit )
                {
                    pexit->rexit = rev_exit;
                    rev_exit->rexit = pexit;
                }
            }
        }
    }
}

/*
    Display vnums currently assigned to areas        -Altrag & Thoric
    Sorted, and flagged if loaded.
*/
void show_vnums( CHAR_DATA* ch, int low, int high )
{
    AREA_DATA* pArea;
    int count = 0, loaded = 0, unloaded = 0;

    for ( pArea = first_area; pArea; pArea = pArea->next )
    {
        if ( pArea->min_vnum < low )
            continue;

        if ( pArea->max_vnum > high )
            continue;

        if ( xIS_SET( pArea->flags, AFLAG_HIDE ) && get_trust( ch ) < LEVEL_PR_ADMIN )
            continue;

        loaded++;
        count++;

        ch_println( ch, "&B%-25s &z| V: &Y%-2d &zRange: &C%10d - %-10d",
        ( pArea->shortname ? pArea->shortname : "&R(invalid)" ), pArea->version, pArea->min_vnum, pArea->max_vnum );
    }

    for ( pArea = first_area_archive; pArea; pArea = pArea->next )
    {
        if ( pArea->min_vnum < low )
            continue;

        if ( pArea->max_vnum > high )
            continue;

        if ( xIS_SET( pArea->flags, AFLAG_HIDE ) && get_trust( ch ) < LEVEL_PR_ADMIN )
            continue;

        unloaded++;
        count++;

        ch_println( ch, "&r%-25s &z| V: &Y%-2d &zRange: &C%10d - %-10d",
                   ( pArea->shortname ? pArea->shortname : "&R(invalid)" ),
                   pArea->version, pArea->min_vnum, pArea->max_vnum );
    }

    ch_println( ch, "&zAreas listed: &C%d &zLoaded: &G%d &zUnloaded: &R%d &z(Current version: &Y%d&z)", count, loaded, unloaded, AREA_VERSION );
    return;
}

/*
    Shows prototype vnums ranges, and if loaded
*/
CMDF do_vnums( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    int low, high;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    low = 0;
    high = MAX_VNUMS;

    if ( !NULLSTR( arg1 ) )
    {
        low = atoi( arg1 );

        if ( !NULLSTR( arg2 ) )
            high = atoi( arg2 );
    }

    show_vnums( ch, low, high );
}

