char* JSON_print_helper( const cJSON *root, bool formatted )
{
    static char* buffers[MAX_POOL];
    static int count = -1;

    if ( !root )
        return "";

    count++;
    count %= MAX_POOL;
    char** buf = &( buffers[count] );

    if ( *buf )
        free( *buf );

    *buf = formatted ? cJSON_Print(root) : cJSON_PrintUnformatted( root );
    return *buf;
}

