/* Check to make sure range of vnums is free - Scryn 2/27/96 */

CMDF do_check_vnums( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    argument = one_argument( argument, arg1 );

    if ( !is_number( arg1 ) || !is_number( argument ) )
    {
        ch_println( ch, "&zSyntax: &Ccheckvnums <&wlow vnum&C> <&whigh vnum&C>" );
        return;
    }

    int low = atoi( arg1 );
    int high = atoi( argument );

    for ( AREA_DATA* area = first_area; area; area = area->next )
    {
        if ( area->min_vnum <= high && area->max_vnum >= low )
        {
            ch_println( ch, "Conflict: %-25s | %10d - %-10d",
                area->shortname ? area->shortname : "(invalid)",
                area->min_vnum, area->max_vnum );
        }
    }
    return;
}

