char* rem_word( char* str, char* word )
{
    char buf[MSL];
    static char output[MSL];
    strlcpy( output, "", MSL );

    while ( str[0] != '\0' )
    {
        str = one_argument( str, buf );

        if ( str_cmp( buf, word ) )
        {
            if ( strstr( buf, " " ) )
                strlcat( output, "'", MSL );

            strlcat( output, buf, MSL );

            if ( strstr( buf, " " ) )
                strlcat( output, "'", MSL );

            strlcat( output, " ", MSL );
        }
    }

    return output;
}

/* Provided by Greven. Originally from AFKMud. */

/*  changetarg: extract a single argument (with given max length) from
    argument to arg; if arg==NULL, just skip an arg, don't copy it out
*/
const char* getarg( const char* argument, char* arg, int length )
{
    int len = 0;

    if ( !argument || argument[0] == '\0' )
    {
        if ( arg )
            arg[0] = '\0';

        return argument;
    }

    while ( *argument && isspace( *argument ) )
        argument++;

    if ( arg )
        while ( *argument && !isspace( *argument ) && len < length - 1 )
            *arg++ = *argument++, len++;
    else
        while ( *argument && !isspace( *argument ) )
            argument++;

    while ( *argument && !isspace( *argument ) )
        argument++;

    while ( *argument && isspace( *argument ) )
        argument++;

    if ( arg )
        *arg = '\0';

    return argument;
}

/* Check for a name in a list */
int hasname( const char* list, const char* name )
{
    const char* p;
    char arg[MIL];

    if ( NULLSTR( list ) || NULLSTR( name ) )
        return 0;

    p = getarg( list, arg, MIL );

    while ( arg[0] )
    {
        if ( !strcmp( name, arg ) )
            return 1;

        p = getarg( p, arg, MIL );
    }

    return 0;
}

/* Add a name to a list */
void addname( char** list, const char* name )
{
    char buf[MSL];

    if ( hasname( *list, name ) )
        return;

    if ( *list && *list[0] != '\0' )
        snprintf( buf, MSL, "%s %s", *list, name );
    else
        strlcpy( buf, name, MSL );

    SET_STRING( *list, buf );
}

/* Remove a name from a list */
void removename( char** list, const char* name )
{
    char buf[MSL];
    char arg[MIL];
    const char* p;
    buf[0] = '\0';
    p = getarg( *list, arg, MIL );

    while ( arg[0] )
    {
        if ( strcmp( arg, name ) )
        {
            if ( buf[0] )
                strlcat( buf, " ", MSL );

            strlcat( buf, arg, MSL );
        }

        p = getarg( p, arg, MIL );
    }

    SET_STRING( *list, buf );
}

int is_valid_utf_8(const unsigned char *bytes, int length)
{
    if (!bytes || length == 0)
        return 0;

    unsigned char lead = bytes[0];

    // Printable ASCII and selected control characters
    if (lead <= 0x7F)
    {
        if (lead < 0x20 && lead != '\n' && lead != '\r' && lead != '\t')
            return 0;
        return 1;
    }

    // Two-byte sequence
    if ((lead >> 5) == 0x06 && length >= 2)
    {
        unsigned char b1 = bytes[1];
        int codepoint = ((lead & 0x1F) << 6) | (b1 & 0x3F);
        if ((b1 >> 6) == 0x02 && codepoint >= 0x80)
            return 2;
    }

    // Three-byte sequence
    if ((lead >> 4) == 0x0E && length >= 3)
    {
        unsigned char b1 = bytes[1], b2 = bytes[2];
        int codepoint = ((lead & 0x0F) << 12) |
                        ((b1 & 0x3F) << 6) |
                        (b2 & 0x3F);
        if ((b1 >> 6) == 0x02 && (b2 >> 6) == 0x02 &&
            codepoint >= 0x800 &&
            !(codepoint >= 0xD800 && codepoint <= 0xDFFF))
            return 3;
    }

    // Four-byte sequence
    if ((lead >> 3) == 0x1E && length >= 4)
    {
        unsigned char b1 = bytes[1], b2 = bytes[2], b3 = bytes[3];
        int codepoint = ((lead & 0x07) << 18) |
                        ((b1 & 0x3F) << 12) |
                        ((b2 & 0x3F) << 6) |
                        (b3 & 0x3F);
        if ((b1 >> 6) == 0x02 && (b2 >> 6) == 0x02 && (b3 >> 6) == 0x02 &&
            codepoint >= 0x10000 && codepoint <= 0x10FFFF)
            return 4;
    }

    return 0;
}


char* remove_invalid_utf_8( const char *source )
{
    static char* buffers[MAX_POOL];
    static int count = -1;

     if ( !source )
        return NULL;

    if ( dump_mem_on_shutdown && source == memdebug_signal )
    {
        cleanup_static_pool( buffers );
        return NULL;
    }

    count++;
    count %= MAX_POOL;
    char** buf = &( buffers[count] );

    if ( *buf )
    {
        free( *buf );
        *buf = NULL;
    }

    int len = strlen( source );
    *buf = malloc( len + 1 );
    memset( *buf, '\0', len + 1 );
    int i = 0, j = 0;
    while ( i < len )
    {
        int charLen = is_valid_utf_8( ( unsigned char * ) &source[i], len - i );
        if ( charLen > 0 )
        {
            memcpy(&(*buf)[j], &source[i], charLen);
            i += charLen;
            j += charLen;
        }
        else
            i++; // Skip invalid byte
    }

    (*buf)[j] = '\0'; // Null-terminate the result string
    return *buf;
}

