bool save_race( RACE_DATA *race )
{
    int res = 0;

    if ( NULLSTR( race->race_name ) )
    {
        bug( "%s: Race %d has null name, not writing to database.", FUNC, race->id );
        return FALSE;
    }

    if ( !str_cmp( race->race_name, "unused" ) )
        return FALSE; // Skip these

    cJSON *abilObj = cJSON_CreateObject();
    cJSON *mainObj = cJSON_CreateObject();
    for ( int abil = 0; abil < MAX_ABILITY; abil++ )
    {
        cJSON_AddItemToObject( abilObj, itoa( abil ), cJSON_CreateNumber(race->ability[abil] ) );

        cJSON *tempMainObj = cJSON_CreateObject();
        for (int mainabil = 0; mainabil < MAX_ABILITY; mainabil++)
            cJSON_AddItemToObject(tempMainObj, itoa( mainabil ), cJSON_CreateNumber(race->main_table[abil][mainabil]));
        cJSON_AddItemToObject(mainObj, itoa( abil ), tempMainObj);
    }

    if( race->ability_json )
        free( race->ability_json );

    race->ability_json = cJSON_Print( abilObj );

    if ( race->main_table_json )
        free( race->main_table_json );

    race->main_table_json = cJSON_Print( mainObj );
    res = upsert_sql_fieldmap_row(DB_TABLE_RACES, race, race_fields, NO_FLAG);
    cJSON_Delete( abilObj );
    cJSON_Delete( mainObj );
    return res;
}

int load_race_sql( const PGresult* res, int row )
{
    RACE_DATA *race = NULL;
    int rval;
    CREATE(race, RACE_DATA, 1);
    if ( ( rval = fieldmap_postgres_row(res, row, race, race_fields)) != E_LOTJ_SUCCESS)
    {
        FREE_STRUCT( race, race_fields );
        return rval;
    }

    RACE_COUNTER++;


    // Deserialize the JSON strings for abilities and main_table
    cJSON *ability_json = cJSON_Parse(race->ability_json);
    for (int abil = 0; abil < MAX_ABILITY; abil++)
    {
        cJSON *item = cJSON_GetObjectItem(ability_json, itoa(abil));
        if (item)
            race->ability[abil] = item->valueint;
    }
    cJSON_Delete(ability_json);

    cJSON *main_table_json = cJSON_Parse(race->main_table_json);
    for (int abil = 0; abil < MAX_ABILITY; abil++)
    {
        cJSON *tempMainObj = cJSON_GetObjectItem(main_table_json, itoa(abil));
        if (tempMainObj)
        {
            for (int mainabil = 0; mainabil < MAX_ABILITY; mainabil++)
            {
                cJSON *item = cJSON_GetObjectItem(tempMainObj, itoa(mainabil));
                if (item)
                    race->main_table[abil][mainabil] = item->valueint;
            }
        }
    }
    cJSON_Delete(main_table_json);

    LINK(race, first_race, last_race, next, prev);
   // boot_log("Loaded race %s (%d) from SQL database", race->race_name, race->id);

    return E_LOTJ_SUCCESS;
}

