#ifdef HARDGDB
// * If you don't have this, you do now * //
char* fgetf( char* s, int n, register FILE* iop )
{
    register int c;
    register char* cs;
    c = '\0';
    cs = s;

    while ( --n > 0 && ( c = getc( iop ) ) != EOF )
        if ( ( *cs++ = c ) == '\0' )
            break;

    *cs = '\0';
    return ( ( c == EOF && cs == s ) ? NULL : s );
}


