    snprintf( arg, 5000, "gdb -se ../src/%s -c %d -q -x ~/mp/src/gdb.dat", sysdata.exe_name, ( int )getpid(  ) );
    fp = popen( arg, "r" );
    fgetf( buf, 5000, fp );
