static void error_callback(void *data __attribute__((unused)), const char *msg, int errnum) {
    fprintf(stderr, "libbacktrace error: %s (%d)\n", msg, errnum);
}

static int full_callback(void *data, uintptr_t pc, const char *filename, int lineno, const char *function) {
    char *buf = (char *)data;
    char line_info[256];
    if (function && filename) {
        snprintf(line_info, sizeof(line_info), "%s() in %s:%d\n", function, filename, lineno);
    } else if (function) {
        snprintf(line_info, sizeof(line_info), "%s()\n", function);
    } else {
        snprintf(line_info, sizeof(line_info), "0x%lx\n", (long)pc);
    }
    strlcat(buf, line_info, MSL - strlen(buf) - 1);
    return 0;  // continue
}

void capturebacktrace(const char* type, siginfo_t *info, void* ucontext) {
    char buf[MIL], buf2[SUB_MSL], buf3[MSL];
    // // Mud backtrace.
    if ( is_not_production() || sysdata.backtrace_enabled )
    {
        int timestamp = (int)time( 0 );
        char buffer[BUF1K] = "no context";
        if(ucontext && info) {

            // let's get some stack info
            ucontext_t *context = (ucontext_t *)ucontext;

            size_t offset = 0;

            // Start with the fault address
            int is_null = (unsigned long)info->si_addr < 0x1000;
            offset += snprintf(buffer + offset, BUF1K - offset,
                            "Fault address: %p%s\n", info->si_addr, 
                            is_null ? " (probably NULL or invalid)" : "");

            // Check architecture and append all general-purpose registers
            #if defined(__x86_64__)
                offset += snprintf(buffer + offset, BUF1K - offset, "RIP: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RIP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RSP: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RSP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RBP: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RBP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RAX: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RAX]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RBX: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RBX]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RCX: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RCX]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RDX: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RDX]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RSI: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RSI]);
                offset += snprintf(buffer + offset, BUF1K - offset, "RDI: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_RDI]);
                offset += snprintf(buffer + offset, BUF1K - offset, "R8 : %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_R8]);
                offset += snprintf(buffer + offset, BUF1K - offset, "R9 : %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_R9]);
