                offset += snprintf(buffer + offset, BUF1K - offset, "R15: %llx\n", (unsigned long long)context->uc_mcontext.gregs[REG_R15]);
            #elif defined(__i386__)
                offset += snprintf(buffer + offset, BUF1K - offset, "EIP: %x\n", context->uc_mcontext.gregs[REG_EIP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "ESP: %x\n", context->uc_mcontext.gregs[REG_ESP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "EBP: %x\n", context->uc_mcontext.gregs[REG_EBP]);
                offset += snprintf(buffer + offset, BUF1K - offset, "EAX: %x\n", context->uc_mcontext.gregs[REG_EAX]);
