                offset += snprintf(buffer + offset, BUF1K - offset, "EDI: %x\n", context->uc_mcontext.gregs[REG_EDI]);
            #elif defined(__arm__)
                offset += snprintf(buffer + offset, BUF1K - offset, "R0 : %lx\n", context->uc_mcontext.arm_r0);
                offset += snprintf(buffer + offset, BUF1K - offset, "R1 : %lx\n", context->uc_mcontext.arm_r1);
                offset += snprintf(buffer + offset, BUF1K - offset, "R2 : %lx\n", context->uc_mcontext.arm_r2);
                offset += snprintf(buffer + offset, BUF1K - offset, "R3 : %lx\n", context->uc_mcontext.arm_r3);
