                offset += snprintf(buffer + offset, BUF1K - offset, "PC : %lx\n", context->uc_mcontext.arm_pc);
            #elif defined(__aarch64__)
                for (int i = 0; i < 31; i++) {
                    offset += snprintf(buffer + offset, BUF1K - offset, "X[%d]: %llx\n", i, (unsigned long long)context->uc_mcontext.regs[i]);
                }
                offset += snprintf(buffer + offset, BUF1K - offset, "SP: %llx\n", (unsigned long long)context->uc_mcontext.sp);
                offset += snprintf(buffer + offset, BUF1K - offset, "PC: %llx\n", (unsigned long long)context->uc_mcontext.pc);
            #else
                snprintf(buffer + offset, BUF1K - offset, "Unsupported architecture.\n");
            #endif
        }


        const char* backtrace = MudBackTrace();
        snprintf( buf, MIL, "%s%d", BACKTRACE_DIR, timestamp );
        snprintf( buf2, SUB_MSL, "BINARY: %s\nLAST_PLAYER_COMMAND: %s\nFIELD_STACK: %s\nSTACK:\n%s\n#BACKTRACE V0\nTIMESTAMP: %d\nGIT_SHORT_HASH: %s\nTYPE: %s\nBACKTRACE:\n%s#END\nLUA:%s\n\r#END\n", sysdata.exe_file,lastplayercmd, get_field_stack(), buffer, timestamp, GIT_SHORT_HASH, type, backtrace, lua_debug_info(NULL) );

        FILE* fp = fopen( buf, "w" );

        if ( !fp )
        {
            bug( "Could not open backtrace file!" );
        }
        else
        {
            fprintf( fp, "%s", buf2 );
            fclose( fp );
        }
        snprintf( buf3, MSL, "```%s```", buf2 );

        //firehose_write_b64sendtodiscordchan("coding",buf3);
        discord_sendchan(DISCORD_CODING_EMERG, buf3);
        fprintf(stderr,  "\n\r%s", buf2 );
    }
}

char* MudBackTrace(void) {
    static char mybugbuf[MSL];
    struct backtrace_state *state;

    mybugbuf[0] = '\0';
    state = backtrace_create_state(NULL, 1, error_callback, NULL);
    if (!state) {
        return "Failed to create backtrace state!";
    }

    backtrace_full(state, 0, full_callback, error_callback, mybugbuf);
    return mybugbuf;
}

void check_timeprogs( void )
{
    TIMEPROG_DATA* tp = NULL, *next_tp = NULL;

    for ( tp = first_timeprog; tp; tp = next_tp )
    {
        next_tp = tp->next;

        if ( tp->room )
        {
            if ( tp->room->tmprog == tp )
            {
                rset_supermob( tp->room );
                rprog_time_check( supermob, NULL, NULL, tp->room, TIME_PROG );
                release_supermob();

                if ( room_extracted( tp->room ) )
                    continue;

                rset_supermob( tp->room );
                rprog_time_check( supermob, NULL, NULL, tp->room, HOUR_PROG );
                release_supermob( );
            }
            else if ( tp->room->tlprog == tp )
                lua_trigger_on_room_time( tp->room );
        }
        else if ( tp->tch )
        {
            if ( tp->tch->tmprog == tp )
            {
                mprog_time_trigger( tp->tch );

                if ( char_extracted( tp->tch ) )
                    continue;

                mprog_hour_trigger( tp->tch );
            }
            else if ( tp->tch->tlprog == tp )
                lua_trigger_on_ch_time( tp->tch );
        }
        else if ( tp->tobj && tp->tobj->tlprog == tp )
            lua_trigger_on_obj_time( tp->tobj );
    }
}

