char* strip_apost( char* str )
{
    static char newstr[MSL];
    int i, j;

    if ( !str || str[0] == '\0' )
    {
        newstr[0] = '\0';
        return newstr;
    }

    for ( i = j = 0; str[i] != '\0'; i++ )
        if ( str[i] != '\'' )
        {
            newstr[j++] = str[i];
        }

    newstr[j] = '\0';
    return newstr;
}

void load_lua_progs()
{
    if ( lprogs_disabled() )
    {
        lognormal( "Lua programs disabled by environment..." );
        return;
    }

    lognormal( "Loading lua progs..." );
    int cnt = 0, rcnt = 0;
    ROOM_INDEX_DATA* room = NULL;
    LUA_PROGRAM* lprog = NULL;

    for ( room = first_room; room; room = room->next )
    {
        if ( !NULLSTR( room->lprog_code ) )
        {
            LUA_PARAM params[] =
            {
                { .type = LUA_PARAM_ROOM, .payload = ( void* ) room, .global_name = "self"},
                { .type = LUA_PARAM_LAST }
            };
            lprog = lua_load_from_buffer( room_lprog_identifier( room ), room->lprog_code, NULL, params );
            if ( lprog )
            {
                lprog->room = room;
                cnt++;
            }
        }
    }

    lognormal( "Loaded %d room lprogs.", cnt );
    cnt = 0;

    for ( SHIP_TEMPLATE_DATA* template = first_shipimage; template; template = template->next )
    {
        if ( !NULLSTR( template->lprog_code ) )
        {
            LUA_PARAM params[] = {{ .type = LUA_PARAM_SHIP_TEMPLATE, .payload = ( void* ) template, .global_name = "self"},
                { .type = LUA_PARAM_LAST }
            };
            lprog = lua_load_from_buffer( ship_lprog_identifier( template ), template->lprog_code, NULL, params );
            if ( lprog )
            {
                lprog->ship = template;
                cnt++;
            }
        }

        rcnt += init_room_lprogs( template->first_room );
    }

    lognormal( "Loaded %d ship template lprogs.", cnt );
    lognormal( "Loaded %d ship template room lprogs.", rcnt );
    cnt = 0;
    rcnt = 0;

    for ( STRUCTURE_TEMPLATE_DATA* strct = first_structure_template; strct; strct = strct->next )
        rcnt += init_room_lprogs( strct->first_room );

    lognormal( "Loaded %d structure template room lprogs.", rcnt );

    MOB_INDEX_DATA* pMobIndex;

    for ( pMobIndex = first_mob_index; pMobIndex; pMobIndex = pMobIndex->next )
    {
        if ( !NULLSTR( pMobIndex->lprog_code ) )
        {
            LUA_PARAM params[] =
            {
                { .type = LUA_PARAM_CHAR_PROTO, .payload = ( void* ) pMobIndex, .global_name = "self"},
                { .type = LUA_PARAM_LAST }
            };
            lprog = lua_load_from_buffer( ch_proto_lprog_identifier( pMobIndex ), pMobIndex->lprog_code, NULL, params );
            if ( lprog )
            {
                lprog->mob = pMobIndex;
                cnt++;
            }
        }
    }

    lognormal( "Loaded %d mob index lprogs.", cnt );
    cnt = 0;
    OBJ_INDEX_DATA* pObjIndex;

    for ( pObjIndex = first_obj_index; pObjIndex; pObjIndex = pObjIndex->next )
    {
        if ( !NULLSTR( pObjIndex->lprog_code ) )
        {
            LUA_PARAM params[] =
            {
                { .type = LUA_PARAM_OBJ_PROTO, .payload = ( void* ) pObjIndex, .global_name = "self"},
                { .type = LUA_PARAM_LAST }
            };
            lprog = lua_load_from_buffer( obj_proto_lprog_identifier( pObjIndex ), pObjIndex->lprog_code, NULL, params );
            if ( lprog )
            {
                lprog->obj = pObjIndex;                    
                cnt++;
            }
        }
    }

    lognormal( "Loaded %d object index lprogs.", cnt );
    // This must happen near the end of initialization, once all template lprogs have been loaded.
    SHIP_DATA* next;

    for ( SHIP_DATA* ship = first_ship; ship; ship = next )
    {
        next = ship->next;

        if ( ship->starsystem && ship->spawn_id > 0 )
            lua_trigger_ship_spawned( ship );
    }

    lognormal( "Lua loading complete." );
}

int save_autocorrect( AUTOCORRECT_DATA* ac )
{
    return upsert_sql_fieldmap_row( DB_TABLE_AUTOCORRECT, ac, autocorrect_fields, NO_FLAG );
}

int delete_autocorrect( AUTOCORRECT_DATA* ac )
{
    char filter[MIL];
    snprintf(filter, MIL, "typo = %s", sql_escape_string(ac->typo));
    int rval = delete_sql_by_where(DB_TABLE_AUTOCORRECT, filter);
    if (rval != E_LOTJ_SUCCESS)
    {
        bug("failed to delete autocorrect: %s", lotj_strerror(rval));
        return rval;
    }

    UNLINK( ac, first_autocorrect, last_autocorrect, next, prev );
    FREE_STRUCT( ac, autocorrect_fields );
    return E_LOTJ_SUCCESS;
}

int load_autocorrect_row( const PGresult* res, int row )
{
    AUTOCORRECT_DATA* ac;
    int rval;

    CREATE( ac, AUTOCORRECT_DATA, 1 );

    if ( ( rval = fieldmap_postgres_row( res, row, ac, autocorrect_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( ac, autocorrect_fields );
        return rval;
    }

    LINK( ac, first_autocorrect, last_autocorrect, next, prev );
    return E_LOTJ_SUCCESS;
}

// Alphabetize function, used mainly by SORT_ARRAY for arrays made with LINK_TO_ARRAY
bool alphabetize( const char* Astr, const char* Bstr )
{
    if ( NULLSTR( Astr ) || NULLSTR( Bstr ) )
        return false;

    return ( strcasecmp( Astr, Bstr ) >= 0 );
}

// Sort by number (descending, typical), also used mainly by SORT_ARRAY for arrays made with LINK_TO_ARRAY
bool number_sort_descending( int a, int b )
{    
    return( a <= b );
}

// Sort by number (ascending, atypical), also used mainly by SORT_ARRAY for arrays made with LINK_TO_ARRAY
bool number_sort_ascending( int a, int b )
{    
    return( a >= b );
}

int numPlaces( int n )
{
    if ( n == 0 )
        return 1;

    return floor (log10 (abs (n))) + 1;
}

DB_DATA* get_db_from_id( int id, DB_DATA* first_db, DB_DATA* last_db )
{
    DB_DATA* result = NULL;
    if ( !first_db && !last_db )
        return NULL;

    for ( result = last_db ? last_db : first_db; result; result = last_db ? result->prev : result->next )
        if ( result->id == id )
            break;

    return result;
}

/**
 * @brief Duplicates an existing area structure
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us duplicate an existing area, assigning a new shortname (formerly
 * filename) to the new area to prevent conflicts. This facilitates editing
 * areas, version control, etc. It is also used in the process of moving an
 * area from one vnum range to another.
 * 
 * This function does not duplicate the rooms, mob indices, or object indices
 * associated with an area. It only duplicates the area structure itself, so
 * the calling function must separately invoke the other duplication functions.
 * 
 * @param source The area being duplicated.
 * @param shortname The shortname to assign to the new area.
 * @return Pointer to newly created area.
 */
AREA_DATA* duplicate_area( AREA_DATA* source, const char* shortname )
{
    // If we don't have an area to duplicate, we can't proceed.
    if ( !source )
    {
        bug( "%s: NULL area", FUNC );
        return NULL;
    }

    // If we don't have a new shortname to assign to the area, we can't proceed.
    if ( NULLSTR( shortname ) )
    {
        bug( "%s: NULL shortname", FUNC );
        return NULL;
    }


    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;

    // We start by querying the database to pull the original area being duplicated.
    /* NOTE: we don't use an area struct already loaded into memory because we
       don't currently have a clean way to duplicate an entire structure -- together
       with member pointers to dynamically allocated memory -- in-game. It's substantially
       easier to use our existing fieldmaps implementation to just load and rehydrate a
       new structure from the database. */
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE shortname = %s", DB_TABLE_AREAS, sql_escape_string(source->shortname) );
    qresult = query_db( selectquery );
    rows = PQntuples(qresult);

    /* It should never be the case that we don't get a return value from the DB since
       we're loading a copy of an area that already exists in game memory. But safety first... */
    if ( qresult == NULL || rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return NULL;
    }

    // Assuming we've gotten a match from the DB, create the new area struct to load the data into 
    AREA_DATA* area = NULL;
    CREATE( area, AREA_DATA, 1 );

    // Load the data into it.
    if ( ( rval = fieldmap_postgres_row( qresult, row, area, area_fields ) ) != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to load area %s, err: %s", FUNC, source->shortname, lotj_strerror( rval ) );
        FREE_STRUCT_NORET( area, area_fields );
        if ( qresult ) PQclear( qresult );
        return NULL;
    }

    // Assign the new shortname so we don't have a unique value conflict when this new area gets saved.
    SET_STRING( area->shortname, shortname );

    // Remember to set the id to 0 so that we don't accidentally overwrite the original area when this gets saved.
    area->id = 0;
    if ( qresult ) PQclear( qresult );

    /* Return the area without saving it. It's the calling function's responsibility to save this new struct if it
       chooses to. */
    return area;
}

/**
 * @brief Copies the rooms from one area into another
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us copy the rooms from one area into another. This is a key
 * component of the area migration system that lets us move areas from
 * the BP to the MP (and vice-versa). If the destination area is enabled,
 * this function will facilitate "hot-swapping" the rooms while the game
 * is live, remapping pointers from the old room to the new room, moving
 * nested content (characters, objects, ships, vehicles, phomes, etc.),
 * and so on.
 * 
 * @param source The area whose rooms are being drawn from.
 * @param dest The area to which the new rooms are being attached.
 * @param db The enum value assigned to the DB being read from.
 * @param offset The +/- modifier for VNums if the destination area has a different VNum range.
 * @param cnt A pointer to an int counter provided by the calling function.
 * @return The resulting status (error or success) code.
 */
int duplicate_rooms( AREA_DATA* source, AREA_DATA* dest, int db, int offset, int* cnt )
{
    // If the source area doesnt exist, can't proceed.
    if ( !source )
    {
        bug( "%s: NULL source area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    // If the destination area doesn't exist, can't proceed.
    if ( !dest )
    {
        bug( "%s: NULL destination area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    /* If the enum value doesn't match with a DB being read from, can't proceed.
       Note that I'm envisioning this expanding to encompass more than two DBs
       if, say, we had a sandbox running in tandem or something. That's why I
       went with the enum approach. */
    if ( db < MAIN_DB || db > ALT_DB )
    {
        bug( "%s: invalid database", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    /* The source and destination area structs can (and should) be the same only
       if we're pulling from the other environment. This is because the calling
       function has already created a new area structure when importing from
       the alt DB. Otherwise, this function is meant to let us copy rooms to
       new areas within the same environment. */
    if ( db == MAIN_DB && source == dest )
    {
        bug( "%s: source and destination areas are the same", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    // Start by pulling the rooms from the appropriate DB
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    TURRET_DATA* pturret = NULL;
    ROOM_INDEX_DATA* room = NULL, *xroom = NULL;
    MPROG_DATA* mprog = NULL;
    TIMEPROG_DATA* tp = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE vnum BETWEEN %d AND %d AND area = %s", DB_TABLE_ROOMS, source->min_vnum, source->max_vnum, sql_escape_string(source->shortname) );
    qresult = db == MAIN_DB ? query_db( selectquery ) : query_alt_db( selectquery );
    rows = PQntuples(qresult);

    /* If we don't get a return from the SQL query at all, something's gone wrong.
    Flag as an error -- which will, in turn, cause the calling function to
    abort the entire migration and SQL transaction, forcing a copyover and restoring
    the status quo from before this function ran. */ 
    if ( qresult == NULL )
        return E_LOTJ_LOAD_ERROR;

    /* If the query succeeds but we simply didn't get any rooms, that's not necessarily an error.
       Some areas may not have rooms (e.g., object-heavy dev-specific areas), so we want the
       calling migration function to continue. Return success. */ 
    if ( rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    // Start iterating through all the rooms we just pulled from the DB.
    for ( row = 0; row < rows; row++ )
    {
        // Create a new room for each.
        CREATE( room, ROOM_INDEX_DATA, 1 );

        // Map the data pulled from the DB to the new room struct.
        if ( ( rval = fieldmap_postgres_row( qresult, row, room, room_index_fields ) ) != E_LOTJ_SUCCESS )
        {
            FREE_STRUCT( room, room_index_fields );
            continue;
        }

        /* Always make sure this stupid variable_data member is allocated. One day I'll make this
           static instead of dynamically allocated. One day... but not today. */
        if ( room->variable == NULL )
        {
            VARIABLE_DATA* variable = NULL;
            CREATE( variable, VARIABLE_DATA, 1 );
            room->variable = variable;
        }

        // If this room is supposed to have a phome data structure, make sure it still does.
        if ( xIS_SET( room->flags, ROOM_EMPTY_HOME ) && !room->phome )
        {
            PHOME_DATA* home = NULL;
            CREATE( home, PHOME_DATA, 1 );
            SET_STRING( home->owner, "" );
            home->price = PHOME_DEFAULT_PRICE;
            room->phome = home;
        }

        // If there's a phome loaded in, make sure the reverse pointer is set up.
        if ( room->phome )
            room->phome->room = room;

        // If this room is supposed to have a clan pad structure but doesn't, call a function that'll create it.
        if ( ( xIS_SET( room->flags, ROOM_CLANPAD ) || xIS_SET( room->flags, ROOM_CLANHANGAR ) ) && !room->pad )
            get_pad_from_room( room );


        // Manually map the mprog types. This is old sorcery that's best left alone.
        for ( MPROG_DATA* mprog = room->first_mprog; mprog; mprog = mprog->next )
            room->progtypes = room->progtypes | mprog->type;


        /* This is where the magic starts to happen. If the destination area is enabled, that
        means that we're doing a hotswap, loading new rooms in the place of old while the game
        is still live and subbing them into place. Start by trying to find the old room.

        NOTE: We need to load the old room before we start applying vnum offsets, because otherwise
        we won't find the old room -- or worse, we'll find the wrong one.  */ 
        if ( dest->enabled )
            xroom = get_room_index( room->vnum );

        /* This part of the function handles remapping vnums. This matters when we're moving or
           copying an area to a new vnum range -- we want data structures to point to the new
           rooms with their new vnum values. */
        room->vnum += offset;
        room->area = dest;

        /* load_turbolift is a bit of a misnomer -- this calls a function that property initializes
           a turbolift struct that's already loaded into memory. It help manage the global linked
           list of turbolifts, etc. */
        if ( room->lift )
            load_turbolift( room->lift, room, true );

        top_room++;

        // If the destination is enabled, we're hotswapping. Here we go!
        if ( dest->enabled )
        {
            // If we found an existing room, let's start remapping stuff.
            if ( xroom )
            {
                // Start by moving everyone in the old room to the new room.
                CHAR_DATA* ch = NULL, *next_ch = NULL;
                for ( ch = xroom->first_person; ch; ch = next_ch )
                {
                    next_ch = ch->next_in_room;                    
                    char_to_room( ch, room );

                    // Remember to update vendor data.
                    if ( ch->vendor_data )
                    {
                        ch->vendor_data->home = room;
                        save_vendor( ch->vendor_data, TRUE );
                    }

                    save_char_obj( ch, true );
                }

                // Move landed/parked ships to the new room.
                SHIP_DATA* ship = NULL, *next_ship = NULL;
                for ( ship = xroom->first_ship; ship; ship = next_ship )
                {
                    next_ship = ship->next_in_room;
                    UNLINK( ship, xroom->first_ship, xroom->last_ship, next_in_room, prev_in_room );
                    LINK( ship, room->first_ship, room->last_ship, next_in_room, prev_in_room );
                    ship->in_room = room;
                    ship->location = room->vnum;
                    ship->lastdoc = room->vnum;
                    save_ship( ship, true );
                }

                // Move objects on the ground to the new room.
                OBJ_DATA* obj = NULL, *next_obj = NULL;
                for ( obj = xroom->first_content; obj; obj = next_obj )
                {
                    next_obj = obj->next_content;
                    obj_to_room( obj, room );
                }

                // Move instances of furniture to the new room. 
                FURN_DATA* furn = NULL, *next_furn = NULL;
                for ( furn = xroom->first_furniture; furn; furn = next_furn )
                {
                    next_furn = furn->next_in_room;
                    furn->room = room;
                    furn->vnum = room->vnum;
                    UNLINK( furn, xroom->first_furniture, xroom->last_furniture, next_in_room, prev_in_room );
                    LINK( furn, room->first_furniture, room->last_furniture, next_in_room, prev_in_room );
                    save_furniture( furn->pIndexData );
                }

                // Move vehicles (if we ever have them again) to the new room.
                VEHICLE_DATA* vehicle = NULL, *next_vehicle = NULL;
                for ( vehicle = xroom->first_vehicle; vehicle; vehicle = next_vehicle )
                {
                    next_vehicle = vehicle->next_in_room;
                    UNLINK( vehicle, xroom->first_vehicle, xroom->last_vehicle, next_in_room, prev_in_room );
                    LINK( vehicle, room->first_vehicle, room->last_vehicle, next_in_room, prev_in_room );
                    vehicle->in_room = room;
                    vehicle->location = room->vnum;
                }

                // If the old room was a planetary turret, update pointers between the room and the global turret struct.
                if ( xIS_SET( xroom->flags, ROOM_WEAP_TURBOLASER ) || xIS_SET( xroom->flags, ROOM_WEAP_ION ) )
                {
                    for ( pturret = first_pturret; pturret; pturret = pturret->next )
                    {
                        if ( pturret->room == xroom )
                        {
                            pturret->room = room;
                            room->turret = pturret;
                            break;
                        }
                    }
                }

                // If the old room had a phome struct, move it over.
                if ( xroom->phome && ( xIS_SET( room->flags, ROOM_PLR_HOME ) || xIS_SET( room->flags, ROOM_EMPTY_HOME ) ) )
                {
                    // If we just created a blank phome struct earlier in this function, free it here.
                    if ( room->phome )
                        free_phome( room->phome );

                    /* Instead of doing some complicated duplication, we're just going to steal the old
                       room's dynamically allocated phome struct and map it to the new room. */
                    room->phome = xroom->phome;

                    /* Make sure to unmap it from xroom, because otherwise freeing xroom will free its phome and
                       create a dangling pointer (and crash the game). */ 
                    xroom->phome = NULL;

                    // Gotta remember to fix the reverse pointer.
                    room->phome->room = room;
                    xREMOVE_BIT( room->flags, ROOM_EMPTY_HOME );
                    xSET_BIT( room->flags, ROOM_PLR_HOME );
                }

                // If the original room was flagged as on a ship, the substitute room should be.
                if ( xroom->on_ship )
                    room->on_ship = xroom->on_ship;

                /* Make sure that lockers pointing to the old room's vnum point to the new room's vnum.
                   This seems redundant until you remember that we might be offsetting the vnum of the
                   new room. */
                for ( LOCKER_DATA* locker = first_locker; locker; locker = locker->next )
                {
                    if ( locker->vnum == xroom->vnum )
                    {
                        locker->vnum = room->vnum;
                        save_locker( locker, true );
                    }
                }

                /* If, for whatever reason, the xroom were already queued for extraction -- which is
                   unlikely but not impossible -- prevent that extraction. We'll do our own extraction,
                   thank you very much. */   
                QUEUE_DATA* rcd, *next_rcd;
                for ( rcd = first_queued_extract[EXTRACT_ROOM]; rcd; rcd = next_rcd )
                {
                    next_rcd = rcd->next;
                    if ( rcd->ptr == xroom )
                    {
                        UNLINK( rcd, first_queued_extract[EXTRACT_ROOM], last_queued_extract[EXTRACT_ROOM], next, prev );
                        DISPOSE( rcd );
                    }
                }

                /* At the very end of the process, we're going to call delete_room on xroom. This will queue the data
                   structure up for extraction, remove it from the hash, and delete the room from the DB. Remember,
                   this code only runs when we're hot-swapping rooms, so we want that old room gone from the DB and
                   replaced with the new one. */
                delete_room( xroom );
            }

            // Make sure the time programs for the new room are linked up appropriately to the global linked list.
            for ( mprog = room->first_mprog; mprog; mprog = mprog->next )
            {
                if ( ( mprog->type & TIME_PROG ) || ( mprog->type & HOUR_PROG ) )
                {
                    CREATE( tp, TIMEPROG_DATA, 1 );
                    tp->room = room;
                    room->tmprog = tp;
                    LINK( tp, first_timeprog, last_timeprog, next, prev );
                    break;
                }
            }

            // If the new room is a planetary turret, make sure a pturret struct exists. 
            if ( xIS_SET( room->flags, ROOM_WEAP_TURBOLASER ) || xIS_SET( room->flags, ROOM_WEAP_ION ) )
            {
                for ( pturret = first_pturret; pturret; pturret = pturret->next )
                    if ( pturret->room == room )
                        break;

                // If it doesn't exist, create it and update pointers.
                if ( !pturret )
                {
                    CREATE( pturret, TURRET_DATA, 1 );
                    pturret->room = room;
                    room->turret = pturret;
                    LINK( pturret, first_pturret, last_pturret, next, prev );
                }
            }

            /* Regardless of whether there was an old room to be replaced, this new room is going live. Add it to
               the linked list and save it to the DB. */  
            LINK( room, first_room, last_room, next, prev );
            room_map[room->vnum] = room;
            save_room( room, false );
        }
        else
        {
            /* If this is running, the destination area isn't enabled and we're not hotswapping. Just save the new
               room to the database and unload it from game memory afterwards. */
            save_room( room, false );
            unload_room( room );
        }

        // Hot-swapping or not, we increment the counter provided by the calling function because another room was saved.
        (*cnt)++;
    }

    // Always remember to PQclear SQL results.
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

/**
 * @brief Applies a vnum offset to turbolift floors
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us update the room mappings for turbolift floors
 * with a new vnum range. Useful when moving areas to new
 * vnum ranges.
 * 
 * @param lift The area whose rooms are being drawn from.
 * @param min The minimum vnum impacted by the offset.
 * @param max The maximum vnum impacted by the offset.
 * @param offset The +/- modifier for impacted vnums.
 * @return The number of changes made.
 */
int offset_turbolift_floors( TURBOLIFT_DATA* lift, int min, int max, int offset )
{
    TURBOFLOOR_DATA* floor = NULL;
    int cnt = 0;

    // If there's no turbolift, we can't proceed.
    if ( !lift )
        return 0;

    // Iterate through the turbolift floors and adjust vnums
    for ( floor = lift->first_floor; floor; floor = floor->next )
    {
        if ( floor->room >= min && floor->room <= max )
        {
            floor->room += offset;
            cnt++;
        }
    }

    // Return the number of turbolift floors adjusted
    return cnt;
}

/**
 * @brief Applies a vnum offset to room exits
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us update the room exits to point to adjusted
 * vnums. Useful when moving areas to new vnum ranges.
 * 
 * Note that I used a double pointer approach for error
 * handling. We want to make sure that the first-level pointer
 * (i.e., the memory address being passed) isn't null even if
 * the room has no exits (i.e., the second-level pointer is null).
 * 
 * @param first A double pointer 
 * @param min The minimum vnum impacted by the offset.
 * @param max The maximum vnum impacted by the offset.
 * @param offset The +/- modifier for impacted vnums.
 * @return The number of changes made.
 */
int offset_room_exits( EXIT_DATA** first, int min, int max, int offset )
{
    EXIT_DATA* exit = NULL;
    int cnt = 0;

    if ( !first )
        return 0;

    // Iterate through the exits and adjust vnums
    for ( exit = *first; exit; exit = exit->next )
    {
        if ( exit->vnum >= min && exit->vnum <= max )
        {
            exit->vnum += offset;
            cnt++;
        }
    }

    return cnt;
}

