/**
 * @brief Copies the mob indices from one area into another
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us copy the mob indices from one area into another. This is a
 * key component of the area migration system that lets us move areas from
 * the BP to the MP (and vice-versa). If the destination area is enabled,
 * this function will facilitate "hot-swapping" the mob indices while the game
 * is live, remapping pointers from the old mob instances to the new mob
 * indices while keeping those mobs loaded, reloading lprogs associated with
 * the mob prototypes, and so on.
 * 
 * @param source The area whose mob indices are being drawn from.
 * @param dest The area to which the new mob indices are being attached.
 * @param db The enum value assigned to the DB being read from.
 * @param offset The +/- modifier for VNums if the destination area has a different VNum range.
 * @param cnt A pointer to an int counter provided by the calling function. 
 * @return The resulting status (error or success) code.
 */
int duplicate_mobs( AREA_DATA* source, AREA_DATA* dest, int db, int offset, int* cnt )
{
    // If the source area doesnt exist, can't proceed.
    if ( !source )
    {
        bug( "%s: NULL source area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    // If the destination area doesn't exist, can't proceed.
    if ( !dest )
    {
        bug( "%s: NULL destination area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    /* If the enum value doesn't match with a DB being read from, can't proceed.
    Note that I'm envisioning this expanding to encompass more than two DBs
    if, say, we had a sandbox running in tandem or something. That's why I
    went with the enum approach. */
    if ( db < MAIN_DB || db > ALT_DB )
    {
        bug( "%s: invalid database", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    /* The source and destination area structs can (and should) be the same only
       if we're pulling from the other environment. This is because the calling
       function has already created a new area structure when importing from
       the alt DB. Otherwise, this function is meant to let us copy mobs to
       new areas within the same environment. */
    if ( db == MAIN_DB && source == dest )
    {
        bug( "%s: source and destination areas are the same", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    // Start by pulling the mobs from the appropriate DB
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    MOB_INDEX_DATA* mob = NULL, *xmob = NULL;
    CHAR_DATA* tmob = NULL, *next_tmob = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE vnum BETWEEN %d AND %d AND area = %s", DB_TABLE_MOBS, source->min_vnum, source->max_vnum, sql_escape_string(source->shortname) );
    qresult = db == MAIN_DB ? query_db( selectquery ) : query_alt_db( selectquery );
    rows = PQntuples(qresult);

    /* If we don't get a return from the SQL query at all, something's gone wrong.
    Flag as an error -- which will, in turn, cause the calling function to
    abort the entire migration and SQL transaction, forcing a copyover and restoring
    the status quo from before this function ran. */ 
    if ( qresult == NULL )
        return E_LOTJ_LOAD_ERROR;

    /* If the query succeeds but we simply didn't get any mobs, that's not necessarily an error.
       Some areas may not have mobs, so we want the calling migration function to continue.
       Return success. */ 
    if ( rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    // Start iterating through all the mobs we just pulled from the DB.
    for ( row = 0; row < rows; row++ )
    {
        // Create a new mob index struct for each.
        CREATE( mob, MOB_INDEX_DATA, 1 );

        // Map the data pulled from the DB to the new mob index struct.
        if ( ( rval = fieldmap_postgres_row( qresult, row, mob, mob_index_fields ) ) != E_LOTJ_SUCCESS )
        {
            FREE_STRUCT( mob, mob_index_fields );
            continue;
        }

        // Manually map the mprog types. This is old sorcery that's best left alone.
        for ( MPROG_DATA* mprog = mob->first_mprog; mprog; mprog = mprog->next )
            mob->progtypes = mob->progtypes | mprog->type;

        // Make sure the mob's special functions get linked up.
        if ( !NULLSTR( mob->spec_funname ) )
            mob->spec_fun = spec_lookup( mob->spec_funname );

        if ( !NULLSTR( mob->spec_funname_2 ) )
            mob->spec_2 = spec_lookup( mob->spec_funname_2 );

        if ( !NULLSTR( mob->spec_funname_3 ) )
            mob->spec_3 = spec_lookup( mob->spec_funname_3 );

        if ( !NULLSTR( mob->spec_funname_4 ) )
            mob->spec_4 = spec_lookup( mob->spec_funname_4 );

        /* This is where the magic starts to happen. If the destination area is enabled, that
        means that we're doing a hotswap, loading new mob indices in the place of old while the
        game is still live and subbing them into place. */
        if ( dest->enabled )
        {
            // Start by finding the old mob index being replaced
            xmob = get_mob_index( mob->vnum );

            // If it exists...
            if ( xmob )
            {
                /* Iterate through all the existing intances of mobs in the game and update their prototypes
                   to point to the new one. */
                for ( tmob = first_char; tmob; tmob = next_tmob )
                {
                    next_tmob = tmob->next;

                    if ( tmob->pIndexData != xmob )
                        continue;

                    tmob->pIndexData = mob;

                    /* If that mob is a reset-generated mob, nuke it. It'll get recreated
                       when the area resets at the tail end of this process. */
                    if ( tmob->reset_ptr )
                        extract_char( tmob );
                }

                /* It's very possible that there are mobs in the extraction queue when this runs. Make sure to remap
                   prototype pointers for those mobs, too, to prevent dangling pointers and possible crashes when that
                   extraction queue finally runs. */
                for ( QUEUE_DATA* zch_queue = first_queued_extract[EXTRACT_CHAR]; zch_queue; zch_queue = zch_queue->next )
                {
                    if ( zch_queue->type == EXTRACT_CHAR )
                    {
                        CHAR_DATA* zch = (CHAR_DATA*) zch_queue->ptr;
                        if ( zch->pIndexData && zch->pIndexData == xmob )
                            zch->pIndexData = mob;
                    }
                }

                // Update the mob count of the new struct to reflect the number of mobs already in the game under the old proto.
                mob->count = xmob->count;
            }
        }

        // Apply any vnum offsets and point the new mob index to the destination area.
        mob->vnum += offset;
        mob->area = dest;
        top_mob_index++;

        // If the destination is enabled, we're hotswapping. 
        if ( dest->enabled )
        {
            /* If the old mob exists, call delete_mob to unload it, remove it from the hash, and delete it from the DB.
               Since a new mob index is going in its place, we need to make sure the old one is completely erased. */
            if ( xmob )
                delete_mob( xmob, FALSE );

            // Add the new mob index to the linked list and save it to the database.
            LINK( mob, first_mob_index, last_mob_index, next, prev );
            mob_map[mob->vnum] = mob;
            save_mob( mob, false );
        }
        else
        {
            /* If this is running, we're not hot-swapping. Just save the new mob index to the DB and unload it
               from MUD memory. It'll see the light of day some other time, once the destination area is activated. */ 
            save_mob( mob, false );
            unload_mob( mob, FALSE );
        }

        // Hot-swapping or not, we increment the counter provided by the calling function because another mob was saved.
        (*cnt)++;
    }

    // Always remember to PQclear SQL results.
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

/**
 * @brief Copies the object indices from one area into another
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us copy the object indices from one area into another. This is a
 * key component of the area migration system that lets us move areas from
 * the BP to the MP (and vice-versa). If the destination area is enabled,
 * this function will facilitate "hot-swapping" the object indices while the
 * game is live, remapping pointers from the old object instances to the new
 * object indices while keeping those objects loaded, reloading lprogs
 * associated with the object prototypes, and so on.
 * 
 * @param source The area whose object indices are being drawn from.
 * @param dest The area to which the new object indices are being attached.
 * @param db The enum value assigned to the DB being read from.
 * @param offset The +/- modifier for VNums if the destination area has a different VNum range.
 * @param cnt A pointer to an int counter provided by the calling function. 
 * @return The resulting status (error or success) code.
 */
int duplicate_objects( AREA_DATA* source, AREA_DATA* dest, int db, int offset, int* cnt )
{
    // If the source area doesnt exist, can't proceed.
    if ( !source )
    {
        bug( "%s: NULL source area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    // If the destination area doesn't exist, can't proceed.
    if ( !dest )
    {
        bug( "%s: NULL destination area", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    /* If the enum value doesn't match with a DB being read from, can't proceed.
    Note that I'm envisioning this expanding to encompass more than two DBs
    if, say, we had a sandbox running in tandem or something. That's why I
    went with the enum approach. */
    if ( db < MAIN_DB || db > ALT_DB )
    {
        bug( "%s: invalid database", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    /* The source and destination area structs can (and should) be the same only
       if we're pulling from the other environment. This is because the calling
       function has already created a new area structure when importing from
       the alt DB. Otherwise, this function is meant to let us copy objects to
       new areas within the same environment. */
    if ( db == MAIN_DB && source == dest )
    {
        bug( "%s: source and destination areas are the same", FUNC );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    // Start by pulling the objects from the appropriate DB
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    OBJ_INDEX_DATA* obj = NULL, *xobj = NULL;
    OBJ_DATA* tobj = NULL, *next_tobj = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE vnum BETWEEN %d AND %d AND area = %s", DB_TABLE_OBJECTS, source->min_vnum, source->max_vnum, sql_escape_string(source->shortname) );
    qresult = db == MAIN_DB ? query_db( selectquery ) : query_alt_db( selectquery );
    rows = PQntuples(qresult);

    /* If we don't get a return from the SQL query at all, something's gone wrong.
    Flag as an error -- which will, in turn, cause the calling function to
    abort the entire migration and SQL transaction, forcing a copyover and restoring
    the status quo from before this function ran. */ 
    if ( qresult == NULL )
        return E_LOTJ_LOAD_ERROR;

    /* If the query succeeds but we simply didn't get any objects, that's not necessarily an error.
       Some areas may not have objects, so we want the calling migration function to continue.
       Return success. */ 
    if ( rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    // Start iterating through all the objects we just pulled from the DB.
    for ( row = 0; row < rows; row++ )
    {
        // Create a new object index struct for each.
        CREATE( obj, OBJ_INDEX_DATA, 1 );

        // Map the data pulled from the DB to the new object index struct.
        if ( ( rval = fieldmap_postgres_row( qresult, row, obj, obj_index_fields ) ) != E_LOTJ_SUCCESS )
        {
            FREE_STRUCT( obj, obj_index_fields );
            continue;
        }

        /* This is some weird hackery to fix a bug with object-based affects
           that manifested during the flatfiles-to-PostgreSQL migration. This
           block can probably be eliminated, but I don't have the courage to
           rip this particular band-aid off. - Nield 07/15/2025 */ 
        char aff_str[MIL];
        for ( AFFECT_DATA* aff = obj->first_affect; aff; aff = aff->next )
        {
            if ( aff->modifier == -2147483648 )
            {
                snprintf( aff_str, MIL, "%d", aff->modifier );
                aff->modifier = 0;
                aff->bitvector = parse_bitvector( aff_str );
                save_object( obj, TRUE );
            }
        }

        // Manually map the mprog types. This is old sorcery that's best left alone.
        for ( MPROG_DATA* mprog = obj->first_mprog; mprog; mprog = mprog->next )
            obj->progtypes = obj->progtypes | mprog->type;

        /* This is where the magic starts to happen. If the destination area is enabled, that
        means that we're doing a hotswap, loading new object indices in the place of old while the
        game is still live and subbing them into place. */
        if ( dest->enabled )
        {
            // Start by finding the old object index being replaced
            xobj = get_obj_index( obj->vnum );

            // If it exists...
            if ( xobj )
            {
                /* Iterate through all the existing intances of objects in the game and update their prototypes
                   to point to the new one. */
                for ( tobj = first_object; tobj; tobj = next_tobj )
                {
                    next_tobj = tobj->next;

                    if ( tobj->pIndexData != xobj )
                        continue;

                    tobj->pIndexData = obj;

                    /* Save the characters if found w/in two layers of nesting. I'm not doing the work to
                       accommodate Russian Nesting Dolls. */
                    if ( tobj->carried_by )
                        save_char_obj( tobj->carried_by, TRUE );

                    if ( tobj->in_obj && tobj->in_obj->carried_by )
                        save_char_obj( tobj->in_obj->carried_by, TRUE );

                    // Save lockers, too.
                    if ( tobj->in_locker )
                        save_locker( tobj->in_locker, TRUE );

                    // Save the persistent object. This function won't do anything if it's not actually a persistent object.
                    if ( tobj->in_room )
                        save_persistent_object( tobj, TRUE );

                    /* If that object is a reset-generated object, nuke it. It'll get recreated
                       when the area resets at the tail end of this process. */
                    if ( tobj->reset_ptr )
                        extract_obj( tobj );
                }


                /* It's very possible that there are objects in the extraction queue when this runs. Make sure to remap
                   prototype pointers for those objects, too, to prevent dangling pointers and possible crashes when that
                   extraction queue finally runs. */
                for ( QUEUE_DATA* ocd_queue = first_queued_extract[EXTRACT_OBJ]; ocd_queue; ocd_queue = ocd_queue->next )
                {
                    if ( ocd_queue->type == EXTRACT_OBJ )
                    {
                        OBJ_DATA* ocd = (OBJ_DATA*) ocd_queue->ptr;
                        if ( ocd->pIndexData && ocd->pIndexData == xobj )
                            ocd->pIndexData = obj;
                    }
                }

                // Update the object count of the new struct to reflect the number of objects already in the game under the old proto.
                obj->count = xobj->count;
            }    
        }

        // Apply any vnum offsets and point the new object index to the destination area.
        obj->vnum += offset;
        obj->area = dest;
        top_obj_index++;

        // If the destination is enabled, we're hotswapping. 
        if ( dest->enabled )
        {
            /* If the old object exists, call delete_obj to unload it, remove it from the hash, and delete it from the DB.
               Since a new object index is going in its place, we need to make sure the old one is completely erased. */
            if ( xobj )
                delete_obj( xobj, FALSE );

            // Save it to the database and add it to the linked list.
            save_object( obj, false );
            LINK( obj, first_obj_index, last_obj_index, next, prev );
            obj_map[obj->vnum] = obj;
        }
        else
        {
            /* If this is running, we're not hot-swapping. Just save the new object index to the DB and unload it
               from MUD memory. It'll see the light of day some other time, once the destination area is activated. */ 
            save_object( obj, false );
            unload_obj( obj, FALSE );
        }

        // Hot-swapping or not, we increment the counter provided by the calling function because another object was saved.
        (*cnt)++;
    }

    // Always remember to PQclear SQL results.
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

int load_rooms_sql( AREA_DATA* area )
{
    int cnt = 0;
    TIMEPROG_DATA* tp = NULL;
    MPROG_DATA* mprog = NULL;

    if ( !area )
    {
        bug("%s: NULL area", FUNC );
        return 0;
    }

    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    ROOM_INDEX_DATA* room = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE vnum BETWEEN %d AND %d AND area = %s", DB_TABLE_ROOMS, area->min_vnum, area->max_vnum, sql_escape_string(area->shortname) );
    qresult = query_db( selectquery );
    rows = PQntuples(qresult);

    if ( qresult == NULL || rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return 0;
    }

    for ( row = 0; row < rows; row++ )
    {
        CREATE( room, ROOM_INDEX_DATA, 1 );

        if ( ( rval = fieldmap_postgres_row( qresult, row, room, room_index_fields ) ) != E_LOTJ_SUCCESS )
        {
            FREE_STRUCT( room, room_index_fields );
            continue;
        }

        if ( room->variable == NULL )
            CREATE( room->variable, VARIABLE_DATA, 1 );

        if ( xIS_SET( room->flags, ROOM_EMPTY_HOME ) && !room->phome )
        {
            CREATE( room->phome, PHOME_DATA, 1 );
            SET_STRING( room->phome->owner, "" );
            room->phome->price = PHOME_DEFAULT_PRICE;
            save_room( room, TRUE );
        }

        // Creates the clan pad data structure if it doesn't exist
        if ( ( xIS_SET( room->flags, ROOM_CLANPAD ) || xIS_SET( room->flags, ROOM_CLANHANGAR ) ) && !room->pad )
            get_pad_from_room( room );

        if ( xIS_SET( room->flags, ROOM_WEAP_TURBOLASER ) || xIS_SET( room->flags, ROOM_WEAP_ION ) )
        {
            TURRET_DATA* pturret = NULL;
            for ( pturret = first_pturret; pturret; pturret = pturret->next )
                if ( pturret->room == room )
                    break;

            if ( !pturret )
            {
                CREATE( pturret, TURRET_DATA, 1 );
                pturret->room = room;
                room->turret = pturret;
                LINK( pturret, first_pturret, last_pturret, next, prev );
            }
        }

        if ( room->phome )
            room->phome->room = room;

        for ( MPROG_DATA* mprog = room->first_mprog; mprog; mprog = mprog->next )
            room->progtypes = room->progtypes | mprog->type;

        if ( room->lift )
            load_turbolift( room->lift, room, true );

        room->on_ship = NULL;

        for ( mprog = room->first_mprog; mprog; mprog = mprog->next )
        {
            if ( ( mprog->type & TIME_PROG ) || ( mprog->type & HOUR_PROG ) )
            {
                CREATE( tp, TIMEPROG_DATA, 1 );
                tp->room = room;
                room->tmprog = tp;
                LINK( tp, first_timeprog, last_timeprog, next, prev );
                break;
            }
        }

        LINK( room, first_room, last_room, next, prev );
        room_map[room->vnum] = room;
        top_room++;
        cnt++;
    }

    if ( qresult )
        PQclear( qresult );

    return cnt;
}

