/**
 * @brief Imports an area from another MUD environment 
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us import an area, together with its rooms, mob indices, and
 * object indices, from another MUD instance (e.g., the BP) to the instance
 * running this function.
 * 
 * @param ch The character invoking the calling function.
 * @param shortname The shortname of the area being imported.
 * @param confirmed Whether the user confirmed their intent to overwrite an existing area.
 * @return The resulting status (error or success) code.
 */
int import_altport_area( CHAR_DATA* ch, const char* shortname, bool confirmed )
{
    // If there's no invoking character or no area shortname, we can't proceed.
    if ( !ch || NULLSTR( shortname ) )
        return E_LOTJ_MISSING_ARGUMENTS;

    // Start by trying to load the area structure from the alternate DB.
    char selectquery[MSL * 2], buf[1024];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0, offset = 0;
    int rooms = 0, objs = 0, mobs = 0;
    AREA_DATA* area = NULL, *tarea = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE shortname = %s", DB_TABLE_AREAS, sql_escape_string( shortname ) );
    qresult = query_alt_db( selectquery );
    rows = PQntuples(qresult);

    // Let's just tee up this copyover alert string now. Just in case...
    snprintf( buf, 1024, "\n *** [ALERT] EMERGENCY COPYOVER, PLEASE STAND BY...\n" );

    // If there was no DB query return value, something's gone wrong. Return an error.
    if ( qresult == NULL )
    {
        bug( "%s: null qresult", FUNC );
        return E_LOTJ_LOAD_ERROR;
    }

    // If there were no matches found, that's fine. It's still a successful run of the function.
    if( rows == 0 )
    {
        ch_println( ch, "&RCould not find %s in the alternate environment database.", shortname );
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    // If there was a match found, let's load it in.
    CREATE( area, AREA_DATA, 1 );

    /* This should only ever happen in the event of a real schema mismatch. For example, if the
       BP is running a MUD build substantially older than the MP and we've made real changes to
       the MP's area schema, this could fire. In that case, we can't proceed. */
    if ( ( rval = fieldmap_postgres_row( qresult, row, area, area_fields ) ) != E_LOTJ_SUCCESS )
    {
        // Free whatever parts of the area were loaded/allocated.
        FREE_STRUCT_NORET( area, area_fields );

        // Let the user know.
        ch_println( ch, "&RError: could not load area %s", shortname );
        bug( "%s: could not load area %s from the alternate environment database.", FUNC, shortname );

        // Always PQclear
        if ( qresult ) PQclear( qresult );

        // Return an error to let the calling function know.
        return E_LOTJ_LOAD_ERROR;
    }

    // If we've successfully loaded an area from the alternate DB, let's see if there are conflicts. 
    tarea = get_area( area->shortname );
    if ( !tarea ) tarea = get_archived_area( area->shortname );

    /* If there is an existing area with a matching shortname and the user has not confirmed (via the calling
       function) that they want to overwrite it, we can go no further. */
    if ( tarea && !confirmed )
    {
        ch_println( ch, "&RWarning: this will overwrite an existing area in this environment." );
        ch_println( ch, "&RTo proceed with the overwrite, enter: migratearea import %s confirm", area->shortname );

        // Free the area we loaded from the alternate DB.
        FREE_STRUCT_NORET( area, area_fields );

        // Always PQclear...
        if ( qresult ) PQclear( qresult );

        // Return the error.
        return E_LOTJ_NOTHING_TO_DO;
    }

    /* This is where things get spicy. We're using a SQL transaction to do an "all or nothing" save of
       what we're importing. If, at any point, we encounter an error in the migration, we roll back the
       transaction and initiate a copyover to return us to the status quo. */
    if ( ( rval = begin_sql_transaction() ) != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to begin transaction when importing area: %s", FUNC, lotj_strerror(rval) );
        return E_LOTJ_DB_POSTGRES_ERROR;
    }

    // If there's an existing area we're overwriting, let's do some preliminary remapping.
    if ( tarea )
    {
        // If the new area is in a different VNum range, account for that.
        offset = area->min_vnum - tarea->min_vnum;

        // If the area is part of a planet, map the pointers
        area->planet = tarea->planet;
        for ( PLANET_DATA* planet = first_planet; planet; planet = planet->next )
        {
            /* Remap the planet's area pointers to point back to this new area.
               Remember: if the area migration fails, the copyover will undo this anyway,
               so it's fine to do this as an early step in the migration process. */ 
            for ( AREA_DATA_LNODE* anode = planet->first_area; anode; anode = anode->next )
            {
                if ( anode->value == tarea )
                {
                    anode->value = area;

                    /* The planet will never save if the migration fails, both because we're
                       queueing it to save (and the save queue won't run until we're out of this
                       process) and because any DB saves that do run are captured in the
                       transaction. */
                    save_planet( planet, TRUE );
                }

                /* If we're replacing the old area with a new area that has a VNum offset, make sure
                   planetary resets account for that. */
                if ( offset_planet_vnums( planet, tarea->min_vnum, tarea->max_vnum, offset ) > 0 )
                    save_planet( planet, TRUE );
            }
        }

        // Sweep through every room and area and offset the vnums, if applicable
        if ( offset != 0 )
            offset_vnums( tarea->min_vnum, tarea->max_vnum, offset );

        /* If we're replacing an old area, set the new area ID to match the old. There's no need
           to delete the old area from the database; we can simply overwrite it in this case. */
        area->id = tarea->id;
        area->enabled = tarea->enabled;

        // Let's unlink the old area from the linked list.
        if ( tarea->enabled )
            UNLINK( tarea, first_area, last_area, next, prev );
        else
            UNLINK( tarea, first_area_archive, last_area_archive, next, prev );
    }
    else
    {
        // If there is no old area, set the new area's ID to 0 so it gets assigned by the DB. 
        area->id = 0;

        /* If there's no old area we're replacing, we're not hotswapping the new one in; it loads as disabled by default
           and can be enabled using "aset" when the user chooses to. */
        area->enabled = FALSE;
    }

    // Save the new area to the database.
    save_area( area, false, false );

    // Link it up appropriately.
    if ( area->enabled )
        LINK_SORT_NUM( area, AREA_DATA, first_area, last_area, next, prev, min_vnum );
    else
        LINK_SORT_NAME( area, AREA_DATA, first_area_archive, last_area_archive, next, prev, shortname );

    /* This is where the magic happens. We duplicate the object indices, mob indices, and rooms -- in that order.
       If any of these duplication functions fail, we abort the migration process, roll back the transaction, and
       copyover. This would mean that the save_area function call we made above has no effect. Most of the
       hotswapping logic exists in these three duplicate_ functions we're calling below. */
    if ( duplicate_objects( area, area, ALT_DB, offset, &objs ) != E_LOTJ_SUCCESS || duplicate_mobs( area, area, ALT_DB, offset, &mobs ) != E_LOTJ_SUCCESS || duplicate_rooms( area, area, ALT_DB, offset, &rooms ) != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to import area. Rolling back.", FUNC );
        rollback_sql_transaction();
        copyover( buf, true, true, true );
        return E_LOTJ_PARSE_ERROR;
    }

    /* If we've gotten this far, we're in the home stretch. Let's commit the SQL transaction and commit these saves to the database.
       If that fails, we may have a DB problem -- but the only thing we can do is copyover and hope for the best. */
    if ( ( rval = commit_sql_transaction() ) != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to commit transaction when importing area: %s", FUNC, lotj_strerror(rval) );
        copyover( buf, true, true, true );
        return E_LOTJ_DB_POSTGRES_ERROR;
    }

    // We made it! Give a report on what we just imported.
    ch_println( ch, "&zImported area &C%s&z.", area->shortname );
    ch_println( ch, "&zImported &C%d&z objects.", objs );
    ch_println( ch, "&zImported &C%d&z rooms.", rooms );
    ch_println( ch, "&zImported &C%d&z mobs.", mobs );
    ch_println( ch, "&zImport successful." );

    // If the imported area isn't enabled, let the user know how to enable it.
    if ( !area->enabled )
        ch_println( ch, "&zUse &Caset %s enable&z to enable the area.", area->shortname );

    // Very important to fix the exits
    fix_exits();

    /* If the area is enabled (meaning we're hot-swapping it), run the resets to load in
       any mobs, objects, non-player vendors, etc. */
    if ( area->enabled ) reset_area( area );

    // If there was an old area we're replacing, we can finally free it from memory.
    if ( tarea ) free_area( tarea );

    // Always PQclear
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

/**
 * @brief Shows details of an area in another MUD environment.
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us view the details of an area that exists in another
 * MUD environment using the same output process that "astat" uses
 * for areas in the local environment.
 * 
 * @param ch The character invoking the calling function.
 * @param shortname The shortname of the area being evaluated.
 * @return The resulting status (error or success) code.
 */
int show_altport_area( CHAR_DATA* ch, const char* shortname )
{
    // If there's no calling character or area shortname, we can't proceed.
    if ( !ch || NULLSTR( shortname ) )
        return E_LOTJ_MISSING_ARGUMENTS;

    // Start by loading the target area from the alternate environment's database.
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    AREA_DATA* area = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE shortname = %s", DB_TABLE_AREAS, sql_escape_string( shortname ) );
    qresult = query_alt_db( selectquery );
    rows = PQntuples(qresult);

    // If the database query failed outright, we've got a problemo. Throw a bug alert and return an error. 
    if ( qresult == NULL )
    {
        bug( "%s: null qresult", FUNC );
        return E_LOTJ_LOAD_ERROR;
    }

    // If there are no matching areas, that's still a successful run of the function. Return success.
    if( rows == 0 )
    {
        ch_println( ch, "&RCould not find %s in the alternate environment database.", shortname );
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    /* What we're really doing here is importing *just* the area structure, but without loading
       any rooms, mob indices, or object indices. Load it into MUD memory. */
    CREATE( area, AREA_DATA, 1 );

    /* This should only ever happen in the event of a real schema mismatch. For example, if the
       BP is running a MUD build substantially older than the MP and we've made real changes to
       the MP's area schema, this could fire. In that case, we can't proceed. */
    if ( ( rval = fieldmap_postgres_row( qresult, row, area, area_fields ) ) != E_LOTJ_SUCCESS )
    {
        // Free up whatever parts of the area were loaded into memory.
        FREE_STRUCT_NORET( area, area_fields );

        // Notify the user.
        ch_println( ch, "&RError: could not load area %s", shortname );

        // Notify the rest of us...
        bug( "%s: could not load area %s from the alternate environment database.", FUNC, shortname );

        // Always PQclear...
        if ( qresult ) PQclear( qresult );

        // Return the error.
        return E_LOTJ_LOAD_ERROR;
    }

    // If we have the area loaded in, all we really do is call the same output function that "astat" uses
    show_area( ch, area, false );

    // Free it after.
    FREE_STRUCT_NORET( area, area_fields );

    // Always PQclear.
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

/**
 * @brief Lists the areas from another MUD environment.
 * @author Nield
 * @date 2025-07-15
 * 
 * This lets us view a list of areas -- enabled or otherwise --
 * that exist in another MUD environment.
 * 
 * @param ch The character invoking the calling function.
 * @return The resulting status (error or success) code.
 */
int list_altport_areas( CHAR_DATA* ch )
{
    // If there's no character to output this list to, we can't proceed.
    if ( !ch )
        return E_LOTJ_MISSING_ARGUMENTS;

    /* Start by pulling all the areas from the alternate DB. This may seem
       like a bad idea, but the actual AREA_DATA data structures are pretty
       light. We can safely load them all at once without creating much
       lag. If that ever becomes the case, we can adopt a more selective
       SQL query like we use for the "prestore" system. */
    int cnt = 0;
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0, rval = 0;
    AREA_DATA* area = NULL, *tarea = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s", DB_TABLE_AREAS );
    qresult = query_alt_db( selectquery );
    rows = PQntuples(qresult);

    // If the query failed, we've got a problemo. Throw a bug alert and return an error.
    if ( qresult == NULL )
    {
        bug( "%s: null qresult", FUNC );
        return E_LOTJ_LOAD_ERROR;
    }

    /* If the query yields zero rows... I mean realistically, that's never going to happen
       because the MUD cannot function without at least limbo.are... but we'll pretend
       that this can be a valid outcome. */
    if ( rows == 0 )
    {
        ch_println( ch, "&zNo areas found in the alternate environment database." );
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    // Load the areas into MUD memory just long enough for us to list them, and then we'll free them out. 
    for ( row = 0; row < rows; row++ )
    {
        CREATE( area, AREA_DATA, 1 );

        /* If this fails, we probably have a schema mismatch because the build the other environment
           (typically the BP) is running is too out-of-date and the AREA_DATA structure has changed
           significantly between builds. Make sure the environments are running the same build. */
        if ( ( rval = fieldmap_postgres_row( qresult, row, area, area_fields ) ) != E_LOTJ_SUCCESS )
        {
            FREE_STRUCT_NORET( area, area_fields );
            continue;
        }

        // For each area we're pulling, check to see if it also exists in the environment we're running.
        if ( area->shortname )
            tarea = get_area( area->shortname );

        if ( area->shortname && !tarea )
            tarea = get_archived_area( area->shortname );

        cnt++;

        // List the area, using the purple color code for areas that already exist in our environment.
        ch_println( ch, "%s%-25s &z| V: &Y%-2d &zRange: &C%10d - %-10d", tarea ? "&p" : "&g",
        ( area->shortname ? area->shortname : "&R(invalid)" ), area->version, area->min_vnum, area->max_vnum );

        // Free the area we've just loaded.
        FREE_STRUCT_NORET( area, area_fields );
    }

    // Always PQclear...
    if ( qresult )
        PQclear( qresult );

    // Mission accomplished.
    return E_LOTJ_SUCCESS;
}

/**
 * @brief Allows the migration of areas from one MUD environment to another.
 * @author Nield
 * @date 2025-07-15
 * 
 * This is the main function that lets a user list areas in an alternate
 * MUD environment, view details of a specific area, or import an area
 * into the current MUD environment.
 * 
 * @param ch The character invoking the function.
 * @param argument The user input provided after the command name.
 */
CMDF do_migratearea( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL], arg3[MIL];

    IMM_CHECK( ch );

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );


    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Cmigratearea list" );
        ch_println( ch, "&z        &Cmigratearea show <&warea shortname&C>" );
        ch_println( ch, "&z        &Cmigratearea import <&warea shortname&C>" );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        list_altport_areas( ch );
        return;
    }

    if ( !str_cmp( arg, "show" ) )
    {
        show_altport_area( ch, arg2 );
        return;
    }

    if ( !str_cmp( arg, "import" ) )
    {
        // Start a critical period to force a copyover if things get squirrely.
        critical_start();
        import_altport_area( ch, arg2, !str_cmp( arg3, "confirm" ) );
        // If we've made it this far without downstream functions forcing a copyover, end the critical period.
        critical_end();
        return;
    }

    do_migratearea( ch, "" );
    return;
}

int load_area_sql( const PGresult* qresult, int row )
{
    AREA_DATA* area = NULL;
    CREATE( area, AREA_DATA, 1 );
    int rval = 0;

    if ( ( rval = fieldmap_postgres_row( qresult, row, area, area_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( area, area_fields );
        return rval;
    }

    if ( area->min_vnum <= 0 || area->max_vnum > MAX_VNUMS )
    {
        boot_log( "Area %s has a vnum range (%d-%d) outside the permitted (%d-%d). Disabling.", area->shortname, area->min_vnum, area->max_vnum, 1, MAX_VNUMS );
        area->enabled = FALSE;
    }

    if ( area->enabled )
    {
        LINK_SORT_NUM( area, AREA_DATA, first_area, last_area, next, prev, min_vnum );
        top_area++;
        load_objects_sql( area );
        load_rooms_sql( area );
        load_mobs_sql( area );
        boot_log( "%-25s: Vnums: %10d - %-10d", area->shortname, area->min_vnum, area->max_vnum );
    }
    else
        LINK_SORT_NAME( area, AREA_DATA, first_area_archive, last_area_archive, next, prev, shortname );

    return E_LOTJ_SUCCESS;
}

bool json_is_empty( const cJSON* object )
{
    if ( object == NULL )
        return TRUE;

    if (cJSON_IsObject(object))
        return (cJSON_GetArraySize(object) == 0);

    if (cJSON_IsArray(object))
        return (cJSON_GetArraySize(object) == 0);

    return TRUE;
}

int load_environment_variables( void )
{
    char buf[256], line[256];
    snprintf( buf, 256, "%s%s", SYSTEM_DIR, ENV_VARS );
    FILE* fp = NULL;
    if ( ( fp = fopen( buf, "r" ) ) == NULL )
    {
        boot_log("%s: could not open %s%s for reading", FUNC, SYSTEM_DIR, ENV_VARS );
        return E_LOTJ_LOAD_ERROR;
    }

    while ( fgets( line, sizeof( line ), fp ) )
    {
        line[strcspn(line, "\n")] = 0;

        if ( NULLSTR( line ) )
            continue;

        char* delimiter = strchr( line, '=' );
        if ( delimiter )
        {
            *delimiter = '\0';
            char *key = line;
            char *value = delimiter + 1;
            boot_log("%s: Setting environment variable '%s' to '%s'", FUNC, key, value );

            if (setenv(key, value, 1) != 0)
                perror("setenv");
        }
    }

    fclose(fp);
    return E_LOTJ_SUCCESS;
}

size_t mod_str_len( const char* str, int base )
{
    size_t len = 0;

    if ( !str || base <= 0 )
        return 0;

    len = base + strlen( str ) - strlen( stripclr( str ) );
    return len;
}

CMDF do_cleanup( CHAR_DATA* ch, char* argument )
{
    char selectquery[MSL], arg[MIL], arg2[MIL];
    PGresult *qresult = NULL;
    int days = 0, rows = 0, row = 0, cnt = 0;
    ROOM_INDEX_DATA* room = NULL;

    IMM_CHECK( ch );

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg ) || NULLSTR( arg2 ) || !is_number( arg2 ) ||
    ( str_cmp( arg, "vendors" ) && str_cmp( arg, "phomes" ) && str_cmp( arg, "wanted" ) ) )
    {
        ch_println( ch, "&zSyntax: &Ccleanup <&wvendors/phomes/wanted&C> [# of days inactive]" );
        return;
    }

    days = atoi( arg2 );
    if ( days < 0 || days > 365 )
    {
        ch_println( ch, "&zInvalid range. Number of days must be between 0 and 365." );
        return;
    }

    snprintf( selectquery, MSL, "SELECT id, name, updated_at FROM %s WHERE living = 't'", DB_TABLE_PLAYERS );
    qresult = query_db( selectquery );
    rows = PQntuples(qresult);

    if ( qresult == NULL || rows == 0 )
    {
        ch_println( ch, "&RFailed to load players table. Aborting..." );
        if ( qresult ) PQclear( qresult );
        return;
    }

    struct PlrInfo {
        int id;
        const char* name;
        int64_t last_login;
    };

    struct PlrInfo players[rows];
    for ( row = 0; row < rows; row++ )
    {
        players[row].id = atoi( PQgetvalue(qresult, row, 0) );
        players[row].name = PQgetvalue(qresult, row, 1);
        players[row].last_login = atol( PQgetvalue(qresult, row, 2) );
    }

    if ( !str_cmp( arg, "vendors" ) )
    {
        VENDOR_DATA* vendor = NULL, *next_vendor = NULL;
        cnt = 0;

        for ( vendor = first_vendor; vendor; vendor = next_vendor )
        {
            next_vendor = vendor->next;

            for ( int i = rows - 1; i >= 0; i-- )
            {
                if ( !str_cmp( players[i].name, vendor->owner ) )
                {
                    if ( players[i].last_login < ( current_time - ( 60 * 60 * 24 * days ) ) )
                    {
                        room = vendor->home ? vendor->home : ( vendor->mob ? vendor->mob->in_room : NULL );
                        delete_vendor( vendor );
                        reset_vendor_room( room );
                        cnt++;
                    }

                    break;
                }
            }
        }

        ch_println( ch, "&zCleaned up &C%'d&z vendors.", cnt );
    }

    if ( !str_cmp( arg, "wanted" ) )
    {
        DB_DATA* wanted = NULL, *next_wanted = NULL;
        cnt = 0;

        for ( wanted = first_wanted; wanted; wanted = next_wanted )
        {
            next_wanted = wanted->next;

            if ( wanted->created_at < ( current_time - ( 60 * 60 * 24 * days ) ) )
            {
                UNLINK( wanted, first_wanted, last_wanted, next, prev );
                delete_dbase_sql( DB_TABLE_WANTED, wanted );
                extract_db( wanted );
                cnt++;
            }
        }

        ch_println( ch, "&zCleaned up &C%'d&z wanted entries.", cnt );
    }

    if ( !str_cmp( arg, "phomes" ) )
    {
        ROOM_INDEX_DATA* room = NULL;
        cnt = 0;

        for ( room = first_room; room; room = room->next )
        {
            if ( !room->phome )
                continue;

            if ( xIS_SET( room->flags, ROOM_EMPTY_HOME ) )
                continue;

            for ( int i = rows - 1; i >= 0; i-- )
            {
                if ( players[i].id == room->phome->owner_id )
                {
                    if ( players[i].last_login < ( current_time - ( 60 * 60 * 24 * days ) ) )
                    {
                        reset_home( room, room->phome );
                        cnt++;
                    }

                    break;
                }
            }
        }

        ch_println( ch, "&zCleaned up &C%'d&z player homes.", cnt );
    }

    if ( qresult ) PQclear( qresult );        
    return;
}

