int offset_prog_vnums( char** str_ptr, int min, int max, int offset )
{
    char buffer[256], tmp1[64], tmp2[64];
    int cnt = 0, len = 0, diflen = 0;

    if ( !str_ptr || NULLSTR( *str_ptr ) )
        return 0;

    snprintf( tmp1, 64, "%d", max );
    snprintf( tmp2, 64, "%d", max + offset );
    diflen = abs( (int)(strlen( tmp2 ) - strlen( tmp1 )) ) + 1;


    len = strlen( *str_ptr ) + ( diflen * 64 ) + 1;
    char* newstr = malloc( len );
    strlcpy( newstr, *str_ptr, len );
    char *p = newstr;

    while ( *p )
    {
        char *start = p;
        int in_parens = 0;

        if ( *p == '(' && isdigit( *( p + 1 ) ) )
        {
            in_parens = 1;
            start = ++p;
        }

        if ( isdigit( *p ) )
        {
            char *num_start = p;

            while ( isdigit( *p ) )
                p++;

            char *num_end = p;

            if ( in_parens && *p == ')' )
                p++;

            char tmp[16] = {0};
            int len = num_end - num_start;
            if ( len >= (int) sizeof( tmp ) )
                len = sizeof( tmp ) - 1;
            strncpy( tmp, num_start, len );
            int value = atoi(tmp);

            if ( value >= min && value <= max )
            {
                int new_value = value + offset;
                snprintf( buffer, sizeof( buffer ), "%s%d%s", in_parens ? "(" : "", new_value, in_parens ? ")" : "");

                // Replace old number (and optional parens) with new one
                int old_len = p - (in_parens ? start - 1 : num_start);
                int new_len = strlen(buffer);
                int tail_len = strlen(p);

                if (new_len != old_len) {
                    memmove((in_parens ? start - 1 : num_start) + new_len, p, tail_len + 1); // move tail including null terminator
                }

                memcpy((in_parens ? start - 1 : num_start), buffer, new_len);
                p = (in_parens ? start - 1 : num_start) + new_len;
                cnt++;
            }
        }
        else
            p++;
    }

    STRFREE( *str_ptr );
    *str_ptr = newstr;
    return cnt;
}

