atomic_long critical_section_start_pulse = ATOMIC_VAR_INIT(0);
long pulse = 0;

#define CRITICAL_SECTION_SAFETY_WINDOW 10

void critical_start() {
    atomic_store(&critical_section_start_pulse, pulse);
    atomic_fetch_add(&critical_section, 1);
}

void critical_end() {
    atomic_fetch_sub(&critical_section, 1);
}

bool is_critical_section() {
    return atomic_load(&critical_section) > 0;
}

long critical_ended_pulses_ago() {
    if(is_critical_section()) {
        return 0;
    } else {
        return pulse - atomic_load(&critical_section_start_pulse);
    }
}

