int is_localhost(const char *ip_address) {
    struct in_addr ipv4;
    struct in6_addr ipv6;

    // Check if the IP address is 127.0.0.1 (IPv4 localhost)
    if (inet_pton(AF_INET, ip_address, &ipv4) == 1) {
        if (ipv4.s_addr == htonl(INADDR_LOOPBACK)) {
            return 1;
        }
    }

    // Check if the IP address is ::1 (IPv6 localhost)
    if (inet_pton(AF_INET6, ip_address, &ipv6) == 1) {
        if (memcmp(&ipv6, &in6addr_loopback, sizeof(in6addr_loopback)) == 0) {
            return 1;
        }
    }

    return 0;
}

int is_rfc1918(const char *ip_address) {
    struct in_addr ipv4;

    // Convert the IP address from text to binary form
    if (inet_pton(AF_INET, ip_address, &ipv4) != 1) {
        return 0;
    }

    // Check for 10.0.0.0 to 10.255.255.255
    if ((ipv4.s_addr & htonl(0xff000000)) == htonl(0x0a000000)) {
        return 1;
    }

    // Check for 172.16.0.0 to 172.31.255.255
    if ((ipv4.s_addr & htonl(0xfff00000)) == htonl(0xac100000)) {
        return 1;
    }

    // Check for 192.168.0.0 to 192.168.255.255
    if ((ipv4.s_addr & htonl(0xffff0000)) == htonl(0xc0a80000)) {
        return 1;
    }

    return 0;
}

void lose_a_life() {
    life++;
    int lives_remaining = extra_lives - life + 1;
    lognormal( "Extra lives remaining: %d", lives_remaining );

    if ( lives_remaining == -1 )
    {
        // schedule copyover
        sysdata.autocopy = AUTOCOPY_NORMAL;
        sysdata.cpy = 60;
        autosave();
        echo_to_all( AT_RED, "COPYOVER IN ONE MINUTE, YOUR CHARACTER HAS BEEN SAVED\n", ECHOTAR_ALL );
    }
    else if ( lives_remaining < -1 )
    {
        char buf[1024];
        snprintf( buf, 1024, "\n *** [ALERT] EMERGENCY COPYOVER, PLEASE STAND BY...\n" );
        copyover( buf, true, true, true );
        lognormal( "Abnormal termination of game, extra lives exhausted." );
        exit( -1 );
    }
}

