int init_socket( int port )
{
    char hostname[64];
    struct sockaddr_in6   sa;
    int x = 1;
    int fd;
    gethostname( hostname, sizeof( hostname ) );

    if ( ( fd = socket( PF_INET6, SOCK_STREAM, 0 ) ) < 0 )
    {
        perror( "Init_socket: socket" );
        exit( 205 );
    }

    if ( setsockopt( fd, SOL_SOCKET, SO_REUSEADDR, ( void* ) &x, sizeof( x ) ) < 0 )
    {
        perror( "Init_socket: SO_REUSEADDR" );
        close( fd );

        exit( 206 );
    }

#if defined(SO_DONTLINGER) && !defined(SYSV)
    {
        struct  linger  ld;
        ld.l_onoff  = 1;
        ld.l_linger = 1000;

        if ( setsockopt( fd, SOL_SOCKET, SO_DONTLINGER, ( void* ) &ld, sizeof( ld ) ) < 0 )
        {
            perror( "Init_socket: SO_DONTLINGER" );
            close( fd );
            exit( 207 );
        }
    }
#endif
    gethostbyname( hostname );
    getservbyname( "service", "mud" );
    memset( &sa, '\0', sizeof( sa ) );
    sa.sin6_family   = AF_INET6; /* hp->h_addrtype; */
    sa.sin6_port     = htons( port );

    /*  this should really not be necessary... or recommended...
        if (sa.sin6_port == 5656 )
        sa.sin6_addr.s6_addr = inet_addr("69.164.219.71"); //Bind to dedicated IP
    */
    if ( bind( fd, ( struct sockaddr* ) &sa, sizeof( sa ) ) == -1 )
    {
        perror( "Init_socket: bind" );
        close( fd );
        exit( 208 );
    }

    if ( listen( fd, 50 ) < 0 )
    {
        perror( "Init_socket: listen" );
        close( fd );
        exit( 209 );
    }

    return fd;
}

