void copyover( char* message, bool emergency, bool nosave, bool bypass )
{
    FILE* fp, *fpl;
    DESCRIPTOR_DATA* d;
    char buf[100], buf2[100], buf3[100], buf4[100] /*buf5[100]*/;
    static int in_progress=0;
    set_alarm( 0 );
    log_critical( "--- Engaging Copyover! ---" );
    fprintf(stderr, "Parameters: message: %s, emergency: %d, nosave: %d, bypass: %d", message, emergency, nosave, bypass);



    if ( !file_exist( sysdata.exe_file ) )
    {
        log_critical( "System executable non-existent, please recompile or wait for it to finish.\n" );
        return;
    }

    if(in_progress)
    {
        fprintf(stderr, "Copyover called while copyover already in progress. Something is really bad. Bailing out.\n");
        exit( 1 );
    }

    in_progress = 1;

    if ( !bypass )
    {
        lognormal( "\n&RProcessing safety checks...\n" );

        for ( d = first_descriptor; d ; d = d->next )
        {
            CHAR_DATA* och = CH ( d );

            if ( d->connected == CON_EDITING )
            {
                lognormal( "&RSorry, a player is in a writing buffer. Please wait for them to finish.\n" );
                return;
            }

            if ( d->connected > CON_PLAYING )
            {
                lognormal( "&RA Player is currently connecting, Please wait.\n" );

                if ( och && och != NULL )
                    lognormal( "&R  Player: &Y%s   &RState: &Y%d\n", och->name, d->connected );

                return;
            }
        }

        lognormal( "\n&RSafety checks cleared...continuing Copyover.\n" );
    }

    fp = fopen ( COPYOVER_FILE, "w" );

    if ( !fp )
    {
        log_critical ( "Could not write to copyover file!" );
        perror ( "copyover:fopen" );
        return;
    }

    set_alarm( 0 );

    snprintf( buf, 100, "\n %s\n", message );

    discord_sendchan(DISCORD_CODING_EMERG, buf);

    /* For each playing descriptor, save its state */
    for ( d = first_descriptor; d; d = d_next )
    {
        CHAR_DATA* och = CH ( d );
        d_next = d->next; /* We delete from the list , so need to save this */

        if ( d && d->descriptor > 3000 )
            continue;

        if ( d && d->is_fake_desc )
            continue;

        if ( !och || !d->character || d->connected > CON_PLAYING ) /* drop those logging on */
        {
            write_to_descriptor ( d->descriptor, "\nWe are rebooting. Please log in after 10 seconds, and sorry if you lost a new character.\n",  0 );
            close_socket ( d, TRUE );
        }
        else
        {

#ifdef CLIENT
            fprintf ( fp, "%d %s %s %s %s %s\n", d->descriptor,
                      och->name, d->host, d->client ? *d->client != '\0' ? d->client : "[unknown]" : "[unknown]", d->ip, CopyoverGet( d ) );
#else
            fprintf ( fp, "%d %s %s %s %s\n", d->descriptor,
                      och->name, d->host, d->ip, CopyoverGet( d ) );
#endif
            write_to_descriptor ( d->descriptor, buf, 0 );
        }
    }

    if ( !nosave )
    {
        save_everything();
    }

    if (!nosave && !emergency ) {
        write_to_log("copyover", buf, sysdata.log_level, 168, true);
        update_publish_status( STATUS_COPYOVER_NOW );
        firehose_write_heartbeat(); // One last off-cycle heartbeat before the copyover

        if ( systemd_watchdog_enabled ) {
            sd_notify( 0, "WATCHDOG=1" );
        }
    }

    // things might be in really bad shape. Don't try to do 
    // graceful things, just pull the ripcord and hope for the best.
    // ~Miros
    if(!emergency) {
        lognormal( "Unloading looms");
        unload_looms();
        lognormal( "Shutting down lua");
        shutdown_lua();
    }

    if ( emergency )
    {
        snprintf( buf, 100, "%secopyover.dat", SYSTEM_DIR );
        fpl = fopen( buf, "w" );
        fprintf( fpl, "This exists solely to tell the recovering mud to be quiet   -Orion\n" );
        fclose( fpl );
    }

    log_critical( "Closing reserve sockets." );
    fprintf ( fp, "-1\n" );
    if ( fp ) fclose ( fp );
    disconnect_db();
    log_critical( "Shutting down Firehose." );
    firehose_shutdown();
    log_critical( "Shutting down MQTT." );
    mqtt_cleanup(); 
    if (!emergency && !nosave) {
        int rake_status = call_rake_db_migrate();

        if (rake_status == 0) {
            lognormal("Rake db:migrate executed successfully.\n");
        } else {
            lognormal("Rake db:migrate failed with status: %d\n", rake_status);
        }
    }
    snprintf( buf, 100, "%d", port );
    snprintf( buf2, 100, "%d", control );
    snprintf( buf3, 100, "%d", control2 );

    strlcpy( buf4, "-1", 100 );

    /*
        close( control  );
        close( control2 );
    */
    dlclose( sysdata.dlHandle );
    signal(SIGPROF, SIG_IGN);
    if(!emergency && !nosave) {
        flush_all_output( FALSE );
    }
    execl ( sysdata.exe_file,  sysdata.exec[0] != '\0' ? sysdata.exec : "swreality", buf, "copyover", buf2, buf3, buf4,/* buf5,*/ ( char* ) NULL );
    /* Failed - successful exec will not return */
 //   execl ( EXE2_FILE, "swbuilder", buf, "copyover", buf2, buf3, buf4,/*buf5,*/ ( char* ) NULL );
    perror ( "copyover: failed to copyover in 'execl'" );
    sysdata.dlHandle = dlopen( NULL, RTLD_LAZY );

    if ( !sysdata.dlHandle )
    {
        bug( "%s", "FATAL ERROR: Unable to reopen system executable handle!" );
        exit( 214 );
    }

    log_critical( "&RCopyover FAILED!" );
}

void send_message_to_descriptors(const char *message)
{
    DESCRIPTOR_DATA *d, *d_next;

    for (d = first_descriptor; d; d = d_next)
    {
        d_next = d->next;

        if (d && d->descriptor > 3000)
            continue;

        write_to_descriptor(d->descriptor, (char*)message, 0);
    }
}

// LAG alarm!                                                   -Thoric
/*
    for lag alarm 2.0, (re-)set a 10 second alarm at the top of every game loop. if the alarm triggers,
    re-set the alarm and echo something to everyone and increment a counter "LAG STRIKE ONE" or something.
    if the counter hits 3, execute a long-jump to the same set-jump we use for the "crash warning."
    If we have a successful trip through the game loop, decrement the counter by 1.
    later if that's not enough we can add a strike 4 which fires an emergency copyover
    this would probably catch most "hang" situations without players getting disconnected
    ~Miros on Discord 1/21/21
*/
static void caught_alarm( )
{
    char buf[MIL];
    lag_strikes++;
    int field_stack_size = get_field_stack_size();
    set_alarm( valgrind_running() ? 120 : 10 );
    log_critical( "ALARM CLOCK!" );

    send_message_to_descriptors("\nPlease stand by...\n");

    snprintf( buf, MIL, "Alas, the hideous malevolent entity known only as 'Lag' rises once more!\n" );
    echo_to_all( AT_IMMORT, buf, ECHOTAR_ALL );

    if ( newdesc )
    {
        FD_CLR( newdesc, &in_set );
        FD_CLR( newdesc, &out_set );
        log_critical( "clearing newdesc" );
    }

    capturebacktrace("lag alarm", NULL, NULL); 

    if ( lag_strikes == 3 )
    {
        lose_a_life();
        if(lua_running()) { 
            // this should never be possible, however, if it were to happen 
            // it would be better to crash in lua than to do the jump here.
            // ~Miros 2/21/24
            _cul_error("C alarm clock under Lua.");
        } else {
            if(critical_ended_pulses_ago() < CRITICAL_SECTION_SAFETY_WINDOW || field_stack_size > 0 )
            {
                snprintf( buf, MIL, "\n *** [ALERT] EMERGENCY COPYOVER - Hang on, we might pull through! *** [CONDITION 3 - CRITICAL]\n" );
                copyover( buf, true, true, true );
                exit( 215 );
            }
        }
    }
    else if ( lag_strikes > 3 )
    {
        if ( emergency_copy == TRUE )
        {
            snprintf( buf, MIL, "\n *** [ALERT] EMERGENCY COPYOVER - Hang on, we might pull through! *** [CONDITION 3]\n" );
            copyover( buf, true, true, true );
        }

        log_critical( "Emergency copyover not ready. Shutting down." );
        exit( -1 );
    }
}

bool check_bad_desc( int desc )
{
    if ( FD_ISSET( desc, &exc_set ) )
    {
        FD_CLR( desc, &in_set );
        FD_CLR( desc, &out_set );
        log_string( "Bad FD caught and disposed." );
        return TRUE;
    }

    return FALSE;
}

void accept_new( int ctrl )
{
    static struct timeval null_time;
    DESCRIPTOR_DATA* d;
    /* int maxdesc; Moved up for use with id.c as extern */
    /*
        Poll all active descriptors.
    */
    FD_ZERO( &in_set  );
    FD_ZERO( &out_set );
    FD_ZERO( &exc_set );
    FD_SET( ctrl, &in_set );
    /* GRAL explicit variable set */
    int maxdesc = ctrl;
    int newdesc = 0;

    for ( d = first_descriptor; d; d = d->next )
    {
        maxdesc = UMAX( maxdesc, d->descriptor );
        FD_SET( d->descriptor, &in_set  );
        FD_SET( d->descriptor, &out_set );
        FD_SET( d->descriptor, &exc_set );

        if ( d->ifd != -1 && d->ipid != -1 )
        {
            maxdesc = UMAX( maxdesc, d->ifd );
            FD_SET( d->ifd, &in_set );
        }

        if ( d->auth_fd != -1 )
        {
            maxdesc = UMAX( maxdesc, d->auth_fd );
            FD_SET( d->auth_fd, &in_set );

            if ( IS_SET( d->auth_state, FLAG_WRAUTH ) )
                FD_SET( d->auth_fd, &out_set );
        }

        if ( d == last_descriptor )
            break;
    }

    auth_maxdesc( &maxdesc, &in_set, &out_set, &exc_set );

    if ( select( maxdesc + 1, &in_set, &out_set, &exc_set, &null_time ) < 0 )
    {
        perror( "accept_new: select: poll" );
        exit( 212 );
    }

    if ( FD_ISSET( ctrl, &exc_set ) )
    {
        bug( "Exception raise on controlling descriptor %d", ctrl );
        FD_CLR( ctrl, &in_set );
        FD_CLR( ctrl, &out_set );
    }
    else if ( FD_ISSET( ctrl, &in_set ) )
    {
        newdesc = ctrl;
        new_descriptor( newdesc );
    }
}

