    set_alarm( 10 );
    sigfpe_strikes++;
    bug( "Caught SIGFPE. Check for divide-by-zero errors!" );

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d_next )
    {
        d_next = d->next;

        if ( d && d->descriptor > 3000 )
            continue;

        write_to_descriptor( d->descriptor, "\nPlease stand by...\n", 0 );
    }

    if ( newdesc )
    {
        FD_CLR( newdesc, &in_set );
        FD_CLR( newdesc, &out_set );
        log_string( "clearing newdesc" );
    }

    capturebacktrace("SIGFPE signal", NULL, NULL);

    if ( sigfpe_strikes < 5 )
    {
        lose_a_life();
        if( lua_running() )
            _cul_error("C alarm clock under Lua.");
        autosave();
        echo_to_all( AT_RED, "\n [ALERT]: ATTEMPTING JUMP - Your character has been saved!\n", ECHOTAR_ALL );
        siglongjmp( place, 4 );        
    }
    else
    {
        if ( emergency_copy == TRUE )
        {
            sigfpe_strikes = 0;
            char buf[1024];
            snprintf( buf, 1024, "\n *** [ALERT] EMERGENCY COPYOVER - Hang on, we might pull through! *** [CONDITION 3]\n" );
            copyover( buf, true, true, true );
        }

        log_string( "Emergency copyover not ready. Shutting down." );
        exit( -1 );
    }
}
static void caught_sigbus( )
{
    log_string( "--- SIGBUS SIGNAL ---" );
    crash_notify();

    /* Are we allowing an emergency copyover? */
    if ( !sysdata.ECOPYOVER )
        log_string( "Emergency copyover not enabled. Shutting down." );
    else if ( emergency_copy == TRUE )
    {
        sigsegv = TRUE;
        emergency_copy = FALSE;
        char buf[MIL];
        snprintf( buf, MIL, "\n *** [ALERT] EMERGENCY COPYOVER - Hang on, we might pull through! *** [CONDITION 1 - CRITICAL]\n" );
        copyover( buf, true, true, true );
        exit( 215 );
    }
    else
        log_string( "Emergency copyover not ready. Shutting down." );

    exit( 215 );
}
static void caught_sigusr( int signum )
{
    log_string( "Caught SIGUSR.\n" );

    if ( signum == SIGUSR1 )
    {
        // schedule copyover
        sysdata.autocopy = AUTOCOPY_NORMAL;
        sysdata.cpy = 60;
        autosave();
        echo_to_all( AT_RED, "COPYOVER IN ONE MINUTE, YOUR CHARACTER HAS BEEN SAVED\n", ECHOTAR_ALL );
    }
    else if ( signum == SIGUSR2 )
    {
        char buf[1024];
        snprintf( buf, 1024, "\n *** [ALERT] EMERGENCY COPYOVER, PLEASE STAND BY...\n" );
        copyover( buf, true, true, true );
        lognormal( "Abnormal termination of game, SIGUSR2 emergency copyover failed" );
        exit( -1 );
    }
}

