#define MICROSECONDS_PER_SECOND 1000000

long microseconds_to_next_interval(int intervals_per_second) {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    long microseconds_per_pulse = MICROSECONDS_PER_SECOND / intervals_per_second;
    long microseconds = current_time.tv_sec * MICROSECONDS_PER_SECOND + current_time.tv_nsec / 1000;
    long remainder = microseconds % microseconds_per_pulse;
    return microseconds_per_pulse - remainder;
}

void game_loop( void )
{
    struct timeval        last_time;
    clock_t               last_time_clocks;
    char cmdline[MIL];
    DESCRIPTOR_DATA* d;
    time_t      last_check = 0;
    struct timeval last_systemd_watchdog;

    //  signal( SIGPIPE, SIG_IGN );
    //  signal( SIGALRM, caught_alarm );
    // signal( SIGSEGV, SegVio );
    if ( sigsegv == TRUE )
        init_signals2();
    else
        init_signals1();

    gettimeofday( &last_time, NULL );
    last_time_clocks = clock();


    if ( systemd_watchdog_enabled )
    {
        lognormal( "Systemd watchdog is enabled." );
        debug( "Updating systemd watchdog." );
        gettimeofday( &last_systemd_watchdog, NULL );
        sd_notify( 0, "WATCHDOG=1" );
    }
    else
    {
        lognormal( "Systemd watchdog is not enabled." );
    }

    current_time = ( time_t ) last_time.tv_sec;
    memset( &stall_time, 0, sizeof(clock_t)*STALL_AVERAGE );

    /* Main loop */
    do
    {
        // Trip free'd memory At the top of each game loop
        malloc_trim( 0 );
        pulse++;
        if( critical_ended_pulses_ago() == CRITICAL_SECTION_SAFETY_WINDOW) {
            log_string("Critical section safety window has ended.");
        }
        last_time_clocks = clock();
        int time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;
        debug("%s: Top of loop. time_remaining: %dms", __FUNCTION__, time_remaining);

        reset_locale();
        set_alarm( valgrind_running() ? 120 : 10 );
        accept_new( control  );
        accept_new( control2 );
        firehose_accept( );
        firehose_read();
        auth_check( &in_set, &out_set, &exc_set );

        time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;

        debug("%s: finished top of loop, about to do commands. time_remaining: %dms", __FUNCTION__, time_remaining);

        // Kick out descriptors with raised exceptions
        // or have been idle, then check for input.
        for ( d = first_descriptor; d; d = d_next )
        {
            if ( d->character )
                set_locale( d->character );

            if ( d->character )
            {
                if ( d->character->played_update <= 0 && d->character->logon > 0 )
                {
                    d->character->played += ( current_time - d->character->logon );
                    d->character->played_update = current_time;
                }
                else if ( d->character->played_update > 0 )
                {
                    d->character->played += current_time - d->character->played_update;
                    d->character->played_update = current_time;
                }
            }

            if ( d == d->next )
            {
                bug( "descriptor_loop: loop found & fixed" );
                d->next = NULL;
            }

            d_next = d->next;
            d->idle++;  /* make it so a descriptor can idle out */

            if ( FD_ISSET( d->descriptor, &exc_set ) )
            {
                FD_CLR( d->descriptor, &in_set  );
                FD_CLR( d->descriptor, &out_set );

                if ( d->character && ( d->connected == CON_PLAYING || d->connected == CON_EDITING ) && valid_char( d->character ) )
                    save_char_obj( d->character, true );

                d->outtop   = 0;
                close_socket( d, TRUE );
                continue;
            }
            else if ( ( !d->character && d->idle > 360 )         /* 2 mins  */
                      || ( d->connected != CON_PLAYING && d->connected != CON_EDITING && d->idle > 1200 ) ) /* 5 mins  */
            {
                write_to_descriptor( d->descriptor, "Idle time-out...disconnecting.\n", 0 );

                if ( d->account )
                {
                    d->account->t_points = 0;
                    xREMOVE_BIT( d->account->flags, ACC_PURCHASE );
                }

                d->outtop   = 0;
                close_socket( d, TRUE );
                continue;
            }
            else if ( d->idle >= 2400 && d->character && !IS_NPC( d->character ) && has_pcflag( d->character, PCFLAG_AUTOAFK ) && ( d->character->pcdata->cooldown == -1 || ( d->character->pcdata->cooldown >= 0 && d->character->pcdata->botting == 0 ) ) && !has_pcflag( d->character, PCFLAG_AFK ) )
            {
                send_to_desc_color(  "\n&RAuto-AFK Activating after 10 minutes!\n", d );
                if ( !IS_IMMORTAL( d->character ) )
                {
                    interrupt_ch( d->character );
                    do_visible( d->character, "-noalert" );
                }

                for ( OBJ_DATA* obj = d->character->last_carrying; obj; obj = obj->prev_content )
                    if ( obj->item_type == ITEM_TRANSMITTER && obj->value[IVAL_TRANSMITTER_STATE] != 0 )
                        deactivate_transmitter( d->character, obj );

                set_pcflag( d->character, PCFLAG_AFK );
                write_to_descriptor( d->descriptor, "You are now afk.\n", 0 );

                if ( IS_IMMORTAL( d->character ) )
                {
                    for ( CHAR_DATA* vch = d->character->in_room->first_person; vch; vch = vch->next_in_room )
                    {
                        if ( vch != d->character && get_trust( vch ) >= get_trust( d->character ) )
                            ch_printf( vch, "%s is now afk.", d->character->name );
                    }
                }
                else
                    act( AT_GREY, "$n is now afk.", d->character, NULL, NULL, TO_ROOM );
            }
            else
            {
                d->fcommand = FALSE;

                if ( FD_ISSET( d->descriptor, &in_set ) )
                {
                    d->idle = 0;

                    if ( d->character )
                        d->character->timer = 0;

                    if ( !read_from_descriptor( d ) )
                    {
                        FD_CLR( d->descriptor, &out_set );

                        if ( d->character && ( d->connected == CON_PLAYING || d->connected == CON_EDITING ) && valid_char( d->character ) )
                            save_char_obj( d->character, true );

                        d->outtop   = 0;
                        close_socket( d, FALSE );
                        continue;
                    }
                }
                if ( d->character && d->character->wait > 0 )
                {
                    --d->character->wait;
                    continue;
                }

                bool read_again = true;
                int buffer_lines_read = 0;

                while ( read_again )
                {
                    read_from_buffer( d );
                    read_again = false;

                    if ( !NULLSTR( d->incomm ) )
                    {
                        d->fcommand     = TRUE;

                        if ( d->pProtocol != NULL )
                            d->pProtocol->WriteOOB = 0;

                        stop_idling( d->character );
                        strlcpy( cmdline, d->incomm, MIL );
                        d->incomm[0] = '\0';

                        if ( d->character )
                            set_cur_char( d->character );

                        if ( d->pagepoint )
                            set_pager_input( d, cmdline );
                        else
                            switch ( d->connected )
                            {
                                default:
                                    nanny( d, cmdline );
                                    break;

                                case CON_PLAYING:
                                    // debug("ccin cmdline %s",cmdline);
                                    interpret( d->character, cmdline, FALSE );
                                    // Always update MSDP after a player takes action. This helps a lot with mapping.
                                    msdp_update_one_player( d );
                                    show_commprompt( d );
                                    break;

                                case CON_EDITING:
                                    edit_buffer( d->character, cmdline, buffer_lines_read > 0 );
                                    buffer_lines_read++;

                                    // Allow processing up to 200 lines in a buffer at once.
                                    if ( buffer_lines_read < 200 )
                                        read_again = true;

                                    break;
                            }
                    }
                }
            }

            if ( d == last_descriptor )
                break;
        }

        time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;

        debug("%s: finished commands. time_remaining: %dms", __FUNCTION__, time_remaining);

        // Autonomous game motion.
        if ( sysdata.interport )
            mud_recv_message();

        time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;

        update_handler( time_remaining - 50 ); // reserve 50ms

        time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;

        debug("%s: finished update_handler. time_remaining: %dms", __FUNCTION__, time_remaining);

        // Output.
        flush_all_output( TRUE );

        time_remaining = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        time_remaining = time_remaining * 1000 / CLOCKS_PER_SEC;

        debug("%s: finished output. time_remaining: %dms", __FUNCTION__, time_remaining);

        /*
            Synchronize to a clock.
            Sleep( last_time + 1/PULSE_PER_SECOND - now ).
            Careful here of signed versus unsigned arithmetic.
        */

        /* Check every 5 seconds...  (don't need it right now)*/
        if ( last_check + 60 < current_time )
        {
            if ( last_check != 0 )
            {
                if ( sigsegv == TRUE )
                {
                    emergency_arm();
                    init_signals1();
                    sigsegv = FALSE;
                }
            }

            last_check = current_time;
        }

        if(pulse > 20)
            increment_counter( &sysdata.metrics, "pulses", NO_FLAG );

        struct timeval now_time;

        gettimeofday( &now_time, NULL );

        stall_time[stall_position] = last_time_clocks + CLOCKS_PER_SEC / PULSE_PER_SECOND - clock();

        if ( stall_time[stall_position] > 0 )
        {
            if ( lag_strikes > 0 && number_range(1,2) == 2 )
                lag_strikes--;
            else
                lag_strikes = 0; // not sure how this would be less than zero, but better to be safe ~Miros

            // sometimes we might sleep a little less if it gives us a chance to align with
            // even intervals of the second. this will give us a more consistent pulse
            long sleep_micros = stall_time[stall_position] * 1000000 / CLOCKS_PER_SEC;

            ///// these three lines should never end up with anything between them
            long jam_micros = microseconds_to_next_interval(PULSE_PER_SECOND);
            sleep_micros = UMIN(sleep_micros,jam_micros);
            usleep(sleep_micros);
            ///// because it could throw off our timing by a little bit. ~Miros

            debug( "game_loop: short pulse %.2fms", sleep_micros / 1000.0 );
            stall_time[stall_position] = sleep_micros * CLOCKS_PER_SEC / 1000000;
            if(pulse > 20)
                set_gauge( &sysdata.metrics, "stall_time", sleep_micros / 1000.0 );
        }
        else
        {
            debug( "game_loop: long pulse %.2fms", stall_time[stall_position] * 1000.0 / CLOCKS_PER_SEC );
            increment_counter( &sysdata.metrics, "long_pulse", NO_FLAG );
        }

        stall_position = ( stall_position + 1 ) % STALL_AVERAGE;

        gettimeofday( &last_time, NULL );
        current_time = ( time_t ) last_time.tv_sec;
    } while ( !mud_down );

    return;
}

DESCRIPTOR_DATA* init_descriptor( int desc )
{
    DESCRIPTOR_DATA* dnew = NULL;
    CREATE( dnew, DESCRIPTOR_DATA, 1 );
    dnew->descriptor    = desc;
    dnew->connected     = CON_GET_NAME;
    dnew->outsize       = HIGHBAND_MAX_BUFFER;
    dnew->scrlen        = 24;
    SET_STRING( dnew->user, "unknown" );
#ifdef CLIENT
    SET_STRING( dnew->client, "[unknown]" );
#endif
    dnew->prevcolor     = 0x07;
    dnew->pProtocol     = ProtocolCreate();
    dnew->ifd           = -1;
    dnew->ipid          = -1;
    dnew->auth_fd       = -1;
    CREATE( dnew->outbuf, char, dnew->outsize );
    LINK( dnew, first_descriptor, last_descriptor, next, prev );
    return dnew;
}

