        // Set the send buffer size to something small so that local 
        // behaves a bit more like prod for socket debugging
        if (setsockopt(desc, SOL_SOCKET, SO_SNDBUF, &sendbuf_size, sizeof(sendbuf_size)) == -1) {
            perror("setsockopt: SO_SNDBUF");
            return;
        } else {
            lognormal("Set send buffer size to %d", sendbuf_size);
        }
    }*/


    if ( check_bad_desc( new_desc ) )
        return;

    dnew = init_descriptor( desc );
    increment_counter( &sysdata.metrics, "connections", NO_FLAG );
    // the use of log_buf here is definitely not a good idea.
    // not sure where that came from, but it should be fixed. ~Miros
    inet_ntop( AF_INET6, &sock.sin6_addr, log_buf, MIL );

    if ( IN6_IS_ADDR_V4MAPPED( &sock.sin6_addr ) )
    {
        int i = 6;

        do
        {
            i++;
            log_buf[i - 7] = log_buf[i];
        } while ( log_buf[i] != '\0' );
    }

    SET_STRING( dnew->host, log_buf );
    SET_STRING( dnew->hostip, log_buf );
    SET_STRING( dnew->ip, log_buf );
    SET_STRING( dnew->newpassword, "" );

    if ( !sysdata.NO_NAME_RESOLVING )
    {
        strlcpy( buf, in_dns_cache( log_buf ), MSL );

        if ( NULLSTR( buf ) )
            resolve_dns( &sock, size );
        else
            SET_STRING( dnew->host, buf );
    }

    snprintf( hostname, MSL, "%s", from ? from->h_name : "" );
    inet_ntop( AF_INET6, &sock.sin6_addr, buf, sizeof( buf ) );

    /* Check for site banning */
    for ( pban = first_ban; pban; pban = pban->next )
    {
        if ( ( !str_prefix( pban->name, dnew->host ) || !str_prefix( pban->name, hostname ) )
                &&  pban->level >= LEVEL_SUPREME )
        {
            snprintf( buf, MSL, "Banning system rejected connection from %s", dnew->host );
            log_string_plus( buf, LOG_NORMAL, sysdata.log_level );
            write_to_descriptor( desc,
                                     "\n(Y)our site has been banned from Star Wars: Legends of the Jedi.\n.\n",
                                     0 );
            write_to_descriptor( desc,
                                     "&z(&YI&z)f you'd like to go about getting the ban lifted, please email admin@legendsofthejedi.com.&w\n",
                                     0 );
            free_desc( dnew );
            return;
        }
    }

    ProtocolNegotiate( dnew );
#ifdef CLIENT
    // Terminal detect
    write_to_buffer( dnew, ( char* ) do_termtype_str, 0 );
#endif

    // Send the greeting.
    if ( dnew->reqstatus == FALSE )
    {
        extern char* help_greeting;

        if ( help_greeting )
        {
            if ( help_greeting[0] == '.' )
                send_to_desc_color( help_greeting + 1, dnew );
            else
                send_to_desc_color( help_greeting, dnew );
        }
        else
        {
            send_to_desc_color( " &RGreeting missing!&z\n", dnew );
        }

        if ( sysdata.cgtime > 0 )
            send_to_desc_color( "\n&YA capital game is currently open!\n"
                "To participate, log into your account here then choose or create a new character\n"
                "with a name ending in \"CG\".\n\n", dnew );

send_to_desc_color( "&z(&CE&z)nter your character or account name, or type &kNEW&k: ", dnew );

    }

    set_auth( dnew );

    if ( ++num_descriptors > sysdata.maxplayers )
        sysdata.maxplayers = num_descriptors;

    if ( sysdata.maxplayers > sysdata.alltimemax )
    {
        DESCRIPTOR_DATA* d = NULL;
        sysdata.time_of_max = time( 0 );

        sysdata.alltimemax = sysdata.maxplayers;
        snprintf( log_buf, MSL, "New timeline maximum player record: %d.\n", sysdata.alltimemax );
        update_pstats();

        for ( d = first_descriptor ; d ; d = d->next )
            if ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                send_to_char( log_buf, d->character );

        to_channel( log_buf, CHANNEL_MONITOR, "Monitor", LEVEL_IMMORTAL );
        save_sysdata( &sysdata );
    }

    return;
}
// miros was here
bool validate_desc( DESCRIPTOR_DATA* d )
{
    DESCRIPTOR_DATA* rd;

    if ( !d )
        return false;

    for ( rd = first_descriptor; rd; rd = rd->next )
        if ( rd == d )
            return true;

    return false;
}

int free_desc( DESCRIPTOR_DATA* d )
{
    if ( !d )
        return E_LOTJ_MISSING_ARGUMENTS;

    kill_auth( d );

    // Don't try to close fake descriptor sockets
    if ( d->descriptor != -1 )
    {
        close( d->descriptor );
        --num_descriptors;
    }

    FREE_STRUCT( d, descriptor_fields );
    return E_LOTJ_SUCCESS;
}

void close_socket( DESCRIPTOR_DATA* dclose, bool force )
{
    /* GRAL free the outbuf of descriptor somewhere's here? else accumulate 2k x # */
    CHAR_DATA* ch = NULL;
    DESCRIPTOR_DATA* d = NULL;
    bool DoNotUnlink = FALSE;
    int i = 0;

    if ( dclose->ipid != -1 )
    {
        int status;
        kill( dclose->ipid, SIGKILL );
        waitpid( dclose->ipid, &status, 0 );
    }

    if ( dclose->ifd != -1 )
        close( dclose->ifd );

    /* flush outbuf */
    if ( !force && dclose->outtop > 0 )
        flush_buffer( dclose, FALSE );

    /* Say bye to whoever's snooping this descriptor */
    for ( i = 0; i <= 5; i++ )
    {
        if ( dclose->snoop_by[i] )
            write_to_buffer( dclose->snoop_by[i], "Your victim has left the game.\n", 0 );
    }

    /* stop snooping everyone else */
    for ( d = first_descriptor; d; d = d->next )
    {
        for ( i = 0; i <= 5; i++ )
        {
            if ( d->snoop_by[i] == dclose )
                d->snoop_by[i] = NULL;
        }
    }

    /* Check for switched people who go link-dead. -- Altrag */
    if ( dclose->original )
    {
        if ( ( ch = dclose->character ) != NULL )
            do_return( ch, "" );
        else
        {
            bug( "Close_socket: dclose->original without character %s",
                 ( dclose->original->name ? dclose->original->name : "unknown" ) );
            dclose->character = dclose->original;
            dclose->original = NULL;
        }
    }

    ch = dclose->character;

    /* sanity check :( */
    if ( !dclose->prev && dclose != first_descriptor )
    {
        DESCRIPTOR_DATA* dp, *dn;
        bug( "Close_socket: %s desc:%p != first_desc:%p and desc->prev = NULL!",
             ch ? ch->name : d->host, dclose, first_descriptor );
        dp = NULL;

        for ( d = first_descriptor; d; d = dn )
        {
            dn = d->next;

            if ( d == dclose )
            {
                bug( "Close_socket: %s desc:%p found, prev should be:%p, fixing.",
                     ch ? ch->name : d->host, dclose, dp );
                dclose->prev = dp;
                break;
            }

            dp = d;
        }

        if ( !dclose->prev )
        {
            bug( "Close_socket: %s desc:%p could not be found!.",
                 ch ? ch->name : dclose->host, dclose );
            DoNotUnlink = TRUE;
        }
    }

    if ( !dclose->next && dclose != last_descriptor )
    {
        DESCRIPTOR_DATA* dp, *dn;
        bug( "Close_socket: %s desc:%p != last_desc:%p and desc->next = NULL!",
             ch ? ch->name : d->host, dclose, last_descriptor );
        dn = NULL;

        for ( d = last_descriptor; d; d = dp )
        {
            dp = d->prev;

            if ( d == dclose )
            {
                bug( "Close_socket: %s desc:%p found, next should be:%p, fixing.",
                     ch ? ch->name : d->host, dclose, dn );
                dclose->next = dn;
                break;
            }

            dn = d;
        }

        if ( !dclose->next )
        {
            bug( "Close_socket: %s desc:%p could not be found!.",
                 ch ? ch->name : dclose->host, dclose );
            DoNotUnlink = TRUE;
        }
    }

    if ( dclose->character )
    {
        snprintf( log_buf, MSL, "Closing link to %s.", ch->name );
        log_string_plus( log_buf, LOG_COMM, UMAX( sysdata.log_level, ch->top_level ) );
        sql_connect_log( ch->name, dclose->user, dclose->account ? dclose->account->name : "",  dclose->host, get_trust( dclose->character ), FALSE, (ch && ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "" );

        /*
            if ( ch->top_level < LEVEL_DEMI )
              to_channel( log_buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        */
        if ( dclose->connected == CON_PLAYING
                ||   dclose->connected == CON_EDITING )
        {
            if ( IS_IMMORTAL( ch ) )
            {
                for ( CHAR_DATA* vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
                {
                    if ( vch != ch && get_trust( vch ) >= get_trust( ch ) )
                        ch_printf( vch, "%s has lost their link.", ch->name );
                }
            }
            else
                act( AT_ACTION, "$n has lost $s link.", ch, NULL, NULL, TO_ROOM );

            stop_editing( ch, true );
            ch->desc = NULL;
            /* GRAL Set it to something so we don't try and leak 4 bytes sending it prompts */
            dclose->connected = CON_COPYOVER_RECOVER;
        }
        else
        {
            /* clear descriptor pointer to get rid of bug message in log */
            /* GRAL Set it to something so we don't try and leak 4 bytes sending it prompts */
            dclose->connected = CON_COPYOVER_RECOVER;
            dclose->character->desc = NULL;            
            free_char( dclose->character );
            dclose->character = NULL;
        }
    }

    if ( !DoNotUnlink )
    {
        /* make sure loop doesn't get messed up */
        if ( d_next == dclose )
            d_next = d_next->next;

        UNLINK( dclose, first_descriptor, last_descriptor, next, prev );
    }

    if ( dclose->descriptor == maxdesc )
        --maxdesc;

    ProtocolDestroy( dclose->pProtocol );

    if ( dclose->auth_fd != -1 )
        close( dclose->auth_fd );

    free_desc( dclose );
    return;
}

bool read_from_descriptor( DESCRIPTOR_DATA* d )
{
    int iStart, iErr;
    char buf[MSL];
    static char read_buf[MAX_PROTOCOL_BUFFER];
    read_buf[0] = '\0';
    int total_read = 0;
    /* Hold horses if pending command already. */
    /*  lets continue to feed the buffer, so that we can continue to read from the socket.
        if ( !NULLSTR( d->incomm ) )
        return TRUE;
    */
    /* Check for overflow. */
    iStart = strlen( read_buf );

    if ( iStart >= ( int ) sizeof( read_buf ) - 10 )
    {
        snprintf( log_buf, MSL, "%s input overflow!", d->host );
        log_string( log_buf );
        write_to_descriptor( d->descriptor, "\n*** PUT A LID ON IT!!! ***\n", 0 );
        return FALSE;
    }

    for ( ; ; )
    {
        int nRead;
        nRead = read( d->descriptor, read_buf + iStart, sizeof( read_buf ) - 10 - iStart );
#ifdef WIN32
        iErr = WSAGetLastError ();
#else
        iErr = errno;
#endif

        if ( nRead > 0 )
        {
            iStart += nRead;
            total_read += nRead;

            if ( read_buf[iStart - 1] == '\n' || read_buf[iStart - 1] == '\r' )
                break;
        }
        else if ( nRead == 0 )
        {
            if ( str_cmp( d->hostip, "127.0.0.1" ) )
            {
                snprintf( buf, MSL, "EOF encountered on read (%s) Inbuf length of %ld.", ( d->character && d->character->pcdata && !NULLSTR( d->character->pcdata->fakeip ) ) ? d->character->pcdata->fakeip : d->hostip, strlen( read_buf ) );
                log_string_plus( buf, LOG_COMM, sysdata.log_level );
                increment_counter( &sysdata.metrics, "eof_read", FLAG_AUTO_GAUGE );
            }

            return FALSE;
        }
        else if ( iErr == EWOULDBLOCK )
        {
            break;
        }
        else
        {
            perror( "Read_from_descriptor" );
            return FALSE;
        }
    }

    read_buf[iStart] = '\0';

    if ( !stristr( read_buf, "clearstack\r" ) )
    {
        ProtocolInput( d, read_buf, iStart, d->inbuf );
    }
    else
    {
        d->inbuf[0] = '\0';
        d->incomm[0] = '\0';

        if ( d && d->character )
        {
            cmdstack( d->character, "clearstack", "", time( 0 ) );
            sql_cmd_log( d->character, NULL, "clearstack", "", 0, FALSE, TRUE );
            tune( "clearstack by %s", d->character->name );
        }

        write_to_descriptor( d->descriptor, "Stack cleared.\n", 0 );
    }

    add_to_counter( &sysdata.metrics, "bytes_read", total_read, FLAG_AUTO_GAUGE );

    return TRUE;
}

// Transfer one line from input buffer to input line.
void read_from_buffer( DESCRIPTOR_DATA* d )
{
    int i, j, k, iac = 0;
#ifdef CLIENT
    unsigned char* p;
#endif

    // Hold horses if pending command already.
    if ( !NULLSTR( d->incomm ) )
        return;

#ifdef CLIENT

    // Thanks Nick!
    for ( p = ( unsigned char* ) d->inbuf; *p; p++ )
    {
        if ( *p == IAC )
        {
            if ( memcmp
                    ( p, term_call_back_str,
                      sizeof( term_call_back_str ) ) == 0 )
            {
                int       pos = ( char* ) p - d->inbuf; /* where we are in buffer */
                int       len = sizeof( d->inbuf ) - pos - sizeof( term_call_back_str ); /* how much to go */
                char      tmp[100];
                unsigned int x = 0;
                unsigned char* oldp = p;
                d->canclient = TRUE;
                p += sizeof( term_call_back_str );  /* skip TERMINAL_TYPE / IS characters */

                for ( x = 0; x < ( sizeof( tmp ) - 1 ) && *p != 0 /* null marks end of buffer */
                        && *p != IAC;  /* should terminate with IAC */
                        x++, p++ )
                    tmp[x] = *p;

                tmp[x] = '\0';
                SET_STRING( d->client, strlen( smash_space( tmp ) ) > 1 ? smash_space( tmp ) : "[unknown]" );
                p += 2; /* skip IAC and SE */
                len -= strlen( tmp ) + 2;

                if ( len < 0 )
                    len = 0;

                // remove string from input buffer
                memmove( oldp, p, len );
            }   /* end of getting terminal type */
        }   /* end of finding an IAC */
    }

#endif

    // Look for at least one new line.
    for ( i = 0; d->inbuf[i] != '\n' && d->inbuf[i] != '\r' && i < MAX_INBUF_SIZE;
            i++ )
    {
        if ( d->inbuf[i] == '\0' )
            return;
    }

    // Canonical input processing.
    for ( i = 0, k = 0; d->inbuf[i] != '\n' && d->inbuf[i] != '\r'; i++ )
    {
        /* STOP CHANGING !!! */
        if ( k >= MIL - 1 ) // Leave space for string terminator
        {
            write_to_descriptor( d->descriptor, "Line too long.\n", 0 );
            d->inbuf[0] = '\0';
            d->incomm[0] = '\0';
            return;
        }

        if ( d->inbuf[i] == ( signed char ) IAC )
            iac = 1;
        else if ( iac == 1
                  && ( d->inbuf[i] == ( signed char ) DO
                       || d->inbuf[i] == ( signed char ) DONT
                       || d->inbuf[i] == ( signed char ) WILL ) )
            iac = 2;
        else if ( iac == 2 )
        {
            iac = 0;

            if ( d->inbuf[i] == ( signed char ) TERMINAL_TYPE )
            {
                d->canclient = TRUE;

                if ( d->inbuf[i - 1] == ( signed char ) WILL )
                    write_to_buffer( d,
                                     ( const char* )
                                     req_termtype_str, 0 );
            }
        }
        else if ( d->inbuf[i] == '\b' && k > 0 )
            --k;
        else if ( isascii( d->inbuf[i] ) && isprint( d->inbuf[i] ) )
            d->incomm[k++] = d->inbuf[i];
    }

    // Finish off the line.
    if ( k == 0 )
        d->incomm[k++] = ' ';

    d->incomm[k] = '\0';

    // Deal with bozos with #repeat 1000 ...
    if ( k > 1 || d->incomm[0] == '!' )
    {
        if ( d->incomm[0] != '!' && strcmp( d->incomm, d->inlast ) )
        {
            d->repeat = 0;
        }
        else
        {
            if ( ++d->repeat == 20 )
            {
                snprintf( log_buf, MSL, "%s input spamming! (%s)", d->character ? d->character->name : d->host, d->inlast );
                log_string( log_buf );
            }
        }
    }

    // Do '!' substitution.
    if ( d->incomm[0] == '!' )
        strlcpy( d->incomm, d->inlast, MIL );
    else
        strlcpy( d->inlast, d->incomm, MIL );

    // Shift the input buffer.
    while ( d->inbuf[i] == '\n' || d->inbuf[i] == '\r' )
        i++;

    for ( j = 0; ( d->inbuf[j] = d->inbuf[i + j] ) != '\0'; j++ )
        ;

    return;
}

bool flush_output(DESCRIPTOR_DATA *d, bool fPrompt) {
    if(!d) {
        return TRUE;
    }
    if ( d->pagepoint )
    {
        return pager_output( d );
    }
    return flush_buffer(d, fPrompt);
}

void flush_all_output(bool prompt) {
    DESCRIPTOR_DATA *d, *d_next;
    for ( d = first_descriptor; d; d = d_next )
    {
        d_next = d->next;

        if ( d->character )
            set_locale( d->character );

        if ( ( d->fcommand || d->outtop > 0 || d->truncated > 0 )
                &&   FD_ISSET( d->descriptor, &out_set ) )
        {
            if(!flush_output(d, prompt)) {
                if ( d->character
                        && ( d->connected == CON_PLAYING
                                ||   d->connected == CON_EDITING ) && valid_char( d->character ) )
                    save_char_obj( d->character, true );

                d->outtop   = 0;
                close_socket( d, FALSE );
                continue;
            }
        }

        if ( d == last_descriptor )
            break;
    }
}

// Low level output function.
bool flush_buffer(DESCRIPTOR_DATA* d, bool fPrompt)
{
    extern bool mud_down;
    CHAR_DATA* ch;
    int i = 0;

    if(!d) {
        return TRUE;
    }

    // Handle fake descriptors safely - they don't need buffer flushing to sockets
    // Check both the flag and the magic descriptor value for safety
    if (d->is_fake_desc || d->descriptor == -1) {
        debug( "flush_buffer: Skipping fake descriptor (flag=%s, desc=%d)", 
               d->is_fake_desc ? "TRUE" : "FALSE", d->descriptor );
        return TRUE;
    }

    ch = d->original ? d->original : d->character;

    if(d->outtop == 0 && d->truncated > 0) {
        write_to_buffer(d, " ", 0); // Flush the truncation message
    }

    // Bust a prompt if needed
    if (d->pProtocol && !d->pProtocol->WriteOOB && fPrompt && !mud_down && d->connected == CON_PLAYING)
    {
        if (has_pcflag(ch, PCFLAG_COMMPROMPT))
        {
            if (has_pcflag(ch, PCFLAG_BLANK))
                write_to_buffer(d, "\n", 2);

            if (has_pcflag(ch, PCFLAG_PROMPT))
                display_prompt(d);

            if (has_pcflag(ch, PCFLAG_TELNET_GA) && d->pProtocol && !d->pProtocol->bSGA)
                write_to_buffer(d, (char*)GoAheadStr, 0);
        }
    }

    // If the buffer is empty, return early.
    if (d->outtop <= 0) {
        d->outtop = 0;
        return TRUE;
    }

    int err = 0;
    ssize_t retval = 0;
    ssize_t bytes_written = low_level_write(d->descriptor, d->outbuf, d->outtop, &err, &retval);

    // If the write was successful, adjust the buffer accordingly
    if (bytes_written > 0)
    {
        // Handle snooping
        for (i = 0; i <= 5; i++)
        {
            if (d->snoop_by[i])
            {
                if (d->character && d->character->name)
                {
                    char snoopbuf[HIGHBAND_CHUNK_SIZE];
                    if (d->original && d->original->name)
                        snprintf(snoopbuf, HIGHBAND_CHUNK_SIZE, "%s (%s)", d->character->name, d->original->name);
                    else
                        snprintf(snoopbuf, HIGHBAND_CHUNK_SIZE, "%s", d->character->name);

                    write_to_buffer(d->snoop_by[i], snoopbuf, 0);
                }

                write_to_buffer(d->snoop_by[i], "% ", 2);
                write_to_buffer(d->snoop_by[i], d->outbuf, bytes_written);
            }
        }

        // Shift the buffer and adjust outtop
        if (bytes_written < d->outtop)
        {
            memmove(d->outbuf, d->outbuf + bytes_written, d->outtop - bytes_written);
            d->outtop -= bytes_written;
            debug("%s: Partial write - Flushed %d bytes from the buffer", FUNC, bytes_written);
        }
        else
        {
            // All data was written, clear the buffer
            d->outtop = 0;
        }
    }

    // If the socket can't handle more data, just return true, we'll flush it later
    if (retval == -1 && (err == EAGAIN || err == EWOULDBLOCK))
    {
        return TRUE;
    }

    // If a critical error occurred, clear the buffer and return false
    if (retval == -1)
    {
        d->outtop = 0;
        return FALSE;
    }

    return TRUE;
}



// Append onto an output buffer.
int write_to_buffer(DESCRIPTOR_DATA* d, const char* buf, int length)
{
    char* txt;
    int len;

    if (!d)
    {
        bug("Write_to_buffer: NULL descriptor");
        return -1;
    }


    if (!d->outbuf || !d->pProtocol)
        return -1;

    buf = ProtocolOutput(d, buf, &length);

    if (d->pProtocol && d->pProtocol->WriteOOB > 0)
        --d->pProtocol->WriteOOB;

    if (NULLSTR(buf) || length <= 0)
        return -1;

    len = length + 1;
    txt = (char*)malloc(len);
    if (!txt)
    {
        bug("write_to_buffer: memory allocation failed");
        return -1;
    }
    strlcpy(txt, buf, len);

    if (block_profane(d->character))
        profanity_filter(txt);

    // Initial \n if needed.
    if (d->outtop == 0 && !d->fcommand && d->pProtocol && !d->pProtocol->WriteOOB)
    {
        d->outbuf[0] = '\n';
        d->outbuf[1] = '\r';
        d->outtop = 2;
    }

    // Check if previous truncations need to be reported
    if (d->truncated > 0)
    {
        char trunc_msg[64];
        snprintf(trunc_msg, sizeof(trunc_msg), "\n\r\n\rTruncated %d lines.\n\r\n\r", d->truncated);

        int trunc_len = strlen(trunc_msg);
        if (d->outtop + trunc_len >= (int)d->outsize)
        {
            // Not enough space to add the truncation message; drop it
            d->truncated += 1;
        }
        else
        {
            // Add the truncation message to the buffer
            strlcpy(d->outbuf + d->outtop, trunc_msg, trunc_len + 1);
            d->outtop += trunc_len;
            d->truncated = 0;
        }
    }

    size_t buffer_max_size = IS_HIGHBAND(d) ? HIGHBAND_MAX_BUFFER : LOWBAND_MAX_BUFFER;

    // Expand the buffer as needed.
    while (d->outtop + length >= (int)d->outsize)
    {
        if (d->outsize >= buffer_max_size)
        {
            // Calculate how many lines will be truncated
            int lines_to_truncate = 0;
            for (int i = 0; i < length; ++i)
            {
                if (txt[i] == '\n')
                {
                    lines_to_truncate++;
                }
            }

            // Increment the truncated counter
            d->truncated += lines_to_truncate;

            // Adjust length to fit within the buffer
            length = (d->outsize - d->outtop - 1);
            if (length <= 0)
            {
                free(txt);
                return 0;
            }
            break;
        }

        d->outsize *= 2;
        d->outsize = UMIN(d->outsize, buffer_max_size);
        RECREATE(d->outbuf, char, d->outsize);
    }

    // Adjust the length if the text exceeds available space
    if (length > (int)(d->outsize - d->outtop - 1))
    {
        // Count the truncated lines that won't fit in the buffer
        for (int i = length; i < len - 1; ++i)
        {
            if (txt[i] == '\n')
            {
                d->truncated++;
            }
        }

        length = d->outsize - d->outtop - 1;
    }

    // Copy the text to the buffer and update the top pointer
    strncpy(d->outbuf + d->outtop, txt, length);
    d->outtop += length;
    d->outbuf[d->outtop] = '\0';

    free(txt);
    return length;
}



#define BUFFER_SIZE 32768  // Set a larger buffer size. 32k seems to be a sweet spot, don't know why

ssize_t low_level_write(int desc, const char *txt, int length, int *err, ssize_t *retval) {
    char buffer[BUFFER_SIZE];
    ssize_t total_written = 0;   // Count of original characters successfully written
    int buffer_pos = 0;
    int injected_count = 0;      // Count of injected \r characters
    int injected_positions[BUFFER_SIZE];  // Track the positions of injected \r characters

    while (total_written < length) {
        buffer_pos = 0;
        injected_count = 0;

        // Fill the buffer with the remaining data
        for (int i = total_written; i < length && buffer_pos < BUFFER_SIZE; i++) {
            if (txt[i] == '\n') {
                if (buffer_pos < BUFFER_SIZE - 1) {  // Ensure space for \r
                    buffer[buffer_pos++] = '\r';
                    injected_positions[injected_count++] = buffer_pos;
                } else {
                    break;  // Buffer is full, exit loop to write data
                }
            }

            buffer[buffer_pos++] = txt[i];
        }

        // Write the buffer to the descriptor
        ssize_t result = write(desc, buffer, buffer_pos);
        if (result < 0) {
            *err = errno;
            if(*err == EAGAIN || *err == EWOULDBLOCK) {
                increment_counter( &sysdata.metrics, "write_eagain", NO_FLAG );
            } else {
                increment_counter( &sysdata.metrics, "write_errors", NO_FLAG );
            }

            *retval = result;
            add_to_counter( &sysdata.metrics, "bytes_written", total_written, FLAG_AUTO_GAUGE );
            return total_written;
        }

        // Calculate how much of the original data was successfully written
        ssize_t chars_written = result;
        for (int j = 0; j < injected_count; j++) {
            if (injected_positions[j] < result) {
                chars_written--;  // Adjust for injected \r
            }
        }

        total_written += chars_written;
    }

    *err = 0;
    *retval = 0;
    add_to_counter( &sysdata.metrics, "bytes_written", total_written, FLAG_AUTO_GAUGE );
    return total_written;
}

bool write_to_descriptor(int desc, char *txt, int length)
{
    int err;
    ssize_t retval = 0;

    if (length <= 0)
        length = strlen(txt);

    // Handle fake descriptors - they use descriptor = -1
    if (desc == -1)
    {
        return true; // Silently succeed for fake descriptors
    }

    if (desc > 4999)
    {
        fprintf(stderr, "write_to_descriptor: desc out of range [%d]\n", desc);
        return false;
    }

    low_level_write(desc, txt, length, &err, &retval);

    if (retval < 0)
    {
        if (err == EAGAIN || err == EWOULDBLOCK)
        {
            // Non-blocking write failed, truncate and exit
            return true;
        }
        else
        {
            perror("write_to_descriptor");
            return false;
        }
    }

    return true;
}

char* stristr( const char* String, const char* Pattern )
{
    char* pptr, *sptr, *start;

    for ( start = ( char* )String; *start != '\0'; start++ )
    {
        /* find start of pattern in string */
        for ( ; ( ( *start != '\0' ) && ( toupper( *start ) != toupper( *Pattern ) ) ); start++ )
            ;

        if ( '\0' == *start )
            return NULL;

        pptr = ( char* )Pattern;
        sptr = ( char* )start;

        while ( toupper( *sptr ) == toupper( *pptr ) )
        {
            sptr++;
            pptr++;

            /* if end of pattern then pattern was found */

            if ( '\0' == *pptr )
                return ( start );
        }
    }

    return NULL;
}

