    send_to_desc_color( buf2, d ); //Display the last of the buffer to the descriptor. Gathorn 23 April 2017
    strlcpy( buf2, "", MSL );
    //Go down the race list again and display races that have a PRICE + DEPOSIT cost of more than the account points. If no account is being used, it'll display everything that isn't free and isn't app only.
    send_to_desc_color( "\nRaces you lack the required account points to qualify for:\n", d );

