// Deal with sockets that haven't logged in yet.
void nanny( DESCRIPTOR_DATA* d, char* argument )
{
    char logperson[MSL];
    char buf[MSL];
    char buf2[MSL];
    int bnum = 0;
    int abil = 0, cost = 0;
    char arg[MSL];
    char tmp[MSL];
    CHAR_DATA* ch = NULL;
    char* pwdnew;
    char* p;
    int iClass = 0, iFocus = 0;

    BAN_DATA* pban = NULL;
    int ability = 0;
    bool fOld, fakeip = FALSE;
    short chk;
    int cnt = 0, fpnt = 0;
    bool newbie = FALSE;
    ROOM_INDEX_DATA* troom = NULL;
    PLANET_DATA* planet = NULL;
    SKILL_DATA* skill = NULL;
    ACCOUNT_DATA* acc = NULL;

    while ( isspace( *argument ) )
        argument++;

    ch = d->character;

    switch ( d->connected )
    {
        default:
            bug( "Nanny: bad d->connected %d.", d->connected );
            close_socket( d, TRUE );
            return;

        case CON_GET_NAME:
            if ( d->character )
            {
                /* clear descriptor pointer to get rid of bug message in log */
                d->character->desc = NULL;
                free_char( d->character );
                d->character = NULL;
            }
            if ( NULLSTR( argument ) )
            {
                send_to_desc_color( "&z(&CI&z)llegal name, try another.\nName: ", d );
                return;
            }

            if ( d->account && is_number( argument ) )
            {
                ACC_CHAR* cycle = NULL;
                cnt = 1;

                for ( cycle = d->account->first_char; cycle; cycle = cycle->next )
                {
                    if ( atoi( argument ) == cnt )
                    {
                        argument = cycle->name;
                        cnt = -1;
                        break;
                    }

                    cnt++;
                }

                if ( cnt != -1 )
                {
                    send_to_desc_color( "&z(&CN&z)umber out of range.\n", d );
                }
            }

            if ( !check_parse_name( argument, true ) )
            {
                send_to_desc_color( "&z(&CI&z)llegal name, try another.\nName: ", d );
                return;
            }

            // Uppercase first character regardless of droid-style name or not
            argument[0] = UPPER( argument[0] );

            // If this is a droid-style name, with numbers and/or a hyphen, leave their casing intact.
            // Otherwise, capitalize it.
            if ( str_suffix( "cg", argument ) ) // Skip case adjustments for CG characters
                if ( check_parse_name( argument, false ) )
                    strlcpy( argument, capitalize( argument ), MIL );

            if ( is_reserved_name( argument ) )
            {
                send_to_desc_color( "&z(&CT&z)hat name is currently reserved from being used.\nName: ", d );
                return;
            }

            if ( argument[0] == '@' )
            {
                acc = d->account;

                if ( d->account )
                {
                    send_to_desc_color( "You are already logged into an account.\n&z(&CC&z)hoices &w<char name>, new: ", d );
                    return;
                }

                if ( ( acc = get_account( argument + 1 ) ) == NULL )
                {
                    send_to_desc_color( "&zThat account doesn't exist. Make a character and use the ACCOUNT command.\n", d );
                    send_to_desc_color( "&z(&CN&z)ame: ", d );
                    return;
                }

                if ( xIS_SET( acc->flags, ACC_FROZEN ) && acc->level < sysdata.log_level )
                {
                    send_to_desc_color( "&zThat account is frozen. Please speak to the IMMs.\n", d );
                    send_to_desc_color( "&z(&CN&z)ame: ", d );
                    return;
                }

                send_to_desc_color( "&z(&CP&z)assword: ", d );
                d->account = acc;
                d->connected = CON_ACC_PASS;
                return;
            }

            if ( !str_cmp( argument, "New" ) )
            {
                if ( d->newstate == 0 )
                {
                    /* New player */
                    /* Don't allow new players if DENY_NEW_PLAYERS is true */
                    if ( sysdata.DENY_NEW_PLAYERS == TRUE )
                    {
                        snprintf( buf, MSL, "&zThe mud is currently preparing for a reboot.\n" );
                        send_to_desc_color( buf, d );
                        snprintf( buf, MSL, "&zNew players are not accepted during this time.\n" );
                        send_to_desc_color( buf, d );
                        snprintf( buf, MSL, "&zPlease try again in a few minutes.\n" );
                        send_to_desc_color( buf, d );
                        close_socket( d, FALSE );
                    }

                    snprintf(buf, MSL, "\n&z(&CP&z)lease choose a character name that fits our Star Wars roleplay \nenvironment. If your name doesn't follow our naming conventions,\nyou'll be asked to pick a new one later.");
			        send_to_desc_color( buf, d );
                    d->newstate++;
                    d->connected = CON_GET_NAME;
                    return;
                }
                else
                {
                    send_to_desc_color( "&z(&CI&z)llegal name, try another.\n&z(&CN&z)ame: ", d );
                    return;
                }
            }

            if ( account_from_name( argument ) != NULL )
            {
                ACCOUNT_DATA* tacc = account_from_name( argument );

                if ( xIS_SET( tacc->flags, ACC_FROZEN ) )
                {
                    send_to_desc_color( "&RSorry, that character's account is frozen.\n If that is yours please send an e-mail to imms@legendsofthejedi.com to speak to staff.\n", d );
                    send_to_desc_color( "&z(&CN&z)ame: ", d );
                    return;
                }
            }

            if ( check_playing( d, argument, FALSE ) == BERR )
            {
                send_to_desc_color( "&z(&CN&z)ame: ", d );
                return;
            }

            acc = d->account;
            fOld = load_char_obj( d, argument );

            if ( !d->character )
            {
                snprintf( log_buf, MSL, "Bad player file %s@%s.", argument, d->host );
                log_string( log_buf );
                send_to_desc_color( "&z(&CY&z)our player data is corrupt...&z(&CP&z)lease notify &Cadmins@legendsofthejedi.com&z.\n", d );
                close_socket( d, FALSE );
                return;
            }

            ch = d->character;
            set_pcflag( ch, PCFLAG_ANSI );

            if ( !d->host )
            {
                char putin[MSL];
                strlcpy( putin, d->ip, MSL );
                SET_STRING( d->host, putin );
            }

            if ( !sysdata.webclient_enabled && stristr( d->host, sysdata.webclient_address ) && !IS_IMMORTAL( ch ) )
            {
                snprintf( buf, MSL, "Rejected connection from web client." );
                write_to_log( "new_descriptor", buf, sysdata.log_level, 24, true );
                log_string_plus( buf, LOG_NORMAL, sysdata.log_level );
                send_to_desc_color( "\n&z(&CW&z)eb client access to Star Wars: Legends of the Jedi is temporarily disabled.\n", d );
                send_to_desc_color( "\n&zPlease download a MUD client (e.g., Mudlet, MUSHClient) and connect directly.&w\n", d );
                close_socket( d, FALSE );
                return;
            }

            for ( pban = first_ban, bnum = 1; pban; pban = pban->next, bnum++ )
            {
                if ( ( !str_prefix( pban->name, d->host ) || !str_suffix( pban->name, d->host ) ) && pban->level >= ch->top_level && pban->level >= 0 )
                {
                    snprintf( buf, MSL, "User %s rejected from %s by Banning module.<#%d>", argument, d->host, bnum );
                    send_to_desc_color( "\n&z(&CY&z)our site has been banned from this Mud.\n", d );
                    close_socket( d, FALSE );
                    log_string_plus( buf, LOG_COMM, sysdata.log_level );
                    return;
                }
            }

            for ( pban = first_ban; pban; pban = pban->next )
            {
                if ( ( !str_prefix( pban->name, d->host ) || !str_suffix( pban->name, d->host ) ) && ch->top_level >= 101 && pban->level == -1 )
                {
                    snprintf( buf, MSL, "User %s rejected from %s by Immortal Banning module.", argument, d->host );
                    send_to_desc_color( "\n&z(&CY&z)our site has been banned from accessing Immortals.\n", d );
                    close_socket( d, FALSE );
                    log_string_plus( buf, LOG_COMM, sysdata.log_level );
                    return;
                }
            }

#ifdef CLIENT
            /* telnet negotiation asking what their client is */
            write_to_buffer( d, ( char* )do_termtype_str, 0 );
#endif
            chk = check_reconnect( d, argument, FALSE );

            if ( chk == BERR )
                return;

            if ( chk )
            {
                fOld = TRUE;
            }
            else
            {
                if ( wizlock )
                {
                    if ( has_pcflag( ch, PCFLAG_WIZLOCK_APPROVED ) )
                    {
                        send_to_desc_color( "&z(&RT&z)he game is wizlocked, however you can bypass that as your character can.\n", d );
                    }
                    else if ( d->account && xIS_SET( d->account->flags, ACC_WIZLOCK_ACCESS ) )
                    {
                        send_to_desc_color( "&z(&RT&z)he game is wizlocked, however you can bypass as your account allows you to.\n", d );
                    }
                    else if ( IS_RPC( ch ) )
                    {
                        send_to_desc_color( "&z(&RT&z)he game is wizlocked however, you can bypass that as you are RPC or higher.\n", d );
                    }
                    else
                    {
                        send_to_desc_color( "&z(&CT&z)he game is wizlocked. Only immortals can connect now.\n", d );
                        send_to_desc_color( "&z(&CP&z)lease try back later.\n", d );
                        close_socket( d, FALSE );
                        return;
                    }
                }
            }

            if ( ch->failed_login >= 3 )
            {
                send_to_desc_color( "This character is locked due to too many consecutive attempts at logging in with the wrong password. Only an immortal can unlock this character. Please contact one via AIM, or email to admins@legendsofthejedi.com. If you are using this to attempt to disable people's characters or to in any way inflict damage upon another player, your IP has been saved and will be both banned and reported. Please be advised.\n", d );
                return;
            }

            if ( ch->pcdata->logintimeout > 0 )
            {
                long tmp = 0, sec = 0;
                tmp = ch->pcdata->logintimeout - current_time;

                if ( tmp > 0 )
                {
                    sec = tmp;
                    tmp /= 60;
                    tmp = labs( tmp );
                    sec %= 60;
                    ch_println( ch, "Since you were recently made undead, you can't log in for another for %ld minute%s, %ld second%s.", tmp, tmp != 1 ? "s" : "", sec, sec != 1 ? "s" : "" );
                    return;
                }
            }

            if ( !str_suffix( "cg", argument ) )
            {
                if ( sysdata.cgtime > 0 )
                {
                    if ( !d->account && !fOld )
                    {
                        send_to_desc_color( 
                            "&zYou must log into your account using &C@<account name>&z before logging into a\n"
                            "CG character.\n"
                            "Name: ", d );
                        d->connected = CON_GET_NAME;
                        return;
                    }
                }
                else
                {
                    send_to_desc_color( 
                        "&zCharacter names ending in CG can only be used while a capital game is running.\n"
                        "Name: ", d );
                    d->connected = CON_GET_NAME;
                    return;
                }

                if ( !fOld )
                    set_pcflag( ch, PCFLAG_CG );
            }

            if ( fOld )
            {
                if ( d->newstate != 0 )
                {
                    send_to_desc_color( "&z(&CT&z)hat name is currently in use.\n&z(&CP&z)lease try again: ", d );
                    if ( d->character )
                    {
                        d->character->desc = NULL;
                        free_char( d->character );
                        d->character = NULL;
                    }
                    d->account = acc;
                    d->connected = CON_GET_NAME;
                    return;
                }

                /* Old player */
                send_to_desc_color( "&z(&CP&z)assword: ", d );
                ProtocolNoEcho( d, true );
                d->connected = CON_GET_OLD_PASSWORD;
                return;
            }
            else
            {
                send_to_desc_color("\n"
                    "&wNo existing character found by that name.\n"
                    "If you're making a new character, please ensure your name\nfits our immersive Star Wars roleplay environment.\n", d);

                if ( !str_suffix( "cg", argument ) )
                {
                    send_to_desc_color( "\n&Y"
                        "This name ends in CG so you will be placed in the capital game when you finish\n"
                        "character creation.\n", d );
                }

                snprintf( buf, MSL, "\n&w%s? Are you sure? &z(&CY&z/&CN&z) ", argument );
                send_to_desc_color( buf, d );
                d->connected = CON_CONFIRM_NEW_NAME;
                return;
            }

            break;

        case CON_ACC_PASS:
            if ( is_number( argument ) && d->account->resetpassword_date > current_time && d->account->resetpassword == atoi( argument ) && d->account->resetpassword != 0 )
            {
                ProtocolNoEcho( d, true );
                snprintf( buf, MSL, "\n&z(&CM&z)ake sure to pick a new password that can't be easily guessed."
                         "\n&z(&CP&z)ick a good account password for @%s: ", d->account->name );
                send_to_desc_color( buf, d );
                d->connected = CON_GET_NEW_ACC_PASSWORD;
                return;
            }

            if ( !password_matches_hash(  argument, d->account->password ) )
            {
                char buf3[MSL];
                send_to_desc_color( "&zIncorrect account password. Would you like to reset your password?&w\n&wType &CY &wto trigger a password reset email or &CN &wto return to the login screen.\n", d );
                snprintf( buf3, MSL, "WARNING: Invalid account password for account %s", d->account->name );
                log_string_plus( buf3, LOG_COMM, 200 );
                d->connected = CON_RESET_ACC_PASS;
                return;
            }
            else
            {
                ACCOUNT_DATA* acc = d->account;
                DESCRIPTOR_DATA* d2 = NULL;

                // upgrade to crypt(3) hashing of passwords.
                if ( acc->password[0] != '$' )
                {
                    SET_STRING( acc->password, new_password( argument ) );
                    xREMOVE_BIT( acc->flags, ACC_SHA256 );
                    account_save( acc, true );
                }

                /* Ensure they don't dupe account stats, such as making two chars using one set of points. */
                if ( d->account->level < sysdata.log_level )
                    for ( d2 = first_descriptor; d2; d2 = d2->next )
                    {
                        if ( d2 == d )
                            continue;

                        if ( d2->account && d2->account->level >= sysdata.log_level )
                            continue;

                        if ( d2->account && d2->account == d->account && ( !d->character || !is_cg( d->character ) ) )
                        {
                            send_to_desc_color( "&RSomeone is already logged into that account.\n&WIf you are trying to reconnect, please try again in a few minutes once the MUD auto-disconnects your character!.\n", d );
                            close_socket( d, FALSE );
                            return;
                        }
                    }

                d->account->t_points = 0;
                d->account->s_points = 0;
                snprintf( buf, MSL, "\n&z(&CA&z)ccount: &w%s    &z(&CP&z)oints: &w%d\n", acc->name, acc->points );
                send_to_desc_color( buf, d );
                snprintf( buf, MSL, "&z(&CE&z)mail%s:   &w%s\n", acc->emailconfirmed == FALSE ? " (&rNot Confirmed&z)" : " (&gConfirmed&z)", acc->email );
                snprintf( buf, MSL, "&z(&CD&z)iscord UUID%s:   &w%s\n--------------------\n", acc->discordconfirmed == FALSE ? " (&rNot Confirmed&z)" : " (&gConfirmed&z)", acc->discorduuid );
                send_to_desc_color( buf, d );
                send_to_desc_color( "&z(&CC&z)haracters associated with account:\n\n", d );
                print_account_characters( d, d->account );
                snprintf( buf, MSL, "\n&z(&CE&z)nter a command &z(&C#&z/&CName&z/&CNew&z): " );
                send_to_desc_color( buf, d );
                d->connected = CON_GET_NAME;
                return;
            }

            break;

        case CON_RESET_ACC_PASS:
            switch ( *argument )
            {
                case 'y':
                case 'Y':
                    if ( d->account && d->account->emailconfirmed == TRUE && !NULLSTR( d->account->email ) )
                    {
                        int rval;
                        if((rval = account_password_reset_email(d->account)) != E_LOTJ_SUCCESS) {
                            send_to_desc_color("&rFailed to send password reset email. Please try again later.\n", d);
                            lognormal("Error when trying to send password reset email: %d (%s)", rval, lotj_strerror(rval));
                        } else {
                            send_to_desc_color( "&YYou will receive a temporary password to your confirmed email on file.\n", d );
                        }
                    }
                    else
                    {
                        send_to_desc_color( "&wYour account does not have a confirmed email on file. Please email &Cimms@legendsofthejedi.com&w for assistance.\n", d );
                    }

                    send_to_desc_color( "&z(&CN&z)ame:&w\n", d );
                    d->account = NULL;
                    d->connected = CON_GET_NAME;
                    return;

                case 'n':
                case 'N':
                    send_to_desc_color( "&z(&CN&z)ame:&w\n", d );
                    d->account = NULL;
                    d->connected = CON_GET_NAME;
                    return;

                default:
                    send_to_desc_color( "&wType &CY &wto trigger a password reset email or &CN &wto return to the login screen.", d );
                    break;
            }

            break;

        case CON_RESET_CH_PASS:
            d->account = account_from_name( ch->name );

            switch ( *argument )
            {
                case 'y':
                case 'Y':
                    if ( d->account && d->account->emailconfirmed == TRUE && !NULLSTR( d->account->email ) )
                    {
                        int rval;
                        if ( ( rval = ch_password_reset_email( ch) ) != E_LOTJ_SUCCESS )
                        {
                            send_to_desc_color( "&rFailed to send password reset email. Please try again later.\n", d );
                            lognormal( "Error when trying to send password reset email: %d (%s)", rval, lotj_strerror( rval ) );
                        }
                        else {
                            send_to_desc_color( "&YYou will receive a temporary password to your account's confirmed email on file.\n", d );
                            send_to_desc_color( "&z(&CP&z)lease enter your temporary password that you received via email!\n", d );
                        }

                        d->connected = CON_GET_OLD_PASSWORD;
                        return;
                    }
                    else
                    {
                        send_to_desc_color( "&wYour account does not have a confirmed email on file. Please email &Cimms@legendsofthejedi.com&w for assistance.\n", d );
                        send_to_desc_color( "&zGoodbye. Please reconnect to log in again.\n", d );
                        d->character->desc = NULL;
                        close_socket( d, FALSE );
                        return;
                    }

                case 'n':
                case 'N':
                    send_to_desc_color( "&z(&CN&z)ame:\n", d );
                    d->account = NULL;
                    d->connected = CON_GET_NAME;
                    return;

                default:
                    send_to_desc_color( "&z(&CP&z)lease type &CY &zor &CN&z to either reset your password or disconnect.", d );
                    break;
            }

            break;

        case CON_GET_OLD_PASSWORD:
            send_to_desc_color( "\n", d );

            if ( is_number( argument ) && ch->pcdata->resetpwd_date > current_time && ch->pcdata->resetpwd == atoi( argument ) && ch->pcdata->resetpwd != 0 )
            {
                ProtocolNoEcho( d, true );
                snprintf( buf, MSL, "\n&z(&CM&z)ake sure to pick a new password that can't be easily guessed."
                         "\n&z(&CP&z)ick a good character password for %s: ", ch->name );
                send_to_desc_color( buf, d );
                d->connected = CON_GET_NEW_PASSWORD;
                return;
            }

            if ( strlen( argument ) < 5 || !password_matches_hash( argument, ch->pcdata->pwd ) )
            {
                char buf2[MSL];
                send_to_desc_color( "&z(&CW&z)rong character password. Would you like to reset your password?&w\n&wType &CY &wto trigger a password reset email or &CN &wto return to the login screen.\n", d );
                snprintf( buf2, MSL, "WARNING: Invalid password for %s", ch->name );
                log_string_plus( buf2, LOG_COMM, 200 );
                snprintf( buf, MSL, "Address: [%s@%s]", ch->desc->user, ch->desc->host );
                log_string_plus( buf, LOG_COMM, 200 );
                sql_invalid_log( ch->name, ch->desc->user, ch->desc->host, "XXX", get_trust( ch ) );
                d->connected = CON_RESET_CH_PASS;
                return;
            }

            ProtocolNoEcho( d, false );
            ch->failed_login = 0;

            if ( check_playing( d, ch->name, TRUE ) )
                return;

            d->account = account_from_name( ch->name );

            if ( check_multi_name( d, ch->name  ) )
            {
                close_socket( d, FALSE );
                return;
            }

            if ( d->account && d->account->level < sysdata.log_level )
            {
                DESCRIPTOR_DATA* d3 = NULL;

                for ( d3 = first_descriptor; d3; d3 = d3->next )
                {
                    if ( d3->account && d3->account->level < sysdata.log_level )
                        continue;

                    if ( d3 != d && d3->account && d3->account == account_from_name( d->character->name ) )
                    {
                        send_to_desc_color( "&RSorry, someone is already logged in from your account.\n", d );
                        close_socket( d, FALSE );
                        return;
                    }
                }

                d->account->t_points = 0;
                d->account->s_points = 0;
            }

#ifdef CLIENT
            /* telnet negotiation asking what their client is */
            write_to_buffer( d, ( char* )do_termtype_str, 0 );
#endif
            chk = check_reconnect( d, ch->name, TRUE );

            if ( chk == BERR )
            {
                if ( d->character && d->character->desc )
                    d->character->desc = NULL;

                close_socket( d, FALSE );
                return;
            }

            if ( chk == TRUE )
            {
                d->account = account_from_name( d->character->name );
                return;
            }

            // upgrade to crypt(3) password hashing.
            if ( ch->pcdata->pwd[0] != '$' )
            {
                SET_STRING( ch->pcdata->pwd, new_password( argument ) );
                xREMOVE_BIT( ch->pcdata->flags, PCFLAG_SHA256 );
            }

            if ( ch->pcdata->death_recovery_time > current_time && !IS_IMMORTAL( ch ) )
            {
                long remaining = ch->pcdata->death_recovery_time - current_time;
                int hours = remaining / 3600;
                int minutes = (remaining % 3600) / 60;
                int seconds = remaining % 60;
                ch_println( ch, "You are still recovering after being defeated during UFG.\n"
                    "Time remaining: %ld hour%s, %ld minute%s, %ld second%s.",
                    hours, hours == 1 ? "" : "s",
                    minutes, minutes == 1 ? "" : "s",
                    seconds, seconds == 1 ? "" : "s"
                );
                ch_println( ch, "\n"
                    "You may log into a different character in the meantime, though you must still\n"
                    "stay logged out for 30 minutes after being defeated." );
                close_socket( d, FALSE );
                return;
            }

            if ( ch->pcdata->fakeip && ch->pcdata->fakeip[0] != '\0' )
                fakeip = TRUE;

            snprintf( log_buf, MSL, "%s@%s(%s) has connected.", ch->name, fakeip ? ch->pcdata->fakeip : d->host, d->user );

            if ( ch->top_level < LEVEL_DEMI )
            {
                log_string_plus( log_buf, LOG_COMM, ch->top_level );

                if ( ( !fakeip ) && str_cmp( ch->desc->host, ch->last_login ) )
                    log_string_plus( "Player logging in from a new IP.", LOG_COMM, ch->top_level );
            }
            else
                log_string_plus( log_buf, LOG_COMM, ch->top_level );

            snprintf( buf, MSL, "nanny.validateClan_Era%d", sysdata.era );
            if ( sysdata.era > 1 && ch->pcdata && ch->pcdata->clan && !get_dvar_bool( ch->vars, buf, FALSE ) )
            {
                d->connected = CON_VERIFY_CLAN;
                snprintf( buf, MSL, "&z(&RY&z)&wour character was previously in %s during Era %d.\n"
                "That clan has survived as %s in Era %d.\n"
                "You can choose to stay in the clan (and be bound by spyapp) or choose to\n"
                "leave the clan (and not be bound by spyapp because of your old affiliation).\n\n"
                "&z(&CW&z)ould you like to stay in %s? (&CY&z/&CN&z)&w\n",
                ch->pcdata->clan_name, sysdata.era - 1, ch->pcdata->clan->name, sysdata.era, ch->pcdata->clan->name );
                send_to_desc_color( buf, d );
                break;
            }

            HELP_DATA* fmotd = get_help( NULL, "fmotd" );

            if ( fmotd &&
                 ch->skill_level[FORCE_ABILITY] > 1 &&
                 get_trust( ch ) <= LEVEL_HERO &&
                 ( ch->pcdata->fmotd_read < ( current_time - 604800 ) || fmotd->lastedittime > ch->pcdata->fmotd_read ) )
            {
                d->connected = CON_FMOTD;
                send_to_desc_color( "&z(&CF&z)orcer message of the day&z:\n", d );
                do_help( ch, "fmotd" );
                ch->pcdata->fmotd_read = time( 0 );
                send_to_desc_color( "&z(&GH&z)ave you read the Forcer Message of the Day? (&CY&z/&CN&z)&w\n", d );
                break;
            }

            d->connected = CON_PRESS_ENTER;

            /* Gral 101 or LEVEL_DEMI */
            if ( get_trust( ch ) > LEVEL_DEMI )
            {
                d->connected = CON_IMM_INVIS;
                send_to_desc_color( "&z(&GW&z)ould you like to enter the game invisible? (&CY&z/&CN&z)&w\n", d );
            }
            else
            {
                send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
            }

            break;

        case CON_VERIFY_CLAN:
            switch ( *argument )
            {
                case 'y':
                case 'Y':
                    snprintf( buf, MSL, "&z(&RY&z)&wou have chosen to remain in %s. You may leave in the\n"
                    "future but will be bound by spyapp restrictions. Be sure to read HELP SPYAPP\n"
                    "if you haven't already.\n\n", ch->pcdata->clan->name );
                    send_to_desc_color( buf, d );
                    snprintf( buf, MSL, "nanny.validateClan_Era%d", sysdata.era );
                    set_dvar_bool( ch->vars, buf, TRUE, 0 );
                    d->connected = CON_PRESS_ENTER;

                    /* Gral 101 or LEVEL_DEMI */
                    if ( get_trust( ch ) > LEVEL_DEMI )
                    {
                        d->connected = CON_IMM_INVIS;
                        send_to_desc_color( "&z(&GW&z)ould you like to enter the game invisible? (&CY&z/&CN&z)&w\n", d );
                    }
                    else
                    {
                        send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
                    }

                    break;

                case 'n':
                case 'N':
                    snprintf( buf, MSL, "&z(&RY&z)&wou have chosen to leave the %s. You won't be bound by spyapp\n"
                    "simply because of your previous affiliation with %s, and\n"
                    "you can always seek to join %s at some point\n"
                    "in the future.\n\n", ch->pcdata->clan->name, ch->pcdata->clan_name, ch->pcdata->clan->name );
                    send_to_desc_color( buf, d );
                    char hist_buf[MIL];
                    snprintf( hist_buf, MIL, "Left %s (bowed out between eras)", ch->pcdata->clan->name );
                    account_add_to_history( ch, ch->desc ? ch->desc->account : (ch->pcdata ? ch->pcdata->account : NULL), hist_buf );
                    int cnt_ships = relocate_ships( ch, ch->pcdata->clan );
                    int cnt_lockers = relocate_lockers( ch, ch->pcdata->clan );
                    bug( "%s: %s leaving clan %s. Migrated %d ships and %d lockers.", FUNC, ch->name, ch->pcdata->clan->name, cnt_ships, cnt_lockers );
                    remove_from_clan( ch );
                    ch->room_num = ROOM_VNUM_LEAVEACADEMY;
                    ch->in_room = get_room_index( ROOM_VNUM_LEAVEACADEMY );
                    snprintf( buf, MSL, "nanny.validateClan_Era%d", sysdata.era );
                    set_dvar_bool( ch->vars, buf, TRUE, 0 );
                    d->connected = CON_PRESS_ENTER;

                    /* Gral 101 or LEVEL_DEMI */
                    if ( get_trust( ch ) > LEVEL_DEMI )
                    {
                        d->connected = CON_IMM_INVIS;
                        send_to_desc_color( "&z(&GW&z)ould you like to enter the game invisible? (&CY&z/&CN&z)&w\n", d );
                    }
                    else
                    {
                        send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
                    }

                    break;

                default:
                    send_to_desc_color( "&z(&CP&z)lease type &CYes &zor &CNo&z.&w", d );
                    break;
            }

            break;

        case CON_FMOTD:
            switch ( *argument )
            {
                case 'y':
                case 'Y':
                    d->connected = CON_PRESS_ENTER;
                    send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
                    break;

                case 'n':
                case 'N':
                    send_to_desc_color( "&z(&CF&z)orcer message of the day&z:\n", d );
                    do_help( ch, "fmotd" );
                    send_to_desc_color( "&z(&GH&z)ave you read the Forcer Message of the Day? (&CY&z/&CN&z)&w\n", d );
                    break;


                default:
                    send_to_desc_color( "&z(&CP&z)lease type &CYes &zor &CNo&z.&w", d );
                    break;
            }

            break;

        case CON_IMM_INVIS:
            switch ( *argument )
            {
                case 'y':
                case 'Y':

                    if ( get_trust( ch ) == 200 )
                        ch->pcdata->wizinvis = get_trust( ch );
                    set_pcflag( ch, PCFLAG_WIZINVIS );
                    send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
                    d->connected = CON_PRESS_ENTER;

                    break;

                case 'n':
                case 'N':
                    remove_pcflag( ch, PCFLAG_WIZINVIS );
                    send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );
                    d->connected = CON_PRESS_ENTER;
                    break;

                default:
                    send_to_desc_color( "&z(&CP&z)lease type &CYes &zor &CNo&z.&w", d );
                    break;
            }

            break;

        case CON_CONFIRM_NEW_NAME:
            switch ( *argument )
            {
                case 'y':
                case 'Y':
                    ProtocolNoEcho( d, true );
                    snprintf( buf, MSL, "\n&z(&CM&z)ake sure to use a password that can't be easily guessed."
                             "\n&z(&CP&z)&wick a good character password for %s&z:&w ", ch->name );
                    send_to_desc_color( buf, d );
                    d->character->id = 0;
                    d->connected = CON_GET_NEW_PASSWORD;
                    break;

                case 'n':
                case 'N':
                    send_to_desc_color( "&zOk, what IS it, then?&w", d );
                    d->connected = CON_GET_NAME;
                    break;

                default:
                    send_to_desc_color( "&z(&CP&z)lease type &CYes &zor &CNo&z.&w", d );
                    break;
            }

            break;

        case CON_GET_NEW_PASSWORD:
            if ( strlen( argument ) < 5 )
            {
                send_to_desc_color( "&z(&CP&z)&wassword must be at least five characters long.\n&z(&CP&z)assword:&w ", d );
                return;
            }

            pwdnew =  new_password( argument );

            for ( p = pwdnew; *p != '\0'; p++ )
            {
                if ( *p == '~' )
                {
                    send_to_desc_color( "&z(&CN&z)&wew character password not acceptable, try again.\n&z(&CP&z)assword:&w ", d );
                    return;
                }
            }

            SET_STRING( ch->pcdata->pwd, pwdnew );
            if ( ch->pcdata->resetpwd != 0 )
                SET_STRING( d->newpassword, pwdnew );
            send_to_desc_color( "\n&z(&CP&z)&wlease retype the character password to confirm&z:&w ", d );
            d->connected = CON_CONFIRM_NEW_PASSWORD;
            break;

        case CON_CONFIRM_NEW_PASSWORD:

            if ( !password_matches_hash( argument, ch->pcdata->pwd ) )
            {
                send_to_desc_color( "&z(&CP&z)asswords don't match.\n&z(&CR&z)&wetype password for your character&z:&w ", d );
                d->connected = CON_GET_NEW_PASSWORD;
                return;
            }

            if ( ch->pcdata->resetpwd != 0 )
            {
                ch->pcdata->resetpwd = 0;
                ch->pcdata->resetpwd_date = 0;
                xREMOVE_BIT( ch->pcdata->flags, PCFLAG_SHA256 );
                send_to_desc_color( "&z(&CP&z)assword successfully reset. You may now log in with your new password.\n", d );
                send_to_desc_color( "&z(&CP&z)lease enter your new password to log in!\n", d );
                d->connected = CON_GET_OLD_PASSWORD;
                return;
            }

            ProtocolNoEcho( d, false );
            {
                HELP_DATA* pHelp = NULL;
                pHelp = get_help( NULL, "disclaimer" );
                HELP_DATA* pHelp2 = NULL;
                pHelp2 = get_help( NULL, "disclaimer2" );
                HELP_DATA* pHelp3 = NULL;
                pHelp3 = get_help( NULL, "disclaimer3" );

                if ( pHelp != NULL )
                {
                    send_to_desc_color( "\n\n&wLegends of the Jedi: Disclaimer &z[&CPlease read carefully&z]\n&z", d );

