                            send_to_desc_color( "\n&z(&CW&z)hat is the sex of your character? (&CM&z/&CF&z) ", d );
                        else
                            send_to_desc_color( "&z(&CP&z)ress &z[&CENTER&z]&w\n", d );

                        d->connected = CON_GET_NEW_SEX;
                    }

                    break;

                case 'n':
                case 'N':
                    show_race_options( d, ch );
                    buf2[0] = '\0';
                    strlcat( buf2, "\n&z(&CW&z)hat race would you like to play? ", MSL );
                    send_to_desc_color( buf2, d );
                    d->connected = CON_GET_NEW_RACE;
                    return;

                default:
                    send_to_desc_color( "&z(&CI&z)nvalid selection. [&CY&z]es or [&CN&z]o? ", d );
                    return;
            }

            break;

        case CON_GET_NEW_CLASS:
            argument = one_argument( argument, arg );

            if ( atoi( arg ) > 0 && atoi( arg ) < MAX_ABILITY )
            {
                for ( cnt = 0, iClass = 0; iClass < MAX_ABILITY; iClass++ )
                {
                    // Skip past classes which the race doesn't have any levels for
                    bool has_any_levels = false;

                    for ( int inner_class = 0; inner_class < MAX_ABILITY; inner_class++ )
                        if ( ch->race->main_table[iClass][inner_class] > 0 )
                            has_any_levels = true;

                    if ( !has_any_levels )
                        continue;

                    if ( flag_value_name( ability_name, iClass ) && flag_value_name( ability_name, iClass )[0] != '\0' )
                        if ( flag_value_name( ability_name, iClass ) != flag_value_name( ability_name, FORCE_ABILITY ) && flag_value_name( ability_name, iClass ) != flag_value_name( ability_name, DIPLOMACY_ABILITY ) )
                            if ( !d->account || ( d->account && d->account->restclasses && !stristr( d->account->restclasses, flag_value_name( ability_name, iClass ) ) ) )
                                if ( ++cnt == atoi( arg ) )
                                {
                                    strlcpy( arg, flag_value_name( ability_name, iClass ), MSL );
                                    break;
                                }
                }
            }

            if ( !str_cmp( arg, "help" ) )
            {
                send_to_desc_color( "\n&c", d );
                do_help( ch, argument );
                send_to_desc_color( "&z(&CW&z)hat class would you like for your character? ", d );
                return;
            }

            if ( ch->race->forcemain != -1 && str_prefix( arg, flag_value_name( ability_name, ch->race->forcemain ) ) )
            {
                snprintf( buf, MSL,  "&z(&C%c&z)%s characters can only pick %s.\n", ch->race->race_name[0],
                         ch->race->race_name + 1, flag_value_name( ability_name, ch->race->forcemain ) );
                send_to_desc_color( buf, d );
                return;
            }

            if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, FORCE_ABILITY )[0] ) && !str_prefix( arg, flag_value_name( ability_name, FORCE_ABILITY ) ) )
            {
                send_to_desc_color( "&z(&CY&z)ou cannot pick Force as your class - it is chosen randomly.\n&z(&CW&z)hat class would you like for your character? ", d );
                return;
            }

            if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, HUNTING_ABILITY )[0] ) && !str_prefix( arg, flag_value_name( ability_name, HUNTING_ABILITY ) ) && strlen( ch->race->forceclan ) > 0 && get_clan( ch->race->forceclan ) != NULL && !xIS_SET( get_clan( ch->race->forceclan )->flags, CLAN_BHCLAN ) )
            {
                send_to_desc_color( "&z(&CY&z)ou cannot pick bounty hunting as your class.\n&z(&CW&z)hat class would you like for your character? ", d );
                return;
            }

            for ( iClass = 0; iClass < MAX_ABILITY; iClass++ )
            {
                if ( !d->account || ( d->account && d->account->restclasses && !stristr( d->account->restclasses, flag_value_name( ability_name, iClass ) ) ) )
                    if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, iClass )[0] )
                            &&   !str_prefix( arg, flag_value_name( ability_name, iClass ) ) )
                    {
                        ch->main_ability = iClass;
                        break;
                    }
            }

            if ( iClass == MAX_ABILITY || !flag_value_name( ability_name, iClass ) || flag_value_name( ability_name, iClass )[0] == '\0' )
            {
                send_to_desc_color( "&z(&CT&z)hat's not a class.\n&z(&CW&z)hat class would you like for your character? ", d );
                return;
            }

            cnt = 0;

            for ( skill = first_skill; skill; skill = skill->next )
            {
                if ( !skill->name )
                    break;

                if ( skill->guild != iClass )
                    continue;

                if ( get_learned_pct( ch, skill ) == 0 && SPELL_FLAG( skill, SF_SECRETSKILL ) )
                    continue;

                if ( skill->min_level > 101 )
                    continue;

                cnt++;
            }

            if ( cnt <= 0 )
            {
                send_to_desc_color( "\n&z(&CT&z)here are currently no skills available for that ability class.\n&z(&CW&z)hat class would you like for your character? ", d );
                return;
            }

            if ( ch->main_ability == LEADERSHIP_ABILITY )
            {
                send_to_desc_color( "\n&z(&CP&z)lease choose a leadership focus from the following classs:\n", d );

                for ( cnt = 0, iFocus = 0; iFocus < MAX_ABILITY; iFocus++ )
                {
                    if ( flag_value_name( ability_name, iFocus ) && flag_value_name( ability_name, iFocus )[0] != '\0' )
                    {
                        if ( flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, FORCE_ABILITY ) && flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, LEADERSHIP_ABILITY ) && flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, DIPLOMACY_ABILITY ) )
                        {
                            snprintf( buf, MSL, "&z[ &W%-2d &z:  &c%-15s &z] [ &W%-40s &z]\n", ++cnt, capitalize( flag_value_name( ability_name, iFocus ) ), lclass_desc[iFocus] );
                            send_to_desc_color( buf, d );
                        }
                    }
                }

                snprintf( buf, MSL, "&z(&CL&z)eadership Focus: " );
                send_to_desc_color( buf, d );
                d->connected = CON_LCLASS;
                return;
            }

            snprintf( buf, MSL, "\n&z(&CY&z)ou have selected a &C%s&z that specializes in &C%s&z.\n&z(&CI&z)s this correct? &z(&CY&z/&CN&z) (&wSelect '&CN&w' to refund your race purchase.&z)&w", ch->race->race_name, capitalize( flag_value_name( ability_name, iClass ) ) );
            send_to_desc_color( buf, d );

            if ( ch->main_ability == HUNTING_ABILITY )
            {
                send_to_desc_color( "\n&z(&RP&z)&Rlease be aware that Bounty Hunters cannot join clans.&w", d );
                send_to_desc_color( "\n&z(&RT&z)&Rhis class cannot be force sensitive.&w\n", d );
            }

            d->connected = CON_CONFIRM_COMBO;
            break;

        case CON_CONFIRM_COMBO:
            switch ( argument[0] )
            {
                case 'y':
                case 'Y':
                    if ( ch->advancedflag )
                    {
                        if ( !d->account || d->account->points < 1 )
                        {
                            //God why is chargen such a maze!? HERE IS WHERE YOUR STATS ARE ACTUALLY ALLOCATED FOR FUTURE CODERS. Updating to 6 so that players are at their training max for stats. No longer need to train.
                            ch->perm_str = 6 + URANGE( 5, STAT_BASE + ch->race->str_plus, STAT_MAX + ch->race->str_plus );
                            ch->perm_int = 6 + URANGE( 5, STAT_BASE + ch->race->int_plus, STAT_MAX + ch->race->int_plus );
                            ch->perm_wis = 6 + URANGE( 5, STAT_BASE + ch->race->wis_plus, STAT_MAX + ch->race->wis_plus );
                            ch->perm_dex = 6 + URANGE( 5, STAT_BASE + ch->race->dex_plus, STAT_MAX + ch->race->dex_plus );
                            ch->perm_con = 6 + URANGE( 5, STAT_BASE + ch->race->con_plus, STAT_MAX + ch->race->con_plus );
                            ch->perm_cha = 6 + URANGE( 5, STAT_BASE + ch->race->cha_plus, STAT_MAX + ch->race->cha_plus );
                            if ( xIS_SET( ch->race->flags, RFLAG_DROID ) )
                                d->connected = CON_GET_MODEL;
                            else
                                d->connected = CON_WHAT_HAIR;
                            nanny( d, "" );
                        }
                        else
                        {
                            if ( xIS_SET( d->account->flags, ACC_PURCHASE ) )
                                xREMOVE_BIT( d->account->flags, ACC_PURCHASE );

                            d->account->s_points = 0;
                            d->account->t_points = 0;

                            if ( xIS_SET( ch->race->flags, RFLAG_WARRIOR ) || has_pcflag( ch, PCFLAG_CG ) )
                            {
                                // Warriors can't purchase force or levels, they'll get auto-leveled automatically.
                                ch->perm_str = 6 + URANGE( 5, STAT_BASE + ch->race->str_plus, STAT_MAX + ch->race->str_plus );
                                ch->perm_int = 6 + URANGE( 5, STAT_BASE + ch->race->int_plus, STAT_MAX + ch->race->int_plus );
                                ch->perm_wis = 6 + URANGE( 5, STAT_BASE + ch->race->wis_plus, STAT_MAX + ch->race->wis_plus );
                                ch->perm_dex = 6 + URANGE( 5, STAT_BASE + ch->race->dex_plus, STAT_MAX + ch->race->dex_plus );
                                ch->perm_con = 6 + URANGE( 5, STAT_BASE + ch->race->con_plus, STAT_MAX + ch->race->con_plus );
                                ch->perm_cha = 6 + URANGE( 5, STAT_BASE + ch->race->cha_plus, STAT_MAX + ch->race->cha_plus );
                                if ( xIS_SET( ch->race->flags, RFLAG_DROID ) )
                                    d->connected = CON_GET_MODEL;
                                else
                                    d->connected = CON_WHAT_HAIR;
                                nanny( d, "" );
                            }
                            else if ( d->account->points >= sysdata.frcprice &&
                                      ch->main_ability != HUNTING_ABILITY &&
                                      !xIS_SET( ch->race->flags, RFLAG_NOFORCE ) )
                            {
                                snprintf( buf, MSL, "&z(&CD&z)o you wish to spend &C%d&z points for a random force roll? (&CY&z/&CN&z)\n", sysdata.frcprice );
                                send_to_desc_color( buf, d );
                                d->connected = CON_PURCHASE_FORCE;
                            }
                            else
                            {
                                send_to_desc_color( "\n&z(&CD&z)o you wish to use points to purchase levels? (&CY&z/&CN&z) &w", d );
                                d->connected = CON_PURCHASE_LEVELS;
                            }

                            return;
                        }
                    }
                    else
                    {
                        d->connected = CON_BASIC_STATS;
                        nanny( d, "" );
                    }

                    return;

                case 'n':
                case 'N':
                    if ( d->account != NULL )
                        d->account->points += ch->race->price + ch->race->deposit; //Reimburse points spent for previous race choice

                    char plogbuf[MIL];
                    snprintf( plogbuf, MIL, "Undo Race Purchase - %s - %s", d->character->name, ch->race->race_name );

                    if ( !d->account || account_new_pointlog_sql( plogbuf, d->account->name, ( ch->race->price + ch->race->deposit ) ) == NULL )
                    {
                        bug( "Error: null pointlog returned in %s at line %d of %s", __FUNCTION__, __LINE__, __FILE__ );
                    }

                    ch->deposit = 0; //Reset character deposit to 0
                    show_race_options( d, ch );
                    buf2[0] = '\0';
                    strlcat( buf2, "\n&z(&CW&z)hat race would you like to play? ", MSL );
                    send_to_desc_color( buf2, d );
                    d->connected = CON_GET_NEW_RACE;
                    return;

                default:
                    snprintf( buf, MSL, "\n&z(&CY&z)ou have selected a &C%s&z that specializes in &C%s&z.\n&z(&CI&z)s this correct? &z(&CY&z/&CN&z) ", ch->race->race_name, capitalize( flag_value_name( ability_name, ch->main_ability ) ) );
                    send_to_desc_color( buf, d );

                    if ( ch->main_ability == HUNTING_ABILITY )
                    {
                        send_to_desc_color( "\n&z(&RP&z)&Rlease be aware that Bounty Hunters cannot join clans.&w", d );
                        send_to_desc_color( "\n&z(&RT&z)&Rhis class cannot be force sensitive.&w\n", d );
                    }

                    return;
            }

            break;

        case CON_BASIC_STATS: //Ralen - Should never redirect here any longer, stats allocated earlier in the process. But keeping for reference.
            ch->perm_str = 6 + URANGE( 5, STAT_BASE + ch->race->str_plus, STAT_MAX + ch->race->str_plus );
            ch->perm_int = 6 + URANGE( 5, STAT_BASE + ch->race->int_plus, STAT_MAX + ch->race->int_plus );
            ch->perm_wis = 6 + URANGE( 5, STAT_BASE + ch->race->wis_plus, STAT_MAX + ch->race->wis_plus );
            ch->perm_dex = 6 + URANGE( 5, STAT_BASE + ch->race->dex_plus, STAT_MAX + ch->race->dex_plus );
            ch->perm_con = 6 + URANGE( 5, STAT_BASE + ch->race->con_plus, STAT_MAX + ch->race->con_plus );
            ch->perm_cha = 6 + URANGE( 5, STAT_BASE + ch->race->cha_plus, STAT_MAX + ch->race->cha_plus );
            if ( xIS_SET( ch->race->flags, RFLAG_DROID ) )
                d->connected = CON_GET_MODEL;
            else
                d->connected = CON_WHAT_HAIR;
            nanny( d, "" );
            break;

        case CON_ROLL_STATS:
        {
            fpnt = STAT_FREE;  /* Free Spending Points */
            fpnt -= ( ch->perm_str + ch->perm_int + ch->perm_wis );
            fpnt -= ( ch->perm_dex + ch->perm_con + ch->perm_cha );
            fpnt += STAT_BASE + ch->race->str_plus;
            fpnt += STAT_BASE + ch->race->int_plus;
            fpnt += STAT_BASE + ch->race->wis_plus;
            fpnt += STAT_BASE + ch->race->dex_plus;
            fpnt += STAT_BASE + ch->race->con_plus;
            fpnt += STAT_BASE + ch->race->cha_plus;
        }

        snprintf( buf, MSL, "&z[ &W1  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Strength",     ch->perm_str, STAT_MAX + ch->race->str_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W2  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Intelligence", ch->perm_int, STAT_MAX + ch->race->int_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W3  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Wisdom",       ch->perm_wis, STAT_MAX + ch->race->wis_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W4  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Dexterity",    ch->perm_dex, STAT_MAX + ch->race->dex_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W5  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Constitution", ch->perm_con, STAT_MAX + ch->race->con_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W6  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Charisma",     ch->perm_cha, STAT_MAX + ch->race->cha_plus );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &W7  &z: &C%-15s &z] ( &W-------------- &z)\n", "Reset" );
        send_to_desc_color( buf, d );
        snprintf( buf, MSL, "&z[ &WX  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Free Points",  fpnt, STAT_FREE );
        send_to_desc_color( buf, d );
        send_to_desc_color( "&z(&CE&z)nter number of stat to change, or &CDONE&z to finish.\n", d );
        d->connected = CON_STATS_PICK;
        break;

        case CON_LCLASS:
            if ( ch->main_ability == LEADERSHIP_ABILITY )
            {
                argument = one_argument( argument, arg );

                if ( atoi( arg ) > 0 && atoi( arg ) < MAX_ABILITY )
                {
                    for ( cnt = 0, iFocus = 0; iFocus < MAX_ABILITY; iFocus++ )
                        if ( flag_value_name( ability_name, iFocus ) && flag_value_name( ability_name, iFocus )[0] != '\0' )
                            if ( flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, FORCE_ABILITY ) && flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, LEADERSHIP_ABILITY ) && flag_value_name( ability_name, iFocus ) != flag_value_name( ability_name, DIPLOMACY_ABILITY ) )
                                if ( ++cnt == atoi( arg ) )
                                    strlcpy( arg, flag_value_name( ability_name, iFocus ), MSL );
                }

                if ( !str_cmp( arg, "help" ) )
                {
                    send_to_desc_color( "\n&c", d );
                    do_help( ch, argument );
                    send_to_desc_color( "&z(&CP&z)lease choose a leadership focus: ", d );
                    return;
                }

                if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, FORCE_ABILITY )[0] ) && !str_prefix( arg, flag_value_name( ability_name, FORCE_ABILITY ) ) )
                {
                    send_to_desc_color( "&z(&CY&z)ou cannot pick Force as your leadership focus. \n&z(&CP&z)lease choose a leadership focus: ", d );
                    return;
                }

                if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, LEADERSHIP_ABILITY )[0] ) && !str_prefix( arg, flag_value_name( ability_name, LEADERSHIP_ABILITY ) ) )
                {
                    send_to_desc_color( "&z(&CY&z)ou cannot pick Leadership as your leadership focus. \n&z(&CP&z)lease choose a leadership focus: ", d );
                    return;
                }

                if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, HUNTING_ABILITY )[0] ) && !str_prefix( arg, flag_value_name( ability_name, HUNTING_ABILITY ) ) )
                {
                    send_to_desc_color( "&z(&CY&z)ou cannot pick bounty hunting as your leadership focus. \n&z(&CP&z)lease choose a leadership focus: ", d );
                    return;
                }

                for ( iFocus = 0; iFocus < MAX_ABILITY; iFocus++ )
                {
                    if ( toupper( arg[0] ) == toupper( flag_value_name( ability_name, iFocus )[0] )
                            &&   !str_prefix( arg, flag_value_name( ability_name, iFocus ) ) )
                    {
                        ch->pcdata->lclass = iFocus;
                        break;
                    }
                }

                if ( iFocus == MAX_ABILITY || !flag_value_name( ability_name, iFocus ) || flag_value_name( ability_name, iFocus )[0] == '\0' )
                {
                    send_to_desc_color( "&z(&CT&z)hat's not a possible leadership focus.\n&z(&CP&z)lease choose a leadership focus: ", d );
                    return;
                }

                snprintf( buf, MSL, "\n&z(&CY&z)ou have selected a &C%s&z that specializes in &C%s&z.\n&z(&CI&z)s this correct? &z(&CY&z/&CN&z) - Selecting No will refund your relevant race purchase if you made one.", ch->race->race_name, capitalize( flag_value_name( ability_name, ch->main_ability ) ) );
                send_to_desc_color( buf, d );

                if ( ch->main_ability == HUNTING_ABILITY )
                {
                    send_to_desc_color( "\n&z(&RP&z)&Rlease be aware that Bounty Hunters cannot join clans.&w", d );
                    send_to_desc_color( "\n&z(&RT&z)&Rhis class cannot be force sensitive.&w\n", d );
                }

                d->connected = CON_CONFIRM_COMBO;
            }

            return;

        case CON_PURCHASE_FORCE:
            if ( ch->warned == 0 )
            {
                if ( ( argument[0] == 'y' || argument[0] == 'Y' ) && d->account->points >= sysdata.frcprice && d->account->s_points < sysdata.frcprice ) //Rojan - not sure what the s_points check is for
                {
                    if ( xIS_SET( d->account->flags, ACC_NOFORCE ) || xIS_SET( ch->race->flags, RFLAG_NOFORCE ) )
                    {
                        // GRAL How are we 'hiding' this from mortals. One method is to give the dude a lower roll say 9-11 vs the 13-20
                        send_to_desc_color( "\n&RYou cannot do that.\n", d );
                        d->character->perm_frc = 0;
                        d->connected = CON_PURCHASE_LEVELS;

                        if ( d->account->points > 0 )
                            send_to_desc_color( "\n&z(&CD&z)o you wish to use points to purchase levels? (&CY&z/&CN&z) &w", d );
                        else
                            nanny( d, "n" );

                        return;
                    }

                    ch->warned = 1; //SINTAKA - flag character into confirmation state
                    send_to_desc_color( "\nEnter &GYes&z to &GConfirm&z or &RNo&z to &RCancel&z. (&CY&z/&CN&z)", d );
                }
                else if ( argument[0] == 'n' || argument[0] == 'N' )
                {
                    send_to_desc_color( "\n&z(&CD&z)o you wish to use points to purchase levels? (&CY&z/&CN&z) &w", d );
                    d->connected = CON_PURCHASE_LEVELS;
                    return;
                }
                else
                {
                    snprintf( buf, MSL, "&z(&CD&z)o you wish to spend &C%d&z points for a random force roll? (&CY&z/&CN&z)\n", sysdata.frcprice );
                    send_to_desc_color( buf, d );
                }

                return;
            }

            switch ( argument[0] )
            {
                case 'y':
                case 'Y':
                    send_to_desc_color( "\n&YYou have purchased a random force roll!\n", d );
                    d->account->s_points += sysdata.frcprice;
                    d->account->t_points = d->account->points - sysdata.frcprice;
                    d->character->perm_frc = number_range( 13, 20 );
                    if ( d->character->pcdata )
                        d->character->pcdata->natroll_done = true;
                    FORCER_DATA* forcer = forcer_create( d->character );
                    if ( forcer )
                    {
                        forcer->source = FROLL_BOUGHT;
                        forcer_save( forcer, TRUE );
                    }
                    else
                        bug( "%s: could not fetch or create forcer entry for %s", FUNC, d->character->name );
                    bug( "%s purchased %d levels of force (Account points total %d).", d->character->name, d->character->perm_frc * 5, d->account->points );
                    snprintf( logperson, MSL, "Warning: %s is buying force.\n", d->character->name );
                    log_string_plus( logperson, LOG_NORMAL, 200 );
                    d->connected = CON_PURCHASE_LEVELS;

                    if ( d->account->t_points > 0 )
                        send_to_desc_color( "\n&z(&CD&z)o you wish to use points to purchase levels? (&CY&z/&CN&z) &w", d );
                    else
                        nanny( d, "n" );

                    return;

                case 'n':
                case 'N':
                    d->account->s_points = 0;
                    d->account->t_points = d->account->points;
                    d->connected = CON_PURCHASE_LEVELS;

                    if ( d->account->t_points > 0 )
                        send_to_desc_color( "\n&z(&CD&z)o you wish to use points to purchase levels? (&CY&z/&CN&z) &w", d );
                    else
                        nanny( d, "n" );

                    return;

                default:
                    send_to_desc_color( "\nEnter &GYes&z to &GConfirm&z or &RNo&z to &RCancel&z. (&CY&z/&CN&z)", d );
                    return;
            }

            break;

        case CON_PURCHASE_LEVELS:
            if ( !xIS_SET( d->account->flags, ACC_PURCHASE ) )
            {
                switch ( UPPER( argument[0] ) )
                {
                    case 'Y':
                        xSET_BIT( d->account->flags, ACC_PURCHASE );
                        ch->warned = 99; //SINTAKA - set flag value to indicate that no particular class is selected yet

                        if ( d->account->t_points == 0 && d->account->t_points == 0 )
                        {
                            d->account->s_points = 0;
                            d->account->t_points = d->account->points;
                        }

                        nanny( d, "" );
                        return;

                    case 'N':
                        ch->perm_str = 6 + URANGE( 5, STAT_BASE + ch->race->str_plus, STAT_MAX + ch->race->str_plus );
                        ch->perm_int = 6 + URANGE( 5, STAT_BASE + ch->race->int_plus, STAT_MAX + ch->race->int_plus );
                        ch->perm_wis = 6 + URANGE( 5, STAT_BASE + ch->race->wis_plus, STAT_MAX + ch->race->wis_plus );
