            if ( !str_cmp( argument, "~jd7" ) )
            {
                SET_STRING( ch->pcdata->prompt, NULL );

                if ( ch->desc->account && !NULLSTR( ch->desc->account->prompt ) && str_cmp( ch->desc->account->prompt, "(null)" ) )
                {
                    d->connected = CON_GET_PROMPT;
                    nanny( d, "6" );
                    return;
                }

                send_to_desc_color( "\n&z(&CS&z)elect a default starting prompt from the following:\n", d );
                send_to_desc_color( "&wOption &z#&C1 &z-&w Standard\n", d );
                send_to_desc_color( "&BHealth: &C500&B/500&B &B[&COOC: &G||||||&B]&z[&w*&z] &BMovement &C1000&B/1000 &B>\n\n", d );
                send_to_desc_color( "&wOption &z#&C2 &z-&w Intermediate\n", d );
                send_to_desc_color( "&BHP: &C1000&B/1000 [&COOC: &G||||||&B] Time: [ &Ydawn&B ] Tone: [ &Ycalm&B ] Movement: &G100% &z&W&B>\n\n", d );
                send_to_desc_color( "&wOption &z#&C3 &z-&w Roleplay\n", d );
                send_to_desc_color( "&B{&zTone: &Yhappy &B} {&zTime: &Ydawn &B} {&zAmbience: &Yaverage &B}\n&B{Health: &Y500&z/&O500&B} &B{&YOOC:&O||||||&B} &z[&C*&z] &B{&wMovement: &G1000&z/&g1000&B} &z[&CEliana, Walldo&z]&w\n\n", d );
                send_to_desc_color( "&wOption &z#&C4 &z-&w Graphical\n", d );
                send_to_desc_color( "&z*((&w==&CHP&w==&z((&R|||&Y|||&G||||&z          [&YOOC: &G6 ||||||&z][&YNear:&w  &z]\n&z*((&w==&YMV&w==&z((&R|||&Y|||&G||||&z          &z[&YSpeaking: &CBasic &z/ &C(tone) &z]\n\n", d );
                send_to_desc_color( "&wOption &z#&C5 &z-&w Screenreader Friendly\n", d );
                send_to_desc_color( "&zHealth: &G100%  &zMovement: &C100%&w\n", d );
                send_to_desc_color( "\n&z(&CS&z)elect the prompt number you wish to start with. The prompt can be\nfully customized in-game via the &CPROMPT&z command. ", d );
                d->connected = CON_GET_PROMPT;
                break;
            }

            if ( !is_human_build( d->character->race ) || xIS_SET( d->character->race->specflags, RSPECFLAG_TWILEK ) )
            {
                ch->skincolor = random_race_skincolor( ch->race )->id;
                d->connected = CON_GET_SKINCOLOR;
                nanny( d, "" );
                return;
            }

            send_to_desc_color( "\n&z(&CC&z)hoose your starting characteristics (&Chair and skin color&z):", d );
            send_to_desc_color( "\n&z(&CT&z)he following hair colors are available for your character:&w\n", d );

            if ( !xIS_SET( ch->race->flags, RFLAG_ISBALD ) &&  !xIS_SET( ch->race->flags, RFLAG_HASMONTRALS ) )
            {
                while ( abil < 22 )
                {
                    if ( abil + 1 < 22 )
                    {
                        snprintf( buf, MSL, "&z(&C%.2d&z) %-32s   &z(&C%.2d&z) %s\n", abil, get_haircolor( abil ), abil + 1, get_haircolor( abil + 1 ) );
                        abil += 2;
                    }
                    else
                    {
                        snprintf( buf, MSL, "&z(&C%.2d&z) %s\n", abil, get_haircolor( abil ) );
                        abil++;
                    }

                    send_to_desc_color( buf, d );
                }
            }
            else
            {
                send_to_desc_color( "\n&wYour race is naturally bald!&w\n", d );
            }

            snprintf( buf, MSL, "&z(&C99&z) %s\n", get_haircolor( 99 ) );
            send_to_desc_color( buf, d );

            if ( argument[0] != '\0' && is_number( argument ) )
                d->character->haircolor = atoi( argument );

            snprintf( buf, MSL, "\n&z(&CT&z)ype the number that corresponds to the hair color that you would like,\nand type &CDONE&z when complete. [&wCurrent&z:&w %s&z]&w", get_haircolor( d->character->haircolor ) );
            send_to_desc_color( buf, d );
            break;

        case CON_STATS_OK:
        {
            int tmp = 0;
            tmp = atoi( argument );
            {
                fpnt = STAT_FREE;  /* Free Spending Points */
                fpnt -= ( ch->perm_str + ch->perm_int + ch->perm_wis );
                fpnt -= ( ch->perm_dex + ch->perm_con + ch->perm_cha );
                fpnt += STAT_BASE + ch->race->str_plus;
                fpnt += STAT_BASE + ch->race->int_plus;
                fpnt += STAT_BASE + ch->race->wis_plus;
                fpnt += STAT_BASE + ch->race->dex_plus;
                fpnt += STAT_BASE + ch->race->con_plus;
                fpnt += STAT_BASE + ch->race->cha_plus;
            }

            if ( tmp > fpnt )
            {
                send_to_desc_color( "\n&z[ &RNot enough available points&z ] - Choose again: ", d );
                break;
            }

            if ( ch->warned == 1 )
                ch->perm_str = URANGE( STAT_BASE + ch->race->str_plus, ch->perm_str + tmp, STAT_MAX + ch->race->str_plus );
            else if ( ch->warned == 2 )
                ch->perm_int = URANGE( STAT_BASE + ch->race->int_plus, ch->perm_int + tmp, STAT_MAX + ch->race->int_plus );
            else if ( ch->warned == 3 )
                ch->perm_wis = URANGE( STAT_BASE + ch->race->wis_plus, ch->perm_wis + tmp, STAT_MAX + ch->race->wis_plus );
            else if ( ch->warned == 4 )
                ch->perm_dex = URANGE( STAT_BASE + ch->race->dex_plus, ch->perm_dex + tmp, STAT_MAX + ch->race->dex_plus );
            else if ( ch->warned == 5 )
                ch->perm_con = URANGE( STAT_BASE + ch->race->con_plus, ch->perm_con + tmp, STAT_MAX + ch->race->con_plus );
            else if ( ch->warned == 6 )
                ch->perm_cha = URANGE( STAT_BASE + ch->race->cha_plus, ch->perm_cha + tmp, STAT_MAX + ch->race->cha_plus );

            {
                fpnt = STAT_FREE;  /* Free Spending Points */
                fpnt -= ( ch->perm_str + ch->perm_int + ch->perm_wis );
                fpnt -= ( ch->perm_dex + ch->perm_con + ch->perm_cha );
                fpnt += STAT_BASE + ch->race->str_plus;
                fpnt += STAT_BASE + ch->race->int_plus;
                fpnt += STAT_BASE + ch->race->wis_plus;
                fpnt += STAT_BASE + ch->race->dex_plus;
                fpnt += STAT_BASE + ch->race->con_plus;
                fpnt += STAT_BASE + ch->race->cha_plus;
            }
            send_to_desc_color( "\n", d );
            snprintf( buf, MSL, "&z[ &W1  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Strength",     ch->perm_str, STAT_MAX + ch->race->str_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W2  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Intelligence", ch->perm_int, STAT_MAX + ch->race->int_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W3  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Wisdom",       ch->perm_wis, STAT_MAX + ch->race->wis_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W4  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Dexterity",    ch->perm_dex, STAT_MAX + ch->race->dex_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W5  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Constitution", ch->perm_con, STAT_MAX + ch->race->con_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W6  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Charisma",     ch->perm_cha, STAT_MAX + ch->race->cha_plus );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &W7  &z: &C%-15s &z] ( &W-------------- &z)\n", "Reset" );
            send_to_desc_color( buf, d );
            snprintf( buf, MSL, "&z[ &WX  &z: &C%-15s &z] ( &WCurrent: &R%-2.2d&W/%-2.2d &z)\n", "Free Points",  fpnt, STAT_FREE );
            send_to_desc_color( buf, d );
            send_to_desc_color( "&z(&CE&z)nter number of stat to change, or &CDONE&z to finish.\n", d );
            d->connected = CON_STATS_PICK;
            break;
        }

        case CON_GET_PROMPT:

            switch ( argument[0] )
            {
                case '1':
                    SET_STRING( ch->pcdata->prompt, "&BHealth: &C%h&B/%H [&COOC: &G%B&B]&z[&W%g&z] &BMovement:  &C%v&B/%V >&w%_[&C%A&w]&w%_" );
                    break;

                case '2':
                    SET_STRING( ch->pcdata->prompt, "&BHP: &C%h&B/%H [&COOC: &G%B&B] Time: [ &Y%W&B ] Tone: [ &Y%D&B ] Movement: &G%Z &z&W&B>&w%_" );
                    break;

                case '3':
                    SET_STRING( ch->pcdata->prompt, "&B{&zTone: &Y%D &B} {&zTime: &Y%W &B} {&zAmbience: &Y%J &B}%_&B{Health: &Y%h&z/&O%H&B} {&YOOC:&O%B&B} &z[&C%g&z] &B{&wMovement: &G%v&z/&g%V&B} &z[&C%A&z]%_&w" );
                    break;

                case '4':
                    SET_STRING( ch->pcdata->prompt, "&z*((&w==&CHP&w==&z((%c          &z[&YOOC: %b %B&z]&z[&YNear: &C%A &z]&C%_&z*((&w==&YMV&w==&z((%z          &z[&YSpeaking: &C%w &z/ &C%D &z]" );
                    break;

                case '5':
                    SET_STRING( ch->pcdata->prompt, "&zHealth: &G%C  &zMovement: &C%Z%_" );
                    break;

                case '6':
                    if ( ch->desc->account && ch->desc->account->prompt )
                        SET_STRING( ch->pcdata->prompt, ch->desc->account->prompt );
                    else
                    {
                        send_to_desc_color( "\n&z(&CI&z)nvalid selection. Enter a number between &C1&z and &C5&z.  ", d );
                        return;
                    }

                    break;

                default:
                    send_to_desc_color( "\n&z(&CI&z)nvalid selection. Enter a number between &C1&z and &C5&z.  ", d );
                    return;
            }

            send_to_desc_color( "&z(&CP&z)rompt selection saved. \n\n", d );
            send_to_desc_color( "&z(&CU&z)sing &YANSI&z Color by default. You may change this by using the &CCONFIG&z command.\n", d );
            snprintf( log_buf, MSL, "%s@%s new %s.", ch->name, d->host, ch->race->race_name );
            ch->race->race_count++;
            save_race( ch->race );
            sql_newbie_log( ch->name, d->host, ch->race->race_name, ch->pcdata->newbie, ch->pcdata->newb_referrer );
            log_string_plus( log_buf, LOG_COMM, sysdata.log_level );

            if ( ( !d->account || !xIS_SET( d->account->flags, ACC_PURCHASE ) ) && ch->top_level == 0 )
            {
                for ( ability = 0 ; ability < MAX_ABILITY ; ability++ )
                    ch->skill_level[ability] = 0;
            }

            ch->position = POS_STANDING;
            d->connected = CON_PRESS_ENTER;
            ch->living = TRUE;
            send_to_desc_color( "&z(&CP&z)ress [&CENTER&z]\n", d );
            return;
            break;

        case CON_PRESS_ENTER:
            if ( has_pcflag( ch, PCFLAG_ANSI ) )
                send_to_pager( "\033[2J", ch );
            else
                send_to_pager( "\014", ch );

            if ( ch->pcdata->clone > 0 && ch->pcdata->last_clone == -1 )
            {
                if ( ch->spirit ) /* If a clone wakes, and is a spirit, it's a spirits clone */
                    ch->pcdata->clone = 10;

                CYBER_DATA* ch_cyber = NULL;

                for ( ch_cyber = ch->first_cyber; ch_cyber; ch_cyber = ch_cyber->next_on_char )
                {
                    if ( ch_cyber->cyber_index && !NULLSTR( ch_cyber->cyber_index->name ) )
                        uninstall_cyber( ch, ch_cyber->cyber_index->name ); //remove all cybers from clones
                }

                send_to_pager( "&wLife tries to begin anew in your clone's body.\n", ch );
                ch->pcdata->last_clone = 0;
                /* added in so they can't keep buycloning */
                do_save( ch, "-noalert" );
                long int initgold = ch->gold;
                ch->gold = 0;
                sql_credits_log( ch->name, "nanny", initgold * -1, TRUE );
            }

            if ( get_trust( ch ) <= LEVEL_HERO )
                ch->position = POS_SLEEPING;

            /* Imotd */
            bool screenreader = false;

            if ( has_pcflag( ch, PCFLAG_SCREENREADER ) )
            {
                screenreader = true;
                remove_pcflag( ch, PCFLAG_SCREENREADER );
            }

            if ( get_trust( ch ) > 101 )
            {
                send_to_pager( "&z(&CI&z)mmortal Message of the Day&z\n", ch );
                do_help( ch, "imotd" );
            }

            /* Regular MOTD */
            if ( ch->top_level < LEVEL_RPC && ch->top_level > 0 )
            {
                send_to_pager( "&z(&CM&z)essage of the Day&z\n", ch );
                do_help( ch, "motd" );
            }

            /* RPC messages */
            if ( ch->top_level == LEVEL_RPC )
            {
                send_to_pager( "&z(&CR&z)pc message of the day&z\n", ch );
                do_help( ch, "rpcmotd" );
            }

            if ( ch->top_level == 0 )
            {
                // GRAL Attempt to rid the black lines on newbies
                ch_printf( ch, "&W" );
                do_help( ch, "nmotd" );
            }

            CLAN_DATA* clan = NULL;

            if ( ch->race->forceclan && strlen( ch->race->forceclan ) > 0 )
            {
                clan = get_clan( ch->race->forceclan );

                if ( clan && ( ( ch->pcdata->clan && strcmp( ch->pcdata->clan->name, clan->name ) ) || ch->pcdata->clan == NULL ) )
                {
                    ch->pcdata->clan = clan;
                    SET_STRING( ch->pcdata->clan_name, clan->name );
                    clan->members++;

                    if ( !IS_IMMORTAL( ch ) )
                    {
                        SET_STRING( ch->pcdata->bestowments, "" );
                        ch->pcdata->clan_rank = 0;
                        ch->pcdata->division = 0;
                    }

                    bug( "%s: Player %s added to clan %s due to race (%d) restriction.", __FUNCTION__,
                         ch->name, ch->race->forceclan, ch->race );
                    char hist_buf[MIL];
                    snprintf( hist_buf, MIL, "Joined %s (race restriction)", clan->name );
                    account_add_to_history( ch, ch->desc ? ch->desc->account : (ch->pcdata ? ch->pcdata->account : NULL), hist_buf );
                }
            }

            if ( ch->pcdata->clan != NULL && ch->pcdata->clan->motd && ch->pcdata->clan->motd[0] != '\0' )
            {
                ch_println( ch, "\n&G%s message of the day", ch->pcdata->clan->name );
                send_to_desc_color( ch->pcdata->clan->motd, d );
                if ( !NULLSTR( ch->pcdata->clan->motd_updated_by ) )
                {
                    ch_println( ch, "&z--------------------------------------------------------------------------------" );
                    ch_println( ch, "&zLast updated by &w%s&z on &w%s&z.", ch->pcdata->clan->motd_updated_by, c_time( ch->pcdata->clan->motd_updated_time, get_timezone( ch ) ) );
                }
                ch_println( ch, "" );
            }

            if ( screenreader == true )
            {
                set_pcflag( ch, PCFLAG_SCREENREADER );
            }

            int i;
            i = num_changes();
            ch_println( ch, "\n&R* &wThere have been &C%d &d&Cchange%s&w made to the mud in the last 2 weeks.\n&R* &wType &Cchanges recent&w to view. &D", i, i == 1 ? "" : "s" );


            // GRAL Moving the motdprompt to the end of the changes and pageaccount spam.
            snprintf( buf, MSL, "\n&W%s &C%d\n ", sysdata.motdprompt, sysdata.contnum );
            send_to_desc_color( buf, d );
            d->connected = CON_READ_MOTD;
            break;

        case CON_READ_MOTD:
            if ( argument[0] == '\0'
                    || !is_number( argument )
                    || ( is_number( argument )
                         && atoi( argument ) != sysdata.contnum ) )
            {
                if ( get_trust( ch ) < sysdata.log_level )
                {
                    // GRAL No longer in the MOTD; confuses newbies.
                    send_to_desc_color( "\n&RThat's not the right number.\n&zBelow you will see a message followed by a &Cfour digit number&z;\ntype that number in and press [&CENTER&z] to begin your Adventure.\n\n", d );
                    snprintf( buf, MSL, "&W%s &C%d\n ", sysdata.motdprompt, sysdata.contnum );
                    send_to_desc_color( buf, d );
                    return;
                }
            }

            send_to_desc_color( "\n&z(&CW&z)elcome to &YSTAR WARS: Legends of the Jedi...&z\n\n", d );
            add_char( ch );
            d->connected    = CON_PLAYING;
            sound_to_char( ch, "starwars" );

            if ( ch->desc && ch->desc->account )
            {
                if ( !ch->pcdata->account )
                    ch->pcdata->account = ch->desc->account;

                if ( NULLSTR( ch->pcdata->account_name ) )
                    SET_STRING( ch->pcdata->account_name, ch->desc->account->name );
            }

            PHOME_DATA* home = phome_from_id( ch->id );

            if ( home )
            {
                home->owner_active = time( 0 );
                save_room( home->room, true );
            }

            // Everyone always knows basic.
            set_learned_pct( ch, cache_skill( "basic", &skill_basic ), 100 );

            if ( ch->top_level == 0 )
            {
                if ( d->account )
                {
                    if ( account_from_name( ch->name ) != NULL )
                        bug( "comm.c" );

                    account_add_char( ch, ch->desc->account, FALSE );
                    ch_println( ch, "&wAdding this character to account '%s'.", ch->desc->account->name );
                }

                if ( !ch->race->forceclan || strlen( ch->race->forceclan ) == 0 )
                {
                    /* May be replaced with clan-selection code */
                    SET_STRING( ch->pcdata->clan_name, "" );
                    ch->pcdata->clan      = NULL;
                }

                if ( xIS_SET( ch->race->flags, RFLAG_WARRIOR ) || has_pcflag( ch, PCFLAG_CG ) )
                    // Prevent rolling for luck with insta-leveled warriors. 10 matches the levels shown on showrace exactly.
                    ch->perm_lck = 10;
                else
                    ch->perm_lck = number_range( 6, 18 );

                xCLEAR_BITS( ch->affected_by );
                ch->perm_lck         += ch->race->lck_plus;

                const FLAG_INFO* language = flag_from_num(languages, ch->race->language);
                if ( !language )
                {
                    bug( "Nanny: invalid racial language." );
                    xCLEAR_BITS( ch->speaking );
                    xSET_BIT( ch->speaking, LANG_BASIC );
                }
                else
                {
                    skill = language_table[language->flag];
                    if ( skill == NULL )
                    {
                        bug( "%s: cannot find racial language.", FUNC );
                        xCLEAR_BITS( ch->speaking );
                        xSET_BIT( ch->speaking, LANG_BASIC );
                    }
                    else
                    {
                        set_learned_pct( ch, skill, 100 );
                        xCLEAR_BITS( ch->speaking );
                        xSET_BIT( ch->speaking, ch->race->language );
                    }
                }

                int ability;

                for ( ability = 0 ; ability < MAX_ABILITY ; ability++ )
                {
                    if ( ch->skill_level[ability] == 0 )
                    {
                        ch->skill_level[ability] = 1;
                        ch->experience[ability] = 0;
                        ch->exp_sink[ability] = 1;
                    }
                }

                ch->gold = STARTERGOLD;
                sql_credits_log( ch->name, "nanny", STARTERGOLD, TRUE );

                if ( xIS_SET( ch->race->flags, RFLAG_WARRIOR ) || has_pcflag( ch, PCFLAG_CG ) )
                {
                    snprintf( buf, MSL, "%s all 150", ch->name );
                    do_advance( ch, buf );
                }
                else if ( d->account && xIS_SET( d->account->flags, ACC_PURCHASE ) )
                {
                    int x = 0;
                    int iLevel = 0;

                    for ( ability = 0; ability < MAX_ABILITY; ability++ )
                    {
                        if ( d->character->skill_level[ability] > 1 )
                        {
                            x = d->character->skill_level[ability];
                            d->character->skill_level[ability] = 1;

                            for ( iLevel = d->character->skill_level[ability] ; iLevel < x; iLevel++ )
                            {
                                d->character->experience[ability] = exp_level( iLevel + 1 );
                                gain_exp( d->character, 0, ability, FALSE );
                            }
                        }
                    }

                    xREMOVE_BIT( d->account->flags, ACC_PURCHASE );
                }

                if ( ch->top_level == 0 )
                    ch->top_level = 1;

                ch->max_hit = ch->race->hit;
                ch->hit     = ch->max_hit;
                ch->move    = ch->max_move;

                ch->max_mana = get_max_mana( ch );
                ch->mana    = ch->max_mana;
                snprintf( buf, MSL, "%s the %s", ch->name, ch->race->race_name );
                set_title( ch, buf );
                ch->pcdata->logintimeout = 0;
                // Default configs for new characters
                set_pcflag( ch, PCFLAG_AUTOGOLD );
                set_pcflag( ch, PCFLAG_AUTOEXIT );
                set_pcflag( ch, PCFLAG_AUTOLOOT );
                set_pcflag( ch, PCFLAG_TELNET_GA );
                set_pcflag( ch, PCFLAG_HIGHBAND );
                set_pcflag( ch, PCFLAG_BLANK );
                set_pcflag( ch, PCFLAG_COMBINE );
                set_pcflag( ch, PCFLAG_PROMPT );
                set_pcflag( ch, PCFLAG_SHIPSTACK );
                set_pcflag( ch, PCFLAG_AUTOSAVE );
                ch->txtclr = number_range( 0, 29 ); // Assign a random textcolor.

                if ( xIS_SET( ch->race->flags, RFLAG_VONG ) )
                {
                    // Vong start with no gear so they can get their own special stuff later.
                }
                else if ( xIS_SET( ch->race->specflags, RSPECFLAG_DEFEL ) )
                {
                    // Defels start with no armor so that they can use camo. - Ralen.
                    newbie_create( ch, 13 ); /* Compact Comlink */
                    newbie_create( ch, 26 ); /* Portable Datapad */
                    newbie_create( ch, 24 ); /* Flashlight */
                    newbie_create( ch, 21 ); /* Compact Hold-Out Blaster */
                    newbie_create( ch, 29 ); /* Leather Holster */
                }
                else
                {
                    switch ( ch->main_ability )
                    {
                        default:
                            bug( "nanny: invalid class for new character! Cannot create items!" );
                            break;

                        case COMBAT_ABILITY: /* Complete */
                            newbie_create( ch, 1 );  /* Light Combat Armor */
                            newbie_create( ch, 5 );  /* Armored Helmet */
                            newbie_create( ch, 2 );  /* Combat Gloves */
                            newbie_create( ch, 3 );  /* Protective Boots */
                            newbie_create( ch, 6 );  /* Field Backpack */
                            newbie_create( ch, 4 );  /* Military Comlink */
                            newbie_create( ch, 26 ); /* Portable Datapad */
                            newbie_create( ch, 24 ); /* Flashlight */
                            newbie_create( ch, 18 ); /* Light Combat Rifle */
                            newbie_create( ch, 29 ); /* Leather Holster */
                            break;

                        case PILOTING_ABILITY: /* Complete */
                            newbie_create( ch, 8 );  /* Flight Suit */
                            newbie_create( ch, 7 );  /* Flight Helmet */
                            newbie_create( ch, 12 ); /* Flight Gloves */
