                    ch_println( ch, "&z(&CY&z)our description has been set to the default for a &C%s&z. Use &Cdescription&z to customize it.\n", ch->race->race_name );
                }

                if ( !NULLSTR( ch->race->default_history ) )
                {
                    SET_STRING( ch->pcdata->bio, ch->race->default_history );
                    ch_println( ch, "&z(&CY&z)our history has been set to the default for a &C%s&z. Use &Chistory&z to customize it.\n", ch->race->race_name );
                }
            }

            troom = ch->in_room ? ch->in_room : get_room_index( ch->room_num );
            load_droids_sql( ch->id, FALSE );

            /* Routine to check if the player is waking up into a room that used to be part of a now-dead ship.
               If so, plop them either in their clan's capital (if they're in a clan and it has a capital), or
               on the spaceport of a random, publicly accessible planet. */
            SHIPDEATH_DATA* deadship = NULL;
            SHIP_DATA* tShip = NULL;
            if ( ch->pcdata && ch->pcdata->location_type == CHAR_ON_SHIP && ( ( tShip = ship_from_id( ch->pcdata->location_id ) ) == NULL || xIS_SET( tShip->flags, SHIP_DRYDOCK ) ) )
            {
                planet = NULL;
                troom = NULL;

                for ( deadship = last_shipdeath; deadship; deadship = deadship->prev )
                    if ( deadship->ship_id == ch->pcdata->location_id )
                        break;

                if ( deadship )
                {
                    if ( !str_cmp( deadship->location, "system" ) || !str_cmp( deadship->location, "hyperspace" ) )
                    {
                        troom = nearest_safe_hospital( deadship->xpos, deadship->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                        planet = get_planet_from_room( troom );
                    }
                    else if ( !str_cmp( deadship->location, "room" ) )
                    {
                        troom = get_room_index( deadship->vnum );
                        planet = get_planet_from_room( troom );
                        SHIP_DATA* tship = NULL;
                        // See if the ship was on a planet landing pad and send them to the nearest hospital (even if not on that planet)
                        if ( planet && planet->starsystem )
                        {
                            troom = nearest_safe_hospital( planet->starsystem->xpos, planet->starsystem->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                            planet = get_planet_from_room( troom );
                        }
                        // If the ship wasn't on a planet, see if it was on another ship (that still exists)
                        else if ( !planet && troom && ( tship = get_ship_from_room( troom ) ) != NULL )
                        {
                            // If yes, see if that ship is landed somewhere
                            if ( tship->in_room )
                            {
                                // If so, find the nearest hospital to that landing spot
                                troom = tship->in_room;
                                planet = get_planet_from_room( troom );
                                if ( planet && planet->starsystem )
                                {
                                    troom = nearest_safe_hospital( planet->starsystem->xpos, planet->starsystem->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                                    planet = get_planet_from_room( troom );
                                }
                                else
                                {
                                    // I'm only willing to do one ship inside another ship, and no more recursion than that. This isn't a turducken.
                                    troom = NULL;
                                    planet = NULL;
                                }
                            }
                            // If not landed, see if it's in space
                            else if ( tship->starsystem )
                            {
                                // If so, find the nearest hospital to that.
                                troom = nearest_safe_hospital( planet->starsystem->xpos, planet->starsystem->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                                planet = get_planet_from_room( troom );
                            }
                        }
                        // Finally, look to see if the dead ship was nested in a different dead ship...
                        else if ( !planet && troom )
                        {
                            SHIPDEATH_DATA* deadship2 = NULL;
                            for ( deadship2 = last_shipdeath; deadship2; deadship2 = deadship2->prev )
                                if ( troom->vnum >= deadship2->first_room && troom->vnum <= deadship2->last_room )
                                    break;

                            // If yes, see where that dead ship was. This is the last layer of recursion we'll do.
                            if ( deadship2 )
                            {
                                // If they were in space, find the nearest hospital to wherever they were.
                                if ( !str_cmp( deadship2->location, "system" ) || !str_cmp( deadship2->location, "hyperspace" ) )
                                {
                                    troom = nearest_safe_hospital( deadship2->xpos, deadship2->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                                    planet = get_planet_from_room( troom );
                                }
                                // If they were landed, try once to get a hospital from wherever that was.
                                else if ( !str_cmp( deadship2->location, "room" ) )
                                {
                                    troom = get_room_index( deadship2->vnum );
                                    planet = get_planet_from_room( troom );

                                    // See if the ship was on a planet landing pad and send them to the nearest hospital (even if not on that planet)
                                    if ( planet && planet->starsystem )
                                    {
                                        troom = nearest_safe_hospital( planet->starsystem->xpos, planet->starsystem->ypos, ( ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL );
                                        planet = get_planet_from_room( troom );
                                    }
                                }
                            }
                        }
                    }
                }

                // If we couldn't find a hospital on a planet, clear out whatever temp value was assigned to troom
                if ( troom && !planet )
                    troom = NULL;
            }
            else if ( ch->pcdata && ch->pcdata->location_type == CHAR_IN_VEHICLE && vehicle_from_id( ch->pcdata->location_id ) == NULL )
                troom = NULL;
            else if ( ch->pcdata && ch->pcdata->location_type == CHAR_IN_STRUCTURE && structure_from_id( ch->pcdata->location_id ) == NULL )
                troom = NULL;

            if ( !newbie )
            {
                ch->in_room = NULL;
                if ( get_trust( ch ) > 101 )
                    char_to_room( ch, get_room_index( 100 ) );
                else if ( ch->pcdata->release_date > current_time )
                    char_to_room( ch, get_room_index( 6 ) );
                else if ( troom )
                {
                    if ( deadship && planet )
                    {
                        ch_println( ch, "&RAfter you went to sleep, the ship you were on was destroyed." );
                        ch_println( ch, "&RYou were evacuated and transported to a hospital on planet %s,", planet->name );
                        ch_println( ch, "&Rwhere you were admitted, treated, and discharged.&w\n" );
                        snprintf( buf, MSL, "%s (%s) logged into a dead ship (%s). Transported to %s.",
                        ch->name, ( ch->pcdata && ch->pcdata->account && ch->pcdata->account->name ) ? ch->pcdata->account->name : "null", deadship->name, planet->name );
                        write_to_log("deadships", buf, sysdata.log_level, 0, true );
                        bug( buf );
                        DROID_DATA* db = NULL;
                        CHAR_DATA* droid = NULL;
                        db = droid_from_controller( ch->id );
                        if ( db )
                            droid = mob_from_droid( db );

                        if ( db && droid )
                            char_to_room( droid, troom );

                        for ( CHAR_DATA* mob = first_char; mob; mob = mob->next )
                        {
                            if ( !IS_NPC( mob ) )
                                continue;

                            if ( mob == ch )
                                continue;

                            if ( !mob->master )
                                continue;

                            if ( mob->master != ch )
                                continue;

                            if ( mob->in_room && mob->in_room == troom )
                                continue;

                            char_to_room( mob, troom );
                        }
                    }

                    char_to_room( ch, troom );
                }
                else
                {
                    char_to_room( ch, get_room_index( 472 ) );
                    bug( "Character %s (%s) has no starting room on login. Previously quit %s(%s%s. Sending to Room 472.",
                    ch->name, ( ch->pcdata && ch->pcdata->account && ch->pcdata->account->name ) ? ch->pcdata->account->name : "null",
                    ch->pcdata->location_type == CHAR_ON_SHIP ? "on ship (" : ch->pcdata->location_type == CHAR_IN_VEHICLE ? "in vehicle (" : ch->pcdata->location_type == CHAR_IN_STRUCTURE ? "in structure (" : "",
                    deadship ? deadship->name : ch->pcdata->location_id > 0 ? itoa( ch->pcdata->location_id ) : "", ch->pcdata->location_type != CHAR_ON_GROUND ? ")" : "" );
                }
            }

            if ( xIS_SET( ch->race->flags, RFLAG_OWNLANG ) )
            {
                xCLEAR_BITS( ch->speaking );
                xSET_BIT( ch->speaking, ch->race->language );
            }

            if ( !str_prefix( ch->race->race_name, "unused" ) )
            {
                bug( "%s set to human because race %d no longer seems to exist.", ch->name, ch->race );
                ch->race = get_race_by_id( 1 );
            }

            if ( get_eq_char( ch, WEAR_BINDING ) != NULL )
                ch->held = TRUE;

            if ( get_timer( ch, TIMER_SHOVEDRAG ) > 0 )
                remove_timer( ch, TIMER_SHOVEDRAG );

            if ( get_timer( ch, TIMER_PKILLED ) > 0 )
                remove_timer( ch, TIMER_PKILLED );

            do_wake( ch, "" ); //Sintaka - autowake character at login

            /* Automatic IP Logging System */

            if ( ch->desc && ch->pcdata && ch->pcdata->account && ( !ch->desc->account || ch->desc->account != ch->pcdata->account ) )
                ch->desc->account = ch->pcdata->account;

            if ( ch->desc && ch->desc->original )
                sql_connect_log( ch->desc->original->name, ch->desc->user, ch->desc->account ? ch->desc->account->name : "", ch->desc->host, get_trust( ch ), TRUE, (ch && ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "" );
            else
                sql_connect_log( ch->name, ch->desc ? ch->desc->user : "", ( ch->desc && ch->desc->account ) ? ch->desc->account->name : "", ch->desc ? ch->desc->host : ( ch->last_login ? ch->last_login : "" ), get_trust( ch ), TRUE, (ch && ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "" );

            if ( ch->desc && ch->desc->account && ch->desc->account->email )
            {
                int rval;
                if ((rval = rpc_func_add_mailjet_contact(ch->desc->account->name, ch->desc->account->email, NULL, NULL)) != E_LOTJ_SUCCESS) {
                    lognormal( "rpc_func_add_mailjet_contact: %d (%s)", rval, lotj_strerror(rval) );
                }
            }

            if ( ch->pcdata && ch->pcdata->email )
            {
                if ( ( ch->desc && !ch->desc->account ) || ( ch->desc && ch->desc->account && NULLSTR( ch->desc->account->email ) ) || ( ch->desc && ch->desc->account && ch->desc->account->email && str_cmp( ch->desc->account->email, ch->pcdata->email ) ) )
                {
                    int rval;
                    if ((rval = rpc_func_add_mailjet_contact(NULL,ch->pcdata->email, ch->name, NULL)) != E_LOTJ_SUCCESS) {
                        lognormal( "rpc_func_add_mailjet_contact: %d (%s)", rval, lotj_strerror(rval) );
                    }
                }
            }

            if ( ch->hit > 0 )
                ch->hit = ch->max_hit;

            lua_trigger_on_ch_info( ch, "motd" );

            if ( ch->in_room )
                do_look( ch, "auto" );
            else
            {
                char_to_room( ch, get_room_index( 6 ) );
                do_look( ch, "auto" );
            }

            checkBuidty( d );
            mail_count( ch );
            sendMudletGUIInfo( d );
            MXPSendTag( d, "<VERSION>" );
            if (!NULLSTR(d->newpassword)) {
                SET_STRING( ch->pcdata->pwd, d->newpassword );
                ch->pcdata->resetpwd = 0;
                ch->pcdata->resetpwd_date = 0;
                xREMOVE_BIT( ch->pcdata->flags, PCFLAG_SHA256 );
                SET_STRING( d->newpassword, "" );
                char buf4[MSL];
                snprintf( buf4, MSL, "WARNING: Char %s has successfully reset their password via the automated system.", ch->name );
                log_string_plus( buf4, LOG_COMM, 200 );
                save_char_obj( ch, true );
            }
            lua_trigger_on_ch_login( ch, ch->in_room );
            if(ch->pcdata->account) {
                increment_counter( &ch->pcdata->account->metrics, "logins", NO_FLAG );
                account_sync_discord_roles(ch->pcdata->account);
            }
            increment_counter( &ch->metrics, "logins", NO_FLAG );
            account_update( ch );
            if ( ch->pcdata->clan )
            {
                ch->pcdata->roster = get_roster( ch );
                update_roster( ch );
            }

            if ( sysdata.sandbox ) natroll( ch );
            break;
    }

    return;
}

// Parse a name for acceptability.
bool check_parse_name( char* name, bool allow_droid_names )
{
    // Reserved words.
    if ( is_name( name, "all auto someone immortal self god supreme demigod dog guard cityguard cat cornholio spock hicaine hithoric death ass fuck shit piss crap public penis rendar rental trainer quit pirate pirates raven" ) )
        return FALSE;

    // Length Restrictions.
    if ( strlen( name ) <  3 )
        return FALSE;

    if ( strlen( name ) > 20 )
        return FALSE;

    if ( profanity_check( name ) )
        return FALSE;

    /*
        Alphanumerics only.
        Lock out IllIll twits.
    */
    if ( allow_droid_names )
    {
        bool first = true;
        bool has_hyphen = false;
        char* last = NULL;

        for ( char* pc = name; *pc != '\0'; pc++ )
        {
            if ( first )
            {
                // First character must always be a letter
                if ( !isalpha( *pc ) && *pc != '@' )
                    return FALSE;
            }
            else
            {
                if ( *pc == '-' )
                {
                    // Can't have two hyphens in one name
                    if ( has_hyphen )
                        return FALSE;

                    has_hyphen = true;
                }
                else if ( *pc == '@' )
                {
                    // Can't have an @ except for the first letter, in case of account names
                    return FALSE;
                }
                else
                {
                    // Droid names can consist of a-z, 0-9, and -.
                    if ( !isalpha( *pc ) && !isdigit( *pc ) )
                    {
                        return FALSE;
                    }
                }
            }

            last = pc;
            first = false;
        }

        // Can't end with a hyphen
        if ( *last == '-' )
            return FALSE;
    }
    else
    {
        int cnt = 0;
        char* pc;
        bool fIll;
        fIll = TRUE;

        for ( pc = name; *pc != '\0'; pc++ )
        {
            if ( !isalpha( *pc ) && ( cnt > 0 || *pc != '@' ) )
                return FALSE;

            cnt++;

            if ( LOWER( *pc ) != 'i' && LOWER( *pc ) != 'l' )
                fIll = FALSE;
        }

        if ( fIll )
            return FALSE;
    }

    /*
        Code that followed here used to prevent players from naming
        themselves after mobs... this caused much havoc when new areas
        would go in...
    */
    return TRUE;
}

