// Look for link-dead player to reconnect.
short check_reconnect( DESCRIPTOR_DATA* d, char* name, bool fConn )
{
    CHAR_DATA* ch = NULL, *rch = NULL;
    bool skip = FALSE;

    for ( ch = first_char; ch; ch = ch->next )
    {
        if ( !IS_NPC( ch )
                && ( !fConn || !ch->desc )
                &&    ch->name
                &&   !str_cmp( name, ch->name ) )
        {
            if ( fConn && ch->switched )
            {
                send_to_desc_color( "&z(&CA&z)lready playing.\n&z(&CN&z)ame: ", d );
                d->connected = CON_GET_NAME;
                return BERR;
            }

            if ( fConn == FALSE )
                SET_STRING( d->character->pcdata->pwd, ch->pcdata->pwd );
            else
            {
                /* clear descriptor pointer to get rid of bug message in log */
                d->character->desc = NULL;
                free_char( d->character );
                d->character = ch;
                ch->desc         = d;
                ch->timer        = 0;

                if ( ch->in_room )
                {
                    for ( rch = ch->in_room->first_person ; rch ; rch = rch->next )
                        if ( rch == ch )
                            skip = TRUE;

                    if ( !skip )
                    {
                        ch->room_num = ch->in_room->vnum;
                        char_from_room( ch );
                        char_to_room( ch, get_room_index( ch->room_num ) );
                    }
                }
                else
                    char_to_room( ch, get_room_index( ch->room_num ) );

                send_to_desc_color( "&z(&RR&z)econnecting.\n", d );

                if ( !IS_IMMORTAL( ch ) )
                    act( AT_ACTION, "$n has reconnected.", ch, NULL, NULL, TO_ROOM );

                snprintf( log_buf, MSL, "%s@%s(%s) reconnected.", ch->name, d->character->pcdata->fakeip && d->character->pcdata->fakeip[0] != '\0' ? d->character->pcdata->fakeip : d->host, d->user );
                log_string_plus( log_buf, LOG_COMM, UMAX( sysdata.log_level, ch->top_level ) );
                /*
                        if ( ch->top_level < LEVEL_SAVIOR )
                          to_channel( log_buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
                */
                d->connected = CON_PLAYING;
                MXPSendTag( d, "<VERSION>" );
            }

            return TRUE;
        }
    }

    return FALSE;
}

// Function to determine if an IP address is IPv6 or IPv4.
int is_ipv6(const char *ip) {
    return strchr(ip, ':') != NULL;
}

// Function to compare the network prefix of IPv6 addresses or perform an exact match for IPv4 addresses.
int compare_ip_network_prefix(const char *ip1, const char *ip2) {
    if(is_ipv6(ip1) && is_ipv6(ip2)) {
        // IPv6 comparison
        for(int i = 0, colon_count = 0; ip1[i] != '\0' && ip2[i] != '\0'; i++) {
            if(ip1[i] == ':') colon_count++;
            if(ip1[i] != ip2[i] || colon_count == 4) {
                return colon_count == 4;
            }
        }
    } else if (!is_ipv6(ip1) && !is_ipv6(ip2)) {
        // IPv4 comparison
        return strcmp(ip1, ip2) == 0;
    }
    // One is IPv6 and the other is IPv4, so they cannot be from the same network.
    return 0;
}


bool check_multi( DESCRIPTOR_DATA* d )
{
    DESCRIPTOR_DATA* dold;

    for ( dold = first_descriptor; dold; dold = dold->next )
        if ( dold && d && dold != d && dold->character && dold->character != d->character && compare_ip_network_prefix(dold->ip, d->ip) )
            return true;

    return false;
}

// Check if already playing.
bool check_multi_name( DESCRIPTOR_DATA* d, char* name )
{
    if ( allowedmp( d ) )
        return FALSE;

    for ( DESCRIPTOR_DATA* dold = first_descriptor; dold; dold = dold->next )
    {
        if ( dold == d ) // Don't check against the current descriptor
            continue;

        CHAR_DATA* other_ch = dold->character ? dold->character : dold->original;

        if ( !other_ch ) // Ignore descriptors without a character
            continue;

        if ( !str_cmp( name, other_ch->name ) ) // Ignore descriptors with the same character connected
            continue;

        if ( !compare_ip_network_prefix( dold->ip, d->ip ) ) // Ignore different IPs
            continue;

        if ( str_cmp( other_ch->pcdata->fakeip, d->character->pcdata->fakeip ) )
            continue;

        if ( get_trust( other_ch ) >= LEVEL_RPC || get_trust( d->character ) >= LEVEL_RPC ) // Ignore RPC+
            continue;

        // Ignore accounts set to multiplay with each other
        if ( d->account && dold->account && is_name( d->account->name, dold->account->multiplay ) )
            continue;

        if ( d->account && dold->account && is_name( dold->account->name, d->account->multiplay ) )
            continue;

        if ( d->account && d->account->level >= LEVEL_IMMORTAL )
            continue;

        write_to_buffer( d, "Sorry, multi-playing is not allowed...have your other character quit first.\n", 0 );
        snprintf( log_buf, MSL, "%s (%s), IP %s, attempting to multiplay with %s (%s), IP %s",
        d->character->name, d->account ? d->account->name : "no/missing account", d->ip, other_ch->name,
        ( other_ch->pcdata && other_ch->pcdata->account ) ? other_ch->pcdata->account->name : "no/missing account",
        ( other_ch->desc && !NULLSTR( other_ch->desc->ip ) ) ? other_ch->desc->ip : "missing" );
        log_string_plus( log_buf, LOG_COMM, sysdata.log_level );
        free_char( d->character );
        d->character = NULL;
        return TRUE;
    }

    return FALSE;
}

void bump_descriptor( DESCRIPTOR_DATA* ignore, char* name )
{
    DESCRIPTOR_DATA* d;
    DESCRIPTOR_DATA* dtmp;
    CHAR_DATA* ch = NULL;

    for ( d = first_descriptor; d; d = dtmp )
    {
        dtmp = d->next;

        if ( d == ignore && ignore != NULL )
            continue;

        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( ( ch = d->character ) == NULL )
            continue;

        if ( !str_cmp( name, d->character->name ) )
            close_socket( d, FALSE );
    }

    return;
}

short check_playing( DESCRIPTOR_DATA* d, char* name, bool kick )
{
    CHAR_DATA* ch;
    DESCRIPTOR_DATA* dold;
    int cstate;

    for ( dold = first_descriptor; dold; dold = dold->next )
    {
        if ( dold != d
                && (  dold->character || dold->original )
                &&   !str_cmp( name, dold->original
                               ? dold->original->name : dold->character->name ) )
        {
            cstate = dold->connected;
            ch = dold->original ? dold->original : dold->character;

            if ( !ch->name
                    || ( cstate != CON_PLAYING && cstate != CON_EDITING ) )
            {
                send_to_desc_color( "&z(&CA&z)lready connected - try again.\n", d );
                snprintf( log_buf, MSL, "%s already connected.", ch->name );
                log_string_plus( log_buf, LOG_COMM, sysdata.log_level );
                return BERR;
            }

            // Handle fake descriptor replacement
            if ( dold->is_fake_desc )
            {
                send_to_desc_color( "&z(&CR&z)econnecting to loaded character.\n", d );

                // Replace fake descriptor with real connection
                destroy_fake_descriptor( dold );
                ch->desc = d;
                d->character = ch;
                d->original = ch;

                lognormal( "Real player connected to character %s, replacing fake descriptor", ch->name );
                return FALSE; // Successfully reconnected
            }

            if ( !kick )
                return TRUE;

            send_to_desc_color( "&z(&CA&z)lready playing... Kicking off old connection.\n", d );
            send_to_desc_color( "&z(&CK&z)icking off old connection... bye!\n", dold );
            close_socket( dold, FALSE );
            /* clear descriptor pointer to get rid of bug message in log */
            d->character->desc = NULL;
            free_char( d->character );
            d->character = ch;
            ch->desc     = d;
            ch->timer    = 0;

            if ( ch->switched )
                do_return( ch->switched, "" );

            ch->switched = NULL;
            ch_println( ch, "&z(&CR&z)econnecting." );

            if ( !IS_IMMORTAL( ch ) )
                act( AT_ACTION, "$n has reconnected, kicking off old link.",
                     ch, NULL, NULL, TO_ROOM );

            snprintf( log_buf, MSL, "%s@%s reconnected, kicking off old link.",
                     ch->name, ch->pcdata->fakeip[0] != '\0' ? ch->pcdata->fakeip : d->host );
            log_string_plus( log_buf, LOG_COMM, UMAX( sysdata.log_level, ch->top_level ) );
            /*
                    if ( ch->top_level < LEVEL_SAVIOR )
                      to_channel( log_buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
            */
            d->connected = cstate;
            d->account = account_from_name( ch->name );
            return TRUE;
        }
    }

    return FALSE;
}

void stop_idling( CHAR_DATA* ch )
{
    if ( !ch
            ||   !ch->desc
            ||    ch->desc->connected != CON_PLAYING
            ||   !ch->was_in_room
            ||    ch->in_room != get_room_index( ROOM_VNUM_LIMBO ) )
        return;

    ch->timer = 0;
    char_from_room( ch );
    char_to_room( ch, ch->was_in_room );
    ch->was_in_room     = NULL;
    act( AT_ACTION, "$n has returned from the void.", ch, NULL, NULL, TO_ROOM );
    return;
}

char* obj_short( OBJ_DATA* obj )
{
    static char buf[MSL];

    if ( obj->count > 1 )
    {
        snprintf( buf, MSL, "%s (%d)", obj->short_descr, obj->count );
        return buf;
    }

    return obj->short_descr;
}

//The primary output interface for formatted output.
/* Major overhaul. -- Alty */

char* act_string( const char* format, CHAR_DATA* to, CHAR_DATA* ch,
                  const void* arg1, const void* arg2 )
{
    static char buf[MSL];
    char fname[MIL];
    char* point = buf;
    const char* str = format;
    const char* i;
    CHAR_DATA* vch = ( CHAR_DATA* ) arg2;
    OBJ_DATA* obj1 = ( OBJ_DATA* ) arg1;
    OBJ_DATA* obj2 = ( OBJ_DATA* ) arg2;

    while ( *str != '\0' )
    {
        if ( *str != '$' )
        {
            *point++ = *str++;
            continue;
        }

        ++str;

        if ( !arg2 && *str >= 'A' && *str <= 'Z' )
        {
            bug( "Act: missing arg2 for code %c:", *str );
            bug( format );
            i = " <@@@> ";
        }
        else
        {
            switch ( *str )
            {
                default:
                    bug( "Act: bad code %c.", *str );
                    i = " <@@@> ";
                    break;

                case 't':
                    i = ( char* ) arg1;
                    break;

                case 'T':
                    i = ( char* ) arg2;
                    break;

                case 'n':
                    /* GRAL changed PERS above */
                    // GRAL HAX
                    // Issue is NAME is not relevant, it needs to do a for all in room check
                    i = ( to && ( !check_blind( to, TRUE ) || !can_see( to, ch ) ) ) ? "Someone" : ( to ? PERS( ch, to ) : NAME( ch ) );
                    break;

                case 'N':
                    i = ( to && ( !check_blind( to, TRUE ) || !can_see( to, vch ) ) ) ? "Someone" : ( to ? PERS( vch, to ) : NAME( vch ) );
                    break;

                case 'e':
                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "they";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "it";
                    else
                        i = he_she [URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'E':
                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "they";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "it";
                    else
                        i = he_she [URANGE( 0, vch->sex, 2 )];

                    break;

                case 'm':
                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "them";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "it";
                    else
                        i = him_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'M':
                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "them";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "it";
                    else
                        i = him_her[URANGE( 0, vch->sex, 2 )];

                    break;

                case 's':
                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "their";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'S':
                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "their";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0, vch->sex, 2 )];

                    break;

                case 'q':
                    i = ( to == ch ) ? "" : "s";
                    break;

                case 'Q':
                    if ( to == ch )
                        i = "your";
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'p':
                    i = ( !to || can_see_obj( to, obj1 )
                          ? stripclr( obj_short( obj1 ) ) : "something" );
                    break;

                case 'P':
                    i = ( !to || can_see_obj( to, obj2 )
                          ? stripclr( obj_short( obj2 ) ) : "something" );
                    break;

                case 'd':
                    if ( !arg2 || ( ( char* ) arg2 )[0] == '\0' )
                        i = "door";
                    else
                    {
                        one_argument( ( char* ) arg2, fname );
                        i = fname;
                    }

                    break;
            }
        }

        ++str;

        while ( ( *point = *i ) != '\0' )
            ++point, ++i;
    }

    strlcpy( point, "\n", MSL );
    buf[0] = UPPER( buf[0] );
    return buf;
}

void act( sh_int AType, const char* format, CHAR_DATA* ch, const void* arg1, const void* arg2, int type )
{
    char* txt;
    CHAR_DATA* to;
    CHAR_DATA* vch = ( CHAR_DATA* )arg2;
    char ntxt[MSL];

    // Discard null and zero-length messages.
    if ( !format || format[0] == '\0' )
        return;

    if ( !format )
    {
        bug( "Act: null format" );
        return;
    }

    if ( !ch )
    {
        bug( "Act: null ch. (%s)", format );
        return;
    }

    if ( !ch->in_room )
        to = NULL;
    else if ( type == TO_CHAR )
        to = ch;
    else
        to = ch->in_room->first_person;

    //ACT_SECRETIVE handling
    if ( IS_NPC( ch ) && xIS_SET( ch->act, ACT_SECRETIVE ) && type != TO_CHAR )
        return;

    // PUFF is the ghost in the machine.
    if ( IS_PUFF( ch ) )
        return;

    if ( type == TO_VICT )
    {
        if ( !vch )
        {
            bug( "Act: null vch with TO_VICT." );
            bug( "%s (%s)", ch->name, format );
            return;
        }

        if ( !vch->in_room )
        {
            bug( "Act: vch in NULL room!" );
            bug( "%s -> %s (%s)", ch->name, vch->name, format );
            return;
        }

        to = vch;
        /*      to = vch->in_room->first_person;*/
    }

    if ( MOBtrigger && type != TO_CHAR && type != TO_VICT && to && to->in_room != NULL )
    {
        OBJ_DATA* to_obj;
        txt = act_string( format, NULL, ch, arg1, arg2 );
        lua_trigger_on_room_act( to->in_room, ch, txt );
        rprog_act_trigger( txt, to->in_room, ch, ( OBJ_DATA* )arg1, ( void* )arg2 );

        for ( to_obj = to->in_room->first_content; to_obj; to_obj = to_obj->next_content )
        {
            lua_trigger_on_obj_act( to_obj, ch, txt );

            if ( IS_SET( to_obj->pIndexData->progtypes, ACT_PROG ) )
                oprog_act_trigger( txt, to_obj, ch, ( OBJ_DATA* )arg1, ( void* )arg2 );
        }
    }

    /*  Anyone feel like telling me the point of looping through the whole
        room when we're only sending to one char anyways..? -- Alty */
    for ( ; to; to = ( type == TO_CHAR || type == TO_VICT )
                     ? NULL : to->next_in_room )
    {
        if ( type == TO_CHAR && to != ch )
            continue;

        if ( type == TO_VICT && ( to != vch || to == ch ) )
            continue;

        if ( type == TO_ROOM && to == ch )
            continue;

        if ( type == TO_NOTVICT && ( to == ch || to == vch ) )
            continue;

        if ( !IS_AWAKE( to ) )
            continue;

        if ( to->in_room && room_is_dark( to->in_room ) && !can_see( to, ch ) )
            if ( !IS_AFFECTED( to, AFF_INFRARED ) )
                continue;

        if ( ch->last_stealthy && ch != to ) {
            // if they are being stealthy, maybe the "to" won't get the message
            int perception_bonus = get_perception_bonus(to);
            int perception_roll = number_range(1, 20);
            if ( to->watching == ch ) {
                // they are watching the stealthy person, so they get a bonus
                perception_bonus += 5;
            }
            if (perception_roll + perception_bonus + ch->last_stealthy->opponent_modifier <= ch->last_stealthy->roll + ch->last_stealthy->player_modifier) {
                // include the ch name and the to name in the tune statement. be verbose and describe each of the parameters.
                tune("do_stealthily: (undetected) %s's perception roll %d + %d bonus + opponent bonus %d vs %s's stealth roll %d + %d bonus", to->name, perception_roll, perception_bonus, ch->last_stealthy->opponent_modifier, ch->name, ch->last_stealthy->roll, ch->last_stealthy->player_modifier);
                // they didn't notice
                continue;
            } else {
                // include the ch name and the to name in the tune statement. be verbose and describe each of the parameters.
                tune("do_stealthily: (detected) %s's perception roll %d + %d bonus + opponent bonus %d vs %s's stealth roll %d + %d bonus", to->name, perception_roll, perception_bonus, ch->last_stealthy->opponent_modifier, ch->name, ch->last_stealthy->roll, ch->last_stealthy->player_modifier);
                // they noticed
                ch_println( to, "You notice someone trying to be sneaky" );
            }
        }

        // For efficiency, skip NPCs who don't have act progs or lprogs
        if ( !to->desc && IS_NPC( to ) &&
                !( IS_SET( to->pIndexData->progtypes, ACT_PROG ) ||
                   ( to->pIndexData && !NULLSTR( to->pIndexData->lprog_code ) )
                 )
           )
            continue;

        txt = act_string( format, to, ch, arg1, arg2 );

        if ( to->desc )
        {
            set_char_color( AType, to );
            send_to_char( txt, to );
        }

        if ( MOBtrigger )
        {
            /* Note: use original string, not string with ANSI. -- Alty */
            lua_trigger_on_ch_act( to, ch, txt );
            mprog_act_trigger( txt, to, ch, ( OBJ_DATA* )arg1, ( void* )arg2 );
        }
    }

    MOBtrigger = TRUE;

    // ~Miros
    if ( ch && ch->in_room && xIS_SET( ch->in_room->flags, ROOM_CAMERA ) && type != TO_CHAR && type != TO_VICT
            && !is_disrupted( ch, TAP_COMM, true ) && !has_feat( ch, cache_skill( "camera avoidance", &skill_camera_avoidance ) ) )
    {
        TIMER* timer = NULL;
        TAP_DATA* tap;

        for ( to = first_char; to; to = to->next )
        {
            if ( IS_NPC( to ) )
                continue;

            if ( to == ch )
                continue;

            if ( ( timer = get_timerptr( to, TIMER_DO_FUN ) ) == NULL )
                continue;

            if ( !str_cmp( timer->buffer->func, "do_monitor_camera" ) )
            {
                tap = (TAP_DATA*)timer->buffer->buf1;
                if ( !tap )
                    continue;

                if ( tap->type != TAP_CAMERA )
                    continue;

                if ( tap->tap_target != ch->in_room )
                    continue;

                if ( !IS_AWAKE( to ) )
                    continue;

                if ( is_disrupted( to, TAP_COMM, true ) )
                    continue;

                snprintf( ntxt, MSL, "&z<&WCamera&z> &B%s", act_string( format, to, ch, arg1, arg2 ) );
                txt = ntxt;
                debug( "act: %s is monitoring camera in %d, string %s", to->name, ch->in_room->vnum, txt );

                if ( to->desc )
                {
                    set_char_color( AType, to );
                    dch_printf( to, "%s", txt );
                    dch_flush( to );
                }
            }
        }
    }

    if ( type != TO_CHAR && type != TO_VICT )
    {
        ROOM_INDEX_DATA* troom = NULL;
        OBJ_DATA* tobj;

        for ( TRANSMIT_DATA* transmit = first_transmit; transmit; transmit = transmit->next )
        {
            if ( !transmitter_sending_from_room( transmit, ch->in_room ) )
                continue;

            snprintf( ntxt, MSL, "&cBinary data detected on holotransmitter channel %d.\n", transmit->channel );
            push_to_taps( ch->in_room, TAP_COMM, ntxt );

            for ( TRANSMIT_RECEIVER* rcv = transmit->first_connected; rcv; rcv = rcv->next )
            {
                tobj = rcv->transmitter;

                if ( tobj->value[IVAL_TRANSMITTER_MODE] == IVAL_TRANSMITTER_MODE_SEND )
                    continue;

                troom = tobj->in_room ? tobj->in_room : tobj->carried_by ? tobj->carried_by->in_room : NULL;

                if ( !troom || troom == ch->in_room )
                    continue;

                for ( to = troom->first_person; to; to = to->next_in_room )
                {
                    if ( !IS_AWAKE( to ) )
                        continue;

                    if ( type == TO_VICT )
                        snprintf( ntxt, MSL, "&z<&WHolo&z> &033%s", act_string( format, to, ch, to, arg2 ) );
                    else
                        snprintf( ntxt, MSL, "&z<&WHolo&z> &033%s", act_string( format, to, ch, arg1, arg2 ) );

                    txt = ntxt;

                    if ( to->desc )
                    {
                        set_char_color( AType, to );
                        send_to_char( txt, to );
                    }

                    if ( MOBtrigger )
                    {
                        /* Note: use original string, not string with ANSI. -- Alty */
                        lua_trigger_on_ch_act( to, ch, txt );
                        mprog_act_trigger( txt, to, ch, ( OBJ_DATA* )arg1, ( void* )arg2 );
                    }
                }

                MOBtrigger = TRUE;
            }
        }
    }

    return;
}

CMDF do_name( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* tmp;

    if ( !NOT_AUTHED( ch ) || ch->pcdata->auth_state != 2 )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    argument[0] = UPPER( argument[0] );

    if ( !check_parse_name( argument, is_droid( ch->race ) ) )
    {
        ch_println( ch, "Illegal name, try another." );
        return;
    }

    if ( !str_cmp( ch->name, argument ) )
    {
        ch_println( ch, "That's already your name!" );
        return;
    }

    for ( tmp = first_char; tmp; tmp = tmp->next )
    {
        if ( !str_cmp( argument, tmp->name ) )
            break;
    }

    if ( tmp )
    {
        ch_println( ch, "That name is already taken. Please choose another." );
        return;
    }

    if ( player_exist( argument ) )
    {
        ch_println( ch, "That name is already taken. Please choose another." );
        return;
    }

    SET_STRING( ch->name, argument );
    ch_println( ch, "Your name has been changed. Please apply again." );
    ch->pcdata->auth_state = 2;
    return;
}

