    //    return number_range(1, 15);
    for ( r = 0; r < 16; r++ )
        if ( clr == colors[r] )
            return r;

    return -1;
}

void display_prompt( DESCRIPTOR_DATA* d )
{
    if ( !d || !d->character || !valid_char( d->character ) )
        return;

    CHAR_DATA* ch = d->character;
    CHAR_DATA* tch = NULL;
    CHAR_DATA* victim;
    CHAR_DATA* och = ( d->original ? d->original : d->character );
    DESCRIPTOR_DATA* dtmp;
    bool ansi = ( !IS_NPC( och ) && has_pcflag( och, PCFLAG_ANSI ) );
    const char* prompt;
    char buf[MSL];
    char tbuf[MSL];
    char* pbuf = buf;
    int stat, percent, cnt = 0;
    int val = 0;
    int i = 0;
    OBJ_DATA* obj = NULL, *wield = NULL;
    DB_DATA* db = NULL;
    DROID_DATA* tDroid = NULL;
    CHAR_DATA* droid = NULL;
    char newstr[MSL];

    if ( !IS_NPC( ch ) && ch->substate != SUB_NONE && ch->pcdata->subprompt
            &&   ch->pcdata->subprompt[0] != '\0' )
        prompt = ch->pcdata->subprompt;
    else if ( has_pcflag( ch, PCFLAG_AFK ) )
        prompt = "&W-[AFK MODE]--Type-AFK-to-return!--[AFK MODE]-%_";
    else if ( ch->fighting )
    {
        if ( !NULLSTR( ch->pcdata->fprompt ) && str_cmp( ch->pcdata->fprompt, "(null)" ) )
            prompt = ch->pcdata->fprompt;
        else if ( ch->pcdata->account && !NULLSTR( ch->pcdata->account->fprompt ) && str_cmp( ch->pcdata->account->fprompt, "(null)" ) )
            prompt = ch->pcdata->account->fprompt;
        else
            prompt = default_fprompt( ch );
    }
    else
    {
        if ( !NULLSTR( ch->pcdata->prompt ) && str_cmp( ch->pcdata->prompt, "(null)" ) )
            prompt = ch->pcdata->prompt;
        else if ( ch->pcdata->account && !NULLSTR( ch->pcdata->account->prompt ) && str_cmp( ch->pcdata->account->prompt, "(null)" ) )
            prompt = ch->pcdata->account->prompt;
        else
            prompt = default_prompt( ch );
    }

    if ( ansi )
    {
        strlcpy( pbuf, ANSI_RESET, MSL );
        d->prevcolor = 0x08;
        pbuf += 4;
    }

    /* Clear out old color stuff */
    for ( ; *prompt; prompt++ )
    {
        if ( *prompt != '%' )
        {
            *( pbuf++ ) = *prompt;
            continue;
        }

        ++prompt;

        if ( !*prompt )
            break;

        if ( *prompt == *( prompt - 1 ) )
        {
            *( pbuf++ ) = *prompt;
            continue;
        }

        switch ( *( prompt - 1 ) )
        {
            default:
                bug( "Display_prompt: bad command char '%c'.", *( prompt - 1 ) );
                break;

            case '%':
                *pbuf = '\0';
                stat = 0x80000000;

                switch ( *prompt )
                {
                    case '%':
                        *pbuf++ = '%';
                        *pbuf = '\0';
                        break;

                    case '_': /* Just add a enter */
                        strlcpy( pbuf, "\n", MSL );
                        break;

                    case 'a':
                        if ( ch->top_level >= 10 )
                            stat = ch->alignment;
                        else if ( IS_GOOD( ch ) )
                            strlcpy( pbuf, "good", MSL );
                        else if ( IS_EVIL( ch ) )
                            strlcpy( pbuf, "evil", MSL );
                        else
                            strlcpy( pbuf, "neutral", MSL );

                        break;

                    case 'A':
                        strlcpy( tbuf, "", MSL );

                        for ( tch = ch->in_room->first_person; tch ; tch = tch->next_in_room )
                        {
                            if ( !valid_char( tch ) )
                                continue;

                            if ( !is_near( ch, tch ) || ch == tch || !can_see( ch, tch ) || ch->position <= POS_SLEEPING )
                                continue;

                            cnt++;

                            if ( cnt > 1 )
                                strlcat( tbuf, ", ", MSL );

                            strlcat( tbuf, stripclr( g_name( tch, ch ) ), MSL );
                        }

                        snprintf( pbuf, MSL, "%s", tbuf );
                        break;

                    case 'b':          /* OOC Limit-break */
                        if ( IS_NPC( ch ) )
                            break;

                        if ( ch->pcdata->ooclimit > 6 )
                            ch->pcdata->ooclimit = 6;

                        if ( ch->pcdata->ooclimit <= 6 )
                            snprintf( pbuf, MSL, "%s%d", ANSISAFE( ansi, "\x1b[1;32m" ), ch->pcdata->ooclimit );

                        if ( ch->pcdata->ooclimit <= 4 )
                            snprintf( pbuf, MSL, "%s%d", ANSISAFE( ansi, "\x1b[1;33m" ), ch->pcdata->ooclimit );

                        if ( ch->pcdata->ooclimit <= 2 )
                            snprintf( pbuf, MSL, "%s%d", ANSISAFE( ansi, "\x1b[1;31m" ), ch->pcdata->ooclimit );

                        if ( ch->pcdata->oocbreak )
                            snprintf( pbuf, MSL, "%sLB", ANSISAFE( ansi, "\x1b[1;31m" ) );

                        break;

                    case 'B':          /* OOC Limit-break */
                        if ( IS_NPC( ch ) )
                            break;

                        if ( ch->pcdata->ooclimit > 6 )
                            ch->pcdata->ooclimit = 6;

                        if ( ch->pcdata->ooclimit == 6 )
                            snprintf( pbuf, MSL, "%s||||||", ANSISAFE( ansi, "\x1b[1;32m" ) );

                        if ( ch->pcdata->ooclimit == 5 )
                            snprintf( pbuf, MSL, "%s|||||-", ANSISAFE( ansi, "\x1b[1;32m" ) );

                        if ( ch->pcdata->ooclimit == 4 )
                            snprintf( pbuf, MSL, "%s||||--", ANSISAFE( ansi, "\x1b[1;33m" ) );

                        if ( ch->pcdata->ooclimit == 3 )
                            snprintf( pbuf, MSL, "%s|||---", ANSISAFE( ansi, "\x1b[1;33m" ) );

                        if ( ch->pcdata->ooclimit == 2 )
                            snprintf( pbuf, MSL, "%s||----", ANSISAFE( ansi, "\x1b[1;31m" ) );

                        if ( ch->pcdata->ooclimit == 1 )
                            snprintf( pbuf, MSL, "%s|-----", ANSISAFE( ansi, "\x1b[1;31m" ) );

                        if ( ch->pcdata->ooclimit == 0 )
                            snprintf( pbuf, MSL, "%s------", ANSISAFE( ansi, "\x1b[1;31m" ) );

                        if ( ch->pcdata->oocbreak )
                            snprintf( pbuf, MSL, "%s--LB--", ANSISAFE( ansi, "\x1b[1;31m" ) );

                        break;

                    case 'c':          /* Graphic health prompt */
                        percent = -1;

                        if ( ch->max_hit > 0 )
                            percent = ( 100 * ch->hit ) / ch->max_hit;

                        if ( percent >= 100 )
                            snprintf( pbuf, MSL, "%s|||%s|||%s||||%s", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 90 )
                            snprintf( pbuf, MSL, "%s|||%s|||%s|||%s ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 80 )
                            snprintf( pbuf, MSL, "%s|||%s|||%s||%s  ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 70 )
                            snprintf( pbuf, MSL, "%s|||%s|||%s|%s   ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 60 )
                            snprintf( pbuf, MSL, "%s|||%s|||%s    ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 50 )
                            snprintf( pbuf, MSL, "%s|||%s||%s     ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 40 )
                            snprintf( pbuf, MSL, "%s|||%s|%s      ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 30 )
                            snprintf( pbuf, MSL, "%s|||%s       ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 20 )
                            snprintf( pbuf, MSL, "%s||%s        ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 10 )
                            snprintf( pbuf, MSL, "%s|%s         ", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                        else
                            snprintf( pbuf, MSL, "          " );

                        break;

                    case 'C':                     /* Percentage health prompt */
                        percent = -1;

                        if ( ch->max_hit > 0 )
                            percent =  ( 100 * ch->hit ) / ch->max_hit;

                        if ( percent >= 60 )
                            snprintf( pbuf, MSL, "%s%d%%%s", ANSISAFE( ansi, "\x1b[1;32m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );
                        else if ( percent >= 30 && percent < 60 )
                            snprintf( pbuf, MSL, "%s%d%%%s", ANSISAFE( ansi, "\x1b[1;33m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );
                        else
                            snprintf( pbuf, MSL, "%s%d%%%s", ANSISAFE( ansi, "\x1b[1;31m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );

                        break;

                    case 'd': // Droid
                        tDroid = droid_from_controller( ch->id );
                        droid = mob_from_droid( tDroid );

                        if ( !tDroid )
                            snprintf( pbuf, MSL, "-" );
                        else if ( !droid )
                            snprintf( pbuf, MSL, "Your droid has died! Type DROIDSTAT." );
                        else
                            snprintf( pbuf, MSL, "%s", droid->short_descr );

                        break;

                    case 'D':
                        db = find_tone( get_tone( ch ) );
                        snprintf( pbuf, MSL, "%s", db ? db->name : "none" );
                        break;

                    case 'e':          /* Graphic battle prompt */
                        if ( ( victim = who_fighting( ch ) ) != NULL )
                        {
                            if ( victim->max_hit > 0 )
                                percent = ( 100 * victim->hit ) / victim->max_hit;
                            else
                                percent = -1;

                            if ( percent >= 100 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|||%s||||%s]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 90 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|||%s|||%s ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 80 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|||%s||%s  ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 70 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|||%s|%s   ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[1;32m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 60 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|||%s    ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 50 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s||%s     ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 40 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s|%s      ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[1;33m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 30 )
                                snprintf( pbuf, MSL, "Enemy: [%s|||%s       ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 20 )
                                snprintf( pbuf, MSL, "Enemy: [%s||%s        ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 10 )
                                snprintf( pbuf, MSL, "Enemy: [%s|%s         ]", ANSISAFE( ansi, "\x1b[1;31m" ), ANSISAFE( ansi, "\x1b[0m" ) );
                            else
                                snprintf( pbuf, MSL, "Enemy: [          ]" );
                        }

                        break;

                    case 'E':                     /* Percentage battle prompt */
                        if ( ( victim = who_fighting( ch ) ) != NULL )
                        {
                            if ( victim->max_hit > 0 )
                                percent =  ( 100 * victim->hit ) / victim->max_hit;
                            else
                                percent = -1;

                            if ( percent >= 60 )
                                snprintf( pbuf, MSL, "Enemy: [ %s%d%%%s ]", ANSISAFE( ansi, "\x1b[1;32m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );
                            else if ( percent >= 30 && percent < 60 )
                                snprintf( pbuf, MSL, "Enemy: [ %s%d%%%s ]", ANSISAFE( ansi, "\x1b[1;33m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );
                            else
                                snprintf( pbuf, MSL, "Enemy: [ %s%d%%%s ]", ANSISAFE( ansi, "\x1b[1;31m" ), percent, ANSISAFE( ansi, "\x1b[0m" ) );
                        }
                        else
                            snprintf( pbuf, MSL, "Enemy: [ none ]" );

                        break;

                    case 'f':
                            if ( ( obj = get_eq_char( ch, WEAR_LIGHT ) ) != NULL && obj->item_type == ITEM_LIGHT && obj->value[2] != 0 && IS_SET( obj->value[3], 1 << 0 ) )
                                snprintf( pbuf, MSL, "%s", "*" );
                            else
                                snprintf( pbuf, MSL, "%s", " " );
                        break;

                    case 'F':
                        if ( ch->fighting )
                        {
                            stat = ch->fighting->xp;
                        }
                        else
                        {
                            snprintf( pbuf, MSL, "---" );
                        }

                        break;

                    case 'g': /* In timer? */
                        snprintf( pbuf, MSL, "%s", is_busy( ch ) ? "*" : " " );
                        break;

                    case 'G':         /* Mental State added as part of ForcerUpdate20201 4Jan21 CoffinC*/
                        stat = ch->mental_state;
                        break;

                    case 'h':
                        stat = ch->hit;
                        break;

                    case 'H':
                        stat = ch->max_hit;
                        break;

                    case 'i':
                        if ( ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_WIZINVIS ) ) ||
                                ( IS_NPC( ch ) && xIS_SET( ch->act, ACT_MOBINVIS ) ) )
                            snprintf( pbuf, MSL, "(Invis %d) ", ( IS_NPC( ch ) ? ch->mobinvis : ch->pcdata->wizinvis ) );
                        else if ( IS_AFFECTED( ch, AFF_INVISIBLE ) )
                            snprintf( pbuf, MSL, "(Invis) " );

                        break;

                    case 'I':
                        stat = ( IS_NPC( ch ) ? ( xIS_SET( ch->act, ACT_MOBINVIS ) ? ch->mobinvis : 0 )
                                 : ( has_pcflag( ch, PCFLAG_WIZINVIS ) ? ch->pcdata->wizinvis : 0 ) );
                        break;

                    case 'J':
                        strlcpy( pbuf, "average", MSL );

                        if ( !ch->in_room )
                            break;

                        if ( ch->in_room->area )
                        {
                            if ( ch->in_room->area->ambience == 1 )
                                strlcpy( pbuf, "quiet", MSL );

                            if ( ch->in_room->area->ambience == 2 )
                                strlcpy( pbuf, "average", MSL );

                            if ( ch->in_room->area->ambience == 3 )
                                strlcpy( pbuf, "loud", MSL );
                        }

                        break;

                    case 'k': // Current comlink's channel
                        obj = ch->curr_comlink;

                        if ( !obj )
                            snprintf( pbuf, MSL, "-" );
                        else
                            snprintf( pbuf, MSL, "%d", obj->value[5] );

                        break;

                    case 'K': //  Current comlink's encryption
                        obj = ch->curr_comlink;

                        if ( !obj )
                            snprintf( pbuf, MSL, "-" );
                        else
                            snprintf( pbuf, MSL, "%d", obj->value[4] );

                        break;

                    case 'l':
                        wield = get_eq_char( ch, WEAR_WIELD );
                        if ( !wield || wield->item_type != ITEM_WEAPON )
                            stat = 0;
                        else
                            stat = wield->value[4];
                        break;

                    case 'L':
                        wield = get_eq_char( ch, WEAR_DUAL_WIELD );
                        if ( !wield || wield->item_type != ITEM_WEAPON )
                            stat = 0;
                        else
                            stat = wield->value[4];
                        break;

                    case 'm':
                        if ( IS_IMMORTAL( ch ) || ch->skill_level[FORCE_ABILITY] > 1 )
                            stat = ch->mana;
                        else
                            stat = 0;

                        break;

                    case 'M':
                        if ( IS_IMMORTAL( ch ) || ch->skill_level[FORCE_ABILITY] > 1 )
                            stat = ch->max_mana;
                        else
                            stat = 0;

                        break;

                    case 'o':          /* Bot status token */
                        if ( ch->pcdata->botting && ch->pcdata->cooldown != -1 )
                            snprintf( pbuf, MSL, "BOT" );
                        else if ( ch->pcdata->cooldown > 0 )
                            snprintf( pbuf, MSL, "CD" );
                        else
                            *pbuf = '\0';

                        break;

                    case 'p':          /* Graphic AP prompt */
                        percent = get_max_ap( ch );

                        if ( percent > 0 )
                            percent = ( 100 * ch->ap ) / percent;

                        if ( percent >= 100 )
                            snprintf( pbuf, MSL, "||||||||||" );
                        else if ( percent >= 90 )
                            snprintf( pbuf, MSL, "||||||||| " );
                        else if ( percent >= 80 )
                            snprintf( pbuf, MSL, "||||||||  " );
                        else if ( percent >= 70 )
                            snprintf( pbuf, MSL, "|||||||   " );
                        else if ( percent >= 60 )
                            snprintf( pbuf, MSL, "||||||    " );
                        else if ( percent >= 50 )
                            snprintf( pbuf, MSL, "|||||     " );
                        else if ( percent >= 40 )
                            snprintf( pbuf, MSL, "||||      " );
                        else if ( percent >= 30 )
                            snprintf( pbuf, MSL, "|||       " );
                        else if ( percent >= 20 )
                            snprintf( pbuf, MSL, "||        " );
                        else if ( percent >= 10 )
                            snprintf( pbuf, MSL, "|         " );
                        else
                            snprintf( pbuf, MSL, "          " );

                        break;

                    case 'P':          /* Numerical AP Indicator */
                        snprintf( pbuf, MSL, "%d/%d", ch->ap, get_max_ap( ch ) );
                        break;

                    case 'q':
                        snprintf( pbuf, MSL, "%d", ch->carry_weight );
                        break;

                    case 'Q':
                        snprintf( pbuf, MSL, "%d", can_carry_w( ch ) );
                        break;

                    case 'r':
                        if ( IS_IMMORTAL( och ) )
                            stat = ch->in_room->vnum;

                        break;

                    case 'R':
                        if ( has_pcflag( och, PCFLAG_ROOMVNUM ) )
                            snprintf( pbuf, MSL, "<#%d> ", ch->in_room->vnum );

                        break;

                    case 's':
                        tDroid = droid_from_controller( ch->id );
                        droid = mob_from_droid( tDroid );

                        if ( !tDroid || !droid )
                            snprintf( pbuf, MSL, "-" );
                        else
                            snprintf( pbuf, MSL, "%d/%d", droid->hit, droid->max_hit );

                        break;

                    case 'S':
                        if ( ch->desc )
                        {
                            int i, j;
                            int itag = 0;

                            for ( i = j = 0; ch->desc->inbuf[i] != '\0'; i++ )
                            {
                                if ( ch->desc->inbuf[i] == '\n' )
                                {
                                    newstr[j++] = ',';
                                }
                                else if ( ch->desc->inbuf[i] == ',' )
                                {
                                    itag++;
                                    newstr[j++] = ch->desc->inbuf[i];
                                }
                                else if ( ch->desc->inbuf[i] != '\r' )
                                {
                                    newstr[j++] = ch->desc->inbuf[i];
                                }
                            }

                            newstr[j] = '\0';
                        }

                        snprintf( pbuf, MSL, "%s", ( ch->desc ) ? newstr : "---" );
                        break;

                    case 't':
                        /* Time till your backup arrives in rounds */
                        stat = ch->called ? ch->called->wait_time : 0;

                        if ( stat < 0 )
                            stat = 0;

                        break;

                    case 'T':

                        /* Time till your backup arrives, Full prompt */
                        if ( ch->called )
                        {
                            snprintf( pbuf, MSL, "(Backup: %d) ", ch->called->wait_time );
                        }

                        break;

                    case 'u':
                        for ( dtmp = first_descriptor ; dtmp ; dtmp = dtmp->next )
                        {
                            if ( dtmp->character )
                                if ( get_trust( dtmp->character ) > 102 )
                                    continue;

                            val++;
                        }

                        stat = val;
                        break;

                    case 'U':
                        stat = sysdata.maxplayers;
                        break;

                    case 'v':
                        stat = ch->move;
                        break;

                    case 'V':
                        stat = ch->max_move;
                        break;

                    case 'w': // spoken language
                        for ( i = 0; languages[i].flag != LAST_FLAG_VALUE; i++ )
                        {
                            if ( !xIS_SET( ch->speaking, languages[i].flag ) )
                                continue;

                            snprintf( pbuf, MSL, "%s", languages[i].name );
                            break; // Print first one so imms dont get spammed
                        }

                        break;

                    case 'W':
                        if      ( time_info.hour <  5 )
                            strlcpy( pbuf, "night", MSL );
                        else if ( time_info.hour <  6 )
                            strlcpy( pbuf, "dawn", MSL );
                        else if ( time_info.hour < 19 )
                            strlcpy( pbuf, "day", MSL );
                        else if ( time_info.hour < 20 )
                            strlcpy( pbuf, "dusk", MSL );
                        else
                            strlcpy( pbuf, "night", MSL );

                        break;

                    case 'x':          /* Graphic mana prompt */
                        percent = -1;

                        if ( ch->max_mana > 0 )
                            percent = ( 100 * ch->mana ) / ch->max_mana;

                        if ( percent >= 100 )
