void set_pager_input( DESCRIPTOR_DATA* d, char* argument )
{
    while ( isspace( *argument ) )
        argument++;

    d->pagecmd = *argument;
    return;
}

bool pager_output( DESCRIPTOR_DATA* d )
{
    register char* last;
    CHAR_DATA* ch;
    int pclines;
    register int lines;
    bool ret;

    if ( !d || !d->pagepoint || d->pagecmd == -1 )
        return TRUE;

    ch = d->original ? d->original : d->character;
    pclines = UMAX( ch->pcdata->pagerlen, 5 ) - 1;

    switch ( LOWER( d->pagecmd ) )
    {
        default:
            lines = 0;
            break;

        case 'b':
            lines = -1 - ( pclines * 2 );
            break;

        case 'r':
            lines = -1 - pclines;
            break;

        case 'q':
            d->pagetop = 0;
            d->pagepoint = NULL;
            flush_buffer( d, TRUE );
            STRFREE( d->pagebuf );
            d->pagesize = MSL;
            return TRUE;
    }

    while ( lines < 0 && d->pagepoint >= d->pagebuf )
        if ( *( --d->pagepoint ) == '\n' )
            ++lines;

    if ( *d->pagepoint == '\n' && *( ++d->pagepoint ) == '\r' )
        ++d->pagepoint;

    if ( d->pagepoint < d->pagebuf )
        d->pagepoint = d->pagebuf;

    for ( lines = 0, last = d->pagepoint; lines < pclines; ++last )
        if ( !*last )
            break;
        else if ( *last == '\n' )
            ++lines;

    if ( *last == '\r' )
        ++last;

    if ( last != d->pagepoint )
    {
        if ( !write_to_descriptor( d->descriptor, d->pagepoint,
                                   ( last - d->pagepoint ) ) )
            return FALSE;

        d->pagepoint = last;
    }

    while ( isspace( *last ) )
        ++last;

    if ( !*last )
    {
        d->pagetop = 0;
        d->pagepoint = NULL;
        flush_buffer( d, TRUE );
        STRFREE( d->pagebuf );
        d->pagesize = MSL;
        return TRUE;
    }

    d->pagecmd = -1;

    /*   if ( has_pcflag( ch, PCFLAG_ANSI ) )
           if ( write_to_descriptor(d->descriptor, "\033[1;36m", 7) == FALSE )
               return FALSE;*/
    if ( has_pcflag( ch, PCFLAG_ANSI ) )
        if ( write_to_descriptor( d->descriptor, ANSI_LBLUE, 0 ) == FALSE )
            return FALSE;

    if ( ( ret = write_to_descriptor( d->descriptor,
                                      "(C)ontinue, (R)efresh, (B)ack, (Q)uit: [C] \n", 0 ) ) == FALSE )
        return FALSE;

    if ( has_pcflag( ch, PCFLAG_ANSI ) )
    {
        char buf[32];
        snprintf( buf, 32, "%s", color_str( d->pagecolor, ch ) );
        ret = write_to_descriptor( d->descriptor, buf, 0 );
    }

    return ret;
}

// New COPYOVER System by Ghost
CMDF do_copyover ( CHAR_DATA* ch, char* argument )
{
    char arg[MSL];
    struct stat fst;
    bool nosave = FALSE;
    bool bypass = FALSE;
    char buf[MIL];
    argument = one_argument( argument, arg );

    if ( stat( sysdata.exe_file, &fst ) == -1 )
    {
        bug( "Error - Copyover file missing. Aborting copyover." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        send_to_char( "\n&zUSAGE: copyover &CNOW     &z-&w Full copyover", ch );
        send_to_char( "\n&z       copyover &CNOSAVE  &z-&w Only stores descriptors", ch );
        send_to_char( "\n&z       copyover &CBYPASS  &z-&w Bypasses PC safety checks", ch );
        send_to_char( "\n&z       copyover &CDEBUG   &z-&w Performs most of the copyover, but does not actually copyover", ch );
        send_to_char( "\n    ", ch );
        return;
    }

    if ( !str_cmp( arg, "nosave" ) )
    {
        nosave = TRUE;
    }
    else if ( !str_cmp( arg, "bypass" ) || !str_cmp( "debug", arg ) )
    {
        bypass = TRUE;
    }
    else if ( str_cmp( arg, "now" ) )
    {
        do_copyover( ch, "" );
        return;
    }

    snprintf( buf, MIL, "\n *** COPYOVER%s%s - please remain seated! ***\n", !has_pcflag( ch, PCFLAG_WIZINVIS ) ? " by " : "", !has_pcflag( ch, PCFLAG_WIZINVIS ) ? ch->name : "" );
    copyover( buf, false, nosave, bypass );
}

/* Recover from a copyover - load players */
void copyover_recover ()
{
    DESCRIPTOR_DATA* d;
    FILE* fp;
    char name [100];
    char ip[MSL];
    char host[MSL];
    char buf[MSL];
    char apData[MSL];
#ifdef CLIENT
    char client[MSL];
#endif
    int desc;
    bool fOld;
    snprintf( buf, MSL, "%secopyover.dat", SYSTEM_DIR );
    log_string ( "----*> Warmboot recovery initiated <*----" );
    fp = fopen ( COPYOVER_FILE, "r" );

    if ( !fp ) /* there are some descriptors open which will hang forever then ? */
    {
        perror ( "copyover_recover:fopen" );
        log_string( "Copyover file not found. Exiting.\n" );
        exit ( 1 );
    }

    unlink ( COPYOVER_FILE ); /* In case something crashes - doesn't prevent reading  */

    for ( ;; )
    {
#ifdef CLIENT
        fscanf ( fp, "%d %s %s %s %s %s\n", &desc, name, host, client, ip, apData );
#else
        fscanf ( fp, "%d %s %s %s %s\n", &desc, name, host, ip, apData );
#endif

        if ( desc == -1 )
            break;

        if ( desc > 30000 )
            continue;

        /* Write something, and check if it goes error-free */

        if ( ( !file_exist( buf ) && !write_to_descriptor( desc, "Restoring from copyover...\n", 0 ) )
                || ( file_exist( buf ) && !write_to_descriptor( desc, "\n", 0 ) ) )
        {
            bug ("failed to write to desc, disconnected %s",host);
            close ( desc ); /* nope */
            continue;
        }

        d = init_descriptor( desc );
        SET_STRING( d->host, host );
        SET_STRING( d->ip, ip );
#ifdef CLIENT
        SET_STRING( d->client, client );
#endif
        d->connected = CON_COPYOVER_RECOVER;
        CopyoverSet( d, apData );
        /* Now, find the pfile */
        fOld = load_char_obj ( d, name );

        if ( !fOld ) /* Player file not found?! */
        {
            // GRAL No &W colors when sending to descriptor
            write_to_descriptor ( desc, "Your character was disconnected in the copyover. Please log back in.\n", 0 );
            close_socket ( d, TRUE );
        }
        else /* ok! */
        {
            d->account = account_from_name( d->character->name );

            if ( !file_exist( buf ) )
                write_to_descriptor ( desc, "\nCopyover recovery complete.\n", 0 );

            /* Insert in the char_list */
            LINK( d->character, first_char, last_char, next, prev );
            hashset_add( valid_chars, d->character );
            load_droids_sql( d->character->id, FALSE );
            /* Now put them in the room */
            bool in_room = FALSE;
            if ( d->character->in_room )
                LINK_HASNODE( d->character->in_room->first_person, CHAR_DATA, next_in_room, d->character, in_room );

            if ( in_room )
                char_from_room( d->character );
            else
                d->character->in_room = NULL;
            char_to_room( d->character, get_room_index( d->character->room_num ) );
            // char_to_room would otherwise save them, but we really don't need to right after a copyover
            d->character->save_queued = FALSE;
            num_descriptors++;
            sysdata.maxplayers++;


            if ( d->character->pcdata->condition[COND_FULL] < 40 )
                d->character->pcdata->condition[COND_FULL] = 40;

            if ( d->character->pcdata->condition[COND_THIRST] < 40 )
                d->character->pcdata->condition[COND_THIRST] = 40;

            /* act( AT_BLOOD, "$n appears from a swirling cloud of mist!", d->character, NULL, NULL, TO_ROOM ); */
            d->connected = CON_PLAYING;
            do_restore( d->character, "self" );
            msdp_update_one_player( d );
        }
    }

    // Restore ship pilots
    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( !ship->piloting && !NULLSTR( ship->pilot_name ) )
        {
            CHAR_DATA* pilot_char = get_player_world( ship->pilot_name );
            if ( pilot_char && pilot_char->in_room && pilot_char->in_room->vnum >= ship->firstroom && pilot_char->in_room->vnum <= ship->lastroom )
                ship->piloting = pilot_char;
        }
    }

    // Restore droid controllers
    CHAR_DATA* controller = NULL;

    for ( DROID_DATA* droid = first_droid; droid; droid = droid->next )
    {
        controller = controller_from_droid( droid );
        if ( controller && droid->active != DROID_STATE_IGNORE )
        {
            add_follower( droid->mob, controller, true );
            droid->mob->leader = controller;
        }
    }


    log_string( "<>---> Warmboot complete <---<>" );
    unlink( buf );
    fclose ( fp );
    /* Safety, close the child functions */
    wait( NULL );

}

