CMDF do_cpywarn( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    DESCRIPTOR_DATA* d = NULL;
    bool canceled = FALSE;

    if ( !is_number( argument ) )
    {
        echo_to_all( AT_RED, "Copyover in 1 minute. We apologize for the short disruption in your gameplay!", ECHOTAR_ALL );
        argument = "60";
    }
    else
    {
        if ( atoi( argument ) > 1 )
            snprintf( buf, MSL, "Copyover in %d seconds. We apologize for the short disruption in your gameplay!", atoi( argument ) );
        else if ( atoi( argument ) == 0 )
        {
            snprintf( buf, MSL, "Copyover cancelled!" );
            canceled = TRUE;
        }
        else
            snprintf( buf, MSL, "Copyover in %d second. We apologize for the short disruption in your gameplay!", atoi( argument ) );

        echo_to_all( AT_RED, buf, ECHOTAR_ALL );
    }

    if ( canceled == FALSE )
    {
        echo_to_all( AT_RED, "This is our way of rolling out new features and other code changes without fully rebooting the MUD. It should take about 30 seconds once the copyover begins.", ECHOTAR_ALL );
        echo_to_all( AT_WHITE, "Please do not launch or land ships until it has passed.", ECHOTAR_ALL );
        echo_to_all( AT_DGREY, "If you open a writing buffer you will be disconnected.", ECHOTAR_ALL );
        echo_to_all( AT_WHITE, "If you are in the middle of a skill, just restart it after the copyover.", ECHOTAR_ALL );
        do_restore( ch, "all" );
        interpret( ch, "wpeace", FALSE );
        interpret( ch, "saveall", FALSE );
    }

    for ( d = first_descriptor ; d ; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character || d->character == NULL )
            continue;

        WAIT_STATE ( d->character, 6 );
    }

    sysdata.cpy_char = ch;
    sysdata.cpy = atoi( argument );
    sysdata.autocopy = AUTOCOPY_NORMAL; // just in case the ch leaves on us
    update_publish_status( STATUS_COPYOVER_WARN );
    return;
}

