void show_commprompt( DESCRIPTOR_DATA* d )
{
    CHAR_DATA* ch = NULL;
    extern bool mud_down;

    if ( !validate_desc( d ) )
        return;

    if ( !d || d == NULL )
        return;

    if ( !d->character || d->character == NULL )
        return;

    /*  GRAL VALGRIND d already free'd?
         Do I want another CONNECTION STATE for terminating..
    */
    /*
        Bust a prompt.
        PCFLAG_COMMPROMPT, if set, will only display a prompt when you
        enter a command. Cuts down on screen spam massively.

        Character gets spammed out, game loop accrues prompts and can't send them
    */
    if ( d && !mud_down && d->connected == CON_PLAYING )
    {
        ch = d->original ? d->original : d->character;

        if ( !has_pcflag( ch, PCFLAG_COMMPROMPT ) )
        {
            write_to_buffer( d, "\n", 2 );

            if ( has_pcflag( ch, PCFLAG_PROMPT ) )
                display_prompt( d );

            if ( has_pcflag( ch, PCFLAG_TELNET_GA ) && !d->pProtocol->bSGA )
                write_to_buffer( d, ( char* )GoAheadStr, 0 );
        }
    }
}
