/*
    Character not in position for command?
*/
bool check_pos( CHAR_DATA* ch, sh_int position )
{
    if ( ch->position < position )
    {
        switch ( ch->position )
        {
            case POS_DEAD:
                ch_println( ch, "A little difficult to do when you are DEAD..." );
                break;

            case POS_MORTAL:
            case POS_INCAP:
                ch_println( ch, "You are hurt far too bad for that." );
                break;

            case POS_STUNNED:
                ch_println( ch, "You are too stunned to do that." );
                break;

            case POS_SLEEPING:
                ch_println( ch, "In your dreams, or what?" );
                break;

            case POS_RESTING:
                ch_println( ch, "Nah... You feel too relaxed..." );
                break;

            case POS_SITTING:
                ch_println( ch, "You can't do that sitting down." );
                break;

            case POS_FIGHTING:
                ch_println( ch, "No way!  You are still fighting!" );
                break;
        }

        return FALSE;
    }

    return TRUE;
}

