bool sql_cmd_log( CHAR_DATA *ch, char* chname, char* cmdname, char* args, sh_int trust, bool is_order, bool realcmd )
{
    if (ch && IS_NPC(ch)) 
        return FALSE;
    SHIP_DATA *ship = NULL;
    time_t tm = time( 0 );
    cJSON *json_context = cJSON_CreateObject();
    if ( ch != NULL && ch->in_room != NULL )
    {
        if (ch->in_room->first_person != ch && ch->in_room->last_person != ch) {
            cJSON *char_array = cJSON_CreateArray();
            for ( CHAR_DATA* rch = ch->in_room->first_person; rch; rch = rch->next_in_room ) {
                cJSON_AddItemToArray(char_array,cJSON_CreateString(rch->name));
            }
            cJSON_AddItemToObject(json_context, "chars_in_room", char_array);
        }
        if ( isFighting(ch) || ch->fighting || ch->held || ch->position <= POS_STUNNED || IS_AFFECTED( ch, AFF_POISON ) || ch->hit < ch->max_hit) {
            cJSON_AddItemToObject(json_context, "curr_hp", cJSON_CreateNumber(ch->hit));
            cJSON_AddItemToObject(json_context, "max_hp", cJSON_CreateNumber(ch->max_hit));
            cJSON_AddItemToObject(json_context, "curr_move", cJSON_CreateNumber(ch->move));
            cJSON_AddItemToObject(json_context, "max_move", cJSON_CreateNumber(ch->max_move));
            if (ch->perm_frc > 0)
            {
                cJSON_AddItemToObject(json_context, "curr_mana", cJSON_CreateNumber(ch->mana));
                cJSON_AddItemToObject(json_context, "max_mana", cJSON_CreateNumber(ch->max_mana));
            }
        }

        if ( ch->in_room && ( ship = get_ship_from_room( ch->in_room ) ) != NULL ) {
            cJSON_AddItemToObject(json_context, "ship_id", cJSON_CreateNumber(ship->id));
            cJSON_AddItemToObject(json_context, "ship_name", cJSON_CreateString(ship->name));
            cJSON_AddItemToObject(json_context, "ship_state", cJSON_CreateString(s_states[ship->shipstate]));
            if ( ship->starsystem ) {
                cJSON_AddItemToObject(json_context, "ship_in_starsystem", cJSON_CreateString(ship->starsystem->name));

                if (ship_is_fighting(ship))
                {
                    cJSON_AddItemToObject(json_context, "ship_hull", cJSON_CreateNumber(ship->hull));
                    cJSON_AddItemToObject(json_context, "ship_max_hull", cJSON_CreateNumber(ship->maxhull));
                }
            }
            if ( ship->in_room ) {
                cJSON_AddItemToObject(json_context, "ship_in_room", cJSON_CreateNumber(ship->in_room->vnum));
            }
        }
    }

    return upsert_sql_row_with_flags(
        "cmdlog",
        FLAG_NO_UPSERT, 
        sql_unique_id(NULL),
        sql_string("char", ch ? ch->name : chname),
        sql_string("cmd", cmdname),
        sql_string("args", args),
        sql_int("trust", ch ? get_trust(ch) : trust),
        sql_int("is_order", is_order),
        sql_long("time", (int)tm),
        sql_int("realcmd", realcmd),
        sql_int("vnum", (ch && ch->in_room) ? ch->in_room->vnum : 0),
        sql_json("context", json_context, true),
        LAST_DB_VALUE
    );

}

DISALLOW_DATA* is_restricted( CHAR_DATA* ch, char* argument )
{
    DISALLOW_DATA* disallow = NULL, *dnext = NULL;
    ACCOUNT_DATA* acc = NULL;

    for ( disallow = ch->pcdata->first_disallow; disallow; disallow = dnext )
    {
        dnext = disallow->next;
        if ( disallow->end_time < current_time )
        {
            char buf[MIL];
            snprintf( buf, MIL, "Disallow of %s expiring for %s", disallow->command, ch->name );
            log_string( buf );
            UNLINK( disallow, ch->pcdata->first_disallow, ch->pcdata->last_disallow, next, prev );
            FREE_STRUCT_NORET( disallow, disallow_fields );
            continue;
        }
        else if ( !str_cmp( disallow->command, argument ) )
            return disallow;
    }

    acc = ch->pcdata->account ? ch->pcdata->account : ( ( ch->desc && ch->desc->account ) ? ch->desc->account : NULL );
    if ( acc )
    {
        for ( disallow = acc->first_disallow; disallow; disallow = dnext )
        {
            dnext = disallow->next;
            if ( disallow->end_time < current_time )
            {
                char buf[MIL];
                snprintf( buf, MIL, "Disallow of %s expiring for @%s", disallow->command, acc->name );
                log_string( buf );
                UNLINK( disallow, acc->first_disallow, acc->last_disallow, next, prev );
                FREE_STRUCT_NORET( disallow, disallow_fields );
                continue;
            }
            else if ( !str_cmp( disallow->command, argument ) )
                return disallow;
        }
    }

    return NULL;
}

bool check_censor( CHAR_DATA *ch, ACCOUNT_DATA *account) {
    if(!ch && !account) {
        return false;
    }

    if(ch && IS_NPC(ch)) {
        return false;
    }

    if(!account && ch && ch->pcdata && ch->pcdata->account) {
        account = ch->pcdata->account;
    }

    if(!account || NULLSTR( account->email) || !account->emailconfirmed) {
        return true;
    }

    return false;
}

/*
    The main entry point for executing commands.
    Can be recursively called from 'at', 'order', 'force'.
*/
/*
    void interpret( CHAR_DATA *ch, char *argument )
*/
void interpret( CHAR_DATA* ch, char* argument, bool is_order )
{
    char command[MIL], logline[XMIL], logname[MIL], buf[MIL];
    TIMER* timer = NULL;
    CMDTYPE* cmd = NULL;
    LUA_COMMAND* lua_cmd = NULL;
    SKILL_DATA* skill = NULL;
    DISALLOW_DATA* disallow = NULL;
    int trust, i = 0;
    int loglvl;
    bool found;
    bool lua_found = false;
    struct timeval time_used;
    long tmptime;
    bool held = FALSE, ooc = FALSE, action = FALSE;

    if ( !ch )
    {
        bug( "interpret: null ch!", 0 );
        return;
    }

    /*
        It strikes me as unlikely, but possible, that someone or something would still
        be trying to stuff commands in even after it is on the extraction queue. Once
        someone is on the extraction queue, we can't assume that it is safe enough
        for them to do ANYTHING. So, in the interests of being safe, I say, fuck off
        we're not going to do what you ask us to do. This also strikes me as one of the
        few possible edge cases where cmdstack could fuck up - it is trying to dealloc/free
        stuff that is being free'd elsewhere.
        ~Miros <3
    */
    if ( char_extracted( ch ) )
    {
        bug( "interpret: char died or was extracted, refusing to proceed!" );
        return;
    }


    /* General limiter, Orion */
    smash_tilde( argument );
    one_argument( argument, buf );
    // Allocate temp_buffer in the function scope
    char temp_buffer[MIL];
    // if it is a restricted command, and we are prod, and you are censored....
    if ( restricted_command( buf ) && !is_not_production() && check_censor( ch, NULL ) )
    {
        strlcpy( temp_buffer, argument, MIL );
        profanity_filter(temp_buffer);
        argument = temp_buffer;
    }
    /* color initialization */
    set_char_color( AT_WHITE, ch );

    increment_counter( &sysdata.metrics, "commands", FLAG_AUTO_GAUGE );

    if ( !IS_NPC( ch ) && ch->desc && !ch->desc->account )
        ch->desc->account = account_from_name( ch->name );

    if ( !IS_NPC( ch ) && ( disallow = is_restricted( ch, buf ) ) != NULL )
    {
        if ( NULLSTR( disallow->reason ) )
            ch_println( ch, "&wYou have been restricted from using this command." );
        else
            ch_println( ch, "&wYou have been restricted from using this command because: %s", disallow->reason );

        return;
    }

    if ( !IS_NPC( ch ) && !is_cg( ch ) && get_trust( ch ) <= LEVEL_HERO && xIS_SET( ch->race->specflags, RSPECFLAG_FIRRERREO ) && restricted_command( buf ) &&
            ch->pcdata->real_name[0] == '\0' )
    {
        ch_println( ch, "You must set your real name. Type REALNAME <name> to set it." );
        return;
    }

    // Gral - grandfather all level 30 people (you can no longer mainchange) their racial levels into their pfile
    //        Theoretically the min level you can have is 1 so this should not loop if the race has 0 as the combat level
    if ( !is_cg( ch ) && get_trust( ch ) <= LEVEL_HERO && ch->top_level >= 30 && !IS_NPC( ch ) && ch->legacymax[0] < 1 )
    {
        int ra;

        for ( ra = 0; ra < MAX_ABILITY; ra++ )
        {
            ch->legacymax[ra] = UMAX( 1, ch->race->main_table[ch->main_ability][ra] );
        }

        if ( ch->pcdata->frank == FRANK_NONE )
            ch_println( ch, "&wYour maximum levels for your race/main choice are now set.\nYou can no longer use &cmainchange &wto change your main class." );
        else
            ch_println( ch, "&wYour maximum levels for your race/main choice have now been reset with your new forcerank." );
    }

    // Gral changed from all players to just forcers ch->pcdata->frank
    //    if ( !is_cg(ch) && get_trust( ch ) <= LEVEL_HERO && ch->top_level >= 50 && !IS_NPC( ch ) && restricted_command( buf ) &&
    //            ch->pcdata->alignment == NO_ALIGN )
    if ( !IS_NPC( ch ) && !is_cg( ch ) && get_trust( ch ) <= LEVEL_HERO && ch->pcdata->frank > FRANK_NONE && restricted_command( buf ) &&
            ch->pcdata->alignment == NO_ALIGN )
    {
        //        ch_println( ch, "You must choose an alignment to proceed past level 50. (alignment command)" );
        ch_println( ch, "You must choose an alignment upon being awoken. (alignment command)" );
        return;
    }

    if ( !IS_NPC( ch ) && ch->pcdata->email[0] == '\0' && ch->desc && ch->desc->account && ch->desc->account->email[0] != '\0' )
    {
        SET_STRING( ch->pcdata->email, ch->desc->account->email );
    }

    /*  if ( !is_cg(ch) && get_trust( ch ) <= LEVEL_HERO && !IS_NPC( ch ) && restricted_command( buf ) && (!ch->pcdata->email || ch->pcdata->email[0] == '\0' || !str_cmp(ch->pcdata->email,"(null)") ) && !has_pcflag( ch, PCFLAG_AFK ))
        {
         ch_println( ch, "You must enter an e-mail address for us to contact you at (you wont receive any spam). (email command)" );
         return;
        }*/
    /*  if ( !is_cg(ch) && get_trust( ch ) <= LEVEL_HERO && ch->top_level >= 100 && !IS_NPC( ch ) && restricted_command( buf ) &&
           ch->pcdata->charsheet[0] == '\0' )
        {
           ch_println( ch, "You must complete your character sheet to proceed past level 100 (Use the charsheet command, &RNOTE: It can only be used ONCE, after that you must use think)&W." );
           return;
        }*/
    if ( !is_cg( ch ) && ch->desc && get_trust( ch ) >= 20 && restricted_command( buf ) && !ch->desc->account )
    {
        ch_println( ch, "&RAccounts are mandatory on LotJ. &CHELP ACCOUNT &Rfor information.\n&zType &CACCOUNT &z<&Cnew name&z> &CCREATE&z or &CACCOUNT &z<&Cexisting account&z> &z<&Caccount password&z> to associate this character with an account." );
        return;
    }
    else if ( sysdata.confirmedemail == TRUE && get_trust( ch ) >= 20 && !is_cg( ch ) && ch->desc && restricted_command( buf ) && ch->desc->account && ch->desc->account->emailconfirmed == FALSE )
    {
        ch_println( ch, "&RPlease confirm your account email before proceeding.\n&zType &CACCOUNT email &z<&Cemail&z> to trigger a confirmation email and then follow the instructions in the email to confirm your account." );
        return;
    }

    if ( !is_cg( ch ) && ch->desc && !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_NEWNAME ) && restricted_command( buf ) )
    {
        ch_println( ch, "&RYou must select a new name in order to proceed.\n&WTo select a new name type &G\"newname <new name>\"&W." );
        return;
    }

    if ( !is_cg( ch ) && !IS_NPC( ch ) && get_trust( ch ) < sysdata.log_level && !has_pcflag( ch, PCFLAG_PICKEDSKIN ) )
        ch_println( ch, "&RPlease select your skincolor with &WSETSKINCOLOR!" );

    action = rprog_action_trigger( ch, argument );
    found = FALSE;

    if ( ch->substate == SUB_REPEATCMD )
    {
        DO_FUN* fun;

        if ( ( fun = ch->last_cmd ) == NULL )
        {
            ch->substate = SUB_NONE;
            bug( "interpret: SUB_REPEATCMD with NULL last_cmd", 0 );
            return;
        }
        else
        {
            int x;

            /*
                yes... we lose out on the hashing speediness here...
                but the only REPEATCMDS are wizcommands (currently)
            */
            for ( x = 0; x < 126; x++ )
            {
                for ( cmd = command_hash[x]; cmd; cmd = cmd->next )
                    if ( cmd->do_fun == fun )
                    {
                        found = TRUE;
                        break;
                    }

                if ( found )
                    break;
            }

            if ( !found )
            {
                cmd = NULL;
                bug( "interpret: SUB_REPEATCMD: last_cmd invalid", 0 );
                return;
            }

            snprintf( logline, XMIL, "(%s) %s", cmd->name, argument );
        }
    }

    if ( !cmd )
    {
        /* Changed the order of these ifchecks to prevent crashing. */
        if ( !argument || !strcmp( argument, "" ) )
        {
            bug( "interpret: null argument!", 0 );
            return;
        }

        /*
            Strip leading spaces.
        */
        while ( isspace( *argument ) )
            argument++;

        if ( NULLSTR( argument ) )
            return;

        /* xREMOVE_BIT( ch->affected_by, AFF_HIDE ); */

        /*
            Implement freeze command.
        */
        if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_FREEZE ) )
        {
            ch_println( ch, "You're totally frozen!" );
            return;
        }

        /*
            Grab the command word.
            Special parsing so ' can be a command,
             also no spaces needed after punctuation.
        */
        strlcpy( logline, argument, XMIL );

        if ( !isalpha( argument[0] ) && !isdigit( argument[0] ) && argument[0] != '.' && argument[0] != '#' )
        {
            command[0] = argument[0];
            command[1] = '\0';
            argument++;

            while ( isspace( *argument ) )
                argument++;
        }
        else
            argument = one_argument( argument, command );

        /*
            Look for command in command table.
            Check for council powers and/or bestowments
        */
        trust = get_trust( ch );

        for ( cmd = command_hash[LOWER( command[0] ) % 126]; cmd; cmd = cmd->next )
            if ( !str_prefix( command, cmd->name )
                    &&   ( cmd->level <= trust
                           ||  ( !IS_NPC( ch ) && ch->pcdata->bestowments && ch->pcdata->bestowments[0] != '\0'
                                 &&    is_name( cmd->name, ch->pcdata->bestowments )
                                 &&    cmd->level <= ( trust + 5 ) ) ) )
            {
                found = TRUE;
                break;
            }

        if ( !found && ( lua_cmd = find_lua_command( command, ch ) ) )
            lua_found = TRUE;

        // Only check lprog command triggers if they're not AFK and it matched no real command.
        if ( !has_pcflag( ch, PCFLAG_AFK ) && !found && !lua_found && !action )
        {
            action = lua_trigger_on_room_command( ch, command, argument );

            if ( !action )
            {
                // If we didn't find a match in the room, try on relevant objects
                // Iterates over all applicable objects (in character inventory, equip, or room).
                // If any trigger on this, it stops after the first.
                OBJ_DATA* next_obj = NULL;
                ROOM_INDEX_DATA* room = ch->in_room;

                if ( room )
                {
                    for ( OBJ_DATA* obj = room->first_content; obj; obj = next_obj )
                    {
                        next_obj = obj->next_content;
                        action = lua_trigger_on_obj_command( ch, obj, command, argument );

                        if ( action )
                            break;
                    }
                }

                if ( !action )
                {
                    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = next_obj )
                    {
                        next_obj = obj->next_content;
                        action = lua_trigger_on_obj_command( ch, obj, command, argument );

                        if ( action )
                            break;
                    }
                }
            }
        }

        /*
            Turn off afk bit when any command performed.
               Changed to a continuous state.  Orion
        */
        if ( has_pcflag( ch, PCFLAG_AFK )  && ( str_cmp( command, "AFK" ) ) && ( ( cmd && cmd->level < 101 && cmd->ooc == 0 ) || !cmd ) && ( ( lua_cmd && lua_cmd->ooc == 0 ) || !lua_cmd ) )
        {
            /*        remove_pcflag( ch, PCFLAG_AFK );
                        act( AT_GREY, "$n is no longer afk.", ch, NULL, NULL, TO_ROOM );*/
            ch_println( ch, "You must turn off AFK first! Type AFK to toggle it off." );
            return;
        }
    }

    /*
        Log and snoop.
        GRAL Clean this up already.
    */


    if ( ( found && cmd->log == LOG_NEVER ) || ( lua_found && lua_cmd->log == LOG_NEVER ) || ( cmd && !str_cmp( cmd->name, "account" ) && !stristr( logline, "email" ) && !stristr( logline, "create" ) && !stristr( logline, "discorduuid" ) && !stristr( logline, "referredby" ) && !stristr( logline, "emailconfirm" ) && !stristr( logline, "prompt" ) && !stristr( logline, "fprompt" ) && !stristr( logline, "chatname" ) ) )
        strlcpy( logline, "XXXXXXXX XXXXXXXX XXXXXXXX", XMIL );

    snprintf( lastplayercmd, SUPER_MIL, "** %s: %s", ch->name, logline );
    loglvl = ( skill && skill->log != LOG_NORMAL ) ? skill->log : ( found ? cmd->log : ( lua_found ? lua_cmd->log : LOG_NORMAL ) );

    if ( ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_LOG ) )
            ||   fLogAll
            ||   loglvl == LOG_BUILD
            ||   loglvl == LOG_HIGH
            ||   loglvl == LOG_ALWAYS )
    {
        /*  Added by Narn to show who is switched into a mob that executes
            a logged command.  Check for descriptor in case force is used. */
        if ( ch->desc && ch->desc->original )
            snprintf( log_buf, MSL, "Log %s (%s): %s", ch->name,
                     ch->desc->original->name, logline );
        else
            snprintf( log_buf, MSL, "Log %s: %s", ch->name, logline );

        /*
            Make it so a 'log all' will send most output to the log
            file only, and not spam the log channel to death -Thoric
        */
        if ( fLogAll && loglvl == LOG_NORMAL
                &&  ( IS_NPC( ch ) || !has_pcflag( ch, PCFLAG_LOG ) ) )
            loglvl = LOG_ALL;

        log_string_plus( log_buf, loglvl, get_trust( ch ) );
    }

    /*
        Full Logging system for Immortals
        Generated under LOG Directory, as immortal.log
    */
    if ( !IS_NPC( ch ) )
    {
        if ( cmd )
        {
            if ( cmd->log == LOG_NEVER || ( (!str_cmp( cmd->name, "account" ) || !str_cmp( cmd->name, "resign" )) && !stristr( argument, "email" ) && !stristr( argument, "create" ) && !stristr( argument, "discorduuid" ) && !stristr( argument, "referredby" ) && !stristr( argument, "emailconfirm" ) && !stristr( argument, "prompt" ) && !stristr( argument, "fprompt" ) && !stristr( argument, "chatname" ) ) )
            {
                cmdstack( ch, buf, "XXXXXXXX XXXXXXXX XXXXXXXX", time( 0 ) );
                sql_cmd_log( ch, NULL, cmd->name, "XXXXXXXX XXXXXXXX XXXXXXXX", 0, is_order, TRUE );
            }
            else
            {
                if ( !str_cmp( cmd->name, "'" ) )
                {
                    cmdstack( ch, cmd->name, buf, time( 0 ) );
                }
                else
                {
                    cmdstack( ch, buf, argument, time( 0 ) );
                }

                sql_cmd_log( ch, NULL, cmd->name, argument, 0, is_order, TRUE );

            }
        }
        else
        {
            cmdstack( ch, buf, argument, time( 0 ) );
            sql_cmd_log( ch, NULL, command, argument, 0, is_order, FALSE );
        }
    }

    for ( i = 0; i <= 5; i++ )
    {
        if ( ch->desc && ch->desc->snoop_by[i] )
        {
            snprintf( logname, MIL, "%s", ch->name );
            write_to_buffer( ch->desc->snoop_by[i], logname, 0 );
            write_to_buffer( ch->desc->snoop_by[i], "% ",    2 );
            write_to_buffer( ch->desc->snoop_by[i], logline, 0 );
            write_to_buffer( ch->desc->snoop_by[i], "\n",  2 );
        }
    }

    if ( ( ( found ) && cmd->ooc == 0 && ch->action_timer > 0 ) || ( lua_found && !lua_cmd->ooc && ch->action_timer > 0 ) )
        action_clear( ch );

    if ( ( ( found ) && !cmd->spirit && cmd->manifest ) || ( lua_found && !lua_cmd->spirit && lua_cmd->manifest ) )
        bug( "Command %s requires manifest but cannot be used by spirits.", cmd->name );

    if ( ( ( found ) && ch->spirit && !cmd->spirit && cmd->ooc <= 0 ) || ( lua_found && ch->spirit && !lua_cmd->spirit && !lua_cmd->ooc ) )
    {
        ch_println( ch, "Spirits can't do that!" );
        return;
    }

    if ( ( ( found ) && ch->spirit && !cmd->manifest && !ch->manifest && cmd->ooc <= 0 ) || ( lua_found && ch->spirit && !lua_cmd->manifest && !ch->manifest && !lua_cmd->ooc ) )
    {
        ch_println( ch, "You must be manifested in order to use this command." );
        return;
    }

    if ( found )
    {
        /* all imm commands are ooc */
        if ( cmd->ooc || cmd->level > LEVEL_IMMORTAL )
            ooc = TRUE;

        if ( cmd->held )
            held = TRUE;
    }
    else if ( lua_found )
    {
        if ( lua_cmd->ooc || lua_cmd->level > LEVEL_IMMORTAL )
            ooc = TRUE;

        if ( lua_cmd->held )
            held = TRUE;
    }
    else
    {
        skill = ( ch->last_skill_used && ( !str_cmp( command, ch->last_skill_used->name ) || !str_prefix( command, ch->last_skill_used->name ) ) ) ? ch->last_skill_used : skill_from_name( command );

        if ( skill != NULL && skill->held )
            held = TRUE;

        if ( find_social( command ) )
            held = TRUE;
    }

    if ( ch->held == TRUE && !ooc && !held && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You cannot do that while restrained!" );
        return;
    }

    if ( !IS_NPC( ch ) && cmd && ( disallow = is_restricted( ch, cmd->name ) ) != NULL )
    {
        if ( NULLSTR( disallow->reason ) )
            ch_println( ch, "&wYou have been restricted from using this command." );
        else
            ch_println( ch, "&wYou have been restricted from using this command because: %s", disallow->reason );

        return;
    }

    timer = get_timerptr( ch, TIMER_DO_FUN );

    if (
        cmd &&
        cmd->ooc == 0 &&
        timer &&
        ( timer->comms_interrupt == true || ( str_cmp( cmd->name, "clantalk" ) && str_cmp( cmd->name, "talk" ) ) )
    )
    {
        interrupt_ch( ch );
    }

    /*
        Look for command in skill and socials table.
    */
    if ( !found && !lua_found )
    {
        if ( skill )
            ch->last_skill_used = skill;

        if ( !check_skill( ch, command, argument )
                &&   !check_social( ch, command, argument )
           )
        {
            EXIT_DATA* pexit;

            /* check for an auto-matic exit command */
            if ( ( pexit = find_door( ch, command, TRUE ) ) != NULL
                    &&   xIS_SET( pexit->flags, EX_xAUTO ) )
            {
                if ( xIS_SET( pexit->flags, EX_CLOSED )
                        && ( !IS_AFFECTED( ch, AFF_PASS_DOOR )
                             ||   xIS_SET( pexit->flags, EX_NOPASSDOOR ) ) )
                {
                    if ( !xIS_SET( pexit->flags, EX_SECRET ) )
                        act( AT_PLAIN, "The $d is closed.", ch, NULL, pexit->keyword, TO_CHAR );
                    else
                        ch_println( ch, "You cannot do that here." );

                    return;
                }

                interrupt_ch( ch );
                move_char( ch, pexit, 0, FALSE );
                return;
            }

            if ( !action )
                ch_println( ch, "Huh?" );
        }

        return;
    }

    /*
        Character not in position for command?
    */
    if ( ( found && !check_pos( ch, cmd->position ) ) || ( lua_found && !check_pos( ch, lua_cmd->position ) ) )
        return;

    if ( lua_found )
    {
        if ( !ooc )
            lua_trigger_on_ch( ch, LUA_TRIGGER_CH_ON_INTERRUPT );

        if ( !dispatch_lua_command( lua_cmd, ch, argument ) )
            ch_println( ch, "Huh!" );


        flush_output(ch->desc, FALSE);
        return;
    } //lua processing never goes below this line

    /* PC Charm check might change this to some kind of table at a later point */
    if ( !IS_NPC( ch ) && is_order && IS_AFFECTED( ch, AFF_CHARM ) &&
            str_cmp( cmd->name, "get" ) &&
            str_cmp( cmd->name, "drop" ) &&
            str_cmp( cmd->name, "leave" ) &&
            str_cmp( cmd->name, "board" ) &&
            str_cmp( cmd->name, "sit" ) &&
            str_cmp( cmd->name, "stand" ) &&
            str_cmp( cmd->name, "remove" ) &&
            str_cmp( cmd->name, "north" ) &&
            str_cmp( cmd->name, "south" ) &&
            str_cmp( cmd->name, "west" ) &&
            str_cmp( cmd->name, "east" ) &&
            str_cmp( cmd->name, "nw" ) &&
            str_cmp( cmd->name, "ne" ) &&
            str_cmp( cmd->name, "sw" ) &&
            str_cmp( cmd->name, "se" ) &&
            str_cmp( cmd->name, "up" ) &&
            str_cmp( cmd->name, "down" ) )
    {
        ch_println( ch, "You can't be ordered to do that..." );
        return;
    }

    /* charmed players can do the following commands */
    if ( !IS_NPC( ch ) && !is_order && IS_AFFECTED( ch, AFF_CHARM ) &&
            str_cmp( cmd->name, "say" ) &&
            str_cmp( cmd->name, "clan" ) &&
            str_cmp( cmd->name, "chat" ) &&
            str_cmp( cmd->name, "emote" ) &&
            str_cmp( cmd->name, "shout" ) &&
            str_cmp( cmd->name, "yell" ) )
    {
        if ( !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "You can't do that while apprehended..." );
            return;
        }
        else
            xREMOVE_BIT( ch->affected_by, AFF_CHARM );
    }

    /*  Berserk check for flee.. maybe add drunk to this?.. but too much
        hardcoding is annoying.. -- Altrag */
    if ( !str_cmp( cmd->name, "flee" ) &&
            IS_AFFECTED( ch, AFF_BERSERK ) )
    {
        ch_println( ch, "You aren't thinking very clearly.." );
        return;
    }

    /*
        Dispatch the command.
    */
    ch->prev_cmd = ch->last_cmd;    /* haus, for automapping */
    ch->last_cmd = cmd->do_fun;

    if ( !ooc )
        lua_trigger_on_ch( ch, LUA_TRIGGER_CH_ON_INTERRUPT );

    start_timer( &time_used );

    if ( !lua_hook_cmd( cmd, ch, argument ) )
        ( *cmd->do_fun ) ( ch, argument );

    end_timer( &time_used );
    flush_output(ch->desc, FALSE);
    /*
        Update the record of how many times this command has been used (haus)
    */
    update_userec( &time_used, &cmd->userec );
    tmptime = UMIN( time_used.tv_sec, 19 ) * 1000000 + time_used.tv_usec;

    snprintf( log_buf, MSL, "[*****] LAG: %s: %s %s (R:%d S:%ld.%06ld)", ch->name,
                cmd->name, ( cmd->log == LOG_NEVER ? "XXX" : argument ),
                ch->in_room ? ch->in_room->vnum : 0,
                time_used.tv_sec, time_used.tv_usec );

    /* laggy command notice: command took longer than .5 seconds */
    if ( tmptime > 500000 )
    {
        log_string_plus( log_buf, LOG_NORMAL, get_trust( ch ) );
        write_to_log("slowcmd", log_buf, sysdata.log_level, 72, true);
    }

    if ( get_trust( ch ) < 101 || is_not_production() )
    {
        snprintf( log_buf, MSL, "cmd_time: %s: %s %s (R:%d S:%ld.%06ld)", ch->name,
                 cmd->name, ( cmd->log == LOG_NEVER ? "XXX" : strrep( argument, "%", "@" ) ),
                 ch->in_room ? ch->in_room->vnum : 0,
                 time_used.tv_sec, time_used.tv_usec );
        debug( log_buf );
    }

    tail_chain( );
}

CMDTYPE* find_command( const char* command )
{
    CMDTYPE* cmd;
    int hash;

    if(command[0] == '.')
        hash = LOWER( command[1] ) % 126;
    else
        hash = LOWER( command[0] ) % 126;

    for ( cmd = command_hash[hash]; cmd; cmd = cmd->next ) {
        if(command[0] == '.') { // if the input command starts with ., match the command exactly
            if( !str_cmp( command+1, cmd->name ) ) 
                return cmd;
        } else {
            if ( !str_prefix( command, cmd->name ) )
                return cmd;
        }
    }

    return NULL;
}


SOCIALTYPE* find_social( char* command )
{
    SOCIALTYPE* social;
    int hash;
    char c = LOWER( command[0] );

    if ( c < 'a' || c > 'z' )
        hash = 0;
    else
        hash = ( c - 'a' ) + 1;

    for ( social = social_index[hash]; social; social = social->next )
        if ( !str_prefix( command, social->name ) )
            return social;

    return NULL;
}
bool check_social( CHAR_DATA* ch, char* command, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    SOCIALTYPE* social;

    if(command[0] == '#')
        command++;

    if ( ( social = find_social( command ) ) == NULL )
        return FALSE;

    if ( IS_AFFECTED( ch, AFF_INVISIBLE ) )
    {
        ch_println( ch, "You can't social while invisible." );
        return TRUE;
    }

    if ( IS_AFFECTED( ch, AFF_HIDE ) )
        do_visible( ch, "" );

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_NO_EMOTE ) )
    {
        ch_println( ch, "You are anti-social!" );
        return TRUE;
    }

    switch ( ch->position )
    {
        case POS_DEAD:
            ch_println( ch, "Lie still; you are DEAD." );
            return TRUE;

        case POS_INCAP:
        case POS_MORTAL:
            ch_println( ch, "You are hurt far too bad for that." );
            return TRUE;

        case POS_STUNNED:
            ch_println( ch, "You are too stunned to do that." );
            return TRUE;

        case POS_SLEEPING:

            /*
                I just know this is the path to a 12" 'if' statement.  :(
                But two players asked for it already!  -- Furey
            */
            if ( !str_cmp( social->name, "snore" ) )
                break;

            ch_println( ch, "In your dreams, or what?" );
            return TRUE;
    }

    //    lua_trigger_on_ch(ch,LUA_TRIGGER_CH_ON_INTERRUPT);
    if ( social->timer != 0 )
        action_clear( ch );

    one_argument( argument, arg );
    victim = NULL;

    if ( NULLSTR( arg ) )
    {
        if ( ch->sex != social->gender && social->gender > 0 )
        {
            ch_println( ch, "You're not the right gender to do that." );
            return TRUE;
        }

        act( AT_SOCIAL, social->others_no_arg, ch, NULL, victim, TO_ROOM    );
        act( AT_SOCIAL, social->char_no_arg,   ch, NULL, victim, TO_CHAR    );

        if ( social->naction )
            action_set( ch, NULL, social->naction, NULL, social->timer );
    }
    else if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return TRUE;
    }
    else if ( victim->sex != social->genderto && social->genderto > 0 )
    {
        ch_println( ch, "But %s isn't the right gender to do that to.", g_name( victim, ch ) );
        return TRUE;
    }
    else if ( social->approach && !is_near( ch, victim ) && !is_near( victim, ch ) && get_trust( ch ) < 103 )
    {
        ch_println( ch, "What, from all the way over here? Get closer!" );
        return TRUE;
    }
    else if ( victim == ch )
    {
        act( AT_SOCIAL, social->others_auto,   ch, NULL, victim, TO_ROOM    );
        act( AT_SOCIAL, social->char_auto,     ch, NULL, victim, TO_CHAR    );

        if ( social->caction )
            action_set( ch, ch, social->caction, social->vaction, social->timer );
    }
    else
    {
        act( AT_SOCIAL, social->others_found,  ch, NULL, victim, TO_NOTVICT );
        act( AT_SOCIAL, social->char_found,    ch, NULL, victim, TO_CHAR    );
        act( AT_SOCIAL, social->vict_found,    ch, NULL, victim, TO_VICT    );

        if ( social->oaction && social->vaction )
            action_set( ch, victim, social->oaction, social->vaction, social->timer );

        if ( !IS_NPC( ch ) && IS_NPC( victim ) && !IS_AFFECTED( victim, AFF_CHARM )
                && IS_AWAKE( victim ) && !IS_SET( victim->pIndexData->progtypes, ACT_PROG ) )
        {
            switch ( number_bits( 4 ) )
            {
                case 0:
                    /*  if ( !xIS_SET(ch->in_room->flags, ROOM_SAFE ) || IS_EVIL(ch) )
                        multi_hit( victim, ch, TYPE_UNDEFINED );
                        else
                        if ( IS_NEUTRAL(ch) )
                        {
                        act( AT_ACTION, "$n slaps $N.",  victim, NULL, ch, TO_NOTVICT );
                        act( AT_ACTION, "You slap $N.",  victim, NULL, ch, TO_CHAR    );
                        act( AT_ACTION, "$n slaps you.", victim, NULL, ch, TO_VICT    );
                        }
                        else
                        {
                        act( AT_ACTION, "$n acts like $N doesn't even exist.",  victim, NULL, ch, TO_NOTVICT );
                        act( AT_ACTION, "You just ignore $N.",  victim, NULL, ch, TO_CHAR    );
                        act( AT_ACTION, "$n appears to be ignoring you.", victim, NULL, ch, TO_VICT    );
                        }*/
                    break;

                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                case 6:
                case 7:
                case 8:
                    /*  act( AT_SOCIAL, social->others_found, victim, NULL, ch, TO_NOTVICT );
                        act( AT_SOCIAL, social->char_found, victim, NULL, ch, TO_CHAR    );
                        act( AT_SOCIAL, social->vict_found, victim, NULL, ch, TO_VICT    );*/
                    break;

                case 9:
                case 10:
                case 11:
                case 12:
                    /*  act( AT_ACTION, "$n slaps $N.",  victim, NULL, ch, TO_NOTVICT );
                        act( AT_ACTION, "You slap $N.",  victim, NULL, ch, TO_CHAR    );
                        act( AT_ACTION, "$n slaps you.", victim, NULL, ch, TO_VICT    );*/
                    break;
            }
        }
    }

    /* Count people in the room */
    if ( ch->pcdata )
    {
        CHAR_DATA* rch;
        int cnt = 0;

        for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
            if ( rch != ch && !IS_NPC( rch ) )
                cnt++;

        shift_points( ch, ( cnt * 2 ) );
    }

    return TRUE;
}



/*
    Return true if an argument is completely numeric.
*/
bool is_number( const char* arg )
{
    if ( NULLSTR( arg ) )
        return FALSE;

    for ( ; *arg != '\0'; arg++ )
    {
        if ( !isdigit( *arg ) )
            return FALSE;
    }

    return TRUE;
}

bool is_number_sym( char* arg )
{
    if ( *arg == '\0' )
        return FALSE;

    for ( ; *arg != '\0'; arg++ )
    {
        if ( !isdigit( *arg ) && *arg != '-' && *arg != '+' )
            return FALSE;
    }

    return TRUE;
}

bool is_number_double( char* arg )
{
    if ( *arg == '\0' )
        return FALSE;

    for ( ; *arg != '\0'; arg++ )
    {
        if ( !isdigit( *arg ) && *arg != '-' && *arg != '+' && *arg != '.' )
            return FALSE;
    }

    return TRUE;
}


/*
    Given a string like 14.foo, return 14 and 'foo'
*/
int number_argument( const char* argument, char* arg )
{
    char* pdot;
    int number;

    // This is dirty, we force it to be non-const. We do modify the value, but we put
    // it right back afterward. Spirit of the law and all that.
    for ( pdot = (char*) argument; *pdot != '\0'; pdot++ )
    {
        if ( *pdot == '.' )
        {
            *pdot = '\0';
            number = atoi( argument );
            *pdot = '.';
            strlcpy( arg, pdot + 1, MIL );
            return number;
        }
    }

    strlcpy( arg, argument, MIL );
    return 1;
}

/*
    Pick off one argument from a string and return the rest.
    Understands quotes. No longer mangles case either. That used to be annoying.
*/
char* one_argument( const char* argument, char* arg_first )
{
    char cEnd;
    int count;
    count = 0;

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' || ++count >= 255 )
    {
        if ( *argument == cEnd )
        {
            argument++;
            break;
        }

        *arg_first = ( *argument );
        arg_first++;
        argument++;
    }

    *arg_first = '\0';

    while ( isspace( *argument ) )
        argument++;

    return ( char* ) argument;
}

/*
    Pick off one argument from a string and return the rest.
    Understands quotes.  Delimiters = { ' ', '-' }
    No longer mangles case either. That used to be annoying.
*/
char* one_argument2( char* argument, char* arg_first )
{
    char cEnd;
    short count;
    count = 0;

    if ( !argument || argument[0] == '\0' )
    {
        arg_first[0] = '\0';
        return argument;
    }

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' && count++ < 255 )
    {
        if ( *argument == cEnd || *argument == '-' )
        {
            argument++;
            break;
        }

        *arg_first = ( *argument );
        arg_first++;
        argument++;
    }

    *arg_first = '\0';

    while ( isspace( *argument ) )
        argument++;

    return argument;
}

/*
    Pick off one argument from a string and return the rest.
    Leaves quotes alone.
*/
char* one_argument_qt( const char* argument, char* arg_first )
{
    char cEnd;
    int count;
    count = 0;

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\"' || *argument == '\'')
    {
        *arg_first = *argument;
        arg_first++;
        *arg_first = '\0';
        argument++;
        return (char*) argument;
    }

    while ( *argument != '\0' || ++count >= 255 )
    {
        if ( *argument == '\"' || *argument == '\'' )
            break;

        if ( *argument == cEnd )
            break;

        *arg_first = ( *argument );
        arg_first++;
        argument++;
    }

    *arg_first = '\0';

    return (char*) argument;
}

