/*
    Pick off one argument from a string and return the rest.
    Understands quotes.  Delimiters = { ' ', ':' }
    Specifically useful for parsing time inputs
*/
char* one_argument_time( char* argument, char* arg_first )
{
    char cEnd;
    short count;
    count = 0;

    if ( !argument || argument[0] == '\0' )
    {
        arg_first[0] = '\0';
        return argument;
    }

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' && count++ < 255 )
    {
        if ( *argument == cEnd || *argument == ':' )
        {
            argument++;
            break;
        }

        *arg_first = ( *argument );
        arg_first++;
        argument++;
    }

    *arg_first = '\0';

    while ( isspace( *argument ) )
        argument++;

    return argument;
}

/*
    Pick off one argument from a string and return the rest.
    Understands quotes.  Delimiters = { ' ', ',' }
    Specifically useful for parsing time inputs
*/
char* one_argument_csv( char* argument, char* arg_first )
{
    char cEnd;
    short count;
    count = 0;

    if ( !argument || argument[0] == '\0' )
    {
        arg_first[0] = '\0';
        return argument;
    }

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' && count++ < 255 )
    {
        if ( *argument == cEnd || *argument == ',' )
        {
            argument++;
            break;
        }

        *arg_first = ( *argument );
        arg_first++;
        argument++;
    }

    *arg_first = '\0';

    while ( isspace( *argument ) )
        argument++;

    return argument;
}

/**
    Counts the number of arguments in a string, accounting for quotes
    'one arg' two three = 3
*/
int argument_count( char* argument )
{
    char* arg_ptr = argument;
    char cur_arg[MIL];
    int count = 0;

    while ( !NULLSTR( arg_ptr ) )
    {
        arg_ptr = one_argument( arg_ptr, cur_arg );
        count++;
    }

    return count;
}

bool is_plain_text( char* text )
{
    char* pc;
    bool fIll;
    fIll = TRUE;

    for ( pc = text; *pc != '\0'; pc++ )
    {
        if ( !isalpha( *pc ) && !isdigit( *pc ) && *pc != ' ' )
            return FALSE;

        if ( LOWER( *pc ) != 'i' && LOWER( *pc ) != 'l' )
            fIll = FALSE;
    }

    if ( fIll )
        return FALSE;

    return TRUE;
}

bool contains_space( char* text )
{
    char* pc;

    for ( pc = text; *pc != '\0'; pc++ )
    {
        if ( *pc == ' ' )
            return TRUE;
    }

    return FALSE;
}

CMDF do_timecmd( CHAR_DATA* ch, char* argument )
{
    struct timeval stime;
    struct timeval etime;
    static bool timing;
    extern CHAR_DATA* timechar;
    char arg[MIL];
    ch_println( ch, "Timing" );

    if ( timing )
        return;

    one_argument( argument, arg );

    if ( !*arg )
    {
        ch_println( ch, "No command to time." );
        return;
    }

    if ( !str_cmp( arg, "update" ) )
    {
        if ( timechar )
            ch_println( ch, "Another person is already timing updates." );
        else
        {
            timechar = ch;
            ch_println( ch, "Setting up to record next update loop." );
        }

        return;
    }

    ch_println( ch, "&zStarting timer." );
    timing = TRUE;
    gettimeofday( &stime, NULL );
    interpret( ch, argument, FALSE );
    gettimeofday( &etime, NULL );
    timing = FALSE;
    ch_println( ch, "&zTiming complete." );
    subtract_times( &etime, &stime );
    ch_println( ch, "&zTiming took &C%d.%06d &zseconds.",
               etime.tv_sec, etime.tv_usec );
    return;
}

void start_timer( struct timeval* stime )
{
    if ( !stime )
    {
        bug( "Start_timer: NULL stime.", 0 );
        return;
    }

    gettimeofday( stime, NULL );
    return;
}

time_t end_timer( struct timeval* stime )
{
    struct timeval etime;
    /* Mark etime before checking stime, so that we get a better reading.. */
    gettimeofday( &etime, NULL );

    if ( !stime || ( !stime->tv_sec && !stime->tv_usec ) )
    {
        bug( "End_timer: bad stime.", 0 );
        return 0;
    }

    subtract_times( &etime, stime );
    /* stime becomes time used */
    *stime = etime;
    return ( etime.tv_sec * 1000000 ) + etime.tv_usec;
}

void send_timer( struct timerset* vtime, CHAR_DATA* ch )
{
    struct timeval ntime;
    int carry;

    if ( vtime->num_uses == 0 )
        return;

    ntime.tv_sec  = vtime->total_time.tv_sec / vtime->num_uses;
    carry = ( vtime->total_time.tv_sec % vtime->num_uses ) * 1000000;
    ntime.tv_usec = ( vtime->total_time.tv_usec + carry ) / vtime->num_uses;
    ch_println( ch, "Has been used %d times this boot.", vtime->num_uses );
    ch_printf( ch, "Time (in secs): min %d.%0.6d; avg: %d.%0.6d; max %d.%0.6d"
               "\n", vtime->min_time.tv_sec, vtime->min_time.tv_usec, ntime.tv_sec,
               ntime.tv_usec, vtime->max_time.tv_sec, vtime->max_time.tv_usec );
    return;
}

void update_userec( struct timeval* time_used, struct timerset* userec )
{
    userec->num_uses++;

    if ( !timerisset( &userec->min_time )
            ||    timercmp( time_used, &userec->min_time, < ) )
    {
        userec->min_time.tv_sec  = time_used->tv_sec;
        userec->min_time.tv_usec = time_used->tv_usec;
    }

    if ( !timerisset( &userec->max_time )
            ||    timercmp( time_used, &userec->max_time, > ) )
    {
        userec->max_time.tv_sec  = time_used->tv_sec;
        userec->max_time.tv_usec = time_used->tv_usec;
    }

    userec->total_time.tv_sec  += time_used->tv_sec;
    userec->total_time.tv_usec += time_used->tv_usec;

    while ( userec->total_time.tv_usec >= 1000000 )
    {
        userec->total_time.tv_sec++;
        userec->total_time.tv_usec -= 1000000;
    }

    return;
}
