void cmdstack( CHAR_DATA* ch, char* buf, char* cmd, int time )
{
    DB_DATA* stack = NULL, *stack_next = NULL;
    int x = 0;

    if ( !sysdata.cmdlist )
        return;

    if ( IS_NPC( ch ) || !ch || !cmd || !time )
        return;

    if ( ch->first_cmdlist )
    {
        if ( !str_cmp( cmd, ch->first_cmdlist->str1 ) )
        {
            ch->first_cmdlist->num1++;
            ch->first_cmdlist->num2 = time;
            return;
        }
    }

    char conc[MSL];
    snprintf( conc, MSL, "%s %s", buf, cmd );
    CREATE( stack, DB_DATA, 1 );
    SET_STRING( stack->str1, conc );
    SET_STRING( stack->str2, "" );
    SET_STRING( stack->name, ch->name );
    stack->num1 = 1;
    stack->num2 = time;
    LINK_FRONT( stack, ch->first_cmdlist, ch->last_cmdlist, next, prev );

    for ( stack = ch->first_cmdlist; stack; stack = stack_next )
    {
        stack_next = stack->next;

        if ( ++x <= 20 )
            continue;

        UNLINK( stack, ch->first_cmdlist, ch->last_cmdlist, next, prev );
        extract_db( stack );
    }
}
CMDF do_lastusage( CHAR_DATA* ch, char* argument )
{
    char selectquery[MSL * 2];
    char arg[MIL], arg2[MIL];
    PGresult *qresult = NULL;
    int rows = 0;
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    int entries = 10;
    int cnt = 0;
    time_t tm;

    if ( IS_NPC( ch ) || !IS_IMMORTAL( ch ) )
        return;

    if ( NULLSTR( arg ) || !is_number( arg ) || NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &CLASTUSAGE [# of entries] <command> " );
        return;
    }

    entries = atoi( arg );
    entries = URANGE( 1, entries, 50 );

    if ( NULLSTR( argument ) )
        snprintf( selectquery, MAX_STRING_LENGTH * 2, "SELECT * FROM cmdlog where cmd LIKE '%s%%' and (trust < %d OR char=%s) order by time desc limit %d", arg2, get_trust( ch ) == 200 ? 201 : get_trust( ch ), sql_escape_string( ch->name ), entries );
    else
        snprintf( selectquery, MAX_STRING_LENGTH * 2, "SELECT * FROM cmdlog where cmd LIKE '%s%%' and args LIKE '%s%%' and (trust < %d OR char=%s) order by time desc limit %d", arg2, argument, get_trust( ch ) == 200 ? 201 : get_trust( ch ), sql_escape_string( ch->name ), entries );
    qresult = query_db( selectquery );

    debug( selectquery );
    rows = PQntuples(qresult);
    if (qresult == NULL || rows == 0)
    {
        if ( qresult ) PQclear( qresult );
        return;
    }

    for (int i = 0; i < rows; i++)
    {
        tm = ( time_t )( atoi( PQgetvalue(qresult, i, 6) ) );
        ch_println( ch, "&w%s(%2d)&G> &W%s %-20s&w\n&c<%s>", PQgetvalue(qresult, i, 1),
                   entries - cnt, PQgetvalue(qresult, i, 2), PQgetvalue(qresult, i, 3), stripclr( ( ( char* ) c_time( tm, get_timezone( ch ) ) ) ) );
        cnt++;
    }

    if ( qresult )
        PQclear( qresult );

    return;
}

CMDF do_cmdlist( CHAR_DATA* ch, char* argument )
{
    DB_DATA* stack = NULL;
    char buf[MSL];
    int x = 0, fin = 0;
    CHAR_DATA* victim = NULL;
    victim = get_player_world( argument );

    if ( !victim )
    {
        ch_println( ch, "That person isn't online right now." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) && get_trust( ch ) != 200 && ch != victim )
    {
        ch_println( ch, "Yeah right." );
        return;
    }

    if ( !victim->first_cmdlist )
    {
        ch_println( ch, "No command history available." );
        return;
    }

    for ( stack = victim->first_cmdlist; stack; stack = stack->next )
        x++;

    fin = victim->last_cmdlist->num2;

    for ( stack = victim->last_cmdlist; stack; stack = stack->prev )
    {
        if ( stack->next && stack->next->num2 != stack->num2 )
            snprintf( buf, MSL, "  &c<%d second wait>\n", stack->num2 - stack->next->num2 );
        else
            strlcpy( buf, "", MSL );

        if ( strncmp( stack->str1, "resign", 6 ) == 0 )
            SET_STRING( stack->str1, "RESIGN" );

        ch_println( ch, "&w%s&w%s(%2d)&G> &W%-20s &G[&wx%-2d&G]&w", buf,
                   stack->name, x, stack->str1, stack->num1 );
        x--;
    }

    x = victim->first_cmdlist->num2 - fin;

    if ( x > ( 60 * 60 ) )
    {
        snprintf( buf, MSL, "%d hr%s, %d min%s, %d sec%s",
                 x / 3600, x / 3600 == 1 ? "" : "s",
                 x % 3600 / 60, x % 3600 / 60 == 1 ? "" : "s",
                 x % 3600 % 60, x % 3600 % 60 == 1 ? "" : "s" );
    }
    else if ( x > 60 )
    {
        snprintf( buf, MSL, "%d min%s, %d sec%s",
                 x % 3600 / 60, x % 3600 / 60 == 1 ? "" : "s",
                 x % 3600 % 60, x % 3600 % 60 == 1 ? "" : "s" );
    }
    else
    {
        snprintf( buf, MSL, "%d sec%s",
                 x % 3600 % 60, x % 3600 % 60 == 1 ? "" : "s" );
    }

    ch_println( ch, "&GShowing activity for the last &w%s&G.", buf );
}

