int remove_from_squad( SHIP_DATA* ship )
{
    SHIP_DATA* tship = NULL, *tship_next = NULL;

    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship_extracted( ship ) )
        return E_LOTJ_INVALID_ARGUMENTS;

    // If the ship is the squad leader, disband the squad
    if ( ship->squadleader && ship->squadleader == ship )
    {
        for ( tship = ship->first_in_squad; tship; tship = tship_next )
        {
            tship_next = tship->next_in_squad;
            UNLINK( tship, ship->first_in_squad, ship->last_in_squad, next_in_squad, prev_in_squad );
            tship->squadleader = NULL;
            tship->_squadleader_uid = 0;
            tship->pos = 0;
            tship->squadassist = FALSE;
            tship->squad_aim = 0;
            save_ship( tship, TRUE );
        }

        return E_LOTJ_SUCCESS;
    }

    // Keep track of who the squadleader is
    tship = ship->squadleader;

    // Linked list management
    if ( ship->squadleader )
        UNLINK( ship, ship->squadleader->first_in_squad, ship->squadleader->last_in_squad, next_in_squad, prev_in_squad );

    // Reset the squad vars
    ship->squadleader = NULL;
    ship->_squadleader_uid = 0;
    ship->pos = 0;
    save_ship( ship, TRUE );

    // If the squad leader isn't the passed ship and its squad is now empty, dissolve the squad
    if ( tship != NULL && tship != ship && count_squadron_members( tship ) == 1 )
        remove_from_squad( tship );

    return E_LOTJ_SUCCESS;
}

int add_to_squad( SHIP_DATA* ship, SHIP_DATA* leader )
{
    if ( !ship || !leader )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship_extracted( ship ) || ship_extracted( leader ) )
        return E_LOTJ_INVALID_ARGUMENTS;

    // Make sure the squad leader is established as a member of the squad
    if ( ship != leader && !leader->squadleader )
        add_to_squad( leader, leader );

    // If the ship is already in a squad, remove it before proceeding
    if ( ship->squadleader )
        remove_from_squad( ship );

    // Set the squad vars
    ship->squadleader = leader;
    ship->_squadleader_uid = leader->id;
    ship->pos = ship == leader ? 3 : 1;
    ship->squadassist = ship == leader ? TRUE : FALSE;

    // Linked list management
    LINK( ship, leader->first_in_squad, leader->last_in_squad, next_in_squad, prev_in_squad );

    // Save the ship
    save_ship( ship, TRUE );
    return E_LOTJ_SUCCESS;
}

int remove_from_bg( SHIP_DATA* ship )
{
    SHIP_DATA* tship = NULL, *tship_next = NULL;

    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship_extracted( ship ) )
        return E_LOTJ_INVALID_ARGUMENTS;

    // If the ship is the battlegroup leader, disband the battlegroup
    if ( ship->leader && ship->leader == ship )
    {
        for ( tship = ship->first_in_bg; tship; tship = tship_next )
        {
            tship_next = tship->next_in_bg;
            UNLINK( tship, ship->first_in_bg, ship->last_in_bg, next_in_bg, prev_in_bg );
            tship->leader = NULL;
            tship->_leader_uid = 0;
            tship->pos = 0;
            save_ship( tship, TRUE );
        }

        return E_LOTJ_SUCCESS;
    }

    // Keep track of the battlegroup leader
    tship = ship->leader;

    // Linked list management
    if ( ship->leader )
        UNLINK( ship, ship->leader->first_in_bg, ship->leader->last_in_bg, next_in_bg, prev_in_bg );

    // Reset the BG vars
    ship->leader = NULL;
    ship->_leader_uid = 0;
    ship->pos = 0;
    save_ship( ship, TRUE );

    // If the BG leader isn't the passed ship and its BG is now empty, dissolve the BG
    if ( tship != NULL && tship != ship && count_battlegroup( tship ) == 1 )
        remove_from_bg( tship );

    return E_LOTJ_SUCCESS;
}

int add_to_bg( SHIP_DATA* ship, SHIP_DATA* leader )
{
    if ( !ship || !leader )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship_extracted( ship ) || ship_extracted( leader ) )
        return E_LOTJ_INVALID_ARGUMENTS;

    // Make sure the BG leader is established as a member of the BG
    if ( ship != leader && !leader->leader )
        add_to_bg( leader, leader );

    // If the ship is already in a BG, remove it
    if ( ship->leader )
        remove_from_bg( ship );

    // Set the BG vars
    ship->leader = leader;
    ship->_leader_uid = leader->id;

    // Linked list management
    LINK( ship, leader->first_in_bg, leader->last_in_bg, next_in_bg, prev_in_bg );
    save_ship( ship, TRUE );
    return E_LOTJ_SUCCESS;
}

