/*
    Counts the number of people onboard a ship. If passed a clan
    pointer, only counts members of that clan. Ignores mobs.
*/
int ship_crew_count( SHIP_DATA* ship, CLAN_DATA* clan )
{
    ROOM_INDEX_DATA* room = NULL;
    SHIP_DATA *docked_ship;
    CHAR_DATA* ch;
    int crew = 0;

    if ( !ship )
        return 0;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( !xIS_SET( room->flags, ROOM_HIDELIFESIGNS ) )
        {
            ch = room->first_person;

            while ( ch != NULL )
            {
                if ( !ch || ch == NULL )
                    break;

                /* GRAL Why dont we count NPCs? RALEN - we should. */
                if ( !IS_IMMORTAL( ch ) &&
                        ( !IS_NPC( ch ) || xIS_SET( ch->act, ACT_LIFESIGNS ) ) &&
                        !ch->spirit &&
                        !IS_AFFECTED( ch, AFF_INVISIBLE ) &&
                        !IS_AFFECTED( ch, AFF_MASKED ) &&
                        !xIS_SET( ch->race->flags, RFLAG_DROID )
                   )
                {
                    if ( clan == NULL )
                    {
                        crew++;
                    }
                    else if ( ch->pcdata != NULL )
                    {
                        if ( ch->pcdata->clan == clan )
                            crew++;
                    }
                }

                ch = ch->next_in_room;
            }

            if ( room->first_ship )
                for ( docked_ship = room->first_ship; docked_ship; docked_ship = docked_ship->next_in_room )
                    crew += ship_crew_count( docked_ship, clan );
        }

    }

    return crew;
}

