void echo_to_ship_windows_filter( int color, SHIP_DATA* ship, const char* argument, bool ( *filter )( CHAR_DATA* ) )
{
    ROOM_INDEX_DATA* room = NULL;
    TURRET_DATA* turret = NULL;

    if ( !ship || ship->occupants == 0 )
        return;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        bool echo = false;

        if ( !room->first_person )
            continue;

        if ( room->vnum == ship->cockpit || room->vnum == ship->navseat ||
                room->vnum == ship->pilotseat || room->vnum == ship->coseat ||
                room->vnum == ship->gunseat || room->vnum == ship->engineroom ||
                xIS_SET( room->flags, ROOM_VIEWPORT )
           )
            echo = true;

        for ( turret = ship->first_turret; turret; turret = turret->next )
            if ( turret->room && turret->room == room )
                echo = true;

        if ( echo )
            echo_to_room_filter( color, room, argument, filter );
    }
}

