void ai_anger( SHIP_DATA* ship, SHIP_DATA* target, bool nohelp )
{
    char buf[MSL];
    double distA = 0.0, distB = 0.0;
    SHIP_DATA* tarnext;

    if ( !ship || !target || ship_extracted( ship ) || ship_extracted( target ) )
        return;

    if ( !ship->starsystem || ship->starsystem != target->starsystem )
        return;

    // Delegate targeting choice to squadron leader if set
    if ( ship->squadleader && ship != ship->squadleader && ship->squadleader->starsystem == ship->starsystem )
    {
        ai_anger( ship->squadleader, target, nohelp );
        return;
    }

    if ( is_public( ship ) ) // why was there an is_pirate check? That made no sense whatsoeverrr
        return;

    if ( !autofly( ship ) )
        return;

    if ( xIS_SET( ship->flags, SHIP_OBJECT ) )
        return;

    if ( is_protected( ship, target, false ) )
    {
        SHIP_DATA* alt_target = nearest_unprotected_group_ship( ship->vpos, ship, target, false );

        if ( alt_target )
            ai_anger( ship, alt_target, nohelp );

        return;
    }

    ship_start_fighting( ship, target );

    /*
        Range check
    */
    if ( vector_distance( &ship->vpos, &target->vpos ) > ( ( ship->classtype + 1 ) * 2500 ) )
        return;

    /*
        Call for help?
    */
    if ( xIS_SET( ship->aflags, AFLAG_RADIO ) && !nohelp )
    {
        SHIP_DATA* guard;

        for ( guard = ship->starsystem->first_ship; guard; guard = tarnext )
        {
            tarnext = guard->next_in_starsystem;

            if ( guard == ship )
                continue;

            if ( !ship_has_weapons( guard ) )
                continue;

            if ( guard->shipstate != SHIP_READY && guard->shipstate != SHIP_BUSY )
                continue;

            // Ralen - LONG-standing bug here: aconfig +radio doesn't check who the owners of any other ship in the system is.
            if ( NULLSTR( ship->shipowner ) || str_cmp( guard->shipowner, ship->shipowner ) )
                continue;

            // Exempt ships in a squadron or bg where their leader is local and *not* on autopilot.
            if ( guard->leader &&
                    guard->leader->starsystem == ship->starsystem &&
                    !autofly( guard->leader ) )
                continue;

            ai_anger( guard, target, TRUE );
        }
    }

    if ( ship->target0 != NULL && !is_pirate( ship ) )
    {
        /*
            --- Intelligent Target Selection ---
            Action:
            Only switch targets if the new target
            is a smaller class then the current one.
            Reason:
            Smaller ships are easier to destroy overall.
            If you waste time trying to destroy the
            large ship, all You're doing is giving the smaller
            ship more time to attack you with its weapons.
        */
        distA = vector_distance( &ship->vpos, &ship->target0->vpos );
        distB = vector_distance( &ship->vpos, &target->vpos );

        if ( target->classtype == ship->target0->classtype )
        {
            if ( distA <= distB )
                return;
        }

        if ( target->classtype >= ship->target0->classtype && distB >= distA - 750 )
            return;

        if ( xIS_SET( target->flags, SHIP_TRAFFIC ) )
            return;

        snprintf( buf, MSL, "%s has broken its target lock!", ship->name );
        echo_to_ship_windows( AT_BLOOD, ship->target0, buf );
    }

    if ( ship->target0 != NULL && is_pirate( ship ) )
    {
        /*
            Pirates aren't that smart. This is a copy of the above code.
        */
        distA = vector_distance( &ship->vpos, &ship->target0->vpos );
        distB = vector_distance( &ship->vpos, &target->vpos );

        if ( target->classtype == ship->target0->classtype )
        {
            if ( distA >= distB )
                return;
        }

        if ( target->classtype < ship->target0->classtype && distB <= distA - 750 )
        {
            return;
        }

        if ( xIS_SET( target->flags, SHIP_TRAFFIC ) )
            return;

        snprintf( buf, MSL, "%s has broken its target lock!", ship->name );
        echo_to_ship_windows( AT_BLOOD, ship->target0, buf );
    }

    snprintf( buf, MSL, "You are being targeted by %s.", ship->name );
    echo_to_ship_windows( AT_BLOOD, target, buf  );
    ship->target0 = target;

    // When a squadron leader autotargets, its members should do the same.
    if ( is_squadleader( ship ) && ship->squadassist )
    {
        for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
        {
            if ( sq->starsystem != ship->starsystem )
                continue;

            if ( !should_follow_squadleader( sq, ship ) )
                continue;

            if ( sq->target0 == target )
                continue;

            if ( sq->target0 )
            {
                snprintf( buf, MSL, "%s has broken its target lock!", sq->name );
                echo_to_ship_windows( AT_BLOOD, sq->target0, buf );
            }

            snprintf( buf, MSL, "You are being targeted by %s.", sq->name );
            echo_to_ship_windows( AT_BLOOD, target, buf  );
            sq->target0 = target;
        }
    }

    return;
}

void finish_maneuver( SHIP_DATA* ship )
{
    char buf[MSL];

    switch ( ship->shipstate )
    {
        case SHIP_BUSY:
            echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Maneuver complete." );
            ship->shipstate = SHIP_READY;
            break;

        case SHIP_LAND:
            if ( ship->dest )
            {
                landship( ship, ship->dest, 0 );
                SET_STRING( ship->dest, NULL );
            }
            else
            {
                /*
                    Failed landing sequence
                */
                bug( "finish_maneuver: Could not complete ship landing sequence." );
                ship->shipstate = SHIP_READY;

                if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
                {
                    resetship( ship );
                }
            }

            break;

        case SHIP_LAUNCH:
            launchship( ship );
            break;

        case SHIP_LAUNCH_ABORT:
            ship->location = ship->lastdoc;
            echo_to_ship_windows( AT_YELLOW, ship, "The ship settles back down on the landing area." );
            snprintf( buf, MSL, "&z&W&Y%s settles back down onto the landing area.", ship->name );
            ship_action( ship, buf );
            ship->shipstate = SHIP_DOCKED;
            break;

        case SHIP_LAND_ABORT:
            echo_to_ship_windows( AT_YELLOW, ship, "Maneuver complete.\n" );
            ship->shipstate = SHIP_READY;
            break;

        case SHIP_HOVERLAUNCH:
            echo_to_ship_main( AT_YELLOW, ship, "The ship drives hum as the craft stabilizes." );
            ship->shipstate = SHIP_HOVER;
            break;

        case SHIP_HOVERLAND:
            echo_to_ship_main( AT_YELLOW, ship, "The ship settles back down on the ground." );
            snprintf( buf, MSL, "&Y%s settles back down on the ground.\n", ship->name );
            ship_action( ship, buf );
            ship->shipstate = SHIP_DOCKED;
            break;
    }

    // Ships should save whenever they change state in a significant way.
    save_ship( ship, true );
}

void update_squadron_move( SHIP_DATA* ship )
{
    if ( !ship || !ship->squadleader )
        return;

    SHIP_DATA* squadleader = ship->squadleader;
    char buf[MIL];

    if ( ship->shipstate != SHIP_READY )
        return;

    if ( squadleader->starsystem != ship->starsystem )
    {
        if ( ship->currspeed > 0 )
        {
            snprintf( buf, MIL, "%s comes to a halt.", ship->name );

            if ( ship->cloakstatus != CLOAK_ON )
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );

            ship->currspeed = 0;
        }

        return;
    }

    int leader_dist = vector_distance( &ship->vpos, &squadleader->vpos );

    if ( !is_facing( ship, squadleader ) && leader_dist > 1 )
    {
        snprintf( buf, MIL, "%s turns, altering its present course.", ship->name );

        if ( ship->cloakstatus != CLOAK_ON )
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
    }

    // We do this even if the ship is considered facing the leader to avoid spammy
    // turning messages when course is corrected multiple times.
    ship_set_course( ship, &squadleader->vpos );
    int target_speed = ship->currspeed;

    if ( leader_dist > 50 )
        target_speed = ship->realspeed;
    else if ( leader_dist > 30 )
        target_speed = squadleader->currspeed + 30;
    else if ( leader_dist > 10 )
        target_speed = squadleader->currspeed + 10;
    else
        target_speed = squadleader->currspeed;

    target_speed = URANGE( 0, target_speed, ship->realspeed );

    if ( target_speed != ship->currspeed )
    {
        if ( target_speed == 0 )
            snprintf( buf, MIL, "%s comes to a halt.", ship->name );
        else if ( target_speed > ship->currspeed )
            snprintf( buf, MIL, "%s begins to speed up.", ship->name );
        else if ( target_speed < ship->currspeed )
            snprintf( buf, MIL, "%s begins to slow down.", ship->name );

        if ( ship->cloakstatus != CLOAK_ON )
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );

        ship->currspeed = target_speed;
    }

    // Squadron members recharge 1/6 their shields every 2 seconds if the leader is piloted or has fastrecharge.
    if ( ( squadleader->piloting ||
            ( autofly( squadleader ) && xIS_SET( squadleader->flags, SHIP_AUTO_FASTRECHARGE ) )
         ) && ship->shield < ship->maxshield )
    {
        int recharge = UMIN( ship->maxshield - ship->shield, ship->maxshield / 6 );
        ship->energy -= recharge;
        ship->shield += recharge;

        if ( ship->shield < ship->maxshield )
        {
            // This one gets spammy, so randomize it
            if ( number_range( 1, 4 ) == 1 )
                message_to_squadleader( ship, "Boosting shields." );
        }
        else
        {
            message_to_squadleader( ship, "Shields fully charged." );
        }
    }

    // Special logic for automated squadrons to perform more effectively in combat
    if ( ship->starsystem &&
            xIS_SET( ship->squadleader->flags, SHIP_AUTO_SQUADRON ) &&
            autofly( ship->squadleader )
       )
    {
        // Simulate missile evasion, either by rolling or chaffing.
        if ( ship->chaff_time == 0 )
        {
            int incoming_count = 0;

            for ( MISSILE_DATA* missile = ship->starsystem->first_missile; missile; missile = missile->next_in_starsystem )
            {
                if ( missile->target == ship && vector_distance( &missile->pos, &ship->vpos ) < 300 )
                    incoming_count++;
            }

            // Players might roll to try to lose missiles, and this will also result in target loss.
            // To simulate that, sometimes roll, and sometimes just chaff.
            if ( incoming_count > 0 )
            {
                if ( number_range( 1, 3 ) != 1 )
                {
                    roll_ship( ship, 100 );
                }
                else
                {
                    ship->chaff--;
                    ship->chaff_time = 20;
                }
            }
        }
    }
}

void move_ships( void )
{
    CHAR_DATA* rch = NULL;
    SHIP_DATA* ship = NULL, *snext = NULL, *target = NULL;
    MINE_DATA* mine = NULL, *n_next = NULL;
    TRACTOR_DATA* tractor = NULL, *t_next = NULL;
    MISSILE_DATA* missile = NULL, *m_next = NULL;
    FCARGO_DATA* fcargo = NULL, *f_next = NULL;
    PLANET_DATA* planet = NULL;
    ROOM_INDEX_DATA* room = NULL;
    int range = 0;
    char buf[MSL];

    // Declare the array of pointers to copy the linked list into
    SHIP_DATA** all_ships = NULL;

    // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
    LINK_TO_ARRAY( first_ship, SHIP_DATA, next, all_ships );

    /*
        Space Mines! Coded by Ghost

        If i wrote these right, the following should apply:
        - Mines require 20 seconds to arm before doing anything
        - Mines will *NOT* hit the ship that launched it, nor any ship from the same clan.
        - Mines will last about 1 days in RL. This will be raised to 1 week later.
        - Mines DO show up on the radar/proximity readouts
    */
    for ( mine = first_mine; mine; mine = n_next )
    {
        n_next = mine->next;
        ship = mine->fired_from;
        target = mine->target;
        mine->age++;

        if ( mine->age > 21600 ) /* 1 Days in RL */
        {
            echo_to_system_noqueue_noship( AT_ORANGE, mine->starsystem, "A mine expires in a massive ball of fire!" );
            extract_mine( mine );
            continue;
        }

        if ( mine->age < 5 ) /* Mines require 20 seconds to arm */
            continue;

        if ( target )
        {
            if ( !target->starsystem )
            {
                mine->target = NULL;
                continue;
            }

            if ( target->starsystem != mine->starsystem )
            {
                mine->target = NULL;
                continue;
            }

            if ( mine->speed < mine->maxspeed )
                mine->speed = URANGE( 0, mine->speed + 5, mine->maxspeed );

            if ( mine->pos.x < ( int )target->vpos.x )
                mine->pos.x += UMIN( mine->speed / 5, ( int )target->vpos.x - mine->pos.x );

            if ( mine->pos.x > ( int )target->vpos.x )
                mine->pos.x -= UMIN( mine->speed / 5, mine->pos.x - ( int )target->vpos.x );

            if ( mine->pos.y < ( int )target->vpos.y )
                mine->pos.y += UMIN( mine->speed / 5, ( int )target->vpos.y - mine->pos.y );

            if ( mine->pos.y > ( int )target->vpos.y )
                mine->pos.y -= UMIN( mine->speed / 5, mine->pos.y - ( int )target->vpos.y );

            if ( mine->pos.z < ( int )target->vpos.z )
                mine->pos.z += UMIN( mine->speed / 5, ( int )target->vpos.z - mine->pos.z );

            if ( mine->pos.z > ( int )target->vpos.z )
                mine->pos.z -= UMIN( mine->speed / 5, mine->pos.z - ( int )target->vpos.z );

            range = ( mine->minetype == PROXIMITY_MINE ) ? 150 : 40;

            if ( fabs( mine->pos.x - ( int )target->vpos.x ) <= range && fabs( mine->pos.y - ( int )target->vpos.y ) <= range
                    && fabs( mine->pos.z - ( int )target->vpos.z ) <= range )
            {
                /*
                    Too Close! Explosion Time!
                */
                if ( target->chaff_time <= 0 || mine->minetype != MAGNETIC_MINE )
                {
                    echo_to_ship_windows( AT_BLOOD, target, "The ship has been hit by a mine!" );
                    echo_to_ship_main( AT_RED, target, "A loud explosion shakes the ship violently!" );
                    damage_ship( target, mine_damage[mine->minetype], mine_damage[mine->minetype] * 2, NULL, NULL );
                    snprintf( buf, MSL, "You see a small explosion as %s is hit by a mine!", target->name );
                    echo_to_system_noqueue( AT_ORANGE, target, buf, target );
                    extract_mine( mine );
                }
                else
                {
                    echo_to_ship_windows( AT_YELLOW, target, "A mine explodes in your chaff!" );
                    echo_to_ship_main( AT_RED, target, "A loud explosion shakes the ship violently!" );
                    damage_ship( target, mine_damage[mine->minetype] / 5, mine_damage[mine->minetype], NULL, NULL );
                    snprintf( buf, MSL, "You see a small explosion a mine explodes in %s's chaff!", target->name );
                    echo_to_system_noqueue( AT_ORANGE, target, buf, target );
                    extract_mine( mine );
                }

                continue;
            }
        }

        for ( ship = mine->starsystem->first_ship; ship; ship = snext )
        {
            snext = ship->next_in_starsystem;

            if ( is_pirate( ship ) )
                continue;

            if ( mine->minetype == MAGNETIC_MINE || mine->minetype == SEEKER_MINE )
            {
                if ( ship == mine->fired_from || !str_cmp( ship->shipowner, mine->fired_clan ) )
                {
                }
                else if ( !mine->target || mine->target == NULL )
                {
                    range = ( mine->minetype == SEEKER_MINE ) ? 500 : 200;

                    if ( vector_distance( &ship->vpos, &mine->pos ) <= range )
                    {
                        mine->target = ship;

                        if ( mine->maxspeed < 5 )
                            mine->maxspeed = 50;

                        mine->speed = mine->maxspeed / 5;
                    }
                }
            }

            range = ( mine->minetype == PROXIMITY_MINE ) ? 60 : 20;

            if ( vector_distance( &ship->vpos, &mine->pos ) <= range )
            {
                /*
                    Too Close! Explosion Time!
                */
                if ( ship != mine->fired_from && str_cmp( ship->shipowner, mine->fired_clan ) )
                {
                    echo_to_ship_windows( AT_BLOOD, ship, "The ship has been hit by a mine!" );
                    echo_to_ship_main( AT_RED, ship, "A loud explosion shakes the ship violently!" );
                    damage_ship( ship, mine_damage[mine->minetype], mine_damage[mine->minetype] * 2, NULL, NULL );
                    snprintf( buf, MSL, "You see a small explosion as %s is hit by a mine!", ship->name );
                    echo_to_system_noqueue( AT_ORANGE, ship, buf, ship );
                    /*
                        blast_radius_space( NULL, mine->starsystem, NULL, mine->mx, mine->my, mine->mz, mine_damage[mine->minetype], mine_radius[mine->minetype] );
                    */
                    extract_mine( mine );
                }
            }
        }
    }

    for ( missile = first_missile; missile; missile = m_next )
    {
        m_next = missile->next;
        ship = missile->fired_from;
        target = missile->target;

        if ( target->starsystem && target->starsystem == missile->starsystem )
        {
            if ( missile->pos.x < target->vpos.x )
                missile->pos.x += UMIN( missile->speed / 5, ( int )target->vpos.x - missile->pos.x );
            else if ( missile->pos.x > target->vpos.x )
                missile->pos.x -= UMIN( missile->speed / 5, missile->pos.x - ( int )target->vpos.x );

            if ( missile->pos.y < target->vpos.y )
                missile->pos.y += UMIN( missile->speed / 5, ( int )target->vpos.y - missile->pos.y );
            else if ( missile->pos.y > target->vpos.y )
                missile->pos.y -= UMIN( missile->speed / 5, missile->pos.y - ( int )target->vpos.y );

            if ( missile->pos.z < target->vpos.z )
                missile->pos.z += UMIN( missile->speed / 5, ( int )target->vpos.z - missile->pos.z );
            else if ( missile->pos.z > target->vpos.z )
                missile->pos.z -= UMIN( missile->speed / 5, missile->pos.z - ( int )target->vpos.z );

            if ( vector_distance( &missile->pos, &target->vpos ) <= 20 )
            {
                /*
                    AUTOPILOT AI Module --- USECHAFF Setting
                */
                if ( autofly( target ) && xIS_SET( target->aflags, AFLAG_USECHAFF ) && target->chaff_time == 0 )
                {
                    if ( target->chaff > 0 )
                    {
                        target->chaff--;
                        target->chaff_time = 20;
                    }
                }

                bool missile_chaffed = false;

                if ( target->chaff_time > 0 )
                {
                    // Chaff effectiveness is:
                    // 100% for fighters
                    // 95% for transports
                    // ...
                    // 75% for frigates
                    // 70% for cruisers
                    int chaff_chance = 100 - target->classtype * 5;

                    if ( number_percent() <= chaff_chance )
                        missile_chaffed = true;
                }

                if ( missile_chaffed )
                {
                    if ( missile->missiletype == PROTON_TORPEDO )
                        add_queue( target, SQUEUE_TORPEDO_CHAFF, 0, 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == HEAVY_ROCKET )
                        add_queue( target, SQUEUE_ROCKET_CHAFF, 0, 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == MAGNETIC_PULSE )
                        add_queue( target, SQUEUE_PULSE_CHAFF, 0, 0, missile->fired_by, missile->fired_from );
                    else    /* Use the missile then */
                        add_queue( target, SQUEUE_MISSILE_CHAFF, 0, 0, missile->fired_by, missile->fired_from );

                    extract_missile( missile );
                }
                else if ( xIS_SET( target->flags, SHIP_VONG ) && target->shipstate != SHIP_DISABLED && target->shipstate != SHIP_PERM_DISABLED && number_percent() < 75 )
                {
                    if ( missile->missiletype == PROTON_TORPEDO )
                        add_queue( target, SQUEUE_VONG_NULLIFY_TORPEDO, 0, 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == HEAVY_ROCKET )
                        add_queue( target, SQUEUE_VONG_NULLIFY_ROCKET, 0, 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == MAGNETIC_PULSE )
                        add_queue( target, SQUEUE_VONG_NULLIFY_PULSE, 0, 0, missile->fired_by, missile->fired_from );
                    else    /* Use the missile then */
                        add_queue( target, SQUEUE_VONG_NULLIFY_MISSILE, 0, 0, missile->fired_by, missile->fired_from );

                    extract_missile( missile );
                }
                else
                {
                    if ( missile->missiletype == PROTON_TORPEDO )
                        add_queue( target, SQUEUE_TORPEDO_HIT, number_range( 40, 60 ), 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == HEAVY_ROCKET )
                        add_queue( target, SQUEUE_ROCKET_HIT, number_range( 100, 150 ), 0, missile->fired_by, missile->fired_from );
                    else if ( missile->missiletype == MAGNETIC_PULSE )
                        // Note: Ion damage, so double this if it's hitting shielding.
                        add_queue( target, SQUEUE_PULSE_HIT, 0, number_range( 40, 60 ), missile->fired_by, missile->fired_from );
                    else    /* Use the missile then */
                        add_queue( target, SQUEUE_MISSILE_HIT, number_range( 20, 30 ), 0, missile->fired_by, missile->fired_from );

                    extract_missile( missile );
                }

                continue;
            }
            else
            {
                missile->age++;

                if ( missile->age >= 50 )
                {
                    extract_missile( missile );
                    continue;
                }

                if ( missile->target->cloakstatus == CLOAK_ON )
                {
                    extract_missile( missile );
                    continue;
                }
            }
        }
        else
        {
            extract_missile( missile );
            continue;
        }
    }

    /*
        Process the attack queue
    */
    process_queue(  );
    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( ship->maneuver_timer > 0 )
        {
            ship->maneuver_timer--;

            if ( ship->maneuver_timer == 0 )
                finish_maneuver( ship );
        }

        if ( ship->roll_timer > 0 )
            ship->roll_timer--;
    }

    //targeting update mod - Rojan
    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( ship->target0 && is_protected( ship, ship->target0, false ) )
            ship->target0 = NULL;

        if ( ship->target0 == NULL )
            continue;

        if ( vector_distance( &ship->vpos, &ship->target0->vpos ) > ( ( ship->classtype + 1 ) * 2500 ) )
        {
            ship->target0 = NULL;
            echo_to_ship_windows( AT_RED, ship, "You have lost your targeting lock." );
        }
    }

    /*
        Updated Tractorbeam System! Coded by Ghost
    */
    for ( tractor = first_tractor; tractor; tractor = t_next )
    {
        t_next = tractor->next;
        ship = tractor->owner;
        target = tractor->target;

        // This ship is no longer in space. Cancel tractor.
        if ( !ship || !target || !ship->starsystem || !target->starsystem )
        {
            extract_tractor( tractor );
            continue;
        }

        if ( ++tractor->age >= 60 || ship->tractorstate >= TRACTOR_DAMAGED ) /* 1 Minute in RL */
        {
            debug( "extracting tractor beam for %s because it is old", tractor->target->name );
            extract_tractor( tractor );
            continue;
        }

        /*
            Tow 'em in
        */
        /*
            tractor->distance -= (power*5);
        */
        if ( target->vpos.x < ship->vpos.x )
            target->vpos.x += UMIN( 10.0, ship->vpos.x - target->vpos.x );
        else if ( target->vpos.x > ship->vpos.x )
            target->vpos.x -= UMIN( 10.0, target->vpos.x - ship->vpos.x );

        if ( target->vpos.y < ship->vpos.y )
            target->vpos.y += UMIN( 10.0, ship->vpos.y - target->vpos.y );
        else if ( target->vpos.y > ship->vpos.y )
            target->vpos.y -= UMIN( 10.0, target->vpos.y - ship->vpos.y );

        if ( target->vpos.z < ship->vpos.z )
            target->vpos.z += UMIN( 10.0, ship->vpos.z - target->vpos.z );
        else if ( target->vpos.z > ship->vpos.z )
            target->vpos.z -= UMIN( 10.0, target->vpos.z - ship->vpos.z );

        /*
            Recalculate the distance
        */
        tractor->distance = vector_distance( &ship->vpos, &target->vpos );
        /*
            Slow the victim
        */
        target->currspeed = URANGE( 0, target->currspeed - 75, target->realspeed );

        if ( tractor->hangar == NULL )
        {
            bug( "%s: NULL hangar for tractor beam system.", FUNC );
            extract_tractor( tractor );
            continue;
        }

        if ( tractor->distance <= 0 && tractor->hangar != NULL && get_hangar_free( tractor->hangar ) >= get_ship_size( target ) )
        {
            /*
                Autopilot AI - NOCAPTURE Check
            */
            if ( xIS_SET( target->aflags, AFLAG_NOCAPTURE ) && autofly( target ) )
            {
                if ( !target->selfd_armed )
                {
                    target->selfd_time = 60;    /* Activate self destruct */
                    target->selfd_armed = TRUE;
                    echo_to_ship_windows( AT_YELLOW, target, "WARNING: SELF-DESTRUCT ENGAGED: EVACUATE THE SHIP!" );
                    echo_to_shipNC( AT_RED, target, "Warning sirens begin to screech through the hallways..." );
                }
            }

            /*
                Escape Pod Failsafe - Autodestruct on Capture
            */
            if ( xIS_SET( target->flags, SHIP_ESCAPEPOD ) )
            {
                if ( !target->selfd_armed )
                {
                    target->selfd_time = 300;   /* Activate self destruct */
                    target->selfd_armed = TRUE;
                    echo_to_ship_windows( AT_YELLOW, target, "WARNING: SELF-DESTRUCT ENGAGED: EVACUATE THE SHIP!" );
                    echo_to_shipNC( AT_RED, target, "Warning sirens begin to screech through the hallways..." );
                }
            }

            /*
                landship( target, ship->name, tractor->hangar->id );
            */

            if ( !ship_to_room( target, tractor->hangar->room->vnum ) )
            {
                echo_to_room( AT_YELLOW, get_room_index( target->pilotseat ),
                              "Could not complete approach. Landing aborted." );
                echo_to_ship_main( AT_YELLOW, target, "The ship pulls back up out of its landing sequence." );

                if ( target->shipstate != SHIP_DISABLED && target->shipstate != SHIP_PERM_DISABLED )
                    target->shipstate = SHIP_READY;

                continue;
            }

            echo_to_ship_main( AT_YELLOW, target, "You feel a slight thud as the ship is tractored to a landing." );
            snprintf( buf, MSL, "%s is pulled into a hangar on %s, disappearing from your scanner.", target->name, ship->name );
            echo_to_system_noqueue( AT_YELLOW, target, buf, NULL );
            /* Gral double check this against the tractor halt bug */
            target->location = tractor->hangar->room->vnum;
            target->lastdoc = target->location;

            if ( target->shipstate != SHIP_DISABLED && target->shipstate != SHIP_PERM_DISABLED )
                target->shipstate = SHIP_COOLDOWN;

            ship_from_starsystem( target );
            snprintf( buf, MSL, "%s lands on the platform.", target->name );
            echo_to_room( AT_YELLOW, get_room_index( target->location ), buf );
            target->tankpurge = FALSE;
            check_repair_public( target, TRUE );
            save_ship( target, true );
            save_ship( ship, true );

            if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
            {
                for ( room = target->first_room; room; room = room->next_in_range )
                {
                    rch = room->first_person;

                    while ( rch != NULL )
                    {
                        char_from_room( rch );
                        char_to_room( rch, tractor->hangar->room );
                        ch_println( rch, "&RAs you come to a halt, your %s and you start to see stars...", xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) ? "skin begins to thaw" : "oxygen tank depletes" );
                        act( AT_MAGIC, "$n flops to the surface as the tractor beam releases them.", rch, NULL, NULL, TO_ROOM );
                        do_look( rch, "auto" );

                        if ( !IS_IMMORTAL( rch ) )
                            rch->hit = number_range( -200, -100 );

                        save_char_obj( rch, TRUE );
                        WAIT_STATE( rch, 6 );
                        rch = room->first_person;
                    }
                }

                target->location = 7;
                target->lastdoc = target->location;
                target->selfd_time = 1;   /* Activate self destruct */
                target->selfd_armed = TRUE;
                save_ship( target, true );
            }

            extract_tractor( tractor );
        }
    }

    for ( fcargo = first_fcargo; fcargo; fcargo = f_next )
    {
        f_next = fcargo->next;
        ship = fcargo->fired_from;
        fcargo->age--;

        if ( fcargo->age <= 0 )
        {
            extract_fcargo( fcargo );
            continue;
        }
    }

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        planet = NULL;

        // Sometimes a ship's pilot ends up invalid or not in the ship. This cleans that up.
        if ( ship->piloting && ( !ship->piloting->in_room || get_ship_from_room( ship->piloting->in_room ) != ship  ) )
            ship->piloting = NULL;

        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            if ( ship->hyper_exit_countdown > 0 )
            {
                ship->hyper_exit_countdown--;
                if ( ship->hyper_exit_countdown == 0 )
                    exit_hyperspace( ship );
                continue;
            }

            float parsecs_per_tick = ship_parsecs_per_second( ship ) * 2;
            float parsecs_remaining = hyper_distance(ship->hyper_currentpos, ship->hyper_exit);
            float parsecs_traveled = UMIN( parsecs_per_tick, parsecs_remaining );

            // Move the ship. Compute vector ratios (values between -1 and 1 which represent the
            // ratio of travel between the x/y/z diffs, where summing up all three equals 1) and
            // move us along based on that * the distance we travel in one tick.
            Vector3 hyper_vector_ratios = {
                .x = ship->hyper_exit.x - ship->hyper_currentpos.x,
                .y = ship->hyper_exit.y - ship->hyper_currentpos.y,
                .z = ship->hyper_exit.z - ship->hyper_currentpos.z,
            };
            vector_normalize(&hyper_vector_ratios);
            ship->hyper_currentpos.x += parsecs_traveled * 100000 * hyper_vector_ratios.x;
            ship->hyper_currentpos.y += parsecs_traveled * 100000 * hyper_vector_ratios.y;
            ship->hyper_currentpos.z += parsecs_traveled * 100000 * hyper_vector_ratios.z;
            parsecs_remaining -= parsecs_traveled;;

            // Handle the last tick where they're not travelling a full 2 seconds worth of distance
            int fuel_burn = ship_hyperjump_fuel_per_second(ship) * 2 * (parsecs_traveled / parsecs_per_tick);
            ship->energy -= fuel_burn;
            if ( ship->energy <= 0 )
            {
                echo_to_ship_windows( AT_RED, ship, "[ALERT]: Fuel reserves depleted. Exiting Hyperspace." );
                ship->energy = 0;
                exit_hyperspace( ship );
                continue;
            }

            if ( parsecs_remaining == 0 )
            {
                echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Destination reached. Initiating realspace reentry..." );
                ship->hyper_currentpos = ship->hyper_exit;
                ship->hyper_exit_countdown = 3;
            }
            else
            {
                // Print status every on each 20 second interval to match legacy behavior
                int remaining_seconds = (int) ceil(ship_hyperjump_seconds(ship, parsecs_remaining) / 2) * 2;
                if ( remaining_seconds % 20 == 0 )
                {
                    snprintf( buf, MSL, "Remaining jump distance: &W%.1f parsecs", parsecs_remaining );
                    echo_to_ship_windows( AT_YELLOW, ship, buf );
                    snprintf( buf, MSL, "Remaining jump time:     &W%s", jumptime( ship, parsecs_remaining ) );
                    echo_to_ship_windows( AT_YELLOW, ship, buf );
                }
            }

            firehose_write_ship( ship );
        }

        if ( !ship->starsystem )
            continue;

        // Try to keep squadron ships aligned with their leaders.
        if ( ship->squadleader && !ship->piloting && ship->squadleader != ship )
            update_squadron_move( ship );

        ship_move( ship );

        if ( ship_extracted( ship ) )
            continue;

        if ( autofly( ship ) && !xIS_SET( ship->flags, SHIP_TRAFFIC ) )
            continue;

        /*
            New collision checks by Ghost
            - STARS are nolonger starsystem variables,
            - but planets with the STAR Flag!
        */
        for ( planet = first_planet; planet; planet = planet->next )
        {
            if (!ship || !planet)  // look, I don't know how this can happen but it seems to? ~Miros   
                continue;

            if ( !ship->starsystem || !planet->starsystem )
                continue;

            if ( ship->starsystem != planet->starsystem )
                continue;

            if ( xIS_SET( planet->flags, PLANET_STAR ) )
            {
                if ( vector_distance( &ship->vpos, &planet->pos ) <= 30 )
                {
                    echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "You fly directly into a star!" );
                    snprintf( buf, MSL, "%s flies directly into %s!", ship->name, planet->name );
                    echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                    destroy_ship( ship, NULL, NULL, "Sunning!" );
                    break;
                }
            }
            else
            {
                if ( ship->currspeed > 0 )
                {
                    // Enter orbit when we're within half a tick's travel (or 10, whatever's a bigger range) from this planet
                    // (and add 0.1 to the speed-based range for double math fuzziness)
                    if ( vector_distance( &ship->vpos, &planet->pos ) > UMAX( ( double )ship->currspeed / 10 + 0.1, 10 ) )
                        continue;

                    if ( xIS_SET( ship->flags, SHIP_ESCAPEPOD ) && get_random_eject_room( planet, ship ) != NULL )
                    {
                        deploy_pod( ship, planet );
                        ship = NULL;
                        break;
                    }

                    if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
                        break;

                    snprintf( buf, MSL, "You begin orbiting %s.", planet->name );
                    echo_to_ship_windows( AT_YELLOW, ship, buf );

                    if ( ship->cloakstatus != CLOAK_ON )
                    {
                        snprintf( buf, MSL, "%s begins orbiting %s.", ship->name, planet->name );
                        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                    }

                    if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) && ship->trafficstate == TRAFFIC_MOVING_ARRIVED )
                    {
                        ship->trafficstate = TRAFFIC_ORBIT_ARRIVED;
                    }

                    vector_copy( &ship->vpos, &planet->pos );
                    ship->currspeed = 0;
                    break;
                }
            }
        }

        if(!ship)
            continue;
    }

    for ( PLANET_DATA* planet = first_planet; planet; planet = planet->next )
    {
        if ( xIS_SET( planet->flags, PLANET_BLOCKADE ) )
        {
            if ( blockade_effective_dist( planet ) == -1 )
            {
                bug ( "%s abandoned blockade on %s.", planet->blockaded_by ? planet->blockaded_by->name : "(UNKNOWN)", planet->name );
                xREMOVE_BIT( planet->flags, PLANET_BLOCKADE );
                xSET_BIT( planet->flags, PLANET_UNBLOCKADED );
                snprintf( buf, MSL, "&R[PLANET BLOCKADE] &c%s is no longer under blockade.\n", planet->name );

                for ( DESCRIPTOR_DATA* d = first_descriptor ; d ; d = d->next )
                {
                    if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                        continue;

                    if ( IS_CLANNED( d->character ) && d->character->pcdata->clan == planet->blockaded_by )
                        send_to_char( buf, d->character );
                }

                snprintf( buf, MSL, "%s is no longer under blockade.", planet->name );

                if ( planet->starsystem )
                {
                    for ( ship = planet->starsystem->first_ship; ship; ship = ship->next_in_starsystem )
                        echo_to_ship_windows( AT_RED, ship, buf );
                }
            }
        }
    }
    gravwell_check();
    DISPOSE( all_ships );
    return;
}

void save_all_ships( bool queue )
{
    SHIP_DATA* ship;

    for ( ship = first_ship; ship; ship = ship->next )
        if ( ship && ship != NULL )
            save_ship( ship, queue );

    return;
}

double standard_ship_hit_chance( CHAR_DATA* ch )
{
    if ( !ch )
        return 1;

    if ( IS_NPC( ch ) )
        return ch->top_level / 100.0;

    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );
    cache_skill( "precision", &skill_precision );

    // A minimum of 22.5%, maximum of 95% with all three skills and precision
    double pct_chance = 22.5;
    pct_chance += get_curr_dex( ch ) / 2.0;
    pct_chance += get_learned_pct( ch, skill_space_combat_1 ) / 6.0;
    pct_chance += get_learned_pct( ch, skill_space_combat_2 ) / 6.0;
    pct_chance += get_learned_pct( ch, skill_space_combat_3 ) / 6.0;
    pct_chance += has_feat( ch, skill_precision ) ? 10 : 0;
    return pct_chance / 100;
}

// Returns true if an attempt was made, false if the weapon was unable to be fired right now
bool fire_ship_laser( SHIP_DATA* ship, CHAR_DATA* ch, SHIP_DATA* target )
{
    debug( "fire_ship_laser: attempting to fire from %s to %s", ship->name, target->name );
    double dist = vector_distance( &ship->vpos, &target->vpos );
    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );

    if ( dist > 1000 )
    {
        if ( ch )
            ch_println( ch, "&RYour target is outside of laser range!" );

        return false;
    }

    // Only enforce direction if this is manual fire from a frigate or smaller
    if ( ch && ship->classtype < CORVETTE_SHIP && !is_facing( ship, target ) )
    {
        ch_println( ch, "&RThe main laser can only fire forwards. You'll need to turn your ship!" );
        return false;
    }

    if ( target->safe_orbital )
    {
        if ( ch )
            ch_println( ch, "&RThat target may not currently be attacked per HELP CAPITAL RULES." );

        return false;
    }

    if ( is_squadleader( ship ) && ship->squadassist && ( ch || xIS_SET( ship->flags, SHIP_AUTO_SQUADRON ) ) )
    {
        for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
        {
            if ( sq->starsystem != ship->starsystem )
                continue;

            if ( !should_follow_squadleader( sq, ship ) || sq->target0 != target )
                continue;

            fire_ship_laser( sq, NULL, target );
        }
    }

    if ( ship->laser_charge <= LASER_DAMAGED )
    {
        if ( ch )
            ch_println( ch, "&RThe ship's laser cannon(s) are %s.", ship->laser_charge == LASER_DESTROYED ? "destroyed" : "damaged" );

        return false;
    }

    if ( ship->laser_charge >= ship->lasers )
    {
        if ( ch )
            ch_println( ch, "&RThe laser cannons are still recharging." );

        return false;
    }

    int energy_cost = valid_focus( ch, PILOTING_ABILITY ) ? 3 : 5;

    if ( ship->energy < energy_cost )
    {
        if ( ch )
            ch_println( ch, "&RThere's not enough energy to fire the lasers!" );

        return false;
    }

    ship_start_fighting( ship, target );
    ship->laser_charge++;
    ship->energy -= energy_cost;
    double base_chance = standard_ship_hit_chance( ch ? ch : ship->squadleader ? ship->squadleader->piloting : NULL );
    double distance_mod = UMIN( 0.5 + ( double )( 1000 - dist + ship->sensor * 5 ) / 800 / 2, 1 );
    double class_mod = UMIN( 80 + target->classtype * 5, 100 ) / 100.0;
    double hit_percent = 100 * base_chance * distance_mod * class_mod;
    tune( "hit_percent for laser: %s has %.1f%% chance to hit %s", ship->name, hit_percent, target->name );

    if ( ch )
        act( AT_PLAIN, "$n presses the fire button.", ch, NULL, NULL, TO_ROOM );

    if ( number_percent() > hit_percent || ship_dodge( target, ship, true ) )
    {
        add_queue( target, SQUEUE_LASER_MISS, 0, 0, ch, ship );

        if ( ch )
            learn_from_failure( ch, skill_space_combat_1 );

        return true;
    }

    if ( vong_nullify( target ) )
    {
        add_queue( target, SQUEUE_VONG_NULLIFY_ENERGY, 0, 0, ch, ship );
        return true;
    }

    add_queue( target, SQUEUE_LASER_HIT, number_range( 5, 20 ), 0, ch, ship );

    if ( ch )
    {
        learn_from_success( ch, skill_space_combat_1 );
        learn_slow( ch, skill_space_combat_2, 4 );
        learn_slow( ch, skill_space_combat_3, 5 );
    }

    ai_anger( target, ship, FALSE );
    return true;
}

