bool turret_fire_checks_passed( SHIP_DATA* ship, CHAR_DATA* ch, TURRET_DATA* turret, int energy_cost, int charge_cost )
{
    if ( !turret->target )
    {
        if ( ch )
            ch_println( ch, "&RYou don't have a target!" );

        return false;
    }

    if ( turret->laserstate <= LASER_DAMAGED )
    {
        if ( ch )
            ch_println( ch, "&RThe turret is %s.", turret->laserstate == LASER_DESTROYED ? "destroyed" : "damaged" );

        return false;
    }

    if ( turret->laserstate + charge_cost > TURRET_STATE_MAX )
    {
        if ( ch )
            ch_println( ch, "&RThe turret is recharging." );

        return false;
    }

    if ( ship->energy < energy_cost )
    {
        if ( ch )
            ch_println( ch, "&RThe ship doesn't have enough energy!" );

        return false;
    }

    if ( turret->target->safe_orbital )
    {
        if ( ch )
            ch_println( ch, "&RThat target may not currently be attacked per HELP CAPITAL RULES." );

        return false;
    }

    if ( is_protected( ship, turret->target, true ) )
    {
        if ( ch )
            ch_println( ch, "&RThat ship is currently being protected by other ships." );

        return false;
    }

    return true;
}

// Returns true if an attempt was made, false if the weapon was unable to be fired right now
bool fire_ship_laser_turret( SHIP_DATA* ship, CHAR_DATA* ch, TURRET_DATA* turret )
{
    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );

    int energy_cost = valid_focus( ch, PILOTING_ABILITY ) ? 3 : 5;
    int charge_cost = TURRET_STATE_RECHARGE / 3; // 3 shots every 6.6 seconds = 9 lasers equivalent;

    if ( ship->classtype != CRUISER_SHIP )
    {
        if ( ch )
            ch_println( ch, "&RThis turret isn't equipped with lasers." );

        return false;
    }

    if ( !turret_fire_checks_passed( ship, ch, turret, energy_cost, charge_cost ) )
        return false;

    SHIP_DATA* target = turret->target;
    double dist = vector_distance( &ship->vpos, &target->vpos );

    if ( dist > 1000 )
    {
        if ( ch )
            ch_println( ch, "&RThat ship is out of laser range." );

        return false;
    }

    ship_start_fighting( ship, target );
    ai_anger( target, ship, FALSE );
    turret->laserstate += charge_cost;
    ship->energy -= energy_cost;
    double base_chance = standard_ship_hit_chance( ch );
    double distance_mod = UMIN( 0.5 + ( double )( 1000 - dist + ship->sensor * 5 ) / 800 / 2, 1 );
    double class_mod = UMIN( 80 + target->classtype * 5, 100 ) / 100.0;
    double hit_percent = 100 * base_chance * distance_mod * class_mod;
    tune( "hit_percent for laser turret: %s has %.1f%% chance to hit %s", ship->name, hit_percent, target->name );

    if ( ch )
        act( AT_PLAIN, "$n grips the targeting controls and fires.", ch, NULL, NULL, TO_ROOM );

    if ( number_percent() > hit_percent || ship_dodge( target, ship, true ) )
    {
        add_queue( target, SQUEUE_LASER_TURRET_MISS, 0, 0, ch, ship );
        learn_from_failure( ch, skill_space_combat_1 );
        return true;
    }

    add_queue( target, SQUEUE_LASER_TURRET_HIT, number_range( 5, 20 ), 0, ch, ship );
    learn_from_success( ch, skill_space_combat_1 );
    learn_slow( ch, skill_space_combat_2, 4 );
    learn_slow( ch, skill_space_combat_3, 5 );
    return true;
}

// Returns true if an attempt was made, false if the weapon was unable to be fired right now
bool fire_ship_autoblaster_turret( SHIP_DATA* ship, CHAR_DATA* ch, TURRET_DATA* turret )
{
    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );

    int energy_cost = valid_focus( ch, PILOTING_ABILITY ) ? 4 : 6;
    int charge_cost = TURRET_STATE_RECHARGE / 6; // 6 shots every 6.6 seconds = 6 autoblasters equivalent

    if ( ship->classtype > FRIGATE_SHIP )
    {
        if ( ch )
            ch_println( ch, "&RThis turret isn't equipped with autoblasters." );

        return false;
    }

    if ( !turret_fire_checks_passed( ship, ch, turret, energy_cost, charge_cost ) )
        return false;

    SHIP_DATA* target = turret->target;
    double dist = vector_distance( &ship->vpos, &target->vpos );

    if ( dist > 1000 )
    {
        if ( ch )
            ch_println( ch, "&RThat ship is out of autoblaster range." );

        return false;
    }

    ship_start_fighting( ship, target );
    ai_anger( target, ship, FALSE );
    turret->laserstate += charge_cost;
    ship->energy -= energy_cost;
    double base_chance = standard_ship_hit_chance( ch );
    // Autoblasters get much less accurate close to max range, relative to other weapons
    double distance_mod = UMIN( 0.25 + ( double )( 1000 - dist + ship->sensor * 5 ) / 800 * 0.75, 1 );
    double hit_percent = 100 * base_chance * distance_mod;
    tune( "hit_percent for autoblaster turret: %s has %.1f%% chance to hit %s", ship->name, hit_percent, target->name );

    if ( ch )
        act( AT_PLAIN, "$n grips the targeting controls and fires.", ch, NULL, NULL, TO_ROOM );

    int hits = 0;

    for ( int x = 0; x < 6; x++ ) // 1.5x the number of shots compared to a single autoblaster
    {
        if ( number_percent() > hit_percent || ship_dodge( target, ship, true ) )
        {
            add_queue( target, SQUEUE_AUTO_TURRET_MISS, 0, 0, ch, ship );
            continue;
        }

        hits++;

        if ( vong_nullify( target ) )
        {
            add_queue( target, SQUEUE_VONG_NULLIFY_ENERGY, 0, 0, ch, ship );
            continue;
        }

        add_queue( target, SQUEUE_AUTO_TURRET_HIT, number_range( 1, 5 ), 0, ch, ship );
    }

    if ( hits > 0 )
    {
        learn_from_success( ch, skill_space_combat_1 );
        learn_slow( ch, skill_space_combat_2, 4 );
        learn_slow( ch, skill_space_combat_3, 5 );
    }
    else
    {
        learn_from_failure( ch, skill_space_combat_1 );
    }

    return true;
}

