    learn_slow( ch, skill_space_combat_2, 4 );
    learn_slow( ch, skill_space_combat_3, 5 );
    return true;
}

void process_interceptor_carrier_ai( SHIP_DATA* ship )
{
    SHIP_DATA* tarnext;
    char buf[200];

    if ( ship->target0 == NULL )
        return;

    // Hold fighters unless we're close enough for their longest-ranged weapon to fire. No point launching fighters
    // for a target that's 2500 units away so they can get picked off by turbolasers before firing a shot.
    if ( vector_distance( &ship->vpos, &ship->target0->vpos ) > 1500 )
        return;

    int hangar_idx = 0;

    for ( HANGAR_DATA* hangar = ship->first_hangar; hangar; hangar = hangar->next )
    {
        hangar_idx++;

        if ( hangar == NULL )
            continue;

        if ( hangar->room == NULL )
            continue;

        for ( SHIP_DATA* target = hangar->room->first_ship; target; target = tarnext )
        {
            tarnext = target->next_in_room;

            if ( !xIS_SET( target->flags, SHIP_INTERCEPTOR ) )
                continue;

            if ( target->shipstate != SHIP_DOCKED )
                continue;

            if ( target->hull < target->maxhull * .1 )
                continue;

            if ( str_cmp( target->homeship, ship->name ) )  /* Home ship? */
                continue;

            /*
                RELOADING
            */
            /*
                .......... To much work for right now
            */

            /*
                REFUELING
            */
            if ( target->energy < target->maxenergy - 5 )
            {
                int fuel, maxfuel;
                maxfuel = ship->energy - ( int )( ship->maxenergy * .1 );
                fuel = URANGE( 0, target->maxenergy - target->energy, maxfuel );

                if ( fuel > 0 )
                {
                    snprintf( buf, 200, "The automatic pump system refuels %s", target->name );
                    echo_to_room( AT_YELLOW, hangar->room, buf );
                    ship->energy -= fuel;
                    target->energy += fuel;
                }
            }

            /*
                FUEL CHECK
            */
            if ( target->energy < target->maxenergy * .15 )
                continue;

            /*
                HATCH CHECK
            */
            if ( target->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
            {
                ship->hatchopen = FALSE;
                snprintf( buf, 200, "The hatch on %s closes.", target->name );
                echo_to_room( AT_YELLOW, get_room_index( target->location ), buf );
                echo_to_room( AT_YELLOW, get_room_index( target->entrance ), "The hatch slides shut." );
            }

            /*
                HANGAR CHECK
            */
            if ( !hangar->bayopen )
            {
                hangar->bayopen = TRUE;
                snprintf( buf, 200, "[ALERT]: Hangar %d is opening.", hangar_idx );
                echo_to_ship_windows( AT_YELLOW, ship, buf );
                snprintf( buf, 200, "One of the hangars on %s slowly slides open.", ship->name );
                echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
            }

            /*
                START LAUNCHING SEQUENCE
            */
            target->autopilot = true;
            target->energy -= target->maxshield - target->shield;
            target->shield = target->maxshield;
            begin_ship_launch( target );
            return; // Only launch one fighter for each 6-second pass through this code.
        }
    }
}

void process_interceptor_ai( SHIP_DATA* ship )
{
    char buf[200];
    SHIP_DATA* home = get_ship_here( ship->homeship, ship->starsystem );

    // Do nothing without a home ship
    if ( home == NULL )
        return;

    // Keep target in sync with home ship's target
    ship->target0 = home->target0;
    // Make sure shields are charging
    ship->autorecharge = TRUE;
    /*
        Validate the target
    */
    SHIP_DATA* target = ship->target0;

    if ( target )
    {
        if ( ship == target || ship->target0->starsystem != ship->starsystem )
        {
            ship->target0 = NULL;
            return;
        }
    }

    /*
        The ship needs a TARGET to fight.
        Plus, the ship will 'flee' or return early if:
        - Energy drops below 15% of max.
        - Hull drops below 10% of max.
    */
    if ( target &&
            ship->energy > ( ship->maxenergy * .15 ) &&
            ship->hull > ( ship->maxhull * .1 )
       )
    {
        // Try to stay within 400 units of the target.
        if ( vector_distance( &ship->vpos, &target->vpos ) > 400 && !is_facing( ship, target ) )
        {
            echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to turn." );
            snprintf( buf, 200, "%s turns, altering its present course.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship_set_course( ship, &target->vpos );
        }
    }
    else
    {
        // Let's head home
        if ( vector_distance( &ship->vpos, &home->vpos ) < 200 )
        {
            /*
                Land!
            */
            /*
                Please note: Auto launched interceptors do NOT close the hangar when they
                are all there. How do we rectify this? Have a counter for the main ship
                of how many interceptors it has and close when it it full?
            */
            for ( HANGAR_DATA* hangar = home->first_hangar; hangar; hangar = hangar->next )
            {
                if ( hangar->room == NULL )
                    continue;

                if ( ship->shipstate == SHIP_DOCKED )
                    continue;

                if ( !hangar->bayopen )
                    continue;

                if ( get_hangar_free( hangar ) < get_ship_size( ship ) )
                    continue;

                if ( !ship_to_room( ship, hangar->room->vnum ) )
                    continue;

                echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Landing sequence complete." );
                echo_to_ship_main( AT_YELLOW, ship, "You feel a slight thud as the ship sets down on the ground." );
                snprintf( buf, 200, "%s disappears from your scanner.", ship->name );
                echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
                ship->location = hangar->room->vnum;
                ship->lastdoc = hangar->room->vnum;
                ship->shipstate = SHIP_DOCKED;
                ship->shield = ship->maxshield;
                ship->currspeed = 0;
                ship_from_starsystem( ship );
                snprintf( buf, 200, "%s lands on the platform.", ship->name );
                echo_to_room( AT_YELLOW, get_room_index( ship->location ), buf );
                ship->tankpurge = FALSE;
                break;
            }
        }
        else
        {
            /*
                Get closer - Homing sub
            */
            if ( !is_facing( ship, home ) )
            {
                echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to turn." );
                snprintf( buf, 200, "%s turns, altering its present course.", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            }

            set_ship_speed( ship, ship->realspeed );
            ship_set_course( ship, &home->vpos );
        }
    }
}

bool in_turret_range( SHIP_DATA* ship, SHIP_DATA* target )
{
    return vector_distance( &ship->vpos, &target->vpos ) <= ( ship->classtype >= BATTLESHIP_SHIP ? 2000 : 1000 );
}

SHIP_DATA* get_turret_target( SHIP_DATA* ship )
{
    SHIP_DATA* valid_turret_targets[200];
    SHIP_DATA* pt;
    int valid_turret_target_count = 0;

    if ( !ship || ship_extracted( ship ) )
        return NULL;

    for ( pt = ship->starsystem->first_ship; pt; pt = pt->next_in_starsystem )
    {
        // Ignore ships >2000 units away on battleships+ or >1000 away on smaller ships
        if ( !in_turret_range( ship, pt ) )
        {
            debug( "get_turret_target: %s is not in turret range vs. %s", pt->name, ship->name );
            continue;
        }

        // Ignore ships which aren't either targeting a ship related to this one or related to the ship's target
        if ( pt->target0 != ship && ship->target0 != pt &&
                !same_group( pt->target0, ship ) && !same_group( pt, ship->target0 )
           )
        {
            debug( "get_turret_target: %s is not in a related group vs. %s", pt->name, ship->name );
            continue;
        }

        // Don't fire on our own ships no matter what happens
        if ( same_group( pt, ship ) )
            continue;

        if ( is_protected( ship, pt, true ) )
        {
            debug( "get_turret_target: %s is protected vs. %s", pt->name, ship->name );
            continue;
        }

        debug( "get_turret_target: %s is a valid target for %s", pt->name, ship->name );
        valid_turret_targets[valid_turret_target_count] = pt;
        valid_turret_target_count++;
        if ( valid_turret_target_count >= 200 ) // Don't blow past our array size
            break;
    }

    SHIP_DATA* best_target = NULL;

    for ( int i = 0; i < valid_turret_target_count; i++ )
    {
        pt = valid_turret_targets[i];

        if ( ship->classtype >= BATTLESHIP_SHIP )
        {
            // Things with turbolaser turrets should prefer to target frigates and larger.
            if ( pt->classtype >= FRIGATE_SHIP &&
                    ( !best_target ||
                      vector_distance( &pt->vpos, &ship->vpos ) < vector_distance( &best_target->vpos, &ship->vpos )
                    ) &&
                    number_range( 1, 10 ) <= 7 // Some randomness so not all turrets jump on the same target
               )
                best_target = pt;
        }
        else
        {
            // Things with laser/autoblaster turrets should prefer to target smaller ships
            if ( pt->classtype < FRIGATE_SHIP &&
                    ( !best_target ||
                      vector_distance( &pt->vpos, &ship->vpos ) < vector_distance( &best_target->vpos, &ship->vpos )
                    ) &&
                    number_range( 1, 10 ) <= 7 // Some randomness so not all turrets jump on the same target
               )
                best_target = pt;
        }
    }

    if ( best_target )
    {
        debug( "get_turret_target: %s selected as best target for %s", pt->name, ship->name );
        return best_target;
    }

    if ( valid_turret_target_count > 0 )
        return valid_turret_targets[number_range( 0, valid_turret_target_count - 1 )];

    return NULL;
}

void set_turret_target( SHIP_DATA* ship, TURRET_DATA* turret, SHIP_DATA* target )
{
    char buf[200];

    if ( turret->target == target )
        return;

    if ( turret->target )
    {
        snprintf( buf, 200, "A turret on %s has broken its target lock.", ship->name );
        echo_to_ship_windows( AT_BLOOD, turret->target, buf );
    }

    if ( target )
    {
        snprintf( buf, 200, "You are being targeted by a turret on %s.", ship->name );
        echo_to_ship_windows( AT_BLOOD, target, buf );
        int idx = 0;
        LINK_INDEXOF( ship->first_turret, TURRET_DATA, next, turret, idx );
        snprintf( buf, 200, "An alert pops up on a console: 'Turret %d now targeting %s.'\n", idx, target->name );
        echo_to_ship_windows( AT_LBLUE, ship, buf );
    }

    turret->target = target;
}

void process_autopilot_ai( SHIP_DATA* ship )
{
    char buf[MIL];
    CLAN_DATA* clan = NULL;
    CLAN_DATA* tclan = NULL;
    SHIP_DATA* target = NULL;

    if ( ship->currspeed > 0 )
    {
        // Sentinel ships always slow down steadily.
        // Autopilot ships which were moving due to having a target should stop moving once they don't have one.
        if ( xIS_SET( ship->aflags, AFLAG_SENTINEL ) ||
                ( ship->target0 == NULL && !is_pirate( ship ) )
           )
            ship->currspeed = URANGE( 0, ship->currspeed - 20, ship->realspeed );

        if ( ship->currspeed == 0 )
        {
            snprintf( buf, MIL, "%s comes to a halt.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
    }

    /*
        Clanpost Routine
    */
    if ( xIS_SET( ship->aflags, AFLAG_CLANPOST ) && ship_has_weapons( ship ) && ship->starsystem != NULL )
    {
        clan = ship->clan;

        if ( clan != NULL )
        {
            /*
                Scan other nearby ships
            */
            SHIP_DATA* tarnext;

            for ( target = ship->starsystem->first_ship; target; target = tarnext )
            {
                tarnext = target->next_in_starsystem;

                if ( target == ship )
                    continue;

                if ( !xIS_SET( clan->flags, CLAN_VONG ) && xIS_SET( target->flags, SHIP_VONG ) )
                    ai_anger( ship, target, FALSE );
                else if ( ( tclan = target->clan ) != NULL )
                    if ( enemy_clan( clan, tclan ) )
                        ai_anger( ship, target, FALSE );
            }
        }
    }

    target = ship->target0;

    if ( !target )
        return;

    if ( target->cloakstatus == CLOAK_ON )
    {
        ship->target0 = NULL;
        return;
    }

    if ( target->starsystem != ship->starsystem )
    {
        ship->target0 = NULL;
        return;
    }

    if ( xIS_SET( ship->aflags, AFLAG_AUTOSHIELD ) )
    {
        ship->autorecharge = TRUE;

        // Special logic for ships which should recharge more like players, up to max every 6 seconds
        if ( xIS_SET( ship->flags, SHIP_AUTO_FASTRECHARGE ) )
        {
            int recharge_amt = ship->maxshield - ship->shield;

            if ( ship->energy > recharge_amt && ship->energy > ship->shield )
            {
                ship->shield += recharge_amt;
                ship->energy -= recharge_amt;
            }
        }
    }

    if ( !xIS_SET( ship->aflags, AFLAG_SENTINEL ) )
    {
        ship->autotrack = TRUE;

        // Fighters can fly back and forth swarming their target. Any other ships should stop once they're 500 units away.
        if ( ship->classtype == FIGHTER_SHIP )
        {
            set_ship_speed( ship, ship->realspeed );
        }
        else
        {
            if ( vector_distance( &ship->vpos, &target->vpos ) > 500 )
                set_ship_speed( ship, ship->realspeed );
            else
                set_ship_speed( ship, 0 );
        }
    }

    if ( autofly( target ) && target->target0 == NULL )
    {
        if ( !is_protected( target, ship, false ) )
            target->target0 = ship;
        else
            target->target0 = nearest_unprotected_group_ship( target->vpos, target, ship, false );
    }

    bool fastfire = xIS_SET( ship->flags, SHIP_AUTO_FASTFIRE );

    // Energy weapons
    if ( xIS_SET( ship->flags, SHIP_VONG ) )
    {
        fire_ship_yaretkor( ship, NULL, target );
        fire_ship_yaretkor( ship, NULL, target );
        fire_ship_yaretkor( ship, NULL, target );
    }
    else
    {
        // These fire rates are meant for fastfire ships to exhaust their initial charges gradually and then keep up maximum possible fire.
        // Other ships should fire at about half their maximum steady rate.
        if ( ship->blasters > 0 )
            for ( int i = 0; i < UMAX( fastfire ? ship->blasters : ship->blasters / 2, 1 ); i++ )
                fire_ship_autoblaster( ship, NULL, target );

        if ( ship->lasers > 0 )
            for ( int i = 0; i < UMAX( fastfire ? ship->lasers / 2 + 1 : ship->lasers / 6, 1 ); i++ )
                fire_ship_laser( ship, NULL, target );

        if ( ship->turbolasers > 0 )
            for ( int i = 0; i < UMAX( fastfire ? ship->turbolasers / 6 + 1 : ship->turbolasers / 18, 1 ); i++ )
                fire_ship_turbolaser( ship, NULL, target );

        if ( ship->ion > 0 )
            for ( int i = 0; i < UMAX( fastfire ? ship->ion / 6 + 1 : ship->ion / 18, 1 ); i++ )
                fire_ship_ion( ship, NULL, target );
    }

    // Turrets
    if ( xIS_SET( ship->flags, SHIP_AUTO_TURRET ) )
    {
        // First acquire targets
        for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
        {
            // Clear targets if they're too far
            if ( turret->target && !in_turret_range( ship, turret->target ) )
                set_turret_target( ship, turret, NULL );

            // Pick a new target
            if ( !turret->target )
            {
                SHIP_DATA* new_target = get_turret_target( ship );

                if ( new_target )
                    set_turret_target( ship, turret, new_target );
            }
        }

        // Now fire all the turrets
        for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
        {
            if ( !turret->target )
                continue;

            if ( ship->classtype <= FRIGATE_SHIP )
                for ( int i = 0; i < ( fastfire ? 6 : number_range( 2, 4 ) ); i++ )
                    fire_ship_autoblaster_turret( ship, NULL, turret );
            else if ( ship->classtype == CRUISER_SHIP )
                for ( int i = 0; i < ( fastfire ? 3 : number_range( 1, 2 ) ); i++ )
                    fire_ship_laser_turret( ship, NULL, turret );
            else
                for ( int i = 0; i < ( fastfire ? 2 : 1 ); i++ )
                    fire_ship_turbolaser_turret( ship, NULL, turret );
        }
    }

    // Projectiles
    int projectile_fire_amt;

    if ( fastfire )
        projectile_fire_amt = number_range( 4, 6 );
    else
        projectile_fire_amt = number_range( 1, 2 );

    for ( int i = 0; i < projectile_fire_amt; i++ )
    {
        if ( !xIS_SET( ship->aflags, AFLAG_USELAUNCHER ) )
            break;

        if ( ship->missilestate >= MISSILE_DAMAGED )
            break;

        if ( ship->missilestate != MISSILE_READY && ship->spent_tubes >= ship->missiletubes )
            break;

        // Whichever of these actually tries to happen will stop us from trying the rest.
        bool fired_any = fire_ship_pulse( ship, NULL, target )
                         || fire_ship_rocket( ship, NULL, target )
                         || fire_ship_torpedo( ship, NULL, target )
                         || fire_ship_missile( ship, NULL, target );

        if ( !fired_any )
            break;
    }
}

void recharge_ships_and_update_ai(  )
{
    SHIP_DATA* ship;
    char buf[MIL];
    TURRET_DATA* turret;

    // Declare the array of pointers to copy the linked list into
    SHIP_DATA** all_ships = NULL;

    // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
    LINK_TO_ARRAY( first_ship, SHIP_DATA, next, all_ships );

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( IS_SET( ship->act_flags, MOD_GRAVITYWELL ) )
        {
            if ( ship->energy <= 240 && ship->energy > 220 )
            {
                echo_to_ship_main( AT_BLUE, ship, "[ALERT]: GRAVITY WELL NEARING OVERLOAD - SHUTDOWN SYSTEM NOW" );

                if ( autofly( ship ) )
                {
                    echo_to_ship_main( AT_YELLOW, ship, "[Autopilot]: Gravity Well Emitter Deactivating!" );
                    REMOVE_BIT( ship->act_flags, MOD_GRAVITYWELL );
                    snprintf( buf, MIL, "%s shimmers as a invisible field disappears.", ship->name );
                    echo_to_system_noqueue( AT_BLUE, ship, buf, NULL );
                }
            }
            else if ( ( ship->energy <= 140 && number_percent(  ) > 80 ) || ( ship->energy <= 35 ) )
            {
                echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: GRAVITY WELL DESTABILIZED: FAILSAFE SHUTDOWN ACTIVATED" );
                echo_to_ship_main( AT_BLOOD, ship, "A violent explosion shakes the ship, as the Gravity well generator" );
                echo_to_ship_main( AT_BLOOD, ship, "overloads. Flames burst forth and smoke fills the room..." );
                snprintf( buf, MIL, "%s shimmers as a invisible field collapses around it.", ship->name );
                echo_to_system_noqueue( AT_BLUE, ship, buf, NULL );
                REMOVE_BIT( ship->act_flags, MOD_GRAVITYWELL );
                REMOVE_BIT( ship->mod_flags, MOD_GRAVITYWELL );

                /*
                    Lets damage it, Mwhahahahahaha =)
                */
                if ( number_percent(  ) > 40 || ship->energy < 70 )
                    damage_ship( ship, ( 150 - ship->energy ) / 2, ( 175 - ship->energy ) / 2, NULL, NULL );
            }

            ship->energy = ( ship->energy - 40 < 0 ) ? 0 : ship->energy - 40;
        }

        if ( ship->cloakstatus == CLOAK_ON )
        {
            if ( ship->energy < 500 )
            {
                echo_to_ship_windows( AT_YELLOW, ship, "Cloaking Device off!" );
                echo_to_ship_windows( AT_BLUE, ship, "[Autopilot] Cloaking Device Deactivating!" );
                ship->cloakstatus = CLOAK_READY;

                if ( xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - deactivating cloak allows ping.
                {
                    xREMOVE_BIT( ship->flags, SHIP_NO_PING );
                }

                snprintf( buf, MIL, "%s shimmers into existence.", ship->name );
                echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
            }
            else
                ship->energy -= 30;
        }

        if ( ship->tankpurge )
        {
            /*
                Purging the tanks. This parts fun =)
            */
            ship->energy = URANGE( 0, ship->energy - number_range( 100, 200 ), ship->maxenergy );

            if ( ship->energy == 0 )
                ship->tankpurge = FALSE;
        }

        if ( xIS_SET( ship->flags, SHIP_VONG ) && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ship->hull < ship->maxhull )
        {
            if ( ship->energy > 500 )
            {
                snprintf( buf, MIL, "Several holes in the outer structure of %s appear to seal and smooth over.", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                echo_to_ship_windows( AT_GREEN, ship, "Biomass pumps through the ship's vessels and heals some damage to its outer shell." );
                // Fighter: 30/6sec (0)
                // Cruiser: 120/6sec (6)
                int regen_amt = ( ship->classtype + 2 ) * 15;
                regen_amt = UMIN( regen_amt, ship->maxhull - ship->hull );
                ship->hull += regen_amt;
                ship->energy -= regen_amt;
            }
            else
            {
                echo_to_ship_windows( AT_RED, ship, "The ship's liquid biomass reserves are too low to repair its structure." );
            }
        }

        ship->hull = URANGE( 0, ship->hull, ship->maxhull );
        ship->shield = URANGE( 0, ship->shield, ship->maxshield );

        for ( turret = ship->first_turret; turret; turret = turret->next )
        {
            if ( !turret || turret == NULL )
                break;

            if ( turret->laserstate > 0 )
            {
                turret->laserstate = UMAX( 0, turret->laserstate - TURRET_STATE_RECHARGE );
            }
        }

        /*
            Replenish the ship's charge
        */
        if ( ship->laser_charge > 0 )
        {
            if ( xIS_SET( ship->flags, SHIP_VONG ) && ship->classtype > BATTLESHIP_SHIP )
                ship->laser_charge = UMAX( 0, ship->laser_charge - 4 );
            else if ( xIS_SET( ship->flags, SHIP_VONG ) && ship->classtype == BATTLESHIP_SHIP )
                ship->laser_charge = UMAX( 0, ship->laser_charge - 3 );
            else
                // Replenish all laser charge every 20 seconds
                ship->laser_charge = UMAX( 0, ship->laser_charge - ship->lasers / 3.0 );
        }

        if ( ship->autoblaster_charge > 0 )
        {
            // Autoblasters get fully replenished every tick
            ship->autoblaster_charge = 0;
        }

        if ( ship->turbolaser_charge > 0 )
        {
            // Turbolasers are fully recharged every minute: 9 space ticks
            ship->turbolaser_charge = UMAX( 0, ship->turbolaser_charge - ship->turbolasers / 9.0 );
        }

        if ( ship->ion_charge > 0 )
        {
            // Ion cannons are fully recharged every minute: 9 space ticks
            ship->ion_charge = UMAX( 0, ship->ion_charge - ship->ion / 9.0 );
        }

        if ( ship->missilestate == MISSILE_RELOAD_2 )
        {
            ship->spent_tubes = 0;
            ship->missilestate = MISSILE_READY;

            if ( ship->missiles > 0 || ship->torpedoes > 0 || ship->rockets > 0 )
                echo_to_room( AT_YELLOW, get_room_index( ship->gunseat ), "Missile launcher(s) reloaded." );
        }

        if ( ship->tractorstate == TRACTOR_REFRESH )
        {
            ship->tractorstate = TRACTOR_READY;

            if ( ship->tractorbeam > 0 )
                echo_to_ship_windows( AT_YELLOW, ship, "Tractor beam recharged." );
        }

        if ( ship->tractorstate == TRACTOR_BUSY )
        {
            ship->tractorstate = TRACTOR_REFRESH;
        }

        if ( ship->missilestate == MISSILE_RELOAD )
        {
            ship->missilestate = MISSILE_RELOAD_2;
        }

        if ( ship->missilestate == MISSILE_FIRED )
            ship->missilestate = MISSILE_RELOAD;

        // Below here, any logic should be kept for ships in space.
        if ( ship->shipstate != SHIP_READY && ship->shipstate != SHIP_BUSY )
            continue;

        if ( autofly( ship ) && !is_public( ship ) )
        {
            /*
                            -= Advanced Ship Interceptors =-
                Another genius idea straight from Ghost himself. ;)

                FLAGS:
                CAN_INTERCEPT - Used to determine what ships are using 'interceptors'
                INTERCEPTOR - Used to determine if a ship is being used as a 'interceptor'
                USAGE:
                Simple enough. First, pick a 'home base' for your interceptors,
                (IE: ISD Darkhand) and set the 'CAN_INTERCEPT' flag on it. Then, to add
                interceptors, simple TRANSSHIP ships into any hangar, and set the
                'INTERCEPTOR' flag on it. The ship system will take it from there. =)
            */

            /*
                We've got an interceptor-capable ship =)
                TO ENGAGE: Must be on AUTOPILOT, and must have a target.
                Handles scrambling interceptors
            */
            if ( xIS_SET( ship->flags, SHIP_CAN_INTERCEPT ) &&
                    ship->first_hangar != NULL &&
                    !xIS_SET( ship->aflags, AFLAG_NOINTERCEPT )
               )
                process_interceptor_carrier_ai( ship );

            // Interceptor AI module
            // Handles moving toward target or recalling to home ship
            if ( xIS_SET( ship->flags, SHIP_INTERCEPTOR ) && !NULLSTR( ship->homeship ) )
                process_interceptor_ai( ship );

            // Bail out if interceptor AI landed this ship
            if ( ship->shipstate != SHIP_READY && ship->shipstate != SHIP_BUSY )
                continue;

            /*
                Autopilot AI Module ---
                Handles SENTINEL Flag
                Handles AGGRESSIVE Flag (Later)
                Handles CLANPOST Flag (Clan Aggression)
                Handles Combat Routines
            */
            process_autopilot_ai( ship );
        }
    }

    DISPOSE( all_ships );
    return;
}

bool can_land( SHIP_DATA* ship )
{
    if ( ship->classtype == CRUISER_SHIP )
        return FALSE;

    if ( ship->classtype == BATTLESHIP_SHIP )
        return FALSE;

    if ( ship->classtype == BATTLESTATION_SHIP )
        return FALSE;

    if ( ship->classtype == PLATFORM_SHIP )
        return FALSE;

    if ( ship->classtype == SATELLITE_SHIP )
        return FALSE;

    return TRUE;
}

bool auto_refuel( SHIP_DATA* ship )
{
    if ( ship->shipstate == SHIP_DISABLED )
        return FALSE;

    if ( ship->shipstate == SHIP_PERM_DISABLED )
        return FALSE;

    if ( IS_SET( ship->act_flags, MOD_GRAVITYWELL ) )
        return FALSE;

    if ( ship->classtype == FRIGATE_SHIP )
        return TRUE;

    if ( ship->classtype == CRUISER_SHIP )
        return TRUE;

    if ( ship->classtype == BATTLESHIP_SHIP )
        return TRUE;

    if ( ship->classtype == BATTLESTATION_SHIP )
        return TRUE;

    if ( ship->classtype == PLATFORM_SHIP )
        return TRUE;

    if ( ship->classtype == SATELLITE_SHIP )
        return TRUE;

    return FALSE;
}

