void auto_jettison( SHIP_DATA* ship )
{
    CARGO_DATA* cargo;

    for ( cargo = ship->first_cargo; cargo; cargo = cargo->next )
    {
        if ( cargo == NULL )
            continue;

        if ( cargo->amount <= 0 )
            continue;

        if ( number_range( 1, 3 ) != 1 )
        {
            cargo->amount /= number_range( 1, 3 );
            new_fcargo( ship, NULL, cargo->type, cargo->amount );
        }

        cargo->type = 0;
        cargo->amount = 0;
    }

    return;
}

void echo_to_ship_main( int color, SHIP_DATA* ship, const char* argument )
{
    ROOM_INDEX_DATA* room = NULL;

    if ( !ship || ship->occupants == 0 )
        return;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( !room->first_person )
            continue;

        echo_to_room( color, room, argument );
    }

    return;
}

void echo_to_ship_bridge( int color, SHIP_DATA* ship, const char* argument )
{
    ROOM_INDEX_DATA* room = NULL;
    bool echo = FALSE;

    if ( !ship || ship->occupants == 0 )
        return;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( !room->first_person )
            continue;

        echo = false;

        if ( room->vnum == ship->cockpit || room->vnum == ship->navseat ||
                room->vnum == ship->pilotseat || room->vnum == ship->coseat ||
                room->vnum == ship->gunseat || room->vnum == ship->engineroom
           )
            echo = true;

        if ( echo )
            echo_to_room_filter( color, room, argument, NULL );
    }

    return;
}

void gravwell_check()
{
    SHIP_DATA* ship;

    // Declare the array of pointers to copy the linked list into
    SHIP_DATA** all_ships = NULL;

    // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
    LINK_TO_ARRAY( first_ship, SHIP_DATA, next, all_ships );

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            SPACE_DATA* currsys;

            if ( ( currsys = system_from_galactic_coords( ship->hyper_currentpos ) ) != NULL )
            {
                SHIP_DATA* eShip;
                //   int dist;

                for ( eShip = currsys->first_ship; eShip; eShip = eShip->next_in_starsystem )
                {
                    if ( eShip == ship )
                        continue;

                    if ( IS_SET( eShip->act_flags, MOD_GRAVITYWELL ) ) // && dist <= MAX_GRAVITY_RANGE )
                    {
                        echo_to_ship_windows( AT_YELLOW, ship, "You are pulled out of hyperspace by a gravity well!" );
                        int pullrange = number_range( 500, MAX_GRAVITY_RANGE );

                        if ( number_percent() > 50 )
                            ship->vpos.x = eShip->vpos.x + ( int )( pullrange / 3 );
                        else
                            ship->vpos.x = eShip->vpos.x - ( int )( pullrange / 3 );

                        if ( number_percent() > 50 )
                            ship->vpos.y = eShip->vpos.y + ( int )( pullrange / 3 );
                        else
                            ship->vpos.y = eShip->vpos.y - ( int )( pullrange / 3 );

                        if ( number_percent() > 50 )
                            ship->vpos.z = eShip->vpos.z + ( int )( pullrange / 3 );
                        else
                            ship->vpos.z = eShip->vpos.z - ( int )( pullrange / 3 );

                        exit_hyperspace( ship );
                        return;
                    }
                }
            }
        }
    }

    DISPOSE( all_ships );
    return;
}
void update_space( )
{
    SHIP_DATA* ship = NULL, *leader = NULL;
    SHIP_DATA* target = NULL;
    PLANET_DATA* planet = NULL;
    char buf[MSL];
    int too_close = 0, recharge = 0, transfer = 0, oldval = 0;

    // Declare the array of pointers to copy the linked list into
    SHIP_DATA** all_ships = NULL;

    // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
    LINK_TO_ARRAY( first_ship, SHIP_DATA, next, all_ships );

    debug( "update_space: first ship loop" );

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) && is_public( ship ) )
            if ( ship_occupants_count( ship ) <= 0 )
                resetship( ship );

        if ( ship->total_fuel_transfer > 0 || ship->remaining_fuel_transfer > 0 )
        {
            if ( ship->dockship == NULL || ship->dock_state != DOCK_DOCKED )
            {
                ship->total_fuel_transfer = 0;
                ship->remaining_fuel_transfer = 0;
            }
            else if ( ship->remaining_fuel_transfer <= 0 )
                ship->total_fuel_transfer = 0;
            else
            {
                transfer = ship->remaining_fuel_transfer;
                transfer = UMIN( transfer, ( ship->dockship->maxenergy / 10 ) );
                transfer = UMIN( transfer, ( ship->dockship->maxenergy - ship->dockship->energy ) );
                ship->remaining_fuel_transfer -= transfer;
                ship->energy -= transfer;
                ship->dockship->energy += transfer;
                snprintf( buf, MIL, "\n&z[&CALERT&z]: &zTransferred &C%'d&z unit(s) of fuel to &C%s&z...", transfer, ship->dockship->name );
                echo_to_ship_bridge( AT_WHITE, ship, buf );
                snprintf( buf, MIL, "\n&z[&CALERT&z]: &C%s&z has transferred &C%'d&z units of fuel to onboard tanks.", ship->name, transfer );
                echo_to_ship_bridge( AT_WHITE, ship->dockship, buf );

                if ( ship->remaining_fuel_transfer <= 0 )
                {
                    ship->remaining_fuel_transfer = 0;
                    ship->total_fuel_transfer = 0;
                }

                save_ship( ship, true );
                save_ship( ship->dockship, true );
            }
        }

        if ( ship->_squadleader_uid > 0 && !ship->squadleader )
        {
            leader = ship_from_id( ship->_squadleader_uid );
            if ( !leader || xIS_SET( leader->flags, SHIP_DRYDOCK ) )
                remove_from_squad( ship );
            else
                add_to_squad( ship, leader );
        }

        if ( ship->_leader_uid > 0 && !ship->leader )
        {
            leader = ship_from_id( ship->_leader_uid );
            if ( !leader || xIS_SET( leader->flags, SHIP_DRYDOCK ) )
                remove_from_bg( ship );
            else
                add_to_bg( ship, leader );
        }

        if ( ship_is_fighting( ship ) )
        {
            ship->fight_timer = URANGE( 0, ship->fight_timer - 1, 1000 );
            save_ship( ship, TRUE );
        }

        /*
            Pubbie patch
            GRAL us is_public?
        */
        if ( !str_cmp( ship->shipowner, "Public" ) || !str_cmp( ship->shipowner, "public" ) )
        {
            if ( NULLSTR( ship->pilot ) )
            {
                if ( !xIS_SET( ship->flags, SHIP_NODELETE ) )
                {
                    xSET_BIT( ship->flags, SHIP_NODELETE );
                    save_ship( ship, TRUE );
                }
            }
        }

        /*
            Fix for nullspace. GRR -Orion
        */
        if ( ( ship->location == 0 || !ship->in_room ) && ship->starsystem == NULL && ship->shipstate != SHIP_HYPERSPACE )
        {
            bug( "Attempting to fix nullspaced ship: %s, state %d", ship->name, ship->shipstate );

            if ( ship->lastdoc > 0 )
            {
                ship_to_room( ship, ship->lastdoc );
                ship->location = ship->lastdoc;
            }
            else if ( ship->shipyard > 0 )
            {
                ship_to_room( ship, ship->shipyard );
                ship->location = ship->shipyard;
                ship->lastdoc = ship->shipyard;
            }
            else
            {
                ship_to_room( ship, ROOM_LIMBO_SHIPYARD );
                ship->location = ROOM_LIMBO_SHIPYARD;
                ship->lastdoc = ROOM_LIMBO_SHIPYARD;
                ship->shipyard = ROOM_LIMBO_SHIPYARD;
            }

            save_ship( ship, TRUE );
        }

        /*
            Docking Safeties, Resets the flags if invalid
        */
        if ( ship->dock_state == DOCK_NONE && ship->dock_install )
            ship->dock_install = FALSE;

        if ( ship->dock_state != DOCK_NONE && !ship->dock_install )
            ship->dock_install = TRUE;

        /*
            Update the energy values on ships.
        */
        if ( ship->starsystem || ship->shipstate == SHIP_HOVER )
        {
            if ( auto_refuel( ship ) )  /* Does this ship replenish fuel? */
            {
                oldval = ship->energy;
                if ( ship->classtype > BATTLESTATION_SHIP )
                    ship->energy = URANGE( 0, ship->energy + 60, ship->maxenergy );
                else
                    ship->energy = URANGE( 0, ship->energy + 20, ship->maxenergy );

                if ( ship->energy != oldval )
                    save_ship( ship, TRUE );
            }

            // We don't want people idling with hover - so drain the eff out of their fuel
            if ( ship->shipstate == SHIP_HOVER )
            {
                oldval = ship->energy;
                if ( ship->piloting )
                    ship->energy = URANGE( 0, ship->energy - ( ship->maxenergy * .01 ), ship->maxenergy );
                else
                    ship->energy = URANGE( 0, ship->energy - ( ship->maxenergy * .02 ), ship->maxenergy );

                if ( ship->energy != oldval )
                    save_ship( ship, TRUE );
            }

            if ( ship->energy < 1 && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
            {
                echo_to_ship_windows( AT_RED, ship, "[ALERT]: Ship is out of fuel. Engines are disabled." );
                ship->tankpurge = FALSE;
                ship->shipstate = SHIP_DISABLED;
                save_ship( ship, TRUE );
            }
        }

        /*  If the ship's disabled, allow gravitation forces from nearby massive objects to slowly
            decelerate it -- really, so other ships can eventually dock with it for rescue purposes */
        if ( ship->starsystem && ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) )
        {
            oldval = ship->currspeed;
            ship->currspeed = URANGE( 0, ship->currspeed - 1, ship->realspeed );

            if ( ship->currspeed != oldval )
                save_ship( ship, TRUE );
        }

        /*
            Docking System. Keep a docked ship on the right course.
        */
        if ( ship->dock_state == DOCK_DOCKED && !ship->dock_lead )
        {
            SHIP_DATA* follow = ship->dockship;

            if ( !follow )
                bug( "ALERT: Dock error... following ship missing!" );
            else
            {                
                if ( ship->currspeed != follow->currspeed )
                    ship->currspeed = follow->currspeed;

                ship_align_heading( ship, follow );
                vector_copy( &ship->vpos, &follow->vpos );
                save_ship( ship, TRUE );
            }
        }

        /*
            For public ship that are stranded in space. Come home.
        */
        if ( is_public( ship ) && ship->starsystem && ship_crew_count( ship, NULL ) <= 0 )
        {
            if ( ship->preset == 0 )
            {
                if ( sysOb )
                    ch_println( sysOb, "%s initiating homing countdown.", ship->name );

                ship->preset = PULSE_MINUTE * 15;
            }
            else if ( ship->preset == 1 )
            {
                if ( sysOb )
                    ch_println( sysOb, "%s homing.", ship->name );

                ship_from_starsystem( ship );
                ship_to_room( ship, ( ship->lastdoc > 0 ? ship->lastdoc : ( ship->shipyard > 0 ? ship->shipyard : 45 ) ) );
                save_ship( ship, TRUE );
                continue;
            }
            else
                ship->preset -= PULSE_PER_SECOND;
        }

        /*
            Docking System   -Ghost
        */
        if ( ship->dock_state == DOCK_DOCKED && ( !ship->dockship || ship->dockship == NULL ) )
        {
            ship->dock_state = DOCK_READY;
            save_ship( ship, TRUE );
        }

        if ( ship->dock_state == DOCK_BUSY_2 )
        {
            dockship( ship );
            save_ship( ship, TRUE );
        }

        if ( ship->dock_state == DOCK_BUSY_1 )
        {
            ship->dock_state = DOCK_BUSY_2;
            save_ship( ship, TRUE );
        }

        /*
            Cooldown
        */
        if ( ship->shipstate == SHIP_COOLDOWN )
        {
            ship->shipstate = SHIP_DOCKED;
            save_ship( ship, TRUE );
        }

        if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        {
            /*
                For ships in space, drain shields/energy ( just a little )
                A Docked, Following ship does not burn fuel.
            */
            if ( ship->dock_state != DOCK_DOCKED || ship->dock_lead )
            {
                oldval = ship->shield;
                ship->shield = UMAX( 0, ship->shield - ship_drain( ship ) );
                if ( ship->shield != oldval ) save_ship( ship, TRUE );

                oldval = ship->energy;
                ship->energy = UMAX( 0, ship->energy - ship_drain( ship ) );
                if ( ship->energy != oldval ) save_ship( ship, TRUE );
            }

            // Autorecharge system
            // Not active when landed or disabled since we don't want those ships to drain fuel
            if ( ship->autorecharge && ship->maxshield > ship->shield && ship->energy > ship->shield )
            {
                recharge = UMAX( 20, ship->maxshield / 20 );
                recharge = UMIN( recharge, ship->maxshield - ship->shield );
                oldval = ship->shield;
                ship->shield = URANGE( 0, ship->shield + recharge, ship->maxshield );
                if ( ship->shield != oldval ) save_ship( ship, TRUE );
                oldval = ship->energy;
                ship->energy = URANGE( 0, ship->energy - recharge, ship->maxenergy );
                if ( ship->energy != oldval ) save_ship( ship, TRUE );
            }
        }

        //Shields fizzle if energy drops below 80
        if ( ship->shield > 0 )
        {
            if ( ship->energy < 80 )
            {
                ship->shield = 0;
                echo_to_ship_windows( AT_RED, ship, "The ship's shields fizzle and die." );
                ship->autorecharge = FALSE;
                save_ship( ship, TRUE );
            }
        }

        // Update ship prompt
        if ( ship->starsystem && ship->currspeed > 0 && ship->cloakstatus != CLOAK_ON )
        {
            ROOM_INDEX_DATA* room;
            double pa = 0;
            room = get_room_index( ship->pilotseat );

            if ( ship->maxenergy > 0 )
                pa = ( ( ( double )( ship->energy ) / ( double )( ship->maxenergy ) ) * 100 );

            snprintf( buf, MSL, "Speed: &w&C%d  &BFuel Level: &C%d%%  &BCoords: &C%.0f %.0f %.0f", ship->currspeed, ( int )pa,
                     ship->vpos.x, ship->vpos.y, ship->vpos.z );
            echo_to_room_dnr( AT_BLUE, room, buf );

            if ( ship->pilotseat != ship->coseat )
            {
                room = get_room_index( ship->coseat );
                snprintf( buf, MSL, "Speed: &w&C%d  &BFuel Level: &C%d%%  &BCoords: &C%.0f %.0f %.0f", ship->currspeed, ( int )pa,
                         ship->vpos.x, ship->vpos.y, ship->vpos.z );
                echo_to_room_dnr( AT_BLUE, room, buf );
            }
        }

        // Proximity Alerts (Updated by Ghost)
        if ( ship->starsystem )
        {
            PLANET_DATA* planet;
            // Notify people they will soon sun themselves!
            PLANET_DATA* tpl;

            if ( get_room_index( ship->cockpit ) ) // Make sure we got a room to notify
                for ( tpl = ship->starsystem->first_planet; tpl; tpl = tpl->next_in_system )
                {
                    if ( xIS_SET( tpl->flags, PLANET_STAR ) )
                        if ( vector_distance( &ship->vpos, &tpl->pos ) <= 1000 )
                        {
                            snprintf( buf, MSL, "&Y[STAR ALERT] %s is within 1000 units!\n", tpl->name );
                            echo_to_ship_windows( AT_YELLOW, ship, buf );
                        }
                }

            too_close = ship->currspeed + 50;
            SHIP_DATA* tarnext;

            for ( target = ship->starsystem->first_ship; target; target = tarnext )
            {
                tarnext = target->next_in_starsystem;

                if ( target == NULL )
                    continue;

                if ( target == ship->dockship || target->dockship == ship )
                    continue;

                if ( target == ship )
                    continue;

                if ( ship->cloakstatus == CLOAK_ON )
                    continue;


                if ( vector_distance( &ship->vpos, &target->vpos ) < too_close )
                {
                    if ( target->cloakstatus != CLOAK_ON )
                    {
                        snprintf( buf, MSL, "    Proximity alert: %s  %.0f %.0f %.0f", target->name, target->vpos.x, target->vpos.y,
                                 target->vpos.z );
                        echo_to_room_prox( AT_RED, get_room_index( ship->pilotseat ), buf );
                    }
                }

                too_close = ship->currspeed + 100;

                for ( planet = first_planet; planet; planet = planet->next )
                {
                    if ( planet == NULL )
                        continue;

                    if ( planet->starsystem != ship->starsystem )
                        continue;

                    if ( xIS_SET( planet->flags, PLANET_STAR ) )
                    {
                        if ( vector_distance( &ship->vpos, &planet->pos ) < too_close )
                        {
                            if ( ship->cloakstatus != CLOAK_ON )
                            {
                                snprintf( buf, MSL, "Proximity alert: (STAR) %s  %lf %lf %lf", planet->name, planet->pos.x, planet->pos.y,
                                         planet->pos.z );
                                echo_to_room_prox( AT_RED, get_room_index( ship->pilotseat ), buf );
                            }
                        }
                    }
                }
            }
        }

        /*
            Update Target Tracking
        */
        if ( ship->target0 )
        {
            double prox = 0;
            prox = vector_distance( &ship->vpos, &ship->target0->vpos );
            snprintf( buf, MSL, "Target: &w&C%s   %.0f %.0f %.0f  (Prox: %.0f)", ship->target0->name, ship->target0->vpos.x,
                     ship->target0->vpos.y, ship->target0->vpos.z, prox );
            echo_to_ship_windows( AT_BLUE, ship, buf );

            if ( ship->starsystem != ship->target0->starsystem )
                ship->target0 = NULL;

            if ( ship->shipstate == SHIP_HYPERSPACE )
                ship->target0 = NULL;
        }

        if ( ship->target_v )
        {
            snprintf( buf, MSL, "Target: &w&C%s   &BShields: &w&C%d   &BHull: &w&C%d", ship->target_v->name,
                     ship->target_v->shield, ship->target_v->hull );
            echo_to_ship_windows( AT_BLUE, ship, buf );

            if ( ship->in_room != ship->target_v->in_room )
                ship->target_v = NULL;

            if ( ship->shipstate != SHIP_HOVER )
                ship->target_v = NULL;
        }

        if ( ship->energy > 0 && ship->energy < 250 && ship->starsystem )
        {
            echo_to_ship_windows( AT_RED, ship, "[ALERT]: Ship is low on fuel." );
        }

        oldval = ship->energy;
        ship->energy = URANGE( 0, ship->energy, ship->maxenergy );
        if ( ship->energy != oldval ) save_ship( ship, TRUE );
        firehose_write_ship( ship );
    }

    debug( "update_space: second ship loop" );

    for ( int i = 0; all_ships[i]; i++ )
    {
        ship = all_ships[i];

        if ( ship_extracted( ship ) )
            continue;

        if ( ship->starsystem )
            lua_trigger_ship_tick( ship );

        if ( ship->autotrack && ship->target0 && ship->classtype <= SATELLITE_SHIP )
        {
            if ( ship->dock_state == DOCK_DOCKED && !ship->dock_lead )
                continue;

            if ( ship->shipstate != SHIP_READY )
                continue;

            if ( ship->target0->cloakstatus == CLOAK_ON )
            {
                echo_to_room( AT_RED, get_room_index( ship->pilotseat ), "Autotrack: Target Lost!\n" );
                ship->target0 = NULL;
                continue;
            }

            if ( !is_facing( ship, ship->target0 ) )
            {
                ship_set_course( ship, &ship->target0->vpos );
                ship->energy -= ship->currspeed / 10;
                echo_to_room( AT_BLUE, get_room_index( ship->pilotseat ),
                              "Autotracking target ... setting new course.\n" );
                ship->shipstate = SHIP_BUSY;
                ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
                echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to turn." );
                snprintf( buf, MSL, "%s turns, altering its present course.", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                save_ship( ship, TRUE );
            }
        }

        /*
            Code for Space Pirates
        */
        if ( autofly( ship ) && ship->starsystem )
        {
            SHIP_DATA* target_ship = NULL, *tnext = NULL;

            // Target and kill pirates, but only if we have more than 25% fuel and more than 50% shields.
            if ( !is_pirate( ship ) && xIS_SET( ship->aflags, AFLAG_PIRATE ) && ship_has_weapons( ship ) &&
                    ship->energy >= ship->maxenergy / 4 && ship->shield >= ship->maxshield / 2 )
            {
                for ( target = ship->starsystem->first_ship; target; target = tnext )
                {
                    tnext = target->next_in_starsystem;

                    if ( target == ship )
                        continue;

                    if ( xIS_SET( ship->flags, SHIP_VONG ) )
                    {
                        // Vong ships will attack any valid non-vong ship.
                        if ( xIS_SET( target->flags, SHIP_VONG ) || xIS_SET( target->flags, SHIP_ENVIROSUIT ) ||
                                is_protected( ship, target, false ) || target->safe_orbital )
                            continue;

                        // Skip any ships piloted by vong, they can presumably tell their friends not to shoot them.
                        if ( target->piloting && xIS_SET( target->piloting->race->flags, RFLAG_VONG ) )
                            continue;
                    }
                    else
                    {
                        if ( !is_pirate( target ) )
                            continue;
                    }

                    if ( vector_distance( &ship->vpos, &target->vpos ) > 2500 && xIS_SET( ship->aflags, AFLAG_SENTINEL ) )
                        continue;

                    // Switch to this target if it's 250 closer than our current target, or we don't have one.
                    if ( !target_ship ||
                            vector_distance( &ship->vpos, &target->vpos ) < vector_distance( &ship->vpos, &target_ship->vpos ) - 250 )
                        target_ship = target;
                }

                // If we have a valid pirate target which is within 500 units, always stick with that target.
                // This helps to avoid angering 4 different pirate ships if we get a swarm coming close at different times.
                if ( ship->target0 && is_pirate( ship->target0 ) && vector_distance( &ship->vpos, &ship->target0->vpos ) < 500 )
                {
                    target_ship = ship->target0;
                }

                if ( target_ship && target_ship != ship->target0 )
                {
                    ship->target0 = NULL;
                    ai_anger( ship, target_ship, FALSE );

                    if ( xIS_SET( ship->flags, SHIP_VONG ) )
                        snprintf( buf, MSL, "The ship's yammosk has decided to eliminate alien vessel %s", target_ship->name );
                    else
                        snprintf( buf, MSL, "Engaging identified pirate vessel %s", target_ship->name );

                    echo_to_ship_windows( AT_YELLOW, ship, buf );
                }
            }

            if ( ship->target0 == ship )
            {
                ship->target0 = NULL;
            }

            /*
                bug("Now checking %s for pirate routine", ship->name);
            */
            if ( is_pirate( ship ) )
            {
                if ( !ship->selfd_armed )
                {
                    ship->selfd_time = ( 45 * 20 );
                    ship->selfd_armed = TRUE;
                    save_ship( ship, TRUE );
                }

                /*
                    Clear target if too far away
                */
                if ( ship->target0 && vector_distance( &ship->target0->vpos, &ship->vpos ) > 5000 )
                {
                    ship->target0 = NULL;
                }

                /*
                    No target? Start pirating the planets.
                */
                int new_speed = ship->realspeed;

                if ( !ship->target0 && ship->starsystem )
                {
                    PLANET_DATA* target_planet = NULL;

                    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
                    {
                        if ( planet->governed_by == NULL )
                            continue;

                        if ( xIS_SET( planet->flags, PLANET_STAR ) )
                            continue;

                        int planet_dist = vector_distance( &ship->vpos, &planet->pos );

                        if ( !target_planet || planet_dist < vector_distance( &ship->vpos, &target_planet->pos ) )
                            target_planet = planet;
                    }

                    if ( target_planet )
                    {
                        int planet_dist = vector_distance( &ship->vpos, &target_planet->pos );

                        if ( planet_dist < 100 )
                        {
                            new_speed = 0;
                            xSET_BIT( target_planet->flags, PLANET_PIRATED );
                        }
                        else if ( planet_dist < 200 )
                            new_speed = UMIN( ship->realspeed, 50 );
                        else
                            new_speed = ship->realspeed;

                        ship_set_course( ship, &target_planet->pos );
                    }
                }

                oldval = ship->currspeed;
                set_ship_speed( ship, new_speed );
                if ( ship->currspeed != oldval ) save_ship( ship, TRUE );
            }
        }

        /*
            If a CAPITAL SHIP or a PLATFORM is -NOT FIGHTING- And is in a safe sector.
            it can automatically reload missiles/rockets/and torpedoes.
        */
        if ( auto_refuel( ship ) )
        {
            PLANET_DATA* refuel_planet = NULL;

            if ( ship->starsystem )
            {
                for ( refuel_planet = ship->starsystem->first_planet; refuel_planet; refuel_planet = refuel_planet->next_in_system )
                {
                    if ( vector_distance( &ship->vpos, &refuel_planet->pos ) <= 2000 )
                        break;
                }
            }

            CLAN_DATA* ship_clan = ship->clan;
            bool near_planet = refuel_planet != NULL;
            bool orbiting_clan_planet = ship_clan && refuel_planet &&
                                        vector_distance( &ship->vpos, &refuel_planet->pos ) < 20 &&
                                        refuel_planet->governed_by == ship_clan;
            bool near_enemy_planet = ship_clan && refuel_planet && enemy_clan( ship_clan, refuel_planet->governed_by );
            bool manned = is_ship_manned( ship );
            // If we're over a planet and the planet is either capturable by anyone or has <10 military, it
            // won't protect the orbital anymore.
            bool planet_capturable = false;
            bool planet_low_military = false;

            if ( refuel_planet && orbiting_clan_planet && is_ufg( refuel_planet ) )
            {
                for ( CLAN_DATA* clan = first_clan; clan; clan = clan->next )
                    if ( can_capture( refuel_planet, clan, NULL, true ) )
                        planet_capturable = true;

                if ( refuel_planet->governed_by && get_planet_mil_presence( refuel_planet, refuel_planet->governed_by ) < 10 )
                    planet_low_military = true;
            }

            if ( !orbiting_clan_planet || manned || planet_capturable || planet_low_military )
            {
                // If it's no longer in orbit for some reason or is now manned, clear safe orbital status
                if ( ship->safe_orbital != FALSE )
                {
                    ship->safe_orbital = FALSE;
                    save_ship( ship, TRUE );
                }
            }
            else if ( orbiting_clan_planet && !manned && !ship_is_fighting( ship ) )
            {
                // If it's not marked safe, has nobody onboard, and isn't fighting, set it as a safe orbital.
                if ( ship->safe_orbital != TRUE )
                {
                    ship->safe_orbital = TRUE;
                    save_ship( ship, TRUE );
                }
            }

            // Do refuel/repair if it's a safe unmanned orbital over a friendly planet, or if it's manned but not fighting.
            if ( ( !ship_is_fighting( ship ) || ship->safe_orbital ) && near_planet && !near_enemy_planet )
            {
                if ( orbiting_clan_planet )
                {
                    // In orbit of friendly planets, we get full fuel, repairs, and projectiles.
                    if ( ship->energy < ship->maxenergy )
                    {
                        ship->energy = URANGE( ship->energy, ship->energy + 1000, ship->maxenergy );
                        save_ship( ship, TRUE );
                    }

                    if ( ship->hull < ship->maxhull )
                    {
                        ship->hull = URANGE( 0, ship->hull + 25, ship->maxhull );
                        save_ship( ship, TRUE );
                    }

                    if ( ship->missiles < ship->maxmissiles )
                    {
                        ship->missiles++;
                        save_ship( ship, TRUE );
                    }

                    if ( ship->torpedoes < ship->maxtorpedoes )
                    {
                        ship->torpedoes++;
                        save_ship( ship, TRUE );
                    }

                    if ( ship->chaff < ship->maxchaff )
                    {
                        ship->chaff++;
                        save_ship( ship, TRUE );
                    }

                    if ( ship->rockets < ship->maxrockets )
                    {
                        ship->rockets++;
                        save_ship( ship, TRUE );
                    }

                    if ( ship->pulses < ship->maxpulses )
                    {
                        ship->pulses++;
                        save_ship( ship, TRUE );
                    }
                }
                else
                {
                    // Near neutral planets, we get half fuel and no missiles/hull.
                    if ( ship->energy < ship->maxenergy )
                    {
                        ship->energy = URANGE( ship->energy, ship->energy + 500, ship->maxenergy );
                        save_ship( ship, TRUE );
                    }
                }
            }
            else
            {
                // Not near a planet, we still get some extra ambient energy gain.
                // This is important to allow people to have a chance to get away from pursuing fleets.
                oldval = ship->energy;
                ship->energy = URANGE( ship->energy, ship->energy + 40, ship->maxenergy );
                if ( ship->energy != oldval )
                    save_ship( ship, TRUE );
            }
        }

        firehose_write_ship( ship );
    }

    debug( "update_space: done" );
    DISPOSE( all_ships );
    return;
}

void exit_hyperspace( SHIP_DATA* ship )
{
    char buf[MSL];

    int sys_x = sys_coord_from_galactic_coords(ship->hyper_currentpos.x);
    int sys_y = sys_coord_from_galactic_coords(ship->hyper_currentpos.y);

    // If our jump landed us at a hidden system we don't have access to or one where we don't fit,
    // move to a neighboring sector.
    while (1) {
        SPACE_DATA* exit_check = starsystem_from_coords(sys_x, sys_y);
        if ( exit_check )
        {
            if ( !ship_knows_system(ship, exit_check) && !xIS_SET( ship->flags, SHIP_MATCHVECTOR ) )
            {
                sys_x--;
                continue;
            }
            else if ( ( exit_check->nocaps > 0 && ship->classtype >= FRIGATE_SHIP )
                      || exit_check->maxshipclass < ship->classtype )
            {
                echo_to_ship_windows( AT_RED, ship, "Debris field detected at destination. Engaging ship safety protocols. Exiting hyperspace." );
                sys_x--;
                continue;
            }
        }
        break;
    }

    xREMOVE_BIT( ship->flags, SHIP_MATCHVECTOR ); // Clear it off here. :)   Orion 2008
    ship->hyperlock = FALSE;

    SPACE_DATA* starsystem = starsystem_from_coords( sys_x, sys_y );
    if ( !starsystem )
        starsystem = make_vsystem(sys_x, sys_y, true);
    if ( starsystem->virtualsys )
        starsystem->timer = 30;

    ship_to_starsystem(ship, starsystem);
    ship->vpos.x = remainder(ship->hyper_currentpos.x, 100000.0);
    if ( ship->vpos.x > 50000 ) // Make the math work with negative coords within a system
        ship->vpos.x -= 100000;
    ship->vpos.y = remainder(ship->hyper_currentpos.y, 100000.0);
    if ( ship->vpos.y > 50000 )
        ship->vpos.y -= 100000;
    ship->vpos.z = remainder(ship->hyper_currentpos.z, 100000.0);
    if ( ship->vpos.z > 50000 )
        ship->vpos.z -= 100000;    

    awaken_ship( ship, FALSE );
    echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Hyperjump complete." );
    ship->hyperbonus = 0;
    ship->prev_starsystem = NULL;
    echo_to_ship_main( AT_YELLOW, ship, "The ship lurches slightly as it comes out of hyperspace." );
    snprintf( buf, MSL, "%s enters the starsystem, coming out of its hyperjump at %.0f %.0f %.0f", ship->name, ship->vpos.x,
                ship->vpos.y, ship->vpos.z );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
    ship->shipstate = SHIP_READY;

    if ( xIS_SET( ship->flags, SHIP_ONEHYPER ) )
    {
        ship->hyperspeed = 0;
        ship->currspeed = 0;
        ship->realspeed = 0;
    }

    if ( ship->classtype == BATTLESTATION_SHIP )
    {
        /*
            Temporarily disable battlestations. Fair game =)
        */
        echo_to_ship_main( AT_YELLOW, ship, "[WARNING]: Ship systems are recalibrating. Please stand by." );
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        // Set weapon charge high enough that it'll take 30 seconds before anything can be fired
        ship->laser_charge = ship->lasers * 4.5;
        ship->turbolaser_charge = ship->turbolasers * 1.5;
        ship->ion_charge = ship->ion * 1.5;
    }

    save_ship( ship, true );
    lua_trigger_ship_hyper_exit( ship, ship->starsystem );
}

SPACE_DATA* starsystem_from_id( int id )
{
    SPACE_DATA* starsystem;

    for ( starsystem = first_starsystem; starsystem; starsystem = starsystem->next )
        if ( starsystem->id == id )
            break;

    return starsystem;
}

/*
    Get pointer to space structure from starsystem name.
*/
SPACE_DATA* starsystem_from_name( char* name )
{
    SPACE_DATA* starsystem;

    for ( starsystem = first_starsystem; starsystem; starsystem = starsystem->next )
        if ( !str_cmp( name, starsystem->name ) )
            return starsystem;

    for ( starsystem = first_starsystem; starsystem; starsystem = starsystem->next )
        if ( !str_prefix( name, starsystem->name ) )
            return starsystem;

    return NULL;
}

/*
    Get pointer to space structure from the dock vnun.
*/
SPACE_DATA* starsystem_from_vnum( int vnum )
{
    ROOM_INDEX_DATA* room = get_room_index( vnum );

    if ( !room )
        return NULL;

    PLANET_DATA* planet = get_planet_from_room( room );

    if ( planet )
        return planet->starsystem;

    // If the current room is in a ship, get the ship's system
    SHIP_DATA* ship = get_ship_from_room( room );

    if ( ship )
    {
        if ( ship->in_room )
            // A docked ship should get its system from where it's docked
            return starsystem_from_vnum( ship->in_room->vnum );
        else
            return ship->starsystem;
    }

    return NULL;
}


/*
    Save a starsystem's data to its data file
*/
int save_starsystem( SPACE_DATA* starsystem, bool queue )
{
    if ( !starsystem )
        return false;

    if ( queue && starsystem->id > 0 && sysdata.save_queues )
    {
        starsystem->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    starsystem->save_queued = FALSE;
    return upsert_sql_fieldmap_row("starsystems", starsystem, space_fields, NO_FLAG);
}

bool starsystem_is_empty( SPACE_DATA* starsystem )
{
    if ( !starsystem )
        return FALSE;

    if ( starsystem->first_fcargo )
        return FALSE;

    if ( starsystem->first_mine )
        return FALSE;

    if ( starsystem->first_missile )
        return FALSE;

    if ( starsystem->first_planet )
        return FALSE;

    if ( starsystem->first_ship )
        return FALSE;

    if ( starsystem->first_tractor )
        return FALSE;

    return TRUE;
}

int extract_starsystem( SPACE_DATA* starsystem )
{
    SHIP_DATA* ship = NULL, *next_ship = NULL;
    bool on_drydock = FALSE;
    char buf[MSL];
    strlcpy( buf, "", MSL );

    if ( !starsystem )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( !starsystem_is_empty( starsystem ) )
    {
        bug( "%s: trying to extract non-empty starsystem %s at %d, %d", FUNC, starsystem->name ? starsystem->name : "(null)", starsystem->xpos, starsystem->ypos );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    for ( ship = first_ship; ship; ship = next_ship )
    {
        next_ship = ship->next;

        if ( !next_ship && !on_drydock )
        {
            next_ship = first_drydock;
            on_drydock = TRUE;
        }

        if ( ship->starsystem == starsystem && !xIS_SET( ship->flags, SHIP_DRYDOCK ) )
        {
            snprintf( buf, MSL, "%s: ship %s thinks it's in starsystem %d, %d -- but it's not in the linked list. Moving to the Immortal Shipyard.", FUNC, ship->name, starsystem->xpos, starsystem->ypos );
            bug( buf );
            write_to_log( FUNC, buf, sysdata.log_level, 0, TRUE );
            ship->starsystem = NULL;

            if ( ship->starsystem_xy )
                DISPOSE( ship->starsystem_xy );

            ship_to_room( ship, ROOM_LIMBO_SHIPYARD );
        }
        else if ( ship->starsystem == starsystem )
        {
            ship->starsystem = NULL;
            if ( ship->starsystem_xy )
                DISPOSE( ship->starsystem_xy );
        }

        if ( ship->prev_starsystem == starsystem )
        {
            ship->prev_starsystem = NULL;
            if ( ship->prev_starsystem_xy )
                DISPOSE( ship->prev_starsystem_xy );
        }

        if ( ship->last_landed == starsystem )
            ship->last_landed = NULL;
    }

    UNLINK( starsystem, first_starsystem, last_starsystem, next, prev );
    if ( starsystem->id > 0 )
        delete_sql_row_by_id( DB_TABLE_STARSYSTEMS, starsystem->id );

    FREE_STRUCT( starsystem, space_fields );
    return E_LOTJ_SUCCESS;
}

int load_starsystem_sql( const PGresult* qresult, int row )
{
    SPACE_DATA* starsystem = NULL;
    CREATE( starsystem, SPACE_DATA, 1 );
    int rval = 0;

    if ( ( rval = fieldmap_postgres_row( qresult, row, starsystem, space_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( starsystem, space_fields );
        return rval;
    }

    LINK( starsystem, first_starsystem, last_starsystem, next, prev );
    return E_LOTJ_SUCCESS;
}

CMDF do_setstarsystem( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    SPACE_DATA* starsystem;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( arg2[0] == '\0' || arg1[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Csetstarsystem <&wstarsystem&C> <&wfield&C> <&wvalues&C>&w" );
        ch_println( ch, "\n&zField being one of:" );
        ch_println( ch, "&Cname filename xpos ypos hidden nocaps notpublic nopvp nohyper&w" );
        send_to_char( "&Cmaxclass delete&w", ch );
        send_to_char( "", ch );
        return;
    }

    starsystem = starsystem_from_name( arg1 );

    if ( !starsystem )
    {
        ch_println( ch, "No such starsystem." );
        return;
    }

    if ( !str_cmp( arg2, "hidden" ) )
    {
        starsystem->hidden = !starsystem->hidden;

        if ( starsystem->hidden )
            ch_println( ch, "Hidden flag set." );
        else
            ch_println( ch, "Hidden flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "xpos" ) )
    {
        starsystem->xpos = atoi( argument );
        ch_println( ch, "Done." );
        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "ypos" ) )
    {
        starsystem->ypos = atoi( argument );
        ch_println( ch, "Done." );
        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "name" ) )
    {
        SET_STRING( starsystem->name, argument );
        ch_println( ch, "Done." );
        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "nocaps" ) )
    {
        starsystem->nocaps = !starsystem->nocaps;

        if ( starsystem->nocaps )
            ch_println( ch, "Nocaps flag set." );
        else
            ch_println( ch, "Nocaps flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "notpublic" ) )
    {
        starsystem->notpublic = !starsystem->notpublic;

        if ( starsystem->notpublic )
            ch_println( ch, "Notpublic flag set." );
        else
            ch_println( ch, "Notpublic flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "nopvp" ) )
    {
        starsystem->nopvp = !starsystem->nopvp;

        if ( starsystem->nopvp )
            ch_println( ch, "Nopvp flag set." );
        else
            ch_println( ch, "Nopvp flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "blackout" ) )
    {
        starsystem->blackout = !starsystem->blackout;

        if ( starsystem->blackout )
            ch_println( ch, "Blackout flag set." );
        else
            ch_println( ch, "Blackout flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "nohyper" ) )
    {
        starsystem->nohyper = !starsystem->nohyper;

        if ( starsystem->nohyper )
            ch_println( ch, "Nohyper flag set." );
        else
            ch_println( ch, "Nohyper flag cleared." );

        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "maxshipclass" ) )
    {
        int maxshipclass = atoi( argument );

        if ( maxshipclass < FIGHTER_SHIP || maxshipclass > SATELLITE_SHIP )
        {
            ch_println( ch, "&RInvalid ship class. Range is %d (fighter) to %d (satellite)", FIGHTER_SHIP, SATELLITE_SHIP );
            return;
        }

        starsystem->maxshipclass = maxshipclass;
        ch_println( ch, "Done." );
        save_starsystem( starsystem, true );
        return;
    }

    if ( !str_cmp( arg2, "delete" ) )
    {
        if ( starsystem->first_fcargo || starsystem->first_mine || starsystem->first_missile
                || starsystem->first_planet || starsystem->first_ship || starsystem->first_tractor )
        {
            ch_println( ch, "&RThat system is not empty." );
            return;
        }

        for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
        {
            if ( ship->last_landed == starsystem )
            {
                ship->last_landed = NULL;
                save_ship( ship, true );
            }
        }

        extract_starsystem( starsystem );
        ch_println( ch, "Done." );
        return;
    }

    do_setstarsystem( ch, "" );
    return;
}

