CMDF do_makestarsystem( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL];
    SPACE_DATA* starsystem = NULL;

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );


    if ( NULLSTR( arg ) || NULLSTR( arg2 ) || NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cmakestarsystem <&wxpos&C> <&wypos&C> <&wstarsystem name&C>" );
        return;
    }

    int xpos = atoi( arg );
    int ypos = atoi( arg2 );

    if ( xpos < -9999 || xpos > 9999 || ypos < -9999 || ypos > 9999 )
    {
        ch_println( ch, "&wInvalid coordinates." );
        return;
    }

    if ( ( starsystem = starsystem_from_coords( xpos, ypos ) ) != NULL )
    {
        ch_println( ch, "&RAnother starsystem already exists at those coordinates." );
        bug("System: %s %d %d", starsystem->name, starsystem->xpos, starsystem->ypos );
        return;
    }

    CREATE( starsystem, SPACE_DATA, 1 );
    LINK( starsystem, first_starsystem, last_starsystem, next, prev );
    SET_STRING( starsystem->name, argument );
    starsystem->maxshipclass = SATELLITE_SHIP;
    starsystem->hidden = TRUE; //default to hidden
    starsystem->xpos = xpos;
    starsystem->ypos = ypos;
    argument = one_argument( argument, arg );
    save_starsystem( starsystem, true );
    ch_println( ch, "Done." );
    return;
}

CMDF do_starsystems( CHAR_DATA* ch, char* argument )
{
    static SPACE_DATA** starsystems;
    int count = 0;
    OBJ_DATA* obj = has_datapad( ch );
    LINK_TO_ARRAY( first_starsystem, SPACE_DATA, next, starsystems );
    SORT_ARRAY( starsystems, SPACE_DATA, alphabetize, name );

    if ( !obj && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You must hold a datapad to do this." );
        return;
    }

    if ( IS_IMMORTAL( ch ) && !NULLSTR( argument ) && str_cmp( argument, "all" ) &&
    str_cmp( argument, "nohyper" ) && str_cmp( argument, "noshow" ) && str_cmp( argument, "hidden" ) && str_cmp( argument, "map" ) && str_cmp( argument, "vsys" ) )
    {   
        ch_println( ch, "&zSyntax: &Cstarsystems" );
        ch_println( ch, "&z        &Cstarsystems <&wall&C/&whidden&C/&wvsys&C>" );
        return;
    }

    int xsize = 0, ysize = 0, xval = 0, yval = 0;

    for( int i = 0; starsystems[i]; i++ )
    {
        if ( str_cmp( argument, "vsys" ) && starsystems[i]->virtualsys )
            continue;

        if ( starsystems[i]->nohyper )
        {
            if ( !IS_IMMORTAL( ch ) || NULLSTR( argument ) || ( str_cmp( argument, "nohyper" ) && str_cmp( argument, "all" ) ) )
                continue;                
        }
        else if ( starsystems[i]->hidden > 0 || starsystems[i]->notpublic > 0 )
        {
            if ( !IS_IMMORTAL( ch ) || NULLSTR( argument ) || ( str_cmp( argument, "map" ) && str_cmp( argument, "noshow" ) && str_cmp( argument, "hidden" ) && str_cmp( argument, "all" ) ) )
                continue;
        }
        else if ( IS_IMMORTAL( ch ) && !NULLSTR( argument ) && ( str_cmp( argument, "map" ) && str_cmp( argument, "all" ) ) )
            continue;

        xval = numPlaces( starsystems[i]->xpos );
        yval = numPlaces( starsystems[i]->ypos );
        if ( starsystems[i]->xpos < 0 )
            xval++;
        if ( starsystems[i]->ypos < 0 )
            yval++;
        xsize = UMAX( xsize, xval );
        ysize = UMAX( ysize, yval );
    }

    ch_println( ch, "&zListing known starsystems:" );
    for( int i = 0; starsystems[i]; i++ )
    {
        if ( str_cmp( argument, "vsys" ) && starsystems[i]->virtualsys )
            continue;

        set_char_color( AT_NOTE, ch );

        if ( starsystems[i]->nocaps > 0 )
            set_char_color( AT_ORANGE, ch );

        if ( starsystems[i]->nohyper )
        {
            if ( !IS_IMMORTAL( ch ) || NULLSTR( argument ) || ( str_cmp( argument, "nohyper" ) && str_cmp( argument, "all" ) ) )
                continue;
            else
                set_char_color( AT_YELLOW, ch );
        }
        else if ( starsystems[i]->hidden > 0 || starsystems[i]->notpublic > 0 )
        {
            if ( !IS_IMMORTAL( ch ) || NULLSTR( argument ) || ( str_cmp( argument, "map" ) && str_cmp( argument, "noshow" ) && str_cmp( argument, "hidden" ) && str_cmp( argument, "all" ) ) )
                continue;
            else
                set_char_color( AT_RED, ch );
        }
        else if ( IS_IMMORTAL( ch ) && !NULLSTR( argument ) && ( str_cmp( argument, "map" ) && str_cmp( argument, "all" ) ) )
            continue;

        ch_println( ch, "%-24s &w&z( &W%*d, %-*d &z)", starsystems[i]->name, xsize, starsystems[i]->xpos, ysize, starsystems[i]->ypos );
        count++;
    }

    ch_println( ch, "\n&zDisplayed &C%d &zstarsystems.", count );
    if ( IS_IMMORTAL( ch ) )
        ch_println( ch, "&zOptional syntax: &Cstarsystems <&wall&C/&whidden&C>" );

    return;
}

void awaken_ship( SHIP_DATA* ship, bool NC )
{
    ROOM_INDEX_DATA* room = NULL;
    TURRET_DATA* turret = NULL;
    CHAR_DATA* vic = NULL;
    bool nEcho = FALSE;

    if ( !ship )
        return;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( NC )
        {
            nEcho = FALSE;

            if ( room->vnum == ship->cockpit || room->vnum == ship->navseat || room->vnum == ship->pilotseat || room->vnum == ship->coseat
                    || room->vnum == ship->gunseat || room->vnum == ship->engineroom )
                nEcho = TRUE;

            for ( turret = ship->first_turret; turret; turret = turret->next )
            {
                if ( !turret || turret == NULL )
                    break;

                if ( turret->room == NULL )
                    continue;

                if ( turret->room == room )
                    nEcho = TRUE;
            }

            if ( nEcho )
                continue;
        }

        for ( vic = room->first_person; vic; vic = vic->next_in_room )
        {
            if ( IS_AWAKE( vic ) )
                continue;

            if ( vic->hit <= 0 )
                continue;

            if ( IS_AFFECTED( vic, AFF_SLEEP ) )
                continue;

            do_wake( vic, "" );
        }
    }

    return;
}

void echo_to_shipNC( int color, SHIP_DATA* ship, const char* argument )
{
    bool nEcho = FALSE;
    TURRET_DATA* turret = NULL;
    ROOM_INDEX_DATA* room = NULL;

    if ( !ship || ship->occupants == 0 )
        return;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( !room->first_person )
            continue;

        if ( room->vnum != ship->cockpit && room->vnum != ship->navseat && room->vnum != ship->pilotseat && room->vnum != ship->coseat
                && room->vnum != ship->gunseat && room->vnum != ship->engineroom )
        {
            nEcho = FALSE;

            for ( turret = ship->first_turret; turret; turret = turret->next )
            {
                if ( !turret || turret == NULL )
                    break;

                if ( turret->room == NULL )
                    continue;

                if ( turret->room == room )
                    nEcho = TRUE;
            }

            if ( !nEcho )
                echo_to_room_dnr( color, room, argument );
        }
    }

    return;
}

void sound_to_ship( SHIP_DATA* ship, char* argument )
{
    ROOM_INDEX_DATA* room = NULL;
