void echo_to_system_noqueue_filter( int color, SHIP_DATA* ship, const char* argument, SHIP_DATA* ignore, bool ( *filter )( CHAR_DATA* ) )
{
    SHIP_DATA* target;
    int cnt = 0;

    if ( !ship->starsystem )
        return;

    for ( target = ship->starsystem->first_ship; target; target = target->next_in_starsystem )
    {
        if ( ++cnt > 9999 )
        {
            bug( "echo_to_system: infinite loop aborted." );
            break;
        }

        if ( target != NULL && ignore != NULL )
        {
            if ( target != ship && target != ignore )
            {
                echo_to_ship_windows_filter( color, target, argument, filter );
            }
        }
        else if ( target != NULL && ignore == NULL )
        {
            if ( target != ship )
            {
                echo_to_ship_windows_filter( color, target, argument, filter );
            }
        }
        else
            return;
    }
}

