long int get_ship_value( SHIP_DATA* ship )
{
    long int price;

    if ( ship == NULL )
        return -1;

    price = 2000;

    if ( ship->classtype == FIGHTER_SHIP )
        price = 0;

    if ( ship->classtype == TRANSPORT_SHIP )
        price = 40000;

    if ( ship->classtype == FREIGHTER_SHIP )
        price = 80000;

    if ( ship->classtype == GUNBOAT_SHIP )
        price = 120000;

    if ( ship->classtype == CORVETTE_SHIP )
        price = 250000;

    if ( ship->classtype == FRIGATE_SHIP )
        price = 400000;

    if ( ship->classtype == CRUISER_SHIP )
        price = 600000;

    if ( ship->classtype == BATTLESHIP_SHIP )
        price = 450000;

    if ( ship->classtype == BATTLESTATION_SHIP )
        price = 2000000;

    if ( ship->classtype == PLATFORM_SHIP )
