}

/*
    Author:   Sanshiro
    Spec:     Takes a string < My name is 'lola' > and returns whatever is inside quotes
    Args:     char * input -> string we want to isolate the single quotes from
            char * output -> caller function should allocate the space to store the choped
            string. This is a pointer to that space.
    Returns:  Pointer to the chopped string.

*/
char* isolateSingleQuoteContents( char* const input, char* outPut )
{
    //i and y are indexes for the two for loops
    //begin and end is where the first and last ' are found
    //quoteFound 0 when no ' is encountered and 1 after the first ' is encountered
    int y, i, begin, end, quoteFound;
    //Temp pointer to iterate through the input string
    char* point;

    //Find where the ' are in the string.
    for ( begin = end = quoteFound = i = 0, point = input; *point != '\0'; point++, i++ )
    {
        if ( *point == 047 && quoteFound == 1 )
        {
            quoteFound = 0;
            end = i;
        }
        else if ( *point == 047 && quoteFound == 0 )
        {
            quoteFound = 1;
            begin = i;
        }
    }

    //If no ' are found or if there's just one, returnpointer should be a null string
    //else, copy to the returnpointer from begin+1 to end-1!
    //Also if someone manages to have three ' i >end and for will never happen.
    if ( end == 0 )
        outPut[0] = '\0';
    else
    {
        for ( y = 0, i = begin + 1, y = 0; i < end; y++, i++ )
            outPut[y] = input[i];

        outPut[y] = '\0';
    }

    return outPut;
}

/*
    Author: Sanshiro
    Spec:       Just like getship, only specialised for locateship to look in '' for shipnames.
    Args:       Ship name
    Returns:    Pointer to ship data.
    Gathorn Update: Changing it so there is no "partial" name search. You must know the full name of the ship.

*/
SHIP_DATA* get_ship_by_quotes( char* name )
{
    SHIP_DATA* ship = NULL;
    //Local space to hold the chopped string.
    char chopped[MIL];

    //This for loop searches for the whole ship name:
    //e.g. A Deep Space Station
    for ( ship = first_ship; ship; ship = ship->next )
        if ( !str_cmp( name, ship->name ) )
            return ship;

    //This for loop searches for the ship name.
    for ( ship = first_ship; ship; ship = ship->next )
        if ( !str_cmp( name, isolateSingleQuoteContents( ship->name, chopped ) ) )
            return ship;

    return NULL;
}

