SHIP_DATA* get_battlegroup_member( SHIP_DATA* leader, char* name, bool same_system )
{
    SHIP_DATA* ship = NULL;
    int cnt = 0, val = 0;
    char buf[128];

    if ( !leader || ship_extracted( leader ) )
        return NULL;

    if ( is_number( name ) )
    {
        val = atoi( name );

        if ( val <= 0 )
            return NULL;

        for ( ship = leader->first_in_bg; ship; ship = ship->next_in_bg )
        {
            if ( ship == leader )
                continue;

            if ( same_system && ship->starsystem != leader->starsystem )
                continue;

            ++cnt;

            if ( cnt != val )
                continue;

            return ship;
        }

        return NULL;
    }

    for ( ship = leader->first_in_bg; ship; ship = ship->next_in_bg )
    {
        get_last_arg( ship->name, buf );

        if ( !str_cmp( name, buf ) && ship->leader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;
    }

    for ( ship = leader->first_in_bg; ship; ship = ship->next_in_bg )
    {
        get_last_arg( ship->name, buf );

        if ( !str_prefix( name, buf ) && ship->leader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;
    }

    for ( ship = leader->first_in_bg; ship; ship = ship->next_in_bg )
        if ( nifty_is_name_prefix( name, ship->name ) && ship->leader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;

    return NULL;
}

SHIP_DATA* get_squadron_member( SHIP_DATA* leader, char* name, bool same_system )
{
    char buf[128];

    if ( !leader || ship_extracted( leader ) )
        return NULL;

    SHIP_DATA* ship = get_ship_exact( name );

    if ( ship && ship->squadleader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
        return ship;

    // This loop looks for exact matches on the ship's name (the part in quotes)

    for ( ship = leader->first_in_squad; ship; ship = ship->next_in_squad )
    {
        get_last_arg( ship->name, buf );

        if ( !str_cmp( name, buf ) && ship->squadleader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;
    }

    for ( ship = leader->first_in_squad; ship; ship = ship->next_in_squad )
    {
        get_last_arg( ship->name, buf );

        if ( !str_prefix( name, buf ) && ship->squadleader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;
    }

    //This for loop searches for partial match.
    for ( ship = leader->first_in_squad; ship; ship = ship->next_in_squad )
        if ( nifty_is_name_prefix( name, ship->name ) && ship->squadleader == leader && ( !same_system || ship->starsystem == leader->starsystem ) )
            return ship;

    return NULL;
}

