void get_ship_name( SHIP_DATA* ship, char* result )
{
    result[0] = '\0';

    if ( !ship )
    {
        bug( "%s: null ship", FUNC );
        return;
    }

    if ( NULLSTR( ship->name ) )
    {
        bug("%s: null ship name, ID %d", FUNC, ship->id );
        return;
    }

    char rev_buf[100];
    char* write_ptr = rev_buf;
    bool in_name = false;

    for ( int i = strlen( ship->name ) - 1; i >= 0; i-- )
    {
        if ( ship->name[i] == '\'' )
        {
            if ( in_name )
            {
                write_ptr = result;

                for ( int r = strlen( rev_buf ) - 1; r >= 0; r-- )
                {
                    *write_ptr = rev_buf[r];
                    write_ptr++;
                }

                *write_ptr = '\0';
                return;
            }

            in_name = true;
        }
        else if ( in_name )
        {
            *write_ptr = ship->name[i];
            write_ptr++;
            *write_ptr = '\0';
        }
    }

    // If we never found a valid name, just return the entire ship name.
    // That means ships like "The Death Star" will use "The Death Star" as their name, and have no basename.
    strlcpy( result, ship->name, 100 );
    return;
}

void get_ship_basename( SHIP_DATA* ship, char* result )
{
    result[0] = '\0';

    if ( !ship )
    {
        bug( "%s: null ship", FUNC );
        return;
    }

    if ( NULLSTR( ship->name ) )
    {
        bug("%s: null ship name, ID %d", FUNC, ship->id );
        return;
    }

    char shipname[100];
    get_ship_name( ship, shipname );

    // If the ship has no valid name chunk, return empty string as the basename.
    // Ships like "The Death Star" will use "The Death Star" as their name, and have no basename.
    if ( strlen( shipname ) == strlen( ship->name ) )
        return;

    int full_len = strlen( ship->name );
    int name_len = strlen( shipname );
    char* write_ptr = result;

    for ( int i = 0; i < full_len - ( name_len + 3 ); i++ )
    {
        *write_ptr = ship->name[i];
        write_ptr++;
    }

    *write_ptr = '\0';
    return;
}

int save_ship( SHIP_DATA* ship, bool queue )
{
    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship->extracted )
        return E_LOTJ_NOTHING_TO_DO;

    if ( queue && ship->id > 0 && sysdata.save_queues )
    {
        ship->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    if ( ship->starsystem )
    {
        if ( !ship->starsystem_xy )
            CREATE( ship->starsystem_xy, XY_DATA, 1 );
        ship->starsystem_xy->xval = ship->starsystem->xpos;
        ship->starsystem_xy->yval = ship->starsystem->ypos;
    }

    if ( ship->prev_starsystem )
    {
        if ( !ship->prev_starsystem_xy )
            CREATE( ship->prev_starsystem_xy, XY_DATA, 1 );
        ship->prev_starsystem_xy->xval = ship->prev_starsystem->xpos;
        ship->prev_starsystem_xy->yval = ship->prev_starsystem->ypos;
    }

    ship->_leader_uid = ship->leader ? ship->leader->id : 0;
    ship->_squadleader_uid = ship->squadleader ? ship->squadleader->id : 0;

    ship->save_queued = FALSE;
    int result = upsert_sql_fieldmap_row(DB_TABLE_SHIPS, ship, ship_fields, NO_FLAG);

    if ( ship->starsystem_xy )
    {
        FREE_STRUCT_NORET( ship->starsystem_xy, xy_fields );
    }

    if ( ship->prev_starsystem_xy )
    {
        FREE_STRUCT_NORET( ship->prev_starsystem_xy, xy_fields );
    }

    return result;
}

/*
    Load in all the ship files.
*/

bool finalize_load_ship( SHIP_DATA* ship )
{
    ROOM_INDEX_DATA* pRoomIndex = NULL;

    if ( !ship )
    {
        bug("%s: NULL ship", FUNC );
        return FALSE;
    }

    ship->clan = !NULLSTR( ship->shipowner ) ? get_clan( ship->shipowner ) : NULL;

    if ( ship->starsystem_xy != NULL )
    {
        SPACE_DATA* system = starsystem_from_coords( ship->starsystem_xy->xval, ship->starsystem_xy->yval );
        if ( system == NULL )
            system = make_vsystem( ship->starsystem_xy->xval, ship->starsystem_xy->yval, false );
        ship_to_starsystem( ship, system );
        FREE_STRUCT_NORET( ship->starsystem_xy, xy_fields );
    }

    if ( ship->prev_starsystem_xy != NULL )
    {
        SPACE_DATA* system = starsystem_from_coords( ship->prev_starsystem_xy->xval, ship->prev_starsystem_xy->yval );
        ship->prev_starsystem = system;
        FREE_STRUCT_NORET( ship->prev_starsystem_xy, xy_fields );
    }

    for ( int vnum = ship->firstroom; vnum <= ship->lastroom; vnum++ )
    {
        pRoomIndex = get_room_index( vnum );

        if ( pRoomIndex )
            LINK( pRoomIndex, ship->first_room, ship->last_room, next_in_range, prev_in_range );
    }

    if ( xIS_SET( ship->flags, SHIP_DRYDOCK ) )
    {
        LINK( ship, first_drydock, last_drydock, next, prev );
        ship->location = 0;
        ship->lastdoc = 0;
        ship->shipyard = 0;
        if ( ship->lastroom == 0 )
        {
            if ( ship->template && ship->template != blank_shipimage && ship->template->first_room && ship->template->last_room )
                ship->lastroom = ship->firstroom + ( ship->template->last_room->vnum - ship->template->first_room->vnum );
            else
            {
                bug( "%s: ship %s has unfixable room range. Manually reconstructing...", FUNC, ship->name ? ship->name : "(null)" );
                ship->lastroom = ship->firstroom;
                ship->lastroom = UMAX( ship->lastroom, ship->cockpit );
                ship->lastroom = UMAX( ship->lastroom, ship->pilotseat );
                ship->lastroom = UMAX( ship->lastroom, ship->coseat );
                ship->lastroom = UMAX( ship->lastroom, ship->gunseat );
                ship->lastroom = UMAX( ship->lastroom, ship->engineroom );
                for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
                    if ( turret->room )
                        ship->lastroom = UMAX( ship->lastroom, turret->room->vnum );

                for ( HANGAR_DATA* hangar = ship->first_hangar; hangar; hangar = hangar->next )
                    if ( hangar->room )
                        ship->lastroom = UMAX( ship->lastroom, hangar->room->vnum );

                for ( ESCAPE_DATA* escape = ship->first_escape; escape; escape = escape->next )
                    if ( escape->room )
                        ship->lastroom = UMAX( ship->lastroom, escape->room->vnum );
            }

            save_ship( ship, true );
        }

        if ( xIS_SET( ship->flags, SHIP_SPAWNED ) || xIS_SET( ship->flags, SHIP_OBJECT ) || NULLSTR( ship->shipowner ) || stristr( ship->shipowner, "spacemob" ) )
        {
            delete_ship( ship );
            return TRUE;
        }
    }
    else
    {
        LINK( ship, first_ship, last_ship, next, prev );
        hashset_add( valid_ships, ship );
    }

    for ( CARGO_DATA* cargo = ship->first_cargo; cargo; cargo = cargo->next )
        cargo->ship = ship;

    ship->target_v = NULL;

    if ( !xIS_SET( ship->flags, SHIP_DRYDOCK ) && ( ship->shipstate == SHIP_DOCKED || ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) && ( pRoomIndex = get_room_index( ship->lastdoc ) ) != NULL && ship->starsystem == NULL )
    {
        LINK( ship, pRoomIndex->first_ship, pRoomIndex->last_ship, next_in_room, prev_in_room );
        ship->in_room = pRoomIndex;
        ship->location = ship->lastdoc;
    }

    if ( !xIS_SET( ship->flags, SHIP_DRYDOCK ) )
        update_ship_room_references( ship );

    if ( !ship->template )
        ship->template = blank_shipimage;

    return TRUE;    
}

void finalize_load_ships( void )
{
    SHIP_DATA* leader = NULL;

    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( ship->_squadleader_uid > 0 && !ship->squadleader )
        {
            leader = ship_from_id( ship->_squadleader_uid );
            if ( !leader || xIS_SET( leader->flags, SHIP_DRYDOCK )  )
                remove_from_squad( ship );
            else
                add_to_squad( ship, leader );
        }

        if ( ship->_leader_uid > 0 && !ship->leader )
        {
            leader = ship_from_id( ship->_leader_uid );
            if ( !leader || xIS_SET( leader->flags, SHIP_DRYDOCK ) )
                remove_from_bg( ship );
            else
                add_to_bg( ship, leader );
        }
    }

    return;
}

int load_ship_sql( const PGresult* qresult, int row )
{
    SHIP_DATA* ship = NULL;
    CREATE( ship, SHIP_DATA, 1 );
    int rval = 0;

    if ( ( rval = fieldmap_postgres_row( qresult, row, ship, ship_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( ship, ship_fields );
        return rval;
    }

    finalize_load_ship( ship );
    return E_LOTJ_SUCCESS;
}

void resetship( SHIP_DATA* ship )
{
    ROOM_INDEX_DATA* room;

    if ( !ship || ship == NULL )
    {
        bug( "resetship has been passed NULL POINTER!" );
        return;
    }

    destroy_lockers( ship->firstroom, ship->lastroom, xIS_SET( ship->flags, SHIP_NODELETE ) ? FALSE : TRUE );

    if ( is_public( ship ) )
    {
        NAVCHART_DATA* chart = NULL, *next_chart = NULL;
        for ( chart = ship->first_navchart; chart; chart = next_chart )
        {
            next_chart = chart->next;
            UNLINK( chart, ship->first_navchart, ship->last_navchart, next, prev );
            delete_navchart( chart );
        }
    }

    if ( ship->starsystem )
        ship_from_starsystem( ship );

    int sendto = ship->shipyard > 0 ? ship->shipyard : ROOM_LIMBO_SHIPYARD;
    ship_to_room( ship, sendto );
    ship->location = sendto;
    ship->lastdoc = sendto;
    ship->shipstate = SHIP_DOCKED;
    ship->trafficstate = TRAFFIC_NONE;
    ship->currspeed = 0;
    ship->energy = ship->maxenergy;
    ship->hull = ship->maxhull;
    ship->shield = ship->maxshield;
    ship->missiles = ship->maxmissiles;
    ship->torpedoes = ship->maxtorpedoes;
    ship->rockets = ship->maxrockets;
    ship->pulses = ship->maxpulses;
    ship->chaff = ship->maxchaff;
    ship->ion_charge = ION_READY;
    ship->autoblaster_charge = LASER_READY;
    ship->laser_charge = LASER_READY;
    ship->turbolaser_charge = LASER_READY;
    ship->missilestate = MISSILE_READY;
    ship->tractorstate = TRACTOR_READY;
    ship->spent_tubes = 0;

    for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
    {
        turret->laserstate = LASER_READY;
    }

    xREMOVE_BIT( ship->flags, SHIP_COMM_DISABLED );
    // Reasonable defaults for autopilot setup
    xCLEAR_BITS( ship->aflags );
    xSET_BIT( ship->aflags, AFLAG_AUTOSHIELD );
    xSET_BIT( ship->aflags, AFLAG_USELASER );
    xSET_BIT( ship->aflags, AFLAG_USEION );
    xSET_BIT( ship->aflags, AFLAG_USELAUNCHER );
    xSET_BIT( ship->aflags, AFLAG_USECHAFF );
    ship->autorecharge = TRUE;
    ship->autotrack = FALSE;
    ship->autospeed = FALSE;
    ship->calctimer = 0;
    ship->target0 = NULL;
    ship->target1 = NULL;
    ship->target2 = NULL;
    ship->hyperlock = FALSE;
    ship->hatchopen = FALSE;
    ship->hatchtimer = 0;
    ship->selfd_time = 0;
    ship->selfd_armed = FALSE;
    ship->undock_time = 0;

    if ( ship->dock_state != DOCK_NONE )
        ship->dock_state = DOCK_READY;
    else
        ship->dock_state = DOCK_NONE;

    ship->autolaunch_time = 0;
    ship->autolaunch_armed = FALSE;
    ship->autolaunch_used = FALSE;

    remove_from_bg( ship );
    remove_from_squad( ship );

    ship->pos = 0;
    // Clear spawn state so it's not counted as an instance of the spawn anymore
    ship->spawn_id = 0;
    ship->spawn_initial_system = 0;

    // Purge any mobs or objects left in the ship
    for ( room = ship->first_room; room; room = room->next_in_range )
        purge_room( room, NULL );

    // Preserve ownership on automated ships and public shuttles
    if ( !is_public( ship ) && !is_pirate( ship ) && !xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        SET_STRING( ship->crew, "" );
        SET_STRING( ship->shipowner, "" );
        SET_STRING( ship->pilot, "" );
        SET_STRING( ship->copilot, "" );
        SET_STRING( ship->homeship, "" );
        ship->clan = NULL;
    }

    save_ship( ship, true );
}

