    if ( !ship || ship_extracted( ship ) )
        return NULL;

    if ( !room )
        return NULL;

    if ( !ship->first_turret )
        return NULL;

    for ( turret = ship->first_turret; turret; turret = turret->next )
    {
        if ( !turret || turret == NULL )
            continue;

        if ( turret->room == NULL )
            continue;

        if ( turret->room == room )
            return turret;
