CMDF do_decorateship( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    SHIP_DATA* ship = NULL;
    BUFFER_DATA* buffer = NULL;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    switch ( ch->substate )
    {
        default:
            break;

        case SUB_SHIP_DESC:
            buffer = get_buffer( ch, FUNC );
            if ( buffer )
            {
                ship = buffer->ship;
                dispose_buffer( buffer );
            }

            if ( !ship )
            {
                bug( "setship: sub_ship_desc: NULL buffer" );
                ch_println( ch, "Sorry I lost track of the ship you were editing." );
                stop_editing( ch, false );
                return;
            }

            SET_STRING( ship->description, copy_buffer( ch ) );
            stop_editing( ch, false );
            ch->substate = ch->tempnum;
            save_ship( ship, true );
            ch->gold -= 100000;
            ch_println( ch, "&YS&zhip %s successfully redecorated, 100,000 credits deducted.", ship->name );
            return;
    }

    if ( !ch->in_room )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_room( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "Usage: decorateship (from within a ship you own)" );
        return;
    }

    if ( !xIS_SET( ship->flags, SHIP_CUSTOMIZABLE ) )
    {
        ch_println( ch, "&RThat ship is not customizable.&w" );
        return;
    }

    if ( is_rental( ch, ship ) )
    {
        ch_println( ch, "&RYou cannot decorate public shuttles!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) )
    {
        ch_println( ch, "&RThat ship is too well known to be decorated!" );
        return;
    }

    if ( !check_pilot( ch, ship ) )
    {
        ch_println( ch, "&RYou must be cleared to pilot the ship before changing its name." );
        return;
    }

    if ( ch->gold < 100000 )
    {
        ch_println( ch, "It costs 100,000 credits to redecorate your ship's hull." );
        return;
    }

    bug( "%s changing ship description (%d)", ch->name, ship->name );
    if ( is_busy( ch ) )
    {
        ch_println( ch, "You are too busy to do that right now." );
        return;
    }

    ch->tempnum = SUB_NONE;
    ch->substate = SUB_SHIP_DESC;
    buffer = create_buffer( ch, FUNC );
    buffer->ship = ship;
    start_editing( ch, FUNC, ship->description );
    return;
}
