int get_modflag( char* flag )
{
    int x;

    for ( x = 0; x < 32; x++ )
        if ( !str_cmp( flag, mod_flags[x] ) )
            return x;

    return -1;
}

CMDF do_gotoship( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship = NULL;
    char arg1[MSL];
    char buf[MSL];

    if ( NULLSTR( argument ) )
    {
        if ( ( ship = get_ship_from_room( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "&zSyntax: &Cgotoship <&wship&C>&w" );
            return;
        }
    }

    argument = one_argument( argument, arg1 );

    if ( !ship )
        ship = get_ship( arg1 );

    if ( !ship )
    {
        ch_println( ch, "No such ship." );
        return;
    }

    snprintf( buf, MSL, "%d", ship->cockpit );
    do_goto( ch, buf );
}

CMDF do_showship( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], arg1[MSL];
    NAVCHART_DATA* chart = NULL;
    SHIP_DATA* ship = NULL;
    TURRET_DATA* turret;
    HANGAR_DATA* hangar;
    ESCAPE_DATA* escape;
    CARGO_DATA* cargo;
    bool drydocked = FALSE;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        if ( ( ship = get_ship_from_room( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "&zUsage:&C showship <&wship&C>&w" );
            return;
        }
    }

    argument = one_argument( argument, arg1 );

    if ( !ship )
        ship = get_ship( arg1 );

    if ( !ship )
        if ( ( ship = get_drydock_ship( arg1 ) ) != NULL )
            drydocked = TRUE;

    if ( !ship )
    {
        ch_println( ch, "&wNo such ship.&w" );
        return;
    }

    set_char_color( AT_YELLOW, ch );
    ch_println( ch, "&z[&CClass: %s&z] : &C%s &z(&CFilename: &C%s&z)", class_types[ship->classtype], ship->name,
               ship->shortname );
    ch_println( ch, "&zId: &C%d&z   Template: &C%s", ship->id, ship->template->shortname );
    ch_println( ch, "&zStatus: %s", drydocked ? "&RDRYDOCKED" : "&GACTIVE" );

    if ( !str_cmp( argument, "hangar" ) )
    {
        ch_println( ch, "&z [&CHangars&z]---------------------------------------------------------------------" );
        int hangar_idx = 0;

        for ( hangar = ship->first_hangar; hangar; hangar = hangar->next )
        {
            hangar_idx++;

            if ( hangar->room )
                ch_println( ch, " &zHangar &C%-2d &z- Vnum: &C%-5d  &zSize: &C%d/%d &zslot(s)  &zClasses: &C%s&z - &C%s%s", hangar_idx,
                           hangar->room->vnum,
                           hangar->size - get_hangar_free( hangar ),
                           hangar->size,
                           class_types[hangar->room->minshipclass],
                           class_types[hangar->room->maxshipclass],
                           ( hangar->size == 0 && xIS_SET( ship->flags, SHIP_RESCUESHIP ) ) ? " (EV ONLY)" : "" );
            else
                ch_println( ch, " &zHangar &C%-2d &z- Vnum: &C-----  &zSize: &C%d/%d &zslot(s)%s", hangar_idx,
                           hangar->size - get_hangar_free( hangar ), hangar->size, ( hangar->size == 0 && xIS_SET( ship->flags, SHIP_RESCUESHIP ) ) ? " (EV ONLY)" : "" );
        }

        ch_println( ch, "&z ------------------------------------------------------------------------------" );
        return;
    }

    if ( !str_cmp( argument, "turret" ) )
    {
        ch_println( ch, "&z [Turrets]------------------------------------" );
        int turret_idx = 0;

        for ( turret = ship->first_turret; turret; turret = turret->next )
        {
            turret_idx++;

            if ( turret->room )
                ch_println( ch, " &zTurret &C%-2d &z- Vnum: &C%-5d  &zCondition: %s", turret_idx, turret->room->vnum,
                           turret->laserstate <= LASER_DESTROYED ? "&RDestroyed" : turret->laserstate <= LASER_DAMAGED ? "&RDamaged" : "&CGood" );
            else
                ch_println( ch, " &zTurret &C%-2d &z- Vnum: &C-----  &zCondition: %s", turret_idx,
                           turret->laserstate <= LASER_DESTROYED ? "&RDestroyed" : turret->laserstate <= LASER_DAMAGED ? "&RDamaged" : "&CGood" );
        }

        ch_println( ch, "&z ---------------------------------------------" );
        return;
    }

    if ( !str_cmp( argument, "lift" ) || !str_cmp( argument, "turbolift" ) || !str_cmp( argument, "turbolifts" ) )
    {
        ch_println( ch, "&z [Turbolifts]---------------------------------" );

        ROOM_INDEX_DATA* room = NULL;
        int cnt = 0;

        for ( room = ship->first_room; room; room = room->next_in_range )
        {            
            if ( room->lift == NULL )
                continue;

            cnt++;

            ch_println( ch, "\n &zTurbolift Room: &C%d&z", room->vnum );
            for ( TURBOFLOOR_DATA* floor = room->lift->first_floor; floor; floor = floor->next )
                ch_println( ch, " &C- &zFloor &C%d&z -- Room &C%d&z", floor->num, floor->room );
        }

        if ( cnt == 0 )
            ch_println( ch, "&wNone found." );

        ch_println( ch, "&z ---------------------------------------------" );
        return;
    }

    if ( !str_cmp( argument, "escape" ) )
    {
        ch_println( ch, "&z [Escape Pods]--------------------------------" );
        int escape_idx = 0;

        for ( escape = ship->first_escape; escape; escape = escape->next )
        {
            escape_idx++;

            if ( escape->room )
                ch_println( ch, " &zEscape &C%-2d &z- Vnum: &C%-5d  &zPods: &C%d/%d &zunit(s)", escape_idx,
                           escape->room->vnum, escape->pods, escape->max_pods );
            else
                ch_println( ch, " &zEscape &C%-2d &z- Vnum: &C-----  &zPods: &C%d/%d &zunit(s)", escape_idx, escape->pods,
                           escape->max_pods );
        }

        ch_println( ch, "&z ---------------------------------------------" );
        ch_println( ch, "&zEject Beacon ID: &C%d", ship->eject_beacon_id );
        return;
    }

    if ( !str_cmp( argument, "cargo" ) )
    {
        ch_println( ch, "&z [Cargo Pods]---------------------------------" );
        int cargo_idx = 0;

        for ( cargo = ship->first_cargo; cargo; cargo = cargo->next )
        {
            cargo_idx++;
            ch_println( ch, " &zCargo &C%-3d &z- Size: &C%d/%d &zslot(s)", cargo_idx, cargo->amount, cargo->size );

            if ( cargo->amount > 0 && cargo->type >= 0 )
            {
                ch_println( ch, " &z - contains &C%d &zunit(s) of &C%s.", cargo->amount, cargo_name[cargo->type] );
            }
        }

        ch_println( ch, "&z ---------------------------------------------" );
        return;
    }

    if ( !str_cmp( argument, "upgrade" ) || !str_cmp( argument, "limits" ) )
    {
        print_upgrade_specs( ch, ship->template, ship );
        return;
    }

    ch_println( ch, "&zHome:  &C%s\n&zDescription: &C\n%s", ship->home, ship->template->description );
    ch_println( ch, "&zHomeship:  [&C%s&z]  &zIdent:  [&C%s&z]",
               ship->homeship[0] == '\0' ? "&RIndependent" : ship->homeship, ship->template->ident );
    ch_println( ch, "&zSquad Leader: &C%s", ( ship->squadleader && ship->squadleader->name ) ? ship->squadleader->name : "None" );
    ch_println( ch, "&zValue: &C%ld &zcredit(s)", get_ship_value( ship ) );

    if ( ship->first_navchart )
    {
        strlcpy( buf, "", MSL );
        for ( chart = ship->first_navchart; chart; chart = chart->next )
        {
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z- &C%s&z added by &C%s&z on &C%s&z\n",
            !NULLSTR( chart->name ) ? chart->name : "NULL",
            !NULLSTR( chart->loaded_by ) ? chart->loaded_by : "NULL",
            micro_c_time( chart->date, get_timezone( ch ) ) );
        }

        ch_println( ch, "&zNavcomp:\n%s", buf );
    }

    ch_println( ch, "&zFlags: [&C%s&z]", flag_string( &ship->flags, ship_flags ) );

    if ( ship->piloting && get_trust( ch ) >= LEVEL_ADMIN )
        ch_println( ch, "&zPiloted by: &C%s", ship->piloting->name );

    char occupants[MSL];
    strlcpy( occupants, "", MSL );
    ROOM_INDEX_DATA* ship_room = NULL;
    CHAR_DATA* occupant = NULL;

    for ( ship_room = ship->first_room; ship_room; ship_room = ship_room->next_in_range )
    {        
        occupant = NULL;
        for ( occupant = ship_room->first_person; occupant; occupant = occupant->next_in_room )
        {
            if ( !NULLSTR( occupants ) )
                snprintf( occupants + strlen( occupants ), MSL - strlen( occupants ), ", " );

            snprintf( occupants + strlen( occupants ), MSL - strlen( occupants ), "&C%s &z(%s%s&z)",
            !IS_NPC( occupant ) ? occupant->name : occupant->short_descr,
            !IS_NPC( occupant ) ? "&W" : "&Y",
            !IS_NPC( occupant ) ? "PC" : "NPC" );
        }
    }

    if ( get_trust( ch ) >= LEVEL_ADMIN && !NULLSTR( occupants ) )
        ch_println( ch, "&zShip occupants: %s", occupants );

    if ( ship->stolen )
        ch_println( ch, "&zStolen By: &C%s  &zSecurity Rating: &C%d", ship->stolen, ship->security_rating );

    if ( ship->mod_flags > 0 )
        ch_println( ch, "&zMod_flags: [&C%s&z]", old_flag_string( ship->mod_flags, mod_flags ) );

    // To the extent these are used at all, they use mod flags, not the NPC act_flags. - Nield 01/17/2024
    if ( ship->act_flags > 0 )
        ch_println( ch, "&zAct_flags: [&C%s&z]", old_flag_string( ship->act_flags, mod_flags ) );

    ch_println( ch, "&zOwner: [&C%-14s&z]   Pilot: [&C%-14s&z]   Copilot: [&C%-14s&z]", ship->shipowner, ship->pilot,
               ship->copilot );

    ch_println( ch, "&zFirstroom: &C%-5d   &zLastroom: &C%-5d", ship->firstroom, ship->lastroom );
    ch_println( ch, "&zCockpit:   &C%-5d   &zEntrance: &C%-5d  &zEngineroom: &C%-5d  &zDockroom: &C%-5d",
               ship->cockpit, ship->entrance, ship->engineroom, ship->dockroom );
    ch_println( ch, "&zPilotseat: &C%-5d   &zCoseat:   &C%-5d  &zNavseat:    &C%-5d  &zGunseat:  &C%-5d",
               ship->pilotseat, ship->coseat, ship->navseat, ship->gunseat );
    ch_println( ch, "&zLocation:  &C%-5d   &zLastdoc:  &C%-5d  &zShipyard:   &C%-5d", ship->location, ship->lastdoc,
               ship->shipyard );
    ch_println( ch, "&zKillcount: &C%-5d", ship->killcount );
    ch_println( ch, "&zLasers:       &C%-7d  &zWeapon Condition: %s&z", ship->lasers,
               ship->laser_charge == LASER_DAMAGED ? "&RDamaged" : ship->laser_charge == LASER_DESTROYED ? "&RDestroyed" : "&CGood" );
    ch_println( ch, "&zAutoblasters: &C%-7d  &zWeapon Condition: %s&z", ship->blasters,
               ship->autoblaster_charge == LASER_DAMAGED ? "&RDamaged" : ship->autoblaster_charge == LASER_DESTROYED ? "&RDestroyed" : "&CGood" );
    ch_println( ch, "&zTurbolasers:  &C%-7d  &zWeapon Condition: %s&z", ship->turbolasers,
               ship->turbolaser_charge == LASER_DAMAGED ? "&RDamaged" : ship->turbolaser_charge == LASER_DESTROYED ? "&RDestroyed" : "&CGood" );
    ch_println( ch, "&zIon Cannons:  &C%-7d  &zIon Condition:    %s&z", ship->ion,
               ship->ion_charge == ION_DAMAGED ? "&RDamaged" : ship->ion_charge == ION_DESTROYED ? "&RDestroyed" : "&CGood" );
    ch_println( ch, "&zComm System:  &C%s&z", xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) ? "&RDestroyed" : xIS_SET( ship->flags, SHIP_COMM_DISABLED ) ? "&RDisabled" : "&COnline" );
    ch_println( ch, "&zDocking Ring: &C%s   &zDocked: &C%s", ship->dock_install ? "Installed" : "Not Installed",
               ship->dockship != NULL ? ship->dockship->name : "&R(Not Docking)" );
    ch_println( ch, "&zFighting:     &W[%s&W]      &zSafe Orbital:     &W[%s&W]",
               ship_is_fighting( ship ) ? "&RX" : " ", ship->safe_orbital ? "&CX" : " " );
    ch_printf( ch, "&zCloaking Device: " );

    switch ( ship->cloakstatus )
    {
        default:
            ch_println( ch, "&RUnknown" );
            break;

        case CLOAK_DESTROYED:
            ch_println( ch, "&RDestroyed" );
            break;

        case CLOAK_DAMAGED:
            ch_println( ch, "&RDamaged" );
            break;

        case CLOAK_NONE:
            ch_println( ch, "&CNot Installed" );
            break;

        case CLOAK_READY:
            ch_println( ch, "&CReady" );
            break;

        case CLOAK_ON:
            ch_println( ch, "&CActive" );
            break;
    }

    ch_println( ch, "&zMissile Launcher - Condition: %s  &zTubes: &C%d",
               ship->missilestate == MISSILE_DESTROYED ? "&RDestroyed" : ship->missilestate == MISSILE_DAMAGED ? "&RDamaged" : "&CGood", ship->missiletubes );
    ch_println( ch, "&zMissiles: &C%d&z/&C%d  &zTorpedoes: &C%d&z/&C%d  &zRockets: &C%d&z/&C%d  &zPulses: &C%d&z/&C%d",
               ship->missiles, ship->maxmissiles, ship->torpedoes, ship->maxtorpedoes, ship->rockets, ship->maxrockets,
               ship->pulses, ship->maxpulses );
    ch_println( ch, "&zTractor Beam - Condition: %s  &zPower: &C%-3d",
               ship->tractorstate == TRACTOR_DESTROYED ? "&RDestroyed" : ship->tractorstate == TRACTOR_DAMAGED ? "&RDamaged" : "&CGood", ship->tractorbeam );
    ch_println( ch, "&zHull:     &C%d&z/&C%d  &zShip Condition: %s", ship->hull, ship->maxhull,
               ship->shipstate == SHIP_PERM_DISABLED ? "&RPermanently Disabled" : ship->shipstate == SHIP_DISABLED ? "&RDisabled" : "&CRunning" );
    ch_println( ch, "&zShields:  &C%d&z/&C%d  &zFuel: &C%d&z/&C%d   &zChaff: &C%d&z/&C%d", ship->shield, ship->maxshield,
               ship->energy, ship->maxenergy, ship->chaff, ship->maxchaff );
    ch_println( ch, "&zCurrent Coordinates: &C%.0f %.0f %.0f", ship->vpos.x, ship->vpos.y, ship->vpos.z );
    ch_println( ch, "&zCurrent Heading:     &C%.0f %.0f %.0f", ship->head.x, ship->head.y, ship->head.z );
    ch_println( ch, "&zSpeed:  &C%-3d&z/&C%-3d  &zHyperspeed: &C%-3d  &zManeuverability: &C%-3d",
               ship->currspeed, ship->realspeed, ship->hyperspeed, ship->maneuver );
    ch_println( ch, "&zComm:   &C%-3d      &zSensor:     &C%-3d  &zShield Boosters: &C%-3d",
               ship->comm, ship->sensor, ship->shield_boosters );

    if ( ship->autolaunch_armed )
    {
        ch_println( ch, "&zAutolaunch Status: &R+--==ARMED==--+" );
        ch_println( ch, "&z -=> Time Remaining: &C%d second(s)&z", ship->autolaunch_time );
    }
    else
        ch_println( ch, "&zAutolaunch Status: &CStandby" );

    if ( ship->selfd_armed )
    {
        ch_println( ch, "&zSelfdestruct Status: &R+--==ARMED==--+" );
        ch_println( ch, "&z -=> Time Remaining: &C%d second(s)&z", ship->selfd_time );
    }
    else
        ch_println( ch, "&zSelfdestruct Status: &CStandby" );

    ch_println( ch, "&zShipstate #: &C%d  &zTraffic state: &C%s", ship->shipstate, traffic_states_names[ship->trafficstate] );
    int count;

    if ( ship->first_hangar )
    {
        LINK_LENGTH( ship->first_hangar, HANGAR_DATA, next, count );
        ch_println( ch, "&zThis ship has &C%d&z hangars. Use &WSHOWSHIP ... HANGAR &zto view.", count );
    }

    if ( ship->first_turret )
    {
        LINK_LENGTH( ship->first_turret, TURRET_DATA, next, count );
        ch_println( ch, "&zThis ship has &C%d&z turrets. Use &WSHOWSHIP ... TURRET &zto view.", count );
    }

    if ( ship->first_escape )
    {
        LINK_LENGTH( ship->first_escape, ESCAPE_DATA, next, count );
        ch_println( ch, "&zThis ship has &C%d&z escape pods. Use &WSHOWSHIP ... ESCAPE &zto view.", count );
    }

    if ( ship->first_cargo )
    {
        LINK_LENGTH( ship->first_cargo, CARGO_DATA, next, count );
        ch_println( ch, "&zThis ship has &C%d&z cargo pods. Use &WSHOWSHIP ... CARGO &zto view.", count );
    }

    return;
}

CMDF do_makeship( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    char arg[MIL];
    argument = one_argument( argument, arg );

    if ( !argument || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Cmakeship <&wshortname&C> <&wship name&C>&w" );
        return;
    }

    CREATE( ship, SHIP_DATA, 1 );
    SET_STRING( ship->shortname, arg );
    SET_STRING( ship->name, argument );
    SET_STRING( ship->copilot, "" );
    SET_STRING( ship->crew, "" );
    SET_STRING( ship->description, "" );
    SET_STRING( ship->dest, "" );
    SET_STRING( ship->first_roomname , "" );
    SET_STRING( ship->home, "" );
    SET_STRING( ship->homeship, "" );
    SET_STRING( ship->pilot, "" );
    SET_STRING( ship->pilot_name, "" );
    SET_STRING( ship->selfd_by, "" );
    SET_STRING( ship->shipowner, "" );
    ship->clan = NULL;
    ship->spawn_initial_system = 0;
    SET_STRING( ship->stolen, "" );
    ship->template = blank_shipimage;
    ship->starsystem = NULL;
    ship->maxhull = 5;
    ship->maxquota = 0;
    ship->energy = ship->maxenergy;
    ship->hull = ship->maxhull;
    ship->in_room = NULL;
    ship->next_in_room = NULL;
    ship->prev_in_room = NULL;
    ship->target0 = NULL;
    ship->target1 = NULL;
    ship->target2 = NULL;
    ship->code[SCODE_HATCH] = number_range( 11111, 99999 );
    ship->code[SCODE_HANGAR] = number_range( 11111, 99999 );
    ship->code[SCODE_DOCK] = number_range( 11111, 99999 );
    ship->code[SCODE_SELFD] = number_range( 11111, 99999 );
    ship->cloakstatus = CLOAK_NONE;
    ship->act_flags = 0;
    ship->mod_flags = 0;
    xCLEAR_BITS( ship->flags );
    xCLEAR_BITS( ship->aflags );
    LINK( ship, first_ship, last_ship, next, prev );
    hashset_add( valid_ships, ship );
    save_ship( ship, true );
}

CMDF do_copyship( CHAR_DATA* ch, char* argument )
