/*
    Counts the ships owned by the player
*/
int count_ships( char* argument )
{
    int count = 0;

    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( str_cmp( ship->shipowner, argument ) )
            continue;

        count++;
    }

    return count;
}

/*
    Counts the ships owned by the player
*/
int count_legendary_ships( char* argument )
{
    int count = 0;

    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( str_cmp( ship->shipowner, argument ) )
            continue;

        if ( !xIS_SET( ship->flags, SHIP_LEGENDARY ) )
            continue;

        count++;
    }

    return count;
}

/*
    Totals the 'hangar usage' by ships in the room
     VEHICLE:  1 Slot(s)
     FIGHTER:  2 Slot(s)
     PLATFORM: 200 Slot(s)
*/
int get_hangar_count( HANGAR_DATA* hangar )
{
    int count = 0;
    SHIP_TEMPLATE_DATA* template = NULL;
    char imgbuf[MSL];

    if ( !hangar )
        return -1;

    if ( hangar->room == NULL )
        return -1;

    for ( SHIP_DATA* ship = hangar->room->first_ship; ship; ship = ship->next_in_room )
        count += get_ship_size( ship );

    // Also check for ship frames!    Orion 2008
    for ( OBJ_DATA* tobj = hangar->room->first_content; tobj; tobj = tobj->next_content )
    {
        if ( tobj->item_type != ITEM_BLUEPRINT )
            continue;

        if ( xIS_SET( tobj->wear_flags, ITEM_TAKE ) )
            continue;

        if ( stristr( tobj->blueprint, "img" ) )
        {
            one_argument( tobj->blueprint, imgbuf );
            template = find_shiptemplate( imgbuf );

            if ( template )
            {
                count += get_shipclass_size( template->classtype );
            }
            else
            {
                count += get_shipclass_size( tobj->value[0] - 1 );
            }
        }
    }

    return count;
}

int get_shipcapacity_count( ROOM_INDEX_DATA* room )
{
    int count = 0;
    SHIP_TEMPLATE_DATA* template = NULL;
    char imgbuf[MSL];

    if ( room == NULL )
        return -1;

    for ( SHIP_DATA* ship = room->first_ship; ship; ship = ship->next_in_room )
        count += get_ship_size( ship );

    // Also check for ship frames!    Orion 2008
    for ( OBJ_DATA* tobj = room->first_content; tobj; tobj = tobj->next_content )
    {
        if ( tobj->item_type != ITEM_BLUEPRINT )
            continue;

        if ( xIS_SET( tobj->wear_flags, ITEM_TAKE ) )
            continue;

        if ( stristr( tobj->blueprint, "img" ) )
        {
            one_argument( tobj->blueprint, imgbuf );
            template = find_shiptemplate( imgbuf );

            if ( template )
            {
                count += get_shipclass_size( template->classtype );
            }
            else
            {
                count += get_shipclass_size( tobj->value[0] - 1 );
            }
        }
    }

    return count;
}
bool room_fits_ship( ROOM_INDEX_DATA* room, int shipsize )
{
    if ( room == NULL )
        return FALSE;

    if ( get_ship_from_room( room ) != NULL )
        return TRUE;

    if ( room->shipcapacity == 0 )
        return TRUE;

    int aMt = room->shipcapacity - get_shipcapacity_count( room ) - shipsize;

    if ( aMt >= 0 )
        return TRUE;

    return FALSE;
}
int get_ship_size( SHIP_DATA* ship )
{
    if ( !ship || xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
        return 0;

    return get_shipclass_size( ship->classtype );
}

int get_shipclass_size( int classtype )
{
    if ( classtype == FIGHTER_SHIP )
        return 2;

    if ( classtype == TRANSPORT_SHIP )
        return 5;

    if ( classtype == FREIGHTER_SHIP )
        return 15;

    if ( classtype == GUNBOAT_SHIP )
        return 20;

    if ( classtype == CORVETTE_SHIP )
        return 30;

    if ( classtype == FRIGATE_SHIP )
        return 35;

    if ( classtype == CRUISER_SHIP )
        return 50;

    if ( classtype == BATTLESHIP_SHIP )
        return 65;

    if ( classtype == BATTLESTATION_SHIP )
        return 100;

    if ( classtype == PLATFORM_SHIP )
        return 200;

    if ( classtype == SATELLITE_SHIP )
        return 15;

    if ( classtype > SATELLITE_SHIP )
        return 1;

    bug( "get_shipclass_size: Bad ship class %d", classtype );
    return 0;
}

/*
    Returns the number of 'free slots' in a hangar
    Now also takes into account ships being built
*/
int get_hangar_free( HANGAR_DATA* hangar )
{
    if ( hangar->room == NULL )
        return 0;

    int aMt = hangar->size - get_hangar_count( hangar );
    return aMt;
}

CMDF do_ships( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    SHIP_DATA* ship;
    int count = 0;
    argument = one_argument( argument, arg1 );

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "&RMobs can't use this command, sorry!" );
        return;
    }

    if ( !str_cmp( arg1, "drydock" ) && get_trust( ch ) >= sysdata.log_level )
    {
        ch_println( ch, "&YDisplaying all drydocked ships." );
        ch_println( ch, "&z%-45s Owner:&w", "&zShip Name:&w" );

        for ( ship = first_drydock; ship; ship = ship->next )
        {
            ch_println( ch, "%-45s %s", ship->name, ship->shipowner );
            count++;
        }

        ch_println( ch, "Total of %d ships.", count );
        return;
    }

    if ( !str_cmp( arg1, "unowned" ) && get_trust( ch ) >= sysdata.log_level )
    {
        ch_println( ch, "&YDisplaying all unowned ships." );
        ch_println( ch, "&z%-45s Location:&w", "Ship Name:" );
        char buf[MSL];
        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !NULLSTR( ship->shipowner ) )
                continue;

            if ( ship->in_room )
                snprintf( buf, MSL, "&w%s &z(&C%d&z)", ship->in_room->name, ship->in_room->vnum );
            else if ( ship->starsystem )
                snprintf( buf, MSL, "&w%s &z(&C%d&w, &C%d&z)", ship->starsystem->name, ship->starsystem->xpos, ship->starsystem->ypos );
            else if ( ship->shipstate == SHIP_HYPERSPACE )
                snprintf( buf, MSL, "&wHYPERSPACE &z(&C%d&w, &C%d&z)", sys_coord_from_galactic_coords(ship->hyper_currentpos.x), sys_coord_from_galactic_coords(ship->hyper_currentpos.y) );
            else
                snprintf( buf, MSL, "&wUNKNOWN" );
            ch_println( ch, "%-45s %s", ship->name, buf );
            count++;
        }

        ch_println( ch, "\n&wTotal of &C%d&w ships.", count );
        return;
    }

    if ( !str_cmp( arg1, "public" ) && get_trust( ch ) >= sysdata.log_level )
    {
        ch_println( ch, "&YDisplaying all public ships." );
        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( "Public", ship->shipowner ) && str_cmp( "public", ship->shipowner ) )
                continue;

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s)", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-45s %s", ship->name, ship->in_room->name );
            }
            else
                ch_println( ch, " %-45s (%s)", ship->name,
                           ship->starsystem != NULL ? ship->starsystem->name : "Somewhere" );

            count++;
        }

        ch_println( ch, "Found a total of %d public ships.", count );
        return;
    }

    if ( !str_cmp( arg1, "pirate" ) && get_trust( ch ) >= 103 )
    {
        ch_println( ch, "&YDisplaying all Pirates" );
        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !is_pirate( ship ) )
                continue;

            /*
                Skip interceptors
            */
            if ( ship->shipyard != 45 )
                continue;

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s)", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-45s %s", ship->name, ship->in_room->name );
            }
            else
                ch_println( ch, " %-45s (%s)", ship->name,
                           ship->starsystem != NULL ? ship->starsystem->name : "Somewhere" );

            count++;
        }

        ch_println( ch, "Found a total of %d pirates.", count );
        return;
    }

    if ( !str_cmp( arg1, "traffic" ) && get_trust( ch ) >= 103 )
    {
        ch_println( ch, "&YDisplaying all Traffic Ships" );
        ch_println( ch, "&zShip Name:                                     Owner:          Location:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !xIS_SET( ship->flags, SHIP_TRAFFIC ) )
                continue;

            count++;

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-34s %-10s %s (%s)&W", ship->name, ship->shipowner, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-34s %-10s %s&W", ship->name, ship->shipowner, ship->in_room->name );
            }
            else
                ch_println( ch, " %-34s %-10s (Somewhere)&W", ship->name, ship->shipowner );
        }

        ch_println( ch, "Found a total of %d traffic ships.", count );
    }

    if ( !str_cmp( arg1, "legendary" ) && get_trust( ch ) >= 103 )
    {
        ch_println( ch, "&YDisplaying all Legendary Ships" );
        ch_println( ch, "&zShip Name:                                     Owner:          Location:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !xIS_SET( ship->flags, SHIP_LEGENDARY ) )
                continue;

            count++;

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-34s %-10s %s (%s)&W", ship->name, ship->shipowner, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-34s %-10s %s&W", ship->name, ship->shipowner, ship->in_room->name );
            }
            else
                ch_println( ch, " %-34s %-10s (Somewhere)&W", ship->name, ship->shipowner );
        }

        ch_println( ch, "Found a total of %d legendary ships.", count );
    }

    if ( !str_cmp( arg1, "owned" ) )
    {
        ch_println( ch, "&YThe following ships are owned by you:" );
        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( ( str_cmp( ship->shipowner, ch->name ) && str_cmp( ship->stolen, ch->name ) )
                    || ship->classtype > SATELLITE_SHIP )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s)%s", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name, !str_cmp( ship->stolen, ch->name ) ? "&Y(Stolen)" : "" );
                else
                    ch_println( ch, " %-45s %s %s", ship->name, ship->in_room->name,
                               !str_cmp( ship->stolen, ch->name ) ? "&Y(Stolen)" : "" );
            }
            else
                ch_println( ch, " %-45s (Somewhere) %s", ship->name, ( !str_cmp( ship->stolen, ch->name ) ? "&Y(Stolen)" : ""   ) );

            count++;
        }

        if ( !count )
        {
            ch_println( ch, "&R There are no ships owned by you." );
        }
    }
    else if ( !str_cmp( arg1, "pilot" ) )
    {
        ch_println( ch, "&YThe following ships are pilotable by you:" );
        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( ship->pilot, ch->name ) || ship->classtype > SATELLITE_SHIP )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s)", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-45s %s", ship->name, ship->in_room->name );
            }
            else
                ch_println( ch, " %-45s (Somewhere)", ship->name );

            count++;
        }

        if ( !count )
        {
            ch_println( ch, "&R There are no ships pilotable by you." );
        }
    }
    else if ( !str_cmp( arg1, "copilot" ) )
    {
        ch_println( ch, "&YThe following ships are copilotable by you:" );
        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( ship->copilot, ch->name ) || ship->classtype > SATELLITE_SHIP )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s)", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name );
                else
                    ch_println( ch, " %-45s %s", ship->name, ship->in_room->name );
            }
            else
                ch_println( ch, " %-45s (Somewhere)", ship->name );

            count++;
        }

        if ( !count )
        {
            ch_println( ch, "&R There are no ships copilotable by you." );
        }
    }
    else if ( !str_cmp( arg1, "clan" ) )
    {
        if ( !ch->pcdata || !ch->pcdata->clan )
        {
            ch_println( ch, "&RYou don't belong to a clan!" );
            return;
        }

        if ( !is_empowered( ch, "pilot" ) && !is_empowered( ch, "bigpilot" ) && str_cmp( ch->pcdata->clan->leader, ch->name ) && str_cmp( ch->pcdata->clan->number1, ch->name ) && str_cmp( ch->pcdata->clan->number2, ch->name ) )
        {
            ch_println( ch, "&RYou aren't authorized to view your clan's ship list." );
            return;
        }

        int class = atoi( argument );

        if ( !NULLSTR( argument ) && ( !is_number( argument ) || class < 0 || class > SATELLITE_SHIP ) )
        {
            ch_println( ch, "&zSyntax: &Cships clan (to see all)" );
            ch_println( ch, "&zSyntax: &Cships clan <&wclass number&C>" );

            if ( is_empowered( ch, "pilot" ) )
            {
                ch_println( ch, "&z          0 - &CFighter Ship      " );
                ch_println( ch, "&z          1 - &CTransport Ship    " );
                ch_println( ch, "&z          2 - &CFreighter Ship    " );
                ch_println( ch, "&z          3 - &CGunboat Ship      " );
                ch_println( ch, "&z          4 - &CCorvette Ship     " );
            }

            if ( is_empowered( ch, "bigpilot" ) )
            {
                ch_println( ch, "&z          5 - &CFrigate Ship      " );
                ch_println( ch, "&z          6 - &CCruiser Ship      " );
                ch_println( ch, "&z          7 - &CBattleship        " );
                ch_println( ch, "&z          8 - &CBattlestation     " );
                ch_println( ch, "&z          9 - &CShip Platform     " );
                ch_println( ch, "&z          10  - &CSatellite       " );
            }

            return;
        }

        ch_println( ch, "&zSyntax: &Cships clan (to see all)" );
        ch_println( ch, "&zSyntax: &Cships clan <&wclass number&C>" );

        if ( !NULLSTR( argument ) )
        {
            ch_println( ch, "&YThe following %s class ships are owned by your clan:", class_types[class] );
        }
        else
        {
            ch_println( ch, "&YThe following ships are owned by your clan:" );
        }

        ch_println( ch, "&z%-45s Location:&w", "&zShip Name:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !ch->pcdata || !ch->pcdata->clan || ( str_cmp( ship->shipowner, ch->pcdata->clan->name ) && str_cmp( ship->stolen, ch->pcdata->clan->name ) )
                    || ship->classtype > SATELLITE_SHIP )
                continue;

            if ( str_cmp( ch->pcdata->clan->leader, ch->name ) && str_cmp( ch->pcdata->clan->number1, ch->name ) && str_cmp( ch->pcdata->clan->number2, ch->name ) )
            {
                if ( !is_empowered( ch, "pilot" ) && ship->classtype <= CORVETTE_SHIP )
                    continue;

                if ( !is_empowered( ch, "bigpilot" ) && ship->classtype >= FRIGATE_SHIP )
                    continue;
            }

            if ( !NULLSTR( argument ) && ship->classtype != class )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( ship->in_room )
            {
                if ( ship->in_room->area && ship->in_room->area->planet )
                    ch_println( ch, " %-45s %s (%s) %s", ship->name, ship->in_room->name,
                               ship->in_room->area->planet->name, ( is_stolen_ship( ch, ship, NULL ) ? "&Y(stolen)" : "" ) );
                else
                    ch_println( ch, " %-45s %s %s", ship->name, ship->in_room->name, ( is_stolen_ship( ch, ship, NULL ) ? "&Y(stolen)" : "" ) );
            }
            else
                ch_println( ch, " %-45s (Somewhere) %s", ship->name, ( is_stolen_ship( ch, ship, NULL ) ? "&Y(stolen)" : "" ) );

            count++;
        }

        if ( !count )
        {
            ch_println( ch, "There are no ships owned by your clan." );
        }
    }
    else if ( !str_cmp( arg1, "room" ) )
    {
        ch_println( ch, "&YThe following ships are docked here:" );
        ch_println( ch, "&zShip Name:                          Owner:          Cost&w/&zRent:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( ship->location != ch->in_room->vnum || ship->classtype > SATELLITE_SHIP )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( !str_cmp( ship->shipowner, ch->name ) || check_clanpilot( ch, ship ) || IS_IMMORTAL( ch ) )
                ch_printf( ch, " %-34s %-15s ", ship->name, ship->shipowner );
            else
                ch_printf( ch, " %-34s [ ---------- ]", ship->name );

            if ( ship->classtype == SATELLITE_SHIP )
            {
                ch_println( ch, "[ ---------- ]" );
                continue;
            }

            if ( !str_cmp( ship->shipowner, "Public" ) || !str_cmp( ship->shipowner, "public" ) )
            {
                ch_println( ch, "%ld to rent.", ship->charge_price );
            }
            else if ( !str_cmp( ship->shipowner, "Trainer" ) )
            {
                ch_println( ch, "Trainer ship. (Rentable)" );
            }
            else if ( str_cmp( ship->shipowner, "" ) )
                ch_println( ch, "[Purchased]" );
            else
                ch_println( ch, "%ld to buy.", get_ship_value( ship ) );

            count++;
        }

        if ( !count )
        {
            ch_println( ch, " &zThere are no ships docked here." );
        }
    }
    else if ( !str_cmp( arg1, "quota" ) && IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&YThe following ships are docked here:" );
        ch_println( ch, "&zShip Name:                          Owner:          Quota:&w" );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( ship->location != ch->in_room->vnum || ship->classtype > SATELLITE_SHIP )
                continue;

            set_char_color( AT_BLUE, ch );
            ch_println( ch, " %-34s %-15s %-1.2f", ship->name, ship->shipowner, ship->maxquota / 100.0 );
            count++;
        }

        if ( !count )
        {
            ch_println( ch, " &zThere are no ships docked here." );
        }
    }
    else if ( !str_cmp( arg1, "sale" ) )
    {
        if ( ch->in_room == NULL )
            return;

        if ( ch->in_room->area == NULL )
            return;

        if ( ch->in_room->area->planet != NULL )
            ch_println( ch, "&YThe following ships are for sale on this planet:" );
        else
            ch_println( ch, "&YThe following ships are for sale nearby:" );

        ch_println( ch, "&z%-45s Cost:&w", "&zShip Name:&w" );
        SHIP_DATA* player_cur_ship = get_ship_from_room( ch->in_room );

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( !ship->in_room )
                continue;

            if ( !ship->in_room->area )
                continue;

            if ( ship->in_room->vnum == 45 )
                continue;

            if ( xIS_SET( ship->in_room->flags, ROOM_HIDDEN_LAND ) && ch->in_room != ship->in_room )
                continue;

            if ( xIS_SET( ship->in_room->flags, ROOM_CLANPAD ) && ch->in_room != ship->in_room )
                continue;

            if ( ch->in_room->area->planet != NULL )
            {
                if ( ship->in_room->area->planet != ch->in_room->area->planet )
                    continue;
            }
            else if ( player_cur_ship != NULL )
            {
                if ( ship->in_room->vnum < player_cur_ship->firstroom ||
                        ship->in_room->vnum > player_cur_ship->lastroom )
                    continue;
            }
            else
            {
                // Not on a ship or planet, so we can just stop now.
                break;
            }

            if ( ship->classtype > SATELLITE_SHIP )
                continue;

            if ( !str_cmp( ship->shipowner, "Trainer" ) )
                continue;

            if ( xIS_SET( ship->flags, SHIP_VONG ) && !xIS_SET( ch->race->flags, RFLAG_VONG ) )
                continue;

            set_char_color( AT_BLUE, ch );

            if ( !str_cmp( ship->shipowner, "Public" ) || !str_cmp( ship->shipowner, "public" ) )
            {
                ch_println( ch, " %-45s %ld to rent.", ship->name, ship->charge_price );
            }
            else if ( str_cmp( ship->shipowner, "" ) )
            {
            }
            else
            {
                ch_println( ch, " %-45s %ld to buy.", ship->name, get_ship_value( ship ) );
            }

            count++;
        }

        if ( !count )
        {
            ch_println( ch, " &zThere are no ships for sale here." );
        }
    }
    /*
        Extra expansion for other ship locations.   Orion
    */
    else if ( !str_cmp( arg1, "space" ) )
    {
        if ( get_trust( ch ) >= 103 )
        {
            for ( ship = first_ship; ship; ship = ship->next )
            {
                if ( !ship->starsystem || ( is_pirate( ship ) ) )
                    continue;
                else
                    ch_println( ch, "&B %-45s in %s.", ship->name, ship->starsystem->name );

                count++;
            }

            if ( count == 0 )
            {
                ch_println( ch, "&z No ships were found in space." );
            }
            else
            {
                ch_println( ch, "&B There are a total of&c %d &Bships in space.", count );
            }
        }
    }
    else if ( get_trust( ch ) >= 103 && !str_cmp( arg1, "class" ) )
    {
        int class = atoi( argument );

        if ( !is_number( argument ) || class < 0 || class > SATELLITE_SHIP )
        {
            ch_println( ch, "&zSyntax: &Cships class <&wvalue&C>" );
            ch_println( ch, "&zClasses:  0 - &CFighter Ship      " );
            ch_println( ch, "&z          1 - &CTransport Ship    " );
            ch_println( ch, "&z          2 - &CFreighter Ship    " );
            ch_println( ch, "&z          3 - &CGunboat Ship      " );
            ch_println( ch, "&z          4 - &CCorvette Ship     " );
            ch_println( ch, "&z          5 - &CFrigate Ship      " );
            ch_println( ch, "&z          6 - &CCruiser Ship      " );
            ch_println( ch, "&z          7 - &CBattleship        " );
            ch_println( ch, "&z          8 - &CBattlestation     " );
            ch_println( ch, "&z          9 - &CShip Platform     " );
            ch_println( ch, "&z          10  - &CSatellite       " );
            return;
        }

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( ship->classtype != class )
                continue;

            ch_println( ch, "&B %-45s in %s%s.", ship->name,
                       ship->in_room ? ship->in_room->name : ship->starsystem ? ship->starsystem->name : "",
                       ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) ? " &r(&wDisabled&r)" : "" );
            count++;
        }

        if ( count == 0 )
        {
            ch_println( ch, "&z You find no %s ships.", class_types[class] );
        }
        else
        {
            ch_printf( ch, "&B Found a total of&c %d &B%s ships", count, class_types[class] );
        }
    }
    else if ( get_trust( ch ) >= 103 && arg1[0] != '\0' )
    {
        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( ship->shipowner, arg1 ) && !strstr( ship->name, arg1 ) )
                continue;

            ch_println( ch, " %-60s in %s%s.", ship->name,
                       ship->in_room ? ship->in_room->name : ship->starsystem ? ship->starsystem->name : "",
                       ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) ? " &r(&wDisabled&r)" : "" );
            count++;
        }

        if ( count == 0 )
        {
            ch_println( ch, "&z You find no ships matching \"%s\".", arg1 );
        }
        else
        {
            ch_printf( ch, "&B Found a total of&c %d &Bships owned by %s.", count, arg1 );
        }
    }
    else
    {
        ch_println( ch, "&zSyntax: &CSHIPS <&wtype&C>" );
        ch_println( ch, "&B OWNED     &z- Shows all of the ships you own." );
        ch_println( ch, "&B CLAN      &z- Shows all of the ships owned by your clan." );
        ch_println( ch, "&B ROOM      &z- Shows all of the ships in the room." );
        ch_println( ch, "&B SALE      &z- Shows all of the ships for sale on your current planet, platform, or ship." );
        ch_println( ch, "&B PILOT     &z- Shows all of the ships you are a pilot on." );
        ch_println( ch, "&B COPILOT   &z- Shows all of the ships you are a copilot on." );

        if ( get_trust( ch ) >= 103 )
        {
            ch_println( ch, "&B <X>       &z- Shows all of the ships owned by X or with X in their name." );
            ch_println( ch, "&B CLASS #   &z- Shows all of the ships of this class (starting at 0)." );
            ch_println( ch, "&B SPACE     &z- Shows all the ships in space." );
            ch_println( ch, "&B LEGENDARY &z- Shows all legendary ships." );
            ch_println( ch, "&B TRAFFIC   &z- Shows all traffic ships." );
        }

        return;
    }

    return;
}

CMDF do_allships( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    int count = 0;

    if ( !str_cmp( argument, "kill now" ) && get_trust( ch ) >= LEVEL_ADMIN )
    {
        int shiptime = 10;

        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( xIS_SET( ship->flags, SHIP_NODELETE ) || xIS_SET( ship->flags, SHIP_LEGENDARY ) || xIS_SET( ship->flags, SHIP_INVINCIBLE )  || xIS_SET( ship->flags, SHIP_NO_SELFD ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) || xIS_SET( ship->flags, SHIP_SIMULATOR ) )
                continue;

            if ( is_pirate( ship ) || is_public(ship))
                continue;

            shiptime += 1;
            ship->selfd_time = shiptime;
            ship->selfd_armed = TRUE;
        }

        ch_println( ch, "&YAll self-destruct modules engaged. 5 minute(s) to detonation." );
        return;
    }

    if ( !str_cmp( argument, "stop now" ) && get_trust( ch ) >= LEVEL_ADMIN )
    {
        for ( ship = first_ship; ship; ship = ship->next )
        {
            ship->selfd_time = 0;
            ship->selfd_armed = FALSE;
        }

        ch_println( ch, "&YAll self-destruct modules aborted. Have a nice day." );
        return;
    }

    count = 0;
    ch_println( ch, "&Y\nThe following ships are currently formed:" );
    ch_println( ch, "&zShip Name:                           Owner:          Cost&w/&zRent:&w" );

    for ( ship = first_ship; ship; ship = ship->next )
    {
        if ( ship->classtype > SATELLITE_SHIP )
            continue;

        pager_printf( ch, "&B %-34s %-15s ", ship->name, ship->shipowner );

        if ( ship->classtype > PLATFORM_SHIP )
        {
            pager_println( ch, "&z[&w----------&z]&w" );
            continue;
        }

        if ( !str_cmp( ship->shipowner, "Public" ) || !str_cmp( ship->shipowner, "public" ) )
            pager_println( ch, "&C%ld&z to rent.&w", get_ship_value( ship ) / 100 );
        else if ( !str_cmp( ship->shipowner, "Trainer" ) )
            pager_println( ch, "&z[&CSimulator&z]&w" );
        else if ( str_cmp( ship->shipowner, "" ) )
            pager_println( ch, "%s", "&z[&CPurchased&z]&w" );
        else
            pager_println( ch, "&C%ld&z to buy.&w", get_ship_value( ship ) );

        count++;
    }

    if ( count <= 0 )
        pager_println( ch, "&zThere are &Rno&z ships currently formed.&w" );
    else
        pager_println( ch, "&zThere are &C%d&z ships currently in existence.&w", count );

    return;
}

CMDF do_pubbie_set( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    SHIP_DATA* ship;
    bool found = FALSE;

    for ( ship = first_ship; ship; ship = ship->next )
    {
        if ( str_cmp( "public", ship->shipowner ) || str_cmp( "Public", ship->shipowner ) )
            continue;

        if ( ship->shipyard == 2400 )
            continue;

        found = TRUE;
        ship->shipyard = 2400;
    }

    if ( found )
    {
        ch_println( ch, "Public shuttle's shipyard value reset to default." );
        return;
    }

    if ( !found )
    {
        ch_println( ch, "All of your pubbies have default shipyard." );
        return;
    }
}
CMDF do_clear_pubbies( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    int shiptime = ( 600 ); //10 minutes
    bool found = FALSE;

    if ( !str_cmp( "abort", argument ) )
    {
        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( "public", ship->shipowner ) || str_cmp( "Public", ship->shipowner ) )
                continue;

            if ( ship->selfd_time < 1 || ( !ship->selfd_armed ) )
                continue;

            found = TRUE;
            xREMOVE_BIT( ship->flags, SHIP_NODELETE );
            ship->selfd_time = 0;
            ship->selfd_armed = FALSE;
        }

        if ( found )
        {
            ch_println( ch, "All pubbie's selfdestruct module disengaged." );
            return;
        }

        if ( !found )
        {
            send_to_char( "Error! No pubbies found with selfdestruct engaged.", ch );
            return;
        }
    }
    else if ( !str_cmp( "confirm", argument ) )
    {
        for ( ship = first_ship; ship; ship = ship->next )
        {
            if ( str_cmp( "public", ship->shipowner ) || str_cmp( "Public", ship->shipowner ) )
                continue;

            if ( ship->pilot && ship->pilot[0] != '\0' )
                continue;

            found = TRUE;
            xREMOVE_BIT( ship->flags, SHIP_NODELETE );
            ship->selfd_time = shiptime++;
            ship->selfd_armed = TRUE;
            SET_STRING( ship->shipowner, "" ); //this is never normally null
            ship->clan = NULL;
            echo_to_ship_main( AT_BLOOD, ship, "This public ship has been targeted for recycling. It will blow up in 10 minutes." );
        }

        if ( found )
            ch_println( ch, "&YAll selfdestruct modules engaged. 10 minute to detonation." );

        if ( !found )
            ch_println( ch, "&YError! No public vessels found." );

        return;
    }
    else
        ch_println( ch, "Usage: Clearpubbies Confirm to initiate.\n       Clearpubbies Abort to stop." );

    return;
}

void ship_to_starsystem( SHIP_DATA* ship, SPACE_DATA* starsystem )
{
    SHIP_DATA* temp = NULL;
    int cnt = 0;

    if ( !ship || !starsystem )
        return;

    if(ship->starsystem == starsystem) 
        return;

    if ( ship->starsystem )
        ship_from_starsystem( ship );

    if ( ship->in_room )
        ship_from_room( ship );

    SET_STRING( ship->home, starsystem->name );

    for ( temp = starsystem->first_ship; temp; temp = temp->next_in_starsystem )
    {
        if ( ++cnt > 99999 )
        {
            bug( "ship_to_starsystem: starsystem ship scan fault. Infinite loop aborted." );
            return;
        }

        if ( temp == ship )
        {
            bug( "ship_to_starsystem: ship already exists in system array. Aborting link." );
            ship->starsystem = starsystem;
            return;
        }
    }

    LINK( ship, starsystem->first_ship, starsystem->last_ship, next_in_starsystem, prev_in_starsystem );
    ship->starsystem = starsystem;
}

void start_tractor( SHIP_DATA* ship, SHIP_DATA* target, int power, HANGAR_DATA* hangar )
{
    TRACTOR_DATA* tractor;
    SPACE_DATA* starsystem;

    if ( ship == NULL || target == NULL )
        return;

    if ( ( starsystem = ship->starsystem ) == NULL )
        return;

    CREATE( tractor, TRACTOR_DATA, 1 );
    LINK( tractor, first_tractor, last_tractor, next, prev );
    tractor->owner = ship;
    tractor->target = target;
    tractor->age = 0;
    tractor->power = power;
    tractor->distance = vector_distance( &ship->vpos, &target->vpos );
    tractor->hangar = hangar;

    if ( starsystem->first_tractor == NULL )
        starsystem->first_tractor = tractor;

    if ( starsystem->last_tractor )
    {
        starsystem->last_tractor->next_in_starsystem = tractor;
        tractor->prev_in_starsystem = starsystem->last_tractor;
    }

    starsystem->last_tractor = tractor;
    tractor->starsystem = starsystem;
}

