    bool hasnode = FALSE;

    if ( !ship || !ship->starsystem )
        return;

    SPACE_DATA* starsystem = ship->starsystem;

    if ( ship->dockship )
    {
        ship->dockship->dockship   = NULL;
        ship->dockship->dock_state = DOCK_READY;
        ship->dockship->dock_lead  = FALSE;
        ship->dockship   = NULL;
        ship->dock_state = DOCK_READY;
        ship->dock_lead  = FALSE;
    }

    LINK_HASNODE( ship->starsystem->first_ship, SHIP_DATA, next_in_starsystem, ship, hasnode );
    if ( hasnode ) UNLINK( ship, starsystem->first_ship, starsystem->last_ship, next_in_starsystem, prev_in_starsystem );
    ship->starsystem = NULL;
    return;
}

