bool is_rental( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( is_public( ship ) && ch && ch->in_room && ch->in_room->area && !xIS_SET( ch->in_room->area->flags, AFLAG_NEWBIE ) )
        return TRUE;

    if ( is_training( ship ) && ch && ch->in_room && ch->in_room->area && xIS_SET( ch->in_room->area->flags, AFLAG_NEWBIE ) )
        return TRUE;

    if ( !str_cmp( "Rental", ship->shipowner ) )
        return FALSE;

    return FALSE;
}

bool check_pilot( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( get_trust( ch ) >= sysdata.log_level )
        return TRUE;

    if ( !str_cmp( ch->name, ship->shipowner ) || !str_cmp( ch->name, ship->pilot )
            || !str_cmp( ch->name, ship->copilot ) || !str_cmp( "Public", ship->shipowner )
            || !str_cmp( "public", ship->shipowner )
            //    || !str_cmp( ch->name, ship->stolen )
            || !str_cmp( "Trainer", ship->shipowner ) )
        return TRUE;

    if ( ch->pcdata && ch->pcdata->bestowments && has_pcflag( ch, PCFLAG_CG ) && !str_cmp( "cg", ship->shipowner ) )
        return TRUE;

    /*
        Clan Checks
    */
    if ( check_clanpilot( ch, ship ) )
        return TRUE;

    if ( in_squadron( ship ) && ship != ship->squadleader && check_pilot( ch, ship->squadleader ) )
        return TRUE;

    return FALSE;
}
bool is_stolen( CHAR_DATA* ch, SHIP_DATA* ship )
{
    return is_stolen_ship( ch, ship, NULL );
    //return !str_cmp(ch->name, ship->stolen);
}
bool check_clanpilot( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( is_cg( ch ) )
    {
        if ( ch->team == 0 || str_cmp( "cg", ship->shipowner ) )
            return FALSE;

        switch ( ch->team )
        {
            case 1:
                return ( strstr( ship->name, "Red" ) ? TRUE : FALSE );

            case 2:
                return ( strstr( ship->name, "Blue" ) ? TRUE : FALSE );

            case 3:
                return ( strstr( ship->name, "Black" ) ? TRUE : FALSE );

            case 4:
                return ( strstr( ship->name, "Green" ) ? TRUE : FALSE );

            default:
                return FALSE;
        }
    }

    if ( !IS_NPC( ch ) && in_clan( ch ) )
    {
        if ( !str_cmp( ch->pcdata->clan->name, ship->shipowner ) )
        {
            if ( !str_cmp( ch->pcdata->clan->leader, ch->name ) )
                return TRUE;

            if ( !str_cmp( ch->pcdata->clan->number1, ch->name ) )
                return TRUE;

            if ( !str_cmp( ch->pcdata->clan->number2, ch->name ) )
                return TRUE;

            if ( is_empowered( ch, "pilot" ) && ship->classtype <= CORVETTE_SHIP )
                return TRUE;

            if ( is_empowered( ch, "bigpilot" ) && ship->classtype >= FRIGATE_SHIP )
                return TRUE;
        }
    }

    return FALSE;
}

bool ship_from_room( SHIP_DATA* ship )
{
    ROOM_INDEX_DATA* room = NULL;
    SHIP_DATA* tship = NULL;
    char buf[MIL];

    if ( !ship || !ship->in_room )
        return FALSE;

    room = ship->in_room;
    ship->in_room = NULL;

    for ( tship = room->first_ship; tship; tship = tship->next_in_room )
        if ( tship == ship )
            break;

    if ( !tship )
    {
        snprintf( buf, MIL, "%s: ship %s shows in room %d but not found there.", FUNC, !NULLSTR( ship->name ) ? ship->name : "(null)", room->vnum );
        write_to_log( FUNC, buf, sysdata.log_level, 168, true );
        return FALSE;
    }

    UNLINK( ship, room->first_ship, room->last_ship, next_in_room, prev_in_room );
    return TRUE;
}

/*
    Deals ION Blast damage to ships
    6x the damage to shields
    NO damage to hull
    5x the chance of disabling ship systems

    This was fun to write =)   <->Ghost<->
*/
void damage_ship_ion( SHIP_DATA* ship, int min, int max, SHIP_DATA* attacker )
{
    int damage, shield_dmg;
    char buf[MSL];

    if ( ship == NULL )
        return;

    if ( xIS_SET( ship->flags, SHIP_INVINCIBLE ) )
        return;

    min = UMAX( 1, min );
    max = UMAX( 1, max );
    damage = number_range( min, max );
    int orig_damage = damage;

    /*
        Energy Drain on *ALL* Systems =)
    */
    ship->energy = URANGE( 0, ship->energy - ( damage / 5 ), ship->energy );

    if ( ship->shield > 0 )
    {
        shield_dmg = UMIN( ship->shield, damage * 2 );
        damage -= shield_dmg;
        ship->shield -= shield_dmg;

        if ( ship->shield == 0 )
        {
            echo_to_ship_windows( AT_RED, ship, "[WARNING]: Critical power overload... Shields down!\n" );
            snprintf( buf, MSL, "%ss shields shine brightly as they fail.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
    }

    if ( xIS_SET( ship->flags, SHIP_OBJECT ) || xIS_SET( ship->flags, SHIP_VONG ) )
        return;

    int squadaim_target = ( attacker && attacker->squadleader && attacker->squadleader->squad_aim ) ?
                          attacker->squadleader->squad_aim : SQUADAIM_NONE;
    bool squadaim_success = false;
    if ( squadaim_target != SQUADAIM_NONE )
    {
        // Ions go from 10-30 damage, this math averages 2% chance per hit.
        // With a full squadron of 6, that's 12% per ion shot fired.
        int squadaim_chance = orig_damage;
        squadaim_success = number_range( 1, 1000 ) <= squadaim_chance;
        tune( "squadaim: %s had %.1f%% chance to disable system on %s and %s (ion)", attacker ? attacker->name : "(unknown)",
              squadaim_chance / 10.0, ship->name, squadaim_success ? "succeeded" : "failed" );
    }

    if (
        ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && 
        damage > 0 && number_percent() <= 15
    )
    {
        echo_to_ship_windows( AT_RED, ship, "Ship drive DAMAGED!\n" );
        snprintf( buf, MSL, "Flames erupt from %ss engines. They appear to be damaged heavily.", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        ship->shipstate = SHIP_DISABLED;

        // Disabling halts autopiloted ships to better support boarding scenarios
        if ( ship->autopilot )
            ship->currspeed = 0;
    }

    if (
        ship->missilestate < MISSILE_DAMAGED && ship->missiletubes > 0 &&
        (
            ( damage > 0 && number_percent() <= 25 ) ||
            ( squadaim_target == SQUADAIM_LAUNCHER && squadaim_success )
        )
    )
    {
        echo_to_ship_windows( AT_RED, ship, "Ship missile launcher DAMAGED!" );
        snprintf( buf, MSL, "%ss missile tubes are immobilized!", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        ship->missilestate = MISSILE_DAMAGED;
        ship->spent_tubes = ship->missiletubes;
    }

    if (
        ship->laser_charge >= LASER_READY && ( ship->blasters > 0 || ship->lasers > 0 || ship->turbolasers > 0 ) &&
        (
            ( damage > 0 && number_percent() <= 15 ) ||
            ( squadaim_target == SQUADAIM_LASER && squadaim_success )
        )
    )
    {
        echo_to_ship_windows( AT_RED, ship, "Ship's lasers DAMAGED!" );
        snprintf( buf, MSL, "%ss lasers spark with ion charge!", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        ship->autoblaster_charge = LASER_DAMAGED;
        ship->laser_charge = LASER_DAMAGED;
        ship->turbolaser_charge = LASER_DAMAGED;
    }

    if (
        ship->ion_charge >= ION_READY && ship->ion > 0 &&
        (
            ( damage > 0 && number_percent() <= 25 ) ||
            ( squadaim_target == SQUADAIM_ION && squadaim_success )
        )
    )
    {
        echo_to_ship_windows( AT_RED, ship, "Ship ion cannons DAMAGED!" );
        snprintf( buf, MSL, "Several of %ss ion cannons surge with an ion charge!", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        ship->ion_charge = ION_DAMAGED;
    }

    if (
        ship->tractorstate < TRACTOR_DAMAGED && ship->tractorbeam > 0 &&
        (
            ( damage > 0 && number_percent() <= 15 ) ||
            ( squadaim_target == SQUADAIM_TRACTOR && squadaim_success )
        )
    )
    {
        echo_to_ship_windows( AT_RED, ship, "Tractor beam DAMAGED!" );
        snprintf( buf, MSL, "%ss tractor beam sparks with an ion charge!", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        ship->tractorstate = TRACTOR_DAMAGED;
    }

    int working_turret_count = 0;

    for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
    {
        if ( turret->laserstate > LASER_DAMAGED )
            working_turret_count++;
    }

    if (
        working_turret_count > 0 &&
        (
            ( damage > 0 && number_percent() <= 25 ) ||
            ( squadaim_target == SQUADAIM_TURRET && squadaim_success )
        )
    )
    {
        int exploding_turret_idx = number_range( 1, working_turret_count );
        int turret_idx = 0;

        for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
        {
            turret_idx++;

            if ( turret->laserstate <= LASER_DAMAGED )
                continue;

            exploding_turret_idx--;

            if ( exploding_turret_idx > 0 )
                continue;

            if ( turret->room )
            {
                echo_to_room( AT_BLOOD, turret->room, "A blinding flash of light fills the turret..." );
                echo_to_room( AT_BLOOD, turret->room, "The consoles fizzle and die, the systems overloaded." );
                echo_to_room( AT_BLOOD, turret->room, "The cannon grinds to a halt, refusing to respond or fire." );
                snprintf( buf, MSL, "Turret %d has been disabled!", turret_idx );
                echo_to_ship_windows( AT_RED, ship, buf );
            }

            snprintf( buf, MSL, "One of %ss turrets sparks with an ion charge!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            turret->laserstate = LASER_DAMAGED;
            break;
        }
    }

    if ( damage > 0 && number_percent() < 96 )
    {
        if ( ship->cloakstatus == CLOAK_READY )
        {
            echo_to_ship_windows( AT_RED, ship, "Cloaking device DAMAGED!\n" );
            snprintf( buf, MSL, "A field flares over %s, but disappears.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->cloakstatus = CLOAK_DAMAGED;
        }

        if ( ship->cloakstatus == CLOAK_ON )
        {
            echo_to_ship_windows( AT_RED, ship, "Cloaking device DAMAGED!\n" );
            echo_to_ship_main( AT_BLUE, ship, "[Alert] Cloaking Devices Deactivating!" );
            snprintf( buf, MSL, "Explosions in space loom eerily as a field around %s deactivates!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->cloakstatus = CLOAK_DAMAGED;
            snprintf( buf, MSL, "%s shimmers into existence.", ship->name );
            echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
        }
    }
}

