char* fleet_location_string( SHIP_DATA* ship )
{
    static char locstr[100];

    if ( ship->starsystem && ship->starsystem->virtualsys )
        snprintf( locstr, 100, "%d %d", ship->starsystem->xpos, ship->starsystem->ypos );
    else if ( ship->starsystem )
        snprintf( locstr, 100, "%s", ship->starsystem->name );
    else if ( ship->in_room )
        snprintf( locstr, 100, "Landed" );
    else
        snprintf( locstr, 100, "Hyperspace" );

    return locstr;
}

int squadron_remove( SHIP_DATA* ship, CHAR_DATA* ch )
{
    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( !in_squadron( ship ) )
    {
        ch_println( ch, "&RThis ship isn't in a squadron." );
        return E_LOTJ_NOTHING_TO_DO;
    }
    else if ( is_squadleader( ship ) )
    {
        for ( SHIP_DATA* s = ship->first_in_squad; s; s = s->next_in_squad )
        {
            if ( s == ship )
                continue;

            echo_to_ship_main( AT_ACTION, s, "Your squadron has been disbanded." );
        }

        remove_from_squad( ship );
        ch_println( ch, "&wSquadron disbanded." );
    }
    else
    {
        message_to_squadleader( ship, "Ship leaving the squadron, channel closed." );
        remove_from_squad( ship );
        ch_println( ch, "&wYou have removed this ship from its squadron." );
    }

    return E_LOTJ_SUCCESS;
}

CMDF do_squadron( CHAR_DATA* ch, char* argument )
{
    char cmd[MIL];
    SHIP_DATA* ship = get_ship_from_room( ch->in_room );

    if ( !ship || ship->classtype != FIGHTER_SHIP || ch->in_room->vnum != ship->cockpit )
    {
        ch_println( ch, "&RYou must be in a fighter cockpit to manage squadrons." );
        return;
    }

    if ( !check_pilot( ch, ship ) )
    {
        ch_println( ch, "&RYou need piloting permission on this ship to manage its squadron." );
        return;
    }

    argument = one_argument( argument, cmd );

    if ( !str_cmp( cmd, "add" ) )
    {
        SHIP_DATA* target = NULL;

        if ( !ship->in_room )
            ch_println( ch, "&RYou must be landed to add or remove squadron members." );
        else if ( NULLSTR( argument ) )
            ch_println( ch, "&wAdd which ship to your squadron?" );
        else if ( ( target = ship_in_room( ship->in_room, argument ) ) == NULL )
            ch_println( ch, "&RThere's no ship with that name landed alongside yours." );
        else if ( !check_pilot( ch, target ) )
            ch_println( ch, "&RYou aren't authorized to pilot that ship." );
        else if ( target->classtype > FIGHTER_SHIP )
            ch_println( ch, "&ROnly fighters can be added to a squadron." );
        else if ( target->template != ship->template )
            ch_println( ch, "&RAll ships in a squadron must be the same type of fighter." );
        else if ( target->squadleader )
            ch_println( ch, "&RThat ship is already part of a squadron." );
        else if ( target == ship )
            ch_println( ch, "&RYou can't add your own ship to your squadron." );
        else if ( str_cmp( target->shipowner, ship->shipowner ) )
            ch_println( ch, "&RThe ships must have the same owner." );
        else if ( ship->squadleader && ship->squadleader != ship )
            ch_println( ch, "&RThis ship is already part of a squadron. Leave that one first before forming a squadron around it." );
        else if ( ship->template->squadronmax <= 1 )
            ch_println( ch, "&RThis fighter doesn't have squadron coordination support." );
        else if ( count_squadron_members( ship ) >= ship->template->squadronmax )
            ch_println( ch, "&RThis fighter can only coordinate %d ships in a squadron.", ship->template->squadronmax );
        else
        {
            add_to_squad( target, ship );
            ch_println( ch, "&w%s has been added to your squadron.", target->name );
        }
    }
    else if ( !str_cmp( cmd, "remove" ) )
    {
        SHIP_DATA* target = NULL;

        if ( NULLSTR( argument ) )
            ch_println( ch, "&wRemove which ship from your squadron?" );
        else if ( ship->squadleader != ship )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else
        {
            target = get_squadron_member( ship, argument, false );

            if ( !target )
                ch_println( ch, "&RThere's no ship with that name in your ship's squadron." );
            else
            {
                remove_from_squad( target );
                ch_println( ch, "&w%s has been removed from your squadron.", target->name );
            }
        }
    }
    else if ( !str_cmp( cmd, "status" ) )
    {
        if ( ship->squadleader != ship )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else
        {
            ch_println( ch, "&WLead: &C%s", ship->name );
            ch_println( ch, "      &zEnergy: &Y%3d%%   &zShield: &C%3d%%   &zHull: &G%3d%%   &zLocation: &W%s",
                       ship->energy * 100 / ship->maxenergy,
                       ship->maxshield > 0 ? ship->shield * 100 / ship->maxshield : 0,
                       ship->hull * 100 / ship->maxhull,
                       fleet_location_string( ship ) );

            for ( SHIP_DATA* s = ship->first_in_squad; s; s = s->next_in_squad )
            {
                if ( s == ship )
                    continue;

                ch_println( ch, "&C%s", s->name );
                ch_println( ch, "      &zEnergy: &Y%3d%%   &zShield: &C%3d%%   &zHull: &G%3d%%   &zLocation: &W%s",
                           s->energy * 100 / s->maxenergy,
                           s->maxshield > 0 ? s->shield * 100 / s->maxshield : 0,
                           s->hull * 100 / s->maxhull,
                           fleet_location_string( s ) );
            }

            ch_println( ch, "&zSquadron Fire Assist: %s        &zSystems Target: &C%s", ship->squadassist ? "&RActive" : "&CDisabled", capitalize( squadaim_name[ship->squad_aim] ) );
        }
    }
    else if ( !str_cmp( cmd, "assist" ) )
    {
        if ( !is_squadleader( ship ) )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else
        {
            if ( ship->squadassist )
                ch_println( ch, "&wSquadron fire assist disabled. Your wing ships will not fire weapons." );
            else
                ch_println( ch, "&wSquadron fire assist enabled. Your wing ships will mirror your attacks when possible." );

            ship->squadassist = !ship->squadassist;
            save_ship( ship, true );
        }
    }
    else if ( !str_cmp( cmd, "aim" ) )
    {
        if ( !is_squadleader( ship ) )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else
        {
            int syscode = -1;

            for ( int i = 0; i < MAX_SQUADAIM; i++ )
            {
                if ( !strcmp( squadaim_name[i], argument ) )
                {
                    syscode = i;
                    break;
                }
            }

            if ( syscode == -1 )
            {
                ch_println( ch, "&wAim at which system? Options: &Cnone, launcher, laser, ion, turret, tractor" );
                return;
            }

            ship->squad_aim = syscode;
            ch_println( ch, "&wSquadron system target set." );

            if ( syscode != SQUADAIM_NONE )
                ch_println( ch, "&wNote: This will persist across targets, reset it using &Csquadron aim none&w." );

            save_ship( ship, true );
        }
    }
    else if ( !str_cmp( cmd, "exit" ) )
        squadron_remove( ship, ch );
    else if ( !str_cmp( cmd, "roll" ) )
    {
        if ( !is_squadleader( ship ) )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else if ( !ship->starsystem )
            ch_println( ch, "&RYou must be in space to issue that command." );
        else
        {
            ch_println( ch, "&wYou order your squadron to execute a roll maneuver..." );
            cache_skill( "roll", &skill_roll );
            int skill = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, skill_roll ) );

            for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( sq->starsystem != ship->starsystem || !should_follow_squadleader( sq, ship ) )
                    continue;

                roll_ship( sq, skill );
            }
        }
    }
    else if ( !str_cmp( cmd, "chaff" ) )
    {
        if ( !is_squadleader( ship ) )
            ch_println( ch, "&RThis ship isn't a squadron leader." );
        else if ( !ship->starsystem )
            ch_println( ch, "&RYou must be in space to issue that command." );
        else
        {
            ch_println( ch, "&wYou order your squadron to launch chaff..." );

            for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( sq->starsystem != ship->starsystem || !should_follow_squadleader( sq, ship ) )
                    continue;

                if ( sq->chaff <= 0 )
                    message_to_squadleader( sq, "I'm all out of chaff." );
                else
                {
                    sq->chaff--;
                    sq->chaff_time = 20;
                    message_to_squadleader( sq, "Chaff deployed!" );
                }
            }
        }
    }
    else
    {
        ch_println( ch, "&zSyntax: &Csquadron add <&wship name&C>    &z: &wAdd a nearby ship to your squadron" );
        ch_println( ch, "&z        &Csquadron remove <&wship name&C> &z: &wRemove a ship from your squadron" );
        ch_println( ch, "&z        &Csquadron status             &z: &wShow squadron status from the lead ship" );
        ch_println( ch, "&z        &Csquadron assist             &z: &wToggle squadron assistance during combat" );
        ch_println( ch, "&z        &Csquadron aim <&wsystem&C>       &z: &wTarget a specific system on your target" );
        ch_println( ch, "&z        &Csquadron exit               &z: &wRemove this ship from its squadron" );
        ch_println( ch, "&z        &Csquadron <&wroll, chaff&C>" );
        return;
    }
}

void message_to_squadleader( SHIP_DATA* ship, const char* msg )
{
    if ( !ship->squadleader || is_squadleader( ship ) || ship->piloting )
        return;

    char buf[MIL];
    snprintf( buf, MIL, "&z[&WSquadron&z] &C%s&W: &w%s", ship->name, msg );
    echo_to_ship_main( AT_CYAN, ship->squadleader, buf );
}

/**
    @param ship Ship which is taking damage
    @param ch Character to attribute the damage to (nullable)
    @param attacker Ship which did the damage (nullable)
    @param type The squeue type
    @param count The number of hits being applied (min/max still represents the total, not per-hit)
    @return true if ship was destroyed
*/
bool damage_ship_full( SHIP_DATA* ship, int min, int max, CHAR_DATA* ch, SHIP_DATA* attacker, int type, int count )
{
    char buf[MSL];
    int dam, shield_dmg;
    long xp;
    CLAN_DATA* aclan = NULL;
    CLAN_DATA* sclan = NULL;

    if ( ship_extracted( ship ) )
        return false;

    if ( ch && char_extracted( ch ) )
        ch = NULL;

    if ( attacker && ship_extracted( attacker ) )
        attacker = NULL;

    if ( xIS_SET( ship->flags, SHIP_INVINCIBLE ) || xIS_SET( ship->flags, SHIP_NADESONLY ) )
        return false;

    min = UMAX( 1, min );
    max = UMAX( 1, max );
    dam = number_range( min, max );

    if ( ship->shield > 0 )
    {
        shield_dmg = UMIN( ship->shield, dam );
        dam -= shield_dmg;
        ship->shield -= shield_dmg;

        if ( ship->shield == 0 )
        {
            echo_to_ship_windows( AT_RED, ship, "[WARNING]: Critical power overload... Shields down!\n" );
            snprintf( buf, MSL, "%ss shields shine brightly as they fail.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
    }

    if ( dam > 0 )
    {
        ship->hull -= dam;

        if ( ship->hull <= 0 )
        {
            if ( ch )
            {
                int pilot_level = ch->skill_level[PILOTING_ABILITY];
                int xp_per_level = ( exp_level( pilot_level + 1 ) - exp_level( pilot_level ) );
                // Fighters tend to be 200k value, corvettes+ tend to be 700k.
                // xp/level tops out at about 150k at level 150
                xp = UMIN( get_ship_value( ship ) / 6, xp_per_level );

                // Stop people from going past level 40 just by using simulators
                if ( xIS_SET( ship->flags, SHIP_SIMULATOR ) && pilot_level >= 20 )
                {
                    // level 21: -5%
                    // level 22: -10%
                    // level 40: -100%
                    xp -= xp * (pilot_level-20)*0.05;
                }

                if ( xp > 0 )
                {
                    gain_exp( ch, xp, PILOTING_ABILITY, TRUE );
                    ch_println( ch, "&WYou gain %ld piloting experience!", xp );
                }
            }

            if ( attacker )
            {
                //This next few lines is to increase the killcount of a ship. Only capitals can acquire killcounts, and squadron kills contribute to the killcount of their cappie lead.
                //Killcounts can only be increased by destroying capitals of a warring clan. Killcounts are currently used to determine a capital's "Veteran" status, and grants bonuses based on killcount - Gathorn 2 Sept 17
                aclan = attacker->clan;
                sclan = ship->clan;

                if ( aclan && sclan && enemy_clan ( aclan, sclan ) )
                {
                    if ( ship->classtype >= FRIGATE_SHIP && attacker->classtype >= FRIGATE_SHIP )
                        attacker->killcount += 1;
                }
            }

            snprintf( buf, MSL, "ship combat" );

            if ( ship->squadleader && !ship->piloting )
            {
                switch ( number_range( 1, 4 ) )
                {
                    case 1:
                        message_to_squadleader( ship, "I'm going down!" );
                        break;

                    case 2:
                        message_to_squadleader( ship, "They came from... behind..." );
                        break;

                    case 3:
                        message_to_squadleader( ship, "Whew, that was a close-- *static*" );
                        break;

                    case 4:
                        message_to_squadleader( ship, "AAIIEEEeeEEeeee!!!" );
                        break;
                }
            }

            destroy_ship( ship, attacker, ch, buf );
            return true;
        }
    }

    if ( !xIS_SET( ship->flags, SHIP_OBJECT ) && !xIS_SET( ship->flags, SHIP_VONG ) )
    {
        int squadaim_target = ( attacker && attacker->squadleader && attacker->squadleader->squad_aim ) ?
                              attacker->squadleader->squad_aim : SQUADAIM_NONE;
        bool squadaim_success = false;
        if ( squadaim_target != SQUADAIM_NONE )
        {
            int squadaim_chance = 0;
            if ( type == SQUEUE_AUTO_HIT )
                squadaim_chance = 1; // Don't multiply by count since these are so numerous already
            else if ( type == SQUEUE_LASER_HIT )
                squadaim_chance = 5 * count;
            else if ( type == SQUEUE_MISSILE_HIT )
                squadaim_chance = 5 * count;
            else if ( type == SQUEUE_TORPEDO_HIT )
                squadaim_chance = 10 * count;
            else if ( type == SQUEUE_ROCKET_HIT )
                squadaim_chance = 20 * count;

            squadaim_success = number_range( 1, 1000 ) <= squadaim_chance;
            tune( "squadaim: %s had %.1f%% chance to disable system on %s and %s", attacker ? attacker->name : "(unknown)",
                squadaim_chance / 10.0, ship->name, squadaim_success ? "succeeded" : "failed" );
        }

        if (
            ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && (
                (
                    dam > 0 && number_percent() <= 15 && ship->hull < ship->maxhull * 0.65 ) || // Chance to disable if hull is somewhat damaged
                ship->hull < ship->maxhull * 0.25 // Guaranteed disable if hull is very damaged
            )
        )
        {
            echo_to_ship_windows( AT_RED, ship, "Ship drive DAMAGED!\n" );
            snprintf( buf, MSL, "Flames erupt from %ss engines. They appear to be damaged heavily.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->shipstate = SHIP_DISABLED;

            // Disabling halts autopiloted ships to better support boarding scenarios
            if ( ship->autopilot )
                ship->currspeed = 0;
        }

        if (
            ship->missilestate < MISSILE_DAMAGED && ship->missiletubes > 0 &&
            (
                ( dam > 0 && number_percent() <= 25 && ship->hull < ship->maxhull * 0.45 ) ||
                ( squadaim_target == SQUADAIM_LAUNCHER && squadaim_success )
            )
        )
        {
            echo_to_ship_windows( AT_RED, ship, "Ship missile launcher DAMAGED!" );
            snprintf( buf, MSL, "Several of %ss missile tubes are destroyed.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->missilestate = MISSILE_DAMAGED;
            ship->spent_tubes = ship->missiletubes;
        }

        if (
            ship->laser_charge >= LASER_READY && ( ship->blasters > 0 || ship->lasers > 0 || ship->turbolasers > 0 ) &&
            (
                ( dam > 0 && number_percent() <= 20 && ship->hull < ship->maxhull * 0.55 ) ||
                ( squadaim_target == SQUADAIM_LASER && squadaim_success )
            )
        )
        {
            echo_to_ship_windows( AT_RED, ship, "Lasers DAMAGED!" );
            ship->autoblaster_charge = LASER_DAMAGED;
            ship->laser_charge = LASER_DAMAGED;
            ship->turbolaser_charge = LASER_DAMAGED;
            snprintf( buf, MSL, "Several lasers explode on %s!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }

        if (
            ship->tractorstate < TRACTOR_DAMAGED && ship->tractorbeam > 0 &&
            (
                ( dam > 0 && number_percent() <= 20 && ship->hull < ship->maxhull * 0.55 ) ||
                ( squadaim_target == SQUADAIM_TRACTOR && squadaim_success )
            )
        )
        {
            echo_to_ship_windows( AT_RED, ship, "Tractor beam DAMAGED!" );
            snprintf( buf, MSL, "%ss tractor beam is engulfed in flames!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->tractorstate = TRACTOR_DAMAGED;
        }

        int working_turret_count = 0;

        for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
        {
            if ( turret->laserstate > LASER_DAMAGED )
                working_turret_count++;
        }

        if (
            working_turret_count > 0 &&
            (
                ( dam > 0 && number_percent() <= 25 && ship->hull < ship->maxhull * 0.60 ) ||
                ( squadaim_target == SQUADAIM_TURRET && squadaim_success )
            )
        )
        {
            int exploding_turret_idx = number_range( 1, working_turret_count );
            int turret_idx = 0;

            for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
            {
                turret_idx++;

                if ( turret->laserstate <= LASER_DAMAGED )
                    continue;

                exploding_turret_idx--;

                if ( exploding_turret_idx > 0 )
                    continue;

                if ( turret->room )
                {
                    echo_to_room( AT_BLOOD, turret->room, "A blinding flash of light fills the turret..." );
                    echo_to_room( AT_BLOOD, turret->room, "The consoles fizzle and die, the systems overloaded." );
                    echo_to_room( AT_BLOOD, turret->room, "The cannon grinds to a halt, refusing to respond or fire." );
                    snprintf( buf, MSL, "Turret %d has been disabled!", turret_idx );
                    echo_to_ship_windows( AT_RED, ship, buf );
                }

                snprintf( buf, MSL, "One of %ss turrets explodes!", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                turret->laserstate = LASER_DAMAGED;
                break;
            }
        }

        if (
            ship->ion_charge >= ION_READY && ship->ion > 0 &&
            (
                ( dam > 0 && number_percent() <= 25 && ship->hull < ship->maxhull * 0.55 ) ||
                ( squadaim_target == SQUADAIM_ION && squadaim_success )
            )
        )
        {
            echo_to_ship_windows( AT_RED, ship, "Ion cannons DAMAGED!" );
            snprintf( buf, MSL, "Several of %ss ion cannons explode!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->ion_charge = ION_DAMAGED;
        }

        if ( number_percent() < 96 && ship->hull < ship->maxhull * 0.55 )
        {
            if ( ship->cloakstatus == CLOAK_READY )
            {
                echo_to_ship_windows( AT_RED, ship, "Cloaking device DAMAGED!\n" );
                snprintf( buf, MSL, "A field flares over %s, but disappears.", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                ship->cloakstatus = CLOAK_DAMAGED;
            }

            if ( ship->cloakstatus == CLOAK_ON )
            {
                echo_to_ship_windows( AT_RED, ship, "Cloaking device DAMAGED!\n" );
                echo_to_ship_main( AT_BLUE, ship, "[Alert] Cloaking Device deactivating!" );
                snprintf( buf, MSL, "Explosions in space loom eerily as a field around %s deactivates!", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                ship->cloakstatus = CLOAK_DAMAGED;
                snprintf( buf, MSL, "%s shimmers into existence.", ship->name );
                echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
            }
        }
    }

    if ( ship->hull <= ship->maxhull * 0.25 && ship->shield <= 0 )
    {
        if ( xIS_SET( ship->flags, SHIP_OBJECT ) )
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "This object is beginning to fall apart!\n" );

            switch ( number_range( 1, 3 ) )
            {
                case 1:
                    snprintf( buf, MSL, "%s is barely holding together.", ship->name );
                    break;

                case 2:
                    snprintf( buf, MSL, "Large pieces of %s begin to break off!", ship->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "Cracks begin to form across the surface of %s.", ship->name );
                    break;
            }

            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
        else
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "WARNING! Ship hull severely damaged!\n" );

            switch ( number_range( 1, 5 ) )
            {
                case 1:
                    snprintf( buf, MSL, "%s looks like it's going to explode soon!", ship->name );
                    break;

                case 2:
                    snprintf( buf, MSL, "%s is surrounded by explosions!", ship->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "%s tilts oddly, rotating slowly.", ship->name );
                    break;

                case 4:
                    snprintf( buf, MSL, "Several parts of %ss structure are gone!", ship->name );
                    break;

                case 5:
                    snprintf( buf, MSL, "A huge explosion rocks %ss entire frame!", ship->name );
                    break;
            }

            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
    }

    return false;
}

/**
    @param ship Ship which is taking damage
    @param ch Character to attribute the damage to (nullable)
    @param attacker Ship which did the damage (nullable)
    @return true if ship was destroyed
*/
bool damage_ship( SHIP_DATA* ship, int min, int max, CHAR_DATA* ch, SHIP_DATA* attacker )
{
    return damage_ship_full( ship, min, max, ch, attacker, -1, 0 );
}

void blast_radius_space( CHAR_DATA* ch, SPACE_DATA* star, SHIP_DATA* ignore, int x, int y, int z, int base_damage,
                         int radius )
{
    SHIP_DATA* ship, *snext;
    int damage = 0;
    double dam = 0, dist = 0;
    /*
        Malfunctioning, Removed due to excessive damage
    */
    return;

    if ( star == NULL )
        return;

    if ( base_damage <= 0 )
    {
        bug( "blast_radius_space: No base damage defined, exiting..." );
        return;
    }

    if ( radius <= 0 )
    {
        bug( "blast_radius_space: No radius defined, exiting..." );
        return;
    }

    for ( ship = star->first_ship; ship; ship = snext )
    {
        snext = ship->next_in_starsystem;

        if ( ignore != NULL && ship == ignore )
            continue;

        if ( ship->hull <= 0 )
            continue;

        Vector3 tempvec;
        vector_init( &tempvec );
        tempvec.x = x;
        tempvec.y = y;
        tempvec.z = z;
        dist = vector_distance( &tempvec, &ship->vpos );

        if ( dist > radius )
            continue;

        dam = ( 100 - ( ( ( double )( dist ) / ( double )( radius ) ) * 100 ) );
        damage = ( int )( ( ( ( double )( base_damage ) ) / 100 ) * dam );
        damage_ship( ship, damage, damage, ch, NULL );
    }

    return;
}

bool has_envirosuit( CHAR_DATA* ch )
{
    if ( !IS_NPC(ch) && xIS_SET( ch->race->flags, RFLAG_ENVIROSUIT ) )
    {
        return true;
    }

    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
    {
        if ( obj->wear_loc > -1 && xIS_SET( obj->extra_flags, ITEM_ENVIROSUIT ) )
        {
            return true;
        }
    }

    return false;
}

void destroy_ship( SHIP_DATA* ship, SHIP_DATA* attacker, CHAR_DATA* ch, char* cause )
{
    char buf[MSL];
    ROOM_INDEX_DATA* room;
    SQUEUE_DATA* squeue = NULL, *next_squeue = NULL;
    OBJ_DATA* robj, *nobj;
    SHIP_DATA* rship = NULL;
    SHIP_DATA* playership = NULL;
    CHAR_DATA* rch, *rnext;
    PLANET_DATA* planet = NULL;
    DB_DATA* wnted = NULL;
    CLAN_DATA* pClan = NULL, *tClan = NULL;
    bool sunned = !str_cmp( cause, "sunning" ) ? true : false;

    if ( !ship )
    {
        bug( "%s: NULL ship", FUNC );
        return;
    }

    if ( ship_extracted( ship ) || xIS_SET( ship->flags, SHIP_DRYDOCK ) )
        return;

    if ( sorted_queue != NULL )
    {
        for ( int i = 0; i < top_squeue; i++ )
        {
            if ( !sorted_queue[i] )
                continue;

            squeue = sorted_queue[i];

            if ( squeue->dship == ship )
                squeue->dship = NULL;

            if ( squeue->target == ship )
            {
                UNLINK( squeue, first_queue, last_queue, next, prev );
                DISPOSE( squeue );
                sorted_queue[i] = NULL;
            }
        }
    }
    else
    {
        for ( squeue = first_queue; squeue; squeue = next_squeue )
        {
            next_squeue = squeue->next;

            if ( squeue->dship == ship )
                squeue->dship = NULL;

            if ( squeue->target == ship )
            {
                UNLINK( squeue, first_queue, last_queue, next, prev );
                DISPOSE( squeue );
            }
        }
    }


    if ( ch && char_extracted( ch ) )
    {
        bug( "%s: extracted ch %s for ship %s", FUNC, ch->name, ship->name );
        ch = NULL;
    }

    if ( attacker && ship_extracted( attacker ) )
    {
        bug( "%s: invalid attacker", FUNC );
        attacker = NULL;
    }

    if ( ship->dockship != NULL )
    {
        ship->dockship->dockship = NULL;
        ship->dockship->dock_state = DOCK_READY;
        ship->dockship->dock_lead = FALSE;
        ship->dockship = NULL;
        ship->dock_state = DOCK_READY;
        ship->dock_lead = FALSE;
    }

    if (
        !ch &&
        in_squadron( attacker ) &&
        attacker->squadleader != attacker &&
        !attacker->piloting &&
        attacker->squadleader->piloting &&
        attacker->starsystem == attacker->squadleader->starsystem
    )
    {
        switch ( number_range( 1, 4 ) )
        {
            case 1:
                message_to_squadleader( attacker, "Scratch one." );
                break;

            case 2:
                message_to_squadleader( attacker, "Target eliminated." );
                break;

            case 3:
                message_to_squadleader( attacker, "Hah, take that, space dust!" );
                break;

            case 4:
                message_to_squadleader( attacker, "That got 'em!" );
                break;
        }

        ch = attacker->squadleader->piloting;
    }

    /*
        if ( ship->starsystem ) blast_radius_space( ch == NULL ? NULL : ch, ship->starsystem, ship, ship->vx, ship->vy, ship->vz, ship_death_damage(ship), ship_death_radius(ship) );
    */

    if ( ch )
    {
        int prize;
        ch_println( ch, "&RYou destroyed %s!", ship->name );
        if ( ch->in_room )
            playership = get_ship_from_cockpit( ch->in_room );

        if ( !str_cmp( ship->shipowner, "Pirate" ) || !str_cmp( ship->shipowner, "Pirates" )
                || !str_cmp( ship->shipowner, "pirate" ) || xIS_SET( ship->flags, SHIP_PIRATE ) )
        {
            if ( !IS_NPC( ch ) )
            {
                ch->pcdata->pirate_kills++;
                hi_score( ch );
            }

            prize = number_range( 5, 10 ) * 200;

            if ( ship->classtype >= TRANSPORT_SHIP )
                prize = number_range( 25, 45 ) * ( 200 * ship->classtype );

            if ( ship->classtype >= CRUISER_SHIP )
                prize = number_range( 35, 55 ) * 1000;

            if ( ship->classtype >= PLATFORM_SHIP )
                prize = number_range( 80, 160 ) * 1300;

            if ( playership && playership->classtype == FIGHTER_SHIP )
            {
                prize *= 2;
                ch_println( ch, "&YYour reward is doubled due to the skill with which you displayed in the starfighter!&w" );
            }

            ch_println( ch, "&YYou collect %d credits for killing a wanted criminal.&w", prize );
            ch->gold += prize;

            if ( !IS_NPC( ch ) )
                sql_credits_log( ch->name, "destroy_ship", prize, TRUE );

            do_save( ch, "-noalert" );
            ship->location = ship->shipyard;
            ship->shipstate = SHIP_DOCKED;
            ship->lastdoc = ship->shipyard;
        }
    }
    SHIPDEATH_DATA* db = NULL;
    if ( !xIS_SET( ship->flags, SHIP_SPAWNED ) &&
    !xIS_SET( ship->flags, SHIP_OBJECT ) &&
    !is_pirate( ship ) &&
    !xIS_SET( ship->flags, SHIP_SIMULATOR ) &&
    ( ship_is_owned( ship ) || NULLSTR( ship->shipowner ) || !str_cmp( ship->shipowner, "public" ) ) &&
    str_cmp( cause, "lua prog" ) )
    {
        CREATE( db, SHIPDEATH_DATA, 1 );
        db->id = 0;
        SET_STRING( db->name, !NULLSTR( ship->name ) ? ship->name : "" );
        db->ship_id = ship->id;
        SET_STRING( db->owner, !NULLSTR( ship->shipowner ) ? ship->shipowner : "" );
        SET_STRING( db->pilot, ship->piloting ? ship->piloting->name : "" );
        SET_STRING( db->occupants, get_ship_occupants( ship ) );
        // db->casualties handled later
        SET_STRING( db->cause, !NULLSTR( cause ) ? cause : "" );
        SET_STRING( db->enemy_ship, ( attacker && !NULLSTR( attacker->name ) ) ? attacker->name : "" );
        SET_STRING( db->enemy_pilot, ( attacker && attacker->piloting ) ? attacker->piloting->name : "" );
        SET_STRING( db->killshot, ch ? ( !IS_NPC( ch ) ? ch->name : ch->short_descr ) : "" );
        SET_STRING( db->location, ship->in_room ? "room" : ( ship->starsystem ? "system" : ( ship->shipstate == SHIP_HYPERSPACE ? "hyperspace" : "other" ) ) );
        db->vnum = ship->in_room ? ship->in_room->vnum : 0;
        db->xpos = ship->starsystem ? ship->starsystem->xpos : ship->shipstate == SHIP_HYPERSPACE ? sys_coord_from_galactic_coords(ship->hyper_currentpos.x) : 0;
        db->ypos = ship->starsystem ? ship->starsystem->ypos : ship->shipstate == SHIP_HYPERSPACE ? sys_coord_from_galactic_coords(ship->hyper_currentpos.y) : 0;
        db->first_room = ship->firstroom;
        db->last_room = ship->lastroom;
        // saving and linking handled later
    }
    snprintf( buf, MSL, "%s (Owner: %s) was destroyed by %s!", ship->name, ship->shipowner, cause );

    if ( !xIS_SET( ship->flags, SHIP_SPAWNED ) && !is_pirate( ship ) && !xIS_SET( ship->flags, SHIP_SIMULATOR ) && !xIS_SET( ship->flags, SHIP_VONG ) && !xIS_SET( ship->flags, SHIP_OBJECT ) )
    {
        log_string( buf );

        if ( ch && str_cmp( ch->name, ship->shipowner ) )
        {
            if ( ship->in_room && ship->in_room->area && ship->in_room->area->planet )
                planet = ship->in_room->area->planet;

            if ( !planet && ship->starsystem )
                for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
                    if ( vector_distance( &ship->vpos, &planet->pos ) < 7500 )
                        break;

            if ( planet )
            {
                pClan = ( ch && ch->pcdata && ch->pcdata->clan ) ? ch->pcdata->clan : NULL;
                tClan = ship->clan;

                if ( !pClan || planet->governed_by != pClan )
                {
                    if ( !pClan || !tClan || !nifty_is_name( tClan->name, pClan->atwar ) || !nifty_is_name( pClan->name, tClan->atwar ) )
                    {
                        wnted = set_wanted( ch->name, planet->name, TRUE, CRIME_SHIP_DESTROY );

                        if ( wnted && wnted->num1 == TRUE )
                            ch_println( ch, "&YYou are now wanted for destruction of property on %s.&w", planet->name );
                    }
                }
            }
        }
    }

    if ( ship->starsystem )
    {
        if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
            snprintf( buf, MSL, "%s goes still as it continues its lonely journey through the vacuum of space.", ship->name );
        else if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
            snprintf( buf, MSL, "The beacon atop %s stops flashing as its life support expires. It becomes just another piece of debris in the system.", ship->name );
        else
            snprintf( buf, MSL, "%s explodes in a blinding flash of light!", ship->name );

        echo_to_system_noqueue( AT_RED, ship, buf, NULL );
        auto_jettison( ship );
    }

    lua_trigger_ship_destroyed( ship, attacker, ch );
    char casualties[MSL];
    strlcpy( casualties, "", MSL );

    /*
        Chance to eject
    */
    if ( !sunned && !xIS_SET( ship->flags, SHIP_ENVIROSUIT ) && !xIS_SET( ship->flags, SHIP_SIMULATOR ) )
    {
        if ( ship->classtype == FIGHTER_SHIP || is_public( ship ) || !str_cmp( "Trainer", ship->shipowner ) )
        {
            room = get_room_index( ship->cockpit );

            if ( room )
            {
                for ( rch = room->first_person; rch; rch = rnext )
                {
                    rnext = rch->next_in_room;
                    do_eject( rch, "-auto" );
                }
            }
        }

        // After trying to eject people, go through the whole ship and look for people with an envirosuit.
        // Anyone who failed to eject will still be in the ship.
        if ( ship->shipstate != SHIP_HYPERSPACE && (ship->starsystem || (ship->in_room && starsystem_from_vnum(ship->in_room->vnum) != NULL)) )
        {
            CHAR_DATA* next_rch = NULL;
            for ( room = ship->first_room; room; room = room->next_in_range )
            {
                for ( rch = room->first_person; rch; rch = next_rch )
                {
                    next_rch = rch->next_in_room;

                    if ( has_envirosuit( rch ) )
                        activate_envirosuit( rch, ship );
                }
            }
        }
    }

    if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
    {
        echo_to_ship_main( AT_BLOOD, ship, "As the blood in your veins freezes, your body finally gives in to the cold vacuum of space." );
        echo_to_ship_main( AT_DGREY, ship, "Your heart at last stops beating, your vision fades, and you feel nothing." );
    }
    else if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
    {
        echo_to_ship_main( AT_BLOOD, ship, "As your envirosuit's power depletes, the respiratory refreshes you one last time, but it won't be enough." );
        echo_to_ship_main( AT_DGREY, ship, "Your breathing shallows, your vision fades, and you feel nothing." );
    }
    else if ( xIS_SET( ship->flags, SHIP_SIMULATOR ) )
    {
        echo_to_ship_main( AT_BLUE, ship, "Your vision flickers as the simulation ends." );
    }
    else
    {
        echo_to_ship_main( AT_RED, ship, "You are ripped apart as your spacecraft explodes..." );
    }

    /* GRAL Maybe add the death message to council net etc? */
    sun_killing = true;
    ship->piloting = NULL;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        rch = room->first_person;

        while ( rch != NULL )
        {
            if ( !rch || rch == NULL )
                break;

            if ( IS_IMMORTAL( rch ) || IS_RPC( rch ) )
            {
                char_from_room( rch );

                if ( IS_IMMORTAL( rch ) )
                    char_to_room( rch, get_room_index( ROOM_START_IMMORTAL ) );
                else if ( IS_RPC( rch ) )
                    char_to_room( rch, get_room_index( ROOM_START_RPC ) );
            }
            else if ( xIS_SET( ship->flags, SHIP_SIMULATOR ) )
            {
                char_from_room( rch );
                char_to_room( rch, get_room_index( ROOM_VNUM_LIMBO ) );
                ch_println( rch, "&PThere has been a bug. You should have been evacuated by a prog, but you weren't."
                            "Please inform the staff.\n" );
            }
            else
            {
                if ( !NULLSTR( casualties ) )
                    snprintf( casualties + strlen( casualties ), MSL - strlen( casualties ), ", " );

                snprintf( casualties + strlen( casualties ), MSL - strlen( casualties ), "&R%s &z(%s%s&z)",
                !IS_NPC( rch ) ? rch->name : rch->short_descr,
                !IS_NPC( rch ) ? "&W" : "&Y",
                !IS_NPC( rch ) ? "PC" : "NPC" );

                if ( ch )
                {
                    check_killer( ch, rch );
                    raw_kill( ch, rch );
                }
                else
                    raw_kill( rch, rch );
            }

            rch = room->first_person;
        }

        for ( robj = room->first_content; robj; robj = nobj )
        {
            /*
                Decided not to destroy ship objects.. Rather set their timer
                and move them to the blast chamber. (So we can get corpses)
            */
            nobj = robj->next_content;
            separate_obj( robj );
            obj_from_room( robj );
            robj = obj_to_room( robj, get_room_index( ROOM_BLAST_LIMBO ) );
        }

        while ( ( rship = room->first_ship ) != NULL )
            destroy_ship( rship, attacker, ch, "ship explosion" );
    }

    if ( db )
    {
        SET_STRING( db->casualties, !NULLSTR( casualties ) ? casualties : "" );
        save_shipdeath( db );
        LINK( db, first_shipdeath, last_shipdeath, next, prev );
    }

    sun_killing = false; // Unset this flag, important!

    remove_from_bg( ship );
    remove_from_squad( ship );

    /*
        Clear all target pointers to this ship
    */
    for ( rship = first_ship; rship; rship = rship->next )
    {
        if ( rship == ship )
            continue;

        if ( rship->target0 == ship )
            rship->target0 = NULL;

        if ( rship->target1 == ship )
            rship->target1 = NULL;

        if ( rship->target2 == ship )
            rship->target2 = NULL;

        if ( rship->first_turret )
        {
            TURRET_DATA* turret;

            for ( turret = rship->first_turret; turret; turret = turret->next )
                if ( turret->target == ship )
                    turret->target = NULL;
        }

        if ( rship->leader == ship )
            remove_from_bg( rship );

        if ( rship->squadleader == ship )
            remove_from_squad( rship );
    }

    if ( xIS_SET( ship->flags, SHIP_NODELETE ) || xIS_SET( ship->flags, SHIP_LEGENDARY ) || is_public( ship ) || is_pirate( ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        resetship( ship );
    else if ( xIS_SET( ship->flags, SHIP_SPAWNED ) || xIS_SET( ship->flags, SHIP_SIMULATOR ) || xIS_SET( ship->flags, SHIP_OBJECT ) || NULLSTR( ship->shipowner ) || stristr( ship->shipowner, "spacemob" ) )
        delete_ship( ship );
    else
        drydock( ship );
}

bool ship_to_room( SHIP_DATA* ship, int vnum )
{
    ROOM_INDEX_DATA* shipto = NULL;

    if ( !ship || ship_extracted( ship ) )
        return FALSE;

    if ( ( shipto = get_room_index( vnum ) ) == NULL )
    {
        bug( "ship_to_room: attempting to send %s to nonexistent vnum %d. Sending to %d", ship->name, vnum, ROOM_LIMBO_SHIPYARD );
        shipto = get_room_index( ROOM_LIMBO_SHIPYARD );
    }

    if ( ship->starsystem )
        ship_from_starsystem( ship );

    if ( ship->in_room )
        ship_from_room( ship );

    LINK( ship, shipto->first_ship, shipto->last_ship, next_in_room, prev_in_room );
    ship->in_room = shipto;
    ship->location = shipto->vnum;
    ship->lastdoc = shipto->vnum;
    ship->shipstate = SHIP_DOCKED;
    save_ship( ship, true );
    return TRUE;
}

void print_ship_condition( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( !ch || !ship )
        return;

    int hull_pct = ship->maxhull != 0 ? ( ship->hull * 100 / ship->maxhull ) : 0;

    if ( !ship->maxhull != 0 )
    {
        if ( hull_pct < 25 )
            ch_println( ch, "&RThe ship heaves as you enter. It's barely holding together!" );
        else if ( hull_pct < 50 )
            ch_println( ch, "&YThe ship's structure seems seriously damaged." );
        else if ( hull_pct < 75 )
            ch_println( ch, "&OYou notice some damage to the ship's hull." );
    }

    return;
}

CMDF do_board( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    ROOM_INDEX_DATA* fromroom = NULL;
    ROOM_INDEX_DATA* toroom = NULL;
    VEHICLE_DATA* vec = NULL;
    CHAR_DATA* fch = NULL;
    CHAR_DATA* nextinroom = NULL;
    CHAR_DATA* tch = NULL;
    SHIP_DATA* ship = NULL;
    int chars = 0, count = 0;
    bool sf = TRUE;
    bool carry = FALSE;

    if ( NULLSTR( argument ) )
    {
        /*
            More of the LOTJ Docking system =)
        */
        if ( ( ship = ship_from_dockroom( ch->in_room ) ) != NULL )
        {
            if ( ship->dockship && ship->dock_state == DOCK_DOCKED && argument[0] == '\0' )
            {
                toroom = get_ship_dockroom( ship->dockship );

                if ( toroom == NULL || !toroom )
                {
                    ch_println( ch, "&YThat ship doesn't have an entrance!" );
                    return;
                }

                for ( fch = toroom->first_person; fch; fch = fch->next_in_room )
                {
                    if ( IS_IMMORTAL( ch ) )
                        continue;

                    chars++;
                }

                if ( chars > toroom->tunnel && toroom->tunnel > 0 )
                {
                    ch_println( ch, "There's not enough room in there." );
                    return;
                }   /* Whoops, missed this one :) */

                if ( ch->move < 1 )
                {
                    ch_println( ch, "You are too exhausted." );
                    return;
                }

                do_visible( ch, "-noalert" );

                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                {
                    if ( ch->carrying )
                    {
                        carry = TRUE;
                        snprintf( buf, MSL, "$n steps through the hatchway of %s, carrying $N.", ship->dockship->name );
                        act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
                    }

                    if ( !carry )
                        act( AT_PLAIN, "$n steps through the hatchway of $T.", ch, NULL, ship->dockship->name, TO_ROOM );
                }
                act( AT_PLAIN, "You step through the hatchway of $T.", ch, NULL, ship->dockship->name, TO_CHAR );
                ch->move -= 1;

                for ( tch = ch->in_room->first_person; tch; tch = tch->next_in_room )
                {
                    if ( tch->watching == ch )
                    {
                        action_clear( ch );
                        tch->watching = NULL;
                    }
                }

                ch->watching = NULL;
                fromroom = ch->in_room;
                char_from_room( ch );
                char_to_room( ch, toroom );

                if ( carry )
                {
                    char_from_room( ch->carrying );
                    char_to_room( ch->carrying, toroom );
                }

                if ( ch->mount )
                {
                    char_from_room( ch->mount );
                    char_to_room( ch->mount, toroom );
                }

                if ( ch->holding )
                {
                    ch_println( ch->holding, "You are pulled through the docking ring!" );
                    ch_println( ch, "You bring %s through the docking ring with you.", g_name( ch->holding, ch ) );
                    char_from_room( ch->holding );
                    char_to_room( ch->holding, toroom );
                }

                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, "$n steps through the docking ring of $T.", ch, NULL, ship->name, TO_ROOM );

                do_look( ch, "auto" );
                print_ship_condition( ch, ship->dockship );
                do_save( ch, "-noalert" );

                for ( fch = fromroom->first_person; fch; fch = fch->next_in_room )
                    chars++;

                for ( fch = fromroom->first_person; fch && ( count < chars ); fch = nextinroom )
                {
                    nextinroom = fch->next_in_room;
                    count++;

                    if ( fch != ch && fch->master == ch && fch->position == POS_STANDING )
                    {
                        act( AT_ACTION, "You follow $N.", fch, NULL, ch, TO_CHAR );
                        do_board( fch, argument );
                    }
                }

                return;
            }
            else if ( ship->dockship )
            {
                ch_println( ch, "&RWait for the ship to finish docking!" );
                return;
            }
        }

        ch_println( ch, "Board what?" );
        return;
    }

    if ( ( ship = ship_in_room( ch->in_room, argument ) ) == NULL )
    {
        if ( ( vec = vehicle_in_room( ch->in_room, argument ) ) != NULL )
        {
            sf = FALSE;
        }
        else
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, argument, TO_CHAR );
            return;
        }
    }

    if ( xIS_SET( ch->act, ACT_MOUNTED ) )
    {
        act( AT_PLAIN, "You are being ridden. Sit still damn you!", ch, NULL, argument, TO_CHAR );
        return;
    }

    fromroom = ch->in_room;

    if ( sf == TRUE )
        toroom = get_room_index( ship->entrance );

    if ( sf != TRUE )
        toroom = get_room_index( vec->entrance );

    if ( toroom != NULL )
    {
        bool hopen;

        if ( sf == TRUE )
            hopen = ship->hatchopen;

        if ( sf != TRUE )
            hopen = vec->hatchopen;

        if ( ( !hopen ) && !IS_AFFECTED( ch, AFF_PASS_DOOR ) )
        {
            if ( xIS_SET( ship->flags, SHIP_VONG ) )
                ch_println( ch, "&RThe hatch membrane is sealed shut!" );
            else
                ch_println( ch, "&RThe hatch is closed!" );

            return;
        }

        if ( toroom->tunnel > 0 )
        {
            CHAR_DATA* ctmp;
            int count = 0;

            for ( ctmp = toroom->first_person; ctmp; ctmp = ctmp->next_in_room )
                if ( !ctmp->spirit && ++count >= toroom->tunnel )
                {
                    if ( ch->carrying && count == toroom->tunnel )
                        ch_println( ch, "There is no room for both you and the person you're carrying in there." );
                    else
                        ch_println( ch, "There is no room for you in there." );

                    return;
                }

            if ( toroom->tunnel == 1 && ch->carrying )
            {
                ch_println( ch, "There is no room for both you and the person you're carrying in there." );
                return;
            }
        }

        /* GRAL Maybe force to be floating, flying, or a force jumper onto a hovering thing */
        if ( sf )
        {
            if ( ( ship->shipstate == SHIP_LAUNCH || ship->shipstate == SHIP_HOVERLAUNCH || ship->shipstate == SHIP_HOVERLAND ) && !IS_AFFECTED( ch, AFF_PASS_DOOR ) && !IS_AFFECTED( ch, AFF_FLYING ) )
            {
                ch_println( ch, "&rThat ship has already started launching, you need to fly up to the hatch!" );
                return;
            }

            if ( ( ship->shipstate == SHIP_HOVER ) && !IS_AFFECTED( ch, AFF_FLYING ) && !IS_AFFECTED( ch, AFF_PASS_DOOR ) )
            {
                ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
                return;
            }

            if ( ch->move < 1 )
            {
                ch_println( ch, "You are too exhausted." );
                return;
            }

            do_visible( ch, "-noalert" );

            if ( ch->mount )
            {
                char_from_room( ch->mount );
                char_to_room( ch->mount, toroom );
            }

            if ( ch->holding )
            {
                char_from_room( ch->holding );
                char_to_room( ch->holding, toroom );
            }

            if ( ch->carrying )
            {
                snprintf( buf, MSL, "$n enters %s carrying $N.", ship->name );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
                snprintf( buf, MSL, "You enter %s carrying $N.", ship->name );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_CHAR );
                ch->move -= 1;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( ch->carrying );
                char_to_room( ch->carrying, toroom );
                snprintf( buf, MSL, "$n enters the ship, carrying $N." );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
                do_save( ch, "-noalert" );
                do_save( ch->carrying, "-noalert" );
            }
            else
            {
                act( AT_PLAIN, "$n enters $T.", ch, NULL, ship->name, TO_ROOM );
                act( AT_PLAIN, "You enter $T.", ch, NULL, ship->name, TO_CHAR );
                ch->move -= 1;
                char_from_room( ch );
                char_to_room( ch, toroom );
                act( AT_PLAIN, "$n enters the ship.", ch, NULL, argument, TO_ROOM );
                do_save( ch, "-noalert" );
            }
        }
        else
        {
            if ( vec->type == CLOUD_CAR && vec->state != VEHICLE_OFF && vec->state != VEHICLE_DISABLED )
            {
                ch_println( ch, "Wait for that vehicle to be completely landed first!" );
                return;
            }

            do_visible( ch, "-noalert" );

            if ( ch->mount )
            {
                char_from_room( ch->mount );
                char_to_room( ch->mount, toroom );
            }

            if ( ch->carrying )
            {
                snprintf( buf, MSL, "$n enters %s carrying $N.", vec->name );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
                snprintf( buf, MSL, "You enter %s carrying $N.", vec->name );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_CHAR );
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( ch->carrying );
                char_to_room( ch->carrying, toroom );
                snprintf( buf, MSL, "$n enters the vehicle, carrying $N." );
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
                do_save( ch, "-noalert" );
                do_save( ch->carrying, "-noalert" );
            }
            else
            {
                act( AT_PLAIN, "$n enters $T.", ch, NULL, vec->name, TO_ROOM );
                act( AT_PLAIN, "You enter $T.", ch, NULL, vec->name, TO_CHAR );
                char_from_room( ch );
                char_to_room( ch, toroom );
                act( AT_PLAIN, "$n enters the vehicle.", ch, NULL, argument, TO_ROOM );
                do_save( ch->carrying, "-noalert" );
            }
        }

        do_look( ch, "auto" );
        if ( sf )
            print_ship_condition( ch, ship );

        for ( fch = fromroom->first_person; fch; fch = fch->next_in_room )
            chars++;

        for ( fch = fromroom->first_person; fch && ( count < chars ); fch = nextinroom )
        {
            nextinroom = fch->next_in_room;
            count++;

            if ( fch != ch && fch->master == ch && fch->position == POS_STANDING )
            {
                act( AT_ACTION, "You follow $N.", fch, NULL, ch, TO_CHAR );
                do_board( fch, argument );
            }
        }
    }
    else
    {
        if ( sf == TRUE )
            ch_println( ch, "&RThat ship has no entrance!" );

        if ( sf != TRUE )
            ch_println( ch, "&RThat vehicle has no entrance!" );
    }
}

bool rent_ship( CHAR_DATA* ch, SHIP_DATA* ship )
{
    int tax_kick = 0;
    long price;

    if ( IS_NPC( ch ) )
        return FALSE;

    /*
        Trainer Ships are free to rent
    */
    if ( is_training( ship ) )
        return TRUE;

    //    price = URANGE( 200, get_ship_value( ship ) / 200, 400 );
    price = ship->charge_price;

    if ( ch->gold < price )
    {
        ch_println( ch, "&RRenting this ship costs %ld. You don't have enough credits!", price );
        return FALSE;
    }

    ROOM_INDEX_DATA* tRoom = get_room_index( ship->location );

    if ( tRoom )
        if ( tRoom->area )
            if ( tRoom->area->planet )
            {
                PLANET_DATA* planet = tRoom->area->planet;
                tax_kick = price * planet->tax_rate / 100;
                planet->pending_taxes += tax_kick;
                save_clan( planet->governed_by, true );
            }

    ch->gold -= price;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "rent_ship", price * -1, FALSE );

    ch_println( ch, "&GYou pay %ld credits to rent the ship.", price );
    BANK_DATA* tBank = bank_from_number( ship->deposit_account );

    if ( tBank )
    {
        tBank->amount += price - tax_kick;
        sql_credits_log( tBank->owner, "rent_ship", ( price - tax_kick ), FALSE );
        save_bank( tBank, true );
    }
    else
    {
        CLAN_DATA* tClan = clan_from_account( ship->deposit_account );

        if ( tClan )
        {
            tClan->funds += price - tax_kick;
            sql_credits_log( tClan->name, "rent_ship", ( price - tax_kick ), FALSE );
            save_clan( tClan, true );
        }
    }

    return TRUE;
}

CMDF do_leaveship( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    ROOM_INDEX_DATA* fromroom = NULL;
    ROOM_INDEX_DATA* toroom = NULL;
    VEHICLE_DATA* vec = NULL;
    SHIP_DATA* ship = NULL;
    CHAR_DATA* fch = NULL;
    CHAR_DATA* nextinroom = NULL;
    CHAR_DATA* victim = NULL;
    int chars = 0, count = 0;
    bool sf = TRUE;
    fromroom = ch->in_room;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = ship_from_entrance( fromroom ) ) == NULL )
    {
        if ( ( vec = vehicle_from_entrance( fromroom->vnum ) ) == NULL )
        {
            ch_println( ch, "I see no exit here." );
            return;
        }

        sf = FALSE;
    }

    if ( sf )
    {
        if ( ship->lastdoc != ship->location )
        {
            ch_println( ch, "&rMaybe you should wait until the ship lands." );
            return;
        }

        if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        {
            if ( ship->shipstate != SHIP_HOVER && ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH  && ship->shipstate != SHIP_LAUNCH )
            {
                ch_println( ch, "&rPlease wait till the ship is properly docked." );
                return;
            }
        }

        if ( !ship->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) && !IS_AFFECTED( ch, AFF_PASS_DOOR ) )
        {
            ch_println( ch, "&RYou need to open the hatch first." );
            return;
        }

        toroom = get_room_index( ship->location );
    }
    else
    {
        if ( vec->type == CLOUD_CAR && vec->state != VEHICLE_DISABLED && vec->state != VEHICLE_OFF )
        {
            ch_println( ch, "You can't do that while in flight!" );
            return;
        }

        if ( !vec->hatchopen && vec->type != WHEELED )
        {
            ch_println( ch, "&RYou need to open the hatch first." );
            return;
        }

        toroom = get_room_index( vec->location );
    }

    if ( toroom == NULL )
    {
        ch_println( ch, "The exit doesn't seem to be working properly." );
        return;
    }

    if ( sf )
    {
        if ( ch->carrying )
        {
            victim = ch->carrying;

            if ( ship->shipstate != SHIP_HOVER && ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH && ship->shipstate != SHIP_LAUNCH )
            {
                //Landed ship
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n exits the ship, carrying $N." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_ROOM );
                snprintf( buf, MSL, "You exit the ship, carrying $N." );
                act( AT_PLAIN, buf, ch, NULL, victim, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n steps out of %s, carrying $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                do_look( ch, "auto" );
                mprog_entry_trigger( ch );
                lua_trigger_on_ch_enter( ch );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
            else if ( IS_AFFECTED( ch, AFF_FLYING ) )
            {
                //Hovering/launching but flying guy
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n floats out of the hovering ship, carrying $N." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_ROOM );
                snprintf( buf, MSL, "You float out of the hovering ship, carrying $N." );
                act( AT_PLAIN, buf, ch, NULL, victim, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n floats out of %s, carrying $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                do_look( ch, "auto" );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
            else
            {
                //Hovering but not flying
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n tumbles out of the hovering ship, pulling $N out with $m." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, buf, ch, NULL, victim, TO_ROOM );
                snprintf( buf, MSL, "You tumble out of the hovering ship, pulling $N out with you." );
                act( AT_RED, buf, ch, NULL, victim, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n tumbles out of %s with $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, buf, ch, NULL, victim, TO_NOTVICT );
                ch_println( ch, "&RYou fall through the air and hit the ground with a loud thud!" );
                damage( ch, ch, ( int )ch->max_hit / 4, TYPE_UNDEFINED );
                damage( victim, victim, ( int )victim->max_hit / 4, TYPE_UNDEFINED );
                release_char( victim, ch, FALSE );
                do_look( ch, "auto" );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
        }
        else if ( ch->holding )
        {
            victim = ch->holding;

            if ( ship->shipstate != SHIP_HOVER && ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH && ship->shipstate != SHIP_LAUNCH )
            {
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n exits the ship, holding $N." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                snprintf( buf, MSL, "You exit the ship, holding $N." );
                act( AT_PLAIN, buf, ch, NULL, victim, TO_CHAR );
                act( AT_PLAIN, "$n brings you with $m as $e exits the ship.", ch, NULL, victim, TO_VICT );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n steps out of %s, holding $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                do_look( ch, "auto" );
                do_look( victim, "auto" );
                mprog_entry_trigger( ch );
                lua_trigger_on_ch_enter( ch );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
            else if ( IS_AFFECTED( ch, AFF_FLYING ) )
            {
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n floats out of the hovering ship, holding $N." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                snprintf( buf, MSL, "You float out of the hovering ship, holding $N." );
                act( AT_PLAIN, buf, ch, NULL, victim, TO_CHAR );
                act( AT_PLAIN, "$n brings you with $m as $e floats out of the hovering ship.", ch, NULL, victim, TO_VICT );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n floats out of %s, holding $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, victim, TO_NOTVICT );
                do_look( ch, "auto" );
                do_look( victim, "auto" );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
            else
            {
                clear_piloting( ch );
                clear_piloting( victim );
                snprintf( buf, MSL, "$n tumbles out of the hovering ship, pulling $N out with $m." );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, buf, ch, NULL, victim, TO_NOTVICT );
                snprintf( buf, MSL, "You tumble out of the hovering ship, pulling $N out with you." );
                act( AT_RED, buf, ch, NULL, victim, TO_CHAR );
                act( AT_RED, "$n brings you with $m as $e exits the ship.", ch, NULL, victim, TO_VICT );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                char_from_room( victim );
                char_to_room( victim, toroom );
                snprintf( buf, MSL, "$n tumbles out of %s with $N.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, buf, ch, NULL, victim, TO_NOTVICT );
                ch_println( ch, "&RYou fall through the air and hit the ground with a loud thud!" );
                ch_println( victim, "&RYou fall through the air and hit the ground with a loud thud!" );
                damage( ch, ch, ( int )ch->max_hit / 4, TYPE_UNDEFINED );
                damage( victim, victim, ( int )victim->max_hit / 4, TYPE_UNDEFINED );
                release_char( victim, ch, FALSE );
                do_look( ch, "auto" );
                do_look( victim, "auto" );
                do_save( ch, "-noalert" );
                do_save( victim, "-noalert" );
            }
        }
        else
        {
            if ( ship->shipstate != SHIP_HOVER && ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH && ship->shipstate != SHIP_LAUNCH )
            {
                clear_piloting( ch );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, "$n exits the ship.", ch, NULL, argument, TO_ROOM );
                act( AT_PLAIN, "You exit the ship.", ch, NULL, argument, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                snprintf( buf, MSL, "$n steps out of %s.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, argument, TO_ROOM );
                do_look( ch, "auto" );
                mprog_entry_trigger( ch );
                lua_trigger_on_ch_enter( ch );
                do_save( ch, "-noalert" );
            }
            else if ( IS_AFFECTED( ch, AFF_FLYING ) )
            {
                clear_piloting( ch );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, "$n floats out of the hovering ship.", ch, NULL, argument, TO_ROOM );
                act( AT_PLAIN, "You float out of the hovering ship.", ch, NULL, argument, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                snprintf( buf, MSL, "$n floats out of %s.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_PLAIN, buf, ch, NULL, argument, TO_ROOM );
                do_look( ch, "auto" );
                do_save( ch, "-noalert" );
            }
            else
            {
                clear_piloting( ch );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, "$n tumbles out the hovering ship.", ch, NULL, argument, TO_ROOM );
                act( AT_RED, "You tumble out of the hovering ship.", ch, NULL, argument, TO_CHAR );
                check_room_for_traps( ch, TRAP_LEAVE_ROOM );
                if ( char_extracted( ch ) )
                    return;
                char_from_room( ch );
                char_to_room( ch, toroom );
                snprintf( buf, MSL, "$n tumbles out of %s.", ship->name );
                if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                    act( AT_RED, buf, ch, NULL, argument, TO_ROOM );
                ch_println( ch, "&RYou fall through the air and hit the ground with a loud thud!" );
                damage( ch, ch, ( int )ch->max_hit / 4, TYPE_UNDEFINED );
                do_look( ch, "auto" );
                do_save( ch, "-noalert" );
            }
        }
    }
    else
    {
        if ( ch->carrying )
        {
            snprintf( buf, MSL, "$n exits the vehicle, carrying $N." );
            if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
            snprintf( buf, MSL, "You exit the vehicle, carrying $N." );
            act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_CHAR );
            check_room_for_traps( ch, TRAP_LEAVE_ROOM );
            if ( char_extracted( ch ) )
                return;
            char_from_room( ch );
            char_to_room( ch, toroom );
            char_from_room( ch->carrying );
            char_to_room( ch->carrying, toroom );
            snprintf( buf, MSL, "$n steps out of a vehicle, carrying $N." );
            if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_PLAIN, buf, ch, NULL, ch->carrying, TO_ROOM );
            do_look( ch, "auto" );
            do_save( ch, "-noalert" );
            do_save( ch->carrying, "-noalert" );
        }

        if ( ch->holding )
        {
            snprintf( buf, MSL, "$n exits the vehicle, holding $N." );
            if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_PLAIN, buf, ch, NULL, ch->holding, TO_NOTVICT );
            snprintf( buf, MSL, "You exit the ship, holding $N." );
            act( AT_PLAIN, buf, ch, NULL, ch->holding, TO_CHAR );
            act( AT_PLAIN, "$n leaves the vehicle, taking you with $m.", ch, NULL, ch->holding, TO_VICT );
            check_room_for_traps( ch, TRAP_LEAVE_ROOM );
            if ( char_extracted( ch ) )
                return;
            char_from_room( ch );
            char_from_room( ch->holding );
            char_to_room( ch, toroom );
            char_to_room( ch->holding, toroom );
            do_look( ch, "auto" );
            do_look( ch->holding, "auto" );
            do_save( ch, "-noalert" );
            do_save( ch->holding, "-noalert" );
        }

        if ( !ch->carrying && !ch->holding )
        {
            if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_PLAIN, "$n exits the vehicle.", ch, NULL, argument, TO_ROOM );
            act( AT_PLAIN, "You exit the vehicle.", ch, NULL, argument, TO_CHAR );
            check_room_for_traps( ch, TRAP_LEAVE_ROOM );
            if ( char_extracted( ch ) )
                return;
            char_from_room( ch );
            char_to_room( ch, toroom );
            snprintf( buf, MSL, "$n steps out of %s.", vec->name );
            if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_PLAIN, buf, ch, NULL, argument, TO_ROOM );
            do_look( ch, "auto" );
            do_save( ch, "-noalert" );
        }
    }

    for ( fch = fromroom->first_person; fch; fch = fch->next_in_room )
        chars++;

    for ( fch = fromroom->first_person; fch && ( count < chars ); fch = nextinroom )
    {
        nextinroom = fch->next_in_room;
        count++;

        if ( fch != ch && fch->master == ch && fch->position == POS_STANDING )
        {
            act( AT_ACTION, "You follow $N.", fch, NULL, ch, TO_CHAR );
            do_leaveship( fch, argument );
        }
    }

    return;
}

void begin_ship_launch( SHIP_DATA* ship )
{
    char buf[MSL];

    if ( ship->hatchopen )
    {
        ship->hatchopen = FALSE;
        ship->hatchtimer = 0;

        if ( xIS_SET( ship->flags, SHIP_VONG ) )
            snprintf( buf, MSL, "The hatch membrane on %s retracts and seals tightly.", ship->name );
        else
            snprintf( buf, MSL, "The hatch on %s closes.", ship->name );

        echo_to_room( AT_YELLOW, get_room_index( ship->location ), buf );

        if ( xIS_SET( ship->flags, SHIP_VONG ) )
            echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch membrane retracts and seals tightly." );
        else
            echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch slides shut." );

        sound_to_room( get_room_index( ship->entrance ), "door" );
        sound_to_room( get_room_index( ship->location ), "door" );
    }

    snprintf( buf, MSL, "%s begins to launch.", ship->name );
    echo_to_room( AT_YELLOW, get_room_index( ship->location ), buf );
    ROOM_INDEX_DATA* ship_room = get_room_index( ship->location );

    if ( ship_room )
    {
        for ( SHIP_DATA* tship = ship_room->first_ship; tship; tship = tship->next_in_room )
            if ( ship->location == tship->location && tship != ship )
                echo_to_ship_windows( AT_ORANGE, tship, buf );
    }

    ship->shipstate = SHIP_LAUNCH;
    ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
    ship->currspeed = ship->realspeed;
    lua_trigger_ship_launch( ship, ship_room );
}

bool check_vong_ship_control( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( xIS_SET( ship->flags, SHIP_VONG ) && !xIS_SET( ch->race->flags, RFLAG_VONG ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RThis ship has no apparent controls, and you have no idea how to operate it!" );
        return false;
    }

    if ( !xIS_SET( ship->flags, SHIP_VONG ) && xIS_SET( ch->race->flags, RFLAG_VONG ) &&
            ch->main_ability != ESPIONAGE_ABILITY && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RThis mechanical ship is suitable only for heathens and should be destroyed, not flown!" );
        send_to_char( "&Y(OOC) If you must fly a non-Vong ship in a life-or-death situation, you may, but "
                      "you should be ashamed of yourself for having to use this forbidden technology.", ch );
        return true;
    }

    return true;
}

int squads_launched( CLAN_DATA* clan )
{
    int cnt = 0;
    SHIP_DATA* ship = NULL;

    if ( !clan )
        return 0;

    for ( ship = first_ship; ship; ship = ship->next )
        if ( ship->squadleader && ship->squadleader == ship )
            if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED &&
            ship->shipstate != SHIP_PERM_DISABLED && ship->shipstate != SHIP_HOVER &&
            ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH )
                if ( !str_cmp( ship->shipowner, clan->name ) )
                    cnt++;

    return cnt;
}

CMDF do_launch( CHAR_DATA* ch, char* argument )
{
    PLANET_DATA* planet = NULL;
    int chance;
    long price = 0;
    SHIP_DATA* ship = NULL;
    HANGAR_DATA* hangar;
    char buf[MSL];
    SHIP_DATA* onship;

    /*
        Vehicle Launch Check
    */
    if ( vehicle_launch( ch, argument ) )
        return;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( !check_vong_ship_control( ch, ship ) )
        return;

    if ( get_ship_from_pilotseat( ch->in_room ) == NULL )
    {
        if ( !xIS_SET( ship->flags, SHIP_VONG ) )
            ch_println( ch, "&RYou don't seem to be in the pilot seat!" );
        else
            ch_println( ch, "&RYou aren't near the interface to this ship's yammosk." );

        return;
    }

    if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) && !is_name( "hover", argument ) )
    {
        if ( !xIS_SET( ship->flags, SHIP_VONG ) )
        {
            ch_println( ch, "&RA warning light on the console flashes, indicating the hatch is inoperable." );
            ch_println( ch, "&zThe ship won't launch!" );
        }
        else
        {
            ch_println( ch, "&RThe ship's yammosk refuses to launch the ship, signaling that its hatch membrane is compromised." );
        }

        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RTake it off autopilot first!" );
        return;
    }

    if ( ( !ship->piloting || ship->piloting != ch ) && can_land( ship ) )
    {
        ch_println( ch, "&RYou need to be piloting the ship." );
        return;
    }

    if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) && !is_name( "hover", argument ) && !is_name( "abort", argument ) )
    {
        ch_println( ch, "&RHey, that's not your ship! Try renting a public one." );
        return;
    }

    if ( is_name( "hover", argument ) )
    {
        if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
        {
            ch_println( ch, "This ship needs to be repaired first." );
            return;
        }

        if ( ship->shipstate == SHIP_HOVER )
        {
            ch_println( ch, "The ship is already hovering." );
            return;
        }

        if ( ship->autopilot )
        {
            ch_println( ch, "You can't engage the engines while the autopilot is on." );
            return;
        }

        if ( ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH )
        {
            ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
            return;
        }

        if ( ship->shipstate != SHIP_DOCKED )
        {
            ch_println( ch, "You need to be landed in order to hover." );
            return;
        }

        /*  GRAL
            Medium ships should be able to hover.
            FIGHTER_SHIP, TRANSPORT_SHIP, FREIGHTER_SHIP, GUNBOAT_SHIP, CORVETTE_SHIP, FRIGATE_SHIP,
            CRUISER_SHIP, BATTLESHIP_SHIP, BATTLESTATION_SHIP, PLATFORM_SHIP
            Was TRANSPORT_SHIP
        */
        if ( ship->classtype > GUNBOAT_SHIP )
        {
            ch_println( ch, "Only small ships are capable of traveling along the surface of a planet." );
            return;
        }

        if ( is_public( ship ) )
        {
            ch_println( ch, "Public ships aren't capable of flying around like that." );
            return;
        }

        ship->shipstate = SHIP_HOVERLAUNCH;
        ship->maneuver_timer = 10; // Flat 20 seconds for hovering
        act( AT_YELLOW, "$n fires up the engines and the ship begins to rise.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "&YYou fire up the engines, and the ship begins to rise." );

        for ( ROOM_INDEX_DATA* room = ship->first_room; room; room = room->next_in_range )
            echo_to_room( AT_YELLOW, room, "The ship begins to launch.\n" );

        snprintf( buf, MSL, "&Y%ss engines fire up, and it begins to rise.\n", ship->name );
        ship_action( ship, buf );
        return;
    }

    if ( is_name( "abort", argument ) )
    {
        if ( ship->shipstate != SHIP_LAUNCH )
        {
            ch_println( ch, "You're not launching." );
            return;
        }

        {
            chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, find_gsn( ship->classtype ) );

            if ( number_percent(  ) > chance )
            {
                ch_println( ch, "You fail to work the controls properly." );
                return;
            }

            ship->shipstate = SHIP_LAUNCH_ABORT;
            ship->maneuver_timer = 5; // Flat 10 seconds to abort launch
            ship->location = ship->lastdoc;
            ch_println( ch, "&WYou abort the launching sequence." );
            echo_to_ship_windows( AT_YELLOW, ship, "The craft lurches as you veer back towards the landing area." );
            snprintf( buf, MSL, "&Y%s veers back towards the landing area.", ship->name );
            ship_action( ship, buf );

            if ( is_squadleader( ship ) )
            {
                for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
                {
                    if ( sq->in_room != ship->in_room )
                        continue;

                    if ( !should_follow_squadleader( sq, ship ) )
                        continue;

                    if ( sq->shipstate != SHIP_LAUNCH )
                        continue;

                    sq->shipstate = SHIP_LAUNCH_ABORT;
                    sq->maneuver_timer = 5;
                    sq->location = sq->lastdoc;
                    snprintf( buf, MSL, "&Y%s veers back towards the landing area.", sq->name );
                    ship_action( sq, buf );
                }
            }

            return;
        }
    }

    if ( ship->lastdoc != ship->location )
    {
        ch_println( ch, "&rYou don't seem to be docked right now." );
        return;
    }

    if ( ship->shipstate == SHIP_COOLDOWN )
    {
        ch_println( ch, "The ship is not ready yet. Please wait a moment." );
        return;
    }

    if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ship->shipstate != SHIP_HOVER
            && ship->shipstate != SHIP_HOVERLAND && ship->shipstate != SHIP_HOVERLAUNCH )
    {
        ch_println( ch, "The ship is not docked right now." );
        return;
    }

    if ( ship->energy < 100 + ( 100 * ship->classtype ) )
    {
        if ( xIS_SET( ship->flags, SHIP_VONG ) )
            ch_println( ch, "&RThere's not enough biomass for the dovin basals to propel the ship!" );
        else
            ch_println( ch, "&RYou might want to refuel first!" );

        return;
    }

    CLAN_DATA* clan_owner = ship->clan;

    if ( clan_owner )
    {
        if ( ship->classtype >= FRIGATE_SHIP && capital_points_used( clan_owner ) + ship_capital_points( ship ) > capital_points_max( clan_owner ) )
        {
            ch_println( ch, "&RYour clan doesn't have capacity to launch this ship right now!" );
            return;
        }
        else if ( ship->squadleader && squads_launched( clan_owner ) >= clan_owner->squadrons )
        {
            ch_println( ch, "&RYour clan can't field any more squadrons right now!" );
            return;
        }
    }

    if ( ship->in_room )
    {
        if ( xIS_SET( ship->in_room->flags, ROOM_NOSHIELD ) )
        {
        }
        else if ( ship->in_room->area )
        {
            if ( ship->in_room->area->planet )
            {
                planet = ship->in_room->area->planet;

                if ( planet->shields > 25 )
                {
                    if ( planet->governed_by != NULL )
                    {
                        if ( in_clan( ch ) )
                        {
                            if ( ch->pcdata->clan == planet->governed_by )
                            {
                                /*
                                    Allow members of the same clan to launch
                                */
                                ch_println( ch, "&YYou give the central control your security clearance codes." );
                            }
                            else
                            {
                                if ( planet->governed_by != ship->clan )
                                {
                                    ch_println( ch, "&RThe Planetary shields are preventing you from launching!" );
                                    return;
                                }
                            }
                        }
                        else if ( planet->governed_by != ship->clan )
                        {
                            ch_println( ch, "&RThe Planetary shields are preventing you from launching!" );
                            return;
                        }
                    }
                    else
                    {
                        ch_println( ch, "&RThe Planetary shields are preventing you from launching!" );
                        return;
                    }
                }
            }
        }
    }

    if ( ( onship = ship_from_hangar( ship->in_room ) ) != NULL )
    {
        hangar = get_hangar_room( onship, ship->in_room );

        if ( hangar == NULL )
        {
            bug( "do_launch: get_hangar_room returned NULL." );
            return;
        }

        if ( !hangar->bayopen )
        {
            ch_println( ch, "&RThe hangar is closed!" );
            return;
        }
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent(  ) <= chance )
    {
        if ( is_rental( ch, ship ) )
        {
            if ( ship->charge_price > 0 && str_cmp( argument, "confirm" ) ) // Failsafe so they dont accidentally lose all their money
            {
                ch_println( ch, "It costs %d to rent this ship. Type LAUNCH CONFIRM to accept.", ship->charge_price );
                return;
            }

            if ( !rent_ship( ch, ship ) )
                return;
        }
        else
        {
            if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
            {
                if ( xIS_SET( ship->flags, SHIP_VONG ) )
                    ch_println( ch, "&RThe ship's yammosk doesn't respond. The ship refuses to launch." );
                else
                    ch_println( ch, "&RThe ship's drive is disabled." );

                return;
            }
        }

        if ( ch->fighting && number_percent(  ) > 25 )
        {
            ch_println( ch, "&RYou try to reach the controls, but narrowly avoid being hit!" );
            return;
        }

        if ( price > 0 )
        {
            if ( in_clan( ch ) && !str_cmp( ch->pcdata->clan->name, ship->shipowner ) )
            {
                if ( ch->pcdata->clan->funds < price )
                {
                    ch_println( ch, "&R%s doesn't have enough funds to prepare this ship for launch.",
                               ch->pcdata->clan->name );
                    return;
                }

                ch->pcdata->clan->funds -= price;
                sql_credits_log( ch->pcdata->clan->name, "do_launch", price * -1, TRUE );
                ch_println( ch, "&GIt costs %s %ld credits to ready this ship for launch.", ch->pcdata->clan->name,
                           price );
            }
            else if ( str_cmp( ship->shipowner, "Public" ) && str_cmp( ship->shipowner, "public" ) && str_cmp( ship->shipowner, "Trainer" ) )
            {
                if ( ch->gold < price )
                {
                    ch_println( ch, "&RYou don't have enough funds to prepare this ship for launch." );
                    return;
                }

                ch->gold -= price;

                if ( !IS_NPC( ch ) )
                    sql_credits_log( ch->name, "do_launch", price * -1, TRUE );

                ch_println( ch, "&GYou pay %ld credits to ready the ship for launch.", price );
            }
        }

        if ( ch->fighting )
        {
            ch_println( ch, "&CYou make a dive for the control console! Success!" );
            act( AT_PLAIN, "$n dives for the console and engages the launch sequence!", ch, NULL, argument, TO_ROOM );
        }
        else
        {
            if ( xIS_SET( ship->flags, SHIP_VONG ) )
                act( AT_PLAIN, "$n signals for the ship's yammosk to begin launching the vessel.", ch, NULL, argument, TO_ROOM );
            else
                act( AT_PLAIN, "$n starts up the ship and begins the launch sequence.", ch, NULL, argument, TO_ROOM );
        }

        ch_println( ch, "&GLaunch sequence initiated." );

        if ( ship->shipstate != SHIP_HOVER && ship->shipstate != SHIP_HOVERLAUNCH && ship->shipstate != SHIP_HOVERLAND )
        {
            if ( xIS_SET( ship->flags, SHIP_VONG ) )
                echo_to_ship_main( AT_YELLOW, ship, "The ship silently lifts off the ground, propelled by its dovin basals." );
            else
                echo_to_ship_main( AT_YELLOW, ship, "The ship hums as it lifts off the ground." );
        }
        else
            echo_to_ship_main( AT_YELLOW, ship, "The ship lurches as it begins to ascend." );

        begin_ship_launch( ship );

        if ( is_name( "orbit", argument ) )
            ship->currspeed = 0;

        if ( autofly( ship ) && xIS_SET( ship->aflags, AFLAG_SENTINEL ) )
            ship->currspeed = 0;

        if ( is_squadleader( ship ) )
        {
            for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( sq->in_room != ship->in_room )
                    continue;

                if ( !should_follow_squadleader( sq, ship ) )
                    continue;

                if ( sq->shipstate == SHIP_DISABLED || sq->shipstate == SHIP_PERM_DISABLED )
                {
                    message_to_squadleader( sq, "Unable to launch, engines aren't responding." );
                    continue;
                }

                if ( sq->energy < 100 )
                {
                    message_to_squadleader( sq, "Unable to launch, fuel levels critical." );
                    continue;
                }

                if ( xIS_SET( sq->flags, SHIP_BROKEN_HATCH ) )
                {
                    message_to_squadleader( sq, "My hatch won't seal, looks like it's cut open!" );
                    continue;
                }

                begin_ship_launch( sq );
                sq->autopilot = true;
                sq->autorecharge = true;
            }
        }

        learn_from_success( ch, find_gsn( ship->classtype ) );
        return;
    }

    if ( !ch->fighting )
    {
        ch_println( ch, "&RYou fail to work the controls properly!" );
        learn_from_failure( ch, find_gsn( ship->classtype ) );
    }
    else
    {
        ch_println( ch, "&RYou're not sure you could pull it off!" );
    }

    return;
}

void launchship( SHIP_DATA* ship )
{
    char buf[MSL], msg[MSL];
    SHIP_DATA* source, *tmpship = NULL;
    PLANET_DATA* planet = NULL;
    ROOM_INDEX_DATA* room = NULL, *room2 = NULL;
    SPACE_DATA* starsystem = NULL;
    bool pfound = FALSE;

    starsystem = starsystem_from_vnum( ship->location );
    room2 = get_room_index( ship->location );

    if ( starsystem == NULL )
    {
        echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Launch path blocked .. Launch aborted." );
        echo_to_ship_main( AT_YELLOW, ship, "The ship slowly sets back back down on the landing pad." );
        snprintf( buf, MSL, "&Y%s slowly sets back down.", ship->name );
        ship_action( ship, buf );
        ship->shipstate = SHIP_DOCKED;
        return;
    }

    if ( ( tmpship = get_ship_from_room( room2 ) ) == NULL )
    {
        pfound = TRUE;
            /* Not a ship? Must be a planet. */

        if ( !room2->name )
        {
            bug( "Launchship - Bad room value returned. " );
            return;
        }
    }

    snprintf( buf, MSL, "&Y%s lifts off into space.", ship->name );
    ship_action( ship, buf );
    source = ship_from_hangar( ship->in_room );
    ship_to_starsystem( ship, starsystem );
    ship->location = 0;

    if ( ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        ship->shipstate = SHIP_READY;

    ship_randomize_heading( ship );

    if ( ( room = get_room_index( ship->lastdoc ) ) != NULL && room->area && room->area->planet
            && room->area->planet->starsystem && room->area->planet->starsystem == ship->starsystem )
    {
        planet = room->area->planet;
        vector_copy( &ship->vpos, &planet->pos );
    }
    else if ( source )
    {
        vector_copy( &ship->vpos, &source->vpos );
    }

    ship->energy -= ( 50 + ( 100 * ship->classtype ) );
    echo_to_room( AT_GREEN, get_room_index( ship->pilotseat ), "Launch complete.\n" );  // This was sending to the wrong room or a NULL room
    if ( xIS_SET( ship->flags, SHIP_BRANDNEW ) )
    {
        echo_to_ship_main( AT_YELLOW, ship, "The ship leaves the platform far behind as it completes its inaugural launch." );
        xREMOVE_BIT( ship->flags, SHIP_BRANDNEW );
    }
    else
        echo_to_ship_main( AT_YELLOW, ship, "The ship leaves the platform far behind as it flies into space." );


    // Ensure we're clear from the minimum orbit distance of 10 by setting speed to 50 and moving one tick.
    if ( ( !xIS_SET( ship->aflags, AFLAG_SENTINEL ) || !ship->autopilot ) && ship->currspeed > 0 )
    {
        sh_int orig_speed = ship->currspeed;
        ship->currspeed = 50;
        ship_move( ship );
        ship->currspeed = orig_speed;
    }
    else
    {
        // Hack to get the "you begin orbiting" message to show:
        // Moving <50 will result in being sucked back to orbit
        ship->currspeed = UMIN( 1, ship->realspeed );
        ship_move( ship );
        ship->currspeed = 0;
        // Force a perfect orbit
        if ( planet )
            vector_copy( &ship->vpos, &planet->pos );
        else if ( source )
            vector_copy( &ship->vpos, &source->vpos );
    }

    if ( pfound )
    {
        if ( room2 && room2->area && room && room->area && ship && room->area->planet )
            snprintf( msg, MSL, "%s launches from the surface of %s, entering the starsystem at %.0f %.0f %.0f", ship->name,
                     room->area->planet->name, ship->vpos.x, ship->vpos.y, ship->vpos.z );
        else if ( ship )
            snprintf( msg, MSL, "%s launches from the surface, entering the starsystem at %.0f %.0f %.0f", ship->name, ship->vpos.x,
                     ship->vpos.y, ship->vpos.z );
    }

    if ( !pfound )
        snprintf( msg, MSL, "%s launches from a hangar on %s, entering the starsystem at %.0f %.0f %.0f", ship->name,
                 tmpship->name, ship->vpos.x, ship->vpos.y, ship->vpos.z );

    echo_to_system_noqueue( AT_YELLOW, ship, msg, NULL );

    if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        //        lognormal("setting ship to orbiting %s",ship->name);
        ship->trafficstate = TRAFFIC_ORBIT_DEPARTING;
    }

    save_ship( ship, true );
    lua_trigger_ship_launched( ship, room2, starsystem );
}

void begin_landing( CHAR_DATA* ch, SHIP_DATA* ship, bool pfound, PLANET_DATA* planet, SHIP_DATA* target, char* arg )
{
    char buf[MSL];

    if ( pfound && planet )
    {
        if ( planet->name )
            snprintf( buf, MSL, "%s begins to approach the surface of %s.", ship->name, planet->name );
        else
            snprintf( buf, MSL, "%s begins to approach the surface.", ship->name );
    }

    if ( !pfound )
        snprintf( buf, MSL, "%s begins to approach one of the hangars on %s.", ship->name, target->name );

    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );

    if ( ch )
    {
        ch_println( ch, "&YYou begin to land on %s&Y.", pfound ? planet->name : target->name );
        act( AT_PLAIN, "$n begins the landing sequence.", ch, NULL, NULL, TO_ROOM );
    }

    echo_to_ship_main( AT_YELLOW, ship, "The ship slowly begins its landing approach." );

    if ( ch )
        ch_println( ch, "&wIf you leave the controls the ship will crash when you reach the surface." );

    lua_trigger_ship_land( ship, ship->starsystem );
    SET_STRING( ship->dest, arg );
    // It takes a little longer to land than standard maneuvers so people have enough time for interaction in orbit.
    ship->maneuver_timer = 5 + SHIP_MANEUVER_DELAY( ship );
    ship->shipstate = SHIP_LAND;
    ship->currspeed = 0;
    ship->autotrack = FALSE;
    ship->autospeed = FALSE;
}

void abort_landing( CHAR_DATA* ch, SHIP_DATA* ship )
{
    char buf[MSL];
    ship->last_landed = ship->starsystem;

    if ( ch )
        ch_println( ch, "&RYou pull the ship into a tight turn!" );

    snprintf( buf, MSL, "%s veers sharply out of its landing trajectory.", ship->name );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );

    if ( ch )
        act( AT_RED, "$n manipulates the flight controls.", ch, NULL, NULL, TO_ROOM );

    echo_to_ship_main( AT_YELLOW, ship, "The ship veers wildly out of its landing path!" );
    ship->shipstate = SHIP_LAND_ABORT;
    ship->maneuver_timer = 5; // Flat 10 seconds to abort landing
}

CMDF do_land( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char arg1[MIL];
    char buf[MSL];
    int chance;
    SHIP_DATA* ship;
    SHIP_DATA* target = NULL;
    HANGAR_DATA* hangar;
    PLANET_DATA* planet;
    ROOM_INDEX_DATA* room = NULL;
    ROOM_INDEX_DATA* croom = NULL;
    STRUCTURE_DATA* stru;
    bool rfound = FALSE;
    bool pfound = FALSE;
    bool instruct = FALSE;
    /*
        int vx, vy ,vz;
    */
    PAD_DATA* pad;
    int vnum, fuel;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "&RYou're a tad distracted getting your ass kicked!" );
        return;
    }

    /*
        Vehicle Land Check
    */
    if ( vehicle_land( ch, argument ) )
        return;

    strlcpy( arg, argument, MIL );
    argument = one_argument( argument, arg1 );

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->dock_state > DOCK_READY )
    {
        ch_println( ch, "&RThe docking system is still in use!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou need to be in the pilot seat!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "&RYou can't land platforms." );
        return;
    }

    if ( ship->classtype == BATTLESTATION_SHIP )
    {
        ch_println( ch, "&RYou can't land battlestations." );
        return;
    }

    if ( ( !ship->piloting || ship->piloting != ch ) && can_land( ship ) )
    {
        ch_println( ch, "&RYou need to be piloting the ship to land." );
        return;
    }

    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to land." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RThe ship is already docked!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( is_name( "abort", arg1 ) )
    {
        if ( ship->shipstate != SHIP_LAND )
        {
            ch_println( ch, "&RMaybe if you were landing." );
            return;
        }
        else
        {
            abort_landing( ch, ship );

            if ( is_squadleader( ship ) )
            {
                for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
                {
                    if ( sq->starsystem != ship->starsystem )
                        continue;

                    if ( !should_follow_squadleader( sq, ship ) )
                        continue;

                    if ( sq->shipstate == SHIP_LAND )
                        abort_landing( NULL, sq );
                }
            }

            return;
        }
    }

    if ( ship->shipstate == SHIP_HOVER )
    {
        if ( !ship->in_room )
        {
            ch_println( ch, "&RBUG: Ship room now found." );
            return;
        }

        if ( xIS_SET( ship->in_room->flags, ROOM_NOFLOOR ) )
        {
            ch_println( ch, "&RYou can't land in the air!" );
            return;
        }

        ch_println( ch, "&YYou begin to land the ship." );

        for ( ROOM_INDEX_DATA* room = ship->first_room; room; room = room->next_in_range )
            echo_to_room( AT_YELLOW, room, "The ship begins to land.\n" );

        snprintf( buf, MSL, "&Y%s begins to land.\n", ship->name );
        ship_action( ship, buf );
        ship->shipstate = SHIP_HOVERLAND;
        ship->maneuver_timer = 10; // Flat 20 seconds to land from hovering
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        send_to_char( "&RThere's nowhere to land around here!", ch );
        return;
    }

    fuel = ( 25 + ( 25 * ship->classtype ) );

    if ( ship->energy < fuel )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        set_char_color( AT_CYAN, ch );

        if ( ship->cloakstatus == CLOAK_ON )
        {
            ch_println( ch, "&cLand where?&w" );
            return;
        }

        ch_printf( ch, "%s", "&cLand where?\n\n&zChoices: " );

        for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
        {
            if ( xIS_SET( planet->flags, PLANET_STAR ) )
                continue;

            if ( planet->shields > 24 )
                ch_println( ch, "&R%s   &R%.0f %.0f %.0f", planet->name, planet->pos.x, planet->pos.y, planet->pos.z );

            if ( planet->shields < 25 )
                ch_println( ch, "&C%s   &C%.0f %.0f %.0f", planet->name, planet->pos.x, planet->pos.y, planet->pos.z );
        }

        for ( target = ship->starsystem->first_ship; target; target = target->next_in_starsystem )
        {
            if ( target->first_hangar && target != ship && target->cloakstatus != CLOAK_ON )
                ch_println( ch, "         &C%s    %.0f %.0f %.0f", target->name, target->vpos.x, target->vpos.y, target->vpos.z );
        }

        ch_println( ch, "\n&zYour Coordinates: %.0f %.0f %.0f", ship->vpos.x, ship->vpos.y, ship->vpos.z );
        return;
    }

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( !str_prefix( arg1, planet->plaintext_name ) && !xIS_SET( planet->flags, PLANET_STAR ) )
        {
            pfound = TRUE;

            if ( !can_land( ship ) )
            {
                ch_println( ch, "&RThis ship can only land on space platforms or battlestations!" );
                return;
            }

            if ( !planet->first_area )
            {
                ch_println( ch, "&RThat planet doesn't have any landing areas." );
                return;
            }

            if ( vector_distance( &ship->vpos, &planet->pos ) > 20 )
            {
                ch_println( ch, "&RYou must attain orbit over the planet first!" );
                return;
            }

            if ( !NULLSTR( argument ) )
            {
                FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
                    for ( vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
                    {
                        instruct = FALSE;

                        if ( ( room = get_room_index( vnum ) ) != NULL )
                        {
                            for ( stru = first_structure; stru; stru = stru->next )
                                if ( vnum <= stru->lastroom && vnum >= stru->firstroom )
                                {
                                    instruct = TRUE;
                                    break;
                                }

                            /* GRAL supposedly clanpads can not be hiden.. */
                            if ( instruct )
                                continue;

                            if ( ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_CLANPAD )
                                    || xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                                    && !str_prefix( argument,
                                                    strlen( stripclr( room->name ) ) <=
                                                    0 ? room->name : stripclr( room->name ) ) )
                            {
                                if ( xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                                    if ( str_cmp( strlen( stripclr( room->name ) ) <= 0 ? room->name : stripclr( room->name ), argument ) )
                                        continue;

                                rfound = TRUE;
                                croom = room;
                                break;
                            }
                        }
                    }
                })

                for ( stru = first_structure; stru; stru = stru->next )
                {
                    if ( planet == get_planet_from_room( get_room_index( stru->in_room ) ) )
                    {
                        for ( vnum = stru->firstroom; vnum <= stru->lastroom; vnum++ )
                        {
                            if ( ( room = get_room_index( vnum ) ) != NULL )
                            {
                                if ( ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_CLANPAD )
                                        || xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                                        && !str_prefix( argument,
                                                        strlen( stripclr( room->name ) ) <=
                                                        0 ? room->name : stripclr( room->name ) ) )
                                {
                                    if ( xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                                        if ( str_cmp( strlen( stripclr( room->name ) ) <= 0 ? room->name : stripclr( room->name ), argument ) )
                                            continue;

                                    rfound = TRUE;
                                    croom = room;
                                    break;
                                }
                            }
                        }
                    }
                }
            }

            if ( !rfound )
            {
                ch_println( ch, "&RPlease type the location after the planet name." );
                ch_println( ch, "&zPossible choices for %s&z:\n", planet->name );

                FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
                    for ( vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
                    {
                        if ( ( room = get_room_index( vnum ) ) != NULL )
                        {
                            instruct = FALSE;

                            for ( stru = first_structure; stru; stru = stru->next )
                                if ( vnum <= stru->lastroom && vnum >= stru->firstroom )
                                {
                                    instruct = TRUE;
                                    break;
                                }

                            if ( instruct )
                                continue;

                            if ( xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                            {
                                if ( xIS_SET( room->flags, ROOM_CLANPAD ) )
                                {
                                    pad = get_pad_from_room( room );
                                    if ( !pad )
                                    {
                                        bug("do_land: misconfigured clan pad in room %d", room->vnum );
                                        continue;
                                    }

                                    if ( IS_IMMORTAL( ch ) || ( ch->pcdata->clan && hasname( pad->immlist, ch->pcdata->clan->shortname ) ) )
                                    {
                                        if ( room->minshipclass == 0 && room->maxshipclass == 10 )
                                            ch_println( ch, "&W%s &z(&wAll Sizes&z)", room->name );
                                        else if ( room->minshipclass == 0 && room->maxshipclass != 10 )
                                            ch_println( ch, "&W%s &z(&wMax: &c%s&z)", room->name, class_types[room->maxshipclass] );
                                        else if ( room->minshipclass != 0 && room->maxshipclass == 10 )
                                            ch_println( ch, "&W%s &z(&wMin: &c%s&z)", room->name, class_types[room->minshipclass] );
                                        else
                                            ch_println( ch, "&W%s &z(&wMin: &c%s &w| Max: &c%s&z)", room->name, class_types[room->minshipclass], class_types[room->maxshipclass] );
                                    }
                                }
                            }
                            else if ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_CLANPAD ) )
                            {
                                if ( room->minshipclass == 0 && room->maxshipclass == 10 )
                                    ch_println( ch, "&W%s &z(&wAll Sizes&z)", room->name );
                                else if ( room->minshipclass == 0 && room->maxshipclass != 10 )
                                    ch_println( ch, "&W%s &z(&wMax: &c%s&z)", room->name, class_types[room->maxshipclass] );
                                else if ( room->minshipclass != 0 && room->maxshipclass == 10 )
                                    ch_println( ch, "&W%s &z(&wMin: &c%s&z)", room->name, class_types[room->minshipclass] );
                                else
                                    ch_println( ch, "&W%s &z(&wMin: &c%s &w| Max: &c%s&z)", room->name, class_types[room->minshipclass], class_types[room->maxshipclass] );
                            }
                        }
                    }
                })

                for ( stru = first_structure; stru; stru = stru->next )
                {
                    if ( planet == get_planet_from_room( get_room_index( stru->in_room ) ) )
                    {
                        for ( vnum = stru->firstroom; vnum <= stru->lastroom; vnum++ )
                        {
                            if ( ( room = get_room_index( vnum ) ) != NULL )
                            {
                                if ( xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
                                {
                                    if ( xIS_SET( room->flags, ROOM_CLANPAD ) )
                                    {
                                        pad = get_pad_from_room( room );

                                        if ( IS_IMMORTAL ( ch ) || ( ch->pcdata->clan && hasname( pad->immlist, ch->pcdata->clan->shortname ) ) )
                                        {
                                            if ( room->minshipclass == 0 && room->maxshipclass == 10 )
                                                ch_println( ch, "&W%s &z(&wAll Sizes&z)", room->name );
                                            else if ( room->minshipclass == 0 && room->maxshipclass != 10 )
                                                ch_println( ch, "&W%s &z(&wMax: &c%s&z)", room->name, class_types[room->maxshipclass] );
                                            else if ( room->minshipclass != 0 && room->maxshipclass == 10 )
                                                ch_println( ch, "&W%s &z(&wMin: &c%s&z)", room->name, class_types[room->minshipclass] );
                                            else
                                                ch_println( ch, "&W%s &z(&wMin: &c%s &w| Max: &c%s&z)", room->name, class_types[room->minshipclass], class_types[room->maxshipclass] );
                                        }
                                    }
                                }
                                else if ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_CLANPAD ) )
                                {
                                    if ( room->minshipclass == 0 && room->maxshipclass == 10 )
                                        ch_println( ch, "&W%s &z(&wAll Sizes&z)", room->name );
                                    else if ( room->minshipclass == 0 && room->maxshipclass != 10 )
                                        ch_println( ch, "&W%s &z(&wMax: &c%s&z)", room->name, class_types[room->maxshipclass] );
                                    else if ( room->minshipclass != 0 && room->maxshipclass == 10 )
                                        ch_println( ch, "&W%s &z(&wMin: &c%s&z)", room->name, class_types[room->minshipclass] );
                                    else
                                        ch_println( ch, "&W%s &z(&wMin: &c%s &w| Max: &c%s&z)", room->name, class_types[room->minshipclass], class_types[room->maxshipclass] );
                                }
                            }
                        }
                    }
                }

                return;
            }

            break;
        }
    }

    if ( !pfound )
    {
        target = get_ship_here( arg1, ship->starsystem );

        if ( target != NULL && target->cloakstatus != CLOAK_ON )
        {
            if ( target == ship )
            {
                ch_println( ch, "&RYou can't land your ship inside itself!" );
                return;
            }

            if ( !can_land( ship ) && ( target->classtype != PLATFORM_SHIP && target->classtype != BATTLESTATION_SHIP ) )
            {
                ch_println( ch, "&RThis ship can only land on ship platforms or battlestations!" );
                return;
            }

            if ( ship->classtype >= target->classtype )
            {
                ch_println( ch, "&RThis ship is too big to land there!" );
                return;
            }

            if ( target->first_hangar == NULL )
            {
                ch_println( ch, "&RThat ship has no hangars for you to land in!" );
                return;
            }

            /*
                List hangar choices
            */
            if ( NULLSTR( argument ) )
            {
                int cnt = 0;
                ch_println( ch, "&RPlease type the hangar after the ship name." );
                ch_println( ch, "&zPossible choices for &C%s&z:\n", ship->name );

                for ( hangar = target->first_hangar; hangar; hangar = hangar->next )
                {
                    if ( ++cnt == 21 )
                    {
                        ch_println( ch, "&zOnly the first &C20 &zHangars are being displayed." );
                        break;
                    }

                    ch_println( ch, "&zHangar %d: %-11s  &zSlot(s): &C%d/%d  &R%s", cnt,
                               hangar->bayopen ? "&ROpen" : "&CClosed", hangar->size - get_hangar_free( hangar ),
                               hangar->size, get_hangar_free( hangar ) == 0 ? ( xIS_SET( target->flags, SHIP_RESCUESHIP ) ? "(EV ONLY)" : "(FULL)" ) : "" );
                }

                return;
            }
            else
            {
                LINK_LOOKUP( target->first_hangar, HANGAR_DATA, next, atoi( argument ) - 1, hangar );

                if ( hangar == NULL )
                {
                    ch_println( ch, "&RYou can't locate that hangar on the ship!" );
                    return;
                }

                if ( hangar->room == NULL )
                {
                    ch_println( ch, "&RThat hangar isn't complete! Sorry!" );
                    return;
                }

                if ( xIS_SET( hangar->room->flags, ROOM_CLANHANGAR )  )
                {
                    if ( !IS_IMMORTAL( ch ) && ( !ch->pcdata->clan || str_cmp( target->shipowner, ch->pcdata->clan->name ) ) )
                    {
                        ch_println( ch, "&RRestricted hangar. Limited to clans members and ships only." );
                        return;
                    }
                }

                if ( ship->classtype < hangar->room->minshipclass )
                {
                    ch_println( ch, "&RThis ship is too small to land in that hangar.&w" );
                    return;
                }

                if ( ship->classtype > hangar->room->maxshipclass )
                {
                    ch_println( ch, "&RThis ship is too large to land in that hangar.&w" );
                    return;
                }

                if ( get_hangar_free( hangar ) < get_ship_size( ship ) )
                {
                    if ( hangar->size == 0 && xIS_SET( target->flags, SHIP_RESCUESHIP ) )
                    {
                        ch_println( ch, "&RThat hangar can only fit envirosuits." );
                        return;
                    }

                    ch_println( ch, "&RThat hangar doesn't have enough room for your ship!" );
                    return;
                }
            }

            if ( !hangar->bayopen )
            {
                ch_println( ch, "&RThat hangar is closed! They have to open it first!" );
                return;
            }

            if ( vector_distance( &target->vpos, &ship->vpos ) > 25 )
            {
                ch_println( ch, "&RYou must be within 25 units to land on that ship." );
                return;
            }

            if ( target->currspeed > 0 && target->currspeed != ship->currspeed )
            {
                send_to_char
                ( "&RThat ship must stop moving or be moving at the same speed as yours if you want to land on it.\n",
                  ch );
                return;
            }

            /*
                Cleared the checks
            */
            croom = hangar->room;
        }
        else
        {
            ch_println( ch, "&RI don't see that here." );
            do_land( ch, "" );
            return;
        }
    }

    if ( croom != NULL && planet != NULL )
    {
        bool foundstruct = FALSE;

        for ( stru = first_structure; stru; stru = stru->next )
        {
            if ( croom->vnum <= stru->lastroom && croom->vnum >= stru->firstroom && get_room_index( stru->in_room ) != NULL && get_room_index( stru->in_room )->area != NULL && get_room_index( stru->in_room )->area->planet != NULL )
            {
                planet = get_room_index( stru->in_room )->area->planet;
                foundstruct = TRUE;
                break;
            }
        }

        if ( croom->area != NULL && !foundstruct )
        {
            planet = croom->area->planet;
        }
    }

    if ( planet != NULL )
    {
        if ( planet->shields > 25 )
        {
            if ( xIS_SET( croom->flags, ROOM_NOSHIELD ) )
            {
            }
            else if ( planet->governed_by != NULL )
            {
                if ( in_clan( ch ) )
                {
                    if ( ch->pcdata->clan == planet->governed_by )
                    {
                        /*
                            Allow members of the same clan to land
                        */
                        ch_println( ch, "&YYou give the central control your security clearance codes." );
                    }
                    else
                    {
                        /*
                            Allow clanships to land, always
                        */
                        if ( planet->governed_by != ship->clan )
                        {
                            ch_println( ch, "&RThe Planetary shields are preventing you from landing!" );
                            return;
                        }
                    }
                }
                else
                {
                    ch_println( ch, "&RThe Planetary shields are preventing you from landing!" );
                    return;
                }
            }
            else
            {
                ch_println( ch, "&RThe Planetary shields are preventing you from landing!" );
                return;
            }
        }
    }

    /*
        CLANPAD Limit Check
    */
    /*    if ( croom != NULL && !IS_IMMORTAL(ch) )
        {
             if ( xIS_SET( croom->flags, ROOM_CLANPAD ) && !IS_NPC(ch) )
             {
                  clan = croom->area->planet->governed_by;

                  if ( clan != NULL )
                  {
                      if ( ch->pcdata->clan == clan )
                      {
                           ch_println( ch, "&YYou give the traffic control your security clearance codes." );
                      }
                      else if ( clan != ship->clan )
                      {
                           ch_println( ch, "&RRestricted Landing pad. Limited to clans members and ships only." );
                           return;
                      }
                  }
                  else
                  {
                      ch_println( ch, "&RRestricted Landing pad. Limited to clans members and ships only." );
                      return;
                  }
             }
        }*/
    /*  Use the get_pad function and the already-defined 'room' to find the pad. */
    if ( pfound && croom != NULL && ( pad = get_pad_from_room( croom ) ) != NULL )
    {
        /*
            Check to see if the clan's shortname is on either of the lists.
        */
        if ( !IS_IMMORTAL( ch ) && ( !ch->pcdata->clan || !hasname( pad->immlist, ch->pcdata->clan->shortname ) ) )
        {
            ch_println( ch, "&RRestricted Landing pad. Limited to clans members and ships only." );
            return;
        }

        /*
            Check for the required minimum rank of the pad and compare it to the rank of the character.
        */
        if ( pad->rank > 0 && ( division( ch ) == NULL || division( ch )->last_rank == NULL ) )
        {
            ch_println( ch, "&RYour clan leader must first set up the ranks/divisions." );
            return;
        }

        if ( pad->rank > 0 && ( division( ch )->last_rank->num - ch->pcdata->clan_rank > division( ch )->last_rank->num - pad->rank ) )
            // Ralen 05/2017 - previous check incorrect.
        {
            ch_println( ch, "&RYou do not have the required clearance to land at that pad." );
            return;
        }
    }

    if ( croom )
    {
        if ( ship->classtype < croom->minshipclass )
        {
            ch_println( ch, "&RThis ship is too small to land on that pad.&w" );
            return;
        }

        if ( ship->classtype > croom->maxshipclass )
        {
            ch_println( ch, "&RThis ship is too large to land on that pad.&w" );
            return;
        }

        if ( room_fits_ship( croom, get_shipclass_size( ship->classtype ) ) == FALSE )
        {
            ch_println( ch, "There is not enough room for you to land on that pad." );
            return;
        }
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent() > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, find_gsn( ship->classtype ) );
        return;
    }

    begin_landing( ch, ship, pfound, planet, target, arg );

    if ( is_squadleader( ship ) )
    {
        for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
        {
            if ( sq->starsystem != ship->starsystem )
                continue;

            if ( !should_follow_squadleader( sq, ship ) )
                continue;

            if ( vector_distance( &sq->vpos, &ship->vpos ) < 25 )
                begin_landing( NULL, sq, pfound, planet, target, arg );
            else
                message_to_squadleader( sq, "Hold up! I'm too far out to land with you." );
        }
    }
}

void landship( SHIP_DATA* ship, char* argument, int bay )
{
    SPACE_DATA* system = NULL;
    CHAR_DATA* rch = NULL;
    SHIP_DATA* target = NULL;
    char buf[MSL];
    int destination = 0;
    double flt = 0.0;
    char arg[MIL];
    char arg1[MIL];
    PLANET_DATA* planet = NULL;
    HANGAR_DATA* hangar = NULL;
    ROOM_INDEX_DATA* room = NULL, *troom = NULL;
    STRUCTURE_DATA* stru;
    int vnum = 0;
    bool pfound = FALSE, no_space = FALSE;
    strlcpy( arg, argument, MIL );
    argument = one_argument( argument, arg1 );

    if ( !ship->starsystem || ship->starsystem == NULL )
    {
        ship->shipstate = SHIP_DOCKED;
        snprintf( buf, MSL, "[ALERT]: Ship %s has failed landing sequence!", ship->name );
        log_string( buf );
        return;
    }

    system = ship->starsystem;

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( !str_prefix( arg1, planet->plaintext_name ) )
        {
            if ( !planet->first_area )
                continue;

            FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
                for ( vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
                {
                    if ( ( room = get_room_index( vnum ) ) == NULL )
                    {
                        continue;
                    }

                    if ( ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_HIDDEN_LAND )
                            || xIS_SET( room->flags, ROOM_CLANPAD ) )
                            && !str_prefix( argument,
                                            strlen( stripclr( room->name ) ) <= 0 ? room->name : stripclr( room->name ) ) )
                    {
                        destination = room->vnum;

                        if ( !room_fits_ship( room, get_shipclass_size( ship->classtype ) ) )
                            no_space = true;

                        pfound = TRUE;
                        break;
                    }
                }
            })

            for ( stru = first_structure; stru; stru = stru->next )
            {
                if ( planet == get_planet_from_room( get_room_index( stru->in_room ) ) )
                {
                    for ( vnum = stru->firstroom; vnum <= stru->lastroom; vnum++ )
                    {
                        if ( ( room = get_room_index( vnum ) ) == NULL )
                        {
                            continue;
                        }

                        if ( ( xIS_SET( room->flags, ROOM_CAN_LAND ) || xIS_SET( room->flags, ROOM_HIDDEN_LAND )
                                || xIS_SET( room->flags, ROOM_CLANPAD ) )
                                && !str_prefix( argument,
                                                strlen( stripclr( room->name ) ) <= 0 ? room->name : stripclr( room->name ) ) )
                        {
                            destination = room->vnum;

                            if ( !room_fits_ship( room, get_shipclass_size( ship->classtype ) ) )
                                no_space = true;

                            pfound = TRUE;
                            break;
                        }
                    }
                }
            }

            break;
        }
    }

    if ( destination == 0 )
    {
        target = get_ship_here( arg1, ship->starsystem );

        if ( target == NULL || target->name == NULL )
        {
            bug( "(%s)Error in landship module: target == NULL!", ship->name );

            if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
                resetship( ship );

            return;
        }

        LINK_LOOKUP( target->first_hangar, HANGAR_DATA, next, ( bay <= 0 ) ? atoi( argument ) - 1 : bay - 1, hangar );

        if ( hangar == NULL )
        {
            bug( "landship: hangar returned NULL. Aborting" );
            return;
        }

        if ( target != ship && target != NULL && hangar->bayopen )
        {
            destination = hangar->room->vnum;

            if ( get_hangar_free( hangar ) < get_shipclass_size( ship->classtype ) )
                no_space = true;
        } else {
            echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "You were not able to successfully land in that hangar bay." );
            abort_landing( ship->piloting, ship );
            return;
        }
    }

    int lastdoc = ship->lastdoc;

    if ( no_space || !ship_to_room( ship, destination ) )
    {
        echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Could not complete approach. Landing aborted." );
        echo_to_ship_main( AT_YELLOW, ship, "The ship pulls back up out of its landing sequence." );

        if ( ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
            ship->shipstate = SHIP_READY;

        return;
    }

    awaken_ship( ship, FALSE );

    if ( !xIS_SET( ship->flags, SHIP_TRAFFIC ) &&
            ( ( !ship->piloting && ship->classtype < CRUISER_SHIP ) || ship->cloakstatus == CLOAK_ON ) &&
            !( ship->squadleader && ship->squadleader != ship ) )
    {
        if ( ship->cloakstatus == CLOAK_ON )
            echo_to_room( AT_BLOOD, get_room_index( ship->pilotseat ),
                          "Without instrumentation to guide the landing, the ship crash lands into the ground!" );
        else
            echo_to_room( AT_BLOOD, get_room_index( ship->pilotseat ),
                          "There is nobody piloting the ship, so it crash lands into the ground!" );

        echo_to_ship_main( AT_BLOOD, ship, "The entire ship shakes as it crashes into something!" );

        if ( pfound )
        {
            if ( planet->plaintext_name )
            {
                if ( ship->cloakstatus == CLOAK_ON )
                {
                    snprintf( buf, MSL, "%s shimmers into existence just before it crash lands on the surface of %s, disappearing from your scanner.", ship->name,
                             planet->plaintext_name );
                    ship->cloakstatus = CLOAK_READY;
                    ship->cloakstatus = CLOAK_DAMAGED;

                    if ( xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - deactivating cloak allows ping.
                    {
                        xREMOVE_BIT( ship->flags, SHIP_NO_PING );
                    }
                }
                else
                    snprintf( buf, MSL, "%s crash lands on the surface of %s, disappearing from your scanner.", ship->name,
                             planet->plaintext_name );

                echo_to_system_noqueue_noship( AT_BLOOD, system, buf );
            }
            else
            {
                if ( ship->cloakstatus == CLOAK_ON )
                {
                    snprintf( buf, MSL, "%s shimmers into existence just before it crash lands on the surface, disappearing from your scanner.", ship->name );
                    ship->cloakstatus = CLOAK_READY;
                    ship->cloakstatus = CLOAK_DAMAGED;

                    if ( xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - deactivating cloak allows ping.
                    {
                        xREMOVE_BIT( ship->flags, SHIP_NO_PING );
                    }
                }
                else
                    snprintf( buf, MSL, "%s crash lands on the surface, disappearing from your scanner.", ship->name );

                echo_to_system_noqueue_noship( AT_BLOOD, system, buf );
            }
        }
        else if ( target->name )
        {
            if ( ship->cloakstatus == CLOAK_ON )
            {
                snprintf( buf, MSL, "%s shimmers into existence as it makes a crash landing in %ss hangar!", ship->name, target->name );
                ship->cloakstatus = CLOAK_READY;
                ship->cloakstatus = CLOAK_DAMAGED;

                if ( xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - deactivating cloak allows ping.
                    xREMOVE_BIT( ship->flags, SHIP_NO_PING );
            }
            else
                snprintf( buf, MSL, "%s makes a crash landing in %ss hangar!", ship->name, target->name );

            target->hull -= ( int )( ship->maxhull * 0.2 ) * ( ship->classtype + 1 );

            if ( ship->classtype >= FRIGATE_SHIP )
                target->hull -= ( int )( ship->maxhull * 0.3 ) * 2;

            echo_to_system_noqueue_noship( AT_BLOOD, system, buf );

            if ( target->hull <= 0 )
            {
                char buf2[MSL];
                snprintf( buf2, MSL, "The crash landing causes a series of explosions on %s!", target->name );
                echo_to_system_noqueue_noship( AT_YELLOW, system, buf2 );
                target->hull = 1;
                target->shipstate = SHIP_DISABLED;
                echo_to_room( AT_BLOOD, get_room_index( ship->pilotseat ), "The ship you crash onto is badly damaged!" );
                echo_to_ship_main( AT_BLOOD, target, "The ship shudders and warning sirens sound." );
                echo_to_ship_main( AT_BLOOD, ship, "Even more explosions rock the ship, these ones much more violent." );
                save_ship( target, true );
            }
        }

        flt = ship->classtype + 3;
        flt /= 10;
        ship->hull -= ( int )( ship->maxhull * flt );

        if ( ship->hull <= 0 )
            ship->hull = 1;

        snprintf( buf, MSL, "&R%s crashes into the ground here!", ship->name );
        ship_action( ship, buf );
        ship->shipstate = SHIP_DISABLED;
        save_ship( ship, true );

        for ( troom = ship->first_room; troom; troom = troom->next_in_range )
        {
            if ( troom->first_person == NULL )
                continue;

            for ( rch = troom->first_person; rch; rch = rch->next_in_room ) // No more stunning/morting chars - this was kinda ghey
            {
                rch->hit = URANGE( 1, rch->hit - number_range( 100, 900 ), rch->max_hit );
                WAIT_STATE( rch, 20 ); // Massive lag instead of freaking morting
                ch_println( rch, "&RYou are injured as the ship comes crashing down!" );
            }
        }

        lua_trigger_ship_landed( ship, get_room_index( ship->location ), system );
        return;
    }

    // GRAL Should these be moved into planet/target for different messages?
    echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Landing sequence complete." );
    echo_to_ship_main( AT_YELLOW, ship, "You feel a slight thud as the ship sets down on the ground." );

    if ( pfound )
    {
        if ( planet->plaintext_name )
            snprintf( buf, MSL, "%s lands on the surface of %s, disappearing from your scanner.", ship->name, planet->plaintext_name );
        else
            snprintf( buf, MSL, "%s lands on the surface, disappearing from your scanner.", ship->name );
    }

    if ( !pfound )
        if ( target->name )
            snprintf( buf, MSL, "%s lands in a hangar on %s, disappearing from your scanner.", ship->name, target->name );

    echo_to_system_noqueue_noship( AT_YELLOW, system, buf );

    if ( ship->piloting )
    {
        learn_from_success( ship->piloting, find_gsn( ship->classtype ) );

        if ( ship->in_room && system != starsystem_from_vnum( lastdoc ) )
        {
            int xp = ( exp_level( ship->piloting->skill_level[PILOTING_ABILITY] + 1 ) - exp_level( ship->piloting->skill_level[PILOTING_ABILITY] ) );
            xp = UMIN( get_ship_value( ship ), xp );
            xp = apply_xp_sink( ship->piloting, xp, PILOTING_ABILITY );
            gain_exp( ship->piloting, xp, PILOTING_ABILITY, TRUE );
            ch_println( ship->piloting, "&WYou gain %ld points of flight experience!", UMIN( get_ship_value( ship ), xp ) );
        }
    }

    ship->last_landed = system;
    ship->hyperlock = FALSE;
    ship->calctimer = 0;

    if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        ship->trafficstate = TRAFFIC_NONE;

    if ( ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        ship->shipstate = SHIP_DOCKED;

    snprintf( buf, MSL, "&Y%s lands on the platform.", ship->name );
    ship_action( ship, buf );
    ship->energy = ship->energy - 25 * ( ship->classtype + 1 );
    ship->tankpurge = FALSE;
    check_repair_public( ship, FALSE );
    save_ship( ship, true );
    lua_trigger_ship_landed( ship, get_room_index( ship->location ), system );
}

CMDF do_accelerate( CHAR_DATA* ch, char* argument )
{
    int chance;
    int change;
    sh_int prev_speed;
    SHIP_DATA* ship;
    char buf[MSL];
    PLANET_DATA* planet = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "&RYou're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RThe controls must be at the pilots chair..." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( !ship->starsystem )
    {
        ch_println( ch, "A little hard to do that while landed." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        if ( xIS_SET( ship->flags, SHIP_ONEHYPER ) && ship->hyperspeed == 0 )
        {
            ch_println( ch, "&RShip Platforms can't move!" );
            return;
        }
    }

    /*
        if ( ship->shipstate == SHIP_TRACTORED)
        {
        chance = (ship->maneuver + ship->realspeed - ( ship->class > 1 ? ship->class:1) * 10 ) / 100;
        chance = URANGE(1, chance , 67 );
        if ( number_percent() > chance )
        {
        ch_println( ch, "You're stuck in a tractor beam!" );
        return;
        }
        else
        {
        send_to_char("You slam the throttle, breaking free of the tractor beam!\n",
    */
    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to accelerate." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( atoi( argument ) > ship->realspeed )
    {
        snprintf( buf, MSL, "%d", ship->realspeed );
        argument = buf;
    }

    if ( atoi( argument ) == ship->currspeed )
    {
        ch_println( ch, "&wYou're already traveling that speed." );
        return;
    }

    if ( ship->energy < abs( ( atoi( argument ) - abs( ship->currspeed ) ) / 10 ) )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED && ship->dockship != NULL )
    {
        if ( !ship->dock_lead )
        {
            ch_println( ch, "&RNot while you're docked! Get the other ship to do that!" );
            return;
        }

        if ( atoi( argument ) > ship->dockship->realspeed )
        {
            ch_println( ch, "&RThe currently docked ship can not support those speeds!" );
            return;
        }
    }

    if ( ship->head.x == 0 && ship->vpos.x == 0 && ship->head.y == 0 && ship->vpos.y == 0 && ship->head.z == 0 && ship->vpos.z == 0 )
    {
        Vector3 tempvect;
        vector_init( &tempvect );
        tempvect.x = ship->head.x + number_range( 100, 10000 );
        tempvect.y = ship->head.y + number_range( 100, 10000 );
        tempvect.z = ship->head.z + number_range( 100, 10000 );
        ship_set_course( ship, &tempvect );
    }

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( xIS_SET( planet->flags, PLANET_MOON ) )
            continue;

        if ( xIS_SET( planet->flags, PLANET_STAR ) )
            continue;

        if ( planet->pos.x == ship->vpos.x && planet->pos.y == ship->vpos.y && planet->pos.z == ship->vpos.z )
        {
            // If we're speeding up from orbit, we should move the ship a distance of 20 from the planet to ensure it doesn't insta-reorbit.
            prev_speed = ship->currspeed;
            ship->currspeed = 100;
            ship_move( ship );
            ship->currspeed = prev_speed;
            break;
        }
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, find_gsn( ship->classtype ) );
        return;
    }

    change = URANGE( 0, atoi( argument ), ship->realspeed );
    act( AT_PLAIN, "$n manipulates the ship's controls.", ch, NULL, argument, TO_ROOM );

    if ( change > ship->currspeed )
    {
        ch_println( ch, "&GAccelerating" );

        if ( is_squadleader( ship ) )
        {
            for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( sq->starsystem != ship->starsystem )
                    continue;

                if ( sq != ship && sq->squadleader == ship && sq->realspeed < change )
                {
                    ch_println( ch, "&YWarning: &wAt least one of your squadron ships won't be able to match that speed." );
                    break;
                }
            }
        }

        echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to accelerate." );
        snprintf( buf, MSL, "%s begins to speed up.", ship->name );

        if ( ship->cloakstatus != CLOAK_ON )
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );

        for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
            if ( vector_distance( &ship->vpos, &planet->pos ) <= 10 )
                break;

        // Fairly sure this was here to prevent tractor rape, but it also creates a nasty skiing bug
        // that enables ships to move very quickly if accelerate is spammed.  Let's remove it for now
        // and think about how to fix tractor beams properly.  This was not a great solution (if it ever even
        // really solved that problem).
        //
        // Finally, as a note, ships move every 2 seconds.  This is not essential for "realism" IMHO.
        //
        // Opinion by Miros
        // Decision by Gathorn, Miros, and Sanshiro
        // 6-15-14
        // ship->vpos.x += 11;
    }

    if ( change < ship->currspeed && ( ship->currspeed - change ) > 0 )
    {
        ch_println( ch, "&GDecelerating" );
        echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to slow down." );
        snprintf( buf, MSL, "%s begins to slow down.", ship->name );

        if ( ship->cloakstatus != CLOAK_ON )
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
    }

    if ( change == 0 )
    {
        echo_to_ship_windows( AT_YELLOW, ship, "The ship comes to a halt." );
        snprintf( buf, MSL, "%s comes to a halt.", ship->name );

        if ( ship->cloakstatus != CLOAK_ON )
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
    }

    ship->energy -= abs( ( change - abs( ship->currspeed ) ) / 15 );
    ship->currspeed = URANGE( 0, change, ship->realspeed );

    /*
        Accelerate our docked ship too
    */
    if ( ship->dock_state == DOCK_DOCKED && ship->dockship != NULL )
        ship->dockship->currspeed = ship->currspeed;

    learn_from_success( ch, find_gsn( ship->classtype ) );
}

/*
    Selfdestruct Module. Priceless Code :)
*/
CMDF do_selfdestruct( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    char arg2[MSL];
    int change;
    SHIP_DATA* ship;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RThe controls must be at the pilots chair..." );
        return;
    }

    if ( is_rental( ch, ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RYou can't self-destruct public shuttles, sorry." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
    {
        ch_println( ch, "&RIt won't be long now..." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
    {
        ch_println( ch, "&RYou can't self-destruct an envirosuit." );
        return;
    }

    if ( !IS_IMMORTAL( ch ) && xIS_SET( ship->flags, SHIP_NO_SELFD ) )
    {
        ch_println( ch, "&RYou can't self-destruct this ship." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CSelfdestruct <&waccess code&C> <&wtime delay&C>" );
        ch_println( ch, "&R [Deactivating Selfdestruct: Selfdestruct <code> 0]" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( atoi( arg1 ) != ship->code[SCODE_SELFD] )
    {
        ch_println( ch, "&RIncorrect Access Code! You need to know the ship's self-destruct code!" );
        return;
    }

    change = atoi( arg2 );

    if ( NULLSTR( arg2 ) )
        change = -1;

    if ( ship->selfd_armed && change != 0 )
    {
        ch_println( ch, "&RIt's already ARMED!\nUse 'SELFDESTRUCT <access code> 0' to abort the countdown." );
        return;
    }

    act( AT_PLAIN, "$n manipulates the emergency override controls.", ch, NULL, argument, TO_ROOM );

    if ( ( ship->selfd_armed ) && ( change == 0 ) )
    {
        ship->selfd_time = 0;   /* Deactivate self destruct */
        ship->selfd_armed = FALSE;
        ch_println( ch, "&RSelf Destruct Disengaged. All systems restored to Normal." );
        echo_to_ship_main( AT_YELLOW, ship, "ALERT: SELF-DESTRUCT ABORT: SYSTEMS RESTORED." );
        SET_STRING( ship->selfd_by, "" );
        return;
    }

    if ( ( change > 1200 || change < 120 ) && !IS_NPC( ch ) )
    {
        ch_println( ch, "&RInvalid Arming Attempt. Range is 120 to 1200 Seconds (20 Minutes)." );
        return;
    }

    if ( ( change > 1800 || change < 30 ) && IS_NPC( ch ) )
    {
        ch_println( ch, "&RInvalid SELFD Attempt. NPC Range is 30 to 1800 Seconds." );
        return;
    }

    ship->selfd_time = change;  /* Activate self destruct */
    ship->selfd_armed = TRUE;
    SET_STRING( ship->selfd_by, !IS_NPC( ch ) ? ch->name : ch->short_descr );
    ch_println( ch, "&RSelf Destruct Engaged. Please evacuate the ship!" );
    echo_to_ship_windows( AT_YELLOW, ship, "WARNING: SELF-DESTRUCT ENGAGED: EVACUATE THE SHIP!" );
    echo_to_shipNC( AT_RED, ship, "Warning sirens begin to screech through the hallways..." );
}

/*
    AUTOLAUNCH Module.

    Syntax: AUTOLAUNCH <delay>

    Hopefully, a very useful system. Once set, the 'autolaunch'
    timer counts down to 0, and then launchs the ship. Typing
    AUTOLAUNCH 0 will override the launch timer.
*/
CMDF do_autolaunch( CHAR_DATA* ch, char* argument )
{
    int change;
    SHIP_DATA* ship;

    /*
        Patch to negate possed mobs and pets
        Why not just disable ALL NPCs? To save us the NULL crashes? - Gathorn 23 Sept 17
    */
    if ( IS_NPC( ch ) )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( is_rental( ch, ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RPublic shuttles are not equipped with autolaunch systems. Sorry." );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RThe controls would be at the pilots chair..." );
        return;
    }

    /*
        if ( ship->classtype == FIGHTER_SHIP )
        {
        ch_println( ch, "&RFighters are not equipped with autolaunch systems. Sorry." );
        return;
        }
    */

    if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
    {
        ch_println( ch, "&RHey, that's not your ship!" );
        return;
    }

    if ( ship->shipstate != SHIP_DOCKED )
    {
        ch_println( ch, "&RIt wont do much good launching unless you're docked!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
    {
        ch_println( ch, "You cannot launch this ship with a broken hatch!" );
        return;
    }

    if ( !check_vong_ship_control( ch, ship ) )
        return;

    CLAN_DATA* clan_owner = ship->clan;

    if ( clan_owner &&
            ship->classtype >= FRIGATE_SHIP &&
            capital_points_used( clan_owner ) + ship_capital_points( ship ) > capital_points_max( clan_owner )
       )
    {
        ch_println( ch, "&RYour clan doesn't have capacity to launch this ship right now!" );
        return;
    }

    change = atoi( argument );

    if ( NULLSTR( argument ) )
        change = -1;

    if ( ship->autolaunch_armed && change != 0 )
    {
        ch_println( ch, "&RIt's already armed!\nUse AUTOLAUNCH '0' to abort the countdown." );
        return;
    }

    act( AT_PLAIN, "$n manipulates the remote launch controls.", ch, NULL, argument, TO_ROOM );

    if ( ( ship->autolaunch_armed ) && ( change == 0 ) )
    {
        ship->autolaunch_time = 0;
        ship->autolaunch_armed = FALSE;
        ch_println( ch, "&RAutolaunch Disengaged. Ship has returned to standby mode." );
        return;
    }

    if ( ( change > 600 || change < 30 ) )
    {
        ch_println( ch, "&RInvalid Delay. Range is 30 to 600 Seconds." );
        return;
    }

    ship->autolaunch_time = change; /* Activate autolaunch */
    ship->autolaunch_armed = TRUE;
    ch_println( ch, "&RAutolaunch Engaged. Ship systems switching to active." );
    return;
}

CMDF do_trajectory( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg2[MIL];
    char arg3[MIL];
    char arg4[MIL];
    char arg5[MIL];
    int chance;
    double vx, vy, vz;
    SHIP_DATA* ship;
    SHIP_DATA* target;
    PLANET_DATA* planet;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis vessel is immobile!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou're not in the pilots seat." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to disengage the ship's autopilot first." );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED && !ship->dock_lead )
    {
        ch_println( ch, "&RNot while docked! Get the other ship to do that!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to maneuver." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "&RPlatforms can't move, what would be the point?" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( ship->energy < ( ship->currspeed / 10 ) )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, find_gsn( ship->classtype ) );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Ccourse <&wx&C> <&wy&C> <&wz&C>" );
        ch_println( ch, "&zSyntax: &Ccourse <&wship or planet name&C>" );
        ch_println( ch, "&zSyntax: &Ccourse rel(ative) <&wx diff&C> <&wy diff&C> <&wz diff&C>" );
        ch_println( ch, "&zSyntax: &Ccourse away <&wship or planet name&C>" );
        return;
    }

    char* after_arg2 = one_argument( argument, arg2 );
    char* after_arg3 = one_argument( after_arg2, arg3 );
    char* after_arg4 = one_argument( after_arg3, arg4 );
    one_argument( after_arg4, arg5 );

    // Relative coursing moves you this amount X/Y/Z away from your current location.
    if ( !str_prefix( arg2, "relative" ) && is_number_sym( arg3 ) && is_number_sym( arg4 ) && is_number_sym( arg5 ) )
    {
        vx = ship->vpos.x + atoi( arg3 );
        vy = ship->vpos.y + atoi( arg4 );
        vz = ship->vpos.z + atoi( arg5 );
    }
    else if ( !str_cmp( arg2, "away" ) && !NULLSTR( after_arg2 ) )
    {
        if ( ( planet = get_planet_here( after_arg2, ship->starsystem ) ) != NULL )
        {
            vx = URANGE( -50000, ship->vpos.x + ( ship->vpos.x - planet->pos.x ), 50000 );
            vy = URANGE( -50000, ship->vpos.y + ( ship->vpos.y - planet->pos.y ), 50000 );
            vz = URANGE( -50000, ship->vpos.z + ( ship->vpos.z - planet->pos.z ), 50000 );
        }
        else if ( ( target = get_ship_here( after_arg2, ship->starsystem ) ) != NULL )
        {
            vx = URANGE( -50000, ship->vpos.x + ( ship->vpos.x - target->vpos.x ), 50000 );
            vy = URANGE( -50000, ship->vpos.y + ( ship->vpos.y - target->vpos.y ), 50000 );
            vz = URANGE( -50000, ship->vpos.z + ( ship->vpos.z - target->vpos.z ), 50000 );
        }
        else
        {
            ch_println( ch, "No local ship or stellar object found by that name." );
            return;
        }
    }
    else if ( is_number_sym( arg2 ) && is_number_sym( arg3 ) && is_number_sym( arg4 ) )
    {
        vx = atoi( arg2 );
        vy = atoi( arg3 );
        vz = atoi( arg4 );
    }
    else
    {
        if ( ( planet = get_planet_here( argument, ship->starsystem ) ) != NULL )
        {
            vx = planet->pos.x;
            vy = planet->pos.y;
            vz = planet->pos.z;
        }
        else if ( ( target = get_ship_here( argument, ship->starsystem ) ) != NULL )
        {
            vx = target->vpos.x;
            vy = target->vpos.y;
            vz = target->vpos.z;
        }
        else if ( ( planet = get_planet_here( arg2, ship->starsystem ) ) != NULL )
        {
            vx = planet->pos.x;
            vy = planet->pos.y;
            vz = planet->pos.z;
        }
        else if ( ( target = get_ship_here( arg2, ship->starsystem ) ) != NULL )
        {
            vx = target->vpos.x;
            vy = target->vpos.y;
            vz = target->vpos.z;
        }
        else
        {
            ch_println( ch, "No local ship or stellar object found by that name." );
            return;
        }
    }

    if ( vx == ship->vpos.x && vy == ship->vpos.y && vz == ship->vpos.z && ship->cloakstatus != CLOAK_ON ) //Idea is cloaking should not give you any way to figure out your current coords or coords of other ships. - Gathorn 17Jan19
    {
        ch_printf( ch, "&RThe ship is already at %.0f %.0f %.0f!", vx, vy, vz );
        return;
    }

    if ( vx > 50000 || vy > 50000 || vz > 50000 || vx < -50000 || vy < -50000 || vz < -50000 )
    {
        ch_println( ch, "Valid range for course is -50,000 to 50,000." );
        return;
    }

    Vector3 tempvect;
    vector_init( &tempvect );
    tempvect.x = vx;
    tempvect.y = vy;
    tempvect.z = vz;
    ship_set_course( ship, &tempvect );

    if ( ship->dock_state == DOCK_DOCKED && ship->dockship != NULL )
    {
        vector_copy( &ship->dockship->vpos, &ship->vpos );
        ship_align_heading( ship->dockship, ship );
        ship->dockship->energy -= ( ship->currspeed / 20 );
    }

    ship->energy -= ( ship->currspeed / 10 );

    if ( ship->cloakstatus == CLOAK_ON ) //Idea is cloaking should not give you any way to figure out your current coords or coords of other ships. - Gathorn 17Jan19
    {
        ch_println( ch, "&GNew course set." );
        act( AT_PLAIN, "$n manipulates the ship's controls.", ch, NULL, NULL, TO_ROOM );
    }
    else
    {
        ch_println( ch, "&GNew course set, approaching %.0f %.0f %.0f.", vx, vy, vz );
        act( AT_PLAIN, "$n manipulates the ship's controls.", ch, NULL, NULL, TO_ROOM );
    }

    echo_to_ship_windows( AT_YELLOW, ship, "The ship begins to turn." );
    snprintf( buf, MSL, "%s turns, altering its present course.", ship->name );

    if ( ship->cloakstatus != CLOAK_ON )
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );

    ship->shipstate = SHIP_BUSY;
    ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
    learn_from_success( ch, find_gsn( ship->classtype ) );
}


CMDF do_buyship( CHAR_DATA* ch, char* argument )
{
    long price = 0;
    SHIP_DATA* ship = NULL;

    if ( IS_NPC( ch ) || !ch->pcdata )
    {
        ch_println( ch, "&ROnly players can do that!" );
        return;
    }

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ch->in_room->vnum == 45 )
    {
        ch_println( ch, "You may not purchase a ship from Limbo Shipyard." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cbuyship <&wship name&C>" );
        return;
    }

    ship = ship_in_room( ch->in_room, argument );

    if ( !ship )
    {
        /*
            ship = get_ship_from_cockpit( ch->in_room );
        */
        if ( !ship )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, argument, TO_CHAR );
            return;
        }
    }

    if ( str_cmp( ship->shipowner, "" ) )
    {
        send_to_char( "&RThat ship isn't for sale!", ch );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_VONG ) && !xIS_SET( ch->race->flags, RFLAG_VONG ) )
    {
        ch_println( ch, "&RThat ship doesn't have any standard identification markers, how do you expect to register ownership?" );
        return;
    }

    if ( check_permit( ch, PERMIT_MULTI_SHIP ) )
    {
        if ( count_ships( ch->name ) >= 20 )
        {
            ch_println( ch, "&RYou can only own up to 20 ships with a permit!" );
            return;
        }
    }
    else if ( count_ships( ch->name ) >= 3 )
    {
        ch_println( ch, "&RYou can only own up to 3 ships without a permit!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) && count_legendary_ships( ch->name ) > 0 )
    {
        ch_println( ch, "&RYou can only own one legendary ship!" );
        return;
    }

    price = get_ship_value( ship );

    if ( ch->gold < price )
    {
        ch_println( ch, "&RThis ship costs %ld. You don't have enough credits!", price );
        return;
    }

    if ( ship->classtype >= FRIGATE_SHIP )
    {
        ch_println( ch, "You may not purchase capital class ships, only clans can do that." );
        return;
    }

    ch->gold -= price;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "do_buyship", price * -1, TRUE );

    ch_println( ch, "&GYou pay %ld credits to purchase the ship.", price );
    act( AT_PLAIN, "$n walks over to a terminal and makes a credit transaction.", ch, NULL, argument, TO_ROOM );
    SET_STRING( ship->shipowner, ch->name );
    ship->clan = NULL;
    save_ship( ship, true );
}

