        return;
    }

    if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) )
    {
        ch_println( ch, "&RYour organization cannot purchase that ship!" );
        return;
    }

    price = get_ship_value( ship );

    if ( ch->pcdata->clan->funds < price )
    {
        ch_println( ch, "&RThis ship costs %ld. %s doesn't have enough credits!", price, ch->pcdata->clan->name );
        return;
    }

    if ( ( ship->shipstate != SHIP_DOCKED || ship->starsystem != NULL ) && ship->classtype >= FRIGATE_SHIP && ( capital_points_used( ch->pcdata->clan ) + ship_capital_points( ship ) > capital_points_max( ch->pcdata->clan ) ) )
    {
        ch_println( ch, "&R%s does not have the capacity to take ownership of this right now!", ch->pcdata->clan->name );
        return;
    }

    char reason[MIL];
    snprintf( reason, MIL, "Purchased ship %s", ship->name );
    mod_clan_funds( ch->pcdata->clan, ch, (price * -1), FUNC, reason );
    ch_println( ch, "&G%s pays %ld credits to purchase the ship.", clan->name, price );
    act( AT_PLAIN, "$n walks over to a terminal and makes a credit transaction.", ch, NULL, argument, TO_ROOM );
    SET_STRING( ship->shipowner, clan->name );
    ship->clan = clan;
    save_ship( ship, true );
}

CMDF do_sellship( CHAR_DATA* ch, char* argument )
{
    long price = 0;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Csellship <&wship name&C>" );
        return;
    }

    SHIP_DATA* ship = ship_in_room( ch->in_room, argument );

    if ( !ship )
    {
        act( AT_PLAIN, "I see no $T here.", ch, NULL, argument, TO_CHAR );
        return;
    }

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( str_cmp( ship->shipowner, ch->name ) )
    {
        ch_println( ch, "&RThat isn't your ship!" );
        return;
    }

    if ( in_squadron( ship ) )
    {
        ch_println( ch, "&RThat ship must be removed from its squadron before being sold." );
