    SET_STRING( ship->shipowner, "" );
    SET_STRING( ship->pilot, "" );
    SET_STRING( ship->copilot, "" );
    SET_STRING( ship->crew, "" );
    ship->clan = NULL;

    /*
        Randomize Codes
    */
    for ( int i = 0; i < MAX_SCODE_TYPES; i++ )
        ship->code[i] = number_range( 11111, 99999 );

    save_ship( ship, true );
    return;
}

