CMDF do_tradeship( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    SHIP_DATA* ship = NULL;
    CHAR_DATA* victim = NULL;
    bool clntrd = FALSE;
    bool owned = FALSE;
    bool self = FALSE;
    bool clantradeship = false;
    bool clan_pirated = false;
    bool pirated_ship = false;
    int i = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CTRADESHIP <&wship&C> <&wnew owner&C>" );
        ch_println( ch, "&R The new owner must be in the room with you." );
        return;
    }

    ship = ship_in_room( ch->in_room, arg1 );

    if ( !ship )
    {
        ship = get_ship_from_cockpit( ch->in_room );

        if ( !ship )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, arg1, TO_CHAR );
            return;
        }
    }

    if ( !str_cmp( ship->shipowner, ch->name ) )
        owned = TRUE;

    if ( is_stolen_ship( ch, ship, &clan_pirated ) )
    {
        owned = TRUE;
        pirated_ship = true;
    }

    if ( ch->pcdata->clan )
        if ( !str_cmp( ship->shipowner, ch->pcdata->clan->name ) || !str_cmp( ship->stolen, ch->pcdata->clan->name ) )
            if ( is_empowered( ch, "clantradeship" ) || !str_cmp( ch->name, ch->pcdata->clan->leader ) )
            {
                owned = TRUE;
                clantradeship = true;
            }

    if ( !owned )
    {
        send_to_char( "&RThat isn't your ship!", ch );
        return;
    }

    if ( !str_cmp( arg2, "none" ) )
    {
        if ( !pirated_ship )
        {
            ch_println( ch, "You can only use this to release a stolen ship." );
            return;
        }

        if ( clan_pirated && !clantradeship )
        {
            ch_println( ch, "Your clan has not empowered you to do that!" );
            return;
        }

        SET_STRING( ship->stolen, "" );
        save_ship( ship, true );
        ch_println( ch, "You relinquish all illegal ties to the ship." );
        return;
    }

    victim = get_char_room( ch, arg2 );

    if ( !str_cmp( argument, "clan" ) )
        self = TRUE;

    if ( !victim )
    {
        ch_println( ch, "I don't see any %s here...", arg2 );
        return;
    }

    if ( victim == ch && ( !self ) )
    {
        ch_println( ch, "You can't transfer the ownership to yourself!" );
        return;
    }

    if ( is_stolen_ship( ch, ship, NULL ) && !can_steal_ship( victim ) && !self )
    {
        send_to_char
        ( "You cannot give them another stolen ship.\nHave them PIRATESHIP RELEASE to relinquish their hold on their current ship.\n",
          ch );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "You can't transfer the ownership to a mobile!" );
        return;
    }

    if ( !str_cmp( "clan", argument ) )
    {
        if ( ch->pcdata && victim->pcdata )
        {
            if ( victim->pcdata->clan )
                clntrd = TRUE;
            else
            {
                ch_println( ch, "They have to be in a clan to trade to their clan." );
                return;
            }
        }
    }

    if ( clntrd && xIS_SET( ship->flags, SHIP_LEGENDARY ) )
    {
        ch_println( ch, "&RYou cannot trade this ship to their organization!" );
        return;
    }

    if ( !clntrd && xIS_SET( ship->flags, SHIP_LEGENDARY ) && count_legendary_ships( victim->name ) > 0 )
    {
        ch_println( ch, "&RYou cannot trade that ship to them!" );
        return;
    }

    if ( pirated_ship )
    {
        if ( clntrd )
        {
            if ( victim->pcdata->clan->clan_type != CLAN_CRIME )
            {
                ch_println( ch, "Their clan cannot take ownership of stolen goods." );
                return;
            }
            else if ( clan_count_active_members( victim->pcdata->clan ) <= clan_count_stolen_ships( victim->pcdata->clan ) )
            {
                ch_println( ch, "Their clan cannot own any more stolen ships!" );
                return;
            }
            else
            {
                squadron_remove( ship, NULL );
                SET_STRING( ship->stolen, victim->pcdata->clan->name );
                save_ship( ship, true );
            }
        }
        else
        {
            squadron_remove( ship, NULL );
            SET_STRING( ship->stolen, victim->name );
            save_ship( ship, true );
        }

        ch_println( ch, "You transfer your stolen ship over to them." );
        ch_println( victim, "%s transfers their stolen ownership of %s.", g_name( ch, victim ), ship->name );
        return;
    }

    if ( check_permit( victim, PERMIT_MULTI_SHIP ) && ( !self ) )
    {
        if ( count_ships( victim->name ) >= 20 )
        {
            ch_println( ch, "&RThey can only own up to 20 ships with a permit!" );
            return;
        }
    }
    else if ( count_ships( victim->name ) >= 3 && ( !self ) )
    {
        ch_println( ch, "&RThey can only own up to 3 ships without a permit!" );
        return;
    }

    if ( !clntrd && ship->classtype >= FRIGATE_SHIP )
    {
        ch_println( ch, "&RPlayers cannot own capital ships!" );
        return;
    }

    if ( clntrd && ( ship->shipstate != SHIP_DOCKED || ship->starsystem != NULL ) && ship->classtype >= FRIGATE_SHIP && ( capital_points_used( victim->pcdata->clan ) + ship_capital_points( ship ) > capital_points_max( victim->pcdata->clan ) ) )
    {
        ch_println( ch, "&RThey do not have the capacity to take ownership of this right now!" );
        return;
    }

    ch_println( ch, "&GTransaction complete. That ship is no longer owned by you." );
    act( AT_PLAIN, "$n walks over to a terminal and makes a transaction.", ch, NULL, argument, TO_ROOM );

    if ( !clntrd )
        ch_println( victim, "&Y%s is now under your ownership.", ship->name );

    if ( clntrd )
        ch_println( victim, "&Y%s is now under %s's ownership.", ship->name, victim->pcdata->clan->name );


    squadron_remove( ship, NULL );
    SET_STRING( ship->shipowner, clntrd ? victim->pcdata->clan->name : victim->name );
    SET_STRING( ship->pilot, "" );
    SET_STRING( ship->copilot, "" );
    SET_STRING( ship->crew, "" );
    ship->clan = clntrd ? victim->pcdata->clan : NULL;

    /*
        Randomize Codes
    */
    for ( i = 0; i < MAX_SCODE_TYPES; i++ )
        ship->code[i] = number_range( 11111, 99999 );

    save_ship( ship, true );
    return;
}

CMDF do_info( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    SHIP_DATA* ship = NULL;
    SHIP_DATA* target = NULL;
    int pods = 0;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( vehicle_info( ch, argument ) )
        return;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        if ( NULLSTR( argument ) )
        {
            act( AT_PLAIN, "Which ship or vehicle do you want info on?", ch, NULL, NULL, TO_CHAR );
            return;
        }

        ship = ship_in_room( ch->in_room, argument );

        if ( !ship )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, argument, TO_CHAR );
            return;
        }

        target = ship;
    }
    else if ( NULLSTR( argument ) )
        target = ship;
    else
        target = get_ship_here( argument, ship->starsystem );

    if ( ship->cloakstatus == CLOAK_ON && ship != target )
    {
        ch_println( ch, "&RYour sensors are no good with the cloaking generator on!&w" );
        return;
    }

    if ( target == NULL || ( target->cloakstatus == CLOAK_ON && ship != target ) )
    {
        ch_println( ch, "&RI don't see that here.\nTry the radar, or type info by itself for info on this ship." );
        return;
    }

    if ( vector_distance( &target->vpos, &ship->vpos ) > 500 + ship->sensor * 2 )
    {
        ch_println( ch, "&RThat ship is too far away to scan." );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_OBJECT ) )
    {
        ch_printf( ch, "&z[&CClass: Unknown&z] : &C%s&z\n&B", target->name );

        if ( !NULLSTR( target->description ) )
            ch_println( ch, "&z%s", target->description );
        else if ( target->template && !NULLSTR( target->template->description ) )
            ch_println( ch, "&z%s", target->template->description );

        return;
    }

    if ( xIS_SET( target->flags, SHIP_VONG ) )
    {
        if ( xIS_SET( ship->flags, SHIP_VONGSCAN ) || xIS_SET( ship->flags, SHIP_VONG ) )
        {
            ch_println( ch, "&137[&065Class: &070%s&137] : &070%s", class_types[target->classtype], target->name );

            if ( !NULLSTR( target->description ) )
                ch_println( ch, "&065%s", target->description );
            else if ( target->template && !NULLSTR( target->template->description ) )
                ch_println( ch, "&065%s", target->template->description );

            bool show_personnel = ( !str_cmp( target->shipowner, ch->name ) || check_clanpilot( ch, target ) || IS_IMMORTAL( ch ) );
            ch_println( ch, "&137Owner: &239[%s%-14s&239]   &137Pilot: &239[%s%-14s&239]   &137Copilot: &239[%s%-14s&239]",
                       show_personnel ? "&070" : "&239",
                       show_personnel ? target->shipowner : " ------------ ",
                       show_personnel || !str_cmp( target->pilot, ch->name ) ? "&070" : "&239",
                       show_personnel || !str_cmp( target->pilot, ch->name ) ? target->pilot : " ------------ ",
                       show_personnel || !str_cmp( target->copilot, ch->name ) ? "&070" : "&239",
                       show_personnel || !str_cmp( target->copilot, ch->name ) ? target->copilot : " ------------ "
                     );

            if ( show_personnel )
                ch_println( ch, "&137Crew:  &239[&070%s &239]", target->crew );

            ch_println( ch, "\n&239--&065Weapons&239----------------------" );
            ch_println( ch, "&137Yaret-Kor:            &070%d", target->lasers );

            if ( IS_SET( target->mod_flags, MOD_BEAM ) )
                ch_println( ch, "&137Qworlth Skaal:        &070%d", 1 );

            ch_println( ch, "\n&239--&065Systems&239----------------------" );
            ch_println( ch, "&137Organic Hull:         &070%d", target->maxhull );
            ch_println( ch, "&137Biomass Storage:      &070%d", target->maxenergy );
            ch_println( ch, "&137Dovin Basals:         &070%d", target->shield_boosters );
            ch_println( ch, "&137  Maximum Speed:      &070%d", target->realspeed );
            ch_println( ch, "&137  Maneuver:           &070%d", target->maneuver );
            ch_println( ch, "&137  Hyperspeed:         &070%d", target->hyperspeed );
            ch_println( ch, "&137  Damage Mitigation:  &070%d%%", target->chaff );
        }
        else
        {
            ch_println( ch, "&137[&065Class: &070Unknown&137] : &070%s", target->name );

            if ( !NULLSTR( target->description ) )
                ch_println( ch, "&065%s", target->description );
            else if ( target->template && !NULLSTR( target->template->description ) )
                ch_println( ch, "&065%s", target->template->description );
        }

        return;
    }

    ch_printf( ch, "&z[&CClass: %s%s&z] : &C%s&z\n&B", xIS_SET( target->flags, SHIP_MODIFIED ) ? "Modified " : "",
               class_types[target->classtype], target->name );

    if ( !NULLSTR( target->description ) )
        ch_println( ch, "&z%s", target->description );
    else if ( target->template && !NULLSTR( target->template->description ) )
        ch_println( ch, "&z%s", target->template->description );

    if ( xIS_SET( ship->flags, SHIP_PERFECT_TUNE ) )
        ch_println( ch, "&zThis ship looks exceptionally well-built." );

    if ( target->classtype >= CORVETTE_SHIP )
    {
        CLAN_DATA* clan_owner = target->clan;

        if ( clan_owner && !xIS_SET( clan_owner->flags, CLAN_HIDDEN ) )
            ch_println( ch, "&zThis ship bears the markings of %s&z.",
                       !NULLSTR( clan_owner->colorname ) ? clan_owner->colorname : clan_owner->name );
    }

    //For capital ships, display their enemy capital kills as "Kill Markers" in the 5-mark tally system. - Gathorn 2 Sep 2017
    if ( target->classtype >= FRIGATE_SHIP )
    {
        snprintf( buf, MSL, "&zKill Markers: " );

        //
        for ( int kc = 1; kc <= target->killcount; kc++ )
        {
            if ( kc % 5 == 0 && strlen( buf ) + strlen( "&R&s||||" ) > 250 ) //If on the final tally of a 5 man group and can't fit enough for another 5 man group, make a new line. Gathorn 2 Sep 17
            {
                ch_printf( ch, buf );
                snprintf( buf, MSL, "\n&w             " );
            }

            if ( ( kc - ( kc % 5 ) + 5 ) <= target->killcount || ( kc - ( kc % 5 ) ) == target->killcount ) //If the loop counter is in the |||| phase, and can make it to the 5th tally, use the strikethrough token. Otherwise, you'll never hit a group of 5 so don't use strikethrough.. Gathorn 2 Sep 17
            {
                if ( kc % 5 == 0 )
                {
                    strlcat( buf, "&w ", MSL );
                }
                else
                {
                    strlcat( buf, "&R&s|", MSL );
                }
            }
            else
            {
                if ( kc % 5 == 0 )
                {
                    continue;
                }
                else if ( kc % 5 == 1 )
                {
                    strlcat( buf, "&w &R|", MSL );
                }
                else
                {
                    strlcat( buf, "&R|", MSL );
                }
            }
        }

        ch_println( ch, "%s", buf );
    }

    if ( !NULLSTR( target->homeship ) )
        ch_println( ch, "&zHomeship: [&C%s&z]", target->homeship[0] == '\0' ? "&RIndependent" : target->homeship );

    snprintf( buf, MSL, "%-1.2f&z/&C%-1.2f&z", ( target->maxquota - get_used_quota( target ) ) / 100.0, target->maxquota / 100.0 );
    ch_println( ch, "&zQuota: &C%-21s &zValue: &C%ld &zcredit(s)", buf, get_ship_value( target ) );
    bool show_personnel = ( !str_cmp( target->shipowner, ch->name ) || check_clanpilot( ch, target ) || IS_IMMORTAL( ch ) );
    ch_println( ch, "&zOwner: [%s%-13s&z] &zPilot: [%s%-14s&z]  &zCopilot: [%s%-14s&z]",
               show_personnel ? "&C" : "&W",
               show_personnel ? target->shipowner : " ----------- ",
               show_personnel || !str_cmp( target->pilot, ch->name ) ? "&C" : "&W",
               show_personnel || !str_cmp( target->pilot, ch->name ) ? target->pilot : " ------------ ",
               show_personnel || !str_cmp( target->copilot, ch->name ) ? "&C" : "&W",
               show_personnel || !str_cmp( target->copilot, ch->name ) ? target->copilot : " ------------ "
             );

    if ( show_personnel )
        ch_println( ch, "&zCrew:  [&W%s &z]", target->crew );

    if ( target->first_escape )
        for ( ESCAPE_DATA* tmp = target->first_escape; tmp; tmp = tmp->next )
            pods += tmp->max_pods;

    ch_println( ch, "&z--&CWeapons&z----------------------------------------------------------------" );
    ch_println( ch, "&zAutoblasters:    &C%-5d &zLaser cannons:    &C%-5d  &zTurbolasers:       &C%-5d", target->blasters,
               target->lasers, target->turbolasers );
    ch_println( ch, "&zIon cannons:     &C%-5d &zMaximum Missiles: &C%-5d  &zMaximum Torpedoes: &C%-5d", target->ion,
               target->maxmissiles, target->maxtorpedoes );
    ch_println( ch, "&zMaximum Rockets: &C%-5d &zMaximum Pulses:   &C%-5d  &zMaximum Chaff:     &C%-5d",
               target->maxrockets, target->maxpulses, target->maxchaff );
    ch_println( ch, "&zMissile Tubes:   &C%-5d &zTractorbeams:     &C%-5d  &zEscape Pods:       &C%-5d",
               target->missiletubes, target->tractorbeam, pods );

    if ( IS_SET( ship->mod_flags, MOD_BURSTFIRE ) )
        ch_println( ch, "&zBurst: &CReady" );

    if ( IS_SET( ship->mod_flags, MOD_BARRAGE ) )
        ch_println( ch, "&zBarrage: &CReady" );

    if ( !str_cmp( target->shipowner, ch->name ) || check_clanpilot( ch, target ) || IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&z--&CAccess Codes&z-----------------------------------------------------------" );
        ch_println( ch, "&zHatchway: &C%-5d        &zHangar Bays:  &C%-5d      &zDocking: &C%-5d",
                   target->code[SCODE_HATCH], target->code[SCODE_HANGAR], target->code[SCODE_DOCK] );
        ch_println( ch, "&z--------: &C%-5d        &zSelfdestruct: &C%-5d      &z-------: &C%-5d",
                   target->code[SCODE_R1], target->code[SCODE_SELFD], target->code[SCODE_R2] );
    }

    ch_println( ch, "&z--&CSystems&z----------------------------------------------------------------" );
    ch_println( ch, "&zMax Hull:      &C%-7d &zMax Shields:     &C%-7d &zMax Energy(fuel): &C%-5d", target->maxhull,
               target->maxshield, target->maxenergy );
    ch_println( ch, "&zMaximum Speed: &C%-7d &zHyperspeed:      &C%-7d &zManeuver:         &C%-5d", target->realspeed,
               target->hyperspeed, target->maneuver );
    ch_println( ch, "&zSensor Array:  &C%-7d &zShield Boosters: &C%-7d &zCommunications:   &C%-5d", target->sensor,
               target->shield_boosters, target->comm );
    ch_println( ch, "&zCloaking Device: %s", target->cloakstatus != CLOAK_NONE ? "&CInstalled" : "&zNot Installed" );
    act( AT_PLAIN, "$n checks various gauges and displays on the control panel.", ch, NULL, argument, TO_ROOM );
    return;
}

CMDF do_autorecharge( CHAR_DATA* ch, char* argument )
{
    int chance = 0;
    SHIP_DATA* ship = NULL;
    cache_skill( "ship systems", &skill_ship_systems );

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( vehicle_autorecharge( ch, argument ) )
        return;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_coseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the co-pilots seat!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, skill_ship_systems ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, skill_ship_systems );
        return;
    }

    act( AT_PLAIN, "$n flips a switch on the control panel.", ch, NULL, argument, TO_ROOM );

    if ( !str_cmp( argument, "on" ) )
    {
        ship->autorecharge = TRUE;
        ch_println( ch, "&GYou power up the shields." );
        echo_to_ship_windows( AT_YELLOW, ship, "Shields ON. Autorecharge ON." );
    }
    else if ( !str_cmp( argument, "off" ) )
    {
        ship->autorecharge = FALSE;
        ch_println( ch, "&GYou shutdown the shields." );
        echo_to_ship_windows( AT_YELLOW, ship, "Shields OFF. Shield strength set to 0. Autorecharge OFF." );
        ship->shield = 0;
    }
    else if ( !str_cmp( argument, "idle" ) )
    {
        ship->autorecharge = FALSE;
        ch_println( ch, "&GYou let the shields idle." );
        echo_to_ship_windows( AT_YELLOW, ship, "Autorecharge OFF. Shields IDLING." );
    }
    else
    {
        if ( ship->autorecharge == TRUE )
        {
            ship->autorecharge = FALSE;
            ch_println( ch, "&GYou toggle the shields." );
            echo_to_ship_windows( AT_YELLOW, ship, "Autorecharge OFF. Shields IDLING." );
        }
        else
        {
            ship->autorecharge = TRUE;
            ch_println( ch, "&GYou toggle the shields." );
            echo_to_ship_windows( AT_YELLOW, ship, "Shields ON. Autorecharge ON" );
        }
    }

    /*
        if (ship->autorecharge)
        {
        recharge  = URANGE( 1, ship->maxshield-ship->shield, 25+ship->class*25 );
        recharge  = UMIN( recharge, ship->energy*5 + 100 );
        ship->shield += recharge;
        ship->energy -= ( recharge*2 + recharge * ship->class );
        }
    */

    learn_from_success( ch, skill_ship_systems );
    save_ship( ship, true );
}

CMDF do_autopilot( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the pilots seat!" );
        return;
    }

    if ( !str_cmp( argument, "on" ) && ship->autopilot )
    {
        ch_println( ch, "&YAutopilot is already on." );
        return;
    }

    if ( !str_cmp( argument, "off" ) && !ship->autopilot )
    {
        ch_println( ch, "&YAutopilot is already off." );
        return;
    }

    if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
    {
        ch_println( ch, "&RDamn, you don't know the control codes!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RNot while cloaked!" );
        return;
    }

    if ( ch->fighting && number_percent(  ) > 25 )
    {
        ch_println( ch, "You reach for the controls, but narrowly avoid getting hit!" );
        return;
    }

    ch_println( ch, "&YYou enter the control codes for the autopilot." );
    act( AT_PLAIN, "$n enters the control codes for the autopilot.", ch, NULL, argument, TO_ROOM );

    if ( ship->autopilot == TRUE )
    {
        ship->autopilot = FALSE;
        ch_println( ch, "&GYou toggle the autopilot." );
        echo_to_ship_windows( AT_YELLOW, ship, "Autopilot OFF." );
    }
    else
    {
        ship->autopilot = TRUE;
        if ( xIS_SET( ship->aflags, AFLAG_AUTOSHIELD ) )
            ship->autorecharge = TRUE;
        ch_println( ch, "&GYou toggle the autopilot." );
        echo_to_ship_windows( AT_YELLOW, ship, "Autopilot ON." );
    }

    // If disabling autopilot for the first time after autolaunch, reset the autopilot configuration back to its pre-launch state
    if ( ship->autolaunch_used )
    {
        xCLEAR_BITS( ship->aflags );
        xSET_BITS( ship->aflags, ship->prev_aflags );
        xCLEAR_BITS( ship->prev_aflags );
        ship->autolaunch_used = FALSE;
    }

    save_ship( ship, true );
    return;
}

CMDF do_openhatch( CHAR_DATA* ch, char* argument )
{
    VEHICLE_DATA* vec = NULL;
    SHIP_DATA* ship = NULL;
    char buf[MSL];
    char arg1[MSL];
    char arg2[MSL];
    int code = 0;
    bool sf = TRUE, hatch;

    if ( IS_NPC( ch ) && !xIS_SET( ch->act, ACT_CANOPENSHIPS ) )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( !argument || argument[0] == '\0' || !str_cmp( argument, "hatch" ) )
    {
        ship = ship_from_entrance( ch->in_room );

        if ( ship == NULL )
        {
            if ( ( vec = vehicle_from_entrance( ch->in_room->vnum ) ) == NULL )
            {
                ch_println( ch, "&ROpen what?" );
                return;
            }

            sf = FALSE;
        }

        if ( sf == TRUE )
            hatch = ship->hatchopen;

        if ( sf != TRUE )
            hatch = vec->hatchopen;

        if ( !hatch )
        {
            if ( sf )
            {
                if ( ( ship->location != ship->lastdoc ) || ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ship->shipstate != SHIP_HOVER ) )
                {
                    ch_println( ch, "&RPlease wait till the ship lands!" );
                    return;
                }

                if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
                {
                    ch_println( ch, "The hatch is broken, how do you expect to open it?" );
                    return;
                }

                ship->hatchopen = TRUE;
                ship->hatchtimer = 30;

                if ( xIS_SET( ship->flags, SHIP_VONG ) )
                {
                    ch_println( ch, "&GYou place your hand near the hatch membrane and it opens in response." );
                    act( AT_PLAIN, "$n places a hand near the hatch membrane and it opens.", ch, NULL, argument, TO_ROOM );
                    snprintf( buf, MSL, "The hatch membrane on %s quickly unfolds open.", ship->name );
                }
                else
                {
                    ch_println( ch, "&GYou open the hatch." );
                    act( AT_PLAIN, "$n opens the hatch.", ch, NULL, argument, TO_ROOM );
                    snprintf( buf, MSL, "The hatch on %s opens.", ship->name );
                }

                echo_to_room( AT_YELLOW, get_room_index( ship->location ), buf );
                sound_to_room( get_room_index( ship->location ), "door" );
                sound_to_room( get_room_index( ship->entrance ), "door" );
                return;
            }
            else
            {
                if ( vec->state != VEHICLE_OFF && vec->state != VEHICLE_DISABLED )
                {
                    if ( vec->type == CLOUD_CAR )
                    {
                        ch_println( ch, "&RNot while flying! Use LAND to land the vehicle first." );
                    }
                    else
                    {
                        ch_println( ch, "&RTurn the vehicle off first! Use 'DRIVE OFF' to shut it off." );
                    }

                    return;
                }

                vec->hatchopen = TRUE;
                ch_println( ch, "&GYou open the hatch." );
                act( AT_PLAIN, "$n opens the hatch.", ch, NULL, argument, TO_ROOM );
                snprintf( buf, MSL, "The hatch on %s opens.", vec->name );
                echo_to_room( AT_YELLOW, get_room_index( vec->location ), buf );
                sound_to_room( get_room_index( vec->location ), "door" );
                sound_to_room( get_room_index( vec->entrance ), "door" );
                return;
            }
        }
        else
        {
            ch_println( ch, "&RIt's already open." );
            return;
        }
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    ship = ship_in_room( ch->in_room, arg1 );

    if ( !ship )
    {
        if ( ( vec = vehicle_in_room( ch->in_room, arg1 ) ) == NULL )
        {
            act( AT_PLAIN, "I see no $T here.", ch, NULL, arg1, TO_CHAR );
            return;
        }

        sf = FALSE;
    }

    if ( sf )
    {
        if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ship->shipstate != SHIP_HOVER )
        {
            ch_println( ch, "&RThat ship is in the middle of a maneuver!" );
            return;
        }

        if ( ship->shipstate == SHIP_HOVER && !IS_AFFECTED( ch, AFF_FLYING ) )
        {
            ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        {
            ch_println( ch, "The hatch is broken, how do you expect to open it?" );
            return;
        }

        if ( !ship->hatchopen )
        {
            if ( !xIS_SET( ship->flags, SHIP_ANYOPEN ) && !check_pilot( ch, ship ) && !is_stolen( ch, ship ) && !is_number( arg2 ) )
            {
                ch_println( ch, "&RThats not a valid access code!" );
                ch_println( ch, "&zSyntax: &COPENHATCH <&wship&C> <&wcode&C>" );
                return;
            }

            code = atoi( arg2 );

            if ( !xIS_SET( ship->flags, SHIP_ANYOPEN ) && code != ship->code[SCODE_HATCH] && !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
            {
                if ( xIS_SET( ship->flags, SHIP_VONG ) )
                {
                    act( AT_PLAIN, "You place your hand near the hatch membrane on $T, but nothing happens.", ch, NULL, ship->name, TO_CHAR );
                    act( AT_PLAIN, "$n places a hand near the hatch membrane on $T, but nothing happens.", ch, NULL, ship->name, TO_ROOM );
                }
                else
                {
                    act( AT_PLAIN, "You fail to open the hatch on $T.", ch, NULL, ship->name, TO_CHAR );
                    act( AT_PLAIN, "$n fails to open the hatch on $T.", ch, NULL, ship->name, TO_ROOM );
                    echo_to_room( AT_WHITE, get_room_index( ship->entrance ),
                                  "The hatch displays flickers as someone attempts to open it." );
                    echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The displays reads, 'Invalid access attempt'" );
                    echo_to_room( AT_YELLOW, ch->in_room, "The hatch display flicks on: 'Invalid access attempt'" );
                }

                return;
            }

            ship->hatchopen = TRUE;
            ship->hatchtimer = 30;  /* Autoclose hatch in 30 seconds */

            if ( xIS_SET( ship->flags, SHIP_VONG ) )
            {
                act( AT_PLAIN, "You place your hand near the hatch membrane on $T and it snaps open in response.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "$n place a hand near the hatch membrane on $T and it snaps open in response.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch membrane suddenly snaps open." );
            }
            else
            {
                act( AT_PLAIN, "You open the hatch on $T.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "$n opens the hatch on $T.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch opens from the outside." );
            }

            sound_to_room( get_room_index( ship->entrance ), "door" );
            sound_to_room( get_room_index( ship->location ), "door" );
            return;
        }
    }
    else
    {
        if ( vec->state != VEHICLE_OFF && vec->state != VEHICLE_DISABLED )
        {
            ch_println( ch, "&RThe vehicle is already running! Wait for it to stop." );
            return;
        }

        if ( !vec->hatchopen )
        {
            if ( !is_number( arg2 ) && !IS_IMMORTAL( ch ) && !is_rental_car( vec ) )
            {
                ch_println( ch, "&RThats not a valid access code!" );
                ch_println( ch, "&zSyntax: &COPENHATCH <&wvehicle&C> <&wcode&C>" );
                return;
            }

            code = atoi( arg2 );

            if ( code != vec->hatchcode && !IS_IMMORTAL( ch ) && !is_rental_car( vec ) )
            {
                act( AT_PLAIN, "You fail to open the hatch on $T.", ch, NULL, vec->name, TO_CHAR );
                act( AT_PLAIN, "$n fails to open the hatch on $T.", ch, NULL, vec->name, TO_ROOM );
                echo_to_room( AT_WHITE, get_room_index( vec->entrance ),
                              "The hatch displays flickers as someone attempts to open it." );
                echo_to_room( AT_YELLOW, get_room_index( vec->entrance ), "The displays reads, 'Invalid access attempt'" );
                echo_to_room( AT_YELLOW, ch->in_room, "The hatch display flicks on: 'Invalid access attempt'" );
                return;
            }

            vec->hatchopen = TRUE;
            act( AT_PLAIN, "You open the hatch on $T.", ch, NULL, vec->name, TO_CHAR );
            act( AT_PLAIN, "$n opens the hatch on $T.", ch, NULL, vec->name, TO_ROOM );
            echo_to_room( AT_YELLOW, get_room_index( vec->entrance ), "The hatch opens from the outside." );
            sound_to_room( get_room_index( vec->entrance ), "door" );
            sound_to_room( get_room_index( vec->location ), "door" );
            return;
        }
    }

    ch_println( ch, "&GIt's already open!" );
    return;
}


