        if ( ship->shipstate == SHIP_HOVER && !IS_AFFECTED( ch, AFF_FLYING ) )
        {
            ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            if ( xIS_SET( ship->flags, SHIP_VONG ) )
                ch_println( ch, "The hatch membrane appears to be injured and can't form a seal." );
            else
                ch_println( ch, "The hatch is broken, how do you expect to close it?" );

            return;
        }

        if ( ship->shipstate == SHIP_LAUNCH )
        {
            ch_println( ch, "&RThat ship is in the middle of a maneuver!" );
            return;
        }

        if ( ship->hatchopen )
        {
            ship->hatchopen = FALSE;
            ship->hatchtimer = 0;

            if ( xIS_SET( ship->flags, SHIP_VONG ) )
            {
                act( AT_PLAIN, "You place your hand near the hatch membrane on $T and it snaps shut in response.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "$n places a hand near the hatch membrane on $T and it snaps shut.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch membrane suddenly snaps shut." );
            }
            else
            {
                act( AT_PLAIN, "You close the hatch on $T.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "$n closes the hatch on $T.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch is closed from outside." );
            }

            sound_to_room( get_room_index( ship->entrance ), "door" );
            sound_to_room( get_room_index( ship->location ), "door" );
            return;
        }
        else
        {
            ch_println( ch, "&RIt's already closed." );
            return;
        }
    }
    else
    {
        if ( vec->state != VEHICLE_OFF && vec->state != VEHICLE_DISABLED )
        {
            ch_println( ch, "&RThat vehicle has already been set in motion!" );
            return;
        }
        else
        {
            if ( vec->hatchopen )
            {
                vec->hatchopen = FALSE;
