                sound_to_room( get_room_index( vec->location ), "door" );
                return;
            }
            else
            {
                ch_println( ch, "&RIt's already closed." );
                return;
            }
        }
    }
}

/*
    Allows pilots to scan other ships,
    Like a 'consider' for ships.
*/
CMDF do_scompare( CHAR_DATA* ch, char* argument )
{
    int chance = 0;
    int ranka = 0, rankb = 0, rat = 0;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* target = NULL;
    cache_skill( "ship systems", &skill_ship_systems );

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit, turret or engine room of a ship to do that!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&RSpecify a target to scan, moron!" );
        return;
    }
    else
        target = get_ship_here( argument, ship->starsystem );

    if ( target == NULL )
    {
        ch_println( ch, "&RI don't see that here.\nTry the radar first, and make sure you got the right one." );
        return;
    }

    if ( vector_distance( &target->vpos, &ship->vpos ) > 1000 + ship->sensor * 2 )
        //  if ( abs( ( int )target->vx - ( int )ship->vx ) > 1000 + ship->sensor * 2 ||
        //        abs( ( int )target->vy - ( int )ship->vy ) > 1000 + ship->sensor * 2 ||
        //      abs( ( int )target->vz - ( int )ship->vz ) > 1000 + ship->sensor * 2 )
    {
        ch_println( ch, "&RThat ship is too far away to scan." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, skill_ship_systems ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't figure out how to scan the target!" );
        learn_from_failure( ch, skill_ship_systems );
        return;
    }

    act( AT_PLAIN, "$n carefully examines various displays on the control panel.", ch, NULL, argument, TO_ROOM );
    ranka += ( target->classtype * 25 ) + 25;
    ranka += ( target->missiletubes );
    ranka += ( target->missiles );
    ranka += ( target->rockets );
    ranka += ( target->torpedoes );
    ranka += ( target->pulses );
    ranka += ( target->lasers / 2 );
    ranka += ( target->blasters / 4 );
    ranka += ( target->turbolasers );
    ranka += ( target->ion );
    ranka += ( target->maxenergy / 1000 );
    ranka += ( target->shield / 500 );
    ranka += ( target->hull / 1000 );
    rankb += ( ship->classtype * 25 ) + 25;
    rankb += ( ship->missiletubes );
    rankb += ( ship->missiles );
    rankb += ( ship->rockets );
    rankb += ( ship->torpedoes );
    rankb += ( ship->pulses );
    rankb += ( ship->lasers / 2 );
    rankb += ( ship->blasters / 4 );
    rankb += ( ship->turbolasers );
    rankb += ( ship->ion );
    rankb += ( ship->maxenergy / 1000 );
    rankb += ( ship->shield / 500 );
    rankb += ( ship->hull / 1000 );

    if ( ranka > rankb )
        rat = ranka / rankb;

    if ( rankb > ranka )
        rat = rankb / ranka;

    rat = rat * 2;

    if ( ranka == rankb )
        ch_println( ch, "&RYou could take him, with a little luck." );

    if ( ranka > rankb )
        ch_println( ch, "&R%s is almost %d times your strength!", target->name, rat );

    if ( rankb > ranka )
        ch_println( ch, "&RYour almost %d times as strong as the %s", rat, target->name );

    learn_from_success( ch, skill_ship_systems );
}

CMDF do_status( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], bufA[MSL], bufB[MSL], bufC[MSL];
    int chance = 0, cnt = 0;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* target = NULL;
    CARGO_DATA* cargo = NULL;
    TURRET_DATA* turret = NULL;
    HANGAR_DATA* hangar = NULL;
    double pa = 0, pb = 0, pc = 0;
    bool othership = FALSE;
    ROOM_INDEX_DATA* room = NULL;
    cache_skill( "ship systems", &skill_ship_systems );

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( vehicle_status( ch, argument ) )
        return;

    ship = get_ship_from_room( ch->in_room );

    if ( NULLSTR( argument ) )
    {
        if ( !ship )
        {
            ch_println( ch, "&RYou must be on a ship to scan other ships!" );
            return;
        }

        if ( ship != get_ship_from_cockpit( ch->in_room ) )
        {
            if ( ship != get_ship_from_engine( ch->in_room ) )
            {
                ch_println( ch, "&RYou must be in the cockpit, turret or engineroom of a ship to do that!" );
                return;
            }
        }

        target = ship;
    }
    else
    {
        if ( !ship )
        {
            ch_println( ch, "&RYou must be on a ship to scan other ships!" );
            return;
        }

        if ( !ship->starsystem )
        {
            ch_println( ch, "&RI don't see that here!" );
            return;
        }

        if ( !str_cmp( argument, "target" ) && ship->target0 != NULL )
            target = ship->target0;
        else
            target = get_ship_here( argument, ship->starsystem );
    }

    if ( ship->cloakstatus == CLOAK_ON && ship != target )
    {
        ch_println( ch, "&RYour sensors are no good with the cloaking generator on!&w" );
        return;
    }

    if ( target == NULL || ( target->cloakstatus == CLOAK_ON && ship != target ) )
    {
        ch_println( ch, "&RI don't see that here.\nTry the radar, or type status by itself for your ships status." );
        return;
    }

    if ( ship != target )
        othership = TRUE;

    if ( vector_distance( &target->vpos, &ship->vpos ) > 500 + ship->sensor * 10 )
    {
        ch_println( ch, "&RThat target is too far away to scan." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, skill_ship_systems ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't figure out what the readout means." );
        learn_from_failure( ch, skill_ship_systems );
        return;
    }

    act( AT_PLAIN, "$n checks various gauges and displays on the control panel.", ch, NULL, argument, TO_ROOM );

    if ( xIS_SET( target->flags, SHIP_VONG ) )
    {
        ch_println( ch, "&239Readout for &065%s&239:", target->name );
        ch_println( ch, "&239---------------------------------------------------------" );
        if ( target->starsystem )
        {
            ch_println( ch, "&137Current Coordinates:  &070%.0f %.0f %.0f", target->vpos.x, target->vpos.y, target->vpos.z );
            ch_println( ch, "&137Current Heading:      &070%.0f %.0f %.0f", target->head.x, target->head.y, target->head.z );
        }

        if ( xIS_SET( ship->flags, SHIP_VONGSCAN ) || xIS_SET( ship->flags, SHIP_VONG ) )
        {
            if ( target->starsystem )
                ch_println( ch, "&137Current Speed:        &070%d&239/&070%d", target->currspeed, target->realspeed );

            if ( othership )
            {
                if ( ( int )ship->sensor >= 50 )
                    ch_println( ch, "&137Lifeforms detected:   &070%d", ship_crew_count( target, NULL ) );
                else
                    ch_println( ch, "&137Lifeforms detected:   &RNeed &W50 &Rsensors to scan for lifeforms." );
            }
            else
                ch_println( ch, "&zYou cannot scan your own ship for lifeforms." );

            ch_println( ch, "&239--&065Systems&239------------------------------------------------" );

            if ( target->maxhull > 0 )
                pa = ( ( ( double )( target->hull ) / ( double )( target->maxhull ) ) * 100 );

            if ( target->maxenergy > 0 )
                pc = ( ( ( double )( target->energy ) / ( double )( target->maxenergy ) ) * 100 );

            snprintf( bufA, MSL, "&137Hull:             &070%d&239/&070%d &239[&070%d%%&239]", target->hull, target->maxhull, ( int )pa );
            ch_println( ch, "&239%-39s  &137Ship Condition: %s", bufA, ( target->shipstate == SHIP_PERM_DISABLED && !othership ) ? "&RPermanently Disabled" : ( target->shipstate == SHIP_PERM_DISABLED || target->shipstate == SHIP_DISABLED ) ? "&RDisabled" : "&070Running" );
            ch_println( ch, "&137Biomass Storage:  &070%d&239/&070%d &239[&070%d%%&239]", target->energy, target->maxenergy, ( int )pc );
            ch_println( ch, "&137Full Yammosk Control: %-11s", autofly( target ) ? "&RYES" : "&239No" );

            if ( target->autolaunch_armed )
            {
                ch_println( ch, "&137Autolaunch Status: &R+--==ARMED==--+" );
                ch_println( ch, "&137 -=> Time Remaining: &070%d second(s)&239", target->autolaunch_time );
            }
            else
                ch_println( ch, "&137Autolaunch Status: &070Standby" );

            if ( target->selfd_armed )
            {
                ch_println( ch, "&137Selfdestruct Status: &R+--==ARMED==--+" );
                ch_println( ch, "&137 -=> Time Remaining: &070%d second(s)&239", target->selfd_time );
            }
            else
                ch_println( ch, "&137Selfdestruct Status: &070Standby" );

            ch_println( ch, "&239--&065Weapons&239------------------------------------------------" );
            ch_println( ch, "&137Primary Target:       &R%s", target->target0 ? target->target0->name : "none" );

            if ( othership )
            {
                if ( target->lasers > 0 )
                    ch_println( ch, "&137Yaret-Kor Condition:  %s", target->laser_charge <= LASER_DAMAGED ? "&RDamaged" : "&070Intact" );
            }
            else
            {
                if ( target->laser_charge <= LASER_DAMAGED )
                {
                    ch_println( ch, "&137Yaret-Kor Ready:     &R0 (%s)", target->laser_charge == LASER_DESTROYED ? "Destroyed" : "Damaged" );
                }
                else
                {
                    ch_println( ch, "&137Yaret-Kor Ready:     &070%3.0f&239/&070%-3d", UMAX( target->lasers - target->laser_charge, 0 ), target->lasers );
                }
            }
        }
        else
        {
            if ( target->starsystem )
                ch_println( ch, "&137Current Speed:        &070%d", target->currspeed );
            ch_println( ch, "&239--&065Systems&239------------------------------------------------" );
            ch_printf( ch, "&137Structural integrity: " );

            switch ( target->hull * 4 / target->maxhull )
            {
                case 4:
                    ch_println( ch, "&070Undamaged" );
                    break;

                case 3:
                    ch_println( ch, "&wSlightly Damaged" );
                    break;

                case 2:
                    ch_println( ch, "&YDamaged" );
                    break;

                case 1:
                    ch_println( ch, "&YBadly Damaged" );
                    break;

                case 0:
                    ch_println( ch, "&RCritical" );
                    break;
            }
        }

        ch_println( ch, "&239--&065Storage&239------------------------------------------------" );

        if ( target->first_cargo )
        {
            int maxcargo = 0, usedcargo = 0, pods = 0;

            for ( cargo = target->first_cargo; cargo; cargo = cargo->next )
            {
                maxcargo += cargo->size;
                usedcargo += cargo->amount;
                pods++;
            }

            ch_println( ch, "&137Cargo - (Storage: &070%d&239/&070%d&239 | &137Pod(s): &070%d&239)", usedcargo, maxcargo, pods );
        }
        else
            ch_println( ch, "&137(This ship is not equipped with cargo containers)" );

        if ( target->first_hangar )
        {
            for ( hangar = target->first_hangar; hangar; hangar = hangar->next )
            {
                if ( ++cnt == 7 )
                {
                    ch_println( ch, "&239Only the first &C6 &239Hangars are being displayed." );
                    break;
                }

                ch_println( ch, "&137Hangar %d: %-11s  &137Slot(s): &070%d/%d", cnt, hangar->bayopen ? "&YOpen" : "&070Closed",
                           hangar->size - get_hangar_free( hangar ), hangar->size );
            }
        }
        else
            ch_println( ch, "&137(This ship is not equipped with hangars)" );

        return;
    }

    ch_println( ch, "&z&W&Y&zReadout for &C%s&z:", target->name );
    ch_println( ch, "&z---------------------------------------------------------" );

    if ( ship->cloakstatus == CLOAK_ON ) //Idea is cloaking should not give you any way to figure out your current coords or coords of other ships. - Gathorn 17Jan19
    {
        ch_println( ch, "&zCurrent Coordinates:  &CUndeterminable" );
        ch_println( ch, "&zCurrent Heading:      &CUndeterminable" ) ;
    }
    else if ( ship->starsystem )
    {
        ch_println( ch, "&zCurrent Coordinates:  &C%.0f %.0f %.0f", target->vpos.x, target->vpos.y, target->vpos.z );
        ch_println( ch, "&zCurrent Heading:      &C%.0f %.0f %.0f", target->head.x, target->head.y, target->head.z );
    }

    if ( ship->starsystem )
    {
        if ( xIS_SET( target->flags, SHIP_OBJECT ) )
            ch_println( ch, "&zCurrent Speed:        &C%d", target->currspeed );
        else
            ch_println( ch, "&zCurrent Speed:        &C%d&z/&C%d", target->currspeed, target->realspeed );
    }

    /*
        Life form scanning. Handy. Cannon (See EP 4)       Orion
    */
    if ( othership )
    {
        if ( ( int )ship->sensor >= 50 )
        {
            ch_println( ch, "&zLifeforms detected:   &C%d", ship_crew_count( target, NULL ) );

            if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
                for ( room = target->first_room; room; room = room->next_in_range )
                    if ( room->first_person != NULL )
                        ch_println( ch, "&zLifeform race:   &C%s", get_apparent_race( room->first_person ) );
        }
        else
            ch_println( ch, "&zLifeforms detected:   &RNeed &W50 &Rsensors to scan for lifeforms." );
    }
    else
        ch_println( ch, "&zYou cannot scan your own ship for lifeforms." );

    if ( xIS_SET( target->flags, SHIP_OBJECT ) )
    {
        ch_printf( ch, "&zStructural integrity: " );

        switch ( target->hull * 4 / target->maxhull )
        {
            case 4:
                ch_println( ch, "&CUndamaged" );
                break;

            case 3:
                ch_println( ch, "&CSlightly Damaged" );
                break;

            case 2:
                ch_println( ch, "&YDamaged" );
                break;

            case 1:
                ch_println( ch, "&YBadly Damaged" );
                break;

            case 0:
                ch_println( ch, "&RCritical" );
                break;
        }

        if ( target->selfd_armed )
        {
            if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
            {
                ch_println( ch, "&zRemaining %s: &C%d second(s)&z", xIS_SET( target->flags, SHIP_SPACE_CORPSE ) ? "Time" : "Life Support", target->selfd_time );
            }
            else
            {
                ch_println( ch, "&zSelfdestruct Status: &R+--==ARMED==--+" );
                ch_println( ch, "&z -=> Time Remaining: &C%d second(s)&z", target->selfd_time );
            }
        }

        if ( target->first_hangar )
        {
            for ( hangar = target->first_hangar; hangar; hangar = hangar->next )
            {
                if ( ++cnt == 7 )
                {
                    ch_println( ch, "&zOnly the first &C6 &zHangars are being displayed." );
                    break;
                }

                ch_println( ch, "&zHangar %d: %-11s  &zSlot(s): &C%d/%d%s", cnt, hangar->bayopen ? "&ROpen" : "&CClosed",
                           hangar->size - get_hangar_free( hangar ), hangar->size, ( hangar->size == 0 && xIS_SET( target->flags, SHIP_RESCUESHIP ) ) ? " (EV ONLY)" : "" );
            }
        }
    }
    else
    {
        int podA = 0, podB = 0;

        if ( target->first_escape )
        {
            ESCAPE_DATA* tmp;

            for ( tmp = target->first_escape; tmp; tmp = tmp->next )
            {
                podA += tmp->pods;
                podB += tmp->max_pods;
            }
        }

        ch_println( ch, "&z--&CSystems&z------------------------------------------------" );

        if ( target->maxhull > 0 )
            pa = ( ( ( double )( target->hull ) / ( double )( target->maxhull ) ) * 100 );

        if ( target->maxshield > 0 )
            pb = ( ( ( double )( target->shield ) / ( double )( target->maxshield ) ) * 100 );

        if ( target->maxenergy > 0 )
            pc = ( ( ( double )( target->energy ) / ( double )( target->maxenergy ) ) * 100 );

        snprintf( bufA, MSL, "Hull: &C%d&z/&C%d &z[&C%d%%&z]", target->hull, target->maxhull, ( int )pa );
        snprintf( bufB, MSL, "Shields: &C%d&z/&C%d &z[&C%d%%&z]", target->shield, target->maxshield, ( int )pb );
        ch_println( ch, "&z%-39s  Ship Condition: %s", bufA,
                   ( target->shipstate == SHIP_PERM_DISABLED && !othership ) ? "&RPermanently Disabled" : ( target->shipstate == SHIP_DISABLED || target->shipstate == SHIP_PERM_DISABLED ) ? "&RDisabled" : "&CRunning" );
        ch_println( ch, "&z%-39s  Energy(fuel): &C%d&z/&C%d &z[&C%d%%&z]", bufB, target->energy, target->maxenergy,
                   ( int )pc );

        ch_println( ch, "&zAutopilot Status: %-11s", autofly( target ) ? "&RACTIVE" : "&COffline" );

        if ( !othership )
        {
            ch_printf( ch, "&zCloaking Device: " );

            /*
                Safty Check for CLOAKING MODULE
            */
            if ( target->cloakstatus != CLOAK_DESTROYED && target->cloakstatus != CLOAK_DAMAGED && target->cloakstatus != CLOAK_NONE && target->cloakstatus != CLOAK_READY
                    && target->cloakstatus != CLOAK_ON )
                target->cloakstatus = CLOAK_NONE;

            switch ( target->cloakstatus )
            {
                default:
                    ch_println( ch, "&RUnknown&z" );
                    break;

                case CLOAK_DESTROYED:
                    ch_println( ch, "&RDestroyed&z" );
                    break;

                case CLOAK_DAMAGED:
                    ch_println( ch, "&RDamaged&z" );
                    break;

                case CLOAK_NONE:
                    ch_println( ch, "&CNot Installed&z" );
                    break;

                case CLOAK_READY:
                    ch_println( ch, "&CReady&z" );
                    break;

                case CLOAK_ON:
                    ch_println( ch, "&CActive&z" );
                    break;
            }
        }

        // a little bit indeterminate.  Adds an aspect of protection for the unsecured ships (you have to be about 7%
        // for it to switch to "active") but also a clear indicator of value / quality for higher end ships
        // Miros
        get_rating_string( bufC, target->security_rating );
        ch_println( ch, "&zSecurity Program: &C%s", ( xIS_SET( target->flags, SHIP_SECURED ) ? bufC : "Not Installed" ) );
        ch_println( ch, "&zComm System: &C%s&z", ( !othership && xIS_SET( target->flags, SHIP_COMM_DESTROYED ) ) ? "&RDestroyed" : ( ( xIS_SET( target->flags, SHIP_COMM_DISABLED ) || xIS_SET( target->flags, SHIP_COMM_DESTROYED ) ) ? "&RDisabled" : ( xIS_SET( target->flags, SHIP_JAMMED ) ? "&YJammed" : "Online" ) ) );

        if ( target->autolaunch_armed )
        {
            ch_println( ch, "&zAutolaunch Status: &R+--==ARMED==--+" );
            ch_println( ch, "&z -=> Time Remaining: &C%d second(s)&z", target->autolaunch_time );
        }
        else
            ch_println( ch, "&zAutolaunch Status: &CStandby" );

        if ( target->selfd_armed )
        {
            ch_println( ch, "&zSelfdestruct Status: &R+--==ARMED==--+" );
            ch_println( ch, "&z -=> Time Remaining: &C%d second(s)&z", target->selfd_time );
        }
        else
            ch_println( ch, "&zSelfdestruct Status: &CStandby" );
        if (check_pilot( ch, target ))
            ch_println( ch, "&zAutorecharge Status: %-11s", target->autorecharge ? "&CActive" : "&ROFFLINE" );

        if ( target->tractorbeam > 0 )
        {
            if ( othership )
                ch_println( ch, "&zTractor Beam Condition: %s", target->tractorstate >= TRACTOR_DAMAGED ? "&RDamaged" : "&CGood" );
            else
                ch_println( ch, "&zTractor Beam Condition: %s", target->tractorstate == TRACTOR_DESTROYED ? "&RDestroyed" : target->tractorstate == TRACTOR_DAMAGED ? "&RDamaged" : "&CGood" );
        }

        if ( target->maxchaff > 0 )
        {
            snprintf( buf, MSL, "%s", target->chaff <= 0 ? "&R" : target->chaff_time > 0 ? "&W" : "&G" );
            if ( target->chaff_time > 0 )
                snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%d seconds", target->chaff_time );
            else
                snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%s", target->chaff > 0 ? "Ready" : "Depleted" );
            ch_println( ch, "&zChaff Remaining:    %s&C%d&z/&C%d%s     &zChaff Status: %s",
            target->chaff > 9 ? "" : " ", target->chaff, target->maxchaff, target->maxchaff > 9 ? "" : " ", buf );
        }
        ch_println( ch, "&z--&CWeapons&z------------------------------------------------" );
        ch_println( ch, "&zPrimary Target:     &R%s", target->target0 ? target->target0->name : "none" );

        if ( othership )
        {
            if ( target->lasers > 0 || target->blasters > 0 || target->turbolasers > 0 )
                ch_println( ch, "&zLaser Condition:    %s",
                           target->laser_charge <= LASER_DAMAGED ? "&RDamaged" : "&CGood" );

            if ( target->ion > 0 )
                ch_println( ch, "&zIon Condition:      %s",
                           target->ion_charge <= ION_DAMAGED ? "&RDamaged" : "&CGood" );
        }
        else
        {
            if ( target->laser_charge <= LASER_DAMAGED )
            {
                ch_println( ch, "&zBlasters Ready:     &R%s   &zLasers Ready:       &R%s", target->laser_charge == LASER_DESTROYED ? "Destroyed" : "Damaged", target->laser_charge == LASER_DESTROYED ? "Destroyed" : "Damaged"  );
                ch_printf( ch, "&zTurbolasers Ready:  &R%s   ", target->laser_charge == LASER_DESTROYED ? "Destroyed" : "Damaged" );
            }
            else
            {
                ch_println( ch, "&zBlasters Ready:    &C%3.0f&z/&C%-3d    &zLasers Ready:      &C%3.0f&z/&C%-3d",
                           UMAX( target->blasters - target->autoblaster_charge, 0 ), target->blasters,
                           UMAX( target->lasers - target->laser_charge, 0 ), target->lasers );
                ch_printf( ch, "&zTurbolasers Ready: &C%3.0f&z/&C%-3d    ",
                           UMAX( target->turbolasers - target->turbolaser_charge, 0 ), target->turbolasers );
            }

            if ( target->ion_charge <= ION_DAMAGED )
            {
                ch_println( ch, "&zIon Cannons Ready:  &R%s", target->ion_charge == ION_DESTROYED ? "Destroyed" : "Damaged" );
            }
            else
            {
                ch_println( ch, "&zIon Cannons Ready: &C%3.0f&z/&C%-3d",
                           UMAX( target->ion - target->ion_charge, 0 ), target->ion );
            }
        }

        if ( target->missiletubes > 0 )
        {
            if ( othership )
            {
                ch_println( ch, "&zLauncher Condition: %-10s",
                           target->missilestate >= MISSILE_DAMAGED ? "&RDamaged" : "&CGood" );
            }
            else
            {
                ch_println( ch, "&zLauncher Condition: %-10s  &zTubes Ready:       &C%3d&z/&C%-3d",
                           target->missilestate == MISSILE_DESTROYED ? "&RDestroyed" : target->missilestate == MISSILE_DAMAGED ? "&RDamaged" : "&CGood",
                           target->missiletubes - target->spent_tubes, target->missiletubes );
            }

            ch_println( ch,
                       "&zMissiles: &C%d&z/&C%d  &zTorpedoes: &C%d&z/&C%d  &zRockets: &C%d&z/&C%d  &zPulses: &C%d&z/&C%d&z",
                       target->missiles, target->maxmissiles, target->torpedoes, target->maxtorpedoes, target->rockets,
                       target->maxrockets, target->pulses, target->maxpulses );
        }

        if ( target->first_turret )
        {
            int count;
            LINK_LENGTH( target->first_turret, TURRET_DATA, next, count );
            snprintf( bufA, MSL, "&zTotal Turrets: &C%d&z. Damaged Turrets: [ &R", count );
            int ctr = 0;

            for ( turret = target->first_turret; turret; turret = turret->next )
            {
                ctr++;

                if ( turret->laserstate <= LASER_DAMAGED )
                {
                    ++cnt;
                    snprintf( bufB, MSL, "%d", ctr );
                    strlcat( bufA, bufB, MSL );
                    strlcat( bufA, " ", MSL );
                }
            }

            if ( cnt == 0 )
                strlcat( bufA, "(All turrets working) ", MSL );

            strlcat( bufA, "&z]\n", MSL );
            ch_printf( ch, bufA );
        }

        ch_println( ch, "&z--&CStorage&z------------------------------------------------" );
        ch_println( ch, "&z&zEscape Pods:         &C%d&z/&C%d&z", podA, podB );
        if ( target->first_cargo )
        {
            int maxcargo = 0, usedcargo = 0, pods = 0;

            for ( cargo = target->first_cargo; cargo; cargo = cargo->next )
            {
                maxcargo += cargo->size;
                usedcargo += cargo->amount;
                pods++;
            }

            ch_println( ch, "&zCargo - (Storage: &C%d&z/&C%d&z | Pod(s): &C%d&z)", usedcargo, maxcargo, pods );
        }
        else
            ch_println( ch, "&z(This ship is not equipped with cargo containers)" );

        if ( target->maxtroops > 0 )
        {
            ch_println( ch, "&zTroop Hold - (Capacity: &C%d&z/&C%d&z)", target->troops, target->maxtroops );
        }

        if ( target->first_hangar )
        {
            for ( hangar = target->first_hangar; hangar; hangar = hangar->next )
            {
                if ( ++cnt == 7 )
                {
                    ch_println( ch, "&zOnly the first &C6 &zHangars are being displayed." );
                    break;
                }

                ch_println( ch, "&zHangar %d: %-11s  &zSlot(s): &C%d/%d%s", cnt, hangar->bayopen ? "&ROpen" : "&CClosed",
                           hangar->size - get_hangar_free( hangar ), hangar->size, ( hangar->size == 0 && xIS_SET( target->flags, SHIP_RESCUESHIP ) ) ? " (EV ONLY)" : "" );
            }
        }
        else
            ch_println( ch, "&z(This ship is not equipped with hangars)" );
    }

    learn_from_success( ch, skill_ship_systems );
    return;
}

int delete_navchart( NAVCHART_DATA* chart )
{
    if ( !chart )
        return E_LOTJ_MISSING_ARGUMENTS;

    FREE_STRUCT( chart, navchart_fields );
    return E_LOTJ_SUCCESS;
}

CMDF do_navstatus( CHAR_DATA* ch, char* argument )
{
    char bufA[MSL], bufB[MIL], arg[MIL];
    NAVCHART_DATA* chart = NULL, *next_chart = NULL;
    OBJ_DATA* obj = NULL;
    SHIP_DATA* ship = NULL;
    SPACE_DATA* system = NULL;
    int chance = 0;
    cache_skill( "ship systems", &skill_ship_systems );

    argument = one_argument( argument, arg );

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    ship = get_ship_from_room( ch->in_room );

    if ( !ship )
    {
        ch_println( ch, "&RMaybe you need to be onboard a ship first!" );
        return;
    }

    if ( ship != get_ship_from_navseat( ch->in_room ) )
    {
        ch_println( ch, "&RYou must be in the navigation seat of a ship to do that!" );
        return;
    }

    if ( !str_cmp( "load", arg ) )
    {
        obj = get_obj_carry( ch, argument );

        if ( !obj )
        {
            ch_println( ch, "Couldn't find that nav chart. It must be in your inventory." );
            return;
        }

        if ( obj->item_type != ITEM_NAVCHART || !obj->blueprint || obj->blueprint[0] == '\0' )
        {
            ch_println( ch, "That doesn't appear to be a proper navchart." );
            return;
        }

        if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
        {
            ch_println( ch, "Yeah...but you don't have clearance to do that." );
            return;
        }

        if ( autofly( ship ) )
        {
            ch_println( ch, "&RTake it off autopilot first!" );
            return;
        }

        for ( chart = ship->first_navchart; chart; chart = chart->next )
        {
            if ( !NULLSTR( chart->name ) && !NULLSTR( obj->blueprint ) && !str_cmp( chart->name, obj->blueprint ) )
            {
                ch_println( ch, "The nav comp already has that sector's info loaded." );
                return;
            }
        }

        system = starsystem_from_name( obj->blueprint );

        if ( !system )
        {
            ch_println( ch, "Your navcomputer beeps twice as it rejects the navigational chart as obsolete." );
            bug( "%s trying to load invalid navchart to %s into %s", ch->name, !NULLSTR( obj->blueprint ) ? obj->blueprint : "NULL", ship->name );
            return;
        }

        chart = NULL;
        CREATE( chart, NAVCHART_DATA, 1 );
        SET_STRING( chart->name, system->name );
        SET_STRING( chart->loaded_by, ch->name );
        chart->date = time( 0 );
        chart->xpos = system->xpos;
        chart->ypos = system->ypos;
        LINK_SORT_NAME( chart, NAVCHART_DATA, ship->first_navchart, ship->last_navchart, next, prev, name );
        save_ship( ship, true );
        ch_println( ch, "Navigational information for %s has been loaded into the nav comp.", chart->name );
        act( AT_ACTION, "$n loads navigational information into the nav computer.", ch, NULL, NULL, TO_ROOM );
        snprintf( bufA, MSL, "%s: %s loaded navchart to %s.", ship->shortname, ch->name, chart->name );
        to_channel( bufA, CHANNEL_MONITOR, "Monitor", 104 );
        separate_obj( obj );
        obj_from_char( obj );
        extract_obj( obj );
        return;
    }

    if ( !str_cmp( "clear", arg ) )
    {
        if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
        {
            ch_println( ch, "Yeah...but you don't have clearance to do that." );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_PERMCHARTS ) )
        {
            ch_println( ch, "This ship's navigation charts cannot be cleared." );
            return;
        }

        if ( !ship->first_navchart )
        {
            ch_println( ch, "There doesn't seem to be any extra sector info loaded." );
            return;
        }

        if ( str_cmp( "confirm", argument ) )
        {
            ch_println( ch, "Doing this will permanently erase all extra nav info on this ship." );
            ch_println( ch, "Are you sure you wish to proceed? If so, type NAVSTATUS CLEAR CONFIRM." );
            return;
        }

        strlcpy( bufB, "", MIL );
        snprintf( bufA, MSL, "%s: %s cleared navcharts to ", ship->shortname, ch->name );
        for ( chart = ship->first_navchart; chart; chart = next_chart )
        {
            next_chart = chart->next;

            if ( !NULLSTR( bufB ) )
                snprintf( bufB + strlen( bufB ), MIL - strlen( bufB ), ", " );

            snprintf( bufB + strlen( bufB ), MIL - strlen( bufB ), "%s", !NULLSTR( chart->name ) ? chart->name : "NULL" );
            UNLINK( chart, ship->first_navchart, ship->last_navchart, next, prev );
            delete_navchart( chart );
        }

        snprintf( bufA + strlen( bufA ), MSL - strlen( bufA ), "%s.", bufB );
        to_channel( bufA, CHANNEL_MONITOR, "Monitor", 104 );
        ch_println( ch, "Nav comp extra data cleared." );
        save_ship( ship, true );
        act( AT_ACTION, "$n clears the navigational computer's memory.", ch, NULL, NULL, TO_ROOM );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RNo point in finding your course while landed, eh?" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, skill_ship_systems ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't figure out what the readout means." );
        learn_from_failure( ch, skill_ship_systems );
        return;
    }

    act( AT_PLAIN, "$n checks various gauges and displays on the control panel.", ch, NULL, NULL, TO_ROOM );
    ch_println( ch, "&zReadout for &C%s&z:", ship->name );
    if ( ship->starsystem )
    {
        ch_println( ch, "&z---------------------------------------------------------" );
        ch_println( ch, "&zCurrent Coordinates: &C%.0f %.0f %.0f", ship->vpos.x, ship->vpos.y, ship->vpos.z );
        ch_println( ch, "&zCurrent Heading:     &C%.0f %.0f %.0f", ship->head.x, ship->head.y, ship->head.z );
        ch_println( ch, "&zCurrent Speed:       &C%d&z/&C%d", ship->currspeed, ship->realspeed );
    }
    ch_println( ch, "&z--&CLocation&z-----------------------------------------------" );

    if ( ship->starsystem != NULL )
    {
        ch_println( ch, "&zCurrent System:      &C%s",
                   ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
        ch_println( ch, "&zCurrent System X/Y:  (&C%d, %d&z)", ship->starsystem->xpos, ship->starsystem->ypos );
    }
    else
    {
        ch_println( ch, " &z(&WUnable to determine current location&z)" );
    }

    /*
        Nav comp - Lets hidden sectors be achieved ICly (BY FORCE!)  Orion
    */
    ch_println( ch, "&z--&CNav Computer&z-------------------------------------------" );
    ch_println( ch, "&zThis ship can jump to all standard sectors." );
    if ( ship->first_navchart )
    {
        strlcpy( bufA, "", MSL );
        for ( chart = ship->first_navchart; chart; chart = chart->next )
        {
            if ( !NULLSTR( bufA ) )
                snprintf( bufA + strlen( bufA ), MSL - strlen( bufA ), "&z, " );

            snprintf( bufA + strlen( bufA ), MSL - strlen( bufA ), "&C%s", !NULLSTR( chart->name ) ? chart->name : "NULL" );
        }

        ch_println( ch, "&zThis ship can also jump to: %s", bufA );
    }

    ch_println( ch, "&zTo add a new sector, &CNAVSTAT LOAD &z<&Cchart keyword&z>." );
    ch_println( ch, "&z--&CHyperspace&z---------------------------------------------" );

    if ( ship->hyperlock || ship->shipstate == SHIP_HYPERSPACE )
    {
        SPACE_DATA* jump_sys = system_from_galactic_coords(ship->hyper_exit);
        bool uncharted = !jump_sys
            || (!IS_IMMORTAL(ch) && !ship_knows_system(ship, jump_sys))
            || jump_sys->virtualsys;
        ch_println( ch, "&zJump System:         &C%s", uncharted ? "Uncharted space" : jump_sys->name );
        ch_println( ch, "&zJump Distance:       &C%.1f parsecs", hyper_distance(ship_galactic_coords(ship), ship->hyper_exit) );
        ch_println( ch, "&zJump Time:           &C%s", jumptime( ship, hyper_distance(ship_galactic_coords(ship), ship->hyper_exit) ) );
    }
    else
    {
        ch_println( ch, " &z(&WNo hyperspace trajectory is locked right now&z)" );
    }

    learn_from_success( ch, skill_ship_systems );
    return;
}

CMDF do_cloak( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    SHIP_DATA* ship = NULL;
    char buf[MSL];

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou aren't in the pilots seat." );
        return;
    }

    if ( ship->energy < 500 )
    {
        ch_println( ch, "&RThe ship does not have enough energy to maintain the cloaking generator." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_NONE )
    {
        ch_println( ch, "&RYou don't have a cloak installed!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_DAMAGED )
    {
        ch_println( ch, "&RYour cloaking device is damaged!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED || ship->dockship )
    {
        ch_println( ch, "&RNot while docked with another ship!" );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        echo_to_ship_windows( AT_YELLOW, ship, "Cloaking Device off!" );
        echo_to_ship_main( AT_BLUE, ship, "[Alert] Cloaking Device Deactivating!" );
        ship->cloakstatus = CLOAK_READY;

        if ( xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - deactivating cloak allows ping.
        {
            xREMOVE_BIT( ship->flags, SHIP_NO_PING );
        }

        snprintf( buf, MSL, "%s shimmers into existence.", ship->name );
        echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
    }
    else if ( ship->cloakstatus == CLOAK_READY )
    {
        echo_to_ship_windows( AT_YELLOW, ship, "Cloaking Device on!" );
        echo_to_ship_main( AT_BLUE, ship, "[Alert] Cloaking Device Activating!" );
        ship->cloakstatus = CLOAK_ON;

        if ( !xIS_SET( ship->flags, SHIP_NO_PING ) ) // Ralen Apr '14 - can't get a ping from a cloaked ship.
        {
            xSET_BIT( ship->flags, SHIP_NO_PING );
        }

        snprintf( buf, MSL, "%s shimmers out of existence.", ship->name );
        echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
        ship->hyperlock = FALSE;

        if ( ship->target0 || ship->target1 || ship->target2 )
        {
            echo_to_ship_windows( AT_PLAIN + AT_BLINK, ship, "All targets lost!" );
            ship->target0 = NULL;
            ship->target1 = NULL;
            ship->target2 = NULL;
        }
    }
}

