void enter_hyperspace( SHIP_DATA* ship )
{
    SPACE_DATA* system = ship ? ship->starsystem : NULL;
    char buf[MSL];
    snprintf( buf, MSL,
             "%ss hyperdrive engines flare as it initiates a hyperjump, disappearing into the distance as a streak of light.",
             ship->name );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );

    // Proactively clear any targeting of this ship
    for ( SHIP_DATA* ship_sys = ship->starsystem->first_ship; ship_sys; ship_sys = ship_sys->next_in_starsystem )
    {
        if ( ship_sys->target0 == ship )
        {
            ship_sys->target0 = NULL;
            echo_to_ship_windows( AT_RED, ship_sys, "You have lost your targeting lock." );
        }

        for ( TURRET_DATA* turret = ship_sys->first_turret; turret; turret = turret->next )
        {
            if ( turret->room && turret->target == ship )
            {
                turret->target = NULL;
                echo_to_room( AT_RED, turret->room, "You have lost your targeting lock." );
            }
        }
    }
    ship->hyperlock = FALSE;
    ship->hyper_currentpos = ship_galactic_coords(ship);
    ship->hyper_exit_countdown = 0;
    ship->prev_starsystem = ship->starsystem;
    ship_from_starsystem( ship );
    ship->shipstate = SHIP_HYPERSPACE;
    echo_to_ship_main( AT_YELLOW, ship, "The ship lurches slightly as it makes the jump to lightspeed." );
    echo_to_ship_windows( AT_YELLOW, ship, "The stars become streaks of light as you enter hyperspace." );
    lua_trigger_ship_hyper( ship, system );
}

CMDF do_hyperspace( CHAR_DATA* ch, char* argument )
{
    int chance = 0;
    SHIP_DATA* ship;
    SHIP_DATA* eShip;
    char buf[MSL];
    bool hyOff = FALSE;
    double dist = 0;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( !str_cmp( argument, "off" ) )
        hyOff = TRUE;

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou aren't in the pilots seat." );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED || ship->dockship )
    {
        ch_println( ch, "&RNot while docked with another ship!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        if ( xIS_SET( ship->flags, SHIP_ONEHYPER ) && ship->hyperspeed == 0 )
        {
            ch_println( ch, "&RPlatforms can't move!" );
            return;
        }
    }

    if ( ship->shipstate != SHIP_HYPERSPACE && hyOff )
    {
        ch_println( ch, "&RThis ship is *NOT* in hyperspace!" );
        return;
    }

    if ( ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) && !hyOff )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to maneuver." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't jump to hyperspace while cloaked." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( !hyOff )
    {
        if ( ship->hyperspeed == 0 )
        {
            ch_println( ch, "&RThis ship is not equipped with a hyperdrive!" );
            return;
        }

        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            ch_println( ch, "&RYou are already traveling at lightspeed!" );
            return;
        }

        if ( ship->shipstate != SHIP_READY )
        {
            ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
            return;
        }

        if ( ship->calctimer > 0 )
        {
            ch_println( ch, "&zPlease Wait. The Navigation Computer is calculating the route." );
            return;
        }

        if ( !ship->hyperlock )
        {
            ch_println( ch, "&RYou need to calculate your jump first!" );
            return;
        }

        if ( IS_SET( ship->act_flags, MOD_GRAVITYWELL ) )
        {
            ch_println( ch, "&RNot with the Gravity Well Emitter on!" );
            return;
        }

        if ( ship->energy < ship_hyperjump_fuel_cost( ship, ship->hyper_exit ) )
        {
            ch_println( ch, "&RThere's not enough fuel!" );
            return;
        }

        if ( ship->currspeed <= 0 )
        {
            ch_println( ch, "&RYou need to speed up a little first!" );
            return;
        }

        for ( eShip = ship->starsystem->first_ship; eShip; eShip = eShip->next_in_starsystem )
        {
            if ( eShip == ship )
                continue;

            if ( xIS_SET( eShip->flags, SHIP_ENVIROSUIT ) )
                continue;

            // Squadrons can jump near each other.
            if ( eShip->squadleader && eShip->squadleader == ship->squadleader )
                continue;

            // Ships in the same battlegroup no longer block each other's hyperspace jumps
            if ( same_group( eShip, ship ) )
                continue;

            dist = vector_distance( &ship->vpos, &eShip->vpos );

            if ( IS_SET( eShip->act_flags, MOD_GRAVITYWELL ) && dist <= MAX_GRAVITY_RANGE )
            {
                ch_println( ch, "&RYou'll have to get outside the range of the interdictor field on the %s",
                        eShip->name );
                return;
            }

            if ( dist < 500 )
            {
                ch_println( ch, "&RYou are too close to %s to make the jump to lightspeed!", eShip->name );
                return;
            }
        }

        for ( PLANET_DATA* planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
        {
            dist = vector_distance( &ship->vpos, &planet->pos );
            if ( dist < 500 )
            {
                ch_println( ch, "&RYou are too close to %s&R to make the jump to lightspeed!", planet->name );
                return;
            }
        }
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't figure out which lever to use." );
        learn_from_failure( ch, find_gsn( ship->classtype ) );
        return;
    }

    if ( !hyOff )
    {
        ch_println( ch, "&GYou push forward the hyperspeed lever." );
        act( AT_PLAIN, "$n pushes a lever forward on the control panel.", ch, NULL, argument, TO_ROOM );

        if ( is_squadleader( ship ) )
        {
            SHIP_DATA* sq = NULL;
            SPACE_DATA* sys = ship->starsystem;

            for ( sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( sq->starsystem != sys )
                    continue;

                if ( !should_follow_squadleader( sq, ship ) )
                    continue;

                if ( !sq->hyperlock )
                    continue;

                if ( sq->shipstate == SHIP_DISABLED || sq->shipstate == SHIP_PERM_DISABLED )
                {
                    message_to_squadleader( sq, "My drive is shot..." );
                    continue;
                }

                if ( sq->energy < ship_hyperjump_fuel_cost( sq, sq->hyper_exit ) )
                {
                    message_to_squadleader( sq, "I don't have enough fuel, I'll stay right here." );
                    continue;
                }

                bool too_close = false;

                for ( eShip = ship->starsystem->first_ship; eShip; eShip = eShip->next_in_starsystem )
                {
                    if ( eShip->squadleader && eShip->squadleader == ship->squadleader )
                        continue;

                    dist = vector_distance( &ship->vpos, &eShip->vpos );

                    if ( IS_SET( eShip->act_flags, MOD_GRAVITYWELL ) && dist <= MAX_GRAVITY_RANGE )
                    {
                        too_close = true;
                        message_to_squadleader( sq, "Feth... it looks like I'm caught in a gravity well." );
                        break;
                    }

                    if ( dist < 500 )
                    {
                        too_close = true;
                        snprintf( buf, MSL, "I'm too close to %s to make the jump!", eShip->name );
                        message_to_squadleader( sq, buf );
                        break;
                    }
                }

                if ( too_close )
                    continue;

                enter_hyperspace( sq );
            }
        }

        enter_hyperspace( ship );
    }
    else
    {
        ch_println( ch, "&GYou pull the hyperspeed lever back." );
        act( AT_PLAIN, "$n pulls a lever back on the control panel.", ch, NULL, argument, TO_ROOM );

        echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Hyperjump aborting! Shutting down the hyperdrive..." );
        ship->hyper_exit = ship->hyper_currentpos;
        ship->hyper_exit_countdown = 3;

        if ( is_squadleader( ship ) )
        {
            for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
            {
                if ( !should_follow_squadleader( sq, ship ) )
                    continue;

                if ( sq->shipstate != SHIP_HYPERSPACE )
                    continue;

                message_to_squadleader( sq, "Aborting hyperjump now." );
                sq->hyper_exit = sq->hyper_currentpos;
                sq->hyper_exit_countdown = 3;
            }
        }
    }

    learn_from_success( ch, find_gsn( ship->classtype ) );
}

bool is_protected( SHIP_DATA* ship, SHIP_DATA* target, bool turret )
{
    if ( !target->starsystem )
        return FALSE;

    // Non-capital ships and turrets can bypass battlegroup protections.
    if ( target->classtype >= FRIGATE_SHIP && ( turret || ( ship && ship->classtype < FRIGATE_SHIP ) ) )
        return FALSE;

    for ( SHIP_DATA* bship = target->starsystem->first_ship; bship; bship = bship->next_in_starsystem )
    {
        if ( !same_group( bship, target ) )
            continue;

        if ( bship->pos >= target->pos )
            continue;

        if ( vector_distance( &bship->vpos, &target->vpos ) > 1000 )
            continue;

        if ( ship && vector_distance( &bship->vpos, &ship->vpos ) > 2000 )
            continue;

        return TRUE;
    }

    return FALSE;
}

SHIP_DATA* nearest_unprotected_group_ship( const Vector3 from_pos, SHIP_DATA* from_ship, SHIP_DATA* target, bool turret )
{
    if ( !target || !target->starsystem )
        return NULL;

    SHIP_DATA* result = NULL;

    for ( SHIP_DATA* ship_sys = target->starsystem->first_ship; ship_sys; ship_sys = ship_sys->next_in_starsystem )
    {
        if ( same_group( target, ship_sys ) && !is_protected( from_ship, ship_sys, turret ) )
        {
            if ( result == NULL ||
                    vector_distance( &ship_sys->vpos, &from_pos ) < vector_distance( &target->vpos, &from_pos )
               )
                result = ship_sys;
        }
    }

    return result;
}

bool ship_has_weapons( SHIP_DATA* ship )
{
    if ( !ship )
        return false;

    bool has_weapons = false;

    if ( ship->missiletubes > 0 && ( ship->missiles > 0 || ship->torpedoes > 0 || ship->rockets > 0 ) )
        has_weapons = true;

    if ( ship->lasers + ship->ion + ship->blasters + ship->turbolasers > 0 )
        has_weapons = true;

    return has_weapons;
}

int target_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYour concentration is broken. You fail to lock on to your target." );
    return E_LOTJ_SUCCESS;
}

int target_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    SHIP_DATA* target = buffer->shiptarget;
    SHIP_DATA* sq = NULL;
    SHIP_DATA** squad = NULL;

    if ( !valid_ship( ship ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    if ( !valid_ship( target ) || target->starsystem != ship->starsystem || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RThe ship has left the starsystem. Targeting aborted." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( ch->in_room->vnum == ship->gunseat )
        ship->target0 = target;

    TURRET_DATA* turret = get_turret_room( ship, ch->in_room );
    if ( turret )
        set_turret_target( ship, turret, target );

    ch_println( ch, "&GTarget Locked." );
    echo_to_ship_windows( AT_BLOOD, target, strfmt("You are being targeted by %s.", ship->name) );
    sound_to_room( ch->in_room, "targetlock" );
    cache_skill( "weapon systems", &skill_weapon_systems );
    learn_from_success( ch, skill_weapon_systems );
    ai_anger( target, ship, FALSE );
    ship_start_fighting( ship, target );
    lua_trigger_ship_targeted( target, ship );

    if ( target->squadleader && target->squadleader != ship )
    {
        switch ( number_range( 1, 3 ) )
        {
            case 1:
                message_to_squadleader( target, strfmt("%s has a lock on me!", ship->name) );
                break;
            case 2:
                message_to_squadleader( target, strfmt("I'm being targeted by %s!", ship->name) );
                break;
            case 3:
                message_to_squadleader( target, strfmt("%s locked weapons on my ship.", ship->name) );
                break;
        }
    }

    if ( is_squadleader( ship ) )
    {
        LINK_TO_ARRAY( ship->first_in_squad, SHIP_DATA, next_in_squad, squad );

        for ( int i = 0; squad[i]; i++ )
        {
            sq = squad[i];

            if ( ship_extracted( sq ) )
                continue;

            if ( !should_follow_squadleader( sq, ship ) )
                continue;

            if ( sq->starsystem != ship->starsystem )
                continue;

            if ( sq->shipstate == SHIP_DISABLED || sq->shipstate == SHIP_PERM_DISABLED )
                continue;

            sq->target0 = target;
            echo_to_ship_windows( AT_BLOOD, target, strfmt("You are being targeted by %s.", sq->name) );
            ai_anger( target, sq, FALSE );
            ship_start_fighting( sq, NULL );
            lua_trigger_ship_targeted( target, sq );

            switch ( number_range( 1, 4 ) )
            {
                case 1:
                    message_to_squadleader( sq, "Target acquired." );
                    break;
                case 2:
                    message_to_squadleader( sq, "Weapons locked." );
                    break;
                case 3:
                    message_to_squadleader( sq, "Targeting computer engaged." );
                    break;
                case 4:
                    message_to_squadleader( sq, "Let's light it up!" );
                    break;
            }
        }

        DISPOSE( squad );
    }

    return E_LOTJ_SUCCESS;
}

CMDF do_target( CHAR_DATA* ch, char* argument )
{
    int chance = 0;
    SPACE_DATA* wsystem = NULL;
    PLANET_DATA* wplanet = NULL;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* target = NULL;
    TURRET_DATA* turret = NULL;
    char buf[MSL];
    VEHICLE_DATA* vec = NULL;
    cache_skill( "weapon systems", &skill_weapon_systems );

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    /*
        Planetary Weapons Addition --> Ghost
    */
    if ( ch->in_room )
    {
        if ( ( xIS_SET( ch->in_room->flags, ROOM_WEAP_ION ) || xIS_SET( ch->in_room->flags, ROOM_WEAP_TURBOLASER ) ) && ( turret = turret_from_room( ch->in_room ) ) != NULL )
        {
            if ( ( wplanet = get_planet_from_room( ch->in_room ) ) != NULL )
            {
                if ( ( wsystem = wplanet->starsystem ) != NULL )
                {
                    if ( !ch->pcdata->clan || ch->pcdata->clan == NULL )
                    {
                        ch_println( ch, "&RYou must be in a clan to change the target of a planets defensive cannons!" );
                        return;
                    }

                    if ( !wplanet->governed_by || wplanet->governed_by == NULL )
                    {
                        ch_println( ch, "&RThis planet is not governed by %s! Access denied.", ch->pcdata->clan->name );
                        return;
                    }

                    if ( ch->pcdata->clan != wplanet->governed_by )
                    {
                        ch_println( ch, "&RThis planet is under the government of %s! Access denied.", wplanet->governed_by->name );
                        return;
                    }

                    if ( !is_empowered( ch, "pturrets" ) && str_cmp( ch->name, ch->pcdata->clan->leader ) )
                    {
                        ch_println( ch, "Your clan did not give you permission to control the planetary cannons!" );
                        return;
                    }

                    if ( NULLSTR( argument ) )
                    {
                        /*
                            List all ships
                        */
                        SHIP_DATA* scan;
                        act( AT_PLAIN, "$n checks the targeting computer.", ch, NULL, argument, TO_ROOM );
                        set_char_color( AT_WHITE, ch );
                        ch_println( ch, "\nTargetable ships within scanning range:" );
                        set_char_color( AT_LBLUE, ch );

                        for ( scan = wsystem->first_ship; scan; scan = scan->next_in_starsystem )
                        {
                            if ( xIS_SET( scan->flags, SHIP_ENVIROSUIT ) || scan->classtype < CORVETTE_SHIP )
                                continue;

                            if ( vector_distance( &wplanet->pos, &scan->vpos ) <= 8000 )
                            {
                                if ( scan->cloakstatus != CLOAK_ON || IS_IMMORTAL( ch ) )
                                {
                                    strlcpy( buf, "&C-----", MSL );

                                    if ( 100 * ( scan->hull / scan->maxhull ) <= 70 )
                                        strlcpy( buf, "&YInjured", MSL );

                                    if ( 100 * ( scan->hull / scan->maxhull ) <= 50 )
                                        strlcpy( buf, "&YDamaged", MSL );

                                    if ( 100 * ( scan->hull / scan->maxhull ) <= 30 )
                                        strlcpy( buf, "&RCrippled", MSL );

                                    if ( scan->shipstate == SHIP_DISABLED || scan->shipstate == SHIP_PERM_DISABLED )
                                        strlcpy( buf, "&W*DISABLED*", MSL );

                                    ch_println( ch, "&z%-25s  Status: %s &zProx &C%d", scan->name, buf,
                                               ( int )vector_distance( &wplanet->pos, &scan->vpos ) );
                                }
                            }
                        }
                    }
                    else if ( !str_cmp( argument, "none" ) )
                    {
                        ch_println( ch, "&GTarget set to none." );
                        act( AT_PLAIN, "$n makes some adjustments on the targeting computer.", ch, NULL, argument, TO_ROOM );
                        turret->target = NULL;
                        return;
                    }
                    else
                    {
                        if ( xIS_SET( wplanet->flags, PLANET_AUTOFIRE ) )
                        {
                            ch_println( ch, "The planetary cannons are being controlled remotely. Try using the PTURRET command to turn on manual control." );
                            return;
                        }

                        if ( xIS_SET( wplanet->flags, PLANET_NOPVP ) )
                        {
                            ch_println( ch, "(OOC) Sorry, this is a No PVP planet." );
                            return;
                        }

                        if ( turret->laserstate > 0 )
                        {
                            ch_println( ch, "&R[ALERT]: Systems busy...Recharging Weapon." );
                            return;
                        }

                        target = get_ship_here( argument, wsystem );

                        if ( !target || target == NULL )
                            ch_println( ch, "&R[ALERT]: Target not found - Systems on standby..." );
                        else
                        {
                            if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) || target->classtype < CORVETTE_SHIP )
                            {
                                ch_println( ch, "&R[ALERT]: That is too small to target - Systems on standby..." );
                                return;
                            }

                            if ( xIS_SET( target->flags, SHIP_NOTARGET ) )
                            {
                                ch_println( ch, "&R[ALERT]: Cannot lock onto that vessel - Systems on standby..." );
                                return;
                            }

                            if ( target->cloakstatus == CLOAK_ON && !IS_IMMORTAL( ch ) )
                            {
                                ch_println( ch, "&R[ALERT]: Target not found - Systems on standby..." );
                                return;
                            }

                            if ( vector_distance( &wplanet->pos, &target->vpos ) > 8000 )
                            {
                                send_to_char( "&R[ALERT]: Target too far away to establish lock. Standing by...\n",
                                              ch );
                                return;
                            }

                            turret->target = target;
                            turret->laserstate += 2;
                            echo_to_room( AT_RED, ch->in_room,
                                          "[ALERT]: Established Target Lock -=- Charging Weapons...\n" );
                            snprintf( buf, MSL, "You are being targeted by planetary turrets on %s.", wplanet->name );
                            echo_to_ship_windows( AT_BLOOD, target, buf );
                            WAIT_STATE( ch, 6 * PULSE_PER_SECOND );
                            return;
                        }
                    }

                    return;
                }
            }

            ch_println( ch, "&R[ALERT]: Targeting Error - All weapons on standby..." );
            return;
        }
    }

    /*
        Vehicle Combat Check
    */
    if ( vehicle_target( ch, argument ) )
        return;

    ship = get_ship_from_turret( ch->in_room );

    if ( !ship )
    {
        ch_println( ch, "&RYou must be in the gunners seat or turret of a ship to do that!" );
        return;
    }

    if ( ship->in_room && ship->in_room->area && ship->in_room->area->planet && xIS_SET( ship->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return;
    }

    if ( ship->target_v && !str_cmp( "none", argument ) )
    {
        ch_println( ch, "Target cleared." );
        act( AT_PLAIN, "$n makes some adjustments on the targeting computer.", ch, NULL, argument, TO_ROOM );
        ship->target_v = NULL;
        return;
    }

    for ( vec = first_vehicle; vec; vec = vec->next )
        if ( nifty_is_name_prefix( argument, vec->name ) && vec->in_room == ship->in_room && ship->in_room != NULL )
            break;

    if ( vec )
    {
        if ( !ship->in_room || ship->shipstate != SHIP_HOVER )
        {
            ch_println( ch, "&RThis ship must be hovering to target vehicles." );
            return;
        }

        ch_println( ch, "&GTarget locked." );
        ship->target_v = vec;
        return;
    }

    // Ship-to-ship targeting happens below here
    if ( ( ship = get_ship_from_turret( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the gunners seat or turret of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( !ship->starsystem )
    {
        ch_println( ch, "&RYou can't do that until you've finished launching!" );
        return;
    }

    if ( autofly( ship ) && ship->classtype < 8 && !nifty_is_name( ch->name, ship->crew ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first..." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't target while cloaked." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&RYou need to specify a target!" );
        return;
    }

    if ( !ship_has_weapons( ship ) )
    {
        ch_println( ch, "&RThis ship doesn't have any weapons." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) && str_cmp( "none", argument ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "&RThe ship's communications array is completely fried!" );
        return;
    }

    if ( !str_cmp( argument, "none" ) )
    {
        ch_println( ch, "&GTarget set to none." );
        act( AT_PLAIN, "$n makes some adjustments on the targeting computer.", ch, NULL, argument, TO_ROOM );

        if ( ch->in_room->vnum == ship->gunseat )
        {
            ship->target0 = NULL;

            if ( ship->first_turret )
                for ( turret = ship->first_turret; turret; turret = turret->next )
                {
                    echo_to_room( AT_WHITE, turret->room,
                                    "A flashing light *BLIPS* on the console next to -TARGET BROKEN-\n" );
                    turret->target = NULL;
                }
        }

        turret = get_turret_room( ship, ch->in_room );

        if ( turret )
        {
            turret->target = NULL;

            if ( ship->navseat > 0 )
            {
                int idx = 0;
                LINK_INDEXOF( ship->first_turret, TURRET_DATA, next, turret, idx );
                snprintf( buf, MSL, "An alert pops up on a console: 'Turret %d broke target lock.'\n", idx );
                echo_to_room( AT_LBLUE, get_room_index( ship->navseat ), buf );
            }
        }

        return;
    }

    target = get_ship_here( argument, ship->starsystem );

    if ( target == NULL )
    {
        ch_println( ch, "&RThat ship isn't here!" );
        return;
    }

    if ( target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RThat ship isn't here!" );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_NOTARGET ) )
    {
        ch_println( ch, "&RYour systems cannot lock on to that target." );
        return;
    }

    if ( is_protected( ship, target, get_turret_room( ship, ch->in_room ) != NULL ) || xIS_SET( target->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RThat ship is currently being protected by other ships." );
        return;
    }

    if ( target == ship )
    {
        ch_println( ch, "&RYou can't target your own ship!" );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) > ( ( ship->classtype + 1 ) * 2500 ) )
    {
        ch_println( ch, "&RThat ship is too far away to target." );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
    {
        ch_println( ch, "&R[ALERT]: That is too small to target - Systems on standby..." );
        return;
    }

    if ( is_rental( ch, target ) )
    {
        send_to_char
        ( "&YIf you perm the person on this ship, and you have insufficient RP to back this up, you will be in a shitload of trouble.\n",
            ch );
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, skill_weapon_systems ) );

    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GTracking target." );
        act( AT_PLAIN, "$n makes some adjustments on the targeting computer.", ch, NULL, argument, TO_ROOM );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 3, target_complete, target_abort, FUNC );
        timer->buffer->ship = ship;
        timer->buffer->shiptarget = target;
        return;
    }

    ch_println( ch, "&RYou fail to work the controls properly." );
    learn_from_failure( ch, skill_weapon_systems );
    return;
}

TURRET_DATA* turret_from_room( ROOM_INDEX_DATA* room )
{
    if ( !room )
        return NULL;

    return room->turret;
}

bool planet_fire_check( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    SHIP_DATA* target = NULL;
    PLANET_DATA* wplanet = NULL;
    SPACE_DATA* wsystem = NULL;
    TURRET_DATA* turret = NULL;
    double chance = 0;
    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );

    if ( ch->in_room )
    {
        if ( xIS_SET( ch->in_room->flags, ROOM_WEAP_ION ) || xIS_SET( ch->in_room->flags, ROOM_WEAP_TURBOLASER ) )
        {

            if ( ( wplanet = get_planet_from_room( ch->in_room ) ) != NULL )
            {
                if ( ( wsystem = wplanet->starsystem ) != NULL )
                {
                    turret = turret_from_room( ch->in_room );

                    if ( !turret )
                    {
                        bug( "%s: missing pturret struct in room %d", FUNC, ch->in_room->vnum );
                        ch_println( ch, "&z[&CALERT&z]: This turret is defective!" );
                        return TRUE;
                    }

                    target = turret->target;

                    if ( !target || target == NULL )
                    {
                        ch_println( ch, "&z[&CALERT&z]: Set target before firing planetary weapons!" );
                        return TRUE;
                    }

                    if ( target->starsystem != wsystem || ( target->cloakstatus == CLOAK_ON && !IS_IMMORTAL( ch ) ) )
                    {
                        ch_println( ch, "&R[ALERT]: Sensors cannot detect current target. Stand down..." );
                        turret->laserstate += 1;
                        turret->target = NULL;
                        return TRUE;
                    }

                    if ( turret->laserstate >= 1 )
                    {
                        ch_println( ch, "&R[ALERT]: Weapons are still recharging...Please stand by..." );
                        return TRUE;
                    }

                    if ( target->starsystem != wsystem )
                    {
                        ch_println( ch, "&R[ALERT]: Target lost...Switching to stand by." );
                        turret->target = NULL;
                        return TRUE;
                    }

                    if ( vector_distance( &wplanet->pos, &target->vpos ) > 5000 )
                    {
                        ch_println( ch, "&R[ALERT]: Target is out of range...Switching to stand by." );
                        turret->target = NULL;
                        return TRUE;
                    }

                    chance += target->classtype * 25;
                    chance -= target->maneuver / 10;
                    chance -= target->currspeed / 20;
                    chance -= ( fabs( wplanet->pos.x - target->vpos.x ) / 70 );
                    chance -= ( fabs( wplanet->pos.y - target->vpos.y ) / 70 );
                    chance -= ( fabs( wplanet->pos.z - target->vpos.z ) / 70 );
                    chance = URANGE( 30, chance, 90 );

                    if ( number_percent() > chance )
                    {
                        turret->laserstate += 1;
                        snprintf( buf, MSL, "Something opens fire from the surface of %s, barely missing %s!", wplanet->name,
                                 target->name );
                        echo_to_system_noqueue_noship( AT_ORANGE, target->starsystem, buf );
                        snprintf( buf, MSL, "You are almost hit by fire from the surface of %s!", wplanet->name );
                        echo_to_ship_windows( AT_BLOOD, target, buf );
                        ch_println( ch, "Your shot entirely misses %s, fading into the distance...", target->name );
                        learn_from_success( ch, skill_space_combat_1 );
                        learn_slow( ch, skill_space_combat_2, 4 );
                        learn_slow( ch, skill_space_combat_3, 5 );
                        WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
                        return TRUE;
                    }

                    echo_to_room( AT_RED, ch->in_room, "\n[ALERT]: Firing weapon batteries!" );

                    if ( !str_prefix( argument, "lasers" ) || !str_prefix( argument, "turbolasers" ) )
                    {
                        if ( xIS_SET( ch->in_room->flags, ROOM_WEAP_TURBOLASER ) )
                        {
                            turret->laserstate += 1;
                            snprintf( buf, MSL, "Turbolasers erupt from the surface of %s, hitting %s!", wplanet->name,
                                     target->name );
                            echo_to_system_noqueue_noship( AT_ORANGE, target->starsystem, buf );
                            snprintf( buf, MSL, "You are hit by turbolasers from the surface of %s!", wplanet->name );
                            echo_to_ship_windows( AT_BLOOD, target, buf );
                            ch_println( ch, "The planetary turbolaser batteries hit %s!", target->name );
                            learn_from_success( ch, skill_space_combat_1 );
                            learn_slow( ch, skill_space_combat_2, 4 );
                            learn_slow( ch, skill_space_combat_3, 5 );
                            int mindam = UMIN( target->maxhull * .1, 1500 );
                            echo_to_ship_main( AT_RED, target, "A massive explosion rips through the ship!" );
                            damage_ship( target, mindam, mindam * 2, ch, NULL );
                            WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
                            return TRUE;
                        }
                        else
                        {
                            ch_println( ch, "&R[ALERT]: Current weapon system does not support 'turbolasers'..." );
                            return TRUE;
                        }
                    }
                    else if ( !str_prefix( argument, "ion" ) )
                    {
                        if ( xIS_SET( ch->in_room->flags, ROOM_WEAP_ION ) )
                        {
                            turret->laserstate += 3;
                            snprintf( buf, MSL, "Ion blasts erupt from the surface of %s, hitting %s!", wplanet->name,
                                     target->name );
                            echo_to_system_noqueue_noship( AT_ORANGE, target->starsystem, buf );
                            snprintf( buf, MSL, "You are hit by ion blasts from the surface of %s!", wplanet->name );
                            echo_to_ship_windows( AT_BLOOD, target, buf );
                            ch_println( ch, "The planetary ion batteries hit %s!", target->name );
                            learn_from_success( ch, skill_space_combat_1 );
                            learn_slow( ch, skill_space_combat_2, 4 );
                            learn_slow( ch, skill_space_combat_3, 5 );
                            int mindam = UMIN( target->maxhull * .1, 1500 );
                            echo_to_ship_main( AT_RED, target, "A small explosion vibrates through the ship." );
                            damage_ship_ion( target, mindam, mindam * 2, NULL );
                            WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
                            return TRUE;
                        }
                        else
                        {
                            ch_println( ch, "&R[ALERT]: Current weapon system does not support 'ion' weapons..." );
                            return TRUE;
                        }
                    }
                    else
                    {
                        ch_println( ch, "&R[ALERT]: No weapon type specified. Please choose ION or LASERS." );
                        return TRUE;
                    }
                }
            }
        }
    }

    return FALSE;
}

CMDF do_fire( CHAR_DATA* ch, char* argument )
{
    double dist = 0;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* target = NULL;
    TURRET_DATA* turret = NULL;
    char buf[MSL];
    VEHICLE_DATA* vec = NULL;
    int i = 0; // For loop counter
    cache_skill( "space combat 1", &skill_space_combat_1 );
    cache_skill( "space combat 2", &skill_space_combat_2 );
    cache_skill( "space combat 3", &skill_space_combat_3 );

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    /*
        Planetary Weapons Systems  -> Ghost
    */
    if ( planet_fire_check( ch, argument ) )
        return;

    /*
        Vehicle Combat Check
    */
    if ( vehicle_fire( ch, argument ) )
        return;

    /*
        Normal ship firing code  -> Ghost
        Expanded for Orbital Mines -> Ghost
    */
    if ( ( ship = get_ship_from_turret( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the gunners chair or turret of a ship to do that!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( is_rental( ch, ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RPublic vessels aren't equipped with firing control systems." );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->starsystem == NULL && !ship->target_v )
    {
        ch_println( ch, "&RYou can't do that until after you've finished launching!" );
        return;
    }

    if ( ship->energy < 5 )
    {
        ch_println( ch, "&RThere's not enough energy left to fire ANYthing!" );
        return;
    }

    if ( autofly( ship ) && ship->classtype < 8 && !is_crew( ch, ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ( vec = ship->target_v ) )
    {
        if ( ship->lasers == 0 )
        {
            ch_println( ch, "This ship is not equipped with lasers." );
            return;
        }

        if ( ship->laser_charge <= LASER_DAMAGED )
        {
            ch_println( ch, "&RThe ship's laser cannon(s) are damaged." );
            return;
        }

        if ( ship->laser_charge >= ship->lasers )
        {
            ch_println( ch, "&RThe laser cannons are still recharging." );
            return;
        }

        ship_start_fighting( ship, NULL );

        if ( number_percent(  ) <= 50 )
        {
            snprintf( buf, MSL, "Lasers from %s fire at %s, narrowly missing.", ship->name, vec->name );
            echo_to_room( AT_ORANGE, ship->in_room, buf );
            snprintf( buf, MSL, "Lasers fire from your ship, narrowly missing %s.", vec->name );
            echo_to_ship_windows( AT_ORANGE, ship, buf );
            snprintf( buf, MSL, "Lasers from %s fire at your vehicle, narrowly missing.", ship->name );
            echo_to_room( AT_ORANGE, get_room_index( vec->cockpit ), buf );
            return;
        }

        snprintf( buf, MSL, "Lasers from %s hit %s!", ship->name, vec->name );
        echo_to_room( AT_YELLOW, ship->in_room, buf );
        snprintf( buf, MSL, "Your ship's lasers hit %s!", vec->name );
        echo_to_ship_windows( AT_YELLOW, ship, buf );
        snprintf( buf, MSL, "Lasers from %s hit your vehicle!", ship->name );
        echo_to_room( AT_ORANGE, get_room_index( vec->cockpit ), buf );
        damage_vehicle_ch( vec, number_range( 10, 25 ), number_range( 20, 55 ), ch );
        echo_to_vehicle( AT_RED, vec, "The vehicle shudders as it is hit\n" );
        ship->laser_charge++;
        save_ship( ship, true );
        return;
    }

    /*
        Make sure the user entered a weapon to use. Otherwise, Find the
        first available standardized weapon on the ship. (Normally lasers)
    */
    if ( NULLSTR( argument ) )
    {
        if ( ( turret = get_turret_room( ship, ch->in_room ) ) != NULL )
        {
            if ( ship->classtype <= FRIGATE_SHIP )
                do_fire( ch, "autoblasters" );
            else if ( ship->classtype == CRUISER_SHIP )
                do_fire( ch, "lasers" );
            else
                do_fire( ch, "turbolaser" );
        }
        else
        {
            if ( ship->turbolasers > 0 )
                do_fire( ch, "turbolaser" );
            else if ( ship->lasers > 0 )
                do_fire( ch, "lasers" );
            else if ( ship->blasters > 0 )
                do_fire( ch, "autoblasters" );
            else if ( ship->ion > 0 )
                do_fire( ch, "ion" );
            else if ( ship->rockets > 0 )
                do_fire( ch, "rocket" );
            else if ( ship->torpedoes > 0 )
                do_fire( ch, "torpedo" );
            else if ( ship->missiles > 0 )
                do_fire( ch, "missile" );
            else if ( ship->pulses > 0 )
                do_fire( ch, "pulse" );
        }

        return;
    }

    turret = get_turret_room( ship, ch->in_room );
    target = ship->target0;

    if ( turret )
        target = turret->target;

    if ( !target )
    {
        ch_println( ch, "&RYou need to choose a target first." );
        return;
    }

    if ( target->starsystem != ship->starsystem || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou need to choose a target first." );

        if ( turret )
            turret->target = NULL;
        else
            ship->target0 = NULL;

        return;
    }

    dist = vector_distance( &ship->vpos, &target->vpos );

    if ( xIS_SET( ship->flags, SHIP_VONG ) )
    {
        turret = get_turret_room( ship, ch->in_room );

        if ( ch->in_room->vnum == ship->gunseat )
        {
            fire_ship_yaretkor( ship, ch, target );
        }
        else if ( turret )
        {
            fire_ship_yaretkor_turret( ship, ch, turret );
        }
        else
        {
            ch_println( ch, "&RYou can't fire from here!" );
        }

        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "lasers" ) )
    {
        fire_ship_laser( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "beam" ) && IS_SET( ship->mod_flags, MOD_BEAM ) )
    {
        if ( dist > 2000 )
        {
            ch_println( ch, "&RYour target is outside of the range of this weapon." );
            return;
        }

        ship_start_fighting( ship, target );
        double chance = standard_ship_hit_chance( ch );

        if ( number_percent() > chance || ship_dodge( target, ship, true ) )
        {
            snprintf( buf, MSL, "A thick green beam streaks out from %s, narrowly missing your ship.", ship->name );
            echo_to_ship_windows( AT_GREEN, target, buf );
            snprintf( buf, MSL, "A thick green beam streaks out from your ship towards %s but misses.", target->name );
            echo_to_ship_windows( AT_WHITE, ship, buf );
            learn_from_failure( ch, skill_space_combat_1 );
            snprintf( buf, MSL, "A thick green beam streaks out from %s, barely missing %s.", ship->name, target->name );
            echo_to_system_noqueue( AT_GREEN, ship, buf, target );
            return;
        }

        snprintf( buf, MSL, "A thick green beam streaks out from %s, colliding with %s!", ship->name, target->name );
        echo_to_system_noqueue( AT_GREEN, ship, buf, target );
        snprintf( buf, MSL, "A thick green beam from %s &R~SURGES~&G towards your vessel...", ship->name );
        echo_to_ship_windows( AT_GREEN, target, buf );
        snprintf( buf, MSL, "A thick green beam streaks out from your ship, colliding with %s!", target->name );
        echo_to_ship_windows( AT_GREEN, ship, buf );
        learn_from_success( ch, skill_space_combat_1 );
        learn_slow( ch, skill_space_combat_2, 4 );
        learn_slow( ch, skill_space_combat_3, 5 );
        damage_ship( target, 1000, 5000, ch, ship );
        echo_to_ship_main( AT_RED, target, "HUGE explosions jostle the entire ship!" );
        ai_anger( target, ship, FALSE );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "turbolasers" ) )
    {
        fire_ship_turbolaser( ship, ch, target );
        return;
    }

    /*
        Autoblasters are unique form of laser.
        They make 3 hit checks when fired, So You're almost
        always going to score a hit. Damage from 3 direct hits
        is a little more than a standard laser shot.
    */
    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "autoblasters" ) )
    {
        fire_ship_autoblaster( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "magnetic" ) )
    {
        if ( ship->mines[MAGNETIC_MINE] < 1 )
        {
            ch_println( ch, "&RThere are no magnetic mines onboard this ship!" );
            return;
        }

        if ( ship->currspeed > 10 )
        {
            ch_println( ch, "&RYour moving too fast to deploy mines! Must be under 10 units." );
            return;
        }

        ship_start_fighting( ship, NULL );
        echo_to_ship_main( AT_ORANGE, ship, "The ship shudders as something bulky is ejected from it." );
        echo_to_ship_windows( AT_ORANGE, ship, "With a loud *WHUUMP* a mine is jettisoned from the ship's hangar!" );
        snprintf( buf, MSL, "A Mine suddenly appears from %s's hangar!.", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, target );
        ship->mines[MAGNETIC_MINE]--;
        new_mine( ship, ch, MAGNETIC_MINE );
        ch_println( ch, "&GMine Deployed. It will be fully armed in 20 seconds." );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "proximity" ) )
    {
        if ( ship->mines[PROXIMITY_MINE] < 1 )
        {
            ch_println( ch, "&RThere are no proximity mines onboard this ship!" );
            return;
        }

        if ( ship->currspeed > 10 )
        {
            ch_println( ch, "&RYour moving too fast to deploy mines! Must be under 10 units." );
            return;
        }

        ship_start_fighting( ship, NULL );
        echo_to_ship_main( AT_ORANGE, ship, "The ship shudders as something bulky is ejected from it." );
        echo_to_ship_windows( AT_ORANGE, ship, "With a loud *WHUUMP* a mine is jettisoned from the ship's hangar!" );
        snprintf( buf, MSL, "A Mine suddenly appears from %s's hangar!.", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, target );
        ship->mines[PROXIMITY_MINE]--;
        new_mine( ship, ch, PROXIMITY_MINE );
        ch_println( ch, "&GMine Deployed. It will be fully armed in 20 seconds." );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "seeker" ) )
    {
        if ( ship->mines[SEEKER_MINE] < 1 )
        {
            ch_println( ch, "&RThere are no seeker mines onboard this ship!" );
            return;
        }

        if ( ship->currspeed > 10 )
        {
            ch_println( ch, "&RYour moving too fast to deploy mines! Must be under 10 units." );
            return;
        }

        ship_start_fighting( ship, NULL );
        echo_to_ship_main( AT_ORANGE, ship, "The ship shudders as something bulky is ejected from it." );
        echo_to_ship_windows( AT_ORANGE, ship, "With a loud *WHUUMP* a mine is jettisoned from the ship's hangar!" );
        snprintf( buf, MSL, "A Mine suddenly appears from %s's hangar!.", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, target );
        ship->mines[SEEKER_MINE]--;
        new_mine( ship, ch, SEEKER_MINE );
        ch_println( ch, "&GMine Deployed. It will be fully armed in 20 seconds." );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "ion" ) )
    {
        fire_ship_ion( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "missile" ) )
    {
        fire_ship_missile( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "torpedo" ) )
    {
        fire_ship_torpedo( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "rocket" ) )
    {
        fire_ship_rocket( ship, ch, target );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "pulse" ) )
    {
        fire_ship_pulse( ship, ch, target );
        return;
    }

    /*
        Burst firing: A New fighter modification
    */
    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "burst" ) )
    {
        if ( !IS_SET( ship->mod_flags, MOD_BURSTFIRE ) )
        {
            ch_println( ch, "&RThis ship does not support burst fire. Sorry!" );
            return;
        }

        if ( ship->missilestate >= MISSILE_DAMAGED )
        {
            ch_println( ch, "&RThe ship's missile launchers are %s.", ship->missilestate == MISSILE_DESTROYED ? "destroyed" : "damaged" );
            return;
        }

        if ( ship->missiles < 2 )
        {
            ch_println( ch, "&RYou must have atleast 2 missiles to fire!" );
            return;
        }

        if ( ship->missilestate != MISSILE_READY && ship->spent_tubes >= ship->missiletubes )
        {
            ch_println( ch, "&RThe missile tubes are still reloading." );
            return;
        }

        if ( dist > 1250 )
        {
            ch_println( ch, "&RThat ship is out of missile range." );
            return;
        }

        if ( ship->classtype < CORVETTE_SHIP && !is_facing( ship, target ) )
        {
            ch_println( ch, "&RMissiles can only fire forwards. You'll need to turn your ship!" );
            return;
        }

        if ( target->safe_orbital )
        {
            ch_println( ch, "&RThat target may not currently be attacked per HELP CAPITAL RULES." );
            return;
        }

        ship_start_fighting( ship, target );
        double base_chance = standard_ship_hit_chance( ch );
        double class_mod = UMIN( 60 + target->classtype * 8, 100 ) / 100.0;
        double hit_percent = 100 * base_chance * class_mod;
        tune( "hit_percent for dual missile: %s has %.1f%% chance to hit %s", ship->name, hit_percent, target->name );
        ship->spent_tubes += 2;

        if ( number_percent() > hit_percent || ship_dodge( target, ship, false ) )
        {
            ch_println( ch, "&RYou fail to lock on to your target!" );

            if ( ship->missilestate == MISSILE_READY )
                ship->missilestate = MISSILE_RELOAD_2;

            return;
        }

        ship->missiles -= 2;
        act( AT_PLAIN, "$n presses the 'DUAL FIRE' button.", ch, NULL, argument, TO_ROOM );
        add_queue( target, SQUEUE_MISSILE_LAUNCH, 0, 0, ch, ship );
        cache_skill( "weapon systems", &skill_weapon_systems );
        learn_from_success( ch, skill_weapon_systems );

        if ( ship->classtype >= CRUISER_SHIP )
            ship->missilestate = MISSILE_RELOAD;
        else
            ship->missilestate = MISSILE_FIRED;

        ai_anger( target, ship, FALSE );
        return;
    }

    if ( ch->in_room->vnum == ship->gunseat && !str_prefix( argument, "barrage" ) )
    {
        if ( !IS_SET( ship->mod_flags, MOD_BARRAGE ) )
        {
            ch_println( ch, "&RThis ship does not support rocket barrage. Sorry!" );
            return;
        }

        if ( ship->missilestate >= MISSILE_DAMAGED )
        {
            ch_println( ch, "&RThe ship's missile launchers are %s.", ship->missilestate == MISSILE_DESTROYED ? "destroyed" : "damaged" );
            return;
        }

        if ( ship->rockets < ROCKET_BARRAGE_REQ )
        {
            ch_println( ch, "&RYou do not have the required 25 rockets to enact a barrage!" );
            return;
        }

        if ( ( ship->missilestate != MISSILE_READY && ship->spent_tubes >= ship->missiletubes ) || ship->missiletubes - ship->spent_tubes < ROCKET_BARRAGE_REQ )
        {
            ch_println( ch, "&RThe missile tubes are still reloading." );
            return;
        }

        if ( dist > 1000 )
        {
            ch_println( ch, "&RThat ship is out of rocket range." );
            return;
        }

        if ( ship->classtype < CORVETTE_SHIP && !is_facing( ship, target ) )
        {
            ch_println( ch, "&RRockets can only fire forwards. You'll need to turn your ship!" );
            return;
        }

        if ( target->safe_orbital )
        {
            ch_println( ch, "&RThat target may not currently be attacked per HELP CAPITAL RULES." );
            return;
        }

        ship_start_fighting( ship, target );
        double base_chance = standard_ship_hit_chance( ch );
        double class_mod = UMIN( 40 + target->classtype * 10, 100 ) / 100.0;
        double hit_percent = 100 * base_chance * class_mod;
        tune( "hit_percent for rocket barrage: %s has %.1f%% chance to hit %s", ship->name, hit_percent, target->name );
        ship->spent_tubes += ROCKET_BARRAGE_REQ;

        if ( number_percent() > hit_percent || ship_dodge( target, ship, false ) )
        {
            ch_println( ch, "&RYou fail to lock on to your target!" );

            if ( ship->missilestate == MISSILE_READY )
                ship->missilestate = MISSILE_RELOAD_2;

            return;
        }

        act( AT_PLAIN, "$n presses the fire button.", ch, NULL, argument, TO_ROOM );
        echo_to_ship_windows( AT_YELLOW, ship, "Rocket barrage launched." );
        learn_from_success( ch, cache_skill( "weapon systems", &skill_weapon_systems ) );
        ship->rockets -= ROCKET_BARRAGE_REQ;

        for ( i = 0; i < ROCKET_BARRAGE_REQ; i++ )
            add_queue( target, SQUEUE_ROCKET_LAUNCH, 0, 0, ch, ship );

        if ( ship->classtype >= CRUISER_SHIP )
            ship->missilestate = MISSILE_RELOAD;
        else
            ship->missilestate = MISSILE_FIRED;

        ai_anger( target, ship, FALSE );
        return;
    }

    /*
        New Turret firing Code (Support for multiable turrets)
        Coded by Ghost
    */
    if ( !turret )
    {
        ch_println( ch, "&RYou can't fire from here!" );
        return;
    }

    if ( !str_prefix( argument, "lasers" ) )
    {
        fire_ship_laser_turret( ship, ch, turret );
        return;
    }

    if ( !str_prefix( argument, "autoblasters" ) )
    {
        fire_ship_autoblaster_turret( ship, ch, turret );
        return;
    }

    if ( !str_prefix( argument, "ion" ) )
    {
        fire_ship_ion_turret( ship, ch, turret );
        return;
    }

    if ( !str_prefix( argument, "turbolasers" ) )
    {
        fire_ship_turbolaser_turret( ship, ch, turret );
        return;
    }

    ch_println( ch, "&RYou can't fire that!" );
    return;
}

// Line intersection math copied from http://www.jeffreythompson.org/collision-detection/line-line.php
// Returns true if two lines intersect at any point, false if not.
// Line 1: (x1,y1) - (x2,y2)
// Line 2: (x3,y3) - (x4,y4)
bool lines_intersect( long double x1, long double y1, long double x2, long double y2,
                      long double x3, long double y3, long double x4, long double y4 )
{
    // calculate the distance to intersection point
    long double uA = ( ( x4 - x3 ) * ( y1 - y3 ) - ( y4 - y3 ) * ( x1 - x3 ) ) / ( ( y4 - y3 ) * ( x2 - x1 ) - ( x4 - x3 ) * ( y2 - y1 ) );
    long double uB = ( ( x2 - x1 ) * ( y1 - y3 ) - ( y2 - y1 ) * ( x1 - x3 ) ) / ( ( y4 - y3 ) * ( x2 - x1 ) - ( x4 - x3 ) * ( y2 - y1 ) );

    // if uA and uB are between 0-1, lines are colliding
    if ( uA >= 0 && uA <= 1 && uB >= 0 && uB <= 1 )
    {
        return true;
    }

    return false;
}

// Line intersection math copied from http://www.jeffreythompson.org/collision-detection/line-line.php
// Returns true if the given line (x1,y1) - (x2,y2) intersects with the given rectangle.
// The lower left corner of the rectangle is passed as (rx,ry), and it extends rw to the right (+x) and rh up (+y)
bool line_intersects_rect( long double x1, long double y1, long double x2, long double y2,
                           long double rx, long double ry, long double rw, long double rh )
{
    // check if the line has hit any of the rectangle's sides
    // uses the Line/Line function below
    bool left =   lines_intersect( x1, y1, x2, y2,  rx, ry, rx,  ry + rh );
    bool right =  lines_intersect( x1, y1, x2, y2,  rx + rw, ry,  rx + rw, ry + rh );
    bool top =    lines_intersect( x1, y1, x2, y2,  rx, ry,     rx + rw, ry );
    bool bottom = lines_intersect( x1, y1, x2, y2,  rx, ry + rh,  rx + rw, ry + rh );

    // if ANY of the above are true, the line
    // has hit the rectangle
    if ( left || right || top || bottom )
    {
        return true;
    }

    return false;
}

bool hyperwall_blocked( SPACE_DATA* origin, int dest_x, int dest_y, int shipclass )
{
    if ( !origin )
        return FALSE;

    for ( HYPERWALL_DATA* hyperwall = first_hyperwall; hyperwall; hyperwall = hyperwall->next )
    {
        if ( !hyperwall->enabled )
            continue;

        if ( lines_intersect( origin->xpos, origin->ypos, dest_x, dest_y, hyperwall->x1, hyperwall->y1, hyperwall->x2, hyperwall->y2 ) )
            if ( shipclass < hyperwall->minship || shipclass > hyperwall->maxship )
                return TRUE;
    }

    return FALSE;
}

bool is_valid_jump( CHAR_DATA* ch, SHIP_DATA* ship, int dest_x, int dest_y, int exit_x, int exit_y, int exit_z )
{
    if ( !ship->starsystem )
    {
        ch_println( ch, "&RYou're not in space!" );
        return false;
    }

    SPACE_DATA* dest_sys = starsystem_from_coords(dest_x, dest_y);
    if ( dest_sys )
    {
        if ( dest_sys->maxshipclass < ship->classtype )
        {
            ch_println( ch, "&RThat location is too riddled with debris for your ship to safely jump into that sector!&w" );
            return false;
        }

        if ( dest_sys->nocaps && ship->classtype >= FRIGATE_SHIP )
        {
            ch_println( ch, "&RThat location is too riddled with debris for your ship to safely jump into that sector!&w" );
            return false;
        }

        if ( dest_sys->nohyper )
        {
            ch_println( ch, "&RThat system can't be safely navigated to." );
            return false;
        }

        Vector3 exit_point = {exit_x, exit_y, exit_z};
        for ( PLANET_DATA* planet = dest_sys->first_planet; planet; planet = planet->next_in_system )
        {
            if ( vector_distance( &exit_point, &planet->pos ) < 500 )
            {
                echo_to_ship_windows( AT_RED, ship, "[Alert]: Jump coordinates too close to stellar object. Jump not set." );
                return false;
            }
        }
    }

    if ( hyperwall_blocked( ship->starsystem, dest_x, dest_y, ship->classtype ) )
    {
        ch_println( ch, "&RWarning: Systems detect interference on that hyperspace route. Jump calculation failed." );
        return false;
    }

    return true;
}

bool has_navchart( SHIP_DATA* ship, char* name )
{
    NAVCHART_DATA* chart = NULL;

    if ( !ship || NULLSTR( name ) )
        return false;

    for ( chart = ship->first_navchart; chart; chart = chart->next )
        if ( !str_cmp( chart->name, name ) )
            return true;

    return false;
}

// Gets "galactic coordinates" for a given point in a given system x/y.
// This acts as if 0, 0, 0 in system 0, 0 is the center of the galaxy and each system
// is 100,000 units wide, giving you coordinates which we can use to represent any point
// in any system.
Vector3 galactic_coords( int sys_x, int sys_y, int x, int y, int z )
{
    Vector3 result = {
        .x = (sys_x * 100000) + x,
        .y = (sys_y * 100000) + y,
        .z = z
    };
    return result;
}

Vector3 system_galactic_coords( SPACE_DATA* starsystem, int x, int y, int z )
{
    return galactic_coords(starsystem->xpos, starsystem->ypos, x, y, z);
}

Vector3 ship_galactic_coords( SHIP_DATA* ship )
{
    Vector3 zero = {0,0,0};
    if ( !ship )
        return zero;

    if ( ship->shipstate == SHIP_HYPERSPACE )
        return ship->hyper_currentpos;

    if ( !ship->starsystem )
        return zero;

    return system_galactic_coords(ship->starsystem, ship->vpos.x, ship->vpos.y, ship->vpos.z);
}

// Returns the distance between two galactic coordinates as parsecs (a system is 1 parsec wide)
float hyper_distance( Vector3 from, Vector3 to )
{
    return vector_distance(&from, &to) / 100000.0;
}

// Returns how many parsecs a given ship can move per second in hyperspeed
float ship_parsecs_per_second( SHIP_DATA* ship )
{
    float hyper_coords_per_sec = (ship->hyperspeed + ship->hyperbonus) * 200;
    return hyper_coords_per_sec / 100000.0; // 1 parsec = 1 system width
}

// Returns how many seconds it'll take for the given ship to travel the given number of parsecs
float ship_hyperjump_seconds( SHIP_DATA* ship, float parsecs )
{
    return parsecs / ship_parsecs_per_second( ship ) + 6; // Add the hyperspace exit delay
}

const char* jumptime( SHIP_DATA* ship, float parsecs )
{
    static char result[100];
    int jump_seconds = ceil(ship_hyperjump_seconds(ship, parsecs) / 2) * 2;
    if ( jump_seconds/60 == 0 )
        snprintf(result, 100, "%02ds", jump_seconds );
    else
        snprintf(result, 100, "%dm %02ds", jump_seconds/60, jump_seconds%60 );
    return result;
}

// Returns how much fuel a ship uses each second while in hyperspace.
int ship_hyperjump_fuel_per_second( SHIP_DATA* ship )
{
    return floor(25.0 / 3 * (ship->classtype + 1)); // A little arbitrary but this matches the prior logic.
}

int ship_hyperjump_fuel_cost( SHIP_DATA* ship, Vector3 to )
{
    float parsecs = hyper_distance( ship_galactic_coords(ship), to );
    // Subtract 6, we don't consume fuel during the hyperspace exit delay.
    return ship_hyperjump_fuel_per_second(ship) * (ship_hyperjump_seconds(ship, parsecs) - 6);
}

SPACE_DATA* system_from_galactic_coords( Vector3 coords )
{
    int sys_x = sys_coord_from_galactic_coords(coords.x);
    int sys_y = sys_coord_from_galactic_coords(coords.y);
    return starsystem_from_coords(sys_x, sys_y);
}

// Returns the right system X/Y value given a galactic X or Y coordinate.
// It's a simple calculation, but better here than scattered all over the codebase.
int sys_coord_from_galactic_coords( double gal_coord )
{
    return round(gal_coord / 100000);
}

bool ship_knows_system( SHIP_DATA* ship, SPACE_DATA* starsystem )
{
    if ( !starsystem->hidden )
        return true;
    if ( ship->squadleader && ship->squadleader != ship )
        return ship_knows_system( ship->squadleader, starsystem );
    if ( starsystem->virtualsys )
        return false;
    if ( has_navchart( ship, starsystem->name ) )
        return true;
    return false;
}

CMDF do_calculate( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    int chance = 0, count = 0, fcost = 0;
    double perc = 0;
    SHIP_DATA* ship = NULL;
    int max;
    SPACE_DATA* starsystem = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ( ship = get_ship_from_navseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be at a nav computer to calculate jumps." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first..." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP  )
    {
        if ( xIS_SET( ship->flags, SHIP_ONEHYPER ) && ship->hyperspeed == 0 )
        {
            ch_println( ch, "&RAnd what exactly are you going to calculate?" );
            return;
        }
    }

    if ( ship->hyperspeed == 0 )
    {
        ch_println( ch, "&RThis ship is not equipped with a hyperdrive!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED || ship->dockship )
    {
        ch_println( ch, "&RNot while docked with another ship!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYour navcomputer cannot obtain the calculation power necessary with the cloaking generator engaged." );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can only do that in realspace." );
        return;
    }

    if ( ship->energy <= 0 )
    {
        ch_println( ch, "&RYou're out of fuel!" );
        return;
    }

    if ( ship->calctimer > 0 )
    {
        if ( !str_cmp( arg1, "stop" ) )
        {
            ch_println( ch, "&w&R[ALERT]: Aborting Hyperspace calculation. Terminal reset." );
            ship->calctimer = 0;
            ship->hyperlock = FALSE;
            return;
        }

        ch_println( ch, "&zCalculating Hyperspace Trajectory: &C%d seconds remaining.", ship->calctimer );
        ch_println( ch, "&zUse &WCALC STOP&z to abort the sequence." );
        return;
    }

    xREMOVE_BIT( ship->flags, SHIP_MATCHVECTOR ); // Double safety   Orion 2008

    if ( has_feat( ch, cache_skill( "navigator", &skill_navigator ) ) )
    {
        ch_println( ch, "Using your skill with navigation you reroute energy to the hyperdrives." );
        ship->hyperbonus = ship->hyperspeed * 0.3;
    }
    else
    {
        ship->hyperbonus = 0;
    }

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&wPossible destinations:" );
        ch_println( ch, "&W%-30s  %7s  %7s  %4s", "Starsystem", "Parsecs", "Time  ", "Fuel" );
        for ( starsystem = first_starsystem; starsystem; starsystem = starsystem->next )
        {
            if ( starsystem->virtualsys )
                continue;

            if ( ( !ship_knows_system(ship, starsystem) || starsystem->notpublic ) && !IS_IMMORTAL( ch ) )
                continue;

            float parsecs = hyper_distance( 
                ship_galactic_coords(ship),
                system_galactic_coords( starsystem, 0, 0, 0 )
            );
            int fuel_cost = ship_hyperjump_fuel_cost(ship, system_galactic_coords( starsystem, 0, 0, 0 ));

            if ( hyperwall_blocked( ship->starsystem, starsystem->xpos, starsystem->ypos, ship->classtype ) || ( starsystem->nocaps > 0 && ship->classtype >= FRIGATE_SHIP ) )
                ch_println( ch, "&R%-30s  %7.1f                 (No Path)", starsystem->name, parsecs );
            else if ( fuel_cost > ship->energy )
                ch_println( ch, "&R%-30s  %7.1f                 (Out of Range)", starsystem->name, parsecs );
            else
                ch_println( ch, "&G%-30s  %7.1f  %7s  %3d%%", starsystem->name, parsecs, jumptime(ship, parsecs), (fuel_cost * 100) / ship->energy );

            count++;
        }

        if ( !count )
            ch_println( ch, "No starsystems found." );

        ch_println( ch, "\n&zSyntax: &Ccalculate <&wsystem name&C>&z             - Jump near a planet in the system" );
        ch_println( ch, "        &Ccalculate <&wsystem name&C> <&wx&C> <&wy&C> <&wz&C>&z - Jump to specific coordinates" );
        ch_println( ch, "        &Ccalculate <&wsystem name&C> random&z      - Jump to random coordinates" );
        ch_println( ch, "&zUse &C'<&wsystem x&C> <&wsystem y&C>'&z as the name for uncharted systems (include quotes)." );

        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "navigation", &skill_navigation ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't seem to figure the charts out today." );
        learn_from_failure( ch, cache_skill( "navigation", &skill_navigation ) );
        return;
    }

    int jump_sys_x;
    int jump_sys_y;
    if ( !str_cmp( arg1, "local" ) )
    {
        jump_sys_x = ship->starsystem->xpos;
        jump_sys_y = ship->starsystem->ypos;
    }
    else
    {
        jump_sys_x = get_coord(arg1, 1);
        jump_sys_y = get_coord(arg1, 2);
        if ( jump_sys_x == INT_MIN || jump_sys_y == INT_MIN )
        {
            SPACE_DATA* starsys = starsystem_from_name( arg1 );
            if ( !starsys || ( !IS_IMMORTAL(ch) && !ship_knows_system(ship, starsys) ) )
            {
                ch_println( ch, "&RCould not locate destination system in your nav computer." );
                return;
            }
            jump_sys_x = starsys->xpos;
            jump_sys_y = starsys->ypos;
        }
    }

    int exit_x = 0, exit_y = 0, exit_z = 0;
    if ( NULLSTR( argument ) )
    {
        PLANET_DATA* exit_planet = NULL;
        SPACE_DATA* exit_system = starsystem_from_coords(jump_sys_x, jump_sys_y);
        if ( exit_system )
        {
            for ( PLANET_DATA* planet = exit_system->first_planet; planet; planet = planet->next_in_system )
            {
                if ( xIS_SET( planet->flags, PLANET_STAR ) )
                    continue;
                if ( !exit_planet || exit_planet->population < planet->population )
                    exit_planet = planet;
            }
        }

        if ( exit_planet && ship_knows_system(ship, exit_system) && str_cmp( arg2, "random" ) )
        {
            Vector3 exit_randvector = {
                .x = number_range( -1000, 1000 ),
                .y = number_range( -1000, 1000 ),
                .z = number_range( -1000, 1000 )
            };
            vector_normalize( &exit_randvector );
            // To avoid integer rounding causing us to be too close to the planet, pad our 500 distance a little bit.
            exit_x = exit_planet->pos.x + 503 * exit_randvector.x;
            exit_y = exit_planet->pos.y + 503 * exit_randvector.y;
            exit_z = exit_planet->pos.z + 503 * exit_randvector.z;
            ch_println( ch, "&YNo exit coordinates specified. Random coordinates near planet %s chosen: %d %d %d", exit_planet->name, exit_x, exit_y, exit_z );
        }
        else
        {
            exit_x = number_range( -49999, 49999 );
            exit_y = number_range( -49999, 49999 );
            exit_z = number_range( -49999, 49999 );
            ch_println( ch, "&YNo exit coordinates specified. Random destination chosen: %d %d %d", exit_x, exit_y, exit_z );
        }
    }
    else
    {
        exit_x = atoi( arg2 );
        exit_y = atoi( arg3 );
        exit_z = atoi( argument );

        max = 49999;
        if ( exit_x > max || exit_x < -max || exit_y > max || exit_y < -max || exit_z > max || exit_z < -max )
        {
            ch_println( ch, "&RThe coordinates must be within -%d and %d.", max, max );
            return;
        }
    }

    if ( !is_valid_jump( ch, ship, jump_sys_x, jump_sys_y, exit_x, exit_y, exit_z ) )
        return;

    Vector3 hyper_exit = galactic_coords(jump_sys_x, jump_sys_y, exit_x, exit_y, exit_z);
    sound_to_room( ch->in_room, "computer" );
    ch_println( ch, "&GHyperspace course locked. Running final jump checks..." );

    fcost = ship_hyperjump_fuel_cost( ship, hyper_exit );
    if ( fcost > ship->energy )
    {
        ch_println( ch, "&RWarning - Not enough fuel to complete the jump!" );
        ch_println( ch, "&RJump requires %d units of fuel. You only have %d.", fcost, ship->energy );
    }
    else
    {
        if ( ship->energy > 0 )
            perc = ( ( ( double )( fcost ) / ( double )( ship->energy ) ) * 100 );

        ch_println( ch, "&CJump requires %d units of fuel. It will consume %.0f%% of the remaining fuel.", fcost, perc );

        if ( ship->classtype == BATTLESTATION_SHIP )
        {
            ch_println( ch, "&R[ALERT]: Upon exiting hyperspace, the vessel will be" );
            ch_println( ch, "  disabled for several seconds while the systems recalibrate." );
        }

        ch_println( ch, "&GChecking hyperspace course integrity. Please wait." );
    }

    if ( is_squadleader( ship ) )
    {
        for ( SHIP_DATA* sq = ship->first_in_squad; sq; sq = sq->next_in_squad )
        {
            if ( sq->starsystem != ship->starsystem )
                continue;

            if ( !should_follow_squadleader( sq, ship ) )
                continue;

            if ( has_feat( ch, cache_skill( "navigator", &skill_navigator ) ) )
                sq->hyperbonus = sq->hyperspeed * 0.3;
            else
                sq->hyperbonus = 0;

            fcost = ship_hyperjump_fuel_cost( sq, hyper_exit );

            if ( fcost > sq->energy )
                message_to_squadleader( sq, "Heads up, I won't have the fuel for that jump." );
            else
                message_to_squadleader( sq, "Course locked in, waiting for your order to jump." );

            sq->hyper_exit = hyper_exit;
            sq->hyperlock = true;
            sq->calctimer = 0;
        }
    }

    act( AT_PLAIN, "$n starts some calculations using the navigation computer.", ch, NULL, argument, TO_ROOM );
    ship->hyper_exit = hyper_exit;
    float jump_seconds = ship_hyperjump_seconds(ship, hyper_distance(ship_galactic_coords(ship), hyper_exit));
    ship->calctimer = URANGE( 5, jump_seconds / 8, 60 );
    learn_from_success( ch, cache_skill( "navigation", &skill_navigation ) );
    return;
}

int get_coord( char* argument, int coord )
{
    char arg[MIL];
    int i = 0;

    for ( ; i < coord; i++ )
    {
        argument = one_argument( argument, arg );
    }

    if ( !is_number_sym( arg ) )
        return INT_MIN;

    return atoi( arg );
}

CMDF do_recharge( CHAR_DATA* ch, char* argument )
{
    int recharge = 0;
    int chance = 0;
    SHIP_DATA* ship = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ( ship = get_ship_from_coseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RThe controls must be at the co-pilot station." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_VONG ) )
    {
        ch_println( ch, "&RThis ship doesn't have conventional shielding." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RTake the ship off autopilot first!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship systems", &skill_ship_systems ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        return;
    }

    if ( ship->energy < 100 )
        ch_println( ch, "&RThere's not enough energy!" );
    else if ( ship->shield >= ship->maxshield )
        ch_println( ch, "&RThe shields are already at peak power." );
    else
    {
        ch_println( ch, "&GRecharging shields.." );
        act( AT_PLAIN, "$n pulls back a lever on the control panel.", ch, NULL, argument, TO_ROOM );
        learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        recharge = UMIN( ship->maxshield - ship->shield, ship->energy * 5 + 100 );
        recharge = URANGE( 0, recharge, 25 + ship->classtype * 25 );
        ship->shield += recharge;
        ship->energy -= ( recharge );
    }
}

int repairship_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are distracted and fail to finish your repairs." );
    return E_LOTJ_SUCCESS;
}

int repairship_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    char* arg = buffer->str1;

    if ( !valid_ship( ship ) )
    {
        ch_println( ch, "&RYou need to be on a ship to repair it!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !str_cmp( arg, "turret" ) )
    {
        TURRET_DATA* turret = get_turret_room( ship, ch->in_room );
        if ( turret )
        {
            int idx = 0;
            LINK_INDEXOF( ship->first_turret, TURRET_DATA, next, turret, idx );
            turret->laserstate = LASER_READY;
            ch_println( ch, "&GTurret %d repaired and ready.", idx );
        }
        else
        {
            ch_println( ch, "&GYou don't seem to be in a turret anymore." );
            return E_LOTJ_ASYNC_VALIDATION_FAILED;
        }
    }
    else
    {
        if ( !str_cmp( arg, "comm" ) )
        {
            if ( !xIS_SET( ship->flags, SHIP_COMM_DISABLED ) )
            {
                ch_println( ch, "&YThe comm system appears to be fully operational!" );
                return E_LOTJ_ASYNC_VALIDATION_FAILED;
            }
        }

        repair_ship_system( ship, arg, ch );
    }

    act( AT_PLAIN, "$n finishes the repairs.", ch, NULL, NULL, TO_ROOM );
    learn_from_success( ch, cache_skill( "ship maintenance", &skill_ship_maintenance ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_repairship( CHAR_DATA* ch, char* argument )
{
    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    OBJ_DATA* hydro = get_obj_carried_of_type( ch, ITEM_HYDROSPANNER );
    if ( !toolkit || !hydro )
    {
        ch_println( ch, "You will need a toolkit and hydrospanner to repair the ship." );
        return;
    }

    if ( str_cmp( argument, "drive" ) && str_cmp( argument, "engine" ) && str_cmp( argument, "launcher" ) && str_cmp( argument, "laser" )
            && str_cmp( argument, "ion" ) && str_cmp( argument, "turret" ) && str_cmp( argument, "cloak" )
            && str_cmp( argument, "fuel" ) && str_cmp( argument, "comm" ) && str_cmp( argument, "tractor" ) )
    {
        ch_println( ch, "&zSyntax: &Crepairship <&wsystem&C>            " );
        ch_println( ch, "&zShip Systems: --------                 " );
        ch_println( ch, "&C Fuel     &z - Halts a purge (sabotage)" );
        ch_println( ch, "&C Drive    &z - Repairs the engine drive" );
        ch_println( ch, "&C Engine   &z - Repairs the engine drive" );
        ch_println( ch, "&C Launcher &z - Repairs the launcher    " );
        ch_println( ch, "&C Laser    &z - Repairs the lasers      " );
        ch_println( ch, "&C Ion      &z - Repairs the ion cannons " );
        ch_println( ch, "&C Cloak    &z - Repairs the cloaking    " );
        ch_println( ch, "&C Turret   &z - Repairs a turret        " );
        ch_println( ch, "&C Comm     &z - Repairs the comm system " );
        ch_println( ch, "&C Tractor  &z - Repairs the tractor beam " );
        return;
    }

    SHIP_DATA* ship = get_ship_from_room( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "&RMight help if you were onboard a ship." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
    {
        ch_println( ch, "&RThere's nothing left around you to repair..." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) )
    {
        ch_println( ch, "&RThere is nothing to repair on your envirosuit." );
        return;
    }

    if ( !str_cmp( argument, "turret" ) )
    {
        TURRET_DATA* turret = get_turret_room( ship, ch->in_room );
        if ( !turret )
        {
            ch_println( ch, "&RYou need to be in a turret to repair it." );
            return;
        }

        if ( turret->laserstate == LASER_DESTROYED )
        {
            ch_println( ch, "&RThe turret has been destroyed. There's no fixing it." );
            return;
        }

        if ( turret->laserstate != LASER_DAMAGED )
        {
            ch_println( ch, "&RRepair an undamaged turret? Unlikely..." );
            return;
        }
    }
    else
    {
        if ( ch->in_room->vnum != ship->engineroom )
        {
            ch_println( ch, "&RYou must be in the engine room of a ship to do that!" );
            return;
        }
    }

    if ( !str_cmp( argument, "fuel" ) && ( !ship->tankpurge ) )
    {
        ch_println( ch, "&RYou can't repair the tanks, they are not being purged!" );
        return;
    }

    if ( !str_cmp( argument, "tractor" ) && ship->tractorstate != TRACTOR_DAMAGED )
    {
        if ( ship->tractorstate == TRACTOR_DESTROYED )
            ch_println( ch, "&RThe tractor beams have been destroyed. There's no fixing them." );
        else
            ch_println( ch, "&RYou can't repair the tractor beams. They are not damaged!" );
        return;
    }

    if ( ( !str_cmp( argument, "drive" ) || !str_cmp( argument, "engine" ) ) )
    {
        if ( ship->shipstate == SHIP_PERM_DISABLED )
        {
            ch_println( ch, "&RThis ship's drive is damaged beyond repair." );
            return;
        }

        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            ch_println( ch, "&RYou can't repair the ship's drive while in hyperspace!" );
            return;
        }
    }

    OBJ_DATA* transceiver = NULL;
    if ( !str_cmp( argument, "comm" ) )
    {
        transceiver = get_obj_carried_of_type( ch, ITEM_TRANSCEIVER );
        if ( !transceiver )
        {
            ch_println( ch, "&RYou need a space transceiver to fix the comm system!" );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
        {
            ch_println( ch, "&RThe comm system has been destroyed. There's no fixing it." );
            return;
        }

        if ( !xIS_SET( ship->flags, SHIP_COMM_DISABLED ) )
        {
            ch_println( ch, "&YThe comm system appears to be fully operational!" );
            return;
        }
    }

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship maintenance", &skill_ship_maintenance ) ) );
    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "\n&GYou begin your repairs on the ship." );
        action_set( ch, NULL, strfmt("is repairing the ship's %s.", argument), NULL, 0 );
        act( AT_PLAIN, "$n begins repairing the ship's $T.", ch, NULL, argument, TO_ROOM );

        int delay = 0;
        if ( !str_cmp( argument, "fuel" ) )
            delay = 5;

        if ( !str_cmp( argument, "drive" ) || !str_cmp( argument, "engine" ) )
            delay = 6;

        if ( !str_cmp( argument, "launcher" ) )
            delay = 10;

        if ( !str_cmp( argument, "laser" ) )
            delay = 5;

        if ( !str_cmp( argument, "tractor" ) )
            delay = 10;

        if ( !str_cmp( argument, "ion" ) )
            delay = 6;

        if ( !str_cmp( argument, "cloak" ) )
            delay = 15;

        if ( !str_cmp( argument, "turret" ) )
            delay = 10;

        if ( !str_cmp( argument, "comm" ) )
            delay = 80;

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, delay*3, repairship_complete, repairship_abort, FUNC );
        SET_STRING( timer->buffer->str1, argument );
        timer->buffer->ship = ship;
        add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
        add_obj_to_buffer( timer->buffer, "hydro", hydro );
        if ( transceiver )
            add_consumable_to_buffer( timer->buffer, "transceiver", transceiver, "Transceiver" );
        return;
    }

    ch_println( ch, "&RYou fail to locate the source of the problem." );
    learn_from_failure( ch, cache_skill( "ship maintenance", &skill_ship_maintenance ) );
}

// Returns true if the system name was valid, regardless of success.
bool repair_ship_system( SHIP_DATA* ship, const char* system_name, CHAR_DATA* ch )
{
    if ( !str_cmp( system_name, "fuel" ) )
    {
        ship->tankpurge = FALSE;

        if ( ch )
            ch_println( ch, "&GRepair complete...Fuel tank purge aborted." );

        return true;
    }
    else if ( !str_cmp( system_name, "drive" ) || !str_cmp( system_name, "engine" ) )
    {
        if ( ship->shipstate == SHIP_PERM_DISABLED )
        {
            if ( ch )
                ch_println( ch, "&RThis ship's drive is damaged beyond repair." );

            return true;
        }

        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            if ( ch )
                ch_println( ch, "&RYou can't repair the ship's drive while in hyperspace!" );

            return true;
        }

        if ( ship->location == ship->lastdoc )
            ship->shipstate = SHIP_DOCKED;
        else
            ship->shipstate = SHIP_READY;

        if ( ch )
            ch_println( ch, "&GShip's drive repaired." );

        return true;
    }
    else if ( !str_cmp( system_name, "launcher" ) )
    {
        if ( ship->missilestate == MISSILE_DESTROYED )
        {
            if ( ch )
                ch_println( ch, "&RThe missile launchers have been destroyed. There's no fixing them." );

            return true;
        }

        ship->missilestate = MISSILE_READY;
        ship->spent_tubes = 0;

        if ( ch )
            ch_println( ch, "&GMissile launcher repaired." );

        return true;
    }
    else if ( !str_cmp( system_name, "tractor" ) )
    {
        if ( ship->tractorstate == TRACTOR_DESTROYED )
        {
            if ( ch )
                ch_println( ch, "&RThe tractor beams have been destroyed. There's no fixing them." );

            return true;
        }

        ship->tractorstate = TRACTOR_READY;

        if ( ch )
            ch_println( ch, "&GTractor beam repaired." );

        return true;
    }
    else if ( !str_cmp( system_name, "cloak" ) )
    {
        if ( ship->cloakstatus == CLOAK_NONE )
        {
            if ( ch )
                ch_println( ch, "&GYou spend hours looking for your cloak but remember that you don't have one." );

            return true;
        }

        if ( ship->cloakstatus == CLOAK_DESTROYED )
        {
            if ( ch )
                ch_println( ch, "&RThe cloaking system has been destroyed. There's no fixing it." );

            return true;
        }

        if ( ship->cloakstatus == CLOAK_DAMAGED )
            ship->cloakstatus = CLOAK_READY;

        if ( ch )
            ch_println( ch, "&GCloaking device repaired." );

        return true;
    }
    else if ( !str_cmp( system_name, "laser" ) )
    {
        if ( ship->autoblaster_charge == LASER_DESTROYED || ship->laser_charge == LASER_DESTROYED || ship->turbolaser_charge == LASER_DESTROYED )
        {
            if ( ch )
                ch_println( ch, "&RThe laser systems have been destroyed. There's no fixing them." );

            return true;
        }

        ship->autoblaster_charge = ship->blasters;
        ship->laser_charge = ship->lasers;
        ship->turbolaser_charge = ship->turbolasers;

        if ( ch )
            ch_println( ch, "&GLaser systems repaired. Please wait for weapons to recharge." );

        return true;
    }
    else if ( !str_cmp( system_name, "ion" ) )
    {
        if ( ship->ion_charge == ION_DESTROYED )
        {
            if ( ch )
                ch_println( ch, "&RThe ion cannons have been destroyed. There's no fixing them." );

            return true;
        }
        ship->ion_charge = ship->ion;

        if ( ch )
            ch_println( ch, "&GIon cannons repaired. Please wait for cannons to recharge." );

        return true;
    }
    else if ( !str_cmp( system_name, "comm" ) )
    {
        if ( xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
        {
            if ( ch )
                ch_println( ch, "&RThe comm system has been destroyed. There's no fixing it." );

            return true;
        }

        if ( ch )
            ch_println( ch, "&GComm system repaired." );

        xREMOVE_BIT( ship->flags, SHIP_COMM_DISABLED );
        save_ship( ship, true );
        return true;
    }

    return false;
}

CMDF do_setcode( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    char arg2[MSL];
    char arg3[MSL];
    SHIP_DATA* ship = NULL;
    VEHICLE_DATA* vec = NULL;
    int ocode = 0, ncode = 0;
    bool random = FALSE;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        if ( ( vec = vehicle_from_cockpit( ch->in_room->vnum ) ) != NULL )
        {
            if ( arg1[0] == '\0' || arg2[0] == '\0' || arg3[0] == '\0' )
            {
                ch_println( ch, "&zSyntax: &CSETCODE <&wsystem&C> <&wold code&C> <&wnew code&C>\n" );
                ch_println( ch, "&zSystems: &BHATCH  &W- This code is required to open the vehicles hatch." );
                return;
            }

            ocode = atoi( arg2 );
            ncode = atoi( arg3 );

            if ( str_cmp( vec->owner, ch->name ) )
            {
                ch_println( ch, "&ROnly the owner may change the access code!" );
                return;
            }

            if ( ocode < 11111 || ocode > 99999 )
            {
                ch_println( ch, "&RInvalid code. Old code must be between 11111 and 99999." );
                return;
            }

            if ( ncode < 11111 || ncode > 99999 )
            {
                ch_println( ch, "&RInvalid code. New code must be between 11111 and 99999." );
                return;
            }

            if ( !str_cmp( arg1, "hatch" ) )
            {
                if ( vec->hatchcode != ocode )
                {
                    ch_println( ch, "&RThat's not the old hatch code!" );
                    return;
                }

                vec->hatchcode = ncode;
                ch_println( ch, "&GHatchway access code changed. Have a nice day." );
                save_vehicle( vec, true );
                return;
            }

            do_setcode( ch, "" );
        }

        ch_println( ch, "&RYou must be in the cockpit of a ship or vehicle to do that!" );
        return;
    }

    if ( arg1[0] == '\0' || arg2[0] == '\0' || arg3[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CSETCODE <&wsystem&C> <&wold code&C> <&wnew code&C>\n" );
        ch_println( ch, "&zSystems: &BHATCH  &W- This code is required to open the ship's hatch." );
        ch_println( ch, "&z         &BHANGAR &W- Required to open hangars remotely." );
        ch_println( ch, "&z         &BDOCK   &W- Required for another ship to dock with yours. " );
        ch_println( ch, "&z         &BSELFD  &W- Required to activate a ship's selfdestruct mechanism. " );
        return;
    }

    ocode = atoi( arg2 );

    if ( !str_cmp( arg3, "random" ) )
        random = TRUE;
    else
        ncode = atoi( arg3 );

    if ( str_cmp( ship->shipowner, ch->name ) && str_cmp( ship->pilot, ch->name ) )
    {
        if ( !check_clanpilot( ch, ship ) )
        {
            ch_println( ch, "&ROnly the owner/pilot may change access codes!" );
            return;
        }
    }

    if ( ocode < 11111 || ocode > 99999 )
    {
        ch_println( ch, "&RInvalid code. Old code must be between 11111 and 99999." );
        return;
    }

    if ( !random && ( ncode < 11111 || ncode > 99999 ) )
    {
        ch_println( ch, "&RInvalid code. New code must be between 11111 and 99999." );
        return;
    }

    if ( !str_cmp( arg1, "hatch" ) )
    {
        if ( ship->code[SCODE_HATCH] != ocode )
        {
            ch_println( ch, "&RThat's not the old hatch code!" );
            return;
        }

        if ( random )
            ship->code[SCODE_HATCH] = number_range( 11111, 99999 );
        else
            ship->code[SCODE_HATCH] = ncode;

        ch_println( ch, "&GHatchway access code changed. Have a nice day." );
        save_ship( ship, true );
        return;
    }
    else if ( !str_cmp( arg1, "hangar" ) )
    {
        if ( ship->code[SCODE_HANGAR] != ocode )
        {
            ch_println( ch, "&RThat's not the old hangar code!" );
            return;
        }

        if ( random )
            ship->code[SCODE_HANGAR] = number_range( 11111, 99999 );
        else
            ship->code[SCODE_HANGAR] = ncode;

        ch_println( ch, "&GHangar control code changed. Have a nice day." );
        save_ship( ship, true );
        return;
    }
    else if ( !str_cmp( arg1, "dock" ) )
    {
        if ( ship->code[SCODE_DOCK] != ocode )
        {
            ch_println( ch, "&RThat's not the old docking code!" );
            return;
        }

        if ( random )
            ship->code[SCODE_DOCK] = number_range( 11111, 99999 );
        else
            ship->code[SCODE_DOCK] = ncode;

        ch_println( ch, "&GDocking code changed. Have a nice day." );
        save_ship( ship, true );
        return;
    }
    else if ( !str_cmp( arg1, "selfd" ) )
    {
        if ( ship->code[SCODE_SELFD] != ocode )
        {
            ch_println( ch, "&RThat's not the old self-destruct code!" );
            return;
        }

        if ( random )
            ship->code[SCODE_SELFD] = number_range( 11111, 99999 );
        else
            ship->code[SCODE_SELFD] = ncode;

        ch_println( ch, "&GSelfdestruct code changed. Have a nice day." );
        save_ship( ship, true );
        return;
    }
    else
    {
        do_setcode( ch, "" );
        return;
    }

    return;
}

int refuel_abort( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* onship = on_ship( ch );
    bool mobile_refuel = ( buffer->ship && onship && buffer->ship == onship );
    if ( mobile_refuel )
    {
        ch_println( ch, "&RYou abort the fuel transfer and retrieve your fuel canister." );
        act( AT_ACTION, "$n closes the stop valve on $s fuel canister.", ch, NULL, NULL, TO_ROOM );
        WAIT_STATE( ch, 4 );
    }
    else
    {
        ch_println( ch, "&RYou abort the fuel transfer." );
        act( AT_ACTION, "$n closes the stop valve on $s fuel transfer.", ch, NULL, NULL, TO_ROOM );
        WAIT_STATE( ch, 4 );
    }
    return E_LOTJ_SUCCESS;
}

int refuel_complete_canister( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    if ( !valid_ship ( ship ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    OBJ_DATA* canister = get_obj_from_buffer( buffer, "canister" );

    // Refuel amount is capped at the lesser of 10% the fuel canister max capacity or 10% the ship's max fuel capacity
    int rfl = UMIN( (int)(canister->value[1] / 10), (int)(ship->maxenergy / 10) );

    // Refuel amount is capped at the lesser of the above or the amout remaining in the canister
    rfl = UMIN( rfl, canister->value[0] );

    // Refuel amount is capped at the lesser of the above or the amount of fuel still needed on the ship
    rfl = UMIN( rfl, ship->maxenergy - ship->energy );

    // Refuel and save the ship
    ship->energy = UMIN( ( ship->energy + rfl ), ship->maxenergy );
    save_ship( ship, true );

    // Decrement the canister's remaining fuel
    canister->value[0] = UMAX( canister->value[0] - rfl, 0 );
    ch_println( ch, "&wTransferred &C%'d&w unit%s of fuel.", rfl, rfl != 1 ? "s" : "" );
    learn_from_success( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) );

    if ( canister->value[0] <= 0 )
    {
        ch_println( ch, "&GYour fuel canister has depleted." );
        WAIT_STATE( ch, URANGE( 4, ( rfl / 1250 ), 12 ) );
        return E_LOTJ_SUCCESS;
    }
    if ( ship->energy >= ship->maxenergy )
    {
        ch_println( ch, "&GYou finish refueling the ship." );
        WAIT_STATE( ch, URANGE( 4, ( rfl / 1250 ), 12 ) );
        return E_LOTJ_SUCCESS;
    }

    int chance = IS_NPC( ch ) ? 0 : ( int ) ( get_learned_pct( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) ) );
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou trip up and the fuel transfer cuts off abruptly." );
        WAIT_STATE( ch, URANGE( 4, ( rfl / 1250 ), 12 ) );
        learn_from_failure( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) );
        return E_LOTJ_SUCCESS;
    }

    if ( canister->value[0] > 0 && ship->energy < ship->maxenergy )
    {
        ch_println( ch, "&GYou continue to refuel the ship..." );
        act( AT_ACTION, "$n continues to refuel the ship from a fuel canister.", ch, NULL, NULL, TO_ROOM );
        add_timer( ch, TIMER_DO_FUN, 30, refuel_complete_canister, refuel_abort, "do_refuel" );
    }
    return E_LOTJ_SUCCESS;
}

int refuel_complete_pad( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    if ( !valid_ship( ship ) || ship->in_room != ch->in_room )
    {
        ch_println( ch, "The ship you were refueling has disappeared." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int total_fuel = buffer->num1;
    int remaining_fuel = buffer->num2;
    int price = buffer->num3;
    int rfl = remaining_fuel;

    // Refuel amount is capped at 10% of the ship's max fuel capacity
    rfl = UMIN( rfl, (int)(ship->maxenergy / 10) );

    // Refuel amount is capped at the lesser of the above or the amount of fuel still needed on the ship
    rfl = UMIN( rfl, ship->maxenergy - ship->energy );

    int paid = (int)(((double)rfl / (double)total_fuel) * (double)price);

    // Refuel and save the ship
    ship->energy += rfl;
    save_ship( ship, true );

    SHIP_DATA* onship = get_ship_from_room( ch->in_room );
    PLANET_DATA* planet = on_planet( ch );
    if ( onship )
    {
        if ( onship->energy < rfl )
        {
            ch_println( ch, "&RThe ship you're own doesn't have enough fuel to transfer that much." );
            return E_LOTJ_ASYNC_VALIDATION_FAILED;
        }
        onship->energy -= rfl;
        save_ship( onship, true );
    }
    else
    {
        if ( planet && planet->governed_by && in_clan( ch ) != planet->governed_by )
        {
            int tax_kick = (int)( paid * planet->tax_rate / 100.0 ); // We cut off the tax
            planet->pending_taxes += floor( tax_kick ); // Pay the clan their taxes
            save_clan( planet->governed_by, true );
            paid += tax_kick;
        }

        if ( in_clan( ch ) && !str_cmp( ch->pcdata->clan->name, ship->shipowner ) )
        {
            mod_clan_funds( ch->pcdata->clan, ch, paid * -1, FUNC, NULL );
            ch_println( ch, "&GIt costs %s %'d credits to refuel the ship.", ch->pcdata->clan->name, paid );
        }
        else if ( str_cmp( ship->shipowner, "public" ) && str_cmp( ship->shipowner, "Public" ) && str_cmp( ship->shipowner, "Trainer" ) )
        {
            player_mod_funds( ch, paid * -1, FALSE, FUNC );
            ch_println( ch, "&GYou pay %'d credits to refuel the ship.", paid );
        }
    }

    ch_println( ch, "&wRefueled &C%'d&w unit%s of fuel.", rfl, rfl != 1 ? "s" : "" );
    if ( ship->energy >= ship->maxenergy )
    {
        ch_println( ch, "&GYou finish refueling the ship." );
        WAIT_STATE( ch, URANGE( 4, ( rfl / 1250 ), 12 ) );
    }
    else
    {
        ch_println( ch, "&GYou continue to refuel the ship..." );
        act( AT_ACTION, "$n continues to refuel the ship.", ch, NULL, NULL, TO_ROOM );
        add_timer( ch, TIMER_DO_FUN, 3, refuel_complete_pad, refuel_abort, "do_refuel" );
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_refuel( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL];
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( ch->fighting )
    {
        ch_println( ch, "You can't do that while you're fighting!" );
        return;
    }

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "&RYou can't figure out how to start the transfer process." );
        return;
    }

    SHIP_DATA* ship;
    SHIP_DATA* onship = get_ship_from_room( ch->in_room );

    bool mobile_refuel = ( onship && ch->in_room->vnum == onship->engineroom );
    if ( mobile_refuel )
        ship = onship;
    else
    {
        if ( NULLSTR( arg1 ) || ( !NULLSTR( arg2 ) && ( !is_number( arg2 ) && str_cmp( arg2, "full" ) ) ) )
        {
            ch_println( ch, "&zSyntax: &Crefuel <&wship&C>" );
            ch_println( ch, "&z        &Crefuel <&wship&C> <&wamount&C>" );
            ch_println( ch, "&z        &Crefuel &z- Refuel your current ship from within its engine room" );
            return;
        }

        ship = ship_in_room( ch->in_room, arg1 );
        if ( !ship )
        {
            ch_println( ch, "&RYou don't see that ship here." );
            return;
        }
    }

    // Make sure nobody else is refueling the same ship already.
    for ( CHAR_DATA* tch = ch->in_room->first_person; tch; tch = tch->next_in_room )
    {
        TIMER* timer = get_timerptr( tch, TIMER_DO_FUN );
        if ( !timer )
            continue;

        if ( !str_cmp( timer->buffer->func, "do_refuel" ) && timer->buffer->ship == ship )
        {
            ch_println( ch, "&RSomeone else is already refueling this ship!" );
            return;
        }
    }

    if ( ship->energy >= ship->maxenergy )
    {
        ch_println( ch, "&wThat ship is already fully fueled!" );
        return;
    }

    if ( mobile_refuel )
    {
        OBJ_DATA* canister = get_eq_char( ch, WEAR_HOLD );
        if ( !canister || canister->item_type != ITEM_FUEL_CANISTER || canister->value[1] <= 0 || canister->value[1] < canister->value[0] )
        {
            ch_println( ch, "&wYou need to be holding a fuel canister to refuel this ship from the inside." );
            if ( canister && canister->item_type == ITEM_FUEL_CANISTER && ( canister->value[1] <= 0 || canister->value[1] < canister->value[0] ) )
                bug( "Misconfigured fuel canister %s (%d)", canister->short_descr, canister->pIndexData ? canister->pIndexData->vnum : 0 );

            return;
        }

        if ( canister->value[0] <= 0 )
        {
            ch_println( ch, "&wYour fuel canister is empty." );
            return;
        }

        int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) ) );
        if ( number_percent( ) > chance )
        {
            ch_println( ch, "&RYou can't figure out how to start the transfer process." );

            if ( get_learned_pct( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) ) > 0 )
                learn_from_failure( ch, cache_skill( "mobile refuel", &skill_mobile_refuel ) );

            return;
        }

        ch_println( ch, "&GYou begin to refuel the ship..." );
        act( AT_ACTION, "$n connects a fuel canister to the intake port and begins refueling the ship.", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, "is refueling the ship.", NULL, 0 );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, refuel_complete_canister, refuel_abort, FUNC );
        timer->buffer->ship = ship;
        add_obj_to_buffer( timer->buffer, "canister", canister );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "You can't refuel platforms. They refuel themselves." );
        return;
    }

    if ( ship->classtype == BATTLESTATION_SHIP )
    {
        ch_println( ch, "You can't refuel battlestations. They refuel themselves." );
        return;
    }

    if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
    {
        ch_println( ch, "That ship is not docked right now." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_CAN_FLY ) && !onship )
    {
        ch_println( ch, "There are no fuel pumps here." );
        return;
    }

    int rfl;
    if ( !strcmp( arg2, "full" ) || NULLSTR( arg2 ) )
        rfl = ( ship->maxenergy - ship->energy );
    else if ( is_number( arg2 ) && atoi( arg2 ) > 0 )
        rfl = atoi( arg2 );

    if ( rfl > ship->maxenergy - ship->energy )
    {
        ch_println( ch, "&GYour tanks can only hold %d unit(s) of fuel.", ship->maxenergy - ship->energy );
        rfl = ship->maxenergy - ship->energy;
    }

    CLAN_DATA* ch_clan = in_clan( ch );
    if ( onship )
    {
        CLAN_DATA* onship_clan = onship->clan;
        CLAN_DATA* ship_clan = ship->clan;
        if ( onship_clan && (
            ( ch_clan && nifty_is_name( onship_clan->atwar, ch_clan->name ) ) ||
            ( ship_clan && nifty_is_name( onship_clan->atwar, ship_clan->name ) )
        ) )
        {
            ch_println( ch, "You're not authorized to use the fuel pumps on this ship!" );
            return;
        }

        int maxpump = ( int )( onship->maxenergy * .1 ) < 500 ? 500 : ( int )( onship->maxenergy * .1 );
        if ( onship->energy - rfl < maxpump )
        {
            ch_println( ch, "The ship you are on doesn't have enough fuel in its reserves!" );
            return;
        }
    }

    double pricemod = 1.0;
    switch ( ship->classtype )
    {
        case FIGHTER_SHIP:
            pricemod = 0.3;
            break;

        case TRANSPORT_SHIP:
            pricemod = 0.4;
            break;

        case FREIGHTER_SHIP:
            pricemod = 0.7;
            break;

        case GUNBOAT_SHIP:
            pricemod = 0.9;
            break;

        case CORVETTE_SHIP:
            pricemod = 1.3;
            break;

        case FRIGATE_SHIP:
            pricemod = 1.6;
            break;

        default:
            pricemod = 2.0;
            break;
    }

    int price = ( int )( ( double )rfl * ( double )pricemod );
    if ( price < 1000 )
        price = 1000;

    PLANET_DATA* planet = on_planet( ch );
    int tax_kick = 0;
    if ( !onship )
    {
        if ( planet && planet->governed_by && planet->governed_by != ch_clan )
        {
            tax_kick = (int)( price * planet->tax_rate / 100.0 ); // We cut off the tax
            price += tax_kick;
        }

        if ( ch_clan && !str_cmp( ch_clan->name, ship->shipowner ) )
        {
            if ( ch_clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough funds to refuel this ship.", ch_clan->name );
                return;
            }
        }
        else if ( str_cmp( ship->shipowner, "public" ) && str_cmp( ship->shipowner, "Public" ) && str_cmp( ship->shipowner, "Trainer" ) )
        {
            if ( ch->gold < price )
            {
                ch_println( ch, "&RYou don't have enough funds to refuel this ship." );
                return;
            }
        }
    }

    if ( ship->classtype >= FRIGATE_SHIP )
    {
        action_set( ch, NULL, "is refueling the ship.", NULL, 0 );
        ch_println( ch, "&GYou begin to refuel the ship..." );
        act( AT_ACTION, "$n connects a fuel line to the intake port and begins refueling $s ship.", ch, NULL, NULL, TO_ROOM );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 3, refuel_complete_pad, refuel_abort, FUNC );
        timer->buffer->ship = ship;
        timer->buffer->num1 = rfl;
        timer->buffer->num2 = rfl;
        timer->buffer->num3 = price - tax_kick; // This will be added back in the callback
        return;
    }

    if ( !onship )
    {
        if ( tax_kick > 0 )
        {
            planet->pending_taxes += floor( tax_kick ); // Pay the clan their taxes]
            save_clan( planet->governed_by, true );
        }

        if ( in_clan( ch ) && !str_cmp( ch_clan->name, ship->shipowner ) )
        {
            mod_clan_funds( ch_clan, ch, price * -1, FUNC, NULL );
            ch_println( ch, "&GIt costs %s %'d credits to refuel the ship.", ch_clan->name, price );
        }
        else if ( str_cmp( ship->shipowner, "public" ) && str_cmp( ship->shipowner, "Public" ) && str_cmp( ship->shipowner, "Trainer" ) )
        {
            player_mod_funds( ch, price * -1, FALSE, FUNC );
            ch_println( ch, "&GYou pay %'d credits to refuel the ship.", price );
        }
    }

    ch_println( ch, "&YShips fuel store increased by %d units.", rfl );

    if ( !IS_NPC( ch ) )
    {
        sql_credits_log( ch->name, FUNC, ( price - tax_kick ) * -1, TRUE );
        sql_credits_log( ch->name, FUNC, tax_kick * -1, FALSE );
    }

    if ( onship )
    {
        onship->energy -= rfl;
        save_ship( onship, true );
    }

    ship->energy += rfl;
    ship->shipstate = SHIP_DOCKED;
    act( AT_GREEN, "$n finishes refueling a ship.", ch, NULL, argument, TO_ROOM );
    WAIT_STATE( ch, URANGE( 4, ( rfl / 1250 ), 12 ) );
    save_ship( ship, true );
}

CMDF do_reload( CHAR_DATA* ch, char* argument )
{
    /*
        char buf[MSL];
    */
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    long price = 0;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* onship = NULL;
    int reload = 0;
    CLAN_DATA* clan = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' || arg3[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CRELOAD <&wship&C> <&wweapon&C> <&wamount&C>" );
        send_to_char( "&z Types: &BChaff     &z-   &C50 &zcredit(s) each.\n", ch );
        send_to_char( "&z        &BMissiles  &z-  &C250 &zcredit(s) each.\n", ch );
        send_to_char( "&z        &BTorpedoes &z-  &C500 &zcredit(s) each.\n", ch );
        send_to_char( "&z        &BRockets   &z- &C1000 &zcredit(s) each.\n", ch );
        send_to_char( "&z        &BPulses    &z- &C1500 &zcredit(s) each.\n", ch );
        return;
    }

    ship = ship_in_room( ch->in_room, arg1 );

    if ( ship == NULL )
    {
        ch_println( ch, "&RYou don't see that ship here!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThat isn't a spacecraft!" );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "You can't reload platforms. They reload themselves." );
        return;
    }

    if ( ship->classtype == BATTLESTATION_SHIP )
    {
        ch_println( ch, "You can't reload battlestations. They reload themselves." );
        return;
    }

    if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
    {
        ch_println( ch, "That ship is not docked right now." );
        return;
    }

    if ( str_cmp( arg2, "missiles" ) && str_cmp( arg2, "rockets" )
            && str_cmp( arg2, "torpedoes" ) && str_cmp( arg2, "chaff" ) && str_cmp( arg2, "pulses" ) )
    {
        send_to_char( "That's not a valid weapon type.\n", ch );
        return;
    }

    reload = atoi( arg3 );

    if ( reload < 0 )
    {
        ch_println( ch, "&RHow much do you want to restock?" );
        return;
    }

    onship = get_ship_from_room( ship->in_room );

    if ( onship != NULL )
    {
        if ( ( clan = onship->clan ) != NULL && nifty_is_name( ship->shipowner, clan->atwar ) )
        {
            ch_println( ch, "This ships clan is at war with your clan!" );
            return;
        }
    }

    if ( !str_cmp( arg2, "missiles" ) )
    {
        if ( reload > ship->maxmissiles - ship->missiles )
        {
            ch_println( ch, "&GYour ship can only hold %d missiles.", ship->maxmissiles - ship->missiles );
            reload = ship->maxmissiles - ship->missiles;
        }

        price += ( reload * 250 );

        if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
        {
            if ( ch->pcdata->clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough money to restock this ship.", ch->pcdata->clan->name );
                return;                
            }   
        }
        else if ( ch->gold < price )
        {
            ch_println( ch, "&RYou don't have enough money to restock this ship." );
            return;
        }

        ship->missiles += reload;
    }
    else if ( !str_cmp( arg2, "torpedoes" ) )
    {
        if ( reload > ship->maxtorpedoes - ship->torpedoes )
        {
            ch_println( ch, "&GYour ship can only hold %d torpedoes.", ship->maxtorpedoes - ship->torpedoes );
            reload = ship->maxtorpedoes - ship->torpedoes;
        }

        price += ( reload * 500 );

        if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
        {
            if ( ch->pcdata->clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough money to restock this ship.", ch->pcdata->clan->name );
                return;                
            }   
        }
        else if ( ch->gold < price )
        {
            ch_println( ch, "&RYou don't have enough money to restock this ship." );
            return;
        }

        ship->torpedoes += reload;
    }
    else if ( !str_cmp( arg2, "rockets" ) )
    {
        if ( reload > ship->maxrockets - ship->rockets )
        {
            ch_println( ch, "&GYour ship can only hold %d rockets.", ship->maxrockets - ship->rockets );
            reload = ship->maxrockets - ship->rockets;
        }

        price += ( reload * 1000 );

        if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
        {
            if ( ch->pcdata->clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough money to restock this ship.", ch->pcdata->clan->name );
                return;                
            }   
        }
        else if ( ch->gold < price )
        {
            ch_println( ch, "&RYou don't have enough money to restock this ship." );
            return;
        }

        ship->rockets += reload;
    }
    else if ( !str_cmp( arg2, "pulses" ) )
    {
        if ( reload > ship->maxpulses - ship->pulses )
        {
            ch_println( ch, "&GYour ship can only hold %d pulses.", ship->maxpulses - ship->pulses );
            reload = ship->maxpulses - ship->pulses;
        }

        price += ( reload * 1000 );

        if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
        {
            if ( ch->pcdata->clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough money to restock this ship.", ch->pcdata->clan->name );
                return;                
            }   
        }
        else if ( ch->gold < price )
        {
            ch_println( ch, "&RYou don't have enough money to restock this ship." );
            return;
        }

        ship->pulses += reload;
    }
    else if ( !str_cmp( arg2, "chaff" ) )
    {
        if ( reload > ship->maxchaff - ship->chaff )
        {
            ch_println( ch, "&GYour ship can only hold %d chaff.", ship->maxchaff - ship->chaff );
            reload = ship->maxchaff - ship->chaff;
        }

        price += ( reload * 50 );

        if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
        {
            if ( ch->pcdata->clan->funds < price )
            {
                ch_println( ch, "&R%s doesn't have enough money to restock this ship.", ch->pcdata->clan->name );
                return;                
            }   
        }
        else if ( ch->gold < price )
        {
            ch_println( ch, "&RYou don't have enough money to restock this ship." );
            return;
        }

        ship->chaff += reload;
    }
    else
    {
        do_reload( ch, "" );
        return;
    }

    if ( !clan_owned( ch, ship ) )
    {
        ch_println( ch, "&GYou pay %ld credits to restock the ship.", price );
        ch->gold -= price;
        if ( !IS_NPC( ch ) )
            sql_credits_log( ch->name, "do_reload", price * -1, TRUE );
    }
    else
    {
        sql_credits_log( ch->pcdata->clan->name, "do_reload", price * -1, TRUE );
        ch->pcdata->clan->funds -= price;
        ch_println( ch, "&G%s pays %ld credits to restock the ship.", ch->pcdata->clan->name, price );
    }

    act( AT_GREEN, "$n finishes reloading a ship.", ch, NULL, argument, TO_ROOM );
    return;
}

