            {
                if ( !str_cmp( ch->pcdata->clan->leader, ch->name ) )
                {
                }
                else if ( !str_cmp( ch->pcdata->clan->number1, ch->name ) )
                {
                }
                else if ( !str_cmp( ch->pcdata->clan->number2, ch->name ) )
                {
                }
                else
                {
                    send_to_char( "&RThat isn't your ship!", ch );
                    return;
                }
            }
            else
            {
                send_to_char( "&RThat isn't your ship!", ch );
                return;
            }
        }
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&RAdd which pilot?" );
        return;
