void rm_pilot_vec( VEHICLE_DATA* vec, char* arg, char* str )
{
    char name[MIL];
    char buf[MSL];
    int lp = 0;
    strlcpy( buf, "", MSL );

    if ( !arg || arg[0] == '\0' )
        return;

    for ( ;; )
    {
        if ( ++lp > 999 )
        {
            bug( "rm_pilot_vec: trapped in infinite loop, aborting." );
            return;
        }

        arg = one_argument( arg, name );

        if ( arg[0] == '\0' && name[0] == '\0' )
        {
            SET_STRING( vec->crew, buf );
            return;
        }
        else if ( str_cmp( name, str ) )
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), " %s", name );
    }
}

int count_args( char* argument )
{
    if ( argument == NULL )
        return 0;

    char* arg;
    arg = argument;
    return cnt_arg( arg, 0 );
}

int cnt_arg( char* argument, int cnt )
{
    if ( argument == NULL )
        return 0;

    char buf[MIL];
    argument = one_argument( argument, buf );

    if ( buf[0] == '\0' || cnt >= 250 )
        return cnt;

    return cnt_arg( argument, cnt + 1 );
}

