CMDF do_radar( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg[MIL];
    SHIP_DATA* target;
    int chance;
    SHIP_DATA* ship;
    MISSILE_DATA* missile;
    FCARGO_DATA* fcargo;
    MINE_DATA* mine;
    PLANET_DATA* planet;
    int cnt = 0;
    int max_distance = INT_MAX;
    bool printed_items;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    int mode = 0; // 0: ships

    if ( !NULLSTR( argument ) )
    {
        if ( is_number( argument ) )
            max_distance = atoi( argument );
        else
        {
            argument = one_argument( argument, arg );

            if ( !str_prefix( arg, "ships" ) )
                mode = 0;
            else if ( !str_prefix( arg, "projectiles" ) )
                mode = 1;
            else if ( !str_prefix( arg, "all" ) )
                mode = 2;
            else
            {
                ch_println( ch, "Invalid radar argument." );
                return;
            }

            if ( NULLSTR( argument ) )
                max_distance = INT_MAX;
            else if ( is_number( argument ) )
                max_distance = atoi( argument );
            else
            {
                ch_println( ch, "Invalid radar argument." );
                return;
            }
        }
    }

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit or turret of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RWait until after you launch!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "&RThe ship's communications array is completely fried!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't use the radar while cloaked!" );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can't do that unless the ship is flying in realspace!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "navigation", &skill_navigation ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, cache_skill( "navigation", &skill_navigation ) );
        return;
    }

    act( AT_PLAIN, "$n checks the radar.", ch, NULL, argument, TO_ROOM );
    set_char_color( AT_WHITE, ch );
    ch_println( ch, "%s\n", ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
    printed_items = false;
    set_char_color( AT_LBLUE, ch );


    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( vector_distance( &ship->vpos, &planet->pos ) > max_distance )
            continue;

        if ( xIS_SET( planet->flags, PLANET_STAR ) )
        {
            printed_items = true;
            ch_println( ch, "&Y(STAR) %-*s&Y   %.0f %.0f %.0f", ( 48 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name, planet->pos.x, planet->pos.y, planet->pos.z );
        }
    }

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( vector_distance( &ship->vpos, &planet->pos ) > max_distance )
            continue;

        if ( xIS_SET( planet->flags, PLANET_MOON ) )
        {
            printed_items = true;
            ch_println( ch, "&c%-*s&c   %.0f %.0f %.0f", ( 55 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name, planet->pos.x, planet->pos.y, planet->pos.z );
        }
    }

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( vector_distance( &ship->vpos, &planet->pos ) > max_distance )
            continue;

        if ( !xIS_SET( planet->flags, PLANET_STAR )  && !xIS_SET( planet->flags, PLANET_MOON ) )
        {
            printed_items = true;
            ch_println( ch, "&G%-*s&G   %.0f %.0f %.0f", ( 55 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name, planet->pos.x, planet->pos.y, planet->pos.z );
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;
    SHIP_DATA* tarnext;

    for ( target = ship->starsystem->first_ship; target; target = tarnext )
    {
        tarnext = target->next_in_starsystem;

        if ( target != ship && ( target->cloakstatus != CLOAK_ON || IS_IMMORTAL( ch ) ) )
        {
            if ( vector_distance( &ship->vpos, &target->vpos ) > max_distance )
                continue;

            printed_items = true;
            ch_println( ch, "%s%-55s%s   %s%.0f %.0f %.0f",
                       target->target0 == ship ? "&R" : "&B",
                       target->name,
                       target->target0 == ship && has_pcflag( ch, PCFLAG_SCREENREADER ) ? " (targeting you)" : "",
                       target->target0 == ship ? "&R" : "&C",
                       target->vpos.x, target->vpos.y, target->vpos.z );
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;

    for ( fcargo = ship->starsystem->first_fcargo; fcargo; fcargo = fcargo->next_in_starsystem )
    {
        cnt++;
        snprintf( buf, MSL, "Cargo pod %d", cnt );

        if ( vector_distance( &ship->vpos, &fcargo->pos ) > max_distance )
            continue;

        printed_items = true;
        ch_println( ch, "&R%-55s   &C%.0f %.0f %.0f", buf, fcargo->pos.x, fcargo->pos.y, fcargo->pos.z );
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;

    for ( mine = ship->starsystem->first_mine; mine; mine = mine->next_in_starsystem )
    {
        if ( vector_distance( &ship->vpos, &mine->pos ) > max_distance )
            continue;

        printed_items = true;
        ch_println( ch, "&R%-55s   &C%.0f %.0f %.0f",
                   mine->minetype == MAGNETIC_MINE ? "A Magnetic Mine" :
                   ( mine->minetype == PROXIMITY_MINE ? "A Proximity Mine" :
                     ( mine->minetype == SEEKER_MINE ? "A Seeker Mine" : "Unknown Mine!" ) ), mine->pos.x, mine->pos.y, mine->pos.z );
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;
    int missile_count_incoming = 0, missile_count_other = 0;

    for ( missile = ship->starsystem->first_missile; missile; missile = missile->next_in_starsystem )
    {
        if ( vector_distance( &ship->vpos, &missile->pos ) > max_distance )
            continue;

        snprintf( buf, MSL, "%s%s%s",
                 ( missile->target && missile->target == ship ) ? "&R" : "&Y",
                 missile->missiletype == CONCUSSION_MISSILE ? "A Concussion Missile" :
                 ( missile->missiletype == PROTON_TORPEDO ? "A Torpedo" :
                   ( missile->missiletype == HEAVY_ROCKET ? "A Heavy Rocket" :
                     ( missile->missiletype == MAGNETIC_PULSE ? "A Magnetic Pulse" : "A Heavy Bomb" ) ) ),
                 ( missile->target && missile->target == ship ) ? " (Incoming)" : "" );

        if ( mode == 0 )
        {
            if ( missile->target == ship )
                missile_count_incoming++;
            else
                missile_count_other++;
        }
        else
        {
            printed_items = true;
            ch_println( ch, "%-57s   %s%.0f %.0f %.0f", buf,
                       missile->target == ship ? "&R" : "&C",
                       missile->pos.x, missile->pos.y, missile->pos.z );
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    ch_println( ch, "&z%-55s   &C%.0f %.0f %.0f", "Your Coordinates:", ship->vpos.x, ship->vpos.y, ship->vpos.z );

    if ( mode == 0 && missile_count_incoming + missile_count_other > 0 )
    {
        ch_println( ch, "\n&Y%d projectiles, %s%d incoming &Y(See &Wradar projectiles&Y)",
                   missile_count_other + missile_count_incoming, missile_count_incoming > 0 ? "&R" : "", missile_count_incoming );
    }

    learn_from_success( ch, cache_skill( "navigation", &skill_navigation ) );
}

CMDF do_autotrack( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    int chance;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "&RPlatforms don't have autotracking systems!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't autotrack while cloaked!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou aren't in the pilots chair!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first..." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship systems", &skill_ship_systems ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou're not sure which switch to flip." );
        learn_from_failure( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        return;
    }

    act( AT_PLAIN, "$n flips a switch on the control panel.", ch, NULL, argument, TO_ROOM );

    if ( ship->autotrack )
    {
        ship->autotrack = FALSE;
        echo_to_ship_windows( AT_YELLOW, ship, "Autotracking off." );
    }
    else
    {
        ship->autotrack = TRUE;
        echo_to_ship_windows( AT_YELLOW, ship, "Autotracking on." );
    }

    learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
    return;
}

CMDF do_transship( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[MSL];
    int vnum;

    SHIP_DATA* ship = NULL, *ship2 = NULL;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Ctransship <&wship&C> <&wroom/ship with hangar&C>" );
        ch_println( ch, "&z        &Ctransship <&wship&C> (to transfer to your location)" );
        return;
    }

    argument = one_argument( argument, arg );
    ship = get_ship( arg );

    if ( !ship )
    {
        ch_println( ch, "No such ship." );
        return;
    }

    if ( !NULLSTR( argument ) && is_number( argument ) )
        vnum = atoi( argument );
    else if ( !NULLSTR( argument ) )
    {
        ship2 = get_ship( argument );

        if ( !ship2 || !ship2->first_hangar || !ship2->first_hangar->room )
        {
            ch_println( ch, "&zSyntax: &Ctransship <&wship&C> <&wroom/ship with hangar&C>" );
            ch_println( ch, "&z        &Ctransship <&wship&C> (to transfer to your location)" );
            return;
        }

        if ( ship == ship2 )
        {
            ch_println( ch, "&RYou can't transfer a ship to itself!" );
            return;
        }

        vnum = ship2->first_hangar->room->vnum;
    }
    else
        vnum = ch->in_room->vnum;


    if ( vnum >= ship->firstroom && vnum <= ship->lastroom )
    {
        ch_println( ch, "&RYou can't transfer a ship to itself!" );
        return;
    }

    if ( ship->starsystem )
        snprintf( buf, MSL, "%s", ship->starsystem->name );
    else
        snprintf( buf, MSL, "%d", ship->in_room ? ship->in_room->vnum : ship->lastdoc );

    ch_println( ch, "Transferring %s from %s.", ship->name, buf );
    transship( ship, vnum );
    ch_println( ch, "Ship transferred." );
}

void transship( SHIP_DATA* ship, int vnum )
{
    if ( !ship )
        return;

    if ( vnum == 0 )
        vnum = 45; 

    ROOM_INDEX_DATA* vroom;
    if ( ( vroom = get_room_index( vnum ) ) == NULL )
    {
        bug( "transship: destination room not found for ship: %s.", ship->name );
        return;
    }

    if ( ship->starsystem )
        ship_from_starsystem( ship );

    if ( ship->in_room )
        ship_from_room( ship );

    ship->shipstate = SHIP_READY;
    ship_to_room( ship, vnum );
    ship->location = vnum;
    ship->lastdoc = vnum;
    ship->shipstate = SHIP_DOCKED;
    save_ship( ship, true );
    return;
}

/* modified so that you can put a ship right in orbit of a planet, even from a landed position  Orion jan '06 */
CMDF do_moveship( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL], arg3[MIL], arg4[MIL], arg5[MIL], arg6[MIL];
    char* arg7;
    double vx, vy, vz;
    SPACE_DATA* star;
    SHIP_DATA* ship;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );
    argument = one_argument( argument, arg4 );
    argument = one_argument( argument, arg5 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &CMOVESHIP <&wship&C> <&wsystem&C> <&wx&C> <&wy&C> <&wz&C>" );
        return;
    }

    ship = get_ship( arg1 );

    if ( !ship )
    {
        ch_println( ch, "No such ship." );
        return;
    }

    if ( !str_cmp( arg2, "local" ) )
    {
        star = ship->starsystem;
    }
    else
    {
        star = starsystem_from_name( arg2 );
    }

    if ( !star )
    {
        arg7 = arg2;
        arg7 = one_argument( arg7, arg6 );

        if ( is_number_sym( arg6 ) && is_number_sym( arg7 ) )
        {
            star = starsystem_from_coords( atoi( arg6 ), atoi( arg7 ) );

            if ( !star )
                star = make_vsystem( atoi( arg6 ), atoi( arg7 ), false );
        }
    }

    if ( !star )
    {
        ch_println( ch, "No starsystem specified. Sorry." );
        return;
    }

    if ( !is_number_sym( arg3 ) )
    {
        PLANET_DATA* planet = NULL;
        planet = get_planet( arg3 );

        if ( planet )
        {
            vx = planet->pos.x;
            vy = planet->pos.y;
            vz = planet->pos.z;
        }
        else
        {
            ch_println( ch, "Planet not found." );
            send_to_char
            ( "Usage: moveship <ship> <starsystem> <planet>\nOR\nmoveship <ship> <starsystem> <x> <y> <z>\n", ch );
            return;
        }
    }
    else
    {
        vx = atoi( arg3 );
        vy = atoi( arg4 );
        vz = atoi( arg5 );
    }

    move_ship( ship, star, vx, vy, vz );
    ch_println( ch, "&zShip transferred to &C%.0f %.0f %.0f.", ship->vpos.x, ship->vpos.y, ship->vpos.z );
    return;
}

void move_ship( SHIP_DATA* ship, SPACE_DATA* star, double posX, double posY, double posZ )
{
    if ( !ship || !star )
        return;

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ship->shipstate = SHIP_READY;
        ship->lastdoc = ship->location;
        ship->location = 0;
    }

    ship->vpos.x = posX;
    ship->vpos.y = posY;
    ship->vpos.z = posZ;
    ship_to_starsystem( ship, star );
}

