int sabotage_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* argument = buffer->str1;
    SHIP_DATA* ship = on_ship( ch );
    if ( !ship )
    {
        ch_println( ch, "&RYou need to be on a ship to sabotage it." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
