CMDF do_sabotage( CHAR_DATA* ch, char* argument )
{
    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( NULLSTR( argument ) || (
        str_cmp( argument, "fuel" ) && str_cmp( argument, "engine" ) && str_cmp( argument, "drive" ) &&
        str_cmp( argument, "launcher" ) && str_cmp( argument, "laser" ) && str_cmp( argument, "ion" ) &&
        str_cmp( argument, "cloak" ) && str_cmp( argument, "tractor" )
    ) )
    {
        ch_println( ch, "&zSyntax: &Csabotage <&wsystem&C>                    " );
        ch_println( ch, "&zShip Systems: --------                       " );
        ch_println( ch, "&C Fuel     &z - Purges the fuel tanks         " );
        ch_println( ch, "&C Engine   &z - Disables the engine drive     " );
        ch_println( ch, "&C Drive    &z - Disables the engine drive     " );
        ch_println( ch, "&C Launcher &z - Damages the launcher          " );
        ch_println( ch, "&C Laser    &z - Damages the lasers            " );
        ch_println( ch, "&C Ion      &z - Damages the ion cannons       " );
        ch_println( ch, "&C Cloak    &z - Damages the cloaking device   " );
        ch_println( ch, "&C Tractor  &z - Damages the tractor beam      " );
        return;
    }

    SHIP_DATA* ship = get_ship_from_room( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "&RMight help if you were onboard a ship." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_VONG ) )
    {
        ch_println( ch, "&RYou have no clue how you'd interfere with this ship's systems." );
        return;
    }

    if ( ch->in_room->vnum != ship->engineroom )
    {
        ch_println( ch, "&RYou must be in the engine room of a ship to do that!" );
        return;
    }

    if ( is_rental( ch, ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RYou can't sabotage public shuttles! Don't even *THINK* about it!" );
        return;
    }

    if ( ship->safe_orbital )
    {
        ch_println( ch, "&RSabotaging this vessel violates the rules set under HELP CAPITALRULES." );
        return;
    }

    if ( ( !str_cmp( argument, "drive" ) || !str_cmp( argument, "engine" ) ) && ( ship->shipstate == SHIP_HYPERSPACE ) )
    {
        ch_println( ch, "&RYou can't damage the ship's drives while in hyperspace!" );
        return;
    }

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "sabotage", &skill_sabotage ) ) );
    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "\n&GYou begin sabotaging the ship." );

        int delay = 0;
        if ( !str_cmp( argument, "fuel" ) )
            delay = 10;

        if ( !str_cmp( argument, "engine" ) || !str_cmp( argument, "drive" ) )
            delay = 15;

        if ( !str_cmp( argument, "launcher" ) )
            delay = 10;

        if ( !str_cmp( argument, "laser" ) )
            delay = 5;

        if ( !str_cmp( argument, "ion" ) )
            delay = 6;

        if ( !str_cmp( argument, "cloak" ) )
            delay = 15;

        if ( !str_cmp( argument, "turret" ) )
            delay = 10;

        if ( !str_cmp( argument, "tractor" ) )
            delay = 5;

        if ( valid_focus( ch, ESPIONAGE_ABILITY ) )
            delay -= ( int )( delay * .2 );

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, delay*3, sabotage_complete, sabotage_abort, FUNC );
        SET_STRING( timer->buffer->str1, argument );
        return;
    }

    ch_println( ch, "&RYou fail to locate that system." );
    learn_from_failure( ch, cache_skill( "sabotage", &skill_sabotage ) );
}

// Returns true if the system name was valid, regardless of success.
bool disable_ship_system( SHIP_DATA* ship, const char* system_name, CHAR_DATA* ch )
{
    if ( !str_cmp( system_name, "fuel" ) )
    {
        if ( ship->energy <= 0 )
        {
            if ( ch )
                ch_println( ch, "&RThis ship is already out of fuel!" );

            return true;
        }

        if ( ch )
        {
            ch_println( ch, "&RLights flash as the tanks begin to purge." );
            ch_println( ch, "&GThe ship will be stranded in a matter of minutes!" );
        }

        echo_to_ship_windows( AT_RED, ship, "[ALERT]: Pump error 104. Purging fuel tanks." );
        ship->tankpurge = TRUE;
        return true;
    }
    else if ( !str_cmp( system_name, "engine" ) || !str_cmp( system_name, "drive" ) )
    {
        if ( ship->shipstate == SHIP_HYPERSPACE )
        {
            if ( ch )
                debug( "do_sabotage: Sabotage by %s pulling %s out of hyerpsace.", ch->name, ship->name );

            exit_hyperspace( ship );
        }

        ship->shipstate = SHIP_DISABLED;

        if ( ch )
            ch_println( ch, "&GYou manage to disable the ship's drive!" );

        return true;
    }
    else if ( !str_cmp( system_name, "launcher" ) )
    {
        ship->missilestate = MISSILE_DAMAGED;
        ship->spent_tubes = ship->missiletubes;

        if ( ch )
            ch_println( ch, "&GYou manage to sabotage the ship's missile launcher!" );

        return true;
    }
    else if ( !str_cmp( system_name, "tractor" ) )
    {
        ship->tractorstate = TRACTOR_DAMAGED;

        if ( ch )
            ch_println( ch, "&GYou manage to sabotage the ship's tractor beam!" );

        return true;
    }
    else if ( !str_cmp( system_name, "cloak" ) )
    {
        if ( ship->cloakstatus == CLOAK_NONE )
        {
            if ( ch )
                ch_println( ch, "&RDammit, this ship doesn't seem to have a cloaking device." );

            return true;
        }

        ship->cloakstatus = CLOAK_DAMAGED;

        if ( ch )
            ch_println( ch, "&GYou manage to sabotage the ship's cloaking device!" );

        return true;
    }
    else if ( !str_cmp( system_name, "laser" ) )
    {
        ship->autoblaster_charge = LASER_DAMAGED;
        ship->laser_charge = LASER_DAMAGED;
        ship->turbolaser_charge = LASER_DAMAGED;

        if ( ch )
            ch_println( ch, "&GYou manage to sabotage the ship's main laser battery!" );

        return true;
    }
    else if ( !str_cmp( system_name, "ion" ) )
    {
        ship->ion_charge = ION_DAMAGED;

        if ( ch )
            ch_println( ch, "&GYou manage to sabotage the ships ion cannons!" );

        return true;
    }

    return false;
}

