            ? "&z[&C+DOCKSAFE&z     ] Executes a lockdown when successfully docked.\n"
            : "&z[&C-docksafe&z     ] Will not engage lockdown upon docking.\n", ch );
        */
        send_to_char( xIS_SET( ship->aflags, AFLAG_NOINTERCEPT )
                      ? "&z[&C+NOINTERCEPT&z  ] Disabled on board interceptors unless scrambled.\n"
                      : "&z[&C-nointercept&z  ] Will use available interceptors when attacked.\n", ch );
        send_to_char( xIS_SET( ship->aflags, AFLAG_CLANPOST )
                      ? "&z[&C+CLANPOST&z     ] Will automatically attack enemy clan ships.\n"
                      : "&z[&C-clanpost&z     ] Will not attack ships from enemy clans.\n", ch );
        send_to_char( xIS_SET( ship->aflags, AFLAG_RADIO )
                      ? "&z[&C+RADIO&z        ] Will request help from nearby clan ships when fighting.\n"
                      : "&z[&C-radio&z        ] Will not request help from nearby clan ships.\n", ch );
    }
