    {
        bool fSet;
        int bit = -1;

        if ( ship->autopilot )
        {
            ch_println( ch, "&RYou have to shut the autopilot off before reconfiguring it!" );
            return;
        }

        if ( arg[0] == '+' )
            fSet = TRUE;
        else if ( arg[0] == '-' )
            fSet = FALSE;
        else
        {
            ch_println( ch, "AConfig -option or +option?" );
            return;
        }

        if ( !str_prefix( arg + 1, "sentinel" ) )
            bit = AFLAG_SENTINEL;
        else if ( !str_prefix( arg + 1, "aggressive" ) )
            bit = AFLAG_AGGRESSIVE;
        else if ( !str_prefix( arg + 1, "tracking" ) )
            bit = AFLAG_TRACKING;
        else if ( !str_prefix( arg + 1, "autocloak" ) )
            bit = AFLAG_AUTOCLOAK;
        else if ( !str_prefix( arg + 1, "autoshield" ) )
            bit = AFLAG_AUTOSHIELD;
        else if ( !str_prefix( arg + 1, "autojamming" ) )
            bit = AFLAG_AUTOJAMMING;
        else if ( !str_prefix( arg + 1, "nocapture" ) )
            bit = AFLAG_NOCAPTURE;
        else if ( !str_prefix( arg + 1, "usechaff" ) )
            bit = AFLAG_USECHAFF;
        else if ( !str_prefix( arg + 1, "uselaser" ) )
            bit = AFLAG_USELASER;
        else if ( !str_prefix( arg + 1, "uselauncher" ) )
            bit = AFLAG_USELAUNCHER;
        else if ( !str_prefix( arg + 1, "docksafe" ) )
            bit = AFLAG_DOCKSAFE;
        else if ( !str_prefix( arg + 1, "nointercept" ) )
            bit = AFLAG_NOINTERCEPT;
        else if ( !str_prefix( arg + 1, "clanpost" ) )
            bit = AFLAG_CLANPOST;
        else if ( !str_prefix( arg + 1, "radio" ) )
            bit = AFLAG_RADIO;
        else if ( !str_prefix( arg + 1, "pirate" ) )
            bit = AFLAG_PIRATE;
        else if ( !str_prefix( arg + 1, "useion" ) )
            bit = AFLAG_USEION;

        if ( bit >= 0 )
        {
            if ( fSet )
                xSET_BIT( ship->aflags, bit );
            else
                xREMOVE_BIT( ship->aflags, bit );

            save_ship( ship, true );
            ch_println( ch, "AConfig Complete." );
            return;
        }
        else
        {
            ch_println( ch, "AConfig which option?" );
            return;
        }
    }

    return;
}

CMDF do_remotebay( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    char arg2[MSL];
    char arg3[MSL];
    SHIP_DATA* ship, *target;
    HANGAR_DATA* hangar;
    int chance;
    char buf[MSL];

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou must be in realspace to do that!" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( NULLSTR( arg1 ) || NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Cremotebay <&wtarget ship&C> <&wbay #&C> [<&waccess code&C>]" );
        return;
    }

    target = get_ship_here( arg1, ship->starsystem );

    if ( !target || target == NULL )
    {
        ch_println( ch, "&RYou can't find that ship here!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_OBJECT ) )
    {
        ch_println( ch, "&RThat isn't a spacecraft!" );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) > ( 1000 + ( ship->comm * 10 ) ) )
    {
        ch_println( ch, "&RThat ship is too far away!" );
        return;
    }

    int hangar_id = atoi( arg2 );
    LINK_LOOKUP( target->first_hangar, HANGAR_DATA, next, hangar_id - 1, hangar );

    if ( IS_SET( target->mod_flags, MOD_DEATHSTAR ) && hangar != NULL && hangar_id == 1 )
        hangar = NULL;

    if ( hangar == NULL )
    {
        ch_println( ch, "&RThats not a valid hangar ID." );
        return;
    }

    if ( !check_pilot( ch, target ) && !is_stolen( ch, target ) )
    {
        if ( atoi( arg3 ) <= 10000 || atoi( arg3 ) >= 99999 )
        {
            ch_println( ch, "&RMake sure to specify a hangar access code!" );
            return;
        }

        if ( atoi( arg3 ) != target->code[SCODE_HANGAR] )
        {
            ch_println( ch, "&RIt refuses to respond! Must have the code wrong." );
            return;
        }
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship systems", &skill_ship_systems ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou're not sure which switch to flip." );
        WAIT_STATE( ch, 1 * PULSE_PER_SECOND );
        learn_from_failure( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        return;
    }

    act( AT_PLAIN, "$n flips a switch on the control panel.", ch, NULL, argument, TO_ROOM );

    if ( !hangar->bayopen )
    {
        ch_println( ch, "&GSuccess! The Hangar is now opening..." );
        hangar->bayopen = TRUE;
        snprintf( buf, MSL, "[ALERT]: Hangar %d is opening.", hangar_id );
        echo_to_ship_windows( AT_YELLOW, target, buf );
        snprintf( buf, MSL, "One of the hangars on %s slowly slides open.", target->name );
        echo_to_system_noqueue( AT_YELLOW, target, buf, NULL );
        snprintf( buf, MSL, "The massive hangar door begins to slide out of the way." );
        echo_to_room( AT_YELLOW, hangar->room, buf );

        if ( hangar->room )
            for ( SHIP_DATA* rship = hangar->room->first_ship; rship; rship = rship->next_in_room )
                echo_to_ship_windows( AT_ORANGE, rship, "The massive hangar door begins to slide out of the way." );
    }
    else
    {
        ch_println( ch, "&GSuccess! The Hangar is now closing..." );
        hangar->bayopen = FALSE;
        snprintf( buf, MSL, "[ALERT]: Hangar %d is closing.", hangar_id );
        echo_to_ship_windows( AT_YELLOW, target, buf );
        snprintf( buf, MSL, "One of the hangars on %s slowly slides shut.", target->name );
        echo_to_system_noqueue( AT_YELLOW, target, buf, NULL );
        snprintf( buf, MSL, "The massive hangar door begins to slide shut again." );
        echo_to_room( AT_YELLOW, hangar->room, buf );

        if ( hangar->room )
            for ( SHIP_DATA* rship = hangar->room->first_ship; rship; rship = rship->next_in_room )
                echo_to_ship_windows( AT_ORANGE, rship, "The massive hangar door begins to slide shut again." );
    }

    save_ship( target, true ); // Forgot this, eh? Save the ship too    Orion 2008
    WAIT_STATE( ch, 3 * PULSE_PER_SECOND );
    learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
    return;
}

CMDF do_closebay( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    HANGAR_DATA* hangar = NULL;
    int chance;
    char buf[MSL];
    int hangar_id = 0;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    //bool hangarroom = FALSE;
    if ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
    {
        hangar = NULL;
        //  HANGAR_DATA* hangar = NULL;

        for ( hangar = ship->first_hangar; hangar; hangar = hangar->next )
        {
            hangar_id++;

            if ( hangar->room == ch->in_room )
            {
                if ( !check_pilot( ch, ship ) && !is_stolen( ch, ship ) )
                {
                    ch_println( ch, "&RDamn, you don't know the control codes!" );
                    return;
                }

                //    hangarroom = TRUE;
                break;
            }
        }
    }

    if ( hangar == NULL && ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( hangar == NULL &&  ( get_ship_from_pilotseat( ch->in_room ) ) == NULL && ( get_ship_from_navseat( ch->in_room ) == NULL ) )
    {
        ch_println( ch, "&RYou aren't in the pilot's or navigator's chair!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( hangar == NULL && autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( argument[0] == '\0' && hangar == NULL )
    {
        ch_println( ch, "&zSyntax: &CCLOSEBAY <&wbay #&C>" );
        ch_println( ch, "&R        CLOSEBAY [ALL]" );
        return;
    }

    if ( hangar == NULL && !str_cmp( argument, "all" ) )
    {
        int total = 0, cnt = 0;

        if ( ship->first_hangar == NULL )
        {
            ch_println( ch, "&RThis ship has no hangars installed." );
            return;
        }

        for ( hangar = ship->first_hangar; hangar; hangar = hangar->next )
        {
            total++;

            if ( hangar->bayopen )
                cnt++;
        }

        if ( cnt == 0 )
        {
            ch_println( ch, "&RAll of the hangars onboard are currently closed." );
            return;
        }

        chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship systems", &skill_ship_systems ) ) );

        if ( number_percent(  ) > ( chance < 100 ? chance - 5 : chance ) )
        {
            ch_println( ch, "&RYou're not sure which switches to flip." );
            learn_from_failure( ch, cache_skill( "ship systems", &skill_ship_systems ) );
            return;
        }

        act( AT_PLAIN, "$n flips several switches on the control panel.", ch, NULL, argument, TO_ROOM );
        echo_to_ship_windows( AT_YELLOW, ship, "[ALERT]: All Hangars are now closing." );
        snprintf( buf, MSL, "Several of the hangars on %s slowly slide closed.", ship->name );
        echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );

        for ( hangar = ship->first_hangar; hangar; hangar = hangar->next )
        {
            if ( !hangar->bayopen )
                continue;

            if ( IS_SET( ship->mod_flags, MOD_DEATHSTAR ) && hangar == ship->first_hangar )
                continue;

            hangar->bayopen = FALSE;
            snprintf( buf, MSL, "The massive hangar door begins to slide shut again." );
            echo_to_room( AT_YELLOW, hangar->room, buf );

            if ( hangar->room )
                for ( SHIP_DATA* rship = hangar->room->first_ship; rship; rship = rship->next_in_room )
                    echo_to_ship_windows( AT_ORANGE, rship, "The massive hangar door begins to slide shut again." );
        }

        learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        return;
    }

    if ( hangar == NULL )
    {
        hangar_id = atoi( argument );
        LINK_LOOKUP( ship->first_hangar, HANGAR_DATA, next, hangar_id - 1, hangar );
    }

    if ( IS_SET( ship->mod_flags, MOD_DEATHSTAR ) && hangar == ship->first_hangar )
        hangar = NULL;

    if ( hangar == NULL )
    {
        ch_println( ch, "&RThats not a valid hangar ID." );
        return;
    }

    if ( !hangar->bayopen )
    {
        ch_println( ch, "&RThat hangar is already closed." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "ship systems", &skill_ship_systems ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou're not sure which switch to flip." );
        learn_from_failure( ch, cache_skill( "ship systems", &skill_ship_systems ) );
        return;
    }

    act( AT_PLAIN, "$n flips a switch on the control panel.", ch, NULL, argument, TO_ROOM );
    hangar->bayopen = FALSE;
    snprintf( buf, MSL, "[ALERT]: Hangar %d is closing.", hangar_id );
    echo_to_ship_windows( AT_YELLOW, ship, buf );
    snprintf( buf, MSL, "One of the hangars on %s slowly slides shut.", ship->name );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
    snprintf( buf, MSL, "The massive hangar door begins to slide shut again." );
    echo_to_room( AT_YELLOW, hangar->room, buf );

    if ( hangar->room )
        for ( SHIP_DATA* rship = hangar->room->first_ship; rship; rship = rship->next_in_room )
            echo_to_ship_windows( AT_ORANGE, rship, "The massive hangar door begins to slide shut again." );

    learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
}

