    snprintf( buf, MSL, "The massive hangar door begins to slide out of the way." );
    echo_to_room( AT_YELLOW, hangar->room, buf );

    if ( hangar->room )
        for ( SHIP_DATA* rship = hangar->room->first_ship; rship; rship = rship->next_in_room )
            echo_to_ship_windows( AT_ORANGE, rship, "The massive hangar door begins to slide out of the way." );

    learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
}

/*
    Super Laser Addition
    This subroutine is used to DESTORY a targeted planet.
*/
void destroy_planet( CHAR_DATA* ch, PLANET_DATA* planet )
{
    CHAR_DATA* rch;
    OBJ_DATA* robj;
    ROOM_INDEX_DATA* room;
    int vnum;

    if ( IS_NPC( ch ) )
        return;

    bug( "[ALERT]: Planet %s destroyed", planet->name );

    FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
        for ( vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
        {
            room = get_room_index( vnum );

            if ( room != NULL )
            {
                rch = room->first_person;

                while ( rch )
                {
                    if ( IS_IMMORTAL( rch ) )
                    {
                        char_to_room( ch, get_room_index( ROOM_START_IMMORTAL ) );
                    }
                    else if ( IS_RPC( rch ) )
                    {
                        char_to_room( ch, get_room_index( ROOM_START_RPC ) );
                    }
                    else
                    {
                        if ( ch )
                        {
                            check_killer( ch, rch );
                            raw_kill( ch, rch );
                        }
                        else
                            raw_kill( NULL, rch );
                    }

                    rch = room->first_person;
                }

                for ( robj = room->first_content; robj; robj = robj->next_content )
                {
                    separate_obj( robj );
                    extract_obj( robj );
                }
            }
        }
    })

    bug( "[ALERT]: Destruction complete...All Players on planet killed." );
    planet->governed_by = NULL;
    TAX_LEECH_DATA* leech = NULL, *next_leech = NULL;
    for ( leech = planet->first_tax_leech; leech; leech = next_leech )
    {
        next_leech = leech->next;
        remove_tax_leech( leech );
    }
    planet->next_in_system = NULL;
    planet->prev_in_system = NULL;
    planet->starsystem = NULL;
    planet->first_guard = NULL;
    planet->last_guard = NULL;
    save_planet( planet, true );
    return;
}

bool is_valid_eject_room( ROOM_INDEX_DATA* room )
{
    /*
        Ejections can only land OUTSIDE and in NON-PRIVATE Rooms with exits
    */
    if ( !xIS_SET( room->flags, ROOM_INDOORS )
            && !xIS_SET( room->flags, ROOM_UNDERGROUND )
            && !xIS_SET( room->flags, ROOM_PHOME_ADDON )
            && !xIS_SET( room->flags, ROOM_PLR_HOME )
            && !xIS_SET( room->flags, ROOM_EMPTY_HOME )
            && !xIS_SET( room->flags, ROOM_PRIVATE )
            && !xIS_SET( room->flags, ROOM_CLANPAD )
            && !xIS_SET( room->flags, ROOM_NOFLOOR )
            && !xIS_SET( room->flags, ROOM_NOPOD )
            && room->first_exit != NULL
            && !xIS_SET( room->flags, ROOM_PROTOTYPE ) )
    {
        return true;
    }

    return false;
}

ROOM_INDEX_DATA* get_random_eject_room( PLANET_DATA* planet, SHIP_DATA* from_ship )
{
    int possible_rooms = 0;
    ROOM_INDEX_DATA* room = NULL;
    OBJ_DATA* obj = NULL;

    // First, do one full loop to get the count of rooms which are valid for ejection.
    // This is expensive but happens very infrequently, so fine.
    FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
        for ( int vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
        {
            room = get_room_index( vnum );

            if ( room )
            {
                // Look for ejection beacon here. If we find a valid one, return this room immediately.
                for ( obj = room->first_content; obj; obj = obj->next_content )
                {
                    if ( obj->item_type != ITEM_EJECTBEACON )
                        continue;

                    // This beacon works on all ships, or the ship matches it
                    if ( obj->value[0] == 0 || obj->value[0] == from_ship->eject_beacon_id )
                        return room;
                }

                if ( is_valid_eject_room( room ) )
                    possible_rooms++;
            }
        }
    })

    if ( possible_rooms == 0 )
    {
        bug( "Unable to find any valid ejection rooms on %s", planet->name );
        return NULL;
    }

    int choice = number_range( 1, possible_rooms );

    // Repeat the same exact loop and check, but this time return once we find the Nth room,
    // where N is the random room index we picked.
    FOREACH_LNODE( AREA_DATA, planet->first_area, area, {
        for ( int vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
        {
            room = get_room_index( vnum );

            if ( room && is_valid_eject_room( room ) )
            {
                choice--;

                if ( choice == 0 )
                    return room;
            }
        }
    })

    bug( "Invalid random selection for ejection room on %s", planet->name );
    return NULL;
}

// Determines whether the given ship is currently blockading the given planet.
bool is_blockading( SHIP_DATA* ship, PLANET_DATA* planet )
{
    if ( !xIS_SET( planet->flags, PLANET_BLOCKADE ) || !planet->blockaded_by )
        return false;

    if ( ship->classtype < CORVETTE_SHIP )
        return false;

    if ( !ship->starsystem || ship->starsystem != planet->starsystem )
        return false;

    if ( vector_distance( &ship->vpos, &planet->pos ) > 7500 )
        return false;

    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( !d->character->pcdata->clan )
            continue;

        if ( d->character->pcdata->clan != planet->blockaded_by )
            continue;

        if ( d->character->in_room->vnum < ship->firstroom || d->character->in_room->vnum > ship->lastroom )
            continue;

        // We found a clan member on this ship, so it counts as blockading.
        return true;
    }

    return false;
}

// Returns the effective distance of a blockade: How close to the planet the blockade is.
// Ships closer than this are unaffected.
// -1 means there is no blockade.
int blockade_effective_dist( PLANET_DATA* planet )
{
    int min_distance = -1;

    if ( !planet || !planet->starsystem )
        return -1;

    for ( SHIP_DATA* ship = planet->starsystem->first_ship; ship; ship = ship->next_in_starsystem )
    {
        if ( is_blockading( ship, planet ) )
        {
            if ( min_distance == -1 )
                min_distance = vector_distance( &ship->vpos, &planet->pos );
            else
                min_distance = UMIN( min_distance, vector_distance( &ship->vpos, &planet->pos ) );
        }
    }

    if ( min_distance > 7500 )
        return -1;

    return min_distance;
}

/*
    Allows people to eject from fighters
    Possibly saving their lives -Ghost
*/
CMDF do_eject( CHAR_DATA* ch, char* argument )
{
    ROOM_INDEX_DATA* room = NULL;
    OBJ_DATA* obj = NULL;
    SHIP_DATA* ship = NULL;
    bool silent = FALSE;
    PLANET_DATA* planet = NULL;
    char buf[MSL];
    bool can_eject = TRUE;

    if ( !str_cmp( argument, "-auto" ) )
        silent = TRUE;

    if ( ch->hit <= 0 )
    {
        can_eject = FALSE;

        if ( !silent )
        {
            ch_println( ch, "&RYou're too stunned to do that right now!" );
            return;
        }
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        can_eject = FALSE;

        if ( !silent )
        {
            ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
            return;
        }
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        if ( !silent )
            ch_println( ch, "&RThis isn't a spacecraft!" );
    }

    if ( ship->classtype > TRANSPORT_SHIP )
    {
        if ( !silent )
            ch_println( ch, "&ROnly fighters and transports are equipped with ejection seats!" );

        return;
    }

    if ( xIS_SET( ship->flags, SHIP_ESCAPEPOD ) )
    {
        ch_println( ch, "Escape pods aren't equipped with ejection seats!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_SPACE_CORPSE ) )
    {
        ch_println( ch, "&RYou've already been ejected into the cold vacuum of space." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_ENVIROSUIT ) && !silent )
    {
        ch_println( ch, "Envirosuits aren't equipped with ejection seats!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        if ( !silent )
            ch_println( ch, "&RYou can't do that until after you've launched!" );

        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE || !ship->starsystem )
    {
        if ( !silent )
            ch_println( ch, "&RYou can only do that in realspace!" );

        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        can_eject = FALSE;

        if ( !silent )
        {
            ch_println( ch, "&RYou aren't in the pilots chair!" );
            return;
        }
    }

    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        int ship_dist = vector_distance( &ship->vpos, &planet->pos );

        if ( ship_dist > 7500 )
            continue;

        if ( xIS_SET( planet->flags, PLANET_STAR ) )
            continue;

        if ( planet->shields > 0 )
            continue;

        if ( xIS_SET( planet->flags, PLANET_BLOCKADE ) && ship_dist >= blockade_effective_dist( planet ) )
        {
            can_eject = FALSE;
            ch_println( ch, "&RThe blockade around %s prevents you from ejecting to it.", planet->name );
            continue;
        }

        break;
    }

    if ( planet == NULL )
    {
        can_eject = FALSE;

        if ( !silent )
        {
            ch_println( ch, "&RThere's no suitable planet within 7500 units to eject to!" );
            return;
        }
    }

    bool targ = FALSE;

    if ( ship->starsystem )
        for ( SHIP_DATA* tship = ship->starsystem->first_ship; tship; tship = tship->next_in_starsystem )
            if ( tship->target0 == ship )
                targ = TRUE;

    if ( ship->hull >= ship->maxhull && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && is_public( ship ) && ( !targ ) )
    {
        if ( !silent )
        {
            ch_println( ch, "&RNo threat to ship present. Ejection system is currently offline." );
            return;
        }
    }

    if ( can_eject == FALSE && silent == TRUE )
    {
        return;
    }

    room = get_random_eject_room( planet, ship );

    if ( !room )
    {
        if ( !silent )
            ch_println( ch, "&RThere's no way you could survive that landing!" );

        if ( silent )
            bug( "%s may not have ejected due to chance.", ch->name );

        return;
    }

    ch_println( ch, "&YYou yank up on the handle under the seat!" );
    act( AT_PLAIN, "$n yanks on the handle under his seat!", ch, NULL, argument, TO_ROOM );
    echo_to_ship_windows( AT_YELLOW, ship, "An Ejection seat *ERUPTS* from the floor!" );
    snprintf( buf, MSL, "An Ejection seat *ERUPTS* from %s, hurtling away!", ship->name );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );

    if ( !ship->selfd_armed )
    {
        ship->selfd_time = 60;
        ship->selfd_armed = TRUE;
        echo_to_ship_windows( AT_RED, ship, "WARNING: Ejection Failsafe *ARMED*. Self-destruct in 60 seconds.\n" );
    }

    if ( !silent )
        snprintf( buf, MSL, "ejection_seat activated by %s: landing vnum at %d", ch->name, room->vnum );

    if ( !silent )
        log_string( buf );

    /*
        Create the Ejection Seat
    */
    obj = create_object( get_obj_index( OBJ_VNUM_EJECTION_SEAT ), 0 );

    if ( obj && obj != NULL )
    {
        obj = obj_to_room( obj, room );
        obj->timer = 6;
    }

    char_from_room( ch );
    char_to_room( ch, room );
    ch_println( ch, "&RYour body is thrown from the ejection chair as it crashes down!" );
    ch_println( ch, "&RYou're ALIVE!" );
    act( AT_MAGIC, "$n is thrown from the ejection chair as it crashes!", ch, NULL, NULL, TO_ROOM );
    ch->hit = number_range( 11, 31 );
    do_look( ch, "auto" );
    WAIT_STATE( ch, 6 );
    learn_from_success( ch, cache_skill( "ship systems", &skill_ship_systems ) );
}

CMDF do_tractorbeam( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    int chance, cnt = 0;
    SHIP_DATA* ship = NULL;
    SHIP_DATA* tempship = NULL;
    SHIP_DATA* target = NULL, *tarnext;
    HANGAR_DATA* hangar;
    FCARGO_DATA* fcargo;
    char buf[MSL];
    int tractors = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        if ( ( ship = get_ship_from_gunseat( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "&RYou need to be in the pilot or gunners seat!" );
            return;
        }
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    /*
        if ( !check_pilot( ch , ship ) )
        {
        ch_println( ch, "This isn't your ship!" );
        return;
        }
    */
    if ( autofly( ship ) && !nifty_is_name( ch->name, ship->crew ) )
    {
        ch_println( ch, "You'll have to turn off the ship's autopilot first." );
        return;
    }

    if ( ( tractors = ship->tractorbeam ) == 0 )
    {
        ch_println( ch, "You might want to install a tractorbeam!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "&RThe ship's communications array is completely fried!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "You can't tractor while cloaked!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYour ship is docked!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. No power available." );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( ship->tractorstate >= TRACTOR_DAMAGED )
    {
        ch_println( ch, "&RThe ship's tractor beam is %s.", ship->tractorstate == TRACTOR_DESTROYED ? "destroyed" : "damaged" );
        return;
    }

    if ( ship->tractorstate != TRACTOR_READY )
    {
        ch_println( ch, "&RThe tractor beam is still recharging." );
        return;
    }

    if ( NULLSTR( arg1 ) )
    {
        /*
            ch_println( ch, "&WYour maximum tractorbeam range: %d", (tractors * 250) );
        */
        ch_println( ch, "&zSyntax: &CTRACTORBEAM <&wship&C> CAPTURE <&wbay #&C>" );
        //Removing tractorbeam COURSE functionality - Gathorn 9April2017
        //ch_println( ch, "&R        TRACTORBEAM <ship> COURSE <x> <y> <z>" );
        ch_println( ch, "&C        TRACTORBEAM <&wship&C> HALT" );
        ch_println( ch, "&C        TRACTORBEAM <&wcargo pod&C>" );
        return;
    }

    /*
        Floating Cargo
    */
    for ( cnt = 0, fcargo = ship->starsystem->first_fcargo; fcargo; fcargo = fcargo->next_in_starsystem )
    {
        snprintf( buf, MSL, "Cargo pod %d", ++cnt );

        if ( !str_cmp( arg1, buf ) )
        {
            tractor_cargo( ch, ship, fcargo );
            return;
        }
    }

    for ( cnt = 0, fcargo = ship->starsystem->first_fcargo; fcargo; fcargo = fcargo->next_in_starsystem )
    {
        snprintf( buf, MSL, "Cargo pod %d", ++cnt );

        if ( nifty_is_name_prefix( arg1, buf ) )
        {
            tractor_cargo( ch, ship, fcargo );
            return;
        }
    }

    target = get_ship_here( arg1, ship->starsystem );

    if ( target == NULL )
    {
        ch_println( ch, "&RYou can't locate that ship anywhere." );
        return;
    }

    if ( target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't locate that ship anywhere." );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) && !xIS_SET( ship->flags, SHIP_RESCUESHIP ) )
    {
        ch_println( ch, "&RYour ship is not equipped to tractor %s.", xIS_SET( target->flags, SHIP_SPACE_CORPSE ) ? "bodies" : "envirosuits" );
        return;
    }

    /*  if ( !xIS_SET( target->flags, SHIP_ENVIROSUIT ) && xIS_SET( ship->flags, SHIP_RESCUESHIP ) )
        {
        ch_println( ch, "&RYour ship is only equipped to tractor envirosuits." );
        return;
        }*/

    if ( target == ship )
    {
        ch_println( ch, "&RYou can't use tractorbeam on your own ship!" );
        return;
    }

    if ( ( target->classtype != SATELLITE_SHIP ) && ( target->classtype >= ship->classtype ) )
    {
        ch_println( ch, "That ship is too big to tractor!" );
        return;
    }

    // GRAL added a SHIP_NO_TRACTOR flag for quest ships or other suitable things
    if ( xIS_SET( target->flags, SHIP_NO_TRACTOR ) || xIS_SET( target->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RYou have no clue how you could lock on to that." );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) > tractors * 300 )
    {
        ch_println( ch, "&RThat ship is too far away! You'll have to get a little closer." );
        return;
    }

    if ( target->safe_orbital )
    {
        ch_println( ch, "&RTractorbeaming that vessel violates the rules set under HELP CAPITALRULES." );
        return;
    }

    if ( is_protected( ship, target, false ) )
    {
        ch_println( ch, "&RThat target is protected by other ships." );
        return;
    }

    int fuel_required = 200 * ( target->classtype + 1 );

    if ( ship->energy < fuel_required )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    if ( !str_cmp( arg2, "capture" ) )
    {
        if ( IS_SET( ship->mod_flags, MOD_DEATHSTAR ) && target->classtype > CORVETTE_SHIP && !check_pilot( ch, target ) )
        {
            ch_println( ch, "The Death Star cannot tractor in large capital ships. (For balance purposes)" );
            return;
        }

        if ( ship->first_hangar == NULL )
        {
            ch_println( ch, "No hangar available." );
            return;
        }

        int hangar_id = atoi( argument );
        LINK_LOOKUP( ship->first_hangar, HANGAR_DATA, next, hangar_id - 1, hangar );

        if ( hangar == NULL )
        {
            ch_println( ch, "&RYou can't find that hangar onboard!" );
            return;
        }

        if ( hangar->room == NULL )
        {
            ch_println( ch, "&RThat hangar is incomplete! Sorry!" );
            return;
        }

        if ( !hangar->bayopen )
        {
            ch_println( ch, "&RHangar %d is still closed! You'll need to open it or use a open one!", hangar_id );
            return;
        }

        if ( ( target->classtype != SATELLITE_SHIP ) && ( ship->classtype <= target->classtype ) )
        {
            ch_println( ch, "&RThat ship is too big for your hangar." );
            return;
        }

        if ( target->classtype < hangar->room->minshipclass )
        {
            ch_println( ch, "&RThat ship is too small to tractor into that hangar.&w" );
            return;
        }

        if ( target->classtype > hangar->room->maxshipclass )
        {
            ch_println( ch, "&RThat ship is too large to tractor into that hangar.&w" );
            return;
        }

        if ( get_hangar_free( hangar ) < get_ship_size( target ) )
        {
            ch_println( ch, "&RThat hangar doesn't have enough room for that ship!" );
            return;
        }

        if ( hangar->size != 0 && xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
        {
            ch_println( ch, "&RThat hangar cannot accommodate %s!", xIS_SET( target->flags, SHIP_SPACE_CORPSE ) ? "bodies" : "envirosuits" );
            return;
        }

        chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "tractor beams", &skill_tractor_beams ) ) );

        if ( number_percent(  ) <= chance )
        {
            ship->tractorstate = TRACTOR_BUSY;
            set_char_color( AT_GREEN, ch );
            ch_println( ch, "Capture sequence initiated." );
            act( AT_PLAIN, "$n begins the capture sequence.", ch, NULL, argument, TO_ROOM );
            echo_to_ship_main( AT_YELLOW, ship, "ALERT: Ship is being captured, all hands to docking bay." );
            echo_to_ship_main( AT_YELLOW, target, "The ship shudders as a tractorbeam locks on." );
            snprintf( buf, MSL, "You are being captured by %s.", ship->name );

            for ( tempship = ship->starsystem->first_ship; tempship; tempship = tarnext )
            {
                tarnext = tempship->next_in_starsystem;

                if ( tempship == target )
                    continue;

                if ( tempship == ship )
                    continue;

                snprintf( buf, MSL, "A thick white tractorbeam encompasses %s, drawing it towards one of %ss hangars.",
                         target->name, ship->name );
                echo_to_ship_windows( AT_YELLOW, tempship, buf );
            }

            echo_to_ship_windows( AT_BLOOD, target, buf );
            ship->energy -= fuel_required;
            start_tractor( ship, target, number_range( 1, ship->tractorbeam ), hangar );
            learn_from_success( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
            return;
        }
        else
        {
            ship->tractorstate = TRACTOR_REFRESH;
            ch_println( ch, "You fail to work the controls properly." );
            echo_to_ship_main( AT_YELLOW, target, "The ship shudders and then stops as a tractorbeam attemps to lock on." );
            snprintf( buf, MSL, "The %s attempted to capture your ship!", ship->name );
            echo_to_ship_windows( AT_BLOOD, target, buf );

            for ( tempship = ship->starsystem->first_ship; tempship; tempship = tarnext )
            {
                tarnext = tempship->next_in_starsystem;

                if ( tempship == target )
                    continue;

                if ( tempship == ship )
                    continue;

                snprintf( buf, MSL, "A thick white tractorbeam from %s encompasses %s, but seems to have no effect.", ship->name,
                         target->name );
                echo_to_ship_windows( AT_YELLOW, tempship, buf );
            }

            learn_from_failure( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
            return;
        }
    }
    else if ( !str_cmp( arg2, "halt" ) )
    {
        if ( target->classtype != SATELLITE_SHIP && ship->classtype <= target->classtype )
        {
            ch_println( ch, "&RThat ship is too big to halt!" );
            return;
        }

        chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "tractor beams", &skill_tractor_beams ) ) );

        if ( number_percent(  ) <= chance )
        {
            ship->tractorstate = TRACTOR_BUSY;
            set_char_color( AT_GREEN, ch );
            ch_println( ch, "Tractorbeam sequence initiated." );
            act( AT_PLAIN, "$n begins the tractorbeam sequence.", ch, NULL, argument, TO_ROOM );
            snprintf( buf, MSL, "The ship shudders to a halt as %s locks on with a tractor beam.", ship->name );
            echo_to_ship_main( AT_YELLOW, target, buf );
            ship->energy -= fuel_required;

            if ( target->shipstate != SHIP_DISABLED && target->shipstate != SHIP_PERM_DISABLED )   // ~ Don't let a landing ship land, ~miros
            {
                // Delay is based on comparing target vs. this ship size.
                // 8 seconds tractoring a ship one size less than you, 12 for 2 sizes less than you, etc, up to 20.
                int delay_ticks = UMIN( 2 + ( ship->classtype - target->classtype ) * 2, 10 );
                target->shipstate = SHIP_BUSY;
                target->maneuver_timer = delay_ticks;

                // If they're trying to dock, abort the docking procedure
                if ( target->dock_state > DOCK_READY && target->dock_state < DOCK_DOCKED && target->dockship )
                {
                    target->dock_state = DOCK_READY;
                    target->dockship->dock_state = DOCK_READY;
                    target->dockship->dock_lead = FALSE;
                    target->dockship->dockship = NULL;
                    target->dockship = NULL;
                    target->dock_lead = FALSE;
                }
            }

            target->currspeed = 0;
            /*
                target->shipstate = SHIP_TRACTORED;
            */
            echo_to_ship_main( AT_GREEN, target, "The ship lurches as its slowed by the tractorbeam." );

            for ( tempship = ship->starsystem->first_ship; tempship; tempship = tarnext )
            {
                tarnext = tempship->next_in_starsystem;

                if ( tempship == target )
                    continue;

                if ( tempship == ship )
                    continue;

                snprintf( buf, MSL, "A thick white tractorbeam from %s encompasses %s, bringing it to a halt.", ship->name, target->name );
                echo_to_ship_windows( AT_YELLOW, tempship, buf );
            }

            learn_from_success( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
            return;
        }
        else
        {
            ship->tractorstate = TRACTOR_REFRESH;
            ch_println( ch, "You fail to work the controls properly." );
            echo_to_ship_main( AT_YELLOW, target, "The ship shudders and then stops as a tractorbeam attempts to lock on." );
            snprintf( buf, MSL, "%s attempted to tractor your ship!", ship->name );
            echo_to_ship_windows( AT_BLOOD, target, buf );

            for ( tempship = ship->starsystem->first_ship; tempship; tempship = tarnext )
            {
                tarnext = tempship->next_in_starsystem;

                if ( tempship == target )
                    continue;

                if ( tempship == ship )
                    continue;

                snprintf( buf, MSL, "A thick white tractorbeam from %s encompasses %s, but seems to have no effect.", ship->name,
                         target->name );
                echo_to_ship_windows( AT_YELLOW, tempship, buf );
            }

            learn_from_failure( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
            return;
        }
    }
    else
        do_tractorbeam( ch, "" );

    return;
}

void tractor_cargo( CHAR_DATA* ch, SHIP_DATA* ship, FCARGO_DATA* fcargo )
{
    CARGO_DATA* cargo;
    int chance, maxamt = 0;

    if ( fcargo == NULL )
        return;

    /*
        Distance check ->
    */
    if ( vector_distance( &ship->vpos, &fcargo->pos ) > 100 )
        // if ( get_sprox( ( int )ship->vx, ( int )ship->vy, ( int )ship->vz, fcargo->mx, fcargo->my, fcargo->mz ) > 100 )
    {
        ch_println( ch, "&RYou must be within 100 units of the cargo package." );
        return;
    }

    for ( cargo = ship->first_cargo; cargo; cargo = cargo->next )
    {
        if ( cargo == NULL )
            continue;

        if ( cargo->type == fcargo->type )
            maxamt += ( cargo->size - cargo->amount );

        if ( cargo->amount <= 0 )
            maxamt += cargo->size;
    }

    if ( fcargo->amount > maxamt )
    {
        ch_println( ch, "&RThere's not enough room onboard to hold all of that cargo!" );
        return;
    }

    if ( ship->energy < 50 )
    {
        ch_println( ch, "&RThere's not enough fuel to recover it!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "tractor beams", &skill_tractor_beams ) ) );

    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GTractorbeam sequence completed. Cargo in storage." );
        act( AT_PLAIN, "$n uses the tractorbeam to collect a cargo pod.", ch, NULL, NULL, TO_ROOM );
        ship->energy -= 50;

        /*
            Fill free cargo pods - Large, Pissy Function
        */
        for ( cargo = ship->first_cargo; cargo; cargo = cargo->next )
        {
            if ( cargo == NULL )
                continue;

            if ( fcargo->amount <= 0 )
                break;

            if ( cargo->type == fcargo->type )
            {
                if ( fcargo->amount > ( cargo->size - cargo->amount ) )
                {
                    fcargo->amount -= ( cargo->size - cargo->amount );
                    cargo->amount = cargo->size;
                }
                else
                {
                    cargo->amount += fcargo->amount;
                    fcargo->amount = 0;
                }
            }

            if ( cargo->amount <= 0 )
            {
                cargo->type = fcargo->type;

                if ( fcargo->amount > cargo->size )
                {
                    cargo->amount = cargo->size;
                    fcargo->amount -= cargo->size;
                }
                else
                {
                    cargo->amount += fcargo->amount;
                    fcargo->amount = 0;
                }
            }
        }

        extract_fcargo( fcargo );
        WAIT_STATE( ch, PULSE_PER_SECOND * 2 );
        learn_from_success( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
        return;
    }
    else
    {
        ch_println( ch, "You fail to work the controls properly." );
        WAIT_STATE( ch, PULSE_PER_SECOND * 1 );
        learn_from_failure( ch, cache_skill( "tractor beams", &skill_tractor_beams ) );
        return;
    }

    return;
}

