/*
    A Command to find the proximity of nearby ships.
    Added by Ghost
*/
int get_sprox( int ax, int ay, int az, int bx, int by, int bz )
{
    double prox;
    double x, y, z;
    x = ( ax - bx );

    if ( x < 0 )
        x = x - ( 2 * x );

    y = ( ay - by );

    if ( y < 0 )
        y = y - ( 2 * y );

    z = ( az - bz );

    if ( z < 0 )
        z = z - ( 2 * z );

    prox = sqrt( pow( x, 2 ) + pow( y, 2 ) );
    prox = sqrt( pow( z, 2 ) + pow( prox, 2 ) );
    return ( int )prox;
}

CMDF do_proximity( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL], buf[MSL];
    SHIP_DATA* target;
    SPACE_DATA* space;
    int chance, cnt = 0;
    SHIP_DATA* ship;
    MISSILE_DATA* missile;
    FCARGO_DATA* fcargo;
    MINE_DATA* mine;
    PLANET_DATA* planet;
    int mode = 0;
    int max_distance = INT_MAX;
    double distance;
    bool printed_items = false;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !NULLSTR( arg1 ) )
    {
        if ( !str_cmp( arg1, "speed" ) )
            mode = 1;
        else if ( !str_cmp( arg1, "velocity" ) )
            mode = 1;
        else if ( !str_cmp( arg1, "projectiles" ) )
            mode = 2;
        else if ( !str_cmp( arg1, "ships" ) )
            mode = 3;
        else if ( is_number( arg1 ) )
            max_distance = atoi( arg1 );
        else
        {
            ch_println( ch, "Invalid proximity argument." );
            return;
        }

        // Check for optional max distance argument after a mode arg
        if ( mode > 0 && !NULLSTR( arg2 ) )
        {
            if ( is_number( arg2 ) )
                max_distance = atoi( arg2 );
            else
            {
                ch_println( ch, "Maximum proximity distance must be a positive number." );
                return;
            }
        }
    }

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit or turret of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RWait until after you launch!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't use the radar while cloaked!" );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can't do that unless the ship is flying in realspace!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "&RThe ship's communications array is completely fried!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "navigation", &skill_navigation ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, cache_skill( "navigation", &skill_navigation ) );
        return;
    }

    act( AT_PLAIN, "$n checks the proximity radar.", ch, NULL, argument, TO_ROOM );
    space = ship->starsystem;
    ch_println( ch, "\n&c%s:&w", space->virtualsys ? "Uncharted space" : space->name );

    /*
        Stars
    */
    for ( planet = space->first_planet; planet; planet = planet->next_in_system )
    {
        distance = vector_distance( &ship->vpos, &planet->pos );

        if ( distance > max_distance )
            continue;

        if ( mode == 2 )
            break;

        if ( xIS_SET( planet->flags, PLANET_STAR ) )
        {
            if ( mode == 0 || mode == 3 )
            {
                printed_items = true;
                ch_println( ch, "&Y(STAR) %-*s   &zProx: &Y%.0f", ( 48 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name, distance );
            }

            if ( mode == 1 )
            {
                printed_items = true;
                ch_println( ch, "&Y(STAR) %-*s   &zVelocity: &YN/A", ( 48 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name );
            }
        }
    }

    /*
        Planets
    */
    for ( planet = space->first_planet; planet; planet = planet->next_in_system )
    {
        distance = vector_distance( &ship->vpos, &planet->pos );

        if ( distance > max_distance )
            continue;

        if ( mode == 2 )
            break;

        if ( !xIS_SET( planet->flags, PLANET_STAR ) )
        {
            if ( mode == 0 || mode == 3 )
            {
                printed_items = true;
                ch_println( ch, "&G%-*s   &zProx: &G%.0f", ( 55 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name, distance );
            }

            if ( mode == 1 )
            {
                printed_items = true;
                ch_println( ch, "&G%-*s   &zVelocity: &GN/A", ( 55 + ( strlen( planet->name ) - strlen( planet->plaintext_name ) ) ), planet->name );
            }
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;
    /*
        Ships
    */
    SHIP_DATA* tarnext;

    for ( target = space->first_ship; target; target = tarnext )
    {
        if ( mode == 2 )//Only care about projectiles
            break;

        tarnext = target->next_in_starsystem;

        if ( target != ship && ( target->cloakstatus != CLOAK_ON || IS_IMMORTAL( ch ) ) )
        {
            distance = vector_distance( &ship->vpos, &target->vpos );

            if ( distance > max_distance )
                continue;

            if ( mode == 0 || mode == 3 )
            {
                printed_items = true;
                ch_println( ch, "%s%-55s%s   &zProx: %s%.0f",
                           target->target0 == ship ? "&R" : "&B",
                           target->name,
                           target->target0 == ship && has_pcflag( ch, PCFLAG_SCREENREADER ) ? " (targeting you)" : "",
                           target->target0 == ship ? "&R" : "&C",
                           distance
                         );
            }

            if ( mode == 1 )
            {
                printed_items = true;
                ch_println( ch, "%s%-55s%s   &zVelocity: %s%d",
                           target->target0 == ship ? "&R" : "&B",
                           target->name,
                           target->target0 == ship && has_pcflag( ch, PCFLAG_SCREENREADER ) ? " (targeting you)" : "",
                           target->target0 == ship ? "&R" : "&C",
                           target->currspeed
                         );
            }
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;

    /*
        Floating Cargo
    */
    for ( fcargo = ship->starsystem->first_fcargo; fcargo; fcargo = fcargo->next_in_starsystem )
    {
        if ( mode == 2 || mode == 3 ) //Modes 2 and 3 only care about projectiles and ships
            break;

        cnt++;
        snprintf( buf, MSL, "Cargo pod %d", cnt );
        distance = vector_distance( &ship->vpos, &fcargo->pos );

        if ( distance > max_distance )
            continue;

        if ( mode == 0 )
        {
            printed_items = true;
            ch_println( ch, "&R%-55s   &zProx: &C%.0f&w", buf, distance );
        }

        if ( mode == 1 )
        {
            printed_items = true;
            ch_println( ch, "&R%-55s   &Velocity: &C0&w", buf );
        }
    }

    if ( printed_items )
        ch_println( ch, "" );

    printed_items = false;

    /*
        Mines
    */
    for ( mine = ship->starsystem->first_mine; mine; mine = mine->next_in_starsystem )
    {
        distance = vector_distance( &ship->vpos, &mine->pos );

        if ( distance > max_distance )
            continue;

        if ( mode == 3 ) //Mode 3 only cares about ships
            break;

        if ( mode == 0 || mode == 2 )
        {
            printed_items = true;
            ch_println( ch, "&R%-55s   &zProx: &C%.0f&w",
                       mine->minetype == MAGNETIC_MINE ? "A Magnetic Mine" :
                       ( mine->minetype == PROXIMITY_MINE ? "A Proximity Mine" :
                         ( mine->minetype == SEEKER_MINE ? "A Seeker Mine" : "Unknown Mine!" ) ),
                       distance );
        }

        if ( mode == 1 )
        {
            printed_items = true;
            ch_println( ch, "&R%-55s   &zVelocity: &C%d&w",
                       mine->minetype == MAGNETIC_MINE ? "A Magnetic Mine" :
                       ( mine->minetype == PROXIMITY_MINE ? "A Proximity Mine" :
                         ( mine->minetype == SEEKER_MINE ? "A Seeker Mine" : "Unknown Mine!" ) ), mine->speed );
        }
    }

    /*
        Missiles
    */
    int missile_count_incoming = 0;
    int missile_count_other = 0;

    for ( missile = ship->starsystem->first_missile; missile; missile = missile->next_in_starsystem )
    {
        distance = vector_distance( &ship->vpos, &missile->pos );

        if ( distance > max_distance )
            continue;

        snprintf( buf, MSL, "%s%s%s",
                 ( missile->target && missile->target == ship ) ? "&R" : "&Y",
                 missile->missiletype == CONCUSSION_MISSILE ? "A Concussion Missile" :
                 ( missile->missiletype == PROTON_TORPEDO ? "A Torpedo" :
                   ( missile->missiletype == HEAVY_ROCKET ? "A Heavy Rocket" :
                     ( missile->missiletype == MAGNETIC_PULSE ? "A Magnetic Pulse" : "A Heavy Bomb" ) ) ),
                 ( missile->target && missile->target == ship ) ? " (Incoming)" : "" );

        if ( mode == 3 ) //Mode 3 only cares about ships
            break;

        if ( mode == 0 )
        {
            if ( missile->target == ship )
                missile_count_incoming++;
            else
                missile_count_other++;
        }

        if ( mode == 1 )
        {
            printed_items = true;
            ch_println( ch, "%-57s   &zVelocity: %s%d&w", buf, missile->target == ship ? "&R" : "&C", missile->speed );
        }

        if ( mode == 2 )
        {
            if ( missile->target && missile->target == ship )
            {
                printed_items = true;
                ch_println( ch, "%-57s   Prox: &R%.0f&w", buf, distance );
            }
        }
    }

    if ( mode == 0 && missile_count_incoming + missile_count_other > 0 )
    {
        ch_println( ch, "&Y%d projectiles, %s%d incoming&Y &Y(See &Wproximity projectiles&Y)", missile_count_incoming + missile_count_other, missile_count_incoming > 0 ? "&R" : "", missile_count_incoming );
        printed_items = true;
    }

    if ( printed_items )
        ch_println( ch, "" );

    set_char_color( AT_LBLUE, ch );
    ch_println( ch, "&z%-55s   &C%.0f %.0f %.0f", "Your Coordinates:", ship->vpos.x, ship->vpos.y, ship->vpos.z );
    set_char_color( AT_WHITE, ch );
    learn_from_success( ch, cache_skill( "navigation", &skill_navigation ) );
}

void ai_anger_planet( PLANET_DATA* planet, SHIP_DATA* ship )
{
    SHIP_DATA* guard = NULL;
    CLAN_DATA* clan = NULL;
    //  AREA_DATA* area = NULL;
    TURRET_DATA* pturret = NULL;
    clan = planet->governed_by;

    if ( xIS_SET( planet->flags, PLANET_AUTOFIRE ) )
    {
        for ( pturret = first_pturret; pturret; pturret = pturret->next )
        {
            if ( !pturret->room || room_extracted( pturret->room ) )
                continue;

            if ( get_planet_from_room( pturret->room ) != planet )
                continue;

            if ( !planet )
                continue;

            if ( !xIS_SET( pturret->room->flags, ROOM_WEAP_ION ) && !xIS_SET( pturret->room->flags, ROOM_WEAP_TURBOLASER ) )
                continue;

            if ( pturret->laserstate > 0 )
                continue;

            pturret->target = ship;
            pturret->laserstate = number_range( 1, 2 );
        }
    }

    if ( !clan )
        return;

    SHIP_DATA* tarnext;

    if ( ship->starsystem )
    {
        for ( guard = ship->starsystem->first_ship; guard; guard = tarnext )
        {
            tarnext = guard->next_in_starsystem;

            if ( guard->shipstate != SHIP_READY )
                continue;

            ai_anger( guard, ship, TRUE );
        }
    }

    return;
}

/*
    Syntax: BOMB <planet> <weapon>
    IE: bomb 'hoth vi' torpedo

    Only works on small spacecraft. Time to complete bombing run
    is based on ships maneuver value. Releases one of the specified
    weapon type, letting it fall to the surface.

    Requires Space Combat and matching ship skill.
*/
CMDF do_bomb( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    PLANET_DATA* planet = NULL;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > FRIGATE_SHIP )
    {
        ch_println( ch, "&RThis ship is too large for bombing runs! Use BATTLEGROUP BOMBARD." );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( is_rental( ch, ship ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RPublic vessels aren't equipped with targeting computers." );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn the autopilot off first..." );
        return;
    }

    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RNot while cloaked!" );
        return;
    }

    if ( ship->maneuver < 65 )
    {
        ch_println( ch, "&RThis ship isn't fast enough to pull off a bombing run!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to maneuver." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CBOMB <&wplanet&C>" );
        return;
    }

    planet = get_planet( argument );

    if ( planet == NULL )
    {
        ch_println( ch, "&RYou don't see that planet here!" );
        return;
    }

    if ( planet->starsystem != ship->starsystem )
    {
        ch_println( ch, "&RYou don't see that planet here!" );
        return;
    }

    if ( xIS_SET( planet->flags, PLANET_NOPVP ) || ( ship->starsystem && ship->starsystem->nopvp == 1 ) )
    {
        ch_println( ch, "&RSorry, this is a No PVP system!" );
        return;
    }

    if ( vector_distance( &ship->vpos, &planet->pos ) > 100 )
    {
        ch_println( ch, "&RThat planet is too far away to bomb! Must be within 100 units!" );
        return;
    }

    if ( ship->energy < ship->classtype * 10 )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    if ( ship->missilestate != MISSILE_READY )
    {
        ch_println( ch, "&RThis ship's missile tubes are still reloading." );
        return;
    }

    if ( ship->missiles == 0 && ship->torpedoes == 0 && ship->rockets == 0 )
    {
        ch_println( ch, "&RYour ship has no projectiles to bomb that planet with." );
        return;
    }

    ch_println( ch, "&GYou release the bombs and pull back up out of the atmosphere." );
    act( AT_PLAIN, "$n drags back on a release handle while pulling back on the stick.", ch, NULL, argument, TO_ROOM );
    orbital_bombardment( ship, planet, ch );
    ship->energy -= ( ship->classtype * 10 );
    return;
}

CMDF do_chaff( CHAR_DATA* ch, char* argument )
{
    int chance;
    SHIP_DATA* ship;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ( ship = get_ship_from_coseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RThe controls are at the copilots seat!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou'll have to turn the autopilot off first..." );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->chaff <= 0 )
    {
        ch_println( ch, "&RYou don't have any chaff to release!" );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "weapon systems", &skill_weapon_systems ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou can't figure out which switch it is." );
        learn_from_failure( ch, cache_skill( "weapon systems", &skill_weapon_systems ) );
        return;
    }

