}

int compare_ships_class_name( SHIP_DATA** s1p, SHIP_DATA** s2p )
{
    SHIP_DATA* s1 = ( *s1p );
    SHIP_DATA* s2 = ( *s2p );

    if ( s1->classtype != s2->classtype )
        return s2->classtype - s1->classtype;

    // If all else is equal, just sort alphabetically
    return strcasecmp( s1->name, s2->name );
}

void show_ships_to_char( ROOM_INDEX_DATA* room, CHAR_DATA* ch )
{
    VEHICLE_DATA* rvec = NULL;
    bool other = FALSE;

    if ( !room || !ch || room_extracted( room ) || char_extracted( ch ) )
        return;

    if ( !has_pcflag( ch, PCFLAG_SHIPSTACK ) )
    {
        for ( SHIP_DATA* rship = room->first_ship; rship; rship = rship->next_in_room )
        {
            if ( rship == curr_ship )
                continue;

            ch_printf( ch, "&C%s%s%-35s",
                       rship->shipstate == SHIP_HOVER || rship->shipstate == SHIP_HOVERLAND || rship->shipstate == SHIP_HOVERLAUNCH ? "&Y[&OHovering&Y]&C " :
                       rship->shipstate == SHIP_LAUNCH ? "&Y[&GLaunching&Y] &C" :
                       rship->shipstate == SHIP_LAUNCH_ABORT ? "&Y[&OLanding&Y] &C" : "",
                       xIS_SET( rship->flags, SHIP_DRYDOCK ) ? "&G" : "",
                       rship->name );

            if ( other )
                ch_println( ch, "" );

            other = !other;
        }
    }
    else
    {
        char last_base_name[100];
        char base_name[100];
        char ship_name[100];
        int ship_cnt = 0;
        SHIP_DATA* ships[500];
        char* colorcodes[] = {"&037", "&116"};

        for ( SHIP_DATA* rship = room->first_ship; rship; rship = rship->next_in_room )
        {
            if ( rship == curr_ship )
                continue;

            ships[ship_cnt++] = rship;

            if ( ship_cnt == 500 )
            {
                ch_println( ch, "&RThere are too many ships in this location." );
                break;
            }
        }

        qsort( &ships[0], ship_cnt, sizeof( SHIP_DATA* ), ( int ( * )( const void*, const void* ) )compare_ships_class_name );
        last_base_name[0] = '\0';
        int line_chars = 0;
        int model_ships = 0;
        int ship_name_chars = 0;

        for ( int i = 0; i < ship_cnt; i++ )
        {
            get_ship_name( ships[i], ship_name );
            get_ship_basename( ships[i], base_name );
            ship_name_chars = strlen( ship_name );

            switch ( ships[i]->shipstate )
            {
                case SHIP_HOVER:
                case SHIP_HOVERLAND:
                case SHIP_HOVERLAUNCH:
                    strlcat( ship_name, " &Y[&OHovering&Y]", 100 );
                    ship_name_chars += strlen( " [Hovering]" );
                    break;

                case SHIP_LAUNCH:
                    strlcat( ship_name, " &Y[&GLaunching&Y]", 100 );
                    ship_name_chars += strlen( " [Launching]" );
                    break;

                case SHIP_LAUNCH_ABORT:
                    strlcat( ship_name, " &Y[&OLanding&Y]", 100 );
                    ship_name_chars += strlen( " [Landing]" );
                    break;
            }

            if ( NULLSTR( base_name ) )
            {
                model_ships = 0;
                ch_printf( ch, "%s%s%s", i > 0 ? "\n" : "", colorcodes[model_ships % 2], ship_name );
                continue;
            }

            if ( str_cmp( last_base_name, base_name ) )
            {
                model_ships = 0;
                strlcpy( last_base_name, base_name, 100 );
                ch_printf( ch, "%s&C%s: %s%s", i > 0 ? "\n" : "", base_name, colorcodes[model_ships % 2], ship_name );
                line_chars = strlen( base_name ) + 2 + ship_name_chars;
            }
            else
            {
                model_ships++;

                if ( line_chars + 2 + ship_name_chars > 80 )
                {
                    ch_printf( ch, "\n  %s%s", colorcodes[model_ships % 2], ship_name );
                    line_chars = 2 + ship_name_chars;
                }
                else
                {
                    ch_printf( ch, ", %s%s", colorcodes[model_ships % 2], ship_name );
                    line_chars += 2 + ship_name_chars;
                }
            }
        }

        if ( ship_cnt > 0 )
            ch_println( ch, "" );
    }

    for ( rvec = first_vehicle; rvec; rvec = rvec->next )
    {
        if ( rvec->location == room->vnum && rvec != curr_vec )
        {
            if ( !other )
            {
                ch_printf( ch, "&B%-35s     ", rvec->name );
                other = TRUE;
            }
            else
            {
                ch_printf( ch, "&B%-35s", rvec->name );
                ch_printf( ch, "\n&w" );
                other = FALSE;
            }
        }
    }

    if ( other )
        ch_printf( ch, "\n&w" );

    if ( ( xIS_SET( room->flags, ROOM_GARAGE ) || xIS_SET( room->flags, ROOM_CAN_LAND )
            || xIS_SET( room->flags, ROOM_CLANPAD )
            || xIS_SET( room->flags, ROOM_HIDDEN_LAND )  ) && room->shipcapacity != 0 )
    {
        ch_printf( ch, "&039Ship Capacity: [&W%d%%&039]\n\n&w", ( int )( ( ( double )get_shipcapacity_count( room ) / ( double )room->shipcapacity ) * 100 ) );
    }

    return;
}

bool autofly( SHIP_DATA* ship )
{
    if ( !ship || ship_extracted( ship ) )
        return FALSE;

    // Let squadron logic take over if the leader is in the system.
    if ( ship->squadleader && ship->squadleader != ship && ship->squadleader->starsystem == ship->starsystem )
        return FALSE;

    if ( ship->autopilot )
        return TRUE;

    return FALSE;
}

bool is_squadleader( SHIP_DATA* ship )
{
    return !ship_extracted( ship ) && ship->squadleader == ship;
}

bool should_follow_squadleader( SHIP_DATA* ship, SHIP_DATA* squadleader )
{
    if( !ship || !squadleader )
        return FALSE;

    if ( !ship->squadleader || ship->squadleader != squadleader )
        return FALSE;

    if ( ship == ship->squadleader )
        return FALSE;

    if ( ship->piloting != NULL )
        return FALSE;

    if ( str_cmp( ship->shipowner, squadleader->shipowner ) )
    {
        remove_from_squad( ship );
        return FALSE;
    }

    return TRUE;
}

/*
    Behold! The LOTJ Docking system =)
    -Ghost
*/
int dock_abort( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    ch_println( ch, "&RDocking Sequence aborted." );

    SHIP_DATA* ship = buffer->ship;
    if ( valid_ship( ship ) && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        ship->shipstate = SHIP_READY;

    return E_LOTJ_SUCCESS;
}

int dock_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    SHIP_DATA* target = buffer->shiptarget;

    if ( !valid_ship( ship ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    if ( !valid_ship( target ) || target->starsystem != ship->starsystem || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYour docking target seems to have left..." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( target->currspeed > ship->realspeed )
    {
        ch_println( ch, "&RThat ship's current speed is higher than your ship's maximum speed!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( target->shipstate == SHIP_LAND )
    {
        ch_println( ch, "&RThe target ship's docking system isn't responding! Must be busy." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( target->dock_state != DOCK_READY && target->dock_state != DOCK_NONE )
    {
        ch_println( ch, "&RThe target ship's docking system isn't responding! Must be busy." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    ch_println( ch, "&GYou managed to initiate the docking sequence." );
    act( AT_PLAIN, "$n locks the docking controls and steps back from them...", ch, NULL, NULL, TO_ROOM );
    echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: Docking Sequence Initiated - All Hands to Boarding Ramp" );
    echo_to_ship_main( AT_YELLOW, target, strfmt("[ALERT]: Docking Sequence Initiated by %s", ship->name) );
    ship->energy -= ( ship->classtype * 10 );
    ship->dock_state = DOCK_BUSY_1;
    target->dock_state = DOCK_WAITING;
    ship->dockship = target;
    target->dockship = ship;
    ship_align_heading( ship, target );
    ship->currspeed = target->currspeed;
    learn_from_success( ch, find_gsn( ship->classtype ) );
    learn_from_success( ch, cache_skill( "dock", &skill_dock ) );
    lua_trigger_ship_dock( ship, target, ship->starsystem );
    return E_LOTJ_SUCCESS;
}

CMDF do_dock( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    argument = one_argument( argument, arg1 );

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    SHIP_DATA* ship = get_ship_from_cockpit( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP || ship->classtype == BATTLESTATION_SHIP )
    {
        ch_println( ch, "&RThis ship is way too large to dock with ANYTHING!" );
        ch_println( ch, "&RTry taking a shuttle over or something!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( !ship->dock_install )
    {
        ch_println( ch, "&RYou don't *HAVE* a docking system installed!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RTake the ship off autopilot first." );
        return;
    }

    if ( IS_SET( ship->mod_flags, MOD_DEATHSTAR ) )
    {
        ch_println( ch, "&RYour ship cannot dock." );
        return;
    }

    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( ship->dock_state < DOCK_NONE )
    {
        ch_println( ch, "&RYour Docking system is too damaged to function!" );
        return;
    }

    if ( ship->dock_state == DOCK_DOCKED )
    {
        ch_println( ch, "&RYou're already docked! Use UNDOCK first!" );
        return;
    }

    if ( ship->dock_state != DOCK_READY )
    {
        ch_println( ch, "&RThe docking system is in use...Please wait." );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to maneuver." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou cannot initiate a docking maneuver with the cloaking field up!" );
        return;
    }

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &CDOCK <&wship&C> [<&wdocking code&C>]" );
        return;
    }

    SHIP_DATA* target = get_ship_here( arg1, ship->starsystem );
    if ( !target || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RThat ship isn't here!" );
        return;
    }

    if ( target == ship )
    {
        ch_println( ch, "&RYou can't dock with your own ship!" );
        return;
    }

    if ( IS_SET( target->mod_flags, MOD_DEATHSTAR ) || !target->dock_install )
    {
        ch_println( ch, "&RThat ship cannot dock." );
        return;
    }

    bool is_disabled = FALSE;
    if ( target->shipstate == SHIP_DISABLED || target->shipstate == SHIP_PERM_DISABLED )
        is_disabled = TRUE;

    if ( target->shipstate == SHIP_LAND || xIS_SET( target->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RThe target ship's docking system isn't responding! Must be busy." );
        return;
    }

    if ( target->dock_state != DOCK_READY && target->dock_state != DOCK_NONE )
    {
        ch_println( ch, "&RThe target ship's docking system isn't responding! Must be busy." );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) > 300 )
    {
        ch_println( ch, "&RThat ship is too far away to dock with!" );
        ch_println( ch, "&RYou must be within 300 units of the other vessel!" );
        return;
    }

    if ( target->currspeed > ship->realspeed )
    {
        ch_println( ch, "&RThat ship's current speed is higher than your ship's maximum speed!" );
        return;
    }

    if ( ship->classtype >= 5 && ship->classtype > target->classtype )
    {
        send_to_char
        ( "&RYour ship is MUCH too big to dock with theirs!\nTry to get them to dock with yours, Or use a tractor beam.\n",
            ch );
        return;
    }

    if ( ship->classtype - 1  > target->classtype )
    {
        send_to_char
        ( "&RYour ship is too big to dock with theirs!\nTry to get them to dock with yours, Or use a tractor beam.\n",
            ch );
        return;
    }

    if ( ship->energy < ship->classtype * 10 )
    {
        ch_println( ch, "&RThere's not enough fuel!" );
        return;
    }

    ch_println( ch, "&YTransmitting Docking Codes now..." );

    if ( !check_pilot( ch, target ) && !is_stolen( ch, target ) && !is_disabled )
    {
        if ( NULLSTR( argument ) || !is_number( argument ) )
        {
            send_to_char( "&RYou'll need the correct code to dock with that ship.\n"
                            "&zSyntax: &CDOCK <&wship&C> <&wdocking code&C>\n", ch );
            return;
        }

        if ( atoi( argument ) != target->code[SCODE_DOCK] )
        {
            ch_println( ch, "&R[ALERT] - Invalid docking code, Docking request refused!" );
            echo_to_ship_main( AT_RED, ship, "[ALERT]: Invalid docking code - Docking request rejected." );
            return;
        }
    }

    int chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, find_gsn( ship->classtype ) );
    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GYou begin to steer the ship into a docking sequence..." );
        act( AT_PLAIN, "$n fiddles with the docking controls...", ch, NULL, argument, TO_ROOM );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 6, dock_complete, dock_abort, FUNC );
        timer->buffer->ship = ship;
        timer->buffer->shiptarget = target;
        return;
    }

    ch_println( ch, "&RYou fail to work the controls properly." );
    learn_from_failure( ch, find_gsn( ship->classtype ) );
}

CMDF do_undock( CHAR_DATA* ch, char* argument )
{
    int chance, tmp;
    SHIP_DATA* ship;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->dock_lead )
    {
        ch_println( ch, "&RYou can't do that! The ship that docked with you must undock!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->dock_state != DOCK_DOCKED || !ship->dockship )
    {
        ch_println( ch, "&RYou're not even docked! Try docking first!" );
        return;
    }

    if ( autofly( ship ) )
    {
        ch_println( ch, "&RYou must disable the autopilot first." );
        return;
    }

    tmp = atoi( argument );

    if ( tmp < 0 || tmp > 60 || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CUNDOCK <&wdelay&C>\n Delay is 1-60 seconds. 0 to cancel." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( tmp == 0 )
    {
        echo_to_ship_main( AT_RED, ship, "[ALERT]: Aborting undocking procedure!" );
        echo_to_ship_main( AT_RED, ship->dockship, "[ALERT]: Aborting undocking procedure!" );
        ship->undock_time = 0;
        return;
    }

    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GYou begin preparing to break dock..." );
        act( AT_PLAIN, "$n punches in several control codes...", ch, NULL, argument, TO_ROOM );
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: Undocking sequence initiated! Prepare to break dock!" );
        echo_to_ship_main( AT_YELLOW, ship->dockship, "[ALERT]: Undocking sequence initiated! Prepare to break dock!" );
        ship->undock_time = tmp + 1;
        learn_from_success( ch, find_gsn( ship->classtype ) );
        learn_from_success( ch, cache_skill( "dock", &skill_dock ) );
        lua_trigger_ship_undock( ship, ship->dockship, ship->starsystem );
        return;
    }

    ch_println( ch, "&RYou fail to work the controls properly." );
    learn_from_failure( ch, find_gsn( ship->classtype ) );
    return;
}

void dockship( SHIP_DATA* ship )
{
    SHIP_DATA* target = NULL;
    char buf[MSL];

    if ( !ship->dockship )
    {
        ship->dock_state = DOCK_READY;

        if ( target )
            target->dock_state = DOCK_READY;

        return;
    }

    target = ship->dockship;

    if ( !target->starsystem || target->starsystem != ship->starsystem )
    {
        ship->dock_state = DOCK_READY;
        target->dock_state = DOCK_READY;
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: Docking attempt failed - *DOCKING ERROR*" );
        snprintf( buf, MSL, "[ALERT]: Ship %s has failed docking sequence!", ship->name );
        log_string( buf );
        return;
    }

    ship->dock_state = DOCK_DOCKED;
    ship->dock_lead = FALSE;
    target->dock_state = DOCK_DOCKED;
    target->dock_lead = TRUE;
    echo_to_room( AT_YELLOW, get_room_index( ship->pilotseat ), "Docking sequence complete." );
    echo_to_ship_main( AT_YELLOW, ship, "You feel a slight thud as the ship docks up with its target." );
    snprintf( buf, MSL, "%s docks with %s.", ship->name, target->name );
    echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
    echo_to_room( AT_YELLOW, get_ship_dockroom( ship ), "The hatch hisses open as the docking connection is formed." );
    echo_to_room( AT_YELLOW, get_ship_dockroom( target ), "The hatch hisses open as the docking connection is formed." );
    ship->energy -= ( ship->classtype * 25 );
    target->energy -= ( target->classtype * 25 );

    if ( ship->currspeed != target->currspeed )
        ship->currspeed = target->currspeed;

    ship_align_heading( ship, target );
    vector_copy( &ship->vpos, &target->vpos );
    save_ship( ship, true );
    lua_trigger_ship_docked( ship, target, ship->starsystem );
}

/* Command to transfer fuel from one ship to another */
CMDF do_transferfuel( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;
    SHIP_DATA* target;
    int value;
    char arg1[MIL];
    char buf[MIL];

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    argument = one_argument( argument, arg1 );
    value = atoi( arg1 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Ctransferfuel <&wamount&C>" );
        ch_println( ch, "&z        &Ctransferfuel abort" );
        return;
    }

    if ( !ch->in_room || !ch->in_room->vnum )
    {
        bug( "%s is not in a room ", ch->name, 0 );
        return;
    }

    ship = get_ship_from_cockpit( ch->in_room );

    if ( ship == NULL )
    {
        set_char_color( AT_RED, ch );
        ch_println( ch, "You can only do that from the cockpit of the ship!" );
        return;
    }

    if ( ship->dock_state != DOCK_DOCKED || !ship->dockship || ship->dockship == ship )
    {
        ch_println( ch, "&z[&CInvalid Option&z] &zTransfering fuel can only be done while docked!" );
        ship->remaining_fuel_transfer = 0;
        ship->total_fuel_transfer = 0;
        return;
    }

    target = ship->dockship;

    if ( !str_cmp( arg1, "abort" ) || !str_cmp( arg1, "stop" ) )
    {
        if ( ship->remaining_fuel_transfer <= 0 || !target || ship->shipstate != SHIP_DOCKED )
            ch_println( ch, "You're not currently transferring any fuel!" );
        else
        {
            snprintf( buf, MIL, "\n&z[&CALERT&z]: &zAborting transfer of fuel to &C%s&z.", target->name );
            echo_to_ship_bridge( AT_WHITE, ship, buf );
            snprintf( buf, MIL, "\n&z[&CALERT&z]: &C%s&z has aborted the fuel transfer.", ship->name );
            echo_to_ship_bridge( AT_WHITE, target, buf );
        }

        ship->remaining_fuel_transfer = 0;
        ship->total_fuel_transfer = 0;
        return;
    }

    if ( value <= 0 )
    {
        ch_println( ch, "&zHow much fuel do you want to transfer?" );
        return;
    }

    if ( target == NULL || target == ship )
    {
        ch_println( ch, "&z[&CInvalid Option&z] &zTransfering fuel can only be done while docked!" );
        return;
    }

    if ( target->energy == target->maxenergy )
    {
        ch_println( ch, "&zTheir tanks are already full!" );
        return;
    }

    if ( value > ship->energy )
    {
        ch_println( ch, "&zYou don't have that much fuel!" );
        return;
    }

    if ( target->energy + value > target->maxenergy )
    {
        ch_println( ch, "&zTheir ship can't hold that much fuel!" );
        return;
    }

    ship->total_fuel_transfer = value;
    ship->remaining_fuel_transfer = value;

    snprintf( buf, MIL, "\n&z[&CALERT&z]: &zInitiating transfer of &C%'d&z unit(s) of fuel to &C%s&z.", value, target->name );
    echo_to_ship_bridge( AT_WHITE, ship, buf );
    snprintf( buf, MIL, "\n&z[&CALERT&z]: &C%s&z has initiated a fuel transfer to onboard tanks.", ship->name );
    echo_to_ship_bridge( AT_WHITE, target, buf );
}

CMDF do_renameship( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];    /* No case-sensityivity */
    char arg2_c[MIL];  /* With case-sensitivity */
    char buf[MSL];
    int price = 10000;
    SHIP_DATA* cship;
    SHIP_DATA* ship;
    argument = one_argument( argument, arg1 );
    strlcpy( arg2_c, argument, MIL );
    argument = strlower( argument );
    strlcpy( arg2, argument, MIL );

    if ( !NULLSTR( arg2 ) )
    {
        strlcpy( arg2, stripclr( arg2 ), MIL );
        strlcpy( arg2_c, stripclr( arg2_c ), MIL );
    }

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&z\n&zSyntax:&C RENAMESHIP <&wship&C> <&wnew name&C>&w" );
        ch_println( ch, "&z Ship renames cost &C10,000 credits&z to alter registration." );
        ch_println( ch, "&w The new name must be no more than 20 letters." );
        return;
    }

    ship = ship_in_room( ch->in_room, arg1 );

    if ( !ship )
    {
        act( AT_PLAIN, "I see no $T here.", ch, NULL, arg1, TO_CHAR );
        return;
    }

    if ( is_rental( ch, ship ) )
    {
        ch_println( ch, "&RYou cannot rename public shuttles!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) )
    {
        ch_println( ch, "&RThat ship is too well known to be renamed!" );
        return;
    }

    if ( !check_pilot( ch, ship ) )
    {
        ch_println( ch, "&RYou must be cleared to pilot the ship before changing its name." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_BRANDNEW ) )
        price = 0;

    if ( ch->pcdata && ch->pcdata->clan && !str_cmp( ship->shipowner, ch->pcdata->clan->name ) )
    {
        if ( ch->pcdata->clan->funds < price )
        {
            ch_println( ch, "&R%s doesn't have enough money to rename this ship.", ch->pcdata->clan->name );
            return;                
        }   
    }
    else if ( ch->gold < price )
    {
        ch_println( ch, "&RYou don't have enough money to rename this ship." );
        return;
    }

    get_ship_name( ship, buf );

    if ( get_trust( ch ) < sysdata.log_level && ship->classtype >= CRUISER_SHIP && str_cmp( buf, ship->shortname ) && !xIS_SET( ship->flags, SHIP_BRANDNEW ) )
    {
        ch_println( ch, "&RThat capital ship has already been renamed." );
        ch_println( ch, "&RCruisers and larger ships can only be renamed once without staff assistance." );
        return;
    }

    if ( !is_plain_text( arg2 ) )
    {
        ch_println( ch, "&RThe new name contains invalid characters. You can ONLY use normal text." );
        return;
    }

    if ( strlen( arg2 ) < 4 || strlen( arg2 ) > 20 )
    {
        ch_println( ch, "&RName must be 4 to 20 letters in length!" );
        return;
    }

    if ( isspace( arg2[strlen( arg2 ) - 1] ) )
    {
        ch_println( ch, "&RName cannot end in an empty space." );
        return;
    }

    one_argument( argument, buf );

    if ( !str_cmp( buf, "the" ) )
    {
        ch_println( ch, "You cannot name your ship beginning with 'The', it causes bugs." );
        return;
    }

    if ( !str_cmp( buf, "pub" ) )
    {
        ch_println( ch, "You cannot name your ship beginning with 'Pub', as it may confuse people looking for public shuttles." );
        return;
    }

    if ( !str_cmp( buf, "none" ) )
    {
        ch_println( ch, "You cannot name your ship beginning with 'None', it causes bugs." );
        return;
    }

    for ( cship = first_ship; cship; cship = cship->next )
    {
        if ( cship == ship )
            continue;

        get_last_arg( cship->name, buf );

        if ( !str_cmp( buf, arg2 ) )
        {
            ch_println( ch, "&RThat name is already in use. Sorry." );
            return;
        }

        if ( first_drydock != NULL && cship == last_ship )
            cship = first_drydock;
    }


    if ( !clan_owned( ch, ship ) )
    {
        ch_println( ch, "&GYou pay %d credits to rename the ship.", price );
        ch->gold -= price;
        if ( price > 0 && !IS_NPC( ch ) )
            sql_credits_log( ch->name, "do_renameship", price * -1, TRUE );
    }
    else
    {
        if ( price > 0 )
            sql_credits_log( ch->pcdata->clan->name, "do_renameship", price * -1, TRUE );
        ch->pcdata->clan->funds -= price;
        ch_println( ch, "&G%s pays %d credits to rename the ship.", ch->pcdata->clan->name, price );
    }

    replace_ship_name( ship, ship->name, arg2_c );
    do_save( ch, "-noalert" );
    save_ship( ship, true );
    ch_println( ch, "&GRegistration changed. The ship is now the %s", ship->name );
    act( AT_PLAIN, "$n makes some changes to a registration paper.", ch, NULL, argument, TO_ROOM );
    return;
}

void replace_ship_name( SHIP_DATA* ship, char* arg, char* str )
{
    char name[MIL];
    char buf[MSL];
    int lp = 0, cnt = 0, tt = 0;
    strlcpy( buf, "", MSL );

    if ( !arg || arg[0] == '\0' )
        return;

    tt = count_args( arg );

    for ( ;; )
    {
        if ( ++lp > 999 )
        {
            bug( "replace_ship_name: trapped in infinite loop, aborting." );
            return;
        }

        arg = one_argument_sc( arg, name );

        if ( ++cnt == tt )
        {
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), " '%s'", str );
            SET_STRING( ship->name, buf );
            return;
        }
        else
        {
            if ( cnt == 1 )
                snprintf( buf, MSL, "%s", name );
            else
                snprintf( buf + strlen( buf ), MSL - strlen( buf ), " %s", name );
        }
    }
}

void get_last_arg( char* arg, char* str )
{
    char name[MIL];
    int lp = 0, cnt = 0, tt = 0;

    if ( !arg || arg[0] == '\0' )
        return;

    tt = count_args( arg );

    for ( ;; )
    {
        if ( ++lp > 999 )
        {
            bug( "get_last_arg: trapped in infinite loop, aborting." );
            return;
        }

        arg = one_argument( arg, name );

        if ( ++cnt == tt )
        {
            strlcpy( str, name, 100 );
            return;
        }
    }
}

void check_repair_public( SHIP_DATA* ship, bool silent )
{
    if ( !str_cmp( "Public", ship->shipowner ) || !str_cmp( "public", ship->shipowner )
            || !str_cmp( "Trainer", ship->shipowner ) )
    {
        SHIP_DATA* target;
        int fueldiff;

        if ( ( target = get_ship_from_room( get_room_index(ship->location) ) ) != NULL )
        {
            fueldiff = ship->maxenergy - ship->energy;

            if ( target->energy > fueldiff )
            {
                ship->energy = ship->maxenergy;
                target->energy -= fueldiff;
            }
            else
            {
                ship->energy += target->energy;
                target->energy = 0;
            }
        }
        else
            ship->energy = ship->maxenergy;

        ship->chaff = ship->maxchaff;
        ship->spent_tubes = 0;
        ship->missiles = ship->maxmissiles;
        ship->torpedoes = ship->maxtorpedoes;
        ship->rockets = ship->maxrockets;
        ship->pulses = ship->maxpulses;
        ship->shield = 0;
        ship->autorecharge = FALSE;
        ship->autotrack = FALSE;
        ship->autospeed = FALSE;
        ship->hull = ship->maxhull;
        ship->missilestate = MISSILE_READY;
        ship->ion_charge = ION_READY;
        ship->autoblaster_charge = LASER_READY;
        ship->laser_charge = LASER_READY;
        ship->turbolaser_charge = LASER_READY;
        ship->shipstate = SHIP_DOCKED;

        if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH )  )
            xREMOVE_BIT( ship->flags, SHIP_BROKEN_HATCH );

        // GRAL No refueling when target and not planet
        if ( silent == FALSE )
            echo_to_ship_windows( AT_YELLOW, ship, "Repairing and refueling ship..." );
    }
}

/*
    Another Orion innovation - Drydocking
    This feature sends all destroyed ships to a seperate linked list,
    and a bitvector bool serves to differentiate on file load.
    Also comes with handy restore do_fun. Simple but effective.
*/
void drydock( SHIP_DATA* ship )
{
    if ( !ship )
        return;

    if ( xIS_SET( ship->flags, SHIP_DRYDOCK ) )
        return;

    destroy_lockers( ship->firstroom, ship->lastroom, FALSE );

    if ( ship->starsystem )
        ship_from_starsystem( ship );

    if ( ship->in_room )
        ship_from_room( ship );

    ship->location = 0;
    ship->shipyard = 0;
    ship->lastdoc = 0;

    UNLINK( ship, first_ship, last_ship, next, prev );
    hashset_remove( valid_ships, ship );
    LINK( ship, first_drydock, last_drydock, next, prev );
    xSET_BIT( ship->flags, SHIP_DRYDOCK );
    save_ship( ship, true );
}

CMDF do_restoreship( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship = NULL;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "You must specify a ship to restore." );
        return;
    }

    for ( ship = first_drydock; ship; ship = ship->next )
        if ( nifty_is_name_prefix( argument, ship->name ) )
            break;

    if ( !ship )
    {
        ch_println( ch, "There is no drydocked ship matching those parameters." );
        return;
    }
    else
    {
        UNLINK( ship, first_drydock, last_drydock, next, prev );
        LINK( ship, first_ship, last_ship, next, prev );
        hashset_add( valid_ships, ship );
        xREMOVE_BIT( ship->flags, SHIP_DRYDOCK );
        ship->hull = ship->maxhull;
        ship->selfd_armed = FALSE;
        ship->selfd_time = 0;
        update_ship_room_references( ship );
        transship( ship, ship->shipyard );
        save_ship( ship, true );
        restore_lockers( ship->firstroom, ship->lastroom );
        ch_println( ch, "%s has been restored.", ship->name );
        return;
    }
}

bool ship_extracted( SHIP_DATA* ship )
{
    if ( !ship )
        return TRUE;

    return ship->extracted;
}

int queue_extracted_ship( SHIP_DATA* ship )
{
    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    add_extract_queue( ship, EXTRACT_SHIP );
    ship->extracted = TRUE;
    cur_qships++;
    return E_LOTJ_SUCCESS;
}

int delete_ship( SHIP_DATA* ship )
{
    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    destroy_lockers( ship->firstroom, ship->lastroom, TRUE );
    WOF(delete_sql_row_by_id( DB_TABLE_SHIPS, ship->id ));  
    ship->delete_queued = TRUE;  
    return extract_ship( ship );
}

int extract_ship( SHIP_DATA* ship )
{
    ROOM_INDEX_DATA* room = NULL, *next_room = NULL;
    SHIP_DATA* tship = NULL, *next_tship = NULL;
    MINE_DATA* mine = NULL, *next_mine = NULL;
    MISSILE_DATA* missile = NULL, *next_missile = NULL;
    TRACTOR_DATA* tractor = NULL, *next_tractor = NULL;
    SQUEUE_DATA* squeue = NULL, *next_squeue = NULL;
    TURRET_DATA* tturret = NULL;
    bool in_main = FALSE, in_drydock = FALSE;

    // Bail out if no ship is provided
    if ( !ship )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ship_extracted( ship ) )
        return E_LOTJ_NOTHING_TO_DO;

    // If the ship's in a room, extract it
    if ( ship->in_room )
        ship_from_room( ship );

    // If it's in a starsystem, extract it
    if ( ship->starsystem )
        ship_from_starsystem( ship );

    remove_from_bg( ship );
    remove_from_squad( ship );

    // If the ship is in the global linked list of active ships, remove it
    LINK_HASNODE( first_ship, SHIP_DATA, next, ship, in_main );
    if ( in_main ) UNLINK( ship, first_ship, last_ship, next, prev );

    // If the ship is in the global linked list of drydocked ships, remove it
    LINK_HASNODE( first_drydock, SHIP_DATA, next, ship, in_drydock );
    if ( in_drydock ) UNLINK( ship, first_drydock, last_drydock, next, prev );
    hashset_remove( valid_ships, ship );

    // Iterate through all the rooms in the ship's range
    for ( room = ship->first_room; room; room = next_room )
    {
        next_room = room->next_in_range;
        // NULL out the backlink pointer
        room->on_ship = NULL;
        UNLINK( room, ship->first_room, ship->last_room, next_in_range, prev_in_range );

        // Unload every nested ship
        for ( tship = room->first_ship; tship; tship = next_tship )
        {
            next_tship = tship->next_in_room;
            tship->delete_queued = ship->delete_queued;
            extract_ship( tship );
        }

        if ( ship->delete_queued )
            delete_room( room );
    }

    for ( tship = first_ship; tship; tship = tship->next )
    {
        if ( tship == ship )
            continue;

        if ( tship->dockship == ship ) tship->dockship = NULL;

        if ( tship->leader == ship )
            remove_from_bg( tship );

        if ( tship->squadleader == ship )
            remove_from_squad( tship );

        if ( tship->join == ship ) tship->join = NULL;
        if ( tship->target0 == ship ) tship->target0 = NULL;
        if ( tship->target1 == ship ) tship->target1 = NULL;
        if ( tship->target2 == ship ) tship->target2 = NULL;

        for ( tturret = tship->first_turret; tturret; tturret = tturret->next )
            if ( tturret->target == ship )
                tturret->target = NULL;
    }

    for ( mine = first_mine; mine; mine = next_mine )
    {
        next_mine = mine->next;
        if ( mine->target == ship )
            extract_mine( mine );
        else if ( mine->fired_from == ship )
            mine->fired_from = NULL;
    }

    for ( missile = first_missile; missile; missile = next_missile )
    {
        next_missile = missile->next;
        if ( missile->target == ship )
            extract_missile( missile );
        else if ( missile->fired_from == ship )
            missile->fired_from = NULL;
    }

    for ( tractor = first_tractor; tractor; tractor = next_tractor )
    {
        next_tractor = tractor->next;
        if ( tractor->owner == ship || tractor->target == ship )
            extract_tractor( tractor );
    }

    if ( sorted_queue != NULL )
    {
        for ( int i = 0; i < top_squeue; i++ )
        {
            if ( !sorted_queue[i] )
                continue;

            squeue = sorted_queue[i];

            if ( squeue->dship == ship )
                squeue->dship = NULL;

            if ( squeue->target == ship )
            {
                UNLINK( squeue, first_queue, last_queue, next, prev );
                DISPOSE( squeue );
                sorted_queue[i] = NULL;
            }
        }
    }
    else
    {
        for ( squeue = first_queue; squeue; squeue = next_squeue )
        {
            next_squeue = squeue->next;

            if ( squeue->dship == ship )
                squeue->dship = NULL;

            if ( squeue->target == ship )
            {
                UNLINK( squeue, first_queue, last_queue, next, prev );
                DISPOSE( squeue );
            }
        }
    }

    for ( tturret = first_pturret; tturret; tturret = tturret->next )
        if ( tturret->target == ship )
            tturret->target = NULL;

    queue_extracted_ship( ship );
    return E_LOTJ_SUCCESS;
}

// Determines whether this ship is considered manned.
// That means: A player is on it, or a player is on its lead ship and in the same system.
// An intentional gap is when an unmanned BG leader is in the same system as a manned BG member. The BG
// leader is not counted as manned in that case, because the iteration would be too costly to do very frequently.
bool is_ship_manned( SHIP_DATA* ship )
{
    for ( DESCRIPTOR_DATA* d = first_descriptor; d; d = d->next )
    {
        if ( !d || !d->character )
            continue;

        if ( IS_IMMORTAL( d->character ) )
            continue;

        if ( d->character->in_room && d->character->in_room->vnum >= ship->firstroom && d->character->in_room->vnum <= ship->lastroom )
            return true;

        // If this character is on the ship's BG leader and in the same system, then the original ship counts as manned.
        if ( ship && ship->leader && ship->starsystem &&
                ship->starsystem == ship->leader->starsystem && d->character->in_room &&
                d->character->in_room->vnum >= ship->leader->firstroom &&
                d->character->in_room->vnum <= ship->leader->lastroom )
            return true;
    }

    return false;
}

SPACE_DATA* in_starsystem( CHAR_DATA* ch )
{
    SHIP_DATA* ship = NULL;
    STRUCTURE_DATA* tstruct = NULL;
    int vnum = 0;

    if ( ch && ch->in_room )
    {
        vnum = ch->in_room->vnum;

        /*
            someone had made this get_ship_from_cockpit. -Orion
        */
        if ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
        {
            if ( ship->shipstate == SHIP_HYPERSPACE )
                return NULL;

            //hovering, launching, etc.  it's still in the room, get it from there  ~Miros
            if ( ship->shipstate != SHIP_DOCKED &&
                    ship->shipstate != SHIP_HOVER &&
                    ship->shipstate != SHIP_HOVERLAUNCH &&
                    ship->shipstate != SHIP_HOVERLAND &&
                    ship->shipstate != SHIP_LAUNCH )
                //if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED ) Sintaka - disabled because a ship can be disabled in space
            {
                return ship->starsystem;
            }
            else
            {
                vnum = ship->location;
            }
        }

        if ( ( tstruct = structure_from_room( ch->in_room->vnum ) ) != NULL )
            vnum = tstruct->in_room;

        if ( vnum > 0 )
        {
            return starsystem_from_vnum( vnum );
        }
    }

    return NULL;
}

SPACE_DATA* get_room_starsystem( ROOM_INDEX_DATA* room )
{
    SHIP_DATA* ship;
    int vnum = 0;

    if ( room )
    {
        vnum = room->vnum;

        if ( ( ship = get_ship_from_cockpit( room ) ) != NULL )
        {
            if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
            {
                return ship->starsystem;
            }
            else
            {
                vnum = ship->location;
            }
        }

        if ( vnum > 0 )
        {
            return starsystem_from_vnum( vnum );
        }
    }

    return NULL;
}

int bulk_ship_rename( char* old, char* newname )
{
    SHIP_DATA* ship;
    int count = 0;

    for ( ship = first_ship; ship; ship = ship->next )
    {
        if ( !str_cmp( ship->shipowner, old ) )
        {
            SET_STRING( ship->shipowner, newname );
            ship->clan = get_clan( ship->shipowner );
            save_ship( ship, true );
            count++;
        }
    }

    return count;
}

void clean_player_ships( char* name )
{
    SHIP_DATA* ship;

    for ( ship = first_ship; ship; ship = ship->next )
    {
        if ( !str_cmp( ship->shipowner, name ) )
        {
            lognormal( "Releasing %s's ownership of ship %s", name, ship->name );
            squadron_remove( ship, NULL );
            if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) && ship->pilot ) //Legendary ships can be passed down upon death to the person set as pilot. - Gathorn 15Nov2018
                SET_STRING( ship->shipowner, ship->pilot );
            else
                SET_STRING( ship->shipowner, "" );

            ship->clan = NULL;
            SET_STRING( ship->pilot, "" );
            SET_STRING( ship->copilot, "" );
            SET_STRING( ship->crew, "" );
            save_ship( ship, true );
        }
        else if ( !str_cmp( ship->pilot, name ) )
        {
            if ( !str_cmp( ship->copilot, name ) )
            {
                SET_STRING( ship->pilot, "" );
                SET_STRING( ship->copilot, "" );
            }
            else
            {
                SET_STRING( ship->pilot, ship->copilot );
                SET_STRING( ship->copilot, "" );
            }

            save_ship( ship, true );
        }
        else if ( !str_cmp( ship->copilot, name ) )
        {
            SET_STRING( ship->copilot, "" );
            save_ship( ship, true );
        }
    }

    return;
}

void init_queue( void )
{
    boot_log( "Initializing ship queue system" );
    first_queue = NULL;
    last_queue = NULL;
    in_queue = FALSE;
    return;
}

void add_queue( SHIP_DATA* target, int type, int dam, int idam, CHAR_DATA* ch, SHIP_DATA* attacker )
{
    SQUEUE_DATA* stmp;

    if ( !target || !target->starsystem )
    {
        bug( "Squeue: no target, or target not in starsystem, type %d", type );
        return;
    }

    if ( type < 0 || type >= SQUEUE_MAX )
    {
        bug( "Invalid squeue type: %d", type );
        return;
    }

    CREATE( stmp, SQUEUE_DATA, 1 );
    stmp->starsystem = target->starsystem;
    stmp->target = target;
    stmp->dch = ch;
    stmp->dship = attacker;
    stmp->type = type;
    stmp->damage = dam;
    stmp->ion_damage = idam;
    stmp->created_at = current_time;
    LINK( stmp, first_queue, last_queue, next, prev );
    return;
}

int compare_squeue( SQUEUE_DATA** s1p, SQUEUE_DATA** s2p )
{
    SQUEUE_DATA* s1 = ( *s1p );
    SQUEUE_DATA* s2 = ( *s2p );

    // We sort by all of the things we need to group display according to various preferences:
    // - By target and damage type
    // - By squardron, by battlegroup, or by individual attacking ship
    // Sorting by ships is done by just comparing memory addresses. There's no need to sort more consistently than that.
    if ( s1->starsystem != s2->starsystem )
        return s1->starsystem - s2->starsystem;

    if ( s1->target != s2->target )
        return s1->target - s2->target;

    if ( s1->type != s2->type )
        return s1->type - s2->type;

    if ( !s1->dship || !s2->dship )
        return (int)(s1->created_at - s2->created_at);

    if ( s1->dship->leader != s2->dship->leader )
        return s1->dship->leader - s2->dship->leader;

    if ( s1->dship->squadleader != s2->dship->squadleader )
        return s1->dship->squadleader - s2->dship->squadleader;

    return s1->dship - s2->dship;
}

// Global state which gets set before filtering space output to tell us which sort of message we're handling
bool sqfilter_unrelated_pirate = FALSE; // Whether the action involved a pirate, but not a player-related ship
bool sqfilter_raw = FALSE; // Whether the action was the raw form of the action, regardless of whether a group was available.
bool sqfilter_squadron = FALSE; // Whether the aggressor was a squadron fighter whose leader is in the system
bool sqfilter_bg = FALSE; // Whether the aggressor was a BG member whose leader is in the system, or a BG leader with 1+ members in the system
bool sqfilter_miss = FALSE; // Whether the action was a miss

bool sqfilter( CHAR_DATA* ch )
{
    // Mobs default to seeing all raw messages, but no grouped ones.
    if ( IS_NPC( ch ) )
        return !sqfilter_squadron && !sqfilter_bg;

    if ( sqfilter_miss && has_pcflag( ch, PCFLAG_GAGSHIPMISS ) )
        return false;

    if ( sqfilter_unrelated_pirate && has_pcflag( ch, PCFLAG_GAGPIRATES ) )
        return false;

    if ( sqfilter_squadron )
    {
        if ( sqfilter_raw )
            return !has_pcflag( ch, PCFLAG_GAGSHIPSQUAD );
        else
            return has_pcflag( ch, PCFLAG_GAGSHIPSQUAD );
    }

    if ( sqfilter_bg )
    {
        if ( sqfilter_raw )
            return !has_pcflag( ch, PCFLAG_GAGSHIPBG );
        else
            return has_pcflag( ch, PCFLAG_GAGSHIPBG );
    }

    return true;
}

