SHIP_DATA* squeue_group_leader( SQUEUE_DATA* sq )
{
    if ( !sq || !sq->dship || ship_extracted( sq->dship ) || !sq->dship->starsystem || !sq->target || ship_extracted( sq->target ) || !sq->target->starsystem )
        return NULL;

    // If attacker has a leader in its system, return that.
    if ( sq->dship->leader && !ship_extracted( sq->dship->leader ) && sq->dship->leader->starsystem == sq->dship->starsystem )
        return sq->dship->leader;

    if ( sq->dship->squadleader && !ship_extracted( sq->dship->squadleader ) && sq->dship->squadleader->starsystem == sq->dship->starsystem )
        return sq->dship->squadleader;

    return NULL;
}

void squeue_append_count( char* buf, int count )
{
    if ( NULLSTR( buf ) || count <= 1 )
        return;

    strlcat( buf, " [x", MIL );
    strlcat( buf, itoa( count ), MIL );
    strlcat( buf, "]", MIL );
}

void process_queue( void )
{
    int i = 0;

    if ( !first_queue )
        return;

    SQUEUE_DATA* sq = NULL, *next_sq = NULL;
    SHIP_DATA* group_leader = NULL;
    DISPOSE( sorted_queue );
    LINK_TO_ARRAY( first_queue, SQUEUE_DATA, next, sorted_queue );
    LINK_LENGTH( first_queue, SQUEUE_DATA, next, top_squeue );

    qsort( &sorted_queue[0], top_squeue, sizeof( SQUEUE_DATA* ), ( int ( * )( const void*, const void* ) )compare_squeue );
    char raw_msg_att[MIL];
    char raw_msg_sys[MIL];
    char raw_msg_tar[MIL];
    int raw_cnt = 0;
    int raw_dmg = 0;
    int raw_ion_dmg = 0;
    char group_msg_att[MIL];
    char group_msg_sys[MIL];
    char group_msg_tar[MIL];
    char buf[200];
    int group_cnt = 0;

    for ( i = 0; i < top_squeue; i++ )
    {
        if ( !sorted_queue[i] )
            continue;

        sq = sorted_queue[i];
        group_leader = squeue_group_leader( sq );

        // Apply individual event effects here.
        if ( sq->type == SQUEUE_MISSILE_LAUNCH )
            new_missile( sq->dship, sq->target, sq->dch, CONCUSSION_MISSILE );
        else if ( sq->type == SQUEUE_TORPEDO_LAUNCH )
            new_missile( sq->dship, sq->target, sq->dch, PROTON_TORPEDO );
        else if ( sq->type == SQUEUE_ROCKET_LAUNCH )
            new_missile( sq->dship, sq->target, sq->dch, HEAVY_ROCKET );
        else if ( sq->type == SQUEUE_PULSE_LAUNCH )
            new_missile( sq->dship, sq->target, sq->dch, MAGNETIC_PULSE );
        else if ( sq->dch && ( sq->type == SQUEUE_DODGE_ENERGY || sq->type == SQUEUE_DODGE_LOCK ) )
            learn_slow( sq->dch, cache_skill( "shipdodge", &skill_shipdodge ), 4 );

        bool msg_includes_attacker = true;

        if ( sq->type == SQUEUE_MISSILE_HIT || sq->type == SQUEUE_MISSILE_CHAFF ||
                sq->type == SQUEUE_TORPEDO_HIT || sq->type == SQUEUE_TORPEDO_CHAFF ||
                sq->type == SQUEUE_ROCKET_HIT || sq->type == SQUEUE_ROCKET_CHAFF ||
                sq->type == SQUEUE_PULSE_HIT || sq->type == SQUEUE_PULSE_CHAFF )
        {
            msg_includes_attacker = false;
        }

        raw_cnt++;
        raw_dmg += sq->damage;
        raw_ion_dmg += sq->ion_damage;

        if ( group_leader )
            group_cnt++;

        next_sq = i + 1 < top_squeue ? sorted_queue[i + 1] : NULL;
        bool will_destroy_ship = raw_dmg > ( sq->target->shield + sq->target->hull );
        bool next_same_raw = next_sq &&
                             next_sq->target == sq->target &&
                             next_sq->type == sq->type &&
                             (
                                 !msg_includes_attacker ||
                                 next_sq->dship == sq->dship
                             );
        bool next_same_target_and_type = next_sq &&
                                         next_sq->target == sq->target &&
                                         next_sq->type == sq->type;
        // Is the next event for the same squadron or the same battlegroup vs. the same taret?
        bool next_same_group = next_sq &&
                               next_sq->target == sq->target &&
                               next_sq->type == sq->type &&
                               (
                                   !msg_includes_attacker ||
                                   ( group_leader && squeue_group_leader( next_sq ) == group_leader )
                               );
        sqfilter_bg = group_leader && sq->dship->leader != NULL;
        sqfilter_squadron = group_leader && sq->dship->squadleader != NULL;

        // If applicable and ready, print grouped messages.
        if ( group_leader && ( will_destroy_ship || !next_same_group ) )
        {
            sqfilter_raw = false;
            set_squeue_messages( sq, group_leader, group_msg_att, group_msg_sys, group_msg_tar );
            squeue_append_count( group_msg_att, group_cnt );
            squeue_append_count( group_msg_sys, group_cnt );
            squeue_append_count( group_msg_tar, group_cnt );

            if ( !NULLSTR( group_msg_att ) )
            {
                sqfilter_unrelated_pirate = false; // The attacker is always involved
                echo_to_ship_windows_filter( AT_ACTION, group_leader, group_msg_att, sqfilter );
            }

            if ( !NULLSTR( group_msg_sys ) )
            {
                // 3rd party observers can hide pirate spam
                sqfilter_unrelated_pirate = is_pirate( sq->target ) || is_pirate( sq->dship );
                echo_to_system_noqueue_filter( AT_ACTION, sq->target, group_msg_sys, group_leader, sqfilter );
            }

            if ( !NULLSTR( group_msg_tar ) )
            {
                sqfilter_unrelated_pirate = false; // The target is always involved
                echo_to_ship_windows_filter( AT_ACTION, sq->target, group_msg_tar, sqfilter );
            }

            group_cnt = 0;
        }

        // If ready, print raw messages.
        bool show_invincibility = false;
        bool show_invincibility_ion = false;

        if ( will_destroy_ship || !next_same_raw )
        {
            sqfilter_raw = true;
            set_squeue_messages( sq, NULL, raw_msg_att, raw_msg_sys, raw_msg_tar );
            squeue_append_count( raw_msg_att, raw_cnt );
            squeue_append_count( raw_msg_sys, raw_cnt );
            squeue_append_count( raw_msg_tar, raw_cnt );

            if ( !NULLSTR( raw_msg_att ) )
            {
                sqfilter_unrelated_pirate = false; // The attacker is always involved
                echo_to_ship_windows_filter( AT_ACTION, sq->dship, raw_msg_att, sqfilter );
            }

            if ( !NULLSTR( raw_msg_sys ) )
            {
                // 3rd party observers can hide pirate spam
                sqfilter_unrelated_pirate = is_pirate( sq->target ) || is_pirate( sq->dship );
                echo_to_system_noqueue_filter( AT_ACTION, sq->target, raw_msg_sys, sq->dship, sqfilter );
            }

            if ( !NULLSTR( raw_msg_tar ) )
            {
                sqfilter_unrelated_pirate = false; // The target is always involved
                echo_to_ship_windows_filter( AT_ACTION, sq->target, raw_msg_tar, sqfilter );
            }

            // If the target is taking damage and in a squadron, see if we should make it complain about taking hits
            if ( ( raw_dmg + raw_ion_dmg ) > 0 &&
                    in_squadron( sq->target ) &&
                    !sq->target->piloting &&
                    !will_destroy_ship && !next_same_target_and_type
               )
            {
                // If this damage will take out the target's shields...
                if ( sq->target->shield > 0 && ( raw_ion_dmg * 2 + raw_dmg ) > sq->target->shield )
                {
                    switch ( number_range( 1, 3 ) )
                    {
                        case 1:
                            message_to_squadleader( sq->target, "I'm hit, shields down!" );
                            break;

                        case 2:
                            message_to_squadleader( sq->target, "My shields are gone!" );
                            break;

                        case 3:
                            message_to_squadleader( sq->target, "Taking damage, that hit punched through my shields!" );
                            break;
                    }
                }
                // If the ship still has shields up and this damage won't knock them out
                else if ( sq->target->shield > 0 )
                {
                    switch ( number_range( 1, 4 ) )
                    {
                        case 1:
                            message_to_squadleader( sq->target, "Taking hits, but shields are holding." );
                            break;

                        case 2:
                            message_to_squadleader( sq->target, "My shields are dropping fast!" );
                            break;

                        case 3:
                            message_to_squadleader( sq->target, "Taking shield damage!" );
                            break;

                        case 4:
                            message_to_squadleader( sq->target, "Incoming fire absorbed." );
                            break;
                    }
                }
                // If the ship doesn't have any shielding left and is taking hull damage
                else if ( raw_dmg > 0 )
                {
                    switch ( number_range( 1, 3 ) )
                    {
                        case 1:
                            message_to_squadleader( sq->target, "I don't think that hole is supposed to be there..." );
                            break;

                        case 2:
                            message_to_squadleader( sq->target, "Just a scratch..." );
                            break;

                        case 3:
                            message_to_squadleader( sq->target, "Taking hull damage!" );
                            break;
                    }
                }
            }

            if ( raw_ion_dmg > 0 )
            {
                double reduction = raw_cnt * sq->target->shield_boosters * 0.1;
                reduction += number_percent() <= ( int )( reduction * 100 ) % 100 ? 1 : 0;

                if ( reduction > 0 )
                {
                    tune( "process_queue: %s shield boosters reducing %d ion damage by %d", sq->target->name, raw_ion_dmg, ( int )reduction );
                    raw_ion_dmg -= ( int )reduction;
                }

                if ( xIS_SET( sq->target->flags, SHIP_INVINCIBLE ) )
                {
                    show_invincibility_ion = true;
                }
                else
                {
                    damage_ship_ion( sq->target, raw_ion_dmg, raw_ion_dmg, sq->dship );
                }

                raw_ion_dmg = 0;
            }

            if ( raw_dmg > 0 )
            {
                double reduction = raw_cnt * sq->target->shield_boosters * 0.1;
                reduction += number_percent() <= ( int )( reduction * 100 ) % 100 ? 1 : 0;

                if ( reduction > 0 )
                {
                    tune( "process_queue: %s shield boosters reducing %d damage by %d", sq->target->name, raw_dmg, ( int )reduction );
                    raw_dmg -= ( int )reduction;
                }

                if ( xIS_SET( sq->target->flags, SHIP_NADESONLY ) || xIS_SET( sq->target->flags, SHIP_INVINCIBLE ) )
                {
                    show_invincibility = true;
                }
                else
                {
                    damage_ship_full( sq->target, raw_dmg, raw_dmg, sq->dch, sq->dship, sq->type, raw_cnt );
                }

                raw_dmg = 0;
            }

            raw_cnt = 0;
        }

        // We do these at the end of each group of the same target + type, so they only show once per round.
        if ( !next_same_target_and_type )
        {
            if ( show_invincibility_ion )
            {
                snprintf( buf, 200, "%s seems unaffected by the ion blasts.", sq->target->name );
                echo_to_system_noqueue( AT_ORANGE, sq->target, buf, NULL );
            }
            else if ( show_invincibility )
            {
                snprintf( buf, 200, "%s seems to be unaffected by the conventional weapons fire.", sq->target->name );
                echo_to_system_noqueue( AT_ORANGE, sq->target, buf, NULL );
            }
        }
    }

    DISPOSE( sorted_queue );

    for ( sq = first_queue; sq; sq = next_sq )
    {
        next_sq = sq->next;
        UNLINK( sq, first_queue, last_queue, next, prev );
        DISPOSE( sq );
    }

    return;
}

void activate_envirosuit( CHAR_DATA* ch, SHIP_DATA* ship )
{
    char buf[MSL];
    char name[MSL];
    PLANET_DATA* planet, *pfound = NULL;
    SHIP_DATA* envirosuit;
    SPACE_DATA *starsys = NULL;
    OBJ_DATA* evobj;
    int iWear;
    snprintf( buf, MSL, "activate_envirosuit: Launching from %s with %s.", ship->name, ch->name );
    log_string( buf );
    /*
        Check with FASTSHIP, make sure there's a pod template
    */
    SHIP_TEMPLATE_DATA* template = find_shiptemplate( "envirosuit.img" );

    if ( !template )
    {
        bug( "activate_envirosuit: could not locate envirosuit.img template" );
        return;
    }
    if (ship->starsystem)
        starsys = ship->starsystem;
    else if (ship->in_room)
        starsys = starsystem_from_vnum(ship->in_room->vnum);
    if ( ship->shipstate == SHIP_HYPERSPACE || !starsys )
    {
        return;
    }

    ch_println( ch, "As the ship is ripped apart around you, you manage to push away from the debris with the help of your envirosuit but you don't think your oxygen will last forever." );
    snprintf( buf, MSL, "As %s explodes, a small humanoid shape seems to float away from the rubble.", ship->name );
    echo_to_system_noqueue( AT_RED, ship, buf, NULL );
    /*
        Call FASTSHIP. Cook up an envirosuit
    */
    RACE_DATA *chrace = ch->disguise ? ch->disguise->race : ch->race;

    switch ( chrace->size )
    {
        case 0:
            snprintf( name, MSL, "A humanoid size Envirosuit" );
            break;

        case 1:
            snprintf( name, MSL, "A massive size Envirosuit" );
            break;

        case 2:
            snprintf( name, MSL, "A large size Envirosuit" );
            break;

        case 3:
            snprintf( name, MSL, "A small size Envirosuit" );
            break;
    }

    envirosuit = make_ship( NULL, template, name );
    SET_STRING( envirosuit->shipowner, ch->name );
    envirosuit->clan = NULL;

    ship_to_starsystem( envirosuit, starsys );
    envirosuit->location = 0;
    vector_copy( &envirosuit->vpos, &ship->vpos );
    /*
        Activate enviro suit configuration
    */
    envirosuit->currspeed = envirosuit->realspeed;
    envirosuit->eject_beacon_id = ship->eject_beacon_id;
    envirosuit->shipstate = SHIP_READY;
    envirosuit->autorecharge = TRUE;
    envirosuit->shield = envirosuit->maxshield;
    xSET_BIT( envirosuit->flags, SHIP_ENVIROSUIT );
    xSET_BIT( envirosuit->flags, SHIP_INVINCIBLE );
    envirosuit->shipstate = SHIP_DISABLED;
    envirosuit->selfd_time = sysdata.envirotimer;   /* Activate self destruct */
    envirosuit->selfd_armed = TRUE;
    envirosuit->dock_install = FALSE;
    Vector3 tempvect;
    vector_init( &tempvect );
    tempvect.x = ship->head.x >= 0 ? ship->head.x + number_range( 100, 10000 ) : ship->head.x + number_range( -10000, -100 );
    tempvect.y = ship->head.y >= 0 ? ship->head.y + number_range( 100, 10000 ) : ship->head.y + number_range( -10000, -100 );
    tempvect.z = ship->head.z >= 0 ? ship->head.z + number_range( 100, 10000 ) : ship->head.z + number_range( -10000, -100 );
    ship_set_course( envirosuit, &tempvect );
    ship_move( envirosuit );

    /*
        Lookup the closest non-star planet in the system.
    */
    for ( planet = envirosuit->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( !xIS_SET( planet->flags, PLANET_STAR ) && planet->first_area )
        {
            double distA = 0;
            double distB = 0;

            if ( pfound == NULL )
            {
                pfound = planet;
            }
            else
            {
                distA =  vector_distance( &envirosuit->vpos, &planet->pos );
                distB = vector_distance( &envirosuit->vpos, &pfound->pos );

                if ( distA < distB )
                    pfound = planet;
            }
        }
    }

    /*
        If we found a close planet, alter trajectory. Else, Cut speed to 1/3.
    */
    if ( pfound )
    {
        ship_set_course( envirosuit, &pfound->pos );
    }
    else
    {
        envirosuit->currspeed = ( envirosuit->realspeed / 3 );
    }

    char_from_room( ch );
    char_to_room( ch, get_room_index( envirosuit->cockpit ) );

    for ( iWear = 0; iWear < MAX_WEAR; iWear++ )
    {
        if ( ( evobj = get_eq_char( ch, iWear ) ) != NULL )
        {
            if ( xIS_SET( evobj->extra_flags, ITEM_ENVIROSUIT ) )
            {
                unequip_char( ch, evobj );
                make_scraps( evobj );
                break;
            }
        }
    }

    save_ship( envirosuit, true );
    log_string( "activate_envirosuit: Enviro Suit successfully launched." );
    return;
}
void activate_pod( CHAR_DATA* ch, SHIP_DATA* ship )
{
    char buf[MSL];
    PLANET_DATA* planet, *pfound = NULL;
    SHIP_DATA* escape;
    snprintf( buf, MSL, "activate_pod: Launching from %s with %s.", ship->name, ch->name );
