    ship_to_starsystem( escape, ship->starsystem );
    escape->location = 0;
    vector_copy( &escape->vpos, &ship->vpos );
    /*
        Activate escape pod configuration
    */
    escape->currspeed = escape->realspeed;
    escape->eject_beacon_id = ship->eject_beacon_id;
    escape->shipstate = SHIP_READY;
    escape->autorecharge = TRUE;
    escape->shield = escape->maxshield;
    xSET_BIT( escape->flags, SHIP_ESCAPEPOD );
    /*
        Match owners heading for the moment
    */
    vector_copy( &escape->head, &ship->head );

    /*
        Lookup the closest non-star planet in the system.
    */
    for ( planet = escape->starsystem->first_planet; planet; planet = planet->next_in_system )
    {
        if ( !xIS_SET( planet->flags, PLANET_STAR ) && planet->first_area )
        {
            double distA = 0;
            double distB = 0;

            if ( pfound == NULL )
            {
                pfound = planet;
            }
            else
            {
                distA =  vector_distance( &escape->vpos, &planet->pos );
                distB = vector_distance( &escape->vpos, &pfound->pos );

                if ( distA < distB )
                    pfound = planet;
            }
        }
    }

    /*
        If we found a close planet, alter trajectory. Else, Cut speed to 1/3.
    */
    if ( pfound )
    {
        ship_set_course( escape, &pfound->pos );
    }
    else
    {
        escape->currspeed = ( escape->realspeed / 3 );
    }

    char_from_room( ch );
    char_to_room( ch, get_room_index( escape->cockpit ) );
    save_ship( escape, true );
    log_string( "activate_pod: Escape Pod successfully launched." );
    return;
}

bool deploy_pod( SHIP_DATA* ship, PLANET_DATA* planet )
{
    char buf[MSL];
    ROOM_INDEX_DATA* fRoom;
    CHAR_DATA* rch;
    OBJ_DATA* obj;
    int safty = 0;

    if ( !planet->first_area )
        return FALSE;

    ROOM_INDEX_DATA* tRoom = get_random_eject_room( planet, ship );
    if ( !tRoom )
        return FALSE;

    snprintf( buf, MSL, "You hurtle towards the surface of %s.", planet->name );
    echo_to_ship_windows( AT_YELLOW, ship, buf );
    snprintf( buf, MSL, "%s hurtles towards the surface of %s.", ship->name, planet->name );
    echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
    snprintf( buf, MSL, "&z%s hurtles across the sky leaving a trail of black smoke.", ship->name );
    echo_to_planet_outdoors( planet, buf );
    snprintf( buf, MSL, "Escape pod touched down at %d.", tRoom->vnum );
    log_string( buf );
    /*
        Create the Escape Pod Wreckage
    */
    obj = create_object( get_obj_index( OBJ_VNUM_ESCAPE_POD ), 0 );

    if ( obj && obj != NULL )
    {
        obj = obj_to_room( obj, tRoom );
        obj->timer = 8;
    }

    for ( fRoom = ship->first_room; fRoom; fRoom = fRoom->next_in_range )
    {
        rch = fRoom->first_person;

        while ( rch != NULL && safty < 99 )
        {
            if ( !rch || rch == NULL )
                break;

            safty++;
            char_from_room( rch );
            char_to_room( rch, tRoom );
            ch_println( rch, "&RYour body is thrown from the escape pod as it crashes down!" );
            ch_println( rch, "&RYou're ALIVE!" );
            act( AT_MAGIC, "$n is thrown from the escape pod as it crashes!", rch, NULL, NULL, TO_ROOM );
            rch->hit = URANGE( 1, rch->hit - ( int )( ( double )( rch->hit ) * ( double )( 0.3 ) ), rch->max_hit );
            do_look( rch, "auto" );
            WAIT_STATE( rch, 6 );
            rch = fRoom->first_person;
        }

        if ( safty >= 99 )
        {
            bug( "deploy_pod: Exceeded 99 passenger safety eject limit. Aborting." );
            return FALSE;
        }
    }

    delete_ship( ship );
    return TRUE;
}

/*
    Attempt to launch an Escape Pod from the current room.
*/
CMDF do_escape( CHAR_DATA* ch, char* argument )
{
    /*
        char buf[MSL];
    */
    ESCAPE_DATA* escape;
    SHIP_DATA* ship;

    if ( !ch->in_room )
        return;

    ship = get_ship_from_room( ch->in_room );

    if ( !ship )
    {
        ch_println( ch, "&RMaybe if you were onboard a ship. That might help." );
        return;
    }

    escape = escape_from_room( ch->in_room->vnum );

    if ( !escape )
    {
        ch_println( ch, "&RBuddy, You're not even in the right room to fire off an escape pod." );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can only do that in realspace." );
        return;
    }

    /*   if ( ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ship->hull > ( ship->hull / 80 ) )
        {
           ch_println( ch, "Due to abuse, you can no longer use escape pods until the vessel is disabled." );
           return;
        }*/
    if ( escape->pods <= 0 )
    {
        ch_println( ch, "&R[ALERT]: Escape Pods depleted. Try another launch chamber." );
        return;
    }

    if ( str_cmp( argument, "now" ) )
    {
        ch_println( ch, "&RThis command will cause you to ditch ship. Type ESCAPE NOW to confirm." );
        return;
    }

    if ( IS_NPC( ch ) )
    {
        do_say( ch, "Were all going to die! Aiiiiiii!" );
    }

    escape->pods--;
    act( AT_ACTION, "$n steps into the cramped escape pod.", ch, NULL, NULL, TO_ROOM );
    act( AT_ACTION, "You step into the cramped escape pod.", ch, NULL, NULL, TO_CHAR );
    echo_to_room( AT_YELLOW, escape->room, "The escape pod emits a hissing sound as the hatch swings shut." );
    /*
        'Pods away, Captain!
    */
    activate_pod( ch, ship );
    echo_to_room( AT_RED, escape->room, "With a roar, the ejection pod explodes out the launch tube." );
    echo_to_room( AT_RED, ch->in_room, "The escape pod rumbles and shakes as it rockets out of the tube." );
    return;
}

bool ship_hail( CHAR_DATA* ch, char* argument )
{
    char buf1[MSL];
    char buf2[MSL];
    char arg1[MSL];
    SHIP_DATA* target;
    SHIP_DATA* ship;
    argument = one_argument( argument, arg1 );
    ship = get_ship_from_room( ch->in_room );

    if ( !ship )
        return FALSE;

    if ( arg1[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CHAIL (ship) (message)" );
        ch_println( ch, "&R Can only be used from the bridge." );
        return TRUE;
    }

    ship = get_ship_from_cockpit( ch->in_room );

    if ( !ship )
    {
        ch_println( ch, "&zSyntax: &CHAIL (ship) (message)" );
        ch_println( ch, "&R Can only be used from the bridge." );
        return TRUE;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RDisengage your cloaking if you want to communicate." );
        return FALSE;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return TRUE;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can only do that in realspace." );
        return TRUE;
    }

    // GRAL Stopped hail while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak through the ship's communication but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't use ship communications while gagged." );
        return TRUE;
    }

    target = get_ship_here( arg1, ship->starsystem );

    if ( !target || target == ship || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RUnable to locate any ship by that name." );
        return TRUE;
    }

    ROOM_INDEX_DATA* room = NULL;
    TURRET_DATA* turret = NULL;
    CHAR_DATA* vic = NULL;

    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        if ( room->vnum == ship->cockpit || room->vnum == ship->navseat
                || room->vnum == ship->pilotseat || room->vnum == ship->coseat || room->vnum == ship->gunseat || room->vnum == ship->engineroom )
        {
            for ( vic = room->first_person; vic; vic = vic->next_in_room )
            {
                if ( !IS_AWAKE( vic ) )
                    continue;

                /*
                    bug("Sending %s to %s.", argument, vic->name );
                */
                snprintf( buf2, MSL, "&z[&WBroadcasting Hail to %s&z]&W( &z%s&W)%s&z: %s%s", target->name, tone_convert( ch, vic ),
                         lang_convert_format( vic, ch->speaking, ch ), txtclr( ch ), knows_language( vic, ch->speaking, ch ) ? argument : scramble_text( argument, ch->speaking ) );
                set_char_color( -1, vic );
                send_to_char( buf2, vic );
                ch_println( vic, "" );
            }
        }
    }

    for ( turret = ship->first_turret; turret; turret = turret->next )
    {
        if ( !turret || turret == NULL )
            break;

        if ( turret->room )
        {
            for ( vic = turret->room->first_person; vic; vic = vic->next_in_room )
            {
                snprintf( buf2, MSL, "&z[&WBroadcasting Hail to %s&z]&W( &z%s&W)%s&z: %s%s", target->name, tone_convert( ch, vic ),
                         lang_convert_format( vic, ch->speaking, ch ), txtclr( ch ), knows_language( vic, ch->speaking, ch ) ? argument : scramble_text( argument, ch->speaking ) );
                send_to_char( buf2, vic );
                ch_println( vic, "" );
            }
        }
    }

    for ( room = target->first_room; room; room = room->next_in_range )
    {
        if ( room->vnum == target->cockpit || room->vnum == target->navseat
                || room->vnum == target->pilotseat || room->vnum == target->coseat || room->vnum == target->gunseat || room->vnum == target->engineroom )
        {
            for ( vic = room->first_person; vic; vic = vic->next_in_room )
            {
                if ( !IS_AWAKE( vic ) )
                    continue;

                /*
                    bug("Sending %s to %s.", argument, vic->name );
                */
                snprintf( buf1, MSL, "&z[&WHail from %s&z]&W( &z%s&W)%s&z: %s%s", ship->name, tone_convert( ch, vic ),
                         lang_convert_format( vic, ch->speaking, ch ), txtclr( ch ), knows_language( vic, ch->speaking, ch ) ? argument : scramble_text( argument, ch->speaking ) );
                set_char_color( -1, vic );

                if ( !vic->desc && IS_NPC( vic ) )
                {
                    lua_trigger_on_ch_act( vic, ch, buf1 );

                    if ( IS_SET( vic->pIndexData->progtypes, ACT_PROG ) )
                        mprog_act_trigger( buf1, vic, ch, NULL, NULL );
                }
                else
                {
                    send_to_char( buf1, vic );
                    ch_println( vic, "" );
                }
            }
        }
    }

    for ( turret = target->first_turret; turret; turret = turret->next )
    {
        if ( !turret || turret == NULL )
            break;

        if ( turret->room )
        {
            for ( vic = turret->room->first_person; vic; vic = vic->next_in_room )
            {
                snprintf( buf1, MSL, "&z[&WHail from %s&z]&W( &z%s&W)%s&z: %s%s", ship->name, tone_convert( ch, vic ),
                         lang_convert_format( vic, ch->speaking, ch ), txtclr( ch ), knows_language( vic, ch->speaking, ch ) ? argument : scramble_text( argument, ch->speaking ) );

                if ( !vic->desc && IS_NPC( vic ) )
                {
                    lua_trigger_on_ch_act( vic, ch, buf1 );

                    if ( IS_SET( vic->pIndexData->progtypes, ACT_PROG ) )
                        mprog_act_trigger( buf1, vic, ch, NULL, NULL );
                }
                else
                {
                    send_to_char( buf1, vic );
                    ch_println( vic, "" );
                }
            }
        }
    }

    return TRUE;
}

CMDF do_makeinterceptor( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char arg2[MIL];
    SHIP_DATA* ship, *onship;
    bool resetfly = FALSE, resetland = FALSE;
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );

    if ( argument[0] == '\0' || arg[0] == '\0' || arg2[0] == '\0' )
    {
        send_to_char( "Usage: makeinterceptor <owner> <image> <name>\n"
                      "This function will automatically set the home of the ship to " "the ship you are on.", ch );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_CAN_LAND ) )
    {
        xSET_BIT( ch->in_room->flags, ROOM_CAN_LAND );
        resetland = TRUE;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_CAN_FLY ) )
    {
        xSET_BIT( ch->in_room->flags, ROOM_CAN_FLY );
        resetfly = TRUE;
    }

    SHIP_TEMPLATE_DATA* template = find_shiptemplate( arg2 );

    if ( !template )
    {
        ch_println( ch, "&RUnable to locate that ship template. Recheck your spelling." );
        return;
    }

    ship = make_ship( ch, template, argument );

    if ( get_trust( ch ) > LEVEL_HERO )
    {
        if ( ship != NULL )
        {
            ch_println( ch, "&YFASTSHIP Complete. Have a nice day." );
        }
        else
        {
            ch_println( ch, "&R[WARNING]: Fault in FASTSHIP system. No ship returned." );
        }
    }

    SET_STRING( ship->shipowner, str_cmp( arg, "none" ) ? arg : "" );
    ship->clan = !NULLSTR( ship->shipowner ) ? get_clan( ship->shipowner ): NULL;

    if ( ( onship = get_ship_from_room( ch->in_room ) ) != NULL )
    {
        SET_STRING( ship->homeship, onship->name );
        ch_println( ch, "%s has been added to %s's interceptor roster.", ship->name, onship->name );
    }

    if ( !str_cmp( arg, "pirate" ) || !str_cmp( arg, "Pirate" ) || !str_cmp( arg, "Pirates" ) )
        xSET_BIT( ship->flags, SHIP_NODELETE );

    xSET_BIT( ship->flags, SHIP_CAN_INTERCEPT );
    xSET_BIT( ship->aflags, AFLAG_AUTOSHIELD );
    xSET_BIT( ship->aflags, AFLAG_USELAUNCHER );
    xSET_BIT( ship->aflags, AFLAG_USELASER );
    xSET_BIT( ship->aflags, AFLAG_USEION );
    ship->autopilot = TRUE;
    ship->shipyard = ch->in_room->vnum;
    save_ship( ship, true );
    ch_println( ch, "Makeinterceptor COMPLETE: %s", ship->name );

    if ( resetland )
        xREMOVE_BIT( ch->in_room->flags, ROOM_CAN_LAND );

    if ( resetfly )
        xREMOVE_BIT( ch->in_room->flags, ROOM_CAN_FLY );

    return;
}

