int tune_ship_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou stop tuning the ship." );
    act( AT_ACTION, "$n stops what $e was doing.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int tune_ship_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    if ( !valid_ship( ship ) || ship->in_room != ch->in_room )
    {
        ch_println( ch, "&RThe ship you were working on has disappeared!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !can_mod_ship( ch, ship ) )
    {
        ch_println( ch, "You need to be the registered owner, pilot or copilot of the ship in order to tune it." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( xIS_SET( ship->flags, SHIP_TUNED ) )
    {
        ch_println( ch, "This vessel has already been tuned." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chance = IS_NPC( ch ) ? number_percent(  ) : ( int )get_learned_pct( ch, cache_skill( "tuneship", &skill_tuneship ) );
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RHmm, you didn't do much of anything." );
        learn_from_failure( ch, cache_skill( "tuneship", &skill_tuneship ) );
        return E_LOTJ_SUCCESS;
    }

    int tuneamt = IS_NPC( ch ) ? ch->top_level : UMIN( ch->skill_level[ENGINEERING_ABILITY], 150 );
    tuneamt = ( tuneamt + number_percent() ) / 2; // At 150 eng, this can be 75-125

    // 5% chance of a perfect tune, so some ships are extra good
    if ( number_percent() > 95 )
    {
        ch_println( ch, "&GYou tuned the ship perfectly, achieving exceptional results!" );
        tuneamt = 200;
        xSET_BIT( ship->flags, SHIP_PERFECT_TUNE );
    }

    // Fighter:     7.5 -  12.5 (  25)
    // Transport:  15   -  25   (  50)
    // Freighter:  22.5 -  37.5 (  75)
    // Gunboat:    30   -  50   ( 100)
    // Corvette:   37.5 -  62.5 ( 125)
    // Frigate:    45   -  75   ( 150)
    // Cruiser:    52.5 -  87.5 ( 175)
    // Battleship: 60   - 100   ( 200)
    tuneamt *= ( ship->classtype + 1 ) * 10;
    ship->maxquota += tuneamt;
    xSET_BIT( ship->flags, SHIP_TUNED );
    save_ship( ship, true );
    act( AT_GREEN, "You finish tuning $T.", ch, NULL, ship->name, TO_CHAR );
    act( AT_ACTION, "$n finishes tuning $T.", ch, NULL, ship->name, TO_ROOM );
    learn_from_success( ch, cache_skill( "tuneship", &skill_tuneship ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_tune_ship( CHAR_DATA* ch, char* argument )
{
    if ( !xIS_SET( ch->in_room->flags, ROOM_GARAGE ) && !xIS_SET( ch->in_room->flags, ROOM_MODSHIPS ) )
    {
        ch_println( ch, "&RYou need to be in a garage to make major changes!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Which ship would you like to do this to?" );
        return;
    }

    SHIP_DATA* ship = ship_in_room( ch->in_room, argument );
    if ( !ship )
    {
        ch_println( ch, "You don't see a ship like that nearby." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_TUNED ) )
    {
        ch_println( ch, "This vessel has already been tuned." );
        return;
    }

    if ( !can_mod_ship( ch, ship ) )
    {
        ch_println( ch, "You need to be the registered owner, pilot or copilot of the ship in order to tune it." );
        return;
    }

    int seconds = 90;
    if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "spacecraft", &skill_spacecraft ) ) == 100 ) // Cut time required in half if science is mastered.
    {
        seconds = seconds / 2;
        ch_println( ch, "&GYour knowledge in spacecraft design allows you to work faster." );
    }

    ch_println( ch, "&WYou begin tuning the spacecraft." );
    act( AT_PLAIN, "$n begins tuning $T.", ch, NULL, ship->name, TO_ROOM );
    action_set( ch, NULL, strfmt("is tuning %s.", ship->name), NULL, 0 );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, seconds, tune_ship_complete, tune_ship_abort, FUNC );
    timer->buffer->ship = ship;
}


bool can_mod_ship( CHAR_DATA* ch, SHIP_DATA* ship )
{
    if ( !ch || !ship )
        return FALSE;

    if ( IS_IMMORTAL( ch ) )
        return TRUE;

    if ( IS_NPC( ch ) )
        return TRUE;

    if ( !str_cmp( ship->pilot, ch->name ) )
        return TRUE;

    if ( !str_cmp( ship->copilot, ch->name ) )
        return TRUE;

    if ( !str_cmp( ship->shipowner, ch->name ) )
        return TRUE;

    if ( ch->pcdata->clan )
    {
        return check_clanpilot( ch, ship );
    }

    return FALSE;
}

