        return false;

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
        return false;

    return number_percent() >= 50;
}

bool ship_dodge( SHIP_DATA* ship, SHIP_DATA* attacker, bool energy_weapon )
{
    if ( !ship || !attacker || ship->classtype > FRIGATE_SHIP || ( ship->dock_state == DOCK_DOCKED && !ship->dock_lead && ship->dockship && ship->dockship->classtype > ship->classtype ) )
        return false;

    SHIP_DATA* squadleader = ship->squadleader;
    CHAR_DATA* ch = ship->piloting;
    CHAR_DATA* squadpilot = NULL;

    if ( squadleader && ship != squadleader && ship->starsystem == squadleader->starsystem && squadleader->piloting )
        squadpilot = squadleader->piloting;

    bool auto_dodge = autofly( ship ) && xIS_SET( ship->flags, SHIP_AUTO_DODGE );

    // If a squadron leader is set to have autododge, its members inherit that.
    if ( squadleader && ship != squadleader && squadleader->starsystem == ship->starsystem )
        auto_dodge = autofly( squadleader ) && xIS_SET( squadleader->flags, SHIP_AUTO_DODGE );

    if ( !ch && !auto_dodge && !squadpilot )
        return false;

    if ( ship->classtype >= CORVETTE_SHIP && ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED ) )
        return false;

    double dodge_chance = ship->maneuver / 3.0;
    // Bonus for dodging against larger ships, penalty if attacker is the same or smaller than you.
    dodge_chance += ( attacker->classtype - ( ship->classtype + 1 ) ) * 5;
    CHAR_DATA* dodge_skill_ch = ch ? ch : squadpilot;

    if ( dodge_skill_ch && !IS_NPC( dodge_skill_ch ) )
    {
        dodge_chance *= get_learned_pct( dodge_skill_ch, cache_skill( "shipdodge", &skill_shipdodge ) ) / 100.0;

        // Evading means 25% fewer hits should get through.
        // To do that, we take the remaining chance to score a hit and add 25% of that to the dodge chance.
        if ( has_feat( dodge_skill_ch, cache_skill( "evading", &skill_evading ) ) )
            dodge_chance += ( 100 - dodge_chance ) * 0.25;
    }

    // Extra dodge boost if a cruiser+ is attacking a tiny ship.
    if ( attacker->classtype > FRIGATE_SHIP && ship->classtype <= TRANSPORT_SHIP )
        dodge_chance += 10;

    // Extra penalty for frigate dodging.
    if ( ship->classtype == FRIGATE_SHIP )
        dodge_chance -= 10;

    // Vong get -50% incoming damage from dovin basal, so they get half dodge chance to balance.
    if ( xIS_SET( ship->flags, SHIP_VONG ) )
        dodge_chance /= 2;

    dodge_chance = URANGE( 10, dodge_chance, 95 );
    tune( "ship_dodge: %s (pilot: %s) has %.2f%% dodge chance against %s", ship->name, (ch && !char_extracted( ch )) ? ch->name : "null", dodge_chance, attacker->name );

    if ( number_percent() <= dodge_chance )
    {
        add_queue( ship, energy_weapon ? SQUEUE_DODGE_ENERGY : SQUEUE_DODGE_LOCK, 0, 0, ch, attacker );

        if ( number_range( 1, 8 ) == 1 && ship->squadleader && ship->squadleader != ship && !ship->piloting )
            message_to_squadleader( ship, "Taking evasive action!" );

        return TRUE;
    }
    else
        return FALSE;
}

