int compare_ships_leader( SHIP_DATA** s1p, SHIP_DATA** s2p )
{
    SHIP_DATA* s1 = ( *s1p );
    SHIP_DATA* s2 = ( *s2p );
    int result = ( long )( ( s2->leader ? s2->leader : s2->squadleader ) - ( s1->leader ? s1->leader : s1->squadleader ) ) % INT_MAX;

    if ( result == 0 )
        result = s2->pos - s1->pos;

    return result;
}

CMDF do_fleetradar( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship;

    /*
        Patch to negate possed mobs and pets
    */
    if ( IS_NPC( ch ) && ch->master != NULL )
        return;

    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit or turret of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RWait until after you launch!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "&RThe ship's communications array is completely fried!" );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't use the radar while cloaked!" );
        return;
    }

    if ( ship->starsystem == NULL )
    {
        ch_println( ch, "&RYou can't do that unless the ship is flying in realspace!" );
        return;
    }

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "navigation", &skill_navigation ) ) );

    if ( number_percent(  ) > chance )
    {
        ch_println( ch, "&RYou fail to work the controls properly." );
        learn_from_failure( ch, cache_skill( "navigation", &skill_navigation ) );
        return;
    }

    act( AT_PLAIN, "$n checks the radar.", ch, NULL, argument, TO_ROOM );
    set_char_color( AT_WHITE, ch );
    int ship_cnt = 0;
    SHIP_DATA* ships[500];
    bool targets_only = FALSE;

    if ( !str_cmp( argument, "targets" ) )
    {
        ch_println( ch, "&wAvailable targets in %s:&w", ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
        targets_only = true;
    }
    else
    {
        ch_println( ch, "%s", ship->starsystem->virtualsys ? "Uncharted space" : ship->starsystem->name );
    }

    for ( SHIP_DATA* rship = ship->starsystem->first_ship; rship; rship = rship->next_in_starsystem )
    {
        if ( rship->cloakstatus == CLOAK_ON && !IS_IMMORTAL( ch ) )
            continue;

        if ( targets_only )
        {
            if ( same_group( rship, ship ) )
                continue;

            if ( is_protected( ship, rship, get_turret_room( ship, ch->in_room ) ) )
                continue;
        }

        ships[ship_cnt++] = rship;

        if ( ship_cnt == 500 )
        {
            ch_println( ch, "&RThere are too many ships in this location." );
            break;
        }
    }

    if ( ship_cnt == 0 )
    {
        ch_println( ch, "\nNone." );
        return;
    }

    qsort( &ships[0], ship_cnt, sizeof( SHIP_DATA* ), ( int ( * )( const void*, const void* ) )compare_ships_leader );
    SHIP_DATA* last_leader = NULL;
    SHIP_DATA* si = NULL;
    SHIP_DATA* si_leader = NULL;

    for ( int i = 0; i < ship_cnt; i++ )
    {
        si = ships[i];
        si_leader = si->leader ? si->leader : si->squadleader;

        if ( si_leader != last_leader )
        {
            if ( !si_leader )
                ch_println( ch, "\n&CIndependent ships:" );
            else if ( si_leader->starsystem != ship->starsystem )
                ch_println( ch, "\n&CUnknown lead ship:" );
            else if ( is_squadleader( si_leader ) )
                ch_println( ch, "\n&C%ss squadron:", si_leader->name );
            else
                ch_println( ch, "\n&C%ss battlegroup:", si_leader->name );
        }

        last_leader = si_leader;
        ch_println( ch, "%s%-53s%s %s%s %.0f %.0f %.0f",
                   si->target0 == ship ? "&R" : "&B",
                   si->name,
                   si->target0 == ship && has_pcflag( ch, PCFLAG_SCREENREADER ) ? " (targeting you)" : "",
                   si->target0 == ship ? "&R" : "&C",
                   !si_leader ? "     " : si->pos == 3 ? "(Ctr)" : si->pos == 2 ? "(Mid)" :  "(Out)",
                   si->vpos.x, si->vpos.y, si->vpos.z );
    }

    ch_println( ch, "\n&WYour Coordinates: %.0f %.0f %.0f", ship->vpos.x, ship->vpos.y, ship->vpos.z );
    learn_from_success( ch, cache_skill( "navigation", &skill_navigation ) );
}

CMDF do_battlegroup( CHAR_DATA* ch, char* argument )
{
    SHIP_DATA* ship = NULL, *target = NULL;
    char arg[MIL];
    char buf[MSL];
    double x = 0.0;
    int nrg = 0, hull = 0, shields = 0, crew = 0, cnt = 0;

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL
            && ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL
            && ( ship = get_ship_from_gunseat( ch->in_room ) ) == NULL )
    {
        if ( get_ship_from_room( ch->in_room ) )
        {
            ch_println( ch, "Get to the pilot seat to do this." );
            return;
        }

        ch_println( ch, "&RIt'd help if you were on a ship." );
        return;
    }

    if ( !ship->starsystem )
    {
        ch_println( ch, "Get in space first!" );
        return;
    }

    /*  if ( xIS_SET(ship->flags, SHIP_JAMMED) ) {
        ch_println( ch, "The radar is jammed!" );
        return;
        }*/
    if ( xIS_SET( ship->flags, SHIP_COMM_DISABLED ) || xIS_SET( ship->flags, SHIP_COMM_DESTROYED ) )
    {
        ch_println( ch, "The comm system is fried!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
        {
            x = ( double )target->energy;
            x /= target->maxenergy;
            x *= 100;
            nrg = ( int )x;
            x = ( double )target->hull;
            x /= target->maxhull;
            x *= 100;
            hull = ( int )x;
            x = ( double )target->shield;
            x /= target->maxshield;
            x *= 100;
            shields = ( int )x;

            crew = ship_crew_count( target, NULL );

            if ( target->leader == target )
                snprintf( buf, MSL, "[ &RL &W]" );
            else
                snprintf( buf, MSL, "[&C%.3d&W]", ++cnt );

            pager_println( ch,
                          "&W%s &w%-13s&z:&W%-35s &w-&c<&zPos&w:&C%s&c>&w-\n &wEnergy: %s%.3d%%&W|&wHull: %s%.3d%%&W|&wShields: %s%.3d%%&W|&wCrew: &C%.3d&w|&WSystem: &O%s &W%d&z/&W%d",
                          buf, class_types[target->classtype], target->name, print_bpos( target->pos ),
                          nrg >= 75 ? "&G" : nrg >= 25 ? "&Y" : "&R", nrg,
                          hull >= 75 ? "&G" : hull >= 25 ? "&Y" : "&R", hull,
                          shields >= 75 ? "&G" : shields >= 25 ? "&Y" : "&R", shields,
                          crew,
                          target->starsystem ? target->starsystem->name : "Docked",
                          target->starsystem ? target->starsystem->xpos : 0,
                          target->starsystem ? target->starsystem->ypos : 0 );

            if ( target->target0 )
            {
                x = ( double )target->target0->energy;
                x /= target->target0->maxenergy;
                x *= 100;
                nrg = ( int )x;
                x = ( double )target->target0->hull;
                x /= target->target0->maxhull;
                x *= 100;
                hull = ( int )x;
                pager_println( ch, "    &RTargetting: &r%s:&R%-25s &W%.3d%%&R|&W%.3d%%&R",
                              class_types[target->target0->classtype], target->target0->name, nrg, hull );
            }
        }

        return;
    }

    argument = one_argument( argument, arg );

    if ( !str_cmp( "join", arg ) )
    {
        if ( xIS_SET( ship->flags, SHIP_VONG ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "&RYuuzhan Vong ships don't network in that way." );
            return;
        }

        if ( ship->classtype >= BATTLESHIP_SHIP )
        {
            ch_println( ch, "You can only be a battlegroup leader." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cbattlegroup join <&wtarget ship&C>&w" );
            return;
        }

        if ( ( target = get_ship_here( argument, ship->starsystem ) ) == NULL )
        {
            ch_println( ch, "You see no ship like that here." );
            return;
        }

        if ( in_battlegroup( ship ) )
        {
            ch_println( ch, "You must quit the battlegroup you're already in." );
            return;
        }

        //Allow frigates to join BGs, but not lead them. - Gathorn 7May16
        if ( target->classtype < CRUISER_SHIP )
        {
            ch_println( ch, "Battlegroups can only be formed around ships of cruiser size or larger." );
            return;
        }

        //Ifcheck added above makes the second have of this ifcheck unncessary. - Gathorn 7May16
        if ( ship->classtype < FRIGATE_SHIP ) // || target->classtype < FRIGATE_SHIP)// && ( target->classtype != FIGHTER_SHIP || ship->classtype != FIGHTER_SHIP ) )
        {
            ch_println( ch, "Battlegroups are formed by capital class ships." );
            return;
        }

        if ( xIS_SET( target->flags, SHIP_NADESONLY ) )
        {
            ch_println( ch, "That ship isn't eligible to join battlegroups." );
            return;
        }

        ship->join = target;
        ch_println( ch, "You broadcast the battlegroup query to that ship." );
        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s\n requesting to join your battlegroup.\n", ship->name );
        echo_to_ship_windows( AT_GREEN, target, buf );
        act( AT_ACTION, "$n sends a battlegroup request.", ch, NULL, NULL, TO_ROOM );
    }
    else if ( !str_cmp( "autotrack", arg ) )
    {
        if ( ship->leader != ship )
        {
            ch_println( ch, "Only the leader ship can do this." );
            return;
        }

        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s is affecting autotracking.\n", ship->name );

        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
        {
            ship->autotrack = argument[0] == '\0' ? !ship->autotrack : !str_cmp( "on", argument ) ? TRUE : FALSE;
            echo_to_ship_windows( AT_ACTION, target, buf );
            save_ship( target, true );
        }
    }
    else if ( !str_cmp( "target", arg ) )
    {
        if ( ship->leader != ship )
        {
            ch_println( ch, "You need to be in a battlegroup leader to issue targeting orders." );
            return;
        }

        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        if ( NULLSTR( argument ) )
        {
            send_to_char( "&zSyntax: &Cbattlegroup target <&wship&z/&wall&C> <&wtarget&C>\n"
                          " &C*&z- This only works on unmanned ships.&w\n", ch );
            return;
        }

        SHIP_DATA* new_target;

        if ( !str_cmp( "none", argument ) )
        {
            new_target = NULL;
        }
        else
        {
            new_target = get_ship_here( argument, ship->starsystem );

            if ( new_target == NULL || new_target->cloakstatus == CLOAK_ON )
            {
                ch_println( ch, "&RThat ship isn't here!" );
                return;
            }

            if ( is_protected( ship, new_target, false ) )
            {
                ch_println( ch, "&RThat ship is currently being protected by other ships." );
                return;
            }

            if ( new_target == ship )
            {
                ch_println( ch, "&RYou can't target your own ship!" );
                return;
            }

            if ( vector_distance( &ship->vpos, &new_target->vpos ) > ( ( ship->classtype + 1 ) * 2500 ) )
            {
                ch_println( ch, "&RThat ship is too far away to target." );
                return;
            }

            if ( new_target->safe_orbital )
            {
                ch_println( ch, "&RTargetting that vessel violates the rules set under HELP CAPITALRULES." );
                return;
            }
        }

        if ( !str_cmp( "all", arg2 ) )
        {
            ch_println( ch, "&wYou order the target change." );

            for ( target = ship->first_in_bg; target; target = target->next_in_bg )
            {
                if ( target->starsystem != ship->starsystem )
                    continue;

                // Ships in a BG can't target themselves
                if ( target == new_target )
                    continue;

                target->target0 = new_target;
                ch_println( ch, "%ss target set to %s.", target->name, new_target ? new_target->name : "none" );
                snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s set your target to %s.\n", ship->name, new_target ? new_target->name : "none" );
                echo_to_ship_windows( AT_ACTION, target, buf );
            }
        }
        else
        {
            target = get_battlegroup_member( ship, arg2, true );

            if ( !target )
            {
                ch_println( ch, "No ships like that in your local battlegroup." );
                return;
            }

            if ( target == new_target )
            {
                ch_println( ch, "That ship can't target itself!" );
                return;
            }

            ch_println( ch, "&wYou order the target change." );
            target->target0 = new_target;
            ch_println( ch, "%ss target set to %s.", target->name, new_target ? new_target->name : "none" );
            snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s set your target to %s.\n", ship->name, new_target ? new_target->name : "none" );
            echo_to_ship_windows( AT_ACTION, target, buf );
        }

        return;
    }
    else if ( !str_cmp( "position", arg ) )
    {
        if ( !in_battlegroup( ship ) )
        {
            ch_println( ch, "You need to be in a battlegroup." );
            return;
        }

        if ( number_percent() > get_learned_pct( ch, find_gsn( ship->classtype ) ) )
        {
            ch_println( ch, "&RYou fail to maneuver the ship into the appropriate position within the formation." );
            return;
        }

        int pos_num = 0;

        if ( is_number( argument ) )
            pos_num = atoi( argument );
        else if ( !str_cmp( argument, "outer" ) )
            pos_num = 1;
        else if ( !str_cmp( argument, "midguard" ) )
            pos_num = 2;
        else if ( !str_cmp( argument, "central" ) )
            pos_num = 3;

        if ( pos_num < 1 || pos_num > 3 )
        {
            send_to_char
            ( "&zPlease pick one of the following:\n"
              "&C1 &w-&C Outer:&w Good for fighter escorts.\n"
              "&C2 &w-&C Midguard: &wProtects the ships in central, ideal for non-leader.\n"
              "&C3 &w-&C Central:&c most guarded, needs outer/midguard ships to avoid fire.\n",
              ch );
            return;
        }

        if ( ship->classtype >= BATTLESTATION_SHIP && pos_num != 3 )
        {
            ch_println( ch, "You can only be in central position." );
            return;
        }

        if ( ship->shipstate != SHIP_READY )
        {
            ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
            return;
        }

        if ( ship->energy < ( ship->realspeed * 2 ) )
        {
            ch_println( ch, "You do not have enough fuel to pull off that maneuver!" );
            return;
        }

        ship->energy -= ( ship->realspeed * 2 );
        snprintf( buf, MSL, "%s maneuvers into a slow turn, banking into %s position.", ship->name,
                 pos_num == 1 ? "an outer" : pos_num == 2 ? "a midguard" : "a central" );
        echo_to_system_noqueue( AT_YELLOW, ship, buf, NULL );
        // Position should probably always have a long timer, given how powerful it can be if allowed to be spammed to often. Gathorn 3 Sep 17
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        ship->pos = pos_num;
        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s changed positions to %s.\n", ship->name, print_bpos( ship->pos ) );

        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
            if ( target->leader == ship->leader )
                echo_to_ship_windows( AT_GREEN, target, buf );

        ch_println( ch, "Position adjusted." );
    }
    else if ( !str_cmp( "eject", arg ) )
    {
        if ( ship->leader != ship )
        {
            ch_println( ch, "You need to be on the battlegroup leader to eject ships." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cbattlegroup eject <&wship&C>" );
            return;
        }

        target = get_battlegroup_member( ship, argument, false );

        if ( !target || target == ship )
        {
            ch_println( ch, "No ships like that in your battlegroup." );
            return;
        }

        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s has been ejected from the battlegroup!\n", target->name );

        for ( SHIP_DATA* iter = ship->first_in_bg; iter; iter = iter->next_in_bg )
            if ( iter->leader == ship )
                echo_to_ship_windows( AT_RED, iter, buf );

        remove_from_bg( target );
    }
    else if ( !str_cmp( "message", arg ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cbattlegroup message <&wmessage&C>&w" );
            return;
        }

        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s:\n&c&z %s%s&c\n",
                 ship->name, txtclr( ch ), argument );

        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
            echo_to_ship_windows( AT_ACTION, target, buf );
    }
    else if ( !str_cmp( "nav", arg ) )
    {
        if ( xIS_SET( ship->flags, SHIP_VONG ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "&RYuuzhan Vong ships don't network in that way." );
            return;
        }

        if ( ship->leader != ship )
        {
            ch_println( ch, "You need to be in a battlegroup leader to issue nav commands." );
            return;
        }

        ROOM_INDEX_DATA* room, *was_in = NULL;
        char arg2[MIL];
        char full_cmd[MIL];
        argument = one_argument( argument, arg2 );

        if ( NULLSTR( arg2 ) || NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cbattlegroup nav <&wship&C> <&wcommand&C>" );
            return;
        }

        if ( !str_cmp( "all", arg2 ) )
        {
            // Declare the array of pointers to copy the linked list into
            SHIP_DATA** all_ships = NULL;

            // Use a macro to copy the linked list (first_ship to last_ship) into an array of pointers
            LINK_TO_ARRAY( ship->first_in_bg, SHIP_DATA, next_in_bg, all_ships );

            for ( int i = 0; all_ships[i]; i++ )
            {
                target = all_ships[i];

                if ( ship_extracted( target ) )
                    continue;

                if ( target->leader != ship )
                    continue;

                if ( !expand_nav_command( ch, argument, target, &room, full_cmd ) )
                {
                    DISPOSE( all_ships );
                    return;
                }

                ch_println( ch, "&WSending command to %s...", target->name );
                was_in = ch->in_room;
                char_from_room( ch );
                char_to_room( ch, room );
                interpret( ch, full_cmd, FALSE );
                char_from_room( ch );
                char_to_room( ch, was_in );
            }

            DISPOSE( all_ships );
            return;
        }

        target = get_battlegroup_member( ship, arg2, false );

        if ( !target )
        {
            ch_println( ch, "&RNo ships like that in your battlegroup." );
            return;
        }

        if ( target == ship )
        {
            ch_println( ch, "&RYou can't issue commands to your own ship individually." );
            return;
        }

        if ( !expand_nav_command( ch, argument, target, &room, full_cmd ) )
            return;

        ch_println( ch, "&WSending command to %s...", target->name );
        was_in = ch->in_room;
        char_from_room( ch );
        char_to_room( ch, room );
        interpret( ch, full_cmd, FALSE );
        char_from_room( ch );
        char_to_room( ch, was_in );
        ch_println( ch, "Command sent." );
    }
    else if ( !str_cmp( "disband", arg ) )
    {
        if ( ship->leader != ship )
        {
            ch_println( ch, "This vessel has no battlegroup to disband." );
            return;
        }

        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
        {
            if ( target != ship )
            {
                snprintf( buf, MSL, "&z[&CBATTLEGROUP&z] &WYour battlegroup has been disbanded.\n" );
                echo_to_ship_windows( AT_CYAN, target, buf );
            }

            remove_from_bg( target );
        }

        echo_to_ship_windows( AT_ACTION, ship, "&z[&CBATTLEGROUP&z] &WBattlegroup disbanded.\n" );
    }
    else if ( !str_cmp( "quit", arg ) )
    {
        if ( !ship->leader )
        {
            if ( ship->join )
            {
                ch_println( ch, "You cancel the request to join." );
                snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s has canceled its request to join.\n", ship->name );
                echo_to_ship_windows( AT_CYAN, ship->join, buf );
                ship->join = NULL;
                return;
            }

            ch_println( ch, "You aren't in a battlegroup." );
            return;
        }

        if ( ship->leader == ship )
        {
            ch_println( ch, "The battlegroup leader can't quit its own battlegroup." );
            return;
        }

        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s has quit the battlegroup.\n", ship->name );

        for ( target = ship->leader->first_in_bg; target; target = target->next_in_bg )
            if ( target->leader == ship->leader && target != ship )
                echo_to_ship_windows( AT_CYAN, target, buf );

        echo_to_ship_windows( AT_CYAN, ship, "&z[&CBATTLEGROUP&z]&W You quit the battlegroup.\n" );
        remove_from_bg( ship );
    }
    else if ( !str_cmp( "bombard", arg ) )
    {
        PLANET_DATA* planet = NULL;
        SHIP_DATA* temp = NULL;

        if ( ship->classtype < CRUISER_SHIP )
        {
            if ( ship->classtype == FRIGATE_SHIP )
            {
                ch_println( ch, "Frigates cannot be used in bombardments." );
                return;
            }

            ch_println( ch, "You need a bigger ship to bombard. Try using BOMB." );
            return;
        }

        if ( !( planet = get_planet_here( argument, ship->starsystem ) ) )
        {
            ch_println( ch, "No planets like that nearby." );
            return;
        }

        if ( vector_distance( &ship->vpos, &planet->pos ) > 20 )
        {
            ch_println( ch, "You must orbit the planet before you can bombard it!" );
            return;
        }

        if ( ship->leader != ship )
        {
            ch_println( ch, "You must be the battlegroup leader to issue bombardments." );
            return;
        }

        ch_println( ch, "You order the bombardment." );
        WAIT_STATE( ch, 4 * PULSE_PER_SECOND );

        for ( target = ship->first_in_bg; target; target = target->next_in_bg )
        {
            if ( target->starsystem != ship->starsystem )
                continue;

            if ( vector_distance( &target->vpos, &planet->pos ) < 50 )
            {
                snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s bombarding %s.\n", target->name, planet->name );
                orbital_bombardment( target, planet, ch );

                for ( temp = ship->first_in_bg; temp; temp = temp->next_in_bg )
                    echo_to_ship_windows( AT_YELLOW, temp, buf );
            }
        }
    }
    else
    {
        if ( xIS_SET( ship->flags, SHIP_VONG ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "&RYuuzhan Vong ships don't network in that way." );
            return;
        }

        if ( NULLSTR( arg ) )
        {
            ch_println( ch, "&zSyntax: &Cbattlegroup <&wtarget ship&C>&w" );
            return;
        }

        if ( ( target = get_ship_here( arg, ship->starsystem ) ) == NULL )
        {
            ch_println( ch, "There's no ship like that in the sector." );
            return;
        }

        if ( target->join != ship )
        {
            ch_println( ch, "That ship isn't requesting to join." );
            return;
        }

        //Changed to allow frigates to actually be allowed to join the BG after requesting. - Gathorn 7May16
        if ( target->classtype < FRIGATE_SHIP ) // && ( target->classtype != FIGHTER_SHIP || ship->classtype != FIGHTER_SHIP ) )
        {
            ch_println( ch, "Battlegroups are formed by capital class ships." );
            return;
        }

        if ( xIS_SET( target->flags, SHIP_NADESONLY ) )
        {
            ch_println( ch, "That ship isn't eligible to join battlegroups." );
            return;
        }

        // GRAL Era 1 2011, mod from 5 to 3
        // Ralen Era 1 2015, Walldo/Gath requested change to 3 max.
        if ( count_battlegroup( ship ) >= 3 )
        {
            ch_println( ch, "Battlegroups have a maximum of 3 ships." );
            return;
        }

        if ( ship->leader && ship->leader != ship )
        {
            ch_println( ch, "You are already in a battlegroup. Have that ship join the leader." );
            return;
        }

        // Force all battlestations and larger into central position when they form a battlegroup
        if ( ship->classtype >= BATTLESTATION_SHIP )
            ship->pos = 3;

        target->join = NULL;
        if ( !ship->leader )
            add_to_bg( ship, ship );

        add_to_bg( target, ship );

        snprintf( buf, MSL, "&z[&CBATTLEGROUP&z]&W %s has joined the battlegroup.\n", target->name );

        for ( ship = ship->first_in_bg; ship; ship = ship->next_in_bg )
            echo_to_ship_windows( AT_CYAN, ship, buf );

        echo_to_ship_windows( AT_CYAN, target, "&z[&CBATTLEGROUP&z] Battlegroup joined.\n" );
        ch_println( ch, "&wYou authorize them to join your battlegroup.&w" );
    }
}

bool in_battlegroup( SHIP_DATA* ship )
{
    if ( !ship )
        return false;

    return ship->leader != NULL;
}

bool same_group( SHIP_DATA* s1, SHIP_DATA* s2 )
{
    if ( !s1 || !s2 )
        return false;

    bool same_battlegroup = s1->leader && s1->leader == s2->leader;
    bool same_squadron = s1->squadleader && s1->squadleader == s2->squadleader;
    return same_battlegroup || same_squadron;
}

bool in_this_squadron( SHIP_DATA* ship, SHIP_DATA* leader )
{
    if ( !ship || !leader )
        return false;

    if ( ship->squadleader == leader )
        return TRUE;

    return FALSE;
}

bool in_squadron( SHIP_DATA* ship )
{
    if ( !ship )
        return false;

    return ship->squadleader != NULL;
}

bool has_squadron( SHIP_DATA* ship )
{
    if ( !ship )
        return FALSE;

    return ( ship->first_in_squad != NULL );
}

bool has_in_squadron( SHIP_DATA* ship, SHIP_DATA* target )
{
    if ( !ship || !target )
        return false;

    return ( target->squadleader == ship );
}

int count_squadron_members( SHIP_DATA* ship )
{
    if ( !ship )
        return 0;

    int cnt = 0;
    LINK_LENGTH( ship->first_in_squad, SHIP_DATA, next_in_squad, cnt );
    return cnt;
}

int count_battlegroup( SHIP_DATA* ship )
{
    if ( !ship )
        return 0;

    int cnt = 0;
    LINK_LENGTH( ship->first_in_bg, SHIP_DATA, next_in_bg, cnt );
    return cnt;
}

char* print_bpos( int pos )
{
    switch ( pos )
    {
        case 1:
            return "Outer";

        case 2:
            return "Midguard";

        case 3:
            return "Central";
    }

    return "";
}

SHIP_DATA* on_ship( CHAR_DATA* ch )
{
    if ( !ch || !ch->in_room )
        return NULL;

    if ( ch->in_room->on_ship )
        return ch->in_room->on_ship;

    for ( SHIP_DATA* ship = first_ship; ship; ship = ship->next )
    {
        if ( ch->in_room->vnum < ship->firstroom || ch->in_room->vnum > ship->lastroom )
            continue;

        return ship;
    }

    return NULL;
}

// Send a message to the ship's current room and also any rooms inside ships/structures/vehicles which should be able to see it
void ship_action( SHIP_DATA* ship, char* buf )
{
    int x = 0;
    SHIP_DATA* tship = NULL;
    VEHICLE_DATA* vec = NULL;
    STRUCTURE_DATA* stru = NULL;
    ROOM_INDEX_DATA* room = NULL, *inner_room = NULL;

    if ( !ship )
        return;

    room = get_room_index( ship->location );

    if ( !room )
        return;

    echo_to_room( AT_YELLOW, room, buf );

    for ( tship = room->first_ship; tship; tship = tship->next_in_room )
        if ( ship->location == tship->location && tship != ship )
            echo_to_ship_windows( AT_ORANGE, tship, buf );

    for ( vec = first_vehicle; vec; vec = vec->next )
    {
        if ( vec->in_room != room )
            continue;

        for ( x = vec->firstroom; x <= vec->lastroom; x++ )
        {
            inner_room = get_room_index( x );

            if ( inner_room && ( xIS_SET( inner_room->flags, ROOM_VIEWPORT ) || x == vec->cockpit ) )
                echo_to_room( AT_ORANGE, inner_room, buf );
        }
    }

    for ( stru = first_structure; stru; stru = stru->next )
    {
        if ( stru->in_room != ship->location )
            continue;

        for ( x = stru->firstroom; x <= stru->lastroom; x++ )
        {
            inner_room = get_room_index( x );

            if ( inner_room && xIS_SET( inner_room->flags, ROOM_VIEWPORT ) )
                echo_to_room( AT_ORANGE, inner_room, buf );
        }
    }
}

void vehicle_action( VEHICLE_DATA* vec, char* buf )
{
    SHIP_DATA* tship = NULL;
    VEHICLE_DATA* tvec = NULL;
    ROOM_INDEX_DATA* room;

    if ( !vec )
        return;

    if ( vec->in_room )
    {
        for ( tship = vec->in_room->first_ship; tship; tship = tship->next_in_room )
            for ( room = tship->first_room; room; room = room->next_in_range )
                if ( ship_window( room ) )
                    echo_to_room( AT_ORANGE, room, buf );

        for ( tvec = first_vehicle; tvec; tvec = tvec->next )
            if ( tvec->in_room == vec->in_room )
                echo_to_room( AT_ORANGE, get_room_index( tvec->cockpit ), buf );
    }
}

int getFightTimer( SHIP_DATA* ship )
{
    if ( !ship )
        return -1;

    return ship->fight_timer;
}

bool ship_is_fighting( SHIP_DATA* ship )
{
    if ( getFightTimer( ship ) )
        return true;

    return false;
}

void ship_start_fighting( SHIP_DATA* ship, SHIP_DATA* target ) // Call this on any ship that is in any form of combat
{
    SHIP_DATA* sys_ship = NULL;

    if ( !ship || ship_extracted( ship ) )
        return;

    if ( is_pirate( ship ) || ( target && is_pirate( target ) ) )
        return;

    // Set the BG's fight timer
    if ( ship->starsystem )
    {
        for ( sys_ship = ship->starsystem->first_ship; sys_ship; sys_ship = sys_ship->next_in_starsystem )
        {
            if ( same_group( sys_ship, ship ) )
            {
                sys_ship->fight_timer = 15;

                // Clear safe orbital status if this wing ship or the BG leader are manned
                if ( sys_ship->safe_orbital && ( is_ship_manned( sys_ship ) || is_ship_manned( ship ) ) )
                    sys_ship->safe_orbital = false;
            }
        }
    }

    // If the target exists, set the fight timers on the target's BG ships
    if ( target && target->starsystem )
    {
        for ( sys_ship = target->starsystem->first_ship; sys_ship; sys_ship = sys_ship->next_in_starsystem )
        {
            if ( same_group( sys_ship, target ) )
            {
                sys_ship->fight_timer = 15;

                // Clear safe orbital status if this wing ship or the BG leader are manned
                if ( sys_ship->safe_orbital && ( is_ship_manned( sys_ship ) || is_ship_manned( target ) ) )
                    sys_ship->safe_orbital = false;
            }
        }
    }

    // Clear safe orbital status if it's now manned
    if ( ship->safe_orbital && is_ship_manned( ship ) )
        ship->safe_orbital = false;

    // Clear safe orbital status if it's now manned
    if ( target && target->safe_orbital && is_ship_manned( target ) )
        target->safe_orbital = false;

    ship->fight_timer = 15;

    if ( target )
        target->fight_timer = 15;

    return;
}

void echo_to_planet( PLANET_DATA* planet, char* argument )
{
    CHAR_DATA* pch = NULL;

    for ( pch = first_char; pch; pch = pch->next )
    {
        if ( IS_AWAKE( pch ) && pch->in_room && pch->in_room->area && pch->in_room->area->planet == planet )
        {
            send_to_char( argument, pch );
        }
    }
}

void echo_to_planet_outdoors( PLANET_DATA* planet, char* argument )
{
    CHAR_DATA* pch = NULL;

    for ( pch = first_char; pch; pch = pch->next )
    {
        if  ( IS_AWAKE( pch ) && pch->in_room && pch->in_room->area && pch->in_room->area->planet == planet && !xIS_SET( pch->in_room->flags, ROOM_INDOORS ) )
        {
            send_to_char( argument, pch );
        }
    }
}

bool ship_is_owned( SHIP_DATA* ship )
{
    CLAN_DATA* clan = NULL;

    if ( !ship || NULLSTR( ship->shipowner ) )
        return false;

    clan = ship->clan;

    if ( clan )
        return true;

    if ( player_exist( ship->shipowner ) )
        return true;

    return false;
}

char* get_ship_occupants( SHIP_DATA* ship )
{
    static char result[MSL];
    strlcpy( result, "", MSL );
    ROOM_INDEX_DATA* ship_room = NULL;
    CHAR_DATA* occupant = NULL;

    if ( !ship )
        return result;

    for ( ship_room = ship->first_room; ship_room; ship_room = ship_room->next_in_range )
    {        
        occupant = NULL;
        for ( occupant = ship_room->first_person; occupant; occupant = occupant->next_in_room )
        {
            if ( !NULLSTR( result ) )
                snprintf( result + strlen( result ), MSL - strlen( result ), ", " );

            snprintf( result + strlen( result ), MSL - strlen( result ), "&C%s &z(%s%s&z)",
            !IS_NPC( occupant ) ? occupant->name : occupant->short_descr,
            !IS_NPC( occupant ) ? "&W" : "&Y",
            !IS_NPC( occupant ) ? "PC" : "NPC" );
        }
    }

    return result;
}

SHIP_DATA* ship_from_id( int id )
{
    SHIP_DATA* ship = NULL;

    if ( id <= 0 )
        return NULL;

    for ( ship = first_ship; ship; ship = ship->next )
        if ( ship->id == id )
            return ship;

    for ( ship = first_drydock; ship; ship = ship->next )
        if ( ship->id == id )
            return ship;

    return NULL;
}

void space_player( CHAR_DATA* ch, SHIP_DATA* ship )
{
    char buf[MSL];
    char name[MSL];
    SHIP_DATA* space_corpse;
    SPACE_DATA* starsys = NULL;
    ROOM_INDEX_DATA* room = NULL;
    snprintf( buf, MSL, "%s: %s expelled from %s.", FUNC, ch->name, ship->name );
    log_string( buf );
    /*
        Check with FASTSHIP, make sure there's a pod template
    */
    SHIP_TEMPLATE_DATA* template = find_shiptemplate( "envirosuit.img" );

    if ( !template )
    {
        bug( "%s: could not locate envirosuit.img template", FUNC );
        return;
    }

    starsys = ship->starsystem;

    if ( ship->shipstate == SHIP_HYPERSPACE || !starsys )
        return;

    ch_println( ch, "As the hull near you ruptures, you find yourself ripped into the cold vacuum of space with nothing to protect you." );
    snprintf( buf, MSL, "As the hull on %s ruptures, a small humanoid shape is expelled into the cold vacuum of space", ship->name );
    echo_to_system_noqueue( AT_RED, ship, buf, NULL );
    /*
        Call FASTSHIP. Cook up an envirosuit
    */
    snprintf( name, MSL, "A humanoid size body" );

    space_corpse = make_ship( NULL, template, name );
    SET_STRING( space_corpse->name, name );
    SET_STRING( space_corpse->shipowner, ch->name );
    space_corpse->clan = NULL;
    SET_STRING( space_corpse->description, "&wA humanoid body, still clinging to life, floats aimlessly through the cold vacuum of space..." );

    ship_to_starsystem( space_corpse, starsys );
    space_corpse->location = 0;
    vector_copy( &space_corpse->vpos, &ship->vpos );
    /*
        Activate space corpse configuration (like an EV suit with a really short duration)
    */
    space_corpse->eject_beacon_id = ship->eject_beacon_id;
    space_corpse->autorecharge = TRUE;
    space_corpse->shield = space_corpse->maxshield;
    space_corpse->currspeed = ( space_corpse->realspeed / 3 );
    xSET_BIT( space_corpse->flags, SHIP_ENVIROSUIT );
    xSET_BIT( space_corpse->flags, SHIP_INVINCIBLE );
    xSET_BIT( space_corpse->flags, SHIP_SPACE_CORPSE );
    space_corpse->shipstate = SHIP_DISABLED;
    space_corpse->selfd_time = 5;
    space_corpse->selfd_armed = TRUE;
    space_corpse->dock_install = FALSE;
    Vector3 tempvect;
    vector_init( &tempvect );
    tempvect.x = ship->head.x >= 0 ? ship->head.x + number_range( 100, 10000 ) : ship->head.x + number_range( -10000, -100 );
    tempvect.y = ship->head.y >= 0 ? ship->head.y + number_range( 100, 10000 ) : ship->head.y + number_range( -10000, -100 );
    tempvect.z = ship->head.z >= 0 ? ship->head.z + number_range( 100, 10000 ) : ship->head.z + number_range( -10000, -100 );
    ship_set_course( space_corpse, &tempvect );
    ship_move( space_corpse );
    room = get_room_index( space_corpse->cockpit );
    if ( room )
    {
        SET_STRING( room->name, "&wThe cold, dark vacuum of space" );
        SET_STRING( room->description, "&wThe infinite expanse of stars beautifully frames your journey through the void..." );
        save_room( room, true );
    }
    char_from_room( ch );
    char_to_room( ch, room );
    save_ship( space_corpse, true );
    snprintf( buf, MSL, "%s: space corpse successfully launched.", FUNC );
    log_string( buf );
    return;
}

void shipram_effects( SHIP_DATA* ship )
{
    CHAR_DATA* tch = NULL;
    ROOM_INDEX_DATA* room = NULL;
    int hull_pct = 0, chance = 0;
    bool destroy = FALSE;
    char buf[MSL];

    if ( !ship || ship_extracted( ship ) )
        return;

    hull_pct = (int)( ( (double)ship->hull / (double)ship->maxhull) * 100 );
    bug( "%s: %s hull pct %d", FUNC, ship->name, hull_pct );

    if ( ship->maxshield > 0 && ship->shield <= 0 )
    {
        echo_to_ship_windows( AT_RED, ship, "[WARNING]: Critical power overload... Shields down!\n" );
        snprintf( buf, MSL, "%ss shields shine brightly as they fail.", ship->name );
        echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
    }

    // First, damage ship systems
    if ( ship->shield <= 0 && ship->hull < ship->maxhull && !xIS_SET( ship->flags, SHIP_OBJECT ) && !xIS_SET( ship->flags, SHIP_VONG ) )
    {
        if ( ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED && ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            snprintf( buf, MSL, "Ship drive %s!\n", destroy ? "DESTROYED" : "DAMAGED" );
            echo_to_ship_windows( AT_RED, ship, buf );
            snprintf( buf, MSL, "Flames erupt from %ss engines. They appear to be damaged heavily.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->shipstate = destroy ? SHIP_PERM_DISABLED : SHIP_DISABLED;

            // Disabling halts autopiloted ships to better support boarding scenarios
            if ( ship->autopilot )
                ship->currspeed = 0;
        }

        if ( ship->missilestate < MISSILE_DAMAGED && ship->missiletubes > 0 && ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            snprintf( buf, MSL, "Ship missile launcher %s!", destroy ? "DESTROYED" : "DAMAGED" );
            echo_to_ship_windows( AT_RED, ship, buf );
            snprintf( buf, MSL, "Several of %ss missile tubes are destroyed.", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->missilestate = destroy ? MISSILE_DESTROYED : MISSILE_DAMAGED;
            ship->spent_tubes = ship->missiletubes;
        }

        if ( ship->laser_charge >= LASER_READY && ( ship->blasters > 0 || ship->lasers > 0 || ship->turbolasers > 0 ) &&
        ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            snprintf( buf, MSL, "Lasers %s!", destroy ? "DESTROYED" : "DAMAGED" );
            echo_to_ship_windows( AT_RED, ship, buf );
            ship->autoblaster_charge = destroy ? LASER_DESTROYED : LASER_DAMAGED;
            ship->laser_charge = destroy ? LASER_DESTROYED : LASER_DAMAGED;
            ship->turbolaser_charge = destroy ? LASER_DESTROYED : LASER_DAMAGED;
            snprintf( buf, MSL, "Several lasers explode on %s!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }

        if ( ship->tractorstate < TRACTOR_DAMAGED && ship->tractorbeam > 0 &&
        ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            snprintf( buf, MSL, "Tractor beam %s!", destroy ? "DESTROYED" : "DAMAGED" );
            echo_to_ship_windows( AT_RED, ship, buf );
            snprintf( buf, MSL, "%ss tractor beam is engulfed in flames!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->tractorstate = destroy ? TRACTOR_DESTROYED : TRACTOR_DAMAGED;
        }

        int working_turret_count = 0;

        for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
            if ( turret->laserstate > LASER_DAMAGED )
                working_turret_count++;

        if ( working_turret_count > 0 && ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            int exploding_turret_idx = number_range( 1, working_turret_count );
            int turret_idx = 0;

            for ( TURRET_DATA* turret = ship->first_turret; turret; turret = turret->next )
            {
                turret_idx++;

                if ( turret->laserstate <= LASER_DAMAGED )
                    continue;

                exploding_turret_idx--;

                if ( exploding_turret_idx > 0 )
                    continue;

                if ( turret->room )
                {
                    echo_to_room( AT_BLOOD, turret->room, "A blinding flash of light fills the turret..." );
                    echo_to_room( AT_BLOOD, turret->room, "The consoles fizzle and die, the systems overloaded." );
                    echo_to_room( AT_BLOOD, turret->room, "The cannon grinds to a halt, refusing to respond or fire." );
                    snprintf( buf, MSL, "Turret %d has been %s!", turret_idx, destroy ? "destroyed" : "disabled" );
                    echo_to_ship_windows( AT_RED, ship, buf );
                }

                snprintf( buf, MSL, "One of %ss turrets explodes!", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                turret->laserstate = destroy ? LASER_DESTROYED : LASER_DAMAGED;
                break;
            }
        }

        if ( ship->ion_charge >= ION_READY && ship->ion > 0 && ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            snprintf( buf, MSL, "Ion cannons %s!", destroy ? "DESTROYED" : "DAMAGED" );
            echo_to_ship_windows( AT_RED, ship, buf );
            snprintf( buf, MSL, "Several of %ss ion cannons explode!", ship->name );
            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
            ship->ion_charge = destroy ? ION_DESTROYED : ION_DAMAGED;
        }

        if ( ship->cloakstatus > CLOAK_NONE && ( ( chance = number_range( 0, 100 ) ) > hull_pct ) )
        {
            destroy = chance >= 95;
            if ( ship->cloakstatus == CLOAK_READY )
            {
                snprintf( buf, MSL, "Cloaking device %s!\n", destroy ? "DESTROYED" : "DAMAGED" );
                echo_to_ship_windows( AT_RED, ship, buf );
                snprintf( buf, MSL, "A field flares over %s, but disappears.", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                ship->cloakstatus = destroy ? CLOAK_DESTROYED : CLOAK_DAMAGED;
            }

            if ( ship->cloakstatus == CLOAK_ON )
            {
                snprintf( buf, MSL, "Cloaking device %s!\n", destroy ? "DESTROYED" : "DAMAGED" );
                echo_to_ship_windows( AT_RED, ship, buf );
                echo_to_ship_main( AT_BLUE, ship, "[Alert] Cloaking Device deactivating!" );
                snprintf( buf, MSL, "Explosions in space loom eerily as a field around %s deactivates!", ship->name );
                echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
                ship->cloakstatus = destroy ? CLOAK_DESTROYED : CLOAK_DAMAGED;
                snprintf( buf, MSL, "%s shimmers into existence.", ship->name );
                echo_to_system_noqueue( AT_WHITE, ship, buf, NULL );
            }
        }
    }

    // Give hull alerts
    if ( ship->hull <= ship->maxhull * 0.25 && ship->shield <= 0 )
    {
        if ( xIS_SET( ship->flags, SHIP_OBJECT ) )
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "This object is beginning to fall apart!\n" );

            switch ( number_range( 1, 3 ) )
            {
                case 1:
                    snprintf( buf, MSL, "%s is barely holding together.", ship->name );
                    break;

                case 2:
                    snprintf( buf, MSL, "Large pieces of %s begin to break off!", ship->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "Cracks begin to form across the surface of %s.", ship->name );
                    break;
            }

            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
        else
        {
            echo_to_ship_windows( AT_BLOOD + AT_BLINK, ship, "WARNING! Ship hull severely damaged!\n" );

            switch ( number_range( 1, 5 ) )
            {
                case 1:
                    snprintf( buf, MSL, "%s looks like it's going to explode soon!", ship->name );
                    break;

                case 2:
                    snprintf( buf, MSL, "%s is surrounded by explosions!", ship->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "%s tilts oddly, rotating slowly.", ship->name );
                    break;

                case 4:
                    snprintf( buf, MSL, "Several parts of %ss structure are gone!", ship->name );
                    break;

                case 5:
                    snprintf( buf, MSL, "A huge explosion rocks %ss entire frame!", ship->name );
                    break;
            }

            echo_to_system_noqueue( AT_ORANGE, ship, buf, NULL );
        }
    }

    // Finally, suck some people into space
    if ( hull_pct < 100 )
    {
        // First, suck some people out into the vacuum of space
        for ( room = ship->first_room; room; room = room->next_in_range )
        {
            for ( tch = room->first_person; tch; tch = tch->next_in_room )
            {
                if ( ( number_range( 0, 100 ) - tch->perm_lck ) > hull_pct )
                {
                    if ( has_envirosuit( tch ) )
                        activate_envirosuit( tch, ship );
                    else
                        space_player( tch, ship );
                }
            }
        }
    } 

    return;
}

/**
    @param ship Ship which is doing the ramming
    @param target Ship which is being rammed
    @param pilot Character piloting the ramming ship
    @param squad Whether the attacked is a squadship or not
    @return true if target was destroyed
*/
bool shipram( SHIP_DATA* ship, SHIP_DATA* target, CHAR_DATA* pilot, bool squad )
{
    SHIP_DATA* tShip = NULL, *next_tShip = NULL;
    double dmg_diff = 0, dmg = 0, total_modified_dmg = 0, max_modified_dmg = 0, total_raw_dmg = 0, max_raw_dmg = 0, dmg_modifier = 0, rel_heading = 0;
    int size_diff = 0, chance = 0;
    bool target_dead = FALSE;
    char buf[MSL];

    if ( !ship || !target || ship_extracted( ship ) || ship_extracted( target ) )
        return false;

    // Calculate the relative strength of the ramming ship
    size_diff = target->classtype - ship->classtype;

    switch ( size_diff )
    {
        case -1:
            dmg_diff = 1.0;
            break;

        case 0:
            dmg_diff = 1.25;
            break;

        case 1:
            dmg_diff = 1.5;
            break;

        case 2:
            dmg_diff = 1.75;
            break;

        case 3:
            dmg_diff = 2.00;
            break;

        case 4:
            dmg_diff = 2.25;
            break;

        case 5:
            dmg_diff = 2.50;
            break;

        case 6:
            dmg_diff = 2.75;
            break;

        case 7:
            dmg_diff = 3.00;
            break;

        case 8:
            dmg_diff = 3.25;
            break;

        case 9:
            dmg_diff = 3.5;
            break;

        default:
            dmg_diff = 4.0;
            break;
    }

    // Figure out if the target is moving towards or away from the ramming ship. 
    rel_heading = calc_relative_heading( target, &ship->vpos );
    dmg_modifier = ( ship->currspeed + ( target->currspeed * rel_heading ) ) / 75;

    max_raw_dmg = ( ship->maxhull * 2 ) * dmg_modifier;
    max_modified_dmg = max_raw_dmg / dmg_diff;

    // Start by damaging the target
    dmg = UMIN( target->shield, max_modified_dmg );
    target->shield -= dmg;
    total_modified_dmg += dmg;
    dmg = UMIN( target->hull, (max_modified_dmg - total_modified_dmg) );
    target->hull -= dmg;
    total_modified_dmg += dmg;

    // Now damage the attacking ship
    total_raw_dmg = total_modified_dmg * dmg_diff;
    dmg = UMIN( ship->shield, total_raw_dmg );
    ship->shield -= dmg;
    total_raw_dmg -= dmg;
    dmg = UMIN( ship->hull, total_raw_dmg );
    ship->hull -= dmg;

    if ( squad && ship->hull <= 0 )
    {
        switch ( number_range( 1, 4 ) )
        {
            case 1:
                snprintf( buf, MSL, "This was a bad idea!" );
                break;

            case 2:
                snprintf( buf, MSL, "Tell my family I love th--" );
                break;

            case 3:
                snprintf( buf, MSL, "I can see it! I can see the li--" );
                break;

            case 4:
                snprintf( buf, MSL, "I think I'm gonna make i--" );
                break;
        }

        radio( ship, buf, NULL );
    }

    // If the attacker survived and the target did not...
    if ( target->hull <= 0 && ship->hull > 0 )
    {
        // Tell the attacker
        snprintf( buf, MSL, "Your ship barrels through %s as their hull rips apart...", target->name );
        echo_to_ship_windows( AT_ORANGE, ship, buf );        

        // Tell the target
        snprintf( buf, MSL, "Your ship breaks apart as %s rams through it...", ship->name );
        echo_to_ship_windows( AT_ORANGE, target, buf );

        // Tell everyone else in the system
        snprintf( buf, MSL, "%s crashes headlong into %s, tearing it apart...", ship->name, target->name );

        for ( tShip = ship->starsystem->first_ship; tShip; tShip = tShip->next_in_starsystem )
            if ( tShip != ship && tShip != target )
                echo_to_ship_windows( AT_ORANGE, tShip, buf );

        // Destroy the target
        destroy_ship( target, ship, pilot, "shipramming" );

        // Cue effects for the survivor
        shipram_effects( ship );
        return TRUE;
    }
    // If the target survived and the attacker did not...
    else if ( target->hull > 0 && ship->hull <= 0 )
    {
        // Tell the target they survived this round...
        snprintf( buf, MSL, "Your ship holds together as %s crashes into it...", ship->name );
        echo_to_ship_windows( AT_ORANGE, target, buf );

        // Tell everyone else in the system
        snprintf( buf, MSL, "%s does critical damage to itself as it crashes into %s...", ship->name, target->name );

        for ( tShip = ship->starsystem->first_ship; tShip; tShip = tShip->next_in_starsystem )
            if ( tShip != ship && tShip != target )
                echo_to_ship_windows( AT_ORANGE, tShip, buf );

        // Squadships also have a 90% chance to shipram -- after their squad leader, who has already attempted
        if ( !squad )
        {
            for ( tShip = ship->first_in_squad; tShip && !target_dead; tShip = next_tShip )
            {
                next_tShip = tShip->next_in_squad;
                if ( !tShip->piloting )
                    if ( tShip->starsystem == ship->starsystem && vector_distance( &tShip->vpos, &target->vpos ) <= 50 )
                        if ( ( chance = number_range( 0, 100 ) ) <= 90 )
                            target_dead = shipram( tShip, target, pilot, true );
            }
        }

        // Even though the squad leader went first, we let them live long enough to see what their squad does. Then they die.
        snprintf( buf, MSL, "Your ship crashes headlong into %s...", target->name );
        echo_to_ship_windows( AT_ORANGE, ship, buf );        

        // Destroy the attacker
        destroy_ship( ship, ship, pilot, "shipramming" );

        // If the target survives the main attack and all possible squad attacks
        if ( !target_dead && !squad ) shipram_effects( target );

        // Return whether the target was destroyed by the main attacker or any of its squads
        return target_dead;
    }
    // If they both survived...
    else if ( ship->hull > 0 && target->hull > 0 )
    {
        // Tell the target
        snprintf( buf, MSL, "Your ship holds together as %s crashes into it...", ship->name );
        echo_to_ship_windows( AT_ORANGE, target, buf );

        // Tell everyone else in the system
        snprintf( buf, MSL, "%s crashes headlong into %s...", ship->name, target->name );

        for ( tShip = ship->starsystem->first_ship; tShip; tShip = tShip->next_in_starsystem )
            if ( tShip != ship && tShip != target )
                echo_to_ship_windows( AT_ORANGE, tShip, buf );

        // Squadships also have a 90% chance to shipram -- after their squad leader, who has already attempted
        if ( !squad )
        {
            for ( tShip = ship->first_in_squad; tShip && !target_dead; tShip = next_tShip )
            {
                next_tShip = tShip->next_in_squad;
                if ( !tShip->piloting )
                    if ( tShip->starsystem == ship->starsystem && vector_distance( &tShip->vpos, &target->vpos ) <= 50 )
                        if ( ( chance = number_range( 0, 100 ) ) <= 90 )
                            target_dead = shipram( tShip, target, pilot, true );
            }
        }

        // Tell the attacker
        snprintf( buf, MSL, "Your ship crashes headlong into %s... but you survive the impact!", target->name );
        echo_to_ship_windows( AT_ORANGE, ship, buf );

        // If they both survived, the target gets pushed away from the ramming ship
        if ( !target_dead && ship->classtype >= target->classtype )
        {
            Vector3 tempvect;
            vector_init( &tempvect );
            double vx = URANGE( -50000, target->vpos.x + ( target->vpos.x - ship->vpos.x ), 50000 );
            double vy = URANGE( -50000, target->vpos.y + ( target->vpos.y - ship->vpos.y ), 50000 );
            double vz = URANGE( -50000, target->vpos.z + ( target->vpos.z - ship->vpos.z ), 50000 );
            tempvect.x = vx;
            tempvect.y = vy;
            tempvect.z = vz;
            set_ship_speed( target, URANGE( 0, ship->currspeed, target->realspeed ) );
            ship_set_course( target, &tempvect );
        }

        set_ship_speed( ship, 0 );
        // Cue the effects
        shipram_effects( ship );
        if ( !target_dead && !squad ) shipram_effects( target );

        // Return whether the target was destroyed by the main attacker or any of its squads
        return target_dead;
    }
    // If they both died...
    else if ( ship->hull <= 0 && target->hull <= 0 )
    {
        // Tell the attacker
        snprintf( buf, MSL, "Your ship barrels into %s, causing an explosion that consumes both ships!", target->name );
        echo_to_ship_main( AT_ORANGE, ship, buf );

        // Tell the target
        snprintf( buf, MSL, "Your ship explodes on impact as %s crashes headlong into it...", ship->name );
        echo_to_ship_main( AT_ORANGE, target, buf );

        // Tell everyone else in the system
        snprintf( buf, MSL, "%s crashes headlong into %s...", ship->name, target->name );

        for ( tShip = ship->starsystem->first_ship; tShip; tShip = tShip->next_in_starsystem )
            if ( tShip != ship && tShip != target )
                echo_to_ship_windows( AT_ORANGE, tShip, buf );

        // Destroy them both
        destroy_ship( target, ship, pilot, "shipramming" );
        destroy_ship( ship, ship, pilot, "shipramming" );
        return true;
    }

    bug( "%s: no conditions satisfied", FUNC );
    return false;
}

