int shipram_abort( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    SHIP_DATA* target = buffer->shiptarget;

    ch_println( ch, "&RYou lose concentration and can't keep up with your target's course heading." );
    if ( valid_ship( ship ) )
    {
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: The ship yaws as it breaks off its ramming maneuvers." );
        if ( valid_ship( target ) )
            echo_to_ship_main( AT_YELLOW, target, strfmt("[ALERT]: %s yaws as it breaks off its ramming maneuvers.", ship->name) );
    }
    return E_LOTJ_SUCCESS;
}

int shipram_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    // Rehydrate the pointers and such
    SHIP_DATA* ship = buffer->ship;
    SHIP_DATA* target = buffer->shiptarget;
    long start_time = buffer->long1;

    if ( !valid_ship( ship ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    // If the target ship is gone, abort.
    if ( !valid_ship( target ) || ship->starsystem != target->starsystem || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYour target seems to have disappeared!" );
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    // If they've been in a shipramming maneuver for five minutes or the enemy's getting away, it's time to call it quits.
    if ( start_time <= current_time - 300 || vector_distance( &ship->vpos, &target->vpos ) > 750 )
    {
        ch_println( ch, "&RYou just can't seem to close the distance on your target." );
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: The ship yaws as it breaks off its ramming maneuvers." );
        echo_to_ship_main( AT_YELLOW, target, strfmt("[ALERT]: %s yaws as it breaks off its ramming maneuvers.", ship->name) );
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        return E_LOTJ_SUCCESS;
    }

    // If we've made it this far and they've closed the distance, it's go time!
    if ( vector_distance( &ship->vpos, &target->vpos ) <= 50 )
    {
        shipram( ship, target, ch, false );
        return E_LOTJ_SUCCESS;
    }

    // Re-run the skill check
    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    // If the skill check succeeds, start the process.
    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GYou continue shipramming maneuvers..." );
        act( AT_PLAIN, "$n continues plotting new courses into the helm.", ch, NULL, NULL, TO_ROOM );
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: The ship lurches slightly as it continues ramming maneuvers." );
        echo_to_ship_main( AT_ORANGE, target, strfmt("[ALERT]: %s continuing on a ramming approach.", ship->name) );
        Vector3 tempvect;
        tempvect.x = target->vpos.x;
        tempvect.y = target->vpos.y;
        tempvect.z = target->vpos.z;
        set_ship_speed( ship, ship->realspeed );
        ship_set_course( ship, &tempvect );
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        add_timer( ch, TIMER_DO_FUN, 9, shipram_complete, shipram_abort, "do_shipram" );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "&RYou can't seem to line up with your target's course heading." );
    echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: The ship yaws as it breaks off its ramming maneuvers." );
    echo_to_ship_main( AT_YELLOW, target, strfmt("[ALERT]: %s yaws as it breaks off its ramming maneuvers.", ship->name) );
    ship->shipstate = SHIP_BUSY;
    ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
    learn_from_failure( ch, find_gsn( ship->classtype ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_shipram( CHAR_DATA* ch, char* argument )
{
    if ( IS_NPC( ch ) )
        return;

    SHIP_DATA* ship = get_ship_from_pilotseat( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "&RYou must be in the pilot seat of a ship to do that!" );
        return;
    }

    if ( ship->classtype > SATELLITE_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ship->shipstate == SHIP_HYPERSPACE )
    {
        ch_println( ch, "&RYou can only do that in realspace!" );
        return;
    }

    if ( ship->shipstate == SHIP_DOCKED )
    {
        ch_println( ch, "&RYou can't do that until after you've launched!" );
        return;
    }

    if ( ship->shipstate == SHIP_DISABLED || ship->shipstate == SHIP_PERM_DISABLED )
    {
        ch_println( ch, "&RThe ship's drive is disabled. Unable to maneuver." );
        return;
    }

    if ( ship->classtype == PLATFORM_SHIP )
    {
        ch_println( ch, "&RPlatforms can't move, what would be the point?" );
        return;
    }

    if ( get_tractor( ship ) != NULL )
    {
        ch_println( ch, "&RYou're stuck in a tractor beam!" );
        return;
    }

    if ( !ship->starsystem )
    {
        ch_println( ch, "&RYou can't do that until you've finished launching!" );
        return;
    }

    if ( ship->autopilot )
    {
        ch_println( ch, "&RYou'll have to turn off the ship's autopilot first..." );
        return;
    }

    if ( ship->shipstate != SHIP_READY )
    {
        ch_println( ch, "&RPlease wait until the ship has finished its current maneuver." );
        return;
    }

    if ( ship->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RYou can't shipram while cloaked." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_JAMMED ) && str_cmp( "none", argument ) )
    {
        ch_println( ch, "Damn, the radar is jammed!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cshipram <&wtarget&C>" );
        return;
    }

    SHIP_DATA* target = get_ship_here( argument, ship->starsystem );
    if ( !target || target->cloakstatus == CLOAK_ON )
    {
        ch_println( ch, "&RThat ship isn't here!" );
        return;
    }

    if ( target == ship )
    {
        ch_println( ch, "&RYou can't target your own ship!" );
        return;
    }

    if ( is_protected( ship, target, false ) || xIS_SET( target->flags, SHIP_TRAFFIC ) )
    {
        ch_println( ch, "&RThat ship is currently being protected by other ships." );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) > 500 )
    {
        ch_println( ch, "&RYou need to close some distance before maneuvering to ram them." );
        return;
    }

    if ( vector_distance( &ship->vpos, &target->vpos ) < 100 )
    {
        ch_println( ch, "&RYou need to get some distance between you before you can begin maneuvers." );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_SPACE_CORPSE ) )
    {
        ch_println( ch, "&RThey're much too small to ram effectively." );
        return;
    }

    if ( xIS_SET( target->flags, SHIP_ENVIROSUIT ) )
    {
        ch_println( ch, "&REV suits are too small to ram effectively." );
        return;
    }

    if ( target->classtype < ship->classtype - 1 )
    {
        ch_println( ch, "&RThat ship is too small. You can't maneuver into them." );
        return;
    }

    // Excessive safety check -- make sure nobody's already trying to ram
    ROOM_INDEX_DATA* room = NULL;
    for ( room = ship->first_room; room; room = room->next_in_range )
    {
        for ( CHAR_DATA* tch = ch->in_room->first_person; tch; tch = tch->next_in_room )
        {
            if ( IS_NPC( tch ) )
                continue;

            TIMER* timer = get_timerptr( tch, TIMER_DO_FUN );
            if ( !timer )
                continue;

            if ( !str_cmp( timer->buffer->func, "do_shipram" ) )
            {
                ch_println( ch, "&RSomeone else onboard is already in a shipramming maneuver!" );
                return;
            }
        }
    }

    // Same skill requirements as do_trajectory
    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    // If the skill check succeeds, start the process.
    if ( number_percent(  ) <= chance )
    {
        ch_println( ch, "&GYou begin ramming maneuvers." );
        act( AT_PLAIN, "$n begins plotting a course into the helm.", ch, NULL, argument, TO_ROOM );

        // Let the two ships' occupants know
        echo_to_ship_main( AT_YELLOW, ship, "[ALERT]: The ship lurches slightly as it begins ramming maneuvers." );
        echo_to_ship_main( AT_ORANGE, target, strfmt("[ALERT]: %s begins maneuvering towards you on a ramming approach.", ship->name) );

        // Set the timer
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 9, shipram_complete, shipram_abort, FUNC );
        timer->buffer->ship = ship;
        timer->buffer->shiptarget = target;
        timer->buffer->long1 = time( 0 );

        // Set the new course
        Vector3 tempvect;
        tempvect.x = target->vpos.x;
        tempvect.y = target->vpos.y;
        tempvect.z = target->vpos.z;
        set_ship_speed( ship, ship->realspeed );
        ship_set_course( ship, &tempvect );

        // Make sure the ship can't do anything else
        ship->shipstate = SHIP_BUSY;
        ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
        return;
    }

    // If they didn't pass the skill check, we still want to lag the ship
    ch_println( ch, "&RYou can't seem to line up with your target's course heading." );
    learn_from_failure( ch, find_gsn( ship->classtype ) );
    ship->shipstate = SHIP_BUSY;
    ship->maneuver_timer = SHIP_MANEUVER_DELAY( ship );
}

int load_hyperwall_sql( const PGresult* qresult, int row )
{
    HYPERWALL_DATA* hyperwall = NULL;
    CREATE( hyperwall, HYPERWALL_DATA, 1 );
    int rval = 0;

    if ( ( rval = fieldmap_postgres_row( qresult, row, hyperwall, hyperwall_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( hyperwall, hyperwall_fields );
        return rval;
    }

    LINK_SORT_NUM( hyperwall, HYPERWALL_DATA, first_hyperwall, last_hyperwall, next, prev, id );
    return E_LOTJ_SUCCESS;
}

int extract_hyperwall( HYPERWALL_DATA* hyperwall )
{
    if ( !hyperwall )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( hyperwall->id > 0 )
        delete_sql_row_by_id( DB_TABLE_HYPERWALLS, hyperwall->id );

    UNLINK( hyperwall, first_hyperwall, last_hyperwall, next, prev );
    FREE_STRUCT( hyperwall, hyperwall_fields );
    return E_LOTJ_SUCCESS;
}

int save_hyperwall( HYPERWALL_DATA* hyperwall )
{
    if ( !hyperwall )
        return E_LOTJ_MISSING_ARGUMENTS;

    return upsert_sql_fieldmap_row(DB_TABLE_HYPERWALLS, hyperwall, hyperwall_fields, NO_FLAG);
}

CMDF do_hyperwall( CHAR_DATA* ch, char* argument )
{
    HYPERWALL_DATA* hyperwall = NULL;
    char arg[MIL], arg2[MIL], arg3[MIL], arg4[MIL], arg5[MIL];
    char start[128], end[128], colstr[8];
    int xpos = 0, ypos = 0, cnt = 0, val = 0;

    IMM_CHECK( ch );

    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Chyperwall list" );
        ch_println( ch, "&z        &Chyperwall create <&wname&C>" );
        ch_println( ch, "&z        &Chyperwall show <&wname/id&C>" );
        ch_println( ch, "&z        &Chyperwall enable/disable/delete <&wname/id&C>" );
        ch_println( ch, "&z        &Chyperwall edit <&wname/id&C> <&wfield&C> <&wval&C>" );
        ch_println( ch, "&z        &Chyperwall label <&wname/id&C> list" );
        ch_println( ch, "&z        &Chyperwall label <&wname/id&C> <&wadd/remove&C> <&wval&C>" );
        ch_println( ch, "&zFields: &Cname&z, &Cstart&z, &Cend&z, &Cminshipsize&z, &Cmaxshipsize" );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        if ( !first_hyperwall )
        {
            ch_println( ch, "&wThere are no hyperwalls set up." );
            return;
        }

        ch_println( ch, "&z%-3s | %-37s | %-10s | %-10s | %-8s", "ID", "NAME", "START", "END", "STATUS" );
        ch_println( ch, "&z--------------------------------------------------------------------------------" );
        for ( hyperwall = first_hyperwall; hyperwall; hyperwall = hyperwall->next )
        {
            cnt++;
            snprintf( colstr, 8, "%s", !hyperwall->enabled ? "&160" : ( cnt % 2 == 0 ? "&037" : "&116" ) );
            snprintf( start, 128, "%d, %d", hyperwall->x1, hyperwall->y1 );
            snprintf( end, 128, "%d, %d", hyperwall->x2, hyperwall->y2 );
            ch_println( ch, "%s%-3d &z| %s%-37s &z| %s%-10s &z| %s%-10s &z| %s%-8s",
            colstr, hyperwall->id,
            colstr, truncate_string( hyperwall->name, 37 ),
            colstr, start,
            colstr, end,
            colstr, hyperwall->enabled ? "Active" : "Disabled" );
        }

        pager_println( ch, "\n&zDisplayed &C%d&z hyperwalls.", cnt );
        return;
    }

    if ( !str_cmp( arg, "create" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Chyperwall create <&wname&C>" );
            return;
        }

        CREATE( hyperwall, HYPERWALL_DATA, 1 );
        SET_STRING( hyperwall->name, stripclr( argument ) );
        hyperwall->minship = SATELLITE_SHIP;
        hyperwall->maxship = SATELLITE_SHIP;
        hyperwall->enabled = FALSE;
        save_hyperwall( hyperwall );
        LINK( hyperwall, first_hyperwall, last_hyperwall, next, prev );
        ch_println( ch, "&zCreated hyperwall: &C%s&z.", hyperwall->name );
        return;
    }

    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg2 ) )
    {
        do_hyperwall( ch, "" );
        return;
    }    

    if ( is_number( arg2 ) )
        hyperwall = hyperwall_from_id( atoi( arg2 ) );
    else
        hyperwall = hyperwall_from_name( arg2 );

    if ( !hyperwall )
    {
        ch_println( ch, "&RCould not find that hyperwall." );
        return;
    }

    if ( !str_cmp( arg, "show" ) )
    {
        ch_println( ch, "&zShowing Hyperwall &C%d&z\n", hyperwall->id );
        ch_println( ch, "&zName: &C%s", hyperwall->name );
        ch_println( ch, "&zStatus: %s", hyperwall->enabled ? "&GENABLED" : "&RDISABLED" );
        ch_println( ch, "&zStarting Sector: &C%d&z, &C%d", hyperwall->x1, hyperwall->y1 );
        ch_println( ch, "&zEnding Sector: &C%d&z, &C%d", hyperwall->x2, hyperwall->y2 );
        ch_println( ch, "&zMinimum Ship Size: &C%s", ship_classes[hyperwall->minship].name );
        ch_println( ch, "&zMaximum Ship Size: &C%s", ship_classes[hyperwall->maxship].name );
        ch_println( ch, "&zLabels:%s", ( hyperwall->first_label != NULL ) ? "" : "&CNone" );
        int i = 0;
        for ( LABEL_DATA* label = hyperwall->first_label; label; label = label->next )
            ch_println( ch, "&z%d: &C%s", ++i, label->label ? label->label : "(NULL)" );

        return;
    }

    if ( !str_cmp( arg, "disable" ) )
    {
        if ( !hyperwall->enabled )
        {
            ch_println( ch, "&RThat hyperwall isn't enabled." );
            return;
        }

        hyperwall->enabled = FALSE;
        save_hyperwall( hyperwall );
        ch_println( ch, "&zDisabled hyperwall &C%d&z (&C%s&z)", hyperwall->id, hyperwall->name );
        return;
    }

    if ( !str_cmp( arg, "enable" ) )
    {
        if ( hyperwall->enabled )
        {
            ch_println( ch, "&RThat hyperwall is already enabled." );
            return;
        }

        if ( hyperwall->x1 == hyperwall->x2 && hyperwall->y1 == hyperwall->y2 )
        {
            ch_println( ch, "&RCannot enable while the starting and ending systems are the same." );
            return;
        }

        hyperwall->enabled = TRUE;
        save_hyperwall( hyperwall );
        ch_println( ch, "&zEnabled hyperwall &C%d&z (&C%s&z)", hyperwall->id, hyperwall->name );
        return;
    }

    if ( !str_cmp( arg, "delete" ) )
    {
        ch_println( ch, "&zDeleted hyperwall &C%d&z (&C%s&z)", hyperwall->id, hyperwall->name );
        extract_hyperwall( hyperwall );
        return;
    }

    if ( !str_cmp( arg, "label" ) )
    {
        argument = one_argument( argument, arg3 );
        if ( NULLSTR( arg3 ) || ( str_cmp( arg3, "add" ) && str_cmp( arg3, "remove" ) && str_cmp( arg3, "list" ) ) )
        {
            ch_println( ch, "&zSyntax: &Chyperwall label <&wname/id&C> list" );
            ch_println( ch, "&z        &Chyperwall label <&wname/id&C> <&wadd/remove&C> <&wval&C>" );
            return;
        }

        if ( !str_cmp( arg3, "list" ) )
        {
            if ( !hyperwall->first_label )
            {
                ch_println( ch, "There are no labels attached to this hyperwall." );
                return;
            }
            ch_println( ch, "&zLabels for hyperwall &C%d&z (&C%s&z):", hyperwall->id, hyperwall->name );
            cnt = 0;
            for ( LABEL_DATA* label = hyperwall->first_label; label; label = label->next )
                ch_println( ch, "&zLabel %d: &C%s", ++cnt, label->label );

            ch_println( ch, "\n&zDisplayed &C%d&z labels.", cnt );
            return;
        }

        bool add = !str_cmp( arg3, "add" );
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Chyperwall label <&wname/id&C> %s <&wval&C>", arg3 );
            return;
        }

        if ( add )
            add_label( &hyperwall->first_label, &hyperwall->last_label, argument );
        else
            remove_label( &hyperwall->first_label, &hyperwall->last_label, argument );

        save_hyperwall( hyperwall );
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg, "edit" ) )
    {
        argument = one_argument( argument, arg3 );

        if ( !str_cmp( arg3, "name" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> name <&wvalue&C>" );
                return;
            }

            SET_STRING( hyperwall->name, stripclr( argument ) );
            save_hyperwall( hyperwall );
            ch_println( ch, "&zHyperwall &C%d&z name set to &C%s&z.", hyperwall->id, hyperwall->name );
            return;
        }

        argument = one_argument( argument, arg4 );
        argument = one_argument( argument, arg5 );

        if ( NULLSTR( arg3 ) || NULLSTR( arg4 ) || ( ( !str_cmp( arg3, "start" ) || !str_cmp( arg3, "end" ) ) && NULLSTR( arg5 ) ) )
        {
            ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> name <&wvalue&C>" );
            ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> start <&wxpos&C> <&wypos&C>" );
            ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> end <&wxpos&C> <&wypos&C>" );
            ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> minshipsize <&wship size&C> (e.g., \"fighter\")" );
            ch_println( ch, "&zSyntax: &Chyperwall edit <&wname/id&C> maxshipsize <&wship size&C> (e.g., \"battleship\")" );
            return;
        }

        if ( !str_cmp( arg3, "start" ) )
        {
            xpos = atoi( arg4 );
            ypos = atoi( arg5 );

            if ( xpos == hyperwall->x2 && ypos == hyperwall->y2 )
            {
                ch_println( ch, "&RThe starting and ending systems cannot be the same." );
                return;
            }

            hyperwall->x1 = xpos;
            hyperwall->y1 = ypos;
            save_hyperwall( hyperwall );
            ch_println( ch, "&zStarting system set to &C%d&z, &C%d&z.", hyperwall->x1, hyperwall->y1 );
            return;
        }

        if ( !str_cmp( arg3, "end" ) )
        {
            xpos = atoi( arg4 );
            ypos = atoi( arg5 );

            if ( xpos == hyperwall->x1 && ypos == hyperwall->y1 )
            {
                ch_println( ch, "&RThe starting and ending systems cannot be the same." );
                return;
            }

            hyperwall->x2 = xpos;
            hyperwall->y2 = ypos;
            save_hyperwall( hyperwall );
            ch_println( ch, "&zEnding system set to &C%d&z, &C%d&z.", hyperwall->x2, hyperwall->y2 );
            return;
        }

        if ( !str_cmp( arg3, "minshipclass" ) || !str_cmp( arg3, "maxshipclass" ) || !str_cmp( arg3, "minshipsize" ) || !str_cmp( arg3, "maxshipsize" ) )
        {
            bool minclass = ( !str_cmp( arg3, "minshipclass" ) || !str_cmp( arg3, "minshipsize" ) );
            val = get_flag( arg4, ship_classes );
            if ( val == FLAG_UNDEFINED )
            {
                ch_println( ch, "&RInvalid ship class: %s", arg4 );
                return;
            }

            if ( minclass )
                hyperwall->minship = val;
            else
                hyperwall->maxship = val;

            save_hyperwall( hyperwall );
            ch_println( ch, "&z%s ship class set to %s", minclass ? "Minimum" : "Maximum", ship_classes[val].name );
            return;
        }

        do_hyperwall( ch, "" );
        return;
    }

    do_hyperwall( ch, "" );
    return;
}

HYPERWALL_DATA* hyperwall_from_name( const char* name )
{
    HYPERWALL_DATA* result = NULL;

    if ( NULLSTR( name ) )
        return NULL;

    for ( result = first_hyperwall; result; result = result->next )
        if ( !str_cmp( result->name, name ) )
            break;

    if ( !result )
        for ( result = first_hyperwall; result; result = result->next )
            if ( !str_prefix( name, result->name ) )
                break;

    return result;
}

HYPERWALL_DATA* hyperwall_from_id( int id )
{
    HYPERWALL_DATA* result = NULL;

    if ( id <= 0 )
        return NULL;

    for ( result = first_hyperwall; result; result = result->next )
        if ( result->id == id )
            break;

    return result;
}

bool valid_ship( SHIP_DATA* ship )
{    
    if ( !ship )
        return FALSE;

    if ( !hashset_contains( valid_ships, ship ) )
        return FALSE;

    return TRUE;
}

