int makeblade_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char buf[MSL];
    double value = 0, mindam = 0, maxdam = 0;

    char* argument = buffer->str1;
    OBJ_DATA* durasteel = get_obj_from_buffer( buffer, "durasteel" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( ch->skill_level[ENGINEERING_ABILITY] + get_learned_pct( ch, cache_skill( "makeblade", &skill_makeblade ) ) / 2 );

    int duramod = durasteel->value[0]; //Durasteel's quality modifier for cost
    int duramod2 = durasteel->value[1]; //Durasteel's quality modifier for damage
    value += durasteel->pIndexData->cost;

    int supermod = super->value[0]; //Superconductor's quality modifier
    value += super->pIndexData->cost;

    double charge = battery->value[0];
    int battmod = battery->value[1]; //Battery's quality modifier
    value += battery->pIndexData->cost;

    int circuitmod = circuit->value[0]; //Circuit's quality modifier
    value += circuit->pIndexData->cost;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_BLADE ), ch->max_move );
    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makeblade", &skill_makeblade ) ) );

    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou activate your newly created vibroblade." );
        ch_println( ch, "&RIt hums softly for a few seconds then begins to shake violently." );
        ch_println( ch, "&RIt finally shatters breaking apart into a dozen pieces." );
        learn_from_failure( ch, cache_skill( "makeblade", &skill_makeblade ) );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    //Bonuses to base damage from science values
    if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) == 100 )
    {
        ch_println( ch, "Your skill in Equipment lets you make a better vibroblade." );
        level += 20;
    }

    if ( get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) == 100 )
    {
        ch_println( ch, "Your skill in Destruction lets you make a better vibroblade." );
        level += 20;
    }

    maxdam = level * 1.125 - 30;
    maxdam *= 1 + ( double )circuitmod / 100;
    maxdam *= 1 + ( double )supermod / 100;
    mindam = maxdam * 0.75;
    value *= 1 + ( duramod / 100. ); // Increase value by durasteel modifier percentage
    charge *= 1 + ( battmod / 100. ); // Increase ammo by battery modifier percentage

    OBJ_DATA* obj = create_object( pObjIndex, level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    set_crafted( ch, obj );
    obj->item_type = ITEM_WEAPON;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_WIELD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    obj->level = level;
    obj->weight = 18;
    strlcpy( buf, argument, MSL );
    strlcat( buf, " vibroblade blade", MSL );
    SET_STRING( obj->name, stripclr( buf ) );
    strlcpy( buf, argument, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was left here.", MSL );
    SET_STRING( obj->description, buf );
    obj->value[0] = INIT_WEAPON_CONDITION;
    obj->value[1] = ( int ) mindam;
    obj->value[2] = ( int ) maxdam;
    obj->value[3] = WEAPON_VIBRO_BLADE;
    obj->value[4] = ( int ) charge;
    obj->value[5] = ( int ) charge;
    obj->cost = calc_markup( ch, ( int ) value );
    add_affect_to_obj( obj, APPLY_DAMROLL, duramod2 );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created blade.&w" );
    act( AT_PLAIN, "$n finishes crafting a vibro-blade.", ch, NULL, argument, TO_ROOM );
    long xpgain;
    xpgain = UMIN( obj->cost * 200, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makeblade", &skill_makeblade ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makeblade( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakeblade <&wname&C>&w&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make a vibroblade." );
        return;
    }

    OBJ_DATA* durasteel = get_obj_carried_of_type( ch, ITEM_DURASTEEL );
    if ( !durasteel )
    {
        ch_println( ch, "&RYou need some durasteel for the vibroblade mold." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a power source for the vibroblade." );
        return;
    }

    OBJ_DATA* oven = get_obj_carried_of_type( ch, ITEM_OVEN );
    if ( !oven )
    {
        ch_println( ch, "&RYou need an oven to heat and shape the material." );
        return;
    }

    OBJ_DATA* circuit = get_obj_carried_of_type( ch, ITEM_CIRCUIT );
    if ( !circuit )
    {
        ch_println( ch, "&RYou need a circuit board to control the activation mechanism." );
        return;
    }

    OBJ_DATA* super = get_obj_carried_of_type( ch, ITEM_SUPERCONDUCTOR );
    if ( !super )
    {
        ch_println( ch, "&RYou need a superconductor to regulate the the current." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_BLADE ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, makeblade_complete, makeblade_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "oven", oven );
    add_consumable_to_buffer( timer->buffer, "durasteel", durasteel, "Durasteel" );
    add_consumable_to_buffer( timer->buffer, "battery", battery, "Battery" );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "super", super, "Superconductor" );

    ch_println( ch, "&GYou begin the long process of crafting a vibroblade." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and a small oven and begins to work on something.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is assembling a vibroblade.", NULL, 0 );
}

