CMDF do_makeblaster( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) || NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakeblaster <&wrepeater&z/&wpistol&z/&wrifle&C> <&wname&C>" );
        return;
    }

    if ( str_cmp( arg, "repeater" ) && str_cmp( arg, "pistol" ) && str_cmp( arg, "rifle" ) )
    {
        ch_println( ch, "&wInvalid blaster class. Choices:&C repeater&w,&C pistol&w,&C rifle&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !nifty_is_name( arg, stripclr( argument ) ) )
    {
        ch_println( ch, "You must include '%s' somewhere in the name of the weapon!", arg );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA *crystal1 = NULL, *crystal2 = NULL, *crystal3 = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !crystal3 && obj->item_type == ITEM_CRYSTAL && obj->value[2] == 0 )
        {
            if ( !crystal1 )
                crystal1 = obj;
            else if ( !crystal2 && crystal1 != obj )
                crystal2 = obj;
            else if ( !crystal3 && crystal1 != obj && crystal2 != obj )
                crystal3 = obj;
            else
                continue;
        }
    }

    OBJ_DATA* cool = NULL;
    if ( !str_cmp( "repeater", arg ) )
    {
        cool = get_obj_carried_of_type( ch, ITEM_COOLINGUNIT );
        if ( !cool )
        {
            ch_println( ch, "&RTo make a repeater you need a cooling unit." );
            return;
        }
    }

    OBJ_DATA* scope = NULL;
    if ( !str_cmp( "rifle", arg ) )
    {
        scope = get_obj_carried_of_type( ch, ITEM_SCOPE );
        if ( !scope )
        {
            ch_println( ch, "&RTo make a rifle you need a scope." );
            return;
        }
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make a blaster." );
        return;
    }

    OBJ_DATA* duraplast = get_obj_carried_of_type( ch, ITEM_DURAPLAST );
    if ( !duraplast )
    {
        ch_println( ch, "&RYou need duraplast for the blaster mold." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a power source for the blaster." );
        return;
    }

    OBJ_DATA* ammo = get_obj_carried_of_type( ch, ITEM_AMMO );
    if ( !ammo )
    {
