int makelightsaber_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* argument = buffer->str1;
    OBJ_DATA* durasteel = get_obj_from_buffer( buffer, "durasteel" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* mirror = get_obj_from_buffer( buffer, "mirror" );
    OBJ_DATA* lens = get_obj_from_buffer( buffer, "lens" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    OBJ_DATA* crystal1 = get_obj_from_buffer( buffer, "crystal1" );
    OBJ_DATA* crystal2 = get_obj_from_buffer( buffer, "crystal2" );
    OBJ_DATA* crystal3 = get_obj_from_buffer( buffer, "crystal3" );

    char buf[MSL];
    bool twinblade = FALSE;
    OBJ_INDEX_DATA* pObjIndex = NULL;
    int crystalmod = 0, duramod = 0, battmod = 0, supermod = 0, circuitmod = 0, lensmod = 0, mirrormod = 0;
    double value = 0, charge = 0, mindam = 0, maxdam = 0;

    if ( IS_OBJ_STAT( durasteel, ITEM_TWINBLADE ) )
        twinblade = TRUE;

    duramod = durasteel->value[0]; //Durasteel's quality modifier for cost
    value += durasteel->pIndexData->cost;

    charge = battery->value[0];
    battmod = battery->value[1]; //Battery's quality modifier
    value += battery->pIndexData->cost;

    supermod = super->value[0]; //Superconductor's quality modifier
    value += super->pIndexData->cost;

    circuitmod = circuit->value[0]; //Circuit's quality modifier
    value += circuit->pIndexData->cost;

    lensmod = lens->value[0]; //Lens' quality modifier
    value += lens->pIndexData->cost;

    mirrormod = mirror->value[0]; //Mirror's quality modifier
    value += mirror->pIndexData->cost;

    if ( crystal1 )
    {
        pObjIndex = crystal1->pIndexData;
        crystalmod += crystal1->value[0]; //Crystal's quality modifier
        value += crystal1->pIndexData->cost;
    }

    if ( crystal2 )
    {
        crystalmod += crystal2->value[0]; //Crystal's quality modifier
        value += crystal2->pIndexData->cost;
    }

    if ( crystal3 )
    {
        crystalmod += crystal3->value[0]; //Crystal's quality modifier
        value += crystal3->pIndexData->cost;
    }

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, FORCE_ABILITY, EFFORT_LIGHTSABER ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "lightsaber crafting", &skill_lightsaber_crafting ) ) ) ;
    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou hold up your new lightsaber and press the switch hoping for the best." );
        ch_println( ch, "&RInstead of a blade of light, smoke starts pouring from the handle." );
        ch_println( ch, "&RYou drop the hot handle and watch as it melts on away on the floor." );
        learn_from_failure( ch, cache_skill( "lightsaber crafting", &skill_lightsaber_crafting ) );
        return E_LOTJ_SUCCESS;
    }

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "lightsaber crafting", &skill_lightsaber_crafting ) ) );
    level += 3 * crystalmod; //Increase level variable by twice amount of crystal quality modifiers
    maxdam = level * 0.265 + 10;
    maxdam *= 1 + ( double )circuitmod / 100;
    maxdam *= 1 + ( double )supermod / 100;
    mindam = maxdam * 0.75;
    value *= 1 + ( duramod / 100. ); //Increase value by duraplast modifier percentage
    charge *= 1 + ( battmod / 100. ); //Increase ammo by battery modifier percentage
    OBJ_DATA* obj = create_object( pObjIndex, level );
    xCLEAR_BITS( obj->extra_flags );
    set_crafted( ch, obj );
    obj->item_type = ITEM_WEAPON;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_WIELD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    obj->level = level;
    obj->weight = 5;
    obj->cost = calc_markup( ch, ( int ) value );
    strlcpy( buf, "lightsaber saber ", MSL );
    strlcat( buf, stripclr( argument ), MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, argument, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MSL );
    SET_STRING( obj->description, buf );
    strlcpy( buf, argument, MSL );
    strlcat( buf, " ignites with a hum and a soft glow.", MSL );
    SET_STRING( obj->action_desc, buf );
    obj->value[0] = INIT_WEAPON_CONDITION;       /* condition  */
    obj->value[1] = ( int ) mindam;    /* min dmg  */
    obj->value[2] = ( int ) maxdam;    /* max dmg */
    obj->value[3] = WEAPON_LIGHTSABER;
    obj->value[4] = ( int ) charge;
    obj->value[5] = ( int ) charge;

    if ( twinblade )
        xSET_BIT( obj->extra_flags, ITEM_TWINBLADE );

    add_affect_to_obj( obj, APPLY_HITROLL, lensmod );
    add_affect_to_obj( obj, APPLY_DAMROLL, mirrormod );

    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created lightsaber.&w" );
    act( AT_PLAIN, "$n finishes making $s new lightsaber.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 10, number_range( 1000, 20000 ) );
    xpgain = apply_xp_sink( ch, xpgain, FORCE_ABILITY );
    gain_exp( ch, xpgain, FORCE_ABILITY, TRUE );
    ch_println( ch, "You gain %d force experience.", xpgain );
    learn_from_success( ch, cache_skill( "lightsaber crafting", &skill_lightsaber_crafting ) );

    if ( ch->skill_level[FORCE_ABILITY] >= 40 && ch->pcdata->frank == FRANK_APPRENTICE )
    {
        ch->pcdata->frank = FRANK_KNIGHT;
        FORCER_DATA* forcer = forcer_create( ch );
        CHAR_DATA* fmaster = NULL;

        if ( forcer && !NULLSTR( forcer->master ) )
            fmaster = get_player_world( forcer->master );

        if ( fmaster )
            ch_println( fmaster, "&RYour apprentice has completed their training and reached the rank of %s!", get_auto_frank( ch, FRANK_KNIGHT ) );

        remove_force_master( forcer );
        ch_println( ch, "&RYou have completed your training, and reached the rank of %s!", get_auto_frank( ch, FRANK_KNIGHT ) );
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_makelightsaber( CHAR_DATA* ch, char* argument )
{
    if ( IS_NPC( ch ) )
        return;

    if ( ( int ) ( get_learned_pct( ch, cache_skill( "lightsaber crafting", &skill_lightsaber_crafting ) ) ) == 0 )
    {
        ch_println( ch, "&wHuh?" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakelightsaber <&wname&C>&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_SILENCE ) )
    {
        ch_println( ch, "&RYou need to be in a quiet, peaceful place to craft a lightsaber." );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_NO_SENSE ) )
    {
        ch_println( ch, "&RYou cannot make a lightsaber while cut off from the force." );
        return;
    }

    OBJ_DATA *crystal1 = NULL, *crystal2 = NULL, *crystal3 = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !crystal3 && obj->item_type == ITEM_CRYSTAL && obj->value[2] == 1 )
        {
            if ( !crystal1 )
                crystal1 = obj;
            else if ( !crystal2 && crystal1 != obj )
                crystal2 = obj;
            else if ( !crystal3 && crystal1 != obj && crystal2 != obj )
                crystal3 = obj;
            else
                continue;
        }
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make a lightsaber." );
        return;
    }

    OBJ_DATA* durasteel = get_obj_carried_of_type( ch, ITEM_DURASTEEL );
    if ( !durasteel )
    {
        ch_println( ch, "&RYou need durasteel for the lightsaber mold." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a power source for the lightsaber." );
        return;
    }

    OBJ_DATA* oven = get_obj_carried_of_type( ch, ITEM_OVEN );
    if ( !oven )
    {
        ch_println( ch, "&RYou need an oven to heat and shape the material." );
        return;
    }

    OBJ_DATA* circuit = get_obj_carried_of_type( ch, ITEM_CIRCUIT );
    if ( !circuit )
    {
        ch_println( ch, "&RYou need a circuit board to control the activation mechanism." );
        return;
    }

    OBJ_DATA* super = get_obj_carried_of_type( ch, ITEM_SUPERCONDUCTOR );
    if ( !super )
    {
        ch_println( ch, "&RYou need a superconductor to regulate the current." );
        return;
    }

    OBJ_DATA* lens = get_obj_carried_of_type( ch, ITEM_LENS );
    if ( !lens )
    {
        ch_println( ch, "&RYou need a lens to focus the energy beam." );
        return;
    }

    if ( !crystal1 )
    {
        ch_println( ch, "&RLightsabers require 1 to 3 gems to work properly." );
        return;
    }

    OBJ_DATA* mirror = get_obj_carried_of_type( ch, ITEM_MIRROR );
    if ( !mirror )
    {
        ch_println( ch, "&RYou need a reflective cup to amplify the energy beam." );
        return;
    }

    if ( calc_effortrate( ch, FORCE_ABILITY, EFFORT_LIGHTSABER ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, makelightsaber_complete, makelightsaber_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "oven", oven );
    add_consumable_to_buffer( timer->buffer, "durasteel", durasteel, "Durasteel" );
    add_consumable_to_buffer( timer->buffer, "battery", battery, "Battery" );
    add_consumable_to_buffer( timer->buffer, "mirror", mirror, "Mirror" );
    add_consumable_to_buffer( timer->buffer, "lens", lens, "Lens" );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "super", super, "Superconductor" );
    add_consumable_to_buffer( timer->buffer, "crystal1", crystal1, "First Crystal" );
    if ( crystal2 ) add_consumable_to_buffer( timer->buffer, "crystal2", crystal2, "Second Crystal" );
    if ( crystal3 ) add_consumable_to_buffer( timer->buffer, "crystal3", crystal3, "Third Crystal" );
    ch_println( ch, "&GYou begin the long process of crafting a lightsaber." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and a small oven and begins to work on something.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is creating a lightsaber.", NULL, 0 );
}

