int makespice_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char buf[MSL];
    char* arg = buffer->str1;
    OBJ_DATA* spice = get_obj_from_buffer( buffer, "spice" );

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, SMUGGLING_ABILITY, EFFORT_SPICE ), ch->max_move );
    xREMOVE_BIT( spice->extra_flags, ITEM_PROTOTYPE );
    strlcpy( buf, stripclr( arg ), MSL );
    SET_STRING( spice->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( spice->short_descr, buf );
    strlcat( buf, " was foolishly left lying around here.", MSL );
    SET_STRING( spice->description, buf );
    spice->item_type = ITEM_SPICE;

    // Increase toxicity if made by people with less than 100% narcotics science
    if ( ch->pcdata && get_learned_pct( ch, cache_skill( "narcotics", &skill_narcotics ) ) < 100 )
        spice->value[2] = UMIN( spice->value[2] + 20, 90 );
    else
        ch_println( ch, "&GYour study in narcotics enables you to produce a purer product." );

    set_crafted( ch, spice );
    spice->cost *= 5;
    ch_println( ch, "&GYou finish your work." );
    act( AT_PLAIN, "$n finishes $s work.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( spice->cost * 50, ( exp_level( ch->skill_level[SMUGGLING_ABILITY] + 1 ) - exp_level( ch->skill_level[SMUGGLING_ABILITY] ) ) );
    xpgain = apply_xp_sink( ch, xpgain, SMUGGLING_ABILITY );
    gain_exp( ch, xpgain, SMUGGLING_ABILITY, TRUE );
    ch_println( ch, "You gain %d smuggling experience.", xpgain );
    learn_from_success( ch, cache_skill( "spice refining", &skill_spice_refining ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makespice( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char* arg2 = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) || NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &CMAKESPICE <&wrawspice&C> <&wfinished product's name&C>&w" );
        return;
    }

    if ( !valid_obj_name( arg2 ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_REFINERY ) )
    {
        ch_println( ch, "&RYou need to be in a refinery to create drugs from spice." );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    OBJ_DATA* spice = get_obj_carry( ch, arg1 );
    if ( !spice )
    {
        ch_println( ch, "&RYou do not have that item.&w" );
        return;
    }

    if ( spice->item_type != ITEM_RAWSPICE )
    {
        ch_println( ch, "&RYou can't make a drug out of that.&w" );
        return;
    }

    if ( calc_effortrate( ch, SMUGGLING_ABILITY, EFFORT_SPICE ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "spice refining", &skill_spice_refining ) ) );
    if ( number_percent( ) <= chance )
    {
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, makespice_complete, makespice_abort, FUNC );
        SET_STRING( timer->buffer->str1, arg2 );
        add_obj_to_buffer( timer->buffer, "spice", spice );
        ch_println( ch, "&GYou begin the long process of refining spice into a drug." );
        ch_println( ch, "&wYour finished product will look like: %s", arg2 );
        act( AT_PLAIN, "$n begins working on something.", ch, NULL, argument, TO_ROOM );
        action_set( ch, NULL, "is refining some spice.", NULL, 0 );
        return;
    }

    ch_println( ch, "&RYou can't figure out what to do with the stuff." );
    learn_from_failure( ch, cache_skill( "spice refining", &skill_spice_refining ) );
}

