int makegrenade_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    char buf[MSL];
    int strength = 0, weight = 0, value = 0, type = 0;

    OBJ_DATA* drinkcon = get_obj_from_buffer( buffer, "drinkcon" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* chemicals = get_obj_from_buffer( buffer, "chemicals" );

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    value += drinkcon->pIndexData->cost;
    value += battery->pIndexData->cost;
    value += chemicals->pIndexData->cost;
    value += circuit->pIndexData->cost;

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makegrenade", &skill_makegrenade ) ) );
    strength = URANGE( 20, chemicals->value[0], level * 500 );
    type = chemicals->value[2];
    weight = chemicals->weight;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_GRENADE ), ch->max_move );

    if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) == 100 )
    {
        ch_println( ch, "&wYour skill in destruction renders a more powerful explosive." );
        strength += 40;
    }

    OBJ_DATA* obj = create_object( pObjIndex, level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    set_crafted( ch, obj );
    obj->item_type = ITEM_GRENADE;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_HOLD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    obj->level = level;
    obj->weight = weight;
    strlcpy( buf, stripclr( arg ), MSL );
    strlcat( buf, " grenade", MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MSL );
    SET_STRING( obj->description, buf );
//Smoke v0/1 dictate rounds, not damage, so we need a different formula
if ( type == GRENADE_SMOKE )
{
    obj->value[0] = chemicals->value[0];
    obj->value[1] = chemicals->value[1];
}
else
{
    obj->value[0] = strength / 2;
    obj->value[1] = strength;
}

    if ( type == GRENADE_NORMAL || type == GRENADE_CONCUSSION || type == GRENADE_BOMB )
        obj->value[2] = URANGE( 1, level / 10, 10 );
    else // Special grenades should only hit the room they're in to make them more useful/specialized.
        obj->value[2] = 0;

    obj->value[3] = type;
    obj->cost = calc_markup( ch, value * 2 );
    obj = obj_to_char( obj, ch );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makegrenade", &skill_makegrenade ) ) ) ;
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RA low whining sound emanates from the grenade as you put the final touches\non it. You silently whimper to yourself..." );
        SET_STRING( obj->armed_by, ch->name );
        obj->value[4] = 1;
        learn_from_failure( ch, cache_skill( "makegrenade", &skill_makegrenade ) );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "&GYou finish your work and hold up your newly created grenade.&w" );
    act( AT_PLAIN, "$n finishes making $s new grenade.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 50, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makegrenade", &skill_makegrenade ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makegrenade( CHAR_DATA* ch, char* argument )
{
