CMDF do_makejewelry( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char* arg2 = one_argument( argument, arg );

    if ( NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &CMakejewelry <&wwearloc&C> <&wname&C>&w" );
        return;
    }

    int wearloc = get_flag( arg, wear_types );
    if ( wearloc != ITEM_WEAR_FINGER &&
         wearloc != ITEM_WEAR_NECK &&
         wearloc != ITEM_WEAR_BODY &&
         wearloc != ITEM_WEAR_WRIST &&
         wearloc != ITEM_WEAR_EARS )
    {
        ch_println( ch, "&RYou cannot make jewelry for that body part. See HELP WEARLOCS.&w" );
        return;
    }

    if ( !valid_obj_name( arg2 ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA *crystal1 = NULL, *crystal2 = NULL, *crystal3 = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !crystal3 && obj->item_type == ITEM_CRYSTAL )
        {
            if ( !crystal1 )
                crystal1 = obj;
            else if ( !crystal2 && crystal1 != obj )
                crystal2 = obj;
            else if ( !crystal3 && crystal1 != obj && crystal2 != obj )
                crystal3 = obj;
            else
                continue;
        }
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make jewelry." );
        return;
    }

    OBJ_DATA* oven = get_obj_carried_of_type( ch, ITEM_OVEN );
    if ( !oven )
    {
        ch_println( ch, "&RYou need an oven to heat and shape the material." );
        return;
    }

    OBJ_DATA* metal = get_obj_carried_of_type( ch, ITEM_RARE_METAL );
    if ( !metal )
    {
        ch_println( ch, "&RYou need some precious metal." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_JEWELRY ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 45, makejewelry_complete, makejewelry_abort, FUNC );
    timer->buffer->num1 = wearloc;
    SET_STRING( timer->buffer->str1, arg2 );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "oven", oven );
    add_consumable_to_buffer( timer->buffer, "metal", metal, "Metal" );
    if ( crystal1 ) add_consumable_to_buffer( timer->buffer, "crystal1", crystal1, "First Crystal" );
    if ( crystal2 ) add_consumable_to_buffer( timer->buffer, "crystal2", crystal2, "Second Crystal" );
    if ( crystal3 ) add_consumable_to_buffer( timer->buffer, "crystal3", crystal3, "Third Crystal" );

    ch_println( ch, "&GYou begin the long process of creating some jewelry." );
    ch_println( ch, "&wYour finished product will look like: %s", arg2 );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s toolkit and some metal and begins to work.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is crafting some jewelry", NULL, 0 );

    add_obj_to_buffer( timer->buffer, "metal", metal ); // Set as nonconsumed now that we printed output
}

