    OBJ_DATA* ingr2 = get_obj_from_buffer( buffer, "ingr2" );
    OBJ_DATA* ingr3 = get_obj_from_buffer( buffer, "ingr3" );

    char buf[MSL], ingredients[MSL];
    int bonus = 0, calories = 0, value = 0;

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    bonus += ingr1->value[0]; /* HP bonus based on ingredient quality*/
    calories += 5;
    value += ingr1->pIndexData->cost;
    snprintf( ingredients, MSL, "%s", ingr1->short_descr );

    if ( ingr2 )
    {
        bonus += ingr2->value[0]; /* HP bonus based on ingredient quality*/
        calories += 5;
        value += ingr2->pIndexData->cost;
        snprintf( ingredients + strlen( ingredients ), MSL - strlen( ingredients ), "%s%s", ingr3 ? ", " : " and ", ingr2->short_descr );
    }

    if ( ingr3 )
    {
        bonus += ingr3->value[0]; /* HP bonus based on ingredient quality*/
        calories += 5;
        value += ingr3->pIndexData->cost;
        snprintf( ingredients + strlen( ingredients ), MSL - strlen( ingredients ), ", and %s", ingr3->short_descr );   
    }

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, LEADERSHIP_ABILITY, EFFORT_FOOD ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makefood", &skill_makefood ) ) ) ;
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou finish cooking a meal..." );
        ch_println( ch, "&R...and quickly realize it's inedible." );
        learn_from_failure( ch, cache_skill( "makefood", &skill_makefood ) );
        return E_LOTJ_SUCCESS;
    }

    // Small HP bonus from edibles skill (potential for imbalance offset by re-adding fullness limit)
    if ( get_learned_pct( ch, cache_skill( "edibles", &skill_edibles ) ) == 100 )
    {
        ch_println( ch, "Your skill in Edibles lets you make a heartier, more restorative meal." );
        bonus *= 2;
    }

    calories += ( bonus / 5 ); /* for balance: the more food heals you, the less additional food you can eat afterwards */
    OBJ_DATA* obj = create_object( pObjIndex, ch->top_level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    obj->item_type = ITEM_FOOD;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_HOLD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    set_crafted( ch, obj );
    obj->weight = 2;
    strlcpy( buf, stripclr( argument ), MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, argument, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly left here.", MSL );
    SET_STRING( obj->description, buf );
    obj->value[0]    = calories; /* calorie count */
    obj->value[1]    = 0; /* special condition/poison factor */
    obj->value[2]    = bonus; /* HP bonus */
    obj->value[3]    = 0; /* poison factor */
    obj->cost = calc_markup( ch, ( int ) value );
    obj->cost = UMAX( 1, obj->cost );
    set_dvar_string( obj->vars, "ingredients", ingredients, 0 );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and package up your newly-cooked meal.&w" );
    act( AT_PLAIN, "$n finishes cooking a meal.", ch, NULL, NULL, TO_ROOM );

    long xpgain = UMIN( obj->cost * 100, ( exp_level( ch->skill_level[LEADERSHIP_ABILITY] + 1 ) - exp_level( ch->skill_level[LEADERSHIP_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, LEADERSHIP_ABILITY );
    gain_exp( ch, xpgain, LEADERSHIP_ABILITY, TRUE );
    ch_println( ch, "You gain %d leadership experience.", xpgain );
    learn_from_success( ch, cache_skill( "makefood", &skill_makefood ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makefood( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakefood <&wname&C>&w" );
        ch_println( ch, "&zRequires: &CSome cookware and 1 to 3 ingredients&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    OBJ_DATA* cookware = get_obj_carried_of_type( ch, ITEM_COOKWARE );
    if ( !cookware )
    {
        ch_println( ch, "&RYou need some cookware to prepare a meal with." );
        return;
    }

    OBJ_DATA *ingr1 = NULL, *ingr2 = NULL, *ingr3 = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !ingr3 && obj->item_type == ITEM_FOOD_INGREDIENT )
        {
            if ( !ingr1 )
                ingr1 = obj;
            else if ( !ingr2 && ingr1 != obj )
                ingr2 = obj;
            else if ( !ingr3 && ingr1 != obj && ingr2 != obj )
                ingr3 = obj;
            else
                continue;
        }
    }

    if ( !ingr1 )
    {
        ch_println( ch, "&RYou need at least one food ingredient to prepare a meal with." );
        return;
    }

    if ( calc_effortrate( ch, LEADERSHIP_ABILITY, EFFORT_FOOD ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, makefood_complete, makefood_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "cookware", cookware );
    add_consumable_to_buffer( timer->buffer, "ingr1", ingr1, "First Ingredient" );
    if ( ingr2 ) add_consumable_to_buffer( timer->buffer, "ingr2", ingr2, "Second Ingredient" );
    if ( ingr3 ) add_consumable_to_buffer( timer->buffer, "ingr3", ingr3, "Third Ingredient" );

    ch_println( ch, "&GYou begin the long process of cooking a meal." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n begins cooking a meal.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is cooking a meal.", NULL, 0 );
}

