    if ( ingr2 )
    {
        drinkval += ingr2->value[0]; /* HP bonus based on ingredient quality*/
        snprintf( ingredients + strlen( ingredients ), MSL - strlen( ingredients ), "%s%s", ingr3 ? ", " : " and ", ingr2->short_descr );
    }

    if ( ingr3 )
    {
        drinkval += ingr3->value[0]; /* HP bonus based on ingredient quality*/
        snprintf( ingredients + strlen( ingredients ), MSL - strlen( ingredients ), ", and %s", ingr3->short_descr );   
    }

    /*  The process to keep the drink value (which, in turn, selects the drink from the liq_table) within bounds, regardless of the ingredients used.
        This is one of a dozen ways I could've done it... but it'll surely keep players guessing awhile as they test out ingredients! */
    while ( drinkval < 0 || drinkval > ( LIQ_MAX - 1 ) )
    {
        if ( drinkval < 0 )
            drinkval = ( 0 - drinkval );

        if ( drinkval > ( LIQ_MAX - 1 ) )
            drinkval = ( ( LIQ_MAX - 1 ) - ( drinkval - ( LIQ_MAX - 1 ) ) );
    }

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, LEADERSHIP_ABILITY, EFFORT_DRINK ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makedrink", &skill_makedrink ) ) ) ;
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou finish making the drink..." );
        ch_println( ch, "&R...and quickly realize it's ruined somehow." );
        learn_from_failure( ch, cache_skill( "makedrink", &skill_makedrink ) );
        return E_LOTJ_SUCCESS;
    }

    // Bonuses to canteen storage capacity from edibles skill
    if ( get_learned_pct( ch, cache_skill( "edibles", &skill_edibles ) ) == 100 )
    {
        ch_println( ch, "Your skill in Edibles improves the quantity of drink you make." );
        bonus = 1.25;
    }

    separate_obj( canteen );

    if ( canteen->cost > 2500 )
        canteen->cost = 2500; // Fixing any canteens with bloated cost values that get re-used

    /* Restore canteen to its original capacity before expanding it */
    if ( canteen->value[0] > ( canteen->value[5] > 0 ? canteen->value[5] : 75 ) )
        canteen->value[0] = canteen->pIndexData->value[0] > 0 ? canteen->pIndexData->value[0] : ( canteen->value[5] > 0 ? canteen->value[5] : 75 ); // Reset the canteen

    canteen->value[0] = ( int ) ( canteen->value[0] * bonus );
    canteen->value[1] = canteen->value[0];
    canteen->value[2] = drinkval;
    set_dvar_string( canteen->vars, "drinkname", arg, 0 );
    set_dvar_string( canteen->vars, "ingredients", ingredients, 0 );
    ch_println( ch, "&GYou finish mixing the %s&G liquid and package it up.&w", liq_table[drinkval].liq_color );
    ch_println( ch, "&WYou carefully fix a \"%s&W\" label on %s&W.&w", arg, canteen->short_descr );
    act( AT_PLAIN, "$n finishes making a drink.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( canteen->cost * 100, ( exp_level( ch->skill_level[LEADERSHIP_ABILITY] + 1 ) - exp_level( ch->skill_level[LEADERSHIP_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, LEADERSHIP_ABILITY );
    gain_exp( ch, xpgain, LEADERSHIP_ABILITY, TRUE );
    ch_println( ch, "You gain %d leadership experience.", xpgain );
    learn_from_success( ch, cache_skill( "makedrink", &skill_makedrink ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makedrink( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char* arg2 = one_argument( argument, arg );

    if ( NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &CMakedrink <&wdrink container&C> <&wdrink name&C>&w" );
        ch_println( ch, "&zRequires: &CSome cookware, an empty drink container, and 1 to 3 ingredients&w" );
        return;
    }

    if ( !valid_obj_name( arg2 ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    OBJ_DATA* canteen = get_obj_carry( ch, arg );
    if ( !canteen )
    {
        ch_println( ch, "&RYou're not carrying that drink container." );
        return;
    }
    else if ( canteen->item_type != ITEM_DRINK_CON )
    {
        ch_println( ch, "&RThat's not a drink container." );
        return;
    }
    else if ( canteen->value[1] != 0 )
    {
        ch_println( ch, "&RThat drink container isn't empty." );
        return;
    }

    OBJ_DATA* cookware = get_obj_carried_of_type( ch, ITEM_COOKWARE );
    if ( !cookware )
    {
        ch_println( ch, "&RYou need some cookware to prepare the ingredients in." );
        return;
    }

    OBJ_DATA *ingr1 = NULL, *ingr2 = NULL, *ingr3 = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !ingr3 && obj->item_type == ITEM_DRINK_INGREDIENT )
        {
            if ( !ingr1 )
                ingr1 = obj;
            else if ( !ingr2 && ingr1 != obj )
                ingr2 = obj;
            else if ( !ingr3 && ingr1 != obj && ingr2 != obj )
                ingr3 = obj;
            else
                continue;
        }
    }

    if ( !ingr1 )
    {
        ch_println( ch, "&RYou need at least one drink ingredient to make drinks." );
        return;
    }

    if ( calc_effortrate( ch, LEADERSHIP_ABILITY, EFFORT_DRINK ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, makedrink_complete, makedrink_abort, FUNC );
    SET_STRING( timer->buffer->str1, arg2 );
    add_obj_to_buffer( timer->buffer, "cookware", cookware );
    add_obj_to_buffer( timer->buffer, "canteen", canteen );
    add_consumable_to_buffer( timer->buffer, "ingr1", ingr1, "First Ingredient" );
    if ( ingr2 ) add_consumable_to_buffer( timer->buffer, "ingr2", ingr2, "Second Ingredient" );
    if ( ingr3 ) add_consumable_to_buffer( timer->buffer, "ingr3", ingr3, "Third Ingredient" );

    ch_println( ch, "&GYou begin the process of making a drink." );
    ch_println( ch, "&wYour finished product will look like: %s", arg2 );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n begins making a drink.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is making a drink.", NULL, 0 );
}

