int makeshield_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    OBJ_DATA* crystal = get_obj_from_buffer( buffer, "crystal" );

    char buf[MSL];
    int crystalmod = 0, circuitmod = 0, supermod = 0, battmod = 0;
    double charge;

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makeshield", &skill_makeshield ) ) );

    charge = UMIN( 600, battery->value[0] ); //Fixed to use V0 which is battery charge instead of V1
    battmod = battery->value[1]; //Battery's quality modifier
    supermod = super->value[0]; //Superconductor's quality modifier
    circuitmod = circuit->value[0]; //Circuit's quality modifier
    crystalmod = crystal->value[0]; //Crystal's quality modifier

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_SHIELD ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makeshield", &skill_makeshield ) ) );
    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou hold up your new energy shield and press the switch hoping for the best." );
        ch_println( ch, "&RInstead of a field of energy being created, smoke starts pouring from the device." );
        ch_println( ch, "&RYou drop the hot device and watch as it melts away on the floor." );
        learn_from_failure( ch, cache_skill( "makeshield", &skill_makeshield ) );
        return E_LOTJ_SUCCESS;
    }

    if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) == 100 )
    {
        ch_println( ch, "Your skill in Equipment lets you make a better shield." );
        level += 100;
    }

    charge *= ( 1 + ( battmod + supermod + circuitmod ) / 100. ); //Increase charge by component modifiers' percentage
    charge += 2 * ( level + crystalmod ); //Increase charge from level and crystal modifier
    OBJ_DATA* obj = create_object( pObjIndex, level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    obj->item_type = ITEM_SHIELD;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    xSET_BIT( obj->wear_flags, ITEM_WEAR_SHIELD );
    obj->level = level;
    obj->weight = 2;
    strlcpy( buf, stripclr( arg ), MSL );
    strlcat( buf, " energy shield", MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MSL );
    SET_STRING( obj->description, buf );
    obj->value[0] = ( int ) level / 5;  /* condition */
    obj->value[1] = ( int ) level / 5;  /* armor */
    obj->value[2] = 0;                  /* charging counter, 0 = ready */
    obj->value[3] = 0;                  /* on/off state, 0=off, 1=on */
    obj->value[4] = ( int ) charge;     /* Current charge */
    obj->value[5] = ( int ) charge;     /* maximum charge */
    obj->cost = obj->value[2] * 10;
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created energy shield.&w" );
    act( AT_PLAIN, "$n finishes making $s new energy shield.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 50, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makeshield", &skill_makeshield ) );
    return E_LOTJ_SUCCESS;
}

