    OBJ_DATA* gel = get_obj_carried_of_type( ch, ITEM_SILICONGEL );
    if ( !gel )
    {
        ch_println( ch, "&RYou'll need some silicon gel to complete the circuit." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_CIRCUIT ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, makecircuit_complete, makecircuit_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "gel", gel, "Gel" );

    ch_println( ch, "&GYou begin the complex process of making a circuit board." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and begins to construct a circuit.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is assembling a circuit board.", NULL, 0 );

    // Set as nonconsumed, we turn this into the circuit
    add_obj_to_buffer( timer->buffer, "circuit", circuit );
}

/*
