*/
int repairarmor_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are interrupted and fail to finish your work." );
    return E_LOTJ_SUCCESS;
}

int repairarmor_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* armor = get_obj_from_buffer( buffer, "armor" );

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_REPAIRA ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "repairarmor", &skill_repairarmor ) ) ) ;
    if ( number_percent( ) > ( chance * 1.5 ) )
    {
        ch_println( ch, "&RYou botch your repair job. Going to have to try again..." );
        learn_from_failure( ch, cache_skill( "repairarmor", &skill_repairarmor ) );
        return E_LOTJ_SUCCESS;
    }

    /* Repair the damage to the armor */
    if ( armor->item_type == ITEM_ARMOR )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            armor->value[0] = MAX_ARMOR_CONDITION;
        else
            armor->value[0] = UMAX( MAX_ARMOR_CONDITION, armor->pIndexData ? armor->pIndexData->value[0] : 0 );
        ch_println( ch, "&GYou finish your work and hold up the fully repaired armor.&w" );
        act( AT_PLAIN, "$n finishes repairing a piece of armor.", ch, NULL, NULL, TO_ROOM );
    }
    else if ( armor->item_type == ITEM_CONTAINER )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            armor->value[3] = MAX_CONTAINER_CONDITION;
        else
            armor->value[3] = UMAX( MAX_CONTAINER_CONDITION, armor->pIndexData ? armor->pIndexData->value[3] : 0 );
        ch_println( ch, "&GYou finish your work and hold up the fully repaired container.&w" );
        act( AT_PLAIN, "$n finishes repairing a container.", ch, NULL, NULL, TO_ROOM );
    }
    else if ( armor->item_type == ITEM_HOLSTER )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            armor->value[3] = MAX_HOLSTER_CONDITION;
        else
            armor->value[3] = UMAX( MAX_HOLSTER_CONDITION, armor->pIndexData ? armor->pIndexData->value[3] : 0 );
        ch_println( ch, "&GYou finish your work and hold up the fully repaired holster.&w" );
        act( AT_PLAIN, "$n finishes repairing a holster.", ch, NULL, NULL, TO_ROOM );
    }
    else if ( armor->item_type == ITEM_SHIELD ) //Add a section for shields when finished repairing.
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            armor->value[0] = UMAX( MAX_ARMOR_CONDITION, armor->value[1] );
        else
            armor->value[0] = UMAX( MAX_ARMOR_CONDITION, armor->pIndexData ? armor->pIndexData->value[0] : 0 );
        ch_println( ch, "&GYou finish your work and hold up the fully repaired shield.&w" );
        act( AT_PLAIN, "$n finishes repairing a shield.", ch, NULL, NULL, TO_ROOM );
    }

    learn_from_success( ch, cache_skill( "repairarmor", &skill_repairarmor ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_repairarmor( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CRepairarmor <&witem&C>&w" );
        ch_println( ch, "&zRequires: &CNeedle and Thread&w" );
        return;
    }

    OBJ_DATA* armor = get_obj_carry( ch, argument );
    if ( !armor )
    {
        ch_println( ch, "&RYou don't have that item!" );
        return;
    }

    if ( armor->item_type != ITEM_ARMOR && armor->item_type != ITEM_CONTAINER && armor->item_type != ITEM_SHIELD && armor->item_type != ITEM_HOLSTER )
    {
        ch_println( ch, "&RThats not a piece of armor!" );
        return;
    }

    int damage = 0;
    if ( armor->item_type == ITEM_ARMOR )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            damage = MAX_ARMOR_CONDITION - armor->value[0];
        else
            damage = UMAX( MAX_ARMOR_CONDITION, armor->pIndexData ? armor->pIndexData->value[0] : 0 ) - armor->value[0];
    }

    if ( armor->item_type == ITEM_SHIELD )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            damage = UMAX( MAX_ARMOR_CONDITION, armor->value[1] ) - armor->value[0];
        else
            damage = UMAX( MAX_ARMOR_CONDITION, armor->pIndexData ? armor->pIndexData->value[0] : 0 ) - armor->value[0];
    }

    if ( armor->item_type == ITEM_CONTAINER )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            damage = MAX_CONTAINER_CONDITION - armor->value[3];
        else
            damage = UMAX( MAX_CONTAINER_CONDITION, armor->pIndexData ? armor->pIndexData->value[3] : 0 ) - armor->value[3];
    }

    if ( armor->item_type == ITEM_HOLSTER )
    {
        if ( xIS_SET( armor->extra_flags, ITEM_CRAFTED ) )
            damage = MAX_HOLSTER_CONDITION - armor->value[3];
        else
            damage = UMAX( MAX_HOLSTER_CONDITION, armor->pIndexData ? armor->pIndexData->value[3] : 0 ) - armor->value[3];
    }

    if ( damage <= 0 )
    {
        ch_println( ch, "&RIt doesn't look very damaged at all!" );
        return;
    }

    OBJ_DATA* sewingkit = get_obj_carried_of_type( ch, ITEM_SEWING_KIT );
    if ( !sewingkit && armor->item_type != ITEM_SHIELD ) //Containers/Armor need sewing kit. Shields don't.
    {
        ch_println( ch, "&RYou need a needle and some thread." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit && armor->item_type == ITEM_SHIELD )
    {
        ch_println( ch, "&RYou need a toolkit to repair the shield with." );
        return;
    }

    damage *= 2;
    damage = URANGE( 4, damage, 12 );

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_REPAIRA ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    ch_println( ch, "&GYou set to work repairing %s.", armor->short_descr );
    if ( armor->item_type == ITEM_ARMOR )
    {
        act( AT_PLAIN, "$n takes $s sewing kit and sets to work repairing some armor.", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, "is repairing some armor.", NULL, 0 );
    }
    else if ( armor->item_type == ITEM_CONTAINER )
    {
        act( AT_PLAIN, "$n takes $s sewing kit and sets to work repairing an item.", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, "is repairing a container.", NULL, 0 );
    }
    else if ( armor->item_type == ITEM_SHIELD )
    {
        act( AT_PLAIN, "$n sets to work repairing a shield.", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, "is repairing a shield.", NULL, 0 );
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, damage*3, repairarmor_complete, repairarmor_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "armor", armor );
    if ( sewingkit )
        add_obj_to_buffer( timer->buffer, "sewingkit", sewingkit );
    if ( toolkit )
        add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
}

