int makegoggles_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are interrupted and fail to finish your work." );
    return E_LOTJ_SUCCESS;
}

int makegoggles_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    char buf[MIL];
    OBJ_DATA* lens = get_obj_from_buffer( buffer, "lens" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* duraplast = get_obj_from_buffer( buffer, "duraplast" );

    int duramod = 0;
    double value = 0;
    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_GOGGLES );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    value += lens->pIndexData->cost;
    value += circuit->pIndexData->cost;
    value += battery->pIndexData->cost;
    duramod = duraplast->value[0]; //Duraplast's quality modifier
    value += duraplast->pIndexData->cost;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_GOGGLES ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makegoggles", &skill_makegoggles ) ) );
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou hold up your newly created infra-red goggles..." );
        ch_println( ch, "&R...and they fall apart in your hands." );
        learn_from_failure( ch, cache_skill( "makegoggles", &skill_makegoggles ) );
        return E_LOTJ_SUCCESS;
    }

    OBJ_DATA* obj = create_object( pObjIndex, ch->top_level );
    set_crafted( ch, obj );
    strlcpy( buf, stripclr( arg ), MIL );
    strlcat( buf, " infrared goggles", MIL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MIL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MIL );
    SET_STRING( obj->description, buf );
    obj->value[0] = ( int ) ( 12 * ( 1 + duramod / 100. ) ); //Duraplast's quality modifier affects durability?
    obj->value[1] = 10;
    obj->cost = calc_markup( ch, ( int ) value );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created goggles.&w" );
    act( AT_PLAIN, "$n finishes crafting some infra-red goggles.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 12, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makegoggles", &skill_makegoggles ) );
    return E_LOTJ_SUCCESS;
}

