}

int enhancearmor_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* armor = get_obj_from_buffer( buffer, "armor" );
    OBJ_DATA* enhancement = get_obj_from_buffer( buffer, "enhancement" );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "enhancearmor", &skill_enhancearmor ) ) );
    if ( number_percent( ) > chance )
    {        
        ch_println( ch, "&RYou hold up the enhanced armor only to find that you failed." );
        learn_from_failure( ch, cache_skill( "enhancearmor", &skill_enhancearmor ) );
        return E_LOTJ_SUCCESS;
    }

    if ( enhancement->item_type == ITEM_CHEMICAL )
    {
        switch ( enhancement->value[4] )
        {
            case 131:
                add_affect_to_obj( armor, APPLY_RESISTANT, RIS_SLASH );
                break;

            case 66:
                add_affect_to_obj( armor, APPLY_RESISTANT, RIS_ENERGY );
                break;

            case 23:
                add_affect_to_obj( armor, APPLY_RESISTANT, RIS_PIERCE );
                break;
        }

        if ( get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) != 100 )
        {
            switch ( enhancement->value[4] )
            {
                case 131:
                case 66:
                    add_affect_to_obj( armor, APPLY_SUSCEPTIBLE, RIS_PIERCE );
                    break;

                case 23:
                    add_affect_to_obj( armor, APPLY_SUSCEPTIBLE, RIS_SLASH );
                    break;
            }
        }
        else
            ch_println( ch, "Due to your skill in enhancement your coating is perfect." );

        switch ( armor->value[2] )
        {
            case 1:
                armor->value[2] = 5;
                break;

            case 2:
                armor->value[2] = 8;
                break;

            case 3:
                armor->value[2] = 11;
                break;

            case 4:
                armor->value[2] =  6;
                break;

            case 7:
                armor->value[2] =  9;
                break;

            case 10:
                armor->value[2] = 12;
                break;
        }

        extract_obj( enhancement );
        ch_println( ch, "You finish adding your coating to the armor." );
        act( AT_ACTION, "$n finishes adding a coating to $s armor.", ch, NULL, NULL, TO_ROOM );
        learn_from_success( ch, cache_skill( "enhancearmor", &skill_enhancearmor ) );
        return E_LOTJ_SUCCESS;
    }

    if ( enhancement->item_type == ITEM_UNDERLAY )
    {
        switch ( enhancement->value[4] )
        {
            case 1:
                if ( get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_HIT, number_range( 150, 300 ) );
                else
                {
                    ch_println( ch, "Your skill in medical improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_HIT, number_range( 300, 450 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 250 : 0) );
                }

                break;

            case 2:
                if ( get_learned_pct( ch, cache_skill( "chemistry", &skill_chemistry ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_CON, 1 );
                else
                {
                    ch_println( ch, "Your skill in chemistry improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_CON, number_range( 1, 2 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 1 : 0) );
                }

                break;

            case 3:
                if ( get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_DEX, 1 );
                else
                {
                    ch_println( ch, "Your skill in enhancement improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_DEX, number_range( 1, 2 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 1 : 0) );
                }

                break;

            case 4:
                if ( get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_STR, 1 );
                else
                {
                    ch_println( ch, "Your skill in destruction improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_STR, number_range( 1, 2 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 1 : 0) );
                }

                break;

            case 5:
                if ( get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_CHA, 1 );
                else
                {
                    ch_println( ch, "Your skill in medical improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_CHA, number_range( 1, 2 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 1 : 0) );
                }

                break;

            case 6:
                if ( get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) != 100 )
                    add_affect_to_obj( armor, APPLY_MOVE, 150 );
                else
                {
                    ch_println( ch, "Your skill in enhancement improves the quality of your work." );
                    add_affect_to_obj( armor, APPLY_MOVE, number_range( 150, 300 ) + (has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 100 : 0) );
                }

                break;
        }

        if ( ( enhancement->value[4] == 6 && get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) == 100 ) ||
                ( enhancement->value[4] == 5 && get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) == 100 ) ||
                ( enhancement->value[4] == 4 && get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) == 100 ) ||
                ( enhancement->value[4] == 3 && get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) == 100 ) ||
                ( enhancement->value[4] == 2 && get_learned_pct( ch, cache_skill( "chemistry", &skill_chemistry ) ) == 100 ) )
        {
            int bonus = has_feat( ch, cache_skill( "armor crafting", &skill_armor_crafting ) ) ? 300 : 100;
            add_affect_to_obj( armor, APPLY_HIT, bonus );
            ch_println( ch, "&GYour mastery of medical, destruction, enhancement and chemistry gives your armor a bonus of %d hp.", bonus );
        }

        switch ( armor->value[2] )
        {
            case 1:
                armor->value[2] = 4;
                break;

            case 5:
                armor->value[2] = 6;
                break;

            case 2:
                armor->value[2] = 7;
                break;

            case 8:
                armor->value[2] = 9;
                break;

            case 3:
                armor->value[2] = 10;
                break;

            case 11:
                armor->value[2] = 12;
                break;
        }

        extract_obj( enhancement );
        ch_println( ch, "You finish adding your underlay to the armor." );
        act( AT_ACTION, "$n finishes adding an underlay to $s armor.", ch, NULL, NULL, TO_ROOM );
        learn_from_success( ch, cache_skill( "enhancearmor", &skill_enhancearmor ) );
        return E_LOTJ_SUCCESS;
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_enhancearmor( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char* arg2 = one_argument( argument, arg );

    if ( NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Cenhancearmor <&witem&C> <&wunderlay&z/&Ccoating&C>&w" );
        ch_println( ch, "&zRequires: &CNeedle and thread, an armor coating or underlay.&w" );
        return;
    }

    OBJ_DATA* armor = get_obj_carry( ch, arg );
    if ( !armor )
    {
        ch_println( ch, "&RYou don't have that item!" );
        return;
    }

    if ( armor->item_type != ITEM_ARMOR )
    {
        ch_println( ch, "&RThats not a piece of armor!" );
        return;
    }

    if ( !xIS_SET( armor->wear_flags, ITEM_WEAR_ABOUT ) && !xIS_SET( armor->wear_flags, ITEM_WEAR_HEAD ) )
    {
        ch_println( ch, "Hey, you can't do that, that'd be cheating!" );
        return;
    }

    OBJ_DATA* enhancement = get_obj_carry( ch, arg2 );
    if ( !enhancement )
    {
        ch_println( ch, "You don't have an item like that." );
        return;
    }

    if ( enhancement->item_type != ITEM_CHEMICAL && enhancement->item_type != ITEM_UNDERLAY )
    {
        ch_println( ch, "That's not the right kind of item." );
        return;
    }

    if ( enhancement->item_type == ITEM_CHEMICAL )
    {
        if ( get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) <= 49 )
        {
            ch_println( ch, "You cannot add coatings to armor until you hit 50%% or greater in enhancement." );
            return;
        }

        switch ( enhancement->value[4] )
        {
            default:
                ch_println( ch, "That's not a proper chemical!" );
                return;

            case 131:
            case 66:
            case 23:
                break;
        }

        switch ( armor->value[2] )
        {
            default:
                break;

            case 5:
            case 6:
            case 8:
            case 9:
            case 11:
            case 12:
                ch_println( ch, "This armor already has a coating!" );
                return;
        }
    }

    if ( enhancement->item_type == ITEM_UNDERLAY )
    {
        switch ( enhancement->value[4] )
        {
            default:
                ch_println( ch, "That's not a proper underlay!" );
                return;

            case 1:
            case 5:
                if ( get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) <= 49 )
                {
                    ch_println( ch, "You need more percentage in medical to use that underlay." );
                    return;
                }

                break;

            case 2:
                if ( get_learned_pct( ch, cache_skill( "chemistry", &skill_chemistry ) ) <= 49 )
                {
                    ch_println( ch, "You need more percentage in chemistry to use that underlay." );
                    return;
                }

                break;

            case 3:
            case 6:
                if ( get_learned_pct( ch, cache_skill( "enhancement", &skill_enhancement ) ) <= 49 )
                {
                    ch_println( ch, "You need more percentage in enhancement to use that underlay." );
                    return;
                }

                break;

            case 4:
                if ( get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) <= 49 )
                {
                    ch_println( ch, "You need more percentage in destruction to use that underlay." );
                    return;
                }

                break;
        }

        switch ( armor->value[2] )
        {
            default:
                break;

            case 4:
            case 6:
            case 7:
            case 9:
            case 10:
            case 12:
                ch_println( ch, "This armor already has an underlay!" );
                return;
        }
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 90, enhancearmor_complete, enhancearmor_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "armor", armor );
    add_consumable_to_buffer( timer->buffer, "enhancement", enhancement, "Enhancement" );

    ch_println( ch, "You start enhancing %s.", armor->short_descr );
    print_buffer_objects( timer->buffer, ch );
    action_set( ch, NULL, "is working on a piece of armor.", NULL, 0 );
    act( AT_ACTION, "$n begins working on some enhancements to some armor.", ch, NULL, NULL, TO_ROOM );
}

