int makedatapad_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* duraplast = get_obj_from_buffer( buffer, "duraplast" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    char buf[MSL];
    int battmod = 0, duramod = 0;
    double value = 0, power = 0;

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_DATAPAD );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    value += super->pIndexData->cost;
    value += circuit->pIndexData->cost;

    power = battery->value[0];
    battmod = battery->value[1]; //Battery's quality modifier
    value += battery->pIndexData->cost;

    duramod = duraplast->value[0]; //Duraplast's quality modifier
    value += duraplast->pIndexData->cost;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_DATAPAD ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makedatapad", &skill_makedatapad ) ) ) ;
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou hold up your newly created datapad..." );
        ch_println( ch, "&R...It explodes into a ball of fire!" );
        learn_from_failure( ch, cache_skill( "makedatapad", &skill_makedatapad ) );
        return E_LOTJ_SUCCESS;
    }

    value *= 1 + ( duramod / 100. ); //Adjust cost by duraplast quality modifier
    power *= 1 + ( battmod / 100. ); //Adjust charge by battery quality modifier
    OBJ_DATA* obj = create_object( pObjIndex, ch->top_level );
    set_crafted( ch, obj );
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    xSET_BIT( obj->wear_flags, ITEM_HOLD );
    strlcpy( buf, stripclr( arg ), MSL );
    strlcat( buf, " datapad", MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MSL );
    SET_STRING( obj->description, buf );
    obj->cost = calc_markup( ch, ( int ) value );
    obj->value[0] = 0;
    obj->value[3] = ( int ) power;
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created datapad.&w" );
    act( AT_PLAIN, "$n finishes crafting a datapad.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 12, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makedatapad", &skill_makedatapad ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makedatapad( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakedatapad <&wname&C>&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make a datapad." );
        return;
    }

    OBJ_DATA* oven = get_obj_carried_of_type( ch, ITEM_OVEN );
    if ( !oven )
    {
        ch_println( ch, "&RYou need an oven to heat and shape the material." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a battery to power the datapad." );
        return;
    }

    OBJ_DATA* super = get_obj_carried_of_type( ch, ITEM_SUPERCONDUCTOR );
    if ( !super )
    {
        ch_println( ch, "&RYou need a superconductor to regulate the current." );
        return;
    }

    OBJ_DATA* duraplast = get_obj_carried_of_type( ch, ITEM_DURAPLAST );
    if ( !duraplast )
    {
        ch_println( ch, "&RYou need some duraplast for the datapad shell." );
        return;
    }

    OBJ_DATA* circuit = get_obj_carried_of_type( ch, ITEM_CIRCUIT );
    if ( !circuit )
    {
        ch_println( ch, "&RYou need a circuit for the datapad processor." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_DATAPAD ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 60, makedatapad_complete, makedatapad_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "oven", oven );
    add_consumable_to_buffer( timer->buffer, "duraplast", duraplast, "Duraplast" );
    add_consumable_to_buffer( timer->buffer, "battery", battery, "Battery" );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "super", super, "Superconductor" );

    ch_println( ch, "&GYou begin the long process of making a datapad." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and begins to piece something together.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is constructing a datapad.", NULL, 0 );
}

