CMDF do_call( CHAR_DATA* ch, char* argument )
{
    PHOME_DATA* home;
    char buf[MSL], arg[MIL];
    CLAN_DATA* clan = NULL;
    OBJ_DATA* obj = NULL;
    SHIP_DATA* ship = NULL;
    bool got_com = FALSE;
    int cost = 0, abil = 0, cnt = 0;
    const RACE_DATA* mobrace = NULL;
    const SKINCOLOR_DATA* skincolor = NULL;
    CALL_DATA* called = NULL;

    if ( IS_NPC( ch ) )
        return;

    if ( xIS_SET( ch->in_room->flags, ROOM_NOCALL ) || get_ship_from_room( ch->in_room ) != NULL || is_disrupted( ch, TAP_COMM, true )  )
    {
        ch_println( ch, "&RYou cannot call for assistance here!" );
        return;
    }

    if ( ( called = ch->called ) != NULL )
    {
        if ( called->type == MOB_TEMP_CUSTOM )
        {
            if ( called->mob )
                snprintf( buf, MSL, "Your &C%s&z is on its", called->mob->short_descr );
            else
            {
                DISPOSE( ch->called );
                ch->called = NULL;
                ch_println( ch, "&RYour previous call for assistance has been cancelled. Please try again." );
                bug( "%s: %s called invalid custom mob", FUNC, !IS_NPC( ch ) ? ch->name : ch->short_descr );
                return;
            }
        }
        else
        {
            if ( called->type == MOB_TEMP_THUG )
                strlcpy( buf, "Your &CThug&z is on its", MSL );

            if ( called->type == MOB_TEMP_DIPLOMAT )
                strlcpy( buf, "Your &CDiplomat&z is on its", MSL );

            if ( called->type == MOB_TEMP_MESSAGEDRONE )
                strlcpy( buf, "Your &CMessage Drone&z is on its", MSL );

            if ( called->type == MOB_TEMP_SOLDIER )
                strlcpy( buf, "Your &CSoldier&z is on its", MSL );

            if ( called->type == MOB_TEMP_REINFORCEMENTS )
                strlcpy( buf, "Your &CReinforcements&z are on their", MSL );

            if ( called->type == MOB_TEMP_GUARD )
                strlcpy( buf, "Your &CGuard&z is on its", MSL );

            if ( called->type == MOB_TEMP_ROYALGUARD )
                strlcpy( buf, "Your &CRoyal Guards&z are on their", MSL );

            if ( called->type == MOB_TEMP_DROIDEKA )
                strlcpy( buf, "Your &CDroideka&z is on its", MSL );
        }

        ch_println( ch, "\n&z%s way in &C%d &zround(s).", buf, called->wait_time );
        return;
    }

    for ( obj = ch->last_carrying; obj; obj = obj->prev_content )
        if ( obj->item_type == ITEM_COMLINK )
            got_com = TRUE;

    if ( !got_com )
    {
        ch_println( ch, "You need to get a comlink first." );
        return;
    }

    if ( ch->pcdata->clan )
        clan = ch->pcdata->clan;

