/*
    GEMCUTTING <new name>
*/
int gemcutting_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are interrupted and fail to finish your work." );
    return E_LOTJ_SUCCESS;
}

int gemcutting_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* ore = get_obj_from_buffer( buffer, "ore" );

    char buf[MSL];
    int oremod = 0;
    double quality = 0;

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "gemcutting", &skill_gemcutting ) ) );

    oremod = ore->value[0]; //Ore's quality modifier
    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_GEMCUT ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "gemcutting", &skill_gemcutting ) ) );
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou finish cutting away one last facet from the ore." );
        ch_println( ch, "&RAfter examining it, you notice it is somewhat dull and useless." );
        learn_from_failure( ch, cache_skill( "gemcutting", &skill_gemcutting ) );
        extract_obj( ore );
        return E_LOTJ_SUCCESS;
    }

    //Bonuses to base damage from science values
    if ( get_learned_pct( ch, cache_skill( "minerals", &skill_minerals ) ) == 100 )
    {
        ch_println( ch, "Your skill in Minerals lets you cut a better crystal." );
        level += 50;
    }

    quality = ( level + oremod ) / 20.; //Set crystal's quality modifier based on engineering level, gemcutting skill, and mineral skill
    ore->item_type = ITEM_CRYSTAL;
    ore->weight = URANGE( 1, ore->weight - 1, 6 );
    strlcpy( buf, arg, MSL );
    strlcat( buf, " crystal", MSL );
    SET_STRING( ore->name, stripclr( buf ) );
    strlcpy( buf, arg, MSL );
    SET_STRING( ore->short_descr, buf );
    strlcat( buf, " was left here.", MSL );
    SET_STRING( ore->description, buf );
    ore->cost = URANGE( 25, ore->cost * 2, 5000 );
    ore->value[0] = ( int ) quality;
    obj_to_char( ore, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly cut gem.&w" );
    act( AT_PLAIN, "$n finishes cutting a gem.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( ore->cost * 200, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "gemcutting", &skill_gemcutting ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_gemcutting( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CGemcutting <&wnew crystal name&C>&w" );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to cut gems." );
        return;
    }

    OBJ_DATA* ore = get_obj_carried_of_type( ch, ITEM_CRYSTALORE );
    if ( !ore )
    {
        ch_println( ch, "&RYou need some crystal ore to cut a gem out of." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_GEMCUT ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, gemcutting_complete, gemcutting_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "ore", ore, "Crystal Ore" );

    ch_println( ch, "&GYou begin the long process of cutting and shaping a crystal." );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and a piece of ore and begins to work.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is cutting some ore.", NULL, 0 );

    add_obj_to_buffer( timer->buffer, "ore", ore ); // Set as nonconsumable after output
}

extern const char* gcha_score[];
extern const char* gstr_score[];
void add_reinforcements( CHAR_DATA* ch )
{
    char              buf[MSL];
    MOB_INDEX_DATA*   pMobIndex;
    MPROG_DATA*       mprog;
    OBJ_DATA*         obj;
    OBJ_INDEX_DATA*   pObjIndex;
    CALL_DATA* called = NULL;
    char nbuf[MSL];
    char rbuf[MSL];
    char tbuf[MSL];

    if ( ( called = ch->called ) == NULL )
        return;

    // New logic for custom call vnums, which don't need any of the following special mob generation logic.
    if ( called->type == MOB_TEMP_CUSTOM )
    {
        pMobIndex = called->mob;

        if ( !pMobIndex )
        {
            bug( "%s: %s called invalid custom mob.", FUNC, !IS_NPC( ch ) ? ch->name : ch->short_descr );
            return;
        }

        CHAR_DATA* mob = create_mobile( pMobIndex );
        char_to_room( mob, ch->in_room );
        ch_println( ch, "&wYour %s &whas arrived.", mob->short_descr );

        add_follower( mob, ch, false );
        xSET_BIT( mob->act, ACT_CALLED ); // So that we save properly.
        lua_trigger_on_ch_spawned( mob );
        DISPOSE( ch->called );
        ch->called = NULL;
        return;
    }

    if ( ( pMobIndex = get_mob_index( MOB_VNUM_TEMPLATE ) ) == NULL )
        return;

    int mobcha;
    int mobstr;

    if ( !called->race )
    {
        bug( "%s: %s calling mob type %d with invalid race.", FUNC, !IS_NPC( ch ) ? ch->name : ch->short_descr, called->type );
        DISPOSE( ch->called );
        ch->called = NULL;
        return;
    }

    if ( !called->skincolor )
        called->skincolor = random_race_skincolor( called->race );

    mobcha = number_range( 0, 5 );
    mobstr = number_range( 0, 5 );
    snprintf( rbuf, MSL, "%s, %s ", gstr_score[mobcha], gcha_score[mobstr] );

    if ( xIS_SET( called->race->specflags, RSPECFLAG_WHILL ) )
        strlcat( rbuf, "Green skinned Whill", MSL );

    if ( ( xIS_SET( called->race->flags, RFLAG_MALFUR ) && ( ch->sex == SEX_MALE || ch->sex == SEX_NEUTRAL ) ) || ( xIS_SET( called->race->flags, RFLAG_FEMFUR ) && ch->sex == SEX_FEMALE ) )
        snprintf( rbuf + strlen( rbuf ), MSL - strlen( rbuf ), "%s furred ", called->skincolor->display_name );
    else
        snprintf( rbuf + strlen( rbuf ), MSL - strlen( rbuf ), "%s skinned ", called->skincolor->display_name );

    if ( is_human( called->race ) )
        strlcat( rbuf, "Human", MSL );

    if ( !is_human( called->race) )
        strlcat( rbuf, called->race->race_name, MSL );

    strlcpy( rbuf, aoran_cap( rbuf ), MSL );

    if ( called->type == MOB_TEMP_REINFORCEMENTS )
    {
        CHAR_DATA* mob[2];
        int         mob_cnt;
        snprintf( tbuf, MSL, "A %s Soldier", called->race->race_name );
        strlcat( rbuf, " soldier is on patrol.\n", MSL );
        ch_println( ch, "Your reinforcements have arrived.\n" );

        for ( mob_cnt = 0 ; mob_cnt < 2 ; mob_cnt++ )
