CMDF do_torture( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    int chance, dam;
    bool fail;
    one_argument( argument, arg );

    if ( !IS_NPC( ch )
            &&  get_learned_pct( ch, cache_skill( "torture", &skill_torture ) ) <= 0  )
    {
        ch_println( ch, "Your mind races as you realize you have no idea how to do that." );
        return;
    }

    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't do that right now." );
        return;
    }

    if ( ch->held )
    {
        ch_println( ch, "You would, except you're restrained. What are you thinking?" );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't get close enough while mounted." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Torture whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "Torturing yourself won't accomplish much." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "Now that's heartless...torturing a mob." );
        return;
    }

    if ( !IS_AWAKE( victim ) )
    {
        ch_println( ch, "You need to wake them first." );
        return;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is AFK." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( victim->fighting )
    {
        ch_println( ch, "You can't torture someone who is in combat." );
        return;
    }

    if ( victim->max_hit <= 200 )
    {
        ch_println( ch, "Torture would have no further effect." );
        return;
    }

    if ( !ch->pcdata->clan )
    {
        ch_println( ch, "Torture is a tool for clans only." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_COMMSHIELD ) && ( !ch->in_room->area->planet->governed_by || ch->in_room->area->planet->governed_by != ch->pcdata->clan || ch->in_room->area->planet->jailroom != ch->in_room->vnum ) )
    {
        ch_println( ch, "You have to be on a planet your clan controls, in the planetary jail room." );
        return;
    }

    ch->alignment = URANGE( -1000, ch->alignment - 50, 1000 );
    WAIT_STATE( ch, cache_skill( "torture", &skill_torture )->beats );
    fail = FALSE;
    chance = ris_save( victim, ch->skill_level[COMBAT_ABILITY], RIS_PARALYSIS );

    if ( chance == 1000 )
        fail = TRUE;
    else
        fail = saves_para_petri( chance, victim );

    if ( !fail && (  IS_NPC( ch ) || ( number_percent( ) + chance ) < get_learned_pct( ch, cache_skill( "torture", &skill_torture ) ) ) )
    {
        learn_from_success( ch, cache_skill( "torture", &skill_torture ) );
        WAIT_STATE( ch,     7 * PULSE_VIOLENCE );
        WAIT_STATE( victim, 7 * PULSE_VIOLENCE );
        act( AT_BLOOD, "$N slowly tortures you. The pain is excruciating.", victim, NULL, ch, TO_CHAR );
        act( AT_ACTION, "Please read HELP TORTURE for rules on torturing.", ch, NULL, NULL, TO_CHAR );
        act( AT_BLOOD, "You torture $N.", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "You are being tortured. You may lose STR/DEX/CON/CHA or HP permanently.", victim, NULL, NULL, TO_CHAR );
        act( AT_BLOOD, "$n tortures $N.", ch, NULL, victim, TO_NOTVICT );
        dam = dice( ch->skill_level[COMBAT_ABILITY] / 10, 4 );
        dam = URANGE( 0, dam, victim->max_hit - 200 );
        victim->max_hit -= dam;
        worsen_mental_state( victim, 5 );
        ch_printf( victim, "You lose %d permanent hit points.", dam );
        ch_printf( ch, "%s loses %d permanent hit points.", g_name( victim, ch ), dam );

        if ( get_curr_str( victim ) > 8 && number_range( 1, 3 ) == 3 )
        {
            victim->mod_str -= 1;
            ch_println( victim, "&R-1 STR!" );
        }
        else if ( get_curr_dex( victim ) > 8 && number_range( 1, 3 ) == 3 )
        {
            victim->mod_dex -= 1;
            ch_println( victim, "&R-1 DEX!" );
        }
        else if ( get_curr_con( victim ) > 8 && number_range( 1, 4 ) == 4 )
        {
            victim->mod_con -= 1;
            ch_println( victim, "&R-1 CON!" );
        }
        else if ( get_curr_cha( victim ) > 8 && number_range( 1, 4 ) == 4 )
        {
            victim->mod_cha -= 1;
            ch_println( victim, "&R-1 CHA!" );
        }
        else
            act( AT_ACTION, "It would appear only health will be taken from $N now.", ch, NULL, victim, TO_CHAR );
    }
    else
    {
        act( AT_SKILL, "$N tortures you, but it doesn't do much.", victim, NULL, ch, TO_CHAR );
        act( AT_SKILL, "You torture $N, but $E doesn't seem too hurt by it.", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n tortures $N, but $N doesn't flinch.", ch, NULL, victim, TO_NOTVICT );
        learn_from_failure( ch, cache_skill( "torture", &skill_torture ) );
        WAIT_STATE( ch,     PULSE_VIOLENCE );
        WAIT_STATE( victim, PULSE_VIOLENCE );
        worsen_mental_state( victim, 1 );
        /* WAIT_STATE( ch,     2 * PULSE_VIOLENCE ); */
        /* global_retcode = multi_hit( victim, ch, TYPE_UNDEFINED ); */
    }

    do_save( victim, "-noalert" );
    return;
}

extern const char* gstr_score[];
extern const char* gcha_score[];
extern const char* gfcha_score[];

int find_str( char* strname )
{
    int x = 0;

    for ( x = 0; x <= 6; x++ )
        if ( !str_cmp( gstr_score[x], strname ) )
            return x;

    return -1;
}
int find_cha( char* strname, int gender )
{
    int x = 0;

    if ( gender < 2 )
    {
        for ( x = 0; x <= 6; x++ )
            if ( !str_cmp( gcha_score[x], strname ) )
                return x;
    }
    else
    {
        for ( x = 0; x <= 6; x++ )
            if ( !str_cmp( gfcha_score[x], strname ) )
                return x;
    }

    return -1;
}

int id_from_disguise( DISGUISE_DATA* disguise )
{
    if ( !disguise )
        return 0;

    return disguise->id;
}

int disguise_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop applying the disguise." );
    act( AT_ACTION, "$n stops applying $s disguise.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int disguise_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    DISGUISE_DATA* disguise = ( DISGUISE_DATA* )buffer->buf1;
    if ( !disguise )
    {
        ch_println( ch, "Your disguise has disappeared!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chc = IS_NPC( ch ) ? ch->top_level : ( int )get_learned_pct( ch, cache_skill( "disguise", &skill_disguise ) );
    if ( number_percent() >= chc )
    {
        ch_println( ch, "&wYou somehow fail horribly in your attempt to finalize the disguise." );
        act( AT_ACTION, "&w$n's disguise attempt fails!", ch, NULL, NULL, TO_ROOM );
        OBJ_DATA* tobj = create_object( get_obj_index( OBJ_VNUM_BLANK ), 1 );
        SET_STRING( tobj->name, "disguise" );
        SET_STRING( tobj->short_descr, "A disguise" );
        SET_STRING( tobj->description, "A disguise" );
        xCLEAR_BITS( tobj->wear_flags );
        obj_to_char( tobj, ch );
        separate_obj( tobj );
        tobj = make_scraps( tobj );
        learn_from_failure( ch, cache_skill( "disguise", &skill_disguise ) );
        return E_LOTJ_SUCCESS;
    }

    ch->disguise = disguise;
    ch_println( ch, "&wYou finish applying the disguise..." );
    act( AT_ACTION, "&w$n finishes applying a disguise.", ch, NULL, NULL, TO_ROOM );
    learn_from_success( ch, cache_skill( "disguise", &skill_disguise ) );
    do_save( ch, "-noalert" );
    return E_LOTJ_SUCCESS;
}

CMDF do_disguise( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    int maxslots = ch->perm_wis / 5; //Maximum number of disguise slots possible by anyone is 5.
    if ( has_feat( ch, cache_skill( "masquerader", &skill_masquerader ) ) )
        maxslots *= 2;

    int usedslots = 0;
    for ( DISGUISE_DATA* disguise = ch->first_disguise; disguise; disguise = disguise->next )
        usedslots++;

    char arg[MIL], arg2[MIL], arg3[MIL], arg4[MIL];
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( NULLSTR( arg ) )
    {
        if ( ch->disguise )
        {
            ch_println( ch, "&z(&CC&z)urrent disguise&w:"
                        "&z-------------------------\n"
                        "&wName: &Y%s\n"
                        "&wTitle: &w%s\n"
                        "&wRace&w:  &C%-28s  &wSkincolor&w: &G%s\n"
                        "&wSTR&w:   &G%-28d  &wCHA&w:       &Y%d\n"
                        "&wDisguise State&w: &GActive\n"
                        "&z-------------------------\n"
                        "&zUsage&w: &Cdisguise list&w\n"
                        "       &Cdisguise apply <&wdisguise ID&C>&w\n"
                        "       &Cdisguise create&w\n"
                        "       &Cdisguise edit <&wdisguise ID&C> <&wattribute&C> <&wvalue&C>&w\n"
                        "       &Cdisguise save <&wdisguise ID&C> &wNote: This locks a disguise's settings&w\n"
                        "&wUse '&Cdisguise remove&w' to remove your disguise.\n"
                        , ch->disguise->disgname, ch->disguise->title, ch->disguise->race->race_name, get_skincolor( ch->disguise->skincolor ), ch->disguise->str, ch->disguise->cha );
        }
        else
        {
            ch_println( ch, "&z(&CC&z)urrent disguise&w:"
                        "&z-------------------------\n"
                        "&zDisguise State: &wNo disguise applied\n"
                        "&z-------------------------\n"
                        "&zUsage&w: &Cdisguise list\n&w"
                        "       &Cdisguise apply <&wdisguise ID&C>&w\n"
                        "       &Cdisguise create&w\n"
                        "       &Cdisguise edit &C<&wdisguise ID&C> <&wattribute&C> <&wvalue&C>&w\n"
                        "       &Cdisguise save <&wdisguise ID&C> &wNote: This locks a disguise's settings&w\n"
                        "&wUse '&Cdisguise remove&w' to remove your disguise.\n" );
        }

        return;
    }

    if ( !str_cmp( arg, "remove" ) )
    {
        if ( !ch->disguise )
        {
            ch_println( ch, "You don't have any sort of disguise on." );
            return;
        }

        ch->disguise = NULL;
        ch_println( ch, "You remove your disguise!" );
        act( AT_ACTION, "$n removes $s disguise!", ch, NULL, NULL, TO_ROOM );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        int i = 0, j = 0;
        char race_str[MIL];
        send_to_char( "&wList of Disguises&w:\n"
                        "&z-------------------------\n", ch );

        for ( DISGUISE_DATA* disguise = ch->first_disguise; disguise; disguise = disguise->next )
        {
            if ( disguise->archived )
                j++;

            strlcpy( race_str, "", MIL );
            snprintf( race_str, MIL, "%s", disguise->race->race_name );
            if ( is_droid( disguise->race ) )
                snprintf( race_str + strlen(race_str), MIL - strlen(race_str), " &z(&C%s&z)", get_droidmodel( disguise->droidmodel ) );
            ch_println( ch, "&wID:    &C%-28d  &wName:  &C%s&w\n"
                        "&wTitle: &w%s\n"
                        "&wRace&w:  &C%-28s  &wSkincolor&w: &G%s\n"
                        "&wSTR&w:   &G%-28d  &wCHA&w:       &Y%d\n"
                        "&wDisguise State&w: &W%s\n"
                        "&z-------------------------\n",
                        ++i, disguise->disgname,
                        disguise->title,
                        race_str, get_skincolor( disguise->skincolor ),
                        disguise->str, disguise->cha,
                        disguise->archived ? "&OArchived" : ( disguise->saved ? "&GSaved&w" : "&RNot saved&w" ) );
        }

        ch_println( ch, "&wYou have &C%d&w unused disguise slots left.&w", ( maxslots - i + j ) );
        return;
    }

    if ( !str_cmp( arg, "create" ) )
    {
        int i = 0;

        for ( DISGUISE_DATA* disguise = ch->first_disguise; disguise; disguise = disguise->next )
            if ( !disguise->archived )
                i++;

        if ( i == maxslots )
        {
            ch_println( ch, "&RAll %d of your disguise slots have been used.&w", maxslots );
            return;
        }

        DISGUISE_DATA* disguise;
        CREATE( disguise, DISGUISE_DATA, 1 );
        SET_STRING( disguise->disgname, "Unset" );
        SET_STRING( disguise->description, "" );
        SET_STRING( disguise->title, "Unset" );
        SET_STRING( disguise->pubtitle, "" );
        disguise->race = ch->race;
        disguise->str = ch->perm_str;
        disguise->cha = ch->perm_cha;
        disguise->skincolor = ch->skincolor;
        disguise->droidmodel = ch->droidmodel;
        disguise->id = ch->last_disguise ? ch->last_disguise->id + 1 : 1;
        disguise->saved = FALSE;
        ch_println( ch, "&wNew disguise slot created. Use &CDISGUISE EDIT <&wslot&C> <&wattribute&C> <&wvalue&C>&w to edit it." );
        LINK( disguise, ch->first_disguise, ch->last_disguise, next, prev );
        save_char_obj( ch, true );
        return;
    }

    if ( !str_cmp( arg, "save" ) )
    {
        if ( NULLSTR( arg2 ) || !is_number( arg2 ) )
        {
            ch_println( ch, "Which disguise do you want to save?" );
            do_disguise( ch, "list" );
            return;
        }

        int v = atoi( arg2 );
        if ( v < 0 || v > usedslots )
        {
            ch_println( ch, "&wThat is not a valid disguise choice: arg was %d, usedslots = %d", v, usedslots );
            return;
        }

        int i = 0;
        DISGUISE_DATA* disguise;
        for ( disguise = ch->first_disguise; disguise; disguise = disguise->next )
            if ( ++i == v )
                break;

        if ( !disguise )
        {
            ch_println( ch, "Unable to find that disguise. Type 'disguise list' to see your list of disguises." );
            return;
        }

        if ( disguise->archived )
        {
            ch_println( ch, "That disguise has been archived by staff and can no longer be used." );
            return;
        }

        if ( disguise->saved )
        {
            ch_println( ch, "That disguise has already been saved and is ready to apply." );
            return;
        }
        else
        {
            if ( !str_cmp( disguise->disgname, "Unset" ) )
            {
                ch_println( ch, "You need to set a name first." );
                return;
            }

            if ( !str_cmp( disguise->title, "Unset" ) )
            {
                ch_println( ch, "You should set a title first." );
                return;
            }

            if ( !xIS_SET( disguise->race->skincolors, disguise->skincolor ) )
            {
                ch_println( ch, "That disguise's skincolor is invalid for its race." );
                ch_println( ch, "Please set a valid skincolor before saving it." );
                return;
            }

            disguise->saved = TRUE;
            save_char_obj( ch, true );
            ch_println( ch, "&wDisguise saved." );
            return;
        }
    }
    else if ( !str_cmp( arg, "edit" ) )
    {
        if ( NULLSTR( arg2 ) || !is_number( arg2 ) )
        {
            ch_println( ch, "Which disguise do you want to edit?" );
            do_disguise( ch, "list" );
            return;
        }

        int v = atoi( arg2 );
        if ( v < 0 || v > usedslots )
        {
            ch_println( ch, "&wThat is not a valid disguise choice." );
            return;
        }

        DISGUISE_DATA* disguise;
        int i = 0;
        for ( disguise = ch->first_disguise; disguise; disguise = disguise->next ) 
            if ( ++i == v )
                break;

        if ( !disguise )
        {
            ch_println( ch, "That is not a valid disguise choice." );
            return;
        }

        if ( disguise->archived )
        {
            ch_println( ch, "That disguise has been archived by staff and can no longer be used." );
            return;
        }

        if ( disguise->saved )
        {
            ch_println( ch, "That disguise has already been saved and cannot be edited." );
            return;
        }

        if ( NULLSTR( arg3 ) )
        {
            ch_printf( ch, "Possible attributes to edit: str, cha, skincolor, name, race, %sand title.", is_droid( disguise->race ) ? "model, " : "" );
            return;
        }

        if ( !str_cmp( arg3, "str" ) )
        {
            argument = one_argument( argument, arg4 );
            if ( NULLSTR( arg4 ) || !is_number( arg4 ) || atoi( arg4 ) < 3 || atoi( arg4 ) > 25 )
            {
                ch_println( ch, "Valid range for strength is 3-25." );
                return;
            }

            ch_println( ch, "The disguise's strength has been adjusted." );
            disguise->str = atoi( arg4 );
            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "cha" ) )
        {
            argument = one_argument( argument, arg4 );
            if ( NULLSTR( arg4 ) || !is_number( arg4 ) || atoi( arg4 ) < 3 || atoi( arg4 ) > 25 )
            {
                ch_println( ch, "Valid range for charisma is 3-25." );
                return;
            }

            ch_println( ch, "The disguise's charisma has been adjusted." );
            disguise->cha = atoi( arg4 );
            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "skincolor" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "Set which skin color?" );
                do_showskincolor( ch, disguise->race->race_name );
                return;
            }

            const SKINCOLOR_DATA* skincolor = skincolor_by_name( argument );

            if ( !skincolor || !xIS_SET( disguise->race->skincolors, skincolor->id ) )
            {
                ch_println( ch, "Invalid selection. Valid skin colors are:" );
                do_showskincolor( ch, disguise->race->race_name );
                return;
            }

            ch_println( ch, "The disguise's skincolor has been adjusted." );
            disguise->skincolor = skincolor->id;
            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "model" ) )
        {
            if ( !is_droid( disguise->race ) )
            {
                ch_println( ch, "You can only pick a droid model if you're disguising as a droid." );
                return;
            }

            DROID_MODEL_DATA* model = NULL;
            int model_num = 0;
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "You can choose from the following droid models:" );
                for ( model = first_droid_model; model; model = model->next )
                {
                    if ( model->enabled && xIS_SET( disguise->race->droidmodels, model->id ) )
                    {
                        model_num++;
                        ch_println( ch, "&z(&C%3d&z) &C%s", model_num, model->name );
                    }
                }

                return;
            }

            if ( is_number( argument ) )
            {
                for ( model = first_droid_model; model; model = model->next )
                {
                    if ( model->enabled && xIS_SET( disguise->race->droidmodels, model->id ) )
                    {
                        model_num++;
                        if ( model_num == atoi( argument ) )
                            break;
                    }
                }       
            }

            if ( !model )
                model = droid_model_by_name( argument );

            if ( !model || !xIS_SET( disguise->race->droidmodels, model->id ) )
            {
                model_num = 0;
                ch_println( ch, "Invalid selection. Valid droid models are:" );
                for ( model = first_droid_model; model; model = model->next )
                {
                    if ( model->enabled && xIS_SET( disguise->race->droidmodels, model->id ) )
                    {
                        model_num++;
                        ch_println( ch, "&z(&C%3d&z) &C%s", model_num, model->name );
                    }
                }

                return;
            }

            ch_println( ch, "The disguise's droid model has been adjusted." );
            disguise->droidmodel = model->id;
            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "name" ) )
        {
            argument = one_argument( argument, arg4 );

            if ( NULLSTR( arg4 ) )
            {
                ch_println( ch, "You have not input a name." );
                return;
            }

            if ( !check_parse_name( arg4, is_droid( disguise->race ) ) )
            {
                ch_println( ch, "Invalid name entry." );
                return;
            }

            if ( !str_cmp( arg4, ch->name ) )
            {
                ch_println( ch, "You can't name a disguise after yourself!" );
                return;
            }

            if ( is_reserved_name( arg4 ) || player_exist( arg4 ) || player_existed( arg4 ) )
            {
                ch_println( ch, "Invalid name. Please choose another." );
                return;
            }

            snprintf( buf, MSL, "Disguise name for %s", ch->name );
            if ( str_cmp( disguise->disgname, "Unset" ) )
            {
                RESERVE_DATA* res = get_reserved( disguise->disgname );
                if ( res && !str_cmp( res->reason, buf ) )
                    remove_reserved( res );
            }

            SET_STRING( disguise->title, "Unset" );
            SET_STRING( disguise->pubtitle, "" );
            SET_STRING( disguise->disgname, arg4 );
            add_reserved( arg4, buf );
            ch_println( ch, "Disguise name has been updated. Reset the disguise's title to fit the new name." );
            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "race" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "Possible races:" );
                RACE_DATA *race = NULL;
                for ( race = first_race; race; race = race->next )
                {
                    if ( xIS_SET( race->flags, RFLAG_NODISGUISE ) && str_cmp(race->race_name, ch->race->race_name ) )
                        continue;

                    if ( xIS_SET( race->flags, RFLAG_HIDEMORTS ) || !str_cmp( race->race_name, "unused" ) )
                        continue;

                    if ( race->size != ch->race->size )
                        continue;

                    if ( race->era && race->era != sysdata.era )
                        continue;

                    ch_println( ch, "%-14s%s", race->race_name, ++v % 5 ? "  " : "" );
                }

                if ( v % 5 )
                    ch_println( ch, "" );

                ch_println( ch, "&zSyntax: &Cdisguise edit <&wdisguise slot&C> race <&wrace name&C>" );
                return;
            }
            RACE_DATA *race = NULL;
            race = get_race_by_name( argument );

            if ( race == NULL  || ( xIS_SET( race->flags, RFLAG_NODISGUISE ) && str_cmp( race->race_name, ch->race->race_name ) ) || xIS_SET( race->flags, RFLAG_HIDEMORTS ) || !str_cmp( race->race_name, "unused" ) || race->size != ch->race->size )
            {
                ch_println( ch, "&zThat isn't a valid race!" );
                return;
            }

            disguise->race = race;
            ch_println( ch, "&zDisguise's race has been updated." );

            if ( !xIS_SET( race->skincolors, disguise->skincolor ) )
                ch_println( ch, "&zThe disguise's current skincolor is invalid for the new race. Please set a new one before saving it." );

            save_char_obj( ch, true );
            return;
        }
        else if ( !str_cmp( arg3, "title" ) )
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "Change your disguise's title to what?" );
                return;
            }

            if ( checkclr( argument, "x" ) )
            {
                ch_println( ch, "&RYou cannot use the BLACK Color token in your title." );
                return;
            }

            if ( nifty_is_name( "^", argument ) )
            {
                ch_println( ch, "&RYou cannot use the background/blinking tokens in your title." );
                return;
            }

            if ( strlen( stripclr( argument ) ) < 1 )
            {
                ch_println( ch, "&RTry including something OTHER than color tokens." );
                return;
            }

            if ( !strstr( stripclr( strip_apost( argument ) ), disguise->disgname ) )
            {
                ch_println( ch, "You must include your disguised name somewhere in your title!" );
                return;
            }

            if ( strstr( argument, ")" ) || strstr( argument, "(" ) )
            {
                ch_println( ch, "You cannot have ( or ) in your title!" );
                return;
            }

            smash_tilde( argument );

            if ( isalpha( argument[0] ) || isdigit( argument[0] ) )
            {
                buf[0] = ' ';
                strlcpy( buf + 1, argument, MSL - 1 );
            }
            else
                strlcpy( buf, argument, MSL );

            SET_STRING( disguise->title, buf );
            save_char_obj( ch, TRUE );
            ch_println( ch, "Disguise title has been set." );
            return;
        }
        else
        {
            do_disguise( ch, "" );
            return;
        }
    }
    else if ( !str_cmp( arg, "apply" ) )
    {
        if ( NULLSTR( arg2 ) || !is_number( arg2 ) )
        {
            ch_println( ch, "Which disguise do you want to apply?" );
            do_disguise( ch, "list" );
            return;
        }

        int v = atoi( arg2 );
        if ( v < 0 || v > usedslots )
        {
            ch_println( ch, "&wThat is not a valid disguise choice: arg was %d, usedslots = %d", v, usedslots );
            return;
        }

        DISGUISE_DATA* disguise;
        int i = 0;
        for ( disguise = ch->first_disguise; disguise; disguise = disguise->next )
            if ( ++i == v )
                break;

        if ( !disguise )
        {
            ch_println( ch, "Unable to find that disguise. Type 'disguise list' to see your list of disguises." );
            return;
        }

        if ( disguise->archived )
        {
            ch_println( ch, "That disguise has been archived by staff and can no longer be used." );
            return;
        }

        if ( !disguise->saved )
        {
            ch_println( ch, "&zThat disguise has not been saved. Use &Cdisguise save <&wdisguise ID&C>" );
	    ch_println( ch, "&RWarning: &zOnce a disguise has been saved, it cannot be edited." );
            return;
        }

        OBJ_DATA* putty = get_obj_carried_of_type( ch, ITEM_PUTTY );
        if ( !putty )
        {
            ch_println( ch, "You need putty to apply a disguise!" );
            return;
        }

        ch_println( ch, "You begin applying your disguise." );
        act( AT_ACTION, "$n begins applying a disguise...", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, "is applying a disguise.", NULL, 0 );

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, disguise_complete, disguise_abort, FUNC );
        add_consumable_to_buffer( timer->buffer, "putty", putty, "Putty" );
        timer->buffer->buf1 = disguise;
        return;
    }
    else
    {
        do_disguise( ch, "" );
        return;
    }
}

// Sets victim_ptr to the target, if any is found.
// If the target is found but invalid, returns false, indicating no further attempts should be made.
// If the target is simply not found, returns true.
bool get_snipe_target( CHAR_DATA* ch, char* target_name, sh_int dir, sh_int max_dist, CHAR_DATA** victim_ptr )
{
    ROOM_INDEX_DATA* to_room;
    ROOM_INDEX_DATA* was_in_room = ch->in_room;
    CHAR_DATA* victim = NULL;

    EXIT_DATA* pexit = get_exit( ch->in_room, dir );
    if ( !pexit )
    {
        ch_println( ch, "Are you expecting to fire through a wall!?" );
        return false;
    }

    for ( int dist = 1; dist <= max_dist; dist++ )  // dist = 1 instead of dist = 0, since 0 counts as 1. - Veska
    {
        if ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) )
            break;

        if ( !pexit->to_room )
            break;

        to_room = NULL;

        if ( pexit->distance > 1 )
            to_room = generate_exit( ch->in_room, &pexit );

        if ( to_room == NULL )
            to_room = pexit->to_room;

        char_from_room( ch );
        char_to_room( ch, to_room );

        if ( IS_NPC( ch ) && ( victim = get_char_room_mp( ch, target_name ) ) != NULL )
            break;

        if ( !IS_NPC( ch ) && ( victim = get_char_room( ch, target_name ) ) != NULL )
            break;

        if ( ( pexit = get_exit( ch->in_room, dir ) ) == NULL )
            break;
    }

    char_from_room( ch );
    char_to_room( ch, was_in_room );

    if ( !victim )
        return true;

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is AFK." );
        return false;
    }

    if ( !pk_allow && !IS_NPC( victim ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, no PKing right now." );
        return false;
    }

    if ( !IS_NPC( victim ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return false;
    }

    if ( victim == ch )
    {
        ch_println( ch, "Shoot yourself...really?" );
        return false;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is AFK." );
        return false;
    }

    if ( is_safe( ch, victim ) )
        return false;

    if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == victim )
    {
        act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
        return false;
    }

    if ( IS_NPC( victim ) && victim->hit < victim->max_hit && IS_AWAKE( victim ) )
    {
        act( AT_PLAIN, "$N is hurt and suspicious... you can't seem to find a good shot.",
             ch, NULL, victim, TO_CHAR );
        return false;
    }

    if ( get_timer( victim, TIMER_SNIPED ) > 0 && IS_AWAKE( victim ) )
    {
        act( AT_PLAIN, "$N is unusually wary... you can't seem to find a good shot.",
             ch, NULL, victim, TO_CHAR );
        return false;
    }

    if ( victim->fighting )
    {
        act( AT_PLAIN, "$N is in the middle of a fight and moving far too quickly to snipe at!",
             ch, NULL, victim, TO_CHAR );
        return false;
    }

    *victim_ptr = victim;
    return true;
}

int snipe_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou stop lining up your shot.&w" );
    return E_LOTJ_SUCCESS;
}

int snipe_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* wield = get_obj_from_buffer( buffer, "weapon" );
    int dir = buffer->num1;
    char* targetname = buffer->str1;
    char buf[MSL];
    SKILL_DATA* skill = cache_skill( "snipe", &skill_snipe );
    if ( !skill )
    {
        bug( "%s: could not find skill", FUNC );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    sh_int max_dist = 1;
    if ( wield->value[3] == WEAPON_BLASTER && xIS_SET( wield->extra_flags, ITEM_NODUAL ) )
        max_dist = IS_NPC(ch) ? 2 : URANGE( 1, get_learned_pct( ch, skill ) / 20, 5 );

    bool is_bowcaster = wield->value[3] == WEAPON_BOWCASTER;

    CHAR_DATA* victim = NULL;
    if ( !get_snipe_target( ch, targetname, dir, max_dist, &victim ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    // We didn't find the target so we'll refresh the timer before they try to fire again.
    if ( !victim )
    {
        if ( number_range( 1, 10 ) == 1 )
            ch_println( ch, "&wYou continue looking for your target..." );
        // Refresh the timer, no need to add things back to the buffer.
        add_timer( ch, TIMER_DO_FUN, has_feat( ch, cache_skill( "deadeye", &skill_deadeye ) ) ? 1 : 3, snipe_complete, snipe_abort, "do_snipe" );
        return E_LOTJ_SUCCESS;
    }

    act( AT_ACTION, "$n spots a target and fires a shot.", ch, NULL, NULL, TO_ROOM );
    ch_println( ch, "&wYou spot your target and fire!" );
    ROOM_INDEX_DATA* was_in_room = ch->in_room;
    char_to_room( ch, victim->in_room );

    int chance = IS_NPC( ch ) ? 100 : ( int ) ( get_learned_pct( ch, skill ) );
    if ( number_percent() <= chance )
    {
        // A forcer with foresight will sometimes be able to autodraw in advance of an incoming snipe to reflect it.
        if ( !IS_NPC( victim ) &&
                !has_pcflag( victim, PCFLAG_NO_SENSE ) &&
                victim->pcdata &&
                get_learned_pct( victim, cache_skill( "foresight", &skill_foresight ) ) > 0 &&
                has_pcflag( victim, PCFLAG_AUTODRAW ) &&
                can_unholster( victim, get_eq_char( victim, WEAR_WAIST ), true ) )
        {
            // 25%-75% chance to succeed based on foresight skill
            if ( number_percent() < 25 + get_learned_pct( victim, cache_skill( "foresight", &skill_foresight ) ) / 2 )
            {
                act( AT_MAGIC, "Your senses tingle as the Force warns you of a threat, and you instinctively reach for your weapon.", ch, NULL, victim, TO_VICT );
                act( AT_ACTION, "With no warning, $N suddenly reaches for $S weapon.", ch, NULL, victim, TO_NOTVICT );
                interpret( victim, "draw", FALSE );
            }
        }

        snprintf( buf, MSL, "A %s shot fires at you from the %s.", is_bowcaster ? "bowcaster" : "blaster", dir_name[rev_dir[dir]] );
        act( AT_ACTION, buf, victim, NULL, ch, TO_CHAR );
        act( AT_ACTION, "You fire at $N.", ch, NULL, victim, TO_CHAR );
        snprintf( buf, MSL, "A %s shot fires at $N from the %s.", is_bowcaster ? "bowcaster" : "blaster", dir_name[rev_dir[dir]] );
        act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );

        int orig_hp = victim->hit;
        if ( one_hit( ch, victim, skill->id ) != rVICT_DIED )
        {
            if ( victim->hit < orig_hp )
                add_timer( victim, TIMER_SNIPED, 15, NULL, NULL, FUNC );
        }

        if ( char_extracted( ch ) )
            return E_LOTJ_SUCCESS;
        stop_fighting( ch, TRUE );
        learn_from_success( ch, skill );
    }
    else
    {
        act( AT_ACTION, "You fire at $N but don't even come close.", ch, NULL, victim, TO_CHAR );
        snprintf( buf, MSL, "A %s shot fired from the %s barely misses you.", is_bowcaster ? "bowcaster" : "blaster", dir_name[rev_dir[dir]] );
        act( AT_ACTION, buf, ch, NULL, victim, TO_ROOM );
        learn_from_failure( ch, skill );
    }

    char_from_room( ch );
    char_to_room( ch, was_in_room );

    if ( !IS_NPC( ch ) )
        WAIT_STATE( ch, 3 * PULSE_PER_SECOND );

    if ( !char_extracted( victim ) && IS_NPC( victim ) )
    {
        if ( xIS_SET( victim->act, ACT_SENTINEL ) )
        {
            victim->was_sentinel = victim->in_room;
            xREMOVE_BIT( victim->act, ACT_SENTINEL );
        }

        start_hating( victim, ch );
        start_hunting( victim, ch );
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_snipe( CHAR_DATA* ch, char* argument )
{
    char dirname[MIL];
    char* targetname = one_argument( argument, dirname );
    int dir = get_door( dirname );
    if ( dir == -1 || NULLSTR( targetname ) )
    {
        ch_println( ch, "&zSyntax: &Csnipe <&wdirection&C> <&wtarget&C>&w" );
        return;
    }

    EXIT_DATA* pexit = get_exit( ch->in_room, dir );
    if ( !pexit )
    {
        ch_println( ch, "Are you expecting to fire through a wall!?" );
        return;
    }

    if ( xIS_SET( pexit->flags, EX_WINDOW ) && ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) ) )
    {
        ch_println( ch, "Are you expecting to fire through a closed window!?" );
        return;
    }

    if ( xIS_SET( pexit->flags, EX_CLOSED ) )
    {
        ch_println( ch, "Are you expecting to fire through a door!?" );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
        ch_println( ch, "&RYou are in a safezone. Make sure you are familiar with the rules stated in &Yhelp safezone&R and are sure you are not breaking them..." );

    OBJ_DATA* wield = NULL;
    if ( ( wield = get_eq_char( ch, WEAR_WIELD ) ) == NULL || wield->item_type != ITEM_WEAPON ||
            ( wield->value[3] != WEAPON_BLASTER && wield->value[3] != WEAPON_BOWCASTER ) || xIS_SET( wield->extra_flags, ITEM_REPEATER ) )
    {
        if ( ( wield = get_eq_char( ch, WEAR_DUAL_WIELD ) ) == NULL || wield->item_type != ITEM_WEAPON ||
                wield->value[3] != WEAPON_BLASTER || xIS_SET( wield->extra_flags, ITEM_REPEATER ) )
        {
            ch_println( ch, "You don't seem to be holding a ranged weapon." );
            return;
        }
    }

    if ( ( wield->blaster_setting != BLASTER_FULL ) && wield->value[3] == WEAPON_BLASTER && xIS_SET( wield->extra_flags, ITEM_NODUAL ) )
    {
        ch_println( ch, "You can't snipe effectively unless your blaster is set to full!" );
        return;
    }

    if ( ( wield->value[4] != wield->value[5] ) && wield->value[3] == WEAPON_BLASTER && xIS_SET( wield->extra_flags, ITEM_NODUAL ) )
    {
        ch_println( ch, "You need a full cell to snipe with a rifle!" );
        return;
    }

    char buf[MSL];
    snprintf( buf, MSL, "$n faces %s and begins lining up a shot...", dir_name[dir] );
    act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
    snprintf( buf, MSL, "You look %s through your scope and begin searching for your target...", dir_name[dir] );
    act( AT_ACTION, buf, ch, NULL, NULL, TO_CHAR );
    snprintf( buf, MSL, "is facing %s and lining up a shot.", dir_name[dir] );
    action_set( ch, NULL, buf, NULL, 0 );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, has_feat( ch, cache_skill( "deadeye", &skill_deadeye ) ) ? 2 : 6, snipe_complete, snipe_abort, FUNC );
    timer->buffer->num1 = dir;
    SET_STRING( timer->buffer->str1, targetname );
    add_obj_to_buffer( timer->buffer, "weapon", wield );
}

/* syntax throw <obj> [direction] [target] */

CMDF do_throw( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA*         obj = NULL;
    OBJ_DATA*         tmpobj = NULL;
    char              arg[MIL];
    char              arg2[MIL];
    char              arg3[MIL];
    bool              was_wielding = FALSE;
    sh_int            dir = 0;
    SHIP_DATA*        ship = NULL;
    EXIT_DATA*        pexit = NULL;
    ROOM_INDEX_DATA* was_in_room = NULL;
    ROOM_INDEX_DATA* to_room = NULL;
    CHAR_DATA*        victim = NULL;
    SKILL_DATA* skill = cache_skill( "throw", &skill_throw );
    char              buf[MSL];
    bool              found = FALSE, fthrow = FALSE;
    int               freecast_chance = 20; //Used to determine if JEDI_CONSULAR subclass can cast a spell for no mana cost. - Gathorn 28Jan2017
    // Ralen Jan 14 - test commit on saber throw parry %
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );
    was_in_room = ch->in_room;

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zUsage:&C throw <&wobject&C> [&wdirection&C] [&wtarget&C]&w" );
        return;
    }

    obj = get_eq_char( ch, WEAR_HOLD );

    if ( !obj || !nifty_is_name( arg, obj->name ) )
        obj = get_eq_char( ch, WEAR_WIELD );

    if ( !obj || !nifty_is_name( arg, obj->name ) )
        obj = get_eq_char( ch, WEAR_DUAL_WIELD );

    if ( !obj || !nifty_is_name( arg, obj->name ) )
        if ( !obj || !nifty_is_name_prefix( arg, obj->name ) )
            obj = get_eq_char( ch, WEAR_HOLD );

    if ( !obj || !nifty_is_name_prefix( arg, obj->name ) )
        obj = get_eq_char( ch, WEAR_WIELD );

    if ( !obj || !nifty_is_name_prefix( arg, obj->name ) )
        obj = get_eq_char( ch, WEAR_DUAL_WIELD );

    if ( !obj || !nifty_is_name_prefix( arg, obj->name ) )
    {
        ch_println( ch, "You don't seem to be holding or wielding %s.", arg );
        return;
    }

    if ( obj == get_eq_char( ch, WEAR_WIELD ) )
        was_wielding = TRUE;

    if ( IS_OBJ_STAT( obj, ITEM_NOREMOVE ) )
    {
        act( AT_PLAIN, "You can't throw $p.", ch, obj, NULL, TO_CHAR );
        return;
    }

    if ( NULLSTR( arg2 ) )
    {
        snprintf( buf, MSL, "$n throws %s at the floor.", obj->short_descr );
        act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You throw %s at the floor.", obj->short_descr );
        to_room = ch->in_room;
        was_in_room = ch->in_room;
        victim = NULL;
    }
    else if ( !strcmp( arg2, "hatch" ) || !strcmp( arg2, "out" ) )
    {
        if ( ( ship = ship_from_entrance( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "You need to be in the hatchway of a ship to do that!" );
            return;
        }

        if ( ship->dockship != NULL && ship->dock_state == DOCK_DOCKED )
        {
            to_room = get_room_index( ship->dockship->dockroom );

            if ( !to_room )
                to_room = get_room_index( ship->dockship->entrance );

            if ( !to_room )
            {
                bug( "%s has no room to throw something through.", ship->dockship->name );
                ch_println( ch, "Hmm, that ship is pretty messed up. Better tell an Admin." );
                return;
            }

            found = TRUE;
        }

        // GRAL Weirdness with synch hatchopen and breached
        if ( ( !ship->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) ) && ( !found ) )
        {
            ch_println( ch, "You can't throw it through a closed hatch!" );
            return;
        }

        if ( !found )
            to_room = get_room_index( ship->location );

        if ( to_room == NULL )
        {
            ch_println( ch, "You might want to land somewhere first!" );
            return;
        }

        char_from_room( ch );
        char_to_room( ch, to_room );
        victim = get_char_room( ch, arg3 );

        if ( victim )
        {
            if ( !pk_allow && !IS_NPC( victim ) && !IS_IMMORTAL( ch ) )
            {
                ch_println( ch, "Sorry, no PKing right now." );
                return;
            }

            if ( ch == victim )
            {
                ch_println( ch, "How are you going to throw that at yourself?" );
                return;
            }

            if ( !IS_NPC( victim ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
            {
                ch_println( ch, "Sorry, this is a No PVP planet." );
                return;
            }

            if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
            {
                ch_println( ch, "That player is AFK." );
                return;
            }

            if ( is_safe( ch, victim ) )
                return;

            if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == victim )
            {
                act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
                return;
            }

            if ( is_safe( ch, victim ) )
                return;

            /* GRAL A forcer with a lightsaber should be able to deflect directed objects taking damage? */
            snprintf( buf, MSL, "Someone throws %s at you from the %s.", obj->short_descr, ship->name );
            act( AT_ACTION, buf, victim, NULL, ch, TO_CHAR );
            act( AT_ACTION, "You throw $p at $N.", ch, obj, victim, TO_CHAR );
            char_from_room( ch );
            char_to_room( ch, was_in_room );
            snprintf( buf, MSL, "$n throws %s to the %s.", obj->short_descr, dir_name[get_dir( arg2 )] );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
            char_from_room( ch );
            char_to_room( ch, to_room );
            snprintf( buf, MSL, "%s is thrown at $N from the %s.", obj->short_descr, ship->name );
            act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
        }
        else
        {
            ch_println( ch, "You throw %s out the hatchway.", obj->short_descr );
            char_from_room( ch );
            char_to_room( ch, was_in_room );
            snprintf( buf, MSL, "$n throws %s to the %s.", obj->short_descr, dir_name[get_dir( arg2 )] );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
            char_from_room( ch );
            char_to_room( ch, to_room );
            snprintf( buf, MSL, "%s is thrown from the %s.", obj->short_descr, ship->name );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
        }
    }
    else if ( !strcmp( arg2, "in" ) || !strcmp( arg2, "into" ) )
    {
        if ( ( ship = ship_in_room( ch->in_room, arg3 ) ) == NULL )
        {
            ch_println( ch, "You can't find that ship here at all!" );
            return;
        }

        // GRAL Weirdness with desynch hatchopen and breached
        if ( !ship->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            ch_println( ch, "You can't throw it through a closed hatch!" );
            return;
        }

        to_room = get_room_index( ship->entrance );

        if ( to_room == NULL )
        {
            ch_println( ch, "Something seems odd about the inside of that ship..." );
            return;
        }

        char_from_room( ch );
        char_to_room( ch, to_room );
        ch_println( ch, "You throw %s into %s.", obj->short_descr, ship->name );
        char_from_room( ch );
        char_to_room( ch, was_in_room );
        snprintf( buf, MSL, "$n throws %s into %s.", obj->short_descr, ship->name );
        act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
        char_from_room( ch );
        char_to_room( ch, to_room );
        snprintf( buf, MSL, "%s sails through the hatch and lands on the deck.", obj->short_descr );
        act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
        victim = NULL;
    }
    else  if ( ( dir = get_door( arg2 ) ) != -1 )
