            if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == victim )
            {
                act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
                return;
            }

            if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
            {
                ch_println( ch, "That player is AFK." );
                return;
            }

            if ( is_safe( ch, victim ) )
                return;

            to_room = NULL;

            if ( pexit->distance > 1 )
                to_room = generate_exit( ch->in_room, &pexit );

            if ( to_room == NULL )
                to_room = pexit->to_room;

            /* GRAL A forcer with a lightsaber should be able to deflect directed objects taking damage? */
            snprintf( buf, MSL, "Someone throws %s at you from the %s.", obj->short_descr, dir_name[dir] );
            act( AT_ACTION, buf, victim, NULL, ch, TO_CHAR );
            act( AT_ACTION, "You throw $p at $N.", ch, obj, victim, TO_CHAR );
            char_from_room( ch );
            char_to_room( ch, was_in_room );
            snprintf( buf, MSL, "$n throws %s to the %s.", obj->short_descr, dir_name[get_dir( arg2 )] );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
            char_from_room( ch );
            char_to_room( ch, to_room );
            snprintf( buf, MSL, "%s is thrown at $N from the %s.", obj->short_descr, dir_name[dir] );
            act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
        }
        else
        {
            if ( to_room == NULL )
                to_room = pexit->to_room;

            char_from_room( ch );
            char_to_room( ch, to_room );
            ch_println( ch, "You throw %s %s.", obj->short_descr, dir_name[get_dir( arg2 )] );
            char_from_room( ch );
            char_to_room( ch, was_in_room );
            snprintf( buf, MSL, "$n throws %s to the %s.", obj->short_descr, dir_name[get_dir( arg2 )] );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
            char_from_room( ch );
            char_to_room( ch, to_room );
            snprintf( buf, MSL, "%s is thrown from the %s.", obj->short_descr, dir_name[dir] );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
        }
    }
    else if ( ( victim = get_char_room( ch, arg2 ) ) != NULL )
    {
        if ( !pk_allow && !IS_NPC( victim ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "Sorry, no PKing right now." );
            return;
        }

        if ( ch == victim )
        {
            ch_println( ch, "How are you going to throw that at yourself?" );
            return;
        }

        if ( !IS_NPC( victim ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
        {
            ch_println( ch, "Sorry, this is a No PVP planet." );
            return;
        }

        if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
        {
            ch_println( ch, "That player is AFK." );
            return;
        }

        if ( is_safe( ch, victim ) )
            return;

        if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == victim )
        {
            act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
            return;
        }

        to_room = victim->in_room;
        was_in_room = ch->in_room;
    }
    else
    {
        ch_println( ch, "They don't seem to be here!" );
        return;
    }

    if ( obj == get_eq_char( ch, WEAR_WIELD )
            && ( tmpobj = get_eq_char( ch, WEAR_DUAL_WIELD ) ) != NULL )
        tmpobj->wear_loc = WEAR_WIELD;

    unequip_char( ch, obj );
    separate_obj( obj );
    obj_from_char( obj );
    obj = obj_to_room( obj, to_room );

    if ( ch->in_room != was_in_room )
    {
        char_from_room( ch );
        char_to_room( ch, was_in_room );
    }

    if ( !obj )
    {
        return;
    }

    if ( !victim || char_extracted( victim ) )
        learn_from_failure( ch, skill );
    else
    {
        WAIT_STATE( ch, skill->beats );

        if ( IS_NPC( ch ) || number_percent( ) <= get_learned_pct( ch, skill ) || check_parry( victim, ch, 0, obj ) || check_dodge( ch, victim ) )
        {
            int dam = 0;
            learn_from_success( ch, skill );
            act( AT_ACTION, "You throw $p at $N!", ch, obj, victim, TO_CHAR );
            act( AT_ACTION, "$n throws $p at you!", ch, obj, victim, TO_VICT );
            act( AT_ACTION, "$n throws $p at $N!", ch, obj, victim, TO_NOTVICT );
            dam = number_range( obj->value[3] == WEAPON_VIBRO_BLADE ? obj->value[2] : obj->weight * 3, ( obj->weight * 3 + ch->perm_str ) );

            SKILL_DATA* skill2 = cache_skill( "lightsaber throw", &skill_lightsaber_throw );
            if ( obj->item_type == ITEM_WEAPON && obj->value[3] == WEAPON_LIGHTSABER && was_wielding && !has_pcflag( ch, PCFLAG_NO_SENSE ) )
            {
                int mana_cost = 1000;
                if ( ( IS_CONSULAR( ch ) || IS_SORCERER( ch ) ) && ch->pcdata->frank >= FRANK_KNIGHT && number_percent () <= freecast_chance ) //JEDI_CONSULAR/SITH_SORCERER Knights and above have a 20% chance to cast a spell for free. Part of Jan 2017 subclass upgrade. - Gathorn 14Jan2017
                {
                    ch_println( ch, "&wYour mastery of the Force allows you to manipulate it with minimal effort." );
                    mana_cost = 0;
                }

                if ( number_percent( ) <= ( int )( get_learned_pct( ch, skill2 ) ) || IS_IMMORTAL( ch ) )
                {
                    if ( ch->mana < mana_cost )
                    {
                        ch_println( ch, "The force is not strong enough within you to guide the saber." );
                        dam = 0;
                    }
                    else
                    {
                        /* GRAL A forcer with a lightsaber should be able to deflect directed objects taking damage? */
                        dam += ( int )( ( ( obj->value[1] + obj->value[2] ) / 2 ) * 10 );
                        ch_println( ch, "You throw your saber, guiding it with the force!" );
                        act( AT_ACTION, "$n's lightsaber flies out in an arc.", ch, NULL, victim, TO_NOTVICT );
                        act( AT_ACTION, "$n throws $s lightsaber at you!", ch, NULL, victim, TO_VICT );
                        learn_slow( ch, skill2, 2 );
                        fthrow = TRUE;
                        ch->mana -= mana_cost;
                    }
                }
                else
                    learn_from_failure( ch, skill2 );
            }

            dam = dam > 900 ? 900 : dam; //Sintaka - New damage cap for throw damage at 900
            global_retcode = damage( ch, victim, dam, ( fthrow && skill2 ) ? skill2->id : TYPE_UNDEFINED );
        }
        else
        {
            learn_from_failure( ch, skill );
            global_retcode = damage( ch, victim, 0, TYPE_HIT );
        }

        if ( victim && IS_NPC( victim ) && !char_extracted( victim ) )
        {
            if ( xIS_SET( victim->act, ACT_SENTINEL ) )
            {
                victim->was_sentinel = victim->in_room;
                xREMOVE_BIT( victim->act, ACT_SENTINEL );
            }

            start_hating( victim, ch );
            start_hunting( victim, ch );
        }
    }

    if ( fthrow )
    {
        obj_from_room( obj );
        obj_to_char( obj, ch );
        act( AT_ACTION, "$n catches $s lightsaber as it sails towards $m.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "Your lightsaber flies back into your hand." );

        if ( get_eq_char( ch, WEAR_WIELD ) == NULL )
            equip_char( ch, obj, WEAR_WIELD );
    }

    if ( obj->item_type != ITEM_GRENADE && !fthrow )
        damage_obj ( obj );

    return;
}

CMDF do_beg( CHAR_DATA* ch, char* argument )
{
    /* GRAL why cant you do it resting or sitting - cedit issue not code */
    /*char buf  [MSL]; */
    char arg1 [MIL];
    CHAR_DATA* victim;
    int xp;
    int amount;

    if ( IS_NPC ( ch ) )
        return;

    argument = one_argument( argument, arg1 );

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Cbeg <&wvictim&C>" );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    if ( ( victim = get_char_room( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "That's pointless." );
        return;
    }

    if ( ch->position == POS_FIGHTING )
    {
        ch_println( ch, "Interesting combat technique." );
        return;
    }

    if ( victim->position == POS_FIGHTING )
    {
        ch_println( ch, "They're a little busy right now." );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "In your dreams or what?" );
        return;
    }

    if ( victim->position <= POS_SLEEPING )
    {
        ch_println( ch, "You might want to wake them first..." );
        return;
    }

    if ( IS_ANIMAL( victim ) ) // Gral and Asmo idea - implemented by Ravaus by request
    {
        ch_println( ch, "You aren't going to earn many credits off of the wildlife!" );
        return;
    }

    if ( !IS_NPC( victim ) )
    {
        ch_println( ch, "You beg them for money." );
        act( AT_ACTION, "$n begs you to give $m some change.\n", ch, NULL, victim, TO_VICT    );
        act( AT_ACTION, "$n begs $N for change.\n",  ch, NULL, victim, TO_NOTVICT );
        return;
    }

    if ( victim->vendor_data )
    {
        ch_println( ch, "Vendors aren't charitable." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    WAIT_STATE( ch, cache_skill( "beg", &skill_beg )->beats );

    // With 100% skill, 50% chance against level 100 mob, 100% chance against level 1 mob.
    if ( ( number_percent() + victim->top_level / 2 ) >= get_learned_pct( ch, cache_skill( "beg", &skill_beg ) ) )
    {
        /*
            Failure.
        */
        ch_println( ch, "You beg them for money but don't get any!" );
        act( AT_ACTION, "$n is really getting on your nerves with all this begging!\n", ch, NULL, victim, TO_VICT    );
        act( AT_ACTION, "$n begs $N for money.\n",  ch, NULL, victim, TO_NOTVICT );
        learn_from_failure( ch, cache_skill( "beg", &skill_beg ) );
        return;
    }

    act( AT_ACTION, "$n begs $N for money.\n",  ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "$n begs you for money!\n", ch, NULL, victim, TO_VICT    );
    //Moving this number_range out of URANGE. Using any sort of random function in URANGE can cause it to go outside boundaries. -Gathorn 15Jan2017
    amount = number_range( 100, get_curr_cha( ch ) * 1500 );
    amount = URANGE( 0, amount, victim->gold );

    if ( amount <= 0 )
    {
        do_look( victim, ch->name );
        do_say( victim, "Sorry, I have nothing to spare." );
        learn_from_failure( ch, cache_skill( "beg", &skill_beg ) );
        return;
    }

    ch->gold     += amount;
    victim->gold -= amount;
    sql_credits_log( ch->name, "do_beg", amount, TRUE );
    ch_println( ch, "%s gives you %d credits.", victim->short_descr, amount );
    learn_from_success( ch, cache_skill( "beg", &skill_beg ) );
    xp = UMIN( amount * 10, ( exp_level( ch->skill_level[SMUGGLING_ABILITY] + 1 ) - exp_level( ch->skill_level[SMUGGLING_ABILITY] )  )  );
    xp = UMIN( xp, xp_compute( ch, victim ) );
    xp = apply_xp_sink( ch, xp, SMUGGLING_ABILITY );
    gain_exp( ch, xp, SMUGGLING_ABILITY, TRUE );
    ch_println( ch, "&WYou gain %ld smuggling experience points!", xp );
    act( AT_ACTION, "$N gives $n some money.\n",  ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "You give $n some money.\n", ch, NULL, victim, TO_VICT    );
    return;
}

