CMDF do_hijack( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    int chance;
    SHIP_DATA* ship;
    char tmp[MSL];

    if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou must be in the cockpit of a ship to do that!" );
        return;
    }

    if ( ship->classtype > PLATFORM_SHIP )
    {
        ch_println( ch, "&RThis isn't a spacecraft!" );
        return;
    }

    if ( ( ship = get_ship_from_pilotseat( ch->in_room ) ) == NULL )
    {
        ch_println( ch, "&RYou don't seem to be in the pilot seat!" );
        return;
    }

    if ( check_pilot( ch, ship ) )
    {
        ch_println( ch, "&RYou can't hijack a ship you already have access to!" );
        return;
    }

    if ( ship->piloting != ch )
    {
        ch_println( ch, "&RYou need to be piloting the ship to hijack it." );
        return;
    }

    if  ( ship->classtype == PLATFORM_SHIP || ship->classtype == BATTLESTATION_SHIP )
    {
        ch_println( ch, "This ship is far too large to hijack." );
        return;
    }

    if ( ship->autopilot )
    {
        ch_println( ch, "&RThe ship's autopilot is on!" );
        return;
    }

    if ( ship->shipstate != SHIP_DOCKED )
    {
        ch_println( ch, "You need to be landed in order to hijack the ship." );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )  ( get_learned_pct( ch, cache_skill( "hijack", &skill_hijack ) ) );

    if ( number_percent( ) > chance - 30 )
    {
        ch_println( ch, "You fail to figure out the correct launch code." );
        learn_from_failure( ch, cache_skill( "hijack", &skill_hijack ) );
        return;
    }

    chance = IS_NPC( ch ) ? ch->top_level : ( int )  ( get_learned_pct( ch, find_gsn( ship->classtype ) ) );

    if ( number_percent( ) <= chance )
    {
        squadron_remove( ship, NULL );
        strlcpy( tmp, ship->pilot, MSL );
        SET_STRING( ship->pilot, ch->name );
        SET_STRING( ship->homeship, "" );
        do_launch( ch, "" );
        SET_STRING( ship->pilot, tmp );
        save_ship( ship, true );
        learn_from_success( ch, find_gsn( ship->classtype ) );
        learn_from_success( ch, cache_skill( "hijack", &skill_hijack ) );
        return;
    }

    set_char_color( AT_RED, ch );
    ch_println( ch, "You fail to work the controls properly!" );
    learn_from_failure( ch, find_gsn( ship->classtype ) );
    return;
}

CMDF do_jail ( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    CLAN_DATA*   clan = NULL;
    ROOM_INDEX_DATA* jail = NULL;
    PLANET_DATA* planet = on_planet( ch );

    if ( IS_NPC ( ch ) )
        return;

    if ( !planet )
    {
        ch_println( ch, "You're not even on a planet!" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Jail who?" );
        return;
    }

    if ( ( victim = get_char_room( ch, argument ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "That's pointless." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        if ( is_ai( victim, AI_THIEF ) )
        {
            if ( victim->position > POS_STUNNED )
            {
                ch_println( ch, "They're too lively to be arrested. Try stunning them first." );
                return;
            }

            if ( number_range( 1, 120 ) > get_learned_pct( ch, cache_skill( "jail", &skill_jail ) ) )
            {
                act( AT_ACTION, "Just as you're about to call a guard over, $N jumps up and runs away!", ch, NULL, victim, TO_CHAR );
                act( AT_ACTION, "$n tries to have $N arrested, but $E jumps up and runs away at the last second!", ch, NULL, victim, TO_NOTVICT );

                if ( ai_enabled( planet, AI_THIEF ) )
                    create_ai( planet, AI_THIEF, ai_random_generate( planet, AI_THIEF ), get_random_ai_room( planet, AI_THIEF ) );

                extract_char( victim );
                learn_from_failure( ch, cache_skill( "jail", &skill_jail ) );
                return;
            }

            ch_println( ch, "You have them escorted off to jail." );
            act( AT_ACTION, "$n has $N escorted away.",  ch, NULL, victim, TO_NOTVICT );
            double crime_drop = 0.5;
            int bounty = 4000;

            if ( number_range( 1, 8 ) == 1 )
            {
                ch_println( ch, "&YYou found a ringleader of the local criminal element!" );
                bounty = 50000;
                crime_drop += 6;
            }

            if ( count_planet_ai( planet, AI_THIEF ) == 1 )
            {
                ch_println( ch, "&YYou have eliminated the last criminal on %s!", planet->name );
                crime_drop += 3;
            }

            affect_planet_crime( planet, ch, crime_drop * -1 );
            save_planet( planet, true );
            ch_println( ch, "&wYou are paid &Y%d&w credits for assisting with planet security.", bounty );
            ch->gold += bounty;
            extract_char( victim );
            learn_from_success( ch, cache_skill( "jail", &skill_jail ) );
        }
        else
        {
            ch_println( ch, "That would be a waste of your time." );
        }

        return;
    }

    if ( !ch->pcdata || ( clan = ch->pcdata->clan ) == NULL )
    {
        ch_println( ch, "Only members of organizations can jail their enemies." );
        return;
    }

    if ( !planet->governed_by || ch->pcdata->clan != planet->governed_by )
    {
        ch_println( ch, "Your clan doesn't govern this planet." );
        return;
    }

    if ( planet->jailroom == 0 )
    {
        ch_println( ch, "This planet's jailroom is not set up!" );
        return;
    }

    jail = get_room_index( planet->jailroom );

    if ( !jail )
    {
        ch_println( ch, "Your organization does not have a suitable prison on this planet." );
        return;
    }

    if ( jail->area && ch->in_room->area
            && jail->area != ch->in_room->area &&
            ( !jail->area->planet || jail->area->planet != ch->in_room->area->planet ) )
    {
        ch_println( ch, "Your organization's prison is too far away." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is AFK." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( ch->position == POS_FIGHTING )
    {
        ch_println( ch, "Interesting combat technique." );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "In your dreams or what?" );
        return;
    }

    if ( victim->position >= POS_SLEEPING )
    {
        ch_println( ch, "You will have to stun them first." );
        return;
    }

    ch_println( ch, "You have them escorted off to jail." );
    act( AT_ACTION, "You have a strange feeling that you've been moved.\n", ch, NULL, victim, TO_VICT    );
    act( AT_ACTION, "$n has $N escorted away.\n",  ch, NULL, victim, TO_NOTVICT );
    char_from_room ( victim );
    char_to_room ( victim, jail );
    victim->jailed_time = time( 0 );
    do_save( victim, "-noalert" );
    act( AT_ACTION, "The door opens briefly as $n is shoved into the room.\n",  victim, NULL, NULL, TO_ROOM );
    learn_from_success( ch, cache_skill( "jail", &skill_jail ) );
    return;
}

CMDF do_smalltalk ( CHAR_DATA* ch, char* argument )
{
    char arg1 [MIL];
    CHAR_DATA* victim = NULL;
    PLANET_DATA* planet = NULL;
    CLAN_DATA*   clan = NULL;
    int xp = 0;

    if ( IS_NPC( ch ) || !ch->pcdata )
    {
        ch_println( ch, "What would be the point of that." );
    }

    argument = one_argument( argument, arg1 );

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "In your dreams or what?" );
        return;
    }

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "Create smalltalk with whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Smalltalk about which clan?" );
        return;
    }

    clan = get_clan( argument );

    if ( !clan || ( xIS_SET( clan->flags, CLAN_HIDDEN ) && ( !ch->pcdata->clan || ch->pcdata->clan != clan ) ) )
    {
        ch_println( ch, "Clan not found." );
        return;
    }

    if ( clan->clan_type != CLAN_GOVERNMENT )
    {
        ch_println( ch, "The locals only have opinions about governments." );
        return;
    }

    if ( !(
                is_cit( victim ) ||
                ( IS_NPC( victim ) && victim->pIndexData->pShop )
            ) )
    {
        ch_println( ch, "They wouldn't know much about the local public opinion." );
        return;
    }

    if ( victim->position <= POS_SLEEPING )
    {
        ch_println( ch, "You might want to wake them first..." );
        return;
    }

    WAIT_STATE( ch, cache_skill( "smalltalk", &skill_smalltalk )->beats );

    if ( number_range( 1, 100 ) > get_learned_pct( ch, cache_skill( "smalltalk", &skill_smalltalk ) )  )
    {
        ch_println( ch, "You attempt to make smalltalk with them, but are ignored." );
        act( AT_ACTION, "$n is really getting on your nerves with all this chatter!\n", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$n asks $N about the weather but is ignored.\n",  ch, NULL, victim, TO_NOTVICT );
        learn_from_failure( ch, cache_skill( "smalltalk", &skill_smalltalk ) );
        return;
    }

    ch_println( ch, "&wYou strike up a short conversation with them." );
    act( AT_ACTION, "$n smiles at you and says, 'hello'.\n", ch, NULL, victim, TO_VICT    );
    act( AT_ACTION, "$n chats briefly with $N.\n",  ch, NULL, victim, TO_NOTVICT );
    planet = get_planet_from_room( ch->in_room );

    if ( !planet )
        return;

    PLANET_SUPPORT_DATA* support = get_planet_support_data( planet, clan );

    if ( !support )
        return;

    ch_println( ch, "&wDuring your conversation, they mention %s...", clan->name );
    ch_println( ch, "%s %s. (%.0f/100)&w", support_public_opinion_name_detailed( planet, support ), clan->name, get_planet_pop_opinion( planet, clan ) );

    for ( PLANET_SUPPORT_EFFECT_DATA* effect = support->first_effect; effect; effect = effect->next )
    {
        int fuzzy_effect = effect->popular_opinion_mod;

        if ( fuzzy_effect != 0 && effect->type != PLANET_SUPPORT_EFF_CUSTOM )
            ch_println( ch, "&z - %s &z(&C%+d&z)", planet_support_effect_names[effect->type], fuzzy_effect );
    }

    // Add support for custom events
    for ( CUSTOM_EVENT_DATA* event = first_event; event; event = event->next )
    {
        if ( event->status != EVENT_ACTIVE )
            continue;

        for ( CUSTOM_EFFECT_DATA* effect = event->first_effect; effect; effect = effect->next )
        {
            if ( effect->opinion_modifier == 0 )
                continue;

            if ( !str_cmp( clan->name, effect->clan->name ) )
            {
                for ( EVENT_PLANET* ePlanet = effect->first_planet; ePlanet; ePlanet = ePlanet->next )
                {
                    if ( !str_cmp( planet->name, ePlanet->planet->name ) )
                    {
                        int fuzzy_effect = ePlanet->support_effect->popular_opinion_mod;
                        ch_println( ch, "&z - %s&z (&C%+d&z)", event->name, fuzzy_effect );
                    }
                }
            }
        }
    }

    ch_println( ch, "\nThey've also noticed that..."
               "%s %s &w(%.0f/100)\n", clan->name, support_military_presence_name_detailed( support ), support->military_presence );
    xp = victim->top_level * 10;
    xp = apply_xp_sink( ch, xp, LEADERSHIP_ABILITY );
    gain_exp( ch, xp, LEADERSHIP_ABILITY, TRUE );
    ch_println( ch, "You gain %d leadership experience.", xp );
    learn_from_success( ch, cache_skill( "smalltalk", &skill_smalltalk ) );
}

CMDF do_propaganda ( CHAR_DATA* ch, char* argument )
{
    char buf  [MSL];
    char vic_name [MIL];
    char for_against [MIL];
    char* clan_name;
    CHAR_DATA* victim;
    CLAN_DATA*   clan = NULL;
    int xp = 0;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Mobs can't do propaganda." );
        return;
    }

    argument = one_argument( argument, vic_name );
    clan_name = one_argument( argument, for_against );
    PLANET_DATA* planet = on_planet( ch );

    if ( NULLSTR( vic_name ) ||
            NULLSTR( for_against ) ||
            NULLSTR( clan_name ) ||
            ( str_cmp( for_against, "for" ) && str_cmp( for_against, "against" ) ) )
    {
        ch_println( ch, "&zSyntax: &Cpropaganda <&wtarget&C> <&wfor/against&C> <&wclan&C>" );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( ( victim = get_char_room( ch, vic_name ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ch == victim || !is_cit( victim ) || is_safe( ch, victim ) )
    {
        ch_println( ch, "Diplomacy would be wasted on them." );
        return;
    }

    if ( ch->position == POS_FIGHTING )
    {
        ch_println( ch, "Interesting combat technique." );
        return;
    }

    if ( victim->position == POS_FIGHTING )
    {
        ch_println( ch, "They're a little busy right now." );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "In your dreams or what?" );
        return;
    }

    if ( victim->position <= POS_SLEEPING )
    {
        ch_println( ch, "You might want to wake them first..." );
        return;
    }

    clan = get_clan( clan_name );

    if ( !clan )
    {
        ch_println( ch, "Clan not found." );
        return;
    }

    if ( clan->clan_type != CLAN_GOVERNMENT )
    {
        ch_println( ch, "You can only spread propaganda about governments." );
        return;
    }

    bool against = !str_cmp( for_against, "against" );
    snprintf( buf, MSL, "$n tells you about the %s of %s.", against ? "evils" : "benefits", clan->name );
    act( AT_ACTION, buf, ch, NULL, victim, TO_VICT );
    snprintf( buf, MSL, "You tell $N about the %s of %s.", against ? "evils" : "benefits", clan->name );
    act( AT_ACTION, buf, ch, NULL, victim, TO_CHAR );
    act( AT_ACTION, "$n tells $N about an organization.",  ch, NULL, victim, TO_NOTVICT );
    // 100%, 5 cha: 40
    // 100%, 25 cha: 100
    int chance = get_learned_pct( ch, cache_skill( "propaganda", &skill_propaganda ) ) / 2 + get_curr_cha( ch ) * 3 - 25;

    if ( number_percent() > chance )
    {
        act( AT_ACTION, "$N doesn't seem convinced.", ch, NULL, victim, TO_CHAR );
        learn_from_failure( ch, cache_skill( "propaganda", &skill_propaganda ) );
    }
    else
    {
        affect_popular_opinion( ch, planet, clan, PLANET_SUPPORT_EFF_OUTREACH, against ? -0.25 : 0.25 );
        xp = victim->top_level * 100;
        xp = apply_xp_sink( ch, xp, LEADERSHIP_ABILITY );
        gain_exp( ch, xp, LEADERSHIP_ABILITY, TRUE );
        ch_println( ch, "You gain %d leadership experience.", xp );
        learn_from_success( ch, cache_skill( "propaganda", &skill_propaganda ) );
    }

    act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_CHAR );
    act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_ROOM );
    extract_char( victim );
    WAIT_STATE( ch, cache_skill( "propaganda", &skill_propaganda )->beats );
}
CMDF do_garrison( CHAR_DATA* ch, char* argument )
{
    PLANET_DATA* planet = NULL;
    CLAN_DATA* clan = NULL;
    int cst = 0;
    planet = on_planet( ch );

    if ( !planet || argument[0] == '\0' || ( str_cmp( "recruit", argument ) && str_cmp( "disband", argument ) ) )
    {
        ch_println( ch, "Usage: garrison <recruit/disband>\nNote: This requires that you are on a planet your clan owns." );
        return;
    }

    clan = planet->governed_by;

    if ( !clan || IS_NPC( ch ) || clan != ch->pcdata->clan )
    {
        ch_println( ch, "You cannot do that on this planet." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_COMMAND ) )
    {
        ch_println( ch, "You need to be in the command room." );
        return;
    }

    if ( IS_NPC( ch ) || !is_empowered( ch, "diplomat" ) )
    {
        ch_println( ch, "You have not been given clearance as a diplomat." );
        return;
    }

    cst = IS_NPC( ch ) ? 0 : ( int ) get_learned_pct( ch, cache_skill( "garrison", &skill_garrison ) );

    if ( number_percent() > cst )
    {
        ch_println( ch, "You forget how to do this..." );
        learn_from_failure( ch, cache_skill( "garrison", &skill_garrison ) );
    }
    else
    {
        set_char_color( AT_ACTION, ch );

        if ( !str_cmp( "recruit", argument ) )
        {
            if ( planet->troops > ( int )( 2 * ( planet->population / 10 ) ) )
            {
                ch_println( ch, "You cannot have more than 20%% of the population in the military." );
                return;
            }

            cst = 100000;
            cst -= 1000 * get_curr_cha( ch );

            if ( clan->funds < cst )
            {
                ch_println( ch, "%s cannot afford that!", clan->name );
                return;
            }

            ch_println( ch, "You recruit a trooper for %d credits.", cst );
            clan->funds -= cst;
            sql_credits_log( clan->name, "do_garrison", cst * -1, TRUE );
            planet->troops++;
        }
        else
        {
            cst = 25000;
            cst += 1000 * get_curr_cha( ch );
            cst /= 2;

            if ( planet->troops <= 0 )
            {
                ch_println( ch, "This planet doesn't HAVE troops." );
                return;
            }

            planet->troops--;
            clan->funds += cst;
            sql_credits_log( clan->name, "do_garrison", cst, TRUE );
            ch_println( ch, "You send a trooper home, and get %d credits for %s.", cst, clan->name );
        }

        save_clan( clan, true );
        save_planet( planet, true );
        learn_from_success( ch, cache_skill( "garrison", &skill_garrison ) );
    }
}
CMDF do_closeshop( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CLAN_DATA* clan = NULL;
    PLANET_DATA* planet = NULL;
    CHAR_DATA* vendor = NULL;
    char buf[MSL];
    planet = on_planet( ch );

    if ( !planet )
    {
        ch_println( ch, "Maybe if you were on a planet." );
        return;
    }

    //Moved clan setting out of the <103 ifcheck to ensure the closeshop echo goes to the right place when an imm does it. -Gathorn May2016
    clan = planet->governed_by;

    //We don't need to check for diplo levels because this is already an empowerment. - walldo
    if ( ch->top_level < 103 )
    {
        if ( !clan || IS_NPC( ch ) || !ch->pcdata->clan || clan != ch->pcdata->clan )
        {
            ch_println( ch, "You don't have any authority on this planet." );
            return;
        }
        else if ( !is_empowered( ch, "diplomat" ) && str_cmp( ch->name, ch->pcdata->clan->leader ) && str_cmp( ch->name, ch->pcdata->clan->number1 ) && str_cmp( ch->name, ch->pcdata->clan->number2 ) )
        {
            ch_println( ch, "You must have the 'diplomat' empowerment before you can close shops." );
            return;
        }
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_VENDOR ) )
    {
        ch_println( ch, "This isn't even a shop." );
        return;
    }

    for ( vendor = ch->in_room->first_person; vendor; vendor = vendor->next_in_room )
        if ( IS_NPC( vendor ) && vendor->pIndexData->vnum == MOB_VNUM_VENDOR )
            break;

    if ( !vendor )
    {
        ch_println( ch, "It would appear that this shop is already vacant." );
        return;
    }

    snprintf( buf, MSL, "&zShop '%s&z', owned by %s, in room %d on planet %s has been closed by %s (%s)",
        ch->in_room->name, (vendor->vendor_data && vendor->vendor_data->owner) ? vendor->vendor_data->owner : "(null)",
        ch->in_room->vnum, planet->name, ch->name, (ch->pcdata && ch->pcdata->clan) ? ch->pcdata->clan->name : "null" );
    write_to_log( "closeshop", buf, sysdata.log_level, 0, TRUE );

    raw_kill( ch, vendor );
    set_char_color( AT_ACTION, ch );
    ch_println( ch, "You close this shop down.", ch );
    act( AT_ACTION, "$n closes down the shop on behalf of the local authorities.", ch, NULL, NULL, TO_ROOM );
    snprintf( buf, MSL, "&z[&wNotice&z]: &WShop &c'&w%s&c' &Whas been shut down on &w%s&W.\n", ch->in_room->name, planet->name );

    for ( vendor = first_char; vendor; vendor = vendor->next )
        if ( !IS_NPC( vendor ) && vendor->pcdata->clan != NULL && vendor->pcdata->clan == clan && clan != NULL )
            send_to_char( buf, vendor );


    reset_vendor_room( ch->in_room );
    save_room( ch->in_room, true );
    return;
}

CMDF do_bribe ( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    CLAN_DATA*   clan;
    PLANET_DATA* planet = get_planet_from_room( ch->in_room );

    if ( IS_NPC( ch ) || !ch->pcdata || !planet )
    {
        ch_println( ch, "What would be the point of that." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Bribe who?" );
        return;
    }

    if ( ch->gold < 1000 )
    {
        ch_println( ch, "You don't have enough credits for a bribe." );
        return;
    }

    if ( ( victim = get_char_room( ch, argument ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( IS_ANIMAL( victim ) ) // Gral and Asmo idea - implemented by Ravaus by request
    {
        ch_println( ch, "You know, animals don't really figure into popular support ratings." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "That's pointless." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( ch->position == POS_FIGHTING )
    {
        ch_println( ch, "Interesting combat technique." );
        return;
    }

    if ( victim->position == POS_FIGHTING )
    {
        ch_println( ch, "They're a little busy right now." );
        return;
    }

    if ( ch->position <= POS_SLEEPING )
    {
        ch_println( ch, "In your dreams or what?" );
        return;
    }

    if ( victim->position <= POS_SLEEPING )
    {
        ch_println( ch, "You might want to wake them first..." );
        return;
    }

    planet = on_planet( ch );

    // make police, troops, customs, etc. disappear
    if ( is_pol( victim ) || is_troop( victim ) || is_customs( victim ) )
    {
        ch->gold -= 1000;

        if ( !IS_NPC( ch ) )
            sql_credits_log( ch->name, "do_bribe", -1000, TRUE );

        ch_println( ch, "You give them a small bribe." );
        act( AT_ACTION, "$n gives $N some money.", ch, NULL, victim, TO_NOTVICT );
        act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_ROOM );
        extract_char( victim );
        affect_planet_crime( planet, ch, 0.33 );
        learn_from_success( ch, cache_skill( "bribe", &skill_bribe ) );
        return;
    }

    clan = ch->pcdata->clan;

    if ( !clan || clan->clan_type != CLAN_GOVERNMENT )
    {
        ch_println( ch, "You must be in a government clan to bribe citizens." );
        return;
    }

    if ( !is_cit( victim ) || !IS_NPC( victim ) )
    {
        ch_println( ch, "Diplomacy would be wasted on them." );
        return;
    }

    ch->gold -= 1000;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "do_bribe", -1000, TRUE );

    ch_println( ch, "You give them a small gift on behalf of %s.", ch->pcdata->clan->name );
    act( AT_ACTION, "$n offers you a small bribe.", ch, NULL, victim, TO_VICT    );
    act( AT_ACTION, "$n gives $N some money.",  ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_CHAR );
    act( AT_ACTION, "$N wanders off.", ch, NULL, victim, TO_ROOM );
    extract_char( victim );
    WAIT_STATE( ch, cache_skill( "bribe", &skill_bribe )->beats );
    affect_popular_opinion( ch, planet, clan, PLANET_SUPPORT_EFF_OUTREACH, 0.1 );
    int xpgain = UMIN( 1000, ( exp_level( ch->skill_level[LEADERSHIP_ABILITY] + 1 ) - exp_level( ch->skill_level[LEADERSHIP_ABILITY] ) ) );
    xpgain = apply_xp_sink( ch, xpgain, LEADERSHIP_ABILITY );
    gain_exp( ch, xpgain, LEADERSHIP_ABILITY, TRUE );
    ch_println( ch, "You gain %d leadership experience.", xpgain );
    learn_from_success( ch, cache_skill( "bribe", &skill_bribe ) );
}

/*
    New Jedi Skill - BREACH

    Used in combination with a lightsaber
    to 'breach' a doorway.
*/
int breach_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop cutting." );
    act( AT_ACTION, "$n stops cutting.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int breach_complete_door( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* weapon = get_obj_from_buffer( buffer, "weapon" );
    EXIT_DATA* pexit = find_door( ch, buffer->str1, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "The door seems to be gone." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
    {
        ch_println( ch, "Why bother? It's not even closed." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    char* keyword;
    if ( xIS_SET( pexit->flags, EX_SECRET ) )
        keyword = "wall";
    else
        keyword = pexit->keyword;

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "breach", &skill_breach ) ) * 0.8 );
    if ( number_percent( ) <= chance )
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        /* Drain the lightsaber a bit */
        weapon->value[4] -= 25;
        xREMOVE_BIT( pexit->flags, EX_CLOSED );
        xREMOVE_BIT( pexit->flags, EX_LOCKED );
        xSET_BIT( pexit->flags, EX_BREACHED );
        act( AT_YELLOW, "Your lightsaber cuts a hole in the $d!", ch, NULL, keyword, TO_CHAR );
        act( AT_YELLOW, "The $d is cut by $n's lightsaber, a shower of sparks illuminating the new hole!", ch, NULL, keyword, TO_ROOM );
        learn_from_success( ch, cache_skill( "breach", &skill_breach ) );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            xREMOVE_BIT( pexit->rexit->flags, EX_CLOSED );
            xREMOVE_BIT( pexit->rexit->flags, EX_LOCKED );
            xSET_BIT( pexit->rexit->flags, EX_BREACHED );
            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "A blade punches through the $d as someone on the other side cuts a hole in it!", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }
    }
    else
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        weapon->value[4] -= number_range( 15, 25 );
        act( AT_SKILL, "You try to slice through the $d, but it holds strong.", ch, NULL, keyword, TO_CHAR );
        act( AT_SKILL, "$n tries to slice through the $d, but it holds strong.", ch, NULL, keyword, TO_ROOM );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            xREMOVE_BIT( pexit->rexit->flags, EX_CLOSED );
            xREMOVE_BIT( pexit->rexit->flags, EX_LOCKED );
            xSET_BIT( pexit->rexit->flags, EX_BREACHED );
            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d begins to cool down.", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }
        learn_from_failure( ch, cache_skill( "breach", &skill_breach ) );
    }

    return E_LOTJ_SUCCESS;
}

int breach_complete_ship( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* weapon = get_obj_from_buffer( buffer, "weapon" );
    SHIP_DATA* ship = buffer->ship;
    if ( !valid_ship( ship ) || ch->in_room != ship->in_room )
    {
        ch_println( ch, "That ship has left!" );
        return E_LOTJ_SUCCESS;
    }

    if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
    {
        ch_println( ch, "Someone beat you to the punch. It's already open." );
        return E_LOTJ_SUCCESS;
    }

    if ( ( ship->shipstate == SHIP_HOVER || ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH ) && !IS_AFFECTED( ch, AFF_FLYING ) )
    {
        ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
        return E_LOTJ_SUCCESS;
    }

    if ( ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH )
    {
        ch_println( ch, "&RThe ship is maneuvering too fast for you to approach! Wait for it to reach a stable hover!" );
        return E_LOTJ_SUCCESS;
    }

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "breach", &skill_breach ) ) * 0.8 );
    if ( number_percent( ) <= chance )
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        /* Drain the lightsaber a bit */
        weapon->value[4] -= 25;
        ch_println( ch, "&YYou use your lightsaber to cut the hatchway." );
        act( AT_SKILL, "$n slices a neat hole in $ts hatchway with $s cutter.", ch, ship->name, NULL, TO_ROOM );
        /* GRAL added to let entry way people know the hatch has just been destroyed */
        echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "A blade punches through the hatch as someone on the other side cuts a hole in it!" );
        learn_from_success( ch, cache_skill( "breach", &skill_breach ) );
        xSET_BIT( ship->flags, SHIP_BROKEN_HATCH ); // GRAL These two are getting out of synch
        ship->hatchopen = TRUE;
    }
    else
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        weapon->value[4] -= number_range( 15, 25 );
        act( AT_SKILL, "You try to slice through the hatch, but it holds strong.", ch, NULL, NULL, TO_CHAR );
        act( AT_SKILL, "$n tries to slice through the hatch, but it holds strong.", ch, NULL, NULL, TO_ROOM );
        echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch begins to cool down." );
        learn_from_failure( ch, cache_skill( "breach", &skill_breach ) );
    }

    return E_LOTJ_SUCCESS;
}

int breach_complete_structure( CHAR_DATA* ch, BUFFER_DATA* buffer )
