}

CMDF do_breach( CHAR_DATA* ch, char* argument )
{
    // Check this first in case they're in the struct entrance and the command should work with no arg.
    STRUCTURE_DATA* stru = find_struct_entrance_in_room( ch->in_room, argument );

    if ( NULLSTR( argument ) && !stru )
    {
        ch_println( ch, "&zSyntax: &Cbreach <&wdirection / ship name / structure name&C>" );
        return;
    }

    OBJ_DATA* wield = get_eq_char( ch, WEAR_WIELD );
    if ( !wield )
    {
        ch_println( ch, "&RYou're not wielding anything to do that with!" );
        return;
    }

    if ( wield->item_type != ITEM_WEAPON || wield->value[3] != WEAPON_LIGHTSABER )
    {
        ch_println( ch, "&RYou need a lightsaber to cut a door!" );
        return;
    }

    if ( wield->value[4] < 25 )
    {
        ch_println( ch, "&RTry recharging your lightsaber first!" );
        return;
    }

    if ( ch->move < 20 )
    {
        ch_println( ch, "&RYou're too tired to slice open any doors!" );
        return;
    }

    if ( stru )
    {
        if ( !xIS_SET( stru->exit_flags, EX_ISDOOR ) )
        {
            ch_println( ch, "That structure doesn't have a door." );
            return;
        }

        if ( !xIS_SET( stru->exit_flags, EX_CLOSED ) )
        {
            ch_println( ch, "The door is already open." );
            return;
        }

        if ( stru->entrance == ch->in_room->vnum )
        {
            if ( !get_room_index( stru->in_room ) )
            {
                ch_println( ch, "This structure has a buggy exit." );
                return;
            }
        }
        else
        {
            if ( !get_room_index( stru->entrance ) )
            {
                ch_println( ch, "This structure has a buggy entrance." );
                return;
            }
        }

        if ( xIS_SET( stru->exit_flags, EX_BREACHED ) )
        {
            ch_println( ch, "Someone beat you to the punch. It's already cut open." );
            return;
        }

        act( AT_ACTION, "You begin to breach into the $t.", ch, stru->name, NULL, TO_CHAR );
        act( AT_ACTION, "$n begins to breach into the $t.", ch, stru->name, NULL, TO_ROOM );

        /* GRAL added to let entry way people know the hatch is being cut */
        if ( ch->in_room && get_room_index( stru->entrance ) == ch->in_room )
            echo_to_room( AT_YELLOW, get_room_index( stru->in_room ), "The door begins to heat up and dimly glow as someone on the other side tries to cut a hole in it!" );
        else
            echo_to_room( AT_YELLOW, get_room_index( stru->entrance ), "The door begins to heat up and dimly glow as someone on the other side tries to cut a hole in it!" );

        action_set( ch, NULL, strfmt("is breaching the door to %s.", stru->name), NULL, 0 );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 39, breach_complete_structure, breach_abort, FUNC );
        timer->buffer->structure = structure_to_ref( stru );
        add_obj_to_buffer( timer->buffer, "weapon", wield );
        return;
    }

    EXIT_DATA* pexit = find_door( ch, argument, TRUE );
    if ( pexit )
    {
        if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
        {
            ch_println( ch, "Why bother? It's not even closed." );
            return;
        }

        if ( xIS_SET( pexit->flags, EX_BREACHPROOF ) )
        {
            ch_println( ch, "&RYour lightsaber won't make a dent in that door!" );
            return;
        }

        if ( xIS_SET( pexit->flags, EX_BREACHED ) )
        {
            ch_println( ch, "&RThat door is already cut open." );
            return;
        }

        alarm_room( ch->in_room, "door cut tamper sensor tripped at" );
        act( AT_ACTION, "You begin to breach into the $d.", ch, NULL, pexit->keyword, TO_CHAR );
        act( AT_ACTION, "$n begins to breach into the $d.", ch, NULL, pexit->keyword, TO_ROOM );

        /* GRAL added so the people on the far side get warned */
        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d begins to heat up and dimly glow as someone on the other side tries to cut a hole in it!", rch, NULL, pexit->rexit->keyword, TO_CHAR );

        action_set( ch, NULL, strfmt("is cutting the %s door.", get_dir_name( pexit->vdir )), NULL, 0 );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 39, breach_complete_door, breach_abort, FUNC );
        SET_STRING( timer->buffer->str1, argument );
        add_obj_to_buffer( timer->buffer, "weapon", wield );
        return;
    }

    SHIP_DATA* ship = ship_in_room( ch->in_room, argument );
    if ( ship )
    {
        if ( !get_room_index( ship->entrance ) )
        {
            ch_println( ch, "You can't breach into that ship!" );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            ch_println( ch, "Someone beat you to the punch. It's already open." );
            return;
        }

        if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        {
            ch_println( ch, "You cannot breach that ship." );
            return;
        }

        if ( ( ship->shipstate == SHIP_HOVER || ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH ) && !IS_AFFECTED( ch, AFF_FLYING ) )
        {
            ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
            return;
        }

        if ( ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH )
        {
            ch_println( ch, "&RThe ship is maneuvering too fast for you to approach! Wait for it to reach a stable hover!" );
            return;
        }

        act( AT_ACTION, "You begin using your lightsaber to cut into $ts hatch.", ch, ship->name, NULL, TO_CHAR );
        act( AT_ACTION, "$n begins to use $s lightsaber to cut into $ts hatch.", ch, ship->name, NULL, TO_ROOM );
        action_set( ch, NULL, strfmt("is breaching into %s.", ship->name), NULL, 0 );
        /* GRAL added to let entry way people know the hatch is being cut */
        echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch begins to heat up and dimly glow as someone on the other side tries to cut a hole in it!" );

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 39, breach_complete_ship, breach_abort, FUNC );
        timer->buffer->ship = ship;
        add_obj_to_buffer( timer->buffer, "weapon", wield );
        return;
    }

    ch_println( ch, "&RYou don't see that here." );
    return;
}

int doorcut_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop cutting." );
