int doorcut_complete_door( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* cutter = get_obj_from_buffer( buffer, "cutter" );
    EXIT_DATA* pexit = find_door( ch, buffer->str1, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "The door seems to be gone." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
    {
        ch_println( ch, "Why bother? It's not even closed." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( xIS_SET( pexit->flags, EX_CUTPROOF ) )
    {
        ch_println( ch, "&RYour fusion cutter won't make a dent in that door!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( xIS_SET( pexit->flags, EX_BREACHED ) )
    {
        ch_println( ch, "&RThat door is already cut open!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    char* keyword;
    if ( xIS_SET( pexit->flags, EX_SECRET ) )
        keyword = "wall";
    else
        keyword = pexit->keyword;

    int chance = IS_NPC( ch ) ? ch->top_level : ( int )( get_learned_pct( ch, cache_skill( "doorcut", &skill_doorcut ) ) * 0.65 );
    if ( number_percent( ) <= chance )
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        /* Drain the lightsaber a bit */
        cutter->value[4] -= 25;
        xREMOVE_BIT( pexit->flags, EX_CLOSED );
        xREMOVE_BIT( pexit->flags, EX_LOCKED );
        xSET_BIT( pexit->flags, EX_BREACHED );
        act( AT_SKILL, "Using your tool, you begin to cut a hole in the $d!", ch, NULL, keyword, TO_CHAR );
        act( AT_SKILL, "$n swings $s weapon at the $d!", ch, NULL, keyword, TO_ROOM );
        act( AT_YELLOW, "You cut a neat hole in the $d!", ch, NULL, keyword, TO_CHAR );
        act( AT_YELLOW, "The $d is cut by $n, a shower of sparks illuminating the new hole!", ch, NULL, keyword, TO_ROOM );
        learn_from_success( ch, cache_skill( "doorcut", &skill_doorcut ) );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            xREMOVE_BIT( pexit->rexit->flags, EX_CLOSED );
            xREMOVE_BIT( pexit->rexit->flags, EX_LOCKED );
            xSET_BIT( pexit->rexit->flags, EX_BREACHED );

            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d falls off its hinges as someone on the other side cuts a hole around it!", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }
    }
    else
    {
        /* Force the character to go visible */
        do_visible( ch, "-noalert" );
        cutter->value[4] -= number_range( 15, 25 );
        act( AT_SKILL, "You try to slice through the $d, but it holds strong.", ch, NULL, keyword, TO_CHAR );
        act( AT_SKILL, "$n tries to slice through the $d, but it holds strong.", ch, NULL, keyword, TO_ROOM );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d begins to cool down.", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }

        learn_from_failure( ch, cache_skill( "doorcut", &skill_doorcut ) );
    }
    return E_LOTJ_SUCCESS;
}

