            seconds -= ( int )( seconds * .2 );

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, seconds, doorcut_complete_ship, doorcut_abort, FUNC );
        timer->buffer->ship = ship;
        add_obj_to_buffer( timer->buffer, "cutter", cutter );
        return;
    }

    ch_println( ch, "&RYou don't see that here." );
}

