int makecutter_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* dura = get_obj_from_buffer( buffer, "dura" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* lens = get_obj_from_buffer( buffer, "lens" );
    OBJ_DATA* mirror = get_obj_from_buffer( buffer, "mirror" );

    char buf[MSL];
    int value = 0, charge = 0;

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    value += dura->pIndexData->cost;
    charge = battery->value[0];
    value += battery->pIndexData->cost;
    value += super->pIndexData->cost;
    value += circuit->pIndexData->cost;
    value += lens->pIndexData->cost;
    value += mirror->pIndexData->cost;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ESPIONAGE_ABILITY, EFFORT_CUTTER ), ch->max_move );
    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makecutter", &skill_makecutter ) ) ) ;
    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou hold up your cutter and press the activation switch." );
        ch_println( ch, "&RInstead of a plasma beam, smoke plumes out." );
        ch_println( ch, "&RYou drop the hot handle and watch as your creation falls apart." );
        learn_from_failure( ch, cache_skill( "makecutter", &skill_makecutter ) );
        return E_LOTJ_SUCCESS;
    }

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makecutter", &skill_makecutter ) ) );
    OBJ_DATA* obj = create_object( pObjIndex, level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    set_crafted( ch, obj );
    obj->item_type = ITEM_CUTTER;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_HOLD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    obj->level = level;
    obj->weight = 10;
    strlcpy( buf, "fusion cutter ", MSL );
    strlcat( buf, stripclr( arg ), MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was left here on the ground.", MSL );
    SET_STRING( obj->description, buf );
    strlcpy( buf, arg, MSL );
    strlcat( buf, " &wA fusion cutter &Ysparks &wto life.", MSL );
    SET_STRING( obj->action_desc, buf );
    obj->value[0] = INIT_WEAPON_CONDITION;       /* condition  */
    obj->value[4] = charge * 2;
    obj->value[5] = charge * 2;
    obj->cost = calc_markup( ch, value );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your cutter and activate it. Congratulations, it does not explode.&w" );
    act( AT_PLAIN, "$n finishes making $s fusion cutter.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 200, ( exp_level( ch->skill_level[ESPIONAGE_ABILITY] + 1 ) - exp_level( ch->skill_level[ESPIONAGE_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ESPIONAGE_ABILITY );
    gain_exp( ch, xpgain, ESPIONAGE_ABILITY, TRUE );
    ch_println( ch, "You gain %d espionage experience, for all that it is worth. ", xpgain );
    learn_from_success( ch, cache_skill( "makecutter", &skill_makecutter ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makecutter( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zUsage:&C Makecutter <&wname&C>&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( stristr( argument, "saber" ) )
    {
        ch_println( ch, "&RFusion cutters are not lightsabers. Please pick a different name." );
        write_to_log( FUNC, strfmt("%s trying to make a fusion cutter named %s", ch->name, argument), sysdata.log_level, 720, true );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_REFINERY ) )
    {
        ch_println( ch, "&RYou need to be far from prying eyes to make a cutter...perhaps a refinery?" );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou are going to need some tools to get started." );
        return;
    }

    OBJ_DATA* dura = get_obj_carried_of_type( ch, ITEM_DURASTEEL );
    if ( !dura )
        dura = get_obj_carried_of_type( ch, ITEM_DURAPLAST );
    if ( !dura )
    {
        ch_println( ch, "&RYou need duraplast or durasteel to make it out of." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a power source for your cutter." );
        return;
    }

    OBJ_DATA* circuit = get_obj_carried_of_type( ch, ITEM_CIRCUIT );
    if ( !circuit )
    {
        ch_println( ch, "&RYou need a circuit to control the activation mechanism." );
        return;
    }

    OBJ_DATA* super = get_obj_carried_of_type( ch, ITEM_SUPERCONDUCTOR );
    if ( !super )
    {
        ch_println( ch, "&RYou need a superconductor to regulate the current." );
        return;
    }

    OBJ_DATA* lens = get_obj_carried_of_type( ch, ITEM_LENS );
    if ( !lens )
    {
        ch_println( ch, "&RYou need a lens to focus the energy beam." );
        return;
    }

    OBJ_DATA* mirror = get_obj_carried_of_type( ch, ITEM_MIRROR );
    if ( !mirror )
    {
        ch_println( ch, "&RYou need a mirror to amplify the energy beam." );
        return;
    }

    if ( calc_effortrate( ch, ESPIONAGE_ABILITY, EFFORT_CUTTER ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, makecutter_complete, makecutter_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "dura", dura, dura->item_type == ITEM_DURASTEEL ? "Durasteel" : "Duraplast" );
    add_consumable_to_buffer( timer->buffer, "battery", battery, "Battery" );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "super", super, "Superconductor" );
    add_consumable_to_buffer( timer->buffer, "lens", lens, "Lens" );
    add_consumable_to_buffer( timer->buffer, "mirror", mirror, "Mirror" );

    ch_println( ch, "&GYou begin the long process of crafting a fusion cutter." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and begins to craft something.", ch,
            NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is creating a cutter.", NULL, 0 );
}

CMDF do_slip( CHAR_DATA* ch, char* argument )
{
    char arg1 [MIL];
    char arg2 [MIL];
    char buf  [MIL];
    CHAR_DATA* victim;
    OBJ_DATA*  obj;
    int chance;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !str_cmp( arg2, "to" ) && argument[0] != '\0' )
        argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zUsage:&C SLIP <&wobject&C> <&wtarget&C>&w" );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    /* Slip Credits */
    if ( is_number( arg1 ) )
    {
        /* 'give NNNN coins victim' */
        int amount;
        amount   = atoi( arg1 );

        if ( amount <= 0 || ( str_cmp( arg2, "credits" ) && str_cmp( arg2, "credit" ) ) )
        {
            ch_println( ch, "Sorry, you can't do that." );
            return;
        }

        argument = one_argument( argument, arg2 );

        if ( !str_cmp( arg2, "to" ) && argument[0] != '\0' )
            argument = one_argument( argument, arg2 );

        if ( ( victim = get_char_room( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "That person isn't in here." );
            return;
        }

        // Gral added so Imms can always slip things. Need it for mini-events, 'story' characters, valentines
        if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "That player is AFK." );
            return;
        }

        if ( ch == victim )
        {
            ch_println( ch, "You're not going to slip that to yourself!" );
            return;
        }

        if ( is_safe( ch, victim ) )
            return;

        if ( !is_near( ch, victim ) )
        {
            ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
            return;
        }

        if ( ch->gold < amount )
        {
            ch_println( ch, "Very generous of you, but you haven't got that many credits." );
            return;
        }

        if ( xIS_SET( victim->act, ACT_NOGIVE ) )
        {
            ch_println( ch, "&wYou cannot give that to them." );
            return;
        }

        if ( victim->gold + amount > sysdata.maxgold )
        {
            ch_println( ch, "They can't carry any more credits." );
            return;
        }

        if ( !IS_NPC( victim ) && ( victim->skill_level[FORCE_ABILITY] >= 60 || ( int ) get_learned_pct( victim, cache_skill( "thieves eye", &skill_thieves_eye ) ) == 100 )
                && !IS_IMMORTAL( ch ) && !has_pcflag( victim, PCFLAG_NO_SENSE ) )
        {
            act( AT_ACTION, "$n tries to slip you something, but you notice!", ch, NULL, victim, TO_VICT );
            act( AT_ACTION, "You try to slip something to $N, but $E notices!", ch, NULL, victim, TO_CHAR );
            return;
        }

        if ( valid_focus( victim, ESPIONAGE_ABILITY ) && !IS_IMMORTAL( ch ) )
        {
            if ( victim->leader == NULL )
            {
                act( AT_ACTION, "Your watchful eye catches $n slipping something to you.", ch, NULL, victim, TO_VICT );
            }
            else if ( victim->leader != ch )
            {
                snprintf( buf, MIL, "Your watchful eye catches $n slipping something to %s.", g_name( victim, victim->leader ) );
                act( AT_ACTION, buf, ch, NULL, victim->leader, TO_VICT );
            }
        }

        ch->gold     -= amount;
        victim->gold += amount;

        if ( !IS_NPC( ch ) )
            sql_credits_log( ch->name, "do_slip", amount * -1, FALSE );

        if ( !IS_NPC( victim ) )
            sql_credits_log( victim->name, "do_slip", amount, FALSE );

        chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "slip", &skill_slip ) );

        if ( ( number_percent( ) > chance ) && !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "&RYou botched...bad. Everyone saw that." );
            snprintf( buf, MIL, "$n slips you %d %s.", amount, ( amount > 1 ) ? "credits" : "credit" );
            act( AT_ACTION, buf, ch, NULL, victim, TO_VICT    );
            act( AT_ACTION, "$n slips $N some credits.",  ch, NULL, victim, TO_NOTVICT );
            learn_from_failure( ch, cache_skill( "slip", &skill_slip ) );
            mprog_bribe_trigger( victim, ch, amount );
        }
        else
        {
            learn_from_success( ch, cache_skill( "slip", &skill_slip ) );
        }

        act( AT_ACTION, "You slip $N some credits.",  ch, NULL, victim, TO_CHAR    );
        return;
    }

    /* Slip Objects */
    if ( ( obj = get_obj_carry( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "You do not have that item." );
        return;
    }

    if ( obj->wear_loc != WEAR_NONE )
    {
        ch_println( ch, "You must remove it first." );
        return;
    }

    if ( ( victim = get_char_room( ch, arg2 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    // Gral added so Imms can always slip things. Need it for mini-events, 'story' characters, valentines
    //      also added an anti AFK flag, could slip things in the past. People used to slip AFK people container messages etc.
    //      More for alt interaction and muling to a safe person.
    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "That player is AFK." );
        return;
    }

    if ( !is_near( ch, victim ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "You're not going to slip that to yourself!" );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( xIS_SET( victim->act, ACT_NOGIVE ) )
    {
        ch_println( ch, "&wYou cannot give that to them." );
        return;
    }

    if ( obj->item_type == ITEM_DISK && xIS_SET( victim->act, ACT_MESSAGE_DRONE ) )
    {
        EXTRA_DESCR_DATA* ed = SetOExtra( obj, "_sender_" );
        SET_STRING( ed->description, ch->name );
    }

    if ( !can_drop_obj( ch, obj ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You can't let go of it." );
        return;
    }

    do_stop( ch, "" );

    if ( !IS_NPC( victim ) && ( victim->skill_level[FORCE_ABILITY] >= 60 || ( int ) get_learned_pct( victim, cache_skill( "thieves eye", &skill_thieves_eye ) ) == 100 )
            && !IS_IMMORTAL( ch ) && !has_pcflag( victim, PCFLAG_NO_SENSE ) )
    {
        act( AT_ACTION, "$n tries to slip you something, but you notice!", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "You try to slip something to $N, but $E notices!", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( valid_focus( victim, ESPIONAGE_ABILITY ) && !IS_IMMORTAL( ch ) )
    {
        if ( victim->leader == NULL )
        {
            act( AT_ACTION, "Your watchful eye catches $n slipping something to you.", ch, NULL, victim, TO_VICT );
        }
        else if ( victim->leader != ch )
        {
            snprintf( buf, MIL, "Your watchful eye catches $n slipping something to %s.", g_name( victim, victim->leader ) );
            act( AT_ACTION, buf, ch, NULL, victim->leader, TO_VICT );
        }
    }

    /* Vendor Safety Patch */

    if ( IS_NPC( victim ) )
    {
        if ( victim->vendor_data )
        {
            if ( !is_your_vendor( ch, victim ) )
            {
                ch_println( ch, "&RThats not your vendor! Find your own vendor, Buddy!" );
                return;
            }
        }
    }

    /*
    if ( ( victim->carry_number + ( get_obj_number( obj ) / obj->count ) > can_carry_n( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N has $S hands full.", ch, NULL, victim, TO_CHAR );
        return;
    } */

    if ( ( victim->carry_weight + ( get_obj_weight( obj ) / obj->count ) > can_carry_w( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N can't carry that much weight.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( !can_see_obj( victim, obj ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N can't see it.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( IS_OBJ_STAT( obj, ITEM_PROTOTYPE ) && !can_take_proto( victim ) )
    {
        act( AT_PLAIN, "You cannot give that to $N!", ch, NULL, victim, TO_CHAR );
        return;
    }

    separate_obj( obj );
    obj_from_char( obj );
    chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "slip", &skill_slip ) );

    if ( ( number_percent( ) > chance ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&RYou botched...bad. Everyone saw that." );
        act( AT_ACTION, "$n slips $p to $N.", ch, obj, victim, TO_NOTVICT );
        act( AT_ACTION, "$n slips you $p.",   ch, obj, victim, TO_VICT    );
        learn_from_failure( ch, cache_skill( "slip", &skill_slip ) );
        mprog_give_trigger( victim, ch, obj );
    }
    else
    {
        learn_from_success( ch, cache_skill( "slip", &skill_slip ) );
    }

    act( AT_ACTION, "You slip $p to $N.", ch, obj, victim, TO_CHAR    );

    if ( IS_NPC( victim ) ) //Sintaka - Internal echo to NPC for successful slip, to be used with progs
        act( AT_ACTION, "$n slips you something", ch, NULL, victim, TO_VICT );

    obj = obj_to_char( obj, victim );

    /* Vendor Patch */
    if ( IS_NPC( victim ) )
    {
        if ( victim->vendor_data )
        {
            xREMOVE_BIT( obj->extra_flags, ITEM_INVENTORY );
            save_vendor( victim->vendor_data, true );
        }
    }

    return;
}

int calc_effortrate( CHAR_DATA* ch, int ability, int diff )
{
    int rate = 0;
    /*
        Base is (diff)% of maximum movement
    */
    rate = ( ch->max_move / 100 ) * diff;
    /*
        Subtract 1% of max movement for each 5 ability levels
    */
    rate -= ( ( ch->max_move / 100 ) * ( ch->skill_level[ability] / 5 ) );

    /* Avvie bonus */
    if ( ch->skill_level[ability] >= 100 )
        rate /= 4;

    /*
        Cap the range ( 25 to [90% of max move] )
    */
    rate = URANGE( 25, rate, ( int )( ch->max_move * 0.9 ) );
    return rate;
}

int calc_markup( CHAR_DATA* ch, int price )
{
    int value = 0;
    int perc = 0;
    perc = ( ch->skill_level[ENGINEERING_ABILITY] / 5 ) + 30;
    value = ( int )( ( double )( price ) * ( ( double )( 1 ) + ( ( double )( perc ) / ( double )( 100 ) ) ) );
    return value;
}

CMDF do_repopulate( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    int raiseamount = 0, cost = 0;
    bool clancleared = FALSE;
    PLANET_DATA* planet = NULL;

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You have to be on a planet in order to boost population." );
        return;
    }

    if ( IS_NPC( ch ) )
        return;

    raiseamount = number_range( 10, 30 ) + ( ch->skill_level[LEADERSHIP_ABILITY] / 2 );

    if ( planet->governed_by != ch->pcdata->clan )
    {
        ch_println( ch, "%s supports the local governments.", planet->governed_by->name );
        return;
    }

    if ( is_empowered( ch, "withdraw" ) )
        clancleared = TRUE;

    if ( planet->population == planet->max_pop )
    {
        ch_println( ch, "The planet is as populated as it's going to get." );
        return;
    }

    switch ( planet->psize )
    {
        default:
            cost = number_range( 1000, 8000 );
            return;

        case 3:
            cost = number_range( 25000, 45000 );
            return;

        case 2:
            cost = number_range( 10000, 15000 );
            return;

        case 1:
            cost = number_range( 4500, 11200 );
            return;
    }

    if ( clancleared )
    {
        if ( ( ch->pcdata->clan->funds -= cost ) < 0 )
        {
            ch_println( ch, "Your organization cannot afford to do this anymore." );
            return;
        }

        ch_println( ch, "You begin to spread word of the benefits of the planet." );
        planet->population = URANGE( 1, planet->population + raiseamount, planet->max_pop );
        /*if (number_percent( ) > 85 )learn_from_success(ch, gsn_ambassador );*/
        return;
    }
    else
    {
        if ( ( ch->gold -= cost ) < 0 )
        {
            ch_println( ch, "You can't afford to do this anymore." );
            return;
        }

        ch_println( ch, "You begin to spread word of the benefits of the planet." );
        planet->population = URANGE( 1, planet->population + raiseamount, planet->max_pop );
        /*if (number_percent( ) > 85 )learn_from_success(ch, gsn_ambassador );*/
        return;
    }
}
CMDF do_depopulate( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    int raiseamount = 0, cost = 0;
    bool clancleared = FALSE;
    PLANET_DATA* planet = NULL;

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You have to be on a planet in order to lower population." );
        return;
    }

    if ( IS_NPC( ch ) )
        return;

    if ( ch->pcdata->clan )
        if ( is_empowered( ch, "withdraw" ) )
            clancleared = TRUE;

    raiseamount = number_range( 1, 3 ) + ( ch->skill_level[LEADERSHIP_ABILITY] / 10 );

    if ( ( get_clan( ch->name ) ) == NULL )
        raiseamount = ( int )( raiseamount * 0.25 );

    switch ( planet->psize )
    {
        default:
            cost = number_range( 2000, 10000 );
            return;

        case 3:
            cost = number_range( 30000, 50000 );
            return;

        case 2:
            cost = number_range( 15000, 20000 );
            return;

        case 1:
            cost = number_range( 10000, 17500 );
            return;
    }

    if ( clancleared )
    {
        if ( ( ch->pcdata->clan->funds - cost ) < 0 )
        {
            ch_println( ch, "Your organization cannot afford to do this." );
            return;
        }
        else
        {
            ch->pcdata->clan->funds -= cost;
            sql_credits_log( ch->pcdata->clan->name, "do_depopulate", cost * -1, TRUE );
            planet->population = URANGE( 0, planet->population - raiseamount, planet->max_pop );
            ch_println( ch, "You spread rumors about the hardships of the planet!" );
            /*if (number_percent( ) > 85 )learn_from_success(ch, gsn_ambassador );*/
            return;
        }
    }
    else
    {
        if ( ( ch->gold - cost ) < 0 )
        {
            ch_println( ch, "You can't afford to do this." );
            return;
        }
        else
        {
            ch->gold -= cost;

            if ( !IS_NPC( ch ) )
                sql_credits_log( ch->name, "do_depopulate", cost * -1, TRUE );

            planet->population = URANGE( 0, planet->population - raiseamount, planet->max_pop );
            ch_println( ch, "You spread rumors about the hardships of the planet!" );
            /*if (number_percent( ) > 85 )learn_from_success(ch, gsn_ambassador );*/
            return;
        }
    }
}

