}

void buildship_ch_updates( CHAR_DATA* ch, int frame_size )
{
    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_BUILDSHIP ), ch->max_move );

    if ( get_active_droid( ch, DROID_MODE_INDUSTRY ) )
        addDroidExperience( ch, number_range( 75 * frame_size, 125 * frame_size ) );

    learn_slow( ch, cache_skill( "buildship", &skill_buildship ), 4 );
    if ( !IS_NPC(ch) && get_learned_pct( ch, cache_skill( "spacecraft", &skill_spacecraft ) ) == 100 )
        learn_slow( ch, cache_skill( "buildship", &skill_buildship ), 1 );

    long xpgain = UMIN( frame_size, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    gain_exp( ch, apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY ), ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %ld engineering experience.", xpgain );
}

int buildship_complete_new( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* blueprint = get_obj_from_buffer( buffer, "blueprint" );

    char img_name[100];
    char new_blueprint[MIL];

    char *base_name = one_argument( blueprint->blueprint, img_name );
    SHIP_TEMPLATE_DATA* template = find_shiptemplate( img_name );
    if ( template && NULLSTR( base_name ) )
        base_name = template->base_name;

    // Has to happen before we replace blueprint->blueprint
    SET_STRING( blueprint->name, base_name );
    SET_STRING( blueprint->short_descr, base_name );
    SET_STRING( blueprint->description, base_name );

    snprintf( new_blueprint, MIL, "'%s' %s %s", buffer->clan ? buffer->clan->name : ch->name, img_name, base_name );
    SET_STRING( blueprint->blueprint, new_blueprint );

    obj_to_room( blueprint, ch->in_room );
    xCLEAR_BITS( blueprint->wear_flags );
    xSET_BIT( blueprint->extra_flags, ITEM_INDESTRUCTIBLE );

    save_persistent_object( blueprint, true );
    act( AT_ACTION, "$n crafts the frame for a ship!", ch, NULL, NULL, TO_ROOM );
    ch_println( ch, "&z&GYou craft the frame for your ship." );

    buildship_ch_updates( ch, blueprint->value[0] );
    return E_LOTJ_SUCCESS;
}

int buildship_complete_existing( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* frame = get_obj_from_buffer( buffer, "frame" );
    OBJ_DATA* component = get_obj_from_buffer( buffer, "component" );
    int comp_type = component->value[4];
    if ( frame->value[comp_type] == 0 )
    {
        act( AT_ACTION, "Your $p doesn't need any of that.", ch, frame, NULL, TO_CHAR );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "buildship", &skill_buildship ) );
    if ( number_percent( ) > chance )
    {
        act( AT_BLOOD, "&RYou step away from $p, and realize you've done it all wrong...\n", ch, frame, NULL, TO_CHAR );
        act( AT_PLAIN, "$n finishes working on $p.", ch, frame, NULL, TO_ROOM );
        learn_from_failure( ch, cache_skill( "buildship", &skill_buildship ) );
        return E_LOTJ_SUCCESS;
    }

    if ( valid_focus( ch, ENGINEERING_ABILITY ) )
        component->value[2] += ( int )( component->value[2] * .25 );
    frame->value[comp_type] = UMAX( frame->value[comp_type] - component->value[2], 0 );
    int frame_size = frame->value[0];

    if ( frame->value[1] == 0 && frame->value[2] == 0 && frame->value[3] == 0 && frame->value[4] == 0 )
    {
        act( AT_GREEN, "You step away from your finished $p!", ch, frame, NULL, TO_CHAR );
        act( AT_ACTION, "$n steps away from $s finished $p.", ch, frame, NULL, TO_ROOM );
        bug( "%s finished building (%s) in room %d", ch->name, frame->name, ch->in_room->vnum );
        do_fastship( ch, frame->blueprint );
        separate_obj( frame );
        extract_obj( frame );
    }
    else
    {
        ch_println( ch, "&z&GYou finish modifying the ship." );
        act( AT_PLAIN, "$n steps away from $p looking very pleased with $mself.", ch, frame, NULL, TO_ROOM );
        save_persistent_object( frame, true );
    }

    buildship_ch_updates( ch, frame_size );
    return E_LOTJ_SUCCESS;
}

int buildship_work_seconds( CHAR_DATA* ch, OBJ_DATA* blueprint )
{
    double work_seconds = 60;
    if ( blueprint->value[0] >= FRIGATE_SHIP + 1 )
        work_seconds = 120;
    else if ( blueprint->value[0] >= FREIGHTER_SHIP + 1 )
        work_seconds = 90;

    if ( valid_focus( ch, ENGINEERING_ABILITY ) )
        work_seconds -= work_seconds / 3;

    if ( has_feat( ch, cache_skill( "ship building", &skill_ship_building ) ) )
        work_seconds -= work_seconds / 3;

    // Max level droid (6) reduces time by 1/3.
    DROID_DATA* droid = get_active_droid( ch, DROID_MODE_INDUSTRY );
    if ( droid )
    {
        ch_println( ch, "Your construction droid assists you!", ch );
        work_seconds -= work_seconds / 18 * getDroidLevel( droid->exp );
    }
    return (int) work_seconds;
}

CMDF do_buildship( CHAR_DATA* ch, char* argument )
{
    char* syntax = "&zUsage:&C buildship      &z-&w Creates a frame from blueprints you hold.\n&w"
                   "&C       buildship clan &z-&w Creates a frame from blueprints you hold, registered to your clan.\n&w"
                   "&C       buildship <&wship&C> <&whull&C|&wcircuits&C|&wweapons&C|&wengines&C> &z-&w Continue work on a ship.&w";
    char buf[MIL];
    char arg1[MIL];
    char* arg2 = one_argument( argument, arg1 );

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou're going to need a toolkit to do that." );
        return;
    }

    OBJ_DATA* hydrospanner = get_obj_carried_of_type( ch, ITEM_HYDROSPANNER );
    if ( !hydrospanner )
    {
        ch_println( ch, "&RYou're going to need a hydrospanner to do that." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_BUILDSHIP ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    if ( NULLSTR( arg1 ) || !str_cmp( arg1, "clan" ) )
    {
        OBJ_DATA* blueprint = get_eq_char( ch, WEAR_HOLD );
        if ( !blueprint || blueprint->item_type != ITEM_BLUEPRINT )
        {
            if ( NULLSTR( arg1 ) )
                ch_println( ch, syntax );
            else
                ch_println( ch, "&RYou're not holding any blueprints." );
            return;
        }

        if ( !xIS_SET( ch->in_room->flags, ROOM_GARAGE ) )
        {
            ch_println( ch, "&RYou need to be in a garage to make ships." );
            return;
        }

        if ( !xIS_SET( ch->in_room->flags, ROOM_SAVEEQ ) )
        {
            ch_println( ch, "&RThis garage isn't advanced enough to build a ship in." );
            return;
        }

        char img_name[MIL];
        one_argument( blueprint->blueprint, img_name );
        SHIP_TEMPLATE_DATA* template = find_shiptemplate( img_name );
        if ( !template )
        {
            ch_println( ch, "That schematic is too ruined to understand. (Please contact staff.)" );
            return;
        }

        if ( template->era_locked && sysdata.era >= 1 && sysdata.era <= 4 && !ext_is_empty( &template->eras_bv ) && !xIS_SET( template->eras_bv, (sysdata.era - 1) ) )
        {
            ch_println( ch, "You're pretty sure you can't get the parts to frame this ship." );
            bug ( "%s: %s trying to build an era-locked ship from template %s (blueprint vnum %d).", FUNC, ch->name, template->shortname, blueprint->pIndexData ? blueprint->pIndexData->vnum : 0 );
            return;
        }

        CLAN_DATA* clan = NULL;
        if ( !NULLSTR( blueprint->obj_clan ) )
        {
            clan = get_clan( blueprint->obj_clan );
            if ( !clan )
            {
                ch_println( ch, "&RThe organization which owns this blueprint doesn't seem to exist anymore." );
                return;
            }
        }
        else if ( !str_cmp( arg1, "clan" ) )
        {
            if ( !IS_CLANNED( ch ) )
            {
                ch_println( ch, "&RYou're not in a clan." );
                return;
            }
            clan = ch->pcdata->clan;
        }

        if ( template->classtype < ch->in_room->minshipclass )
        {
            ch_println( ch, "&RThis garage does not have the infrastructure to build ships that small.&w" );
            return;
        }

        if ( template->classtype > ch->in_room->maxshipclass )
        {
            ch_println( ch, "&RThis garage is not large enough to build that ship in.&w" );
            return;
        }

        if ( template->classtype >= FRIGATE_SHIP && !clan )
        {
            ch_println( ch, "&RCapital ships can only be owned by clans. Use 'buildship clan'.&w" );
            return;
        }

        // Check whether the room fits the ship. Use hangar size first if relevant, then check room settings.
        HANGAR_DATA* hangar = NULL;
        SHIP_DATA* in_ship = ship_from_hangar( ch->in_room );
        if ( in_ship )
        {
            hangar = get_hangar_room( in_ship, ch->in_room );
            if ( hangar && get_hangar_free( hangar ) < get_shipclass_size( template->classtype ) )
            {
                ch_println( ch, "There is not enough room to build that here." );
                return;
            }
        }
        if ( !hangar && !room_fits_ship( ch->in_room, get_shipclass_size( template->classtype ) ) )
        {
            ch_println( ch, "There is not enough room to build that here." );
            return;
        }

        if ( IS_AFFECTED( ch, AFF_HIDE ) )
            do_visible( ch, "-noalert" );
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, buildship_work_seconds( ch, blueprint ), buildship_complete_new, buildship_abort, FUNC );
        timer->comms_interrupt = false;
        add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
        add_obj_to_buffer( timer->buffer, "hydrospanner", hydrospanner );
        add_obj_to_buffer( timer->buffer, "blueprint", blueprint );
        timer->buffer->clan = clan;
        ch_println( ch, "&GYou begin working on your new ship." );
        act( AT_PLAIN, "$n pulls out some blueprints and starts building a ship.", ch, NULL, argument, TO_ROOM );
        snprintf( buf, MSL, "is laying down a new ship's frame." );
        action_set( ch, NULL, buf, NULL, 0 );
        return;
    }

    int comp_type;
    if ( !str_cmp( arg2, "hull" ) )
        comp_type = 1;
    else if ( !str_cmp( arg2, "circuits" ) )
        comp_type = 2;
    else if ( !str_cmp( arg2, "weapons" ) )
        comp_type = 3;
    else if ( !str_cmp( arg2, "engines" ) || !str_cmp( arg2, "engine" ) )
        comp_type = 4;
    else
    {
        ch_println( ch, syntax );
        return;
    }

    OBJ_DATA* frame = get_obj_list_rev( ch, arg1, ch->in_room->last_content );
    if ( !frame )
    {
        ch_println( ch, "You don't see a ship like that nearby to work on." );
        return;
    }

    if ( frame->value[comp_type] <= 0 )
    {
        act( AT_ACTION, "Your $p doesn't need any more of that.", ch, frame, NULL, TO_CHAR );
        return;
    }

    OBJ_DATA* component = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( obj->item_type != ITEM_DURASTEEL && obj->item_type != ITEM_CIRCUIT )
            continue;

        // value5 == 1 on durasteel or circuit is an indicator that it's a shipbuilding component
        if ( obj->value[5] < 1 )
            continue;

        // value4 on durasteel or circuit specifies which component type
        if ( obj->value[4] != comp_type )
            continue;

        component = obj;
        break;
    }
    if ( !component )
    {
        ch_println( ch, "You don't have a component like that." );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_HIDE ) )
        do_visible( ch, "-noalert" );
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, buildship_work_seconds( ch, frame ), buildship_complete_existing, buildship_abort, FUNC );
    timer->comms_interrupt = false;
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "hydrospanner", hydrospanner );
    add_obj_to_buffer( timer->buffer, "frame", frame );
    add_consumable_to_buffer( timer->buffer, "component", component, "Component" );
    ch_println( ch, "&GYou begin working on your new ship." );
    act( AT_PLAIN, "$n takes $s tools and starts to work on $p.", ch, frame, NULL, TO_ROOM );
    snprintf( buf, MSL, "is working on %s.", frame->short_descr );
    action_set( ch, NULL, buf, NULL, 0 );
}

