CMDF do_imbue( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Imbue what?" );
        return;
    }

    OBJ_DATA* weapon = get_obj_carry( ch, argument );
    if ( !weapon )
    {
        ch_println( ch, "You have nothing like that." );
        return;
    }

    //Cortosis should only be able to be applied to forcepikes and vibroblades.
    if ( weapon->item_type != ITEM_WEAPON )
    {
        ch_println( ch, "&wThat isn't a weapon!" );
        return;
    }

    if ( weapon->value[3] != WEAPON_VIBRO_BLADE )
    {
        if ( weapon->value[3] != WEAPON_FORCE_PIKE )
        {
            ch_println( ch, "&wYou can only imbue melee weapons with cortosis." );
            return;
        }
    }

    if ( xIS_SET( weapon->extra_flags, ITEM_CORTOSIS ) )
    {
        ch_println( ch, "&wThis weapon is already imbued with cortosis!" );
        return;
    }

    OBJ_DATA* ore = NULL;
    for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( !ore && obj->item_type == ITEM_CRYSTALORE && obj->value[3] == 1 )
            ore = obj;
    }
    if ( !ore )
    {
        ch_println( ch, "You don't have any cortosis ore to imbue with." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "You don't have a toolkit to do the work with." );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 90, imbue_complete, imbue_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "weapon", weapon );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "ore", ore, "Cortosis Ore" );

    ch_println( ch, "&wYou take your tools and begin to imbue %s", weapon->short_descr );
    print_buffer_objects( timer->buffer, ch );
    act( AT_ACTION, "$n takes $s tools and begins to work on a weapon.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is imbuing a weapon.", NULL, 0 );
}

