int repairdoor_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    EXIT_DATA* pexit = find_door( ch, buffer->str1, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "Your work seems to have left without you!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !xIS_SET( pexit->flags, EX_BASHED ) && !xIS_SET( pexit->flags, EX_BREACHED ) )
    {
        ch_println( ch, "Seems like someone fixed the %s door before you could.", pexit->keyword );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chances = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, cache_skill( "repairdoor", &skill_repairdoor ) );
    if ( number_percent ( ) > chances )
    {
        ch_println( ch, "&RAfter all that, the door still seems broken." );
        learn_from_failure( ch, cache_skill( "repairdoor", &skill_repairdoor ) );
        return E_LOTJ_SUCCESS;
    }

    act( AT_ACTION, "You finish repairing the $d.", ch, pexit->keyword, NULL, TO_CHAR );
    act( AT_ACTION, "$n finishes repairing the $d.", ch, pexit->keyword, NULL, TO_ROOM );
    xREMOVE_BIT( pexit->flags, EX_BASHED );
    xREMOVE_BIT( pexit->flags, EX_BREACHED );
    learn_slow( ch, cache_skill( "repairdoor", &skill_repairdoor ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_repairdoor( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Repair which door?" );
        return;
    }

    EXIT_DATA* pexit = find_door( ch, argument, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "No such door nearby." );
        return;
    }

    if ( !xIS_SET( pexit->flags, EX_ISDOOR ) )
    {
        ch_println( ch, "That is not a door." );
        return;
    }

    if ( !xIS_SET( pexit->flags, EX_BASHED ) && !xIS_SET( pexit->flags, EX_BREACHED ) )
    {
        ch_println( ch, "That door is not damaged." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "You'll need a toolkit before you start working." );
        return;
    }

    OBJ_DATA* durasteel = get_obj_carried_of_type( ch, ITEM_DURASTEEL );
    if ( !durasteel )
    {
        ch_println( ch, "You'll need a piece of durasteel to replace the missing metal." );
        return;
    }

    int seconds = 60;
    if ( xIS_SET( pexit->flags, EX_BREACHED ) )
        seconds = 105;
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, seconds, repairdoor_complete, repairdoor_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "durasteel", durasteel, "Durasteel" );

    ch_println( ch, "&wYou take your tools and start repairing the %s&w.", NULLSTR( pexit->keyword ) ? "door" : pexit->keyword );
    print_buffer_objects( timer->buffer, ch );
    act( AT_ACTION, "$n takes $s tools and starts repairing the $d.", ch, NULL, pexit->keyword, TO_ROOM );
    action_set( ch, NULL, strfmt("is fixing the %s door.", !NULLSTR( pexit->keyword ) ? pexit->keyword : get_dir_name( pexit->vdir )), NULL, 0 );
}

