    learn_slow( ch, cache_skill( "repairhatch", &skill_repairhatch ), 2 );
    return E_LOTJ_SUCCESS;
}

int repair_hatch_complete_ship( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SHIP_DATA* ship = buffer->ship;
    if ( !valid_ship( ship ) || ship->in_room != ch->in_room )
    {
        ch_println( ch, "That ship doesn't seem to be here anymore." );
