        ch_println( ch, "Seems like someone fixed %s before you could.", ship->name );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chances = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, cache_skill( "repairhatch", &skill_repairhatch ) );
    if ( number_percent ( ) > chances )
    {
        ch_println( ch, "&RYou messed it up. Better start again." );
        learn_from_failure( ch, cache_skill( "repairhatch", &skill_repairhatch ) );
        return E_LOTJ_SUCCESS;
    }

    act( AT_ACTION, "You finish repairing $ts hatch.", ch, ship->name, NULL, TO_CHAR );
