    xREMOVE_BIT( ship->flags, SHIP_BROKEN_HATCH );
    learn_slow( ch, cache_skill( "repairhatch", &skill_repairhatch ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_repair_hatch( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Repair which hatch?" );
        return;
    }

    OBJ_DATA* hull = NULL;
    for ( OBJ_DATA* obj = ch->first_carrying; obj ; obj = obj->next_content )
    {
        if ( !hull && obj->item_type == ITEM_DURASTEEL && obj->value[5] >= 1 )
            hull = obj;
    }
    if ( !hull )
    {
        ch_println( ch, "You'll need a piece of hull to replace the missing metal." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "You'll need a toolkit before you start working." );
        return;
    }

    STRUCTURE_DATA* stru = find_struct_entrance_in_room( ch->in_room, argument );
    if ( stru )
    {
        if ( !xIS_SET( stru->exit_flags, EX_BREACHED ) )
        {
            ch_println( ch, "It doesn't appear to need its door fixed." );
            return;
        }

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, repair_hatch_complete_structure, repair_hatch_abort, FUNC );
        timer->buffer->structure = structure_to_ref( stru );
        add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
        add_consumable_to_buffer( timer->buffer, "hull", hull, "Hull" );

        act( AT_ACTION, "$n takes $s tools and starts repairing $t's door.\n", ch, stru->name, NULL, TO_ROOM );
        ch_println( ch, "You start working on fixing %s's door.", stru->name );
        print_buffer_objects( timer->buffer, ch );
        action_set( ch, NULL, strfmt("is fixing %s's door.", stru->name), NULL, 0 );
        return;
    }

    SHIP_DATA* ship = ship_in_room( ch->in_room, argument );
    if ( ship )
    {
        if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED )
        {
            ch_println( ch, "&RThe ship needs to land before you can repair the hatch!" );
            return;
        }

        if ( !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            ch_println( ch, "It doesn't appear to need its hatch fixed." );
            return;
        }

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 75, repair_hatch_complete_ship, repair_hatch_abort, FUNC );
        timer->buffer->ship = ship;
        add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
        add_consumable_to_buffer( timer->buffer, "hull", hull, "Hull" );

        act( AT_ACTION, "$n takes $s tools and starts repairing $ts hatch.", ch, ship->name, NULL, TO_ROOM );
        ch_println( ch, "You start working on fixing %ss hatch.", ship->name );
        action_set( ch, NULL, strfmt("is fixing %s's hatch.", ship->name), NULL, 0 );
        return;
    }
    ch_println( ch, "No ship or structure like that nearby." );
}

int makecamera_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are interrupted and fail to finish your work." );
    return E_LOTJ_SUCCESS;
}

int makecamera_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* lens = get_obj_from_buffer( buffer, "lens" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* duraplast = get_obj_from_buffer( buffer, "duraplast" );

    char buf[MSL];
    int duramod = 0;
    double value = 0;

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_DATAPAD );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    value += lens->pIndexData->cost;
    value += super->pIndexData->cost;
    value += circuit->pIndexData->cost;
    value += battery->pIndexData->cost;
    value += duraplast->pIndexData->cost;
    duramod = duraplast->value[0]; //Duraplast's quality modifier

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ESPIONAGE_ABILITY, EFFORT_DATAPAD ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makecamera", &skill_makecamera ) ) ) ;
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou hold up your newly created camera..." );
        ch_println( ch, "&RIt explodes into a ball of fire!" );
        learn_from_failure( ch, cache_skill( "makecamera", &skill_makecamera ) );
        return E_LOTJ_SUCCESS;
    }

    value *= 1 + ( duramod / 100. ); //Increase value by duraplast modifier percentage
    OBJ_DATA* obj = create_object( pObjIndex, ch->top_level );
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    strlcpy( buf, stripclr( arg ), MSL );
    strlcat( buf, " camera", MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " was carelessly misplaced here.", MSL );
    SET_STRING( obj->description, buf );
    obj->item_type = ITEM_CAMERA;
    obj->cost = calc_markup( ch, ( int ) value );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created camera.&w" );
    act( AT_PLAIN, "$n finishes crafting a camera.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 12, ( exp_level( ch->skill_level[ESPIONAGE_ABILITY] + 1 ) - exp_level( ch->skill_level[ESPIONAGE_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ESPIONAGE_ABILITY );
    gain_exp( ch, xpgain, ESPIONAGE_ABILITY, TRUE );
    ch_println( ch, "You gain %d espionage experience.", xpgain );
    learn_from_success( ch, cache_skill( "makecamera", &skill_makecamera ) );
    return E_LOTJ_SUCCESS;
}

CMDF do_makecamera( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMakecamera <&wname&C>" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make this." );
        return;
    }

    OBJ_DATA* lens = get_obj_carried_of_type( ch, ITEM_LENS );
    if ( !lens )
    {
        ch_println( ch, "You need a lens for the camera." );
        return;
    }

    OBJ_DATA* oven = get_obj_carried_of_type( ch, ITEM_OVEN );
    if ( !oven )
    {
        ch_println( ch, "&RYou need an oven to heat the duraplast." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a battery to power the camera." );
        return;
    }

    OBJ_DATA* super = get_obj_carried_of_type( ch, ITEM_SUPERCONDUCTOR );
    if ( !super )
    {
        ch_println( ch, "&RYou need a superconductor to regulate the current." );
        return;
    }

    OBJ_DATA* duraplast = get_obj_carried_of_type( ch, ITEM_DURAPLAST );
    if ( !duraplast )
    {
        ch_println( ch, "&RYou need some duraplast for the camera body." );
        return;
    }

    OBJ_DATA* circuit = get_obj_carried_of_type( ch, ITEM_CIRCUIT );
    if ( !circuit )
    {
        ch_println( ch, "&RYou need a circuit to process the video feed." );
        return;
    }

    if ( calc_effortrate( ch, ESPIONAGE_ABILITY, EFFORT_DATAPAD ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    int seconds = 60;
    if ( valid_focus( ch, ESPIONAGE_ABILITY ) )
        seconds -= ( int )( seconds * .2 );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, seconds, makecamera_complete, makecamera_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_obj_to_buffer( timer->buffer, "oven", oven );
    add_consumable_to_buffer( timer->buffer, "duraplast", duraplast, "Duraplast" );
    add_consumable_to_buffer( timer->buffer, "battery", battery, "Battery" );
    add_consumable_to_buffer( timer->buffer, "circuit", circuit, "Circuit" );
    add_consumable_to_buffer( timer->buffer, "super", super, "Superconductor" );
    add_consumable_to_buffer( timer->buffer, "lens", lens, "Lens" );

    ch_println( ch, "&GYou begin the long process of making a camera." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and a lens and begins to piece something together.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is building a camera.", NULL, 0 );
}

