{
    ch_println( ch, "&WYour thoughts turn from pondering to the immediate circumstances at hand." );
    act( AT_ACTION, "$n blinks, looking about.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int ponder_complete( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    int chances = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, cache_skill( "ponder", &skill_ponder ) );
    chances /= chances == 100 ? 2 : 5;
    if ( number_percent() > chances )
    {
        ch_println( ch, "&WYou ponder for some time, but fail to figure anything out." );
        act( AT_ACTION, "$n shakes $s head about something.", ch, NULL, NULL, TO_ROOM );
        learn_slow( ch, cache_skill( "ponder", &skill_ponder ), 3 );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "&WYou ponder for some time, and things seem clearer." );
    act( AT_ACTION, "$n seems pleased by something.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "ponder", &skill_ponder ), 2 );

    int sci_level = IS_NPC( ch ) ? ch->top_level : ch->skill_level[SCIENCE_ABILITY];
    if ( sci_level > 30 )
    {
        ch_println( ch, "&WYou have already pondered life, now you must study." );
        return E_LOTJ_SUCCESS;
    }

    long xpgain = UMIN( 10000, ( exp_level( ch->skill_level[SCIENCE_ABILITY] + 1 ) - exp_level( ch->skill_level[SCIENCE_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, SCIENCE_ABILITY );
    gain_exp( ch, xpgain, SCIENCE_ABILITY, TRUE );
    ch_println( ch, "&wYou gain %d science experience.", xpgain );
    return E_LOTJ_SUCCESS;
}

