int study_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    SKILL_DATA* skill = skill_from_id( buffer->num1 );
    bool usingbook = FALSE;
    if ( !skill )
    {
        ch_println( ch, "&RYou struggle to glean any useful knowledge." );
        bug( "%s: character %s trying to learn skill %d, which doesn't exist.", FUNC, ch->name, buffer->num1 );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    OBJ_DATA* book = get_obj_from_buffer( buffer, "book" );
    if ( book )
    {
        usingbook = TRUE;

        /*bug("Learning skill");*/
        /* Check their skill level versus level of the subject */
        if ( ch->skill_level[skill->guild] < skill->min_level )
        {
            ch_println( ch, "&WYou are not ready to learn this skill." );
            /*return; Taken out to let people level off books, and then learn the skill*/
        }

        if ( get_learned_pct( ch, skill ) > book->value[3]  /*|| skill->min_level > obj->value[3] */ && book->value[2] < 120 )
        {
            ch_println( ch, "&WYou can learn no more from this." );
            return E_LOTJ_SUCCESS;
        }

        bool bonus = FALSE;

        if ( ch->skill_level[skill->guild] < book->value[2] || book->value[2] == 150 )
            bonus = TRUE;

        if ( bonus && ch->skill_level[skill->guild] >= skill->min_level * 2.5 )
        {
            ch_println( ch, "That skill is too low level for you to gain EXP from." );
            bonus = FALSE;
        }

        if ( skill->guild == FORCE_ABILITY && ch->skill_level[FORCE_ABILITY] <= 1 )
        {
            ch_println( ch, "You cannot understand this. Maybe if a teacher taught you more about the force first..." );
            return E_LOTJ_SUCCESS;
        }

        /* Gain EXP unless your level is 5 levels greater than the skill itself */
        /*  if ( skill->min_level < ( ch->skill_level[skill->guild] + 5 ) )
                bonus = FALSE;*/
        if ( bonus )
        {
            /*bug("%s gaining exp in %d from studying.", ch->name, skill->guild );*/
            long xpgain = UMIN( URANGE( 1, number_range( 10000, skill->min_level * 500 ), 75000 ), ( exp_level( ch->skill_level[skill->guild] + 1 ) - exp_level( ch->skill_level[skill->guild] ) ) ) / 2;
            xpgain = apply_xp_sink( ch, xpgain, skill->guild );
            xpgain /= 2;
            gain_exp( ch, xpgain, skill->guild, FALSE );
            ch_println( ch, "&wYou gain %d %s experience.", xpgain, flag_value_name( ability_name, skill->guild ) );
        }
    }

    int chances = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, skill );

    if ( chances == 0 && !IS_NPC( ch ) && ch->skill_level[skill->guild] >= skill->min_level )
    {
        if ( !usingbook )
            set_learned_pct( ch, skill, 1 );

        chances = 10;
    }

    if ( number_percent( ) > chances + get_curr_int( ch ) )
    {
        ch_println( ch, "&WYou study it for some time, but fail to learn anything about it." );
        act( AT_ACTION, "$n finishes studying.", ch, NULL, NULL, TO_ROOM );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "&WAfter some time studying you feel you know more." );
    act( AT_ACTION, "$n finishes studying.", ch, NULL, NULL, TO_ROOM );

    /* Can't learn the skill unless you're the right level. Lets books teach exp too */
    if ( ch->skill_level[skill->guild] >= skill->min_level )
    {
        if ( !IS_NPC(ch) && get_learned_pct( ch, skill ) >= ch->skill_level[SCIENCE_ABILITY] && skill->guild == SCIENCE_ABILITY )
            ch_println( ch, "You must raise your science level before learning more about this knowledge." );
        else if ( number_percent() > chances - ( get_curr_int( ch ) / 3 ) )
        {
            if ( !usingbook )
                learn_from_success( ch, skill );
            else
                learn_from_success( ch, cache_skill( "education", &skill_education ) );
        }
    }

    if ( ch->skill_level[SCIENCE_ABILITY] < 105 )
    {
        long xpgain = UMIN( 10000, ( exp_level( ch->skill_level[SCIENCE_ABILITY] + 1 ) - exp_level( ch->skill_level[SCIENCE_ABILITY] ) ) ) / 2;
        xpgain = apply_xp_sink( ch, xpgain, SCIENCE_ABILITY );

        //leadership bonus, only applies when studying objects/spacecraft
        if ( valid_focus( ch, SCIENCE_ABILITY ) && !usingbook )
            xpgain = ( int )( xpgain * 1.5 );

        gain_exp( ch, xpgain, SCIENCE_ABILITY, FALSE );
        ch_println( ch, "&wYou gain %d science experience.", xpgain );
    }

    //Ralen moving the learn success for study out of the restrictive part about using datachips. Should be able to study anything and gain %.
    learn_from_success( ch, cache_skill( "study", &skill_study ) );
    /*      else
                ch_println( ch, "You will need to use HYPOTHESIZE to progress in levels." );*/
    return E_LOTJ_SUCCESS;
}

CMDF do_study( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "You must study an object or a ship." );
        return;
    }

    SKILL_DATA* learn_skill = NULL;
    OBJ_DATA* book = NULL;

    OBJ_DATA* obj = get_obj_here( ch, argument );

    if ( !obj )
        obj = get_obj_carry( ch, argument );

    if ( obj )
    {
        switch ( obj->item_type )
        {
            /* electronics */
            case ITEM_DATAPAD:
            case ITEM_CIRCUIT:
            case ITEM_SUPERCONDUCTOR:
            case ITEM_BLANKCIRCUIT:
            case ITEM_CABLE:
                learn_skill = cache_skill( "electronics", &skill_electronics );
                break;

            /* communications */
            case ITEM_MICROPHONE:
            case ITEM_COMLINK:
                learn_skill = cache_skill( "communication", &skill_communication );
                break;

            /* advanced electronics */
            case ITEM_CAMERA:
            case ITEM_MONITOR:
            case ITEM_CUTTER:
                learn_skill = cache_skill( "advanced electronics", &skill_advanced_electronics );
                break;

            /* destruction */
            case ITEM_WEAPON:
            case ITEM_GRENADE:
            case ITEM_LANDMINE:
            case ITEM_BOMB:
            case ITEM_AMMO:
                learn_skill = cache_skill( "destruction", &skill_destruction );
                break;

            case ITEM_BOOK:
                if ( obj->value[1] > 0 )
                {
                    book = obj;
                    learn_skill = skill_from_name( book->blueprint );
                }
                else
                    learn_skill = cache_skill( "education", &skill_education );
                break;

            /* medical */
            case ITEM_VIAL:
            case ITEM_PILL:
            case ITEM_SYRINGE:
            case ITEM_MEDPAC:
                learn_skill = cache_skill( "medical", &skill_medical );
                break;

            /* forensics */
            case ITEM_CORPSE_NPC:
            case ITEM_CORPSE_PC:
            case ITEM_BLOODSTAIN:
                learn_skill = cache_skill( "forensics", &skill_forensics );
                break;

            /* construction */
            case ITEM_FURNITURE:
            case ITEM_OIL:
            case ITEM_LENS:
            case ITEM_DURASTEEL:
            case ITEM_DURAPLAST:
            case ITEM_HYDROSPANNER:
            case ITEM_TOOLKIT:
            case ITEM_MIRROR:
            case ITEM_FOUNTAIN:
                learn_skill = cache_skill( "construction", &skill_construction );
                break;

            /* equipment */
            case ITEM_BINDING:
            case ITEM_HOLSTER:
            case ITEM_ARMOR:
            case ITEM_UNDERLAY:
            case ITEM_FABRIC:
                learn_skill = cache_skill( "equipment", &skill_equipment );
                break;

            /* transportation */
            case ITEM_DRINK_CON:
            case ITEM_CONTAINER:
                learn_skill = cache_skill( "transportation", &skill_transportation );
                break;

            /* cybernetics */
            case ITEM_CYBER:
                learn_skill = cache_skill( "enhancement", &skill_enhancement );
                break;

            /* guidance */
            case ITEM_BEACON:
            case ITEM_EJECTBEACON:
            case ITEM_LIGHT:
                learn_skill = cache_skill( "guidance", &skill_guidance );
                break;

            /* chemistry */
            case ITEM_ASHES:
            case ITEM_CHEMICAL:
            case ITEM_FIRE:
                learn_skill = cache_skill( "chemistry", &skill_chemistry );
                break;

            /* data */
            case ITEM_NOTE:
            case ITEM_PERMIT:
                learn_skill = cache_skill( "data", &skill_data );
                break;

            /* narcotics */
            case ITEM_RAWSPICE:
            case ITEM_SPICE:
                learn_skill = cache_skill( "narcotics", &skill_narcotics );
                break;

            /* edibles */
            case ITEM_FOOD:
                learn_skill = cache_skill( "edibles", &skill_edibles );
                break;

            /* minerals */
            case ITEM_CRYSTALORE:
            case ITEM_CRYSTAL:
                learn_skill = cache_skill( "minerals", &skill_minerals );
                break;

            /* machines */
            case ITEM_DROID_PART:
            case ITEM_DEVICE:
            case ITEM_DROID_CORPSE:
                learn_skill = cache_skill( "machines", &skill_machines );
                break;

            /* spacecraft */
            case ITEM_SPACECRAFT:
            case ITEM_BLUEPRINT:
                learn_skill = cache_skill( "spacecraft", &skill_spacecraft );
                break;

            default:
                ch_println( ch, "&WYou wouldn't learn much from that." );
                return;

        }
        ch_println( ch, "&WYou begin to study %s&W, trying to learn more about it.", obj->short_descr );
        act( AT_ACTION, "&W$n begins to study $t &Wquite intently.", ch, obj->short_descr, NULL, TO_ROOM );
        action_set( ch, NULL, strfmt("is studying %s&w.", obj->short_descr), NULL, 0 );
    }
    else
    {
        SHIP_DATA* ship = ship_in_room( ch->in_room, argument );
        if ( !ship )
        {
            ch_println( ch, "&WYou don't see anything like that nearby to study." );
            return;
        }
        learn_skill = cache_skill( "spacecraft", &skill_spacecraft );
        ch_println( ch, "&WYou begin to study %s&W, trying to learn more about it.", ship->name );
        act( AT_ACTION, "$n begins to study a spacecraft.", ch, NULL, NULL, TO_ROOM );
        action_set( ch, NULL, strfmt("is studying %s.", ship->name), NULL, 0 );
    }

    if ( !learn_skill )
    {
        ch_println( ch, "&WYou wouldn't learn much from that." );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 45, study_complete, study_abort, FUNC );

    if ( learn_skill != NULL )
        timer->buffer->num1 = learn_skill->id;

    if ( book )
        add_obj_to_buffer( timer->buffer, "book", book );

    return;
}

