int hypothesize_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* obj = get_obj_from_buffer( buffer, "book" );
    char buf[MSL];
    SKILL_DATA* skill = skill_from_id( buffer->num1 );

    if ( !skill )
    {
        bug( "%s: could not find skill", FUNC );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int chances = ( int ) get_learned_pct( ch, cache_skill( "hypothesize", &skill_hypothesize ) );
    if ( number_percent() > chances )
    {
        ch_println( ch, "Drat! Your ideas and concepts are all over the place! Better start from the top." );
        return E_LOTJ_SUCCESS;
    }

    SET_STRING( obj->blueprint, skill->name );
    /* they can only learn from the book as high as the writers education */
    obj->value[3] = ( int ) get_learned_pct( ch, cache_skill( "education", &skill_education ) );
    obj->value[0] = 1;
    /* Writers level is saved as v2, lets us discern later in finalizing it...*/
    obj->value[2] = ( int ) ch->skill_level[SCIENCE_ABILITY];

    /* Provide different colors for different levels of the maker */
    if ( ch->skill_level[SCIENCE_ABILITY] >= 150 )
        snprintf( buf, MSL, "&zA datachip labelled '&R%s hypothesis&z'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 140 )
        snprintf( buf, MSL, "&cA datachip labelled '&w%s hypothesis&c'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 120 )
        snprintf( buf, MSL, "&CA datachip labelled '&W%s hypothesis&C'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 110  )
        snprintf( buf, MSL, "&YA datachip labelled '&G%s hypothesis&Y'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] < 110  )
        snprintf( buf, MSL, "&WA datachip labelled '&G%s hypothesis&W'", skill->name );

    SET_STRING( obj->short_descr, buf );

    /* Provide different colors for different levels of the maker */
    if ( ch->skill_level[SCIENCE_ABILITY] >= 150 )
        snprintf( buf, MSL, "&zA datachip labelled '&R%s&z' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 140 )
        snprintf( buf, MSL, "&cA datachip labelled '&w%s&c' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 120 )
        snprintf( buf, MSL, "&CA datachip labelled '&W%s&C' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 110  )
        snprintf( buf, MSL, "&YA datachip labelled '&G%s&Y' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] < 110  )
        snprintf( buf, MSL, "&WA datachip labelled '&G%s&W' lies here.", skill->name );

    SET_STRING( obj->description, buf );
    /* fix name */
    snprintf( buf, MSL, "datachip hypothesis %s", skill->name );
    SET_STRING( obj->name, buf );
    /* now subtract their distance to level 150 */
    chances = 150;
    chances -= ch->skill_level[SCIENCE_ABILITY];

    if ( chances > 0 )
        obj->value[3] -= chances;

    /*
        cost is made by a combination of education, science level
        and the skill you are writing about       -Orion
    */
    obj->cost = ( ch->skill_level[SCIENCE_ABILITY]
                  + get_learned_pct( ch, cache_skill( "education", &skill_education ) )
                  + get_learned_pct( ch, skill ) )
                * ch->skill_level[SCIENCE_ABILITY] * 500;
    /* This is a hypothesis */
    obj->value[1] = 0;
    /*    ch_println( ch, "You finish writing the hypothesis into the datachip." );*/
    learn_slow( ch, cache_skill( "education", &skill_education ), 3 );

    if ( ch->skill_level[SCIENCE_ABILITY] > 90 && ch->skill_level[SCIENCE_ABILITY] < 120 )
    {
        learn_slow( ch, cache_skill( "education", &skill_education ), 2 );
        long xpgain = UMIN( 10000, ( exp_level( ch->skill_level[SCIENCE_ABILITY] + 1 ) - exp_level( ch->skill_level[SCIENCE_ABILITY] ) ) ) / 2;
        xpgain = apply_xp_sink( ch, xpgain, SCIENCE_ABILITY );
        gain_exp( ch, xpgain, SCIENCE_ABILITY, TRUE );
        ch_println( ch, "You gain %d science experience.", xpgain );
    }

    ch_println( ch, "You finish writing the hypothesis." );
    act( AT_ACTION, "$n finishes writing in $s datachip.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "hypothesize", &skill_hypothesize ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_hypothesize( CHAR_DATA* ch, char* argument )
{
    SKILL_DATA* skill = NULL;

    if ( IS_NPC( ch ) )
        return;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "You must hypothesize about a skill." );
        return;
    }

    /* Redundancy to correct manipulative builders :D  -Orion */
    OBJ_DATA* obj = get_eq_char( ch, WEAR_HOLD );
    if ( !obj
            /* book? */
            || obj->item_type != ITEM_BOOK
            /* written in? */
            || obj->value[0] > 0
            /* is this a finished book? */
            || obj->value[2] > 0 )
    {
        ch_println( ch, "You need to hold a blank data source to write your hypothesis into." );
        return;
    }

    /* search for the skill, the logical way. */
    skill = skill_from_name( argument );

    if ( skill == NULL )
    {
        ch_println( ch, "You've never even HEARD of that before!" );
        return;
    }

    if ( skill->type == SKILL_FEAT )
    {
        ch_println( ch, "You can't write a hypothesis on that." );
        return;
    }

    if ( get_learned_pct( ch, skill ) < 100 )
    {
        ch_println( ch, "You must learn more about the topic before you can write the hypothesis." );
        return;
    }

    /* Correlation between knowledges and writing the hypothesis */
    switch ( skill->guild )
    {
        case COMBAT_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) < 100 )
            {
                ch_println( ch, "You must learn about destruction more in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case PILOTING_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "spacecraft", &skill_spacecraft ) ) < 100 )
            {
                ch_println( ch, "You must learn more about spacecraft in order to write a hypothesis on that subject." );
                return;
            }

            break;

        case ENGINEERING_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "construction", &skill_construction ) ) < 100 )
            {
                ch_println( ch, "You must learn more about construction in order to write a hypothesis on that subject." );
                return;
            }

            break;

        case HUNTING_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "guidance", &skill_guidance ) ) < 100 )
            {
                ch_println( ch, "You must learn more about guidance in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case SMUGGLING_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 )
            {
                ch_println( ch, "You must learn more about equipment in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "spacecraft", &skill_spacecraft ) ) < 100 )
            {
                ch_println( ch, "You must learn more about spacecraft in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case ESPIONAGE_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 )
            {
                ch_println( ch, "You must learn more about equipment in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "electronics", &skill_electronics ) ) < 100 )
            {
                ch_println( ch, "You must learn more about electronics in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "data", &skill_data ) ) < 100 )
            {
                ch_println( ch, "You must learn more about data in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case SLICER_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 )
            {
                ch_println( ch, "You must learn more about equipment in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "electronics", &skill_electronics ) ) < 100 )
            {
                ch_println( ch, "You must learn more about electronics in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "advanced electronics", &skill_advanced_electronics ) ) < 100 )
            {
                ch_println( ch, "You must learn more about advanced electronics in order to write a hypothesis on this subject." );
                return;
            }

            if ( get_learned_pct( ch, cache_skill( "data", &skill_data ) ) < 100 )
            {
                ch_println( ch, "You must learn more about data in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case FORCE_ABILITY:
            ch_println( ch, "If you want to teach someone about the force, get an apprentice!" );
            return;

        case MEDIC_ABILITY:
            if ( get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) < 100 )
            {
                ch_println( ch, "You must learn more about medical in order to write a hypothesis on this subject." );
                return;
            }

            break;

        case SCIENCE_ABILITY:
        case LEADERSHIP_ABILITY:
        default:
            break;
    }

    int dur = URANGE( 8, 150 - ch->skill_level[SCIENCE_ABILITY], 40 );
    action_set( ch, NULL, "is programming a datachip.", NULL, 0 );
    ch_println( ch, "You begin to write your hypothesis." );
    act( AT_ACTION, "$n begins to write in $s datachip.", ch, NULL, NULL, TO_ROOM );
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, dur*3, hypothesize_complete, hypothesize_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "book", obj );
    timer->buffer->num1 = skill->id;
}

int theorize_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop finalizing the datachip." );
    act( AT_ACTION, "$n stops writing in $s datachip.\n", ch, NULL, NULL, TO_ROOM );
