}

int theorize_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char buf[MSL];
    SKILL_DATA* skill = skill_from_id( buffer->num1 );
    OBJ_DATA* obj = get_obj_from_buffer( buffer, "book" );
    if ( !skill )
    {
        bug( "%s: could not find skill", FUNC );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }
    /*
        If this skill is over used, have this destroy the hypothesis,
        forcing them to remake it        -Orion
    */
    int chances = ( int ) get_learned_pct( ch, cache_skill( "theorize", &skill_theorize ) );
    if ( number_percent() > chances )
    {
        ch_println( ch, "You fail to finalize it. You had better start all over again..." );
        act( AT_ACTION, "$n finishes writing in $s datachip.", ch, NULL, NULL, TO_ROOM );
        return E_LOTJ_SUCCESS;
    }

    obj->value[1] = 1;

    /*
        Unlike hypothesize, you need only to have as high of science ability as the maker
        of the hypothesis in order to finish it. - Orion
    */

    /* Provide different colors for different levels of the maker */
    if ( ch->skill_level[SCIENCE_ABILITY] >= 150 )
        snprintf( buf, MSL, "&zA datachip labelled '&R%s&z'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 140 )
        snprintf( buf, MSL, "&cA datachip labelled '&w%s&c'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 120 )
        snprintf( buf, MSL, "&CA datachip labelled '&W%s&C'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 110  )
        snprintf( buf, MSL, "&YA datachip labelled '&G%s&Y'", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] < 110  )
        snprintf( buf, MSL, "&WA book labelled '&G%s&W'", skill->name );

    SET_STRING( obj->short_descr, buf );

    /* Provide different colors for different levels of the maker */
    if ( ch->skill_level[SCIENCE_ABILITY] >= 150 )
        snprintf( buf, MSL, "&zA datachip labelled '&R%s&z' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 140 )
        snprintf( buf, MSL, "&cA datachip labelled '&w%s&c' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 120 )
        snprintf( buf, MSL, "&CA datachip labelled '&W%s&C' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] >= 110  )
        snprintf( buf, MSL, "&YA datachip labelled '&G%s&Y' lies here.", skill->name );
    else if ( ch->skill_level[SCIENCE_ABILITY] < 110  )
        snprintf( buf, MSL, "&WA datachip labelled '&G%s&W' lies here.", skill->name );

    SET_STRING( obj->description, buf );
    snprintf( buf, MSL, "datachip %s", skill->name );
    SET_STRING( obj->name, buf );

    if ( ch->skill_level[SCIENCE_ABILITY] >= 120 )
    {
        learn_slow( ch, cache_skill( "education", &skill_education ), 2 );
        long xpgain = UMIN( 100000, ( exp_level( ch->skill_level[SCIENCE_ABILITY] + 1 ) - exp_level( ch->skill_level[SCIENCE_ABILITY] ) ) ) / 2;
        xpgain = apply_xp_sink( ch, xpgain, SCIENCE_ABILITY );
        gain_exp( ch, xpgain, SCIENCE_ABILITY, TRUE );
        ch_println( ch, "You gain %d science experience.", xpgain );
    }

    ch_println( ch, "You finish writing the datachip!" );
    act( AT_ACTION, "$n finishes writing in $s datachip.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "theorize", &skill_theorize ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_theorize( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    /* Redundancy to correct manipulative builders :D  -Orion */
    OBJ_DATA* obj = get_eq_char( ch, WEAR_HOLD );
    if ( !obj
            /* book? */
            || obj->item_type != ITEM_BOOK
            /* blank? */
            || obj->value[0] <= 0
            /* is this a finished book? */
            || obj->value[1] > 0 )
    {
        ch_println( ch, "You need to hold a chip with a hypothesis to finalize with theory." );
        return;
    }

    if ( obj->value[3] > ch->skill_level[SCIENCE_ABILITY] )
    {
        ch_println( ch, "You cannot finish this, it's far too advanced for your abilities." );
        return;
    }

    if ( NULLSTR( obj->blueprint ) )
    {
        ch_println( ch, "Your hypothesis is bugged." );
        bug ( "%s trying to theorize hypothesis without blueprint", ch->name );
        return;
    }

    SKILL_DATA* skill = skill_from_name( obj->blueprint );
    if ( !skill )
    {
        ch_println( ch, "You've never even HEARD of that before!" );
        return;
    }

    int dur = URANGE( 8, 150 - ch->skill_level[SCIENCE_ABILITY], 40 );
    action_set( ch, NULL, "is programming a datachip.", NULL, 0 );
    ch_println( ch, "You begin to finalize the hypothesis." );
    act( AT_ACTION, "$n begins to write in $s datachip.\n", ch, NULL, NULL, TO_ROOM );
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, dur*3, theorize_complete, theorize_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "book", obj );
    timer->buffer->num1 = skill->id;
}

/*  Books
    item type  v0              v1                      v2           v3               v4      v5
    book       written?        hypothesis(0)/theory(1) education %  level of creator

    for the skill to learn, we do a find_skill on obj->blueprint
    This allows for endless expansion!
*/
CMDF do_inspire_crime ( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    PLANET_DATA* planet = NULL;
    DB_DATA* wnted = NULL;

    if ( 2000 > ch->gold )
    {
        ch_println( ch, "You do not have enough to pay for that." );
        return;
    }

    planet = on_planet( ch );

    if ( !planet )
    {
        ch_println( ch, "You aren't on a planet!" );
        return;
    }

    CHAR_DATA* target = NULL;
    CHAR_DATA* police = NULL;

    for ( CHAR_DATA* rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( !target && is_cit( rch ) )
            target = rch;

        if ( !police && ( is_pol( rch ) || is_customs( rch ) ) )
            police = rch;
    }

    if ( !target )
    {
        ch_println( ch, "You cannot inspire crime when none of the locals are around!" );
        return;
    }

    ch->gold -= 2000;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "do_inspire_crime", -2000, TRUE );

    act( AT_ACTION, "You slip some credits to $N and suggest they stir up some trouble...", ch, NULL, target, TO_CHAR );
    act( AT_ACTION, "$n slips you some credits and suggests you stir up some trouble.", ch, NULL, target, TO_VICT );
    act( AT_ACTION, "$n gives $N some credits.",  ch, NULL, target, TO_NOTVICT );

    if ( police )
    {
        ch_println( ch, "Your efforts are noticed! You are now wanted on this planet." );
        wnted = set_wanted( ch->name, planet->name, TRUE, CRIME_INCITEMENT );

        if ( wnted->num1 == TRUE )
            ch_println( ch, "&YYou are now wanted for incitement on %s.&w", planet->name );

        return;
    }

    int chance = IS_NPC( ch ) ? ch->top_level / 2 : get_learned_pct( ch, cache_skill( "inspirecrime", &skill_inspirecrime ) ) / 2;

    if ( planet->governed_by )
    {
        // With 0 public opinion, 50% chance
        // With 100 public opinion, 17% chance
        chance -= get_planet_pop_opinion( planet, planet->governed_by ) / 3;
    }

    chance += get_curr_cha( ch ) - 15;

    if ( number_percent() > chance )
    {
        ch_println( ch, "They accept the credits but seem nervous about putting them to use." );
    }
    else
    {
        ch_println( ch, "They accept the credits and seem open to the idea." );
        affect_planet_crime( planet, ch, number_range( 2, 5 ) * 0.5 );
        learn_slow( ch, cache_skill( "inspirecrime", &skill_inspirecrime ), 2 );
    }

    act( AT_ACTION, "$N wanders off.\n", ch, NULL, target, TO_CHAR );
    act( AT_ACTION, "$N wanders off.\n", ch, NULL, target, TO_ROOM );
    extract_char( target );
    save_planet( planet, true );
    WAIT_STATE( ch, 60 );
}

bool is_cit( CHAR_DATA* ch )
{
    PLANET_DATA* planet = get_planet_from_room( ch->in_room );

    if ( !planet )
        return FALSE;

    return is_ai( ch, AI_CITIZEN );
}

bool is_customs( CHAR_DATA* ch )
{
    if ( !ch->in_room || !ch->in_room->area )
        return FALSE;

    if ( !IS_NPC( ch ) )
        return FALSE;

    if ( !ch->pIndexData )
        return FALSE;

    if ( !str_prefix( "spec_customs", ch->spec_funname ) || !str_prefix( "spec_customs", ch->spec_funname_2 ) ||
            !str_prefix( "spec_customs", ch->spec_funname_3 ) || !str_prefix( "spec_customs", ch->spec_funname_4 ) )
    {
        return TRUE;
    }

    return FALSE;
}
bool is_pol( CHAR_DATA* ch )
{
    PLANET_DATA* planet = NULL;

    if ( !ch->in_room || !ch->in_room->area || !ch->in_room->area->planet )
        return FALSE;

    if ( !IS_NPC( ch ) )
        return FALSE;

    if ( !ch->pIndexData )
        return FALSE;

    if ( is_ai( ch, AI_POLICE ) )
        return TRUE;

    if ( !str_prefix( "spec_police", ch->spec_funname ) || !str_prefix( "spec_police", ch->spec_funname_2 ) ||
            !str_prefix( "spec_police", ch->spec_funname_3 ) || !str_prefix( "spec_police", ch->spec_funname_4 ) )
    {
        return TRUE;
    }

    planet = ch->in_room->area->planet;

    if ( ch->pIndexData->vnum == planet->police1 || ch->pIndexData->vnum == planet->police2 || ch->pIndexData->vnum == planet->police3 || ch->pIndexData->vnum == planet->police4 )
        return TRUE;
    else
        return FALSE;
}
