void crim_react( CHAR_DATA* ch, CHAR_DATA* victim, int type )
{
    char buf[MSL];
    CHAR_DATA* rch = NULL;
    int mcount = 0, m = 0;

    if ( !is_crim( ch ) || !victim )
    {
        bug( "Crim_react: bad variables passed. %s%s", ch ? ch->name : "", victim ? victim->name : "" );
        return;
    }

    switch ( type )
    {
        default:
            bug( "Type out of range %d/%s.", ch->pIndexData->vnum, ch->name );
            break;

        case AI_STEAL:
            for ( rch = ch->in_room->first_person ; rch ; rch = rch->next_in_room )
                if ( rch != ch )
                    mcount++;

            m = number_range( 0, mcount );

            if ( m > 0 )
                for ( rch = ch->in_room->first_person; rch ; rch = rch->next_in_room )
                {
                    if ( mcount == m )
                        break;
                    else
                        continue;
                }

            if ( !rch )
                break;
            else
            {
                snprintf( buf, MSL, "coins '%s'", victim->name );
                do_steal( ch, buf );
            }

            break;

        case AI_FEAR:
            interpret( ch, "gulp", FALSE );
            start_fearing( ch, victim );
            break;

        case AI_ATTACK:
            multi_hit( ch, victim, TYPE_UNDEFINED );
            break;
    }

    return;
}

void cit_react( CHAR_DATA* ch, CHAR_DATA* victim, int type )
{
    if ( !is_cit( ch ) || !victim )
    {
        bug( "Cit_react: bad variables passed. %s%s", ch ? ch->name : "", victim ? victim->name : "" );
        return;
    }

    switch ( type )
    {
        default:
            bug( "Mob %d/%s executing cit_react with invalid type.", ch->pIndexData->vnum, ch->name );
            break;

        case AI_ATTACK:
            do_say( ch, "Stop that, you!" );
            start_hating( ch, victim );
            break;

        case AI_FEAR:
            do_say( ch, "Get away from me!" );
            start_fearing( ch, victim );
            break;

        case AI_ARREST:
            do_say( ch, "Freeze!" );
            start_hating( ch, victim );
            ch->ai_code = AI_ARREST;
            break;
    }

    return;
}
void troop_react( CHAR_DATA* ch, CHAR_DATA* victim, int type )
{
    char buf[MSL];

    if ( !is_troop( ch ) || !victim )
        return;

    switch ( type )
    {
        default:
            bug( "Mob %d/%s tried to react to bad type.", ch->pIndexData->vnum, ch->name );
            break;

        case AI_FEAR:
            snprintf( buf, MSL, "ptalk Fleeing from %s! Request assistance!", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            start_fearing( ch, victim );
            break;

        case AI_ARREST:
            snprintf( buf, MSL, "ptalk Arresting hostile %s! Request assistance!", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            start_hating( ch, victim );
            ch->ai_code = AI_ARREST;
            break;

        case AI_ATTACK:
            snprintf( buf, MSL, "ptalk Engaging enemy %s! Requesting assistance.", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            multi_hit( ch, victim, TYPE_UNDEFINED );
            break;
    }

    return;
}

void customs_react( CHAR_DATA* ch, CHAR_DATA* victim, int type )
{
    if ( !is_customs( ch ) || !victim )
        return;

    switch ( type )
    {
        default:
            bug( "Invalid type for %d/%s in customs_react.", ch->pIndexData->vnum, ch->name );
            break;

        case AI_ATTACK:
            interpret( ch, "say Freeze scumbag!", FALSE );
            multi_hit( ch, victim, TYPE_UNDEFINED );
            break;
    }

    return;
}
void pol_react( CHAR_DATA* ch, CHAR_DATA* victim, int type )
{
    char buf[MSL];

    if ( !is_pol( ch ) || !victim )
        return;

    switch ( type )
    {
        default:
            bug( "Invalid type for %d/%s in pol_react.", ch->pIndexData->vnum, ch->name );
            break;

        case AI_ATTACK:
            snprintf( buf, MSL, "ptalk Police report: Engaging hostile %s.", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            interpret( ch, "say Freeze scumbag!", FALSE );
            multi_hit( ch, victim, TYPE_UNDEFINED );
            break;

        case AI_ARREST:
            snprintf( buf, MSL, "ptalk Police report: Arresting suspect, %s.", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            start_hating( ch, victim );
            ch->ai_code = AI_ARREST;
            break;

        case AI_FEAR:
            snprintf( buf, MSL, "ptalk Gaagh! I'm pulling back! %s is too much to handle!", g_name( victim, ch ) );
            interpret( ch, buf, FALSE );
            start_fearing( ch, victim );
            break;
    }

    return;
}
CMDF do_setleader( CHAR_DATA* ch, char* argument )
{
    PLANET_DATA* planet = NULL;
    CLAN_DATA* clan;
    char buf[MSL];

    if ( IS_NPC( ch ) || !ch->pcdata->clan )
    {
        ch_println( ch, "You cannot use this skill unaffiliated." );
        return;
    }

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You're not even on a planet!" );
        return;
    }

    if ( strcmp( ch->name, ch->pcdata->clan->leader ) && strcmp( ch->name, ch->pcdata->clan->number1 ) && strcmp( ch->name, ch->pcdata->clan->number2 ) )
    {
        ch_println( ch, "You must be set by the leader as first, or second, in order to assign leadership to a planet and issue government to a member of your clan." );
        return;
    }

    if ( !planet->governed_by )
    {
        ch_println( ch, "This planet is not affiliated! Someone should take it over!" );
        return;
    }

    if ( planet->governed_by != ch->pcdata->clan )
    {
        ch_println( ch, "Your clan does not hold power on this planet..." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Csetleader <&wname&C>&w\nPlease be advised, it is case sensitive." );
        return;
    }

    ch_println( ch, "Changing the leader of this planet from %s to %s.", planet->leader ? planet->leader : "(Empty)", argument );
    clan = ch->pcdata->clan;

    SET_STRING( planet->leader, argument );
    save_planet( planet, true );

    if ( !xIS_SET( clan->flags, CLAN_HIDESTATS ) )
    {
        snprintf( buf, MSL, "%s has succeeded as the new ruler of %s.", planet->leader, planet->name );
        echo_to_all ( AT_RED, buf, 0 );
    }
}

void leadplanet_event( CHAR_DATA* ch, PLANET_DATA* planet, char* argument )
{
    int event_type = get_planet_event_type( argument );

    if ( event_type == -1 )
    {
        if ( !NULLSTR( argument ) )
            ch_println( ch, "Invalid event type.\n" );

        print_event_hints( planet, ch );
        return;
    }

    CLAN_DATA* clan = in_clan( ch );

    if ( !clan )
    {
        ch_println( ch, "You must be in a clan to begin planetary events." );
        return;
    }

    int cooldown = planet_event_cooldown( planet, clan );

    if ( cooldown > 0 )
    {
        ch_println( ch, "You must wait %s before beginning an event here.", duration_string( cooldown ) );
        return;
    }

    if ( !planet_event_requirement_check( ch, planet, event_type, false ) )
    {
        return;
    }

    int credits_needed = 0;

    if ( event_type == PLANET_EVENT_CRIMEWAVE )
        credits_needed = 100000;
    else if ( event_type == PLANET_EVENT_PROTESTS || event_type == PLANET_EVENT_CONSCRIPTION )
        credits_needed = 200000;
    else if ( event_type == PLANET_EVENT_INSURRECTION || event_type == PLANET_EVENT_MARTIAL_LAW )
        credits_needed = 400000;

    if ( credits_needed > 0 )
    {
        if ( clan->funds < credits_needed )
        {
            ch_println( ch, "Your clan can't afford the %d credits it would take to begin this event.", credits_needed );
            return;
        }

        char buf[MIL];
        snprintf( buf, MIL, "Beginning event '%s' on %s", flag_value_name( planet_event_types, event_type ), planet->name );
        add_clan_banklog( clan, ch->name, credits_needed * -1, buf );
        clan->funds -= credits_needed;
        ch_println( ch, "You authorize spending %d credits to fund the event.", credits_needed );
    }

    start_planet_event( planet, event_type, clan, ch );
}

CMDF do_leadplanet( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[MSL];
    PLANET_DATA* planet = NULL;
    CHAR_DATA* victim = NULL;
    CLAN_DATA* clan;
    DB_DATA* wnted;
    CAPTURE_DATA* capture = NULL;
    int cnt = 0;

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You're not even on a planet." );
        return;
    }

    clan = in_clan( ch );
    bool leader_or_diplomat = false;

    if ( clan )
    {
        if ( is_empowered( ch, "diplomat" ) ||
                !str_cmp( ch->name, clan->leader ) ||
                !str_cmp( ch->name, clan->number1 ) ||
                !str_cmp( ch->name, clan->number2 ) ||
                get_trust( ch ) >= sysdata.log_level )
            leader_or_diplomat = true;
    }

    if ( get_trust( ch ) >= sysdata.log_level && !clan )
    {
        clan = planet->governed_by;
        leader_or_diplomat = true;
    }

    if ( !clan )
    {
        ch_println( ch, "You're not in a clan to lead planets for." );
        return;
    }

    if ( clan->clan_type == CLAN_CRIME )
    {
        if ( !leader_or_diplomat )
        {
            ch_println( ch, "You must have the diplomat empowerment or be a clan leader, first, or second to lead planets." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ROOM_INDEX_DATA* jailroom = planet->jailroom > 0 ? get_room_index(planet->jailroom) : NULL;
            ch_println( ch, "&zCurrent state of affairs:\n"
                       "&zGoverned by: &C%s\n"
                       "&zLeader:      &C%s\n"
                       "&zTax rate:            &C%3.2f%%    &zCrime rate:       &C%3.0f\n"
                       "&zMilitary funding level: &C???    &zDeployed police: &C%4d\n"
                       "&zJail room: %s\n"
                       "\n",
                       planet->governed_by ? planet->governed_by->name : "(None)",
                       planet->leader,
                       planet->tax_rate, planet->crime,
                       active_police( planet ), planet->jailroom > 0 ? ( ( jailroom && jailroom->name ) ? jailroom->name : "(unknown)" ) : "(none)"
                     );
            ch_println( ch, "&zIn your network  [&G%s&z]\n", planet->crime_clan == clan ? "X" : " " );
            print_event_hints( planet, ch );
            ch_println( ch, "" );
            send_to_char( "&zCommands must start with &Cleadplanet\n"
                          "&wCommands: &znetwork, event\n", ch );
            return;
        }

        argument = one_argument( argument, arg );

        if ( !str_cmp( arg, "network" ) )
        {
            if ( planet->crime_clan == clan )
            {
                ch_println( ch, "You give the order for your crime network on this planet to disperse." );
                planet->crime_clan = NULL;
                save_planet( planet, true );
                return;
            }

            int current_count = 0;

            for ( PLANET_DATA* p = first_planet; p; p = p->next )
            {
                if ( p->crime_clan == clan )
                    current_count++;
            }

            if ( current_count >= 3 )
            {
                ch_println( ch, "Your clan can only have a network on up to three planets at a time." );
                return;
            }

            if ( planet->crime_clan && planet->crime >= 25 )
            {
                ch_println( ch, "A competing network is too established. You must drop crime below 25 before creating your own." );
                return;
            }

            if ( get_planet_event( planet, PLANET_EVENT_CRIMEWAVE ) || get_planet_event( planet, PLANET_EVENT_EMBEZZLEMENT ) || get_planet_event( planet, PLANET_EVENT_TERRORISM ) )
            {
                ch_println( ch, "Your contacts say the local criminal element is too busy to set up a network right now. Try again later." );
                return;
            }

            if ( clan->funds < 100000 )
            {
                ch_println( ch, "Your clan can't afford the 100,000 credit cost to establish a network." );
                return;
            }

            snprintf( buf, MSL, "Establishing a criminal network on %s", planet->name );
            add_clan_banklog( clan, ch->name, -100000, buf );
            clan->funds -= 100000;
            send_to_char( "You send your contacts 100,000 credits and ask them to begin setting up a "
                          "criminal network on this planet.\n", ch );
            planet->crime_clan = clan;
            save_planet( planet, true );
            save_clan( clan, true );
            return;
        }
        else if ( !strcmp( arg, "event" ) )
        {
            leadplanet_event( ch, planet, argument );
        }
        else
        {
            ch_println( ch, "Invalid leadplanet command." );
            do_leadplanet( ch, "" );
            return;
        }
    }
    else if ( clan == planet->governed_by )
    {
        if ( !leader_or_diplomat && str_cmp( planet->leader, ch->name ) )
        {
            ch_printf( ch, "You must be the appointed planet leader, have the diplomat empowerment, "
                       "or be a clan leader, first, or second to lead this planet.\n" );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ROOM_INDEX_DATA* jailroom = planet->jailroom > 0 ? get_room_index(planet->jailroom) : NULL;
            ch_println( ch, "&zCurrent state of affairs:\n"
                       "&zLeader:     &C%s\n"
                       "&zGovernment: &C%s\n"
                       "&zMain Clan:  &C%s\n"
                       "&zTax rate:              &C%3.2f%%    &zCrime rate:       &C%3.0f\n"
                       "&zMilitary funding level: &C%3d    &zDeployed police: &C%4d\n"
                       "\n"
                       "&zBlockade     [&G%s&z]\n"
                       "&zEmbargo      [&G%s&z]\n"
                       "&zComm         [&G%s&z]\n"
                       "&zRecruiting   [&G%s&z]\n"
                       "&zJail room: %s\n\n"
                       ,  planet->leader, planet->gov_name, planet->governed_by ? planet->governed_by->name : "(None)",
                       planet->tax_rate, planet->crime,
                       planet->military, active_police( planet ),
                       xIS_SET( planet->flags, PLANET_BLOCKADE ) ? "X" : " ", xIS_SET( planet->flags, PLANET_EMBARGO ) ? "X" : " ",
                       xIS_SET( planet->flags, PLANET_COMM ) ? "X" : " ", xIS_SET( planet->flags, PLANET_RECRUIT ) ? "X" : " ",
                       planet->jailroom > 0 ? ( ( jailroom && jailroom->name ) ? jailroom->name : "(unknown)" ) : "(none)" );
            print_event_hints( planet, ch );
            ch_println( ch, "" );
            send_to_char( "&zCommands must start with &Cleadplanet\n"
                          "&wCommands: &zevent, gov_name, military, tax, recruit,\n"
                          "&z          blockade, embargo, freeport, yield,\n"
                          "&z          broadcast, assist, jailroom, cargopass\n"
                          "&z          wanted\n", ch );
            return;
        }

        argument = one_argument( argument, arg );

        if ( NULLSTR( argument ) )
            argument = "(nothing)";

        if ( !strcmp( arg, "gov_name" ) )
        {
            if ( strlen( stripclr( argument ) ) <= 5 || strlen( stripclr( argument ) ) > 128 )
            {
                ch_println( ch, "Please enter 5-128 characters with or without color codes for the name." );
                return;
            }

            ch_println( ch, "Changing gov_name from %s to %s.", planet->gov_name, argument );
            bug ( "%s changing %s's gov_name from %s to %s.", ch->name, planet->name, planet->gov_name, argument );

            SET_STRING( planet->gov_name, argument );
        }
        else if ( !strcmp( arg, "wanted" ) )
        {
            clan = ch->pcdata->clan;
            cnt = 0;

            if ( !clan )
            {
                ch_println( ch, "In order to do this you must be part of a clan." );
                return;
            }

            if ( !str_cmp( argument, "view" ) || argument[0] == '\0' || !str_cmp( argument, "list" ) )
            {
                ch_println( ch, " &z.--&O-&YWANTED RECORDS&O-&z--." );

                for ( wnted = first_wanted; wnted; wnted = wnted->next )
                    if ( !str_cmp( planet->name, wnted->str1 )  )
                    {
                        if ( ( wnted->num1 == TRUE || wnted->num2 == TRUE ) && ( wnted->name && wnted->name[0] != '\0' && strcmp( wnted->name, "(null)" ) ) )
                        {
                            ch_printf( ch,
                                       "  &WName: %-25s  Status: %-8s", wnted->name, wnted->num2 == TRUE ? "&gImmune" : ( ( wnted->num2 == FALSE && wnted->num1 == TRUE ) ? "&rWanted" : "N/A" ) );

                            if ( wnted->num1 == TRUE && !NULLSTR( wnted->str2 ) )
                                ch_printf( ch, " &w(&r%s&w)", wnted->str2 );

                            ch_println( ch, "" );
                            cnt++;
                        }
                    }

                ch_println( ch, " &z.--&O-&Y%d TOTAL RECORDS&O-&z--.", cnt );
            }
            else if ( !str_cmp( argument, "clear" ) )
            {
                for ( wnted = first_wanted; wnted; wnted = wnted->next )
                {
                    if ( !str_cmp( wnted->str1, planet->name ) && ( wnted->name && wnted->name[0] != '\0' && strcmp( wnted->name, "(null)" ) ) )
                    {
                        cnt++;
                        wnted->num1 = FALSE;
                        wnted->num2 = FALSE;
                        SET_STRING( wnted->str2, "" );
                    }
                }
                save_dbase_sql(DB_TABLE_WANTED,wnted);

                ch_println( ch, " &z.--&O-&Y%d WANTED/IMMUNITY RECORDS CLEARED&O-&z--.", cnt );
            }
            else
            {
                ch_println( ch, "&Cleadplanet wanted <&wview/clear&C>&w" );
                return;
            }
        }
        else if ( !strcmp( arg, "military" ) )
        {
            if ( atoi( argument ) < 0 || atoi( argument ) > 75 )
            {
                ch_println( ch, "Valid military funding range is 0-75." );
                return;
            }

            if ( xIS_SET( clan->flags, CLAN_VONG ) )
            {
                ch_println( ch, "Yuuzhan Vong military funding cannot be set by players." );
                return;
            }

            ch_println( ch, "Changing military funding level from %d to %d.", planet->military, atoi( argument ) );
            planet->military = URANGE( 0, atoi( argument ), 75 );
        }
        else if ( !strcmp( arg, "tax" ) )
        {
            if ( NULLSTR( argument ) || !is_number( argument ) )
            {
                ch_println( ch, "Please enter the new tax rate." );
                return;
            }

            double new_rate = atof( argument );
            if ( new_rate < 0.0 || new_rate > 30.0 )
            {
                ch_println( ch, "The new tax rate must be between 0 and 30." );
                return;
            }

            if ( planet->tax_rate == new_rate )
            {
                ch_println( ch, "The tax rate is already set at that level." );
            }

            if ( planet->tax_last_changed + 3600 * 24 * 7 > time( 0 ) )
            {
                ch_println( ch, "The planetary tax rate can only be changed once per week. It was last changed on %s.", ( char* )c_time( (time_t)planet->tax_last_changed, get_timezone( ch ) ) );
                return;
            }

            ch_println( ch, "Changing tax rate from %.2f%% to %.2f%%.", planet->tax_rate, new_rate );
            planet->tax_rate = new_rate;
            planet->tax_last_changed = time( 0 );
        }
        else if ( !str_prefix( arg, "cargopass" ) ) /* C-O I-S */
        {
            int vnum = OBJ_VNUM_BLANK;
            OBJ_INDEX_DATA* index = NULL;
            OBJ_DATA* obj = NULL;

            if ( ( index = get_obj_index( vnum ) ) == NULL )
            {
                ch_println( ch, "Please contact coders." );
                bug( "OBJ_VNUM_BLANK is missing for %s!", ch->name );
            }

            obj = create_object( index, LEVEL_HERO );
            xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
            xSET_BIT( obj->wear_flags, ITEM_TAKE );
            obj->cost = 1000;
            obj->weight = 1;

            snprintf( buf, MSL, "permit %s cargo", planet->name );
            SET_STRING( obj->name, buf );

            snprintf( buf, MSL, "&zA permit to buy and sell goods on '&w%s&z'&w", planet->name );
            SET_STRING( obj->short_descr, buf );

            snprintf( buf, MSL, "&zA permit of some sort has been left here.\n" );
            SET_STRING( obj->description, buf );
            obj->item_type = ITEM_PERMIT;

            for ( vnum = 1; vnum <= 5; vnum++ )
                obj->value[vnum] = 0;

            obj->value[0] = 13;

            generate_permit( buf, MSL, planet );
            SET_STRING( obj->blueprint, buf );
            obj = obj_to_char( obj, ch );
            ch_println( ch, "&zYou authorize the permit." );
        }
        else if ( !strcmp( arg, "recruit" ) )
        {
            if ( xIS_SET( planet->flags, PLANET_RECRUIT ) )
            {
                ch_println( ch, "Recruiting of troops will no longer occur." );
                xREMOVE_BIT( planet->flags, PLANET_RECRUIT );
            }
            else
            {
                ch_println( ch, "Recruiting enabled." );
                xSET_BIT( planet->flags, PLANET_RECRUIT );
            }
        }
        else if ( !strcmp( arg, "blockade" ) )
        {
            if ( xIS_SET( planet->flags, PLANET_BLOCKADE ) && planet->blockaded_by == ch->pcdata->clan )
            {
                ch_println( ch, "Blockade lifted." );
                xREMOVE_BIT( planet->flags, PLANET_BLOCKADE );
                xSET_BIT( planet->flags, PLANET_UNBLOCKADED );
                snprintf( buf, MSL, "%s is no longer under blockade.", planet->name );

                for ( SHIP_DATA* ship = planet->starsystem->first_ship; ship; ship = ship->next_in_starsystem )
                    echo_to_ship_windows( AT_RED, ship, buf );

                snprintf( buf, MSL, "&R[PLANET BLOCKADE] &c%s is no longer under blockade.\n", planet->name );

                for ( DESCRIPTOR_DATA* d = first_descriptor ; d ; d = d->next )
                {
                    if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                        continue;

                    if ( IS_CLANNED( d->character ) && d->character->pcdata->clan == planet->blockaded_by )
                        send_to_char( buf, d->character );
                }
            }
            else if ( xIS_SET( planet->flags, PLANET_BLOCKADE ) )
            {
                ch_println( ch, "Your organization did not start this blockade." );
                return;
            }
            else
            {
                xSET_BIT( planet->flags, PLANET_BLOCKADE );
                xREMOVE_BIT( planet->flags, PLANET_UNBLOCKADED );
                CLAN_DATA* old_blockaded_by = planet->blockaded_by;
                planet->blockaded_by = ch->pcdata->clan;

                if ( blockade_effective_dist( planet ) == -1 )
                {
                    ch_println( ch, "&RYou must have a corvette or larger with a clan member onboard to support this blockade." );
                    xREMOVE_BIT( planet->flags, PLANET_BLOCKADE );
                    planet->blockaded_by = old_blockaded_by;
                    return;
                }

                if ( planet->blockade_start_time == 0 )
                    planet->blockade_start_time = current_time;

                ch_println( ch, "You have blockaded the planet!" );
                snprintf( buf, MSL, "Ships of %s move into position to begin a blockade of %s!", ch->pcdata->clan->name, planet->name );

                for ( SHIP_DATA* ship = planet->starsystem->first_ship; ship; ship = ship->next_in_starsystem )
                    echo_to_ship_windows( AT_RED, ship, buf );

                snprintf( buf, MSL, "&R[PLANET BLOCKADE] &c%s under %s blockade.\n", planet->name, planet->blockaded_by->name );

                for ( DESCRIPTOR_DATA* d = first_descriptor ; d ; d = d->next )
                {
                    if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                        continue;

                    if ( IS_CLANNED( d->character ) && d->character->pcdata->clan == planet->blockaded_by )
                        send_to_char( buf, d->character );
                }
            }
        }
        else if ( !strcmp( arg, "embargo" ) )
        {
            if ( xIS_SET( planet->flags, PLANET_EMBARGO ) )
            {
                ch_println( ch, "Trade Embargo has been lifted." );
                xREMOVE_BIT( planet->flags, PLANET_EMBARGO );
            }
            else
            {
                ch_println( ch, "Trade is now under embargo!" );
                xSET_BIT( planet->flags, PLANET_EMBARGO );
            }
        }
        else if ( !strcmp( arg, "freeport" ) )
        {
            if ( xIS_SET( planet->flags, PLANET_FREEPORT ) )
            {
                ch_println( ch, "This planet is no longer a freeport." );
                xREMOVE_BIT( planet->flags, PLANET_FREEPORT );
            }
            else
            {
                ch_println( ch, "This planet is now a freeport." );
                xSET_BIT( planet->flags, PLANET_FREEPORT );
            }
        }
        else if ( !strcmp( arg, "event" ) )
        {
            leadplanet_event( ch, planet, argument );
        }
        else if ( !strcmp( arg, "yield" ) )
        {
            if ( ( victim = get_char_room( ch, argument ) ) == NULL )
            {
                ch_println( ch, "You see nobody like that nearby to yield clan affiliation to." );
                return;
            }

            if ( IS_NPC( victim ) || !victim->pcdata->clan )
            {
                ch_println( ch, "You can't yield control to them!" );
                return;
            }

            if ( !planet->governed_by || victim->pcdata->clan == planet->governed_by )
            {
                ch_println( ch, "The planet already is affiliated with that clan!" );
                return;
            }

            bug( "%s yielding affiliation of %s to %s in room %d!", ch->name, planet->name, victim->name, ch->in_room->vnum );

            CREATE( capture, CAPTURE_DATA, 1 );
            capture->date = time( 0 );
            SET_STRING( capture->clan, victim->pcdata->clan->name );
            capture->yielded = true;
            LINK( capture, planet->first_capture, planet->last_capture, next, prev );
            planet->governed_by = victim->pcdata->clan;

            TAX_LEECH_DATA* leech = get_tax_leech( planet, victim->pcdata->clan );
            if ( leech )
            {
                bug( "%s was already a tax leech on %s. Removing tax leech...", victim->pcdata->clan, planet->name );
                remove_tax_leech( leech );
            }

            planet->military = 40;
            planet->tax_rate = 15.0;
            planet->tax_last_changed = 0;

            for ( wnted = first_wanted; wnted; wnted = wnted->next )
            {
                if ( !str_cmp( wnted->str1, planet->name ) )
                {
                    wnted->num1 = FALSE;
                    wnted->num2 = FALSE;
                }
            }

            // All events get ended, but we don't clear out the data for them so that we can still use
            // their start timestamps to determine cooldowns.
            for ( PLANET_EVENT_DATA* event = planet->first_event; event; event = event->next )
                event->expiration = current_time;

            ch_println( ch, "You have yielded leadership of this planet to %s!\n This means you have abdicated leadership!", victim->pcdata->clan->name );

            SET_STRING( planet->leader, "" );
            ch_println( victim, "%s has turned over the control of %s to %s.", g_name( ch, victim ), planet->name, victim->pcdata->clan->name );
            lua_trigger_on_planet_capture( planet, victim->pcdata->clan );
            snprintf( buf, MSL, "%s has yielded %s to %s!", ch->pcdata->clan->name, planet->name, victim->pcdata->clan->name );
            echo_to_all( AT_RED, buf, 0 );
            save_planet( planet, true );
            return;
        }
        else if ( !strcmp( arg, "broadcast" ) )
        {
            if ( !xIS_SET( planet->flags, PLANET_COMM ) )
            {
                ch_println( ch, "This planet is not equipped with a broadcasting beacon." );
                return;
            }
            else if ( NULLSTR( argument ) || !str_cmp( argument, "(nothing)" ) )
            {
                ch_println( ch, "What do you wish to broadcast?" );
                return;
            }
            else
            {
                lognormal( "%s using leadplanet broadcast from room %d: %s", ch->name, ch->in_room->vnum, ch->in_room->name );
                xSET_BIT( planet->flags, PLANET_TRANSMIT );
                do_chat( ch, argument );
                xREMOVE_BIT( planet->flags, PLANET_TRANSMIT );
            }
        }
        else if ( !strcmp( arg, "assist" ) )
        {
            if ( xIS_SET( planet->flags, PLANET_ASSIST ) )
            {
                xREMOVE_BIT( planet->flags, PLANET_ASSIST );
                ch_println( ch, "Military and police will no longer assist." );
            }
            else
            {
                xSET_BIT( planet->flags, PLANET_ASSIST );
                ch_println( ch, "Military and police will now assist." );
            }
        }
        else if ( !strcmp( arg, "jailroom" ) )
        {
            if ( planet->jailroom == ch->in_room->vnum )
            {
                ch_println( ch, "You have already set this room as the jail room." );
                return;
            }
            else if ( xIS_SET( ch->in_room->flags, ROOM_PLR_HOME ) || xIS_SET( ch->in_room->flags, ROOM_PHOME_ADDON ) )
            {
                ch_println( ch, "&RThis room cannot be used as a jail room." );
                bug( "%s trying to use a player home (%d) for the %s jail room.", ch->name, ch->in_room->vnum, planet->name );
                return;
            }
            else
            {
                bug( "%s changing %s jailroom from %d to %d.", ch->name, planet->name, planet->jailroom, ch->in_room->vnum );
                planet->jailroom = ch->in_room->vnum;
                ch_println( ch, "You have set the current room as the jail room." );
            }
        }
        else
        {
            ch_println( ch, "You have entered an invalid option." );
            ch_println( ch, "Please try again, or simply enter leadplanet to see commands." );
            return;
        }
    }
    else
    {
        if ( !leader_or_diplomat )
        {
            ch_println( ch, "You must have the diplomat empowerment or be a clan leader, first, or second to lead planets." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zCurrent state of affairs:\n"
                       "&zGoverned by: &C%s\n"
                       "&zLeader:      &C%s\n"
                       "&zTax rate:              &C%3.2f%%    &zCrime rate:       &C%3.0f\n"
                       "&zMilitary funding level: &C???    &zDeployed police: &C%4d\n"
                       "\n",
                       planet->governed_by ? planet->governed_by->name : "(None)",
                       planet->leader,
                       planet->tax_rate, planet->crime,
                       active_police( planet )
                     );
            print_event_hints( planet, ch );
            ch_println( ch, "" );
            send_to_char( "&zCommands must start with &Cleadplanet\n"
                          "&wCommands: &zevent\n", ch );
            return;
        }

        argument = one_argument( argument, arg );

        if ( !strcmp( arg, "event" ) )
        {
            leadplanet_event( ch, planet, argument );
        }
        else
        {
            ch_println( ch, "Invalid leadplanet command." );
            do_leadplanet( ch, "" );
            return;
        }
    }

    save_planet( planet, true );
}
CMDF do_escape_binding( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    int chances = 0;
    OBJ_DATA* obj = NULL;

    if ( ch->move <= 60 )
    {
        ch_println( ch, "You are too tired to even try that." );
        return;
    }

    if ( ( obj = get_eq_char( ch, WEAR_BINDING ) ) == NULL )
    {
        ch_println( ch, "You're not even bound right now." );
        return;
    }

    chances = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, cache_skill( "escape_binding", &skill_escape_binding ) );

    if ( number_percent() > chances )
    {
        ch_println( ch, "You wriggle, but fail to get free." );

        if ( number_percent() > ( chances * 1.5 ) )
            act( AT_ACTION, "$n wriggles, trying to free $mself from $s bindings.", ch, NULL, NULL, TO_ROOM );
        else
            learn_slow( ch, cache_skill( "escape_binding", &skill_escape_binding ), 3 );
    }
    else
    {
        ch_println( ch, "You wriggle your way out of your bindings." );
        obj->value[3] = 0;
        do_unbind( ch, "self 0" );
        learn_slow( ch, cache_skill( "escape_binding", &skill_escape_binding ), 2 );
    }

    return;
}

