int makeholster_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou are interrupted and fail to finish your work." );
    return E_LOTJ_SUCCESS;
}

int makeholster_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* duraplast = get_obj_from_buffer( buffer, "duraplast" );
    OBJ_DATA* fabric = get_obj_from_buffer( buffer, "fabric" );

    int value = 0;
    char buf[MSL];

    OBJ_DATA* obj = fabric;
    obj_from_char( fabric );

    value += duraplast->pIndexData->cost;

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_ARMOR ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makeholster", &skill_makeholster ) ) ) ;
    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou look over the newly crafted holster." );
        ch_println( ch, "&RSuddenly, the holster falls apart." );
        learn_from_failure( ch, cache_skill( "makeholster", &skill_makeholster ) );
        return E_LOTJ_SUCCESS;
    }

    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    set_crafted( ch, obj );
    obj->item_type = ITEM_HOLSTER;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    xSET_BIT( obj->wear_flags, ITEM_WEAR_WAIST );
    obj->weight = 1;
    strlcpy( buf, stripclr( arg ), MSL );
    strlcat( buf, " holster", MSL );
    SET_STRING( obj->name, buf );
    strlcpy( buf, arg, MSL );
    SET_STRING( obj->short_descr, buf );
    strlcat( buf, " lies here on the ground.", MSL );
    SET_STRING( obj->description, buf );
    obj->value[1]    = 0;
    obj->value[3]    = MAX_HOLSTER_CONDITION;  /* Condition */

    int skill = ( ch->skill_level[ENGINEERING_ABILITY] + ( get_learned_pct( ch, cache_skill( "makeholster", &skill_makeholster ) ) ) / 2 );
    if ( ch->skill_level[ENGINEERING_ABILITY] < 100 )
    {
        obj->cost = number_range( 500 * skill, 1000 * skill );
    }
    else
    {
        /*  If the engineer is an avatar engineer, the holster has double the price
              and it also includes a bonus to the hitroll of the wearer */
        obj->cost = 2 * number_range( 500 * skill, 1000 * skill );
        add_affect_to_obj( obj, APPLY_HITROLL, ch->skill_level[ENGINEERING_ABILITY] / 60 );
    }

    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up a brand new holster.&w" );
    act( AT_PLAIN, "$n finishes crafting a holster.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "makeholster", &skill_makeholster ), ( get_learned_pct( ch, cache_skill( "makeholster", &skill_makeholster ) ) + 1 ) / 25 );
    long xpgain = UMIN( obj->cost * 100, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    return E_LOTJ_SUCCESS;
}

CMDF do_makeholster( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cmakeholster <&wname&C>" );
        ch_println( ch, "&zRequires: Toolkit, duraplast, fabric&w" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_FACTORY ) )
    {
        ch_println( ch, "&RYou need to be in a factory or workshop to do that." );
        return;
    }

    OBJ_DATA* toolkit = get_obj_carried_of_type( ch, ITEM_TOOLKIT );
    if ( !toolkit )
    {
        ch_println( ch, "&RYou need a toolkit to make a holster." );
        return;
    }

    OBJ_DATA* duraplast = get_obj_carried_of_type( ch, ITEM_DURAPLAST );
    if ( !duraplast )
    {
        ch_println( ch, "&RYou need some duraplast for the molding." );
        return;
    }

    OBJ_DATA* fabric = get_obj_carried_of_type( ch, ITEM_FABRIC );
    if ( !fabric )
    {
        ch_println( ch, "&RYou need some fabric to put it together." );
        return;
    }

    if ( calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_ARMOR ) > ch->move )
    {
        ch_println( ch, "&RYou're too exhausted to do that right now!" );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, makeholster_complete, makeholster_abort, FUNC );
    SET_STRING( timer->buffer->str1, argument );
    add_obj_to_buffer( timer->buffer, "toolkit", toolkit );
    add_consumable_to_buffer( timer->buffer, "duraplast", duraplast, "Duraplast" );
    add_consumable_to_buffer( timer->buffer, "fabric", fabric, "Fabric" );

    ch_println( ch, "&GYou begin the long process of making a holster." );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_PLAIN, "$n takes $s tools and begins to craft something.", ch, NULL, argument, TO_ROOM );
    action_set( ch, NULL, "is crafting a holster.", NULL, 0 );

    add_obj_to_buffer( timer->buffer, "fabric", fabric ); // Set as nonconsumed after output
}

