    return E_LOTJ_SUCCESS;
}

int makebowcaster_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char* arg = buffer->str1;
    OBJ_DATA* duraplast = get_obj_from_buffer( buffer, "duraplast" );
    OBJ_DATA* quarrel = get_obj_from_buffer( buffer, "quarrel" );
    OBJ_DATA* battery = get_obj_from_buffer( buffer, "battery" );
    OBJ_DATA* super = get_obj_from_buffer( buffer, "super" );
    OBJ_DATA* circuit = get_obj_from_buffer( buffer, "circuit" );
    OBJ_DATA* scope = get_obj_from_buffer( buffer, "scope" );

    int supermod = 0, duramod = 0, battmod = 0, circuitmod = 0, scopemod = 0;
    double mindam = 0, maxdam = 0, shots = 0, value = 0;
    char buf[MSL];

    int level = IS_NPC( ch ) ? ch->top_level : ( int ) ( ch->skill_level[ENGINEERING_ABILITY] + get_learned_pct( ch, cache_skill( "makebowcaster", &skill_makebowcaster ) ) / 2 );

    OBJ_INDEX_DATA* pObjIndex = get_obj_index( OBJ_VNUM_BLANK );
    if ( !check_default_obj( ch, pObjIndex, FUNC ) )
        return E_LOTJ_ASYNC_VALIDATION_FAILED;

    duramod = duraplast->value[0]; //Duraplast's quality modifier for cost
    value += duraplast->pIndexData->cost;

    shots = quarrel->value[0]; //Bolt item's v0 determines number of charges
    value += quarrel->pIndexData->cost;

    battmod = battery->value[1]; //Battery's quality modifier
    value += battery->pIndexData->cost;

    supermod = super->value[0]; //Superconductor's quality modifier
    value += super->pIndexData->cost;

    circuitmod = circuit->value[0]; //Circuit's quality modifier
    value += circuit->pIndexData->cost;

    if ( scope )
    {
        scopemod = scope->value[0]; //Scope's quality modifier
        value += scope->pIndexData->cost;
    }

    ch->move = URANGE( 0, ch->move - calc_effortrate( ch, ENGINEERING_ABILITY, EFFORT_BLASTER ), ch->max_move );

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, cache_skill( "makebowcaster", &skill_makebowcaster ) ) ) ;
    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou hold up the newly crafted bowcaster and prime it." );
        ch_println( ch, "&RThe sound of bending parts and sizzling is heard shortly before it explodes." );
        learn_from_failure( ch, cache_skill( "makebowcaster", &skill_makebowcaster ) );
        return E_LOTJ_SUCCESS;
    }

    //Bonuses to base damage from science values
    if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) == 100 )
    {
        ch_println( ch, "Your skill in Equipment lets you make a better bowcaster." );
        level += 20;
    }

    if ( get_learned_pct( ch, cache_skill( "destruction", &skill_destruction ) ) == 100 )
    {
        ch_println( ch, "Your skill in Destruction lets you make a better bowcaster." );
        level += 20;
    }

    maxdam = level * 0.55; //Set base maximum damage
    maxdam *= 1 + ( double )circuitmod / 100;
    maxdam *= 1 + ( double )supermod / 100;
    mindam = maxdam * 0.75;
    value *= 1 + ( duramod / 100. ); //Increase value by duraplast modifier percentage
    shots *= 1 + ( battmod / 100. ); //Increase ammo by battery modifier percentage
    OBJ_DATA* obj = create_object( pObjIndex, level );
    xREMOVE_BIT( obj->extra_flags, ITEM_PROTOTYPE );
    set_crafted( ch, obj );
    obj->item_type = ITEM_WEAPON;
    xCLEAR_BITS( obj->wear_flags );
    xSET_BIT( obj->wear_flags, ITEM_WIELD );
    xSET_BIT( obj->wear_flags, ITEM_TAKE );
    xSET_BIT( obj->extra_flags, ITEM_NODUAL ); //Lydor '08.
    obj->level = level;
    obj->weight = 55; //Only 24 str can wield. Lydor '08.
    obj->cost = calc_markup( ch, ( int ) value );
    snprintf( buf, MSL, "%s bowcaster", stripclr( arg ) );
    SET_STRING( obj->name, buf );
    snprintf( buf, MSL, "%s", arg );
    SET_STRING( obj->short_descr, buf );
    snprintf( buf + strlen( buf ), MSL - strlen( buf ), " lies here on the ground." );
    SET_STRING( obj->description, buf );
    obj->value[0] = INIT_WEAPON_CONDITION; /* condition */
    obj->value[1] = ( int ) mindam; /* min dmg */
    obj->value[2] = ( int ) maxdam; /* max dmg */
    obj->value[3] = WEAPON_BOWCASTER;
    obj->value[4] = ( int ) shots;
    obj->value[5] = ( int ) shots;
    add_affect_to_obj( obj, APPLY_HITROLL, scopemod );
    obj = obj_to_char( obj, ch );
    ch_println( ch, "&GYou finish your work and hold up your newly created bowcaster.&w" );
    act( AT_PLAIN, "$n finishes making $s new bowcaster.", ch, NULL, NULL, TO_ROOM );
    long xpgain = UMIN( obj->cost * 50, ( exp_level( ch->skill_level[ENGINEERING_ABILITY] + 1 ) - exp_level( ch->skill_level[ENGINEERING_ABILITY] ) ) ) / 2;
    xpgain = apply_xp_sink( ch, xpgain, ENGINEERING_ABILITY );
    gain_exp( ch, xpgain, ENGINEERING_ABILITY, TRUE );
    ch_println( ch, "You gain %d engineering experience.", xpgain );
    learn_from_success( ch, cache_skill( "makebowcaster", &skill_makebowcaster ) );
    return E_LOTJ_SUCCESS;
}

