    if ( !durasteel )
    {
        ch_println( ch, "&RYou need some durasteel for the forcepike mold." );
        return;
    }

    OBJ_DATA* battery = get_obj_carried_of_type( ch, ITEM_BATTERY );
    if ( !battery )
    {
        ch_println( ch, "&RYou need a power source for the forcepike." );
