int blastdoor_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    EXIT_DATA* pexit = find_door( ch, buffer->str1, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "&RA charge isn't going to do you any good on a solid wall." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
    {
        ch_println( ch, "Why bother? It's not even closed." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( xIS_SET( pexit->flags, EX_BLASTPROOF ) )
    {
        ch_println( ch, "&RYour mine won't make a dent in that door!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    char* keyword;
    if ( xIS_SET( pexit->flags, EX_SECRET ) )
        keyword = "wall";
    else
        keyword = pexit->keyword;

    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) get_learned_pct( ch, cache_skill( "blastdoor", &skill_blastdoor ) ) / 1.33 ; //Ralen Dec' 13 - Previously / 3. 30% success rate at 100%??


    alarm_room( ch->in_room, "Door percussive blast sensor tripped at" );
    do_visible( ch, "-noalert" );

    if ( number_percent( ) <= chance )
    {   
        xREMOVE_BIT( pexit->flags, EX_CLOSED );
        xREMOVE_BIT( pexit->flags, EX_LOCKED );
        xSET_BIT( pexit->flags, EX_BREACHED );
        act( AT_SKILL, "You finish placing the breaching charge on the $d!", ch, NULL, keyword, TO_CHAR );
        act( AT_SKILL, "$n finishes placing $s his breaching charge on the $d!", ch, NULL, keyword, TO_ROOM );
        act( AT_YELLOW, "You activate the release and blast the $d open!", ch, NULL, keyword, TO_CHAR );
        act( AT_YELLOW, "The $d is blasted open by $n as the charge detonates!", ch, NULL, keyword, TO_ROOM );
        learn_from_success( ch, cache_skill( "blastdoor", &skill_blastdoor ) );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            xREMOVE_BIT( pexit->rexit->flags, EX_CLOSED );
            xREMOVE_BIT( pexit->rexit->flags, EX_LOCKED );
            xSET_BIT( pexit->rexit->flags, EX_BREACHED );

            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d blasts open as someone activates a charge!", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }
    }
    else
    {
        act( AT_SKILL, "You try to blow open the $d, but it holds strong.", ch, NULL, keyword, TO_CHAR );
        act( AT_SKILL, "$n tries to blow open the $d, but it holds strong.", ch, NULL, keyword, TO_ROOM );

        if ( pexit->to_room && pexit->rexit && pexit->rexit->to_room == ch->in_room )
        {
            for ( CHAR_DATA* rch = pexit->to_room->first_person; rch; rch = rch->next_in_room )
                act( AT_SKILL, "The $d shudders due to a blast on the far side but holds strong!", rch, NULL, pexit->rexit->keyword, TO_CHAR );
        }

        learn_from_failure( ch, cache_skill( "blastdoor", &skill_blastdoor ) );
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_blastdoor( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cblastdoor <&wdirection&C>" );
        return;
    }

    if ( ch->fighting )
    {
        ch_println( ch, "Not in the middle of a battle!" );
        return;
    }

    OBJ_DATA* charge = get_obj_carried_of_type( ch, ITEM_LANDMINE );
    if ( !charge )
    {
        ch_println( ch, "You don't possess a charge to breach the door!" );
        return;
    }

    EXIT_DATA* pexit = find_door( ch, argument, TRUE );
    if ( !pexit )
    {
        ch_println( ch, "&RA charge isn't going to do you any good on a solid wall." );
        return;
    }

    if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
    {
        ch_println( ch, "Why bother? It's not even closed." );
        return;
