CMDF do_mine( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj;
    bool shovel;
    sh_int move;

    if ( get_learned_pct( ch, cache_skill( "mines", &skill_mines ) ) <= 0 )
    {
        ch_println( ch, "You have no idea how to do that." );
        return;
    }

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "And what will you mine the room with?" );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    shovel = FALSE;

    for ( obj = ch->first_carrying; obj; obj = obj->next_content )
        if ( obj->item_type == ITEM_SHOVEL )
        {
            shovel = TRUE;
            break;
        }

    obj = get_obj_list_rev( ch, arg, ch->in_room->last_content );

    if ( !obj )
    {
        ch_println( ch, "You don't see that here." );
        return;
    }

    separate_obj( obj );

    if ( obj->item_type != ITEM_LANDMINE )
    {
        act( AT_PLAIN, "That's not a landmine!", ch, obj, 0, TO_CHAR );
        return;
    }

    if ( !CAN_WEAR( obj, ITEM_TAKE ) )
    {
        act( AT_PLAIN, "You cannot bury $p.", ch, obj, 0, TO_CHAR );
        return;
    }

    switch ( ch->in_room->sector_type )
    {
        case SECT_AIR:
            ch_println( ch, "What?  Bury a mine in the air?!" );
            return;
    }

    if ( obj->weight > ( UMAX( 5, ( can_carry_w( ch ) / 10 ) ) ) &&  !shovel )
    {
        ch_println( ch, "You'd need a shovel to bury something that big." );
        return;
    }

    move = ( obj->weight * 50 * ( shovel ? 1 : 5 ) ) / UMAX( 1, can_carry_w( ch ) );
    move = URANGE( 2, move, 1000 );

    if ( move > ch->move )
    {
        ch_println( ch, "You don't have the energy to bury something of that size." );
        return;
    }

    ch->move -= move;
    xSET_BIT( obj->extra_flags, ITEM_BURIED );
    WAIT_STATE( ch, URANGE( 10, move / 2, 100 ) );
    SET_STRING( obj->armed_by, ch->name );
    xSET_BIT( obj->extra_flags, ITEM_PERSISTENT );

    // Random time between 4-22 hours, but weighted toward the middle by combining two rolls.
    int lifespan_hours = number_range( 2, 11 ) + number_range( 2, 11 );
    obj->timer = (lifespan_hours*60*60*PULSE_PER_SECOND)/PULSE_TICK;

    save_persistent_object( obj, true );
    /* GRAL v4 timer like grenades? */
    ch_println( ch, "You arm and bury %s.", obj->short_descr );
    act( AT_PLAIN, "$n arms and buries $p.", ch, obj, NULL, TO_ROOM );
    learn_from_success( ch, cache_skill( "mines", &skill_mines ) );
    return;
}

