CMDF do_broadcast( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    PLANET_DATA* planet = NULL;

    if ( get_learned_pct( ch, cache_skill( "broadcast", &skill_broadcast ) ) <= 0 )
    {
        ch_println( ch, "You have no idea how to do that." );
        return;
    }

    strlcpy( arg, argument, MIL );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Cnetworkhack <&wmessage&C>" );
        return;
    }

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You aren't on a planet." );
        return;
    }

    if ( !xIS_SET( planet->flags, PLANET_COMM ) )
    {
        ch_println( ch, "This planet is not equipped with a broadcasting beacon." );
        return;
    }

    if ( is_disrupted( ch, TAP_COMM, false ) )
        return;
    else if ( !xIS_SET( ch->in_room->flags, ROOM_COMMAND ) && !xIS_SET( ch->in_room->flags, ROOM_BROADCAST ) )
    {
        ch_println( ch, "&RYou need to be in a transmitting station." );
        return;
    }
    else if ( ch->gold < 50000 )
    {
        ch_println( ch, "You don't have the credits to pay the 50,000 credit fee!" );
        return;
    }

    // GRAL Stopped broadcast while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak through the transmitting station but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't use a transmitting station while gagged." );
        return;
    }

    ch->gold -= 50000;

    if ( !IS_NPC( ch ) )
        sql_credits_log( ch->name, "do_broadcast", -50000, FALSE );

    if ( planet->governed_by != NULL )
    {
        planet->governed_by->funds += 50000; //Pay the clan! Make them care about network hackers. Gathorn 24 July 18
        sql_credits_log( planet->governed_by->name, "do_broadcast", 50000, FALSE );
    }

    lognormal( "%s using broadcast from room %d: %s", ch->name, ch->in_room->vnum, ch->in_room->name );
    xSET_BIT( planet->flags, PLANET_TRANSMIT );
    do_chat( ch, arg );
    xREMOVE_BIT( planet->flags, PLANET_TRANSMIT );
    learn_from_success( ch, cache_skill( "broadcast", &skill_broadcast ) );
    return;
}
CMDF do_networkhack( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj;
    PLANET_DATA* planet = NULL;
    bool checkpad = FALSE;
    int chance;

    if ( get_learned_pct( ch, cache_skill( "networkhack", &skill_networkhack ) ) <= 0 )
    {
        ch_println( ch, "You have no idea how to do that." );
        return;
    }

    strlcpy( arg, argument, MIL );

    if ( ( obj = get_eq_char( ch, WEAR_HOLD ) ) != NULL )
        if ( obj->item_type == ITEM_DATAPAD && obj->value[0] >= 2 )
            checkpad = TRUE;

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "What do you wish to broadcast?" );
        return;
    }

    if ( ( planet = ch->in_room->area->planet ) == NULL )
    {
        ch_println( ch, "You aren't on a planet." );
        return;
    }

    if ( is_disrupted( ch, TAP_COMM, false ) )
        return;

    // GRAL Stopped networkhack while gagged
    if ( has_pcflag( ch, PCFLAG_GAGGED ) )
    {
        act( AT_ACTION, "Gagged, $n tries to speak through the communication system but their words are muffled.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You can't use communications while gagged." );
        // GRAL Do we want a noise perhaps? Check if they at least have hands to push a button?
        return;
    }

    // GRAL Stopped networkhack lorrdian while gagged do we want all to go through but speech maybe?
    if ( xIS_SET( ch->speaking, LANG_LORRDIAN ) )
    {
        ch_println( ch, "The language of the Lorrdians is physical." );
        return;
    }

    if ( !xIS_SET( planet->flags, PLANET_COMM ) )
    {
        ch_println( ch, "This planet is not equipped with a broadcasting beacon." );
        return;
    }
    else if ( !xIS_SET( ch->in_room->flags, ROOM_TAP_COMM ) ) // Let's make networkhack a little bit more difficult to encourage broadcast a bit more.
    {
        ch_println( ch, "&RYou need to be in a communications tap point." );
