    }

    chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "networkhack", &skill_networkhack ) );

    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou have trouble linking the datapad to the transmission network." );
        learn_from_failure( ch, cache_skill( "networkhack", &skill_networkhack ) );
        return;
    }

    lognormal( "%s using networkhack from room %d: %s", ch->name, ch->in_room->vnum, ch->in_room->name );
    xSET_BIT( planet->flags, PLANET_TRANSMIT );
    do_chat( ch, arg );
    xREMOVE_BIT( planet->flags, PLANET_TRANSMIT );
    learn_slow( ch, cache_skill( "networkhack", &skill_networkhack ), URANGE( 1, ( get_learned_pct( ch, cache_skill( "networkhack", &skill_networkhack ) ) + 1 ) / 25, 5 ) );
