int makearmor_complete_new( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* material = get_obj_from_buffer( buffer, "material" );
    int wearloc = buffer->num1;
    bool cover = buffer->bool1;
    char* orig_name = buffer->str1;

    obj_from_char( material ); // So weight gets calculated correctly

    set_crafted( ch, material );
    xCLEAR_BITS( material->wear_flags );
    xSET_BIT( material->wear_flags, ITEM_TAKE );
    xSET_BIT( material->wear_flags, wearloc );

    char armor_name[MIL], armor_short[MIL], armor_long[MIL];
    strlcpy( armor_name, stripclr( orig_name ), MIL );
    snprintf( armor_short, MIL, "&z%s &G(&RUnfinished&G)", orig_name );
    snprintf( armor_long, MIL, "&z%s lies here on the ground.", orig_name );
    SET_STRING( material->name, armor_name );
    SET_STRING( material->description, armor_long );
    SET_STRING( material->short_descr, armor_short );
    SET_STRING( material->blueprint, orig_name );

    ch_println( ch, "You create your new piece of %s armor: %s", xIS_SET( material->wear_flags, ITEM_WEAR_HEAD ) ? "head" : "body", material->short_descr );
    act( AT_ACTION, "$n finishes creating some new armor.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "makearmor", &skill_makearmor ), 3 );

    if ( material->item_type == ITEM_FABRIC )
    {
        material->value[2] = 1;
        material->value[1] = get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 ? 50 : 150;
        material->value[4] = 300;
        material->weight = 30;
    }
    if ( material->item_type == ITEM_DURAPLAST )
    {
        material->value[2] = 2;
        material->value[1] = get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 ? 100 : 300;
        material->value[4] = 550;
        material->weight = 85;
    }
    if ( material->item_type == ITEM_DURASTEEL )
    {
        material->value[2] = 3;
        material->value[1] = get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) < 100 ? 150 : 450;
        material->value[4] = 800;
        material->weight = 175;
    }

    if ( cover )
        material->value[5] = 1;
    material->item_type = ITEM_ARMOR;
    material->value[0] = 13;
    learn_slow( ch, cache_skill( "makearmor", &skill_makearmor ), 3 );

    obj_to_char( material, ch );
    return E_LOTJ_SUCCESS;
}

int makearmor_complete_existing( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* armor = get_obj_from_buffer( buffer, "armor" );
    if ( armor->value[4] == 0 )
    {
        ch_println( ch, "It's already finished!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    int progress;
    if ( ch->skill_level[SCIENCE_ABILITY] >= ( LEVEL_HERO / 2 ) )
    {
        progress = get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) + 5;
        if ( get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) == 100 )
            progress += number_range( 3, 6 );
    }
    else
    {
        progress = number_range( 3, 25 );
    }
    progress /= ( 87 - URANGE( 30, ch->skill_level[SCIENCE_ABILITY], 80 ) );

    armor->value[4] = URANGE( 0, armor->value[4] - progress, armor->value[4] );
    if ( armor->value[4] == 0 )
    {
        SET_STRING( armor->short_descr, armor->blueprint );
        SET_STRING( armor->blueprint, "" );
        ch_println( ch, "You hold up your finished piece of %s armor!", xIS_SET( armor->wear_flags, ITEM_WEAR_HEAD ) ? "head" : "body" );
    }
    else
    {
        ch_println( ch, "You finish working on %s.", armor->short_descr );
        act( AT_ACTION, "$n finishes working on some armor.", ch, NULL, NULL, TO_ROOM );

        if ( armor->value[4] < ( progress * 5 ) )
        {
            if ( armor->value[2] == 1 || armor->value[2] == 2 || armor->value[2] == 3 )
                ch_println( ch, "&RYou are close to completing this, but there is no coating or underlay!&w" );
            else if ( armor->value[2] == 4 || armor->value[2] == 7 || armor->value[2] == 10 )
                ch_println( ch, "&RYou are close to completing this, but there is no coating!&w" );
            else if ( armor->value[2] == 5 || armor->value[2] == 8 || armor->value[2] == 11 )
                ch_println( ch, "&RYou are close to completing this, but there is no underlay!&w" );
        }
    }

    if ( number_range( 1, 105 ) > get_learned_pct( ch, cache_skill( "makearmor", &skill_makearmor ) ) )
        learn_slow( ch, cache_skill( "makearmor", &skill_makearmor ), 3 );
    do_save( ch, "-noalert" );
    return E_LOTJ_SUCCESS;
}

CMDF do_makearmor( CHAR_DATA* ch, char* argument )
{
    char *syntax = "&zSyntax: &Cmakearmor <&warmor&C>\n"
                   "&z        &Cmakearmor <&wmaterial&C> <&wabout/head&C> <&wcover/nocover&C> <&wname&C>";
    char arg1[MIL], arg2[MIL], arg3[MIL];
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, syntax );
        return;
    }

    OBJ_DATA* sewingkit = get_obj_carried_of_type( ch, ITEM_SEWING_KIT );
    if ( !sewingkit )
    {
        ch_println( ch, "You need a needle and thread to work on armor." );
        return;
    }

    // 45 seconds with adept equipment science, up to 1:35 without.
    int dur = IS_NPC( ch ) ? 40 : 45 + ( 100 - get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) ) / 2;

    // If there's just one argument, find an existing piece of armor to work on.
    OBJ_DATA* armor = get_obj_here( ch, arg1 );
    if ( armor && NULLSTR( arg2 ) )
    {
        if ( armor->item_type != ITEM_ARMOR )
        {
            ch_println( ch, "That's not an unfinished piece of armor." );
            return;
        }

        if ( armor->wear_loc != WEAR_NONE )
        {
            ch_println( ch, "You must remove it first." );
            return;
        }

        if ( armor->value[4] == 0 )
        {
            ch_println( ch, "That armor is already finished." );
            return;
        }

        TIMER* timer = add_timer( ch, TIMER_DO_FUN, dur, makearmor_complete_existing, makearmor_abort, FUNC );
        add_obj_to_buffer( timer->buffer, "sewingkit", sewingkit );
        add_obj_to_buffer( timer->buffer, "armor", armor );
        timer->comms_interrupt = false;

        ch_println( ch, "You take the armor and continue to work on it.", ch );
        action_set( ch, NULL, "is working on a piece of armor.", NULL, 0 );
        act( AT_ACTION, "$n takes some armor and $e begins to work on it.", ch, NULL, NULL, TO_ROOM );
        return;
    }

    if ( NULLSTR( arg2 ) || NULLSTR( arg3 ) || NULLSTR( argument ) )
    {
        ch_println( ch, syntax );
        return;
    }

    OBJ_DATA* material = get_obj_carry( ch, arg1 );
    if ( !material )
    {
        ch_println( ch, "You have no material like that." );
        return;
    }

    if ( material->item_type != ITEM_FABRIC && material->item_type != ITEM_DURASTEEL && material->item_type != ITEM_DURAPLAST )
    {
        ch_println( ch, "That's not a suitable material for armor." );
        return;
    }

    if ( material->item_type == ITEM_DURASTEEL && material->value[4] != 0 )
    {
        ch_println( ch, "What kind of armor do you think you'd make with ship parts?" );
        return;
    }

    int wearloc;
    if ( !str_cmp( arg2, "head" ) )
        wearloc = ITEM_WEAR_HEAD;
    else if ( !str_cmp( arg2, "about" ) )
        wearloc = ITEM_WEAR_ABOUT;
    else
    {
        ch_println( ch, "You must make armor on the HEAD or ABOUT layer." );
        return;
    }

    bool cover;
    if ( !str_cmp( arg3, "cover" ) )
        cover = true;
    else if ( !str_cmp( arg3, "nocover" ) )
        cover = false;
    else
    {
        ch_println( ch, "Please decide whether the armor will cover the whole body or not. (cover/nocover)" );
        return;
    }

    if ( !valid_obj_name( argument ) )
    {
        ch_println( ch, "That name is invalid. Please try a different name." );
        return;
    }

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, dur, makearmor_complete_new, makearmor_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "sewingkit", sewingkit );
    add_consumable_to_buffer( timer->buffer, "material", material, "Material" );
    SET_STRING( timer->buffer->str1, argument );
    timer->buffer->bool1 = cover;
    timer->buffer->num1 = wearloc;
    timer->comms_interrupt = false;

    ch_println( ch, "You take the %s and begin creating some new %s armor.", material->short_descr, wearloc == ITEM_WEAR_HEAD ? "head" : "body" );
    ch_println( ch, "&wYour finished product will look like: %s", argument );
    print_buffer_objects( timer->buffer, ch );
    act( AT_ACTION, "$n takes some materials and begins making some armor.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is working on a piece of armor.", NULL, 0 );

    // We temporarily add the material as consumable so we can reuse the print_buffer_consumables function.
    add_obj_to_buffer( timer->buffer, "material", material );
}

CMDF do_duty( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL, *vch = NULL;
    char target_arg[MIL];
    char cmd_arg[MIL];
    char buf[MSL];
    char line[SUB_MSL];
    AI_DATA* curr_ai = NULL;
    int cnt = 0;

    if ( NULLSTR( argument ) )
    {
        for ( curr_ai = first_ai; curr_ai; curr_ai = curr_ai->next )
        {
            if ( !curr_ai->character || curr_ai->character->master != ch )
                continue;

            vch = curr_ai->character;
            ch_println( ch, "&z[&C%d&z] &YVitals &z[&W%s&z][&R%d&W/&R%d&z] &YLocation: &z[&W%s&z][&W%s&z]\n &yCombat state: &z[&W%s&z]", ++cnt, vch->short_descr, vch->hit, vch->max_hit,
                       on_planet( vch ) ? on_planet( vch )->name : "-",
                       get_ship_from_room( vch->in_room ) ? get_ship_from_room( vch->in_room )->name : "-",
                       who_fighting( vch ) ? g_name( who_fighting( vch ), ch ) : "-" );
        }

        if ( cnt == 0 )
            ch_println( ch, "You have 0 troopers in your squad." );
        else
            ch_println( ch, "You have %d trooper%s in your squad.", cnt, cnt == 1 ? "" : "s" );

        return;
    }

    argument = one_argument( argument, target_arg );

    if ( !str_cmp( "all", target_arg ) )
    {
        if ( !cycle_char )
        {
            for ( cycle_char = ch->in_room->first_person; cycle_char; cycle_char = cycle_char->next_in_room )
            {
                if ( !cycle_char->ai_data || cycle_char->master != ch )
                    continue;

                break;
            }

            if ( !cycle_char )
            {
                ch_println( ch, "You have no squad here to command." );
                return;
            }

            victim = cycle_char;
        }
        else
        {
            for ( victim = cycle_char->next_in_room; victim; victim = victim->next_in_room )
                if ( victim->ai_data && victim->master == ch )
                    break;

            if ( !victim )
            {
                cycle_char = NULL;
                return;
            }
            else
                cycle_char = victim;
        }
    }
    else if ( !ch || !ch->in_room || NULLSTR( target_arg ) || ( victim = get_char_room( ch, target_arg ) ) == NULL )
    {
        ch_println( ch, "You see nobody like that nearby." );
        return;
    }

    strlcpy( line, argument, SUB_MSL );
    argument = one_argument( argument, cmd_arg );
    bool isDroid = false;
    DROID_DATA* tDB = droid_from_mob( victim );

    if ( tDB ) isDroid = true;

    if ( isDroid && tDB && can_control_droid( ch, tDB ) && tDB->controller != ch->id )
    {
        ch_println( ch, "You must control that droid before you can order them around." );
        ch_println( ch, "&zHint: try &Ccontroldroid %s&z to control them.", victim->name );
        return;
    }

    if ( !isDroid || !can_control_droid( ch, tDB ) )
    {
        if ( !victim->ai_data )
        {
            ch_println( ch, "You can't order them around!" );
            return;
        }

        if ( !victim->ai_data->clan || victim->ai_data->clan != ch->pcdata->clan )
        {
            ch_println( ch, "They aren't in your clan." );
            return;
        }

        if ( !is_ai( victim, AI_SOLDIER_LIGHT ) && ( is_ai( victim, AI_POLICE ) && !is_leader( ch, on_planet( ch ) ) ) )
        {
            ch_println( ch, "You can't order them around." );
            return;
        }
    }

    if ( !str_cmp( "group", cmd_arg ) || !str_cmp( "follow", cmd_arg ) || !str_cmp( "party", cmd_arg ) || !str_cmp( "add", cmd_arg ) )
    {
        if ( victim->master != NULL )
        {
            interpret( victim, "say I am already following someone.", FALSE );
            ch_println( ch, "Better try someone else." );
            return;
        }

        if ( !isDroid )
            if ( count_ai_followers( ch ) >= calc_max_followers( ch ) )
            {
                ch_println( ch, "You have as many followers as you can have!" );
                return;
            }

        stop_follower( victim, false );
        add_follower( victim, ch, false );
        victim->leader = ch;
        ch_println( ch, "You give the command to follow." );
        act( AT_ACTION, "$n gives $N the command to follow $m.", ch, NULL, victim, TO_NOTVICT );
    }
    else if ( !str_cmp( "flee", cmd_arg ) )
    {
        ch_println( ch, "You give the order to flee." );
        act( AT_ACTION, "$n gives $N the command to flee.", ch, NULL, victim, TO_NOTVICT );
        do_flee( victim, "" );
    }
    else if ( !str_cmp( "setblaster", cmd_arg ) )
    {
        ch_println( ch, "You give the order to adjust blaster settings." );
        act( AT_ACTION, "$n gives $N the command to adjust blaster settings.", ch, NULL, victim, TO_NOTVICT );
        interpret( victim, line, FALSE );
    }
    else if ( !str_cmp( "currentcom", cmd_arg ) )
    {
        interpret( victim, line, FALSE );
        OBJ_DATA* tobj = victim->curr_comlink;

        if ( !tobj )
        {
            interpret( victim, "say Current comlink set to none.", FALSE );
        }
        else
        {
            snprintf( buf, MSL, "say Now using %s, which is tuned to %d.", tobj->short_descr, tobj->value[5] );
            interpret( victim, buf, FALSE );

            if ( tobj->value[4] != 0 )
            {
                snprintf( buf, MSL, "tell '%s' My comlink is encrypted with code %d.", ch->name, tobj->value[4] );
                interpret( victim, buf, FALSE );
            }
        }
    }
    else if ( !str_cmp( "emote", cmd_arg ) )
    {
        interpret( victim, line, FALSE ); // We are silent just to avoid spam
    }
    else if ( !str_cmp( "assist", cmd_arg ) || !str_cmp( "ignore", cmd_arg ) )
    {
        if ( !isDroid )
        {
            ch_println( ch, "Only droids can be ordered to assist." );
            return;
        }

        if ( tDB->active == 0 )
        {
            ch_println( ch, "That droid is disabled." );
            return;
        }

        if ( tDB->active == 1 )
        {
            ch_println( ch, "That droid is in a blind frenzy. You need an engineer to use UPGRADEDROID on it!" );
            return;
        }

        if ( !str_cmp( "ignore", cmd_arg ) )
        {
            if ( tDB->active == 3 )
            {
                snprintf( buf, MSL, "say I am already ignoring." );
            }
            else
            {
                tDB->active = 3;
                snprintf( buf, MSL, "say I will no longer assist." );
            }
        }

        if ( !str_cmp( "assist", cmd_arg ) )
        {
            if ( tDB->active == 2 )
            {
                snprintf( buf, MSL, "say I am already assisting." );
            }
            else
            {
                tDB->active = 2;
                snprintf( buf, MSL, "say I will now assist." );
            }
        }

        interpret( victim, buf, FALSE );
        save_droid( tDB, TRUE );
    }
    else if ( !str_cmp( "speak", cmd_arg ) || !str_cmp( "language", cmd_arg ) )
    {
        if ( !isDroid || tDB->mode != 2 )
        {
            ch_println( ch, "You can only order translation droids to speak other languages." );
            return;
        }

        if ( getDroidLevel( tDB->exp ) < 2 )
        {
            ch_println( ch, "Until translation droids reach level 2 they will only speak in basic." );
            return;
        }

        snprintf( buf, MSL, "speak %s", argument );
        interpret( victim, buf, FALSE );
        act( AT_ACTION, "$n instructs $s droid to speak another language.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You give the order to speak another language." );
        return;
    }
    else if ( !str_cmp( "tune", cmd_arg ) )
    {
        interpret( victim, line, FALSE );
        ch_println( ch, "You order them to '%s'.", line );
    }
    else if ( !str_cmp( "dismiss", cmd_arg ) || !str_cmp( "leave", cmd_arg ) )
    {
        if ( victim->master != ch && !isDroid )
        {
            interpret( victim, "You cannot dismiss me, sorry.", FALSE );
            ch_println( ch, "That person isn't following you." );
            return;
        }

        /* 
         * equivalent to follow self, in theroy, but less
         * prone to crashes if the pointers got messed up...
         * somehow... See issue #2646 ~Miros
         */
        stop_follower( victim, false );

        // do_follow( victim, "self" );

        if ( !isDroid )
        {
            interpret( victim, "salute", FALSE );
            ch_println( ch, "You dismiss them." );
            act( AT_ACTION, "$n dismisses $N.", ch, NULL, victim, TO_NOTVICT );
        }
        else
        {
            ch_println( ch, "You instruct your droid to stay here." );
            act( AT_ACTION, "$n instructs $s droid to stay here.", ch, NULL, NULL, TO_ROOM );
        }
    }
    else if ( !str_cmp( "block", cmd_arg ) )
    {
        if ( isDroid && tDB->mode != 1 )
        {
            ch_println( ch, "You need to configure your droid to focus on combat before you can do that." );
            return;
        }

        snprintf( buf, MSL, "block %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You order them to block." );
    }
    else if ( !str_cmp( "textcolor", cmd_arg ) )
    {
        interpret( victim, line, FALSE );
        ch_println( ch, "You order them to change their textcolor." );
        return;
    }
    else if ( !str_cmp( "kill", cmd_arg ) || !str_cmp( "attack", cmd_arg ) || !str_cmp( "murder", cmd_arg ) || !str_cmp( "fight", cmd_arg ) )
    {
        if ( isDroid && tDB->mode != 1 )
        {
            ch_println( ch, "You need to configure your droid to focus on combat before you can do that." );
            return;
        }
        else if ( !ch || !ch->in_room || NULLSTR( argument ) || ( vch = get_char_room( ch, argument ) ) == NULL )
        {
            ch_println( ch, "Target not found." );
            return;
        }

        if ( who_fighting( victim ) == NULL )
        {
            ch_println( ch, "You give the command to attack." );
            multi_hit( victim, vch, TYPE_UNDEFINED );
        }
        else
            ch_println( ch, "That trooper is already fighting." );
    }
    else if ( !str_cmp( "wear", cmd_arg ) || !str_cmp( "equip", cmd_arg ) || !str_cmp( "wield", cmd_arg ) )
    {
        if ( isDroid && tDB->mode != 1 )
        {
            ch_println( ch, "Only combat focused droids can use items." );
            return;
        }

        snprintf( buf, MSL, "%s %s", isDroid ? "wield" : "wear", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "unequip", cmd_arg ) || !str_cmp( "remove", cmd_arg ) )
    {
        snprintf( buf, MSL, "remove %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "drop", cmd_arg ) )
    {
        snprintf( buf, MSL, "drop %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "get", cmd_arg ) )
    {
        snprintf( buf, MSL, "get %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "put", cmd_arg ) )
    {
        snprintf( buf, MSL, "put %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "set", cmd_arg ) )
    {
        if ( isDroid && tDB->mode != 1 )
        {
            ch_println( ch, "You need to configure your droid to focus on combat before you can do that." );
            return;
        }

        snprintf( buf, MSL, "set %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "battery", cmd_arg ) )
    {
        snprintf( buf, MSL, "battery %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "use", cmd_arg ) )
    {
        snprintf( buf, MSL, "use %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "close", cmd_arg ) )
    {
        snprintf( buf, MSL, "close %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "open", cmd_arg ) )
    {
        snprintf( buf, MSL, "open %s", argument );
        interpret( victim, buf, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else if ( !str_cmp( "holster", cmd_arg ) || !str_cmp( "draw", cmd_arg ) )
    {
        if ( isDroid && tDB->mode != 1 )
        {
            ch_println( ch, "You need to configure your droid to focus on combat before you can do that." );
            return;
        }

        interpret( victim, line, FALSE );
        ch_println( ch, "You issue the command." );
    }
    else
    {
        ch_println( ch, "Command not recognized. Only specific commands work with duty, and they must be typed out fully." );
        return;
    }

    if ( cycle_char )
    {
        snprintf( buf, MSL, "squad all %s", line );
        interpret( ch, buf, FALSE );
        return;
    }
}

CMDF do_describearmor( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj = NULL;
    EXTRA_DESCR_DATA* ed = NULL;
    BUFFER_DATA* buffer = NULL;

    if ( !ch->desc )
    {
        bug( "do_describearmor: no descriptor", 0 );
        return;
    }

    if ( is_busy( ch ) )
    {
        ch_println( ch, "You are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            bug( "do_describearmor: illegal substate", 0 );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            break;

        case SUB_ARMOR_DESC:
            buffer = get_buffer( ch, FUNC );
            if ( !buffer ) return;
            ed = buffer->ed;
            dispose_buffer( buffer );
            SET_STRING( ed->description, copy_buffer( ch ) );
            stop_editing( ch, false );
            return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cdescarmor <&warmor&C>" );
        return;
    }

    if ( ( obj = get_obj_carry( ch, argument ) ) == NULL )
    {
        ch_println( ch, "I don't see that object here!" );
        return;
    }

    ed = SetOExtra( obj, "_armordesc_" );

    if ( obj->item_type != ITEM_ARMOR || obj->value[0] > 13 || obj->value[5] != 1 || !xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) )
    {
        ch_println( ch, "You can't add a description to that item." );
        return;
    }

    if ( obj->value[4] > 0 )
    {
        ch_println( ch, "This can only be done on finished equipment." );
        return;
    }

    ch->substate = SUB_ARMOR_DESC;
    buffer = create_buffer( ch, FUNC );
    buffer->ed = ed;
    ch_println( ch, "Enter the description." );
    start_editing( ch, FUNC, ed->description );
    return;
}

CMDF do_restring( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj = NULL;
    char arg[MIL], arg2[MIL], buf[MIL];
    DB_DATA* db = NULL;
    argument = one_argument( argument, arg );

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Usage: restring <item keyword> <new string>" );
        ch_println( ch, "Keep in mind all restrings are tracked.\nAny abuse of this skill will result in hefty punishments." );
        return;
    }

    obj = get_obj_carry( ch, arg );

    if ( !obj )
    {
        ch_println( ch, "You aren't carrying an object like that." );
        return;
    }

    if ( obj->item_type != ITEM_ARMOR && obj->item_type != ITEM_CONTAINER && obj->item_type != ITEM_COOKWARE )
    {
        ch_println( ch, "You can only restring armor, containers, and cookware." );
        return;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_RESTRUNG ) )
    {
        ch_println( ch, "This piece of equipment has already been restrung." );
        return;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_NORESTRING ) )
    {
        ch_println( ch, "This piece of equipment is unable to be restrung." );
        return;
    }

    if ( xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) ) //This path is for how restring works as we used to know it, adding the blueprint.
    {
        if ( obj->value[0] > 13 || obj->value[5] != 1 )
        {
            ch_println( ch, "You can't restring that item." );
            return;
        }

        if ( obj->value[4] > 0 )
        {
            ch_println( ch, "This can only be done on finished equipment." );
            return;
        }

        if ( strlen( stripclr( argument ) ) < strlen( argument ) )
        {
            ch_println( ch, "The new string may not contain any color tokens." );
            return;
        }

        if ( strlen( argument ) < 10 || count_args( argument ) < 2 )
        {
            ch_println( ch, "You need to make the string two or more words and no less than ten letters long." );
            return;
        }

        one_argument( argument, arg2 );

        if ( str_cmp( "a", arg2 ) && str_cmp( "an", arg2 ) )
        {
            ch_println( ch, "Please start the string off with either A or AN." );
            return;
        }

        if ( strlen( argument ) > 50 )
        {
            ch_println( ch, "That string is too long. Keep it under 30 letters long." );
            return;
        }

        separate_obj( obj );
        CREATE( db, DB_DATA, 1 );
        SET_STRING( db->name, "" );
        SET_STRING( db->str1, ch->name );
        SET_STRING( db->str2, argument );
        LINK( db, first_restring, last_restring, next, prev );
        save_dbase_sql( DB_TABLE_RESTRING, db );
        argument = capitalize( argument );

        if ( !obj->vars )
            CREATE( obj->vars, DVAR_LIST, 1 );

        set_dvar_string( obj->vars, "OGBlueprint", obj->blueprint, 0 );
        set_dvar_string( obj->vars, "RestrungBy", ch->name, 0 );
        set_dvar_string( obj->vars, "RestrungTo", argument, 0 );
        set_dvar_timestamp( obj->vars, "RestrungAt", current_time, 0 );

        SET_STRING( obj->blueprint, argument );
        xSET_BIT( obj->extra_flags, ITEM_RESTRUNG );
        ch_println( ch, "Your armor is now restrung as '%s'.", argument );
    }
    else if ( obj->item_type == ITEM_ARMOR || obj->item_type == ITEM_CONTAINER || obj->item_type == ITEM_COOKWARE ) //This path is new path of restring that renames items.
    {
        if ( obj->pIndexData->vnum == OBJ_VNUM_SHOPPING_BAG )
        {
            ch_println( ch, "You can't restring these shopping bags." );
            return;
        }

        if ( xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) )
        {
            ch_println( ch, "You can't restring helmets." );
            return;
        }
        else if ( xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
        {
            ch_println( ch, "You can't restring crafted items." );
            return;
        }

        // When checking for top-layer items, only check if the item is actually in a layerable slot.
        if ( xIS_SET( obj->wear_flags, ITEM_WEAR_BODY )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_LEGS )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_FEET )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_HANDS )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_ARMS )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_BACK )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_OVER )
                || xIS_SET( obj->wear_flags, ITEM_WEAR_WAIST )
           )
        {
            if ( obj->pIndexData->layers != 128 && obj->item_type == ITEM_ARMOR && !xIS_SET( obj->extra_flags, ITEM_RESTRINGABLE ) )
            {
                ch_println( ch, "You can only restring top layer armor or objects set specifially to allow it." );
                return;
            }
        }
        separate_obj( obj );

        if ( !obj->vars )
            CREATE( obj->vars, DVAR_LIST, 1 );

        set_dvar_string( obj->vars, "OGShortDesc", obj->short_descr, 0 );
        set_dvar_string( obj->vars, "RestrungBy", ch->name, 0 );
        set_dvar_string( obj->vars, "RestrungTo", argument, 0 );
        set_dvar_timestamp( obj->vars, "RestrungAt", current_time, 0 );       

        strlcpy( buf, obj->name, MIL );
        strlcpy( buf, argument, MIL );
        SET_STRING( obj->name, stripclr( buf ) );
        strlcpy( buf, argument, MIL );
        SET_STRING( obj->short_descr, buf );
        strlcat( buf, " is here on the ground nearby.", MIL );
        SET_STRING( obj->description, buf );
        xSET_BIT( obj->extra_flags, ITEM_RESTRUNG );
        CREATE( db, DB_DATA, 1 );
        SET_STRING( db->name, "" );
        SET_STRING( db->str1, ch->name );
        SET_STRING( db->str2, argument );
        LINK( db, first_restring, last_restring, next, prev );
        save_dbase_sql( DB_TABLE_RESTRING, db );
        ch_println( ch, "Your equipment is now stringed as '%s'.", argument );

    }

    if ( get_learned_pct( ch, cache_skill( "restring", &skill_restring ) ) < 100 )
    {
        set_learned_pct( ch, cache_skill( "restring", &skill_restring ), 99 );
        learn_from_success( ch, cache_skill( "restring", &skill_restring ) );
    }
    if (db)
        save_dbase_sql(DB_TABLE_RESTRING,db);
    //save_restring();
    return;
}

int stealship_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop trying to steal the ship." );
    act( AT_ACTION, "$n stops manipulating the ship.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int stealship_complete( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    SHIP_DATA* ship = get_ship_from_cockpit( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "You need to be in the cockpit of a ship to steal one." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( number_percent() > get_learned_pct( ch, cache_skill( "pirateship", &skill_pirateship ) ) )
    {
        ch_println( ch, "&wDespite your best efforts, you were unable to steal the ship.&w" );
        learn_from_failure( ch, cache_skill( "pirateship", &skill_pirateship ) );
        return E_LOTJ_SUCCESS;
    }

    squadron_remove( ship, NULL );
    SET_STRING( ship->stolen, ch->name );
    ch_println( ch, "You have successfully stolen %s.", ship->name );
    act( AT_ACTION, "$n finishes stealing the ship.", ch, NULL, NULL, TO_ROOM );
    learn_from_success( ch, cache_skill( "pirateship", &skill_pirateship ) );
    save_ship( ship, true );

    return E_LOTJ_SUCCESS;
}

CMDF do_stealship( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    argument = one_argument( argument, arg1 );

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "NPCs can't steal ships." );
        return;
    }

    if ( !str_cmp( arg1, "release" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cpirateship" );
            ch_println( ch, "&z        &Cpirateship release <&wship name&C>" );
            return;
        }

        SHIP_DATA* ship = stolen_ship( ch, argument );
        if ( !ship )
        {
            ch_println( ch, "That is not a ship that you have stolen." );
            return;
        }

        ch_println( ch, "You relinquish your hold on your stolen ship." );
        SET_STRING( ship->stolen, "" );
        save_ship( ship, true );
        return;
    }

    if ( !can_steal_ship( ch ) )
    {
        ch_println( ch, "You are unable to steal any more ships.\nType PIRATESHIP RELEASE to relinquish your claim to it.\nYou can see info on it using SHIPS OWNED." );
        return;
    }

    SHIP_DATA* ship = get_ship_from_cockpit( ch->in_room );
    if ( !ship )
    {
        ch_println( ch, "&RYou need to be in the cockpit of a ship to do that." );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_VONG ) && !xIS_SET( ch->race->flags, RFLAG_VONG ) )
    {
        ch_println( ch, "&RHow do you expect to steal a ship you can't even fly?&w" );
        return;
    }

    if ( xIS_SET( ship->flags, SHIP_LEGENDARY ) )
    {
        ch_println( ch, "&RLegendary ships cannot be stolen.&w" );
        return;
    }

    //Changed to allow gunships/Corvettes to be pirated. -Gathorn 7May16
    if ( ship->classtype > CORVETTE_SHIP )
    {
        ch_println( ch, "You can't steal capital ships." );
        return;
    }

    //Dumb players pirating pirate ships to stripship them and control them - Gathorn 14Nov18
    if ( !str_cmp( ship->shipowner, "Pirate" ) || !str_cmp( ship->shipowner, "pirate" ) || !str_cmp( ship->shipowner, "Pirates" ) )
    {
        ch_println( ch, "You can't steal a pirate ship!" );
        return;
    }

    int delay = 35 - get_learned_pct( ch, cache_skill( "pirateship", &skill_pirateship ) ) / 5;
    add_timer( ch, TIMER_DO_FUN, delay*3, stealship_complete, stealship_abort, FUNC );

    if ( ship->in_room && xIS_SET( ship->flags, SHIP_SECURED ) )
        alarm_ship( ch, ship, "stolen" );

    ch_println( ch, "You begin to steal the ship." );
    act( AT_ACTION, "$n begins to steal the ship.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is stealing the ship.", NULL, 0 );
}

int security_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop enabling security." );
    return E_LOTJ_SUCCESS;
}

int security_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    OBJ_DATA* datapad = get_obj_from_buffer( buffer, "datapad" );
    char buf[MSL];

    if ( xIS_SET( ch->in_room->flags, ROOM_SECURITY ) )
    {
        ch_println( ch, "This room already has security." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    drain_datapad( datapad );

    if ( number_percent() > get_learned_pct( ch, cache_skill( "security", &skill_security ) ) )
    {
        ch_println( ch, "You fail to get the security routines right." );
        learn_from_failure( ch, cache_skill( "security", &skill_security ) );
        return E_LOTJ_SUCCESS;
    }

    ch->in_room->security_rating = get_security_rating( ch, false, false );
    get_rating_string( buf, ch->in_room->security_rating );
    xSET_BIT( ch->in_room->flags, ROOM_SECURITY );
    save_room( ch->in_room, true );
    ch_println( ch, "You enable %s security routines for this spot.", buf );
    act( AT_ACTION, "$n's datapad chimes.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "security", &skill_security ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_security( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    if ( IS_NPC( ch ) )
        return;

    OBJ_DATA* datapad = get_datapad( ch );
    if ( !datapad )
        return;

    if ( datapad->value[0] < 3 )
    {
        ch_println( ch, "Your datapad's mode is too weak to do this." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SECURITY ) )
    {
        ch_println( ch, "This room already has security." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_CAN_LAND ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CLANPAD ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CAN_FLY ) &&
            !xIS_SET( ch->in_room->flags, ROOM_HIDDEN_LAND ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CAN_SECURITY ) )
    {
        tune( "security: %s tried to secure a non-securable room: %d", ch->name, ch->in_room->vnum );
        //Previously had a message that didn't really tell you why this skill wasn't working. It now points people in a direction the skill is typically used for. -Gathorn 7May16
        ch_println( ch, "This room is not capable of supporting a security network. Try looking for a landing pad." );
        return;
    }

    int delay = 25 - get_learned_pct( ch, cache_skill( "security", &skill_security ) ) / 5;
    if ( valid_focus( ch, SLICER_ABILITY ) )
        delay -= ( int )( delay / 4 );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, delay*3, security_complete, security_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "datapad", datapad );

    ch_println( ch, "You begin to add security to the room." );
	act( AT_ACTION, "$n begins working on $s datapad.", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is busy on $s datapad.", NULL, 0 );
}

int disable_security_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop disabling security." );
    return E_LOTJ_SUCCESS;
}

int disable_security_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char buf[MSL];
    OBJ_DATA* datapad = get_obj_from_buffer( buffer, "datapad" );

    if ( !xIS_SET( ch->in_room->flags, ROOM_SECURITY ) )
    {
        ch_println( ch, "This room already has no security." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    drain_datapad( datapad );
    int security_rating = try_slice( ch, MODULATION_MSTR_ROOM, ch->in_room, ch->in_room->security_rating, false );
    int skill = ( int ) get_learned_pct( ch, cache_skill( "disable_security", &skill_disable_security ) );

    if ( number_percent() >= skill || security_rating == 0 )
    {
        if ( number_percent() > 50 )
            alarm_room( ch->in_room, "security system tampering detected at" );

        ch_println( ch, "You fail to disable security." );
        learn_from_failure( ch, cache_skill( "disable_security", &skill_disable_security ) );
        return E_LOTJ_SUCCESS;
    }

    xREMOVE_BIT( ch->in_room->flags, ROOM_SECURITY );
    save_room( ch->in_room, true );
    get_rating_string( buf, ch->in_room->security_rating );
    ch_println( ch, "You disable %s security routines for this spot.", buf );
    act( AT_ACTION, "$n's datapad chimes.", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, cache_skill( "disable_security", &skill_disable_security ), 2 );
    return E_LOTJ_SUCCESS;
}

CMDF do_disable_security( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    OBJ_DATA* datapad = get_datapad( ch );
    if ( !datapad )
        return;

    if ( datapad->value[0] < 4 )
    {
        ch_println( ch, "Your datapad's mode is too weak to do this." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_SECURITY ) )
    {
        ch_println( ch, "This room already has no security." );
        return;
    }

    if ( !xIS_SET( ch->in_room->flags, ROOM_CAN_LAND ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CLANPAD ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CAN_FLY ) &&
            !xIS_SET( ch->in_room->flags, ROOM_HIDDEN_LAND ) &&
            !xIS_SET( ch->in_room->flags, ROOM_CAN_SECURITY ) )
    {
        tune( "security: %s tried to secure a non-securable room: %d", ch->name, ch->in_room->vnum );
        ch_println( ch, "This room wouldn't support a security system. Try on a landing pad." );
        return;
    }

    int delay = try_slice( ch, MODULATION_MSTR_ROOM, ch->in_room, ch->in_room->security_rating, true );
    if ( delay == 0 )
        delay = 30;
    if ( valid_focus( ch, SLICER_ABILITY ) )
        delay -= ( int )( delay / 4 );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, delay*3, disable_security_complete, disable_security_abort, FUNC );
    add_obj_to_buffer( timer->buffer, "datapad", datapad );

    ch_println( ch, "You begin to disable security in the room." );
	act( AT_ACTION, "$n begins working on $s datapad.", ch, NULL, NULL, TO_ROOM );
	action_set( ch, NULL, "is busy on $s datapad.", NULL, 0 );
}

CMDF do_rally( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* vch = NULL;
    AFFECT_DATA af;
    int x = 0;

    if ( IS_AFFECTED( ch, AFF_RALLY ) )
    {
        ch_println( ch, "You can't rally your party members just yet." );
        return;
    }

    if ( count_group( ch ) == 0 )
    {
        gen_message( ch, "nogroup" );
        return;
    }

    //if ( !ap_drain( ch, 7 ) )
    //  return;
    x = IS_NPC( ch ) ? 0 : ( int ) get_learned_pct( ch, cache_skill( "rally", &skill_rally ) );

    if ( number_percent() > x )
    {
        ch_println( ch, "You fail to rouse the spirits of your party members." );
        act( AT_ACTION, "$n tries to rouse the spirits of $s party members, but fails.", ch, NULL, NULL, TO_ROOM );
        learn_from_failure( ch, cache_skill( "rally", &skill_rally ) );
        return;
    }

    af.type = cache_skill( "rally", &skill_rally )->id;
    af.location = 0;
    af.modifier = 0;
    af.duration = number_range( 10, 120 );
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_RALLY );
    affect_join( ch, CHAR_AFFECT, &af );
    act( AT_ACTION, "$n cries out, rallying $s party members!", ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
    {
        if ( vch->leader != ch && vch != ch )
            continue;

        x = ( int ) ( 2 * ( vch->max_hit / 10 ) );
        vch->hit += UMIN( vch->max_hit - vch->hit, x );
    }

    ch_println( ch, "You rally your party members!" );
    learn_from_success( ch, cache_skill( "rally", &skill_rally ) );
}
