int count_group( CHAR_DATA* ch )
{
    CHAR_DATA* vch = NULL;
    int cnt = 0;

    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
        if ( vch->leader == ch )
            cnt++;

    if ( cnt > 0 )
        cnt++;

    return cnt;
}
