void scrap_disguise( CHAR_DATA* ch )
{
    OBJ_DATA* tobj = create_object( get_obj_index( OBJ_VNUM_BLANK ), 1 );
    SET_STRING( tobj->name, "disguise" );
    SET_STRING( tobj->short_descr, "A disguise" );
    SET_STRING( tobj->description, "A disguise." );
    xCLEAR_BITS( tobj->wear_flags );
    obj_to_char( tobj, ch );
    separate_obj( tobj );
    tobj = make_scraps( tobj );
    // Now clear disguise from the player
    ch->disguise = NULL;
    return;
}

// Allows players to add a description to crafted items to give them more of a personal touch.

CMDF do_describeitem( CHAR_DATA* ch, char* argument )
{
    BUFFER_DATA* buffer = NULL;
    OBJ_DATA* obj = NULL;
    EXTRA_DESCR_DATA* ed = NULL, *ed2 = NULL;
    char buf[MSL];
    char arg[MSL];

    if ( is_busy( ch ) )
    {
        ch_println( ch, "You are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            bug( "do_describeitem: illegal substate", 0 );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            break;

        case SUB_ITEM_DESC:
            buffer = get_buffer( ch, FUNC );
            if ( !buffer || !buffer->ed ) return;
            ed = buffer->ed;
            ed2 = ed->prev;
            dispose_buffer( buffer );

            do
            {
                if ( !ed->custom_ed )
                    SET_STRING( ed->description, copy_buffer( ch ) );

                ed = ed->next;
            } while ( ed != ed2 );

            stop_editing( ch, false );
            return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cdescitem <&wobject&C>\n&zSyntax: &Cdescitem <&wobject&C> lock&w" );
        return;
    }

    argument = one_argument( argument, arg );

    if ( ( obj = get_obj_carry( ch, arg ) ) == NULL )
    {
        ch_println( ch, "I don't see that object here!" );
        return;
    }

    if ( !xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
    {
        ch_println( ch, "&RYou can only add a description to player crafted items.&w" );
        return;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_DESCLOCK ) )
    {
        ch_println( ch, "%s&w has had its description locked into place.&w", obj->short_descr );
        return;
    }

    if ( !str_cmp( argument, "lock" ) )
    {
        xSET_BIT( obj->extra_flags, ITEM_DESCLOCK );
        ch_println( ch, "&wYou have locked the description for %s.&w", obj->short_descr );
        return;
    }

    one_argument( obj->name, buf );
    ed = SetOExtraCustom( obj, obj->name, FALSE );
    ch->substate = SUB_ITEM_DESC;
    buffer = create_buffer( ch, FUNC );
    buffer->ed = ed;
    ch_println( ch, "Enter the description." );
    start_editing( ch, FUNC, ed->description );
    return;
}

CMDF do_setdraw( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj = NULL;
    char arg[MSL];
    char buf[MSL];
    argument = one_argument( argument, arg );

    if ( argument[0] == '\0' || arg[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Csetdraw <&wobject&C> <&wdraw message&C>" );
        return;
    }

    if ( ( obj = get_obj_carry( ch, arg ) ) == NULL )
    {
        ch_println( ch, "I don't see that object here!" );
        return;
    }

    if ( obj->item_type != ITEM_WEAPON )
    {
        ch_println( ch, "&RYou can only add a draw message to a weapon!" );
    }

    if ( !xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
    {
        ch_println( ch, "&RYou can only add a draw message to player crafted weapons.&w" );
        return;
    }

    //I think this is to avoid token shenanigans. It's in oset action_desc.
    if ( strstr( argument, "%" ) )
    {
        ch_println( ch, "&RDraw messages cannot contain a %." );
        return;
    }

    for ( unsigned int i = 0; i < strlen( argument ); i++ )
    {
        if (
            argument[i] == '$' &&
            argument[i + 1] != 'n' &&
            argument[i + 1] != 'e' &&
            argument[i + 1] != 'm' &&
            argument[i + 1] != 's' &&
            argument[i + 1] != 'p'
        )
        {
            ch_println( ch, "&RIllegal $ token in draw message. Only $n, $e, $m, $s and $p may be used." );
            return;
        }
    }

    if ( !str_cmp( argument, "clear" ) )
    {
        if ( obj->value[3] == WEAPON_LIGHTSABER )
        {
            snprintf( buf, MSL, "%s ignites with a hum and a soft glow.", obj->short_descr );
            SET_STRING( obj->action_desc, buf );
            ch_println( ch, "You have reset the draw message for %s to %s&w", obj->short_descr, obj->action_desc );
            return;
        }
        else
        {
            SET_STRING( obj->action_desc, "" );
            ch_println( ch, "You have cleared the draw message for %s.&w", obj->short_descr );
            return;
        }
    }
    else
    {
        SET_STRING( obj->action_desc, argument );
        ch_println( ch, "You have set the draw message for %s to %s&w", obj->short_descr, obj->action_desc );
    }

    return;
}

// A standard function for processing exp gains from completing a skill.
// This handles phasing out xp past a certain level based on what level the skill is at.
// skill_num: The SN of the skill they've just used
// base_level_pct: At the level they learned the skill, what percent of a level worth of xp should they get.
// max_levels_past_learned: How many levels past the skill's learnable level they are eligible to get xp.
//   Percent of a level drops as they approach max_levels_past_learned.
//   Optional. If 0, no max.
void gain_exp_from_skill( CHAR_DATA* ch, const char* skill_name, int base_level_pct, int max_levels_past_learned )
{
    SKILL_DATA* skill = skill_from_name(skill_name);
    if ( !skill )
    {
        bug( "gain_exp_from_skill: invalid skill_name %s", skill_name );
        return;
    }

    if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
    {
        bug( "gain_exp_from_skill: skill %s belongs to invalid class %d", skill_name, skill->guild );
        return;
    }

    int current_level = ch->skill_level[skill->guild];
    int learned_level = skill->min_level;

    // How much xp one needs to go from learned_level to the next level
    int learned_level_advance_xp = exp_level( learned_level+1 ) - exp_level( learned_level );
    int xp_gain = learned_level_advance_xp * base_level_pct / 100;

    if ( max_levels_past_learned > 0 )
    {
        // They've leveled too far past the skill to gain xp from it
        if ( current_level - learned_level > max_levels_past_learned )
            return;

        // How many levels the ch can gain before the skill stops granting xp
        // As they approach that level (within 5 of it), xp drops by up to 80%.
        int levels_left = (learned_level + max_levels_past_learned) - current_level;
        if ( levels_left <= 5 )
            xp_gain = xp_gain * levels_left / 5;
    }

    if ( xp_gain > 0 )
    {
        ch_println( ch, "&WYou gain %d %s experience.", xp_gain, flag_value_name( ability_name, skill->guild ) );
        gain_exp( ch, xp_gain, skill->guild, false );
    }
}

