/*
    Toggle "Do Not Disturb" flag. Used to prevent lower level imms from
    using commands like "trans" and "goto" on higher level imms.
*/
CMDF do_dnd( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    if ( !IS_NPC( ch ) && ch->pcdata )
        if ( has_pcflag( ch, PCFLAG_DND ) )
        {
            xREMOVE_BIT( ch->pcdata->flags, PCFLAG_DND );
            ch_println( ch, "Your 'do not disturb' flag is now off." );
        }
        else
        {
            xSET_BIT( ch->pcdata->flags, PCFLAG_DND );
            ch_println( ch, "Your 'do not disturb' flag is now on." );
        }
    else
        ch_println( ch, "huh?" );
}

CMDF do_wizhelp( CHAR_DATA* ch, char* argument )
{
    CMDTYPE* cmd;
    int col, hash, level, title, slevel;
    slevel = get_trust( ch );

    for ( level = slevel; level > 100; level-- )
    {
        /*
            Skips over the 106-199 Range
        */
        if ( level > 110 && level <= 200 )
            level = 110;

        col = 0;
        title = 0;

        for ( hash = 0; hash < 126; hash++ )
            for ( cmd = command_hash[hash]; cmd; cmd = cmd->next )
                if ( cmd->level == level )
                {
                    if ( argument[0] != '\0' && !stristr( cmd->name, argument ) )
                        continue;

                    if ( title == 0 )
                    {
                        ++title;
                        pager_printf( ch, "&z--&CLevel %d&z-----------------------------------------------------\n",
                                      level );
                    }

                    pager_printf( ch, "&B%-15s", cmd->name );

                    if ( ++col % 5 == 0 )
                        send_to_pager( "\n", ch );
                }

        if ( col % 5 != 0 )
            send_to_pager( "\n", ch );
    }

    return;
}

CMDF do_restrict( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char arg2[MIL];
    char buf[MSL];
    sh_int level, hash;
    CMDTYPE* cmd;
    bool found;
    found = FALSE;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Restrict which command?" );
        return;
    }

    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg2 ) )
        level = get_trust( ch );
    else
        level = atoi( arg2 );

    level = UMAX( UMIN( get_trust( ch ), level ), 0 );
    hash = arg[0] % 126;

    for ( cmd = command_hash[hash]; cmd; cmd = cmd->next )
    {
        if ( !str_prefix( arg, cmd->name ) && cmd->level <= get_trust( ch ) )
        {
            found = TRUE;
            break;
        }
    }

    if ( found )
    {
        if ( !str_prefix( arg2, "show" ) )
        {
            snprintf( buf, MSL, "%s show", cmd->name );
            do_cedit( ch, buf );
            /*          ch_println( ch, "%s is at level %d.", cmd->name, cmd->level );*/
            return;
        }

        cmd->level = level;
        ch_println( ch, "You restrict %s to level %d", cmd->name, level );
        snprintf( buf, MSL, "%s restricting %s to level %d", ch->name, cmd->name, level );
        log_string( buf );
    }
    else
        ch_println( ch, "You may not restrict that command." );

    return;
}

/*
    Check if the name prefix uniquely identifies a char descriptor
*/
CHAR_DATA* get_waiting_desc( CHAR_DATA* ch, char* name )
{
    DESCRIPTOR_DATA* d;
    CHAR_DATA* ret_char = NULL;
    static unsigned int number_of_hits;
    number_of_hits = 0;

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->character && ( !str_prefix( name, d->character->name ) ) && IS_WAITING_FOR_AUTH( d->character ) )
        {
            if ( ++number_of_hits > 1 )
            {
                ch_println( ch, "%s does not uniquely identify a char.", name );
                return NULL;
            }

            ret_char = d->character;    /* return current char on exit */
        }
    }

    if ( number_of_hits == 1 )
        return ret_char;
    else
    {
        ch_println( ch, "No one like that waiting for authorization." );
        return NULL;
    }
}

CMDF do_authorize( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char buf[MSL];
    CHAR_DATA* victim;
    DESCRIPTOR_DATA* d;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "Usage:  authorize <player> <yes|name|immsim|mobsim|swear|plain|no/deny>" );
        ch_println( ch, "Pending authorizations:" );
        ch_println( ch, " Chosen Character Name" );
        ch_println( ch, "---------------------------------------------" );

        for ( d = first_descriptor; d; d = d->next )
            if ( ( victim = d->character ) != NULL && IS_WAITING_FOR_AUTH( victim ) )
                ch_println( ch, " %s@%s new %s...",
                           victim->name, victim->desc->host, victim->race->race_name );

        return;
    }

    victim = get_waiting_desc( ch, arg1 );

    if ( victim == NULL )
        return;

    if ( arg2[0] == '\0' || !str_cmp( arg2, "accept" ) || !str_cmp( arg2, "yes" ) )
    {
        victim->pcdata->auth_state = 3;
        xREMOVE_BIT( victim->pcdata->flags, PCFLAG_UNAUTHED );
        SET_STRING( victim->pcdata->authed_by, ch->name );
        snprintf( buf, MSL, "%s authorized %s", ch->name, victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( ch, "You have authorized %s.", victim->name );
        /*
            Below sends a message to player when name is accepted - Brittany
        */
        ch_println( victim,
                   "The MUD Administrators have accepted the name %s."
                   "You are now fully authorized to play Star Wars: Legends of the Jedi.\n", victim->name );
        return;
    }
    else if ( !str_cmp( arg2, "immsim" ) || !str_cmp( arg2, "i" ) )
    {
        victim->pcdata->auth_state = 2;
        snprintf( buf, MSL, "%s: name denied - similar to Imm name", victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( victim,
                   "The name you have chosen is too similar to that of a current immortal."
                   "We ask you to please choose another name using the name command.\n" );
        ch_println( ch, "You requested %s change names.", victim->name );
        return;
    }
    else if ( !str_cmp( arg2, "mobsim" ) || !str_cmp( arg2, "m" ) )
    {
        victim->pcdata->auth_state = 2;
        snprintf( buf, MSL, "%s: name denied - similar to mob name", victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( victim,
                   "The name you have chosen is too similar to that of certain"
                   "monsters in the game, in the long run this could cause problems\n"
                   "and therefore we are unable to authorize them.  Please choose\n"
                   "another name using the name command.\n" );
        ch_println( ch, "You requested %s change names.", victim->name );
        return;
    }
    else if ( !str_cmp( arg2, "swear" ) || !str_cmp( arg2, "s" ) )
    {
        victim->pcdata->auth_state = 2;
        snprintf( buf, MSL, "%s: name denied - swear word", victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( victim,
                   "We will not authorize names containing swear words, in any language."
                   "Please choose another name using the name command.\n" );
        ch_println( ch, "You requested %s change names.", victim->name );
        return;
    }
    else if ( !str_cmp( arg2, "plain" ) || !str_cmp( arg2, "p" ) )
    {
        victim->pcdata->auth_state = 2;
        snprintf( buf, MSL, "%s: name denied", victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( victim,
                   "We would ask you to please attempt to choose a name that is more"
                   "Star Wars in nature.  Please choose another name using the name\n" "command.\n" );
        ch_println( ch, "You requested %s change names.", victim->name );
        return;
    }
    else if ( !str_cmp( arg2, "no" ) || !str_cmp( arg2, "deny" ) )
    {
        ch_println( victim, "You have been denied access." );
        snprintf( buf, MSL, "%s denied authorization to %s", ch->name, victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_println( ch, "You have denied %s.", victim->name );
        do_quit( victim, "" );
    }
    else if ( !str_cmp( arg2, "name" ) || !str_cmp( arg2, "n" ) )
    {
        snprintf( buf, MSL, "%s has denied %s's name", ch->name, victim->name );
        to_channel( buf, CHANNEL_MONITOR, "Monitor", ch->top_level );
        ch_printf( victim,
                   "The MUD Administrators have found the name %s "
                   "to be unacceptable.\n" "Use 'name' to change it to something more appropriate.\n", victim->name );
        ch_println( ch, "You requested %s change names.", victim->name );
        victim->pcdata->auth_state = 2;
        return;
    }
    else
    {
        ch_println( ch, "Invalid argument." );
        return;
    }
}

