/*
         New MUD Statistics for LOTJ ;)
    ... The main interface command is LSTAT ...
             -=# Added by Ghost #=-
*/
CMDF do_lstat( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    DB_DATA* db = NULL;
    int cnt = 0;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &CLSTAT <&wStatistic&C>&w" );
        ch_println( ch, "&zValid Statistic types:" );
        ch_println( ch, "&C   Keys      &z-&w display all keys in the game&w" );
        ch_println( ch, "&C   Files     &z-&w File information && sizes &C(&wDisabled&C)&w" );
        ch_println( ch, "&C   Homes     &z-&w List homes and their info&w" );
        ch_println( ch, "&C   Clearship &z-&w clear expired ships&w" );
        ch_println( ch, "&C   Furniture &z-&w list all pieces of furniture&w" );
        ch_println( ch, "&C   Pturrets  &z-&w display all pturrets&w" );
        ch_println( ch, "&C   Wed       &z-&w Show all married couples" );
        ch_println( ch, "&C   Restring  &z-&w List restrings&w" );
        ch_println( ch, "&C   Shipcount &z-&w count all ships in game &C(&wstored and active&C)&w" );
        ch_println( ch, "&C   Vendor    &z-&w See all vendors in the game&w" );
        ch_println( ch, "&C   Mset      &z-&w see what has been mset recently&w" );
        ch_println( ch, "&z---- &wSeemingly Unused Stuff &z----" );
        ch_println( ch, "&B Jams, oaverage, maverage, challenges&w" );
        return;
    }

    if ( !str_cmp( arg, "keys" ) )
    {
        lstat_keys( ch );
    }
    else if ( !str_cmp( "pturrets", arg ) )
    {
        for ( TURRET_DATA* turret = first_pturret; turret; turret = turret->next )
        {
            PLANET_DATA* planet = NULL;

            if ( !turret->room || room_extracted( turret->room ) )
                continue;

            cnt++;
            planet = get_planet_from_room( turret->room );

            if ( !planet )
                continue;

            ch_println( ch, "(%s:%d) %d %s", planet ? planet->name : "No planet", cnt, turret->laserstate,
                       turret->target ? turret->target->name : "no target" );
        }

        ch_println( ch, "Displayed a total of %d pturrets.", cnt );
        return;
    }

    else if ( !str_cmp( "restring", arg ) )
    {
        if ( NULLSTR( argument ) )
        {
            cnt = 41;

            for ( db = last_restring; db && --cnt > 0; db = db->prev )
                ch_println( ch, "&zRestrung by: &C%s &zString: &w%s&w", db->str1, db->str2 );
        }
        else
            for ( db = last_restring; db; db = db->prev )
                if ( strstr( db->str1, argument ) || strstr( db->str2, argument ) )
                    ch_println( ch, "&zRestring by: &C%s &zString: &w%s&w", db->str1, db->str2 );

        return;
    }
    else if ( !str_cmp( "shipcount", arg ) )
    {
        SHIP_DATA* ship = NULL;
        int tot = 0;

        for ( ship = first_ship; ship; ship = ship->next )
            cnt++;

        ch_println( ch, "&z   Active ships: &C%d", cnt );
        tot += cnt;
        cnt = 0;

        for ( ship = first_drydock; ship; ship = ship->next )
            cnt++;

        tot += cnt;
        ch_println( ch, "&zDrydocked ships: &Y%d\n&z    Total ships: &C%d", cnt, tot );
        return;
    }
    else if ( !str_cmp( "mset", arg ) )
    {
        if ( NULLSTR( argument ) )
        {
            for ( db = last_mset; db; db = db->prev )
                if ( db->num1 <= get_trust( ch ) )
                {
                    if ( ++cnt == 100 )
                        break;

                    ch_println( ch, "&w&z[&C%d&z] Set by: &C%s &zSet: &C%s &zType: &w%s", db->id, db->name, db->str1,
                               db->str2 );
                }
        }
        else
        {
            for ( db = last_mset; db; db = db->prev )
                if ( db->num1 <= get_trust( ch ) )
                    if ( strstr( db->str1, argument )
                            || ++cnt == atoi( argument )
                            || !str_cmp( db->name, argument )
                            || ( cnt == 100 && str_cmp( "full", argument ) )
                            || !str_cmp( db->str2, argument ) || atoi( argument ) == db->num1 )
                        ch_println( ch, "&w&z[&C%d&z] Set by: &C%s &zSet: &C%s &zType: &w%s", db->id, db->name,
                                   db->str1, db->str2 );

            if ( cnt == atoi( argument ) )
                ch_println( ch, "&zShowed &C%d&z most recent mset entries.&w", ch );
        }
    }
    else if ( !str_cmp( "vendor", arg ) )
    {
        time_t tm;

        if ( NULLSTR( argument ) )
        {
            for ( VENDOR_DATA* vendor = first_vendor; vendor; vendor = vendor->next )
            {
                tm = current_time - vendor->last_active;
                tm /= 86400;
                ch_println( ch, "&zVendor in room: &C%d&z Owned by &C%s&z.%s",
                vendor->home ? vendor->home->vnum : ( vendor->mob && vendor->mob->in_room ? vendor->mob->in_room->vnum : -1),
                vendor->owner, tm > 7 ? " &R(Inactive)&w" : "" );
            }
        }
        else
        {
            for ( VENDOR_DATA* vendor = first_vendor; vendor; vendor = vendor->next )
                if ( !str_cmp( vendor->owner, argument ) )
                {
                    tm = current_time - vendor->last_active;
                    tm /= 86400;
                    ch_println( ch, "&zVendor in room: &C%d&z Owned by &C%s&z.%s",
                    vendor->home ? vendor->home->vnum : ( vendor->mob && vendor->mob->in_room ? vendor->mob->in_room->vnum : -1),
                    vendor->owner, tm > 7 ? " &R(Inactive)&w" : "" );
                }
        }
    }
    else if ( !str_cmp( "furniture", arg ) )
    {
        do_flist( ch, "" );
        return;
    }
    else if ( !str_cmp( "clearship", arg ) )
    {
        SHIP_DATA* ship = NULL;
        char buf[MSL];

        for ( ship = first_ship; ship; ship = ship->next )
        {
            snprintf( buf, MSL, "%s", ship->name );

            if ( expiredship( ship ) )
            {
                bug( "%s handled as expired ship!", buf );
                cnt++;
            }
        }

        if ( cnt > 0 )
            ch_println( ch, "Cleaned up a total of %d ship%s.", cnt, cnt == 1 ? "" : "s" );
        else
            ch_println( ch, "0 ships were expired!" );

        return;
    }
    else if ( !str_cmp( arg, "oaverage" ) )
    {
    }
    else if ( !str_cmp( arg, "maverage" ) )
    {
    }
    else if ( !str_cmp( arg, "homes" ) )
    {
        ROOM_INDEX_DATA* room = NULL;
        AREA_DATA* area = NULL;
        int col = 0, vnum = 0;
        ch_println( ch, "&zList of homes in LOTJ: (&RRed&z = &wOwned, &BBlue&z = &wEmpty&z)" );
        ch_println( ch, "&z-------------------------------------------------------" );

        for ( area = first_area; area; area = area->next )
        {
            if ( !area || area == NULL )
                continue;

            for ( vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
            {
                if ( ( room = get_room_index( vnum ) ) != NULL )
                {
                    if ( xIS_SET( room->flags, ROOM_PLR_HOME ) )
                    {
                        ch_printf( ch, "&R%-8d ", room->vnum );

                        if ( ++col % 5 == 0 )
                            ch_println( ch, "" );
                    }
                    else if ( xIS_SET( room->flags, ROOM_EMPTY_HOME ) )
                    {
                        ch_printf( ch, "&B%-8d ", room->vnum );

                        if ( ++col % 5 == 0 )
                            ch_println( ch, "" );
                    }
                }
            }
        }

        if ( col % 3 != 0 )
            ch_println( ch, "" );
    }
    else
    {
        ch_println( ch, "&RInvalid Statistic, Try again!" );
        do_lstat( ch, "" );
    }

    return;
}

void lstat_keys( CHAR_DATA* ch )
{
    int count = 0;
    OBJ_DATA* obj;
    ch_println( ch, "\n&YName:           Vnum:       Lock ID:  " );
    set_char_color( AT_BLUE, ch );

    for ( obj = first_object; obj; obj = obj->next )
    {
        if ( obj->item_type == ITEM_KEY )
        {
            if ( obj->value[0] > 0 )
            {
                ch_println( ch, "%-15s %-12ld %-12ld", obj->short_descr, obj->pIndexData->vnum, obj->value[0] );
                count++;
            }
        }

        if ( count >= 300 )
            break;
    }

    if ( count < 300 )
        ch_println( ch, "Objects counted: %ld", count );
    else
        ch_println( ch, "%ld Object counted. Limit break tripped.", count );

    return;
}

CMDF do_rank( CHAR_DATA* ch, char* argument )
{
    if ( IS_NPC( ch ) )
        return;

    if ( !argument || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Crank <&wstring&C>&w" );
        ch_println( ch, "&z   or: &Crank none.&w" );
        return;
    }

    if ( checkclr( argument, "x" ) )
    {
        ch_println( ch, "&RYou cannot use the BLACK Color token in your rank." );
