    }

    if ( nifty_is_name( "^", argument ) )
    {
        ch_println( ch, "&RYou cannot use the background/blinking tokens in your rank." );
        return;
    }

    smash_tilde( argument );
    strlcat( argument, "&w", MIL );

    if ( !str_cmp( argument, "none" ) )
        SET_STRING( ch->pcdata->rank, "" );
    else
        SET_STRING( ch->pcdata->rank, argument );

    ch_println( ch, "Ok." );
    return;
}

