CMDF do_retire( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Retire whom?" );
        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You failed." );
        return;
    }

    if ( victim->top_level < LEVEL_SAVIOR )
    {
        ch_println( ch, "The minimum level for retirement is savior." );
        return;
    }

    if ( IS_RETIRED( victim ) )
    {
        xREMOVE_BIT( victim->pcdata->flags, PCFLAG_RETIRED );
        ch_println( ch, "%s returns from retirement.", victim->name );
        ch_println( victim, "%s brings you back from retirement.", ch->name );
    }
    else
    {
        xSET_BIT( victim->pcdata->flags, PCFLAG_RETIRED );
        ch_println( ch, "%s is now a retired immortal.", victim->name );
        ch_println( victim, "Courtesy of %s, you are now a retired immortal.", ch->name );
    }

    return;
}

CMDF do_delay( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    int delay;
    set_char_color( AT_IMMORT, ch );
    argument = one_argument( argument, arg );

    if ( !*arg )
    {
        ch_println( ch, "&zSyntax: &Cdelay <&wvictim&C> <&w# of rounds&C>&w" );
        return;
    }

    if ( !( victim = get_player_world( arg ) ) )
    {
        ch_println( ch, "No such character online." );
        return;
    }

    if ( !IS_NPC( victim ) && get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You haven't the power to succeed against them." );
        return;
    }

    argument = one_argument( argument, arg );

    if ( !*arg )
    {
        ch_println( ch, "For how long do you wish to delay them?" );
        return;
    }

    if ( !str_cmp( arg, "none" ) )
    {
        ch_println( ch, "All character delay removed." );
        victim->wait = 0;
        return;
    }

    delay = atoi( arg );

    if ( delay < 1 )
    {
        ch_println( ch, "Pointless. Try a positive number." );
        return;
    }

    if ( delay > 999 )
    {
        ch_println( ch, "You cruel bastard. Just kill them!" );
        return;
    }

    WAIT_STATE( victim, delay * PULSE_VIOLENCE );
    ch_println( ch, "You've delayed %s for %d rounds.", victim->name, delay );
    return;
}


CMDF do_disconnect( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    DESCRIPTOR_DATA* d;
    CHAR_DATA* victim;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Disconnect whom?" );
        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( ch ) <= get_trust( victim ) )
    {
        ch_println( ch, "They might not like that..." );
        return;
    }

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d == victim->desc )
        {
            close_socket( d, FALSE );
            ch_println( ch, "Ok." );
            return;
        }
    }

    bug( "Do_disconnect: *** desc not found ***.", 0 );
    ch_println( ch, "Descriptor not found!" );
    return;
}

