CMDF do_forceclose( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    DESCRIPTOR_DATA* d;
    int desc;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Cforceclose <&wdescriptor #&C>&w" );
        return;
    }

    desc = atoi( arg );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->descriptor == desc )
        {
            if ( d->character && get_trust( d->character ) >= get_trust( ch ) )
            {
                ch_println( ch, "They might not like that..." );
                return;
            }

            close_socket( d, FALSE );
            ch_println( ch, "Ok." );
            return;
        }
    }

    ch_println( ch, "Not found!" );
    return;
}

void echo_to_all( sh_int AT_COLOR, char* argument, sh_int tar )
{
    DESCRIPTOR_DATA* d;

    if ( !argument || argument[0] == '\0' )
        return;

    for ( d = first_descriptor; d; d = d->next )
    {
        /*
            Added showing echoes to players who are editing, so they won't
            miss out on important info like upcoming reboots. --Narn
        */
        if ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
        {
            /*
                This one is kinda useless except for switched..
            */
            if ( tar == ECHOTAR_PC && IS_NPC( d->character ) )
                continue;
            else if ( tar == ECHOTAR_IMM && !IS_IMMORTAL( d->character ) )
                continue;
            else if ( tar == ECHOTAR_FORCERS && d->character->skill_level[FORCE_ABILITY] <= 1 )
                continue;

            set_char_color( AT_COLOR, d->character );
            send_to_char( argument, d->character );
            ch_println( d->character, "" );
        }
    }

    return;
}

CMDF do_echo( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    sh_int color;
    int target;
    char* parg;

    if ( has_pcflag( ch, PCFLAG_NO_EMOTE ) )
    {
        ch_println( ch, "You are noemoted and can not echo." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Echo what?" );
        return;
    }

    if ( ( color = get_color( argument ) ) )
        argument = one_argument( argument, arg );

    parg = argument;
    argument = one_argument( argument, arg );

    if ( !str_cmp( arg, "PC" ) || !str_cmp( arg, "player" ) )
        target = ECHOTAR_PC;
    else if ( !str_cmp( arg, "imm" ) )
        target = ECHOTAR_IMM;
    else if ( !str_cmp( arg, "forcers" ) )
        target = ECHOTAR_FORCERS;
    else
    {
        target = ECHOTAR_ALL;
        argument = parg;
    }

    if ( !color && ( color = get_color( argument ) ) )
        argument = one_argument( argument, arg );

    if ( !color )
        color = AT_IMMORT;

    one_argument( argument, arg );
    echo_to_all( color, convert_newline( argument ), target );
}

void echo_to_room_prox( sh_int AT_COLOR, ROOM_INDEX_DATA* room, char* argument )
{
    CHAR_DATA* vic;
    OBJ_DATA* to_obj;

    if ( room == NULL )
        return;

    push_to_taps( room, TAP_CAMERA, argument );
    lua_trigger_on_room_act( room, NULL, argument );
    rprog_act_trigger( argument, room, NULL, NULL, NULL );

    if ( !room || room_extracted( room ) )
        return;

    for ( vic = room->first_person; room && vic; vic = vic->next_in_room )
    {
        if ( !room || !vic )
            break;

        if ( has_pcflag( vic, PCFLAG_NOPROX ) || vic->position <= POS_SLEEPING )
            continue;

        if ( AT_COLOR > -1 )
            set_char_color( AT_COLOR, vic );

        send_to_char( argument, vic );
        ch_println( vic, "" );

        if ( !vic->desc && IS_NPC( vic ) )
        {
            lua_trigger_on_ch_act( vic, NULL, argument );

            if ( IS_SET( vic->pIndexData->progtypes, ACT_PROG ) )
                mprog_act_trigger( argument, vic, supermob, NULL, NULL );
        }
    }

    if ( !room )
        return;

    for ( to_obj = room->first_content; to_obj; to_obj = to_obj->next_content )
    {
        lua_trigger_on_obj_act( to_obj, NULL, argument );

        if ( IS_SET( to_obj->pIndexData->progtypes, ACT_PROG ) )
            oprog_act_trigger( argument, to_obj, vic, NULL, NULL );
    }

    return;
}

void echo_to_room( sh_int AT_COLOR, ROOM_INDEX_DATA* room, const char* argument )
{
    echo_to_room_filter( AT_COLOR, room, argument, NULL );
}

void echo_to_room_filter( sh_int AT_COLOR, ROOM_INDEX_DATA* room, const char* argument, bool ( *filter )( CHAR_DATA* ) )
{
    CHAR_DATA* vic;
    OBJ_DATA* to_obj;

    if ( room == NULL )
        return;

    if ( NULLSTR( argument ) )
    {
        bug( "null or empty argument to echo_to_room_filter at room %d", room->vnum );
        return;
    }

    push_to_taps( room, TAP_CAMERA, argument );
    lua_trigger_on_room_act( room, NULL, argument );
    rprog_act_trigger( argument, room, NULL, NULL, NULL );

    for ( vic = room->first_person; vic; vic = vic->next_in_room )
    {
        if ( !IS_AWAKE( vic ) )
            continue;

        if ( filter && !filter( vic ) )
            continue;

        if ( AT_COLOR > -1 )
            set_char_color( AT_COLOR, vic );

        send_to_char( argument, vic );
        ch_println( vic, "" );

        if ( !vic->desc && IS_NPC( vic ) )
        {
            lua_trigger_on_ch_act( vic, NULL, argument );

            if ( IS_SET( vic->pIndexData->progtypes, ACT_PROG ) )
                mprog_act_trigger( argument, vic, supermob, NULL, NULL );
        }
    }

    for ( to_obj = room->first_content; to_obj; to_obj = to_obj->next_content )
    {
        lua_trigger_on_obj_act( to_obj, NULL, argument );

        if ( IS_SET( to_obj->pIndexData->progtypes, ACT_PROG ) )
            oprog_act_trigger( argument, to_obj, vic, NULL, NULL );
    }

    OBJ_DATA* tobj;
    ROOM_INDEX_DATA* troom;
    CHAR_DATA* to;
    char buf[MIL];
    snprintf( buf, MIL, "&z<&WHolo&z> &033%s\n", argument );

    for ( TRANSMIT_DATA* transmit = first_transmit; transmit; transmit = transmit->next )
    {
        if ( !transmitter_sending_from_room( transmit, room ) )
            continue;

        for ( TRANSMIT_RECEIVER* rcv = transmit->first_connected; rcv; rcv = rcv->next )
        {
            tobj = rcv->transmitter;

            if ( tobj->value[IVAL_TRANSMITTER_MODE] == IVAL_TRANSMITTER_MODE_SEND )
                continue;

            troom = tobj->in_room ? tobj->in_room : tobj->carried_by ? tobj->carried_by->in_room : NULL;

            if ( !troom || troom == room )
                continue;

            for ( to = troom->first_person; to; to = to->next_in_room )
            {
                if ( !IS_AWAKE( to ) || IS_NPC( to ) )
                    continue;

                if ( filter && !filter( to ) )
                    continue;

                send_to_char( buf, to );
            }
        }
    }
}

CMDF do_recho( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    sh_int color;

    if ( has_pcflag( ch, PCFLAG_NO_EMOTE ) )
    {
        ch_println( ch, "You are noemoted and can not recho." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Recho what?" );
        return;
    }

    if ( check_ooc_in_ic_message( ch, argument, __FUNCTION__ ) )
        return;

    one_argument( argument, arg );

    if ( ( color = get_color( argument ) ) )
    {
        argument = one_argument( argument, arg );
        echo_to_room( color, ch->in_room, argument );
    }
    else
        echo_to_room( AT_IMMORT, ch->in_room, argument );
}


ROOM_INDEX_DATA* find_location( CHAR_DATA* ch, char* arg )
{
    CHAR_DATA* victim;
    OBJ_DATA* obj;

    if ( is_number( arg ) )
        return get_room_index( atoi( arg ) );

    if ( ( victim = get_char_world_full( ch, arg ) ) != NULL )
        return victim->in_room;

    if ( ( obj = get_obj_world( ch, arg ) ) != NULL )
        return obj->in_room;

    return NULL;
}

CMDF do_phome( CHAR_DATA* ch, char* argument )
{
    PHOME_DATA* home = NULL;
    ROOM_INDEX_DATA* room = NULL;
    char arg1[MIL], arg2[MIL];
    PLANET_DATA* planet = NULL;
    AREA_DATA* tarea = NULL;
    smash_tilde( argument );
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, only Imms can manage homes." );
        return;
    }

    if ( ( arg1[0] == '\0' || arg2[0] == '\0' ) && str_cmp( arg1, "total" ) && str_cmp( arg1, "show" ) && str_cmp( arg1, "inactive" ) )
    {
        ch_println( ch, "&zSyntax: &Cphome show <&wvnum&z/&wplayer&C>&w" );
        ch_println( ch, "&zSyntax: &Cphome owner <&wvnum&C> <&wnew owner&C>&w" );
        ch_println( ch, "&zSyntax: &Cphome sell <&wvnum&C>&w" );
        ch_println( ch, "&zSyntax: &Cphome price <&wvnum&C> <&wnew price&C> &w(default: 100,000 credits)" );
        ch_println( ch, "&zSyntax: &Cphome <&wavailable&z/&wunavailable&C> <&warea&z/&wplanet&C>&w" );
        ch_println( ch, "&zSyntax: &Cphome total&w" );
        ch_println( ch, "&zSyntax: &Cphome inactive&w" );
        return;
    }

    if ( !str_cmp( arg1, "total" ) )
    {
        int total = 0;
        int owned = 0;
        int unowned = 0;

        for ( AREA_DATA* area = first_area; area; area = area->next )
        {
            for ( int vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
            {
                room = get_room_index( vnum );
                if ( !room || !room->phome )
                    continue;

                home = room->phome;

                total++;

                if ( NULLSTR( home->owner ) && home->owner_id == 0 )
                    unowned++;
                else
                    owned++;
            }
        }

        ch_println( ch, "&zTotal # of Homes: &C%d&w", total );
        ch_println( ch, "&zOwned Homes: &w%d", owned );
        ch_println( ch, "&zUnowned Homes: &w%d", unowned );
        return;
    }

    if ( !str_cmp( arg1, "inactive" ) )
    {
        ch_println( ch, "&RHomes owned by players who haven't logged in for 3+ months:" );

        for ( AREA_DATA* area = first_area; area; area = area->next )
        {
            for ( int vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
            {
                room = get_room_index( vnum );

                if ( !room || !room->phome )
                    continue;

                home = room->phome;

                if ( home->owner_active < current_time - ( 90 * 86400 ) )
                    ch_println( ch, "&zOwner: &C%s&w | &zVnum: &C%-6d&w | &zPrice: &C%d&w (&C%s&w)", !NULLSTR( home->owner ) ? home->owner : "None", room->vnum, home->price, mini_c_time( home->owner_active, get_timezone( ch ), false ) );
            }
        }

        return;
    }

    if ( !str_cmp( arg1, "available" ) || !str_cmp( arg1, "unavailable" ) )
    {
        tarea = get_area( arg2 );
        planet = get_planet( arg2 );
        if ( tarea )
        {
            if ( !str_cmp( arg1, "unavailable" ) )
                ch_println( ch, "&zUnavailable Homes in area &C%s&z:&w", arg2 );
            else
                ch_println( ch, "&zAvailable Homes in area &C%s&z:&w", arg2 );

            for ( int vnum = tarea->min_vnum; vnum <= tarea->max_vnum; vnum++ )
            {
                room = get_room_index( vnum );

                if ( !room || !room->phome )
                    continue;

                home = room->phome;

                if ( !str_cmp( arg1, "unavailable" ) )
                {
                    if ( !NULLSTR( home->owner ) && home->owner_id != 0 )
                        ch_println( ch, "&zOwner: &C%s&w | &zVnum: &C%-6d&w | &zPrice: &C%d&w", home->owner, room->vnum, home->price );
                }
                else
                {
                    if ( NULLSTR( home->owner ) && home->owner_id == 0 )
                        ch_println( ch, "&zVnum: &C%d&w | &zPrice: &C%d&w", room->vnum, home->price );
                }
            }
        }
        else if ( planet )
        {
            if ( !str_cmp( arg1, "unavailable" ) )
                ch_println( ch, "&zUnavailable Homes on planet &C%s&z:&w", arg2 );
            else
                ch_println( ch, "&zAvailable Homes on planet &C%s&z:&w", arg2 );

            FOREACH_LNODE( AREA_DATA, planet->first_area, tarea, {
                for ( int vnum = tarea->min_vnum; vnum <= tarea->max_vnum; vnum++ )
                {
                    room = get_room_index( vnum );

                    if ( !room || !room->phome )
                        continue;

                    home = room->phome;

                    if ( !str_cmp( arg1, "unavailable" ) )
                    {
                        if ( !NULLSTR( home->owner ) && home->owner_id != 0 )
                            ch_println( ch, "&zOwner: &C%s&w | &zVnum: &C%-6d&w | &zPrice: &C%d&w", home->owner, room->vnum, home->price );
                    }
                    else
                    {
                        if ( NULLSTR( home->owner ) && home->owner_id == 0 )
                            ch_println( ch, "&zVnum: &C%-6d&w | &zPrice: &C%d&w", room->vnum, home->price );
                    }
                }
            })
        }
        else
        {
            ch_println( ch, "&RNo such area or planet." );
        }

        return;
    }

    if ( !str_cmp( arg1, "show" ) )
    {
        if ( NULLSTR( arg2 ) )
            home = ch->in_room->phome;
        else if ( is_number( arg2 ) )
        {
            room = get_room_index( atoi( arg2 ) );
            home = room ? room->phome : NULL;            
        }
        else
            home = phome_from_name( arg2 );

        if ( home != NULL )
        {
            room = home->room;

            if ( room == NULL )
                ch_println( ch, "&RERROR: Player owns home with non-existent room!" );
            else
            {
                ch_println( ch, "&zRoom Name: &w%s", room->name );
                ch_println( ch, "&zArea: &w%s", room->area->shortname );

                if ( room->area->planet )
                    ch_println( ch, "&zPlanet: &w%s", room->area->planet->name );
            }

            ch_println( ch, "&zOwner: &C%s&w", !NULLSTR( home->owner ) ? home->owner : "NONE" );

            ch_println( ch, "&zPrevious Owners:" );
            for ( OWNER_DATA* owner = home->first_owner; owner; owner = owner->next )
            {
                if ( owner->player_id == ch->id && owner == home->last_owner )
                    continue;

                ch_println( ch, "&z- &C%s", owner->name );
            }

            ch_println( ch, "&zVnum: &w%d", room->vnum );
            ch_println( ch, "&zHome Price: &w%d", home->price );
            ch_println( ch, "&zResidents:%s", home->first_resident ? "" : " &CNONE" );
            for ( RESIDENT_DATA* resident = home->first_resident; resident; resident = resident->next )
                ch_println( ch, "&z- &C%s", resident->real_name );

            return;
        }

        ch_println( ch, "&zNo such home.&w" );
        return;
    }

    if ( !str_cmp( arg1, "owner" ) )
    {
        char arg3[MIL];
        argument = one_argument( argument, arg3 );

        if ( NULLSTR( arg3 ) || NULLSTR( arg2 ) || !is_number( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Cphome owner <&wvnum&C> <&wnew owner&C>&w" );
            return;
        }

        CHAR_DATA* new_owner = get_player_world( arg3 );

        if ( !new_owner || IS_NPC( new_owner ) )
        {
            ch_println( ch, "&RThat player must be online to assign a home to them." );
            return;
        }

        if ( ( home = phome_from_id( new_owner->id ) ) != NULL )
        {
            ch_println( ch, "&RThat player already has a home!" );
            return;
        }

        room = get_room_index( atoi( arg2 ) );
        home = room ? room->phome : NULL;

        if ( !room || !home )
        {
            ch_println( ch, "&RNo such home." );
            return;
        }

        SET_STRING( home->owner, new_owner->name );
        home->owner_id = new_owner->id;

        OWNER_DATA* owner = NULL;
        CREATE( owner, OWNER_DATA, 1 );
        SET_STRING( owner->name, new_owner->name );
        owner->player_id = new_owner->id;
        LINK( owner, home->first_owner, home->last_owner, next, prev );
        save_room( home->room, true );
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg1, "price" ) )
    {
        char arg3[MIL];
        argument = one_argument( argument, arg3 );

        if ( NULLSTR( arg2 ) || !is_number( arg2 ) || NULLSTR( arg3 ) || !is_number( arg3 ) )
        {
            ch_println( ch, "&zSyntax: &Cphome price <&wvnum&C> <&wnew price&C> &w(default: 100,000 credits)" );
            return;
        }

        room = get_room_index( atoi( arg2 ) );
        home = room ? room->phome : NULL;
        int price = atoi( arg3 );

        if ( home != NULL )
        {
            if ( price <= 0 || price > 50000000 )
            {
                ch_println( ch, "The home price must be between 1 and 50,000,000 credits!" );
                return;
            }

            home->price = price;
            save_room( home->room, true );
            return;
        }

        ch_println( ch, "&zNo such home.&w" );
        return;
    }

    if ( !str_cmp( arg1, "sell" ) )
    {
        if ( NULLSTR( arg2 ) || !is_number( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Cphome sell <&wvnum&C>&w" );
            return;
        }

        room = get_room_index( atoi( arg2 ) );
        home = room ? room->phome : NULL;

        if ( home != NULL )
        {
            reset_home( room, home );
            save_room( room, true );
            return;
        }

        ch_println( ch, "&zNo such home.&w" );
        return;
    }
}

CMDF do_transfer( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    ROOM_INDEX_DATA* location;
    DESCRIPTOR_DATA* d;
    CHAR_DATA* victim;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Ctransfer <&wplayer&C> <&wvnum&C>&w" );
        return;
    }

    if ( !str_cmp( arg1, "all" ) && get_trust( ch ) > 103 )
    {
        for ( d = first_descriptor; d; d = d->next )
        {
            if ( d->connected == CON_PLAYING
                    && d->character != ch && d->character->in_room && d->newstate != 2 && can_see( ch, d->character ) )
            {
                char buf[MSL];
                snprintf( buf, MSL, "%s %s", d->character->name, arg2 );
                do_transfer( ch, buf );
            }
        }

        return;
    }

    /*
        Thanks to Grodyn for the optional location parameter.
    */
    if ( NULLSTR( arg2 ) )
        location = ch->in_room;
    else
    {
        if ( ( location = find_location( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "No such location." );
            return;
        }

        if ( !can_build( ch, location->area ) )
            return;

        if ( room_is_private( ch, location ) && get_trust( ch ) < 105 )
        {
            ch_println( ch, "That room is private right now." );
            return;
        }
    }

    if ( ( victim = get_char_world_full( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You cannot transfer yourself." );
        return;
    }

    if ( NOT_AUTHED( victim ) )
    {
        ch_println( ch, "They are not authorized yet!" );
        return;
    }

    if ( !victim->in_room )
    {
        ch_println( ch, "They are in limbo." );
        return;
    }

    if ( get_trust( ch ) < get_trust( victim ) && !IS_NPC( victim ) )
    {
        ch_println( ch, "You can't transfer someone above your level!" );
        return;
    }

    /*
        modification to prevent a low level imm from transferring a
    */
    /*
        higher level imm with the DND flag on.  - Gorog
    */
    if ( !IS_NPC( victim ) && get_trust( ch ) < get_trust( victim )
            && victim->desc
            && ( victim->desc->connected == CON_PLAYING
                 || victim->desc->connected == CON_EDITING ) && has_pcflag( victim, PCFLAG_DND ) )
    {
        pager_printf( ch, "Sorry. %s does not wish to be disturbed.\n", victim->name );
        pager_printf( victim, "Your DND flag just foiled %s's transfer command.\n", ch->name );
        return;
    }

    /*
        end of modification
    */

    if ( victim->fighting )
        stop_fighting( victim, TRUE );

    act( AT_MAGIC, "$n disappears in a cloud of swirling colors.", victim, NULL, NULL, TO_ROOM );
    victim->retran = victim->in_room->vnum;
    char_from_room( victim );
    char_to_room( victim, location );
    act( AT_MAGIC, "$n arrives from a puff of smoke.", victim, NULL, NULL, TO_ROOM );

    if ( ch != victim )
        act( AT_IMMORT, "$n has transferred you.", ch, NULL, victim, TO_VICT );

    do_look( victim, "auto" );
    ch_println( ch, "Ok." );
}

CMDF do_retran( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim = NULL;
    DESCRIPTOR_DATA* d;
    char buf[MSL];
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Retransfer whom?" );
        return;
    }

    if ( !( str_cmp( arg, "all" ) ) )
    {
        for ( d = first_descriptor; d; d = d->next )
        {
            if ( d->connected != CON_PLAYING )
                continue;

            if ( !d->character )
                continue;

            if ( !d->character->in_room )
                continue;

            if ( !d->character->retran )
                continue;

            if ( get_trust( ch ) < get_trust( d->character ) )
                continue;

            victim = d->character;
            snprintf( buf, MSL, "'%s' %d", victim->name, victim->retran );
            do_transfer( ch, buf );
        }
    }
    else if ( !( victim = get_char_world_full( ch, arg ) ) )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    snprintf( buf, MSL, "'%s' %d", victim->name, victim->retran );
    do_transfer( ch, buf );
    return;
}

