CMDF do_at( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    ROOM_INDEX_DATA* location = NULL;
    ROOM_INDEX_DATA* original;
    CHAR_DATA* wch = NULL;

    if (IS_NPC(ch))
        return;

    set_char_color( AT_IMMORT, ch );
    argument = one_argument( argument, arg );

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "At where what?" );
        return;
    }

    if ( is_number( arg ) )
        location = get_room_index( atoi( arg ) );
    else if ( ( wch = get_char_world_full( ch, arg ) ) == NULL || wch->in_room == NULL )
    {
        ch_println( ch, "No such mobile or player in existence." );
        return;
    }

    if ( !location && wch )
        location = wch->in_room;

    if ( !location )
    {
        ch_println( ch, "No such location exists." );
        return;
    }

    /*
        The following mod is used to prevent players from using the
    */
    /*
        at command on a higher level immortal who has a DND flag
    */
    if ( wch && !IS_NPC( wch ) && has_pcflag( wch, PCFLAG_DND ) && get_trust( ch ) < get_trust( wch ) )
    {
        pager_printf( ch, "Sorry. %s does not wish to be disturbed.\n", wch->name );
        pager_printf( wch, "Your DND flag just foiled %s's at command.\n", ch->name );
        return;
    }

    /*
        End of modification  -- Gorog
    */

    if ( xIS_SET( location->flags, ROOM_ADMIN ) && get_trust( ch ) < 105 )
    {
        ch_println( ch, "You aren't allowed into administrative rooms unless invited. Nice try." );
        return;
    }

    if ( room_is_private( ch, location ) )
    {
        if ( get_trust( ch ) < LEVEL_GREATER )
        {
            ch_println( ch, "That room is private right now." );
            return;
        }
        else
            ch_println( ch, "Overriding private flag!" );
    }

    /*    if ( (victim=room_is_dnd(ch, location)) )
        {
           pager_printf( ch, "That room is \"do not disturb\" right now.\n" );
           pager_printf( victim,
              "Your DND flag just foiled %s's atmob command\n", ch->name );
           return;
        }*/
    /*
        set_char_color( AT_PLAIN, ch );
    */
    original = ch->in_room;
    char_from_room( ch );
    char_to_room( ch, location );
    interpret( ch, argument, FALSE );

    if ( !char_extracted( ch ) )
    {
        char_from_room( ch );
        char_to_room( ch, original );
    }

    return;
}

