        }*/
    set_char_color( AT_PLAIN, ch );
    original = ch->in_room;
    char_from_room( ch );
    char_to_room( ch, location );
    interpret( ch, argument, FALSE );

    if ( !char_extracted( ch ) )
    {
        char_from_room( ch );
        char_to_room( ch, original );
    }

    return;
}

CMDF do_rat( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    ROOM_INDEX_DATA* location;
    ROOM_INDEX_DATA* original;
    int Start, End, vnum;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Crat <&wstart&C> <&wend&C> <&wcommand&C>&w" );
        return;
    }

    Start = atoi( arg1 );
    End = atoi( arg2 );

    if ( Start < 1 || End < Start || Start > End || Start == End || End > MAX_VNUMS )
    {
        ch_println( ch, "Invalid range." );
        return;
    }

    if ( !str_cmp( argument, "quit" ) )
    {
        ch_println( ch, "I don't think so!" );
        return;
    }

    original = ch->in_room;

    for ( vnum = Start; vnum <= End; vnum++ )
    {
        if ( ( location = get_room_index( vnum ) ) == NULL )
            continue;

        char_from_room( ch );
        char_to_room( ch, location );
        interpret( ch, argument, FALSE );
    }

    char_from_room( ch );
    char_to_room( ch, original );
    ch_println( ch, "Done." );
    return;
}


CMDF do_rstat( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg[MIL];
    ROOM_INDEX_DATA* location;
    OBJ_DATA* obj;
    CHAR_DATA* rch;
    EXIT_DATA* pexit;
    int cnt;
    one_argument( argument, arg );

    if ( !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( !str_cmp( arg, "exits" ) )
    {
        location = ch->in_room;
        ch_println( ch, "Exits for room '%s.' vnum %d", location->name, location->vnum );

        for ( cnt = 0, pexit = location->first_exit; pexit; pexit = pexit->next )
            ch_println( ch,
                       "%2d) %2s to %-5d.  Key: %d  Flags: %d  Keywords: '%s'.\nDescription: %sExit links back to vnum: %d  Exit's RoomVnum: %d  Distance: %d",
                       ++cnt,
                       dir_name_short[pexit->vdir],
                       pexit->to_room ? pexit->to_room->vnum : pexit->vnum,
                       pexit->key,
                       pexit->flags,
                       pexit->keyword,
                       pexit->description[0] != '\0'
                       ? pexit->description : "(none).\n",
                       pexit->rexit ? pexit->rexit->vnum : 0, pexit->rvnum, pexit->distance );

        return;
    }

    if ( !str_cmp( arg, "vars" ) )
    {
        location = ch->in_room;
        ch_println( ch, "\n&zVariables:" );
        print_dvars( ch, location->vars );
        return;
    }

    if ( !str_cmp( arg, "affects" ) )
    {
        location = ch->in_room;
        int cnt = 0, i = 0;
        SKILL_DATA* skill = NULL;
        ch_println( ch, "&zDisplaying basic affects for Room &C%d&z:", location->vnum );

        for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
        {
            if ( xIS_SET( location->affected_by, affect_flags[i].flag ) )
            {
                ch_println( ch, "&z- &C%s", affect_flags[i].name );
                cnt++;
            }
        }

        if ( cnt == 0 )
            ch_println( ch, "&z- None" );

        cnt = 0;
        ch_println( ch, "\n&zDisplaying complex affects for Room &C%d&z:", location->vnum );
        for ( AFFECT_DATA* paf = location->first_affect; paf; paf = paf->next )
        {
            strlcpy( buf, "", MSL );
            for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
                if ( xIS_SET( paf->bitvector, affect_flags[i].flag ) )
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%s ", affect_flags[i].name );
            skill = skill_from_id( paf->type );
            ch_println( ch, "&z- Type &C%s&z, Mod &C%d&z, Duration &C%d&z, Location &C%s&z, Bitvector &C%s&z", skill ? skill->name : itoa( paf->type ), paf->modifier, paf->duration, apply_table[paf->location].name, !NULLSTR( buf ) ? buf : "None" );
            ch_printf( ch, "&z  Values:&C" );
            for ( size_t i = 0; i < MAX_VALS; i++ )
                ch_printf( ch, " %d", paf->value[i] );
            ch_printf( ch, "&z\n" );
            cnt++;
        }

        if ( cnt == 0 )
            ch_println( ch, "&z- None" );

        return;
    }

    location = ( arg[0] == '\0' ) ? ch->in_room : find_location( ch, arg );

    if ( !location )
    {
        ch_println( ch, "No such location." );
        return;
    }

    if ( ch->in_room != location && room_is_private( ch, location ) )
    {
        if ( get_trust( ch ) < LEVEL_GREATER )
        {
            ch_println( ch, "That room is private right now." );
            return;
        }
        else
        {
            ch_println( ch, "Overriding private flag!" );
        }
    }

    ch_println( ch, "&zName: &C%s\n&zArea: &C%s\n&zFilename: &C%s.",
               location->name,
               location->area ? location->area->name : "(None)", location->area ? location->area->shortname : "(None)" );

    TURRET_DATA* turret = turret_from_room( location );
    ch_println( ch,
               "&zVnum: &B%d.  &zWeapon Charge: &C%d.\n&zSector: &C%d.  &zLight: &C%d.  &zTeleDelay: &C%d.  &zTeleVnum: &C%d  &zTunnel: &C%d.",
               location->vnum,
               turret ? turret->laserstate : 0,
               location->sector_type, location->light, location->tele_delay, location->tele_vnum, location->tunnel );
    ch_println( ch, "&zAffected by: &C%s", flag_string( &location->affected_by, affect_flags ) );

    if ( location->mapper_coords_set )
        ch_println( ch, "&zRoom Map Coordinates: &B%d %d %d", location->mapper_x, location->mapper_y, location->mapper_z );

    ch_println( ch, "&zRoom flags: &B%s", flag_string( &location->flags, room_flags ) );
    ch_println( ch, "&zSecurity Rating: &B%d", location->security_rating );

    if ( xIS_SET( location->flags, ROOM_GARAGE ) || xIS_SET( location->flags, ROOM_CAN_LAND )
            || xIS_SET( location->flags, ROOM_CLANPAD ) || xIS_SET( location->flags, ROOM_HIDDEN_LAND )  || xIS_SET( location->flags, ROOM_SPACECRAFT ) )
        ch_println( ch, "&zMinimum Ship Class: &B%s (%d).  &zMaximum Ship Class: &B%s (%d).", class_types[location->minshipclass], location->minshipclass, class_types[location->maxshipclass], location->maxshipclass );

    if ( xIS_SET( location->flags, ROOM_GARAGE ) || xIS_SET( location->flags, ROOM_CAN_LAND )
            || xIS_SET( location->flags, ROOM_CLANPAD ) || xIS_SET( location->flags, ROOM_HIDDEN_LAND )  )
    {
        if ( location->shipcapacity == 0 )
            ch_println( ch, "&zShip Capacity: &B%d/Unlimited.", get_shipcapacity_count( location ) );
        else
            ch_println( ch, "&zShip Capacity: &B%d/%d.", get_shipcapacity_count( location ), location->shipcapacity );
    }
    if ( location->on_ship && location->on_ship->name )
    {
        ch_println( ch, "&zRoom Part of Ship: &B%s", location->on_ship->name );
    }
    ch_println( ch, "&zVariables  : &C%d&z. Use &Crstat vars &zto view.", count_dvars( location->vars ) );
    ch_println( ch, "&zAffects    : &C%d&z. Use &Crstat affects &zto view.", count_dvars( location->vars ) );

    send_to_char( "&zCharacters:&B", ch );

    for ( rch = location->first_person; rch; rch = rch->next_in_room )
    {
        if ( can_see( ch, rch ) )
        {
            send_to_char( " ", ch );
            one_argument( rch->name, buf );
            send_to_char( buf, ch );
        }
    }

    send_to_char( "\n&zObjects:&B", ch );

    for ( obj = location->first_content; obj; obj = obj->next_content )
    {
        send_to_char( " ", ch );
        one_argument( obj->name, buf );
        send_to_char( buf, ch );
    }

    ch_println( ch, "" );
    ch_printf( ch, "&zDescription:\n&w%s", location->description );

    if ( NULLSTR( location->nightdesc ) )
        ch_println( ch, "&zNightdesc: &wNone" );
    else
        ch_printf( ch, "&zNightdesc: \n&w%s",  location->nightdesc );

    ch_println( ch, "&zStockname: &z%s", NULLSTR( location->stockname ) ? "&wNone" : location->stockname );

    if ( NULLSTR( location->stockdesc ) )
        ch_println( ch, "&zStockdesc: &wNone" );
    else
        ch_printf( ch, "&zStockdesc: \n&w%s",  location->stockdesc );

    if ( location->first_extradesc )
    {
        EXTRA_DESCR_DATA* ed;
        send_to_char( "&zExtra description keywords: '&C", ch );

        for ( ed = location->first_extradesc; ed; ed = ed->next )
        {
            send_to_char( ed->keyword, ch );

            if ( ed->next )
                send_to_char( " ", ch );
        }

        ch_println( ch, "&z'." );
    }

    if ( location->first_exit )
        ch_println( ch, "&z-------------------&C EXITS &z-------------------" );

    for ( cnt = 0, pexit = location->first_exit; pexit; pexit = pexit->next )
        ch_println( ch, "&B%2d&z) &B%2s &zto %s%-5d  &zKey: &C%d  &zKeywords: &C%s",
                   ++cnt,
                   dir_name_short[pexit->vdir],
                   pexit->to_room ? "&C" : "&R",
                   pexit->to_room ? pexit->to_room->vnum : pexit->vnum,
                   pexit->key, pexit->keyword[0] != '\0' ? pexit->keyword : "(none)" );

    return;
}

void print_ostat_affect( CHAR_DATA* ch, AFFECT_DATA* paf, bool extra )
{
    if ( paf->location == APPLY_AFFECT )
    {
        ch_printf( ch, "&zWearer &Caffected &zby &C" );
        int aff_cnt = 0;

        for ( int i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
        {
            if ( gives_affected_by( paf, affect_flags[i].flag ) )
            {
                ch_printf( ch, "%s%s", aff_cnt == 0 ? "" : "&z, &C", affect_flags[i].name );
                aff_cnt++;
            }
        }

        if ( aff_cnt == 0 )
            ch_printf( ch, "(invalid affect value)" );

        ch_println( ch, "&z.%s", extra ? " (extra)" : "" );
    }
    else if ( paf->location == APPLY_RESISTANT || paf->location == APPLY_IMMUNE || paf->location == APPLY_SUSCEPTIBLE )
    {
        ch_println( ch, "&zWearer &C%s &zto &C%s&z.%s",
            affect_loc_name( paf->location ),
            flag_value_name( resistant_types, paf->modifier ),
            extra ? " (extra)" : ""
        );
    }
    else
    {
        ch_println( ch, "&zAffects &C%s &zby &C%d&z.%s",
            affect_loc_name( paf->location ),
            paf->modifier,
            extra ? " (extra)" : ""
        );
    }
}

