CMDF do_inspectmem( CHAR_DATA *ch, char* argument ) {
    char arg[MIL];

    argument = one_argument( argument, arg );
    size_t num_bytes = atoi(argument);

    if(!is_not_production() && ch->top_level < 200) {
        ch_println( ch, "I don't think that would be a good idea on production..." );
        return;
    }

    if( arg[0] == '\0') {
        ch_println( ch, "What memory address would you like to inspect?" );
        return;
    }

    if( num_bytes < 1 ) {
        ch_println( ch, "Please choose a positive number of bytes." );
        return;
    }

    uintptr_t addr = strtoull(arg, NULL, 16); // Convert string to address
    uint8_t* pointer = (uint8_t*) addr; // Cast to byte pointer for byte-wise access

    ch_printf(ch, "Inspecting %d bytes at %p\n", num_bytes, addr);

    for (size_t i = 0; i < num_bytes; ++i) {
        if (i != 0 && i % 16 == 0) { // Print ASCII after every 16 bytes
            ch_printf(ch, " | ");
            for (size_t j = i - 16; j < i; ++j) {
                if (isprint(pointer[j])) {
                    ch_printf(ch, "%c", pointer[j]);
                } else {
                    ch_printf(ch, ".");
                }
            }
            ch_printf(ch, "\n");
        }

        // Print each byte in hex
        ch_printf(ch, "%02x ", pointer[i]);
    }

    // Handle remaining ASCII characters for last line if it's not 16 bytes long
    while (num_bytes % 16 != 0) {
        ch_printf(ch, "   "); // Extra space for alignment
        num_bytes++;
    }

    ch_printf(ch, " | ");
    size_t start = num_bytes - num_bytes % 16;
    for (size_t i = start; i < start + 16 && i < num_bytes; ++i) {
        if (isprint(pointer[i])) {
            ch_printf(ch, "%c", pointer[i]);
        } else {
            ch_printf(ch, ".");
        }
    }

    ch_printf(ch, "\n");
    return;

}

