        for ( OBJ_DATA* obj = victim->first_carrying; obj; obj = obj->next_content )
        {
            if ( obj->wear_loc == WEAR_NONE )
                continue;

            if ( !obj->first_affect && ( !obj->pIndexData || !obj->pIndexData->first_affect ) )
                continue;

            ch_println( ch, "&z- &C%s &z(&C%d&z)", obj->short_descr, obj->pIndexData ? obj->pIndexData->vnum : 0 );
            for ( AFFECT_DATA* paf = obj->first_affect; paf; paf = paf->next )
            {
                strlcpy( buf, "", MSL );
                for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
                    if ( xIS_SET( paf->bitvector, affect_flags[i].flag ) )
                        snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%s ", affect_flags[i].name );
                skill = skill_from_id( paf->type );
                ch_println( ch, "&z  - Type &C%s&z, Mod &C%d&z, Duration &C%d&z, Location &C%s&z, Bitvector &C%s&z", skill ? skill->name : itoa( paf->type ), paf->modifier, paf->duration, apply_table[paf->location].name, !NULLSTR( buf ) ? buf : "None" );
                cnt++;
            }

            if ( obj->pIndexData && obj->pIndexData->first_affect )
            {
                for ( AFFECT_DATA* paf = obj->pIndexData->first_affect; paf; paf = paf->next )
                {
                    strlcpy( buf, "", MSL );
                    for ( i = 0; affect_flags[i].flag != LAST_FLAG_VALUE; i++ )
                        if ( xIS_SET( paf->bitvector, affect_flags[i].flag ) )
                            snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%s ", affect_flags[i].name );
                    skill = skill_from_id( paf->type );
                    ch_println( ch, "&z  - Type &C%s&z, Mod &C%d&z, Duration &C%d&z, Location &C%s&z, Bitvector &C%s&z", skill ? skill->name : itoa( paf->type ), paf->modifier, paf->duration, apply_table[paf->location].name, !NULLSTR( buf ) ? buf : "None" );
                    cnt++;
                }
            }
        }

        if ( cnt == 0 )
            ch_println( ch, "&z- None" );

        return;
    }

    if ( get_trust( ch ) < get_trust( victim ) && !IS_NPC( victim ) )
    {
        ch_println( ch, "&YTheir godly glow prevents you from getting a good look." );
        ch_println( victim, "&R%s has attempted to MSTAT you!", ch->name );
        return;
    }

    if ( !IS_NPC( victim ) && get_trust( ch ) < 104 && (IS_NPC(ch) || !is_name( "pmstat", ch->pcdata->bestowments ) ) && victim != ch )
    {
        ch_println( ch, "Sorry, you cannot mstat players." );
        bug( "%s attempting to mstat %s.", ch->name, victim->name );
        return;
    }

    if ( !str_cmp( argument, "metrics" ) ) 
    {
        ch_println( ch, "&zMetrics:" );
        print_all_metrics(ch, &victim->metrics);
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "&zName: &Y%s     &zOrganization: &Y%s", victim->name,
                   ( !get_clan( victim->mob_clan ) ) ? "(none)" : get_clan( victim->mob_clan )->name );
    }
    else
    {
        ch_println( ch, "&zName: &G%s     &zOrganization: &G%s", victim->name,
                   ( !victim->pcdata->clan ) ? "(none)" : victim->pcdata->clan->name );
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "&zMemory Address: &Y%p     &zIndex Memory Address: &Y%p", victim, victim->pIndexData);
    }
    else
    {
        ch_println( ch, "&zMemory Address: &G%p", victim);
    }

    ch_println( ch, "&zMain Ability: &G%s     &zLeadership Focus: &G%s", flag_value_name( ability_name, victim->main_ability ),
               victim->main_ability != LEADERSHIP_ABILITY ? "None" : flag_value_name( ability_name, victim->pcdata->lclass ) );

    if ( victim->disguise )
    {
        ch_println( ch, "&zDisguise Race:&w %s  \n&zDisguise Skincolor:&w %s", victim->disguise->race->race_name, get_skincolor( victim->disguise->skincolor ) );
        current_tone = find_tone( victim->disguise->tone );
        sh_int txtclr = victim->disguise->txtclr;
        ch_println( ch, "&zDisguise Tone: &C%s      &zDisguise Text Color: %s%s &z(&C#%d&z)",
                current_tone ? current_tone->name : "(unknown)",
                txtclr >= 0 && txtclr < txtclr_count ? txtclr_codes[txtclr] : "&C",
                txtclr >= 0 && txtclr < txtclr_count ? txtclr_names[txtclr] : "(unknown)",
                txtclr
                );
    }

    if ( get_trust( ch ) >= LEVEL_GOD && !IS_NPC( victim ) && victim->desc )
    {
        int msets = 0;

        for ( db = first_mset; db; db = db->next )
            if ( !str_cmp( db->name, victim->name ) )
                msets++;

        ch_println( ch, "&zUser: &C%s&z@&C%s   &zDescriptor: &C%d   &zTrust: &Y%d\n&zMsets:  &C%d",
                   victim->desc->user, get_char_ip( ch, victim->desc ),
                   victim->desc->descriptor, victim->trust, msets );

        if ( victim->pcdata->silence_expires >= 0 && !NULLSTR( victim->pcdata->silence_reason ) && !NULLSTR( victim->pcdata->silenced_by ) && has_pcflag( victim, PCFLAG_SILENCE ) )
        {
            ch_println( ch, "&zSilenced by: &w%s\n&zSilence reason: &w%s\n&zSilence expires in: &w%s", victim->pcdata->silenced_by, victim->pcdata->silence_reason, ( victim->pcdata->silence_expires == 0 ) ? "NEVER" : duration_string( victim->pcdata->silence_expires - current_time ) );
        }
    }

    if ( get_trust( ch ) >= 110 && !IS_NPC( victim ) && victim->desc )
    {
        // if( victim->pcdata->fakeip && victim->pcdata->fakeip[0] != '\0' )
        ch_println( ch, "&zFake IP: &C%s",
                   victim->pcdata->fakeip && victim->pcdata->fakeip[0] != '\0' ? victim->pcdata->fakeip : "None" );
    }

    PHOME_DATA* home = phome_from_id( victim->id );

    if ( !IS_NPC( victim ) && home && home->room )
        ch_println( ch, "&zHome: &C%d", home->room->vnum );

    if ( !IS_NPC( victim ) )
        pass = TRUE;

    if ( IS_NPC( victim ) && victim->pIndexData )
    {
        if ( victim->pIndexData->area )
        {
            ch_println( ch, "&cArea: &w%s", victim->pIndexData->area->name );
            pass = TRUE;
        }
    }

    if ( !pass )
    {
        bug( "Mstat: %s mstating %s, %s has no area file.", ch->name, victim->name, victim->name );
        return;
    }

    if ( !IS_NPC( victim ) && victim->pcdata->release_date != 0 )
        ch_println( ch, "&RHelled until &C%24.24s &Rby &C%s.",
                   ctime( &victim->pcdata->release_date ), victim->pcdata->helled_by );

    ch_println( ch, "&zVnum: &Y%d   &zSex: &C%s   &zRoom: &C%d   &zCount: &C%d  &zKilled: &C%d &zID: &C%d%s%s%s",
               IS_NPC( victim ) ? victim->pIndexData->vnum : 0,
               IS_NPC( victim ) && xIS_SET( victim->act, ACT_PROTOTYPE ) && victim->pIndexData->sex == SEX_RANDOM ? "random" :
               victim->sex == SEX_MALE ? "male" : victim->sex == SEX_FEMALE ? "female" : "neutral",
               victim->in_room == NULL ? 0 : victim->in_room->vnum,
               IS_NPC( victim ) ? victim->pIndexData->count : 1,
               IS_NPC( victim ) ? victim->pIndexData->killed : victim->pcdata->mdeaths + victim->pcdata->pdeaths,
               victim->id,
               IS_NPC( victim ) ? " &z(&C" : "",
               IS_NPC( victim ) ? itoa( victim->sid ) : "",
               IS_NPC( victim ) ? "&z)" : "" );

    if ( victim->pcdata && victim->pcdata->location_type > CHAR_ON_GROUND && victim->pcdata->location_id > 0 )
    {
        char loctype[64], locname[MIL];
        if ( victim->pcdata->location_type == CHAR_ON_SHIP && ( ship = ship_from_id( victim->pcdata->location_id ) ) != NULL )
        {
            snprintf( loctype, 64, "Ship" );
            snprintf( locname, MIL, "%s", ship->name );
        }
        else if ( victim->pcdata->location_type == CHAR_IN_VEHICLE && ( vehicle = vehicle_from_id( victim->pcdata->location_id) ) != NULL )
        {
            snprintf( loctype, 64, "Vehicle" );
            snprintf( locname, MIL, "%s", vehicle->name );
        }
        else if ( victim->pcdata->location_type == CHAR_IN_STRUCTURE && ( structure = structure_from_id( victim->pcdata->location_id ) ) != NULL )
        {
            snprintf( loctype, 64, "Structure" );
            snprintf( locname, MIL, "%s", structure->name );
        }
        else
        {
            snprintf( loctype, 64, "Other" );
            snprintf( locname, MIL, "None" );
        }
        ch_println( ch, "&zLocation: &C%s %d &z(&C%s&z)", loctype, victim->pcdata->location_id, locname );
    }

    if ( IS_NPC( victim ) )
        ch_println( ch, "&zMob Difficulty Level: &C%d%s",
                   victim->pIndexData->difficulty,
                   victim->pIndexData->difficulty == -1 ? " (Non-Combat)" :
                   victim->pIndexData->difficulty == 0 ? " (Custom)" : "" );

    ch_println( ch,
               "&zStr: &C%d  &zInt: &C%d  &zWis: &C%d  &zDex: &C%d  &zCon: &C%d  &zCha: &C%d  &zLck: &C%d  &zFrc: &C%d",
               get_curr_str( victim ), get_curr_int( victim ), get_curr_wis( victim ), get_curr_dex( victim ),
               get_curr_con( victim ), get_curr_cha( victim ), get_curr_lck( victim ), get_curr_frc( victim ) );
    ch_println( ch, "&zHps: &C%d&z/&C%d  &zForce: &C%d&z/&C%d   &zMove: &C%d&z/&C%d", victim->hit, victim->max_hit,
               victim->mana, victim->max_mana, victim->move, victim->max_move );

    if ( !IS_NPC( victim ) )
    {
        int ability;
        ch_println( ch, "&z&Y&W&zMain Ability: &C%d", victim->main_ability );

        for ( ability = 0; ability < MAX_ABILITY; ability++ )
            ch_println( ch, "&C%-15s   &zLevel: &G%-3d   &z%sMax: &C%-3d   &zExp: &C%-10ld   &zNext: &C%-10ld",
                       flag_value_name( ability_name, ability ), victim->skill_level[ability],
                       victim->legacymax[ability] == 0 ? "Racial" : "Legacy",
                       max_level( victim, ability ),
                       victim->experience[ability], exp_level( victim->skill_level[ability] + 1 ) );

        // GRAL Missing custommax check here?
    }

    ch_println( ch, "&zTop Level: &Y%d     &zAlign: &C%d  &zAC: &C%d  &zCredits: &C%d  &zBank: &C%d",
               victim->top_level, victim->alignment, GET_AC( victim ), victim->gold, get_bank_sum( victim ) );

    //if ( victim->race < MAX_PC_RACE && victim->race >= 0 && IS_NPC(victim))
    //  ch_println( ch, "&zRace: &C%s", pc_race[victim->race] );
    if ( victim->race != NULL )
        ch_println( ch, "&zRace: &C%s (#%d)", victim->race->race_name, victim->race->id );

    if ( !IS_NPC( victim ) )
    {
        char bf1[256], bf2[256], bf3[256], bf4[256];
        snprintf( bf1, 256, "%s", fclass( victim->pcdata->frank, victim->pcdata->fclass, victim->alignment ) );
        snprintf( bf2, 256, "%s", !str_cmp( sysdata.sithlord, victim->name ) && sysdata.ruleoftwo == TRUE ? "&GYes" : "&RNo" );
        snprintf( bf3, 256, "%s", !str_cmp( sysdata.sithapprentice, victim->name ) && sysdata.ruleoftwo == TRUE ? "&GYes" : "&RNo" );
        snprintf( bf4, 256, "%s", str_cmp( sysdata.sithapprentice, victim->name ) && victim->pcdata->clan == get_clan( "Sith Order" ) && victim->pcdata->frank != FRANK_NONE && str_cmp( sysdata.sithlord, victim->name ) && sysdata.ruleoftwo == TRUE ? "&GYes" : "&RNo" );
        ch_println( ch, "&zForce Rank: &W%s | &zSith Lord: &W%s | &zSith Apprentice: &W%s | &zSith, Not Apprentice: &W%s", bf1, bf2, bf3, bf4 );
        ch_println( ch, "&zNatroll attempted: [&W%s&z] &W| &zCorruption Counters: &W%d", victim->pcdata->natroll_done ? "X" : " ", victim->corruption_counters );
        if ( ch->pcdata->clan )
            ch_println( ch, "&zClan Rank: &W%s | &zClan Division: &W%s",
                       get_rank( victim ), get_division( victim ) );
    }

    ch_println( ch, "&zHitroll: &C%d   &zDamroll: &C%d   &zPosition: &C%d   &zWimpy: &C%d ",
               GET_HITROLL( victim ), GET_DAMROLL( victim ), victim->position, victim->wimpy );
    ch_println( ch, "&zFighting: &R%s    &zMaster: &R%s    &zLeader: &R%s",
               ( victim->fighting && victim->fighting->who && !NULLSTR( victim->fighting->who->name ) ) ? victim->fighting->who->name : "(none)",
               ( victim->master && !NULLSTR( victim->master->name ) ) ? victim->master->name : "(none)", ( victim->leader && !NULLSTR( victim->leader->name ) ) ? victim->leader->name : "(none)" );
    ch_println( ch, "&zCOUNTERS-> &zWarned: &C%d   &zBusy: &C%d", victim->warned, victim->busy );

    if ( !IS_NPC( victim ) )
        ch_println( ch, "&zThirst: &C%d   &zFull: &C%d   &zDrunk: &C%d",
                   victim->pcdata->condition[COND_THIRST], victim->pcdata->condition[COND_FULL],
                   victim->pcdata->condition[COND_DRUNK] );
    else
        ch_println( ch, "&zHit dice: &C%dd%d&z+&C%d.  &zDamage dice: &C%dd%d&z+&C%d.",
                   victim->pIndexData->hitnodice, victim->pIndexData->hitsizedice,
                   victim->pIndexData->hitplus, victim->pIndexData->damnodice,
                   victim->pIndexData->damsizedice, victim->pIndexData->damplus );

    ch_println( ch, "&zMentalState: &C%d   &zEmotionalState: &C%d", victim->mental_state, victim->emotional_state );
    ch_println( ch, "&zSaving throws: &C%d %d %d %d %d.",
               victim->saving_poison_death,
               victim->saving_wand, victim->saving_para_petri, victim->saving_breath, victim->saving_spell_staff );
    ch_println( ch, "&zCarry figures: items (&C%d&z/&C%d&z)  weight (&C%d&z/&C%d&z)   Numattacks: &C%d",
               victim->carry_number, can_carry_n( victim ), victim->carry_weight, can_carry_w( victim ),
               victim->numattacks );
    ch_println( ch, "&zPlayed: &C%s   &zTimer: &C%d   &zAct: &C%d", dhms_string( victim->played, true ), victim->timer, victim->act );
    char saved[128];
    snprintf( saved, 128, "%s", mini_c_time( victim->updated_at, get_timezone( ch ), true ) );
    ch_println( ch, "&zSaved: &C%s   &zBacked up: &C%s", saved, !IS_NPC( victim ) ? mini_c_time( victim->pcdata->last_backup, get_timezone( ch ), true ) : "N/A");
    ch_println( ch, "&zAct flags: &C%s", flag_string( &victim->act, act_flags ) );

    if ( !IS_NPC( victim ) )
    {
        ch_println( ch, "&zPcflags: &C%s", flag_string( &victim->pcdata->flags, pc_flags ) );
        ch_println( ch, "&zWanted on: &C%s", print_wanted( victim, FALSE ) );
        ch_println( ch, "&zHas immunity on: &C%s", print_wanted( victim, TRUE ) );
        ch_println( ch, "&zClone stage: %d", victim->pcdata->clone );
    }

    ch_println( ch, "&zAffected by: &C%s", flag_string( &victim->affected_by, affect_flags ) );
    ch_println( ch, "&zSpeaks: &C%s\n&zSpeaking: &C%s", flag_string( &victim->speaks, languages ),
               flag_string( &victim->speaking, languages ) );
    current_tone = find_tone( victim->tone );
    ch_println( ch, "&zTone: &C%s      &zText Color: %s%s &z(&C#%d&z)",
               current_tone ? current_tone->name : "(unknown)",
               victim->txtclr >= 0 && victim->txtclr < txtclr_count ? txtclr_codes[victim->txtclr] : "&C",
               victim->txtclr >= 0 && victim->txtclr < txtclr_count ? txtclr_names[victim->txtclr] : "(unknown)",
               victim->txtclr
             );

    if ( victim->pcdata && victim->pcdata->bestowments && victim->pcdata->bestowments[0] != '\0' )
        ch_println( ch, "&zBestowments: &C%s", victim->pcdata->bestowments );

    if ( victim->pcdata && victim->pcdata->clan ) {
        RANK_DATA* rank = get_rank_obj(victim);
        ch_println( ch, "&zRank Empowerments: &C%s", (rank && !NULLSTR(rank->empowerments)) ? rank->empowerments : "" );
    }

    ch_printf( ch, "&zShort description: &Y%s\n&zLong  description: &Y%s",
               victim->short_descr, victim->long_descr[0] != '\0' ? victim->long_descr : "(none)\n" );

    if ( IS_NPC( victim ) )
        ch_println( ch, "&zMobile is running these specials:\n&z &G%-20s &z &G%-20s &z\n&z &G%-20s &z &G%-20s &z|",
                   ( victim->spec_fun && !NULLSTR( victim->spec_funname ) ) ? victim->spec_funname :
                   ( ( victim->pIndexData && victim->pIndexData->spec_fun && !NULLSTR( victim->pIndexData->spec_funname ) ) ? victim->pIndexData->spec_funname : "(empty)" ),
                   ( victim->spec_2 && !NULLSTR( victim->spec_funname_2 ) ) ? victim->spec_funname_2 :
                   ( ( victim->pIndexData && victim->pIndexData->spec_2 && !NULLSTR( victim->pIndexData->spec_funname_2 ) ) ? victim->pIndexData->spec_funname_2 : "(empty)" ),
                   ( victim->spec_3 && !NULLSTR( victim->spec_funname_3 ) ) ? victim->spec_funname_3 :
                   ( ( victim->pIndexData && victim->pIndexData->spec_3 && !NULLSTR( victim->pIndexData->spec_funname_3 ) ) ? victim->pIndexData->spec_funname_3 : "(empty)" ),
                   ( victim->spec_4 && !NULLSTR( victim->spec_funname_4 ) ) ? victim->spec_funname_4 :
                   ( ( victim->pIndexData && victim->pIndexData->spec_4 && !NULLSTR( victim->pIndexData->spec_funname_4 ) ) ? victim->pIndexData->spec_funname_4 : "(empty)" ) );

    ch_println( ch, "&zResistant  : &C%s", flag_string( &victim->resistant, resistant_types ) );
    ch_println( ch, "&zImmune     : &C%s", flag_string( &victim->immune, resistant_types ) );
    ch_println( ch, "&zSusceptible: &C%s", flag_string( &victim->susceptible, resistant_types ) );
    ch_println( ch, "&zAttacks    : &C%s", flag_string( &victim->attacks, attack_types ) );
    ch_println( ch, "&zDefenses   : &C%s", flag_string( &victim->defenses, defense_types ) );
    ch_println( ch, "&zVariables  : &C%d&z. Use &Cmstat <&wtarget&C> vars &zto view.", count_dvars( victim->vars ) );
    ch_println( ch, "&zAffects    : &C%d&z. Use &Cmstat <&wtarget&C> affects &zto view.", count_dvars( victim->vars ) );


    CALL_DATA* called = NULL;

    if ( ( called = victim->called ) != NULL )
    {
        if ( called->type == MOB_TEMP_CUSTOM )
        {
            MOB_INDEX_DATA* backup_index = called->mob;

            if ( backup_index )
                strlcpy( buf, backup_index->short_descr, MIL );
            else
                snprintf( buf, MIL, "(invalid custom mob)" );
        }

        if ( called->type == MOB_TEMP_THUG )
            snprintf( buf, MIL, "a Thug" );

        if ( called->type == MOB_TEMP_MEDIC )
            snprintf( buf, MIL, "a Medic" );

        if ( called->type == MOB_TEMP_REINFORCEMENTS )
            snprintf( buf, MIL, "Reinforcements" );

        if ( called->type == MOB_TEMP_GUARD )
            snprintf( buf, MIL, "a Guard" );

        if ( called->type == MOB_TEMP_MESSAGEDRONE )
            snprintf( buf, MIL, "a Message Drone" );

        if ( called->type == MOB_TEMP_DIPLOMAT )
            snprintf( buf, MIL, "a Diplomat" );

        if ( called->type == MOB_TEMP_SOLDIER )
            snprintf( buf, MIL, "a Soldier" );

        if ( called->type == MOB_TEMP_ROYALGUARD )
            snprintf( buf, MIL, "a Royal Guard" );

        if ( called->type == MOB_TEMP_DROIDEKA )
            snprintf( buf, MIL, "a Droideka" );

        ch_println( ch, "&z(&CR&z)einforcements '&C%s&z' is on its way in &C%d &ztick(s).", buf, called->wait_time );
    }

    for ( paf = victim->first_affect; paf; paf = paf->next )
        if ( ( skill = skill_from_id( paf->type ) ) != NULL )
            ch_println( ch, "&z%s: '&C%s&z' modifies &C%s &zby &C%d &zfor &C%d &zrounds with bits &C%s.",
                       skill_tname[skill->type], skill->name, affect_loc_name( paf->location ), paf->modifier, paf->duration,
                       flag_string( &paf->bitvector, affect_flags ) );

    return;
}



CMDF do_mfind( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char* argValue;
    MOB_INDEX_DATA* pMobIndex;
    int nMatch;
    bool fAll;
    bool expandStats = false;
    int flag = -1;
    EXT_BV flags;
    xCLEAR_BITS( flags );
    set_pager_color( AT_PLAIN, ch );
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Mfind whom?" );
        return;
    }

    while ( true )
    {
        if ( !str_prefix( "flag:", arg ) )
        {
            argValue = arg + strlen( "flag:" );

            if ( ( flag = get_flag( argValue, act_flags ) ) == FLAG_UNDEFINED )
            {
                ch_println( ch, "Mob flag '%s' not found.", argValue );
                return;
            }

            xSET_BIT( flags, flag );
            argument = one_argument( argument, arg );
        }
        else if ( !str_prefix( "expand:", arg ) )
        {
            argValue = arg + strlen( "expand:" );

            if ( !str_cmp( argValue, "stats" ) )
                expandStats = true;
            else
            {
                ch_println( ch, "Invalid expand mode '%s'. Supported: stats", argValue );
                return;
            }

            argument = one_argument( argument, arg );
        }
        else
        {
            break;
        }
    }

    fAll = NULLSTR( arg ) || !str_cmp( arg, "all" );
    nMatch = 0;

    for ( pMobIndex = first_mob_index; pMobIndex; pMobIndex = pMobIndex->next )
    {
        if ( !fAll && !nifty_is_name( arg, pMobIndex->player_name ) )
            continue;

        if ( !xIS_EMPTY( flags ) && !xHAS_BITS( pMobIndex->act, flags ) )
            continue;

        if ( nMatch == 0 )
        {
            if ( expandStats )
            {
                pager_printf( ch, "&W              &z(&WS&z|&wP&z|&GS&z|&rA&z|&RP&z: &WSanctuary&z|&wProtect&z|&GSafe&z|&rAggressive&z|&RProgs&z)\n" );
                pager_printf( ch, "&W    vnum &z| &Wdf lvl  maxhit maxmove armor  hr  dr  S&z|&wP&z|&GS&z|&rA&z|&RP&z| &Wname\n" );
            }
            else
                pager_printf( ch, "&W    vnum &z| &Wname\n" );

            pager_printf( ch, "&z-------------------------------------------------------------------------------\n" );
        }

        nMatch++;

        if ( expandStats )
            pager_printf( ch, "&C%8d &z| &C%2d %3d %7d %7d %5d  %2d  %2d  &W%s&z|&w%s&z|&G%s&z|&r%s&z|&R%s&z| &w%s\n",
                            pMobIndex->vnum,
                            pMobIndex->difficulty,
                            pMobIndex->level,
                            pMobIndex->hitplus + pMobIndex->hitsizedice * pMobIndex->hitnodice,
                            pMobIndex->max_move,
                            pMobIndex->ac,
                            pMobIndex->hitroll,
                            pMobIndex->damroll,
                            xIS_SET( pMobIndex->affected_by, AFF_SANCTUARY ) ? "S" : " ",
                            xIS_SET( pMobIndex->affected_by, AFF_PROTECT ) ? "P" : " ",
                            xIS_SET( pMobIndex->act, ACT_SAFE ) ? "S" : " ",
                            xIS_SET( pMobIndex->act, ACT_AGGRESSIVE ) ? "A" : " ",
                            ( !NULLSTR( pMobIndex->lprog_code ) || pMobIndex->first_mprog ) ? "P" : " ",
                            capitalize_first( pMobIndex->short_descr )
                        );
        else
            pager_printf( ch, "&C%8d &z| &w%s\n", pMobIndex->vnum, capitalize_first( pMobIndex->short_descr ) );
    }

    if ( nMatch )
        pager_printf( ch, "&zNumber of matches: &C%d&w\n", nMatch );
    else
        ch_println( ch, "Nothing like that in hell, earth, or heaven." );

    return;
}



CMDF do_ofind( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char displayExpand[MIL];
    char* argValue;
    EXT_BV flags;
    xCLEAR_BITS( flags );
    int flag = -1;
    int type = -1;
    OBJ_INDEX_DATA* pObjIndex;
    int nMatch;
    bool fAll = FALSE;
    bool expandValues = FALSE;
    bool expandStats = FALSE;
    set_pager_color( AT_PLAIN, ch );
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Ofind what?" );
        return;
    }

    while ( true )
    {
        if ( !str_prefix( "flag:", arg ) )
        {
            argValue = arg + strlen( "flag:" );

            if ( ( flag = get_flag( argValue, obj_flags ) ) == FLAG_UNDEFINED )
            {
                ch_println( ch, "Object flag '%s' not found.", argValue );
                return;
            }

            xSET_BIT( flags, flag );
            argument = one_argument( argument, arg );
        }
        else if ( !str_prefix( "type:", arg ) )
        {
            argValue = arg + strlen( "type:" );

            if ( ( type = get_flag( argValue, obj_types ) ) == FLAG_UNDEFINED )
            {
                ch_println( ch, "Type '%s' not found.", argValue );
                return;
            }

            argument = one_argument( argument, arg );
        }
        else if ( !str_prefix( "expand:", arg ) )
        {
            argValue = arg + strlen( "expand:" );

            if ( !str_cmp( argValue, "values" ) )
                expandValues = true;
            else if ( !str_cmp( argValue, "stats" ) )
                expandStats = true;
            else
            {
                ch_println( ch, "Invalid expand mode '%s'. Supported: stats values", argValue );
                return;
            }

            argument = one_argument( argument, arg );
        }
        else
        {
            break;
        }
    }

    fAll = NULLSTR( arg ) || !str_cmp( arg, "all" );
    nMatch = 0;
    displayExpand[0] = '\0';

    for ( pObjIndex = first_obj_index; pObjIndex; pObjIndex = pObjIndex->next )
    {
        if ( !fAll && !nifty_is_name( arg, pObjIndex->name ) )
            continue;

        if ( type != -1 && pObjIndex->item_type != type )
            continue;

        if ( !xIS_EMPTY( flags ) && !xHAS_BITS( pObjIndex->extra_flags, flags ) )
            continue;

        if ( nMatch == 0 )
        {
            if ( expandValues )
                pager_printf( ch, "&W    vnum &z|&W  v0   v1   v2   v3   v4   v5  &z|&W name\n" );
            else if ( expandStats )
                pager_printf( ch, "&W    vnum &z| &Wwgt  lyr    cost &z| &Wname\n" );
            else
                pager_printf( ch, "&W    vnum &z| &Wname\n" );

            pager_printf( ch, "&z-------------------------------------------------------------------------------\n" );
        }

        nMatch++;

        if ( expandValues )
            snprintf( displayExpand, MIL, "&C %4d %4d %4d %4d %4d %4d &z|",
                        pObjIndex->value[0], pObjIndex->value[1], pObjIndex->value[2],
                        pObjIndex->value[3], pObjIndex->value[4], pObjIndex->value[5] );
        else if ( expandStats )
            snprintf( displayExpand, MIL, "&C %4d %3d %7d &z|", pObjIndex->weight, pObjIndex->layers, pObjIndex->cost );

        pager_printf( ch, "&C%8d &z|%s&w %s\n", pObjIndex->vnum, displayExpand, capitalize_first( stripclr( pObjIndex->short_descr ) ) );
    }

    if ( nMatch )
        pager_printf( ch, "&zNumber of matches:&C %d&w\n", nMatch );
    else
        ch_println( ch, "Nothing like that in hell, earth, or heaven." );

    return;
}

CMDF do_mwhere( CHAR_DATA* ch, char* argument )
{
    // GRAL 00:30 ImmNet[Walldo]: of course owhere vnum works but not mwhere vnum
    char arg[MIL];
    char* argValue;
    // char arg2[MIL];
    CHAR_DATA* victim;
    PLANET_DATA* planet;
    bool found = FALSE, vnumsearch = FALSE;
    int cnt = 0;
    set_pager_color( AT_PLAIN, ch );
    int flag;
    EXT_BV flags;
    xCLEAR_BITS( flags );
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Mwhere whom and on what planet/all?" );
        return;
    }

    while ( true )
    {
        if ( !str_prefix( "flag:", arg ) )
        {
            argValue = arg + strlen( "flag:" );

            if ( ( flag = get_flag( argValue, act_flags ) ) == FLAG_UNDEFINED )
            {
                ch_println( ch, "Mob flag '%s' not found.", argValue );
                return;
            }

            xSET_BIT( flags, flag );
            argument = one_argument( argument, arg );
        }
        else
        {
            break;
        }
    }

    planet = get_planet( argument );

    if ( planet == NULL && argument[0] != '\0' && str_cmp( argument, "all" ) )
    {
        ch_println( ch, "No such planet." );
        return;
    }

    if ( is_number( arg ) )
        vnumsearch = TRUE;

    found = FALSE;

    for ( victim = first_char; victim; victim = victim->next )
    {
        if ( !IS_NPC( victim ) )
            continue;

        if ( !victim->in_room )
            continue;

        if ( !xIS_EMPTY( flags ) && !xHAS_BITS( victim->act, flags ) )
            continue;

        if ( ( vnumsearch ) )
        {
            if ( !victim->pIndexData )
            {
                bug( "Object %s has no pIndexData!", victim->short_descr );
                continue;
            }

            if ( victim->pIndexData->vnum != atoi( arg ) )
                continue;
        }
        else if ( !NULLSTR( arg ) )
        {
            if ( !nifty_is_name( arg, victim->name ) )
                continue;
        }

        if ( ( planet != NULL && planet == victim->in_room->area->planet ) || argument[0] == '\0' || !str_cmp( argument, "all" ) )
        {
            cnt++;
            found = TRUE;
            pager_printf( ch, "&z[&C%5d&z] %-28s &z[&w%5d&z] %s &w(%d)&w\n",
                          victim->pIndexData->vnum, victim->short_descr, victim->in_room->vnum, victim->in_room->name, cnt );
        }
    }

    if ( !found )
        act( AT_PLAIN, "You didn't find any $T.", ch, NULL, arg, TO_CHAR );

    return;
}

CMDF do_gwhere( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    DESCRIPTOR_DATA* d;
    bool pmobs = FALSE;
    int low = 1, high = 65, count = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !NULLSTR( arg1 ) )
    {
        if ( arg1[0] == '\0' || arg2[0] == '\0' )
        {
            send_to_pager_color( "\n&wSyntax:  gwhere | gwhere <low> <high> | gwhere <low> <high> mobs\n", ch );
            return;
        }

        low = atoi( arg1 );
        high = atoi( arg2 );
    }

    if ( low < 1 || high < low || low > high || high > 65 )
    {
        send_to_pager_color( "&wInvalid level range.\n", ch );
        return;
    }

    argument = one_argument( argument, arg3 );

    if ( !str_cmp( arg3, "mobs" ) )
        pmobs = TRUE;

    pager_printf( ch, "\nGlobal %s locations:\n", pmobs ? "mob" : "player" );

    if ( !pmobs )
    {
        for ( d = first_descriptor; d; d = d->next )
            if ( ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                    && ( victim = d->character ) != NULL && !IS_NPC( victim ) && victim->in_room
                    && can_see( ch, victim ) && victim->top_level >= low && victim->top_level <= high )
            {
                pager_printf( ch, "(%2d) %-12.12s   [%-5d - %-19.19s]   %-25.25s\n",
                              victim->top_level, victim->name, victim->in_room->vnum, victim->in_room->area->name,
                              victim->in_room->name );
                count++;
            }
    }
    else
    {
        for ( victim = first_char; victim; victim = victim->next )
            if ( IS_NPC( victim )
                    && victim->in_room && can_see( ch, victim ) && victim->top_level >= low && victim->top_level <= high )
            {
                pager_printf( ch, "(%2d) %-12.12s   [%-5d - %-19.19s]   %-25.25s\n",
                              victim->top_level, victim->name, victim->in_room->vnum, victim->in_room->area->name,
                              victim->in_room->name );
                count++;
            }
    }

    pager_printf( ch, "%d %s found.\n", count, pmobs ? "mobs" : "characters" );
    return;
}

