        vnumsearch = TRUE;

    found = FALSE;

    for ( obj = first_object; obj; obj = obj->next )
    {
        if ( !NULLSTR( arg ) && !nifty_is_name( arg, obj->name ) && ( !vnumsearch ) )
            continue;

        if ( type != -1 && obj->item_type != type )
            continue;

        if ( !xIS_EMPTY( flags ) && !xHAS_BITS( obj->extra_flags, flags ) )
            continue;

        found = TRUE;

