CMDF do_snoop( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    DESCRIPTOR_DATA* d;
    CHAR_DATA* victim;
    int v, i, cnt = 0;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Snoop whom? 'Snoop self' to cancel your snooping." );
        return;
    }

    if ( !str_cmp( arg, "self" ) )
    {
        ch_println( ch, "Cancelling all snoops." );

        for ( d = first_descriptor; d; d = d->next )
        {
            for ( i = 0; i <= 5; i++ )
            {
                if ( d->snoop_by[i] == ch->desc )
                    d->snoop_by[i] = NULL;
            }
        }

        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    for ( i = 0; i <= 5; i++ )
    {
        if ( victim->desc->snoop_by[i] != NULL )
            cnt++;
    }

    if ( cnt >= 5 )
    {
        ch_println( ch, "&zThere are already &C5&z people snooping that target!&w" );
        return;
    }

    /*
        Minimum snoop level... a secret mset value
        makes the snooper think that the victim is already being snooped
    */
    if ( get_trust( victim ) >= get_trust( ch ) || ( victim->pcdata && victim->pcdata->min_snoop > get_trust( ch ) ) )
    {
        ch_println( ch, "&w&RBusy already. Maximum of five pipes already established." );
        return;
    }

    if ( ch->desc )
    {
        for ( v = 0; v <= 5; v++ )
        {
            for ( d = ch->desc->snoop_by[v]; d; d = d->snoop_by[v] )
            {
                if ( d->character == victim || d->original == victim )
                {
                    ch_println( ch, "No snoop loops." );
                    return;
                }
            }
        }
    }

    /*  Snoop notification for higher imms, if desired, uncomment this
        if ( get_trust(victim) > LEVEL_GOD && get_trust(ch) < LEVEL_SUPREME )
          write_to_descriptor( victim->desc->descriptor, "\nYou feel like someone is watching your every move...\n", 0 );
    */
    for ( i = 0; i <= 5; i++ )
    {
        if ( victim->desc->snoop_by[i] == NULL )
        {
            victim->desc->snoop_by[i] = ch->desc;
            ch_println( ch, "&zYou are now snooping them. You are snoop number &C%d&z on this player.&w", 1 + i );
            return;
        }
    }

    ch_println( ch, "&w&RBusy already. Maximum of five pipes already established." );
    /*
        victim->desc->snoop_by = ch->desc;
    */
    /*
        ch_println( ch, "Ok." );
    */
    return;
}

CMDF do_switch( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    one_argument( argument, arg );

    if ( !ch || !ch->desc )
        return;

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Switch into whom?" );
        return;
    }

    if ( ch->desc->original )
    {
        ch_println( ch, "You are already switched." );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You cannot switch into yourself." );
        return;
    }

    if ( victim->desc )
    {
        ch_println( ch, "Character in use." );
        return;
    }

    if ( !IS_NPC( victim ) )
    {
        ch_println( ch, "You cannot switch into a player!" );
        return;
    }

    ch->desc->character = victim;
    ch->desc->original = ch;
    victim->desc = ch->desc;
    victim->pcdata = duplicate_pcdata( ch->pcdata );
    ch->desc = NULL;
    ch->switched = victim;
    victim->switched = ch;
    xSET_BIT( victim->deaf, CHANNEL_TUNE );
    xSET_BIT( victim->deaf, CHANNEL_DEBUG );
    if ( !xIS_SET( victim->act, ACT_IS_NPC ) )
        xSET_BIT( victim->act, ACT_IS_NPC );
    ch_println( victim, "Done." );
    return;
}

CMDF do_return( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    if ( !ch )
        return;

    if ( !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) )
    {
        ch_println( ch, "You're not switched into another body." );
        return;
    }

    ch_println( ch, "You return to your original body." );

    if ( ch->desc )
    {
        ch->desc->character = ch->desc->original;
        ch->desc->original = NULL;
        ch->desc->character->desc = ch->desc;
        ch->desc->character->switched = NULL;
        ch->desc = NULL;
    }

    if ( ch->pcdata )
        free_pcdata( ch->pcdata );
    ch->pcdata = NULL;
    ch->switched = NULL;
    return;
}

