    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Cminvoke <&wvnum&C>&w" );
        return;
    }

    if ( !is_number( arg ) )
    {
        char arg2[MIL];
        int cnt;
        int count = number_argument( arg, arg2 );
        vnum = -1;

        for ( pMobIndex = first_mob_index; pMobIndex; pMobIndex = pMobIndex->next )
        {
            if ( nifty_is_name( arg2, pMobIndex->player_name ) && ++cnt == count )
            {
                vnum = pMobIndex->vnum;
                break;
            }
        }

        if ( vnum == -1 )
        {
            ch_println( ch, "No such mobile exists." );
            return;
        }
    }
    else
        vnum = atoi( arg );

    if ( ( pMobIndex = get_mob_index( vnum ) ) == NULL )
    {
        ch_println( ch, "No mobile has that vnum." );
        return;
    }

    victim = create_mobile( pMobIndex );
    char_to_room( victim, ch->in_room );
    lua_trigger_on_ch_spawned( victim );

    save_persistent_mob( victim, true );

    if ( !has_pcflag( ch, PCFLAG_WIZINVIS ) )
        act( AT_IMMORT, "$n has created $N!", ch, NULL, victim, TO_ROOM );

    ch_println( ch, "Ok." );
    return;
}



CMDF do_oinvoke( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    OBJ_INDEX_DATA* pObjIndex;
    OBJ_DATA* obj;
    int amount;
    int level;
    int vnum;
    int i;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Coinvoke <&wvnum&C> <&wamount&C>&w" );
        return;
    }

    level = get_trust( ch );

    if ( NULLSTR( arg2 ) )
    {
        amount = 1;
    }
    else
    {
        if ( !is_number( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Coinvoke <&wvnum&C> <&wamount&C>&w" );
            return;
        }

        amount = atoi( arg2 );

        if ( amount < 1 || amount > 99 )
        {
            ch_println( ch, "Amount must be between 1 and 99." );
            return;
        }
    }

    if ( !is_number( arg1 ) )
    {
        char arg[MIL];
        int cnt;
        int count = number_argument( arg1, arg );
        vnum = -1;

        for ( pObjIndex = first_obj_index; pObjIndex; pObjIndex = pObjIndex->next )
        {
            if ( nifty_is_name( arg, pObjIndex->name ) && ++cnt == count )
            {
                vnum = pObjIndex->vnum;
                break;
            }
        }

        if ( vnum == -1 )
        {
            ch_println( ch, "No such object exists." );
            return;
        }
    }
    else
        vnum = atoi( arg1 );

    if ( ( pObjIndex = get_obj_index( vnum ) ) == NULL )
    {
        ch_println( ch, "No object has that vnum." );
        return;
    }

    if ( !xIS_SET( pObjIndex->extra_flags, ITEM_PROTOTYPE )
            && !is_name( "objects", ch->pcdata->bestowments ) && get_trust( ch ) < 105 )
    {
        ch_println( ch, "You cannot invoke that object." );
        return;
    }

    for ( i = 0; i < amount; i++ )
    {
        obj = create_object( pObjIndex, level );

        if ( CAN_WEAR( obj, ITEM_TAKE ) )
        {
            obj = obj_to_char( obj, ch );
        }
        else
        {
            obj = obj_to_room( obj, ch->in_room );

            if ( i == 1 && !has_pcflag( ch, PCFLAG_WIZINVIS ) )
                act( AT_IMMORT, "$n has created $p!", ch, obj, NULL, TO_ROOM );
        }
    }

    ch_println( ch, "Ok." );
    return;
}

/**
    @param ch Character executing the purge, to avoid purging a mob doing it. Nullable when no character is involved.
*/
void purge_room( ROOM_INDEX_DATA* room, CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    CHAR_DATA* vnext;
    OBJ_DATA* obj;
    OBJ_DATA* obj_next;

    for ( victim = room->first_person; victim; victim = vnext )
    {
        vnext = victim->next_in_room;

        if ( IS_NPC( victim ) && victim != ch )
            extract_char( victim );
    }

    for ( obj = room->first_content; obj; obj = obj_next )
    {
        obj_next = obj->next_content;

        if ( obj->item_type == ITEM_SPACECRAFT )
            continue;

        extract_obj( obj );
    }
}

CMDF do_purge( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    OBJ_DATA* obj;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        purge_room( ch->in_room, ch );
        act( AT_IMMORT, "You purge the room!", ch, NULL, NULL, TO_CHAR );
        act( AT_IMMORT, "$n purges the room!", ch, NULL, NULL, TO_ROOM );
        return;
    }

    victim = NULL;
    obj = NULL;

    if ( ( victim = get_char_room( ch, arg ) ) == NULL && ( obj = get_obj_here( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    /* Single object purge in room for high level purge - Scryn 8/12*/
    if ( obj )
    {
        separate_obj( obj );
        act( AT_IMMORT, "$n purges $p.", ch, obj, NULL, TO_ROOM );
        act( AT_IMMORT, "You make $p disappear in a puff of smoke!", ch, obj, NULL, TO_CHAR );
        extract_obj( obj );
        return;
    }

    if ( IS_SWITCHED_NPC( victim ) )
    {
        ch_println( ch, "You cannot purge a switched player." );
        return;
    }


    if ( !IS_NPC( victim ) )
    {
        ch_println( ch, "Not on PC's." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You cannot purge yourself!" );
        return;
    }

    act( AT_IMMORT, "You purge $N.", ch, NULL, victim, TO_CHAR );
    act( AT_IMMORT, "$n purges $N.", ch, NULL, victim, TO_NOTVICT );
    extract_char( victim );
    return;
}

