CMDF do_balzhur( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], buf[MSL];
    CHAR_DATA* victim;
    ACCOUNT_DATA* acc = NULL;
    ACC_CHAR* ach = NULL;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Who is deserving of such a fate?" );
        return;
    }

    if ( ( victim = get_player_room( ch->in_room, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "I wouldn't even think of that if I were you..." );
        return;
    }

    victim->top_level = 1;
    victim->trust = 0;
    check_switch( victim, TRUE );
    set_char_color( AT_WHITE, ch );
    ch_println( ch, "You summon the demon Balzhur to wreak your wrath!" );
    ch_println( ch, "Balzhur sneers at you evilly, then vanishes in a puff of smoke." );
    set_char_color( AT_IMMORT, victim );
    ch_println( victim, "You hear an ungodly sound in the distance that makes your blood run cold!" );
    snprintf( buf, MSL, "Balzhur screams, 'You are MINE %s!!!'", victim->name );
    echo_to_all( AT_IMMORT, buf, ECHOTAR_ALL );
    {
        int ability;

        for ( ability = 0; ability < MAX_ABILITY; ability++ )
        {
            victim->experience[ability] = 1;
            victim->skill_level[ability] = 1;
        }
    }
    victim->max_hit = 500;
    victim->max_mana = 0;
    victim->set_max_mana = 0;
    victim->max_move = 1000;

    for ( SKILL_DATA* skill = first_skill; skill; skill = skill->next )
        set_learned_pct( victim, skill, 0 );

    victim->hit = victim->max_hit;
    victim->mana = victim->max_mana;
    victim->move = victim->max_move;
    do_help( victim, "M_BALZHUR_" );
    set_char_color( AT_WHITE, victim );
    ch_println( victim, "You awake after a long period of time..." );

    while ( victim->first_carrying )
        extract_obj( victim->first_carrying );

    acc = victim->pcdata->account != NULL ? victim->pcdata->account : ( !NULLSTR( victim->pcdata->account_name ) ? account_from_name( victim->pcdata->account_name ) : NULL );
    if ( !acc )
        acc = account_from_char( victim->name );

    if ( acc )
    {
        acc->level = 1;

        for ( ach = acc->first_char; ach; ach = ach->next )
        {
            if ( !str_cmp( ach->name, victim->name ) )
            {
                ach->level = 1;
                account_save( acc, true );
            }

            acc->level = UMAX( acc->level, ach->level );
        }
    }

    save_player( victim, false );
    return;
}

CMDF do_advance( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    char buf[MSL];
    CHAR_DATA* victim = NULL;
    SKILL_DATA* skill = NULL;
    int level, ability;
    int iLevel, iAbility;
    snprintf( buf, MSL, "%s", argument );
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg3 );
    argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' || arg3[0] == '\0' || !is_number( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Cadvance <&wchar&C> <&wability&C> <&wlevel&C>&w" );
        return;
    }

    victim = !str_cmp( arg1, "self" ) ? ch : get_player_world( arg1 );

    if ( victim == NULL )
    {
        ch_println( ch, "That player is not here." );
        return;
    }

    /*
        You can demote yourself but not someone else at your own trust. -- Narn
    */
    if ( get_trust( ch ) <= get_trust( victim ) && ch != victim )
    {
        ch_println( ch, "You can't do that." );
        return;
    }

    if ( !str_cmp( arg3, "all" ) )
    {
        /*
            advance [target] ALL [level]
        */
        if ( ( level = atoi( arg2 ) ) < 1 || level > 200 )
        {
            ch_println( ch, "Level must be 1 to 200." );
            return;
        }

        advance_all( ch, victim, level );
        return;
    }

    ability = -1;

    for ( iAbility = 0; iAbility < MAX_ABILITY; iAbility++ )
    {
        if ( !str_prefix( arg3, flag_value_name( ability_name, iAbility ) ) )
        {
            ability = iAbility;
            break;
        }
    }

    if ( ability == -1 || ability == DIPLOMACY_ABILITY )
    {
        ch_println( ch, "No Such ability." );
        do_advance( ch, "" );
        return;
    }

    if ( ( level = atoi( arg2 ) ) < 1 || level > 200 )
    {
        ch_println( ch, "Level must be 1 to 200." );
        return;
    }

    add_mset( ch, buf, get_trust( ch ), "Advance" );

    /*
        Lower level:
         Reset to level 1.
         Then raise again.
         Currently, an imp can lower another imp.
         -- Swiftest
    */
    if ( level <= victim->skill_level[ability] )
    {
        ch_println( ch, "Lowering a player's level!" );
        set_char_color( AT_IMMORT, victim );
        ch_println( victim, "Cursed and forsaken! The gods have lowered your level." );
        victim->experience[ability] = 0;
        victim->skill_level[ability] = 1;

        if ( ability == COMBAT_ABILITY )
            victim->max_hit = 500;

        if ( ability == FORCE_ABILITY )
        {
            victim->max_mana = 0;
            victim->set_max_mana = 0;
        }
    }
    else
    {
        ch_println( ch, "Raising a player's level!" );
        ch_println( victim, "The gods feel fit to raise your level!" );
    }

    if ( ability == FORCE_ABILITY )
    {
        if ( level > 1 && victim->pcdata->frank < 1 && ( level <= 60 || victim->skill_level[FORCE_ABILITY] == 1 ) )
            victim->pcdata->frank = 1;
        else if ( level > 60 && victim->pcdata->frank < 2 )
            victim->pcdata->frank = 2;
        victim->pcdata->awakened_at = (int)current_time;
    }

    for ( iLevel = victim->skill_level[ability]; iLevel < level; iLevel++ )
    {
        victim->experience[ability] = exp_level( iLevel + 1 );
        gain_exp( victim, 0, ability, FALSE );
    }

    if ( !IS_IMMORTAL( victim ) )
    {
        for ( skill = first_skill; skill; skill = skill->next )
        {
            // when someone's level max lowers, reset skills they have above that level
            if ( skill->guild < 0 || skill->guild >= MAX_ABILITY || skill->guild != ability )
                continue;

            if (  skill->min_level > victim->skill_level[skill->guild] )
                set_learned_pct( victim, skill, 0 );
        }
    }

    if ( ability == FORCE_ABILITY && victim->skill_level[FORCE_ABILITY] >= 2 )
    {
        FORCER_DATA* forcer = forcer_create( victim );

        if ( forcer && NULLSTR( forcer->awakened_by ) )
        {
            SET_STRING( forcer->awakened_by, ch->name );
            forcer->awakened_at = time( 0 );
            forcer_save( forcer, TRUE );
        }
    }

    if ( iAbility == FORCE_ABILITY && victim->skill_level[FORCE_ABILITY] <= 1 )
    {
        victim->pcdata->frank = FRANK_NONE;
        victim->pcdata->fclass = JEDI_NONE;
        FORCER_DATA* forcer = forcer_create( victim );
        if ( forcer )
            forcer_delete( forcer );
    }

    save_char_obj( victim, TRUE );
    return;
}

void advance_all( CHAR_DATA* ch, CHAR_DATA* victim, int level )
{
    int iAbility, iLevel, iMax;
    SKILL_DATA* skill = NULL;
    char buf[MSL];
    snprintf( buf, MSL, "&zChanging all of &C%s's &zlevels.\n", victim->name );
    send_to_char( buf, ch );

    for ( iAbility = 0; iAbility < MAX_ABILITY; iAbility++ )
    {
        if ( iAbility == DIPLOMACY_ABILITY )
            continue;

        iMax = max_level( victim, iAbility );

        if ( level < victim->skill_level[iAbility] )
        {
            snprintf( buf, MSL, "&zLowering [&C%s&z] from &C%d&z to &C%d&z\n", flag_value_name( ability_name, iAbility ),
                     victim->skill_level[iAbility], UMIN( level, iMax ) );
            send_to_char( buf, ch );

            if ( victim != ch )
            {
                snprintf( buf, MSL, "&zYour &C%s&z ability has been lowered to &C%d&z\n", flag_value_name( ability_name, iAbility ),
                         UMIN( level, iMax ) );
                send_to_char( buf, victim );
            }

            victim->experience[iAbility] = 0;
            victim->skill_level[iAbility] = 1;

            if ( iAbility == COMBAT_ABILITY )
                victim->max_hit = 500;

            if ( iAbility == FORCE_ABILITY )
                victim->max_mana = get_max_mana( victim );
        }
        else if ( level > victim->skill_level[iAbility] && iMax > victim->skill_level[iAbility] )
        {
            snprintf( buf, MSL, "&zRaising [&C%s&z] from &C%d&z to &C%d&z\n", flag_value_name( ability_name, iAbility ),
                     victim->skill_level[iAbility], UMIN( level, iMax ) );
            send_to_char( buf, ch );

            if ( victim != ch )
            {
                snprintf( buf, MSL, "&zYour &C%s&z ability has been raised to &C%d&z\n", flag_value_name( ability_name, iAbility ),
                         UMIN( level, iMax ) );
                send_to_char( buf, victim );
            }
        }

        if ( iAbility == FORCE_ABILITY )
        {
            if ( level > 1 && victim->pcdata->frank < 1 && ( level <= 60 || victim->skill_level[FORCE_ABILITY] == 1 ) )
                victim->pcdata->frank = 1;
            else if ( level > 60 && victim->pcdata->frank < 2 )
                victim->pcdata->frank = 2;
        }

        for ( iLevel = victim->skill_level[iAbility]; iLevel < level; iLevel++ )
        {
            victim->experience[iAbility] = exp_level( iLevel + 1 );

            if ( victim->skill_level[iAbility] >= iMax )
            {
                victim->experience[iAbility] = UMAX( 0, ( exp_level( iMax ) - 1 ) );
                continue;
            }

            ++victim->skill_level[iAbility];
            advance_level( victim, iAbility, TRUE );
        }

        if ( !IS_IMMORTAL( victim ) )
        {
            for ( skill = first_skill; skill; skill = skill->next )
            {
                // when someone's level max lowers, reset skills they have above that level
                if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
                    continue;

                if (  skill->min_level > victim->skill_level[skill->guild] )
                    set_learned_pct( victim, skill, 0 );
            }
        }

        if ( iAbility == FORCE_ABILITY && victim->skill_level[FORCE_ABILITY] >= 2 )
        {
            FORCER_DATA* forcer = forcer_create( victim );

            if ( forcer && NULLSTR( forcer->awakened_by ) )
            {
                SET_STRING( forcer->awakened_by, ch->name );
                forcer->awakened_at = time( 0 );
                forcer_save( forcer, TRUE );
            }
        }

        if ( iAbility == FORCE_ABILITY && victim->skill_level[FORCE_ABILITY] <= 1 )
        {
            victim->pcdata->frank = FRANK_NONE;
            victim->pcdata->fclass = JEDI_NONE;
            FORCER_DATA* forcer = forcer_create( victim );
            if ( forcer )
                forcer_delete( forcer );
        }
    }

    save_char_obj( victim, TRUE );
    return;
}

CMDF do_trust( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    CHAR_DATA* victim;
    int level;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' || !is_number( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Ctrust <&wchar&C> <&wlevel&C>&w" );
        return;
    }

    if ( ( victim = get_player_world( arg1 ) ) == NULL )
    {
        ch_println( ch, "That player is not here." );
        return;
    }

    if ( ( level = atoi( arg2 ) ) < 0 || level > MAX_LEVEL )
    {
        ch_println( ch, "Level must be 0 (reset) or 1 to 60." );
        return;
    }

    if ( level > get_trust( ch ) )
    {
        ch_println( ch, "Limited to your own trust." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You can't do that." );
        return;
    }

    victim->trust = level;
    ch_println( ch, "Ok." );
    return;
}

int restore_player_backup( CHAR_DATA* ch, const char* target, int id )
{
    if ( !ch || NULLSTR( target ) )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( id <= 0 )
    {
        ch_println( ch, "&RInvalid ID." );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    char arg[MIL];
    one_argument( target, arg );

    CHAR_DATA* xch = get_player_world( arg );
    if ( xch && !str_cmp( xch->name, arg ) && !IS_NPC( xch ) )
    {
        ch_println( ch, "&RThey're still logged in! Have them log out first." );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    xch = load_player_sql( arg, PLAYER_LIVING );
    if ( !xch ) xch = load_player_sql( arg, PLAYER_DEAD );

    if ( !xch )
    {
        ch_println( ch, "&zCould not find a player named &C%s&z. Cannot proceed.", arg );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    if ( !finalize_load_objects( &xch->first_carrying, &xch->last_carrying, (void*) xch, OBJ_IN_INVENTORY ) )
        bug( "%s: failed to finalize objects load for %s (OLD)", FUNC, xch->name );
    finalize_load_followers( xch );

    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int rows = 0, rval = 0;
    CHAR_DATA* tch = NULL;
    snprintf( selectquery, ( MSL * 2 ), "SELECT * FROM %s WHERE name ilike %s AND id = %d", DB_TABLE_PLAYER_BACKUPS, sql_escape_string( arg ), id );
    qresult = query_db( selectquery );
    rows = PQntuples(qresult);

    if ( qresult == NULL )
    {
        bug( "%s: null qresult", FUNC );
        if ( xch ) free_char( xch );
        return E_LOTJ_LOAD_ERROR;
    }

    if ( rows == 0 )
    {
        ch_println( ch, "&RNo backup for %s matching ID #%d", arg, id );
        if ( qresult ) PQclear( qresult );
        if ( xch ) free_char( xch );
        return E_LOTJ_SUCCESS;
    }

    if ( rows > 1 )
    {
        ch_println( ch, "&RToo many matching backups for %s matching ID #%d. Aborting.", arg, id );
        if ( qresult ) PQclear( qresult );
        if ( xch ) free_char( xch );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "&zAttempting to revert player &C%s&z to backup number &C%d&z...", arg, id );

    CREATE( tch, CHAR_DATA, 1 );
    if ( ( rval = fieldmap_postgres_row( qresult, 0, tch, char_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( tch, char_fields );
        ch_println( ch, "&RError loading backup. Cannot proceed." );
        if ( qresult ) PQclear( qresult );
        if ( xch ) free_char( xch );
        return E_LOTJ_LOAD_ERROR;
    }

    if ( !finalize_load_objects( &tch->first_carrying, &tch->last_carrying, (void*) tch, OBJ_IN_INVENTORY ) )
        bug( "%s: failed to finalize objects load for %s (NEW)", FUNC, tch->name );
    finalize_load_followers( tch );

    tch->id = xch->id;
    save_player_backup( xch );
    free_char( xch );
    int64_t timestamp = tch->updated_at;
    upsert_sql_fieldmap_row(DB_TABLE_PLAYERS, tch, char_fields, NO_FLAG);
    ch_println( ch, "&zSuccessfully reverted &C%s&z to timestamp &C%s&z.", tch->name, c_time( timestamp, get_timezone( ch ) ) );
    free_char( tch );

    if ( qresult )
        PQclear( qresult );

    return E_LOTJ_SUCCESS;
}

int list_player_backups( CHAR_DATA* ch, const char* target )
{
    if ( !ch || NULLSTR( target ) )
        return E_LOTJ_MISSING_ARGUMENTS;

    char arg[MIL], colstr[8];
    one_argument( target, arg );
    int cnt = 0, id = 0;
    int64_t date = 0;
    char selectquery[MSL * 2];
    PGresult *qresult = NULL;
    int row = 0, rows = 0;
    snprintf( selectquery, ( MSL * 2 ), "SELECT id, updated_at FROM %s WHERE name ilike %s", DB_TABLE_PLAYER_BACKUPS, sql_escape_string( arg ) );
    qresult = query_db( selectquery );
    rows = PQntuples(qresult);

    if ( qresult == NULL )
    {
        bug( "%s: null qresult", FUNC );
        return E_LOTJ_LOAD_ERROR;
    }

    if( rows == 0 )
    {
        ch_println( ch, "&zNo player backups found for %s.", arg );
        if ( qresult ) PQclear( qresult );
        return E_LOTJ_SUCCESS;
    }

    pager_println( ch, "&zShowing player backups for &C%s&z...", arg );
    pager_println( ch, "&z%-4s | %-s", "ID", "SAVE DATE" );
    for ( row = 0; row < rows; row++ )
    {
        id = atoi( PQgetvalue(qresult, row, 0) );
        date = atol( PQgetvalue(qresult, row, 1) );
        cnt++;
        snprintf( colstr, 8, "%s", cnt % 2 == 0 ? "&037" : "&116" );
        pager_println( ch, "%s%-4d &z| %s%-s", colstr, id, colstr, c_time( date, get_timezone( ch ) ) );
    }

    if ( qresult )
        PQclear( qresult );

    return E_LOTJ_SUCCESS;
}

CMDF do_prestore( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], buf2[MSL], arg[MIL], arg2[MIL], arg3[MIL];
    CHAR_DATA* victim;
    ACCOUNT_DATA* acc = NULL;
    DEATH_DATA* death = NULL;
    snprintf( buf2, MSL, "%s", capitalize( argument ) );
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    IMM_CHECK( ch );

    if ( NULLSTR( arg ) || NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Cprestore <&wcharacter name&C> list" );
        ch_println( ch, "&z        &Cprestore <&wcharacter name&C> revert <&w#&C>" );
        ch_println( ch, "&z        &Cprestore <&wcharacter name&C> resurrect" );
        return;
    }

    if ( !str_cmp( arg2, "resurrect" ) )
    {
        if ( ( victim = get_player_world( arg ) ) != NULL )
        {
            if ( !str_cmp( victim->name, arg ) && !IS_NPC( victim ) )
            {
                ch_println( ch, "&RNot while %s is still online.", victim->name );
                return;
            }
        }

        if ( ( victim = load_player_sql( arg, PLAYER_LIVING ) ) != NULL )
        {
            if ( !finalize_load_objects( &victim->first_carrying, &victim->last_carrying, (void*) victim, OBJ_IN_INVENTORY ) )
                bug( "%s: failed to finalize objects load for %s", FUNC, victim->name );
            finalize_load_followers( victim );
            ch_println( ch, "They're still alive." );
            free_char( victim );
            return;
        }

        if ( ( victim = load_player_sql( arg, PLAYER_DEAD ) ) == NULL )
        {
            ch_println( ch, "Could not find any dead characters with that name." );
            ch_println( ch, "HINT: This command requires that names be case-sensitive." );
            return;
        }

        for ( death = last_death; death; death = death->prev )
            if ( !str_cmp( arg, death->victim ))
                break;

        if ( death )
            for ( acc = first_account; acc; acc = acc->next )
                if ( !str_cmp( acc->name, death->victaccount ) )
                    break;

        if ( !finalize_load_objects( &victim->first_carrying, &victim->last_carrying, (void*) victim, OBJ_IN_INVENTORY ) )
            bug( "%s: failed to finalize objects load for %s", FUNC, victim->name );

        finalize_load_followers( victim );

        hashset_add( valid_chars, victim );
        victim->living = true;
        if ( acc )
            account_add_char( victim, acc, TRUE );

        save_player( victim, false );
        ch_println( ch, "Restored %s", victim->name );

        RESERVE_DATA* res = get_reserved( victim->name );
        if ( res ) remove_reserved( res );
        hashset_remove( valid_chars, victim );
        free_char( victim );
        add_mset( ch, buf2, get_trust( ch ), "Prestore" );

        if ( death && death->expiration > 0 )
        {
            lognormal( "Cancelling ownership revert for %s's death.\n", death->victim );
            death->expiration = 0;
            death_save(death);
        }

        for ( BOUNTY_DATA* bounty = first_bounty; bounty; bounty = bounty->next )
        {
            if ( bounty->expiration > 0 && !str_cmp( bounty->placer, arg ) )
            {
                bounty->expiration = 0;
                bounty_save(bounty);
            }
        }

        RACE_DATA *lookuprace = death ? get_race_by_id(death->victrace) : NULL;
        if ( death && acc && ( death->points > 0 || (lookuprace && lookuprace->deposit > 0 ) ))
        {
            char plogbuf[SUPER_MIL];
            snprintf( plogbuf, SUPER_MIL, "Backup Restore - %s", arg );

            if ( account_new_pointlog_sql( plogbuf, acc->name, ( death->points * -1 ) ) == NULL )
            {
                bug( "Error: null pointlog returned in %s at line %d of %s", FUNC, __LINE__, __FILE__ );
                return;
            }

            ch_println( ch, "&WTaking &G%d&W points from account &w%s&W for restoring &w%s.", death->points, acc->name, death->victim );
            snprintf( buf, MSL, "Taking %d points from account %s for restoring %s.", death->points, acc->name, death->victim );
            log_string( buf );
            acc->points -= death->points;        
            account_save( acc, true );
            RACE_DATA *accrace = get_race_by_id(death->victrace);
            accrace->race_count++;
            save_race( accrace );
        }

        return;
    }

    if ( !str_cmp( arg2, "list" ) )
    {
        list_player_backups( ch, arg );
        return;
    }

    if ( !str_cmp( arg2, "revert" ) )
    {
        if ( !player_exist( arg ) )
        {
            ch_println( ch, "&zThere isn't a living character named &C%s&z. You may need to resurrect them first.", arg );
            return;
        }

        if ( NULLSTR( arg3 ) || !is_number( arg3 ) )
        {
            ch_println( ch, "&zSyntax: &Cprestore %s revert <&wbackup #&C>", arg );
            return;
        }

        restore_player_backup( ch, arg, atoi( arg3 ) );
        return;
    }

    do_prestore( ch, "" );
    return;
}

CMDF do_restore( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Restore whom?" );
        return;
    }

    if ( !str_cmp( arg, "all" ) )
    {
        CHAR_DATA* vch;
        CHAR_DATA* vch_next;

        if ( !ch->pcdata )
            return;

        if ( get_trust( ch ) < 105 )
        {
            ch_println( ch, "Only admins can restore all now." );
            return;
        }

        if ( get_trust( ch ) < LEVEL_SUB_IMPLEM )
        {
            if ( IS_NPC( ch ) )
            {
                ch_println( ch, "You can't do that." );
                return;
            }
            else
            {
                /*
                    Check if the player did a restore all within the last 18 hours.
                */
                if ( current_time - last_restore_all_time < RESTORE_INTERVAL )
                {
                    ch_println( ch, "Sorry, you can't do a restore all yet." );
                    do_restoretime( ch, "" );
                    return;
                }
            }
        }

        last_restore_all_time = current_time;
        ch->pcdata->restore_time = current_time;
        save_char_obj( ch, true );

        if ( IS_IMMORTAL( ch ) )
            ch_println( ch, "Ok." );

        for ( vch = first_char; vch; vch = vch_next )
        {
            vch_next = vch->next;

            if ( !IS_NPC( vch ) && !IS_IMMORTAL( vch ) )
            {
                restore_ch( vch );
                act( AT_IMMORT, "$n has restored you.", ch, NULL, vch, TO_VICT );
            }
        }
    }
    else
    {
        CHAR_DATA* victim;

        if ( ( victim = get_char_world_full( ch, arg ) ) == NULL )
        {
            ch_println( ch, "They aren't here." );
            return;
        }

        if ( get_trust( ch ) < LEVEL_LESSER
                && victim != ch && !( IS_NPC( victim ) && xIS_SET( victim->act, ACT_PROTOTYPE ) ) )
        {
            ch_println( ch, "You can't do that." );
            return;
        }

        restore_ch( victim );

        if ( ch != victim )
            act( AT_IMMORT, "$n has restored you.", ch, NULL, victim, TO_VICT );

        if ( IS_IMMORTAL( ch ) )
            ch_println( ch, "Ok." );

        return;
    }
}

void restore_ch( CHAR_DATA* ch )
{
    ch->hit = ch->max_hit;

    if ( !has_pcflag( ch, PCFLAG_NO_SENSE ) )
        ch->mana = ch->max_mana;
    else
        ch->mana = 0;

    ch->move = ch->max_move;
    ch->mental_state = 0;
    ch->emotional_state = 0;

    for ( int x = 0; x <= MED_BACK; x++ )
        if ( xIS_SET( ch->w_wound, x ) )
            xREMOVE_BIT( ch->w_wound, x );

    if ( ch->pcdata )
    {
        if ( ch->pcdata->condition[COND_FULL] < 40 )
            ch->pcdata->condition[COND_FULL] = 40;

        if ( ch->pcdata->condition[COND_THIRST] < 40 )
            ch->pcdata->condition[COND_THIRST] = 40;

        ch->pcdata->condition[COND_BLOODTHIRST] = ( 10 + ch->top_level );
        ch->pcdata->blood_toxicity = 0;
    }

    update_pos( ch );
}

CMDF do_restoretime( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    long int time_passed;
    int hour, minute;

    if ( !last_restore_all_time )
        ch_println( ch, "There has been no restore all since reboot" );
    else
    {
        time_passed = current_time - last_restore_all_time;
        hour = ( int )( time_passed / 3600 );
        minute = ( int )( ( time_passed - ( hour * 3600 ) ) / 60 );
        ch_println( ch, "The  last restore all was %d hours and %d minutes ago.", hour, minute );
    }

    if ( !ch->pcdata )
        return;

    if ( !ch->pcdata->restore_time )
    {
        ch_println( ch, "You have never done a restore all." );
        return;
    }

    time_passed = current_time - ch->pcdata->restore_time;
    hour = ( int )( time_passed / 3600 );
    minute = ( int )( ( time_passed - ( hour * 3600 ) ) / 60 );
    ch_println( ch, "Your last restore all was %d hours and %d minutes ago.", hour, minute );
    return;
}

CMDF do_freeze( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], arg[MIL];
    CHAR_DATA* victim;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Freeze whom?" );
        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You failed." );
        return;
    }

    if ( victim->desc && victim->desc->original && get_trust( victim->desc->original ) >= get_trust( ch ) )
    {
        ch_println( ch, "For some inexplicable reason, you failed." );
        return;
    }

    if ( has_pcflag( victim, PCFLAG_FREEZE ) )
    {
        remove_pcflag( victim, PCFLAG_FREEZE );
        ch_println( victim, "Your frozen form suddenly thaws." );
        ch_println( ch, "%s is now unfrozen.", victim->name );
        snprintf( buf, MSL, "&RFREEZE removed from %s by %s\n", victim->name, ch->name );
    }
    else
    {
        if ( victim->switched )
        {
            do_return( victim->switched, "" );
            set_char_color( AT_LBLUE, victim );
        }

        set_pcflag( victim, PCFLAG_FREEZE );
        ch_println( victim, "A godly force turns your body to ice!" );
        ch_println( ch, "You have frozen %s.", victim->name );
        snprintf( buf, MSL, "&RFREEZE set on %s by %s\n", victim->name, ch->name );
    }

    lognormal( buf );
    save_char_obj( victim, true );
    return;
}



