void check_silenced( void )
{
    CHAR_DATA* fch;
    ACCOUNT_DATA* acc;

    for ( fch = first_char; fch; fch = fch->next )
    {
        if ( IS_NPC( fch ) )
            continue;

        if ( has_pcflag( fch, PCFLAG_SILENCE ) )
        {
            if ( fch->pcdata && fch->pcdata->silence_expires != 0 && current_time >= fch->pcdata->silence_expires )
            {
                lognormal( "&RSILENCE removed on char %s by their timer | Silenced by: %s | Original Reason: %s\n", fch->name, fch->pcdata->silenced_by, fch->pcdata->silence_reason );
                //     rpc( "%s has been unsilenced by their timer!", fch->name );
                ch_println( fch, "&RYour silence timer has expired. You are now able to use OOC channels again." );
                fch->pcdata->silence_expires = -1;
                SET_STRING( fch->pcdata->silenced_by, "" );
                SET_STRING( fch->pcdata->silence_reason, "" );
                remove_pcflag( fch, PCFLAG_SILENCE );
                do_save( fch, "-noalert" );
            }
        }
    }

    for ( acc = first_account; acc; acc = acc->next )
    {
        if ( !xIS_SET( acc->flags, ACC_NOOOC ) )
            continue;

        if ( acc->silence_expires != 0 && current_time >= acc->silence_expires )
        {
            lognormal( "&RSILENCE removed on @%s by their timer | Silenced by: %s | Original Reason: %s | Synced to Discord: %s\n", acc->name, acc->silenced_by, acc->silence_reason, ( acc->discordconfirmed == TRUE ) ? "TRUE" : "FALSE" );
            WOF(account_unsilence( acc ));
        }
    }

    return;
}

CMDF do_silence( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char buf[MSL];
    CHAR_DATA* victim;
    ACCOUNT_DATA* acc = NULL;
    int timeout;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || !is_number( arg2 ) || argument[0] == '\0' )
    {
        send_to_char( "&zSyntax: &Csilence <&wplayer name&z/&w@account name&C> <&wtimeout in minutes&C> <&wreason&C>&w\n&WIf you want to permanently silence an account, use 0 for the timer.", ch );
        return;
    }

    timeout = atoi( arg2 );

    if ( timeout < 0 || timeout > 525600 )
    {
        send_to_char( "&CMinimum is 1 minute, Maximum silence timeout is 1 year (525600). Use 0 for never expiring.", ch );
        return;
    }

    if ( arg1[0] == '@' )
    {
        strlcpy( buf, "", MSL );

        if ( ( acc = get_account( arg1 + 1 ) ) )
        {
            if ( acc->level > get_trust( ch ) )
            {
                ch_println( ch, "Nice try." );
                return;
            }

            if ( xIS_SET( acc->flags, ACC_NOOOC ) && acc->silence_expires >= 0 )
            {
                ch_println( ch, "&ROverwriting existing silence for that account, originally set by %s for reason '%s' and expiring in %s", acc->silenced_by, acc->silence_reason, ( acc->silence_expires == 0 ) ? "NEVER" : duration_string( acc->silence_expires - current_time ) );
            }

            if( WOF(account_silence( acc, timeout * 60, ch->name, argument )) == E_LOTJ_SUCCESS ) {
                snprintf( buf, MSL, "&RSILENCE set on @%s by %s | Reason: %s | Expires in: %s | Synced to Discord: %s\n", acc->name, ch->name, argument, ( acc->silence_expires == 0 ) ? "NEVER" : duration_string( acc->silence_expires - current_time ), ( acc->discordconfirmed == TRUE ) ? "TRUE" : "FALSE" );

                if ( get_trust( ch ) < 102 )
                {
                    do_council( ch, buf );
                }
                else
                {
                    lognormal( buf );
                }
            }
        }
        else
            snprintf( buf, MSL, "\n%s was not found.\n", arg1 );

        send_to_char( buf, ch );
        return;
    }

    if ( ( victim = get_player_world( arg1 ) ) == NULL ) //only leave in non-account silence for people who don't have accounts yet for some reason
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You failed." );
        return;
    }

    if ( has_pcflag( victim, PCFLAG_SILENCE ) )
        ch_println( ch, "Player already silenced, use unsilence to remove." );
    else
    {
        if ( has_pcflag( victim, PCFLAG_SILENCE ) && victim->pcdata->silence_expires >= 0 )
            ch_println( ch, "&ROverwriting existing silence for that char, originally set by %s for reason '%s' and expiring in %s", victim->pcdata->silenced_by, victim->pcdata->silence_reason, ( victim->pcdata->silence_expires == 0 ) ? "NEVER" : duration_string( victim->pcdata->silence_expires - current_time ) );

        set_pcflag( victim, PCFLAG_SILENCE );

        if ( timeout == 0 )
            victim->pcdata->silence_expires = 0;
        else
            victim->pcdata->silence_expires = ( timeout * 60 ) + current_time;

        SET_STRING( victim->pcdata->silenced_by, ch->name );
        SET_STRING( victim->pcdata->silence_reason, argument );
        ch_println( victim, "You can't use OOC channels!" );
        snprintf( buf, MSL, "&RSILENCE set on char %s by %s | Reason: %s | Expires in: %s\n", victim->name, ch->name, argument, ( victim->pcdata->silence_expires == 0 ) ? "NEVER" : duration_string( victim->pcdata->silence_expires - current_time ) );

        if ( get_trust( ch ) < 102 )
            do_council( ch, buf );
        else
            lognormal( buf );

        //   ch_println( ch, "SILENCE set. Reason: %s | Expires in: %s",argument,(victim->pcdata->silence_expires == 0) ? "NEVER" : duration_string( victim->pcdata->silence_expires - current_time ));
        // rpc( "%s has been silenced!", victim->name );
        acc = account_get_from_char( victim->name );

        if ( acc && acc->level <= get_trust( ch ) )
        {
            xSET_BIT( acc->flags, ACC_NOOOC );

            if ( timeout == 0 )
                acc->silence_expires = 0;
            else
                acc->silence_expires = ( timeout * 60 ) + current_time;

            SET_STRING( acc->silenced_by, ch->name );
            SET_STRING( acc->silence_reason, argument );

            if ( acc->discordconfirmed == TRUE )
            {
                discord_add_remove_timeout( acc->discorduuid, acc->silence_reason, timeout * 60 * 1000, false);
            }

            account_save( acc, true );
            account_broadcast( acc, "You can't use OOC channels!" );
            snprintf( buf, MSL, "&RSILENCE set on @%s by %s | Reason: %s | Expires in: %s | Synced to Discord: %s\n", acc->name, ch->name, argument, ( acc->silence_expires == 0 ) ? "NEVER" : duration_string( acc->silence_expires - current_time ), ( acc->discordconfirmed == TRUE ) ? "TRUE" : "FALSE" );

            if ( get_trust( ch ) < 102 )
            {
                do_council( ch, buf );
            }
            else
            {
                lognormal( buf );
            }
        }

        send_to_char( buf, ch );
    }

    return;
}

CMDF do_unsilence( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL];
    CHAR_DATA* victim;
    ACCOUNT_DATA* acc = NULL;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Unsilence whom?" );
        return;
    }

    if ( arg[0] == '@' )
    {
        strlcpy( buf, "", MSL );

        if ( ( acc = get_account( arg + 1 ) ) )
        {
            if ( acc->level > get_trust( ch ) )
            {
                ch_println( ch, "Nice try." );
                return;
            }

            if(WOF(account_unsilence(acc)) == E_LOTJ_SUCCESS) {
                snprintf( buf, MSL, "&RSILENCE removed on @%s by %s | Silencer: %s | Original Reason: %s | Original expiration in: %s | Synced to Discord: %s\n", acc->name, ch->name, acc->silenced_by, acc->silence_reason, ( acc->silence_expires == 0 ) ? "NEVER" : duration_string( acc->silence_expires - current_time ), ( acc->discordconfirmed == TRUE ) ? "TRUE" : "FALSE" );
                if ( get_trust( ch ) < 102 )
                {
                    rpc( buf );
                }
                else
                {
                    lognormal( buf );
                }
            }
        }
        else
            snprintf( buf, MSL, "\n%s was not found.\n", arg );

        send_to_char( buf, ch );
        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "You failed." );
        return;
    }

    if ( has_pcflag( victim, PCFLAG_SILENCE ) )
    {
        snprintf( buf, MSL, "&RSILENCE removed on char %s by %s | Silencer: %s | Original Reason: %s | Originally expired in: %s\n", victim->name, ch->name, victim->pcdata->silenced_by, victim->pcdata->silence_reason, ( victim->pcdata->silence_expires == 0 ) ? "NEVER" : duration_string( victim->pcdata->silence_expires - current_time ) );

        if ( get_trust( ch ) < 102 )
        {
            rpc( buf );
        }
        else
        {
            lognormal( buf );
        }

        remove_pcflag( victim, PCFLAG_SILENCE );
        victim->pcdata->silence_expires = -1;
        SET_STRING( victim->pcdata->silenced_by, "" );
        SET_STRING( victim->pcdata->silence_reason, "" );
        ch_println( victim, "You can use OOC channels again." );
        //  ch_println( ch, "SILENCE removed." );
        // rpc( "%s has been unsilenced!", victim->name );
        acc = account_get_from_char( victim->name );
        do_save( victim, "-noalert" );

        if ( acc && acc->level <= get_trust( ch ) )
        {
            xSET_BIT( acc->flags, ACC_NOOOC );
            acc->silence_expires = -1;
            SET_STRING( acc->silenced_by, "" );
            SET_STRING( acc->silence_reason, "" );

            if ( acc->discordconfirmed == TRUE )
            {
                discord_add_remove_timeout(acc->discorduuid, NULL, 0, true);
            }

            account_save( acc, true );
        }
    }
    else
    {
        ch_println( ch, "That player is not silenced." );
    }

    return;
}

CMDF do_peace( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* rch;
    act( AT_IMMORT, "$n booms, 'PEACE!'", ch, NULL, NULL, TO_ROOM );

    for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( rch->fighting )
        {
            stop_fighting( rch, TRUE );
            do_sit( rch, "" );
        }

        /*
            Added by Narn, Nov 28/95
        */
        stop_hating( rch );
        stop_hunting( rch );
        stop_fearing( rch );
    }

    ch_println( ch, "Ok." );
    return;
}

BAN_DATA* first_ban;
BAN_DATA* last_ban;

bool save_ban( BAN_DATA* ban )
{
    if ( !ban )
        return false;

    return upsert_sql_fieldmap_row( DB_TABLE_BANS, ban, ban_fields, NO_FLAG );
}

void remove_ban_sql( BAN_DATA* ban )
{
    delete_sql_row_by_id( DB_TABLE_BANS, ban->id );
}

int load_ban_sql( const PGresult* res, int row )
{
    BAN_DATA* pban = NULL;
    CREATE( pban, BAN_DATA, 1 );
    int rval;
    if ( ( rval = fieldmap_postgres_row(res, row, pban, ban_fields) ) != E_LOTJ_SUCCESS ) {
        FREE_STRUCT( pban, ban_fields );
        return rval;
    }

    LINK( pban, first_ban, last_ban, next, prev );

    return E_LOTJ_SUCCESS;
}

CMDF do_ban( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg[MIL];

    if ( IS_NPC( ch ) )
        return;

    argument = one_argument( argument, arg );
    set_pager_color( AT_PLAIN, ch );

    if ( NULLSTR( arg ) )
    {
        send_to_pager( "&zBanned sites:&w\n", ch );
        send_to_pager( "&z[ &C#&z] &C(&wLv&C) Time                     Site\n", ch );
        send_to_pager( "&z---- ---- ------------------------ ---------------&w\n", ch );

        for ( BAN_DATA* pban = first_ban; pban; pban = pban->next )
            pager_printf( ch, "&z[&C%3d&z] &C(&w%2d&C)&w %-24s %s\n", pban->id, pban->level, pban->ban_time, pban->name );

        return;
    }

    /*
        People are gonna need .# instead of just # to ban by just last
        number in the site ip.                               -- Altrag
    */
    if ( is_number( arg ) )
    {
        BAN_DATA* pban;
        for ( pban = first_ban; pban; pban = pban->next )
            if ( pban->id == atoi( arg ) )
                break;

        if ( !pban )
        {
            do_ban( ch, "" );
            return;
        }

        argument = one_argument( argument, arg );

        if ( NULLSTR( arg ) )
        {
            do_ban( ch, "help" );
            return;
        }

        if ( !str_cmp( arg, "level" ) )
        {
            argument = one_argument( argument, arg );

            if ( arg[0] == '\0' || !is_number( arg ) )
            {
                do_ban( ch, "help" );
                return;
            }

            if ( atoi( arg ) < 1 || atoi( arg ) > LEVEL_SUPREME )
            {
                ch_println( ch, "Level range: 1 - %d.", LEVEL_SUPREME );
                return;
            }

            pban->level = atoi( arg );
            ch_println( ch, "Ban level set." );
        }
        else if ( !str_cmp( arg, "newban" ) )
        {
            pban->level = 1;
            ch_println( ch, "New characters banned." );
        }
        else if ( !str_cmp( arg, "mortal" ) )
        {
            pban->level = LEVEL_AVATAR;
            ch_println( ch, "All mortals banned." );
        }
        else if ( !str_cmp( arg, "total" ) )
        {
            pban->level = LEVEL_SUPREME;
            ch_println( ch, "Everyone banned." );
        }
        else if ( !str_cmp( arg, "imm" ) )
        {
            pban->level = -1;
            ch_println( ch, "Immortals banned." );
        }
        else
        {
            do_ban( ch, "help" );
            return;
        }

        save_ban( pban );
        return;
    }

    if ( !str_cmp( arg, "help" ) )
    {
        ch_println( ch, "&zSyntax: &Cban <&wsite address&C>&w" );
        ch_println( ch, "&zSyntax: &Cban <&wban number&C> <&wlevel &C(&wlevel #&C)&C|&wnewban&C|&wmortal&C|&wtotal&C|&wimm&C>&w" );
        return;
    }

    for ( BAN_DATA* pban = first_ban; pban; pban = pban->next )
    {
        if ( !str_cmp( arg, pban->name ) )
        {
            ch_println( ch, "That site is already banned!" );
            return;
        }
    }

    BAN_DATA* pban;
    CREATE( pban, BAN_DATA, 1 );
    LINK( pban, first_ban, last_ban, next, prev );
    SET_STRING( pban->name, arg );
    pban->level = LEVEL_AVATAR;
    snprintf( buf, MSL, "%24.24s", ctime( &current_time ) );
    SET_STRING( pban->ban_time, buf );
    save_ban( pban );
    ch_println( ch, "Ban created.  Mortals banned from site." );
    return;
}

CMDF do_allow( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&GRemove which site from the ban list?&w\n&zSyntax: &Callow <&wip, dns, or &W#&C[&wnumber&C]&w (ie #2)&C>&w" );
        return;
    }

    for ( BAN_DATA* pban = first_ban; pban; pban = pban->next )
    {
        if ( !str_cmp( arg, pban->name ) || atoi( arg + 1 ) == pban->id )
        {
            if ( delete_sql_row_by_id( DB_TABLE_BANS, pban->id ) != E_LOTJ_SUCCESS )
                return;

            UNLINK( pban, first_ban, last_ban, next, prev );
            FREE_STRUCT_NORET( pban, ban_fields );
            ch_println( ch, "Site no longer banned." );
            return;
        }
    }

    ch_println( ch, "Site is not banned." );
    return;
}

CMDF do_wizlock( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    extern bool wizlock;
    DESCRIPTOR_DATA* d = NULL;
    wizlock = !wizlock;
    sysdata.SWIZLOCK = wizlock;
    save_sysdata( &sysdata );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( !IS_IMMORTAL( d->character ) && !IS_RPC( d->character ) )
            continue;

        if ( wizlock )
            ch_println( d->character, "&RThe game has been wizlocked by %s.", ch->name );
        else
            ch_println( d->character, "&GThe game has been un-wizlocked by %s.", ch->name );
    }

    return;
}


CMDF do_noresolve( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    sysdata.NO_NAME_RESOLVING = !sysdata.NO_NAME_RESOLVING;

    if ( sysdata.NO_NAME_RESOLVING )
        ch_println( ch, "Name resolving disabled." );
    else
        ch_println( ch, "Name resolving enabled." );

    return;
}

char* center_str( char* argument, int columns )
{
    static char centered[MIL];
    int spaces;
    columns = ( columns < 2 ) ? 80 : columns;
    spaces = ( columns - strlen( argument ) ) / 2;
    snprintf( centered, MSL, "%*c%s%*c", spaces, ' ', argument, spaces, ' ' );
    return centered;
}

CMDF do_users( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    DESCRIPTOR_DATA* d;
    int count;
    char arg[MIL];
    set_pager_color( AT_PLAIN, ch );
    one_argument( argument, arg );
    count = 0;
    buf[0] = '\0';
    snprintf( buf, MSL, "\n&z&Y&WDesc&z| &WCon Stat &z|&WIdle&z| &WPlayer      &wHost&CIP           " );
    strlcat( buf, "\n", MSL );
    strlcat( buf, "&z----&Y+&z----------&Y+&z----&Y+&z-------------------------------", MSL );
    strlcat( buf, "\n&z", MSL );
    send_to_pager( buf, ch );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d == NULL )
            continue;

        if ( d->descriptor < 0 || d->descriptor > 10000 )
        {
            tune( "do_users called with a DESCRIPTOR_DATA->descriptor  of < 0 or > 10000!" );
            continue;
        }

        if ( ( d->connected < 0 || d->connected > CON_MAX ) )
            continue;

        // lets validate the descriptor_data before moving forward
        if ( d->character == NULL )
        {
            tune( "do_users called with a NULL d->character!" );
            continue;
        }

        if ( d->original == NULL )
        {
            tune( "do_users called with a NULL d->original (keep an eye if I cause a crash!" );
        }

        if ( d->host == NULL )
        {
            tune( "do_users called with a NULL HOST!" );
            continue;
        }

        // put this at the top, happens if there is an arg or not ~Miros
        if ( d->character != NULL )
            if ( !str_cmp( d->character->name, "Anna" ) || !str_cmp( d->character->name, "Rojan" ) )
                if ( get_trust( ch ) < 200 )
                    continue;

        if ( NULLSTR( arg ) )
        {
            if ( get_trust( ch ) >= 103 || ( d->character != NULL && can_see( ch, d->character ) ) )
            {
                count++;
                /*  if( d->character && d->character != NULL )
                    if( d->character->pcdata->fakeip && d->character->pcdata->fakeip[0] != '\0' )
                        fakeip = TRUE;*/
                snprintf( buf, MSL,
                         " %3d|%9.9s|%4d| %-12s %-16s %s%s",
                         d->descriptor,
                         center_str( connection_state[d->connected], 9 ),
                         d->idle / 4,
                         d->original ? d->original->name : d->character ? d->character->name : "(none)",
                         get_char_ip( ch, d ),
                         //  fakeip ? d->character->pcdata->fakeip : d->host,
                         d->connected != CON_PLAYING && d->connected != CON_EDITING ? "&z(&CC&z)" : "",
                         d->connected == CON_EDITING ? "&z(&YE&z)" : "" );
                strlcat( buf, "\n", MSL );
                send_to_pager( buf, ch );
            }
        }
        else
        {
            if ( ( get_trust( ch ) >= LEVEL_SUPREME
                    || ( d->character && can_see( ch, d->character ) ) )
                    && ( !str_prefix( arg, d->host ) || ( d->character && !str_prefix( arg, d->character->name ) ) ) )
            {
                count++;
                pager_printf( ch,
                              " %3d|%9.9s|%4d| %-12s %-16s ",
                              d->descriptor,
                              center_str( connection_state[d->connected], 9 ),
                              d->idle / 4,
                              d->original ? d->original->name : d->character ? d->character->name : "(none)", d->host );
                buf[0] = '\0';
                strlcat( buf, "\n", MSL );
                send_to_pager( buf, ch );
            }
        }
    }

    pager_printf( ch, "%d user%s.\n", count, count == 1 ? "" : "s" );
    return;
}

/*
    Thanks to Grodyn for pointing out bugs in this function.
*/
CMDF do_force( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    bool mobsonly;
    set_char_color( AT_IMMORT, ch );
    argument = one_argument( argument, arg );

    if ( arg[0] == '\0' || argument[0] == '\0' )
    {
        ch_println( ch, "Force whom to do what?" );
        return;
    }

    mobsonly = get_trust( ch ) < sysdata.level_forcepc;

    if ( !str_cmp( arg, "all" ) )
    {
        CHAR_DATA* vch;
        CHAR_DATA* vch_next;

        if ( mobsonly )
        {
            ch_println( ch, "Force whom to do what?" );
            return;
        }

        for ( vch = first_char; vch; vch = vch_next )
        {
            vch_next = vch->next;

            if ( !IS_NPC( vch ) && get_trust( vch ) < get_trust( ch ) )
            {
                xSET_BIT( vch->act, ACT_FORCED );
                if ( get_trust( ch ) < 105 )
                    act( AT_IMMORT, "$n forces you to '$t'.", ch, argument, vch, TO_VICT );

                interpret( vch, argument, FALSE );
                if (vch->desc)
                    vch->desc->idle = 0;

                xREMOVE_BIT( vch->act, ACT_FORCED );
            }
        }
    }
    else
    {
        CHAR_DATA* victim;

        if ( ( victim = get_char_world_full( ch, arg ) ) == NULL )
        {
            ch_println( ch, "They aren't here." );
            return;
        }

        if ( victim == ch )
        {
            ch_println( ch, "Aye aye, right away!" );
            return;
        }

        if ( ( get_trust( victim ) >= get_trust( ch ) ) || ( mobsonly && !IS_NPC( victim ) ) )
        {
            ch_println( ch, "Do it yourself!" );
            return;
        }

        if ( get_trust( ch ) < 105 )
            act( AT_IMMORT, "$n forces you to '$t'.", ch, argument, victim, TO_VICT );

        xSET_BIT( victim->act, ACT_FORCED );
        interpret( victim, argument, FALSE );
        if (victim->desc)
            victim->desc->idle = 0;
        xREMOVE_BIT( victim->act, ACT_FORCED );
    }

    ch_println( ch, "Ok." );
    return;
}


CMDF do_invis( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    sh_int level;
    /*
        if ( IS_NPC(ch))
        return;
    */
    argument = one_argument( argument, arg );

    //The compiler is right, "arg" will always resolve to true ~~Miros
    if ( !NULLSTR( arg ) )
    {
        if ( !is_number( arg ) )
        {
            ch_println( ch, "Usage: invis | invis <level>" );
            return;
        }

        level = atoi( arg );

        if ( level < 2 || level > get_trust( ch ) )
        {
            ch_println( ch, "Invalid level." );
            return;
        }

        if ( !IS_NPC( ch ) )
        {
            ch->pcdata->wizinvis = level;
            ch_println( ch, "Wizinvis level set to %d.", level );
        }

        if ( IS_NPC( ch ) )
        {
            ch->mobinvis = level;
            ch_println( ch, "Mobinvis level set to %d.", level );
        }

        return;
    }

    if ( IS_NPC( ch ) )
    {
        if ( ch->mobinvis < 2 )
            ch->mobinvis = ch->top_level;

        return;
    }

    if ( ch->pcdata->wizinvis < 2 )
        ch->pcdata->wizinvis = ch->top_level;

    if ( has_pcflag( ch, PCFLAG_WIZINVIS ) )
    {
        remove_pcflag( ch, PCFLAG_WIZINVIS );
        act( AT_IMMORT, "$n slowly fades into existence.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You slowly fade back into existence." );
    }
    else
    {
        set_pcflag( ch, PCFLAG_WIZINVIS );
        act( AT_IMMORT, "$n slowly fades into thin air.", ch, NULL, NULL, TO_ROOM );
        ch_println( ch, "You slowly vanish into thin air." );
    }

    return;
}


CMDF do_holylight( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    if ( IS_NPC( ch ) )
        return;

    if ( has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
    {
        remove_pcflag( ch, PCFLAG_HOLYLIGHT );
