/*
    Load up a player file
*/
CMDF do_loadup( CHAR_DATA* ch, char* argument )
{
    char name[256];
    char buf[MSL];
    CHAR_DATA* loaded_ch;
    int old_room_vnum;

    one_argument( argument, name );

    if ( NULLSTR( name ) )
    {
        ch_println( ch, "&zSyntax: &Cloadup <&wplayer&C>&w" );
        return;
    }

    // Use unified loadup function with fake descriptor
    loaded_ch = unified_loadup( name, NULL, NULL, ch->in_room );

    if ( !loaded_ch )
    {
        ch_println( ch, "No such player." );
        return;
    }

    // Check trust level (different logic for wizard loadup)
    if ( get_trust( loaded_ch ) >= get_trust( ch ) )
    {
        do_say( loaded_ch, "Do *NOT* disturb me again!" );
        ch_println( ch, "I think you'd better leave that player alone!" );

        // Clean up the loaded character
        destroy_fake_descriptor( loaded_ch->desc );
        loaded_ch->desc = NULL;
        do_quit( loaded_ch, "" );
        return;
    }

    old_room_vnum = loaded_ch->retran;
    ch_println( ch, "Player %s loaded from room %d.", capitalize( name ), old_room_vnum );
    snprintf( buf, MSL, "%s appears from nowhere, eyes glazed over.\n", capitalize( name ) );
    act( AT_IMMORT, buf, ch, NULL, NULL, TO_ROOM );
    ch_println( ch, "Done." );
}

