/*
    Extract area names from "input" string and place result in "output" string
    e.g. "aset joe.are sedit susan.are cset" --> "joe.are susan.are"
    - Gorog
*/
void extract_area_names( char* inp, char* out )
{
    char buf[MIL], *pbuf = buf;
    int len;
    *out = '\0';

    while ( inp && *inp )
    {
        inp = one_argument( inp, buf );

        if ( ( len = strlen( buf ) ) >= 5 && !strcmp( ".are", pbuf + len - 4 ) )
        {
            if ( *out )
                strlcat( out, " ", MSL );

            strlcat( out, buf, MSL );
        }
    }
}

/*
    Remove area names from "input" string and place result in "output" string
    e.g. "aset joe.are sedit susan.are cset" --> "aset sedit cset"
    - Gorog
*/
void remove_area_names( char* inp, char* out )
{
    char buf[MIL], *pbuf = buf;
    int len;
    *out = '\0';

    while ( inp && *inp )
    {
        inp = one_argument( inp, buf );

        if ( ( len = strlen( buf ) ) < 5 || strcmp( ".are", pbuf + len - 4 ) )
        {
            if ( *out )
                strlcat( out, " ", MSL );

            strlcat( out, buf, MSL );
        }
    }
}

CMDF do_bestowarea( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL];
    char buf2[MSL];
    CHAR_DATA* victim;
    int arg_len;
    snprintf( buf2, MSL, "%s", argument );
    argument = one_argument( argument, arg );

    if ( get_trust( ch ) < LEVEL_SUB_IMPLEM )
    {
        ch_println( ch, "Sorry..." );
        return;
    }

    if ( !*arg )
    {
        send_to_char( "&zSyntax: &Cbestowarea <&wvictim&C> <&wfilename&C>.are&w\n"
                      "&zSyntax: &Cbestowarea <&wvictim&C> none            &wremoves bestowed areas\n"
                      "&zSyntax: &Cbestowarea <&wvictim&C> list            &wlists bestowed areas\n"
                      "&zSyntax: &Cbestowarea <&wvictim&C>                 &wlists bestowed areas\n", ch );
        return;
    }

    if ( !( victim = get_player_world( arg ) ) )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( get_trust( victim ) < LEVEL_IMMORTAL )
    {
        ch_println( ch, "They aren't an immortal." );
        return;
    }

    if ( !victim->pcdata->bestowments )
        SET_STRING( victim->pcdata->bestowments, "" );

    if ( !*argument || !str_cmp( argument, "list" ) )
    {
        extract_area_names( victim->pcdata->bestowments, buf );
        ch_println( ch, "Bestowed areas: %s", buf );
        return;
    }

    if ( !str_cmp( argument, "none" ) )
    {
        remove_area_names( victim->pcdata->bestowments, buf );
        SET_STRING( victim->pcdata->bestowments, buf );
        ch_println( ch, "Done." );
        return;
    }

    arg_len = strlen( argument );

    if ( arg_len < 3 )
    {
        ch_println( ch, "You can only bestow an area name" );
        ch_println( ch, "E.G. bestow joe sam.are" );
        return;
    }

    snprintf( buf, MSL, "%s %s", victim->pcdata->bestowments, argument );
    SET_STRING( victim->pcdata->bestowments, buf );
    ch_println( victim, "%s has bestowed on you the area: %s", ch->name, argument );
    add_mset( ch, buf2, get_trust( ch ), "Bestowarea" );
    ch_println( ch, "Done." );
}

CMDF do_bestow( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL], buf2[MSL];
    CHAR_DATA* victim;
    snprintf( buf2, MSL, "%s", argument );
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Bestow whom with what?" );
        return;
    }

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ( !str_cmp( arg, "self" ) || !str_cmp( ch->name, arg ) ) && get_trust( ch ) < LEVEL_ADMIN )
    {
        ch_println( ch, "You can't bestow yourself!" );
        return;
    }

    if ( get_trust( victim ) > get_trust( ch ) )
    {
        ch_println( ch, "You aren't powerful enough..." );
        return;
    }

    if ( !victim->pcdata->bestowments )
        SET_STRING( victim->pcdata->bestowments, "" );

    if ( is_name( argument, victim->pcdata->bestowments ) )
    {
        strlcpy( buf, remove_substr_from_str( victim->pcdata->bestowments, argument ), MSL );
        SET_STRING( victim->pcdata->bestowments, buf );
        ch_println( ch, "&zRemoving bestowed command: &C%s&z.", argument );
        return;
    }

    if ( argument[0] == '\0' || !str_cmp( argument, "list" ) )
    {
        ch_println( ch, "&zCurrent bestowed commands on &C%s&z: &C%s&z.", victim->name, victim->pcdata->bestowments );
        return;
    }

    if ( !str_cmp( argument, "values" ) && get_trust( ch ) < LEVEL_ADMIN )
    {
        ch_println( ch, "You are not a high enough level." );
        return;
    }

    if ( !str_cmp( argument, "none" ) )
    {
        SET_STRING( victim->pcdata->bestowments, "" );
        ch_println( ch, "&zBestowments removed from &C%s&z.", victim->name );
        ch_println( victim, "&C%s&z has removed your bestowed commands.", ch->name );
        check_switch( victim, FALSE );
        return;
    }

    if ( NULLSTR( victim->pcdata->bestowments ) )
        snprintf( buf, MSL, "%s", argument );
    else
        snprintf( buf, MSL, "%s %s", victim->pcdata->bestowments, argument );

    SET_STRING( victim->pcdata->bestowments, buf );
    ch_println( victim, "%s has bestowed on you the command(s): %s", ch->name, argument );
    add_mset( ch, buf2, get_trust( ch ), "Bestow" );
    ch_println( ch, "Done." );
}

struct tm* update_time( struct tm* old_time )
{
    time_t time;
    time = mktime( old_time );
    return localtime( &time );
}

CMDF do_set_boot_time( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char arg1[MIL];
    bool check;
    check = FALSE;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Csetboot time {hour minute <&wday&C> <&wmonth&C> <&wyear&C>}" );
        ch_println( ch, "&w        &Csetboot manual {0/1}" );
        ch_println( ch, "&w        &Csetboot default" );
        ch_println( ch, "&zBoot time is currently set to &C%s&z, manual bit is set to &w%d", reboot_time, set_boot_time->manual );
        return;
    }

    if ( !str_cmp( arg, "time" ) )
    {
        struct tm* now_time;
        argument = one_argument( argument, arg );
        argument = one_argument( argument, arg1 );

        if ( !*arg || !*arg1 || !is_number( arg ) || !is_number( arg1 ) )
        {
            ch_println( ch, "You must input a value for hour and minute." );
            return;
        }

        now_time = localtime( &current_time );

        if ( ( now_time->tm_hour = atoi( arg ) ) < 0 || now_time->tm_hour > 23 )
        {
            ch_println( ch, "Valid range for hour is 0 to 23." );
            return;
        }

        if ( ( now_time->tm_min = atoi( arg1 ) ) < 0 || now_time->tm_min > 59 )
        {
            ch_println( ch, "Valid range for minute is 0 to 59." );
            return;
        }

        argument = one_argument( argument, arg );

        if ( *arg != '\0' && is_number( arg ) )
        {
            if ( ( now_time->tm_mday = atoi( arg ) ) < 1 || now_time->tm_mday > 31 )
            {
                ch_println( ch, "Valid range for day is 1 to 31." );
                return;
            }

            argument = one_argument( argument, arg );

            if ( *arg != '\0' && is_number( arg ) )
            {
                if ( ( now_time->tm_mon = atoi( arg ) ) < 1 || now_time->tm_mon > 12 )
                {
                    ch_println( ch, "Valid range for month is 1 to 12." );
                    return;
                }

                now_time->tm_mon--;
                argument = one_argument( argument, arg );

                if ( ( now_time->tm_year = atoi( arg ) - 1900 ) < 0 || now_time->tm_year > 199 )
                {
                    ch_println( ch, "Valid range for year is 1900 to 2099." );
                    return;
                }
            }
        }

        now_time->tm_sec = 0;

        if ( mktime( now_time ) < current_time )
        {
            ch_println( ch, "You can't set a time previous to today!" );
            return;
        }

        if ( set_boot_time->manual == 0 )
            set_boot_time->manual = 1;

        new_boot_time = update_time( now_time );
        new_boot_struct = *new_boot_time;
        new_boot_time = &new_boot_struct;
        reboot_check( mktime( new_boot_time ) );
        get_reboot_string(  );
        ch_println( ch, "Boot time set to %s", reboot_time );
        check = TRUE;
    }
    else if ( !str_cmp( arg, "manual" ) )
    {
        argument = one_argument( argument, arg1 );

        if ( NULLSTR( arg1 ) )
        {
            ch_println( ch, "Please enter a value for manual boot on/off" );
            return;
        }

        if ( !is_number( arg1 ) )
        {
            ch_println( ch, "Value for manual must be 0 (off) or 1 (on)" );
            return;
        }

        if ( atoi( arg1 ) < 0 || atoi( arg1 ) > 1 )
        {
            ch_println( ch, "Value for manual must be 0 (off) or 1 (on)" );
            return;
        }

        set_boot_time->manual = atoi( arg1 );
        ch_println( ch, "Manual bit set to %s", arg1 );
        check = TRUE;
        get_reboot_string(  );
        return;
    }
    else if ( !str_cmp( arg, "default" ) )
    {
        set_boot_time->manual = 0;
        /*
            Reinitialize new_boot_time
        */
        new_boot_time = localtime( &current_time );
        new_boot_time->tm_mday += 1;

        if ( new_boot_time->tm_hour > 12 )
            new_boot_time->tm_mday += 1;

        new_boot_time->tm_hour = 6;
        new_boot_time->tm_min = 0;
        new_boot_time->tm_sec = 0;
        new_boot_time = update_time( new_boot_time );
        sysdata.DENY_NEW_PLAYERS = FALSE;
        ch_println( ch, "Reboot time set back to normal." );
        check = TRUE;
    }

    if ( !check )
    {
        ch_println( ch, "Invalid argument for setboot." );
        return;
    }
    else
    {
        get_reboot_string(  );
        new_boot_time_t = mktime( new_boot_time );
    }
}

/*  Super-AT command:

    FOR ALL <action>
    FOR MORTALS <action>
    FOR GODS <action>
    FOR MOBS <action>
    FOR EVERYWHERE <action>


    Executes action several times, either on ALL players (not including yourself),
    MORTALS (including trusted characters), GODS (characters with level higher than
    L_HERO), MOBS (Not recommended) or every room (not recommended either!)

    If you insert a # in the action, it will be replaced by the name of the target.

    If # is a part of the action, the action will be executed for every target
    in game. If there is no #, the action will be executed for every room containing
    at least one target, but only once per room. # cannot be used with FOR EVERY-
    WHERE. # can be anywhere in the action.

    Example:

    FOR ALL SMILE -> you will only smile once in a room with 2 players.
    FOR ALL TWIDDLE # -> In a room with A and B, you will twiddle A then B.

    Destroying the characters this command acts upon MAY cause it to fail. Try to
    avoid something like FOR MOBS PURGE (although it actually works at my MUD).

    FOR MOBS TRANS 3054 (transfer ALL the mobs to Midgaard temple) does NOT work
    though :)

    The command works by transporting the character to each of the rooms with
    target in them. Private rooms are not violated.

*/

/*  Expand the name of a character into a string that identifies THAT
    character within a room. E.g. the second 'guard' -> 2. guard
*/
const char* name_expand( CHAR_DATA* ch )
{
    int count = 1;
    CHAR_DATA* rch;
    char name[MIL];    /*  HOPEFULLY no mob has a name longer than THAT */
    static char outbuf[SUPER_MIL];
    strlcpy( outbuf, "", SUPER_MIL );

    if ( !IS_NPC( ch ) )
        return ch->name;

    one_argument( ch->name, name ); /* copy the first word into name */

    if ( !name[0] ) /* weird mob .. no keywords */
        return outbuf;

    /*
        ->people changed to ->first_person -- TRI
    */
    for ( rch = ch->in_room->first_person; rch && ( rch != ch ); rch = rch->next_in_room )
        if ( is_name( name, rch->name ) )
            count++;

    snprintf( outbuf, SUPER_MIL, "%d.%s", count, name );
    return outbuf;
}


CMDF do_for( CHAR_DATA* ch, char* argument )
{
    char range[MIL];
    char buf[MSL];
    bool fGods = FALSE, fMortals = FALSE, fMobs = FALSE, fEverywhere = FALSE, found;
    ROOM_INDEX_DATA* room, *old_room;
    CHAR_DATA* p, *p_prev;  /* p_next to p_prev -- TRI */
    argument = one_argument( argument, range );

    if ( !range[0] || !argument[0] ) /* invalid usage? */
    {
        do_help( ch, "for" );
        return;
    }

    if ( !str_prefix( "quit", argument ) )
    {
        ch_println( ch, "Are you trying to crash the MUD or something?" );
        return;
    }

    if ( !str_cmp( range, "all" ) )
    {
        fMortals = TRUE;
        fGods = TRUE;
    }
    else if ( !str_cmp( range, "gods" ) )
        fGods = TRUE;
    else if ( !str_cmp( range, "mortals" ) )
        fMortals = TRUE;
    else if ( !str_cmp( range, "mobs" ) )
        fMobs = TRUE;
    else if ( !str_cmp( range, "everywhere" ) )
        fEverywhere = TRUE;
    else
        do_help( ch, "for" );   /* show syntax */

    /*
        do not allow # to make it easier
    */
    if ( fEverywhere && strchr( argument, '#' ) )
    {
        ch_println( ch, "Cannot use FOR EVERYWHERE with the # thingie." );
        return;
    }

    if ( strchr( argument, '#' ) )  /* replace # ? */
    {
        /*
            char_list - last_char, p_next - gch_prev -- TRI
        */
        for ( p = last_char; p; p = p_prev )
        {
            p_prev = p->prev;   /* TRI */
            /*
                p_next = p->next;
            *//*
    In case someone DOES try to AT MOBS SLAY #
*/
            found = FALSE;

            if ( get_trust( p ) >= 105 && get_trust( ch ) < 105 )
                continue;

            if ( get_trust( p ) == 200 && get_trust( ch ) < 200 )
                continue;

            if ( !( p->in_room ) || room_is_private( p, p->in_room ) || ( p == ch ) )
                continue;

            if ( IS_NPC( p ) && fMobs )
                found = TRUE;
            else if ( !IS_NPC( p ) && get_trust( p ) >= LEVEL_IMMORTAL && fGods )
                found = TRUE;
            else if ( !IS_NPC( p ) && get_trust( p ) < LEVEL_IMMORTAL && fMortals )
                found = TRUE;

            /*
                It looks ugly to me.. but it works :)
            */
            if ( found ) /* p is 'appropriate' */
            {
                char* pSource = argument;   /* head of buffer to be parsed */
                char* pDest = buf;  /* parse into this */

                while ( *pSource )
                {
                    if ( *pSource == '#' )  /* Replace # with name of target */
                    {
                        const char* namebuf = name_expand( p );

                        if ( namebuf )  /* in case there is no mob name ?? */
                            while ( *namebuf )  /* copy name over */
                                *( pDest++ ) = *( namebuf++ );

                        pSource++;
                    }
                    else
                        *( pDest++ ) = *( pSource++ );
                }   /* while */

                *pDest = '\0';  /* Terminate */
                /*
                    Execute
                */
                old_room = ch->in_room;
                char_from_room( ch );
                char_to_room( ch, p->in_room );
                interpret( ch, buf, FALSE );
                char_from_room( ch );
                char_to_room( ch, old_room );
            }   /* if found */
        }   /* for every char */
    }
    else    /* just for every room with the appropriate people in it */
    {
        for ( room = first_room; room; room = room->next )
        {
            found = FALSE;

            /*
                Anyone in here at all?
            */
            if ( fEverywhere )  /* Everywhere executes always */
                found = TRUE;
            else if ( !room->first_person ) /* Skip it if room is empty */
                continue;

            /*
                ->people changed to first_person -- TRI
            */

            /*
                Check if there is anyone here of the required type
            */
            /*
                Stop as soon as a match is found or there are no more ppl in room
            */
            /*
                ->people to ->first_person -- TRI
            */
            for ( p = room->first_person; p && !found; p = p->next_in_room )
            {
                if ( p == ch )  /* do not execute on oneself */
                    continue;

                if ( IS_NPC( p ) && fMobs )
                    found = TRUE;
                else if ( !IS_NPC( p ) && ( get_trust( p ) >= LEVEL_IMMORTAL ) && fGods )
                    found = TRUE;
                else if ( !IS_NPC( p ) && ( get_trust( p ) <= LEVEL_IMMORTAL ) && fMortals )
                    found = TRUE;
            }   /* for everyone inside the room */

            if ( found && !room_is_private( p, room ) ) /* Any of the required type here AND room not private? */
            {
                /*
                    This may be ineffective. Consider moving character out of old_room
                    once at beginning of command then moving back at the end.
                    This however, is more safe?
                */
                old_room = ch->in_room;
                char_from_room( ch );
                char_to_room( ch, room );
                interpret( ch, argument, FALSE );
                char_from_room( ch );
                char_to_room( ch, old_room );
            }   /* if found */
        }
    }   /* if strchr */
}   /* do_for */

