        return;
    }

    if ( !str_cmp( arg, "ai_sudoers" ) )
    {
        char* current_config = NULL;

        if ( is_busy( ch ) )
        {
            ch_println( ch, "You are too busy to do that right now." );
            return;
        }

        // Get configuration from database only
        dbc_get_string(DBC_SETTING_AI_SUDOERS, &current_config, DBC_SETTING_AI_SUDOERS_DEFAULT);

        if ( ch->substate == SUB_REPEATCMD )
            ch->tempnum = SUB_REPEATCMD;
        else
            ch->tempnum = SUB_NONE;

        ch->substate = SUB_AI_SUDOERS_EDIT;
        start_editing( ch, FUNC, current_config ? current_config : "" );

        return;
    }

    ch_println( ch, "Invalid argument." );
    return;
}

