CMDF do_hell( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    sh_int time;
    bool h_d = FALSE;
    struct tm* tms;
    argument = one_argument( argument, arg );

    if ( !*arg )
    {
        ch_println( ch, "Hell who, and for how long?" );
        return;
    }

    if ( ( victim = get_char_world_full( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( IS_IMMORTAL( victim ) )
    {
        ch_println( ch, "There is no point in helling an immortal." );
        return;
    }

    if ( victim->pcdata->release_date != 0 )
    {
        ch_println( ch, "They are already in hell until %24.24s, by %s.",
                   ctime( &victim->pcdata->release_date ), victim->pcdata->helled_by );
        return;
    }

    argument = one_argument( argument, arg );

    if ( !*arg || !is_number( arg ) )
    {
        ch_println( ch, "Hell them for how long?" );
        return;
    }

    time = atoi( arg );

    if ( time <= 0 )
    {
        ch_println( ch, "You cannot hell for zero or negative time." );
        return;
    }

    argument = one_argument( argument, arg );

    if ( !*arg || !str_prefix( arg, "hours" ) )
        h_d = TRUE;
    else if ( str_prefix( arg, "days" ) )
    {
        ch_println( ch, "Is that value in hours or days?" );
        return;
    }
    else if ( time > 30 )
    {
        ch_println( ch, "You may not hell a person for more than 30 days at a time." );
        return;
    }

    tms = localtime( &current_time );

    if ( h_d )
        tms->tm_hour += time;
    else
        tms->tm_mday += time;

    victim->pcdata->release_date = mktime( tms );
    SET_STRING( victim->pcdata->helled_by, ch->name );
    ch_println( ch, "%s will be released from hell at %24.24s.", victim->name, ctime( &victim->pcdata->release_date ) );
    act( AT_MAGIC, "$n disappears in a cloud of hellish light.", victim, NULL, ch, TO_NOTVICT );
    char_from_room( victim );
    char_to_room( victim, get_room_index( 6 ) );
    act( AT_MAGIC, "$n appears in a could of hellish light.", victim, NULL, ch, TO_NOTVICT );
    do_look( victim, "auto" );
    ch_println( victim, "The immortals are not pleased with your actions."
               "You shall remain in hell for %d %s%s.\n", time, ( h_d ? "hour" : "day" ), ( time == 1 ? "" : "s" ) );
    save_char_obj( victim, true );    /* used to save ch, fixed by Thoric 09/17/96 */
    return;
}

CMDF do_unhell( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    ROOM_INDEX_DATA* location;
    argument = one_argument( argument, arg );

    if ( !*arg )
    {
        ch_println( ch, "Unhell whom..?" );
        return;
    }

    location = ch->in_room;
    ch->in_room = get_room_index( 6 );
    victim = get_char_room( ch, arg );
    ch->in_room = location; /* The case of unhell self, etc. */

    if ( !victim || IS_NPC( victim ) || victim->in_room->vnum != 6 )
    {
        ch_println( ch, "No one like that is in hell." );
        return;
    }

    location = get_room_index( 472 );

    if ( !location )
        location = ch->in_room;

    MOBtrigger = FALSE;
    act( AT_MAGIC, "$n disappears in a cloud of godly light.", victim, NULL, ch, TO_NOTVICT );
    char_from_room( victim );
    char_to_room( victim, location );
    ch_println( victim, "The gods have smiled on you and released you from hell early!" );
    do_look( victim, "auto" );
    ch_println( ch, "They have been released." );

    if ( victim->pcdata->helled_by )
    {
        if ( str_cmp( ch->name, victim->pcdata->helled_by ) )
            ch_println( ch, "(You should probably write a note to %s, explaining the early release.)",
                       victim->pcdata->helled_by );

