    save_char_obj( victim, true );
    return;
}

/* Vnum search command by Swordbearer */
CMDF do_vsearch( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    bool found = FALSE;
    OBJ_DATA* obj;
    OBJ_DATA* in_obj;
    int obj_counter = 1;
    int argi;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax:  vsearch <vnum>." );
        return;
    }

    set_pager_color( AT_PLAIN, ch );
    argi = atoi( arg );

    if ( argi < 0 && argi > 20000 )
    {
        ch_println( ch, "Vnum out of range." );
        return;
    }

    for ( obj = first_object; obj != NULL; obj = obj->next )
    {
        if ( !can_see_obj( ch, obj ) || !( argi == obj->pIndexData->vnum ) )
            continue;

        found = TRUE;

        for ( in_obj = obj; in_obj->in_obj != NULL; in_obj = in_obj->in_obj );

        if ( in_obj->carried_by != NULL )
            pager_printf( ch, "[%2d] Level %d %s carried by %s.\n",
                          obj_counter, obj->level, obj_short( obj ), PERS( in_obj->carried_by, ch ) );
        else
            pager_printf( ch, "[%2d] [%-5d] %s in %s.\n", obj_counter,
                          ( ( in_obj->in_room ) ? in_obj->in_room->vnum : 0 ),
                          obj_short( obj ), ( in_obj->in_room == NULL ) ? "somewhere" : in_obj->in_room->name );

        obj_counter++;
    }

    if ( !found )
        ch_println( ch, "Nothing like that in hell, earth, or heaven." );

    return;
}

