/*
    Free a social structure                  -Thoric
*/
int free_social( SOCIALTYPE* social )
{
    if ( !social )
        return E_LOTJ_MISSING_ARGUMENTS;

    FREE_STRUCT( social, social_type_fields );
    return E_LOTJ_SUCCESS;
}

/*
    Remove a social from it's hash index             -Thoric
*/
void unlink_social( SOCIALTYPE* social )
{
    SOCIALTYPE* tmp, *tmp_next;
    int hash;

    if ( !social )
    {
        bug( "Unlink_social: NULL social", 0 );
        return;
    }

    if ( social->name[0] < 'a' || social->name[0] > 'z' )
        hash = 0;
    else
        hash = ( social->name[0] - 'a' ) + 1;

    if ( social == ( tmp = social_index[hash] ) )
    {
        social_index[hash] = tmp->next;
        return;
    }

    for ( ; tmp; tmp = tmp_next )
    {
        tmp_next = tmp->next;

        if ( social == tmp_next )
        {
            tmp->next = tmp_next->next;
            return;
        }
    }
}

/*
    Add a social to the social index table           -Thoric
    Hashed and insert sorted
*/
void add_social( SOCIALTYPE* social )
{
    int hash, x;
    SOCIALTYPE* tmp, *prev;

    if ( !social )
    {
        bug( "Add_social: NULL social", 0 );
        return;
    }

    if ( !social->name )
    {
        bug( "Add_social: NULL social->name", 0 );
        return;
    }

    if ( !social->char_no_arg )
    {
        bug( "Add_social: NULL social->char_no_arg", 0 );
        return;
    }

    /*
        make sure the name is all lower-case
    */
    for ( x = 0; social->name[x] != '\0'; x++ )
        social->name[x] = LOWER( social->name[x] );

    if ( social->name[0] < 'a' || social->name[0] > 'z' )
        hash = 0;
    else
        hash = ( social->name[0] - 'a' ) + 1;

    if ( ( prev = tmp = social_index[hash] ) == NULL )
    {
        social->next = social_index[hash];
        social_index[hash] = social;
        return;
    }

    for ( ; tmp; tmp = tmp->next )
    {
        if ( ( x = strcmp( social->name, tmp->name ) ) == 0 )
        {
            bug( "Add_social: trying to add duplicate name to bucket %d", hash );
            free_social( social );
            return;
        }
        else if ( x < 0 )
        {
            if ( tmp == social_index[hash] )
            {
                social->next = social_index[hash];
                social_index[hash] = social;
                return;
            }

            prev->next = social;
            social->next = tmp;
            return;
        }

        prev = tmp;
    }

    /*
        add to end
    */
    prev->next = social;
    social->next = NULL;
    return;
}

/*
    Social editor/displayer/save/delete              -Thoric
*/
CMDF do_sedit( CHAR_DATA* ch, char* argument )
{
    SOCIALTYPE* social;
    char arg1[MIL], arg2[MIL], buf[MSL];
    smash_tilde( argument );
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    set_char_color( AT_SOCIAL, ch );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Csedit <&wsocial&C> [field]" );
        ch_println( ch, "&zSyntax: &Csedit <&wsocial&C> create" );

        if ( get_trust( ch ) > LEVEL_GOD )
            ch_println( ch, "&zSyntax: &Csedit <&wsocial&C> delete" );

        if ( get_trust( ch ) > LEVEL_LESSER )
            ch_println( ch, "&zSyntax: &Csedit <&wsave&C>" );

        ch_println( ch, "\nField being one of:" );
        ch_println( ch, "  cnoarg onoarg cfound ofound vfound cauto oauto vaction oaction caction naction" );
        return;
    }

    social = find_social( arg1 );

    if ( !str_cmp( arg2, "create" ) )
    {
        if ( social )
        {
            ch_println( ch, "That social already exists!" );
            return;
        }

        CREATE( social, SOCIALTYPE, 1 );
        SET_STRING( social->name, arg1 );
        snprintf( buf, MSL, "You %s.", arg1 );
        SET_STRING( social->char_no_arg, buf );
        add_social( social );
        ch_println( ch, "Social added." );
        return;
    }

    if ( !social )
    {
        ch_println( ch, "Social not found." );
        return;
    }

    if ( arg2[0] == '\0' || !str_cmp( arg2, "show" ) )
    {
        ch_println( ch, "Social  : %s\n\nCNoArg  : %s", social->name, social->char_no_arg );
        ch_println( ch, "ONoArg  : %s\nCFound  : %s\nOFound  : %s",
                   social->others_no_arg ? social->others_no_arg : "(not set)",
                   social->char_found ? social->char_found : "(not set)",
                   social->others_found ? social->others_found : "(not set)" );
        ch_println( ch, "VFound  : %s\nCAuto   : %s\nOAuto   : %s",
                   social->vict_found ? social->vict_found : "(not set)",
                   social->char_auto ? social->char_auto : "(not set)",
                   social->others_auto ? social->others_auto : "(not set)" );
        ch_println( ch, "VAction : %s\nOAction : %s\nCAction : %s\nNAction : %s\nTimer   : %d",
                   social->vaction ? social->vaction : "(not set)", social->oaction ? social->oaction : "(not set)",
                   social->caction ? social->caction : "(not set)", social->naction ? social->naction : "(not set)",
                   social->timer );
        ch_println( ch, "Gender  : %s\nGenderto: %s",
                   social->gender == 1 ? "males" : social->gender == 2 ? "females" : "anyone",
                   social->genderto == 1 ? "males" : social->genderto == 2 ? "females" : "anyone" );
        ch_println( ch, "%s",
                   social->
                   approach ? " (Must be approached to use this social.)" : " (This social doesn't require approach.)" );
        return;
    }

    if ( get_trust( ch ) > LEVEL_GOD && !str_cmp( arg2, "delete" ) )
    {
        delete_sql_row_by_id( DB_TABLE_SOCIALS, social->id);
        unlink_social( social );
        free_social( social );
        ch_println( ch, "Deleted." );
        return;
    }

    if ( !str_cmp( arg2, "cnoarg" ) )
    {
        if ( argument[0] == '\0' || !str_cmp( argument, "clear" ) )
        {
            ch_println( ch, "You cannot clear this field.  It must have a message." );
            return;
        }

        SET_STRING( social->char_no_arg, argument );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "gender" ) )
    {
        if ( NULLSTR( argument ) )
            social->gender = 0;
        else
            social->gender = atoi( argument );

        if ( social->gender > 2 || social->gender < 0 )
            ch_println( ch, "Out of range, setting gender to 0 (none)" );
        else
            ch_println( ch, "%s can now only be done by %s.", social->name,
                       social->gender == 1 ? "males" : social->gender == 2 ? "females" : "anyone" );
        social_save(social);
        return;
    }

    if ( !str_cmp( arg2, "genderto" ) )
    {
        if ( NULLSTR( argument ) )
            social->genderto = 0;
        else
            social->genderto = atoi( argument );

        if ( social->genderto > 2 || social->genderto < 0 )
            ch_println( ch, "Out of range, setting genderto to 0 (none)" );
        else
            ch_println( ch, "%s can now only be done to %s.", social->name,
                       social->genderto == 1 ? "males" : social->genderto == 2 ? "females" : "anyone" );
        social_save(social);
        return;
    }

    if ( !str_cmp( "timer", arg2 ) )
    {
        social->timer = atoi( argument );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( "oaction", arg2 ) )
    {
        SET_STRING( social->oaction, !NULLSTR( argument ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( "naction", arg2 ) )
    {
        SET_STRING( social->naction, !NULLSTR( argument ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( "caction", arg2 ) )
    {
        SET_STRING( social->caction, !NULLSTR( argument ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( "vaction", arg2 ) )
    {
        SET_STRING( social->vaction, !NULLSTR( argument ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "approach" ) )
    {
        social->approach = !social->approach;
        ch_println( ch, "%s", social->approach ? "Social now requires approach." : "Social no longer requires approach." );
        social_save(social);        
        return;
    }

    if ( !str_cmp( arg2, "onoarg" ) )
    {
        SET_STRING( social->others_no_arg, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);        
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "cfound" ) )
    {
        SET_STRING( social->char_found, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "ofound" ) )
    {
        SET_STRING( social->others_found, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "vfound" ) )
    {
        SET_STRING( social->vict_found, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "cauto" ) )
    {
        SET_STRING( social->char_auto, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( !str_cmp( arg2, "oauto" ) )
    {
        SET_STRING( social->others_auto, ( !NULLSTR( argument ) && str_cmp( argument, "clear" ) ) ? argument : NULL );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    if ( get_trust( ch ) > LEVEL_GREATER && !str_cmp( arg2, "name" ) )
    {
        bool relocate;
        SOCIALTYPE* checksocial = NULL;
        one_argument( argument, arg1 );

        if ( NULLSTR( arg1 ) )
        {
            ch_println( ch, "Cannot clear name field!" );
            return;
        }

        if ( ( checksocial = find_social( arg1 ) ) != NULL )
        {
            ch_println( ch, "There is already a social named %s.", arg1 );
            return;
        }

        if ( arg1[0] != social->name[0] )
        {
            unlink_social( social );
            relocate = TRUE;
        }
        else
            relocate = FALSE;

        SET_STRING( social->name, arg1 );

        if ( relocate )
            add_social( social );
        social_save(social);
        ch_println( ch, "Done." );
        return;
    }

    /*
        display usage message
    */
    do_sedit( ch, "" );
}

/*
    Free a command structure                 -Thoric
*/
int free_command( CMDTYPE* command )
{
    if ( !command )
        return E_LOTJ_MISSING_ARGUMENTS;

    FREE_STRUCT( command, cmd_type_fields );
    return E_LOTJ_SUCCESS;
}

/*
    Remove a command from it's hash index            -Thoric
*/
void unlink_command( CMDTYPE* command )
{
    CMDTYPE* tmp, *tmp_next;
    int hash;

    if ( !command )
    {
        bug( "Unlink_command NULL command", 0 );
        return;
    }

    hash = command->name[0] % 126;

    if ( command == ( tmp = command_hash[hash] ) )
    {
        command_hash[hash] = tmp->next;
        return;
    }

    for ( ; tmp; tmp = tmp_next )
    {
        tmp_next = tmp->next;

        if ( command == tmp_next )
        {
            tmp->next = tmp_next->next;
            return;
        }
    }
}
/*
    Add a command to the command hash table          -Thoric
*/
void add_command( CMDTYPE* command )
{
    int hash, x;
    CMDTYPE *tmp, *prev;

    if ( !command )
    {
        bug( "Add_command: NULL command", 0 );
        return;
    }

    if ( !command->name )
    {
        bug( "Add_command: NULL command->name", 0 );
        return;
    }

    if ( !command->do_fun )
    {
        bug( "Add_command: NULL command->do_fun", 0 );
        return;
    }

    /*
        make sure the name is all lowercase
    */
    for ( x = 0; command->name[x] != '\0'; x++ )
        command->name[x] = LOWER( command->name[x] );

    hash = command->name[0] % 126;

    /* Initialize previous pointer to NULL and current to the start of the list */
    prev = NULL;
    tmp = command_hash[hash];

    /* Traverse the list and find the correct position based on priority */
    while ( tmp && tmp->priority <= command->priority )
    {
        prev = tmp;
        tmp = tmp->next;
    }

    /* If prev is NULL, insert at the beginning of the list */
    if ( prev == NULL )
    {
        command->next = command_hash[hash];
        command_hash[hash] = command;
    }
    else
    {
        /* Insert between prev and tmp */
        prev->next = command;
        command->next = tmp;
    }

    return;
}

/*
    Command editor/displayer/save/delete             -Thoric
*/
CMDF do_cedit( CHAR_DATA* ch, char* argument )
{
    CMDTYPE* command;
    char arg1[MIL];
    char arg2[SUPER_MIL];
    static char* const cedit_positions  [] = {"POS_DEAD", "POS_MORTAL", "POS_INCAP", "POS_STUNNED", "POS_SLEEPING",
                                              "POS_RESTING", "POS_SITTING", "POS_FIGHTING", "POS_STANDING", "POS_MOUNTED", "POS_SHOVE", "POS_DRAG"
                                             };
    static char* const cedit_log [] = {"LOG_NORMAL", "LOG_ALWAYS", "LOG_NEVER", "LOG_BUILD", "LOG_HIGH", "LOG_COMM", "LOG_MPROG", "LOG_LPROG", "LOG_ALL"};
    smash_tilde( argument );
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    set_char_color( AT_IMMORT, ch );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> create [&wcode&C]" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> delete" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> show" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> raise" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> lower" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> list" );
        ch_println( ch, "  &zSyntax: &Ccedit <&wcommand&C> &C[&wfield&C]&D" );
        ch_println( ch, "\n  &zField being one of:" );
        ch_println( ch, "  &Blevel position log code ooc held manifest spirit&D" );
        return;
    }

    int hash = arg1[0] % 126;
    for ( command = command_hash[hash]; command; command = command->next )
        if ( !str_cmp( command->name, arg1 ) )
            break;

    if ( !str_cmp( arg2, "create" ) )
    {
        if ( command )
        {
            ch_println( ch, "&RC&zedit that command already exists!  &Ccedit %s&D", command->name );
            return;
        }

        for ( int hash = 0; hash < 126; hash++ )
        {
            for ( CMDTYPE* cmdcheck = command_hash[hash]; cmdcheck; cmdcheck = cmdcheck->next )
            {
                if ( get_trust( ch ) < LEVEL_ADMIN && cmdcheck->level > get_trust( ch ) && !str_cmp( cmdcheck->fun_name, arg2 ) )
                {
                    ch_println( ch, "&RUnable to add: There's already a command with that function and it's higher than your level." );
                    return;
                }
            }
        }

        CREATE( command, CMDTYPE, 1 );
        SET_STRING( command->name, arg1 );
        command->level = get_trust( ch );

        if ( *argument )
            one_argument( argument, arg2 );
        else
            snprintf( arg2, SUPER_MIL, "do_%s", arg1 );

        command->do_fun = skill_function( arg2 );
        SET_STRING( command->fun_name, arg2 );
        add_command( command );
        ch_println( ch, "&RC&zedit command &c%s &zadded.", command->name );

        if ( command->do_fun == skill_notfound )
            ch_println( ch, "&RC&zedit code &c%s &znot found.  Set to no code.&D", arg2 );
        command_save(command);
        command->priority = command->id;
        command_save(command);
        return;
    }

    if ( !command )
        command = find_command( arg1 );

    if ( !command )
    {
        ch_println( ch, "&RC&zedit command not found.&D" );
        return;
    }
    else if ( command->level > get_trust( ch ) && get_trust( ch ) < LEVEL_ADMIN )
    {
        ch_println( ch, "&RC&zedit change disallowed due to your level.&D" );
        return;
    }

    if ( NULLSTR( arg2 ) || !str_cmp( arg2, "show" ) )
    {
        ch_println( ch, "&RC&zedit status:" );
        ch_println( ch, "  &zID:              &C%d", command->id );
        ch_println( ch, "  &zCommand:        &C%s", command->name );
        ch_println( ch, "  &zLevel:          &C%d", command->level );
        ch_println( ch, "  &z(Min) Position: &C%d&z:       &c%s", command->position, cedit_positions[command->position] );
        ch_println( ch, "  &zLog (Status):   &C%d&z:       &c%s", command->log, cedit_log[command->log] );
        ch_println( ch, "  &zOOC:            &C%d&z:       &c%s", command->ooc, command->ooc ? "ooc" : "no ooc" );
        ch_println( ch, "  &zHeld:           &C%d&z:       &c%s", command->held, command->held ? "held" : "not held" );
        ch_println( ch, "  &zCode:           &C%s", command->fun_name );
        ch_println( ch, "  &zPriority Order: &C%d", command->priority );
        ch_println( ch, "  &zSpirit:         Toggled&z: &c%s",
                   command->spirit ? "&cSpirits can use this command&D" : "No spirits can use this" );
        ch_println( ch, "  &zManifest:       Toggled&z: &c%s&D\n",
                   command->manifest ? "&cManifested spirits can use this command&D" : "No manifested spirits can use this" );

        if ( command->userec.num_uses )
            send_timer( &command->userec, ch );

        return;
    }

    if ( !str_cmp( arg2, "raise" ) )
    {
        CMDTYPE* tmp, *tmp_next;
        int hash = command->name[0] % 126;

        if ( ( tmp = command_hash[hash] ) == command )
        {
            ch_println( ch, "&RC&zedit this command is already at the top.&D" );
            return;
        }

        if ( tmp->next == command )
        {
            command_hash[hash] = command;
            tmp_next = tmp->next;
            tmp->next = command->next;
            command->next = tmp;
            ch_println( ch, "&RC&zedit raised &c%s &zabove &c%s.&D", command->name, command->next->name );
            command->priority = command->next->priority - 1;
            command_save(command);
            return;
        }

        for ( ; tmp; tmp = tmp->next )
        {
            tmp_next = tmp->next;

            if ( tmp_next->next == command )
            {
                tmp->next = command;
                tmp_next->next = command->next;
                command->next = tmp_next;
                ch_println( ch, "&RC&zedit raised &c%s &zabove &c%s&z.&D", command->name, command->next->name );
                command->priority = command->next->priority - 1;
                command_save(command);
                return;
            }
        }

        ch_println( ch, "&RC&zedit raise ERROR -- Not Found!&D" );
        return;
    }

    if ( !str_cmp( arg2, "lower" ) )
    {
        CMDTYPE* tmp, *tmp_next;
        int hash = command->name[0] % 126;

        if ( command->next == NULL )
        {
            ch_println( ch, "&RC&zedit this command is already at the bottom.&D" );
            return;
        }

        tmp = command_hash[hash];

        if ( tmp == command )
        {
            tmp_next = tmp->next;
            command_hash[hash] = command->next;
            command->next = tmp_next->next;
            tmp_next->next = command;
            ch_println( ch, "&RC&zedit lowered &c%s &zbelow &c%s&z.&D", command->name, tmp_next->name );
            command->priority = tmp_next->priority + 1;
            command_save(command);
            return;
        }

        for ( ; tmp; tmp = tmp->next )
        {
            if ( tmp->next == command )
            {
                tmp_next = command->next;
                tmp->next = tmp_next;
                command->next = tmp_next->next;
                tmp_next->next = command;
                ch_println( ch, "&RC&zedit lowered &c%s &zbelow &c%s&z.&D", command->name, tmp_next->name );
                command->priority = tmp_next->priority + 1;
                command_save(command);
                return;
            }
        }

        ch_println( ch, "&RC&zedit lower ERROR -- Not Found!&D" );
        return;
    }

    if ( !str_cmp( arg2, "list" ) )
    {
        CMDTYPE* tmp;
        int hash = command->name[0] % 126;
        pager_printf( ch, "&RC&zedit priority placement for &z(&c%s&z):&D\n", command->name );

        for ( tmp = command_hash[hash]; tmp; tmp = tmp->next )
        {
            if ( tmp == command )
                set_pager_color( AT_GREEN, ch );
            else
                set_pager_color( AT_PLAIN, ch ); // GRAL dislike this coloring scheme

            pager_printf( ch, "  %s&D\n", tmp->name );
        }

        return;
    }

    if ( !str_cmp( arg2, "delete" ) )
    {
        ch_println( ch, "&RC&zedit deleted &c%s&z.&D", command->name );
        command_sql_delete( command );
        return;
    }

    if ( !str_cmp( arg2, "code" ) )
    {
        DO_FUN* fun = skill_function( argument );

        if ( fun == skill_notfound )
        {
            ch_println( ch, "&RC&zedit skill code not found.\n  (example for &clook &zthe code would be &cdo_look&z).&D" );
            return;
        }

        for ( int hash = 0; hash < 126; hash++ )
        {
            for ( CMDTYPE* cmdcheck = command_hash[hash]; cmdcheck; cmdcheck = cmdcheck->next )
            {
                if ( get_trust( ch ) < LEVEL_ADMIN && cmdcheck->level > get_trust( ch ) && !str_cmp( cmdcheck->fun_name, argument ) )
                {
                    ch_println( ch, "&RUnable to set code: There's already a command with that function and it's higher than your level." );
                    return;
                }
            }
        }

        command->do_fun = fun;        
        SET_STRING( command->fun_name, argument );
        ch_println( ch, "&RC&zedit &c%s's &zcode set to &c%s&z.&D", command->name, argument );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "level" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&RC&zedit level between &c# &zand &c%d&D", MAX_IMM_LEVEL );
            return;
        }

        int level = atoi( argument );

        if ( ( level < 0 || level > get_trust( ch ) ) || argument[0] == '\0'  )
        {
            ch_println( ch, "&RC&zedit level &c%d&z out of range or out of your trust level &c%d&z.&D", level, get_trust ( ch ) );
            return;
        }

        if ( level > command->level && command->do_fun == do_switch )
        {
            command->level = level;
            check_switches( FALSE );
        }
        else
            command->level = level;

        ch_println( ch, "&RC&zedit &c%s&z level &c%d &zchanged.&D", command->name, level );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "log" ) )
    {
        int log = atoi( argument );

        if ( log < 0 || log > LOG_LPROG || argument[0] == '\0' )
        {
            ch_println( ch, "&RC&zedit log range is &c0 <= &R# &z<= &c%d.", LOG_LPROG );
            ch_println( ch, "&c0 &zLOG_NORMAL, &c1 &zLOG_ALWAYS, &c2 &zLOG_NEVER, &c3 &zLOG_BUILD, &c4 &zLOG_HIGH,\n&c5 &zLOG_COMM, &r6 LOG_MPROG&z, &r7 LOG_LPROG&z, &r8 LOG_ALL&D" );
            return;
        }

        command->log = log;
        ch_println( ch, "&RC&zedit &c%s &zlog level &c%d &zsaved.&D", command->name, log  );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "held" ) )
    {
        int held = atoi( argument );

        if ( held < 0 || held > 1 || argument[0] == '\0' )
        {
            ch_println( ch, "&RC&zedit held range: &c1 &zfor held, &c0 &zfor non-held&D" );
            return;
        }

        command->held = held;
        ch_println( ch, "&RC&zedit held saved.&D" );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "ooc" ) )
    {
        int ooc = atoi( argument );

        if ( ooc < 0 || ooc > 1 || argument[0] == '\0' )
        {
            ch_println( ch, "&RC&zedit OOC range: &c1 &zfor OOC, &c0 &zfor IC.&D" );
            return;
        }

        command->ooc = ooc;
        ch_println( ch, "&RC&zedit ooc set.&D" );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "spirit" ) )
    {
        command->spirit = !command->spirit;
        ch_println( ch, "&RC&zedit &c%s &zcan &c%s be used by &wspirits&z.&D", capitalize( command->name ), command->spirit ? "now" : "no longer" );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "manifest" ) )
    {
        command->manifest = !command->manifest;
        ch_println( ch, "&RC&zedit &c%s &zcan &c%s be used by &wunmanifested spirits&z.&D", capitalize( command->name ), command->manifest ? "now" : "no longer" );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "position" ) )
    {
        int position = atoi( argument );

        if ( position < 0 || position > POS_DRAG || argument[0] == '\0' )
        {
            ch_println( ch, "&RC&zedit position range &c0 &z<= &R# &z<= &c%d&z.", POS_DRAG );
            ch_println( ch, "  &c0 &zPOS_DEAD     &c1 &zPOS_MORTAL   &c2 &zPOS_INCAP,   &c3 &zPOS_STUNNED" );
            ch_println( ch, "  &c4 &zPOS_SLEEPING &c5 &zPOS_RESTING  &c6 &zPOS_SITTING  &c7 &zPOS_FIGHTING" );
            ch_println( ch, "  &c8 &zPOS_STANDING &c9 &zPOS_MOUNTED &c10 &zPOS_SHOVE   &c11 &zPOS_DRAG&D" );
            return;
        }

        command->position = position;
        ch_println( ch, "&RC&zedit position set &c%d &z(&c%s&z) done.&D", position, cedit_positions[position] );
        command_save(command);
        return;
    }

    if ( !str_cmp( arg2, "name" ) )
    {
        bool relocate;
        CMDTYPE* checkcmd = NULL;
        one_argument( argument, arg1 );

        if ( NULLSTR( arg1 ) )
        {
            ch_println( ch, "&RC&zedit cannot clear name field!&D" );
            return;
        }

        if ( ( checkcmd = find_command( arg1 ) ) != NULL )
        {
            ch_println( ch, "&RC&zedit there is already a command named &c%s&z.&D", arg1 );
            return;
        }

        if ( arg1[0] != command->name[0] )
        {
            unlink_command( command );
            relocate = TRUE;
        }
        else
            relocate = FALSE;

        SET_STRING( command->name, arg1 );

        if ( relocate )
            add_command( command );

        ch_println( ch, "&RC&zedit &c%s &zname saved (&c%s&z).&D", command->name, argument );
        command_save(command);
        return;
    }

    /*
        display usage message
    */
    do_cedit( ch, "" );
    return;
}

CMDF do_promote( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL];
    CHAR_DATA* victim;
    int raise_amt = 0, rank1 = 0, rank2 = 0;
    DIVISION_DATA* div = NULL, *div2 = NULL;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "NPC's can not promote someone." );
        return;
    }

    if ( !ch->pcdata->clan )
    {
        ch_println( ch, "Join a clan first." );
        return;
    }

    if ( !division( ch ) || !division( ch )->last_rank )
    {
        ch_println( ch, "The divisions must be set up first." );
        return;
    }

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Cpromote <&wchar&C> <&wrank #&C>&w" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "They must be present to be promoted." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "You must be mad." );
        return;
    }

    if ( !victim->pcdata->clan || ( ( victim->pcdata->clan != ch->pcdata->clan ) && ( get_trust( ch ) < sysdata.log_level ) ) )
    {
        ch_println( ch, "You can not promote a player who is not in your clan." );
        return;
    }

    if ( !ch->pcdata->clan->first_division )
    {
        ch_println( ch, "The leader of %s must first set up the divisions.", ch->pcdata->clan->name );
        return;
    }

    div = division( ch );
    div2 = division( victim );

    if ( !div2->first_rank || !div2->last_rank )
    {
        ch_printf( ch, "The leader of %s must first set up ranks for %s.", ch->pcdata->clan->name, div->name );
        return;
    }

    if ( NULLSTR( arg2 ) )
    {
        ch_println( ch, "%s is a %s in %s.", g_name( victim, ch ), get_rank( victim ), get_division( victim ) );
        return;
    }

    raise_amt =  atoi( arg2 );
    rank1 = div->last_rank->num - ch->pcdata->clan_rank;
    rank2 = div2->last_rank->num - victim->pcdata->clan_rank;

    if ( div2->last_rank->num - raise_amt < 0 )
    {
        ch_println( ch, "Out of range. Valid range for %s is 0-%d.", div2->name, div2->last_rank->num );
        return;
    }

    if ( get_trust( ch ) >= sysdata.log_level || !str_cmp( ch->name, ch->pcdata->clan->leader ) )
    {
    }
    else
    {
        if ( victim == ch )
        {
            ch_println( ch, "You cannot promote yourself." );
            return;
        }

        if ( !is_name( "induct", ch->pcdata->bestowments ) && rank1 >= 5 )
        {
            send_to_char
            ( "You must be at least five spots from the top of your division to promote.\nAlternatively, have your leader empower you with INDUCT.\n",
              ch );
            return;
        }

        if ( rank2 <= rank1 )
        {
            ch_println( ch, "You cannot promote someone who is of greater or equal rank." );
            return;
        }

        if ( div2->last_rank->num - raise_amt < rank1 )
        {
            ch_println( ch, "You cannot promote someone to a higher rank than your own." );
            return;
        }
    }

    bool promoted = ( raise_amt > victim->pcdata->clan_rank );
    victim->pcdata->clan_rank = raise_amt;
    ch_println( ch, "You %s %s to the rank of %s in %s.", promoted ? "promote" : "demote",  g_name( victim, ch ), get_rank( victim ),
               get_division( victim ) );
    ch_println( victim, "%s has %s you to the rank of %s in %s.", g_name( ch, victim ), promoted ? "promoted" : "demoted", get_rank( victim ),
               get_division( victim ) );
    update_roster( victim );
    save_char_obj( victim, TRUE );
    return;
}

CMDF do_saveall( )
{
    CHAR_DATA* vch;
    CHAR_DATA* vch_next;

    for ( vch = first_char; vch; vch = vch_next )
    {
        vch_next = vch->next;

        if ( !IS_NPC( vch ) )
        {
            do_save( vch, "" );
        }
    }

    return;
}

void autosave( void )
{
    CHAR_DATA* vch;
    CHAR_DATA* vch_next;

    for ( vch = first_char; vch; vch = vch_next )
    {
        if ( vch == NULL )
            break;

        vch_next = vch->next;

        if ( !IS_NPC( vch ) )
            do_save( vch, "-noalert" );
    }

    save_persistent_mobs( false );
    save_persistent_objects( false );
    return;
}

CMDF do_immortalize( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    char arg2[MIL];
    int oldlevel, level;
    char buf[MIL];
    argument = one_argument( argument, arg );
    one_argument( argument, arg2 );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "You need to pick a person to immortalize." );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "That person doesn't exist." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "Advance a mob.. yea right." );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "Nice try" );
        return;
    }

    if ( NULLSTR( arg2 ) )
    {
        send_to_char( "&zSyntax: &CImmortalize <&wcharname&C> <&wimmlevel&C>", ch );
        return;
    }

    level = atoi( arg2 );

    if ( level < ( LEVEL_HERO + 1 ) || level > MAX_IMM_LEVEL || level > get_trust( ch ) )
    {
        ch_println( ch, "Level out of range." );
        return;
    }

    if ( get_trust( victim ) == level )
    {
        ch_println( ch, "Victim is already at that level" );
        return;
    }

    if ( get_trust( ch ) <= get_trust( victim ) )
    {
        ch_println( ch, "You are not authorized to do that" );
        return;
    }

    oldlevel = get_trust( victim );
    victim->top_level = level;
    snprintf( buf, MIL, "%s advanced %s from level %d to %d", ch->name, victim->name, oldlevel, level );
    log_string( buf );
    to_channel( buf, CHANNEL_MONITOR, "Monitor", LEVEL_IMMORTAL );
    do_save( victim, "-noalert" );
    return;
}

