CMDF do_freevnums( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    char arg2[MSL];
    char buf[MSL];
    AREA_DATA* pArea;
    bool a_conflict;
    int low_v = 0, high_v = 0, count = 0;
    int l = 0, h = 0, curr = 0, total_c = 0, total_r = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CFREEVNUMS [low vnum] [high vnum]" );
        return;
    }
    else
    {
        low_v = atoi( arg1 );
        high_v = atoi( arg2 );
    }

    if ( low_v < 1 || low_v > MAX_VNUMS )
    {
        ch_println( ch, "Invalid argument for bottom of range." );
        return;
    }

    if ( high_v < 1 || high_v > MAX_VNUMS )
    {
        ch_println( ch, "Invalid argument for top of range." );
        return;
    }

    if ( high_v <= low_v )
    {
        ch_println( ch, "Bottom of range must be below top of range." );
        return;
    }

    if ( ( high_v - low_v ) > 1000000 )
    {
        ch_println( ch, "Sorry, You can only check up to 1000000 rooms at a time!" );
        return;
    }

    snprintf( buf, MSL, "&zFree vnum ranges in the &C%d &zto &C%d &zRANGE: &C------ \n\n", low_v, high_v );
    send_to_char( buf, ch );
    /*
        Check the range room-by-room. This is going to SUCK processor time...
    */
    l = low_v;
    h = low_v;

    for ( curr = low_v; curr <= high_v; curr++ )
    {
        a_conflict = FALSE;

        for ( pArea = first_area; pArea; pArea = pArea->next )
        {
            if ( curr >= pArea->min_vnum && curr <= pArea->max_vnum )
                a_conflict = TRUE;
        }

        if ( a_conflict || curr == high_v )
        {
            count = curr - l - 1;
            h = count + l;

            if ( curr == high_v )
                h++;

            if ( count > 1 )
            {
                snprintf( buf, MSL, "&BVNums: &C%7d &B- &C%7d   &B|   Count: &C%8d&B\n", l, h, count );
                send_to_char( buf, ch );
                total_c++;
                total_r += count;
            }

            l = curr + 1;
            h = curr + 1;
        }
    }

    snprintf( buf, MSL, "\n&zThere are &C%d &zfree rooms in &C%d &zset(s) of vnums.\n", total_r, total_c );
    send_to_char( buf, ch );
    return;
}

CMDF do_compute( CHAR_DATA* ch, char* argument )
{
    char arg1[MSL];
    char arg2[MSL];
    char arg3[MSL];
    double a = 0, b = 0, c = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( arg1[0] == '\0' || arg2[0] == '\0' || arg3[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &CCOMPUTE [first number] [expression] [second number]" );
        ch_println( ch, "Valid Expressions: + - * \\" );
        return;
    }
    else
    {
        a = atoi( arg1 );
        b = atoi( arg3 );
    }

    if ( !str_cmp( arg2, "+" ) || !str_cmp( arg2, "-" ) || !str_cmp( arg2, "\\" ) || !str_cmp( arg2, "/" )
            || !str_cmp( arg2, "*" ) )
    {
        if ( a < -999999 || a > 999999 || b < -999999 || b > 999999 )
        {
            ch_println( ch, "Sorry, One of your numbers is too large." );
            return;
        }
    }
    else
    {
        ch_println( ch, "&RInvalid expression for formula!" );
        return;
    }

    if ( !str_cmp( arg2, "+" ) )
        c = a + b;

    if ( !str_cmp( arg2, "-" ) )
        c = a - b;

    if ( !str_cmp( arg2, "*" ) )
        c = a * b;

    if ( !str_cmp( arg2, "\\" ) )
