int remove_disallow( DISALLOW_DATA** first, DISALLOW_DATA** last, DISALLOW_DATA* disallow )
{
    if ( !first || !last || !disallow )
        return E_LOTJ_MISSING_ARGUMENTS;

    UNLINK( disallow, *first, *last, next, prev );
    FREE_STRUCT( disallow, disallow_fields );
    return E_LOTJ_SUCCESS;
}

CMDF do_disallow( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL], arg3[MIL], arg4[MIL], name[128];
    CHAR_DATA* victim = NULL;
    ACCOUNT_DATA* acc = NULL;
    DISALLOW_DATA* disallow = NULL, *dnext = NULL;
    DISALLOW_DATA** first = NULL;
    DISALLOW_DATA** last = NULL;
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );
    argument = one_argument( argument, arg4 );
    bool has_match = false;

    if ( NULLSTR( arg ) || NULLSTR( arg2 ) )
    {
        ch_println( ch, "&zSyntax: &Cdisallow <&wchar/@acct&C> [command] [duration] <&wminutes/hours/days&C> <&wreason&C>" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> [command] (to remove a disallow)" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> list" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> clear" );
        return;
    }

    if ( arg[0] == '@' )
    {
        if ( ( acc = get_account( arg + 1 ) ) == NULL )
        {
            ch_println( ch, "Could not find that account." );
            return;
        }
    }
    else if ( ( victim = get_player_world( arg ) ) == NULL && victim != ch )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ( acc && acc->level > get_trust( ch ) ) || ( !acc && get_trust( victim ) > get_trust( ch ) ) )
    {
        ch_println( ch, "You aren't powerful enough..." );
        return;
    }

    first = acc ? &acc->first_disallow : &victim->pcdata->first_disallow;
    last = acc ? &acc->last_disallow : &victim->pcdata->last_disallow;
    snprintf( name, 128, "%s%s", acc ? "@" : "", acc ? acc->name : victim->name );

    if ( !str_cmp( arg2, "list" ) )
    {
        ch_println( ch, "&zCurrent disallowed commands on &C%s&z:", name );
        for ( disallow = *first; disallow; disallow = dnext )
        {
            dnext = disallow->next;
            if ( disallow->end_time > current_time )
            {
                ch_println( ch, "&zCommand: &C%s", disallow->command );
                ch_println( ch, "&zSet by: &C%s &zon &C%s", disallow->set_by, c_time( disallow->start_time > 0 ? disallow->start_time : ( disallow->end_time - ( disallow->duration * 60 ) ), get_timezone( ch ) ) );
                ch_println( ch, "&zDuration: &C%s", dhms_string( disallow->duration, false ) );
                ch_println( ch, "&zEnds on: &C%s", c_time( disallow->end_time, get_timezone( ch ) ) );
                ch_println( ch, "&zReason: &C%s", !NULLSTR( disallow->reason ) ? disallow->reason : "Unknown" );
            }
            else
            {
                char buf[MIL];
                snprintf( buf, MIL, "Disallow of %s expiring for %s", disallow->command, name );
                log_string( buf );
                remove_disallow( first, last, disallow );
            }
        }

        return;
    }

    for ( disallow = *first; disallow; disallow = dnext )
    {
        dnext = disallow->next;
        if ( !str_cmp( arg2, "clear" ) )
        {
            remove_disallow( first, last, disallow );
        }
        else if ( is_name( arg2, disallow->command ) )
        {
            if ( NULLSTR( arg3 ) )
            {
                has_match = true;
                remove_disallow( first, last, disallow );
                break;           
            }
            else if ( !is_number( arg3 ) || NULLSTR( arg4 ) || ( str_cmp( arg4, "minute" ) && str_cmp( arg4, "minutes" ) && str_cmp( arg4, "hour" ) && str_cmp( arg4, "hours" ) && str_cmp( arg4, "day" ) && str_cmp( arg4, "days" ) ) )
            {
                ch_println( ch, "&zSyntax: &Cdisallow <&wchar/@acct&C> [command] [duration] <&wminutes/hours/days&C> <&wreason&C>" );
                ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> [command] (to remove a disallow)" );
                ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> list" );
                ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> clear" );
                return;
            }
            else
            {
                int old_duration = disallow->duration;
                disallow->duration = ( !str_cmp( arg4, "day" ) || !str_cmp( arg4, "days" ) ) ? atoi( arg3 ) * 60 * 24 : ( ( !str_cmp( arg4, "hour" ) || !str_cmp( arg4, "hours" ) ) ? atoi( arg3 ) * 60 : atoi( arg3 ) );
                disallow->end_time += ( disallow->duration - old_duration ) * 60;
                if ( acc ) account_save( acc, TRUE );
                if ( victim ) save_char_obj( victim, TRUE );
                ch_println( ch, "&zDuration changed." );
                return;
            }
        }
    }

    if ( !str_cmp( arg2, "clear" ) )
    {
        if ( acc ) account_save( acc, TRUE );
        if ( victim ) save_char_obj( victim, TRUE );
        ch_println( ch, "&zAll disallows removed from &C%s&z.", name );
        return;
    }
    else if (has_match)
    {
        if ( acc ) account_save( acc, TRUE );
        if ( victim ) save_char_obj( victim, TRUE );
        ch_println( ch, "&zNo longer disallowing &C%s&z from &C%s&z.", arg2, name );
        return;
    }
    else if ( NULLSTR( arg3 ) || NULLSTR( arg4 ) || NULLSTR( argument ) || !is_number( arg3 ) || ( str_cmp( arg4, "minute" ) && str_cmp( arg4, "minutes" ) && str_cmp( arg4, "hour" ) && str_cmp( arg4, "hours" ) && str_cmp( arg4, "day" ) && str_cmp( arg4, "days" ) ) )
    {
        ch_println( ch, "&zSyntax: &Cdisallow <&wchar/@acct&C> [command] [duration] <&wminutes/hours/days&C> <&wreason&C>" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> [command] (to remove a disallow)" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> list" );
        ch_println( ch, "&z        &Cdisallow <&wchar/@acct&C> clear" );
        return;
    }
    else
    {
        DISALLOW_DATA* disallow;
        CREATE( disallow, DISALLOW_DATA, 1 );
        SET_STRING( disallow->command, arg2 );
        SET_STRING( disallow->set_by, ch->name );
        SET_STRING( disallow->reason, argument );
        disallow->duration = ( !str_cmp( arg4, "day" ) || !str_cmp( arg4, "days" ) ) ? atoi( arg3 ) * 60 * 24 : ( ( !str_cmp( arg4, "hour" ) || !str_cmp( arg4, "hours" ) ) ? atoi( arg3 ) * 60 : atoi( arg3 ) );
        disallow->start_time = current_time;
        disallow->end_time = current_time + disallow->duration * 60;
        LINK( disallow, *first, *last, next, prev );
        if ( acc ) account_save( acc, TRUE );
        if ( victim ) save_char_obj( victim, TRUE );
        ch_println( ch, "&zDone." );
        return;
    }

    return;
}

CMDF do_recall( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
