CMDF do_makeimm( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim = NULL;
    int tmplvl = 0;
    char buf[MSL];
    bool imm = FALSE;

    if ( NULLSTR( argument ) )
    {
        send_to_char
        ( "&RUsage: makeimm <victim> <option>\n \n&WOptions:\n&ztemp     102     103\n&zbuilder  Intern  104\n",
          ch );
        return;
    }

    argument = one_argument( argument, arg );

    if ( ( victim = get_player_world( arg ) ) == NULL )
    {
        act( AT_ACTION, "You cannot find $t anywhere.", ch, arg, NULL, TO_CHAR );
        return;
    }

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Dream on." );
        return;
    }

    if ( get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "I don't think so." );
        return;
    }

    if ( !str_cmp( argument, "102" ) || !str_cmp( argument, "builder" ) )
        tmplvl = 102;

    if ( !str_cmp( argument, "102" ) || !str_cmp( argument, "103" ) || !str_cmp( argument, "104" ) )
        imm = TRUE;

    if ( !str_cmp( argument, "intern" ) )
        tmplvl = 104;

    if ( !str_cmp( argument, "temp" ) )
        tmplvl = 101;

    if ( str_cmp( argument, "temp" ) )
    {
        snprintf( buf, MSL, "%s builder", victim->name );
        do_bestow( ch, buf );
    }

    imm ? ch_println( victim, "You have been granted level %d." ) : send_to_char( "You have been temp immed.", victim );

    if ( imm )
    {
        victim->top_level = tmplvl;
        do_save( victim, "-noalert" );
        snprintf( buf, MSL, "setgroup 1 add %s", victim->name );
        interpret( ch, buf, FALSE );
    }

    if ( !imm )
    {
        snprintf( buf, MSL, "trust %s %d", victim->name, tmplvl );
        interpret( ch, buf, FALSE );
    }

    interpret( victim, "holylight", FALSE );
    interpret( victim, "config +whois", FALSE );
    interpret( victim, "config +whois", FALSE );
    snprintf( buf, MSL, "invis %d", tmplvl );
    interpret( victim, buf, FALSE );
    interpret( victim, "invis", FALSE );

    if ( imm )
        victim->pcdata->clan = get_clan( "immortal" );

    do_save( victim, "-noalert" );
    return;
}

