char* wordwrap( char* txt, sh_int wrap )
{
    static char buf[MSL];
    char* bufp;
    buf[0] = '\0';
    bufp = buf;

    if ( txt != NULL )
    {
        char line[MSL];
        char temp[MSL];
        char* ptr, *p;
        int ln, x;
        ++bufp;
        line[0] = '\0';
        ptr = txt;

        while ( *ptr )
        {
            ptr = grab_word( ptr, temp );
            ln = strlen( line );
            x = strlen( temp );

            if ( ( ln + x + 1 ) < wrap )
            {
                if ( line[ln - 1] == '.' )
                    strlcat( line, "  ", MSL );
                else
                    strlcat( line, " ", MSL );

                strlcat( line, temp, MSL );
                p = strchr( line, '\n' );
                if ( p )
                {
                    strlcat( buf, line, MSL );
                    line[0] = '\0';
                }
            }
            else
            {
                strlcat( line, "\n", MSL );
                strlcat( buf, line, MSL );
                strlcpy( line, temp, MSL );
            }
        }

        if ( !NULLSTR( line ) )
            strlcat( buf, line, MSL );
    }

    return bufp;
}

char* show_ext_flag_string( int len, char* const flagarray[] )
{
    static char buf[MSL];
    int x;
    buf[0] = '\0';

    for ( x = 0; x < len; x++ )
    {
        strlcat( buf, flagarray[x], MSL );
        strlcat( buf, ", ", MSL );
    }

    if ( ( x = strlen( buf ) ) > 0 )
        buf[x - 2] = '\0';

    return buf;
}

