    if ( IS_NPC( ch ) )
        return;

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Crename <&wvictim&C> <&wnew name&C>&w" );
        return;
    }

    /*
        Just a security precaution so you don't rename someone you don't mean
     * * too --Shaddai
    */
    if ( ( victim = get_char_room( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "That person is not in the room." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "You can't rename NPC's." );
        return;
    }

    if ( get_trust( ch ) < get_trust( victim ) )
    {
        ch_println( ch, "I don't think they would like that!" );
        return;
    }

    if ( !check_parse_name( arg2, is_droid( victim->race ) ) )
    {
        ch_println( ch, "Illegal name." );
        return;
    }

    if ( is_droid( victim->race ) )
    {
        arg2[0] = UPPER( arg2[0] );
    }
    else
    {
        strlcpy( arg2, capitalize( arg2 ), MIL );
    }

    if ( is_reserved_name( newname ) )
    {
        ch_println( ch, "That name is reserved." );
        return;
    }

    if ( player_exist( newname ) )
    {
        ch_println( ch, "That name already exists." );
        return;
    }

    /*
        Lets fix any ships they own
    */
    bool changed = FALSE;
    SHIP_DATA* ship = NULL;

    for ( ship = first_ship; ship; ship = ship->next )
    {
        changed = FALSE;

        if ( !str_cmp( victim->name, ship->shipowner ) )
        {
            SET_STRING( ship->shipowner, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, ship->pilot ) )
        {
            SET_STRING( ship->pilot, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, ship->copilot ) )
        {
            SET_STRING( ship->copilot, arg2 );
            changed = TRUE;
        }

        if ( changed )
            save_ship( ship, true );
    }
    /*
        Lets do clans now
    */

    changed = FALSE;
    if ( victim->pcdata->clan )
    {
        CLAN_DATA* clan = victim->pcdata->clan;

        if ( !str_cmp( victim->name, clan->leader ) )
        {
            SET_STRING( clan->leader, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, clan->number1 ) )
        {
            SET_STRING( clan->number1, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, clan->number2 ) )
        {
            SET_STRING( clan->number2, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, clan->lead_dev ) )
        {
            SET_STRING( clan->lead_dev, arg2 );
            changed = TRUE;
        }

        if ( changed ) save_clan( clan, true );
    }

    /*
        Bounties
    */
    BOUNTY_DATA* bounty = NULL;
    for ( bounty = first_bounty; bounty; bounty = bounty->next )
    {
        changed = FALSE;

        if ( !str_cmp( bounty->target, victim->name ) )
        {
            SET_STRING( bounty->target, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( bounty->placer, victim->name ) )
        {
            SET_STRING( bounty->placer, arg2 );
            changed = TRUE;
        }

        if ( changed ) bounty_save(bounty);
    }

    /*
        bank stuff
    */
    BANK_DATA* bank = NULL;

    for ( bank = first_bank; bank ; bank = bank->next )
    {
        changed = FALSE;

        if ( !str_cmp( bank->owner, victim->name ) )
        {
            SET_STRING( bank->owner, arg2 );
            changed = TRUE;
        }

        if ( changed ) save_bank( bank, true );
    }

    /*
        Lets do mail and terminal stuff too
    */
    for ( terminal = first_terminal; terminal; terminal = terminal->next )
    {
        changed = FALSE;
        for ( message = terminal->first_message; message; message = message->next )
        {
            if ( !str_cmp( victim->name, message->posted_by ) )
            {
                SET_STRING( message->posted_by, arg2 );
                changed = TRUE;
            }

            if ( !str_cmp( victim->name, message->recipient ) )
            {
                SET_STRING( message->recipient, arg2 );
                changed = TRUE;
            }
        }

        if ( changed )
            save_terminal( terminal );
    }

    for ( mail = first_mail; mail; mail = mail->next )
    {
        changed = FALSE;

        if ( !str_cmp( victim->name, mail->sender ) )
        {
            SET_STRING( mail->sender, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, mail->from_line ) )
        {
            SET_STRING( mail->from_line, arg2 );
            changed = TRUE;
        }

        if ( !str_cmp( victim->name, mail->recipient ) )
        {
            SET_STRING( mail->recipient, arg2 );
            changed = TRUE;
        }

        if ( changed )
            save_mail( mail );
    }

    /*
        Lets do homes now
    */
    for ( AREA_DATA* area = first_area; area; area = area->next )
    {
        ROOM_INDEX_DATA* room;
        for ( int vnum = area->min_vnum; vnum <= area->max_vnum; vnum++ )
        {
            room = get_room_index( vnum );
            if ( !room || !room->phome )
                continue;

            if ( room->phome->owner_id == victim->id )
            {
                SET_STRING( room->phome->owner, arg2 );
                save_room( room, true );
            }

            for ( RESIDENT_DATA* resident = room->phome->first_resident; resident; resident = resident->next )
            {
                if ( resident->plr_id == victim->id )
                {
                    if ( !str_cmp( resident->known_name, victim->name ) )
                    {
                        SET_STRING( resident->known_name, arg2 );
                        save_room( room, true );
                    }

                    if ( !str_cmp( resident->real_name, victim->name ) )
                    {
                        SET_STRING( resident->real_name, arg2 );
                        save_room( room, true );
                    }
                }
            }
        }
    }

    rename_dbase_sql( "thoughtdb", "owner", arg2, victim->name ); //rename think logs

    /*
        Don't forget accounts!
    */
    if ( victim->desc && victim->desc->account )
    {
        ACC_CHAR* ach = NULL;

        for ( acc = first_account; acc; acc = acc->next )
        {
            for ( ach = acc->first_char; ach; ach = ach->next )
            {
                if ( !str_cmp( ach->name, victim->name ) )
                {
                    SET_STRING( ach->name, arg2 );
                    account_save( acc, true );
                }
            }
        }
    }

    SET_STRING( victim->name, arg2 );
    remove( backname );
    /*
        Time to save to force the affects to take place
    */
    save_char_obj( victim, true );
    //    save_home( victim );

    ch_println( ch, "Character was renamed." );
    return;
}

CMDF do_listdir( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    DIR* dp;
    struct dirent* dentry;
    int count = 0, dircount = 0;
    snprintf( buf, MSL, "../%s", argument );

    if ( ( dp = opendir( buf ) ) == NULL )
    {
        ch_println( ch, "That directory does not exist" );
        return;
    }

    dentry = readdir( dp );
    ch_println( ch, "&RDirectory listing for: %s", buf );

    for ( dentry = readdir( dp ); dentry; dentry = readdir( dp ), count++ )
    {
        if ( dentry->d_name[0] == '.' )
        {
            dircount++;
            continue;
        }

        ch_println( ch, "&G  %s", dentry->d_name );
    }

    ch_println( ch, "&pTotal number of files: %d", count - dircount );
    closedir( dp );
}


