CMDF do_doas( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    DESCRIPTOR_DATA* orig = NULL;
    char arg[MIL];

    if ( IS_NPC( ch ) )
        return;

    if ( !ch->desc )
        return;

    argument = one_argument( argument, arg );

    if ( NULLSTR( argument ) || NULLSTR( arg ) )
    {
        send_to_char( "&zSyntax: &Cdoas <&wvictim&C> <&wcommand&C>", ch );
        return;
    }

    if ( ( victim = get_char_world( ch, arg ) ) == NULL || get_trust( victim ) >= get_trust( ch ) )
    {
        ch_println( ch, "&BN&zo such person in the game." );
        return;
    }

    ch_println( ch, "You switch bodies with %s momentarily", victim->name );
    orig = victim->desc;
    victim->desc = ch->desc;
    ch->desc = NULL;
    interpret( victim, argument, FALSE );
    ch->desc = victim->desc;
    victim->desc = orig;
    ch_println( ch, "You revert back to your own body" );
}

CMDF do_gfighting( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    DESCRIPTOR_DATA* d;
    char arg1[MIL], arg2[MIL];
    int low = 1, high = 105, count = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !NULLSTR( arg1 ) )
    {
        if ( arg1[0] == '\0' || arg2[0] == '\0' )
        {
            pager_println( ch, "&wSyntax:  gfighting | gfighting <low> <high> | gfighting <low> <high> mobs" );
            return;
        }

        low = atoi( arg1 );
        high = atoi( arg2 );
    }

    if ( low < 1 || high < low || low > high || high > 105 )
    {
        pager_println( ch, "&wInvalid level range." );
        return;
    }

    pager_println( ch, "&cGlobal conflicts:" );
    pager_println( ch, "&z%-12s | %-10s | %-12s [%5s] | %-20s [%5s]",
    "Player Name", "Levels", "Opponent", "NPC #", "Area Name", "VNUM" );
    pager_println( ch, "&c--------------------------------------------------------------------------------" );

    for ( d = first_descriptor; d; d = d->next )
    {
        /*
            How can someone be fighting and editing?
        */
        if ( ( IS_PLAYING( d ) || d->connected == CON_EDITING )
                && ( victim = d->character ) != NULL && !IS_NPC( victim )
                && victim->in_room && can_see( ch, victim )
                && victim->fighting && victim->top_level >= low && victim->top_level <= high )
        {
            pager_println( ch,
                          "&w%-12.12s &z| &C%3d &wvs &C%-3d &z| &w%-12.12s &z[&W%5d&z] &z| &w%-20.20s [%5d]",
                          victim->name, victim->top_level,
                          victim->fighting->who->top_level,
                          IS_NPC( victim->fighting->who ) ? victim->fighting->who->short_descr : victim->fighting->who->name,
                          IS_NPC( victim->fighting->who ) ? victim->fighting->who->pIndexData->vnum : 0,
                          victim->in_room->area->name, victim->in_room == NULL ? 0 : victim->in_room->vnum );
            count++;
        }
    }

    pager_println( ch, "\n&c%d conflicts located.", count );
    return;
}

