/* This is only required if you do not already have it, you need it for both loop and cycle */
char* number_sign( char* txt, int num )
{
    static char newstring[MIL];
    int i;

    if ( !txt )
        return "";

    newstring[0] = '\0';

    for ( i = 0; txt[i] != '\0'; i++ )
    {
        if ( txt[i] == '#' )
            strlcat( newstring, itoa( num ), MIL );
        else
            snprintf( newstring + strlen( newstring ), MIL - strlen( newstring ), "%c", txt[i] );
    }

    return newstring;
}

CMDF do_cycle( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL];
    int start, stop, x;
    int cnt = 0;

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg ) || NULLSTR( arg2 ) || NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Ccycle <&wfirst number&C> <&wlast number&C> <&wcommand&C>" );
        return;
    }

    start = atoi( arg );
    stop = atoi( arg2 );

    if ( start < 0 )
    {
        ch_println( ch, "You must start on a zero or higher." );
        return;
    }

    if ( stop <= start )
    {
        ch_println( ch,
                   "You must stop at a point higher than you've started. %d is %s than %d.",
                   stop, stop == start ? "equal to" : "less than", start );
        return;
    }

    if ( ( stop - start ) > 1001 && get_trust( ch ) < LEVEL_ADMIN )
    {
        ch_println( ch, "You're cycling too many times. Try 1000 or fewer." );
        return;
    }

    for ( x = start; x <= stop; x++ )
    {
        cnt++;
        interpret( ch, number_sign( argument, x ), FALSE );
    }

    ch_println( ch, "Finished running cycle %d times.", cnt );
}

