CMDF do_forcename( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Please specify a player in the game who you wish to force to select a new name." );
        return;
    }

    if ( ( victim = get_player_world( argument ) ) == NULL )
    {
        ch_println( ch, "That player isn't online currently." );
        return;
    }

    if ( get_trust( victim ) > LEVEL_HERO )
    {
        ch_println( ch, "You can only use this on mortals." );
        return;
    }

    xSET_BIT( victim->pcdata->flags, PCFLAG_NEWNAME );
    send_to_char( "&RYour character name is against our naming conventions and a staff member is\n"
        "&Rasking you to change it. &wRemember, names must fit into our in-character\n"
        "&Renvironment to maintain immersion. Please read HELP NAME for more, or reach out\n"
        "&Ron the &kimmchat&k channel if you have any questions.\n"
        "&WTo pick a new name, type &knewname <YOUR NEW NAME HERE>&k", victim );
    ch_println( ch, "%s will now be forced to select a new name.", victim->name );
    do_save( victim, "-noalert" );
}

CMDF do_newname( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], arg[MIL], oldname[MSL];

    if ( IS_NPC( ch ) || !has_pcflag( ch, PCFLAG_NEWNAME ) )
    {
        ch_println( ch, "&wHuh?" );
        return;
    }

    if ( argument[0] == '\0' || argument[0] == '@' )
    {
        ch_println( ch, "Please specify a valid name." );
        return;
    }

    argument = one_argument( argument, arg );
    snprintf( buf, MSL, "%s %s", ch->name, arg );
    snprintf( oldname, MSL, "%s", ch->name );
    do_pcrename( ch, buf );

    if ( !str_cmp( oldname, ch->name ) )
    {
        ch_println( ch, "&RThe name you chose was unacceptable. Please try again, this time be more careful." );
        return;
    }

    SET_STRING( ch->pcdata->title, ch->name );
    SET_STRING( ch->pcdata->pubtitle, ch->name );
    xREMOVE_BIT( ch->pcdata->flags, PCFLAG_NEWNAME );
    do_save( ch, "-noalert" );
    ch_println( ch, "You will now be known as '%s'. Thank you for your understanding.", ch->name );
}

