CMDF do_rfind( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char* argValue;
    ROOM_INDEX_DATA* room = NULL;
    int x = 0, cnt = 0, flag = -1;
    AREA_DATA* tarea;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Rfind what?" );
        return;
    }

    while ( true )
    {
        if ( !str_prefix( "flag:", arg ) )
        {
            argValue = arg + strlen( "flag:" );

            if ( ( flag = get_flag( argValue, room_flags ) ) == FLAG_UNDEFINED )
            {
                ch_println( ch, "Room flag '%s' not found.", argValue );
                return;
            }

            argument = one_argument( argument, arg );
        }
        else
        {
            break;
        }
    }

    for ( tarea = first_area; tarea; tarea = tarea->next )
    {
        for ( x = tarea->min_vnum; x <= tarea->max_vnum; x++ )
        {
            if ( ( room = get_room_index( x ) ) )
            {
                if ( flag > -1 && !xIS_SET( room->flags, flag ) )
                    continue;

                if ( strstr( stripclr( room->name ), arg ) )
                {
                    cnt++;
                    ch_println( ch, "{%15s}[%5d] %s", tarea->shortname, room->vnum, room->name );
                }
            }
        }
    }

    if ( cnt > 0 )
        ch_println( ch, "Found a total of %d matches.", cnt );
    else
        ch_println( ch, "Could not find any matches!" );
}



