CMDF do_setcyber( CHAR_DATA* ch, char* argument )
{
    char arg1 [MIL];
    char arg2 [MIL];
    char arg3 [MIL];
    //   char arg4 [MIL];
    CYBER_TYPE_DATA* cyber;
    CHAR_DATA* rch;
    //  CYBER_DATA* ch_cyber;
    AFFECT_DATA* paf;
    //    AFFECT_DATA* chpaf;
    sh_int loc;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Csetcyber <&wcyber name&C> <&wfield&C> <&wvalue&C>&w" );
        ch_println( ch, "&zSyntax: &Csetcyber <&wcyber name&C> create&w         " );
        ch_println( ch, "&zSyntax: &Csetcyber <&wcyber name&C> delete&w         " );
        ch_println( ch, "\n&zField being one of:" );
        ch_println( ch, "&C  longdesc category flags affect rmaffect level" );
        return;
    }

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    cyber = get_cyber( arg1 );

    if ( !str_cmp( arg2, "create" ) && cyber )
    {
        ch_println( ch, "That cyber type already exists!" );
        return;
    }
    else if ( !cyber && str_cmp( arg2, "create" ) )
    {
        ch_println( ch, "No such cyber type to edit." );
        return;
    }

    if ( !str_cmp( arg2, "create" ) )
    {
        CREATE( cyber, CYBER_TYPE_DATA, 1 );
        SET_STRING( cyber->name, arg1 );
        LINK( cyber, first_cyber, last_cyber, next, prev );
        ch_println( ch, "Created new cyber type '%s'.", cyber->name );
        save_cyber( cyber );
        return;
    }

    if ( !str_cmp( arg2, "affect" ) )
    {
        EXT_BV aff_bitvector;
        xCLEAR_BITS( aff_bitvector );
        int value = 0;
        argument = one_argument( argument, arg3 );
        if ( NULLSTR( arg3 ) )
        {
            ch_println( ch, "&zSyntax: &Csetcyber <&wcyber name&C> affect <&wfield&C> <&wvalue&C>&w" );
            ch_println( ch, "&zAffect Fields:" );
            ch_println( ch, "&Bnone        strength    dexterity   intelligence  wisdom       constitution" );
            ch_println( ch, "&Bsex         level       age         height        weight       force" );
            ch_println( ch, "&Bhit         move        credits     experience    armor        hitroll" );
            ch_println( ch, "&Bdamroll     save_para   save_rod    save_poison   save_breath  save_power" );
            ch_println( ch, "&Bcharisma    resistant   immune      susceptible   affected     luck" );
            return;
        }

        loc = get_atype( arg3 );
        if ( loc < 1 )
        {
            ch_println( ch, "Unknown field: %s", arg3 );
            return;
        }

        if ( loc == APPLY_AFFECT )
        {
            aff_bitvector = set_flags( ch, affect_flags, aff_bitvector, argument, true );
            value = 0;
            if ( xIS_EMPTY( aff_bitvector ) )
                return;
        }
        else if ( loc == APPLY_RESISTANT || loc == APPLY_IMMUNE || loc == APPLY_SUSCEPTIBLE )
        {
            const FLAG_INFO* ris_flag = flag_from_name( resistant_types, argument );
            if ( !ris_flag )
            {
                ch_println( ch, "Unknown flag: %s", argument );
                return;
            }
            value = ris_flag->flag;
        }
        else
        {
            if ( NULLSTR( argument ) )
            {
                ch_println( ch, "&zSyntax: &Csetcyber <&wcyber name&C> affect <&wfield&C> <&wvalue&C>&w" );
                return;
            }
            value = atoi( argument );
        }

        for ( rch = first_char; rch; rch = rch->next )
        {
            de_cyber_char( rch );
        }

        CREATE( paf, AFFECT_DATA, 1 );
        paf->type            = -1;
        paf->duration        = -1;
        paf->location        = loc;
        paf->modifier        = value;
        xCLEAR_BITS( paf->bitvector );
        xSET_BITS( paf->bitvector, aff_bitvector );
        paf->next = NULL;
        LINK( paf, cyber->first_affect, cyber->last_affect, next, prev );

        for ( rch = first_char; rch; rch = rch->next )
        {
            re_cyber_char( rch );
        }

        ch_println( ch, "Done." );
        save_cyber( cyber );
        return;
    }

    if ( !str_cmp( arg2, "rmaffect" ) )
    {
        sh_int count;

        if ( !argument || argument[0] == '\0' )
        {
            ch_println( ch, "&zSyntax: &Csetcyber <&wcyber type&C> rmaffect <&waffect &z#&C>&w" );
            return;
        }

        loc = atoi( argument );

        if ( loc < 1 )
        {
            ch_println( ch, "Invalid number." );
            return;
        }

        count = 0;

        for ( rch = first_char; rch; rch = rch->next )
            de_cyber_char( rch );

        for ( paf = cyber->first_affect; paf; paf = paf->next )
        {
            if ( ++count == loc )
            {
                UNLINK( paf, cyber->first_affect, cyber->last_affect, next, prev );
                FREE_STRUCT_NORET( paf, affect_fields );
                ch_println( ch, "Removed." );
                return;
            }
        }

        for ( rch = first_char; rch; rch = rch->next )
            re_cyber_char( rch );

        save_cyber( cyber );
    }

    if ( !str_cmp( arg2, "category" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Csetcyber <&wcyber type&C> category <&wcategory name&C>&w" );
            return;
        }

        SET_STRING( cyber->category, argument );
        ch_println( ch, "Cyber type '%s' category set to '%s'.", cyber->name, cyber->category );
        save_cyber( cyber );
        return;
    }

    if ( !str_cmp( arg2, "level" ) )
    {
        if ( NULLSTR( argument ) || !is_number( argument ) )
        {
            ch_println( ch, "&zSyntax: &Csetcyber <&wcyber type&C> level <&wlevel within cyber category&C>&w" );
            return;
        }

        cyber->level = atoi( argument );
        ch_println( ch, "Cyber type '%s' level set to '%d'.", cyber->name, cyber->level );
        save_cyber( cyber );
        return;
    }

    if ( !str_cmp( arg2, "longdesc" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Csetcyber <&wcyber type&C> longdesc <&wdesc to show on examine/diagnose&C>&w" );
            return;
        }

        SET_STRING( cyber->longdesc, argument );
        ch_println( ch, "Cyber type '%s' longdesc set to '%s'.", cyber->name, cyber->longdesc );
        save_cyber( cyber );
        return;
    }

    if ( !str_cmp( arg2, "flags" ) )
    {
        cyber->flags = set_flags( ch, cyber_flags, cyber->flags, argument, true );
        save_cyber( cyber );
        return;
    }

    ch_println( ch, "&zSet which field?\n"
                "&B  affect rmaffect category level longdesc flags" );
    return;
}

