RACE_DATA * create_new_race( char* argument )
{
    int i = 0, j = 0;
    RACE_DATA *race = NULL;
    CREATE( race, RACE_DATA, 1 );
    if ( !NULLSTR( argument ) )
        argument[0] = UPPER( argument[0] );

    SET_STRING( race->race_name, argument ); //snprintf( race->race_name, 17, "%-.16s", argument );
    race->id = 0;
    race->str_plus = 0;
    race->dex_plus = 0;
    race->wis_plus = 0;
    race->int_plus = 0;
    race->con_plus = 0;
    race->cha_plus = 0;
    race->lck_plus = 0;
    race->frc_plus = 0;
    race->hit = 0;
    race->mana = 0;
    race->price = 0;
    race->deposit = 0;
    race->size = 0;
    race->max_feat = 0;
    race->min_feat = 0;
    race->acmod = 0;
    race->race_count = 0;
    race->app_only = FALSE;
    SET_STRING( race->appaccepted, "" );
    xCLEAR_BITS( race->flags );
    xCLEAR_BITS( race->specflags );
    race->era = 0;
    SET_STRING( race->forceclan, "" );
    SET_STRING( race->shortdesc, race->race_name );
    SET_STRING( race->move_message, NULL );
    SET_STRING( race->default_description, "" );
    SET_STRING( race->default_history, "" );
    xCLEAR_BITS( race->affected );
    race->language = 0;

    for ( i = 0; i < 12; i++ )
        race->ability[i] = 0;

    for ( i = 0; i < 12; i++ )
        for ( j = 0; j < 12; j++ )
            race->main_table[i][j] = 0;
    save_race(race);
    LINK(race, first_race, last_race, next, prev);
    return race;
}

char*   skill_color ( int skill )
// Gral levels now static per race
//   &b  Crap skills 0-30
//   &g  Base skills 31-70
//   &Y  Useful skills 71-129
//  &R  Pwn skills 130-150

{
