void do_droidmodel( CHAR_DATA* ch, char* argument )
{
    DROID_MODEL_DATA* model;
    char arg1[MIL], arg2[MIL];
    argument = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) || ( NULLSTR ( argument ) && str_cmp( arg1, "list" ) ) )
    {
        ch_println( ch, "&zSyntax: &Cdroidmodel create [name]" );
        ch_println( ch, "&z        &Cdroidmodel enable/disable <&wmodel&C>" );
        ch_println( ch, "&z        &Cdroidmodel rename <&wmodel number&C> [new name]" );
        ch_println( ch, "&z        &Cdroidmodel list" );
        return;
    }

    if ( !str_cmp( arg1, "list" ) )
    {
        if ( !first_droid_model )
        {
            ch_println( ch, "No droid models have been created yet." );
            return;
        }

        ch_println( ch, "&zThe following droid models have been created:" );
        for ( model = first_droid_model; model; model = model->next )
            ch_println( ch, "&z(&C%3d&z) &C%s%s", model->id, model->name, model->enabled ? "" : "&R*" );
        ch_println( ch, "\n&R* &zModel is currently disabled" );
        return;
    }

    if ( !str_cmp( arg1, "create" ) )
    {
       /* int new_id = 1;
        for ( model = first_droid_model; model; model = model->next )
        {
            if ( !str_cmp( model->name, argument ) )
            {
                ch_println( ch, "&zModel already exists." );
                return;
            }

            if ( model->id >= new_id )
                new_id = model->id + 1;
        }
*/
        model = NULL;
        CREATE( model, DROID_MODEL_DATA, 1 );
        SET_STRING( model->name, stripclr( argument ) );
        model->id = 0; //new_id;
        model->enabled = true;
        LINK( model, first_droid_model, last_droid_model, next, prev );
        ch_println( ch, "&zNew droid model successfully created." );
        save_droidmodel( model );
        return;
    }

    if ( !str_cmp( arg1, "enable" ) || !str_cmp( arg1, "disable" ) )
    {
        for ( model = first_droid_model; model; model = model->next )
            if ( ( is_number( argument ) && atoi( argument ) == model->id ) || !str_cmp( model->name, argument ) )
                break;

        if (!model)
        {
            ch_println( ch, "&zCould not find that droid model." );
            return;  
        }

        if ( ( !str_cmp( arg1, "enable" ) && model->enabled ) || ( !str_cmp( arg1, "disable" ) && !model->enabled ) )
        {
            ch_println( ch, "&zDroid model &C%s&z is already &C%s&z.", model->name, model->enabled ? "enabled" : "disabled" );
            return;
        }        

        model->enabled = !model->enabled;
        ch_println( ch, "&zDroid model &C%s&z is now &C%s&z.", model->name, model->enabled ? "enabled" : "disabled" );
        save_droidmodel( model );
        return;
    }

    if ( !str_cmp( arg1, "rename" ) )
    {
        argument = one_argument( argument, arg2 );

        if ( !is_number( arg2 ) )
        {
            ch_println( ch, "&zYou must specify the model number of the droid model you wish to rename." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zYou must provide a new name for the droid model!" );
            return;
        }

        for ( model = first_droid_model; model; model = model->next )
            if ( atoi( arg2 ) == model->id )
                break;

        if (!model)
        {
            ch_println( ch, "&zCould not find that droid model." );
            return;  
        }

        SET_STRING( model->name, stripclr( argument ) );
        ch_println( ch, "&zDroid model renamed to &C%s&z.", model->name );
        save_droidmodel( model );
        return;
    }

    ch_println( ch, "&zSyntax: &Cdroidmodel create [name]" );
    ch_println( ch, "&z        &Cdroidmodel enable/disable <&wmodel&C>" );
    ch_println( ch, "&z        &Cdroidmodel rename <&wmodel number&C> [new name]" );
    ch_println( ch, "&z        &Cdroidmodel list" );
    return;
}

