int compare_race_cost( RACE_DATA** r1p, RACE_DATA** r2p )
{
    RACE_DATA* r1 = ( *r1p );
    RACE_DATA* r2 = ( *r2p );

    if ( !r1 && !r2 )
        return 0;

    if ( !r1 && r2 )
        return 1;

    if ( !r2 && r1 )
        return -1;

    // Consider app-only races to be higher than any non-app-only ones
    if ( r1->app_only && r2->app_only )
        return 0;

    if ( r1->app_only && !r2->app_only )
        return 1;

    if ( !r1->app_only && r2->app_only )
        return -1;

    // Sort by total price first
    if ( r1->price + r1->deposit != r2->price + r2->deposit )
        return ( r1->price + r1->deposit ) - ( r2->price + r2->deposit );

    // If total price is equal, sort by the nonrefundable part of price
    return r1->price - r2->price;
}

// Compare races by cost, but fall back to comparing by name if they're otherwise equal
int compare_races( RACE_DATA** r1p, RACE_DATA** r2p )
{
    RACE_DATA* r1 = ( *r1p );
    RACE_DATA* r2 = ( *r2p );
    int point_cmp = compare_race_cost( r1p, r2p );

    if ( point_cmp != 0 )
        return point_cmp;

    // If all else is equal, just sort alphabetically
    return strcasecmp( r1->race_name, r2->race_name );
}

bool can_see_race( CHAR_DATA* ch, RACE_DATA* race )
{
    if ( !ch )
        return false;

    if ( has_pcflag( ch, PCFLAG_CG ) )
        return xIS_SET( race->flags, RFLAG_CG );

    if ( xIS_SET( race->flags, RFLAG_HIDEMORTS ) )
    {
        if ( is_name( ch->name, race->appaccepted ) )
            return true;

        if ( ch->desc && ch->desc->account && xIS_SET( race->flags, RFLAG_VONG ) && xIS_SET( ch->desc->account->flags, ACC_VONG ) )
            return true;

        if ( ch->desc && ch->desc->account && xIS_SET( race->flags, RFLAG_CHISS ) && xIS_SET( ch->desc->account->flags, ACC_CHISS ) )
            return true;

        if ( get_trust( ch ) >= 103 )
            return true;

        return false;
    }

    return true;
}

void do_showrace( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL];
    RACE_DATA* race, *last_race;
    RACE_DATA* sorted_races[1000];
    int col, ra, i, displayed_race_count, same_price_ct, races_per_line;
    int average, weightedaverage, maxweightedaverage;
    char tmp[MSL];
    char buf[MSL];
    bool list_imm_mode = false, has_match = false;
    set_pager_color( AT_PLAIN, ch );
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( !str_cmp( arg2, "class" ) )
    {
        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cshowrace <&wrace&C> class <&wclass name&C>" );
            return;
        }
        else
        {
            for ( i = 0; i < MAX_ABILITY; i++ )
            {
                if ( i == 5 || i == 7 )
                    continue;

                if ( !str_cmp( argument, flag_value_name( ability_name, i ) ) )
                    has_match = true;
            }
            if ( !has_match )
            {
                ch_println( ch, "&RThat's not a valid class name." );
                return;
            }
        }
    }

    // List all races when no arguments are given
    if ( NULLSTR( arg1 ) )
    {
        list_imm_mode = get_trust( ch ) >= sysdata.log_level;
        races_per_line = 4;

        if ( list_imm_mode )
            races_per_line = 3;

        // Collect the races this character is allowed to see
        displayed_race_count = 0;

        for ( RACE_DATA *allrace = first_race; allrace; allrace = allrace->next )
        {
            if ( !can_see_race( ch, allrace ) )
                continue;

            if ( !str_cmp( allrace->race_name, "unused" ) || !str_cmp( allrace->race_name, "" ) ) // GRAL Gathorn hates seeing unused
                continue;

            sorted_races[displayed_race_count++] = allrace;
        }

        // ...Then sort them by cost
        qsort( &sorted_races[0], displayed_race_count, sizeof( RACE_DATA* ), ( int( * )( const void*, const void* ) ) compare_races );
        send_to_pager( "&zFor races shown in &Bblue&z, the &Cpoints &zand &cdeposit &zfields tell you how much a race\n", ch );
        send_to_pager( "will cost. Points are non-refundable, and your deposit is how many points you\n", ch );
        send_to_pager( "pay for the race which you receive back upon your character's death, unless you\n", ch );
        send_to_pager( "abuse your race and have it removed.\n", ch );
        send_to_pager( "\n", ch );
        send_to_pager( "&zRaces shown in &Clight blue&z are free, making them ideal for players who are\n", ch );
        send_to_pager( "either new or have not earned points on their account. To play as an app-only\n", ch );
        send_to_pager( "race, shown in &ggreen&z, you must submit a player app. (&CHELP APPLICATION&z)\n", ch );
        send_to_pager( "\n", ch );

        if ( get_trust( ch ) >= 103 )
            send_to_pager( "&zRaces shown in &Rred&z are hidden from morts.\n\n", ch );

        if ( list_imm_mode )
            send_to_pager( "&CPoints&z/&cDep.   &CRace #&z(&WEra&z): &CRaces\n", ch );
        else
            send_to_pager( "&CPoints&z/&cDep.   &CRaces\n", ch );

        send_to_pager( "&z-------------------------------------------------------------------------", ch );
        same_price_ct = 0;
        last_race = NULL;

        for ( i = 0; i < displayed_race_count; i++ )
        {
            race = sorted_races[i];

            // If first race in its price bucket, show price
            if ( compare_race_cost( &last_race, &race ) != 0 )
            {
                if ( race->app_only )
                    pager_printf( ch, "\n&z[&CApp Only &z]: ", ch );
                else
                    pager_printf( ch, "\n&z[&C%4d&z/&c%4d&z]: ", race->price, race->deposit );

                same_price_ct = 0;
            }
            else if ( last_race != NULL && same_price_ct % races_per_line == 0 )
                pager_printf( ch, "\n             " );

            // When showing to an imm, include race numbers and era restrictions
            if ( list_imm_mode )
                for ( RACE_DATA *allrace = first_race; allrace; allrace = allrace->next ) {
                    if ( allrace == race )
                    {
                        pager_printf( ch, " &C%3d", race->id );

                        if ( race->era > 0 )
                            pager_printf( ch, "&z(&W%d&z):", race->era );
                        else
                            pager_printf( ch, "&z( ):" );
                    }
                }
            if ( xIS_SET( race->flags, RFLAG_HIDEMORTS ) )
                pager_printf( ch, "&R" );
            else if ( race->app_only )
                pager_printf( ch, "&g" );
            else if ( race->price > 0 || race->deposit > 0 )
                pager_printf( ch, "&B" );
            else
                pager_printf( ch, "&C" );

            pager_printf( ch, " %-14s", race->race_name );
            same_price_ct++;
            last_race = race;
        }

        send_to_pager( "\n&z-------------------------------------------------------------------------\n", ch );
