CMDF do_showskincolor( CHAR_DATA* ch, char* argument )
{
    RACE_DATA * drace;
    char buf[MSL];

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cshowskincolor <&wrace&C>&w" );

        if ( IS_IMMORTAL( ch ) )
            drace = NULL;
        else
            return;
    }
    else
    {
        drace = get_race_by_name( argument );

        if ( drace == NULL || !can_see_race( ch, drace ) ) 
        {
            ch_println( ch, "No such race." );
            return;
        }
    }

    int i = 0;
    int clr_code_len = 0;
    int col = 0;
    strlcpy( buf, "", MSL );

    while ( true )
    {
        if ( skincolors[i].id == -1 )
            break;

        if ( drace == NULL || xIS_SET( drace->skincolors, skincolors[i].id ) )
        {
            clr_code_len = strlen( skincolors[i].display_name ) - strlen( stripclr( skincolors[i].display_name ) );
            strlcat( buf, skincolors[i].display_name, MSL );

            // Add padding until we're at 20 characters
            while ( ( strlen( buf ) - clr_code_len ) % 20 )
                strlcat( buf, " ", MSL );

            col++;
        }

        if ( col == 3 )
        {
            ch_println( ch, "   %s", buf );
            strlcpy( buf, "", MSL );
            col = 0;
        }

        i++;
    }

    if ( col > 0 )
        ch_println( ch, "   %s", buf );

    ch_println( ch, "", buf );
    return;
}
/*  Pfreload: allows you to "reload" a pfile so you can edit it in shell without making a player log out
    The idea was taken from another snippet, but I pretty much had to write this one myself
    This is written for FotE, but should work in any SMAUG based mud (i think) -->Keberus
*/
void do_pfreload( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];

    if ( IS_NPC( ch ) )
        return;

    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Reload who?" );
        return;
    }

    if ( !( victim = get_char_world( ch, arg ) ) )
    {
        ch_println( ch, "They are not here." );
        return;
    }

    if ( get_trust( victim ) > get_trust( ch ) )
    {
        ch_println( ch, "You can't reload someone who's a higher level!" );
        return;
    }

    if ( player_exist( victim->name ) )
    {
        DESCRIPTOR_DATA* d;
        char name[MSL];
        //        char buf[MSL];
        ROOM_INDEX_DATA* in_room;
        bool Load;
        d = NULL;
        d = victim->desc;
        snprintf( name, MSL, "%s", victim->name );
        in_room = victim->in_room;
        /*
            clear descriptor pointer to get rid of bug message in log
        */
        victim->desc = NULL;
        extract_char( victim );
        d->character = NULL;
        Load = load_char_obj( d, name );
        victim = d->character;
        victim->desc = d;
        victim->timer = 0;
        /*
            Insert in the char_list
        */
        LINK( d->character, first_char, last_char, next, prev );
        hashset_add( valid_chars, d->character );
        char_to_room( victim, in_room );

        if ( Load )
        {
            ch_println( victim, "Your pfile has been reloaded." );
            ch_println( ch, "Their pfile has been reloaded." );
        }
        else
        {
            ch_println( ch, "Hrmm bug, it didnt work." );
            return;
        }
    }
    else
        ch_println( ch, "They have to have a pfile before you can load it." );

    return;
}
CMDF do_setcookie( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    char arg1 [MIL];
    char arg2 [MIL];
    COOKIE_DATA* cookie = NULL;

    if ( NULLSTR( argument ) )
    {
        // setcookie arg1 arg2 argument
        ch_println( ch, "&zSyntax: &Csetcookie <&wremove&z/&wadd&z/&wpremove&z/&wpadd&C> <&wcookie&z/&wplayer name&C> (&wpcookie&C)&w" );
        return;
    }

    argument = one_argument( argument, arg1 );

    if ( str_cmp( arg1, "add" ) && str_cmp( arg1, "remove" ) && str_cmp( arg1, "premove" ) && str_cmp( arg1, "padd" ) )
    {
        ch_println( ch, "&zSyntax: &Csetcookie <&wremove&z/&wadd&z/&wpremove&z/&wpadd&C> <&wcookie&z/&wplayer name&C> (&wpcookie&C)&w" );
        return;
    }

    if ( !str_cmp( arg1, "add" ) )
    {
        for ( cookie = first_global_cookie; cookie; cookie = cookie->next )
            if ( !str_cmp( cookie->name, argument ) )
                return;

        CREATE( cookie, COOKIE_DATA, 1 );
        SET_STRING( cookie->name, argument );
        LINK( cookie, first_global_cookie, last_global_cookie, next, prev );
        cookie_save( cookie );
        ch_println( ch, "&RGlobal cookie added." );
        return;
    }

    if ( !str_cmp( arg1, "remove" ) )
    {
        for ( cookie = first_global_cookie; cookie; cookie = cookie->next )
            if ( !str_cmp( cookie->name, argument ) )
                break;

        if ( !cookie )
            return;

        delete_sql_row_by_id( DB_TABLE_COOKIES, cookie->id );
        UNLINK( cookie, first_global_cookie, last_global_cookie, next, prev );
        FREE_STRUCT_NORET( cookie, cookie_fields );
        ch_println( ch, "&RGlobal cookie removed." );
        return;
    }

    if ( !str_cmp( arg1, "padd" ) )
    {
        argument = one_argument( argument, arg2 );

        if ( ( victim = get_char_world( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "&RNo such character." );
            return;
        }

        for ( cookie = victim->first_cookie; cookie; cookie = cookie->next )
            if ( !str_cmp( cookie->name, argument ) )
                return;

        CREATE( cookie, COOKIE_DATA, 1 );
        SET_STRING( cookie->name, argument );
        LINK( cookie, victim->first_cookie, victim->last_cookie, next, prev );
        save_char_obj( victim, true );
        ch_println( ch, "&RPlayer cookie added." );
        return;
    }

    if ( !str_cmp( arg1, "premove" ) )
    {
        argument = one_argument( argument, arg2 );

        if ( ( victim = get_char_world( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "&RNo such character." );
            return;
        }

        for ( cookie = victim->first_cookie; cookie; cookie = cookie->next )
            if ( !str_cmp( cookie->name, argument ) )
                break;

        if ( !cookie )
            return;

        UNLINK( cookie, victim->first_cookie, victim->last_cookie, next, prev );
        FREE_STRUCT_NORET( cookie, cookie_fields );
        save_char_obj( victim, true );
        ch_println( ch, "&RPlayer cookie removed." );
        return;
    }

    return;
}

