CMDF do_fixpassword( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    victim = get_char_world( ch, argument );

    if ( victim )
    {
        if ( !victim->pcdata->oldpwd || victim->pcdata->oldpwd[0] == '\0' )
        {
            ch_println( ch, "They don't have an old password, try mset <name> password <newpass> instead." );
            return;
        }

        char* pwdnew = new_password( victim->pcdata->oldpwd );
        SET_STRING( victim->pcdata->pwd, pwdnew );
        xREMOVE_BIT( victim->pcdata->flags, PCFLAG_SHA256 );
        ch_println( victim, "Your password has been reset, please confirm that it is working and let us know." );
        ch_println( ch, "New password has been replaced with old password!" );
        do_save( victim, "-noalert" );
    }
    else
    {
        ch_println( ch, "No such player logged on." );
        return;
    }

    return;
}

/*
    Author: Sanshiro
    Spec:   Sends a message to all members of a clan.
*/
CMDF do_commandmessage( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL];
    CLAN_DATA* clan = NULL;
    DESCRIPTOR_DATA* d = NULL;
    int i = 0;

    if ( !IS_IMMORTAL( ch ) )
    {
        send_to_char( "&wYou must be an Immortal to do that. \n", ch );
        return;
    }

    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        send_to_char( "&wUsage: commandmessage <clan> <message>\n", ch );
        return;
    }

    if ( ( clan = get_clan( arg ) ) == NULL )
    {
        send_to_char( "This clan doesn't exist.\n", ch );
        return;
    }

    snprintf( buf, MSL, "%s\n", argument );
    ch_printf( ch, "&wBroadcasting to &C%s:&w  %s", clan->name, buf );

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( !d->character )
            continue;

        if ( ( !d->character->pcdata->clan || d->character->pcdata->clan != clan ) || get_comlink( d->character ) == NULL )
            continue;

        if ( xIS_SET( d->character->deaf, CHANNEL_CLAN ) )
            continue;

        if ( d->character->in_room && xIS_SET( d->character->in_room->flags, ROOM_COMMSHIELD ) )
            continue;

        send_to_char( buf, d->character );
        i++;
    }

    ch_println( ch, "&C%d&w members got the message.", i );
    return;
}
