// Wipe out all saved state which is player-generated to prepare for a new timeline
CMDF do_newtimeline( CHAR_DATA* ch, char* argument )
{
    char buf[MIL], updatequery[MSL * 2];
    int cameras = 0, securedRooms = 0, vendors = 0, homes = 0, cnt = 0, lockers = 0, rval;
    ROOM_INDEX_DATA* room = NULL;
    OBJ_DATA* obj = NULL;
    CHAR_DATA* victim = NULL, *next_victim = NULL;
    TERMINAL_DATA* terminal = NULL;
    MESSAGE_DATA* message = NULL, *next_message = NULL;
    LOCKER_DATA* locker = NULL, *next_locker = NULL;
    MAIL_DATA* mail = NULL, *next_mail = NULL;
    VENDOR_DATA* vendor = NULL, *next_vendor = NULL;
    SHIP_DATA* ship = NULL, *next_ship = NULL;

    if ( str_cmp( argument, "wipe all saved state" ) )
    {
        ch_println( ch, "&RWARNING: This command will delete all saved player-generated state from this"
                   "timeline. You have to confirm with a very specific message to go through with it:\n"
                   "&zSyntax: &Cnewtimeline wipe all saved state\n"
                   "\n"
                   "&YEnsure you have the log channel enabled, as output will be sent there.\n" );
        return;
    }

    lognormal( "Newtimeline: Killing all mortals..." );
    for ( victim = first_char; victim; victim = next_victim )
    {
        next_victim = victim->next;

        if ( IS_NPC( victim ) )
            continue;

        if ( IS_IMMORTAL( victim ) )
            continue;

        set_cur_char( victim );
        raw_kill( ch, victim );
    }

    snprintf( buf, MIL, "toplevel < 101" );
    if ( ( rval = sql_count( DB_TABLE_PLAYERS, buf, &cnt ) ) != E_LOTJ_SUCCESS )
        bug( "%s: error %d (%s) when trying to check players count", FUNC, rval, lotj_strerror(rval) );
    else
    {
        snprintf( updatequery, (MSL * 2), "DELETE FROM %s WHERE toplevel < 101", DB_TABLE_PLAYERS );
        query_db2( updatequery, NULL, NULL );
        lognormal( "Killed %d players", cnt );
        reset_sql_id_seq( DB_TABLE_PLAYERS );
    }

    ACC_CHAR* ach = NULL, *ach_next = NULL;
    for ( ACCOUNT_DATA* acc = first_account; acc; acc = acc->next )
    {
        for ( ach = acc->first_char; ach; ach = ach_next )
        {
            ach_next = ach->next;
            if ( NULLSTR( ach->name ) || !player_exist( ach->name ) )
            {
                UNLINK( ach, acc->first_char, acc->last_char, next, prev );
                FREE_STRUCT_NORET( ach, acc_char_fields );
                account_save( acc, true );
            }
        }
    }

    lognormal( "Newtimeline: Cleaning areas..." );
    for ( AREA_DATA* area = first_area; area; area = area->next )
    {
        cameras = 0;
        securedRooms = 0;
        vendors = 0;
        homes = 0;

        for ( int rvnum = area->min_vnum; rvnum <= area->max_vnum; rvnum++ )
        {
            room = get_room_index( rvnum );

            if ( room )
            {
                if ( xIS_SET( room->flags, ROOM_CAMERA ) )
                {
                    cameras++;
                    xREMOVE_BIT( room->flags, ROOM_CAMERA );
                }

                if ( xIS_SET( room->flags, ROOM_SECURITY ) )
                {
                    securedRooms++;
                    xREMOVE_BIT( room->flags, ROOM_SECURITY );
                    room->security_rating = 0;
                }

                if ( xIS_SET( room->flags, ROOM_SAVEEQ ) )
                {
                    while ( ( obj = room->first_content ) != NULL )
                        extract_obj( obj );
                }

                if ( xIS_SET( room->flags, ROOM_VENDOR ) )
                {
                    vendors++;
                    reset_vendor_room( room );
                }

                // Reset both owned and empty homes in case any descs are leftover
                if ( xIS_SET( room->flags, ROOM_PLR_HOME ) || xIS_SET( room->flags, ROOM_EMPTY_HOME ) )
                {
                    homes++;
                    reset_home( room, room->phome );
                }
            }
        }

        if ( cameras > 0 || securedRooms > 0 || vendors > 0 || homes > 0 )
        {
            lognormal( "Saving %s after resetting: %d cameras, %d secured rooms, %d homes",
                       area->shortname, cameras, securedRooms, homes );
            save_area( area, true, false );
        }
    }

    lognormal( "Newtimeline: Deleting lockers..." );
    // Delete the lockers that are loaded into memory
    for ( locker = first_locker; locker; locker = next_locker )
    {
        next_locker = locker->next;
        delete_locker( locker );
        lockers++;
    }

    cnt = 0;

    // Then delete the rest
    if ( ( rval = sql_count( DB_TABLE_LOCKERS, NULL, &cnt ) ) != E_LOTJ_SUCCESS )
        bug( "%s: error %d (%s) when trying to check lockers count", FUNC, rval, lotj_strerror(rval) );
    else
    {
        truncate_sql_table( DB_TABLE_LOCKERS );
        reset_sql_id_seq( DB_TABLE_LOCKERS );
        lockers += cnt;
        lognormal( "Destroyed %d lockers", lockers );
    }

    vendors = 0, cnt = 0;
    lognormal( "Newtimeline: Deleting vendors..." );
    // Delete the vendors that are loaded into memory
    for ( vendor = first_vendor; vendor; vendor = next_vendor )
    {
        next_vendor = vendor->next;
        delete_vendor( vendor );
        vendors++;
    }

    // Then delete the rest
    if ( ( rval = sql_count( DB_TABLE_VENDORS, NULL, &cnt ) ) != E_LOTJ_SUCCESS )
        bug( "%s: error %d (%s) when trying to check vendors count", FUNC, rval, lotj_strerror(rval) );
    else
    {
        truncate_sql_table( DB_TABLE_VENDORS );
        reset_sql_id_seq( DB_TABLE_VENDORS );
        vendors += cnt;
        lognormal( "Destroyed %d vendors", vendors );
    }


    lognormal( "Newtimeline: Resetting turbolift security..." );

    for ( TURBOLIFT_DATA* lift = first_turbolift; lift; lift = lift->next )
    {
        if ( lift->security_rating > 0 )
        {
            lift->security_rating = 0;
            save_turbolift( lift );
        }
    }

    lognormal( "Newtimeline: Blowing up all ships..." );

    cnt = 0;
    for ( ship = first_ship; ship; ship = next_ship )
    {
        if ( ship_extracted( ship ) )
        {
            next_ship = first_ship;
            continue;
        }
        next_ship = ship->next;

        if ( xIS_SET( ship->flags, SHIP_NODELETE ) || xIS_SET( ship->flags, SHIP_LEGENDARY ) || xIS_SET( ship->flags, SHIP_INVINCIBLE )  || xIS_SET( ship->flags, SHIP_NO_SELFD ) || xIS_SET( ship->flags, SHIP_TRAFFIC ) || xIS_SET( ship->flags, SHIP_SIMULATOR ) )
        {
            transship( ship, ROOM_LIMBO_SHIPYARD );
            continue;
        }

        if ( is_pirate( ship ) || is_public(ship) )
        {
            transship( ship, ROOM_LIMBO_SHIPYARD );
            continue;
        }

        delete_ship( ship );
        cnt++;
    }
    lognormal( "Deleted %d ships", cnt );

    cnt = 0;
    for ( ship = first_drydock; ship; ship = next_ship )
    {
        if ( ship_extracted( ship ) )
        {
            next_ship = first_drydock;
            continue;
        }
        next_ship = ship->next;
        delete_ship( ship );
        cnt++;
    }

    lognormal( "Queued %d drydocked ships for deletion", cnt );

    lognormal( "Newtimeline: Closing all bank accounts..." );
    do_bank( ch, "closeall now" );
    lognormal( "Newtimeline: Resetting max player counter..." );
    do_cset( ch, "highplayers 0" ); //reset max player counter
    lognormal( "Newtimeline: Resetting message terminals..." );
    for ( terminal = first_terminal; terminal; terminal = terminal->next )
    {
        if ( terminal->min_post_level >= LEVEL_RPC || terminal->min_read_level >= LEVEL_RPC )
            continue;

        message = NULL;
        next_message = NULL;

        for ( message = terminal->first_message; message; message = next_message )
        {
            next_message = message->next;
            delete_message( message );
        }
    }
    lognormal( "Newtimeline: Resetting mail..." );
    for ( mail = first_mail; mail; mail = next_mail )
    {
        next_mail = mail->next;
        delete_mail( mail );
    }
    do_cset( ch, "tlstartdate now" ); // set the timeline start date
    sysdata.pointsondeath = TRUE;
    lognormal( "Newtimeline complete." );
}

/* Allows adding, removing, or changing typos and substitutions for the autoformat system. */
CMDF do_autocorrect( CHAR_DATA* ch, const char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cautocorrect <&woption&C> [typo] [substitution]" );
        ch_println( ch, "&z        &Cautocorrect list <&wstarting letter/all&C>" );
        ch_println( ch, "\n&zOptions: &Cadd&z, &Cdelete&z, &Cedit" );
        return;
    }

    char arg[MIL], arg2[MIL];
    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );

    if ( !str_cmp( arg, "list" ) )
    {
        if ( NULLSTR( arg2 ) || ( str_cmp( arg2, "all" ) && (int) strlen( arg2 ) != 1 ) || !NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cautocorrect list <&wstarting letter/all&C>" );
            ch_println( ch, "&ze.g., \"&Cautocorrect list A&z\"" );
            return;
        }

        bool found_any = false;
        bool list_all = !str_cmp( arg2, "all" );
        char list_ltr = tolower( arg2[0] );
        ch_println( ch, "&z%-25s %-25s", "Typo", "Correction" );
        ch_println( ch, "&z--------------------------------------------------------------------------------" );
        for ( AUTOCORRECT_DATA* autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
            if ( list_all || tolower(autocorrect->typo[0]) == list_ltr )
            {
                ch_println( ch, "&R%-25s &C%-25s", autocorrect->typo, autocorrect->correction );
                found_any = true;
            }

        if ( !first_autocorrect || !found_any )
            ch_println( ch, "&R%-25s &C%-25s", "None", "None" );
        return;
    }
    else if ( !str_cmp( arg, "add" ) || !str_cmp( arg, "create" ) )
    {
        if ( NULLSTR( arg2 ) || NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cautocorrect add [typo] [substitution]" );
            return;
        }
        for ( AUTOCORRECT_DATA* autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
        {
            if ( autocorrect && strcmp( arg2, autocorrect->typo ) == 0 )
            {
                ch_println( ch, "&zFailed: &R%s&z is already being corrected to &C%s&z.", autocorrect->typo, autocorrect->correction );
                return;
            }
            else if ( autocorrect && strcmp( arg2, autocorrect->correction ) == 0 )
            {
                ch_println( ch, "&zFailed: &R%s&z is already considered a correction for the word &R%s&z.", autocorrect->correction, autocorrect->typo );
                return;
            }
        }

        AUTOCORRECT_DATA *new_autocorrect = NULL;
        CREATE( new_autocorrect, AUTOCORRECT_DATA, 1 );
        SET_STRING( new_autocorrect->typo, arg2 );
        SET_STRING( new_autocorrect->correction, argument );
        LINK_SORT_NAME( new_autocorrect, AUTOCORRECT_DATA, first_autocorrect, last_autocorrect, next, prev, typo );
        save_autocorrect(new_autocorrect);
        ch_println( ch, "&zSucceeded: &R%s&z is now correcting to &C%s&z.", new_autocorrect->typo, new_autocorrect->correction );
        return;
    }
    else if ( !str_cmp( arg, "delete" ) || !str_cmp( arg, "remove" ) )
    {
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Cautocorrect delete [typo]" );
            return;
        }
        AUTOCORRECT_DATA* autocorrect = NULL;
        for ( autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
            if ( autocorrect && strcmp( arg2, autocorrect->typo ) == 0 )
                break;

        if ( !autocorrect )
        {
            ch_println( ch, "&zFailed: Autocorrection for &R%s&z not found.", arg2 );
            return;
        }

        delete_autocorrect( autocorrect );
        ch_println( ch, "&zSucceeded: Deleted autocorrection for &R%s&z.", arg2 );
        return;
    }
    else if ( !str_cmp( arg, "edit" ) )
    {
        if ( NULLSTR( arg2 ) || NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cautocorrect edit [typo] [new correction]" );
            return;
        }
        AUTOCORRECT_DATA* autocorrect = NULL;
        for ( autocorrect = first_autocorrect; autocorrect; autocorrect = autocorrect->next )
            if ( autocorrect && strcmp( arg2, autocorrect->typo ) == 0 )
                break;

        if ( !autocorrect )
        {
            ch_println( ch, "&zFailed: Autocorrection for &R%s&z not found.", arg2 );
            return;
        }

        SET_STRING( autocorrect->correction, argument );
        save_autocorrect(autocorrect);
        ch_println( ch, "&zSucceeded: Changed autocorrection for &R%s&z to &C%s&z.", autocorrect->typo, autocorrect->correction );
        return;
    }
    else
    {
        ch_println( ch, "&zSyntax: &Cautocorrect <&woption&C> [typo] [substitution]" );
        ch_println( ch, "&z        &Cautocorrect list <&wstarting letter/all&C>" );
        ch_println( ch, "\n&zOptions: &Cadd&z, &Cdelete&z, &Cedit" );
        return;
    }

    return;
}

bool has_multiplay( ACCOUNT_DATA* acc, char* name )
{
    char buf[MSL], namelower[256], arg[MIL];
    bool match = FALSE;
    char* multi = NULL;

    if ( !acc || NULLSTR( name ) || NULLSTR( acc->multiplay ) )
        return FALSE;

    strlcpy( buf, strlower( acc->multiplay ), MSL );
    strlcpy( namelower, strlower( name ), 256 );
    multi = buf;

    for ( ; ; )
    {
        multi = one_argument( multi, arg );

        if ( NULLSTR( arg ) )
            break;

        if ( !str_cmp( arg, namelower ) )
        {
            match = TRUE;
            break;
        }
    }

    return match;
}

bool add_multiplay( ACCOUNT_DATA* acc, char* name )
{
    char buf[MSL];
    if ( !acc || NULLSTR( name ) )
        return FALSE;

    if ( has_multiplay( acc, name ) )
        return FALSE;

    strlcpy( buf, acc->multiplay, MSL );
    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "%s%s", strlen( buf ) > 0 ? " " : "", sentence_case( name ) );    
    SET_STRING( acc->multiplay, buf );
    return TRUE;
}

bool remove_multiplay( ACCOUNT_DATA* acc, char* name )
{
    char buf[MSL], buf2[MSL], namelower[256], arg[MIL];
    bool match = FALSE;
    char* multi = NULL;

    if ( !acc || NULLSTR( name ) || NULLSTR( acc->multiplay ) )
        return FALSE;

    strlcpy( buf, strlower( acc->multiplay ), MSL );
    strlcpy( buf2, "", MSL );
    strlcpy( namelower, strlower( name ), 256 );
    multi = buf;

    for ( ; ; )
    {
        multi = one_argument( multi, arg );

        if ( NULLSTR( arg ) )
            break;

        if ( !str_cmp( arg, namelower ) )
        {
            match = TRUE;
            continue;
        }

        snprintf( buf2 + strlen( buf2 ), MSL - strlen( buf2 ), "%s%s", strlen( buf2 ) > 0 ? " " : "", sentence_case( arg ) );
    }

    SET_STRING( acc->multiplay, buf2 );
    return match;
}


CMDF do_allowmultiplay( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    char buf[MSL], arg[MIL];

    IMM_CHECK( ch );

    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Callowmultiplay <&wcharacter&C>" );
        return;
    }

    victim = get_player_world( arg );

    if ( !victim || !victim->pcdata )
    {
        ch_println( ch, "&RThey're not online." );
        return;
    }

    if ( victim->pcdata->can_multiplay )
    {
        ch_println( ch, "&RThey already have multiplay enabled." );
        return;
    }

    victim->pcdata->can_multiplay = TRUE;
    snprintf( buf, MSL, "%s: %s allowing %s to bypass multiplay restrictions and make an account.", FUNC, ch->name, victim->name );
    write_to_log( "allowmultiplay", buf, LEVEL_ADMIN, 720, true );
    ch_println( ch, "&zYou have allowed &C%s&z to bypass multiplay restrictions and make an account.", victim->name );
    ch_println( victim, "&WYou are now able to make an account.\n&WUse the &Caccount&W command to get started." );
    return;
}

