char* format_obj_to_char( OBJ_DATA* obj, CHAR_DATA* ch, bool fShort )
{
    static char buf[MSL];
    buf[0] = '\0';

    if ( xIS_SET( obj->extra_flags, ITEM_INVIS ) )
        strlcat( buf, "(Invis) "    , MSL );

    if ( xIS_SET( obj->extra_flags, ITEM_GLOW ) )
        strlcat( buf, "&c(&CGlowing&c)&w "  , MSL );

    if ( xIS_SET( obj->extra_flags, ITEM_HUM ) )
        strlcat( buf, "(Humming) "  , MSL );

    if ( xIS_SET( obj->extra_flags, ITEM_HIDDEN ) )
        strlcat( buf, "(Hidden) "   , MSL );

    if ( xIS_SET( obj->extra_flags, ITEM_CONCEAL ) )
        strlcat( buf, "(Concealed) ", MSL );

    if ( xIS_SET( obj->extra_flags, ITEM_BURIED ) )
        strlcat( buf, "(buried) "  , MSL );

    if ( IS_IMMORTAL( ch ) )
    {
        if ( xIS_SET( obj->extra_flags, ITEM_PROTOTYPE ) )
            strlcat( buf, "(Prototype)", MSL );
    }

    if ( ( IS_AFFECTED( ch, AFF_DETECTTRAPS ) || has_pcflag( ch, PCFLAG_HOLYLIGHT ) ) && is_trapped( obj ) )
        strlcat( buf, "&r(&RTrap&r)&w ", MSL );

    if ( IS_AFFECTED( ch, AFF_DETECTTRAPS ) && is_trapped( obj ) )
        strlcat( buf, "&r(&RTrap&r)&w ", MSL );

    if ( IS_AFFECTED( ch, AFF_DETECT_MAGIC ) || IS_IMMORTAL( ch ) )
        if ( xIS_SET( obj->extra_flags, ITEM_MAGIC ) )
            strlcat( buf, "(Blue Aura)&w ", MSL );

    if ( fShort )
    {
        if ( obj->short_descr )
            strlcat( buf, obj->short_descr, MSL );
    }
    else
    {
        if ( obj->description )
            strlcat( buf, obj->description, MSL );
    }

    return buf;
}


