/*
    Show a list to a character.
    Can coalesce duplicated items.
*/
void show_list_to_char( OBJ_DATA* list, CHAR_DATA* ch, bool fShort, bool fShowNothing )
{
    char** prgpstrShow;
    int* prgnShow;
    int* pitShow;
    char* pstrShow;
    OBJ_DATA* obj;
    int nShow;
    int iShow;
    int count, offcount, tmp, ms, cnt;
    bool fCombine;

    if ( !ch->desc )
        return;

    /*
        if there's no list... then don't do all this crap!  -Thoric
    */
    if ( !list )
    {
        if ( fShowNothing )
        {
            if ( IS_NPC( ch ) || has_pcflag( ch, PCFLAG_COMBINE ) )
                send_to_char( "     ", ch );

            set_char_color( AT_OBJECT, ch );
            ch_println( ch, "Nothing." );
        }

        return;
    }

    /*
        Alloc space for output lines.
    */
    count = 0;

    for ( obj = list; obj; obj = obj->next_content )
        count++;

    ms  = ( ch->mental_state ? ch->mental_state : 1 )
          * ( IS_NPC( ch ) ? 1 : ( ch->pcdata->condition[COND_DRUNK] ? ( ch->pcdata->condition[COND_DRUNK] / 12 ) : 1 ) );

    /*
        If not mentally stable...
    */
    if ( abs( ms ) > 40 )
    {
        offcount = URANGE( -( count ), ( count * ms ) / 100, count * 2 );

        if ( offcount < 0 )
            offcount += number_range( 0, abs( offcount ) );
        else if ( offcount > 0 )
            offcount -= number_range( 0, offcount );
    }
    else
        offcount = 0;

    if ( count + offcount <= 0 )
    {
        if ( fShowNothing )
        {
            if ( IS_NPC( ch ) || has_pcflag( ch, PCFLAG_COMBINE ) )
                send_to_char( "     ", ch );

            set_char_color( AT_OBJECT, ch );
            ch_println( ch, "Nothing." );
        }

        return;
    }

    CREATE( prgpstrShow,    char*,    count + ( ( offcount > 0 ) ? offcount : 0 ) );
    CREATE( prgnShow,        int,    count + ( ( offcount > 0 ) ? offcount : 0 ) );
    CREATE( pitShow,        int,    count + ( ( offcount > 0 ) ? offcount : 0 ) );
    nShow    = 0;
    tmp        = ( offcount > 0 ) ? offcount : 0;
    cnt        = 0;

    /*
        Format the list of objects.
    */
    for ( obj = list; obj; obj = obj->next_content )
    {
        if ( offcount < 0 && ++cnt > ( count + offcount ) )
            break;

        if ( tmp > 0 && number_bits( 1 ) == 0 )
        {
            SET_STRING( prgpstrShow[nShow], halucinated_object( ms, fShort ) );
            prgnShow    [nShow] = 1;
            pitShow    [nShow] = number_range( ITEM_LIGHT, ITEM_BOOK );
            nShow++;
            --tmp;
        }

        if ( obj->wear_loc == WEAR_NONE
                && can_see_obj( ch, obj )
                && ( obj->item_type != ITEM_TRAP || IS_AFFECTED( ch, AFF_DETECTTRAPS ) ) )
        {
            pstrShow = format_obj_to_char( obj, ch, fShort );
            fCombine = FALSE;

            if ( IS_NPC( ch ) || has_pcflag( ch, PCFLAG_COMBINE ) )
            {
                /*
                    Look for duplicates, case sensitive.
                    Matches tend to be near end so run loop backwords.
                */
                for ( iShow = nShow - 1; iShow >= 0; iShow-- )
                {
                    if ( !strcmp( prgpstrShow[iShow], pstrShow ) )
                    {
                        prgnShow[iShow] += obj->count;
                        fCombine = TRUE;
                        break;
                    }
                }
            }

            pitShow[nShow] = obj->item_type;

            /*
                Couldn't combine, or didn't want to.
            */
            if ( !fCombine )
            {
                SET_STRING( prgpstrShow[nShow], pstrShow );
                prgnShow    [nShow] = obj->count;
                nShow++;
            }
        }
    }

    if ( tmp > 0 )
    {
        int x;

        for ( x = 0; x < tmp; x++ )
        {
            SET_STRING( prgpstrShow[nShow], halucinated_object( ms, fShort ) );
            prgnShow    [nShow] = 1;
            pitShow    [nShow] = number_range( ITEM_LIGHT, ITEM_BOOK );
            nShow++;
        }
    }

    /*
        Output the formatted list.        -Color support by Thoric
    */
    for ( iShow = 0; iShow < nShow; iShow++ )
    {
        switch ( pitShow[iShow] )
        {
            default:
                set_char_color( AT_OBJECT, ch );
                break;

            case ITEM_MONEY:
            case ITEM_FOOD:
                set_char_color( AT_HUNGRY, ch );
                break;

            case ITEM_DRINK_CON:
            case ITEM_FOUNTAIN:
                set_char_color( AT_THIRSTY, ch );
                break;

            case ITEM_FIRE:
                set_char_color( AT_FIRE, ch );
                break;
        }

        if ( fShowNothing )
            send_to_char( "     ", ch );

        send_to_char( prgpstrShow[iShow], ch );
        /*  if ( IS_NPC(ch) || has_pcflag( ch, PCFLAG_COMBINE ) ) */
        {
            if ( prgnShow[iShow] != 1 )
                ch_printf( ch, " &z(&C%d&z)&w", prgnShow[iShow] );
        }
        ch_println( ch, "" );
        DISPOSE( prgpstrShow[iShow] );
    }

    if ( fShowNothing && nShow == 0 )
    {
        if ( IS_NPC( ch ) || has_pcflag( ch, PCFLAG_COMBINE ) )
            send_to_char( "     ", ch );

        ch_println( ch, "Nothing." );
    }

    /*
        Clean up.
    */
    DISPOSE( prgpstrShow );
    DISPOSE( prgnShow     );
    DISPOSE( pitShow     );
    return;
}
