void show_char_to_char_0( CHAR_DATA* victim, CHAR_DATA* ch )
{
    char buf[MSL], buf1[MIL], buf2[MIL], tbuf[MIL];
    RACE_DATA * victrace;
    strlcpy( buf, "", MSL );

    if ( !ch || !victim || char_extracted( ch ) || char_extracted( victim ) )
        return;

    /*
        Renders specified mobs invisible to all players, except Lv. 105+ Imms.
    */
    if ( IS_NPC( victim ) && get_trust( ch ) < LEVEL_ADMIN )
    {
        if ( victim->pIndexData->vnum == 1 )
            return;  /* Puff */

        if ( victim->pIndexData->vnum == 3 )
            return;  /* Supermob */
    }

    victrace = victim->race;

    if ( is_ai( victim, AI_SOLDIER_LIGHT ) )
        return;

    if ( victim->pcdata && has_pcflag( victim, PCFLAG_CG ) && victim->team > 0 )
    {
        strlcat( buf, victim->team == 1 ? "&w[&RRed&w] "  :
                victim->team == 2 ? "&w[&BBlue&w] " :
                victim->team == 3 ? "&w[&zBlack&w] " :
                victim->team == 4 ? "&w[&GGreen&w] " : "", MSL );
    }

    if ( victim->spirit )
        strlcat( buf, "&W", MSL );

    if ( IS_NPC( victim ) )
    {
        if ( victim->pIndexData->vnum == 1 || victim->pIndexData->vnum == 3 )
            strlcat( buf, "(IMask) ", MSL );
    }

    if ( !IS_NPC( victim ) && !victim->desc )
    {
        if ( !victim->switched )
            strlcat( buf, "(Link Dead) ", MSL );
        else if ( !IS_AFFECTED( victim->switched, AFF_POSSESS ) )
            strlcat( buf, "(Switched) ", MSL );
    }

    if ( !IS_NPC( victim ) && victim->desc && victim->desc->is_fake_desc )
        strlcat( buf, "(Fake Desc) ", MSL );

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
        strlcat( buf, "[AFK] ", MSL );

    if ( !IS_NPC( victim ) && victim->pcdata->botting && victim->pcdata->cooldown != -1 )
        strlcat( buf, "[BOTTING] ", MSL );

    if ( ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_WIZINVIS ) )
            || ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_MOBINVIS ) ) )
    {
        if ( !IS_NPC( victim ) )
            snprintf( buf1, MIL, "(Invis %d) ", victim->pcdata->wizinvis );
        else
            snprintf( buf1, MIL, "(Mobinvis %d) ", victim->mobinvis );

        strlcat( buf, buf1, MSL );
    }

    if ( is_same_group( victim, ch ) && victim != ch )
        strlcat( buf, "&B(&CGrouped&B)&w ", MSL );

    if ( is_same_group( victim, ch ) && IS_AFFECTED( victim, AFF_FORTIFY ) )
        strlcat( buf, "&z(&OFortified&z)&w ", MSL );

    if ( ( victim->ai_data && is_ai( victim, AI_SOLDIER_LIGHT ) ) )
        strlcat( buf, "&g(&OClan Trooper&g) ", MSL );

    if ( ( victim->ai_data && is_ai( victim, AI_POLICE ) ) )
        strlcat( buf, "&w(&RPolice&w) ", MSL );

    if ( ( victim->ai_data && is_ai( victim, AI_CITIZEN ) ) )
        strlcat( buf, "&w(Citizen) ", MSL );

    if ( IS_AFFECTED( victim, AFF_INVISIBLE )   )
        strlcat( buf, "(Invis) ", MSL );

    /* GRAL If invisible why not reveal the disguise of "a race sex" instead of the invis? */
    if ( IS_AFFECTED( victim, AFF_HIDE )        )
        strlcat( buf, "(Hide) ", MSL );

    /* GRAL If hidden why not set a action description of Asshat is trying to hide here. */
    if ( IS_AFFECTED( victim, AFF_PASS_DOOR ) && ( !victim->spirit )  )
        strlcat( buf, "(Translucent) ", MSL );

    if ( IS_AFFECTED( victim, AFF_PASS_DOOR ) && victim->spirit && victim->alignment >= 300 )
        strlcat( buf, "&w(&CTranslucent&w)&C ", MSL );

    if ( IS_AFFECTED( victim, AFF_PASS_DOOR ) && victim->spirit && victim->alignment <= -300 )
        strlcat( buf, "&r(&RTranslucent&r)&r ", MSL );

    if ( IS_AFFECTED( victim, AFF_FAERIE_FIRE ) )
        strlcat( buf, "&P(Pink Aura)&w ", MSL );

    if ( IS_EVIL( victim ) && IS_AFFECTED( ch, AFF_DETECT_EVIL ) )
        strlcat( buf, "&R(Red Aura)&w ", MSL );

    if ( ( victim->mana > 10 ) && ( IS_AFFECTED( ch, AFF_DETECT_MAGIC ) || IS_IMMORTAL( ch ) ) )
        strlcat( buf, "&B(Blue Aura)&w ", MSL );

    if ( IS_NPC( victim ) && IS_IMMORTAL( ch ) && xIS_SET( victim->act, ACT_PROTOTYPE ) )
        strlcat( buf, "(PROTO) ", MSL );

    if ( victim->desc && victim->desc->connected == CON_EDITING )
        strlcat( buf, "(Writing) ", MSL );

    set_char_color( AT_PERSON, ch );

    if ( victim->position == victim->defposition && victim->long_descr[0] != '\0' && ( victim->pIndexData->vnum != 250 && victim->pIndexData->vnum != 97 ) )
    {
        strlcat( buf, victim->long_descr, MSL );
        send_to_char( buf, ch );
        show_visible_affects_to_char( victim, ch );
        return;
    }

    /*   strlcat( buf, PERS( victim, ch ), MSL );       old system of titles
          removed to prevent prepending of name to title     -Kuran

          But added back bellow so that you can see mobs too :P   -Durga
    */

    if ( victim->spirit )
        strlcat( buf, "&C", MSL );

    if ( !IS_NPC( victim ) && !has_pcflag( ch, PCFLAG_BRIEF ) )
    {
        if ( IS_IMMORTAL( ch ) )
            strlcat( buf, g_name( victim, ch ), MSL );
        else if ( IS_IMMORTAL( victim ) || ( knows_player( ch, victim, GREET_KNOWN, true ) && ch->pcdata->clan && victim->pcdata->clan && victim->pcdata->clan == ch->pcdata->clan && !obj_mask( victim ) ) )
            strlcat( buf, victim->disguise ? victim->disguise->title : victim->pcdata->title, MSL );
        else if ( ( ( victim->disguise && !NULLSTR( victim->disguise->pubtitle ) ) || ( !victim->disguise && !NULLSTR( victim->pcdata->pubtitle ) ) ) && !obj_mask( victim ) && knows_player( ch, victim, GREET_KNOWN, true ) && ( ch->pcdata->clan == NULL || victim->pcdata->clan == NULL || victim->pcdata->clan != ch->pcdata->clan ) )
            strlcat( buf, victim->disguise ? victim->disguise->pubtitle : victim->pcdata->pubtitle, MSL );
        else
            strlcat( buf, make_greet_desc( victim, ch ), MSL );
    }
    else if ( victim->ai_data )
    {
        strlcat( buf, g_name( victim, ch ), MSL );
    }
    else
        strlcat( buf, PERS( victim, ch ), MSL );

    if ( victim->heldby )
    {
        if ( victim->heldby->in_room != victim->in_room )
        {
            victim->heldby->holding = NULL;
            victim->heldby = NULL;
        }
    }

    if ( get_eq_char( victim, WEAR_WIELD ) )
    {
        snprintf( tbuf, MIL, " wielding %s", get_eq_char( victim, WEAR_WIELD )->short_descr );

        if ( get_eq_char( victim, WEAR_DUAL_WIELD ) )
            snprintf( tbuf + strlen( tbuf ), MIL - strlen( tbuf ), " and %s", get_eq_char( victim, WEAR_DUAL_WIELD )->short_descr );

        //        else
        //          snprintf( tbuf + strlen(tbuf), MSL - strlen( tbuf ), "." );
        strlcat( buf, tbuf, MSL );
    }

    if ( victim->heldby )
    {
        if ( victim->heldby == ch )
        {
            if ( victim->position <= POS_SLEEPING )
                strlcat( buf, " is unconscious in your grip.", MSL );
            else
                strlcat( buf, " is in your grip.", MSL );
        }
        else
        {
            if ( victim->position <= POS_SLEEPING )
                snprintf( buf2, MIL, " is unconscious, held by %s.", g_name( victim->heldby, ch ) );
            else
                snprintf( buf2, MIL, " is held by %s.", g_name( victim->heldby, ch ) );

            strlcat( buf, buf2, MSL );
        }
    }
    else if ( in_action( victim ) )
        strlcat( buf, get_action( victim, ch ), MSL );
    else if ( IS_SNEAKING( victim ) && !has_feat( victim, cache_skill( "silent sneak", &skill_silent_sneak ) ) && victim->position == POS_STANDING )
        strlcat( buf, " is sneaking around.", MSL );
    else
        switch ( victim->position )
        {
            case POS_DEAD:
                strlcat( buf, " is DEAD!!", MSL );
                break;

            case POS_MORTAL:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is mortally wounded... and ON FIRE!", MSL );
                else
                    strlcat( buf, " is mortally wounded.", MSL );
                break;

            case POS_INCAP:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is incapacitated... and ON FIRE!", MSL );
                else
                    strlcat( buf, " is incapacitated.", MSL );
                break;

            case POS_STUNNED:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is lying here stunned... and ON FIRE!", MSL );
                else
                    strlcat( buf, " is lying here stunned.", MSL );
                break;

            case POS_SLEEPING:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is sleeping nearby... and ON FIRE!", MSL );
                else if ( victim->furniture && victim->furniture->pIndexData )
                {
                    strlcat( buf, " is sleeping on ", MSL );
                    strlcat( buf, victim->furniture->pIndexData->short_desc, MSL );

                    if ( ch->furniture && ch->furniture == victim->furniture )
                        strlcat( buf, " with you.", MSL );
                    else
                        strlcat( buf, ".", MSL );
                }
                else if ( ch->position == POS_SITTING
                          ||  ch->position == POS_RESTING )
                    strlcat( buf, " is sleeping nearby.", MSL );
                else
                    strlcat( buf, " is deep in slumber here.", MSL );

                break;

            case POS_RESTING:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is sprawled out... and ON FIRE!", MSL );
                else if ( victim->furniture && victim->furniture->pIndexData )
                {
                    strlcat( buf, " is laying down on ", MSL );
                    strlcat( buf, victim->furniture->pIndexData->short_desc, MSL );

                    if ( ch->furniture && ch->furniture == victim->furniture )
                        strlcat( buf, " with you.", MSL );
                    else
                        strlcat( buf, ".", MSL );
                }
                else if ( is_naked( victim ) && !IS_NPC( victim ) && ( !victim->spirit ) && is_human_build( victrace ) )
                    strlcat( buf, " is lying around NAKED.", MSL );
                else if ( ch->position == POS_RESTING )
                    strlcat( buf, " is sprawled out alongside you.", MSL );
                else if ( ch->position == POS_MOUNTED )
                    strlcat( buf, " is sprawled out at the foot of your mount.", MSL );
                else
                    strlcat( buf, " is sprawled out here.", MSL );

                break;

            case POS_SITTING:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is sitting here... and ON FIRE!", MSL );
                else if ( victim->furniture && victim->furniture->pIndexData )
                {
                    // GRAL for Ralen sitat furniture
                    if ( xIS_SET( victim->furniture->pIndexData->positions, FURN_SITAT ) )
                        strlcat( buf, " is sitting at ", MSL );
                    else
                        strlcat( buf, " is sitting on ", MSL );

                    strlcat( buf, victim->furniture->pIndexData->short_desc, MSL );

                    if ( ch->furniture && ch->furniture == victim->furniture )
                        strlcat( buf, " with you.", MSL );
                    else
                        strlcat( buf, ".", MSL );
                }
                else if ( is_naked( victim ) && !IS_NPC( victim ) && ( !victim->spirit ) && is_human_build( victrace ) )
                    strlcat( buf, " is sitting here NAKED.", MSL );
                else if ( ch->position == POS_SITTING )
                    strlcat( buf, " sits here with you.", MSL );
                else if ( ch->position == POS_RESTING )
                    strlcat( buf, " sits nearby as you lie around.", MSL );
                else
                    strlcat( buf, " sits upright here.", MSL );

                break;

            case POS_STANDING:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is standing here... and ON FIRE!", MSL );
                else if ( IS_IMMORTAL( victim ) )
                    strlcat( buf, " is here before you.", MSL );
                else if ( ( victim->in_room->sector_type == SECT_UNDERWATER )
                          && !IS_AFFECTED( victim, AFF_AQUA_BREATH ) && !xIS_SET( victim->race->flags, RFLAG_AQUABREATH ) && !IS_NPC( victim ) )
                    strlcat( buf, " is drowning here.", MSL );
                else if ( victim->in_room->sector_type == SECT_UNDERWATER )
                    strlcat( buf, " is here in the water.", MSL );
                else if ( ( victim->in_room->sector_type == SECT_OCEANFLOOR )
                          && !IS_AFFECTED( victim, AFF_AQUA_BREATH ) && !xIS_SET( victim->race->flags, RFLAG_AQUABREATH ) && !IS_NPC( victim ) )
                    strlcat( buf, " is drowning here.", MSL );
                else if ( victim->in_room->sector_type == SECT_OCEANFLOOR )
                    strlcat( buf, " is standing here in the water.", MSL );
                else if ( ( IS_AFFECTED( victim, AFF_FLOATING ) || IS_AFFECTED( victim, AFF_FLYING ) ) &&
                          is_naked( victim ) && !IS_NPC( victim ) && ( !victim->spirit ) && is_human_build( victrace ) )
                    strlcat( buf, " is hovering here NAKED.", MSL );
                else if ( IS_AFFECTED( victim, AFF_FLOATING )
                          || IS_AFFECTED( victim, AFF_FLYING ) )
                    strlcat( buf, " is hovering here.", MSL );
                else if ( is_naked( victim ) && !IS_NPC( victim ) && ( !victim->spirit ) && is_human_build( victrace ) )
                    strlcat( buf, " is standing here NAKED.", MSL );
                else
                    strlcat( buf, " is standing here.", MSL );

                break;

            case POS_SHOVE:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is being shoved around... while ON FIRE!", MSL );
                else
                    strlcat( buf, " is being shoved around.", MSL );
                break;

            case POS_DRAG:
                if ( xIS_SET( victim->affected_by, AFF_NAPALM ) )
                    strlcat( buf, " is being dragged around... while ON FIRE!", MSL );
                else
                    strlcat( buf, " is being dragged around.", MSL );
                break;

            case POS_MOUNTED:
                strlcat( buf, " is here, upon ", MSL );

                if ( !victim->mount )
                    strlcat( buf, "thin air???", MSL );
                else if ( victim->mount == ch )
                    strlcat( buf, "your back.", MSL );
                else if ( victim->in_room == victim->mount->in_room )
                {
                    strlcat( buf, PERS( victim->mount, ch ), MSL );
                    strlcat( buf, ".", MSL );
                }
                else
                    strlcat( buf, "someone who left??", MSL );

                break;

            case POS_FIGHTING:
                strlcat( buf, " is here, fighting ", MSL );

                if ( !victim->fighting )
                    strlcat( buf, "thin air???", MSL );
                else if ( who_fighting( victim ) == ch )
                    strlcat( buf, "YOU!", MSL );
                else if ( victim->in_room == victim->fighting->who->in_room )
                {
                    strlcat( buf, PERS( victim->fighting->who, ch ), MSL );
                    strlcat( buf, ".", MSL );
                }
                else
                    strlcat( buf, "someone who left??", MSL );

                break;
        }

    strlcat( buf, "\n", MSL );
    buf[0] = UPPER( buf[0] );
    send_to_char( buf, ch );
    show_visible_affects_to_char( victim, ch );
    return;
}

bool is_bald( CHAR_DATA* ch )
{
    return ( xIS_SET( ch->race->flags, RFLAG_ISBALD ) || ch->hairstyle == 6 );
}

void show_char_to_char_1( CHAR_DATA* victim, CHAR_DATA* ch )
{
    /* Gral Need to either use flags to replace RACE_TWILEK with HEAD_Lekku etc */
    OBJ_DATA* obj;
    char buf[MSL];
    int iWear;
    bool found;
    int victskincolor;
    RACE_DATA *victrace = NULL;
//    int victrace;

    if ( !IS_NPC( victim ) )
    {
        victskincolor = victim->disguise ? victim->disguise->skincolor : victim->skincolor;
        victrace = victim->disguise ? victim->disguise->race : victim->race;
    }
    else
    {
        victskincolor = victim->skincolor;
        victrace = victim->race;
    }

    if ( can_see( victim, ch ) )
    {
        act( AT_ACTION, "$n looks at you.", ch, NULL, victim, TO_VICT    );
        act( AT_ACTION, "$n looks at $N.",  ch, NULL, victim, TO_NOTVICT );
    }

    if ( !IS_NPC( victim ) && victim->disguise && !obj_mask( victim ) )
    {
        send_to_char( victim->disguise->description, ch );
    }
    else if ( victim->description[0] != '\0' && !obj_mask( victim ) )
    {
        send_to_char( victim->description, ch );
    }
    else if ( obj_mask( victim ) )
    {
        send_to_char( get_mask_desc( victim ), ch );
    }
    else
    {
        act( AT_PLAIN, "You see nothing special about $M.", ch, NULL, victim, TO_CHAR );
    }

    /* Vendor Patch - Shows the Owner */
    if ( IS_NPC( victim ) )
    {
        if ( victim->vendor_data )
        {
            if ( IS_IMMORTAL( ch ) || !xIS_SET( victim->act, ACT_HIDEVENDOR ) || is_your_vendor( ch, victim ) )
                ch_println( ch, "%s works in the shop owned by %s.", PERS( victim, ch ), victim->vendor_data->owner );
        }
    }

    show_condition( ch, victim );
    show_appearance( ch, victim );
    if ( !IS_NPC( victim ) )
        show_char_to_char_0( victim, ch );
    found = FALSE;

    if ( victim->spirit )
    {
        ch_println( ch, "" );
        act( AT_PLAIN, "$N is wearing:", ch, NULL, victim, TO_CHAR );

        if ( IS_GOOD( victim ) )
        {
            send_to_char( "&B ", ch );
            send_to_char( where_name[WEAR_HEAD], ch );
            send_to_char( "&Oa worn&W, &Ovoluminous brown cowl", ch );
            ch_println( ch, "&w" );
            send_to_char( "&B ", ch );
            send_to_char( where_name[WEAR_OVER], ch );
            send_to_char( "&Oa worn&W, &Obrown mantle cloak", ch );
            ch_println( ch, "&w" );
        }
        else
        {
            send_to_char( "&B ", ch );
            send_to_char( where_name[WEAR_HEAD], ch );
            send_to_char( "&zan oversized&w,&z black concealing hood", ch );
            ch_println( ch, "&w" );
            send_to_char( "&B ", ch );
            send_to_char( where_name[WEAR_OVER], ch );
            send_to_char( "&za faded and tattered&w,&z loose&w-&zfitting onyx robe", ch );
            ch_println( ch, "&w" );
        }
    }
    else if  ( ( obj = get_eq_char( victim, WEAR_OVER ) ) == NULL
               || !can_see_obj( ch, obj )
               || obj->value[4] == 0
             )
    {
        for ( iWear = 0; iWear < MAX_WEAR; iWear++ )
        {
            if ( !found )
            {
                ch_println( ch, "" );
                act( AT_PLAIN, "$N is wearing:", ch, NULL, victim, TO_CHAR );
                found = TRUE;
            }

            if ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_DROID ) && ( victim->pIndexData->vnum != 250 ) )
                continue;

            if ( is_covered( victim, WEAR_ABOUT ) && iWear != WEAR_ABOUT && iWear != WEAR_HEAD && iWear != WEAR_EYES && iWear != WEAR_EARS && iWear != WEAR_OVER && iWear != WEAR_HOLD && iWear != WEAR_WIELD && iWear != WEAR_DUAL_WIELD )
                continue;

            if ( is_covered( victim, WEAR_HEAD ) && ( iWear == WEAR_EARS || iWear == WEAR_EYES ) )
                continue;

            if ( wielding_claws( victim ) && iWear == WEAR_WIELD )
            {
                send_to_char( "&B ", ch );
                send_to_char( where_name[iWear], ch );
                ch_println( ch, "&G&rA pair of deadly dewclaws" );
            }

            if ( ( obj = get_eq_char( victim, iWear ) ) != NULL && can_see_obj( ch, obj ) )
            {
                send_to_char( "&B ", ch );
                send_to_char( where_name[iWear], ch );
                send_to_char( "&G", ch );
                send_to_char( format_obj_to_char( obj, ch, TRUE ), ch );
                ch_println( ch, "&w" );
            }

            if ( !IS_NPC( victim ) && obj == NULL && ( iWear == WEAR_BODY || iWear == WEAR_FEET || iWear == WEAR_LEGS || iWear == WEAR_WAIST || iWear == WEAR_ARMS || iWear == WEAR_HEAD || iWear == WEAR_HANDS || iWear == WEAR_WRIST_L || iWear == WEAR_WRIST_R ) )
            {
                send_to_char( "&B ", ch );
                send_to_char( where_name[iWear], ch );
                send_to_char( "&G", ch );

                if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASLEKKU ) )
                    ch_println( ch, "%s%s lekku", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASANTENNAE ) ) // && victim->disguise && victim->disguise[0] == '\0') || (victim->disguise && victim->disguise[0] != '\0' && strstr( victim->disguise, "verpine" ) ) ) )
                    ch_println( ch, "%s%s antennae", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASMONTRALS ) )
                    ch_println( ch, "%s%s montrals", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASLETHORNS ) )
                    ch_println( ch, "%s%s lethorns", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASTENDRILS ) )
                    ch_println( ch, "%s%s tendrils", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASREBREATHER ) ) // && victim->disguise && victim->disguise[0] == '\0') || (victim->disguise && victim->disguise[0] != '\0' && strstr( victim->disguise, "verpine" ) ) ) )
                    ch_println( ch, "&R&r&W&OA Rebreather Mask" );
                else if ( iWear == WEAR_HEAD && is_humanoid( victrace ) )
                    ch_println( ch, "%s%s%s%s&G", color_of_hair( victim->haircolor ), is_bald( victim ) ? skincolor( victskincolor ) : "", is_bald( victim ) ? "Bald " : get_hairstyle( victim->hairstyle ), xIS_SET( victim->race->flags, RFLAG_ISBALD ) ? "" : get_haircolor( victim->haircolor ) );
                else
                {
                    if ( ( xIS_SET( victrace->flags, RFLAG_MALFUR ) && ( victim->sex == SEX_MALE || victim->sex == SEX_NEUTRAL ) ) || ( xIS_SET( victrace->flags, RFLAG_FEMFUR ) && victim->sex == SEX_FEMALE ) )
                        snprintf( buf, MSL, "%s fur\n", get_skincolor( victskincolor ) );
                    else
                        snprintf( buf, MSL, "%sBare\n", skincolor( victskincolor ) );

                    send_to_char( buf, ch );
                }
            }
        }
    }
    else
    {
        ch_println( ch, "" );
        act( AT_PLAIN, "$N is wearing:", ch, NULL, victim, TO_CHAR );
        found = TRUE;
        send_to_char( "&B ", ch );
        send_to_char( where_name[WEAR_OVER], ch );
        send_to_char( "&G", ch );
        send_to_char( format_obj_to_char( obj, ch, TRUE ), ch );
        ch_println( ch, "&w" );

        for ( iWear = 0; iWear < MAX_WEAR; iWear++ )
        {
            if ( xIS_SET( victim->act, ACT_DROID ) )
                continue;

            if ( is_covered( ch, WEAR_HEAD ) && ( iWear == WEAR_EARS || iWear == WEAR_EYES ) )
                continue;

            if ( iWear != WEAR_WIELD && iWear != WEAR_DUAL_WIELD && iWear != WEAR_SHIELD && iWear != WEAR_HEAD && iWear != WEAR_HOLD && iWear != WEAR_EARS && iWear != WEAR_EYES && iWear != WEAR_FEET && iWear != WEAR_BACK )
                continue;

            if ( ( obj = get_eq_char( victim, iWear ) ) != NULL && can_see_obj( ch, obj ) )
            {
                send_to_char( "&B ", ch );
                send_to_char( where_name[iWear], ch );
                send_to_char( "&G", ch );
                send_to_char( format_obj_to_char( obj, ch, TRUE ), ch );
                ch_println( ch, "&w" );
            }

            if ( !IS_NPC( victim ) && obj == NULL && ( iWear == WEAR_FEET || iWear == WEAR_HEAD ) )
            {
                send_to_char( "&B ", ch );
                send_to_char( where_name[iWear], ch );
                send_to_char( "&G", ch );

                if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASLEKKU ) ) //&& victim->disguise && victim->disguise[0] == '\0') || (victim->disguise && strstr( victim->disguise, "twi" ) ) ) )
                    ch_println( ch, "%s%s lekku", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASANTENNAE ) ) //&& victim->disguise && victim->disguise[0] == '\0') || (victim->disguise && victim->disguise[0] !='\0' && strstr( victim->disguise, "verpine" ) ) ) )
                    ch_println( ch, "%s%s antennae", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" :  "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASMONTRALS ) )
                    ch_println( ch, "%s%s montrals", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASLETHORNS ) )
                    ch_println( ch, "%s%s lethorns", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASTENDRILS ) )
                    ch_println( ch, "%s%s tendrils", skincolor( victskincolor ), victim->sex == 1 ? "His" : victim->sex == 2 ? "Her" : "It's" );
                else if ( iWear == WEAR_HEAD && xIS_SET( victrace->flags, RFLAG_HASREBREATHER ) )
                    ch_println( ch, "&R&r&W&OA Rebreather Mask" );
                else if ( iWear == WEAR_HEAD && is_humanoid( victrace ) )
                    ch_println( ch, "%s%s%s%s&G", color_of_hair( victim->haircolor ), is_bald( victim ) ? skincolor( victskincolor ) : "", is_bald( victim ) ? "Bald " : get_hairstyle( victim->hairstyle ), xIS_SET( victim->race->flags, RFLAG_ISBALD ) ? "" : get_haircolor( victim->haircolor ) );
                else
                {
                    if ( ( xIS_SET( victrace->flags, RFLAG_MALFUR ) && ( victim->sex == SEX_MALE || victim->sex == SEX_NEUTRAL ) ) || ( xIS_SET( victrace->flags, RFLAG_FEMFUR ) && victim->sex == SEX_FEMALE ) )
                        snprintf( buf, MSL, "%s fur\n", get_skincolor( victskincolor ) );
                    else
                        snprintf( buf, MSL, "%sBare\n", skincolor( victskincolor ) );

                    send_to_char( buf, ch );
                }
            }
        }
    }

    /*
        Crash fix here by Thoric
    */
    if ( IS_NPC( ch ) || victim == ch )
        return;

    if ( IS_IMMORTAL( victim ) && ( victim->top_level > ch->top_level ) )
        return;

    /* Need to be near to see their stuff, suggested by Alassra */
    if ( number_percent( ) <= get_learned_pct( ch, cache_skill( "peek", &skill_peek ) ) || get_trust( ch ) >= sysdata.log_level )
    {
        if ( get_trust( ch ) < sysdata.log_level && !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
        {
            ch_println( ch, "That player is afk, you can't see what they are carrying." );
            return;
        }

        if ( !is_near( ch, victim ) && get_trust( ch ) < sysdata.log_level )
        {
            ch_println( ch, "You are too far away to see what they're carrying." );
            return;
        }

        // Can't peek at clan vault inventory, to protect secret devs from being known.
        if ( get_trust( ch ) < sysdata.log_level && xIS_SET( victim->act, ACT_CLANVAULT ) )
            return;

        ch_println( ch, "\nYou peek at the inventory:" );
        show_list_to_char( victim->first_carrying, ch, TRUE, TRUE );
        learn_from_success( ch, cache_skill( "peek", &skill_peek ) );
    }
    else if ( get_learned_pct( ch, cache_skill( "peek", &skill_peek ) ) )
        learn_from_failure( ch, cache_skill( "peek", &skill_peek ) );

    return;
}

void show_chars_to_char( ROOM_INDEX_DATA* room, CHAR_DATA* ch )
{
    CHAR_DATA* rch;
    int cnt = 0;
    DB_DATA* db = NULL, *startai = NULL, *endai = NULL, *db_next = NULL;
    AI_DATA* curr_ai = NULL;
    sh_int trust = ch ? get_trust( ch ) : 0;

    for ( rch = room->first_person; rch; rch = rch->next_in_room )
    {
        if ( rch == ch )
            continue;

        if ( can_see( ch, rch ) )
            show_char_to_char_0( rch, ch );
        else if ( IS_NPC( rch ) || !has_pcflag( rch, PCFLAG_WIZINVIS ) || trust > get_trust( rch ) )
        {
            if ( room_is_dark( room ) && IS_AFFECTED( ch, AFF_INFRARED ) )
                ch_println( ch, "&rThe red form of a living creature is here." );
            else if ( xIS_SET( room->affected_by, AFF_SMOKE ) && ( IS_AFFECTED( ch, AFF_INFRARED ) || IS_AFFECTED( ch, AFF_TRUESIGHT ) ) )
                ch_println( ch, "&wThe vague outline of a living creature is here amidst the smoke." );
        }
    }

    {
        VEHICLE_DATA* vec = NULL;
        CHAR_DATA* rch = NULL;

        for ( vec = first_vehicle; vec; vec = vec->next )
        {
            if ( vec->type == WHEELED || vec->type == BARGE )
            {
                for ( rch = first_char; rch; rch = rch->next )
                    if ( ( vehicle_from_room( rch->in_room->vnum ) == vec ) )
                        if ( ( vec->type == WHEELED && ( vec->cockpit == rch->in_room->vnum || xIS_SET( rch->in_room->flags, ROOM_VIEWPORT ) ) )
                                || ( vec->type == BARGE && !xIS_SET( rch->in_room->flags, ROOM_SPACECRAFT ) && !xIS_SET( rch->in_room->flags, ROOM_INDOORS ) ) )
                            ch_println( ch, "&z<On %s>:%s", vec->name, g_name( rch, ch ) );
            }
        }
    }

    TRANSMIT_DATA* transmit = NULL;
    TRANSMIT_RECEIVER* rcv = NULL;
    ROOM_INDEX_DATA* troom = NULL;
    OBJ_DATA* tobj = NULL, *obj = NULL;
    CHAR_DATA* vch = NULL;

    for ( transmit = first_transmit; transmit; transmit = transmit->next )
    {
        bool found_receiving_transmitter = false;

        for ( obj = room->first_content; obj; obj = obj->next_content )
        {
            if ( obj->item_type == ITEM_TRANSMITTER
                    && obj->value[IVAL_TRANSMITTER_STATE] == 1
                    && obj->value[IVAL_TRANSMITTER_MODE] != 2
                    && obj->value[IVAL_TRANSMITTER_CHANNEL] == transmit->channel )
                found_receiving_transmitter = true;
        }

        for ( vch = room->first_person; vch; vch = vch->next_in_room )
        {
            for ( obj = vch->first_carrying; obj; obj = obj->next_content )
            {
                if ( obj->item_type == ITEM_TRANSMITTER
                        && obj->value[IVAL_TRANSMITTER_STATE] == 1
                        && obj->value[IVAL_TRANSMITTER_MODE] != 2
                        && obj->value[IVAL_TRANSMITTER_CHANNEL] == transmit->channel )
                    found_receiving_transmitter = true;
            }
        }

        if ( !found_receiving_transmitter )
            continue;

        // Go through any transmitters on this channel
        for ( rcv = transmit->first_connected; rcv; rcv = rcv->next )
        {
            tobj = rcv->transmitter;

            if ( tobj->value[IVAL_TRANSMITTER_MODE] == IVAL_TRANSMITTER_MODE_RECEIVE )
                continue;

            troom = tobj->in_room ? tobj->in_room : tobj->carried_by ? tobj->carried_by->in_room : NULL;

            if ( !troom || room == troom ) // Skip transmitters in a bad room or in this same room
                continue;

            // For any transmitters not in receive-only, show players in that room to this character
            for ( vch = troom->first_person; vch; vch = vch->next_in_room )
            {
                if ( can_see( ch, vch ) )
                {
                    if ( has_pcflag( vch, PCFLAG_AFK ) )
                        ch_println( ch, "&z<&WHolo&z> &033[AFK] %s's image is projected forth here.", g_name( vch, ch ) );
                    else
                        ch_println( ch, "&z<&WHolo&z> &033%s's image is projected forth here.", g_name( vch, ch ) );
                }
            }
        }
    }

    for ( rch = room->first_person; rch; rch = rch->next_in_room )
        if ( is_ai( rch, AI_SOLDIER_LIGHT ) )
            cnt++;

    if ( cnt == 0 )
        return;

    for ( rch = room->first_person; rch; rch = rch->next_in_room )
    {
        if ( !is_ai( rch, AI_SOLDIER_LIGHT ) )
            continue;

        curr_ai = find_ai( rch );

        for ( db = startai; db; db = db->next )
            if ( curr_ai->clan && !str_cmp( curr_ai->clan->shortname, db->str1 ) && ( ( !rch->master && db->str2[0] == '\0' ) || ( rch->master && !str_cmp( rch->master->name, db->str2 ) ) ) )
                break;

        if ( !db )
        {
            CREATE( db, DB_DATA, 1 );
            SET_STRING( db->name, curr_ai->name );
            SET_STRING( db->str1, curr_ai->clan ? curr_ai->clan->shortname : "" );
            SET_STRING( db->str2, rch->master ? rch->master->name : "" );
            LINK( db, startai, endai, next, prev );
            db->num1 = 1;
        }
        else
            db->num1++;
    }

    for ( db = startai; db; db = db_next )
    {
        db_next = db->next;
        send_to_char( "&W", ch );

        if ( !db->str2 || db->str2[0] == '\0' )
            ch_println( ch, "&O[x%d] %s trooper%s.", db->num1, db->str1, db->num1 == 1 ? "" : "s"            );
        else
            ch_println( ch, "&O[x%d] %s%s trooper squad.", db->num1, !str_cmp( db->str2, ch->name ) ? "Your " : "", db->str1 );

        UNLINK( db, startai, endai, next, prev );
        extract_db( db );
    }

    return;
}

bool check_smoke( CHAR_DATA* ch, bool silent )
{
    if ( !ch || ch == NULL )
        return TRUE;

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
        return TRUE;

    if ( IS_IMMORTAL( ch ) )
        return TRUE;

    if ( ch->in_room && xIS_SET( ch->in_room->affected_by, AFF_SMOKE ) )
    {
        if ( !silent )
            ch_println( ch, "You can't see much of anything through the cloud of smoke!" );

        return FALSE;
    }

    return TRUE;
}

bool check_blind( CHAR_DATA* ch, bool silent )
{
    if ( !ch || ch == NULL )
        return TRUE;

    if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_HOLYLIGHT ) )
        return TRUE;

    if ( IS_IMMORTAL( ch ) )
        return TRUE;

    if ( IS_AFFECTED( ch, AFF_TRUESIGHT ) )
        return TRUE;

    if ( IS_AFFECTED( ch, AFF_BLIND ) )
    {
        if ( !silent )
            ch_println( ch, "You can't see a thing!" );

        return FALSE;
    }

    return TRUE;
}

/*
    Returns classical DIKU door direction based on text in arg    -Thoric
*/
int get_door( char* arg )
{
    int door;

    if ( !str_cmp( arg, "n"  ) || !str_cmp( arg, "north"      ) )
        door = 0;
    else if ( !str_cmp( arg, "e"  ) || !str_cmp( arg, "east"      ) )
        door = 1;
    else if ( !str_cmp( arg, "s"  ) || !str_cmp( arg, "south"      ) )
        door = 2;
    else if ( !str_cmp( arg, "w"  ) || !str_cmp( arg, "west"      ) )
        door = 3;
    else if ( !str_cmp( arg, "u"  ) || !str_cmp( arg, "up"      ) )
        door = 4;
    else if ( !str_cmp( arg, "d"  ) || !str_cmp( arg, "down"      ) )
        door = 5;
    else if ( !str_cmp( arg, "ne" ) || !str_cmp( arg, "northeast" ) )
        door = 6;
    else if ( !str_cmp( arg, "nw" ) || !str_cmp( arg, "northwest" ) )
        door = 7;
    else if ( !str_cmp( arg, "se" ) || !str_cmp( arg, "southeast" ) )
        door = 8;
    else if ( !str_cmp( arg, "sw" ) || !str_cmp( arg, "southwest" ) )
        door = 9;
    else
        door = -1;

    return door;
}

CMDF do_look( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char arg1[MIL];
    char arg2[MIL];
    char arg3[MIL];
    EXIT_DATA* pexit;
    CHAR_DATA* victim;
    OBJ_DATA* obj;
    PLANET_DATA* planet;
    ROOM_INDEX_DATA* original;
    VEHICLE_DATA* vec;
    SHIP_DATA* ship = NULL, *tship = NULL;
    LOCKER_DATA* locker = NULL;
    char* pdesc;
    sh_int door;
    int number, cnt;
    TAP_DATA* tap = NULL;

    if(!ch->desc) {
        ch_println( ch, "NPCs can't use desc at this time" );
        return;
    }

    char* blizzard_description =
        "&W                 *                               *\n&W.        .                                                 .\n&W	                            *                               *\n&W	          *      .          .              *  .          .\n&x&Y&WA fierce, freezing blizzard completely obscures your vision.\n\n&W *                 .                .                 *        .\n&W      .       *            *                .               \n&W                    .               *                     *\n&W";
    char* sandstorm_description =
        "&O               .             .                       .\n&O.        .        .                .            .            .\n&O	           .                 .                                 .\n&O	  .        .      .          .      .        .  .          .\n&x&Y&OA howling sandstorm whips up dust and sand, obscuring your vision.\n&O *                 .                .        .         .        .\n&O      .       .        .                    .               \n&O                    .              .    .                   .\n&O      .       .                 .                    .               	 \n&O";

    if ( ch->position < POS_SLEEPING )
    {
        ch_println( ch, "&wYou can't see anything but stars!" );
        return;
    }

    if ( ch->position == POS_SLEEPING )
    {
        ch_println( ch, "&wYou can't see anything, you're sleeping!" );
        return;
    }

    //Lydor '08 - Can't look while AFK.

    if ( has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "&WYou must turn off AFK first! Type AFK to toggle it off." );
        return;
    }

    if ( !check_blind( ch, FALSE ) )
        return;

    if ( ( vec = vehicle_from_room( ch->in_room->vnum ) ) != NULL && ( vec->type == WHEELED ||
            ( vec->type == BARGE && !xIS_SET( ch->in_room->flags, ROOM_INDOORS ) && !xIS_SET( ch->in_room->flags, ROOM_SPACECRAFT ) ) ) )
    {
        original = ch->in_room;
        char_from_room_temporary( ch );
        char_to_room( ch, vec->in_room );
        do_look( ch, argument );
        char_from_room_temporary( ch );
        char_to_room( ch, original );
        return;
    }

    if ( !NULLSTR( argument ) && str_cmp( "auto", argument ) )
    {
        STRUCTURE_DATA* stru = find_struct_in_room( ch->in_room, argument );
        if ( stru )
        {
            if ( !NULLSTR( stru->description ) )
                ch_printf( ch, "&wLooking at %s&w you see:\n%s", stru->name, stru->description );
            else
                ch_println( ch, "&w%s&w isn't very interesting to look at.", stru->name );

            if ( xIS_SET( stru->flags, STRUCTFLAG_UNFINISHED ) )
            {
                ch_println( ch, "&YThis structure is still under construction." );
            }
            else
            {
                if ( xIS_SET( stru->exit_flags, EX_ISDOOR ) )
                    ch_println( ch, "&WThe door is %s.", xIS_SET( stru->exit_flags, EX_CLOSED ) ? "closed" : "open" );
                if ( !xIS_SET( stru->exit_flags, EX_CLOSED ) )
                    ch_println( ch, "&WYou can ENTER this structure." );
            }

            return;
        }
    }

    if ( !str_cmp( "datapad", argument ) )
    {
        TIMER* timer = get_timerptr( ch, TIMER_DO_FUN );
        if ( timer && !str_cmp( timer->buffer->func, "do_monitor_camera" ) )
        {
            tap = ( TAP_DATA* )timer->buffer->buf1;
            if ( is_disrupted( ch, TAP_COMM, true ) )
            {
                ch_println( ch, "&RAll you see is static!" );
                return;
            }

            EXIT_DATA* prevblockexit = ch->block;
            char blockbuf[MSL];

            if ( prevblockexit != NULL )
            {
                snprintf( blockbuf, MSL, "is blocking the %s exit.", dir_name[prevblockexit->vdir] );
            }

            ROOM_INDEX_DATA* was_room = ch->in_room;
            char_from_room_temporary( ch );
            char_to_room( ch, ( ROOM_INDEX_DATA* )tap->tap_target );
            do_look( ch, "auto" );
            char_from_room_temporary( ch );
            char_to_room( ch, was_room );

            if ( prevblockexit != NULL )
            {
                action_set_ex( ch, NULL, blockbuf, NULL, 0, AS_LOCK );
                ch->block = prevblockexit;
            }

            return;
        }

        //fall through
    }

    if ( ( tship = get_ship_from_cockpit( ch->in_room ) ) == NULL && !NULLSTR( argument ) )
        tship = ship_in_room( ch->in_room, argument );
    else
        tship = NULL;

    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( arg1[0] == '\0' || !str_cmp( arg1, "auto" ) )
    {
        if ( !check_smoke( ch, FALSE ) )
        {
            if ( !IS_NPC( ch ) && ( IS_AFFECTED( ch, AFF_TRUESIGHT ) || IS_AFFECTED( ch, AFF_INFRARED ) ) )
                show_chars_to_char( ch->in_room, ch );

            return;
        }

        if ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_HOLYLIGHT ) && !IS_AFFECTED( ch, AFF_TRUESIGHT ) && !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) && room_is_dark( ch->in_room ) )
        {
            ch_println( ch, "&zIt is pitch black ... " );    
            show_chars_to_char( ch->in_room, ch );
            return;
        }

        ship = NULL;
        bool sengine = FALSE;
        /* 'look' or 'look auto' */
        send_to_char( "&W", ch );
        send_to_char( ch->in_room->name, ch );
        /* better than relying on lazy builders   Orion */
        TURBOLIFT_DATA* lift = NULL;
        TURBOFLOOR_DATA* floor = NULL;


        if ( ch && ch->in_room )
        {
            lift = get_lift( ch->in_room->vnum );
            floor = get_floor( NULL, ch->in_room->vnum );
        }

        ship = get_ship_from_room( ch->in_room );

        if ( ship && ch->in_room->vnum == ship->engineroom )
            sengine = TRUE;

        ch_printf( ch, " %s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s",
                   xIS_SET( ch->in_room->flags, ROOM_WEAP_ION ) ? "&Y[ION]&w" : "",
                   xIS_SET( ch->in_room->flags, ROOM_WEAP_TURBOLASER ) ? "&Y[TURBO]&w" : "",
                   xIS_SET( ch->in_room->flags, ROOM_HOSPITAL ) ? "&P[HOSPITAL]&w" : "",
                   xIS_SET( ch->in_room->flags, ROOM_HOTEL ) ? "&R[Hotel]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_RECRUIT ) ? "&Y[&OCITIZENSHIP&Y]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_COMMAND ) ? "&C[Command]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_BANK ) ? "&Y[Bank]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_BACTA ) ? "&R[Bacta]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_PACKAGE ) ? "&c[Package]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_BROADCAST ) ? "&C[Broadcast]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_FACTORY ) ? "&G[Workshop]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_LOCKER ) ? "&W[Locker]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) ? "&R[SAFEZONE]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_GARAGE ) ? "&G[Garage]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_LIBRARY ) ? "&p[Library]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_BLACKMARKET ) ? "&z[Blackmarket]" : "",
                   ( ch->skill_level[SMUGGLING_ABILITY] >= 50 && xIS_SET( ch->in_room->flags, ROOM_REFINERY ) ) ? "&z[Refinery]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_SECURITY )
                   && ch->skill_level[SLICER_ABILITY] >= 140 ? "&B[Security]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_TAP_COMM )
                   && ch->skill_level[SLICER_ABILITY] >= 130 ? "&B[Comm Junction]" : "",
                   xIS_SET( ch->in_room->flags, ROOM_TAP_BANK )
                   && ch->skill_level[SLICER_ABILITY] >= 130 ? "&B[Bank Net Junction]" : "",
                   ( lift != NULL ) ? "&Y[Turbolift]" : "",
                   ( floor != NULL ) ? "&Y[Turbolift Landing]" : "",
                   sengine == TRUE ? "&G[ENGINE]&w" : "" );

        if ( ch->desc )
        {
            if ( ( get_trust( ch ) >= LEVEL_IMMORTAL ) && ( has_pcflag( ch, PCFLAG_ROOM ) ) )
            {
                if ( has_pcflag( ch, PCFLAG_ROOMVNUM ) )
                {
                    set_char_color( AT_BLUE, ch );   /* Added 10/17 by Kuran of */
                    send_to_char( "{", ch );   /* SWReality */
                    ch_printf( ch, "%d", ch->in_room->vnum );
                    send_to_char( "}}", ch );
                }

                if ( has_pcflag( ch, PCFLAG_ROOM ) )
                {
                    set_char_color( AT_CYAN, ch );
                    send_to_char( "[", ch );
                    send_to_char( flag_string( &ch->in_room->flags, room_flags ), ch );
                    send_to_char( "]", ch );
                }
            }
        }

        ch_println( ch, "&w" );

        if ( arg1[0] == '\0' || ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_BRIEF ) ) )
        {
            if ( xIS_SET( ch->in_room->flags, ROOM_SNOWSTORM ) && !xIS_SET( ch->in_room->flags, ROOM_INDOORS ) )
                send_to_char ( blizzard_description, ch );
            else if ( xIS_SET( ch->in_room->flags, ROOM_SANDSTORM ) && !xIS_SET( ch->in_room->flags, ROOM_INDOORS ) )
                send_to_char ( sandstorm_description, ch );
            else if ( ( time_info.hour <  6 || time_info.hour > 19 ) && ch->in_room->nightdesc[0] != '\0' )
                send_to_char( ch->in_room->nightdesc, ch );
