            if ( home && home->price > 0 )
                price = home->price;

            ch_println( ch, "&wThis home can be purchased for &Y%d&w credits. (See &khelp buyhome&k)", price );
        }

        if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_AUTOEXIT ) )
            do_exits( ch, "" );

        show_structs_to_char( ch->in_room, ch );
        show_ships_to_char( ch->in_room, ch );
        show_list_to_char( ch->in_room->first_content, ch, FALSE, FALSE );
        show_lifts_to_char( ch );
        show_blockaders_to_char( ch );
        show_lockers_to_char( ch );
        for ( FURN_DATA* furn = ch->in_room->first_furniture; furn; furn = furn->next_in_room )
        {
            if ( !furn->pIndexData )
            {
                bug("Error: furniture without prototype in room %d", ch->in_room->vnum );
                continue;
            }

            ch_println( ch, "&O%s", !NULLSTR( furn->pIndexData->long_desc ) ? furn->pIndexData->long_desc : furn->pIndexData->short_desc );
        }
        show_chars_to_char( ch->in_room, ch );

        if ( ship != NULL )
        {
            HANGAR_DATA* hangar = NULL;
            ESCAPE_DATA* escape = NULL;

            for ( hangar = ship->first_hangar; hangar; hangar = hangar->next )
            {
                if ( hangar->room == ch->in_room )
                {
                    if ( hangar->bayopen )
                        ch_println( ch, "&zThe hangar bay doors are open." );
                    else
                        ch_println( ch, "&zThe hangar bay doors are closed." );
                }
            }

            if ( get_ship_dockroom( ship ) == ch->in_room && ship->dock_state == DOCK_DOCKED && ship->dockship )
            {
                // When a ship is docked, that takes precedence over showing they're in the entrance
                // when the two are the same.
                ch_println( ch, "&zThe docking hatch is open to %s.", ship->dockship->name );
            }
            else if ( ship->entrance == ch->in_room->vnum )
            {
                // When the entrance is also the dockroom, we prefer showing the entrance message.
                if ( xIS_SET( ship->flags, SHIP_VONG ) )
                {
                    if ( ship->hatchopen  )
                        send_to_char( "&zThe hatch membrane is open", ch );
                    else
                        send_to_char( "&zThe hatch membrane is sealed", ch );
                }
                else
                {
                    if ( ship->hatchopen  )
                        send_to_char( "&zThe hatch is open", ch );
                    else
                        send_to_char( "&zThe hatch is closed", ch );
                }

                // GRAL Precision on it being breached.
                if ( xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
                    ch_println( ch, " and it's been breached." );
                else
                    ch_println( ch, "." );
            }
            else if ( ship->dockroom == ch->in_room->vnum )
            {
                // Only show this if it's not also the entrance.
                ch_println( ch, "&zThe docking hatch is closed." );
            }

            for ( escape = ship->first_escape; escape; escape = escape->next )
                if ( escape->room == ch->in_room )
                    ch_println( ch, "&zEscape pods can be accessed from this room." );
        }

        // Ralen copied from above to allow vehicles to also display hatches.
        if ( vehicle_from_room( ch->in_room->vnum ) != NULL )
        {
            if ( vehicle_from_room( ch->in_room->vnum )->entrance == ch->in_room->vnum )
                // Placeholder - certain single room vehicle types, speeders etc, maybe shouldn't display a hatch.
            {
                if ( vehicle_from_room( ch->in_room->vnum )->hatchopen  )
                    send_to_char( "&zThe hatch is open.", ch );
                else
                    send_to_char( "&zThe hatch is closed.", ch );

                //  GRAL Precision on it being breached // Ralen placeholder, flag doesn't exist yet.
                // if ( xIS_SET( vehicle_from_room( ch->in_room->vnum )->flags, VEHICLE_BROKEN_HATCH ) )
                //     ch_println( ch, " and it's been breached." );
                // else
                //     ch_println( ch, "." );
            }
        }

        if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) != NULL && ship->classtype <= FRIGATE_SHIP )
        {
            if ( ship->piloting && ship->piloting->in_room == ch->in_room )
                ch_println( ch, "&z%s %s holding the piloting controls.", ship->piloting != ch ? g_name( ship->piloting, ch ) : "You", ship->piloting != ch ? "is" : "are" );
            else if ( ship->piloting && ship->piloting->in_room != ch->in_room )
                ch_println( ch, "&zThe ship is being piloted from some other room." );
            else
                ch_println( ch, "&zNobody is holding the piloting controls." );
        }

        if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) && is_public( ship ) && ship->charge_price > 0 )
        {
            ch_println( ch, "\n&z[&WRENTAL PRICE: &G%d&z]", ship->charge_price );
        }

        if ( str_cmp( arg1, "auto" ) )
            if ( ( ship = get_ship_from_cockpit( ch->in_room ) ) != NULL || ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL && xIS_SET( ch->in_room->flags, ROOM_VIEWPORT ) ) )
            {

                if ( xIS_SET( ship->flags, SHIP_VONG ) )
                    ch_println( ch, "\n&WThrough the transparent hull membrane you see:" );
                else
                    ch_println( ch, "\n&WThrough the transparisteel windows you see:" );

                // GRAL Bugs happen here.
                if ( ship->starsystem )
                {
                    MISSILE_DATA* missile;
                    SHIP_DATA* target;

                    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
                    {
                        if ( xIS_SET( planet->flags, PLANET_STAR ) )
                            ch_println( ch, "&Y(STAR) %s", planet->name );
                    }

                    for ( planet = ship->starsystem->first_planet; planet; planet = planet->next_in_system )
                    {
                        if ( xIS_SET( planet->flags, PLANET_STAR ) )
                            continue;

                        ch_printf( ch, "&G%s", planet->name );

                        if ( xIS_SET( planet->flags, PLANET_BLOCKADE ) )
                            ch_printf( ch, " &R(Blockaded past %d units)", blockade_effective_dist( planet ) );

                        ch_println( ch, "" );
                    }

                    for ( target = ship->starsystem->first_ship; target; target = target->next_in_starsystem )
                    {
                        if ( target != ship && target->cloakstatus != CLOAK_ON )
                            ch_println( ch, "%s%s%s&z", xIS_SET( target->flags, SHIP_SHATTERED_SPACE ) ? "&024" : "&Y", target->name, target->dock_state == DOCK_DOCKED ? " (Docked)" : "" );
                    }

                    int missile_count_incoming = 0, missile_count_other = 0;

                    for ( missile = ship->starsystem->first_missile; missile; missile = missile->next_in_starsystem )
                    {
                        if ( missile->target == ship )
                            missile_count_incoming++;
                        else
                            missile_count_other++;
                    }

                    if ( missile_count_incoming + missile_count_other > 0 )
                        ch_println( ch, "&Y%d projectiles, %s%d incoming", missile_count_incoming + missile_count_other, missile_count_incoming > 0 ? "&R" : "", missile_count_incoming );
                }
                else if ( ship->location == ship->lastdoc )
                {
                    ROOM_INDEX_DATA* to_room;

                    if ( ( to_room = get_room_index( ship->location ) ) != NULL )
                    {
                        if ( room_is_dark( to_room ) )
                        {
                            set_char_color( AT_DGREY, ch );
                            ch_println( ch, "&z (It is too dark to see outside the cockpit)" );
                            original = ch->in_room;
                            char_from_room_temporary( ch );
                            char_to_room( ch, to_room );
                            char_from_room_temporary( ch );
                            char_to_room( ch, original );
                        }
                        else
                        {
                            curr_ship = ship;
                            ch_println( ch, "" );
                            original = ch->in_room;
                            char_from_room_temporary( ch );
                            char_to_room( ch, to_room );
                            do_glance( ch, "" );
                            char_from_room_temporary( ch );
                            char_to_room( ch, original );
                            curr_ship = NULL;
                        }

                        if ( ship->in_room && !str_cmp( ship->in_room->area->shortname, "limbo.are" ) ) //== 98 || ship->in_room->vnum == 100 || ship->in_room->vnum == 45 || ship->in_room->vnum == 47))
                        {
                            char bugrep[MSL];
                            snprintf( bugrep, MSL, "Player %s in ship %s in limbo!", ch->name, ship->name );

                            if ( !IS_IMMORTAL( ch ) )
                                bug( bugrep );
                        }

                        // ch_println( ch, "\n&R&r&W&RIMMCHAT THIS SHIP NAME TO ROJAN RIGHT NOW: &P%s",ship->name );
                    }
                }
                else if ( ship->shipstate == SHIP_HYPERSPACE )
                {
                    ch_println( ch, "&CThe swirling, blue tunnel of hyperspace." );
                }
            }

        if ( str_cmp( arg1, "auto" ) )
            if ( ( vec = vehicle_from_cockpit( ch->in_room->vnum ) ) != NULL || ( ( vec = vehicle_from_room( ch->in_room->vnum ) ) != NULL && xIS_SET( ch->in_room->flags, ROOM_VIEWPORT ) ) )
            {
                ch_println( ch, "\n&WThrough the transparisteel windows you see:" );

                // GRAL Bugs hide in here
                if ( vec->in_room != NULL )
                {
                    if ( room_is_dark( vec->in_room ) )
                    {
                        set_char_color( AT_DGREY, ch );
                        ch_println( ch, "&z (It is too dark to see outside the vehicle)" );
                    }
                    else
                    {
                        curr_vec = vec;
                        ch_println( ch, "" );
                        original = ch->in_room;
                        char_from_room_temporary( ch );
                        char_to_room( ch, vec->in_room );
                        do_glance( ch, "" );
                        char_from_room_temporary( ch );
                        char_to_room( ch, original );
                        curr_vec = NULL;
                    }

                    if ( vec->in_room && !str_cmp( vec->in_room->area->shortname, "limbo.are" ) )
                        //if (vec->in_room && (vec->in_room->vnum == 98 || vec->in_room->vnum == 100 || vec->in_room->vnum == 45 || vec->in_room->vnum == 47))
                    {
                        char bugrep[MSL];
                        snprintf( bugrep, MSL, "Player %s in vehicle %s in limbo!", ch->name, vec->name );

                        if ( !IS_IMMORTAL( ch ) )
                            bug( bugrep );
                    }

                    //               ch_println( ch, "\n&R&r&W&RIMMCHAT THIS VEHICLE NAME TO ROJAN RIGHT NOW: &P%s",vec->name );
                }
            }

        if ( str_cmp( arg1, "auto" ) && xIS_SET( ch->in_room->flags, ROOM_VIEWPORT ) )
        {
            STRUCTURE_DATA* stru = structure_from_room( ch->in_room->vnum );
            if ( stru )
            {
                ch_println( ch, "" );
                original = ch->in_room;
                ch_println( ch, "&WThrough the window you can see...&w" );
                char_from_room_temporary( ch );
                char_to_room( ch, get_room_index( stru->in_room ) );
                do_glance( ch, "" );
                char_from_room_temporary( ch );
                char_to_room( ch, original );
            }
        }

        lua_trigger_on_room_look( ch->in_room, ch, "" );
        return;
    }

    if ( !str_cmp( arg1, "under" ) )
    {
        int count;

        /* 'look under' */
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&wLook beneath what?" );
            return;
        }

        if ( ( obj = get_obj_here( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "&wYou do not see that here." );
            return;
        }

        if ( ch->carry_weight + obj->weight > can_carry_w( ch ) )
        {
            ch_println( ch, "&wIt's too heavy for you to look under." );
            return;
        }

        count = obj->count;
        obj->count = 1;
        act( AT_PLAIN, "You lift $p and look beneath it:", ch, obj, NULL, TO_CHAR );
        act( AT_PLAIN, "$n lifts $p and looks beneath it:", ch, obj, NULL, TO_ROOM );
        obj->count = count;

        if ( IS_OBJ_STAT( obj, ITEM_COVERING ) )
            show_list_to_char( obj->first_content, ch, TRUE, TRUE );
        else
            ch_println( ch, "&wNothing." );

        lua_trigger_on_obj_examine( obj, ch );
        oprog_examine_trigger( ch, obj );
        return;
    }

    if ( !str_cmp( arg1, "out" ) )
    {
        ship = NULL;
        ROOM_INDEX_DATA* rtmp = NULL, *rcurr = NULL;

        if ( ( ship = ship_from_entrance( ch->in_room ) ) == NULL )
        {
            ch_println( ch, "&wYou aren't at a hatch!" );
            return;
        }

        if ( ship->shipstate != SHIP_DOCKED &&
                ship->shipstate != SHIP_HOVER &&
                ship->shipstate != SHIP_HOVERLAUNCH &&
                ship->shipstate != SHIP_HOVERLAND )
        {
            ch_println( ch, "&wYou need to be landed in order to open the hatch! Much less look out!" );
            return;
        }

        if ( !ship->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
        {
            ch_println( ch, "&wThe hatch is closed!" );
            return;
        }

        if ( ( rtmp = get_room_index( ship->location ) ) == NULL )
        {
            ch_println( ch, "&wSomething seems very odd..." );
            return;
        }

        rcurr = ch->in_room;
        char_from_room_temporary( ch );
        char_to_room( ch, rtmp );
        do_look( ch, "auto" );
        char_from_room_temporary( ch );
        char_to_room( ch, rcurr );
        act( AT_PLAIN, "$n looks out the ship's hatch.", ch, NULL, NULL, TO_ROOM );
        return;
    }

    /* Looking into ships */
    if ( !str_cmp( arg1, "in" ) || !str_cmp( arg1, "into" ) )
    {
        ship = NULL;

        if ( ( ship = ship_in_room( ch->in_room, arg2 ) ) != NULL )
        {
            ROOM_INDEX_DATA* rtmp, * rcurr;

            // GRAL Getting a weird desynch between the two
            // Could yield info that the hatch is breached.
            if ( !ship->hatchopen && !xIS_SET( ship->flags, SHIP_BROKEN_HATCH ) )
            {
                ch_println( ch, "&wThe hatch is closed!" );
                return;
            }

            if ( ( rtmp = get_room_index( ship->entrance ) ) == NULL )
            {
                ch_println( ch, "&wSomething seems very odd about that ship..." );
                return;
            }

            rcurr = ch->in_room;
            char_from_room_temporary( ch );
            char_to_room( ch, rtmp );
            do_look( ch, "auto" );
            char_from_room_temporary( ch );
            char_to_room( ch, rcurr );
            return;
        }
    }

    if ( !str_cmp( arg1, "i" ) || !str_cmp( arg1, "in" ) )
    {
        /* 'look in' */
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "Look in what?" );
            return;
        }

        if ( ( obj = get_obj_here( ch, arg2 ) ) == NULL  && ( locker = get_open_locker( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "You do not see that here." );
            return;
        }
        if ( obj )
            itemcontents( ch, obj, TRUE );
        else
            show_locker_to_char( ch, locker );

        return;
    }

    if ( ( pdesc = get_extra_descr( arg1, ch->in_room->first_extradesc ) ) != NULL )
    {
        send_to_char( pdesc, ch );
        return;
    }

    door = get_door( arg1 );

    if ( ( pexit = find_door( ch, arg1, TRUE ) ) != NULL )
    {
        if ( pexit->keyword )
        {
            if ( xIS_SET( pexit->flags, EX_CLOSED ) )
            {
                if ( xIS_SET( pexit->flags, EX_SECRET )
                        &&   door != -1 )
                    ch_println( ch, "Nothing special there." );
                else
                    act( AT_PLAIN, "The $d is closed.", ch, NULL, !NULLSTR( pexit->keyword ) ? pexit->keyword : xIS_SET( pexit->flags, EX_WINDOW ) ? "window" : "door", TO_CHAR );

                return;
            }

            if ( xIS_SET( pexit->flags, EX_BASHED ) )
                act( AT_RED, "The $d has been bashed from its hinges!", ch, NULL, pexit->keyword, TO_CHAR );
        }

        if ( pexit->description && pexit->description[0] != '\0' )
            send_to_char( pexit->description, ch );
        else
            ch_println( ch, "Nothing special there." );

        /*
            Ability to look into the next room            -Thoric
        */
        if ( pexit->to_room
                && ( IS_AFFECTED( ch, AFF_SCRYING )
                     ||   xIS_SET( pexit->flags, EX_xLOOK )
                     ||   get_trust( ch ) >= LEVEL_IMMORTAL ) )
        {
            if ( !xIS_SET( pexit->flags, EX_xLOOK )
                    &&    get_trust( ch ) < LEVEL_IMMORTAL )
            {
                set_char_color( AT_MAGIC, ch );
                ch_println( ch, "You attempt to scry..." );

                /*  Change by Narn, Sept 96 to allow characters who don't have the
                    scry spell to benefit from objects that are affected by scry.
                */
                if ( !IS_NPC( ch ) )
                {
                    int percent = get_learned_pct( ch,  cache_skill( "scry", &skill_scry )  );

                    if ( !percent )
                        percent = 99;

                    if (  number_percent( ) > percent )
                    {
                        ch_println( ch, "You fail." );
                        return;
                    }
                }
            }

            if ( room_is_private( ch, pexit->to_room )
                    &&   get_trust( ch ) < sysdata.level_override_private )
            {
                set_char_color( AT_WHITE, ch );
                ch_println( ch, "That room is private buster!" );
                return;
            }

            original = ch->in_room;

            if ( pexit->distance > 1 )
            {
                ROOM_INDEX_DATA* to_room;

                if ( ( to_room = generate_exit( ch->in_room, &pexit ) ) != NULL )
                {
                    char_from_room_temporary( ch );
                    char_to_room( ch, to_room );
                }
                else
                {
                    char_from_room_temporary( ch );
                    char_to_room( ch, pexit->to_room );
                }
            }
            else
            {
                char_from_room_temporary( ch );
                char_to_room( ch, pexit->to_room );
            }

            do_look( ch, "auto" );
            char_from_room_temporary( ch );
            char_to_room( ch, original );
        }

        return;
    }
    else if ( door != -1 )
    {
        ch_println( ch, "Nothing special there." );
        return;
    }

    if ( ( victim = get_char_room( ch, arg1 ) ) != NULL && can_see( ch, victim ) )
    {
        show_char_to_char_1( victim, ch );
        lua_trigger_on_ch_look( victim, ch );
        return;
    }

    /* finally fixed the annoying look 2.obj desc bug    -Thoric */
    number = number_argument( arg1, arg );

    for ( cnt = 0, obj = ch->last_carrying; obj; obj = obj->prev_content )
    {
        if ( can_see_obj( ch, obj ) )
        {
            pdesc = get_extra_descr( arg, obj->first_extradesc );

            if ( !NULLSTR( pdesc ) )
            {
                if ( ( cnt += obj->count ) < number )
                    continue;

                send_to_char( pdesc, ch );
                lua_trigger_on_obj_examine( obj, ch );
                oprog_examine_trigger( ch, obj );
                return;
            }

            if ( !xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
            {
                pdesc = get_extra_descr( arg, obj->pIndexData->first_extradesc );

                if ( !NULLSTR( pdesc ) )
                {
                    if ( ( cnt += obj->count ) < number )
                        continue;

                    send_to_char( pdesc, ch );
                    lua_trigger_on_obj_examine( obj, ch );
                    oprog_examine_trigger( ch, obj );
                    return;
                }
            }

            if ( nifty_is_name_prefix( arg, obj->name ) )
            {
                if ( ( cnt += obj->count ) < number )
                    continue;

                send_full_obj_desc( ch, obj, true );
                return;
            }
        }
    }

    for ( obj = ch->in_room->last_content; obj; obj = obj->prev_content )
    {
        if ( can_see_obj( ch, obj ) )
        {
            TERMINAL_DATA* terminal = NULL;
            pdesc = get_extra_descr( arg, obj->first_extradesc );

            if ( !NULLSTR( pdesc ) )
            {
                if ( ( cnt += obj->count ) < number )
                    continue;

                send_to_char( pdesc, ch );
                lua_trigger_on_obj_examine( obj, ch );
                oprog_examine_trigger( ch, obj );
                if ( ( terminal = get_terminal( obj ) ) != NULL )
                    terminal->mail_terminal ? do_mail( ch, "list " ) : do_message( ch, "list" );
                return;
            }

            if ( !xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
            {
                pdesc = get_extra_descr( arg, obj->pIndexData->first_extradesc );

                if ( !NULLSTR( pdesc ) )
                {
                    if ( ( cnt += obj->count ) < number )
                        continue;

                    send_to_char( pdesc, ch );
                    lua_trigger_on_obj_examine( obj, ch );
                    oprog_examine_trigger( ch, obj );
                    if ( ( terminal = get_terminal( obj ) ) != NULL )
                        terminal->mail_terminal ? do_mail( ch, "list " ) : do_message( ch, "list" );
                    return;
                }
            }

            if ( nifty_is_name_prefix( arg, obj->name ) )
            {
                if ( ( cnt += obj->count ) < number )
                    continue;

                send_full_obj_desc( ch, obj, true );
                if ( ( terminal = get_terminal( obj ) ) != NULL )
                    terminal->mail_terminal ? do_mail( ch, "list " ) : do_message( ch, "list" );
                return;
            }
        }
    }

    locker = get_open_locker( ch, arg );
    if ( locker )
    {
        show_locker_to_char( ch, locker );
        return;
    }

    if ( tship )
    {
        do_info( ch, tship->name );
        return;
    }

    FURN_DATA* furn = get_furniture( ch, arg );
    if ( furn )
    {
        ch_println( ch, "&w%s", !NULLSTR( furn->pIndexData->full_desc ) ? furn->pIndexData->full_desc : !NULLSTR( furn->pIndexData->long_desc ) ? furn->pIndexData->long_desc : furn->pIndexData->short_desc );
        return;
    }

    SHIP_DATA* vship = NULL, *tvship = NULL;

    if ( ch && ch->in_room && !NULLSTR( arg1 ) &&
    ( ( vship = get_ship_from_cockpit( ch->in_room ) ) != NULL || ( ( vship = get_ship_from_room( ch->in_room ) ) != NULL && xIS_SET( ch->in_room->flags, ROOM_VIEWPORT ) ) )
    && vship->starsystem != NULL && vship->shipstate != SHIP_HYPERSPACE && ( tvship = get_ship( arg1 ) ) != NULL &&
    tvship->starsystem == vship->starsystem )
    {
        ch_println( ch, "&wThrough the transparisteel windows you see a ship in the distance..." );
        if ( vector_distance( &tvship->vpos, &vship->vpos ) > 2000 )
            ch_println( ch, "&w... but it's too far away for you to make out any details." );
        else if ( NULLSTR( tvship->description ) && ( !tvship->template || NULLSTR( tvship->template->description ) ) )
            ch_println( ch, "&w... but there aren't a lot of distinguishing features to it." );
        else
            ch_println( ch, "\n%s", !NULLSTR( tvship->description ) ? tvship->description : tvship->template->description );
        return;
    }

    if ( !lua_trigger_on_room_look( ch->in_room, ch, arg ) )
        ch_println( ch, "You do not see that here." );

    return;
}

void send_full_obj_desc( CHAR_DATA* ch, OBJ_DATA* obj, bool include_name )
{
    if ( !ch || !obj )
        return;

    char* pdesc;
    pdesc = get_extra_descr( obj->name, obj->first_extradesc );

    if ( !pdesc && !xIS_SET( obj->extra_flags, ITEM_CRAFTED ) )
        pdesc = get_extra_descr( obj->name, obj->pIndexData->first_extradesc );

    if ( !NULLSTR( pdesc ) )
        send_to_char( pdesc, ch );

    bool ldesc = lua_trigger_on_obj_examine( obj, ch );

    if ( NULLSTR( pdesc ) && !ldesc )
    {
        if ( include_name )
            act( AT_PLAIN, "You see nothing special about $p.", ch, obj, NULL, TO_CHAR );
        else
            act( AT_PLAIN, "You see nothing special about it.", ch, NULL, NULL, TO_CHAR );
    }

    oprog_examine_trigger( ch, obj );
    return;
}

void itemcontents( CHAR_DATA* ch, OBJ_DATA* obj, bool doexaprog )
{
    int count;

    switch ( obj->item_type )
    {
        default:
            ch_println( ch, "That is not a container." );
            break;

        case ITEM_CHEMICAL:
            if ( obj->value[4] == CHEM_DYE )
            {
                int old = 0;
                old = ch->haircolor;
                ch->haircolor = obj->value[3];
                ch_println( ch, "The dye is %s.", get_haircolor( ch->haircolor ) );
                ch->haircolor = old;
            }

            break;

        case ITEM_DRINK_CON:
            if ( obj->value[1] <= 0 )
            {
                ch_println( ch, "It is empty." );
            }
            else if ( obj->value[1] < ( obj->value[0] / 4 ) )
            {
                ch_println( ch, "It's less than a quarter full of a %s liquid.", liq_table[obj->value[2]].liq_color );
            }
            else if ( obj->value[1] < ( obj->value[0] / 2 ) )
            {
                ch_println( ch, "It's less than half full of a %s liquid.", liq_table[obj->value[2]].liq_color );
            }
            else if ( obj->value[1] < ( ( obj->value[0] / 4 ) * 3 ) )
            {
                ch_println( ch, "It's just under three-quarters full of a %s liquid.", liq_table[obj->value[2]].liq_color );
            }
            else if ( obj->value[1] < obj->value[0] )
            {
                ch_println( ch, "It's nearly full of a %s liquid.", liq_table[obj->value[2]].liq_color );
            }
            else if ( obj->value[1] == obj->value[1] )
            {
                ch_println( ch, "It's full of a %s liquid.", liq_table[obj->value[2]].liq_color );
            }

            if ( doexaprog )
            {
                lua_trigger_on_obj_examine( obj, ch );
                oprog_examine_trigger( ch, obj );
            }

            break;

        case ITEM_CONTAINER:
        case ITEM_CORPSE_NPC:
        case ITEM_ASHES:
        case ITEM_CORPSE_PC:
        case ITEM_DROID_CORPSE:
        case ITEM_HOLSTER:
            if ( IS_SET( obj->value[1], CONT_CLOSED ) )
            {
                act( AT_PLAIN, "You can't, as $p is closed.", ch, obj, NULL, TO_CHAR );
                break;
            }

            count = obj->count;
            obj->count = 1;
            act( AT_PLAIN, "$p contains:", ch, obj, NULL, TO_CHAR );
            obj->count = count;
            show_list_to_char( obj->first_content, ch, TRUE, TRUE );

            if ( doexaprog )
            {
                lua_trigger_on_obj_examine( obj, ch );
                oprog_examine_trigger( ch, obj );
            }

            break;
    }

    return;
}

void itemcapacity( CHAR_DATA* ch, OBJ_DATA* obj )
{
    if ( !ch || !obj )
        return;

    int contents = 0;

    contents = get_obj_weight( obj ) / obj->count;

    switch ( obj->item_type )
    {
        case ITEM_CONTAINER:
            if ( contents <= 0 || !obj->first_content )
            {
                ch_println( ch, "%s is empty.", obj->short_descr );
            }
            else if ( contents < ( obj->value[0] / 4 ) )
            {
                ch_println( ch, "%s is less than a quarter full.", obj->short_descr );
            }
            else if ( contents < ( obj->value[0] / 2 ) )
            {
                ch_println( ch, "%s is less than half full.", obj->short_descr );
            }
            else if ( contents < ( ( obj->value[0] / 4 ) * 3 ) )
            {
                ch_println( ch, "%s is just under three-quarters full.", obj->short_descr );
            }
            else if ( contents < obj->value[0] )
            {
                ch_println( ch, "%s is nearly full.", obj->short_descr );
            }
            else if ( contents == obj->value[0] )
            {
                ch_println( ch, "%s is full.", obj->short_descr );
            }
            else if ( contents > obj->value[0] )
            {
                ch_println( ch, "%s is overfull.", obj->short_descr );
            }
            break;

        default:
            ch_println( ch, "That is not a container." );
            break;
    }

    return;
}

void show_condition( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL];
    char color_code[10];
    int percent;
    int x = 0, y = 0;
    int top_wound = 0;
    int max_wounds = 0;

    if ( victim->max_hit > 0 )
        percent = ( int )( ( 100.0 * ( double )( victim->hit ) ) / ( double )( victim->max_hit ) );
    else
        percent = -1;

    if ( percent >= 100 )
        strlcpy( color_code, "&007", 10 );
    else if ( percent >=  90 )
        strlcpy( color_code, "&187", 10 );
    else if ( percent >=  80 )
        strlcpy( color_code, "&185", 10 );
    else if ( percent >=  70 )
        strlcpy( color_code, "&180", 10 );
    else if ( percent >=  60 )
        strlcpy( color_code, "&216", 10 );
    else if ( percent >=  50 )
        strlcpy( color_code, "&210", 10 );
    else if ( percent >=  40 )
        strlcpy( color_code, "&209", 10 );
    else if ( percent >=  30 )
        strlcpy( color_code, "&203", 10 );
    else if ( percent >=  20 )
        strlcpy( color_code, "&009", 10 );
    else if ( percent >=  10 )
        strlcpy( color_code, "&160", 10 );
    else
        strlcpy( color_code, "&124", 10 );

    strlcpy( buf, color_code, 10 );
    strlcat( buf, PERS( victim, ch ), MSL );
    strlcat( buf, color_code, MSL );

    if ( IS_NPC ( victim ) && ( xIS_SET( victim->act, ACT_DROID ) ||
                                xIS_SET( victim->act, ACT_PET ) ) )
    {
        if ( percent >= 100 )
            strlcat( buf, " is in perfect condition.\n" , MSL );
        else if ( percent >=  90 )
            strlcat( buf, " is slightly scratched.\n", MSL );
        else if ( percent >=  80 )
            strlcat( buf, " has a few scrapes.\n"    , MSL );
        else if ( percent >=  70 )
            strlcat( buf, " has some dents.\n"        , MSL );
        else if ( percent >=  60 )
            strlcat( buf, " has a couple of holes in its plating.\n"   , MSL );
        else if ( percent >=  50 )
            strlcat( buf, " has many broken pieces.\n", MSL );
        else if ( percent >=  40 )
            strlcat( buf, " has many exposed circuits.\n"   , MSL );
        else if ( percent >=  30 )
            strlcat( buf, " is leaking oil.\n"  , MSL );
        else if ( percent >=  20 )
            strlcat( buf, " has smoke coming out of it.\n"      , MSL );
        else if ( percent >=  10 )
            strlcat( buf, " is almost completely broken.\n"       , MSL );
        else
            strlcat( buf, " is about to EXPLODE.\n"             , MSL );

        strlcat( buf, "&w", MSL );
    }
    else
    {
        if ( percent >= 100 )
            strlcat( buf, " is in perfect health.\n" , MSL );
        else if ( percent >=  90 )
            strlcat( buf, " is slightly scratched.\n", MSL );
        else if ( percent >=  80 )
            strlcat( buf, " has a few bruises.\n"    , MSL );
        else if ( percent >=  70 )
            strlcat( buf, " has some cuts.\n"        , MSL );
        else if ( percent >=  60 )
            strlcat( buf, " has several wounds.\n"   , MSL );
        else if ( percent >=  50 )
            strlcat( buf, " has many nasty wounds.\n", MSL );
        else if ( percent >=  40 )
            strlcat( buf, " is bleeding freely.\n"   , MSL );
        else if ( percent >=  30 )
            strlcat( buf, " is covered in blood.\n"  , MSL );
        else if ( percent >=  20 )
            strlcat( buf, " is leaking guts.\n"      , MSL );
        else if ( percent >=  10 )
            strlcat( buf, " is almost dead.\n"       , MSL );
        else if ( percent >    0 )
            strlcat( buf, " is DYING.\n"             , MSL );
        else
            strlcat( buf, " is unconscious.\n"        , MSL );

        strlcat( buf, "&w", MSL );

        if ( !obj_mask( victim ) )
        {
            for ( x = 0; x <= MAX_MED; x++ )
            {
                if ( xIS_SET( victim->w_wound, x ) )
                {
                    top_wound = x;
                    max_wounds++;
                }
            }

            x = 0;
            y = 0;

            for ( x = 0; x <= MAX_MED; x++ )
            {
                if ( xIS_SET( victim->w_wound, x ) )
                {
                    if ( y == 0 )
                    {
                        strlcat( buf, capitalize_first( PERS( victim, ch ) ), MSL );
                        strlcat( buf, " is bleeding from their ", MSL );
                    }

                    if ( max_wounds == 1 )
                    {
                        strlcat( buf, part_name( x ), MSL );
                        strlcat( buf, ".\n", MSL );
                    }
                    else if ( x == top_wound )
                    {
                        strlcat( buf, "and ", MSL );
                        strlcat( buf, part_name( x ), MSL );
                        strlcat( buf, ".\n", MSL );
                    }
                    else
                    {
                        strlcat( buf, part_name( x ), MSL );
                        strlcat( buf, ", ", MSL );
                    }

                    y++;
                }
            }
        }
    }

    buf[0] = UPPER( buf[0] );
    send_to_char( buf, ch );
}

void show_appearance( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL];
    if ( !IS_NPC( victim ) )
    {
        snprintf( buf, MSL, "%s is %s.\n", g_name( victim, ch ), make_greet_desc( victim, NULL ) );
        send_to_char( buf, ch );
    }

    if ( is_naked( victim ) && ( !victim->spirit ) && !IS_NPC( victim ) )
    {
        snprintf( buf, MSL, "%s is NAKED!\n", g_name( victim, ch ) );
        send_to_char( buf, ch );
    }
}

/*  A much simpler version of look, this function will show you only
    the condition of a mob or pc, or if used without an argument, the
    same you would see if you enter the room and have config +brief.
    -- Narn, winter '96
*/
CMDF do_glance( CHAR_DATA* ch, char* argument )
{
    char arg1 [MIL];
    CHAR_DATA* victim;

    if ( !ch->desc )
        return;

    if ( ch->position < POS_SLEEPING )
    {
        ch_println( ch, "You can't see anything but stars!" );
        return;
    }

    if ( ch->position == POS_SLEEPING )
    {
        ch_println( ch, "You can't see anything, you're sleeping!" );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_AFK ) )
    {
        ch_println( ch, "&WYou must turn off AFK first! Type AFK to toggle it off." );
        return;
    }

    if ( !check_blind( ch, FALSE ) )
        return;

    argument = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) )
    {
        bool has_brief = has_pcflag( ch, PCFLAG_BRIEF );
        set_pcflag( ch, PCFLAG_BRIEF );
        do_look( ch, "auto" );

        if ( !has_brief )
            remove_pcflag( ch, PCFLAG_BRIEF );

        return;
    }

    if ( ( victim = get_char_room( ch, arg1 ) ) == NULL )
    {
        send_to_char( "They're not here.", ch );
        return;
    }
    else
    {
        if ( can_see( victim, ch ) )
        {
            act( AT_ACTION, "$n glances at you.", ch, NULL, victim, TO_VICT    );
            act( AT_ACTION, "$n glances at $N.",  ch, NULL, victim, TO_NOTVICT );
        }

        show_condition( ch, victim );
        show_appearance( ch, victim );
        return;
    }

    return;
}

CMDF do_examine( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj = NULL;
    LOCKER_DATA* locker = NULL;

    if ( !argument )
    {
        bug( "do_examine: null argument.", 0 );
        return;
    }

    if ( !ch )
    {
        bug( "do_examine: null ch.", 0 );
        return;
    }

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Examine what?" );
        return;
    }

    obj = get_obj_here( ch, arg );
    locker = get_open_locker( ch, arg );
    STRUCTURE_DATA* stru = find_struct_in_room( ch->in_room, arg );

    if ( obj == NULL && locker == NULL && stru == NULL )
    {
        ch_println( ch, "You do not see that here." );
        return;
    }

    if ( obj )
    {
        ch_println( ch, "&zThis is &C%s&z.&w", obj->short_descr );
        itemexamine( ch, obj );
    }
    else if ( locker )
    {
        show_locker_to_char( ch, locker );
    }
    else if ( stru )
    {
        ch_println( ch, "&zThis is &C%s&z.&w", stru->name );
        if ( !NULLSTR( stru->description ) )
            ch_println( ch, stru->description );
        ch_println( ch, "" );

        if ( xIS_SET( stru->flags, STRUCTFLAG_UNFINISHED ) )
        {
            ch_println( ch, "&zThis structure is still under construction." );
            ch_println( ch, "&zComponents until completion:" );
            ch_println( ch, "&zFraming:   &C%d&z", stru->framing_needed );
            ch_println( ch, "&zDuracrete: &C%d&z", stru->duracrete_needed );
            ch_println( ch, "&zWiring:    &C%d&z", stru->wiring_needed );
        }
        else
        {
            if ( stru->maxhull > 0 )
            {
                int hull_pct = stru->hull * 100 / stru->maxhull;
                if ( hull_pct < 25 )
                    ch_println( ch, "&RThis structure looks like it might collapse at any moment." );
                else if ( hull_pct < 50 )
                    ch_println( ch, "&rThis structure is heavily damaged." );
                else if ( hull_pct < 75 )
                    ch_println( ch, "&YThis structure is noticeably damaged." );
                else if ( hull_pct < 100 )
                    ch_println( ch, "&OThis structure has suffered some wear." );
                else
                    ch_println( ch, "&wThis structure is in perfect condition." );
            }

            if ( xIS_SET( stru->exit_flags, EX_ISDOOR ) )
                ch_println( ch, "&WThe door is %s.", xIS_SET( stru->exit_flags, EX_CLOSED ) ? "closed" : "open" );
            if ( !xIS_SET( stru->exit_flags, EX_CLOSED ) )
                ch_println( ch, "&WYou can ENTER this structure." );
        }
    }
    return;
}

void itemexamine( CHAR_DATA* ch, OBJ_DATA* obj )
{
    TERMINAL_DATA* terminal;
    sh_int dam;
    AFFECT_DATA* paf;
    CYBER_TYPE_DATA* cyber;
    bool identified = FALSE;
    char* tmpbuf;
    char buf[MSL], drinkname[MIL], ingredients[MSL];

    if ( !ch )
    {
        bug( "itemexamine: null ch.", 0 );
        return;
    }

    if ( !obj )
    {
        bug( "itemexamine: null obj.", 0 );
        return;
    }

    send_full_obj_desc( ch, obj, false );

    if ( ( terminal = get_terminal( obj ) ) != NULL )
    {
        terminal->mail_terminal ? do_mail( ch, "list " ) : do_message( ch, "list" );
        return;
    }

    switch ( obj->item_type )
    {
        default:
            break;

        case ITEM_PERMIT:
            ch_printf( ch, ( obj->blueprint ? obj->blueprint : "Not a valid permit." ) );
            break;

        case ITEM_BLUEPRINT:
            if ( !xIS_EMPTY( obj->wear_flags ) )
            {
                if ( !obj->blueprint )
                {
                    bug( "%s/%d has no blueprint!", obj->name, obj->pIndexData->vnum );
                    break;
                }

                tmpbuf = obj->blueprint;
                tmpbuf = one_argument( tmpbuf, buf );
                ch_println( ch, "%s", obj->short_descr );
                ch_println( ch, "&zSchematics for: &C%s", tmpbuf );
                ch_println( ch, "&zHull:      &C%d", obj->value[1] );
                ch_println( ch, "&zCircuits:  &C%d", obj->value[2] );
                ch_println( ch, "&zWeapons:   &C%d", obj->value[3] );
                ch_println( ch, "&zEngines:   &C%d", obj->value[4] );
                break;
            }
            else
            {
                char buf2[MSL];
                bool yours = FALSE;

                if ( !obj->blueprint )
                {
                    bug( "%s/%d has no blueprint!", obj->name, obj->pIndexData->vnum );
                    break;
                }

                tmpbuf = obj->blueprint;
                tmpbuf = one_argument( tmpbuf, buf );
                tmpbuf = one_argument( tmpbuf, buf2 );
                ch_println( ch, "&zThis looks like the frame for a %s", tmpbuf );

                if ( !str_cmp( buf, ch->name ) )
                {
                    yours = TRUE;
                    ch_println( ch, "&zThis ship belongs to you." );
                }
                else if ( IS_CLANNED( ch ) && !str_cmp( buf, ch->pcdata->clan->name ) )
                {
                    yours = TRUE;
                    ch_println( ch, "&zThis ship belongs to your clan." );
                }

                if ( !IS_NPC( ch ) )
                {
                    if (  ch->main_ability == ENGINEERING_ABILITY || ( yours ) || ch->top_level >= LEVEL_HERO )
                    {
                        ch_println( ch, "Components till completion:" );
                        ch_println( ch, "&zHull:      &C%d", obj->value[1] );
                        ch_println( ch, "&zCircuits:  &C%d", obj->value[2] );
                        ch_println( ch, "&zWeapons:   &C%d", obj->value[3] );
                        ch_println( ch, "&zEngines:   &C%d", obj->value[4] );
                        break;
                    }
                }

                break;
            }

        case ITEM_FABRIC:
            if ( xIS_SET( obj->extra_flags, ITEM_SMALL_SIZE ) )
                ch_println( ch, "This item is a SMALL size." );
            else if ( xIS_SET( obj->extra_flags, ITEM_HUMAN_SIZE ) )
                ch_println( ch, "This item is HUMAN sized." );
            else if ( xIS_SET( obj->extra_flags, ITEM_LARGE_SIZE ) )
                ch_println( ch, "This item is a LARGE size." );
            else if ( xIS_SET( obj->extra_flags, ITEM_HUTT_SIZE ) )
                ch_println( ch, "This item is big enough for a HUTT." );

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "construction", &skill_construction ) ) >= 60 )
                identified = TRUE;

            break;

        case ITEM_CRYSTAL:
            if ( IS_NPC( ch ) || get_learned_pct( ch, cache_skill( "minerals", &skill_minerals ) ) < 60 )
            {
                ch_println( ch, "&zLooks like a crystal." );
                break;
            }

            identified = TRUE;

            if ( obj->value[2] == 1 )
                ch_println( ch, "&zThis crystal can be used for a lightsaber." );
            else
                ch_println( ch, "&zThis crystal can be used for a blaster." );

            break;

        case ITEM_ARMOR:
            if ( obj->value[2] >= 1 && obj->value[4] > 0 && ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "makearmor", &skill_makearmor ) ) > 0 ) )
            {
                int cst = 0, div = 0;

                if ( ch->skill_level[SCIENCE_ABILITY] >= ( LEVEL_HERO / 2 ) )
                {
                    cst = get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) + 5;

                    if ( ( int ) get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) == 100 )
                        cst += number_range( 3, 6 );

                    div = 1;
                    div = 87 - URANGE( 30, ch->skill_level[SCIENCE_ABILITY], 80 );
                    cst /= div;
                }
                else
                {
                    cst = number_range( 3, 25 );
                    div = 1;
                    div = 87 - URANGE( 30, ch->skill_level[SCIENCE_ABILITY], 80 );
                    cst /= div;
                }

                div = ( int ) ( obj->value[4] / ( cst == 0 ? 1 : cst ) );
                ch_println( ch, "&zThis armor is unfinished.\nYou estimate it would take you &C%d&z attempts to finish it.", div );
            }

            if ( xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) && xIS_SET( obj->extra_flags, ITEM_RESTRUNG ) && ( !NULLSTR( obj->blueprint ) ) )
                ch_println( ch, "&zThis armor has been restrung to make the wearer appear as: &C%s", obj->blueprint );
            else if ( xIS_SET( obj->extra_flags, ITEM_RESTRUNG ) )
                ch_println( ch, "&zThis armor has been restrung. Its original appearance was: %s&w", obj->pIndexData->short_descr );

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) > 49 )
                switch ( obj->value[2] )
                {
                    default:
                        break;

                    case 1:
                        ch_println( ch, "&zThis is unenhanced light armor." );
                        break;

                    case 2:
                        ch_println( ch, "&zThis is unenhanced medium armor." );
                        break;

                    case 3:
                        ch_println( ch, "&zThis is unenhanced heavy armor." );
                        break;

                    case 4:
                        ch_println( ch, "&zThis is uncoated light armor." );
                        break;

                    case 5:
                        ch_println( ch, "&zThis is coated light armor with no underlay." );
                        break;

                    case 6:
                        ch_println( ch, "&zThis is light armor with a coating and underlay." );
                        break;

                    case 7:
                        ch_println( ch, "&zThis is uncoated medium armor." );
                        break;

                    case 8:
                        ch_println( ch, "&zThis is coated medium armor with no underlay." );
                        break;

                    case 9:
                        ch_println( ch, "&zThis is medium armor with a coating and underlay." );
                        break;

                    case 10:
                        ch_println( ch, "&zThis is uncoated heavy armor." );
                        break;

                    case 11:
                        ch_println( ch, "&zThis is coated heavy armor with no underlay." );
                        break;

                    case 12:
                        ch_println( ch, "&zThis is heavy armor with a coating and underlay." );
                        break;
                }

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "equipment", &skill_equipment ) ) >= 60 )
                identified = TRUE;

            dam = obj->value[0];
            strlcpy( buf, "&zAs you look more closely, you notice that it is ", MSL );

            if ( dam >= 10 )
                strlcat( buf, "in superb condition.", MSL );
            else if ( dam ==  9 )
                strlcat( buf, "in very good condition.", MSL );
            else if ( dam ==  8 )
                strlcat( buf, "in good shape.", MSL );
            else if ( dam ==  7 )
                strlcat( buf, "showing a bit of wear.", MSL );
            else if ( dam ==  6 )
                strlcat( buf, "a little run down.", MSL );
            else if ( dam ==  5 )
                strlcat( buf, "in need of repair.", MSL );
            else if ( dam ==  4 )
                strlcat( buf, "in great need of repair.", MSL );
            else if ( dam ==  3 )
                strlcat( buf, "in dire need of repair.", MSL );
            else if ( dam ==  2 )
                strlcat( buf, "very badly worn.", MSL );
            else if ( dam ==  1 )
                strlcat( buf, "practically worthless.", MSL );
            else if ( dam <=  0 )
                strlcat( buf, "broken.", MSL );

            strlcat( buf, "\n", MSL );
            send_to_char( buf, ch );

            if ( xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) || xIS_SET( obj->wear_flags, ITEM_WEAR_HEAD ) )
                ch_println( ch, "&zThis %s is %s.", xIS_SET( obj->wear_flags, ITEM_WEAR_ABOUT ) ? "armor" : "helmet", obj->value[5] == 1 ? "covering": "non-covering" );

            if ( xIS_SET( obj->extra_flags, ITEM_SMALL_SIZE ) )
                ch_println( ch, "This item is a SMALL size." );
            else if ( xIS_SET( obj->extra_flags, ITEM_HUMAN_SIZE ) )
                ch_println( ch, "This item is HUMAN sized." );
            else if ( xIS_SET( obj->extra_flags, ITEM_LARGE_SIZE ) )
                ch_println( ch, "This item is a LARGE size." );
            else if ( xIS_SET( obj->extra_flags, ITEM_HUTT_SIZE ) )
                ch_println( ch, "This item is big enough for a HUTT." );

            break;

        case ITEM_WEAPON:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "minerals", &skill_minerals ) ) > 49 &&  xIS_SET( obj->extra_flags, ITEM_CORTOSIS ) )
