                else if ( obj->blaster_setting == BLASTER_HIGH )
                    ch_println( ch, "&zIt is set on &CHIGH&z power." );
                else if ( obj->blaster_setting == BLASTER_NORMAL )
                    ch_println( ch, "&zIt is set on &CNORMAL&z power." );
                else if ( obj->blaster_setting == BLASTER_HALF )
                    ch_println( ch, "&zIt is set on &CHALF&z power." );
                else if ( obj->blaster_setting == BLASTER_LOW )
                    ch_println( ch, "&zIt is set on &CLOW&z power." );
                else if ( obj->blaster_setting == BLASTER_STUN )
                    ch_println( ch, "&zIt is set on &CSTUN&z." );

                ch_println( ch, "&zIt has from &C%d&z to &C%d&z shots remaining.", obj->value[4] / 50, obj->value[4] );
            }
            else if ( obj->value[3] == WEAPON_BOWCASTER )
            {
                ch_println( ch, "&zIt is loaded with &C%d&z/&C%d&z quarrels.", obj->value[4], obj->value[5] );
            }
            else if (     ( obj->value[3] == WEAPON_LIGHTSABER ||
                            obj->value[3] == WEAPON_VIBRO_BLADE ||
                            obj->value[3] == WEAPON_VIBRO_AXE ||
                            obj->value[3] == WEAPON_FORCE_PIKE ) )
            {
                ch_println( ch, "&zIt has &C%d&z/&C%d&z units of charge remaining.", obj->value[4], obj->value[5] );
            }

            if ( xIS_SET( obj->extra_flags, ITEM_TWINBLADE ) )
            {
                ch_println( ch, "&zThe lightsaber has two blades." );
            }

            break;

        case ITEM_FOOD:
            strlcpy( ingredients, get_dvar_string( obj->vars, "ingredients", "NULL" ), MSL );

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "edibles", &skill_edibles ) ) >= 60 && strcmp( ingredients, "NULL" ) )
            {
                ch_println( ch, "&zThis meal was prepared using %s&w", ingredients );
            }

            if ( obj->timer > 0 && obj->value[1] > 0 )
                dam = ( obj->timer * 10 ) / obj->value[1];
            else
                dam = 10;

            strlcpy( buf, "&zAs you examine it carefully you notice that it ", MSL );

            if ( dam >= 10 )
                strlcat( buf, "is fresh.", MSL );
            else if ( dam ==  9 )
                strlcat( buf, "is nearly fresh.", MSL );
            else if ( dam ==  8 )
                strlcat( buf, "is perfectly fine.", MSL );
            else if ( dam ==  7 )
                strlcat( buf, "looks good.", MSL );
            else if ( dam ==  6 )
                strlcat( buf, "looks ok.", MSL );
            else if ( dam ==  5 )
                strlcat( buf, "is a little stale.", MSL );
            else if ( dam ==  4 )
                strlcat( buf, "is a bit stale.", MSL );
            else if ( dam ==  3 )
                strlcat( buf, "smells slightly off.", MSL );
            else if ( dam ==  2 )
