                ch_println( ch, "&zYou notice that it is in the up position." );
            else
                ch_println( ch, "&zYou notice that it is in the down position." );

            break;

        case ITEM_BUTTON:
            if ( IS_SET( obj->value[0], TRIG_UP ) )
                ch_println( ch, "&zYou notice that it is depressed." );
            else
                ch_println( ch, "&zYou notice that it is not depressed." );

            break;

        case ITEM_MEDPAC:
            if ( obj->value[0] > 0 )
                ch_println( ch, "&zRestores &C%d &zhp per second (base).", obj->value[0] );
            break;

        case ITEM_CORPSE_PC:
        case ITEM_CORPSE_NPC:
        {
            sh_int timerfrac = obj->timer;

            if ( obj->item_type == ITEM_CORPSE_PC )
                timerfrac = ( int )obj->timer / 8 + 1;

            switch ( timerfrac )
            {
                default:
                    ch_println( ch, "&zThis corpse has recently been slain." );
                    break;

                case 4:
                    ch_println( ch, "&zThis corpse was slain a little while ago." );
                    break;

                case 3:
                    ch_println( ch, "&zA foul smell rises from the corpse, and it is covered in flies." );
                    break;

                case 2:
                    ch_println( ch, "&zA writhing mass of maggots and decay, you can barely go near this corpse." );
                    break;

                case 1:
                case 0:
                    ch_println( ch, "&zLittle more than bones, there isn't much left of this corpse." );
                    break;
            }
        }

        if ( IS_OBJ_STAT( obj, ITEM_COVERING ) )
            break;

        ch_println( ch, "&zWhen you look inside, you see:" );
        itemcontents( ch, obj, FALSE );
        break;

        case ITEM_ASHES:
        {
            sh_int timerfrac = obj->timer;

            if ( obj->item_type == ITEM_ASHES )
                timerfrac = ( int )obj->timer / 8 + 1;

            switch ( timerfrac )
            {
                default:
                    ch_println( ch, "This seems to be a fairly fresh pile of ash." );
                    break;

                case 4:
                    ch_println( ch, "These remains are still smoking. Fresh kill..." );
                    break;

                case 3:
                    ch_println( ch, "The pile of ashes is cooling slowly, fairly old." );
                    break;

                case 2:
                    ch_println( ch, "The pile of ashes have almost entirely blown away." );
                    break;

                case 1:
                case 0:
                    ch_println( ch, "Theses ashes are little more than a smudge on the ground." );
                    break;
            }
        }

        if ( IS_OBJ_STAT( obj, ITEM_COVERING ) )
            break;

        ch_println( ch, "When you look inside, you see:" );
        itemcontents( ch, obj, FALSE );
        break;

        case ITEM_DROID_CORPSE:
        {
            sh_int timerfrac = obj->timer;

            switch ( timerfrac )
            {
                default:
                    ch_println( ch, "&zThese remains are still smoking." );
                    break;

                case 4:
                    ch_println( ch, "&zThe parts of this droid have cooled down completely." );
                    break;

                case 3:
                    ch_println( ch, "&zThe broken droid components are beginning to rust." );
                    break;

                case 2:
                    ch_println( ch, "&zThe pieces are completely covered in rust." );
                    break;

                case 1:
                case 0:
                    ch_println( ch, "&zAll that remains of it is a pile of crumbling rust." );
                    break;
            }

            break;
        }

        case ITEM_HOLSTER:
        case ITEM_CONTAINER:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "transportation", &skill_transportation ) ) >= 60 )
                identified = TRUE;

            if ( xIS_SET( obj->extra_flags, ITEM_RESTRUNG ) )
                ch_println( ch, "&zThis container has been restrung. Its original appearance was: %s&w", obj->pIndexData->short_descr );

            if ( obj->item_type == ITEM_CONTAINER && !IS_OBJ_STAT( obj, ITEM_COVERING ) )
                itemcapacity( ch, obj );

            if ( !IS_OBJ_STAT( obj, ITEM_COVERING ) )
            {
                ch_println( ch, "&zWhen you look inside, you see:" );
                itemcontents( ch, obj, FALSE );
            }

            break;

        case ITEM_DRINK_CON:
            strlcpy( drinkname, get_dvar_string( obj->vars, "drinkname", "NULL" ), MIL );
            strlcpy( ingredients, get_dvar_string( obj->vars, "ingredients", "NULL" ), MSL );

            if ( strcmp( drinkname, "NULL" ) )
            {
                ch_println( ch, "&WA label fixed to the container reads \"%s&W\"&w", drinkname );
            }

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "edibles", &skill_edibles ) ) >= 60 && strcmp( ingredients, "NULL" ) )
            {
                ch_println( ch, "&zThis drink was prepared using %s&w", ingredients );
            }

            ch_println( ch, "&zWhen you look inside, you see:" );
            itemcontents( ch, obj, FALSE );
            break;

        case ITEM_SHIELD:
            dam = obj->value[0];
            strlcpy( buf, "&zAs you look more closely, you notice that it is ", MSL );

            if ( dam >= 10 )
                strlcat( buf, "in superb condition.", MSL );
            else if ( dam ==  9 )
                strlcat( buf, "in very good condition.", MSL );
            else if ( dam ==  8 )
                strlcat( buf, "in good shape.", MSL );
            else if ( dam ==  7 )
                strlcat( buf, "showing a bit of wear.", MSL );
            else if ( dam ==  6 )
                strlcat( buf, "a little run down.", MSL );
            else if ( dam ==  5 )
                strlcat( buf, "in need of repair.", MSL );
            else if ( dam ==  4 )
                strlcat( buf, "in great need of repair.", MSL );
            else if ( dam ==  3 )
                strlcat( buf, "in dire need of repair.", MSL );
            else if ( dam ==  2 )
                strlcat( buf, "very badly worn.", MSL );
            else if ( dam ==  1 )
                strlcat( buf, "practically worthless.", MSL );
            else if ( dam <=  0 )
                strlcat( buf, "broken.", MSL );

            strlcat( buf, "\n", MSL );
            send_to_char( buf, ch );

            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "electronics", &skill_electronics ) ) >= 60 )
                identified = TRUE;

            ch_println( ch, "&zIt has &C%d&z/&C%d&z units of charge remaining.", obj->value[4], obj->value[5] );
            break;

        case ITEM_DURASTEEL:
        case ITEM_DURAPLAST:
        case ITEM_RARE_METAL:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "construction", &skill_construction ) ) >= 60 )
                identified = TRUE;

            break;

        case ITEM_SYRINGE:
            if ( obj->value[1] <= 0 )
                ch_println( ch, "&zThis syringe is &Cempty&z." );
            else
                ch_println( ch, "&zThis syringe is &Cfull&z." );

            break;

        case ITEM_LIGHT:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "guidance", &skill_guidance ) ) >= 60 )
                identified = TRUE;

            if ( obj->value[2] >= 0 )
                ch_println( ch, "&zIt has &C%d&z units of charge remaining.", obj->value[2] );
            else
                ch_println( ch, "&zThis light can operate indefinitely.." );

            break;

        case ITEM_CYBER:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "medical", &skill_medical ) ) >= 60 )
            {
                cyber = get_cyber( obj->cybertype );

                if ( !cyber )
                {
                    ch_println( ch, "&zThis will enhance a patient with: &CUnknown Cybernetic &R(BUG)&z" );
                }
                else
                {
                    ch_println( ch, "&zThis will enhance a patient with: &C%s&z", cyber->longdesc );
                }
            }

            break;

        case ITEM_SPICE:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "narcotics", &skill_narcotics ) ) >= 60 )
            {
                const FLAG_INFO* flag = flag_from_num( drug_types, obj->value[0] );

                if ( !flag )
                {
                    ch_println( ch, "Unknown Spice &R(BUG)" );
                    bug("%s: unknown spice for obj %d (%d)", FUNC, obj->pIndexData ? obj->pIndexData->vnum : 0, obj->value[0] );
                    break;
                }

                ch_println( ch, "&zThis spice appears to be &C%s", flag->name );
                ch_println( ch, "&zPotency:  &C%d", obj->value[1] );
                ch_println( ch, "&zToxicity: &C%d", obj->value[2] );
            }

            break;

        case ITEM_COMLINK:
            if ( !IS_NPC( ch ) && get_learned_pct( ch, cache_skill( "electronics", &skill_electronics ) ) >= 60 )
                identified = TRUE;

            ch_println( ch, "&zThis comlink is currently tuned to channel &C%d&z.", obj->value[5] );

            if ( IS_SET( obj->value[3], COMM_ENCRYPT ) )
                ch_println( ch, "&zThis comlink is currently encrypted with code &C%d&z.", obj->value[4] );

            break;

        case ITEM_DATAPAD:
            ch_println( ch, "&zIt has &C%d&z units of charge remaining.", obj->value[3] );
            break;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_ENVIROSUIT ) )
    {
        ch_println( ch, "&zThis item acts as an envirosuit." );
    }

    if ( obj->count <= 1 )
        ch_println( ch, "&zItem Weight: &C%d&w", get_obj_weight( obj ) );
    else
    {
        ch_println( ch, "&zItem Weight (each): &C%d&w", (int)( get_obj_weight( obj ) / obj->count ) );
        ch_println( ch, "&zItem Weight (all): &C%d&w", get_obj_weight( obj ) );
    }
    ch_println( ch, "&zWear locations:  &C%s&w", flag_string( &obj->wear_flags, wear_types ) );

    if ( IS_OBJ_STAT( obj, ITEM_COVERING ) )
    {
        itemcontents( ch, obj, FALSE );
    }

    check_for_trap( ch, obj, TRAP_EXAMINE );

    if ( identified )
    {
        if ( apply_ac( obj ) > 0 )
            ch_println( ch, "&zAffects &C%s&z by &C%d.", "armor class", -1 * apply_ac( obj ) );

        if ( dex_mod( obj ) > 0 )
            ch_println( ch, "&zAffects &C%s&z by &C%d.", "dexterity", -1 * dex_mod( obj ) );

        if ( hp_mod( obj ) > 0 )
            ch_println( ch, "&zAffects &C%s&z by &C%d.", "hp", hp_mod( obj ) );

        for ( paf = obj->pIndexData->first_affect; paf; paf = paf->next )
        {
            if ( paf->location == APPLY_LCK )
                continue;

            if ( paf->location == APPLY_MANA && ch->skill_level[FORCE_ABILITY] <= 1 )
                continue;

            showaffect( ch, paf );
        }

        for ( paf = obj->first_affect; paf; paf = paf->next )
        {
            if ( paf->location == APPLY_LCK )
                continue;

            if ( paf->location == APPLY_MANA && ch->skill_level[FORCE_ABILITY] <= 1 )
                continue;

            showaffect( ch, paf );
        }
    }

    return;
}

CMDF do_exits( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    EXIT_DATA* pexit;
    bool found;
    bool fAuto;
    buf[0] = '\0';
    fAuto  = !str_cmp( argument, "auto" );

    if ( !check_blind( ch, FALSE ) )
        return;

    if ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_HOLYLIGHT ) && !IS_AFFECTED( ch, AFF_TRUESIGHT ) && !xIS_SET( ch->race->flags, RFLAG_DARKVISION ) && room_is_dark( ch->in_room ) )
    {
        ch_println( ch, "&zIt's too dark to distinguish the exits!" );
        return;
    }

    if ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_HOLYLIGHT ) && !IS_AFFECTED( ch, AFF_TRUESIGHT ) && xIS_SET( ch->in_room->flags, ROOM_SNOWSTORM ) )
    {
        ch_println( ch, "&WYou can't see a thing in this blizzard!&w" );
        return;
    }

    if ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_HOLYLIGHT ) && !IS_AFFECTED( ch, AFF_TRUESIGHT ) && xIS_SET( ch->in_room->flags, ROOM_SANDSTORM ) )
    {
        ch_println( ch, "&OYou can't see a thing in this sandstorm!&w" );
        return;
    }

    strlcpy( buf, fAuto ? "&z&WExits:" : "&z&WObvious exits:\n", MSL );
    found = FALSE;

    for ( pexit = ch->in_room->first_exit; pexit; pexit = pexit->next )
    {
        if ( pexit->to_room && get_room_index( pexit->vnum ) && !xIS_SET( pexit->flags, EX_HIDDEN ) )
        {
            found = TRUE;

            if ( !fAuto )
            {
                if ( xIS_SET( pexit->flags, EX_LOCKED ) && !xIS_SET( pexit->flags, EX_WINDOW ) )
                {
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - (locked)\n", capitalize_first( pexit->keyword && pexit->keyword[0] != '\0' ? pexit->keyword : dir_name[pexit->vdir] ) );
                }
                else if ( xIS_SET( pexit->flags, EX_CLOSED ) && !xIS_SET( pexit->flags, EX_WINDOW ) )
                {
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - (closed)%s\n", capitalize_first(
                                 pexit->keyword && pexit->keyword[0] != '\0' ? pexit->keyword : dir_name[pexit->vdir] ), xIS_SET( pexit->flags, EX_JAMMED ) ? " [JAMMED]" : "" );
                }
                else if ( xIS_SET( pexit->flags, EX_WINDOW ) )
                {
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - (%swindow)\n", capitalize_first( pexit->keyword && pexit->keyword[0] != '\0' ? pexit->keyword : dir_name[pexit->vdir] ),
                    xIS_SET( pexit->flags, EX_SEALED_WINDOW ) ? "sealed " : xIS_SET( pexit->flags, EX_LOCKED ) ? "locked " : xIS_SET( pexit->flags, EX_CLOSED ) ? "closed " : "" );
                }
                else if ( xIS_SET( pexit->flags, EX_xAUTO ) )
                {
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - %s\n", capitalize_first( pexit->keyword ), room_is_dark( pexit->to_room ) ? "Too dark to tell" : pexit->to_room->name );
                }
                else
                {
                    snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - %s\n", capitalize_first( dir_name[pexit->vdir] ), room_is_dark( pexit->to_room ) ?  "Too dark to tell" : pexit->to_room->name );
                }
            }
            else
            {
                snprintf( buf + strlen( buf ), MSL - strlen( buf ), " &z&W%s", capitalize_first( dir_name[pexit->vdir] ) );
            }
        }

        if ( xIS_SET( pexit->flags, EX_HIDDEN ) && ( get_trust( ch ) > 103 || is_name( "hiddenexits", ch->pcdata->bestowments ) ) )
        {
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), "&z&W%-5s - (hidden)\n", capitalize_first( pexit->keyword && pexit->keyword[0] != '\0' ? pexit->keyword : dir_name[pexit->vdir] ) );
        }
    }

    if ( !found )
        strlcat( buf, fAuto ? " &z&Wnone.\n" : "&z&WNone.\n", MSL );
    else if ( fAuto )
        strlcat( buf, ".\n", MSL );

    send_to_char( buf, ch );
    return;
}

