/*
    Now this is cleaner.
    Added SOUNDEX Support --- Ghost (5/22/02)
*/
CMDF do_help( CHAR_DATA* ch, char* argument )
{
    HELP_DATA* pHelp;

    /* GRAL case "help" returns "No help on '' found. No similar help files."  So lets feed them something. */
    if ( !argument || argument[0] == '\0' )
        argument = "newbie";

    if ( ( pHelp = get_help( ch, argument ) ) == NULL )
    {
        pager_printf( ch, "&wNo help on &z\'&C%s&z\'&w found.", argument );
        similar_help_files( ch, argument );

        if ( ch->desc && ch->desc->original )
            sql_help_log( ch->desc->original->name, argument );
        else
            sql_help_log( ch->name, argument );

        return;
    }

    if ( !str_cmp( argument, "fmotd" ) && get_trust( ch ) < sysdata.log_level && ch->skill_level[FORCE_ABILITY] < 2 )
    {
        send_to_pager( "&RYou can't read this help file, sorry.\n", ch );
        return;
    }

    // Display header lines for non-screenreader users
    if ( ch->pcdata && !has_pcflag( ch, PCFLAG_SCREENREADER ) )
    {
        send_to_pager( "&z[&C::&w Legends Of The Jedi&C ::&z]\n", ch );
        send_to_pager( "&z---------------------------&w\n", ch );
    }

    ch_printf( ch, "&W" );

    if ( pHelp->level >= 0 && str_cmp( argument, "imotd" ) && !nifty_is_name_prefix( argument, "news_" ) )
    {
        pager_printf( ch, "&WDisplaying HELP %s&w\n", pHelp->keyword );
    }

    sound_to_char( ch, "help" );

    /*
        Strip leading '.' to allow initial blanks.
    */
    if ( pHelp->text[0] == '.' )
        send_to_pager_color( pHelp->text + 1, ch );
    else
        send_to_pager_color( pHelp->text, ch );

    if ( pHelp->level >= 0 )
    {
        char buf[MSL];
        strlcpy( buf, "", MSL );

        if ( pHelp->lasteditor && pHelp->lastedittime )
        {
            time_t last_edited = ( time_t ) ( pHelp->lastedittime );
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), "\n&z---------------------------\n&wHelp file last modified by &C%s &won &C%s&w\n", pHelp->lasteditor, c_time( last_edited, get_timezone( ch ) ) );
        }

        if ( IS_IMMORTAL( ch ) )
        {
            snprintf( buf + strlen( buf ), MSL - strlen( buf ), "\n&z---------------------------\n&wHelp file level &C%d&w\n", pHelp->level );
        }

        send_to_pager_color( buf, ch );
    }

    return;
}

extern char* help_greeting;     /* so we can edit the greeting online */

/*
    Help editor                            -Thoric
*/
CMDF do_hedit( CHAR_DATA* ch, char* argument )
{
    HELP_DATA* pHelp = NULL;
    BUFFER_DATA* buffer = NULL;

    if ( !ch->desc )
    {
        ch_println( ch, "&RYou have no descriptor." );
        return;
    }

    if ( is_busy( ch ) )
    {
        ch_println( ch, "&RYou are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            break;

        case SUB_HELP_EDIT:
            buffer = get_buffer( ch, FUNC );
            if ( buffer )
            {
                pHelp = ( HELP_DATA* )buffer->buf1;
                dispose_buffer( buffer );
            }
            if ( !pHelp )
            {
                bug( "hedit: sub_help_edit: NULL buffer", 0 );
                stop_editing( ch, false );
                return;
            }

            SET_STRING( pHelp->lasteditor, ch->name );
            pHelp->lastedittime = ( int )( time( 0 ) );
            SET_STRING( pHelp->text, copy_buffer( ch ) );

            if ( !str_cmp( pHelp->keyword, "wizlist" ) )
                SET_STRING( help_wizlist, pHelp->text );
            else if ( !str_cmp( pHelp->keyword, "greeting" ) )
                SET_STRING( help_greeting, pHelp->text );

            stop_editing( ch, false );
            save_help( pHelp );
            return;
    }

    if ( ( pHelp = get_help( ch, argument ) ) == NULL )  /* new help */
    {
        HELP_DATA* tHelp;
        char argnew[MIL];
        int lev;
        bool new_help = TRUE;

        for ( tHelp = first_help; tHelp; tHelp = tHelp->next )
            if ( !str_cmp( argument, tHelp->keyword ) )
            {
                pHelp = tHelp;
                //bug("4 %s",pHelp->keyword);
                new_help = FALSE;
                break;
            }

        if ( new_help )
        {
            if ( isdigit( argument[0] ) )
            {
                lev = number_argument( argument, argnew );
                argument = argnew;
            }
            else
                lev = get_trust( ch );

            CREATE( pHelp, HELP_DATA, 1 );
            SET_STRING( pHelp->keyword, strupper( argument ) );
            SET_STRING( pHelp->text, "" );
            pHelp->level   = lev;
            SET_STRING( pHelp->lasteditor, ch->name );
            pHelp->lastedittime = ( int )( time( 0 ) );
            pHelp->id = 0;
            add_help( pHelp, TRUE );
            //bug("3 %s",pHelp->keyword);
        }
    }

    ch->substate = SUB_HELP_EDIT;
    buffer = create_buffer( ch, FUNC );
    buffer->buf1 = pHelp;
    start_editing( ch, FUNC, pHelp->text );
}

/*
    News editor                                                  -Thoric
*/
CMDF do_newswrite( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    HELP_DATA* pHelp = NULL;
    BUFFER_DATA* buffer = NULL;
    /* Help file to be editing */
    strlcpy( buf, "news_1", MSL );

    if ( !ch->desc )
    {
        ch_println( ch, "&RYou have no descriptor. Sucks for you." );
        return;
    }

    /* Make sure it was bestowed */
    if ( !( ch->pcdata && ch->pcdata->bestowments && is_name( "newswrite", ch->pcdata->bestowments ) ) )
    {
        send_to_char( "Huh?", ch );
        return;
    }

    if ( is_busy( ch ) )
    {
        ch_println( ch, "&RYou are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            break;

        case SUB_HELP_EDIT:
            buffer = get_buffer( ch, FUNC );
            if ( buffer )
            {
                pHelp = ( HELP_DATA* )buffer->buf1;
                dispose_buffer( buffer );
            }
            if ( !pHelp )
            {
                bug( "newswrite: sub_help_edit: NULL buffer", 0 );
                stop_editing( ch, false );
                return;
            }

            if ( help_greeting == pHelp->text )
                help_greeting = NULL;

            if ( help_wizlist == pHelp->text )
                help_wizlist = NULL;

            SET_STRING( pHelp->text, copy_buffer( ch ) );

            if ( !help_greeting )
                help_greeting = pHelp->text;

            if ( !help_wizlist )
                help_wizlist = pHelp->text;

            stop_editing( ch, false );
            /* Save the file - Ghost */
            save_help(pHelp);
          //  strlcpy( buf, "save", MSL );
            //do_hset( ch, buf );
            return;
    }

    if ( argument[0] == '\0' || atoi( argument ) < 1 || atoi( argument ) > 9 )
    {
        ch_println( ch, "&zSyntax: &CNEWSWRITE <&wpage 1-9&C>" );
        return;
    }

    snprintf( buf, MSL, "news_%d", atoi( argument ) );

    if ( ( pHelp = get_help( ch, buf ) ) == NULL ) /* new help */
    {
        HELP_DATA* tHelp;
        bool new_help = TRUE;

        for ( tHelp = first_help; tHelp; tHelp = tHelp->next )
            if ( !str_cmp( buf, tHelp->keyword ) )
            {
                pHelp = tHelp;
                new_help = FALSE;
                break;
            }

        if ( new_help )
        {
            CREATE( pHelp, HELP_DATA, 1 );
            SET_STRING( pHelp->keyword, strupper( buf ) );
            SET_STRING( pHelp->text, "" );
            pHelp->level   = 1;
            pHelp->id = 0;
            add_help( pHelp, TRUE );
        }
    }

    ch->substate = SUB_HELP_EDIT;
    buffer = create_buffer( ch, FUNC );
    buffer->buf1 = pHelp;
    start_editing( ch, FUNC, pHelp->text );
}

CMDF do_hset( CHAR_DATA* ch, char* argument )
{
    HELP_DATA* pHelp;
    char arg1[MIL];
    char arg2[MIL];
    smash_tilde( argument );
    argument = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &Chset <&wfield&C> [value] [help page]" );
        ch_println( ch, "" );
        ch_println( ch, "&zField being one of:" );
        ch_println( ch, "  &Blevel keyword remove" );
        return;
    }

    if ( str_cmp( arg1, "remove" ) )
        argument = one_argument( argument, arg2 );

    if ( ( pHelp = get_help( ch, argument ) ) == NULL )
    {
        ch_println( ch, "&RCan't find help on that subject." );
        return;
    }

    if ( !str_cmp( arg1, "remove" ) )
    {
        delete_help( pHelp );
        UNLINK( pHelp, first_help, last_help, next, prev );
        FREE_STRUCT_NORET( pHelp, help_fields );
        ch_println( ch, "&wRemoved." );
        return;
    }

    if ( !str_cmp( arg1, "level" ) )
    {
        int lev;

        if ( !is_number_sym( arg2 ) )
        {
            ch_println( ch, "&RLevel field must be numeric." );
            return;
        }

        lev = atoi( arg2 );

        if ( lev < -1 || lev > get_trust( ch ) )
        {
            ch_println( ch, "&RYou can't set the level to that." );
            return;
        }

        pHelp->level = lev;
        ch_println( ch, "&wDone." );
        save_help(pHelp);
        return;
    }

    if ( !str_cmp( arg1, "keyword" ) )
    {
        SET_STRING( pHelp->keyword, strupper( arg2 ) );
        ch_println( ch, "&wDone." );
        save_help( pHelp );
        return;
    }

    do_hset( ch, "" );
}

/*
    Show help topics in a level range                -Thoric
    Idea suggested by Gorog
    prefix keyword indexing added by Fireblade
*/
CMDF do_hlist( CHAR_DATA* ch, char* argument )
{
    int min, max, minlimit, maxlimit, cnt;
    char arg[MIL];
    HELP_DATA* help;
    bool minfound, maxfound;
    char idx[MSL];
    maxlimit = get_trust( ch );
    minlimit = maxlimit >= LEVEL_GREATER ? -1 : 0;
    min = minlimit;
    max  = maxlimit;
    minfound = FALSE;
    maxfound = FALSE;

    strlcpy( idx, "", MSL );
    for ( argument = one_argument( argument, arg ); arg[0] != '\0';
            argument = one_argument( argument, arg ) )
    {
        if ( !isdigit( arg[0] ) )
        {
            if ( !NULLSTR( idx ) )
            {
                //set_char_color(AT_GREEN, ch);
                ch_println( ch, "&RYou may only use a single keyword to index the list." );
                return;
            }

            snprintf( idx, MSL, "%s", arg );
        }
        else
        {
            if ( !minfound )
            {
                min = URANGE( minlimit, atoi( arg ), maxlimit );
                minfound = TRUE;
            }
            else if ( !maxfound )
            {
                max = URANGE( minlimit, atoi( arg ), maxlimit );
                maxfound = TRUE;
            }
            else
            {
                //set_char_color(AT_GREEN, ch);
                ch_println( ch, "&RYou may only use two level limits." );
                return;
            }
        }
    }

    if ( min > max )
    {
        int temp = min;
        min = max;
        max = temp;
    }

    //set_pager_color( AT_GREEN, ch );
    pager_printf( ch, "&GHelp Topics in level range %d to %d:\n\n&B", min, max );

    for ( cnt = 0, help = first_help; help; help = help->next )
        if ( help->level >= min && help->level <= max
                &&  ( NULLSTR( idx ) || nifty_is_name_prefix( idx, help->keyword ) ) )
        {
            pager_printf( ch, "  %3d %s\n", help->level, help->keyword );
            ++cnt;
        }

    if ( cnt )
        pager_printf( ch, "\n&z%d pages found.\n", cnt );
    else
        ch_println( ch, "&zNone found." );

    return;
}


/*
    New do_who with WHO REQUEST, clan, race and homepage support.  -Thoric

    Latest version of do_who eliminates redundant code by using linked lists.
    Shows imms separately, indicates guest and retired immortals.
    Narn, Oct/96
*/
CMDF do_who( CHAR_DATA* ch, char* argument )
{
    DESCRIPTOR_DATA* d;
    char buf[SUPER_MSL], buf2[SUPER_MIL], clan_name[MIL], extra_title[MIL], race_text[MIL];
    int iLevelLower = 0, iLevelUpper = 200, nNumber = 0, nMatch = 0, pCount = 0, iCount = 0;
    RACE_DATA *iRace = NULL;
    bool fRaceRestrict = FALSE, fImmortalOnly = FALSE, fClanMatch = FALSE, HidePlayer = TRUE;
    WHO_DATA* cur_who = NULL, *next_who = NULL, *first_mortal = NULL, *first_newbie = NULL, *first_rpc = NULL, *first_imm = NULL;

    if ( IS_IMMORTAL( ch ) && ( !has_pcflag( ch, PCFLAG_HIDEACCS ) || !NULLSTR( argument ) ) )
    {
        snprintf( buf, SUPER_MSL, "%s: who %s", ch->name, argument );
        log_string_plus( buf, LOG_NORMAL, get_trust( ch ) );
        strlcpy( buf, "", SUPER_MSL );
    }

    iLevelUpper = 200;
    iRace = get_race_by_name( argument );
    HidePlayer = sysdata.hidewho;

    if ( get_trust( ch ) >= sysdata.log_level )
        HidePlayer = FALSE;

    for ( ;; )
    {
        char arg[MIL];
        argument = one_argument( argument, arg );

        if ( NULLSTR( arg ) )
            break;

        if ( is_number( arg ) )
        {
            switch ( ++nNumber )
            {
                case 1:
                    iLevelLower = atoi( arg );
                    break;

                case 2:
                    iLevelUpper = atoi( arg );
                    break;

                default:
                    ch_println( ch, "Only two level numbers allowed." );
                    return;
            }
        }
        else
        {
            CLAN_DATA* tclan = NULL, *clan = NULL;

            if ( strlen( arg ) < 3 )
            {
                ch_println( ch, "Be a little more specific please." );
                return;
            }

            /*
                Look for classes to turn on.
            */

            if ( !str_cmp( arg, "imm" ) || !str_cmp( arg, "gods" ) )
                fImmortalOnly = TRUE;
            //else if ( !str_cmp( arg, "www" ) )
            //    fShowHomepage = TRUE;
            else
            {
                if  ( !str_cmp( arg, "clan" ) )
                {
                    if ( IS_NPC( ch ) || !ch->pcdata || !ch->pcdata->clan )
                    {
                        ch_println( ch, "You are not in a clan." );
                        return;
                    }
                    else
                        fClanMatch = TRUE;
                }
                else
                {
                    if ( get_trust( ch ) > 102 && iRace != NULL ) // GRAL Cheating morts checking how many Yev or Wooks on.
                        fRaceRestrict = TRUE;

                    if ( get_trust( ch ) > 102 && str_cmp( arg, "clan" ) && ( clan = get_clan( arg ) ) != NULL )
                    {
                        tclan = ch->pcdata->clan;
                        ch->pcdata->clan = clan;
                        do_who( ch, "clan" );       // GRAL That could break and fux your clan.
                        ch->pcdata->clan = tclan;
                        return;
                    }
                }
            }
        }
    }

    /*
        Now find matching chars.
    */
    nMatch = 0;
    buf[0] = '\0';

    if ( ch )
        set_pager_color( AT_GREEN, ch );

    int acclen = 0, namelen = 0;

    CHAR_DATA* wch = NULL;

    for ( d = last_descriptor; d; d = d->prev )
    {
        if ( ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                || ( !can_see( ch, d->character ) && IS_RPC( d->character ) ) )
            continue;

        wch = d->original ? d->original : d->character;

        if ( wch->top_level < iLevelLower
                ||   wch->top_level > iLevelUpper
                || ( fImmortalOnly  && wch->top_level < LEVEL_RPC )
                || ( fRaceRestrict && wch->race != iRace )
                || ( fClanMatch && ( ch->pcdata->clan != wch->pcdata->clan ) ) ) /* SB */
            continue;

        if ( !IS_RPC( d->character ) && HidePlayer )
            continue;

        if ( has_pcflag( wch, PCFLAG_NOWHO ) && ( wch->top_level > ch->top_level ) )
            continue;

        if ( IS_RPC( wch ) )
        {
            if ( wch->pcdata && !NULLSTR( wch->pcdata->rank ) && acclen < ( (int)strlen( stripclr( wch->pcdata->rank ) ) ) )
                    acclen = strlen( stripclr( wch->pcdata->rank ) );
        }
        else if ( !has_pcflag( ch, PCFLAG_HIDEACCS ) && get_trust( ch ) >= sysdata.log_level && d && d->account && !NULLSTR( d->account->name ) && acclen < ( (int)strlen( stripclr( d->account->name ) ) + 3 ) )
            acclen = strlen( stripclr( d->account->name ) ) + 3;

        if ( IS_IMMORTAL( ch ) && !NULLSTR( wch->name ) && namelen < ( (int) strlen( stripclr( wch->name ) ) + 2 ) )
            namelen = strlen( stripclr( wch->name ) ) + 2;
    }

    /* start from last to first to get it in the proper order */
    for ( d = last_descriptor; d; d = d->prev )
    {
        wch = NULL;
        char const* race;

        /*
            If there not PLAYING or EDITING, skip them.
            If the character can't see the wch(and wch is a Imm), skip them.
            If they dont have a original character, skip them.
        */
        if ( ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                || ( !can_see( ch, d->character ) && IS_RPC( d->character ) ) )
            continue;

        wch = d->original ? d->original : d->character;

        if ( wch->top_level < iLevelLower
                ||   wch->top_level > iLevelUpper
                || ( fImmortalOnly  && wch->top_level < LEVEL_RPC )
                || ( fRaceRestrict && wch->race != iRace )
                || ( fClanMatch && ( ch->pcdata->clan != wch->pcdata->clan ) ) ) /* SB */
            continue;

        if ( !IS_RPC( d->character ) )
        {
            ++pCount;

            if ( HidePlayer )
                continue;
        }
        else
        {
            ++iCount;
        }

        /*
            Check for the NOWHO flag. -Ghost
        */
        if ( has_pcflag( wch, PCFLAG_NOWHO ) && ( wch->top_level > ch->top_level ) )
            continue;

        nMatch++;

        if ( IS_IMMORTAL(ch) )
            snprintf( extra_title, MIL, "&z[&C%-*s&z]&w ", namelen - 2, wch->name );
        else
            strlcpy( extra_title, "", MIL );

        if ( IS_RPC( wch ) && !NULLSTR( wch->pcdata->rank ) )
            snprintf( race_text, MIL, "&W%-*s&z ", acclen + (int)(strlen(wch->pcdata->rank)-strlen(stripclr(wch->pcdata->rank))), wch->pcdata->rank );
        else if ( !has_pcflag( ch, PCFLAG_HIDEACCS ) && get_trust( ch ) >= sysdata.log_level && ( ( !IS_RPC( wch ) || NULLSTR( wch->pcdata->rank ) ) && d->account && d->account->name ) )
            snprintf( race_text, MIL, "&z(&Y@%-*s&z) ", acclen-3, d->account->name );
        else if ( !has_pcflag( ch, PCFLAG_HIDEACCS ) && get_trust( ch ) >= sysdata.log_level && ( !d->account || NULLSTR( d->account->name ) ) )
            snprintf( race_text, MIL, "&z(%-*s&z) ", acclen-2, " " );
        else
            strlcpy( race_text, "", MIL );

        race = race_text;

        if ( in_clan( ch ) && fClanMatch == TRUE )
        {
            if ( wch->pcdata->clan == ch->pcdata->clan )
            {
                CLAN_DATA* pclan = wch->pcdata->clan;

                if ( !str_cmp( wch->name, pclan->leader ) )
                    snprintf( clan_name, MIL, " &z(&CLeader&z)" );
                else if ( !str_cmp( wch->name, pclan->number1 ) )
                    snprintf( clan_name, MIL, " &z(&CFirst&z)" );
                else if ( !str_cmp( wch->name, pclan->number2 ) )
                    snprintf( clan_name, MIL, " &z(&CSecond&z)" );
                else
                    strlcpy( clan_name, "", MIL );
            }
            else
                strlcpy( clan_name, "", MIL );
        }
        else
            strlcpy( clan_name, "", MIL );

        char invis_str[64], afkflag[64], botflag[64], cooldown[64], hidforce[64], isforce[8];

        if ( has_pcflag( wch, PCFLAG_WIZINVIS ) )
            snprintf( invis_str, 64, "&z(&C%d&z) ", wch->pcdata->wizinvis );
        else
            strlcpy( invis_str, "", 64 );

        snprintf( afkflag, 64, "%s", has_pcflag( wch, PCFLAG_AFK ) ? " &z[&YAFK&z]&w" : "" );
        snprintf( botflag, 64, "%s", ( !IS_NPC( wch ) && wch->pcdata->botting && wch->pcdata->cooldown != -1 ) ? " &z[&PBOTTING&z]&w" : "" );
        snprintf( cooldown, 64, "%s", ( !IS_NPC( wch ) && wch->pcdata->cooldown > 0 ) ? " &z[&CCOOLDOWN&z]&w" : "" );
        snprintf( hidforce, 64, "%s", ( has_pcflag( wch, PCFLAG_NO_SENSE ) && get_trust( ch ) > 105 ) ? " &z(&bHidden Force&z)&w" : "" );
        snprintf( isforce, 8, "%s", ( get_trust( ch ) > 105 && wch->perm_frc > 1 ) ? " &B*&w" : "" );
        int a = NULLSTR( afkflag ) ? 0 : strlen( stripclr( afkflag ) );
        int b = NULLSTR( botflag ) ? 0 : strlen( stripclr( botflag ) );
        int c = NULLSTR( cooldown ) ? 0 : strlen( stripclr( cooldown ) );
        int e = NULLSTR( hidforce ) ? 0 : strlen( stripclr( hidforce ) );
        int f = NULLSTR( isforce ) ? 0 : strlen( stripclr( isforce ) );
        int g = NULLSTR( invis_str ) ? 0 : strlen( stripclr( invis_str ) );
        int h = NULLSTR( clan_name ) ? 0 : strlen( stripclr( clan_name ) );

        int remainder = 80 - ( acclen + namelen + 2 + a + b + c + e + f + g + h );
        if ( ( has_pcflag( ch, PCFLAG_HIDEACCS ) || get_trust( ch ) < sysdata.log_level ) && ( !d->character || !IS_RPC( d->character ) ) )
            remainder += acclen;

        // Safety check: if everything else on the screen is taking up 75+ characters, just give an extra line for the title to render.
        if ( remainder < 5 )
            remainder = 80;

        snprintf( buf2, SUPER_MIL, "%s%s%s%s%s%s%s%s", truncate_string( wch->pcdata ? wch->pcdata->title : wch->name, remainder ), invis_str, afkflag, botflag, cooldown, hidforce, isforce, clan_name );
        snprintf( buf, SUPER_MSL, "%s%s%s&G\n", race, extra_title, buf2 );

        /*
            This is where the old code would display the found player to the ch.
            What we do instead is put the found data into a linked list
        */
        /* First make the structure. */
        CREATE( cur_who, WHO_DATA, 1 );
        SET_STRING( cur_who->text, buf );

        if ( get_trust( wch ) > 101 )
            cur_who->type = WT_IMM;
        else if ( get_trust( wch ) <= 5 )
            cur_who->type = WT_NEWBIE;
        else if ( get_trust( wch ) == 101 )
            cur_who->type = WT_RPC;
        else
            cur_who->type = WT_MORTAL;

