CMDF do_compare( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    OBJ_DATA* obj1;
    OBJ_DATA* obj2;
    int value1;
    int value2;
    char* msg;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "Compare what to what?" );
        return;
    }

    if ( ( obj1 = get_obj_carry( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "You do not have that item." );
        return;
    }

    if ( NULLSTR( arg2 ) )
    {
        for ( obj2 = ch->first_carrying; obj2; obj2 = obj2->next_content )
        {
            if ( obj2->wear_loc != WEAR_NONE
                    &&   can_see_obj( ch, obj2 )
                    &&   obj1->item_type == obj2->item_type )
                break;
        }

        if ( !obj2 )
        {
            ch_println( ch, "You aren't wearing anything comparable." );
            return;
        }
    }
    else
    {
        if ( ( obj2 = get_obj_carry( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "You do not have that item." );
            return;
        }
    }

    msg        = NULL;
    value1    = 0;
    value2    = 0;

    if ( obj1 == obj2 )
    {
        msg = "You compare $p to itself.  It looks about the same.";
    }
    else if ( obj1->item_type != obj2->item_type )
    {
        msg = "You can't compare $p and $P.";
    }
    else
    {
        switch ( obj1->item_type )
        {
            default:
                msg = "You can't compare $p and $P.";
                break;

            case ITEM_ARMOR:
                value1 = obj1->value[2];
                value2 = obj2->value[2];
                break;

            case ITEM_WEAPON:
                value1 = obj1->value[1] + obj1->value[2];
                value2 = obj2->value[1] + obj2->value[2];
                break;

            case ITEM_CONTAINER:
                value1 = obj1->value[0];
                value2 = obj2->value[0];
        }
    }

    if ( !msg )
    {
        if ( value1 == value2 )
            msg = "$p and $P look about the same.";
        else if ( value1  > value2 )
            msg = "$p looks better than $P.";
        else
            msg = "$p looks worse than $P.";
    }

    act( AT_PLAIN, msg, ch, obj1, obj2, TO_CHAR );
    return;
}

/* Added from Smaug 1.4a */
CMDF do_where( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    char buf[MSL];
    CHAR_DATA* victim;
    DESCRIPTOR_DATA* d;
    bool found;
    bool full = FALSE;
    one_argument( argument, arg );

    if ( !str_cmp( arg, "full" ) && IS_IMMORTAL( ch ) )
        full = TRUE;

    if ( !full )
    {
        if ( arg[0] != '\0'
                &&   ( victim = get_char_world( ch, arg ) ) && !IS_NPC( victim )
                &&   has_pcflag( victim, PCFLAG_DND )
                &&   get_trust( ch ) < get_trust( victim ) )
        {
            act( AT_PLAIN, "You didn't find any $T.", ch, NULL, arg, TO_CHAR );
            return;
        }
    }

    set_pager_color( AT_PERSON, ch );

    if ( arg[0] == '\0' || full )
    {
        if ( full )
            send_to_pager( "Players logged in:\n", ch );

        if ( !full )
            pager_printf( ch, "Players near you in %s:\n", ch->in_room->area->name );

        found = FALSE;

        for ( d = first_descriptor; d; d = d->next )
            if ( ( d->connected == CON_PLAYING || d->connected == CON_EDITING )
                    && ( victim = d->character ) != NULL
                    &&   !IS_NPC( victim )
                    &&   victim->in_room
                    &&   ( victim->in_room->area == ch->in_room->area || full )
                    && ( get_trust( ch ) >= get_trust( victim )
                         ||   !has_pcflag( victim, PCFLAG_DND ) )
               ) /* if victim has the DND flag ch must outrank them */
            {
                found = TRUE;
                /*        if ( CAN_PKILL( victim ) )
                          set_pager_color( AT_PURPLE, ch );
                        else
                          set_pager_color( AT_PERSON, ch );
                */
                snprintf( buf, MSL, "&P%-13s  ", victim->name );
                send_to_pager_color( buf, ch );

                if ( IS_IMMORTAL( victim ) && victim->top_level > 100 )
                    send_to_pager_color( "&P(&WImmortal&P)\t", ch );
                else
                    send_to_pager( "\t\t\t", ch );

                snprintf( buf, MSL, "&P%-20s", ( victim->in_room->area->planet ? victim->in_room->area->planet->name : "noplanet" ) );
                send_to_pager_color( buf, ch );
                snprintf( buf, MSL, "&P%s\n", victim->in_room->name );
                send_to_pager_color( buf, ch );
            }

        if ( !found )
            ch_println( ch, "None" );
    }
    else
    {
        found = FALSE;

        for ( victim = first_char; victim; victim = victim->next )
            if ( victim->in_room
                    &&   victim->in_room->area == ch->in_room->area
                    &&   is_name( arg, victim->name ) )
            {
                found = TRUE;
                pager_printf( ch, "%-28s %s\n",
                              PERS( victim, ch ), victim->in_room->name );
                break;
            }

        if ( !found )
            act( AT_PLAIN, "You didn't find any $T.", ch, NULL, arg, TO_CHAR );
    }

    return;
}


