bool abl_name( const char* argument )
{
    int x = 0;

    if ( !argument || argument[0] == '\0' )
        return FALSE;

    for ( x = 0; x < MAX_ABILITY; x++ )
        if ( !str_cmp( flag_value_name( ability_name, x ), argument ) )
            return TRUE;

    return FALSE;
}

/*
    Place any skill types you don't want them to be able to practice
    normally in this list.  Separate each with a space.
    (Uses an is_name check). -- Altrag
*/
#define CANT_PRAC "Tongue"

void show_practice( CHAR_DATA* ch, CHAR_DATA* victim, const char* argument )
{
    if ( !ch || !victim )
        return;

    SKILL_DATA* skill = NULL;
    int col, disp = 0;
    sh_int currtype, cnt;
    static SKILL_DATA** skills;
    LINK_TO_ARRAY( first_skill, SKILL_DATA, next, skills );
    SORT_ARRAY( skills, SKILL_DATA, alphabetize, name );
    int order[13] = { SKILL_UNKNOWN, SKILL_SPELL, SKILL_LIGHTSABER_FORM,
    SKILL_SKILL, SKILL_WEAPON, SKILL_TONGUE, SKILL_HERB, SKILL_RACIAL,
    SKILL_DISEASE, SKILL_DROIDTYPE, SKILL_PROTOCOL, SKILL_KNOWLEDGE, SKILL_FEAT };

    if ( abl_name( argument ) )
        while ( str_cmp( flag_value_name( ability_name, disp ), argument ) )
            disp++;

    col = cnt = 0;

    for ( int i = 0; i < 13; i++ )
    {
        currtype = -1;
        if ( ( order[i] == SKILL_SPELL || order[i] == SKILL_LIGHTSABER_FORM ) && victim->pcdata->frank == FRANK_NONE )
            continue;

        for ( int j = 0; skills[j]; j++ )
        {
            skill = skills[j];

            if ( !skill )
                continue;

            if ( skill->type != order[i] )
                continue;

            if ( !skill->name )
                continue;

            if ( skill->type == SKILL_HERB )
                continue;

            if ( ( ch == victim || skill->type != SKILL_TONGUE ) && ( skill->guild < 0 || skill->guild >= MAX_ABILITY ) )
                continue;

            if ( skill->guild != disp && abl_name( argument ) )
                continue;

            if ( get_learned_pct( victim, skill ) <= 0 && victim->skill_level[skill->guild] < skill->min_level )
                continue;

            if ( skill->type != currtype )
            {
                if ( col % 3 != 0 )
                    send_to_pager( "\n", ch );

                if ( skill->type == SKILL_SPELL && victim->pcdata->frank == FRANK_NONE )
                    continue;
                else if ( skill->type == SKILL_SPELL )
                    pager_printf( ch, "&B--------------------------------&159Force Abilities&B--------------------------------\n" );
                else if ( skill->type == SKILL_LIGHTSABER_FORM )
                    pager_printf( ch, "&B--------------------------------&159Lightsaber Forms&B-------------------------------\n" );                    
                else
                    pager_printf( ch, "&B------------------------------------&C%*s%s%*s&B------------------------------------\n", 3 + strlen( skill_tname[skill->type] ) / 2, skill_tname[skill->type], "s", 3 - strlen( skill_tname[skill->type] ) / 2, "" );

                col = cnt = 0;
            }

            currtype = skill->type;

            if ( ( ch == victim || skill->type != SKILL_TONGUE ) && ( skill->guild < 0 || skill->guild >= MAX_ABILITY ) )
                continue;

            if ( skill->guild == FORCE_ABILITY )
            {
                if ( skill->alignment >= 300 && victim->alignment < 0 )
                    continue;

                if ( skill->alignment <= -300 && victim->alignment > 0 )
                    continue;
            }

            if ( get_learned_pct( victim, skill ) == 0 && SPELL_FLAG( skill, SF_SECRETSKILL ) )
                continue;

            if ( skill->guild == FORCE_ABILITY && SPELL_FLAG( skill, SF_SECRETSKILL ) && get_trust( victim ) < LEVEL_PR )
                continue;

            ++cnt;

            if ( skill->guild == FORCE_ABILITY )
            {
                if ( skill->alignment < -1000 )
                    send_to_pager( "&r", ch );
                else if ( skill->alignment > 1000 )
                    send_to_pager( "&g", ch );
                else
                    send_to_pager( "&B", ch );
            }
            else
                send_to_pager( "&B", ch );

            if ( skill->type != SKILL_FEAT )
                pager_printf( ch, "&B%20s &%c%3d%%", skill->name,
                            get_learned_pct( victim, skill ) == 100 ? 'C' :
                            get_learned_pct( victim, skill ) > 89 ? 'G' :
                            get_learned_pct( victim, skill ) > 0 ? 'Y' : 'R',
                            get_learned_pct( victim, skill ) );
            else
                pager_printf( ch, "&B%21s &w[&C%s&w]&B", skill->name, get_learned_pct( victim, skill ) > 0 ? "X" : " " );

            if ( ++col % 3 == 0 )
                send_to_pager( "\n", ch );
            else
                send_to_pager( "  ", ch );
        }
    }

    if ( col % 3 != 0 )
        send_to_pager( "\n", ch );

    return;
}

CMDF do_practice( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    SKILL_DATA* skill = NULL;

    if ( IS_NPC( ch ) )
        return;

    if ( argument[0] == '\0' || abl_name( argument ) )
    {
        show_practice( ch, ch, argument );
        ch_println( ch, "To see a shorter practice list, type PRACTICE <class name>." );
    }
    else
    {
        CHAR_DATA* mob;
        int adept;
        bool can_prac = TRUE;

        if ( !IS_AWAKE( ch ) )
        {
            ch_println( ch, "In your dreams, or what?" );
            return;
        }

        for ( mob = ch->in_room->first_person; mob; mob = mob->next_in_room )
            if ( IS_NPC( mob ) && xIS_SET( mob->act, ACT_PRACTICE ) )
                break;
        skill = skill_from_name( argument );

        if ( !IS_NPC( ch ) && has_pcflag( ch, PCFLAG_CG ) )
        {
            if ( !skill )
            {
                ch_println( ch, "&RThat's not a skill or feat." );
                return;
            }

            if ( skill->type == SKILL_FEAT )
            {
                if ( get_learned_pct( ch, skill ) > 0 )
                {
                    ch_println( ch, "You already know that feat." );
                    return;
                }

                if ( count_feats( ch ) >= 3 )
                {
                    ch_println( ch, "&RYou can't learn any more feats." );
                    return;
                }

                set_learned_pct( ch, skill, 100 );
                act( AT_ACTION, "You learn $T.", ch, NULL, skill->name, TO_CHAR );
                act( AT_ACTION, "$n learns $T.", ch, NULL, skill->name, TO_ROOM );
                do_save( ch, "-noalert" );
            }
            else
            {
                ch_println( ch, "&RYou can only use practice to gain feats." );
            }
            return;
        }

        if ( !mob )
        {
            ch_println( ch, "You can't do that here." );
            return;
        }

        if ( !skill )
        {
            act( AT_TELL, "$n tells you 'I've never heard of that one...'",
                 mob, NULL, ch, TO_VICT );
            return;
        }

        if ( skill->guild < 0  || skill->guild >= MAX_ABILITY || skill->guild == FORCE_ABILITY )
        {
            act( AT_TELL, "$n tells you 'I can't teach you that...'",
                 mob, NULL, ch, TO_VICT );
            return;
        }

        if ( can_prac &&  !IS_NPC( ch )
                &&   ch->skill_level[skill->guild] < skill->min_level )
        {
            act( AT_TELL, "$n tells you 'You're not ready to learn that yet...'",
                 mob, NULL, ch, TO_VICT );
            return;
        }

        if ( is_name( skill_tname[skill->type], CANT_PRAC ) || skill->no_teach )
        {
            act( AT_TELL, "$n tells you 'I do not know how to teach that.'",
                 mob, NULL, ch, TO_VICT );
            return;
        }

        /*
            Skill requires a special teacher
        */
        if ( skill->teachers && skill->teachers[0] != '\0' )
        {
            snprintf( buf, MSL, "%d", mob->pIndexData->vnum );

            if ( !is_name( buf, skill->teachers ) )
            {
                act( AT_TELL, "$n tells you, 'I know not how to teach that.'",
                     mob, NULL, ch, TO_VICT );
                return;
            }
        }

        if ( skill->type == SKILL_LIGHTSABER_FORM )
        {
            if ( get_learned_pct( ch, skill ) > 0 )
            {
                ch_println( ch, "You already know that form. Now you must practice it." );
                return;
            }

            if ( count_saberforms( ch ) >= 2 )
            {
                ch_println( ch, "&RYou can't learn any more lightsaber forms." );
                return;
            }

            if ( !str_cmp( skill->name, "niman" ) && ch->pcdata->fclass != JEDI_CONSULAR && ch->pcdata->fclass != SITH_SORCERER )
            {
                ch_println( ch, "&RYou cannot learn that form." );
                return;
            }

            if ( !str_cmp( skill->name, "vaapad" ) )
            {
                ch_println( ch, "&RThat cannot be taught." );
                return;
            }
        }

        adept = 20;

        if ( ch->gold < skill->min_level * 10 )
        {
            snprintf( buf, MSL, "$n tells you, 'I charge %d credits to teach that. You don't have enough.'", skill->min_level * 10 );
            act( AT_TELL, "$n tells you 'You don't have enough credits.'",
                 mob, NULL, ch, TO_VICT );
            return;
        }

        if ( skill->type == SKILL_FEAT )
        {
            if ( get_learned_pct( ch, skill ) > 0 )
            {
                ch_println( ch, "You already know that feat." );
                return;
            }

            if ( count_feats( ch ) >= 3 )
            {
                ch_println( ch, "&RYou can't learn any more feats." );
                return;
            }

            set_learned_pct( ch, skill, 100 );
            act( AT_ACTION, "You learn $T.", ch, NULL, skill->name, TO_CHAR );
            act( AT_ACTION, "$n learns $T.", ch, NULL, skill->name, TO_ROOM );
            do_save( ch, "-noalert" );
            return;
        }

        if ( get_learned_pct( ch, skill ) >= adept )
        {
            snprintf( buf, MSL, "$n tells you, 'I've taught you everything I can about %s.'",
                     skill->name );
            act( AT_TELL, buf, mob, NULL, ch, TO_VICT );
            act( AT_TELL, "$n tells you, 'You'll have to practice it on your own now...'",
                 mob, NULL, ch, TO_VICT );
        }
        else
        {
            ch->gold -= skill->min_level * 10;

            if ( !IS_NPC( ch ) )
                sql_credits_log( ch->name, "do_practice", ( skill->min_level * 10 ) * -1, TRUE );

            add_learned_pct( ch, skill, int_app[get_curr_int( ch )].learn );
            act( AT_ACTION, "You practice $T.",
                 ch, NULL, skill->name, TO_CHAR );
            act( AT_ACTION, "$n practices $T.",
                 ch, NULL, skill->name, TO_ROOM );

            if ( get_learned_pct( ch, skill ) >= adept )
            {
                set_learned_pct( ch, skill, adept );
                act( AT_TELL,
                     "$n tells you. 'You'll have to practice it on your own now...'",
                     mob, NULL, ch, TO_VICT );
            }
        }
    }

    return;
}

CMDF do_steacher( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    char buf[MSL];
    char* buf1;
    char arg[MSL];
    int vnum;
    bool fMob, fSet;
    SKILL_DATA* skill = NULL;

    if ( IS_NPC( ch ) )
        return;

    set_pager_color( AT_MAGIC, ch );
    send_to_pager( "\n------------[ Missing Teachers ]-------------\n", ch );

    for ( skill = first_skill; skill; skill = skill->next )
    {
        if ( !skill->name )
            break;

        if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
            continue;

        fMob = FALSE;
        fSet = TRUE;
        skill = skill;

        if ( skill->teachers && skill->teachers[0] != '\0' )
        {
            buf1 = skill->teachers;

            for ( ; ; )
            {
                buf1 = one_argument( buf1, arg );

                if ( !NULLSTR( arg ) )
                {
                    vnum = atoi( arg );

                    if ( vnum > 0 )
                        if ( ( victim = get_char_world( ch, arg ) ) != NULL )
                            fMob = TRUE;
                }
                else
                    break;
            }
        }
        else if ( !skill->teachers || skill->teachers[0] == '\0' )
            fSet = FALSE;
        else
            continue;

        if ( fMob )
            continue;

        if ( fSet && fMob )
            continue;

        if ( !fMob )
            snprintf( buf, MSL, "Skill: %-25s    [No Invoked Teachers]\n", skill->name );

        if ( !fSet )
            snprintf( buf, MSL, "Skill: %-25s    [No Designated Teachers]\n", skill->name );

        send_to_char( buf, ch );
        continue;
    }

    return;
}

void dispose_teach( TEACH_DATA* teach )
{
    if ( !teach )
        return;

    UNLINK( teach, first_teach, last_teach, next, prev );
    DISPOSE( teach );
    return;
}

TEACH_DATA* fetch_teach( CHAR_DATA* teacher, CHAR_DATA* student )
{
    TEACH_DATA* teach = NULL;

    if ( !teacher || !student || char_extracted( teacher ) || char_extracted( student ) )
        return NULL;

    for ( teach = first_teach; teach; teach = teach->next )
        if ( teach->teacher == teacher && teach->student == student && teach->disguise == student->disguise )
            break;

    return teach;
}

TEACH_DATA* create_teach( CHAR_DATA* teacher, CHAR_DATA* student, SKILL_DATA* skill )
{
    TEACH_DATA* teach = NULL;

    if ( !teacher || !student || char_extracted( teacher ) || char_extracted( student ) || !skill )
        return NULL;

    if ( ( teach = fetch_teach( teacher, student ) ) != NULL )
    {
        teach->skill = skill;
        teach->created_at = current_time;
        return teach;
    }

    CREATE( teach, TEACH_DATA, 1 );
    teach->teacher = teacher;
    teach->student = student;
    teach->disguise = student->disguise;
    teach->skill = skill;
    teach->created_at = current_time;
    LINK( teach, first_teach, last_teach, next, prev );
    return teach;
}

void teach_accept( TEACH_DATA* teach )
{
    char buf[MSL];
    int teachamt = 0;
    CHAR_DATA* ch = NULL, *victim = NULL;
    SKILL_DATA* skill = NULL;

    if ( !teach )
        return;

    if ( !teach->student || !teach->teacher || !teach->skill )
    {
        dispose_teach( teach );
        return;
    }

    ch = teach->teacher;
    victim = teach->student;
    skill = teach->skill;

    if ( victim->skill_level[skill->guild] < skill->min_level )
    {
        act( AT_TELL, "$n isn't ready to learn that yet.", victim, NULL, ch, TO_VICT );
        return;
    }

    teachamt = UMAX( 10, ch->skill_level[LEADERSHIP_ABILITY] / 2 );

    if ( is_focus( ch, skill->guild ) )
        teachamt += ( int )( teachamt * .3 );

    teachamt = UMIN( teachamt, 100 );

    if ( skill->teach_max > 0 )
        teachamt = UMIN( teachamt, skill->teach_max );

    if ( get_learned_pct( victim, skill ) >= teachamt )
    {
        act( AT_TELL, "$n must practice that on their own.", victim, NULL, ch, TO_VICT );
        return;
    }

    if ( get_learned_pct( ch, skill ) < 100 )
    {
        act( AT_TELL, "You must perfect that yourself before teaching others.", victim, NULL, ch, TO_VICT );
        return;
    }
    else
    {
        if ( number_percent() > get_learned_pct( ch, cache_skill( "teach", &skill_teach ) ) )
        {
            act( AT_TELL, "You attempt to explain the concept to $N, but fail miserably...", ch, NULL, victim, TO_CHAR );
            act( AT_TELL, "$n attempts to explain it to you, but you just end up confused.", ch, NULL, victim, TO_VICT );
            learn_from_failure( ch, cache_skill( "teach", &skill_teach ) );
            return;
        }

        //  add_learned_pct( victim, sn, int_app[get_curr_int(ch)].learn );
        set_learned_pct( victim, skill, UMAX( get_learned_pct( victim, skill ), teachamt ) );
        snprintf( buf, MSL, "You teach %s $T, raising it to %d%%.", PERS( victim, ch ), get_learned_pct( victim, skill ) );
        act( AT_ACTION, buf, ch, NULL, skill->name, TO_CHAR );
        snprintf( buf, MSL, "%s teaches you $T, raising it to %d%%.", PERS( ch, victim ), get_learned_pct( victim, skill ) );
        act( AT_ACTION, buf, victim, NULL, skill->name, TO_CHAR );
        learn_from_success( ch, cache_skill( "teach", &skill_teach ) ); //Ralen Dec '13 - This was previously GSN_SCAN? Bad copypasta methinks.
    }

    dispose_teach( teach );
    return;
}

CMDF do_teach( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    SKILL_DATA* skill = NULL;
    TEACH_DATA* db = NULL;
    CHAR_DATA* victim;

    if ( IS_NPC( ch ) )
        return;

    argument = one_argument( argument, arg );

    if ( argument[0] == '\0' && str_cmp( "deny", arg ) && str_cmp( "accept", arg ) )
    {
        ch_println( ch, "Teach who, what?" );
        return;
    }

    if ( !IS_AWAKE( ch ) ) // GRAL Other positions required DYING etc
    {
        ch_println( ch, "In your dreams, or what?" );
        return;
    }

    if ( !str_cmp( "deny", arg ) || !str_cmp( "accept", arg ) )
    {
        for ( db = first_teach; db; db = db->next )
            if ( db->student == ch && db->disguise == ch->disguise )
                break;

        if ( !db || !db->skill )
        {
            ch_println( ch, "Nobody is offering to teach you anything." );
            return;
        }

        victim = db->teacher;
        skill = db->skill;

        if ( !valid_char( victim ) || victim->in_room != ch->in_room )
        {
            ch_println( ch, "Seems like your would-be teacher left." );
            dispose_teach( db );
            return;
        }

        if ( !str_cmp( "deny", arg ) )
        {
            dispose_teach( db );
            ch_println( ch, "You refuse the %s lesson from %s.", skill->name, g_name( victim, ch ) );
            ch_println( victim, "%s refuses your %s lesson.", g_name( ch, victim ), skill->name );
            return;
        }

        if ( !str_cmp( "accept", arg ) )
        {
            db->accepted = TRUE;
            ch_println( ch, "You accept the %s lesson from %s", skill->name, g_name( victim, ch ) );
            teach_accept( db );
            return;
        }
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They don't seem to be here..." );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "You can't teach that to them!" );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You say \"Good ol' me, I taught me everything I know.\"" );
        return;
    }

    skill = skill_from_name( argument );

    if ( !skill )
    {
        act( AT_TELL, "You have no idea what that is.",  victim, NULL, ch, TO_VICT );
        return;
    }

    if ( skill->guild == FORCE_ABILITY || skill->type == SKILL_LIGHTSABER_FORM )
    {
        if ( ch->pcdata->frank < FRANK_KNIGHT )
        {
            ch_println( ch, "&RYou must obtain the rank of %s before you can do that!", get_auto_frank( ch, FRANK_KNIGHT ) );
            return;
        }

        if ( victim->pcdata->frank < FRANK_KNIGHT )
        {
            ch_println( ch, "&RThey must obtain the rank of %s before you can teach them!", get_auto_frank( victim, FRANK_KNIGHT ) );
            return;
        }
    }

    if ( skill->type == SKILL_LIGHTSABER_FORM )
    {
        if ( get_learned_pct( victim, skill ) > 0 )
        {
            ch_println( ch, "They already know that form. Now they must practice it." );
            return;
        }

        if ( count_saberforms( victim ) >= 2 )
        {
            ch_println( ch, "&RThey can't learn any more lightsaber forms." );
            return;
        }

        if ( !str_cmp( skill->name, "niman" ) && victim->pcdata->fclass != JEDI_CONSULAR && victim->pcdata->fclass != SITH_SORCERER )
        {
            ch_println( ch, "&RThey cannot learn that form." );
            return;
        }

        if ( !str_cmp( skill->name, "vaapad" ) )
        {
            ch_println( ch, "&RThat cannot be taught." );
            return;
        }
    }

    if ( skill->type == SKILL_FEAT )
    {
        act( AT_TELL, "You can't teach feats.", victim, NULL, ch, TO_VICT );
        return;
    }

    if ( skill->guild < -1  || skill->guild >= MAX_ABILITY )
    {
        act( AT_TELL, "That's just not going to happen.", victim, NULL, ch, TO_VICT );
        return;
    }

    if ( is_name( skill_tname[skill->type], CANT_PRAC ) || skill->no_teach )
    {
        act( AT_TELL, "You are unable to teach that skill.",
                victim, NULL, ch, TO_VICT );
        return;
    }

    if ( ( db = fetch_teach( ch, victim ) ) != NULL )
    {
        if ( db->skill == skill && !db->accepted )
        {
            ch_println( ch, "Waiting on them to accept the lesson." );
            return;
        }
    }

    if ( !db || db->skill != skill )
    {
        db = create_teach( ch, victim, skill );
        ch_println( ch, "You offer to teach %s to %s.", skill->name, g_name( victim, ch ) );
        ch_println( victim, "&w%s offers to teach you %s.\n&zType &CTEACH ACCEPT&z or &CTEACH DENY&z to respond.&w",
                    g_name( ch, victim ), skill->name );
        return;
    }

    return;
}

CMDF do_wimpy( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    int wimpy = 0;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
        wimpy = ( int ) ch->max_hit / 5;
    else
        wimpy = atoi( arg );

    int skelmod = affect_modifier_from_cybers( ch, APPLY_HIT );

    if ( wimpy < 0 )
    {
        ch_println( ch, "You cannot set a wimpy value less than zero. See &CHELP WIMPY&w." );
        return;
    }

    if ( wimpy > ch->race->hit + skelmod )
    {
        ch_println( ch, "You cannot set a wimpy value higher than %d. See &CHELP WIMPY&W.", ch->race->hit + skelmod );
        return;
    }

    ch->wimpy = wimpy;
    ch_println( ch, "Wimpy set to %d hit points.", wimpy );
    return;
}

CMDF do_password( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL];
    char arg2[MIL];
    char* pArg;
    char* pwdnew;
    char* p;
    char cEnd;

    if ( IS_NPC( ch ) )
        return;

    /*
        Can't use one_argument here because it smashes case.
        So we just steal all its code.  Bleagh.
    */
    pArg = arg1;

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' )
    {
        if ( *argument == cEnd )
        {
            argument++;
            break;
        }

        *pArg++ = *argument++;
    }

    *pArg = '\0';
    pArg = arg2;

    while ( isspace( *argument ) )
        argument++;

    cEnd = ' ';

    if ( *argument == '\'' || *argument == '"' )
        cEnd = *argument++;

    while ( *argument != '\0' )
    {
        if ( *argument == cEnd )
        {
            argument++;
            break;
        }

        *pArg++ = *argument++;
    }

    *pArg = '\0';

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zSyntax to change your &Rcharacter&z's password: &Cpassword &z<&Cold&z> <&Cnew&z>." );
        return;
    }

    if ( !password_matches_hash( arg1, ch->pcdata->pwd ) )
    {
        WAIT_STATE( ch, 40 );
        ch_println( ch, "&RWrong password.  Wait 10 seconds." );
        return;
    }

    if ( strlen( arg2 ) < 5 )
    {
        send_to_char(
            "&RNew password must be at least five characters long.\n", ch );
        return;
    }

    if ( arg1[0] == '!' || arg2[0] == '!' )
    {
        send_to_char( "&RNew password cannot begin with the '!' character.", ch );
        return;
    }

    /*
        No tilde allowed because of player file format.
    */
    pwdnew = new_password( arg2 ); //crypt( arg2, ch->name );

    for ( p = pwdnew; *p != '\0'; p++ )
    {
        if ( *p == '~' )
        {
            send_to_char(
                "&RNew password not acceptable, try again.\n", ch );
            return;
        }
    }

    SET_STRING( ch->pcdata->pwd, pwdnew );
    ch->pcdata->resetpwd = 0;
    ch->pcdata->resetpwd_date = 0;

    if ( IS_SET( sysdata.save_flags, SV_PASSCHG ) )
        save_char_obj( ch, true );

    ch_println( ch, "&wCharacter password changed." );
    return;
}



CMDF do_socials( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
