CMDF do_commands( CHAR_DATA* ch, char* argument )
{
    int col, cnt = 0;
    bool found = FALSE;
    int hash;
    CMDTYPE* command;
    col = 0;

    if ( NULLSTR( argument ) )
    {
        for ( hash = 0; hash < 126; hash++ )
            for ( command = command_hash[hash]; command; command = command->next )
                if ( command->level <= get_trust( ch ) && ( command->name[0] != 'm' || command->name[1] != 'p' ) )
                {
                    pager_printf( ch, "&z(&C%3d&z) &B%-16s", command->level, command->name );
                    cnt++;

                    if ( ++col % 3 == 0 )
                        send_to_pager( "\n", ch );
                }

        if ( col % 3 != 0 )
            send_to_pager( "\n", ch );
    }
    else
    {
        found = FALSE;

        for ( hash = 0; hash < 126; hash++ )
            for ( command = command_hash[hash]; command; command = command->next )
                if ( command->level <  LEVEL_HERO
                        &&   command->level <= get_trust( ch )
                        &&  !str_prefix( argument, command->name )
                        &&  ( command->name[0] != 'm'
                              &&   command->name[1] != 'p' ) )
                {
                    cnt++;
                    pager_printf( ch, "&z(&C%3d&z) &B%-16s", command->level, command->name );
                    found = TRUE;

                    if ( ++col % 3 == 0 )
                        send_to_pager( "\n", ch );
                }

        if ( col % 3 != 0 )
            send_to_pager( "\n", ch );

        if ( !found )
            ch_println( ch, "&zNo command found under &C%s&z.", argument );
    }

    if ( cnt > 0 && found )
        ch_println( ch, "&zThere are &C%d&z commands listed above.", cnt );

    return;
}

