                    , ch );

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_TALK )
                    ? "&z[&G+TALK&z        ] You see in-character comlink messages.\n"
                    : "&z[&R-talk&z        ] You do not see in-character comlink messages.\n"
                    , ch );

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_YELL )
                    ? "&z[&G+YELL&z        ] You hear nearby yells.\n"
                    : "&z[&R-yell&z        ] You do not hear nearby yells.\n"
                    , ch );

        ch_println( ch, "\n&WOut-of-Character (OOC) Channels" );

        if ( get_trust( ch ) < sysdata.log_level )
        {
            send_to_char(  !xIS_SET( ch->deaf, CHANNEL_IMMCHAT )
                        ? "&z[&G+IMMCHAT&z     ] You see communications between yourself and imms.\n"
                        : "&z[&R-immchat&z     ] You do not see communications between yourself and imms.\n"
                        , ch );
        }

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_NEWBIE )
                    ? "&z[&G+NEWBIE&z      ] You see the global out-of-character newbie chat.\n"
                    : "&z[&R-newbie&z      ] You do not see the global out-of-character newbie chat.\n"
                    , ch );

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_OOC )
                    ? "&z[&G+OOC&z         ] You see the global out-of-character chat.\n"
                    : "&z[&R-ooc&z         ] You do not see the global out-of-character chat.\n"
                    , ch );

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_OSAY )
                    ? "&z[&G+OSAY&z        ] You see in-room out-of-character messages.\n"
                    : "&z[&R-osay&z        ] You do not see in-room out-of-character messages.\n"
                    , ch );

        send_to_char(  !xIS_SET( ch->deaf, CHANNEL_TELLS )
                    ? "&z[&G+TELLS&z       ] You see private out-of-character messages from others.\n"
                    : "&z[&R-tells&z       ] You do not see private out-of-character messages from others.\n"
                    , ch );

        if ( IS_RPC( ch ) )
        {
            ch_println( ch, "\n&WRPC Channels" );
            send_to_char(  !xIS_SET( ch->deaf, CHANNEL_COUNCIL )
                        ? "&z[&G+COUNCIL&z     ] You see RPC councilnet messages.\n"
                        : "&z[&R-council&z     ] You do not see RPC councilnet messages.\n"
                        , ch );

            send_to_char(  !xIS_SET( ch->deaf, CHANNEL_RPC )
                        ? "&z[&G+RPC&z         ] You see messages between RPC and players.\n"
                        : "&z[&R-rpc&z         ] You do not see messages between RPC and players.\n"
                        , ch );
        }

        if ( IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "\n&WStaff Channels" );
            if ( get_trust( ch ) >= sysdata.log_level )
            {
                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_BUILD )
                            ? "&z[&G+BUILD&z       ] You see the build log channel.\n"
                            : "&z[&R-build&z       ] You do not see the build log channel.\n"
                            , ch );

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_COMM )
                            ? "&z[&G+COMM&z        ] You see the comm channel.\n"
                            : "&z[&R-comm&z        ] You do not see the comm channel.\n"
                            , ch );

                if ( get_trust( ch ) >= LEVEL_ADMIN || is_name( "chan_debug", ch->pcdata->bestowments ) )
                {
                    send_to_char(  !xIS_SET( ch->deaf, CHANNEL_DEBUG )
                                ? "&z[&G+DEBUG&z       ] You see the debug channel.\n"
                                : "&z[&R-debug&z       ] You do not see the debug channel.\n"
                                , ch );
                }

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_IMMCHAT )
                            ? "&z[&G+IMMCHAT&z     ] You see messages between imms and players.\n"
                            : "&z[&R-immchat&z     ] You do not see messages between imms and players.\n"
                            , ch );

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_IMMTALK )
                            ? "&z[&G+IMMTALK&z     ] You see the private imm channel.\n"
                            : "&z[&R-immtalk&z     ] You do not see the private imm channel.\n"
                            , ch );
            }

            send_to_char(  !xIS_SET( ch->deaf, CHANNEL_INTERPORT )
                        ? "&z[&G+INTERPORT&z   ] You see messages relayed from other MUD ports.\n"
                        : "&z[&R-interport&z   ] You do not see messages relayed from other MUD ports.\n"
                        , ch );

            if ( get_trust( ch ) >= sysdata.log_level )
            {
                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_LOG )
                            ? "&z[&G+LOG&z         ] You see the log channel.\n"
                            : "&z[&R-log&z         ] You do not see the log channel.\n"
                            , ch );

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_LPROG )
                            ? "&z[&G+LPROG&z       ] You see the lprog log channel.\n"
                            : "&z[&R-lprog&z       ] You do not see the lprog log channel.\n"
                            , ch );

                if ( get_trust( ch ) >= LEVEL_PR_ADMIN )
                {
                    send_to_char(  !xIS_SET( ch->deaf, CHANNEL_MICROPHONE )
                                ? "&z[&G+MICROPHONE&z  ] You see the microphone channel.\n"
                                : "&z[&R-microphone&z  ] You do not see the microphone channel.\n"
                                , ch );
                }

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_MONITOR )
                            ? "&z[&G+MONITOR&z     ] You see the monitor channel.\n"
                            : "&z[&R-monitor&z     ] You do not see the monitor channel.\n"
                            , ch );

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_MPROG )
                            ? "&z[&G+MPROG&z       ] You see the mprog log channel.\n"
                            : "&z[&R-mprog&z       ] You do not see the mprog log channel.\n"
                            , ch );

                send_to_char(  !xIS_SET( ch->deaf, CHANNEL_RPC )
                            ? "&z[&G+RPC&z         ] You see messages between RPC and players.\n"
                            : "&z[&R-rpc&z         ] You do not see messages between RPC and players.\n"
                            , ch );

                if ( get_trust( ch ) >= LEVEL_ADMIN || is_name( "chan_tune", ch->pcdata->bestowments ) )
                {
                    send_to_char(  !xIS_SET( ch->deaf, CHANNEL_TUNE )
                                ? "&z[&G+TUNE&z        ] You see the tune channel.\n"
                                : "&z[&R-tune&z        ] You do not see the tune channel.\n"
                                , ch );
                }
            }
        }
    }
    else
    {
        bool fClear;
        bool ClearAll;
        int bit;
        bit = 0;
        ClearAll = FALSE;

        if ( arg[0] == '+' )
            fClear = TRUE;
        else if ( arg[0] == '-' )
            fClear = FALSE;
        else
        {
            ch_println( ch, "Channels -channel or +channel?" );
            return;
        }

        if ( !str_cmp( arg + 1, "team"     ) )
            bit = CHANNEL_TEAM;
        else if ( !str_cmp( arg + 1, "chat"     ) )
            bit = CHANNEL_CHAT;
        else if ( !str_cmp( arg + 1, "ooc"      ) )
            bit = CHANNEL_OOC;
        else if ( !str_cmp( arg + 1, "clan"     ) )
            bit = CHANNEL_CLAN;
        else if ( !str_cmp( arg + 1, "talk"     ) )
            bit = CHANNEL_TALK;
        else if ( !str_cmp( arg + 1, "council"  ) && IS_RPC( ch ) )
            bit = CHANNEL_COUNCIL;
        else if ( !str_cmp( arg + 1, "tells"    ) )
            bit = CHANNEL_TELLS;
        else if ( !str_cmp( arg + 1, "immtalk"  ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_IMMTALK;
        else if ( !str_cmp( arg + 1, "log"      ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_LOG;
        else if ( !str_cmp( arg + 1, "build"    ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_BUILD;
        else if ( !str_cmp( arg + 1, "monitor"  ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_MONITOR;
        else if ( !str_cmp( arg + 1, "newbie"   ) )
            bit = CHANNEL_NEWBIE;
        else if ( !str_cmp( arg + 1, "gni"   ) )
            bit = CHANNEL_GNI;
        else if ( !str_cmp( arg + 1, "arena"    ) )
            bit = CHANNEL_ARENA;
        else if ( !str_cmp( arg + 1, "yell"     ) )
            bit = CHANNEL_YELL;
        else if ( !str_cmp( arg + 1, "comm"     ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_COMM;
        else if ( !str_cmp( arg + 1, "microphone" ) && get_trust( ch ) >= LEVEL_PR_ADMIN )
            bit = CHANNEL_MICROPHONE;
        else if ( !str_cmp( arg + 1, "osay"    ) )
            bit = CHANNEL_OSAY;
        else if ( !str_cmp( arg + 1, "mprog"    ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_MPROG;
        else if ( !str_cmp( arg + 1, "interport" ) && IS_IMMORTAL( ch ) )
            bit = CHANNEL_INTERPORT;
        else if ( !str_cmp( arg + 1, "rpc" ) && ( get_trust( ch ) == LEVEL_RPC || get_trust( ch ) >= sysdata.log_level || has_pcflag( ch, PCFLAG_NCOUNCIL ) ) )
            bit = CHANNEL_RPC;
        else if ( !str_cmp( arg + 1, "immchat" ) )
            bit = CHANNEL_IMMCHAT;
        else if ( !str_cmp( arg + 1, "tune" ) && ( get_trust( ch ) >= LEVEL_ADMIN || is_name( "chan_tune", ch->pcdata->bestowments ) ) )
            bit = CHANNEL_TUNE;
        else if ( !str_cmp( arg + 1, "debug" ) && ( get_trust( ch ) >= LEVEL_ADMIN || is_name( "chan_debug", ch->pcdata->bestowments ) ) )
            bit = CHANNEL_DEBUG;
        else if ( !str_cmp( arg + 1, "lprog"    ) && get_trust( ch ) >= sysdata.log_level )
            bit = CHANNEL_LPROG;
        else if ( !str_cmp( arg + 1, "all"      ) )
            ClearAll = TRUE;
        else
        {
            ch_println( ch, "Set or clear which channel?" );
            return;
        }

        if ( ( fClear ) && ( ClearAll ) )
        {
            xREMOVE_BIT ( ch->deaf, CHANNEL_TEAM );
            xREMOVE_BIT ( ch->deaf, CHANNEL_CHAT );
            xREMOVE_BIT ( ch->deaf, CHANNEL_ARENA );
            xREMOVE_BIT ( ch->deaf, CHANNEL_YELL );
            xREMOVE_BIT ( ch->deaf, CHANNEL_OOC );
            xREMOVE_BIT ( ch->deaf, CHANNEL_CLAN );
            xREMOVE_BIT ( ch->deaf, CHANNEL_TELLS );
            xREMOVE_BIT ( ch->deaf, CHANNEL_NEWBIE );
            xREMOVE_BIT ( ch->deaf, CHANNEL_GNI );
            xREMOVE_BIT ( ch->deaf, CHANNEL_INTERPORT );

            if ( get_trust( ch ) > 102 )
                xREMOVE_BIT ( ch->deaf, CHANNEL_RPC );

            if ( get_trust( ch ) > 104 )
                xREMOVE_BIT ( ch->deaf, CHANNEL_IMMCHAT );
        }
        else if ( ( !fClear ) && ( ClearAll ) )
        {
            xSET_BIT ( ch->deaf, CHANNEL_TEAM );
            xSET_BIT ( ch->deaf, CHANNEL_CHAT );
            xSET_BIT ( ch->deaf, CHANNEL_ARENA );
            xSET_BIT ( ch->deaf, CHANNEL_YELL );
            xSET_BIT ( ch->deaf, CHANNEL_OOC );
            xSET_BIT ( ch->deaf, CHANNEL_CLAN );
            xSET_BIT ( ch->deaf, CHANNEL_TELLS );
            xSET_BIT ( ch->deaf, CHANNEL_NEWBIE );
            xSET_BIT ( ch->deaf, CHANNEL_GNI );
            xSET_BIT ( ch->deaf, CHANNEL_INTERPORT );

            if ( get_trust( ch ) > 102 )
                xSET_BIT ( ch->deaf, CHANNEL_RPC );

            if ( get_trust( ch ) > 104 )
                xSET_BIT ( ch->deaf, CHANNEL_IMMCHAT );
        }
        else if ( fClear )
        {
            if ( xIS_SET( ch->deaf, bit ) && ( bit == CHANNEL_DEBUG || bit == CHANNEL_TUNE ) )
                debuggers++;

            xREMOVE_BIT ( ch->deaf, bit );

            if ( bit == CHANNEL_DEBUG || bit == CHANNEL_TUNE )
            {
                if ( !str_cmp( arg2, "filter" ) )
                {
                    if ( NULLSTR( arg3 ) )
                    {
                        ch_println( ch, "Filter on what??" );
                    }
                    else
                    {
                        smash_tilde( arg3 );

                        switch ( bit )
                        {
                            case CHANNEL_DEBUG:
                                SET_STRING( ch->pcdata->debug_filter, ( !NULLSTR( arg3 ) && str_cmp( arg3, "none" ) ) ? arg3 : NULL );
                                break;

                            case CHANNEL_TUNE:
                                SET_STRING( ch->pcdata->tune_filter, ( !NULLSTR( arg3 ) && str_cmp( arg3, "none" ) ) ? arg3 : NULL );
                                break;
                        }

                        ch_println( ch, "Filter set." );
                    }
                }
            }
        }
        else
        {
            if ( !xIS_SET( ch->deaf, bit ) && ( bit == CHANNEL_DEBUG || bit == CHANNEL_TUNE ) )
                debuggers--;

            xSET_BIT( ch->deaf, bit );
        }

        ch_println( ch, "Ok." );
    }

    return;
}


CMDF do_config( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];

    if ( IS_NPC( ch ) )
        return;

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&WGameplay Options" );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTOAFK )
                       ? "&z[&G+AUTOAFK&z     ] You automatically go AFK after being idle for 10 minutes.\n"
                       : "&z[&R-autoafk&z     ] You do not automatically go AFK.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTOGOLD )
                       ? "&z[&G+AUTOCRED&z    ] You automatically split credits from kills in groups.\n"
                       : "&z[&R-autocred&z    ] You don't automatically split credits from kills in groups.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTODRAW )
                       ? "&z[&G+AUTODRAW&z    ] You automatically draw your weapons in combat.\n"
                       : "&z[&R-autodraw&z    ] You will not draw weapons automatically in combat.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTOLOOT )
                       ? "&z[&G+AUTOLOOT&z    ] You automatically loot corpses.\n"
                       : "&z[&R-autoloot&z    ] You don't automatically loot corpses.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_NOFIGHT )
                       ? "&z[&G+NOFIGHT&z     ] You will not fight enemies in combat.\n"
                       : "&z[&R-nofight&z     ] You will attack and fight normally in combat.\n"
                       , ch );
        ch_println( ch, "\n&WDisplay Options" );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTOEXIT )
                       ? "&z[&G+AUTOEXIT&z    ] You automatically see exits.\n"
                       : "&z[&R-autoexit&z    ] You don't automatically see exits.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_BLANK )
                       ? "&z[&G+BLANK&z       ] You have a blank line before your prompt.\n"
                       : "&z[&R-blank&z       ] You have no blank line before your prompt.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_CENSOR )
                       ? "&z[&G+CENSOR&z      ] Profanity filtering is on.\n"
                       : "&z[&R-censor&z      ] Profanity filtering is off.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_COMMPROMPT )
                       ? "&z[&G+COMMPROMPT&z  ] You see a prompt for every line sent to your char.\n"
                       : "&z[&R-commprompt&z  ] You see a prompt only when you enter commands.\n"
