                       : "&z[&R-pager&z       ] Long output scrolls to the end.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_PROMPT )
                       ? "&z[&G+PROMPT&z      ] You have a prompt.\n"
                       : "&z[&R-prompt&z      ] You don't have a prompt.\n"
                       , ch );
        ch_println( ch, "\n&WSpam Reduction Options" );
        send_to_char(  has_pcflag( ch, PCFLAG_BRIEF )
                       ? "&z[&G+BRIEF&z       ] You see brief descriptions.\n"
                       : "&z[&R-brief&z       ] You see long descriptions.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_COMBINE )
                       ? "&z[&G+COMBINE&z     ] You see object lists in combined format.\n"
                       : "&z[&R-combine&z     ] You see object lists in single format.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_COMPACT )
                       ? "&z[&G+COMPACT&z     ] Compact score is on.\n"
                       : "&z[&R-compact&z     ] Compact score is off.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_GAG )
                       ? "&z[&G+GAGCOMBAT&z   ] You see only necessary ground combat text.\n"
                       : "&z[&R-gagcombat&z   ] You see full ground combat text.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_GAGPIRATES )
                       ? "&z[&G+GAGPIRATES&z  ] Output about pirates fighting other ships will be hidden.\n"
                       : "&z[&R-gagpirates&z  ] You see full output for pirate ships in combat with other ships.\n"
