                       : "&z[&R-shipstack&z   ] You see the non-consolidated view of ships on pads.\n"
                       , ch );
        ch_println( ch, "\n&WColor and Accessibility Options" );
/*        send_to_char( has_pcflag( ch, PCFLAG_NO24BIT )
                      ? "&z[&G+NO24BIT&z     ] You are downconverting 24-bit color to 256 color.\n"
                      : "&z[&R-no24bit&z     ] You are not downconverting 24-bit color to 256 color.\n"
                      , ch );*/
        send_to_char( has_pcflag( ch, PCFLAG_16 )
