                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_AUTOFORMAT )
                       ? "&z[&G+AUTOFORMAT&z  ] You are automatically formatting your sentences. (BETA)\n"
                       : "&z[&R-autoformat&z  ] You are not automatically formatting your sentences. (BETA)\n"
                       , ch );
        ch_println( ch, "\n&WConnection Options" );
        send_to_char(  has_pcflag( ch, PCFLAG_HIGHBAND )
                       ? "&z[&G+HIGHBAND&z    ] You are in high bandwidth mode.\n"
                       : "&z[&R-HIGHBAND&z    ] You are in low bandwidth mode.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_SOUND )
                       ? "&z[&G+SOUND&z       ] You have MSP support.\n"
                       : "&z[&R-sound&z       ] You don't have MSP support.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_TELNET_GA )
                       ? "&z[&G+TELNETGA&z    ] You receive a telnet GA sequence.\n"
                       : "&z[&R-telnetga&z    ] You don't receive a telnet GA sequence.\n"
                       , ch );
        send_to_char(  has_pcflag( ch, PCFLAG_WEBBUFFER )
                       ? "&z[&G+WEBBUFFER&z   ] &zYou use the web based buffer editor. &B(BETA)&z\n"
                       : "&z[&R-webbuffer&z   ] You don't use the web based buffer editor. (BETA)\n"
                       , ch );

        if ( IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "\n&WStaff Options" );

            if ( get_trust( ch ) >= 105 )
                send_to_char(  has_pcflag( ch, PCFLAG_ACCNAME )
                               ? "&z[&G+ACCNAME&z     ] You always see just account names.\n"
                               : "&z[&R-accname&z     ] You see account name and player name.\n"
                               , ch );

            send_to_char(  has_pcflag( ch, PCFLAG_AUTOSAVE )
                            ? "&z[&G+AUTOSAVE&z    ] You automatically save things while building.\n"
                            : "&z[&R-autosave&z    ] You do not automatically save things while building.\n"
                            , ch );

            send_to_char(  has_pcflag( ch, PCFLAG_NOWHO )
                           ? "&z[&G+NOWHO&z       ] You don't show up on the who listing.\n"
