                      pArea->author, pArea->name );
    }

    return;
}

CMDF do_afk( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{

    if ( IS_NPC( ch ) )
        return;

    if ( has_pcflag( ch, PCFLAG_AFK ) )
    {
        remove_pcflag( ch, PCFLAG_AFK );
        ch_println( ch, "You are no longer afk." );
        if ( IS_IMMORTAL( ch ) )
        {
            for ( CHAR_DATA* vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
            {
                if ( vch != ch && get_trust( vch ) >= get_trust( ch ) )
                    ch_printf( vch, "%s is no longer afk.", ch->name );
            }
        }
        else
            act( AT_GREY, "$n is no longer afk.", ch, NULL, NULL, TO_ROOM );
    }
    else
    {
        if ( !IS_IMMORTAL( ch ) )
        {
            do_visible( ch, "-noalert" );
            interrupt_ch( ch );
        }

        if ( ch->block )
            do_block( ch, "" );

        // Turn off holo transmitters as part of the AFK process
        for ( OBJ_DATA* obj = ch->last_carrying; obj; obj = obj->prev_content )
            if ( obj->item_type == ITEM_TRANSMITTER && obj->value[IVAL_TRANSMITTER_STATE] != 0 )
                deactivate_transmitter( ch, obj );

        set_pcflag( ch, PCFLAG_AFK );
        ch_println( ch, "You are now afk." );

        if ( IS_IMMORTAL( ch ) )
        {
            for ( CHAR_DATA* vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
            {
                if ( vch != ch && get_trust( vch ) >= get_trust( ch ) )
                    ch_printf( vch, "%s is now afk.", ch->name );
            }
        }
        else
            act( AT_GREY, "$n is now afk.", ch, NULL, NULL, TO_ROOM );

        if ( !IS_IMMORTAL(ch) && isFighting( ch ) )
        {
            char buf[MSL];
            int mm, ms;
            ms = ch->fight_timer % 60;
            mm = ch->fight_timer / 60;
            snprintf( buf, MSL, "Player %s going AFK while under fight timer: %d minute%s and %d second%s left to be able to quit", ch->name, mm, mm == 1 ? "" : "s", ms, ms == 1 ? "" : "s" );
            write_to_log( "afk_during_fight_timer", buf, sysdata.log_level, 720, true );
            lognormal(buf);
        }
        return;
    }

    return;
}

CMDF do_slist( CHAR_DATA* ch, char* argument )
{
    SKILL_DATA* skill = NULL;
    int i = 0, lowlev = 0, hilev = 0, sAbil = 0, col = 0, cnt = 0, scnt = 0, ability = 0;
    char skn[MIL], arg1[MIL], arg2[MIL], arg3[MIL];
    bool feats = FALSE;

    if ( IS_NPC( ch ) )
        return;

    argument = one_argument( argument, arg1 );

    if ( !str_cmp( "force", arg1 ) )
    {
        argument = one_argument( argument, arg1 );
        argument = one_argument( argument, arg2 );
        lowlev = atoi( arg1 ) > 0 ? atoi( arg1 ) : 1;
        hilev = MAX_LEVEL;

        if ( !NULLSTR( arg2 ) && is_number( arg2 ) && atoi( arg2 ) > 0 )
            hilev = atoi( arg2 );

        pager_println( ch, "&BFORCE POWER LISTING:" );
        pager_println( ch, "&z-----------------------------------------------" );
        pager_println( ch, "&CForce Skills:" );

        for ( i = lowlev; i <= hilev; i++ )
        {
            for ( skill = first_skill; skill; skill = skill->next )
            {
                if ( !skill->name )
                    break;

                if ( skill->guild != FORCE_ABILITY )
                    continue;

                if ( skill->type == SKILL_SPELL || skill->type == SKILL_LIGHTSABER_FORM )
                    continue;

                // if ( get_learned_pct( ch, skill ) == 0 &&  SPELL_FLAG(skill, SF_SECRETSKILL) ) continue;
                if ( SPELL_FLAG( skill, SF_SECRETSKILL ) && get_trust( ch ) <= 105 )
                    continue;

                if ( i == skill->min_level )
                {
                    pager_printf( ch, " &C%3d&z) &B%-19.19s ", i,  skill->name );

                    if ( ++col == 3 )
                    {
                        pager_printf( ch, "\n" );
                        col = 0;
                    }
                }
            }
        }

        if ( col != 0 )
        {
            pager_printf( ch, "\n" );
            col = 0;
        }

        for ( ability = 1 ; ability <= 4 ; ability++ )
        {
            if ( ability == 1 )
                pager_println( ch, "&CUniversal Spells:" );

            if ( ability == 2 )
                pager_println( ch, "&CLight Spells:" );

            if ( ability == 3 )
                pager_println( ch, "&CDark Spells:" );

            if ( ability == 4 )
                pager_println( ch, "&CLightsaber Forms:" );

            for ( i = lowlev; i <= hilev; i++ )
            {
                for ( skill = first_skill; skill; skill = skill->next )
                {
                    if ( !skill->name )
                        break;

                    if ( skill->guild != FORCE_ABILITY )
                        continue;

                    if ( ability != 4 && skill->type != SKILL_SPELL )
                        continue;

                    if ( ability == 4 && skill->type != SKILL_LIGHTSABER_FORM )
                        continue;

                    if ( skill->alignment >= 300 && ability != 2 && ability != 4 )
                        continue;

                    if ( skill->alignment <= -300 && ability != 3 && ability != 4 )
                        continue;

                    if ( skill->alignment < 300 && skill->alignment > -300 )
                        if ( ability != 1 && ability != 4 )
                            continue;

                    if ( SPELL_FLAG( skill, SF_SECRETSKILL ) && get_trust( ch ) <= 105 )
                        continue;

                    if ( i == skill->min_level )
                    {   
                        if ( skill->alignment < -1000 )
                            pager_printf( ch, " &C%3d&z) &r%-18.18s ", i,  skill->name );
                        else if ( skill->alignment > 1000 )
                            pager_printf( ch, " &C%3d&z) &g%-18.18s ", i,  skill->name );
                        else if ( skill->type == SKILL_LIGHTSABER_FORM )
                            pager_printf( ch, " &C%3d&z) &O%-18.18s ", i,  skill->name );
                        else
                            pager_printf( ch, " &C%3d&z) &B%-18.18s ", i,  skill->name );

                        if ( ++col == 3 )
                        {
                            pager_printf( ch, "\n" );
                            col = 0;
                        }
                    }
                }
            }

            if ( col != 0 )
            {
                pager_printf( ch, "\n" );
                col = 0;
            }
        }

        return;
    }

    if ( !str_cmp( "feats", arg1 ) )
    {
        feats = TRUE;
        argument = one_argument( argument, arg1 );
    }

    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );
    if ( !str_cmp( arg1, "bounty" ) )
    {
        snprintf( arg1 + strlen( arg1 ), MIL - strlen( arg1 ), " %s", arg2 );
        snprintf( arg2, MIL, "%s", arg3 );
        argument = one_argument( argument, arg3 );
    }
    /* Keep it simple. Orion */
    lowlev = atoi( arg2 ) > 0 ? atoi( arg2 ) : 1;
    hilev = MAX_LEVEL;

    if ( arg3[0] != '\0' && atoi( arg3 ) > 0 )
        hilev = atoi( arg3 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "&zSyntax: &CSLIST <&wability name&C/&wALL&C> &C[&wmin level&C] [&wmax level&C]&w" );
        ch_println( ch, "&zSyntax: &CSLIST FEATS <&wability name&C/&wALL&C> &C[&wmin level&C] [&wmax level&C]&w" );
        return;
    }

    if ( !str_cmp( arg1, "all" ) )
    {
        sAbil = -1;
    }
    else if ( !str_cmp( "feats", arg1 ) )
    {
        feats = TRUE;
        sAbil = -1;
    }
    else
    {
        for ( ability = 0; ability < MAX_ABILITY ; ability++ )
        {
            if ( ability == FORCE_ABILITY || ability == DIPLOMACY_ABILITY )
                continue;

            if ( !str_cmp( flag_value_name( ability_name, ability ), arg1 ) )
            {
                sAbil = ability;
                break;
            }
        }

        if ( ability == MAX_ABILITY )
        {
            ch_println( ch, "&RThats not a valid ability name! Try typing LEVEL." );
            return;
        }
    }

    pager_printf( ch, "&B%s LISTING: \n", feats ? "FEAT" : "SKILL" );
    send_to_pager( "&z-----------------------------------------------------------------------\n", ch );

    for ( ability = -1 ; ability < MAX_ABILITY ; ability++ )
    {
        if ( ability == FORCE_ABILITY || ability == DIPLOMACY_ABILITY || ability < 0 )
            continue;

        if ( sAbil >= 0 && ability != sAbil )
            continue;

        scnt = 0;

        if ( ability >= 0 )
            snprintf( skn, MIL, "&z&C%s %s:\n", capitalize( flag_value_name( ability_name, ability ) ), feats ? "feats" : "skills" );
        else
            snprintf( skn, MIL, "&z&CLanguages:\n" );

        send_to_pager( skn, ch );

        for ( i = lowlev; i <= hilev; i++ )
        {
            for ( skill = first_skill; skill; skill = skill->next )
            {
                if ( !skill->name )
                    break;

                if ( skill->guild != ability )
                    continue;

                if ( get_learned_pct( ch, skill ) == 0 && SPELL_FLAG( skill, SF_SECRETSKILL ) )
                    continue;

                if ( ( !feats && skill->type == SKILL_FEAT ) || ( feats && skill->type != SKILL_FEAT ) )
                    continue;

                if ( i == skill->min_level )
                {
                    cnt++;
                    scnt++;
                    pager_printf( ch, " &C%3d&z) &B%-20.20s ", i,  skill->name );

                    if ( ++col == 3 )
                    {
                        pager_printf( ch, "\n" );
                        col = 0;
                    }
                }
            }
        }

        if ( col != 0 )
        {
            pager_printf( ch, "\n" );
            col = 0;
        }

        if ( scnt <= 0 )
        {
            pager_printf( ch, " &z(&BThere are no %s in that range in this class&z)\n", feats ? "feats" : "skills" );
        }
    }

    send_to_pager( "&z-----------------------------------------------------------------------\n", ch );
    pager_printf( ch, "&zThere %s &C%d &z%s%s listed above.\n", cnt == 1 ? "is" : "are", cnt, feats ? "feat" : "skill", cnt == 1 ? "" : "s" );
    return;
}

CMDF do_whois( CHAR_DATA* ch, char* argument )
{
    char buf2[MSL];
    CHAR_DATA* victim;
    OBJ_DATA* datapad;
    // bool fakeip=FALSE;

    if ( IS_NPC( ch ) )
        return;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&RYou must input the name of a player online." );
        return;
    }

    datapad = has_datapad( ch );

    if ( ( ( victim = get_player_world( argument ) ) == NULL ) )
    {
        if ( ( victim = get_char_room( ch, argument ) ) != NULL )
        {}
        else
        {
            if ( datapad == NULL && !IS_RPC( ch ) )
            {
                ch_println( ch, "&RYou're not going to find anything out without a datapad." );
                return;
            }

            ch_println( ch, "&zCould not locate that file in the database." );
            return;
        }
    }

    if ( datapad == NULL && !IS_RPC( ch ) && ch != victim )
    {
        ch_println( ch, "&RYou're not going to find anything out without a datapad." );
        return;
    }

    if ( IS_RPC( ch ) && get_trust( victim ) >= get_trust( ch ) && victim != ch )
    {
        ch_println( ch, "&RSorry, to preserve privacy you cannot see that immortal's whois screen." );
        return;
    }

    if ( IS_NPC( victim ) || !victim->pcdata )
    {
        ch_println( ch, "&RThat's not a player!" );
        return;
    }

    if ( has_pcflag( victim, PCFLAG_WHOIS ) && !IS_RPC( ch ) && ch != victim )
    {
        ch_println( ch, "&zYou could not locate them in the database." );
        return;
    }

    // Vong can't be looked up. They would not be in some computer database of people.
    if ( ( xIS_SET( victim->race->flags, RFLAG_VONG ) || xIS_SET( victim->race->flags, RFLAG_CHISS ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&zYou could not locate them in the database." );
        return;
    }

    /*
        Ghost is 42 year old male human.
        Ghost is level 200.
        Ghost is a member of the Empire.
        Ghost is a member of the Roleplay Council.
        Ghost is currently in room 100.
        Ghost's Roleplay Rating: [|||||||---]
        Ghost's homepage can be found at http:\\www.archsysinc.com/finalstands/
        Ghost's personal bio:
        [Bio]
        Info for immortals:
        Ghost was authorized by Raven.
        ...
    */

    if ( knows_player( ch, victim, GREET_KNOWN, false ) )
    {
        if ( IS_IMMORTAL( ch ) )
            dch_println( ch, "&z%s is a &C%s %s&z.&w", g_name( victim, ch ),
                        victim->sex == SEX_MALE ? "male" : victim->sex == SEX_FEMALE ? "female" : "neutral",
                        get_race( victim ) );
        else
            dch_println( ch, "&z%s is a &c%s %s&z.&w", g_name( victim, ch ), victim->sex == SEX_FEMALE ? "female" : victim->sex == SEX_MALE
                        ? "male" : "neutral", get_race( victim ) );
    }
    else
    {
        dch_println( ch, "&z%s is a &C%s&z.&w", g_name( victim, ch ),
                    victim->sex == SEX_MALE ? "male" : victim->sex == SEX_FEMALE ? "female" : "neutral" );
    }

    dch_println( ch, "&z%s is level &C%d&z.&w", g_name( victim, ch ), victim->top_level );

    //Ralen Apr 2015 - Show a player's rank in lookup aswell.
    if ( victim->pcdata->clan )
    {
        if ( !xIS_SET( victim->pcdata->clan->flags, CLAN_HIDEWHOIS ) || get_trust( ch ) >= sysdata.log_level )
            dch_println( ch, "&z%s is a %s&z in &C%s&z.&w", g_name( victim, ch ), get_rank( victim ), victim->pcdata->clan->name );
    }

    ch_println( ch, "&z%s is currently wanted on &C%s&z.&w", g_name( victim, ch ), print_wanted( victim, FALSE ) );
    ch_println( ch, "&z%s currently has immunity on &C%s&z.&w", g_name( victim, ch ), print_wanted( victim, TRUE ) );

    if ( has_pcflag( victim, PCFLAG_NCOUNCIL ) )
        dch_println( ch, "&z%s is a member of &Bthe Roleplay Council&z.&w", victim->name );

    if ( IS_IMMORTAL( ch ) )
        ch_println( ch, "&z%s is currently in room &C%d&z.&w", g_name( victim, ch ), victim->in_room->vnum );

    if ( get_trust( ch ) == 101 || get_trust( ch ) >= sysdata.log_level )
        ch_println( ch, "&z%s's desc&w:\n&W%s", victim->name, victim->description ? victim->description : "<NONE>" );

    if ( victim->pcdata->bio && victim->pcdata->bio[0] != '\0' )
    {
        dch_printf( ch, "&z%s's databank file: &W\n%s", g_name( victim, ch ), victim->pcdata->bio );
    }
    else
    {
        ch_println( ch, "&RCould not retrieve databank file. Contact databank admins." );
    }

    if ( IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "&z----------------------------------------------------" );
        ch_println( ch, "&BInfo for immortals:" );

        ch_println( ch, "&zTitle: &w%s", victim->pcdata->title );
        ch_println( ch, "&zPublic Title: &w%s", victim->pcdata->pubtitle );
        if ( victim->disguise && !NULLSTR( victim->disguise->pubtitle ) )
            ch_println( ch, "&zDisguise Public Title: &w%s", victim->disguise->pubtitle );

        if ( get_trust( ch ) >= 105 && victim->pcdata->authed_by && victim->pcdata->authed_by[0] != '\0' )
            ch_println( ch, "&z%s was authorized by &C%s.",
                       victim->name, victim->pcdata->authed_by );

        ch_printf( ch, "&z%s was created on &C%s\n", victim->name, ctime( &( victim->created_at ) ) );
        ch_println( ch, "&z%s has killed &C%d &zmobiles, and been killed by a mobile &C%d &ztimes.",
                   victim->name, victim->pcdata->mkills, victim->pcdata->mdeaths );

        if ( victim->pcdata->pkills || victim->pcdata->pdeaths )
            ch_println( ch, "&z%s has killed &C%d &zplayers, and been killed by a player &C%d&z times.",
                       victim->name, victim->pcdata->pkills, victim->pcdata->pdeaths );

        if ( victim->pcdata->illegal_pk )
            ch_println( ch, "&z%s has committed &C%d&z illegal player kills.",
                       victim->name, victim->pcdata->illegal_pk );

        ch_println( ch, "&z%s is %shelled at the moment.",
                   victim->name,
                   ( victim->pcdata->release_date == 0 ) ? "not " : "" );

        if ( victim->pcdata->release_date != 0 )
            ch_println( ch, "&z%s was helled by &C%s&z, and will be released on &C%24.24s.",
                       victim->sex == SEX_MALE ? "He" :
                       victim->sex == SEX_FEMALE ? "She" : "It",
                       victim->pcdata->helled_by,
                       ctime( &victim->pcdata->release_date ) );

        if ( is_silenced( victim ) || has_pcflag( victim, PCFLAG_NO_EMOTE )
                || has_pcflag( victim, PCFLAG_NO_TELL ) || has_pcflag( victim, PCFLAG_SCREENREADER ) )
        {
            snprintf( buf2, MSL, "&zThis player has the following flags set:&C" );

            if ( is_silenced( victim ) )
                strlcat( buf2, " silence", MSL );

            if ( has_pcflag( victim, PCFLAG_NO_EMOTE ) )
                strlcat( buf2, " noemote", MSL );

            if ( has_pcflag( victim, PCFLAG_NO_TELL ) )
                strlcat( buf2, " notell", MSL );

            if ( has_pcflag( victim, PCFLAG_SCREENREADER ) )
                strlcat( buf2, " screenreader", MSL );

            strlcat( buf2, ".\n", MSL );
            send_to_char( buf2, ch );
        }

        //    if ( victim->pcdata->fakeip && victim->pcdata->fakeip[0] != '\0' )
        //   fakeip=TRUE;
        if ( victim->desc && victim->desc->host[0] != '\0' ) /* added by Gorog */
        {
            snprintf( buf2, MSL, "&z%s's IP info: &C", victim->name );

            if ( get_trust( ch ) >= LEVEL_GOD )
            {
                strlcat( buf2, victim->desc->user, MSL );
                strlcat( buf2, "@", MSL );
                // strlcat( buf2, fakeip ? victim->pcdata->fakeip : victim->desc->host, MSL );
                strlcat( buf2, get_char_ip( ch, victim->desc ), MSL );
            }

            strlcat( buf2, "\n", MSL );
            send_to_char( buf2, ch );
        }

        if ( get_trust( ch ) >= LEVEL_GOD && get_trust( ch ) >= get_trust( victim ) && victim->pcdata )
        {
            snprintf( buf2, MSL, "&zEmail: &C%s\n", victim->pcdata->email );
            send_to_char( buf2, ch );
        }

#ifdef CLIENT

        if ( victim->desc && victim->desc->client[0] != '\0' )
            ch_println( ch, "&zClient is: &C%s", victim->desc->client );

#endif
    }

    dch_flush( ch );
}

