CMDF do_pager( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];

    if ( !ch || IS_NPC( ch ) )
        return;

    set_char_color( AT_NOTE, ch );
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {            
        if ( has_pcflag( ch, PCFLAG_PAGERON ) )
            remove_pcflag( ch, PCFLAG_PAGERON );
        else
            set_pcflag( ch, PCFLAG_PAGERON );

        do_save( ch, "-noalert" );
        ch_println( ch, "Pager %s", has_pcflag( ch, PCFLAG_PAGERON ) ? "enabled" : "disabled" );
        return;
    }

    if ( !is_number( arg ) )
    {
        ch_println( ch, "Set page pausing to how many lines?" );
        return;
    }

    ch->pcdata->pagerlen = atoi( arg );

    if ( ch->pcdata->pagerlen < 5 )
        ch->pcdata->pagerlen = 5;
    do_save( ch, "-noalert" );
    ch_println( ch, "Page pausing set to %d lines.", ch->pcdata->pagerlen );
    return;
}

