/*
    Converts color tokens into HTML Color Codes.
    -Ghost
*/
char* conv_hcolor( char* msg )
{
    char wrkstr[2];
    conv_result[0] = 0;
    wrkstr[1] = 0;

    while ( *msg != 0 )
    {
        if ( *msg == '^' )
        {
            msg++;
        }
        else if ( *msg == '&' )
        {
            msg++;

            /*
                The Following Lines allow the sub to replace the & with
                a color in the HTML Document. Removed for convinence.

            */
            switch ( *msg )
            {
                case 'x':
                    strlcat( conv_result, "<font color=#000000>", MSL );
                    break;  /* Black */

                case 'g':
                    strlcat( conv_result, "<font color=#008000>", MSL );
                    break;  /* Green */

                case 'b':
                    strlcat( conv_result, "<font color=#000080>", MSL );
                    break;  /* Dark Blue */

                case 'c':
                    strlcat( conv_result, "<font color=#408080>", MSL );
                    break;  /* Cyan */

                case 'z':
                    strlcat( conv_result, "<font color=#669999>", MSL );
                    break;  /* Dark Grey */

                case 'G':
                    strlcat( conv_result, "<font color=#00FF00>", MSL );
                    break;  /* Light Green */

                case 'B':
                    strlcat( conv_result, "<font color=#0000FF>", MSL );
                    break;  /* Blue */

                case 'C':
                    strlcat( conv_result, "<font color=#00FFFF>", MSL );
                    break;  /* Light Blue */

                case 'r':
                    strlcat( conv_result, "<font color=#800000>", MSL );
                    break;  /* Blood Red */

                case 'O':
                    strlcat( conv_result, "<font color=#804000>", MSL );
                    break;  /* Orange(Brown) */

                case 'p':
                    strlcat( conv_result, "<font color=#FF00FF>", MSL );
                    break;  /* Purple */

                case 'w':
                    strlcat( conv_result, "<font color=#FFFFFF>", MSL );
                    break;  /* Gray(White?) */

                case 'R':
                    strlcat( conv_result, "<font color=#FF0000>", MSL );
                    break;  /* Light Red */

                case 'Y':
                    strlcat( conv_result, "<font color=#FFFF00>", MSL );
                    break;  /* Yellow */

                case 'P':
                    strlcat( conv_result, "<font color=#FF00FF>", MSL );
                    break;  /* Pink */

                case 'W':
                    strlcat( conv_result, "<font color=#C0C0C0>", MSL );
                    break;  /* White(Grey?) */
            }
        }
        else
        {
            wrkstr[0] = *msg;
            strlcat( conv_result, wrkstr, MSL );
        }

        msg++;
    }

    return conv_result;
}

/*
    Ranks by number of matches between two whole words.
    + Code by Senir, for the Similar Help snippet. Thanks, Senir!
*/
sh_int str_similarity( const char* astr, const char* bstr )
{
    sh_int matches = 0;

    if ( !astr || !bstr )
        return matches;

    for ( ; *astr; astr++ )
    {
        if ( LOWER( *astr ) == LOWER( *bstr ) )
            matches++;

        bstr++;

        if ( *bstr == '\0' )
            return matches;
    }

    return matches;
}

/*
    Ranks by number of matches until there's a non-matching character between two words.
    + Code by Senir, for the Similar Help snippet. Thanks, Senir!
*/
sh_int str_prefix_level( const char* astr, const char* bstr )
{
    sh_int matches = 0;

    if ( !astr || !bstr )
        return matches;

    for ( ; *astr; astr++ )
    {
        if ( LOWER( *astr ) == LOWER( *bstr ) )
            matches++;
        else
            return matches;

        bstr++;

        if ( *bstr == '\0' )
            return matches;
    }

    return matches;
}

/*
    Main function of Similar Helpfiles Snippet by Senir. It loops through all of the
    helpfiles, using the string matching function defined to find the closest matching
    helpfiles to the argument. It then checks for singles. Then, if matching helpfiles
    are found at all, it loops through and prints out the closest matching helpfiles.
    If its a single(there's only one), it opens the helpfile.
*/
void similar_help_files( CHAR_DATA* ch, char* argument )
{
    HELP_DATA* pHelp = NULL;
    char buf[MSL];
    char* extension;
    sh_int lvl = 0;
    bool single = FALSE;
    bool banner = FALSE;
    //    bug("%s:%d %s",__FUNCTION__,__LINE__,argument);

    for ( pHelp = first_help; pHelp; pHelp = pHelp->next )
    {
        if ( ch && !str_cmp( pHelp->keyword, "fmotd" ) && get_trust( ch ) < sysdata.log_level && ch->skill_level[FORCE_ABILITY] < 2 )
            continue;

        buf[0] = '\0';
        extension = pHelp->keyword;

        if ( pHelp->level > get_trust( ch ) )
            continue;

        while ( extension[0] != '\0' )
        {
            extension = one_argument( extension, buf );

            if ( str_similarity( argument, buf ) > lvl )
            {
                lvl = str_similarity( argument, buf );
                single = TRUE;
            }
            else if ( str_similarity( argument, buf ) == lvl && lvl > 0 )
            {
                single = FALSE;
            }
        }
    }

    if ( lvl == 0 )
    {
        send_to_pager_color( " &RNo similar help files.\n", ch );
        return;
    }

    for ( pHelp = first_help; pHelp; pHelp = pHelp->next )
    {
        if ( ch && !str_cmp( pHelp->keyword, "fmotd" ) && get_trust( ch ) < sysdata.log_level && ch->skill_level[FORCE_ABILITY] < 2 )
            continue;

        strlcpy( buf, "", MSL );
        extension = pHelp->keyword;

        while ( extension[0] != '\0' )
        {
            extension = one_argument( extension, buf );

            if ( str_similarity( argument, buf ) >= lvl
                    && pHelp->level <= get_trust( ch ) )
            {
                if ( single )
                {
                    send_to_pager_color( " &wOpening only similar helpfile.&w\n", ch );
                    send_to_pager_color( "&W", ch );
                    send_to_pager( pHelp->keyword, ch );
                    send_to_pager( "\n", ch );
                    sound_to_char( ch, "help" );

                    if ( pHelp->text[0] == '.' )
                        send_to_pager_color( pHelp->text + 1, ch );
                    else
                        send_to_pager_color( pHelp->text, ch );

                    char buf2[MIL];
                    strlcpy( buf2, "", MIL );

                    if ( pHelp->lasteditor && pHelp->lastedittime )
                    {
                        time_t last_edited = ( time_t ) ( pHelp->lastedittime );
                        snprintf( buf2, MIL, "&z---------------------------\n&wHelp file last modified by &C%s &won &C%s&w\n", pHelp->lasteditor, c_time( last_edited, get_timezone( ch ) ) );
                    }

                    if ( IS_IMMORTAL( ch ) )
                        snprintf( buf2 + strlen( buf2 ), MIL - strlen( buf2 ), "&z---------------------------\n&wHelp file level &C%d&w\n", pHelp->level );

                    send_to_pager_color( buf2, ch );

                    return;
                }

                if ( !banner )
                {
                    send_to_pager_color( " Similar Help Files:\n", ch );
                    banner = TRUE;
                }

                if ( IS_IMMORTAL( ch ) )
                    pager_printf( ch, "&G %3d %s\n", pHelp->level, pHelp->keyword );
                else
                    pager_printf( ch, "&G   %s\n", pHelp->keyword );

                break;
            }
        }
    }

    return;
}
