    switch ( id )
    {
        case 6:
            id = 5;
            break;

        case 8:
            id = 7;
            break;

        case 14:
            id = 3;
            break;

        case 17:
            id = 1;
            break;

        case 20:
            id = 4;
            break;

        case 21:
            id = 2;
            break;

        case 23:
            id = 11;
            break;

        case 28:
            id = 7;
            break;

        case 31:
            id = 10;
            break;

        case 32:
            id = 9;
            break;

        case 33:
            id = 13;
            break;

        case 34:
            id = 3;
            break;

        case 36:
            id = 4;
            break;
    }

    int i = 0;

    while ( true )
    {
        if ( skincolors[i].id == -1 )
            return NULL;

        if ( skincolors[i].id == id )
            return &skincolors[i];

        i++;
    }
}

