        if ( !str_cmp( skincolors[i].name, name ) )
            return &skincolors[i];

        i++;
    }
}

// Returns a random skincolor valid for the given race
const SKINCOLOR_DATA* random_race_skincolor( const RACE_DATA *race )
{
    int opt_count = 0;

    if ( !race )
        return &skincolors[0];

    for ( int i = 0; skincolors[i].id != -1; i++ )
        if ( xIS_SET( race->skincolors, skincolors[i].id ) )
            opt_count++;

    int choice = number_range( 1, opt_count );

    for ( int i = 0; skincolors[i].id != -1; i++ )
        if ( xIS_SET( race->skincolors, skincolors[i].id ) )
            if ( --choice == 0 )
                return &skincolors[i];

    // This shouldn't happen for any properly configured race
    return &skincolors[0];
}

