void action_set( CHAR_DATA* ch, CHAR_DATA* victim, const char* room, const char* targ, int time )
{
    action_set_ex( ch, victim, room, targ, time, 0 );
}

void action_set_ex( CHAR_DATA* ch, CHAR_DATA* victim, const char* room, const char* targ, int time, int flags )
{
    if ( ch->action_locked && !IS_SET( flags, AS_UNLOCK ) )
    {
        debug( "suppressing attempt to override locked action desc on %s", ch->name );
        return;
    }

    if ( IS_SET( flags, AS_UNLOCK ) )
    {
        debug( "unlocking action desc on %s", ch->name );
        ch->action_locked = false;
        return;
    }

    if ( IS_SET( flags, AS_LOCK ) )
    {
        debug( "locking action desc on %s", ch->name );
        ch->action_locked = true;
    }

    if ( ( victim && !targ ) || !room )
    {
        bug( "action_set: %s invalid sequence.", ch->name );
        return;
    }

    if ( victim )
    {
        ch->action_to = victim;
        SET_STRING( ch->action_room, room );
        SET_STRING( ch->action_char, targ );
        ch->action_timer = time;
    }
    else
    {
        ch->action_to = NULL;
        SET_STRING( ch->action_room, room );
        SET_STRING( ch->action_char, "" );
        ch->action_timer = time;
    }
}

char* get_action( CHAR_DATA* ch, CHAR_DATA* looker )
{
    char buf[MSL];

    if ( !ch || !looker )
        return "";

    if ( looker == ch->action_to )
    {
        snprintf( buf, MSL, " %s", ch->action_char );
        return action_string( buf, looker, ch, NULL, looker );
    }
    else if ( ch == ch->action_to )
    {
        snprintf( buf, MSL, " %s", ch->action_room );
        return action_string( buf, looker, ch, NULL, ch );
    }
    else
    {
        snprintf( buf, MSL, " %s", ch->action_room );
        return action_string( buf, looker, ch, NULL, ch->action_to );
    }
}
bool in_action( CHAR_DATA* ch )
{
    if ( ch->action_to && ch->action_to->in_room != ch->in_room )
    {
        action_clear( ch );
        return FALSE;
    }

    if ( ch->action_room && ch->action_room[0] != '\0' )
        return TRUE;

    return FALSE;
}

void action_clear( CHAR_DATA* ch )
{
    action_clear_ex( ch, AS_NONE );
}

void action_clear_ex( CHAR_DATA* ch, int flags )
{
    if ( !ch || char_extracted( ch ) )
        return;

    if ( ch->action_locked && !IS_SET( flags, AS_UNLOCK ) )
    {
        debug( "suppressing attempt to clear locked action desc without unlock flag on %s", ch->name );
        return;
    }

    if ( IS_SET( flags, AS_UNLOCK ) )
    {
        debug( "unlocking action desc on %s", ch->name );
        ch->action_locked = false;
    }

    if ( IS_SET( flags, AS_LOCK ) )
    {
        debug( "locking action desc on %s", ch->name );
        ch->action_locked = true;
    }

    if ( ch->action_to )
        ch->action_to = NULL;

    SET_STRING( ch->action_room, "" );
    SET_STRING( ch->action_char, "" );
    ch->action_timer = 0;
}
