// GRAL Lets try the defined ones in mud.h
#define NAME(ch)        (IS_NPC(ch) ? ch->short_descr : ch->name)
char* action_string( const char* format, CHAR_DATA* to, CHAR_DATA* ch,
                     const void* arg1, const void* arg2 )
{
    static char buf[MSL];
    char fname[MIL];
    char* point = buf;
    const char* str = format;
    const char* i;
    CHAR_DATA* vch = ( CHAR_DATA* ) arg2;
    OBJ_DATA* obj1 = ( OBJ_DATA* ) arg1;
    OBJ_DATA* obj2 = ( OBJ_DATA* ) arg2;

    while ( *str != '\0' )
    {
        if ( *str != '$' )
        {
            *point++ = *str++;
            continue;
        }

        ++str;

        if ( !arg2 && *str >= 'A' && *str <= 'Z' )
        {
            bug( "Act: missing arg2 for code %c:", *str );
            bug( format );
            i = " <@@@> ";
        }
        else
        {
            switch ( *str )
            {
                default:
                    bug( "Act: bad code %c.", *str );
                    i = " <@@@> ";
                    break;

                case 't':
                    if ( !arg1 )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( char* ) arg1;
                    break;

                case 'T':
                    if ( !arg2 )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( char* ) arg2;
                    break;

                case 'n':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    /* GRAL progs have to use name for explicit actions but talk about gname */
                    i = ( to ? PERS( ch, to ) : NAME( ch ) );
                    break;

                case 'N':
                    if ( !vch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( to ? PERS( vch, to ) : NAME( vch ) );
                    break;

                case 'e':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "they";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "it";
                    else
                        i = he_she [URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'E':
                    if ( !vch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "they";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "it";
                    else
                        i = he_she [URANGE( 0, vch->sex, 2 )];

                    break;

                case 'm':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "them";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "it";
                    else
                        i = him_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'M':
                    if ( !vch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "them";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "it";
                    else
                        i = him_her[URANGE( 0, vch->sex, 2 )];

                    break;

                case 's':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( ch->sex > 2 || ch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", ch->name,
                             ch->sex );
                        i = "their";
                    }
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'S':
                    if ( !vch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( vch->sex > 2 || vch->sex < 0 )
                    {
                        bug( "act_string: player %s has sex set at %d!", vch->name,
                             vch->sex );
                        i = "their";
                    }
                    else if ( is_droid( get_visible_race( vch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0, vch->sex, 2 )];

                    break;

                case 'q':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( to == ch ) ? "" : "s";
                    break;

                case 'Q':
                    if ( !ch )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    if ( to == ch )
                        i = "your";
                    else if ( is_droid( get_visible_race( ch ) ) )
                        i = "its";
                    else
                        i = his_her[URANGE( 0,  ch->sex, 2 )];

                    break;

                case 'p':
                    if ( !obj1 )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( !to || can_see_obj( to, obj1 )
                          ? stripclr( obj_short( obj1 ) ) : "something" );
                    break;

                case 'P':
                    if ( !obj2 )
                    {
                        bug( "Act: missing value for code %c.", *str );
                        i = " <@@@> ";
                        break;
                    }

                    i = ( !to || can_see_obj( to, obj2 )
                          ? stripclr( obj_short( obj2 ) ) : "something" );
                    break;

                case 'd':
                    if ( !arg2 || ( ( char* ) arg2 )[0] == '\0' )
                        i = "door";
                    else
                    {
                        one_argument( ( char* ) arg2, fname );
                        i = fname;
                    }

                    break;
            }
        }

        ++str;

        while ( ( *point = *i ) != '\0' )
            ++point, ++i;
    }

    strlcpy( point, "", MSL );
    buf[0] = UPPER( buf[0] );
    return buf;
}
