void ai_react( CHAR_DATA* ch, CHAR_DATA* victim, char* type, char* message )
{
    char buf[MSL];

    if ( !ch || !victim || ch == victim || !*type )
        return;

    if ( !str_cmp( "say", type ) )
    {
        if ( understand( ch, message ) )
            ai_reply( ch, victim, message );
    }

    if ( !str_cmp( "clan", type ) )
    {
        if ( !str_cmp( "report", message ) )
        {
            DESCRIPTOR_DATA* d = NULL;

            if ( ch->ai_data->ai_level != AI_SOLDIER_LIGHT )
                return;

            if ( !on_planet( ch ) )
                return;

            if ( char_clan_level( victim ) > 4 )
                return;

            for ( d = first_descriptor; d; d = d->next )
            {
                if ( d->connected != CON_PLAYING )
                    continue;

                if ( !d->character )
                    continue;

                if ( !d->character->pcdata->clan )
                    continue;

                if ( d->character->pcdata->clan != ch->ai_data->clan )
                    continue;

                snprintf( buf, MSL, "&z&Y&W&z[&GReport&w: from &z(&W%s&z)&G%s&z] &C<&w%d&C>&w %s\n", ch->in_room->name, ch->in_room->area->planet->name, ch->ai_data->clan_rank, ch->short_descr );

                if ( get_comlink( ch ) )
                    send_to_char( buf, d->character );
            }
        }
    }
}
void ai_reply( CHAR_DATA* ch, CHAR_DATA* victim, char* message )
{
    char buf[MSL];
    char* greet;

    if ( is_greeting( message ) )
    {
        greet = ai_greet( ch, victim, message );

        if ( greet )
            snprintf( buf, MSL, "%s", greet );
        else
            return;
    }
    else if ( is_known_name( ch, message ) )
    {
        greet = ai_recognize( ch, victim, message );

        if ( greet )
            snprintf( buf, MSL, "%s", greet );
        else
            return;
    }

    interpret( ch, buf, FALSE );
}

char* ai_greet_friend( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL], *rtn = NULL;

    switch ( number_range( 1, 5 ) )
    {
        case 1:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "grin '%s'", victim->name );
                do_say( ch, "Hello there." );
            }

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
            {
                snprintf( buf, MSL, "nod '%s'", victim->name );
            }

            break;

        case 2:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "smile '%s'", victim->name );
            }

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
            {
                if ( !IS_NPC( victim ) && ch->ai_data->clan && victim->pcdata->clan == ch->ai_data->clan )
                {
                    if ( victim->pcdata->clan_rank > ch->ai_data->clan_rank )
                    {
                        snprintf( buf, MSL, "salute '%s'", victim->name );
                    }

                    snprintf( buf, MSL, "nod '%s'", victim->name );
                }
            }

            break;

        case 3:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' Good day my friend.", victim->name );
            }

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
            {
                if ( !IS_NPC( victim ) && ch->ai_data->clan && victim->pcdata->clan == ch->ai_data->clan )
                {
                    if ( victim->pcdata->clan_rank > ch->ai_data->clan_rank )
                    {
                        snprintf( buf, MSL, "salute '%s'", victim->name );
                    }

                    snprintf( buf, MSL, "sayto '%s' Hello there", victim->name );
                }
            }

            break;

        case 4:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' Nice to see you.", victim->name );
            }

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
            {
                if ( !IS_NPC( victim ) && ch->ai_data->clan && victim->pcdata->clan == ch->ai_data->clan )
                {
                    if ( victim->pcdata->clan_rank > ch->ai_data->clan_rank )
                    {
                        snprintf( buf, MSL, "salute '%s'", victim->name );
                    }

                    snprintf( buf, MSL, "emote looks around, making sure nothing is amiss." );
                }
            }

            break;

        case 5:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' How are you?", victim->name );
            }

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
            {
                if ( !IS_NPC( victim ) && ch->ai_data->clan && victim->pcdata->clan == ch->ai_data->clan )
                {
                    if ( victim->pcdata->clan_rank > ch->ai_data->clan_rank )
                    {
                        snprintf( buf, MSL, "salute '%s'", victim->name );
                    }

                    snprintf( buf, MSL, "look '%s'", victim->name );
                }
            }

            break;
    }

    if ( NULLSTR( buf ) )
        return "";

    rtn = buf;
    return rtn;
}

char* ai_attack_enemy( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL], *rtn = NULL;

    switch ( number_range( 1, 5 ) )
    {
        case 1:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "yell Help, I'm being attacked!" );
                multi_hit( ch, victim, TYPE_UNDEFINED );
                do_flee( ch, "" );
            }

            break;

        case 2:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "glare '%s'", victim->name );
                do_say( ch, "Get away!" );
            }

            break;

        case 3:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' Leave me alone!", victim->name );
            }

            break;

        case 4:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' I know who you are! Go away %s!", victim->name, victim->name );
            }

            break;

        case 5:
            if ( is_ai( ch, AI_CITIZEN ) )
            {
                snprintf( buf, MSL, "sayto '%s' I'm calling the police on you!", victim->name );
            }

            break;
    }

    if ( NULLSTR( buf ) )
        return "";

    rtn = buf;
    return rtn;
}

char* ai_greet( CHAR_DATA* ch, CHAR_DATA* victim, char*   message )
{
    char buf[MSL], *rtn = NULL;

    if ( !*message )
        return "";

    if ( is_enemy( victim, ch ) )
        return ai_attack_enemy( ch, victim );

    if ( is_friend( victim, ch ) )
        return ai_greet_friend( ch, victim );

    if ( is_ai( ch, AI_CITIZEN ) )
    {
        if ( !IS_NPC( victim ) )
        {
            snprintf( buf, MSL, "say Hello there. I don't think we've met before." );
            add_friend( ch, victim );
        }
        else if ( is_happy( ch ) )
            snprintf( buf, MSL, "say Hello there." );
        else if ( is_angry( ch ) )
        {
            switch ( number_range( 1, 4 ) )
            {
                case 1:
                    snprintf( buf, MSL, "frown" );
                    break;

                case 2:
                    snprintf( buf, MSL, "sayto '%s' I'm in no mood for talking right now, sorry.", victim->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "sayto '%s' Pardon me but I can't talk now.", victim->name );
                    break;

                case 4:
                    snprintf( buf, MSL, "shrug" );
                    break;
            }
        }

        rtn = buf;
        return rtn;
    }

    if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
    {
        if ( !IS_NPC( victim ) )
        {
            snprintf( buf, MSL, "sayto '%s' Nice to meet you.", victim->name );
            add_friend( ch, victim );
        }
        else if ( is_happy( ch ) )
            snprintf( buf, MSL, "say Hello there." );
        else if ( is_angry( ch ) )
        {
            switch ( number_range( 1, 4 ) )
            {
                case 1:
                    snprintf( buf, MSL, "frown" );
                    break;

                case 2:
                    snprintf( buf, MSL, "sayto '%s' I'm in no mood for talking right now, sorry.", victim->name );
                    break;

                case 3:
                    snprintf( buf, MSL, "sayto '%s' Pardon me but I can't talk now.", victim->name );
                    break;

                case 4:
                    snprintf( buf, MSL, "shrug" );
                    break;
            }
        }

        rtn = buf;
        return rtn;
    }

    return NULL;
}
void add_friend( CHAR_DATA* ch, CHAR_DATA* victim )
{
    FRIEND_DATA* fr = NULL;

    if ( !ch->ai_data )
        return;

    CREATE( fr, FRIEND_DATA, 1 );
    SET_STRING( fr->name, victim->name );
    fr->id = victim->id;
    LINK( fr, ch->ai_data->first_friend, ch->ai_data->last_friend, next, prev );
    save_persistent_mob( ch, true );
}
void add_enemy( CHAR_DATA* ch, CHAR_DATA* victim )
{
    ENEMY_DATA* enemy = NULL;

    if ( IS_NPC( victim ) )
        return;

    if ( !ch->ai_data )
        return;

    CREATE( enemy, ENEMY_DATA, 1 );
    SET_STRING( enemy->name, victim->name );
    enemy->id = victim->id;
    LINK( enemy, ch->ai_data->first_enemy, ch->ai_data->last_enemy, next, prev );
    save_persistent_mob( ch, true );
}
bool is_ai( CHAR_DATA* ch, int ai_code )
{
    if ( !ch )
        return FALSE;

    if ( !ch->ai_data )
        return FALSE;

    if ( ch->ai_data->ai_level == ai_code )
        return TRUE;

    return FALSE;
}
bool understand( CHAR_DATA* ch, char* message )
{
    if ( is_greeting( message ) )
        return TRUE;

    if ( is_known_name( ch, message ) )
        return TRUE;

    if ( is_clan_name( ch, message ) )
        return TRUE;

    if ( is_order_phrase( ch, message ) )
        return TRUE;

    return FALSE;
}
bool is_order_phrase( CHAR_DATA* ch, char* message )
{
    if ( !str_prefix( message, "report" )
            && is_ai( ch, AI_SOLDIER_LIGHT )
       )
        return TRUE;

    return FALSE;
}
bool is_clan_name( CHAR_DATA* ch, char* message )
{
    AI_DATA* curr_ai = NULL;

    for ( curr_ai = first_ai; curr_ai; curr_ai = curr_ai->next )
        if ( curr_ai->character == ch )
            break;

    if ( !curr_ai || !curr_ai->clan )
        return FALSE;

    if ( nifty_is_name_prefix( message, curr_ai->clan->name ) )
        return TRUE;

    return FALSE;
}


bool is_known_name( CHAR_DATA* ch, char* message )
{
    FRIEND_DATA* fr = NULL;
    ENEMY_DATA* enemy = NULL;
    AI_DATA* curr_ai = NULL;

    if ( !first_ai )
        return FALSE;

    for ( curr_ai = first_ai; curr_ai; curr_ai = curr_ai->next )
        if ( curr_ai->character == ch )
            break;

    if ( !curr_ai )
        return FALSE;

    for ( fr = curr_ai->first_friend; fr; fr = fr->next )
    {
        if ( !str_prefix( message, fr->name ) )
            break;

        if ( strstr( message, fr->name ) )
            break;
    }

    for ( enemy = curr_ai->first_enemy; enemy; enemy = enemy->next )
    {
        if ( !str_prefix( message, enemy->name ) )
            break;

        if ( strstr( message, enemy->name ) )
            break;
    }

    if ( fr || enemy )
        return TRUE;
    else
        return FALSE;
}

bool is_greeting( char* message )
{
    message = strlower( message );

    if ( !str_prefix( message, "hello" )
            || !str_prefix( message, "hi" )
            || !str_prefix( message, "greetings" )
            || !str_prefix( message, "good morning" )
            || !str_prefix( message, "hey there" )
            || !str_prefix( message, "heya" )
       )
        return TRUE;

    return FALSE;
}
bool is_friend( CHAR_DATA* ch, CHAR_DATA* looker )
{
    FRIEND_DATA* fr = NULL;

    if ( !ch || !looker )
        return FALSE;

    if ( !looker->ai_data )
        return FALSE;

    if ( IS_NPC( ch ) )
        return FALSE;

    for ( fr = looker->ai_data->first_friend; fr; fr = fr->next )
        if ( !str_cmp( fr->name, ch->name ) )
            break;

    if ( !fr )
        return FALSE;

    return TRUE;
}
bool is_enemy( CHAR_DATA* ch, CHAR_DATA* looker )
{
    ENEMY_DATA* enemy = NULL;

    if ( !ch || !looker )
        return FALSE;

    if ( !looker->ai_data )
        return FALSE;

    if ( IS_NPC( ch ) )
        return FALSE;

    for ( enemy = looker->ai_data->first_enemy; enemy; enemy = enemy->next )
        if ( !str_cmp( enemy->name, ch->name ) )
            break;

    if ( !enemy )
        return FALSE;

    return TRUE;
}
bool is_happy( CHAR_DATA* ch )
{
    if ( !ch->ai_data )
        return FALSE;

    if ( ch->ai_data->happy < 60 || ch->ai_data->anger > 40 || ch->ai_data->fear > 30 )
        return FALSE;

    return TRUE;
}
bool is_angry( CHAR_DATA* ch )
{
    if ( !ch->ai_data )
        return FALSE;

    if ( ch->ai_data->anger < 40 )
        return FALSE;

    return TRUE;
}
char* ai_recognize( CHAR_DATA* ch, CHAR_DATA* victim, char* message )
{
    if ( !ch || !victim || !*message )
        return "";

    return "";
}
bool is_naked( CHAR_DATA* ch )
{
    if ( get_eq_char( ch, WEAR_BODY ) == NULL &&
            get_eq_char( ch, WEAR_HEAD ) == NULL &&
            get_eq_char( ch, WEAR_ARMS ) == NULL &&
            get_eq_char( ch, WEAR_LEGS ) == NULL &&
            get_eq_char( ch, WEAR_WAIST ) == NULL &&
            get_eq_char( ch, WEAR_BACK ) == NULL &&
            get_eq_char( ch, WEAR_FEET ) == NULL &&
            get_eq_char( ch, WEAR_HANDS ) == NULL &&
            get_eq_char( ch, WEAR_ABOUT ) == NULL &&
            get_eq_char( ch, WEAR_OVER ) == NULL &&
            ch && ch->race &&
            !xIS_SET( ch->race->flags, RFLAG_DROID ) /* Ralen - Nudist Droid Prevention. */
       )
        return TRUE;
    else
        return FALSE;
}

void print_death( CHAR_DATA* ch, DEATH_DATA* death )
{
    time_t tm;
    tm = ( time_t )death->time;
    ch_println( ch, "&z(#%d) Dead person:&W %-25s (@%s) [%s]%s &zKilled by:&W %s (@%s) [%s]&w", death->id, death->victim, death->victaccount, death->victclan, death->has_clone == TRUE ? "*" : "", death->killer, death->killeraccount, death->killerclan );
    ch_printf( ch, "  &zTime of death:&W %s", ctime(&tm) );
    if ( IS_IMMORTAL( ch ) )
    {
        if ( death->expiration > 0 )
        {
            time_t ownership_revert_time = (time_t)death->expiration;
            ch_printf( ch, "  &zOwnership reverts at:&W %s", ctime( &( ownership_revert_time ) ) );
        }

        ROOM_INDEX_DATA* deathroom = get_room_index( death->room );
        ch_println( ch, "  &zIn room:&W %d (%s&W)", death->room, deathroom ? deathroom->name : "(Unknown room)");

        if ( death->points != 1 )
            ch_println( ch, "  &zPoints (inc deposit):&W %d", death->points );
    }
    ch_println( ch, "" );
}

CMDF do_deaths( CHAR_DATA* ch, char* argument )
{
    DEATH_DATA* death = NULL, *death2 = NULL;
    int cnt = 0;
    if (!IS_IMMORTAL(ch))
        return;

    if ( NULLSTR( argument ) )
    {
        if ( get_trust( ch ) >= sysdata.log_level )
        {
            for ( death = last_death; death; death = death->prev )
            {
                cnt++;

                if ( death->prev != NULL && cnt < 15 )
                    continue;

                for ( death2 = death; death2; death2 = death2->next )
                    print_death( ch, death2 );

                break;
            }

            ch_println( ch, "&zDisplayed last &R%d&z recorded deaths.&w", cnt );
        }
        else
            ch_println( ch, "&zSyntax: &Cdeaths <&wkeyword for killer&z/&wkilled&C char name or @account>&w" );

        return;
    }
    else if ( argument[0] == '@' )
    {
        ACCOUNT_DATA* acc = get_account( argument + 1 );

        if ( !acc )
        {
            ch_println( ch, "Account not found." );
            return;
        }

        for ( death = first_death; death; death = death->next )
            if ( account_from_char( death->victaccount ) == acc || account_from_char( death->killeraccount ) == acc )
                print_death( ch, death );

        return;
    }

    for ( death = first_death; death; death = death->next )
    {
        if ( ( strstr( death->killer, argument ) || strstr( death->victim, argument )) )
        {
            print_death( ch, death );
            cnt++;
        }
    }

    if ( cnt == 0 )
        ch_println( ch, "Sorry, no matches found." );
    else
        ch_println( ch, "Found a total of %d matches.", cnt );
}

void show_structs_to_char( ROOM_INDEX_DATA* room, CHAR_DATA* ch )
{
    if ( !room || !ch )
        return;

    // List structures in this room
    for ( STRUCTURE_DATA* stru = first_structure; stru; stru = stru->next )
    {
        if ( stru->in_room != room->vnum )
            continue;

        ch_println( ch, "&O[Structure] &w%s%s", stru->name,
            xIS_SET( stru->flags, STRUCTFLAG_BROKEN ) ? " &r(derelict)" :
            xIS_SET( stru->flags, STRUCTFLAG_UNFINISHED ) ? " &O(under construction)" :
            xIS_SET( stru->exit_flags, EX_CLOSED ) ? " &w(closed)" : ""
        );
    }

    // Show details about the way out if we're showing them the struct entry room
    STRUCTURE_DATA* in_struct = structure_from_room( ch->in_room->vnum );
    if ( in_struct && in_struct->entrance == ch->in_room->vnum )
    {
        if ( xIS_SET( in_struct->exit_flags, EX_ISDOOR ) )
            ch_println( ch, "The exit door is %s.", xIS_SET( in_struct->exit_flags, EX_CLOSED ) ? "closed" : "open" );
        if ( !xIS_SET( in_struct->exit_flags, EX_CLOSED ) )
            ch_println( ch, "&z&Y&WYou may type LEAVE to exit the building." );
    }
}

void show_lifts_to_char( CHAR_DATA* ch )
{
