void show_blockaders_to_char( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* room = ch->in_room;

    if ( !xIS_SET( room->flags, ROOM_CAN_LAND )
            && !xIS_SET( room->flags, ROOM_CLANPAD )
            && !xIS_SET( room->flags, ROOM_HIDDEN_LAND ) )
        return;

    PLANET_DATA* planet = room->area->planet;

    if ( !planet )
        return;

    if ( !xIS_SET( planet->flags, PLANET_BLOCKADE ) )
        return;


    for ( SHIP_DATA* ship = planet->starsystem->first_ship; ship; ship = ship->next_in_starsystem )
        if ( is_blockading( ship, planet ) )
            ch_println( ch, "&zYou see %s overhead blockading the planet.", ship->name );
}

