/* Refactored 08/17/2023. - Nield */
CMDF do_changes( CHAR_DATA* ch, char* argument )
{
    DB_DATA* db = NULL;
    CHAR_DATA* rch = NULL;
    BUFFER_DATA* buffer = NULL;
    int cnt = 0;
    int curr_time = ( int )( time( 0 ) );
    char arg[MIL];

    switch ( ch->substate )
    {
        default:
            bug( "do_changes: illegal substate" );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            break;

        case SUB_EDIT_CHANGE:
            buffer = get_buffer( ch, FUNC );

            if ( buffer )
            {
                db = ( DB_DATA* )buffer->buf1;
                dispose_buffer( buffer );
            }

            if ( !db )
            {
                stop_editing( ch, false );
                return;
            }

            int orig_len = strlen( db->str1 );
            SET_STRING( db->str1, copy_buffer( ch ) );
            save_dbase_sql( DB_TABLE_CHANGES, db );
            stop_editing( ch, false );

            if ( orig_len == 0 )
                for ( rch = first_char; rch; rch = rch->next )
                    if ( !IS_NPC( rch ) )
                        ch_println( rch, "&D&z[&WCHANGES&z] &wA change &z(&W#&w%d&z) &whas been added: &G%s\n"
                               "&wType &W'&zchanges %d&W' &wto view.&D\n", db->id, db->name, db->id );

            return;
    }

    if ( NULLSTR( argument ) )
    {
        pager_printf( ch, "No option specified, defaulting to 'recent'.\n" );
        argument = "recent";
    }

    if ( !str_cmp( "recent", argument ) || is_name( "search", argument ) || is_name( "by", argument ) )
    {
        cnt = 0;
        int i = 0;
        bool has_found = false;
        DB_DATA* db2 = NULL;
        char buf[MSL];
        argument = one_argument( argument, arg );
        strlcpy( buf, strlower_safe( argument ), MSL );

        for ( db = !str_cmp( "recent", arg ) ? last_change : first_change; db; db = !str_cmp( "recent", arg ) ? db->prev : db->next )
        {
            i++;

            if ( !str_cmp( "recent", arg ) && ( ( curr_time - db->num1 < (60 * 60 * 24 * 10) ) || i < 10 ) && db->prev != NULL )
                continue;

            for (i = 0; i <= 3; i++)
            {
                has_found = false;
                db2 = NULL;
                for ( db2 = db; db2; db2 = db2->next )
                {
                    if ( !str_cmp( "search", arg ) )
                        if ( !strstr( strlower_safe( db2->str1 ), buf ) && !strstr( strlower_safe( db2->name ), buf ) )                       
                            continue;

                    if ( !str_cmp( "by", arg ) && str_cmp( argument, db2->str2 ) )
                        continue;

                    if ( db2->num2 == i )
                    {
                        if ( !has_found )
                        {
                            pager_printf( ch, "\n&W%s\n", db2->num2 == 0 ? "Code Changes" : db2->num2 == 1 ? "Area Updates" : db2->num2 == 2 ? "Rules/Policy Changes" : "Announcements" );
                            has_found = true;
                        }

                        display_change( ch, db2, true );
                        cnt++;
                    }
                }
            }

            break;
        }
        if ( cnt == 0 )
            pager_printf( ch, "Sorry, could not find any changes that match that criteria.\n" );
        else
        {
            pager_printf( ch, "\n&wFound a total of %d match%s.\n", cnt, cnt == 1 ? "" : "es" );
            pager_printf( ch, "&wTo see more information about each change, type '&Cchanges <&wid/name&C>&w'\n\n" );
        }
        pager_printf( ch, "&zValid options: &CRecent&w, &CCode&w, &CArea&w, &CRules/Policy&w, &CAnnouncement&w, &CAll&w, &CSearch&w, &CBy&w\n" );
        if ( IS_IMMORTAL( ch ) )
            pager_printf( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Ctype&z, &Cauthor&z, &Cpublish&z\n" );

        return;
    }
    else if ( !str_cmp( "code", argument ) || !str_prefix( "area", argument ) || !str_prefix( "rules", argument ) || !str_suffix( "policy", argument ) || !str_prefix( "announcement", argument ) )
    {
        cnt = 0;
        bool has_found = false;
        for ( db = first_change; db; db = db->next )
        {
            if ( !str_cmp( "code", argument ) && db->num2 != 0 )
                continue;

            if ( !str_prefix( "area", argument ) && db->num2 != 1 )
                continue;

            if ( ( !str_prefix( "rules", argument ) || !str_suffix( "policy", argument ) ) && db->num2 != 2 )
                continue;

            if ( !str_prefix( "announcement", argument ) && db->num2 != 3 )
                continue;

            if ( !has_found )
            {
                pager_printf( ch, "\n&W%s\n", db->num2 == 0 ? "Code Changes" : db->num2 == 1 ? "Area Updates" : db->num2 == 2 ? "Rules/Policy Changes" : "Announcements" );
                has_found = true;
            }

            display_change( ch, db, true );
            cnt++;
        }

        if ( cnt == 0 )
            pager_printf( ch, "Sorry, could not find any changes that match that criteria.\n" );
        else
        {
            pager_printf( ch, "\n&wFound a total of %d match%s.\n", cnt, cnt == 1 ? "" : "es" );
            pager_printf( ch, "&wTo see more information about each bulletin, type '&Cchanges <&wid/name&C>&w'\n\n" );
        }

        pager_printf( ch, "&zValid options: &CRecent&w, &CCode&w, &CArea&w, &CRules/Policy&w, &CAnnouncement&w, &CAll&w, &CSearch&w, &CBy&w\n" );
        if ( IS_IMMORTAL( ch ) )
            pager_printf( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Ctype&z, &Cauthor&z, &Cpublish&z\n" );

        return;
    }
    else if ( !str_cmp( argument, "all" ) )
    {            
        for ( db = last_change; db; db = db->prev )
        {         
            display_change( ch, db, true );
            cnt++;
        }

        if ( cnt == 0 )
            pager_printf( ch, "Sorry, could not find any changes that match that criteria.\n" );
        else
        {
            pager_printf( ch, "\n&wFound a total of %d match%s.\n", cnt, cnt == 1 ? "" : "es" );
            pager_printf( ch, "&wTo see more information about each bulletin, type '&Cchanges <&wid/name&C>&w'\n\n" );
        }

        pager_printf( ch, "&zValid options: &CRecent&w, &CCode&w, &CArea&w, &CRules/Policy&w, &CAnnouncement&w, &CAll&w, &CSearch&w, &CBy&w\n" );
        if ( IS_IMMORTAL( ch ) )
            pager_printf( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Ctype&z, &Cauthor&z, &Cpublish&z\n" );

        return;
    }
    else
    {
        for ( db = last_change; db; db = db->prev )
        {
            if ( atoi( argument ) == db->id || !str_cmp( db->name, argument ) )
            {
                display_change( ch, db, false );
                return;
            }
        }
        if ( !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "Unable to find that change. Please specify the ID # or the name." );
            return;
        }
    }

    argument = one_argument( argument, arg );

    if ( !str_cmp( arg, "create" ) )
    {
        if(IS_NPC(ch) || !ch->desc ) {
            ch_println( ch, "No can do." );
            return;
        }

        if ( is_busy( ch ) )
        {
            ch_println( ch, "You are too busy to do that right now." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cchanges create [change name]" );
            return;
        }

        if ( strlen( stripclr( argument ) ) > 74 )
        {
            ch_println( ch, "That name is too long. Please try a shorter one." );
            return;
        }

        for ( db = last_change; db; db = db->prev )
        {
            if ( !str_cmp( db->name, argument ) )
            {
                ch_println( ch, "A change with that name already exists." );
                return;
            }
        }

        CREATE( db, DB_DATA, 1 );
        SET_STRING( db->name, argument );
        SET_STRING( db->str1, "" );
        SET_STRING( db->str2, ch->name );
        db->num1 = ( int )( time( 0 ) );
        db->num2 = 3; // Default to announcement change per walldo, 10Oct18
        LINK( db, first_change, last_change, next, prev );
        db->id = 0; //should be updated by save_dbase_sql
        save_dbase_sql( DB_TABLE_CHANGES, db );
        ch_println( ch, "New change added:" );
        display_change( ch, db, false );
        ch->substate = SUB_EDIT_CHANGE;
        buffer = create_buffer( ch, FUNC );
        buffer->buf1 = db;
        ch_println( ch, "Please enter the details of this change.\nThis can be edited later with the EDIT option." );
        start_editing( ch, FUNC, db->str1 );
        return;
    }
    else if ( !str_cmp( arg, "edit" ) || !str_cmp( arg, "delete" ) )
    {
        if(IS_NPC(ch) || !ch->desc ) {
            ch_println( ch, "No can do." );
            return;
        }

        if ( is_busy( ch ) )
        {
            ch_println( ch, "You are too busy to do that right now." );
            return;
        }

        for ( db = last_change; db; db = db->prev )
            if ( !str_cmp( db->name, argument ) || atoi( argument ) == db->id )
            {
                if ( !str_cmp( arg, "edit" ) )
                {
                    ch->substate = SUB_EDIT_CHANGE;
                    buffer = create_buffer( ch, FUNC );
                    buffer->buf1 = db;
                    start_editing( ch, FUNC, db->str1 );
                }
                else
                {
                    delete_dbase_sql( DB_TABLE_CHANGES, db );
                    UNLINK( db, first_change, last_change, next, prev );
                    extract_db( db );
                    ch_println( ch, "Deleted." );
                }

                return;
            }

        ch_println( ch, "Could not find that change by ID or name." );
        return;
    }
    else if ( !str_cmp( arg, "rename" ) )
    {
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        for ( db = last_change; db; db = db->prev )
            if ( !str_cmp( db->name, arg2 ) || atoi( arg2 ) == db->id )
                break;

        if ( !db )
        {
            ch_println( ch, "Unable to find that change by ID or name." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cchanges rename <&wchange ID #&C> [new name]" );
            return;
        }

        if ( strlen( stripclr( argument ) ) > 80 )
        {
            ch_println( ch, "That name is too long. Please try a shorter one." );
            return;
        }

        for ( DB_DATA* tdb = last_change; tdb; tdb = tdb->prev )
            if ( !str_cmp( tdb->name, argument ) )
            {
                ch_println( ch, "A change with that name already exists." );
                return;
            }

        SET_STRING( db->name, argument );
        ch_println( ch, "Renamed #%d to %s.", db->id, db->name );
        save_dbase_sql( DB_TABLE_CHANGES, db );
        return;
    }
    else if ( !str_cmp( arg, "author" ) )
    {
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        for ( db = last_change; db; db = db->prev )
            if ( !str_cmp( db->name, arg2 ) || atoi( arg2 ) == db->id )
                break;

        if ( !db )
        {
            ch_println( ch, "Unable to find that change by ID or name." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cchanges author <&wchange ID #&C> [author name]" );
            return;
        }

        SET_STRING( db->str2, argument );
        ch_println( ch, "Changed author of #%d to %s.", db->id, argument );
        save_dbase_sql( DB_TABLE_CHANGES, db );
        return;
    }
    else if ( !str_cmp( arg, "type" ) )
    {
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        for ( db = last_change; db; db = db->prev )
            if ( !str_cmp( db->name, arg2 ) || atoi( arg2 ) == db->id )
                break;

        if ( !db )
        {
            ch_println( ch, "Unable to find that change by ID or name." );
            return;
        }

        if ( !str_cmp( argument, "code" ) )
            db->num2 = 0;
        else if ( !str_cmp( argument, "area" ) )
            db->num2 = 1;
        else if ( !str_cmp( argument, "rules" ) || !str_cmp( argument, "policy" ) || !str_cmp( argument, "rules/policy" ) )
            db->num2 = 2;
        else if ( !str_cmp( argument, "announcement" ) )
            db->num2 = 3;
        else
        {
            ch_println( ch, "Valid options: code, area, rules/policy, announcement" );
            return;
        }

        ch_println( ch, "Changed category to %s.", argument );
        save_dbase_sql( DB_TABLE_CHANGES, db );
    }
    else
    {
        ch_println( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Ctype&z, &Cauthor&z, &Cpublish&z" );
        return;
    }
}

char* truncate_string( const char* str, size_t len )
{
    return fit_string( str, len, false );
}

// Fits the given string in no more than <len> characters.
// If it doesn't fit, a ... is added to the end.
// Accounts for color codes.
// If pad is true, it adds trailing whitespace to ensure the string, once rendered
// with color codes, is exactly <len> characters wide.
char* fit_string( const char* str, size_t len, bool pad )
{
    size_t str_len = 0, buflen = 0;
    static char* buffers[MAX_POOL]; //an array of pointers
    static int count = -1;

    if ( !str )
        return NULL;

    if ( dump_mem_on_shutdown && str == memdebug_signal )
    {
        cleanup_static_pool( buffers );
        return NULL;
    }

    str_len = strlen( str );

    if ( str_len == 0 )
        return (char*)str;

    count++;
    count %= MAX_POOL;
    char** buf = &( buffers[count] );

    if ( *buf )
    {
        free( *buf );
        (*buf) = NULL;
    }

    str_len -= strlen( stripclr( str ) );

    // Maybe a little bigger than we need, but never smaller.
    buflen = sizeof( char ) * ( ( UMAX( len, 0 ) + UMAX( str_len, 0 ) + 1 ) );
    buflen = UMAX( buflen, 4 ); // Always allow at least 4 bytes for ellipses and a null terminator.
    (*buf) = ( char* )malloc( buflen );
    memset( *buf, '\0', buflen );

    if ( len <= 0 )
        return (*buf);

    size_t orig_len = 0;
    if ( !NULLSTR( str ) )
        orig_len = strlen( stripclr( str ) );

    if ( orig_len <= len )
        snprintf( (*buf), buflen, "%s", str ? str : "" );
    else
    {
        int src_idx = 0, dst_idx = 0;
        size_t cnt = 0;
        char val;
        while ( cnt < len - 3 )
        {
            val = str[src_idx];
            if ( val == '^' && (
                str[src_idx + 1] == 'x' || str[src_idx + 1] == 'r' || str[src_idx + 1] == 'g' ||
                str[src_idx + 1] == 'O' || str[src_idx + 1] == 'b' || str[src_idx + 1] == 'p' ||
                str[src_idx + 1] == 'c' || str[src_idx + 1] == 'w' )
            )
            {
                (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++];
            }
            else if ( str[src_idx] == '}' && (
                str[src_idx + 1] == 'x' || str[src_idx + 1] == 'O' || str[src_idx + 1] == 'c' ||
                str[src_idx + 1] == 'z' || str[src_idx + 1] == 'g' || str[src_idx + 1] == 'G' ||
                str[src_idx + 1] == 'P' || str[src_idx + 1] == 'r' || str[src_idx + 1] == 'b' ||
                str[src_idx + 1] == 'w' || str[src_idx + 1] == 'Y' || str[src_idx + 1] == 'C' ||
                str[src_idx + 1] == 'p' || str[src_idx + 1] == 'R' || str[src_idx + 1] == 'B' ||
                str[src_idx + 1] == 'W' )
            )
            {
                (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++];
            }
            else if ( str[src_idx] == '&' && (
                str[src_idx + 1] == 'x' || str[src_idx + 1] == 'O' || str[src_idx + 1] == 'c' ||
                str[src_idx + 1] == 'z' || str[src_idx + 1] == 'g' || str[src_idx + 1] == 'G' ||
                str[src_idx + 1] == 'P' || str[src_idx + 1] == 'r' || str[src_idx + 1] == 'b' ||
                str[src_idx + 1] == 'w' || str[src_idx + 1] == 'Y' || str[src_idx + 1] == 'C' ||
                str[src_idx + 1] == 'p' || str[src_idx + 1] == 'R' || str[src_idx + 1] == 'B' ||
                str[src_idx + 1] == 'W' || str[src_idx + 1] == '?' )
            )
            {
                (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++];
            }
            else if ( str[src_idx] == '&' && isdigit(str[src_idx+1]) && isdigit(str[src_idx+2]) && isdigit(str[src_idx+3]) )
            {
                (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++]; (*buf)[dst_idx++] = str[src_idx++];
            }
            else
            {
                (*buf)[dst_idx++] = str[src_idx++];
                cnt++;
            }
        }
        (*buf)[dst_idx++] = '.'; (*buf)[dst_idx++] = '.'; (*buf)[dst_idx++] = '.'; (*buf)[dst_idx++] = '\0';
    }

    if ( pad )
    {
        int remainder = len - strlen( stripclr( (*buf) ) );
        for ( int i = 0; i < remainder; i++ )
            strlcat( (*buf), " ", MSL );
    }

    return (*buf);
}

void display_change( CHAR_DATA* ch, DB_DATA* db, bool brief )
{
    if ( !ch || !db )
        return;

    bool is_gni = !str_cmp( ch->name, "GNI" );

    time_t last_edited = ( time_t ) ( db->num1 );

    if ( !brief )
    {
        ch_println( ch, "&z(&w%4d&z) &G%s", db->id, db->name );
        if ( !is_gni )
            ch_println( ch, "&c--------------------------------------------------------------------------------" );
        ch_println( ch, "&w%s", db->str1 );
        if ( !is_gni )
            ch_println( ch, "&c--------------------------------------------------------------------------------" );
        ch_println( ch, "&zMade by &C%s &zon &C%s&z.", db->str2, c_time( last_edited, get_timezone( ch ) ) );
    }
    else
    {  
        pager_printf( ch, "&z(&w%4d&z) &G%-42s &zon &w%s &zby &w%s\n", db->id, truncate_string( db->name, 42 ), alt_c_time( last_edited, get_timezone( ch ) ), db->str2 );   
    }

    return;

}

int num_news()
{
    DB_DATA* db = NULL;
    int cnt = 0;

    for ( db = last_news; db; db = db->prev )
        if ( ( time( 0 ) - db->num1 ) < ( 60 * 60 * 24 * 14 ) ) // 2 weeks
            cnt++;

    return cnt;
}

int num_changes()
{
    DB_DATA* db = NULL;
    int cnt = 0;

    for ( db = last_change; db; db = db->prev )
        if ( ( time( 0 ) - db->num1 ) < ( 60 * 60 * 24 * 14 ) ) // 2 weeks
            cnt++;

    return cnt;
}
CMDF do_doubleooc( CHAR_DATA* ch, char* argument )
{
    if ( !str_cmp( argument, "on" ) )
    {
        if ( sysdata.doubleOOC )
            ch_println( ch, "OOC cost already doubled." );
        else
        {
            CHAR_DATA* tch;

            for ( tch = first_char; tch; tch = tch->next )
                if ( !IS_NPC( tch ) )
                    if ( !xIS_SET( tch->deaf, CHANNEL_OOC ) )
                        ch_println( tch, "OOC channel usage will now cost double OOC points!" );

            sysdata.doubleOOC = true;
        }
    }
    else if ( !str_cmp( argument, "off" ) )
    {
        if ( !sysdata.doubleOOC )
            ch_println( ch, "OOC cost already at normal." );
        else
        {
            CHAR_DATA* tch;

            for ( tch = first_char; tch; tch = tch->next )
                if ( !IS_NPC( tch ) )
                    if ( !xIS_SET( tch->deaf, CHANNEL_OOC ) )
                        ch_println( tch, "OOC channel usage no longer costs double OOC points." );

            sysdata.doubleOOC = false;
        }
    }
    else
    {
        ch_println( ch, "OOC usage is %s.", sysdata.doubleOOC ? "double price" : "normal" );
        return;
    }

    save_sysdata( &sysdata );
}

