CMDF do_news( CHAR_DATA* ch, char* argument )
{
    DB_DATA* db = NULL;
    CHAR_DATA* rch = NULL;
    int cnt = 0;
    char arg[MIL];
    BUFFER_DATA* buffer = NULL;

    switch ( ch->substate )
    {
        default:
            bug( "do_news: illegal substate" );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            break;

        case SUB_EDIT_NEWS:
            buffer = get_buffer( ch, FUNC );

            if ( buffer )
            {
                db = ( DB_DATA* )buffer->buf1;
                dispose_buffer( buffer );
            }

            if ( !db )
                return;

            int orig_len = strlen( db->str1 );
            SET_STRING( db->str1, copy_buffer( ch ) );
            save_dbase_sql( DB_TABLE_NEWS, db );
            stop_editing( ch, false );

            if ( orig_len == 0 )
                for ( rch = first_char; rch; rch = rch->next )
                    if ( !IS_NPC( rch ) )
                        ch_println( rch, "&D&O[&YNEWS BULLETIN&O] &wA news item &O(&Y#%d&O) &whas been added: &Y%s\n"
                               "&wType &O'&Ynews %d&O' &wto view.&D\n", db->id, db->name, db->id );

            return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "No option specified, defaulting to 'recent'.\n" );
        argument = "recent";
    }

    if ( !str_cmp( "recent", argument ) )
    {
        cnt = 0;
        int i = 0;
        for ( db = last_news; db; db = db->prev )
        {
            i++;

            if ( i < 10 && db->prev != NULL )
                continue;

            for ( db = db; db; db = db->next )
            {
                display_news( ch, db, true );
                cnt++;
            }
            break;
        }
        if ( cnt == 0 )
            ch_println( ch, "Sorry, could not find any news bulletins that match that criteria." );
        else
        {
            ch_println( ch, "&wFound a total of %d match%s.", cnt, cnt == 1 ? "" : "es" );
            ch_println( ch, "&wTo see more information about each bulletin, type '&Cnews <&wid/name&C>&w'\n" );
        }

        ch_println( ch, "&zValid options:&C GNI&w,&C Other&w,&C Recent&w,&C All&w,&C Search&w" );
        if ( IS_IMMORTAL( ch ) )
            ch_println( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Cnetwork&z, &Cpublish&z" );
        return;
    }
    else if ( is_name( "search", argument ) || !str_cmp( argument, "GNI" ) || !str_cmp( argument, "other" ) || !str_cmp( argument, "all" ) )
    {
        cnt = 0;
        argument = one_argument( argument, arg );

        for ( db = first_news; db; db = db->next )
        {
            if ( !str_cmp( "search", arg ) && !nifty_is_name_prefix( argument, db->str1 ) && !nifty_is_name_prefix( argument, db->name ) )
                continue;

            if ( !str_cmp( arg, "GNI" ) && str_cmp( stripclr( db->str2 ), "Galactic News Incorporated" ) )
                continue;

            if ( !str_cmp( arg, "other" ) && !str_cmp( stripclr( db->str2 ), "Galactic News Incorporated" ) )
                continue;

            display_news( ch, db, true );
            cnt++;
        }

        if ( cnt == 0 )
            ch_println( ch, "Sorry, could not find any news bulletins that match that criteria." );
        else
        {
            ch_println( ch, "&wFound a total of %d match%s.", cnt, cnt == 1 ? "" : "es" );
            ch_println( ch, "&wTo see more information about each bulletin, type '&Cnews <&wid/name&C>&w'\n" );
        }

        ch_println( ch, "&zValid options:&C GNI&w,&C Other&w,&C Recent&w,&C All&w,&C Search&w" );
        if ( IS_IMMORTAL( ch ) )
            ch_println( ch, "&zStaff options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Cnetwork&z, &Cpublish&z" );
        return;
    }
    else
    {
        for ( db = last_news; db; db = db->prev )
        {
            if ( atoi( argument ) == db->id || !str_cmp( db->name, argument ) )
            {
                display_news( ch, db, false );
                return;
            }
        }
        if ( !IS_IMMORTAL( ch ) )
        {
            ch_println( ch, "Unable to find that news bulletin. Please specify the ID # or the name." );
            return;
        }
    }

    argument = one_argument( argument, arg );

    if ( !str_cmp( arg, "create" ) )
    {
        if(IS_NPC(ch) || !ch->desc ) {
            ch_println( ch, "No can do." );
            return;
        }

        if ( is_busy( ch ) )
        {
            ch_println( ch, "You are too busy to do that right now." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cnews create [news bulletin name]" );
            return;
        }

        if ( strlen( stripclr( argument ) ) > 78 )
        {
            ch_println( ch, "That name is too long. Please try a shorter one." );
            return;
        }

        for ( db = last_news; db; db = db->prev )
        {
            if ( !str_cmp( db->name, argument ) )
            {
                ch_println( ch, "A news bulletin with that name already exists." );
                return;
            }
        }

        CREATE( db, DB_DATA, 1 );
        SET_STRING( db->name, argument );
        SET_STRING( db->str1, "" );
        SET_STRING( db->str2, "&YG&Oa&zlactic &YN&Oe&zw&ws &YI&On&zc&wo&zr&Op&Yo&Or&za&wt&ze&Od&D" ); // GNI by default
        db->num1 = ( int )( time( 0 ) );
        db->num2 = ch->id;
        LINK( db, first_news, last_news, next, prev );
        db->id = 0;
        save_dbase_sql( DB_TABLE_NEWS, db );
        ch_println( ch, "News bulletin added:" );
        display_news( ch, db, false );
        ch->substate = SUB_EDIT_NEWS;
        buffer = create_buffer( ch, FUNC );
        buffer->buf1 = db;
        ch_println( ch, "Please enter the details of this news bulletin.\nThis can be edited later with the EDIT option." );
        start_editing( ch, FUNC, db->str1 );
        return;
    }
    else if ( !str_cmp( arg, "edit" ) || !str_cmp( arg, "delete" ) )
    {
        if(IS_NPC(ch) || !ch->desc ) {
            ch_println( ch, "No can do." );
            return;
        }

        if ( is_busy( ch ) )
        {
            ch_println( ch, "You are too busy to do that right now." );
            return;
        }

        for ( db = last_news; db; db = db->prev )
            if ( !str_cmp( db->name, argument ) || atoi( argument ) == db->id )
            {
                if ( !str_cmp( arg, "edit" ) )
                {
                    ch->substate = SUB_EDIT_NEWS;
                    buffer = create_buffer( ch, FUNC );
                    buffer->buf1 = db;
                    start_editing( ch, FUNC, db->str1 );
                }
                else
                {
                    delete_dbase_sql( DB_TABLE_NEWS, db );
                    UNLINK( db, first_news, last_news, next, prev );
                    extract_db( db );
                    ch_println( ch, "Deleted." );
                }

                return;
            }

        ch_println( ch, "Could not find that news bulletin by ID or name." );
        return;
    }
    else if ( !str_cmp( arg, "rename" ) )
    {
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        for ( db = last_news; db; db = db->prev )
            if ( !str_cmp( db->name, arg2 ) || atoi( arg2 ) == db->id )
                break;

        if ( !db )
        {
            ch_println( ch, "Unable to find that news bulletin by ID or name." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cnews rename <&wnews ID #&C> [new name]" );
            return;
        }

        if ( strlen( stripclr( argument ) ) > 78 )
        {
            ch_println( ch, "That name is too long. Please try a shorter one." );
            return;
        }

        for ( DB_DATA* tdb = last_news; tdb; tdb = tdb->prev )
            if ( !str_cmp( tdb->name, argument ) )
            {
                ch_println( ch, "A news bulletin with that name already exists." );
                return;
            }

        SET_STRING( db->name, argument );
        ch_println( ch, "Renamed #%d to %s.", db->id, db->name );
        save_dbase_sql( DB_TABLE_NEWS, db );
        return;
    }
    else if ( !str_cmp( arg, "network" ) )
    {
        char arg2[MIL];
        argument = one_argument( argument, arg2 );

        for ( db = last_news; db; db = db->prev )
            if ( !str_cmp( db->name, arg2 ) || atoi( arg2 ) == db->id )
                break;

        if ( !db )
        {
            ch_println( ch, "Unable to find that news bulletin by ID or name." );
            return;
        }

        if ( NULLSTR( argument ) )
        {
            ch_println( ch, "&zSyntax: &Cnews network <&wnews ID #&C> [network name]" );
            ch_println( ch, "&z        &Cnews network <&wnews ID #&C> GNI" );
            return;
        }

        if ( str_cmp( argument, "gni" ) && strlen( stripclr( argument ) ) > 57 )
        {
            ch_println( ch, "That name is too long. Please try a shorter one." );
            return;
        }

        if ( !str_cmp( argument, "gni" ) )
            SET_STRING( db->str2, "&YG&Oa&zlactic &YN&Oe&zw&ws &YI&On&zc&wo&zr&Op&Yo&Or&za&wt&ze&Od&D" );
        else
            SET_STRING( db->str2, argument );

        ch_println( ch, "Changed network to %s.", str_cmp( argument, "gni" ) ? argument : "&YG&Oa&zlactic &YN&Oe&zw&ws &YI&On&zc&wo&zr&Op&Yo&Or&za&wt&ze&Od&D" );
        save_dbase_sql( DB_TABLE_NEWS, db );
    }
    else
    {
        ch_println( ch, "&zValid options: &Ccreate&z, &Cedit&z, &Cdelete&z, &Crename&z, &Cnetwork&z, &Cpublish&z" );
        return;
    }
}

