/*
    Check to see if weapon is poisoned.
*/
bool is_wielding_poisoned( CHAR_DATA* ch )
{
    OBJ_DATA* obj;

    if (  xIS_SET( ch->race->flags, RFLAG_UNDEAD ) )
        return TRUE;

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) && ( xIS_SET( obj->extra_flags, ITEM_POISONED ) ) )
        return TRUE;

    if ( ( obj = get_eq_char( ch, WEAR_DUAL_WIELD ) ) && ( xIS_SET( obj->extra_flags, ITEM_POISONED ) ) )
        return TRUE;

    return FALSE;
}

bool is_wielding_type( CHAR_DATA* ch, int type )
{
    OBJ_DATA* obj;

    if ( !ch )
    {
        bug( "is_wielding_type: null ch" );
        return false;
    }

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) &&
            obj->item_type == ITEM_WEAPON &&
            obj->value[3] == type )
        return true;

    if ( ( obj = get_eq_char( ch, WEAR_DUAL_WIELD ) ) &&
            obj->item_type == ITEM_WEAPON &&
            obj->value[3] == type )
        return true;

    return false;
}

OBJ_DATA* is_holstered_type( CHAR_DATA* ch, int type )
{
    OBJ_DATA* holster = NULL;
    OBJ_DATA* obj = NULL;
    OBJ_DATA* objective = NULL;

    if ( !ch )
    {
        bug( "is_wielding_type: null ch" );
        return false;
    }

    holster = get_eq_char( ch, WEAR_WAIST );

    if ( holster && holster->item_type == ITEM_HOLSTER )
    {
        for ( obj = holster->first_content; obj; obj = obj->next_content )
        {
            if ( obj->item_type == ITEM_WEAPON && obj->value[3] != type )
            {
                return false;
            }
            else
            {
                objective = obj;
            }
        }
    }
    else
    {
        return false;
    }

    return objective;
}

/*
    hunting, hating and fearing code             -Thoric
*/
bool is_hunting( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch->hunting || ch->hunting->who != victim )
        return FALSE;

    return TRUE;
}

bool is_tracking( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch->tracking || ch->tracking->who != victim )
        return FALSE;

    return TRUE;
}

bool is_hating( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch->hating || ch->hating->who != victim )
        return FALSE;

    if ( victim->hit <= 0 )
    {
        stop_hating( ch );
        return FALSE;
    }

    return TRUE;
}

bool is_fearing( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch->fearing || ch->fearing->who != victim )
        return FALSE;

    return TRUE;
}

void stop_hunting( CHAR_DATA* ch )
{
    if ( ch->hunting )
    {
        debug( "stop_hunting: %s no longer hunting %s", ch->name, ch->hunting->name );
        FREE_STRUCT_NORET( ch->hunting, hhf_fields );
    }

    return;
}

