/*
    Control the fights going on.
    Called periodically by update_handler.
    Many hours spent fixing bugs in here by Thoric, as noted by residual
    debugging checks.  If you never get any of these error messages again
    in your logs... then you can comment out some of the checks without
    worry.
*/
void violence_update( void )
{
    char buf[MSL];
    CHAR_DATA* ch;
    CHAR_DATA* lst_ch;
    CHAR_DATA* victim;
    CHAR_DATA* rch, *rch_next;
    AFFECT_DATA* paf, *paf_next;
    ch_ret     retcode;
    SKILL_DATA*   skill;
    lst_ch = NULL;
    first_cqueue = NULL;
    last_cqueue = NULL;
    CQUEUE_DATA* cq = NULL;
    int milliseconds = 0, loop_start = 0, leg = 0, leg_time = 0;

    clock_t start_time = clock();

    for ( ch = last_char; ch; lst_ch = ch, ch = gch_prev )
    {
        // Begin leg 1
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        leg = 1;
        loop_start = milliseconds;
        leg_time = loop_start;
        /*
            See if we got a pointer to someone who recently died...
            if so, either the pointer is bad... or it's a player who
            "died", and is back at the healer...
            Since he/she's in the char_list, it's likely to be the later...
            and should not already be in another fight already
        */

        /*
            See if we got a pointer to some bad looking data...
        */
        if ( !ch->in_room || !ch->name )
        {
            log_string( "violence_update: bad ch record!  (Shortcutting.)" );
            snprintf( buf, MSL, "ch: %ld  ch->in_room: %ld  ch->prev: %ld  ch->next: %ld", ( long ) ch, ( long ) ch->in_room, ( long ) ch->prev, ( long ) ch->next );
            log_string( buf );
            log_string( lastplayercmd );

            if ( lst_ch )
                snprintf( buf, MSL, "lst_ch: %ld  lst_ch->prev: %ld  lst_ch->next: %ld",  ( long ) lst_ch, ( long ) lst_ch->prev, ( long ) lst_ch->next );
            else
                strlcpy( buf, "lst_ch: NULL", MSL );

            log_string( buf );
            gch_prev = NULL;
            continue;
        }

        // Sometimes mobs end up in fighting position without a target. This cleans that up.
        if ( ch->position == POS_FIGHTING && !ch->fighting )
            ch->position = POS_STANDING;

        set_cur_char( ch );

        if ( ch == first_char && ch->prev )
        {
            bug( "ERROR: first_char->prev != NULL, fixing...", 0 );
            ch->prev = NULL;
        }

        gch_prev    = ch->prev;

        if ( gch_prev && gch_prev->next != ch )
        {
            snprintf( buf, MSL, "FATAL: violence_update: %s->prev->next doesn't point to ch.", ch->name );
            bug( buf, 0 );
            bug( "Short-cutting here", 0 );
            ch->prev = NULL;
            gch_prev = NULL;
        }

        /*
            Update the AP counter for this character
        */
        ch->ap = UMIN( ch->ap + 1, get_max_ap( ch ) );

        /*
            Experience gained during battle deceases as battle drags on
        */
        if ( ch->fighting )
            if ( ( ++ch->fighting->duration % 24 ) == 0 )
                ch->fighting->xp = ( ( ch->fighting->xp * 9 ) / 10 );

        if ( IS_AFFECTED( ch, AFF_BACTA_STIM ) && ch->hit < ch->max_hit )
        {
            ch->hit = UMIN( ch->hit + number_range( 100, 200 ), ch->max_hit );
            act( AT_GREEN, "The bacta flowing through your veins heals your wounds from within.",
                 ch, NULL, NULL, TO_CHAR );
        }

        // End leg 1/begin leg 2
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );
        leg_time = milliseconds;
        leg++;

        /*
            We need spells that have shorter durations than an hour.
            So a melee round sounds good to me... -Thoric
        */
        for ( paf = ch->first_affect; paf; paf = paf_next )
        {
            paf_next = paf->next;

            if ( --paf->duration < 0 )
            {
                if ( !paf_next || paf_next->type != paf->type || paf_next->duration > 0 )
                {
                    skill = skill_from_id( paf->type );

                    if ( paf->type > 0 && skill && skill->msg_off )
                    {
                        set_char_color( AT_WEAROFF, ch );
                        send_to_char( skill->msg_off, ch );
                        ch_println( ch, "" );
                    }
                }

                affect_remove( ch, CHAR_AFFECT, paf );
                continue;
            }

            if ( xIS_SET( paf->bitvector, AFF_NAPALM ) )
            {
                paf->duration = URANGE( 0, paf->duration, SHRT_MAX );
                act( AT_BLOOD, "$n screams as $s body is engulfed in flames!", ch, NULL, NULL, TO_ROOM );
                act( AT_RED, "You scream as your body is engulfed in flames!", ch, NULL, NULL, TO_CHAR );
                interrupt_ch( ch );
                damage( ch, ch, paf->modifier, TYPE_UNDEFINED );
            }

            if ( char_extracted( ch ) )
                break;
        }

        if ( char_extracted( ch ) )
            continue;

        // End leg 2/begin leg 3
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );
        leg_time = milliseconds;
        leg++;

        update_blood_toxicity( ch );

        //Relocated from char_update. Jetpacks should be continuously using fuel, not once every 60-70 seconds. - Gathorn 28Nov17
        if ( get_eq_char( ch, WEAR_BACK ) != NULL )
        {
            OBJ_DATA* tobj = get_eq_char( ch, WEAR_BACK );

            if ( tobj->item_type == ITEM_JETPACK )
            {
                if ( tobj->value[2] > 0 )
                {
                    tobj->value[2]--;

                    if ( tobj->value[2] == 0 )
                    {
                        ch_println( ch, "&zYour jetpack's onboard computer comes online. &G'&gEngines stabilized.&G'&w" );
                    }
                }

                if ( tobj->value[5] != 0 )
                {
                    tobj->value[4] -= 5;

                    if ( tobj->value[4] <= 0 )
                    {
                        act( AT_PLAIN, "$p sputters and dies, dropping you abruptly to the floor.", ch, tobj, NULL, TO_CHAR );
                        act( AT_PLAIN, "$n's jetpack sputters and dies, dropping them out of the sky.", ch, NULL, NULL, TO_ROOM );
                        tobj->value[4] = tobj->value[5] = 0;

                        if ( IS_AFFECTED( ch, AFF_FLYING ) )
                            xREMOVE_BIT( ch->affected_by, AFF_FLYING );
                    }
                }
            }
        }

        // End leg 3/begin leg 4
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );
        leg_time = milliseconds;
        leg++;

        /*
            Here's where you might wanna break out of code if certain things happen,
            Such as your victim being paralysed.
        */
        if ( ( victim = who_fighting( ch ) ) == NULL || IS_AFFECTED( ch, AFF_PARALYSIS ) )
            continue;

        retcode = rNONE;

        if ( is_safe( ch, victim ) )
        {
            snprintf( buf, MSL, "violence_update: %s fighting %s in a SAFE room.", ch->name, victim->name );
            log_string( buf );
            stop_fighting( ch, TRUE );
        }
        else if ( IS_AWAKE( ch ) && ch->in_room == victim->in_room )
        {
            /*
                Execute the combat routine, I guess
            */
            retcode = multi_hit( ch, victim, TYPE_UNDEFINED );
            show_commprompt( ch->desc );
            cq = NULL;
            OBJ_DATA* tobj = NULL;
            bool queue_found = FALSE;

            for ( cq = first_cqueue; cq && !queue_found; cq = cq->next )
            {
                if ( cq && ( cq->ch == ch || cq->ch == victim ) )
                {
                    queue_found = TRUE;
                    break;
                }
            }

            tobj = get_eq_char( ch, WEAR_WIELD );

            if ( queue_found == FALSE )
            {
                CREATE( cq, CQUEUE_DATA, 1 );
                cq->ch = ch;

                if ( tobj != NULL && tobj->item_type == ITEM_WEAPON )
                    cq->obj_type = tobj->value[3];
                else
                    cq->obj_type = WEAPON_NONE;

                LINK( cq, first_cqueue, last_cqueue, next, prev );
            }
            else
            {
                if ( tobj != NULL && tobj->item_type == ITEM_WEAPON && tobj->value[3] > cq->obj_type )
                    cq->obj_type = tobj->value[3];
            }
        }
        else
            stop_fighting( ch, FALSE );

        // End leg 4/begin leg 5
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );
        leg_time = milliseconds;
        leg++;

        if ( char_extracted( ch ) )
            continue;

        if ( retcode == rCHAR_DIED || ( victim = who_fighting( ch ) ) == NULL )
            continue;

        /*
            Mob triggers
        */
        rprog_rfight_trigger( ch );
        mprog_hitprcnt_trigger( ch, victim );
        lua_trigger_on_ch_fight( ch, victim );
        mprog_fight_trigger( ch, victim );

        // End leg 5/begin leg 6
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );
        leg_time = milliseconds;
        leg++;

        if ( char_extracted( ch ) || char_extracted( victim ) )
            continue;

        /*
            Fun for the whole family!
        */
        for ( rch = ch->in_room->first_person; rch; rch = rch_next )
        {
            rch_next = rch->next_in_room;

            if ( !ch || !victim || char_extracted( ch ) || char_extracted( victim ) )
                break;

            if ( IS_AWAKE( rch ) && !rch->fighting )
            {
                /*
                    PC's auto-assist others in their group.
                */
                if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) || IS_AFFECTED( ch, AFF_CHARM ) )
                {
                    if (
                        ( ( !IS_NPC( rch ) && !IS_SWITCHED_NPC( rch ) ) || IS_AFFECTED( rch, AFF_CHARM ) )
                        && is_same_group( ch, rch )
                        && !get_timer( rch, TIMER_DO_FUN ) // Don't join the fight if you're busy
                    )
                    {
                        act( AT_YELLOW, "You assist $N.", rch, NULL, ch, TO_CHAR );
                        act( AT_YELLOW, "$n assists you.", rch, NULL, ch, TO_VICT );
                        act( AT_YELLOW, "$n assists $N.", rch, NULL, ch, TO_NOTVICT );
                        multi_hit( rch, victim, TYPE_UNDEFINED );
                        show_commprompt( ch->desc );
                    }

                    continue;
                }

                if ( rch->ai_data )
                {
                    if ( char_extracted( ch ) )
                        break;

                    if ( is_ai( rch, AI_POLICE ) )
                    {
                        if ( is_ai( ch, AI_CITIZEN ) || is_ai( ch, AI_POLICE ) )
                        {
                            multi_hit( rch, who_fighting( ch ), TYPE_UNDEFINED );
                            continue;
                        }
                    }

                    if ( is_ai( rch, AI_THIEF ) )
                    {
                        if ( is_ai( ch, AI_THIEF ) )
                        {
                            multi_hit( rch, who_fighting( ch ), TYPE_UNDEFINED );
                            continue;
                        }
                    }

                    if ( is_ai( rch, AI_CITIZEN ) )
                    {
                        if ( !is_ai( ch, AI_SOLDIER_LIGHT ) && !is_ai( ch, AI_POLICE ) )
                            ai_police_backup( on_planet( rch ), ch );
                    }

                    if ( is_ai( rch, AI_SOLDIER_LIGHT ) )
                    {
                        if ( in_clan( ch ) == rch->ai_data->clan )
                        {
                            if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) || victim->pcdata->clan != rch->ai_data->clan )
                            {
                                multi_hit( rch, victim, TYPE_UNDEFINED );
                                continue;
                            }
                        }

                        if ( !is_ai( ch, AI_SOLDIER_LIGHT ) && !is_ai( ch, AI_POLICE ) )
                        {
                            multi_hit( rch, ch, TYPE_UNDEFINED );
                            continue;
                        }
                    }
                }

                /*
                    NPC's assist NPC's of same type.
                    GRAL Ware the bs droids kill the master and stuff ganging the ai
                    MAYBE this is the source of Pez spam Mpdamage: trying to damage self, Mob #5387.
                */
                if ( ( IS_NPC( rch ) || IS_SWITCHED_NPC( rch ) ) &&
                        !IS_AFFECTED( rch, AFF_CHARM ) &&
                        !xIS_SET( rch->act, ACT_NOASSIST ) &&
                        !xIS_SET( rch->act, ACT_SAFE ) &&
                        !is_ai( rch, AI_CITIZEN ) )
                {
                    if ( char_extracted( ch ) )
                        break;

                    if ( rch->pIndexData == ch->pIndexData || is_same_group( rch, ch ) )
                    {
                        CHAR_DATA* vch;
                        CHAR_DATA* target;
                        int number;
                        target = NULL;
                        number = 0;

                        for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
                        {
                            if ( can_see( rch, vch )
                                    &&   is_same_group( vch, victim )
                                    &&   number_range( 0, number ) == 0 )
                            {
                                target = vch;
                                number++;
                            }
                        }

                        if ( target )
                            multi_hit( rch, target, TYPE_UNDEFINED );
                    }
                }
            }
        }

        // End leg 6/begin leg 7
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, ch->name );

        if ( (milliseconds - loop_start) > 100 )
            debug("%s: loop took %d ms, char %s", FUNC, milliseconds - loop_start, ch->name );        

        leg_time = milliseconds;
        leg++;
    }

    cq = NULL;
    CQUEUE_DATA* cnext = NULL;

    for ( cq = first_cqueue; cq; cq = cnext )
    {
        // Begin leg 1
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        leg = 1;
        leg_time = milliseconds;

        cnext = cq->next;
        UNLINK( cq, first_cqueue, last_cqueue, next, prev );

        if ( number_range( 1, 2 ) == 1 )
        {
            if ( cq->obj_type == WEAPON_BLASTER || cq->obj_type == WEAPON_BOWCASTER )
            {
                yell_radius( cq->ch, "blaster fire", false );
            }
            else if ( cq->obj_type != WEAPON_NONE )
            {
                yell_radius( cq->ch, "weapons clashing", false );
            }
            else
            {
                yell_radius( cq->ch, "a fight", false );
            }
        }

        // End leg 1 (the only leg in this for loop)
        milliseconds = (clock() - start_time) * 1000 / CLOCKS_PER_SEC;
        if ( (milliseconds - leg_time) > 25 )
            debug("%s: CQ leg %d took %d ms, char %s", FUNC, leg, milliseconds - leg_time, cq->ch ? cq->ch->name : "(null)" );
        leg_time = milliseconds;
        leg++;

        DISPOSE( cq );
    }

    first_cqueue = NULL;
    last_cqueue = NULL;
    return;
}



/*
    Do one group of attacks.
*/
ch_ret multi_hit( CHAR_DATA* ch, CHAR_DATA* victim, int dt )
{
    int     chance;
    int     dual_bonus;
    OBJ_DATA* obj = NULL;
    bool ranged;
    ch_ret  retcode;
    DROID_DATA* db = droid_from_controller( ch->id );
    CHAR_DATA* droid = mob_from_droid( db );
    SKILL_DATA* skill = NULL;

    if ( !ch || !victim )
        return rNONE;

    if ( char_extracted( ch ) || char_extracted( victim ) )
        return rNONE;

    // Unconscious people can't attack.
    if ( ch->position <= POS_STUNNED )
        return rNONE;

    if ( IS_AFFECTED( ch, AFF_CALM ) )
    {
        act( AT_MAGIC, "You're too calm to do that.", ch, NULL, NULL, TO_CHAR );
        return rNONE;
    }

    if ( IS_AFFECTED( victim, AFF_CALM ) )
    {
        cache_skill( "calm", &skill_calm );
        act( AT_YELLOW, "The assault shakes you out of your calmness.", victim, NULL, NULL, TO_CHAR );
        affect_strip( victim, CHAR_AFFECT, skill_calm );
    }

    if ( droid && droid->in_room == ch->in_room && db->active == 2 && db->mode == 1 )
    {
        if ( who_fighting( droid ) == NULL )
        {
            act( AT_BLOOD, "$n jumps into the fray!", droid, NULL, NULL, TO_ROOM );
            multi_hit( droid, victim, TYPE_HIT );
        }

        addDroidExperience( ch, number_range( 1, 45 * ( getDroidLevel( db->exp ) + 1 ) ) );
        if ( char_extracted( victim ) )
            return rNONE;
    }

    add_timer( ch, TIMER_RECENTFIGHT, 60, NULL, NULL, "multihit" );
    add_timer( victim, TIMER_RECENTFIGHT, 60, NULL, NULL, "multihit" );
    /* add timer if player is attacking another player */
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        add_timer( ch, TIMER_RECENTPVP, 60, NULL, NULL, "multihit_pvp" );

    /*
        Check if either of the combatants are holding someone, and if so
        there is a chance the fight will release them. This will allow for
        even weak characters to become martyrs, or the toughest combatants
        to one-round their enemy without losing their quarry.
                                                             -Ulthrax
    */
    if ( ch->holding != NULL )
    {
        chance = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? victim->top_level : number_range( 10, 80 );

        if ( number_percent( ) < chance )
        {
            CHAR_DATA* holding = NULL;

            if ( ( holding = ch->holding ) == NULL )
            {
                bug( "%s with null holding structure in multi_hit", ch->name );
                return rNONE;
            }

            ch_println( ch, "&Y&WThe fight distracts you, and you lose hold of your victim." );
            act( AT_ACTION, "In the midst of the fight, $n lets go of $N!", ch, NULL, holding, TO_NOTVICT );
            release_char( holding, ch, FALSE );
        }
    }

    if ( victim->holding != NULL )
    {
        chance = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? victim->top_level : number_range( 10, 80 );

        if ( number_percent( ) < chance )
        {
            CHAR_DATA* holding = NULL;

            if ( ( holding = victim->holding ) == NULL )
            {
                bug( "%s with null holding structure in multi_hit", victim->name );
                return rNONE;
            }

            ch_println( ch, "&Y&WThe fight distracts you, and you lose hold of your victim." );
            act( AT_ACTION, "In the midst of the fight, $n lets go of $N!", victim, NULL, holding, TO_NOTVICT );
            release_char( holding, victim, FALSE );
        }
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && has_pcflag( ch, PCFLAG_NOFIGHT ) )
    {
        act( AT_GREEN, "$n is not attacking you.", ch, NULL, victim, TO_VICT );
        act( AT_GREEN, "You intentionally miss $N.", ch, NULL, victim, TO_CHAR );
    }

    ranged = TRUE;

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL || ( obj->value[3] != WEAPON_BLASTER && obj->value[3] != WEAPON_BOWCASTER ) || wielding_claws( ch ) )
        if ( ( obj = get_eq_char( ch, WEAR_DUAL_WIELD ) ) == NULL || ( obj->value[3] != WEAPON_BLASTER && obj->value[3] != WEAPON_BOWCASTER ) || wielding_claws( ch ) )
            ranged = FALSE;

    if ( ( !ranged ) && !is_near( ch, victim ) )
    {
        if ( ch->warned == 0 )
        {
            double dist = 0.0;
            dist = ( ( get_curr_dex( ch ) + get_curr_dex( ch ) ) / 2 ) < number_range( 18, 25 ) ?
                   /* Further, or slower */
                   number_range( 2, 3 )
                   /* Closer, or quicker */
                   : number_range( 1, 2 );
            /* Throw in a little chance */
            dist = URANGE( 1, dist - number_range ( 0, 1 ), 6 );
            dist = URANGE( 2, dist / 7, dist );
            ch->warned = ( int )dist;

            act( AT_ACTION, "You begin approaching $N.", ch, NULL, victim, TO_CHAR );
            act( AT_ACTION, "$n begins moving towards $N.", ch, NULL, victim, TO_NOTVICT );
            act( AT_ACTION, "$n begins moving towards you.", ch, NULL, victim, TO_VICT );
            if ( !who_fighting( ch ) )
                set_fighting( ch, victim );
            return rNONE;
        }

        if ( --ch->warned <= 1 )
        {
            ch->approach = victim;
            act( AT_ACTION, "You step closer to $M.", ch, NULL, victim, TO_CHAR );
            act( AT_ACTION, "$n steps closer to $N.", ch, NULL, victim, TO_NOTVICT );
            act( AT_ACTION, "$n steps closer to you.", ch, NULL, victim, TO_VICT );
            ch->warned = 0;
        }
    }
    else if ( is_near( ch, victim ) && ch->warned != 0 )
        ch->warned = 0;

    if ( who_fighting( ch ) == NULL && !ch->ai_data )
    {
        char buf[MSL];

        if ( is_ai( victim, AI_POLICE ) || is_ai( victim, AI_CITIZEN ) )
        {
            snprintf( buf, MSL, "[AI_POLICE_BACKUP] Called against %s for starting a fight.", ch->name );
            log_string( buf );
            ai_police_backup( on_planet( ch ), ch );
        }
    }

    /*
        Character gets one attack here...
    */
    if ( ( retcode = one_hit( ch, victim, dt ) ) != rNONE )
        return retcode;

    /*
        Quit if it was just a backstab/circle, or if we no longer have a enemy.
    */
    cache_skill( "backstab", &skill_backstab );
    cache_skill( "circle", &skill_circle );
    cache_skill( "berserk", &skill_berserk );

    if ( who_fighting( ch ) != victim ||
    ( ( skill = skill_backstab ) != NULL && dt == skill->id ) ||
    ( ( skill = skill_circle ) != NULL && dt == skill->id ) )
        return rNONE;

    /* Very high chance of hitting compared to chance of going berserk */
    /* 40% or higher is always hit.. don't learn anything here though. */
    /* -- Altrag */
    chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 100 : ( get_learned_pct( ch, skill_berserk ) * 5 / 2 );

    if ( IS_AFFECTED( ch, AFF_BERSERK ) && number_percent() < chance )
        if ( ( retcode = one_hit( ch, victim, dt ) ) != rNONE || who_fighting( ch ) != victim )
            return retcode;

    if ( xIS_SET( ch->race->flags, RFLAG_VONG ) )
    {
        // Vong get extra attack rolls, based on how hurt they are. More hurt, more attacks.
        for ( int i = 0; i < 3; i++ )
        {
            if ( number_percent() > ( ch->hit * 100 ) / ch->max_hit )
            {
                ch_println( ch, "&rYour pain energizes you to strike again!" );

                if ( ( retcode = one_hit( ch, victim, dt ) ) != rNONE || who_fighting( ch ) != victim )
                    return retcode;
            }
        }
    }

    /*
        Dual wielding skills. Allows for the extra attack
    */
    if ( get_eq_char( ch, WEAR_DUAL_WIELD ) )
    {
        cache_skill( "dual wield", &skill_dual_wield );
        dual_bonus = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ( ch->skill_level[COMBAT_ABILITY] / 10 ) : ( get_learned_pct( ch, skill_dual_wield ) / 10 );
        chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : get_learned_pct( ch, skill_dual_wield );

        if ( number_percent( ) <= chance )
        {
            learn_from_success( ch, skill_dual_wield );
            retcode = one_hit( ch, victim, dt );

            if ( retcode != rNONE || who_fighting( ch ) != victim )
                return retcode;
        }
        else
            learn_from_failure( ch, skill_dual_wield );
    }
    else
        dual_bonus = 0;

    if ( ch->move < 10 )
        dual_bonus = -20;

    /*
        NPC predetermined number of attacks         -Thoric
    */
    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ch->numattacks > 0 )
    {
        for ( chance = 0; chance < ch->numattacks; chance++ )
        {
            retcode = one_hit( ch, victim, dt );

            if ( retcode != rNONE || who_fighting( ch ) != victim )
                return retcode;
        }

        return retcode;
    }

    cache_skill( "second attack", &skill_second_attack );
    chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? -1 : ( int ) ( ( get_learned_pct( ch, skill_second_attack ) + dual_bonus ) / 1.5 );

    if ( number_percent( ) <= chance )
    {
        learn_from_success( ch, skill_second_attack );
        retcode = one_hit( ch, victim, dt );

        if ( retcode != rNONE || who_fighting( ch ) != victim )
            return retcode;
    }
    else
        learn_from_failure( ch, skill_second_attack );

    if ( IS_AFFECTED( ch, AFF_SPEED ) )
    {
        retcode = one_hit( ch, victim, dt );

        if ( retcode != rNONE || who_fighting( ch ) != victim )
            return retcode;
    }

    OBJ_DATA* tobj = NULL;

    if ( ( tobj = get_eq_char( ch, WEAR_WIELD ) ) != NULL
            && tobj->item_type == ITEM_WEAPON
            && tobj->value[3] == WEAPON_BLASTER
            && xIS_SET( tobj->extra_flags, ITEM_REPEATER ) )
    {
        int numattacks = number_range( 1, 4 ); // Bonus shots for using a repeater

        while ( numattacks )
        {
            numattacks--;
            retcode = one_hit( ch, victim, dt );

            if ( retcode != rNONE || who_fighting( ch ) != victim )
                return retcode;
        }
    }

    if ( xIS_SET( ch->race->flags, RFLAG_EXTRAHIT ) )
        /* GRAL Supposedly this isn't being noticed */
    {
        OBJ_DATA* obj = get_eq_char( ch, WEAR_ABOUT );

        if ( !obj || obj->weight < 85 ) // Heavy armor/mid armor ---- WRONG! Should be light armor (Rojan)
            if ( ch->skill_level[COMBAT_ABILITY] >= 60 )
            {
                tune( "multi_hit: %s is getting an extra hit due to race bonus", ch->name );
                retcode = one_hit( ch, victim, dt );

                if ( retcode != rNONE || who_fighting( ch ) != victim )
                    return retcode;
            }
    }

    retcode = rNONE;
    chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ( int ) ( ch->top_level / 4 ) : 0;

    if ( number_percent( ) < chance )
        retcode = one_hit( ch, victim, dt );

    if ( retcode == rNONE )
    {
        int move;

        if ( !IS_AFFECTED( ch, AFF_FLYING ) && !IS_AFFECTED( ch, AFF_FLOATING ) && ch->in_room )
            move = encumbrance( ch, movement_loss[UMIN( SECT_MAX - 1, ch->in_room->sector_type )] );
        else
            move = encumbrance( ch, 1 );

        if ( ch->move )
            ch->move = UMAX( 0, ch->move - move );
    }

    return retcode;
}


/*
    Weapon types, haus
*/
int weapon_prof_bonus_check( CHAR_DATA* ch, OBJ_DATA* wield, SKILL_DATA** skill_ptr )
{
    int bonus = 0, handicap = 0, bns = 0;
    handicap = 5; /* Global handicap */
    SKILL_DATA* skill = NULL;
    cache_skill( "unarmed combat", &skill_unarmed_combat );
    cache_skill( "advanced unarmed", &skill_advanced_unarmed );
    cache_skill( "unarmed mastery", &skill_unarmed_mastery );

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !wield )
    {
        *skill_ptr = skill_unarmed_combat;

        if ( get_learned_pct( ch, ( skill = skill_advanced_unarmed ) ) > 0 )
        {
            if ( ch->skill_level[HUNTING_ABILITY] > 80 )
                bns += number_range( 50, 200 );

            bns += ( int ) get_learned_pct( ch, skill );
            learn_slow( ch, skill, handicap );
            bns *= 2;
        }

        if ( get_learned_pct( ch, ( skill = skill_unarmed_mastery ) ) > 0 )
        {
            bns += ( int ) get_learned_pct( ch, skill );
            learn_slow( ch, skill, 5 );
            bns *= 2;

            if ( number_range( 1, 3 ) == 3 )
                if ( get_learned_pct( ch, skill ) == 100 )
                    bns *= 4;
        }
    }

    /*
        Weapon proficiencies, Orion
    */

    cache_skill( "bowcasters", &skill_bowcasters );
    cache_skill( "advanced bowcaster", &skill_advanced_bowcaster );
    cache_skill( "bowcaster mastery", &skill_bowcaster_mastery );

    cache_skill( "force pikes", &skill_force_pikes );
    cache_skill( "advanced forcepike", &skill_advanced_forcepike );
    cache_skill( "forcepike mastery", &skill_forcepike_mastery );

