    cache_skill( "blasters", &skill_blasters );
    cache_skill( "advanced blaster", &skill_advanced_blaster );
    cache_skill( "blaster mastery", &skill_blaster_mastery );

    cache_skill( "disruptors", &skill_disruptors );



    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && wield )
    {
        switch ( wield->value[3] )
        {
            case 9:
                *skill_ptr = skill_bowcasters;

                if ( get_learned_pct( ch, ( skill = skill_advanced_bowcaster ) ) > 0 )
                {
                    if ( ch->skill_level[HUNTING_ABILITY] > 80 )
                        bns += number_range( 50, 150 );

                    bns += ( int ) get_learned_pct( ch, skill ) / 2;
                    learn_slow( ch, skill, handicap );
                }

                if ( get_learned_pct( ch, ( skill = skill_bowcaster_mastery ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) ;
                    learn_slow( ch, skill, 5 );
                }

                if ( ch->skill_level[HUNTING_ABILITY] > 99 )
                    bns += number_range( 50, 150 );

                break;

            case 11:
                *skill_ptr = skill_force_pikes;

                if ( get_learned_pct( ch, ( skill = skill_advanced_forcepike ) ) > 0 )
                {
                    if ( ( int ) ch->skill_level[HUNTING_ABILITY] > 80 )
                        bns += number_range( 50, 150 );

                    bns += ( int ) get_learned_pct( ch, skill ) / 2 ;
                    learn_slow( ch, skill, handicap );
                }

                if ( get_learned_pct( ch, ( skill = skill_forcepike_mastery ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) ;
                    learn_slow( ch, skill, 5 );
                }

                if ( ch->skill_level[HUNTING_ABILITY] > 80 )
                    bns += number_range( 50, 150 );

                break;

            case 3:
                *skill_ptr = skill_lightsabers;

                if ( get_learned_pct( ch, ( skill = skill_advanced_lightsaber ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) / 2;
                    learn_slow( ch, skill, handicap );
                }

                if ( get_learned_pct( ch, ( skill = skill_lightsaber_mastery ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) ;
                    learn_slow( ch, skill, 5 );
                }

                break;

            case 2:
                *skill_ptr = skill_vibroblades;

                if ( get_learned_pct( ch, ( skill = skill_advanced_vibroblade ) ) > 0 )
                {
                    if ( ch->skill_level[HUNTING_ABILITY] > 80 )
                        bns += number_range( 50, 150 );

                    bns += ( int ) get_learned_pct( ch, skill ) / 2;
                    learn_slow( ch, skill, handicap );
                }

                if ( get_learned_pct( ch, ( skill = skill_vibroblade_mastery ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) ;
                    learn_slow( ch, skill, 5 );
                }

                if ( ch->skill_level[HUNTING_ABILITY] > 99 )
                    bns += number_range( 50, 150 );

                break;

            case 6:
                *skill_ptr = skill_blasters;

                if ( get_learned_pct( ch, ( skill = skill_advanced_blaster ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) / 2;
                    learn_slow( ch, skill, handicap );
                }

                if ( get_learned_pct( ch, ( skill = skill_blaster_mastery ) ) > 0 )
                {
                    bns += ( int ) get_learned_pct( ch, skill ) ;
                    learn_slow( ch, skill, 5 );
                }

                if ( ch->skill_level[HUNTING_ABILITY] > 99 )
                    bns += number_range( 10, 50 );

                break;

            case 4:
                *skill_ptr = NULL; // Flexible arms
                break;

            case 5:
                *skill_ptr = NULL; // Talonous arms
                break;

            case 8:
                *skill_ptr = NULL; // Bludgeons
                break;

            case 12:
                *skill_ptr = skill_disruptors;
                break;

            default:
                *skill_ptr = NULL;
                break;
        }

        if ( *skill_ptr != NULL )
        {
            bonus = ( int ) ( get_learned_pct( ch, *skill_ptr ) );
            bonus += bns; /* Proficiency bonus */
        }
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield )
        bonus = get_trust( ch );

    /*bug("%s's prof_bonus: %d", ch->name, bonus); */
    return bonus;
}

/*
    Calculate the tohit bonus on the object and return RIS values.
    -- Altrag
*/
int obj_hitroll( OBJ_DATA* obj )
{
    int tohit = 0;
    AFFECT_DATA* paf;

    for ( paf = obj->pIndexData->first_affect; paf; paf = paf->next )
        if ( paf->location == APPLY_HITROLL )
            tohit += paf->modifier;

    for ( paf = obj->first_affect; paf; paf = paf->next )
        if ( paf->location == APPLY_HITROLL )
            tohit += paf->modifier;

    return tohit;
}

/*
    Offensive shield level modifier
*/
sh_int off_shld_lvl( CHAR_DATA* ch, CHAR_DATA* victim )
{
    sh_int lvl;

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )    /* players get much less effect */
    {
        lvl = UMAX( 1, ( ch->skill_level[FORCE_ABILITY] )  );

        if ( number_percent() + ( victim->skill_level[COMBAT_ABILITY] - lvl ) < 35 )
            return lvl;
        else
            return 0;
    }
    else
    {
        lvl = ch->top_level;

        if ( number_percent() + ( victim->skill_level[COMBAT_ABILITY] - lvl ) < 70 )
            return lvl;
        else
            return 0;
    }
}

int calc_hit_percent( CHAR_DATA* ch, CHAR_DATA* victim, OBJ_DATA* wield, bool silent )
{
    // Start the attacker's side with their combat level.
    int ch_hit_val = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : ch->skill_level[COMBAT_ABILITY];
    // Hitroll increases hit chance as much as one combat level per hitroll.
    ch_hit_val += GET_HITROLL( ch );

    // You can't hit what you can't see
    if ( !can_see( ch, victim ) )
        ch_hit_val -= 50;

    // Start the defender's side with their combat level.
    int vict_avoid_val = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? victim->top_level : victim->skill_level[COMBAT_ABILITY];
    // Victim's dexterity increases miss chance.
    vict_avoid_val += get_curr_dex( victim ) * 2;

    // Sleeping victims are easy to hit
    if ( !IS_AWAKE( victim ) )
        vict_avoid_val -= 50;

    vict_avoid_val = UMAX( vict_avoid_val, 1 ); // Don't let negative avoidance make them impossible to hit
    // Do a straightforward comparison between the attacker's hit score and the defender's avoid score.
    int hit_chance = URANGE( 5, ( ch_hit_val * 100 ) / vict_avoid_val, 95 );
    tune( "calc_hit_percent: %s (lvl %d, %d hr) has %d%% chance to hit %s (lvl %d, %d dex)",
          ch->name,
          ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : ch->skill_level[COMBAT_ABILITY],
          GET_HITROLL( ch ),
          hit_chance,
          victim->name,
          ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? victim->top_level : victim->skill_level[COMBAT_ABILITY],
          get_curr_dex( victim )
        );

    // Combat flag Orion 2008
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && has_pcflag( ch, PCFLAG_NOFIGHT ) )
        hit_chance = 0;

    cache_skill( "iron wall", &skill_iron_wall );
    if ( has_feat( victim, skill_iron_wall ) && number_percent() > 95 )
    {
        hit_chance = 0;

        if ( !silent )
            ch_println( victim, "&GYou resist the attack!" );

        tune( "calc_hit_percent: %s resisted %s attack due to iron_wall feat", victim->name, ch->name );
    }

    // CYCLOPS flag: A 5% miss chance with blasters.
    if ( xIS_SET( ch->race->flags, RFLAG_CYCLOPS ) &&
            wield && wield->value[3] == WEAPON_BLASTER &&
            number_percent() > 95
       )
    {
        /* Depth perception threw off your aim */
        if ( !silent )
            ch_println( ch, "&RYour lack of depth perception throws off your aim!&w" );

        hit_chance = 0;
    }

    return hit_chance;
}

/*
    Hit one guy once.

    To keep the Starwars feeling alive, blaster
    damage now does 4 times as much as it used to.  -Ghost

    More-so, there are checks for force ghosts, nice flag, safe flag, and some cool
    titbits for approach and hth vs ranged weapons styles  -Orion
*/
ch_ret one_hit( CHAR_DATA* ch, CHAR_DATA* victim, int dt )
{
    OBJ_DATA* wield;
    OBJ_DATA* device;
    // int plusris;
    int dam;
    int chc = 0;
    int chances = 0;
    int attacktype, cnt;
    int prof_bonus;
    SKILL_DATA* skill = NULL, *prof_skill = NULL;
    ch_ret retcode = 0;
    int chance;
    bool fail, nobonus = FALSE;
    bool wep = FALSE;
    AFFECT_DATA af;
    DROID_DATA* tDB = NULL;
    bool twinblade = FALSE;
    bool ranged = FALSE;
    int lv;

    if ( in_action( ch )  )
        action_clear( ch );

    /*
        Can't beat a dead char!
        Guard against weird room-leavings.
    */
    if ( victim->position == POS_DEAD || ch->in_room != victim->in_room )
        return rVICT_DIED;

    if ( ( victim->spirit ) || ( ch->spirit ) )
    {
        ch_println( ch, "&OYour attack has no effect on your opponent!" );
        stop_fighting( ch, TRUE );
        return rNONE;
    }

    if ( is_safe( ch, victim ) )
        return rNONE;

    if ( ( get_eq_char( ch, WEAR_BINDING ) ) != NULL )
    {
        ch_println( ch, "&OYou are bound, and cannot fight!" );
        return rNONE;
    }

    // Ok so we want players who start fighting or are attacked to have a fight timer! Watch this!
    startFighting( ch, victim );

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && victim->ai_data && !is_enemy( ch, victim ) )
        add_enemy( victim, ch );

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && ch->ai_data && !is_enemy( victim, ch ) )
        add_enemy( ch, victim );

    if ( ch->move <= 0 )
    {
        chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : ( int ) ch->skill_level[COMBAT_ABILITY];
        chance = ( int )( chance * 0.8 );

        if ( number_percent() > chance )
        {
            ch_println( ch, "&OYou are too tired to attack!" );
            return rNONE;
        }
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ( tDB = droid_from_mob( ch ) ) != NULL )
    {
        if ( tDB->mode == 1 )
            addDroidExperience_b( tDB, number_range( 1, 20 ) * ( getDroidLevel( tDB->exp ) + 1 ) );
    }

    // Don't tire out regular NPCs to save us having to add progs to them to keep mental state up
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) || IS_CONTROLLED( ch ) )
        ch->move -= UMAX( 0, number_range( 5, 20 ) ); /* Combat is tiring. */

    if ( ch->mental_state > 0 )
    {
        chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : ( int ) ch->skill_level[COMBAT_ABILITY];

        if ( ch->mental_state > number_range( ( int )( chance * 0.2 ), ( int )( chance * 0.8 ) ) )
        {
            ch_println( ch, "&OYour mind is too scattered to focus on the fight!" );
            return rNONE;
        }
    }

    if ( IS_AFFECTED( ch, AFF_LETHARGY ) && number_percent() < 25 )
    {
        act( AT_ORANGE, "You're moving too slowly and miss the opportunity to strike.", ch, NULL, victim, TO_CHAR );
        act( AT_ORANGE, "$n is moving too slowly and misses the opportunity to strike.", ch, NULL, victim, TO_ROOM );
        return rNONE;
    }

    if ( !IS_NPC( victim ) )
    {
        // Mitigate PVP ganksquads by having people miss more attacks as there are more players fighting the same target.
        int same_target_count = 1; // 1 for the attacker regardless of whether they're set as fighting that target
        for ( CHAR_DATA* rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
            if ( rch != ch && !IS_NPC( rch ) && who_fighting( rch ) == victim )
                same_target_count++;

        // This math looks like:
        // 3v1: 75% of hits succeed
        // 4v1: 60% of hits succeed
        // 5v1: 50% of hits succeed
        // 6v1: 43% of hits succeed ... and so on
        int pct_chance = 100;
        if ( same_target_count > 2 )
            pct_chance = 100 - (same_target_count-2)*100 / (same_target_count+1);
        if ( number_percent() > pct_chance )
        {
            ch_println( ch, "&OAnother attacker gets in the way and you miss your chance to strike." );
            return rNONE;
        }
    }

    if ( ch->move <= 0 && number_range( 1, 100 ) > number_range( 1, 100 ) )
    {
        ch_println( ch, "&OYour fatigue wears on you!" );
        worsen_mental_state( ch, 1 );
    }

    /*
        Figure out the weapon doing the damage           -Thoric
    */
   cache_skill( "circle", &skill_circle );
   cache_skill( "slash", &skill_slash );
    if ( ( wield = get_eq_char( ch, WEAR_DUAL_WIELD ) ) != NULL &&
    ( !skill_circle || dt != skill_circle->id ) &&
    ( !skill_slash || dt != skill_slash->id ) )
    {
        if ( dual_flip == FALSE )
        {
            if ( ( !skill_slash || dt != skill_slash->id ) && ( !skill_circle || dt != skill_circle->id ) )
                dual_flip = TRUE;

            wield = get_eq_char( ch, WEAR_WIELD );
        }
        else
            dual_flip = FALSE;
    }
    else
        wield = get_eq_char( ch, WEAR_WIELD );

    if ( wield != NULL )
        wep = TRUE;

    if ( !wield && ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
    {
        if ( get_learned_pct( ch, skill_unarmed_mastery ) > 0 )
            dt = skill_unarmed_mastery->id;
        else if ( get_learned_pct( ch, skill_advanced_unarmed ) > 0 )
            dt = skill_advanced_unarmed->id;
        else
            dt = skill_unarmed_combat ? skill_unarmed_combat->id : -1;
    }

    cache_skill( "snipe", &skill_snipe );
    if ( skill_snipe && dt == skill_snipe->id )
    {
        if ( ( wield = get_eq_char( ch, WEAR_WIELD ) ) == NULL || wield->item_type != ITEM_WEAPON ||
                ( wield->value[3] != WEAPON_BLASTER && wield->value[3] != WEAPON_BOWCASTER )  || wielding_claws( ch ) || xIS_SET( wield->extra_flags, ITEM_REPEATER ) )
        {
            if ( ( wield = get_eq_char( ch, WEAR_DUAL_WIELD ) ) == NULL || wield->item_type != ITEM_WEAPON ||
                    wield->value[3] != WEAPON_BLASTER || wielding_claws( ch ) || xIS_SET( wield->extra_flags, ITEM_REPEATER ) )
            {
                ch_println( ch, "&OYou aren't wielding a ranged weapon!" );
                return rNONE;
            }
        }
    }

    /*
        Process NPC Special attacks  -Redesigned by Ghost
    */
    if ( ch->fighting && dt == TYPE_UNDEFINED && ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && !xIS_EMPTY( ch->attacks ) )
    {
        cnt = 0;

        for ( ;; )
        {
            attacktype = number_range( 0, 6 );

            if ( xIS_SET( ch->attacks, attacktype ) )
                break;

            if ( cnt++ > 16 )
            {
                attacktype = -1;
                break;
            }
        }

        if ( attacktype == ATCK_BACKSTAB )
            attacktype = -1;

        if ( wield && number_percent( ) > 25 )
            attacktype = -1;

        if ( !wield && number_percent( ) > 50 )
            attacktype = -1;

        switch ( attacktype )   /* Attack Types, Rewritten by Ghost */
        {
            default: /* No attack chosen */
                break;

            case ATCK_BITE:
                retcode = global_retcode;
                break;

            case ATCK_CLAWS:
                retcode = global_retcode;
                break;

            case ATCK_TAIL:
                retcode = global_retcode;
                break;

            case ATCK_STING:
                retcode = global_retcode;
                break;

            case ATCK_PUNCH:
                do_punch( ch, "" );
                retcode = global_retcode;
                break;

            case ATCK_KICK:
                do_kick( ch, "" );
                retcode = global_retcode;
                break;

            case ATCK_TRIP:
                attacktype = 0;
                break;
        }

        if ( attacktype >= 0 )
            return retcode;
    }

    /*
        Add in the weapon-damage type
    */
    if ( dt == TYPE_UNDEFINED )
    {
        dt = TYPE_HIT;

        if ( wield && wield->item_type == ITEM_WEAPON )
        {
            dt += wield->value[3];

            if ( wield->value[3] == WEAPON_BLASTER )
                nobonus = TRUE;

            if ( wield->value[3] == WEAPON_BOWCASTER )
                nobonus = TRUE;
        }
    }

    if ( wield && wield->item_type == ITEM_WEAPON )
    {
        if ( wield->value[3] == WEAPON_BLASTER )
            ranged = TRUE;

        if ( wield->value[3] == WEAPON_BOWCASTER )
            ranged = TRUE;
    }

    if ( ( !ranged ) && !is_near( ch, victim ) )
    {
        if ( ch->warned == 0 )
        {
            ch->warned = 4;
            act( AT_ACTION, "You begin approaching $N.", ch, NULL, victim, TO_CHAR );
            act( AT_ACTION, "$n begins moving towards $N.", ch, NULL, victim, TO_NOTVICT );
            act( AT_ACTION, "$n begins moving towards you.", ch, NULL, victim, TO_VICT );
            return rNONE;
        }

        if ( !is_near( ch, victim ) && !is_near( victim, ch ) )
        {
            ch_println( ch, "&OYou need to get closer to strike with %s!", wield == NULL ? "your bare hands" : "this weapon" );
            return rNONE;
        }
    }
    cache_skill( "slowdraw", &skill_slowdraw );
    int hit_chance = ( skill_slowdraw && dt == skill_slowdraw->id ) ? 100 : calc_hit_percent( ch, victim, wield, false ); // Slowdraw guaranteed a hit

    if ( hit_chance < number_percent() )
    {
        /* Missed. */
        damage( ch, victim, 0, dt );
        tail_chain( );
        tune( "one_hit/hit_chance: %s was missed by %s, hit chance %d%%", victim->name, ch->name, hit_chance );
        return rNONE;
    }
    else
    {
        debug( "one_hit/hit_chance: %s was not missed by %s, hit chance %%d", victim->name, ch->name, hit_chance );
    }

    /*
        Hit.
        Calc damage.
    */

    if ( !wep )       /* dice formula fixed by Thoric, changed later by Orion */
    {
        if ( !wielding_claws( ch ) )
            dam = number_range( get_curr_str( ch ) * get_curr_dex( ch ) / 10, get_curr_str( ch ) * get_curr_dex( ch ) / 7 );
        else
            dam = number_range( 90, 130 );  //dewclaw damage, like a good vibroblade?
    }
    else
        dam = number_range( wield->value[1], wield->value[2] );

    cache_skill( "slowdraw", &skill_slowdraw );
    if ( skill_slowdraw && dt == skill_slowdraw->id )
        dam = ( int )( dam * number_range( 12, 15 ) / 10 );

    //moved by Rojan to AFTER dam is defined, since dam *= 3, when dam isn't set yet, is ALWAYS 0
    if ( ( !wield ) && has_cyber_flag( ch, CYBER_RIDGES ) )
    {
        dam *= 3;
    }

    if ( has_cyber_flag( victim, CYBER_DERMAL ) )
    {
        int modifier = ( int )( ( 10 * dam ) / 100 ); //10 should be modifiable, but setting it static for now out of laziness
        dam -= modifier;
        tune( "one_hit: %s damage against %s moderated by dermal cyber, modifier -%d", ch->name, victim->name, modifier );
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        cache_skill( "toughness", &skill_toughness );
        if ( has_feat( victim, skill_toughness ) )
        {
            int modifier = ( int )( 1 * ( dam / 10 ) );
            dam -= modifier;
            tune( "one_hit: %s damage against %s moderated by toughness feat, modifier -%d", ch->name, victim->name, modifier );
        }

        if ( IS_AFFECTED( victim, AFF_FORTIFY ) )
        {
            int modifier = ( int )( 2 * ( dam / 10 ) );
            dam -= modifier;
            tune( "one_hit: %s damage against %s moderated by fortify affect, modifier -%d", ch->name, victim->name, modifier );
        }
        else if ( IS_AFFECTED( victim, AFF_BATTLE_MEDITATION ) )
        {
            int modifier = dam / 10;
            dam -= modifier;
            tune( "one_hit: %s damage against %s moderated by battle meditation affect, modifier -%d", ch->name, victim->name, modifier );
        }
    }

    if ( valid_focus( ch, COMBAT_ABILITY ) )
    {
        int modifier = ( int )( 1 * ( dam / 10 ) );
        dam += modifier;
        tune( "one_hit: %s damage against %s receives bonus as a combat main: %d", ch->name, victim->name, modifier );
    }

    /*
        Bonuses.
        (No longer works with Blasters and Bowcasters)
    */
    if ( !nobonus )
        dam += GET_DAMROLL( ch );

    cache_skill( "enhanced damage", &skill_enhanced_damage );
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && get_learned_pct( ch, skill_enhanced_damage ) > 0 )
    {
        int modifier = ( ( int )( ( double )( dam / 100. ) * ( double )( get_learned_pct( ch, skill_enhanced_damage ) ) ) * 2 );
        dam += modifier;
        tune( "one_hit: %s damage against %s receives bonus from enhanced_damage: %d", ch->name, victim->name, modifier );
        /* dam *= (int) (dam * get_learned_pct( ch, skill_enhanced_damage ) / 120); */
        learn_slow( ch, skill_enhanced_damage, 3 );
    }

    /*
        Level bonus. Huge damage boost in current fight
        Lasts about 5 rounds. -Ghost
    */
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ch->fighting && !nobonus )
    {
        if ( ch->fighting->bonus > 0 )
        {
            int modifier = dam * ( ch->fighting->bonus - 1 );
            dam += modifier;
            ch->fighting->bonus--;
            tune( "one_hit: %s damage against %s receiving fighting damage bonus of %d, hits remaining: %d", ch->name, victim->name, modifier, ch->fighting->bonus );
        }
        else if ( ch->fbonus > 0 )
        {
            int modifier = dam * UMAX( 0, ( ch->fbonus / 10 ) - 1 );
            dam += modifier;
            ch->fighting->bonus = ( ch->fbonus / 10 );
            tune( "one_hit: %s damage against %s receiving fighting damage bonus of %d, fbonus: %d", ch->name, victim->name, modifier, ch->fbonus );
        }
    }

    cache_skill( "senses", &skill_senses );
    chances = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 0 : ( int ) get_learned_pct( ch, skill_senses );

    if ( chances != 0 && number_percent() <= chances && !has_pcflag( ch, PCFLAG_NO_SENSE ) && get_eq_char( ch, WEAR_WIELD ) && get_eq_char( ch, WEAR_WIELD )->value[3] == WEAPON_LIGHTSABER  )
    {
        OBJ_DATA* armor = get_eq_char( ch, WEAR_ABOUT );

        // Forcers on drugs will be dramatically less effective in combat.
        if ( ch->pcdata && ch->pcdata->blood_toxicity >= 20 && number_percent() <= 50 )
        {
            if ( number_range( 1, 3 ) == 3 ) // Just to cut down on spam.
                ch_println( ch, "&OYou're too disoriented to focus on your enemy's movements." );
        }
        else if ( armor && get_armor_type( armor ) >= 2 && number_percent() <= 50 )
        {
            if ( number_range( 1, 3 ) == 3 ) // Just to cut down on spam.
                ch_println( ch, "&OYour armor slows you down too much to take advantage of your senses." );
        }
        else
        {
            dam += number_range( dam * 2, dam * 3 );
            tune( "one_hit: %s is receiving damage boost from senses", ch->name );

            if ( number_range( 1, 7 ) > 5 ) // Just to cut down on spam.
                ch_println( ch, "&WYou notice your enemy's next move, and capitalize." );

            // Minimum 5% chance to pass onto apprentice even if a master has adepted the skill.
            if ( number_percent() <= UMAX( 100 - chances, 5 ) )
                learn_slow( ch, skill_senses, 3 );
        }
    }

    if ( ranged )
    {
        cache_skill( "duelist", &skill_duelist );
        if ( has_feat( ch, skill_duelist ) )
        {
            if ( get_eq_char( ch, WEAR_WIELD ) && !xIS_SET( get_eq_char( ch, WEAR_WIELD )->extra_flags, ITEM_NODUAL ) )
            {
                int modifier = ( int )( 2 * ( dam / 10 ) );
                dam += modifier;
                tune( "one_hit: %s damage against %s receives duelist bonus of %d.", ch->name, victim->name, modifier );
            }
        }
    }

    /*
        Check to see if weapon is charged
    */
    if ( wield && wield->item_type == ITEM_WEAPON && wield->value[3] == WEAPON_BLASTER )
    {
        if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
            dam /= 2;

        /*        if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) ) dam /= 5;*/
        /*        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ) dam *= 1.25;*/
        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
            dam = ( int )( dam * 0.75 );

        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1 && ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield->value[5] > 0 )
        {
            act( AT_PLAIN, "$n replaces the ammunition cell in $p.", ch, wield, NULL, TO_ROOM );
            wield->value[4] = wield->value[5];
        }

        if ( wield->value[4] < 1  )
        {
            act( AT_YELLOW, "$n points their blaster at you but nothing happens.",  ch, NULL, victim, TO_VICT    );
            act( AT_YELLOW, "$n is out of ammo for $p.", ch, wield, NULL, TO_ROOM );
            act( AT_YELLOW, "*CLICK* ... your blaster needs a new ammunition cell!", ch, NULL, victim, TO_CHAR    );

            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            {
                do_remove( ch, wield->name );
            }

            return rNONE;
        }
        else if ( wield->blaster_setting == BLASTER_FULL && wield->value[4] >= 5 )
        {
            cache_skill( "snipe", &skill_snipe );
            if ( ( skill_snipe && dt == skill_snipe->id ) && xIS_SET( wield->extra_flags, ITEM_NODUAL ) && !xIS_SET( wield->extra_flags, ITEM_REPEATER ) )
            {
                dam = ( int )( dam * 4.3 );
                wield->value[4] = 0;
            }
            else
            {
                dam = ( int )( dam * 2.9 );             /*    3.5   x  4 =  14      */
                wield->value[4] -= 50;
            }
        }
        else if ( wield->blaster_setting == BLASTER_HIGH && wield->value[4] >= 4 )
        {
            dam *=  2;                 /*   2.25  x  4 =  9      */
            wield->value[4] -= 25;
        }
        else if ( wield->blaster_setting == BLASTER_NORMAL && wield->value[4] >= 3 )
        {
            dam = ( int )( dam * 1.5 );             /*   1.75  x  4 =  7      */
            wield->value[4] -= 10;
        }
        else if ( wield->blaster_setting == BLASTER_STUN && wield->value[4] >= 5 )
        {
            dam /= 20;
            dam = URANGE( 0, dam, 50 );
            wield->value[4] -= 3;
            fail = FALSE;

            if ( xIS_SET( victim->immune, RIS_PARALYSIS ) )
                fail = TRUE;
            else if ( xIS_SET( victim->resistant, RIS_PARALYSIS ) && number_percent() <= 75 )
                fail = TRUE;

            /* else */
            /*   fail = saves_para_petri( chance, victim ); */
            if ( victim->was_stunned > 0 )
            {
                fail = TRUE;
                victim->was_stunned--;
            }

            chance = 100 - get_curr_con( victim ) - victim->skill_level[COMBAT_ABILITY] / 2;

            /* harder for player to stun another player */
            if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
                chance -= sysdata.stun_plr_vs_plr;
            else
                chance -= sysdata.stun_regular;

            chance = URANGE( 3, chance, 95 );

            cache_skill( "increasedresistance", &skill_increased_resistance );
            if ( has_feat( victim, skill_increased_resistance ) )
                if ( number_percent() <= 25 )
                    fail = TRUE;


            OBJ_DATA* pShield = NULL;
            bool has_shield = FALSE;

            if ( ( pShield = get_eq_char( victim, WEAR_SHIELD ) ) != NULL )
            {
                if ( pShield->item_type == ITEM_SHIELD && pShield->value[4] > 0 && pShield->value[3] != 0 )
                {
                    pShield->value[4] = URANGE( 0, pShield->value[4] - dam, pShield->value[4] );
                    act( AT_BLUE, "Blue rings of energy from $N's blaster dissipate against your energy shield.", victim, NULL, ch, TO_CHAR );
                    act( AT_BLUE, "Blue rings of energy from your blaster dissipate against $N's energy shield.", ch, NULL, victim, TO_CHAR );
                    act( AT_BLUE, "Blue rings of energy from $n's blaster dissipate against $N's energy shield.", ch, NULL, victim, TO_NOTVICT );

                    if ( pShield->value[4] == 0 )
                    {
                        ch_println( victim, "&CYour energy shield fizzles and dies!&w" );
                        act( AT_ACTION, "&C$n's energy shield fails!&w", victim, NULL, NULL, TO_ROOM );
                        pShield->value[3] = 0;
                    }

                    fail = TRUE;
                    has_shield = TRUE;
                }
            }

            if (!fail)
                tune( "one_hit: %s hit against %s has %d%% chance of stunning.", ch->name, victim->name, chance );

            if ( !fail && number_percent( ) < chance && !check_parry( ch, victim, dam, wield ) && victim->perm_frc <= 3 )
            {
                WAIT_STATE( victim, PULSE_VIOLENCE );
                act( AT_BLUE, "Blue rings of energy from $N's blaster knock you down leaving you stunned!", victim, NULL, ch, TO_CHAR );
                act( AT_BLUE, "Blue rings of energy from your blaster strike $N, leaving $M stunned!", ch, NULL, victim, TO_CHAR );
                act( AT_BLUE, "Blue rings of energy from $n's blaster hit $N, leaving $M stunned!", ch, NULL, victim, TO_NOTVICT );
                stop_fighting( victim, TRUE );
                lua_trigger_on_ch_stun( victim, ch );

                if ( !IS_AFFECTED( victim, AFF_PARALYSIS ) )
                {
                    cache_skill( "stun", &skill_stun );
                    SKILL_DATA* afskill = skill_stun;
                    af.type      = afskill ? afskill->id : -1;
                    af.type      = -1;
                    af.location  = APPLY_AC;
                    af.modifier  = 20;
                    cache_skill( "quick healer", &skill_quick_healer );
                    af.duration = has_feat( victim, skill_quick_healer ) ? 5 : 10;

                    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
                        af.duration = 40;

                    xCLEAR_BITS( af.bitvector );
                    xSET_BIT( af.bitvector, AFF_PARALYSIS );
                    affect_to_target( victim, CHAR_AFFECT, &af );
                    update_pos( victim );

                    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
                    {
                        start_hating( victim, ch );
                        start_hunting( victim, ch );
                        victim->was_stunned = 10;
                    }
                }

                if ( IS_AFFECTED( victim, AFF_FLYING ) )
                    xREMOVE_BIT( victim->affected_by, AFF_FLYING );

                if ( IS_AFFECTED( victim, AFF_HIDE ) )
                    xREMOVE_BIT( victim->affected_by, AFF_HIDE );
            }
            else if ( !has_shield )
            {
                act( AT_BLUE, "Blue rings of energy from $N's blaster hit you but have little effect", victim, NULL, ch, TO_CHAR );
                act( AT_BLUE, "Blue rings of energy from your blaster hit $N, but nothing seems to happen!", ch, NULL, victim, TO_CHAR );
                act( AT_BLUE, "Blue rings of energy from $n's blaster hit $N, but nothing seems to happen!", ch, NULL, victim, TO_NOTVICT );
            }
        }
        else if ( wield->blaster_setting == BLASTER_HALF && wield->value[4] >= 2 )
        {
            dam = ( int )( dam * 1.25 );               /*   1.25   x  4  =  5  */
            wield->value[4] -= 2;
        }
        else
        {
            dam = ( int )( dam * 0.5 );               /*   .5    x  4  =  2  */
            wield->value[4] -= 1;
        }

        dam /= 2; // Halve it now, with new blaster classes this makes sense.    Orion 2008
    }
    else if ( dt == ( TYPE_HIT + WEAPON_VIBRO_BLADE ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1 )
        {
            act( AT_YELLOW, "Your vibro-blade needs recharging ...", ch, NULL, victim, TO_CHAR    );
            act( AT_YELLOW, "$n is out of energy for $p.", ch, wield, NULL, TO_ROOM );
            dam /= 3;
        }

        dam = ( int )( dam * 1.5 );

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
            wield->value[4]--;
    }
    else if ( dt == ( TYPE_HIT + WEAPON_VIBRO_AXE ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1  )
        {
            act( AT_YELLOW, "Your vibro-axe needs recharging ...", ch, NULL, victim, TO_CHAR    );
            act( AT_YELLOW, "$n is out of energy for $p.", ch, wield, NULL, TO_ROOM );
            dam /= 3;
        }

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
            wield->value[4]--;
    }
    else if ( dt == ( TYPE_HIT + WEAPON_FORCE_PIKE ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1  )
        {
            act( AT_YELLOW, "Your force-pike needs recharging ...", ch, NULL, victim, TO_CHAR    );
            act( AT_YELLOW, "$n is out of energy for $p.", ch, wield, NULL, TO_ROOM );
            dam /= 2;
        }
        else
        {
            if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
                wield->value[4]--;
        }
    }
    else if ( dt == ( TYPE_HIT + WEAPON_LIGHTSABER ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1  )
        {
            act( AT_YELLOW, "$n waves a dead hand grip around in the air.",  ch, NULL, victim, TO_VICT    );
            act( AT_YELLOW, "$n is out of energy for $p.", ch, wield, NULL, TO_ROOM );
            act( AT_YELLOW, "You need to recharge your lightsaber ... it seems to be lacking a blade.", ch, NULL, victim, TO_CHAR    );

            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            {
                do_remove( ch, wield->name );
            }

            return rNONE;
        }
        else
        {
            cache_skill( "twinblade", &skill_twinblade );
            if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && get_learned_pct( ch, skill_twinblade ) > 0 && xIS_SET( wield->extra_flags, ITEM_TWINBLADE ) )
            {
                int nchc = 0, rl = number_percent();
                nchc = ( int ) get_learned_pct( ch, skill_twinblade );

                if ( nchc <= 80 )
                    nchc = 0;
                else
                    nchc -= 80;

                if ( rl < nchc )
                {
                    ch_println( ch, "&WYou unleash a twin-blade attack!" );
                    act( AT_ACTION, "$n unleashes a twin-blade attack!\n", ch, NULL, NULL, TO_ROOM );
                    dam *= 2;
                    twinblade = TRUE;
                    learn_from_success( ch, skill_twinblade );
                }
                else
                    learn_slow( ch, skill_twinblade, 5 );
            }

            /*
                Force Level -> Damage Modifier
            */
            lv = ch->skill_level[FORCE_ABILITY];
            dam += lv * 5;
            //if ( ( !IS_NPC(victim) && !IS_SWITCHED_NPC(victim) ) )
            //dam /= 2;
            /*  if ( ( !IS_NPC(victim) && !IS_SWITCHED_NPC(victim) ) && victim->skill_level[FORCE_ABILITY] > 60 )
                dam *= 2;
                if ( ( obj2 = get_eq_char(victim, WEAR_WIELD) ) != NULL && obj2->item_type == ITEM_WEAPON && obj2->value[3] == WEAPON_LIGHTSABER )
                dam *= 2;*/
        }
    }
    else if ( dt == ( TYPE_HIT + WEAPON_BOWCASTER ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1 )
        {
            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield->value[5] > 0 )
            {
                act( AT_PLAIN, "$n replaces the quarrels in $p.", ch, wield, NULL, TO_ROOM );
                wield->value[4] = wield->value[5];
            }
            else
            {
                act( AT_YELLOW, "$n points their bowcaster at you but nothing happens.",  ch, NULL, victim, TO_VICT    );
                act( AT_YELLOW, "*CLICK* ... your bowcaster needs a new bolt cartridge!", ch, NULL, victim, TO_CHAR    );

                if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
                {
                    do_remove( ch, wield->name );
                }

                return rNONE;
            }
        }
        else
            wield->value[4]--;
    }
    else if ( wield && wield->item_type == ITEM_WEAPON && wield->value[3] == WEAPON_BOWCASTER && cache_skill( "snipe", &skill_snipe ) && ( skill_snipe && dt == skill_snipe->id ) )
    {
        if ( wield->value[4] < 1 && ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield->value[5] > 0 )
        {
            act( AT_PLAIN, "$n replaces the quarrels in $p.", ch, wield, NULL, TO_ROOM );
            wield->value[4] = wield->value[5];
        }

        if ( wield->value[4] < 1  )
        {
            act( AT_YELLOW, "$n points their bowcaster at you but nothing happens.",  ch, NULL, victim, TO_VICT    );
            act( AT_YELLOW, "*CLICK* ... your bowcaster needs a new bolt cartridge!", ch, NULL, victim, TO_CHAR    );
            wield->value[4] = 0;

            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            {
                do_remove( ch, wield->name );
            }

            return rNONE;
        }
        else
        {
            dam = ( int )( dam * 2 );             /*    3.5   x  4 =  14      */
            wield->value[4] -= 25;

            if ( wield->value[4] < 0 )
                wield->value[4] = 0;
        }
    }
    else if ( dt == ( TYPE_HIT + WEAPON_FLAMETHROWER ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1 )
        {
            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield->value[5] > 0 )
            {
                act( AT_PLAIN, "$n replaces the fuel cartridge in $p.", ch, wield, NULL, TO_ROOM );
                wield->value[4] = wield->value[5];
            }
            else
            {
                act( AT_YELLOW, "$n points their flamethrower at you, but nothing happens!",  ch, NULL, victim, TO_VICT    );
                act( AT_YELLOW, "*CHUNK* ... Your flamethrower needs a new fuel canister!", ch, NULL, victim, TO_CHAR    );

                if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
                {
                    do_remove( ch, wield->name );
                }

                return rNONE;
            }
        }
        else
            wield->value[4]--;
    }
    else if ( dt == ( TYPE_HIT + WEAPON_DISRUPTOR ) && wield && wield->item_type == ITEM_WEAPON )
    {
        wield->value[4] = URANGE( 0, wield->value[4], wield->value[5] );

        if ( wield->value[4] < 1 && ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && wield->value[5] > 0 )
        {
            act( AT_PLAIN, "$n replaces the ammunition cell in $p.", ch, wield, NULL, TO_ROOM );
            wield->value[4] = wield->value[5];
        }

        if ( wield->value[4] < 1 )
        {
            act( AT_YELLOW, "$n points their disruptor at you but nothing happens.",  ch, NULL, victim, TO_VICT    );
            act( AT_YELLOW, "*CLICK* ... your disruptor needs a new ammunition cell!", ch, NULL, victim, TO_CHAR    );

            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            {
                do_remove( ch, wield->name );
            }

            return rNONE;
        }
        else
        {
            wield->value[4]--;
            /*  Explosion time
                {
                OBJ_DATA * scrap;

                ch_println( ch, "&R%s *EXPLODES* in a ball of fire!", wield->short_descr );
                act( AT_PLAIN, "&R$p *EXPLODES* in $n's hands!", ch, wield, NULL, TO_ROOM );

                global_retcode = damage( ch, ch, number_range( wield->value[1]*10 , wield->value[2]*10 ), TYPE_HIT );

                scrap = make_scraps(wield);

                return rNONE;
                }*/
            fail = FALSE;
            chance = ris_save( victim, ch->skill_level[COMBAT_ABILITY], RIS_PARALYSIS );

            if ( chance == 1000 )
                fail = TRUE;

            /* else */
            /*    fail = saves_para_petri( chance, victim ); */
            if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
                chance = 100 - get_curr_con( victim ) - victim->top_level / 2;
            else
                chance = 100 - get_curr_con( victim ) - victim->skill_level[ESPIONAGE_ABILITY] / 2;

            cache_skill( "disruptors", &skill_disruptors );
            chance += number_range( get_learned_pct( ch, skill_disruptors ) / 2, get_learned_pct( ch, skill_disruptors ) ) * 2;
            chance -= number_range( 25, 70 );
            chance -= sysdata.stun_regular;
            chance = URANGE( 5, chance, 95 );
            bug( "Chance to hit with disruptor - %d", chance );

            if ( !fail && number_percent( ) < chance && get_trust( victim ) >= 5 )
            {
                WAIT_STATE( victim, PULSE_VIOLENCE );
                act( AT_BLUE, "A Wavering blast of energy from $N's disruptor reduces your body to ash!", victim, NULL, ch, TO_CHAR );
                act( AT_BLUE, "A Wavering blast of energy from your disruptor reduces $N to ash!", ch, NULL, victim, TO_CHAR );
                act( AT_BLUE, "A Wavering blast of energy from $n's disruptor hits $N, reducing $M to ash!", ch, NULL, victim, TO_NOTVICT );

                if ( !IS_IMMORTAL( victim ) )
                {
                    if ( prof_skill != NULL )
                        learn_from_success( ch, prof_skill );

                    set_cur_char( victim );
                    victim->disruption = TRUE;
                    damage( ch, victim, URANGE( 0, victim->hit * 12, 90000 ), dt );
                    return rVICT_DIED;
                }
                else
                {
                    act( AT_BLOOD, "With a *SNAP*, $N stands up from the ashes unharmed.", ch, NULL, victim, TO_NOTVICT );
                    act( AT_BLOOD, "With a *SNAP*, $N stands up from the ashes unharmed. Uh oh... ", ch, NULL, victim, TO_CHAR );
                    act( AT_YELLOW, "With a beat of your immortal heart you stand again... stupid $n.", ch, NULL, victim, TO_VICT );
                    return rNONE;
                }
            }
            else
            {
                /*
                    Seem to have a glitch in here, when a person
                    MISSES a shot, he ends up with a 1200 point -suction-
                    hit. I'd call that a glitch, wouldn't you?
                    I hope that rNONE works....   --->->-> Ghost <-<-<---
                */
                act( AT_BLUE, "A Wavering blast of energy from $N's disruptor barely misses you!", victim, NULL, ch, TO_CHAR );
                act( AT_BLUE, "A Wavering blast of energy from your disruptor barely misses $N!", ch, NULL, victim, TO_CHAR );
                act( AT_BLUE, "A Wavering blast of energy from $n's disruptor barely misses $N!", ch, NULL, victim, TO_NOTVICT );

                if ( prof_skill != NULL )
                    learn_from_failure( ch, prof_skill );

                return rNONE;
            }
        }
    }

    /*
        Damage Modifiers
    */
    if ( !IS_AWAKE( victim ) )
    {
        int modifier = dam * 2;
        dam += modifier;
        tune( "one_hit: %s damage against %s receives bonus of %d because victim is sleeping", ch->name, victim->name, modifier );
    }

    cache_skill( "backstab", &skill_backstab );
    cache_skill( "circle", &skill_circle );
    cache_skill( "snipe", &skill_snipe );
    if ( skill_backstab && dt == skill_backstab->id )
    {
        dam *= 2;
        cache_skill( "foresight", &skill_foresight );
        chances = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? 0 : has_pcflag( victim, PCFLAG_NO_SENSE ) ? 0 : ( int ) get_learned_pct( victim, skill_foresight );

        //Ralen - this ifcheck has been broken for some-generic-madeup-deity knows how long. Was >= , should be <= .
        if ( chances > 0 && number_range( 1, 100 ) <= chances )
        {
            cache_skill( "dodge", &skill_dodge );
            chances = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? 0 : ( int ) get_learned_pct( victim, skill_dodge ) / 2;

            if ( number_percent() >= chances )
            {
                ch_println( victim, "You notice %s try to backstab you, but don't move quickly enough!", g_name( ch, victim ) );
                ch_println( ch, "%s notices you as you try to backstab %s, but doesn't manage to evade.", g_name( victim, ch ), victim->sex == 2 ? "her" : "him" );
            }
            else
            {
                ch_println( victim, "&RYou notice %s try to backstab you!\n&GYou quickly evade the attack.", g_name( ch, victim ) );
                ch_println( ch, "%s notices you as you try to backstab %s...and they quickly evade!", g_name( victim, ch ), victim->sex == 2 ? "her" : "him" );
                return rNONE;
            }
        }
    }
    else if ( skill_circle && dt == skill_circle->id )
    {
        // No adjustment at this time, but it could go back here in the future.
    }
    else if ( skill_snipe && dt == skill_snipe->id )
    {
        if ( !xIS_SET( wield->extra_flags, ITEM_REPEATER ) && xIS_SET( wield->extra_flags, ITEM_NODUAL ) )
        {
            dam = ( int )( dam * 1.5 );

            // 25% chance for a critical hit (+50%) if you're a deadeye
            cache_skill( "deadeye", &skill_deadeye );
            if ( has_feat( ch, skill_deadeye ) && number_range( 1, 4 ) == 1 )
            {
                ch_println( ch, "&WYou aimed perfectly!" );
                dam = ( int )( dam * 1.5 );
            }
        }
        else
        {
            dam = ( int )( dam * 0.5 ); // Reduce damage a lot for pistols
        }
    }

    /*
        Check for a proficiency bonus
    */
    prof_bonus = weapon_prof_bonus_check( ch, wield, &prof_skill );
    /* Damage roll-back cap */
    /* dam = UMIN( dam, ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 125 : 200 ); */

    if ( prof_bonus )
        dam += dam * prof_bonus / 100;

    if ( prof_skill != NULL )
    {
        if ( dam > 0 )
            learn_from_success( ch, prof_skill );
        else
            learn_from_failure( ch, prof_skill );
    }

    cache_skill( "integrated optics", &skill_integrated_optics );
    chc = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 0 : ( int ) get_learned_pct( ch, skill_integrated_optics );
    chc -= number_percent();

    if ( chc > 0 && get_eq_char( ch, WEAR_EYES ) != NULL )
        learn_from_success( ch, skill_integrated_optics );

    if ( chc <= 0 && number_range( 1, 100 ) > 20 && get_eq_char( ch, WEAR_EYES ) != NULL )
    {
        ch_println( ch, "&OYour goggles worsen your fighting ability!" );
        dam /= 4;
    }

    // reduce damage if we are flying and wearing a jetpack (based on skill)
    device = get_eq_char( ch, WEAR_BACK );

    if ( device != NULL && device->item_type == ITEM_JETPACK && IS_AFFECTED( ch, AFF_FLYING ) && !IS_AFFECTED( victim, AFF_FLYING ) )
    {
        // now let's see if we do damage reduction..
        cache_skill( "jetpack mastery", &skill_jetpack_mastery );
        chc = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 0 : ( int ) get_learned_pct( ch, skill_jetpack_mastery );
        chc -= number_percent();
        chc += get_curr_int( ch );

        if ( chc > 0 )
        {
            learn_from_success( ch, skill_jetpack_mastery );
        }
        else
        {
            learn_from_failure( ch, skill_jetpack_mastery );
            dam /= 4;

            if ( number_range( 1, 6 ) > 5 ) // 1/3 chance
                ch_println( ch, "&RYour ability to fight is worsened because you are flying." );
        }
    }

    // Do not want to have damage less than zero
    if ( dam <= 0 )
        dam = number_range( 1, 3 );

    /* immune to damage */
    if ( dam == -1 )
    {
        if ( dt >= 0 )
        {
            SKILL_DATA* skill = skill_from_id( dt );
            bool found = FALSE;

            if ( skill )
            {
                if ( skill->imm_char && skill->imm_char[0] != '\0' )
                {
                    act( AT_HIT, skill->imm_char, ch, NULL, victim, TO_CHAR );
                    found = TRUE;
                }

                if ( skill->imm_vict && skill->imm_vict[0] != '\0' )
                {
                    act( AT_HITME, skill->imm_vict, ch, NULL, victim, TO_VICT );
                    found = TRUE;
                }

                if ( skill->imm_room && skill->imm_room[0] != '\0' )
                {
                    act( AT_ACTION, skill->imm_room, ch, NULL, victim, TO_NOTVICT );
                    found = TRUE;
                }
            }

            if ( found )
                return rNONE;
        }

        dam = 0;
    }

    /* Ranged weapons "bonus" */
    if ( wep )
    {
        if ( wield->value[3] == WEAPON_BLASTER )
            dam *= 3;

        if ( wield->value[3] == WEAPON_BOWCASTER )
            //dam *= 7; //More damage to bowcasters, suitable for a weapon of high str and non-dual. Lydor '08.
            dam *= 4; //No, * 7 is retarded. Ralen.
    }

    /*
        Deal the damage
    */

    if ( check_parry( ch, victim, dam, wield ) )
    {
        if ( who_fighting( ch ) == NULL )
            dam = 0;
        else
            return rNONE;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        dam /= 4; // Dropped from /= 5 to speed things up in PVP
    else
        dam /= 4;

    /*  if ( ( obj2 = get_eq_char(victim, WEAR_WIELD) ) != NULL )
        {
        if ( obj2->value[3] == WEAPON_BLASTER || obj2->value[3] == WEAPON_BOWCASTER )
        {
            if ( wield )
            {
                if ( wield->value[3] != WEAPON_BLASTER && wield->value[3] != WEAPON_BOWCASTER)
                {
                    dam *= 2;
                    if ( wield && ( !IS_NPC(ch) && !IS_SWITCHED_NPC(ch) ) && dam > 1000)
                    bug("Multiplied damage for hth vs ranged" );
                }
            }
        }
        }
    */
    /*    if ( wield && (( !IS_NPC(ch) && !IS_SWITCHED_NPC(ch) ) ) && (( !IS_NPC( victim) && !IS_SWITCHED_NPC( victim) ) ) && dam > 1000)
            bug("Total damage for hit: %s hitting %s (%d)", ch->name, victim->name, dam);*/
    if ( wield )
    {
        switch ( wield->value[3] )
        {
            case WEAPON_BLASTER:
            case WEAPON_BOWCASTER:
                if ( xIS_SET( victim->immune, RIS_ENERGY ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ) // Intended for mobs, not players to utilize. Gathorn 16 April 2017
                {
                    dam = 0;
                    act( AT_ACTION, "&RYou shrug off the energy attack.&w", victim, NULL, ch, TO_CHAR ); //Broadcasting to the mob in the event builders want to do a prog off of it.
                    act( AT_ACTION, "&RYour energy attack does not seem to faze $N&R!&w", ch, NULL, victim, TO_CHAR );
                    act( AT_ACTION, "&R$N&R seems unfazed by the energy attack from $n's&R weapon.&w", ch, NULL, victim, TO_NOTVICT );
                }

                if ( xIS_SET( victim->resistant, RIS_ENERGY ) )
                    dam = number_range( dam / 3, dam / 2 );

                if ( xIS_SET( victim->susceptible, RIS_ENERGY ) )
                    dam = number_range( dam * 2, dam * 3 );

                break;

            case WEAPON_LIGHTSABER:
                if ( xIS_SET( victim->immune, RIS_SLASH ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ) // Intended for mobs, not players to utilize. Gathorn 16 April 2017
                {
                    dam = 0;
                    act( AT_ACTION, "&REnergy crackles and sparks against your defenses.&w", victim, NULL, ch, TO_CHAR ); //Broadcasting to the mob in the event builders want to do a prog off of it.
                    act( AT_ACTION, "&RYour lightsaber appears to have no effect against $N!&w", ch, NULL, victim, TO_CHAR );
                    act( AT_ACTION, "&R$N's&R defenses crackle and spark with energy against $n's weapon.&w", ch, NULL, victim, TO_NOTVICT );
                }

                if ( xIS_SET( victim->resistant, RIS_SLASH ) )
                    dam = ( dam * 70 ) / 100;

                if ( xIS_SET( victim->susceptible, RIS_SLASH ) )
                    dam = number_range( dam * 2, dam * 3 );

                break;

            case WEAPON_VIBRO_BLADE:
            case WEAPON_FORCE_PIKE:
            case WEAPON_VIBRO_AXE:
                if ( xIS_SET( victim->immune, RIS_PIERCE ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ) // Intended for mobs, not players to utilize. Gathorn 16 April 2017
                {
                    dam = 0;
                    act( AT_ACTION, "&R$n's weapon hits you, but is unable to pierce your defenses.&w", victim, NULL, ch, TO_CHAR ); //Broadcasting to the mob in the event builders want to do a prog off of it.
                    act( AT_ACTION, "&RYour weapon slides off of $N&R without leaving a mark!&w", ch, NULL, victim, TO_CHAR );
                    act( AT_ACTION, "&R$N&R shrugs off the blade of $n's weapon!&w", ch, NULL, victim, TO_NOTVICT );
                }

                if ( xIS_SET( victim->resistant, RIS_PIERCE ) )
                    dam = number_range( dam / 3, dam / 2 );

                if ( xIS_SET( victim->susceptible, RIS_PIERCE ) )
                    dam = number_range( dam * 2, dam * 3 );

                break;

            default:
                break;
        }
    }

    //dewclaws act like vibroblades
    if ( wielding_claws( ch ) )
    {
        if ( xIS_SET( victim->resistant, RIS_PIERCE ) )
            dam = number_range( dam / 3, dam / 2 );

        if ( xIS_SET( victim->susceptible, RIS_PIERCE ) )
            dam = number_range( dam * 2, dam * 3 );
    }
    else if ( !wield )
    {
        if ( xIS_SET( victim->immune, RIS_BLUNT ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ) // Intended for mobs, not players to utilize. Gathorn 19 Jan 2019
        {
            dam = 0;
            act( AT_ACTION, "&R$n's fist collides into you, but you just shrug it off.&w", victim, NULL, ch, TO_CHAR ); //Broadcasting to the mob in the event builders want to do a prog off of it.
            act( AT_ACTION, "&RThe impact from your fist appears to leave $N&R unfazed!&w", ch, NULL, victim, TO_CHAR );
            act( AT_ACTION, "&R$N&R appears unfazed by $n's punch!&w", ch, NULL, victim, TO_NOTVICT );
        }

        if ( xIS_SET( victim->resistant, RIS_BLUNT ) )
            dam = number_range( dam / 3, dam / 2 );

        if ( xIS_SET( victim->susceptible, RIS_BLUNT ) )
            dam = number_range( dam * 2, dam * 3 );
    }

    /* Cap it off */
    /* weapon specific caps */

    //Sintaka - damcap lowered on repeaters due to testing with Gathorn, high attack numbers led to this remedy
    cache_skill( "snipe", &skill_snipe );
    if ( wield && wield->value[3] == WEAPON_BLASTER && xIS_SET( wield->extra_flags, ITEM_REPEATER ) && ( !skill_snipe || dt != skill_snipe->id ) )
    {
        if ( dam > 500 )
            tune( "dam_cap: type %d by %s to %s: %d > 500", dt, ch->name, victim->name, dam );
    }

    if ( ( wield && wield->value[3] == WEAPON_BLASTER ) && ( !skill_snipe || dt != skill_snipe->id ) )
    {
        if ( dam > 600 )
            tune( "dam_cap: type %d by %s to %s: %d > 600", dt, ch->name, victim->name, dam );
    }

    if ( wield && wield->value[3] == WEAPON_BOWCASTER )
    {
        if ( dam > 700 )
            tune( "dam_cap: type %d by %s to %s: %d > 700", dt, ch->name, victim->name, dam );
    }

    if ( dam > 900 )
        tune( "dam_cap: type %d by %s to %s: %d > 900", dt, ch->name, victim->name, dam );

    if ( twinblade )
        dam *= 2;

    /* Shield bonus, woot eh? */
    if ( get_eq_char( victim, WEAR_SHIELD ) != NULL && wield && wield->value[3] == WEAPON_BLASTER )
    {
        OBJ_DATA* tobj = get_eq_char( victim, WEAR_SHIELD );

        if ( tobj->item_type == ITEM_SHIELD && tobj->value[4] > 0 && tobj->value[3] != 0 )
        {
            tobj->value[4] = URANGE( 0, tobj->value[4] - dam, tobj->value[4] );
            act( AT_ACTION, "$n's energy shield shines brightly!", victim, NULL, NULL, TO_ROOM );
            act( AT_ACTION, "Your energy shield flares as it intercepts a blaster bolt.", victim, NULL, NULL, TO_CHAR );

            if ( tobj->value[4] == 0 )
            {
                ch_println( victim, "&CYour energy shield fizzles and dies!&w" );
                act( AT_ACTION, "&C$n's energy shield fails!&w", victim, NULL, NULL, TO_ROOM );
                tobj->value[3] = 0;
            }

            dam = 0;
        }
    }

    /* Ralen - Bowcaster Shield bonus, mostly ripped from above. 10% chance to deflect, 90% chance to 1/2 damage. */
    if ( get_eq_char( victim, WEAR_SHIELD ) != NULL && wield && wield->value[3] == WEAPON_BOWCASTER )
    {
        OBJ_DATA* tobj = get_eq_char( victim, WEAR_SHIELD );

        if ( tobj->item_type == ITEM_SHIELD && tobj->value[4] > 0 && tobj->value[3] != 0 )
        {
            if ( number_range( 1, 10 ) == 5 ) /*Ralen '13 - let's give shields a straight 10% chance to block these bolts. */
            {
                tobj->value[4] = URANGE( 0, tobj->value[4] - dam, tobj->value[4] );
                act( AT_ACTION, "&C$n's shield shines brightly as it deflects an energy bolt!&w", victim, NULL, NULL, TO_ROOM );
                act( AT_ACTION, "&CYour energy shield flares brightly as it deflects a bowcaster bolt!&w", victim, NULL, NULL, TO_CHAR );
                dam = 0;
            }
            else /*Ralen '13 - And the rest of the time, punch through to do 1/2 damage. */
            {
                tobj->value[4] = URANGE( 0, tobj->value[4] - dam, tobj->value[4] );
                act( AT_ACTION, "&G$n's energy shield ripples as a bowcaster bolt punches through!&w", victim, NULL, NULL, TO_ROOM );
                act( AT_ACTION, "&GA bowcaster bolt punches through your shield!&w", victim, NULL, NULL, TO_CHAR );
                dam /= 2;
            }

            if ( tobj->value[4] == 0 )
            {
                ch_println( victim, "&CYour energy shield fizzles and dies!&w" );
                act( AT_ACTION, "&C$n's energy shield fails!&w", victim, NULL, NULL, TO_ROOM );
                tobj->value[3] = 0;
            }
        }
    }

    if ( dam > 0 && handwound( ch ) )
    {
        dam /= ( int )handwound_count( ch ) + 1;
        ch_println( ch, "&RDue to your injur%s, your damage is divided by %d!", handwound_count( ch ) == 1 ? "y" : "ies", handwound_count( ch ) + 1 );
    }

    if ( ( retcode = damage( ch, victim, dam, dt ) ) != rNONE )
        return retcode;

    if ( char_extracted( ch ) )
        return rCHAR_DIED;

    if ( char_extracted( victim ) )
        return rVICT_DIED;

    retcode = rNONE;

    if ( dam == 0 )
        return retcode;

    /*
        Weapon spell support            -Thoric
        Each successful hit casts a spell
    */
    if ( wield && !xIS_SET( victim->immune, RIS_MAGIC ) && !xIS_SET( victim->in_room->flags, ROOM_NO_MAGIC ) )
    {
        AFFECT_DATA* aff;

        for ( aff = wield->pIndexData->first_affect; aff; aff = aff->next )
        {
            if ( ( skill = skill_from_id( aff->modifier ) ) == NULL )
                continue;

            if ( aff->location == APPLY_WEAPONSPELL && IS_VALID_SN( aff->modifier ) && skill->spell_fun )
                retcode = ( *skill->spell_fun ) ( skill_from_id( aff->modifier ), ( wield->level + 3 ) / 3, ch );
        }

        if ( retcode == rSPELL_FAILED )
            retcode = rNONE; // Luc, 6/11/2007

        if ( retcode != rNONE || !ch || !victim || char_extracted( ch ) || char_extracted( victim ) )
            return retcode;

        for ( aff = wield->first_affect; aff; aff = aff->next )
        {
            if ( ( skill = skill_from_id( aff->modifier ) ) == NULL )
                continue;

            if ( aff->location == APPLY_WEAPONSPELL && IS_VALID_SN( aff->modifier ) && skill->spell_fun )
                retcode = ( *skill->spell_fun ) ( skill_from_id( aff->modifier ), ( wield->level + 3 ) / 3, ch );
        }

        if ( retcode == rSPELL_FAILED )
            retcode = rNONE; // Luc, 6/11/2007

        if ( retcode != rNONE || !ch || !victim || char_extracted( ch ) || char_extracted( victim ) )
            return retcode;
    }

    if ( retcode != rNONE || !ch || !victim || char_extracted( ch ) || char_extracted( victim ) )
        return retcode;

    tail_chain( );
    return retcode;
}

/*
    Calculate damage based on resistances, immunities and susceptibilities
                    -Thoric
*/
sh_int ris_damage( CHAR_DATA* ch, sh_int dam, int ris )
{
    sh_int modifier;
    modifier = 10;

    if ( xIS_SET( ch->immune, ris ) )
        modifier -= 10;

    if ( xIS_SET( ch->resistant, ris ) )
        modifier -= 2;

    if ( xIS_SET( ch->susceptible, ris ) )
        modifier += 2;

    if ( modifier <= 0 )
        return -1;

    if ( modifier == 10 )
        return dam;

    return ( dam * modifier ) / 10;
}


/*
    Inflict damage from a hit.
    Modified to fit LOTJ Standards.  -Ghost
*/
ch_ret damage( CHAR_DATA* ch, CHAR_DATA* victim, int dam, int dt )
{
    char buf1[MSL];
    sh_int dameq;
    bool npcvict = FALSE;
    bool loot = FALSE;
    OBJ_DATA* damobj = NULL, *wield = NULL;
    ch_ret retcode = rNONE;
    sh_int dampmod = 0;
    SKILL_DATA* skill = NULL;
    bool vicdisrupt = FALSE;
    OBJ_DATA* obj = NULL;
    bool ranged;
    //    char filename[MIL];
    //   char logperson[MSL];
    //   char *strtime;
    //    CHAR_DATA *gch = NULL;
    int init_gold = 0, new_gold = 0, gold_diff = 0;
    TIMER* timer;
    retcode = rNONE;
    int original_hp = 0;

    if ( !ch )
    {
        debug( "Damage: null ch!", 0 );
        return rERROR;
    }

    if ( char_extracted( ch ) )
    {
        debug( "Damage: ch %s (%d) died!", ( ch && ( ch->name || ch->short_descr ) ) ? ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) ? ch->name : ch->short_descr ) : "NULL", (ch && ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ch->pIndexData) ? ch->pIndexData->vnum : 0 );
        return rERROR;
    }

    if ( !victim )
    {
        debug( "Damage: null victim!", 0 );
        return rVICT_DIED;
    }

    if ( char_extracted( victim ) )
    {
        debug( "Damage: victim already died!", 0 );
        return rVICT_DIED;
    }

    if ( ch->spirit || victim->spirit )
        return rNONE;

    if ( victim->position == POS_DEAD )
        return rVICT_DIED;

    if ( is_safe( ch, victim ) )
        return rNONE;

    if ( IS_AFFECTED( ch, AFF_CALM ) )
    {
        act( AT_MAGIC, "You're too calm to do that.", ch, NULL, NULL, TO_CHAR );
        return rNONE;
    }

    // No longer get rescue protection
    remove_timer( ch, TIMER_RESCUED );

    if ( IS_AFFECTED( victim, AFF_CALM ) )
    {
        act( AT_YELLOW, "The assault shakes you out of your calmness.", victim, NULL, NULL, TO_CHAR );
        cache_skill( "calm", &skill_calm );
        affect_strip( victim, CHAR_AFFECT, skill_calm );
    }

    if(ch != victim) // self damage is not really damage given
        add_to_counter( &ch->metrics, "damage_given", dam, FLAG_AUTO_GAUGE );

    original_hp = victim->hit;

    npcvict = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) );
    vicdisrupt = victim->disruption; /* Store disrupted flag */
    victim->disruption = FALSE;

    if ( IS_AFFECTED( victim, AFF_BLOODBATH ) )
        dam += ( int )( 4 * ( dam / 10 ) );

    ranged = TRUE;

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL || ( obj->value[3] != WEAPON_BLASTER && obj->value[3] != WEAPON_BOWCASTER ) || wielding_claws( ch ) )
        if ( ( obj = get_eq_char( ch, WEAR_DUAL_WIELD ) ) == NULL || ( obj->value[3] != WEAPON_BLASTER && obj->value[3] != WEAPON_BOWCASTER ) || wielding_claws( ch ) )
            ranged = FALSE;

    // Only standard hits are eligible for most damage bonuses, not spells.
    if ( dt >= TYPE_HIT && dt < TYPE_HERB )
    {
        //JEDI_GUARDIANS/SITH_JUGGERNAUT of rank Knight or above receive a 10% damage boost when attacking with a lightsaber due to Jan 2017 subclass upgrade. - Gathorn 28Jan2017
        if ( ( IS_GUARDIAN( ch ) || IS_JUGGERNAUT( ch ) ) && ch->pcdata->frank >= FRANK_KNIGHT && ( obj = get_eq_char( ch, WEAR_WIELD ) ) != NULL && obj->item_type == ITEM_WEAPON && obj->value[3] == WEAPON_LIGHTSABER )
        {
            int modifier = dam / 10;
            dam += modifier;
            tune( "one_hit: %s damage against %s received jedi_guardian lightsaber damage bonus of %d.", ch->name, victim->name, modifier );
        }

        // Sith get +20% damage for hits when using non-ranged weapons if affected by carnage
        if ( ( !ranged ) && IS_AFFECTED( ch, AFF_CARNAGE ) )
            dam += ( int )( 2 * ( dam / 10 ) );

        if ( IS_AFFECTED( ch, AFF_ADRENAL_STIM ) )
            dam += dam / 10;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && has_pcflag( ch, PCFLAG_CHILD ) )
        dam = ( int )( dam * 0.3 );

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_CHILD ) )
        dam = ( int )( dam * 2.5 );

    /*
        Check damage types for RIS               -Thoric
    */
    if ( dam && dt != TYPE_UNDEFINED )
    {
        if ( dam == -1 )
        {
            if ( dt >= 0 )
            {
                bool found = FALSE;
                SKILL_DATA* skill = skill_from_id( dt );

                if ( skill )
                {
                    if ( skill->imm_char && skill->imm_char[0] != '\0' )
                    {
                        act( AT_HIT, skill->imm_char, ch, NULL, victim, TO_CHAR );
                        found = TRUE;
                    }

                    if ( skill->imm_vict && skill->imm_vict[0] != '\0' )
                    {
                        act( AT_HITME, skill->imm_vict, ch, NULL, victim, TO_VICT );
                        found = TRUE;
                    }

                    if ( skill->imm_room && skill->imm_room[0] != '\0' )
                    {
                        act( AT_ACTION, skill->imm_room, ch, NULL, victim, TO_NOTVICT );
                        found = TRUE;
                    }
                }

                if ( found )
                    return rNONE;
            }

            dam = 0;
        }
    }

    if ( dam && npcvict && ch != victim )
    {
        if ( !xIS_SET( victim->act, ACT_SENTINEL ) )
        {
            if ( victim->hunting )
            {
                if ( victim->hunting->who != ch )
                {
                    SET_STRING( victim->hunting->name, ch->name );
                    victim->hunting->who  = ch;
                }
            }
            else
                start_hunting( victim, ch );
        }

        if ( victim->hating )
        {
            if ( victim->hating->who != ch )
            {
                SET_STRING( victim->hating->name, ch->name );
                victim->hating->who  = ch;
            }
        }
        else
            start_hating( victim, ch );
    }

    if ( victim != ch )
    {
        /*
            Certain attacks are forbidden.
            Most other attacks are returned.
        */
        if ( is_safe( ch, victim ) )
        {
            return rNONE;
        }

        add_timer( victim, TIMER_RECENTFIGHT, 60, NULL, NULL, FUNC );
        add_timer( ch, TIMER_RECENTFIGHT, 60, NULL, NULL, FUNC );

        if ( victim->position > POS_STUNNED )
        {
            if ( !victim->fighting )
                set_fighting( victim, ch );

            if ( victim->fighting )
                victim->position = POS_FIGHTING;
        }

        if ( victim->position > POS_STUNNED )
        {
            if ( !ch->fighting )
                set_fighting( ch, victim );

            /*
                If victim is charmed, ch might attack victim's master.
            */
            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
                    &&   npcvict
                    &&   IS_AFFECTED( victim, AFF_CHARM )
                    &&   victim->master
                    &&   victim->master->in_room == ch->in_room
                    &&   number_bits( 3 ) == 0 )
            {
                stop_fighting( ch, FALSE );
                retcode = multi_hit( ch, victim->master, TYPE_UNDEFINED );
                return retcode;
            }
        }

        /*
            More charm stuff.
        */
        if ( is_following( victim, ch ) )
            stop_follower( victim, false );

        /*
            Inviso attacks ... not.
        */
        if ( IS_AFFECTED( ch, AFF_INVISIBLE ) )
        {
            cache_skill( "mask", &skill_mask );
            affect_strip( ch, CHAR_AFFECT, skill_mask );
            xREMOVE_BIT( ch->affected_by, AFF_INVISIBLE );
            WAIT_STATE( ch, 2 * PULSE_PER_SECOND );
            act( AT_MAGIC, "$n fades into existence.", ch, NULL, NULL, TO_ROOM );
        }

        /* Take away Hide */
        if ( IS_AFFECTED( ch, AFF_HIDE ) )
            xREMOVE_BIT( ch->affected_by, AFF_HIDE );

        // taking damage causes interruption ~Miros
        if ( ( timer = get_timerptr( victim, TIMER_DO_FUN ) ) != NULL && timer->on_damage_interrupt == true )
        {
            int retval = interrupt_ch( victim );

            if ( retval != rNONE )
                return retval;
        }

        lua_trigger_on_ch( victim, LUA_TRIGGER_CH_ON_INTERRUPT );

        if ( char_extracted( victim ) )
            return rVICT_DIED;

        if ( dt >= TYPE_HIT && ( !vicdisrupt || number_range( 1, 10 ) == 1 ) )
        {
            cache_skill( "slowdraw", &skill_slowdraw );
            if ( ( !skill_slowdraw || dt != skill_slowdraw->id ) && check_dodge( ch, victim ) )
                return rNONE;
        }

        /*
            Damage modifiers.
        */
        if ( IS_AFFECTED( victim, AFF_SANCTUARY ) || IS_AFFECTED( victim, AFF_VITALITY ) || IS_AFFECTED( victim, AFF_FURY ) )
            dam /= 2;
        else if ( IS_AFFECTED( victim, AFF_PROTECT ) )
            dam -= ( int ) ( dam / 4 );

        if ( dam < 0 )
            dam = 0;

        /*
            Check for disarm, trip, parry, and dodge.
        */
        if ( dt >= TYPE_HIT )
        {
            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
                    &&   xIS_SET( ch->attacks, DFND_DISARM )
                    &&   number_percent( ) < ch->skill_level[COMBAT_ABILITY] / 2 )
                disarm( ch, victim );

            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
                    &&   xIS_SET( ch->attacks, ATCK_TRIP )
                    &&   number_percent( ) < ch->skill_level[COMBAT_ABILITY] )
                trip( ch, victim );
        }

        /*
            Check control panel settings and modify damage
        */
        if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        {
            if ( npcvict )
                dampmod = sysdata.dam_mob_vs_mob;
            else
                dampmod = sysdata.dam_mob_vs_plr;
        }
        else
        {
            if ( npcvict )
                dampmod = sysdata.dam_plr_vs_mob;
            else
                dampmod = sysdata.dam_plr_vs_plr;
        }

        wield = get_eq_char( ch, WEAR_WIELD );
        if ( !wield ) wield = get_eq_char( ch, WEAR_DUAL_WIELD );

        if ( ( wield ) && dam > 0 && ch->aim == victim )
        {
            if ( !check_wound( ch, victim ) )
            {
                ch_println( ch, "&wYou miss the spot you are aiming for!" );
                dam = 0;
            }

            if ( ch->aim_part != 0 )
                dam /= ( int )3;
            else
                dam *= ( int )10;
        }

        /*
            Apply Victim's armor value
            Scale range: -1000 AC = 50% damage blocked
                             0 AC =  0% damage blocked
        */
        {
            int reduction = UMAX( ( ( double )dam ) * GET_AC( victim ) / ( -2000.0 ), 0 );
            tune( "apply_armor: armor of %d reducing damage to %s by %d/%d", GET_AC( victim ), victim->name, reduction, dam );
            dam -= reduction;
        }

        cache_skill( "iron wall", &skill_iron_wall );
        if ( dam > 0 && has_feat( victim, skill_iron_wall ) )
        {
            if ( number_percent() <= 5 )
            {
                ch_println( victim, "&GYou avoid taking damage!" );
                dam = 0;
            }
        }

        if ( dampmod > 0 )
            dam = ( dam * dampmod ) / 100;
    }

    /*
        Code to handle equipment getting damaged, and also support  -Thoric
        bonuses/penalties for having or not having equipment where hit
        ---Required DAM to damage a object changed from 10 to 5---  -Ghost
    */
    cache_skill( "poison", &skill_poison );
    cache_skill( "kick", &skill_kick );
    if ( dam > 5 && dt != TYPE_UNDEFINED &&
    ( ( skill = skill_poison ) == NULL || dt != skill->id ) &&
    ( ( skill = skill_kick ) == NULL || dt != skill->id ) &&
    ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        /* get a random body eq part */
        dameq  = number_range( WEAR_LIGHT, WEAR_EYES );
        damobj = get_eq_char( victim, dameq );

        if ( damobj )
        {
            if ( dam > get_obj_resistance( damobj ) )
            {
                set_cur_obj( damobj );
                damage_obj( damobj );
            }

            dam = ( int )( dam * 0.98 ); /* add a 2% bonus for having something to block the blow */
        }
        else
            dam = ( int )( dam * 1.02 ); /* add 2% penalty for bare skin! */
    }

    if ( dam > 0 && ( ch->aim != victim || ch->aim_part == 0 ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && victim->disguise )
    {
        // Disguise check
        cache_skill( "disguise", &skill_disguise );
        cache_skill( "enduring facade", &skill_enduring_facade );
        int i = ( int )( get_learned_pct( victim, skill_disguise ) );
        int disgdurability = 0;

        if ( has_feat( victim, skill_enduring_facade ) ) //If you have the enduring facade feat, the minimum damage required to knock off your disguise increases, and your disguise now only has a 5% chance to fall off in combat.
        {
            disgdurability = 200;
            i += 10;
        }

        if ( dam > disgdurability && number_range( 1, 115 ) > i ) //Damage needs a floor check to prevent dodges and misses breaking disguise.
        {
            ch_println( victim, "Due to the damage sustained you have lost your disguise!" );
            scrap_disguise( victim );
        }
    }

    if ( ch && victim && ( !skill || dt != skill->id ) )
        startFighting( ch, victim );

    /*
        Hurt the victim.
        Inform the victim of his new state.
        No more 1 shot kills. Stun first.
        -150 hps safety net.
    */

    if ( dam < 0 )
        dam = 0;

    if ( ch != victim )
        dam_message( ch, victim, dam, dt );

    if ( ( victim->hit - dam ) < -150 && victim->hit > 0 && !IS_IMMORTAL( victim ) )
    {
        char buf[MSL];
        snprintf( buf, MSL, "$n looks like $e %s pretty hurt.", victim->sex == SEX_NEUTRAL ? "are" : "is" );
        act( AT_ACTION, buf, victim, NULL, NULL, TO_ROOM );
        victim->hit = -150;
        stop_fighting( ch, TRUE );
        /*bug("stopped fighting"); */
    }
    else
        victim->hit -= dam;

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) )
            &&   victim->top_level >= LEVEL_IMMORTAL
            &&   victim->hit < 1 )
        victim->hit = 1;

    /* Make sure newbies don't die */

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && NOT_AUTHED( victim ) && victim->hit < 1 )
        victim->hit = 1;

    /*
        NODEATH Flag. Keep them just health enough to keep kicking...
        [Also causes healing under UPDATE.C]
    */

    if ( ch && ch->in_room && xIS_SET( victim->in_room->flags, ROOM_NODEATH ) && victim->hit < -400 )
    {
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        {
            victim->hit = UMAX( -400, victim->hit );
            update_pos( victim );
        }
    }

    if ( ( dam > 0 && dt > TYPE_HIT
            && !IS_AFFECTED( victim, AFF_POISON )
            &&  is_wielding_poisoned( ch )
            && !xIS_SET( victim->immune, RIS_POISON )
            && !saves_poison_death( ch->skill_level[COMBAT_ABILITY], victim ) ) )
    {
        AFFECT_DATA af;
        cache_skill( "poison", &skill_poison );
        SKILL_DATA* afskill = skill_poison;
        af.type      = afskill ? afskill->id : -1;
        af.duration  = 20;
        af.location  = APPLY_STR;
        af.modifier  = -2;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_POISON );
        affect_join( victim, CHAR_AFFECT, &af );
        // Special case: The first time someone is poisoned, they get a sudden bump in mental state.
        // Subsequent applications just add 2.
        victim->mental_state = URANGE( 20, victim->mental_state + 2, 100 );
    }

    if ( dam > 0 && dt == TYPE_HIT + WEAPON_FLAMETHROWER )
    {
        AFFECT_DATA af;
        cache_skill( "napalm", &skill_napalm );
        SKILL_DATA* afskill = skill_napalm;
        af.type      = afskill ? afskill->id : -1;
        af.duration  = URANGE( 15, number_range( dam / 4, dam / 2 ), 60 );
        af.location  = APPLY_DEX;
        af.modifier  = -4;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_NAPALM );
        affect_replace( victim, CHAR_AFFECT, &af );

        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
            ch_println( victim, "&RYou scream in agony as the searing flames engulf you!" );
    }

    if ( !npcvict
            &&   get_trust( victim ) >= LEVEL_IMMORTAL
            &&   get_trust( ch )     >= LEVEL_IMMORTAL
            &&   victim->hit < 1 )
        victim->hit = 1;

    if ( victim->hit < 0 && IS_AFFECTED( victim, AFF_SALVATION ) )
    {
        cache_skill( "salvation", &skill_salvation );
        affect_strip( victim, CHAR_AFFECT, skill_salvation );
        xREMOVE_BIT( victim->affected_by, AFF_SALVATION );
        victim->hit = number_range( 10, 40 );
        stop_fighting( victim, TRUE );
        victim->wait = 0;
        act( AT_GREEN, "Just as you are about to lose consciousness, you are healed by the Force!", victim, NULL, NULL, TO_CHAR );
        act( AT_YELLOW, "You are no longer protected.", victim, NULL, NULL, TO_CHAR );
        act( AT_GREEN, "$n is nearly brought down by the attack, but a sudden flash of light leaves $m looking better!", victim, NULL, NULL, TO_ROOM );
    }

    add_to_counter( &victim->metrics, "damage_taken", dam, FLAG_AUTO_GAUGE );
    lua_trigger_on_ch_damage( victim, ch, dam );

    if(original_hp > 0 && victim->hit <= 0)
    {
        if(lua_hook_knockout(victim->in_room, victim ))
            return rNONE;
    }

    update_pos( victim );

    switch ( victim->position )
    {
        case POS_MORTAL:
            if ( is_ai( ch, AI_POLICE ) || is_pol( ch ) )
                ai_jail( ch, victim );

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
                ai_bind( ch, victim );

            act( AT_DYING, "$n is mortally wounded, and will die soon, if not aided.\n",
                 victim, NULL, NULL, TO_ROOM );
            ch_println( victim, "&RYou are mortally wounded, and will die soon, if not aided." );
            break;

        case POS_INCAP:
            if ( is_ai( ch, AI_POLICE ) || is_pol( ch )  )
                ai_jail( ch, victim );

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
                ai_bind( ch, victim );

            act( AT_DYING, "$n is incapacitated and will slowly die, if not aided.\n",
                 victim, NULL, NULL, TO_ROOM );
            ch_println( victim, "&RYou are incapacitated and will slowly die, if not aided." );
            break;

        case POS_STUNNED:
            if ( victim->block )
            {
                act( AT_ACTION, "$n is no longer blocking a direction.", victim, NULL, NULL, TO_ROOM );
                set_char_color( AT_ACTION, victim );
                ch_println( victim, "You are no longer blocking a direction." );
                victim->block = NULL;
                action_clear_ex( victim, AS_UNLOCK );
            }

            if ( IS_AFFECTED( victim, AFF_SALVATION ) )
            {
                cache_skill( "salvation", &skill_salvation );
                affect_strip( victim, CHAR_AFFECT, skill_salvation );
                xREMOVE_BIT( victim->affected_by, AFF_SALVATION );
                ch_println( victim, "The force protects you, letting you escape being stunned!" );
                victim->hit = number_range( 10, 40 );
                update_pos( victim );
                break;
            }

            if ( is_ai( ch, AI_POLICE ) || is_pol( ch )  )
                ai_jail( ch, victim );

            if ( is_ai( ch, AI_SOLDIER_LIGHT ) )
                ai_bind( ch, victim );

            if ( !IS_AFFECTED( victim, AFF_PARALYSIS ) )
            {
                act( AT_ACTION, "$n is stunned, but will probably recover.\n",
                     victim, NULL, NULL, TO_ROOM );
                ch_println( victim, "&RYou are stunned, but will probably recover." );
            }

            if ( IS_AFFECTED( victim, AFF_FLYING ) )
                xREMOVE_BIT( victim->affected_by, AFF_FLYING );

            if ( IS_AFFECTED( victim, AFF_HIDE ) )
                xREMOVE_BIT( victim->affected_by, AFF_HIDE );

            break;

        case POS_DEAD:
            if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && ( is_ai( ch, AI_POLICE ) || is_pol( ch ) ) )
                ai_jail( ch, victim );

            if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && is_ai( ch, AI_SOLDIER_LIGHT ) )
                ai_bind( ch, victim );

            if ( dt >= 0 )
            {
                SKILL_DATA* skill = skill_from_id( dt );
                if ( skill )
                {
                    if ( skill->die_char && skill->die_char[0] != '\0' )
                        act( AT_DEAD, skill->die_char, ch, NULL, victim, TO_CHAR );

                    if ( skill->die_vict && skill->die_vict[0] != '\0' )
                        act( AT_DEAD, skill->die_vict, ch, NULL, victim, TO_VICT );

                    if ( skill->die_room && skill->die_room[0] != '\0' )
                        act( AT_DEAD, skill->die_room, ch, NULL, victim, TO_NOTVICT );
                }
            }

            if ( !xIS_SET( victim->act, ACT_QUIETDEATH ) )
            {
                if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && ( xIS_SET( victim->act, ACT_NOKILL ) || xIS_SET( victim->act, ACT_PET ) ) )
                    act( AT_YELLOW, "$n flees for $s life ... barely escaping certain death!", victim, 0, 0, TO_ROOM );
                else if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && ( xIS_SET( victim->act, ACT_DROID ) ) )
                    act( AT_DEAD, "$n EXPLODES into many small pieces!", victim, 0, 0, TO_ROOM );
                else
                    act( AT_DEAD, "$n is DEAD!", victim, 0, 0, TO_ROOM );
            }

            break;

        default:
            if ( dam > victim->max_hit / 4 )
            {
                act( AT_HURT, "That really did HURT!", victim, 0, 0, TO_CHAR );

                if ( number_bits( 3 ) == 0 )
                    worsen_mental_state( victim, 1 );
            }

            if ( victim->hit < victim->max_hit / 4 )
            {
                act( AT_DANGER, "You wish that your wounds would stop BLEEDING so much!&w",
                     victim, 0, 0, TO_CHAR );

                if ( number_bits( 2 ) == 0 )
                    worsen_mental_state( victim, 1 );
            }

            break;
    }

    /*
        Sleep spells and extremely wounded folks.
    */
    if ( !IS_AWAKE( victim )    /* lets make NPC's not slaughter PC's */
            &&   !IS_AFFECTED( victim, AFF_PARALYSIS ) )
    {
        if ( victim->fighting
                &&   victim->fighting->who->hunting
                &&   victim->fighting->who->hunting->who == victim )
            stop_hunting( victim->fighting->who );

        if ( victim->fighting
                &&   victim->fighting->who->hating
                &&   victim->fighting->who->hating->who == victim )
            stop_hating( victim->fighting->who );

        stop_fighting( victim, TRUE );
    }

    if ( victim->hit <= 0 && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        OBJ_DATA* obj;
        OBJ_DATA* obj_next;
        int cnt = 0;
        stop_fighting( victim, TRUE );

        if ( ch && ch->pcdata )
            ch->pcdata->dewclaws = FALSE;

        if ( ( obj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
            unequip_char( victim, obj );

        if ( ( obj = get_eq_char( victim, WEAR_WIELD ) ) != NULL )
            unequip_char( victim, obj );

        if ( ( obj = get_eq_char( victim, WEAR_HOLD ) ) != NULL )
            unequip_char( victim, obj );

        if ( ( obj = get_eq_char( victim, WEAR_LIGHT ) ) != NULL )
            unequip_char( victim, obj );

        OBJ_DATA* pile = NULL;

        for ( obj = victim->first_carrying; obj; obj = obj_next )
        {
            obj_next = obj->next_content;

            if ( obj->wear_loc == WEAR_NONE )
            {
                if ( !pile )
                {
                    OBJ_INDEX_DATA* blank_index = get_obj_index( OBJ_VNUM_BLANK );

                    if ( blank_index == NULL )
                    {
                        bug( "No blank object found at vnum %d, can't create equipment pile", OBJ_VNUM_BLANK );
                        break;
                    }

                    pile = create_object( blank_index, 1 );
                    pile->item_type = ITEM_CONTAINER;
                    pile->timer = 120;
                    pile->weight = 1;
                    pile->value[0] = 0;
                    pile->value[1] = 0;
                    SET_STRING( pile->name, "pile equipment" );
                    SET_STRING( pile->short_descr, "a pile of equipment" );
                    SET_STRING( pile->description, "&OA pile of someone's equipment was left here." );
                    xCLEAR_BITS( pile->extra_flags );
                    xSET_BIT( pile->extra_flags, ITEM_PERSISTENT );
                    xSET_BIT( pile->extra_flags, ITEM_INDESTRUCTIBLE );
                    xSET_BIT( pile->extra_flags, ITEM_DELETE_WHEN_EMPTY );
                    xCLEAR_BITS( pile->wear_flags );
                    obj_to_room( pile, victim->in_room );
                }

                if ( obj->pIndexData->progtypes & DROP_PROG && obj->count > 1 )
                {
                    ++cnt;
                    separate_obj( obj );
                    obj_from_char( obj );

                    if ( !obj_next )
                        obj_next = victim->first_carrying;
                }
                else
                {
                    cnt += obj->count;
                    obj_from_char( obj );
                }

                act( AT_ACTION, "$n drops $p.", victim, obj, NULL, TO_ROOM );
                act( AT_ACTION, "You drop $p.", victim, obj, NULL, TO_CHAR );
                obj = obj_to_obj( obj, pile );
            }
        }

        if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        {
            long lose_exp;
            lose_exp = UMAX( ( victim->experience[COMBAT_ABILITY] - exp_level( victim->skill_level[COMBAT_ABILITY] ) ), 0 );
            ch_println( victim, "You lose %ld experience.", lose_exp );
            victim->experience[COMBAT_ABILITY] -= lose_exp;
        }

        add_timer( victim, TIMER_RECENTPVP, 60, NULL, NULL, FUNC );
    }
    if ( victim->position == POS_DEAD &&
            ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) &&
            perming_char == NULL && perming_char != ch &&
            ch != victim )
    {
        ch_println( ch, "&RIf you want to PERM or HOSPITALIZE %s,\n you will have to type 'murder <name> perm'", g_name( victim, ch ) );
        victim->hit = -490;
        update_pos( victim );
    }

    /*
        Payoff for killing things.
    */
    if ( victim->position == POS_DEAD )
    {
        victim->disruption = vicdisrupt;   /* Bring back the disruptor flag */
        combat_group_gain( ch, victim );

        /* Autoholster at the completion of combat? */
        if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            do_holster( ch, "" );

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )  /* keep track of mob vnum killed */
        {
            add_kill( ch, victim );
            /*
                Add to kill tracker for grouped chars, as well. -Halcyon
                Uncomment this if you want to basically rape powerleveling combat

                for( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
                if( is_same_group( gch, ch ) && ( !IS_NPC( gch ) && !IS_SWITCHED_NPC( gch ) ) && gch != ch )
                  add_kill( gch, victim );
            */
        }

        check_killer( ch, victim );

        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) || !xIS_SET( victim->act, ACT_NOKILL )  )
            loot = legal_loot( ch );
        else
            loot = FALSE;

        set_cur_char( victim );
        raw_kill( ch, victim );
        victim = NULL;

        cache_skill( "snipe", &skill_snipe );
        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && loot && ( ( skill = skill_snipe ) == NULL || dt != skill->id ) )
        {
            /* Autogold by Scryn 8/12 */
            if ( has_pcflag( ch, PCFLAG_AUTOGOLD ) )
            {
                init_gold = ch->gold;
                do_get( ch, "credits corpse" );
                new_gold = ch->gold;
                gold_diff = ( new_gold - init_gold );

                if ( gold_diff > 0 )
                {
                    snprintf( buf1, MSL, "%d", gold_diff );
                    do_split( ch, buf1 );
                }
            }

            if ( has_pcflag( ch, PCFLAG_AUTOLOOT ) )
            {
                if ( vicdisrupt )
                    do_get( ch, "all ashes" );
                else
                    do_get( ch, "all corpse" );
            }
            else
            {
                if ( vicdisrupt )
                    do_look( ch, "in ashes" );
                else
                    do_look( ch, "in corpse" );
            }
        }

        if ( IS_SET( sysdata.save_flags, SV_KILL ) )
            save_char_obj( ch, true );

        return rVICT_DIED;
    }

    if ( victim == ch )
        return rNONE;

    // Disabled because it was nerfing buffers and preventing things like "aim". - Nield 05/13/2024
    // do_stop( victim, "" );

    /*
        Take care of link dead people.
    */
    if ( !npcvict && !victim->desc && !victim->switched && !char_extracted( victim ) )
    {
        if ( number_range( 0, victim->wait ) == 0 )
        {
            do_flee( victim, "" );
            do_flee( victim, "" );
            do_flee( victim, "" );
            do_flee( victim, "" );
            do_hail( victim, "hotel" );
            do_quit( victim, "" );
            return rNONE;
        }
    }

    /*
        Wimp out?
    */
    if ( npcvict && dam > 0 )
    {
        if ( ( xIS_SET( victim->act, ACT_WIMPY ) && number_bits( 1 ) == 0
                &&   victim->hit < victim->max_hit / 2 )
                ||   ( IS_AFFECTED( victim, AFF_CHARM ) && victim->master
                       &&     victim->master->in_room != victim->in_room ) )
        {
            start_fearing( victim, ch );
            stop_hunting( victim );
            interpret( victim, "flee", FALSE );
        }
    }

    if ( !npcvict
            &&   victim->hit > 0
            &&   victim->hit <= victim->wimpy
            &&   victim->wait == 0 )
        interpret( victim, "flee", FALSE );

    tail_chain( );
    return rNONE;
}

bool is_safe( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch ) 
        return TRUE;

    if ( !victim )
        return FALSE;

    TIMER* rescue_timer = get_timerptr( victim, TIMER_RESCUED );
    if ( rescue_timer &&
        ch != victim &&
        rescue_timer->buffer->target != ch &&
        same_room( victim, rescue_timer->buffer->target )
    )
    {
        act( AT_ACTION, "Your target is being protected by $N.", ch, NULL, rescue_timer->buffer->target, TO_CHAR );
        return TRUE;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        return FALSE;

    if ( get_trust( ch ) > LEVEL_HERO )
        return FALSE;

    if ( victim->position == POS_FIGHTING )
        return FALSE;

    /* kill room flags when you can */
    if ( xIS_SET( victim->in_room->flags, ROOM_SAFE )
            ||   xIS_SET( victim->act, ACT_SAFE )                )
    {
        ch_println( ch, "You can't do that to them." );
        return TRUE;
    }

    return FALSE;
}

/*
    Just verify that a corpse looting is legal
*/
bool legal_loot( CHAR_DATA* ch )
{
    /* PC's can now loot .. why not .. death is pretty final */
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
        return TRUE;

    /* non-charmed mobs can loot anything */
    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && !ch->master )
        return TRUE;

    return FALSE;
}

/*
    Edited for LOTJ, allows PK with few restrictions,
    But certain attacks still allow you a KILLER flag.
    -Ghost
*/
void check_killer( CHAR_DATA* ch, CHAR_DATA* victim )
{
    DB_DATA* wnted = NULL;

    /*
        Charm-o-rama.
    */
    if ( IS_AFFECTED( ch, AFF_CHARM ) )
    {
        if ( !ch->master )
        {
            char buf[MSL];
            snprintf( buf, MSL, "Check_killer: %s bad AFF_CHARM", ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->short_descr : ch->name );
            bug( buf, 0 );
            xREMOVE_BIT( ch->affected_by, AFF_CHARM );
            return;
        }

        if ( ch->master )
            check_killer( ch->master, victim );
    }

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
    {
        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
        {
            //for ( x = 0; x < MAX_VIP_FLAGS; x++ )
            //{
            /* Mobs with VIPs still get you wanted    -Ghost */
            /*  if ( xIS_SET(victim->vip_flags , x ) )
                {
                xSET_BIT(ch->pcdata->wanted_flags, x );
                ch_println( ch, "&YYou are now wanted on %s.&w", planet_flags[x] , victim->short_descr );
                }
                }*/
            if ( ch->in_room && ch->in_room->area && ch->in_room->area->planet && ( is_cit( victim ) || is_pol( victim ) || is_troop( victim ) || is_customs( victim ) ) && !IS_ANIMAL( victim ) )
            {
                wnted = set_wanted( ch->name, ch->in_room->area->planet->name, TRUE, CRIME_MURDER );

                if ( wnted->num1 == TRUE )
                {
                    ch_println( ch, "&YYou are now wanted for murder on %s.&w", ch->in_room->area->planet->name );
                }
            }

            if ( ch->pcdata->clan )
                ch->pcdata->clan->mkills++;

            ch->pcdata->mkills++;
            if ( ch->in_room && ch->in_room->area )
                ch->in_room->area->mkills++;
        }

        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        update_pos( victim );

        // Don't increase pkill stats if a player hospitalizes themself
        if ( victim == ch )
            return;

        ch->pcdata->pkills++;

        if ( ch->pcdata->clan )
            ch->pcdata->clan->pkills++;

        if ( victim->pcdata->clan )
            victim->pcdata->clan->pdeaths++;
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
            victim->in_room->area->mdeaths++;

    return;
}

/*
    Set position of a victim.
*/
void update_pos( CHAR_DATA* victim )
{
    if ( !victim )
    {
        bug( "update_pos: null victim", 0 );
        return;
    }

    if ( victim->position < POS_FIGHTING && victim->block )
    {
        act( AT_ACTION, "$n is no longer blocking a direction.", victim, NULL, NULL, TO_ROOM );
        set_char_color( AT_ACTION, victim );
        ch_println( victim, "You are no longer blocking a direction." );
        action_clear_ex( victim, AS_UNLOCK );
        victim->block = NULL;
    }

    if ( victim->furniture && victim->position < POS_SLEEPING )
    {
        victim->furniture->occupants--;
        victim->furniture = NULL;
    }

    if ( victim->position <= POS_STUNNED && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        victim->pcdata->dewclaws = FALSE; //dewclaws go away when stunned

    if ( victim->hit > 0 )
    {
        if ( victim->position <= POS_STUNNED && !IS_AFFECTED( victim, AFF_SLEEP ) && !IS_AFFECTED( victim, AFF_PARALYSIS )  )
            victim->position = POS_STANDING;

        if ( IS_AFFECTED( victim, AFF_PARALYSIS ) )
            victim->position = POS_STUNNED;

        return;
    }

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) || victim->hit <= -500 )
    {
        if ( victim->mount )
        {
            act( AT_ACTION, "$n falls from $N.",
                 victim, NULL, victim->mount, TO_ROOM );
            xREMOVE_BIT( victim->mount->act, ACT_MOUNTED );
            victim->mount = NULL;
        }

        victim->position = POS_DEAD;
        return;
    }

    if ( victim->hit <= -400 )
        victim->position = POS_MORTAL;
    else if ( victim->hit <= -200 )
        victim->position = POS_INCAP;
    else
        victim->position = POS_STUNNED;

    if ( victim->position > POS_STUNNED && IS_AFFECTED( victim, AFF_PARALYSIS ) )
        victim->position = POS_STUNNED;

    if ( victim->mount )
    {
        act( AT_ACTION, "$n falls unconscious from $N.", victim, NULL, victim->mount, TO_ROOM );
        xREMOVE_BIT( victim->mount->act, ACT_MOUNTED );
        victim->mount = NULL;
    }

    return;
}


/*
    Start fights.
*/
void set_fighting( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL];
    FIGHT_DATA* fight;

    if ( ch->fighting )
    {
        snprintf( buf, MSL, "Set_fighting: %s -> %s (already fighting %s)", ch->name, victim->name, ch->fighting->who->name );
        bug( buf, 0 );
        return;
    }

    if ( ch->in_room != victim->in_room )
        return;

    cache_skill( "sleep", &skill_sleep );
    if ( IS_AFFECTED( ch, AFF_SLEEP ) )
        affect_strip( ch, CHAR_AFFECT, skill_sleep );

    /* Limit attackers -Thoric */
    if ( victim->num_fighting > max_fight( ) )
    {
        ch_println( ch, "There are too many people fighting for you to join in." );
        return;
    }

    CREATE( fight, FIGHT_DATA, 1 );
    fight->who   = victim;
    fight->xp    = ( int ) xp_compute( ch, victim );
    fight->align = align_compute( ch, victim );

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        fight->timeskilled = times_killed( ch, victim );

    ch->num_fighting = 1;
    ch->fighting = fight;
    ch->position = POS_FIGHTING;
    victim->num_fighting++;

    /* Autodraw feature. Whee! */
    if ( ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || has_pcflag( ch, PCFLAG_AUTODRAW ) ) && can_unholster( ch, get_eq_char( ch, WEAR_WAIST ), true ) )
        /*       do_unholster( victim, "" );*/
        interpret( ch, "draw", FALSE );

    if ( victim->switched && IS_AFFECTED( victim->switched, AFF_POSSESS ) )
    {
        ch_println( victim->switched, "You are disturbed!" );
        do_return( victim->switched, "" );
    }

    return;
}


CHAR_DATA* who_fighting( CHAR_DATA* ch )
{
    if ( !ch )
    {
        bug( "who_fighting: null ch", 0 );
        return NULL;
    }

    if ( !ch->fighting )
        return NULL;

    return ch->fighting->who;
}

void free_fight( CHAR_DATA* ch )
{
    if ( !ch )
    {
        bug( "Free_fight: null ch!", 0 );
        return;
    }

    if ( ch->fighting )
    {
        if ( ch->fighting->who && !char_extracted( ch->fighting->who ) )
            --ch->fighting->who->num_fighting;

        DISPOSE( ch->fighting );
    }

    ch->fighting = NULL;

    if ( ch->mount )
        ch->position = POS_MOUNTED;
    else
        ch->position = POS_STANDING;

    /* Berserk wears off after combat. -- Altrag */
    if ( IS_AFFECTED( ch, AFF_BERSERK ) )
    {
        cache_skill( "berserk", &skill_berserk );
        SKILL_DATA* skill = skill_berserk;
        if ( skill )
        {
            affect_strip( ch, CHAR_AFFECT, skill );
            set_char_color( AT_WEAROFF, ch );
            send_to_char( skill->msg_off, ch );
            ch_println( ch, "" );
        }
    }

    return;
}


/*
    Stop fights.
*/
void stop_fighting( CHAR_DATA* ch, bool fBoth )
{
    CHAR_DATA* fch;
    free_fight( ch );
    update_pos( ch );

    if ( !fBoth )   /* major short cut here by Thoric */
        return;

    for ( fch = first_char; fch; fch = fch->next )
    {
        if ( who_fighting( fch ) == ch )
        {
            free_fight( fch );
            update_pos( fch );
            fch->warned = 0;
        }
    }

    return;
}

/*
    Restored Death Cry code for LOTJ
*/
void death_cry( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* was_in_room;
    char* msg;
    EXIT_DATA* pexit;

    if ( !ch )
    {
        bug( "DEATH_CRY: null ch!", 0 );
        return;
    }

    msg = NULL;

    if ( xIS_SET( ch->act, ACT_DROID ) || xIS_SET( ch->race->flags, RFLAG_DROID ) )
        switch ( number_range( 0, 5 ) )
        {
            default:
                msg  = "You hear $n's agonized screech.";
                break;

            case  0:
            case  1:
                msg  = "$n hits the ground ... BROKEN.";
                break;

            case  2:
            case  3:
                msg  = "$n splatters oil on your armor.";
                break;

            case  4:
            case  5:
                msg  = "$n crumbles to a rusted heap.";
                break;
        }
    else
        switch ( number_range( 0, 5 ) )
        {
            default:
                msg  = "You hear $n's agonized cry.";
                break;

            case  0:
            case  1:
                msg  = "$n hits the ground ... DEAD.";
                break;

            case  2:
            case  3:
                msg  = "$n splatters gore on your armor.";
                break;

            case  4:
            case  5:
                msg  = "$n crumbles to a dismembered heap.";
                break;
        }

    if ( !msg )
        msg = "You hear $n's agonized cry.";

    act( AT_CARNAGE, msg, ch, NULL, NULL, TO_ROOM );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        msg = "You hear something's agonized cry.";
    else
        msg = "You hear someone's agonized cry of death!";

    was_in_room = ch->in_room;

    for ( pexit = was_in_room->first_exit; pexit; pexit = pexit->next )
    {
        if ( pexit->to_room && pexit->to_room != was_in_room )
        {
            ch->in_room = pexit->to_room;
            act( AT_CARNAGE, msg, ch, NULL, NULL, TO_ROOM );
        }
    }

    ch->in_room = was_in_room;
    return;
}

void raw_kill_retire( CHAR_DATA* ch, CHAR_DATA* victim, bool isRetiring )
{
    char buf[MSL], arg[MSL];
    OBJ_DATA* obj = NULL, *obj_next = NULL;
    DROID_DATA* droid = NULL;
    bool cloned = FALSE;
    bool undead = FALSE;

    if ( !victim )
    {
        bug( "raw_kill: null victim!", 0 );
        return;
    }

    if ( char_extracted( victim ) )
    {
        bug( "raw_kill: victim already died!", 0 );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        if ( ( droid = droid_from_mob( victim ) ) != NULL )
        {
            droid->mob = NULL;
            victim->droid_data = NULL;
            delete_droid( droid );
        }
    }

    if ( ( obj = get_eq_char( victim, WEAR_BINDING ) ) != NULL )
    {
        separate_obj( obj );
        xCLEAR_BITS( obj->wear_flags );
        xREMOVE_BIT( obj->extra_flags, ITEM_NOREMOVE );
        xSET_BIT( obj->wear_flags, ITEM_HOLD );
        xSET_BIT( obj->wear_flags, ITEM_TAKE );
        unequip_char( victim, obj );
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        if ( victim->spirit && !isRetiring )
        {
            act( AT_ACTION, "$n blurs, fading from view!", victim, NULL, NULL, TO_ROOM );

            if ( victim->max_hit > 0 )
            {
                char_from_room( victim );
                char_to_room( victim, get_room_index( 2 ) );
                send_to_char( "You fade from the corporeal world...\n"
                              "You find yourself somewhere else.\n", victim );
                do_restore( victim, "self" );
                victim->manifest = FALSE;
                return;
            }
        }

        if ( has_pcflag( victim, PCFLAG_CG ) && ch->in_room->vnum != ROOM_CG )
        {
            DESCRIPTOR_DATA* d;
            char_from_room( victim );
            char_to_room( victim, get_room_index( ROOM_CG ) );
            ch_println( victim, "You have been killed." );
            snprintf( buf, MSL, "&z[&YCG&z] &W%s has been killed.\n", victim->name );

            for ( d = first_descriptor ; d ;  d = d->next )
            {
                if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
                    continue;

                if ( !d->character )
                    continue;

                if ( !has_pcflag( d->character, PCFLAG_CG )
                        && get_trust( d->character ) < sysdata.log_level )
                    continue;

                send_to_char( buf, d->character );
            }

            do_restore( victim, "self" );
            return;
        }

        // UFG ground combat deaths result in 12 hour lockout instead of being permed.
        if ( use_ufg_death_system( victim ) )
        {
            ch_println( victim,
                "&RThe sounds of the battle fade as the pain of your injuries overwhelmes you.\n"
                "\n"
                "&rSeconds turn to hours in your mind as your life flashes before you.\n"
                "\n"
                "&wThen, you are faintly aware of voices nearby. You feel life returning as an\n"
                "emergency bacta injection courses through you. You might pull through after all.\n"
                "\n"
                "&C(OOC) You have been defeated on a planet which is currently being contested. You\n"
                "may log back into this character in 12 hours."
            );

            act( AT_YELLOW, 
                "$n has been defeated! A team of battle medics rushes in to carry $m away.",
                victim, NULL, NULL, TO_ROOM );

            // Ensure they can call a taxi when they log back in - give them a makeshift comlink.
            OBJ_INDEX_DATA* blank_obj = get_obj_index( OBJ_VNUM_BLANK );
            if ( blank_obj )
            {
                OBJ_DATA* comlink = create_object( blank_obj, 1 );
                xREMOVE_BIT( comlink->extra_flags, ITEM_PROTOTYPE );
                comlink->item_type = ITEM_COMLINK;
                xCLEAR_BITS( comlink->wear_flags );
                xSET_BIT( comlink->wear_flags, ITEM_TAKE );
                comlink->weight = 3;
                SET_STRING( comlink->name, "emergency comlink" );
                SET_STRING( comlink->short_descr, "&Wan &Rem&Wergen&Rcy co&Wmli&Rnk" );
                SET_STRING( comlink->description, "&WAn &Rem&Wergen&Rcy co&Wmli&Rnk&W has been dropped here." );
                obj_to_char( comlink, victim );
            }

            victim->pcdata->death_recovery_time = current_time + 12 * 3600;
            save_char_obj( victim, false );
            extract_char( victim );
            return;
        }
    }

    /* Held patch */
    if ( !IS_SWITCHED_NPC( victim ) && get_trust( victim ) >= LEVEL_RPC )
    {
        act( AT_ACTION, "$n rises from $s own ashes!", victim, NULL, NULL, TO_ROOM );
        ch_println( victim, "Just as you are about to die, you realize you are eternal and cannot die." );
        do_restore( victim, "self" );
        return;
    }

    if ( victim->held )
        victim->held = FALSE;

    if ( victim->heldby )
    {
        victim->heldby->holding = NULL;
        victim->heldby = NULL;
    }

    if ( victim->carried )
    {
        victim->carried->carrying = NULL;
        victim->carried = NULL;
    }

    /*
        Carrying Patch
    */
    if ( victim->carried )
    {
        act( AT_LBLUE, "You release $N, dropping $M on the ground.", victim->carried, NULL, victim, TO_CHAR );
        act( AT_LBLUE, "$n releases $N, dropping $M on the ground..", victim->carried, NULL, victim, TO_NOTVICT );
        victim->carried->carrying = NULL;
        victim->carried = NULL;
    }

    stop_fighting( victim, TRUE );

    if ( ch != victim && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && xIS_SET( ch->race->flags, RFLAG_UNDEAD ) && !xIS_SET( victim->race->flags, RFLAG_UNDEAD ) )
    {
        undead = TRUE;
    }

    // Do we hospitalize?
    if ( ( ch != victim || !isRetiring ) && ( !victim->pcdata || !victim->pcdata->slayed ) && ch != bh_char && bh_char == NULL && !isWarring( ch, victim ) )
    {
        // if we aren't at war, send the victim to the hospital and abort death/perm
        if ( hospitalZone( victim ) && undead == FALSE )
        {
            sendToHospital( ch, victim );
            return;
        }
    }

    /*
        Ai Patch
    */
    PLANET_DATA* planet = on_planet( victim );

    if ( victim->ai_data && planet )
    {
        if ( is_ai( victim, AI_THIEF ) )
        {
            double crime_drop = 0.5;

            if ( number_range( 1, 8 ) == 1 )
            {
                ch_println( ch, "&YYou found a ringleader of the local criminal element!" );
                victim->gold += 45000;
                crime_drop += 6;
            }
            else
            {
                victim->gold += 3500;
            }

            if ( count_planet_ai( planet, AI_THIEF ) == 1 )
            {
                ch_println( ch, "&YYou have eliminated the last criminal on %s!", planet->name );
                crime_drop += 3;
            }

            affect_planet_crime( planet, ch, crime_drop * -1 );
            save_planet( planet, true );
        }

        if ( is_ai( victim, AI_CITIZEN ) )
        {
            // Murdering your own citizens doesn't increase crime, just increases military presence.
            if ( !ch->pcdata || ch->pcdata->clan != planet->governed_by )
            {
                affect_planet_crime( planet, ch, 0.5 );
            }

            if ( in_clan( ch ) )
            {
                affect_popular_opinion( ch, planet, ch->pcdata->clan, PLANET_SUPPORT_EFF_MURDER_CIT, -1 );
                affect_planet_mil_presence( ch, planet, ch->pcdata->clan, 0.25 );
            }

            planet->population = UMAX( 0, planet->population - 10 );
            save_planet( planet, true );
        }

        if ( is_ai( victim, AI_POLICE ) )
        {
            affect_planet_crime( planet, ch, 0.5 );
            affect_planet_mil_presence( ch, planet, planet->governed_by, -0.5 );
            if ( in_clan( ch ) && is_ufg( planet ) )
                affect_planet_mil_presence( ch, planet, ch->pcdata->clan, 1 );
        }

        extract_ai( victim->ai_data );
        victim->ai_data = NULL;
    }

    /*
        Vendor Patch
    */
    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
    {
        if ( victim->vendor_data )
        {
            /* Delete the Vendor Reference */
            bug( "Player vendor owned by %s was killed by %s in room %d. ", victim->vendor_data->owner, !IS_NPC( ch ) ? ch->name : ch->short_descr, victim->in_room->vnum );
            death_cry( victim );
            make_corpse( victim, ch, isRetiring );
            delete_vendor( victim->vendor_data );
            return;
        }
    }

    strlcpy( arg, victim->name, MSL );

    if ( ch && ch != NULL && ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        claim_bounties( ch, victim, true );

    if ( IS_SWITCHED_NPC( victim ) )
        do_return( victim, "" );

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) || !xIS_SET( victim->act, ACT_NOKILL  ) )
    {
        lua_trigger_on_ch_death( victim, ch );
        lua_trigger_on_ch_pcdeath( victim, ch );

        if ( ch != NULL )
            mprog_death_trigger( ch, victim );

        if ( !isRetiring )
        {
            ch_println( victim, "&WYou have been KILLED!" );
            death_cry( victim );
        }
    }

    if ( char_extracted( victim ) )
        return;

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) || !xIS_SET( victim->act, ACT_NOKILL  ) )
    {
        if ( ch != NULL )
            rprog_death_trigger( ch, victim );
    }

    if ( char_extracted( victim ) )
        return;

    do_save( victim, "-noalert" );
    if ( undead == FALSE )
    {
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !xIS_SET( ch->race->flags, RFLAG_UNDEAD ) )
        {
            char hist_buf[MIL];

            if ( isRetiring )
                snprintf( hist_buf, MIL, "Deleted" );
            else
                snprintf( hist_buf, MIL, "Killed by %s", ( ch && ch != victim ) ? ch->name : "(unknown)" );

            account_add_to_history( victim, victim->desc ? victim->desc->account : (victim->pcdata ? victim->pcdata->account : NULL), hist_buf );
            if ( !isRetiring )
            {
                if ( has_cyber_flag( victim, CYBER_RADAR ) && victim->pcdata->clan )
                {
                    char buf[MSL];
                    CHAR_DATA* wch;

                    if ( get_ship_from_room( victim->in_room ) )
                        snprintf( buf, MSL, "&R[LIFE RADAR ALERT]: &W%s has been killed on ship %s.\n", victim->name, get_ship_from_room( victim->in_room )->name );
                    else
                        snprintf( buf, MSL, "&R[LIFE RADAR ALERT]: &W%s has been killed on %s.\n", victim->name, on_planet( victim )->name );

                    for ( wch = first_char; wch; wch = wch->next )
                        if ( ( !IS_NPC( wch ) && !IS_SWITCHED_NPC( wch ) ) && wch->pcdata->clan && wch->pcdata->clan == victim->pcdata->clan )
                            send_to_char( buf, wch );
                }

                snprintf( log_buf, MSL, "%s killed by %s at %d", victim->name, (ch ? ch->name : "(unknown)" ), victim->in_room->vnum );
                log_string( log_buf );
                int rval;
                if ( ( rval = to_ooc_talk_channel( NULL, NULL, NULL, sysdata.rpc_sees_deaths ? CHANNEL_COUNCIL : CHANNEL_IMMTALK, log_buf, RAW_OUTPUT)) != E_LOTJ_SUCCESS ) {
                    lognormal( "Failed to send death notification to channel with error: %s", lotj_strerror(rval) );
                }
            }
        }
    }

    if ( !undead && !victim->spirit )
    {
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) || ( !xIS_SET( victim->act, ACT_NOKILL ) && !xIS_SET( victim->act, ACT_NOCORPSE ) ) )
            make_corpse( victim, ch, isRetiring );
        else
        {
            for ( obj = victim->last_carrying; obj; obj = obj_next )
            {
                obj_next = obj->prev_content;
                obj_from_char( obj );
                extract_obj( obj );
            }
        }
    }

    /*
        Leaves pools of blood when a victim dies...
    */
    /* make_blood( victim ); */

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
    {
        victim->pIndexData->killed++;
        extract_char( victim );
        victim = NULL;
        return;
    }

    if ( undead == FALSE && isRetiring == FALSE )
    {
        set_char_color( AT_DIEMSG, victim );
        do_help( victim, "_DIEMSG_" );
    }
    else if ( undead == TRUE && isRetiring == FALSE )
    {
        do_help( victim, "_UNDEADVICTMESSAGE_" );
        ch_println( victim, "&YYou may log back in your new undead warrior (with the same name) in %d minutes.", sysdata.undeadtimeout / 60 );
        //return;
    }
    else
    {
        ch_println( ch, "\n&z(&CC&z)haracter deleted.&w" );
    }

    if ( victim->pcdata->last_clone > 0 && undead == FALSE )
        cloned = TRUE;

    if ( victim->pcdata )
    {
        add_death( victim, ch );
        ACCOUNT_DATA* accrem = NULL;
        if ( undead == FALSE )
        {
            accrem = account_get_from_char( victim->name );

            if ( !accrem && victim->desc && victim->desc->account )
                accrem = victim->desc->account;

            if ( !accrem && victim->pcdata && victim->pcdata->account )
                accrem = victim->pcdata->account;

            if ( accrem && victim->pcdata->last_clone < 1 ) {
                account_rem_char( victim, accrem );

                if (victim->desc)
                    victim->desc->account = NULL; //fix a bug where chars got added back to account on deletion due to account_update check

                if ( victim->pcdata )
                    victim->pcdata->account = NULL;
            }
        }

        bump_descriptor( victim->desc, victim->name );


        if ( victim->pcdata->last_clone < 1 || undead == TRUE )
        {
            death_reward( victim, accrem );
            /* Cleanup vendors */
            victim->race->race_count--;
            clear_wanted( victim->name );
            save_race( victim->race );

            DROID_DATA* droid = droid_from_controller( victim->id );
            CHAR_DATA* droid_mob = mob_from_droid( droid );

            // Unassign clan droids from dead characters. - Nield
            if ( droid && droid->clan_owned )
            {
                droid->controller = 0;
                droid->active = 3;
                save_droid( droid, TRUE );
            }

            if ( droid_mob )
                do_follow( droid_mob, "self" );
            else
                delete_droid( droid );

            FORCER_DATA* forcer = NULL;

            if ( sysdata.ruleoftwo == TRUE && !str_cmp( sysdata.sithlord, victim->name ) && !str_cmp( sysdata.sithapprentice, ch->name ) )
                //if ( has_pcflag( ch, PCFLAG_SITHAPPRENTICE ) && victim->pcdata->fclass == SITH_DARKLORD )
            {
                ch_println( victim, "Upon your death, your apprentice ascends to the rank of master and dark lord..." );
                ch_println( ch, "Upon defeating your former master, you ascend to the rank of Dark Lord of the Sith." );
                ch->pcdata->frank = FRANK_MASTER;
                ch->pcdata->fclass = SITH_DARKLORD;
                //remove_pcflag( ch, PCFLAG_SITHAPPRENTICE );
                SET_STRING( sysdata.sithlord, ch->name );
                forcer = forcer_create( ch );
            }

            if ( sysdata.ruleoftwo == TRUE && str_cmp( sysdata.sithapprentice, ch->name ) && !str_cmp( sysdata.sithlord, victim->name ) )
            {
                ch_println( victim, "Upon your death, your apprentice ascends to the rank of master and dark lord..." );
                SET_STRING( sysdata.sithlord, sysdata.sithapprentice );
                SET_STRING( sysdata.sithapprentice, NULL );
            }

            if ( !str_cmp( sysdata.sithapprentice, victim->name ) )
            {
                SET_STRING( sysdata.sithapprentice, NULL );
            }

            if ( undead == FALSE && victim->skill_level[FORCE_ABILITY] >= 20 && !victim->spirit )
            {
                /* exit early */
                if ( number_percent () < ( int ) victim->skill_level[FORCE_ABILITY] )
                {
                    victim = make_force_ghost( victim );

                    //Ralen - PLACEHOLDER REMINDER. Further changes to be made in separate branch.
                    //Making the victim a force ghost AFTER account disconnection means the first thing a new
                    //ghost has to do is reconnect to their account. Not very epic!
                    //act(AT_LBLUE, "$n's body disappears, their equipment falling to the ground.", victim, NULL, NULL, TO_ROOM);
                    if ( victim->spirit )
                        return;
                }
            }

            if ( undead == FALSE && ( victim->skill_level[FORCE_ABILITY] >= 2 || victim->perm_frc > 0 ) )
            {
                forcer = NULL;
                forcer = forcer_create( victim );

                if ( victim->skill_level[FORCE_ABILITY] == 1 && victim->perm_frc > 0 && victim->perm_frc > victim->race->frc_plus && victim->pcdata->awakened_at <= 0 )
                {
                    snprintf( buf, MSL, "%s %s (%s) natrolled force and died without having it awakened.", lulz_lines[number_range( 0, 9 )],
                    victim->name, accrem ? accrem->name : "no account" );
                    write_to_log( "natroll_lulz", buf, sysdata.log_level, 720, true );
                }

                if ( forcer )
                    forcer_delete( forcer );
            }

            if ( victim && victim->pcdata && victim->pcdata->clan )
                remove_from_clan( victim );

            victim->living = FALSE;
            save_player( victim, false );
        }
    }

    if ( undead == TRUE )
    {
        makeUndead( victim );
        // return;
    }

    if ( !victim )
    {
        DESCRIPTOR_DATA* d;

        /* Make sure they aren't halfway logged in. */
        for ( d = first_descriptor; d; d = d->next )
            if ( ( victim = d->character ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) )  )
                break;

        if ( d )
            close_socket( d, TRUE );
    }
    else
        extract_char( victim );

    if ( undead == TRUE )
        return;

    // NIELD NOTE: ADD CLONE LOGIC HERE

    if ( !is_reserved_name( victim->name ) && !cloned )
        add_reserved( victim->name, "death" );

    return;
}

void combat_group_gain( CHAR_DATA* ch, CHAR_DATA* victim )
{
    char buf[MSL];
    CHAR_DATA* gch;
    CHAR_DATA* lch;
    int xp;
    int members;

    /*
        Monsters don't get kill xp's or alignment changes.
        Dying of mortal wounds or poison doesn't give xp to anyone!
    */
    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || victim == ch )
        return;

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        shift_points( ch, -40 );
        return;
    }

    members = 0;

    for ( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
    {
        if ( is_same_group( gch, ch ) )
            members++;
    }

    if ( members == 0 )
    {
        bug( "Combat_group_gain: members.", members );
        members = 1;
    }

    lch = ch->leader ? ch->leader : ch;

    for ( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
    {
        OBJ_DATA* obj;
        OBJ_DATA* obj_next;

        if ( !is_same_group( gch, ch ) )
            continue;

        xp = ( int ) ( xp_compute( gch, victim ) / members );
        xp = apply_xp_sink( gch, xp, COMBAT_ABILITY );

        /*gch->alignment = align_compute( gch, victim );*/
        if ( gch->position <= POS_SLEEPING )
            continue;

        if ( ( !IS_NPC( gch ) && !IS_SWITCHED_NPC( gch ) ) && ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && gch->pcdata && gch->pcdata->clan
                && !str_cmp ( gch->pcdata->clan->name, victim->mob_clan ) )
        {
            xp = 0;
            snprintf( buf, MSL, "You receive no experience for killing your organization's resources.\n" );
            send_to_char( buf, gch );
        }
        else
        {
            snprintf( buf, MSL, "You receive %d combat experience.\n", xp );
            send_to_char( buf, gch );
        }

        gain_exp( gch, xp, COMBAT_ABILITY, FALSE );

        if ( lch == gch && members > 1 )
        {
            xp = URANGE( members, xp * members, ( exp_level( gch->skill_level[LEADERSHIP_ABILITY] + 1 ) - exp_level( gch->skill_level[LEADERSHIP_ABILITY] ) / 10 ) );
            xp = URANGE( 0, xp, exp_level( ch->skill_level[LEADERSHIP_ABILITY] + 1 ) );
            xp = apply_xp_sink( gch, xp, LEADERSHIP_ABILITY );
            //    xp  = (int)(xp/4);
            snprintf( buf, MSL, "You get %d leadership experience for leading your group to victory.\n", xp );
            send_to_char( buf, gch );
            gain_exp( gch, xp, LEADERSHIP_ABILITY, FALSE );
        }

        for ( obj = ch->first_carrying; obj; obj = obj_next )
        {
            obj_next = obj->next_content;

            if ( obj->wear_loc == WEAR_NONE )
                continue;

            if ( ( IS_OBJ_STAT( obj, ITEM_ANTI_EVIL )    && IS_EVIL( ch )    )
                    ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_GOOD )    && IS_GOOD( ch )    )
                    ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_NEUTRAL ) && IS_NEUTRAL( ch ) )
                    ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_JEDI ) && IS_JEDI( ch ) )
                    ||   ( IS_OBJ_STAT( obj, ITEM_ANTI_SITH ) && IS_SITH( ch ) ) )
            {
                act( AT_MAGIC, "You are zapped by $p.", ch, obj, NULL, TO_CHAR );
                act( AT_MAGIC, "$n is zapped by $p.",   ch, obj, NULL, TO_ROOM );
                obj_from_char( obj );
                obj = obj_to_room( obj, ch->in_room );
                oprog_zap_trigger( ch, obj ); /* mudprogs */

                if ( char_extracted( ch ) )
                    return;
            }
        }
    }

    return;
}


int align_compute( CHAR_DATA* gch, CHAR_DATA* victim )
{
    /* New alignment system --- Offline for a while */
    /* return URANGE ( -1000, (int) ( gch->alignment - ( 180 + victim->alignment/5 ) ), 1000 ); */
    return URANGE ( -1000, ( int ) ( gch->alignment - victim->alignment / 5 ), 1000 );
}


/*
    Calculate how much XP gch should gain for killing victim
    Lots of redesigning for new exp system by Thoric
*/
int xp_compute( CHAR_DATA* gch, CHAR_DATA* victim )
{
    int effective_level = victim->skill_level[COMBAT_ABILITY];

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && victim->pIndexData->difficulty > 10 )
    {
        // Allow high difficulty mobs to give more xp than a level 100 mob, since they're made tougher than that.
        // This kicks in at difficulty 11, so that's 100, 12 is 110, etc, up to 190 for difficulty 20 (big boss mobs)
        effective_level = ( victim->pIndexData->difficulty - 1 ) * 10;
    }

    // Start at the xp-per-level of the mob's level
    int level_based_exp = exp_level( effective_level ) - exp_level( effective_level - 1 );
    // Divide by 2, it should take 2 mobs at your level to gain a level
    int xp = level_based_exp / 2;
    // If the player's level is higher than the mob's effective level, reduce it by an appropriate amount
    // (for example, killing a level 100 mob at level 150 will get you 25% xp)
    int level_deficit = gch->skill_level[COMBAT_ABILITY] - effective_level;

    if ( level_deficit > 0 )
        xp = xp * ( effective_level - level_deficit * 1.5 ) / effective_level;

    xp = URANGE( MIN_EXP_WORTH, xp, MAX_EXP_WORTH );
    /* new xp cap for swreality */
    return URANGE( 1, xp, ( exp_level(  gch->skill_level[COMBAT_ABILITY] + 1 ) - exp_level( gch->skill_level[COMBAT_ABILITY] ) )   );
}

