/*
    Revamped by Thoric to be more realistic
*/
void dam_message( CHAR_DATA* ch, CHAR_DATA* victim, int dam, int dt )
{
    char buf[256], buf1[256], buf2[256], buf3[256];
    const char* vs;
    const char* vp;
    const char* attack;
    int dampc;
    SKILL_DATA* skill = NULL, *snipe = NULL;

    if ( ! dam )
        dampc = 0;
    else
        dampc = ( ( dam * 1000 ) / victim->max_hit ) +
                ( 50 - ( ( victim->hit * 50 ) / victim->max_hit ) );

    /*           10 * percent                   */
    if ( dam ==      0 )
    {
        vs = "miss";
        vp = "misses";
    }
    else if ( dampc <=    5 )
    {
        vs = "barely scratch";
        vp = "barely scratches";
    }
    else if ( dampc <=   10 )
    {
        vs = "scratch";
        vp = "scratches";
    }
    else if ( dampc <=   20 )
    {
        vs = "nick";
        vp = "nicks";
    }
    else if ( dampc <=   30 )
    {
        vs = "graze";
        vp = "grazes";
    }
    else if ( dampc <=   40 )
    {
        vs = "bruise";
        vp = "bruises";
    }
    else if ( dampc <=   50 )
    {
        vs = "hit";
        vp = "hits";
    }
    else if ( dampc <=   60 )
    {
        vs = "injure";
        vp = "injures";
    }
    else if ( dampc <=   75 )
    {
        vs = "thrash";
        vp = "thrashes";
    }
    else if ( dampc <=   80 )
    {
        vs = "wound";
        vp = "wounds";
    }
    else if ( dampc <=   90 )
    {
        vs = "maul";
        vp = "mauls";
    }
    else if ( dampc <=  125 )
    {
        vs = "decimate";
        vp = "decimates";
    }
    else if ( dampc <=  150 )
    {
        vs = "devastate";
        vp = "devastates";
    }
    else if ( dampc <=  200 )
    {
        vs = "maim";
        vp = "maims";
    }
    else if ( dampc <=  300 )
    {
        vs = "MUTILATE";
        vp = "MUTILATES";
    }
    else if ( dampc <=  400 )
    {
        vs = "DISEMBOWEL";
        vp = "DISEMBOWELS";
    }
    else if ( dampc <=  500 )
    {
        vs = "MASSACRE";
        vp = "MASSACRES";
    }
    else if ( dampc <=  600 )
    {
        vs = "PULVERIZE";
        vp = "PULVERIZES";
    }
    else if ( dampc <=  750 )
    {
        vs = "EVISCERATE";
        vp = "EVISCERATES";
    }
    else if ( dampc <=  990 )
    {
        vs = "* OBLITERATE *";
        vp = "* OBLITERATES *";
    }
    else
    {
        vs = "*** ANNIHILATE ***";
        vp = "*** ANNIHILATES ***";
    }

    if ( dt >= 0 )
        skill = skill_from_id( dt );

    if ( dt == ( TYPE_HIT + WEAPON_BLASTER ) )
    {
        char sound[MSL];
        int vol = number_range( 20, 80 );
        snprintf( sound, MSL, "blaster V=%d", vol );
        sound_to_room( ch->in_room, sound );
    }

    char punct = dampc <= 100 ? '.' : '!';
    char dam_amt[50];

    if ( dam == 0 )
        dam_amt[0] = '\0';
    else
        snprintf( dam_amt, 50, " (%d)", dam );

    cache_skill( "snipe", &skill_snipe );
    if ( ( dt == TYPE_HIT || dam == 0 ) && !xIS_SET( ch->race->flags, RFLAG_UNDEAD ) )
    {
        snprintf( buf1, 256, "$n %s $N%c",  vp, punct );
        snprintf( buf2, 256, "You %s $N%c%s", vs, punct, dam_amt );
        snprintf( buf3, 256, "$n %s you%c", vp, punct );
    }
    else if ( ( snipe = skill_snipe ) != NULL && dt == snipe->id )
    {
        snprintf( buf1, 256, "$n's shot %s $N%c",  vp, punct );
        snprintf( buf2, 256, "Your shot %s $N%c%s", vp, punct, dam_amt );
        snprintf( buf3, 256, "Someone's shot %s you%c", vp, punct );
    }
    else
    {
        if ( dt > TYPE_HIT && is_wielding_poisoned( ch ) )
        {
            if ( dt < TYPE_HIT + ( int ) sizeof( attack_table ) / ( int ) sizeof( attack_table[0] ) )
                attack  = attack_table[dt - TYPE_HIT];
            else
            {
                snprintf( buf, 256, "Dam_message:  bad dt %d by %s.", dt, ch->name );
                bug( buf );
                /* bug( "Dam_message: bad dt %d.", dt ); */
                dt  = TYPE_HIT;
                attack  = attack_table[0];
            }

            snprintf( buf1, 256, "$n's poisoned %s %s $N%c", attack, vp, punct );
            snprintf( buf2, 256, "Your poisoned %s %s $N%c%s", attack, vp, punct, dam_amt );
            snprintf( buf3, 256, "$n's poisoned %s %s you%c", attack, vp, punct );
        }
        else
        {
            if ( skill )
            {
                attack = skill->noun_damage;

                // Default to 'hit' for skills with no noun set
                if ( NULLSTR( attack ) )
                    attack = attack_table[0];

                if ( dam == 0 )
                {
                    bool found = FALSE;

                    if ( skill->miss_char && skill->miss_char[0] != '\0' )
                    {
                        act( AT_HIT, skill->miss_char, ch, NULL, victim, TO_CHAR );
                        found = TRUE;
                    }

                    if ( skill->miss_vict && skill->miss_vict[0] != '\0' )
                    {
                        act( AT_HITME, skill->miss_vict, ch, NULL, victim, TO_VICT );
                        found = TRUE;
                    }

                    if ( skill->miss_room && skill->miss_room[0] != '\0' )
                    {
                        act( AT_ACTION, skill->miss_room, ch, NULL, victim, TO_NOTVICT );
                        found = TRUE;
                    }

                    if ( found )    /* miss message already sent */
                        return;
                }
                else
                {
                    if ( skill->hit_char && skill->hit_char[0] != '\0' )
                        act( AT_HIT, skill->hit_char, ch, NULL, victim, TO_CHAR );

                    if ( skill->hit_vict && skill->hit_vict[0] != '\0' )
                        act( AT_HITME, skill->hit_vict, ch, NULL, victim, TO_VICT );

                    if ( skill->hit_room && skill->hit_room[0] != '\0' )
                        act( AT_ACTION, skill->hit_room, ch, NULL, victim, TO_NOTVICT );
                }
            }
            else if ( dt >= TYPE_HIT
                      && dt < TYPE_HIT + ( int ) sizeof( attack_table ) / ( int ) sizeof( attack_table[0] ) )
                attack  = attack_table[dt - TYPE_HIT];
            else if ( dt == TYPE_UNDEFINED )
                return;
            else
            {
                snprintf( buf, 256, "Dam_message:  bad dt %d by %s.", dt, ch->name );
                bug( buf );
                /* bug( "Dam_message: bad dt %d.", dt ); */
                dt  = TYPE_HIT;
                attack  = attack_table[0];
            }

            if ( wielding_claws( ch ) )
                attack = attack_table[3];

            //    if (xIS_SET(ch->race->flags,RFLAG_UNDEAD))
            //        attack = attack_table[10];
            snprintf( buf1, 256, "$n's %s %s $N%c",  attack, vp, punct );
            snprintf( buf2, 256, "Your %s %s $N%c%s",  attack, vp, punct, dam_amt );
            snprintf( buf3, 256, "$n's %s %s you%c", attack, vp, punct );
        }
    }

    if ( dt == TYPE_HIT + WEAPON_FLAMETHROWER )
    {
        act( AT_RED, buf1, ch, NULL, victim, TO_NOTVICT );
        //if (!gcflag)
        act( AT_RED, buf2, ch, NULL, victim, TO_CHAR );
        //if (!gvflag)
        act( AT_HITME, buf3, ch, NULL, victim, TO_VICT );
    }
    else
    {
        act( AT_ACTION, buf1, ch, NULL, victim, TO_NOTVICT );
        //if (!gcflag)
        act( AT_HIT, buf2, ch, NULL, victim, TO_CHAR );
        //if (!gvflag)
        act( AT_HITME, buf3, ch, NULL, victim, TO_VICT );
    }

    return;
}


CMDF do_kill( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    VEHICLE_DATA* vec = NULL;
    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Kill whom?" );
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && has_pcflag( ch, PCFLAG_NOFIGHT ) )
    {
        ch_println( ch, "&RWARNING! YOU HAVE CONFIG +NOFIGHT ENABLED!\nTHIS MEANS YOU WILL NOT DO DAMAGE IN COMBAT UNLESS YOU USE SKILLS\nOR DISABLE THIS OPTION." );
    }

    for ( vec = first_vehicle; vec; vec = vec->next )
        if ( nifty_is_name_prefix( arg, vec->name ) && vec->in_room == ch->in_room )
            break;

    if ( vec )
    {
        char buf[MSL];
        int dam = 0;
        OBJ_DATA* obj = NULL;
        ROOM_INDEX_DATA* room = NULL;

        if ( !str_cmp( vec->owner, "public" ) || !str_cmp( vec->owner, "Public" ) )
        {
            ch_println( ch, "You shouldn't attack public vehicles!" );
            return;
        }

        obj = get_eq_char( ch, WEAR_WIELD );

        //        if ( !obj )
        //      {
        //        ch_println( ch, "Punching or kicking a vehicle is madness." );
        //      return;
        //        }
        switch ( vec->armor )
        {
            default:
                break;

            case 1: // Light armor, need a weapon to hit it
                if ( !obj )
                {
                    ch_println( ch, "You won't be able to damage it without a weapon." );
                    return;
                }

                break;

            case 2: // Med armor, blasters and sabers only
                if ( !obj )
                {
                    ch_println( ch, "You won't be able to damage it without a weapon." );
                    return;
                }

                if ( obj->value[3] != WEAPON_BLASTER && obj->value[3] != WEAPON_LIGHTSABER )
                {
                    ch_println( ch, "You won't do much damage with this." );
                    return;
                }

                if ( obj->value[4] == 0 )
                {
                    ch_println( ch, "This weapon has no ammo left." );
                    return;
                }

                break;

            case 3: // Heavy armor, sabers only
                if ( !obj )
                {
                    ch_println( ch, "You won't be able to damage it without a weapon." );
                    return;
                }

                if ( obj->value[3] != WEAPON_LIGHTSABER )
                {
                    ch_println( ch, "You won't do much damage with this." );
                    return;
                }

                if ( obj->value[4] == 0 )
                {
                    ch_println( ch, "This weapon has no ammo left." );
                    return;
                }

                break;
        }

        if ( obj )
        {
            obj->value[4] = URANGE( 0, obj->value[4] - ( number_range( 4, 9 ) * obj->blaster_setting ), obj->value[5] );

            if ( vec->state != VEHICLE_DISABLED && vec->state != VEHICLE_OFF )
                if ( number_percent() + 30 > what_prof( ch, obj ) )
                    dam = -1;
        }
        else
        {
            if ( number_percent() < 30 )
                dam = -1;
            else
                dam = 1;
        }

        WAIT_STATE( ch, 1 * PULSE_VIOLENCE );

        if ( dam == -1 )
        {
            ch_println( ch, "Your attack misses." );
            snprintf( buf, MSL, "$n attacks %s with %s, but misses.", vec->name, obj ? obj->name : "$s bare hands" );
            act( AT_ACTION, buf, ch, NULL, NULL, TO_ROOM );
            room = get_room_index( vec->cockpit );

            if ( room && room->first_person )
            {
                snprintf( buf, MSL, "$N attacks this vehicle with %s, but misses.", obj ? obj->name : "$S bare hands" );
                act( AT_ACTION, buf, room->first_person, NULL, ch, TO_CHAR );
                act( AT_ACTION, buf, room->first_person, NULL, ch, TO_ROOM );
            }

            return;
        }

        //if ( number_percent() < (10*(vec->armor+1)) )
        //  dam = 1;
        if ( obj )
        {
            dam = number_range( obj->value[1], obj->value[2] );
            dam /= 3;
        }

        snprintf( buf, MSL, "%s attacking vehicle %s, doing %d damage.", ch->name, vec->name, dam );
        log_string( buf );

        if ( ch->skill_level[COMBAT_ABILITY] < 100 )
            ch_println( ch, "You attack %s with %s, doing %s damage.", vec->name, obj ? obj->name : "your bare hands", dam == 1 ? "almost no" : "some" );
        else
            ch_println( ch, "You attack %s with %s, doing %d damage.", vec->name, obj ? obj->name : "your bare hands", dam );

        snprintf( buf, MSL, "$N attacks the vehicle with %s, doing %s damage.", obj ? obj->name : "$S bare hands", dam == 1 ? "almost no" : "some" );
        room = get_room_index( vec->cockpit );

        if ( room && room->first_person )
        {
            act( AT_ACTION, buf, room->first_person, NULL, ch, TO_ROOM );
            act( AT_ACTION, buf, room->first_person, NULL, ch, TO_CHAR );
        }

        snprintf( buf, MSL, "$n attacks %s with %s.", vec->name, obj ? obj->name : "$s bare hands" );
        act( AT_RED, buf, ch, NULL, NULL, TO_ROOM );
        damage_vehicle_ch( vec, dam / 2, dam, ch );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You hit yourself.  Ouch!" );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        ch_println( ch, "You must MURDER a player." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == victim )
    {
        act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( ch->position == POS_FIGHTING )
    {
        if ( who_fighting( ch ) == victim )
        {
            ch_println( ch, "You do the best you can!" );
        }
        else
        {
            act( AT_YELLOW, "You begin attacking $N.", ch, NULL, victim, TO_CHAR );
            act( AT_YELLOW, "$n begins attacking you!", ch, NULL, victim, TO_VICT );
            act( AT_YELLOW, "$n begins attacking $N.", ch, NULL, victim, TO_NOTVICT );
            stop_fighting( ch, FALSE );
            set_fighting( ch, victim );
            WAIT_STATE( ch, 1 * PULSE_VIOLENCE );
        }
        return;
    }

    /*
        if ( !xIS_EMPTY(victim->vip_flags) )
        ch->alignment -= 10;*/
    WAIT_STATE( ch, 1 * PULSE_VIOLENCE );
    multi_hit( ch, victim, TYPE_UNDEFINED );
    return;
}



