CMDF do_murder( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    OBJ_DATA* obj = NULL;
    CHAR_DATA* victim;
    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Murder whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ( ch->held ) && ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL )
    {
        ch_println( ch, "You can't attack with no weapon while held! Try struggling!" );
        return;
    }

    if ( !pk_allow && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, no PKing right now." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
    {
        ch_println( ch, "&RYou are in a safezone. Make sure you are familiar with the rules stated in &Yhelp safezone&R and are sure you are not breaking them..." );
    }

    if ( victim == ch )
    {
        ch_println( ch, "Suicide is a mortal sin." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( IS_AFFECTED( ch, AFF_CHARM ) )
    {
        if ( ch->master == victim )
        {
            act( AT_PLAIN, "$N is your beloved master.", ch, NULL, victim, TO_CHAR );
            return;
        }
    }

    if ( ch->position == POS_FIGHTING )
    {
        if ( who_fighting( ch ) == victim )
        {
            ch_println( ch, "You do the best you can!" );
        }
        else
        {
            act( AT_YELLOW, "You begin attacking $N.", ch, NULL, victim, TO_CHAR );
            act( AT_YELLOW, "$n begins attacking you!", ch, NULL, victim, TO_VICT );
            act( AT_YELLOW, "$n begins attacking $N.", ch, NULL, victim, TO_NOTVICT );
            stop_fighting( ch, FALSE );
            set_fighting( ch, victim );
            WAIT_STATE( ch, 1 * PULSE_VIOLENCE );
        }
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !str_cmp( argument, "perm" ) && !xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
    {
        if ( ch->desc && ch->desc->account && xIS_SET( ch->desc->account->flags, ACC_NOPERM ) )
        {
            ch_println( ch, "&RYou are not allowed to perm." );
            return;
        }

        perming_char = ch;
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        perming_char = ch;

    /*
        ch->alignment -= 10;*/

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && has_pcflag( ch, PCFLAG_NOFIGHT ) )
    {
        ch_println( ch, "&R[WARNING]: &WYou have CONFIG +NOFIGHT enabled! Until you disable this option you will not attack during combat! To disable it, type 'config -nofight'." );
    }

    WAIT_STATE( ch, 1 * PULSE_VIOLENCE );
    multi_hit( ch, victim, TYPE_UNDEFINED );

    if ( perming_char )
        perming_char = NULL;

    return;
}

CMDF do_flee( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    ROOM_INDEX_DATA* was_in = NULL;
    int attempt;
    sh_int door;
    EXIT_DATA* pexit;

    if ( ch->held )
    {
        ch_println( ch, "You're a little busy being restrained right now." );
        return;
    }

    if ( !who_fighting( ch ) )
    {
        if ( ch->position == POS_FIGHTING )
        {
            if ( ch->mount )
                ch->position = POS_MOUNTED;
            else
                ch->position = POS_STANDING;
        }

        ch_println( ch, "You aren't fighting anyone." );
        return;
    }

    /*  Let em run from a fight, its tiring! Orion
        if ( ch->move <= 0 )
        {
        ch_println( ch, "You're too exhausted to flee from combat!" );
        return;
        }
    */
    /* No fleeing while stunned. - Narn */
    if ( ch->position < POS_FIGHTING )
        return;

    if ( !ch->in_room )
        return;

    /* Redundant safety check against weird pointer handling */
    was_in = ( ROOM_INDEX_DATA* ) get_room_index( ch->in_room->vnum );

    if ( !was_in || was_in != ch->in_room )
        return;

    for ( attempt = 0; attempt < 8; attempt++ )
    {
        door = number_door( );

        if ( ( pexit = get_exit( was_in, door ) ) == NULL )
            continue;

        move_char( ch, pexit, 0, FALSE );

        if ( ch->in_room == was_in )
            continue;

        stop_fighting( ch, TRUE );
        char_from_room( ch );
        char_to_room( ch, was_in );
        act( AT_FLEE, "$n flees $t!", ch, dir_name[pexit->vdir], NULL, TO_ROOM );
        char_from_room( ch );
        char_to_room( ch, pexit->to_room );
        act( AT_FLEE, "$n runs in from the $t!", ch, dir_name[rev_dir[pexit->vdir]], NULL, TO_ROOM );
        ch_println( ch, "You flee %s.", dir_name[pexit->vdir] );
        return;
    }
    ch_println( ch, "You attempt to run for cover!" );
    return;
}

bool get_cover( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* was_in;
    ROOM_INDEX_DATA* now_in;
    int attempt;
    sh_int door;
    EXIT_DATA* pexit;

    if ( !who_fighting( ch ) )
        return FALSE;

    if ( ch->position < POS_FIGHTING )
        return FALSE;

    was_in = ch->in_room;

    for ( attempt = 0; attempt < 10; attempt++ )
    {
        door = number_door( );

        if ( ( pexit = get_exit( was_in, door ) ) == NULL
                ||   !pexit->to_room
                || ( ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) ) && !IS_AFFECTED( ch, AFF_PASS_DOOR ) )
                || ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && !MOB_CAN_ENTER( pexit->to_room ) )
           )
            continue;

        cache_skill( "sneak", &skill_sneak );
        affect_strip( ch, CHAR_AFFECT, skill_sneak );
        xREMOVE_BIT( ch->affected_by, AFF_SNEAK );

        if ( ch->mount && ch->mount->fighting )
            stop_fighting( ch->mount, TRUE );

        move_char( ch, pexit, 0, FALSE );

        if ( ( now_in = ch->in_room ) == was_in )
            continue;

        ch->in_room = was_in;
        act( AT_FLEE, "$n sprints for cover!", ch, NULL, NULL, TO_ROOM );
        ch->in_room = now_in;
        act( AT_FLEE, "$n spins around and takes aim.", ch, NULL, NULL, TO_ROOM );
        stop_fighting( ch, TRUE );
        return TRUE;
    }

    return FALSE;
}

