CMDF do_slay( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    char arg2[MIL];
    if (IS_NPC(ch))
        return;

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &CSLAY <&wtarget&C> <&wtype&C>" );
        ch_println( ch, "        SLAY [list]" );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        ch_println( ch, "&YTypes:" );
        ch_println( ch, "&RIMMOLATE, SHATTER, DEMON, POUNCE, SLIT, BLADE," );
        ch_println( ch, "&RTWIDDLE, SNEEZE, GRENADE, SPOON, WALL, JD," );
        ch_println( ch, "&RPEACE, SLOW, SPORK" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "Suicide is a mortal sin." );
