/*
    Allows Immortals to add some pretty nasty Affects =)
    -Ghost
*/
CMDF do_curse( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    char arg[MIL];
    char arg2[MIL];
    AFFECT_DATA af;
    argument = one_argument( argument, arg );
    one_argument( argument, arg2 );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Curse whom? Type CURSE LIST" );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        ch_println( ch, "Usage: Curse <player> <curse>" );
        ch_println( ch, "CURSES: Blind  Weaken    Poison  Paralysis" );
        ch_println( ch, "        Ryll   Carsanum  Andris  Glitterstim" );
        ch_println( ch, "        Mental Emotional " );
        return;
    }

    if ( ( victim = get_char_world( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    /*
        if ( ch == victim )
        {
        ch_println( ch, "That would not be very bright." );
        return;
        }
    */

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && get_trust( ch ) <= 102 )
    {
        ch_println( ch, "Not likely, Weakling." );
        return;
    }

    if ( ( get_trust ( ch ) <= get_trust ( victim ) ) && ch != victim )
    {
        send_to_char( "Ahhhhh! It burns! It burns! [Curse was Reflected]", ch );
        victim = ch;
    }

    if ( !str_cmp( arg2, "blind" ) )
    {
        if ( !IS_AFFECTED( victim, AFF_BLIND ) )
        {
            cache_skill( "blindness", &skill_blindness );
            SKILL_DATA* afskill = skill_blindness;
            af.type      = afskill ? afskill->id : -1;
            af.location  = APPLY_HITROLL;
            af.modifier  = -7;
            af.duration  = 14;
            xCLEAR_BITS( af.bitvector );
            xSET_BIT( af.bitvector, AFF_BLIND );
            affect_to_target( victim, CHAR_AFFECT, &af );
            act( AT_SKILL, "You can't see a thing!", victim, NULL, NULL, TO_CHAR );
        }
    }
    else if ( !str_cmp( arg2, "weaken" ) )
    {
        cache_skill( "weaken", &skill_weaken );
        SKILL_DATA* afskill = skill_weaken;
        af.type      = afskill ? afskill->id : -1;
        af.location  = APPLY_STR;
        af.modifier  = -2;
        af.duration  = 15;
        xCLEAR_BITS( af.bitvector );
        affect_to_target( victim, CHAR_AFFECT, &af );
        act( AT_SKILL, "You feel weaker...", victim, NULL, NULL, TO_CHAR );
    }
    else if ( !str_cmp( arg2, "poison" ) )    /* Sure kill   -Ghost */
    {
        cache_skill( "poison", &skill_poison );
        SKILL_DATA* afskill = skill_poison;
        af.type      = afskill ? afskill->id : -1;
        af.location  = APPLY_STR;
        af.modifier  = -3;
        af.duration  = 500;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_POISON );
        affect_to_target( victim, CHAR_AFFECT, &af );
        act( AT_SKILL, "You feel very sick...", victim, NULL, NULL, TO_CHAR );
    }
    else if ( !str_cmp( arg2, "paralysis" ) )
    {
        if ( !IS_AFFECTED( victim, AFF_PARALYSIS ) )
        {
            cache_skill( "stun", &skill_stun );
            SKILL_DATA* afskill = skill_stun;
            af.type      = afskill ? afskill->id : -1;
            af.location  = APPLY_AC;
            af.modifier  = 20;
            af.duration = 10;
            xCLEAR_BITS( af.bitvector );
            xSET_BIT( af.bitvector, AFF_PARALYSIS );
            affect_to_target( victim, CHAR_AFFECT, &af );
            update_pos( victim );
        }
    }
    else if ( !str_cmp( arg2, "mental" ) )
    {
        worsen_mental_state( victim, 20 );
    }
    else if ( !str_cmp( arg2, "emotional" ) )
    {
        if ( victim->emotional_state - 20 <= -500 )
        {
            victim->emotional_state = -500;
        }
        else
        {
            victim->emotional_state -= 20;
        }
    }
    else
    {
        ch_println( ch, "Usage: Curse <player> <curse>" );
        ch_println( ch, "CURSES: Blind  Weaken    Poison  Paralysis" );
        ch_println( ch, "        Ryll   Carsanum  Andris  Glitterstim" );
        ch_println( ch, "        Mental Emotional " );
    }

    return;
}

void makeUndead( CHAR_DATA* victim )
{
    OBJ_DATA* obj = NULL, *obj_next = NULL;
    ACCOUNT_DATA* acc = NULL;
    RACE_DATA *undeadrace = NULL;
    ACC_CHAR* ach = NULL;
    AFFECT_DATA* paf;
    AFFECT_DATA* pnext;
    CHAR_DATA* rch, *rnext;
    //todo: Lets clean up these messages to be more.. specific to environmental damage?
    //   ch_println( victim, "&RYour world fades to black. As a lifetime of memories flashes before your eyes, you feel your life force leave your body. Suddenly, you are cold. You are filled with a sudden, instinctual aggression. You can think of nothing else as your eyes blink back open. Your world has a red tint and you feel compelled to kill. Kill now." );

    // remove weapons, bindings, etc..
    for ( obj = victim->last_carrying; obj; obj = obj_next )
    {
        obj_next = obj->prev_content;

        if ( ( get_eq_char( victim, WEAR_BINDING ) ) != NULL )
        {
            unequip_char( victim, obj );
            separate_obj( obj );
            obj_from_char( obj );
            extract_obj( obj );
        }
