// After hospitalZone is returned to true, this function can be called to send a character to a hospital
void sendToHospital( CHAR_DATA* attacker, CHAR_DATA* victim )
{
    AFFECT_DATA* paf = NULL, *next_paf = NULL;
    ROOM_INDEX_DATA* room  = NULL;
    OBJ_DATA* obj = NULL, *obj_next = NULL;
    BANK_DATA* bank = NULL;
    char* txt;
    room = fetchHospital( victim );

    if ( room != NULL )
    {
        CHAR_DATA* rch, *rnext;
        //todo: Lets clean up these messages to be more.. specific to environmental damage?
        ch_println( victim, "&BYou were nearly killed, but luckily there is a hospital nearby.\n&zEverything fades to black, and only the piercing sound of sirens echo in your ears as you plunge into darkness...&w\n" );

        // remove weapons, bindings, etc..
        for ( obj = victim->last_carrying; obj; obj = obj_next )
        {
            obj_next = obj->prev_content;

            if ( ( get_eq_char( victim, WEAR_BINDING ) ) != NULL )
            {
                unequip_char( victim, obj );
                separate_obj( obj );
                obj_from_char( obj );
                extract_obj( obj );
            }
        }

        // Remove 5k from the player and give it to them... lucky sons of bitches
        if ( victim->gold < 5000 )
        {
            for ( bank = first_bank; bank; bank = bank->next )
                if ( !str_cmp( bank->owner, victim->name ) && bank->amount >= 5000 )
                    break;

            if ( bank )
            {
                bank -= 5000;
                victim->gold += 5000;
                save_bank( bank, TRUE );
            }
        }

        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
            sql_credits_log( victim->name, "sendToHospital", -1 * ( UMIN( 5000, victim->gold ) ), TRUE );

        victim->gold = UMAX( 0, victim->gold - 5000 );
        victim->hit = number_range( 1, 5 );
        victim->mana = 0;
        victim->move = number_range( 1, 5 );
        victim->pcdata->condition[COND_BLOODTHIRST] = ( 10 + victim->top_level );
        update_pos( victim );

        if ( victim->heldby )
            victim->heldby->holding = NULL;
        victim->heldby = NULL;
        victim->held = FALSE;

        if ( victim->carried )
            victim->carried->carrying = NULL;
        victim->carried = NULL;

        for ( paf = victim->first_affect; paf; paf = next_paf )
        {
            next_paf = paf->next;
            paf->duration = 0;
        }

        act( AT_MAGIC, "$n is taken away by a team of paramedics.", victim, NULL, NULL, TO_ROOM );
        // Force a check of rprogs before the character moves
        txt = act_string( "$n is taken away by a team of paramedics.", NULL, victim, NULL, NULL );
        rprog_wordlist_check( txt, supermob, victim, NULL, NULL, ACT_PROG, victim->in_room );

        victim->retran = victim->in_room->vnum;
        char_from_room( victim );
        char_to_room( victim, room );

        act( AT_MAGIC, "$n is hauled in by a team of paramedics, and put in a tank.", victim, NULL, NULL, TO_ROOM );

        if ( !attacker || ( IS_NPC( attacker ) || IS_SWITCHED_NPC( attacker ) ) || attacker == victim )
        {
            // Leave them logged in, but hit them with a lag for effect.
            victim->position = POS_RESTING;
            ch_println( victim, "&CYou slowly regain consciousness in the hospital. You are still alive, but injured, exhausted,\nand 5,000 credits poorer.&w" );
            WAIT_STATE( victim, 40 );


            return;
        }
        else
        {
            // If the character is going to be extracted (logged out), force a check of rprogs in the hospital room before extraction
            txt = act_string( "$n is hauled in by a team of paramedics, and put in a tank.", NULL, victim, NULL, NULL );
            rprog_wordlist_check( txt, supermob, victim, NULL, NULL, ACT_PROG, victim->in_room );
            // If hospitalized in PVP combat, we log out the victim to:
            // - Give them an automatic break to cool down
            // - Prevent camping at hospitals to re-attack the victim. They can just stay logged off for a while if they need to.
            ch_println( victim, "&C(OOC) When hospitalized by another player, you are logged out. You will be alive and in the\nhospital when you log back in.&w" );
            save_char_obj( victim, true );

            for ( rch = first_char; rch; rch = rnext )
            {
                rnext = rch->next;

                if ( victim == rch )
                    continue;

                if ( rch->master == victim && !victim->master )
                {
                    if ( ( IS_NPC( rch ) || IS_SWITCHED_NPC( rch ) ) )
                        extract_char( rch );
                }
            }

            extract_char( victim );
        }
    }
}

// initial check for sending someone to a hospital, will return TRUE if eliglbe to go to a local hospital
bool hospitalZone( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* room;

    if ( sun_killing )
        return FALSE;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        return FALSE;

    if ( xIS_SET( ch->in_room->flags, ROOM_NOHOSPITAL ) )
        return FALSE;

    if ( ( room = fetchHospital( ch ) ) == NULL )
        return FALSE;

    // Planets which are currently UFG use the 12-hour lockout instead of hospitalization.
    if ( use_ufg_death_system( ch ) )
        return FALSE;

    return TRUE;
}

bool use_ufg_death_system( CHAR_DATA* ch )
{
    PLANET_DATA* planet = on_planet( ch );
    if ( planet && is_ufg( planet ) && !get_ship_from_room( ch->in_room ) )
        return true;
    return false;
}

// will return a hospital from the local area
ROOM_INDEX_DATA* fetchHospital( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* room = NULL;
    SHIP_DATA* ship = NULL;
    int vnum;
    STRUCTURE_DATA* structure = NULL;

    if ( !ch->in_room )
        return NULL;

    if ( xIS_SET( ch->in_room->flags, ROOM_NOHOSPITAL ) )
        return NULL; //Regardless of ship or not, always return NULL if the room is flagged no hospital.

    if ( ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
    {
        if ( clan_npcs_warring_ch( get_clan( ship->shipowner ), ch ) )
            return NULL;

        for ( vnum = ship->firstroom; vnum <= ship->lastroom; vnum++ )
        {
            if ( ( room = get_room_index( vnum ) ) != NULL )
            {
                if ( xIS_SET( room->flags, ROOM_HOSPITAL ) )
                    break;

                room = NULL;
            }
        }
    }
    else
    {
        if ( !ch->in_room->area )
            return NULL;

        ROOM_INDEX_DATA* chroom = ch->in_room;

        if ( ( structure = structure_from_room( chroom->vnum ) ) != NULL )
            chroom = get_room_index( structure->in_room );

        if ( !chroom || !chroom->area )
            return NULL;

        if ( clan_npcs_warring_ch( get_localclan( chroom ), ch ) )
            return NULL;

        for ( vnum = chroom->area->min_vnum; vnum <= chroom->area->max_vnum; vnum++ )
        {
            room = get_room_index ( vnum );

            if ( room != NULL )
            {
                if ( xIS_SET( room->flags, ROOM_PROTOTYPE ) )
                {
                    room = NULL;
                    continue;
                }

                if ( xIS_SET( room->flags, ROOM_NOHAIL ) )
                {
                    room = NULL;
                    continue;
                }

                if ( xIS_SET( room->flags, ROOM_PLR_HOME ) || xIS_SET( room->flags, ROOM_EMPTY_HOME ) )
                {
                    room = NULL;
                    continue;
                }

                if ( xIS_SET( room->flags, ROOM_COMMSHIELD ) )
                {
                    room = NULL;
                    continue;
                }

                if ( xIS_SET( room->flags, ROOM_HOSPITAL ) )
                    break;

                room = NULL;
            }
        }
    }

    return room;
}

// Determines if two characters are in warring factions
//TODO: need to probably move this into the player section...
bool isWarring( CHAR_DATA* ch, CHAR_DATA* victim )
{
    CLAN_DATA* clanA = NULL;
    CLAN_DATA* clanB = NULL;

    // Check for warring faction
    if ( ch && victim )
    {
        // Snag attacker clandata
        if ( ch->pcdata )
        {
            clanA = ch->pcdata->clan;
        }
        else
        {
            clanA = get_clan( ch->mob_clan );
        }

        // snag victim clan data
        if ( victim->pcdata )
        {
            clanB = victim->pcdata->clan;
        }
        else
        {
            clanB = get_clan( victim->mob_clan );
        }

        if ( enemy_clan( clanB, clanA ) )
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    return false;
}

CMDF do_flurry( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim = NULL;
    int atks = 0, chance = 0;

    if ( ( victim = who_fighting( ch ) ) == NULL )
    {
        ch_println( ch, "You must be in a fight to unleash a flurry of attacks." );
        return;
    }

    if ( ch->move < 100 )
    {
        ch_println( ch, "You're too tired to do that right now." );
        return;
    }

    if ( ch->aim )
    {
        ch_println( ch, "You stop aiming as you unleash the flurry." );
        clear_aim( ch );
    }

    cache_skill( "flurry", &skill_flurry );
    chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : ( int ) get_learned_pct( ch, skill_flurry );
    atks = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ?
           number_range( 1, 3 ) :
           number_range( 3, 5 );

    if ( atks < 1 )
        atks = 1;

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        atks += atks / 3;

    if ( atks < 1 )
        atks = 1;

    ch_println( ch, "You unleash a flurry of attacks!" );

    while ( atks > 0 && victim && !char_extracted( victim ) && victim->hit >= 1 && !char_extracted( ch ) )
    {
        atks--;

        if ( number_percent() > chance )
            ch_println( ch, "You miss %s.", g_name( victim, ch ) );
        else
            global_retcode = one_hit( ch, victim, TYPE_UNDEFINED );
    }

    ch->move = URANGE( 10, ch->move - number_range( 250, 650 ), ch->max_move );
    ch_println( ch, "You finish your flurry." );
    WAIT_STATE( ch, PULSE_VIOLENCE * 1 );
    cache_skill( "flurry", &skill_flurry );
    learn_slow( ch, skill_flurry, 5 );
    return;
}

int slowdraw_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "Your hand stops moving towards your holster." );
    return E_LOTJ_SUCCESS;
}

int slowdraw_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    CHAR_DATA* victim = buffer->target;
    cache_skill( "slowdraw", &skill_slowdraw );
    cache_skill( "foresight", &skill_foresight );
    SKILL_DATA* skill = skill_slowdraw;
    if ( !valid_char( victim ) || victim->in_room != ch->in_room )
    {
        ch_println( ch, "&RYour target seems to have left." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( ch->position != POS_SITTING && ch->position != POS_STANDING )
    {
        ch_println( ch, "You're not in a good position to do that." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( victim->position == POS_FIGHTING )
    {
        ch_println( ch, "You can't get the drop on them -- they're already fighting!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is now afk." );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    OBJ_DATA* weapon = is_holstered_type( ch, WEAPON_BLASTER );
    if ( !weapon || xIS_SET( weapon->extra_flags, ITEM_NODUAL ) || xIS_SET( weapon->extra_flags, ITEM_REPEATER ) )
    {
        ch_println( ch, "You need a holstered blaster pistol for that!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    if ( number_percent() <= UMAX( 15, get_learned_pct( ch, skill_slowdraw ) ) )
    {
        if ( act_unholster( ch, false, true, false, NULL ) )
        {
            // A forcer with foresight will sometimes be able to autodraw in advance of an incoming slowdraw to reflect it.
            if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) &&
                    !has_pcflag( victim, PCFLAG_NO_SENSE ) &&
                    victim->pcdata &&
                    get_learned_pct( victim, skill_foresight ) > 0 &&
                    has_pcflag( victim, PCFLAG_AUTODRAW ) &&
                    can_unholster( victim, get_eq_char( victim, WEAR_WAIST ), true ) )
            {
                // 25%-75% chance to succeed based on foresight skill
                if ( number_percent() < 25 + get_learned_pct( victim, skill_foresight ) / 2 )
                {
                    act( AT_MAGIC, "Your senses tingle as the Force warns you of a threat, and you instinctively reach for your weapon.", ch, NULL, victim, TO_VICT );
                    act( AT_ACTION, "With no warning, $N suddenly reaches for $S weapon.", ch, NULL, victim, TO_NOTVICT );
                    interpret( victim, "draw", FALSE );
                }
            }

            act( AT_ACTION, "You stealthily draw $p and take a shot at $N.", ch, weapon, victim, TO_CHAR );
            act( AT_ACTION, "$n stealthily draws $p and takes a shot at $N.", ch, weapon, victim, TO_NOTVICT );
            act( AT_ACTION, "$n stealthily draws $p and takes a shot at you.", ch, weapon, victim, TO_VICT );
            one_hit( ch, victim, skill->id );
            learn_from_success( ch, skill );
        }
    }
    else
    {
        if ( act_unholster( ch, false, false, false, NULL ) )
        {
            ch_println( ch, "You fumble awkwardly for your weapon, and everyone sees it!" );
            learn_from_failure( ch, skill );
        }
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_slowdraw( CHAR_DATA* ch, char* argument )
{
    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
    {
        ch_println( ch, "NPC - NCD" );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cslowdraw <&wvictim&C>" );
        return;
    }

    CHAR_DATA* victim = get_char_room( ch, argument );
    if ( !victim )
    {
        ch_println( ch, "They're not here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "What would be the point of that??" );
        return;
    }

    if ( ch->position != POS_SITTING && ch->position != POS_STANDING ) // Doing it this way so that they can't slowdraw while fighting
    {
        ch_println( ch, "You're not in a good position to do that." );
        return;
    }

    if ( !act_unholster( ch, true, true, false, NULL ) )
        return;

    if ( victim->position == POS_FIGHTING )
    {
        ch_println( ch, "You can't get the drop on them -- they're already fighting!" );
        return;
    }

    if ( !pk_allow && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, no PKing right now." );
        return;
    }

    if ( is_safe( ch, victim ) )
    {
        ch_println( ch, "You can't do that here." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
    {
        ch_println( ch, "&RYou are in a safezone. Make sure you are familiar with the rules stated in HELP SAFEZONE and are sure you are not breaking them.&w" );
        return;
    }

    OBJ_DATA* weapon = is_holstered_type( ch, WEAPON_BLASTER );
    if ( !weapon || xIS_SET( weapon->extra_flags, ITEM_NODUAL ) || xIS_SET( weapon->extra_flags, ITEM_REPEATER ) )
        ch_println( ch, "You need a holstered blaster pistol for that!" );
    else
    {
        TIMER* timer = add_timer( ch, TIMER_DO_FUN, 30, slowdraw_complete, slowdraw_abort, FUNC );
        timer->buffer->target = victim;
        ch_println( ch, "You begin to slowly ease your blaster out of its holster..." );
    }
}

/*
    Slow learning, to desired degree.

    lvl is the degree of difficulty

    Makes adepting the skill more valuable
    (Orion       April 29, 2004)
*/

void learn_slow( CHAR_DATA* ch, SKILL_DATA* skill, int lvl )
{
    learn_slow_ex( ch, skill, lvl, false );
}

/*  Note to future generations.  Force apprentice learning passes
    THROUGH this function.  That is, if you do something to prevent
    someone who is already adept from calling learn_from_success,
    you will prevent the padawans from picking up their masters skills.
    Dont make the same mistake I did! ~Miros
*/
void learn_slow_ex( CHAR_DATA* ch, SKILL_DATA* skill, int lvl, bool assured ) // miros was here
{
    int chance = 100;
    int roll = 0;

    if ( !ch || !skill )
        return;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        return;

    switch ( lvl )
    {
        default:
            bug( "Learn_slow - %d out of range. (1-6)", lvl );
            return;

        case 1:
            chance -= 30;
            break;

        case 2:
            chance -= 40;
            break;

        case 3:
            chance -= 60;
            break;

        case 4:
            chance -= 80;
            break;

        case 5:
            chance -= 95;
            break;

        case 6: // A lifetime to master.
            chance -= 98;
            break;
    }

    roll = number_percent();
    debug( "learn_slow %s - %s roll %d chance %d", ch->name, skill->name, roll, chance );

    if ( roll < chance )
    {
        learn_from_success_ex( ch, skill, assured );
        tune( "learn_slow %s learning %s roll %d chance %d, assured: %s", ch->name, skill->name, roll, chance, ( assured ? "true" : "false" ) );
    }

    return;
}

int what_prof( CHAR_DATA* ch, OBJ_DATA* wield )
{
    int gsn_ptr = 0;

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && wield )
    {
        switch ( wield->value[3] )
        {
            case 9:
                cache_skill( "bowcasters", &skill_bowcasters );
                cache_skill( "advanced bowcaster", &skill_advanced_bowcaster );
                cache_skill( "bowcaster mastery", &skill_bowcaster_mastery );

                if ( get_learned_pct( ch, skill_bowcasters ) > 0 )
                    gsn_ptr = ( int ) get_learned_pct( ch, skill_bowcasters );

                if ( get_learned_pct( ch, skill_advanced_bowcaster ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_advanced_bowcaster ) + 25 );

                if ( get_learned_pct( ch, skill_bowcaster_mastery ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_bowcaster_mastery ) + 50 );

                break;

            case 11:
                cache_skill( "force pikes", &skill_force_pikes );
                cache_skill( "advanced forcepike", &skill_advanced_forcepike );
                cache_skill( "forcepike mastery", &skill_forcepike_mastery );

                if ( get_learned_pct( ch, skill_force_pikes ) > 0 )
                    gsn_ptr = ( int ) get_learned_pct( ch, skill_force_pikes );

                if ( get_learned_pct( ch, skill_advanced_forcepike ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_advanced_forcepike ) + 55 );

                if ( get_learned_pct( ch, skill_forcepike_mastery ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_forcepike_mastery ) + 70 );

                break;

            case 3:
                cache_skill( "lightsabers", &skill_lightsabers );
                cache_skill( "advanced lightsaber", &skill_advanced_lightsaber );
                cache_skill( "lightsaber mastery", &skill_lightsaber_mastery );

                if ( get_learned_pct( ch, skill_lightsabers ) > 0 )
                    gsn_ptr = ( int ) get_learned_pct( ch, skill_lightsabers );

                if ( get_learned_pct( ch, skill_advanced_lightsaber ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_advanced_lightsaber ) + 55 );

                if ( get_learned_pct( ch, skill_lightsaber_mastery ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_lightsaber_mastery ) + 70 );

                break;

            case 2:
                cache_skill( "vibro-blades", &skill_vibroblades );
                cache_skill( "advanced vibroblade", &skill_advanced_vibroblade );
                cache_skill( "vibroblade mastery", &skill_vibroblade_mastery );

                if ( get_learned_pct( ch, skill_vibroblades ) > 0 )
                    gsn_ptr = ( int ) get_learned_pct( ch, skill_vibroblades );

                if ( get_learned_pct( ch, skill_advanced_vibroblade ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_advanced_vibroblade ) + 55 );

                if ( get_learned_pct( ch, skill_vibroblade_mastery ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_vibroblade_mastery ) + 70 );

                break;

            case 6:
                cache_skill( "blasters", &skill_blasters );
                cache_skill( "advanced blaster", &skill_advanced_blaster );
                cache_skill( "blaster mastery", &skill_blaster_mastery );

                if ( get_learned_pct( ch, skill_blasters ) > 0 )
                    gsn_ptr = ( int ) get_learned_pct( ch, skill_blasters );

                if ( get_learned_pct( ch, skill_advanced_blaster ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_advanced_blaster ) + 45 );

                if ( get_learned_pct( ch, skill_blaster_mastery ) > 0 )
                    gsn_ptr = UMAX( gsn_ptr, ( int ) get_learned_pct( ch, skill_blaster_mastery ) + 70 );

                break;

            case 4:
                gsn_ptr = 0;
                break;

            case 5:
                gsn_ptr = 0;
                break;

            case 8:
                gsn_ptr = 0;
                break;

            case 12:
                cache_skill( "disruptors", &skill_disruptors );
                gsn_ptr = get_learned_pct( ch, skill_disruptors );
                break;

            default:
                gsn_ptr = -1;
                break;
        }
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        return 0;

    if ( gsn_ptr == -1 )
    {
        bug( "%s%s using %s (unknown proficiency type)", ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? "(NPC)" : "", ch->name, wield->name );
        gsn_ptr = 0;
    }

    return gsn_ptr;
}
bool wielding_claws( CHAR_DATA* ch )
{
    if ( !ch || ch == NULL )
        return FALSE;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        return FALSE;

    if ( !xIS_SET( ch->race->flags, RFLAG_HASCLAWS ) )
        return FALSE;

    if ( ch->pcdata->dewclaws == FALSE )
        return FALSE;
    else
        return TRUE;
}
bool check_parry_melee( CHAR_DATA* ch, CHAR_DATA* attacker, OBJ_DATA* wep1 )
{
    OBJ_DATA* wep2 = NULL;
    int reversechance = 0;
    int parrychance = 0;
    int ptype = 0;
    char buf[MSL];
    char buf2[MSL];
    char buf3[MSL];

    if ( !ch || ch == NULL )
        return FALSE;

    if ( !attacker || attacker == NULL )
        return FALSE;

    if ( ( !wep1 || wep1 == NULL ) && !wielding_claws( ch ) )
        return FALSE;

    if ( wep1->value[3] == WEAPON_BOWCASTER || wep1->value[3] == WEAPON_BLASTER || wep1->value[3] == WEAPON_LIGHTSABER )
        return FALSE;

    if ( ch == attacker )
        return FALSE;

    if ( ( wep2 = get_eq_char( attacker, WEAR_WIELD ) ) == NULL && !wielding_claws( attacker ) )
    {
        if ( check_dodge( attacker, ch ) )
            return FALSE;
        else
            return FALSE;
    }

    if ( wep2 && ( wep2->value[3] == WEAPON_BOWCASTER || wep2->value[3] == WEAPON_BLASTER ) )
    {
        if ( check_dodge( attacker, ch ) )
            return FALSE;
        else
            return FALSE;
    }

    // 100 ( base weapon skill) up to 170 (with adv and mastery)
    parrychance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : wielding_claws( ch ) ? 100 : wep1 ? what_prof( ch, wep1 ) : 0;

    // 100 ( base weapon skill) up to 170 (with adv and mastery)
    reversechance = ( IS_NPC( attacker ) || IS_SWITCHED_NPC( attacker ) ) ? attacker->top_level / 2 : wielding_claws( attacker ) ? 100 : wep2 ? what_prof( attacker, wep2 ) : 0;

    if ( parrychance == 0 )
        parrychance++;

    if ( reversechance == 0 )
        reversechance++;

    // 0 - 170
    parrychance = number_range( 0, parrychance );

    // Jumps to 0 - 340 for pikes
    if ( wep1 && xIS_SET( wep1->extra_flags, ITEM_NODUAL ) )
        parrychance *= 2;

    // 43-66 with average roll
    reversechance = ( reversechance  / 3 ) + number_range( 1, 20 );

    // reversechance does nothing here, 0-340 minus 4-6? we're just based on number_percent > parrychance.
    if ( number_percent() > ( parrychance - ( reversechance / 10 ) ) || ( wielding_claws( ch ) && wep2->value[3] == WEAPON_LIGHTSABER ) )
        return FALSE;

    if ( parrychance >= reversechance &&
            number_percent() > number_range( reversechance, reversechance * 2 ) )
    {
        act( AT_ACTION, "Your weapon intercepts $N's, knocking it wide.", ch, NULL, attacker, TO_CHAR );
        act( AT_ACTION, "$n's weapon intercepts $N's, knocking it wide.", ch, NULL, attacker, TO_NOTVICT );
        act( AT_ACTION, "$n's weapon intercepts yours, knocking it wide.", ch, NULL, attacker, TO_VICT );
        send_to_char( "You attempt to counter...", ch );
        one_hit( ch, attacker, TYPE_UNDEFINED );
        return TRUE;
    }

    ptype = number_range( 1, 7 );

    switch ( ptype )
    {
        case 1:
            snprintf( buf, MSL, "You bring your weapon up, blocking $N's." );
            snprintf( buf2, MSL, "$n brings $s weapon up, blocking $N's." );
            snprintf( buf3, MSL, "$n brings $s weapon up, blocking yours." );
            break;

        case 2:
            snprintf( buf, MSL, "You feint to your left, bringing your weapon across to intercept $N's." );
            snprintf( buf2, MSL, "$n feints to $s left, bringing $s weapon across to intercept $N's." );
            snprintf( buf3, MSL, "$n feints to $s left, bringing $s weapon across to intercept yours." );
            break;

        case 3:
            snprintf( buf, MSL, "You bring your weapon up, blocking $N's with a resounding TWANG." );
            snprintf( buf2, MSL, "$n brings $s weapon up, blocking $N's with a resounding TWANG." );
            snprintf( buf3, MSL, "$n brings $s weapon up, blocking yours with a resounding TWANG." );
            break;

        case 4:
            snprintf( buf, MSL, "You step back, your weapon striking $N's." );
            snprintf( buf2, MSL, "$n steps back, $s weapon striking $N's." );
            snprintf( buf3, MSL, "$n steps back, $s weapon striking yours." );
            break;

        case 5:
            snprintf( buf, MSL, "You lunge forward, striking $N's weapon with your own." );
            snprintf( buf2, MSL, "$n lunges forward, $s weapon stopping $N's." );
            snprintf( buf3, MSL, "$n lunges forward, $s weapon stopping yours." );
            break;

        case 6:
            snprintf( buf, MSL, "You feint to your right, bringing your weapon down to stop $N's." );
            snprintf( buf2, MSL, "$n feints to $s right, bringing $s weapon down to stop $N's." );
            snprintf( buf3, MSL, "$n feints to $s right, bringing $s weapon down to stop yours." );
            break;

        case 7:
            snprintf( buf, MSL, "You thrust your weapon towards $N's, stopping $S attack." );
            snprintf( buf2, MSL, "$n thrusts $s weapon towards $N's, stopping $S attack." );
            snprintf( buf3, MSL, "$n thrusts $s weapon towards yours, stopping your attack." );
            break;
    }

    act( AT_ACTION, buf, ch, NULL, attacker, TO_CHAR );
    act( AT_ACTION, buf2, ch, NULL, attacker, TO_NOTVICT );
    act( AT_ACTION, buf3, ch, NULL, attacker, TO_VICT );

    if ( wep2 && wep2->value[3] == WEAPON_LIGHTSABER && wep1 && !xIS_SET( wep1->extra_flags, ITEM_CORTOSIS ) )
    {
        if ( number_range( 1, 5 ) > 1 )
        {
            act( AT_ACTION, "Your weapon sizzles as it touches $N's lightsaber!", ch, NULL, attacker, TO_CHAR );
            act( AT_ACTION, "$n's weapon sizzles as it touches $N's lightsaber!", ch, NULL, attacker, TO_NOTVICT );
            act( AT_ACTION, "$n's weapon sizzles as it touches your lightsaber!", ch, NULL, attacker, TO_VICT );

            if ( wep1->value[3] == WEAPON_FORCE_PIKE )
                wep1->value[0] = URANGE( 0, wep1->value[0] - number_range( 2, 4 ), 100 );
            else
                wep1->value[0] = URANGE( 0, wep1->value[0] - number_range( 4, 6 ), 100 );

            if ( wep1->value[0] < 1 )
            {
                act( AT_ACTION, "$p is destroyed by $N's lightsaber!", ch, wep1, attacker, TO_CHAR );
                act( AT_ACTION, "$n's weapon is destroyed by $N's lightsaber!", ch, NULL, attacker, TO_NOTVICT );
                act( AT_ACTION, "$n's weapon is destroyed by your lightsaber!", ch, NULL, attacker, TO_VICT );
                wep1 = make_scraps( wep1 );
            }
        }
    }

    return TRUE;
}
CMDF do_slash( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;
    OBJ_DATA* obj = NULL;
    cache_skill( "slash", &skill_slash );

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) != NULL )
    {
        if ( obj->value[3] != WEAPON_LIGHTSABER && obj->value[3] != WEAPON_VIBRO_BLADE )
        {
            ch_println( ch, "You can't slash with that weapon." );
            return;
        }
    }
    else
    {
        ch_println( ch, "You need to be wielding a weapon that can slash in order to do this." );
        return;
    }

    if ( !argument || argument[0] == '\0' )
    {
        victim = who_fighting( ch );

        if ( !victim )
        {
            ch_println( ch, "You aren't fighting anyone." );
            return;
        }
    }

    if ( !victim || victim == NULL )
    {
        if ( ( victim = get_char_room( ch, argument ) ) == NULL )
        {
            ch_println( ch, "You don't see anyone like that nearby." );
            return;
        }
    }

    if ( ch == victim )
    {
        ch_println( ch, "Slash yourself?" );
        return;
    }

    if ( victim->hit < 1 )
    {
        act( AT_ACTION, "But $E is already down. Use MURDER to finish $M off.", ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( skill_slash && one_hit( ch, victim, skill_slash->id ) == rNONE )
        learn_slow( ch, skill_slash, 2 );

    WAIT_STATE( ch, 30 );
    return;
}

bool chiss_check( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( !ch || !ch->race || !victim )
        return FALSE;

    if ( IS_NPC( victim ) )
        return FALSE;

    if ( str_cmp( ch->race->race_name, "Chiss" ) && !xIS_SET( ch->race->flags, RFLAG_CHISS ) )
        return FALSE;

    if ( !victim->pcdata || !victim->pcdata->account )
        return FALSE;

    if ( xIS_SET( victim->pcdata->account->flags, ACC_CHISS ) )
        return TRUE;

    ch_println( victim, "\n\r&OYou are now eligible to play a Chiss!" );
    ch_println( victim, "&OIf you are interested, please ensure you have no alts in other clans" );
    ch_println( victim, "&Oand then roll a new character with the Chiss race." );
    xSET_BIT( victim->pcdata->account->flags, ACC_CHISS );
    account_save( victim->pcdata->account, true );
    return TRUE;
}

void death_reward( CHAR_DATA* ch, ACCOUNT_DATA *acc )
{
    int points = 0, x = 0;
    int calc_points = 0;
   // char buf[MSL];
    int skills = 0, levels = 0, poss_skills = 0, poss_levels = 0;
    /*  GRAL
        Rework this to reflect RP more perhaps.  We reward the achiever not socializer here.
    */

  /*  acc = account_get_from_char( ch->name );

    if ( !acc && ch->desc && ch->desc->account )
    {
        acc = ch->desc->account;
    }
*/
    if ( !acc )
        return;

    if ( !sysdata.pointsondeath )
        return;

    if ( xIS_SET( acc->flags, ACC_NOPOINTS ) )
    {
        ch_println( ch, "&WYour points have been restricted so you will receive no points for this death." );
        return;
    }

    if ( xIS_SET( ch->race->flags, RFLAG_UNDEAD ) )
    {
        ch_println( ch, "&WYou already received points when you became undead." );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_CG ) )
        return;

    if ( ch->deposit > 0 )
    {
        ch_println( ch, "&WYou receive &C%d &Wpoints back for your deposit!", ch->deposit );
        acc->points += ch->deposit;
        char plogbuf[MIL];
        snprintf( plogbuf, MIL, "Death - Deposit Refund - %s - %s", ch->name, ch->race->race_name );

        if ( account_new_pointlog_sql( plogbuf, acc->name, ch->deposit ) == NULL )
        {
            bug( "Error: null pointlog returned in %s at line %d of %s", __FUNCTION__, __LINE__, __FILE__ );
            return;
        }

        account_save( acc, true );
    }

    if ( ( ch->played / 86400 ) < sysdata.points_days )
        return;

    for ( x = 0; x < MAX_ABILITY; x++ )
    {
        if ( x == FORCE_ABILITY && ch->skill_level[x] < 2 )
            continue;

        poss_levels += max_level( ch, x );
        levels += ch->skill_level[x];
    }

    SKILL_DATA* skill = NULL;

    for ( LEARNED_DATA* learned = ch->first_learned; learned; learned = learned->next )
    {
        if ( ( skill = skill_from_id( learned->id ) ) == NULL )
            continue;

        if ( !skill->name )
            continue;

        if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
            continue;

        if (  get_learned_pct( ch, skill ) <= 0  &&  ch->skill_level[skill->guild] < skill->min_level )
            continue;

        if ( skill->type == SKILL_FEAT )
            continue;

        poss_skills += 100;
        skills += get_learned_pct( ch, skill );
    }

    if ( xIS_SET( ch->race->flags, RFLAG_WARRIOR ) )
    {
        // Because warriors automatically get max level and skill, we don't use those as a component
        // in their points, but weigh their time played more than with normal characters.
        calc_points = ( ch->played / 1500 ) +
                     number_range( 1, 500 );
    }
    else
    {
        calc_points = ( levels * 500 / poss_levels ) +
                     ( skills * 1000 / poss_skills ) +
                     ( ch->played / 2000 ) +
                     number_range( 1, 500 );
    }
    lognormal("Calculated points for %s: %d, before URANGE", ch->name, calc_points);
    points = URANGE(sysdata.points_min, calc_points, sysdata.points_max);
    lognormal("Points for %s after URANGE: %d", ch->name, points);
    acc->points += points;
    char plogbuf[MIL];
    snprintf( plogbuf, MIL, "Death - Point Reward - %s", ch->name );

    if ( account_new_pointlog_sql( plogbuf, acc->name, points ) == NULL )
    {
        bug( "Error: null pointlog returned in %s at line %d of %s", __FUNCTION__, __LINE__, __FILE__ );
        return;
    }

    if ( !str_cmp( last_death->victim, ch->name ) && (NULLSTR(last_death->victaccount) || (!str_cmp( last_death->victaccount, acc->name ) )))
    {
        last_death->points = points + ch->deposit;
        death_save(last_death);

    }
    else
    {
        debug( "death_reward: unable to update deaths records with points for %s because it is not the last death (%s)", ch->name, last_death->victim );
    }

    //ch->deposit = 0;
    ch_println( ch, "&WYour character has qualified for &C%d &Wpoints!", points );
    account_save( acc, true );
}
