int aim_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop aiming." );
    act( AT_ACTION, "$n stops aiming.", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int aim_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    char buf[MSL], buf2[MSL];
    int part_num = buffer->num1;
    CHAR_DATA* victim = buffer->target;
    if ( !same_room( ch, victim ) )
    {
        ch_println( ch, "Your target must have left!" );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    ch->aim = victim;
    ch->aim_part = part_num;

    snprintf( buf, MIL, "$n aims $s weapon at your %s.", part_name( part_num ) );
    act( AT_ACTION, buf, ch, NULL, victim, TO_VICT );
    snprintf( buf, MIL, "$n aims $s weapon at $N's %s.", part_name( part_num ) );
    act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
    ch_println( ch, "You aim your weapon at %s's %s.", g_name( ch->aim, ch ), part_name( part_num ) );
    cache_skill( "aim", &skill_aim );
    learn_from_success( ch, skill_aim );
    snprintf( buf, MSL, "is aiming $s weapon at $N's %s.", part_name( part_num ) );
    snprintf( buf2, MSL, "is aiming $s weapon at your %s.", part_name( part_num ) );
    action_set( ch, victim, buf, buf2, 0 );

    if ( who_fighting( ch ) == NULL )
        ch->aimshot = TRUE;

    return E_LOTJ_SUCCESS;
}

CMDF do_aim( CHAR_DATA* ch, char* argument )
{
    if ( !str_cmp( "stat", argument ) && IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Aiming at: %s\nAim part: %d Which is: %s\n%s", ch->aim ? ch->aim->name : "Nobody", ch->aim_part, part_name( ch->aim_part ), ch->aimshot ? "You have first shot bonus." : "You do not have first shot bonus." );
        return;
    }

    if ( !str_cmp( "none", argument ) && ch->aim )
    {
        ch_println( ch, "You stop aiming." );
        act( AT_ACTION, "$n stops aiming.", ch, NULL, NULL, TO_ROOM );
        clear_aim( ch );
        return;
    }

    if ( !get_eq_char( ch, WEAR_WIELD ) && !get_eq_char( ch, WEAR_DUAL_WIELD ) && !wielding_claws( ch ) )
    {
        ch_println( ch, "You really should have a weapon for this, you know." );
        return;
    }

    char arg[MIL];
    argument = one_argument( argument, arg );

    if ( NULLSTR( argument ) )
    {
        if ( ch->aim )
            ch_println( ch, "You are aiming at %s's %s.", g_name( ch->aim, ch ), part_name( ch->aim_part ) );
        else
            ch_println( ch, "&zSyntax: &Caim <&wvictim&C> <&wbody part&C>" );

        return;
    }

    CHAR_DATA* victim = get_char_room( ch, arg );
    if ( !victim )
    {
        ch_println( ch, "You see nobody like that nearby." );
        return;
    }

    int part_num = -1;
    for ( int x = 0; x <= MED_BACK; x++ )
        if ( !str_cmp( part_name( x ), argument ) )
            part_num = x;

    if ( part_num == -1 )
    {
        ch_println( ch, "That's not a valid bodypart!" );
        return;
    }

    cache_skill( "aim", &skill_aim );
    int tm = get_curr_dex( ch ) + ( int )( get_learned_pct( ch, skill_aim ) / 4 );
    tm /= 2;
    tm += number_range( 1, 8 );
    tm -= ( int )( get_curr_dex( victim ) / 3 );
    tm = ( int )URANGE( 2, ( 30 - tm ), 4 );

    if ( who_fighting( ch ) != NULL )
        tm *= ( int )2;

    action_set( ch, victim, "is drawing a bead on $N.", "is drawing a bead on you!", 0 );
    ch_println( ch, "You start drawing a bead..." );
    act( AT_ACTION, "$n begins drawing a bead on $N.", ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "$n begins drawing a bead on you!", ch, NULL, victim, TO_VICT );

    TIMER* timer = add_timer( ch, TIMER_DO_FUN, tm*3, aim_complete, aim_abort, FUNC );
    timer->on_damage_interrupt = false;
    timer->buffer->target = victim;
    timer->buffer->num1 = part_num;
}


