        case 4:
            return "right hand";

        case 5:
            return "left wrist";

        case 6:
            return "right wrist";

        case 7:
            return "left arm";

        case 8:
            return "right arm";

        case 9:
            return "left leg";

        case 10:
            return "right leg";

        case 11:
            return "neck";

        case 12:
