    }
}
bool check_wound( CHAR_DATA* ch, CHAR_DATA* victim )
{
    cache_skill( "aim", &skill_aim );
    cache_skill( "duelist", &skill_duelist );
    int chance = ( int ) get_learned_pct( ch, skill_aim );
    int chanceBonus = 0;
    char buf[MSL];

    if ( has_feat( ch, skill_duelist ) )
    {
        if ( get_eq_char( ch, WEAR_WIELD ) )
            if ( get_eq_char( ch, WEAR_WIELD )->item_type == ITEM_WEAPON )
                if ( get_eq_char( ch, WEAR_WIELD )->value[3] == WEAPON_BLASTER )
                    if ( !xIS_SET( get_eq_char( ch, WEAR_WIELD )->extra_flags, ITEM_NODUAL ) )
                        chanceBonus = chance / 10 * 3;
    }

    if ( ch->aimshot )
    {
        chance += ( int ) 2 * ( chance / 3 );
        ch->aimshot = FALSE;
    }

    switch ( ch->aim_part )
    {
        case 0:
            chance -= ( int )( ( get_curr_dex( victim ) + get_curr_lck( victim ) ) / 2 );

            if ( number_range( 80, 250 ) > chance )
                return FALSE;

            ch_println( ch, "&YYou score a headshot!" );
            ch_println( victim, "%s hits you in the head!", g_name( ch, victim ) );

            if ( number_range( 1, 35 ) > get_curr_lck( victim ) )
            {
                ch_println( ch, "&RYou wound %s's %s!", g_name( victim, ch ), part_name( ch->aim_part ) );
                ch_println( victim, "&RYou have sustained an injury to your %s!", part_name( ch->aim_part ) );
                xSET_BIT( victim->w_wound, ch->aim_part );
                make_bloodstain( victim );
            }

            return TRUE;

        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
            if ( number_range( 60, 140 ) > chance )
                return FALSE;

            if ( number_range( 1, 35 ) > get_curr_lck( victim ) )
            {
                ch_println( ch, "&RYou wound %s's %s!", g_name( victim, ch ), part_name( ch->aim_part ) );
                ch_println( victim, "&RYou have sustained an injury to your %s!", part_name( ch->aim_part ) );
                xSET_BIT( victim->w_wound, ch->aim_part );
                make_bloodstain( victim );

                if ( ch->aim_part > 2 )
                {
                    OBJ_DATA* obj = NULL;
                    obj = get_eq_char( victim, WEAR_WIELD );

                    if ( !obj )
                        obj = get_eq_char( victim, WEAR_DUAL_WIELD );

                    if ( obj )
                    {
                        if ( !check_grip( ch, victim ) )
                        {
                            act( AT_ACTION, "$N's weapon is knocked from $S grasp!", ch, NULL, victim, TO_NOTVICT );
                            ch_println( ch, "You manage to disarm %s!", g_name( victim, ch ) );
                            act( AT_ACTION, "Your weapon is knocked from your hand!\n", ch, NULL, victim, TO_VICT );
                            unequip_char( victim, obj );
                            separate_obj( obj );
                            obj_from_char( obj );
                            obj_to_room( obj, victim->in_room );
                        }
                    }
                }
            }

            snprintf( buf, MSL, "$n hits $N in the %s!\n", part_name( ch->aim_part ) );
            act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
            ch_println( ch, "You hit %s in the %s.", g_name( victim, ch ), part_name( ch->aim_part ) );
            ch_println( victim, "%s hits you in the %s!", g_name( ch, victim ), part_name( ch->aim_part ) );
            return TRUE;

        case 9:
        case 10:
        case 7:
        case 8:
            if ( number_range( 50, 120 ) > chance + chanceBonus )
                return FALSE;

            if ( number_range( 1, 35 ) > get_curr_lck( victim ) )
            {
                ch_println( ch, "&RYou wound %s's %s!", g_name( victim, ch ), part_name( ch->aim_part ) );
                ch_println( victim, "&RYou have sustained an injury to your %s!", part_name( ch->aim_part ) );
                xSET_BIT( victim->w_wound, ch->aim_part );
                make_bloodstain( victim );
            }

            snprintf( buf, MSL, "$n hits $N in the %s!\n", part_name( ch->aim_part ) );
            act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
            ch_println( ch, "You hit %s in the %s.", g_name( victim, ch ), part_name( ch->aim_part ) );
            ch_println( victim, "%s hits you in the %s!", g_name( ch, victim ), part_name( ch->aim_part ) );
            return TRUE;

        case 11:
        case 12:
            if ( number_range( 65, 170 ) > chance + chanceBonus )
                return FALSE;

            if ( number_range( 1, 35 ) > get_curr_lck( victim ) )
            {
                ch_println( ch, "&RYou wound %s's %s!", g_name( victim, ch ), part_name( ch->aim_part ) );
                ch_println( victim, "&RYou have sustained an injury to your %s!", part_name( ch->aim_part ) );
                xSET_BIT( victim->w_wound, ch->aim_part );
                make_bloodstain( victim );
            }

            snprintf( buf, MSL, "$n hits $N in the %s!\n", part_name( ch->aim_part ) );
            act( AT_ACTION, buf, ch, NULL, victim, TO_NOTVICT );
            ch_println( ch, "You hit %s in the %s.", g_name( victim, ch ), part_name( ch->aim_part ) );
            ch_println( victim, "%s  hits you in the %s!", g_name( ch, victim ), part_name( ch->aim_part ) );
            return TRUE;

        default:
            return FALSE;
    }
}
