{
    if ( xIS_SET( ch->w_wound, MED_L_HAND ) ||
            xIS_SET( ch->w_wound, MED_R_HAND ) ||
            xIS_SET( ch->w_wound, MED_L_WRIST ) ||
            xIS_SET( ch->w_wound, MED_R_WRIST ) ||
