int handwound_count( CHAR_DATA* ch )
{
    int x = 0, y = 0;

    for ( x = 3; x <= 8; x++ )
        if ( xIS_SET( ch->w_wound, x ) )
            y++;

    return y;
}


int death_save( DEATH_DATA *death) {
    return upsert_sql_fieldmap_row( DB_TABLE_DEATHS, death, death_fields, NO_FLAG );
}
int death_sql_load( const PGresult* res, int row ) {
    DEATH_DATA *death = NULL;
    CREATE( death, DEATH_DATA, 1 );
    int rval;
    if ( ( rval = fieldmap_postgres_row( res, row, death, death_fields ) ) != E_LOTJ_SUCCESS ) {
        FREE_STRUCT( death, death_fields );
        return rval;
    }

    LINK( death, first_death, last_death, next, prev );
    return E_LOTJ_SUCCESS;
}

int death_load_all_sql() {
    return read_all_rows(DB_TABLE_DEATHS, death_sql_load, NULL );
}

void add_death( CHAR_DATA* ch, CHAR_DATA* killer )
{
    DEATH_DATA* death = NULL;

    if ( !ch || IS_NPC(ch) || !killer )
        return;

    // If the killer is a player droid, for example, give their master the credit
    if ( IS_NPC( killer ) && valid_char( killer->master ) )
        killer = killer->master;

    // Do this twice, in case of nested follows
    if ( IS_NPC( killer ) && valid_char( killer->master ) )
        killer = killer->master;

    CREATE( death, DEATH_DATA, 1 );    
    SET_STRING( death->victim, ch->name );

    if  ( IS_NPC( killer ) || IS_SWITCHED_NPC( killer ) )
        SET_STRING( death->killer, killer->short_descr );
    else
        SET_STRING( death->killer, killer->name );

    death->room = ch->in_room ? ch->in_room->vnum : 0;
    death->time = time( 0 );
    death->victtrust = get_trust( ch );
    death->killertrust = get_trust( killer );
    SET_STRING( death->victclan, ch->pcdata->clan ? ch->pcdata->clan->name : "No Clan" );

    if ( IS_NPC(killer) || IS_SWITCHED_NPC( killer ) || !killer->pcdata->clan )
        SET_STRING( death->killerclan, "No Clan" );
    else
        SET_STRING( death->killerclan, killer->pcdata->clan->name );

    if ( ch->desc && ch->desc->account )
        SET_STRING( death->victaccount, ch->desc->account->name );
    else if ( ch->pcdata->account )
        SET_STRING( death->victaccount, ch->pcdata->account->name );
    else
        SET_STRING( death->victaccount, "No Account" );

    if ( killer->desc && killer->desc->account )
        SET_STRING( death->killeraccount, killer->desc->account->name );
    else if ( killer->pcdata && killer->pcdata->account )
        SET_STRING( death->killeraccount, killer->pcdata->account->name );
    else
        SET_STRING( death->killeraccount, "No Account" );

    death->points = 0;
    if ( ch->pcdata->last_clone == 1 )
        death->has_clone = TRUE;
    else
    {
        // Timer for when owned resources should revert to unowned
        // Random amount of time between 7-14 days
        int min_delay = 60*60*24*7;  // 7 days
        int max_delay = 60*60*24*14; // 14 days
        death->expiration = time( 0 ) + number_range( min_delay, max_delay );
        set_bounty_expirations( ch->name, death->expiration );
        death->has_clone = FALSE;
    }

    death->victrace = ch->race->id;
    death->killerrace = killer->race->id;
    death->victimid = ch->id;
    if ( !IS_NPC( killer ) && !IS_SWITCHED_NPC( killer ) )
        death->killerid = killer->id;
    else
        death->killerid = 0;
    LINK( death, first_death, last_death, next, prev );
    death_save( death );
    return;
}

void save_follows( void )
{
    CHAR_DATA* vch = NULL;
    DB_DATA* follow = NULL;

    for ( vch = first_char; vch; vch = vch->next )
    {
        if ( ( !IS_NPC( vch ) && !IS_SWITCHED_NPC( vch ) ) && vch->master && !get_follow( vch->name ) && ( !IS_NPC( vch->master ) && !IS_SWITCHED_NPC( vch->master ) ) )
        {
            CREATE( follow, DB_DATA, 1 );
            SET_STRING( follow->name, vch->name );

            if ( vch->leader )
                follow->num1 = 1;

            SET_STRING( follow->str1, vch->master->name );
            SET_STRING( follow->str2, "" );
            save_dbase_sql("follows",follow);
            LINK( follow, first_follow, last_follow, next, prev );
        }
        else if ( vch->ai_data && !get_follow( vch->ai_data->shortname ) && vch->master )
        {
            CREATE( follow, DB_DATA, 1 );
            SET_STRING( follow->name, vch->ai_data->shortname );

            if ( vch->leader )
                follow->num1 = 1;

            SET_STRING( follow->str1, vch->master->name );
            SET_STRING( follow->str2, "" );
            save_dbase_sql("follows",follow);
            LINK( follow, first_follow, last_follow, next, prev );
        }
    }

}
void load_follows( void )
{
    CHAR_DATA* vch = NULL, *tch = NULL;
    DB_DATA* follow = NULL, *f_next = NULL;
    load_dbdata_table( "follows", &first_follow, &last_follow );
    for ( follow = first_follow; follow; follow = f_next )
    {
        f_next = follow->next;

        for ( vch = first_char; vch; vch = vch->next )
        {
            if ( !str_cmp( vch->name, follow->name ) )
                break;

            if ( vch->ai_data && !str_cmp( vch->ai_data->shortname, follow->name ) )
                break;
        }

        for ( tch = first_char; tch; tch = tch->next )
            if ( !str_cmp( tch->name, follow->str1 ) )
                break;

        if ( !vch || !tch )
        {
            delete_dbase_sql("follows",follow);
            UNLINK( follow, first_follow, last_follow, next, prev );
            extract_db( follow );
            continue;
        }

        stop_follower( vch, false );
        add_follower( vch, tch, false );

        if ( follow->num1 == 1 )
            vch->leader = tch;
    }

    for ( follow = first_follow; follow; follow = f_next )
    {
        f_next = follow->next;
        delete_dbase_sql("follows",follow);
        UNLINK( follow, first_follow, last_follow, next, prev );
        extract_db( follow );
    }
}

DB_DATA* get_follow( char* name )
{
    DB_DATA* db = NULL;

    for ( db = first_follow; db; db = db->next )
        if ( !str_cmp( db->name, name ) )
            return db;

    return NULL;
}

bool isFighting( CHAR_DATA* ch )
{
    if ( !ch || ch->fight_timer == 0 || ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
        return false;

    return true;
}
void startFighting( CHAR_DATA* ch, CHAR_DATA* vic )
{
    if ( !ch || ( vic && ch == vic ) )
        return;

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !vic || ( !IS_NPC( vic ) && !IS_SWITCHED_NPC( vic ) ) ) )
        ch->fight_timer = 60 * 3; // 3 min fight timer!! :)

    if ( vic && ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( vic ) && !IS_SWITCHED_NPC( vic ) ) )
        vic->fight_timer = 60 * 3;
}
