int count_saberforms( CHAR_DATA* ch )
{
    LEARNED_DATA* learned = NULL;
    SKILL_DATA* skill = NULL;
    int cnt = 0;

    if ( !ch )
        return 0;

    for ( learned = ch->first_learned; learned; learned = learned->next )
    {
        if ( learned->pct <= 0 )
            continue;

        skill = skill_from_id( learned->id );

        if ( !skill || skill->type != SKILL_LIGHTSABER_FORM )
            continue;

        cnt++;
    }

    return cnt;
}

CMDF do_saberform( CHAR_DATA* ch, char* argument )
{
    char buf[MIL], buf2[MIL], arg[MIL];
    int val = -1;
    SKILL_DATA* skill = NULL;
    OBJ_DATA* weapon = NULL;

    if ( !ch )
        return;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Huh?" );
        return;
    }

    argument = one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Csaberform <&wform name/#&C>" );
        ch_println( ch, "\n&zValid forms:" );
        for ( int i = 0; lightsaber_forms[i].flag != LAST_FLAG_VALUE; i++ )
            ch_println( ch, "&z%-2d - &C%s", i, lightsaber_forms[i].desc );

        return;
    }

    weapon = get_eq_char( ch, WEAR_WIELD );

    if ( !weapon || weapon->value[3] != WEAPON_LIGHTSABER  )
    {
        ch_println( ch, "&RYou must be wielding a lightsaber to change forms." );
        return;
    }

    val = get_flag( arg, lightsaber_forms );

    if ( val == FLAG_UNDEFINED )
    {
        ch_println( ch, "&RInvalid lightsaber form." );
        ch_println( ch, "\n&zValid forms:" );
        for ( int i = 0; lightsaber_forms[i].flag != LAST_FLAG_VALUE; i++ )
            ch_println( ch, "&z%-2d - &C%s", i, lightsaber_forms[i].desc );
        return;   
    }

    if ( val == FORM_NONE )
    {
        ch_println( ch, "&wYou release your held form and take a neutral stance." );
        ch->lightsaber_form = FORM_NONE;
        save_char_obj( ch, true );
        return;
    }

    skill = skill_from_lightsaber_form( val );

    if ( get_learned_pct( ch, skill ) <= 0 )
    {
        ch_println( ch, "&RYou don't know the %s form.", flag_value_desc( lightsaber_forms, val ) );
        return;
    }

    if ( ch->move < 100 )
    {
        ch_println( ch, "You're too tired to do that right now." );
        return;
    }

    if ( ch->position != POS_STANDING && ch->position != POS_FIGHTING )
    {
        ch_println( ch, "You're not in a good position to do that." );
        return;
    }

    int chance = ( int ) ( get_learned_pct( ch, skill ) );

    if ( number_percent( ) > chance * 2 )
    {
        ch_println( ch, "&RYou fumble around but can't quite find the right stance." );
        learn_from_failure( ch, skill );
        return;
    }

    ch->lightsaber_form = val;
    save_char_obj( ch, true );

    snprintf( buf, MIL, "%s", lightsaber_form_messages[ch->lightsaber_form].stance_msg[0] );
    snprintf( buf2, MIL, "%s", lightsaber_form_messages[ch->lightsaber_form].stance_msg[1] );
    act( AT_ACTION, buf, ch, NULL, NULL, TO_CHAR );
    act( AT_ACTION, buf2, ch, NULL, NULL, TO_NOTVICT );
    return;
}

void clear_apprentices( const char* name )
{
    FORCER_DATA* forcer = NULL;

    if ( NULLSTR( name ) )
        return;

    for ( forcer = first_forcer; forcer; forcer = forcer->next )
        if ( !str_cmp( forcer->master, name ) )
            remove_force_master( forcer );

    return;
}

int forcer_load_sql( const PGresult *res, int row )
{
    FORCER_DATA* forcer = NULL;
    int rval;
    CREATE(forcer, FORCER_DATA, 1);
    if ( ( rval = fieldmap_postgres_row( res, row, forcer, forcer_fields ) ) != E_LOTJ_SUCCESS )
    {
        FREE_STRUCT( forcer, forcer_fields );
        return rval;
    }

    LINK( forcer, first_forcer, last_forcer, next, prev );
    return E_LOTJ_SUCCESS;
}

int forcer_save( FORCER_DATA* forcer, bool queue )
{
    if ( !forcer )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( queue && forcer->id > 0 && sysdata.save_queues )
    {
        forcer->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    forcer->save_queued = FALSE;
    return upsert_sql_fieldmap_row(DB_TABLE_FORCERS, forcer, forcer_fields, NO_FLAG);
}

int forcer_unload( FORCER_DATA* forcer )
{
    if ( !forcer )
        return E_LOTJ_MISSING_ARGUMENTS;

    UNLINK( forcer, first_forcer, last_forcer, next, prev );
    FREE_STRUCT( forcer, forcer_fields );
    return E_LOTJ_SUCCESS;
}

int forcer_delete( FORCER_DATA* forcer )
{
    if ( !forcer )
        return E_LOTJ_MISSING_ARGUMENTS;

    clear_apprentices( forcer->name );

    int rcode = delete_sql_row_by_id( DB_TABLE_FORCERS, forcer->id );

    if ( rcode != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to delete forcer, code %s", FUNC, lotj_strerror( rcode ) );
        return rcode;
    }

    return forcer_unload( forcer );
}

//get or make force db entry by char
FORCER_DATA* forcer_create( CHAR_DATA* ch )
{
    FORCER_DATA* forcer = NULL;
    bool mod = FALSE;

    if ( !ch || IS_NPC( ch ) || NULLSTR( ch->name ) )
        return NULL;

    forcer = forcer_get( ch->name );

    if ( !forcer )
    {
        CREATE( forcer, FORCER_DATA, 1 );
        LINK( forcer, first_forcer, last_forcer, next, prev );
        SET_STRING( forcer->name, ch->name );
        SET_STRING( forcer->master, NULL );
        mod = TRUE;
    }

    if ( forcer->frank != ch->pcdata->frank )
    {
        forcer->frank = ch->pcdata->frank;
        mod = TRUE;
    }

    if ( forcer->fclass != ch->pcdata->fclass )
    {
        forcer->fclass = ch->pcdata->fclass;
        mod = TRUE;
    }

    if ( forcer->curr_level != ch->skill_level[FORCE_ABILITY] )
    {
        forcer->curr_level = ch->skill_level[FORCE_ABILITY];
        mod = TRUE;
    }

    if ( forcer->max_level != ( ch->perm_frc * 5 ) )
    {
        forcer->max_level = ch->perm_frc * 5;
        mod = TRUE;
    }

    if ( forcer->perm_frc != ch->perm_frc )
    {
        forcer->perm_frc = ch->perm_frc;
        mod = TRUE;
    }

    if ( forcer->alignment != ch->alignment )
    {
        forcer->alignment = ch->alignment;
        mod = TRUE;
    }

    if ( ch->pcdata->clan && ( NULLSTR( forcer->clan ) || str_cmp( ch->pcdata->clan->name, forcer->clan ) ) )
    {
        SET_STRING( forcer->clan, ch->pcdata->clan->name );
        mod = TRUE;
    }

    if ( mod )
        forcer_save( forcer, TRUE );

    return forcer;
}

FORCER_DATA* forcer_get( char* name )
{
    FORCER_DATA* forcer = NULL;

    for ( forcer = first_forcer; forcer; forcer = forcer->next )
        if ( !str_cmp( forcer->name, name ) )
            break;

    return forcer;
}

FORCER_DATA* forcer_get_apprentice( CHAR_DATA* ch, bool inroom )
{
    CHAR_DATA* victim = NULL;
    FORCER_DATA* forcer;
    char buf[MSL];
    strlcpy( buf, "", MSL );

    if ( !ch || ( inroom && !ch->in_room ) )
        return NULL;

    for ( forcer = first_forcer; forcer; forcer = forcer->next )
    {
        if ( !forcer->master )
            continue;

        if ( !str_cmp( forcer->master, ch->name ) )
        {
            if ( !inroom )
                return forcer;
            else
            {
                victim = get_player_world( forcer->name );

                if ( victim != NULL && victim->in_room && victim->in_room == ch->in_room )
                    return forcer;
            }
        }
    }

    return NULL;
}

/*
    Is immune to a damage type
*/
bool is_immune( CHAR_DATA* ch, sh_int damtype )
{
    switch ( damtype )
    {
        case SD_FIRE:
            return ( xIS_SET( ch->immune, RIS_FIRE ) );

        case SD_COLD:
            return ( xIS_SET( ch->immune, RIS_COLD ) );

        case SD_ELECTRICITY:
            return ( xIS_SET( ch->immune, RIS_ELECTRICITY ) );

        case SD_ENERGY:
            return ( xIS_SET( ch->immune, RIS_ENERGY ) );

        case SD_ACID:
            return ( xIS_SET( ch->immune, RIS_ACID ) );

        case SD_POISON:
            return ( xIS_SET( ch->immune, RIS_POISON ) );

        case SD_DRAIN:
            return ( xIS_SET( ch->immune, RIS_DRAIN ) );
    }

    return FALSE;
}

/*
    Lookup a skill by slot number.
    Used for object loading.
*/
int slot_lookup( int slot )
{
    extern bool fBootDb;
    SKILL_DATA* skill = NULL;

    if ( slot <= 0 )
        return -1;

    for ( skill = first_skill; skill; skill = skill->next )
        if ( slot == skill->slot )
            return skill->id;

    if ( fBootDb )
    {
        bug( "Slot_lookup: bad slot %d.", slot );
        abort( );
    }

    return -1;
}

int standard_force_success_rate( CHAR_DATA* ch, SKILL_DATA* skill )
{
    if ( IS_NPC( ch ) )
    {
        if ( IS_CONTROLLED( ch ) )
            return 0;

        return ( int ) ch->top_level;
    }

    return ( int ) get_learned_pct( ch, skill );
}

/*
    Fancy message handling for a successful casting      -Thoric
*/
void successful_casting( SKILL_DATA* skill, CHAR_DATA* ch, CHAR_DATA* victim, OBJ_DATA* obj )
{
    sh_int chitroom = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_ACTION );
    sh_int chit     = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HIT );
    sh_int chitme   = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HITME );

    if ( skill->target != TAR_CHAR_OFFENSIVE )
    {
        chit = chitroom;
        chitme = chitroom;
    }

    if ( ch && ch != victim )
    {
        if ( !NULLSTR( skill->hit_char ) )
            act( chit, skill->hit_char, ch, obj, victim, TO_CHAR );
    }

    if ( ch && !NULLSTR( skill->hit_room ) )
        act( chitroom, skill->hit_room, ch, obj, victim, TO_NOTVICT );

    if ( ch && victim && !NULLSTR( skill->hit_vict ) )
    {
        if ( ch != victim )
            act( chitme, skill->hit_vict, ch, obj, victim, TO_VICT );
        else
            act( chitme, skill->hit_vict, ch, obj, victim, TO_CHAR );
    }
    else if ( ch && ch == victim && skill->type == SKILL_SKILL )
    {
        if ( !NULLSTR( skill->hit_char ) )
            act( chit, skill->hit_char, ch, obj, victim, TO_CHAR );
    }
}

/*
    Fancy message handling for a failed casting          -Thoric
*/
void failed_casting( SKILL_DATA* skill, CHAR_DATA* ch, CHAR_DATA* victim, OBJ_DATA* obj )
{
    sh_int chitroom = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_ACTION );
    sh_int chit     = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HIT );
    sh_int chitme   = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HITME );

    if ( skill->target != TAR_CHAR_OFFENSIVE )
    {
        chit = chitroom;
        chitme = chitroom;
    }

    if ( ch && ch != victim )
    {
        if ( !NULLSTR( skill->miss_char ) )
            act( chit, skill->miss_char, ch, obj, victim, TO_CHAR );
        else if ( skill->type == SKILL_SPELL )
            act( chit, "You failed.", ch, NULL, NULL, TO_CHAR );
    }

    if ( ch && !NULLSTR( skill->miss_room ) )
        act( chitroom, skill->miss_room, ch, obj, victim, TO_NOTVICT );

    if ( ch && victim && !NULLSTR( skill->miss_vict ) )
    {
        if ( ch != victim )
            act( chitme, skill->miss_vict, ch, obj, victim, TO_VICT );
        else
            act( chitme, skill->miss_vict, ch, obj, victim, TO_CHAR );
    }
    else if ( ch && ch == victim )
    {
        if ( !NULLSTR( skill->miss_char ) )
            act( chitme, skill->miss_char, ch, obj, victim, TO_CHAR );
        else if ( skill->type == SKILL_SPELL )
            act( chitme, "You failed.", ch, NULL, NULL, TO_CHAR );
    }
}

/*
    Fancy message handling for being immune to something     -Thoric
*/
void immune_casting( SKILL_DATA* skill, CHAR_DATA* ch, CHAR_DATA* victim, OBJ_DATA* obj )
{
    sh_int chitroom = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_ACTION );
    sh_int chit     = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HIT );
    sh_int chitme   = ( skill->type == SKILL_SPELL ? AT_MAGIC : AT_HITME );

    if ( skill->target != TAR_CHAR_OFFENSIVE )
    {
        chit = chitroom;
        chitme = chitroom;
    }

    if ( ch && ch != victim )
    {
        if ( !NULLSTR( skill->imm_char ) )
            act( chit, skill->imm_char, ch, obj, victim, TO_CHAR );
        else if ( !NULLSTR( skill->miss_char ) )
            act( chit, skill->hit_char, ch, obj, victim, TO_CHAR );
        else if ( skill->type == SKILL_SPELL || skill->type == SKILL_SKILL )
            act( chit, "That appears to have no effect.", ch, NULL, NULL, TO_CHAR );
    }

    if ( ch && !NULLSTR( skill->imm_room ) )
        act( chitroom, skill->imm_room, ch, obj, victim, TO_NOTVICT );
    else if ( ch && !NULLSTR( skill->miss_room ) )
        act( chitroom, skill->miss_room, ch, obj, victim, TO_NOTVICT );

    if ( ch && victim && !NULLSTR( skill->imm_vict ) )
    {
        if ( ch != victim )
            act( chitme, skill->imm_vict, ch, obj, victim, TO_VICT );
        else
            act( chitme, skill->imm_vict, ch, obj, victim, TO_CHAR );
    }
    else if ( ch && victim && !NULLSTR( skill->miss_vict ) )
    {
        if ( ch != victim )
            act( chitme, skill->miss_vict, ch, obj, victim, TO_VICT );
        else
            act( chitme, skill->miss_vict, ch, obj, victim, TO_CHAR );
    }
    else if ( ch && ch == victim )
    {
        if ( !NULLSTR( skill->imm_char ) )
            act( chit, skill->imm_char, ch, obj, victim, TO_CHAR );
        else if ( !NULLSTR( skill->miss_char ) )
            act( chit, skill->hit_char, ch, obj, victim, TO_CHAR );
        else if ( skill->type == SKILL_SPELL || skill->type == SKILL_SKILL )
            act( chit, "That appears to have no affect.", ch, NULL, NULL, TO_CHAR );
    }
}


/*
    When this was Smaug, say_spell was for a muttering.
    LOTJ uses it to show a disturbance in the force.     -Orion
*/
void say_spell( CHAR_DATA* ch )
{
    CHAR_DATA* rch = NULL;
    DESCRIPTOR_DATA* d = NULL;

    //I swapped the order of disturbance and the following message. Mostly because it made implementing JEDI_SENTINEL bonus easier and more clean. - Gathorn 14Jan2017
    if ( ch->race == get_race_by_name( "Dathomiri" ) )
        ch_println( ch, "&WYou call upon the power of your magic..." );
    else
        ch_println( ch, "&BYou focus your mind..." );

    if ( ( IS_SENTINEL( ch ) || IS_ASSASSIN ( ch ) ) && ch->pcdata->frank >= FRANK_KNIGHT ) //If JEDI_SENTINE/SITH_ASSASSIN Knights and above do not continue on to give disturbances. Part of Jan 2017 subclass upgrade. - Gathorn 14Jan2017
        return;

    /* Instead of looping first_char <-> last_char, stick to descs */
    for ( d = first_descriptor; d ; d = d->next )
    {
        if ( d->connected != CON_PLAYING && d->connected != CON_EDITING )
            continue;

        if ( ( rch = d->character ) == NULL )
            continue;

        if ( rch == ch )
            continue;

        if ( get_trust( rch ) >= sysdata.log_level || get_trust( ch ) >= sysdata.log_level )
            continue;

        /* Eliminate all crashes? Lets hope. */
        if ( in_starsystem( rch ) != in_starsystem( ch ) || in_starsystem( rch ) == NULL )
            continue;

        if ( ( int ) rch->skill_level[FORCE_ABILITY] < 20 )
            continue;

        if ( number_percent() > ( int ) rch->skill_level[FORCE_ABILITY] )
            continue;

        if ( has_pcflag( rch, PCFLAG_NO_SENSE ) )
            continue;

        ch_println( rch, "&WYou sense a disturbance in the Force." );
    }

    return;
}

/*
    Make adjustments to saving throw based in RIS        -Thoric
*/
int ris_save( CHAR_DATA* ch, int chance, int ris )
{
    sh_int modifier;
    modifier = 10;

    if ( ris == RIS_PARALYSIS )
    {
        if ( xIS_SET( ch->race->flags, RFLAG_RESISTSTUN ) )
            modifier -= 3;
    }

    if ( xIS_SET( ch->immune, ris ) )
        modifier -= 10;

    if ( xIS_SET( ch->resistant, ris ) )
        modifier -= 2;

    if ( xIS_SET( ch->susceptible, ris ) )
        modifier += 2;

    if ( modifier <= 0 )
        return 1000;

    if ( modifier == 10 )
        return chance;

    return ( chance * modifier ) / 10;
}


/*                                  -Thoric
    Fancy dice expression parsing complete with order of operations,
    simple exponent support, dice support as well as a few extra
    variables: L = level, H = hp, M = mana, V = move, S = str, X = dex
              I = int, W = wis, C = con, A = cha, U = luck, A = age

    Used for spell dice parsing, ie: 3d8+L-6

*/
int rd_parse( CHAR_DATA* ch, int level, char* exp )
{
    int x, lop = 0, gop = 0, eop = 0;
    char operation;
    char* sexp[2];
    int total = 0, len = 0;

    /* take care of nulls coming in */
    if ( !exp || !strlen( exp ) )
        return 0;

    /*
        get rid of brackets if they surround the entire expression
    */
    if ( ( *exp == '(' ) && exp[strlen( exp ) - 1] == ')' )
    {
        exp[strlen( exp ) - 1] = '\0';
        exp++;
    }

    /* check if the expresion is just a number */
    len = strlen( exp );

    if ( len == 1 && isalpha( exp[0] ) )
        switch ( exp[0] )
        {
            case 'L':
            case 'l':
                return level;

            case 'H':
            case 'h':
                return ch->hit;

            case 'M':
            case 'm':
                return ch->mana;

            case 'V':
            case 'v':
                return ch->move;

            case 'S':
            case 's':
                return get_curr_str( ch );

            case 'I':
            case 'i':
                return get_curr_int( ch );

            case 'W':
            case 'w':
                return get_curr_wis( ch );

            case 'X':
            case 'x':
                return get_curr_dex( ch );

            case 'C':
            case 'c':
                return get_curr_con( ch );

            case 'A':
            case 'a':
                return get_curr_cha( ch );

            case 'U':
            case 'u':
                return get_curr_lck( ch );
        }

    for ( x = 0; x < len; ++x )
        if ( !isdigit( exp[x] ) && !isspace( exp[x] ) )
            break;

    if ( x == len )
        return ( atoi( exp ) );

    /* break it into 2 parts */
    for ( x = 0; x < ( signed )strlen( exp ); ++x )
        switch ( exp[x] )
        {
            case '^':
                if ( !total )
                    eop = x;

                break;

            case '-':
            case '+':
                if ( !total )
                    lop = x;

                break;

            case '*':
            case '/':
            case '%':
            case 'd':
            case 'D':
                if ( !total )
                    gop =  x;

                break;

            case '(':
                ++total;
                break;

            case ')':
                --total;
                break;
        }

    if ( lop )
        x = lop;
    else if ( gop )
        x = gop;
    else
        x = eop;

    operation = exp[x];
    exp[x] = '\0';
    sexp[0] = exp;
    sexp[1] = ( char* )( exp + x + 1 );
    /* work it out */
    total = rd_parse( ch, level, sexp[0] );

    switch ( operation )
    {
        case '-':
            total -= rd_parse( ch, level, sexp[1] );
            break;

        case '+':
            total += rd_parse( ch, level, sexp[1] );
            break;

        case '*':
            total *= rd_parse( ch, level, sexp[1] );
            break;

        case '/':
            total /= rd_parse( ch, level, sexp[1] );
            break;

        case '%':
            total %= rd_parse( ch, level, sexp[1] );
            break;

        case 'd':
        case 'D':
            total = dice( total, rd_parse( ch, level, sexp[1] ) );
            break;

        case '^':
        {
            int y = rd_parse( ch, level, sexp[1] ), z = total;

            for ( x = 1; x < y; ++x, z *= total );

            total = z;
            break;
        }
    }

    return total;
}

/* wrapper function so as not to destroy exp */
int dice_parse( CHAR_DATA* ch, int level, char* exp )
{
    char buf[MIL];
    strlcpy( buf, exp, MIL );
    return rd_parse( ch, level, buf );
}

/*
    Compute a saving throw.
    Negative apply's make saving throw better.
*/
bool saves_poison_death( int level, CHAR_DATA* victim )
{
    int save;
    save = 50 + ( victim->top_level - level - victim->saving_poison_death ) * 2;
    save = URANGE( 5, save, 95 );
    return chance( victim, save );
}
bool saves_wands( int level, CHAR_DATA* victim )
{
    int save;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
        return TRUE;

    save = 50 + ( victim->top_level - level - victim->saving_wand ) * 2;
    save = URANGE( 5, save, 95 );
    return chance( victim, save );
}
bool saves_para_petri( int level, CHAR_DATA* victim )
{
    int save;
    save = 50 + ( victim->top_level - level - victim->saving_para_petri ) * 2;
    save = URANGE( 5, save, 95 );
    return chance( victim, save );
}
bool saves_breath( int level, CHAR_DATA* victim )
{
    int save;
    save = 50 + ( victim->top_level - level - victim->saving_breath ) * 2;
    save = URANGE( 5, save, 95 );
    return chance( victim, save );
}
bool saves_spell_staff( int level, CHAR_DATA* victim )
{
    int save;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
        return TRUE;

    if ( IS_NPC( victim ) && level > 10 )
        level -= 5;

    save = 50 + ( victim->top_level - level - victim->saving_spell_staff ) * 2;
    save = URANGE( 5, save, 95 );
    return chance( victim, save );
}

// Standard success calculation for most negative affect spells
// Based on caster and target force level, and target int and wis
bool negative_spell_succeeds( CHAR_DATA* ch, SKILL_DATA* skill, CHAR_DATA* victim )
{
    int caster_level = ( int ) ( IS_NPC( ch ) ? ch->top_level : ch->skill_level[FORCE_ABILITY] );
    int victim_level = ( int ) victim->skill_level[FORCE_ABILITY];

    if ( victim_level < 1 )
        victim_level = 1;

    // Against a same-level target, you get a 2/3 chance to succeed, and it adjusts from there.
    int success_chance = ( caster_level * 2 * 100 ) / ( victim_level * 3 );
    success_chance = URANGE( 10, success_chance, 90 );
    int vict_int_wis = get_curr_int( victim ) + get_curr_wis( victim );

    if ( vict_int_wis >= 46 ) // Avg 23 int/wis
        success_chance -= success_chance / 10;
    else if ( vict_int_wis >= 40 ) // Avg 20 int/wis or higher
        success_chance -= success_chance / 15;
    else if ( vict_int_wis <= 30 ) // Avg 15 int/wis or lower
        success_chance += success_chance / 10;

    if ( skill )
        tune( "%s casting %s on %s has a success chance of %d%%", ch->name, skill->name, victim->name, success_chance );

    return number_percent() <= success_chance;
}

int pAbort;

/*
    Locate targets.
*/
void* locate_targets( CHAR_DATA* ch, char* arg, SKILL_DATA* skill, CHAR_DATA** victim, OBJ_DATA** obj )
{
    void* vo    = NULL;
    *victim = NULL;
    *obj    = NULL;

    switch ( skill->target )
    {
        default:
            bug( "%s: bad target for sn %s.", FUNC, skill->name ? skill->name : itoa( skill->id ) );
            return &pAbort;

        case TAR_IGNORE:
            break;

        case TAR_CHAR_OFFENSIVE:
            if ( NULLSTR( arg ) )
            {
                if ( ( *victim = who_fighting( ch ) ) == NULL )
                {
                    ch_println( ch, "Cast the spell on whom?" );
                    return &pAbort;
                }
            }
            else
            {
                if ( ( *victim = get_char_room( ch, arg ) ) == NULL )
                {
                    ch_println( ch, "They aren't here." );
                    return &pAbort;
                }
            }

            if ( is_safe( ch, *victim ) )
                return &pAbort;

            if ( ch == *victim )
            {
                ch_println( ch, "Cast this on yourself?  Okay..." );
                /*
                    ch_println( ch, "You can't do that to yourself." );
                    return &pAbort;
                */
            }

            if ( !IS_NPC( ch ) )
            {
                if ( !IS_NPC( *victim ) )
                {
                    /*  Sheesh! can't do anything
                        ch_println( ch, "You can't do that on a player." );
                        return &pAbort;
                    */
                    if ( get_timer( ch, TIMER_PKILLED ) > 0 )
                    {
                        ch_println( ch, "You have been killed in the last 5 minutes." );
                        return &pAbort;
                    }

                    if ( get_timer( *victim, TIMER_PKILLED ) > 0 )
                    {
                        ch_println( ch, "This player has been killed in the last 5 minutes." );
                        return &pAbort;
                    }
                }

                if ( IS_AFFECTED( ch, AFF_CHARM ) && ch->master == *victim )
                {
                    ch_println( ch, "You can't do that on your own follower." );
                    return &pAbort;
                }
            }

            vo = ( void* ) *victim;
            break;

        case TAR_CHAR_DEFENSIVE:
            if ( NULLSTR( arg ) )
                *victim = ch;
            else
            {
                if ( ( *victim = get_char_room( ch, arg ) ) == NULL )
                {
                    ch_println( ch, "They aren't here." );
                    return &pAbort;
                }
            }

            vo = ( void* ) *victim;
            break;

        case TAR_CHAR_SELF:
            if ( !NULLSTR( arg ) && !nifty_is_name( arg, ch->name ) )
            {
                ch_println( ch, "You cannot cast this spell on another." );
                return &pAbort;
            }

            vo = ( void* ) ch;
            break;

        case TAR_OBJ_INV:
            if ( NULLSTR( arg ) )
            {
                ch_println( ch, "What should the spell be cast upon?" );
                return &pAbort;
            }

            if ( ( *obj = get_obj_carry( ch, arg ) ) == NULL )
            {
                ch_println( ch, "You are not carrying that." );
                return &pAbort;
            }

            vo = ( void* ) *obj;
            break;
    }

    return vo;
}


/*
    The kludgy global is for spells who want more stuff from command line.
*/
char* target_name;

/*
    Cast a spell.  Multi-caster and component support by Thoric
*/
CMDF do_cast( CHAR_DATA* ch, char* argument )
{
    char arg1[MIL], arg2[MIL], buf[MSL], logline[MIL];
    static char staticbuf[MSL];
    strlcpy( staticbuf, "", MSL );
    CHAR_DATA* victim = NULL;
    int mana = 0;
    ch_ret retcode = rNONE;
    bool dont_wait = FALSE;
    SKILL_DATA* skill = NULL;
    DISALLOW_DATA* disallow = NULL;
    struct timeval time_used;
    int freecast_chance = 20; //Used to determine if JEDI_CONSULAR subclass can cast a spell for no mana cost. - Gathorn 28Jan2017

    snprintf( logline, MIL, "%s", ( ch->first_cmdlist && ch->first_cmdlist->str1 ) ? ch->first_cmdlist->str1 : argument );

    /* no ordering charmed mobs to cast spells */
    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't seem to do that right now..." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_NO_MAGIC ) )
    {
        set_char_color( AT_MAGIC, ch );
        ch_println( ch, "Something's blocking your access to the Force..." );
        return;
    }

    target_name = one_argument( argument, arg1 );
    one_argument( target_name, arg2 );

    if ( NULLSTR( arg1 ) )
    {
        ch_println( ch, "Cast which what where?" );
        return;
    }

    if ( !str_cmp( "self", arg1 ) )
    {
        ch_println( ch, "Get a room, sicko." );
        return;
    }

    if ( get_eq_char( ch, WEAR_ABOUT ) != NULL && get_eq_char( ch, WEAR_ABOUT )->value[2] >= 7 )
    {
        ch_println( ch, "You cannot cast spells while in armor heavier than light armor." );
        return;
    }

    skill = skill_from_name( arg1 );

    if ( !skill )
    {
        snprintf( buf, MSL, "force %s", arg1 );
        skill = skill_from_name( buf );
    }

    if ( !skill || ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && get_learned_pct( ch, skill ) <= 0  ) )
    {
        ch_println( ch, "You rack your mind for that spell, but can't find it!" );
        return;
    }

    if ( skill->type != SKILL_SPELL )
    {
        ch_println( ch, "That isn't a Force power." );
        return;
    }

    if ( !skill->spell_fun )
    {
        ch_println( ch, "We didn't finish that one yet..." );
        return;
    }

    if ( !IS_NPC( ch ) && skill && ch->pcdata->first_disallow && ( disallow = is_restricted( ch, skill->name ) ) != NULL )
    {
        if ( NULLSTR( disallow->reason ) )
            ch_println( ch, "&wYou have been restricted from using this force power." );
        else
            ch_println( ch, "&wYou have been restricted from using this force power because: %s", disallow->reason );

        return;
    }

    if ( skill->log == LOG_BUILD || skill->log == LOG_HIGH || skill->log == LOG_ALWAYS )
    {
        /*  Added by Narn to show who is switched into a mob that executes
            a logged command.  Check for descriptor in case force is used. */
        if ( ch->desc && ch->desc->original )
            snprintf( log_buf, MSL, "Log %s (%s): %s", ch->name, ch->desc->original->name, logline );
        else
            snprintf( log_buf, MSL, "Log %s: %s", ch->name, logline );

        log_string_plus( log_buf, skill->log, get_trust( ch ) );
    }

    /*
        Something else removed by Merc           -Thoric
    */
    if ( ch->position < skill->minimum_position )
    {
        switch ( ch->position )
        {
            default:
                ch_println( ch, "You can't concentrate enough." );
                break;

            case POS_SITTING:
                ch_println( ch, "You can't summon enough energy sitting down." );
                break;

            case POS_RESTING:
                ch_println( ch, "You're too relaxed to focus properly." );
                break;

            case POS_FIGHTING:
                ch_println( ch, "You can't concentrate enough while fighting!" );
                break;

            case POS_SLEEPING:
                ch_println( ch, "You dream about great feats of power." );
                break;
        }

        return;
    }

    if ( skill->spell_fun == spell_null )
    {
        ch_println( ch, "You have no knowledge of that ability or power." );
        return;
    }

    if ( !skill->spell_fun )
    {
        ch_println( ch, "You cannot cast that... yet." );
        return;
    }

    if ( has_pcflag( ch, PCFLAG_NO_SENSE ) && str_cmp( skill->name, "force conceal" ) )
    {
        ch_println( ch, "You cannot make use of the Force after you have cut yourself off from it!" );
        return;
    }

    mana = IS_NPC( ch ) ? 0 : skill->min_mana;

    if  ( is_safe( ch, victim ) && skill->target != TAR_CHAR_DEFENSIVE )
    {
        set_char_color( AT_MAGIC, ch );
        ch_println( ch, "You cannot do that to them." );
        return;
    }

    if ( skill->target == TAR_CHAR_OFFENSIVE && IS_AFFECTED( ch, AFF_CALM ) )
    {
        act( AT_MAGIC, "You're too calm to focus on that offensive ability.", ch, NULL, NULL, TO_CHAR );
        return;
    }

    if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && ch->mana < mana )
    {
        ch_println( ch, "The Force is not strong enough within you." );
        return;
    }

    if ( ( IS_CONSULAR( ch ) || IS_SORCERER( ch ) ) && ch->pcdata->frank >= FRANK_KNIGHT && number_percent () <= freecast_chance ) //JEDI_CONSULAR/SITH_SORCERER Knights and above have a 20% chance to cast a spell for free. Part of Jan 2017 subclass upgrade. - Gathorn 14Jan2017
    {
        ch_println( ch, "&wYour mastery of the Force allows you to manipulate it with minimal effort." );
        mana = 0;
    }

    // High chance to fail at any cast with any significant toxicity level
    if ( ch->pcdata && ch->pcdata->blood_toxicity >= 20 )
    {
        if ( number_percent() < 75 )
        {
            if ( get_trust( ch ) < LEVEL_IMMORTAL )  /* so imms dont lose mana */
                ch->mana -= mana;

            ch_println( ch, "Your mind is too scattered to concentrate!" );
            return;
        }
    }

    if ( !str_cmp( skill->name, "cleanse mind" ) ) // Reduced mental state failure chance for cleanse mind.
    {
        if ( number_percent() < ch->mental_state * 2 / 3 )
        {
            if ( get_trust( ch ) < LEVEL_IMMORTAL )  /* so imms dont lose mana */
                ch->mana -= mana;

            ch_println( ch, "Your mind is too scattered to concentrate!" );
            return;
        }
    }
    else if ( ch->mental_state > 70 || number_percent() < ch->mental_state )
    {
        if ( get_trust( ch ) < LEVEL_IMMORTAL )  /* so imms dont lose mana */
            ch->mana -= mana;

        ch_println( ch, "Your mind is too scattered to concentrate!" );
        return;
    }

    if ( str_cmp( skill->name, "ventriloquate" ) )
        say_spell( ch );

    if ( !dont_wait )
        WAIT_STATE( ch, skill->beats );

    /*    if ( !IS_NPC(ch) && abs(ch->alignment - skill->alignment) > 1010 )*/
    if ( !IS_NPC( ch ) && ( ( skill->alignment <= -1000 && ch->alignment > -300 )  ||
                            ( skill->alignment >=  1000 && ch->alignment <  300 )    ) )
    {
        if ( ch->alignment > skill->alignment && get_trust( ch ) < LEVEL_IMMORTAL )
        {
            ch_println( ch, "You do not have enough anger in you." );

            if ( get_trust( ch )  < LEVEL_IMMORTAL ) /* so imms don't lose mana */
                ch->mana -= mana / 2;

            return;
        }

        if (  ch->alignment < skill->alignment && get_trust( ch ) < LEVEL_IMMORTAL )
        {
            ch_println( ch, "Your anger and hatred prevent you from focusing." );

            if ( get_trust( ch )  < LEVEL_IMMORTAL ) /* so imms don't lose mana */
                ch->mana -= mana / 2;

            return;
        }
    }

    if ( !IS_NPC( ch )
            &&   ( number_percent( ) + skill->difficulty * 5 ) > get_learned_pct( ch, skill ) )
    {
        /* Some more interesting loss of concentration messages  -Thoric */
        switch ( number_bits( 2 ) )
        {
            case 0: /* too busy */
                if ( ch->fighting )
                    ch_println( ch, "This round of battle is too hectic to concentrate properly." );
                else
                    ch_println( ch, "You lost your concentration." );

                break;

            case 1: /* irritation */
                if ( number_bits( 2 ) == 0 )
                {
                    switch ( number_bits( 2 ) )
                    {
                        case 0:
                            ch_println( ch, "A tickle in your nose prevents you from keeping your concentration." );
                            break;

                        case 1:
                            ch_println( ch, "An itch on your leg keeps you from properly using the Force." );
                            break;

                        case 2:
                            ch_println( ch, "A nagging thought prevents you from focusing on the Force." );
                            break;

                        case 3:
                            ch_println( ch, "A twitch in your eye disrupts your concentration for a moment." );
                            break;
                    }
                }
                else
                    ch_println( ch, "Something distracts you, and you lose your concentration." );

                break;

            case 2: /* not enough time */
                if ( ch->fighting )
                    ch_println( ch, "There wasn't enough time this round to complete your concentration." );
                else
                    ch_println( ch, "You lost your concentration." );

                break;

            case 3:
                ch_println( ch, "A disturbance in the Force muddles your concentration." );
                break;
        }

        if ( get_trust( ch )  < LEVEL_IMMORTAL ) /* so imms don't lose mana */
            ch->mana -= mana / 2;

        learn_from_failure( ch, skill );
        return;
    }
    else
    {
        /*
            check for immunity to magic if victim is known...
            and it is a TAR_CHAR_DEFENSIVE/SELF spell
            otherwise spells will have to check themselves
        */
        if ( ( skill->target == TAR_CHAR_DEFENSIVE
                ||    skill->target == TAR_CHAR_SELF )
                &&    victim && xIS_SET( victim->immune, RIS_MAGIC ) )
        {
            immune_casting( skill, ch, victim, NULL );
            retcode = rSPELL_FAILED;
        }
        else
        {
            start_timer( &time_used );
            retcode = ( *skill->spell_fun ) ( skill, ch->skill_level[FORCE_ABILITY], ch );
            end_timer( &time_used );
            update_userec( &time_used, &skill->userec );
        }
    }

    if ( retcode == rCHAR_DIED || retcode == rERROR || char_extracted( ch ) )
        return;

    // Don't drain mana when the args were invalid and the spell wasn't really attempted.
    if ( retcode != rINVALID_ARGS )
    {
        ch->mana -= mana;
        spirit_drain( ch, mana );

        if ( retcode != rSPELL_FAILED )
        {
            int force_exp;
            force_exp = skill->min_level * skill->min_level * 10;
            force_exp = URANGE( 0, force_exp, ( exp_level( ch->skill_level[FORCE_ABILITY] + 1 ) - exp_level( ch->skill_level[FORCE_ABILITY] ) ) / 35 );
            force_exp = apply_xp_sink( ch, force_exp, FORCE_ABILITY );

            if ( skill->target == TAR_CHAR_OFFENSIVE && victim && IS_AFFECTED( victim, AFF_CALM ) )
            {
                act( AT_YELLOW, "The assault shakes you out of your calmness.", victim, NULL, NULL, TO_CHAR );
                affect_strip( victim, CHAR_AFFECT, cache_skill( "calm", &skill_calm ) );
            }

            if ( !ch->fighting  )
                ch_println( ch, "You gain %d Force experience.", force_exp );

            gain_exp( ch, force_exp, FORCE_ABILITY, FALSE );
            learn_from_success( ch, skill );
        }
        else
            learn_from_failure( ch, skill );
    }

    /*
        Fixed up a weird mess here, and added double safeguards  -Thoric
    */
    if ( skill->target == TAR_CHAR_OFFENSIVE && !char_extracted( victim ) && victim != ch )
    {
        CHAR_DATA* vch, *vch_next;

        for ( vch = ch->in_room->first_person; vch; vch = vch_next )
        {
            vch_next = vch->next_in_room;

            if ( vch == victim )
            {
                if ( victim->master != ch && !victim->fighting )
                    retcode = multi_hit( victim, ch, TYPE_UNDEFINED );

                break;
            }
        }
    }

    return;
}

void spirit_drain ( CHAR_DATA* ch, int mana )
{
    if ( !ch || !ch->spirit || mana <= 0 )
        return;
    else
        ch->max_hit = URANGE( 0, ch->max_hit - number_range( 1, 3 ), ch->max_hit );

    do_save( ch, "-noalert" );
}

CHAR_DATA* get_local_offensive_target( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim = NULL;

    if ( NULLSTR( argument ) )
    {
        victim = who_fighting( ch );

        if ( !victim )
        {
            ch_println( ch, "Use that ability on which target?" );
            return NULL;
        }
    }
    else
    {
        victim = get_char_room( ch, target_name );

        if ( !victim )
        {
            ch_println( ch, "Unable to find that target." );
            return NULL;
        }
    }

    if ( is_safe( ch, victim ) )
        return NULL;

    return victim;
}

OBJ_DATA* get_local_object_target( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];

    if ( !ch || !ch->in_room || NULLSTR( argument ) )
        return NULL;

    one_argument( argument, arg );
    return get_obj_here( ch, arg );
}

/*
    Cast spells at targets using a magical object.
*/
ch_ret obj_cast_spell( SKILL_DATA* skill, int level, CHAR_DATA* ch, char* arg, OBJ_DATA* obj )
{
    ch_ret retcode = rNONE;
    int levdiff = ch->top_level - level;
    struct timeval time_used;
    CHAR_DATA* victim = NULL;
    victim = get_char_room( ch, arg );

    if ( !victim )
    {
        bug( "obj_cast_spell: invalid passing of victim on %s", ch->name );
        return rNONE;
    }

    if ( !skill )
    {
        bug( "%s: missing skill", FUNC );
        return rERROR;
    }

    if ( !skill->spell_fun )
    {
        bug( "%s: bad skill %s.", FUNC, skill->name ? skill->name : itoa( skill->id ) );
        return rERROR;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_NO_MAGIC ) )
    {
        set_char_color( AT_MAGIC, ch );
        ch_println( ch, "Nothing seems to happen..." );
        return rNONE;
    }

    /*
        Basically this was added to cut down on level 5 players using level
        40 scrolls in battle too often ;)        -Thoric
    */
    if ( ( skill->target == TAR_CHAR_OFFENSIVE
            ||    number_bits( 7 ) == 1 ) /* 1/128 chance if non-offensive */
            &&   !chance( ch, 95 + levdiff ) )
    {
        switch ( number_bits( 2 ) )
        {
            case 0:
                failed_casting( skill, ch, victim, NULL );
                break;

            case 1:
                act( AT_MAGIC, "The $t backfires!", ch, skill->name, victim, TO_CHAR );

                if ( victim )
                    act( AT_MAGIC, "$n's $t backfires!", ch, skill->name, victim, TO_VICT );

                act( AT_MAGIC, "$n's $t backfires!", ch, skill->name, victim, TO_NOTVICT );
                return damage( ch, ch, number_range( 1, level ), TYPE_UNDEFINED );

            case 2:
                failed_casting( skill, ch, victim, NULL );
                break;

            case 3:
                act( AT_MAGIC, "The $t backfires!", ch, skill->name, victim, TO_CHAR );

                if ( victim )
                    act( AT_MAGIC, "$n's $t backfires!", ch, skill->name, victim, TO_VICT );

                act( AT_MAGIC, "$n's $t backfires!", ch, skill->name, victim, TO_NOTVICT );
                return damage( ch, ch, number_range( 1, level ), TYPE_UNDEFINED );
        }

        return rNONE;
    }

    target_name = "";

    switch ( skill->target )
    {
        default:
            bug( "%s: bad target for skill %s.", FUNC, skill->name ? skill->name : itoa( skill->id ) );
            return rERROR;

        case TAR_IGNORE:

            if ( victim )
                target_name = victim->name;
            else if ( obj )
                target_name = obj->name;

            break;

        case TAR_CHAR_OFFENSIVE:
            if ( victim != ch )
            {
                if ( !victim )
                    victim = who_fighting( ch );

                if ( !victim || !IS_NPC( victim ) )
                {
                    ch_println( ch, "You can't do that." );
                    return rNONE;
                }
            }

            if ( ch != victim && is_safe( ch, victim ) )
                return rNONE;

            break;

        case TAR_CHAR_DEFENSIVE:
            if ( victim == NULL )
                victim = ch;

            if ( xIS_SET( victim->immune, RIS_MAGIC ) )
            {
                immune_casting( skill, ch, victim, NULL );
                return rNONE;
            }

            break;

        case TAR_CHAR_SELF:
            if ( xIS_SET( ch->immune, RIS_MAGIC ) )
            {
                immune_casting( skill, ch, victim, NULL );
                return rNONE;
            }

            break;

        case TAR_OBJ_INV:
            if ( obj == NULL )
            {
                ch_println( ch, "You can't do that." );
                return rNONE;
            }

            break;
    }

    /* Need to have it use the greet system. Fix me right, later. Orion */
    target_name = arg;
    start_timer( &time_used );
    retcode = ( *skill->spell_fun ) ( skill, level, ch );
    end_timer( &time_used );
    update_userec( &time_used, &skill->userec );

    if ( retcode == rSPELL_FAILED )
        retcode = rNONE;

    if ( retcode == rCHAR_DIED || retcode == rERROR )
        return retcode;

    if ( char_extracted( ch ) )
        return rCHAR_DIED;

    if ( skill->target == TAR_CHAR_OFFENSIVE
            &&   victim != ch
            &&  !char_extracted( victim ) )
    {
        CHAR_DATA* vch;
        CHAR_DATA* vch_next;

        for ( vch = ch->in_room->first_person; vch; vch = vch_next )
        {
            vch_next = vch->next_in_room;

            if ( victim == vch && !victim->fighting && victim->master != ch )
            {
                retcode = multi_hit( victim, ch, TYPE_UNDEFINED );
                break;
            }
        }
    }

    return retcode;
}

