SPELLF spell_blindness( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    AFFECT_DATA af;
    int tmp;

    if ( SPELL_FLAG( skill, SF_PKSENSITIVE )
            &&  !IS_NPC( ch ) && !IS_NPC( victim ) )
        tmp = level;
    else
        tmp = level;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( IS_AFFECTED( victim, AFF_BLIND ) || saves_spell_staff( tmp, victim ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( is_affected( victim, CHAR_AFFECT, skill ) )
    {
        /* Already affect */
        af.type      = skill->id;
        af.location  = APPLY_HITROLL;
        af.modifier  = -2;
        af.duration  = ( ( 1 + ( level / 3 ) ) * ( int )DUR_CONV ) / 5;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_BLIND );
        affect_join( victim, CHAR_AFFECT, &af );
        ch_println( victim, "&GYour vision worsens and pain flashes in your head..." );

        if ( ch != victim )
            act( AT_MAGIC, "$N clutches at $S eyes, as $S vision is worsened.", ch, NULL, victim, TO_NOTVICT );
    }
    else
    {
        /* Not affected yet! */
        af.type = skill->id;
        af.location  = APPLY_HITROLL;
        af.modifier  = -4;
        af.duration  = ( 1 + ( level / 3 ) ) * ( int )DUR_CONV;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_BLIND );
        affect_join( victim, CHAR_AFFECT, &af );
        ch_println( victim, "&GYour vision blurs and your eyes water.. You're blind!" );

        if ( ch != victim )
            act( AT_MAGIC, "$N doubles over, grasping at $S eyes!\n", ch, NULL, victim, TO_NOTVICT );
    }

    return rNONE;
}


