SPELLF spell_call_lightning( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* vch = NULL, *vch_next = NULL;
    int dam;
    bool ch_died;
    ch_ret retcode = 0;

    if ( !IS_OUTSIDE( ch ) )
    {
        ch_println( ch, "You must be out of doors." );
        return rINVALID_ARGS;
    }

    dam = dice( level / 4, 8 );
    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 100;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    set_char_color( AT_MAGIC, ch );
    ch_println( ch, "Lightning strikes your foes!" );
    act( AT_MAGIC, "$n calls Lightning to strike $s foes!", ch, NULL, NULL, TO_ROOM );
    ch_died = FALSE;

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( !vch->in_room )
            continue;

        if ( vch->in_room == ch->in_room )
        {
            if ( !IS_NPC( vch ) && has_pcflag( vch, PCFLAG_WIZINVIS )
                    &&    vch->pcdata->wizinvis >= LEVEL_IMMORTAL )
                continue;

            if ( vch != ch && ( IS_NPC( ch ) ? !IS_NPC( vch ) : IS_NPC( vch ) ) )
                retcode = damage( ch, vch, saves_spell_staff( level, vch ) ? dam / 2 : dam, skill->id );

            if ( retcode == rCHAR_DIED || char_extracted( ch ) )
                ch_died = TRUE;

            continue;
        }

        if ( !ch_died
                &&   vch->in_room->area == ch->in_room->area
                &&   IS_OUTSIDE( vch )
                &&   IS_AWAKE( vch ) )
        {
            set_char_color( AT_MAGIC, vch );
            ch_println( vch, "Lightning flashes in the sky." );
        }
    }

    if ( ch_died )
        return rCHAR_DIED;
    else
        return rNONE;
}

