SPELLF spell_charm_person( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    AFFECT_DATA af;
    int chance, abil = 0;
    char buf[MSL];

    if ( victim == ch )
    {
        ch_println( ch, "You like yourself even better!" );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC )
            ||   xIS_SET( victim->immune, RIS_CHARM ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( !IS_NPC( victim ) && !IS_NPC( ch ) )
    {
        ch_println( ch, "I don't think so..." );
        ch_println( victim, "You feel as if someone tried to enter your mind but failed.." );
        return rSPELL_FAILED;
    }

    if ( !IS_NPC( ch ) )
        abil = ch->skill_level[LEADERSHIP_ABILITY];

    if ( count_followers( ch, 1, FALSE ) + 1 > ( abil / 5 ) )
    {
        ch_println( ch, "You feel that that many followers would be too much to handle!" );
        return rSPELL_FAILED;
    }

    chance = ris_save( victim, level, RIS_CHARM );

    if ( IS_AFFECTED( victim, AFF_CHARM )
            ||   chance == 1000
            ||   IS_AFFECTED( ch, AFF_CHARM )
            ||   level < victim->top_level
            ||   circle_follow( victim, ch )
            ||   saves_spell_staff( chance, victim ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    stop_follower( victim, false );
    add_follower( victim, ch, false );
    af.type = skill->id;
    af.duration  = ( number_fuzzy( ( level + 1 ) / 3 ) + 1 ) * ( int )DUR_CONV;
    af.location  = 0;
    af.modifier  = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_CHARM );
    affect_join( victim, CHAR_AFFECT, &af );
    act( AT_MAGIC, "Isn't $n just so nice?", ch, NULL, victim, TO_VICT );
    act( AT_MAGIC, "$N's eyes glaze over...", ch, NULL, victim, TO_ROOM );

    if ( ch != victim )
        ch_println( ch, "Ok." );

    snprintf( buf, MSL, "%s has charmed %s.", ch->name, victim->name );
    log_string_plus( buf, LOG_NORMAL, ch->top_level );
    /*
        to_channel( buf, CHANNEL_MONITOR, "Monitor", UMAX( LEVEL_IMMORTAL, ch->top_level ) );
    */
    return rNONE;
}

