}
SPELLF spell_unfamiliar( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    GREET_DATA* greet;

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They are not here." );
        return rNONE;
    }

    if ( !IS_NPC( victim ) )
    {
        if ( has_pcflag( victim, PCFLAG_AFK ) )
        {
            ch_println( ch, "That player is afk." );
            return rINVALID_ARGS;
        }

        if ( chance( ch, 50 ) && ch->skill_level[FORCE_ABILITY] < victim->top_level )
        {
            failed_casting( skill, ch, victim, NULL );
            return rSPELL_FAILED;
        }
    }

    // GRAL for Ralen
    // Max forcer is frc=22 or level 110. This allows for a (1..90+20)+ or 10% chance to fail
    if ( ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  &&
            number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] ) ||
            ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) )
    {
        ch_println( ch, "&BReaching out with the Force, you try to influence %s's mind.&w", g_name( victim, ch ) );
        ch_println( ch, "&wYour Mind Trick has no effect on %s.", g_name( victim, ch ) );
        act( AT_MAGIC, "&wYou sense $n trying to reach your mind with the Force. Their mind powers won't work.", ch, NULL, victim, TO_VICT );
        return rNONE;
    }

    act( AT_MAGIC, "You clear $N's mind of all memory of you.", ch, NULL, victim, TO_CHAR );
    act( AT_MAGIC, "You feel all memory of $n fade from your mind...", ch, NULL, victim, TO_VICT );
    act( AT_MAGIC, "A blank look crosses over $N's face.", ch, NULL, victim, TO_NOTVICT );
    greet = fetch_greet( victim, ch );

    if ( greet != NULL )
        extract_greet( victim, greet );

    AFFECT_DATA af;
    af.type = skill->id;
    af.duration  = 4;
    af.location  = 0;
    af.modifier  = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_UNFAMILIAR );
    affect_replace( victim, CHAR_AFFECT, &af );
    return rNONE;
}
