SPELLF spell_force_healing( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    int hp = 0;
    int mod = 0;

    if ( NULLSTR( target_name ) )
        victim = ch;

    else if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They are not here." );
        return rINVALID_ARGS;
    }

    /*Ralen - Droids shouldn't be affected by revive/heal. */
    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    act( AT_GREEN, "Glowing green light emanates from $n.", ch, NULL, NULL, TO_ROOM );

    if ( victim == ch )
        ch_println( ch, "Using the Force, you mend your wounds." );

    if ( victim != ch )
    {
        ch_println( ch, "Using the Force, you mend %s's wounds.", g_name( victim, ch ) );
        act( AT_PLAIN, "A surge of warmth permeates you, and you feel healthier.\n", ch, NULL, victim, TO_VICT );
        //act(AT_PLAIN, "$n uses the Force to mend your wounds.\n", ch, NULL, victim, TO_VICT);
    }

    if ( ch->spirit )
    {
        ch_println( ch, "&x&Y&wYour healing abilities are not as effective as they were in life." );
    }

    if ( victim != ch )
    {
        ch->alignment = ch->alignment + 50;
        ch->alignment = URANGE( -1000, ch->alignment, 1000 );
        jedi_bonus( ch );
    }

    /*  GRAL Where is the drain done?
         Xpuma20X: I'd have to think on that. I'd like to see force healing actually
         stay a set at a specific rate so I can get use to it...
         Its ranged from 500 mana for 50 health, to 200 mana for about 500 health
    */
    hp = number_percent() * number_range( 1, 4 );
    mod = IS_NPC( ch ) ? ch->top_level : ( int )get_learned_pct( ch, skill ); //Split into further lines because NPC use crashing us. Gathorn 13Jan19

    if ( victim == ch )
        hp += mod;
    else
        hp += mod / 2;

    if ( IS_AFFECTED( ch, AFF_CLARITY ) )
        hp += number_range( 150, 400 );

    if ( ch->spirit )
        hp /= 2;

    victim->hit += hp;

    if ( victim->hit > victim->max_hit )
        victim->hit = victim->max_hit;

    return rNONE;
}

SPELLF spell_force_revive( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    AFFECT_DATA* paf = NULL, *pnext = NULL;

    /*bug("starting process"); */
    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return rINVALID_ARGS;
    }

    /*Ralen - Droids shouldn't be affected by revive/heal. */
    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You cannot use this on yourself." );
        return rINVALID_ARGS;
    }

    /*bug ("found victim: %s", victim->name);   */
    act( AT_GREEN, "Glowing green light emanates from $n.\n", ch, NULL, NULL, TO_ROOM );

    /*bug( "Doing ch_printf for victim" );    */
    if ( victim != ch )
    {
        act( AT_GREEN, "Using the Force, you clear $S mind.\n", ch, NULL, victim, TO_CHAR );
        ch_println( victim, "Glowing clarity spreads blissfully through your mind." );
    }

    /*bug("checking alignment of ch"); */
    if ( ch->alignment < 1000 && victim != ch )
    {
        ch->alignment = ch->alignment + 50;
        jedi_bonus( ch );
    }

    /*bug ("removing affects on %s", victim->name );    */
    for ( paf = victim->first_affect; paf; paf = pnext )
    {
        pnext = paf->next;

        if ( xIS_SET( paf->bitvector, AFF_PARALYSIS ) )
            affect_remove( victim, CHAR_AFFECT, paf );

        if ( xIS_SET( paf->bitvector, AFF_SLEEP ) )
            affect_remove( victim, CHAR_AFFECT, paf );
    }

    update_pos( victim );
    return rNONE;
}
SPELLF spell_force_grab( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    OBJ_DATA* obj, *tmpobj;
    bool wield;
    wield = FALSE;

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        send_to_char( "They are not here.", ch );
        return rINVALID_ARGS;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        return rINVALID_ARGS;
    }

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL )
        wield = TRUE;

    if ( ( obj = get_eq_char( victim, WEAR_WIELD ) ) == NULL && !wielding_claws( victim ) )
    {
        send_to_char( "They are not wielding a weapon.", ch );
        return rINVALID_ARGS;
    }

    if ( ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
        obj = tmpobj;

    /* GRAL forcer-force %, forcer-mortal high% */

    if ( wielding_claws( victim ) )
    {
        act( AT_ACTION, "You cannot seem to rip the dewclaws from $N's hands.", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "$n tries to pull the dewclaws from your hands.", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$n reaches out towards $N, and $s dewclaws shake slightly.", ch, NULL, victim, TO_NOTVICT );
        return rNONE;
    }

    /*No disarm mob flag by Walldo 01nov09. Ralen September '13 - You had it as or rather than and, bud! */
    if ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_NODISARM ) )
    {
        ch_println( ch, "How do you expect to disarm that?" );
        return rNONE;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_NODISARM ) )
    {
        ch_println( ch, "Their weapon can't be disarmed." );
        return rNONE;
    }

    if ( check_grip( ch, victim ) )
    {
        act( AT_ACTION, "You cannot seem to pull $p from $N's hands.", ch, obj, victim, TO_CHAR );
        act( AT_ACTION, "$n tries to pull $p from your hands.", ch, obj, victim, TO_VICT );
        act( AT_ACTION, "$n reaches out towards $N, and $p shakes in $S hands.", ch, obj, victim, TO_NOTVICT );
        return rNONE;
    }

    act( AT_MAGIC, "Holding out your hand, you reach out with the Force, yanking $p from $N's hands!\nIt zips across the distance spanning the two of you until your hand closes about it.", ch, obj, victim, TO_CHAR );
    act( AT_MAGIC, "$n holds $s hand out, and $p is ripped from your hands!\nIt zips across the distance spanning the two of you, until $s hand closes about it!", ch, obj, victim, TO_VICT );
    act( AT_MAGIC, "$n holds $s hand out towards $N, and $p is yanked from $N's hands!\nIt zips across the distance spanning the two of them, until $n's hand closes about it.", ch, obj, victim, TO_NOTVICT );

    if ( obj == get_eq_char( victim, WEAR_WIELD )
            &&  ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
        tmpobj->wear_loc = WEAR_WIELD;

    obj_from_char( obj );
    obj_to_char( obj, ch );

    if ( wield )
        equip_char( ch, obj, WEAR_WIELD );

    return rNONE;
}

