SPELLF spell_cure_poison( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( NULLSTR( target_name ) )
        victim = ch;
    else if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They are not here." );
        return rINVALID_ARGS;
    }

    AFFECT_DATA* paf;
    int drain;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( !IS_AFFECTED( victim, AFF_POISON ) )
    {
        ch_println( ch, "Even through the Force, you find no trace of toxins." );
        return rSPELL_FAILED;
    }

    if ( IS_AFFECTED( victim, AFF_POISON ) )
    {
        if ( ch != victim )
        {
            ch_println( ch, "You attempt to leech the poison from the being!" );
            ch->alignment = ch->alignment + 25 ;
            ch->alignment = URANGE( -1000, ch->alignment, 1000 );
            jedi_bonus( ch );
        }

        /*drain = level * get_learned_pct( ch, skill );*/
        drain = 500 + ( ch->skill_level[FORCE_ABILITY] * 2 );

        for ( paf = victim->first_affect; paf; paf = paf->next ) // Previously ch->first_affect, meant only affected when cast on self.
            if ( xIS_SET( paf->bitvector, AFF_POISON ) )
                paf->duration = URANGE( 1, paf->duration - drain, 32000 );

        if ( victim == ch ) //Ralen - 'Their body' on self didn't look quite right.
            ch_println( ch, "&GYou pass your hands over your own body, drawing out the poison." );

        if ( victim != ch )
        {
            ch_println( ch, "&GYou pass your hands over their body, drawing out the poison." );
        }

        ch_println( victim, "&GA warm feeling runs through your body." );
        act( AT_MAGIC, "$N looks a bit better.", ch, NULL, victim, TO_NOTVICT );
        return rNONE;
    }
    else
        return rSPELL_FAILED;
}


SPELLF spell_curse( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    AFFECT_DATA af;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( IS_AFFECTED( victim, AFF_CURSE ) || saves_spell_staff( level, victim ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    af.type = skill->id;
    af.duration  = ( 4 * level ) * ( int )DUR_CONV;
    af.location  = APPLY_HITROLL;
    af.modifier  = -1;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_CURSE );
    affect_join( victim, CHAR_AFFECT, &af );
    af.location  = APPLY_SAVING_SPELL;
    af.modifier  = 1;
    affect_join( victim, CHAR_AFFECT, &af );
    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 50;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    set_char_color( AT_MAGIC, victim );
    ch_println( victim, "You feel unclean." );

    if ( ch != victim )
        ch_println( ch, "Ok." );

    return rNONE;
}


