SPELLF spell_dispel_undead( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    int dam;

    if ( !xIS_SET( victim->race->flags, RFLAG_UNDEAD ) || xIS_SET( ch->race->flags, RFLAG_UNDEAD ) )
    {
        act( AT_MAGIC, "$N does not seem to be affected.", ch, NULL, victim, TO_CHAR );
        return rSPELL_FAILED;
    }

    dam = dice( level, 4 );

    if ( saves_spell_staff( level, victim ) )
        dam /= 2;

    if ( IS_NPC( victim ) )
        dam *= 2;

    return damage( ch, victim, dam, skill->id );
}

SPELLF spell_dispel_evil( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    int dam;

    if ( !IS_NPC( ch ) && IS_EVIL( ch ) )
        victim = ch;

    if ( IS_GOOD( victim ) )
    {
        act( AT_MAGIC, "The light side protects $N.", ch, NULL, victim, TO_ROOM );
        return rSPELL_FAILED;
    }

    if ( IS_NEUTRAL( victim ) )
    {
        act( AT_MAGIC, "$N does not seem to be affected.", ch, NULL, victim, TO_CHAR );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    dam = dice( level, 4 );

    if ( saves_spell_staff( level, victim ) )
        dam /= 2;

    return damage( ch, victim, dam, skill->id );
}

SPELLF spell_dispel_magic( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( victim == ch )
    {
        set_char_color( AT_MAGIC, ch );
        ch_println( ch, "You pass your hands around your body..." );
        act( AT_MAGIC, "$n passes $s hands around $s body.", ch, NULL, NULL, TO_ROOM );
    }
    else
    {
        act( AT_MAGIC, "$n reaches out towards $N, gesturing with one hand.", ch, NULL, victim, TO_NOTVICT );
        act( AT_MAGIC, "$n reaches towards you, gesturing with one hand!", ch, NULL, victim, TO_VICT );
        act( AT_MAGIC, "You reach out toward $N, attempting to tear away the protection of the Force...", ch, NULL, victim, TO_CHAR );
    }

    SKILL_DATA* aff_skill;
    AFFECT_DATA* next_aff;

    for ( AFFECT_DATA* aff = victim->first_affect; aff; aff = next_aff )
    {
        next_aff = aff->next;
        aff_skill = skill_from_id( aff->type );

        // Ignore non-force affects (spice, poison, berserk, etc)
        if ( !aff_skill || aff_skill->guild != FORCE_ABILITY )
            continue;

        if ( !negative_spell_succeeds( ch, skill, victim ) )
            continue;

        if ( ch != victim )
            act( AT_MAGIC, "You banish an effect from $N.", ch, NULL, victim, TO_CHAR );

        if ( aff->type > 0 && aff_skill && aff_skill->msg_off )
        {
            set_char_color( AT_WEAROFF, victim );
            send_to_char( aff_skill->msg_off, victim );
            ch_println( victim, "" );
        }

        affect_remove( victim, CHAR_AFFECT, aff );
    }

    successful_casting( skill, ch, victim, NULL );
    return rNONE;
}



SPELLF spell_earthquake( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* vch;
    CHAR_DATA* vch_next;
    bool ch_died;
    ch_ret retcode;
    ch_died = FALSE;
    retcode = rNONE;

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFE ) )
    {
        failed_casting( skill, ch, NULL, NULL );
        return rSPELL_FAILED;
    }

    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 100;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    act( AT_MAGIC, "The earth trembles beneath your feet!", ch, NULL, NULL, TO_CHAR );
    act( AT_MAGIC, "$n makes the earth tremble and shiver.", ch, NULL, NULL, TO_ROOM );

    for ( vch = first_char; vch; vch = vch_next )
    {
        vch_next    = vch->next;

        if ( !vch->in_room )
            continue;

        if ( vch->in_room == ch->in_room )
        {
            if ( !IS_NPC( vch ) && has_pcflag( vch, PCFLAG_WIZINVIS )
                    && vch->pcdata->wizinvis >= LEVEL_IMMORTAL )
                continue;

            if ( IS_AFFECTED( vch, AFF_FLOATING ) || IS_AFFECTED( vch, AFF_FLYING ) )
                continue;

            if  ( ch == vch )
                continue;

            retcode = damage( ch, vch, level + dice( 2, 8 ), skill->id );

            if ( retcode == rCHAR_DIED || char_extracted( ch ) )
            {
                ch_died = TRUE;
                continue;
            }

            if ( char_extracted( vch ) )
                continue;
        }

        if ( !ch_died && vch->in_room->area == ch->in_room->area )
        {
            set_char_color( AT_MAGIC, vch );
            ch_println( vch, "The earth trembles and shivers." );
        }
    }

    if ( ch_died )
        return rCHAR_DIED;
    else
        return rNONE;
}


SPELLF spell_enchant_weapon( UNUSED(SKILL_DATA* skill), int level, CHAR_DATA* ch )
{
    OBJ_DATA* obj = get_local_object_target( ch, target_name );
    if ( !obj ) return rINVALID_ARGS;

    AFFECT_DATA* paf;

    if ( obj->item_type != ITEM_WEAPON
            ||   IS_OBJ_STAT( obj, ITEM_MAGIC )
            ||   obj->first_affect )
        return rSPELL_FAILED;

    /* Bug fix here. -- Alty */
    separate_obj( obj );
    CREATE( paf, AFFECT_DATA, 1 );
    paf->type       = -1;
    paf->duration   = -1;
    paf->location   = APPLY_HITROLL;
    paf->modifier   = level / 15;
    xCLEAR_BITS( paf->bitvector );
    LINK( paf, obj->first_affect, obj->last_affect, next, prev );
    CREATE( paf, AFFECT_DATA, 1 );
    paf->type       = -1;
    paf->duration   = -1;
    paf->location   = APPLY_DAMROLL;
    paf->modifier   = level / 15;
    xCLEAR_BITS( paf->bitvector );
    LINK( paf, obj->first_affect, obj->last_affect, next, prev );

    if ( IS_GOOD( ch ) )
    {
        xSET_BIT( obj->extra_flags, ITEM_ANTI_EVIL );
        act( AT_BLUE, "$p glows blue.", ch, obj, NULL, TO_CHAR );
    }
    else if ( IS_EVIL( ch ) )
    {
        xSET_BIT( obj->extra_flags, ITEM_ANTI_GOOD );
        act( AT_RED, "$p glows red.", ch, obj, NULL, TO_CHAR );
    }
    else
    {
        xSET_BIT( obj->extra_flags, ITEM_ANTI_EVIL );
        xSET_BIT( obj->extra_flags, ITEM_ANTI_GOOD );
        act( AT_YELLOW, "$p glows yellow.", ch, obj, NULL, TO_CHAR );
    }

    ch_println( ch, "Ok." );
    return rNONE;
}



/*
    Drain XP, MANA, HP.
    Caster gains HP.
*/
SPELLF spell_energy_drain( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    int dam;
    int chance;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 200;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    chance = ris_save( victim, victim->top_level, RIS_DRAIN );

    if ( chance == 1000 || saves_spell_staff( chance, victim ) )
    {
        failed_casting( skill, ch, victim, NULL ); /* SB */
        return rSPELL_FAILED;
    }

    if ( victim->top_level <= 2 )
        dam      = ch->hit + 1;
    else
    {
        victim->mana    /= 2;
        victim->move    /= 2;
        dam      = dice( 1, level );
        ch->hit     += dam;
    }

    if ( ch->hit > ch->max_hit )
        ch->hit = ch->max_hit;

    return damage( ch, victim, dam, skill->id );
}



