SPELLF spell_identify( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    /* Modified by Scryn to work on mobs/players*/
    CHAR_DATA* victim;
    AFFECT_DATA* paf;
    SKILL_DATA* sktmp;

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Who would you like identified?" );
        return rINVALID_ARGS;
    }

    if ( ( victim = get_char_room( ch, target_name ) ) != NULL )
    {
        if ( xIS_SET( victim->immune, RIS_MAGIC ) )
        {
            immune_casting( skill, ch, victim, NULL );
            return rSPELL_FAILED;
        }

        if ( IS_NPC( victim ) )
        {
            ch_println( ch, "%s appears to be between level %d and %d.",
                       g_name( victim, ch ),
                       victim->top_level - ( victim->top_level % 5 ),
                       victim->top_level - ( victim->top_level % 5 ) + 5 );
        }
        else
        {
            ch_println( ch, "%s appears to be level %d.", g_name( victim, ch ), victim->top_level );
        }

        // GRAL for Ralen
        // GRAL ToDo - faulty mset setting mset droid flags droid to pet
        if ( xIS_SET( victim->act, ACT_IS_NPC ) && ( xIS_SET( victim->act, ACT_DROID ) ||
                xIS_SET( victim->act, ACT_PET ) ) )
        {
            ch_println( ch, "%s looks like a droid.",
                       g_name( victim, ch ) );
        }
        else if ( xIS_SET( victim->act, ACT_IS_NPC ) && xIS_SET( victim->act, ACT_ANIMAL ) )
        {
            ch_println( ch, "%s looks like some sort of creature.",
                       g_name( victim, ch ) );
        }
        else
        {
            //Changed to show race name, and not race shortdesc. Gathorn 7May16
            ch_println( ch, "%s looks like %s.",
                       g_name( victim, ch ), aoran( victim->race->race_name ) );
        }

        if ( ( chance( ch, 50 ) && ch->top_level >= victim->top_level + 10 )
                ||    IS_IMMORTAL( ch ) )
        {
            ch_printf( ch, "%s appears to be affected by: ", g_name( victim, ch ) );

            if ( !victim->first_affect )
            {
                ch_println( ch, "nothing." );
                return rNONE;
            }

            for ( paf = victim->first_affect; paf; paf = paf->next )
            {
                if ( victim->first_affect != victim->last_affect )
                {
                    if ( paf != victim->last_affect && ( sktmp = skill_from_id( paf->type ) ) != NULL )
                        ch_printf( ch, "%s, ", sktmp->name );

                    if ( paf == victim->last_affect && ( sktmp = skill_from_id( paf->type ) ) != NULL )
                    {
                        ch_println( ch, "and %s.", sktmp->name );
                        return rNONE;
                    }
                }
                else
                {
                    if ( ( sktmp = skill_from_id( paf->type ) ) != NULL )
                        ch_println( ch, "%s.", sktmp->name );
                    else
                        ch_println( ch, "" );

                    return rNONE;
                }
            }
        }
    }
    else
    {
        ch_println( ch, "You can't find %s!", target_name );
        return rINVALID_ARGS;
    }

    return rNONE;
}



SPELLF spell_invis( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim;

    /* Modifications on 1/2/96 to work on player/object - Scryn */

    if ( NULLSTR( target_name ) )
        victim = ch;
    else
        victim = get_char_room( ch, target_name );

    if ( victim )
    {
        AFFECT_DATA af;

        if ( xIS_SET( victim->immune, RIS_MAGIC ) )
        {
            immune_casting( skill, ch, victim, NULL );
            return rSPELL_FAILED;
        }

        if ( IS_AFFECTED( victim, AFF_INVISIBLE ) )
        {
            act( AT_MAGIC, "$n is already masked from view.", ch, NULL, NULL, TO_CHAR );
            return rINVALID_ARGS;
        }

        if ( ( IS_NPC( victim ) && victim->master != ch ) || IS_AFFECTED( victim, AFF_VISIBLE ) )
        {
            act( AT_MAGIC, "Despite your efforts, $n still seems easy to spot.", victim, NULL, NULL, TO_CHAR );
            return rSPELL_FAILED;
        }

        act( AT_MAGIC, "$n fades out of existence.", victim, NULL, NULL, TO_ROOM );
        af.type = skill->id;
        af.duration  = ( ( level / 4 ) + 12 ) * ( int )DUR_CONV;
        af.location  = APPLY_NONE;
        af.modifier  = 0;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_INVISIBLE );
        affect_join( victim, CHAR_AFFECT, &af );
        act( AT_MAGIC, "You fade out of existence.", victim, NULL, NULL, TO_CHAR );
        return rNONE;
    }

    ch_println( ch, "They aren't here." );
    return rINVALID_ARGS;
}

