SPELLF spell_locate_object( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    char buf[MIL];
    OBJ_DATA* obj;
    OBJ_DATA* in_obj;
    bool found;
    int cnt;
    found = FALSE;

    for ( obj = first_object; obj; obj = obj->next )
    {
        if ( !can_see_obj( ch, obj ) || !nifty_is_name( target_name, obj->name ) )
            continue;

        if ( IS_OBJ_STAT( obj, ITEM_PROTOTYPE ) && !IS_IMMORTAL( ch ) )
            continue;

        found = TRUE;

        for ( cnt = 0, in_obj = obj;
                in_obj->in_obj && cnt < 100;
                in_obj = in_obj->in_obj, ++cnt )
            ;

        if ( cnt >= MAX_NEST )
        {
            snprintf( buf, MIL, "spell_locate_obj: object [%d] %s is nested more than %d times!",
                     obj->pIndexData->vnum, obj->short_descr, MAX_NEST );
            bug( buf, 0 );
            continue;
        }

        if ( in_obj->carried_by )
        {
            if ( IS_IMMORTAL( in_obj->carried_by )
                    && !IS_NPC(  in_obj->carried_by )
                    && ( get_trust( ch ) < in_obj->carried_by->pcdata->wizinvis )
                    && has_pcflag( in_obj->carried_by, PCFLAG_WIZINVIS ) )
                continue;

            snprintf( buf, MIL, "%s carried by %s.\n",
                     obj_short( obj ), PERS( in_obj->carried_by, ch ) );
        }
        else
        {
            snprintf( buf, MIL, "%s in %s.\n",
                     obj_short( obj ), in_obj->in_room == NULL
                     ? "somewhere" : in_obj->in_room->name );
        }

        buf[0] = UPPER( buf[0] );
        set_char_color( AT_MAGIC, ch );
        send_to_char( buf, ch );
    }

    if ( !found )
    {
        ch_println( ch, "Nothing like that exists." );
        return rSPELL_FAILED;
    }

    return rNONE;
}



