SPELLF spell_poison( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    AFFECT_DATA af;
    int chance;
    bool first = TRUE;
    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 100;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    chance = ris_save( victim, level, RIS_POISON );

    if ( chance == 1000 || saves_poison_death( chance, victim ) )
        return rSPELL_FAILED;

    if ( IS_AFFECTED( victim, AFF_POISON ) )
        first = FALSE;

    af.type = skill->id;
    af.duration  = level * ( int )DUR_CONV;
    af.location  = APPLY_STR;
    af.modifier  = -2;
    xCLEAR_BITS( af.bitvector );
