    affect_join( victim, CHAR_AFFECT, &af );
    set_char_color( AT_MAGIC, victim );
    ch_println( victim, "You feel very sick." );
    // Special case: The first time someone is poisoned, they get a sudden bump in mental state.
    victim->mental_state = URANGE( 20, victim->mental_state
                                   + ( first ? 5 : 0 ), 100 );

    if ( ch != victim )
        ch_println( ch, "Ok." );

    return rNONE;
}

SPELLF spell_remove_trap( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    OBJ_DATA* obj;
    OBJ_DATA* trap;
    bool found;
    int retcode;

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Remove trap on what?" );
        return rINVALID_ARGS;
    }

    found = FALSE;

    if ( !ch->in_room->first_content )
    {
        ch_println( ch, "You can't find that here." );
        return rNONE;
    }

    for ( obj = ch->in_room->first_content; obj; obj = obj->next_content )
        if ( can_see_obj( ch, obj ) && nifty_is_name( target_name, obj->name ) )
        {
            found = TRUE;
            break;
        }

    if ( !found )
    {
        ch_println( ch, "You can't find that here." );
        return rINVALID_ARGS;
    }

    if ( ( trap = get_trap( obj ) ) == NULL )
    {
        failed_casting( skill, ch, NULL, NULL );
        return rSPELL_FAILED;
    }

    if ( chance( ch, 70 + get_curr_wis( ch ) ) )
    {
        ch_println( ch, "Ooops!" );
        retcode = spring_trap( ch, trap );

        if ( retcode == rNONE )
            retcode = rSPELL_FAILED;

        return retcode;
    }

    extract_obj( trap );
    successful_casting( skill, ch, NULL, NULL );
    return rNONE;
}


