SPELLF spell_sleep( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    AFFECT_DATA af;
    int chance;
    int tmp;
    CHAR_DATA* victim;

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return rINVALID_ARGS;
    }

    level = IS_NPC( ch ) ? ch->top_level : get_trust( ch ) ;

    if ( !IS_NPC( victim ) && victim->fighting )
    {
        ch_println( ch, "You cannot sleep a fighting player." );
        return rINVALID_ARGS;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        return rINVALID_ARGS;
    }

    if ( is_safe( ch, victim ) )
        return rSPELL_FAILED;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( victim->skill_level[FORCE_ABILITY] > 45 )
    {
        act( AT_MAGIC, "$N's mind is too sharp for that to work.", ch, NULL, victim, TO_CHAR );
        return rSPELL_FAILED;
    }

    if ( SPELL_FLAG( skill, SF_PKSENSITIVE )
            &&  !IS_NPC( ch ) && !IS_NPC( victim ) )
        tmp = level;
    else
        tmp = level;

    if ( IS_AFFECTED( victim, AFF_SLEEP )
            ||  ( chance = ris_save( victim, tmp, RIS_SLEEP ) ) == 1000
            ||   saves_spell_staff( chance, victim ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    af.type = skill->id;
    af.duration  = ( 4 + level ) * ( int )DUR_CONV;
    af.location  = APPLY_NONE;
    af.modifier  = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_SLEEP );
    affect_join( victim, CHAR_AFFECT, &af );

    /* Added by Narn at the request of Dominus. */
    if ( !IS_NPC( victim ) )
    {
        snprintf( log_buf, MSL, "%s has cast sleep on %s.", ch->name, victim->name );
        log_string_plus( log_buf, LOG_NORMAL, ch->top_level );
        to_channel( log_buf, CHANNEL_MONITOR, "Monitor", UMAX( LEVEL_IMMORTAL, ch->top_level ) );
    }

    if ( IS_AWAKE( victim ) )
    {
        act( AT_MAGIC, "You feel very sleepy ..... zzzzzz.", victim, NULL, NULL, TO_CHAR );
        act( AT_MAGIC, "$n goes to sleep.", victim, NULL, NULL, TO_ROOM );
        victim->position = POS_SLEEPING;
    }

    if ( IS_NPC( victim ) )
        start_hating( victim, ch );

    return rNONE;
}

SPELLF spell_ventriloquate( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    char buf1[MSL];
    char buf2[MSL];
    char speaker[MIL];
    CHAR_DATA* vch;
    int chances = 0;
    target_name = one_argument( target_name, speaker );
    chances = standard_force_success_rate( ch, skill );

    if ( xIS_SET( ch->in_room->flags, ROOM_SILENCE ) )
    {
        ch_println( ch, "This room is too silent for that." );
        return rNONE;
    }

    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
    {
        if ( vch->position < POS_RESTING )
            continue;

        snprintf( buf1, MSL, "&z&Y&W&C%s %ssays%s '%s%s&C'\n", speaker, tone_convert( ch, vch ), lang_convert( vch, ch->speaking, ch ), txtclr( ch ), target_name );
        snprintf( buf2, MSL, "&z&Y&W&CSomeone makes %s %ssay%s '%s%s&C'\n", speaker, tone_convert( ch, vch ), lang_convert( vch,  ch->speaking, ch ), txtclr( ch ), target_name );
        buf1[0] = UPPER( buf1[0] );

        if ( is_name( speaker, vch->name ) )
            send_to_char( buf2, vch );
        else if ( number_percent() > chances )
            send_to_char( buf2, vch );
        else
        {
            send_to_char( buf1, vch );
            learn_slow( ch, skill, 1 );
        }
    }

    return rNONE;
}

SPELLF spell_weaken( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    AFFECT_DATA af;

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( is_affected( victim, CHAR_AFFECT, skill ) )
    {
        act( AT_MAGIC, "$N is already affected by that.\n", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( saves_wands( level, victim ) )
        return rSPELL_FAILED;

    af.type      = skill->id;
    af.duration  = level / 2 * ( int )DUR_CONV;
    af.location  = APPLY_STR;
    af.modifier  = -2;
    xCLEAR_BITS( af.bitvector );
    affect_join( victim, CHAR_AFFECT, &af );
    set_char_color( AT_MAGIC, victim );
    ch_println( victim, "You feel weaker." );

    if ( ch != victim )
        ch_println( ch, "Ok." );

    return rNONE;
}

