SPELLF spell_gas_breath( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* vch;
    CHAR_DATA* vch_next;
    int dam;
    int hpch;
    bool ch_died;
    ch_died = FALSE;

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFE ) )
    {
        set_char_color( AT_MAGIC, ch );
        ch_println( ch, "You fail to breathe." );
        return rNONE;
    }

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( !IS_NPC( vch ) && has_pcflag( vch, PCFLAG_WIZINVIS )
                && vch->pcdata->wizinvis >= LEVEL_IMMORTAL )
            continue;

        if ( IS_NPC( ch ) ? !IS_NPC( vch ) : IS_NPC( vch ) )
        {
            hpch = UMAX( 10, ch->hit );
            dam  = number_range( hpch / 16 + 1, hpch / 8 );

            if ( saves_breath( level, vch ) )
                dam /= 2;

            if ( damage( ch, vch, dam, skill->id ) == rCHAR_DIED || char_extracted( ch ) )
                ch_died = TRUE;
        }
    }

    if ( ch_died )
        return rCHAR_DIED;
    else
        return rNONE;
}



