SPELLF spell_farsight( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* location = NULL;
    SPACE_DATA* tmpA = NULL;
    SPACE_DATA* tmpB = NULL;
    CHAR_DATA* victim = NULL;
    int chc = 0;

    if ( xIS_SET( ch->in_room->affected_by, AFF_OBSCURE ) )
    {
        ch_println( ch, "A dark presence is obscuring this area." );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_NOFARSIGHT ) )
    {
        ch_println( ch, "&BYou failed." );
        return rSPELL_FAILED;
    }

    /*  The spell fails if the victim isn't playing, the victim is the caster,
        the target room has private, solitary, noastral, death or proto flags,
        the caster's room is norecall, the victim is too high in level, the
        victim is a proto mob, the victim makes the saving throw or the pkill
        flag on the caster is not the same as on the victim.  Got it?

         At some point someone removed that top level restriction
         Adding in a knows_player requirement.
    */
    if ( ( victim = get_char_starsystem( ch, target_name ) ) == NULL
            ||   victim == ch
            ||   !victim->in_room
            ||   xIS_SET( victim->in_room->flags, ROOM_PRIVATE )
            ||   xIS_SET( victim->in_room->flags, ROOM_PROTOTYPE )
            /* ||   victim->top_level >= level + 15 */
            ||   xIS_SET( victim->in_room->affected_by, AFF_OBSCURE )
            ||  ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_PROTOTYPE ) )
            ||   xIS_SET( victim->in_room->flags, ROOM_NOFARSIGHT )
            || xIS_SET( victim->act, ACT_DROID ) 
            ||   xIS_SET( victim->act, ACT_NOFARSIGHT )
            ||  ( IS_NPC( victim ) && saves_spell_staff( level, victim ) )
            ||        ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  &&
                number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] )
                 || ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) 
            ||   !knows_player( ch, victim, GREET_ANY, true ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    /* New limit. Make sure the target is in the same over-all starsystem */
    if ( ( tmpA = in_starsystem( ch ) ) == NULL )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( ( tmpB = in_starsystem( victim ) ) == NULL )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( str_cmp( tmpA->name, tmpB->name ) && ( !ch->spirit || ch->perm_frc < 26 ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    location = victim->in_room;

    if ( !location )
    {
        ch_println( ch, "A dark presence is obscuring this area." );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( victim->race->flags, RFLAG_VONG ) )
    {
        send_to_char( "&zYour mind sees only a void, the complete absence of The Force.", ch );
        return rSPELL_FAILED;
    }

    ch_println( ch, "&zThrough gray, swirling mists, your consciousness brushes against theirs." );
    ch_println( ch, "From within their mind, you reach out to sense their surroundings and see:" );
    ch_println( ch, "%s&z", victim->in_room->name );

    chc = IS_NPC( victim ) ? 0 : has_pcflag( victim, PCFLAG_NO_SENSE ) ? 0 : ( int ) get_learned_pct( victim, cache_skill( "perception", &skill_perception ) );
    if ( chc != 0 && number_range( 1, 120 ) > chc )
    {
        ch_println( victim, "You feel as if you're being watched." );
        learn_from_failure( victim, cache_skill( "perception", &skill_perception ) );
    }
    else if ( chc != 0 )
    {
        ch_println( victim, "You feel as if %s is watching you!", g_name( ch, victim ) );
        ch_println( ch, "You brush awareness with %s...", g_name( victim, ch ) );
        learn_from_success( victim, cache_skill( "perception", &skill_perception ) );
    }

    if ( !IS_NPC( ch ) && ch->pcdata->frank > FRANK_APPRENTICE )
    {
        bool printed_header = false;
        for ( CHAR_DATA* rch = victim->in_room->first_person; rch; rch = rch->next_in_room )
        {
            if ( rch == ch
              || rch == victim
              || IS_IMMORTAL( rch )
              || xIS_SET( rch->act, ACT_NOFARSIGHT )
                          ||        ( xIS_SET( rch->race->flags, RFLAG_FORCERESISTANCE )  &&
                number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] )
                 || ( xIS_SET( rch->race->flags, RFLAG_FORCEIMMUNE ) )
                 || xIS_SET( rch->act, ACT_DROID ) 
            )
                continue;

            if ( !printed_header )
            {
                ch_println( ch, "" );
                ch_println( ch, "&zYou also sense the presence of other beings nearby:" );
                printed_header = true;
            }

            ch_println(ch, "%s&z", g_name( rch, ch ) );

            chc = IS_NPC( rch ) ? 0 : has_pcflag( rch, PCFLAG_NO_SENSE ) ? 0 : ( int ) get_learned_pct( rch, cache_skill( "perception", &skill_perception ) );
            if ( chc != 0 && number_range( 1, 120 ) > chc )
            {
                ch_println( rch, "You feel as if you're being watched." );
                learn_from_failure( rch, cache_skill( "perception", &skill_perception ) );
            }
            else if ( chc != 0 )
            {
                ch_println( rch, "You feel as if %s is watching you!", g_name( ch, rch ) );
                ch_println( ch, "You brush awareness with %s...", g_name( rch, ch ) );
                learn_from_success( rch, cache_skill( "perception", &skill_perception ) );
            }
        }
    }
    successful_casting( skill, ch, victim, NULL );

    return rNONE;
}
SPELLF spell_awareness( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    DESCRIPTOR_DATA* d = NULL;
    SPACE_DATA* starsystem = NULL; // GRAL Era 1, Timeline X #2
    PLANET_DATA* planet = NULL;    // GRAL Era 1, Timeline X #2
    bool ffound = FALSE;
    int fcount = 0, wcount = 0, acount = 0;

    if ( !in_starsystem( ch ) )
    {
        ch_println( ch, "You can only do that in realspace." );
        return rINVALID_ARGS;
    }

    for ( d = first_descriptor; d; d = d->next )
    {
        if ( d->connected != CON_PLAYING )
            continue;

        if ( !d->character )
            continue;

        if ( in_starsystem( ch ) != in_starsystem( d->character ) )
            continue;

        if ( IS_IMMORTAL( d->character ) )
            continue; /* Rule out the ones we don't want...*/

        if ( d->character == ch )
            continue;

        if ( has_pcflag( d->character, PCFLAG_NO_SENSE ) )
            continue;

        // Gral the next line to comment for testing. Blocks the detection of <100 level wild forcers
        if ( get_trust( d->character ) < LEVEL_HERO )
            continue;

        if ( d->character->perm_frc == 1 ) // || xIS_SET(race_table[d->character->race]->flags,RFLAG_NATURALFORCE))
        {
            ffound = TRUE;
            wcount++;
        }

        if ( d->character->perm_frc > 1 )
        {
            ffound = TRUE;
            fcount++;
        }
    }

    if ( ( starsystem = in_starsystem( ch ) ) != NULL )
    {
        // why do it twice? ~Miros
        //starsystem = in_starsystem( ch ); // GRAL Era 1, Timeline X #2
        if ( starsystem->first_planet != NULL )
        {
            for ( planet = starsystem->first_planet; planet; planet = planet->next_in_system )
            {
                acount += planet->ambience;

                if ( planet->ambience > 0 )
                    ffound = TRUE;
            }
        }
    }

    if ( !ffound )
    {
        ch_println( ch, "&BYou sense nothing." );
        return rNONE;
    }

    if ( ( acount > 0 ) // GRAL Immortals see the real number
            && ( !IS_IMMORTAL( ch ) || get_trust( ch ) < sysdata.log_level ) )
    {
        fcount += acount;
        fcount =  number_range( 0, fcount );
        wcount += acount;
        wcount =  number_range( 0, wcount );
    }

    if ( ch->skill_level[FORCE_ABILITY] >= 75 ) //75 is the new "master" territory, so let's make them able to see #s.
    {
        if ( fcount == 1 )
            ch_println( ch, "You sense %d origin of the Force.", fcount );
        else
            ch_println( ch, "You sense %d different origins of the Force.", fcount );

        if ( wcount > 0 )
