/* Scryn 2/2/96 */
SPELLF spell_remove_invis( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    OBJ_DATA* obj;

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "What should the spell be cast upon?" );
        return rINVALID_ARGS;
    }

    obj = get_obj_carry( ch, target_name );

    if ( obj )
    {
        if ( !IS_OBJ_STAT( obj, ITEM_INVIS ) )
            return rSPELL_FAILED;

        xREMOVE_BIT( obj->extra_flags, ITEM_INVIS );
        act( AT_MAGIC, "$p becomes visible again.", ch, obj, NULL, TO_CHAR );
        ch_println( ch, "Ok." );
        return rNONE;
    }
    else
    {
        CHAR_DATA* victim = get_char_room( ch, target_name );
        AFFECT_DATA af;

        if ( victim )
        {
            if ( !can_see( ch, victim ) )
            {
                ch_println( ch, "You don't see %s!", target_name );
                return rINVALID_ARGS;
            }

            if ( is_safe( ch, victim ) )
            {
                failed_casting( skill, ch, victim, NULL );
                return rSPELL_FAILED;
            }

            if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) )
            {
                ch_println( ch, "That player is afk." );
                return rINVALID_ARGS;
            }

            if ( xIS_SET( victim->immune, RIS_MAGIC ) )
            {
                immune_casting( skill, ch, victim, NULL );
                return rSPELL_FAILED;
            }

            if ( !IS_NPC( victim ) )
            {
                if ( chance( ch, 50 ) && ch->skill_level[FORCE_ABILITY] < victim->top_level )
                {
                    failed_casting( skill, ch, victim, NULL );
                    return rSPELL_FAILED;
                }
            }
            else
            {
                if ( chance( ch, 50 ) && ch->skill_level[FORCE_ABILITY] + 15 < victim->top_level )
                {
                    failed_casting( skill, ch, victim, NULL );
                    return rSPELL_FAILED;
                }
            }

            af.type = skill->id;
            af.duration = level / 20;
            af.modifier = 0;
            af.location = 0;
            xCLEAR_BITS( af.bitvector );
            xSET_BIT( af.bitvector, AFF_VISIBLE );
            affect_replace( victim, CHAR_AFFECT, &af );
            do_visible( victim, "-noalert" );
            act( AT_MAGIC, "$N becomes easier to see as the Force draws attention to $M.", ch, NULL, victim, TO_CHAR );
            act( AT_MAGIC, "You feel attention drawn to yourself as $n calls upon the Force to make you visible.", ch, NULL, victim, TO_VICT );
            return rNONE;
        }

        ch_println( ch, "You can't find %s!", target_name );
        return rINVALID_ARGS;
    }
}

