/* Works now.. -- Altrag */
SPELLF spell_possess( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    char buf[MSL];
    AFFECT_DATA af;

    if ( ch->desc->original )
    {
        ch_println( ch, "You are not in your original state." );
        return rINVALID_ARGS;
    }

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They aren't here!" );
        return rINVALID_ARGS;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You can't possess yourself!" );
        return rINVALID_ARGS;
    }

    if ( !IS_NPC( victim ) )
    {
        ch_println( ch, "You can't possess another player!" );
        return rINVALID_ARGS;
    }

    if ( victim->desc )
    {
        ch_println( ch, "%s is already possessed.", victim->short_descr );
        return rINVALID_ARGS;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( IS_AFFECTED( victim, AFF_POSSESS )
            ||   level < ( victim->top_level + 30 )
            ||  victim->desc
            ||  !chance( ch, 25 ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    ch_println( ch, "You feel the hatred grow within you as you twist your victims mind!" );
    ch->alignment = ch->alignment - 50;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );
    af.type = skill->id;
    af.duration  = 20 + ( ch->skill_level[FORCE_ABILITY] - victim->top_level ) / 2;
    af.location  = 0;
    af.modifier  = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_POSSESS );
    affect_join( victim, CHAR_AFFECT, &af );
    snprintf( buf, MSL, "You have possessed %s!\n", victim->short_descr );
    ch->desc->character = victim;
    ch->desc->original  = ch;
    victim->desc        = ch->desc;
    ch->desc            = NULL;
    ch->switched        = victim;
    send_to_char( buf, victim );
    return rNONE;
}

/* Ignores pickproofs, but can't unlock containers. -- Altrag 17/2/96 */
SPELLF spell_knock( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    EXIT_DATA* pexit;
    set_char_color( AT_MAGIC, ch );

    /*
        shouldn't know why it didn't work, and shouldn't work on pickproof
        exits.  -Thoric
    */
    if ( !( pexit = find_door( ch, target_name, FALSE ) )
            ||   !xIS_SET( pexit->flags, EX_CLOSED )
            ||   !xIS_SET( pexit->flags, EX_LOCKED )
            ||    xIS_SET( pexit->flags, EX_PICKPROOF ) )
    {
        failed_casting( skill, ch, NULL, NULL );
        return rSPELL_FAILED;
    }

    xREMOVE_BIT( pexit->flags, EX_LOCKED );
    ch_println( ch, "*Click*" );

    if ( pexit->rexit && pexit->rexit->to_room == ch->in_room )
        xREMOVE_BIT( pexit->rexit->flags, EX_LOCKED );

    check_room_for_traps( ch, TRAP_UNLOCK | trap_door[pexit->vdir] );
    return rNONE;
}

