    ch_println( ch, "&c&BConcentrating on the Force, you shape a dream in your target's mind." );
    ch_println( victim, "&c&BYour mind swirls in your sleep..." );
    ch_println( victim, "You have dreams about %s.", target_name );
    ch_println( ch, "Ok." );
    return rNONE;
