SPELLF spell_force_lightning( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    int dam = 0, attacks = 0, i = 0;
    OBJ_DATA* obj = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    obj = get_eq_char( victim, WEAR_WIELD );

    if ( obj && obj->value[3] != WEAPON_LIGHTSABER )
        obj = NULL;

    attacks = ( ch->skill_level[FORCE_ABILITY] / 20 ) + number_range( 0, 2 );

    if ( attacks == 0 )
        attacks++;

    interrupt_ch( victim );

    while ( i < attacks && !char_extracted( victim ) )
    {
        i++;
        int parryperc = ( IS_NPC( victim ) || has_pcflag( victim, PCFLAG_NO_SENSE ) ) ? 0 : get_learned_pct( victim, cache_skill( "parry", &skill_parry ) );

        if ( obj && !IS_NPC( victim ) && number_range( 1, 160 ) < parryperc )
        {
            act( AT_WHITE, "You raise your lightsaber, and the blade absorbs the lightning.", ch, NULL, victim, TO_VICT );
            act( AT_WHITE, "White lightning arcs from $n's fingertips, but is absorbed by $N's lightsaber!", ch, NULL, victim, TO_NOTVICT );
            act( AT_WHITE, "White lightning arcs from your fingertips, but is absorbed by $N's lightsaber!", ch, NULL, victim, TO_CHAR );
            learn_from_success( victim, cache_skill( "parry", &skill_parry ) );
            continue;
        }

        if ( is_immune( victim, RIS_ENERGY ) || ( xIS_SET( victim->immune, RIS_MAGIC ) ) ||
                !negative_spell_succeeds( ch, skill, victim ) )
        {
            act( AT_WHITE, "You resist the energy.", ch, NULL, victim, TO_VICT );
            act( AT_WHITE, "White lightning arcs from your fingertips, but does nothing to $N!", ch, NULL, victim, TO_CHAR );
            act( AT_WHITE, "White lightning arcs from $n's fingertips, but does nothing to you!", ch, NULL, victim, TO_VICT );
            act( AT_WHITE, "White lightning arcs from $n's fingertips, but does nothing to $N!", ch, NULL, victim, TO_NOTVICT );
            continue;
        }

        if ( number_percent() < get_curr_dex( victim ) )
        {
            act( AT_WHITE, "A surge of white lightning arcs from your fingertips, narrowly missing $N!", ch, NULL, victim, TO_CHAR );
            act( AT_WHITE, "A surge of white lightning arcs from $n's fingertips, narrowly missing you!", ch, NULL, victim, TO_VICT );
            act( AT_WHITE, "A surge of white lightning arcs from $n's fingertips, narrowly missing $N!", ch, NULL, victim, TO_NOTVICT );
            continue;
        }

        act( AT_LBLUE, "A surge of white lightning arcs from your fingertips, jolting $N!", ch, NULL, victim, TO_CHAR );
        act( AT_RED, "A surge of white lightning arcs from $n's fingertips, searing you painfully!", ch, NULL, victim, TO_VICT );
        act( AT_LBLUE, "A surging arc of white lightning from $n's fingertips jolts $N!", ch, NULL, victim, TO_NOTVICT );
        dam = number_range( 60, 120 ); // Gradually increase damage as we go
        worsen_mental_state( victim, number_range( 0, 1 ) );

        if ( victim->hit > 0 && ( victim->hit - dam ) < 0 )
            act( AT_ACTION, "$n falls to the ground, smouldering!", victim, NULL, NULL, TO_ROOM );

        if ( victim->hit > -150 )
        {
            victim->hit = URANGE( -150, victim->hit - dam, victim->max_hit );

            if ( victim->hit < -100 )
            {
                act( AT_ACTION, "$n smoulders, smoke rising from $s body.", victim, NULL, NULL, TO_ROOM );
                break;
            }
        }

        if ( victim->hit < -149  )
            victim->hit = URANGE( -499, victim->hit - dam, victim->max_hit );

        if ( victim->hit == -499 && !IS_IMMORTAL( victim ) )
        {
            act( AT_ACTION, "$n looks like $e is almost dead!", victim, NULL, NULL, TO_ROOM );
            ch_println( ch, "If you want to finish this, use MURDER PERM." );
        }
    }

    sith_penalty( ch );
    return rNONE;
}

SPELLF spell_armor( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    AFFECT_DATA af;
    af.type = skill->id;
    af.location  = APPLY_AC;
    af.modifier  = -200;
    af.duration  = 1000;
    xCLEAR_BITS( af.bitvector );
    affect_replace( ch, CHAR_AFFECT, &af );
    act( AT_MAGIC, "$n's body is shrouded in a pulsing energy.", ch, NULL, NULL, TO_ROOM );
    act( AT_MAGIC, "Your body is shrouded in a pulsing energy!", ch, NULL, NULL, TO_CHAR );
    return rNONE;
}

SPELLF spell_battle_meditation( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* vch;
    AFFECT_DATA af;

    if ( count_group( ch ) == 0 )
    {
        gen_message( ch, "nogroup" );
        return rINVALID_ARGS;
    }

    if ( who_fighting( ch ) )
    {
        ch_println( ch, "You cannot do this during combat." );
        return rINVALID_ARGS;
    }

    for ( vch = ch->in_room->first_person; vch; vch = vch->next_in_room )
    {
        if ( vch != ch && vch->leader != ch )
            continue;

        affect_strip( vch, CHAR_AFFECT, skill );
        af.type = skill->id;
        af.duration  = level;
        af.location  = APPLY_HITROLL;
        af.modifier  = 10;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_BATTLE_MEDITATION );
        affect_to_target( vch, CHAR_AFFECT, &af );
        af.location  = APPLY_DAMROLL;
        af.modifier  = 10;
        xCLEAR_BITS( af.bitvector );
        affect_to_target( vch, CHAR_AFFECT, &af );

        if ( vch != ch )
            act( AT_MAGIC, "As $n adopts a meditative pose, your spirits are lifted and you feel ready for battle.", ch, NULL, vch, TO_VICT );
        else
            act( AT_MAGIC, "You close your eyes and instill hope and focus into the minds of your group.", ch, NULL, vch, TO_CHAR );
    }

    return rNONE;
}

