/*
    saving throw check                       -Thoric
*/
bool check_save( SKILL_DATA* skill, int level, CHAR_DATA* ch, CHAR_DATA* victim )
{
    bool saved = FALSE;

    if ( SPELL_FLAG( skill, SF_PKSENSITIVE )
            &&  !IS_NPC( ch ) && !IS_NPC( victim ) )
        level /= 2;

    if ( skill->saves )
        switch ( skill->saves )
        {
            case SS_POISON_DEATH:
                saved = saves_poison_death( level, victim );
                break;

            case SS_ROD_WANDS:
                saved = saves_wands( level, victim );
                break;

            case SS_PARA_PETRI:
                saved = saves_para_petri( level, victim );
                break;

            case SS_BREATH:
                saved = saves_breath( level, victim );
                break;

            case SS_SPELL_STAFF:
                saved = saves_spell_staff( level, victim );
                break;
        }

    return saved;
}

/*
    Generic offensive spell damage attack            -Thoric
*/
SPELLF spell_attack( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    bool saved = check_save( skill, level, ch, victim );
    int dam;
    ch_ret retcode;
    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 100;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );

    if ( saved && !SPELL_FLAG( skill, SF_SAVE_HALF_DAMAGE ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( skill->dice )
        dam = UMAX( 0, dice_parse( ch, level, skill->dice ) );
    else
        dam = dice( 1, level );

    if ( saved )
        dam /= 2;

    retcode = damage( ch, victim, dam, skill->id );

    return retcode;
}

/*
    Generic area attack                      -Thoric
*/
SPELLF spell_area_attack( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    bool saved;
    int dam;
    ch_ret retcode = 0;
    ch_println( ch, "You feel the hatred grow within you!" );
    ch->alignment = ch->alignment - 100;
    ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    sith_penalty( ch );

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFE ) )
    {
        failed_casting( skill, ch, NULL, NULL );
        return rSPELL_FAILED;
    }

    if ( !NULLSTR( skill->hit_char ) )
        act( AT_MAGIC, skill->hit_char, ch, NULL, NULL, TO_CHAR );

    if ( !NULLSTR( skill->hit_room ) )
        act( AT_MAGIC, skill->hit_room, ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( !IS_NPC( vch ) && has_pcflag( vch, PCFLAG_WIZINVIS )
                && vch->pcdata->wizinvis >= LEVEL_IMMORTAL )
            continue;

        if ( vch != ch && ( IS_NPC( ch ) ? !IS_NPC( vch ) : IS_NPC( vch ) ) )
        {
            saved = check_save( skill, level, ch, vch );

            if ( saved && !SPELL_FLAG( skill, SF_SAVE_HALF_DAMAGE ) )
            {
                failed_casting( skill, ch, vch, NULL );
                dam = 0;
            }
            else if ( skill->dice )
                dam = dice_parse( ch, level, skill->dice );
            else
                dam = dice( 1, level );

            if ( saved && SPELL_FLAG( skill, SF_SAVE_HALF_DAMAGE ) )
                dam /= 2;

            retcode = damage( ch, vch, dam, skill->id );
        }

        if ( retcode == rCHAR_DIED || char_extracted( ch ) )
            break;
    }

    return retcode;
}

int meditate_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&RYou rise from your trance, pushing the thoughts aside." );
    return E_LOTJ_SUCCESS;
}

int meditate_complete( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch->substate = SUB_NONE;
    SKILL_DATA* skill = cache_skill( "meditate", &skill_meditate );
    int chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, skill ) );
    if ( number_percent( ) > chance )
    {
        ch_println( ch, "&RYou are disrupted by outside thoughts, and stop your meditations." );
        learn_from_failure( ch, skill );
        return E_LOTJ_ASYNC_VALIDATION_FAILED;
    }

    ch_println( ch, "&zYou complete your meditations. You feel the Force pulsing through you.&w" );
    /* Mana Increase */
    int boost = ( ch->perm_frc * chance ) / 5;

    if ( IS_AFFECTED( ch, AFF_CLARITY ) )
        boost += ( int )( 4 * ( boost / 10 ) );

    if ( has_pcflag( ch, PCFLAG_NO_SENSE ) )
        boost = 0;

    ch->mana = URANGE( 0, ch->mana + boost, ch->max_mana );

    // Meditating in a specific room can teach you a new spell?
    SKILL_DATA* temple_skill = NULL;
    for ( temple_skill = first_skill; temple_skill; temple_skill = temple_skill->next )
        if ( temple_skill->temple == ch->in_room->vnum )
            break;

    if ( temple_skill )
    {
        if ( number_range( 1, 20 ) == 2 && get_learned_pct( ch, temple_skill ) == 0 )
        {
            ch_println( ch, "&WAs you meditate you find enlightenment in the Force." );
            learn_from_success( ch, temple_skill );
        }
    }

    if ( ch->mental_state > 0 )
    {
        chance = IS_NPC( ch ) ? ch->top_level : ( ( int )ch->skill_level[FORCE_ABILITY] / 10 )  + ( ( get_curr_int( ch ) + get_curr_wis( ch ) ) / 2 );
        chance -= UMAX( 1, ( int )( ch->mental_state * 0.9 ) );
        better_mental_state( ch, number_range( ( int )( chance * 0.1 ), ( int )( chance * 0.4 ) ) );
        ch_println( ch, "You calm your mind somewhat." );
    }

    ch->move = URANGE( 0, ch->move + get_curr_con ( ch ) + ch->skill_level[FORCE_ABILITY], ch->max_move );

    /* Force Experience --- Only up to level 10 */
    if ( ch->skill_level[FORCE_ABILITY] <= 10 )
    {
        int xp = chance;
        xp = URANGE( 0, xp, ( exp_level( ch->skill_level[FORCE_ABILITY] + 1 ) - exp_level( ch->skill_level[FORCE_ABILITY] ) ) / 35 );
        xp = apply_xp_sink( ch, xp, FORCE_ABILITY );
        ch_println( ch, "You gain %d Force experience from your meditation.", xp );
        gain_exp( ch, xp, FORCE_ABILITY, FALSE );
    }

    learn_from_success( ch, skill );

    if ( ch->mana < ch->max_mana )
    {
        ch_println( ch, "&zYou continue your meditations..." );
        add_timer( ch, TIMER_DO_FUN, 12, meditate_complete, meditate_abort, FUNC );
    }
    return E_LOTJ_SUCCESS;
}

CMDF do_meditate( CHAR_DATA* ch, char* argument )
{
    if ( has_pcflag( ch, PCFLAG_NO_SENSE ) )
    {
        ch_println( ch, "You cannot meditate while cut off from the Force." );
        return;
    }

    if ( ch->spirit )
    {
        ch_println( ch, "Only the living have the ability to meditate effectively." );
        return;
    }

    if ( who_fighting( ch ) )
    {
        ch_println( ch, "You cannot focus in the midst of combat." );
        return;
    }

    if ( ch->block )
    {
        act( AT_ACTION, "$n is no longer blocking a direction.", ch, NULL, NULL, TO_ROOM );
        set_char_color( AT_ACTION, ch );
        ch_println( ch, "You are no longer blocking a direction." );
        action_clear_ex( ch, AS_UNLOCK );
        ch->block = NULL;
    }

    if ( ch->race == get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&WYou close your eyes and softly hum your clan's meditation tune." );
        act( AT_SOCIAL, "$n closes $s eyes and hums softly to $mself.", ch, NULL, argument, TO_ROOM );
    }
    else
    {
        ch_println( ch, "&zYou begin to meditate, tuning yourself to the Force." );
        act( AT_SOCIAL, "$n closes $s eyes, breathing deeply.", ch, NULL, argument, TO_ROOM );
    }

    action_set( ch, NULL, "is in a meditative pose, eyes closed.", NULL, 0 );
    add_timer( ch, TIMER_DO_FUN, 12, meditate_complete, meditate_abort, FUNC );
}

char* fclass( int frank, int fclass, int ali )
{
    static char result[MSL];
    char buf1[MIL];
    char buf2[MIL];

    strlcpy( result, "", MSL );

    if ( fclass == SITH_DARKLORD )
        return "&RDark Lord of the Sith";

    switch ( frank )
    {
        case 0:
            strlcpy( result, "&WNone", MIL );
            return result;

        case 1:
            strlcpy( buf1, "Apprentice", MIL );
            break;

        case 2:
            strlcpy( buf1, "Knight", MIL );
            break;

        case 3:
            strlcpy( buf1, "Master", MIL );
            break;

        default:
            strlcpy( result, "&WNone", MIL );
            return result;
    }

    switch ( fclass )
    {
        case JEDI_NONE:
            strlcpy( buf2, "", MIL );
            break;

        case JEDI_GUARDIAN:
            strlcpy( buf2, "Guardian", MIL );
            break;

        case JEDI_SENTINEL:
            strlcpy( buf2, "Sentinel", MIL );
            break;

        case JEDI_CONSULAR:
            strlcpy( buf2, "Consular", MIL );
            break;

        case JEDI_SAGE:
            strlcpy( buf2, "Sage", MIL );
            break;

        case SITH_JUGGERNAUT:
            strlcpy( buf2, "Juggernaut", MIL );
            break;

        case SITH_ASSASSIN:
            strlcpy( buf2, "Assassin", MIL );
            break;

        case SITH_SORCERER:
            strlcpy( buf2, "Sorcerer", MIL );
            break;

        default:
            strlcpy( buf2, "", MIL );
            break;
    }

    int align = ali < -300 ? 2 : ali > 300 ? 1 : 0;

    /* finally, we make our return value */
    snprintf( result, MSL, "%s%s%s%s%s%s", align == 1 ? "&G" : align == 2 ? "&R" : "&W", buf1, align != 0 ? " " : "", align == 1 ? "Jedi" : align == 2 ? "Sith" : "",
             NULLSTR( buf2 ) ? "" : " ", NULLSTR( buf2 ) ? "" : buf2 );

    return result;
}

bool fclass_select( CHAR_DATA* ch, char* argument )
{
    int x = 0;

    if ( !ch || !argument || IS_NPC( ch ) )
        return FALSE;

    if ( max_level( ch, FORCE_ABILITY ) < 35 )
    {
        ch_println( ch, "You are not proficient enough in the Force to do that.." );
        return FALSE;
    }

    if ( ch->pcdata->fclass != JEDI_NONE )
    {
        ch_println( ch, "You have already selected your Force class." );
        return FALSE;
    }

    if ( ( NULLSTR( argument ) || !str_cmp( "list", argument ) ) && ( IS_GOOD( ch ) || IS_NEUTRAL( ch ) ) ) //This menu should only show up for Good/Neutral Forcers as part of Jan 2017 Subclass upgrade. -Gathorn 15Jan2017
    {
        send_to_char( "Options for Force class choice:\n\n"
                      "&cClass            Level bonus                 FP/level   Other bonus(es)\n"
                      "&zNot selected     -                           5          -\n"
                      "Guardian         +70 com, +30 esp, +20 pil   20         Force Combat \n", ch );
        send_to_char(
            "Sentinel         +50 smu, +40 com, +30 sli   25         Force Suppression\n"
            "Consular         +50 dip, +40 com, +30 eng   35         Force Mastery\n"
            "Choose wisely, as you may not reconsider.\napprentice class <class name>\n", ch );
        return FALSE;
    }

    if ( ( NULLSTR( argument ) || !str_cmp( "list", argument ) ) && IS_EVIL( ch ) ) //This menu should only show up for Evil Forcers as part of Jan 2017 Subclass upgrade. -Gathorn 15Jan2017
    {
        send_to_char( "Options for Force class choice:\n\n"
                      "&cClass            Level bonus                 FP/level   Other bonus(es)\n"
                      "&zNot selected     -                           5          -\n"
                      "Juggernaut       +70 com, +30 esp, +20 pil   20         Force Combat \n", ch );
        send_to_char(
            "Assassin         +50 smu, +40 com, +30 sli   25         Force Suppression\n"
            "Sorcerer         +50 dip, +40 com, +30 eng   35         Force Mastery\n"
            "Choose wisely, as you may not reconsider.\napprentice class <class name>\n", ch );
        return FALSE;
    }

    if ( !str_cmp( "guardian", argument ) )
        x = JEDI_GUARDIAN;
    else if ( !str_cmp( "sentinel", argument ) )
        x = JEDI_SENTINEL;
    else if ( !str_cmp( "consular", argument ) )
        x = JEDI_CONSULAR;
    else if ( !str_cmp( "juggernaut", argument ) )
        x = SITH_JUGGERNAUT;
    else if ( !str_cmp( "assassin", argument ) )
        x = SITH_ASSASSIN;
    else if ( !str_cmp( "sorcerer", argument ) )
        x = SITH_SORCERER;
    //      Consulars no longer receive a force boost due to Jan 2017 subclass update. -Gathorn 14Jan2017
    //        ch->perm_frc = UMIN( 30, ch->perm_frc+2 );
    /*    else if ( !str_cmp( "sage", argument ) )
            x = JEDI_SAGE;*/
    else
    {
        ch_println( ch, "That is not a valid force class." );
        return FALSE;
    }

    switch ( x )
    {
        case SITH_JUGGERNAUT:
        case SITH_ASSASSIN:
        case SITH_SORCERER:
            if ( IS_GOOD( ch ) || IS_NEUTRAL ( ch ) )
            {
                ch_println( ch, "This class is a path of the Sith. Choose a path of the Jedi!" );
                return FALSE;
            }

            break;

        case JEDI_GUARDIAN:
        case JEDI_SENTINEL:
        case JEDI_CONSULAR:
            if ( IS_EVIL( ch ) )
            {
                ch_println( ch, "This class is a path of the Jedi. Choose a path of the Sith!" );
                return FALSE;
            }

            break;
    }

    ch->pcdata->fclass = x;
    ch_println( ch, "Alright, you are now %s.", aoran( fclass( ch->pcdata->frank, ch->pcdata->fclass, ch->alignment ) ) );
    //GRAL DONE, if I don't have force class ie not awoken, and my legacymax force is 0 or default then re-max me
    //     Custommax is not factored though. Watch out!
    int ra;

    for ( ra = 0; ra < MAX_ABILITY; ra++ )
        ch->legacymax[ra] = 0;

    save_char_obj( ch, TRUE );
    return TRUE;
}

void immprentice( CHAR_DATA* ch, char* argument, sh_int trust )
{
    char arg[MIL], arg2[MIL], arg3[MIL], date_buf[32], level_buf[32], colstr[8];
    FORCER_DATA* forcer = NULL, *fnext = NULL;
    int cnt = 0;
    bool list_all = FALSE;    
    sh_int align = 0;

    if ( !ch || !argument || trust < LEVEL_PR )
        return;

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );    

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Capprentice list" );
        ch_println( ch, "&z        &Capprentice list all" );
        ch_println( ch, "&z        &Capprentice list <&wjedi/sith/neutral&C>" );
        ch_println( ch, "&z        &Capprentice list all <&wjedi/sith/neutral&C>" );
        ch_println( ch, "&z        &Capprentice show <&wname&C>" );
        if ( trust >= LEVEL_PR_ADMIN )
        {
            ch_println( ch, "&z        &Capprentice remove <&wname&C>" );
            ch_println( ch, "&z        &Capprentice removemaster <&wname&C>" );
        }
        if ( trust >= LEVEL_ADMIN )
            ch_println( ch, "&z        &Capprentice removemaster <&wname&C>" );

        return;
    }

    if ( !str_cmp( arg, "show" ) )
    {
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Capprentice show <&wname&C>" );
            return;
        }

        forcer = forcer_get( arg2 );
        if ( !forcer )
        {
            ch_println( ch, "&wCould not find any forcer records for %s.", arg2 );
            return;
        }

        ch_println( ch, "&zDisplaying forcer record&z...\n" );
        ch_println( ch, "&zName: &C%s", forcer->name );
        ch_println( ch, "&zAwakened by: &C%s", !NULLSTR( forcer->awakened_by ) ? forcer->awakened_by : "Unknown" );
        ch_println( ch, "&zAwakened at: &C%s", forcer->awakened_at > 0 ? c_time( forcer->awakened_at, get_timezone( ch ) ) : "Unknown" );
        ch_println( ch, "&zMaster: &C%s", !NULLSTR( forcer->master ) ? forcer->master : "None" );
        ch_println( ch, "&zClan: &C%s", !NULLSTR( forcer->clan ) ? forcer->clan : "None" );
        ch_println( ch, "&zForce Stat: &C%d", forcer->perm_frc );
        ch_println( ch, "&zLevel: &C%d&z/&C%d", forcer->curr_level, forcer->max_level );
        ch_println( ch, "&zAlignment: &C%d", forcer->alignment );
        ch_println( ch, "&zForce Rank: &C%s", get_manual_frank( forcer->fclass, forcer->frank, forcer->alignment ) );
        ch_println( ch, "&zForce Class: &C%s", fclass( forcer->frank, forcer->fclass, forcer->alignment ) );
        ch_println( ch, "&zSource: &C%s", get_froll( forcer->source ) );
        return;
    }

    if ( !str_cmp( arg, "list" ) )
    {
        list_all = !str_cmp( arg2, "all" );

        if ( ( list_all && !NULLSTR( arg3 ) ) || ( !list_all && !NULLSTR( arg2 ) ) )
        {
            if ( !str_cmp( list_all ? arg3 : arg2, "jedi" ) )
                align = ALIGNMENT_GOOD;
            else if ( !str_cmp( list_all ? arg3 : arg2, "sith" ) )
                align = ALIGNMENT_EVIL;
            else if ( !str_cmp( list_all ? arg3 : arg2, "neutral" ) )
                align = ALIGNMENT_NEUTRAL;
            else
            {
                if ( list_all )
                    ch_println( ch, "&zSyntax: &Capprentice list all <&wjedi/sith/neutral&C>" );
                else
                    ch_println( ch, "&zSyntax: &Capprentice list <&wjedi/sith/neutral&C>" );

                return;
            }
        }

        if ( !first_forcer )
        {
            ch_println( ch, "There are currently no forcer entries." );
            return;
        }

        ch_println( ch, "&z%-12s | %-7s | %-12s | %-8s | %-12s | %-14s", "NAME", "LEVEL", "RANK", "ACTIVE", "MASTER", "CLAN" );
        ch_println( ch, "&z--------------------------------------------------------------------------------" );

        for ( forcer = first_forcer; forcer; forcer = forcer->next )
        {
            if ( forcer->perm_frc < 12 && !list_all )
                continue;

            // Skip non-matching alignments
            switch ( align )
            {
                case 0:
                    break;

                case ALIGNMENT_NEUTRAL:
                    if ( forcer->alignment != 0 )
                        continue;
                    break;

                case ALIGNMENT_GOOD:
                    if ( forcer->alignment <= 0 )
                        continue;
                    break;

                case ALIGNMENT_EVIL:
                    if ( forcer->alignment >= 0 )
                        continue;
                    break;

                default:
                    break;
            }

            cnt++;
            time_t last_seen = player_last_seen( forcer->name );

            snprintf( date_buf, 32, "%s", last_seen > 0 ? micro_c_time( last_seen, get_timezone( ch ) ) : "Unknown" );
            snprintf( level_buf, 32, "%d/%d", forcer->curr_level, forcer->max_level );
            snprintf( colstr, 8, "%s", cnt % 2 == 0 ? "&037" : "&116" );

            ch_println( ch,
                "%s%-12s &z| %s%-7s &z| %s%-12s &z| %s%-8s &z| %s%-12s &z| %s%-14s",
                colstr, truncate_string( forcer->name, 12 ),
                colstr, level_buf,
                forcer->alignment < 0 ? "&R" : forcer->alignment > 0 ? "&G" : "&W", truncate_string( stripclr( get_manual_frank( forcer->fclass, forcer->frank, forcer->alignment ) ), 12 ),
                colstr, date_buf,
                colstr, forcer->master ? truncate_string( forcer->master, 12 ) : "(None)",
                colstr, forcer->clan ? truncate_string( forcer->clan, 14 ) : "(None)"
            );
        }

        if ( cnt > 0 )
            ch_println( ch, "&zDisplayed &C%'d&z matching forcers.", cnt );

        return;
    }

    if ( !str_cmp( arg, "clear" ) && trust >= LEVEL_ADMIN )
    {
        for ( forcer = first_forcer; forcer; forcer = fnext )
        {
            fnext = forcer->next;
            forcer_delete( forcer );
            cnt++;
        }

        ch_printf( ch, "&zRemoved a total of &C%'d&z forcer entries.", cnt );
        return;
    }

    if ( !str_cmp( arg, "remove" ) && trust >= LEVEL_PR_ADMIN )
    {
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Capprentice remove <&wname&C>" );
            return;
        }

        forcer = forcer_get( arg2 );

        if ( forcer )
        {
            ch_println( ch, "&zDeleting &C%s&z's forcer entry.", forcer->name );
            forcer_delete( forcer );
        }
        else
            ch_println( ch, "&zCould not find forcer entry for &C%s&z. Try another name.", arg2 );

        return;
    }

    if ( !str_cmp( arg, "removemaster" ) && trust >= LEVEL_PR_ADMIN )
    {
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Capprentice removemaster <&wname&C>" );
            return;
        }

        forcer = forcer_get( arg2 );

        if ( forcer )
        {
            if ( !forcer->master )
            {
                ch_println( ch, "&zThere is no master currently set for &C%s&z.", forcer->name );
                return;
            }

            ch_println( ch, "&zRemoving &C%s&z as &C%s&z's master in their forcer entry.", forcer->master, forcer->name );
            remove_force_master( forcer );
        }
        else
            ch_println( ch, "&zCould not find forcer entry for &C%s&z. Try another name.", arg2 );

        return;
    }

    immprentice( ch, "", trust );
}

/*
    Allows a MASTER JEDI to take on an apprentice.
*/
CMDF do_apprentice( CHAR_DATA* ch, char* argument )
{
    char arg[MIL], arg2[MIL], arg3[MIL];
    GREET_DATA* greet = NULL;
    FORCER_DATA* forcer = NULL;
    CHAR_DATA* victim = NULL;
    sh_int trust = ch ? get_trust( ch ) : 0;

    if ( IS_NPC( ch ) )
        return;

    if ( trust >= LEVEL_PR )
    {
        immprentice( ch, argument, trust );
        return;
    }

    argument = one_argument( argument, arg );
    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( ch->pcdata->frank == FRANK_NONE || ch->perm_frc == 0 )
    {
        ch_println( ch, "You can't apprentice anyone." );
        return;
    }

    if ( !str_cmp( arg, "class" ) || !str_cmp( arg, "subclass" ) )
    {
        if ( fclass_select( ch, arg2 ) )
            forcer = forcer_create( ch );

        return;
    }

    if ( ch->pcdata->frank < FRANK_KNIGHT )
    {
        forcer = forcer_create( ch );

        if ( !forcer )
        {
            bug( "%s: Forcer entry not found and could not be created for %s", FUNC, ch->name );
            return;
        }

        if ( NULLSTR( forcer->master ) )
        {
            ch_println( ch, "You don't currently have a master." );
            return;
        }

        if ( str_cmp( arg, "none" ) )
        {
            ch_println( ch, "&RYou must obtain the rank of %s before you can do that!", get_auto_frank( ch, FRANK_MASTER ) );
            ch_println( ch, "If you are trying to leave your apprenticeship, type APPRENTICE NONE." );
            return;
        }

        if ( str_cmp( arg2, "confirm" ) )
        {
            ch_println( ch, "Are you sure? Abandoning your master will decrease all skill percentages you have by 20%, and you will lose 100,000 experience in the force.\nYou will, however, be able to be taught under someone else's tutelage. Choose wisely.\nIf you truly wish to proceed, type APPRENTICE NONE CONFIRM." ) ;
            return;
        }

        remove_force_master( forcer );
        ch_println( ch, "&RYou abandon the teachings of your master!" );
        ch->experience[FORCE_ABILITY] = URANGE( 1, ch->experience[FORCE_ABILITY] - 100000, ch->experience[FORCE_ABILITY] );

        for ( LEARNED_DATA* learned = ch->first_learned; learned; learned = learned->next )
            if ( learned->skill && learned->skill->guild == FORCE_ABILITY )
                if ( learned->pct > 0 )
                    set_learned_pct( ch, learned->skill, URANGE( 1, learned->pct - 20, 100 ) );

        send_to_char( "As you make your decision, you feel the force react within you!\n"
                      "You feel as if your teachings have been weakened. You should seek a new master!\n", ch );

        save_char_obj( ch, TRUE );
        return;
    }

    // Temporarily disabling "apprentice promote". Maybe forever. Who knows. - Nield 04/08/2025
    /*
    if ( !str_cmp( arg, "promote" ) )
    {
        if ( NULLSTR( arg2 ) )
        {
            ch_println( ch, "&zSyntax: &Capprentice promote <&wname&C>" );
            return;
        }

        if ( sysdata.ruleoftwo == TRUE && !str_cmp( sysdata.sithlord, ch->name ) )
        {
            ch_println( ch, "You cannot do that. Your apprentice must kill you to ascend to the rank of master." );
            return;
        }

        if ( ( victim = get_char_room( ch, arg2 ) ) == NULL )
        {
            ch_println( ch, "Nobody like that nearby to promote." );
            return;
        }

        if ( ch->pcdata && ch->pcdata->frank == FRANK_KNIGHT )
        {
            ch_println( ch, "Knights are unable to promote others to the rank of master." );
            return;
        }

        if ( IS_NPC( victim ) || victim->pcdata->frank != FRANK_KNIGHT )
        {
            ch_println( ch, "You can only raise the Force rank of a knight." );
            return;
        }

        victim->pcdata->frank = FRANK_MASTER;
        forcer = forcer_create( victim );
        ch_println( ch, "You have raised %s's rank from %s to %s.", g_name( victim, ch ), get_auto_frank( victim, FRANK_KNIGHT ), get_auto_frank( victim, FRANK_MASTER ) );
        ch_println( victim, "You have been granted the status of %s.", get_auto_frank( victim, FRANK_MASTER ) );
        save_char_obj( victim, TRUE );
        return;
    } */

    forcer = forcer_get_apprentice( ch, FALSE );

    if ( forcer )
    {
        if ( !str_cmp( arg, "none" ) )
        {
            clear_apprentices( ch->name );
            gain_exp( ch, -50000, FORCE_ABILITY, FALSE );
            ch_println( ch, "&RYou no longer have an apprentice. You have lost 50000 force exp." );
        }
        else
        {
            ch_println( ch, "&RIt would appear you have already taken on an apprentice!" );
            ch_println( ch, "&RYou may ditch your current apprentice with APPRENTICE NONE," );
            ch_println( ch, "&Rdoing so will penalize you 50000 exp. Use with caution." );
        }

        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "You can't seem to find that person here..." );
        return;
    }

    if ( ch == victim )
    {
        ch_println( ch, "You're not going to teach yourself!" );
        return;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "They'd be a pretty subpar apprentice..." );
        return;
    }

    greet = fetch_greet( ch, victim );

    if ( !greet || !xIS_SET( greet->flags, GREET_KNOWN ) || xIS_SET( greet->flags, GREET_INFORM ) )
    {
        ch_println( ch, "You must first be greeted by your apprentice." );
        return;
    }

    greet = fetch_greet( victim, ch );

    if ( !greet || !xIS_SET( greet->flags, GREET_KNOWN ) || xIS_SET( greet->flags, GREET_INFORM ) )
    {
        ch_println( ch, "You must first greet your apprentice." );
        return;
    }

    if ( sysdata.ruleoftwo == TRUE && str_cmp( sysdata.sithlord, ch->name ) )
    {
        ch_println( ch, "You must become the Dark Lord of the Sith to have your own apprentice." );
        return;
    }

    if ( victim->skill_level[FORCE_ABILITY] < 2 )
    {
        ch_println( ch, "They must be at least a level 2 forcer first." );
        return;
    }

    if ( victim->pcdata->frank > FRANK_APPRENTICE )
    {
        ch_println( ch, "That person is not apprentice material. Try someone else." );
        return;
    }

    if ( check_apprentice( victim ) )
    {
        ch_println( ch, "They are already serving as someone else's apprentice!" );
        return;
    }

    ch_println( ch, "%s will now be taught under your apprenticeship.", victim->name );
    ch_println( victim, "You will now be taught under %s's apprenticeship.", ch->name );

    /* Move the victim to 'apprentice' rank if lower */
    if ( victim->pcdata->frank < FRANK_APPRENTICE )
        victim->pcdata->frank = FRANK_APPRENTICE;

    forcer = forcer_create( victim );

    if ( !forcer )
    {
        bug( "%s: error fetching or creating new forcer entry for %s.", FUNC, victim->name );
        return;
    }

    SET_STRING( forcer->master, ch->name );
    forcer_save( forcer, TRUE );

    if ( sysdata.ruleoftwo == TRUE && !str_cmp( sysdata.sithlord, ch->name ) )
    {
        if ( !str_cmp( arg2, "sith" ) )
        {
            ch_println( ch, "%s is now your official sith apprentice. They are your only apprentice able to attain masterhood and may not resign from the Sith Order. You may not select another Sith Apprentice unless they die.", victim->name );
            ch_println( victim, "You are now the official sith apprentice. You may not leave the Sith Order unless outcast. You are the Sith Apprentice until either you die or you kill your Master." );
            SET_STRING( sysdata.sithapprentice, victim->name );
            save_sysdata(&sysdata);
        }
        else
        {
            ch_println( ch, "Your new apprentice may not attain knighthood as they are not the official apprentice." );
            ch_println( victim, "You are in the Sith Order but are not the official apprentice, so you may not attain knighthood." );    
        }
    }

    add_follower( victim, ch, FALSE );
    save_char_obj( ch, TRUE );
    save_char_obj( victim, TRUE );
    return;
}

