    if ( ch->pcdata->fclass == SITH_DARKLORD )
        return "&RDark Lord of the Sith";

    if ( ch->pcdata->frank == FRANK_NONE )
        return "&WNone";
    /*  if ( ch->race == RACE_SITH )
