void remove_force_master( FORCER_DATA* forcer )
{
    if ( !forcer )
        return;

    SET_STRING( forcer->master, NULL );
    forcer_save( forcer, TRUE );
}

bool check_apprentice( CHAR_DATA* ch )
{
    FORCER_DATA* forcer = NULL;

    if ( !ch )
        return FALSE;

    if ( !first_forcer )
        return FALSE;

    forcer = forcer_create( ch );

    if ( !NULLSTR( forcer->master ) )
        return TRUE;

    return FALSE;
}

CHAR_DATA* fetch_apprentice( CHAR_DATA* ch, bool inroom )
{
    CHAR_DATA* victim = NULL;
    FORCER_DATA* forcer;
    char buf[MSL];
    strlcpy( buf, "", MSL );

    if ( !ch || ch == NULL )
        return NULL;

    for ( forcer = first_forcer; forcer; forcer = forcer->next )
    {
        if ( !str_cmp( forcer->master, ch->name ) )
        {
            victim = get_player_world( forcer->name );

            if ( victim != NULL )
                if ( !inroom || victim->in_room == ch->in_room )
                    if ( !IS_NPC( victim ) )
                        return victim;
        }
    }

    return NULL;
}

SPELLF spell_sense_attunement( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    char msg[MSL];
    int ap;

    if ( ch->pcdata->frank < FRANK_MASTER )
    {
        ch_println( ch, "&RYou must obtain the rank of %s before you can do that!", get_auto_frank( ch, FRANK_MASTER ) );
        return rINVALID_ARGS;
    }

    if ( !victim )
    {
        act( AT_ACTION, "&zSyntax: &Cfeel sense <&wtarget&C>", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( ch == victim )
    {
        act( AT_ACTION, "&zSyntax: &Cfeel sense <&wtarget&C>", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    ap = max_level( victim, FORCE_ABILITY );

    /* Sith ability... learn to hide your force. -Orionv */
    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_NO_SENSE ) )
        ap = 0;

    // GRAL Make sure you can never sense a noforce account skill for some odd chance it isn't already stripped
    //   Also need to have account for it to work to avoid the fluke accounts crash, you level 99->100 and sensed.
    //   ? Need a descriptor else you are linkdead.. could you be checked?
    //   Any reason to block 'child characters' from becoming awaken ie Younglings?
    if ( !victim || !victim->pcdata || !victim->pcdata->natroll_done )
        ap = 0;

    // GRAL Why block NPCs. Do we want NPCs to have force and visible in the planet ambience or awareness?
    if ( IS_NPC( victim ) )
        ap = 0;

    if ( ap > 80 )
        snprintf( msg, MSL, "$N is imbued with the raw power of the Force." );
    else if ( ap > 70 )
        snprintf( msg, MSL, "$N has great potential in the Force." );
    else if ( ap > 50 )
        snprintf( msg, MSL, "The Force courses through $N's veins." );
    else if ( ap > 25 )
        snprintf( msg, MSL, "$N is partially attuned to the Force." );
    else if ( ap > 1 )
        snprintf( msg, MSL, "$N seems to have very little connection to the Force." );
    else if ( victim && victim->pcdata && !victim->pcdata->natroll_done )
        snprintf( msg, MSL, "$N's potential connection to the Force is not yet manifest." );
    else
        snprintf( msg, MSL, "$N appears to have no Force potential." );

    act( AT_MAGIC, msg, ch, NULL, victim, TO_CHAR );
    return rNONE;
}

SPELLF spell_awaken_force( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    int ap;
    FORCER_DATA* forcer = NULL;
    char buf[MSL];

    if ( ch->pcdata->frank < FRANK_MASTER )
    {
        ch_println( ch, "&RYou must obtain the rank of %s before you can do that!", get_auto_frank( ch, FRANK_MASTER ) );
        return rINVALID_ARGS;
    }

    if ( !victim || victim == ch )
    {
        act( AT_ACTION, "&zSyntax: &Cfeel awaken <&wtarget&C>", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( victim->desc && !victim->desc->account )
    {
        ch_println( ch, "&RTheir character must be attached to an account first!" );
        ch_println( victim, "&RYour character must be attached to an account before you can be awoken!" );
        return rINVALID_ARGS;
    }

    if ( victim->desc && xIS_SET( victim->desc->account->flags, ACC_NOFORCE ) )
    {
        snprintf( buf, MSL, "%s attempting to awaken %s, but they have the noforce account flag.", ch->name, victim->name );
        bug( buf );
        return rSPELL_FAILED;
    }

    if ( ch == victim || IS_NPC( victim ) )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC ) || xIS_SET( victim->desc->account->flags, ACC_NOFORCE ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    ap = max_level( victim, FORCE_ABILITY );

    if ( ( victim->top_level < 100 && !IS_NPC( victim ) && !has_pcflag( victim, PCFLAG_CHILD ) ) || ap < 5 || victim->skill_level[FORCE_ABILITY] > 1 )
    {
        failed_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    forcer = forcer_create( victim );
    if ( !forcer )
    {
        bug( "%s: could not fetch or create forcer entry for %s", FUNC, victim->name );
        return rSPELL_FAILED;
    }

    act( AT_MAGIC, "Raw energy surges through $N, awakening The Force within!", ch, NULL, victim, TO_CHAR );
    act( AT_MAGIC, "Raw energy surges through you, awakening The Force within!", ch, NULL, victim, TO_VICT );
    act( AT_MAGIC, "A radiant aura surrounds $n and $N!", ch, NULL, victim, TO_NOTVICT );

    victim->pcdata->awakened_at = current_time;
    victim->experience[FORCE_ABILITY] = exp_level( 2 );
    gain_exp( victim, 0, FORCE_ABILITY, FALSE );
    bool had_feat = false;

    for ( SKILL_DATA* skill = first_skill; skill; skill = skill->next )
    {
        if ( skill->type == SKILL_FEAT && get_learned_pct( victim, skill ) > 0 )
        {
            had_feat = true;
            set_learned_pct( victim, skill, 0 );
        }
    }

    if ( had_feat )
        act( AT_OOC, "Your feats have been reset.", ch, NULL, victim, TO_VICT );

    SET_STRING( forcer->awakened_by, ch->name );
    forcer->awakened_at = time( 0 );
    forcer_save( forcer, TRUE );
    save_char_obj( ch, TRUE );
    return rNONE;
}

SPELLF spell_fury( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    if ( number_percent() > standard_force_success_rate( ch, skill ) )
    {
        ch_println( ch, "You attempt to draw on your fury, to no avail!" );
        return rNONE;
    }

    AFFECT_DATA af;
    af.type = skill->id;
    af.duration  = 1000;
    af.location  = 0;
    af.modifier  = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_FURY );
    affect_replace( ch, CHAR_AFFECT, &af );
    ch_println( ch, "You bask in the fury within your heart, dark strands of the Force weaving about your body to form an invisible barrier." );
    act( AT_RED, "$n closes $s eyes, a red light glowing behind $s eyelids.", ch, NULL, NULL, TO_ROOM );
    act( AT_RED, "&rObsidian strands of energy weave about $s body, visible for only a second before disappearing.&w", ch, NULL, NULL, TO_ROOM );
    sith_penalty( ch );
    return rNONE;
}

SPELLF spell_fear( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    int chance = ris_save( victim, level, RIS_FEAR );

    if ( chance == 1000 || saves_spell_staff( chance, victim ) )
    {
        act( AT_MAGIC, "$N resists your attempt to shroud $S mind with fear!", ch, NULL, victim, TO_CHAR );
        act( AT_MAGIC, "You resist the growing swell of fear in your mind!", ch, NULL, victim, TO_VICT );
        sith_penalty( ch );
        return rSPELL_FAILED;
    }

    // GRAL for Ralen
    // Max forcer is frc=22 or level 110. This allows for a (1..90+20)+ or 10% chance to fail
    if ( ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  &&
            number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] ) ||
            ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) )
    {
        ch_println( ch, "&zReaching out with the Dark Side, you try to twist %s's mind against them.&w", g_name( victim, ch ) );
        ch_println( ch, "&rCurse them. Your Mind Trick has no effect on %s.&w", g_name( victim, ch ) );
        act( AT_MAGIC, "&wYou sense $n trying to fool you with the Force. Their mind powers won't work.&w", ch, NULL, victim, TO_VICT );
        return rSPELL_FAILED;
    }

    if ( !negative_spell_succeeds( ch, skill, victim ) )
    {
        act( AT_MAGIC, "$N resists your attempt to shroud $S mind with fear!", ch, NULL, victim, TO_CHAR );
        act( AT_MAGIC, "You resist the growing swell of fear in your mind!", ch, NULL, victim, TO_VICT );
        sith_penalty( ch );
        learn_slow( ch, skill, 3 );
        return rSPELL_FAILED;
    }

    act( AT_MAGIC, "&c&w$N breaks into a cold sweat, $S eyes widening.", ch, NULL, victim, TO_NOTVICT );
    act( AT_MAGIC, "$N's eyes widen as fear grips $S mind!", ch, NULL, victim, TO_CHAR );
    act( AT_MAGIC, "Your mind races as fear takes hold!", ch, NULL, victim, TO_VICT );
    worsen_mental_state( victim, number_range( 5, 10 ) );
    sith_penalty( ch );
    learn_slow( ch, skill, 2 );
    return rNONE;
}

