SPELLF spell_hate( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    char arg[MIL];
    char buf[MSL];
    CHAR_DATA* victim = NULL, *target = NULL;
    int resist = 0;
    int chances = 0;

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Whose mind do you wish to fill with hate, and for whom?" );
        return rINVALID_ARGS;
    }

    target_name = one_argument( target_name, arg );

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "You see no %s nearby.", arg );
        return rINVALID_ARGS;
    }

    /* kill room flags when you can */
    if ( xIS_SET( victim->in_room->flags, ROOM_SAFE )
            ||   xIS_SET( victim->act, ACT_SAFE )                )
    {
        ch_println( ch, "You can't do that to them." );
        return TRUE;
    }

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Who do you want %s to attack?", g_name( victim, ch ) );
        return rINVALID_ARGS;
    }

    if ( ( target = get_char_world_full( ch, target_name ) ) == NULL )
    {
        for ( target = first_char ; target ; target = target->next )
        {
            if ( !IS_NPC( target ) )
                continue;

            if ( !target->in_room )
                continue;

            if ( !target->in_room->area )
                continue;

            if ( !target->in_room->area->planet )
                continue;

            if ( target->in_room->area->planet != ch->in_room->area->planet )
                continue;

            /* Found */
            break;
        }
    }

    if ( target == victim )
    {
        ch_println( ch, "&z&Y&zMake them hate themselves? Wow, you ARE evil!" );
        ch_println( ch, "&RFORGET IT!" );
        return rINVALID_ARGS;
    }

    chances = standard_force_success_rate( ch, skill );

    if ( ch->spirit != 0 )
    {
        ch->max_hit = URANGE( 1, ch->max_hit - number_range( 10, 30 ), ch->max_hit );
        ch_println( ch, "Affecting minds with hatred is draining on the ethereal!" );
    }

    // GRAL for Ralen
    // Max forcer is frc=22 or level 110. This allows for a (1..90+20)+ or 10% chance to fail
    if ( ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  &&
            number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] ) ||
            ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) )
    {
        ch_println( ch, "&zReaching out with the Dark Side, you try to twist %s's mind against them.&w", g_name( victim, ch ) );
        ch_println( ch, "&rCurse them. Your Mind Trick has no effect on %s.&w", g_name( victim, ch ) );
        act( AT_MAGIC, "&wYou sense $n trying to fool you with the Force. Their mind powers won't work.&w", ch, NULL, victim, TO_VICT );
        sith_penalty( ch );
        return rNONE;
    }

    if ( !IS_NPC( ch ) && victim->skill_level[FORCE_ABILITY] > 40 )
        snprintf( buf, MSL, "spell_hate: %s casting on %s hate Target: %s Chance: %d.", ch->name, victim->name, target_name, chances );

    bug( buf );
    chances /= 2;

    if ( number_percent () > chances )
    {
        ch_println( ch, "&x&Y&rYou fail to channel your hatred.&w" );
        learn_slow( ch, skill, 3 );
        return rNONE;
    }

    resist = IS_NPC( victim ) ? victim->top_level : ( get_curr_wis( victim ) * 5 + get_curr_int( victim ) * 5 ) / 4;

    if ( number_range( chances / 20, chances ) < number_range( resist / 20, resist / 2 ) )
    {
        act( AT_MAGIC, "You attempt to fill $N's mind with hatred for $t... but fail.", ch, target_name, victim, TO_CHAR );
        act( AT_RED, "You feel hatred in your mind for only a second, before it clears.", ch, NULL, victim, TO_VICT );
        snprintf( buf, MSL, "spell_hate: %s making Vict: %s hate Target: %s Chance: %d / Resist: %d.", ch->name, victim->name, target_name, chances, resist );
        bug( buf );
        sith_penalty( ch );
        learn_slow( ch, skill, 3 );
        return rSPELL_FAILED;
    }

    if ( !IS_NPC( ch ) && ( int ) ch->perm_frc < 18  && !IS_NPC( victim ) ) //Ralen: Why render this level 55 spell utterly moot unless you are level 90?
    {
        ch_println( ch, "You cannot seem to overcome %s's mind!", g_name( victim, ch ) );
        return rSPELL_FAILED;
    }

    if ( !IS_NPC( victim ) )
    {
        if ( get_char_room_exact( victim, target->name ) )
        {
            act( AT_ACTION, "Hatred soaks through your heart, and you lash out at $N!", victim, NULL, target, TO_CHAR );
            act( AT_RED, "$n's eyes flash red as $e looks at you, and $e attacks!", victim, NULL, target, TO_VICT );
            act( AT_ACTION, "$n's eyes flash red as $e looks at $N. $n attacks $N!", victim, NULL, target, TO_NOTVICT );
            multi_hit( victim, target, TYPE_UNDEFINED );
            snprintf( buf, MSL, "spell_hate: %s making Vict: %s hate Target: %s Chance: %d / Resist: %d.", ch->name, victim->name, target_name, chances, resist );
            bug( buf );
            sith_penalty( ch );
            learn_slow( ch, skill, 2 );
            return rNONE;
        }
        else
        {
            ch_println( victim, "&W&zYour thoughts change, centering around a rising hatred for someone named &R%s&z. You will recognize them as &R%s&z.&w", target_name, g_name( target, victim ) );
            act( AT_MAGIC, "&zYou fill $N's mind with thoughts of hatred for &r$t&z.", ch, target_name, victim, TO_CHAR );
            ch_println( victim, "&z&O(&YOOC&O) &wNote&z: &wThis is RP, your character has failed a save vs. force spell.\n&z&Y&WFailure to cooperate may result in punishment from immortals." );
            snprintf( buf, MSL, "spell_hate: %s making Vict: %s hate Target: %s Chance: %d / Resist: %d.", ch->name, victim->name, target_name, chances, resist );
            bug( buf );
            sith_penalty( ch );
            learn_slow( ch, skill, 2 );
            return rNONE;
        }
    }
    else
    {
        if ( number_percent () < number_range( victim->top_level / 5, victim->top_level ) )
            start_hunting( victim, target ); /* Don't always go looking for him */

        start_hating( victim, target ); /* At least they will lie in wait. */
        act( AT_MAGIC, "You fill $N's mind with hatred for $t!", ch, target_name, victim, TO_CHAR );
        act( AT_ACTION, "$n begins to mutter, $s eyes flashing red for a moment.", victim, NULL, NULL, TO_ROOM );
        snprintf( buf, MSL, "spell_hate: %s making Vict: %s hate Target: %s Chance: %d / Resist: %d.", ch->name, victim->name, target_name, chances, resist );
        bug( buf );
        sith_penalty( ch );
        learn_slow( ch, skill, 2 );
        return rNONE;
    }
}

SPELLF spell_conceal_force( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    int chances = 0;
    chances = standard_force_success_rate( ch, skill );

    if ( number_percent() > chances )
    {
        ch_println( ch, "You are unsuccessful in your attempts to cloak yourself within the Force." );
        return rSPELL_FAILED;
    }

    if ( has_pcflag( ch, PCFLAG_NO_SENSE ) )
    {
        ch_println( ch, "Your body is encased in a white light once more as you reveal your presence." );
        remove_pcflag( ch, PCFLAG_NO_SENSE );
    }
    else
    {
        if ( !IS_NPC( ch ) && !IS_IMMORTAL( ch ) && ch->mana < 2000 )
        {
            ch_println( ch, "The Force is not strong enough within you." );
            return rNONE;
        }

        ch_println( ch, "Your body is encased in a white light for a brief moment as you cloak yourself in the Force." );
        ch->mana = 0;
        set_pcflag( ch, PCFLAG_NO_SENSE );
    }

    act( AT_ACTION, "$n raises $s hands and is momentarily encased in white strands of light...", ch, NULL, NULL, TO_ROOM );
    learn_slow( ch, skill, 2 );
    return rNONE;
}
SPELLF spell_daze( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    int rds = 0, chances = 0;

    if ( NULLSTR( target_name ) )
    {
        if ( ( victim = who_fighting( ch ) ) == NULL )
        {
            ch_println( ch, "You aren't fighting anyone." );
            return rNONE;
        }
    }

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL  )
    {
        ch_println( ch, "You don't seen anyone like that nearby" );
        return rNONE;
    }

    if ( victim->skill_level[FORCE_ABILITY] >= 20 )
    {
        ch_println( ch, "%s seems to be immune to being dazed!", g_name( victim, ch ) );
        ch_println( victim, "You feel a momentary wave of pressure, and notice %s peering at you oddly!", g_name( ch, victim ) );
        return rNONE;
    }

    rds = number_range( 1, 3 );
    chances = IS_NPC( ch ) ? ch->top_level : ( get_learned_pct( ch, skill ) + ch->skill_level[FORCE_ABILITY] ) / 2;

    if ( number_percent ( ) > chances || get_curr_int( victim ) > ( chances / 15 ) || ( !IS_NPC( victim ) && victim->skill_level[FORCE_ABILITY] >= level ) )
    {
        ch_println( ch, "You try to daze %s, but it seems to have little effect!", g_name( victim, ch ) );
        ch_println( victim, "You feel pressure inside your head and your limbs feel numb... after a moment it passes." );
