        return rSPELL_FAILED;
    }
    else
    {
        act( AT_MAGIC, "You focus your will, causing a wave of the Force to daze $N $t!", ch, rds > 100 ? "totally" : rds > 50 ? "somewhat" : "mildly", victim, TO_CHAR );
