CMDF do_manifest( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* tch = NULL;
    int chances = 0;

    SKILL_DATA* skill = cache_skill( "manifest", &skill_manifest );

    if ( !ch->spirit )
    {
        ch_println( ch, "&wHuh?" );
        return;
    }

    chances = standard_force_success_rate( ch, skill );

    if ( number_percent() > chances )
    {
        if ( !ch->manifest )
            ch_println( ch, "&RYou try to manifest yourself... but fail!" );
        else
            ch_println( ch, "&RYou try to fade from view, but fail!" );

        learn_slow( ch, skill, 2 );
    }
    else
    {
        do_restore( ch, "self" );

        if ( ch->holding || ch->carrying )
            do_release( ch, "" );

        for ( tch = first_char ; tch ; tch = tch->next )
        {
            if ( tch->holding == ch )
                do_release( tch, "" );

            if ( tch->carrying == ch )
                do_release( tch, "" );
        }

        learn_slow( ch, skill, 1 );
        ch->manifest = !ch->manifest;
        ch_println( ch, "You are now %s.", ch->manifest ? "manifested and visible" : "ethereal" );

        if ( ch->manifest )
            act( AT_ACTION, "$n forms in the air, $s body taking shape.", ch, NULL, NULL, TO_ROOM );
        else
            act( AT_ACTION, "$n fades from sight, vanishing as if never there.", ch, NULL, NULL, TO_ROOM );
    }
}

/*
    Something important... the code invoking this in raw_kill (fight.c) should
    occur when the character has lost all of its equipment, that way it can be
    reversed. Force ghosts shouldn't be able to wear equipment unmanifested.
*/
CHAR_DATA* make_force_ghost ( CHAR_DATA* ch )
{
    int lvl = 0;

    if ( !ch || IS_NPC( ch ) || ( int ) ch->skill_level[FORCE_ABILITY] < 20 || IS_IMMORTAL( ch ) || ( ch->spirit ) )
        return ch;

    if ( sysdata.ghostsenabled == FALSE )
        return ch;

    if (  ch->alignment >= 300 && get_learned_pct( ch, cache_skill( "presence", &skill_presence ) ) <= 50 )
        return ch;

    if ( ch->alignment <= -300 && get_learned_pct( ch, cache_skill( "vengeance", &skill_vengeance ) ) <= 50 )
        return ch;

    ch->spirit = TRUE;
    ch->manifest = FALSE;
    bool align = FALSE;

    if ( IS_GOOD( ch ) )
        align = TRUE;

    lvl = ch->perm_frc;

    if ( lvl >= 100 )
        lvl += number_range( 1, 10 );

    ch_println( ch, "&CYou feel yourself changing...you feel somehow free...&w"
               "&wA shaking tremor rips through the area and lights flare all over.&w\n"
               "&WA cool breeze blows...you feel yourself within the wind, one with it.&w\n"
               "&CYou notice your skin, your clothes, your very essence now glowing.&w\n"
               "&wWhispers of the Force hushedly murmur in your mind, a phrase once remembered.\n"
               "%s", align ? "&CThere is no Death, there is the Force.&w\n" : "&rThe Force shall &RFREE &rme.&w\n" );
    //Ralen - level-based commentary not really relevant, as you need a certain FRC above 50% of these to even know the skills.
    //"&WYou feel %s.&w\n", lvl > 29 ? "infinity take hold of you." :
    //lvl > 24 ? "nearly omnipotent"           :
    //lvl > 19 ? "powerful"                    :
    //lvl > 14 ? "very strong"                 :
    //lvl > 9  ? "strong"                      :
    //lvl > 4  ? "weak"                        :
    //"cursed"                       );
    xSET_BIT( ch->affected_by, AFF_PASS_DOOR );
    ch->skill_level[FORCE_ABILITY] = lvl * 5;
    set_learned_pct( ch, cache_skill( "converge", &skill_converge ), 100 );
    char_from_room( ch );
    char_to_room( ch, get_room_index( 2 ) );
    send_to_char( "In order to return to the galaxy, you will have to manifest.\n"
                  "Until then, you will not be able to do anything.\n", ch );
    return ch;
}

SPELLF spell_dispel_spirit( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( !victim->spirit )
    {
        ch_println( ch, "You can't dispel that!" );
        return rINVALID_ARGS;
    }

    int chances = standard_force_success_rate( ch, skill );

    if ( number_percent() > chances )
    {
        ch_println( ch, "You are unsuccessful in your attempts to banish that Force manifestation." );
        return rNONE;
    }

    act( AT_ACTION, "$n reaches towards $N and $N vanishes with a shattering scream!", ch, NULL, victim, TO_NOTVICT );
    act( AT_ACTION, "$n reaches out towards you, and you feel yourself willed out of the physical world!", ch, NULL, victim, TO_VICT );
    act( AT_ACTION, "You reach out, forcing $N from the physical world with the Force.", ch, NULL, victim, TO_CHAR );
    victim->max_hit = URANGE( 0, victim->max_hit - number_range( 1, 30 ), 32000 );

    if ( victim->max_hit > 0 )
    {
        victim->manifest = FALSE;
        WAIT_STATE( victim, PULSE_VIOLENCE * 2 );
    }
    else
    {
        act( AT_ACTION, "You search the Force for echoes of $N, but hear only silence as $S connection to the galaxy has finally been severed.", ch, NULL, victim, TO_CHAR );
        raw_kill( ch, victim );
    }

    learn_slow( ch, skill, 2 );
    return rNONE;
}

SPELLF spell_converge( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    bool found = FALSE;
    SPACE_DATA* t1 = NULL, *t2 = NULL;
    int chances = 0;

    if ( !ch->spirit )
    {
        ch_println( ch, "How do you expect to do that!?" );
        return rNONE;
    }

    if ( ch->manifest )
    {
        ch_println( ch, "You may only do this while ethereal." );
        return rNONE;
    }

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Who do you wish to converge upon?" );
        return rNONE;
    }

    if ( ( victim = get_char_world( ch, target_name ) ) != NULL )
        found = TRUE;

    if ( found )
        if ( ( t1 = in_starsystem(   ch   ) ) == NULL ||
                ( t2 = in_starsystem( victim ) ) == NULL ||
                t1 != t2 )
            found = FALSE;

    chances = standard_force_success_rate( ch, skill );

    if ( ( !found ) || number_percent() > chances )
    {
        ch_println( ch, "You fail to focus your will enough." );
        return rNONE;
    }

    char_from_room( ch );
    char_to_room( ch, victim->in_room );
    ch_println( ch, "With a rush you find yourself standing near %s.", g_name( victim, ch ) );

    if ( victim->skill_level[FORCE_ABILITY] >= 55 && number_percent( ) > 50 )
        ch_println( victim, "You sense a presence near you." );

    learn_slow( ch, skill, 2 );
    return rNONE;
}

SPELLF spell_farspeak( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    FARSPEAK_LOG* farspeaklog = NULL;
    bool found = TRUE;
    char arg[MIL];
    int chance;

    if ( !target_name )
        return rSPELL_FAILED;

    target_name = one_argument( target_name, arg );

    if ( NULLSTR( arg ) || NULLSTR( target_name ) )
    {
        ch_println( ch, "Who do you want to farspeak to, and what do you want to say?" );
        return rSPELL_FAILED;
    }

    if ( ( victim = get_char_world_full( ch, arg ) ) == NULL )
        found = FALSE;

    if ( victim && victim == ch )
    {
        ch_println( ch, "&wThere are easier ways to talk to yourself..." );
        return rSPELL_FAILED;
    }

    ch_println( ch, "&z&W&CYou are attempting to %ssay '%s%s&C' in %s's mind", tone_convert( ch, NULL ), txtclr( ch ), target_name, arg );

    // Let's log this in a farspeak log
    CREATE( farspeaklog, FARSPEAK_LOG, 1 );
    LINK( farspeaklog, first_farspeak_log, last_farspeak_log, next, prev );
    SET_STRING( farspeaklog->sender, ch->name );
    SET_STRING( farspeaklog->target, arg );
    SET_STRING( farspeaklog->recipient, victim ? victim->name : "" );
    SET_STRING( farspeaklog->message, target_name );

    /*
        Looks nice and it boggles people trying to use this to discover if someone is online
                                                                                Orion
    */
    switch ( number_range( 1, 10 ) )
    {
        case 1:
            ch_println( ch, "You concentrate on your thoughts... and send them out." );
            break;

        case 2:
            ch_println( ch, "You channel your thoughts into a stream, and send it into the galaxy." );
            break;

        case 3:
            ch_println( ch, "Your thoughts form until almost tangible, and you will them to your target." );
            break;

        case 4:
            ch_println( ch, "A wave of your will carries your words on the Force." );
            break;

        case 5:
            ch_println( ch, "Concentrating, you try to echo your words in your target's mind." );
            break;

        case 6:
            ch_println( ch, "Drawing from your connection with the Force, you whisper your words as if your target were near." );
            break;

        case 7:
            if ( ch->skill_level[FORCE_ABILITY] >= 100 )
                ch_println( ch, "You usher your thoughts across the galaxy." );
            else
                /* GRAL typo */
                ch_println( ch, "You focus, and a sudden shift in the Force carries your thoughts." );

            break;

        case 8:
            ch_println( ch, "Whispers, your own thoughts, seem to reverberate in your mind." );
            break;

        case 9:
            ch_println( ch, "Strands of your will carry the words into the galaxy." );
            break;

        case 10:
            if ( ch->alignment > 300 )
                ch_println( ch, "You complacently project your thoughts, seeking your target." );
            else
                ch_println( ch, "You send your words on churning waves of Force towards your target." );

            break;

        default:
            break;
    }

    /* GRAL Check against gsn or force? */
    /* RALEN this has been a pain in the ass for years, changing to a gsn skill check. */
    chance = IS_NPC( ch ) ? ch->top_level : ( int ) ( get_learned_pct( ch, skill ) );
    // GRAL Readded boggler so people can't use farspeak to see if someone is online.
    chance = chance * found;

    if ( number_percent( ) <= chance )
    {
        // GRAL for Ralen
        // Max forcer is frc=22 or level 110. This allows for a (1..90+20)+ or 10% chance to fail
        if ( ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  && number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] ) || ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) )
        {
            act( AT_MAGIC, "&wYou sense $n trying to reach your mind with the Force. Their mind powers won't work.", ch, NULL, victim, TO_VICT );
            farspeaklog->received = FALSE;
            farspeak_log_save( farspeaklog, TRUE );
            return rSPELL_FAILED;
        }
        else
        {
            farspeaklog->received = TRUE;
            farspeak_log_save( farspeaklog, TRUE );
            ch_println( victim, "&z&W&CInside your mind, %s %ssays '%s%s&C'", g_name( ch, victim ), tone_convert( ch, victim ), txtclr( ch ), target_name );
        }
    }
    else
    {
        farspeaklog->received = FALSE;
        farspeak_log_save( farspeaklog, TRUE );
    }

    return rNONE;
}
SPELLF spell_drain_force( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    CHAR_DATA* tch = NULL;

    if ( !ch->spirit )
    {
        ch_println( ch, "You don't have the right sort of power to do this." );
        return rNONE;
    }

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "You see nobody like that nearby." );
        return rNONE;
    }

    ch_println( ch, "You begin to draw Force energy from your victim." );
    act( AT_ACTION, "$n glares at you and you begin to feel your life force being sucked towards $m!", ch, NULL, victim, TO_VICT );
    act( AT_ACTION, "$n glares at $N and $N starts to shake!", ch, NULL, victim, TO_NOTVICT );
    bug ( "%s trying to force_drain %s at %d.", ch->name, victim->name, ch->in_room->vnum );

    if ( number_percent() >= victim->perm_frc * 3 )
    {
        ch_println( ch, "You feel stronger!" );
        ch->max_hit += number_range( 10, 30 );
        victim->perm_frc = URANGE( 0, victim->perm_frc - 1, 30 );
        act( AT_ACTION, "You feel defiled, and weaker!", ch, NULL, victim, TO_VICT );

        for ( tch = first_char ; tch ; tch = tch->next )
        {
            if ( get_trust( tch ) > LEVEL_HERO )
                continue;

            if ( IS_NPC( tch ) )
                continue;

            if ( tch->skill_level[FORCE_ABILITY] < 10 )
                continue;

            ch_println( tch, "The Force cries out as someone is drained of their essence!" );

            if ( in_starsystem( ch ) == in_starsystem( tch ) )
                ch_println( ch, "You sense it is nearby." );
        }

        return rNONE;
    }
    else
    {
        ch_println( ch, "You fail to drain your victim." );
        ch_println( victim, "You feel weakened but intact." );

        for ( tch = first_char ; tch ; tch = tch->next )
        {
            if ( get_trust( tch ) > LEVEL_HERO )
                continue;

            if ( IS_NPC( tch ) )
                continue;

            if ( tch->skill_level[FORCE_ABILITY] < 80 )
                continue;

            ch_println( tch, "The Force shudders as someone resists being drained." );

            if ( in_starsystem( ch ) == in_starsystem( tch ) )
                ch_println( ch, "You sense it is nearby." );
        }

        return rNONE;
    }
}
SPELLF spell_choke ( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( !negative_spell_succeeds( ch, skill, victim ) )
    {
        act( AT_ACTION, "&w$n extends $s hand towards $N, slowly curling it into a fist.&w", ch, NULL, victim, TO_NOTVICT );
        act( AT_MAGIC, "&w$n curls his fingers in your direction, tightening them slowly into a fist.&w", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "You reach out with the Force, but fail to choke $N.", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "You feel intense pressure on your throat for a second, but it passes.", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$N looks like $E is having trouble breathing.", ch, NULL, victim, TO_NOTVICT );
        sith_penalty( ch );
        return rSPELL_FAILED;
    }

    act( AT_ACTION, "&w$n extends $s hand towards $N, slowly curling it into a fist.&w", ch, NULL, victim, TO_NOTVICT );
    act( AT_MAGIC, "&w$n curls his fingers in your direction, tightening them slowly into a fist.&w", ch, NULL, victim, TO_VICT );
    act( AT_ACTION, "You reach out with the Force, choking $N!", ch, NULL, victim, TO_CHAR );
    act( AT_ACTION, "You feel intense pressure on your throat, and your whole body aches!", ch, NULL, victim, TO_VICT );
    act( AT_ACTION, "$N grasps at $S throat, $S face going red as $E chokes.", ch, NULL, victim, TO_NOTVICT );
    sith_penalty( ch );

    if ( damage( ch, victim, number_range( 100, 200 ), skill->id ) == rVICT_DIED )
    {
        ch_println( ch, "You choke the life out of your victim!" );
        return rNONE;
    }

    stop_fighting( victim, TRUE );
    start_hating( victim, ch );
    learn_slow( ch, skill, 3 );

    /* RALEN currently trying here to interrupt their actions. Hard to carry on making containers when being choked to death. */
    // this is the wrong way to do this and can cause a crash
    // under certain circumstances.  need generalized
    // interrupt mechanism ~Miros
    //The wise prophet Miros hath spoketh. The previous way did indeed crash us. Interpret should work better.
    if ( victim->first_buffer )
    {
        do_stop( victim, "" );
        if ( victim->editor )
            stop_editing( victim, false );
        clear_buffers( victim );
        ch_println( victim, "&YYou are interrupted, paralyzed by the pain!" );
    }
    else
    {
        ch_println( victim, "You are paralyzed by the pain!" );
    }

    WAIT_STATE( victim, 15 );
    return rNONE;
}
/* Witch spells - Farsight type spell */
SPELLF spell_vision( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    int chances = 0;
    int oldtrust = ch->trust;
    ch->trust = 103;

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "You need to supply a target to try to conjure in a vision." );
        ch->trust = oldtrust;
        return rNONE;
    }

    chances = standard_force_success_rate( ch, skill );

    if ( ( victim = get_char_world( ch, target_name ) ) == NULL || !xIS_SET( ch->race->flags, RFLAG_NATURALFORCE ) ) //|| in_starsystem( victim ) != in_starsystem( ch ) )
        chances = 0;

    if ( chances > 0 && number_percent() <= chances )
    {
        ROOM_INDEX_DATA* room = NULL;
        act( AT_ACTION, "$n conjures up a vision of $N in the air.", ch, NULL, victim, TO_ROOM );
        room = ch->in_room;
        char_from_room( ch );
        char_to_room( ch, victim->in_room );
        do_look( ch, "" );
        char_from_room( ch );
        char_to_room( ch, room );
        ch_println( ch, "\n&z&Y&WYou see your target in your mind as you conjure up a vision in the air." );
        /* Handy little trick, makes it slower the higher you gain :)   Orion */
        learn_slow( ch, skill, chances / 20 );
        ch->trust = oldtrust;
        return rNONE;
    }
    else
    {
        learn_slow( ch, skill, 4 );
        ch->trust = oldtrust;
        return rSPELL_FAILED;
    }

    ch->trust = oldtrust;
}

SPELLF spell_force_storm( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    int dam;
    act( AT_WHITE, "You channel the raw power of the Force, stretching out your hands to inflict a storm of lightning on your surroundings!", ch, NULL, NULL, TO_CHAR );
    act( AT_WHITE, "$n raises $s arms toward the sky as a massive storm of white lightning emanates from $s palms!", ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( vch == ch || is_same_group( ch, vch ) || has_pcflag( vch, PCFLAG_AFK ) || is_safe( ch, vch ) )
            continue;

        dam = ( int )( ch->skill_level[FORCE_ABILITY] * 4 );
        damage( ch, vch, dam, skill->id );
    }

    return rNONE;
}

SPELLF spell_death_field( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    int dam = 0;
    int chances = 0;
    chances = IS_NPC( ch ) ? ch->top_level : ( get_learned_pct( ch, skill ) + ch->skill_level[FORCE_ABILITY] ) / 2;

    if ( number_percent() > chances )
    {
        ch_println( ch, "You fail to channel your anger into creating a death field!" );
        learn_slow( ch, skill, 3 );
        return rNONE;
    }

    act( AT_BLOOD, "You harness your anger and the area is encircled with crimson bolts emanating from you!", ch, NULL, NULL, TO_CHAR );
    act( AT_BLOOD, "The room is suddenly encircled with crimson bolts emanating from $n.\n", ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( vch == ch || is_same_group( ch, vch ) || has_pcflag( vch, PCFLAG_AFK ) || is_safe( ch, vch ) )
            continue;

        if ( xIS_SET( vch->act, ACT_DROID ) || ( xIS_SET( vch->race->flags, RFLAG_DROID ) ) )
        {
            act( AT_DAMAGE, "One of the bolts arcs towards you and plunges into your chest.", ch, NULL, vch, TO_VICT );
            act( AT_ACTION, "It seems to have no effect on your machinery.", ch, NULL, vch, TO_VICT );
            act( AT_ACTION, "One of the bolts plunges into $N, but has no effect on $S machinery.", ch, NULL, vch, TO_CHAR );
            continue;
        }

        act( AT_DAMAGE, "One of the bolts arcs towards you and plunges into your chest.", ch, NULL, vch, TO_VICT );
        act( AT_BLOOD, "As the bolt courses through you, you feel your health being drained away.", ch, NULL, vch, TO_VICT );
        act( AT_BLOOD, "One of the bolts plunges into $N then returns to you, bringing some of $S health.", ch, NULL, vch, TO_CHAR );
        dam = ( int )( ch->skill_level[FORCE_ABILITY] * 5.25 );
        // Reduce damage for forcer targets.
        // This math means a level 100 would take 2/3 of the original damage, scaling linearly.
        dam -= dam * vch->skill_level[FORCE_ABILITY] / 300;
        damage( ch, vch, dam, skill->id );
        ch->hit = UMIN( ch->max_hit, ch->hit + dam / 5 );

        if ( !IS_NPC( ch ) && number_percent() >= get_learned_pct( ch, skill ) + 4 )
            learn_slow( ch, skill, 4 );
    }

    sith_penalty( ch );
    return rNONE;
}

SPELLF spell_force_crush( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( victim == ch )
    {
        act( AT_ACTION, "You can't use that ability on yourself.", ch, NULL, NULL, TO_CHAR );
