    {
        act( AT_DGREY, "The Force seems almost nonexistent around $N, and your efforts prove fruitless.", ch, NULL, victim, TO_CHAR );
        return rSPELL_FAILED;
    }

    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
