SPELLF spell_resurrect( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    int cnt = 0;
    char buf[MSL];

    if ( NULLSTR( target_name ) )
    {
        ch_println( ch, "Target not specified." );
        return rNONE;
    }

    victim = get_char_room( ch, target_name );

    if ( !victim )
    {
        ch_println( ch, "Target not found." );
        return rNONE;
    }

    if ( IS_NPC( victim ) )
    {
        ch_println( ch, "Are you mad?!" );
        return rNONE;
    }

    if ( !victim->spirit )
    {
        ch_println( ch, "They'd have to die first..." );
        return rNONE;
    }

    cnt = ( int ) ( 5 * victim->perm_frc );
    cnt -= ( int ) ( 2 * ( cnt / 10 ) );
    cnt /= 5;
    victim->perm_frc = cnt;
    victim->max_mana = get_max_mana( victim );
    victim->mana = UMIN( victim->mana, victim->max_mana );
    victim->spirit = FALSE;
    victim->skill_level[FORCE_ABILITY] = 5 * victim->perm_frc;
    victim->experience[FORCE_ABILITY] = exp_level( 5 * victim->perm_frc );
    xREMOVE_BIT( victim->affected_by, AFF_PASS_DOOR );
    act( AT_ACTION, "The air wavers around $n for a second...", victim, NULL, NULL, TO_ROOM );
    act( AT_MAGIC, "$n's form appears, taking solid shape.", victim, NULL, NULL, TO_ROOM );
    send_to_char( "&WThe air wavers around you...\n&BA strange feeling washes over you.\n"
                  "You hear a loud *SNAP*, and your vision blacks out.\n"
                  "You feel your awareness wandering... then centering.\n"
                  "Suddenly your vision returns, and you feel a soft wind blow over your cheek.\n"
                  "&RYou are alive.\n", victim );
    do_save( victim, "-noalert" );
    snprintf( buf, MSL, "%s was resurrected at %d.", victim->name, victim->in_room->vnum );
    log_string( buf );
    sith_penalty( ch );
    return rNONE;
}

CMDF do_apprenticestat( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim = NULL;
    int cnt = 0, cn = 0;
    SKILL_DATA* skill = NULL;

    /*  6-23-2014
        Changed to not take a parameter as you can only have
        one apprentice at a time anyway.  Still requires that
        your apprentice be in the room.
        ~Miros
    */
    victim = fetch_apprentice( ch, TRUE );

    if ( !victim || victim == ch )
    {
        ch_println( ch, "Your apprentice is not here." );
        return;
    }

    for ( skill = first_skill; skill; skill = skill->next )
    {
        if ( skill->guild == FORCE_ABILITY && get_learned_pct( victim, skill ) > 0 )
            cnt++;

        if ( skill->guild == FORCE_ABILITY && victim->skill_level[FORCE_ABILITY] >= skill->min_level )
            cn++;
    }

    ch_println( ch, "&g-&GApprentice stats&g-"
               "&zName: &G%-20s &zRace: &G%s\n"
               "&zForce level: &G%d &zForce Rank: &G%s\n"
               "&zAbilities known: &W%d/%d\n"
               "&zExp to level: &G%ld&z\n",
               g_name( victim, ch ), get_race( victim ),
               victim->skill_level[FORCE_ABILITY],
               get_auto_frank( victim, victim->pcdata->frank ),
               cnt, cn,
               exp_level( victim->skill_level[FORCE_ABILITY] + 1 ) - victim->experience[FORCE_ABILITY] );
}

SPELLF spell_force_speed( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    AFFECT_DATA af;
    int chc = 0, dur = 0;
    chc = standard_force_success_rate( ch, skill );

    if ( IS_AFFECTED( ch, AFF_SPEED ) )
    {
        ch_println( ch, "You're already moving quickly." );
        return rINVALID_ARGS;
    }

    if ( number_percent() > chc )
    {
        ch_println( ch, "You fail to speed yourself up using the Force." );
        return rSPELL_FAILED;
    }

    if ( IS_AFFECTED( ch, AFF_LETHARGY ) )
    {
        affect_strip( ch, CHAR_AFFECT, cache_skill( "lethargy", &skill_lethargy ) );
        act( AT_MAGIC, "You cast off the lethargy holding you back, but are moving no faster than usual.", ch, NULL, NULL, TO_CHAR );
        return rNONE;
    }

    dur = number_range( 2, 5 );
    af.type = skill->id;
    af.duration = dur;
    af.modifier = 0;
    af.location = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_SPEED );
    affect_join( ch, CHAR_AFFECT, &af );
    set_char_color( AT_MAGIC, ch );
    ch_println( ch, "You begin moving faster!" );
    act( AT_MAGIC, "$n begins moving faster!", ch, NULL, NULL, TO_ROOM );
    return rNONE;
}

SPELLF spell_affliction( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    AFFECT_DATA af;
    if ( !skill ) return rERROR;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    int chance = ris_save( victim, level, RIS_POISON );

    if ( chance == 1000 || saves_poison_death( chance, victim ) || !negative_spell_succeeds( ch, skill, victim ) )
    {
        act( AT_ACTION, "You try to afflict $N, but fail!", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "$n closes $s eyes, but nothing happens.", ch, NULL, NULL, TO_ROOM );
        sith_penalty( ch );
        return rSPELL_FAILED;
    }

    act( AT_MAGIC, "You reach out, striking $N with an affliction!", ch, NULL, victim, TO_CHAR );
    act( AT_MAGIC, "$n motions towards $N, and $S skin takes on a pallid tone.", ch, NULL, victim, TO_NOTVICT );
    act( AT_POISON, "$n motions towards you, and you feel very sick.", ch, NULL, victim, TO_VICT );
    af.type      = skill->id;
    af.duration  = level / 2;
    af.location  = APPLY_STR;
    af.modifier  = -2;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_POISON );
    affect_join( victim, CHAR_AFFECT, &af );
    // Elsewhere, poison gives a one-time boost to mental state level, setting to a minimum of 20.
    // Here, we'll tone that down to 12.
    victim->mental_state = URANGE( 12, victim->mental_state + number_range( 2, 5 ), 100 );
    sith_penalty( ch );
    return rNONE;
}

SPELLF spell_lethargy( SKILL_DATA* skill, int level, CHAR_DATA* ch )
