SPELLF spell_drain( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;
    AFFECT_DATA af;
    if ( !skill ) return rERROR;


    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    if ( victim == ch )
    {
        ch_println( ch, "Drain yourself? Not much sense in doing that, is there." );
        return rINVALID_ARGS;
    }

    if ( IS_AFFECTED( victim, AFF_DRAIN ) )
    {
        act( AT_BLOOD, "You must wait before you can drain the life from $N again.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( !IS_AWAKE( victim ) )
    {
        ch_println( ch, "Try that on someone conscious." );
        return rINVALID_ARGS;
    }

    if ( xIS_SET( victim->act, ACT_DROID ) || ( xIS_SET( victim->race->flags, RFLAG_DROID ) ) )
    {
        act( AT_ACTION, "This Force ability does not work on droids.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( !negative_spell_succeeds( ch, skill, victim ) )
    {
        act( AT_ACTION, "You reach out towards $N, but nothing happens!", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "$N reaches out towards you, but nothing happens!", victim, NULL, ch, TO_CHAR );
        act( AT_ACTION, "$n reaches out towards $N, but nothing seems to happen.", ch, NULL, victim, TO_NOTVICT );
        sith_penalty( ch );
        return rSPELL_FAILED;
    }

    int dmg = UMIN( victim->max_hit / 8, 2000 );
    victim->hit = URANGE( -20, victim->hit - dmg, victim->max_hit );
    dmg -= dmg / 3;
    ch->hit = URANGE( ch->hit, ch->hit + dmg, ch->max_hit );
    af.type = skill->id;
    af.duration = number_range( 2, 5 );
    af.modifier = -( number_range( 50, 150 ) );
    af.location = APPLY_HIT;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_DRAIN );
    affect_join( victim, CHAR_AFFECT, &af );
    act( AT_MAGIC, "&RClosing your eyes, you steal some of $N's essence!&w", ch, NULL, victim, TO_CHAR );
    act( AT_MAGIC, "$n closes $s eyes, and $N recoils backwards in pain.&w", ch, NULL, victim, TO_NOTVICT );
    act( AT_MAGIC, "&R$n closes $s eyes, and you feel pain wrack your body!&w", ch, NULL, victim, TO_VICT );
    sith_penalty( ch );
    return rNONE;
}

