SPELLF spell_force_wave( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    int chc;
    act( AT_MAGIC, "With a quick motion, you create a wave of kinetic energy to blast your surroundings.", ch, NULL, NULL, TO_CHAR );
    act( AT_MAGIC, "$n motions toward the ground as a wave of kinetic energy emanates from $m.", ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( vch == ch )
            continue;

        if ( is_same_group( ch, vch ) || has_pcflag( vch, PCFLAG_AFK ) || is_safe( ch, vch ) )
            continue;

        chc = standard_force_success_rate( ch, skill );

        if ( number_range( 2, 175 ) < vch->skill_level[FORCE_ABILITY] )
            chc = 0;

        if ( number_percent() > chc && vch->skill_level[FORCE_ABILITY] >= 2 )
        {
            act( AT_ACTION, "$n holds steady as the wave passes through $m harmlessly.", vch, NULL, NULL, TO_ROOM );
            act( AT_ACTION, "You steady yourself using the Force as the wave passes through you harmlessly.", ch, NULL, vch, TO_VICT );
            continue;
        }

        act( AT_ACTION, "$n is knocked off balance and thrown a short distance across the room.", vch, NULL, NULL, TO_ROOM );
        act( AT_ACTION, "You lose your footing and find yourself skidding across the ground!", ch, NULL, vch, TO_VICT );

        /* RALEN currently trying here to interrupt their actions. */
        if ( vch->first_buffer )
        {
            do_stop( vch, "" );
            if ( vch->editor )
                stop_editing( vch, false );
            clear_buffers( vch );
            vch->substate = SUB_NONE;
            act( AT_RED, "You are interrupted, and stop what you are doing.", ch, NULL, vch, TO_VICT );
        }

        release_char( vch->holding, vch, FALSE );
        release_char( vch->carrying, vch, FALSE );
        release_char( vch, NULL, FALSE );
        lose_approach( vch );

        // Don't make most mobs stop blocking, to prevent messing with progged mobs
        if ( vch->block && !( IS_NPC( vch ) && ( vch->pIndexData->vnum != 97 ) && ( vch->pIndexData->vnum != 250 ) ) )
        {
            act( AT_ACTION, "$n is no longer blocking a direction.", vch, NULL, NULL, TO_ROOM );
            ch_println( vch, "You are no longer blocking a direction." );
            vch->block = NULL;
        }

        // Stun target slightly longer than casting time so they can't immediately re-block the exit
        if ( skill != NULL && number_percent() > 20 )
            WAIT_STATE( vch, UMAX( 5, skill->beats + 3 ) );
        else
            act( AT_ACTION, "You regain your footing quickly.", ch, NULL, vch, TO_VICT );
    }

    return rNONE;
}

SPELLF spell_repulse( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    EXIT_DATA* out_exit;
    int chc;
    int attempt;
    act( AT_MAGIC, "You collect energy within yourself for a moment, then expel it outward as a powerful shockwave!", ch, NULL, NULL, TO_CHAR );
    act( AT_MAGIC, "$n throws $s hands outward as $e summons a powerful shockwave which envelops the area!", ch, NULL, NULL, TO_ROOM );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( vch == ch )
            continue;

        if ( is_same_group( ch, vch ) || has_pcflag( vch, PCFLAG_AFK ) || is_safe( ch, vch ) )
            continue;

        chc = standard_force_success_rate( ch, skill );

        if ( number_range( 2, 175 ) < vch->skill_level[FORCE_ABILITY] )
            chc = 0;

        if ( number_percent() > chc )
        {
            act( AT_ACTION, "$n holds steady as the shockwave passes through $m harmlessly.", vch, NULL, NULL, TO_ROOM );
            act( AT_ACTION, "You anchor yourself with the Force and manage to resist the burst of energy.", ch, NULL, vch, TO_VICT );
            continue;
        }

        if ( vch->position <= POS_SLEEPING )
        {
            act( AT_ACTION, "$n remains motionless on the ground, safely beneath the shockwave's reach.", vch, NULL, NULL, TO_ROOM );
            continue;
        }

        // Figure out where we're sending them.
        out_exit = NULL;

        if ( vch->block != NULL )
            out_exit = vch->block; // Always send someone out the way they were blocking
        else
        {
            // Similar to flee, find a random exit and give up if we never find one that matches the room's exits.
            // This means it's less likely to find one in a room with fewer exits, which makes sense ICly.
            for ( attempt = 0; attempt < 8; attempt++ )
                if ( ( out_exit = get_exit( ch->in_room, number_door() ) ) != NULL )
                    break;
        }

        if ( vch->editor )
            stop_editing( vch, false );

        do_stop( vch, "" );
        release_char( vch->holding, vch, FALSE );
        release_char( vch->carrying, vch, FALSE );
        release_char( vch, NULL, FALSE );
        lose_approach( vch );

        if ( vch->block )
        {
            act( AT_ACTION, "$n is no longer blocking a direction.", vch, NULL, NULL, TO_ROOM );
            set_char_color( AT_ACTION, vch );
            ch_println( vch, "You are no longer blocking a direction." );
            action_clear_ex( vch, AS_UNLOCK );
            vch->block = NULL;
        }

        int base_damage = 100;
        bool move_to_room = false;

        // If it's a mob we don't want to move around, or no exit was found, just damage them in-place.
        if ( out_exit == NULL
                || room_is_private( vch, out_exit->to_room )
                || ( IS_NPC( vch ) && ( vch->pIndexData->vnum != 97 ) && ( vch->pIndexData->vnum != 250 ) ) )
        {
            act( AT_ACTION, "$n is thrown into the air, then violently crashes to the ground.", vch, NULL, NULL, TO_ROOM );
            act( AT_ACTION, "You find yourself in mid-air momentarily, then crash to the ground.", ch, NULL, vch, TO_VICT );
        }
        else if ( xIS_SET( out_exit->flags, EX_WINDOW ) )
        {
            if ( !xIS_SET( out_exit->flags, EX_CLOSED ) && !xIS_SET( out_exit->flags, EX_SEALED_WINDOW ) )
            {
                act( AT_ACTION, "$n is thrown into the air and smashes into the $t window, hitting the frame before flying through!", vch, dir_name[out_exit->vdir], NULL, TO_ROOM );
                act( AT_ACTION, "You are knocked into the air briefly, then smash into the $t window frame before flying through!", vch, dir_name[out_exit->vdir], NULL, TO_CHAR );
                move_to_room = true;
                base_damage = 150; // Damage for hitting an open window
            }
            else
            {
                act( AT_ACTION, "$n is thrown into the air and smashes into the $t window!", vch, dir_name[out_exit->vdir], NULL, TO_ROOM );
                act( AT_ACTION, "You are knocked into the air briefly, then smash into the $t window!", vch, dir_name[out_exit->vdir], NULL, TO_CHAR );
                base_damage = 200; // Damage for hitting a closed window
            }
        }
        else if ( xIS_SET( out_exit->flags, EX_CLOSED ) )
        {
            if ( number_percent() < 50 && !xIS_SET( out_exit->flags, EX_BASHPROOF ) )
            {
                bash_door( out_exit, vch );
                act( AT_ACTION, "$n is thrown into the $t door, which bursts open as they fly through!", vch, dir_name[out_exit->vdir], NULL, TO_ROOM );
                act( AT_ACTION, "You are knocked into the air briefly, then smash through the $t door!", vch, dir_name[out_exit->vdir], NULL, TO_CHAR );
                move_to_room = true;
                base_damage = 150; // A little more damage for hitting the door and going through it
            }
            else
            {
                act( AT_ACTION, "$n is thrown into the $t door, which remains closed!", vch, dir_name[out_exit->vdir], NULL, TO_ROOM );
                act( AT_ACTION, "You are knocked into the air briefly, then smash into the $t door!", vch, dir_name[out_exit->vdir], NULL, TO_CHAR );
                base_damage = 200; // More damage for hitting a closed door
            }
        }
        else
        {
            act( AT_ACTION, "$n is thrown into the air and out to the $t!", vch, dir_name[out_exit->vdir], NULL, TO_ROOM );
            act( AT_ACTION, "You find yourself hurtling through the air toward the $t!", vch, dir_name[out_exit->vdir], NULL, TO_CHAR );
            move_to_room = true;
        }

        if ( out_exit && move_to_room )
        {
            stop_fighting( vch, TRUE );
            char_from_room( vch );
            char_to_room( vch, out_exit->to_room );
            act( AT_ACTION, "$n is thrown through the air from the $t and crashes violently to the ground!", vch, dir_name[rev_dir[out_exit->vdir]], NULL, TO_ROOM );
            act( AT_ACTION, "You crash violently to the ground.", vch, NULL, NULL, TO_CHAR );
        }

        // At force level 100, default 100-300 damage.
        damage( ch, vch, base_damage + number_range( 0, ch->skill_level[FORCE_ABILITY] * 2 ), skill->id );
        // Stun target slightly longer than casting time so they can't immediately re-block the exit

        if ( skill != NULL && number_percent() > 20 )
            WAIT_STATE( vch, UMAX( 5, skill->beats + 3 ) );
        else
            act( AT_ACTION, "You regain your footing quickly.", ch, NULL, vch, TO_VICT );
    }

    return rNONE;
}

