                // GRAL for Ralen
                // Max forcer is frc=22 or level 110. This allows for a (1..90+20)+ or 10% chance to fail
                if ( ( xIS_SET( victim->race->flags, RFLAG_FORCERESISTANCE )  &&
                        number_percent() + 20 >= ch->skill_level[FORCE_ABILITY] ) ||
                        ( xIS_SET( victim->race->flags, RFLAG_FORCEIMMUNE ) ) )
                {
                    act( AT_MAGIC, "Your Mind Trick has no effect on $N.", ch, NULL, victim, TO_CHAR );
                    act( AT_MAGIC, "&wYou sense $n trying to reach your mind with the Force. Their mind powers won't work.", ch, NULL, victim, TO_VICT );
                }
                else
                {
                    set_char_color( AT_GREEN, victim );
                    act( AT_GREEN, "You fill $N's mind with calm.", ch, NULL, victim, TO_CHAR );
                    act( AT_GREEN, "$n fills your mind with calm.", ch, NULL, victim, TO_VICT );

                    // Mobs can't be put in a calm state. Too hard to think through how it could be abused.
                    if ( !IS_NPC( victim ) )
                    {
                        af.type = skill->id;
                        af.duration  = number_range( 2, 4 );
                        af.location  = APPLY_NONE;
                        af.modifier  = 0;
                        xCLEAR_BITS( af.bitvector );
                        xSET_BIT( af.bitvector, AFF_CALM );
                        affect_replace( victim, CHAR_AFFECT, &af );
                    }

                    stop_fighting( victim, TRUE );
                }
            }
        }
        else if ( victim != ch )
        {
            ch_println( victim, "A wave of calm radiates from %s.", g_name( ch, victim ) );
            do_stop( victim, "" );
        }
    }

    return rNONE;
}

SPELLF spell_force_jump( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    AFFECT_DATA af;
    int chc = 0, dur = 0;

    if ( IS_AFFECTED( ch, AFF_FLYING ) )
    {
        ch_println( ch, "You are already airborne..." );
        return rINVALID_ARGS;
    }

    chc = standard_force_success_rate( ch, skill );

    if ( number_percent() > chc )
    {
        set_char_color( AT_ACTION, ch );
        ch_println( ch, "You try to levitate, but fail." );
        return rSPELL_FAILED;
    }

    dur = ( int ) ch->skill_level[skill->guild];
    dur /= 5;
    af.type = skill->id;
    af.duration = number_range( 1, 2 );
    af.modifier = 0;
    af.location = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_FLYING );
    affect_join( ch, CHAR_AFFECT, &af );
    act( AT_MAGIC, "You leap into the air, lifted by the Force!", ch, NULL, NULL, TO_CHAR );
    act( AT_MAGIC, "$n leaps into the air, floating uncannily!", ch, NULL, NULL, TO_ROOM );
    return rNONE;
}

SPELLF spell_obscure( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* room = NULL;
    AFFECT_DATA af;
    if ( !skill || !ch || !ch->in_room )
        return rERROR;

    room = ch->in_room;

    if ( xIS_SET( room->flags, ROOM_CANTOBSCURE ) )
    {
        ch_println( ch, "Something is preventing you from gathering the will to cloud this area." );
        return rSPELL_FAILED;
    }

    if ( number_percent() > standard_force_success_rate( ch, skill ) )
    {
        act( AT_MAGIC, "You try to summon enough ill will to cloud this area in the Dark Side, but you cannot help but think of your mother.", ch, NULL, NULL, TO_CHAR );
        return rSPELL_FAILED;
    }


    af.type      = skill->id;
    af.location  = APPLY_AFFECT;
    af.modifier  = 0;

    af.duration  = 3500; // 3500 rounds (8-ish hours) is where we're capping obscure for now.
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_OBSCURE );

    affect_join( room, ROOM_AFFECT, &af );
    act( AT_BLOOD, "$n focuses $s hatred and covers the area in a dark presence.", ch, NULL, NULL, TO_ROOM );
    act( AT_BLOOD, "Your focus your hatred and cover the area in a dark presence.", ch, NULL, NULL, TO_CHAR );
    save_room( room, true );
    sith_penalty( ch );
    return rNONE;
}

SPELLF spell_mindtalk( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    DB_DATA* mtalk = NULL;
    int chc = 0;
    mtalk = get_mindtalk( ch, true );

    if ( mtalk )
    {
        ch_println( ch, "You are already in a conversation with someone mentally.\nTry MINDTALK END to stop that session." );
        return rINVALID_ARGS;
    }

    // If they already had a pending mindtalk, cancel it silently
    mtalk = get_mindtalk( ch, false );

    if ( mtalk )
    {
        UNLINK( mtalk, first_mtalk, last_mtalk, next, prev );
        mtalk = NULL;
    }

    chc = standard_force_success_rate( ch, skill );

    if ( number_percent() > chc || xIS_SET( ch->in_room->flags, ROOM_NO_MAGIC ) )
    {
        ch_println( ch, "You fail to focus your will." );
        return rSPELL_FAILED;
    }

    victim = get_char_world_full( ch, target_name );

    if ( victim == ch )
    {
        ch_println( ch, "You have a blast focusing your thoughts on yourself!" );
        return rINVALID_ARGS;
    }

    ch_println( ch, "&BYou attempt to establish mental contact." );

    // Fail silently if the target is not eligible.
    if ( victim == NULL
            || IS_NPC( victim )
            || get_mindtalk( victim, false ) != NULL // Fail if pending mindtalk
            || get_mindtalk( victim, true ) != NULL // Fail if established mindtalk
            || victim->skill_level[FORCE_ABILITY] < 2 // Fail if not awakened
            || has_pcflag( victim, PCFLAG_NO_SENSE ) // Fail if target is concealed
            || xIS_SET( victim->in_room->flags, ROOM_NO_MAGIC ) // Fail if target is in nomagic room
       )
    {
        return rNONE;
    }

    ch_println( victim, "&BYou feel %s attempt to make mental contact with you."
               "Use &kmindtalk accept&k or &kmindtalk deny&k. If you accept, %s will be notified.",
               g_name( ch, victim ), g_name( ch, victim ) );
    CREATE( mtalk, DB_DATA, 1 );
    SET_STRING( mtalk->name, ch->name );
    SET_STRING( mtalk->str1, victim ? victim->name : target_name );
    LINK( mtalk, first_mtalk, last_mtalk, next, prev );
    save_dbase_sql( DB_TABLE_MTALK, mtalk);
    return rNONE;
}

SPELLF spell_reveal( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* vch, *vch_next;
    ROOM_INDEX_DATA* room;
    room = ch->in_room;

    if ( number_percent() > standard_force_success_rate( ch, skill ) )
    {
        act( AT_MAGIC, "You focus your attention, but the Dark Side is too strong.", ch, NULL, NULL, TO_CHAR );
        return rSPELL_FAILED;
    }

    act( AT_ACTION, "&C&w$n raises $s hands and pushes them outwards, causing a ripple in the air around $m.&w", ch, NULL, NULL, TO_ROOM );

    if ( !xIS_SET( room->affected_by, AFF_OBSCURE ) )
    {
        ch_println( ch, "There is no presence muddling this area." );
    }
    else
    {
        ch_println( ch, "&GYou focus the Force around you and project, driving the Dark Side from the area.&w" );

        for ( vch = ch->in_room->first_person; vch; vch = vch_next )
        {
            vch_next = vch->next_in_room;

            if ( vch == ch )
                continue;

            if ( vch->skill_level[FORCE_ABILITY] >= 90 && IS_GOOD( vch ) ) //Awakened, Master, Light
            {
                ch_println( vch, "&c&GThe pervading gloom of the Dark Side recoils and vanishes.&w" );
            }
            else if ( vch->skill_level[FORCE_ABILITY] >= 90 && IS_EVIL( vch ) ) //Awakened, Master, Dark
            {
                ch_println( vch, "&c&r%s's meddling purges the embracing miasma of the Dark Side from the area.&w", g_name( ch, vch ) );
            }
            else if ( vch->skill_level[FORCE_ABILITY] > 1 && vch->skill_level[FORCE_ABILITY] <= 60 && IS_GOOD( vch ) ) //Padawans witness the physical but may not understand.
            {
                ch_println( vch, "&c&GYou feel a sudden change in the area as the Force coalesces around %s.", g_name( ch, vch ) );
            }
            else if ( vch->skill_level[FORCE_ABILITY] > 1 && vch->skill_level[FORCE_ABILITY] <= 60 && IS_EVIL( vch ) ) //Padawans witness the physical but may not understand.
            {
                ch_println( vch, "&c&rYou feel as if %s has stripped away a comfort as something dissipates.&w", g_name( ch, vch ) );
            }
            else
            {
                ch_println( vch, "&c&GA pervading gloominess at the edge of your vision dissipates as the air ripples around %s.", g_name( ch, vch ) );
            }
        }

        affect_strip( room, ROOM_AFFECT, cache_skill( "obscure", &skill_obscure ) );
        save_room( room, true );
    }

    jedi_bonus( ch );
    return rNONE;
}

/* START OF CUSTOM SPELLS FOR DATHOMIRI */

SPELLF spell_storm( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    int dam = 0, attacks = 0;
    bool stop = FALSE;
    OBJ_DATA* obj = NULL;
    char cbuf[MSL], nvbuf[MSL], vbuf[MSL];

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( NULLSTR( target_name ) )
    {
        if ( ( victim = who_fighting( ch ) ) == NULL )
        {
            send_to_char( "Usage: cast 'storm' <victim>\n"
                          "Note:  If you are in combat, you don't have to worry about the victim, it will\ndefault to your enemy.\n", ch );
            return rNONE;
        }
    }

    if ( !victim )
    {
        if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
        {
            ch_println( ch, "You don't see anyone like that nearby." );
            return rNONE;
        }
    }

    obj = get_eq_char( victim, WEAR_WIELD );

    if ( obj )
        if ( obj->value[3] != WEAPON_LIGHTSABER )
            obj = NULL;

    attacks = ( ch->skill_level[FORCE_ABILITY] / 20 )  + number_range( 0, 2 );

    if ( attacks == 0 )
        attacks++;

    while ( attacks > 0 && !char_extracted( victim ) && ( !stop ) )
    {
        attacks--;
        int parryperc = ( IS_NPC( victim ) || has_pcflag( victim, PCFLAG_NO_SENSE ) ) ? 0 : get_learned_pct( victim, cache_skill( "parry", &skill_parry ) );

        if ( obj && !IS_NPC( victim ) && number_range( 1, 120 ) < parryperc )
        {
            ch_println( victim, "You raise your lightsaber, and the blade absorbs the tempest." );
            snprintf( nvbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, but is absorbed by $N's lightsaber!" );
            snprintf( cbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from your palm, but is absorbed by $N's lightsaber!" );
            act( AT_WHITE, nvbuf, ch, NULL, victim, TO_NOTVICT );
            act( AT_PLAIN, cbuf, ch, NULL, victim, TO_CHAR );
            learn_from_success( victim, cache_skill( "parry", &skill_parry ) );
            continue;
        }

        if ( is_immune( victim, RIS_ENERGY ) || ( xIS_SET( victim->immune, RIS_MAGIC ) )
                || ( victim->skill_level[FORCE_ABILITY] > 1 && number_range( 1, 150 ) >  victim->skill_level[FORCE_ABILITY] ) )
        {
            snprintf( nvbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, but do nothing to $N!" );
            snprintf( vbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, but do nothing to you!" );
            snprintf( cbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from your palm, but do nothing to $N!" );
            act( AT_PLAIN, cbuf, ch, NULL, victim, TO_CHAR );
            act( AT_PLAIN, vbuf, ch, NULL, victim, TO_VICT );
            act( AT_PLAIN, nvbuf, ch, NULL, victim, TO_NOTVICT );
            continue;
        }

        if ( number_percent() < ( get_curr_dex( victim ) * 2 ) )
        {
            snprintf( nvbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, narrowly missing $N!" );
            snprintf( vbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, narrowly missing you!" );
            snprintf( cbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from your palm, narrowly missing $N!" );
            act( AT_PLAIN, cbuf, ch, NULL, victim, TO_CHAR );
            act( AT_PLAIN, vbuf, ch, NULL, victim, TO_VICT );
            act( AT_PLAIN, nvbuf, ch, NULL, victim, TO_NOTVICT );
            continue;
        }

        snprintf( nvbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, thrashing $N!" );
        snprintf( vbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from $n's palm, thrashing you!" );
        snprintf( cbuf, MSL, "&YG&Oolden &YL&Oightning and intense bursts of wind emanate from your palm, thrashing $N!" );
        act( AT_PLAIN, cbuf, ch, NULL, victim, TO_CHAR );
        act( AT_PLAIN, vbuf, ch, NULL, victim, TO_VICT );
        act( AT_PLAIN, nvbuf, ch, NULL, victim, TO_NOTVICT );
        dam = URANGE( 1, attacks + ( number_range( 175, 200 + attacks ) + ( int )( attacks * 0.40 ) ), 250 );

        if ( stop )
            break;

        if ( victim->hit > 0 && ( victim->hit - dam ) < 0 )
            act( AT_ACTION, "$n falls to the ground, smouldering!", victim, NULL, NULL, TO_ROOM );

        if ( victim->hit > -150 )
        {
            victim->hit = URANGE( -150, victim->hit - dam, victim->max_hit );

            if ( victim->hit < -100 )
                stop = TRUE;

            if ( stop )
            {
                act( AT_ACTION, "$n smoulders, smoke rising from $s body.", victim, NULL, NULL, TO_ROOM );
                continue;
            }
        }

        if ( victim->hit < -149  )
            victim->hit = URANGE( -499, victim->hit - dam, victim->max_hit );

        if ( victim->hit == -499 && ( !stop ) )
            if ( !IS_IMMORTAL( victim ) )
            {
                act( AT_ACTION, "$n looks like $e is almost dead!", victim, NULL, NULL, TO_ROOM );
                ch_println( ch, "If you want to finish this, use MURDER PERM." );
            }
    }

    return rNONE;
}

SPELLF spell_shield( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    AFFECT_DATA af;
    char arg[MIL];
    level = IS_NPC( ch ) ? ch->top_level : ( int ) ch->skill_level[FORCE_ABILITY];
    target_name = one_argument( target_name, arg );
    set_char_color( AT_MAGIC, ch );

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( NULLSTR( arg ) )
        victim = ch;
    else if ( !( victim = get_char_world( ch, arg ) ) )
    {
        ch_println( ch, "&zSyntax: &CCast Shield [Target]\nNOTE: [Target] is optional." );
        return rINVALID_ARGS;
    }

    if ( is_affected( victim, CHAR_AFFECT, skill ) )
    {
        /* Already affected? Hmm.. Lets just strengthen the spell */
        af.type      = skill->id;
        af.location  = APPLY_AC;
        af.modifier  = 0;

        /*  GRAL  If less than -600 make it -600?
            Xuur: Oh and armor is weird too..Obelix at one time got it up
            further than I could, mine stops at like -415 or whatever....
            But now his won't go over like -300 He once got his to like -560
        */
        if ( GET_AC( victim ) > -600 )
            af.modifier  = -URANGE( 1, ( level / 20 ), level );

        af.duration  = number_range( 1, level / 3 );
        xCLEAR_BITS( af.bitvector );

        /* GRAL Cap out at 600 - something odd above in the math in practice */
        if ( GET_AC( victim ) + af.modifier < -600 )
            af.modifier = GET_AC( victim ) + 600;

        affect_join( victim, CHAR_AFFECT, &af );
        ch_println( ch, "&WYou call upon the power of your magic..." );
        act( AT_WHITE, "$n's body glows as the pulsing energy strengthens!", victim, NULL, NULL, TO_ROOM );
        act( AT_WHITE, "Your body glows as the pulsing energy strengthens!", victim, NULL, NULL, TO_CHAR );
    }
    else
    {
        /* First-time casted */
        af.type = skill->id;
        af.location  = APPLY_AC;
        af.modifier  = -level / 5;
        af.duration  = level * 3;
        xCLEAR_BITS( af.bitvector );

        /* GRAL Cap out at 600 - something odd above in the math in practice */
        if ( GET_AC( victim ) + af.modifier < -600 )
            af.modifier = GET_AC( victim ) + 600;

        /* affect_to_target( victim, CHAR_AFFECT, &af );  Wanted stackable affects */
        affect_join( victim, CHAR_AFFECT, &af );
        ch_println( ch, "&WYou call upon the power of your magic..." );
        act( AT_WHITE, "$n's body is shrouded in a pulsing energy.", victim, NULL, NULL, TO_ROOM );
        act( AT_WHITE, "Your body is shrouded in a pulsing energy!", victim, NULL, NULL, TO_CHAR );
    }

    return rNONE;
}

