SPELLF spell_mist( SKILL_DATA* skill, int level, CHAR_DATA* ch )
{
    CHAR_DATA* victim;

    /* Modifications on 1/2/96 to work on player/object - Scryn */

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( NULLSTR( target_name ) )
        victim = ch;
    else
        victim = get_char_room( ch, target_name );

    if ( victim )
    {
        AFFECT_DATA af;

        if ( xIS_SET( victim->immune, RIS_MAGIC ) )
        {
            immune_casting( skill, ch, victim, NULL );
            return rSPELL_FAILED;
        }

        if ( IS_AFFECTED( victim, AFF_INVISIBLE ) )
        {
            failed_casting( skill, ch, victim, NULL );
            return rSPELL_FAILED;
        }

        act( AT_WHITE, "A mist appears and envelopes $n, concealing them from sight.", victim, NULL, NULL, TO_ROOM );
        af.type = skill->id;
        af.duration  = ( ( level / 4 ) + 12 ) * ( int )DUR_CONV;
        af.location  = APPLY_NONE;
        af.modifier  = 0;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_INVISIBLE );
        affect_join( victim, CHAR_AFFECT, &af );
        act( AT_WHITE, "A mist appears and envelopes you, concealing you from sight.", victim, NULL, NULL, TO_CHAR );
        return rNONE;
    }
    else
    {
        OBJ_DATA* obj;
        obj = get_obj_carry( ch, target_name );

        if ( obj )
        {
            if ( IS_OBJ_STAT( obj, ITEM_INVIS ) || chance( ch, 40 + level / 10 ) )
            {
                failed_casting( skill, ch, NULL, NULL );
                return rSPELL_FAILED;
            }

            xSET_BIT( obj->extra_flags, ITEM_INVIS );
            act( AT_MAGIC, "A mist appears and envelopes $p, concealing it from sight.", ch, obj, NULL, TO_CHAR );
            return rNONE;
        }
    }

    ch_println( ch, "You can't find %s!", target_name );
    return rINVALID_ARGS;
}

SPELLF spell_heal( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    int hp = 0;

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( NULLSTR( target_name ) )
        victim = ch;
    else if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        failed_casting( skill, ch, victim, NULL );
        ch_println( ch, "They are not here." );
        return rINVALID_ARGS;
    }

    act( AT_WHITE, "$n chants softly and is enshrouded in a soft white light.", ch, NULL, NULL, TO_ROOM );

    if ( victim == ch )
        ch_println( ch, "&WYou call upon the power of your magic to heal your wounds." );

    if ( victim != ch )
    {
        ch_println( ch, "&WYou call upon the power of your magic to heal %s's wounds.", g_name( victim, ch ) );
        act( AT_WHITE, "A surge of warmth permeates you, and you feel healthier.\n", ch, NULL, victim, TO_VICT );
    }

    if ( victim != ch )
    {
        ch->alignment = ch->alignment + 50;
        ch->alignment = URANGE( -1000, ch->alignment, 1000 );
    }

    /*  GRAL Where is the drain done?
         Xpuma20X: I'd have to think on that. I'd like to see force healing actually
         stay a set at a specific rate so I can get use to it...
         Its ranged from 500 mana for 50 health, to 200 mana for about 500 health
    */
    hp = number_percent() * number_range( 1, 4 ) + victim == ch ? ( int )get_learned_pct( ch, skill ) :
         ( int )get_learned_pct( ch, skill ) / 2;

    if ( IS_AFFECTED( ch, AFF_CLARITY ) )
        hp += number_range( 150, 400 );

    victim->hit += hp;

    if ( victim->hit > victim->max_hit )
        victim->hit = victim->max_hit;

    return rNONE;
}

SPELLF spell_discovery( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim = NULL;

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    char* msg;
    int ap;

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( !victim )
    {
        act( AT_ACTION, "&zSyntax: &CCast Discovery <&wTarget&C>", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( ch == victim )
    {
        act( AT_ACTION, "&zSyntax: &CCast Discovery <&wTarget&C>", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( xIS_SET( victim->immune, RIS_MAGIC ) )
    {
        immune_casting( skill, ch, victim, NULL );
        return rSPELL_FAILED;
    }

    ap = max_level( victim, FORCE_ABILITY );

    /* Sith ability... learn to hide your force. -Orionv */
    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_NO_SENSE ) )
        ap = 0;

    if ( ( int ) victim->top_level < 100 && !IS_NPC( victim ) && !has_pcflag( victim, PCFLAG_CHILD ) )
        ap = 0;

    if ( IS_NPC( victim ) )
        ap = 0;

    if ( ap > 95 )
        msg = "$N is coursing with the raw power of the Force.";
    else if ( ap > 80 )
        msg = "$N has great potential in the Force.";
    else if ( ap > 50 )
        msg = "The Force courses through $N's veins.";
    else if ( ap > 25 )
        msg = "$N is partially attuned to the Force.";
    else if ( ap > 0 )
        msg = "$N seems to have very little connection to the Force.";
    else
        msg = "$N appears to have no Force potential.";

    act( AT_MAGIC, msg, ch, NULL, victim, TO_CHAR );
    return rNONE;
}

SPELLF spell_speed( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    AFFECT_DATA af;
    int chc = 0, dur = 0;
    chc = standard_force_success_rate( ch, skill );

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( IS_AFFECTED( ch, AFF_SPEED ) )
    {
        ch_println( ch, "You're already moving quickly." );
        return rINVALID_ARGS;
    }

    if ( number_percent() > chc )
    {
        ch_println( ch, "You fail to speed yourself up using the Force." );
        return rSPELL_FAILED;
    }

    dur = number_range( 2, 5 );
    af.type = skill->id;
    af.duration = dur;
    af.modifier = 0;
    af.location = 0;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_SPEED );
    affect_join( ch, CHAR_AFFECT, &af );
    set_char_color( AT_MAGIC, ch );
    ch_println( ch, "You begin moving faster!" );
    act( AT_MAGIC, "$n begins moving faster!", ch, NULL, NULL, TO_ROOM );
    return rNONE;
}

SPELLF spell_grab( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    OBJ_DATA* obj, *tmpobj;
    bool wield;
    wield = FALSE;

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        send_to_char( "They are not here.", ch );
        return rINVALID_ARGS;
    }

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL )
        wield = TRUE;

    if ( ( obj = get_eq_char( victim, WEAR_WIELD ) ) == NULL && !wielding_claws( victim ) )
    {
        send_to_char( "They are not wielding a weapon.", ch );
        return rINVALID_ARGS;
    }

    if ( ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
        obj = tmpobj;

    /* GRAL forcer-force %, forcer-mortal high% */

    if ( wielding_claws( victim ) )
    {
        act( AT_ACTION, "You cannot seem to rip the dewclaws from $N's hands.", ch, NULL, victim, TO_CHAR );
        act( AT_ACTION, "$n tries to pull the dewclaws from your hands.", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$n reaches out towards $N, and $s dewclaws shake slightly.", ch, NULL, victim, TO_NOTVICT );
        return rNONE;
    }

    /*No disarm mob flag by Walldo 01nov09. Ralen September '13 - You had it as or rather than and, bud! */
    if ( IS_NPC( victim ) && xIS_SET( victim->act, ACT_NODISARM ) )
    {
        ch_println( ch, "How do you expect to disarm that?" );
        return rINVALID_ARGS;
    }

    if ( check_grip( ch, victim ) )
    {
        act( AT_ACTION, "You cannot seem to pull $p from $N's hands.", ch, obj, victim, TO_CHAR );
        act( AT_ACTION, "$n tries to pull $p from your hands.", ch, obj, victim, TO_VICT );
        act( AT_ACTION, "$n reaches out towards $N, and $p shakes in $S hands.", ch, obj, victim, TO_NOTVICT );
        return rNONE;
    }

    act( AT_WHITE, "You call upon the power of your magic and pull $p away from $N!", ch, obj, victim, TO_CHAR );
    act( AT_WHITE, "$n quickly chants something and $e pulls $p away from you!", ch, obj, victim, TO_VICT );
    act( AT_WHITE, "$n quickly chants something and $e pulls $p away from $N!", ch, obj, victim, TO_NOTVICT );

    if ( obj == get_eq_char( victim, WEAR_WIELD )
            &&  ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
        tmpobj->wear_loc = WEAR_WIELD;

    obj_from_char( obj );
    obj_to_char( obj, ch );

    if ( wield )
        equip_char( ch, obj, WEAR_WIELD );

    return rNONE;
}

SPELLF spell_wind( SKILL_DATA* skill, int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    int chc = 0;
    /* GRAL shove into a room if exit, if not then take damage from slamming into the wall? */

    if ( ch->race != get_race_by_name( "Dathomiri" ) )
    {
        ch_println( ch, "&ROnly Dathomiri can call upon this spell!" );
        return rINVALID_ARGS;
    }

    if ( ( victim = get_local_offensive_target( ch, target_name ) ) == NULL )
        return rINVALID_ARGS;

    chc = standard_force_success_rate( ch, skill );

    if ( number_range( 2, 175 ) < victim->skill_level[FORCE_ABILITY] )
        chc = 0;

    if ( number_percent() > chc )
    {
        act( AT_WHITE, "You call upon the power of your magic to send a strong gust of wind towards $N, but nothing happens.", ch, NULL, victim, TO_CHAR );
        act( AT_WHITE, "A strong gust of wind pushes against you, but nothing happens.", ch, NULL, victim, TO_VICT );
        return rSPELL_FAILED;
    }

    act( AT_WHITE, "You call upon the power of your magic to send a strong gust of wind to push $N away.", ch, NULL, victim, TO_CHAR );
    act( AT_WHITE, "$n softly chants a spell and causes a strong gust of wind to push $N away from $m.", ch, NULL, victim, TO_NOTVICT );
    act( AT_WHITE, "$n softly chants a spell and causes a strong gust of wind to push you away from $m.", ch, NULL, victim, TO_VICT );
    do_stop( victim, "" );
    lose_approach( victim );

    // Don't make most mobs stop blocking, to prevent messing with progged mobs
    if ( victim->block && !( IS_NPC( victim ) && ( victim->pIndexData->vnum != 97 ) && ( victim->pIndexData->vnum != 250 ) ) )
    {
        act( AT_ACTION, "$n is no longer blocking a direction.", victim, NULL, NULL, TO_ROOM );
        set_char_color( AT_ACTION, victim );
        ch_println( victim, "You are no longer blocking a direction." );
        victim->block = NULL;
    }

    return rNONE;
}

SPELLF spell_levitate( UNUSED(SKILL_DATA* skill), int level __attribute__((unused)), CHAR_DATA* ch )
{
    CHAR_DATA* victim;
    char obj_name [MIL];
    OBJ_DATA*  obj;
    target_name = one_argument( target_name, obj_name );

    if ( NULLSTR( target_name ) || NULLSTR( obj_name ) )
    {
        ch_println( ch, "What object do you wish to levitate, and to whom?" );
        return rINVALID_ARGS;
    }

    if ( ( obj = get_obj_carry( ch, obj_name ) ) == NULL )
    {
        ch_println( ch, "You do not have that item." );
        return rINVALID_ARGS;
    }

    if ( ms_find_obj( ch ) )
        return rSPELL_FAILED;

    if ( obj->wear_loc != WEAR_NONE )
    {
        ch_println( ch, "You must remove it first." );
        return rINVALID_ARGS;
    }

    if ( ( victim = get_char_room( ch, target_name ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return rINVALID_ARGS;
    }

    if ( !IS_NPC( victim ) && has_pcflag( victim, PCFLAG_AFK ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "That player is AFK." );
        return rINVALID_ARGS;
    }

    if ( is_safe( ch, victim ) )
        return rSPELL_FAILED;

    if ( ch == victim )
    {
        ch_println( ch, "You can't levitate that to yourself." );
        return rINVALID_ARGS;
    }

    if ( !can_drop_obj( ch, obj ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You can't let go of it." );
        return rINVALID_ARGS;
    }

    if ( IS_NPC( victim ) )
    {
        if ( victim->vendor_data )
        {
            if ( !is_your_vendor( ch, victim ) )
            {
                ch_println( ch, "&RThats not your vendor! Find your own vendor, Buddy!" );
                return rINVALID_ARGS;
            }
        }
    }

    // We've removed -- at least for now -- the limit on how many items a character can carry. Just focusing on weight. - Nield 08/31/2024
    /*
    if ( ( victim->carry_number + ( get_obj_number( obj ) / obj->count ) > can_carry_n( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N has $S hands full.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    } */

    if ( ( victim->carry_weight + ( get_obj_weight( obj ) / obj->count ) > can_carry_w( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N can't carry that much weight.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( !can_see_obj( victim, obj ) && !IS_IMMORTAL( ch ) )
    {
        act( AT_PLAIN, "$N can't see it.", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    if ( IS_OBJ_STAT( obj, ITEM_PROTOTYPE ) && !can_take_proto( victim ) )
    {
        act( AT_PLAIN, "You cannot give that to $N!", ch, NULL, victim, TO_CHAR );
        return rINVALID_ARGS;
    }

    separate_obj( obj );
    obj_from_char( obj );
    act( AT_MAGIC, "You hold out your hand, guiding $p through the air toward $N until it settles in $S hands.", ch, obj, victim, TO_CHAR );
    act( AT_MAGIC, "$n gestures toward $p as it floats through the air, settling in your hands.", ch, obj, victim, TO_VICT );
    act( AT_MAGIC, "$n gestures toward $p as it floats through the air toward $N, settling in $S hands.", ch, obj, victim, TO_NOTVICT );
    obj = obj_to_char( obj, victim );

    /* Vendor Patch */
    if ( IS_NPC( victim ) )
    {
        if ( victim->vendor_data )
        {
            xREMOVE_BIT( obj->extra_flags, ITEM_INVENTORY );
            save_vendor( victim->vendor_data, true );
        }
    }

    return rNONE;
}

/* Function to determine natural force rolls */
void natroll( CHAR_DATA* ch )
{    
    // Return w/o natrolling if this isn't a PC with an account
    if ( !ch || !ch->pcdata )
        return;

    // Return w/o natrolling if they've already attempted a natroll (regardless of whether it succeeded)
    if ( ch->pcdata->natroll_done )
        return;

    if (!sysdata.sandbox && !ch->pcdata->account)
        return;

    char buf[MSL];

    /* Return w/o natrolling and set the natroll value to done if they:
        - already have force (presumably because they bought it)
        - are a BHer
        - are playing a race that doesn't allow force
        - are playing a warrior race
        - are noforced
        - are an rpc or an imm (we don't want rpc/imms natrolling and taking up limited natroll slots )
    */
    if ( ch->perm_frc > 0 ||
    ch->main_ability == HUNTING_ABILITY ||
    xIS_SET( ch->race->flags, RFLAG_NOFORCE ) ||
    xIS_SET( ch->race->flags, RFLAG_WARRIOR ) ||
    has_pcflag( ch, PCFLAG_CG ) ||
    (ch->pcdata->account && xIS_SET( ch->pcdata->account->flags, ACC_NOFORCE )) ||
    IS_RPC( ch ) ||
    IS_IMMORTAL( ch ) )
    {
        ch->pcdata->natroll_done = true;
        do_save( ch, "-noalert" );
        snprintf( buf, MSL, "%s (%s) is ineligible to natroll force because %s. Auto-failing natroll.", ch->name, ch->pcdata->account ? ch->pcdata->account->name : "No Account",
        ch->perm_frc > 0 ? "they already have it" : ch->main_ability == HUNTING_ABILITY ? "they're a BHer" :
        xIS_SET( ch->race->flags, RFLAG_NOFORCE ) ? "their race is force insensitive" :
        xIS_SET( ch->race->flags, RFLAG_WARRIOR ) ? "they're playing a warrior race" :
        has_pcflag( ch, PCFLAG_CG ) ? "they're a CG character" :
        (ch->pcdata->account && xIS_SET( ch->pcdata->account->flags, ACC_NOFORCE )) ? "their account is noforced" :
        IS_IMMORTAL( ch ) ? "they're an immortal" :
        IS_RPC( ch ) ? "they're an RPC" :
        "unknown (bug)" );
        write_to_log( "natroll", buf, sysdata.log_level, 720, true );
        return;
    }

    // Return w/o natrolling if they're not level 100 or don't have the requisite hours of game time in
    if ( ( ch->top_level < LEVEL_HERO || ch->played < ( 60 * 60 * sysdata.hours_for_force ) ) && !sysdata.sandbox )
        return;

    char logperson[MIL];
    int force_odds = sysdata.force;
    int hours = ( (int) ch->played / 3600 );
    int minutes = ( (int) ( ( ch->played % 3600 ) / 60 ) );

    if ( xIS_SET( ch->race->flags, RFLAG_NATURALFORCE ) )
        force_odds = sysdata.naturalforce;

    debug( "forceroll: %s getting 1 in %d chance for force", ch->name, force_odds );

    if ( number_range( 1, force_odds ) == 1 )
    {
        snprintf( logperson, MIL, "Warning: %s (%s) has rolled natural force.\n", ch->name, ch->pcdata->account ? ch->pcdata->account->name : "No Account" );
        ch->perm_frc = number_range( 12, 20 );
        FORCER_DATA* forcer = forcer_create( ch );
        if ( !forcer )
        {
            bug( "%s: could not fetch or create forcer entry for %s", FUNC, ch->name );
            return;
        }
        forcer->source = FROLL_ROLLED;
        forcer_save( forcer, TRUE );
        save_char_obj( ch, TRUE );
        snprintf( buf, MSL, "%s (%s), %d hours %d minutes of playtime, natrolled %d frc.", ch->name, ch->pcdata->account ? ch->pcdata->account->name : "No Account", hours, minutes, ch->perm_frc );
        write_to_log( "natroll", buf, sysdata.log_level, 720, true );
        log_string_plus( logperson, LOG_NORMAL, 200 );
        sql_natural_log( ch->name, ch->perm_frc );
    }
    else if ( ch->race->frc_plus > 0 )
    {
        ch->perm_frc = ch->race->frc_plus;
        FORCER_DATA* forcer = forcer_create( ch );
        if ( !forcer )
        {
            bug( "%s: could not fetch or create forcer entry for %s", FUNC, ch->name );
            return;
        }
        forcer->source = FROLL_RACIAL;
        forcer_save( forcer, TRUE );
        save_char_obj( ch, TRUE );
        snprintf( buf, MSL, "%s (%s), %d hours %d minutes of playtime, failed to natroll force but has %d racial frc.", ch->name, ch->pcdata->account ? ch->pcdata->account->name : "No Account", hours, minutes, ch->perm_frc );
        write_to_log( "natroll", buf, sysdata.log_level, 720, true );
    }
    else
    {
        snprintf( buf, MSL, "%s (%s), %d hours %d minutes of playtime, failed to natroll force.", ch->name, ch->pcdata->account ? ch->pcdata->account->name : "No Account", hours, minutes );
        write_to_log( "natroll", buf, sysdata.log_level, 720, true );
    }

    ch->pcdata->natroll_done = true;
    save_char_obj( ch, TRUE );
    return;
}

int get_max_mana( CHAR_DATA* ch )
{
    int result = base_max_mana( ch ) + mod_max_mana( ch );
    return result;
}

int base_max_mana( CHAR_DATA* ch )
{
    if ( !ch || ch->perm_frc <= 0 || ch->skill_level[FORCE_ABILITY] <= 1 )
        return 0;

    if ( ch->set_max_mana > 0 )
        return ch->set_max_mana;

    int result = 100;
    result += ch->perm_frc * 100;
    result += ch->corruption_counters * 65;

    if ( ch->pcdata )
    {
        switch ( ch->pcdata->fclass )
        {
            case JEDI_GUARDIAN:
            case SITH_JUGGERNAUT:
                result += 20 * ch->skill_level[FORCE_ABILITY];
                break;

            case JEDI_SENTINEL:
            case SITH_ASSASSIN:
                result += 25 * ch->skill_level[FORCE_ABILITY];
                break;

            case JEDI_CONSULAR:
            case SITH_SORCERER:
                result += 35 * ch->skill_level[FORCE_ABILITY];
                break;

            case JEDI_SAGE:
                result += 30 * ch->skill_level[FORCE_ABILITY];
                break;

            case SITH_DARKLORD:
                result += 30 * ch->skill_level[FORCE_ABILITY];
                break;

            default:
                result += 5 * ch->skill_level[FORCE_ABILITY];
                break;
        }
    }

    return result;
}

int mod_max_mana( CHAR_DATA* ch )
{
    if ( !ch || base_max_mana( ch ) <= 0 )
        return 0;

    int result = 0;
    AFFECT_DATA* aff = NULL;
    for ( aff = ch->first_affect; aff; aff = aff->next )
        if ( aff->location == APPLY_MANA )
            result += aff->modifier;

    aff = NULL;
    for ( OBJ_DATA* obj = ch->first_carrying; obj; obj = obj->next_content )
    {
        if ( obj->wear_loc != WEAR_NONE )
        {
            for ( aff = obj->first_affect; aff; aff = aff->next )
                if ( aff->location == APPLY_MANA && !ch_affected_by( ch, aff ) )
                    result += aff->modifier;

            if ( obj->pIndexData )
                for ( aff = obj->pIndexData->first_affect; aff; aff = aff->next )
                    if ( aff->location == APPLY_MANA && !ch_affected_by( ch, aff ) )
                        result += aff->modifier;
        }
    }

    return result;
}
