int get_skilltype( char* skilltype )
{
    if ( !str_cmp( skilltype, "Unknown" ) )
        return SKILL_UNKNOWN;

    if ( !str_cmp( skilltype, "Spell" ) )
        return SKILL_SPELL;

    if ( !str_cmp( skilltype, "Skill" ) )
        return SKILL_SKILL;

    if ( !str_cmp( skilltype, "Weapon" ) )
        return SKILL_WEAPON;

    if ( !str_cmp( skilltype, "Tongue" ) )
        return SKILL_TONGUE;

    if ( !str_cmp( skilltype, "Herb" ) )
        return SKILL_HERB;

    if ( !str_cmp( skilltype, "Bodytype" ) )
        return SKILL_DROIDTYPE;

    if ( !str_cmp( skilltype, "Protocol" ) )
        return SKILL_PROTOCOL;

    if ( !str_cmp( skilltype, "Feat" ) )
        return SKILL_FEAT;

    if ( !str_cmp( skilltype, "Lightsaber Form" ) || !str_cmp( skilltype, "LightsaberForm" ) || !str_cmp( skilltype, "SaberForm" ) )
        return SKILL_LIGHTSABER_FORM;

    return SKILL_UNKNOWN;
}

int skill_delete( SKILL_DATA* skill )
{
    SKILL_CACHE* cache = NULL, *next_cache = NULL;

    if ( !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    // Go through the cached pointers and null any that relate to this skill
    for ( cache = first_skill_cache; cache; cache = next_cache )
    {
        next_cache = cache->next;

        if ( cache->ptr && *cache->ptr == skill )
        {
            *cache->ptr = NULL;
            UNLINK( cache, first_skill_cache, last_skill_cache, next, prev );
            DISPOSE( cache );
        }
    }

    // Dispose of the skill table. It'll get remade the next time skill_from_id runs.
    if ( skill_table )
        DISPOSE( skill_table );

    // If the skill was a language, remove it from the language table.
    if ( skill->type == SKILL_TONGUE )
        for ( int i = 0; i < MAX_LANGUAGE; i++ )
            if ( language_table[i] == skill )
                language_table[i] = NULL;

    delete_sql_row_by_id( DB_TABLE_SKILLS, skill->id );
    return remove_skill( skill );
}

