extern char* target_name;   /* from magic.c */

/*
    Perform a binary search on a section of the skill table
    Each different section of the skill table is sorted alphabetically
    Only match skills player knows               -Thoric
*/
bool check_skill( CHAR_DATA* ch, char* command, char* argument )
{
    char logline[XMIL];
    SKILL_DATA* skill = ( ch->last_skill_used && ( !str_cmp( command, ch->last_skill_used->name ) || !str_prefix( command, ch->last_skill_used->name ) ) ) ? ch->last_skill_used : skill_from_name( command );
    struct timeval time_used;
    int mana;
    /* bsearch for the skill */

    if ( !skill || skill->skill_fun == NULL || skill->spell_fun == spell_null || ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && get_learned_pct( ch, skill ) < 100 ) )
    {
        for ( skill = first_skill; skill; skill = skill->next )
        {
            if ( LOWER( command[0] ) == LOWER( skill->name[0] ) && !str_prefix( command, skill->name ) && ( skill->skill_fun != NULL || skill->spell_fun != spell_null ) && ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || ( get_learned_pct( ch, skill ) > 0 ) ) )
            {
                if ( !str_prefix( command, skill->name ) )
                    break;
            }
        }

        if ( !skill )
            return FALSE;
    }

    if ( skill && skill->type == SKILL_SPELL )
        return FALSE;

    int loglvl = skill ? skill->log : LOG_NORMAL;

    if ( !IS_NPC( ch ) && !has_pcflag( ch, PCFLAG_LOG ) && ( loglvl == LOG_BUILD || loglvl == LOG_HIGH || loglvl == LOG_ALWAYS ) )
    {
        /*  Added by Narn to show who is switched into a mob that executes
            a logged command.  Check for descriptor in case force is used. */
        snprintf( logline, XMIL, "%s %s", skill->name, argument );
        if ( ch->desc && ch->desc->original )
            snprintf( log_buf, MSL, "Log %s (%s): %s", ch->name, ch->desc->original->name, logline );
        else
            snprintf( log_buf, MSL, "Log %s: %s", ch->name, logline );

        /*
            Make it so a 'log all' will send most output to the log
            file only, and not spam the log channel to death -Thoric
        */
        if ( fLogAll && loglvl == LOG_NORMAL
                &&  ( IS_NPC( ch ) || !has_pcflag( ch, PCFLAG_LOG ) ) )
            loglvl = LOG_ALL;

        log_string_plus( log_buf, loglvl, get_trust( ch ) );
    }

    if ( !check_pos( ch, skill->minimum_position ) )
        return TRUE;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
            &&  ( IS_AFFECTED( ch, AFF_CHARM ) || IS_AFFECTED( ch, AFF_POSSESS ) ) )
    {
        ch_println( ch, "For some reason, you seem unable to perform that..." );
        act( AT_GREY, "$n looks around.", ch, NULL, NULL, TO_ROOM );
        return TRUE;
    }

    /* check if mana is required */
    if ( skill->min_mana )
    {
        mana = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 0 : skill->min_mana;

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ch->mana < mana )
        {
            ch_println( ch, "You need to rest before using the Force any more." );
            return TRUE;
        }
    }
    else
    {
        mana = 0;
    }

    /*
        Is this a real do-fun, or a really a spell?
    */
    if ( !skill->skill_fun )
    {
        ch_ret retcode = rNONE;
        CHAR_DATA* victim = NULL;
        OBJ_DATA* obj = NULL;
        target_name = "";

        switch ( skill->target )
        {
            default:
                bug( "Check_skill: bad target for skill %d.", skill->id );
                ch_println( ch, "Something went wrong..." );
                return TRUE;

            case TAR_IGNORE:
                if ( NULLSTR( argument ) )
                {
                    if ( ( victim = who_fighting( ch ) ) != NULL )
                        target_name = victim->name;
                }
                else
                    target_name = argument;

                break;

            case TAR_CHAR_OFFENSIVE:
                if ( argument[0] == '\0'
                        &&  ( victim = who_fighting( ch ) ) == NULL )
                {
                    ch_println( ch, "%s who?", capitalize( skill->name ) );
                    return TRUE;
                }
                else if ( argument[0] != '\0'
                          &&  ( victim = get_char_room( ch, argument ) ) == NULL )
                {
                    ch_println( ch, "They aren't here." );
                    return TRUE;
                }

                if ( is_safe( ch, victim ) )
                    return TRUE;

                break;

            case TAR_CHAR_DEFENSIVE:
                if ( argument[0] != '\0'
                        &&  ( victim = get_char_room( ch, argument ) ) == NULL )
                {
                    ch_println( ch, "They aren't here." );
                    return TRUE;
                }

                if ( !victim )
                    victim = ch;

                break;

            case TAR_CHAR_SELF:
                break;

            case TAR_OBJ_INV:
                if ( ( obj = get_obj_carry( ch, argument ) ) == NULL )
                {
                    ch_println( ch, "You can't find that." );
                    return TRUE;
                }
                break;
        }

        if ( mana )
            ch->mana -= mana;

        // Do skills not interrupt?? -Miros
        //
        // Evidently not Past Miros.  It seems as though they dont, and in-fact should or chaos will follow.
        // ~Miros 6-15-14.
        interrupt_ch( ch );
        /* waitstate */
        WAIT_STATE( ch, skill->beats );
        start_timer( &time_used );
        retcode = ( *skill->spell_fun ) ( skill, ch->top_level, ch );
        end_timer( &time_used );
        update_userec( &time_used, &skill->userec );

        if ( retcode == rCHAR_DIED || retcode == rERROR )
            return TRUE;

        if ( char_extracted( ch ) )
            return TRUE;

        if ( retcode == rSPELL_FAILED )
        {
            learn_from_failure( ch, skill );
            retcode = rNONE;
        }
        else
            learn_from_success( ch, skill );

        if ( skill->target == TAR_CHAR_OFFENSIVE && victim != ch && !char_extracted( victim ) )
        {
            CHAR_DATA* vch;
            CHAR_DATA* vch_next;

            for ( vch = ch->in_room->first_person; vch; vch = vch_next )
            {
                vch_next = vch->next_in_room;

                if ( victim == vch && !victim->fighting && victim->master != ch )
                {
                    retcode = multi_hit( victim, ch, TYPE_UNDEFINED );
                    break;
                }
            }
        }

        return TRUE;
    }

    if ( mana )
        ch->mana -= mana;

    ch->prev_cmd = ch->last_cmd;    /* haus, for automapping */
    ch->last_cmd = skill->skill_fun;
    // interrupt ch here also ~Miros
    interrupt_ch( ch );
    // note lua interrupt not implemented here.  revisit. ~Miros
    start_timer( &time_used );
    ( *skill->skill_fun ) ( ch, argument );
    end_timer( &time_used );
    update_userec( &time_used, &skill->userec );
    tail_chain( );
    return TRUE;
}

/*
    Lookup a skills information
    High god command
*/
CMDF do_slookup( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], arg[MIL];
    SKILL_DATA* skill = NULL;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&wSlookup what?" );
        ch_println( ch, "&zSyntax: &CSlookup <&wskill #&C>&w" );
        return;
    }

    one_argument( argument, arg );

    if ( !str_cmp( arg, "all" ) )
    {
        for ( skill = first_skill; skill; skill = skill->next )
            pager_printf( ch, "&zSn: &C%4d&z Slot: &w%4d&z Skill/spell: &C'&w%-20s&C'&z Damtype: &C%s&z\n",
                          skill->id, skill->slot, skill->name ? skill->name : "(null)",
                          spell_damage[SPELL_DAMAGE( skill )] );
    }
    else if ( !str_cmp( arg, "feats" ) )
    {
        for ( skill = first_skill; skill; skill = skill->next )
            if ( skill->type == SKILL_FEAT )
                pager_printf( ch, "&C%d&z) &C'&w%-20s&C' &zClass: &w%s: &z(&C%d&z)\n", skill->id, skill->name ? skill->name : "(null)", flag_value_name( ability_name, skill->guild ), skill->min_level );
    }
    else
    {
        if ( is_number( arg ) )
            skill = skill_from_id( atoi( arg ) );
        else
            skill = skill_from_name( argument );

        if ( !skill )
        {
            ch_println( ch, "Could not find that skill." );
            return;
        }

        ch_println( ch, "&zSn: &C%4d&z Slot: &w%4d &C%s: '&w%-20s&C'&w",
                   skill->id, skill->slot, skill_tname[skill->type], skill->name ? skill->name : "(null)" );

        if ( skill->flags )
        {
            int x;
            ch_println( ch, "&zDamtype: &C%s  &zActtype: &C%s&z   Classtype: &C%s&z   &zPowertype: &C%s&w",
                       spell_damage[SPELL_DAMAGE( skill )],
                       spell_action[SPELL_ACTION( skill )],
                       spell_class[SPELL_CLASS( skill )],
                       spell_power[SPELL_POWER( skill )] );
            strlcpy( buf, "&zFlags:&C", MSL );

            for ( x = 11; x < 32; x++ )
                if ( SPELL_FLAG( skill, 1 << x ) )
                {
                    strlcat( buf, " ", MSL );
                    strlcat( buf, spell_flag[x - 11], MSL );
                }

            strlcat( buf, "\n", MSL );
            send_to_char( buf, ch );
        }

        ch_println( ch, "&zSaves: &w%s&z", spell_saves[( int ) skill->saves] );

        if ( skill->difficulty != '\0' )
            ch_println( ch, "&zDifficulty: &R%d&z", ( int ) skill->difficulty );

        ch_println( ch, "&zType: &C%s&z Target: &C%s&z Minpos: &w%d&z Mana: &C%d&z Beats: &w%d&z",
                   skill_tname[skill->type],
                   target_type[URANGE( ( int )TAR_IGNORE, skill->target, ( int )TAR_OBJ_INV )],
                   skill->minimum_position,
                   skill->min_mana,
                   skill->beats );
        ch_println( ch, "&zFlags: &C%d&z  Class: &C%d&z  Code: &w%s&z",
                   skill->flags,
                   skill->guild,
                   skill->skill_fun ? skill->skill_fun_name : skill->spell_fun_name );
        ch_printf( ch, "&zDammsg:&w %s\n&zWearoff: &w%s&z\n",
                   skill->noun_damage,
                   skill->msg_off ? skill->msg_off : "&z(&Cnone set&z)&w" );

        if ( skill->dice && skill->dice[0] != '\0' )
            ch_println( ch, "&zDice: &C%s&z", skill->dice );

        if ( skill->teachers && skill->teachers[0] != '\0' )
            ch_println( ch, "&zTeachers: &C%s&z", skill->teachers );

        ch_println( ch, "&zTeachable: %s&z", skill->no_teach ? "&RNO" : "&GYES" );

        if ( skill->participants )
            ch_println( ch, "&zParticipants: &C%d&z", ( int ) skill->participants );

        if ( skill->userec.num_uses )
            send_timer( &skill->userec, ch );

        if ( skill->hit_char && skill->hit_char[0] != '\0' )
            ch_println( ch, "Hitchar   : %s", skill->hit_char );

        if ( skill->hit_vict && skill->hit_vict[0] != '\0' )
            ch_println( ch, "Hitvict   : %s", skill->hit_vict );

        if ( skill->hit_room && skill->hit_room[0] != '\0' )
            ch_println( ch, "Hitroom   : %s", skill->hit_room );

        if ( skill->miss_char && skill->miss_char[0] != '\0' )
            ch_println( ch, "Misschar  : %s", skill->miss_char );

        if ( skill->miss_vict && skill->miss_vict[0] != '\0' )
            ch_println( ch, "Missvict  : %s", skill->miss_vict );

        if ( skill->miss_room && skill->miss_room[0] != '\0' )
            ch_println( ch, "Missroom  : %s", skill->miss_room );

        if ( skill->die_char && skill->die_char[0] != '\0' )
            ch_println( ch, "Diechar   : %s", skill->die_char );

        if ( skill->die_vict && skill->die_vict[0] != '\0' )
            ch_println( ch, "Dievict   : %s", skill->die_vict );

        if ( skill->die_room && skill->die_room[0] != '\0' )
            ch_println( ch, "Dieroom   : %s", skill->die_room );

        if ( skill->imm_char && skill->imm_char[0] != '\0' )
            ch_println( ch, "Immchar   : %s", skill->imm_char );

        if ( skill->imm_vict && skill->imm_vict[0] != '\0' )
            ch_println( ch, "Immvict   : %s", skill->imm_vict );

        if ( skill->imm_room && skill->imm_room[0] != '\0' )
            ch_println( ch, "Immroom   : %s", skill->imm_room );

        if ( skill->guild >= 0 && skill->guild < MAX_ABILITY )
        {
            snprintf( buf, MSL, "&zClass: &C%s&z   &zAlign: &G%4d&z   &zlvl: &C%3d&z\n",
                     flag_value_name( ability_name, skill->guild ), skill->alignment,    skill->min_level );
            send_to_char( buf, ch );
        }

        ch_println( ch, "" );
    }

    return;
}

/*
    Set a skill's attributes or what skills a player has.
    High god command, with support for creating skills/spells/herbs/etc
*/
CMDF do_sset( CHAR_DATA* ch, char* argument )
{
    SKILL_DATA* skill = NULL;
    SKILL_CACHE* cache = NULL, *next_cache = NULL;
    char buf[MSL], arg1[MIL], arg2[MIL], arg3[MIL];
    CHAR_DATA* victim = NULL;
    int value;
    bool fAll;
    snprintf( buf, MSL, "%s", argument );

    argument = one_argument( argument, arg1 );

    if ( NULLSTR( arg1 ) || NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Csset <&wvictim&C> <&wskill name/#&C> <&wvalue&C>" );
        ch_println( ch, "&z        &Csset <&wvictim&C> all <&wvalue&C>" );
        ch_println( ch, "&z        &Csset create <&wnew skill&C>&w" );
        ch_println( ch, "&z        &Csset delete <&wskill name/#&C>" );
        ch_println( ch, "&z        &Csset edit <&wskill name/#&C> <&wfield&C> <&wvalue&C>" );
        ch_println( ch, "\n&zFields:" );
        ch_println( ch, "&B  name code target minpos slot mana beats dammsg wearoff guild minlevel&w" );
        ch_println( ch, "&B  type damtype acttype classtype powertype flag dice value difficulty&w" );
        ch_println( ch, "&B  level adept hit miss die imm &C(&wchar/vict/room&C)&B approach&w" );
        ch_println( ch, "&B  teachers held noteach teachmax log&w" );
        ch_println( ch, "&CAffect&z having the fields: &C<&wlocation&C> <&wmodifier&C> [duration] [bitvector]&w" );
        ch_println( ch, "&z(&wSee &CAFFECTTYPES&w for location, and &CAFFECTED_BY&w for bitvectors&z)" );
        ch_println( ch, "&z'Skill' being any &Cskill&z or &Cspell&z.&w" );
        return;
    }

    if ( !str_cmp( arg1, "create" ) )
    {
        if ( ( skill = skill_from_name( argument ) ) != NULL )
        {
            ch_println( ch, "&RThat skill already exists!" );
            return;
        }

        CREATE( skill, SKILL_DATA, 1 );
        SET_STRING( skill->name, argument );
        SET_STRING( skill->noun_damage, "" );
        SET_STRING( skill->msg_off, "" );
        skill->spell_fun = spell_null;
        skill->type = SKILL_SKILL;
        skill_save( skill );
        add_skill( skill );

        // Nix the skill table. It'll get remade with a new dynamic size the next time skill_from_id runs.
        if ( skill_table )
            DISPOSE( skill_table );

        ch_println( ch, "Done." );
        return;
    }

    argument = one_argument( argument, arg2 );
    argument = one_argument( argument, arg3 );

    if ( !str_cmp( arg1, "edit" )|| !str_cmp( arg1, "delete" ) )
    {
        if ( is_number( arg2 ) )
            skill = skill_from_id( atoi( arg2 ) );
        else
            skill = skill_from_name( arg2 );

        if ( !skill )
        {
            ch_println( ch, "&RThat skill could not be found." );
            return;
        }

        if ( !str_cmp( arg1, "delete" ) )
        {
            skill_delete( skill );
            ch_println( ch, "Done." );
            return;
        }

        if ( !str_cmp( arg3, "approach" ) )
        {
            skill->approach = !skill->approach;
            skill_save( skill );
            ch_println( ch, "&zApproach is &C%s&z needed to use &C%s&z.&w", skill->approach ? "now" : "no longer", skill->name );
            return;
        }

        if ( !str_cmp( arg3, "noteach" ) )
        {
            skill->no_teach = !skill->no_teach;
            skill_save( skill );
            ch_println( ch, "&zSkill &C%s&z is &C%s&z teachable.&w", skill->name, skill->no_teach ? "no longer" : "now" );
            return;
        }

        if ( !str_cmp( arg3, "teachmax" ) )
        {
            if ( skill->no_teach )
            {
                ch_println( ch, "&zThat skill is currently set to noteach." );
                return;
            }

            char arg4[MIL];
            int val = 0;
            argument = one_argument( argument, arg4 );
            if ( NULLSTR( arg4 ) || !is_number( arg4 ) || ( val = atoi( arg4 ) ) < 0 || val > 100 )
            {
                ch_println( ch, "&zSyntax: &Csset edit %s teacmax <&wskill percent&C>" );
                ch_println( ch, "&wRange: 0 (no limit) to 100" );
                return;
            }

            skill->teach_max = val;
            skill_save( skill );
            ch_println( ch, "&zSkill &C%s&z is &C%s&z teachable.&w", skill->name, skill->no_teach ? "no longer" : "now" );
            return;
        }

        if ( !str_cmp( arg3, "difficulty" ) )
        {
            skill->difficulty = atoi( argument );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "participants" ) )
        {
            skill->participants = atoi( argument );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "alignment" ) )
        {
            skill->alignment = atoi( argument );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( "temple", arg3 ) )
        {
            if ( !get_room_index( atoi( argument ) ) )
                ch_println( ch, "No such room." );
            else {
                skill->temple = atoi( argument );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }
            return;
        }

        if ( !str_cmp( arg3, "damtype" ) )
        {
            int x = get_sdamage( argument );

            if ( x == -1 )
                ch_println( ch, "Not a spell damage type." );
            else
            {
                SET_SDAM( skill, x );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "acttype" ) )
        {
            int x = get_saction( argument );

            if ( x == -1 )
                ch_println( ch, "Not a spell action type." );
            else
            {
                SET_SACT( skill, x );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "classtype" ) )
        {
            int x = get_sclass( argument );

            if ( x == -1 )
                ch_println( ch, "Not a spell class type." );
            else
            {
                SET_SCLA( skill, x );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "powertype" ) )
        {
            int x = get_spower( argument );

            if ( x == -1 )
                ch_println( ch, "Not a spell power type." );
            else
            {
                SET_SPOW( skill, x );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "flag" ) )
        {
            int x = get_sflag( argument );

            if ( x == -1 )
                ch_println( ch, "Not a spell flag." );
            else
            {
                TOGGLE_BIT( skill->flags, 1 << ( x + 11 ) );
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "saves" ) )
        {
            int x = get_ssave( argument );

            if ( x == -1 )
                ch_println( ch, "Not a saving type." );
            else
            {
                skill->saves = x;
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "code" ) )
        {
            SPELL_FUN* spellfun;
            DO_FUN* dofun;

            if ( !str_prefix( "do_", argument ) && ( dofun = skill_function( argument ) ) != skill_notfound )
            {
                skill->skill_fun = dofun;
                skill->spell_fun = NULL;
                SET_STRING( skill->skill_fun_name, argument );
                SET_STRING( skill->spell_fun_name, NULL );
            }
            else if ( ( spellfun = spell_function( argument ) ) != spell_notfound )
            {
                skill->spell_fun = spellfun;
                skill->skill_fun = NULL;
                SET_STRING( skill->spell_fun_name, argument );
                SET_STRING( skill->skill_fun_name, NULL );
            }
            else if ( is_spec( argument ) )
            {
                ch_println( ch, "Cannot use a spec_fun for skills or spells." );
                return;
            }
            else
            {
                ch_println( ch, "Not a spell or skill." );
                return;
            }

            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "target" ) )
        {
            int x = get_starget( argument );

            if ( x == -1 )
                ch_println( ch, "Not a valid target type." );
            else
            {
                skill->target = x;
                skill_save( skill );
                ch_println( ch, "Ok." );
            }

            return;
        }

        if ( !str_cmp( arg3, "minpos" ) )
        {
            skill->minimum_position = URANGE( POS_DEAD, atoi( argument ), POS_DRAG );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "minlevel" ) )
        {
            skill->min_level = URANGE( 1, atoi( argument ), MAX_LEVEL );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "slot" ) )
        {
            skill->slot = URANGE( 0, atoi( argument ), 30000 );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "mana" ) )
        {
            skill->min_mana = URANGE( 0, atoi( argument ), 2000 );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "beats" ) )
        {
            /* let us set the beats to violence length -Orion */
            if ( !str_cmp( argument, "round" ) )
                skill->beats = PULSE_VIOLENCE;
            else
                skill->beats = URANGE( 0, atoi( argument ), 120 );

            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "guild" ) )
        {
            skill->guild = atoi( argument );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "value" ) )
        {
            skill->value = atoi( argument );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "type" ) )
        {
            skill->type = get_skilltype( argument );    
            skill_save( skill );
            ch_println( ch, "Ok." );
            if ( skill->type == SKILL_TONGUE )
            {
                const FLAG_INFO* flag = flag_from_name( languages, skill->name );
                if ( flag )
                    language_table[flag->flag] = skill;
            }
            return;
        }

        if ( !str_cmp( arg3, "level" ) )
        {
            skill->min_level = URANGE( 1, atoi( argument ), MAX_LEVEL );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "log" ) )
        {
            int log = atoi( argument );

            if ( log < 0 || log > LOG_LPROG || NULLSTR( argument ) )
            {
                ch_println( ch, "&zsset log range is &c0 <= &R# &z<= &c%d.", LOG_LPROG );
                ch_println( ch, "&c0 &zLOG_NORMAL, &c1 &zLOG_ALWAYS, &c2 &zLOG_NEVER, &c3 &zLOG_BUILD, &c4 &zLOG_HIGH,\n&c5 &zLOG_COMM, &r6 LOG_MPROG&z, &r7 LOG_LPROG&z, &r8 LOG_ALL&D" );
                return;
            }

            skill->log = log;
            ch_println( ch, "&zsset &c%s &zlog level &c%d &zsaved.&D", skill->name, log );
            skill_save( skill );
            return;
        }

        if ( !str_cmp( arg3, "name" ) )
        {
            for ( cache = first_skill_cache; cache; cache = next_cache )
            {
                next_cache = cache->next;
                if ( cache->ptr && *cache->ptr == skill )
                {
                    *cache->ptr = NULL;
                    UNLINK( cache, first_skill_cache, last_skill_cache, next, prev );
                    DISPOSE( cache );
                }
            }
            SET_STRING( skill->name, argument );
            skill_save( skill );
            if ( skill->type == SKILL_TONGUE )
            {
                const FLAG_INFO* flag = flag_from_name( languages, skill->name );
                if ( flag )
                    language_table[flag->flag] = skill;
            }
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "dammsg" ) )
        {
            SET_STRING( skill->noun_damage, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "wearoff" ) )
        {
            SET_STRING( skill->msg_off, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "hitchar" ) )
        {
            SET_STRING( skill->hit_char, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "hitvict" ) )
        {
            SET_STRING( skill->hit_vict, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "hitroom" ) )
        {
            SET_STRING( skill->hit_room, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "misschar" ) )
        {
            SET_STRING( skill->miss_char, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "missvict" ) )
        {
            SET_STRING( skill->miss_vict, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "missroom" ) )
        {
            SET_STRING( skill->miss_room, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "diechar" ) )
        {
            SET_STRING( skill->die_char, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "dievict" ) )
        {
            SET_STRING( skill->die_vict, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "dieroom" ) )
        {
            SET_STRING( skill->die_room, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "immchar" ) )
        {
            SET_STRING( skill->imm_char, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "immvict" ) )
        {
            SET_STRING( skill->imm_vict, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "immroom" ) )
        {
            SET_STRING( skill->imm_room, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "dice" ) )
        {
            SET_STRING( skill->dice, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "teachers" ) )
        {
            SET_STRING( skill->teachers, str_cmp( argument, "clear" ) ? argument : "" );
            skill_save( skill );
            ch_println( ch, "Ok." );
            return;
        }

        if ( !str_cmp( arg3, "held" ) )
        {
            if ( !is_number( argument ) || atoi( argument ) < 0 || atoi( argument ) > 1 )
            {
                ch_println( ch, "&zValid values are &C1&z for TRUE, &C0&z for FALSE.&w" );
                return;
            }
            else
            {
                skill->held = atoi( argument );
                skill_save( skill );
                ch_println( ch, "Ok." );
                return;
            }
        }

        do_sset( ch, "" );
        return;
    }

    if ( ( victim = get_char_world_full( ch, arg1 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim != ch && !IS_NPC( victim ) )
        add_mset( victim, buf, get_trust( ch ), ch->name );


    fAll = !str_cmp( arg2, "all" );

    if ( !fAll )
    {
        if ( is_number( arg2 ) )
            skill = skill_from_id( atoi( arg2 ) );
        else
            skill = skill_from_name( arg2 );
    }

    if ( !fAll && !skill )
    {
        ch_println( ch, "Could not find that skill." );
        return;
    }

    /*
        Snarf the value.
    */
    if ( !is_number( arg3 ) )
    {
        ch_println( ch, "Value must be numeric." );
        return;
    }

    value = atoi( arg3 );

    if ( value < 0 || value > 100 )
    {
        ch_println( ch, "&zValue range is &C0&z to &C100&z.&w" );
        return;
    }

    if ( fAll )
    {
        for ( skill = first_skill; skill; skill = skill->next )
        {
            /* Fix by Narn to prevent ssetting skills the player shouldn't have. */
            /* marker */
            if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
                continue;

            if ( skill->type == SKILL_FEAT )
                continue;

            if ( skill->name && ( victim->skill_level[skill->guild] >= skill->min_level || value == 0 ) )
                set_learned_pct( victim, skill, value );
        }

        if ( IS_IMMORTAL( ch ) ) //Check is necessary because sometimes functions use SSET and players don't need to see this when those other paths are utilized.
            ch_println( ch, "All of %s's skills have been adjusted to %d.", victim->name, value );
    }
    else
    {
        int tmpval = get_learned_pct( victim, skill );
        set_learned_pct( victim, skill, value );

        if ( IS_IMMORTAL( ch ) ) //Check is necessary because sometimes functions use SSET and players don't need to see this when those other paths are utilized.
            ch_println( ch, "%s's skill in %s has been adjusted from %d to %d.", victim->name, skill->name, tmpval, value );
    }

    return;
}

void learn_from_success( CHAR_DATA* ch, SKILL_DATA* skill )
{
    learn_from_success_ex( ch, skill, false );
}

void learn_from_success_ex( CHAR_DATA* ch, SKILL_DATA* skill, bool assured )
{
    int adept = 0, gain = 0, sklvl = 0, learn = 0, percent = 0, chance = 0, chc = 0, prev_pct = 0, new_pct = 0;

    if ( !ch || !skill )
        return;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || ( prev_pct = get_learned_pct( ch, skill ) ) == 0 )
        return;

    if ( skill->guild == FORCE_ABILITY )
    {
        CHAR_DATA* victim;
        victim = fetch_apprentice( ch, TRUE );

        if ( skill->name )
        {
            if ( !str_cmp( "presence", skill->name )
                    || !str_cmp( "vengeance", skill->name ) )
            {
                chc = prev_pct;
                chc = 100 - chc;

                if ( number_percent() > chc )
                    return;
            }
        }

        if ( victim != NULL )
            learn_from_master_success( victim, skill );

        if ( !str_cmp( "senses", skill->name ) && prev_pct >= ch->skill_level[FORCE_ABILITY] )
            return; //Move the check here instead of fight.c so masters have a chance to teach their padawans how to fight with senses. - Gathorn 24 Jul 18
    }

    sklvl = skill->min_level;

    if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
        return;

    adept = ( ( ch->skill_level[skill->guild] - skill->min_level ) * 20 ) + 50;

    /* What about level 150 skills? :)  -Orion */
    if ( skill->min_level >= 147 )
        adept = 100;

    adept = UMIN( adept, 100 );

    if ( prev_pct >= adept )
        return;

    if ( sklvl == 0 || sklvl > ch->skill_level[skill->guild] )
        sklvl = ch->skill_level[skill->guild];

    if ( prev_pct < 100 )
    {
        chance = prev_pct + 5; /* skill->difficulty);*/
        percent = number_percent();

        if ( percent >= chance )
            learn = 2;
        else if ( !assured && chance - percent > 25 )
        {
            debug( "learn_from_success roll failed. %s not learning.", ch->name );
            return;
        }
        else
            learn = 1;

        cache_skill( "scientific mind", &skill_scientific_mind );
        if ( has_feat( ch, skill_scientific_mind ) )
        {
            learn *= 2;
            debug( "learn from success, %s is learning quickly (%d pts)", ch->name, learn );
            ch_println( ch, "&GYou learn quickly!" );
        }

        new_pct = UMIN( adept, get_learned_pct( ch, skill ) + learn );
        set_learned_pct( ch, skill, new_pct );

        if ( new_pct == 100 )    /* fully learned! */
        {
            gain = 50 * sklvl;
            /* gain = apply_xp_sink( ch, gain, skill->guild ); */
            set_char_color( AT_WHITE, ch );
            ch_println( ch, "You are now an adept of %s! You gain %d bonus experience!", skill->name, gain );
        }
        else
        {
            gain = 10 * sklvl;
            gain = apply_xp_sink( ch, gain, skill->guild );
            set_char_color( AT_WHITE, ch );
            ch_println( ch, "You learned more about %s, growing from %d%% to %d%%", skill->name, prev_pct, new_pct );
            ch_println( ch, "You gain %d experience points from your success!", gain );
        }

        gain_exp( ch, gain, skill->guild, TRUE );
    }

    // We force player to save after they gain %!    Orion 2008
    do_save( ch, "-noalert" ); // HAX
}


void learn_from_failure( CHAR_DATA* ch, SKILL_DATA* skill )
{
    int adept = 0, gain = 0, sklvl = 0, learn = 0, percent = 0, chance = 0, prev_pct = 0, new_pct = 0;

    if ( !ch )
        return;

    /* Lower odds of learning from failures */
    if ( number_range( 0, 5 ) != 0 )
        return;

    if ( !skill )
    {
        bug( "%s: NULL skill", FUNC );
        return;
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || ( prev_pct = get_learned_pct( ch, skill ) ) == 0 )
        return;

    if ( skill->guild == FORCE_ABILITY )
    {
        CHAR_DATA* victim;
        victim = fetch_apprentice( ch, TRUE );

        if ( victim != NULL )
            learn_from_master_failure( victim, skill );
    }

    sklvl = skill->min_level;

    if ( skill->guild < 0 || skill->guild >= MAX_ABILITY )
        return;

    adept = ( ( ch->skill_level[skill->guild] - skill->min_level ) * 10 ) + 50;
    adept = UMIN( adept, 100 );

    if ( prev_pct >= adept )
        return;

    if ( sklvl == 0 || sklvl > ch->skill_level[skill->guild] )
        sklvl = ch->skill_level[skill->guild];

    if ( prev_pct < 60 )
    {
        chance = prev_pct + 5; /* skill->difficulty);*/
        percent = number_percent();

        if ( percent >= chance )
            learn = 2;
        else if ( chance - percent > 25 )
            return;
        else
            learn = 1;

        new_pct = UMIN( adept, prev_pct + learn );
        set_learned_pct( ch, skill, new_pct );

        if ( new_pct == 100 )    /* fully learned! */
        {
            gain = 50 * sklvl;
            /* gain = apply_xp_sink( ch, gain, skill->guild ); */
            set_char_color( AT_WHITE, ch );
            ch_println( ch, "You are now an adept of %s!  You gain %d bonus experience!", skill->name, gain );
        }
        else
        {
            gain = 10 * sklvl;
            gain = apply_xp_sink( ch, gain, skill->guild );

            if ( !ch->fighting && str_cmp( skill->name, "hide" ) && str_cmp( skill->name, "sneak" ) )
            {
                set_char_color( AT_WHITE, ch );
                ch_println( ch, "You learn from your failure at %s, growing from %d%% to %d%%", skill->name, prev_pct, new_pct );
                ch_println( ch, "You learn more from your failure at %s, and gain %d experience points.", skill->name, gain );
            }
        }

        gain_exp( ch, gain, skill->guild, TRUE );
    }
}

