// Applies diminishing returns on stuns by players to players.
void stun_dimreturns( CHAR_DATA* ch, CHAR_DATA* victim, int duration )
{
    // Only apply diminishing returns if the attacker and target are both players (or player-controlled)
    bool player_controlled_ch = !IS_NPC( ch ) || IS_AFFECTED( ch, AFF_CHARM ) || ( ch->master && !IS_NPC( ch->master ) );
    bool player_controlled_vch = !IS_NPC( victim ) || IS_AFFECTED( victim, AFF_CHARM ) || ( victim->master && !IS_NPC( victim->master ) );
    if ( player_controlled_ch && player_controlled_vch )
    {
        // Stun timer gets set to twice the duration of any applied stuns.
        // When we apply another stun, we drop its duration based on the duration of the timer.
        // If the timer is > 16, drop the stun by (timer-16)/32:
        // 1 person bashing constnatly:
        // 0:00: bashed: timer =  0, stun for 16, timer now set to 32
        // 0:16: bashed: timer = 16, stun for 16, timer now set to 48
        // 0:32: bashed: timer = 32, stun for  8, timer now set to 48 (and so on)

        // 1 person gouging constantly:
        // 0:00: gouged: timer =  0, stun for 8, timer now set to 16
        // 0:08: gouged: timer =  8, stun for 8, timer now set to 24
        // 0:16: gouged: timer = 16, stun for 8, timer now set to 32
        // 0:24: gouged: timer = 24, stun for 6, timer now set to 36
        // 0:32: gouged: timer = 28, stun for 5, timer now set to 38
        // 0:40: gouged: timer = 30, stun for 5, timer now set to 40
        // 0:48: gouged: timer = 32, stun for 4, timer now set to 40 (and so on)

        // So in effect, you can be stunlocked for 32 seconds straight, but then stuns become
        // increasingly ineffective, trending toward only stunning you for half the time your
        // attacker is stunned by using the skill.

        // Looking at this in a group combat context where more than one person might be bashing/gouging:
        // 2 people bashing constantly:
        // 0:00: bashed: timer =  0, stun for 16, timer now set to 32
        // 0:08: bashed: timer = 24, stun for 12, timer now set to 48
        // 0:16: bashed: timer = 40, stun for  4, timer now set to 48
        // 0:24: bashed: timer = 40, stun for  4, timer now set to 48 (and so on)
        // Stunlocked for 20 seconds before diminishing returns kick in.

        // 3 people bashing constantly:
        // 0:00: bashed: timer =  0, stun for 16, timer now set to 32
        // 0:04: bashed: timer = 28, stun for 10, timer now set to 48
        // 0:08: bashed: timer = 44, stun for  2, timer now set to 48
        // 0:16: bashed: timer = 40, stun for  4, timer now set to 48
        // 0:20: bashed: timer = 44, stun for  2, timer now set to 48
        // 0:24: bashed: timer = 44, stun for  2, timer now set to 48 (and so on)
        // Stunlocked for 20 seconds before diminishing returns kick in.

        // So you actually get stunned less than with a single person bashing you. That's OK.
        // Overstunning is now a mistake to avoid if you're in a group.

        sh_int stun_timer = get_timer( victim, TIMER_STUNNED );
        if ( stun_timer > 16 )
        {
            int orig_duration = duration;
            duration -= duration * (stun_timer-16) / 32;
            tune( "stun_dimreturns: dropping stun from %d to %d seconds on %s", orig_duration / PULSE_PER_SECOND, duration / PULSE_PER_SECOND, victim->name );
        }
        add_timer( victim, TIMER_STUNNED, stun_timer+(duration/PULSE_PER_SECOND)*2, NULL, NULL, FUNC );
    }
    WAIT_STATE( victim, duration );
}

CMDF do_gouge( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    sh_int dam;
    int percent;
    cache_skill( "gouge", &skill_gouge );
    SKILL_DATA* skill = skill_gouge;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !get_learned_pct( ch, skill ) )
    {
        ch_println( ch, "You do not yet know of this skill." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't get close enough while mounted." );
        return;
    }

    if ( ch->move <= 0 )
    {
        ch_println( ch, "You're too exhausted to do that!" );
        return;
    }

    if ( ( victim = who_fighting( ch ) ) == NULL )
    {
        ch_println( ch, "You aren't fighting anyone." );
        return;
    }

    // if ( !is_near( ch, victim ) )
    // {
    //     ch_println( ch, "Get closer first!" );
    //     return;
    // }

    // Assuming equal str/dex, chance equals your gouge skill - 10%
    percent = ( ( ( get_curr_dex( victim ) + get_curr_str( victim ) ) - ( get_curr_dex( ch ) + get_curr_str( ch ) ) ) * 5 ) + 10;

    // Full round of lag for the user. Always.
    WAIT_STATE( ch, PULSE_VIOLENCE );

    // Removed reduction in chance against players now that we have diminishing returns.

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || ( number_percent ( ) + percent ) < get_learned_pct( ch, skill ) )
    {
        dam = number_range( 1, ch->skill_level[COMBAT_ABILITY] / 3 );
        global_retcode = damage( ch, victim, dam, skill->id );

        if ( global_retcode == rNONE )
        {
            stun_dimreturns( ch, victim, PULSE_VIOLENCE );
            /*  Taken out by request - put back in by Thoric
                This is how it was designed.  You'd be a tad stunned
                if someone gouged you in the eye.
            */
        }
        else if ( global_retcode == rVICT_DIED )
        {
            act( AT_BLOOD, "Your fingers plunge into your victim's brain, causing immediate death!",
                 ch, NULL, NULL, TO_CHAR );
        }

        if ( global_retcode != rCHAR_DIED && global_retcode != rBOTH_DIED )
            learn_from_success( ch, skill );
    }
    else
    {
        global_retcode = damage( ch, victim, 0, skill->id );
        learn_from_failure( ch, skill );
    }

    return;
}

int get_stealth_bonus( CHAR_DATA *ch ) {
    int bonus = 0;
    //first let's consider their class
    switch(ch->main_ability) {
        case ESPIONAGE_ABILITY:
        case SMUGGLING_ABILITY:
            // they have proficiency, let's give them 5 points at level 150
            bonus += (ch->skill_level[ch->main_ability] / 30);
            break;
    }

    // add a raw bonus for their dex
    bonus += ch->perm_dex / 2;

    return bonus;
}

int get_perception_bonus( CHAR_DATA *ch ) {
    int bonus = 0;
    //first let's consider their class
    switch(ch->main_ability) {
        case SLICER_ABILITY:
        case SCIENCE_ABILITY:
        case HUNTING_ABILITY:
        case LEADERSHIP_ABILITY:
            // they have proficiency, let's give them 5 points at level 150
            bonus += (ch->skill_level[ch->main_ability] / 30);
            break;
    }

    // bonus for their raw wis
    bonus += ch->perm_wis / 2;

    return bonus;
}

// array of strings of commands that can be used with do_stealthily
// in the future, change this structure so we can include modifiers as well
const char *stealthy_commands[] = {
    "drop", "east", "west", "north", "south",
    "northeast", "northwest", "southeast", "southwest", "up",
    "down", "get", "put", "give", "remove", "wear",
    "wield", "hold", "use", "enter", "exit", "open",
    "close", "lock", "unlock", "pick", "steal", "throw",
    "climb", "push", "dig",
    NULL // sentinel - always end with NULL
};

CMDF do_stealthily( CHAR_DATA* ch, char* argument )
{
    STEALTHY_DATA *stealthy;
    if(NULLSTR(argument)) {
        ch_println( ch, "You must specify what you are trying to do stealthily." );
        return;
    }

    tune("do_stealthily: %s is trying to do %s", ch->name, argument);
    // check if it is in the array of OK commands
    for(int i = 0; stealthy_commands[i] != NULL; i++) {
        if(!str_prefix(stealthy_commands[i], argument)) {
            // it is, let's do it
            CREATE(stealthy, STEALTHY_DATA, 1);
            stealthy->player_modifier = get_stealth_bonus(ch);
            stealthy->roll = number_range(1, 20);
            tune("do_stealthily: %s is trying to %s stealthily, roll is %d, modifier is %d", ch->name, argument, stealthy->roll, stealthy->player_modifier);
            LINK(stealthy, ch->first_stealthy, ch->last_stealthy, next_in_char, prev_in_char);
            interpret(ch, argument, false);
            WAIT_STATE(ch, 5);
            UNLINK(stealthy, ch->first_stealthy, ch->last_stealthy, next_in_char, prev_in_char);
            DISPOSE(stealthy);
            return;
        }
    }

    ch_println( ch, "You can't do that stealthily.");
    return;
}

int dig_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "&wYou stop digging...&D" );
    act( AT_PLAIN, "$n stops digging...", ch, NULL, NULL, TO_ROOM );
    return E_LOTJ_SUCCESS;
}

int dig_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    cache_skill( "dig", &skill_dig );
    SKILL_DATA* skill = skill_dig;
    if ( !skill ) return E_LOTJ_ASYNC_VALIDATION_FAILED;

    int chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 80 : get_learned_pct( ch, skill );

    /* dig out an EX_DIG exit... */
    char* argument = buffer->str1;
    if ( !NULLSTR( argument ) )
    {
        EXIT_DATA* pexit = find_door( ch, argument, TRUE );
        if ( pexit && xIS_SET( pexit->flags, EX_DIG ) && xIS_SET( pexit->flags, EX_CLOSED ) )
        {
            if ( number_percent() < chance )
            {
                xREMOVE_BIT( pexit->flags, EX_CLOSED );
                ch_println( ch, "&wYou dig open a passageway!&D" );
                act( AT_PLAIN, "$n digs open a passageway!", ch, NULL, NULL, TO_ROOM );
                learn_from_success( ch, skill );
                return E_LOTJ_SUCCESS;
            }
        }

        learn_from_failure( ch, skill );
        ch_println( ch, "&wYour dig did not discover any exit...&D" );
        act( AT_PLAIN, "$n's stops digging.", ch, NULL, NULL, TO_ROOM );
        return E_LOTJ_SUCCESS;
    }

    OBJ_DATA* obj = NULL;
    for ( obj = ch->in_room->first_content; obj; obj = obj->next_content )
        if ( IS_OBJ_STAT( obj, ITEM_BURIED ) && number_percent() < chance )
            break;

    if ( !obj )
    {
        ch_println( ch, "&wYour dig uncovered nothing.&D" );
        act( AT_PLAIN, "$n's stops digging.", ch, NULL, NULL, TO_ROOM );
        learn_from_failure( ch, skill );
        return E_LOTJ_SUCCESS;
    }

    separate_obj( obj );
    xREMOVE_BIT( obj->extra_flags, ITEM_BURIED );
    act( AT_SKILL, "Your dig uncovered $p!", ch, obj, NULL, TO_CHAR );
    act( AT_SKILL, "$n's dig uncovered $p!", ch, obj, NULL, TO_ROOM );
    learn_from_success( ch, skill );

    return E_LOTJ_SUCCESS;
}

CMDF do_dig( CHAR_DATA* ch, char* argument )
{
    cache_skill( "dig", &skill_dig );
    SKILL_DATA* skill = skill_dig;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )  && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "&wYou can't concentrate enough for that.&D" );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "&wYou can't do that while mounted.&D" );
        return;
    }

    /* not having a shovel makes it harder to succeed */
    /*                  ^~ How right you are.  -Orion */
    OBJ_DATA* shovel = get_obj_carried_of_type( ch, ITEM_SHOVEL );
    if ( !shovel )
    {
        ch_println( ch, "&wTo do any real digging you need some sort of shovel.&D" );
        return;
    }

    if ( ch->move <= 10 )
    {
        ch_println( ch, "You're too exhausted to do that!" );
        return;
    }

    if ( !NULLSTR( argument ) )
    {
        EXIT_DATA* pexit = find_door( ch, argument, TRUE );
        if ( pexit && !xIS_SET( pexit->flags, EX_DIG ) && !xIS_SET( pexit->flags, EX_CLOSED ) )
        {
            ch_println( ch, "&wThere is no need to dig out that exit.&D" );
            return;
        }
    }
    else
    {
        switch ( ch->in_room->sector_type )
        {
            case SECT_CITY:
            case SECT_INSIDE:
                ch_println( ch, "&wThe floor is too hard to dig through.&D" );
                return;

            case SECT_WATER_SWIM:
            case SECT_WATER_NOSWIM:
            case SECT_UNDERWATER:
                ch_println( ch, "&wYou cannot dig here.&D" );
                return;

            case SECT_AIR:
                ch_println( ch, "&wWhat?  In the air?!&D" );
                return;
        }
    }

    ch_println( ch, "&wYou begin digging...&D" );
    act( AT_PLAIN, "$n begins digging...", ch, NULL, NULL, TO_ROOM );
    action_set( ch, NULL, "is digging.", NULL, 0 );
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, UMIN( skill->beats / 10, 3 )*3, dig_complete, dig_abort, FUNC );
    timer->buffer->str1 = STRALLOC( argument );
}

int search_abort( CHAR_DATA* ch, UNUSED(BUFFER_DATA* buffer) )
{
    ch_println( ch, "You stop your search..." );
    return E_LOTJ_SUCCESS;
}

int search_complete( CHAR_DATA* ch, BUFFER_DATA* buffer )
{
    cache_skill( "search", &skill_search );
    OBJ_DATA* container = get_obj_from_buffer( buffer, "container" );
    int dir = buffer->num1;
    int chance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 80 : get_learned_pct( ch, skill_search );

    if ( dir != -1 )
    {
        EXIT_DATA* pexit = get_exit( ch->in_room, dir );
        if ( pexit && xIS_SET( pexit->flags, EX_SECRET ) && xIS_SET( pexit->flags, EX_xSEARCHABLE )
                && number_percent() < chance )
        {
            act( AT_SKILL, "Your search reveals the $d!", ch, NULL, pexit->keyword, TO_CHAR );
            act( AT_SKILL, "$n finds the $d!", ch, NULL, pexit->keyword, TO_ROOM );
            xREMOVE_BIT( pexit->flags, EX_SECRET );
            learn_from_success( ch, skill_search );
            return E_LOTJ_SUCCESS;
        }
    }

    OBJ_DATA* startobj = ch->in_room->first_content;
    if ( container )
        startobj = container->first_content;

    OBJ_DATA* obj = NULL;
    for ( obj = startobj; obj; obj = obj->next_content )
        if ( IS_OBJ_STAT( obj, ITEM_HIDDEN ) && number_percent() < chance )
            break;
    if ( obj )
    {
        separate_obj( obj );
        xREMOVE_BIT( obj->extra_flags, ITEM_HIDDEN );
        act( AT_SKILL, "Your search reveals $p!", ch, obj, NULL, TO_CHAR );
        act( AT_SKILL, "$n finds $p!", ch, obj, NULL, TO_ROOM );
        learn_from_success( ch, skill_search );
        return E_LOTJ_SUCCESS;
    }

    ch_println( ch, "You find nothing." );
    learn_from_failure( ch, skill_search );
    return E_LOTJ_SUCCESS;
}

CMDF do_search( CHAR_DATA* ch, char* argument )
{
    cache_skill( "search", &skill_search );
    SKILL_DATA* skill = skill_search;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    OBJ_DATA* container = NULL;
    int dir = -1;
    if ( !NULLSTR( argument ) )
    {
        dir = get_door( argument );
        if ( dir == -1 )
        {
            container = get_obj_here( ch, argument );
            if ( !container )
            {
                ch_println( ch, "You can't find that here." );
                return;
            }

            if ( container->item_type != ITEM_CONTAINER )
            {
                ch_println( ch, "You can't search in that!" );
                return;
            }

            if ( IS_SET( container->value[1], CONT_CLOSED ) )
            {
                ch_println( ch, "It is closed." );
                return;
            }
        }
    }

    ch_println( ch, "You begin your search..." );
    action_set( ch, NULL, "is searching for something.", NULL, 0 );
    TIMER* timer = add_timer( ch, TIMER_DO_FUN, UMIN( skill->beats / 10, 3 )*3, search_complete, search_abort, FUNC );
    if ( container )
        add_obj_to_buffer( timer->buffer, "container", container );
    timer->buffer->num1 = dir;
}

CMDF do_steal( CHAR_DATA* ch, char* argument )
{
    char buf[MSL], arg1[MIL], arg2[MIL];
    CHAR_DATA* victim, *mst;
    OBJ_DATA* obj, *obj_next;
    int percent, xp, chances = 0;
    argument = one_argument( argument, arg1 );
    argument = one_argument( argument, arg2 );
    cache_skill( "steal", &skill_steal );
    cache_skill( "thieves eye", &skill_thieves_eye );

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( arg1[0] == '\0' || arg2[0] == '\0' )
    {
        ch_println( ch, "&zSyntax: &Csteal <&wobject&C> <&wvictim&C>" );
        return;
    }

    if ( ch->spirit && !ch->manifest )
    {
        ch_println( ch, "Better manifest first." );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    if ( ( victim = get_char_room( ch, arg2 ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !victim->desc )
    {
        ch_println( ch, "Trying to steal from a linkdead player? Cheater." );
        snprintf( buf, MSL, "%s trying to steal from %s while linkdead.", ch->name, victim->name );
        write_to_log( FUNC, buf, sysdata.log_level, 72, FALSE );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "That's pointless." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is afk." );
        snprintf( buf, MSL, "%s trying to steal from %s while AFK.", ch->name, victim->name );
        write_to_log( FUNC, buf, sysdata.log_level, 72, FALSE );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( check_illegal_psteal( ch, victim ) )
    {
        ch_println( ch, "You can't steal from that player." );
        return;
    }

    do_stop( ch, "" );
    WAIT_STATE( ch, skill_steal->beats );
    chances = ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) ? 0 : ( int ) get_learned_pct( victim, skill_thieves_eye );

    if ( !IS_AWAKE( victim ) )
        chances = 0;

    /* masters of thieves eye get bigtime bonus */
    if ( chances > 0 && chances < 100 )
        learn_slow( victim, skill_thieves_eye, 3 );

    if ( chances < 100 )
        chances /= 5;

    if ( number_percent () <= chances )
    {
        ch_println( victim, "&wYou notice %s trying to steal from you!", g_name( ch, victim ) );
        ch_println( ch, "&wOops, you messed this one up!" );
        return;
    }

    percent  = number_percent( ) + ( IS_AWAKE( victim ) ? 10 : -50 )
               - ( get_curr_lck( ch ) - 15 ) + ( get_curr_lck( victim ) - 13 )
               + times_killed( ch, victim ) * 7;

    /* Nearly impossible to botch if the victim is sleeping */
    if ( victim->position <= POS_SLEEPING )
        percent = 20;

    if ( victim->position == POS_FIGHTING
            ||   percent > ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 90 : get_learned_pct( ch, skill_steal ) ) )
    {
        /*
            Failure.
        */
        ch_println( ch, "&wOops, you messed this one up!" );
        act( AT_ACTION, "&w$n tried to steal from you!\n", ch, NULL, victim, TO_VICT    );
        act( AT_ACTION, "&w$n tried to steal from $N.\n",  ch, NULL, victim, TO_NOTVICT );

        /* Log the attempted STEAL */
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        {
            snprintf( buf, MSL, "%s attempted to steal from %s, but failed.", ch->name, victim->name );
            log_string( buf );
        }

        learn_from_failure( ch, skill_steal );

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
        {
            /*  if ( legal_loot( ch ) )
                {
                global_retcode = multi_hit( victim, ch, TYPE_UNDEFINED );
                }
                else
                {*/
            /* log_string( buf ); */
            if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) )
            {
                if ( ( mst = ch->master ) == NULL )
                    return;
            }
            else
                mst = ch;

            if ( ( IS_NPC( mst ) || IS_SWITCHED_NPC( mst ) ) )
                return;

            /*}*/
        }

        return;
    }

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        add_kill( ch, victim );  /* makes it harder to steal from same char */

    if ( !str_cmp( arg1, "credits"  )
            ||   !str_cmp( arg1, "credit" )
            ||   !str_cmp( arg1, "money"  ) )
    {
        int amount;
        amount = ( int ) ( victim->gold * number_range( 1, 10 ) / 100 );

        if ( amount <= 0 )
        {
            ch_println( ch, "You couldn't get any credits." );
            learn_from_failure( ch, skill_steal );
            return;
        }

        cache_skill( "sticky fingers", &skill_sticky_fingers );
        if ( has_feat( ch, skill_sticky_fingers ) )
            amount = URANGE( amount, amount * 3 > victim->gold ? victim->gold : amount * 3, sysdata.maxgold - ( amount + ch->gold ) );

        if ( ch->gold + amount > sysdata.maxgold )
        {
            ch_println( ch, "You can't carry any more credits! Go deposit some." );
            return;
        }

        /* Log the attempted STEAL */
        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        {
            snprintf( buf, MSL, "%s attempted to steal credits from %s, and succeeded.", ch->name, victim->name );
            write_to_log( FUNC, buf, sysdata.log_level, 72, FALSE );
        }

        ch->gold     += amount;
        victim->gold -= amount;

        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
            sql_credits_log( ch->name, "do_steal", amount, FALSE );

        if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
            sql_credits_log( victim->name, "do_steal", amount * -1, FALSE );

        ch_println( ch, "Aha!  You got %d credits.", amount );
        learn_from_success( ch, skill_steal );

        if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        {
            xp = UMIN( amount * 10, ( exp_level( ch->skill_level[SMUGGLING_ABILITY] + 1 ) - exp_level( ch->skill_level[SMUGGLING_ABILITY] )  ) / 35  );
            xp = UMIN( xp, xp_compute( ch, victim ) );
            xp = apply_xp_sink( ch, xp, SMUGGLING_ABILITY );
            gain_exp( ch, xp, SMUGGLING_ABILITY, TRUE );
            ch_println( ch, "&WYou gain %ld smuggling experience!", xp );
        }

        return;
    }

    if ( ( obj = get_obj_carry( victim, arg1 ) ) == NULL )
    {
        if ( victim->position <= POS_SLEEPING )
        {
            if ( ( obj = get_obj_wear( victim, arg1 ) ) != NULL )
            {
                if ( ( obj_next = get_eq_char( victim, obj->wear_loc ) ) != obj )
                {
                    ch_println( ch, "They are wearing %s on top of %s.", obj_next->short_descr, obj->short_descr );
                    ch_println( ch, "You'll have to steal that first." );
                    learn_from_failure( ch, skill_steal );
                    return;
                }
                else if ( IS_OBJ_STAT( obj, ITEM_NOREMOVE ) )
                {
                    ch_println( ch, "You can't steal that." );
                    return;
                }
                else
                    unequip_char( victim, obj );
            }
        }

        ch_println( ch, "You can't seem to find it." );
        learn_from_failure( ch, skill_steal );
        return;
    }

    if ( !can_drop_obj( ch, obj )
            ||   IS_OBJ_STAT( obj, ITEM_INVENTORY )
            ||   IS_OBJ_STAT( obj, ITEM_PROTOTYPE )
            ||   IS_OBJ_STAT( obj, ITEM_NOREMOVE ) )
    {
        ch_println( ch, "You can't manage to pry it away." );
        learn_from_failure( ch, skill_steal );
        return;
    }

    // We've removed -- at least for now -- the limit on how many items a character can carry. Just focusing on weight. - Nield 08/31/2024
    /*
    if ( ch->carry_number + ( get_obj_number( obj ) / obj->count ) > can_carry_n( ch ) )
    {
        ch_println( ch, "You have your hands full." );
        learn_from_failure( ch, skill_steal );
        return;
    } */

    if ( ch->carry_weight + ( get_obj_weight( obj ) / obj->count ) > can_carry_w( ch ) )
    {
        ch_println( ch, "You can't carry that much weight." );
        learn_from_failure( ch, skill_steal );
        return;
    }

    /* Log the attempted STEAL */
    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
    {
        snprintf( buf, MSL, "%s attempted to steal from %s, and succeeded.", ch->name, victim->name );
        write_to_log( FUNC, buf, sysdata.log_level, 72, FALSE );
    }

    ch_println( ch, "You managed to steal it!" );
    learn_from_success( ch, skill_steal );

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
    {
        xp = UMIN( obj->cost * 10, ( exp_level( ch->skill_level[SMUGGLING_ABILITY] + 1 ) - exp_level( ch->skill_level[SMUGGLING_ABILITY] )  ) / 10  );
        xp = UMIN( xp, xp_compute( ch, victim ) );
        xp = apply_xp_sink( ch, xp, SMUGGLING_ABILITY );
        gain_exp( ch, xp, SMUGGLING_ABILITY, TRUE );
        ch_println( ch, "&WYou gain %ld smuggling experience!", xp );
    }

    separate_obj( obj );
    obj_from_char( obj );
    obj_to_char( obj, ch );
    return;
}

CMDF do_backstab( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    OBJ_DATA* obj;
    int percent;

    cache_skill( "backstab", &skill_backstab );
    SKILL_DATA* skill = skill_backstab;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't do that right now." );
        return;
    }

    one_argument( argument, arg );

    if ( ch->mount )
    {
        ch_println( ch, "You can't get close enough while mounted." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "Backstab whom?" );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( !pk_allow && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, no PKing right now." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
    {
        ch_println( ch, "&W&RYou are in a safezone. Make sure you are familiar with the rules stated in HELP SAFEZONE and are sure you are not breaking them.&w" );
    }

    if ( victim == ch )
    {
        ch_println( ch, "How can you sneak up on yourself?" );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
    {
        ch_println( ch, "That player is AFK." );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    /* Added stabbing weapon. -Narn */
    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL  //very similar ambiguous logic seen elsewhere, probably copied from here ~Miros
            ||   ( obj->value[3] != WEAPON_VIBRO_BLADE  && !wielding_claws( ch ) ) )
    {
        ch_println( ch, "You need to wield a stabbing weapon." );
        return;
    }

    if ( victim->fighting )
    {
        ch_println( ch, "You can't backstab someone who is in combat." );
        return;
    }

    /* Can backstab a char even if it's hurt as long as it's sleeping. -Narn */
    if ( victim->hit < victim->max_hit && IS_AWAKE( victim ) )
    {
        act( AT_PLAIN, "$N is hurt and suspicious...you can't sneak up.",
             ch, NULL, victim, TO_CHAR );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "&WYou're too far away! Use the &Capproach &Wcommand to get closer!" );
        return;
    }

    percent = number_percent( ) - ( get_curr_lck( ch ) - 14 )
              + ( get_curr_lck( victim ) - 13 );

    //bh focus bonus
    if ( valid_focus( ch, HUNTING_ABILITY ) )
        percent -= ( int )( percent * .2 );

    WAIT_STATE( ch, skill->beats );

    if ( !IS_AWAKE( victim )
            ||   ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
            ||   percent < get_learned_pct( ch, skill ) )
    {
        int hp_start = victim->hit;
        learn_from_success( ch, skill );
        global_retcode = multi_hit( ch, victim, skill->id );

        //Ralen - upgraded backstab to have a shot at wounding target's back
        if ( number_range( 1, 35 ) > get_curr_lck( victim )
                && ch->hit < hp_start ) // If their hp has dropped, that means our backstab didn't miss
        {
            ch_println( ch, "&RYou wound %s's back!", g_name( victim, ch ) );
            ch_println( victim, "&RYou have sustained an injury to your back!" );
            xSET_BIT( victim->w_wound, MED_BACK );
            make_bloodstain( victim );
        }
    }
    else
    {
        learn_from_failure( ch, skill );
        global_retcode = damage( ch, victim, 0, skill->id );
    }

    return;
}

CMDF do_rescue( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    int percent;
    cache_skill( "rescue", &skill_rescue );

    if ( IS_CONTROLLED( ch ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Crescue <&wvictim&C>" );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_BERSERK ) )
    {
        ch_println( ch, "You aren't thinking very clearly..." );
        return;
    }

    if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "You try and rescue yourself, but fail miserably." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    if ( get_timer( victim, TIMER_RECENT_RESCUE ) )
    {
        ch_println( ch, "They can't be rescued again yet." );
        return;
    }

    bool any_fighting = false;
    for ( CHAR_DATA* rch = victim->in_room->first_person; rch; rch = rch->next_in_room )
        if ( who_fighting( rch ) == victim )
            any_fighting = true;

    if ( !any_fighting && !who_fighting( victim ) )
    {
        ch_println( ch, "They are not fighting right now." );
        return;
    }

    if ( who_fighting( victim ) == ch )
    {
        ch_println( ch, "One would imagine THEY don't need your help." );
        return;
    }

    percent = number_percent( ) - ( get_curr_lck( ch ) - 14 ) - ( get_curr_lck( victim ) - 16 );
    WAIT_STATE( ch, skill_rescue->beats );

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && percent > get_learned_pct( ch, skill_rescue ) )
    {
        ch_println( ch, "You fail the rescue." );
        act( AT_SKILL, "$n tries to rescue you!", ch, NULL, victim, TO_VICT   );
        act( AT_SKILL, "$n tries to rescue $N!", ch, NULL, victim, TO_NOTVICT );
        learn_from_failure( ch, skill_rescue );
        return;
    }

    act( AT_SKILL, "You rescue $N!",  ch, NULL, victim, TO_CHAR    );
    act( AT_SKILL, "$n rescues you!", ch, NULL, victim, TO_VICT    );
    act( AT_SKILL, "$n moves in front of $N!",  ch, NULL, victim, TO_NOTVICT );

    learn_from_success( ch, skill_rescue );
    for ( CHAR_DATA* rch = victim->in_room->first_person; rch; rch = rch->next_in_room )
    {
        if ( rch == ch || rch == victim )
            continue;

        if ( who_fighting( rch ) == victim )
        {
            stop_fighting( rch, FALSE );
            set_fighting( rch, ch );
        }
    }

    stop_fighting( victim, FALSE );

    TIMER* rescue_timer = add_timer( victim, TIMER_RESCUED, 12, NULL, NULL, FUNC );
    rescue_timer->buffer->target = ch; // Who rescued them
    add_timer( victim, TIMER_RECENT_RESCUE, 24, NULL, NULL, "rescue_recent" );

    return;
}

CMDF do_kick( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    one_argument( argument, arg );
    CHAR_DATA* victim;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ch->move <= 40 )
    {
        ch_println( ch, "You're too exhausted to do that!" );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't kick while mounted." );
        return;
    }

    if ( !who_fighting(ch) )
    {
        ch_println( ch, "You can't kick when you aren't fighting." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        victim = who_fighting(ch);
    }
    else if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "How can you sneak up on yourself?" );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "Get closer first!" );
        return;
    }

    WAIT_STATE( ch, PULSE_VIOLENCE / 3 ); // 3 kicks per round
    ch->move -= 40;

    cache_skill( "kick", &skill_kick );
    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || number_percent( ) <= get_learned_pct( ch, skill_kick ) )
    {
        learn_from_success( ch, skill_kick );
        // Max damage of 125:
        // str*2 + dex*2 (max 100)
        int max_dam = get_curr_str(ch)*2 + get_curr_dex(ch)*2;
        // if str=25, +25 (max 125)
        if ( get_curr_str(ch) == 25 )
            max_dam += 25;
        // * (combat level / 1.5)%, which means 100% for morts at level 150.
        // min of 5 to help new characters out
        max_dam = UMAX(5, max_dam * ch->skill_level[COMBAT_ABILITY] / 150);

        int dmg = number_range(max_dam / 2, max_dam);

        global_retcode = damage( ch, victim, dmg, skill_kick->id );
    }
    else
    {
        learn_from_failure( ch, skill_kick );
        global_retcode = damage( ch, victim, 0, skill_kick->id );
    }

    return;
}

