CMDF do_bash( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    int chance;
    cache_skill( "bash", &skill_bash );
    SKILL_DATA* skill = skill_bash;
    SKILL_CHECK( skill );


    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) )
            &&  get_learned_pct( ch, skill ) <= 0  )
    {
        send_to_char(
            "Your mind races as you realize you have no idea how to do that.\n", ch );
        return;
    }

    if ( ch->move <= 0 )
    {
        ch_println( ch, "You're too exhausted to do that!" );
        return;
    }

    if ( ( victim = who_fighting( ch ) ) == NULL )
    {
        ch_println( ch, "You aren't fighting anyone." );
        return;
    }

    // chance here meaning: a higher number makes it less likely to succeed
    // both have 25 str/dex, this will be: ((25+25)-(25+25))*5+10 = 10
    // victim has 23 str/dex, attacker has 25, this will be: -10
    // victim has 25 str/dex, attacker has 23, this will be: 30
    // Assuming equal str/dex, chance is your bash skill - 20%
    chance = ( ( ( get_curr_dex( victim ) + get_curr_str( victim ) )
                 -   ( get_curr_dex( ch )     + get_curr_str( ch ) ) ) * 5 ) + 20;

    // Removed reduction in chance against players now that we have diminishing returns.

    WAIT_STATE( ch, skill->beats );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
            || ( number_percent( ) + chance ) < get_learned_pct( ch, skill ) )
    {
        act( AT_WHITE, "You slam into $N, sending $M reeling!", ch, NULL, victim, TO_CHAR );
        act( AT_YELLOW, "$n slams into you, sending you reeling!", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$n slams into $N, sending $M reeling!", ch, NULL, victim, TO_NOTVICT );        
        WAIT_STATE( ch, PULSE_VIOLENCE );
        stun_dimreturns( ch, victim, 2 * PULSE_VIOLENCE );
        global_retcode = damage( ch, victim, number_range( 1, ch->skill_level[COMBAT_ABILITY] / 3 ), skill->id );
        learn_from_success( ch, skill );
    }
    else
    {
        act( AT_WHITE, "You try to slam into $N, but miss and hurtle into a wall instead!", ch, NULL, victim, TO_CHAR );
        act( AT_YELLOW, "$n tries to slam into you, but you move out of the way.", ch, NULL, victim, TO_VICT );
        act( AT_ACTION, "$n tries to slam into $N, but misses and hurtles into a wall instead!", ch, NULL, victim, TO_NOTVICT );        
        WAIT_STATE( ch, 2 * PULSE_VIOLENCE );
        learn_from_failure( ch, skill );
    }

    return;
}

CMDF do_stun( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    AFFECT_DATA af;
    int chance;
    bool fail;
    cache_skill( "stun", &skill_stun );
    SKILL_DATA* skill = skill_stun;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) )
            &&  get_learned_pct( ch, skill ) <= 0  )
    {
        send_to_char(
            "Your mind races as you realize you have no idea how to do that.\n", ch );
        return;
    }

    if ( ( victim = who_fighting( ch ) ) == NULL )
    {
        ch_println( ch, "You aren't fighting anyone." );
        return;
    }

    if ( ch->move < 16 )
    {
        set_char_color( AT_SKILL, ch );
        ch_println( ch, "You are far too tired to do that." );
        return;     /* missing return fixed March 11/96 */
    }

    WAIT_STATE( ch, skill->beats );
    fail = FALSE;
    chance = ris_save( victim, ch->skill_level[COMBAT_ABILITY], RIS_PARALYSIS );

    if ( chance == 1000 )
        fail = TRUE;
    else
        fail = saves_para_petri( chance, victim );

    chance = ( ( ( get_curr_dex( victim ) + get_curr_str( victim ) )
                 -   ( get_curr_dex( ch )     + get_curr_str( ch ) ) ) * 10 ) + 10;

    /* harder for player to stun another player */
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        chance += sysdata.stun_plr_vs_plr;
    else
        chance += sysdata.stun_regular;

    if ( !fail
            && (  ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
                  || ( number_percent( ) + chance ) <= get_learned_pct( ch, skill ) ) )
    {
        learn_from_success( ch, skill );
        /*    DO *NOT* CHANGE!    -Thoric    */
        ch->move -= 15;
        WAIT_STATE( ch,     2 * PULSE_VIOLENCE );
        WAIT_STATE( victim, PULSE_VIOLENCE );
        act( AT_SKILL, "$N smashes into you, leaving you stunned!", victim, NULL, ch, TO_CHAR );
        act( AT_SKILL, "You smash into $N, leaving $M stunned!", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n smashes into $N, leaving $M stunned!", ch, NULL, victim, TO_NOTVICT );

        if ( !IS_AFFECTED( victim, AFF_PARALYSIS ) )
        {
            af.type      = skill->id;
            af.location  = APPLY_AC;
            af.modifier  = 20;
            af.duration  = 3;
            xCLEAR_BITS( af.bitvector );
            xSET_BIT( af.bitvector, AFF_PARALYSIS );
            affect_to_target( victim, CHAR_AFFECT, &af );
            update_pos( victim );
        }
    }
    else
    {
        WAIT_STATE( ch,     2 * PULSE_VIOLENCE );
        ch->move -= 5;
        learn_from_failure( ch, skill );
        act( AT_SKILL, "$N charges at you screaming, but you dodge out of the way.", victim, NULL, ch, TO_CHAR );
        act( AT_SKILL, "Your attempt to stun $N leaves you racing past $E as $e laughs.", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n charges screaming at $N, but keeps going right on past.", ch, NULL, victim, TO_NOTVICT );
    }

    return;
}

/*
    Disarm a creature.
    Caller must check for successful attack.
    Check for loyalty flag (weapon disarms to inventory) for pkillers -Blodkai
*/
void disarm( CHAR_DATA* ch, CHAR_DATA* victim )
{
    OBJ_DATA* obj, *tmpobj;
    cache_skill( "disarm", &skill_disarm );
    SKILL_DATA* skill = skill_disarm;

    if ( ( obj = get_eq_char( victim, WEAR_WIELD ) ) == NULL || wielding_claws( victim ) )
        return;

    if ( ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL
            &&     number_bits( 1 ) == 0 )
        obj = tmpobj;

    if ( get_eq_char( ch, WEAR_WIELD ) == NULL && number_bits( 1 ) == 0 )
    {
        learn_from_failure( ch, skill );
        return;
    }

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && !can_see_obj( ch, obj ) && number_bits( 1 ) == 0 )
    {
        learn_from_failure( ch, skill );
        return;
    }

    if ( check_grip( ch, victim ) )
    {
        learn_from_failure( ch, skill );
        return;
    }

    act( AT_SKILL, "$n DISARMS you!", ch, NULL, victim, TO_VICT    );
    act( AT_SKILL, "You disarm $N!",  ch, NULL, victim, TO_CHAR    );
    act( AT_SKILL, "$n disarms $N!",  ch, NULL, victim, TO_NOTVICT );
    learn_from_success( ch, skill );

    if ( obj == get_eq_char( victim, WEAR_WIELD )
            &&  ( tmpobj = get_eq_char( victim, WEAR_DUAL_WIELD ) ) != NULL )
        tmpobj->wear_loc = WEAR_WIELD;

    obj_from_char( obj );
    obj_to_room( obj, victim->in_room );
    return;
}

CMDF do_disarm( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    OBJ_DATA* obj;
    int percent;
    cache_skill( "disarm", &skill_disarm );
    SKILL_DATA* skill = skill_disarm;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && get_learned_pct( ch, skill ) <= 0  )
    {
        ch_println( ch, "You don't know how to disarm opponents." );
        return;
    }

    cache_skill( "advanced disarm", &skill_advanced_disarm );
    if ( get_eq_char( ch, WEAR_WIELD ) == NULL && !wielding_claws( ch ) && !has_feat( ch, skill_advanced_disarm ) )
    {
        ch_println( ch, "You must wield a weapon to disarm." );
        return;
    }

    if ( ch->move <= 0 )
    {
        ch_println( ch, "You're too exhausted to do that!" );
        return;
    }

    if ( ( victim = who_fighting( ch ) ) == NULL )
    {
        ch_println( ch, "You aren't fighting anyone." );
        return;
    }

    if ( wielding_claws( victim ) )
    {
        ch_println( ch, "Your cannot disarm dewclaws, they are a body part!" );
        return;
    }

    /*No disarm mob flag by Walldo 01nov09*/
    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && xIS_SET( victim->act, ACT_NODISARM ) )
    {
        ch_println( ch, "How do you expect to disarm that?" );
        return;
    }

    if ( ( obj = get_eq_char( victim, WEAR_WIELD ) ) == NULL )
    {
        ch_println( ch, "Your opponent is not wielding a weapon." );
        return;
    }

    if ( xIS_SET( obj->extra_flags, ITEM_NODISARM ) )
    {
        ch_println( ch, "Their weapon can't be disarmed." );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "You need to get closer!" );
        return;
    }

    WAIT_STATE( ch, skill->beats );
    percent = number_percent( ) + victim->skill_level[COMBAT_ABILITY] - ch->skill_level[COMBAT_ABILITY] - ( get_curr_lck( ch ) - 15 ) + ( get_curr_lck( victim ) - 15 );

    if ( !can_see_obj( ch, obj ) )
        percent += 10;

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || percent < get_learned_pct( ch, skill ) * 2 / 3 )
        disarm( ch, victim );
    else
    {
        ch_println( ch, "You failed." );
        learn_from_failure( ch, skill );
    }

    return;
}

/*
    Trip a creature.
    Caller must check for successful attack.
*/
void trip( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( IS_AFFECTED( victim, AFF_FLYING )
            ||   IS_AFFECTED( victim, AFF_FLOATING ) )
        return;

    if ( victim->mount )
    {
        if ( IS_AFFECTED( victim->mount, AFF_FLYING )
                ||   IS_AFFECTED( victim->mount, AFF_FLOATING ) )
            return;

        act( AT_SKILL, "$n trips your mount and you fall off!", ch, NULL, victim, TO_VICT    );
        act( AT_SKILL, "You trip $N's mount and $N falls off!", ch, NULL, victim, TO_CHAR    );
        act( AT_SKILL, "$n trips $N's mount and $N falls off!", ch, NULL, victim, TO_NOTVICT );
        xREMOVE_BIT( victim->mount->act, ACT_MOUNTED );
        victim->mount = NULL;
        WAIT_STATE( ch,     2 * PULSE_VIOLENCE );
        WAIT_STATE( victim, 2 * PULSE_VIOLENCE );
        victim->position = POS_RESTING;
        return;
    }

    if ( victim->wait == 0 )
    {
        act( AT_SKILL, "$n trips you and you go down!", ch, NULL, victim, TO_VICT    );
        act( AT_SKILL, "You trip $N and $N goes down!", ch, NULL, victim, TO_CHAR    );
        act( AT_SKILL, "$n trips $N and $N goes down!", ch, NULL, victim, TO_NOTVICT );
        WAIT_STATE( ch,     2 * PULSE_VIOLENCE );
        WAIT_STATE( victim, 2 * PULSE_VIOLENCE );
        victim->position = POS_RESTING;
    }

    return;
}

CMDF do_pick( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* gch;
    OBJ_DATA* obj;
    EXIT_DATA* pexit;
    SHIP_DATA* ship;
    DB_DATA* wnted = NULL;
    PLANET_DATA* planet = NULL;
    bool clan_authed;
    cache_skill( "pick ship lock", &skill_pick_ship_lock );

    if ( !ch->in_room )
        return;

    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "&zSyntax: &Cpick <&wdirection/object/ship&C>" );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    planet = get_planet_from_room( ch->in_room );

    clan_authed = ( planet && planet->governed_by && ch->pcdata && ch->pcdata->clan && ch->pcdata->clan == planet->governed_by ) ? true : false;

    WAIT_STATE( ch, skill_pick_ship_lock->beats );

    /* look for guards */
    if ( !clan_authed )
    {
        for ( gch = ch->in_room->first_person; gch; gch = gch->next_in_room )
        {
            if ( IS_NPC( gch ) && IS_AWAKE( gch ) && ch->skill_level[SMUGGLING_ABILITY] < gch->top_level && gch->leader != ch )
            {
                act( AT_PLAIN, "$N is standing too close to the lock.", ch, NULL, gch, TO_CHAR );
                return;
            }
        }
    }


    if ( ( pexit = find_door( ch, arg, TRUE ) ) != NULL )
    {
        /* 'pick door' */
        /*  ROOM_INDEX_DATA *to_room; */ /* Unused */
        EXIT_DATA* pexit_rev;

        if ( !xIS_SET( pexit->flags, EX_CLOSED ) )
        {
            ch_println( ch, "It's not closed." );
            return;
        }

        if ( xIS_SET( pexit->flags, EX_KEYPAD ) )
        {
            ch_println( ch, "You can't pick a keypad lock." );
            return;
        }

        if ( pexit->key < 0 )
        {
            ch_println( ch, "It can't be picked." );
            return;
        }

        if ( xIS_SET( pexit->flags, EX_PICKPROOF ) )
        {
            ch_println( ch, "You failed." );
            learn_from_failure( ch, skill_pick_ship_lock );
            check_room_for_traps( ch, TRAP_PICK | trap_door[pexit->vdir] );
            return;
        }

        if ( !IS_NPC( ch ) && number_percent( ) > get_learned_pct( ch, skill_pick_ship_lock ) )
        {
            ch_println( ch, "You failed." );
            learn_from_failure( ch, skill_pick_ship_lock );
            return;
        }

        xTOGGLE_BIT( pexit->flags, EX_LOCKED );
        ch_println( ch, "*Click*" );
        act( AT_ACTION, "$n picks the $d.", ch, NULL, pexit->keyword, TO_ROOM );
        learn_from_success( ch, skill_pick_ship_lock );

        /* pick the other side */
        if ( ( pexit_rev = pexit->rexit ) != NULL
                &&   pexit_rev->to_room == ch->in_room )
        {
            xTOGGLE_BIT( pexit_rev->flags, EX_LOCKED );
        }

        check_room_for_traps( ch, TRAP_PICK | trap_door[pexit->vdir] );
        return;
    }

    if ( ( obj = get_obj_here( ch, arg ) ) != NULL )
    {
        if ( obj->item_type != ITEM_CONTAINER )
        {
            ch_println( ch, "You can't pick that." );
            return;
        }

        if ( !IS_SET( obj->value[1], CONT_CLOSED ) )
        {
            ch_println( ch, "It's not closed." );
            return;
        }

        if ( obj->value[2] < 0 )
        {
            ch_println( ch, "It can't be unlocked." );
            return;
        }

        /* if ( !IS_SET(obj->value[1], CONT_LOCKED) ) { ch_println( ch, "It's already unlocked." ); return; } */

        if ( IS_SET( obj->value[1], CONT_PICKPROOF ) )
        {
            ch_println( ch, "You failed." );
            learn_from_failure( ch, skill_pick_ship_lock );
            check_for_trap( ch, obj, TRAP_PICK );
            return;
        }

        if ( !IS_NPC( ch ) && number_percent( ) > get_learned_pct( ch, skill_pick_ship_lock ) )
        {
            ch_println( ch, "You failed." );
            learn_from_failure( ch, skill_pick_ship_lock );
            return;
        }

        separate_obj( obj );
        TOGGLE_BIT( obj->value[1], CONT_LOCKED );
        ch_println( ch, "*Click*" );
        act( AT_ACTION, "$n picks $p.", ch, obj, NULL, TO_ROOM );
        learn_from_success( ch, skill_pick_ship_lock );
        check_for_trap( ch, obj, TRAP_PICK );
        return;
    }

    if ( ( ship = ship_in_room( ch->in_room, arg ) ) != NULL )
    {
        /* char buf[MSL]; */
        ROOM_INDEX_DATA* room;
        CHAR_DATA* rch, *rnext;
        int chance = 0, cnt = 0;
        bool yelled = FALSE;

        if ( ship->hatchopen )
        {
            ch_println( ch, "&RIt's already open." );
            return;
        }

        // Ralen - giving pick ship lock the same functionality as doorcut/breach.
        // if ( ship->shipstate != SHIP_DOCKED && ship->shipstate != SHIP_DISABLED && ship->shipstate != SHIP_PERM_DISABLED )
        // {
        //     send_to_char( "&RThat ship has already started to launch!",ch);
        //     return;
        // }
        if ( xIS_SET( ship->flags, SHIP_TRAFFIC ) )
        {
            ch_println( ch, "You cannot pick into that ship." );
            return;
        }

        if ( ( ship->shipstate == SHIP_HOVER || ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH ) && !IS_AFFECTED( ch, AFF_FLYING ) )
        {
            ch_println( ch, "&RThe ship is hovering, you need to fly up to the hatch!" );
            return;
        }

        if ( ship->shipstate == SHIP_HOVERLAND || ship->shipstate == SHIP_HOVERLAUNCH )
        {
            ch_println( ch, "&RThe ship is maneuvering too fast for you to approach! Wait for it to reach a stable hover!" );
            return;
        }

        if ( ship->shipstate == SHIP_LAUNCH  )
        {
            obj = get_eq_char( ch, WEAR_BACK );

            if ( obj == NULL || !IS_AFFECTED( ch, AFF_FLYING ) ) //If you aren't flying at all, you can't pick the lock.
            {
                ch_println( ch, "&RThat ship is too high in the air for you to reach!&w" );
                return;
            }
            else if ( obj != NULL && obj->item_type != ITEM_JETPACK && IS_AFFECTED( ch, AFF_FLYING ) ) //Forcers force jumping can't hover, they just jump. Not really meeting the conditions here.
            {
                ch_println( ch, "&RThat ship is maneuvering too much for you to keep pace!&w" );
                return;
            }
        }

        if ( xIS_SET( ship->flags, SHIP_VONG ) )
            act( AT_PLAIN, "$n gently tickles the sealed hatch membrane on $T.", ch, NULL, ship->name, TO_ROOM );
        else
            act( AT_PLAIN, "$n fiddles with the hatch on $T.", ch, NULL, ship->name, TO_ROOM );

        WAIT_STATE( ch, skill_pick_ship_lock->beats );
        room = get_room_index( ship->location );
        chance = IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, skill_pick_ship_lock );

        /* Chance modifiers. Yaaay! */
        if ( ship->classtype == FIGHTER_SHIP )
            chance -= 0;

        if ( ship->classtype == TRANSPORT_SHIP )
            chance -= 10;

        if ( ship->classtype == FREIGHTER_SHIP )
            chance -= 20;

        if ( ship->classtype == GUNBOAT_SHIP )
            chance -= 30;

        if ( ship->classtype == CORVETTE_SHIP )
            chance -= 40;

        if ( ship->classtype == FRIGATE_SHIP )
            chance -= 50;

        /*
            Hell, Add the guards and witnesses into this too!
            (5% penalty for each person in the room)
        */
        for ( rch = room->first_person; rch; rch = rch->next_in_room )
            if ( rch != ch && IS_AWAKE( rch ) && can_see( rch, ch ) )
                cnt++;

        chance -= ( cnt * 5 );

        if ( number_percent( ) > chance )
        {
            ch_println( ch, "You failed to pick the lock." );
            learn_from_failure( ch, skill_pick_ship_lock );

            /*
                Its time for a bloodbath! -Ghost
            */
            if ( !clan_authed )
            {
                for ( rch = room->first_person; rch; rch = rnext )
                {
                    rnext = rch->next_in_room;

                    if ( rch == ch
                            || !IS_NPC( rch )
                            || !IS_AWAKE( rch )
                            || !can_see( rch, ch )
                            || xIS_SET( rch->act, ACT_NOASSIST )
                            || xIS_SET( rch->act, ACT_SAFE )
                            || xIS_SET( rch->act, ACT_ANIMAL )
                            || rch->leader == ch )
                        continue;

                    if ( number_range( 1, 30 ) > rch->perm_int )
                        continue;

                    if ( !yelled )
                    {
                        yelled = TRUE;
                        do_yell( rch, "Someone is breaking into ships here!" );
                    }

                    if ( ch->in_room && ch->in_room->area && ch->in_room->area->planet )
                    {
                        wnted = set_wanted( ch->name, ch->in_room->area->planet->name, TRUE, CRIME_BREAK_AND_ENTER );

                        if ( wnted->num1 == TRUE )
                        {
                            ch_println( ch, "&YYou are now wanted for breaking and entering on %s.", ch->in_room->area->planet->name );
                        }
                    }

                    multi_hit( rch, ch, TYPE_UNDEFINED );
                }
            }

            return;
        }

        if ( !ship->hatchopen )
        {
            ship->hatchopen = TRUE;
            ship->hatchtimer = 30;

            if ( xIS_SET( ship->flags, SHIP_VONG ) )
            {
                act( AT_PLAIN, "You tickle the hatch membrane on $T and it recoils, opening involuntarily.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "The hatch membrane on $T recoils and opens involuntarily.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch membrane opens suddenly." );
            }
            else
            {
                act( AT_PLAIN, "You pick the lock and open the hatch on $T.", ch, NULL, ship->name, TO_CHAR );
                act( AT_PLAIN, "$n opens the hatch on $T.", ch, NULL, ship->name, TO_ROOM );
                echo_to_room( AT_YELLOW, get_room_index( ship->entrance ), "The hatch opens from the outside." );
            }

            if ( ship->shipstate == SHIP_LAUNCH )
            {
                echo_to_ship_windows( AT_YELLOW, ship, "WARNING: HATCH INTEGRITY COMPROMISED." );
            }

            learn_from_success( ch, skill_pick_ship_lock );
        }

        /*
            Just when you thought you pulled it off...
        */
        if ( !clan_authed )
        {
            for ( rch = room->first_person; rch; rch = rnext )
            {
                rnext = rch->next_in_room;

                if ( rch == ch
                        || !IS_NPC( rch )
                        || !IS_AWAKE( rch )
                        || !can_see( rch, ch )
                        || xIS_SET( rch->act, ACT_NOASSIST )
                        || xIS_SET( rch->act, ACT_SAFE )
                        || xIS_SET( rch->act, ACT_ANIMAL )
                        || rch->leader == ch )
                    continue;

                if ( number_range( 1, 40 ) > rch->perm_int )
                    continue;

                if ( !yelled )
                {
                    yelled = TRUE;
                    do_yell( rch, "You thief!" );
                }

                multi_hit( rch, ch, TYPE_UNDEFINED );
            }
        }

        return;
    }

    ch_println( ch, "You see no %s here.", arg );
    return;
}

CMDF do_sneak( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    AFFECT_DATA af;
    cache_skill( "sneak", &skill_sneak );
    SKILL_DATA* skill = skill_sneak;
    SKILL_CHECK( skill );

    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_VISIBLE ) )
    {
        ch_println( ch, "You're unable to move quietly right now." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You can't do that while mounted." );
        return;
    }

    affect_strip( ch, CHAR_AFFECT, skill );

    if ( IS_NPC( ch ) || number_percent( ) <= get_learned_pct( ch, skill ) )
    {
        af.type      = skill->id;
        af.duration  = ch->skill_level[SMUGGLING_ABILITY]  * ( int )DUR_CONV;
        af.location  = APPLY_NONE;
        af.modifier  = 0;
        xCLEAR_BITS( af.bitvector );
        xSET_BIT( af.bitvector, AFF_SNEAK );
        affect_to_target( ch, CHAR_AFFECT, &af );
        learn_from_success( ch, skill );
        ch_println( ch, "&zYou are confident you could leave here without anyone noticing." );
    }
    else
    {
        learn_from_failure( ch, skill );
        ch_println( ch, "&RYou trip over your own feet!" );
    }

    return;
}

CMDF do_hide( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    cache_skill( "hide", &skill_hide );
    SKILL_DATA* skill = skill_hide;
    SKILL_CHECK( skill );

    if ( IS_NPC( ch ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "&RYou can't concentrate enough for that." );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "&RYou can't do that while mounted." );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_VISIBLE ) )
    {
        ch_println( ch, "You try to hide, but feel like you could still be seen easily." );
        return;
    }

    //GRAL Sneak maybe but hide no way when you are fighting.
    if ( ch->fighting )
    {
        ch_println( ch, "You're a tad distracted getting your ass kicked!" );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_HIDE ) )
        xREMOVE_BIT( ch->affected_by, AFF_HIDE );

    // VESKA No more hiding while blocking
    if ( ch->block != NULL )
    {
        ch_println( ch, "Hide? But you're standing right in the middle of the %s exit!", dir_name[ch->block->vdir] );
        return;
    }

    interpret( ch, "stop", FALSE ); //stop what you're doing, no sploits

    if ( IS_NPC( ch ) || number_percent( ) <= get_learned_pct( ch, skill ) )
    {
        xSET_BIT( ch->affected_by, AFF_HIDE );
        learn_from_success( ch, skill );
        ch_println( ch, "&zYou slip into the shadows." );
    }
    else
    {
        learn_from_failure( ch, skill );
        ch_println( ch, "&RYou try and blend in to your surroundings, but you realize you stick out like a Wookiee at a Jawa trade meet." );
    }

    WAIT_STATE( ch, 6 );
    return;
}

/* Contributed by Alander. */
CMDF do_visible( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* rch;
    cache_skill( "mask", &skill_mask );
    cache_skill( "sneak", &skill_sneak );
    cache_skill( "silent sneak", &skill_silent_sneak );

    if ( IS_AFFECTED( ch, AFF_HIDE ) || IS_AFFECTED( ch, AFF_INVISIBLE ) || IS_AFFECTED( ch, AFF_SNEAK ) )
    {
        // GRAL stop the steps out of shadows spam when people go afk or enter ships etc and they aren't affected.
        affect_strip( ch, CHAR_AFFECT, skill_mask );
        affect_strip( ch, CHAR_AFFECT, skill_sneak );
        xREMOVE_BIT   ( ch->affected_by, AFF_HIDE        );
        xREMOVE_BIT   ( ch->affected_by, AFF_INVISIBLE   );
        xREMOVE_BIT   ( ch->affected_by, AFF_SNEAK       );
        WAIT_STATE( ch, 1 * PULSE_PER_SECOND );
        // GRAL do we still want the wait?

        if ( str_cmp( argument, "-noalert" ) )
        {
            ch_println( ch, "&GYou step out of the shadows." );
        }
    }

    if ( !ch->in_room )
        return;

    if ( IS_AFFECTED( ch, AFF_HIDE ) || IS_AFFECTED( ch, AFF_INVISIBLE ) || ( IS_SNEAKING( ch ) && !has_feat( ch, skill_silent_sneak ) ) ) //If you have silent sneak and are sneaking but NOT hiding, don't show an echo. Otherwise, show an echo when hiding/sneaking.
    {
        if ( str_cmp( argument, "-noalert" )  )
        {
            ch_println( ch, "&GYou step out of the shadows." );
        }

        for ( rch = ch->in_room->first_person; rch; rch = rch->next_in_room )
        {
            if ( ch != rch && can_see( rch, ch ) && rch->position > POS_SLEEPING )
                ch_println( rch, "&zYou suddenly notice %s, standing nearby.", PERS( ch, rch ) );
        }
    }

    if ( IS_SNEAKING( ch ) && has_feat( ch, skill_silent_sneak ) )
    {
        ch_println( ch, "&GYou stop sneaking.&w" );
    }

    affect_strip( ch, CHAR_AFFECT, skill_mask );
    affect_strip( ch, CHAR_AFFECT, skill_sneak );
    xREMOVE_BIT   ( ch->affected_by, AFF_HIDE        );
    xREMOVE_BIT   ( ch->affected_by, AFF_INVISIBLE   );
    xREMOVE_BIT   ( ch->affected_by, AFF_SNEAK       );
    WAIT_STATE( ch, 1 * PULSE_PER_SECOND );
    return;
}

CMDF do_mount( CHAR_DATA* ch, char* argument )
{
    CHAR_DATA* victim;
    cache_skill( "mount", &skill_mount );

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) )
            &&   get_learned_pct( ch, skill_mount ) <= 0  )
    {
        send_to_char(
            "I don't think that would be a good idea...\n", ch );
        return;
    }

    if ( ch->mount )
    {
        ch_println( ch, "You're already mounted!" );
        return;
    }

    if ( ( victim = get_char_room( ch, argument ) ) == NULL )
    {
        ch_println( ch, "You can't find that here." );
        return;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) || !xIS_SET( victim->act, ACT_MOUNTABLE ) )
    {
        ch_println( ch, "You can't mount that!" );
        return;
    }

    if ( xIS_SET( victim->act, ACT_MOUNTED ) )
    {
        ch_println( ch, "That mount already has a rider." );
        return;
    }

    if ( victim->position < POS_STANDING )
    {
        ch_println( ch, "Your mount must be standing." );
        return;
    }

    if ( victim->position == POS_FIGHTING || victim->fighting )
    {
        ch_println( ch, "Your mount is moving around too much." );
        return;
    }

    WAIT_STATE( ch, skill_mount->beats );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || number_percent( ) <= get_learned_pct( ch, skill_mount ) )
    {
        stop_follower( victim, true );
        add_follower( victim, ch, true );
        xSET_BIT( victim->act, ACT_MOUNTED );
        ch->mount = victim;
        act( AT_SKILL, "You mount $N.", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n skillfully mounts $N.", ch, NULL, victim, TO_NOTVICT );
        act( AT_SKILL, "$n mounts you.", ch, NULL, victim, TO_VICT );
        learn_from_success( ch, skill_mount );
        ch->position = POS_MOUNTED;
        if ( !xIS_SET( victim->act, ACT_SENTINEL ) )
            xSET_BIT( victim->act, ACT_SENTINEL );
    }
    else
    {
        act( AT_SKILL, "You unsuccessfully try to mount $N.", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n unsuccessfully attempts to mount $N.", ch, NULL, victim, TO_NOTVICT );
        act( AT_SKILL, "$n tries to mount you.", ch, NULL, victim, TO_VICT );
        learn_from_failure( ch, skill_mount );
    }

    return;
}

CMDF do_dismount( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* victim;
    cache_skill( "mount", &skill_mount );

    if ( ( victim = ch->mount ) == NULL )
    {
        ch_println( ch, "You're not mounted." );
        if ( ch->position == POS_MOUNTED )
            ch->position = POS_STANDING;
        return;
    }

    WAIT_STATE( ch, skill_mount->beats );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) || number_percent( ) <= get_learned_pct( ch, skill_mount ) )
    {
        act( AT_SKILL, "You dismount $N.", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n skillfully dismounts $N.", ch, NULL, victim, TO_NOTVICT );
        act( AT_SKILL, "$n dismounts you.  Whew!", ch, NULL, victim, TO_VICT );
        learn_from_success( ch, skill_mount );
        ch->position = POS_STANDING;
    }
    else
    {
        act( AT_SKILL, "You fall off while dismounting $N.  Ouch!", ch, NULL, victim, TO_CHAR );
        act( AT_SKILL, "$n falls off of $N while dismounting.", ch, NULL, victim, TO_NOTVICT );
        act( AT_SKILL, "$n falls off your back.", ch, NULL, victim, TO_VICT );
        learn_from_failure( ch, skill_mount );
        ch->position = POS_SITTING;
        global_retcode = damage( ch, ch, 1, TYPE_UNDEFINED );
    }

    ch->mount = NULL;
    stop_follower( victim, true );
    xREMOVE_BIT( victim->act, ACT_MOUNTED );
    if ( xIS_SET( victim->act, ACT_SENTINEL ) && victim->pIndexData && !xIS_SET( victim->pIndexData->act, ACT_SENTINEL ) )
        xREMOVE_BIT( victim->act, ACT_SENTINEL );

    return;
}


