/*
    Check for parry.

    Modified by Orion

    THIS IS FOR LIGHTSABERS --==========

    Take the damage, and depending on the skill, rebound it back, and give
    it to the enemy, someone in the room, or take the damage.
*/
bool check_parry( CHAR_DATA* ch, CHAR_DATA* victim, int dam, OBJ_DATA* aweapon )
{
    CHAR_DATA* rch = NULL, *vch = NULL;
    char buf[MSL], buf2[MIL];
    int chances = 0, parrycode = -1, rebound = 0, ctb = 0;
    OBJ_DATA* wield = NULL, *ch_wield = NULL;
    bool found = FALSE;
    int modifier = 0; //Used for parry chance modifier. - Gathorn 14Jan2017
    cache_skill( "parry", &skill_parry );

    if ( !IS_AWAKE( victim ) )
        return FALSE;

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && !xIS_SET( victim->defenses, DFND_PARRY ) )
        return FALSE;

    if ( victim->move <= 0 )
    {
        ch_println( victim, "You're too exhausted to parry the attack!" );
        return FALSE;
    }

    /*  if ( ( IS_NPC(victim) || IS_SWITCHED_NPC(victim) ) )
        {
        chances = victim->top_level;
        if ( number_percent() < chances )
            return TRUE;
        return FALSE;
        }*/
    /*    bug("Ch: %s Victim: %s", ch->name, victim->name); */

    if ( ( wield = get_eq_char( victim, WEAR_WIELD ) ) == NULL )
        if ( ( wield = get_eq_char( victim, WEAR_DUAL_WIELD ) ) == NULL ||  wield->value[3] != WEAPON_LIGHTSABER )
            return FALSE;

    if ( check_parry_melee( victim, ch, wield ) )
        return TRUE;

    if ( wield->value[3] != WEAPON_LIGHTSABER )
        return FALSE;

    if ( victim->pcdata && victim->pcdata->blood_toxicity >= 20 && number_percent() <= 25 )
    {
        ch_println( victim, "&YYou're too disoriented to parry the attack!" );
        return FALSE;
    }

    ch_wield = get_eq_char( ch, WEAR_WIELD );
    if ( ch_wield == NULL )
        ch_wield = get_eq_char( ch, WEAR_DUAL_WIELD );

    // Initial parry chance of <skill> * 50%
    chances =  ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) || has_pcflag( victim, PCFLAG_NO_SENSE ) ) ? 0 : ( get_learned_pct( victim, skill_parry ) / 2 );
    // Adjust parry chance based on target and attacker's force levels.
    chances += ( victim->skill_level[FORCE_ABILITY] / 2 );
    chances -= ( ch->skill_level[FORCE_ABILITY] / 5 );

    /*  bug("%s's modifier: -%d  %s's bonus: %d", ch->name, ch->skill_level[FORCE_ABILITY]/5,
        victim->name, victim->skill_level[FORCE_ABILITY]/2);
        bug("After force mods: %d, After Cap: %d", chances, chances>90?90:chances);*/
    if ( ( IS_GUARDIAN( victim ) || IS_JUGGERNAUT( victim ) ) && victim->pcdata->frank >= FRANK_KNIGHT ) //JEDI_GUARDIAN/SITH_JUGGERNAUT Knights and above now receives a +10% parry chance due to Jan 2017 subclass upgrade. - Gathorn 14Jan2017
    {
        modifier = chances / 10;
        chances += modifier;
        tune( "check_parry: %s receives JEDI_GUARDIAN parry bonus of %d against %s.", victim->name, modifier, ch->name );
    }

    chances = URANGE( 0, chances, 90 );

    if ( number_range( 1, 100 ) > chances )
    {
        tune( "check_parry: %s fails parry chance of %d against %s.", victim->name, chances, ch->name );
        learn_slow( victim, skill_parry, 4 );
        return FALSE;
    }

    tune( "check_parry: %s succeeds parry chance of %d against %s.", victim->name, chances, ch->name );
    /*
        if ( ( !IS_NPC(victim) && !IS_SWITCHED_NPC(victim) )
         && !has_pcflag( victim, PCFLAG_GAG ) )  SB
        act( AT_SKILL, "You parry $n's attack.",  ch, NULL, victim, TO_VICT    );

        if ( ( !IS_NPC(ch) && !IS_SWITCHED_NPC(ch) )
         && !has_pcflag( ch, PCFLAG_GAG ) )   SB
        act( AT_SKILL, "$N parries your attack.", ch, NULL, victim, TO_CHAR    );

        learn_from_success( victim, skill_parry );
        return TRUE;

    */ /* This is the old parry code. Wee. WEAK. */
    if ( dam < 1 )
    {
        bug( "check_parry - no damage passed." );
        return FALSE;
    }

    if ( aweapon == NULL )
        return TRUE;

    if ( aweapon->value[3] == WEAPON_LIGHTSABER && wield->value[3] == WEAPON_LIGHTSABER )
    {
        if ( check_parry_saber( victim, ch ) )
            return TRUE;
        else
            return FALSE;
    }

    switch ( aweapon->value[3] )
    {
        default:
            parrycode = -1;
            break;

        case WEAPON_BLASTER:
        case WEAPON_BOWCASTER: //Lydor '09.
            parrycode = 2;
            break;

        case WEAPON_LIGHTSABER:
            parrycode = 3;
            break;

        case WEAPON_FORCE_PIKE:
        case WEAPON_VIBRO_AXE:
        case WEAPON_VIBRO_BLADE:
            parrycode = 1;
            break;
    }

    if ( parrycode == 1 )
    {
        if ( !xIS_SET( aweapon->extra_flags, ITEM_CORTOSIS ) )
        {
            if ( number_range( 1, 5 ) > 1 )
            {
                act( AT_ACTION, "Your lightsaber intercepts $N's weapon, damaging it!", victim, NULL, ch, TO_CHAR );
                act( AT_ACTION, "$n's lightsaber intercepts $N's weapon, showering the area with sparks.", victim, NULL, ch, TO_NOTVICT );
                act( AT_ACTION, "$n's lightsaber intercepts your weapon, damaging the weapon!", victim, NULL, ch, TO_VICT );
                aweapon->value[0] = URANGE( 0, aweapon->value[0] - number_range( 4, 6 ), 100 );

                if ( aweapon->value[0] > 1 )
                {
                    act( AT_ACTION, "Your weapon is destroyed by $N's lightsaber!", ch, NULL, victim, TO_CHAR );
                    act( AT_ACTION, "$n's weapon is destroyed by $N's lightsaber!", ch, NULL, victim, TO_NOTVICT );
                    act( AT_ACTION, "$n's weapon is destroyed by your lightsaber!", ch, NULL, victim, TO_VICT );
                    separate_obj( aweapon );
                    make_scraps( aweapon );
                }

                learn_slow( victim, skill_parry, 3 );
                return TRUE;
            }
        }

        act( AT_ACTION, "Your weapon collides with $N's with a spark.", victim, NULL, ch, TO_CHAR );
        act( AT_ACTION, "$n's weapon collides with yours with a spark.", victim, NULL, ch, TO_VICT );
        act( AT_ACTION, "$n's weapon collides with $N's with a spark.", victim, NULL, ch, TO_NOTVICT );
        learn_slow( victim, skill_parry, 3 );
        return TRUE;
    }

    if ( parrycode != 2 )
        return TRUE;

    ctb = ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) || has_pcflag( victim, PCFLAG_NO_SENSE ) ) ? 0 : ( int ) get_learned_pct( victim, skill_parry );
    /* Master forcer parry bonus */
    ctb += UMAX( 1, ch->skill_level[FORCE_ABILITY] - 90 );
    /*bug("Ctb: %d", ctb); */
    ctb -= UMAX( 0, dam / 20 );

    /*bug("Ctb: %d", ctb); */
    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) )
        ctb -= UMAX( 0, ch->skill_level[COMBAT_ABILITY] / 30 );

    /*bug("Ctb: %d", ctb); */
    if ( number_percent() > ctb ) /* Redirected back at ch */
    {
        snprintf( buf2, MIL, "You intercept $N's %s bolt with your lightsaber, redirecting it back at $M!", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_CHAR );
        snprintf( buf2, MIL, "$n intercepts $N's %s bolt with $s lightsaber, redirecting it back at $M!", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_NOTVICT );
        snprintf( buf2, MIL, "$n intercepts your %s bolt with $s lightsaber, redirecting it back at you!", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_VICT );
        dam /= 3;
        dam = URANGE( 1, dam, 525 ); //Ralen '13 - changed damcap from 600 to 525 for lowest possible blaster-based damcap

        /* Someone forgot shields to absorb reflected shots! */
        if ( get_eq_char( ch, WEAR_SHIELD ) != NULL )
        {
            OBJ_DATA* tobj = get_eq_char( ch, WEAR_SHIELD );

            if ( tobj->item_type == ITEM_SHIELD && tobj->value[4] > 0 && tobj->value[3] != 0 )
            {
                tobj->value[4] = URANGE( 0, tobj->value[4] - dam, tobj->value[4] );
                act( AT_ACTION, "$n's energy shield shines brightly!", ch, NULL, NULL, TO_ROOM );
                snprintf( buf2, MIL, "Your energy shield flares as it intercepts a %s bolt.", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
                act( AT_ACTION, buf2, ch, NULL, NULL, TO_CHAR );
                dam = 0;

                if ( tobj->value[4] == 0 )
                {
                    ch_println( ch, "&CYour energy shield fizzles and dies!&w" );
                    act( AT_ACTION, "&C$n's energy shield fails!&w", ch, NULL, NULL, TO_ROOM );
                    tobj->value[3] = 0;
                }
            }

            debug( "Redirect damage - %d", dam );
            damage( victim, ch, dam, TYPE_UNDEFINED );
            learn_slow( victim, skill_parry, 3 );
            return TRUE;
        }
        else
        {
            debug( "Redirect damage - %d", dam );
            damage( victim, ch, dam, TYPE_UNDEFINED );
            learn_slow( victim, skill_parry, 3 );
            return TRUE;
        }
    }
    else /* Redirected, hitting either a person in the room, or nothing. */
    {
        for ( rch = ch->in_room->first_person ; rch ; rch = rch->next_in_room )
        {
            if ( rch == ch )
                continue;

            if ( rch == victim )
                continue;

            if ( rch->leader == victim )
                continue;

            if ( has_pcflag( rch, PCFLAG_AFK ) )
                continue;

            if ( IS_IMMORTAL( rch ) )
                continue;

            if ( number_range( 1, 20 ) > 10 )
            {
                found = TRUE;
                break;
            }
        }

        if ( ( found ) && victim->alignment < 0 )
        {
            snprintf( buf, MSL, "You redirect %s's %s bolt, and it flies into $N!", g_name( ch, victim ), ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
            act( AT_ACTION, buf, victim, NULL, rch, TO_CHAR );

            for ( vch = ch->in_room->first_person ; vch ; vch = vch->next_in_room )
            {
                if ( ( IS_NPC( vch ) || IS_SWITCHED_NPC( vch ) ) )
                    continue;

                if ( vch == rch )
                    continue;

                if ( vch == victim )
                    continue;

                if ( vch == ch )
                    continue;

                snprintf( buf, MSL, "%s redirects %s's %s bolt, and it flies into $N!", g_name( victim, vch ), g_name( ch, vch ), ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
                act( AT_ACTION, buf, vch, NULL, rch, TO_CHAR );
            }

            snprintf( buf, MSL, "$n redirects your %s bolt, and it flies into %s!", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster", g_name( rch, ch ) );
            act( AT_ACTION, buf, victim, NULL, ch, TO_VICT );
            snprintf( buf, MSL, "$N redirects %s's %s bolt, and it flies into you!", g_name( ch, rch ), ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
            act( AT_RED, buf, rch, NULL, victim, TO_CHAR );
            //Ralen - This doesn't check for the reboundee having parry, making for a massive bug.
            rebound = ( IS_NPC( rch ) || IS_SWITCHED_NPC( rch ) ) ? rch->top_level : ( int ) ( get_learned_pct( ch, skill_parry ) );
            wield = get_eq_char( rch, WEAR_DUAL_WIELD );

            if ( number_percent( ) <= rebound && wield && wield->value[3] == WEAPON_LIGHTSABER )
            {
                snprintf( buf, MSL, "You flick your lightsaber up to parry %s's %s bolt, rebounding it away.", g_name( ch, rch ), ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
                act( AT_RED, buf, rch, NULL, victim, TO_CHAR );
                snprintf( buf2, MIL, "$n quickly parries a deflected %s bolt, and it rebounds into the ground.", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
                act( AT_ACTION, buf2, rch, NULL, victim, TO_ROOM );
                bug( "Redirect damage: %d rebounded damage correctly parried.", dam );
                return TRUE;
            }

            damage( victim, rch, dam, TYPE_UNDEFINED );
            learn_slow( victim, skill_parry, 3 );
            return TRUE;
        }

        snprintf( buf2, MIL, "You redirect $N's %s bolt, and it rebounds into the ground.", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_CHAR );
        snprintf( buf2, MIL, "$n redirects $N's %s bolt, and it rebounds into the ground.", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_NOTVICT );
        snprintf( buf2, MIL, "$n redirects your %s bolt, and it rebounds into the ground.", ( ch_wield && ch_wield->value[3] == WEAPON_BOWCASTER ) ? "bowcaster" : "blaster" );
        act( AT_ACTION, buf2, victim, NULL, ch, TO_VICT );
        return TRUE;
    }
}
/*
    Check for dodge.
*/
bool check_dodge( CHAR_DATA* ch, CHAR_DATA* victim )
{
    int chances;

    if ( !IS_AWAKE( victim ) )
        return FALSE;

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && !xIS_SET( victim->defenses, DFND_DODGE ) )
        return FALSE;

    cache_skill( "senses", &skill_senses );
    cache_skill( "foresight", &skill_foresight );
    cache_skill( "dodge", &skill_dodge );
    cache_skill( "reflexes", &skill_reflexes );

    OBJ_DATA* armor = get_eq_char( victim, WEAR_ABOUT );
    // Allow attackers with the "senses" force skill to cancel out a successful dodge sometimes
    int senses_chance = 0;

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && ch->pcdata && !has_pcflag( ch, PCFLAG_NO_SENSE ) && get_learned_pct( ch, skill_senses ) > 0 )
        senses_chance = get_learned_pct( ch, skill_senses ) / 4;

    // If the target has foresight, we should see if they dodge this blow.
    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && victim->pcdata && !has_pcflag( victim, PCFLAG_NO_SENSE ) && get_learned_pct( victim, skill_foresight ) > 0 )
    {
        // Initial chance is <foresight percentage> * 40%
        chances = ( int ) get_learned_pct( victim, skill_foresight ) * 4 / 10;

        // Back wound decreases chance for foresight to kick in
        if ( xIS_SET( victim->w_wound, MED_BACK ) )
            chances /= 2;

        // Foresight doesn't help against vong.
        if ( xIS_SET( ch->race->flags, RFLAG_VONG ) )
            chances = 0;

        // Senses doesn't help against vong.
        if ( xIS_SET( victim->race->flags, RFLAG_VONG ) )
            senses_chance = 0;

        // Forcers on drugs will be dramatically less effective in combat.
        if ( victim->pcdata && victim->pcdata->blood_toxicity >= 20 && number_percent() <= 50 )
        {
            chances = 0;

            if ( number_range( 1, 3 ) == 3 ) // Just to cut down on spam.
                ch_println( victim, "&YYou're too disoriented to focus on your enemy's next attack." );
        }

        if ( armor && get_armor_type( armor ) >= 2 && number_percent() <= 50 )
        {
            chances = 0;

            if ( number_range( 1, 3 ) == 3 ) // Just to cut down on spam.
                act( AT_YELLOW, "&YYour foresight reveals $n's next move, but your armor makes you too clumsy to avoid it.", ch, NULL, victim, TO_VICT );
        }

        if ( number_percent() < chances )
        {
            if ( number_percent() < senses_chance )
            {
                if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !has_pcflag( ch, PCFLAG_GAG ) )
                    act( AT_SKILL, "$N tries to step out of the way, but you sense it early enough to react.", ch, NULL, victim, TO_CHAR );

                // They have a <skill percent remaining> chance to maybe improve senses, min 5% to help train apprentices
                if ( number_percent() <= UMAX( 100 - get_learned_pct( ch, skill_senses ), 5 ) )
                    learn_slow( ch, skill_senses, 3 );

                return FALSE;
            }

            if ( !has_pcflag( victim, PCFLAG_GAG ) )
                act( AT_SKILL, "Your foresight reveals $n's next move, and you step out of the way.", ch, NULL, victim, TO_VICT );

            if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !has_pcflag( ch, PCFLAG_GAG ) )
                act( AT_SKILL, "$N dodges your attack.", ch, NULL, victim, TO_CHAR    );

            // They have a <skill percent remaining> chance to maybe improve foresight, min 5% to help train apprentices
            if ( number_percent() <= UMAX( 100 - get_learned_pct( victim, skill_foresight ), 5 ) )
                learn_slow( victim, skill_foresight, 3 );

            return TRUE;
        }
    }

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        chances  = UMIN( 60, victim->top_level );
    else
        chances  = ( int ) ( get_learned_pct( victim, skill_dodge ) / 2 );

    OBJ_DATA* wielding = get_eq_char( victim, WEAR_WIELD );

    if ( has_feat( victim, skill_reflexes ) )
    {
        double reflexes_bonus = 0.30;

        if ( wielding && wielding->value[3] == WEAPON_LIGHTSABER )
        {
            // For balance, reflexes increases dodge by 10% for forcers with a lightsaber.
            reflexes_bonus = 0.10;
        }
        else if ( armor && get_armor_type( armor ) == 3 )
        {
            // Reflexes increases dodge by 15% when in heavy armor to make medium armor a better
            // choice for those with the feat.
            reflexes_bonus = 0.15;
        }

        int reflexes_plus = chances * reflexes_bonus;
        tune( "check_dodge: %s reflexes bonus against %s of %d", ch->name, victim->name, reflexes_plus );
        chances += reflexes_plus;
    }

    bool cat_spice_dodge = false;

    if ( chances > 0 && IS_AFFECTED( victim, AFF_MAG_CAT_SPICE ) && number_range( 1, 4 ) == 4 )
    {
        tune( "check_dodge: %s cat-spice bonus against %s", ch->name, victim->name );
        cat_spice_dodge = true;
    }

    if ( number_range( 1, 100 ) > chances && !cat_spice_dodge )
    {
        learn_from_failure( victim, skill_dodge );
        return FALSE;
    }

    if ( number_percent() < senses_chance )
    {
        if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !has_pcflag( ch, PCFLAG_GAG ) )
            act( AT_SKILL, "$N tries to dodge, but you sense it early enough to react.", ch, NULL, victim, TO_CHAR );

        // They have a <skill percent remaining> chance to maybe improve senses, min 5% to help train apprentices
        if ( number_percent() <= UMAX( 100 - get_learned_pct( ch, skill_senses ), 5 ) )
            learn_slow( ch, skill_senses, 3 );

        return FALSE;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && !has_pcflag( victim, PCFLAG_GAG ) )
    {
        if ( cat_spice_dodge )
            act( AT_SKILL, "$n seems to move in slow motion as you swerve away from $s attack.", ch, NULL, victim, TO_VICT );
        else
            act( AT_SKILL, "You dodge $n's attack.", ch, NULL, victim, TO_VICT );
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && !has_pcflag( ch, PCFLAG_GAG ) )
        act( AT_SKILL, "$N dodges your attack.", ch, NULL, victim, TO_CHAR );

    learn_from_success( victim, skill_dodge );
    return TRUE;
}

CMDF do_poison_weapon( CHAR_DATA* ch, char* argument )
{
    OBJ_DATA* obj;
    OBJ_DATA* pobj;
    OBJ_DATA* wobj;
    char      arg [ MIL ];
    int       percent;
    cache_skill( "poison weapon", &skill_poison_weapon );

    if ( !IS_NPC( ch )
            &&  get_learned_pct( ch, skill_poison_weapon ) <= 0  )
    {
        ch_println( ch, "What do you think you are, an assassin?" );
        return;
    }

    one_argument( argument, arg );

    if ( NULLSTR( arg ) )
    {
        ch_println( ch, "What are you trying to poison?" );
        return;
    }

    if ( ch->fighting )
    {
        ch_println( ch, "While you're fighting? Nice try." );
        return;
    }

    if ( ms_find_obj( ch ) )
        return;

    if ( !( obj = get_obj_carry( ch, arg ) ) )
    {
        ch_println( ch, "You do not have that weapon." );
        return;
    }

    if ( obj->item_type != ITEM_WEAPON )
    {
        ch_println( ch, "That item is not a weapon." );
        return;
    }

    if ( obj->value[3] == WEAPON_LIGHTSABER || obj->value[3] == WEAPON_BLASTER || obj->value[3] == WEAPON_BOWCASTER )
    {
        ch_println( ch, "That won't work on that type of weapon." );
        return;
    }

    if ( IS_OBJ_STAT( obj, ITEM_POISONED ) )
    {
        ch_println( ch, "That weapon is already poisoned." );
        return;
    }

    /* Now we have a valid weapon...check to see if we have the powder. */
    for ( pobj = ch->first_carrying; pobj; pobj = pobj->next_content )
    {
        if ( pobj->pIndexData->vnum == OBJ_VNUM_BLACK_POWDER )
            break;
    }

    if ( !pobj )
    {
        ch_println( ch, "You do not have a suitable poison." );
        return;
    }

    /* Okay, we have the powder...do we have water? */
    for ( wobj = ch->first_carrying; wobj; wobj = wobj->next_content )
    {
        if ( wobj->item_type == ITEM_DRINK_CON
                && wobj->value[1]  >  0
                && wobj->value[2]  == 0 )
            break;
    }

    if ( !wobj )
    {
        ch_println( ch, "You have no water to mix with the powder." );
        return;
    }

    /* And does the thief have steady enough hands? */
    if ( !IS_NPC( ch )
            &&  ( ch->pcdata->condition[COND_DRUNK] > 0 ) )
    {
        ch_println( ch, "Your hands aren't steady enough to properly mix the poison." );
        return;
    }

    WAIT_STATE( ch, skill_poison_weapon->beats );
    percent = ( number_percent( ) - get_curr_lck( ch ) - 14 );
    /* Check the skill percentage */
    separate_obj( pobj );
    separate_obj( wobj );

    if ( !IS_NPC( ch ) && percent > get_learned_pct( ch, skill_poison_weapon ) )
    {
        set_char_color( AT_RED, ch );
        ch_println( ch, "You failed and spill some on yourself. Ouch!" );
        set_char_color( AT_GREY, ch );
        damage( ch, ch, ch->skill_level[HUNTING_ABILITY], skill_poison_weapon->id );
        act( AT_RED, "$n spills a vial of poison all over themselves!", ch, NULL, NULL, TO_ROOM );
        extract_obj( pobj );
        extract_obj( wobj );
        learn_from_failure( ch, skill_poison_weapon );
        return;
    }

    separate_obj( obj );
    /* Well, I'm tired of waiting.  Are you? */
    act( AT_RED, "You mix $p in $P, creating a deadly poison!", ch, pobj, wobj, TO_CHAR );
    act( AT_RED, "$n mixes $p in $P, creating a deadly poison!", ch, pobj, wobj, TO_ROOM );
    act( AT_GREEN, "You pour the poison over $p, which glistens wickedly!", ch, obj, NULL, TO_CHAR  );
    act( AT_GREEN, "$n pours the poison over $p, which glistens wickedly!", ch, obj, NULL, TO_ROOM  );
    xSET_BIT( obj->extra_flags, ITEM_POISONED );
    obj->cost *= ch->skill_level[HUNTING_ABILITY] / 2;
    /* Set an object timer.  Don't want proliferation of poisoned weapons */
    obj->timer = 10 + ch->skill_level[HUNTING_ABILITY] ;

    if ( IS_OBJ_STAT( obj, ITEM_BLESS ) )
        obj->timer *= 2;

    if ( IS_OBJ_STAT( obj, ITEM_MAGIC ) )
        obj->timer *= 2;

    /* WHAT?  All of that, just for that one bit?  How lame. ;) */
    act( AT_BLUE, "The remainder of the poison eats through $p.", ch, wobj, NULL, TO_CHAR );
    act( AT_BLUE, "The remainder of the poison eats through $p.", ch, wobj, NULL, TO_ROOM );
    extract_obj( pobj );
    extract_obj( wobj );
    learn_from_success( ch, skill_poison_weapon );
    return;
}

bool check_grip( CHAR_DATA* ch, CHAR_DATA* victim )
{
    int chance;
    cache_skill( "grip", &skill_grip );

    /* GRAL add a force bonus? */
    if ( !IS_AWAKE( victim ) )
        return FALSE;

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) && !xIS_SET( victim->defenses, DFND_GRIP ) )
        return FALSE;

    if ( wielding_claws( victim ) )
        return TRUE;

    if ( ( IS_NPC( victim ) || IS_SWITCHED_NPC( victim ) ) )
        chance  = 45 + victim->top_level / 2; // Give mobs a higher base chance since their top_level is maxed at 100
    else
        chance  = ( int ) ( get_learned_pct( victim, skill_grip ) / 2 );

    /* Consider luck as a factor */
    chance += ( 2 * ( get_curr_lck( victim ) - 13 ) );

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) )
        chance += victim->skill_level[FORCE_ABILITY];

    if ( number_percent( ) >= chance + victim->top_level - ch->top_level )
    {
        learn_from_failure( victim, skill_grip );
        return FALSE;
    }

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && victim->skill_level[FORCE_ABILITY] > 1 )
        ch_println( victim, "The force helps you hold on to your weapon!" );

    act( AT_SKILL, "You evade $n's attempt to disarm you.", ch, NULL, victim, TO_VICT    );
    act( AT_SKILL, "$N holds $S weapon strongly, and is not disarmed.",
         ch, NULL, victim, TO_CHAR    );
    learn_from_success( victim, skill_grip );
    return TRUE;
}

CMDF do_circle( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];
    CHAR_DATA* victim;
    OBJ_DATA* obj;
    int percent;
    cache_skill( "circle", &skill_circle );
    SKILL_DATA* skill = skill_circle;
    SKILL_CHECK( skill );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) && IS_AFFECTED( ch, AFF_CHARM ) )
    {
        ch_println( ch, "You can't concentrate enough for that." );
        return;
    }

    one_argument( argument, arg );

    if ( ch->mount )
    {
        ch_println( ch, "You can't circle while mounted." );
        return;
    }

    if ( NULLSTR( arg ) )
    {
        if ( ch->fighting && ch->fighting->who )
            victim = ch->fighting->who;
        else
        {
            ch_println( ch, "Circle around whom?" );
            return;
        }
    }
    else if ( ( victim = get_char_room( ch, arg ) ) == NULL )
    {
        ch_println( ch, "They aren't here." );
        return;
    }

    if ( victim == ch )
    {
        ch_println( ch, "How can you sneak up on yourself?" );
        return;
    }

    if ( is_safe( ch, victim ) )
        return;

    if ( ( obj = get_eq_char( ch, WEAR_WIELD ) ) == NULL
            ||   ( obj->value[3] != WEAPON_VIBRO_BLADE && !wielding_claws( ch ) ) )
    {
        ch_println( ch, "You need to wield a stabbing weapon to do that." );
        return;
    }

    if ( !ch->fighting )
    {
        ch_println( ch, "You can't circle when you aren't fighting." );
        return;
    }

    if ( !victim->fighting )
    {
        ch_println( ch, "You can't circle around a person who is not fighting." );
        return;
    }

    if ( !is_near( ch, victim ) )
    {
        ch_println( ch, "Get closer!" );
        return;
    }

    /*  if ( victim->num_fighting < 2 )
        {
        act( AT_PLAIN, "You can't circle around them without a distraction.",
        ch, NULL, victim, TO_CHAR );
        return;
        }*/
    percent = number_percent( ) - ( get_curr_lck( ch ) - 16 )
              + ( get_curr_lck( victim ) - 13 );

    //bh focus bonus
    if ( valid_focus( ch, HUNTING_ABILITY ) )
        percent -= ( int )( percent * .2 );

    WAIT_STATE( ch, skill->beats );

    if ( percent < ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ( ch->skill_level[HUNTING_ABILITY]  * 1.5 ) : get_learned_pct( ch, skill ) ) )
    {
        learn_from_success( ch, skill );
        global_retcode = multi_hit( ch, victim, skill->id );
        WAIT_STATE( ch, 5 );
    }
    else
    {
        learn_from_failure( ch, skill );
        global_retcode = damage( ch, victim, 0, skill->id );
        WAIT_STATE( ch, 9 );
    }

    return;
}

/* Berserk and HitAll. -- Altrag */
CMDF do_berserk( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    sh_int percent;
    AFFECT_DATA af;
    cache_skill( "berserk", &skill_berserk );

    if ( !ch->fighting )
    {
        ch_println( ch, "But you aren't fighting!" );
        return;
    }

    if ( IS_AFFECTED( ch, AFF_BERSERK ) )
    {
        ch_println( ch, "Your rage is already at its peak!" );
        return;
    }

    percent = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 80 : get_learned_pct( ch, skill_berserk );
    WAIT_STATE( ch, skill_berserk->beats );

    if ( !chance( ch, percent ) )
    {
        ch_println( ch, "You couldn't build up enough rage." );
        learn_from_failure( ch, skill_berserk );
        return;
    }

    af.type = skill_berserk->id;
    /*  Hmmm.. 10-20 combat rounds at level 50.. good enough for most mobs,
        and if not they can always go berserk again.. shrug.. maybe even
        too high. -- Altrag */
    af.duration = number_range( ch->top_level / 5, ch->top_level * 2 / 5 );
    /*  Hmm.. you get stronger when yer really enraged.. mind over matter
        type thing.. */
    af.location = APPLY_STR;
    af.modifier = 1;
    xCLEAR_BITS( af.bitvector );
    xSET_BIT( af.bitvector, AFF_BERSERK );
    affect_to_target( ch, CHAR_AFFECT, &af );
    ch_println( ch, "You start to lose control.." );
    act( AT_PLAIN, "$n starts to go berserk!", ch, NULL, NULL, TO_ROOM );
    learn_from_success( ch, skill_berserk );
    return;
}

/* External ONE_HIT reference moved to global prototype in mud.h */
CMDF do_hitall( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    CHAR_DATA* vch;
    CHAR_DATA* vch_next;
    sh_int nvict = 0;
    sh_int nhit = 0;
    sh_int percent;
    cache_skill( "hitall", &skill_hitall );

    if ( !pk_allow && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "Sorry, no PKing right now." );
        return;
    }

    if ( ch->in_room && ch->in_room->area && ch->in_room->area->planet && xIS_SET( ch->in_room->area->planet->flags, PLANET_NOPVP ) )
    {
        ch_println( ch, "Sorry, this is a No PVP planet." );
        return;
    }

    if ( xIS_SET( ch->in_room->flags, ROOM_SAFEZONE ) )
    {
        ch_println( ch, "&R&r&W&RYou are in a safezone. Make sure you are familiar with the rules stated in &Yhelp safezone&R and are sure you are not breaking them..." );
    }

    if ( !ch->in_room->first_person )
    {
        ch_println( ch, "There's no one here!" );
        return;
    }

    do_stop( ch, "" );
    percent = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? 80 : get_learned_pct( ch, skill_hitall );

    for ( vch = ch->in_room->first_person; vch; vch = vch_next )
    {
        vch_next = vch->next_in_room;

        if ( is_same_group( ch, vch ) || !is_legal_kill( ch, vch ) ||
                !can_see( ch, vch ) || is_safe( ch, vch ) || has_pcflag( vch, PCFLAG_AFK ) )
            continue;

        if ( ++nvict > ch->skill_level[COMBAT_ABILITY]  / 5 )
            break;

        if ( chance( ch, percent ) )
        {
            nhit++;
            global_retcode = one_hit( ch, vch, TYPE_UNDEFINED );
        }
        else
            global_retcode = damage( ch, vch, 0, TYPE_UNDEFINED );

        /* Fireshield, etc. could kill ch too.. :>.. -- Altrag */
        if ( global_retcode == rCHAR_DIED || global_retcode == rBOTH_DIED || char_extracted( ch ) )
            return;
    }

    if ( !nvict )
    {
        ch_println( ch, "There's no one here!" );
        return;
    }

    ch->move = UMAX( 0, ch->move - nvict * 3 + nhit );

    if ( nhit )
        learn_from_success( ch, skill_hitall );
    else
        learn_from_failure( ch, skill_hitall );

    WAIT_STATE( ch, 4 );
    return;
}



bool check_illegal_psteal( CHAR_DATA* ch, CHAR_DATA* victim )
{
    if ( get_trust( victim ) > 100 && get_trust( ch ) < 103 )
        return TRUE;

    if ( ( !IS_NPC( victim ) && !IS_SWITCHED_NPC( victim ) ) && has_pcflag( victim, PCFLAG_AFK ) )
        return TRUE;

    return FALSE;
}

CMDF do_scan( CHAR_DATA* ch, char* argument )
{
    ROOM_INDEX_DATA* last_room;
    ROOM_INDEX_DATA* next_room;
    EXIT_DATA* pexit = NULL;
    OBJ_DATA* obj = NULL;
    sh_int dir = -1;
    sh_int dist;
    sh_int max_dist = 5;
    bool lightecho = FALSE;
    char buf[100];
    cache_skill( "scan", &skill_scan );

    if ( !check_blind( ch, FALSE ) )
        return;

    if ( !check_smoke( ch, FALSE ) )
        return;

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "Scan in a direction..." );
        return;
    }

    if ( ( dir = get_door( argument ) ) == -1 )
    {
        ch_println( ch, "Scan in WHAT direction?" );
        return;
    }

    last_room = ch->in_room;
    EXIT_DATA* blockexit = ch->block;
    char buf2[MSL];

    if ( blockexit != NULL )
    {
        snprintf( buf2, MSL, "is blocking the %s exit.", dir_name[blockexit->vdir] );
    }

    act( AT_GREY, "Scanning $t...", ch, dir_name[dir], NULL, TO_CHAR );
    act( AT_GREY, "$n scans $t.", ch, dir_name[dir], NULL, TO_ROOM );

    if ( ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) )
            || ( number_percent() > get_learned_pct( ch, skill_scan ) ) )
    {
        act( AT_GREY, "You stop scanning $t as your vision blurs.", ch,
             dir_name[dir], NULL, TO_CHAR );
        learn_from_failure( ch, skill_scan );
        return;
    }

    if ( ( pexit = get_exit( last_room, dir ) ) == NULL )
    {
        act( AT_GREY, "You can't see $t.", ch, dir_name[dir], NULL, TO_CHAR );
        return;
    }

    /* See if they have a flashlight, that's ON */
    obj = get_eq_char( ch, WEAR_LIGHT );

    if ( obj != NULL )
    {
        if ( obj->value[3] == 1 && obj->value[2] > 0 )
            lightecho = TRUE;
        else
            obj = NULL;
    }

    if ( ch->top_level < 50 )
        max_dist--;

    if ( ch->top_level < 20 )
        max_dist--;

    if ( IS_AFFECTED( ch, AFF_LONG_RANGE_SIGHT ) )
        max_dist *= 2;

    for ( dist = 1; dist <= max_dist; )
    {
        //lightecho = FALSE;

        if ( ( !xIS_SET( pexit->flags, EX_WINDOW) && xIS_SET( pexit->flags, EX_CLOSED ) ) ||
        ( xIS_SET( pexit->flags, EX_WINDOW ) && ( xIS_SET( pexit->flags, EX_CLOSED ) || xIS_SET( pexit->flags, EX_SEALED_WINDOW ) ) && xIS_SET( pexit->flags, EX_OPAQUE_WINDOW ) ) )
        {
            if ( xIS_SET( pexit->flags, EX_SECRET ) )
                act( AT_GREY, "Your view $t is blocked by a wall.", ch,
                     dir_name[dir], NULL, TO_CHAR );
            else if ( xIS_SET( pexit->flags, EX_WINDOW ) )
                act( AT_GREY, "Your view $t is blocked by a closed window.", ch,
                     dir_name[dir], NULL, TO_CHAR );            
            else
                act( AT_GREY, "Your view $t is blocked by a door.", ch,
                     dir_name[dir], NULL, TO_CHAR );

            break;
        }

        next_room = NULL;

        if ( pexit->distance > 1 )
            next_room = generate_exit( last_room, &pexit );

        if ( next_room == NULL )
            next_room = pexit->to_room;

        if ( room_is_private( ch, next_room ) && get_trust( ch ) < LEVEL_GREATER )
        {
            act( AT_GREY, "Your view $t is blocked by a private room.", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        if ( xIS_SET( next_room->affected_by, AFF_SMOKE ) )
        {
            act( AT_GREY, "Your view $t is blocked by a cloud of smoke.", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        if ( xIS_SET( next_room->flags, ROOM_SANDSTORM ) && get_trust( ch ) < LEVEL_GREATER )
        {
            act( AT_GREY, "&Y&OYour view $t is blocked by a swirling sandstorm.&w", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        if ( xIS_SET( next_room->flags, ROOM_SNOWSTORM ) && get_trust( ch ) < LEVEL_GREATER )
        {
            act( AT_WHITE, "&WYour view $t is blocked by a howling snowstorm!&w", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        if ( room_is_dark( next_room ) )
        {
            if ( dist > 1 )
            {
                if ( obj )
                    act( AT_GREY, "Your light cannot pierce the wall of darkness further.", ch, dir_name[dir], NULL, TO_CHAR );

                if ( !obj )
                    act( AT_GREY, "Your view $t is blocked by a wall of darkness.", ch, dir_name[dir], NULL, TO_CHAR );

                break;
            }
           // else
            //{
                /* Beam of light echo to target room */
              //  lightecho = TRUE;
            //}
        }

        set_char_color( AT_RMNAME, ch );
        send_to_char( next_room->name, ch );
        ch_println( ch, "" );

        if ( xIS_SET( next_room->affected_by, AFF_NAPALM ) )
            ch_println( ch, "&RThick flames are engulfing the room and its occupants!&w" );

        show_structs_to_char( next_room, ch );
        show_ships_to_char( next_room, ch );
        show_list_to_char( next_room->first_content, ch, FALSE, FALSE );
        show_chars_to_char( next_room, ch );

        SHIP_DATA* ship;

        if ( ( ship = get_ship_from_cockpit( next_room ) ) != NULL && ship->classtype <= FRIGATE_SHIP )
        {
            if ( ship->piloting && ship->piloting->in_room == next_room )
                ch_println( ch, "&z%s is holding the piloting controls.", g_name( ship->piloting, ch ) );
            else
                ch_println( ch, "&zNobody is holding the piloting controls." );
        }


        if ( lightecho )
        {
            snprintf( buf, 100, "A narrow beam of light sweeps the room from %s.", dir_name[rev_dir[dir]] );
            echo_to_room( AT_YELLOW, next_room, buf );
        }

        if ( xIS_SET( next_room->affected_by, AFF_NAPALM ) )
        {
            act( AT_YELLOW, "Your view $t is blocked by a wall of flames.", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        switch ( next_room->sector_type )
        {
            default:
                dist++;
                break;

            case SECT_AIR:
                if ( number_percent() < 80 )
                    dist++;

                break;

            case SECT_INSIDE:
            case SECT_FIELD:
            case SECT_UNDERGROUND:
                dist++;
                break;

            case SECT_FOREST:
            case SECT_CITY:
            case SECT_DESERT:
            case SECT_HILLS:
                dist += 2;
                break;

            case SECT_WATER_SWIM:
            case SECT_WATER_NOSWIM:
                dist += 3;
                break;

            case SECT_MOUNTAIN:
            case SECT_UNDERWATER:
            case SECT_OCEANFLOOR:
                dist += 4;
                break;
        }

        if ( dist >= max_dist )
        {
            act( AT_GREY, "Your vision blurs with distance and you see no "
                 "farther $t.", ch, dir_name[dir], NULL, TO_CHAR );
            break;
        }

        if ( ( pexit = get_exit( next_room, dir ) ) == NULL )
        {
            act( AT_GREY, "Your view $t is blocked by a wall.", ch,
                 dir_name[dir], NULL, TO_CHAR );
            break;
        }

        last_room = next_room;
    }

    if ( blockexit != NULL )
    {
        action_set_ex( ch, NULL, buf2, NULL, 0, AS_LOCK );
        ch->block = blockexit;
    }

    learn_from_success( ch, skill_scan );
}

