}

bool check_parry_saber( CHAR_DATA* ch, CHAR_DATA* attacker )
{
    OBJ_DATA* wep1 = NULL, *wep2 = NULL;
    int ptype = 0;
    int achance = 0, bchance = 0; //achance corresponds to defender, and bchance corresponds to attacker. They are compared against each other to determine parry chance.
    char buf[MIL], buf2[MIL], buf3[MIL];
    int modifier = 0; //Using this for TUNE statement additions. - Gathorn 14Jan2017

    if ( !ch || ch == NULL || !attacker || attacker == NULL )
        return FALSE;

    if ( ( wep1 = get_eq_char( ch, WEAR_WIELD ) ) == NULL || wep1->value[3] != WEAPON_LIGHTSABER )
        return FALSE;

    if ( ( wep2 = get_eq_char( attacker, WEAR_WIELD ) ) == NULL || wep2->value[3] != WEAPON_LIGHTSABER )
        return FALSE;

    achance = ( IS_NPC( ch ) || IS_SWITCHED_NPC( ch ) ) ? ch->top_level : what_prof( ch, wep1 );
    bchance = ( IS_NPC( attacker ) || IS_SWITCHED_NPC( attacker ) ) ? attacker->top_level : what_prof( attacker, wep2 );
    /*bug("Achance %d Bchance %d", achance, bchance); */
    achance = number_range( achance, achance * 2 ); //Another instance of number_range in URANGE! Not that it matters in this instance. -Gathorn 16Jan2015
    achance = URANGE( 0, achance, 100 );
    bchance = bchance / 2;

    /*bug("Achance %d Bchance %d", achance, bchance); */
    if ( handwound( ch ) )
        achance -= ( int )( handwound_count( ch ) * 5 );

    if ( ( IS_GUARDIAN( ch ) || IS_JUGGERNAUT( ch ) ) && ch->pcdata->frank >= FRANK_KNIGHT )
    {
        modifier = achance / 10;
        achance += modifier;
        tune( "check_parry_saber: %s parry chance against %s received jedi_guardian parry bonus of %d.", ch->name, attacker->name, modifier );
    }

    tune( "check_parry_saber: %s has defender parry chance of %d against %s's attacker chance of %d.", ch->name, achance, attacker->name, bchance );

    if ( achance < bchance )
    {
        if ( ch->lightsaber_form > 0 )
            learn_from_failure( ch, skill_from_lightsaber_form( ch->lightsaber_form ) );

        return FALSE;
    }

    ptype = number_range( 0, 6 );

    if ( ch->race && ch->race->size == 3 && ch->lightsaber_form == FORM_ATARU )
    {
        snprintf( buf, MIL, "%s", lightsaber_form_messages[FORM_ATARU].alt_parry_msg[ptype][0] );
        snprintf( buf2, MIL, "%s", lightsaber_form_messages[FORM_ATARU].alt_parry_msg[ptype][1] );
        snprintf( buf3, MIL, "%s", lightsaber_form_messages[FORM_ATARU].alt_parry_msg[ptype][2] );
    }
    else
    {
        snprintf( buf, MIL, "%s", lightsaber_form_messages[ch->lightsaber_form].parry_msg[ptype][0] );
        snprintf( buf2, MIL, "%s", lightsaber_form_messages[ch->lightsaber_form].parry_msg[ptype][1] );
        snprintf( buf3, MIL, "%s", lightsaber_form_messages[ch->lightsaber_form].parry_msg[ptype][2] );
    }

    act( AT_ACTION, buf, ch, NULL, attacker, TO_CHAR );
    act( AT_ACTION, buf2, ch, NULL, attacker, TO_NOTVICT );
    act( AT_ACTION, buf3, ch, NULL, attacker, TO_VICT );

    if ( ch->lightsaber_form > 0 )
        learn_from_success( ch, skill_from_lightsaber_form( ch->lightsaber_form ) );

    if ( ( ptype = number_range( 1, 7 ) ) == 4 || ptype == 6 )
    {
        ch_println( ch, "You press your advantage, trying for a counter-attack..." );
        ch_printf( attacker, "%s counter attacks...", g_name( ch, attacker ) );
        one_hit( ch, attacker, TYPE_UNDEFINED );
        return TRUE;
    }

    return TRUE;
}

bool has_feat( CHAR_DATA* ch, SKILL_DATA* feat )
{
    if ( !ch )
        return FALSE;

    if ( !feat )
    {
        bug( "%s: missing feat" );
        return FALSE;
    }

    if ( ( !IS_NPC( ch ) && !IS_SWITCHED_NPC( ch ) ) && get_learned_pct( ch, feat ) > 0 )
        return TRUE;
    else
        return FALSE;
}

SKILL_DATA* skill_from_id( int sn )
{
    SKILL_DATA* skill = NULL;
    bool rev = FALSE;

    if ( !first_skill )
        return NULL;

    if ( ( first_skill && sn < first_skill->id ) || ( last_skill && sn > last_skill->id ) )
        return NULL;

    // If the skill table doesn't exist, make it.
    if ( !skill_table && last_skill )
    {
        CREATE( skill_table, SKILL_DATA*, last_skill->id + 1 );
        for ( skill = first_skill; skill; skill = skill->next )
            skill_table[skill->id] = skill;
    }

    // If the skill table exists (which it should), just return the proper skill mapped to the array value.
    if ( skill_table )
        return skill_table[sn];

    // If for whatever reason the skill table doesn't exist, find it the old fashioned way.
    // Figure out if it's more efficient to start from the beginning or the end of the linked list...
    if ( last_skill && last_skill != first_skill && last_skill->id > 100 && sn > ( last_skill->id / 2 ) )
        rev = TRUE;

    // ... and go find that skill (if it exists).
    for ( skill = rev ? last_skill : first_skill; skill; skill = rev ? skill->prev : skill->next )
        if ( skill->id == sn )
            return skill;

    return NULL;
}

SKILL_DATA* skill_from_name( const char* name )
{
    SKILL_DATA* skill = NULL;
    int hash = 0;

    if ( NULLSTR( name ) )
        return NULL;

    if ( !str_prefix( "mpdonothing", name ) )
        return NULL;

    char c = LOWER( name[0] );

    if ( c < 'a' || c > 'z' )
        hash = 0;
    else
        hash = ( c - 'a' ) + 1;

    for ( skill = skill_index[hash]; skill; skill = skill->next_hash )
        if ( !str_cmp( name, skill->name ) )
            return skill;

    for ( skill = skill_index[hash]; skill; skill = skill->next_hash )
        if ( !str_prefix( name, skill->name ) )
            return skill;

    return NULL;
}

int extract_learned( CHAR_DATA* ch, LEARNED_DATA* learned )
{
    if ( !ch || !learned )
        return E_LOTJ_NOTHING_TO_DO;

    UNLINK( learned, ch->first_learned, ch->last_learned, next, prev );
    FREE_STRUCT( learned, learned_fields );
    return E_LOTJ_SUCCESS;
}

LEARNED_DATA* add_learned( CHAR_DATA* ch, SKILL_DATA* skill )
{
    LEARNED_DATA* learned = NULL;

    if ( !ch || !skill )
        return NULL;

    CREATE( learned, LEARNED_DATA, 1 );
    learned->id = skill->id;
    SET_STRING( learned->name, skill->name );
    learned->pct = 0;
    learned->skill = skill;
    LINK_SORT_NUM( learned, LEARNED_DATA, ch->first_learned, ch->last_learned, next, prev, id );
    save_char_obj( ch, true );
    return learned;
}

LEARNED_DATA* get_learned( CHAR_DATA* ch, SKILL_DATA* skill )
{
    LEARNED_DATA* learned = NULL;

    if ( !ch || !skill )
        return NULL;

    if ( ( skill->guild >= 0 && skill->guild < MAX_ABILITY ) && ch->skill_level[skill->guild] < skill->min_level )
        return NULL;

    for ( learned = ch->first_learned; learned; learned = learned->next )
    {
        if ( learned->skill == skill || learned->id == skill->id )
        {
            if ( !learned->skill )
                learned->skill = skill;

            return learned;
        }
    }

    learned = add_learned( ch, skill );
    return learned;
}

int get_learned_pct( CHAR_DATA* ch, SKILL_DATA* skill )
{
    LEARNED_DATA* learned = NULL;

    if ( !ch || !skill )
        return 0;

    if ( IS_NPC( ch ) )
        return URANGE( 0, ch->top_level, 100 );

    if ( ( learned = get_learned( ch, skill ) ) == NULL )
        return 0;

    return learned->pct;
}

int set_learned_pct( CHAR_DATA* ch, SKILL_DATA* skill, int val )
{
    LEARNED_DATA* learned = NULL;

    if ( !ch || !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( val < 0 || val > 100 )
        return E_LOTJ_INVALID_ARGUMENTS;

    if ( ( learned = get_learned( ch, skill ) ) == NULL )
        return E_LOTJ_NOTHING_TO_DO;

    learned->pct = val;

    if ( learned->pct == 0 && ( !learned->skill || ( ( learned->skill->guild >= 0 && learned->skill->guild < MAX_ABILITY ) && ch->skill_level[learned->skill->guild] < learned->skill->min_level ) ) )
        extract_learned( ch, learned );

    save_char_obj( ch, true );
    return E_LOTJ_SUCCESS;
}

int add_learned_pct( CHAR_DATA* ch, SKILL_DATA* skill, int val )
{
    LEARNED_DATA* learned = NULL;

    if ( !ch || !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( ( learned = get_learned( ch, skill ) ) == NULL )
        return E_LOTJ_NOTHING_TO_DO;

    learned->pct = URANGE( 0, learned->pct + val, 100 );

    if ( learned->pct == 0 && ( !learned->skill || ( ( learned->skill->guild >= 0 && learned->skill->guild < MAX_ABILITY ) && ch->skill_level[learned->skill->guild] < learned->skill->min_level ) ) )
        extract_learned( ch, learned );

    save_char_obj( ch, true );
    return E_LOTJ_SUCCESS;
}

