int skill_save( SKILL_DATA* skill )
{
    if( !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    return upsert_sql_fieldmap_row( DB_TABLE_SKILLS, skill, skill_fields, NO_FLAG);
}

int add_skill( SKILL_DATA* skill )
{
    SKILL_DATA* tSkill = NULL, *tSkill_prev = NULL;
    int hash = 0, x = 0;

    if ( !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    LINK_SORT_NUM( skill, SKILL_DATA, first_skill, last_skill, next, prev, id );

    // This code is ugly as sin, but this is how socials get hashed and I'm applying the
    // same approach for skills.
    char hash_char = LOWER( skill->name[0] );

    if ( hash_char >= 'a' && hash_char <= 'z' )
        hash = ( hash_char - 'a' ) + 1;

    if ( ( tSkill_prev = tSkill = skill_index[hash] ) == NULL )
    {
        skill->next_hash = skill_index[hash];
        skill_index[hash] = skill;
        return E_LOTJ_SUCCESS;
    }

    for ( ; tSkill; tSkill = tSkill->next_hash )
    {
        x = strcmp( skill->name, tSkill->name );

        if ( x <= 0 )
        {
            if ( tSkill == skill_index[hash] )
            {
                skill->next_hash = skill_index[hash];
                skill_index[hash] = skill;
                return E_LOTJ_SUCCESS;
            }

            tSkill_prev->next_hash = skill;
            skill->next_hash = tSkill;
            return E_LOTJ_SUCCESS;
        }

        tSkill_prev = tSkill;
    }

    tSkill_prev->next_hash = skill;
    skill->next_hash = NULL;
    return E_LOTJ_SUCCESS;
}

int remove_skill( SKILL_DATA* skill )
{
    SKILL_DATA* tSkill = NULL, *tSkill_next = NULL;
    CHAR_DATA* tch = NULL;
    LEARNED_DATA* learned = NULL;
    TEACH_DATA* teach = NULL, *next_teach = NULL;

    int hash = 0;

    if ( !skill )
        return E_LOTJ_MISSING_ARGUMENTS;

    // Nix any dangling pointers.
    for ( tch = first_char; tch; tch = tch->next )
    {
        if ( tch->last_skill_used == skill )
            tch->last_skill_used = NULL;

        for ( learned = tch->first_learned; learned; learned = learned->next )
            if ( learned->skill == skill )
                learned->skill = NULL;
    }

    for ( teach = first_teach; teach; teach = next_teach )
    {
        next_teach = teach->next;

        if ( teach->skill == skill )
        {
            UNLINK( teach, first_teach, last_teach, next, prev );
            DISPOSE( teach );
        }
    }

    UNLINK( skill, first_skill, last_skill, next, prev );
    char hash_char = LOWER( skill->name[0] );

    if ( hash_char >= 'a' && hash_char <= 'z' )
        hash = ( hash_char - 'a' ) + 1;

    if ( skill == ( tSkill = skill_index[hash] ) )
        skill_index[hash] = tSkill->next_hash;
    else
    {
        for ( ; tSkill; tSkill = tSkill_next )
        {
            tSkill_next = tSkill->next_hash;

            if ( skill == tSkill_next )
            {
                tSkill->next_hash = tSkill_next->next_hash;
                break;
            }
        }
    }

    FREE_STRUCT( skill, skill_fields );
    return E_LOTJ_SUCCESS;
}

int skill_sql_load( const PGresult *res, int row)
{
    char buf[MIL];
    SKILL_DATA* skill = NULL;
    CREATE( skill, SKILL_DATA, 1 );
    int rval = 0;

    if ( ( rval = fieldmap_postgres_row( res, row, skill, skill_fields ) ) != E_LOTJ_SUCCESS ) {
        FREE_STRUCT( skill, skill_fields );
        return rval;
    }

    if ( !skill->name )
    {
        snprintf( buf, MIL, "%s: loading skill %d with no name, type %s.", FUNC, skill->id, skill_tname[skill->type] );
        bug( buf );
        write_to_log( FUNC, buf, sysdata.log_level, 0, TRUE );
    }

    skill->spell_fun = spell_null;
    skill->skill_fun = NULL;

    SPELL_FUN* spellfun;
    DO_FUN* dofun;

    if(skill->skill_fun_name) {
        if((dofun = skill_function(skill->skill_fun_name)) != skill_notfound) {
            skill->skill_fun = dofun;
            skill->spell_fun = NULL;
        }
    }

    if(skill->spell_fun_name) {
        if((spellfun = spell_function(skill->spell_fun_name)) != spell_notfound) {
            skill->spell_fun = spellfun;
            skill->skill_fun = NULL;
        }
    }

    if ( skill->type == SKILL_TONGUE )
    {
        const FLAG_INFO* flag = flag_from_name( languages, skill->name );
        if ( flag )
            language_table[flag->flag] = skill;
    }

    add_skill( skill );
    return E_LOTJ_SUCCESS;
}

int skill_load_all_sql( void )
{
    if ( skill_table )
        DISPOSE( skill_table );

    return read_all_rows(DB_TABLE_SKILLS, skill_sql_load, NULL );
}

SKILL_DATA* cache_skill( const char* sname, SKILL_DATA** ptr )
{
    SKILL_CACHE* cache = NULL;
    SKILL_DATA* skill = NULL;

    if ( !ptr )
        return NULL;

    if ( ptr && *ptr )
        return *ptr;

    if ( NULLSTR( sname ) )
        return NULL;

    skill = skill_from_name( sname );

    if ( !skill )
        return NULL;

    *ptr = skill;
    CREATE( cache, SKILL_CACHE, 1 );
    cache->ptr = ptr;
    LINK( cache, first_skill_cache, last_skill_cache, next, prev );
    return skill;
}

