char* drawalign( int align )
{
    // Gral changing to -1000 to -300, -299 to +299, +300 to 1000
    static char buf[MSL];

    if ( align >= 1000 )
        snprintf( buf, MSL, "&w[&C============&G|&w]" );
    else if ( align >= 900 )
        snprintf( buf, MSL, "&w[&C===========&G|&C=&w]" );
    else if ( align >= 600 )
        snprintf( buf, MSL, "&w[&C==========&G|&C==&w]" );
    else if ( align >= 300 )
        snprintf( buf, MSL, "&w[&C=========&G|&C===&w]" );
    else if ( align >= 200 )
        snprintf( buf, MSL, "&w[&C========&W|&C====&w]" );
    else if ( align >= 100 )
        snprintf( buf, MSL, "&w[&C=======&W|&C=====&w]" );
    else if ( align <= -1000 )
        snprintf( buf, MSL, "&w[&R|&C============&w]" );
    else if ( align <= -900 )
        snprintf( buf, MSL, "&w[&C=&R|&C===========&w]" );
    else if ( align <= -600 )
        snprintf( buf, MSL, "&w[&C==&R|&C==========&w]" );
    else if ( align <= -300 )
        snprintf( buf, MSL, "&w[&C===&R|&C=========&w]" );
    else if ( align <= -200 )
        snprintf( buf, MSL, "&w[&C====&W|&C========&w]" );
    else if ( align <= -100 )
        snprintf( buf, MSL, "&w[&C=====&W|&C=======&w]" );
    else
        snprintf( buf, MSL, "&w[&C======&W|&C======&w]" );

    return buf;
}

char* drawbar( int bars, int curr, int max, char* cA, char* cB )
{
    static char buf[MSL];
    int perc = 0;
    int a = 0, b = 0;
    strlcpy( buf, "", MSL );

    if ( max == 0 )
        return buf;

    if ( curr > max )
        curr = max;

    perc = ( curr * 100 ) / max;

    for ( b = 1; b <= bars; b++ )
        if ( ( double )( b ) * ( ( double )( 100 ) / ( double )( bars ) ) <= ( double )( perc ) )
            a++;

    if ( a > 0 )
    {
        strlcat( buf, cA, MSL );

        for ( b = 0; b < a; b++ )
            strlcat( buf, "|", MSL );
    }

    b = bars - a;

    if ( b > 0 )
    {
        strlcat( buf, cB, MSL );

        for ( a = 0; a < b; a++ )
            strlcat( buf, "-", MSL );
    }

    return buf;
}

void print_account_characters( DESCRIPTOR_DATA* d, ACCOUNT_DATA* acc )
{
    ACC_CHAR* ach = NULL;
    int cnt = 0, namelen = 0, clanlen = 0;
    bool show_ip = false;

    if ( !d || !acc )
        return;

    if ( d->character && get_trust( d->character ) >= sysdata.log_level )
        show_ip = true;

    for ( ach = acc->first_char; ach; ach = ach->next )
    {
        if ( !NULLSTR( ach->name ) && (int) strlen( ach->name ) > namelen )
            namelen = strlen( ach->name );

        if ( !NULLSTR( ach->clan ) && (int) strlen( ach->clan ) > clanlen )
            clanlen = strlen( ach->clan );
    }

    if ( namelen < 10 )
        namelen = 10;

    if ( clanlen < 25 )
        clanlen = 25;

    if ( ( namelen + clanlen + 21 ) > 80 )
        clanlen = 80 - namelen - 21;

    char buf[MSL], ach_name[128], ach_clan[128], ach_level[32], ips[MSL], colstr[8];

    snprintf( buf, MSL, "&w%-2s &z|&w %-*s &z|&w %-3s &z|&w %-4s &z|&w %-*s\n", "ID", namelen, "NAME", "CLS", "LVL", clanlen, "CLAN" );
    send_to_desc_color( buf, d );
    snprintf( buf, MSL, "&z%.*s\n", ( 21 + namelen + clanlen ), "--------------------------------------------------------------------------------" );
    send_to_desc_color( buf, d );

    for ( ACC_CHAR* ach = acc->first_char; ach; ach = ach->next )
    {
        cnt++;
        bool logged_in = false;

        for ( DESCRIPTOR_DATA* od = first_descriptor; od; od = od->next )
        {
            if ( od->character && !str_cmp( od->character->name, ach->name ) )
                logged_in = true;
        }

        snprintf( ach_name, 128, "%s", !NULLSTR( ach->name ) ? truncate_string( ach->name, namelen ) : "" );
        snprintf( ach_clan, 128, "%s", !NULLSTR( ach->clan ) ? truncate_string( ach->clan, clanlen ) : "" );
        snprintf( ach_level, 32, "%d%s", ach->level, ach->level == 100 ? "+" : "" );
        snprintf( colstr, 8, "%s", cnt % 2 == 0 ? "&037" : "&116" );

        snprintf( buf, MSL, "%s%-2d &z| %s%-*s &z| %s%-3s &z| %s%-4s &z| %s%-*s\n",
        colstr, cnt, logged_in ? "&W" : colstr, namelen + ( (int) strlen( ach_name ) - (int) strlen( stripclr( ach_name ) ) ), ach_name, colstr,
        ( ach->main >= 0 && ach->main < MAX_ABILITY ) ? ability_name_short[ach->main] : "???", colstr,
        ach_level, colstr, clanlen, ( NULLSTR( ach->clan ) || !str_cmp( ach->clan, "(None)" ) ) ? "" : ach_clan );

        send_to_desc_color( buf, d );
    }

    if ( show_ip )
    {
        snprintf( ips, MSL, "\n&zIP Addresses:\n" );
        for ( ach = acc->first_char; ach; ach = ach->next )
            if ( !NULLSTR( ach->ip ) && !stristr( ips, ach->ip ) )
                snprintf( ips + strlen( ips ), MSL - strlen( ips ), "&z- &C%s\n", ach->ip );

        snprintf( ips + strlen( ips ), MSL - strlen( ips ), "\n" );
        send_to_desc_color( ips, d );
    }

    return;
}

