    Various Pages:
     STAT   : Detailed Stat Information
     LEVEL  : Detailed Level Information
     AFFECT : Detailed Affect Information
     TIME   : Log In/Out Times
     ACCOUNT: Show account information

    GRAL to do 19:58 ( IMM | CHAT )[Daven]: 'any immortals around who can tell me where my home is? I haven't been on LOTJ in months'
*/
CMDF do_score( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char arg[MIL], arg2[MIL];

    char cbuf[MAX_STRING_LENGTH];
   // DB_DATA* arena = NULL;
    int bank_sum, ability, i, cnt = 0;
    ACCOUNT_DATA* acc = NULL;

    if ( IS_NPC ( ch ) || ch->switched )
    {
        ch_println( ch, "NPCs cannot use score." );
        return;
    }

    AFFECT_DATA*    paf;
    EXT_BV xbit;
    argument = one_argument( argument, arg );
    pager_println( ch, "&W" );

    if ( !str_cmp( "comments", arg ) || !str_cmp( "account_other", arg ) )
    {
        if ( !IS_IMMORTAL( ch ) )
        {
            bug( "do_score: non-immortal use of \"%s\" by %s.", arg, ch->name );
            return;
        }

        argument = one_argument( argument, arg2 );

        for ( acc = first_account; acc; acc = acc->next )
            if ( !str_cmp( acc->name, arg2 ) )
                break;
    }
    else
    {
        if (!ch->desc)
        {
            send_to_char("Score command requires an active connection.\n", ch);
            return;
        }
        acc = ch->desc->account;
    }
    if ( !str_cmp( "comments", arg ) )
    {
        pager_printf( ch, "&z(&RA&z)ccountcomment:\n" );

        if ( !acc )
        {
            pager_printf( ch, "You have no account associated with this character.\n" );
            return;
        }

        if ( IS_RPC( ch ) && ( get_trust( ch ) > 102 || is_name( "showcomments", ch->pcdata->bestowments ) ) && acc->first_comment )
        {
            ACC_COMMENT* comment = NULL;
            acc->comm_count = 0;

            for ( comment = acc->first_comment; comment; comment = comment->next )
