                acc->comm_count++;
                cnt += comment->warning;
                pager_printf( ch, "&z[&c%.3d&z]&w{ &c%s     &z(&C%s&z)&W: %-30s &zWarning: &R%d\n&w%s&w\n", acc->comm_count, comment->date, comment->from, comment->subject, comment->warning, comment->message );
            }
        }

        pager_printf( ch, "&w---------------------------------------------------------------------------\n" );
        snprintf( buf, MSL, "account_other %s", acc->name );
