        pager_println( ch, "&zWeight: &C%5.5d &z(&wmax &C%7.7d&z)",
                   ch->carry_weight, can_carry_w( ch ) );
        pager_println( ch, "&zPager: (&Y%c&z) &w%3d&z  AutoExit(&Y%c&z)  AutoLoot(&Y%c&z)  AutoAFK(&Y%c&z)  Safe(%s&z)  %s",
