                break;

            case POS_INCAP:
                snprintf( buf, MSL, "&RYou are incapacitated. " );
                break;

            case POS_STUNNED:
                snprintf( buf, MSL, "&RYou are stunned. " );
                break;

            case POS_SLEEPING:
                snprintf( buf, MSL, "&YYou are sleeping. " );
                break;

            case POS_RESTING:
                snprintf( buf, MSL, "&YYou are resting. " );
                break;

            case POS_STANDING:
                snprintf( buf, MSL, "&CYou are standing. " );
