        }

        pager_println( ch, "&zMore info can be gathered through &wSCORE TIME&z, &wSCORE STAT&z, and &wSCORE LEVEL&z." );
        pager_println( ch, "" );
    }

    return;
}
int count_feats( CHAR_DATA* ch )
{
    int cnt = 0;
    LEARNED_DATA* learned = NULL;
    SKILL_DATA* skill = NULL;
    if ( !ch )
        return 0;

    for ( learned = ch->first_learned; learned; learned = learned->next )
        if ( learned->pct > 0 && ( skill = skill_from_id( learned->id ) ) != NULL && skill->type == SKILL_FEAT )
            cnt++;

    return cnt;
}
/*
    Return ascii name of an affect location.
*/
char*           tiny_affect_loc_name( int location )
{
    switch ( location )
    {
        case APPLY_NONE:
            return "NIL";

        case APPLY_STR:
            return " STR  ";

        case APPLY_DEX:
            return " DEX  ";

        case APPLY_INT:
            return " INT  ";

        case APPLY_WIS:
            return " WIS  ";

        case APPLY_CON:
            return " CON  ";

        case APPLY_CHA:
            return " CHA  ";

