RACE_DATA* get_race_by_id( int ra )
{
    RACE_DATA* race;

    for ( race = first_race; race; race = race->next )
        if ( race->id == ra )
            break;

    return race;
}
RACE_DATA* get_race_by_name( char * name )
{
    RACE_DATA* race;

    for ( race = first_race; race; race = race->next ) {
        if ( NULLSTR( race->race_name ) )
            continue;
        if ( !str_cmp(race->race_name, name) )
            break;
    }

    return race;
}

char* get_race( CHAR_DATA* ch )
{
    if ( ch->race )
        return ch->race->shortdesc ? ch->race->shortdesc : ch->race->race_name;
    return "Unknown";
}

// Returns the race string by which other characters should view someone.
// ("Human" instead of "Corellian", account for disguise, etc)
char* get_apparent_race( CHAR_DATA* ch )
{
    RACE_DATA *chrace = ch->disguise ? ch->disguise->race : ch->race;
    if ( chrace == NULL )
        return "Unknown";

    if ( xIS_SET( chrace->flags, RFLAG_RETRACTABLEANT ) && has_pcflag( ch, PCFLAG_RETRACTED_ANT ) && ch->disguise == NULL )
        return "Human";
    if ( is_human( chrace ) )
        return "Human";
    else
        return chrace->shortdesc ? chrace->shortdesc : chrace->race_name;
}

char* get_sex( CHAR_DATA* ch )
{
    if ( ch->sex == 0 )
        return "neutral";

    if ( ch->sex == 1 )
        return "male";

    if ( ch->sex == 2 )
        return "female";

    return ( "unknown" );
}

/*
    Display your current exp, level, and surrounding level exp requirements
    Modified to show your FORCE level at bottom, always.

    New Addition: All max levels are hidden until level 5.
*/
CMDF do_level( CHAR_DATA* ch, char* argument )
{
    char buf[MSL];
    char fbuf[MSL];
    int ability;
    int percent;
    int mode = 0;

    if ( !str_cmp( argument, "progress" ) )
        mode = 1;

    for ( ability = 0 ; ability < MAX_ABILITY ; ability++ )
    {
        if ( ability == DIPLOMACY_ABILITY )
            continue;

        if ( exp_level( ch->skill_level[ability] + 1 ) > 0 )
            percent = 100 * ( ch->experience[ability] - exp_level( ch->skill_level[ability] ) )
                      / ( exp_level( ch->skill_level[ability] + 1 ) - exp_level( ch->skill_level[ability] ) );
        else
            percent = -1;

        snprintf( buf, MSL, "&zNext level: [&R----------&z]" );

        if ( percent >= 100 )
            snprintf( buf, MSL, "&zNext level: [&R||||||||||&z]" );
        else if ( percent >= 90 )
            snprintf( buf, MSL, "&zNext level: [&R|||||||||&r-&z]" );
        else if ( percent >= 80 )
            snprintf( buf, MSL, "&zNext level: [&R||||||||&r--&z]" );
        else if ( percent >= 70 )
            snprintf( buf, MSL, "&zNext level: [&R|||||||&r---&z]" );
        else if ( percent >= 60 )
            snprintf( buf, MSL, "&zNext level: [&R||||||&r----&z]" );
        else if ( percent >= 50 )
            snprintf( buf, MSL, "&zNext level: [&R|||||&r-----&z]" );
        else if ( percent >= 40 )
            snprintf( buf, MSL, "&zNext level: [&R||||&r------&z]" );
        else if ( percent >= 30 )
            snprintf( buf, MSL, "&zNext level: [&R|||&r-------&z]" );
        else if ( percent >= 20 )
            snprintf( buf, MSL, "&zNext level: [&R||&r--------&z]" );
        else if ( percent >= 10 )
            snprintf( buf, MSL, "&zNext level: [&R|&r---------&z]" );

        if ( ability != FORCE_ABILITY )
        {
            if ( ch->skill_level[ability] < 3 && max_level( ch, ability ) >= 3 )
            {
                if ( mode == 0 )
                    ch_println( ch, "&C%s%-15s   &zLevel: &G%-3d   &zMax: &C???   &zExp: &C%-10ld   &zNext: &C%-10d",
                               ability == ch->main_ability ? "&W" : "", flag_value_name( ability_name, ability ), ch->skill_level[ability], ch->experience[ability],
                               exp_level( ch->skill_level[ability] + 1 ) );

                if ( mode == 1 )
                    ch_println( ch, "&C%s%-15s   &zLevel: &G%-3d   &zMax: &C???   %s",
                               ability == ch->main_ability ? "&W" : "", flag_value_name( ability_name, ability ), ch->skill_level[ability], buf );
            }
            else
            {
                if ( mode == 0 )
                    ch_println( ch, "&C%s%-15s   &zLevel: &G%-3d   &zMax: &C%-3d   &zExp: &C%-10ld   &zNext: &C%-10d",
                               ability == ch->main_ability ? "&W" : "", flag_value_name( ability_name, ability ), ch->skill_level[ability], max_level( ch, ability ), ch->experience[ability],
                               exp_level( ch->skill_level[ability] + 1 ) );

                if ( mode == 1 )
                    ch_println( ch, "&C%s%-15s   &zLevel: &G%-3d   &zMax: &C%-3d   %s",
                               ability == ch->main_ability ? "&W" : "", flag_value_name( ability_name, ability ), ch->skill_level[ability], max_level( ch, ability ), buf );
            }
        }
        else
        {
            strlcpy( fbuf, buf, MSL );
        }
    }

    if ( ch->skill_level[FORCE_ABILITY] > 1 )
    {
        if ( mode == 0 )
            ch_println( ch, "&C%-15s   &zLevel: &G%-3d   &zMax: &C%-3d   &zExp: &C%-10ld   &zNext: &C%-10d",
                       flag_value_name( ability_name, FORCE_ABILITY ), ch->skill_level[FORCE_ABILITY], max_level( ch, FORCE_ABILITY ), ch->experience[FORCE_ABILITY],
                       exp_level( ch->skill_level[FORCE_ABILITY] + 1 ) );

        if ( mode == 1 )
            ch_println( ch, "&C%-15s   &zLevel: &G%-3d   &zMax: &C%-3d   %s",
                       flag_value_name( ability_name, FORCE_ABILITY ), ch->skill_level[FORCE_ABILITY], max_level( ch, FORCE_ABILITY ), fbuf );
    }
    else
    {
        snprintf( fbuf, MSL, "&zNext level: [&r..........&z]" );

        if ( mode == 0 )
            ch_println( ch, "&C%-15s   &zLevel: &G%-3d   &zMax: &C???   &zExp: &C???          &zNext: &C???",
                       flag_value_name( ability_name, FORCE_ABILITY ), ch->skill_level[FORCE_ABILITY], ch->experience[FORCE_ABILITY] );

        if ( mode == 1 )
            ch_println( ch, "&C%-15s   &zLevel: &G%-3d   &zMax: &C???   %s",
                       flag_value_name( ability_name, FORCE_ABILITY ), ch->skill_level[FORCE_ABILITY], fbuf );
    }
}

