        }

        ch_println( ch, "&z| --------------------------------------------------------------------------+" ) ;

        if ( ch->pcdata->frank >= FRANK_KNIGHT ) //Let's have the sub-classes see their passive buffs on aff by. - Gathorn 28Jan2017
        {
