            else if ( IS_GOOD ( ch ) )
                ch_println( ch, "&z| &GJedi Training&z:" );
            else
                ch_println( ch, "&z| &WForce Training&z:" );

            switch ( ch->pcdata->fclass )
            {
                case JEDI_GUARDIAN:
                case SITH_JUGGERNAUT:
                    ch_println( ch, "&z| &CForce Combat &z- &CYou are more proficient in combat with a lightsaber." );
                    break;

                case JEDI_SENTINEL:
                case SITH_ASSASSIN:
                    ch_println( ch, "&z| &CForce Suppression &z- &CYour usage of the Force does not cause disturbances." );
                    break;

                case JEDI_CONSULAR:
                case SITH_SORCERER:
                    ch_println( ch, "&z| &CForce Mastery &z- &CYou are sometimes able to use the Force effortlessly." );
                    break;
