            send_to_char( "&z| &BSuscepts:     ", ch );
            ch_println( ch, " &C%s", flag_string( &ch->susceptible, resistant_types ) );
        }

        ch_println( ch, "&z\\---------------------------------------------------------------------------+" );
        return;
    }

    if ( ch->first_affect )
    {
        cmatch = TRUE;
        ch_println( ch, "" );
        ch_println( ch, "&wCharacter affects:" );

        if ( ch->spirit )
            ch_println( ch, "&z&W&CYou are %s.", ch->manifest ? "Manifested" : "Ethereal" );

        for ( paf = ch->first_affect; paf; paf = paf->next )
        {
            skill = skill_from_id( paf->type );

            if ( skill && paf->type >= TYPE_HERB && paf->type < TYPE_PERSONAL )
                send_to_char( "&YDrug:       ", ch );
            else if ( skill && skill->guild == FORCE_ABILITY )
                send_to_char( "&CForce:      ", ch );
            else
                send_to_char( "&BPhysical:   ", ch );

            if ( ch->top_level >= 20 )
            {
                if ( paf->duration < 25 )
                    ch_printf( ch, "&z(&Y%5d&z )   ", paf->duration );
                else if ( paf->duration < 6  )
                    ch_printf( ch, "&z(&R%5d&z )   ", paf->duration );
                else
                    ch_printf( ch, "&z(&C%5d&z )   ", paf->duration );
            }

            if ( paf->modifier == 0 )
                ch_printf( ch, "&z[ &R------------ &z]   " );
            else if ( paf->modifier > 999 )
                ch_printf( ch, "&z[          %7.7s&z ]   ", tiny_affect_loc_name( paf->location ) );
            else
                ch_printf( ch, "&z[ &R%+-4.4d %7.7s&z]   ", paf->modifier, tiny_affect_loc_name( paf->location ) );

            if ( skill )
                ch_printf( ch, "&C%-14s&z", skill->name );
            else
                ch_printf( ch, "&Y%-14s&z", print_bitvector_flags( &paf->bitvector, affect_flags ) );

            ch_println( ch, "" );
        }
    }

    if ( ch->in_room->first_affect )
    {
        for ( paf = ch->in_room->first_affect; paf; paf = paf->next )
        {
            if ( xIS_SET( paf->bitvector, AFF_OBSCURE ) )
            {
                int chance = 0; // Ralen: Chance ripped from handler.c sharp_eye check.
                chance = URANGE( 0, IS_NPC( ch ) ? ch->top_level : get_learned_pct( ch, cache_skill( "perception", &skill_perception ) ), 100 );

                if ( chance < 100 )
                    chance = URANGE( 1, chance - 40, 100 );

                if ( number_percent() >= chance )
                    continue;
            }

            if ( !rmatch )
            {
                ch_println( ch, "" );
                ch_println( ch, "&wRoom affects:" );
                rmatch = TRUE;
            }

            skill = skill_from_id( paf->type );

            if ( skill && paf->type >= TYPE_HERB && paf->type < TYPE_PERSONAL )
                send_to_char( "&YDrug:       ", ch );
            else if ( skill && skill->guild == FORCE_ABILITY )
                send_to_char( "&CForce:      ", ch );
            else
                send_to_char( "&BPhysical:   ", ch );

            if ( ch->top_level >= 20 )
            {
                if ( paf->duration < 25 )
                    ch_printf( ch, "&z(&Y%5d&z )   ", paf->duration );
                else if ( paf->duration < 6  )
                    ch_printf( ch, "&z(&R%5d&z )   ", paf->duration );
                else
                    ch_printf( ch, "&z(&C%5d&z )   ", paf->duration );
            }

            if ( paf->modifier == 0 )
                ch_printf( ch, "&z[ &R------------ &z]   " );
            else if ( paf->modifier > 999 )
                ch_printf( ch, "&z[          %7.7s&z ]   ", tiny_affect_loc_name( paf->location ) );
            else
                ch_printf( ch, "&z[ &R%+-4.4d %7.7s&z]   ", paf->modifier, tiny_affect_loc_name( paf->location ) );

            if ( skill )
                ch_printf( ch, "&C%-14s&z", skill->name );
            else
                ch_printf( ch, "&Y%-14s&z", print_bitvector_flags( &paf->bitvector, affect_flags ) );

            ch_println( ch, "" );
        }
    }

    if ( !cmatch && !rmatch )
        ch_println( ch, "\n&YYou are not currently affected by anything.&w" );

    return;
}

