CMDF do_equipment( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    OBJ_DATA* obj;
    int iWear, dam;
    bool found;
    char buf[MSL];
    ch_println( ch, "&RYou are using:" );
    found = FALSE;
    MSDPSetNumber( ch->desc, eMSDP_SHIELD_ENERGY, 0 );
    MSDPSetNumber( ch->desc, eMSDP_JETPACK_FUEL, 0 );
    MSDPSetNumber( ch->desc, eMSDP_LIGHT_TIME, 0 );
    MSDPSetNumber( ch->desc, eMSDP_GRENADE_ROUNDS, 0 );
    MSDPSetNumber( ch->desc, eMSDP_BLADE_POWER, 0 );
    MSDPSetNumber( ch->desc, eMSDP_CURRENT_AMMO, 0 );
    MSDPSetNumber( ch->desc, eMSDP_MAX_AMMO, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_SHIELD_ENERGY, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_JETPACK_FUEL, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_LIGHT_TIME, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_GRENADE_ROUNDS, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_BLADE_POWER, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_CURRENT_AMMO, 0 );
    UpdateGMCPNumber( ch->desc, GMCP_MAX_AMMO, 0 );

    for ( iWear = 0; iWear < MAX_WEAR; iWear++ )
    {
        if ( wielding_claws( ch ) && iWear == WEAR_WIELD )
        {
            send_to_char( "&B ", ch );
            send_to_char( where_name[iWear], ch );
            ch_println( ch, "&G&rA pair of deadly dewclaws" );
            found = TRUE;
        }
        else
        {
            for ( obj = ch->first_carrying; obj; obj = obj->next_content )
                if ( obj->wear_loc == iWear )
                {
                    send_to_char( where_name[iWear], ch );

                    if ( can_see_obj( ch, obj ) )
                    {
                        send_to_char( "&G", ch );
                        send_to_char( format_obj_to_char( obj, ch, TRUE ), ch );
                        strlcpy( buf, "", MSL );

                        if ( xIS_SET( obj->wear_flags, ITEM_WEAR_SHIELD ) &&  obj->item_type == ITEM_SHIELD )
                        {
                            ch_printf( ch, " &B(&CEnergy: &Y%d &C%s&B)&w", obj->value[4], obj->value[2] > 0 ? "&YWarming up&w" : obj->value[3] == 1 ? "&GOn&w" : "&zOff&w" );
                            MSDPSetNumber( ch->desc, eMSDP_SHIELD_ENERGY, obj->value[4] );
                            UpdateGMCPNumber( ch->desc, GMCP_SHIELD_ENERGY, obj->value[4] );
                        }

                        //Ripped from above:
                        if ( xIS_SET( obj->wear_flags, ITEM_WEAR_BACK ) && obj->item_type == ITEM_JETPACK  )
                        {
                            ch_printf( ch, " &B(&CFuel: &Y%d &C%s&B)&w", obj->value[4], obj->value[2] > 0 ? "&YSpooling up&w" : obj->value[5] == 1 ? "&GOnline&w" : "&zOffline&w" );
                            MSDPSetNumber( ch->desc, eMSDP_JETPACK_FUEL, obj->value[4] );
                            UpdateGMCPNumber( ch->desc, GMCP_JETPACK_FUEL, obj->value[4] );
                        }
                        else
                            switch ( obj->item_type )
                            {
                                default:
                                    break;

                                case ITEM_ARMOR:
                                case ITEM_SHIELD:
                                    dam = obj->value[0];

                                    if ( dam >= 10 )
                                        strlcat( buf, " &B(&Csuperb&B) ", MSL );
                                    else if ( dam >=  7 )
                                        strlcat( buf, " &B(&Ggood&B) ", MSL );
                                    else if ( dam >=  5 )
                                        strlcat( buf, " &B(&Yworn&B) ", MSL );
                                    else if ( dam >=  3 )
                                        strlcat( buf, " &B(&Rpoor&B) ", MSL );
                                    else if ( dam >=  1 )
                                        strlcat( buf, " &B(&Rawful&B) ", MSL );
                                    else if ( dam ==  0 )
                                        strlcat( buf, " &B(&Rbroken&B) ", MSL );

                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_LIGHT:
                                    if ( obj->value[2] > 3 )
                                        ch_printf( ch, " &B(&CTime: &Y%d&B)", obj->value[2] );
                                    else if ( obj->value[2] < 4 && obj->value[2] >= 0 )
                                        ch_printf( ch, " &B(&CTime: &R%d&B)", obj->value[2] );

                                    if ( IS_SET( obj->value[3], BV00 ) )
                                        strlcat( buf, " &B(&YOn&B) ", MSL );

                                    if ( !IS_SET( obj->value[3], BV00 ) )
                                        strlcat( buf, " &B(&COff&B) ", MSL );

                                    MSDPSetNumber( ch->desc, eMSDP_LIGHT_TIME, obj->value[2] );
                                    UpdateGMCPNumber( ch->desc, GMCP_LIGHT_TIME, obj->value[2] );
                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_GRENADE:
                                    if ( obj->value[4] > 0 )
                                        ch_printf( ch, " &R[ARMED] &B(&C%d Rounds&B) ", obj->value[4] );

                                    if ( obj->value[4] < 1 )
                                        strlcat( buf, " &B(&CUnarmed&B) ", MSL );

                                    MSDPSetNumber( ch->desc, eMSDP_GRENADE_ROUNDS, obj->value[4] );
                                    UpdateGMCPNumber( ch->desc, GMCP_GRENADE_ROUNDS, obj->value[4] );
                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_COMLINK:
                                    ch_printf( ch, " &B(&CChannel: &Y%d&B)", obj->value[5] );

                                    if ( IS_SET( obj->value[3], COMM_ENCRYPT ) )
                                        ch_printf( ch, " &B(&CCode: &Y%d&B)", obj->value[4] );

                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_CONTAINER:
                                    dam = 10 - obj->value[3];

                                    if ( dam < 2 )
                                        strlcat( buf, " &B(&Csuperb&B) ", MSL );
                                    else if ( dam < 4 )
                                        strlcat( buf, " &B(&Ggood&B) ", MSL );
                                    else if ( dam < 6 )
                                        strlcat( buf, " &B(&Yworn&B) ", MSL );
                                    else if ( dam < 8 )
                                        strlcat( buf, " &B(&Rpoor&B) ", MSL );
                                    else if ( dam < 10 )
                                        strlcat( buf, " &B(&Rtorn&B) ", MSL );
                                    else if ( dam ==  10 )
                                        strlcat( buf, " &B(&Rshredded&B) ", MSL );

                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_HOLSTER:
                                    if ( obj->first_content == NULL )
                                        strlcat( buf, " &B(&CEmpty&B) ", MSL );

                                    if ( obj->first_content != NULL )
                                        strlcat( buf, " &B(&CFull&B) ", MSL );

                                    send_to_char( buf, ch );
                                    break;

                                case ITEM_CUTTER:
                                    send_to_char( buf, ch );
                                    ch_printf( ch, " &G(Power: &Y%d&G)", obj->value[4] );
                                    MSDPSetNumber( ch->desc, eMSDP_BLADE_POWER, obj->value[4] );
                                    UpdateGMCPNumber( ch->desc, GMCP_BLADE_POWER, obj->value[4] );
                                    break;

                                case ITEM_WEAPON:
                                    if ( !wielding_claws( ch ) )
                                    {
                                        dam = INIT_WEAPON_CONDITION - obj->value[0];

                                        if ( dam < 2 )
                                            strlcat( buf, " &B(&Csuperb&B) ", MSL );
                                        else if ( dam < 4 )
                                            strlcat( buf, " &B(&Ggood&B) ", MSL );
                                        else if ( dam < 7 )
                                            strlcat( buf, " &B(&Yworn&B) ", MSL );
                                        else if ( dam < 10 )
                                            strlcat( buf, " &B(&Rpoor&B) ", MSL );
                                        else if ( dam < 12 )
                                            strlcat( buf, " &B(&Rawful&B) ", MSL );
                                        else if ( dam ==  12 )
                                            strlcat( buf, " &B(&Rbroken&B) ", MSL );

                                        send_to_char( buf, ch );

                                        if ( obj->value[3] == WEAPON_BLASTER )
                                        {
                                            obj->value[4] = URANGE( 0, obj->value[4], obj->value[5] );

                                            if ( obj->blaster_setting == BLASTER_FULL )
                                                ch_printf( ch, "&CFULL" );
                                            else if ( obj->blaster_setting == BLASTER_HIGH )
                                                ch_printf( ch, "&CHIGH" );
                                            else if ( obj->blaster_setting == BLASTER_NORMAL )
                                                ch_printf( ch, "&CNORMAL" );
                                            else if ( obj->blaster_setting == BLASTER_HALF )
                                                ch_printf( ch, "&CHALF" );
                                            else if ( obj->blaster_setting == BLASTER_LOW )
                                                ch_printf( ch, "&CLOW" );
                                            else if ( obj->blaster_setting == BLASTER_STUN )
                                                ch_printf( ch, "&CSTUN" );

                                            MSDPSetNumber( ch->desc, eMSDP_CURRENT_AMMO, obj->value[4] );
                                            MSDPSetNumber( ch->desc, eMSDP_MAX_AMMO, obj->value[5] );
                                            UpdateGMCPNumber( ch->desc, GMCP_CURRENT_AMMO, obj->value[4] );
                                            UpdateGMCPNumber( ch->desc, GMCP_MAX_AMMO, obj->value[5] );
                                            ch_printf( ch, " &G%d&z/&G%d", obj->value[4], obj->value[5] );
                                        }
                                        else if ( obj->value[3] == WEAPON_DISRUPTOR )
                                        {
                                            obj->value[4] = URANGE( 0, obj->value[4], obj->value[5] );
                                            MSDPSetNumber( ch->desc, eMSDP_CURRENT_AMMO, obj->value[4] );
                                            MSDPSetNumber( ch->desc, eMSDP_MAX_AMMO, obj->value[5] );
                                            UpdateGMCPNumber( ch->desc, GMCP_CURRENT_AMMO, obj->value[4] );
                                            UpdateGMCPNumber( ch->desc, GMCP_MAX_AMMO, obj->value[5] );
                                            ch_printf( ch, " &G%d&z/&G%d", obj->value[4], obj->value[5] );
                                        }
                                        else if ( obj->value[3] == WEAPON_FLAMETHROWER )
                                        {
                                            double pa = 0;

                                            if ( obj->value[5] > 0 )
                                                pa = ( ( ( double )( obj->value[4] ) / ( double )( obj->value[5] ) ) * 100 );

                                            ch_printf( ch, " &B(&CFuel: %d%%&B)", ( int )pa );
                                        }
                                        else if ( ( obj->value[3] == WEAPON_LIGHTSABER || obj->value[3] == WEAPON_VIBRO_BLADE
                                                    || obj->value[3] == WEAPON_FORCE_PIKE || obj->value[3] == WEAPON_BOWCASTER
                                                    || obj->value[3] == WEAPON_VIBRO_AXE ) )
                                        {
                                            ch_printf( ch, "&G(Power: &Y%d&G)", obj->value[4] );
                                            MSDPSetNumber( ch->desc, eMSDP_BLADE_POWER, obj->value[4] );
                                            UpdateGMCPNumber( ch->desc, GMCP_BLADE_POWER, obj->value[4] );
                                        }
                                    }

                                    break;
                            }

                        ch_println( ch, "" );
                    }
                    else
                        ch_println( ch, "something." );

                    found = TRUE;
                }
        }
    }

    if ( !found )
        ch_println( ch, "Nothing." );

    return;
}



void set_title( CHAR_DATA* ch, char* title )
{
    char buf[MSL];

    if ( !ch || IS_NPC( ch ) )
        return;

    if ( NULLSTR( title ) )
        strlcpy( buf, ch->disguise ? ch->disguise->disgname : ch->name, MSL );
    else
        strlcpy( buf, title, MSL );

    if ( ch->disguise )
        SET_STRING( ch->disguise->title, buf );
    else
        SET_STRING( ch->pcdata->title, buf );

    save_char_obj( ch, TRUE );
    return;
}

