CMDF do_publictitle( CHAR_DATA* ch, char* argument )
{
    char arg[MIL];

    if ( IS_NPC( ch ) )
        return;

    one_argument( argument, arg );

    if ( has_pcflag( ch, PCFLAG_NOTITLE ) )
    {
        ch_println( ch, "You try but the Force resists you." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zYour current %spublic title is: &W%s", ch->disguise ? "disguise " : "", ch->disguise ? ch->disguise->pubtitle : ch->pcdata->pubtitle );
        ch_println( ch, "&zSyntax: &Cpublictitle <&wnew title&C>" );
        ch_println( ch, "&z        &Cpublictitle clear" );
        ch_println( ch, "\n&CHINT: &zPublictitles can be seen by everyone. Use &Ctitle&z to customize your title for clan members." );
        return;
    }

    if ( !str_cmp( arg, "clear" ) )
    {
        set_title2( ch, "" );
        ch_println( ch, "&wYour %spublic title has been cleared.", ch->disguise ? "disguise " : "" );
        return;
    }

    if ( checkclr( argument, "x" ) )
    {
        ch_println( ch, "&RYou cannot use the BLACK Color token in your %stitle.", ch->disguise ? "disguise " : "" );
        return;
    }

    if ( nifty_is_name( "^", argument ) )
    {
        ch_println( ch, "&RYou cannot use the background/blinking tokens in your %stitle.", ch->disguise ? "disguise " : "" );
        return;
    }

    if ( strlen( stripclr( argument ) ) < 1 )
    {
        ch_println( ch, "&RTry including something OTHER than color tokens." );
        return;
    }

    if ( ch->disguise )
    {
        if ( !strstr( stripclr( strip_apost( argument ) ), ch->disguise->disgname ) )
        {
            ch_println( ch, "You must include your disguised name somewhere in your %stitle!", ch->disguise ? "disguise " : "" );
            return;
        }
    }
    else if ( ( get_trust( ch ) <= 101 ) && !strstr( stripclr( strip_apost( argument ) ), ch->name ) )
    {
        ch_println( ch, "You must include your name somewhere in your %stitle!", ch->disguise ? "disguise " : "" );
        return;
    }

    if ( ( get_trust( ch ) <= 101 ) && ( strstr( argument, ")" ) || strstr( argument, "(" ) ) )
    {
        ch_println( ch, "You cannot have ( or ) in your %stitle!", ch->disguise ? "disguise " : "" );
        return;
    }

    smash_tilde( argument );
    set_title2( ch, argument );
    ch_println( ch, "Ok." );
}

