        buf[70] = '\0';

    hide_tilde( buf );
    SET_STRING( ch->pcdata->homepage, buf );
    ch_println( ch, "Homepage set." );
}



/*
    Set your personal description                -Thoric
*/
CMDF do_description( CHAR_DATA* ch, char* argument __attribute__((unused)) )
{
    BUFFER_DATA* buffer = NULL;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "Monsters are too dumb to do that!" );
        return;
    }

    if ( !ch->desc )
    {
        bug( "do_description: no descriptor", 0 );
        return;
    }

    if ( is_busy( ch ) )
    {
        ch_println( ch, "You are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            bug( "do_description: illegal substate", 0 );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            ch->substate = SUB_PERSONAL_DESC;
            buffer = create_buffer( ch, FUNC );
            start_editing( ch, FUNC, ch->disguise ? ch->disguise->description : ch->description );
            return;

        case SUB_PERSONAL_DESC:
            buffer = get_buffer( ch, FUNC );
            if ( !buffer )
            {
                stop_editing( ch, false );
                return;
            }
            dispose_buffer( buffer );
            if ( ch->disguise )
                SET_STRING( ch->disguise->description, copy_buffer( ch ) );
            else
                SET_STRING( ch->description, copy_buffer( ch ) );

            stop_editing( ch, false );
            return;
    }
}

/* Ripped off do_description for whois bio's -- Scryn*/
CMDF do_bio( CHAR_DATA* ch, char* argument )
{
    BUFFER_DATA* buffer = NULL;

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "&RMobs can't set their histories!" );
