    }

    if ( !str_cmp( argument, "display" ) )
    {
        // GRAL Allows you to check your encryption status above the spam :P
        ch_println( ch, "&WDisplaying your %s bio.\n%s\n-\t\tComplete\t\t-", has_pcflag( ch, PCFLAG_WHOIS ) ? "encrypted" : "decrypted", ch->pcdata->bio );
