    }

    if ( !ch->desc )
    {
        bug( "do_bio: no descriptor", 0 );
        return;
    }

    if ( is_busy( ch ) )
    {
        ch_println( ch, "You are too busy to do that right now." );
        return;
    }

    switch ( ch->substate )
    {
        default:
            bug( "do_bio: illegal substate", 0 );
            return;

        case SUB_RESTRICTED:
            ch_println( ch, "You cannot use this command from within another command." );
            return;

        case SUB_NONE:
            ch->substate = SUB_PERSONAL_BIO;
            buffer = create_buffer( ch, FUNC );
            start_editing( ch, FUNC, ch->pcdata->bio );
            return;

        case SUB_PERSONAL_BIO:
            buffer = get_buffer( ch, FUNC );
            if ( !buffer )
            {
                stop_editing( ch, false );
                return;
            }
            dispose_buffer( buffer );
            SET_STRING( ch->pcdata->bio, copy_buffer( ch ) );
            stop_editing( ch, false );
            return;
    }
}

