char* convert_newline( char* str )
{
    static char ret[MSL];
    char*     retptr;
    retptr = ret;

    for ( ; *str != '\0'; str++ )
    {
        if ( *str == '\\' )
        {
            if ( *( str - 1 ) == '\\' )
                continue;
            else if ( *( str + 1 ) == 'n' )
            {
                *retptr = '\n';
                retptr++;
                str++;
                continue;
            }
        }

        *retptr = *str;
        retptr++;
    }

    *retptr = '\0';
    return ret;
}
