CMDF do_bot( CHAR_DATA* ch, char* argument )
{
    int i = ( 60 * 60 * 2 );

    if ( IS_NPC( ch ) )
    {
        ch_println( ch, "NPCs can't use this." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Cbot <&woption&C>\n&zOptions:&C start, stop, cancel, status&w" );
        ch_println( ch, "&wIt's important to read &kHELP BOTTING&k to understand when you can and cannot use this command." );

        return;
    }

    if ( !str_cmp( "start", argument ) )
    {
        if ( ch->pcdata->cooldown > 0 )
        {
            ch_println( ch, "&wYou have to wait &C%d min%s&w to bot again.",
                       ( int )( ch->pcdata->cooldown / 60 ), ch->pcdata->cooldown / 60 == 1 ? "" : "s" );
            return;
        }

        if ( ch->pcdata->cooldown == -1 )
        {
            ch_println( ch, "&wBotting resumed." );
            ch->pcdata->cooldown = 0;
            return;
        }

        if ( ch->pcdata->botting )
        {
            ch_println( ch, "&zYou are already botting.\n&wYou have &C%d min%s&w left to bot.\n&zTo STOP type &CBOT STOP&z.&w", ( ( 60 * 60 * 2 ) - ch->pcdata->botting ) / 60, ( ( 60 * 60 * 2 ) - ch->pcdata->botting ) / 60 == 1 ? "" : "s" );
            return;
        }

        send_to_char( "&wYour &Ctwo hour &wbot time starts now. You will have a &R[BOTTING] &wflag but this does NOT protect you like the AFK flag does. When your time is up, you will automatically be set AFK and enter cooldown mode. If for any reason you need to pause botting you can do so by typing &kBOT STOP&k to pause your timer. You can resume it by typing &kBOT START&k again.\n\n&wIt is important to know what skills you can and cannot use with the bot command. Read &kHELP BOTTING&k for more info.", ch );
        ch->pcdata->botting = 1;
        }
      else if ( !str_cmp( "stop", argument ) )
    {
        if ( !ch->pcdata->botting )
        {
            ch_println( ch, "&wYou aren't botting. Try &CBOT START&w." );
            return;
        }

        if ( ch->pcdata->cooldown == -1 )
        {
            ch_println( ch, "Botting is already stopped.\nType BOT START to resume, or BOT CANCEL to cancel." );
            return;
        }

        ch->pcdata->cooldown = -1;
        ch_println( ch, "&zBotting paused. You have &C%d min%s&z remaining.\n&wType &CBOT START&w to resume, or &CBOT CANCEL&w to cancel.",
                   ( 60 * 60 * 2 - ch->pcdata->botting ) / 60, ( 60 * 60 * 2 - ch->pcdata->botting ) / 60 == 1 ? "" : "s" );
    }
    else if ( !str_cmp( "cancel", argument ) )
    {
        if ( !ch->pcdata->botting )
        {
            ch_println( ch, "&wBut you aren't botting!" );
            return;
        }

        ch->pcdata->botting = 0;
        ch->pcdata->cooldown = 60 * 30;
        ch_println( ch, "&zBotting session terminated.\n&wYou must wait &C30 mins&w to bot again.\n&zType &CBOT STATUS&z for info.&w" );
    }
    else if ( !str_cmp( "status", argument ) )
    {
        if ( ch->pcdata->botting )
        {
            ch_printf( ch, "&zYou have been botting for &C%d min%s&z.&w\n&wYou may bot for another &C%d min%s&w.\n%s",
                       ch->pcdata->botting / 60, ch->pcdata->botting / 60 == 1 ? "" : "s", ( i - ch->pcdata->botting ) / 60,
                       ( i - ch->pcdata->botting ) / 60 == 1 ? "" : "s", ch->pcdata->cooldown == -1 ?
                       "&zYour botting session is &CPAUSED&z. Type &CBOT START&z to resume.&w\n" : "" );
        }
        else if ( ch->pcdata->cooldown > 0 )
        {
            ch_println( ch, "&wYou may bot again in another &C%d min%s&w.", ch->pcdata->cooldown / 60, ch->pcdata->cooldown / 60 == 1 ? "" : "s" );
        }
        else
        {
            ch_println( ch, "&wYou aren't even botting.\n&zType &CBOT START&z to start botting.&w" );
        }
    }
    else
    {
        ch_println( ch, "&wUnrecognized command. Type &CBOT&w to see the available options." );
        return;
    }

    do_save( ch, "-noalert" );
}

