    if ( nifty_is_name( "^", argument ) )
    {
        ch_println( ch, "&RYou cannot use the background/blinking tokens in your action description." );
        return;
    }

    if ( strlen( stripclr( argument ) ) < 1 )
    {
        ch_println( ch, "&RTry including something OTHER than color tokens." );
        return;
    }

    smash_tilde( argument );
    action_set( ch, NULL, argument, NULL, 0 );
    do_visible( ch, "-noalert" );
    ch_println( ch, "Ok." );
