bool is_empowered( CHAR_DATA* ch, char* argument )
{
    if ( !ch || !ch->pcdata )
        return FALSE;

    if ( is_name( argument, ch->pcdata->bestowments ) )
        return TRUE;

    if ( ch->pcdata->clan )
    {
        RANK_DATA* rank = get_rank_obj(ch);

        if ( rank && rank->empowerments && is_name( argument, rank->empowerments ) )
            return TRUE;
    }

    return FALSE;
}

char* get_empowerments( CHAR_DATA* ch )
{
    if ( !ch || !ch->pcdata )
        return NULL;

    static char result[MSL];
    char* rank_empowers;
    char arg[MIL];

    strlcpy( result, "", MSL );

    if ( !NULLSTR( ch->pcdata->bestowments ) )
        snprintf( result, MSL, "%s", ch->pcdata->bestowments );

    RANK_DATA* rank = get_rank_obj(ch);

    if ( rank && !NULLSTR( rank->empowerments ) )
    {
        if ( !NULLSTR( result ) )
        {
            rank_empowers = rank->empowerments;
            while ( !NULLSTR( rank_empowers ) )
            {
                rank_empowers = one_argument( rank_empowers, arg );
                if ( !is_name( arg, result ) )
                    snprintf( result + strlen( result ), MSL - strlen( result ), " %s", arg );
            }
        }
        else
            snprintf( result, MSL, "%s", rank->empowerments );
    }

    return result;
}

/* Function to check if the character has a matching alt from this timeline. */
bool is_alt( CHAR_DATA* ch, char* alt )
{
    ACCOUNT_DATA* acc = NULL;
    DB_DATA* ach = NULL;

    if ( !ch || !ch->pcdata || !ch->pcdata->account )
        return false;

    // First check for living alts
    acc = account_get_from_char( alt );

    if ( acc && acc == ch->pcdata->account )
        return true;

    // Then check for dead, historical account characters who lived and died in this timeline     
    for ( ach = ch->pcdata->account->last_history; ach; ach = ach->prev )
        if ( !str_cmp( ach->name, alt ) && atoi( ach->str2 ) > sysdata.tlstartdate )
            return true;

    return false;
}

