    long funds = 0;

    if ( !ch )
        return FALSE;

    // If they have the money on hand, then great. Return true
    funds += ch->gold;

    if ( funds >= amount )
        return TRUE;

    // If not, and if we're checking their bank accounts, iterate through
    if ( bank )
    {
        for ( BANK_DATA* acct = first_bank; acct; acct = acct->next )
        {
            if ( str_cmp( ch->name, acct->owner ) )
                continue;

            funds += acct->amount;

            if ( funds >= amount )
                return TRUE;
        }
    }

    // If they still didn't have enough money even in their bank accounts, return false
    return FALSE;
}

/**
    @param ch Character making the transaction
    @param amount Amount of funds (+/-) to add or subtract
    @param bank Whether to add/subtract funds to/from the character's bank accounts, if needed
    @param function The name of the calling function, to be recorded in the SQL log
*/
void player_mod_funds( CHAR_DATA* ch, int amount, bool bank, const char* function )
{
    long funds = amount;
    int acct_amt = 0;

    // Fail out if there isn't a character passed or if they're an NPC.
    if ( !ch || !ch->pcdata || amount == 0 )
        return;

    // Make a basic SQL log for the transaction.
    sql_credits_log( ch->name, function, amount, TRUE );

    // If we're adding funds, figure out where to put them
    if ( amount > 0 )
    {
        if ( bank && amount > ( sysdata.maxgold - ch->gold ) )
        {
            for ( BANK_DATA* acct = first_bank; acct; acct = acct->next )
            {
                if ( str_cmp( ch->name, acct->owner ) )
                    continue;

                acct_amt = acct->amount;
                acct->amount += UMIN( funds, 5000000 - acct_amt );
                save_bank( acct, true );
                funds -= UMIN( funds, 5000000 - acct_amt );

                if ( funds <= 0 )
                    break;
            }

            if ( funds > 0 )
            {
                ch_println( ch, "&WYour bank accounts are too full to hold the entire amount. The remaining %'ld credits have been deposited on your person.", funds );
                ch->gold += funds;
            }
        }
        else
            ch->gold += amount;
    }
    else
    {
        funds *= -1;

        if ( bank )
        {
            for ( BANK_DATA* acct = first_bank; acct; acct = acct->next )
            {
                if ( str_cmp( ch->name, acct->owner ) )
                    continue;

                acct_amt = acct->amount;
                acct->amount -= UMIN( funds, acct_amt );
                save_bank( acct, true );
                funds -= UMIN( funds, acct_amt );

                if ( funds <= 0 )
                    break;
            }
        }

        acct_amt = funds;
        funds -= UMIN( acct_amt, ch->gold );
        ch->gold -= UMIN( acct_amt, ch->gold );

        if ( funds > 0 )
            bug( "%s: trying to subtract %'d credits from character %s but was only able to subtract %'d", FUNC, amount, ch->name, amount - funds );
    }

    // Save the character so the credits stay modified.
    save_char_obj( ch, TRUE );
    return;
}


/*
    This system was added by Ghost of LOTJ =)
    It was written to check for the existence of players,
    even offline. This way, Players can place bounties
    on people offline. Fair?
*/
bool player_exist( const char* name )
{
    int rval;
    int cnt = 0;
    char where[MSL];

    snprintf( where, MSL, "name ILIKE %s AND living = 't'", sql_escape_string(name) );

    if ( ( rval = sql_count( DB_TABLE_PLAYERS, where , &cnt ) ) != E_LOTJ_SUCCESS ) {
        bug( "player_exist: error when trying to check db %d (%s)", rval, lotj_strerror(rval) );
        return false;
    }

    if ( cnt > 0 )
        return true;
    else
        return false;
}

/*
    Checks for the existence of dead players.
    This way, Players cannot use bounty as ability
    to tell if someone is alive or dead.
*/
bool player_existed( const char* name )
{
    int rval;
    int cnt = 0;
    char where[MSL];

    snprintf( where, MSL, "name ILIKE %s AND living = 'f'", sql_escape_string(name) );

    if ( ( rval = sql_count( DB_TABLE_PLAYERS, where , &cnt ) ) != E_LOTJ_SUCCESS ) {
        bug( "player_existed: error when trying to check db %d (%s)", rval, lotj_strerror(rval) );
        return false;
    }

    if ( cnt > 0 )
        return true;
    else
        return false;
}

time_t player_last_seen( const char* name )
{
    char query[MIL];
    snprintf( query, MIL, "SELECT updated_at FROM %s WHERE name ILIKE %s AND living = 't' LIMIT 1",
        DB_TABLE_PLAYERS, sql_escape_string( name ) );
    PGresult *qresult = query_db( query );

    if ( qresult == NULL )
    {
        bug( "failed to query db for player_last_seen" );
        return 0;
    }

    int rows = PQntuples( qresult );
    if ( rows == 0 )
    {
        if ( qresult ) PQclear( qresult );
        return 0;
    }

    time_t result = read_sql_long( qresult, 0, "updated_at" );
    PQclear( qresult );
    return result;
}

