/*
    Save a character and inventory.
    Would be cool to save NPC's too for quest purposes,
     some of the infrastructure is provided.
*/
void save_char_obj( CHAR_DATA* ch, bool queue )
{
    SHIP_DATA* ship = NULL;
    VEHICLE_DATA* vehicle = NULL;
    STRUCTURE_DATA* structure = NULL;
    DROID_DATA* droid = NULL;

    if ( !ch || char_extracted( ch ) )
        return;

    if ( IS_NPC( ch ) )
    {
        save_persistent_mob( ch, queue );
        return;
    }

    if ( NOT_AUTHED( ch ) || IS_SWITCHED( ch ) )
        return;

    if ( ( droid = droid_from_controller( ch->id ) ) != NULL )
        save_droid( droid, queue );

    if ( ch->skill_level[FORCE_ABILITY] >= 2 || ch->perm_frc > 0 )
        forcer_create( ch );

    if ( ch->desc && ch->desc->original )
        ch = ch->desc->original;

    if ( ch->in_room && ( ship = get_ship_from_room( ch->in_room ) ) != NULL )
    {
        ch->pcdata->location_type = CHAR_ON_SHIP;
        ch->pcdata->location_id = ship->id;
    }
    else if ( ch->in_room && ( vehicle = vehicle_from_room( ch->in_room->vnum ) ) != NULL )
    {
        ch->pcdata->location_type = CHAR_IN_VEHICLE;
        ch->pcdata->location_id = vehicle->id;
    }
    else if ( ch->in_room && ( structure = structure_from_room( ch->in_room->vnum ) ) != NULL )
    {
        ch->pcdata->location_type = CHAR_IN_STRUCTURE;
        ch->pcdata->location_id = structure->id;
    }
    else
    {
        ch->pcdata->location_type = CHAR_ON_GROUND;
        ch->pcdata->location_id = 0;
    }

    ch->total_int = get_curr_int( ch );
    ch->disguise_num = ( ch->disguise != NULL ) ? ch->disguise->id : 0;
    update_roster( ch );
    save_player( ch, queue );
    return;
}

