/*
    Based on last time modified, show when a player was last on  -Thoric
*/
CMDF do_last( CHAR_DATA* ch, char* argument )
{
    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &Clast <&wplayername&W/&w@accountname&C>" );
        return;
    }

    if ( argument[0] == '@' )
    {
        ACCOUNT_DATA* acc = get_account( argument + 1 );
        if ( acc )
        {
            if ( acc->level > get_trust( ch ) )
            {
                ch_println( ch, "Nice try" );
                return;
            }

            for ( ACC_CHAR* ach = acc->first_char; ach; ach = ach->next )
            {
                time_t ch_last = player_last_seen( ach->name );
                if ( ch_last > 0 )
                    ch_println( ch, "\n%s was last on: %s", ach->name, ctime( &ch_last ) );
            }
        }
        else
            ch_println( ch, "%s was not found.", argument );
        return;
    }

    time_t ch_last = player_last_seen( argument );
    if ( ch_last > 0 )
        ch_println( ch, "%s was last on: %s", argument, ctime( &ch_last ) );
    else
        ch_println( ch, "%s was not found.", argument );
}

bool password_matches_hash( const char* nonhashed, const char* hashed )
{
    if ( NULLSTR( nonhashed ) || NULLSTR( hashed ) )
    {
        return false;
    }

    if ( hashed[0] == '$' )
    {
        return !str_cmp( hashed, crypt( nonhashed, hashed ) );
    }
    else
    {
        return !str_cmp( hashed, handle_sha256( nonhashed ) );
    }
}
//https://stackoverflow.com/questions/14834209/how-to-simply-generate-a-random-base64-string-compatible-with-all-base64-encodin
static char* rand_string( char* str, size_t size )
{
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    if ( size )
    {
        --size;

        for ( size_t n = 0; n < size; n++ )
        {
            int key = rand() % ( int ) ( sizeof charset - 1 );
            str[n] = charset[key];
        }

        str[size] = '\0';
    }

    return str;
}

// generates a new hash, which includes generating a new salt
char* new_password( const char* nonhashed )
{
    char salt[19] = "$6$";
    rand_string( salt + 3, 16 );
    return crypt( nonhashed, salt );
}

CMDF do_mainchange( CHAR_DATA* ch, char* argument )
{
    int iClass;
    ACCOUNT_DATA* acc;
    ACC_CHAR* ach;

    if ( IS_NPC( ch ) )
        return;

    if ( ch->top_level >= 30 && !IS_IMMORTAL( ch ) )
    {
        ch_println( ch, "You are already at least level 30 and can no longer change your main class." );
        return;
    }

    if ( NULLSTR( argument ) )
    {
        ch_println( ch, "&zSyntax: &CMAINCHANGE <&wnew main class&C>" );
        ch_println( ch, "Type LEVEL for a list of main classes to change to. Please note that this may permanently affect your level maxes!" );
        return;
    }

    for ( iClass = 0; iClass < MAX_ABILITY; iClass++ )
    {
        if ( iClass == DIPLOMACY_ABILITY )
            continue;

        if ( !ch->desc->account || ( ch->desc->account && ch->desc->account->restclasses && !stristr( ch->desc->account->restclasses, flag_value_name( ability_name, iClass ) ) ) )
            if ( toupper( argument[0] ) == toupper( flag_value_name( ability_name, iClass )[0] )
                    &&   !str_prefix( argument, flag_value_name( ability_name, iClass ) ) )
            {
                if ( iClass == FORCE_ABILITY )
                {
                    ch_println( ch, "You cannot pick Force as your main class. Please choose another main class." );
                    return;
                }

                if ( iClass == HUNTING_ABILITY && ch->pcdata->clan && !xIS_SET( ch->pcdata->clan->flags, CLAN_BHCLAN ) )
                {
                    ch_println( ch, "You cannot be a bounty hunter in your current clan. RESIGN or pick a different main class." );
                    return;
                }

                if ( iClass == HUNTING_ABILITY && ch->skill_level[FORCE_ABILITY] > 1 )
                {
                    ch_println( ch, "You cannot be a bounty hunter when you have the Force." );
                    return;
                }

                ch->main_ability = iClass;

                for ( acc = first_account; acc; acc = acc->next )
                {
                    for ( ach = acc->first_char; ach; ach = ach->next )
                    {
                        if ( !str_cmp( ach->name, ch->name ) )
                        {
                            ach->main = ch->main_ability;
                            account_save( acc, true );
                        }
                    }
                }

                ch_println( ch, "You have changed your main class to %s.", flag_value_name( ability_name, iClass ) );

                if ( iClass == LEADERSHIP_ABILITY )
                    ch_println( ch, "You may now change your Leadership sub-class using LCLASSCHANGE <new leadership sub-class>." );

                break;
            }
    }

    int tmplevel = 0;

    for ( iClass = 0; iClass < MAX_ABILITY; iClass++ )
    {
        tmplevel = ch->skill_level[iClass];
        ch->skill_level[iClass] = 1;
        ch->skill_level[iClass] = URANGE( 1, tmplevel, max_level_flag( ch, iClass, TRUE ) );
        tmplevel = 0;
    }

    if ( !IS_IMMORTAL( ch ) )
    {
        for ( SKILL_DATA* skill = first_skill; skill; skill = skill->next )
        {
            if ( skill->min_level > ch->skill_level[skill->guild] )
                set_learned_pct( ch, skill, 0 );
        }
    }

    do_save( ch, "-noalert" );
    return;
}
