            {
                ch_println( ch, "You cannot pick Bounty Hunting as your sub-class. Please choose another sub-class." );
                return;
            }

            ch->pcdata->lclass = iClass;
            ch_println( ch, "You have changed your leadership sub-class to %s.", flag_value_name( ability_name, iClass ) );
            break;
        }
    }

    int tmplevel = 0;

    for ( iClass = 0; iClass < MAX_ABILITY; iClass++ )
    {
        tmplevel = ch->skill_level[iClass];
        ch->skill_level[iClass] = 1;
        ch->skill_level[iClass] = URANGE( 1, tmplevel, max_level( ch, iClass ) );
        tmplevel = 0;
    }

    do_save( ch, "-noalert" );
    return;
}

