int finalize_load_followers( CHAR_DATA* master )
{
    CHAR_DATA* follower = NULL, *nextfollower = NULL;

    if ( !master )
        return E_LOTJ_MISSING_ARGUMENTS;

    for ( follower = master->first_follower; follower; follower = nextfollower )
    {
        nextfollower = follower->next_follower;
        if ( finalize_load_npc( follower ) != E_LOTJ_SUCCESS )
        {
            bug( "%s: failed to load follower for %s", !IS_NPC( master ) ? master->name : master->short_descr );
            UNLINK( follower, master->first_follower, master->last_follower, next_follower, prev_follower );
            continue;
        }

        follower->master = master;
        follower->leader = master;
    }

    return E_LOTJ_SUCCESS;
}

int finalize_load_npc( CHAR_DATA* ch )
{
    ROOM_INDEX_DATA* room = NULL;

    if ( !ch )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( !IS_NPC( ch ) || !ch->pIndexData )
        return E_LOTJ_INVALID_ARGUMENTS;

    // Process inventories
    finalize_load_objects( &ch->first_carrying, &ch->last_carrying, (void*) ch, OBJ_IN_INVENTORY );

    // If the mob has followers, process 'em
    finalize_load_followers( ch );

    add_char( ch );
    ch->pIndexData->count++;
    nummobsloaded++;

    if ( !NULLSTR( ch->spec_funname ) )
        ch->spec_fun = what_spec( ch->spec_funname );
    else if ( ch->pIndexData && ch->pIndexData->spec_fun )
        ch->spec_fun = ch->pIndexData->spec_fun;
    else if ( ch->pIndexData && !NULLSTR( ch->pIndexData->spec_funname ) )
        ch->spec_fun = what_spec( ch->pIndexData->spec_funname );

    if ( !NULLSTR( ch->spec_funname_2 ) )
        ch->spec_2 = what_spec( ch->spec_funname_2 );
    else if ( ch->pIndexData && ch->pIndexData->spec_2 )
        ch->spec_2 = ch->pIndexData->spec_2;
    else if ( ch->pIndexData && !NULLSTR( ch->pIndexData->spec_funname_2 ) )
        ch->spec_2 = what_spec( ch->pIndexData->spec_funname_2 );

    if ( !NULLSTR( ch->spec_funname_3 ) )
        ch->spec_3 = what_spec( ch->spec_funname_3 );
    else if ( ch->pIndexData && ch->pIndexData->spec_3 )
        ch->spec_3 = ch->pIndexData->spec_3;
    else if ( ch->pIndexData && !NULLSTR( ch->pIndexData->spec_funname_3 ) )
        ch->spec_3 = what_spec( ch->pIndexData->spec_funname_3 );

    if ( !NULLSTR( ch->spec_funname_4 ) )
        ch->spec_4 = what_spec( ch->spec_funname_4 );
    else if ( ch->pIndexData && ch->pIndexData->spec_4 )
        ch->spec_4 = ch->pIndexData->spec_4;
    else if ( ch->pIndexData && !NULLSTR( ch->pIndexData->spec_funname_4 ) )
        ch->spec_4 = what_spec( ch->pIndexData->spec_funname_4 );

    if ( ch->variable == NULL )
        CREATE( ch->variable, VARIABLE_DATA, 1 );

    if ( ch->vars == NULL )
        CREATE( ch->vars, DVAR_LIST, 1 );

    room = ch->in_room;
    ch->in_room = NULL;
    char_to_room( ch, room );
    return E_LOTJ_SUCCESS;
}

int finalize_load_player( CHAR_DATA* ch )
{
    if ( !ch )
    {
        bug( "%s: missing ch", FUNC );
        return E_LOTJ_MISSING_ARGUMENTS;
    }

    if ( ch->variable == NULL )
    {
        VARIABLE_DATA* variable = NULL;
        CREATE( variable, VARIABLE_DATA, 1 );
        ch->variable = variable;
    }

    if ( !finalize_load_objects( &ch->first_carrying, &ch->last_carrying, (void*) ch, OBJ_IN_INVENTORY ) )
        bug( "%s: failed to finalize objects load for %s", FUNC, ch->name );
    finalize_load_followers( ch );
    fix_char( ch );
    fix_greets( ch );
    validate_char_sheet( ch );

    char buf[MSL];
    RESERVE_DATA* res = NULL;
    snprintf( buf, MSL, "Disguise name for %s", ch->name );

    for ( DISGUISE_DATA* disguise = ch->first_disguise; disguise; disguise = disguise->next )
    {
        // Retro-fix folks who named disguises after themselves
        if ( !str_cmp( disguise->disgname, ch->name ) || player_exist( disguise->disgname ) || player_existed( disguise->disgname ) || ( ( res = get_reserved( disguise->disgname ) ) != NULL && str_cmp( res->reason, buf ) ) )
        {
            ch_println( ch, "Warning: Your disguise named %s has a name that is now invalid. Please rename it.", disguise->disgname );
            SET_STRING( disguise->disgname, "Unset" );
            SET_STRING( disguise->title, "Unset" );
            SET_STRING( disguise->pubtitle, "" );
            disguise->saved = FALSE;
            if ( disguise->id == ch->disguise_num )
                ch->disguise_num = 0;            
            continue;
        }

        if ( !res )
            add_reserved( disguise->disgname, buf );

        if ( NULLSTR( disguise->title ) )
            SET_STRING( disguise->title, !NULLSTR( disguise->pubtitle ) ? disguise->pubtitle : disguise->disgname );

        if ( !disguise->pubtitle )
            SET_STRING( disguise->pubtitle, "" );

        if ( ch->disguise_num > 0 && disguise->id == ch->disguise_num )
            ch->disguise = disguise;
    }

    // Force knowing basic and racial language
    set_learned_pct( ch, cache_skill( "basic", &skill_basic ), 100 );
    const FLAG_INFO* language = ch->race ? flag_from_num(languages, ch->race->language) : NULL;
    if ( language )
    {
        SKILL_DATA* skill = language_table[language->flag];
        if ( skill )
            set_learned_pct( ch, skill, 100 );
    }

    ACCOUNT_DATA* acc = NULL;
    ACC_CHAR* ach = NULL;
    if ( !NULLSTR( ch->pcdata->account_name ) && ( acc = get_account( ch->pcdata->account_name ) ) != NULL )
    {
        ch->pcdata->account = acc;
        for ( ach = ch->pcdata->account->first_char; ach; ach = ach->next )
            if ( !str_cmp( ach->name, ch->name ) )
                break;

        if ( !ach )
            account_add_char( ch, acc, FALSE );
    }

    if ( ch->pcdata && !ch->pcdata->clan && ( ch->pcdata->clan = get_clan( ch->pcdata->clan_name ) ) == NULL )
    {
        if ( !NULLSTR( ch->pcdata->bestowments ) && !IS_IMMORTAL( ch ) )
            SET_STRING( ch->pcdata->bestowments, "" );

        if ( !NULLSTR( ch->pcdata->clan_name ) )
        {
            char hist_buf[MIL];
            snprintf( hist_buf, MIL, "Left %s (clan deleted)", ch->pcdata->clan_name );
            account_add_to_history( ch, ch->desc ? ch->desc->account : (ch->pcdata ? ch->pcdata->account : NULL), hist_buf );
            ch_println( ch, "Warning: %s no longer exists. Your affiliation has been cleared.", ch->pcdata->clan_name );
            SET_STRING( ch->pcdata->clan_name, "" );
        }
    }
    else
    {
        bool modified = false;
        if ( ch->pcdata && ch->pcdata->account )
        {
            for ( ach = ch->pcdata->account->first_char; ach; ach = ach->next )
            {
                if ( !str_cmp( ach->name, ch->name ) && !NULLSTR( ach->clan ) && str_cmp( ach->clan, ch->pcdata->clan->name ) )
                {
                    SET_STRING( ach->clan, ch->pcdata->clan->name );
                    modified = true;
                }
            }

            if ( modified )
                account_save( ch->pcdata->account, true );
        }
    }

    // Load lockers for the player only for their first login after each boot. If they've already had lockers loaded, don't load them again.
    load_lockers_sql( ch->id, LOCKER_PLR );

    if ( ch->pcdata && ( get_trust( ch ) >= LEVEL_ADMIN || is_name( "chan_debug", ch->pcdata->bestowments ) ) )
    {
        if ( !xIS_SET( ch->deaf, CHANNEL_DEBUG ) )
            xSET_BIT( ch->deaf, CHANNEL_DEBUG );

        if ( !xIS_SET( ch->deaf, CHANNEL_TUNE ) )
            xSET_BIT( ch->deaf, CHANNEL_TUNE );
    }

    return E_LOTJ_SUCCESS;
}

CHAR_DATA* load_player_sql( const char* name, int status )
{
    CHAR_DATA *ch = NULL;
    char selectquery[MSL * 2];
    PGresult *res = NULL;
    int rows = 0, row = 0, rval = 0;

    snprintf(selectquery, (MSL * 2), "SELECT * FROM players WHERE name ilike %s", sql_escape_string(name));
    if ( status != PLAYER_ALL )
        snprintf(selectquery + strlen(selectquery), (MSL * 2) - strlen(selectquery), " AND living = '%s'", status == PLAYER_LIVING ? "t" : "f");
    res = query_db(selectquery);
    rows = PQntuples(res);
    if ( res == NULL )
        return NULL;

    if ( rows == 0 )
    {
        if (res)
            PQclear(res);

        return NULL;
    }

    if ( rows > 1 )
        bug("%s: multiple matches for %s", FUNC, name );

    row = rows - 1; // Always pick the last (i.e., most recent) match
    CREATE( ch, CHAR_DATA, 1 );

    if ( ( rval = fieldmap_postgres_row( res, row, ch, char_fields ) ) != E_LOTJ_SUCCESS )
    {
        bug( "%s: failed to load player %s, err: %s", FUNC, name, lotj_strerror( rval ) );
        FREE_STRUCT_NORET( ch, char_fields );

        if (res)
            PQclear(res);

        return NULL;
    }

    if ( ch->variable == NULL )
    {
        VARIABLE_DATA* variable = NULL;
        CREATE( variable, VARIABLE_DATA, 1 );
        ch->variable = variable;
    }        

    if (res)
        PQclear(res);

    return ch;
}

int save_player( CHAR_DATA* ch, bool queue )
{
    if ( !ch )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( char_extracted( ch ) )
        return E_LOTJ_NOTHING_TO_DO;

    if ( IS_NPC( ch ) )
        return E_LOTJ_INVALID_ARGUMENTS;

    if ( queue && ch->id > 0 && sysdata.save_queues )
    {
        ch->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    ch->save_queued = FALSE;
    ch->save_time = current_time;
    return upsert_sql_fieldmap_row(DB_TABLE_PLAYERS, ch, char_fields, NO_FLAG);
}

int save_player_backup( CHAR_DATA* ch )
{
    int ch_id = 0, result = 0;

    if ( !ch || IS_NPC( ch ) )
        return 0;

    ch->pcdata->last_backup = time( 0 );
    ch_id = ch->id;
    ch->id = 0;
    result = upsert_sql_fieldmap_row(DB_TABLE_PLAYER_BACKUPS, ch, char_fields, FLAG_NO_UPSERT);
    ch->id = ch_id;
    return result;
}

int prune_player_backups( void )
{
    char query[MIL];
    long cutoff = current_time - ( 60 * 60 * 24 * 30 );
    snprintf( query, MIL, "updated_at < %ld", cutoff );
    return delete_sql_by_where( DB_TABLE_PLAYER_BACKUPS, query );
}

void do_save_all_players( CHAR_DATA* ch, UNUSED(char* argument) )
{
    int cnt = 0;
    CHAR_DATA* vch = NULL;

    IMM_CHECK( ch );

    for ( vch = first_char; vch; vch = vch->next )
    {       
        if ( IS_NPC( vch ) )
            continue;

        if ( save_player( vch, false ) )
            cnt++;
    }

    ch_println( ch, "&zSaved &C%d&z characters.", cnt );
    return;
}

int load_persistent_mob_sql( const PGresult* res, int row )
{
