    CREATE( ch, CHAR_DATA, 1 );
    int rval;
    if ( ( rval = fieldmap_postgres_row( res, row, ch, char_fields ) ) != E_LOTJ_SUCCESS )
    {
        bug("Failed to load persistent mob. Error: %d", rval );
        FREE_STRUCT( ch, char_fields );
        return rval;
