int save_persistent_mob( CHAR_DATA* ch, bool queue )
{
    DROID_DATA* droid = NULL;

    if ( !ch || char_extracted( ch ) || !IS_NPC( ch ) || !ch->pIndexData || !ch->in_room )
        return false;

    if ( ch->vendor_data )
        save_vendor( ch->vendor_data, TRUE );

    if ( ( droid = droid_from_mob( ch ) ) != NULL )
    {
        save_droid( droid, queue );
        return true;
    }
    else if ( !xIS_SET( ch->act, ACT_PERSISTENT ) )
        return false;

    // Don't save drones that are already following someone. This is handled separately.
    if ( xIS_SET( ch->act, ACT_MESSAGE_DRONE ) && ch->master )
        return false;

    if ( queue && ch->id > 0 && sysdata.save_queues )
    {
        ch->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    ch->save_queued = FALSE;
    ch->save_time = current_time;
    return upsert_sql_fieldmap_row(DB_TABLE_PERS_MOBS, ch, char_fields, NO_FLAG);
}

void save_persistent_mobs( bool queue )
{
    for ( CHAR_DATA* ch = first_char; ch; ch = ch->next )
    {
        if ( !IS_NPC( ch ) )
            continue;

        if ( ( !xIS_SET( ch->act, ACT_PERSISTENT ) || xIS_SET( ch->act, ACT_PROTOTYPE ) ) && !xIS_SET( ch->act, ACT_MESSAGE_DRONE ) )
            continue;

        // Don't save drones that are already following someone. This is handled separately.
        if ( xIS_SET( ch->act, ACT_MESSAGE_DRONE ) && ch->master )
            continue;

        save_persistent_mob( ch, queue );
    }

    return;
}

int load_persistent_object_sql( const PGresult* res, int row )
{
    OBJ_DATA *obj = NULL;
    CREATE( obj, OBJ_DATA, 1 );
    int rval;
    if ( ( rval = fieldmap_postgres_row( res, row, obj, obj_fields ) ) != E_LOTJ_SUCCESS )
    {
        bug("%s: failed to load persistent obj. Error: %d", FUNC, rval );
        FREE_STRUCT( obj, obj_fields );
        return rval;
    }

    if ( !obj->pIndexData || !obj->in_room )
    {
        bug("%s: failed to load persistent obj. Null %s", FUNC, !obj->pIndexData ? "index" : "room" );
        extract_obj( obj );
        return E_LOTJ_LOAD_ERROR;
    }

    if ( !finalize_load_obj( obj, (void*)obj->in_room, OBJ_IN_ROOM ) )
    {
        bug("%s: failed to finalize persistent obj." );
        extract_obj( obj );
        return E_LOTJ_LOAD_ERROR;
    }

    LINK( obj, obj->in_room->first_content, obj->in_room->last_content, next_content, prev_content );
    return E_LOTJ_SUCCESS;
}

int load_persistent_objects( void )
{
    boot_log("Loading persistent objects from DB.");
    return read_all_rows(DB_TABLE_PERS_OBJS, &load_persistent_object_sql, NULL);
}

int save_persistent_object( OBJ_DATA* obj, bool queue )
{
    if ( !obj )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( !obj->pIndexData )
        return E_LOTJ_INVALID_ARGUMENTS;

    if ( obj->extracted || obj->carried_by || obj->in_obj || !obj->in_room )
        return E_LOTJ_NOTHING_TO_DO;

    bool save = sysdata.persist_all_objects;
    if ( xIS_SET( obj->extra_flags, ITEM_PERSISTENT ) )
        save = true;
    else if ( if_equip_room( obj->in_room ) && !obj->fresh_reset )
        save = true;
    if ( !save )
        return E_LOTJ_NOTHING_TO_DO;

    if ( queue && obj->id > 0 && sysdata.save_queues )
    {
        obj->save_queued = TRUE;
        return E_LOTJ_SUCCESS;   
    }

    obj->save_queued = FALSE;
    return upsert_sql_fieldmap_row(DB_TABLE_PERS_OBJS, obj, obj_fields, NO_FLAG);
}

void do_savepersistentobjects( CHAR_DATA* ch, UNUSED(char* argument) )
{
    IMM_CHECK( ch );

    int rslt = save_persistent_objects( false );
    ch_println( ch, "&zSaved &C%d&z objects.", rslt );
    return;
}

int save_persistent_objects( bool queue )
{
    int cnt = 0;

    for ( OBJ_DATA* obj = first_object; obj; obj = obj->next )
    {
        if ( !obj->pIndexData )
            continue;

        // Objects carried by characters or inside another object get saved with that thing, not directly.
        if ( obj->carried_by || obj->in_obj || !obj->in_room )
            continue;

        if ( !sysdata.persist_all_objects && ( !xIS_SET( obj->extra_flags, ITEM_PERSISTENT ) && !if_equip_room( obj->in_room ) ) )
            continue;

        save_persistent_object( obj, queue );
        cnt += count_obj_contents( obj );
    }

    return cnt;
}

int ch_password_reset_email(CHAR_DATA *ch) {   
    int rval;
    char mail_body[MSL];
    int reset_code = number_range( 10000000, 99999999 );
    ACCOUNT_DATA *account;
    if(!ch) {
        return E_LOTJ_MISSING_ARGUMENTS;
    }
    if(!ch->pcdata->account){
        return E_LOTJ_ACCOUNT_NOT_FOUND;
    }
    account = ch->pcdata->account;
    if(account->emailconfirmed == 0 || NULLSTR(account->email)) {
        return E_LOTJ_ACCOUNT_NOT_CONFIRMED;
    }
    snprintf(mail_body, MSL, "Your temporary password for the character %s is %d, and you will have one hour to login with it and reset.", ch->name, reset_code );
    if ( ( rval = rpc_func_send_mail(NULL, account->email, "Legend of the Jedi - Password Reset",mail_body)) != E_LOTJ_SUCCESS ) {
        return rval;
    }
    time_t tms;
    tms = time( 0 );
    tms += 3600;
    ch->pcdata->resetpwd_date = tms;
    ch->pcdata->resetpwd = reset_code;
    save_char_obj( ch, true );
    lognormal( "Character password email sent for %s", ch->name );
    return E_LOTJ_SUCCESS;
}

int add_extract_queue( void* ptr, sh_int type )
{
    QUEUE_DATA* queue = NULL;

    if ( !ptr )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( type < 0 || type >= MAX_EXTRACT_TYPE )
    {
        bug( "%s: invalid extract type %d", FUNC, type );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    CREATE( queue, QUEUE_DATA, 1 );
    queue->ptr = ptr;
    queue->type = type;
    LINK( queue, first_queued_extract[type], last_queued_extract[type], next, prev );
    return E_LOTJ_SUCCESS;    
}

int remove_extract_queue( void* ptr, sh_int type )
{
    QUEUE_DATA* queue = NULL, *next_queue = NULL;

    if ( !ptr )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( type < 0 || type >= MAX_EXTRACT_TYPE )
    {
        bug( "%s: invalid extract type %d", FUNC, type );
        return E_LOTJ_INVALID_ARGUMENTS;
    }

    for ( queue = first_queued_extract[type]; queue; queue = next_queue )
    {
        next_queue = queue->next;
        if ( queue->ptr == ptr )
        {
            UNLINK( queue, first_queued_extract[type], last_queued_extract[type], next, prev );
            DISPOSE( queue );
        }
    }

    return E_LOTJ_SUCCESS;
}

/*
 * Create a deep fake descriptor that looks identical to a real one
 * Only the socket descriptor (-1) distinguishes it from real connections
 */
DESCRIPTOR_DATA* create_fake_descriptor( void )
{
    DESCRIPTOR_DATA* d = init_descriptor( -1 );

    d->connected     = CON_PLAYING; // Start in playing state
    d->outsize       = 2000;        // Standard buffer size
    d->is_fake_desc  = TRUE;

    d->pagesize      = 2000;
    CREATE( d->pagebuf, char, d->pagesize );
    d->pagecolor     = 7;

    SET_STRING( d->host, "fake_connection" );
    SET_STRING( d->hostip, "123.123.123.123" );
    SET_STRING( d->ip, "127.123.123.123" );

    // Initialize user tracking
    SET_STRING( d->user, "fake_user" );
#ifdef CLIENT
    SET_STRING( d->client, "[fake]" );
#endif

    // Debug logging to verify fake descriptor creation
    debug( "%s: Created fake descriptor with flag=%s, desc=%d", FUNC, d->is_fake_desc ? "TRUE" : "FALSE", d->descriptor );
    return d;
}

/*
 * Destroy a deep fake descriptor - uses same cleanup as real descriptors
 */
int destroy_fake_descriptor( DESCRIPTOR_DATA* d )
{
    if ( !d )
        return E_LOTJ_MISSING_ARGUMENTS;

    if ( !d->is_fake_desc )
        return E_LOTJ_INVALID_ARGUMENTS;

    if ( d->pProtocol )
        ProtocolDestroy( d->pProtocol );

    UNLINK( d, first_descriptor, last_descriptor, next, prev );        
    FREE_STRUCT( d, descriptor_fields );
    return E_LOTJ_SUCCESS;
}

/*
 * Unified loadup function that creates a character with a fake descriptor
 * This replaces the duplicate logic in lua_ch.c, cpr_game.c, and act_wiz.c
 */
CHAR_DATA* unified_loadup( const char* name, ACCOUNT_DATA* account, const char* totp_code, ROOM_INDEX_DATA* room )
{
    DESCRIPTOR_DATA* d = NULL;
    CHAR_DATA* ch = NULL;

    if ( NULLSTR( name ) )
    {
        bug( "%s: NULL or empty name", FUNC );
        return NULL;
    }

    // Check if player already loaded
    for ( CHAR_DATA* wch = first_char; wch; wch = wch->next )
    {
        if ( IS_NPC( wch ) )
            continue;

        if ( !str_cmp( name, wch->name ) )
        {
            bug( "%s: Player %s already loaded", FUNC, name );
            return NULL;
        }
    }

    // Check if player exists
    if ( !player_exist( name ) )
    {
        bug( "%s: Player %s does not exist", FUNC, name );
        return NULL;
    }

    // Verify TOTP if account and code provided
    if ( account && totp_code && !verify_account_totp( account, totp_code ) )
    {
        lognormal( "%s: Invalid totp code to loadup %s", FUNC, name );
        return NULL;
    }
    else if ( account && totp_code )
        lognormal( "%s: Valid totp code to loadup %s provided by account %s", FUNC, name, account->name );

    // Create temporary descriptor for loading
    d = create_fake_descriptor();

    // Load the character
    if ( !load_char_obj( d, name ) )
    {
        destroy_fake_descriptor( d );
        bug( "%s: Failed to load character %s", FUNC, name );
        return NULL;
    }

    ch = d->character;
    if ( !ch )
    {
        destroy_fake_descriptor( d );
        bug( "%s: load_char_obj succeeded but character %s is NULL", FUNC, name );
        return NULL;
    }

    ch->desc = d;
    ch->desc->character = ch;
    add_char( ch );

    // Check trust level restrictions
    if ( get_trust( ch ) > 100 &&  ( !account ||  ( account->level <= get_trust( ch ) &&  ( str_cmp( account->name, ch->name ) || account->level <= 101 ) ) ) )
    {
        do_say( ch, "Do *NOT* disturb me again!" );
        lognormal( "%s: refusing to loadup high-trust character %s", FUNC, ch->name );
        ch->desc = NULL;
        do_quit( ch, "" );
        destroy_fake_descriptor( d );
        return NULL;
    }

    // Set up room placement
    ch->retran = ch->room_num; // Save original room
    if ( room )
        char_to_room( ch, room );
    else
        char_to_room( ch, get_room_index( 1 ) ); // Default to room 1

    debug( "%s: character %s loaded successfully with fake descriptor", FUNC, ch->name );
    return ch;
}


