typedef enum
{
    SQUEUE_DODGE_ENERGY, SQUEUE_DODGE_LOCK,

    // The queue is sorted by type, from top to bottom in this list.
    // Ions go first. We want their damage to apply before physical damage.
    SQUEUE_ION_HIT, SQUEUE_ION_MISS,
    SQUEUE_ION_TURRET_HIT, SQUEUE_ION_TURRET_MISS,

    // Below here, ordering doesn't matter much, the damage is all treated the same.
    SQUEUE_TURBO_HIT, SQUEUE_TURBO_MISS,
    SQUEUE_LASER_HIT, SQUEUE_LASER_MISS,
    SQUEUE_AUTO_HIT, SQUEUE_AUTO_MISS,
    SQUEUE_TURBO_TURRET_HIT, SQUEUE_TURBO_TURRET_MISS,
    SQUEUE_LASER_TURRET_HIT, SQUEUE_LASER_TURRET_MISS,
    SQUEUE_AUTO_TURRET_HIT, SQUEUE_AUTO_TURRET_MISS,

    SQUEUE_VONG_NULLIFY_ENERGY, SQUEUE_YARETKOR_HIT, SQUEUE_YARETKOR_MISS,
    SQUEUE_YARETKOR_BLOCK,

    SQUEUE_MISSILE_HIT, SQUEUE_MISSILE_CHAFF, SQUEUE_VONG_NULLIFY_MISSILE,
    SQUEUE_TORPEDO_HIT, SQUEUE_TORPEDO_CHAFF, SQUEUE_VONG_NULLIFY_TORPEDO,
    SQUEUE_ROCKET_HIT, SQUEUE_ROCKET_CHAFF, SQUEUE_VONG_NULLIFY_ROCKET,
    SQUEUE_PULSE_HIT, SQUEUE_PULSE_CHAFF, SQUEUE_VONG_NULLIFY_PULSE,

    // Below here, projectile launches. We want to show them after all the spam.
    SQUEUE_MISSILE_LAUNCH, SQUEUE_TORPEDO_LAUNCH, SQUEUE_ROCKET_LAUNCH, SQUEUE_PULSE_LAUNCH,

    SQUEUE_MAX,
} squeue_type;

