/*
    Vehicle Weapons =)
*/
#define HEAVY_CANNON        0  /* Single Heavy Laser Cannon */
#define MEDIUM_CANNON       1  /* Single Medium Laser Cannon */
#define LIGHT_CANNON        2  /* Single Light Laser Cannon */
#define TWIN_HEAVY_CANNON   3  /* Double Heavy Laser Cannon */
#define TWIN_MEDIUM_CANNON  4  /* Double Medium Laser Cannon */
#define TWIN_LIGHT_CANNON   5  /* Double Light Laser Cannon */
#define GRENADE_LAUNCHER    6  /* Concussion-Grenade Launcher */
#define HARPOON_LAUNCHER    7  /* Harpoon Launcher - Snowspeeder */
#define MAX_WEAPONS         8

/*
    DISABLED - When the vehicle is 'disabled' or damaged
    OFF - Vehicle has not yet been 'started'
    READY - Vehicle is running and ready
    LAUNCH - Vehicle is a flying/hovering vehicle, and is launching.
    LAND - Vehicle is a flying/hovering vehicle, and is landing.
    WAITING_1 - Vehicle is 'busy'. Usage varys (Leads to Ready)
    WAITING_2 - Vehicle is 'busy'. Usage varys (Leads to Waiting_1)
*/
typedef enum
{
    VEHICLE_DISABLED = -1, VEHICLE_OFF = 0, VEHICLE_READY, VEHICLE_LAUNCH,
    VEHICLE_LAND, VEHICLE_WAITING_1, VEHICLE_WAITING_2, VEHICLE_FALLING
} vehicle_states;

/*
    Vehicle Sizes -
    SMALL VEHICLES can travel into any room, except indoors. (If theres no CAN_DRIVE set)
    MEDIUM VEHICLES can travel into any room except indoors.
    LARGE VEHICLES can only travel in CAN_DRIVE Flagged outdoor rooms.
*/
typedef enum { VEHICLE_SMALL, VEHICLE_MEDIUM, VEHICLE_LARGE } vehicle_sizes;

/*
    Vehicle Classes
    CLOUD_CAR    - Flying, Air Sectors Only.
    OCEAN_SHIP   - Water Sectors only.
    LAND_SPEEDER - Small and Fast, indoor travel. No weapons.
    LAND_CRAWLER - Huge, slow moving vehicle. Rolling jawa camp.
    WHEELED      - Juggernauts, Etc.
    WALKER       - Two or Four legged Walkers. ATs are the most common.
    BARGE        - Jabba's Sail Barge etc.
    // Ralen additions for an IC use of switchmode - https://starwars.fandom.com/wiki/Basilisk_war_droid/Legends
    BASILISK_GROUND - Basilisk War Droid, landed.
    BASILISK_AIR    - Basilisk War Droid, aerial.

*/
typedef enum
{
    CLOUD_CAR, OCEAN_SHIP, LAND_SPEEDER, LAND_CRAWLER, WHEELED, WALKER, BARGE, BASILISK_GROUND, BASILISK_AIR
} vehicle_classes;

