/* This is a "swiss army knife" buffer to support timed/channel commands.
   It can be safely expanded as needed to encompass different struct
   pointers that need to persist. Using the ch->first_buffer/last_buffer
   linked list with this struct eliminates the potential for overlap
   or one function overwriting another's buffer. - Nield 04/04/2024 */
struct buffer_data
{
    BUFFER_DATA*        next;
    BUFFER_DATA*        prev;
    int64_t             created; // Useful for tracking stray buffers that aren't eliminated properly by their functions
    CHAR_DATA*          ch; // The character to whom the buffer pertains (if any)
    char*               func; // Used as a sort of cheap-and-easy UID for the buffers, with some nice flexibility
    CHAR_DATA*          target;
    SHIP_DATA*          ship;
    SHIP_DATA*          shiptarget;
    STRUCTURE_REF*      structure;
    ROOM_INDEX_DATA*    room;
    EXIT_DATA*          exit;
    EXTRA_DESCR_DATA*   ed;
    CLAN_DATA*          clan;
    BUFFER_OBJ_REF*     _first_obj_ref; // Internal. Use add_obj_to_buffer and get_obj_from_buffer.
    BUFFER_OBJ_REF*     _last_obj_ref;
    OBJ_DATA*           obj; // A raw direct object reference. Use only for oset / other imm stuff
    char*               str1;
    char*               str2;
    int                 num1;
    int                 num2;
    int                 num3;
    long                long1;
    bool                bool1;
    bool                bool2;
    void*               buf1; // Void pointers. Use sparingly.
    void*               buf2; // Void pointers. Use sparingly.
};

